  Person tiernan "Prince Tiernan" at hm_study {
    Role "the Prince of Harrowmere, twenty-one". Ancestry human. Calling bard. Level 3. Peaceable. Pronouns he. Manner jovial.
    Greets "A tall, ink-stained, laughing young man in black, sitting on his desk with his boots on a chair. 'Ah,' says the Prince. 'My bodyguards. How sad for you. I am the least guardable man in the Margravate; ask anyone. I have been trying to be assassinated since the spring and the court is simply not up to it.'".
  }
  Person rolf "Margrave Rolf" at hm_hall {
    Role "the Margrave of Harrowmere, the Prince's uncle". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "The Margrave's chain is a size too tight on a large, easy man. 'My nephew,' says Rolf, 'is a wonderful boy. Keep the boy alive, there's a good fellow, and if you can make him a little less interesting, there is a purse in it. Do what you can.'".
  }
  Person iseult "Margravine Iseult" at hm_hall {
    Role "the Margrave's wife, the Prince's mother". Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Greets "Beauty, once, and now a decision to be still: the Margravine. 'You are to stand where he can see you,' she says. 'He does not do foolish things where he can see a witness. He does them to prove he is right.'".
  }
  Person fosbury "Chancellor Fosbury" at hm_hall {
    Role "the Chancellor". Ancestry human. Peaceable. Pronouns he. Manner proud.
    Greets "A little man in a big furred gown who keeps a notebook open on his forearm. 'I have been the Chancellor of three Margraves,' he says, 'and this is the first time one of them has been dead and sitting down. I will pay you thirty pieces. Keep him off the roof.'".
  }
  Person ysenne "Ysenne Fosbury" at hm_chapel {
    Role "the Chancellor's daughter". Ancestry human. Peaceable. Pronouns she. Manner cheerful.
    Greets "At the altar rail a girl of nineteen has stopped praying to look at you. 'He says things,' she says, 'that sound like jokes and are not.'".
  }
  Person spargo "Sir Dunmow Spargo" at hm_hall {
    Role "a young courtier of the Prince's, his friend". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "Fair, anxious, smiling, with a new sword he keeps touching: a young man. 'The Prince's friend,' he says. 'Dunmow. I am to go with him wherever he goes, which is the one thing, I think, that frightens me.'".
  }
  Person quillan "Sir Cullen Quillan" at hm_hall {
    Role "a courtier, the Prince's friend". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "A dark young man who watches you without moving his head. 'Cullen,' he says. 'I am the other.'".
  }
  Person captain "Captain Fenn Darrow" at hm_yard {
    Role "a drunk captain of the guard". Ancestry human. Calling warrior. Level 2. Peaceable. Pronouns he. Manner jovial.
    Greets "'The Prince!' says Captain Darrow, who is holding two foils and has not noticed. 'Tell the Prince from me, he fences like a poet. I'll fence him like a pig.'".
  }
  Person berengar "Margravine Aldith" at or_hall {
    Role "the Margravine of Orlay". Ancestry human. Peaceable. Pronouns she. Manner compassionate.
    Greets "Over a pile of letters, from a large chair, a small old woman looks at you. 'From Rolf,' she says, tapping the pile. 'Does he think I read these? Sit. You look as if you've been walking.'".
  }

  // The commission: the Chancellor engages the company.
  Topic fosbury_job with fosbury "Ask the Chancellor what he wants of the company" when true once {
    Says "'Of the Players: a play, the Margrave has asked it, and it will be good for the court's appearance. Of you: that you keep the Prince alive.' He closes the notebook. 'He goes to the south rampart at midnight to speak to what is not there. He fences the captains for money. He prays, and then does not do what he went to the chapel to do. He says he is going to prove a point. I do not know what the point is. The point is a number of people at present, and the Margrave is one of them.'".
    On discuss { Assert e3On(rierdan). Set e3Start(rierdan) to watch(clock). }
  }

  // Swale is sent for: the Prince has written a speech and wants it said by a professional. He comes up from the Wend in the Chancellor's cart.
  Rule e3_swale when e3On(rierdan) and not e3Done(rierdan) and at(party, hm_hall) and troupe(swale) and not at(swale, hm_hall) and at(swale, ?sw) { Retract at(swale, ?sw). Assert at(swale, hm_hall). }
  Observe e3_swale_told at hm_hall when e3On(rierdan) and troupe(swale) and not e3Done(rierdan) "Ambrose Swale has been fetched up from the Fourways in the Chancellor's cart, with his make-up box on his knee, looking as if he had been asked to criticise a ghost.".

  // The Prince is hard to guard. Three exploits, each with a counter, each costing him a harm if the company is absent.
  Rule rp_x1 when e3On(rierdan) and not x1(rierdan) and (hour(clock) >= 23 or hour(clock) < 4) and watch(clock) >= e3Start(rierdan) + 12 {
    Assert x1(rierdan). Set e3X1At(rierdan) to watch(clock). Retract at(tiernan, hm_study). Assert at(tiernan, hm_rampart). }
  Rule rp_x1h when x1(rierdan) and not x1c(rierdan) and watch(clock) >= e3X1At(rierdan) + 6 {
    Assert x1c(rierdan). Increase harm(rierdan) by 1. Retract at(tiernan, hm_rampart). Assert at(tiernan, hm_study). }
  Rule rp_x2 when x1c(rierdan) and not x2(rierdan) and hour(clock) >= 9 and hour(clock) < 17 and watch(clock) >= e3X1At(rierdan) + 18 and at(tiernan, ?q) {
    Assert x2(rierdan). Set e3X2At(rierdan) to watch(clock). Retract at(tiernan, ?q). Assert at(tiernan, hm_yard). }
  Rule rp_x2h when x2(rierdan) and not x2c(rierdan) and watch(clock) >= e3X2At(rierdan) + 6 {
    Assert x2c(rierdan). Increase harm(rierdan) by 1. Retract at(tiernan, hm_yard). Assert at(tiernan, hm_study). }
  Rule rp_x3 when x2c(rierdan) and not x3(rierdan) and hour(clock) >= 17 and hour(clock) < 22 and watch(clock) >= e3X2At(rierdan) + 12 and at(tiernan, ?q) {
    Assert x3(rierdan). Set e3X3At(rierdan) to watch(clock). Retract at(tiernan, ?q). Assert at(tiernan, hm_chapel). Assert at(rolf, hm_chapel). }
  Rule rp_x3h when x3(rierdan) and not x3c(rierdan) and watch(clock) >= e3X3At(rierdan) + 6 {
    Assert x3c(rierdan). Increase harm(rierdan) by 1. Retract at(tiernan, hm_chapel). Assert at(tiernan, hm_study). Retract at(rolf, hm_chapel). Assert at(rolf, hm_hall). }
  Observe x1_told near tiernan when x1(rierdan) and at(tiernan, hm_rampart) "The Prince stands at the third merlon in the dark with his sword out, talking at the air in a voice he has plainly rehearsed. A cold comes up off the stones. Beyond him the orchard glows, faintly, white.".
  Observe x2_told near captain when x2(rierdan) and at(tiernan, hm_yard) and not x2c(rierdan) "The Prince has two foils and a bet of fifty crowns that he can touch the captain before the captain touches him. The captain is much the bigger. He is also drunk, but has not been told that this is the wrong kind.".
  Observe x3_told near tiernan when x3(rierdan) and at(tiernan, hm_chapel) and not x3c(rierdan) "The Margrave kneels at the rail with his back to the room. Behind him the Prince has drawn his sword. He has not moved. He is breathing hard, as if from a long stair.".

  // The counters.
  Action stand_by_prince(actor: group, site: place) "Stand beside the Prince on the rampart and say nothing" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hm_rampart) and at(tiernan, hm_rampart) and x1(rierdan) and not x1c(rierdan).
    Time 2.
    On success { Assert x1c(rierdan). Assert tiernanTrust(actor). Assert e3Ghost(actor). }
    Result "You stand a pace behind his elbow. At last he says, without turning, 'You are the first person who has stayed. Everyone else announces they are going to stay, and then does.' The cold place stirs, and takes the shape of an old man with an apple in his hand. It looks past you. It says one sentence to the Prince, who has gone white, and you do not hear it. The cold place goes quiet. When he turns his face is wet and he is grinning. 'I'll need you for the chapel,' he says. 'I mean to behave badly.'".
  }
  Action disarm_captain(actor: group, site: place) "Step between the Prince and the captain, and take the captain's foil" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hm_yard) and x2(rierdan) and not x2c(rierdan) and not f_capt(rierdan).
    Time 1.
    Resolve check(actor, tumbling, dc_fair).
    On success { Assert x2c(rierdan). }
    On failure { Assert f_capt(rierdan). Assert x2c(rierdan). Increase harm(rierdan) by 1. }
    Result "You come in under the captain's arm and the foil is in your hand before either of them has finished the sentence. The captain looks at his empty fingers with deep sorrow. 'I let him have that,' he says. The Prince applauds, once, and says 'Not bad. Not bad at all, for a bodyguard,' and walks off in a better mood than he arrived in.".
    Otherwise "The captain's foil takes you across the ribs in a way that was meant for the Prince. It is blunt. It is a lot of foil.".
  }
  Rule rp_rolf_home when x3c(rierdan) and at(rolf, hm_chapel) { Retract at(rolf, hm_chapel). Assert at(rolf, hm_hall). }
  Rule rp_confess when x3(rierdan) and e3Trap(rierdan) and not x3c(rierdan) { Assert x3c(rierdan). Assert e3Confessed(rierdan). }
  Observe e3_confess_told at hm_chapel when e3Confessed(rierdan) "The Margrave does not pray. He kneels with his hands open and his mouth working, and says to the stone Margrave on the tomb, aloud, clearly: 'I cannot. Brother, I cannot.' Behind him the Prince's sword comes down by itself, an inch at a time, and the Prince sits on the floor of the chapel with his hand over his face.".
  Action stop_chapel(actor: group, site: place) "Take the Prince by the sleeve before he does it" {
    Speaker tiernan.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hm_chapel) and x3(rierdan) and not x3c(rierdan) and not e3Trap(rierdan).
    Time 0.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert x3c(rierdan). Assert e3Spared(rierdan). }
    On failure { Assert x3c(rierdan). Increase harm(rierdan) by 1. }
    Result "'He is at his prayers,' you whisper. 'If you kill him now he goes to the gods clean.' The Prince stares at you. His mouth works. 'You have heard the same story,' he says, with great bitterness, and lowers the sword. 'I'll wait,' he says, 'until he is doing something thoroughly damnable. A man should be caught at his best sin.'".
    Otherwise "'Let go,' says the Prince, in a voice you have not heard. He throws off your hand and goes in with the sword up, and Sir Cullen Quillan, who was in the porch, knocks the blade down and cuts the Prince across the forearm with his own. The Margrave turns on his knees and sees the blood and his nephew's face, and his mouth shuts.".
  }

  Topic tiernan_ghost with tiernan "Ask the Prince what the cold place said to him" when e3Ghost(party) and not e3Orchard(rierdan) once {
    Says "'Orchard,' says the Prince. 'It said, my son, the orchard.' He looks at the skull. 'My father slept in the orchard after dinner, every day of his life. They told me it was a snake. My uncle was the first to find him.' He is still. 'I have only a word. A word is not a proof.'".
    On discuss { Assert e3Orchard(rierdan). }
  }
  Observe tiernan_dark near tiernan when e3On(rierdan) and not x1(rierdan) and not e3Done(rierdan) "When you come in the Prince is sitting at his desk in the dark with the skull in his two hands, still. Then he sees you, and the room is full of his laugh again, as if somebody had lit a lamp.".

  // The players' trap: Swale speaks a murder in an orchard, and the Margrave is watched while he hears it.
  Action set_trap(actor: group, site: place) "Have Swale work a speech about a king killed in an orchard into the Prince's play, and watch the Margrave hear it" {
    Speaker swale.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hm_hall) and at(swale, site) and e3Orchard(rierdan) and not e3Trap(rierdan) and not e3Fumbled(rierdan) and not x3(rierdan).
    Time 1.
    Resolve check(actor, performance, dc_fair).
    On success { Assert e3Trap(rierdan). }
    On failure { Assert e3Fumbled(rierdan). Increase harm(rierdan) by 1. }
    Result "Swale gives it in the Prince's own lines, to the hall, in a flat reading voice: a sleeper in an orchard, a poured cup, a brother. The Margrave takes his chain in both hands. He does not move. He asks for wine, and does not drink it, and goes out. The Prince, at the back, is breathing hard and has not looked at you once.".
    Otherwise "Swale begins well and then, from habit, adds an ornament. The Margrave smiles at it: a verse is a verse. The Prince, in the corner, closes his eyes.".
  }
  Observe spies_scene near quillan when x1c(rierdan) and not e3Done(rierdan) and not e3Spies(rierdan) "Sir Cullen Quillan is at the Prince's desk turning over the Prince's papers. He puts them down gently when you look, and goes on being agreeable.".
  Action watch_friends(actor: group, site: place) "Watch the Prince's two friends: where they go when he is not looking" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hm_hall) and e3On(rierdan) and not e3Watched(actor) and not e3Spies(rierdan).
    Time 2.
    Resolve check(actor, insight, dc_fair).
    On success { Assert e3Watched(actor). Assert e3Spies(rierdan). }
    On failure { Assert e3Watched(actor). }
    Result "Sir Dunmow Spargo goes to the Margrave's door every evening with a small, scrupulous face, and stays a quarter of an hour. Sir Cullen Quillan waits in the passage. They are the Prince's friends; they are also, plainly, the Margrave's ears, and neither of them thinks the less of himself for it.".
    Otherwise "They are friendly, and talk of hawks. You learn that Dunmow is afraid of horses.".
  }

  // The Prince asks the company things; the answers are remembered at the road and at the match.
  Topic tiernan_ask with tiernan "Ask the Prince why he talks to the rampart" when e3On(rierdan) and at(tiernan, hm_study) once {
    Says "'Because it answers,' says the Prince. He sits up. 'Here is a thing to be honest about, because otherwise there is no fun in it. If you knew your father had been murdered, and you could not prove it, and the man who did it was kind to you at supper: what would you do?'".
  }
  Topic tiernan_a1 with tiernan "Wait, and watch, and be sure" answering tiernan_ask when true {
    Says "'Sensible,' says the Prince, with enormous disappointment. 'I was afraid you would say that. It is what everyone says. It is what I have been doing for six months.' He looks at the skull. 'It is dreadful.'".
    On discuss { Assert tiernanScorn(actor). }
  }
  Topic tiernan_a2 with tiernan "Make him show it: a play, a trap, a trick" answering tiernan_ask when true {
    Says "The Prince leaps off the desk. 'THAT,' he says. 'Yes. A play. I had a play in mind and could not decide who to trust to put on a play.' He grabs your hands. 'You are the Players! You are the PLAYERS!' His face falls. 'Oh. I have done it again. I have given a plan to the person who is hired to stop me.'".
    On discuss { Assert tiernanTrust(actor). }
  }
  Topic tiernan_a3 with tiernan "Leave. Go somewhere he cannot be kind to you at supper" answering tiernan_ask when true {
    Says "The Prince is silent. 'That,' he says at last, 'is the one I could not do. Not because I am brave. Because I do not know where I would be if I were not here.' He glances at the skull. 'Everyone thinks I stay for revenge. I stay because I haven't got anywhere else I am a prince.'".
    On discuss { Assert tiernanLonely(actor). }
  }
  Topic swale_prince with swale "Ask Swale to speak the Prince's lines to him as a player would" when e3On(rierdan) and at(swale, hm_hall) once {
    Says "Swale rolls up a sleeve. 'The Prince has written a speech,' he says, 'and asked that I show him how to say it.' He turns to the empty hall. 'To be or not to be,' he begins, and stops. 'No. He writes better than that. It is, I regret to say, better.' He looks at you, stricken. 'Do I tell him it wants cutting?'".
  }
  Topic swale_cut with swale "Tell him it wants no cutting; he is the better writer" answering swale_prince when true {
    Says "Swale sits down heavily. 'Yes,' he says. 'Thank you.' For the first time he looks at a younger writer without malice.".
    On discuss { Assert swaleHand(actor). }
  }
  Topic swale_vain with swale "Tell him it wants cutting, and cut it" answering swale_prince when true {
    Says "'Of course,' says Swale, happily, and goes off to cut the Prince's best line to ribbons, which the Prince will not forgive.".
    On discuss { Assert swaleVain(actor). }
  }

  // The letter.
  Kind rolf_letter "the Margrave's letter to Orlay" is document teaching letter_read described "A single folded sheet, sealed with the Margrave's own signet in green wax, addressed in the Chancellor's fair hand: To my good neighbour the Margravine of Orlay, by the hand of the Players and my nephew.".
  Discovery letter_read "The Margrave's letter, read: 'Dear neighbour, receive the bearers kindly and see to it that none of them is alive by the end of the week, beginning with my nephew. R.'".
  Rule rp_letter when x3c(rierdan) and not e3Letter(rierdan) and harm(rierdan) < 3 and watch(clock) >= e3X3At(rierdan) + 12 {
    Assert e3Letter(rierdan). Give rolf_letter to party. Assert at(tiernan, hm_hall). Assert at(spargo, hm_hall). Assert at(quillan, hm_hall). }
  Observe letter_told at hm_hall when e3Letter(rierdan) and not e3Done(rierdan) "The Margrave has given the company a sealed letter for Orlay, 'a courtesy,' and sent his nephew along for his health. Sir Dunmow Spargo and Sir Cullen Quillan are to go as well, to see the Prince comfortable, with a smaller packet of their own. Nobody looks at the Chancellor, who is looking at the floor.".

  Action read_letter(actor: group, site: place) "Warm the seal over a candle and read the Margrave's letter" {
    Requires able(actor) and company(actor) and at(actor, site) and e3Letter(rierdan) and holding(actor, rolf_letter) and not e3ReadTried(rierdan).
    Time 3.
    Resolve check(actor, trapwork, dc_fair).
    On success { Assert e3Read(rierdan). Assert e3ReadTried(rierdan). Assert knows(actor, letter_read). }
    On failure { Assert e3Cracked(rierdan). Assert e3ReadTried(rierdan). Decrease quantity(actor, gold) by 3 or to nothing. }
    Result "The wax lifts in one piece, the way it does when the man who sealed it did not expect it to be lifted. The letter is a courteous page of the Margrave's best phrases, and in the middle of it, between a remark on the weather and one on the price of wool, it asks that its bearers be killed. It does so in the voice of a man ordering a fish.".
    Otherwise "The wax cracks across the signet. You hold it over the candle until it runs, and press it shut with the flat of a knife, and the Margrave's seal now has a seam in it that a child could see. You did not learn what it said, and the cook who lent the candle is owed three crowns for forgetting that he did.".
  }
  Kind second_sheet "a sheet of the Prince's good paper" is document described "A clean sheet of the Prince's cream paper, with his crest in the corner and a chewed quill-mark.".
  Action take_sheet(actor: group, site: place) "Take a clean sheet of the Prince's paper from his desk" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hm_study) and e3Letter(rierdan) and not holding(actor, second_sheet) and not e3Forged(rierdan) and not e3SheetTaken(rierdan).
    Time 0.
    On success { Give second_sheet to actor. Assert e3SheetTaken(rierdan). }
    Result "The Prince watches you take it. After a moment he pushes the ink an inch toward you.".
  }
  Action tell_prince_letter(actor: group, site: place) "Tell the Prince what his uncle's letter says, and what you might do with it" {
    Speaker tiernan.
    Requires able(actor) and company(actor) and at(actor, site) and at(tiernan, site) and e3Read(rierdan) and not e3PrinceKnows(rierdan).
    Time 0.
    On success { Assert e3PrinceKnows(rierdan). }
    Result "He reads it over your arm. 'Ask for them,' he says, evenly. 'Dunmow and Cullen. If it must be somebody's name, let it be somebody I know.' He gives a short laugh. 'Do not tell me it is not what you meant.'".
  }
  Action forge_letter(actor: group, site: place) "Ask Swale to write a new letter in the Margrave's hand, in place of the old" {
    Speaker swale.
    Requires able(actor) and company(actor) and at(actor, site) and e3Read(rierdan) and e3PrinceKnows(rierdan) and holding(actor, second_sheet) and at(swale, site) and not e3Forged(rierdan) and not e3Burned(rierdan).
    Time 3.
    Resolve check(actor, performance, dc_fair).
    On success { Assert e3Forged(rierdan). Spend second_sheet from actor. }
    On failure { Spend second_sheet from actor. }
    Result "Swale takes the seal, a pen and a scruple of the Margrave's best ink, and for twenty minutes is not an actor but a clerk. The new letter asks the Margravine of Orlay, with the Margrave's compliments, to receive Sir Dunmow Spargo and Sir Cullen Quillan kindly, and to see that they are not alive at the end of the week. He signs it with a flourish. 'Why,' he says, 'that is the best part I have had since Lear.'".
    Otherwise "'Oh,' says Swale, looking at his work, 'oh dear. That is the Duke of Pentrice's hand. I was thinking of someone else.' The sheet is spoiled.". 
  }
  Topic ysenne_letter with ysenne "Ask Ysenne Fosbury what her father has been copying" when e3Letter(rierdan) and not e3Done(rierdan) once {
    Says "Ysenne looks at the altar rail and not at you. 'He copies the Margrave's letters,' she says. 'He copied one for Orlay on Thursday and did not sleep. He kept saying it was a courtesy, and that a courtesy is whatever the man who sealed it says it is.' She twists a thread from her sleeve. 'Do not let anyone carry it who cannot read.'".
    On discuss { Assert e3Warned(rierdan). }
  }
  Action burn_letter(actor: group, site: place) "Burn the Margrave's letter in the nearest hearth" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, hm_inn) or at(actor, hm_hall)) and e3Letter(rierdan) and (e3Read(rierdan) or e3Warned(rierdan)) and holding(actor, rolf_letter) and not e3Burned(rierdan) and not e3Forged(rierdan).
    Time 2.
    On success { Assert e3Burned(rierdan). Spend rolf_letter from actor. }
    Result "It goes up in a small bright flower. The Prince, who is watching, applauds. 'Beautifully done. A little late, but the form was perfect.'".
  }
  Action seal_letter_away(actor: group, site: place) "Wrap the letter in oilskin and keep it on your own person" {
    Requires able(actor) and company(actor) and at(actor, site) and e3Letter(rierdan) and holding(actor, rolf_letter) and not e3Kept(rierdan) and not e3Mixed(rierdan).
    Time 1.
    On success { Assert e3Kept(rierdan). }
    Result "You wrap it in oilskin and tie it about your waist under your coat. Pudding, who has been carrying every other parcel for a week, looks briefly relieved and then cross.".
  }
  Relation e3MixRolled(place).
  Rule rp_mix when e3Letter(rierdan) and at(party, hm_inn) and not e3MixRolled(rierdan) and not e3Mixed(rierdan) and not e3Kept(rierdan) and not e3Burned(rierdan) and not e3Forged(rierdan) and hour(clock) >= 5 and hour(clock) < 9 and dice(clock) <= 10 {
    Assert e3MixRolled(rierdan). Assert e3Mixed(rierdan). Spend rolf_letter from party. }
  Rule rp_mix_safe when e3Letter(rierdan) and at(party, hm_inn) and not e3MixRolled(rierdan) and not e3Mixed(rierdan) and hour(clock) >= 5 and hour(clock) < 9 and dice(clock) > 10 { Assert e3MixRolled(rierdan). }
  Observe e3_mix_told at hm_inn when e3Mixed(rierdan) and not e3Done(rierdan) "In the grey of the morning Jem Pudding picks up every parcel in the room, humming, and puts them in the Orlay basket. The Margrave's letter is among them. So is Hepzibah's laundry list. And a love-poem of Kit's, the one he did not mean anyone to read. By the time anyone counts, the basket is on a carrier's cart and the cart is on the road.".
  Observe e3_mix_safe_told at hm_inn when e3MixRolled(rierdan) and not e3Mixed(rierdan) and not e3Done(rierdan) "In the grey of the morning Jem Pudding goes round the room with the Orlay basket, humming, and gathers every parcel but the one you are sitting on.".
  Hazard road_cutpurse "The Orlay road at night" means "Deal (1d6) physical damage to ally unless dexterity save against (12).".
  Rule rp_road_night at hm_road when e3Letter(rierdan) and at(party, hm_road) and not e3Robbed(rierdan) and (hour(clock) >= 21 or hour(clock) < 5) and dice(clock) <= 9
    says "Two men step out of the hedge with the sort of cudgels that are carried for effect, and mean it." {
    Assert e3Robbed(rierdan). Assert strikes(road_cutpurse, party). }
  Relation e3Robbed(place).
  Rule rp_to_orlay when e3Letter(rierdan) and at(party, or_gate) and not e3PrinceAlong(rierdan) { Assert e3PrinceAlong(rierdan). Assert at(tiernan, or_gate). Assert at(spargo, or_gate). Assert at(quillan, or_gate). }

  // At Orlay: what the Margravine does with what she is handed. Five shapes of arrival.
  Action confront_margrave(actor: group, site: place) "Lay the Margrave's own letter, sealed, on the table before him in front of the court" {
    Speaker rolf.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hm_hall) and at(rolf, hm_hall) and e3Read(rierdan) and e3Kept(rierdan) and holding(actor, rolf_letter) and not e3Done(rierdan) and not f_conf(rierdan).
    Time 1.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert e3Exposed(rierdan). Assert e3Done(rierdan). Spend rolf_letter from actor. }
    On failure { Assert f_conf(rierdan). Assert e3Dismissed(rierdan). Assert e3Done(rierdan). }
    Result "You lay it down, sealed, with his own signet on it, and say what it asks, and of whom. The court has stopped breathing. The Margrave looks at the green wax for a long moment, and then at his nephew, and takes it up and puts it in the fire himself. 'It is a courtesy,' he says, 'that was not meant.' Nobody in the hall will say what it was meant for. He sends the Prince to his mother, and goes out.".
    Otherwise "'My seal,' says the Margrave, pleasantly, 'on a thing you were not to open. You have been diligent.' He takes it from you. The court watches the company go out of the hall; by morning the company's wagon is on the road with a guard beside it.".
  }
  Observe e3_exposed_told near rolf when e3Exposed(rierdan) "The Margrave has not come out of his rooms. The Chancellor says the court is in mourning for something it cannot name, and has paid the company in full, in advance, to be gone by dawn.".
  Observe e3_dismissed_told at hm_hall when e3Dismissed(rierdan) "The hall is cold and the Prince is not in it. The Chancellor will not meet your eye as he counts out the fee.".
  Action present_forged_letter(actor: group, site: place) "Hand the Margravine of Orlay the letter that Swale wrote" {
    Speaker berengar.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, or_hall) and at(berengar, or_hall) and e3Forged(rierdan) and not e3Delivered(rierdan) and not e3Misdelivered(rierdan).
    Time 0.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert e3Delivered(rierdan). Spend rolf_letter from actor. }
    On failure { Assert e3Delivered(rierdan). Assert e3ForgeBlown(rierdan). Spend rolf_letter from actor. }
    Result "The Margravine reads it twice. You stand straight and look like people who have been sent with a letter.".
    Otherwise "She reads it, and then holds the signature against a letter of the Margrave's she keeps in her sleeve. The two hands do not agree about the loop of an R.".
  }
  Action present_letter(actor: group, site: place) "Hand the Margravine of Orlay the letter you were given" {
    Speaker berengar.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, or_hall) and at(berengar, or_hall) and e3Letter(rierdan) and holding(actor, rolf_letter) and not e3Forged(rierdan) and not e3Mixed(rierdan) and not e3Delivered(rierdan) and not e3Misdelivered(rierdan) and not e3Burned(rierdan).
    Time 0.
    On success { Assert e3Delivered(rierdan). Spend rolf_letter from actor. }
    Result "The Margravine reads it twice, with her lips moving. She looks up. Her face does not alter. 'Leave it with me,' she says.".
  }
  Action present_the_basket(actor: group, site: place) "Present what the carrier brings: the basket of parcels" {
    Speaker berengar.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, or_hall) and at(berengar, or_hall) and e3Mixed(rierdan) and not e3Delivered(rierdan) and not e3Misdelivered(rierdan).
    Time 0.
    On success { Assert e3Misdelivered(rierdan). Assert e3Done(rierdan). }
    Result "The Margravine opens the first parcel and reads the laundry list, and the second and reads Kit's love-poem aloud, with feeling, and the third. 'My neighbour,' she says, 'has written me the most remarkable letter of my life. I do not understand a word of it, but I think I am being courted.' She sends a ham.".
  }
  Rule rp_orlay_cracked when e3Delivered(rierdan) and not e3Forged(rierdan) and e3Cracked(rierdan) and not e3Done(rierdan) { Assert e3Escape(rierdan). Assert e3Done(rierdan). Assert e3CrackedSaved(rierdan). Assert e3Held(rierdan). Assert at(tiernan, or_hall). }
  Rule rp_orlay_forged when e3Delivered(rierdan) and e3Forged(rierdan) and not e3ForgeBlown(rierdan) and not e3Done(rierdan) { Assert e3Escape(rierdan). Assert e3Done(rierdan). Assert e3Seized(rierdan). Assert e3Killed(rierdan). }
  Rule rp_orlay_blown when e3Delivered(rierdan) and e3ForgeBlown(rierdan) and not e3Done(rierdan) { Assert e3Bellerophon(rierdan). Assert e3Done(rierdan). }
  Rule rp_orlay_genuine when e3Delivered(rierdan) and not e3Forged(rierdan) and not e3Cracked(rierdan) and not e3Done(rierdan) { Assert e3Bellerophon(rierdan). Assert e3Done(rierdan). }
  Relation e3CrackedSaved(place).
  Observe e3_held_told at or_hall when e3Held(rierdan) "The Prince is staying. The Margravine has not made it a threat: he will be her guest until the Margrave his uncle has sent to ask for him, and nobody expects the Margrave to ask. The company is free to go. The Prince walks you to the gate and stands in it for a little.".
  Observe e3_cracked_told at or_hall when e3CrackedSaved(rierdan) "The Margravine turns the sheet over and sees the seam in the seal. She turns it in the light. 'This has been opened,' she says, 'and closed by somebody who does not do it for a living.' She does not ask what it said. 'I should not like to have to act on a letter I cannot swear to. Go out by the kitchen. Run.'".
  Observe e3_forged_told at or_hall when e3Seized(rierdan) "The Margravine reads it, and looks at the two young men in the doorway, who are smiling at her, and says: 'Seize them.' She looks at you. 'The Margrave my neighbour has never been so definite.'".
  Observe e3_blown_told at or_hall when e3ForgeBlown(rierdan) "The Margravine folds the letter in four, and then in eight. 'That is a clever hand,' she says, 'but I have had thirty years of his R. I do not like to be written to by a boy.' She makes a small sign, and the guards close the door.".
  Observe e3_genuine_told at or_hall when e3Bellerophon(rierdan) and not e3ForgeBlown(rierdan) "The Margravine reads it twice, with her lips moving. Her face does not alter. 'My neighbour is clear,' she says. 'I don't like it. I'd like it less if I disobeyed him.' She makes a small sign, and the guards close the door.".
  Action explain_no_letter(actor: group, site: place) "Tell the Margravine you come without the Margrave's letter, and why the Prince is with you" {
    Speaker berengar.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, or_hall) and at(berengar, or_hall) and e3Burned(rierdan) and not e3Done(rierdan).
    Time 1.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert e3Explained(rierdan). Assert e3Escape(rierdan). Assert e3Done(rierdan). }
    On failure { Assert e3TurnedAway(rierdan). Assert e3Done(rierdan). }
    Result "You say that you were given a letter and that it burned, and who gave it, and what it asked, and that the Prince is here to be out of the house it came from. The Margravine puts down her pen. 'That is a odd cover story,' she says, 'for a truth. Sit down. You will want ham.'".
    Otherwise "'A letter that burned,' says the Margravine. 'On the road. With a prince in your company. I have not heard a story I liked less.' She has you shown to the gate, politely, and the gate is shut behind you. The Prince looks back at it once.".
  }
  Observe e3_confessed_told at hm_hall when e3Confessed(rierdan) and e3Letter(rierdan) and not e3Done(rierdan) "The Margrave has not met anyone's eye since the chapel. The letter was written that night, in a steady hand, by a man who has been shown himself and would rather not have been; it is the courteous page, and the seal is green.".
  Observe e3_explained_told near berengar when e3Explained(rierdan) "The Margravine of Orlay has put the Prince at her right hand, and the company at the end of the table, and a ham between them. She is writing, with pleasure, to her neighbour; the letter is about the price of wool.".
  Observe e3_killed_told near tiernan when e3Killed(rierdan) "Word comes to the kitchen by evening: Sir Dunmow Spargo and Sir Cullen Quillan were taken to the yard at dusk. The Prince listens, and puts down his knife. 'I said yes,' he says. 'I'll have to carry it that I said yes.'".
  Observe e3_killed_trust near tiernan when e3Killed(rierdan) and tiernanTrust(party) "'You stood on the wall with me,' says the Prince, to you, 'and then you let me choose this. I do not know whether to thank you.'".
  Observe e3_killed_scorn near tiernan when e3Killed(rierdan) and tiernanScorn(party) and not tiernanTrust(party) "'You told me to wait, and watch, and be sure,' says the Prince. 'And then the first time I could act, you handed me the pen.'".
  Observe e3_killed_spies near tiernan when e3Killed(rierdan) and e3Spies(rierdan) "'You knew about them,' says the Prince. 'You knew before I did. That is why you let it be them.' He is not angry. He is tired.".
  Observe e3_bell_told near berengar when e3Bellerophon(rierdan) "The company is in the Orlay larder among the hams, behind a good oak door. The Margravine has sent down bread and a note: that she is sorry, that it is in the letter, and that she will take it as a kindness if nobody tries the door before the week is out.".
  Observe or_larder_scene at or_larder when true "A cold stone room hung with hams and strings of onions, one window the width of a hand, and a bench. The door is oak and has a bar on the outside. Someone has left a loaf and a note.".
  Rule rp_bell_lock when e3Bellerophon(rierdan) and not e3Locked(rierdan) { Assert e3Locked(rierdan). Set e3LockedAt(rierdan) to watch(clock). Assert at(party, or_larder). }
  Rule rp_unlock_trust when e3Locked(rierdan) and not e3Unlocked(rierdan) and tiernanTrust(party) and watch(clock) >= e3LockedAt(rierdan) + 432 { Assert e3Unlocked(rierdan). }
  Rule rp_unlock_cook when e3Locked(rierdan) and not e3Unlocked(rierdan) and watch(clock) >= e3LockedAt(rierdan) + 1008 { Assert e3Unlocked(rierdan). }
  Action pick_larder_lock(actor: group, site: place) "Work the bar loose from inside, with a spoon and a great deal of patience" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, or_larder) and e3Locked(rierdan) and not e3Unlocked(rierdan) and not f_lock(rierdan).
    Time 6.
    Resolve check(actor, trapwork, dc_hard).
    On success { Assert e3Unlocked(rierdan). Assert e3Picked(rierdan). }
    On failure { Assert f_lock(rierdan). }
    Result "The bar comes up out of its bracket with a sound like a cough. The corridor beyond is empty. Somewhere a cook is singing.".
    Otherwise "The spoon bends. Whoever fitted the bar knew something about spoons.".
  }
  Observe e3_picked_told at or_larder when e3Picked(rierdan) "The bar lies on the flags where you left it. Nobody has come to put it back.".
  Observe e3_bell_trust at or_larder when e3Bellerophon(rierdan) and e3Unlocked(rierdan) and not e3Picked(rierdan) and tiernanTrust(party) "On the third night the Prince knocks from the passage. 'I have told her I am my uncle's heir,' he says through the door, 'and that I will go home and be what she likes, if she lets the Players go. She is considering it.' His voice is level.".
  Observe e3_bell_cook at or_larder when e3Bellerophon(rierdan) and e3Unlocked(rierdan) and not e3Picked(rierdan) and not tiernanTrust(party) "On the seventh night the Orlay cook lets you out by the coal door, because, he says, she makes a thing of it every time, and keeps his eyes on the pot.".
  Observe e3_turned_told near tiernan when e3TurnedAway(rierdan) "The Prince walks back to Harrowmere beside the cart, in the dust, and does not speak until the first milestone. Then he says, 'Well. That is a thing I should have thought of myself.'".
  Observe e3_escape_told near tiernan when e3Escape(rierdan) and not e3Held(rierdan) "The Prince is in the kitchen at Orlay eating the Margravine's ham with both hands, in a borrowed coat, with the Players round him and the look of having, for the first time, got away.".
  Observe e3_escape_seized near tiernan when e3Seized(rierdan) "Behind the kitchen wall, a long way off, two young men are being reasonable at some guards. The Prince does not look round. 'They were my friends,' he says, 'in the sense that I knew where they were.'".
  Observe e3_escape_trust near tiernan when e3Escape(rierdan) and not e3Held(rierdan) and tiernanTrust(party) "'Take me with you,' says the Prince. 'You are the ones who stayed. I can fence, I can write, and I'll be dreadful at everything else.'".
  Observe e3_escape_lonely near tiernan when e3Escape(rierdan) and not e3Held(rierdan) and tiernanLonely(party) and not tiernanTrust(party) "'Here I am,' says the Prince, looking at the ham, 'somewhere else, and still a prince. It is not at all what I was afraid of.'".
  Observe e3_escape_scorn near tiernan when e3Escape(rierdan) and not e3Held(rierdan) and tiernanScorn(party) and not tiernanTrust(party) and not tiernanLonely(party) "'You told me to wait and be sure,' says the Prince, not unkindly, with his mouth full. 'It turns out that when one is sure, one is generally somewhere else.'".
  Observe e3_escape_spared near tiernan when e3Escape(rierdan) and not e3Held(rierdan) and e3Spared(rierdan) "The Prince sits a little apart. 'I had my sword out in the chapel,' he says. 'You took my sleeve. I have not decided whether to thank you.' He turns the ham over. 'I have not decided whether I wished you hadn't.'".
  Observe e3_mis_told near tiernan when e3Misdelivered(rierdan) "The Prince has heard the Margravine of Orlay's reply, which is a ham and an offer of marriage, and is lying on the ground at the gate of Orlay, laughing, with tears down his face. 'My uncle,' he says, 'has proposed to the wrong woman. The wrong woman has said yes.' He is quiet. 'It is the first time,' he says, 'that I have thought we might get out of this.'".
  Rule rp_grave when x3c(rierdan) and not e3Letter(rierdan) and not e3Grave(rierdan) and harm(rierdan) >= 3 and watch(clock) >= e3X3At(rierdan) + 12 {
    Assert e3Grave(rierdan). Assert e3Done(rierdan). }
  Observe e3_grave_gate at hm_gate when e3Grave(rierdan) "A bell is going at the Margravate chapel, one stroke to a breath. The gate guard has taken his helmet off and does not seem to know where to put it.".
  Observe e3_grave_told at hm_hall when e3Grave(rierdan) "At the match the Margrave drinks to his nephew in a cup he does not drink from. The foil is not blunt. The Prince, who has been wounded twice already this month, goes down on the grass in the sun with his mother's name in his mouth. He has time to say 'Well,' and nothing more. In the chapel the stone Margrave has a new neighbour and the Margravine has the space for the next. The company plays that night because the Margrave commands it, and Swale does not remember a word.".
  Milestone m_prince_ghost "heard the Margrave's ghost on the rampart" worth 150 when e3Ghost(party).
  Milestone m_prince_letter "read what the letter said" worth 150 when e3Read(rierdan).
  Milestone m_prince_done "came away from Harrowmere" worth 300 when e3Done(rierdan).
  // Dorcas plays the Margravine as she decided to play the Lady at Cairnholt (the answer given in "The Three" is read here).
  Topic dorcas_iseult_a with dorcas "Ask Dorcas how she plays the Margravine, now" when e3Done(rierdan) and dorcasWants(party) once {
    Says "'Cleanly,' says Dorcas. 'She wanted the throne and the husband and she got both and it has not been enough. I did the Lady that way too, you remember, and I was right. I am a little ashamed how easily it comes.'".
  }
  Topic dorcas_iseult_b with dorcas "Ask Dorcas how she plays the Margravine, now" when e3Done(rierdan) and dorcasAfraid(party) once {
    Says "'The same way as the Lady,' says Dorcas. 'I find I can only do them frightened. Iseult is so still because if she moved she would have to choose between her son and her husband. It makes the part quiet. Gosse says nobody will hear me past the third row.' She smiles. 'The third row will.'".
  }
  Chapter ch_prince "The Prince and the Letter" when e3On(rierdan) and not e3Done(rierdan) "A Margravate in mourning, a prince who will not be guarded, a ghost on the rampart, a letter you have not yet been given.".
  Relation f_capt(place).
  Relation e3Locked(place).
  Relation e3Unlocked(place).
  Relation e3Picked(place).
  Relation e3Held(place).
  Relation e3Exposed(place).
  Relation e3Dismissed(place).
  Relation e3ForgeBlown(place).
  Relation e3SheetTaken(place).
  Relation f_conf(place).
  Relation f_lock(place).
  Relation e3Warned(place).
}

data/adventures/gosses-company/rep_three:
Module pentrice "Gosse's Company" {
  // ── Episode 2: The Three (Macbeth) ──────────────────────────────────────────────────────────────────────────────
  // Lord Ranulf Valtry of Cairnholt, a tired and honest soldier who has held a bad frontier for nineteen years, has
  // been told by three women on the moor that he will be Warden of the March, and that his keep will stand until the
  // heather walks. He hires the company, first, to learn whether the women can be believed; and then, as the days go,
  // to be the hands for what he has begun to want. The party need not notice. What they report, whom they test and
  // where they post their guards on the night of the feast are the prophecy's means. Act II of the King's Players
  // gave the Salt-Wives one line about a Marshal; this is the other half of the shape: the prediction that is made
  // true by the people sent to check it.
  // c2 = complicity: the count of things the company did that the prophecy needed.
  Place moor "the Cairnholt moor" is wilderness within wend at 3, 0.
  Place moor_cairns "the Three Cairns" is room within moor at 0, 1 outdoors.
  Place ck_yard "Cairnholt's yard" is room within moor at 1, 1 outdoors.
  Place ck_hall "Cairnholt's hall" is room within moor at 2, 1.
  Place ck_stair "the keep stair" is room within moor at 2, 0.
  Place ck_chamber "the Warden's chamber" is room within moor at 3, 0.
  Passage mo_yard "the peat track to the keep" is path between moor_cairns and ck_yard taking 30 minutes.
  Passage ck_door "the hall door" is door between ck_yard and ck_hall.
  Passage ck_up "the keep stair" is path between ck_hall and ck_stair.
  Passage ck_warden "the Warden's door" is door between ck_stair and ck_chamber.

  Observe moor_cairns_scene at moor_cairns when true "Three heaps of grey stones on a rise in brown heather, like three loaves of different ages. The wind has a sound in it. There is a small fire with a kettle on it, and three women sitting round it, who do not look up. The rise is the only place on the moor from which you cannot see the keep.".
  Observe ck_yard_scene at ck_yard when true "The yard of a keep that has been held for a king who forgot it: a well, a midden, thirty soldiers' washing, and a flag of a colour the weather has decided. Lord Valtry's men do their work as men do who have not been paid on time and have decided it is a matter of personal honour.".
  Observe ck_hall_scene at ck_hall when true "A long hall with a roof of black beams and a floor of flags. A hearth like a cave. A table laid for a feast, and a smaller table, to one side, where a lean lady in a green gown keeps the accounts.".
  Observe ck_stair_scene at ck_stair when true "A turnpike of worn stone, with a rope for a rail and a window the width of a man's two hands. At the top is a door with a bar on the inside.".
  Observe ck_chamber_scene at ck_chamber when true "A bedchamber for an old man: a bed with curtains, a chair by the fire, a basin, a shelf of tonics and one window over the dark moor. There is a smell of camphor and of a long life.".

  Relation e2On(place). Relation e2Reported(place). Relation e2Genuine(place). Relation e2Fraud(place). Relation e2Unclear(place).
  Relation e2StroudComes(place). Relation e2Night(place). Relation e2Murder(place). Relation e2Left(place).
  Relation e2Turned(place). Relation e2Revealed(place). Relation e2Warned(place).
  Relation e2GuardDoor(place). Relation e2GuardGate(place). Relation e2Carried(place). Relation e2Tested1(group). Relation e2Tested2(group). Relation e2Tested3(group).
  Relation e2Boots(place). Relation dorcasWants(group). Relation dorcasAfraid(group).
  Measure c2(place). Measure e2StroudAt(place). Measure e2NightAt(place). Measure e2StairAt(place). Relation e2Stair(place). Measure e2Start(place).

  Person valtry "Lord Ranulf Valtry" at ck_hall {
    Role "the Lord of Cairnholt, a soldier". Ancestry human. Calling warrior. Level 4. Peaceable. Pronouns he. Manner grim.
    Greets "A big grey man in a dented gorget, who stands as if the floor were deck. 'I do not need advice,' says Lord Valtry. 'I need a fact, and I am told you are in the business of showing things that are not so. Come to the fire. I am cold.'".
  }
  Person marit "Lady Marit Valtry" at ck_hall {
    Role "his sister, who keeps the keep's accounts". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "Green gown, ledger, twenty years of arithmetic: Lady Marit finishes her line before she lifts her eyes. 'The players,' says Lady Marit. 'Mind the table: it is the accounts. My brother likes you. Ranulf likes anyone who agrees with him.'".
  }
  Person toon "Steward Bartle Toon" at ck_yard {
    Role "the steward of Cairnholt". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "A round man in a leather apron with a ring of keys. 'Welcome,' says the steward. 'It is a beautiful keep when it is not on fire.'".
  }
  Person stroud "Warden Ancel Stroud" nowhere {
    Role "the Warden of the March, seventy-four, tired". Ancestry human. Peaceable. Pronouns he. Manner compassionate.
    Greets "An old man in a good fur with a stick he does not lean on. 'I am told,' says the Warden, 'that I am to be amused. Is there soup.'".
  }
  Person three "the three women" at moor_cairns {
    Role "three women of the moor, round a kettle, at a cairn". Ancestry human. Numbers 3. Peaceable. Pronouns they.
    Greets "The three do not turn their heads. 'Valtry's,' says the first. 'Or the Lady's,' says the second. 'Or the strangers',' says the third, and takes the kettle off the fire.".
  }

  // The employment: Toon engages the company, in the yard.
  Topic toon_job with toon "Ask the steward what the Lord wants of the company" when true once {
    Says "'A thing he will not say himself,' says Toon. 'Three women on the moor told him, at the harvest feast, that he would be Warden of the March, and that Cairnholt would stand until the heather walks. He has not slept since. He wants to know if they are real. He has asked the priest, who says no; and the farrier, who says yes, which settles nothing.' He lowers his voice. 'He thinks you are people who know what is pretended. Test them. Come back and tell him straight.'".
    On discuss { Assert e2On(rierdan). Set e2Start(rierdan) to watch(clock). }
  }

  // The women: three tests, each an action at the cairns.
  Action test_sincere(actor: group, site: place) "Watch the three women's hands while they talk, and listen for what is practised" {
    Speaker three.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, moor_cairns) and e2On(rierdan) and not e2Tested1(actor) and not e2Done(rierdan).
    Time 3.
    Resolve check(actor, insight, dc_fair).
    On success { Assert e2Tested1(actor). Assert knows(actor, three_hands_known). }
    On failure { Assert e2Tested1(actor). }
    Result "They talk about nothing for half an hour: a ewe, a cart, a daughter. Not one of the three looks at the other when she speaks, and when the third says a thing the other two, without turning, finish the sentence. It is practised. It is a rehearsed thing, and also the voice of women who have been three together for forty years. You cannot tell which of those it is.".
    Otherwise "They give you tea. You watch their hands. The hands are hands.".
  }
  Discovery three_hands_known "The three women speak as one voice in three; it is practised, and also old.".
  Action test_question(actor: group, site: place) "Ask them something the steward has hidden, and see what they say" {
    Speaker three.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, moor_cairns) and e2On(rierdan) and not e2Tested2(actor) and not e2Done(rierdan).
    Time 2.
    Resolve check(actor, lore, dc_hard).
    On success { Assert e2Tested2(actor). Assert knows(actor, three_truth_known). }
    On failure { Assert e2Tested2(actor). }
    Result "You ask what Toon has in his left pocket, which Toon told you in the yard: a ring. 'A ring,' says the eldest, 'with a blue stone, that he has not got, because he lost it to the Lady at cards.' It is true. It was the Lady who told Toon to put it there, yesterday, and told the women not at all. You write down the pocket's contents. You do not write down how she knew.".
    Otherwise "'A pocket,' says the eldest, and pours the tea.".
  }
  Discovery three_truth_known "The women knew a thing the steward had hidden, which only the Lady could have told them, or the world.".
  Action test_boots(actor: group, site: place) "Look for how they came to the cairns: tracks, a purse, a path" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, moor_cairns) and e2On(rierdan) and not e2Tested3(actor) and not e2Done(rierdan).
    Time 3.
    Resolve check(actor, woodcraft, dc_fair).
    On success { Assert e2Tested3(actor). Assert e2Boots(rierdan). Assert knows(actor, three_paid_known). }
    On failure { Assert e2Tested3(actor). }
    Result "A path through the heather runs from the cairns to the back of the keep's kitchen midden, and has been walked often by one woman in good boots, a lady's, with a heel. At the third cairn, under a stone, a purse that has been counted into three: a green ribbon, a seal, and the beginning of an initial. M.".
    Otherwise "Heather. A great deal of heather.".
  }
  Discovery three_paid_known "A lady's path runs from Cairnholt's kitchen to the cairns; under the third stone, a purse bound with a green ribbon, sealed M.".

  // The report: the company's word, and what the Lord does with it. Three answers, each acted on.
  Topic valtry_report with valtry "Report to Lord Valtry what you found on the moor" when e2On(rierdan) and not e2Reported(rierdan) once {
    Says "He listens with his arms folded and his eyes on the fire. 'Straight,' he says. 'As you would tell a man what is in his coat. Are they what they say?'".
  }
  Topic rep_genuine with valtry "They are genuine, my lord: they see" answering valtry_report when true {
    Says "He lets out a breath that has been in him since the harvest feast. 'Then it is not mine to refuse,' he says. He gets up and puts his coat on, though the fire is lit.".
    On discuss { Assert e2Reported(rierdan). Assert e2Genuine(rierdan). Increase c2(rierdan) by 1. }
  }
  Topic rep_fraud with valtry "They are frauds, my lord, and somebody is paying them" answering valtry_report when knows(actor, three_paid_known) {
    Says "Valtry is quiet for a while. 'Paying,' he says. 'Who?' You say you cannot say. He looks across the hall, at the lean lady in green bending over her accounts, and looks away again fast. 'No,' he says. 'No, that is not a thing we say.'".
    On discuss { Assert e2Reported(rierdan). Assert e2Fraud(rierdan). }
  }
  Topic rep_unclear with valtry "I cannot tell, my lord; it would take another day" answering valtry_report when true {
    Says "'Another day,' says Lord Valtry, and stops. 'The Warden comes in a day and a half. A man does not wait on a silence.' He looks at the fire. 'If you have nothing to tell me, I'll go by what I believe, and the gods help whoever it is I believe.'".
    On discuss { Assert e2Unclear(rierdan). }
  }

  // The loop: from here the Lord begins to arrange what he has been told. The company is asked for the means.
  Rule e2_unreported when e2On(rierdan) and not e2Reported(rierdan) and watch(clock) >= e2Start(rierdan) + 40 {
    Assert e2Reported(rierdan). Assert e2Genuine(rierdan). Assert e2Unreported(rierdan). Increase c2(rierdan) by 1. }
  Observe e2_unreported_told near valtry when e2Unreported(rierdan) and not e2Done(rierdan) and not e2Night(rierdan) "Lord Valtry has stopped waiting for the company's word. He has decided what the women are, and is arranging the house to suit.".
  Rule e2_stroud when e2Reported(rierdan) and not e2StroudComes(rierdan) and not e2Done(rierdan) and watch(clock) >= e2Start(rierdan) + 60 {
    Assert e2StroudComes(rierdan). Set e2StroudAt(rierdan) to watch(clock). Assert at(stroud, ck_hall). }
  Observe e2_summons at wend_cross when e2On(rierdan) and not e2Reported(rierdan) and not e2Done(rierdan) and watch(clock) >= e2Start(rierdan) + 30 "A rider in Cairnholt's green has been up and down the Fourways road twice asking for the Players. Lord Valtry's message is short: the Warden comes in a day and a half, and he will decide without the company's word if he has none by tomorrow noon.".
  Observe e2_stroud_told at ck_yard when e2StroudComes(rierdan) and not e2Night(rierdan) and not e2Done(rierdan) "Outriders in the Warden's colours have come in under the gate with a cart of good bedding, and the yard has gone quiet to look. The feast will be tonight, when the lamps are lit, and the whole keep is saying so.".
  Observe e2_arrange near valtry when e2Genuine(rierdan) and not e2Night(rierdan) and not e2Done(rierdan) "Lord Valtry has had the Warden's room aired, the stair-rope re-hung, and a good bed made up, 'because he is old', and has asked the steward three times where the guards will stand.".
  Observe e2_fraud_obs near valtry when e2Fraud(rierdan) and not e2Night(rierdan) and not e2Done(rierdan) "Lord Valtry takes his meals at the far end of the table from his sister now, and watches her pour, and has not said why.".
  Observe e2_unclear_obs near valtry when e2Unclear(rierdan) and not e2Reported(rierdan) and not e2Night(rierdan) and not e2Done(rierdan) "Lord Valtry says he is waiting for the company's day, and in the meantime has had the Warden's room swept twice.".
  Topic toon_guards with toon "Ask the steward where the guards are to stand on the feast night" when e2Reported(rierdan) and e2StroudComes(rierdan) and not e2GuardDoor(rierdan) and not e2GuardGate(rierdan) once {
    Says "'My Lord's instruction,' says Toon, 'is that the company's soldiers stand wherever the company thinks best. He says the Warden should see he is trusted. I should put two at the gate and none at the Warden's door, which is what my lady suggests, but it is a matter for you.'".
  }
  Action guard_gate(actor: group, site: place) "Post the guards at the gate, and let the Warden's door alone" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ck_yard) and e2StroudComes(rierdan) and not e2GuardDoor(rierdan) and not e2GuardGate(rierdan) and not e2Done(rierdan).
    Time 1.
    On success { Assert e2GuardGate(rierdan). Increase c2(rierdan) by 1. }
    Result "The soldiers take the gate. The old man's stair is not watched, as the Lady suggested and the Lord assented, on the grounds that a Warden should not be treated like a prisoner.".
  }
  Action guard_door(actor: group, site: place) "Post two soldiers at the Warden's door, and tell the Lord it is the company's rule" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ck_yard) and e2StroudComes(rierdan) and not e2GuardDoor(rierdan) and not e2GuardGate(rierdan) and not e2Done(rierdan) and not f_door(rierdan).
    Time 1.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert e2GuardDoor(rierdan). }
    On failure { Assert f_door(rierdan). }
    Result "You tell Valtry it is the Players' practice that a guest of rank is watched at the door in a house with a feast, which is not true. He studies you with an expression you cannot read. 'Do it,' he says. He does not say thank you.".
    Otherwise "'The Warden is among friends,' says Valtry. 'He will not be guarded.' He is angry, a little, and has not decided at whom.".
  }
  Observe marit_cup near marit when e2StroudComes(rierdan) and not e2Carried(rierdan) and not e2CupRefused(rierdan) and not e2Done(rierdan) "Lady Marit has a covered cup on her table, warming by the fire. She keeps her back to it. She looks, now and again, at whoever in the hall is idle.".
  Topic marit_asks with marit "Ask Lady Marit how the Warden is to be received" when e2StroudComes(rierdan) and not e2Done(rierdan) once {
    Says "'He is old,' says Lady Marit, ruling a line. 'He will want to be left alone and to be thought well of. I would put the guard on the gate, where they can be seen, and let him sleep without a soldier on his stair; he will take it as a courtesy. And someone he does not know should bring him the cup. It is a family cup, and spiced.'".
  }
  Action carry_invitation(actor: group, site: place) "Take Lady Marit's covered cup up to the Warden's room, as she asks" {
    Speaker marit.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ck_hall) and at(marit, ck_hall) and e2StroudComes(rierdan) and not e2Carried(rierdan) and not e2CupRefused(rierdan) and not e2Done(rierdan).
    Time 1.
    On success { Assert e2Carried(rierdan). Increase c2(rierdan) by 1. }
    Result "You carry it up the stair yourself. The cup is warm. Under the spice there is something you know from sick-rooms: poppy, and a bitterness behind it. The Warden thanks you and sets it by the bed. 'Tell the Lady,' he says, 'that it is a good cup.'".
  }
  Action refuse_cup(actor: group, site: place) "Tell Lady Marit that the company does not carry cups to guests it has not tasted for" {
    Speaker marit.
    Requires able(actor) and company(actor) and at(actor, site) and at(marit, site) and e2StroudComes(rierdan) and not e2Carried(rierdan) and not e2CupRefused(rierdan) and not e2Done(rierdan).
    Time 0.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert e2CupRefused(rierdan). }
    On failure { Assert e2Carried(rierdan). Increase c2(rierdan) by 1. }
    Result "'As you like,' says Lady Marit. She does not move, and she does not say it again. After a while the steward comes for the cup, and the cup goes down to the kitchen with a cloth over it, and you do not see it again.".
    Otherwise "'You are particular for a hired company,' says Lady Marit. She gives the cup to the steward, who takes it up the stair on the company's authority, because a cup, once refused by the people who were told to carry it, has had the company's name put on it.".
  }
  Action warn_stroud(actor: group, site: place) "Tell the Warden he is not safe in this keep, and why" {
    Speaker stroud.
    Requires able(actor) and company(actor) and at(actor, site) and at(stroud, site) and e2StroudComes(rierdan) and not e2Warned(rierdan) and not e2Done(rierdan) and not f_warn(rierdan).
    Time 0.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert e2Warned(rierdan). Assert e2GuardDoor(rierdan). }
    On failure { Assert f_warn(rierdan). }
    Result "The old man listens with his head turned to one side. 'I have been told I am in danger from Cairnholt every year for twenty years,' he says, 'by people who wanted a fee. You, I think, want nothing.' He sits up. 'A man at my door, then. And no cup for me.'".
    Otherwise "'Danger,' says the Warden, and smiles, 'is a thing I have outlived.'".
  }

  // The loop is seen: from the second act of complicity the women say so.
  Observe e2_loop at moor_cairns when c2(rierdan) >= 2 and not e2Night(rierdan) "The three women have moved the kettle. Now one of them is writing, and the writing is yours: 'Who reported. Who posted. Who carried.' She looks up, kindly. 'And the strangers,' she says, 'fetched it.' You had not told them your names." teaches e2_loop_known.
  Discovery e2_loop_known "The women have been writing down what the company did, and calling it the prophecy.".

  // The night.
  Rule e2_clear when e2Done(rierdan) and at(stroud, ?sx) { Retract at(stroud, ?sx). }
  Rule e2_night when e2StroudComes(rierdan) and not e2Night(rierdan) and not e2Done(rierdan) and (hour(clock) >= 21 or hour(clock) < 4) and watch(clock) >= e2StroudAt(rierdan) + 12 { Assert e2Night(rierdan). Set e2NightAt(rierdan) to watch(clock). }
  Observe e2_night_told at ck_hall when e2Night(rierdan) and not e2Stair(rierdan) and not e2Done(rierdan) "The feast is cleared. The Warden has been helped up the stair with a lamp. Lady Marit sits in her corner with her ledger shut, and every soldier in the hall is looking at the company.".
  Rule e2_stair when e2Night(rierdan) and not e2Stair(rierdan) and not e2Done(rierdan) and hour(clock) >= 2 and hour(clock) < 12 and watch(clock) >= e2NightAt(rierdan) + 6 { Assert e2Stair(rierdan). Set e2StairAt(rierdan) to watch(clock). }
  Observe e2_stair_told at ck_hall when e2Stair(rierdan) and not e2Done(rierdan) "A step on the keep stair, slow and careful, with something carried. In an hour the hall will know what it was.".
  Rule e2_kill when e2Night(rierdan) and not e2Done(rierdan) and not e2GuardDoor(rierdan) and not e2Warned(rierdan) and not e2CupRefused(rierdan) and c2(rierdan) >= 1 and e2Stair(rierdan) and watch(clock) >= e2StairAt(rierdan) + 6 {
    Assert e2Murder(rierdan). Assert e2Done(rierdan). }
  Rule e2_quiet when e2Night(rierdan) and not e2Done(rierdan) and not e2GuardDoor(rierdan) and not e2Warned(rierdan) and not e2CupRefused(rierdan) and c2(rierdan) < 1 and e2Stair(rierdan) and watch(clock) >= e2StairAt(rierdan) + 6 {
    Assert e2Left(rierdan). Assert e2Quiet(rierdan). Assert e2Done(rierdan). }
  Relation e2Done(place). Relation e2Quiet(place). Relation e2Unreported(place). Relation e2Rebuffed(place). Relation e2CupRefused(place).
  Observe e2_left_broadside at wend_cross when e2Left(rierdan) and not e2Quiet(rierdan) "A month later, on a broadside nailed to the milestone: the Lord of Cairnholt, found in the morning in his own hall with his gorget off and no mark on him, a heart, they said. The Warden was chosen again at midsummer by the usual vote.".
  Observe e2_quiet_told at ck_hall when e2Quiet(rierdan) "The feast is long and dull. Nobody tries the Warden's stair, because nobody has been given a reason; the Lord of Cairnholt gets drunk at the high table, and says to the company that he has been a fool about three old women. In the morning the kettle has gone from the cairns and, they say, the women from the moor.".
  Observe e2_heather at moor_cairns when e2Murder(rierdan) "The south slope of the moor has been cut for the new Warden's winter bonfire, and a long cart of heather is coming down the hill towards Cairnholt, so that from the cairns the whole hillside seems to be walking. The three women have gone from the kettle. The kettle has not.".
  Observe e2_broadside at wend_cross when e2Murder(rierdan) "A broadside is nailed to the milestone: the Warden of the March died in his bed at Cairnholt, of the cold, and the Lord of Cairnholt is chosen Warden by acclamation. A carter says that he has not been seen to sleep since. Someone has drawn a small kettle in the corner, in chalk.".
  Observe e2_murder_told at ck_hall when e2Murder(rierdan) "In the morning there is a noise in the keep that is not a noise: the sound of thirty soldiers standing still. The Warden's chamber door is open and the old man lies in his bed with the cup beside him, peaceful, and warm. Lord Valtry stands at the foot of the bed in his gorget. He turns. 'You see,' he says, 'it was true.' By noon the keep has a new Warden, and the company has a letter of thanks.".
  Observe e2_murder_after near valtry when e2Murder(rierdan) "Lord Valtry is the Warden of the March. He has not slept since the night. He has had the cups taken out of the keep, and the women sent for, and not found.".
  Rule e2_survive when e2Night(rierdan) and not e2Done(rierdan) and (e2GuardDoor(rierdan) or e2Warned(rierdan) or e2CupRefused(rierdan)) and e2Stair(rierdan) and watch(clock) >= e2StairAt(rierdan) + 6 { Assert e2Left(rierdan). Assert e2Done(rierdan). }
  Observe e2_survive_told at ck_hall when e2Left(rierdan) and not e2Quiet(rierdan) "In the grey, someone tries the Warden's stair. Two soldiers stand at the door with their spears crossed, as they were told, and the footstep stops, and goes down again. Nobody says who it was. At breakfast the Warden eats his egg with great attention and Lord Valtry does not come down. Lady Marit pours the tea. You leave on the stroke of ten.".
  // The two ways out of the loop that take nerve: expose the Lady's purse, or turn the Lord.
  Action show_purse(actor: group, site: place) "Put the Lady's purse on the table in front of the Lord, and the ribbon, and the seal" {
    Speaker valtry.
    Requires able(actor) and company(actor) and at(actor, site) and at(valtry, site) and e2Boots(rierdan) and e2On(rierdan) and not e2Revealed(rierdan) and not e2Turned(rierdan) and not e2Rebuffed(rierdan) and not e2Done(rierdan).
    Time 0.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert e2Revealed(rierdan). Assert e2Done(rierdan). }
    On failure { Assert e2Rebuffed(rierdan). }
    Result "He looks at it. He picks up the ribbon and puts it down. 'She said,' he says at last, to nobody, 'that I had always had the hands for it.' He sits. He keeps his back to the door, behind which, you can hear, his sister is not listening. 'I think I would rather be a tired man,' he says, 'than the thing I had been told.' He sends for the Warden to be told that his chamber is warm. In the morning the Lady is not at the table, and her accounts are balanced.".
    Otherwise "'You say that,' says Valtry, 'because you are afraid of what I might be.' He is quiet. 'Go, before I decide whether you are right.' He will not hear it from you again.".
  }
  Action turn_the_lord(actor: group, site: place) "Say to the Lord, alone, that a man told he will be a king is not told to do anything" {
    Speaker valtry.
    Requires able(actor) and company(actor) and at(actor, site) and at(valtry, site) and knows(actor, e2_loop_known) and not e2Revealed(rierdan) and not e2Turned(rierdan) and not e2Rebuffed(rierdan) and not e2Done(rierdan).
    Time 0.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert e2Turned(rierdan). Assert e2Done(rierdan). }
    On failure { Assert e2Rebuffed(rierdan). }
    Result "He is still. 'Go on.' You say that a prophecy is the shape of a thing, and a man who is told it can walk round it or into it, and it is not your business which; and that you have been the hands for what he had begun to want and are going to stop. He does not say anything for a time. 'Stop, then,' he says. 'I'll go up and wake the Warden and ask him to tell me why he is tired. It is my habit that I do not do that.'".
    Otherwise "'It is easy,' says Valtry, 'to say what a man should do who is not me.' He turns his back, and it is a back that has stopped listening.".
  }
  Observe e2_turned_told near valtry when e2Turned(rierdan) "Lord Valtry sits by the Warden's fire in the morning with a bowl of soup in his hands and the old man talking, and listens, and does not seem to be waiting for anything. Lady Marit is looking at them from the door with an expression you will remember.".
  Observe e2_revealed_told near marit when e2Revealed(rierdan) "Lady Marit has gone back to her mother's house on the coast. Her accounts, which are balanced, are on the table. At the cairns the kettle has gone cold, and under the third stone there is nothing.".
  Chapter ch_three "The Three" when e2On(rierdan) and not e2Done(rierdan) "A soldier on a bad frontier has been told something. You have been hired to find out if it is true.".
  Milestone m_three_loop "saw that the company was in the prophecy" worth 200 when knows(party, e2_loop_known).
  Milestone m_three_end "left Cairnholt behind" worth 300 when e2Done(rierdan).
  Milestone m_three_turn "turned Lord Valtry, or showed him the purse" worth 400 when e2Turned(rierdan) or e2Revealed(rierdan).

  // Dorcas, and whom she will play.
  Topic dorcas_marit with dorcas "Ask Dorcas how she would play the Lady" when e2On(rierdan) and at(dorcas, wend_taproom) once {
    Says "Dorcas puts down the stocking. 'There is the thing everyone does,' she says, 'where she wants it. Cold, hungry, the whole of it. I never believed it. I think she is afraid of what her brother will turn into if nobody gives him something to be for.' She looks at you. 'Which is it? You have seen her.'".
  }
  Topic dorcas_wants with dorcas "She wants it, and has for years" answering dorcas_marit when true {
    Says "'Yes,' says Dorcas, without triumph. 'That is the safer way. Cleaner. I'll do her hungry.'".
    On discuss { Assert dorcasWants(actor). }
  }
  Topic dorcas_afraid with dorcas "She is afraid of what he will be without it" answering dorcas_marit when true {
    Says "Dorcas is silent. 'That is the difficult one,' she says. 'It will be much harder to play.' She picks up the stocking and then puts it down. 'Good.'".
    On discuss { Assert dorcasAfraid(actor). }
  }
  Relation f_door(place).
  Relation f_warn(place).
}

Module pentrice "Gosse's Company" {
  // ── Episode 4: The Wood near Athens-under-Hollin (A Midsummer Night's Dream) ──────────────────────────────────────────
  // Squire Rafe Hartigan is to be married on the lawn of Hollin Wood at dawn to Idony Faulds, and has engaged the
  // King's Players to oversee a play to be given by the village's own players, in which a weaver is to play a lover,
  // a wall, and a lion. The wood has a Lord and a Lady who have been quarrelling over a changeling for seven years
  // and who take an interest in the wedding the way the weather takes an interest in washing. By midnight the stage
  // enchantments are real, the lovers are in love with the wrong people, the weaver has an ass's head, and Absalom
  // Gosse, who has directed kings, is beside himself. The company must get everyone back to the lawn by dawn, in the
  // pairs they started in or not; the wood does not much care. It is not harmless: it has a hunt.
  // d = watches since the company first stood on the lawn (e4Start). The night is about ninety watches.
  Place hollin "Hollin Wood" is wilderness within wend at 5, 1.
  Place wd_lawn "the wedding lawn" is room within hollin at 1, 2 outdoors.
  Place wd_edge "the edge of the wood" is room within hollin at 1, 1 outdoors.
  Place wd_ring "the oak ring" is room within hollin at 2, 1 outdoors.
  Place wd_glade "the Lord's glade" is room within hollin at 2, 0 outdoors.
  Place wd_bog "the lantern bog" is room within hollin at 0, 1 outdoors.
  Place wd_hollow "the pixie's hollow" is room within hollin at 0, 0 outdoors.
  Place wd_ash "the ash that is a woman" is room within hollin at 1, 0 outdoors.
  Passage wd_a "the green ride" is path between wd_lawn and wd_edge taking 10 minutes.
  Passage wd_b "the track to the oaks" is path between wd_edge and wd_ring taking 20 minutes.
  Passage wd_c "the deer-path to the glade" is path between wd_ring and wd_glade taking 20 minutes.
  Passage wd_d "the boardwalk to the bog" is path between wd_edge and wd_bog taking 20 minutes.
  Passage wd_e "the rabbit-run to the hollow" is path between wd_bog and wd_hollow taking 20 minutes.
  Passage wd_f "the root-stair to the ash" is path between wd_glade and wd_ash taking 10 minutes.
  Passage wd_g "the ash's long shadow" is path between wd_ash and wd_hollow taking 20 minutes.
  Observe wd_lawn_scene at wd_lawn when true "A lawn cut into the beech wood and set with trestles, an arbour of ribbons, and a heap of hampers. The village players have built a stage out of two carts and a door. A smell of cut grass and cheese, and, from the dark of the wood, an absolutely steady sound of someone not laughing.".
  Observe wd_edge_scene at wd_edge when true "Where the lawn ends the wood begins, with no fuss: a wall of beech and a ride that closes behind you, if you look back, sooner than it should. Midges. A faint, warm smell of hay and honey, the smell of nothing in particular, that you realise you have been smelling since the lawn.".
  Observe wd_ring_scene at wd_ring when true "A ring of old oaks around a clearing carpeted in moss, lit from no source. In the middle, on a bed of cut flowers, someone is sleeping with enormous dignity.".
  Observe wd_glade_scene at wd_glade when true "A glade of trampled grass and cold fires, where a revel is just ending or about to begin. The air tastes of cider that has been left out in the moon. Goat-hoofed prints go round and round.".
  Observe wd_bog_scene at wd_bog when true "A black bog with islands of reed and a hundred small blue lights moving over it in no pattern, politely, like guests who have not been introduced. The boardwalk goes on into them.".
  Observe wd_hollow_scene at wd_hollow when true "A bank under a tree-root, soft with moss, in which something small has made a bed and lined it with stolen things: a thimble, a bell, a lock of hair. Round the bank grow low blue flowers, and, among them, some red ones, with heavy heads.".
  Observe wd_ash_scene at wd_ash when true "A great ash in a clearing, which has the shoulders of a tall woman and a bark like a grey cloak. Her roots go down into the earth like a skirt. She is watching you.".

  Relation e4AshAsked(group). Relation e4Slept(place). Relation e4BargainFailed(place). Relation e4Blank(place). Relation e4NameKnown(place). Relation robinStole(place). Relation e4On(place). Relation e4Done(place). Relation e4Dawn(place). Relation e4Restored(place). Relation e4Fiasco(place). Relation e4Price(place).
  Relation e4Mischief(place). Relation e4Quarrel(place). Relation e4Hunt(place). Relation e4LoomAss(place). Relation e4QueenLoves(place). Relation e4LoomFree(place).
  Relation e4Gathered(group). Relation e4Namepaid(group). Relation e4LordTolerates(place).
  Relation loves(group, group). Relation e4Rested(place). Relation gosseBeside(place). Relation gosseCalm(place).
  Measure e4Start(place). Measure e4EdgeAt(place). Measure e4BogAt(place). Measure e4Dusk(place). Relation e4Humbled(place).
  Initially Assert loves(rafe, idony). Initially Assert loves(idony, rafe). Initially Assert loves(jack, maud). Initially Assert loves(maud, jack).

  Person rafe "Squire Rafe Hartigan" at wd_lawn {
    Role "the groom, a loud, kind young man". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "'HARTIGAN!' says the Squire, shaking your hand to the elbow. 'Marrying! Dawn! A play! My bride says you are clever. I say you are welcome. Have you seen a girl? Idony, this tall, with a hat?'".
  }
  Person idony "Idony Faulds" at wd_lawn {
    Role "the bride". Ancestry human. Peaceable. Pronouns she. Manner cheerful.
    Greets "Under a hat as wide as a cartwheel, Idony Faulds is checking the hampers. 'Rafe,' she says, 'is the best man in Hollin. You should know I've thought about this.'".
  }
  Person jack "Wat Dunstable" at wd_lawn {
    Role "the groom's friend, a farmer's son". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "Straw in his hair and a fiddle he is not sure he is meant to have: a big shy fellow. 'Wat,' he says. 'I'm to stand up for Rafe. I'm no good at it.'".
  }
  Person maud "Nan Sellars" at wd_lawn {
    Role "the bride's friend, who is to stand up for her". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "Nan Sellars, who has pinned her own hem, looks you up and down. 'Bridesmaid. Means I hold the hat. You'll find I hold it well.'".
  }
  Person loom "Barnaby Loom" at wd_lawn {
    Role "the weaver, who is to play Pyramus, the Wall and the Lion". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "In a lion's mane of carded wool stands a tall, wide, happy man. 'ROAR,' says Barnaby Loom, to demonstrate. 'No, I'll do it softer. So as not to frighten the ladies. ROAR.'".
  }
  Person robin "Robin Sprigg" nowhere {
    Role "a small brown pixie with a bag". Species pixie. Level 2. Peaceable.
    Greets "Something small and brown drops off a branch onto your shoulder and examines your ear. 'No iron,' it says, delighted. 'Not a nail. Pick what you like from the bank. I have picked from everybody.'".
  }
  Person queen "the Lady of the Ring" nowhere {
    Role "the queen of the oak ring, asleep". Species nymph. Level 3. Temperament territorial.
    Warns "The woman on the flower bed opens her eyes, which are the colour of the moss, and looks at you without any interest at all. 'Not now,' she says, 'I am in love.'".
    Lair wd_ring.
  }
  Person greenlord "the Lord of the Green" nowhere {
    Role "the Lord of the wood, a goat-legged, honey-voiced thing". Species satyr. Level 4. Temperament territorial.
    Warns "In the glade the shadow of a man stands up and has a pair of horns and the hocks of a goat, and a smile you can see from across the clearing. 'A mortal,' says the Lord of the Green, 'is not a guest. A mortal is an excuse.'".
    Comes "The Lord of the Green comes at you in a dance step that is not a dance.".
    Lair wd_glade.
  }
  Person ash "the Ash" at wd_ash {
    Role "a dryad, in her tree". Species dryad. Level 3. Peaceable.
    Greets "The ash says, in a voice like a branch on a roof: 'I have a long memory and a short temper. Which do you wish to meet?'".
  }

  // The commission: the Squire's steward asks for the company; Gosse, backstage, is already beside himself.
  Rule e4_begin when at(party, wd_lawn) and not e4On(rierdan) { Assert e4On(rierdan). Set e4Start(rierdan) to watch(clock). Assert gosseBeside(rierdan). }
  // The troupe is wherever the party finds it: whoever of the troupe is not on the lawn when the party stands there is fetched, every time.
  Rule e4_fetch when e4On(rierdan) and not e4Done(rierdan) and at(party, wd_lawn) and troupe(?p) and distinct(?p, clemency) and not at(?p, wd_lawn) and at(?p, ?q) { Retract at(?p, ?q). Assert at(?p, wd_lawn). }
  Topic gosse_beside with gosse "Ask Gosse how the rehearsal is going" when e4On(rierdan) and not gosseCalm(rierdan) once {
    Says "Gosse is on the stage, if it is a stage, with one hand clasped to his forehead and the other pointing at a villager. 'He is a LION,' he says, 'and he will not be a lion. He is a WALL, and he will not be a wall. He says he can do both at once and he is correct, and it is DREADFUL.' He turns to you, eyes wet. 'Eight rehearsals, Heaven help me, and not one person in the wood is following the SCRIPT.'".
  }
  Topic gosse_calm1 with gosse "Tell him that no one in the wood has ever followed a script, and the best plays are the ones where they do not" answering gosse_beside when true {
    Says "'Heresy,' says Gosse. He thinks about it. 'It is a comforting heresy.' He sits down on a hamper. 'I shall try to enjoy myself.'".
    On discuss { Assert gosseCalm(rierdan). }
  }
  Topic gosse_calm2 with gosse "Offer to run the rehearsal yourself, so he can lie down" answering gosse_beside when true {
    Says "'Run it?' says Gosse. He stares. 'You will have to be firm with the Wall.' He hands you the book, trembling, and withdraws behind a tree to be beside himself in private.".
    On discuss { Assert e4Rested(rierdan). Assert gosseCalm(rierdan). }
  }

  Observe gosse_beside_obs near gosse when gosseBeside(rierdan) and not gosseCalm(rierdan) "Gosse is walking in a small circle with the prompt book held out in front of him like a dead bird.".
  Observe gosse_rested_obs at wd_lawn when e4Rested(rierdan) and e4Hunt(rierdan) and not e4Dawn(rierdan) "The prompt book is open on a hamper and Gosse is asleep face-down on it, with his hat over his ear, snoring in iambics.".

  // What the troupe carried into the wood from the road: each earlier answer is read here.
  Topic kit_wood_a with kit "Ask Kit how he is, here, among the lovers" when e4On(rierdan) and kitSaysSo(party) once {
    Says "'I said I was the sort of boy who says so,' says Kit, 'and it turns out to be true. It is awkward. I told Nan Sellars she had lovely handwriting, and she said thank you, and I have been dying ever since.' He grins, miserable. 'Is this what it is?'".
  }
  Topic kit_wood_b with kit "Ask Kit how he is, here, among the lovers" when e4On(rierdan) and kitHolds(party) once {
    Says "'I am holding it back,' says Kit, 'the way you said.' He looks at the pairs on the grass. 'I see now why one might. It looks like hard work, and none of them is any good at it.'".
  }
  Topic kit_wood_c with kit "Ask Kit how he is, here, among the lovers" when e4On(rierdan) and kitLeaned(party) once {
    Says "'I stayed near you,' says Kit, 'and it was the right thing, because the wood is full of people who are all going to be someone else's by morning.' He kicks a root. 'I like being nobody's. It is restful.'".
  }
  Topic swale_wood_a with swale "Ask Swale who he thinks will play the Wall" when e4On(rierdan) and swaleHand(party) once {
    Says "'The Prince of Harrowmere,' says Swale, unexpectedly, 'writes better than I do, and I find it has made me generous. Let the carpenter be the Wall. I never knew a Wall that was not improved by being someone's best part.'".
  }
  Topic swale_wood_b with swale "Ask Swale who he thinks will play the Wall" when e4On(rierdan) and swaleVain(party) once {
    Says "'I shall play the Wall,' says Swale, 'and the Lion, and the Moon, and I shall have all the best lines, and the carpenter may hold the lantern. I have been cut before and I do not intend to be again.'".
  }

  // The night. Four beats.
  Rule rp_w1 when e4On(rierdan) and not e4Mischief(rierdan) and watch(clock) >= e4Start(rierdan) + 8 {
    Assert e4Mischief(rierdan). Assert at(robin, wd_hollow). }
  Rule rp_w1s when e4Mischief(rierdan) and not e4Quarrel(rierdan) and (hour(clock) >= 18 or hour(clock) < 4)
    and at(rafe, ?r1) and at(jack, ?j1) and at(idony, ?i1) and at(maud, ?m1) {
    Assert e4Quarrel(rierdan). Set e4Dusk(rierdan) to watch(clock).
    Retract at(rafe, ?r1). Assert at(rafe, wd_edge). Retract at(jack, ?j1). Assert at(jack, wd_edge).
    Retract at(idony, ?i1). Assert at(idony, wd_edge). Retract at(maud, ?m1). Assert at(maud, wd_edge). }
  Observe w_dusk_told at wd_lawn when e4Quarrel(rierdan) and not e4Dawn(rierdan) "At dusk Rafe and Wat walked into the wood to find a better hat; Idony and Nan followed them with a lantern, to lecture. Nobody has come back out.".
  Rule rp_w2 when e4Quarrel(rierdan) and not e4LoomAss(rierdan) and watch(clock) >= e4Dusk(rierdan) + 6 {
    Assert e4LoomAss(rierdan). Retract at(loom, wd_lawn). Assert at(loom, wd_ring). Assert e4QueenLoves(rierdan). Assert at(queen, wd_ring). }
  Rule rp_w3 when e4LoomAss(rierdan) and not e4Hunt(rierdan) and watch(clock) >= e4Dusk(rierdan) + 16 {
    Assert e4Hunt(rierdan). Assert at(greenlord, wd_glade).
    Retract loves(rafe, idony). Retract loves(idony, rafe). Retract loves(jack, maud). Retract loves(maud, jack).
    Assert loves(rafe, maud). Assert loves(jack, idony). Assert loves(maud, rafe). Assert loves(idony, jack). }
  Observe w_lovers near rafe when e4Hunt(rierdan) and loves(rafe, maud) "The Squire has gone down on one knee in the bracken to Nan Sellars, who is trying to get up from her own, and is saying, in a clear carrying voice, the finest verse he has ever made.".
  Observe w_lovers2 near jack when e4Hunt(rierdan) and loves(jack, idony) "Wat Dunstable, who has never in his life said a thing to a woman, is holding Idony's hat and reciting the order of service to her in a voice of anguish.".
  Observe w_loom near loom when e4QueenLoves(rierdan) and not e4LoomFree(rierdan) "Barnaby Loom lies on the moss in the oak ring with an ass's head on his shoulders, entirely happy, being fed strawberries by the Lady of the Ring. 'Mothwing,' he says, 'scratch me.' It is not clear that he was told to say it.".
  Observe w_hunt at wd_lawn as sound when e4Hunt(rierdan) and not e4Dawn(rierdan) "From deep in the wood a horn, a goat's, a long way off, and the sound of hooves going the wrong way round.".

  // The wood's rules, and ways through them: iron, names, music, refusal of thanks. The hunt strikes the unprotected.
  Item wd_iron "a handful of iron nails from the stage-carpenter's box" is iron_spikes at wd_lawn.
  Item wd_torch "a pitch torch from the property hamper" is torch at wd_lawn.
  Hazard hunt_blow "The Hunt in the wood" means "Deal (1d6) physical damage to ally unless dexterity save against (13).".
  Hazard bog_drown "The bog" means "Deal (1d6) physical damage to ally unless constitution save against (12).".
  // At the edge the horn comes first: the company has two watches (twenty minutes) between the horn and the hooves, and may turn its coats, play on the lawn, hold iron, or go back.
  Rule rp_hunt_warn at wd_edge when e4Hunt(rierdan) and not e4Dawn(rierdan) and at(party, wd_edge) and not e4EdgeSeen(rierdan) and not e4LordTolerates(rierdan)
    says "The horn is in the beech-wood, nearer than it was, and the wind has turned to bring it. In the ride behind you the leaves have begun to move the wrong way, towards the lawn. Whatever is coming is coming round the oaks, and it will be here soon." {
    Assert e4EdgeSeen(rierdan). Set e4EdgeAt(rierdan) to watch(clock). }
  Rule rp_edge_clear when e4EdgeSeen(rierdan) and not at(party, wd_edge) { Retract e4EdgeSeen(rierdan). }
  Rule rp_hunt_strikes at wd_edge when e4Hunt(rierdan) and not e4Dawn(rierdan) and at(party, wd_edge) and e4EdgeSeen(rierdan) and watch(clock) >= e4EdgeAt(rierdan) + 2 and not e4LordTolerates(rierdan) and not holding(party, iron_spikes) and dice(clock) <= 14
    says "The horn comes round the oaks in a rush, and the wind with it, and a thing with the smell of goat goes past you at the height of a man's head." {
    Assert strikes(hunt_blow, party). }
  Rule rp_bog_warn at wd_bog when e4Hunt(rierdan) and at(party, wd_bog) and not e4BogSeen(rierdan) and not e4LordTolerates(rierdan) and not holding(party, torch)
    says "Blue lights have come out on the water, one and then three, and they are drifting your way over the reeds like guests who have decided to walk you home. The boards under your feet are slick." {
    Assert e4BogSeen(rierdan). Set e4BogAt(rierdan) to watch(clock). }
  Rule rp_bog_clear when e4BogSeen(rierdan) and not at(party, wd_bog) { Retract e4BogSeen(rierdan). }
  Rule rp_bog_strikes at wd_bog when at(party, wd_bog) and e4BogSeen(rierdan) and watch(clock) >= e4BogAt(rierdan) + 2 and not holding(party, torch) and not e4LordTolerates(rierdan) and dice(clock) <= 14
    says "A hand you cannot see takes your elbow and walks you on, pleasantly, towards the water." {
    Assert strikes(bog_drown, party). }
  Action turn_coats(actor: group, site: place) "Turn your coats inside out, the old way, and keep to the middle of the ride" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wd_edge) and e4Hunt(rierdan) and not e4LordTolerates(rierdan) and not f_coats(rierdan).
    Time 1.
    Resolve check(actor, woodcraft, dc_fair).
    On success { Assert e4LordTolerates(rierdan). }
    On failure { Assert f_coats(rierdan). }
    Result "You do it as your grandmother did, with your teeth set. The wood, with great reluctance, loses interest. The ride is a ride again, and goes where it appears to.".
    Otherwise "It is a lining, and not a good one. The wood is not fooled.".
  }
  Action play_hautboy(actor: group, site: place) "Ask Tam to play the hautboy on the lawn, loud enough to carry into the wood" {
    Speaker tam.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wd_lawn) and at(tam, site) and e4Hunt(rierdan) and not e4LordTolerates(rierdan) and not f_haut(rierdan).
    Time 0.
    Resolve check(actor, performance, dc_fair).
    On success { Assert e4LordTolerates(rierdan). }
    On failure { Assert f_haut(rierdan). }
    Result "Tam puts the hautboy to his mouth, and for the first time in his life plays something he has not rehearsed. Far off in the wood the horn stops, mid-breath. A voice like honey says, to the trees, 'That is a badly made tune.' It does not move. It listens to the whole of it, and when it is over it says: 'More.'".
    Otherwise "The tune is correct. The Lord does not care for the correct.".
  }

  // The lovers: three ways to the pairs, and one price.
  Thing wd_ofbit "the ofbit" at wd_hollow is scenery { State growing "Low blue flowers, ofbit, grow round the bank in the moss, with delicate heads and thin stems; the wood's own old remedy for the heart.". }
  Initially Assert grows(wd_ofbit).
  Discovery wd_ofbit_hid "The ofbit round the pixie's bank is gathered, not found.".
  Item wd_ofbit_1 "a sprig of ofbit" is ofbit_gathered in wd_ofbit hidden until wd_ofbit_hid.
  Initially Assert crop(wd_ofbit_1, wd_ofbit).
  Item wd_ofbit_2 "a second sprig of ofbit" is ofbit_gathered in wd_ofbit hidden until wd_ofbit_hid.
  Initially Assert crop(wd_ofbit_2, wd_ofbit).
  Thing wd_poppy "the red poppies" at wd_hollow is scenery { State growing "Red poppies, heavy-headed, grow among the blue: the wood's own old remedy for the same thing.". }
  Initially Assert grows(wd_poppy).
  Discovery wd_poppy_hid "The red poppies are gathered, not found.".
  Item wd_poppy_1 "a handful of poppy heads" is poppy_gathered in wd_poppy hidden until wd_poppy_hid.
  Initially Assert crop(wd_poppy_1, wd_poppy).
  Item wd_poppy_2 "a second handful of poppy heads" is poppy_gathered in wd_poppy hidden until wd_poppy_hid.
  Initially Assert crop(wd_poppy_2, wd_poppy).
  Action anoint_true_a(actor: group, site: place) "Touch the lovers' eyes with poppy and let them sleep it off: all four, side by side" {
    Requires able(actor) and company(actor) and at(actor, site) and e4Hunt(rierdan) and at(rafe, site) and at(idony, site) and holding(actor, poppy_gathered) and loves(rafe, maud).
    Time 1.
    On success { Spend poppy_gathered from actor. Retract loves(rafe, maud). Retract loves(maud, rafe). Retract loves(idony, jack). Retract loves(jack, idony). Assert e4Slept(rierdan). }
    Result "You pinch the poppy over four pairs of eyelids and they lie down in the bracken like children. It is a clean sleep. When they wake they will remember the wedding, and the hats, and that there was someone they were fond of; they will not remember who.".
  }
  Action anoint_cross(actor: group, site: place) "Touch Rafe's eyes and Idony's with ofbit, so that each wakes to the other" {
    Requires able(actor) and company(actor) and at(actor, site) and e4Hunt(rierdan) and at(rafe, site) and at(idony, site) and holding(actor, ofbit_gathered) and loves(rafe, maud) and not e4Slept(rierdan).
    Time 1.
    Resolve check(actor, woodcraft, dc_fair).
    On success { Spend ofbit_gathered from actor. Retract loves(rafe, maud). Retract loves(maud, rafe). Retract loves(idony, jack). Retract loves(jack, idony). Assert loves(rafe, idony). Assert loves(idony, rafe). Assert loves(jack, maud). Assert loves(maud, jack). }
    On failure { Spend ofbit_gathered from actor. }
    Result "A little ofbit, the old rule: the first face seen. Rafe opens his eyes on Idony's hat and says 'My dear.' Wat, a yard off, opens his on Nan and cannot speak.".
    Otherwise "The sprig is too dry, or your hand is too quick; the juice runs into the moss. You have one fewer sprig, and four people who are still, tenderly, wrong.".
  }
  Action leave_them(actor: group, site: place) "Stand at the edge and let the lovers be as they are; it is none of the company's business" {
    Requires able(actor) and company(actor) and at(actor, site) and e4Hunt(rierdan) and at(rafe, site) and loves(rafe, maud) and not e4Gathered(actor).
    Time 6.
    On success { Assert e4Gathered(actor). Assert e4Left(rierdan). }
    Result "You nod. After all, the Squire will be in love with whoever he is told to marry by the time the bell goes. It has been done before.".
  }

  // The weaver and the Lady: the Lord's bargain.
  Action bargain_lord(actor: group, site: place) "Offer the Lord of the Green the thing he is quarrelling about: the Lady's changeling boy, for the weaver" {
    Speaker greenlord.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wd_glade) and at(greenlord, site) and e4LordTolerates(rierdan) and not e4LoomFree(rierdan) and not e4BargainFailed(rierdan).
    Time 0.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert e4LoomFree(rierdan). Retract at(loom, wd_ring). Assert at(loom, wd_lawn). Retract e4QueenLoves(rierdan). }
    On failure { Assert e4BargainFailed(rierdan). }
    Result "'You will tell the Lady,' says the Lord of the Green, 'that the boy she kept is to come home to my hall. And that the old wood is full.' His smile is dreadful. 'She will listen. She has been listening for seven years for someone to say it.' The weaver comes out of the ring with his own head, looking puzzled and well rested. 'What a dream,' says Barnaby Loom. 'I was a Wall.'".
    Otherwise "'No,' says the Lord, agreeably, and does not say it again.".
  }
  Action ask_the_ash(actor: group, site: place) "Ask the Ash whether she remembers the Lord of the Green's name" {
    Speaker ash.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wd_ash) and at(ash, site) and not e4NameKnown(rierdan) and not e4AshAsked(actor).
    Time 6.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert e4NameKnown(rierdan). Assert e4AshAsked(actor). }
    On failure { Assert e4AshAsked(actor). }
    Result "The ash is silent for a while, long enough for the shadow to move. 'He was born in a ditch,' she says, 'in a hard winter, and his mother called him Tod.' A branch creaks, which may be laughter. 'Say it in his hearing and see how big he is.'".
    Otherwise "'I remember everything,' says the ash. 'I do not remember you.'".
  }
  Action name_the_lord(actor: group, site: place) "Call the Lord of the Green by the name he was born with, and ask for the weaver" {
    Speaker greenlord.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wd_glade) and at(greenlord, site) and e4NameKnown(rierdan) and e4LordTolerates(rierdan) and not e4LoomFree(rierdan).
    Time 0.
    On success { Assert e4LoomFree(rierdan). Assert e4Humbled(rierdan). Retract at(loom, wd_ring). Assert at(loom, wd_lawn). Retract e4QueenLoves(rierdan). }
    Result "'Tod,' you say. The glade goes quiet. The Lord of the Green becomes, for the length of a breath, rather small. 'Take him,' he says. 'Take him and go, and never say it where the Lady can hear.' The weaver comes out of the ring with his own head, and says that he had a curious dream about a Wall.".
  }
  Action pay_name(actor: group, site: place) "Give the Lord of the Green your true name, in return for the weaver" {
    Speaker greenlord.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wd_glade) and at(greenlord, site) and e4BargainFailed(rierdan) and not e4NameKnown(rierdan) and not e4LoomFree(rierdan) and not e4Namepaid(actor).
    Time 0.
    On success { Assert e4Namepaid(actor). Assert e4Price(rierdan). Assert e4LoomFree(rierdan). Retract at(loom, wd_ring). Assert at(loom, wd_lawn). Retract e4QueenLoves(rierdan). }
    Result "You give it. It goes out of your mouth like a coin into a well. 'Thank you,' says the Lord, kindly, and takes it somewhere you cannot see. You find you have to think, for a moment, which of two people you are.".
  }
  Rule rp_robin at wd_hollow when e4Hunt(rierdan) and at(party, wd_hollow) and not robinStole(rierdan) and quantity(party, gold) >= 2
    says "The pixie drops onto your hat from nowhere, examines your purse with great courtesy, and removes two coins, a button and the dignity of the thing. 'For the bank,' it says. 'It has so few things.' It is pleased with you. It points out the poppy you were looking at." {
    Assert robinStole(rierdan). Decrease quantity(party, gold) by 2. Assert at(robin, wd_hollow). }
  Observe w_changeling near greenlord when e4Hunt(rierdan) and not e4LoomFree(rierdan) "At the Lord's heel, holding his goat-hair in one fist, stands a small boy of six in a coat of moss. He is not smiling. He is the thing the Lord and the Lady have been quarrelling over, a human child, since before the wedding was thought of.".

  // Dawn. The wedding goes ahead, in whatever pairs it finds.
  Rule rp_acted when e4Hunt(rierdan) and not e4Acted(rierdan) and (e4LoomFree(rierdan) or e4Slept(rierdan) or e4LordTolerates(rierdan) or loves(rafe, idony)) { Assert e4Acted(rierdan). }
  Observe w_left_told at wd_lawn when e4Left(rierdan) and e4Dawn(rierdan) and e4Fiasco(rierdan) "At first light the company stands at the back of the lawn with its arms folded, having decided it was none of its business, and has the grace to look as if it had not enjoyed it.".
  Rule rp_loom_pay when e4Done(rierdan) and e4LoomFree(rierdan) and not e4Paid(rierdan) { Assert e4Paid(rierdan). Increase quantity(party, gold) by 8. }
  Observe w_loom_pay at wd_lawn when e4Paid(rierdan) "The Squire's mother pays the fiddler, and, seeing the weaver in his own head, pays him as well, and he gives the company his half in the speech of a man who has just played a Lion for the first time to a full house.".
  Rule rp_pyramus when e4Dawn(rierdan) and puddingPyramus(party) and not e4LoomFree(rierdan) and not pyramusPlayed(rierdan) { Assert pyramusPlayed(rierdan). }
  Observe w_pyramus at wd_lawn when pyramusPlayed(rierdan) "With no weaver in his own head, Jem Pudding plays Pyramus. He dies seven times, on the carts, with three onions, and the third time the audience stands.".
  Rule rp_dawn when e4Hunt(rierdan) and not e4Dawn(rierdan) and hour(clock) >= 5 and hour(clock) < 12 and watch(clock) >= e4Dusk(rierdan) + 40 and at(rafe, ?a) and at(idony, ?b) and at(jack, ?c) and at(maud, ?d) {
    Assert e4Dawn(rierdan). Retract at(rafe, ?a). Assert at(rafe, wd_lawn). Retract at(idony, ?b). Assert at(idony, wd_lawn).
    Retract at(jack, ?c). Assert at(jack, wd_lawn). Retract at(maud, ?d). Assert at(maud, wd_lawn). }
  Rule rp_restored when e4Dawn(rierdan) and loves(rafe, idony) and loves(jack, maud) and not e4Done(rierdan) and not e4Price(rierdan) { Assert e4Restored(rierdan). Assert e4Done(rierdan). }
  Rule rp_priced when e4Dawn(rierdan) and loves(rafe, idony) and loves(jack, maud) and e4Price(rierdan) and not e4Done(rierdan) { Assert e4Restored(rierdan). Assert e4Done(rierdan). }
  Observe w_humbled at wd_lawn when e4Humbled(rierdan) and e4Dawn(rierdan) "The horn does not sound at sunrise. In the beech wood a goat-legged shape stands a long way back from the trees, with its arms folded, and does not come any nearer. The Lady's changeling boy is sitting on the Squire's mother's lap, eating a bun.".
  Rule rp_blank when e4Dawn(rierdan) and e4Slept(rierdan) and not e4Done(rierdan) { Assert e4Blank(rierdan). Assert e4Done(rierdan). }
  Observe w_blank at wd_lawn when e4Blank(rierdan) "The wedding goes ahead at sunrise between two people who like one another much and cannot say why. The Squire and Idony stand side by side with the faintly puzzled courtesy of people who have been introduced. Wat plays the fiddle as if he were mourning something. Gosse, at the side of the lawn, finds he has no complaint, and cannot account for the lump in his throat.".
  Rule rp_fiasco when e4Dawn(rierdan) and (loves(rafe, maud) or loves(jack, idony)) and not e4Done(rierdan) { Assert e4Fiasco(rierdan). Assert e4Done(rierdan). }
  Observe w_restored at wd_lawn when e4Restored(rierdan) and not e4Price(rierdan) "The wedding goes ahead at sunrise in the pairs it was meant for, with a long grey light, a fiddler who will not stop, and a lion who is good. Pyramus dies seven times. The Squire cries into his cuffs. Gosse, at the side of the lawn, finds that he is weeping, and that he has been enjoying himself.".
  Observe w_priced at wd_lawn when e4Restored(rierdan) and e4Price(rierdan) "The wedding goes ahead in the right pairs. At the vows one of the company says a name that is nearly theirs, and the Squire's mother looks round to see whom they are speaking to. Nobody says anything. In the grass at the edge of the lawn a pair of small hoof-prints goes away towards the wood.".
  Observe w_fiasco at wd_lawn when e4Fiasco(rierdan) "At sunrise Squire Hartigan, still beautifully in love, marries Nan Sellars before the whole village, and Wat Dunstable, shining, stands up for him, and weeps for Idony, who stands up for Nan with a smile on her face that is much too steady. The play follows. The Wall falls on the Lion. The Lion is a woman in a ram's mask, and nobody, afterwards, can say which of the villagers she was. The audience gives a standing ovation that lasts until noon.".
  Observe w_fiasco2 near gosse when e4Fiasco(rierdan) "Gosse has stopped saying it is not in the script. He sits on a hamper with the prompt-book on his knee and looks forgiven.".
  Chapter ch_wood "The Wood near Athens-under-Hollin" when e4On(rierdan) and not e4Done(rierdan) "A wedding at dawn, a play by a weaver, and a wood that has taken an interest.".
  Milestone m_wood_loom "got the weaver's head back" worth 200 when e4LoomFree(rierdan).
  Milestone m_wood_done "got the wedding to the lawn by dawn" worth 300 when e4Done(rierdan).
  Milestone m_wood_lord "was suffered by the Lord of the Green" worth 150 when e4LordTolerates(rierdan).

  // Pudding, who is to be Pyramus if the weaver is not; and who finds he can be.
  Topic pudding_part with pudding "Ask Jem Pudding whether he would play Pyramus if the weaver does not come back" when e4On(rierdan) and e4LoomAss(rierdan) once {
    Says "Jem Pudding puts down the onions. 'I am a juggler,' he says. 'I have said it so often it has set. I'd like to be a person who is Pyramus.' He looks at his hands. 'Do you think I could?'".
  }
  Topic pudding_yes with pudding "Yes. You were a clown before you were anything else" answering pudding_part when true {
    Says "'Oh,' says Pudding. He puts the onions in his pocket. 'Oh, that would be a thing.'".
    On discuss { Assert puddingPyramus(actor). }
  }
  Topic pudding_no with pudding "No. Stick to the juggling; it is a gift" answering pudding_part when true {
    Says "'Right,' says Pudding, relieved and a little crushed. He takes the onions out again.".
    On discuss { Assert puddingSings(actor). }
  }
  Relation puddingPyramus(group). Relation puddingSings(group).
  Observe pudding_p near pudding when puddingPyramus(party) "Pudding has begun to say the death-speech of Pyramus under his breath to the trees, and is better at it, now, than the weaver ever was.".
  Observe pudding_s near pudding when puddingSings(party) "Pudding has been juggling three onions behind the hampers all night, and dropping none.".
  Relation f_coats(place).
  Relation f_haut(place).
  Relation e4Acted(place).
  Relation e4Left(place).
  Relation e4Paid(place).
  Relation e4EdgeSeen(place).
  Relation e4BogSeen(place).
  Relation pyramusPlayed(place).
}

data/adventures/gosses-company/rier_cast:
Module pentrice "Gosse's Company" {
  // ── The summons, the road, and the people of Dun Rierdan ─────────────────────────────────────────────────────
  // After the verdict a herald comes to the Painted Moon with a writ: whatever the Bench decided, the King has heard.
  // The troupe goes ahead to the Brazen Sparrow; whoever follows finds them there, lodged on credit, rehearsing in a
  // loft with a chalk line down the middle. The company is not the only story in the city: the city has its own.
  Measure favour(place). Measure arrivedR(place). Measure standingR(place).
  Relation writHeld(group). Relation heraldGone(place).
  // The Pentrice epilogue waits for the herald: it closes only when the writ is refused, ignored for three hours, or the
  // book is not yet read. Once the company is summoned (and after, through Dun Rierdan) it does not close at all.
  Query pentriceCloses() means not summoned(pentrice) and not royalCall(pentrice) and (heraldGone(pentrice) or not verdictRead(pentrice)).
  Rule herald_leaves when verdictRead(pentrice) and not heraldGone(pentrice) and watch(clock) >= verdictAt(pentrice) + 180 { Assert heraldGone(pentrice). }
  Relation heraldWarned(place).
  Rule herald_warns when verdictRead(pentrice) and not heraldGone(pentrice) and not heraldWarned(pentrice) and watch(clock) >= verdictAt(pentrice) + 150 and inCity()
    says "A servant of the Painted Moon is leading a tall horse out of the stable to the mounting-block, and the herald in blue is standing in the yard looking at the sun. He will not wait much longer." { Assert heraldWarned(pentrice). }
  Topic aubrey_refuse with aubrey "Tell Aubrey Lintel the company has had enough of masters, and will stay" when verdictRead(pentrice) and not heraldGone(pentrice) once {
    Says "'Ah,' says Aubrey Lintel, who has been refused by better, and says it kindly. 'I shall say you were indisposed. It is what the Household says, when it does not wish to know.' He remounts as though the yard had been laid for it. 'The King is eighty-one. He will not remember.'".
    On discuss { Assert heraldGone(pentrice). }
  }

  Person aubrey "Aubrey Lintel" nowhere {
    Role "a herald of the King's Household, in a tabard with a crowned tower on it". Ancestry human. Peaceable. Pronouns he. Manner proud.
    Arrives at moon_yard when verdictRead(pentrice).
    Arrives "A horse comes in under the Moon's arch with a man on it in a tabard of seven blue towers, and the whole yard stops to look. He dismounts as though the cobbles had been laid for it.".
    Greets "'I am sent,' says Aubrey Lintel, 'to the players that played The Alderman's Ghost, or the ones that did not, and to anyone who was in the house or says so.' He consults a roll, upside down, and rights it. 'His Majesty, Casimir of the House of Orvane, has been told a story of the Trial, and wishes the story to be played for him. That is all. It is not a command. It is not a command in a way that has never in the history of the Household been refused.'".
  }
  Topic aubrey_writ with aubrey "Take the King's writ" when verdictRead(pentrice) and not summoned(pentrice) once {
    Says "He gives you a writ, sealed in blue wax with a tower, and holds out the other hand for you to kiss it, and, on seeing your face, puts it away. The writ is addressed to GOSSE'S COMPANY OF PLAYERS AND SUCH AS GO WITH THEM, and it says: COME TO DUN RIERDAN BY THE KING'S ROAD, BEING FOUND SUFFICIENT, AND PLAY. Under it, in a different hand, someone has added: BRING THE BEAR.".
    On discuss { Assert summoned(pentrice). Assert heraldGone(pentrice). Assert writHeld(actor). Assert knows(actor, writ_known). }
  }
  Discovery writ_known "King Casimir Orvane has sent a writ to Gosse's Company to come to Dun Rierdan by the King's Road, and play.".
  Topic aubrey_why with aubrey "Ask Aubrey Lintel why the King has heard of them" when true once {
    Says "'Because the King,' says Aubrey, 'is eighty-one and has not been amused since the Siege of Thrall. The Chamberlain keeps a list of things that might do it. A Trial of three companies and a riot is the first new thing on it in three years.' He considers. 'He is also, I am told, afraid of something, and would like to be somewhere else for an evening. I did not say that.'".
  }

  // The troupe goes ahead. They lodge at the Sparrow until they have a house of their own.
  Rule royal_arrival when at(party, road_head) and summoned(pentrice) and not royalCall(pentrice) {
    Assert royalCall(pentrice). Set arrivedR(rierdan) to day(clock). Set favour(rierdan) to 0.
    Assert at(the_bear, sparrow_taproom). }
  // Whoever is still of the company lodges at the Sparrow; whoever left it in Pentrice is found where they went.
  Relation lodged(group). Relation dorcasFound(group). Relation swaleFound(group). Relation clemArrived(group).
  Rule lodge_troupe when royalCall(pentrice) and troupe(?p) and not lodged(?p) and not houseGranted(rierdan) { Assert lodged(?p). Assert at(?p, sparrow_loft). }
  Rule lodge_troupe_wick when royalCall(pentrice) and troupe(?p) and not lodged(?p) and houseGranted(rierdan) { Assert lodged(?p). Assert at(?p, lant_ward). }
  Rule dorcas_found when royalCall(pentrice) and dorcasGone(dorcas) and not dorcasFound(dorcas) { Assert dorcasFound(dorcas). Assert at(dorcas, rot_front). }
  Rule swale_found when royalCall(pentrice) and swaleGone(swale) and not swaleFound(swale) { Assert swaleFound(swale). Assert at(swale, sparrow_taproom). }
  Rule clem_follows when royalCall(pentrice) and not clemArrived(clemency) { Assert clemArrived(clemency). Assert troupe(clemency). Assert lodged(clemency). }
  Topic dorcas_return with dorcas "Ask Dorcas whether the Rotunda is all she thought it would be" when royalCall(pentrice) and dorcasGone(dorcas) once {
    Says "Dorcas Quaile is sitting in the Rotunda's front of house in a gown she did not pay for, drinking something clear. 'It has a roof,' she says. 'It has a Fallow. It has a Lord Rask who is the second-largest man in the realm and the first-most-patient.' She turns the glass. 'Master Gosse is the King's, they say. Is there a part?' It is the nearest she will come to saying it.".
  }
  Topic dorcas_home with dorcas "There is a part, and a wardrobe, and a Gosse who has not got over you" answering dorcas_return when true {
    Says "'He has not,' says Dorcas. 'He told me a thing in Pentrice and I was a coward.' She puts down the glass. 'I'll come. I'll want it in writing that I was not asked to.' She is already getting up.".
    On discuss { Assert dorcasHome(actor). }
  }
  Topic dorcas_stay_rask with dorcas "Stay where you are, then. The roof is real" answering dorcas_return when true {
    Says "Dorcas looks at you for a good while. 'Thank you,' she says. 'Nobody has said that to me and meant it.' She finishes the glass.".
  }
  Relation dorcasHome(group). Relation swaleHome(group).
  Rule dorcas_returns when dorcasHome(party) and dorcasGone(dorcas) { Retract dorcasGone(dorcas). Assert troupe(dorcas). Assert lodged(dorcas). Assert at(dorcas, lant_ward). }
  Topic swale_return with swale "Ask Swale what brings a man of his gifts to a taproom in Dun Rierdan" when royalCall(pentrice) and swaleGone(swale) once {
    Says "Ambrose Swale rises, magnificently, and sits again. 'I heard,' he says. 'In a coach, from a tallow-chandler, that Gosse had been sent for by the King. I thought: he will want a Ghost.' He studies his hands. 'I did not think: he will not want me. I thought it afterward, on the road, and I am here, and I am drunk, and it is a splendid city.'".
  }
  Topic swale_back with swale "He wants you. He has never said so" answering swale_return when true {
    Says "Swale puts both hands over his face. 'He has not,' he says through them. 'Nineteen years. He has not said it once.' He drops them. 'Take me to him before I think better of it.'".
    On discuss { Assert swaleHome(actor). }
  }
  Rule swale_returns when swaleHome(party) and swaleGone(swale) { Retract swaleGone(swale). Assert troupe(swale). Assert lodged(swale). Assert at(swale, lant_ward). }
  // The Trial's outcome, carried by the people it happened to.
  Observe gosse_patent near gosse when royalCall(pentrice) and patentWon(pentrice) "Gosse has the Patent of the Wheel in a leather tube, and takes it out to look at when he thinks nobody sees. It does not say what he thought it would say. It says he owes the Office a quarter's rent.".
  Observe gosse_pension near gosse when royalCall(pentrice) and pensionTaken(gosse) "Gosse wears Fallow's thirty crowns like a good coat that belongs to someone else. He is gracious about it and does not speak of the Trial.".
  Observe gosse_neither near gosse when royalCall(pentrice) and not patentWon(pentrice) and not pensionTaken(gosse) "Gosse has no Patent and no pension, and the grey patience of one who has been refused a roof before, in a better year.".
  Observe hepzibah_wife near hepzibah when royalCall(pentrice) and (proposed(gosse) or emptyWing(gosse)) "Hepzibah Dimmock is Mrs Gosse, and writes it in the prompt-book's margin in a small hand when she thinks nobody is looking, and then rubs it out.".
  Observe kit_voice at sparrow_loft when royalCall(pentrice) and kitVoiceHeld(kit) "Kit Arden's voice has held through the winter, on a spoonful of honey a day and a great deal of will. He is sixteen, and plays girls, and is aware that this is a loan.".
  Observe kit_broke at sparrow_loft when royalCall(pentrice) and not kitVoiceHeld(kit) "Kit Arden's voice broke somewhere between Pentrice and the River Gate, and he plays the girls now in a falsetto he hates, and knows exactly how many more months it has.".
  Observe fallow_won near fallow when royalCall(pentrice) and not patentWon(pentrice) "Corin Fallow holds the Patent of the Wheel and is, accordingly, a power in a bigger room, which he has taken the trouble to learn the shape of.".
  Observe fallow_lost near fallow when royalCall(pentrice) and patentWon(pentrice) "Corin Fallow lost the Patent of the Wheel to Gosse's Company and has been given the Rotunda by way of a consolation. He is gracious about it, and has made a list.".
  Topic clem_left with clemency "Ask Clemency Orde why she left the Office of Plain Speech" when royalCall(pentrice) and clemBowed(clemency) once {
    Says "'I stood up on the stage of the Wheel before the City and said I had written it,' says Clemency Orde, 'and a Master of Plain Speech cannot be seen to have written a play. It is an Ordinance. I wrote the Ordinance.' She smooths the page. 'My father was the Lord Mayor Gosse made a fool of. I did not forgive Gosse for forty years. I have been surprised to find that I would like to be in the room when he is forgiven.'".
  }
  Topic clem_leave with clemency "Ask Clemency Orde what a Master of Plain Speech wants in a theatre" when royalCall(pentrice) and not clemBowed(clemency) once {
    Says "'I am on leave,' says Clemency Orde, 'which is to say that I did not ask permission.' She does not smile. 'My father was a Lord Mayor Gosse made a fool of, and he loved me, and he is dead. I wrote a play about him for the man who mocked him, which is not what the Office calls plain.' She looks at the stage. 'I should like to see what he does with it. In a room where nobody is counting.'".
  }
  // When the Crown gives the company the Wick, it lodges there: in the wardrobe, among the hampers.
  Rule troupe_to_wick_loft when troupe(?p) and houseGranted(rierdan) and distinct(?p, clemency) and at(?p, sparrow_loft) and not holdingAct(rierdan) { Retract at(?p, sparrow_loft). Assert at(?p, lant_ward). }
  Rule troupe_to_wick_taproom when troupe(?p) and houseGranted(rierdan) and distinct(?p, clemency) and at(?p, sparrow_taproom) and not holdingAct(rierdan) { Retract at(?p, sparrow_taproom). Assert at(?p, lant_ward). }
  Query rehoused() means houseGranted(rierdan).
  Relation houseGranted(place).
  Rule rtroupe_taproom when troupe(?p) and royalCall(pentrice) and distinct(?p, clemency) and at(?p, sparrow_loft) and hour(clock) >= 18 and hour(clock) < 23 and not holdingAct(rierdan) and not tamPicket(rierdan) and not houseGranted(rierdan) {
    Retract at(?p, sparrow_loft). Assert at(?p, sparrow_taproom). }
  Rule rtroupe_loft when troupe(?p) and royalCall(pentrice) and distinct(?p, clemency) and at(?p, sparrow_taproom) and (hour(clock) >= 23 or hour(clock) < 18) and not holdingAct(rierdan) and not tamPicket(rierdan) and not houseGranted(rierdan) {
    Retract at(?p, sparrow_taproom). Assert at(?p, sparrow_loft). }
  Relation holdingAct(place).

  // ── The Crown ────────────────────────────────────────────────────────────────────────────────────────────────
  Person casimir "King Casimir Orvane" at audience {
    Role "King of the Seven Towers, eighty-one". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "The King is a small bright-eyed old man in a coat too large for him. He watches you come the length of the rug without moving, as one watches a play, and says in a high clear voice when you reach the end: 'You are shorter than the herald said.'".
  }
  Person pyke "Sir Ferrand Pyke" at closet {
    Role "the King's Chamberlain, keeper of the Book of Names". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Greets "Sir Ferrand Pyke is a long thin man who stands with his hands behind him in a room that cannot fit them. He consults his book before he answers anything, even a greeting, and writes down what he has said.".
  }
  Person mallam "Osbert Mallam" at closet {
    Role "the Chamberlain's clerk". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "Osbert Mallam is twenty-two and has been up all night, and is in the best of spirits about it. 'The masquers!' he cries. 'Splendid! Do sit. Is that a bear? Which of you does the voices?'".
  }
  Person lothar "Prince Lothar Orvane" at terrace {
    Role "the King's grandson and heir, nineteen". Ancestry human. Peaceable. Pronouns he. Manner grim.
    Greets "The young man in black does not turn. 'You are the players,' he says to the Concourse. 'You will have noticed the whole city is lit and nobody is looking at the dark.' He turns at last. He has the face of someone who has stopped sleeping out of politeness.".
  }
  Person tallis "Sergeant Hob Peverell" at river_gate {
    Role "sergeant of the River Gate". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "The sergeant looks up from the ledger and his face does something complicated. 'Marchant's masquers!' he says. 'You're late! His Lordship's steward has been down here four times since breakfast with a face like a boiled ham.' He turns a page. 'How many of you? He said eight, and a bear.'".
  }

  // The Marchants: the Chancellor's house, with a daughter and a son nobody has been told apart from.
  Person marchant "Lord Lisle Marchant" at marchant_hall {
    Role "the Lord Chancellor of Dun Rierdan". Ancestry human. Peaceable. Pronouns he. Manner proud.
    Greets "Lord Lisle Marchant is a short stout man in a robe of office, who stands in his own hall as though it were a courtroom and you had come to prove the roof. 'I understand,' he says, 'you are the masquers. I understand you are to perform in the presence of the King on his Name-Day. I understand that nobody will tell me what you will say.'".
  }
  Person simm "Beadle Simm" at marchant_hall {
    Role "the Marchants' steward". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "The steward has the face of a boiled ham and the manner of one who has waited on the same family for forty years and has decided to say nothing about any of it. He looks at you, and at Kit if Kit is with you, and lets his eyes do the arithmetic.".
  }
  Person oriel "Oriel Marchant" at rot_wings {
    Role "a page of the Rotunda, small and sharp-faced". Ancestry human. Peaceable. Pronouns she. Manner cheerful.
    Known as "Orrin, a page of the Rotunda" when not knows(party, oriel_unmasked).
    Greets "A slight page in the Rotunda's blue, with soot on one cheek and a prompt-copy under his arm, looks at you with sharp interest. 'You're players,' he says, and the word is a different word in his mouth than in anyone else's. 'True ones. Not Master Fallow's.'".
  }
  Discovery oriel_unmasked "The Rotunda's page Orrin is Lady Oriel Marchant, the Chancellor's daughter, who has been living in the wings as a boy for six weeks.".
  Person cyprian "Cyprian Marchant" at marchant_hall {
    Role "the Chancellor's son, a lieutenant of the Watch". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "A young man in the Watch's grey and pewter comes down the stair two at a time and stops in front of you with his mouth open. 'You,' he says. It is odd to be looked at as though you were a ghost, and a welcome one.".
  }

  // The Rotunda's master: Corin Fallow, who won the Patent and is now being a power in a bigger room.
  Rule fallow_moves when royalCall(pentrice) and at(fallow, ?x) and distinct(?x, rot_front) and distinct(?x, rot_stage) and distinct(?x, lant_stage) { Retract at(fallow, ?x). Assert at(fallow, rot_front). }

  // The Towers.
  Person dray "Lord Warden Cassian Verrall" at king_court {
    Role "the Warden of the Realm, the King's hand in the Seven Seats". Ancestry human. Calling warrior. Level 3. Peaceable. Pronouns he. Manner grim.
    Greets "Lord Warden Cassian Verrall is a lean grey man of sixty with a soldier's back and the habit of speaking in separate words so that he cannot be misquoted. 'The law,' he says, when you are introduced, as if it were a surname. 'You have come to see it done.'".
  }
  Person lucan "Lucan Verrall" at dust_gate {
    Role "the Warden's son, a captain of the Household". Ancestry human. Calling warrior. Level 2. Peaceable. Pronouns he. Manner compassionate.
    Greets "A broad young captain in blue leans on a pillar of the colonnade with a book open on his knee, a thing that has plainly cost him some effort to be seen doing. He shuts it when you come near.".
  }
  Person tarn "Marshal Edric Marrick" at lamp_hill {
    Role "Marshal of the Watch, in the Tower of Lamps". Ancestry human. Calling warrior. Level 4. Peaceable. Pronouns he. Manner proud.
    Greets "The Marshal of the Watch is a big, handsome, sincere man of fifty with a scar like a signature across the back of one hand. 'Players!' he says, with pleasure. 'Good. This city has too many lawyers and not enough plays. I should like to see one where the right man wins.'".
  }
  Person ysolt "Ysolt Marrick" at bell_nave {
    Role "the Marshal's daughter, an acolyte of the Bells". Ancestry human. Peaceable. Pronouns she. Manner compassionate.
    Greets "A young woman in the grey of an acolyte is on her knees at the foot of the great rope, very straight, as one kneels who has been taught to. She gets up when you come near and the knees of her robe are worn.".
  }
  Person ambros "Brother Ambros" at ringers_loft {
    Role "the blind ringer of the Bells". Ancestry human. Peaceable. Pronouns he. Manner grim.
    Greets "A blind man with a face like a closed fist turns toward your footstep before you have made it. 'You walk like an actor,' says Brother Ambros. 'You walk as though somebody were looking.'".
  }
  Person salt_wives "the Salt-Wives" at salt_hall {
    Role "three old women of the guild of Salt, who keep the weather-lore of the city". Ancestry human. Numbers 3. Peaceable. Pronouns they. Manner acerbic.
    Greets "Three women in grey look up as one. The eldest says: 'Rain by Thursday.' The second says: 'And a fall by Friday.' The third says nothing at all, and smiles, and it is the smile of someone who has seen the end of the play.".
  }
  Person crake "Master Isidore Mauger" at crake_room {
    Role "a moneylender of the Tower of Coin". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "Master Mauger rises like a friendly sunrise. 'The King's Players!' he says. 'Or soon to be. How good of you to call. I have heard so much, and written down so much more.' He sits, and you notice you are sitting too.".
  }
  Person pardew "Mistress Pardew" at draper {
    Role "the draper, who dresses the Rotunda and everyone else". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "Mistress Pardew looks you over once, from the hat down, and says: 'Four crowns and an alteration.' She has not asked you what you want. She knows exactly what you want.".
  }
  Person rask "Lord Anselm Rask" at rot_box {
    Role "a young lord of leisure, and the Rotunda's most generous patron". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "A smooth, smiling young man with an orchid in his buttonhole rises from the royal box as if the Rotunda belonged to him, which in a manner of speaking it does. 'I adore the theatre,' he says. 'I adore everyone in it. Who are you, and are you spoken for?'".
  }
  Person printer "Master Gabriel Gadsby" at print_row {
    Role "a printer of quartos, not licensed". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "A man with ink to the elbow looks up from a press he is not supposed to be running. 'The Players?' he says. 'You'll want a copy of yourselves. I've done four.'".
  }
  Rule gammage_follows when royalCall(pentrice) and at(gammage, ?x) and distinct(?x, playhouse_row) { Retract at(gammage, ?x). Assert at(gammage, playhouse_row). }
  Rule rot_home_rot_front when troupe(?p) and royalCall(pentrice) and nightOver(rierdan) and distinct(?p, clemency) and at(?p, rot_front) and not holdingAct(rierdan) { Retract at(?p, rot_front). Assert at(?p, sparrow_loft). }
  Rule rot_home_rot_stage when troupe(?p) and royalCall(pentrice) and nightOver(rierdan) and distinct(?p, clemency) and at(?p, rot_stage) and not holdingAct(rierdan) { Retract at(?p, rot_stage). Assert at(?p, sparrow_loft). }
  Rule rot_home_rot_wings when troupe(?p) and royalCall(pentrice) and nightOver(rierdan) and distinct(?p, clemency) and at(?p, rot_wings) and not holdingAct(rierdan) { Retract at(?p, rot_wings). Assert at(?p, sparrow_loft). }
  Rule rot_home_rot_flies when troupe(?p) and royalCall(pentrice) and nightOver(rierdan) and distinct(?p, clemency) and at(?p, rot_flies) and not holdingAct(rierdan) { Retract at(?p, rot_flies). Assert at(?p, sparrow_loft). }
  Rule rot_home_rot_box when troupe(?p) and royalCall(pentrice) and nightOver(rierdan) and distinct(?p, clemency) and at(?p, rot_box) and not holdingAct(rierdan) { Retract at(?p, rot_box). Assert at(?p, sparrow_loft). }
  Relation heraldNews(place).
  Rule herald_news when verdictRead(pentrice) and not heraldNews(pentrice) and not heraldGone(pentrice) and inCity()
    says "The crier of the Chepe, who has the Bench's verdict by heart, has a second piece of news and gives it with the same lungs: a herald of the King's Household is in the yard of the Painted Moon, in blue, and will wait there for the players of the Wheel till noon tomorrow, and not after." { Assert heraldNews(pentrice). }
  Observe chancellor_posed near marchant when posing(party) "Lord Marchant has the masquers' letter of engagement open on his desk, and holds it up beside your faces as though one of them would turn out to be a forgery. 'Masquers,' he says, to the room. 'You will understand that I know every masquer in this city by his gait.' He does not say whether he has found the gait.".
  Observe chancellor_plain near marchant when not posing(party) and gateHonest(party) "Lord Marchant has been told, by a sergeant with a good memory, who you are. 'The Pentrice people,' he says, with a lawyer's relief. 'Good. Then the lie is somebody else's, and I can be wronged by it in comfort.'".
}

data/adventures/gosses-company/rier_side:
Module pentrice "Gosse's Company" {
  // ── Dun Rierdan by the way: errands that do not touch the main line ───────────────────────────────────────────
  // A ghost-light that burns untrimmed, a pirate printer, a procession of herring, a street-company without a licence,
  // and two more who will come along: Cyprian Marchant of the Watch, who is impulsive and honest, and Oriel, who is
  // neither. The city's institutions are what they are; the errands are what the people in them want this week.
  Relation lightLit(place). Relation lightOut(place). Relation lightLeft(place). Relation printerSmashed(place).
  Relation printerHired(place). Relation printerBought(place). Relation herringKing(group). Relation herringSkipped(group).
  Relation mummersLicensed(place). Relation mummersTold(group). Relation cyprianWith(group). Relation puddingBrave(group).
  Relation puddingFool(group). Relation tamStood(group). Relation tamBack(group).

  // 1. The Wick's ghost-light: nine years, and nobody trims it.
  Topic fallow_wick with fallow "Ask Corin Fallow about the Wick" when royalCall(pentrice) and not lightLit(rierdan) and not lightOut(rierdan) once {
    Says "Corin Fallow, who is wearing a hat, raises it. 'The Wick,' he says. 'Thrale's house. Marcus Thrale played Macbeth on that stage on a Friday, and on the Saturday he was found in the flies with his hand on the light-cord. They say he is still trimming it.' He puts the hat back. 'Nobody has gone in since. It's bad for business to be seen frightened of a stage.' He is frightened of the stage. Ask him what he thinks you should do, and he will say: 'I'd leave it.'".
  }
  Action trim_the_light(actor: group, site: place) "Trim the ghost-light's wick yourself, and say Thrale's name" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lant_stage) and not lightLit(rierdan) and not lightOut(rierdan).
    Time 2.
    Resolve check(actor, performance, dc_fair).
    On success { Assert lightLit(rierdan). }
    On failure { Assert lightLit(rierdan). Assert lightLeft(rierdan). }
    Result "You trim it. You say, to the empty house, 'Marcus Thrale,' and the flame stands up straight and goes a clear white. Something that has been waiting for nine years sits down in the back row. For the rest of your stay the Wick's boards will not creak, and Pudding will swear that the prompt-book turns its own pages.".
    Otherwise "You trim it a little crooked, and the flame lies down and sulks. It will burn another nine years, at that rate.".
  }
  Action put_out_the_light(actor: group, site: place) "Put out the ghost-light, and let the dead man go to bed" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lant_stage) and not lightLit(rierdan) and not lightOut(rierdan).
    Time 1.
    On success { Assert lightOut(rierdan). }
    Result "You put the cage's door aside and pinch the flame. The whole house goes dark in a single breath. From the flies, distinctly, a man's voice says 'Thank you,' in the weary tone of a stagehand told he may go home, and the Wick is only a theatre.".
  }
  Observe lit_light at lant_stage when lightLit(rierdan) and not lightLeft(rierdan) "The ghost-light burns white at the centre of the stage. Whoever trims it does not leave a mark.".

  // 2. Quill Alley: the pirate, and what he will print.
  Topic gadsby_pirate with printer "Ask Master Gadsby about the four-page Alderman's Ghost" when royalCall(pentrice) and not printerSmashed(rierdan) and not printerHired(rierdan) and not printerBought(rierdan) once {
    Says "Gabriel Gadsby cuts a corner off the nearest sheet and shows you where he has misspelled Gosse's name. 'Four pages of a play,' he says. 'Taken down by a boy in the pit. Eight hundred sold, and not a penny to the author, and I am the nearest thing to a literary man this city has.' He wipes the type. 'You can break my press. People do. You can buy my copies; they're good paper. Or you can give me the right text and let me print it clean and sell it under the Wick's name, and share.' He holds up a finger. 'I should like to be paid.'".
  }
  Action smash_the_press(actor: group, site: place) "Take Tam's sledge to Master Gadsby's press" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, print_row) and not printerSmashed(rierdan) and not printerHired(rierdan) and not printerBought(rierdan).
    Time 3.
    On success { Assert printerSmashed(rierdan). }
    Result "It takes six minutes and Tam's sledge. Gadsby watches with his arms folded, and at the end says, mildly, 'That was my grandfather's.' He sweeps the type into a sack. There will be a new press in Hog Lane by Thursday.".
  }
  Action hire_the_printer(actor: group, site: place) "Give Gadsby a clean text, and half the profit, and a name on the title-page" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, print_row) and not printerSmashed(rierdan) and not printerHired(rierdan) and not printerBought(rierdan) and masqueChosen(actor).
    Time 1.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert printerHired(rierdan). Increase quantity(actor, gold) by 12. }
    Result "Gadsby reads Hepzibah's fair copy through twice. 'This,' he says, 'is why I became a printer.' The title-page says THE KING'S PLAYERS in the largest type he has. Twelve crowns come back by the end of the week, and a bill for the paper.".
    Otherwise "'Half,' says Gadsby, 'is what I give my own mother. You may have a third.' He is right, and neither of you knows it.".
  }
  Action buy_the_quartos(actor: group, site: place) "Buy up Gadsby's pirate copies, all eight hundred" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, print_row) and quantity(actor, gold) >= 12 and not printerSmashed(rierdan) and not printerHired(rierdan) and not printerBought(rierdan).
    Time 1.
    On success { Decrease quantity(actor, gold) by 12. Assert printerBought(rierdan). }
    Result "Twelve crowns and Gadsby carries them out on his back, in four trips, and stacks them in the Wick's wardrobe. Jem Pudding uses the first for kindling and has to be told what they are.".
  }

  // 3. The herring procession: the Salt-Wives want a King.
  Topic salt_procession with salt_wives "Ask the Salt-Wives about the procession on the quay" when royalCall(pentrice) and not herringKing(party) and not herringSkipped(party) once {
    Says "The eldest looks at you and her face is without expression. 'The Herring King,' she says. 'On the feast of the Shoal. Every year a man is dressed in nets and silver paper and carried the length of the Quay on a hurdle and thrown in the dock. It has always been a fishmonger. We would like it this year to be a player.' The second wife says, 'It's a great honour.' The third holds her tongue and is already smiling.".
  }
  Topic herring_yes with salt_wives "I'll be your Herring King" answering salt_procession when true {
    Says "'Splendid,' says the eldest, with a warmth that is a little too prompt. 'The net is in the back.' You are dressed in silver paper. You are carried down the Quay by eight fishwives, singing, and thrown in the dock to cheers, and come up with a herring in your coat that you never discover the source of. Nothing in the city is ever so friendly as it is that afternoon.".
    On discuss { Assert herringKing(actor). Give herring_kind to actor. }
  }
  Topic herring_no with salt_wives "I'll send a better man, in my place" answering salt_procession when true {
    Says "'Ah,' says the eldest. 'A man in his place.' She considers. 'We should like to meet him.' It is a threat. It is also a courtesy. In the afternoon Jem Pudding, who has never been asked to do anything with such evident delight, is dressed in paper and carried off.".
    On discuss { Assert herringSkipped(actor). Assert puddingFool(actor). }
  }
  Kind herring_kind "a silver herring from the Quay" is gear described "A herring cut from tin-leaf, on a ribbon. It is the Herring King's badge, and it admits you to every fishwife's kitchen on the Quay.".

  // 4. The mummers: a street company without a licence, and the sergeant who has to arrest them.
  Topic peverell_mummers with tallis "Ask Sergeant Peverell about the troupe he is not arresting" when royalCall(pentrice) and not mummersLicensed(rierdan) and not mummersTold(party) once {
    Says "Sergeant Peverell looks at his boots. 'There's a troupe of five in the Gate Street,' he says. 'Doing the Siege of Thrall on a barrel. No licence. I've got to take them in by the Chamberlain's rule and I'd as soon take in my own mother.' He lowers his voice. 'They have a boy who does the horse. The sergeant before me took his father in. I haven't the heart. If a company with a patent were to take them on as a street branch, so to speak, I'd have no cause.'".
  }
  Action license_the_mummers(actor: group, site: place) "Take the mummers on as the King's Players' street branch, on Gosse's name" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, river_gate) and (provisional(rierdan) or titleByAccident(rierdan) or bookCorrected(actor)) and not mummersLicensed(rierdan).
    Time 2.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert mummersLicensed(rierdan). Assert mummersTold(actor). }
    Result "Peverell ticks them in under a title that does not exist, THE KING'S PLAYERS (OUT OF DOORS), and goes pink with pleasure. The boy who does the horse is given a ribbon. He turns out to be the best horse in the city. The Chamberlain will have this in a book, soon, in the wrong column.".
    Otherwise "'Not in the Chamberlain's book,' says Peverell. 'I'd have to put your name to it. I'd have to put it to the Household.' He is as sorry as one who can be.".
  }

  // The companions. Cyprian is impulsive and brave; he does not ask what you want him for.
  Topic cyprian_join with cyprian "Ask Cyprian Marchant whether he would come along, in the Watch's name or not" when twinsMet(party) and not cyprianWith(party) once {
    Says "'Come along?' says Cyprian. 'Of course. Where?' He has not asked what for. 'I'm no good in a play,' he says. 'But I can stand at a door.' He thinks. 'That's a thing in a play, isn't it? Standing at a door. I should like to be good at it.'".
    On discuss { Assert willing(cyprian, actor). Set hire(cyprian) to 0. Assert cyprianWith(actor). }
  }

  // Jem Pudding wants to be taken seriously; Tam Hautboy wants his men paid.
  Topic pudding_beat with pudding "Ask Jem why he's so quiet" when edictOn(rierdan) and not actIIIDone(rierdan) and not puddingBrave(party) and not puddingFool(party) once {
    Says "Jem Pudding is balancing an onion on his nose and not looking at anyone. 'I'm going to be asked,' he says, 'to be the Fool in the Chorus, in the Marshal's tragedy, in the Field.' He lets the onion fall. 'I've never played a Fool at a funeral. A Fool does not belong at a funeral. He has nothing to say there that is not a joke.' He looks at you. 'What does a clown do at a funeral?'".
  }
  Topic jem_silent with pudding "Nothing. He stands there and is sad" answering pudding_beat when true {
    Says "Jem looks at you. 'That's not a part,' he says, and then: 'Is it? Is it a part?' A great change comes over him. He gets up. He puts on his Fool's coat, and he takes the bells off it. He stands in the middle of the wardrobe for a quarter of an hour, perfectly still, and the rest of the company, who come in and out for hampers, step round him as round a monument.".
    On discuss { Assert puddingBrave(actor). }
  }
  Topic jem_joke with pudding "A joke. The one the dead man would have liked" answering pudding_beat when true {
    Says "Jem's face does a number of things. 'Ah,' he says. 'Yes. Well. If I knew him.' He sits down on a hamper. 'I knew the Marshal. He once stood me a pint in the Row and told me I was the only honest man in the Rotunda's pay. I'll do a joke.' He goes quiet. 'I'll find one he'd have liked,' he says. He will be ten days at it.".
    On discuss { Assert puddingFool(actor). }
  }
  Topic tam_beat with tam "Ask Tam why the carpenters haven't been paid" when wickGranted(rierdan) and not tamStood(party) and not tamBack(party) once {
    Says "Tam Hautboy sets down the plane. 'Because Mauger has sixty days on the fit-out and the men have sixty days on their own,' he says. 'They'll stay for a promise. They won't stay for a rope.' His hands are steady. 'I'll tell them to go on. I'll tell them the Wick will pay on opening. I'll tell them that, if that's what you want me to say.' He looks at you. 'Or I'll stand with them. I've only ever had the one trade.'".
  }
  Topic tam_promise with tam "Tell them the Wick will pay on opening" answering tam_beat when true {
    Says "'Right,' says Tam, and puts on his coat. He goes out to the carpenters at the back door. He is gone an hour. When he comes back he has a face that says he has spent it. 'They'll stay,' he says. 'Now we'd better pay.'".
    On discuss { Assert tamBack(actor). Decrease quantity(actor, gold) by 10 or to nothing. }
  }
  Topic tam_stand with tam "Stand with the carpenters. We'll pay them, or we'll go dark" answering tam_beat when true {
    Says "Tam takes off his apron. For the first time in the whole engagement he is alone, a thin man in the middle of the wardrobe with a plane in his hand. 'Yes,' he says. 'Well. I thought you might.' He goes out to the back door. The sound of carpenters putting down their tools comes in like a long breath.".
    On discuss { Assert tamStood(actor). Assert tamPicket(rierdan). }
  }
  Relation tamPicket(place).
  Rule tam_strike_ends when tamStood(party) and heistOver(rierdan) and tamPicket(rierdan) { Retract tamPicket(rierdan). }
  Milestone m_light "kept, or let go of, the ghost-light" worth 100 when lightLit(rierdan) or lightOut(rierdan).
  Milestone m_printer "settled the pirate" worth 100 when printerSmashed(rierdan) or printerHired(rierdan) or printerBought(rierdan).
  Milestone m_herring "was carried down the Quay, or sent a man" worth 100 when herringKing(party) or herringSkipped(party).
  Milestone m_mummers "took in the street company" worth 100 when mummersLicensed(rierdan).

  // Cyprian and Oriel: the Watch and the father, in three beats each (the join, the question, and the scene on the stage).
  Relation cyprianResigned(group). Relation cyprianBoth(group). Relation orielTells(group). Relation orielStage(group). Relation orielAsked(group). Relation cyprianAsked(group).
  Topic cyprian_watch with cyprian "Ask Cyprian what the Watch will say to a lieutenant who goes on a stage" when cyprianWith(party) and not cyprianAsked(party) once {
    Says "Cyprian Marchant considers the pewter on his collar. 'There is a regulation,' he says. 'Against lieutenants being in a play. I wrote the regulation. I was nineteen and I thought plays were for people who could not lift anything.' He turns the collar over. 'The Marshal signed it.' He looks at his boots. 'He is a good man to have against you in an argument and a bad one to have for you in a ditch.'".
    On discuss { Assert cyprianAsked(actor). }
  }
  Topic cyprian_resign with cyprian "Hand in the pewter, then. A lieutenant is a small thing to be" answering cyprian_watch when true {
    Says "'Yes,' says Cyprian, with the face of someone told his tooth is out. He unpins the pewter and puts it in his purse. 'My father will be a good deal worse than my commander.' He puts the purse away, and takes it out again, and looks at the pewter, and puts it back.".
    On discuss { Assert cyprianResigned(actor). }
  }
  Topic cyprian_both with cyprian "Keep it. A man can be a lieutenant and a player" answering cyprian_watch when true {
    Says "'I'll be a laughing-stock,' says Cyprian, delighted. 'I'll be the only lieutenant of the Watch who can do the sword-fight in the third act with the right foot.' He has already decided; he only needed it said.".
    On discuss { Assert cyprianBoth(actor). }
  }
  Topic oriel_say with oriel "Ask Oriel what she means to say to her father" when travelsWith(oriel, party) and not orielAsked(party) once {
    Says "Oriel Marchant is sitting on a hamper with the Chancellor's seal in a clay impression in her lap, turning it over. 'I thought: the Wick,' she says. 'On the stage, in front of the Household, in my own voice, in a part, so that he cannot make a scene because it will be one.' She looks up. 'Or I tell him in the Concourse, tomorrow, at his own door, and let him be furious in private. Which is the braver?'".
    On discuss { Assert orielAsked(actor). }
  }
  Topic oriel_tell with oriel "Tell him first, tomorrow, at his door" answering oriel_say when true {
    Says "'Item,' says Oriel, counting on her fingers. 'A trick forgives nobody; a plain statement forgives itself. Item: he is a lawyer, and will respect a disclosure made before witnesses.' She stands. She puts the seal in your hand. 'Hold this, as evidence of my having surrendered it.'".
    On discuss { Assert orielTells(actor). }
  }
  Topic oriel_stage with oriel "On the stage, in the part, in your own voice. He cannot shout at a play" answering oriel_say when true {
    Says "'Good,' says Oriel, quick as a latch. 'A statement made in a part is a statement made in a part. He cannot call a play perjury.' She grins, which she does rarely, and looks about eleven. 'I had the argument drafted. I wanted it countersigned.'".
    On discuss { Assert orielStage(actor). }
  }
  Observe s5_oriel_told at lant_stage when sceneV(rierdan) == 5 and orielTells(party) "Lord Marchant has been told, and has had a day to be furious in, and has come to the Wick in his second-best coat with his spectacles in his hand. He looks at his daughter on the stage the way one looks at a piece of news that has taken a good while to arrive.".
  Rule oriel_stage_costs when holdingCommand(rierdan) and sceneV(rierdan) == 5 and orielStage(party) and not orielPaid(rierdan) and at(party, lant_stage)
    says "Oriel steps into the light in her own voice, in front of the Household, and says her name; and in the second tier the Chancellor of the Realm stands up with a noise like a chair being sat on by a horse." { Assert orielPaid(rierdan). Increase chaos(rierdan) by 1. }
  Relation orielPaid(place).
  Observe s5_cyprian_resigned at lant_stage when sceneV(rierdan) == 5 and cyprianResigned(party) "Cyprian is in the wings in a plain brown coat with a pale place on the collar where the pewter was, and his hands, now that they have nothing to do, do not know where to go.".
  Observe s5_cyprian_both at lant_stage when sceneV(rierdan) == 5 and cyprianBoth(party) "Cyprian is in the wings in the Watch's grey with the pewter polished, and a stage-sword in the other hand, and is the happiest man in the Wick.".
  Observe jem_funeral_brave at field when puddingBrave(party) and bodyStaged(rierdan) "Jem Pudding stands at the foot of the bier in the Fool's coat with the bells off it, perfectly still. The sextons, who have heard a Chorus and a verdict and are no longer sure what is allowed, take their hats off first, because of him.".
  Observe jem_funeral_fool at field when puddingFool(party) and bodyStaged(rierdan) "Jem Pudding steps out at the end of the burial and tells the Marshal's joke, the one with the pint and the Watch's pay. It is a bad joke. The sextons laugh before they can stop themselves, and a woman in the back of the crowd says, loudly, that Edric would have, too.".
  Observe jem_pays_grave at ringers_loft when puddingBrave(party) and ysoltSealed(rierdan) "Somebody has hung a Fool's coat with the bells off it on the peg inside the ringers' ladder. Ambros, who cannot see it, says the Bells have not been so quiet since the Siege.".
}

data/adventures/gosses-company/road/link:
Module westmarch "The road across the march" {
  // The road across the march from Wending Cross to Pentrice, for the campaign played alone (in a generated world the
  // frontier lays this road itself).
  Place here "Where the road leaves" is room.
  Place there "Where the road comes in" is room.
  Passage march "the road across the march" is road between here and there taking 2 hours.
  Goal false.
}

data/adventures/gosses-company/supper.ky:
Module pentrice "Gosse's Company" {
  // ── The Bench's supper ──────────────────────────────────────────────────────────────────────────────────────────
  // After the last night of the Trial the four judges sup at the Orde house on Hill Street, by Ezra Orde's custom,
  // which his widow keeps to annoy them: nobody votes till they have eaten, and nobody eats till they have said one
  // true thing about the play. It is La Critique de l'École des femmes played in Pentrice: Urania Orde is the hostess,
  // reasonable and mischievous; her daughter the Master, at the window, agrees with everyone ironically; Sukey Rowe
  // announces the dishes; Canon Mallory cannot bring himself to say the word; Nym Carrow has one argument and says it
  // whenever there is a silence; Ormsby Clay has the rules; Dame Thalia Gammage has the yard. A company that came
  // (invited by the Master, Dame Gammage, Tunstall or the widow herself, or in by the kitchen as a waiter) may speak,
  // once in each course, and what it says moves the Bench, who vote at ten. Without it, the supper goes on all the
  // same, and the Bench votes as it came in.
  //
  // Eight courses of two watches each, from an hour after the play, at the parlour: each tells what is said, then
  // what is said next, then (if the company spoke) how it was taken.
  Measure supperBeat(place). Measure supperAt(place). Measure endedAt(place).
  Relation supperOn(place). Relation supperOver(place). Relation bedFor(group, place).
  Kind course. Entity course_one: course "the true things". Entity course_two: course "the soup". Entity course_three: course "the verb".
  Entity course_four: course "the pie". Entity course_five: course "the old days". Entity course_six: course "the tally".
  Entity course_seven: course "the straw vote". Entity course_eight: course "the carriages".
  Relation courseOpen(course). Relation spoke(course).
  Query atSupper(a: group) means at(a, orde_parlour) and (guest(a) or servant(a)).
  Query midCourse() means watch(clock) >= supperAt(pentrice) + 1.
  Query courseDone() means watch(clock) >= supperAt(pentrice) + 2.
  Query speaking(a: group) means atSupper(a) and supperOn(pentrice) and midCourse().

  Rule supper_begins when playEnded(pentrice) and ghostPlay(pentrice) and watch(clock) >= endedAt(pentrice) + 6 and not supperOn(pentrice) and not supperOver(pentrice) {
    Assert supperOn(pentrice). Set supperBeat(pentrice) to 1. Set supperAt(pentrice) to watch(clock). }
  // The Bench, the Master and the clerk go up to the Hill; Sukey keeps the door.
  Rule supper_gathers when supperOn(pentrice) and critic(?c) and at(?c, ?p) and not at(?c, orde_parlour) { Retract at(?c, ?p). Assert at(?c, orde_parlour). }
  Rule supper_clerk when supperOn(pentrice) and at(tunstall, ?p) and not at(tunstall, orde_parlour) { Retract at(tunstall, ?p). Assert at(tunstall, orde_parlour). }
  Rule supper_master when supperOn(pentrice) and at(clemency, ?p) and not at(clemency, orde_parlour) { Retract at(clemency, ?p). Assert at(clemency, orde_parlour). }
