    On success { Assert shadStopped(shad). Assert playbills(inchbald). Retract at(shad, moon_loft). Assert at(shad, press_room). }
    On failure { Assert triedBills(actor). }
    Result "Inchbald considers it with his head on one side. 'Five hundred bills,' he says. 'In red. Posted at every corner and the Westgate and the Stairs.' He considers longer. 'A quarto's a week's trade. A company that likes me is a season's.' He calls Shad home and sets you a playbill instead: GOSSE'S COMPANY! THE ALDERMAN'S GHOST! A BEAR!".
    Otherwise "'A quarto's money in the hand,' says Inchbald, 'and players is promises.'".
  }
  Relation triedBills(group).
  Rule bills_posted when playbills(inchbald) and not spread(bills_known) and inCity()
    says "By evening Inchbald's playbills are on every corner of Pentrice, in red, with a bear on them." { Assert spread(bills_known). }
  Discovery bills_known "Inchbald has posted Gosse's Company's playbills all over Pentrice.".
  // Fallow takes the quarto to the Office; the Office takes an unlicensed book where it finds it within the walls.
  Rule fallow_informs when quartoPrinted(pentrice) and tday(pentrice) >= 3 and not fallowGrateful(fallow) and not informed(fallow) and not pensionTaken(gosse) { Assert informed(fallow). }
  Relation informed(group).
  Rule book_seized when informed(fallow) and tday(pentrice) >= 3 and hour(clock) >= 15 and state(book, copy_fair) and not bookInSoke(pentrice) and not seizedOnce(pentrice) {
    Assert state(book, copy_seized). Assert seizedOnce(pentrice). }
  Relation seizedOnce(place).
  Rule seized_told when state(book, copy_seized) and not spread(seized_known) and inCity()
    says "Abel Tunstall comes up the Moon's loft stair at three in the afternoon with two clerks and an Office warrant, very civil, and takes the fair copy of The Alderman's Ghost off Hepzibah's trestle as unlicensed matter found within the walls, on information. 'It will be kept at the Office,' he says, 'pending.' Pending what, he does not say." { Assert spread(seized_known). }
  Discovery seized_known "The Office has seized the fair copy of The Alderman's Ghost from the Moon as unlicensed matter, on Corin Fallow's information.".
  Action carry_book(actor: group, site: place) "Carry the fair copy over the river to the Wheel, out of the City's reach" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, moon_loft) and inCompany(actor) and state(book, copy_fair) and not bookInSoke(pentrice) and week()
      and not watermenStrike(pentrice).
    On success { Assert bookInSoke(pentrice). }
    Result "Hepzibah wraps the fair copy in its oilcloth again and gives it to you without a word, and you take it over the river in a waterman's boat with your arm round it, and up Soke Lane, and give it to the Wheel's keeper to lock in the tiring-house press, under the Liberty's law. 'The book will rehearse in the Soke from now on,' says Hepzibah, when you come back. 'It's a long way to go for a book.'".
  }
  // A seized book may come back: from its author, who keeps the Office; out of the Master's room, by a hand that is not
  // seen; or not at all, and then by the Ordinances it is burned in Guildhall Square at noon on the last day.
  Topic clem_return with clemency "Ask the Master to give the fair copy back" when state(book, copy_seized) and clemTold(clemency) and not clemCold(clemency) once {
    Says "The Master takes the fair copy out of the drawer of her desk, where it has been lying under her hand all afternoon. 'Seized on information,' she says. 'Corin Fallow's. Who has never once in his life informed on anybody, and has chosen my play.' She gives it to you. 'Take it over the river,' she says. 'Tonight. And do not bring it back inside the walls until it is played.'".
    On discuss { Assert state(book, copy_fair). Assert bookInSoke(pentrice). }
  }
  Action steal_book(actor: group, site: place) "Take the fair copy back out of the drawer of the Master's desk" {
    Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, master_room) and state(book, copy_seized) and not at(clemency, master_room) and not triedSteal(actor).
    Resolve check(actor, stealth, dc_hard).
    On success { Assert state(book, copy_fair). Assert bookInSoke(pentrice). }
    On failure { Assert triedSteal(actor). }
    Result "The Master's desk drawer is not locked; it holds the fair copy, and a pen, and a dried primrose, and nothing else. The book goes under your coat. You are out of the Office and down Fish Lane before the clerks look up, and over the river before you breathe.".
    Otherwise "A clerk is in the Master's doorway as you open the drawer, and you shut it again, and say you were looking for the Master, and he says she is at home.".
  }
  Relation triedSteal(group).
  Rule book_burned when state(book, copy_seized) and tday(pentrice) >= 4 and hour(clock) >= 12 { Assert state(book, copy_burned). }
  Rule burned_told when state(book, copy_burned) and not spread(burned_known) and inCity()
    says "At noon, in Guildhall Square, by the Fountain of Concord, the common hangman burns the fair copy of The Alderman's Ghost on a brazier, as the Ordinances provide for unlicensed matter found within the walls. Abel Tunstall reads the order. A small crowd watches. Up in the window of the Master's room, somebody stands for the whole of it and does not move." { Assert spread(burned_known). }
  Discovery burned_known "The fair copy of The Alderman's Ghost was burned in Guildhall Square by order of the Office.".
}

data/adventures/gosses-company/troupe.ky:
Module pentrice "Gosse's Company" {
  // ── Gosse's Company ─────────────────────────────────────────────────────────────────────────────────────────────
  // Six players, a prompter and a bear, lodged in the loft over the Painted Moon's stables. By day they are in the loft;
  // in the evening in the taproom; on the fourth night at the Wheel.
  Relation troupe(group).
  Initially Assert troupe(gosse). Initially Assert troupe(hepzibah). Initially Assert troupe(swale). Initially Assert troupe(dorcas).
  Initially Assert troupe(pudding). Initially Assert troupe(kit). Initially Assert troupe(tam).
  Rule troupe_to_taproom when troupe(?p) and not royalCall(pentrice) and at(?p, moon_loft) and hour(clock) >= 18 and hour(clock) < 23 and not playingTonight(pentrice) {
    Retract at(?p, moon_loft). Assert at(?p, moon_taproom). }
  Rule troupe_to_loft when troupe(?p) and not royalCall(pentrice) and at(?p, moon_taproom) and (hour(clock) >= 23 or hour(clock) < 18) {
    Retract at(?p, moon_taproom). Assert at(?p, moon_loft). }

  Person gosse "Absalom Gosse" at moon_loft {
    Role "the actor-manager of Gosse's Company". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "Absalom Gosse is a big old man in a coat that was crimson once, with a voice made for open air and a face that has been every king in Imbar. 'Ah,' he says, turning the whole of himself toward you as if you were the house. 'You.'".
    Wants parcel_kind.
  }
  Observe gosse_here near gosse when not knows(party, deaf_seen) "Gosse stands a little to the right of whoever he is talking to, always, and tilts his head as if listening to music.".
  Person hepzibah "Hepzibah Dimmock" at moon_loft {
    Role "the company's prompter". Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Greets "Hepzibah Dimmock looks up from the book: a small grey woman with spectacles on a ribbon and a pencil in her hair. She waits for you to say what you want, and does not help.".
    Offers lodging "a pallet in the loft among the hampers" for 1 coin.
  }
  Person swale "Ambrose Swale" at moon_loft {
    Role "the company's tragedian". Ancestry human. Peaceable. Pronouns he. Manner proud.
    Greets "Ambrose Swale turns from the window, where he has been saying 'Ay' to himself in several different keys, and inclines his head to you a measured inch. He is a tall man with a beautiful ruined face, and he holds himself as though there were a crown on it.".
    Wants mothers_letter.
    Wants gull_note.
  }
  Person dorcas "Dorcas Quaile" at moon_loft {
    Role "the company's leading lady". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "Dorcas Quaile is darning a stocking with her feet up on a hamper and a book of the play open on her knee. She has a wonderful mobile face, and she uses all of it to look you up and down. 'Well,' she says. 'Gosse said there'd be someone.'".
    Wants old_notice.
  }
  Person pudding "Jem Pudding" at moon_loft {
    Role "the company's clown". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "Jem Pudding is sitting on the floor of the loft juggling three onions, badly, on purpose. 'Mind the onions,' he says. 'They are rehearsing.'".
  }
  Person kit "Kit Arden" at moon_loft {
    Role "the boy who plays the girls". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "Kit Arden is fifteen, all elbows and eyelashes, and is sitting very straight on a hamper holding a pot of something warm in both hands as though it were precious.".
  }
  Person tam "Tam Hautboy" at moon_loft {
    Role "the company's hired man: carpentry, music and small parts". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "Tam Hautboy is planing a length of wood with a hautboy sticking out of his coat pocket. He nods to you and goes on planing.".
  }
  Species bear_of_company "an old dancing bear" like bear tame described "A big brown bear, grey about the muzzle, with a leather collar and no teeth to speak of. She smells of honey and straw and is very gentle.".
  Person the_bear "Patience" at moon_yard {
    Role "the company's bear". Species bear_of_company. Peaceable. Pronouns she.
    Greets "Patience lifts her chin off her paws to look at you, sniffs, and puts it down again, satisfied.".
  }

  // ── Coming to the company ───────────────────────────────────────────────────────────────────────────────────────
  // Said wherever he is (the loft by day, the taproom of an evening); what he has to tell depends on whether the play has
  // come yet, or is still in the ostler's keeping.
  Topic gosse_back with gosse "Tell Gosse you have come, as you said on the green" when knows(actor, joined) and not toldGosseCame(actor) and bookCome(pentrice) once {
    Says "Gosse gets up and embraces you, which is like being embraced by a feather bed with opinions. 'Faithful!' he says. 'Hepzibah, the faithful one has come.' Hepzibah, without looking up, writes something in the book. 'You lodge here, in the loft, for nothing, because nothing is what we have. You will carry, you will hold the book, you will very possibly act.' He holds you off at arm's length. 'And something has happened, my friend. A play has come to us. Out of the air.'".
    On discuss { Assert toldGosseCame(actor). }
  }
  Topic gosse_back_early with gosse "Tell Gosse you have come, as you said on the green" when knows(actor, joined) and not toldGosseCame(actor) and not bookCome(pentrice) once {
    Says "Gosse gets up and embraces you, which is like being embraced by a feather bed with opinions. 'Faithful!' he says. 'Hepzibah, the faithful one has come.' Hepzibah, without looking up, writes something in the book. 'You lodge here, in the loft, for nothing, because nothing is what we have. You will carry, you will hold the book, you will very possibly act.' He lowers his voice. 'And something is waiting for us, my friend, in this very inn: a parcel, left for the Fool of the Wheel the night of the riot. Which is me. The ostler does not believe it. Find out what he wants.'".
    On discuss { Assert toldGosseCame(actor). }
  }
  Relation toldGosseCame(group).
  Topic gosse_green with gosse "Ask Gosse whether he remembers you from the green" when knows(actor, freed) and not knows(actor, joined) and not inCompany(actor) once {
    Says "'Remember!' says Gosse. 'The one who got the chain off our wheel! Hepzibah!' Hepzibah looks up and, for once, smiles. 'You would not sign on, then,' says Gosse, 'and I bear no grudge, because I am a magnanimous man and because I mean to ask you again now.'".
  }
  Topic gosse_hire with gosse "Ask Gosse whether the company needs a hand for the Trial" when not inCompany(actor) and week() and not pensionTaken(gosse) once {
    Says "'Needs!' says Gosse. 'We are a handful of players, a prompter and a bear, to play a comedy of eleven parts in a round house before the Bench of four on the last night of the Trial. We need a hand. We need hands. We need a Tapwell, a chain-man, a carrier of hampers and a person to stand in the wings.' He considers you. 'A season's work, a share of the house, a pallet in the loft, and all the applause you can carry. Yes or no?'".
  }
  Topic gosse_sign with gosse "Tell Gosse you will take service with the company" when not inCompany(actor) once {
    Says "'Done,' says Gosse, and seizes your hand. 'Hepzibah, write it down.' Hepzibah writes it down. 'You are one of us. You will discover that this is a mixed blessing, like all blessings and most of the gods.'".
    On discuss { Assert inCompany(actor). }
  }
  Topic gosse_tally with gosse "Tell Gosse you are signed on as a tallyman with the Office for the week" when tallyman(actor) once {
    Says "Gosse stares at you, and then laughs until he has to sit down on a hamper. 'A tallyman!' he says. 'The Office pays you sixpence a night to sit in the front row and count my sins! My friend, I will give you sins worth counting.' He wipes his eyes. 'Stay a tallyman. Sit on the grey bench. A friend in the front row is worth two in the wings.'".
  }
  Topic gosse_profession with gosse "Tell Gosse you are of the profession yourself" when craft(actor, craft_stage) and not knows(actor, freed) once {
    Says "Gosse looks at you as one player looks at another across a green: the hands, the feet, the way you stand when you are not standing for anyone. 'So you are,' he says. 'So you are. Then you know what this is,' and he spreads his arms as if to take in every company that ever was. 'You know what four days are. God help you, you know.'".
  }

  // ── Gosse ───────────────────────────────────────────────────────────────────────────────────────────────────────
  Topic gosse_patent with gosse "Ask Gosse about the Patent" when not knows(actor, freed) once {
    Says "'A roof,' says Gosse. 'Forty-one years I have played under the sky, on greens and in barns and in the yards of inns, and I have been rained on in every country of Imbar. The Patent is the Wheel, my friend, the Wheel itself, for us, every night, for as long as there is a company called Gosse's. A house. No more roads.' He looks at the window. 'Hepzibah thinks I am too old to stop walking. Hepzibah thinks a great many things she does not say, which is why I have kept her thirty-four years.'".
  }
  Topic gosse_riot with gosse "Ask Gosse about the last time he played in Pentrice" when true once {
    Says "Gosse's whole face lights up. 'The riot!' he says. 'Forty years ago, my friend, at the Wheel, I was twenty-three and playing a fool in a thing called The Miser's Wedding, and the Lord Mayor himself was in the gallery, Ezra Orde, a man shaped like a pudding in a chain, and in the second act the miser's fool has a line about a man who weighs his gold and his wife in the same scales, and I looked up at the gallery, and I said it to him.' He spreads his hands. 'And I added a little. And the pit took it up, and carried it over the river, and the City sang it for two nights, and within the week they made the Office of Plain Speech to see it never happened again, and banned Absalom Gosse from every stage inside the walls for ever.' He beams. 'I made an Office. How many players can say that?'".
    On discuss { Assert knows(actor, riot_gosse). }
  }
  Discovery riot_gosse "Forty years ago at the Wheel, playing a fool, the young Absalom Gosse said something to Lord Mayor Ezra Orde in the gallery that the pit took up and sang through the City for two nights; within the week, the Office of Plain Speech was founded, and Gosse was banned from every stage inside the walls." { Known by gosse, hepzibah. }

  // What happened before the company came: Fallow's pension, offered on the first morning (see town.kyr).
  Topic gosse_pension with gosse "Ask Gosse about Corin Fallow's offer" when fallowOffered(gosse) and not pensionTaken(gosse) once {
    Says "'A pension,' says Gosse, with great contempt. 'Thirty crowns a year from the Mayor's Servants, for as long as I live, to put my name to a paper saying I retire from the profession. A little house by the Ise. A garden.' He is quiet a moment. 'He means it kindly, the devil. That is what I cannot forgive.' He looks round the loft. 'And what becomes of them? Swale to Fallow, to carry a spear. Dorcas to the wardrobe. Pudding to the fairs. Kit to whatever boys become. Hepzibah —' He stops.".
  }
  Action advise_pension(actor: group, site: place) "Tell Gosse to take Fallow's pension, and stop walking" {
    Speaker gosse. Time 5 minutes.
    Grave "If Gosse puts his name to Fallow's paper, Gosse's Company is finished: there will be no play, and the players will go their ways.".
    Requires able(actor) and company(actor) and at(actor, site) and at(gosse, site) and fallowOffered(gosse) and not pensionTaken(gosse)
      and week() and not playingTonight(pentrice).
    On success { Assert pensionTaken(gosse). }
    Result "Gosse hears you out without a word, which you have never seen him do. Then he sits down on the wooden throne and puts his big hands on his knees. 'Yes,' he says, at last. 'Yes. I am tired. I have been tired for a long time.' He looks at Hepzibah, who does not look up from the book. 'Fetch me a pen, somebody. I shall want it to have a speech in it.'".
  }
  Relation pensionTaken(group). Relation fallowOffered(group).

  // ── Hepzibah and the book ───────────────────────────────────────────────────────────────────────────────────────
  // As the book came: once the parts are changed, the cast list in the loft says how they stand.
  Topic hepz_cast with hepzibah "Ask Hepzibah who plays whom" when bookCome(pentrice) and plays(dorcas, part_bell) and plays(kit, part_widow) once {
    Says "Hepzibah turns the book round so you can see the cast list, written in pencil and rubbed out so often the paper is furry. 'The Ghost, Swale. Sir Rowley Pomfret, Absalom, and the Prologue. Lob, Pudding. The Tallyman, Tam, in a beard. Bell, the daughter, nineteen,' she taps it, 'Dorcas, who has told everybody so. The Widow, Kit, because Dorcas will not, and he is fifteen and will play her like his own grandmother. Master Tapwell, the young lover,' she taps again, 'nobody. If nobody, I read him from the wings in my own voice, and God help the house.' She looks up. 'It is a good play. It is the best play I have read in thirty-four years. And we have cast it like a pig's breakfast.'".
    On discuss { Assert knows(actor, cast_trouble). }
  }
  Discovery cast_trouble "Dorcas Quaile has claimed Bell, the nineteen-year-old daughter, though the Widow is the better part and hers by right; Kit Arden is down for the Widow; and nobody is playing Master Tapwell, the lover, so Hepzibah will read him from the wings." { Known by hepzibah. }
  Topic hepz_quarrel with hepzibah "Ask Hepzibah why Swale and Pudding never speak" when true once {
    Says "'Nine years,' says Hepzibah. 'Swale's mother died at Galt, on the road, and we buried her in a churchyard in the rain, and Jem Pudding stood at the grave and told a joke. A good one. Everyone laughed but Ambrose.' She turns a page. 'There is more, and it is Jem's to tell, not mine.' She puts her hand flat on the book. 'I will say that I have something of hers in here, that Jem gave me to keep the night of the funeral, and that I have kept it nine years because nobody asked.'".
    On discuss { Assert knows(actor, mother_letter_known). }
  }
  Discovery mother_letter_known "Ambrose Swale's mother asked Jem Pudding to tell a joke at her burying, and left a letter for her son saying so; Hepzibah Dimmock has kept it in the book for nine years." { Known by hepzibah, pudding. }
  Kind mothers_letter "a letter in an old woman's hand" is gear worth 0 weighing 0
    described "A folded letter, soft with keeping, addressed in a big careful hand: For my son Ambrose, after.".
  Item swale_letter "the letter from Swale's mother" is mothers_letter at moon_loft hidden until letter_given.
  Discovery letter_given "Hepzibah has given you Mrs Swale's letter for her son.".
  Action ask_letter(actor: group, recipient: member, site: place) "Ask Hepzibah for Mrs Swale's letter, to give to Swale" {
    Speaker hepzibah. Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(hepzibah, site) and knows(actor, mother_letter_known)
      and memberOf(recipient, actor) and awake(recipient) and not knows(actor, letter_given) and not reconciled(swale) and not swaleGone(swale).
    Resolve acquire(swale_letter, mothers_letter, recipient).
    On success { Assert knows(actor, letter_given). Retract at(swale_letter, moon_loft). }
    Result "Hepzibah takes the letter out from between the pages of the book, where it has pressed itself flat, and holds it a moment. 'Give it him at the window,' she says, 'where he can turn his back on us,' and gives it to you.".
  }
  Initially Assert lends(hepzibah, swale_letter, party).

  // Gosse cannot hear the prompt any more, from his left; Hepzibah has known for a year, and says nothing.
  Discovery deaf_seen "Absalom Gosse is going deaf, in the left ear worst: he misses a prompt given from that side, and covers it.".
  Topic hepz_deaf with hepzibah "Ask Hepzibah about Gosse's hearing" when knows(actor, deaf_seen) and not promptWing(actor) once {
    Says "Hepzibah takes her spectacles off, which is the most emotion you have seen her show. 'A year,' she says. 'Worse these three months. He thinks I don't know. He has learned every play in the repertory by heart so that he will not need me, and he does need me.' She folds the spectacles. 'I prompt from the left side, the book side. It has always been the left side. On the night, I want someone in the right-hand wing who knows the play, to give him his line from his good side if he dries.' She looks at you. 'Will you?'".
  }
  Topic hepz_wing with hepzibah "Tell Hepzibah you will stand in the right-hand wing on the night" when knows(actor, deaf_seen) and inCompany(actor) and not promptWing(actor) once {
    Says "'Good,' says Hepzibah, and puts her spectacles back on. 'Learn his cues. I'll mark them for you.' She marks them, in red pencil, in a copy of the scenes, and gives it to you without another word.".
    On discuss { Assert promptWing(actor). }
  }
  Relation promptWing(group).
  Rule deaf_told when tday(pentrice) >= 3 and inCompany(party) and not knows(party, deaf_seen) and at(party, moon_loft) and at(hepzibah, moon_loft)
    says "Hepzibah catches your sleeve as you pass her trestle, and says, low, with her eyes on the page: 'You'll have seen it. Absalom can't hear from the left any more. He covers it. Don't tell him you know.'" teaches deaf_seen { }

  // ── The property chest ──────────────────────────────────────────────────────────────────────────────────────────
  Thing chest "the property chest" at moon_loft {
    Holds.
    State locked closed "A big old chest with brass corners and GOSSE painted on the lid, locked.".
    State open "The property chest stands open: crowns of paste, a sceptre, a skull, a bundle of letters tied with tape, a roll of old playbills.".
    Change pick "Pick the property chest's lock" from locked to open needing lockwork.
  }
  Topic hepz_chest with hepzibah "Ask Hepzibah to open the property chest" when state(chest, locked) and inCompany(actor) once {
    Says "Hepzibah gives you the key off her chatelaine without asking why, which is how you know you are one of the company now.".
    On discuss { Assert state(chest, open). }
  }
  Kind paste_crown "Gosse's crown of paste" like old_glossary granting persuasion worth 0 weighing 1
    described "A king's crown of gilt tin set with glass, much mended, that Absalom Gosse has worn as every king in Imbar. Inside the band, in ink, a list of names and towns going back forty years, and at the end of it, newer: yours. Whoever wears it stands as if a house were watching.".
  Item crown "the crown of paste" is paste_crown at wheel hidden until crown_given.
  Discovery crown_given "Absalom Gosse has given you his crown of paste, with your name written in the band.".
  Kind letter_bundle "a bundle of letters" is gear worth 0 weighing 0
    described "Thirty or forty letters tied with old tape, every one addressed, none ever sent: My dear H. My dearest H. H —.".
  Item letters "a bundle of letters tied with tape" is letter_bundle in chest.
  Kind riot_playbill "an old playbill" is gear worth 0 weighing 0
    described "A playbill, brown as toast: GOSSE'S COMPANY, AT THE WHEEL, THE MISER'S WEDDING, WITH A JIG. The Fool: Mr A. Gosse. And a date forty years gone.".
  Item gosse_bill "Gosse's old playbill" is riot_playbill in chest.
  Initially Assert lends(gosse, letters, party). Initially Assert lends(gosse, gosse_bill, party).
  Discovery letters_read "In the property chest are thirty-odd letters from Absalom Gosse to Hepzibah Dimmock, written over thirty years and never sent: love letters, mostly about the weather, the takings and the bear.".
  Action read_letters(actor: group, site: place) "Read the letters in the property chest" {
    Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, moon_loft) and state(chest, open) and inside(letters, chest)
      and not knows(actor, letters_read).
    On success { Assert knows(actor, letters_read). }
    Result "You should not, and you do. They are not long. 'My dear H., rain at Galt, the takings four coin and a ham. Patience is off her food. You were very good tonight in the second act.' 'My dearest H., I have bought you a shawl and given it to Dorcas because I could not think how to explain it.' 'H. — If I were a younger man.' 'H. — If I were a braver one.' The last is dated this year, and is only one line: 'H. — I can't hear you any more on the left side, and you know it, and I know you know.'".
  }
  Topic hepz_letters with hepzibah "Tell Hepzibah you have read the letters in the chest" when knows(actor, letters_read) once {
    Says "Hepzibah goes on writing for a while. 'Eleven years,' she says. 'I found them looking for a skull.' She blots the line. 'I put them back. He doesn't know I know. I'd thank you not to tell him, and not to tell me any more about them, and to remember that I am fifty-nine and have prompted that man through four thousand nights and could prompt him through this one.' She looks at you over her spectacles. 'He has to say it himself. Somewhere he can't take it back.'".
  }
  Topic gosse_hepz with gosse "Ask Gosse about Hepzibah" when bookCome(pentrice) and not gosseMeans(gosse) once {
    Says "Gosse is a long time answering. 'You have read the epilogue,' he says. 'Who walks first. The Ghost walks first, and then Pomfret, and then everybody, and at the end Pomfret turns to the house and asks their pardon, and asks a lady for her hand, because it is a comedy.' He looks across the room at Hepzibah, who has her back to him. 'I shall not ask the house. I shall turn to the wing, where she is, with the book, and ask her. On the stage, in front of the City, so that I cannot take it back.' He clears his throat. 'Will you see that she is there? In the wing, at the end. It is the one thing I ask.'".
    On discuss { Assert gosseMeans(gosse). }
  }
  Relation gosseMeans(group).

  // ── Ambrose Swale and the Ghost's lines ─────────────────────────────────────────────────────────────────────────
  Topic swale_part with swale "Ask Swale what he thinks of his part" when bookCome(pentrice) once {
    Says "'The Ghost,' says Swale, and something in his face comes alive. 'Verse. Real verse, in a comedy, God knows why. A man who will not lie down. Listen.' He lifts a hand. '“I rise, sirs, as I always rose: unbidden, and too soon, and much too long.”' He lets the hand fall. 'The pathos of it. A man's whole public life in a line.' Behind him, Pudding has put both hands over his face. Swale does not notice. Swale has not, you realise, ever noticed.".
    On discuss { Assert knows(actor, swale_innocent). }
  }
  Discovery swale_innocent "Ambrose Swale does not hear the double meanings in the Ghost's lines, which are the bluest in the play: he thinks them pathetic, and plays them so." { Known by pudding, dorcas, hepzibah, gosse. }
  Action tell_swale(actor: group, site: place) "Tell Swale what the Ghost's lines mean" {
    Speaker swale. Time 5 minutes.
    Grave "Once he knows, he will never hear the lines the same way again.".
    Requires able(actor) and company(actor) and at(actor, site) and at(swale, site) and knows(actor, swale_innocent)
      and not swaleKnows(swale) and week().
    On success { Assert swaleKnows(swale). }
    Result "You tell him. You have to explain three of them twice. Ambrose Swale goes red from his collar to his hair and stays that way. 'Every one,' he says at last. 'Every one of them.' He turns to the loft, where nobody is looking at him. 'You knew. All of you knew.' He sits down very straight on a hamper. 'I will not say them. I will not stand on the stage of the Wheel before the City and say them. They must come out, or I do.'".
  }
  Relation swaleKnows(group). Relation linesCut(group). Relation swaleKnowing(group). Relation swaleGone(group). Relation reconciled(group).
  Action cut_lines(actor: group, site: place) "Sit down with Hepzibah and Swale and cut the Ghost's blue lines" {
    Speaker hepzibah. Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(hepzibah, site) and at(swale, site) and swaleKnows(swale)
      and not linesCut(swale) and not swaleKnowing(swale) and week().
    On success { Assert linesCut(swale). }
    Result "It takes an hour. Hepzibah reads each line aloud in a voice like a cold spoon and Swale says 'Out' or, rarely, 'That one I will keep,' and you find a new word where a new word will go. 'I rise' becomes 'I stand'. 'Member' becomes 'councillor'. The Ghost comes out of it cleaner, prouder and less funny, and Swale shakes your hand afterward as if you had saved his life.".
  }
  Action persuade_swale(actor: group, site: place) "Tell Swale the Ghost's lines are tragic, whatever else they are, and that only he can play them so" {
    Speaker swale. Time 5 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(swale, site) and swaleKnows(swale)
      and not linesCut(swale) and not swaleKnowing(swale) and week() and not triedSwale(actor).
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert swaleKnowing(swale). }
    On failure { Assert triedSwale(actor). }
    Result "You tell him the truth, which is that a man who will not lie down is a sad thing as well as a funny one, and that the house will laugh at the line and then hear the man, if the man is played by somebody who believes in him. Swale listens with his chin up. 'Both,' he says, at last. 'You mean that they will laugh, and then they will not be able to.' He breathes out. 'Very well. I will play him as if every word were clean. God forgive me.'".
    Otherwise "'You are very kind,' says Swale, and does not believe you. 'They must come out.'".
  }
  Relation triedSwale(group).
  Topic swale_player with swale "Tell Swale, as one player to another, that the laugh and the tears are the same breath" when craft(actor, craft_stage) and swaleKnows(swale) and not linesCut(swale) and not swaleKnowing(swale) once {
    Says "Swale looks at you differently: as at someone who has stood on boards. 'You have played the fool,' he says. 'Yes. I see you have.' A long silence. 'My mother used to say a comedy is a tragedy that has been to bed.' He almost smiles. 'Very well. I will play him as if every word were clean, and you will stand in the wing and tell me afterward whether I was a fool.'".
    On discuss { Assert swaleKnowing(swale). }
  }
  // A Swale who knows, and has neither his cuts nor a reason to play the lines, walks out at noon on the third day.
  Rule swale_walks when swaleKnows(swale) and not linesCut(swale) and not swaleKnowing(swale) and not swaleGone(swale) and tday(pentrice) >= 3 and hour(clock) >= 12
    and at(swale, ?p) {
    Retract at(swale, ?p). Assert at(swale, owl_room). Assert swaleGone(swale). Retract troupe(swale). }
  Rule swale_walks_told when swaleGone(swale) and not spread(swale_gone_known) and inCity()
    says "Word goes round the Moon within the hour: Ambrose Swale has packed his cloak and his crown and gone to sit in the Owl, and says he has left the profession." { Assert spread(swale_gone_known). }
  Discovery swale_gone_known "Ambrose Swale has walked out of Gosse's Company over the Ghost's lines.".
  Action fetch_swale(actor: group, site: place) "Ask Swale to come back, on his own terms: with the lines cut" {
    Speaker swale. Time 5 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(swale, site) and swaleGone(swale) and week() and not triedFetch(actor).
    Resolve check(actor, persuasion, dc_fair).
    On success { Retract swaleGone(swale). Assert linesCut(swale). Assert troupe(swale). Retract at(swale, owl_room). Assert at(swale, moon_loft). }
    On failure { Assert triedFetch(actor). }
    Result "He makes you say it twice. Then he stands, and gathers his cloak, and says, 'With the lines cut,' and you say, 'With the lines cut,' and he walks back to the Moon in front of you, very fast, as if he had thought of going anyway.".
    Otherwise "'No,' says Swale, to the window. 'I have played my last fool.'".
  }
  Relation triedFetch(group).

  // Swale and Pudding: nine years without a word, over a joke at a grave.
  Topic swale_pudding with swale "Ask Swale about Jem Pudding" when not reconciled(swale) once {
    Says "'I do not speak of that person,' says Swale, 'or to him.' He looks out of the window. 'We play together. On the stage he is my servant, my fool, my shadow, my conscience, whatever the play requires. Off it,' he says, 'he stood at my mother's grave in the rain and told a joke about a bishop and a goat. And they laughed.'".
  }
  Topic pudding_swale with pudding "Ask Pudding about Swale" when not reconciled(swale) once {
    Says "Pudding catches the three onions and holds them. 'She asked me to,' he says. 'His mother. She said: Jem, they'll all be standing there with faces like wet Wednesdays, and Ambrose worst. Tell them the one about the bishop and the goat.' He puts the onions down in a row. 'So I did. And it was the best laugh I ever got, and he hasn't spoken to me since.' He does not look round for Swale. 'She wrote it down for him. I couldn't give it him. He'd not let me near. Hepzibah has it.'".
    On discuss { Assert knows(actor, mother_letter_known). }
  }
  Event swale_reads near swale when keeps(swale, swale_letter) "Swale takes the letter as if it might be hot. He reads it at the window with his back to the room, twice, and then he stands there a long time with it in his hand. Then he crosses the loft, the whole length of it, to where Pudding is sitting on the floor, and says, in his ordinary voice, which you have never heard: 'The bishop and the goat. Tell it me again, Jem. I didn't hear the end.' Pudding tells it. Swale laughs until he has to sit down beside him." then {
    Assert reconciled(swale). }
  Action lock_them_in(actor: group, site: place) "Lock Swale and Pudding in the loft together for the morning, with the Ghost's scenes" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, moon_loft) and at(swale, moon_loft) and at(pudding, moon_loft)
      and not reconciled(swale) and not rehearsedGhost(swale) and daytime() and week() and not swaleGone(swale) and bookCome(pentrice).
    Resolve check(actor, lockwork, dc_easy).
    On success { Assert rehearsedGhost(swale). }
    Result "You go out, and turn the key on them, and sit on the loft stair outside with the key in your fist. There is a great deal of silence. Then Swale's voice, cold: 'Your cue.' Then Pudding's. By noon they are shouting at each other, but they are shouting the play, and when you open the door they have the Ghost's scenes off by heart and will not look at you.".
    Otherwise "The loft door's lock is old and you cannot make it catch, and before you can try again Swale has walked out past you with his cloak over his arm.".
  }
  Relation rehearsedGhost(group).

  // ── Dorcas Quaile, and who plays the Widow ──────────────────────────────────────────────────────────────────────
  Topic dorcas_part with dorcas "Ask Dorcas about her part" when bookCome(pentrice) and not dorcasWidow(dorcas) once {
    Says "'Bell,' says Dorcas. 'The daughter. Nineteen.' She does not look up from the stocking. 'I have played the daughter for twenty-five years, in every play Absalom ever bought, and I will play her one more season, at the Wheel, in front of the Bench, because after this season there won't be another.' The needle goes in and out. 'The Widow is a part for an old woman. I know what the Widow is. Don't tell me what the Widow is.'".
  }
  Relation dorcasWidow(group). Relation dorcasStays(group). Relation dorcasGone(group). Relation gosseLied(group).
  Action persuade_dorcas(actor: group, site: place) "Tell Dorcas the Widow is the best part in the play, and the only one in it worth her" {
    Speaker dorcas. Time 5 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(dorcas, site) and bookCome(pentrice) and not dorcasWidow(dorcas)
      and not dorcasGone(dorcas) and week() and not triedDorcas(actor).
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert dorcasWidow(dorcas). Assert dorcasStays(dorcas). }
    On failure { Assert triedDorcas(actor). }
    Result "You read her the Widow's scene with Pomfret over the funeral meats, all of it, the bit with the pie, the bit with the will, the bit where she makes him propose on his knees on the hearth-rug and then says no. Dorcas stops darning. When you finish she is quiet a while. 'It's a good part,' she says, as if it hurt. 'It's the best part I've been offered in ten years.' She puts the stocking down. 'Tell Hepzibah. Before I change my mind.'".
    Otherwise "'That's what Absalom says,' says Dorcas, and goes on darning.".
  }
  Relation triedDorcas(group).
  Topic dorcas_player with dorcas "Tell Dorcas, as one player to another, what the Widow is" when craft(actor, craft_stage) and bookCome(pentrice) and not dorcasWidow(dorcas) and not dorcasGone(dorcas) once {
    Says "You tell her what she knows: that the girl has two scenes and a kiss, and the Widow has the play; that the house will come for Bell and go home talking of the Widow; that it takes a great actress to be laughed at on purpose. Dorcas looks at you a long time. 'You've done it,' she says. 'Played the old woman.' She bites off her thread. 'All right. All right. But I'll have the blue gown.'".
    On discuss { Assert dorcasWidow(dorcas). Assert dorcasStays(dorcas). }
  }
  Topic gosse_dorcas with gosse "Ask Gosse to talk Dorcas into the Widow" when bookCome(pentrice) and not dorcasWidow(dorcas) and not dorcasGone(dorcas) and not gosseLied(gosse) once {
    Says "'Leave it to me,' says Gosse, and goes across the loft to Dorcas with his arms out. You hear only a little of it: 'Fallow, my dear, Corin Fallow himself, asking after you for his widows, his duchesses, his queens, which is why I cannot spare you to be nineteen.' Dorcas looks at him with deep suspicion and slowly increasing pleasure. Gosse comes back rubbing his hands. 'The Widow,' he says. 'And a lie, which is the oil of the profession.'".
    On discuss { Assert dorcasWidow(dorcas). Assert gosseLied(gosse). }
  }
  // The notice Dame Gammage wrote of Dorcas's Widow in The Miller's Wife, twelve years ago (from her scrapbook).
  Kind old_notice "an old ballad-sheet notice" is gear worth 0 weighing 0
    described "A cutting from a ballad-sheet twelve years old, gone brown: '…and MISTRESS QUAILE as the Miller's Widow was the funniest thing seen at the Wheel since the Flood, and this writer laughed till she was obliged to be carried out. Let her play nothing but widows, and the town will follow her to the grave. P.G.'".
  Event dorcas_reads near dorcas when keeps(dorcas, gammage_notice) "Dorcas reads the cutting once and laughs out loud, and reads it again, and stops laughing. 'Carried out,' she says. 'I remember. She was.' She folds the cutting very small and puts it in the bosom of her dress. 'Give me the Widow, then,' she says to the loft at large. 'And somebody find me a pie.'" then {
    Assert dorcasWidow(dorcas). Assert dorcasStays(dorcas). }

  // Fallow's offer (town.kyr): a place in his house. In the City's licensed house no woman may play, by ordinance: what he
  // wants her for is the wardrobe.
  Topic dorcas_fallow with dorcas "Ask Dorcas about Fallow's offer" when fallowOffered(dorcas) and not dorcasStays(dorcas) and not dorcasGone(dorcas) once {
    Says "'A place in the Lord Mayor's Servants,' says Dorcas, and for the first time she sounds young. 'A house. A roof. Fifteen crowns a year and a chair by the fire. He says he has parts for me, Corin does. Girls.' She looks at her hands. 'I'm going, I think. Tomorrow. Don't tell Absalom. I'll tell him myself, which I won't.'".
  }
  Discovery fallow_wardrobe "By the Ordinances of Plain Speech no woman may speak on a licensed stage within the walls: the Lord Mayor's Servants are men and boys. Whatever Corin Fallow wants Dorcas Quaile for, it is not to act; it is to keep his wardrobe." { Known by hepzibah, tunstall. }
  Topic hepz_fallow with hepzibah "Ask Hepzibah about Fallow's offer to Dorcas" when fallowOffered(dorcas) and not knows(actor, fallow_wardrobe) once {
    Says "Hepzibah's pencil stops. 'Parts,' she says. 'In the Mayor's Room. Inside the walls.' She looks at you. 'There's not been a woman on a licensed stage in Pentrice for forty years. It's in the Ordinances; the Office put it there the same month it put Absalom out. Corin Fallow's boys play his girls.' She starts writing again. 'He wants her for his wardrobe. He's lost his wardrobe-mistress to a glover.'".
    On discuss { Assert knows(actor, fallow_wardrobe). }
  }
  Topic dorcas_truth with dorcas "Tell Dorcas what Fallow wants her for" when knows(actor, fallow_wardrobe) and fallowOffered(dorcas) and not dorcasStays(dorcas) and not dorcasGone(dorcas) once {
    Says "Dorcas listens without moving. Then she gets up, and puts her darning down on the hamper very gently, and goes to the window, and looks down into the yard as if Corin Fallow were in it. 'His wardrobe,' she says. 'Twenty-five years at the top of the bill, and Corin Fallow wants me to sew his boys into their stays.' She turns round. 'Give me a part,' she says, 'and I'll make him eat his Siege.'".
    On discuss { Assert dorcasStays(dorcas). }
  }
  Action ask_dorcas_stay(actor: group, site: place) "Ask Dorcas to stay with the company for the Trial" {
    Speaker dorcas. Time 5 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(dorcas, site) and fallowOffered(dorcas) and not dorcasStays(dorcas)
      and not dorcasGone(dorcas) and not triedStay(actor).
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert dorcasStays(dorcas). }
    On failure { Assert triedStay(actor). }
    Result "'For the Trial,' says Dorcas. 'One more time.' She looks round the loft: Absalom declaiming at a hamper, Kit with his pot, Pudding and his onions. 'Somebody has to,' she says. 'Somebody in this company has to be a grown woman.'".
    Otherwise "'You're kind,' says Dorcas. 'You don't have to sleep on the straw.'".
  }
  Relation triedStay(group).
  // If she has not been given a reason, she goes over to Fallow on the second morning; and if Gosse lied to her, his lie
  // comes out when Fallow comes, and she goes then.
  Rule dorcas_goes when fallowOffered(dorcas) and not dorcasStays(dorcas) and not dorcasGone(dorcas) and tday(pentrice) >= 2 and hour(clock) >= 8
    and at(dorcas, ?p) {
    Assert dorcasGone(dorcas). Retract troupe(dorcas). Retract at(dorcas, ?p). Assert at(dorcas, mayors_hall). Retract dorcasWidow(dorcas). }
  Rule dorcas_goes_told when dorcasGone(dorcas) and not spread(dorcas_gone_known) and inCity()
    says "Kit Arden finds you, white-faced: Dorcas has gone over to Corin Fallow, with her box, and left a note for Gosse that says only SORRY, ABSALOM, I AM FORTY-EIGHT." { Assert spread(dorcas_gone_known). }
  Discovery dorcas_gone_known "Dorcas Quaile has left Gosse's Company for Corin Fallow's.".

  // ── Kit Arden, and his voice ────────────────────────────────────────────────────────────────────────────────────
  Topic kit_voice with kit "Ask Kit what is in the pot" when true once {
    Says "'Honey and hot water,' says Kit, and his voice goes up on 'water' and comes down somewhere else entirely, and he goes scarlet. 'It's going,' he says, in a whisper, which is safer. 'My voice. For months. If it goes at the Wheel in front of the Bench, in the middle of Bell, I'm finished. Boys whose voices go don't play girls, and boys who don't play girls don't play anything till they're men, and by then everybody's forgotten them.' He looks into the pot. 'Ma Tolly in the Gullet has the best honey. She charges for it.'".
    On discuss { Assert knows(actor, kit_fear). }
  }
  Discovery kit_fear "Kit Arden's voice is breaking: it goes in the middle of a line, and he is afraid it will go on the night." { Known by kit. }
  Relation kitCracked(group). Relation kitVoiceHeld(group).
  Action dose_kit(actor: group, site: place) "Make Kit Canon Mallory's draught of honey and horehound, and tell him what the Canon said" {
    Speaker kit. Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and at(kit, site) and quantity(actor, honey) >= 1 and knows(actor, mallory_trick)
      and not kitVoiceHeld(kit) and week().
    On success { Decrease quantity(actor, honey) by 1. Assert kitVoiceHeld(kit). }
    Result "You make it as the Canon said, with the horehound bruised and the honey stirred in off the boil, and you tell Kit what the Canon said, word for word: sing under the voice, not over it; never reach for the top of a line, let it come down to you. Kit drinks it making faces. Then he says Bell's first speech, very carefully, under the voice, and it holds, all of it, low and clear and a little husky, like a girl who has been crying. He looks at you with his mouth open.".
  }

  // ── Casting, with Hepzibah ──────────────────────────────────────────────────────────────────────────────────────
  // Parts: the Widow, Bell and Master Tapwell. Swale is the Ghost, Gosse is Pomfret and the Prologue, Pudding is Lob,
  // Tam is the Tallyman. Who plays the three that are in question is written in Hepzibah's book.
  Kind part. Entity part_widow: part "the Widow Gudgeon". Entity part_bell: part "Bell Gudgeon". Entity part_tapwell: part "Master Tapwell".
  Entity part_ghost: part "the Ghost of Alderman Gudgeon".
  Relation plays(group, part).
  Initially Assert plays(dorcas, part_bell). Initially Assert plays(kit, part_widow). Initially Assert plays(hepzibah, part_tapwell).
  Initially Assert plays(swale, part_ghost).
  Action cast_dorcas_widow(actor: group, site: place) "Have Hepzibah put Dorcas down for the Widow, and Kit for Bell" {
    Speaker hepzibah. Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(hepzibah, site) and dorcasWidow(dorcas) and not dorcasGone(dorcas)
      and not plays(dorcas, part_widow) and week() and not plays(kit, part_tapwell).
    On success { Retract plays(dorcas, part_bell). Retract plays(kit, part_widow). Assert plays(dorcas, part_widow). Assert plays(kit, part_bell). }
    Result "Hepzibah rubs out two names and writes two, and blows on the page. 'Better,' she says. 'Much better. Kit, you're nineteen and in love. Dorcas, you're a widow and you've buried two and you'll bury a third.' 'With pleasure,' says Dorcas.".
  }
  Action cast_kit_tapwell(actor: group, site: place) "Have Hepzibah put Kit down for Master Tapwell, his first man's part" {
    Speaker hepzibah. Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(hepzibah, site) and knows(actor, kit_fear) and not plays(kit, part_tapwell) and week()
      and (plays(hepzibah, part_tapwell) or plays(party, part_tapwell)).
    On success { Retract plays(kit, part_widow). Retract plays(kit, part_bell). Retract plays(hepzibah, part_tapwell). Retract plays(party, part_tapwell).
      Assert plays(kit, part_tapwell). }
    Result "Hepzibah looks at Kit over her spectacles. 'Master Tapwell,' she says. 'The lover. Twenty, a fountain-builder's apprentice, with a voice like a cart going over cobbles, which is what you have.' Kit stares at her. 'A man's part,' he says, and his voice goes down into his boots, and for once he doesn't mind.".
  }
  Action cast_self_tapwell(actor: group, site: place) "Tell Hepzibah you will play Master Tapwell yourself" {
    Speaker hepzibah. Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(hepzibah, site) and inCompany(actor) and plays(hepzibah, part_tapwell)
      and not tallyman(actor) and week() and bookCome(pentrice) and not plays(party, part_ghost).
    On success { Retract plays(hepzibah, part_tapwell). Assert plays(actor, part_tapwell). }
    Result "Hepzibah writes your name beside Tapwell's without comment, and then, with comment: 'Learn it. All of it. Tapwell has the kiss in the garden, and the Tallyman counts it, and if you dry in the middle of a kiss the Wheel will never let you forget it.' She hands you the part, copied out in her small hand, with your cues underlined.".
  }
  Action cast_self_ghost(actor: group, site: place) "Tell Hepzibah you will play the Ghost yourself, now Swale has gone" {
    Speaker hepzibah. Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(hepzibah, site) and inCompany(actor) and swaleGone(swale) and not plays(party, part_ghost)
      and not plays(party, part_tapwell) and not tallyman(actor) and week().
    On success { Retract plays(swale, part_ghost). Assert plays(party, part_ghost). }
    Result "Hepzibah's pencil, which was moving, stops. 'The Ghost,' she says. 'Nineteen speeches and a complaint.' She writes your name. 'He is dead in every line. Remember that, and the rest will look after itself.'".
  }
  // A part nobody plays is taken by whoever is free: the Widow by Kit, or Gosse, doubling, in a cap; Bell by Ned Cherry
  // if he is with the company, or Kit, or, failing everyone, Tam Hautboy in a frock.
  Rule recast_widow when dorcasGone(dorcas) and plays(dorcas, ?r) { Retract plays(dorcas, ?r). }
  Query kitFree() means not plays(kit, part_bell) and not plays(kit, part_widow) and not plays(kit, part_tapwell).
  Rule widow_to_kit when not plays(?x, part_widow) and kitFree() { Assert plays(kit, part_widow). }
  Rule widow_to_gosse when not plays(?x, part_widow) and not kitFree() { Assert plays(gosse, part_widow). }
  Rule bell_to_ned when not plays(?x, part_bell) and atMoon(ned) { Assert plays(ned, part_bell). }
  Rule bell_to_kit when not plays(?x, part_bell) and not atMoon(ned) and kitFree() { Assert plays(kit, part_bell). }
  Rule bell_to_tam when not plays(?x, part_bell) and not atMoon(ned) and not kitFree() { Assert plays(tam, part_bell). }
  Rule widow_from_gosse when plays(gosse, part_widow) and plays(dorcas, part_widow) { Retract plays(gosse, part_widow). }
  Rule widow_back_to_kit when plays(gosse, part_widow) and not plays(dorcas, part_widow) and kitFree() { Retract plays(gosse, part_widow). Assert plays(kit, part_widow). }
  Query atMoon(n: group) means nedRuns(n) or nedLent(n).
  Action cast_ned_bell(actor: group, site: place) "Have Hepzibah put Ned Cherry down for Bell" {
    Speaker hepzibah. Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(hepzibah, site) and atMoon(ned) and not plays(ned, part_bell) and week()
      and not plays(dorcas, part_bell).
    On success { Retract plays(kit, part_bell). Retract plays(tam, part_bell). Assert plays(ned, part_bell). }
    Result "Hepzibah hears Ned read Bell's first speech in a voice like a blackbird's, and puts down her pencil, and picks it up again, and writes him in. 'The Close taught you to sing,' she says. 'Now unlearn half of it.'".
  }
  // The cast list on Hepzibah's trestle, as it stands.
  Observe cast_widow_dorcas at moon_loft when bookCome(pentrice) and plays(dorcas, part_widow) "On the cast list, in pencil: THE WIDOW GUDGEON, Mrs Quaile.".
  Observe cast_widow_kit at moon_loft when bookCome(pentrice) and plays(kit, part_widow) "On the cast list, in pencil: THE WIDOW GUDGEON, Master Arden.".
  Observe cast_widow_gosse at moon_loft when bookCome(pentrice) and plays(gosse, part_widow) "On the cast list, in pencil: THE WIDOW GUDGEON, Mr Gosse (doubling, in a cap).".
  Observe cast_bell_dorcas at moon_loft when bookCome(pentrice) and plays(dorcas, part_bell) "On the cast list: BELL, her daughter, Mrs Quaile, underlined twice in somebody else's pencil.".
  Observe cast_bell_kit at moon_loft when bookCome(pentrice) and plays(kit, part_bell) "On the cast list: BELL, her daughter, Master Arden.".
  Observe cast_bell_ned at moon_loft when bookCome(pentrice) and plays(ned, part_bell) "On the cast list: BELL, her daughter, Master Cherry (of the Close, lent).".
  Observe cast_bell_tam at moon_loft when bookCome(pentrice) and plays(tam, part_bell) "On the cast list: BELL, her daughter, Mr Hautboy, God help us.".
  Observe cast_tapwell_hepz at moon_loft when bookCome(pentrice) and plays(hepzibah, part_tapwell) "On the cast list: MASTER TAPWELL, a lover, and beside it, in Hepzibah's hand: (read from the book).".
  Observe cast_tapwell_kit at moon_loft when bookCome(pentrice) and plays(kit, part_tapwell) "On the cast list: MASTER TAPWELL, a lover, Master Arden.".
  Observe cast_tapwell_party at moon_loft when bookCome(pentrice) and plays(party, part_tapwell) "On the cast list: MASTER TAPWELL, a lover, and your own name.".

  // ── Rehearsal ───────────────────────────────────────────────────────────────────────────────────────────────────
  // An hour in the loft for each act, with the company that is in it. What a rehearsal shows (Gosse's ear, Swale's
  // innocence, Kit's voice) is seen there; what it makes is a scene the company knows.
  Relation rehearsedI(place). Relation rehearsedII(place). Relation rehearsedIII(place).
  Action rehearse_one(actor: group, site: place) "Rehearse the first act in the loft: the Prologue, the funeral, the Widow's suitor" {
    Speaker hepzibah. Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, moon_loft) and at(hepzibah, moon_loft) and at(gosse, moon_loft)
      and bookCome(pentrice) and daytime() and week() and not rehearsedI(pentrice) and not pensionTaken(gosse).
    On success { Assert rehearsedI(pentrice). Assert knows(actor, act_one_known). }
    Result "Gosse gives the Prologue to the hampers as if they were the City, and gets it word-perfect, and you see him do it. Then the funeral: mourners in a line, quarrelling about who walks first, until the coffin is left in the middle of the floor and the Ghost climbs out of it, which is a hamper and a great deal of dignity. Then the Widow and her suitor over the funeral meats. Twice, when Hepzibah throws a cue from the left, Gosse takes it a beat late, from Pudding, as if he had meant to.".
  }
  Observe deaf_rehearsal at moon_loft noticed by insight when rehearsedI(pentrice) and not knows(party, deaf_seen) "You saw it, in the first act: Hepzibah gave Gosse his line from the left, twice, and he did not hear it, and covered with a bit of business, and took it from Pudding on his right. He has been standing a little to the right of everyone since you came." teaches deaf_seen.
  Discovery act_one_known "You have rehearsed the first act of The Alderman's Ghost with the company.".
  Action rehearse_two(actor: group, site: place) "Rehearse the second act in the loft: the Council, the lovers, the Ghost's complaint" {
    Speaker hepzibah. Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, moon_loft) and at(hepzibah, moon_loft) and at(kit, moon_loft)
      and bookCome(pentrice) and daytime() and week() and not rehearsedII(pentrice) and not pensionTaken(gosse).
    On success { Assert rehearsedII(pentrice). Assert knows(actor, swale_innocent). }
    Result "The Council sits on hampers, and the Ghost rises to speak against the sale of his statue. Then the lovers in the garden, Bell and Tapwell under the moon, with Tam as the Tallyman counting their kisses on a notched stick. Then the Ghost's complaint, the long one, which is either the funniest thing in the play or the saddest, and nobody in the loft can tell which.".
  }
  Rule rehearse_rise at moon_loft when rehearsedII(pentrice) and not swaleKnows(swale) and not rehearsalTold(pentrice)
    says "At the Council, the company tries not to look at each other while Ambrose Swale says, with tremendous feeling, 'I rise, sirs, as I always rose,' and Pudding bites through his own lip." { Assert rehearsalTold(pentrice). }
  Rule rehearse_stand at moon_loft when rehearsedII(pentrice) and linesCut(swale) and not rehearsalTold(pentrice)
    says "At the Council Swale says, with tremendous feeling, 'I stand, sirs, as I always stood,' and nobody laughs, and Pudding looks faintly bereaved." { Assert rehearsalTold(pentrice). }
  Rule rehearse_knowing at moon_loft when rehearsedII(pentrice) and swaleKnowing(swale) and not rehearsalTold(pentrice)
    says "At the Council Swale says, 'I rise, sirs, as I always rose,' knowing it now, with his chin up and his eyes perfectly clear, and the laugh in the loft comes and stops halfway, as if it had walked into a door." { Assert rehearsalTold(pentrice). }
  Relation rehearsalTold(place).
  Rule kit_cracks at moon_loft when rehearsedII(pentrice) and plays(kit, part_bell) and not kitVoiceHeld(kit) and not kitCracked(kit)
    says "In the garden scene Kit reaches for the top of Bell's line about the moon and his voice goes straight up through the roof and comes down a man's. Nobody laughs. Kit sits down on the floor with his hands over his face, and Hepzibah, after a moment, writes something in the margin of the book." teaches kit_fear { Assert kitCracked(kit). }
  Rule kit_cracks_widow at moon_loft when rehearsedII(pentrice) and plays(kit, part_widow) and not kitVoiceHeld(kit) and not kitCracked(kit)
    says "Between scenes, cueing the lovers for Hepzibah, Kit reaches for the top of Bell's line about the moon and his voice goes straight up through the roof and comes down a man's. Nobody laughs. Kit sits down on the floor with his hands over his face. 'And I'm the Widow,' he says, through them. 'For now.'" teaches kit_fear { Assert kitCracked(kit). }
  Rule kit_holds at moon_loft when rehearsedII(pentrice) and plays(kit, part_bell) and kitVoiceHeld(kit) and not kitCracked(kit) and not kitHeldTold(kit)
    says "In the garden scene Kit takes Bell's line about the moon under his voice, as the Canon said, low and husky, and it holds; and Hepzibah, at the book, says 'Well,' very softly." { Assert kitHeldTold(kit). }
  Relation kitHeldTold(group).
  Action rehearse_three(actor: group, site: place) "Rehearse the third act in the loft: the Fountain, the bear, who walks first" {
    Speaker hepzibah. Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, moon_loft) and at(hepzibah, moon_loft) and at(gosse, moon_loft)
      and bookCome(pentrice) and daytime() and week() and not rehearsedIII(pentrice) and not pensionTaken(gosse).
    On success { Assert rehearsedIII(pentrice). }
    Result "The Fountain is a bucket and Tam Hautboy with a watering-can. The bear is Pudding on all fours. Who walks first: the whole company in a line round the loft, the Ghost at the head of it, then Pomfret, then everyone. At the end Gosse turns, as Pomfret, for the epilogue, and opens his mouth, and then says: 'I shall do the epilogue on the night. I know it.' Hepzibah, at the book, says nothing at all.".
  }
}

data/adventures/gosses-company/verdict.k:
Module pentrice "Gosse's Company" {
  // ── The fines ───────────────────────────────────────────────────────────────────────────────────────────────────
  // Read at the Wheel when the house has gone; due before the Bench reads its verdict at ten the next morning. The
  // Master who wrote the play has torn them up, if she bowed; otherwise the Owl may pay them, or Corin Fallow, who owes
  // the company a tower, or whoever pays them at the Office; or Gosse goes to the Clink of the Soke.
  Relation finesPaid(place). Relation gosseClink(group).
  Action pay_fines(actor: group, site: place) "Pay the company's fines to the Office, {fines(pentrice)} coin" {
    Speaker tunstall. Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(tunstall, site) and playEnded(pentrice) and fines(pentrice) > 0 and not finesPaid(pentrice)
      and not verdictRead(pentrice) and quantity(actor, gold) >= fines(pentrice).
    On success { Decrease quantity(actor, gold) by fines(pentrice). Increase quantity(tunstall, gold) by fines(pentrice). Assert finesPaid(pentrice). }
    Result "Tunstall counts it twice and writes a receipt in his small grey hand, and blots it, and gives it to you. 'Paid,' he says. He hesitates, and then says, not as a clerk: 'It was worth every line.'".
  }
  Rule fines_owl when playEnded(pentrice) and fines(pentrice) > 0 and not finesPaid(pentrice) and regard(callow) >= slight(callow) + 4 and tday(pentrice) >= 5 and hour(clock) >= 9 {
    Assert finesPaid(pentrice). Assert owlPaid(pentrice). }
  Rule fines_fallow when playEnded(pentrice) and fines(pentrice) > 0 and not finesPaid(pentrice) and fallowGrateful(fallow) and tday(pentrice) >= 5 and hour(clock) >= 9 {
    Assert finesPaid(pentrice). Assert fallowPaid(pentrice). }
  Rule fines_unpaid when playEnded(pentrice) and fines(pentrice) > 0 and not finesPaid(pentrice) and tday(pentrice) >= 5 and hour(clock) >= 9 and not gosseClink(gosse) {
    Assert gosseClink(gosse). }
  Relation owlPaid(place). Relation fallowPaid(place).

  // ── The verdict ─────────────────────────────────────────────────────────────────────────────────────────────────
  // At ten on the morning after the last night the Bench reads its verdict from the stage of the Wheel, and the crier
  // carries it through the City. Each critic gives a vote to the company whose regard has risen far enough; three give
  // Gosse the Patent. A house that roared is worth one more to the Gullet.
  Relation verdictRead(place). Relation verdictDue(place). Relation votedFor(group). Relation patentWon(place). Relation childrenWon(place).
  Relation epilogueTold(place). Relation verdictCounted(place).
  Measure votes(place). Measure verdictAt(place).
  Rule verdict_due when tday(pentrice) >= 5 and hour(clock) >= 10 and not verdictDue(pentrice) { Assert verdictDue(pentrice). Set verdictAt(pentrice) to watch(clock). }
  Rule joy_counts when verdictDue(pentrice) and temper(pentrice) >= 10 and not verdictCounted(pentrice) { Increase regard(gammage) by 1. }
  // What the Bench looks like when the play is over: whoever stays in the Wheel can read the verdict in the lords' room,
  // a night before the crier cries it.
  // Each critic's mind, at the margin they need to be moved by.
  Query clayWon() means regard(clay) >= slight(clay) + 4.
  Query gammageWon() means regard(gammage) >= slight(gammage) + 7.
  Query malloryWon() means regard(mallory) >= slight(mallory) + 4.
  Query callowWon() means regard(callow) >= slight(callow) + 4.
  Observe after_clay_won at wheel when playEnded(pentrice) and at(clay, wheel) and not verdictRead(pentrice) and clayWon() "In the lords' room Ormsby Clay closes his book on his finger and sits on a moment longer than he needs to, looking at the empty stage.".
  Observe after_clay_lost at wheel when playEnded(pentrice) and at(clay, wheel) and not verdictRead(pentrice) and not clayWon() "Ormsby Clay is already on his feet in the lords' room with his book shut, pushing in his chair, neatly.".
  Observe after_gammage_won at wheel when playEnded(pentrice) and at(gammage, wheel) and not verdictRead(pentrice) and gammageWon() "Dame Gammage is still on her feet in the lords' room with her bonnet in her hand, shouting something at the stage that nobody can hear.".
  Observe after_gammage_lost at wheel when playEnded(pentrice) and at(gammage, wheel) and not verdictRead(pentrice) and not gammageWon() "Dame Gammage has finished her nuts, and is looking into the empty bag as if it owed her a better evening.".
  Observe after_mallory_won at wheel when playEnded(pentrice) and at(mallory, wheel) and not verdictRead(pentrice) and malloryWon() "Canon Mallory is mouthing the moral to himself, very happily, and blowing his nose.".
  Observe after_mallory_lost at wheel when playEnded(pentrice) and at(mallory, wheel) and not verdictRead(pentrice) and not malloryWon() "Canon Mallory is studying his hands, pink, like a man to whom something has been said in church.".
  Observe after_callow_won at wheel when playEnded(pentrice) and at(callow, wheel) and not verdictRead(pentrice) and callowWon() "Nym Carrow is writing so fast that he has torn through his programme into the next one.".
  Observe after_callow_lost at wheel when playEnded(pentrice) and at(callow, wheel) and not verdictRead(pentrice) and not callowWon() "Nym Carrow has written one word across his programme, and underlined it twice.".
  Rule vote_clay when verdictDue(pentrice) and (ghostPlay(pentrice) or galtPlay(pentrice)) and clayWon() and not verdictCounted(pentrice) { Assert votedFor(clay). Increase votes(pentrice) by 1. }
  Rule vote_gammage when verdictDue(pentrice) and (ghostPlay(pentrice) or galtPlay(pentrice)) and gammageWon() and not verdictCounted(pentrice) { Assert votedFor(gammage). Increase votes(pentrice) by 1. }
  Rule vote_mallory when verdictDue(pentrice) and (ghostPlay(pentrice) or galtPlay(pentrice)) and malloryWon() and not verdictCounted(pentrice) { Assert votedFor(mallory). Increase votes(pentrice) by 1. }
  Rule vote_callow when verdictDue(pentrice) and (ghostPlay(pentrice) or galtPlay(pentrice)) and callowWon() and not verdictCounted(pentrice) { Assert votedFor(callow). Increase votes(pentrice) by 1. }
  Rule votes_counted when verdictDue(pentrice) and not verdictCounted(pentrice) { Assert verdictCounted(pentrice). }
  Rule patent_won when verdictCounted(pentrice) and votes(pentrice) >= 3 and not patentWon(pentrice) and not gosseAshamed(gosse) { Assert patentWon(pentrice). }
  Rule children_won when verdictCounted(pentrice) and votes(pentrice) < 3 and siegeFell(fallow) and not childrenWon(pentrice) { Assert childrenWon(pentrice). }
  Rule verdict_read when verdictCounted(pentrice) and not verdictRead(pentrice) { Assert verdictRead(pentrice). }

  Rule verdict_gosse when verdictRead(pentrice) and patentWon(pentrice) and not spread(verdict_known) and inCity()
    says "At ten o'clock the crier comes through the City ringing his bell, and stops at every corner, and cries it: THE BENCH OF THE TRIAL GIVES THE PATENT OF THE WHEEL TO GOSSE'S COMPANY, BY {votes(pentrice)} VOICES. Behind him, all the way, people are coming out of their doors." { Assert spread(verdict_known). }
  Rule verdict_refused when verdictRead(pentrice) and votes(pentrice) >= 3 and gosseAshamed(gosse) and not spread(verdict_known) and inCity()
    says "At ten o'clock the crier comes through the City ringing his bell: THE BENCH GIVES THE PATENT OF THE WHEEL TO GOSSE'S COMPANY, BY {votes(pentrice)} VOICES. And an hour later he comes through again, puzzled, with a second cry: ABSALOM GOSSE DECLINES IT. A HOUSE IS NOT TO BE HAD BY ANOTHER COMPANY'S FALL. THE PATENT STAYS WITH THE LORD MAYOR'S SERVANTS." { Assert spread(verdict_known). }
  Rule verdict_children when verdictRead(pentrice) and votes(pentrice) < 3 and childrenWon(pentrice) and not spread(verdict_known) and inCity()
    says "At ten o'clock the crier comes through the City ringing his bell: THE BENCH OF THE TRIAL GIVES THE PATENT OF THE WHEEL TO THE CHILDREN OF THE CLOSE. Nobody, the Children least of all, can remember this happening before." { Assert spread(verdict_known). }
  Rule verdict_fallow when verdictRead(pentrice) and votes(pentrice) >= 1 and votes(pentrice) < 3 and not childrenWon(pentrice) and not spread(verdict_known) and inCity()
    says "At ten o'clock the crier comes through the City ringing his bell: THE BENCH OF THE TRIAL GIVES THE PATENT OF THE WHEEL TO THE LORD MAYOR'S SERVANTS, FOR A TWELFTH YEAR. Gosse's Company had {votes(pentrice)} of the four voices." { Assert spread(verdict_known). }
  Rule verdict_none when verdictRead(pentrice) and votes(pentrice) == 0 and not childrenWon(pentrice) and not spread(verdict_known) and inCity()
    says "At ten o'clock the crier comes through the City ringing his bell: THE BENCH OF THE TRIAL GIVES THE PATENT OF THE WHEEL TO THE LORD MAYOR'S SERVANTS, FOR A TWELFTH YEAR. Not one of the four voices was Gosse's." { Assert spread(verdict_known). }
  Discovery verdict_known "The Bench of the Trial has read its verdict.".

  // ── The season's account ────────────────────────────────────────────────────────────────────────────────────────
  // What became of everyone, told the morning of the verdict wherever the company is in Pentrice; then the ending.
  Relation fateTold(fact).
  Rule fate_married when verdictRead(pentrice) and proposed(gosse) and not fateTold(fate_married_known) and inCity()
    says "Absalom Gosse and Hepzibah Dimmock are married in the minster a month later by Canon Mallory, with their banns read on three Sundays running, to the congregation's very great interest. Gosse gives the responses as if the minster were the Wheel. Hepzibah gives him every one of his." { Assert fateTold(fate_married_known). }
  Discovery fate_married_known "Gosse and Hepzibah were married.".
  Rule fate_empty when verdictRead(pentrice) and emptyWing(gosse) and not fateTold(fate_married_known) and inCity()
    says "Gosse does not say it again. He says it to nobody, the next morning, in the loft, by mistake, and Hepzibah, at the book, says without looking up: 'Yes. I heard you the first time,' and that is the whole of it, and they are married before the season is out, in the Wheel's tiring-house, under the wall of names." { Assert fateTold(fate_married_known). }
  Rule fate_swale_gammage when verdictRead(pentrice) and understanding(swale) and not fateTold(fate_swale_known) and inCity()
    says "Dame Gammage's notice of Gosse's night, on the ballad-sheets of the Gullet the next morning, runs to a column and a half, and ends: 'THE WALKING CATHEDRAL HAS LEARNED TO DANCE. This writer will be at the Wheel every night he plays, in the front of the yard, and you may draw what conclusions you like.'" { Assert fateTold(fate_swale_known). }
  Discovery fate_swale_known "What became of Ambrose Swale.".
  Rule fate_swale_shamed when verdictRead(pentrice) and humiliated(swale) and not fateTold(fate_swale_known) and inCity()
    says "Dame Gammage's notice of Gosse's night says nothing of Ambrose Swale at all, which in fifteen years she has never done, and is the cruellest thing she has ever written." { Assert fateTold(fate_swale_known). }
  Rule fate_swale_fool when verdictRead(pentrice) and swaleUnderstands(swale) and not understanding(swale) and not humiliated(swale) and not fateTold(fate_swale_known) and inCity()
    says "Ambrose Swale is not seen in a tragedy again that season. He plays fools, and old men in comedies, and is so good in them that by the season's end the Gullet calls him the Wooden Lear with love." { Assert fateTold(fate_swale_known). }
  Rule fate_swale_shaken when verdictRead(pentrice) and swaleShaken(swale) and not swaleUnderstands(swale) and not understanding(swale) and not fateTold(fate_swale_known) and inCity()
    says "Ambrose Swale leaves the company the morning after, very politely, with his cloak and his own crown, and is next heard of carrying a spear in the Siege of Arle for Corin Fallow, who is kind to him." { Assert fateTold(fate_swale_known). }
  Rule fate_swale_gone when verdictRead(pentrice) and swaleGone(swale) and not fateTold(fate_swale_known) and inCity()
    says "Ambrose Swale sat at the Owl through Gosse's night, and went home to Galt the morning after, and teaches elocution there to the sons of grocers, and writes to Hepzibah once a year, at the turn of it." { Assert fateTold(fate_swale_known). }
  Rule fate_dorcas_widow when verdictRead(pentrice) and plays(dorcas, part_widow) and not fateTold(fate_dorcas_known) and inCity()
    says "Dorcas Quaile plays widows from then on, and duchesses, and grandmothers, and is greater in every one of them than she ever was as a girl." { Assert fateTold(fate_dorcas_known). }
  Rule fate_dorcas_notice when verdictRead(pentrice) and plays(dorcas, part_widow) and keeps(dorcas, gammage_notice) and not fateTold(fate_notice_known) and inCity()
    says "She keeps Dame Gammage's old notice in her stays, and takes it out before every first night, and reads it, and puts it back." { Assert fateTold(fate_notice_known). }
  Discovery fate_notice_known "Dorcas keeps Gammage's notice.".
  Discovery fate_dorcas_known "What became of Dorcas Quaile.".
  Rule fate_dorcas_gone when verdictRead(pentrice) and dorcasGone(dorcas) and not fateTold(fate_dorcas_known) and inCity()
    says "Dorcas Quaile keeps Corin Fallow's wardrobe at the Mayor's Room, and sews his boys into their stays, and is good at it, and whenever Gosse's Company plays in Pentrice she comes to stand among the fishwives in the yard, and does not let anybody see her face." { Assert fateTold(fate_dorcas_known). }
  Rule fate_dorcas_bell when verdictRead(pentrice) and plays(dorcas, part_bell) and not fateTold(fate_dorcas_known) and inCity()
    says "Dorcas Quaile plays the girl one more season, as she said, and at the season's end puts the frock away in the bottom of a hamper and says nothing about it, and the next year asks Hepzibah for the old women's parts." { Assert fateTold(fate_dorcas_known). }
  Rule fate_kit_man when verdictRead(pentrice) and plays(kit, part_tapwell) and not fateTold(fate_kit_known) and inCity()
    says "Kit Arden plays young men from then on, badly at first and then well, and the Wheel's yard, which watched his voice break in a garden by moonlight, follows him like an aunt." { Assert fateTold(fate_kit_known). }
  Discovery fate_kit_known "What became of Kit Arden.".
  Rule fate_kit_held when verdictRead(pentrice) and kitVoiceHeld(kit) and not plays(kit, part_tapwell) and not fateTold(fate_kit_known) and inCity()
    says "Kit Arden's voice holds through the season, under the Canon's trick, and goes at the season's end in a single night, in his sleep; and in the morning he comes down the loft stair a man and asks Hepzibah for a man's part, and gets one." { Assert fateTold(fate_kit_known). }
  Rule fate_kit_broke when verdictRead(pentrice) and kitBroke(kit) and not plays(kit, part_tapwell) and not fateTold(fate_kit_known) and inCity()
    says "Kit Arden does not go on again that season. He sits in the tiring-house and keeps the book for Hepzibah, and learns it, and by the autumn is the best prompter in Imbar but one." { Assert fateTold(fate_kit_known). }
  Rule fate_bear_home when verdictRead(pentrice) and bearOn(pentrice) and patentWon(pentrice) and not fateTold(fate_bear_known) and inCity()
    says "Patience appears on the Wheel's own playbills from then on, in red, BY PUBLIC DEMAND, and is paid in honey, on time, every night." { Assert fateTold(fate_bear_known). }
  Rule fate_bear_road when verdictRead(pentrice) and bearOn(pentrice) and not patentWon(pentrice) and not fateTold(fate_bear_known) and inCity()
    says "Patience's honey-pot dance is talked about in the Gullet for a year, and every honey-woman in Pentrice keeps a pot back, in case the company and its bear come through again." { Assert fateTold(fate_bear_known). }
  Discovery fate_bear_known "What became of Patience.".
  Rule fate_bear_lost when verdictRead(pentrice) and at(the_bear, bear_pen) and not fateTold(fate_bear_known) and inCity()
    says "Patience stays in the bear-garden of the Soke, and dances on Sundays for Simeon Bowle's customers, who are not kind; and every Sunday Jem Pudding goes over the river and stands at the palings and hums." { Assert fateTold(fate_bear_known). }
  Rule fate_ned when verdictRead(pentrice) and atMoon(ned) and not fateTold(fate_ned_known) and inCity()
    says "Ned Cherry does not go back to the Close. His voice goes before the season is out, as the Canon said it would, and he plays the bear's keeper instead, and is very happy, and writes to the Canon every week." { Assert fateTold(fate_ned_known). }
  Discovery fate_ned_known "What became of Ned Cherry.".
  Rule fate_ned_stays when verdictRead(pentrice) and nedStays(ned) and not fateTold(fate_ned_known) and inCity()
    says "Ned Cherry sings Behold for one more season, and at its end, when his voice goes, the Canon walks him down to the Moon himself." { Assert fateTold(fate_ned_known). }
  Rule fate_banns when verdictRead(pentrice) and sukeyYes(sukey) and not fateTold(fate_banns_known) and inCity()
    says "The banns of Richard Merriman, ostler, and Susan Rowe, spinster, are read in the minster, and nobody knows any just cause." { Assert fateTold(fate_banns_known). }
  Discovery fate_banns_known "Merriman and Sukey's banns were read.".
  Rule fate_bells when verdictRead(pentrice) and pealRung(bunces) and not fateTold(fate_bells_known) and inCity()
    says "The Budge brothers ring every peal that season together, and argue all through every one of them, about jackdaws." { Assert fateTold(fate_bells_known). }
  Discovery fate_bells_known "The Budges rang together.".
  Rule fate_fountain when verdictRead(pentrice) and fountainRuns(pentrice) and not fateTold(fate_fountain_known) and inCity()
    says "The Fountain of Concord runs all season. The Lord Mayor brings an action against the Guildhall for the loss of his carp, and loses it, and Wat Cundy is made his master's journeyman for reasons nobody gives in writing." { Assert fateTold(fate_fountain_known). }
  Discovery fate_fountain_known "The Fountain of Concord ran.".
  Rule fate_clink when verdictRead(pentrice) and gosseClink(gosse) and not fateTold(fate_clink_known) and inCity()
    says "Absalom Gosse goes to the Clink of the Soke at noon for the Office's fines, in his crimson coat, waving, and holds court there for a week, and plays the Prologue through the bars every evening to a crowd in the street, until the Owl and the Gullet between them have raised the money in pennies." { Assert fateTold(fate_clink_known). }
  Discovery fate_clink_known "Gosse went to the Clink for the fines.".
  Rule fate_owl when verdictRead(pentrice) and owlPaid(pentrice) and not fateTold(fate_clink_known) and inCity()
    says "The fines are paid by subscription at the Owl, a penny a head, raised in an hour, with Nym Carrow standing on a table shouting the total." { Assert fateTold(fate_clink_known). }
  Rule fate_fallow_paid when verdictRead(pentrice) and fallowPaid(pentrice) and not fateTold(fate_clink_known) and inCity()
    says "The fines are paid at the Office before ten by Corin Fallow, in coin, without a word, for a siege-tower." { Assert fateTold(fate_clink_known). }
  Rule fate_master_bowed when verdictRead(pentrice) and clemBowed(clemency) and not fateTold(fate_master_known) and inCity()
    says "Clemency Orde keeps the Office of Plain Speech. She adds a Tenth Ordinance, in her own hand, the week after: Of Laughter. A word spoken to make the City laugh is the City's, and may not be fined. Abel Tunstall reads it twice, and blots it, and has it chained to the lectern." { Assert fateTold(fate_master_known). }
  Discovery fate_master_known "What became of Clemency Orde and the Office.".
  Rule fate_master_kept when verdictRead(pentrice) and clemTold(clemency) and not clemBowed(clemency) and not clemCold(clemency) and not fateTold(fate_master_known) and not authorNamed(pentrice) and inCity()
    says "Clemency Orde keeps the Office of Plain Speech, and her secret, and whenever Gosse's Company plays in Pentrice she comes to the yard in Sukey's old brown hood, and stands at the back, and laughs." { Assert fateTold(fate_master_known). }
  Rule fate_master_named when verdictRead(pentrice) and authorNamed(pentrice) and not clemBowed(clemency) and not clemCold(clemency) and not fateTold(fate_master_known) and inCity()
    says "Clemency Orde keeps the Office of Plain Speech for one more year, because everyone at her mother's table knew by the pie who had written the play, and four critics cannot keep a secret past the second bottle. She does not take the bow; it was taken for her, at supper. Nobody fines her. At the Trial the year after, she sits on the grey bench with a hazel stick across her knees and does not cut a notch all night, and the yard, which knows, watches her not doing it." { Assert fateTold(fate_master_known). }
  Rule fate_master_cold when verdictRead(pentrice) and clemCold(clemency) and not fateTold(fate_master_known) and inCity()
    says "Clemency Orde keeps the Office of Plain Speech, harder than her father ever did; and nobody in Pentrice ever learns who wrote The Alderman's Ghost, because the one who could tell them made her pay for it." { Assert fateTold(fate_master_known). }
  Rule fate_book_licensed when verdictRead(pentrice) and patentWon(pentrice) and ghostPlay(pentrice) and state(book, copy_licensed) and not fateTold(fate_book_known) and inCity()
    says "The Alderman's Ghost is played at the Wheel all season as the Office licensed it, with the Tallyman struck out and the Ghost rising and standing where the book once had him rise; and the yard, which has heard what the lines used to be, says them along with him under its breath." { Assert fateTold(fate_book_known). }
  Discovery fate_book_known "How The Alderman's Ghost went on being played.".
  Rule fate_book_warranted when verdictRead(pentrice) and patentWon(pentrice) and ghostPlay(pentrice) and state(book, copy_warranted) and not fateTold(fate_book_known) and inCity()
    says "The Alderman's Ghost is played at the Wheel all season as it was written, under the Master's warrant, every line of it, and the grey bench sits through it every night with its sticks across its knees and does not cut a notch." { Assert fateTold(fate_book_known). }
  Rule fate_book_whole when verdictRead(pentrice) and patentWon(pentrice) and liberty() and not clemBowed(clemency) and not fateTold(fate_book_known) and inCity()
    says "The Alderman's Ghost is played whole at the Wheel all that season, every night, under the Soke's law; and every night the Office sits on its grey bench and counts, and Abel Tunstall reads the fines from the stage when the house has gone, and the yard pays them, a penny a head, into Gosse's hat." { Assert fateTold(fate_book_known). }
  Rule epilogue_done when verdictRead(pentrice) and not epilogueTold(pentrice) and watch(clock) >= verdictAt(pentrice) + 1 { Assert epilogueTold(pentrice). }

  // A share of the house, to whoever was one of the company on its night.
  Relation shared(group).
  Rule house_share when verdictRead(pentrice) and inCompany(party) and ghostPlay(pentrice) and not shared(party) {
    Assert shared(party). Increase quantity(party, gold) by crowd(pentrice) * 4. }
  Rule house_share_told when shared(party) and not fateTold(share_known) and inCity()
    says "Hepzibah counts out your share of the house onto the trestle in the loft, coin by coin, from the book, less the candles; the fuller the yard, the taller the pile." { Assert fateTold(share_known). }
  Discovery share_known "Hepzibah paid you your share of the house.".
  // Gosse's crown, to whoever stood on the stage as one of the company.
  Relation crownOffered(group). Relation licenceOffered(group).
  Topic gosse_crown with gosse "Ask Gosse what he means to do with his crown" when verdictRead(pentrice) and (plays(party, part_tapwell) or plays(party, part_ghost)) and not crownOffered(gosse) once {
    Says "Gosse takes the crown of paste off his own head, the gilt tin and the glass, and holds it a moment, and then writes something in the band with Hepzibah's pencil. 'Forty-one years,' he says. 'It goes to whoever stood on the boards with us when it mattered.' He holds it out to you. 'Look inside.'".
    On discuss { Assert crownOffered(gosse). }
  }
  Action take_crown(actor: group, recipient: member, site: place) "Take Gosse's crown of paste" {
    Speaker gosse. Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(gosse, site) and crownOffered(gosse) and memberOf(recipient, actor) and awake(recipient)
      and not knows(actor, crown_given).
    Resolve acquire(crown, paste_crown, recipient).
    On success { Assert knows(actor, crown_given). Retract at(crown, wheel). }
    Result "Inside the band, at the end of the long list of names and towns, is yours, in Hepzibah's pencil, the lead still bright.".
  }
  // The Master's licence, to whoever made her stand.
  Kind master_licence "the Master's licence" like old_glossary granting deception worth 0 weighing 0
    described "A sheet of the Office's heavy white paper with the padlocked mouth showing through it, sealed in grey wax: LICENSED, WHATEVER THE BEARER SAYS, ON ANY STAGE, IN ANY CITY. C. ORDE, MASTER OF PLAIN SPEECH. It is, strictly, worthless outside Pentrice. It does not feel worthless.".
  Item licence "the Master's licence" is master_licence at wheel hidden until licence_given.
  Discovery licence_given "Clemency Orde has written you a licence for whatever you say, on any stage.".
  Topic clem_licence with clemency "Ask the Master what she will do now" when verdictRead(pentrice) and clemBowed(clemency) and not licenceOffered(clemency) once {
    Says "'Write,' says the Master. 'At night. As before. Only now with the door open.' She takes a sheet of the Office's paper and writes four lines on it, and seals it, and holds it out. 'A licence,' she says, 'for whatever you say, on any stage, in any city. It is worthless outside Pentrice and you must never tell anyone that.' She almost smiles. 'What is said is done. Go and say something.'".
    On discuss { Assert licenceOffered(clemency). }
  }
  Action take_licence(actor: group, recipient: member, site: place) "Take the Master's licence" {
    Speaker clemency. Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(clemency, site) and licenceOffered(clemency) and memberOf(recipient, actor) and awake(recipient)
      and not knows(actor, licence_given).
    Resolve acquire(licence, master_licence, recipient).
    On success { Assert knows(actor, licence_given). Retract at(licence, wheel). }
    Result "The wax is still warm.".
  }

  // ── How it ends ─────────────────────────────────────────────────────────────────────────────────────────────────
  // An ending is the company's only if it came for the Trial (see clock.kyr): one that never went down the West Road,
  // or came too late, goes on with its own life.
  Ending pension "The Pension" when pentriceCloses() and cameForTrial(party) and pensionTaken(gosse) and tday(pentrice) >= 5 and hour(clock) >= 11 "Absalom Gosse put his name to Corin Fallow's paper and took his thirty crowns a year and a little house by the Ise with a garden, and the Trial of the Wheel was played by two companies that season, and the Patent stayed where it was. The fair copy of The Alderman's Ghost went into a drawer in the little house. Gosse grows beans. He is very good at it. In the evenings he stands at the end of his garden, facing the river, and you can hear him from the Soke, giving the Prologue to the beans.".
  Ending burned "The Fair Copy Burned" when pentriceCloses() and cameForTrial(party) and epilogueTold(pentrice) and galtPlay(pentrice) and not patentWon(pentrice) and not pensionTaken(gosse) "The Alderman's Ghost was burned in Guildhall Square, and Gosse's Company played The Wolf King instead, very well, to a house that had seen it before, and lost the Patent, and went on the road again when the season was over, west. The play is gone. Nobody in Pentrice ever saw it. But on the last night in the loft, before the wagon went, Hepzibah Dimmock sat up with a candle and wrote down the first act from memory, and Kit the second, and Pudding the third, and between them they had all of it but the epilogue, which only Gosse knew; and Gosse would not say it.".
  Ending bow "The Author's Bow" when pentriceCloses() and cameForTrial(party) and epilogueTold(pentrice) and clemBowed(clemency) "The Master of Plain Speech stood up on the stage of the Wheel before the City and said that she had written The Alderman's Ghost, and that it was her father, and that he would have laughed; and then she laughed, which nobody in Pentrice had heard her do. The tallymen broke their sticks. Whatever the Bench decided the next morning (and it is written down, as everything in Pentrice is), it is not what anybody remembers. What they remember is a woman in grey at the end of a procession, and an old fool taking her hand, and the Wheel on its feet. The Alderman's Ghost is played at the Wheel every Trial since, and the Ghost walks first.".
  Ending refused "The Patent Refused" when pentriceCloses() and cameForTrial(party) and epilogueTold(pentrice) and votes(pentrice) >= 3 and gosseAshamed(gosse) "The Bench gave Gosse's Company the Patent of the Wheel, and Absalom Gosse stood up in the yard and gave it back. A house is not to be had by another company's fall, he said, whoever knocked the wedge out; and Corin Fallow, who had lost his tower in front of the City, took it back without a word, and sent the company a ham. Gosse's Company went on the road again when the season was over, west, under the sky, as it always had. It is the only prize Absalom Gosse ever refused in his life.".
  Ending patent "The Patent House" when pentriceCloses() and cameForTrial(party) and epilogueTold(pentrice) and patentWon(pentrice) "The Bench gave Gosse's Company the Patent of the Wheel, and Absalom Gosse, sixty-three, who had played under the sky for forty-one years, came in out of the rain. They paint GOSSE'S COMPANY over the gate of the Wheel in red letters that will go pink. Hepzibah keeps the book in the tiring-house press. The wagon stands in Soke Lane with its shafts down and grass growing round its wheels, and sometimes, on a fine evening, Gosse goes and sits on its tail-board, and looks west, along the road, for a while, before he goes in to play.".
  Ending broken "The Company Broken" when pentriceCloses() and cameForTrial(party) and epilogueTold(pentrice) and ghostPlay(pentrice) and temper(pentrice) < 7 "The Alderman's Ghost went up at the Wheel on the last night of the Trial and came down again to a house that did not know what it had seen, and the Bench gave the Patent to another company. By the season's end Gosse's Company was gone: its players to Fallow's spears and the fairs and the wardrobe and their mothers, its wagon sold. Absalom Gosse was last seen on the road west out of Pentrice on foot, in his crimson coat, telling the Prologue to the hedges.".
  Ending liberty "The Liberty" when pentriceCloses() and cameForTrial(party) and epilogueTold(pentrice) and liberty() and not patentWon(pentrice) "The Bench gave the Patent to another company, and the Office fined Gosse's Company for every line of The Alderman's Ghost, and the City banned it from the walls for another forty years; and before the season was out the play was being sung in the Gullet and acted in back rooms and quoted at the Owl, and the Lord Mayor's Servants' Siege of Arle played to a third of a house. Gosse's Company went on the road again, west, famous in every town in Imbar that had ever had an alderman, which is all of them.".
  Ending road "The Road Again" when pentriceCloses() and cameForTrial(party) and epilogueTold(pentrice) and ghostPlay(pentrice) and not liberty() and not patentWon(pentrice) "Gosse's Company played The Alderman's Ghost as the Office licensed it, and played it well, and the Bench gave the Patent to another company. Gosse took it with a magnificent bow, and called the winners the best of good fellows in the Owl, and before the week was out the wagon went out of the Westgate with its painted cloth rolled on top, west, toward the next green and the one after, with a licensed comedy in Hepzibah's hamper that any town in Imbar could see without a fine.".

  // ── What was done ───────────────────────────────────────────────────────────────────────────────────────────────
  Milestone ms_parcel "got Gosse's parcel out of the ostler" worth 100 when knows(party, parcel_freed).
  Milestone ms_widow "gave Dorcas Quaile the Widow" worth 150 when plays(dorcas, part_widow).
  Milestone ms_stays "kept Dorcas Quaile from Corin Fallow's wardrobe" worth 100 when dorcasStays(dorcas) and fallowOffered(dorcas).
  Milestone ms_mended "made it up between Swale and Pudding" worth 200 when reconciled(swale).
  Milestone ms_lines "settled the Ghost's lines with Swale" worth 150 when linesCut(swale) or swaleKnowing(swale).
  Milestone ms_voice "kept Kit Arden's voice, or gave him a man's part" worth 100 when kitVoiceHeld(kit) or plays(kit, part_tapwell).
  Milestone ms_bear "brought Patience home" worth 150 when bearHome(the_bear).
  Milestone ms_ned "found Ned Cherry a place" worth 100 when nedLent(ned) or nedRuns(ned) or nedStays(ned).
  Milestone ms_licence "got The Alderman's Ghost a licence" worth 200 when state(book, copy_licensed) or state(book, copy_warranted).
  Milestone ms_dead "found the Ordinance of the dead" worth 150 when ghostRestored(pentrice) and not tunstallBought(pentrice).
  Milestone ms_author "found out who wrote The Alderman's Ghost" worth 300 when knows(party, author_known).
  Milestone ms_riot "heard the riot told twice" worth 150 when gosseSorry(gosse).
  Milestone ms_clay "gave Ormsby Clay back his Dido" worth 150 when clayMoved(clay).
  Milestone ms_gull "made the gulling come true" worth 200 when understanding(swale).
  Milestone ms_callow "caught Nym Carrow out" worth 100 when knows(party, callow_lies).
  Milestone ms_banns "got Dick Merriman his answer" worth 100 when sukeyYes(sukey).
  Milestone ms_bells "found the jackdaws in the bell-frame" worth 100 when bellsMended(bunces).
  Milestone ms_bees "saved Ma Tolly's swarm" worth 100 when state(chimney, saved).
  Milestone ms_fountain "set the Fountain of Concord running" worth 250 when fountainRuns(pentrice).
  Milestone ms_heckler "dealt with Oswin Garlick" worth 100 when garlickHome(garlick) or garlickOurs(garlick).
  Milestone ms_watermen "got the City over the river on Gosse's night" worth 150 when watermenOurs(ferriby) or crowdLed(pentrice).
  Milestone ms_bailiff "kept the costumes from the bailiff" worth 100 when bailiffDone(grimsditch) and not costumesTaken(pentrice).
  Milestone ms_pirate "stopped the pirate quarto" worth 100 when shadStopped(shad).
  Milestone ms_tower "saved Fallow's siege-tower" worth 150 when siegeHeld(fallow).
  Milestone ms_played "played Gosse's night at the Wheel" worth 500 when playEnded(pentrice) and ghostPlay(pentrice) and inCompany(party).
  Milestone ms_house "brought the Wheel to its feet" worth 300 when playEnded(pentrice) and temper(pentrice) >= 12.
  Milestone ms_patent "won Gosse's Company the Patent" worth 800 when patentWon(pentrice).
  Milestone ms_bow "brought the author to the stage" worth 600 when clemBowed(clemency).

  // ── What the company is trying to do ───────────────────────────────────────────────────────────────────────────
  Objective obj_trial when cameForTrial(party) and not playEnded(pentrice) and not pensionTaken(gosse) "The Trial of the Wheel: the Lord Mayor's Servants on the second night, the Children of the Close on the third, Gosse's Company on the fourth; the Bench of four gives the Patent the morning after.".
  Objective obj_parcel when knows(party, parcel_waiting) and not bookCome(pentrice) "A parcel waits at the Painted Moon for whoever played the Fool at the Wheel the night of the riot.".
  Objective obj_cast when knows(party, cast_trouble) and not plays(dorcas, part_widow) and not dorcasGone(dorcas) and week() "The Alderman's Ghost is badly cast: Dorcas Quaile will have Bell, not the Widow, and nobody plays Master Tapwell.".
  Objective obj_swale when swaleKnows(swale) and not linesCut(swale) and not swaleKnowing(swale) and not swaleGone(swale) and week() "Ambrose Swale knows what the Ghost's lines mean, and will not say them: cut them, or give him a reason to play them, before he walks out.".
  Objective obj_licence when bookCome(pentrice) and state(book, copy_fair) and not libertyChosen(pentrice) and week() and inCompany(party) "The Alderman's Ghost has no licence: send it to the Office of Plain Speech, or play it whole in the Soke and let the tallymen count.".
  Objective obj_struck when state(book, copy_struck) and week() "The Office has struck forty-one lines from The Alderman's Ghost: argue them, accept them, or take the play whole to the Soke.".
  Objective obj_author when bookCome(pentrice) and not knows(party, author_known) and (knows(party, wm_seen) or knows(party, margins_seen) or knows(party, drawing_seen) or knows(party, hooded_lady)) "Who wrote The Alderman's Ghost, and sent it to the Fool of the Wheel?".
  Objective obj_bear when bearLoose(the_bear) and not bearHome(the_bear) and not at(the_bear, moon_yard) "Patience is loose, or taken: bring her home before the night.".
  Objective obj_wing when gosseMeans(gosse) and not playEnded(pentrice) "Gosse means to ask Hepzibah in the epilogue: see that she is in the left-hand wing at the end.".
  Objective obj_prompt when promptWing(party) and not playEnded(pentrice) "On the night, stand in the right-hand wing and give Gosse his line from his good side if he dries.".
  Objective obj_fines when playEnded(pentrice) and fines(pentrice) > 0 and not finesPaid(pentrice) and not verdictRead(pentrice) and not clemBowed(clemency) "The Office's fines for Gosse's night must be paid by ten tomorrow, or Gosse goes to the Clink.".
}

data/adventures/gosses-company/voices.ky:
Module pentrice "Gosse's Company" {
  Description "What each of the company makes of Pentrice by what they are; the requiem for the lamplighter, said alone or said before his son; a playbill for a ship that came ashore; the lamplighter's pole.".

  // The preset party has no declared people, so it has no Remarks of its own. What a rule can ask of a member is their
  // calling, and print their name; each voice is said once, by whoever has the calling.
  Relation heardWheel(group). Relation heardPlate(group). Relation heardLock(group). Relation heardDogs(group).
  Relation heardWeir(group). Relation heardStep(group).

  // ── Voices, by calling ──────────────────────────────────────────────────────────────────────────────────────────
  Rule voice_wheel at wheel when capable(party, performance) and at(party, wheel) and not heardWheel(party)
    says "The one of you who has trodden boards walks to the middle of the empty yard, claps once, and stands with a head on one side while the clap goes up through three galleries and comes back late. 'Good house,' they say. 'It gives you back everything but the left-hand corner of the stage, where it gives you back nothing at all. Stand an old man there and he will think his own voice has failed him.'" {
    Assert heardWheel(party).
  }
  Rule voice_plate at nave when capable(party, rites) and at(party, nave) and not heardPlate(party)
    says "The one of you who keeps the offices stops at the small brass plate by the west door, as a priest stops at any plate, and reads it twice with the lips moving. 'Somebody comes every week with a rag,' they say. 'There is rag-polish in the lettering, and nowhere else. Whoever it is does not let the Close see him do it.' A finger touches the couplet cut beneath. 'And this is a song, not a text. I have not seen a song on a plate before. There must have been a reason it was allowed.'" {
    Assert heardPlate(party).
  }
  Rule voice_lock at office_hall when capable(party, lockwork) and at(party, office_hall) and not heardLock(party)
    says "The one of you with clever fingers lets the eye go round the hall once, like a man reading a menu. 'Nine locks on the Ordinances' chest and one on the Master's door, and the Master's is the cheap one,' they say, very low. 'The man who guards the rules locks the rules. The woman who writes the plays does not lock anything.'" {
    Assert heardLock(party).
  }
  Rule voice_dogs at bear_pen when capable(party, intimidation) and at(party, bear_pen) and not heardDogs(party)
    says "The one of you who has stood in front of men for a living walks the edge of the sand and does not once turn a back to the kennel. 'Trained to the word, not to the man,' they say. 'Watch Bowle's left hand. Whoever hears it open is the one they will come for. If he whistles, they are his again; if he does not, nothing in the world will call them off.'" {
    Assert heardDogs(party).
  }
  Rule voice_weir at weir_stones when capable(party, woodcraft) and at(party, weir_stones) and not heardWeir(party)
    says "The one of you who knows the ground crouches by the cold fire on the ledge and puts a hand over the ashes. 'Three nights of it, banked with wet wood to keep it in till dusk,' they say. 'Nobody banks a fire like that unless they are coming back to it. And the stones are scrubbed. Whoever lives under there keeps the crossing the way a farmer keeps a gate.'" {
    Assert heardWeir(party).
  }
  Rule voice_step at under_stage when capable(party, perception) and not capable(party, woodcraft) and at(party, under_stage) and not heardStep(party)
    says "The one of you who reads the unseen lays a palm flat on the white curve of the old step and holds it there. 'No working in it,' they say, frowning. 'It was built to do one thing, and that thing is carry a whisper up to the last row without losing a syllable. It does it still. Whatever you say on this step is heard in every seat that is left.'" {
    Assert heardStep(party).
  }

  // ── The requiem: a choice with a price ─────────────────────────────────────────────────────────────────────────
  // Tunstall polishes his father's plate in the minster at six of a morning, before the Office opens, and has done for
  // forty years. One of the company who keeps the offices can say the office for Abel Tunstall at it. Said alone, it is a kindness
  // and a lawful reading: the plate's couplet is cut under the Eighth Ordinance, of Epitaphs, and a priest knows what
  // that is for. Said before the son, it is a gift to the living; and a man who has been given that will not be bribed.
  Place gosse_limbo "nowhere" is room within pentrice at 9, 9.
  Entity gosse_limbo_fact: fact "the nowhere of Pentrice".
  Rule tunstall_polishes when hour(clock) == 6 and tday(pentrice) >= 1 and tday(pentrice) <= 4 and at(tunstall, office_hall) and not pensionTaken(gosse) { Retract at(tunstall, office_hall). Assert at(tunstall, nave). }
  Rule tunstall_polished when hour(clock) >= 7 and at(tunstall, nave) { Retract at(tunstall, nave). Assert at(tunstall, westgate). }
  Observe tunstall_at_plate near tunstall when at(tunstall, nave) and not knows(party, plate_seen_son) "A narrow grey man in a narrow grey coat is on one knee at the west door with a rag, working at a small brass plate in short strokes, as one rubs a child's cheek. He does not look up. He has not hurried, you think, in forty years.".
  Discovery plate_seen_son "At six in the morning, before the Office opens, Abel Tunstall kneels at the lamplighter's plate in the minster and polishes it with a rag, as he has every week since he was nine.".
  Relation requiemAlone(group). Relation requiemAloud(group). Relation tunstallMourned(place).
  Action requiem_alone(actor: group, site: place) "Say the office for Abel Tunstall the lamplighter at the plate, alone" {
    Description "An hour on the stone floor. The Eighth Ordinance was written for this. A priest knows it by its smell.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, nave) and knows(actor, plate_read) and capable(actor, rites)
      and not requiemAlone(actor) and not requiemAloud(actor) and not at(tunstall, nave).
    Time 60 minutes.
    On success { Assert requiemAlone(actor). Assert knows(actor, ordinance_dead). Assert knows(actor, lamplighter_known). }
    Result "The one of you who keeps the offices kneels where Tunstall kneels and says it all, the office for a man who fell from a ladder, to a plate and an empty nave, in the plain voice of someone who has done it before. At the end of the couplet they sit back on their heels and say, to nobody: 'It is cut under the Eighth. Words in the person of the dead are the dead's. That is what this couplet is.' You will find the Ordinance is where they say it is.".
  }
  Action requiem_aloud(actor: group, site: place) "Say the office for Abel Tunstall the lamplighter, aloud, with his son kneeling beside the plate" {
    Description "Tunstall is here at six in the morning. He will not be asked, and he will not leave. He has never in his life had it said.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, nave) and at(tunstall, nave) and knows(actor, plate_read) and capable(actor, rites)
      and not requiemAlone(actor) and not requiemAloud(actor).
    Time 60 minutes.
    On success { Assert requiemAloud(actor). Assert tunstallMourned(pentrice). Assert knows(actor, ordinance_dead). Assert knows(actor, lamplighter_known). Increase clemTrust(clemency) by 1. Give abel_seal to actor. }
    Result "Your priest goes down on the stone beside him, and says it. Tunstall does not move. At the first versicle the rag stops. At the second his shoulders go, once, and he does not make a sound, and the office does not stop. When the last response has been given he sits back on his heels with the rag in his lap and does not look at either of you. 'Nobody has said that,' he says. 'In forty years. I did not know it could be said.' He reaches into his narrow coat and brings out a brass seal on a chain, a lamp with a hand closed round it. 'His,' he says. 'The Lamplighters' seal. It is no use to me.' He closes your hand over it. 'The Eighth Ordinance is on a chained page in the Office. I wrote the ruling beneath it myself.'".
  }
  // The company of one has no priest in it. A player who has the song can do a poorer thing: sing the plate's couplet to
  // the son, who has not heard it sung since the night it was sung under his father's ladder. It is the right tune
  // in the wrong mouth. He will tell what he knows, but no seal, no warmth in the Master, and a man who has been
  // made to hear it cannot afterwards be bought.
  Relation requiemSung(group). Relation tunstallShaken(place).
  Action requiem_sung(actor: group, site: place) "Sing the couplet on the plate to Tunstall, softly, as a song and not an office" {
    Description "Tunstall is at the plate. It is his father's song. You know the tune; you are not a priest.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, nave) and at(tunstall, nave) and knows(actor, plate_read)
      and capable(actor, performance) and not capable(actor, rites)
      and not requiemAlone(actor) and not requiemAloud(actor) and not requiemSung(actor).
    Time 20 minutes.
    On success { Assert requiemSung(actor). Assert tunstallShaken(pentrice). Assert knows(actor, ordinance_dead). Assert knows(actor, lamplighter_known). }
    Result "You kneel two yards off and sing it, the two lines on the brass, to the tune they came up the Chepe with, and you sing it slowly, which is wrong. The rag stops. Tunstall's face does not change, and then it does. 'That is the song,' he says. 'You have got it from the plate.' You say you have it from a hundred taverns. He takes a while. 'Not that fast,' he says, 'and not on the third beat,' and he gets up off his knee, and takes you to the Office through the cold nave with a hand under his own elbow, and shows you the Eighth Ordinance, and the ruling under it, and says what it was made for. He gives you nothing else. When you leave he is writing something in the ledger, and has not offered you the door. You think that you could not now put ten coin on his desk and be answered.".
  }
  Item abel_seal "Abel Tunstall's lamplighter seal" is lamplighter_seal at gosse_limbo.
  Rule tunstall_incorruptible_told at office_hall when tunstallMourned(pentrice) and at(tunstall, office_hall) and state(book, copy_struck) and not spread(mourned_fact)
    says "Tunstall looks up from the desk as you come in, and nods, once, and goes back to the ledger. There is a new ruling in his handwriting beside the Eighth Ordinance in the chained book. It is only two words long: SEE PLATE." {
    Assert spread(mourned_fact).
  }
  Entity mourned_fact: fact "Tunstall's two words".

  // ── The Ship That Came Late: a playbill from the south ─────────────────────────────────────────────────────────
  // Players are the first to hear any prodigy and the first to put it on. If, in the world, the ship Remainder has been
  // given harbour at the House of Doors, the story has come up the roads by now, and Inchbald has been sent the bill.
  Topic inchbald_ship with inchbald "Ask Inchbald about the bill he is printing for a company from the south" when befell(remainder_harboured) once {
    Says "'A calf with two heads is a calf with two heads,' says Inchbald, with the reverence of a man at a shrine, and slides a proof across the stone. THE SHIP THAT CAME LATE, OR, THE MARINERS OF NO WEATHER. A NEW AND TRUE HISTORY, WITH MACHINERY. BY THE LORD WARDEN'S MEN LATE OF SENNET. 'They say a ship came up out of a cellar in the south,' he says. 'Full of people who had been sailing since before their grandmothers. They sent the bill ahead of the news. Machinery,' he adds, wetly, 'is a trap and a rope and a boy.' He looks at the proof with something very like longing. 'I could have set a stage for that.'".
    On discuss { Assert knows(actor, ship_bill). }
  }
  Discovery ship_bill "A bill has come up from the south for a play called The Ship That Came Late, about a ship out of a cellar that has been sailing since before anyone's grandmother.".
  Topic pudding_ship with pudding "Show Pudding the bill for The Ship That Came Late" when knows(actor, ship_bill) and inCompany(actor) once {
    Says "Pudding reads it standing on one foot, and then the other. 'A ship in a cellar,' he says. 'Full of ghosts who can't get home.' He lowers the paper. 'We have a Ghost who can't get home. We have a bear. Why have we not got machinery?' Hepzibah, from the prompt-corner, without looking up: 'Because it is not licensed.' 'Neither is the ship,' says Pudding, one foot on a hamper, and goes to practise being seasick.".
  }
}

data/adventures/half-the-hive/after.kyr:
Module hume "Half the Hive" {
  // ── After the Leaving: what the places and people are, for a company that comes back ─────────────────────────────
  // Each half of the hive goes on. Wherever the Mother went, the new comb is there to be seen and its people to be
  // asked; in the Brow, those who stayed have their own news. Nothing here asks whether the company saw it happen.

  // The new combs.
  Observe new_far at far_hollow when left(far_brow) and spread(founding) "Under the Far Brow a new comb hangs from the rock, a yard long already and growing, white at the edges and going gold at the heart, roaring softly. Along the back wall the Leaving has put up shelters of wattle and sailcloth, and somebody has scratched FAR BROW on a post, and somebody else has added NEW in front of it.".
  Observe new_far_here at far_hollow when left(far_brow) and not spread(founding) "Under the Far Brow a new comb hangs from the rock, white going gold, roaring softly, and along the back wall are the shelters of the Leaving.".
  Observe new_dell at dell_floor when left(chalk_dell) "The cave in the chalk roars softly all day, like a sea-cave, and the Sisters come and go from it in a brown stream. On the warm floor of the Dell the Leaving has put up shelters of wattle among the harebells.".
  Observe new_lark at chantry_yard when left(larkhill) "The chantry tower at Larkhill hums from its belfry like a bell that has been struck and will not stop, and the Sisters pour in and out of the louvres. The Leaving lives in the yard and the lane in shelters of wattle and sailcloth.".
  Observe lark_deed at chantry_yard as feature when left(larkhill) and corveGives(corve) "In the chantry porch, framed and glazed, hangs a sheet of paper in a neat hand: a deed of gift of the chantry, its tower and its yard, to whatever nests there, owned by nobody.".
  Observe lark_board at chantry_yard as feature when left(larkhill) and not corveGives(corve) "On the chantry gate a board is nailed: THESE BEES AND ALL THEY MAKE THE PROPERTY OF L. CORVE ESQ. OF LARKHILL. Someone has scratched the hexagon of the Comb over the ESQ., deep.".
  Observe new_gallow at gallow_knoll when left(gallowtree) "The Gallowtree roars from root to crown like a forest in a gale, and the Leaving lives on the knoll round it in shelters of wattle. The children are not allowed through the door in the trunk, and do not ask why.".
  Observe new_bivouac at honey_oak when left(high_wold) "From a great bough of the honey linden hangs the new comb, in the open air, white sheets swaying a little in the wind, and the Sisters cling over it in a living brown curtain. The Leaving camps in the clearing under it and looks up at it a great deal.".

  // The Brow, half empty.
  Observe chamber_empty at mothers_chamber when leavingBegun() and not daughtersDone(brenna) "The Mother's long bed of comb is empty. The Sisters who stayed stand round it in a ring, facing in, touching nothing.".
  Observe chamber_new at mothers_chamber when daughtersDone(brenna) "On the Mother's long bed of comb lies a new queen, slender and very gold, with Sisters stroking her; she is restless, and keeps walking to the end of the bed and back.".
  Observe tobit_gone at capped_gallery as feature when left(?s) and goes(agnes) and linnetPermitsDead(linnet) "Nearest the arch, where a bier stood on a trestle, there is only the trestle.".
  Observe bench_bare at wax_gallery as feature when goes(eben) "Eben Candlish's bench under the Stair is bare: his blades are gone, and his brazier is cold.".

  // Kestrel, wherever the Leaving is.
  Topic kestrel_after_far with kestrel "Ask Kestrel how the Leaving does under the Far Brow" when left(far_brow) and kestrelTurned(kestrel) once {
    Says "Kestrel is sitting with her back to the rock and her boots off, which you have never seen. 'Forty years I danced for this,' she says. 'Forty years they went somewhere nearer.' She looks along the ledge at the shelters, the smoke, the children, Hannet on her fleece. Her face does not know what to do. 'I was right about the place,' she says. 'I wasn't right about the rest. I'd have left them. A Drone showed me a road.'".
  }
  Topic kestrel_after_far_hard with kestrel "Ask Kestrel how the Leaving does under the Far Brow" when left(far_brow) and not kestrelTurned(kestrel) once {
    Says "Kestrel is counting shelters, and then counting them again. 'It's the best place in the Wold,' she says, without looking up. 'I always said.' She gets to the end of the row. 'Hannet's not here. The Mellors aren't. Old Penry's mother isn't. Half the grey heads in the Brow stood on the Apron and watched us go, because they knew they couldn't walk it, and I knew, and I danced for it anyway.' She starts counting again. 'I was right,' she says. 'I was right.'".
  }
  Topic kestrel_after_dell with kestrel "Ask Kestrel how the Leaving does in the Dell" when left(chalk_dell) once {
    Says "'Dry,' says Kestrel. 'Warm. South.' She is cutting a stake with her short hand. 'Not mine. Not the Far Brow. But the comb's coming on, and nobody's sick, and the walls give back the heat all night.' She glances at the back of the Dell, where the brocks are or were. 'Ask me in a year.'".
  }
  Topic kestrel_after_lark with kestrel "Ask Kestrel how the Leaving does at Larkhill" when left(larkhill) and corveGives(corve) once {
    Says "Kestrel looks up at the humming tower. 'It's a good tower,' she says, as if it hurt her. 'And it's nobody's. He gave it.' She scowls at the farmhouse. 'I've had to say thank you to a lowland squire. Twice. He went red both times.'".
  }
  Topic kestrel_after_owned with kestrel "Ask Kestrel how the Leaving does at Larkhill" when left(larkhill) and not corveGives(corve) once {
    Says "Kestrel looks up at the humming tower, and then at the board on the gate, and says nothing; she splits two withies while you wait. Then she says, 'Rent,' the way you would name a sickness, and goes back to splitting.".
  }
  Topic kestrel_after_gallow with kestrel "Ask Kestrel how the Leaving does at the Gallowtree" when left(gallowtree) once {
    Says "'The wood's wet.' Kestrel says it quietly so the people on the knoll won't hear. 'I put my hand inside the trunk this morning and it came out wet to the wrist.' She looks at the tree, roaring and green. 'Linnet's been in. She won't say what she saw.' She looks at you. 'You've been in. You know.' It is not a question.".
  }
  Topic kestrel_after_open with kestrel "Ask Kestrel what the Leaving will do" when left(high_wold) once {
    Says "'Wait,' says Kestrel. 'Pray they change their minds. Build them a box.' She laughs, without anything in it. 'Nobody's ever built a box for the Sisters. They'd laugh at us, if bees laughed.' She looks up at the comb swinging in the wind. 'It's a fine summer,' she says.".
  }
  // Linnet, keeping the old queen, or the Daughters.
  Topic linnet_after_mother with linnet "Ask Linnet how the Mother does" when leavingBegun() and goes(linnet) once {
    Says "'She flew.' Linnet says it as if she still cannot believe it. 'Nine years in the dark in the Crown and she flew all the way, in the middle of them, and when they hung on the rock she walked up through them to the top and started laying in the first cells before the wax was cool.' She smiles. 'She's old. She won't see another summer. But the first brood here will be hers.'".
  }
  Topic linnet_after_daughters with linnet "Ask Linnet how the Daughters do" when daughtersDone(brenna) and not goes(linnet) once {
    Says "'One reigns.' Linnet is very tired. 'She's strong. She'll fly in a day or two, and the Escort will walk her up the Toot, and then they'll be turned out, and the Brow will be the Brow again, half of it.' She looks at the empty half of the gallery. 'I stayed to keep this. It's quieter than I thought.'".
  }
  Topic pim_after with pim "Ask Pim how he is keeping the old Mother" when leavingBegun() and goes(pim) once {
    Says "Pim's arms are covered in Sisters and he is holding them out from his sides, as he did on the walk, as if they were wet. 'She likes me,' he says, astonished. 'She touched my hand this morning. With her feelers.' He swallows. 'I write to Linnet every day. She writes back. I do what she says. Mostly it's: don't panic.' He beams, terrified. 'I'm not panicking.'".
  }
  // Eben.
  Topic eben_after_lit with eben "Ask Eben whether he misses the Stair" when leavingBegun() and goes(eben) and stairLit(eben) once {
    Says "Eben is carving the doorframe of the first cell, a little, between other work. 'It's finished,' he says. 'It's lit. They'll send word at midsummer how the sun came down it. I don't need to see it. I made it.' He blows wax-dust off a carved bee. 'She's here,' he says, as if that answered something, and perhaps it does.".
  }
  Topic eben_after_short with eben "Ask Eben whether he misses the Stair" when leavingBegun() and goes(eben) and not stairLit(eben) once {
    Says "Eben is carving the doorframe of the first cell, a little, between other work. 'Every night,' he says. 'Three turns up and stopping at nothing.' He blows wax-dust off a carved bee. 'Somebody will finish it. Or the children will dare each other to stand on the last step for a hundred years, and that's a kind of finishing.' He looks across the camp to where the keeper sits with the old queen, if she is here, and his face changes.".
  }
  Topic eben_after_home with eben "Ask Eben about the Stair, now there is no hurry" when leavingBegun() and not goes(eben) once {
    Says "'No hurry,' says Eben, and laughs, and looks up the Stair. 'I've been carving faces into it since you went. Everyone who walked out. I'm doing them from memory.' He touches a white tread. 'So they're still here. Some of them.'".
  }
  // Hannet, and Agnes.
  Topic hannet_after with hannet "Ask Hannet how she likes the new comb" when leavingBegun() and goes(hannet) once {
    Says "Hannet is on her fleece in the sun with the two wax bees on their cord. 'I like it,' she says. 'It's new. Nothing in my whole life has been new.' She pats the ground. 'I danced for it, didn't I? An old woman's dance. They'll tell that.' She shuts her eyes. 'Merrit would have liked it.'".
  }
  Topic agnes_after_gone with agnes "Ask Agnes whether she has her view" when leavingBegun() and goes(agnes) once {
    Says "Agnes points with her chin. 'There.' Whatever is there, she has been looking at it since you came. 'Tobit would have said it was too windy,' she says. 'He'd have been right.' She keeps looking. 'It's a good view.'".
  }
  Topic agnes_after_quiet with agnes "Ask Agnes how she does" when leavingBegun() and not goes(agnes) and mothDead(deathshead) once {
    Says "'I sit with him.' Agnes's hands are in her lap. 'Nights, mostly. In the dark, the way you do. It's quiet up there now. Just the two of us and four hundred years.'".
  }
  Topic agnes_after_stick with agnes "Ask Agnes how she does" when leavingBegun() and not goes(agnes) and not mothDead(deathshead) once {
    Says "'I sit with him.' Agnes's hands are in her lap, and beside her, against the bed, there is a stout ash stick that was not there before. 'Nights. In the dark.' She does not say anything about the stick, and you do not ask.".
  }
  Topic huw_after with huw "Ask Huw what he will make here" when leavingBegun() and goes(huw) once {
    Says "'Heather mead.' Huw Penry spreads his arms at whatever is round him: moor, chalk, tower or tree. 'Wild, dark, strong as a horse. A new country, a new mead. The first barrel will be ready at the Lime Feast, and they'll drink it at the first Calling of this comb in thirty years' time and say: Penry made that, the year he came.' He lowers his voice. 'I've brought bee-bread. Just in case.'".
  }
  // Smoke End, which hears of it.
  Topic martin_after with martin "Ask Martin what Smoke End says of the Leaving" when leavingBegun() once {
    Says "'That they went.' Martin turns his good ear to you. 'That the sky over the gorge went brown and the whole street came out to look, and the wax-buyers were up the gorge before the bees were over the Brow, buying what the stayers couldn't carry back.' He wipes the board. 'And that a stranger walked about up there all week asking questions.' He looks at you. 'They say that too.'".
  }
  Topic elspet_after with elspet "Ask Elspet how the Comb is, half empty" when leavingBegun() once {
    Says "'Quieter.' Elspet wipes her hands. 'I scent half as many, and the Sisters are thinner on the stair, and in a year they'll have bred it back and nobody will remember how loud it was.' She looks at you over her spectacles, and leans in, out of habit, and smells you.".
  }
  Observe elspet_ours near elspet when named(party) and leavingBegun() "When Elspet Garnock smells you now, something in her face eases, as it does for the Comb's own.".
}

data/adventures/half-the-hive/apron.kyr:
Module hume "Half the Hive" {
  // ── The Apron and the Scenting House ──────────────────────────────────────────────────────────────────────────────
  Person elspet "Elspet Garnock" at scenting_room {
    Role "the Scent-warden: a small exact woman with a stained apron and very clean hands, who smells overwhelmingly of the Comb".
    Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Greets "A small woman at the stone basin looks at you over her spectacles, and then, deliberately, leans close and smells you: hair, throat, hands. 'Lowland,' she says. 'Woodsmoke, sheep, somebody else's soap. Nothing of ours.' She wipes her hands. 'Two coin and I'll make you smell like a cousin for a day. The Sisters won't know you from a Hume child. They'll know you the day after, so come back.'".
    Greets again "Elspet leans in and smells you, out of habit, and nods.".
  }
  Action scent_paid(actor: group, site: place) "Ask Elspet to scent you for a day, two coin" {
    Speaker elspet.
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, scenting_room) and at(elspet, scenting_room) and not searcher(actor) and not named(actor) and not scented() and quantity(actor, gold) >= 2.
    Time 1.
    On success { Decrease quantity(actor, gold) by 2. Increase quantity(elspet, gold) by 2. Set scentUntil(actor) to watch(clock) + 144. Assert anointed(actor). Retract spread(scent_faded). }
    Result "She dips two fingers in a jar of something gold and thick, and draws them down your forehead, your throat, the insides of your wrists, behind your ears, saying something under her breath that has the hum's tune and no words. It is warm, and then it is nothing; and then, as you go out, a Sister on the doorframe turns her head toward you, and away, uninterested, as if you were family.".
  }
  Action scent_searcher(actor: group, site: place) "Show Elspet your Searcher's ribbon, and be scented" {
    Speaker elspet.
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, scenting_room) and at(elspet, scenting_room) and searcher(actor) and not named(actor).
    Time 1.
    On success { Set scentUntil(actor) to watch(clock) + 144. Assert anointed(actor). Retract spread(scent_faded). }
    Result "Elspet looks at the yellow ribbon and nods and does it without a word, quicker than for a guest: forehead, throat, wrists. 'Kestrel's,' she says. 'Mind she pays you.'".
  }
  Rule elspet_smells at scenting_room when at(party, scenting_room) and usedNellOil(party) and scented() and not named(party) and not spread(elspet_smelled) says "Elspet Garnock leans in to smell you, out of habit, and stops. 'That is not mine,' she says, very quietly. 'That is very nearly mine.' She looks at you over her spectacles, and does not ask where you got it. You would rather she had." { Assert spread(elspet_smelled). }
  Entity elspet_smelled: fact "Elspet smells Nell's oil".
  Topic elspet_scent with elspet "Ask Elspet what the scent is" when true once {
    Says "'The Mother.' She holds up the jar. 'Every queen has her own smell, and every Sister born to her knows it, and knows that whatever smells of it is the hive, and whatever does not is a robber. So we take a little of what the Mother leaves on the comb where she walks, and we cut it with wax and oil, and we put it on our children the day they are born, and on ourselves at every feast. That is what it is to be of the Comb.' She stoppers the jar. 'On you it lasts a day. On us it never quite comes off.'".
  }
  Topic elspet_who with elspet "Ask Elspet who she will not scent" when true once {
    Says "'Anyone may be scented for a day, if they pay. That is hospitality.' She dries her hands, finger by finger. 'To be named, to be scented for life, is another thing. That is for those born to it, and for those the Comb takes in: a marriage, sometimes; a service. I decide. My mother decided before me.' She looks at you over the spectacles. 'People think it is a small thing, a smell. It is everything. It is the only thing the Sisters know about you.'".
  }
  Topic elspet_nell with elspet "Ask Elspet about Nell Quarrie" when knows(actor, nell_forges) and not nellNamed(nell) and not nellBarred(nell) once {
    Says "Her face goes very still. 'Aldo Quarrie's widow. A lowlander. She asked to be named after he died, so she could sit with him. I said no.' She says it without heat. 'He married out. He went down the gorge for eleven years. The Comb did not take her in; he took her out. It is not the same.' A pause. 'She asks me every year. I say no every year. I say it kindly, now,' she says. 'It took me some years to learn how.'".
  }
  Action expose_nell(actor: group, site: place) "Tell Elspet that Nell Quarrie forges the scent and goes up the stair in it" {
    Speaker elspet.
    Grave "Elspet will close the stair to Nell Quarrie for good; she will never sit with Aldo again.".
    Requires at(actor, site) and able(actor) and at(actor, scenting_room) and at(elspet, scenting_room) and knows(actor, nell_forges) and not nellNamed(nell) and not nellBarred(nell).
    Time 1.
    On success { Assert nellBarred(nell). }
    Result "Elspet hears you out without moving. Then she takes off her spectacles and folds them. 'Six years,' she says. 'Up my stair.' She sends the girl who sweeps the step running up the Comb for two of the Hum-keepers. 'Thank you,' she says to you, quite sincerely, and you understand that you have done a thing that cannot be taken back, and that she is grateful for it.".
  }
  // Agnes Mellor's word, from one Capper's widow for another's friend's: Aldo Quarrie was Tobit's friend.
  Relation agnesVouches(group).
  Action plead_nell(actor: group, site: place) "Ask Elspet to name Nell Quarrie to the Comb, on Agnes Mellor's word" {
    Speaker elspet.
    Requires at(actor, site) and able(actor) and at(actor, scenting_room) and at(elspet, scenting_room) and knows(actor, nell_forges) and agnesVouches(agnes) and not nellNamed(nell) and not nellBarred(nell).
    Time 2.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert nellNamed(nell). }
    Result "You tell her all of it: the oil, the six years, the fourth row on the left. And then what Agnes Mellor said, that Tobit sealed Aldo Quarrie himself and wept doing it, and that Nell sat with Tobit's body last week in the dark when nobody else would. Elspet turns a stoppered jar on her bench a quarter-turn, and another. 'She has been coming up my stair,' she says at last, 'for six years, to sit in the dark with a dead man, because I would not let her do it in the light.' She puts her spectacles back on. 'Tell her to come in the morning. I will do it properly. The way it is done for a bride.'".
    Otherwise "Elspet hears you out and shakes her head. 'You are asking me to reward a forger for forging.' She turns back to the basin. 'Ask me again when I have slept on it.'".
  }

  // The Apron's market: food, of the Comb's kind.
  Person doll "Doll Rowntree" at apron {
    Role "a stallholder by the troughs, with a griddle, a fly-whisk, and forearms like hams".
    Ancestry human. Peaceable. Pronouns she. Manner jovial.
    Sells rations for 1 coin from 20.
    Sells bee_bread for 1 coin from 6.
    Greets "'Honey-cake, bee-bread, comb on a leaf, mead by the horn,' says the woman at the griddle, 'and brood, fried, hot, the best in the Brow, a coin the cone. Go on. The Escort eat it every night and they're the handsomest men in the Wold.' She laughs until she has to hold on to the trough.".
    Greets again "Doll Rowntree waves her fly-whisk at you. 'Hungry?'".
  }
  Topic doll_brood with doll "Ask Doll Rowntree why the Escort eat fried brood" when true once {
    Says "'Because it's drone brood, love.' She flips a cone of it on the griddle: little pale curls in golden wax, crackling. 'Drones. Lads. Born to do nothing but follow the princess up the Toot. Fed and pampered and good for nothing else, and then turned out, come the autumn.' She grins. 'So we feed the Escort on drones. They think it's a compliment.' She shrugs. 'Might be. Might not. It's been done since before the Comb, and nobody's ever said which.'".
  }
  Topic doll_who with doll "Ask Doll Rowntree who is going" when not leavingBegun() {
    Says "'Me? Staying. I've a griddle that weighs more than me and the Mother's got no use for brood fried or otherwise.' She fans the coals. 'My sister's going. My boy's going. Searcher, he is, like his dad was.' She fans harder. 'He's twenty-two. You can't keep them.' She does not look up for a while.".
  }
  Observe apron_after at apron when leavingBegun() "The Apron is too quiet. The Sisters still come and go overhead, but thinly, a stream where there was a river; half the stalls are bare boards; and the people who are left stand about in twos and threes, not talking much, looking up at the Comb as if it were somebody's house after a funeral.".
}

data/adventures/half-the-hive/calling.ky:
Module hume "Half the Hive" {
  // ── The Calling ───────────────────────────────────────────────────────────────────────────────────────────────────
  // At six on the second evening, in the Dancing Hall, every household says aloud who goes and who stays. Keepers and
  // Searchers are not asked; they go. The Escort is not asked; it is the Escort. What each says is what each has come to
  // by then, so the Calling is where the week shows itself. Huw Penry's cask is broached at the end.
  Occasion the_calling "the Calling" at dancing_hall when day(clock) >= 2 and hour(clock) >= 18 and not leavingBegun() {
    Matter call_open "Elspet Garnock, the Scent-warden, strikes the slope three times with a staff of black wax, and the hall goes quiet, and the hum comes back into the quiet like water into a footprint." for 10 minutes.
    Matter call_keepers "'The keeper is not asked,' says Elspet. 'The keeper goes.' At the top of the slope, under the round window, Linnet Amory stands with her eyes on the floor." for 10 minutes.
    Matter call_searchers "'The Searchers are not asked,' says Elspet. 'The Searchers go.' Along the wall the Searchers stand up, one by one, Kestrel Dunn first." for 10 minutes.
    Matter call_households "'The households,' says Elspet, and one by one, from the front of the hall to the back, the heads of households stand up on the tilted floor and say it: so many go, so many stay, and the names. Some read it off a slate. Some cannot get it out, and someone beside them says it for them." for 20 minutes.
    Matter call_escort "'The Escort,' says Elspet, 'is not asked.' A few people laugh, the way they always laugh at that, and along the back wall a row of yellow coats sits very straight and smiles." for 10 minutes.
    Matter call_mead "Huw Penry comes in with two of the Waxwrights rolling his great barrel, and stands it on its end at the foot of the slope, and knocks in the tap, and the whole hall holds out its cups." for 10 minutes.
    Closes "Elspet strikes the slope three times. 'It is said,' she says. What is said at a Calling is not unsaid. People go out of the hall in silence, holding on to each other on the slope, and in the Brood gallery outside somebody begins to cry, and somebody else begins, very badly, to sing.".
  }
  // Everyone of the Comb is in the hall for it.
  Rule calling_gathers when occasionBegun(the_calling) and not occasionOver(the_calling) and not at(linnet, dancing_hall) and not spread(calling_gathered) {
    Assert at(linnet, dancing_hall). Assert at(eben, dancing_hall). Assert at(agnes, dancing_hall). Assert at(huw, dancing_hall). Assert at(elspet, dancing_hall). Assert at(pim, dancing_hall).
    Assert spread(calling_gathered). }
  Rule calling_disperses when occasionOver(the_calling) and spread(calling_gathered) and not spread(calling_dispersed) {
    Assert at(linnet, mothers_chamber). Assert at(eben, wax_gallery). Assert at(agnes, mellor_cell). Assert at(huw, honey_vaults). Assert at(elspet, scenting_room). Assert at(pim, mothers_chamber).
    Assert spread(calling_dispersed). }
  Entity calling_gathered: fact "the Comb in the hall". Entity calling_dispersed: fact "the Comb gone home".

  // The keepers.
  Rule call_linnet_knows at dancing_hall when matterOpen(call_keepers) and linnetKnows(linnet) and not spread(said_linnet) says "Linnet lifts her head and looks straight down the slope across the whole hall at Eben Candlish, and he looks back, and a few people who know turn to see what she is looking at." { Assert spread(said_linnet). }
  Rule call_linnet_hides at dancing_hall when matterOpen(call_keepers) and not linnetKnows(linnet) and knows(party, linnet_secret) and not spread(said_linnet) says "You know what she means to say on the morning of the Leaving: that she is ill, that Pim must go. You are the only one in the hall who knows it. Pim, beside her, is beaming." { Assert spread(said_linnet). }
  Entity said_linnet: fact "the keeper at the Calling".
  // The Searchers.
  Rule call_hannet_carried at dancing_hall when matterOpen(call_searchers) and promiseMade(carry_hannet) and not spread(said_hannet) says "Hannet Coke gets up off the floor on her stick. 'Hannet Coke goes,' she says, in a voice that carries, 'carried, like a cheese, by this lowlander and whoever else they can bully into it,' and the hall laughs out loud, and some of them are crying as they laugh, because she has stayed six times." { Assert spread(said_hannet). }
  Rule call_hannet_stays at dancing_hall when matterOpen(call_searchers) and hannetStopped(hannet) and not promiseMade(carry_hannet) and not spread(said_hannet) says "Hannet Coke does not get up. When Elspet looks at her she says, from the floor, 'Hannet Coke stays,' quite steadily, and puts her hand inside her collar, where something hangs on a cord." { Assert spread(said_hannet). }
  Rule call_hannet_tree at dancing_hall when matterOpen(call_searchers) and dancesFor(hannet, gallowtree) and not spread(said_hannet) says "Hannet Coke gets up on her stick with the rest, beaming, seventy years old, going at last." { Assert spread(said_hannet). }
  Entity said_hannet: fact "Hannet at the Calling".
  Rule call_moss_hurt at dancing_hall when matterOpen(call_searchers) and mossHurt(moss) and not spread(said_moss) says "One Searcher does not stand: Moss Ashdown, propped against the wall with his side bound up, looking at his knees. 'Moss stays,' Kestrel says for him, not unkindly. 'Can't walk.'" { Assert spread(said_moss). }
  Entity said_moss: fact "Moss at the Calling".
  // The households.
  Rule call_agnes_carries at dancing_hall when matterOpen(call_households) and linnetPermitsDead(linnet) and not spread(said_agnes) says "Agnes Mellor stands up. 'The Mellors,' she says. 'Agnes goes. And Tobit Mellor goes with her, by leave of the keeper.' There is a sound in the hall like wind in a wood. Somebody says, 'The dead stay,' and somebody else says, 'Hush,' and Linnet Amory, at the top of the slope, says clearly, 'Not this one.'" { Assert spread(said_agnes). }
  Rule call_agnes_likeness at dancing_hall when matterOpen(call_households) and likenessGiven(agnes) and not linnetPermitsDead(linnet) and not spread(said_agnes) says "Agnes Mellor stands up with something wrapped in her shawl held against her chest. 'The Mellors. Agnes goes.' She looks down at the shawl. 'Both of us,' she says, and sits down." { Assert spread(said_agnes). }
  Rule call_agnes_free at dancing_hall when matterOpen(call_households) and agnesFreed(agnes) and not spread(said_agnes) says "Agnes Mellor stands up. 'The Mellors. Agnes goes. Tobit stays, with the others, safe.' Her voice holds all the way." { Assert spread(said_agnes). }
  Rule call_agnes_stays at dancing_hall when matterOpen(call_households) and not spread(said_agnes) says "Agnes Mellor stands up. 'The Mellors,' she says. 'Agnes stays.' People turn to look at her; everyone knew the Mellors meant to go. 'I'll not leave him alone up there,' she says, to the floor, and sits down." { Assert spread(said_agnes). }
  Entity said_agnes: fact "Agnes at the Calling".
  Rule call_eben_both at dancing_hall when matterOpen(call_households) and linnetKnows(linnet) and not spread(said_eben) says "When the Candlishes are called, old Abel Candlish starts to say that the household stays, all of it, and Eben stands up beside him and says over him, 'Eben Candlish goes,' and looks up the slope at the keeper; and the old man stops, and looks at his son, and sits down." { Assert spread(said_eben). }
  Rule call_eben_stays at dancing_hall when matterOpen(call_households) and ebenKnows(eben) and not linnetKnows(linnet) and not spread(said_eben) says "When the Candlishes are called, old Abel Candlish says the household stays, and Eben, beside him, says nothing at all, and looks up the slope at the keeper, and goes on looking." { Assert spread(said_eben). }
  Rule call_eben_hides at dancing_hall when matterOpen(call_households) and knows(party, eben_secret) and not spread(said_eben) says "When the Candlishes are called, old Abel Candlish says the household stays, all of it, and Eben, beside him, keeps his face perfectly still. You know he means to walk out after the bees on the day without a word to anyone. Nobody else does." { Assert spread(said_eben). }
  Entity said_eben: fact "Eben at the Calling".
  Rule call_brecks at dancing_hall when matterOpen(call_households) and not spread(said_brecks) says "Dame Brenna Breck stands up, very upright, in a black gown with a silver bee on it. 'The Brecks stay. All of us. We keep a princess.' She sits down as if she had won something." { Assert spread(said_brecks). }
  Entity said_brecks: fact "the Brecks at the Calling".
  // The Escort.
  Rule call_ivo at dancing_hall when matterOpen(call_escort) and ivoSearcher(ivo) and not spread(said_ivo) says "And then one of the yellow coats stands up. 'Ivo Gildersleeve,' says Ivo, in a voice that fills the hall to the round window. 'Searcher. Goes.' There is an uproar: laughter, shouting, someone's cup going over. Elspet strikes the slope with her staff for quiet and does not get it. Then Kestrel Dunn says, from the wall, not loudly, 'He does,' and the hall goes quiet as if she had shut a door." { Assert spread(said_ivo). }
  Entity said_ivo: fact "Ivo at the Calling".
  // The mead.
  Rule call_mead_miracle at dancing_hall when matterOpen(call_mead) and meadSecret(huw) and not spread(said_mead) says "The mead comes out of the tap gold and clear and smelling of heather and lime-flower, and a silence goes down the hall as people taste it, and then a long low sound of four hundred people saying oh. Huw Penry stands by his barrel with tears running into his beard and tells everyone near him that it started again on its own in the night, by the Mother's grace, and that he always knew it would; and he believes it, and so, by the end of the evening, does the hall." { Assert spread(said_mead). }
  Rule call_mead_good at dancing_hall when matterOpen(call_mead) and meadSaved(huw) and not spread(said_mead) says "The mead comes out of the tap gold and clear and smelling of heather and lime-flower, and a silence goes down the hall as people taste it, and then a sound, a long low sound of four hundred people saying oh. It tastes like the best day of a summer you had when you were young. Huw Penry stands by his barrel with tears running into his beard, saying to everyone near him that it came to him in a dream." { Assert spread(said_mead). }
  Rule call_mead_bad at dancing_hall when matterOpen(call_mead) and not meadSaved(huw) and not spread(said_mead) says "The mead comes out of the tap thick and cloudy and sweet as syrup, unworked, and the hall drinks it because it is the Calling, and says how fine it is, and Huw Penry stands by his barrel and smiles and smiles, and you can see he would rather be dead." { Assert spread(said_mead). }
  Entity said_mead: fact "the mead at the Calling".
}

data/adventures/half-the-hive/clock.kyr:
Module hume "Half the Hive" {
  // ── The week ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // The country's days are counted from the first morning after the company comes (day(clock) is 1 then). The Calling
  // is on the evening of the second day; the Mother will not go before it. From the third noon she goes as soon as
  // five dance for one place. At dawn on the fourth day Squire Corve uncorks his flask at Larkhill; at noon on the
  // fourth day she goes, to the flask if it is open, or where most dance. The Daughters wake the night she goes; the
  // new queen flies two days after; the Escort is turned out that dusk, and the book closes.
  Query daytime() means hour(clock) >= 7 and hour(clock) < 20.
  Query night() means hour(clock) >= 22 or hour(clock) < 5.
  Query inWold() means at(party, ?p) and wold(?p).
  Query inComb() means at(party, ?p) and combRoom(?p).
  Relation spread(fact).

  // ── Chapters ──────────────────────────────────────────────────────────────────────────────────────────────────────
  Chapter hum_drops "The Hum Drops a Note" when inWold() "In the Wold of Hume the limes are in flower, the queen-cells in the Comb were capped six days ago, and every household under the Brow is deciding who goes. The hum has dropped a note. Anyone in the Wold can hear it, if they know what it sounded like before.".
  Chapter searching "The Searching" when day(clock) >= 2 and hour(clock) >= 6 and inWold() and not leavingBegun() "All over the Wold the Searchers are out: walking the lindens, the moor, the chalk, looking into every hollow big enough to hold two hundred people and a cloud of bees. In the Dancing Hall the dances have begun to lean one way, then another. The Mother will not go before the Calling, tonight. After that she will go when five dance for one place, and not before; unless something else decides it.".
  Chapter calling "The Calling" when occasionBegun(the_calling) and not occasionOver(the_calling) and within(party, comb) "At six the hum in the Dancing Hall is drowned out for once by people: the whole of Hume Brow crowded onto the tilted floor, standing, sitting, holding on to each other so as not to slide. The Calling. Every household, in turn, will say aloud who goes with the Mother, and who stays.".
  Chapter leaving_ch "The Leaving" when leavingBegun() and inWold() "She goes.".
  Chapter daughters_ch "The Daughters" when leavingBegun() and leftNight() and inComb() "In the half-empty Comb, in the royal gallery, something is moving inside the wax.".
  Chapter turning_ch "The Turning-out" when flightDay() and inWold() "Two days after the Leaving the new queen flies, and the Escort walks behind her in yellow; and at dusk, by a custom older than the Comb, the Escort is turned out.".

  // ── The Sisters know their own ────────────────────────────────────────────────────────────────────────────────────
  // A scent lasts a day from the Scenting House (Searchers' and guests' alike), half a day from Nell's oil; for one named
  // to the hive it does not wear off. In the Comb unscented, a Sister tastes you; the watch after, they sting. A
  // smoking smoker carried makes them slow, and they do not.
  Measure scentUntil(group). Relation named(group). Relation anointed(group). Relation tasted(group). Measure tastedAt(group).
  Query scented() means named(party) or anointed(party) and scentUntil(party) > watch(clock).
  Query smoking() means holding(party, bee_smoker).
  Hazard sting "a Sister's sting" means "Deal (2d6) poison damage to ally unless constitution save against (12).".
  Rule sisters_taste when inComb() and not scented() and not smoking() and not tasted(party) and not leftNight() says "A Sister lands on the wall beside you, as big as a hound, and turns her head; and then she is on your shoulder, light as a cat, and her feelers are going over your face and hair, quick, quick, tasting. The hum near you goes up half a note. Someone in the gallery says sharply, 'You're not scented. Get out, or get smoke.'" { Assert tasted(party). Set tastedAt(party) to watch(clock). }
  Rule sisters_sting when at(party, ?p) and combRoom(?p) and not scented() and not smoking() and tasted(party) and watch(clock) > tastedAt(party) and not leftNight() says "The Sisters come for you. One, then three, then the air is full of them, and a sting goes in like a hot nail driven, and there is a smell like bananas, sharp and sudden, and more come to it. A Sister that stings dies of it, tearing; you see her drop and crawl. You get your arms over your head and run, down and down, out of the Comb into the light of the Apron, with the hum roaring after you." { Assert strikes(sting, party). Set tastedAt(party) to watch(clock). Retract at(party, ?p). Assert at(party, apron). }
  Rule sisters_forget when tasted(party) and not inComb() { Retract tasted(party). }
  Rule scent_fades when inWold() and anointed(party) and scentUntil(party) <= watch(clock) + 6 and not named(party) and not spread(scent_faded) says "You catch the smell of yourself, as the air moves: your own smell, coming back through the Mother's, like a stone coming up through snow. The anointing is wearing off. Within the hour you will smell of nothing but yourself." { Assert spread(scent_faded). }
  Entity scent_faded: fact "the scent worn off".

  // ── The things of the Wold ──
  Kind wax_cake "a cake of Brow wax" is treasure worth 2 weighing 1 described "A round cake of yellow wax the size of a cheese, stamped with a hexagon. Searchers are paid in it; anyone in Smoke End will take it as money.".
  Kind sister_sting "a Sister's sting in a twist of paper" is gear worth 2 weighing 0 described "A Sister's sting, as long as your finger, barbed, with the little white sac of venom still on the end of it, folded in a twist of brown paper. Even through the paper it smells sharply of bananas.".
  Kind nell_oil "a phial of Nell Quarrie's oil" is gear worth 1 weighing 0 described "A tiny stoppered phial of something gold and thick that smells, when you unstop it, so exactly like the Comb that your mouth waters. It is not quite right. You cannot say how.".
  Kind fine_candles "a bundle of fluted Brow candles" is treasure worth 6 weighing 1 described "Six tall white candles, fluted like columns, from the Drewes' moulds. A Brow candle burns three nights and smells of summer.".
  Kind white_wax "a slab of white comb" is treasure worth 4 weighing 1 described "A slab of old comb, white and fine as paper, that was never used for brood: the first comb a new swarm draws. It smells of nothing at all, which is how you know how old it is.".
  Kind old_comb "a slab of old black comb" is gear worth 0 weighing 1 described "A slab of brood comb gone black with a hundred years of being lived in: tough as leather, smelling of bees and old honey and something animal.".
  Kind found_phial "a little phial Agnes found" is gear worth 0 weighing 0 described "A tiny stoppered phial, empty, with a smear of something gold dried round its lip that smells, faintly, of the Comb, and not quite.".
  Kind tobit_likeness "a wax likeness of Tobit Mellor" is gear worth 0 weighing 1 described "A little figure as long as your forearm, carved in gold and white wax: a stocky man in a capping apron with his sleeves rolled, his head a little on one side.".
  Kind deathshead_wing "a death's-head moth's wing" is treasure worth 5 weighing 0 described "A wing the size of a hand-mirror, brown and grey as a dead leaf, dusted soft, with a pale ring on it like an eye.".
  Kind bee_bread "a loaf of bee-bread" is gear worth 1 weighing 0 described "A small brown loaf of pollen packed by the Sisters into the comb and soured there: bitter, nutty, sticky, the colour of an old penny.".
  Kind wild_comb "a slab of wild comb" is treasure worth 3 weighing 1 described "A slab of wild comb from the honey linden, black and gold, dripping, with a dead small bee or two in it, which is how you know it is real.".
  Kind queen_flask "the squire's flask" is gear worth 0 weighing 1 described "A flask of thick green glass, stoppered and wired and sealed with red wax, warm to the touch. Even through the glass and the wax you can smell it: the Mother, stronger than the Mother, so strong it makes your head swim.".
  Kind wax_bee "a little bee carved in wax" is gear worth 0 weighing 0 described "A bee no bigger than your thumb, carved in yellow wax gone brown, every leg and every vein of the wing, made by someone with time and love and a very fine blade.".
  Kind queen_cage "a queen-cage of wax rods" is gear worth 0 weighing 0 described "A little lantern of thin wax rods, Waxwright's work, hinged to close round a princess-cell, so that what comes out of it can come out, and what wants to get in cannot.".
  // A smoker, a veil.
  Kind bee_smoker "a bee-smoker" is gear worth 3 weighing 2 described "A tin can with a spout and a little leather bellows, stuffed with smouldering bracken and dried dung. Squeeze, and it gives a puff of cool grey smoke, and any bee it touches goes slow and stupid and thinks of honey.".
  Kind bee_veil "a bee-veil" like cloak worth 2 weighing 1 described "A broad hat of plaited straw with a curtain of black horsehair gauze hanging all round it to the shoulders, tied under the arms.".

  // ── Places once seen ──────────────────────────────────────────────────────────────────────────────────────────────
  // The four places the Mother might go, and the room in each from which a Searcher can say she has seen it.
  Relation hollowSite(place). Relation seenFrom(place, place).
  Initially Assert hollowSite(gallowtree). Initially Assert hollowSite(chalk_dell). Initially Assert hollowSite(larkhill). Initially Assert hollowSite(far_brow).
  Initially Assert seenFrom(gallow_hollow, gallowtree). Initially Assert seenFrom(dell_floor, chalk_dell). Initially Assert seenFrom(chantry_nave, larkhill). Initially Assert seenFrom(far_hollow, far_brow).
  Query hasSeen(s: place) means been(party, ?r) and seenFrom(?r, s).
}

data/adventures/half-the-hive/company.ky:
Module hume "Half the Hive" {
  // The campaign played alone: a traveller come up the drove road from the march on a June morning, with a little
  // money and no particular reason to be here. (placed.kyr is the world's own company, come over the march by the
  // same road.)
  Company party "You" of 1 to 3 at drove_end.
  Initially Set quantity(party, gold) to 10. Initially Set quantity(party, rations) to 2.
}

data/adventures/half-the-hive/dance.kyr:
Module hume "Half the Hive" {
  // ── Who dances for what ───────────────────────────────────────────────────────────────────────────────────────────
  // tally(place) is how many dance for it: the Sisters' own scouts (two for the Far Brow, one for the Dell, and one more
  // for the Dell once the brocks are no danger), and the Searchers: Kestrel for the Far Brow, Hannet for the Gallowtree,
  // Moss for the Dell; the company, once taught and having seen a place; Ivo, once he has seen one with the company;
  // Hannet again, if she is promised a way. Every change to who dances is made where it happens, with its tally.
  Measure tally(place). Relation dancesFor(group, place).
  Initially Set tally(far_brow) to 3. Initially Set tally(chalk_dell) to 2. Initially Set tally(gallowtree) to 1. Initially Set tally(larkhill) to 0.
  Initially Assert dancesFor(kestrel, far_brow). Initially Assert dancesFor(hannet, gallowtree). Initially Assert dancesFor(moss, chalk_dell).
  Relation sistersDell(place).

  // Where the Leaving camps at each, and the bivouac in the lindens.
  Relation siteRoom(place, place).
  Initially Assert siteRoom(gallowtree, gallow_knoll). Initially Assert siteRoom(chalk_dell, dell_floor).
  Initially Assert siteRoom(larkhill, chantry_yard). Initially Assert siteRoom(far_brow, far_hollow). Initially Assert siteRoom(high_wold, honey_oak).

  // ── The Dancing Hall, as it leans ─────────────────────────────────────────────────────────────────────────────────
  Observe hall_far at dancing_hall as sign when not leavingBegun() and tally(far_brow) > 0 "For the Far Brow, east over the moor, a long waggling run straight toward the window and a little left, a day's distance: {tally(far_brow) in words} dancing it.".
  Observe hall_dell at dancing_hall as sign when not leavingBegun() and tally(chalk_dell) > 0 "For the Chalk Dell, south-east: {tally(chalk_dell) in words}.".
  Observe hall_gallow at dancing_hall as sign when not leavingBegun() and tally(gallowtree) > 0 "For the Gallowtree, a short run west, two hours: {tally(gallowtree) in words}.".
  Observe hall_lark at dancing_hall as sign when not leavingBegun() and tally(larkhill) > 0 "For Larkhill, west, toward the lowland: {tally(larkhill) in words}.".
  Observe hall_sisters at dancing_hall as feature when not leavingBegun() "The Searchers do not dance alone. On the upper slope, where the wax is darkest, Sisters dance too, the bees' own scouts, huge and fast and silent, running their lines and turning; and where a Sister dances, the people watching go quiet and lean to read her.".
  Observe hall_quorum at dancing_hall as sign when committed() and not leavingBegun() "Something has changed in the hall. The dancers have stopped arguing. Every run on the slope, bee and human, goes the same way now, over and over, and the hum has gone up and up until the wax buzzes under your bare feet. She will go at noon.".
  Observe hall_empty at dancing_hall when leavingBegun() "The Dancing Hall is empty. The marks of this week's dances are the newest on the walls, pale and sharp among the old ones.".

  // ── Kestrel Dunn, Wardmistress of the Searchers ───────────────────────────────────────────────────────────────────
  Person kestrel "Kestrel Dunn" at dancing_hall {
    Role "the Wardmistress of the Searchers, lean and brown, two fingers short on her left hand" when not leavingBegun().
    Role "the Wardmistress of the Searchers, a lean brown woman with cropped grey hair, walking at the head of the Leaving" when leavingBegun().
    Ancestry human. Calling ranger. Level 4. Peaceable. Pronouns she. Manner acerbic.
    Greets "A lean brown woman at the foot of the slope looks you up and down the way a farrier looks at a horse. 'You came about the notice,' she says. It is not a question. 'Good. I've two hundred people to house by Midsummer and half my Searchers have decided to stay home and grow old. Can you walk? Can you look? Can you tell a dry hollow from a wet one? Then you'll do.'".
    Greets again "Kestrel looks round from the slope. 'Well? What have you found?'".
  }
  Relation searcher(group). Relation danceLearned(group). Relation reported(group, place).
  Discovery sites_named "Kestrel Dunn named the places the Searchers are dancing for: the Gallowtree, two hours west on its knoll, Hannet Coke's; the Chalk Dell, south-east, Moss Ashdown's; the Far Brow, a day east across the moor, her own; and something at Larkhill on the Wold's edge that the Sisters keep flying to, which she does not like.".
  Initially Assert leadsTo(sites_named, gallow_knoll). Initially Assert leadsTo(sites_named, dell_rim). Initially Assert leadsTo(sites_named, far_ledge). Initially Assert leadsTo(sites_named, larkhill_lane).
  Topic kestrel_hire with kestrel "Ask to be taken on as a Searcher" when not searcher(actor) and not leavingBegun() once {
    Says "'Taken on.' Kestrel takes a strip of yellow ribbon out of her belt and ties it round your arm, hard, with her teeth and her good hand. 'Elspet at the Scenting House will scent you for nothing while you wear that. You're paid in wax, a cake for every place you go and look at and come back and tell me about, honestly. Four places worth the walk, this year.' She counts on her short hand. 'The Gallowtree: Hannet's. Two hours west, on a knoll, big hollow lime, close, which is all Hannet cares about. The Chalk Dell: Moss's. South-east. Dry, warm, a cave in the chalk, and the brocks live in it, which Moss thinks is a selling point. The Far Brow: mine. A day east, over the moor, and the most beautiful place in the Wold. And Larkhill.' Her face shuts. 'A lowland squire's got a chapel on the Wold's edge, and for a week the Sisters' own scouts have been flying out to it and coming back excited, and I don't know why, and I don't like not knowing.'".
    On discuss { Assert searcher(actor). Assert knows(actor, sites_named). }
  }
  Topic kestrel_teach with kestrel "Ask Kestrel to teach you the dance" when searcher(actor) and not danceLearned(actor) once {
    Says "She stands you at the bottom of the slope with the sun coming in at the round window. 'Straight up is the sun. Wherever it is. Run up the slope, that's toward it; run off to the left of straight up, that's left of the sun, by as much.' She runs a line, waggling her hips, comically and then not comically at all: you see the moor in it. 'Waggle as long as it is far. Waggle as hard as it is good. Loop back, do it again, till they've got it.' She makes you do it, twenty times, thirty, until your legs know it and the Searchers sitting round the walls stop laughing. 'You dance like a lowlander,' she says at last. 'But it reads. Don't dance for anything you haven't stood in.'".
    On discuss { Assert danceLearned(actor). }
  }
  Topic kestrel_why with kestrel "Ask Kestrel why the Far Brow" when not leavingBegun() {
    Says "'Because it's the best place in the Wold, and because the Sisters think so too: look at them.' She nods up the slope at the bees' dancers. 'My gran said the Brow's founders came from there. I've danced for it at every Leaving since I was fourteen, and every time the Mother's gone somewhere nearer, and every time I've been right and they've been wrong. Ketter's damp. The Nine Holes have the moth. Sallowcomb starves every third winter.' She folds her arms. 'This time the bees are with me.' Then, quieter, almost to herself: 'It's a long walk. I know it's a long walk.'".
  }
  Topic kestrel_fingers with kestrel "Ask Kestrel about her hand" when true once {
    Says "She holds it up: thumb, first finger, and two neat stumps. 'Brock,' she says. 'In the Dell, when I was Moss's age and as stupid. I put my hand in a hole to feel how deep it went.' She puts the hand away. 'It went quite deep.'".
  }
  // Reports: a cake of wax for each, and what she makes of it.
  Topic report_gallow with kestrel "Tell Kestrel what you found at the Gallowtree" when searcher(actor) and hasSeen(gallowtree) and not reported(actor, gallowtree) and not leavingBegun() once {
    Says "She hears you out. When you tell her about the people in the comb inside the tree she wipes the dance-slate clean, though it is clean. 'The seventh Leaving,' she says. 'We say they went on east.' She gives you a cake of wax and does not look at you. 'Don't tell Hannet. Or do. I don't know. Her aunt went with them.'".
    On discuss { Assert reported(actor, gallowtree). Give cake_gallow to actor. Assert knows(actor, merrit_aunt). }
  }
  Topic report_dell with kestrel "Tell Kestrel what you found in the Chalk Dell" when searcher(actor) and hasSeen(chalk_dell) and not reported(actor, chalk_dell) and not leavingBegun() once {
    Says "'Dry. Warm. South. Yes.' She pays you. 'And the brocks?' She listens. 'If you can find a way to live beside them, it's not a bad place. If Moss's way is to go in there with a spear, it's a grave.'".
    On discuss { Assert reported(actor, chalk_dell). Give cake_dell to actor. }
  }
  Topic report_lark with kestrel "Tell Kestrel what you found at Larkhill" when searcher(actor) and hasSeen(larkhill) and not reported(actor, larkhill) and not leavingBegun() once {
    Says "'A tower.' She frowns. 'A good tower; I'll give him that. Dry, high, south wall.' She pays you. 'But it's his. Lowland law: what nests on a man's land is his. Two hundred of us and the Mother, rent-payers to a squire.' She spits, neatly, off the slope. 'Over my dead body. Over the Mother's.'".
    On discuss { Assert reported(actor, larkhill). Give cake_lark to actor. }
  }
  Topic report_far with kestrel "Tell Kestrel what you found at the Far Brow" when searcher(actor) and hasSeen(far_brow) and not reported(actor, far_brow) and not leavingBegun() once {
    Says "Her whole face changes when you say you've stood under it, as if you had brought her news of someone she loved. 'The handprints,' she says. 'Are they still there? My gran told me about the handprints.' She gives you two cakes of wax instead of one, and then looks at the second as if she does not know how it got into your hand, and lets you keep it.".
    On discuss { Assert reported(actor, far_brow). Give cake_far to actor. Give cake_far2 to actor. }
  }
  Item cake_gallow "a cake of Brow wax" is wax_cake at limbo. Item cake_dell "a cake of Brow wax" is wax_cake at limbo. Item cake_lark "a cake of Brow wax" is wax_cake at limbo.
  Item cake_far "a cake of Brow wax" is wax_cake at limbo. Item cake_far2 "a cake of Brow wax" is wax_cake at limbo.
  Discovery merrit_aunt "Hannet Coke's aunt, Merrit Coke, went with the seventh Leaving to the Gallowtree eighty-one years ago.".

  // The company's dance.
  Relation partyDances(place).
  Query dancedAny() means partyDances(?s).
  Action dance_for(actor: group, dest: place) "Dance for {dest} in the Dancing Hall" {
    Description "Run your line on the slope for a place you have stood in, and add your dance to those for it.".
    Requires able(actor) and company(actor) and at(actor, dancing_hall) and danceLearned(actor) and hollowSite(dest) and hasSeen(dest)
      and not dancedAny() and not committed() and not leavingBegun() and daytime().
    Time 3.
    Resolve check(actor, performance, dc_easy).
    On success { Assert partyDances(dest). Increase tally(dest) by 1. }
    Result "You run your line up the tilted floor toward the sun, waggling, and loop back, and run it again, and again. The first time the Searchers watch. By the fifth a Sister has come down the slope to stand beside you, her feelers on your back, reading you; and then she turns, and runs your line herself, faster and better.".
    Otherwise "You run your line, and loop, and run it; but you lose the angle on the loop, and the Searchers watching shake their heads, and a Sister who came down to read you turns away. Try again when you have your breath.".
  }
  Action dance_instead(actor: group, dest: place, old: place) "Dance for {dest} instead of {old}" {
    Description "Stop dancing for one place and dance for another, as the bees' own scouts do when they have seen something better.".
    Requires able(actor) and company(actor) and at(actor, dancing_hall) and danceLearned(actor) and hollowSite(dest) and hasSeen(dest)
      and partyDances(old) and distinct(dest, old) and not committed() and not leavingBegun() and daytime().
    Time 3.
    Resolve check(actor, performance, dc_easy).
    On success { Retract partyDances(old). Decrease tally(old) by 1. Assert partyDances(dest). Increase tally(dest) by 1. }
    Result "You stop running the old line and run the new one, and the Searchers who knew your first dance look at each other.".
    Otherwise "Your feet keep finding the old line. Try again when you have your breath.".
  }

  // ── Hannet Coke ───────────────────────────────────────────────────────────────────────────────────────────────────
  Person hannet "Hannet Coke" at dancing_hall {
    Role "the oldest of the Searchers, small and brown and bent, sitting on the slope with her stick across her knees" when not walked(hannet).
    Role "the oldest of the Searchers, small and brown and bent, sitting on a fleece with her stick across her knees and two wax bees on a cord round her neck" when walked(hannet).
    Ancestry human. Peaceable. Pronouns she. Manner cheerful.
    Greets "A tiny old woman sitting on the slope pats the wax beside her. 'Sit, sit, you'll slide. You're Kestrel's new legs? Good. Mine are seventy and they've struck. Two hours and then they sit down wherever they are and won't get up for anybody.' She laughs, a startling young laugh.".
    Greets again "Hannet pats the wax beside her. 'Sit.'".
  }
  Relation hannetStopped(group). Relation hannetToldRot(group).
  Topic hannet_why with hannet "Ask Hannet why she dances for the Gallowtree" when dancesFor(hannet, gallowtree) {
    Says "'Because I can walk there.' She says it simply. 'I've stayed six Leavings. Six. My mother stayed, and I stayed with her, and then my man stayed, and I stayed with him, and then I was too old for anyone to take me, and now they're all capped upstairs and I can go where I please, and I please to go with the Mother.' She taps her knee. 'Two hours. The Gallowtree's two hours. It's a big old hollow lime and the Sisters could fill it in a summer. Kestrel's Far Brow, now, that's a day across the moor and I'd be capped in the heather by teatime.'".
  }
  Topic hannet_rot with hannet "Tell Hannet the Gallowtree is rotten at its heart" when knows(actor, gallow_rotten) and dancesFor(hannet, gallowtree) and not hannetToldRot(actor) once {
    Says "She waves it away. 'They're all rotten in the middle, limes. That's how they get hollow. It's stood a thousand years, it'll stand twenty more, and twenty more is all I want of it.' She looks at you sidelong. 'You've been in it, then. Is it big?'".
    On discuss { Assert hannetToldRot(actor). }
  }
  Topic hannet_merrit with hannet "Tell Hannet what is inside the Gallowtree" when knows(actor, lost_leaving) and dancesFor(hannet, gallowtree) and not holding(actor, wax_bee) once {
    Says "You tell her: the comb gone grey, the people standing in it, the children. And the one by the door, uncapped, who capped all the others and then had nobody to do it for her. Hannet listens without moving. When you have finished she says, 'Merrit,' and then nothing, her mouth working. 'My aunt Merrit went with the seventh. She was the Capper's girl. She gave me a wax bee when I was four and said she'd send for me.' She puts her hand flat on the slope, on the line she has been dancing all week, as if to stop it. 'They didn't go on east, then.' After a while she gets up, very slowly, with her stick, and goes and sits by the wall, and does not dance any more.".
    On discuss { Assert hannetStopped(hannet). Retract dancesFor(hannet, gallowtree). Decrease tally(gallowtree) by 1. Assert knows(actor, merrit_aunt). }
  }
  Promise carry_hannet "to see Hannet Coke carried wherever the Mother goes" to hannet
    kept when leavingBegun() and goes(hannet) "Somewhere in the Leaving, Hannet Coke is being carried, and is complaining about it, and is there."
    broken when leavingBegun() and not goes(hannet) "Hannet Coke is not in the Leaving. You promised." { Assert failedHannet(party). }.
  Relation failedHannet(group).
  Topic hannet_promise with hannet "Promise Hannet she will be carried, wherever the Mother goes" when hannetStopped(hannet) and not promiseMade(carry_hannet) and not leavingBegun() once {
    Grave "A promise to an old woman that she will go: if the Leaving goes without her, you broke it.".
    Says "Hannet looks at you, and laughs, and then stops laughing because you are not. 'Carried. Like a cheese to market.' She thinks about it. 'There's a litter in the Searchers' store, for the hurt ones. Two to carry it, four for the moor.' She grips your wrist with a hand like a bundle of twigs. 'If you mean it, I'll dance again. Not for the tree. Tell me where, and I'll dance it, and they'll know old Hannet's seen sense.'".
    On discuss { Assert promiseMade(carry_hannet). }
  }
  Action ask_hannet_dance(actor: group, dest: place) "Ask Hannet to dance for {dest}" {
    Speaker hannet.
    Requires able(actor) and at(actor, dancing_hall) and at(hannet, dancing_hall) and promiseMade(carry_hannet) and partyDances(dest)
      and not dancesFor(hannet, ?any) and not committed() and not leavingBegun().
    Time 2.
    On success { Assert dancesFor(hannet, dest). Increase tally(dest) by 1. }
    Result "Hannet gets up on her stick, and goes to the slope, and watches you run your line twice, with her head on one side; and then she runs it herself, very short, very slow, every waggle exact, an old woman's dance, and the Searchers round the walls stop talking to watch her do it.".
  }

  // ── Moss Ashdown ──────────────────────────────────────────────────────────────────────────────────────────────────
  Person moss "Moss Ashdown" at dancing_hall {
    Role "a Searcher, nineteen, freckled, with a boar-spear he will not put down" when not mossHurt(moss).
    Role "a Searcher, nineteen, freckled, with his arm and side bound up in bloody linen" when mossHurt(moss).
    Ancestry human. Calling warrior. Level 2. Peaceable. Pronouns he. Manner jovial.
    Greets "A freckled boy with a boar-spear grins at you. 'You're the lowlander? I'm Moss. I'm dancing for the Dell. Best place in the Wold, the Dell: dry as a bone, warm as an oven, faces south, and the brocks are in it, which means there's nothing else is.' He hefts the spear. 'There'll be nothing in it at all, once I've been.'".
    Greets again "Moss raises his spear to you.".
  }
  Relation mossHurt(group). Relation mossWaits(group). Relation mossWent(group).
  Topic moss_brocks with moss "Ask Moss what he means to do about the brocks" when not mossHurt(moss) and not brocksSafe() and not mossWent(moss) {
    Says "'Kill them.' He says it the way you would say you were going to mend a gate. 'There's two. Sows, both, big as ponies. I'll go in at first light the day after the Calling, when they're sleepy, with this,' the spear, 'and there'll be a song about it in every comb in the Wold. Kestrel lost two fingers there. I'll bring her two claws.' He looks at you to see if you are impressed. Under the grin he is very young and a little white.".
  }
  Action talk_moss_down(actor: group, site: place) "Talk Moss into waiting for you before he goes into the Dell" {
    Speaker moss.
    Requires able(actor) and at(actor, site) and at(moss, site) and not mossHurt(moss) and not mossWaits(moss) and not brocksSafe() and not mossWent(moss).
    Time 1.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert mossWaits(moss). Assert willing(moss, actor). }
    Result "Moss argues, and blusters, and in the end lets out a long breath that might be relief. 'Together, then,' he says. 'Ask me when you're going, and I'll come. But I get the first blow.'".
    Otherwise "'You sound like my mother,' says Moss, and turns his back on you to sharpen his spear.".
  }
  // On the third morning, at first light, he goes, unless he waits for the company or there is nothing to go for.
  Rule moss_goes when day(clock) >= 3 and hour(clock) >= 5 and not mossWaits(moss) and not mossWent(moss) and not brocksSafe() and not mossHurt(moss) and not leavingBegun() {
    Assert mossWent(moss). Assert mossHurt(moss). Retract dancesFor(moss, chalk_dell). Decrease tally(chalk_dell) by 1. Assert at(moss, mellor_cell).
  }
  Rule moss_brought_back at dancing_hall when mossHurt(moss) and mossWent(moss) and not spread(moss_back) says "There is shouting on the foot stair. They are carrying Moss Ashdown up out of the gorge on a hurdle, grey as wax, with his spear broken and his side opened from the ribs to the hip. He went into the Dell alone at first light. The brocks were not sleepy." { Assert spread(moss_back). }
  Entity moss_back: fact "Moss carried back".
  Topic moss_hurt with moss "Sit with Moss a while" when mossHurt(moss) once {
    Says "He is lying in the Mellors' cell because it was nearest, with Agnes Mellor sponging his side, and he is not grinning. 'There's no song,' he says. 'Is there. There's no song about the one who got carried home.' He can't go with the Leaving now; he can't walk. He knows. He turns his face to the wax.".
  }

  // ── When she goes ─────────────────────────────────────────────────────────────────────────────────────────────────
  // Called to a place, by quorum after the Calling, by the flask, or at noon on the fourth day by the most dances or none.
  Relation calledTo(place). Measure calledAt(place).
  Query committed() means calledTo(?s).
  Query swarmReady() means occasionOver(the_calling).
  Query outdone(s: place) means hollowSite(?o) and distinct(?o, s) and tally(?o) >= tally(s).
  Rule quorum when swarmReady() and hollowSite(?s) and tally(?s) >= 5 and not committed() and not leavingBegun() { Assert calledTo(?s). Set calledAt(hume_wold) to watch(clock). }
  Rule flask_calls when swarmReady() and flaskAt(?s) and hour(clock) >= 10 and hour(clock) < 13 and not committed() and not leavingBegun() { Assert calledTo(?s). Assert flaskCalled(?s). Set calledAt(hume_wold) to watch(clock). }
  Rule noon_leader when day(clock) >= 4 and hour(clock) >= 12 and hollowSite(?s) and tally(?s) > 0 and not outdone(?s) and not committed() and not leavingBegun() { Assert calledTo(?s). Set calledAt(hume_wold) to watch(clock). }
  Rule noon_bivouac when day(clock) >= 4 and hour(clock) >= 12 and not committed() and not leavingBegun() { Assert calledTo(high_wold). Set calledAt(hume_wold) to watch(clock). }
  Relation flaskCalled(place).
  Rule called_told at dancing_hall when committed() and not spread(called_told) says "On the slope every dance, bee and human, runs the same way now, over and over. The Searchers stand up one by one along the walls. Kestrel Dunn says, not loudly, 'That's it, then.'" { Assert spread(called_told). }
  Entity called_told: fact "the dance agreed".

  // She goes, between eleven and three, at least half an hour after she is called.
  Relation left(place). Measure leftDay(place).
  Query leavingBegun() means left(?s).
  Query leftNight() means leavingBegun() and (day(clock) == leftDay(hume_wold) and hour(clock) >= 20 or day(clock) == leftDay(hume_wold) + 1 and hour(clock) < 6).
  Query flightDay() means leavingBegun() and day(clock) >= leftDay(hume_wold) + 2.
  Rule she_goes when calledTo(?s) and hour(clock) >= 11 and hour(clock) < 15 and watch(clock) >= calledAt(hume_wold) + 3 and not leavingBegun() {
    Assert left(?s). Set leftDay(hume_wold) to day(clock). }
  Rule leaving_seen when leavingBegun() and within(party, hume_brow) and not spread(leaving_seen) says "It begins as a change in the hum: up, and up, a whole octave, until the gorge rings with it like a struck bell. Then out of every door and crack and window of the Comb at once, the Sisters pour. Not in streams: in a flood, a brown roaring flood, filling the air of the gorge from wall to wall, so many and so loud that the sun goes dim and you cannot hear yourself shout. They boil up over the lip of the Brow in a column a quarter of a mile wide. Somewhere in the middle of it, invisible, is the Mother. And down the foot stair, out of the doors, with bundles on their backs and veils on their heads and little bells tied on their wrists so as not to lose each other, come the people who are going: two hundred of them, walking fast, not looking back, while the people who are staying stand at the troughs and on the Apron and in the doorways and watch them go. At the foot of the stair the keeper of the Leaving looks back once, at you, and lifts a hand: come, if you are coming. Behind you, up in the Comb, three cells hang in a quiet gallery with a night to wake in." { Assert spread(leaving_seen). }
  Rule leaving_heard when leavingBegun() and inWold() and not within(party, hume_brow) and not spread(leaving_seen) says "From the direction of the gorge comes a sound like the sea getting up, and then the whole sky over the Brow goes brown, and moves." { Assert spread(leaving_seen). }
  Entity leaving_seen: fact "the Leaving seen".

  // Walking with it: from Hume Brow or Smoke End, on the day it goes, in the afternoon.
  Relation walkedWith(group).
  Query walkable(s: place) means left(s) and distinct(s, far_brow) and day(clock) == leftDay(hume_wold) and hour(clock) < 17.
  Action walk_with(actor: group, dest: place, camp: place) "Walk with the Leaving" {
    Description "Go with them, behind the swarm, to wherever she has gone.".
    Requires able(actor) and company(actor) and (within(actor, hume_brow) or within(actor, smoke_end)) and walkable(dest) and siteRoom(dest, camp) and not walkedWith(actor).
    Time 24.
    On success { Assert walkedWith(actor). Assert at(actor, camp). }
    Result "You walk with them. The talk dies away after the first mile. The swarm goes ahead of you like a weather-front, low, roaring, settling on a tree to rest and lifting off again, and the Leaving follows it at a walk, two hundred people strung out over the turf with their bundles, the old on sticks and on each other's arms, the children riding on shoulders, the little bells on everyone's wrists going all the way along the line, so that from a distance you would think a flock of sheep was crossing the Wold. Twice someone stops and turns round and looks back at the Brow. Then they turn round again and walk on.".
  }
  Action walk_with_far(actor: group, camp: place) "Walk with the Leaving, east over the moor" {
    Description "Go with them, behind the swarm, over the moor to the Far Brow: a long day.".
    Requires able(actor) and company(actor) and (within(actor, hume_brow) or within(actor, smoke_end)) and left(far_brow) and siteRoom(far_brow, camp)
      and day(clock) == leftDay(hume_wold) and hour(clock) < 16 and not walkedWith(actor).
    Time 54.
    On success { Assert walkedWith(actor). Assert at(actor, camp). }
    Result "You walk with them, all the long afternoon and into the evening, east over the moor behind a roaring cloud. The heather is waist-high and the bees in it are wild and small and indifferent. The line stretches and stretches; the old fall behind and the young go back for them; the little bells on everyone's wrists go on, all down the moor, a mile of bells. Near sunset, ahead, you see the Far Brow catch the light; and the swarm, which has been going in long low loops all day, goes straight at it, like water finding a drain, and pours in under the rock.".
  }
}

Module hume "Half the Hive" {
  // ── The Daughters ─────────────────────────────────────────────────────────────────────────────────────────────────
  // Three princess cells in the royal gallery, each watched by a household: the Brecks', the Candlishes', the
  // Ashdowns'. The night the Mother goes, the first princess wakes, pipes, and the others answer from inside; at two in
  // the morning she goes to their cells and stings them through the wax. The Brecks' wakes first because Dame Brenna has
  // fed it at night with a spoon; unless it is pierced in its cell first. A caged cell she cannot reach: its princess
  // wakes the next day and goes with a cast, a second, smaller Leaving. Caging needs the keeper's leave.
  Person brenna "Dame Brenna Breck" at royal_gallery {
    Role "the head of the Brecks: a tall old woman in black with a silver bee at her throat, sitting very upright under the first princess-cell".
    Ancestry human. Peaceable. Pronouns she. Manner proud.
    Greets "A tall old woman in black under the first princess-cell inclines her head to you a quarter of an inch. 'Dame Brenna Breck. That is our cell.' She does not need to say whose. 'You will forgive me if I do not get up. A watcher does not get up.'".
    Greets again "Dame Brenna inclines her head a quarter of an inch.".
  }
  Person watchers "Abel Candlish and Wenn Ashdown" at royal_gallery {
    Role "the watchers of the other two cells: Eben's old father on one stool, Moss's freckled mother on the other, not speaking".
    Ancestry human. Numbers 2. Peaceable. Pronouns they.
  }
  Relation brennaShamed(group). Relation pimConsents(group). Relation breckPierced(group). Relation emerged(entity). Relation castTomorrow(group). Relation castWent(group).
  Relation stung(entity). Relation caged(entity). Relation royalCell(entity).
  Thing cell_breck "the Breck princess-cell" at royal_gallery {
    State sealed "The first princess-cell, the Brecks', is fatter than the others, and darker, and very faintly moving.".
    State pierced "The first princess-cell, the Brecks', hangs with a slit in its side, dark and wet.".
    State open "The first princess-cell, the Brecks', hangs open at the bottom like a cup, empty.".
  }
  Thing cell_candlish "the Candlish princess-cell" at royal_gallery {
    State sealed "The second princess-cell, the Candlishes', hangs still, a little paler.".
    State caged "The second princess-cell, the Candlishes', is closed in a cage of thin wax rods like a lantern.".
    State killed "The second princess-cell, the Candlishes', has a small neat hole in its side.".
    State open "The second princess-cell, the Candlishes', hangs open at the bottom, empty.".
  }
  Thing cell_ashdown "the Ashdown princess-cell" at royal_gallery {
    State sealed "The third princess-cell, the Ashdowns', is the smallest, and hangs a little crooked.".
    State caged "The third princess-cell, the Ashdowns', is closed in a cage of thin wax rods like a lantern.".
    State killed "The third princess-cell, the Ashdowns', has a small neat hole in its side.".
    State open "The third princess-cell, the Ashdowns', hangs open at the bottom, empty.".
  }
  Initially Assert royalCell(cell_candlish). Initially Assert royalCell(cell_ashdown).
  Observe spoon_seen at royal_gallery when night() and not leavingBegun() and at(party, royal_gallery) and not knows(party, breck_spoon) "In the dark of the royal gallery, a tall figure in black is standing on a stool under the first cell, with a pot in one hand and a long spoon in the other, feeding something through a hole in the wax. The other two watchers are asleep on their stools. The figure sees you, and goes very still, and then gets down, and goes out without a word." teaches breck_spoon.

  Topic brenna_cells with brenna "Ask Dame Brenna about the princess-cells" when not leavingBegun() once {
    Says "'Three. One will reign.' She looks up at her cell. 'Every princess-cell has its household. It is the greatest honour the Comb gives: to watch a cell. And when your princess wakes first, your household is the Mother's household, for her whole life. Thirty years.' A pause. 'The Brecks have watched a cell at every Leaving for a hundred years. Ours has never woken first.' Another pause. 'My mother watched. She sat on this stool for nine days and nights, and her princess was stung in the cell, and she went home and died that winter. People said it was the cold.'".
  }
  Topic brenna_spoon with brenna "Tell Dame Brenna you know about the spoon" when knows(actor, breck_spoon) and not brennaShamed(brenna) and not leavingBegun() once {
    Says "She does not move. For a while you think she will not answer. Then she says, without looking at you, 'Royal jelly. From our own hives. My own princess, my own jelly, my own spoon.' Her hands are perfectly still in her lap. 'A queen that is fed more wakes sooner and stronger. Every keeper knows it. Nobody does it, because it is not done.' She looks at you at last. 'A hundred years of being the household that loses. Of being looked at, at the Calling, with that particular kindness. I am seventy-three. I wanted, once, to be looked at another way.' She turns back to her cell. 'Tell whom you like.'".
    On discuss { Assert brennaShamed(brenna). }
  }
  Topic eben_cages with eben "Ask Eben to make queen-cages for the other two princess-cells" when knows(actor, cages_known) and not leavingBegun() and not holding(actor, queen_cage) once {
    Says "'Cages.' He looks at you sharply. 'Garnock's trick.' Then, slowly: 'The Candlish cell is my family's. My father's sat under it nine days.' He picks up a handful of thin wax rods from the bench. 'They'd say it was against nature. Two queens, two Leavings.' He starts bending the rods. 'They said the Stair was against nature.' In half an hour he gives you two little lanterns of wax. 'The keeper has to allow it,' he says. 'Or it's just two cages.'".
    On discuss { Give cage_one to actor. Give cage_two to actor. }
  }
  Topic pim_spoon with pim "Tell Pim that Dame Brenna has been feeding her princess at night" when knows(actor, breck_spoon) and not pimConsents(pim) and not goes(pim) once {
    Says "Pim's mouth falls open. 'With a spoon?' He looks as if you had told him somebody had been cheating at a funeral. 'Then it's not the Mother's choosing at all. It's Dame Brenna's.' He goes red, and then white, and then he stands up very straight, and for a moment he looks like a keeper. 'If you've cages, cage the other two. I'll answer for it. Old Garnock did it once. Tell them the keeper said.' His voice cracks on keeper.".
    On discuss { Assert pimConsents(pim). }
  }
  Topic linnet_spoon with linnet "Tell Linnet that Dame Brenna has been feeding her princess at night" when knows(actor, breck_spoon) and not pimConsents(pim) and not goes(linnet) once {
    Says "Linnet closes her eyes. 'Brenna,' she says. 'Of course.' When she opens them she is a keeper. 'Cage the others, if you've cages. The Mother's choosing should be the Mother's. I'll answer to the Comb.'".
    On discuss { Assert pimConsents(pim). }
  }
  Item cage_one "a queen-cage of wax rods" is queen_cage at limbo. Item cage_two "a queen-cage of wax rods" is queen_cage at limbo.
  Action cage_cell(actor: group, cell: entity, site: place) "Close a queen-cage round {cell}" {
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, royal_gallery) and royalCell(cell) and state(cell, sealed) and holding(actor, queen_cage) and pimConsents(pim) and not emerged(cell_breck).
    Time 1.
    On success { Spend queen_cage from actor. Assert state(cell, caged). }
    Result "You lift the little lantern of rods up round the cell, and close it, and the watcher on the stool beneath stands up and watches you do it and does not stop you. 'The keeper said,' says the watcher under it, to the room, to Dame Brenna, who says nothing.".
  }
  Action pierce_breck(actor: group, site: place) "Pierce the Breck princess-cell with a blade before she wakes" {
    Grave "The princess in it will die in the wax, the Brecks' hundred years of hoping with her.".
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, royal_gallery) and state(cell_breck, sealed) and not emerged(cell_breck).
    Time 1 minute.
    On success { Assert state(cell_breck, pierced). Assert breckPierced(brenna). }
    Result "The wax is thicker than you thought, and then it gives. Something inside moves once, hard, against the blade, and then not. Dame Brenna Breck makes no sound at all. She gets down off her stool, and puts her hand flat on the cell, and stands there with her eyes shut, and does not move again while you are in the room.".
  }

  // The night: at eleven the first wakes; at two she goes to the others.
  Rule daughter_wakes when leftNight() and hour(clock) >= 23 and not emerged(cell_breck) and not emerged(cell_candlish) {
    Assert emerged(cell_breck). }
  Rule breck_wakes when emerged(cell_breck) and state(cell_breck, sealed) { Assert state(cell_breck, open). }
  Rule candlish_first when emerged(cell_breck) and breckPierced(brenna) and not emerged(cell_candlish) and state(cell_candlish, sealed) { Assert emerged(cell_candlish). Assert state(cell_candlish, open). }
  Observe piping at royal_gallery as sound when leftNight() and emerged(cell_breck) and hour(clock) >= 23 "From the royal gallery a sound you have never heard: a thin high piping, like a tin whistle blown through a comb, toot, toot, toot-toot-toot, the new queen, out, calling. And from inside the other cells, muffled through the wax, the answers: quack, quack, quack, deeper, frightened, still shut in.".
  Rule daughters_told at royal_gallery when emerged(cell_breck) and leftNight() and within(party, comb) and not spread(daughters_told) says "All over the half-empty Comb people wake and sit up in the dark and listen to the piping, and nobody goes back to sleep." { Assert spread(daughters_told). }
  Entity daughters_told: fact "the piping".
  Relation stayedForDaughters(group).
  Rule saw_daughters when at(party, royal_gallery) and emerged(cell_breck) and leftNight() and not stayedForDaughters(party) { Assert stayedForDaughters(party). }
  Relation daughtersDone(group).
  Rule daughters_resolve when emerged(cell_breck) and hour(clock) >= 2 and hour(clock) < 6 and not daughtersDone(brenna) {
    Assert daughtersDone(brenna). }
  Rule candlish_stung when daughtersDone(brenna) and state(cell_candlish, sealed) and not breckPierced(brenna) { Assert state(cell_candlish, killed). }
  Rule ashdown_stung when daughtersDone(brenna) and state(cell_ashdown, sealed) { Assert state(cell_ashdown, killed). }
  Rule cast_coming when daughtersDone(brenna) and (state(cell_candlish, caged) or state(cell_ashdown, caged)) and not castTomorrow(brenna) { Assert castTomorrow(brenna). }
  Rule stinging_caged at royal_gallery when daughtersDone(brenna) and at(party, royal_gallery) and state(cell_candlish, caged) and state(cell_ashdown, caged) and not spread(stinging_seen) says "At two the new queen comes along the ceiling of the royal gallery: long, gold, new, quick as a cat. She goes to each cell in turn, and at each she walks round and round the cage, piping, frantic, and cannot get in; and inside, the quacking goes on, frightened and alive. Abel Candlish and Wenn Ashdown sit under their cages with their hands clenched in their laps and do not look at Dame Brenna, and Dame Brenna does not look at them." { Assert spread(stinging_seen). }
  Rule stinging_seen at royal_gallery when daughtersDone(brenna) and at(party, royal_gallery) and not spread(stinging_seen) says "At two the new queen comes along the ceiling of the royal gallery: long, gold, new, quick as a cat. She goes to each cell in turn. Where a cell is caged she walks round and round the cage, piping, frantic, and cannot get in. Where it is not, she clings to the wax and curls her body under her, and the quacking from inside stops. Under the Candlish cell old Abel Candlish puts his face in his hands; under the Ashdown cell Wenn Ashdown stands up, and sits down again, and stands up." { Assert spread(stinging_seen). }
  Entity stinging_seen: fact "the stinging".
  Rule cast_goes when castTomorrow(brenna) and hour(clock) >= 12 and not castWent(brenna) and daughtersDone(brenna) {
    Assert castWent(brenna). }
  Rule cast_seen when castWent(brenna) and within(party, hume_brow) and not spread(cast_seen) says "At noon the hum goes up again, thinner, and out of the Comb pours a second, smaller swarm, a cast, behind the princess who was caged; and after it, with bundles hastily tied, the watchers of her cell and their families and forty others who stayed yesterday and have changed their minds, walking out over the Wold after it, south, toward somewhere nobody has danced for." { Assert spread(cast_seen). }
  Entity cast_seen: fact "the cast".
  // Pim, or Linnet, names whoever kept the night with the Daughters.
  Rule named_at_brow when stayedForDaughters(party) and daughtersDone(brenna) and at(party, royal_gallery) and not named(party) says "In the grey of the morning the keeper who stayed comes along the gallery with the jar, and stops in front of you, and dips two fingers in it, and draws them down your forehead, your throat, your wrists, behind your ears, saying the words. 'You stayed with us,' is all that is said. 'Half of us went. You stayed.'" { Assert named(party). }
}

data/adventures/half-the-hive/dell.kyr:
Module hume "Half the Hive" {
  // ── The Chalk Dell and the brocks ─────────────────────────────────────────────────────────────────────────────────
  // Two brock sows, honey badgers as big as ponies, live in the cave at the back of the Dell, and have since before the
  // Brow. The Searchers of the sixth Leaving left a message for whoever came after, in dance-marks on the chalk: at the
  // turn of the year, the dead year's comb at the cave mouth, and the brocks keep the peace. Nobody has read it in sixty
  // years, because nobody has looked. The brocks can be killed (very dangerous), driven in by fire (they come back), or
  // given the old gift.
  Species brock_kind "a brock" like owlbear temperament territorial described "A honey badger the size of a pony: low, broad, grey-backed and black-bellied, with a short thick tail and front claws as long as sickles, and a smell of musk you can taste. Its skin hangs loose on it, so that when you seize it, it turns round inside its own hide and bites you.".
  Person brocks "the brocks" at sett_mouth {
    Role "two brock sows, honey badgers as big as ponies, grey-backed, lying in the cave mouth" when at(brocks, sett_mouth).
    Role "two brock sows, honey badgers as big as ponies, loose in the dark among the sleepers" when not at(brocks, sett_mouth).
    Species brock_kind. Level 2. Numbers 2.
    Lair sett_mouth. Refuge limbo.
    Fears flame.
    Warns "In the dark of the cave mouth something grey heaves up, and then another: two shapes, low and very broad, as big as ponies, with flat striped heads that swing toward you. One of them clacks its teeth, a sound like a shut book. They do not come. They wait, and the smell of musk rolls out of the cave at you so thick you could lean on it. A fire would send them back into the dark.".
    Comes "The brocks come out of the cave low and fast, like grey water, and the first one hits you at the knee.".
    Flinches "The brocks back into the dark of the cave from the fire, hissing, and are gone, though you can hear them in there, waiting.".
    Pleads "The last brock, bloody, turns and drags herself back into the dark of the cave, and does not come out again.".
  }
  Relation brockTruce(group). Relation brocksKilled(group).
  Query brocksSafe() means brockTruce(brocks) or brocksKilled(brocks).
  Rule brocks_slain when not able(brocks) and not brocksKilled(brocks) { Assert brocksKilled(brocks). }
  // The marks on the chalk.
  Thing chalk_marks "the marks on the chalk" at dell_floor {
    State scored "Low on the white wall of the Dell, at the height of a hand, are scored marks: lines and loops and figure-eights, old, weathered, the edges gone soft.".
  }
  Observe marks_read at dell_floor when tried(chalk_marks, looking) and danceLearned(party) and not knows(party, brock_truce) "Looked at with the eye Kestrel gave you, the marks are not decoration. They are dances, scored where a dancer would run them, and you can read them, slowly, like a child spelling: a short run toward the cave. A loop. A run that turns round on itself, the sign for the end of the year. A run back from the cave, waggling hard: good, good, very good. And at the end, a sign you have seen on the wall of the Dancing Hall a thousand times: the mark of the Searchers. At the turning of the year, the old comb at the cave. Then all is well." teaches brock_truce.
  Observe marks_unread at dell_floor when tried(chalk_marks, looking) and not danceLearned(party) "They look like the marks on the walls of the Dancing Hall: lines and loops. Someone who knew the dance might read them.".
  Discovery brock_truce "Dance-marks on the chalk of the Dell, left by the Searchers of an old Leaving, say: at the turning of the year, leave the old comb at the cave, and the brocks keep the peace.".
  Action brock_gift(actor: group, site: place) "Leave the old black comb at the cave mouth, as the marks say" {
    Description "The old gift, sixty years late.".
    Requires at(actor, site) and able(actor) and company(actor) and (at(actor, dell_floor) or at(actor, sett_mouth)) and holding(actor, old_comb) and knows(actor, brock_truce) and able(brocks) and not brockTruce(brocks).
    Time 2.
    On success { Spend old_comb from actor. Assert brockTruce(brocks). Assert tolerates(brocks, actor). Retract assails(brocks, actor). Retract warned(brocks, actor). }
    Result "You walk to the cave mouth with the black comb held out in front of you in both hands, which is the stupidest thing you have ever done, and put it down on the bare earth there, and back away. Nothing. A fly walks along the chalk. Then a broad striped head comes out of the dark, and sniffs, and sniffs again, and a paw as big as a spade drags the comb inside. You hear it being eaten: a long, contented, crunching sound. The second brock comes out and lies down in the cave mouth in the sun, and yawns, showing you everything, and looks at you with its small black eyes as if you were weather.".
  }
  Rule sisters_for_dell when brocksSafe() and not sistersDell(chalk_dell) and not committed() and not leavingBegun() { Assert sistersDell(chalk_dell). Increase tally(chalk_dell) by 1. }
  Rule dell_word at dancing_hall when sistersDell(chalk_dell) and not spread(dell_word) says "On the upper slope of the Dancing Hall a Sister you have not seen before is dancing south-east, short and hard, over and over: the Dell. The bees' own scouts have been to look, now that nothing in it will eat them." { Assert spread(dell_word). }
  Entity dell_word: fact "the Sisters for the Dell".
  Observe dell_peace at sett_mouth when brockTruce(brocks) "The brocks lie in the cave mouth in the sun with their chins on their paws, and watch you, and do not get up.".
  Observe dell_empty at sett_mouth when brocksKilled(brocks) "The cave mouth is empty and smells of blood and musk. Flies.".
}

data/adventures/half-the-hive/endings.ky:
Module hume "Half the Hive" {
  // ── The account ───────────────────────────────────────────────────────────────────────────────────────────────────
  // At eight on the evening of the Turning-out, to a company anywhere in the Wold (or when it next comes into it): each
  // strand's morning after, plainly; then one ending, by where the Mother went. The world goes on after.
  Query accounting() means flightDay() and (hour(clock) >= 20 or day(clock) >= leftDay(hume_wold) + 3).

  // You.
  Rule fate_forced within hume_wold when accounting() and forcedSwarm(party) and not spread(fate_you) says "You chose for the bees. The Searchers know it; the Sisters do not, and never will. Kestrel Dunn has not said your name since, and will not, either to curse it or to thank you." { Assert spread(fate_you). }
  Rule fate_hannet_broken within hume_wold when accounting() and failedHannet(party) and not spread(fate_you) says "Hannet Coke is sitting on the slope of the empty Dancing Hall where the marks of this week's dances are newest, with two wax bees on a cord round her neck. She does not blame you. She says so, to anyone who asks, which is worse." { Assert spread(fate_you). }
  Rule fate_named within hume_wold when accounting() and named(party) and not spread(fate_you) says "You are of the Comb now. The scent will not come off: you will smell, a little, of the Mother for the rest of your life, in the lowland, in the rain, in your grave; and any Sister anywhere in the Wold will turn her head toward you, and away, as if you were family." { Assert spread(fate_you). }
  Entity fate_you: fact "you".
  // The lovers, and the Stair.
  Rule fate_lovers_gone within hume_wold when accounting() and goes(linnet) and goes(eben) and stairLit(eben) and not spread(fate_lovers) says "Linnet Amory keeps the old Mother in the new comb, and Eben Candlish is carving the doorframe of the first cell, and at midsummer, in the Brow they left, the sun comes down the Lantern Stair from the Crown to the Brood like water down a drain, and people come from Sallowcomb and Ketter to stand at the foot of it." { Assert spread(fate_lovers). }
  Rule fate_lovers_gone_short within hume_wold when accounting() and goes(linnet) and goes(eben) and not spread(fate_lovers) says "Linnet Amory keeps the old Mother in the new comb, and Eben Candlish is carving the doorframe of the first cell. In the Brow, the Lantern Stair goes up three turns and stops at nothing, and the children of the Waxwrights dare each other to climb to the last step and stand on it." { Assert spread(fate_lovers). }
  Rule fate_lovers_home within hume_wold when accounting() and not goes(linnet) and not goes(eben) and not spread(fate_lovers) says "Linnet Amory and Eben Candlish stayed, both of them, and are to be married at the Feast of the Lime, and Eben is finishing the Stair, slowly, now there is no hurry; and somewhere across the Wold a boy of seventeen is keeping the old Mother in a new comb, and writing back every week to ask how to do it." { Assert spread(fate_lovers). }
  Rule fate_lovers_crossed within hume_wold when accounting() and goes(eben) and not goes(linnet) and not spread(fate_lovers) says "Eben Candlish walked out after the bees without a word to anyone, and is in the new comb, carving nothing; and Linnet Amory, who stayed for him so that he could finish the Stair, keeps the Daughters in the Brow, and goes every evening to the Waxwrights' gallery and stands at the foot of the Lantern Stair, three turns up and stopping at nothing, and nobody has had the heart yet to tell her he meant to do the same for her." { Assert spread(fate_lovers). }
  Entity fate_lovers: fact "the lovers".
  // Hannet.
  Rule fate_hannet_carried within hume_wold when accounting() and goes(hannet) and not left(gallowtree) and not spread(fate_hannet) says "Hannet Coke went with the Mother at last, carried, complaining the whole way, and sits now in the sun at the mouth of the new comb on a stool somebody made her, telling the children how it was done in the old Brow, mostly wrongly, with two wax bees on a cord round her neck." { Assert spread(fate_hannet). }
  Rule fate_hannet_tree within hume_wold when accounting() and goes(hannet) and left(gallowtree) and not spread(fate_hannet) says "Hannet Coke went with the Mother at last, two hours, on her own legs, to the Gallowtree, and sits on the knoll in the sun, happy, and does not know whose tree it is." { Assert spread(fate_hannet). }
  Rule fate_hannet_home within hume_wold when accounting() and not goes(hannet) and not failedHannet(party) and not spread(fate_hannet) says "Hannet Coke stayed, for the seventh time. She sits on the slope of the empty Dancing Hall in the afternoons and runs, very short, very slow, the line of a dance for somewhere, to nobody." { Assert spread(fate_hannet). }
  Entity fate_hannet: fact "Hannet".
  // Agnes, Tobit, and the thing in the dark.
  Rule fate_agnes_carried within hume_wold when accounting() and goes(agnes) and linnetPermitsDead(linnet) and not spread(fate_agnes) says "Agnes Mellor carried her husband out of the Brow on a litter, capped, by leave of the keeper, the first of the dead ever to go with a Leaving; and he stands now in the first wall of the new comb, alone in it, with a view." { Assert spread(fate_agnes). }
  Rule fate_agnes_likeness within hume_wold when accounting() and goes(agnes) and likenessGiven(agnes) and not spread(fate_agnes) says "Agnes Mellor went with the Mother with a little wax Tobit wrapped in her shawl, his head on one side the way he stood when he was waiting for her to stop talking; and she stops talking, sometimes, now, and waits." { Assert spread(fate_agnes). }
  Rule fate_agnes_freed within hume_wold when accounting() and goes(agnes) and not spread(fate_agnes) says "Agnes Mellor went with the Mother, and left Tobit capped in the Gallery with the others, safe, and has a view." { Assert spread(fate_agnes). }
  Rule fate_agnes_stays within hume_wold when accounting() and not goes(agnes) and not spread(fate_agnes) says "Agnes Mellor stayed. She sits in the Capped Gallery every night in the dark with Tobit, on her stool, talking about the goat." { Assert spread(fate_agnes). }
  Entity fate_agnes: fact "Agnes".
  Rule fate_moth_dead within hume_wold when accounting() and mothDead(deathshead) and not spread(fate_moth) says "Nothing comes into the Capped Gallery in the small hours now." { Assert spread(fate_moth). }
  Rule fate_moth_alive within hume_wold when accounting() and not mothDead(deathshead) and not spread(fate_moth) says "Something still comes into the Capped Gallery in the small hours, soft and dry, smelling of the Mother, and drinks from the seals of the dead; and the children of the Brow have a name for it, and a rhyme, and will not go up the honey stair after dark." { Assert spread(fate_moth). }
  Entity fate_moth: fact "the Gallery".
  // Nell, and the squire.
  Rule fate_nell_named within hume_wold when accounting() and nellNamed(nell) and not spread(fate_nell) says "Nell Quarrie goes up the stair in the afternoons now, in daylight, scented by Elspet Garnock's own hand, and sits with Aldo, fourth row on the left, with the light coming down the arch; and has shut her shop, because she finds she has no more use for the oil." { Assert spread(fate_nell). }
  Rule fate_nell_barred within hume_wold when accounting() and nellBarred(nell) and not spread(fate_nell) says "Nell Quarrie's shop in Smoke End has a mark on the door that the Comb reads, and she does not go up the gorge, and in the evenings she stands at the foot of the path with her eyes shut, smelling." { Assert spread(fate_nell). }
  Rule fate_nell_none within hume_wold when accounting() and not spread(fate_nell) says "Once a month Nell Quarrie goes up the stair in the dark smelling of her own oil, and sits an hour with Aldo, and comes down, and nobody notices." { Assert spread(fate_nell). }
  Entity fate_nell: fact "Nell".
  Rule fate_corve_gift within hume_wold when accounting() and corveGives(corve) and not spread(fate_corve) says "Squire Lucian Corve of Larkhill is of the Comb, named by the keeper's own hand, and goes up the stair in the Brow every week with his drawing-board, and has redrawn the Mother twice, and is still getting her wrong, and does not mind." { Assert spread(fate_corve). }
  Rule fate_corve_robbed within hume_wold when accounting() and flaskGone(corve) and not flaskAt(larkhill) and not corveGives(corve) and not spread(fate_corve) says "Squire Corve's oak case is empty, and he has not said a word to anyone about it, because he cannot. He writes to the keeper this spring as every spring, and asks, as every spring, to be named; and does not mention the flask; and nor does the keeper." { Assert spread(fate_corve). }
  Rule fate_corve_none within hume_wold when accounting() and not left(larkhill) and not spread(fate_corve) says "At Larkhill the squire's tower stands empty and dry and pointed, with an empty green flask in a crack at the top of it; and the squire sits in his study among twelve years of drawings and does not draw." { Assert spread(fate_corve). }
  Entity fate_corve: fact "Corve".
  // Moss, the Daughters, Ivo, the mead, the Drewes.
  Rule fate_moss_hurt within hume_wold when accounting() and mossHurt(moss) and not spread(fate_moss) says "Moss Ashdown can walk again, with a stick. The Leaving went without him." { Assert spread(fate_moss). }
  Rule fate_moss_brocks within hume_wold when accounting() and brocksKilled(brocks) and not mossHurt(moss) and not spread(fate_moss) says "Moss Ashdown has two brock claws on a thong round his neck and a song in every comb in the Wold, and does not sing it, and does not wear the claws when Kestrel is near." { Assert spread(fate_moss). }
  Entity fate_moss: fact "Moss".
  Rule fate_daughters_pierced within hume_wold when accounting() and breckPierced(brenna) and not spread(fate_daughters) says "The Candlish princess reigns in the Brow, and the Candlishes are the Mother's household for thirty years, and do not know what to do with it. Dame Brenna Breck has not left her cell in the Brood since the night, and her grandson Tibby brings her meals, with his drone, and she eats them." { Assert spread(fate_daughters). }
  Rule fate_daughters_cast within hume_wold when accounting() and castWent(brenna) and not spread(fate_daughters) says "The Breck princess reigns in the Brow; and the princess who was caged went out with a cast the next noon, south, with forty people behind her, toward somewhere nobody danced for; and no word has come back yet. The Comb has never had two Leavings in one summer. Some say it is against nature. Some say Garnock would have been proud." { Assert spread(fate_daughters). }
  Rule fate_daughters_shamed within hume_wold when accounting() and brennaShamed(brenna) and not spread(fate_daughters) says "The Breck princess woke first, as she was always going to, fed with a spoon, and stung her sisters in their cells, and reigns; and Dame Brenna Breck is the Mother's household for thirty years, and walks through the Brood upright in black with a silver bee at her throat, and finds that she is looked at, now, in another way, and that it is not the way she wanted." { Assert spread(fate_daughters). }
  Rule fate_daughters_none within hume_wold when accounting() and not spread(fate_daughters) says "The Breck princess woke first and stung her sisters in their cells, and reigns, and the Brecks are the Mother's household at last after a hundred years, and everyone says what a strong queen she is, and how lucky." { Assert spread(fate_daughters). }
  Entity fate_daughters: fact "the Daughters".
  Rule fate_ivo_founder within hume_wold when accounting() and goes(ivo) and not spread(fate_ivo) says "Ivo Gildersleeve is a Searcher of the new comb, in a yellow coat gone brown with walking, and has been out every day since they came, finding things: water, wild comb, a quicker way, a better view. Kestrel Dunn has told him twice to stop showing off, and once, when she thought nobody could hear, that he was the best she ever trained, which is untrue, because she never trained him." { Assert spread(fate_ivo). }
  Rule fate_ivo_with within hume_wold when accounting() and travelsWith(ivo, party) and not spread(fate_ivo) says "Ivo Gildersleeve is with you, in a yellow coat gone brown with walking, and knows the way." { Assert spread(fate_ivo). }
  Rule fate_ivo_out within hume_wold when accounting() and ivoTurnedOut(ivo) and not spread(fate_ivo) says "Ivo Gildersleeve was turned out with the Escort, with a cloak and a loaf, and is sitting on a milestone at the edge of the Wold looking down the drove road at the lowland, which he has never seen, deciding." { Assert spread(fate_ivo). }
  Rule fate_ivo_kept within hume_wold when accounting() and ivoSearcher(ivo) and not spread(fate_ivo) says "Ivo Gildersleeve was not turned out. He is a Searcher of the Brow, the first of the Escort ever to be one, and the Escort do not know whether to be proud of him." { Assert spread(fate_ivo). }
  Entity fate_ivo: fact "Ivo".
  Rule fate_mead within hume_wold when accounting() and meadSaved(huw) and not spread(fate_mead) says "A cask of Huw Penry's last mead is laid down in the honey vaults of the Brow to be broached at every Calling for thirty years, chalked PENRY · THE YEAR HE WENT, and Martin Sayle in Smoke End says it is the second-best mead in the Wold, and will not say which is the first." { Assert spread(fate_mead). }
  Entity fate_mead: fact "the mead".
  Rule fate_drewes within hume_wold when accounting() and drewesPaid(party) and not spread(fate_drewes) says "The Drewes bought a goat with what you paid them, at the last farm before the moor, and walked it all the way, and it is the only goat in the new comb, and the younger girl has named it after you." { Assert spread(fate_drewes). }
  Entity fate_drewes: fact "the Drewes".

  // ── Endings ───────────────────────────────────────────────────────────────────────────────────────────────────────
  Query told() means spread(fate_daughters) and spread(fate_ivo) and spread(fate_nell).
  Ending far_free "Under the Far Brow" when accounting() and told() and left(far_brow) and kestrelTurned(kestrel) "Under the Far Brow the new comb hangs a yard long already, white going gold, and the old came by the shepherds' drove and are there to see it. It is the best place in the Wold, as Kestrel always said; and this time everyone could walk it. There are child-handprints at the back in the old wax, and new ones beside them now, and one that a grown man says is his from when he was nine, and nobody knows whose the oldest are, or why the first comb here was ever left. Half the hive went. Half stayed. Both halves are alive.".
  Ending far_hard "The Long Way" when accounting() and told() and left(far_brow) "Under the Far Brow the new comb hangs a yard long, white going gold, in the best place in the Wold, as Kestrel always said. The young are there, and the strong. The old stayed home, mostly, knowing they could not walk it, and some who tried did not come in, and the Leaving goes on without them. Kestrel Dunn was right about the place. She was wrong about who could walk it. She knows.".
  Ending dell_peace "The Brocks' Peace" when accounting() and told() and left(chalk_dell) and brockTruce(brocks) "In the Chalk Dell the new comb fills the cave in the chalk, and the brocks sleep in a smaller hole at the back and are given the old comb at the turn of the year, as the marks say, and keep the peace. Moss Ashdown is cutting new marks under the old ones, for whoever comes next, so that this time somebody reads them.".
  Ending dell_blood "The Dell" when accounting() and told() and left(chalk_dell) and brocksKilled(brocks) "In the Chalk Dell the new comb fills the cave where the brocks lived, and it is dry and warm and faces south and is the best-sheltered comb in the Wold; and at the back of the Dell the chalk is stained, and the children are told not to go there, and do.".
  Ending dell_raided "The Brocks' Cave" when accounting() and told() and left(chalk_dell) "The brocks came back for their cave the first night, and every night after. The Leaving holds the Dell, just; the comb is in the cave and the brocks are in the dark at the back of the Dell, and every night the Searchers sit up with torches, and every morning someone counts. It is a good place. It is going to cost.".
  Ending lark_gift "The Gift at Larkhill" when accounting() and told() and left(larkhill) and corveGives(corve) "The chantry tower at Larkhill hums like a struck bell from dawn to dusk, and belongs to nobody, by a deed of gift in a neat hand that the Wold has framed. The lowland markets are a morning's walk away. The squire comes up from the farmhouse every evening and sits in the yard with his drawing-board, scented, and the Sisters walk across his paper.".
  Ending lark_owned "The Squire's Bees" when accounting() and told() and left(larkhill) "The Leaving lives in the chantry tower at Larkhill, safe and dry and a morning from market; and the bees, and the comb, and the honey, are the property of L. Corve, Esquire, by the law of the lowland, which the Humefolk have never had to know before and are learning. He has not taken a single pot. He has not been in among them. He cannot bring himself to, and they cannot bring themselves to ask him.".
  Ending gallow "The Eighth Leaving" when accounting() and told() and left(gallowtree) "In the Gallowtree the new comb grows white over the grey, up the inside of the old tree, over the faces of the seventh Leaving, whom the eighth have decided not to speak about. The tree is green and loud with bees. It is wet at the heart. It will be a long winter, and when the Searchers of the Brow walk out to the knoll at the thaw to see how the eighth Leaving did, they will find out, as the Brow has always said of the seventh, whether they went on east.".
  Ending bivouac "In the Open" when accounting() and told() and left(high_wold) "The swarm hangs on the honey linden in the open air, building white comb in the wind and the sun, and the Leaving camps under it, and waits for the bees to change their minds, which bees do not. It is a fine summer. Nobody talks about the winter.".
}

data/adventures/half-the-hive/gallow.kyr:
Module hume "Half the Hive" {
  // ── The Gallowtree: the seventh Leaving ───────────────────────────────────────────────────────────────────────────
  // Eighty-one years ago the seventh Leaving went to the Gallowtree, close, vast, sheltered; and the tree's heart was
  // rotten and wet, and the comb sagged in the first winter, and the honey soured, and they died, one by one, and were
  // capped by the ones still living, until the last, the Capper's girl, Merrit Coke, capped the last but herself and sat
  // down by the door. The Brow says they went on east. The white comb they drew first is still up in the dry top of the
  // hollow, never brooded, the last white comb in the Wold.
  Thing seventh "the capped of the seventh Leaving" at gallow_hollow {
    State kept "In the grey comb of the walls, upright, capped in wax gone the colour of old bone: men, women, a few children, in clothes eighty years out of fashion, eyes shut. Some have their hands folded. Some do not. One woman holds a baby.".
  }
  Observe seventh_seen at gallow_hollow when tried(seventh, looking) and not knows(party, lost_leaving) "You go round the walls slowly. Forty-one of them. The capping gets worse as you go: the first are smooth and clear and careful, the work of a Capper with time; then rougher; then thin, hurried, cracked, as if done by someone who was cold, or ill, or alone. The last few are hardly capped at all." teaches lost_leaving.
  Discovery lost_leaving "Inside the Gallowtree are the seventh Leaving, eighty-one years dead: forty-one people capped in the comb by each other, more roughly as they went, as if they died one by one through a winter. The Brow says they went on east.".
  Thing merrit "the one by the door" at gallow_hollow {
    State sitting "By the door, on the floor, against the wall, sits the one who capped the others: uncapped, because there was nobody left to do it. Bones in a brown Capper's apron, a sealing-iron by one hand. In the lap, something small.".
  }
  Observe merrit_seen at gallow_hollow when tried(merrit, looking) and not knows(party, merrit_found) "In the lap of the bones, where the hands were, is a little bee carved in wax, no bigger than a thumb, very carefully done, every leg; and cut into the iron by the hand, small and square: M. COKE." teaches merrit_found.
  Discovery merrit_found "The last of the seventh Leaving, the one who capped the others and was never capped, was M. Coke: a Capper's girl, with a little wax bee in her lap.".
  Action take_wax_bee(actor: group, site: place) "Take the little wax bee from the lap of the one by the door" {
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, gallow_hollow) and knows(actor, merrit_found) and not tookBee(actor).
    Time 1 minute.
    On success { Give merrit_bee to actor. Assert tookBee(actor). }
    Result "The bones do not hold it. It comes away into your hand, warm from the green light, lighter than it looks.".
  }
  Relation tookBee(group).
  Item merrit_bee "a little bee carved in wax" is wax_bee at limbo.
  Topic hannet_bee_dancing with hannet "Give Hannet the little wax bee from the Gallowtree" when holding(actor, wax_bee) and not hannetHasBee(hannet) and dancesFor(hannet, gallowtree) once {
    Says "Hannet takes it in her palm and closes her fingers over it. Then she reaches inside her collar and pulls out a cord, and on the cord, worn smooth and dark with seventy years of being held, is another bee, its twin, every leg. She holds them side by side. 'Merrit,' she says. 'My aunt Merrit. She went with the seventh. She gave me this one when I was four and said she'd send the other when they'd built, and that would be the sign.' She leans toward you out of her chair. 'Where was it?' You tell her: the tree, the grey comb, the people standing in it; the one by the door, uncapped, who capped all the others and had nobody to do it for her. Hannet closes her hand on both bees. 'Well,' she says. 'She sent it.' After a while she gets up, very slowly, with her stick, and goes and sits by the wall, and does not dance any more.".
    On discuss { Spend wax_bee from actor. Assert hannetHasBee(hannet). Assert knows(actor, lost_leaving). Assert hannetStopped(hannet). Retract dancesFor(hannet, gallowtree). Decrease tally(gallowtree) by 1. Assert knows(actor, merrit_aunt). }
  }
  Topic hannet_bee with hannet "Give Hannet the little wax bee from the Gallowtree" when holding(actor, wax_bee) and not hannetHasBee(hannet) and not dancesFor(hannet, gallowtree) once {
    Says "Hannet takes it in her palm and closes her fingers over it. Then she reaches inside her collar and pulls out a cord, and on the cord, worn smooth and dark with seventy years of being held, is another bee, its twin, every leg. She holds them side by side. 'She said she'd send for me,' Hannet says. 'When they'd built. She said she'd send this one, and that would be the sign.' She closes her hand on both of them. 'Well,' she says. 'She sent it.'".
    On discuss { Spend wax_bee from actor. Assert hannetHasBee(hannet). Assert knows(actor, lost_leaving). }
  }
  Relation hannetHasBee(group).
  // Its heart.
  Thing gallow_heart "the heart of the Gallowtree" at gallow_hollow {
    State standing "At the back of the hollow the inner wood of the tree goes up into the dark, ridged and grey, wet-looking.".
  }
  Observe heart_prodded at gallow_hollow when (tried(gallow_heart, prodding) or tried(gallow_heart, prying) or tried(gallow_heart, pushing)) and not knows(party, gallow_rotten) "The wood gives. It is soft as cake under a crust, and wet; a lump of it comes away, black inside, crawling with white grubs, and from somewhere up in the dark there is a slow drip of water, and the whole great trunk round you seems to sigh." teaches gallow_rotten.
  Observe heart_heard at gallow_hollow when tried(gallow_heart, listening) and not knows(party, gallow_rotten) "With your ear to the wood you hear water: a slow drip, deep inside, and the tick of something eating. The tree is green outside and wet and rotten in." teaches gallow_rotten.
  Discovery gallow_rotten "The Gallowtree is green outside and wet and rotten at its heart: comb built in it would sag and sour in a winter.".
  // The white comb, high in the dry top.
  Thing white_comb "the white comb high in the hollow" at gallow_hollow {
    State whole "High up in the hollow, above the capped, where the dry top of the trunk catches the light, a few sheets of comb hang that are not grey but white, white as milk: the first comb the seventh Leaving's bees drew, before anything was born in it.".
    State cut "High in the hollow, where the white comb hung, a clean pale scar.".
  }
  Hazard comb_fall "a fall in the hollow of the Gallowtree" means "Deal (2d4) physical damage to ally unless dexterity save against (11).".
  Action cut_white(actor: group, site: place) "Climb the old comb of the hollow and cut a slab of the white" {
    Description "Up the grey comb, past the faces, to the white.".
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, gallow_hollow) and state(white_comb, whole).
    Time 3.
    Resolve check(actor, climbing, dc_fair).
    On success { Assert state(white_comb, cut). }
    On failure { Assert strikes(comb_fall, actor). }
    Result "You go up the old grey comb with your knife in your teeth, careful where you put your hands and feet, because the hands and feet are not all wax; and the white comb comes away under your knife in one sheet, light as paper.".
    Otherwise "Halfway up, the grey comb crumbles under your foot like stale bread, and you come down among the capped, hard.".
  }
  Rule white_cut when state(white_comb, cut) and not whiteTaken(party) { Assert whiteTaken(party). Give white_slab to party. }
  Relation whiteTaken(group).
  Item white_slab "a slab of white comb" is white_wax at limbo.
  Initially Assert suits(gallow_heart, listening). Initially Assert suits(gallow_heart, pushing). Initially Assert suits(gallow_heart, prodding).
}

data/adventures/half-the-hive/ivo.kyr:
Module hume "Half the Hive" {
  // ── Ivo Gildersleeve, of the Escort ───────────────────────────────────────────────────────────────────────────────
  // Born to the Escort: fed by the town, dressed in yellow, good for one thing, which is to walk behind a new queen to
  // the Toot; and two days after the Leaving, by custom, turned out of the Wold with a cloak and a loaf. He has walked
  // every path in the Wold out of idleness and knows it better than any Searcher, and nobody has ever asked him
  // anything. He can come with the company; he can dance; he can be turned out, and follow the company into the world.
  Person ivo "Ivo Gildersleeve" at drones_gallery {
    Role "one of the Escort: a tall gold-haired man in a yellow coat, lying on a cushion as if he had been poured there" when not ivoSearcher(ivo).
    Role "one of the Escort, and a Searcher, with a yellow ribbon tied round the sleeve of his yellow coat" when ivoSearcher(ivo).
    Ancestry human. Calling bard. Level 2. Peaceable. Pronouns he. Manner jovial.
    Greets "A tall man in a yellow coat turns his head and looks at you as if you had come expressly to rescue him from boredom. 'Oh, a new face. Thank the Mother. I have been looking at the old ones for thirty-four years.' He makes you a bow, beautifully, without getting up. 'Ivo Gildersleeve, of the Escort, at your service, which is to say at nobody's: we don't serve, we are served. Have a brood-cake. They're made of our little brothers.' His voice is extraordinary: deep and warm, like a cello in a small room. 'What brings you up among the useless?'".
    Greets again "Ivo raises his cup to you from the cushions. 'My only friend.'".
    Joins "Ivo stands up, and brushes the crumbs off his yellow coat, and looks round him as if he were seeing everything for the first time. 'Well,' he says. 'Lead on. I know where everything is. I have simply never had a reason to go there.'".
    Leaves "Ivo sketches you a bow. 'I'll be on the cushions,' he says, 'being decorative. Come and fetch me if you want anything found.'".
  }
  // What Ivo says, coming somewhere with the company. (The shared Remarks ask that he be able, which a companion who
  // has joined is not: friction.md.)
  Relation ivoRemarked(place).
  Rule ivo_at_gallow_hollow when travelsWith(ivo, party) and at(party, gallow_hollow) and not ivoRemarked(gallow_hollow) says "Ivo, who has talked since the linden wood, stops talking. After a while he says, very quietly, 'I used to come and sit on the knoll when I was a boy. I never once came in.'" { Assert ivoRemarked(gallow_hollow). }
  Rule ivo_at_black_crag when travelsWith(ivo, party) and at(party, black_crag) and not ivoRemarked(black_crag) says "'Ah,' says Ivo, looking up at the black bees on the crag. 'The robbers. I came this way once at fifteen and ran the last mile with my coat over my head. There is,' he adds, 'another way. Nobody ever asks.'" { Assert ivoRemarked(black_crag). }
  Rule ivo_at_far_hollow when travelsWith(ivo, party) and at(party, far_hollow) and not ivoRemarked(far_hollow) says "Ivo walks to the back of the hollow and kneels by the handprints in the old wax, and puts his own hand over one of them, enormous, and laughs. 'I did this,' he says. 'When I was nine. I ran away from the Escort for three days and came here and pressed my hand in the wax beside these and thought I was the first person in the world.' He takes his hand away. 'I wasn't, of course.'" { Assert ivoRemarked(far_hollow). }
  Rule ivo_at_dell_floor when travelsWith(ivo, party) and at(party, dell_floor) and not ivoRemarked(dell_floor) says "Ivo looks at the scored marks on the chalk. 'Those are dances,' he says. 'Old ones. Somebody left a message.' He squints. 'I never learned to read them. The Escort doesn't dance.'" { Assert ivoRemarked(dell_floor). }
  Rule ivo_at_toot when travelsWith(ivo, party) and at(party, toot) and not ivoRemarked(toot) says "Ivo looks at the standing stone on the Toot and is quiet for once. 'That's where we walk her,' he says. 'The new queen. All of us in our yellow, behind her, up the hill. She flies, and we stand round the stone and watch her go up, and that's what we're for.' He clears his throat. 'And then they turn us out.'" { Assert ivoRemarked(toot). }
  Person escort "the Escort" at drones_gallery {
    Role "a dozen men and women in yellow coats, lolling on cushions, talking about horses they do not own" when at(escort, drones_gallery).
    Role "a dozen men and women in yellow coats" when not at(escort, drones_gallery).
    Ancestry human. Numbers 12. Peaceable. Pronouns they.
  }
  Relation ivoSearcher(group). Relation ivoAsked(group). Relation ivoSaw(place). Relation ivoDances(place). Relation ivoTurnedOut(group).
  Relation kestrelTurned(group). Relation kestrelWatched(group).
  Topic ivo_escort with ivo "Ask Ivo what the Escort is for" when true once {
    Says "'Ornament.' He spreads his arms to show the yellow. 'The Escort are born, not made: the Gildersleeves, the Hollands, the Pyes. We are fed by the Comb from the cradle, and we do nothing, and we are very good at it, and once in a generation, when there is a new queen, we put on our best yellow and walk behind her up the Toot when she flies to be married, and stand round the stone and gaze up admiringly.' He drinks. 'Like drones, you see. That is the joke. Everybody's joke. Mine too.' He holds the cup up to the light. 'And then two days later they take us down to the edge of the Wold with a cloak and a loaf apiece and point us at the lowland, because the queen's married now and the Comb need not feed us any more. Like drones.' He smiles at you, beautifully. 'I'm told it's very moving.'".
  }
  Topic ivo_turning with ivo "Ask Ivo whether he is afraid of the Turning-out" when not ivoSearcher(ivo) and not leavingBegun() once {
    Says "He laughs. He makes a whole performance of laughing. Then he stops, and looks at his hands, which are very clean. 'I can't do anything,' he says, in a different voice. 'Do you understand? Not anything. I can't spin, I can't carve, I can't cook, I can't dance the dance, I can't keep a bee. I can talk and I can sing and I can walk. I have walked every path in this Wold, every single one, because there was nothing else to do.' He looks up. 'Thirty-four years. And in three days they'll put a loaf in my hand and point at the lowland. What does a man do in the lowland, who can walk?' He picks the cup back up. 'Don't answer. I'm being dull. Have a brood-cake.'".
  }
  Topic ivo_walks with ivo "Ask Ivo where he walks" when true {
    Says "'Everywhere. The wood, the moor, the Dell, the Toot, the knoll, out to the Far Brow and back.' He ticks them off. 'I know where the wild bees are in every tree in the linden wood. I know where the brocks drink. I know a shepherds' drove round the moor that misses the black crag by a mile and has a bothy halfway with a roof on it.' He shrugs. 'Nobody asks the Escort the way. We're not supposed to know it.'".
    On discuss { Assert knows(actor, drove_known). }
  }
  Discovery drove_known "Ivo Gildersleeve knows a shepherds' drove round the heather moor, gentle walking, a mile wide of the black crag, with a bothy halfway: a way to the Far Brow the old could walk.".
  Topic ivo_come with ivo "Ask Ivo to come out searching with you" when not ivoAsked(ivo) and not travelsWith(ivo, actor) once {
    Says "He looks at you as if you had spoken in another language. 'Searching,' he says. 'Me.' The cup stops halfway to his mouth. 'Nobody,' he says slowly, 'has ever asked me to come anywhere.' He puts the cup down. 'The Escort don't search. It isn't done.' He stands up. 'I should be delighted.'".
    On discuss { Assert ivoAsked(ivo). Assert willing(ivo, actor). }
  }
  // Where he has stood with the company, he can dance for.
  Rule ivo_sees when travelsWith(ivo, party) and at(party, ?r) and seenFrom(?r, ?s) and not ivoSaw(?s) { Assert ivoSaw(?s). }
  Topic ivo_learn with ivo "Ask Ivo whether he would like to learn the dance" when travelsWith(ivo, actor) and danceLearned(actor) and not ivoSearcher(ivo) and not leavingBegun() once {
    Says "'From you?' He looks delighted and appalled. 'A lowlander teaching the Escort the Searchers' dance. My grandmother would come out of the wax.' He takes off his coat. 'Show me.' You show him, there and then, wherever you are: the run, the waggle, the loop. He is terrible, and then, quite suddenly, he is not: he has a dancer's body and has never had a reason to use it, and when he runs the line the third time you see the place in it. He stops, breathing hard. 'Oh,' he says. 'Oh, I see. It's a kind of singing.'".
    On discuss { Assert ivoLearned(ivo). }
  }
  Relation ivoLearned(group).
  Action ivo_dance(actor: group, dest: place) "Ask Ivo to dance for {dest} in the Dancing Hall" {
    Requires able(actor) and company(actor) and at(actor, dancing_hall) and travelsWith(ivo, actor) and ivoLearned(ivo) and ivoSaw(dest) and hollowSite(dest)
      and not ivoDances(?any) and not committed() and not leavingBegun() and daytime().
    Time 3.
    On success { Assert ivoDances(dest). Increase tally(dest) by 1. Assert ivoSearcher(ivo). Assert kestrelWatched(kestrel). }
    Result "Ivo Gildersleeve of the Escort, in his yellow coat, walks out onto the slope of the Dancing Hall in front of every Searcher in the Brow, and the hall goes quiet in a particular way, the way a room does when someone is about to make a fool of himself. Then he dances. He dances the place the way he talks: too much, gorgeously, with his whole body, every waggle a phrase, and it is the best dance anyone in the hall has seen in years. Three Sisters come down the slope to read him. When he stops, the hall is silent. Then Kestrel Dunn, at the foot of the slope, takes the yellow ribbon off her own arm and walks up and ties it round his.".
  }
  Topic kestrel_ivo with kestrel "Ask Kestrel what she made of Ivo's dance" when kestrelWatched(kestrel) once {
    Says "'Nothing.' She is very busy with a strap. 'A Drone dancing. It reads, I suppose. It reads very well.' The strap will not do up. 'Thirty-four years he's been lying on cushions with that,' she says, to the strap, angrily, 'and nobody thought to ask him.' She gives up on the strap. 'He walked to the Far Brow when he was nine, did he tell you? On his own. I was eleven. I walked there when I was fourteen and found a new little handprint in the wax beside the old ones, fresh, and thought it was a ghost. I told my gran a ghost child had been there.' She looks at you, and then away, and goes rather red under the brown. 'Don't tell him that.'".
  }
  // Kestrel and the shepherds' drove: told by a stranger, she scoffs; told with Ivo there to say it, she listens.
  Topic kestrel_drove with kestrel "Tell Kestrel about the shepherds' drove round the moor" when knows(actor, drove_known) and not kestrelTurned(kestrel) and not travelsWith(ivo, actor) once {
    Says "'There's no way round the moor.' She does not even look up. 'I've crossed it forty times. You go by the crag, fast, with smoke, and hope.' Then she does look up. 'Who told you there was a way round?' You tell her. 'A Drone.' She laughs, not kindly. 'The Escort can't find the honey in a honey-cake.'".
  }
  Topic kestrel_drove_ivo with kestrel "Ask Ivo to tell Kestrel about the shepherds' drove" when knows(actor, drove_known) and not kestrelTurned(kestrel) and travelsWith(ivo, actor) once {
    Says "Ivo tells her. He does it well: the drove, where it leaves the moor path, the cairns that mark it, the bothy halfway with the names on the lintel, the gentle fall of it down to the Far Brow from the north, where the ground is soft. Kestrel listens with her arms folded, and her face does several things. When he has finished she says, 'Hannet could walk that.' And then: 'Agnes Mellor could walk that. Carrying.' And then, as if it hurt her: 'I didn't know it was there.' She looks at Ivo's boots, which have never done a mile of work. 'Forty times I've crossed that moor by the crag.' She unfolds her arms. 'Show me tomorrow. If it's there, the Leaving goes by it.'".
    On discuss { Assert kestrelTurned(kestrel). }
  }
  // After the Turning-out, a man with a loaf at the edge of the Wold.
  Topic ivo_world with ivo "Ask Ivo to come with you, out into the world" when ivoTurnedOut(ivo) and not travelsWith(ivo, actor) once {
    Says "He looks down the drove road toward the lowland, his loaf under his arm, his yellow coat already dusty. 'I can walk,' he says. 'I can talk. I can sing.' He tucks the loaf more firmly under his arm. 'And it turns out I can find things.' He smiles, the real smile, not the one for cushions. 'Yes. Thank you. Yes.'".
    On discuss { Assert willing(ivo, actor). }
  }
}

data/adventures/half-the-hive/lark.kyr:
Module hume "Half the Hive" {
  // ── Larkhill: Squire Corve and his flask ──────────────────────────────────────────────────────────────────────────
  // A younger son of a lowland house, a naturalist, who has drawn the Sisters for twelve years and written every spring
  // to the keeper to be named to the Comb, and been refused three times by the Scent-warden. This spring he paid Nell
  // Quarrie forty crowns for a flask of the Mother's scent made stronger than the Mother, to uncork on his tower at
  // dawn on the fourth day and call the swarm to his chantry. Under lowland law what nests on a man's land is his. He is
  // not greedy. He wants to belong to something that will not have him, and he has stolen it.
  Person corve "Squire Lucian Corve" at corve_study {
    Role "the squire of Larkhill: a thin fair man of forty in a good shabby coat, with ink on his cuffs and a magnifying glass on a ribbon round his neck".
    Ancestry human. Peaceable. Pronouns he. Manner compassionate.
    Greets "A thin fair man at the table jumps up so fast he knocks a sheet of drawings to the floor. 'A visitor! From the Wold? You've come down from the Brow?' He has your hand in both of his. 'Lucian Corve. Forgive the mess. Do you know them? The Sisters? Have you been in the Comb? What is it like inside, really like, the light, the sound?' He hears himself, and lets go of your hand, and smiles, embarrassed. 'Forgive me. I've been trying to get up that stair for twelve years.'".
    Greets again "Squire Corve looks up from his drawings with real pleasure.".
    Objects "Squire Corve looks at the flask in your hands, and goes white, and then red, and says nothing at all, and goes out of the room.".
  }
  Person halse "Halse" at chantry_yard {
    Role "the Larkhill bailiff: a big slow lowlander with a cudgel, who touches his hat to everyone".
    Ancestry human. Calling warrior. Level 3. Peaceable. Pronouns he. Manner stoic.
    Greets "A big man by the chantry gate touches his hat. 'Squire's in his study. Go in. He'll want to show you the drawings.' He sighs, very slightly. 'He'll want to show you all of them.'".
  }
  Initially Assert serves(halse, corve).
  Topic halse_squire with halse "Ask Halse about the squire" when true once {
    Says "'Good master.' Halse turns his hat round in his hands. 'Better than his father. Pays on quarter day, mends the cottages, talks to the bees in the skeps every morning like they were his aunts.' He looks at the chantry. 'Writes letters up the gorge every spring and nobody writes back.' A pause. 'Back in the spring he came home from Smoke End with a parcel, and he's not slept right since. Walks about at night. Went up the tower one morning a week back with something in his hand, and came down again white as a sheet, and every bee in the Wold was round that tower by noon.'".
  }
  Topic halse_skeps with halse "Ask Halse about the skeps along the wall" when true once {
    Says "'Ordinary bees. Lowland bees, the little brown sort.' He almost smiles. 'He bought them to practise on. Twelve years. He's never once been stung, he says, because he's never once been rough.' He scratches his neck. 'I have. Plenty.'".
  }
  Relation corveGives(group). Relation corveConfronted(group). Relation flaskGone(group).
  Thing flask_case "the squire's oak case" at corve_study {
    Holds.
    State locked closed "On a shelf by the window, a small case of polished oak with a brass lock, the only locked thing in the room.".
    State open "The oak case on the shelf stands open.".
  }
  Action pick_case(actor: group, site: place) "Pick the lock of the squire's oak case" {
    Description "While he is not in the room.".
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, corve_study) and not at(corve, corve_study) and state(flask_case, locked).
    Time 1.
    Resolve check(actor, lockwork, dc_fair).
    On success { Assert state(flask_case, open). }
    Result "The lock is good lowland work and takes you longer than it should, in the dark, with the house creaking; and then it gives.".
    Otherwise "The lock is good lowland work. It does not give, and somewhere in the house a floorboard does.".
  }
  Item corve_flask "the squire's flask" is queen_flask in flask_case owned by corve.
  Rule corve_sleeps when (hour(clock) >= 21 or hour(clock) < 7) and at(corve, corve_study) { Assert at(corve, limbo). }
  Rule corve_wakes when hour(clock) >= 7 and hour(clock) < 21 and at(corve, limbo) and not flaskGone(corve) { Assert at(corve, corve_study). }
  Rule halse_sleeps when (hour(clock) >= 22 or hour(clock) < 6) and at(halse, chantry_yard) { Assert at(halse, limbo). }
  Rule halse_wakes when hour(clock) >= 6 and hour(clock) < 22 and at(halse, limbo) { Assert at(halse, chantry_yard). }

  Topic corve_drawings with corve "Ask Squire Corve about his drawings" when true once {
    Says "He shows you. He cannot help it. Sisters from above, from below, in flight; a leg under the glass, every hair; a wing; the sting, the barb, the venom-sac; a Sister feeding a larva; the Mother, from a description, wrong in a dozen ways he does not know about. 'Twelve years,' he says. 'I came up the drove road at twenty-eight on a walking tour and saw them go over and never went home.' He touches the drawing of the Mother. 'I've never seen her. I've written to the keeper every spring since I came. Old Garnock wrote back, kindly. He sent me a wing.' The framed wing on the wall. 'And every spring the Scent-warden says no.'".
    On discuss { Assert knows(actor, corve_refused). }
  }
  Discovery corve_refused "Squire Lucian Corve of Larkhill has drawn the Sisters for twelve years, written to the keeper every spring, and been refused the scent each time by the Scent-warden, because a lowland lord owns things.".
  Topic corve_tower with corve "Ask Squire Corve about his tower" when not knows(actor, flask_known) once {
    Says "'Isn't it fine? I've had it pointed. Dry as a granary. South wall. Room for a hive four times the size of the Comb.' He looks out of the window at it. 'I've told the Searchers. I wrote to the Wardmistress. I'd ask no rent. I'd ask nothing at all.' He says it a little too quickly. 'They could come and go as they liked. I'd just be,' he searches for the word, 'near.'".
  }
  Topic corve_flask with corve "Ask Squire Corve about the flask Nell Quarrie made him" when knows(actor, flask_known) and not corveConfronted(corve) and not corveGives(corve) once {
    Says "He does not deny it. He sits down at his table among the drawings and looks at his inky hands. 'Yes.' After a while: 'Do you know what it is to love a thing that does not know you exist? For twelve years?' He laughs, without any pleasure. 'Of course they would have been mine. In law. I know that. I told myself I'd never use it; I'd never take a pot of honey; I'd just have them here, on my land, where I could see them, where I could go in among them with the smell on me and they would let me.' He looks at the shelf by the window. 'I tried it once, on the tower, a week ago. A minute. I had to know. By noon there were Sisters all over the stone, dancing on it.' His face is wretched and shining at once. 'I'm not a bad man. I'm a thief. It's not the same, quite, but it's near.' He does not offer to give it up.".
    On discuss { Assert corveConfronted(corve). }
  }
  Topic corve_named with corve "Tell Squire Corve the Hum-keeper will name him to the Comb herself, if he gives up the flask and gives the land" when linnetWillName(linnet) and knows(actor, flask_known) and not corveGives(corve) and not flaskGone(corve) once {
    Says "He does not understand you at first. Then he does, and stands up so fast the chair goes over. 'Name me. The keeper. Herself.' He goes to the window, and back. 'Up the stair. With the smell on me. Not stolen.' He goes to the shelf, and fumbles a key out of his waistcoat, and opens the oak case, and takes out a flask of green glass, and stands holding it in both hands like a man holding a bird. Then he gives it to you. 'Pour it in the stream,' he says. 'Or keep it. I don't want to see it.' He sits down at the table and pulls a sheet of paper toward him and writes, fast, in his neat hand, and signs it, and sands it: a deed of gift. The chantry at Larkhill and its tower and its yard, to the Comb of Hume Brow and whatever nests there, for ever, owned by nobody. He hands you that too. His hands are shaking. 'When?' he says. 'When can I go up?'".
    On discuss { Assert corveGives(corve). Assert flaskGone(corve). Assert lends(corve, corve_flask, actor). Give corve_flask to actor. }
  }
  // The flask in the company's hands: poured away, or uncorked where it will call her.
  Relation flaskAt(place). Measure flaskAtWatch(place). Relation forcedSwarm(group). Relation pouredFlask(group).
  Rule flask_taken when not inside(corve_flask, flask_case) and not flaskGone(corve) { Assert flaskGone(corve). }
  Action pour_flask(actor: group) "Pour the squire's flask out on the ground" {
    Requires able(actor) and company(actor) and holding(actor, queen_flask) and not committed().
    Time 1 minute.
    On success { Spend queen_flask from actor. Assert pouredFlask(actor). }
    Result "You break the wax and pull the stopper and pour it out, and the smell comes up off the ground like a shout, so strong your eyes stream; a Sister going over a long way up turns, and turns again, and circles, puzzled, and goes on. In an hour it is only a smell. In a day it will be nothing.".
  }
  Action uncork_flask(actor: group, dest: place, room: place) "Uncork the squire's flask here, on the wind, to call the swarm to {dest}" {
    Description "She will go where it smells of her, stronger than herself, whatever the dancers say.".
    Grave "Uncorked, it calls the Mother here at the next noon, whatever the Searchers dance; you will have chosen for the bees, and for two hundred people.".
    Requires able(actor) and company(actor) and holding(actor, queen_flask) and at(actor, room) and seenFrom(room, dest) and swarmReady() and not committed() and not leavingBegun().
    Time 1.
    On success { Spend queen_flask from actor. Assert flaskAt(dest). Assert forcedSwarm(actor). }
    Result "You break the wax and draw the stopper and set the flask in a crack where the wind takes it. The smell goes out from it like ripples from a stone. Within the hour the first Sisters come, high, circling, then lower; by evening there are dozens, walking on the rock, fanning their wings, beside themselves. They will go back and dance it. They will not be able to help it.".
  }
  // Left with him, he uncorks it on his tower at dawn on the fourth day.
  Rule corve_uncorks when day(clock) >= 4 and hour(clock) >= 6 and inside(corve_flask, flask_case) and not committed() and not leavingBegun() and not corveGives(corve) {
    Retract inside(corve_flask, flask_case). Assert at(corve_flask, limbo). Assert flaskAt(larkhill). Assert flaskGone(corve). }
  Rule corve_dawn at chantry_yard when flaskAt(larkhill) and not spread(corve_dawn) says "At dawn a thin fair man in a good shabby coat climbs to the top of the chantry tower at Larkhill with something green in his hands, and stands there till the sun clears the Wold; and then the wind brings, all down the Wold's edge, a smell of the Mother so strong that the ordinary bees in the skeps along the wall come boiling out, crazed." { Assert spread(corve_dawn). }
  Entity corve_dawn: fact "the flask on the tower".
  Rule flask_word at dancing_hall when flaskAt(?s) and not committed() and not spread(flask_word) says "On the upper slope of the Dancing Hall the Sisters' own scouts have gone mad. They are all dancing the same line, over and over, frantic, butting each other out of the way to dance it, and it is not the line of any place a Searcher danced. Kestrel Dunn stands at the foot of the slope with her face like a shut door." { Assert spread(flask_word). }
  Entity flask_word: fact "the scouts gone mad".
  Topic corve_after with corve "Ask Squire Corve whether he has been up the stair" when corveGives(corve) and leavingBegun() once {
    Says "'Yesterday.' He looks ten years younger and has not slept. 'She put her fingers on my forehead and my throat and my wrists, the keeper, and said something under her breath, and I went up the stair, and a Sister landed on my sleeve and tasted me and walked away.' He laughs, helplessly. 'She walked away. As if I were nobody. As if I were family.' He looks at his drawing of the Mother. 'I got her wrong,' he says. 'Every single thing. I'm going to do it again.'".
  }
}

data/adventures/half-the-hive/leaving.ky:
Module hume "Half the Hive" {
  // ── Who goes ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // Settled the moment she goes, from what each has come to: Kestrel and the Searchers always; Moss unless hurt; Hannet
  // if promised and the way is one she can be carried, or if she is still dancing for the tree it goes to; Linnet if
  // she knows Eben means to go; Eben unless he alone knows Linnet means to stay; Pim if Linnet does not; Agnes if she may
  // carry Tobit, has his likeness, or knows he is safe; Huw and the Drewes always; Ivo, if he is a Searcher and not with
  // the company. Whoever goes is at the camp that night; whoever stays is where they are.
  Relation goes(group). Relation stays(group). Relation decided(group).
  Rule decide_kestrel when leavingBegun() and not decided(kestrel) { Assert goes(kestrel). Assert decided(kestrel). }
  Rule decide_moss when leavingBegun() and not decided(moss) and not mossHurt(moss) and not travelsWith(moss, party) { Assert goes(moss). Assert decided(moss). }
  Rule decide_hannet_carried when leavingBegun() and not decided(hannet) and promiseMade(carry_hannet) and (not left(far_brow) or kestrelTurned(kestrel)) { Assert goes(hannet). Assert decided(hannet). }
  Rule decide_hannet_tree when leavingBegun() and not decided(hannet) and dancesFor(hannet, gallowtree) and left(gallowtree) { Assert goes(hannet). Assert decided(hannet). }
  Rule decide_linnet when leavingBegun() and not decided(linnet) and linnetKnows(linnet) { Assert goes(linnet). Assert decided(linnet). }
  Rule decide_eben when leavingBegun() and not decided(eben) and (linnetKnows(linnet) or not ebenKnows(eben)) { Assert goes(eben). Assert decided(eben). }
  Rule decide_pim when leavingBegun() and not decided(pim) and not linnetKnows(linnet) { Assert goes(pim). Assert decided(pim). }
  Rule decide_agnes when leavingBegun() and not decided(agnes) and (linnetPermitsDead(linnet) or likenessGiven(agnes) or agnesFreed(agnes)) { Assert goes(agnes). Assert decided(agnes). }
  Rule decide_huw when leavingBegun() and not decided(huw) { Assert goes(huw). Assert decided(huw). }
  Rule decide_drewes when leavingBegun() and not decided(drewes) { Assert goes(drewes). Assert decided(drewes). }
  Rule decide_ivo when leavingBegun() and not decided(ivo) and ivoSearcher(ivo) and not travelsWith(ivo, party) { Assert goes(ivo). Assert decided(ivo). }
  // To the camp.
  Rule goers_walk when left(?s) and siteRoom(?s, ?r) and goes(?x) and not walked(?x) { Assert at(?x, ?r). Assert walked(?x). }
  Relation walked(group).
  Rule linnet_stays_home when leavingBegun() and not goes(linnet) and decided(pim) and not walked(linnet) { Assert at(linnet, royal_gallery). Assert walked(linnet). }
  Rule pim_stays_home when leavingBegun() and goes(linnet) and not walked(pim) { Assert at(pim, royal_gallery). Assert walked(pim). }
  // Agnes carries him: the bier is empty.
  Rule tobit_carried when goes(agnes) and linnetPermitsDead(linnet) and at(tobit_bier, capped_gallery) { Assert at(tobit_bier, limbo). }

  // ── Crossed, on the Apron ─────────────────────────────────────────────────────────────────────────────────────────
  Rule lovers_cross at apron when leavingBegun() and goes(eben) and not goes(linnet) and not spread(lovers_cross) says "At the foot of the stair two people pass each other in the crowd: a long-faced man in a travelling cloak with a Waxwright's roll of blades on his back, going out after the bees, not looking back; and a young woman with a shaved head and Sisters on her arms, coming in, not looking at anyone. They do not see each other. The crowd closes between them." { Assert spread(lovers_cross). }
  Entity lovers_cross: fact "the lovers crossed".
  Rule pim_goes_told at apron when leavingBegun() and goes(pim) and not spread(pim_goes_told) says "At the head of the going, beside Kestrel, walks the keeper's novice, Pim Garnock, seventeen, with his shaved head sunburnt and his arms held out stiffly from his sides because they are covered in Sisters, and his face set like a boy's at his first funeral." { Assert spread(pim_goes_told). }
  Entity pim_goes_told: fact "Pim at the head of it".

  // ── The founding night ────────────────────────────────────────────────────────────────────────────────────────────
  // Wherever she went, the first evening, told to a company that is there.
  Query atCamp() means left(?s) and siteRoom(?s, ?r) and at(party, ?r).
  Rule founding at far_hollow when left(far_brow) and at(party, far_hollow) and day(clock) <= leftDay(hume_wold) + 1 and not spread(founding)
    says "By the time the last of the Leaving comes in under the Far Brow it is nearly dark, and the swarm has already hung itself from the rock, a great brown beard of bees as long as a barn, roaring softly; and at its top, where it touches the stone, the Sisters have begun to build. You can see it if you stand close: a first finger of new comb, white as milk, the whitest thing in the world, growing while you watch. They are all too tired to stand. Someone lights a fire, which they never do at home. Somebody passes round a crock of honey and a knife. And then, for no reason, very badly, too tired to sing, two hundred people sing: the hum, the old note under everything, sitting on the warm dust under the Far Brow with the white comb growing over their heads; and Kestrel Dunn sits by the child-handprints at the back with her knees up and her face hidden." { Assert spread(founding). }
  Rule founding_far_drove at far_hollow when left(far_brow) and at(party, far_hollow) and spread(founding) and kestrelTurned(kestrel) and not spread(founding_far) says "The old came by the shepherds' drove, slow, with the bothy to rest in. Hannet Coke was carried in on the Searchers' litter at dusk, by four of them and a man in a yellow coat, telling them all the way how to do it." { Assert spread(founding_far). }
  Rule founding_far_crag at far_hollow when left(far_brow) and at(party, far_hollow) and spread(founding) and not kestrelTurned(kestrel) and not spread(founding_far) says "They came by the crag, fast, with smoke, the way Kestrel always went. Not everyone who set out is here. The old stayed home, mostly, knowing; and of those who tried it, some turned back, and the black bees took a few. Kestrel goes along the line with her face set, counting." { Assert spread(founding_far). }
  Entity founding_far: fact "the way to the Far Brow".
  Rule founding_far_ivo at far_hollow when left(far_brow) and at(party, far_hollow) and spread(founding) and ivoSearcher(ivo) and not spread(founding_ivo) says "Later, when the singing has worn itself out, a man in a yellow coat gone brown with walking goes to the back of the hollow and sits down by the handprints, a little way from Kestrel Dunn; and after a while she shifts over, without looking at him, and makes room." { Assert spread(founding_ivo). }
  Entity founding_ivo: fact "Ivo by the handprints".
  Rule founding_dell at dell_floor when left(chalk_dell) and at(party, dell_floor) and day(clock) <= leftDay(hume_wold) + 1 and not spread(founding)
    says "The swarm goes into the cave in the chalk like smoke going up a chimney, and in an hour there is a roar inside it like a sea-cave, and the Leaving sits down on the warm floor of the Dell among the harebells, too tired to talk. The white walls hold the day's heat long after sunset. Someone finds the first new comb in the cave mouth by lamplight, pale as a fingernail, a hand's breadth already, and carries the news out, and then, too tired to sing, they sing: the hum, two hundred voices in a bowl of chalk that gives it back." { Assert spread(founding). }
  Rule founding_dell_truce at dell_floor when left(chalk_dell) and at(party, dell_floor) and spread(founding) and brockTruce(brocks) and not spread(founding_dell2) says "At the back of the Dell, outside a smaller hole in the chalk, two brock sows lie in the last of the sun with their chins on their paws, watching the new town with their small black eyes, and nobody is afraid of them. Moss Ashdown, sitting as near them as he dares, is cutting fresh dance-marks into the chalk under the old ones, for whoever comes next." { Assert spread(founding_dell2). }
  Rule founding_dell_blood at dell_floor when left(chalk_dell) and at(party, dell_floor) and spread(founding) and brocksKilled(brocks) and not spread(founding_dell2) says "The children have been told not to go near the back of the Dell, where the chalk is stained and the flies are. They go anyway, and come back quiet." { Assert spread(founding_dell2). }
  Rule founding_dell_brocks at dell_floor when left(chalk_dell) and at(party, dell_floor) and spread(founding) and not brocksSafe() and not spread(founding_dell2) says "Nobody sleeps. The brocks were driven out of the cave by the bees, and they are somewhere in the dark at the back of the Dell, and every so often one of them coughs, low, like a man clearing his throat in the next room." { Assert spread(founding_dell2). }
  Entity founding_dell2: fact "the brocks at the founding".
  Rule founding_lark at chantry_yard when left(larkhill) and at(party, chantry_yard) and day(clock) <= leftDay(hume_wold) + 1 and not spread(founding)
    says "The swarm goes into the chantry tower at Larkhill through the louvres of the belfry, a brown river pouring upward, and the tower hums like a struck bell. The Leaving sits down in the walled yard and in the lane outside it. In the farmhouse windows the squire's household stands looking out at them. It is dry, and safe, and the lowland is a morning's walk away, and nobody sings." { Assert spread(founding). }
  Rule founding_lark_gift at chantry_yard when left(larkhill) and at(party, chantry_yard) and spread(founding) and corveGives(corve) and not spread(founding_lark2) says "At the gate Squire Corve stands with his hat in his hands, not coming in, until Linnet goes down to him with the jar, and draws her fingers down his forehead, his throat, his wrists, and says the words under her breath; and a Sister lands on his sleeve and walks up it and tastes his face, and walks away. Then they do sing. He stands in the middle of it with his hat crushed in his fist and does not know the tune, and hums it anyway, wrong." { Assert spread(founding_lark2). }
  Rule founding_lark_owned at chantry_yard when left(larkhill) and at(party, chantry_yard) and spread(founding) and not corveGives(corve) and not spread(founding_lark2) says "At dusk Halse the bailiff comes out of the farmhouse with a hammer and a board and, not looking at anyone, nails the board to the chantry gate: THESE BEES AND ALL THEY MAKE THE PROPERTY OF L. CORVE ESQ. OF LARKHILL. TRESPASSERS PROSECUTED. In an upper window of the farmhouse the squire stands, quite still, looking down at the yard full of people who will not look up." { Assert spread(founding_lark2). }
  Entity founding_lark2: fact "the squire at the founding".
  Rule founding_gallow at gallow_knoll when left(gallowtree) and at(party, gallow_knoll) and day(clock) <= leftDay(hume_wold) + 1 and not spread(founding)
    says "The swarm goes into the Gallowtree through the door in the trunk and the cracks in its crown, and the old tree roars from root to leaf like a forest in a gale, and the Leaving sits down on the knoll in the long evening light. It was a short walk. Everyone came: the old, the lame, the women with children. Linnet goes inside with the first of the Searchers to see where the bees are building, and comes out after a while, and sits down by herself on the far side of the knoll, and does not say what she saw." { Assert spread(founding). }
  Rule founding_gallow_know at gallow_knoll when left(gallowtree) and at(party, gallow_knoll) and spread(founding) and knows(party, gallow_rotten) and not spread(founding_gallow2) says "In the night it rains a little. You lie awake on the knoll and listen to the water going into the tree through the cracks in its crown, and down inside it, slowly, drip by drip, into the soft heart." { Assert spread(founding_gallow2). }
  Entity founding_gallow2: fact "rain in the Gallowtree".
  Rule founding_bivouac at honey_oak when left(high_wold) and at(party, honey_oak) and day(clock) <= leftDay(hume_wold) + 1 and not spread(founding)
    says "The swarm never decided. It came out of the Brow, and hung in the lindens a while, roaring, waiting for a word that did not come; and in the end it settled on the honey linden, on a great bough in the open air, and began, because it could not help it, to build: white comb hanging from the bark in the wind and the sun, beautiful, unsheltered, for anything to take. The Leaving sits in the clearing under it and does not know what to do." { Assert spread(founding). }
  Entity founding: fact "the founding night".
  // Named to the hive: whoever walked with them, at the founding; the keeper of the Leaving does it.
  Rule named_at_founding when walkedWith(party) and spread(founding) and atCamp() and not named(party)
    says "Late, by the fire, the keeper of the Leaving comes and kneels in front of you with the jar of the Mother's own scent, and draws two fingers down your forehead, your throat, the insides of your wrists, behind your ears, saying the words under the breath that have the hum's tune; not the guest's anointing, but the other one, the one for a child. 'You walked with us,' is all that is said. A Sister on the rock above you turns her head toward you, and away, as if you had always been here." { Assert named(party). }
  Rule named_founder when named(party) and partyDances(?s) and left(?s) and atCamp() and not spread(founder_named) says "And they tell you, as if it were a small thing, what the Leaving has decided to call the new comb, in the Wold way, after the first Searcher who danced for it who was not born to it. It is your name. They say it oddly, with the hum in it. It will be on the maps of the Wold for four hundred years, said wrong." { Assert spread(founder_named). }
  Entity founder_named: fact "the comb named for you".
  // The brocks come in the night, to a Dell where nothing was done about them.
  Rule brocks_raid at dell_floor when left(chalk_dell) and not brocksSafe() and able(brocks) and night() and day(clock) >= leftDay(hume_wold) and not raided(brocks) says "In the small hours the brocks come back for their cave. Two grey shapes out of the dark at the back of the Dell, low and fast, into the sleeping Leaving, and the screaming starts." {
    Assert raided(brocks). Assert at(brocks, dell_floor). Retract peaceable(brocks). }
  Relation raided(group).
  Rule brocks_assail_camp when raided(brocks) and at(brocks, dell_floor) and at(party, dell_floor) and able(brocks) and not assails(brocks, party) and not tolerates(brocks, party) and night() { Assert assails(brocks, party). }
}

data/adventures/half-the-hive/lore.kyr:
Module hume "Half the Hive" {
  Description "Links outward from the Wold: a ship's people who keep their own hours, and a Dame who is shown a keeper's face.".

  // ── A world event, read: a story for the Smoker's Rest ──────────────────────────────────────────────────────────
  Observe lore_rest_ship at taproom when befell(remainder_harboured) "A drover from the south is telling the room about a ship's company who came ashore in a town on the coast and would not sleep when the town slept. 'They keep their own hours,' he says. 'Twelve to a watch, like bees to a shift, and they hum when they are thinking.' Martin Sayle stops his cloth. 'That is a thing the Leavers would have liked to know,' he says, 'seventy year back.' The drover asks what they did. 'Nothing,' says Martin, 'that anyone wrote down.'".

  // ── A visitor from elsewhere: a keeper's face ───────────────────────────────────────────────────────────────────
  Discovery lore_brenna_face "A keeper's grey face, shown to the Dame of the Brood, is a face the Brood has no word for, because it has a face.".
  Topic lore_brenna_mask with brenna "Show Dame Brenna the grey keeper's face" when holding(actor, keeper_mask) once {
    Says "The Dame turns it to the light on her palm, and the escort around her goes still. 'A face,' she says, 'that does not do anything.' She does not touch it again. 'We have the Leaving, which is a face going away. We have the Capped, which is a face that was never asked. This is a face that stayed, and has been made to stay.' The royal gallery hums, once, on a note you can feel in your teeth. 'Whoever carried this carried it for someone who could not,' says Brenna, and gives it back with the tips of two fingers. 'I do not want to know who. Put it away before the Daughters see.'".
    On discuss { Assert knows(actor, lore_brenna_face). }
  }
}

data/adventures/half-the-hive/lovers.kyr:
Module hume "Half the Hive" {
  // ── Crossed: Linnet Amory and Eben Candlish ───────────────────────────────────────────────────────────────────────
  // Each has decided, secretly, to give up their calling for the other. Eben will walk with the Leaving and leave the
  // Lantern Stair one course short; Linnet will stay and give the Mother to Pim, who is seventeen. Neither has told the
  // other. Told that Eben is going, Linnet goes too; told that Linnet is staying, Eben stays; told both, they go together.
  // Left alone, they cross on the Apron. The Stair can be finished in a night, with white wax, a hand and a voice.
  Person linnet "Linnet Amory" at mothers_chamber {
    Role "the Hum-keeper: a young woman with a shaved head and bare arms crawling with Sisters, who does not seem to notice them" when not leavingBegun().
    Role "the Hum-keeper, with a shaved head, and grass-stains on her gown from the long walk" when leavingBegun() and goes(linnet).
    Role "the Hum-keeper, with a shaved head, who stayed" when leavingBegun() and not goes(linnet).
    Ancestry human. Calling cleric. Level 3. Peaceable. Pronouns she. Manner compassionate.
    Greets "A young woman sitting cross-legged beside the Mother looks up. Her head is shaved and her arms are bare and there are Sisters walking on them, on her shoulders, on her scalp, and she moves them aside with a finger as you might move a cat off a chair. 'Shh,' she says, not to you. Then, to you, low: 'She's resting. She has a long way to go and she's never flown in her life, not since she was a girl.' She looks at the Mother with an expression you have seen on people at a bedside. 'I'm Linnet. I keep her. For four more days.'".
    Greets again "Linnet looks up from beside the Mother, and moves a Sister off her cheek, and smiles.".
  }
  Person eben "Eben Candlish" at wax_gallery {
    Role "a Waxwright: a long-faced man of forty with burnt fingertips and wax in his beard, who keeps looking up at the Stair" when not leavingBegun().
    Role "a Waxwright, with wax in his beard" when leavingBegun().
    Ancestry human. Peaceable. Pronouns he. Manner grim.
    Wants white_wax.
    Greets "A long-faced man at the foot of the Stair is warming a blade in a little brazier, and does not look round. 'Don't touch it,' he says. 'Everyone touches it.' Then he looks round, and sees you are a stranger, and something in his face lets go. 'Sorry. Nineteen years. You'd think they'd stop touching it.' He looks up the spiral to where it ends in air. 'One course,' he says. 'One turn. And then it goes all the way to the Crown and the sun comes down it at midsummer like water down a drain.'".
    Greets again "Eben Candlish looks up from his brazier, and then up at the Stair, as he always does.".
  }
  Person pim "Pim Garnock" at mothers_chamber {
    Role "the keeper's novice: a gangling boy of seventeen with a newly shaved head, sunburnt where the hair was" when not leavingBegun().
    Role "the keeper's novice, keeping what is left" when leavingBegun() and not goes(pim).
    Role "the keeper's novice, keeping the Leaving's queen, out of his depth" when leavingBegun() and goes(pim).
    Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "A gangling boy with a raw scalp is holding a bowl of something for the Sisters to drink from, and spilling it. 'Sorry, sorry,' he says to the bees, and then to you. 'I'm Pim. I'm the novice. When Linnet goes I'll be the keeper.' He laughs, a little high. 'Of the Daughters. Three of them. In the royal gallery. Who'll wake up and try to kill each other.' He spills some more. 'It'll be fine.'".
    Greets again "Pim looks up and spills something. 'Oh, hello.'".
  }

  Relation ebenGoing(group). Relation linnetStaying(group). Relation linnetKnows(group). Relation ebenKnows(group).
  Initially Assert ebenGoing(eben). Initially Assert linnetStaying(linnet).
  Discovery eben_secret "Eben Candlish means to walk with the Leaving and leave the Lantern Stair unfinished, for Linnet's sake. He has not told her.".
  Discovery linnet_secret "Linnet Amory means to stay behind and give the Mother to Pim, for Eben's sake. She has not told him.".
  Relation stairLit(group). Relation stairFailed(group).

  // Eben.
  Topic eben_stair with eben "Ask Eben about the Lantern Stair" when not stairLit(eben) and not leavingBegun() {
    Says "'Every Waxwright makes one thing that's theirs. That's mine.' He follows it up with his eyes, turn by turn: flowers, Sisters, the faces of the Brow, children, hands. 'My master started it. I took it on at twenty-one. Every tread is somebody: that's Kestrel at fourteen, that's old Penry's first barrel, that's Linnet the day she was made keeper.' He stops. 'The last course wants white wax. New comb, never brooded. The Sisters don't draw it white any more, not in a hive this old; the only white comb left in the Wold is in places nobody goes.' He shrugs, too hard. 'It doesn't matter now.'".
  }
  Topic eben_why with eben "Ask Eben why it doesn't matter now" when not stairLit(eben) and not knows(actor, eben_secret) and not leavingBegun() once {
    Says "He looks you over, and you can see him deciding: a stranger, who will be gone in a week. 'Because I'm going,' he says. 'With the Leaving. With her.' He doesn't say who. 'She's the keeper; keepers go. And I'm not going to stand on the Apron and watch her walk off after the bees and then come up here and carve. So I'm going.' He looks up the Stair. 'Somebody'll finish it. Or not. It's wax.' His voice does something on the last word. 'I haven't told her. She'd only tell me to stay and finish it, and she'd be right, and I'd stay.' He turns back to his brazier. 'Don't tell her.'".
    On discuss { Assert knows(actor, eben_secret). }
  }
  Topic eben_told with eben "Tell Eben that Linnet means to stay behind for him" when knows(actor, linnet_secret) and not ebenKnows(eben) and not leavingBegun() once {
    Says "He puts the blade down on the bench, very carefully, as if it might go off. 'Stay,' he says. 'Linnet. Give the Mother to Pim?' And then, getting it: 'For me. So I could finish this.' He looks up the Stair and for a moment you think he will knock it down. 'The stupid,' he says. 'The stupid, stupid,' and then he laughs, and sits down on the bench with his burnt hands over his face, and laughs until it is not laughing.".
    On discuss { Assert ebenKnows(eben). }
  }
  Topic eben_old_comb with eben "Ask Eben for some old dark comb" when knows(actor, brock_truce) and not holding(actor, old_comb) once {
    Says "'Brood comb? Old black stuff?' He jerks his head at a heap of it under the bench, gone dark as liver with a hundred years of being lived in. 'Take what you like. Nobody can carve it.' He watches you pick a slab out. 'What do you want it for?' You tell him. 'The brock-gift,' he says slowly. 'My grandad used to talk about that. They stopped doing it when the Searchers stopped reading the old marks.'".
    On discuss { Give old_slab to actor. }
  }
  Item old_slab "a slab of old black comb" is old_comb at limbo.
  Event white_wax_given near eben when keeps(eben, white_slab) "Eben Candlish takes the white comb from you in both hands and holds it up to the light, and the light comes through it as if through a leaf. 'Where,' he says, and then, 'no, don't, I can guess.' He is already reaching for his blades. 'Tonight. It must be tonight; it has to set cool. I'll want a pair of hands to hold the mould while it takes, all night, without moving. Or,' he hesitates, 'a voice. The old Waxwrights sang it in. The hum's key. It sets truer sung.'" then { Assert ebenReady(eben). }
  Relation ebenReady(group).
  Action stair_hold(actor: group, site: place) "Hold the mould for Eben through the night while the last course sets" {
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, wax_gallery) and at(eben, wax_gallery) and ebenReady(eben) and not stairLit(eben) and (hour(clock) >= 20 or hour(clock) < 2).
    Time 30.
    Resolve check(actor, brawn, dc_fair).
    On success { Assert stairLit(eben). }
    On failure { Assert stairFailed(eben). }
    Result "Eben warms the white wax in a copper over the brazier until it goes clear as water, and pours it, and you hold the mould: a curved trough of oiled wood the length of a coffin, up on the last turn of the Stair, braced against your shoulder, while the wax cools and clouds and whitens inside it. You hold it for five hours. Your arms burn and then stop burning and then burn again. Eben carves as it sets, fast, not talking, and you see under his knife a face coming out of the wax, and then another. Toward dawn he says, 'Let go,' and you do, and the course stays: a last white turn of the Stair, joining the old wax to the hole in the ceiling, and through the hole, grey, the light of the Crown.".
    Otherwise "Somewhere around three your arm shakes, once, and the mould moves a finger's breadth, and the wax inside it cracks across like ice. Eben says nothing at all. He tips the cracked course out into the copper to melt down again. 'Tomorrow night,' he says. 'It'll take it twice.'".
  }
  Action stair_sing(actor: group, site: place) "Sing the hum's key to the last course of the Stair while it sets" {
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, wax_gallery) and at(eben, wax_gallery) and ebenReady(eben) and not stairLit(eben) and (hour(clock) >= 20 or hour(clock) < 2).
    Time 30.
    Resolve check(actor, performance, dc_fair).
    On success { Assert stairLit(eben). }
    On failure { Assert stairFailed(eben). }
    Result "Eben pours the white wax, clear as water, into the mould on the last turn, and wedges it, and nods to you; and you sing. Not a song: the hum. The note under everything in the Comb, which you find you know, after these days, the way you know your own pulse. You hold it, and when your breath goes you take another and hold it again, and the Sisters on the walls of the gallery lean toward you, and some of them begin to hum with you, and the wax in the mould clouds and whitens evenly from the edges in, without a crack, while Eben carves faces into it as it comes. By dawn your throat is raw and the Stair goes all the way up.".
    Otherwise "You lose the note around three: your voice cracks, the Sisters on the walls go quiet, and the wax in the mould cracks with it, across, like ice. Eben tips it back into the copper. 'Tomorrow night,' he says. 'It'll take it twice.'".
  }
  Action stair_ivo(actor: group, site: place) "Ask Ivo to sing the hum's key to the last course while it sets" {
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, wax_gallery) and at(eben, wax_gallery) and ebenReady(eben) and not stairLit(eben) and travelsWith(ivo, actor) and (hour(clock) >= 20 or hour(clock) < 2).
    Time 30.
    On success { Assert stairLit(eben). Assert ivoSang(ivo). }
    Result "Ivo looks at the mould, and at Eben, and at you, and for once makes no joke at all. He takes off his yellow coat and folds it and sits down on the bottom step, and opens his mouth, and the hum comes out of him: deep, steady, enormous, the voice he has been wasting all his life on feasts. The Sisters on every wall of the gallery turn toward him. Some come down and stand round him on the floor. All night he holds it, breathing in the gaps so you cannot hear him breathe, and the white wax sets in the mould as evenly as frost on a window, and Eben, carving, keeps stopping to look at him. At dawn Ivo closes his mouth and says, hoarsely, 'Well. Nobody's ever asked me that before.'".
  }
  Relation ivoSang(group).
  Rule stair_retry when stairFailed(eben) and hour(clock) >= 12 and hour(clock) < 13 { Retract stairFailed(eben). }
  Rule stair_dawn at wax_gallery when stairLit(eben) and hour(clock) >= 5 and not spread(stair_dawn) says "At sunrise the sun comes in at the window of the Crown and down the Lantern Stair, all the way down, for the first time, turn by turn, lighting each tread from inside: the flowers, the bees, the hands, the faces of the Brow one after another, gold, and at the bottom, white, the newest faces. People come running from all over the Brood to stand at the foot of it and look up. Somebody starts to cry. Eben Candlish sits on the bottom step with his chin on his fists and does not say anything at all." { Assert spread(stair_dawn). }
  Entity stair_dawn: fact "the Stair lit".
  Passage lantern_stair "the Lantern Stair" is stair between wax_gallery and mothers_chamber opening when stairLit(eben) "The Lantern Stair climbs round and round toward the Crown and stops, three turns up, at nothing.".
  Observe stair_done at wax_gallery as feature when stairLit(eben) "The Lantern Stair goes all the way up now, to the Crown, its last course white, and in the white you can find, if you look, a face you know.".

  // Linnet.
  Topic linnet_mother with linnet "Ask Linnet about the Mother" when not leavingBegun() {
    Says "'She's nine years old, which is very old for a queen, and she has laid more eggs than there are stars, and every Sister in this Comb is her daughter.' Linnet strokes the dark flank. 'Old Garnock, the keeper before me, said she'd swarm this year, and he was right, and then he died in the spring before he could see it, so I'm her keeper.' She smiles crookedly. 'I'm twenty-four. I'll walk her across the Wold to wherever the dancers say, and sit with her while they build, and keep her till she dies, and then I'll keep her daughter. That's what a keeper is.'".
  }
  Topic linnet_ready with linnet "Ask Linnet whether she is ready to go" when not knows(actor, linnet_secret) and not leavingBegun() once {
    Says "She does not answer for a while. A Sister walks across her face and she closes her eyes for it. 'No,' she says. 'I'm not going.' She says it so quietly you hardly hear it under the hum. 'I'll give her to Pim. Keepers have handed over before, when they were ill. I'll say I'm ill.' She opens her eyes. 'There's a man in the Waxwrights' gallery who has given nineteen years to a stair, and it wants one course, and if I go he'll come with me; I know he will; he'll leave it. So I'm not going. I'll stay and he can finish it and I'll be in the Comb when he does.' She looks at Pim spilling the Sisters' water across the chamber. 'Pim will be all right,' she says. 'Pim will be fine.' You can hear she does not believe it.".
    On discuss { Assert knows(actor, linnet_secret). }
  }
  Topic linnet_told with linnet "Tell Linnet that Eben means to go with the Leaving, and leave the Stair" when knows(actor, eben_secret) and not linnetKnows(linnet) and not leavingBegun() once {
    Says "Linnet sits very still. Then she says, 'He what?' loudly enough that the Mother stirs, and every Sister in the ring turns its head. 'He'd leave it,' she says, lower. 'Nineteen years. For me.' She puts her hand on the Mother's back as if to steady herself. 'And I was going to stay. For him. So he could finish it.' She laughs, once, appalled. 'We'd have passed each other on the Apron. Him going, me staying. Both of us being noble.' She is quiet. Then she says, decided, a keeper: 'I'm going. I keep her; I go. If he comes, he comes.'".
    On discuss { Assert linnetKnows(linnet). }
  }
  // Told both, they meet: wherever the second is told, the other comes.
  Rule lovers_meet at wax_gallery when linnetKnows(linnet) and ebenKnows(eben) and not spread(lovers_meet) says "Linnet Amory comes down into the Waxwrights' gallery with Sisters still on her arms, and every Waxwright at every bench stops work. Eben stands up. Neither of them says anything for so long that someone drops a blade. Then Linnet says, 'You were going to leave it,' and Eben says, 'You were going to stay,' and Linnet says, 'Idiot,' and Eben says, 'Yes,' and that seems to be all that needs saying, because she walks into his arms, Sisters and all, and the Waxwrights start working again very loudly, all at once, looking at their benches." { Assert spread(lovers_meet). }
  Entity lovers_meet: fact "Linnet and Eben".
  Topic linnet_dead with linnet "Ask Linnet to let Agnes Mellor carry Tobit with the Leaving" when wantsTobit(agnes) and not linnetPermitsDead(linnet) and not leavingBegun() once {
    Says "'No.' She says it at once, gently. 'The dead stay. They always stay. That's what the Capped Gallery is: the ones who went are the Comb's future, and the ones who stay are its past, and the dead are with the past.' She strokes the Mother. 'If we carried our dead, we'd carry everything. Every Leaving would be a funeral procession, and the new comb would be built round coffins.' She looks at you. 'I know what Agnes wants. I'm sorry.'".
  }
  Action plead_tobit(actor: group, site: place) "Tell Linnet about the dark watch you kept with Agnes, and what she said to him" {
    Speaker linnet.
    Requires at(actor, site) and able(actor) and at(actor, mothers_chamber) and at(linnet, mothers_chamber) and keptWatch(actor) and wantsTobit(agnes) and not linnetPermitsDead(linnet) and not leavingBegun().
    Time 1.
    On success { Assert linnetPermitsDead(linnet). }
    Result "You tell her about the watch in the dark: Agnes's voice going on and on to the shape in the wax, about the goat, and the roof, and their son in Ketter, and whose turn it was to fetch water, as if he could answer. Linnet listens with her hand on the Mother. When you have done she says, 'She talked to him about the goat.' And then, after a while: 'Nobody ever wrote down that the dead must stay. It's just what's done.' She looks at the old queen, who is leaving everything she ever made. 'Tell Agnes she can carry him. Tell her I'll walk beside her.'".
  }
  Relation linnetPermitsDead(group).
  Topic linnet_corve with linnet "Tell Linnet about Squire Corve and his twelve years of drawings" when knows(actor, corve_refused) and not linnetWillName(linnet) and not leavingBegun() once {
    Says "'Corve.' She knows the name. 'He writes to the keeper every spring. Old Garnock used to read his letters out to us in the Crown, the drawings especially; they're better than anything in the Brow. Every leg-hair. And every spring he asks to be named, and every spring Elspet says no, because he's a lowland lord, and lowland lords own things.' She frowns. 'He's never asked me. I've only been keeper since Lady Day.' She thinks. 'If he gave up whatever he's doing at Larkhill, and if he gave the land, freely, so that whatever nested there was nobody's,' and she looks at the Mother. 'I'd name him myself. Elspet can't stop the keeper. A man who has drawn every hair on a Sister's leg for twelve years is more of the Comb than half the Escort.'".
    On discuss { Assert linnetWillName(linnet). }
  }
  Relation linnetWillName(group).
  Topic pim_daughters with pim "Ask Pim about the Daughters" when not leavingBegun() {
    Says "'Three princess cells. One's the Brecks', one's the Candlishes', one's the Ashdowns'. Every queen-cell has a household to watch it, it's an honour.' He swallows. 'When the Mother goes, the first princess out pipes; you can hear it all through the Comb. And the others answer from inside their cells, because they're not out yet. And then the first one goes to their cells and stings them through the wax.' He looks at his bowl. 'That's how it's always been. One queen.' He lowers his voice. 'Unless the other cells are caged. Then she can't get at them, and the second one comes out and leaves with some of the bees: a cast, a little Leaving. Old Garnock did it once. Everybody said it was unnatural.'".
    On discuss { Assert knows(actor, cages_known). }
  }
  Discovery cages_known "If the other princess cells are caged before the first princess wakes, she cannot reach them, and the second wakes and leaves with a cast: a second, smaller Leaving. It was done once, in old Garnock's time.".
}

data/adventures/half-the-hive/placed.kyr:
Module hume "Half the Hive" {
  // The country beyond a march of a generated world: the company that comes in by the drove road is the world's own.
  Entity party: group "Your company".
  // What the country below says of the Wold (its innkeepers' rumour of the swarm): once the Mother has gone, it is old
  // news there, and they say so to whoever comes back down the drove road.
  Entity word: fact "What is said of the Wold of Hume in the country below.".
  Rule word_old when leavingBegun() and not stale(word) { Assert stale(word). }
}

data/adventures/half-the-hive/smoke.kyr:
Module hume "Half the Hive" {
  // ── Smoke End ─────────────────────────────────────────────────────────────────────────────────────────────────────
  // The outsiders' street at the mouth of the gorge: an inn, a smith of smokers and veils, a perfumer, and the
  // Chandlers' yard, where this week the Leavers' things are bought at a fifth of what they are worth.

  // Martin Sayle, who keeps the Smoker's Rest.
  Person martin "Martin Sayle" at taproom {
    Role "the keeper of the Smoker's Rest: a grey, square, careful man who turns his head to listen with his left ear".
    Profession innkeeper. Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Sells rations for 2 coin from 8.
    Buys wax_cake for 2 coin.
    Buys wild_comb for 3 coin.
    Greets "The man behind the board turns his head to bring his left ear round to you. 'Speak up on that side. The right's been no use since a Sister put a sting in it, twenty years back, the first week I came up here.' He pours you something without asking. 'Mead. Mine. It isn't as good as Huw Penry's up the Comb, and I'll tell you why before you ask: he's got the heather honey and I've got what he sells me. Bed's two coin. Welcome to the Wold.'".
    Greets again "Martin turns his good ear to you and reaches for a cup.".
  }
  Topic martin_wold with martin "Ask Martin about the Wold" when true {
    Says "'Up the gorge is the Comb, and in the Comb are the Humefolk, and the Sisters, and the honey.' He wipes the board. 'They're good people. Odd. They'll sell to you all day at the foot of the stair, but they won't have you up it unless you smell right; Elspet at the Scenting House'll do you for two coin, a day's worth. Don't let it run out up there.' He touches his deaf ear. 'And this week they're splitting the town in half and walking off with the old queen, so mind where you stand.'".
  }
  Topic martin_leaving with martin "Ask Martin about the Leaving" when not leavingBegun() {
    Says "'Every thirty, forty years. The old queen swarms and half of them go with her and never come back. Nobody's made to. They choose.' He looks at the door, at the handcarts going by. 'Families split down the middle. Husbands, wives. I saw the last one, my first year. A man and his wife stood on the Apron with their hands on each other's faces for an hour, and then he walked off after the bees and she went back up the stair.' He sets a cup down. 'It's the best week's trade Smoke End ever has. Make of that what you like. Crispin Polglaze at the Chandlers' yard is making something of it.'".
  }
  Topic martin_mead with martin "Ask Martin about Huw Penry's mead" when true once {
    Says "His face does something complicated. 'Huw Penry is the finest mead-maker in the Wold and the vainest man in it, and he's going with the Mother, and he's making one last mead for the Calling that'll be drunk at every Calling for thirty years, he says.' He turns a cup over, and back. 'I hear it's stuck. Stopped working in the barrel. Won't go.' Another cup turned. 'I'm not glad,' says Martin, who is a little glad. 'Somebody should tell him what'll start it. It won't be me. He'd sooner pour it in the stream than take a word from Smoke End.'".
    On discuss { Assert knows(actor, mead_stuck). }
  }
  Discovery mead_stuck "Huw Penry's mead for the Calling has stuck in the barrel and will not work.".

  // Hild Thorle, smith of smokers and veils.
  Person hild "Hild Thorle" at forge {
    Role "the smith of Smoke End: a broad dwarf woman in a leather apron, with a bee-veil pushed up on her head like a bonnet".
    Ancestry dwarf. Peaceable. Pronouns she. Manner jovial.
    Sells bee_smoker for 3 coin from 4.
    Sells bee_veil for 2 coin from 4.
    Sells sister_sting for 2 coin from 3.
    Greets "A dwarf woman looks up from a tin can she is riveting a spout onto. 'Smoker? Veil? Both? You'll want both, if you're going up. The scent's the thing, but scent wears off and smoke doesn't lie.' She hands you the can to admire. 'Three coin. And I pull stings, a coin a sting, if you come back down with any in you.'".
    Greets again "Hild waves a hammer at you.".
  }
  Topic hild_stings with hild "Ask Hild why she keeps the stings she pulls" when true once {
    Says "'Because they're worth more out than in.' She takes one out of a jar, in its paper, and sniffs it, and holds it under your nose: bananas, sharp and sweet. 'Smell that? That's what a Sister leaves when she stings. It means: here's a robber, come and help. Every Sister in a mile comes to that smell.' She folds the paper up. 'Rub one on a thing, and the Sisters will kill that thing, whatever it smells of underneath. The Waxwrights buy them to set the bees on the wild hives when they rob. Two coin.' She grins. 'Don't rub it on yourself.'".
    On discuss { Assert knows(actor, alarm_known). }
  }
  Discovery alarm_known "A Sister's sting carries a smell like bananas that calls every Sister near to kill whatever it is rubbed on, whatever that thing smells of underneath.".
  Topic hild_comb with hild "Ask Hild about the Comb" when true {
    Says "'Beautiful. Hot. Sticky. I went up once with my scent running thin and came down with eleven stings.' She shows you a wrist pocked with little white scars. 'Lowlanders think the Sisters are gentle because they're furry. They're gentle because they're full. Annoy one and you'll see what four hundred years of not needing to be gentle looks like.'".
  }

  // Nell Quarrie, perfumer: who was refused, and forged it.
  Person nell "Nell Quarrie" at nell_shop {
    Role "the perfumer of Smoke End: a tall woman in black, fifty, very upright, who smells faintly of the Comb".
    Ancestry human. Peaceable. Pronouns she. Manner proud.
    Sells nell_oil for 1 coin from 6.
    Greets "A tall woman in black looks up from a row of little bottles. The shop smells of roses, of resin, of musk, and under it all, faint and impossible, of warm wax and summer fields. 'Rosewater,' she says, 'lavender, attar, civet, and a few things of my own.' She watches you notice the smell under the smells. 'Yes,' she says, 'that too. One coin. Half a day.'".
    Greets again "Nell Quarrie inclines her head.".
  }
  Action anoint_nell(actor: group) "Anoint yourself with Nell Quarrie's oil" {
    Description "Half a day of smelling as if you belonged to the Comb.".
    Requires able(actor) and company(actor) and holding(actor, nell_oil) and not named(actor).
    Time 1 minute.
    On success { Spend nell_oil from actor. Set scentUntil(actor) to watch(clock) + 72. Assert anointed(actor). Assert usedNellOil(actor). }
    Result "You dab it at your throat and wrists and in your hair. For a moment you smell like a summer afternoon in the Comb; then you stop noticing, the way you stop noticing your own house.".
  }
  Relation usedNellOil(group).
  Measure nellTrust(group). Relation nellConfessed(group). Relation nellNamed(group). Relation nellBarred(group).
  Topic nell_oil_how with nell "Ask Nell Quarrie how she makes the oil that smells of the Comb" when not nellConfessed(nell) once {
    Says "'Carefully.' She does not smile. 'Six years of carefully. Heather oil, and wax, and propolis, and fourteen other things, and a great deal of standing at the foot of the stair with my eyes shut, smelling.' She sets a bottle straight on the shelf. 'It is not illegal. There is no law in the Wold about smelling of things. There is only Elspet Garnock.'".
    On discuss { Increase nellTrust(nell) by 1. }
  }
  Topic nell_aldo with nell "Ask Nell Quarrie why she learned to make it" when nellTrust(nell) >= 1 once {
    Says "She is quiet so long you think she will not answer. 'My husband was Aldo Quarrie, of the Comb. He came down to Smoke End to buy lavender for his mother and he stayed eleven years. When he was dying he wanted to go home, and I took him up the stair, and Elspet Garnock scented him, and would not scent me.' Her hands are quite still on the counter. 'He's capped in the Gallery. Fourth row from the arch, on the left. I asked to go up and sit with him the way the Humefolk sit with theirs. Three times. Elspet said I was not of the Comb.' Her eyes come up to yours, and stay. 'So I made myself of the Comb. Once a month, for six years, I have gone up the stair smelling of this, and sat with him an hour in the dark, and come down. Nobody has ever stopped me. Nobody has ever noticed.'".
    On discuss { Increase nellTrust(nell) by 1. Assert knows(actor, nell_forges). }
  }
  Discovery nell_forges "Nell Quarrie forges the Comb's scent, and has gone up the stair in it once a month for six years to sit with her dead husband Aldo in the Capped Gallery, because Elspet Garnock would not scent her.".
  Topic nell_sat_aldo with nell "Tell Nell Quarrie you sat a while with Aldo" when knows(actor, aldo_sat) and not nellConfessed(nell) once {
    Says "Something goes out of her shoulders. 'Fourth row,' she says. 'On the left.' You tell her what he looks like now: the brown coat, the hands, the little smile they all have. She nods at each thing. 'Yes. Yes.' Then she says, abruptly, as if it has been sitting in her mouth for a week: 'I made a thing I should not have. For the squire at Larkhill.'".
    On discuss { Increase nellTrust(nell) by 1. }
  }
  Topic nell_flask with nell "Ask Nell Quarrie what she made for the squire" when nellTrust(nell) >= 2 and not nellConfessed(nell) once {
    Says "'A flask.' She takes a breath. 'Not this,' the phials, 'but the thing itself. Strong. Stronger than the Mother smells to her own bees. Lucian Corve came here in the spring with his drawings and his letters and his good manners, and asked me if it could be done, and paid me forty crowns, and I did it, because it could be done, and because the Comb would not have me, and because forty crowns is forty crowns.' She looks at her hands. 'Uncorked on his tower, on the wind, it will call the swarm. It will call it whatever they dance. He means to open it on the fourth morning.' She straightens a phial that was straight. 'I hoped he would not. I hoped, when I gave it him, that he would turn out to be a man who would not.'".
    On discuss { Assert nellConfessed(nell). Assert knows(actor, flask_known). }
  }
  Discovery flask_known "Squire Corve of Larkhill has a flask of Nell Quarrie's making, stronger than the Mother's own scent, and means to uncork it on his tower on the fourth morning to call the swarm to his chantry, whatever the Searchers dance.".
  Topic nell_named with nell "Tell Nell Quarrie that Elspet Garnock will scent her" when nellNamed(nell) once {
    Says "She does not believe you, and then she does, and then she sits down on the stool behind her counter very suddenly, like a much older woman. 'Properly,' she says. 'Up the stair in daylight, like anybody.' She puts her hands over her face. When she takes them away she is smiling, which you have not seen her do. 'I shall go up tomorrow,' she says, 'and sit with him in the afternoon. In the afternoon! With the light coming down the arch.'".
  }
  Topic nell_barred with nell "Ask Nell Quarrie for the oil" when nellBarred(nell) once {
    Says "'There is no oil.' Her face is closed like a door. 'Elspet Garnock came down the gorge yesterday with two of the Hum-keepers and poured it in the stream, every phial, and put a mark on my door that the Comb reads, and told me that if I am found on the stair again the Sisters will be told what I am.' She looks at you without any expression at all. 'Somebody told her. I wonder who.'".
  }

  // Crispin Polglaze, factor of the Chandlers' Company, and the Leavers' Market.
  Person penhallow "Crispin Polglaze" at leavers_yard {
    Role "the factor of the Chandlers' Company: a pleasant, soft-voiced man in a black coat, with a boy and a slate".
    Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Buys wax_cake for 1 coin.
    Buys wild_comb for 2 coin.
    Buys fine_candles for 3 coin.
    Greets "The man in the black coat smiles at you, a real smile, sympathetic. 'Sad week,' he says. 'Sad week for them. They can't carry it, you see. The Leaving takes what it stands up in, and the ones staying have no money to buy it off them, because they never do, so it comes to us.' He gestures at the rows of wax and chests and cradles. 'We give them what we can.' What he can is one coin for a cake of wax that the Company sells in the lowland for six.".
    Greets again "Crispin Polglaze nods to you pleasantly.".
  }
  Topic penhallow_price with penhallow "Ask Crispin Polglaze what he pays" when true once {
    Says "'A fifth.' He does not lower his voice. 'Of the lowland price. Which sounds hard, I grant you, but consider: if I did not buy it, it would sit in the Comb till the stayers took it for nothing. A fifth of something is better than all of nothing.' He taps the boy's slate. 'And the Company has carriage to pay, and the risk, and my wage. I am not a bad man,' he says, as if you had asked. 'I am a price. Somebody has to be.'".
  }
  // The Drewes, going with the Mother, selling the best of what they made.
  Person drewes "the Drewes" at leavers_yard {
    Role "a family of chandlers of the Comb going with the Mother: a mother, a father, two girls, standing by a table of fine candles".
    Ancestry human. Numbers 4. Peaceable. Pronouns they.
    Greets "The mother of the family watches you look at the candles: tall, white, fluted, the best work you have seen. 'Thirty years of my mother's moulds,' she says. 'Master Polglaze says two coin the bundle.' She does not look at Master Polglaze.".
  }
  Relation drewesPaid(group). Relation drewesCheated(group).
  Item drewe_candles "a bundle of fluted Brow candles" is fine_candles at limbo.
  Action buy_drewes_cheap(actor: group, site: place) "Buy the Drewes' candles at the Leavers' price, two coin" {
    Speaker drewes.
    Requires at(actor, site) and able(actor) and at(actor, leavers_yard) and at(drewes, leavers_yard) and quantity(actor, gold) >= 2 and not drewesPaid(actor) and not drewesCheated(actor) and not leavingBegun().
    Time 1.
    On success { Decrease quantity(actor, gold) by 2. Give drewe_candles to actor. Assert drewesCheated(actor). }
    Result "The mother takes your two coins and puts them in her apron and hands you the candles, and says thank you, and does not look at you either.".
  }
  Action buy_drewes_fair(actor: group, site: place) "Pay the Drewes what the candles are worth, six coin" {
    Speaker drewes.
    Requires at(actor, site) and able(actor) and at(actor, leavers_yard) and at(drewes, leavers_yard) and quantity(actor, gold) >= 6 and not drewesPaid(actor) and not drewesCheated(actor) and not leavingBegun().
    Time 1.
    On success { Decrease quantity(actor, gold) by 6. Give drewe_candles to actor. Assert drewesPaid(actor). }
    Result "The mother looks at the six coins in her hand, and then at you, and then, for the first time, at Crispin Polglaze, who is looking at the sky. 'There,' she says to her daughters, and closes her hand. The younger girl says, 'Now we can have the goat,' and is hushed.".
  }

  // ── Smoke End, the week after ──────────────────────────────────────────────────────────────────────────────────
  // The street that sold veils and scent to the Searchers and wax-prices to the Leavers has, once the sky has gone brown
  // and come back, a good deal to say for itself, and each of its people says a different thing.
  Topic hild_after with hild "Ask Hild whether the Leaving has been good for trade" when leavingBegun() once {
    Says "Hild has the veil off her head and is turning it inside out, looking for a hole. 'Best week of my life and the worst,' she says. 'I sold forty smokers to people who will never need one again. Half the Comb has walked off with a smoker in its pack, and I am the one who will be asked for a spare by the half that stayed.' She finds the hole, and puts her thumb through it. 'They come down now and stand in the door and don't buy. They look at the stings in the jar. Then they say, how many, and I know somebody has died of being too fond.'".
  }
  Topic nell_after_named with nell "Ask Nell Quarrie how she found the stair by daylight" when leavingBegun() and nellNamed(nell) once {
    Says "'Cold,' says Nell Quarrie. 'He is colder than I thought, and drier, and the little smile they all have is a bit less than I told myself.' She is arranging bottles that do not need it. 'I sat the whole of the afternoon. With the light coming down the arch.' She turns a bottle to the window, and the light goes through it the colour of weak tea. 'I have stopped making the oil. I find I would rather smell of roses and know it.'".
  }
  Topic nell_after_barred with nell "Ask Nell Quarrie how she is, now the Comb is half empty" when leavingBegun() and nellBarred(nell) once {
    Says "'The mark is still on my door,' says Nell Quarrie. 'Nobody has come to see if I mind it.' She does not look at you. 'Half the Hum-keepers have gone with the Mother, and the half who stayed are the half who do not remember me, and I think Aldo is nearer than he has ever been.' A bottle rolls against another on the shelf, and she stops it with one finger. 'I am not going to climb that stair again. I am not sure that I shall not.'".
  }
  Topic nell_after_forger with nell "Ask Nell Quarrie what she makes now" when leavingBegun() and not nellNamed(nell) and not nellBarred(nell) once {
    Says "'The same.' She puts a finger on the cork of the nearest phial. 'Lavender for the lowland. A little of the Comb for anybody who asks nicely.' The corner of her mouth moves. 'The Leavers took bottles of it with them. They say a new comb smells of nothing at all for a season. They will want to smell of home.' She stoppers the phial. 'I never thought to be anyone's home.'".
  }
  Topic polglaze_after with penhallow "Ask Crispin Polglaze what the Company made of the week" when leavingBegun() once {
    Says "He is counting crocks, and the boy is counting after him, and neither has hurried. 'Eleven carts,' says Crispin Polglaze. 'To the lowland, on the south road, under oilcloth. Brow wax for the chandlers at the fair, honey for the monasteries, and a hundred and forty bundles of fluted candles that burn three nights, which will be in your inns by the first frost at nine times what I paid.' He is not smiling. 'There is a woman at an inn on the south road who will light one at her window and call it a Merrowdale candle, or a Corran candle, or nothing at all, because who would believe it came out of a hill under a cliff?' He straightens a crock. 'I am not a bad man. I have said so. It does not seem to carry.'".
  }
  Topic drewes_after with drewes "Ask the mother of the Drewes how the new comb sits" when leavingBegun() and drewesPaid(actor) once {
    Says "'The goat is in the lee of the wall,' she says, 'and the girls have named it Polglaze, which I have forbidden and shall not enforce.' She looks up at the half-built comb, at the first white sheets. 'We took the moulds, six dozen, wrapped in my mother's shawl. They will want waxing. They will want a year.' She smiles, which she did not do at the table. 'A year is quite a thing to want, after thirty.'".
  }
}

data/adventures/half-the-hive/stores.kyr:
Module hume "Half the Hive" {
  // ── Agnes Mellor, and the dark watch ──────────────────────────────────────────────────────────────────────────────
  // Tobit Mellor, the Capper who sealed the dead, was found dead in the Capped Gallery four mornings ago with his face
  // slack and the honey cells beside him empty. The Hum-keepers say his heart. By custom someone sits a night in the
  // dark with the dead before they are capped, without a light, because there is no flame among the Capped. Nobody will
  // sit with Agnes: there is something in the Gallery since Tobit died, they say. There is. It is a death's-head moth as
  // long as a man's arm, and it smells of the Mother, so the Sisters let it be, and it comes in the small hours to drink
  // the honey the dead are sealed with. It is nobody's plan. Nell Quarrie saw it the night Tobit died, and dropped a phial.
  Person agnes "Agnes Mellor" at mellor_cell {
    Role "the Capper's widow: a heavy, quiet woman with grey plaits and a mourning band of black wax on her wrist" when not leavingBegun().
    Role "the Capper's widow" when leavingBegun().
    Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Greets "A heavy grey woman is sitting on the end of the bed with her hands in her lap, the way people sit in a room where somebody has died. She looks up at you without much interest. 'If you're from the Hum-keepers, the answer's still the same,' she says. 'If you're not, sit down. Nobody sits down in here since Tobit.'".
    Greets again "Agnes looks up. 'Sit down.'".
  }
  Relation wantsTobit(group). Relation watchAgreed(group). Relation keptWatch(group). Relation agnesStays(group).
  Relation likenessGiven(group). Relation agnesFreed(group).
  Initially Assert wantsTobit(agnes).
  Topic agnes_tobit with agnes "Ask Agnes how Tobit died" when true once {
    Says "'In the Capped Gallery. In the night. He went up to see to old Mother Rook's seal, which was weeping, and he didn't come down, and they found him in the morning by the wall, sitting, with his face,' she says, and stops. 'Slack. Like a child's, asleep. Except his eyes were open.' She turns her mourning band round on her wrist. 'And the cells beside him, the honey cells under the seals, empty. Licked out. The keepers say his heart. Sixty-one, and up and down that stair forty times a day, and his heart.' She reaches into her apron and holds something out on her palm. 'This was by his hand. It isn't his. I don't know what it is.'".
    On discuss { Give agnes_phial to actor. Assert knows(actor, phial_found). }
  }
  Item agnes_phial "a little phial Agnes found" is found_phial at limbo.
  Discovery phial_found "By Tobit Mellor's body in the Capped Gallery, Agnes found a little empty phial that smells of the Comb, not quite.".
  Topic agnes_watch with agnes "Ask Agnes about the dark watch" when not keptWatch(actor) once {
    Says "'The night before you're capped, someone sits with you. In the Gallery, in the dark, no light, because there's no flame among the Capped: one candle up there and four hundred years of us go up like a hayrick.' She looks at her hands. 'Tomorrow they cap him, or the day after, whenever I've sat. I can't sit alone; it's not done. And nobody'll sit with me.' Her mouth goes thin. 'They say there's something up there since he died. Something in the dark that smells of the Mother. Children's talk.' She looks at you. 'You're not a child.'".
  }
  Topic agnes_offer with agnes "Offer to sit the dark watch with Agnes tonight" when not watchAgreed(agnes) and not keptWatch(actor) and not leavingBegun() once {
    Says "Agnes counts something on the fingers of one hand. 'Tonight,' she says. 'At ten, in the Gallery. No light. You'll not need one; you sit where you're put and you don't move.' She almost smiles. 'You talk to him, if you like. I do.'".
    On discuss { Assert watchAgreed(agnes). }
  }
  Topic agnes_going with agnes "Ask Agnes whether she will go with the Leaving" when not leavingBegun() once {
    Says "'I was always going to go. Tobit and me both. We'd said, when it came, we'd go together and start again somewhere with a view.' She is quiet. 'He's going to be capped in that wall with four hundred years of strangers, and I'm going to walk off over the Wold and never see him again. That's the custom. The dead stay.' She looks up. 'I want to take him. Capped, in his wax, on a litter. Linnet says no. Everyone says no. It's never been done.' Her hands close. 'I'll not leave him alone up there with whatever it is that's in the dark.'".
  }
  Topic agnes_nell with agnes "Tell Agnes the phial was Nell Quarrie's, and that Nell sat with Tobit the night he died" when knows(actor, nell_sat_tobit) and not agnesVouches(agnes) once {
    Says "'Nell Quarrie.' Agnes says the name slowly. 'Aldo's widow. From Smoke End.' She takes it in. 'Tobit capped Aldo. Six years ago. He cried doing it; he was fond of Aldo. He said it was a shame about the wife, that Elspet wouldn't have her.' She is silent. 'And she was up there. In the dark, with nobody knowing, and she found him, and she sat with him till it got light.' Agnes wipes her face with the flat of her hand, roughly. 'Somebody sat with him, then. Somebody did.' She stands up. 'You tell Elspet Garnock that Agnes Mellor says Nell Quarrie is more of the Comb than Elspet is. Tell her I said it.'".
    On discuss { Assert agnesVouches(agnes). }
  }
  Topic agnes_likeness with agnes "Give Agnes the wax likeness Eben made of Tobit" when holding(actor, tobit_likeness) and not likenessGiven(agnes) once {
    Says "She takes it in both hands: a little figure as long as her forearm, white and gold, Tobit in his capping apron with his sleeves rolled, his head a little on one side the way he must have stood. She turns it to the light. 'That's him,' she says. 'That's exactly how he stood when he was waiting for me to stop talking.' She wraps it in her shawl and puts it in the bundle by the door, on top. 'I'll take this, then,' she says. 'And he can stay.'".
    On discuss { Spend tobit_likeness from actor. Assert likenessGiven(agnes). }
  }
  Topic agnes_go_free with agnes "Tell Agnes the thing in the Gallery is dead, and Tobit is safe to leave" when mothDead(deathshead) and knows(actor, moth_heard) and not agnesFreed(agnes) once {
    Says "She looks at the bundle by the door, and at the unpacked half of the room. 'Safe,' she says. 'In the wall, with the others, and nothing coming in the dark.' She gets up and begins, slowly, to pack the other half. 'He'd want me to go. He'd say, go on, woman, you've always wanted a view.' She folds his spare apron and puts it in, and then takes it out again and leaves it on the bed.".
    On discuss { Assert agnesFreed(agnes). }
  }
  Topic eben_likeness with eben "Ask Eben to carve a likeness of Tobit Mellor for Agnes to carry" when not leavingBegun() and wantsTobit(agnes) and holding(actor, wax_cake) and not holding(actor, tobit_likeness) and not likenessGiven(agnes) once {
    Says "'Tobit.' Eben puts down his blade. 'I can do Tobit. I've done him on the Stair: fourth turn, with the sealing-iron.' He takes your cake of wax and warms it in his hands. 'Give me an hour.' It is less than an hour. When he gives it to you it is still warm.".
    On discuss { Spend wax_cake from actor. Give tobit_figure to actor. }
  }

  Item tobit_figure "a wax likeness of Tobit Mellor" is tobit_likeness at limbo.
  // The watch: Agnes goes up at ten on the night agreed, and sits till first light.
  Rule agnes_to_gallery when watchAgreed(agnes) and not keptWatch(party) and (hour(clock) >= 22 or hour(clock) < 5) and not at(agnes, capped_gallery) and not leavingBegun() { Assert at(agnes, capped_gallery). }
  Action sit_watch(actor: group, site: place) "Sit down beside Agnes in the dark, and keep the watch" {
    Description "No light. You sit where you are put, and you do not move, until something changes.".
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, capped_gallery) and at(agnes, capped_gallery) and watchAgreed(agnes) and not keptWatch(actor) and not at(deathshead, capped_gallery) and (hour(clock) >= 22 or hour(clock) < 4).
    Time 6.
    Interrupted when at(deathshead, capped_gallery).
    Result "You sit. The dark is complete. After a while you can hear the dead, or think you can: the wax ticking as the night cools, a long way back in the rows. Agnes talks to Tobit. You do not move.".
  }
  Rule agnes_home when at(agnes, capped_gallery) and hour(clock) >= 5 and hour(clock) < 22 { Assert at(agnes, mellor_cell). }
  Rule watch_kept_lit at capped_gallery when watchAgreed(agnes) and at(party, capped_gallery) and at(agnes, capped_gallery) and hour(clock) >= 4 and hour(clock) < 5 and not keptWatch(party) and lightAmongCapped(party) says "The grey comes at the arch. Agnes Mellor gets up stiffly off her stool and puts her palm flat on the wax in front of Tobit's face. 'Somebody sat,' she says to him. 'With a light, among them all. But sat.' She does not look at you." { Assert keptWatch(party). }
  Rule watch_kept at capped_gallery when watchAgreed(agnes) and at(party, capped_gallery) and at(agnes, capped_gallery) and hour(clock) >= 4 and hour(clock) < 5 and not keptWatch(party) says "The dark goes grey at the arch, and then you can see your hands. Agnes Mellor gets up stiffly off her stool and puts her palm flat on the wax in front of Tobit's face, the way you would on a door, and holds it there. 'There,' she says to him. 'Somebody sat.'" { Assert keptWatch(party). }
  Rule watch_missed when watchAgreed(agnes) and not at(party, capped_gallery) and hour(clock) >= 4 and hour(clock) < 5 and at(agnes, capped_gallery) and not keptWatch(party) { Retract watchAgreed(agnes). }
  Observe agnes_talks at capped_gallery as sound when at(agnes, capped_gallery) and night() "Beside you in the dark Agnes is talking to Tobit, low and steady, the way you talk to someone across a kitchen: the goat has got into the beans again; the roof over the loom wants seeing to; their boy in Ketter has not written; whose turn it is to fetch water. She leaves gaps for him to answer.".

  // Tobit, waiting; and Aldo, fourth row on the left.
  Thing tobit_bier "Tobit Mellor on his bier" at capped_gallery {
    State waiting "Nearest the arch, on a trestle, under a sheet of muslin, a stocky man lies waiting to be capped, his hands folded on a sealing-iron.".
    State capped "In the newest place in the wall, nearest the arch, a stocky man stands in clear wax with a sealing-iron in his hands.".
  }
  Rule tobit_capped when keptWatch(party) and state(tobit_bier, waiting) and hour(clock) >= 9 and not linnetPermitsDead(linnet) { Assert state(tobit_bier, capped). }
  Thing aldo_capped "Aldo Quarrie, fourth row on the left" at capped_gallery hidden until nell_forges {
    State kept "Fourth row from the arch, on the left, a man in a brown lowland coat with a sprig of lavender in his buttonhole, smiling a little, as they all do.".
  }
  Action sit_aldo(actor: group, site: place) "Sit a while with Aldo Quarrie" {
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, capped_gallery) and knows(actor, nell_forges) and not knows(actor, aldo_sat).
    Time 3.
    On success { Assert knows(actor, aldo_sat). }
    Result "You find a stool and sit in front of him. Up close the lavender in his buttonhole is still purple, sealed in with him. His face is a kind face, long, with laughter-lines, and there is a small worn place on the floor in front of him, where a stool has stood, once a month, for six years, in the dark.".
  }
  Discovery aldo_sat "You sat a while in the Capped Gallery with Aldo Quarrie, fourth row on the left: a kind long face, a lavender sprig, and a worn place on the floor where a stool has stood once a month for six years.".

  // ── The thing in the dark ─────────────────────────────────────────────────────────────────────────────────────────
  Species deathshead_kind "a death's-head moth" like nightmare temperament savage described "A moth as long as a man's arm, its body thick and furred and banded yellow and black like a Sister's, its wings brown as a dead leaf; and on its back, in pale fur, a skull. It smells, overwhelmingly, of the Mother.".
  Person deathshead "the Deathshead" at limbo {
    Role "a death's-head moth as long as a man's arm, with a skull in pale fur on its back".
    Species deathshead_kind. Level 2. Peaceable.
    Known as "something in the dark" when not mothSeen(party).
    Comes "It comes at the light. A shape the size of a dog, soft and fast, out of the rows of the dead, wings rattling like dry paper, and on its back, lit from below, a skull; and it squeals, a high thin sound like a wet finger on glass, so loud and so close it goes into your teeth.".
  }
  Relation mothDead(group). Relation mothSeen(group). Relation mothPassed(group). Relation lightAmongCapped(group).
  Discovery moth_heard "Something comes into the Capped Gallery in the small hours that smells of the Mother so the Sisters let it be, that squeaks, and that drinks the honey from the seals of the dead: a death's-head moth as long as a man's arm.".
  Rule gallery_dark when night() and not unlit(capped_gallery) { Assert unlit(capped_gallery). }
  Rule gallery_dim when not night() and unlit(capped_gallery) { Retract unlit(capped_gallery). }
  Rule moth_in when hour(clock) >= 1 and hour(clock) < 4 and not mothDead(deathshead) and able(deathshead) and not at(deathshead, capped_gallery) { Assert at(deathshead, capped_gallery). }
  Rule moth_out when at(deathshead, capped_gallery) and (hour(clock) >= 4 or hour(clock) < 1) and peaceable(deathshead) { Assert at(deathshead, limbo). }
  Observe moth_sound at capped_gallery as sound when at(deathshead, capped_gallery) and peaceable(deathshead) "In the dark, among the rows, something is moving: a soft dry pattering, like a hand brushing a wall, coming nearer, and a smell of the Mother so strong your eyes water. It stops. Close by, at the wax, something squeaks, high and thin, like a wet finger on glass, and then there is a small wet sound, like sucking. Whatever it is, it is drinking from the seals of the dead, and the Sisters on the walls do not stir for it. It smells of home to them." teaches moth_heard.
  Rule moth_lit at capped_gallery when at(deathshead, capped_gallery) and at(party, capped_gallery) and capable(party, light) and peaceable(deathshead) {
    Retract peaceable(deathshead). Assert assails(deathshead, party). Assert mothSeen(party). }
  Rule light_among when at(party, capped_gallery) and capable(party, light) and night() and at(agnes, capped_gallery) and not lightAmongCapped(party) says "'No,' Agnes says, aloud, appalled, the first thing she has said above a whisper. 'Not here. Not among them.'" { Assert lightAmongCapped(party). }
  Rule moth_seen_teaches when mothSeen(party) and not knows(party, moth_heard) says "It was a moth. A death's-head moth as long as your arm, that smells of the Mother, so the Sisters let it be; and it drinks from the seals of the dead." teaches moth_heard { }
  Rule moth_slain when not able(deathshead) and not mothDead(deathshead) { Assert mothDead(deathshead). }
  Action rub_sting(actor: group, site: place) "Reach out in the dark and rub the Sister's sting on the thing at the wax" {
    Description "It smells of the Mother. Make it smell of a robber.".
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, capped_gallery) and at(deathshead, capped_gallery) and peaceable(deathshead) and holding(actor, sister_sting) and not mothDead(deathshead).
    Time 1 minute.
    Resolve check(actor, stealth, dc_fair).
    On success { Spend sister_sting from actor. Assert mothDead(deathshead). Assert mothSeen(actor). Assert knows(actor, moth_heard). Assert at(deathshead, limbo). Give moth_wing to actor. }
    On failure { Spend sister_sting from actor. Retract peaceable(deathshead). Assert assails(deathshead, actor). Assert mothSeen(actor). }
    Result "You unfold the paper by feel, and the smell of bananas comes up sharp in the dark, and you lean toward the sucking sound and reach, slowly, slowly, and your fingers meet fur: thick, soft, warm, the size of a dog's back. You draw the sting down it. For a heartbeat nothing. Then every Sister on every wall of the Gallery goes up at once with a roar like a furnace door opened, and the dark is full of wings, and something squeals and squeals and squeals in the middle of it, and the squealing stops. When the grey comes at the arch there is a wing on the floor, brown as a dead leaf, with a pale eye on it, and nothing else.".
    Otherwise "Your fingers find fur, and it feels them: the sucking stops, there is a dry rattle of wings, and something squeals in your face.".
  }
  Item moth_wing "a death's-head moth's wing" is deathshead_wing at limbo.
  Action keep_still(actor: group, site: place) "Keep still in the dark, and let it pass" {
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, capped_gallery) and at(deathshead, capped_gallery) and peaceable(deathshead) and not mothPassed(actor).
    Time 6.
    On success { Assert mothPassed(actor). Assert knows(actor, moth_heard). }
    Result "You keep still. It goes along the rows, slowly, stopping, drinking. Once it passes so close behind you that its wing touches the back of your neck, soft and dry as ash, and the smell of the Mother is so strong you could weep. Beside you Agnes's hand finds your wrist and holds it, very hard. Then it is further away, and further, and gone.".
  }
  Observe tobit_drained at capped_gallery when mothPassed(party) and state(tobit_bier, waiting) and not night() "On the sheet over Tobit Mellor's hands there are small brown marks, like footprints of dust, and the honey-wax on his sealing-iron has been licked clean.".

  // Nell's night.
  Topic nell_night with nell "Ask Nell Quarrie whether she was in the Capped Gallery the night Tobit Mellor died" when knows(actor, phial_found) and knows(actor, nell_forges) and not knows(actor, nell_sat_tobit) once {
    Says "She does not pretend. She has been waiting for someone to ask. 'Yes. It was my night.' She sits down. 'I was with Aldo. In the dark. And Tobit came up with a little lamp, which they never do, to see to a seal that was weeping, and I heard him stop, and say, What are you? Very surprised. And then there was a noise.' Her hands tighten. 'A squeal. And I saw, by his lamp, before it went over, a moth. As long as my arm. On the wall over him, with its wings open. It had a face on its back. A skull.' She breathes. 'Then the lamp was out. I went to him in the dark. He was sitting against the wall, and he was dead, and it was drinking, beside us, at the seals. It smelt of the Mother. It smelt like me.' Her mouth works once, over nothing. 'I closed his eyes. I sat with him until it went away and the arch went grey, and then I ran, because if I was found there they would have said I did it, the lowland woman in the forged scent. I dropped a phial. I have been waiting for someone to come and ask me about it ever since.'".
    On discuss { Assert knows(actor, nell_sat_tobit). Assert knows(actor, moth_heard). }
  }
  Discovery nell_sat_tobit "Nell Quarrie was in the Capped Gallery the night Tobit Mellor died: she saw a death's-head moth as long as her arm squeal over him, sat with his body in the dark until dawn, closed his eyes, and fled.".

  // ── Huw Penry's mead ──────────────────────────────────────────────────────────────────────────────────────────────
  Person huw "Huw Penry" at honey_vaults {
    Role "the Comb's mead-maker: a big man with a magnificent beard and a voice he uses to its full extent, among his barrels".
    Ancestry human. Peaceable. Pronouns he. Manner proud.
    Greets "A big bearded man among the barrels turns round with his arms out as if you had come to his wedding. 'A stranger! A lowlander! Have you ever tasted mead? You have not. You have tasted what Martin Sayle sells in Smoke End, which is honey-water that has had a fright.' He thumps a barrel. 'This is mead.' He lowers his voice. 'Not this one.'".
    Greets again "Huw Penry flings his arms out. 'Back for more!'".
  }
  Relation meadSaved(group). Relation meadSecret(group). Relation huwRefused(group).
  Topic huw_mead with huw "Ask Huw about his mead for the Calling" when not meadSaved(huw) and not leavingBegun() {
    Says "'My last.' He lays a hand on the biggest barrel. 'Heather honey off the moor, lime honey off the wood, water from the Brow spring, and forty years of knowing. It'll be drunk at the Calling, and they'll keep a cask of it to drink at every Calling after, for thirty years, and say: Penry made that, the year he went.' His hand stays on the barrel. Then, quietly, all the voice gone out of him: 'It's stopped. It was working, and it stopped. Eight days now. It just sits there, sweet, and won't go.' He looks at you with real despair. 'Forty years and it's never happened.'".
    On discuss { Assert knows(actor, mead_stuck). }
  }
  Topic martin_fix with martin "Ask Martin what would start a stuck mead" when knows(actor, mead_stuck) and not knows(actor, bread_fix) once {
    Says "'Bee-bread,' says Martin at once, and then looks as if he wished he had not. 'A fist of it, crumbled in. The yeast's hungry, honey's not enough for it; it wants feeding. Any brewer in the lowland knows that.' He polishes a cup that does not need it. 'Doll Rowntree on the Apron sells it by the loaf. Huw'd know it himself if he ever listened to anybody.' He sets the cup down. 'Don't tell him it came from me.'".
    On discuss { Assert knows(actor, bread_fix). }
  }
  Discovery bread_fix "A fist of bee-bread crumbled into a stuck mead feeds the yeast and starts it working again; any lowland brewer knows it, and Martin Sayle told you.".
  Action tell_huw(actor: group, site: place) "Tell Huw that a fist of bee-bread will start his mead" {
    Speaker huw.
    Requires at(actor, site) and able(actor) and at(actor, honey_vaults) and at(huw, honey_vaults) and knows(actor, bread_fix) and not meadSaved(huw) and not huwRefused(huw).
    Time 1.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert meadSaved(huw). }
    On failure { Assert huwRefused(huw). }
    Result "Huw Penry stares at you. Then he stares at the barrel. 'Bee-bread,' he says, 'is for babies and the sick.' But he goes and gets a loaf, and stands weighing it, and crumbles in a fistful, like a man throwing away his own good name. By evening the barrel is talking to itself, and Huw is telling everyone in the vaults that it came to him in the night.".
    Otherwise "'Bee-bread!' Huw Penry's voice fills the vaults. 'In my mead! Is that what they do down in Smoke End? Is that Martin Sayle's notion?' He turns his back on you and will not hear another word.".
  }
  Action trick_huw(actor: group, site: place) "Tell Huw that the old mead-masters of the Comb swore by bee-bread in a stuck barrel" {
    Speaker huw.
    Requires at(actor, site) and able(actor) and at(actor, honey_vaults) and at(huw, honey_vaults) and knows(actor, bread_fix) and not meadSaved(huw).
    Time 1.
    Resolve check(actor, deception, dc_fair).
    On success { Assert meadSaved(huw). }
    Result "You tell him you heard it from the Waxwrights, who heard it from their grandfathers: that the old masters of the Comb, in the days before anybody wrote anything down, would crumble a fist of bee-bread into a sulking barrel. Huw Penry's eyes go wide. 'The old masters,' he says reverently. 'Of course. Of course they did. Lost knowledge.' He has a loaf in the barrel before you have finished, and by evening it is working, and he is telling everyone that he rediscovered it.".
    Otherwise "Huw narrows his eyes. 'What old masters? I knew the old masters. My master was the old master.' He turns his back.".
  }
  Rule huw_sleeps when (hour(clock) >= 22 or hour(clock) < 6) and at(huw, honey_vaults) { Assert at(huw, limbo). }
  Rule huw_wakes when hour(clock) >= 6 and hour(clock) < 22 and at(huw, limbo) and not leavingBegun() { Assert at(huw, honey_vaults). }
  Thing mead_barrel "Huw Penry's great barrel" at honey_vaults {
    State stuck "The biggest barrel in the vaults, chalked PENRY · CALLING, sits silent: put your ear to it and there is nothing.".
    State working "The biggest barrel in the vaults, chalked PENRY · CALLING, is muttering and ticking to itself, and smells of summer.".
  }
  Initially Assert suits(mead_barrel, listening).
  Rule mead_works when meadSaved(huw) and state(mead_barrel, stuck) { Assert state(mead_barrel, working). }
  Action slip_bread(actor: group, site: place) "Crumble a loaf of bee-bread into Huw's barrel while he sleeps" {
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, honey_vaults) and not at(huw, honey_vaults) and holding(actor, bee_bread) and not meadSaved(huw).
    Time 1.
    On success { Spend bee_bread from actor. Assert meadSaved(huw). Assert meadSecret(huw). }
    Result "You prise the bung, and crumble the loaf in, and knock the bung home with the heel of your hand, and go. By morning the barrel is ticking like a clock, and Huw Penry is on his knees beside it with his ear to the staves, weeping into his beard and telling it that he always knew.".
  }
}

data/adventures/half-the-hive/turning.ky:
Module hume "Half the Hive" {
  // ── The flight, and the Turning-out ───────────────────────────────────────────────────────────────────────────────
  // Two days after the Leaving the new queen flies from the Toot, and the Escort walks behind her up the hill in yellow;
  // at dusk the Escort is taken down to Smoke End with a cloak and a loaf apiece and pointed at the lowland. Ivo is among
  // them unless he is a Searcher, or with the company, or gone with the Leaving.
  Relation flown(group). Relation turnedOut(group).
  Rule flight when flightDay() and hour(clock) >= 10 and not flown(escort) { Assert flown(escort). Assert at(escort, toot). }
  Rule flight_seen at toot when flown(escort) and at(party, toot) and not spread(flight_seen) says "Up the Toot in the morning sun comes the Escort, a dozen men and women in their best yellow, walking in pairs, very slowly, very upright, singing something old with no words; and ahead of them, walking too, in the grass, a long gold shape with her new wings folded: the queen. At the standing stone they stop and stand round it in a ring. She climbs the stone. She stands on the top of it, trembling, with her wings opening and closing. Then she goes up, straight up, into the blue, faster than you would believe, and is a speck, and is nothing; and from all over the Toot, out of the air, out of nowhere, comes the deep rich droning of a thousand drones going up after her. The Escort stand round the stone with their faces turned up, admiringly, as they were born to, until there is nothing left to look at." { Assert spread(flight_seen). }
  Rule flight_heard when flown(escort) and within(party, hume_brow) and not spread(flight_seen) says "From up the Toot comes singing, old and wordless, and then a sound like the whole sky humming, and then quiet." { Assert spread(flight_seen). }
  Entity flight_seen: fact "the wedding flight".
  Rule turning_out when flightDay() and hour(clock) >= 18 and not turnedOut(escort) { Assert turnedOut(escort). Assert at(escort, smoke_street). }
  Rule ivo_turned when turnedOut(escort) and not ivoSearcher(ivo) and not travelsWith(ivo, party) and not goes(ivo) and not ivoTurnedOut(ivo) { Assert ivoTurnedOut(ivo). Assert at(ivo, drove_end). }
  Rule turning_seen at smoke_street when turnedOut(escort) and at(party, smoke_street) and not spread(turning_seen) says "At dusk they bring the Escort down the gorge. Not roughly: Elspet Garnock walks in front with her staff, and two of the Hum-keepers walk behind, and between them come the yellow coats, a dozen of them, blinking, dusty from the Toot. At the end of the street, where the drove road begins, Elspet gives each of them a brown cloak and a round loaf, and says the same words to each, which are thank you; and turns round; and walks back up the gorge without looking back, because that is the custom. The Escort stand at the end of the street of Smoke End in their yellow coats with their loaves under their arms, looking down the drove road at the lowland going blue in the dusk. One of them starts to laugh, and stops. Martin Sayle comes out of the Smoker's Rest and stands in his doorway, and says, 'Well, come in, then, the lot of you. First night's on the house. It always is.'" { Assert spread(turning_seen). }
  Entity turning_seen: fact "the Turning-out".
  Observe escort_out at smoke_street when turnedOut(escort) and at(escort, smoke_street) "A dozen people in dusty yellow coats sit along the bench outside the Smoker's Rest with brown cloaks over their knees, eating their loaves very slowly.".
  Observe ivo_at_edge at drove_end when ivoTurnedOut(ivo) and at(ivo, drove_end) "Where the turf meets the hedges a tall man in a dusty yellow coat is sitting on a milestone with a loaf on his knee, looking down the road.".
  Rule escort_remark when ivoTurnedOut(ivo) and at(party, drove_end) and at(ivo, drove_end) and not spread(escort_remark) says "Ivo Gildersleeve looks up from his milestone and lifts his loaf to you in salute. 'Turned out,' he says. 'With a cloak. They give you a cloak, did you know? Nobody tells you about the cloak.'" { Assert spread(escort_remark). }
  Entity escort_remark: fact "Ivo on the milestone".
  // A Searcher is paid; the Escort is fed. A Searcher is not turned out.
  Rule ivo_kept at smoke_street when turnedOut(escort) and ivoSearcher(ivo) and at(party, smoke_street) and not goes(ivo) and not spread(ivo_kept) says "Ivo is not among them. When Elspet reached his name on her slate at the Toot, there was a boy at her elbow, out of breath, sent back across the Wold by Kestrel Dunn with four words: Searcher. Paid. Strike it. And Elspet looked at the boy a long time, and struck it." { Assert spread(ivo_kept). }
  Entity ivo_kept: fact "Ivo kept".
}

data/adventures/half-the-hive/wake.kyr:
Module hume "Half the Hive" {
  // ── The Account, kept: what each of a company sees, and the seventh Leaving's last page ───────────────────────────────
  // The Brow's count is its Leavings: six it remembers, a seventh it does not say. Whoever keeps the Comb's account (the
  // Cappers, once; Tobit Mellor, lately) was handed the book without its first page, and the Wold has been quietly
  // lying about one line of it for eighty-one years. Everything below is what a company of several callings finds when
  // it goes looking, and none of it is on the road to any ending.

  // ── Voices: the company, by what it is ───────────────────────────────────────────────────────────────────────────────
  Relation heardRows(group). Relation heardKnoll(group). Relation heardBeam(group). Relation heardSett(group). Relation heardWalls(group).

  Rule voice_rows at capped_gallery when memberOf(?m, party) and hasCalling(?m, calling_cleric) and awake(?m) and at(party, capped_gallery) and not heardRows(party)
    says "{?m} stops at the end of the first row and does not go on. 'Standing,' {?m} says, low. 'In every office I know the dead are laid down, because the dead are resting. These are kept on their feet with their hands folded, like people in a room waiting to be called.' {?m} looks along the clear wax, four hundred years of it. 'Whoever made this custom did not think death was a rest. Who says the words over them? Somebody must; the hands are all done the same way.'" {
    Assert heardRows(party).
  }
  Rule voice_knoll at gallow_knoll when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, gallow_knoll) and not heardKnoll(party)
    says "{?m} walks the foot of the knoll once, slowly, head down, and stops where the turf is a different green. 'A cart-road,' {?m} says. 'Under the grass, going east. Iron tyres, eighty years of rain filling the ruts.' {?m} follows it a hundred paces to a bank of turf, where it ends. The wheels did not turn round there. The cart was tipped over the bank and left, and the only way back is a line of footprints, small ones, one person's, going the other way to the tree. 'Somebody made a road that goes east and stops,' {?m} says. 'And then walked home along the side of it so as not to spoil it. I'd say it was made to be found, by anyone who came looking for where they'd gone.'" teaches east_staged {
    Assert heardKnoll(party).
  }
  Discovery east_staged "Eighty-one years ago someone made a cart-road east from the Gallowtree that ends at a bank where a cart was tipped over, and walked back alone along the edge of it: the seventh Leaving's 'gone on east' was laid on the ground, by a small foot, to be found.".
  Rule voice_beam at leavers_yard when memberOf(?m, party) and hasCalling(?m, calling_thief) and awake(?m) and at(party, leavers_yard) and not heardBeam(party)
    says "{?m} drifts along the rows to the weighing-beam, as if looking at the cradles, and runs a thumbnail under the near pan. 'Filed,' {?m} says, not moving the lips. 'Underneath, where the stamp doesn't cover. Four strokes, fresh bright metal. That pan weighs light by a sixth, and the Measures' mark above it says it has been proved.' {?m} moves on to a chest and admires it loudly. 'Don't look at him. Look at the chests. We'll have to decide what to do about the Drewes.'" teaches beam_filed {
    Assert heardBeam(party).
  }
  Discovery beam_filed "The near pan of the Chandlers' weighing-beam in the Leavers' Market has been filed underneath, four fresh strokes, so that it weighs light by a sixth beneath the Collegium of Measures' stamp.".
  Rule voice_sett at sett_mouth when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and at(party, sett_mouth) and not heardSett(party)
    says "{?m} lays a hand flat against the highest of the grooves, well above {?m}'s own head, and measures it with the span of the other. 'She stood to this,' {?m} says. 'Sow, on her back legs, to scratch. That puts the first blow at the height of a man's neck, and a boar-spear's reach is no more than hers.' {?m} takes the hand away and looks at the dark mouth. 'Moss is nineteen and it is a very good spear,' {?m} says. 'I would not go in there with a spear for anything that could be had by some other road.'" {
    Assert heardSett(party).
  }
  Rule voice_walls at dancing_hall when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, dancing_hall) and not heardWalls(party)
    says "{?m} tips an ear to the slope while the Searchers argue, and then hums a little under the breath, a figure and a loop and a figure and a loop, to see how it goes. 'It scans,' {?m} says, surprised. 'Every dance on this wall is the same measure: a run, a waggle, a loop, a rest of one breath. The old ones are cut deep and the new ones shallow, but the breath is always in the same place.' {?m} walks down to the lowest marks, by the door, where the children's hands reach. 'Count them. Six of these are a song. The seventh has had its breath taken out.'" {
    Assert heardWalls(party).
  }

  // ── The seventh run, on the wall of the Dancing Hall ───────────────────────────────────────────────────────────────
  // Foreshadow, in plain sight; and its payoff, for whoever has been to the Gallowtree and comes back to look.
  Observe seventh_run at dancing_hall as feature when not leavingBegun() and not knows(party, lost_leaving) "Low by the door, where the wax is smoothed by children's hands, the oldest dances are cut. Seven long runs, each ending in a place: you can read the Far Brow in the sixth, by its handprints. The seventh runs out east, farther than all the rest, and ends in a smear, as if someone wiped it out with a thumb while it was still soft.".
  Observe seventh_run_read at dancing_hall as feature when knows(party, lost_leaving) "Low by the door, the seventh run. Knowing where to look you can read under the smear: the line did not go east at all. It was cut west, two hours, a short run to a tree, and a hand has turned it round and dragged it out long, east, with a thumb, and then wiped the end. The hand that did that knew exactly what the first line said.".

  // ── The Cappers' board ─────────────────────────────────────────────────────────────────────────────────────────────
  Observe cappers_board at capped_gallery as feature when not knows(party, merrit_found) "Beside the board that forbids flame, another is pegged, with names burnt into it in a column, one beneath another: the Cappers of the Brow, by their years. Six are cut clean. The seventh place is smooth wax, rubbed flat with a thumb, with nothing on it at all; the eighth is Tobit Mellor, and a long line of Mellors below.".
  Observe cappers_board_read at capped_gallery as feature when knows(party, merrit_found) "Beside the board that forbids flame, the Cappers' names in their column. Six are cut clean. In the seventh place, knowing what to feel for, you press your thumb into the smooth wax and under it, small and square, you find it: M. COKE. Somebody smoothed it over, carefully, not to destroy it, and the Cappers have kept the board that way, a name shut under wax, for eighty-one years.".

  // ── Capping Merrit Coke ────────────────────────────────────────────────────────────────────────────────────────────
  // The one by the door was never capped, because nobody was left to do it. A company that has a cleric can say the
  // Capper's office over her, and must decide in what wax: the seventh Leaving's own white comb, or Brow wax. The white
  // is the only white in the Wold, and Eben Candlish's Stair wants it. Neither choice can be taken back.
  Relation merritCapped(group). Relation merritWhite(group). Relation merritBrow(group).
  Action cap_merrit_white(actor: group, site: place, c: member) "Say the Capper's office over Merrit Coke, and cap her in the seventh Leaving's own white comb" {
    Description "{c} knows the words. The white is the first wax they drew, and it is the only white in the Wold; Eben's Lantern Stair wants it too.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gallow_hollow) and knows(actor, merrit_found) and holding(actor, white_wax)
      and memberOf(c, actor) and hasCalling(c, calling_cleric) and not merritCapped(actor).
    Time 4.
    Grave "Once Merrit is capped in the white, the Lantern Stair cannot have it; and she cannot be uncapped.".
    On success { Spend white_wax from actor. Assert merritCapped(actor). Assert merritWhite(actor). }
    Result "{c} says it plainly, in the voice for the dead, standing by the door where the bones sit against the wall; and it is not an office you have heard, but it has a shape you know: a name, a place, a thanks. You warm the white comb in your hands until it takes the shape of a shell, and {c} sets it over her, and seals the edge with Merrit's own iron. She stands up. She stands with her hands folded, clear in the white, the colour of milk with the light behind it, with a little space left in the lap where something small was.".
  }
  Action cap_merrit_brow(actor: group, site: place, c: member) "Say the Capper's office over Merrit Coke, and cap her in a cake of Brow wax" {
    Description "{c} knows the words. Brow wax is the Brow's: it will make her the Brow's, after eighty-one years of nobody's.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gallow_hollow) and knows(actor, merrit_found) and holding(actor, wax_cake)
      and memberOf(c, actor) and hasCalling(c, calling_cleric) and not merritCapped(actor).
    Time 4.
    Grave "Brow wax closes her into the Brow's account; she cannot be uncapped.".
    On success { Spend wax_cake from actor. Assert merritCapped(actor). Assert merritBrow(actor). }
    Result "{c} says it plainly, in the voice for the dead, by the door where the bones sit. The cake of yellow wax goes soft in your hands and is dull when it sets; it is not the colour of anything in that tree. {c} lays it over her all the same, and seals it, and she stands up capped in the Brow's wax with her hands folded, a Capper's girl at last among the Brow's own dead; and you have the feeling, which you do not say, of having signed something on her behalf.".
  }
  // A company with no cleric in it can still cap her. It has no office to say, so it says nothing, and caps her with
  // its hands; Hannet will ask who spoke for her, and the account will say that nobody did.
  Relation merritUnsaid(group).
  Action cap_merrit_white_unsaid(actor: group, site: place) "Cap Merrit Coke in the seventh Leaving's own white comb, with no office to say" {
    Description "You have no words for the dead. You have a slab of white comb and your hands, and a girl by a door.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gallow_hollow) and knows(actor, merrit_found) and holding(actor, white_wax)
      and not companyHasCleric(actor) and not merritCapped(actor).
    Time 6.
    Grave "Once Merrit is capped in the white, the Lantern Stair cannot have it; and she cannot be uncapped.".
    On success { Spend white_wax from actor. Assert merritCapped(actor). Assert merritWhite(actor). Assert merritUnsaid(actor). }
    Result "You do not know the Capper's office, so you do not say it. You warm the white comb until it will take a shape and lay it over her a hand at a time, from the knees up, the way you have seen it done on the wall behind you, and you seal the edge with her own iron because it is lying there. It is not neat. The shoulders are thick and one hand has lost a finger to your thumb. When it sets she is clear as milk, and there is a little hollow in the lap where something small was.".
  }
  Action cap_merrit_brow_unsaid(actor: group, site: place) "Cap Merrit Coke in a cake of Brow wax, with no office to say" {
    Description "You have no words for the dead. A cake of yellow wax is a thing you can carry, and she has waited eighty-one years.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gallow_hollow) and knows(actor, merrit_found) and holding(actor, wax_cake)
      and not companyHasCleric(actor) and not merritCapped(actor).
    Time 6.
    Grave "Brow wax closes her into the Brow's account; she cannot be uncapped.".
    On success { Spend wax_cake from actor. Assert merritCapped(actor). Assert merritBrow(actor). Assert merritUnsaid(actor). }
    Result "You cannot say the office, so you do not. The cake goes soft between your palms and dull when it sets, and you press it over her in sheets, and the edge will not take her iron, so you leave the iron where it is in her hand. She stands up in the Brow's yellow with the seams showing.".
  }
  Rule company_has_cleric when memberOf(?m, party) and hasCalling(?m, calling_cleric) and not companyHasCleric(party) { Assert companyHasCleric(party). }
  Relation companyHasCleric(group).
  Topic hannet_merrit_unsaid with hannet "Tell Hannet that Merrit was capped, and that nobody said anything over her" when merritUnsaid(party) and hannetHasBee(hannet) once {
    Says "Hannet turns the two bees over on their cord. 'Nobody said it,' she says. 'No.' She looks at your hands. 'You did it with those.' She is quiet for a time. 'My aunt capped forty-one of them and I do not suppose any of them was done with words, either, at the end.'".
  }
  Topic hannet_merrit_white with hannet "Tell Hannet that Merrit was capped in the white comb" when merritWhite(party) and not merritUnsaid(party) and hannetHasBee(hannet) once {
    Says "Hannet turns the two bees over on their cord. 'The white,' she says. 'The first comb. She drew that, you know, with her own hands, the first week, before they knew about the damp; she told me it was the cleanest wax in the world, and I was four.' She sits a while. 'She'd have chosen that. She never had a thing that was the Brow's.'".
  }
  Topic hannet_merrit_brow with hannet "Tell Hannet that Merrit was capped in Brow wax" when merritBrow(party) and not merritUnsaid(party) and hannetHasBee(hannet) once {
    Says "Hannet turns the two bees over on their cord. 'Brow wax,' she says, and her mouth does something. 'Well. The Brow never sent for her, and it's capped her anyway. That's the Brow.' She is quiet. 'It's more than it did for the other forty.' She does not say whether she is glad.".
  }
  Rule fate_merrit_w within hume_wold when accounting() and merritWhite(party) and not merritUnsaid(party) and not spread(fate_merrit) says "By the door of the Gallowtree a woman stands in white wax with her hands folded, clear as milk, where the whole tree can see her. Nobody in the Brow has been told, and Hannet Coke knows, and says nothing, and keeps two bees on a cord." { Assert spread(fate_merrit). }
  Rule fate_merrit_b within hume_wold when accounting() and merritBrow(party) and not merritUnsaid(party) and not spread(fate_merrit) says "By the door of the Gallowtree a woman stands in yellow wax with her hands folded. It is Brow wax, and the Brow has not been told whose, and the Cappers' board has a smooth place in its seventh line that one day someone will read." { Assert spread(fate_merrit). }
  Rule fate_merrit_u within hume_wold when accounting() and merritUnsaid(party) and not spread(fate_merrit) says "By the door of the Gallowtree a woman stands in wax with her hands folded and the seams showing, capped by someone who did not know the words and did it anyway. Hannet Coke knows, and keeps two bees on a cord." { Assert spread(fate_merrit). }
  Entity fate_merrit: fact "Merrit".

  // ── A cleric's way through: the carrying office ───────────────────────────────────────────────────────────────────
  // Linnet's reason for refusing Agnes is that nobody ever wrote down that the dead may go, only that they stay. A
  // company that has a cleric knows the lowland office, which does write it, and which the Brow's keeper has never
  // heard said. Linnet can be moved by the watch (lovers.kyr); this is the other way, and no other calling has it.
  Action say_carrying_office(actor: group, site: place, c: member) "Have {c} say the lowland office of the carrying, to Linnet, for Agnes Mellor" {
    Speaker linnet.
    Description "In the lowland office the living say, over the bier, 'We take you.' The Brow has the custom of the dead staying; it has never had the words for the other.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, mothers_chamber) and at(linnet, mothers_chamber) and wantsTobit(agnes)
      and memberOf(c, actor) and hasCalling(c, calling_cleric) and not linnetPermitsDead(linnet) and not leavingBegun().
    Time 2.
    On success { Assert linnetPermitsDead(linnet). }
    Result "{c} does not argue. {c} says it, in the plain low voice for it, with a hand on the Mother's cold flank because that is where the keeper's hand is: the office for carrying the dead, with its three lines. We take you. You will not be left. We carry what is ours. Linnet Amory's hands stop on the old queen's back. 'That is written down?' she says. 'Somewhere that is written down?' {c} says it is written in every parish below the march. 'We kept the dead because nobody ever told us we could take them,' Linnet says, not to you. 'Tell Agnes. Tell her I will walk beside the litter.'".
  }

  // ── Polglaze's beam ───────────────────────────────────────────────────────────────────────────────────────────────
  // The thief sees it; what the company does about it is its own. Crispin Polglaze offers a hush; the Drewes would
  // sooner know. Taking his coin costs nothing but the Drewes; telling them costs him his table.
  Relation beamHushed(group). Relation drewesTold(group).
  Topic polglaze_beam with penhallow "Tell Crispin Polglaze you have seen the file-marks under his near pan" when knows(actor, beam_filed) and not beamHushed(actor) and not drewesTold(actor) once {
    Says "He does not look at the beam. He looks at the boy, and the boy looks at the slate. 'Everyone files a little,' says Crispin Polglaze, pleasantly. 'It is the carriage.' He takes four coin from his coat, as someone might take out a handkerchief, and holds them where only you can see. 'I am a price,' he says. 'I did tell you.'".
    On discuss { Assert offeredHush(penhallow). }
  }
  Relation offeredHush(group).
  Topic polglaze_take with penhallow "Take Crispin Polglaze's four coin" when offeredHush(penhallow) and not beamHushed(actor) and not drewesTold(actor) once {
    Says "The coin is warm from his pocket. 'Sensible,' he says, and the boy goes on writing numbers. At the table of fine candles the mother of the Drewes watches you take it, and watches the beam, and works out what she was not told.".
    On discuss { Assert beamHushed(actor). Increase quantity(actor, gold) by 4. }
  }
  Topic drewes_beam with drewes "Tell the mother of the Drewes about the filed pan" when knows(actor, beam_filed) and not drewesTold(actor) and not beamHushed(actor) once {
    Says "She puts a finger under the near pan, the way you did, and takes it away. 'Thirty years of my mother's moulds,' she says. 'I have been selling them a sixth short to the Company for six years, and I thought it was me.' She picks up the bundle of fluted candles, and then the next, and begins, without hurry, to pack them in the cloth. 'We'll carry them ourselves,' she says to the girls. 'They'll sell new, where we go.' Crispin Polglaze looks up from his slate, and sees the table empty, and does not ask.".
    On discuss { Assert drewesTold(actor). }
  }
  Observe drewes_gone at leavers_yard as sign when drewesTold(party) and not leavingBegun() "The Drewes' table is bare, and the family sits by their bundles at the end of the row, in the sun, not selling.".
  Rule fate_drewes_own within hume_wold when accounting() and drewesTold(party) and not spread(fate_drewes) says "The Drewes carried their own moulds out of the Brow, and light their own candles in the new comb, and the Chandlers' Company in the lowland has noticed that the best fluted candles have stopped coming and asks, courteously, why." { Assert spread(fate_drewes). }
  Entity fate_drewes: fact "the Drewes".

  // ── Where the drovers sleep ────────────────────────────────────────────────────────────────────────────────────────
  Observe bothy_fire at bothy as feature when true "The peat in the grate is banked: ash drawn over a core of red, as someone does who means to come back. A notched stick on a nail by the hearth has a splinter taken out of it at every stop, and a rule cut in the lintel under the names: BANK IT FOR THE NEXT. Nobody in the Wold can tell you who the next is meant to be. The shepherds say their grandfathers' grandfathers did it, and so do they.".
  Observe bothy_quarrel at bothy as feature when true "Low on the lintel two names are cut side by side, with the same date, two hundred and some years gone: HOB TREWIN, and next to him GABRIEL FENN. Someone has scored out FENN with a knife, and under it, in a rounder hand, scratched: HE WAS RIGHT ABOUT THE SHEEP.".

  // ── Where the Wold's wax goes ──────────────────────────────────────────────────────────────────────────────────────
  Observe polglaze_slate at leavers_yard as feature when daytime() "The factor's boy holds his slate where you can read it over his arm: the Company's carts for the week, and where. SIXWAYS, the Haskett cart, six bundles of fluted candles, and a note that the Sixways trade asks for them unlit, because they keep better so. LARUM, below the Pass, nine bundles for the parson's vigil, no questions asked about the Pass. And the stamp on the beam, which the boy is polishing with his sleeve: COLLEGIUM OF MEASURES · PROVED.".
}

data/adventures/half-the-hive/wold.kyr:
Module hume "Half the Hive" {
  // ── The High Wold: the honey linden, the moor, the Toot ───────────────────────────────────────────────────────────

  // Cutting wild comb: a living. Forty feet up a lime on old pegs, a slab a day, sold in Smoke End.
  Relation combCutToday(place). Measure combCutDay(place).
  Hazard peg_fall "a fall from the honey linden" means "Deal (2d6) physical damage to ally unless dexterity save against (12).".
  Action cut_comb(actor: group, site: place) "Climb the pegs to the wild comb, and cut a slab" {
    Description "Forty feet up an old lime on other people's pegs, with wild bees about your head.".
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, honey_oak) and daytime() and combCutDay(honey_oak) != day(clock).
    Time 6.
    Resolve check(actor, climbing, dc_fair).
    On success { Set combCutDay(honey_oak) to day(clock). Increase combsCut(honey_oak) by 1. }
    On failure { Set combCutDay(honey_oak) to day(clock). Assert strikes(peg_fall, actor). }
    Result "You go up the pegs with your knife in your teeth. Up close the wild bees are tiny and furious and their stings are needles, not nails; you hardly feel them. You cut a slab the size of a book from the lip of the comb and come down with it held against your chest, honey running down your wrists.".
    Otherwise "Thirty feet up a peg turns under your foot, old and rotten, and the trunk goes past you, and the ground comes up.".
  }
  Measure combsCut(place). Relation combHanded(entity).
  Item wild_a "a slab of wild comb" is wild_comb at limbo. Item wild_b "a slab of wild comb" is wild_comb at limbo. Item wild_c "a slab of wild comb" is wild_comb at limbo.
  Item wild_d "a slab of wild comb" is wild_comb at limbo. Item wild_e "a slab of wild comb" is wild_comb at limbo. Item wild_f "a slab of wild comb" is wild_comb at limbo.
  Rule comb_a when combsCut(honey_oak) >= 1 and not combHanded(wild_a) { Assert combHanded(wild_a). Give wild_a to party. }
  Rule comb_b when combsCut(honey_oak) >= 2 and not combHanded(wild_b) { Assert combHanded(wild_b). Give wild_b to party. }
  Rule comb_c when combsCut(honey_oak) >= 3 and not combHanded(wild_c) { Assert combHanded(wild_c). Give wild_c to party. }
  Rule comb_d when combsCut(honey_oak) >= 4 and not combHanded(wild_d) { Assert combHanded(wild_d). Give wild_d to party. }
  Rule comb_e when combsCut(honey_oak) >= 5 and not combHanded(wild_e) { Assert combHanded(wild_e). Give wild_e to party. }
  Rule comb_f when combsCut(honey_oak) >= 6 and not combHanded(wild_f) { Assert combHanded(wild_f). Give wild_f to party. }
  Observe oak_cut at honey_oak as sign when combCutDay(honey_oak) == day(clock) "A raw pale place on the lip of the wild comb shows where a slab was cut today. The bees are mending it already.".

  // The black hive on the crag: robbers. Smoke, flame, a fight, or the shepherds' drove.
  Species robber_kind "a black robber-bee" like nightmare temperament territorial described "A bee the size of a cat, black all over and glossy as a beetle, with a high mean whine and a sting like an awl. Robbers: they take honey from weaker hives, and anything else they find.".
  Person robbers "the black bees of the crag" at black_crag {
    Role "a swarm of black robber-bees, each the size of a cat, boiling out of the splits in the crag".
    Species robber_kind. Level 2. Numbers 5.
    State hanging blocking "Black bees hang in the air over the far path under the crag, whining, and they will let no one by who has not dealt with them.".
    Guards far_path.
    Fears flame.
    Refuge limbo.
    Warns "The whine on the crag goes up a note, sharp, and black bees come out of the splits in the rock and hang in the air over the path, a dozen, twenty, facing you. They do not come nearer yet. They are deciding. A smoker would make them stupid; a torch would make them go; there is no other way past the crag but through them, unless you know one.".
    Comes "The black bees come down off the crag at you all at once, whining, and the air is full of them.".
    Flinches "The black bees fall back from the fire, whining, into the splits of the crag.".
  }
  Action smoke_robbers(actor: group, site: place) "Puff smoke at the black bees until they go slow" {
    Requires at(actor, site) and able(actor) and company(actor) and at(actor, black_crag) and smoking() and able(robbers) and at(robbers, black_crag) and not tolerates(robbers, actor).
    Time 1.
    On success { Assert tolerates(robbers, actor). }
    Result "You work the bellows, and the smoker coughs grey into the air over the path, and the black bees in it slow and blunder and settle on the heather, and crawl, and forget you. You go under the crag at a walk, puffing, with your heart in your throat.".
  }

  // The bothy, on the shepherds' drove.
  Observe bothy_names at bothy as feature when true "The names on the lintel are shepherds' names, mostly, and dates; and in among them, newer, cut in a careless flowing hand that must have taken an afternoon: IVO G. HIS BOTHY. And under that, in another hand, neat and square: NOT HIS. K.D.".

  // ── The Toot, and Duke ────────────────────────────────────────────────────────────────────────────────────────────
  // Tibby Breck's pet drone, Duke, has flown up the Toot to the drones' gathering, as drones do. Tibby will tell where
  // with a dance, as Hume children do; and brought Duke home, he tells what his grandmother does at night.
  Species drone_kind "a drone" like dragonfly tame described "A drone of the Sisters: bigger than a worker, blunt-faced, with enormous eyes that meet on the top of his head, no sting at all, and a deep rich buzz like a man humming with his mouth shut.".
  Person duke "Duke" at toot {
    Role "a young drone with a scrap of red ribbon tied round one leg, sitting in the grass with his enormous eyes on the sky" when not dukeHome(duke).
    Role "Tibby's drone, with a scrap of red ribbon round one leg, humming" when dukeHome(duke).
    Species drone_kind. Peaceable. Pronouns he.
  }
  Initially Assert acceptsEscort(duke, party).
  Person tibby "Tibby Breck" at royal_gallery {
    Role "a small boy of eight with a scab on his chin, sitting under the Breck princess-cell, kicking his heels".
    Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "A small boy under the first princess-cell looks at you with frank interest. 'Are you a lowlander? Can you find things? Duke's gone. He's my drone. I raised him from an egg. He's got a red ribbon on. Gran says drones always go, it's what they're for, but he's mine.' His lip goes. Then it firms up. 'I can show you where he went. I saw him go.'".
    Greets again "Tibby kicks his heels. 'Have you found Duke?'".
  }
  Relation dukeHome(group).
  Initially Assert home(duke, royal_gallery).
  Topic tibby_where with tibby "Ask Tibby to show you where Duke went" when not dukeHome(duke) and not knows(actor, duke_where) once {
    Says "Tibby stands up, very serious, and shows you with a dance, the way Hume children do: a little run toward where the sun would be, and then off to one side, waggling his bottom for all he is worth, and then a loop, and again. He is very bad at it and very proud.".
    On discuss { Assert knows(actor, duke_where). }
  }
  Discovery duke_where "Tibby Breck's drone Duke went up the Toot, the hill above the gorge, where the drones gather.".
  Initially Assert leadsTo(duke_where, toot).
  Observe tibby_dance_read near tibby when knows(party, duke_where) and danceLearned(party) and not dukeHome(duke) "Read with the eye Kestrel gave you, Tibby's dance was not so bad: a short way, uphill, north of the sun. The Toot.".
  Rule duke_home at royal_gallery when cameHome(duke) and not dukeHome(duke) says "Tibby sees Duke before Duke sees him, and makes a noise like a kettle, and then he has the drone round the neck, which is a thing you would not have thought possible, and Duke is humming deep in his chest like a cat purring, and Tibby is telling him he is a very bad drone, very bad, the worst." { Assert dukeHome(duke). Retract following(duke, party). Retract acceptsEscort(duke, party). Assert at(duke, royal_gallery). }
  Topic tibby_secret with tibby "Ask Tibby whether anything strange happens in the royal gallery" when dukeHome(duke) and not knows(actor, breck_spoon) once {
    Says "Tibby looks round to see if anyone is listening, and then puts his mouth up to your ear, and Duke's enormous eye comes round too, as if he wants to hear. 'Gran comes at night,' Tibby whispers. 'When everyone's gone to sleep. With the big spoon and the jelly-pot. And she puts jelly in our princess's cell through a little hole, lots of it. I followed her, looking for Duke.' He thinks. 'She said if I told, the princess would be sad.' He looks worried. 'Is it a secret if you tell a lowlander?'".
    On discuss { Assert knows(actor, breck_spoon). }
  }
  Discovery breck_spoon "Dame Brenna Breck goes to the royal gallery at night and feeds extra royal jelly into her household's princess-cell through a hole, so that her princess will wake first and kill the others.".
}

data/adventures/hessel/ball.kyr:
Module hessel "The Banns at Hessel" {
  // ── The Closing Ball ──────────────────────────────────────────────────────────────────────────────────────────────
  // The fourth night, seven till eleven: the minuet at seven, which Mr Twiss opens; country dances on the hour at eight,
  // nine and ten; at eleven the music stops, though the King himself should ask. Who dances with whom is seen by
  // everyone, and the Rules say what it means.
  Relation atBall(group).
  Query ballNight() means fourthDay() and hour(clock) >= 19.
  Query minuet() means ballNight() and hour(clock) == 19.
  Query secondDance() means ballNight() and hour(clock) == 20.
  Query thirdDance() means ballNight() and hour(clock) == 21.
  Query fourthDance() means ballNight() and hour(clock) == 22.
  Query afterEleven() means ballNight() and hour(clock) >= 23.
  Rule ball_over when atBall(?x) and not ballNight() { Retract atBall(?x). }
  // Who comes. The household, if Mr Twiss has lifted his bar; Mrs Cherrett, if she is well enough and someone will
  // push her chair across the Circus (Kit, unless the poles are down; the chairmen, for a friend of theirs; or you).
  Relation cherrettPushed(group).
  Query cherrettCanGo() means householdAdmitted(cherrett) and cherrettUp() and failing(cherrett) < 4 and (not strike(chairmen) or stoodWith(party) or cherrettPushed(cherrett)).
  Rule ball_cherrett when ballNight() and hour(clock) < 23 and cherrettCanGo() and not atBall(cherrett) and not ballLeft(cherrett) { Assert atBall(cherrett). Assert at(cherrett, ballroom). }
  Rule ball_cherrett_late when afterEleven() and cherrettCanGo() and not atBall(cherrett) and not ballLeft(cherrett) and cherrettPushed(cherrett) { Assert atBall(cherrett). Assert at(cherrett, ballroom). }
  Relation ballLeft(group).
  Action push_cherrett(actor: group, site: place) "Push Mrs Cherrett's chair across the Circus to the Ball yourself" {
    Description "The poles are down; no chairman will push it. It is only across the lawn.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, cherrett_parlour) and at(cherrett, cherrett_parlour) and ballNight() and hour(clock) < 23
      and householdAdmitted(cherrett) and strike(chairmen) and not stoodWith(actor) and not cherrettPushed(cherrett) and cherrettUp().
    Time 1.
    On success { Assert cherrettPushed(cherrett). Retract at(actor, site). Assert at(actor, ballroom). }
    Result "Across the Circus lawn in the dusk, with the Rooms lit like a ship in front of you and the music coming out of the windows, pushing a wicker bath-chair with a very large old woman in purple in it, who is singing. On Stall Street, below, thirty chairmen sit on their poles in the dark, and somebody down there, seeing who it is, begins to clap.".
  }
  Rule ball_ismay when ballNight() and hour(clock) < 23 and householdAdmitted(cherrett) and not atBall(ismay) and not ismayAway(ismay) and not ballLeft(ismay) { Assert atBall(ismay). Assert at(ismay, ballroom). }
  Rule ball_rob when ballNight() and hour(clock) < 23 and (householdAdmitted(cherrett) or celiaOut(celia)) and not atBall(rob) and not robAway(rob) and not ballLeft(rob) { Assert atBall(rob). Assert at(rob, ballroom). }
  Rule ball_mopsa when ballNight() and hour(clock) < 23 and householdAdmitted(cherrett) and (not mopsaHouse(mopsa) or mopsaYes(party)) and not atBall(mopsa) and not mopsaAway(mopsa) and not ballLeft(mopsa) and not travelsWith(mopsa, party) { Assert atBall(mopsa). Assert at(mopsa, ballroom). }
  Rule ball_wenlock when ballNight() and hour(clock) < 23 and (not scandal(wenlock) or grandmother(lady_wenlock)) and not atBall(lady_wenlock) and not wenlockGone(wenlock) and (not strike(chairmen) or grandmother(lady_wenlock)) { Assert atBall(lady_wenlock). Assert at(lady_wenlock, ballroom). }
  Rule ball_rupert when ballNight() and hour(clock) < 23 and grandmother(lady_wenlock) and not atBall(rupert) { Assert atBall(rupert). Assert at(rupert, ballroom). }
  Rule ball_hetty when ballNight() and hour(clock) < 23 and grandmother(lady_wenlock) and not atBall(hetty) { Assert atBall(hetty). Assert at(hetty, ballroom). }
  Rule ball_hartopp when ballNight() and hour(clock) < 23 and not hartoppRuined(hartopp) and not hartoppBarred(hartopp) and not hartoppWalked(hartopp) and not atBall(hartopp) { Assert atBall(hartopp). Assert at(hartopp, ballroom). }
  Rule ball_celia when ballNight() and hour(clock) >= 21 and hour(clock) < 23 and (celiaOut(celia) or carthOpened(carth)) and not atBall(celia) and not celiaAway(celia) { Assert atBall(celia). Assert at(celia, ballroom). }
  Rule ball_carths when ballNight() and hour(clock) >= 21 and hour(clock) < 23 and carthOpened(carth) and not atBall(gervase) { Assert atBall(gervase). Assert at(gervase, ballroom). Assert atBall(nan). Assert at(nan, ballroom). }
  Rule ball_twiss when ballNight() and not at(twiss, ballroom) { Assert at(twiss, ballroom). }
  // Hartopp, walking up the Parade in the strike or because no chairman will carry him, arrives in boots.
  Event hartopp_boots at vestibule when ballNight() and hartoppWalked(hartopp) and not hartoppRuined(hartopp) and not hartoppBarred(hartopp) and not spread(boots_told) and at(party, vestibule) "At a quarter past seven Dr Hartopp arrives at the Rooms on foot, very hot, having walked up the Parade, in the riding-boots he pulled on to do it, splashed to the knee. Mr Twiss, at the ballroom doors, looks at the boots. The whole vestibule looks at the boots. 'No boots after six,' says Mr Twiss, in the voice he uses for the Rules, and does not move out of the doorway. Dr Hartopp says that he is a physician. Mr Twiss says that the Rule makes no exception for the learned professions. Dr Hartopp goes away down the hill in his boots, and the band, which can see the vestibule from the gallery, plays him out with a jig." then {
    Assert hartoppBarred(hartopp). Assert spread(boots_told). Assert bootsHeard(party). }
  Rule hartopp_boots_unseen when ballNight() and hour(clock) >= 19 and hartoppWalked(hartopp) and not hartoppRuined(hartopp) and not hartoppBarred(hartopp) and not spread(boots_told) and not at(party, vestibule) {
    Assert hartoppBarred(hartopp). Assert spread(boots_told). }
  Entity boots_told: fact "Hartopp's boots".
  // Whoever was not in the vestibule to see it hears it in the ballroom, or from the chairmen, who made it happen.
  Relation bootsHeard(group).
  Rule boots_told_in_the_room at ballroom when spread(boots_told) and at(party, ballroom) and not bootsHeard(party) says "The whole ballroom is telling itself, behind its fans, that Dr Hartopp came up the Parade on foot, in riding-boots, and Mr Twiss looked at the boots and said 'No boots after six', and the band played him out with a jig." { Assert bootsHeard(party). }
  Rule boots_retold at two_poles when spread(boots_told) and hartoppWalked(hartopp) and at(party, two_poles) and not bootsHeard(party) says "The chairmen have it already, and tell it to you with their arms folded: how Dr Hartopp came up the Parade on foot at a quarter past seven, in riding-boots, red as a beef, and Mr Twiss looked at the boots, and said 'No boots after six,' and Dr Hartopp went down the Parade again on foot, with the whole Circus at its windows. 'In his boots,' says Big Lanyon, with deep content. 'All the way down.'" { Assert bootsHeard(party). }
  // The footman bribed: Mr Twiss finds the household at the side door, in front of the Season.
  Event fitch_found at vestibule when (at(party, vestibule) or at(party, ballroom)) and ballNight() and fitchBribed(party) and householdBarred(cherrett) and not householdAdmitted(cherrett) and not spread(fitch_told) "At half past seven Mr Twiss, on his rounds, opens the side door of the ballroom and finds Mrs Cherrett's household on the other side of it, with Pocklington holding the door. He looks at Pocklington. Pocklington looks at the far wall. 'Mrs Cherrett's party,' says Mr Twiss, to the whole room, which has turned to watch, 'is not admitted to these Rooms. Pocklington, you are dismissed. Good evening.' And he shuts the door on you himself." then {
    Assert twissOffended(party). Assert spread(fitch_told). Assert fitchDismissed(fitch). Assert at(fitch, limbo). }
  Entity fitch_told: fact "Pocklington at the side door". Relation fitchDismissed(group).
  Rule offended_out when twissOffended(party) and admitted(party) { Retract admitted(party). }
  // How it looks.
  Observe ball_scene at ballroom when ballNight() and hour(clock) < 23 "The ballroom at night: five chandeliers lit, a thousand candles, the mirrors doubling everything, the band in the gallery, and the whole Season of Hessel on the floor in its best, turning, bowing, watching itself turn and bow. It is very hot and very beautiful and everybody is talking at once.".
  Observe ball_minuet at ballroom when minuet() "Mr Twiss opens the Ball with the minuet, as he has for twenty years, dancing it with the first lady present; he dances it as if it were a prayer, and nobody laughs, not even the young.".
  Observe ball_cherrett at ballroom when ballNight() and at(cherrett, ballroom) and hour(clock) < 23 "Mrs Cherrett is in her bath-chair at the edge of the floor in purple and diamonds, with her stick across her knees, watching everyone dance with an expression of the most intense critical pleasure.".
  Observe ball_cherrett_drowsy at ballroom when ballNight() and at(cherrett, ballroom) and failing(cherrett) >= 3 "Mrs Cherrett has fallen asleep in her bath-chair at the edge of the floor, with her diamonds rising and falling, and Mopsa is standing beside her so that nobody sees.".
  Observe ball_grandmother at ballroom when ballNight() and grandmother(lady_wenlock) and at(lady_wenlock, ballroom) "Lady Wenlock is at the Ball with a blue ribbon in her cap that does not go with anything, and beside her, in the best bonnet in Hessel, a milliner, whom she is introducing to people. 'My son's wife,' she says, and dares them.".
  Observe ball_carths at ballroom when ballNight() and at(gervase, ballroom) "At nine the Rooms go quiet, and then quieter. Sir Gervase Carth is standing in the doorway of the ballroom in a coat nine years out of fashion, with a woman on his arm in grey silk that somebody has lent her, with red laundress's hands. The whole Season knows who she is by the time they reach the middle of the floor. Mr Twiss goes to meet them and bows the bow that is several bows, and gives them the floor.".
  Observe ball_celia at ballroom when ballNight() and at(celia, ballroom) and not at(gervase, ballroom) "At nine a girl comes in at the ballroom doors on Rob Cherrett's arm, in a borrowed white gown, with no fur cap, blinking at the chandeliers as if she had never seen so much light, which she has not. The room goes quiet as she crosses it. 'Who is she?' says somebody, and somebody else says, 'The Carth girl. The one in the dark,' and the whispering goes round the floor like a wind round a field.".
  // The dances.
  Relation dancedWith(group, group). Relation hartoppClaims(group). Relation hartoppCutOut(group). Relation twissWarned(group).
  Action dance_ismay(actor: group, site: place) "Ask Ismay to stand up with you for the second dance" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ballroom) and at(ismay, ballroom) and secondDance() and not dancedWith(actor, ismay) and admitted(actor).
    Time 1 minute.
    On success { Assert dancedWith(actor, ismay). Assert hartoppCutOut(hartopp). }
    Result "Ismay looks at you, and at Dr Hartopp coming across the floor toward her with his hand already out, and says 'Yes,' very quickly, and stands up. You go down the set together. She dances the way she does accounts: exactly, and better than anyone, and without once looking as if she is enjoying it, until the end, when she laughs.".
  }
  Action dance_mopsa(actor: group, site: place) "Ask Mopsa to stand up with you for the second dance, against the Rule" {
    Description "No companion, governess or paid attendant to stand up in the dances. Signed, Septimus Twiss.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ballroom) and at(mopsa, ballroom) and secondDance() and not dancedWith(actor, mopsa) and admitted(actor).
    Time 1 minute.
    On success { Assert dancedWith(actor, mopsa). Increase courtship(mopsa) by 1. }
    Result "Mopsa looks at your hand, and at the Rules on their gold frame by the door, and at Mr Twiss, and then she puts her book down on her chair and stands up. You go down the set. The set notices. The room notices. Mopsa dances very well, as if she had learned it once a long time ago and kept it in a drawer.".
  }
  Rule twiss_sees_mopsa at ballroom when dancedWith(party, mopsa) and twissFavour(twiss) < 3 and not spread(twiss_mopsa_told) says "At the end of the dance Mr Twiss is waiting. 'Miss Gedge,' he says, not loudly, 'is a companion. The Rule is the Rule.' Mopsa curtseys to him, very low, and goes back to her chair and her book, and as she passes you she says, without moving her lips, 'Worth it.'" { Assert spread(twiss_mopsa_told). Decrease twissFavour(twiss) by 1. }
  Rule twiss_blind_mopsa at ballroom when dancedWith(party, mopsa) and twissFavour(twiss) >= 3 and not spread(twiss_mopsa_told) says "At the end of the dance Mr Twiss is looking with great attention at a chandelier. He goes on looking at it until Mopsa is back in her chair." { Assert spread(twiss_mopsa_told). }
  Entity twiss_mopsa_told: fact "Twiss and the companion's dance".
  Topic twiss_not_betrothed with twiss "Tell Mr Twiss that Miss Cherrett is not betrothed to Dr Hartopp" when secondDance() and atBall(hartopp) and atBall(ismay) and not hartoppCutOut(hartopp) and not twissWarned(twiss) once {
    Says "Mr Twiss follows your eyes across the floor to Dr Hartopp, who is leading Ismay Cherrett down the set with a look on him like a man who has just been dealt a good hand. 'Not betrothed,' says Mr Twiss. 'And he means to stand up with her for the third, running. In my Rooms.' His face does not change at all. 'Thank you,' he says. 'Thank you very much.'".
    On discuss { Assert twissWarned(twiss). }
  }
  Observe hartopp_second at ballroom when secondDance() and atBall(hartopp) and atBall(ismay) and hartoppHasIsmay() and not hartoppCutOut(hartopp) "Dr Hartopp has stood up with Ismay Cherrett for the second dance, and is leading her down the set with a look on him like a man who has been dealt a good hand. He says something to her at every turn. She does not answer any of it. Across the room Mrs Scrope has put down her cards to watch, which she never does until the third dance.".
  // Hartopp leads her out for the third, running: a declaration. Stopped by Twiss if warned; claimed if not.
  Rule hartopp_third at ballroom when thirdDance() and atBall(hartopp) and atBall(ismay) and hartoppHasIsmay() and not hartoppCutOut(hartopp) and not hartoppClaims(ismay) and not hartoppBarred(hartopp) and twissWarned(twiss)
    says "Dr Hartopp, who stood up with Ismay Cherrett for the second dance, stands up with her for the third, running, in front of the whole Season; and Mr Twiss comes across the floor and stops the band with one lifted finger. 'Dr Hartopp,' he says, quite pleasantly, so that everyone can hear, 'is not betrothed to Miss Cherrett. Nor, I think, is he going to be. The Rule is the Rule.' He offers Ismay his own arm. Dr Hartopp stands alone in the middle of the floor for a moment that goes on and on, and then goes out, and the band starts again." {
    Assert hartoppBarred(hartopp). Retract atBall(hartopp). Assert at(hartopp, hartopp_room). }
  Rule hartopp_claims at ballroom when thirdDance() and atBall(hartopp) and atBall(ismay) and hartoppHasIsmay() and not hartoppCutOut(hartopp) and not hartoppClaims(ismay) and not hartoppBarred(hartopp) and not twissWarned(twiss)
    says "Dr Hartopp, who stood up with Ismay Cherrett for the second dance, stands up with her for the third, running, in front of the whole Season; and nobody stops him, and the Season, which knows what two dances running means, begins to whisper. Nobody of her household says a word. Ismay dances it white and straight, like somebody walking to a gallows she has been told is a garden." {
    Assert hartoppClaims(ismay). }
  // Kit at the door: chairmen are not admitted; Ismay goes out to him.
  Relation kitDanced(group).
  Rule kit_at_door when fourthDance() and kitEngaged(kit) and atBall(ismay) and not kitDanced(kit) and not hartoppClaims(ismay) { Assert kitDanced(kit). Retract atBall(ismay). Assert at(ismay, circus). Assert at(kit, circus). Assert ballLeft(ismay). Assert kitAway(kit). }
  Observe kit_dancing at circus when kitDanced(kit) and fourthDance() "On the Circus lawn, in the dark, to the music coming out of the Rooms' tall windows, Ismay Cherrett in her ball-dress and Kit Danby in his blue coat are dancing the fourth dance by themselves on the grass. They are doing it wrong. It does not matter. Up at the windows the Season is crowded three deep to watch, and in the doorway Mr Twiss is standing with his hands behind his back and his face perfectly still.".
  Observe kit_dancing_seen at ballroom when kitDanced(kit) and fourthDance() "Half the room is at the windows. Down on the Circus lawn, in the dark, Ismay Cherrett has gone out to dance the fourth dance on the grass with a chairman.".
  // Rob and Celia dance the third and the fourth.
  Rule rob_dances_celia when thirdDance() and atBall(rob) and atBall(celia) and robCeliaSpoke(rob) and not dancedWith(rob, celia) { Assert dancedWith(rob, celia). }
  Observe rob_celia_dance at ballroom when dancedWith(rob, celia) and atBall(celia) and hour(clock) < 23 "Rob Cherrett is dancing with Celia Carth, both of them very badly, both of them laughing; she has never danced, and he has never cared to, and they have decided between them that it is a kind of walking in which you keep meeting.".
  // Eleven o'clock. The music stops. Mrs Cherrett's dance, if Mr Twiss will break the oldest Rule of the Rooms.
  Relation cherrettDanced(group). Relation lastDanceAsked(group).
  Observe after_eleven at ballroom when afterEleven() and cherrettDanced(cherrett) "The ballroom after the last minuet: half the candles out, the Season going home in a slow happy crush at the doors, and the band, without being asked, playing it again, quietly, to nobody.".
  Observe eleven at ballroom when afterEleven() and not cherrettDanced(cherrett) "Eleven. Mr Twiss lifts his hand, and the band stops in the middle of a bar, as it has every night at eleven for twenty years, though the King himself should ask. The Season begins, slowly, to look for its shawls.".
  Action ask_last_dance(actor: group, site: place) "Ask Mr Twiss for one dance more, for Mrs Cherrett" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ballroom) and at(twiss, ballroom) and at(cherrett, ballroom) and afterEleven()
      and not gone(cherrett) and not cherrettDanced(cherrett) and not lastDanceAsked(actor).
    Time 2 minutes.
    On success { Assert lastDanceAsked(actor). }
    Result "You ask it. Mr Twiss looks at you, and then across the emptying floor at Mrs Cherrett in her bath-chair, purple and diamonds, with her stick across her knees.".
  }
  Rule twiss_bends at ballroom when lastDanceAsked(party) and twissFavour(twiss) >= 2 and failing(cherrett) < 3 and at(cherrett, ballroom) and not cherrettDanced(cherrett)
    says "Mr Twiss looks at the old woman. Then he goes across the empty floor to her chair, and bows (the bow that is several bows), and holds out his hand. 'Mrs Cherrett,' he says. 'I believe I have the honour of the last minuet.' The whole Season stops on its way to the door. Mrs Cherrett looks at the hand. 'I can't stand,' she says. 'I'll hold you up,' says Mr Twiss. And the band, without being told, begins the minuet from the beginning; and the Master of the Ceremonies dances the minuet with a canal-cutter's widow, at a quarter past eleven, in the Closing Ball of the Season, holding her up, very slowly, in the middle of the floor, while everyone watches; and Mrs Cherrett does not laugh once, all the way through, until the very end, when she laughs so that you can hear it in the card room, and so does he." {
    Assert cherrettDanced(cherrett). }
  Rule twiss_refuses at ballroom when lastDanceAsked(party) and (twissFavour(twiss) < 2 or failing(cherrett) >= 3) and not cherrettDanced(cherrett) and not spread(twiss_refused_told)
    says "'No dancing after eleven,' says Mr Twiss gently, 'though the King himself should ask it.' He bows to Mrs Cherrett across the floor, a real bow, and she nods to him, and that is all." { Assert spread(twiss_refused_told). }
  Entity twiss_refused_told: fact "the last dance refused".
  // At midnight everyone goes home.
  Rule ball_home_cherrett when fifthDay() and hour(clock) < 6 and atBall(cherrett) { Retract atBall(cherrett). }
}

data/adventures/hessel/banns.kyr:
Module hessel "The Banns at Hessel" {
  // ── Mr Pyne ───────────────────────────────────────────────────────────────────────────────────────────────────────
  // The curate of Saint Ebba's, twenty-four. He has read banns for two years and has never once been answered at "If
  // any of you know cause". He has a recurring dream in which he is. This Sunday, he will be, or he will not.
  Person pyne "Mr Pyne" at vestry {
    Role "the curate of Saint Ebba's, very young, very thin, very clean". Ancestry human. Calling cleric. Level 1. Peaceable. Pronouns he. Manner compassionate.
    Greets "The young curate jumps up from the vestry table as if you had caught him at something, which you have: he was practising, under his breath, the form for the publication of banns. 'Oh!' he says. 'Forgive me. How may I serve you?'".
    Greets again "Mr Pyne smiles at you nervously.".
    Wants licence_kind.
  }
  Rule pyne_vestry when not at(pyne, vestry) and not readingNow() and not weddingNow() and hour(clock) >= 7 and hour(clock) < 20 { Assert at(pyne, vestry). }
  Rule pyne_reads when readingNow() and not at(pyne, ebba_nave) { Assert at(pyne, ebba_nave). }
  Rule pyne_weds when weddingNow() and not at(pyne, ebba_nave) { Assert at(pyne, ebba_nave). }
  Rule pyne_bed when (hour(clock) >= 20 or hour(clock) < 7) and not at(pyne, limbo) { Assert at(pyne, limbo). }
  Relation pyneReady(group).
  Topic pyne_dream with pyne "Ask Mr Pyne about the banns" when not bannsDone(ebbas) and not bannsWithdrawn(ebbas) once {
    Says "'The Cherrett and Wenlock banns.' Mr Pyne turns the register round so you can see the two entries in his own careful hand. 'Sunday will be the third time of asking.' He swallows. 'I have read banns for two years. Forty-one couples. At If any of you know cause, or just impediment, I pause, as the rubric directs, for the space of a breath, and nobody has ever said anything.' He looks at the vestry window. 'I dream about it. I dream someone stands up, and I don't know what to do, and the whole church looks at me, and I wake up.' He tries to laugh. 'Every Saturday night.'".
  }
  Topic pyne_warned with pyne "Tell Mr Pyne what he will hear on Sunday if he pauses long enough: that Rupert Wenlock is married already" when knows(actor, rupert_married) and not pyneReady(pyne) and not bannsDone(ebbas) and not bannsWithdrawn(ebbas) once {
    Says "Mr Pyne sits down. He goes very white, and then, oddly, he goes calm, the way a man does when the thing he has been dreading turns out to be a thing. 'Married,' he says. 'Then it is an impediment. A true one.' He takes up the prayer book and finds the place. 'The rubric says pause. It does not say for how long.' He looks at you. 'I shall pause,' says Mr Pyne, 'until somebody says something, if it takes all morning. And I shall look at Mr Wenlock while I do it.'".
    On discuss { Assert pyneReady(pyne). }
  }

  // ── The third reading ─────────────────────────────────────────────────────────────────────────────────────────────
  // Sunday, morning service at eleven. At ten past, Mr Pyne publishes the banns of Ismay Cherrett and Rupert Wenlock for
  // the third time of asking, and pauses. In the pause anyone may speak. At twenty past, the pause is over.
  Relation bannsWithdrawn(place). Relation bannsDone(place). Relation readingBegun(place). Relation bannsStopped(place).
  Relation stoppedByCompany(place). Relation stoppedByRupert(place). Relation stoppedByHetty(place). Relation ismayObjected(place).
  Query readingNow() means thirdDay() and hour(clock) == 11 and not bannsWithdrawn(ebbas) and not bannsDone(ebbas).
  Measure readingWatch(place).
  Rule reading_begins when readingNow() and not readingBegun(ebbas) { Assert readingBegun(ebbas). Set readingWatch(ebbas) to watch(clock). }
  Query inPause() means readingBegun(ebbas) and readingNow() and watch(clock) >= readingWatch(ebbas) + 1 and watch(clock) <= readingWatch(ebbas) + 2.
  // The congregation gathers for service: those who would be in church.
  Rule church_cherrett when readingNow() and cherrettUp() and not at(cherrett, ebba_nave) { Assert at(cherrett, ebba_nave). }
  Rule church_ismay when readingNow() and not at(ismay, ebba_nave) and not ismayAway(ismay) { Assert at(ismay, ebba_nave). }
  Rule church_rupert when readingNow() and not at(rupert, ebba_nave) and not rupertAway(rupert) { Assert at(rupert, ebba_nave). }
  Rule church_wenlock when readingNow() and not at(lady_wenlock, ebba_nave) and not wenlockGone(wenlock) { Assert at(lady_wenlock, ebba_nave). }
  Rule church_mopsa when readingNow() and not at(mopsa, ebba_nave) and not mopsaAway(mopsa) and not mopsaHouse(mopsa) { Assert at(mopsa, ebba_nave). }
  Rule church_scrope when readingNow() and not at(scrope, ebba_nave) { Assert at(scrope, ebba_nave). }
  Observe reading_scene at ebba_nave when readingNow() and not inPause() "Saint Ebba's is full for morning service: the Season in its Sunday best, fanning itself under the memorial tablets. The Cherretts are in the third pew; the Wenlocks across the aisle; Mrs Scrope behind both, where she can see.".
  Observe pause_scene at ebba_nave when inPause() "Mr Pyne reads it, in his clear young voice: I publish the banns of marriage between Ismay Cherrett, spinster, of this parish, and the Honourable Rupert Wenlock, bachelor, of the parish of Saint Cuthbert. This is the third time of asking. If any of you know cause, or just impediment, why these two persons should not be joined together in holy matrimony, ye are to declare it. And he stops. Saint Ebba's waits. Somebody coughs. Mr Pyne does not go on.".
  Observe pause_ready at ebba_nave when inPause() and pyneReady(pyne) "Mr Pyne is looking straight at Rupert Wenlock, and does not look away, and does not go on, and goes on not going on. The pause stretches. The Season begins to look at the curate, and then at where the curate is looking.".
  // In the pause.
  Action declare_cause(actor: group, site: place) "Stand up and declare the cause: that Rupert Wenlock has a wife living" {
    Grave "Before the whole Season, in church. It cannot be unsaid.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ebba_nave) and inPause() and knows(actor, rupert_married) and not bannsStopped(ebbas).
    Time 2 minutes.
    On success { Assert bannsStopped(ebbas). Assert bannsWithdrawn(ebbas). Assert stoppedByCompany(ebbas). Assert scandal(wenlock). }
    Result "You stand up. Every head in Saint Ebba's turns, with the sound a field of barley makes. You say it: that the Honourable Rupert Wenlock has a wife living, Hetty Wenlock, born Quiney, milliner, of Quay Lane, and a son. Mr Pyne closes the book. 'Then these banns are void,' he says, in a voice that does not shake at all; he sounds, if anything, relieved. Across the aisle Lady Wenlock rises, and walks out of the church without looking at anyone, and Rupert sits with his head bowed, and Mrs Scrope is already halfway to the door.".
  }
  Action rupert_rises(actor: group, site: place) "Look at Rupert Wenlock, and wait" {
    Description "He swore every Sunday he would.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ebba_nave) and inPause() and at(rupert, ebba_nave) and (rupertBrave(rupert) or rupertConfessed(rupert) and pyneReady(pyne)) and not bannsStopped(ebbas).
    Time 2 minutes.
    On success { Assert bannsStopped(ebbas). Assert bannsWithdrawn(ebbas). Assert stoppedByRupert(ebbas). Assert rupertSpoke(rupert). }
    Result "Rupert Wenlock feels you looking. He looks back. Then, very slowly, as if his legs belonged to somebody else, he stands up in the Wenlock pew, with his pill-box in his hand, and says to the whole of Saint Ebba's in a voice that cracks on the first word and then does not: 'I do. I know cause. I have a wife. Her name is Hetty and she makes bonnets in Quay Lane and we have a son called Jack. I'm sorry, Miss Cherrett. I'm so sorry. I should have said it the first time.' He sits down. Nobody breathes. Then, from the back of the church, where the servants and the chairmen stand, a man's voice says, 'Well done, sir,' and it is Big Lanyon.".
  }
  Relation rupertSpoke(group).
  Action hetty_speaks(actor: group, site: place) "Bring Hetty Quiney forward with the baby" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ebba_nave) and inPause() and following(hetty, actor) and not bannsStopped(ebbas).
    Time 2 minutes.
    On success { Assert bannsStopped(ebbas). Assert bannsWithdrawn(ebbas). Assert stoppedByHetty(ebbas). Assert scandal(wenlock). Retract following(hetty, actor). Assert at(hetty, ebba_nave). }
    Result "Hetty Quiney walks up the aisle of Saint Ebba's in her best bonnet with Jack on her hip, and stops by the Wenlock pew, and says to Mr Pyne quite clearly: 'He's mine. We were married in Bristol, two years since, and that's his son.' Jack, seeing his father, holds out his arms and shouts. Rupert takes him. It is the only thing he could have done, and he does it.".
  }
  Action ismay_stands(actor: group, site: place) "Stand up beside Ismay, if she means to say anything" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ebba_nave) and inPause() and at(ismay, ebba_nave) and ismayBrave(ismay) and not bannsStopped(ebbas) and not ismayObjected(ebbas).
    Time 2 minutes.
    On success { Assert ismayObjected(ebbas). }
    Result "You stand up, and after a moment, so does Ismay, beside you, with her prayer book shut on her finger. 'I don't consent,' she says, to Mr Pyne, to the church, to her grandmother. 'I'm sorry, Mr Wenlock. I don't consent to it.' Mr Pyne looks at her with enormous sympathy. 'Miss Cherrett,' he says gently, 'that is not an impediment. That is an opinion.' And somebody laughs, and then the whole church laughs, not unkindly, and Ismay goes scarlet and does not sit down.".
  }
  // Ismay's opinion, said aloud in church, makes Rupert ashamed to be less brave than she was, if he has confessed to
  // anyone at all.
  Rule rupert_shamed at ebba_nave when ismayObjected(ebbas) and inPause() and rupertConfessed(rupert) and at(rupert, ebba_nave) and not bannsStopped(ebbas)
    says "Rupert Wenlock looks at the girl standing scarlet in the Cherrett pew, and stands up too, hauled up by something. 'It's not an opinion,' he says. 'It's not only an opinion. I have a wife.'" {
    Assert bannsStopped(ebbas). Assert bannsWithdrawn(ebbas). Assert stoppedByRupert(ebbas). Assert rupertSpoke(rupert). }
  // Nobody speaks: the pause ends, and the banns are good.
  Rule pause_ends at ebba_nave when readingBegun(ebbas) and not bannsStopped(ebbas) and not bannsWithdrawn(ebbas) and watch(clock) > readingWatch(ebbas) + 2 and not bannsDone(ebbas)
    says "Mr Pyne lets out his breath. Nobody has said anything. He goes on, a little unsteadily, to the second lesson; and after the service, at the door, Lady Wenlock shakes Mrs Cherrett's hand with two fingers and says, 'Monday, then.'" {
    Assert bannsDone(ebbas). }
  Rule pause_ends_away when thirdDay() and hour(clock) >= 12 and not bannsStopped(ebbas) and not bannsWithdrawn(ebbas) and not bannsDone(ebbas) { Assert bannsDone(ebbas). }
  // After a stopped reading, everyone goes home; Rupert goes down the hill to Quay Lane.
  Rule reading_scatters when bannsStopped(ebbas) and thirdDay() and hour(clock) >= 12 and not rupertAway(rupert) and not grandmother(lady_wenlock) { Assert rupertAway(rupert). Assert at(rupert, hetty_shop). }
  Observe rupert_with_hetty at hetty_shop when rupertAway(rupert) and at(rupert, hetty_shop) "Rupert Wenlock is behind Hetty's counter in his shirt-sleeves with the baby on his knee, and his hat on the peg, and he does not get up when you come in, because he is home.".

  // ── Monday at ten ─────────────────────────────────────────────────────────────────────────────────────────────────
  // The banns read and unanswered, the wedding is at ten on the fourth morning. Hetty is on the steps with Jack, and
  // Rupert cannot walk past them. It is not a scene she meant to make; it is the scene there is.
  Query weddingNow() means fourthDay() and hour(clock) == 10.
  Relation weddingBroken(place).
  Rule wedding_on_steps when weddingNow() and bannsDone(ebbas) and not bannsWithdrawn(ebbas) and not weddingBroken(ebbas) {
    Assert weddingBroken(ebbas). Assert bannsWithdrawn(ebbas). Assert scandal(wenlock). Assert ismayJilted(ismay). Assert at(hetty, abbey_yard). }
  Relation ismayJilted(group).
  Rule wedding_told at abbey_yard when weddingBroken(ebbas) and weddingNow() and not spread(wedding_told) says "At ten o'clock the Abbey Yard is full of the Season come to see the canal money marry the peerage. On the steps of Saint Ebba's a young woman in a good bonnet is standing with a baby on her hip, not making a scene; only standing. Rupert Wenlock comes across the yard in a blue coat with a flower in it, and sees her, and stops. He stands there in front of the whole Season until the sexton coughs. Then he goes up the steps, past the church door, to her, and takes the baby, and stands beside her; and the Season understands, all at once, the way a crowd does. Inside the church Ismay Cherrett is waiting at the altar on her grandmother's arm, and Mr Pyne has to go and tell her." { Assert spread(wedding_told). }
  Entity wedding_told: fact "the wedding at Saint Ebba's".

  // ── A licence from Orm ────────────────────────────────────────────────────────────────────────────────────────────
  // The bishop's surrogate at Orm grants marriage licences, without banns, for a fee; his clerk at the gate will sell, for ten coin,
  // one with the names left blank, for a consideration, which is not lawful and is done every day.
  Kind licence_kind "a marriage licence from the surrogate at Orm, with the names left blank" is treasure worth 0 weighing 0.
  Person surrogate_clerk "the surrogate's clerk" at orm_gate {
    Role "a clerk at a little desk by the wicket of Orm's gate, with a stack of printed forms". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Greets "The clerk at the little desk by the wicket looks up. 'Licences,' he says. 'Marriage, without banns, from the bishop's surrogate. Names, parishes, a sworn statement of no impediment, eight shillings.' He looks at you more closely. 'Or ten, and the names left blank, and no questions, and I never saw you.'".
    Sells licence_kind for 10 coin from 1.
  }
  Rule clerk_hours when hour(clock) >= 9 and hour(clock) < 17 and not at(surrogate_clerk, orm_gate) { Assert at(surrogate_clerk, orm_gate). }
  Rule clerk_home when (hour(clock) >= 17 or hour(clock) < 9) and not at(surrogate_clerk, limbo) { Assert at(surrogate_clerk, limbo). }
  // Given to Mr Pyne, a licence marries whichever couple it is filled in for, at nine the next morning, in Saint Ebba's.
  Relation pyneHasLicence(group). Relation licensedFor(entity). Relation married(entity). Measure weddingDay(group).
  Entity couple_kit: fact "Kit Danby and Ismay Cherrett". Entity couple_rob: fact "Rob Cherrett and Celia Carth". Entity couple_mopsa: fact "you and Mopsa Gedge".
  Event pyne_takes_licence near pyne when keeps(pyne, ?l) and itemKind(?l, licence_kind) and not pyneHasLicence(pyne) "Mr Pyne turns the licence over. 'The names are blank,' he says. He looks at the surrogate's seal, which is real, and at the blank spaces, which are also real, and goes a little pink. 'I'm told this is done,' he says. 'I'm told it's done every day.' He dips his pen. 'Whose?'" then {
    Assert pyneHasLicence(pyne). }
  Topic licence_kit with pyne "Ask Mr Pyne to fill in the licence for Kit Danby, chairman, and Ismay Cherrett" when pyneHasLicence(pyne) and not licensedFor(couple_rob) and not licensedFor(couple_mopsa) and not licensedFor(couple_kit) and (kitEngaged(kit) or cherrettBlessesKit(cherrett)) and bannsWithdrawn(ebbas) once {
    Says "Mr Pyne writes the names in his careful hand. 'Christopher Danby, chairman, of Stall Street. Ismay Cherrett, spinster, of this parish.' He sands it. 'Nine o'clock tomorrow,' he says. 'Tell them to come early. I'll unlock the side door.' He smiles, for the first time since you have known him, as if he had done something wicked and enjoyed it.".
    On discuss { Assert licensedFor(couple_kit). Set weddingDay(pyne) to dayN(hessel_town) + 1. }
  }
  Topic licence_rob with pyne "Ask Mr Pyne to fill in the licence for Rob Cherrett and Celia Carth" when pyneHasLicence(pyne) and not licensedFor(couple_rob) and not licensedFor(couple_mopsa) and not licensedFor(couple_kit) and celiaOut(celia) and robCeliaSpoke(rob) once {
    Says "'Celia Carth.' Mr Pyne's pen stops. 'Of Carth House? The girl nobody has seen?' He writes it anyway. 'Nine o'clock tomorrow. If her father comes with a sword I shall read the service faster.'".
    On discuss { Assert licensedFor(couple_rob). Set weddingDay(pyne) to dayN(hessel_town) + 1. }
  }
  Topic licence_mopsa with pyne "Ask Mr Pyne to fill in the licence for yourself and Mopsa Gedge" when pyneHasLicence(pyne) and not licensedFor(couple_rob) and not licensedFor(couple_mopsa) and not licensedFor(couple_kit) and mopsaYes(party) once {
    Says "Mr Pyne writes your name, and Mopsa's, and looks up. 'Miss Gedge,' he says. 'Who reads at the back of the Rooms. She told me once my sermon on the talents was the only one she'd ever stayed awake through.' He sands it. 'Nine o'clock tomorrow.'".
    On discuss { Assert licensedFor(couple_mopsa). Set weddingDay(pyne) to dayN(hessel_town) + 1. }
  }
  Rule licence_wedding when licensedFor(?c) and not married(?c) and dayN(hessel_town) >= weddingDay(pyne) and hour(clock) >= 9 and hour(clock) < 12 { Assert married(?c). }
  Rule wedding_seen at ebba_nave when married(?c) and hour(clock) == 9 and not spread(?c) says "Nine o'clock in the morning at Saint Ebba's: the side door, Mr Pyne in a surplice too big for him, the pew-opener and the sexton for witnesses, and {?c} married in a quarter of an hour, which is as long as it needs to be." { Assert spread(?c). }
  Entity licence_wedding_told: fact "the wedding by licence".
}

data/adventures/hessel/carth.kyr:
Module hessel "The Banns at Hessel" {
  // ── A Winter in Carth ─────────────────────────────────────────────────────────────────────────────────────────────
  // Nine winters ago, in the great snow, Sir Gervase Carth in a jealous rage shut his wife out of the house at night,
  // and in the morning she was gone. He gave out that she was dead. He has kept the house in that night ever since:
  // the shutters closed, the fires lit day and night, the clocks stopped at two, the household in furs. Dr Hartopp
  // attends his daughter's "weak lungs" and prescribes the heat. Every night at two someone knocks, once. He sits up
  // for it in the hall in his greatcoat, and has never opened the door. Lady Carth lived. She washes linen in the Old
  // Town under the name of Nan Bellamy, and the housekeeper has carried her word of her daughter every week for nine
  // years. She will come in if he opens the door himself; not if anybody else does.
  Entity carth: group "the Carths".
  Observe carth_hall_scene at carth_hall when not carthReunited(carth) "The heat hits you in the doorway like a hand. The hall of Carth House is lit by candles, day and night; a fire roars in a grate as big as a cart, and another at the stair-foot; every shutter is closed and barred. On the wall a long-case clock says two o'clock. So does the one on the stair. So, you will find, do all of them. By the front door, facing it, stands one high-backed chair, with a greatcoat over its arm.".
  Observe carth_hall_night at carth_hall when carthReunited(carth) and not carthOpened(carth) "The hall of Carth House with its front door standing open on the night: the cool air coming in, the candles leaning, and the long-case clock still saying two, for the last time.".
  Observe carth_hall_open at carth_hall when carthOpened(carth) "The hall of Carth House with its shutters open: daylight on the floor for the first time in nine years, showing every scuff. The fires are out. Somebody has started the long-case clock, and it is wrong, and nobody cares.".
  Observe drawing_scene at carth_drawing when not celiaOut(celia) and not carthReunited(carth) "The drawing room is upstairs, and hotter. Furs on every chair; a fire; candles; the shutters closed, except one, which has a crack in it that someone has worn with a fingertip. Books everywhere: a girl's room, a scholar's room, a prison.".
  Observe drawing_empty at carth_drawing when celiaOut(celia) and not carthReunited(carth) "The drawing room, with its fires and furs, and nobody in it; on the floor by the window, a fur cap.".
  Observe study_scene at carth_study when true "Sir Gervase's study keeps one rule: nothing is moved. A pen lies across the blotter at the angle of a man called away, the gun-case is shut on a gun nobody has cleaned, and over the fire a portrait stands under a cloth that is dusted every week and never lifted.".
  Observe kitchen_scene at carth_kitchen when not visitedBefore(carth_kitchen) "The kitchen of Carth House: as hot as a baker's, and as clean as a chapel. Coal stacked to the ceiling. A dresser of blue plates. A rocking-chair by the range with a Bible on it, open, face down.".
  Observe kitchen_again at carth_kitchen when visitedBefore(carth_kitchen) "The kitchen of Carth House: the heat, the coal, the blue plates, the Bible on the rocking-chair.".
  Observe cellar_scene at coal_cellar when true "The coal cellar is black and low and as hot as the kitchen wall behind it, the coal heaped to the vault so that you go bent, with your hand on the slope. At the back, where the heap gives out, a door has a line of light under it, thin as a drawn knife.".
  Observe area_scene at carth_area when not carthReunited(carth) "The area of Carth House, below the street: flagstones, a dustbin, the kitchen door, and a round iron plate in the pavement over your head where the coal goes in, which from down here is a hatch in the vault with a rusted hasp.".

  // ── The ways in ───────────────────────────────────────────────────────────────────────────────────────────────────
  Thing front_door "the front door of Carth House" on carth_front {
    State shut blocking "The front door of Carth House is shut, and its knocker is tied up in a black glove.".
    State open "The front door of Carth House stands open, and the heat comes out of it like a dog.".
    Change open_inside "Draw the bolts of the front door" from shut to open at carth_hall.
  }
  Initially Assert state(front_door, shut).
  Thing area_gate "the area gate" on area_steps {
    State chained blocking "The gate at the top of the area steps is chained, and the chain is padlocked.".
    State open "The area gate stands open.".
    Change pick_area "Pick the padlock on the area chain" from chained to open needing lockwork.
    Change wrench_area "Wrench the area chain off its staple" from chained to open needing brawn.
  }
  Initially Assert state(area_gate, chained).
  // The coal-man and the tradesmen come at eight, and the gate stands open for them for the hour.
  Rule area_morning when hour(clock) == 8 and state(area_gate, chained) { Assert state(area_gate, open). Assert areaOpenedByDay(carth). }
  Rule area_locked when hour(clock) == 9 and state(area_gate, open) and areaOpenedByDay(carth) { Assert state(area_gate, chained). Retract areaOpenedByDay(carth). }
  Relation areaOpenedByDay(group).
  Thing kitchen_bolt "the kitchen door's bolt" on kitchen_door {
    State bolted blocking "The kitchen door is bolted on the inside.".
    State drawn "The kitchen door is open, and the kitchen's heat stands in it.".
    Change unbolt "Draw the kitchen bolt" from bolted to drawn at carth_kitchen.
  }
  Initially Assert state(kitchen_bolt, bolted).
  Discovery coal_hole_known "From the area of Carth House, the coal-hole in the vault over the flags opens on the coal cellar, and the coal cellar on the kitchen. Its hasp is rusted; it could be forced, or picked." {
    Found by searching carth_area "Above you in the vault, where the coal comes down, is an iron hatch with a rusted hasp; the coal goes in there, and the coal goes to the kitchen.".
  }
  Thing drawing_window "the drawing-room window" on carth_window is scenery {
    State shuttered blocking "The drawing-room shutters are barred.".
    State ajar "One shutter of the drawing-room window over the area stands open a hand's breadth, with a candle behind it.".
    State nailed blocking "The drawing-room shutters at Carth House have been nailed across with laths.".
  }
  Initially Assert state(drawing_window, shuttered).
  Relation windowNailed(group).

  // ── Mrs Brannagh ──────────────────────────────────────────────────────────────────────────────────────────────────
  Person brannagh "Mrs Brannagh" at carth_kitchen {
    Role "the housekeeper of Carth House, in black, with a Bible in her apron pocket and coal-dust in the lines of her hands". Ancestry human. Peaceable. Pronouns she. Manner grim.
    Greets "The housekeeper does not get up. 'This is a private house,' she says. 'Nobody comes into it. You'll have a reason, or you'll go.'".
    Greets again "Mrs Brannagh looks at you over her spectacles.".
    Wants poem_kind.
  }
  Measure brannaghTrust(group).
  // At eight she is in the area, taking in the coal and the milk, while the gate stands open for the hour.
  Rule brannagh_area when hour(clock) == 8 and not at(brannagh, carth_area) and not carthReunited(carth) { Assert at(brannagh, carth_area). }
  Rule brannagh_kitchen when hour(clock) != 8 and not at(brannagh, carth_kitchen) { Assert at(brannagh, carth_kitchen). }
  Observe brannagh_in_area at carth_area when at(brannagh, carth_area) "Mrs Brannagh is in the area in a black shawl, counting sacks of coal off a cart as the coal-man drops them through the hole, and does not look at you.".
  Topic brannagh_why with brannagh "Ask Mrs Brannagh why the house is kept like this" when true once {
    Says "Mrs Brannagh closes her Bible on her finger. 'Because the master wishes it,' she says. 'Because Dr Hartopp says Miss Celia's chest won't stand the least draught. Because nine years ago there was a great snow, and something happened in it, and the master would sooner it went on being that night for ever than that it should ever be the morning after.' She opens the Bible again. 'That's three reasons. Only one of them's true, and it's not Dr Hartopp's.'".
    On discuss { Increase brannaghTrust(brannagh) by 1. }
  }
  Topic brannagh_knock with brannagh "Ask Mrs Brannagh who knocks at two in the morning" when brannaghTrust(brannagh) >= 2 and not knows(actor, nan_is_lady) once {
    Says "Mrs Brannagh takes off her spectacles, which she has never done in front of you. 'Her ladyship,' she says. 'Who else? He shut her out in the snow in her nightgown because a man had written her a letter, and the letter was from her brother. She walked down the hill to the laundries and they took her in. Nine years she's washed the Season's sheets under his windows, and every Thursday I've gone down with the linen and told her how Miss Celia does. What she reads. How tall she is.' She puts the spectacles back. 'And every night at two she comes up and knocks once, so that he'll know. And he sits there and doesn't open it. And she goes away.' She looks at you hard. 'She'll come in if he opens it himself. She's told me so. Not if I do, nor you. Him.'".
    On discuss { Assert knows(actor, nan_is_lady). Assert knows(actor, nan_terms). }
  }
  Discovery nan_is_lady "Nan Bellamy, the laundress, is Lady Carth. Sir Gervase shut her out of Carth House in the great snow nine years ago over a letter that was from her brother; she was taken in at the laundries, and has knocked at the door once every night since, at two.".
  Discovery nan_terms "Lady Carth will come into Carth House if Sir Gervase opens the door to her himself; not if anybody else does.".
  Event brannagh_poem near brannagh when keeps(brannagh, ?p) and itemKind(?p, poem_kind) and poemGood(rob) and not celiaHasPoem(celia) "Mrs Brannagh unfolds the paper and reads it with her lips moving, the whole thing, slowly. When she has done she reads it again. 'He's seen her,' she says. 'Whoever wrote this has seen her. The candle, and her hand.' She folds it small. 'I'll take it up with her supper.' And then, quite differently: 'Nobody's written Miss Celia anything in her life.'" then {
    Assert celiaHasPoem(celia). Increase brannaghTrust(brannagh) by 1. }
  Event brannagh_scorns near brannagh when keeps(brannagh, ?p) and itemKind(?p, poem_kind) and not poemGood(rob) "Mrs Brannagh reads two lines, and puts the paper in the range. 'Lady of the Lattice,' she says. 'Pale and pensive. She's not pale, she's yellow, from the candles; and she's not pensive, she's bored to death.' She pokes the fire. 'Tell your poet to look at her before he writes about her.'".
  Topic brannagh_hartopp with brannagh "Tell Mrs Brannagh that Dr Ottery says there is nothing the matter with Miss Celia's lungs" when knows(actor, celia_well) and not brannaghKnowsWell(brannagh) once {
    Says "'Nothing,' says Mrs Brannagh. 'Nothing the matter.' She sits very still in the rocking chair. 'Nine years of coal,' she says. 'Nine years of Dr Hartopp's guineas.' Then she gets up, and goes to the range, and for the first time since you have known her she lets the fire go down.".
    On discuss { Assert brannaghKnowsWell(brannagh). Increase brannaghTrust(brannagh) by 1. }
  }
  Relation brannaghKnowsWell(group).
  // With her goodwill, the kitchen door is open to the company, and she will take it up the back stair.
  Rule brannagh_unbolts when brannaghTrust(brannagh) >= 2 and state(kitchen_bolt, bolted) and at(party, carth_area) { Assert state(kitchen_bolt, drawn). }

  // ── Celia ─────────────────────────────────────────────────────────────────────────────────────────────────────────
  Person celia "Celia Carth" at carth_drawing {
    Role "a girl in a fur cap, very pale and very bored, with a book" when not celiaOut(celia).
    Role "a girl in a borrowed cloak, out of doors, blinking at everything" when celiaOut(celia).
    Ancestry human. Peaceable. Pronouns she. Manner cheerful.
    Greets "The girl in the fur cap looks up from her book and stares at you as if you had come in through the wall, which in a sense you have. 'Oh,' she says. 'Are you real? Nobody comes. Sit down. No: tell me something. Anything. What is it like out there?'".
    Greets again "Celia Carth puts her book down at once.".
  }
  Relation celiaOut(group). Relation celiaHasPoem(group). Relation celiaWants(group). Relation celiaAway(group).
  Discovery celia_book "Celia Carth has read everything and seen nothing: nine years behind the shutters of Carth House.".
  Observe celia_reading at carth_drawing when at(celia, carth_drawing) and not seenOnce(celia_book) "The girl in the fur cap is reading Ovid by three candles, with her feet up on the fender and a treatise on bees open on the floor beside her and the voyages of Anson under the treatise. She turns the pages fast, as if somebody might take them away." teaches celia_book.
  Topic celia_outside with celia "Tell Celia what it is like outside" when not celiaOut(celia) once {
    Says "You tell her: the Crescent, the lawn, the Season walking on it; the Pump Room, the King's Bath full of people standing in hot water in hats; the chairmen; the Beacon; the warm wind. She listens with her hands round her knees. 'Warm,' she says at the end. 'Is it warm? Father says it's winter. Father says it's always winter for me, because of my chest.' She looks at the fire, and at the shuttered window. 'Brannagh says it's the Season. I think Brannagh's right. I can smell the lime trees, at the crack in the shutter, at night.'".
    On discuss { Assert celiaWants(celia). }
  }
  Topic celia_mother with celia "Ask Celia about her mother" when true once {
    Says "'She died in the great snow,' says Celia, as if reciting. 'When I was nine. Father says.' She turns the fur cap round in her hands. 'I don't remember a funeral. I remember her in the hall in her nightgown, and Father shouting, and a door, and in the morning snow, and then nothing.' She puts the cap back on. 'Somebody knocks at two. Every night. Father sits up for it in the hall. I'm not supposed to know.'".
  }
  Topic celia_poem with celia "Ask Celia whether she had the poem" when celiaHasPoem(celia) once {
    Says "Celia goes pink under the candle-yellow. 'It was about me,' she says. 'It said about the candle. And my hand on the glass. Nobody's ever.' She takes it out of the book, where she has been using it to mark Ovid. 'Who is he? Is he the one on the lawn? There's someone lies on the lawn in the afternoons. I've seen him through the crack.' She is very serious. 'I'd like to meet him. I'd like to meet anyone.'".
    On discuss { Assert celiaWants(celia). Assert celiaLikesRob(celia). }
  }
  Relation celiaLikesRob(group).
  // Once she has had a good poem, at dusk she opens the shutter a hand's breadth and stands at it with a candle; unless
  // the shutters are nailed.
  Rule window_opens when celiaHasPoem(celia) and hour(clock) >= 19 and hour(clock) < 23 and state(drawing_window, shuttered) and not windowNailed(carth) and not celiaOut(celia) { Assert state(drawing_window, ajar). }
  Rule window_closes when (hour(clock) >= 23 or hour(clock) < 19) and state(drawing_window, ajar) { Assert state(drawing_window, shuttered). }
  // What can be seen of her from the Crescent, which is what a poem can be made of.
  Discovery celia_candle "The girl in Carth House comes to the one unbarred shutter at dusk, with a candle.".
  Discovery celia_hand "Late at night the girl at the Carth House shutter puts her hand to the glass.".
  Observe celia_at_dusk at crescent when hour(clock) >= 19 and hour(clock) < 22 and not celiaOut(celia) and not windowNailed(carth) and not seenOnce(celia_candle) "At the end of the Crescent, in the dark front of Carth House, one shutter has a crack of yellow light in it, and in the crack, holding a candle, a girl in a fur cap is looking out at the lawn." teaches celia_candle.
  Observe celia_at_night at crescent when hour(clock) >= 22 and not celiaOut(celia) and not windowNailed(carth) and not seenOnce(celia_hand) "In the crack of the shutter at Carth House the candle is lower. The girl has put her hand flat on the glass, palm out, and is holding it there, as if feeling the night for warmth." teaches celia_hand.

  // ── Rob's poem ────────────────────────────────────────────────────────────────────────────────────────────────────
  // Made of what someone has actually seen of her. Rob has seen a face at a window and written eleven poems about a
  // Pale and Pensive Maid. A poem with the candle, the hand, the fur cap and the Ovid in it is a different thing.
  Measure poemLines(group). Relation poemGood(group). Relation poemMade(group).
  Relation lineCandle(group). Relation lineHand(group). Relation lineBook(group).
  Kind poem_kind "Rob Cherrett's poem" is treasure worth 0 weighing 0.
  Item rob_poem "Rob's poem" is poem_kind at limbo.
  Topic rob_line_candle with rob "Give Rob a line: not a pale maid, but a girl with a candle at a crack in a shutter, looking at the grass" when knows(actor, rob_loves_window) and knows(actor, celia_candle) and not lineCandle(rob) and not poemMade(rob) once {
    Says "Rob stops crossing things out. 'Looking at the grass,' he says. 'Not at the sky. At the grass.' He writes, and does not cross out. 'Because she's never been on it,' he says, not to you.".
    On discuss { Assert lineCandle(rob). Increase poemLines(rob) by 1. }
  }
  Topic rob_line_hand with rob "Give Rob a line: her hand flat on the glass at night, feeling for the warmth" when knows(actor, rob_loves_window) and knows(actor, celia_hand) and not lineHand(rob) and not poemMade(rob) once {
    Says "Rob puts his own hand flat on the grass without seeming to know he has done it. 'Feeling for the warmth,' he says. 'Oh.' He writes, and crosses out, and writes. 'It's warm,' he says. 'It's the Season. It's warm, and she doesn't know.'".
    On discuss { Assert lineHand(rob). Increase poemLines(rob) by 1. }
  }
  Topic rob_line_book with rob "Give Rob a line: a girl in a fur cap reading Ovid by three candles, with her feet on the fender" when knows(actor, rob_loves_window) and knows(actor, celia_book) and not lineBook(rob) and not poemMade(rob) once {
    Says "Rob stares at you. 'Ovid,' he says. 'In a fur cap.' He begins to laugh, and then to write, very fast, and does not stop laughing. 'Not pale,' he says. 'Not pensive. Reading Ovid with her feet up. Oh, I'd like her.' He writes. 'I like her.'".
    On discuss { Assert lineBook(rob). Increase poemLines(rob) by 2. }
  }
  Topic rob_finish with rob "Tell Rob the poem is finished; write it fair" when knows(actor, rob_loves_window) and not poemMade(rob) and poemLines(rob) >= 1 once {
    Says "Rob writes it fair on a clean leaf of his pocket-book, tears it out, folds it, and holds it a moment against his chest. Then he puts it on the grass at your feet, like a dog with a bird. 'You take it,' he says. 'I can't. I'd die.'".
    On discuss { Assert poemMade(rob). Assert poemGood(rob). Assert at(rob_poem, crescent). }
  }
  Topic rob_finish_bad with rob "Tell Rob to send the Lady of the Lattice as it is" when knows(actor, rob_loves_window) and not poemMade(rob) and poemLines(rob) == 0 once {
    Says "'As it is?' Rob looks at the Lady of the Lattice with deep doubt, and then shrugs, and tears it out and folds it. 'Thou Pale and Pensive Maid,' he says. 'Well. Perhaps she likes that sort of thing.' He puts it on the grass at your feet. 'You take it. I'd die.'".
    On discuss { Assert poemMade(rob). Assert at(rob_poem, crescent). }
  }
  Action climb_to_window(actor: group, site: place) "Climb the area railings at dusk, and slip Rob's poem through the crack in the shutter" {
    Description "Over the railings, onto the sill. The Crescent is full of windows.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, crescent) and carries(actor, rob_poem) and hour(clock) >= 19 and hour(clock) < 23
      and not celiaHasPoem(celia) and not windowNailed(carth) and not triedWindow(actor).
    Time 1.
    Resolve check(actor, climbing, dc_fair).
    On success { Assert celiaHasPoem(celia). Assert climbedToWindow(actor). }
    On failure { Assert triedWindow(actor). }
    Result "Up the area railings, a foot on the spikes, a hand on the sill, and there is the crack in the shutter and a candle behind it, and an eye. You push the folded paper through. A hand takes it. The candle goes away from the crack, and comes back, and you hear, very faintly, through the glass, a girl laughing; and you drop down onto the pavement and walk off along the Crescent as if you lived there.".
    Otherwise "Your foot slips on the railings' spikes and you come down into the area with a noise like a dropped coal-scuttle, and a dog starts barking in the next house, and the candle at the crack goes out. You get away before anyone comes.".
  }
  Relation triedWindow(group). Relation climbedToWindow(group).
  // Rob, once there is a poem with her name in it, keeps the lawn till the window opens: and once it is open, they talk.
  Relation robCeliaSpoke(group).
  Rule rob_waits when celiaHasPoem(celia) and celiaLikesRob(celia) and hour(clock) >= 19 and hour(clock) < 23 and not at(rob, crescent) and not robAway(rob) and not atBall(rob) and not celiaOut(celia) and not following(rob, party) and not travelsWith(rob, party) { Assert at(rob, crescent). }
  Rule rob_and_celia when state(drawing_window, ajar) and at(rob, crescent) and celiaLikesRob(celia) and not robCeliaSpoke(rob) { Assert robCeliaSpoke(rob). }
  Observe rob_celia_talking at crescent when robCeliaSpoke(rob) and state(drawing_window, ajar) and at(rob, crescent) "Rob Cherrett is standing in the area of Carth House on an upturned dustbin, holding on to the railings, talking up at the open crack in the shutter; and from behind it a girl's voice is talking down to him, both of them at once, both of them laughing.".

  // ── Sir Gervase ───────────────────────────────────────────────────────────────────────────────────────────────────
  Person gervase "Sir Gervase Carth" at carth_study {
    Role "a big grey man in a greatcoat, with a face that has not seen the sun". Ancestry human. Calling warrior. Level 3. Pronouns he. Manner grim.
    Temperament territorial. Lair carth_hall.
    Warns "The big grey man in the greatcoat is on his feet with a sword in his hand that he did not have a moment ago. 'Get out of my house,' says Sir Gervase Carth, very quietly. 'Get out of my house, or I will kill you, here, on my own floor, and the law will thank me.' He means it. The door you came by is behind you.".
    Comes "Sir Gervase comes at you across his own hall, with the sword, and the heat, and nine years of nobody coming.".
    Greets "Sir Gervase looks at you from his chair without getting up. 'You're the first person through that door in nine years who wasn't Hartopp,' he says. 'Sit down. Don't open anything.'".
    Greets again "Sir Gervase does not get up.".
  }
  // By day in his study; from ten at night in the hall, in the chair facing the door, until it is light.
  Rule gervase_study when hour(clock) >= 7 and hour(clock) < 22 and not at(gervase, carth_study) and not carthReunited(carth) and not gervaseAway(gervase) { Assert at(gervase, carth_study). }
  Rule gervase_hall when (hour(clock) >= 22 or hour(clock) < 7) and not at(gervase, carth_hall) and not carthReunited(carth) and not gervaseAway(gervase) { Assert at(gervase, carth_hall). }
  Relation gervaseAway(group). Relation received(group). Relation gervaseTold(group). Relation gervaseKnows(group).
  Relation gervaseSatWith(group). Relation celiaWell(group).
  Query gervasePrepared() means gervaseTold(gervase) and gervaseKnows(gervase).
  Rule received_tolerated when received(party) and not tolerates(gervase, party) and not gervaseFought(gervase) { Assert tolerates(gervase, party). }
  Relation gervaseFought(group).
  Rule gervase_fought when not able(gervase) and not gervaseFought(gervase) { Assert gervaseFought(gervase). }
  // He does not kill a beaten intruder: he throws them out into the Crescent, and nails the shutters, and knows the
  // face after. What happens is told where the company comes round.
  Initially Assert takesPrisoners(gervase).
  Relation thrownOut(group). Measure cameRound(place).
  Rule gervase_throws_out when captured(gervase, party) and at(party, ?p) {
    Retract captured(gervase, party). Retract assails(gervase, party). Assert thrownOut(party). Set cameRound(crescent) to watch(clock).
    Retract at(party, ?p). Assert at(party, crescent). Assert windowNailed(carth). Assert state(drawing_window, nailed). }
  Rule thrown_told at crescent when thrownOut(party) and watch(clock) > cameRound(crescent) and not spread(thrown_told)
    says "You come round on the pavement of the Crescent, in the dark, with your head ringing and your coat torn, and the front door of Carth House shut behind you. Somebody upstairs is hammering: laths across the drawing-room shutters, nail after nail. In the morning the whole Crescent will say Sir Gervase Carth threw a housebreaker into the street, and that he did not call the watch." { Assert spread(thrown_told). }
  Entity thrown_told: fact "thrown out of Carth House".
  // Found in his house, the company has the length of his warning to stop his sword with something that is true. What
  // he did is the only thing in the world that can reach him; and the one thing he does not know is what the letter was.
  Action tell_brother(actor: group, site: place) "Tell him the letter in his wife's work-box was from her brother" {
    Description "If it is true, it is the one thing that will reach him.".
    Requires able(actor) and company(actor) and at(actor, site) and at(gervase, site) and (at(actor, carth_hall) or at(actor, carth_study))
