  // Orm gate: the turn, and the choice.
  Relation ottTurned(group).
  Event ottery_turn at orm_gate when at(party, orm_gate) and following(ottery, party) and not ottTurned(party) "At the grey gate of Orm, under MEDICUS CURAT, NATURA SANAT, Ottery stops, and puts down his bag, and turns round to you. 'I've been thinking about what you said,' he says, 'all the way over the down.' And he tells you what you said: about the dying woman at the stile, and the shepherd at the hut, and the lie at the gibbet, every word, in your own voice, which is an uncomfortable thing to hear. 'So,' he says. 'You've a choice now, and it's the same choice. You can walk in there with me and tell the College I'm a man of good character, which is a lie, I'm a man of very bad character and a good physician. Or you can let me go on north, where nobody's heard of me, and I'll physic shepherds till I drop. Or you can take me back down to Hessel, struck off, and I'll do what I can for whoever will have me without a licence.' He picks up his bag. 'I know what I'd choose. I'm not telling you.'" then { Assert ottTurned(party). }
  Observe ottery_turn_truth at orm_gate when ottTurned(party) and saidTruth(party) and following(ottery, party) and not otteryDecided(ottery) "Ottery is watching you with his head on one side. 'You said the truth,' he says. 'At the stile. You said she had a right to it. Mind you remember that, in there, if we go in.'".
  Observe ottery_turn_comfort at orm_gate when ottTurned(party) and saidComfort(party) and following(ottery, party) and not otteryDecided(ottery) "Ottery is watching you with his head on one side. 'You said let her be happy,' he says. 'At the stile. You said what good is the truth to the dying. I've been chewing on it all the way. I'm sixty, and the College is going to tell me something I don't want to hear, and I find I'd like very much not to hear it.'".
  Observe ottery_turn_depends at orm_gate when ottTurned(party) and saidDepends(party) and following(ottery, party) and not otteryDecided(ottery) "Ottery is watching you with his head on one side. 'Ask her what she wants to know, you said,' he says. 'Well. Ask me.'".
  Query beforeCollege() means secondDay() and hour(clock) < 12.
  Action stand_witness(actor: group, site: place) "Go in with Dr Ottery, and stand witness to his good character before the College" {
    Description "The College sits at noon.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, orm_gate) and following(ottery, actor) and beforeCollege() and not otteryDecided(ottery).
    Time 12.
    On success { Assert otteryLicensed(ottery). Assert otteryDecided(ottery). Assert stoodWitness(actor). }
    Result "The College of Physicians sits in a long room that smells of beeswax and old men, and keeps you both standing. They have a great many letters. You are asked whether you know Dr Jonas Ottery to be of good character, and you say what you say, and the President looks at you over his spectacles exactly as Ottery does, and you realise they were students together. At two o'clock they give him back his licence, with a reprimand for intemperate language to a governor of the Hospital of the Waters, read aloud. Outside on the step Ottery puts the paper in his bag without looking at it. 'Well,' he says. 'Now I can be turned off again properly.' He shakes your hand. 'The carrier goes down to Hessel at three. I'll buy you a pie.'".
  }
  Relation stoodWitness(group).
  Action let_ottery_go(actor: group, site: place) "Let Dr Ottery go on north, where nobody has heard of him" {
    Grave "He will not come back to Hessel.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, orm_gate) and following(ottery, actor) and not otteryDecided(ottery).
    Time 2 minutes.
    On success { Assert otteryGone(ottery). Assert otteryDecided(ottery). Retract following(ottery, actor). Assert at(ottery, limbo). }
    Result "Ottery looks at you, and nods, and picks up his bag. 'North,' he says. 'There's sheep up there, and shepherds, and children with fevers, and not a College for a hundred miles.' He shakes your hand, hard. 'Tell Abigail Cherrett from me to stop drinking that muck.' And he goes off along the wall of Orm toward the north road, in his slept-in coat, not looking back, getting smaller.".
  }
  Action bring_ottery_back(actor: group, site: place) "Take Dr Ottery back to Hessel, without going in" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, orm_gate) and following(ottery, actor) and not otteryDecided(ottery).
    Time 2 minutes.
    On success { Assert otteryFugitive(ottery). Assert otteryStruck(ottery). Assert otteryDecided(ottery). }
    Result "'Back,' says Ottery. 'Struck off in my absence, unlicensed, and back to the ward that's turned me off.' He looks at the College's grey gate, and laughs. 'Well, they can't strike me off it twice,' he says. 'The carrier goes at three. I'll buy you a pie.'".
  }
  // Too late for the College, whatever is chosen: it struck him off at noon in his absence.
  Rule college_sat when secondDay() and hour(clock) >= 12 and otteryOnRoad(ottery) and not otteryDecided(ottery) and not at(party, orm_gate) and not spread(college_sat_told) { Assert collegeMissed(ottery). Assert spread(college_sat_told). }
  Entity college_sat_told: fact "the College sat".
  Relation collegeMissed(group).
  Observe college_missed at orm_gate when collegeMissed(ottery) and not otteryDecided(ottery) "A clerk in black comes out of Orm's gate with a paper and nails it to the board by the wicket, and goes in again. Ottery reads it over your shoulder. 'Struck off,' he says, 'in my absence.' He does not seem surprised.".
  // Home by the carrier: three hours down, to the Abbey Yard by evening.
  Action carrier_home(actor: group, site: place) "Ride the carrier's cart back over the down to Hessel, one coin" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, orm_gate) and hour(clock) >= 13 and hour(clock) < 20 and quantity(actor, gold) >= 1.
    Time 18.
    On success { Decrease quantity(actor, gold) by 1. Retract at(actor, site). Assert at(actor, abbey_yard). }
    Result "The carrier's cart goes down over the high down at a walk, with a load of cheeses and a curate, and you sleep most of the way, and wake with the sun going down and the steam of Hessel standing up gold out of the valley in front of you.".
  }
  // Back in Hessel, Ottery goes to his ward; licensed or not, he is himself there, and can be asked along.
  Rule ottery_returns when otteryDecided(ottery) and not otteryGone(ottery) and following(ottery, party) and inHessel() and otteryOnRoad(ottery) {
    Retract following(ottery, party). Retract otteryOnRoad(ottery). Assert otteryHome(ottery). Assert willing(ottery, party). }
  Rule ottery_strays when otteryOnRoad(ottery) and following(ottery, party) and otteryDecided(ottery) and not otteryGone(ottery) and hour(clock) >= 21 and not inHessel() and not onOrmRoad() {
    Retract following(ottery, party). Retract otteryOnRoad(ottery). Assert otteryHome(ottery). }
  Initially Set hire(ottery) to 0.
}

data/adventures/hessel/placed.kyr:
Module hessel "The Banns at Hessel" {
  // The country beyond a march of a generated world: the company that comes in by the south road is the world's own.
  Entity party: group "Your company".
  // What is said of Hessel in the country behind it: once the Season is over, the talk of the old woman and the shuttered house is old news there, told by how it ended.
  Entity word: fact "What is said of Hessel in the country behind it.".
  Entity word_gone: fact "What is said there of the old woman who bought husbands.".
  Entity word_danced: fact "What is said there of the last dance.".
  Rule word_old when seasonOver() and cameToHessel(party) and not stale(word) { Assert stale(word). }
  Rule word_gone_old when gone(cherrett) and not stale(word_gone) { Assert stale(word_gone). }
  Rule word_danced_old when cherrettDanced(cherrett) and not stale(word_danced) { Assert stale(word_danced). }
}

data/adventures/hessel/rooms.kyr:
Module hessel "The Banns at Hessel" {
  // ── Mr Twiss ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // The Master of the Ceremonies: sixty, beautifully dressed, absurd, sincere, and the most powerful person in Hessel.
  // He has given his life to making a town's manners into an art, and he thinks of the Rules of the Rooms the way a
  // priest thinks of the creed: not true because written, but written because true.
  Person twiss "Mr Septimus Twiss" at twiss_parlour {
    Role "the Master of the Ceremonies, in dove-grey silk and a white wig". Ancestry human. Peaceable. Pronouns he. Manner proud.
    Greets "Mr Twiss rises, bows (it is a very good bow, made of several smaller bows, like a fan opening), and looks at your boots. 'You are new to Hessel,' he says. 'Welcome. Everyone is new to Hessel once. Most people remain so.'".
    Greets again "Mr Twiss inclines his head exactly as far as you deserve, which is a little further than last time.".
  }
  Rule twiss_home when hour(clock) >= 10 and hour(clock) < 18 and not at(twiss, twiss_parlour) { Assert at(twiss, twiss_parlour). }
  Rule twiss_rooms when hour(clock) >= 18 and not at(twiss, ballroom) and not at(twiss, vestibule) { Assert at(twiss, vestibule). }
  Rule twiss_to_floor when evening() and at(twiss, vestibule) and not twissFrantic(twiss) { Assert at(twiss, ballroom). }
  Rule twiss_bed when hour(clock) < 10 and not at(twiss, twiss_parlour) { Assert at(twiss, twiss_parlour). }
  Measure twissFavour(group).
  Relation admitted(group). Relation householdBarred(group). Relation householdAdmitted(group). Relation twissOffended(group).
  Initially Assert householdBarred(cherrett).
  // Mrs Cherrett's people come in with her once the bar is lifted; the company, if it is not of her household, may
  // subscribe like anyone.
  Rule household_in when legs(party) and householdAdmitted(cherrett) and not admitted(party) and not twissOffended(party) { Assert admitted(party). }
  Rule household_out when legs(party) and admitted(party) and householdBarred(cherrett) and not householdAdmitted(cherrett) { Retract admitted(party). }
  Rule bar_lifted when householdAdmitted(cherrett) and householdBarred(cherrett) { Retract householdBarred(cherrett). }
  // Why the portrait of him older is not dancing; and the one time he broke the eleven o'clock Rule.
  Topic twiss_portraits with twiss "Ask Mr Twiss why, in the second portrait, he is not dancing" when twissFavour(twiss) >= 1 once {
    Says "Mr Twiss looks at the two portraits as if they were of somebody he had once been introduced to. 'In my first Season,' he says, 'I was a dancing-master's assistant, and the band played on after eleven, once, because a young lady asked it, and I danced with her, and the old Master had me out of these Rooms for a twelvemonth.' He straightens a letter on the desk by a quarter of an inch. 'When I came back I made the Rules, and I have kept them, and I have not danced since except to open the Ball. The young lady married an earl.' A pause. 'She dances the minuet still. In the second figure she forgets her feet, and has for thirty years, and nobody in the room has ever been so unkind as to notice, until Mrs Cherrett.'".
    On discuss { Assert knows(actor, twiss_countess). }
  }
  Discovery twiss_countess "Mr Twiss broke the eleven o'clock Rule once, in his first Season, to dance with the young lady who is now the Countess of Arne.".
  Topic twiss_rules with twiss "Ask Mr Twiss about the Rules of the Rooms" when true once {
    Says "'The Rules.' Mr Twiss touches the frame on his wall, the way a man touches wood. 'You think them trifles. Everybody does, who has not thought. No boots after six: because a ballroom is a place where a duchess and a draper's widow may stand up in the same set, and they must not be able to tell from the floor which is which. No lady to dance two running with one gentleman unless betrothed: because otherwise a girl may be compromised in twenty minutes by a man she would not let into her kitchen. No dancing after eleven: because the old must go home to bed, and if the music goes on, they will not.' He folds his hands. 'Every Rule of the Rooms is a kindness that has had to be made into a law, because people are not kind unless they are made to be. I am the Master of the Ceremonies. I am the one who makes them.'".
    On discuss { Increase twissFavour(twiss) by 1. }
  }
  Topic twiss_cherrett with twiss "Ask Mr Twiss why Mrs Cherrett is barred from the Rooms" when true once {
    Says "Mr Twiss's face closes like a snuff-box. 'Mrs Cherrett laughed,' he says, 'aloud, during the Countess of Arne's minuet. In the second figure. The Countess has danced the minuet in these Rooms for forty-one years; she is seventy; she dances it like a heron with the gout, and she knows it, and she does it because it is the last thing in the world she is good at.' He looks at you. 'Mrs Cherrett has a great deal of money and a very loud laugh. She may use neither in my Rooms until she has expressed her regret. In form.'".
  }
  Discovery cherrett_will_regret "Mrs Cherrett will let her regret be expressed to Mr Twiss on her behalf, though she will not choke on the word herself.".
  Topic cherrett_regret with cherrett "Tell Mrs Cherrett that Ismay will never stand up at a ball in Hessel unless she makes her peace with Mr Twiss" when householdBarred(cherrett) and not gone(cherrett) and not knows(actor, cherrett_will_regret) once {
    Says "'Peace!' Mrs Cherrett's stick comes down on the floor. 'With that pink-heeled dancing-master! I laughed because the old heron was funny, and so she was.' She glares at the stuffed pike. Then she looks at Ismay, at her ledger by the window, and something in her face gives. 'Oh, very well,' she says. 'Go and tell him I regret it. I don't. But you can tell him so. I'll not choke on the word myself, mind.'".
    On discuss { Assert knows(actor, cherrett_will_regret). }
  }
  Action apologise_form(actor: group, site: place) "Express Mrs Cherrett's regret to Mr Twiss, in form, naming the Rule" {
    Description "In his parlour, by one of her household, with the word regret and not the word sorry.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, twiss_parlour) and at(twiss, twiss_parlour)
      and legs(actor) and knows(actor, cherrett_will_regret) and knows(actor, twiss_form) and householdBarred(cherrett) and not twissOffended(actor).
    Time 2.
    On success { Assert householdAdmitted(cherrett). Increase twissFavour(twiss) by 1. }
    Result "You stand in the middle of Mr Twiss's carpet and say that Mrs Abigail Cherrett, of the Circus, has charged you to express her very great regret that she was so unhappy as to give offence, in the second figure of the Countess of Arne's minuet, against the spirit of the Rule that the Rooms are for the pleasure of all who keep them. Mr Twiss listens with his eyes shut. When you have done he opens them. 'Regret,' he says softly. 'Not sorry.' He takes a card from his desk and writes on it, in a hand like a garden in a frost. 'Mrs Cherrett and her household,' he says, 'are welcome at the Rooms. Tell her the Countess has asked after her ankle.'".
  }
  Action apologise_plain(actor: group, site: place) "Tell Mr Twiss that Mrs Cherrett is sorry, and ask him to let her household in" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, twiss_parlour) and at(twiss, twiss_parlour)
      and legs(actor) and knows(actor, cherrett_will_regret) and not knows(actor, twiss_form) and householdBarred(cherrett) and not twissOffended(actor) and not triedPlain(actor).
    Time 2.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert householdAdmitted(cherrett). }
    On failure { Assert triedPlain(actor). }
    Result "Mr Twiss winces at sorry as at a wrong note. But you go on, and say it well, and somewhere in the middle of it he begins to listen. 'You do not know the form,' he says at last. 'That is evident. But you have the spirit of it, which is rarer.' He writes a card. 'Mrs Cherrett and her household are welcome at the Rooms.'".
    Otherwise "'Sorry,' says Mr Twiss, as if you had trodden on his foot. 'Mrs Cherrett is sorry.' He rings for his man. 'Sorry is for servants and for dogs. Good afternoon.'".
  }
  Relation triedPlain(group).
  // Anyone not of the household may subscribe to the Season's last week, three coin, as any stranger may.
  Action subscribe(actor: group, site: place) "Subscribe to the Rooms for the last week of the Season, three coin" {
    Requires able(actor) and company(actor) and at(actor, site) and at(twiss, site) and (at(actor, twiss_parlour) or at(actor, vestibule))
      and not admitted(actor) and not legs(actor) and not twissOffended(actor) and quantity(actor, gold) >= 3.
    Time 2 minutes.
    On success { Decrease quantity(actor, gold) by 3. Assert admitted(actor). Increase quantity(twiss, gold) by 3. }
    Result "Mr Twiss enters your name in a book bound in blue morocco, sands it, and gives you a ticket of the Rooms, engraved with a lady and a gentleman bowing to each other across a lyre. 'You are now,' he says, 'one of us. Do try.'".
  }
  Topic twiss_household_refused with twiss "Ask Mr Twiss to take your subscription" when legs(actor) and householdBarred(cherrett) and not admitted(actor) once {
    Says "Mr Twiss looks at you with real regret. 'You are Mrs Cherrett's,' he says. 'Everyone in Hessel knows it; you were seen catching her, or not catching her, which is the same as far as reputation goes.' He spreads his hands. 'Her household is barred. I cannot take your money. I can only wish, for your sake, that she would express a little regret.'".
  }

  // ── The footman ───────────────────────────────────────────────────────────────────────────────────────────────────
  // Who can be bought; and the price of being bought is Mr Twiss finding out, at his own Ball, in front of everybody.
  Person fitch "Pocklington" at vestibule {
    Role "the Rooms' footman, in blue, who has stood at that door for eleven Seasons and seen everything twice". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "The footman looks over your head at a point on the far wall.".
  }
  Topic fitch_door with fitch "Ask the footman who is let in at the Rooms" when true once {
    Says "'Subscribers,' says Pocklington, to the far wall. 'Their names in Mr Twiss's book, their tickets in their hands. Strangers, by subscription, three coin, the last week of the Season, at Mr Twiss's pleasure.' A pause of exactly one breath. 'Persons Mr Twiss has barred, never. Not by the front door, and not by the side door, which there is not, and which is locked at half past seven.'".
  }
  Topic fitch_seasons with fitch "Ask the footman what he has seen in eleven Seasons" when true once {
    Says "For the first time his eyes come down from the wall and rest on you, briefly, as on a coat that has been hung on the wrong peg. 'Everything, sir or madam,' he says. 'Twice.' The eyes go back up. 'A duel on the stairs, a proposal in the card-room, an elopement out of the tea-room window, which is not as easy as it looks. Mr Twiss has opened the Rooms every night of the Season for twenty years, and I have stood at this door for eleven of them, and nobody has once asked me what I thought of any of it.' He does not say what he thinks of it now.".
  }
  Relation fitchBribed(group).
  Action bribe_fitch(actor: group, site: place) "Slip Pocklington five coin to let Mrs Cherrett's household in at the Ball" {
    Requires able(actor) and company(actor) and at(actor, site) and at(fitch, site) and legs(actor) and householdBarred(cherrett)
      and not fitchBribed(actor) and quantity(actor, gold) >= 5.
    Time 1 minute.
    On success { Decrease quantity(actor, gold) by 5. Increase quantity(fitch, gold) by 5. Assert fitchBribed(actor). }
    Result "The coins go into Pocklington's glove without his face moving at all. 'The side door,' he says to the far wall. 'Half past seven. Monday.'".
  }

  // ── Signor Brocca's evening ───────────────────────────────────────────────────────────────────────────────────────
  // On the second evening the Rooms' first violin is drunk at the Two Poles, where he goes to be with people who do not
  // know he plays. Without him there is no band; with no band there is no assembly; Mr Twiss has never once in twenty
  // years opened the Rooms to silence.
  Person brocca "Signor Brocca" at limbo {
    Role "a little man in a velvet coat, with a violin case, weeping into a pot of porter" when not broccaSober(brocca).
    Role "the Rooms' first violin, damp and upright" when broccaSober(brocca).
    Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "The little man in the velvet coat looks up at you with swimming eyes. 'You are kind,' he says. 'Everybody here is kind. Nobody here knows who I am. Is it not wonderful?'".
  }
  Relation broccaSober(group). Relation broccaDone(group). Relation twissFrantic(group).
  Rule brocca_drinks when secondDay() and hour(clock) >= 17 and hour(clock) < 21 and not at(brocca, two_poles) and not broccaSober(brocca) and not broccaDone(brocca) and not following(brocca, party) and not travelsWith(brocca, party) { Assert at(brocca, two_poles). }
  Rule twiss_waits when secondDay() and hour(clock) >= 19 and hour(clock) < 21 and not broccaDone(brocca) and not twissFrantic(twiss) { Assert twissFrantic(twiss). Assert at(twiss, vestibule). }
  Observe twiss_frantic at vestibule when twissFrantic(twiss) and not broccaDone(brocca) "Mr Twiss is in the vestibule in his ballroom silks, walking up and down between the mirrors, so that there are a great many of him, all of them frantic. 'The first violin,' he is saying to Pocklington, to the ceiling, to anyone. 'Without a first violin there is no band. Without a band there is no assembly. I have opened these Rooms every night of the Season for twenty years.'".
  Action sober_brocca(actor: group, site: place) "Walk Signor Brocca round the yard and put his head under the pump" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, two_poles) and at(brocca, two_poles) and not broccaSober(brocca).
    Time 3.
    On success { Assert broccaSober(brocca). Assert acceptsEscort(brocca, actor). Assert following(brocca, actor). }
    Result "Twice round the yard, once under the pump, and a pint of the landlord's black coffee that tastes of the pot. Signor Brocca comes up out of the pump-trough like a drowned cat and looks at you with sudden, terrible clarity. 'The Rooms,' he says. 'It is Saturday? It is the Rooms. Twiss will kill me.' He picks up his violin case and holds it to his chest. 'Take me. Take me up the hill.'".
  }
  Action carry_brocca(actor: group, site: place) "Carry Signor Brocca up the Parade on your back, violin and all" {
    Description "He is not heavy. The Parade is.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, abbey_yard) and following(brocca, actor) and broccaSober(brocca) and not broccaDone(brocca).
    Time 2.
    Resolve check(actor, brawn, dc_easy).
    On success { Retract following(brocca, actor). Assert at(brocca, vestibule). Retract at(actor, abbey_yard). Assert at(actor, circus). }
    On failure { Retract following(brocca, actor). Assert at(brocca, vestibule). Retract at(actor, abbey_yard). Assert at(actor, circus). }
    Result "Up the Parade at a stagger, with Signor Brocca's arms round your neck and his violin case beating time on your shoulder, past the chairmen at the Parade foot, who cheer. At the top you set him down at the door of the Rooms, and he straightens his coat, and goes in.".
    Otherwise "Halfway up the Parade your legs go, and you sit down together on the ridged paving, and Signor Brocca laughs until he cries. You go the rest of the way on foot, slowly, arm in arm, and at the door of the Rooms he straightens his coat and goes in.".
  }
  Event brocca_arrives near twiss when at(brocca, vestibule) and hour(clock) < 21 and not broccaDone(brocca) "Mr Twiss sees Signor Brocca come in at the door, damp, upright, holding his violin, and for a moment the Master of the Ceremonies closes his eyes. Then he takes the little man by both shoulders and turns him toward the ballroom, and the band strikes up before Brocca is in his chair. Mr Twiss comes back to you across the vestibule. 'I am in your debt,' he says. 'I am never in anyone's debt. Name it.'" then {
    Assert broccaDone(brocca). Retract twissFrantic(twiss). Increase twissFavour(twiss) by 2. Assert twissOwes(party). }
  Event brocca_late at vestibule when secondDay() and hour(clock) >= 21 and not broccaDone(brocca) "The Rooms open at last at nine, to a band without a first violin, and Mr Twiss, white to the lips, conducts it himself with a candle-snuffer. It is spoken of for years." then {
    Assert broccaDone(brocca). Retract twissFrantic(twiss). Assert at(brocca, limbo). }
  Rule brocca_goes_home when broccaDone(brocca) and at(brocca, vestibule) and hour(clock) >= 23 { Assert at(brocca, limbo). }
  Relation twissOwes(group).
  Topic twiss_name_household with twiss "Name it: Mrs Cherrett and her household, admitted to the Rooms" when twissOwes(actor) and householdBarred(cherrett) once {
    Says "Mr Twiss's eyebrows go up, and come down again. 'The household of Mrs Cherrett,' he says. 'Without regret expressed.' He looks into the ballroom, where Brocca is playing like a man redeemed. 'Very well. A debt is a debt. Mrs Cherrett and her household are welcome. Tell her I shall expect her not to laugh.'".
    On discuss { Retract twissOwes(actor). Assert householdAdmitted(cherrett). }
  }
  Topic twiss_name_self_stranger with twiss "Name it: a ticket of the Rooms for yourself" when twissOwes(actor) and not admitted(actor) and not legs(actor) once {
    Says "'Done,' says Mr Twiss, and gives you a ticket of the Rooms from his own pocket. 'You are one of us. Do try.'".
    On discuss { Retract twissOwes(actor). Assert admitted(actor). }
  }

  // ── Mrs Scrope ────────────────────────────────────────────────────────────────────────────────────────────────────
  // Whatever she is told at the Pump Room in the morning is all over Hessel by dinner, at three, with its teller's
  // name. She is not malicious. She is a widow with nothing to do, and the truth, in Hessel, is the only thing that is
  // free.
  Person scrope "Mrs Tabitha Scrope" at pump_room {
    Role "a small bright widow in lavender, with a glass of the waters she never drinks". Ancestry human. Peaceable. Pronouns she. Manner cheerful.
    Greets "The little widow in lavender turns to you with the whole of her face, as a sunflower turns. 'You're new,' she says. 'How delightful. Sit by me. Tell me everything. I never repeat anything, except to my particular friends.'".
    Greets again "Mrs Scrope pats the seat beside her.".
  }
  Rule scrope_pump when hour(clock) >= 8 and hour(clock) < 12 and not at(scrope, pump_room) { Assert at(scrope, pump_room). }
  Rule scrope_cards when hour(clock) >= 19 and hour(clock) < 23 and not at(scrope, card_room) { Assert at(scrope, card_room). }
  Rule scrope_home when (hour(clock) >= 12 and hour(clock) < 19 or hour(clock) >= 23 or hour(clock) < 8) and not at(scrope, kings_bath) { Assert at(scrope, kings_bath). }
  // What she has been told, and what is public: the rumour goes round at three, the hour Hessel dines.
  Kind rumour.
  Entity rumour_rupert: rumour "that the Honourable Rupert Wenlock has a wife and child in the Old Town".
  Entity rumour_kit: rumour "that Ismay Cherrett is in love with a chairman".
  Entity rumour_drops: rumour "that Dr Hartopp has doubled Mrs Cherrett's drops since she put him in her will".
  Entity rumour_nan: rumour "that Lady Carth is alive and washing linen in the Old Town".
  Entity rumour_window: rumour "that a young man moons all day at the window of Carth House".
  Entity rumour_ruin: rumour "that the Cherrett money is all in canal shares, and the canals are failing".
  Relation toldScrope(rumour). Relation public(rumour).
  Rule rumour_goes_round when toldScrope(?r) and not public(?r) and hour(clock) == 15 { Assert public(?r). }
  Rule rumour_goes_round_late when toldScrope(?r) and not public(?r) and hour(clock) >= 15 and hour(clock) < 16 { Assert public(?r). }
  Topic scrope_rupert with scrope "Tell Mrs Scrope that Rupert Wenlock is secretly married, with a baby" when knows(actor, rupert_married) and not toldScrope(rumour_rupert) and not bannsDone(ebbas) once {
    Says "Mrs Scrope's eyes become perfectly round. 'Married!' she breathes. 'And the banns read twice! And the Cherrett girl!' She puts down her glass. 'I shall tell no one,' she says, and is already looking round the room for someone to tell.".
    On discuss { Assert toldScrope(rumour_rupert). }
  }
  Topic scrope_kit with scrope "Tell Mrs Scrope that Ismay Cherrett is in love with a chairman" when knows(actor, ismay_loves_kit) and not toldScrope(rumour_kit) once {
    Says "'A chairman!' Mrs Scrope claps her little gloved hands together without a sound. 'Oh, but that's beautiful. That's a ballad. Which one? The young one who reads? Oh, I knew it, I knew it from the way he holds the poles.' She is already half out of her chair.".
    On discuss { Assert toldScrope(rumour_kit). }
  }
  Topic scrope_drops with scrope "Tell Mrs Scrope that Dr Hartopp has doubled Mrs Cherrett's drops since she put him in her will" when knows(actor, drops_doubled) and not toldScrope(rumour_drops) once {
    Says "Mrs Scrope goes quite still. 'Hartopp,' she says. 'He attends me. He attends my sister.' She looks at her glass of the waters as if something might be in it. 'I shall mention it,' she says, 'to my particular friends.' She has eleven.".
    On discuss { Assert toldScrope(rumour_drops). }
  }
  Topic scrope_nan with scrope "Tell Mrs Scrope that Lady Carth is alive, and washing linen in the Old Town" when knows(actor, nan_is_lady) and not toldScrope(rumour_nan) once {
    Says "For once in her life Mrs Scrope cannot speak. Then she says, 'Lady Carth. Lady Carth,' and stands up, and sits down, and stands up again, and goes out of the Pump Room without her shawl.".
    On discuss { Assert toldScrope(rumour_nan). }
  }
  Topic scrope_window with scrope "Tell Mrs Scrope that Rob Cherrett is in love with a face at the window of Carth House" when knows(actor, rob_loves_window) and not toldScrope(rumour_window) once {
    Says "'The Carth girl!' says Mrs Scrope. 'Nobody has seen the Carth girl in nine years! They say she is consumptive. They say she is mad. They say Sir Gervase keeps her in the dark.' She sighs, happily. 'And a poet. How perfectly dreadful.'".
    On discuss { Assert toldScrope(rumour_window). }
  }
  Topic scrope_ruin with scrope "Tell Mrs Scrope, in confidence, that the Cherrett money is all in canal shares, and the canals are failing" when legs(actor) and not toldScrope(rumour_ruin) once {
    Says "It is not true. Mrs Scrope does not know that; neither, you suspect, would she much mind. 'Canals,' she says, with a beautiful look of sorrow. 'Oh, the poor things. And the Wenlocks so very particular about money.' She pats your hand. 'You were right to tell me. Who else would you tell?'".
    On discuss { Assert toldScrope(rumour_ruin). Assert liedPublicly(actor). }
  }
  Relation liedPublicly(group).
  // What the town says back, at the next Pump Room, of what went round.
  Query quietTown() means not public(rumour_rupert) and not public(rumour_kit) and not public(rumour_drops) and not public(rumour_nan) and not public(rumour_window) and not public(rumour_ruin) and not bannsWithdrawn(ebbas).
  Topic scrope_news with scrope "Ask Mrs Scrope what the news is" when not dark() and quietTown() {
    Says "'Oh, the news,' says Mrs Scrope, and tells you about a colonel's gout, a bishop's niece, a pair of twins in the King's Bath who are not, after all, the same person, and a bonnet. Then she leans close. 'And they're saying the Cherrett girl's banns are as good as read, and the Wenlocks will have the canal money by Monday, and Dr Hartopp has his eye on the companion, or the granddaughter, depending who you ask.' She sips water she does not swallow.".
  }
  Topic scrope_ottery with scrope "Ask Mrs Scrope about the Hospital of the Waters" when firstDay() and not otteryDecided(ottery) once {
    Says "'Oh, poor Dr Ottery.' Mrs Scrope is delighted. 'Turned off by the governors, for telling Mrs Cherrett she was dying, in the Pump Room, in front of everybody. And now the College at Orm has summoned him for tomorrow noon, and he has to walk it, over the down, at first light, with nobody to speak for him. Nobody will, of course. He calls the governors fools.' She sips. 'Which they are.'".
  }
  Topic scrope_news_after with scrope "Ask Mrs Scrope what the news is" when not dark() and not quietTown() {
    Says "'The news!' Mrs Scrope can hardly sit still. 'My dear, there's never been a Season like it. The Cherrett banns are off, and everybody has a different reason, and every one of them is true.' She lowers her voice. 'And they say the Cherretts' stranger is at the bottom of it all. I said, nonsense. I said, a stranger can't do anything in Hessel. Can they?' She looks at you with enormous interest.".
  }
  Observe scrope_public_rupert near scrope when public(rumour_rupert) and not seenOnce(rupert_public) "'Married,' Mrs Scrope is saying to a colonel, 'two years, to a milliner, with a little boy, and the banns read twice at Saint Ebba's! Lady Wenlock has taken to her bed.'" teaches rupert_public.
  Discovery rupert_public "All Hessel knows that Rupert Wenlock was secretly married to a milliner, with a child, while his banns were read to Ismay Cherrett.".
  Observe scrope_public_kit near scrope when public(rumour_kit) and not seenOnce(kit_public) "'A chairman,' Mrs Scrope is telling the gallery, 'a common chairman, in a blue coat, and she the Cherrett heiress. Like a ballad.' The gallery is delighted." teaches kit_public.
  Discovery kit_public "All Hessel knows that Ismay Cherrett is in love with Kit Danby, the chairman.".
  Observe scrope_public_drops near scrope when public(rumour_drops) and not seenOnce(drops_public) "'Laudanum,' Mrs Scrope is saying, behind her fan, 'by the pint. And she put him in her will! Lady Pomfret has dismissed him. So has my sister.'" teaches drops_public.
  Discovery drops_public "All Hessel is saying that Dr Hartopp doubled Mrs Cherrett's drops after she put him in her will; his patients are leaving him.".
  Observe scrope_public_nan near scrope when public(rumour_nan) and not seenOnce(nan_public) "'Alive,' Mrs Scrope is telling everybody, 'alive these nine years, washing sheets under his very windows. Half the town went down to the laundries to look at her this morning.'" teaches nan_public.
  Discovery nan_public "All Hessel knows that Lady Carth is alive, and washing linen in the Old Town, under her husband's windows.".
  Observe scrope_public_window near scrope when public(rumour_window) and not seenOnce(window_public) "'A poet,' Mrs Scrope is saying, 'on the lawn, all day, at the Carth girl's window. And Sir Gervase has had his man nail the shutters.'" teaches window_public.
  Discovery window_public "All Hessel knows that Rob Cherrett moons at the window of Carth House, and Sir Gervase has had the shutters nailed.".
  Observe scrope_public_ruin near scrope when public(rumour_ruin) and not seenOnce(ruin_public) "'Canals,' Mrs Scrope is saying, mournfully, to a bishop. 'Every penny. And the Wenlocks have withdrawn. I had it from Mrs Cherrett's own cavalier.'" teaches ruin_public.
  Discovery ruin_public "All Hessel believes the Cherrett money is lost in failing canals; the Wenlocks have withdrawn from the match, and everyone knows who said it first.".

  // ── What the rumours do ───────────────────────────────────────────────────────────────────────────────────────────
  // Rupert's marriage, public: the banns are stopped in fury, the Wenlocks leave the Rooms, Rupert goes to his wife.
  Rule rupert_scandal when public(rumour_rupert) and not bannsWithdrawn(ebbas) and not bannsDone(ebbas) {
    Assert bannsWithdrawn(ebbas). Assert scandal(wenlock). Retract wenlockSponsor(wenlock). }
  // Ismay's love, public: Mrs Cherrett hears it from the town before she hears it from Ismay, and turns the chairman
  // off for presumption.
  Rule kit_scandal when public(rumour_kit) and not kitDismissed(kit) and not cherrettBlessesKit(cherrett) { Assert kitDismissed(kit). Assert cherrettHumiliated(cherrett). }
  Relation cherrettHumiliated(group).
  // The drops, public: Hartopp's practice cools, and he courts nobody.
  Rule drops_scandal when public(rumour_drops) and not hartoppCooled(hartopp) { Assert hartoppCooled(hartopp). }
  // Lady Carth, public: the town goes down to stare, and she goes away.
  Rule nan_scandal when public(rumour_nan) and not nanFled(nan) and not carthReunited(carth) { Assert nanFled(nan). Assert at(nan, limbo). }
  // The window, public: the shutters are nailed.
  Rule window_scandal when public(rumour_window) and not windowNailed(carth) and not celiaOut(celia) { Assert windowNailed(carth). Assert state(drawing_window, nailed). }
  // The canals, public: the Wenlocks withdraw; Hartopp cools; and Mrs Cherrett learns who said it.
  Rule ruin_scandal when public(rumour_ruin) and not bannsDone(ebbas) {
    Assert bannsWithdrawn(ebbas). Assert hartoppCooled(hartopp). Assert cherrettBetrayed(cherrett). Retract wenlockSponsor(wenlock). }
  Relation cherrettBetrayed(group). Relation scandal(group). Relation hartoppCooled(group).
  Rule betrayed_dismissed when cherrettBetrayed(cherrett) and legs(party) and not gone(cherrett) says "A note comes from the Circus, in Mrs Cherrett's enormous hand: You told the town I was ruined. I am not. You are dismissed. A. C. Underneath, in a smaller hand: She cried. M. G." {
    Retract legs(party). Assert legsLost(party). Set mopsaRegard(mopsa) to 0. }
  Relation legsLost(group).

  // ── The Wenlocks ──────────────────────────────────────────────────────────────────────────────────────────────────
  Person lady_wenlock "Lady Wenlock" at wenlock_room {
    Role "a long thin lady in black with a face like a closed umbrella" when not grandmother(lady_wenlock).
    Role "a long thin lady in black, with a blue ribbon in her cap that goes with nothing" when grandmother(lady_wenlock).
    Ancestry human. Peaceable. Pronouns she. Manner proud.
    Greets "Lady Wenlock looks at you through a glass on a stick, as if you were very small and a long way off. 'Yes?' she says.".
    Greets again "Lady Wenlock raises her glass.".
  }
  Rule wenlock_pump when pumpHour() and not at(lady_wenlock, pump_room) and not wenlockGone(wenlock) { Assert at(lady_wenlock, pump_room). }
  Rule wenlock_home when (hour(clock) >= 10 and hour(clock) < 19 or hour(clock) >= 23 or hour(clock) < 8) and not at(lady_wenlock, wenlock_room) and not wenlockGone(wenlock) and not atBall(lady_wenlock) { Assert at(lady_wenlock, wenlock_room). }
  Rule wenlock_cards when evening() and not at(lady_wenlock, card_room) and not wenlockGone(wenlock) and not scandal(wenlock) and not atBall(lady_wenlock) { Assert at(lady_wenlock, card_room). }
  Entity wenlock: group "the Wenlocks".
  Relation wenlockGone(group). Relation wenlockSponsor(group). Relation grandmother(group).
  Topic wenlock_match with lady_wenlock "Ask Lady Wenlock about the match" when not bannsWithdrawn(ebbas) once {
    Says "'The match.' Lady Wenlock lowers her glass. 'My son has a name that has been in the Book of the Peerage since there was a book, and an income that would not keep a curate in boots. Mrs Cherrett has forty thousand pounds and a voice that would carry across a canal.' She raises the glass again. 'It is a perfectly ordinary arrangement. They are made every Season in this town by people who smell less strongly of trade. I do not have to like it. I have only to attend it.'".
  }
  Topic wenlock_sponsor with lady_wenlock "Ask Lady Wenlock to speak to Mr Twiss for the Cherretts, since their granddaughter is to be her son's wife" when householdBarred(cherrett) and not bannsWithdrawn(ebbas) and legs(actor) and not wenlockSponsor(wenlock) once {
    Says "Lady Wenlock considers the request, and you, and the window. 'It would be awkward,' she says, 'to have my son married on Monday morning to a girl who was not admitted to the Ball on Monday night. People would ask why.' She sighs. 'Very well. I shall write to Mr Twiss. He will do it for me.' The glass goes up. 'You understand that I now expect the banns to be read on Sunday without the smallest hitch.'".
    On discuss { Assert wenlockSponsor(wenlock). Assert householdAdmitted(cherrett). }
  }
  // A sponsor withdrawn takes the household out again, unless Twiss has been won another way.
  Rule sponsor_withdrawn when householdAdmitted(cherrett) and sponsorOnly(cherrett) and not wenlockSponsor(wenlock) and scandal(wenlock) {
    Retract householdAdmitted(cherrett). Assert householdBarred(cherrett). Retract sponsorOnly(cherrett). }
  Relation sponsorOnly(group).
  Rule sponsor_only when wenlockSponsor(wenlock) and householdAdmitted(cherrett) and twissFavour(twiss) < 2 and not sponsorOnly(cherrett) and not twissWon(cherrett) { Assert sponsorOnly(cherrett). }
  Rule twiss_won when twissFavour(twiss) >= 2 and not twissWon(cherrett) { Assert twissWon(cherrett). Retract sponsorOnly(cherrett). }
  Relation twissWon(group).

  Person rupert "the Honourable Rupert Wenlock" at wenlock_room {
    Role "a pleasant, anxious man of thirty with a beetle in a pill-box". Ancestry human. Peaceable. Pronouns he. Manner compassionate.
    Greets "The pleasant anxious man shakes your hand as if it were a great relief to him that you have one. 'How do you do. Rupert Wenlock. Are you interested in beetles? Nobody is. I don't blame them.'".
    Greets again "Rupert Wenlock smiles at you, and looks at the door.".
  }
  // Mornings with his mother; at noon to Quay Lane, to his wife and son; the afternoons on the King's Bath gallery; the
  // evenings at the Rooms, or, on the second, drinking at the Two Poles with the chairmen, who do not know he is anyone.
  Relation rupertAway(group).
  Rule rupert_morning when hour(clock) >= 8 and hour(clock) < 12 and not at(rupert, wenlock_room) and not rupertAway(rupert) and not following(rupert, party) and not travelsWith(rupert, party) { Assert at(rupert, wenlock_room). }
  Rule rupert_noon when hour(clock) >= 12 and hour(clock) < 14 and not at(rupert, hetty_shop) and not rupertAway(rupert) and not following(rupert, party) and not travelsWith(rupert, party) { Assert at(rupert, hetty_shop). }
  Rule rupert_afternoon when hour(clock) >= 14 and hour(clock) < 19 and not at(rupert, kings_bath) and not rupertAway(rupert) and not following(rupert, party) and not travelsWith(rupert, party) { Assert at(rupert, kings_bath). }
  Rule rupert_evening when evening() and not secondDay() and not at(rupert, card_room) and not rupertAway(rupert) and not atBall(rupert) and not following(rupert, party) and not travelsWith(rupert, party) { Assert at(rupert, card_room). }
  Rule rupert_drinks when evening() and secondDay() and not at(rupert, two_poles) and not rupertAway(rupert) and not following(rupert, party) and not travelsWith(rupert, party) { Assert at(rupert, two_poles). }
  Rule rupert_night when (hour(clock) >= 23 or hour(clock) < 8) and not at(rupert, wenlock_room) and not rupertAway(rupert) and not following(rupert, party) and not travelsWith(rupert, party) { Assert at(rupert, wenlock_room). }
  Discovery rupert_married "Rupert Wenlock, whose banns are being read to Ismay Cherrett, has a wife and a son in Quay Lane.".
  Topic rupert_banns with rupert "Ask Rupert about the banns" when not knows(actor, rupert_married) once {
    Says "Rupert goes pink, and then rather white, and looks at his pill-box. 'The banns,' he says. 'Yes. Twice. Sunday is the third. Miss Cherrett is a very fine young woman. Very fine. Very good with figures.' He opens the pill-box and looks at the beetle inside as if it might help. It does not. 'Excuse me,' he says, 'I think I hear my mother,' though she is sitting beside him.".
  }
  Topic rupert_confronted with rupert "Tell Rupert that you know about Hetty and the baby" when knows(actor, rupert_married) and not rupertConfessed(rupert) once {
    Says "Rupert sits down very suddenly, on nothing in particular. 'Oh God,' he says. 'Oh God, who else knows?' He puts his face in his hands. 'I married her in Bristol. Two years ago. Her name is Hetty and she makes the best bonnets in Hessel and my son is called Jack and he has teeth now, four.' He looks up. 'And my mother has no money, none, and she's arranged it, and the banns were read before I could think, and every Sunday I go to church and think, now I'll stand up, now, and I don't. I sit there. What do I do?'".
    On discuss { Assert rupertConfessed(rupert). }
  }
  Relation rupertConfessed(group). Relation rupertBrave(group).
  Topic rupert_brave with rupert "Tell Rupert you will go with him to his mother, and stand beside him while he tells her" when rupertConfessed(rupert) and not rupertBrave(rupert) and not bannsWithdrawn(ebbas) once {
    Says "'You'd come?' Rupert looks at you as if you had offered to go down a well for him. 'Into the room? While I say it?' He shuts the pill-box. 'Hetty must come. And Jack. Mother must see Jack. Nobody could see Jack and stay angry; he has a face like a pudding.' He stands up. 'I'll tell Hetty. You'll fetch her? Tomorrow, or today, in the afternoon, when mother's at home. Oh God. Yes.'".
    On discuss { Assert rupertBrave(rupert). }
  }

  // ── Dr Hartopp ────────────────────────────────────────────────────────────────────────────────────────────────────
  // He attends Mrs Cherrett's heart and Celia Carth's lungs. He keeps the first asleep and the second indoors, and is
  // paid for both. He means to marry Ismay if the Wenlocks can be got rid of, and to be remembered in a will if they
  // cannot. He is charming, and what he has done he has done by small steps, each of which he could explain.
  Person hartopp "Dr Ambrose Hartopp" at hartopp_room {
    Role "a handsome physician in plum-coloured cloth, smelling of cloves" when not hartoppRuined(hartopp).
    Role "Dr Hartopp, packing" when hartoppRuined(hartopp).
    Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "The handsome physician takes your hand and, without seeming to, your pulse. 'A stranger to our waters,' he says warmly. 'You must let me prescribe for you. Everyone needs something.'".
    Greets again "Dr Hartopp smiles with all his teeth.".
  }
  Relation hartoppRuined(group). Relation hartoppDismissed(group). Relation hartoppBarred(group). Relation hartoppWalked(group).
  Rule hartopp_consults when hour(clock) >= 9 and hour(clock) < 17 and not at(hartopp, hartopp_room) and not hartoppRuined(hartopp) { Assert at(hartopp, hartopp_room). }
  Rule hartopp_rounds when hour(clock) >= 17 and hour(clock) < 19 and not at(hartopp, circus) and not hartoppRuined(hartopp) { Assert at(hartopp, circus). }
  Rule hartopp_rooms when evening() and not at(hartopp, card_room) and not hartoppRuined(hartopp) and not hartoppBarred(hartopp) and not atBall(hartopp) { Assert at(hartopp, card_room). }
  Rule hartopp_night when (hour(clock) >= 23 or hour(clock) < 9) and not at(hartopp, hartopp_room) and not hartoppRuined(hartopp) { Assert at(hartopp, hartopp_room). }
  Rule hartopp_ruined when (hartoppDismissed(hartopp) and (hartoppCooled(hartopp) or hartoppBarred(hartopp) or hartoppWalked(hartopp))) and not hartoppRuined(hartopp) { Assert hartoppRuined(hartopp). }
  // Dismissed by Mrs Cherrett once someone she loves has asked her to stop.
  Rule hartopp_dismissed when stoppedBy(cherrett, ?who) and not hartoppDismissed(hartopp) { Assert hartoppDismissed(hartopp). }
  Topic hartopp_cherrett with hartopp "Ask Dr Hartopp how Mrs Cherrett does" when not gone(cherrett) once {
    Says "'Mending,' says Dr Hartopp, with real tenderness. 'Mending beautifully. The heart is a pump, you know, like the one in the Pump Room, and the waters are its oil. A little rest, a little sleep. I see that she sleeps.' He smiles. 'A wonderful woman. A heart of oak, and of gold, and of, well. A failing heart, between ourselves. But she must not be told so. It is the first rule of medicine: never take away hope. Hope is the best physic in the world, and the cheapest; I never charge for it.'".
  }
  Topic hartopp_carth with hartopp "Ask Dr Hartopp about the Carths" when true once {
    Says "'Sir Gervase.' Dr Hartopp lowers his voice. 'A tragic house. I attend Miss Carth, poor child: a weakness of the lungs from infancy. The least draught, the least change of air, and I would not answer for her. I have advised that she be kept warm, very warm, and quiet, and indoors.' He spreads his hands. 'Sir Gervase has followed my advice to the letter for nine years. A most conscientious father.'".
    On discuss { Assert knows(actor, hartopp_keeps_carth). }
  }
  Discovery hartopp_keeps_carth "Dr Hartopp attends Celia Carth for a weakness of the lungs, and has told Sir Gervase for nine years that she must be kept warm and indoors. Carth House's winter is his prescription.".
  Topic hartopp_bribe with hartopp "Ask Dr Hartopp what he wants of you" when legs(actor) and not hartoppOffered(actor) once {
    Says "Dr Hartopp looks at you with frank appreciation. 'A sensible question. You have Mrs Cherrett's ear; she likes you; she says so.' He takes a little purse from his waistcoat and puts it on the desk between you. 'Ten. If, when she speaks of her granddaughter's future, should the Wenlock arrangement fail, as arrangements do, you were to speak of me, warmly. That is all. I ask nothing dishonest.' He smiles. 'I never have.'".
    On discuss { Assert hartoppOffered(actor). }
  }
  // Faced with the dose: he is not a monster, and he is very frightened, and he makes the best case for himself.
  Topic hartopp_faced with hartopp "Tell Dr Hartopp you know what he wrote at the apothecary's: forty, where it said twenty" when knows(actor, drops_doubled) and not hartoppRuined(hartopp) and not gone(cherrett) and not hartoppFaced(actor) once {
    Says "Dr Hartopp does not deny it. That is the first surprising thing. He sits down, and takes off his gloves finger by finger, and lays them on his knee. 'She has a heart like a wet paper bag,' he says, 'and three months, and she is in pain every night of them, and she has forty thousand pounds that will go to a boy who writes about lattices.' He looks up. 'Do you know what a physician has, in this town? Eleven brass plates in one street. A coat he must not be seen in twice. Patients who pay at Michaelmas, if they live to Michaelmas.' The gloves. 'I gave her quiet nights. I would have married her granddaughter, and been kind to her, and kept her books for her, which she likes.' He smiles, and it does not quite arrive. 'Hope is the cheapest physic. I never charge for it. I could not afford to.'".
    On discuss { Assert hartoppFaced(actor). Assert hartoppOffered(actor). }
  }
  Topic hartopp_son with hartopp "Tell Dr Hartopp the pumper says good morning" when hartoppFaced(actor) and knows(actor, hartopp_pumpers_son) and not hartoppRuined(hartopp) once {
    Says "For a moment Dr Hartopp's face is a boy's, under a counter, washing glasses. Then it is a physician's again. 'Does he,' he says. He stands, and goes to the window, which looks down Doctors' Walk to the Abbey Yard and the steam and, below it, the Old Town's roofs. 'They carry you up,' he says, to the glass. 'Nobody carries you down. You fall.' He does not turn round. 'Take the purse or leave it. I should take it, in your place. I always have.'".
  }
  Relation hartoppFaced(group).
  Relation hartoppOffered(group). Relation hartoppPaid(group).
  Action take_hartopp_purse(actor: group, site: place) "Take Dr Hartopp's ten coin" {
    Requires able(actor) and company(actor) and at(actor, site) and at(hartopp, site) and hartoppOffered(actor) and not hartoppPaid(actor).
    Time 1 minute.
    On success { Increase quantity(actor, gold) by 10. Assert hartoppPaid(actor). }
    Result "The purse is warm from his waistcoat. 'Warmly,' says Dr Hartopp, and shows you to the door himself.".
  }
  // Paid, the company has spoken for him whether it meant to or not; it tips Mrs Cherrett toward him once the Wenlocks
  // are gone, if she is still on his drops.
  Query hartoppHasIsmay() means bannsWithdrawn(ebbas) and not hartoppCooled(hartopp) and not hartoppRuined(hartopp) and doubled(cherrett) and not kitEngaged(kit) and (hartoppPaid(party) or failing(cherrett) >= 3).

  // ── The pumper ────────────────────────────────────────────────────────────────────────────────────────────────────
  Person pumper "the pumper" at pump_room {
    Role "in a striped waistcoat, at the urn". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "The pumper fills a glass from the urn without being asked, and holds it out. 'Threepence. Good for what ails you. Everything ails you, in Hessel.'".
    Sells pump_bottle for 1 coin from 6.
  }
  Rule pumper_hours when hour(clock) >= 7 and hour(clock) < 18 and not at(pumper, pump_room) { Assert at(pumper, pump_room). }
  Rule pumper_home when (hour(clock) >= 18 or hour(clock) < 7) and not at(pumper, limbo) { Assert at(pumper, limbo). }
  Topic pumper_hartopp with pumper "Ask the pumper about Dr Hartopp" when true once {
    Says "The pumper polishes a glass for some time. 'Ambrose,' he says. 'He had this urn before me. His father had it thirty years before that; Saint Ebba's pump, they called it then, and the old man in a waistcoat like this one, and the boy under the counter washing the glasses.' He sets the glass down. 'Went to Orm on the old man's savings, and came back with a plate for Doctors' Walk, and a coat the colour of a plum, and never once since has he drunk a glass of this water, nor said good morning to me.' He fills one, for nobody. 'Can't blame him. It's a long way up that hill, and he walked it.'".
    On discuss { Assert knows(actor, hartopp_pumpers_son). }
  }
  Discovery hartopp_pumpers_son "Dr Hartopp is the old pumper's son, from the bottom of the hill; he washed glasses at the urn as a boy.".
  Topic pumper_water with pumper "Ask the pumper whether the waters really cure anything" when true once {
    Says "The pumper considers the question with the seriousness of a man who has been asked it eleven thousand times. 'They come up out of the hill hot,' he says. 'Nobody knows why. They taste of iron. People drink them and feel better.' He polishes a glass. 'People who walk up the Parade every morning, and go to bed at eleven, and don't eat three dinners, feel better. I'm not a doctor. I'm a pump.'".
  }
}

data/adventures/hessel/season.kyr:
Module hessel "The Banns at Hessel" {
  // ── The Season's slate, the King's Hesitation, and the Colonel ────────────────────────────────────────────────────
  // The count: the Season's dead, tallied in the sexton's book and the pumper's head. The keeper:
  // the pumper. The first page: nobody now living knows why the Rooms rule that the music stops at eleven; the answer
  // (the old King's minuet, left unfinished when he sat down) is in the peal of Saint Ebba's, called wrong in the fourth
  // change by the ringers of Orm for two hundred years. The price of reading it: Mr Twiss's Rule, which is his life.

  // ── Depth: things everyone does and no one can explain ────────────────────────────────────────────────────────────
  // The signpost: the bill on the board by the door, which a visitor reads whether or not they mean to.
  Observe season_bill at pump_room when true "On the board by the door, under the notice about the waters, the Season's bill is pinned in the Master of the Ceremonies' hand: THE CLOSING BALL ON THE FOURTH NIGHT, THE BAND TO STOP AT ELEVEN. Beneath it, in the pumper's pencil, as a courtesy to the visitors: Saint Ebba's rings the Season's peal on the third morning from first light, and the ringers of Orm will tell you it is wrong in the fourth change.".
  Topic pumper_gloves with pumper "Ask the pumper why the lost-property box holds only left-hand gloves" when true once {
    Says "'Because the right is the hand a gentleman drinks with,' says the pumper, 'and he keeps it bare for the glass, so it has nothing to lose.' He lifts the lid so you can see: forty gloves, all of them left, and every one worn through at the thumb of the hand that holds a glass.".
  }
  Topic pyne_peal with pyne "Ask Mr Pyne why the ringers of Orm call the peal wrong in the fourth change" when true once {
    Says "Mr Pyne closes the bell-book on his finger. 'Because it is wrong,' he says. 'And because it has been wrong since the abbey was a sty, and the ringers of Orm say they will ring it right the day Saint Ebba's does. We say we will the day they stop saying it.'".
  }
  Observe cross_custom at cross_bath when true "Everyone who comes down to the Cross Bath turns once, at the north pillar, before going in: a quarter-turn on the left heel, like a man remembering something. A boy sitting on the step with his boots in his lap says it is so you don't hit your head on the pillar going in, and that he has told them, and that there is no pillar there to hit, and that they do it anyway.".

  // ── The peal on the third morning: heard by everyone, understood by a bard ────────────────────────────────────────
  // Foreshadowed in the Sunday chapter ("a peal the ringers of Orm have called wrong in the fourth change"); paid at the Ball.
  Observe peal_heard at abbey_yard when thirdDay() and hour(clock) >= 6 and hour(clock) < 11 "The ringers are at it from first light on the third morning, and by now all eight bells of Saint Ebba's are going over the Yard in the long rolling peal, and at the fourth change the sixth bell falls a half-beat behind the rest and the peal stumbles, exactly where it always has, and goes on as if nothing had happened.".
  Observe peal_understood at abbey_yard as revelation when thirdDay() and hour(clock) >= 6 and hour(clock) < 11 and memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m)
    "The stumble in the fourth change is not a fault. Heard as a musician hears it, it is the last bar of a tune: eleven bars played and a twelfth rung wrong." teaches fourth_change.
  Discovery fourth_change "The fourth change of the peal of Saint Ebba's, that the ringers of Orm have called wrong for two hundred years, is the missing twelfth bar of an old minuet.".

  // ── Voices by calling: what each of the company makes of the Season ──────────────────────────────────────────────
  Relation hrdPump(group). Relation hrdPumpB(group). Relation hrdStall(group). Relation hrdStallB(group). Relation hrdNave(group).
  Relation hrdNaveB(group). Relation hrdHall(group). Relation hrdHallB(group). Relation hrdBeacon(group). Relation hrdBath(group).
  Rule hv_bard_pump at pump_room when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, pump_room) and not hrdPump(party)
    says "{?m} listens to the room for a minute with the pleased attention of a person at a rehearsal. 'Do you hear it?' {?m} says. 'Four conversations, and every one of them has the same rhythm. They all say a sentence, and then a name, and then 'dear.''" {
    Assert hrdPump(party).
  }
  Rule hv_thief_pump at pump_room when memberOf(?m, party) and hasCalling(?m, calling_thief) and awake(?m) and at(party, pump_room) and not hrdPumpB(party)
    says "{?m} lifts the lid of the lost-property box with one finger, and lets it fall. 'Forty left-hand gloves,' {?m} says. 'Somebody takes the right of every pair on the way out. It is not luck. It is a tidy small income.'" {
    Assert hrdPumpB(party).
  }
  Rule hv_warrior_stall at stall_street when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and at(party, stall_street) and not hrdStall(party)
    says "{?m} watches two chairmen swing a lady off the kerb between them, and nods slowly, the way one soldier nods to another. 'Left pole and right pole, in step, and the one at the back calls it,' {?m} says. 'That is a drill. I have seen worse in a regiment.'" {
    Assert hrdStall(party).
  }
  Rule hv_bard_stall at stall_street when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, stall_street) and not hrdStallB(party)
    says "{?m} stands with a thumb under the chin. 'They are calling the Parade,' {?m} says. 'Not out loud. In the knees. Seventeen steps up, a rest at the Abbey Yard, and a hitch at the seventh step where the paving is wrong. I could set that to a tune in an afternoon.'" {
    Assert hrdStallB(party).
  }
  Rule hv_cleric_nave at ebba_nave when memberOf(?m, party) and hasCalling(?m, calling_cleric) and awake(?m) and at(party, ebba_nave) and not hrdNave(party)
    says "{?m} stops at the foot of the west window and looks at the two tablets side by side, the white one and the slate. 'One of those is a memorial to a person who is still alive,' {?m} says." {
    Assert hrdNave(party).
  }
  Rule hv_thief_nave at ebba_nave when memberOf(?m, party) and hasCalling(?m, calling_thief) and awake(?m) and at(party, ebba_nave) and not hrdNaveB(party)
    says "{?m} runs a thumbnail down the edge of the poor-box, and is a little sorry to find that it would not be worth the trouble." {
    Assert hrdNaveB(party).
  }
  Rule hv_mage_hall at hospital when memberOf(?m, party) and hasCalling(?m, calling_mage) and awake(?m) and at(party, hospital) and not hrdHall(party)
    says "{?m} stands at the end of the ward and counts, lips moving. 'Twenty beds,' {?m} says. 'Eleven vinegar jugs. One window in four is shut, and it is always the same four.'" {
    Assert hrdHall(party).
  }
  Rule hv_monk_hall at hospital when memberOf(?m, party) and hasCalling(?m, calling_monk) and awake(?m) and at(party, hospital) and not hrdHallB(party)
    says "{?m} stands very still among the beds and does not speak. After a time someone coughs, and then someone sleeps. 'They can feel it,' {?m} says, low." {
    Assert hrdHallB(party).
  }
  Rule hv_ranger_beacon at beacon when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, beacon) and not hrdBeacon(party)
    says "{?m} crouches by a trodden patch of turf and picks up a pinch of it. 'Everyone walks the Beacon in pairs,' {?m} says. 'I can see which ones were not on speaking terms. The path is wider where they kept apart.'" {
    Assert hrdBeacon(party).
  }
  Rule hv_bard_bath at cross_bath when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, cross_bath) and not hrdBath(party)
    says "{?m} turns once, at the north pillar, without deciding to, and laughs at {?m}self. 'I caught it,' {?m} says." {
    Assert hrdBath(party).
  }

  // ── The King's Hesitation: the bard's way through the Rule, and a choice that costs ──────────────────────────────
  // Mr Twiss's Rule (no dancing after eleven, "though the King himself should ask") is why the Closing Ball stops. A bard
  // who heard the peal on Sunday can hum the twelfth bar into the stopped band. Done to Mr Twiss alone it earns him
  // back his dignity and a debt; done aloud it ends the Rule and the Ball goes on, and he loses the one law he has kept.
  Relation barHummed(group). Relation ruleBroken(group). Relation barPrivate(group).
  Action hum_bar_privately(actor: group, site: place, m: member) "Hum the missing twelfth bar to Mr Twiss, under your breath, as the band stops" {
    Description "{m} heard it in the peal. It is the bar that ends the King's minuet.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ballroom) and at(twiss, ballroom) and afterEleven() and knows(actor, fourth_change)
      and memberOf(m, actor) and hasCalling(m, calling_bard) and awake(m) and not barHummed(party).
    Time 2 minutes.
    On success { Assert barHummed(party). Assert barPrivate(party). Increase twissFavour(twiss) by 2. }
    Result "{m} hums it, close, to Mr Twiss's collar: eleven bars he knows, and a twelfth that he has always heard as a mistake in the bells. He goes still. 'Again,' he says, very low, and {m} does. His eyes are shut, and his foot, in its dove-grey shoe, is beating the bar. 'I was seven,' he says. 'My father hummed it, wrong, to put me to sleep.' He opens his eyes. 'I shall remember that you did not do it aloud.'".
  }
  Action hum_bar_aloud(actor: group, site: place, m: member) "Hum the missing twelfth bar aloud, to the stopped band, and let the Rooms hear the minuet end" {
    Description "It finishes the tune. It also finishes the reason for the Rule.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ballroom) and at(twiss, ballroom) and afterEleven() and knows(actor, fourth_change)
      and memberOf(m, actor) and hasCalling(m, calling_bard) and awake(m) and not barHummed(party).
    Time 2 minutes.
    On success { Assert barHummed(party). Assert ruleBroken(party). Increase twissFavour(twiss) by 3. Assert cherrettDanced(cherrett). }
    Result "{m} sings it, out, across the emptying floor, the twelfth bar, which is a falling third and a held note. The first violin takes it, and the second, and the band comes in under it as a person comes in at a door they had forgotten was a door. The Season, with its shawls, stops. Mr Twiss stands in the middle of the floor with his hand still lifted to stop the music, and does not lower it, and the minuet finishes, for the first time in a hundred and twenty years, at the bar it was always meant to. He turns slowly to Mrs Cherrett's chair. 'Madam,' he says, in a voice nobody in the Rooms has heard. 'I think we are going to have to dance.'".
  }
  Observe ruleBroken_seen at ballroom when ruleBroken(party) and afterEleven() "The band is playing the King's minuet to the end, again, and again, and nobody has told the Master of the Ceremonies the hour. Candles are going out one by one in the five chandeliers, and nobody is leaving.".

  // ── Colonel Ede, on the end bed: a grave scene in a comic book ─────────────────────────────────────────────
  Person ede "Colonel Ormerod Ede" at hospital {
    Role "a dying colonel of foot, on the end bed, who came for the waters and has had them". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "A very old gentleman with a clipped white moustache lies on the end bed with his boots still on, which the ward sister has given up arguing about. 'Don't get up,' he says, though you were not. 'Don't be told I'm dying. I'm not. I'm being very slow.'".
  }
  Relation satWithEde(group). Relation edeGone(group).
  Rule ede_dies when fourthDay() and hour(clock) >= 2 and hour(clock) < 5 and not edeGone(ede) { Assert edeGone(ede). Assert at(ede, limbo). }
  Topic ede_regiment with ede "Ask Colonel Ede about his regiment" when not edeGone(ede) once {
    Says "'The Fusiliers,' says the Colonel. 'We held a bridge once, at a place I will not pronounce, for a night and a day, against nine times our number, and I have forgotten the name of everyone who held it with me.' He studies the ceiling. 'Isn't it extraordinary? I can tell you the number of buttons on every man's coat.'".
  }
  Action sit_with_ede(actor: group, site: place) "Sit up with Colonel Ede through the night watches" {
    Description "Nobody has sat up with him. The ward sister has twenty beds and one night.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hospital) and not edeGone(ede) and (hour(clock) >= 21 or hour(clock) < 5) and not satWithEde(party).
    Time 6.
    On success { Assert satWithEde(party). }
    Result "You sit by the end bed through the small hours with a candle shaded, and he talks for a while, and then is quiet, and then talks again about nothing: a dog, a dance, a girl whose name he does not remember, only that she hummed. Towards four he says 'Is it my watch?' and you say it is not, and he says 'Good,' and sleeps; and you are still there at six when the sister brings the vinegar.".
  }
  Rule ede_ottery_sits at hospital when satWithEde(party) and following(ottery, party) and not spread(ede_ottery_told)
    says "Ottery, at the foot of the bed, takes his spectacles off. 'He won't see Thursday,' he says. He does not lower his voice; the Colonel is asleep. 'I never say it in front of them while they wake. It is my one piece of tact.' He looks at you. 'You sat. Good. Most don't.'" { Assert spread(ede_ottery_told). }
  Entity ede_ottery_told: fact "Ottery on the Colonel".
  Rule fate_ede_kept when accounting() and satWithEde(party) and not spread(fate_ede) says "Colonel Ede died on the ward in the small hours of the last night with a stranger beside him, and the ward sister, who found them at six, let the stranger sleep another hour in the chair. The Colonel had his boots on. It is said on the ward that this was the only argument she ever lost to him." { Assert spread(fate_ede). }
  Rule fate_ede_alone when accounting() and not satWithEde(party) and not spread(fate_ede) and cameToHessel(party) says "Colonel Ede died on the ward in the small hours of the last night with the ward sister at the other end of it, and was buried on the Tuesday in his boots, which she had given up arguing about." { Assert spread(fate_ede). }
  Entity fate_ede: fact "the Colonel".

  // ── A world event, read: Mrs Scrope hears a thing from the coast ──────────────────────────────────────────────────
  Observe scrope_slack_news at pump_room when befell(slack_opened) and at(scrope, pump_room) "Mrs Scrope has a new story and is telling it for the third time to the same lady: that at Sennet, on the coast, under a college, a black stair was found in a floor, and a ship came up it. 'In a floor,' she says. 'I had it from a milliner who had it from a sea-captain's widow. I never repeat anything.'".
  Observe scrope_ship_news at pump_room when befell(remainder_harboured) and at(scrope, pump_room) "Mrs Scrope has put the ship into her story, with a crew. 'They are said to be very pale,' she says, 'and to keep their own hours.'".
  // Where the Season comes from, and what would bring a stranger up the south road.
  Topic scrope_south with scrope "Ask Mrs Scrope who comes to Hessel for the waters, and from where" when true once {
    Says "'Everyone,' says Mrs Scrope, delighted to be asked. 'The gouty from Corran, with their lawyers, and the nervous from the coast, with their doctors, and anyone at all with an inheritance and no one to leave it to. Mrs Cherrett's husband came with a compass and a canal and never went home. That is the way of the Season. You arrive for a week and a thing happens, and you are here for the rest of your life.'".
  }
  Topic mopsa_delve with mopsa "Ask Mopsa about the Delve Cut and the three canals" when true once {
    Says "'Josiah dug it with his own hands for the first mile,' says Mopsa. 'Then he hired navvies, and then he hired the navvies' wives to cook for the navvies, and that is where she started. It joins the cut at Corran, and somebody there, at the Lesser Instruments, bought the first of the pumps.' She laughs. 'She says the water goes where she told it. I have never been sure which of them was joking.'".
  }
}

data/adventures/hollins/acts.kyr:
Module hollins "Behind the Wainscot" {
  // ── The chapters ──────────────────────────────────────────────────────────────────────────────────────────────────
  // Bootscrape; I, the Ratcatcher, from the first step inside; Ten Past Four, when the Clock strikes; II, the Thaw,
  // from the morning the fire is lit; III, the Smoking, from the day the sulphur is in the house or the seventh day;
  // the Last Night, the tenth.
  Relation bootRoom(place).
  Initially Assert bootRoom(march_road). Initially Assert bootRoom(bs_street). Initially Assert bootRoom(mat_tap).
  Initially Assert bootRoom(tallis_yard). Initially Assert bootRoom(arkle_shop). Initially Assert bootRoom(saltash_office).
  Chapter ch_bootscrape "Bootscrape" when at(party, ?p) and bootRoom(?p) and not within(party, house) "Bootscrape lives on a giant's doorstep and makes a living from what falls out of the letterbox. It has done so since before the oldest grandmother in it was born, and has never told a carter what it knows. Four days ago a wagon the size of an inn came over the moor, and a woman as tall as a church tower got down from it and walked up the step and put a key in the door, and since then the village has been very quiet, and has watched the chimney.".
  Chapter ch_ratcatcher "I. The Ratcatcher" when within(party, house) "Inside, the house is a country. It is cold, as it has been since the Going, except where she has lit fires, and dim, except where she has opened shutters; and everywhere, in the walls, in the grate, on the shelves, the people who came in by the letterbox are going about their lives without a sound, listening, as they have listened every day since Thursday, for the floor to shake.".
  // The first dusk: the Lady winds the Clock, and it strikes, for the first time since the Going.
  Rule lady_winds_clock when at(lady, clock_foot) and state(long_clock, stopped) and hour(clock) >= 18 { Assert state(long_clock, going). }
  Rule lady_rewinds when at(lady, clock_foot) and state(long_clock, jammed) and clockTrapped(pye) and dayN(hollins) >= 5 and trapsLifted(lady) { Assert state(long_clock, going). }
  Chapter ch_tenpast "Ten Past Four" when state(long_clock, going) and within(party, hollins_country) "At six o'clock on the first evening the Lady came down the Stair, slowly, a step at a time, with Mrs Pyecroft on her shoulder and a candle in her hand like a burning tree, and the whole Hall went still. She crossed the flagstones to the Long Clock, opened its trunk, felt inside for the key, and wound it, forty turns, each turn a groan of brass through the house. Then she set the hands by her watch, and shut the trunk, and stood back; and the Clock struck six. It had not struck since the Going. The sound went into every wall in the house, and the Wainscot stood in its doorways and counted the strokes, six, and then stood there after, in the silence, counting a seventh that did not come.".
  Chapter ch_thaw "II. The Thaw" when hearthBurned(hollins) and within(party, hollins_country) "The fire was lit in the drawing room at nine on the second morning. By noon the warmth had gone into the walls, and the cress on the sill had turned to face the glass, and in the Skirting people were taking off coats that their grandparents had put on. The Hearth was gone. It is the warmest the house has been in three hundred years, and the most frightened.".
  Chapter ch_smoking "III. The Smoking" when (pyeHasSulphur(pye) or dayN(hollins) >= 7) and not ladyDead(lady) and within(party, hollins_country) "Now the house is warm all through, and the Lady sleeps more and works less, and Mrs Pyecroft goes about with her lips pressed together. In the Wainscot people have begun to pack, without saying so: a bundle by the door, a child's shoes laced together. Faith Penny has begun to enter every name in the register twice, in case.".
  Chapter ch_last "The Last Night" when day10() and hour(clock) >= 18 and not ladyDead(lady) and within(party, hollins_country) "On the tenth evening the Lady did not ring for her supper, and Mrs Pyecroft came down the ribbon from her hatbox and sat on the counterpane by her hand, and did not go back up. The house knows. The Clock goes on. The fire in her room has been let burn low.".

  // ── Her death ─────────────────────────────────────────────────────────────────────────────────────────────────────
  Rule lady_dies when day10() and hour(clock) >= 23 and not ladyDead(lady) { Assert ladyDead(lady). }
  Relation satWith(group).
  Action sit_with_lady(actor: group, site: place) "Sit with her on the counterpane, by her hand, until the end" {
    Description "She will not see the morning.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, counterpane) and day10() and hour(clock) >= 18 and not ladyDead(lady) and ladyKnows(lady) and not satWith(party).
    Time 6.
    On success { Assert satWith(party). }
    Result "You sit on the counterpane by her hand, which is as big as a boat and as light on the linen as a leaf. She talks for a while, not much, in a voice you have to lean close to: about a coast in the north where the cliffs are white and the sea comes in green; about Honor Lacey, who could whistle through her teeth; about her mother. Then she asks you to stand where she can see you, in the candle, and you do; and she looks at you a long time, exactly, the way she looked at every coast in Imbar. 'There,' she says. 'Drawn.' And she closes her eyes.".
  }
  Rule wainscot_gathers at counterpane when day10() and hour(clock) >= 21 and ladyKnows(lady) and not ladyDead(lady) and at(party, counterpane) and not gathered(hollins)
    says "They come up the Stair in the dark, all of them who will: the Court in its good gloves, the colliers, the Readers, the Keys, Faith Penny in her green cap, the Winders with a candle each, Ma Riser carrying the old ones up her ladders one by one. They stand on the floor of the room, and on the bedside table, and along the foot of the bed, very quiet, six hundred people the size of the Lady's thumb. She cannot see them. She can hear them breathing. 'Oh,' she says. 'All of you.'" { Assert gathered(hollins). }
  Relation gathered(place).
  Rule concert_last at counterpane when day10() and hour(clock) >= 22 and gathered(hollins) and concertPlayed(party) and not lastAir(hollins)
    says "And from downstairs, through the floor, slow as weather, a note; and a minute's silence; and another. The Keys have gone down to the piano without being asked. The Lady smiles, and says the words under her breath with them, a beat ahead, as she must have said them in the nursery to a family in a doll's house, three hundred and twelve years ago: the Little Ship." { Assert lastAir(hollins). }
  Relation lastAir(place).

  // ── Places heard of ───────────────────────────────────────────────────────────────────────────────────────────────
  Initially Assert leadsTo(wainscot_told, skirting). Initially Assert leadsTo(stone_told, waiting_stone).
  Initially Assert leadsTo(coal_hole_known, kitchen_garden). Initially Assert leadsTo(dumbwaiter_known, kitchen_floor).
  Initially Assert leadsTo(court_told, small_house_parlour). Initially Assert leadsTo(page_held, letterdrift).
  Initially Assert leadsTo(underfolk_uncounted, wine_bins). Initially Assert leadsTo(moot_coming, small_house_parlour).

  // ── What the company is about ─────────────────────────────────────────────────────────────────────────────────────
  Objective obj_rats when hiredBy(party, pye) and not soldOut(party) and not pyeTurned(pye) and not ladyDead(lady) "Clear the pantry and the skirtings of rats for Mrs Pyecroft, twopence a tail on the string; she wants to be told where they nest.".
  Objective obj_hearth when knows(party, fire_coming) and not hearthBurned(hollins) and not hearthWarned(hollins) "Get the colliers out of the Hearth before the fire laid on the irons in the middle of their town is lit.".
  Objective obj_trap when knows(party, trap_seen) and state(pye_trap, set) and not watDead(wat) and not trapGivenUp(pye) "Spring Mrs Pyecroft's trap on the run into the back of the Pantry before Wat Tallowby goes in, as he does every morning before light.".
  Objective obj_letter when carries(party, c_letter) "Deliver the letter with the black seal where the Lady will find it: on her chart in the Library, or by her bed.".
  Objective obj_reply when carries(party, reply) "Carry the Lady's reply up the moor to the Waiting Stone.".
  Objective obj_chart when knows(party, chart_plan) and not chartWritten(party) and not ladyKnows(lady) "Draw the Wainscot into the Lady's chart at night, in a hand she can read: pace it out first, and get ink from the Readers.".
  Objective obj_answer when state(lady_chart, questioned) and knows(party, chart_known) and not ladyKnows(lady) "Answer the Lady's question in the margin of her chart: WHO ARE YOU?".
  Objective obj_moot when knows(party, moot_coming) and not occasionOver(moot) and dayN(hollins) <= 3 "Be at the Moot in the Small House parlour at two in the afternoon of the third day, with someone of the Wainscot to speak for you.".
  Objective obj_keys when knows(party, keys_need) and not concertPlayed(party) and not ladyDead(lady) "Help the Keys play the First Air to its end at night: their lost page, weight on the bass, and someone to lead the count.".
  Objective obj_smoke when knows(party, smoking_planned) and not smokingOver(hollins) and not ladyForbids(lady) and not candlesGone(pye) "Stop Mrs Pyecroft smoking the house with sulphur on the night of the {smokeNight(hollins)}th, or get the Wainscot out of its way.".
  Objective obj_poison when knows(party, poison_plan) and not poisoned(lady) and not haspStands(hasp) and not sugarSpilled(party) and not brackStopped(brack) and not potEmptied(party) and dayN(hollins) <= 6 "Keep the Jarl's poison out of the Lady's sugar on the sixth afternoon, while she naps before tea.".
  Objective obj_will when willWanted(lady) and not willMade(lady) "The Lady would make her will: fetch Mr Salcombe from Bootscrape to witness it, and someone to write large.".
  Objective obj_deed when knows(party, will_needs) and (willWanted(lady) or willMade(lady)) and not deedLodged(party) and not deedSold(party) "Find the deed of Hollins, which nobody upstairs has seen, and lodge it with Mr Salcombe beside her will.".
  Objective obj_bell when bellVolunteer(party) and not belled(bishop) "Bell the cat, as you told the Moot you would.".
  Objective obj_kit when knows(party, nan_fears) and not kitNanMet(kit) "Bring Kit Lacey and Nan Collier, who have written to each other for two years along the bell-wires, into one room.".
  Objective obj_under when knows(party, underfolk_uncounted) and not underfolkEntered(annet) "See the Under-folk of the cellars entered in the Post's register, so that they are somebody's, and get water.".
  Objective obj_verity when knows(party, verity_plans) and not verityRelents(verity) and not verityCaught(verity) and not ladyDead(lady) "Keep Sister Verity from stopping the Long Clock.".
  Objective obj_regiment when knows(party, fennick_stopped) and not standDown(regiment) and not regimentStopped(regiment) "Decide what becomes of the Tin Regiment, which is running down because Fennick will not wind it.".
  Objective obj_sovereign when knows(party, sovereign_wanted) and not sovereignSold(party) and not ladyDead(lady) "Bring Hob Ludd a Whitbread sovereign out of the Lady's purse, for thirty coin, if you mean to.".
  Objective obj_last when day10() and ladyKnows(lady) and not ladyDead(lady) "Be with her, if you can. She will not see the morning.".
}

data/adventures/hollins/after.kyr:
Module hollins "Behind the Wainscot" {
  // ── Afterwards: Hollins, come back to ─────────────────────────────────────────────────────────────────────────────
  // In a world the book does not close on her death; a company that comes back finds the house as it was left.
  Query freeheld() means reached(freehold).
  Query sold() means reached(sold) or reached(last_game_sold).
  Query emptied() means reached(smoking) or reached(downladder).
  Query known() means reached(last_game) or reached(freehold) or reached(last_game_sold).
  Chapter ch_after_free "Hollins, Freehold" when freeheld() and within(party, hollins_country) and dayN(hollins) >= 11 "Hollins stands on its hill with its shutters open and smoke going up from four chimneys, none of them very large. A notice on the Mat's door says, in Faith Penny's hand: HOLLINS. VISITORS BY THE SLOT. PLEASE ENTER YOUR NAME. NO RATCATCHERS.".
  Chapter ch_after_sold "Hollins, Coming Down" when sold() and within(party, hollins_country) and dayN(hollins) >= 11 "Scaffolding stands up the face of Hollins like a cage, and men are on the roof, small as ants, taking the slates off one by one and sending them down on ropes. Bootscrape is full of strangers' carts, and of people who are not strangers at all, living in lofts.".
  Chapter ch_after_empty "Hollins, Empty" when emptied() and within(party, hollins_country) and dayN(hollins) >= 11 "Hollins stands on its hill with its windows dark. Nobody goes in by the Slot now. The flap has been let fall shut, and somebody has nailed it.".
  Chapter ch_after_cold "Hollins, Cold" when (reached(cold) or reached(tea) or reached(ratcatcher)) and within(party, hollins_country) and dayN(hollins) >= 11 "Hollins stands on its hill as it stood for three hundred years, shut, its chimneys cold. People still go in and out of the letterbox, quietly, as they always did.".
  Observe street_free at bs_street as feature when freeheld() and not dark() "A second rope ladder hangs beside Hob's now, painted green, with a sign at its foot: THE WAINSCOT. FREE. And at the top of the step the letterbox flap stands open on its own, unwedged, with a bell on a string inside it.".
  Observe hall_free at hall_flags as feature when freeheld() and not dark() "People are crossing the flagstones in daylight, unhurried, carrying baskets; a child is running. On the east wall, beside the Long Clock, hangs the Lady's chart of Hollins, framed, a field of paper, with the Wainscot drawn into it in a big black hand, and in the margin, in hers: SO YOU DO. E. W.".
  Observe hall_sold at hall_flags as feature when sold() "The Hall is full of the noise of hammers somewhere overhead, and dust comes down through the light in slow sheets. The Skirting doors stand open on empty rooms. Someone has chalked on the flagstones, in a fair round hand: GONE TO BOOTSCRAPE. ASK AT THE MAT.".
  Observe hall_empty at hall_flags as feature when emptied() "Along the skirting, at the height of your knee, a yellow stain runs the length of the Hall, like a tidemark.".
  Observe nursery_free at small_house_hall as feature when freeheld() "Under the framed WELCOME someone has pinned a sheet of the Lady's own paper, folded small: a page in her huge slanting hand, beginning MY DEAR HONOR, which the Court reads aloud on the first of every month.".
  Topic jory_after with jory "Ask Jory Mudge how things go up at the house" when known() once {
    Says "Jory Mudge leans on the bread. 'You'd not credit it,' he says. 'The Court sends down to the Mat for a barrel every Saturday and pays in coin. The Keys play on Midwinter night and you can hear it in the street, slow as a funeral and sweet as a wedding. The Readers have started on N.' He grins. 'Bootscrape's never been so respectable. We hate it.'".
  }
}

data/adventures/hollins/bedroom.kyr:
Module hollins "Behind the Wainscot" {
  // ── The Lady's room ───────────────────────────────────────────────────────────────────────────────────────────────
  // Along the landing, the room she was born in: the bed, the bedside table with her glass and her medicine and her
  // purse, and the dressing table, on which Mrs Pyecroft lives in a hatbox. The Bishop sleeps on the counterpane by day.
  Place bedroom_floor "the floor of the Lady's room" is room within first_floor at 2, 1.
  Place bedside "the bedside table" is room within first_floor at 3, 1.
  Place counterpane "the counterpane" is room within first_floor at 3, 0.
  Place hatbox "Mrs Pyecroft's hatbox" is room within first_floor at 2, 0.

  Passage bedroom_door "the door of the Lady's room" is passage between landing and bedroom_floor taking 10 minutes.
  Passage bedside_leg "the bedside table's leg" is steps between bedroom_floor and bedside taking 10 minutes.
  Passage bed_valance "the valance, up onto the bed" is steps between bedroom_floor and counterpane taking 10 minutes.
  Passage bedside_step "the step from the table to the pillow" is passage between bedside and counterpane taking 5 minutes.
  Passage hatbox_ribbon "the ribbon ladder up the dressing table" is steps between bedroom_floor and hatbox taking 10 minutes.

  Observe bedroom_scene at bedroom_floor when true "The Lady's room. A fire burns in the grate, and has burned since she came; it has been the warmest room in Hollins since she came, and the warmth is extraordinary after the Hall, like walking into a loaf. The bed is a hill of white linen under a canopy, the bedside table beside it on tall legs, and on the dressing table a hatbox stands with a little door cut in its side and a curtain at a window. Along the mantel, in frames, maps: coasts, harbours, a whole sea, drawn so finely that the waves are lines of figures.".
  Observe bedroom_lady at bedroom_floor as ambience when at(lady, bedroom_floor) "The Lady is dressing, slowly, by the window, with her back to the room; every movement of her arms is a weather in the air.".
  Observe bedside_scene at bedside when true "The top of the bedside table: a candlestick like a column, a glass as round as a millpond on a handle, a medicine bottle as tall as a chimney with FOXGLOVE: TEN DROPS IN WATER on its label, a framed miniature of a tall woman in grey, and a purse of green silk lying open, with gold in it.".
  Observe counterpane_scene at counterpane when true "The counterpane is a white country of quilted hills and valleys, warm, smelling of lavender and old woman. At its head the pillows rise like snowfields.".
  Observe counterpane_lady at counterpane as ambience when at(lady, counterpane) and not ladyDead(lady) "Under the counterpane the Lady sleeps, a range of hills that rises and falls; her breath goes over you slow and warm and with a catch in it, every so often, like a door that sticks. Her face on the pillow is the size of a cottage, and very old, and in sleep it looks frightened.".
  Observe counterpane_cat at counterpane as sign when at(bishop, counterpane) and asleep(bishop) and not belled(bishop) "Across the foot of the bed, in a heap of grey fur as big as a haystack, the Bishop is asleep: eighteen feet of cat, his flank going up and down, one ear twitching at nothing, his paws, each the width of a cart-wheel, folded under his chest. Round his neck is a collar of red leather with a silver ring on it, and nothing hanging from the ring.".
  Observe counterpane_belled at counterpane as sign when belled(bishop) and at(bishop, counterpane) "Across the foot of the bed, in a heap of grey fur as big as a haystack, the Bishop lies curled: eighteen feet of cat, his flank going up and down. A silver bell hangs from his collar now, and rings, faintly, whenever he breathes.".

  // ── The Bishop ────────────────────────────────────────────────────────────────────────────────────────────────────
  Species bishop_kind "a giant's cat" like behemoth temperament territorial described "A long-haired grey cat of the tall folk's breeding: eighteen feet from nose to tail, with eyes you could row across, whiskers like ropes, and a purr you feel in your teeth. He is not cruel. He is a cat.".
  Person bishop "the Bishop" at counterpane {
    Role "the Lady's cat, eighteen feet long". Species bishop_kind. Level 6. Pronouns he.
    Warns "Out in the dark, low down, two lamps open, each the size of a cartwheel, green; and a sound like a sack being dragged stops. The Bishop has seen you. He is settling on his haunches, the way cats do, with his hind end working. You have a moment, no more.".
    Comes "Out of the dark something huge and grey comes at you, silent, low, fast as a dropped stone.".
    Flinches "The Bishop's ears go back at the smell of the catmint, and then forward, and he goes after it, rolling, forgetting you entirely.".
  }
  Relation belled(group). Relation bellTried(group).
  Kind sleigh_bell_kind "the sleigh bell" is gear worth 1 weighing 3 described "A giant child's silver sleigh bell, deep enough to bathe in, on a red silk ribbon as wide as a sash. It rings if you breathe on it, so you carry it with your hand over the clapper.".
  Item sleigh_bell "the sleigh bell" is sleigh_bell_kind at toy_box.
  Action bell_cat(actor: group, site: place) "Tie the sleigh bell to the Bishop's collar while he sleeps" {
    Grave "If he wakes, he wakes with you on his neck.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, counterpane) and at(bishop, counterpane) and asleep(bishop) and carries(actor, sleigh_bell) and not belled(bishop) and not bellTried(party).
    Time 2.
    Resolve check(actor, stealth, dc_hard).
    On success { Assert belled(bishop). Spend sleigh_bell from actor. }
    On failure { Assert bellTried(party). Assert strikes(cat_paw, actor). Assert at(actor, bedroom_floor). }
    Result "You go up the grey slope of him on your hands and knees, through fur as deep as standing corn, with the bell held against your chest and your hand over the clapper. His flank lifts you and lets you down. At the collar you have to lie flat along his neck, in the heat of him, with his pulse under you like someone knocking on a door, and thread the ribbon through the ring, and knot it, and knot it again, with your fingers shaking. Then you take your hand off the clapper. The bell rings, once, very softly. An ear turns. The great eye nearest you opens, a slit of green the size of a window, and looks at nothing, and closes. You slide down his shoulder into the counterpane and lie there for a long time before you can move.".
    Otherwise "His fur moves under your hand the wrong way; a muscle jumps; the bell rings, loud, against his throat. And the Bishop is awake, all at once, the way cats are. He does not get up. He does not need to. A paw the size of a cartwheel comes round, lazily, claws half out, and bats you across the counterpane like a cork, and again, and then off the edge of the bed altogether; and you fall a long way, through the valance, onto the floor, and lie there, and hear him above you settle, and begin, enormously, to purr.".
  }
  Hazard cat_paw "A cat's paw, playing" means "Deal (1d6) physical damage to ally unless dexterity save against (12).".
  Observe bell_heard near bishop when belled(bishop) and prowling() "Somewhere in the dark the Bishop's bell rings, softly, every time he moves; and all along the skirting, at the sound, people step back into their doorways and wait for it to go by, and then go on.".
  Rule bell_tried_resets when bellTried(party) and hour(clock) == 7 { Retract bellTried(party). }
  Rule catmint_scattered when carries(party, catmint) and at(party, ?p) and at(bishop, ?p) and prowling() and not catAway(bishop)
    says "You fling the armful of catmint down on the floor in front of him. The Bishop stops. His nostrils widen. Then he is down on his back in it, rolling, kneading the air, making a sound like a cart going over cobbles; and when he gets up he goes off after the smell of it on the draught, out through the dark toward the kitchen and the garden door, and does not look back." { Spend catmint from party. Assert catAway(bishop). Retract assails(bishop, party). }

  // ── The bedside: the purse, the glass, the medicine ───────────────────────────────────────────────────────────────
  Thing lady_purse "the Lady's purse" at bedside {
    Holds.
    State open "A purse of green silk lies open on the table, as big as a tent, with gold coins in it each a foot across.".
  }
  Relation sovereignMissed(group).
  Rule sovereign_missed when sovereignSold(party) and dayN(hollins) >= 2 and not sovereignMissed(lady) and not ladyKnows(lady) { Assert sovereignMissed(lady). Assert poisonLaid(skirting). }
  Event sovereign_told within house when sovereignMissed(lady) "Word goes along the Skirting by noon, from the Court's maids who heard it through the floor: the Lady has counted her purse, and is one sovereign short, and said, quite quietly, 'Then they are real, Dorothea, and they are thieves'; and Mrs Pyecroft has gone down to the village for more poison.".
  Action lay_letter_bedside(actor: group, site: place) "Lay the letter with the black seal against her candlestick, where she will see it" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bedside) and carries(actor, c_letter) and not letterDelivered(party).
    On success { Spend c_letter from actor. Assert letterDelivered(party). Assert letterAt(bedside). }
    Result "You prop it against the foot of the candlestick, black seal outward, where she cannot reach for her glass without touching it. It stands there like a door. You think of Faith Penny's oath, and that it is kept.".
  }
  Action lay_letter_chart(actor: group, site: place) "Lay the letter with the black seal on her chart, where she will find it at nine" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, chart_table) and carries(actor, c_letter) and not letterDelivered(party).
    On success { Spend c_letter from actor. Assert letterDelivered(party). Assert letterAt(chart_table). }
    Result "You lay it in the middle of the chart, on the Hall, black seal up. It covers most of the drawing room.".
  }
  Relation letterAt(place). Relation letterRead(group). Measure letterReadOn(entity).
  Rule letter_read_bed when letterAt(bedside) and at(lady, counterpane) and hour(clock) >= 21 and not letterRead(lady) and not ladyDead(lady) { Assert letterRead(lady). Increase primed(lady) by 1. Set letterReadOn(lady) to dayN(hollins). }
  Rule letter_read_chart when letterAt(chart_table) and at(lady, chart_table) and not letterRead(lady) and not ladyDead(lady) { Assert letterRead(lady). Increase primed(lady) by 1. Set letterReadOn(lady) to dayN(hollins). }
  Event letter_read_told when letterRead(lady) and letterReadOn(lady) == dayN(hollins) and (at(party, bedside) or at(party, counterpane) or at(party, bedroom_floor) or at(party, chart_table) or at(party, sill)) "She finds it. She holds it close to her eye, and sees the seal, and her hand stops. Then she breaks the seal with her thumbnail, slowly, and unfolds it, and reads, with the glass, to the end; puts the glass down, and reads it again without, moving her lips, since she knows it already. 'Corwen,' she says. 'Oh, Corwen. You fool.' And then, sharply, to the room, to nobody: 'Who brought this?'".
  // She writes a reply, and leaves it where the letter came, for whoever brings her letters.
  Kind reply_kind "the Lady's reply" is gear worth 0 weighing 3 described "A sheet of a giant's paper folded small, which is to say the size of a door, sealed with a plain wafer. On the outside, in her big fine slanting hand: To Corwen Ashgrove, at the stone on the moor. And under it, smaller: To whoever brought my letter: I cannot carry this. Would you?".
  Item reply "the Lady's reply" is reply_kind at nowhere.
  Relation replyWritten(group). Relation replyLaid(group). Relation stoneTurned(group). Measure laidOn(entity).
  Rule reply_written when letterRead(lady) and dayN(hollins) > letterReadOn(lady) and not replyWritten(lady) and not ladyDead(lady) { Assert replyWritten(lady). Assert at(reply, chart_table). }
  Observe reply_seen at chart_table as feature when at(reply, chart_table) "On the corner of the chart, held down by her glass, a folded sheet with a wafer seal, addressed in her hand.".
  Action lay_reply(actor: group, site: place) "Lay the Lady's reply in the heather at the foot of the Waiting Stone" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, waiting_stone) and carries(actor, reply) and not replyLaid(party).
    On success { Spend reply from actor. Assert replyLaid(party). Set laidOn(reply_kind) to dayN(hollins). }
    Result "You lay it in the heather at the stone's knees, and put a flint on it against the wind, and step back. Nothing happens. It is a stone. The wind goes over the moor and the paper lifts at its corners under the flint and settles. You stand a while anyway.".
  }
  Rule stone_turns when replyLaid(party) and dayN(hollins) > laidOn(reply_kind) and hour(clock) >= 18 and not stoneTurned(party) { Assert stoneTurned(party). }
  Action open_c_letter(actor: group, site: place) "Break the black seal and read the letter yourself" {
    Grave "It is hers, and the Post's oath was to deliver it whole.".
    Requires able(actor) and company(actor) and at(actor, site) and carries(actor, c_letter) and not letterOpened(party).
    Time 2.
    On success { Assert letterOpened(party). Assert knows(actor, corwen_letter). }
    Result "The wax cracks like a plate. The sheet is the size of a sail and you have to walk it: E. They tell me you are sent away tomorrow, to the sea. I will wait for you at the stone on the moor where we said, every evening, until you come home. However long. Don't laugh. You know I am slow. C.".
  }
  Relation letterOpened(group).
  Discovery corwen_letter "The letter with the black seal is from Corwen, who swore to wait for Ermengarde at the stone on the moor every evening until she came home, however long.".
  Observe faith_broken at letterdrift as sign when letterOpened(party) and letterDelivered(party) "Faith Penny has struck a line through an entry in the register, and written beside it in red: DELIVERED, OPENED. She does not look up when you come in.".

  // ── Mrs Pyecroft's hatbox ──────────────────────────────────────────────────────────────────────────────────────────────
  Observe hatbox_scene at hatbox when true "Inside the hatbox, a room: our size, plainly furnished from a town shop, a narrow bed, a washstand, a writing desk with a ledger on it, a chair, a little stove. On the wall a sampler: GOD BLESS OUR HOME, worked in black thread. Through the curtained window the Lady's room goes away enormous, and the bed, and the fire.".
  Observe hatbox_sulphur at hatbox as feature when pyeHasSulphur(pye) and not candlesGone(pye) and not smokingOver(hollins) "Under the bed, wrapped in brown paper, three fat yellow candles stamped with skulls.".
  Discovery pye_ledger "Mrs Pyecroft's ledger: she has had no wages from the Lady in eleven years, and is owed four hundred and forty crowns. The Hollins Stone Concern will pay her one part in ten of the price of the house's stone, upon the Lady's death, if the deed is found. The Lady signed a conveyance to the Concern in the spring, which Pyecroft read to her as a letter to her bank." {
    Source pye_book "Mrs Pyecroft's ledger" at hatbox readable by party.
  }
  Discovery smoking_planned "Mrs Pyecroft means to smoke the house with sulphur candles from the drawing room to the kitchen, on a night when the Lady is abed upstairs: lit in a shut house, the smoke sinks, and fills the walls.".
  Relation pyeHasSulphur(group). Relation candlesGone(group).
  Action take_sulphur(actor: group, site: place) "Take the sulphur candles from under Mrs Pyecroft's bed" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hatbox) and pyeHasSulphur(pye) and not candlesGone(pye) and not smokingOver(hollins) and not perceives(pye, actor).
    On success { Assert candlesGone(pye). Give pye_sulphur to actor. }
    Result "They are heavier than they look, and smell of matches. You go out with them under your coat and down the ribbon, and nobody sees.".
  }
  Item pye_sulphur "Mrs Pyecroft's sulphur candles" is sulphur_kind at nowhere.
  Rule sulphur_shows when pyeHasSulphur(pye) and at(party, hatbox) and not knows(party, smoking_planned) says "Somebody has written on the brown paper, in the pinched hand of the notice on the Mat's door: FOR THE NIGHT. ALL DOORS SHUT. HALL, DRAWING ROOM, KITCHEN." teaches smoking_planned { }
}

data/adventures/hollins/bootscrape.kyr:
Module hollins "Behind the Wainscot" {
  // ── Bootscrape ────────────────────────────────────────────────────────────────────────────────────────────────────
  // A village of salvagers and carters built under the iron boot-scraper on the doorstep of Hollins. It lives by what
  // comes out of the letterbox: a pin is a spear-shaft of good steel, a button a millstone of horn, a dropped nail a
  // bar of iron. It knows where these things come from, and has never said so to anyone from outside.
  Place mat_inn "the Mat" is building within bootscrape.
  Place arkle_house "Widow Arkle's chandlery" is building within bootscrape.
  Place saltash_house "Mr Salcombe's office" is building within bootscrape.

  Place march_road "the moor road above Bootscrape" is room within bootscrape at 0, 0.
  Place bs_street "Bootscrape street" is room within bootscrape at 1, 0.
  Place mat_tap "the Mat's taproom" is room within mat_inn at 1, 1.
  Place tallis_yard "Ludd's yard, under the scraper" is room within bootscrape at 2, 0.
  Place arkle_shop "Widow Arkle's chandlery" is room within arkle_house at 0, 1.
  Place saltash_office "Mr Salcombe's office" is room within saltash_house at 2, 1.
  Place waiting_stone "the Waiting Stone" is room within moor at 0, 0.
  Place nowhere "nowhere" is room within moor at 9, 9.

  Passage moor_way "the moor road" is road between march_road and bs_street taking 10 minutes.
  Passage mat_door "the Mat's door" is door between bs_street and mat_tap.
  Passage yard_way "under the scraper" is arch between bs_street and tallis_yard.
  Passage arkle_door "the chandlery door" is door between bs_street and arkle_shop.
  Passage saltash_door "Mr Salcombe's door" is door between bs_street and saltash_office.
  Passage stone_path "the path up onto the moor" is path between march_road and waiting_stone taking 1 hour.

  Observe march_scene at march_road when true "The moor road comes over the last of the heather and there it is, and for a moment you take it for a hill: a grey slope of stone with a roof on it, going up and up, and windows in it, each window as tall as a church. Smoke goes up from one chimney, thick and new. Below it, at its foot, a village of thirty roofs crowds against something you cannot at first make sense of, a long dark ledge of dressed stone as high as a house, which is a doorstep.".
  Observe march_smoke at march_road as feature when not ladyDead(lady) "The smoke from the chimney leans east in the wind. A carter going by on the road stops his horse to look at it, the way people look at a thing they were told about as children.".
  Observe street_notice_first at bs_street when not dark() and not hiredBy(party, pye) and dayN(hollins) <= 3 "On the door of the inn, the Mat, a notice in a clear, pinched hand: WANTED, A RATCATCHER, FOR HOLLINS, TWO CROWNS THE DAY, APPLY WITHIN, TEN UNTIL TWO. Under that: THE HOUSE BEING OVERRUN; TWOPENCE THE TAIL. D. PYECROFT. Somebody has drawn a very small face in the corner of it, with its finger to its lips.".
  Observe street_scene at bs_street as feature when not dark() "Bootscrape street runs along the foot of the doorstep, under the scraper: an iron arch thirty feet high, rusted to the colour of a fox, with a forge built into one leg of it and washing hung from the crossbar. The houses are built of the ordinary stone of the hills, and roofed, a good many of them, with things that are not slates: a sheet of blackened brass, half a horn button the size of a millwheel, a shard of green glass that throws a green light into somebody's kitchen. A rope ladder hangs down the face of the step to the lip, sixty feet up, where the brass of the letterbox shines.".
  Observe street_night at bs_street when dark() "Bootscrape at night: the forge glowing in the scraper's leg, a lamp in the Mat's window, and high over everything a lit window in the house, as tall as a church, and a shadow crossing it slowly, the size of a cloud.".
  Observe street_plain at bs_street when not dark() and (hiredBy(party, pye) or dayN(hollins) > 3) "Bootscrape street runs along the foot of the giant's doorstep, under the iron arch of the scraper, with the rope ladder hanging down the face of the step to the brass of the letterbox sixty feet up.".

  // ── The Mat ───────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe mat_scene at mat_tap when true "The Mat is called after the thing it stands on, or stood on once: its floor is an edge of the giant's doormat, coir as thick as a man's wrist, grown over with moss and beaten flat by three centuries of boots. A fire, settles, the smell of beer and wet dog. Over the fireplace, framed, hangs a giant's playing card, the six of cups, as big as a door.".
  Observe mat_pye at mat_tap as sign when at(pye, mat_tap) and interviewing() "At the corner table, with her back to the wall and a ledger open in front of her, sits a small upright woman in black with a pen behind her ear. A little line of men waits on the settle with sacks and terriers: ratcatchers, come down off the moor for two crowns a day. None of them looks as if he means to take it.".
  Person jory "Jory Mudge" at mat_tap {
    Role "who keeps the Mat". Profession innkeeper. Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Likeness "innkeeper".
    Greets "A big soft man with flour on his forearms looks up from the bread. 'Come in off the moor. You'll have seen it, then,' he says, and nods at the wall, meaning what is beyond it. 'Everybody stops on the road the first time. Sit down. Ale's a penny and the bread's my own.'".
    Greets again "'Back again,' says Jory Mudge, and looks at your boots, which is where Bootscrape looks first: for the white dust of the house.".
    Sells rations for 2 coin from 10.
    Sells torch for 1 coin from 6.
  }
  Topic jory_house with jory "Ask Jory Mudge about the house" when true once {
    Says "'Hollins,' says Jory. 'The Whitbreads built it. Tall folk, giant gentry, the last of them west of the march, and the last of the last went away when my great-great-grandad's grandad was a boy, and it's stood shut since.' He wipes his hands. 'We live off its doorstep. Off what falls out of it, you might say.' He does not say how a shut house lets things fall out of it. 'And now she's come home. Miss Whitbread. Four days back, in a wagon you could have put this inn in, with a cat on the seat beside her the size of a bull. Walked up the step, put a key the length of my arm in the door, and went in. The chimney's smoked since.' He looks at the wall again. 'First smoke in three hundred years. You'd think we'd be glad.'".
    On discuss { Assert knows(actor, lady_home). }
  }
  Discovery lady_home "Miss Whitbread, the last of the giant Whitbreads of Hollins, came home four days before you did, after three hundred years, with a cat the size of a bull. The house is twelve times the size of a house.".
  Topic jory_glad with jory "Ask Jory Mudge why Bootscrape is not glad" when knows(actor, lady_home) once {
    Says "Jory Mudge wipes his hands on his apron, twice, and leans on the bread. 'You're going in,' he says. 'Everybody who stops on the road goes in, sooner or later. So I'll tell you what we tell nobody, and you'll keep it like we keep it.' He lowers his voice, though there is nobody near. 'There's folk in there. Our size. Living in it. Six hundred, they say. In the walls, and the grate, and the doll's house in the nursery. Came in by the letterbox, starving, three hundred years of them. We trade with them, out of the Slot: their pins and buttons for our bread and needles.' He straightens up. 'And now she's home, and she's lit the fire, and her woman wants a ratcatcher.'".
    On discuss { Assert knows(actor, wainscot_told). }
  }
  Discovery wainscot_told "There are people of our own size living inside Hollins, some six hundred, in the walls, the cold grate and the doll's house: three hundred years of the hungry and the hunted, who came in by the letterbox. Bootscrape trades with them through the Slot, and tells nobody.".
  Topic jory_pye with jory "Ask Jory Mudge about Mrs Pyecroft" when true once {
    Says "'Her companion,' says Jory. 'Our size, mark you. Rides about in the Lady's pocket and does her letters for her, the Lady's eyes being gone. Comes down the ladder of a morning like any of us.' He considers. 'Sharp. Not unkind, exactly. She's seen droppings and gnawed candle-ends and a doll's bed slept in, and she says rats, and she's right in the way that people are right who've never been poor.' He shrugs. 'Eight men have sat on that settle since yesterday and not one's taken it. They know what's in there. She doesn't.'".
    On discuss { Assert knows(actor, pye_heard). }
  }
  Discovery pye_heard "Mrs Pyecroft, the Lady's companion, is of our size, writes the Lady's letters, and believes the house is overrun with rats. She is hiring a ratcatcher at the Mat.".
  Topic jory_stone with jory "Ask Jory Mudge about the stone on the moor" when true once {
    Says "'The Waiting Stone,' says Jory. 'Up on the moor, an hour's walk. Stands on its own. Looks like a man sitting with his elbows on his knees, if you squint, and at dusk, if you're daft, it's got a face.' He smiles. 'My gran said it was a giant who sat down to wait for somebody and never got up again, and the moss grew on him. Gran said a lot of things.'".
    On discuss { Assert knows(actor, stone_told). }
  }
  Discovery stone_told "On the moor above Bootscrape stands the Waiting Stone, like a man sitting with his elbows on his knees. Bootscrape grandmothers say it is a giant who sat down to wait for somebody and never got up.".
  Topic jory_shelter with jory "Ask Jory Mudge whether Bootscrape would take them in, if they had to come out" when knows(actor, wainscot_told) once {
    Says "Jory puts the bread down. He looks at the door, and the wall, and the door. 'Come out,' he says. 'Down the ladder. Six hundred.' He counts something on his floury fingers and gives it up. 'Three hundred years we've bought their pins and sold them bread and never once asked them in to sit down.' Then: 'There's lofts in Bootscrape, and barns, and the Mat's got a cellar. We'd manage. We'd have to.' He picks the bread back up, and his hands are not steady. 'Tell them that. From Jory Mudge. If it comes to it, we'd take them in.'".
    On discuss { Assert knows(actor, bootscrape_shelter). }
  }
  Discovery bootscrape_shelter "Jory Mudge says Bootscrape will take the people of the Wainscot in, in its lofts and barns and the Mat's cellar, if they come down the ladder.".

  // ── Mrs Pyecroft's interviews ──────────────────────────────────────────────────────────────────────────────────────────
  Topic pye_position with pye "Ask Mrs Pyecroft about the position" when interviewing() and at(pye, mat_tap) once {
    Says "Mrs Pyecroft looks you over, all of you, boots to hat, as if she were pricing you. 'Hollins is infested,' she says. 'I have found droppings on the stair, candle-ends gnawed, and in the nursery a doll's bed that has been slept in, which, if you have ever kept house, you will know means rats, and bold ones.' She taps the ledger. 'Two crowns a day, and found, and twopence a tail, which I shall count. I want the pantry cleared and the skirtings, and I want to know where they nest. Miss Whitbread is not well. She hears them in the walls at night, and she thinks,' and here Mrs Pyecroft stops, and goes on in a different voice, 'she thinks it is her mind. It is not her mind. It is rats. I want it to be rats.'".
    On discuss { Assert knows(actor, position_heard). }
  }
  Discovery position_heard "Mrs Pyecroft will pay a ratcatcher two crowns a day and twopence a tail to clear the pantry and the skirtings of Hollins, and more to know where the vermin nest. The Lady hears them in the walls at night, and is afraid it is her mind.".
  Topic pye_hire with pye "Take Mrs Pyecroft's position as ratcatcher of Hollins" when interviewing() and at(pye, mat_tap) and knows(actor, position_heard) once {
    Says "'Good,' says Mrs Pyecroft, and writes your name in the ledger, spelt as she hears it. She pushes a canvas bag across the table: two spring-traps, a tin of paste, a pair of gauntlets. 'The traps go where they run. The paste goes on bread. Don't eat the bread.' She counts four coins onto the table. 'Two days in hand. I shall want tails, and I shall want the nest.' She closes the ledger. 'You come in by the Slot, like everybody. I'll tell the Lady there's a ratcatcher in the house, so she does not tread on you.'".
    On discuss { Assert hiredBy(actor, pye). Increase quantity(actor, gold) by 4. Give rat_traps to actor. Give arsenic to actor. }
  }
  Kind trap_kind "a pair of spring-traps" is gear worth 1 weighing 2 described "Two iron spring-traps with toothed jaws, rat-sized, which is to say big enough to break a man's hand. Mrs Pyecroft's, out of a carton from a town ironmonger.".
  Kind arsenic_kind "a tin of arsenic paste" is gear worth 1 weighing 0 described "A flat tin of grey paste that smells of almonds and lard, with a skull scratched on the lid by somebody conscientious.".
  Item rat_traps "a pair of spring-traps" is trap_kind at nowhere.
  Item arsenic "a tin of arsenic paste" is arsenic_kind at nowhere.
  Kind tail_kind "a string of rat-tails" is gear worth 1 weighing 0 described "A dozen rat-tails threaded on a string by their roots, like a bunch of grey dried grass.".
  Topic pye_tails_how with pye "Ask Mrs Pyecroft how she pays for tails" when hiredBy(actor, pye) once {
    Says "'Twopence a tail, by the dozen, on the string,' says Mrs Pyecroft. 'Three coin a string. I have been cheated in four counties, so I shall count them.'".
  }

  // ── Hob Ludd, salvager ──────────────────────────────────────────────────────────────────────────────────────────
  Observe yard_scene at tallis_yard when true "Under the leg of the scraper, where the iron goes into the ground, a salvager's yard: a steel pin as long as a pike leaning on a rack with a dozen more, a horn button as wide as a cart wheel being sawn into combs, a copper rivet in a vice, and in a barrel by the gate, standing upright like arrows in a quiver, a great many rat-tails on strings.".
  Person hob "Hob Ludd" at tallis_yard {
    Role "salvager under the scraper". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Likeness "merchant".
    Greets "A wiry man with a jeweller's glass screwed into one eye is filing a pin. 'Buying or selling? Or neither, which is the commonest,' he says, without looking up. 'Everything in this yard came out of the Slot, honest, for good bread and better needles.'".
    Greets again "Hob Ludd takes his glass out, which he only does for people he expects to make money from.".
    Sells tail_kind for 1 coin from 6.
    Sells rope for 2 coin from 4.
    Sells pin_spear_kind for 3 coin from 2.
  }
  Kind pin_spear_kind "a giant's pin, for a spear" like spear described "A steel dressmaker's pin out of Hollins, filed to a new point and bound with leather at the head end for a grip: eight feet of the best steel in the hills.".
  Topic hob_tails with hob "Ask Hob Ludd about the rat-tails in the barrel" when true once {
    Says "Hob grins. 'Every ratcatcher that ever came to Bootscrape has been paid by the tail,' he says, 'and every one of them came to me for tails, because the rats in there are the Jarmen's, and the Jarmen take a dim view.' He pulls a string out of the barrel and shakes it. 'Some of these I've sold six times. One coin the string. Your Mrs Pyecroft pays three. It's not dishonest. It's tradition.'".
    On discuss { Assert knows(actor, tails_trade). }
  }
  Discovery tails_trade "Hob Ludd sells old rat-tails by the string, one coin each, to every ratcatcher paid by the tail; some strings have been sold six times.".
  Topic hob_ways with hob "Ask Hob Ludd how to get into the house" when true once {
    Says "'By the Slot, like an honest body,' says Hob. 'Up the ladder, through the letterbox, and the Post'll have you down the other side. The ladder's mine and it's a penny.' He considers you. 'Or round the north side to the kitchen garden, and down the coal-hole, if you don't want the Post to know you've come. It comes out in the cellars, in the dark.' He goes back to his pin. 'I wouldn't, myself. There's people in the cellars that don't come up.'".
    On discuss { Assert knows(actor, coal_hole_known). }
  }
  Discovery coal_hole_known "Round the north side of Hollins, in the kitchen garden, the old coal-hole goes down into the cellars: a way in that the Post does not see.".
  Topic hob_sovereign with hob "Ask Hob Ludd what he would buy, if he could get it" when true once {
    Says "Hob takes the glass out of his eye. 'A Whitbread sovereign,' he says. 'Out of her purse. Gold, a foot across, with old Lord Whitbread on it. There's not been one through the Slot in three hundred years; she took them all with her.' He wets his lips. 'She'll have a purse on her dressing table, or by the bed. Old women do. Bring me one and I'll give you thirty coin and not ask how.' He puts the glass back. 'She'd never miss one. She can't see.'".
    On discuss { Assert knows(actor, sovereign_wanted). }
  }
  Discovery sovereign_wanted "Hob Ludd will give thirty coin for one gold Whitbread sovereign out of the Lady's purse, which he supposes lies on her bedside table.".
  Kind sovereign_kind "a Whitbread sovereign" is treasure worth 30 weighing 6 described "A gold coin a foot across and as thick as a finger, with a bearded giant in profile on one face and on the other a tower on a hill and the words HOLLINS · WHITBREAD. It is the heaviest single thing you have ever picked up that was not a stone.".
  Item sovereign "a Whitbread sovereign" is sovereign_kind in lady_purse.
  Action sell_sovereign(actor: group, site: place) "Sell Hob Ludd the Whitbread sovereign" {
    Requires able(actor) and company(actor) and at(actor, site) and at(hob, site) and carries(actor, sovereign).
    On success { Spend sovereign from actor. Increase quantity(actor, gold) by 30. Assert sovereignSold(party). }
    Result "Hob weighs it on both hands, and bites the rim, and then just looks at it, for longer than a man looks at money. 'Thirty,' he says at last, and counts it out, and puts the sovereign under a sack without letting go of it until the sack is over it.".
  }
  Relation sovereignSold(group).

  // ── Widow Arkle, chandler ─────────────────────────────────────────────────────────────────────────────────────────
  Observe arkle_scene at arkle_shop when true "A chandler's: candles in bunches, rope, lamp oil, tallow in crocks, and along the top shelf, behind glass, a row of fat yellow candles with a skull stamped on each, for fumigating cellars. A giant's thimble, upturned, serves as the counter, and the widow keeps her change in a dent in it.".
  Person arkle "Widow Arkle" at arkle_shop {
    Role "the chandler of Bootscrape". Ancestry dwarf. Peaceable. Pronouns she. Manner stoic.
    Likeness "merchant".
    Greets "A broad grey dwarf-woman behind the thimble looks up. 'Candles, rope, oil, tallow,' she says. 'And if you're here for the yellow ones, I'll want to know what for.'".
    Greets again "Widow Arkle nods to you over the thimble.".
    Sells candle for 1 coin from 12.
    Sells lamp_oil for 1 coin from 6.
    Sells lantern for 3 coin from 2.
    Sells rope for 2 coin from 4.
  }
  Kind sulphur_kind "the sulphur candles" is gear worth 2 weighing 1 described "Three fat candles of yellow sulphur, stamped with a skull, for smoking out a cellar. Lit in a shut house the smoke goes down, not up, and fills whatever is low.".
  Item sulphur_stock "the sulphur candles" is sulphur_kind at nowhere.
  Relation sulphurBought(group). Relation arkleRefuses(group).
  Topic arkle_yellow with arkle "Ask Widow Arkle about the yellow candles" when true once {
    Says "'Sulphur,' says the widow. 'For smoking a cellar of rats, or a granary of weevils. Light them, shut the doors, and in a night there's nothing left alive under the height of your knee.' She looks at the shelf. 'I've three. Nobody's bought one in years. Six coin the three.'".
    On discuss { Assert knows(actor, sulphur_seen). }
  }
  Discovery sulphur_seen "Widow Arkle in Bootscrape keeps three sulphur candles for smoking out cellars: lit in a shut house, they kill everything low.".
  Action buy_sulphur(actor: group, site: place) "Buy Widow Arkle's three sulphur candles, for six coin" {
    Requires able(actor) and company(actor) and at(actor, site) and at(arkle, site) and knows(actor, sulphur_seen) and not sulphurBought(party) and not pyeOrdered(pye) and quantity(actor, gold) >= 6.
    On success { Decrease quantity(actor, gold) by 6. Increase quantity(arkle, gold) by 6. Assert sulphurBought(party). Give sulphur_stock to actor. }
    Result "The widow reaches them down and wraps them in brown paper without a word, and looks at you while she ties the string. 'Whatever you mean to smoke,' she says, 'mind you're not under the smoke.'".
  }
  Topic arkle_warned with arkle "Tell Widow Arkle what Mrs Pyecroft will want the yellow candles for" when knows(actor, sulphur_seen) and knows(actor, wainscot_told) and not pyeOrdered(pye) and not sulphurBought(party) once {
    Says "The widow's face shuts like a box. 'In there,' she says. 'In the walls.' She takes the three candles down off the shelf and puts them under the counter, behind the thimble, where nobody could see them. 'Then I've none. Sold out. Years ago.' She looks at you. 'She'll send to Wendle for them, mind. The carrier goes Tuesdays. It'll not stop her; it'll slow her.'".
    On discuss { Assert arkleRefuses(arkle). }
  }

  // ── Mr Salcombe, notary and carrier ────────────────────────────────────────────────────────────────────────────────
  Observe saltash_scene at saltash_office when true "A narrow office with a high desk, a strongbox, pigeonholes full of folded paper, and a sign in the window: SALTASH. CONVEYANCES, WILLS, LETTERS CARRIED TO WENDLE AND THE COUNTY. On the wall, as a curiosity, a giant's envelope, unopened, the size of a bedsheet, addressed to somebody three hundred years dead.".
  Person saltash "Mr Salcombe" at saltash_office {
    Role "the notary and carrier of Bootscrape". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Likeness "scholar".
    Greets "A thin man in black sleeves rises from the high desk. 'Salcombe. Conveyances, wills, letters. Sit, if it is business; stand, if it is gossip, and be brief.'".
    Greets again "Mr Salcombe takes his pen from behind his ear, which is his greeting.".
  }
  Topic saltash_will with saltash "Ask Mr Salcombe what a giant's will would need, to stand" when true once {
    Says "Mr Salcombe puts his fingertips together. 'A will is a will,' he says. 'Her hand, or a hand she owns as hers, two witnesses who are not to inherit, and lodged with a notary, which is to say with me, in that box.' He considers the wall, and what is beyond it. 'And if she meant to leave the house to anyone, the deed should lie with it, or the Hollins Stone Concern will say she had no house to leave. They have been writing to Mrs Pyecroft.' He says the name with care. 'I should come myself, to witness. I have always wanted to see the inside.'".
    On discuss { Assert knows(actor, will_needs). }
  }
  Discovery will_needs "Mr Salcombe says a will must be in the Lady's hand or one she owns, witnessed by two who do not inherit, and lodged with him; and the house's deed should lie with it, or the Hollins Stone Concern will dispute it. He would come into the house to witness it.".
  Topic saltash_concern with saltash "Ask Mr Salcombe about the Hollins Stone Concern" when true once {
    Says "'A Wendle company,' says Salcombe. 'Quarrymen. They would take a giant's house down for its stone and sell it by the cartload; there's dressed granite enough in Hollins to build a town.' He opens a pigeonhole, then shuts it again, as if he had remembered something about confidences. 'Their surveyor, a Mr Overy, has taken a room at the Mat from the fifth. I gather Mrs Pyecroft holds the Lady's affairs. I gather there is a paper. I gather nothing else.'".
    On discuss { Assert knows(actor, concern_heard). }
  }
  Discovery concern_heard "The Hollins Stone Concern of Wendle would take the house down for its stone. Its surveyor, Mr Overy, comes to the Mat on the fifth day; Mrs Pyecroft holds the Lady's affairs, and there is a paper.".

  // ── The Waiting Stone ─────────────────────────────────────────────────────────────────────────────────────────────
  Observe stone_scene at waiting_stone when true "On the top of the moor, alone in the heather, a grey stone the height of a church tower, leaning forward a little, with two great humps at its base like knees. Lichen grows on it in rings. From here you can see the whole of Hollins below, roof and chimneys and windows, and its doorstep, and the village like crumbs along it.".
  Observe stone_dusk at waiting_stone as feature when hour(clock) >= 18 and hour(clock) < 21 "In the low light the lichen and the cracks on the stone's upper face make, if you let them, a face: a long nose, a mouth, two hollows that look down the moor at the house, and have looked down at it, it seems, for a very long time.".
  Observe stone_reply at waiting_stone as feature when replyLaid(party) "In the heather at the stone's foot, weighted with a flint, a sheet of paper the size of a sail, folded and folded again, addressed in an enormous careful hand.".
  Observe stone_turned at waiting_stone as feature when replyLaid(party) and stoneTurned(party) "The paper is gone from the heather. The stone is as it was, of course. Only the lichen on the side toward the house is broken in a long fresh line, as if the stone had moved, a little, to see better; and on the turf at its foot, where the flint was, the flint is lying on a single dried flower.".
}

data/adventures/hollins/cellar.kyr:
Module hollins "Behind the Wainscot" {
  // ── The cellars ───────────────────────────────────────────────────────────────────────────────────────────────────
  // Down the cellar steps from the kitchen, or down the coal-hole from the garden: the coal cellar; the wine-bins,
  // where the Under-folk live; the cistern; and across the cistern, the vault of the Whitbreads. No light comes here.
  Place coal_store "the coal cellar" is room within cellars at 0, 0 underground.
  Place cellar_foot "the foot of the cellar steps" is room within cellars at 1, 0 underground.
  Place wine_bins "the wine-bins" is room within cellars at 1, 1 underground.
  Place cistern "the edge of the cistern" is room within cellars at 2, 1 underground.
  Place vault "the Whitbread vault" is room within cellars at 3, 1 underground.

  Passage cellar_steps "the cellar steps" is stair between kitchen_floor and cellar_foot taking 20 minutes.
  Passage coal_hole "the coal-hole" is shaft between kitchen_garden and coal_store taking 10 minutes hidden until coal_hole_known.
  Passage coal_door "the coal-cellar arch" is arch between coal_store and cellar_foot.
  Passage bins_way "the way between the bins" is passage between cellar_foot and wine_bins taking 10 minutes.
  Passage cistern_way "the way down to the cistern" is passage between wine_bins and cistern taking 10 minutes.
  Passage vault_way "the vault steps, across the water" is passage between cistern and vault taking 10 minutes
    opening when annetHelps(annet) or eelGone(eel) "The way to the vault is across the cistern: forty yards of black water with something in it, and the steps on the far side going up to an iron door.".

  Observe garden_scene at kitchen_garden when not dark() "The kitchen garden of Hollins, gone wild in three hundred years: a forest of giant rhubarb with leaves like sails, artichokes as tall as trees going to seed in purple thistles, and everywhere, in drifts as high as your shoulder, grey-green catmint, humming with bees. Against the house wall, an iron grating the breadth of a barn door lies half open on its hinge over a black hole that breathes cold.".
  Observe garden_night at kitchen_garden when dark() "The kitchen garden at night: the shapes of rhubarb like ships, the smell of catmint, the black hole of the coal-hole under the house wall.".
  Observe garden_grating at kitchen_garden as feature when knows(party, mother_letter) "The grating over the coal-hole stands open on its hinge, as it has, you know now, for three hundred winters, because somebody wanted it so.".
  Relation catmintCarried(group).
  Kind catmint_kind "an armful of catmint" is gear worth 0 weighing 1 described "An armful of grey-green catmint out of the kitchen garden, bruised, smelling sharp and minty; to a cat, irresistible.".
  Item catmint "an armful of catmint" is catmint_kind at nowhere.
  Action gather_catmint(actor: group, site: place) "Gather an armful of catmint" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, kitchen_garden) and not carries(actor, catmint).
    On success { Give catmint to actor. }
    Result "You pull an armful of it, and the bees go up round you in a cloud and come down again. Your hands smell of it for an hour.".
  }

  Observe coal_scene at coal_store when true "The coal cellar: a heap of coal like a black hill under the hole in the roof, with grey light falling on it from above, and footprints across the dust where a good many people, over three centuries, have come down the heap and gone on through the arch.".
  Observe cfoot_scene at cellar_foot when true "At the foot of the cellar steps, which are each a fall of eight feet with a ladder lashed to it, the dark opens out under vaults of brick. It is cold, and still, and smells of earth and old wine. Somewhere water drips into water, and every few seconds someone in the brick says, quite close to your ear, 'Hush.'".
  Observe bins_scene at wine_bins when true "The wine-bins: brick cells in rows, each as big as a chapel, each racked with bottles lying on their sides like great green cannons. In the cells people are living, in the dark, among pale mushrooms grown on the straw. Nobody carries a light. Voices come from everywhere, quiet.".
  Observe cistern_scene at cistern when true "The cistern is a black lake under a brick vault, and the drip from somewhere high falls into it with a sound that goes on and on round the walls. A ledge a hand wide runs along the wall to the left. On the far side, forty yards off, steps go up out of the water to an iron door with a lock in it you could stand inside.".
  Observe cistern_eel at cistern as sign when not eelGone(eel) and not annetHelps(annet) "Out in the middle of the cistern something moves under the water, long and slow, and a ring spreads across the black and laps at your feet.".
  Observe vault_scene at vault when true "The vault of the Whitbreads: a long brick room with shelves cut into the walls, and on the shelves the coffins of the tall family, oak, each as long as a barge, with brass plates the size of doors. LADY AGATHE WHITBREAD. SIR AMBROSE WHITBREAD. And smaller, a child's length, which is still twice yours: EDMUND, AGED FOUR. At the end, under the last shelf, an iron strongbox the size of a cottage, with a keyhole in its front like an arched door.".

  // ── The Under-folk ────────────────────────────────────────────────────────────────────────────────────────────────
  // A hundred years ago the Court sent down the Candle Rioters, who had stormed the Small House over a tax on light,
  // and they stayed down: their children have never seen a candle. They came in, in the first place, by the coal-hole,
  // not by the Slot, and so the Post has never entered them, and the Tapwarden has never given them a thimble; they
  // drink what drips in the cistern. Blind Annet is their eldest.
  Person annet "Blind Annet" at wine_bins {
    Role "the eldest of the Under-folk". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Likeness "elder".
    Greets "A voice out of the dark, old and dry, very close: 'You've a light. Put it down; it hurts the children.' A hand finds your sleeve, light as a moth. 'I'm Annet. They call me Blind, which is a joke, since there's nothing down here to see. What brings an upstairs body to the bins?'".
    Greets again "'The upstairs one,' says Annet's voice, out of the dark, pleased.".
  }
  Topic annet_folk with annet "Ask Blind Annet who the Under-folk are" when true once {
    Says "'The Candle Riot,' says Annet. 'A hundred years. The Court put a tax on candle-ends, and my grandmother's people went up the Stair and broke the Small House windows, and the Court sent them down here, and said stay.' She laughs. 'We stayed. We like it. It's quiet.' Then, not laughing: 'But we came into Hollins by the coal-hole, my grandmother's grandmother, in the Hungry Winter of Forty. The grating was open. So the Post never wrote us down. So we're not in the book. So Drewe gives us no water, and we drink the cistern, and the children are sick of it every summer.' Her hand tightens on your sleeve. 'Six hundred in the house, they say. They don't count us. Forty-one. We're not anybody.'".
    On discuss { Assert knows(actor, underfolk_uncounted). }
  }
  Discovery underfolk_uncounted "The Under-folk of the cellars, forty-one of them, came into Hollins by the open coal-hole and not by the Slot, so the Post has never entered them, and the Tapwarden gives them no water; they drink the cistern and their children sicken.".
  Relation underfolkEntered(group). Relation annetHelps(group).
  Topic faith_underfolk with faith "Ask Faith Penny to enter the Under-folk in the register" when knows(actor, underfolk_uncounted) and not underfolkEntered(annet) once {
    Says "Faith Penny's pen stops. 'They came in by the coal-hole,' she says. 'The register is of all who come in by the Slot.' She looks at the register, at its two hundred and ninety years. Then she turns to the first page, the very first, where in a faded hand it says what the Post is for, and reads it under her breath, and stops. 'All who come in,' she says. 'It says all who come in. It doesn't say by the Slot.' She sits very still. 'Ninety years we've been saying by the Slot, and it doesn't say it.' She dips the pen. 'Forty-one, you said. Give me the names, if she'll give them.' And then, fiercely, to the register: 'The Post is not a gate.'".
    On discuss { Assert underfolkEntered(annet). }
  }
  Topic annet_entered with annet "Tell Blind Annet the Post will enter her people" when underfolkEntered(annet) and not annetHelps(annet) once {
    Says "Annet is quiet for so long you think she has gone. Then her voice, near and changed: 'In the book. With names.' Somewhere in the dark a child asks what is happening and is hushed. 'Then Drewe owes us forty-one thimbles a day, and she'll pay them, because Drewe's fair, whatever else.' Her hand finds yours. 'You wanted the vault. Everybody upstairs wants the vault this week; her woman's been down the steps twice with a lantern, poking. There's a raft. We use it at the Old One's sleeping time, which is now, near enough. I'll take you over myself.'".
    On discuss { Assert annetHelps(annet). Assert knows(actor, pye_hunts_deed). }
  }
  Discovery pye_hunts_deed "Mrs Pyecroft has been down the cellar steps twice with a lantern, hunting for the vault.".
  Topic annet_old with annet "Ask Blind Annet about the Old One in the cistern" when true once {
    Says "'An eel,' says Annet. 'Came up the drain when it was a bootlace, and found the cistern, and never found the way back. That was before my grandmother.' She considers. 'As long as a ladder now, and white, and blind as me. It sleeps in the day and hunts at night, by the feel of the water. Anyone who goes in the water, it knows. There's a ledge along the left wall, a hand wide, if you're a fly.'".
    On discuss { Assert knows(actor, eel_told). }
  }
  Discovery eel_told "A blind white eel as long as a ladder, the Old One, lives in the cistern and hunts whatever goes into the water; a ledge a hand wide runs along the left wall.".

  // ── The Old One ───────────────────────────────────────────────────────────────────────────────────────────────────
  Species old_one_kind "the Old One" like great_pike temperament ambush described "A blind eel as long as a ladder, white as a peeled stick, that came up the drain as a bootlace a hundred years ago and has lived on whatever falls into the cistern since.".
  Person eel "the Old One" at cistern {
    Role "a blind white eel as long as a ladder". Species old_one_kind. Level 3.
    Lair cistern.
  }
  Relation eelGone(group).
  Rule eel_down when (dead(eel) or routed(eel)) and not eelGone(eel) { Assert eelGone(eel). }
  Rule eel_quiet when annetHelps(annet) and not tolerates(eel, party) { Assert tolerates(eel, party). }
  Relation ledgeFell(group).
  Action edge_ledge(actor: group, site: place) "Edge along the cistern ledge to the vault steps" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, cistern) and not eelGone(eel) and not annetHelps(annet) and not ledgeFell(party).
    Time 2.
    Resolve check(actor, climbing, dc_fair).
    On success { Assert at(actor, vault). }
    On failure { Assert ledgeFell(party). Assert assails(eel, actor). }
    Result "Forty yards, face to the brick, heels over the water, fingers in the mortar. Halfway along, something passes under you in the black with a long slow swirl, and goes on. You come to the steps and climb them on your hands and knees.".
    Otherwise "Twenty yards along, the ledge crumbles under your heel and you go in, into water so cold it stops your breath; and before you can get it back, something white comes up out of the dark below you.".
  }

  // ── The vault ─────────────────────────────────────────────────────────────────────────────────────────────────────
  Thing strongbox "the Whitbreads' strongbox" at vault {
    Holds.
    State locked closed "An iron strongbox the size of a cottage, locked. Its keyhole is an arch you could walk into; inside it, in the dark, the wards and tumblers of the lock are iron bars as thick as your arm.".
    State open "The strongbox stands open, its lid propped on its own great hinge. You had to go inside the lock to do it, among iron bars as thick as your arm, and heave, and the whole box rang like a bell when it gave.".
    Change pick "Climb into the lock and lift the tumblers" from locked to open needing lockwork.
    Change heave "Climb into the lock and heave the tumblers up by main strength" from locked to open needing brawn.
    Change lever "Lever the tumblers up with a giant's pin, from inside the lock" from locked to open needing pin_spear_kind.
  }
  Kind deed_kind "the deed of Hollins" is gear worth 0 weighing 4 described "A roll of parchment as thick as a man and as long as two, tied with a ribbon the colour of old blood, sealed with the arms of the Whitbreads: a tower on a hill. Spread out, it would cover a floor. CONVEYANCE OF THE HOUSE AND LANDS OF HOLLINS, in letters you can read from across a room.".
  Item deed "the deed of Hollins" is deed_kind in strongbox.
  Kind mama_letter_kind "Lady Agathe's letter" is gear worth 0 weighing 3 described "A giant's letter, folded, never sealed, the paper as brown as a leaf, and on the outside in a fine tall hand: For Ermengarde. Not to be sent. To be found.".
  Item mama_letter "Lady Agathe's letter" is mama_letter_kind in strongbox.
  Relation deedTaken(group).
  Rule deed_out when carries(party, deed) and not deedTaken(party) { Assert deedTaken(party). }
  Relation motherRead(group).
  Action read_mama(actor: group, site: place) "Unfold Lady Agathe's letter and read it" {
    Requires able(actor) and company(actor) and at(actor, site) and carries(actor, mama_letter) and not motherRead(party).
    Time 2.
    On success { Assert motherRead(party). Assert knows(actor, mother_letter). }
    Result "It takes walking to read, the sheet spread out on the floor, a line at a time: For Ermengarde. My darling. I saw her. The little girl, at the window of your doll's house, on the night before Doctor Hume came; she had a candle-end and she looked straight at me. I told the doctor you were ill because I could not bear to have him say it of me as well, and your father would have let him. I sent you to Sabine to keep you from being looked at. I have been a coward, and I have left the coal-hole grating open every winter since, which is all the courage I have. If they are still here, it is because of the grating. Forgive me. I could not say it. I am writing it so that it is somewhere. Mama.".
  }
  Discovery mother_letter "Lady Agathe Whitbread saw the Lacey child at the doll's house window, and told the doctor her daughter was ill rather than be called ill herself. She sent Ermengarde away to keep her from being looked at, and left the coal-hole grating open every winter after, which is how the Under-folk and others came in. She wrote it, and never sent it.".
}

data/adventures/hollins/clock.kyr:
Module hollins "Behind the Wainscot" {
  Description "Bootscrape, a salvagers' village on a giant's doorstep in the western hills; and Hollins, the house of the last of the tall gentry, shut three hundred years, where six hundred people of our own size live in the walls, the grate, the pantry and the doll's house, and where the giantess has come home to die.".

  // ── The country ───────────────────────────────────────────────────────────────────────────────────────────────────
  // West to east: the moor road comes down off the moor (the Waiting Stone stands up on it) into Bootscrape, a village
  // on the house's doorstep, under its iron boot-scraper. Hollins stands over the village like a hill with windows.
  // Round the north side of the house the lane goes to the kitchen garden and the coal-hole.
  Place hollins_country "the Hollins country" is region.
  Place moor "Scrape Moor" is wilderness within hollins_country at 0, 1.
  Place bootscrape "Bootscrape" is settlement within hollins_country at 1, 1.
  Place grounds "the grounds of Hollins" is wilderness within hollins_country at 2, 0.
  Place hollins "Hollins" is settlement within hollins_country at 2, 1.
  Initially Assert terrain(hollins_country, hills).

  // The house is twelve times the size of a house. Its rooms are countries; the places a company can stand in are
  // the places its people stand in: a ledge, a shelf, the space behind a skirting board.
  Place house "the house" is building within hollins.
  Place cellars "the cellars" is level within house.
  Place ground_floor "the ground floor" is level within house.
  Place first_floor "the first floor" is level within house.

  // ── The days ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // Counted from the company's coming, at each dawn after the first hour it is here: the day it comes is the first.
  // The Lady came home three days before. She dies on the night of the tenth, whatever anyone does.
  Measure dayN(place). Relation dawned(place).
  Initially Set dayN(hollins) to 1.
  Rule dawn_counts when hour(clock) == 6 and not dawned(hollins) and watch(clock) >= 0 { Increase dayN(hollins) by 1. Assert dawned(hollins). }
  Rule dawn_passes when hour(clock) != 6 and dawned(hollins) { Retract dawned(hollins). }
  Query onDay(n: entity) means dayN(hollins) == dayNumber(n).
  Measure dayNumber(entity).
  Query day1() means dayN(hollins) == 1.
  Query day2() means dayN(hollins) == 2.
  Query day3() means dayN(hollins) == 3.
  Query day4() means dayN(hollins) == 4.
  Query day5() means dayN(hollins) == 5.
  Query day6() means dayN(hollins) == 6.
  Query day7() means dayN(hollins) == 7.
  Query day8() means dayN(hollins) == 8.
  Query day9() means dayN(hollins) == 9.
  Query day10() means dayN(hollins) == 10.
  Query night() means hour(clock) >= 21 or hour(clock) < 6.

  // ── The Lady's day ────────────────────────────────────────────────────────────────────────────────────────────────
  // Miss Whitbread keeps a cartographer's hours. She dresses at seven; works at her chart in the Library from nine to
  // noon; lunches in the kitchen; dozes on the drawing-room sofa over the Carpet; takes tea at the drawing-room table
  // at ten past four, which was the hour the carriage left; winds the Long Clock at six; sits by the fire; goes up at
  // nine. From the ninth day she keeps to her bed. Where she is, the floor shakes, and the house goes still.
  Relation bedridden(group). Relation ladyDead(group). Relation poisoned(group).
  Query ladyUp() means not ladyDead(lady) and not bedridden(lady) and not poisoned(lady).
  Rule lady_takes_bed when dayN(hollins) >= 9 and not bedridden(lady) and not ladyDead(lady) { Assert bedridden(lady). }
  Rule lady_poisoned_abed when poisoned(lady) and not ladyDead(lady) and not at(lady, counterpane) { Assert at(lady, counterpane). }
  Rule lady_bedridden_abed when bedridden(lady) and not ladyDead(lady) and not at(lady, counterpane) { Assert at(lady, counterpane). }
  Rule lady_night when ladyUp() and (hour(clock) >= 21 or hour(clock) < 7) and not at(lady, counterpane) { Assert at(lady, counterpane). }
  Rule lady_dresses when ladyUp() and hour(clock) >= 7 and hour(clock) < 9 and not at(lady, bedroom_floor) { Assert at(lady, bedroom_floor). }
  Rule lady_charts when ladyUp() and hour(clock) >= 9 and hour(clock) < 12 and not at(lady, chart_table) { Assert at(lady, chart_table). }
  Rule lady_lunches when ladyUp() and hour(clock) >= 12 and hour(clock) < 13 and not at(lady, kitchen_floor) { Assert at(lady, kitchen_floor). }
  Rule lady_dozes when ladyUp() and (hour(clock) >= 13 and hour(clock) < 16 or hour(clock) >= 17 and hour(clock) < 18 or hour(clock) >= 19 and hour(clock) < 21) and not at(lady, carpet) { Assert at(lady, carpet). }
  Rule lady_tea when ladyUp() and hour(clock) >= 16 and hour(clock) < 17 and not at(lady, tea_table) { Assert at(lady, tea_table). }
  Rule lady_winds when ladyUp() and hour(clock) >= 18 and hour(clock) < 19 and not at(lady, clock_foot) { Assert at(lady, clock_foot). }
  Rule lady_gone when ladyDead(lady) and not at(lady, nowhere) { Assert at(lady, nowhere). }

  // ── Mrs Pyecroft's day ─────────────────────────────────────────────────────────────────────────────────────────────────
  // Mrs Pyecroft is our size. She goes where the Lady goes, in her pocket or on her shoulder, except at seven, when she
  // goes round her traps; on the first two days from ten until two, when she is at the Mat in Bootscrape seeing
  // ratcatchers; on the fourth and seventh afternoons, when she goes down to the village on business; and at night,
  // when she sleeps in her hatbox.
  Relation pyeGone(group). Relation pyeAway(group).
  Query pyeFree() means not pyeGone(pye) and not pyeAway(pye).
  Query interviewing() means (day1() or day2() and not hiredBy(party, pye)) and hour(clock) >= 10 and hour(clock) < 14 and not pyeTurned(pye).
  Query pyeErrand() means (day4() or day7()) and hour(clock) >= 14 and hour(clock) < 17.
  Relation hiredBy(group, group). Relation pyeTurned(group).
  Rule pye_sleeps when pyeFree() and (hour(clock) >= 21 or hour(clock) < 7) and not at(pye, hatbox) { Assert at(pye, hatbox). }
  Rule pye_rounds when pyeFree() and hour(clock) >= 7 and hour(clock) < 8 and not interviewing() and not at(pye, pantry) { Assert at(pye, pantry). }
  Rule pye_interviews when pyeFree() and interviewing() and not at(pye, mat_tap) { Assert at(pye, mat_tap). }
  Rule pye_errand when pyeFree() and pyeErrand() and not at(pye, bs_street) and not interviewing() { Assert at(pye, bs_street). }
  Rule pye_with_lady when pyeFree() and hour(clock) >= 8 and hour(clock) < 21 and not interviewing() and not pyeErrand() and at(lady, ?p) and not at(pye, ?p) and not ladyDead(lady) { Assert at(pye, ?p). }
  Rule pye_mourns when pyeFree() and ladyDead(lady) and not at(pye, hatbox) { Assert at(pye, hatbox). }

  // ── The Bishop's night ────────────────────────────────────────────────────────────────────────────────────────────
  // The Lady's cat sleeps on her counterpane by day and hunts the ground floor by night: the Hall from nine, the
  // Carpet from midnight, the kitchen from three, and goes up to the bed at six. Belled, it can be heard coming.
  Relation catAway(group).
  Query prowling() means (hour(clock) >= 21 or hour(clock) < 6) and not catAway(bishop) and able(bishop).
  Rule cat_sleeps when not prowling() and not catAway(bishop) and not at(bishop, counterpane) { Assert at(bishop, counterpane). Assert peaceable(bishop). Assert asleep(bishop). Assert tolerates(bishop, party). }
  Rule cat_dozes when not prowling() and at(bishop, counterpane) and not asleep(bishop) and not catAway(bishop) { Assert peaceable(bishop). Assert asleep(bishop). Assert tolerates(bishop, party). }
  Rule cat_wakes when prowling() and asleep(bishop) and not belled(bishop) { Retract asleep(bishop). Retract peaceable(bishop). Retract tolerates(bishop, party). }
  Rule cat_wakes_belled when prowling() and asleep(bishop) and belled(bishop) { Retract asleep(bishop). }
  Rule cat_hall when prowling() and hour(clock) >= 21 and not at(bishop, hall_flags) { Assert at(bishop, hall_flags). }
  Rule cat_carpet when prowling() and hour(clock) < 3 and not at(bishop, carpet) { Assert at(bishop, carpet). }
  Rule cat_kitchen when prowling() and hour(clock) >= 3 and hour(clock) < 6 and not at(bishop, kitchen_floor) { Assert at(bishop, kitchen_floor). }
  Rule cat_away_night when catAway(bishop) and not at(bishop, kitchen_garden) { Assert at(bishop, kitchen_garden). Assert peaceable(bishop). Assert tolerates(bishop, party). }
  Rule cat_comes_back when catAway(bishop) and hour(clock) == 6 { Retract catAway(bishop). }
}

data/adventures/hollins/company.kyr:
Module hollins "Behind the Wainscot" {
  Company party "Your company" of 1 to 3 at march_road.
  Initially Set quantity(party, gold) to 12. Initially Set quantity(party, rations) to 2.
}

data/adventures/hollins/drawing.kyr:
Module hollins "Behind the Wainscot" {
  // ── The Drawing Room ──────────────────────────────────────────────────────────────────────────────────────────────
  // The Carpet is a plain between the door and the fire; the colliers' Hearth is in the grate; the Keys live in the
  // piano against the north wall, reached from the top of the skirting by a plank; the tea table stands by the sofa.
  Place carpet "the Carpet" is room within ground_floor at 4, 2.
  Place hearth "the Hearth" is room within ground_floor at 5, 2.
  Place piano_keys "the keyboard of the piano" is room within ground_floor at 4, 3.
  Place tea_table "the tea table" is room within ground_floor at 5, 3.

  Passage drawing_door "the drawing-room door" is passage between hall_flags and carpet taking 10 minutes.
  Passage grate_walk "the wall-way to the grate" is passage between skirting and hearth taking 20 minutes.
  Passage hearth_edge "the fender" is passage between carpet and hearth taking 5 minutes.
  Passage keys_plank "the Keys' plank" is steps between skirting and piano_keys taking 10 minutes.
  Passage piano_leg "the piano leg" is steps between carpet and piano_keys taking 10 minutes.
  Passage table_leg "the table leg" is steps between carpet and tea_table taking 10 minutes.

  Observe carpet_scene at carpet when not dark() "The Carpet: a plain of faded red and blue wool, its pile as high as your knee and worn to the threads along the paths the giants walked, three hundred years ago. Its pattern is a garden of flowers each the size of a field. Far off across it the sofa stands like a cliff, the tea table beside it on four turned legs as tall as trees, and on the north wall a black piano, and in the west wall the great mouth of the fireplace.".
  Observe carpet_night at carpet when dark() "The Carpet at night, a dark field. The only light is the fire, banked red in the great grate, and the shapes of the furniture are hills against it. The wool moves round your legs in the draught, and whispers.".
  Observe carpet_lady at carpet as ambience when at(lady, carpet) "On the sofa above, the Lady sits with a rug over her knees, enormous and quiet, her head nodding; and the floor of the room trembles, very slightly, with her breathing.".
  Observe carpet_cat at carpet as sign when at(bishop, carpet) and prowling() "Out on the Carpet, between you and everything, something long and grey is lying with its paws tucked under, and its eyes, which are the size of cartwheels, are open, and turned your way.".

  // ── The Hearth and the colliers ───────────────────────────────────────────────────────────────────────────────────
  // Colliers from a flooded pit in the hills came in by the Slot ninety years ago and took the cold grate: a town in the
  // ash, its pits sunk in the cinder-heap, its chimneys the flue. The fire is lit at nine on the second morning.
  Relation hearthWarned(place). Relation hearthBurned(place). Relation collierDead(place). Relation refugeesHoused(place).
  Thing fire "the drawing-room fire" on hearth_edge is scenery {
    State laid "In the great grate, on the irons, somebody has laid logs as long as boats crosswise over a bed of kindling, with coal heaped round them: a fire, ready, waiting for a match.".
    State blazing blocking "The fire is roaring in the grate, a wall of flame and heat that comes across the fender like a hand. Nobody goes near it.".
    State banked "The fire is banked under its ash for the night, red at the heart, and the grate ticks as it cools.".
  }
  Hazard scorched "Heat off the fire" means "Deal (2d6) physical damage to ally unless dexterity save against (12).".
  Rule fire_scorches at hearth when at(party, hearth) and state(fire, blazing) says "The heat comes at you like a wall. Your clothes smoke." { Assert strikes(scorched, party). }
  Rule fire_burns when hearthBurned(hollins) and hour(clock) >= 9 and hour(clock) < 22 and not ladyDead(lady) and not state(fire, blazing) { Assert state(fire, blazing). }
  Rule fire_banks when hearthBurned(hollins) and (hour(clock) >= 22 or hour(clock) < 9) and state(fire, blazing) { Assert state(fire, banked). }
  Rule fire_out when ladyDead(lady) and state(fire, blazing) { Assert state(fire, banked). }

  Observe hearth_scene at hearth when not hearthBurned(hollins) "The Hearth: a town in a cold grate, where eighty colliers live in the ash of the Whitbreads' last fire. The ash of the Whitbreads' last fire, three hundred years old, has been dug into streets; the cinders are walls; on the iron fire-dogs, which are as tall as gallows, people have built galleries of slate and hung lanterns. The coal-heap at the back is a hill with pits sunk in it and a windlass over each. Up the black throat of the chimney you can see, far up, a square of sky, and ledges in the soot with doors.".
  Observe hearth_burned at hearth when hearthBurned(hollins) and not state(fire, blazing) "What was the Hearth: a grate full of hot ash with the banked fire in the middle of it, red under grey. The galleries on the fire-dogs have gone. The windlasses have gone. A melted lantern hangs from an iron bar, and on the brick at the back, black on black, somebody has written with a cinder the names of the dead.".
  Observe hearth_burning at hearth when hearthBurned(hollins) and state(fire, blazing) "You cannot stand here: the fire fills the grate like a sunrise, and the air beyond the fender shakes.".
  Observe hearth_names at hearth as feature when collierDead(hollins) and hearthBurned(hollins) and not state(fire, blazing) "Nine names on the brick. The last is BET COLLIER, FOREWOMAN, and under it, smaller: SHE WENT BACK FOR THE PIT BOYS.".

  Person bet "Bet Collier" at hearth {
    Role "the forewoman of the Hearth". Ancestry dwarf. Peaceable. Pronouns she. Manner grim.
    Likeness "miner".
    Greets "A square black-faced dwarf-woman with a lamp on her cap straightens up from a windlass. 'You're not from the grate,' she says. 'You're not from anywhere, by your boots. What do you want in the Hearth?'".
    Greets again "Bet Collier lifts her lamp to see you, and lets it down.".
  }
  Person nan "Nan Collier" at hearth {
    Role "Bet Collier's daughter". Ancestry dwarf. Peaceable. Pronouns she. Manner acerbic.
    Likeness "miner".
    Greets "A young dwarf-woman with soot in her plaits and a pencil behind her ear is sitting on an upturned bucket, writing very small on a scrap of paper on her knee. She hides it when she sees you, badly.".
    Greets again "Nan Collier looks up, and her hand goes, without her meaning it to, to her pocket.".
  }
  Topic bet_hearth with bet "Ask Bet Collier about the Hearth" when not hearthBurned(hollins) once {
    Says "'Ninety years,' says Bet. 'Since my gran's gran came in by the Slot off Holloway pit when it flooded. Forty men drowned and the owners said it was God.' She spits into the ash. 'We dig her coal. Nobody's burned it in three hundred years; it burns lovely. We sell it to the Wainscot for their stoves, a bucket for a button.' She looks round at the galleries. 'Eighty-three of us. It's warm in the grate, warmer than anywhere. It holds the heat of her last fire, my gran said, the last fire her mother lit, the night before the Child went away.'".
  }
  Discovery fire_coming "Logs and coal have been laid in the drawing-room grate, on top of the colliers' Hearth. The Lady will want a fire in the room where she sits.".
  Observe laid_teaches at hearth as feature when state(fire, laid) and not knows(party, fire_coming) "The colliers walk round the laid fire without looking at it, the way you walk round something in a dream." teaches fire_coming.
  Topic pye_fire with pye "Ask Mrs Pyecroft about the drawing-room fire" when hiredBy(actor, pye) and not hearthBurned(hollins) once {
    Says "'I laid it myself last night,' says Mrs Pyecroft. 'She sits in that room, and it is perishing; three hundred years of cold in the walls. I shall light it at nine, when she goes through to the Library.' She looks at you. 'Why?'".
    On discuss { Assert knows(actor, fire_at_nine). }
  }
  Discovery fire_at_nine "Mrs Pyecroft will light the drawing-room fire at nine on the second morning, as the Lady goes through to the Library.".
  Topic warn_bet with bet "Warn Bet Collier that the fire will be lit in the morning" when knows(actor, fire_coming) and not hearthWarned(hollins) and not hearthBurned(hollins) and knows(actor, fire_at_nine) once {
    Says "Bet Collier hears you out with her arms folded. 'At nine,' she says. 'By her woman's own mouth.' She looks at the logs, and then up the black throat of the chimney, which in ninety years she has never once looked up. Then she puts two fingers in her mouth and whistles, and the whole grate goes still. 'Everybody out,' she says, not loud. 'Children first, then the old, then what you can carry. Up the wall-way to the Skirting. Now.' And as the Hearth begins to move round her, she turns back to you: 'If you're wrong, I'll have your hide. If you're right, I owe you eighty-three.'".
    On discuss { Assert hearthWarned(hollins). }
  }
  Action urge_bet(actor: group, site: place) "Urge Bet Collier to take the Hearth out tonight, before they light the fire" {
    Speaker bet.
    Requires able(actor) and company(actor) and at(actor, site) and at(bet, site) and knows(actor, fire_coming) and not knows(actor, fire_at_nine) and not hearthWarned(hollins) and not hearthBurned(hollins) and not urgedBet(party).
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert hearthWarned(hollins). }
    On failure { Assert urgedBet(party). }
    Result "'They laid one the week she came,' says Bet, 'and never lit it.' But she is looking at the logs while she says it, and after a while she says: 'All right. All right. We'll sleep on the Skirting tonight. If nothing comes of it, you can stand the Hearth a barrel.' She whistles, and the grate goes still.".
    Otherwise "'They laid one the week she came, and never lit it,' says Bet Collier. 'We're not moving eighty-three people up a wall for a stranger's nerves.'".
  }
  Relation urgedBet(group). Relation toldBetFires(group).
  Action tell_bet_fires(actor: group, site: place) "Tell Bet Collier the Lady has had a fire lit in her own room every night since she came" {
    Speaker bet.
    Requires able(actor) and company(actor) and at(actor, site) and at(bet, site) and knows(actor, fire_coming) and knows(actor, lady_home) and not hearthWarned(hollins) and not hearthBurned(hollins) and not toldBetFires(party).
    Resolve check(actor, persuasion, dc_easy).
    On success { Assert hearthWarned(hollins). }
    On failure { Assert toldBetFires(party). }
    Result "Bet Collier stops with her hand on the windlass. 'Every night,' she says. 'Her own room.' She looks at the logs on the irons, and up the black throat of the chimney, where the sky is. 'Then she's a woman who likes a fire.' She puts two fingers in her mouth and whistles, and the whole grate goes still. 'We'll sleep on the Skirting tonight,' she says. 'And if I'm a fool, I'm a fool with eighty-three people.'".
    Otherwise "'A bedroom's a bedroom,' says Bet Collier. 'She's not sat in this room once.' She goes back to the windlass.".
  }
  // At nine on the second morning Mrs Pyecroft lights the fire.
  Rule fire_lit when day2() and hour(clock) >= 9 and not hearthBurned(hollins) and not ladyDead(lady) {
    Assert hearthBurned(hollins). Assert state(fire, blazing). Retract at(bet, hearth). Retract at(nan, hearth).
  }
  Rule hearth_evacuated when hearthBurned(hollins) and hearthWarned(hollins) and not at(nan, skirting) and not refugeesHoused(hollins) { Assert at(bet, skirting). Assert at(nan, skirting). }
  Rule hearth_burned_dead when hearthBurned(hollins) and not hearthWarned(hollins) and not collierDead(hollins) { Assert collierDead(hollins). Assert at(bet, nowhere). Assert at(nan, skirting). Assert ladyCursed(hollins). }
  Relation ladyCursed(place).
  Event fire_told within hollins when hearthBurned(hollins) and hearthWarned(hollins) "At nine the whole house hears it: a sound like a sheet of paper torn the length of a street, and then a roar in the chimney that shakes the walls. In the Skirting the colliers stand in the doorways with their bundles, and listen to their town burn, and nobody says anything, and then a child begins to cry because he has left a wooden horse.".
  Event fire_told_dead within hollins when hearthBurned(hollins) and not hearthWarned(hollins) "At nine the whole house hears it: a sound like a sheet of paper torn the length of a street, and then a roar in the chimney that shakes the walls, and under the roar, for a little while, a sound which is not the fire. By ten the colliers who got out are coming along the Skirting black to the eyes, carrying their children, and some of them are carrying other things, wrapped, which they lay down in a row by the gap.".

  // ── Nan, afterwards ───────────────────────────────────────────────────────────────────────────────────────────────
  Topic nan_writing with nan "Ask Nan Collier what she is writing" when not hearthBurned(hollins) and not knows(actor, kit_nan) once {
    Says "Nan puts her hand over the paper. Then, because you are a stranger and will be gone, and because she has wanted to tell somebody for two years: 'A letter. Along the wires.' She points up at the iron wire that runs out of the wall above the grate, as thick as a finger, going away into the dark on a pulley. 'The bell-wires go through every wall in the house. You tie a note on, and pull, and it goes.' She goes red under the soot. 'There's somebody at the other end. Up the Stair. I've never seen him.' She folds the paper very small. 'Don't tell Mam.'".
    On discuss { Assert knows(actor, kit_nan). }
  }
  Topic nan_hearth with nan "Ask Nan Collier about the Hearth" when hearthBurned(hollins) and hearthWarned(hollins) once {
    Says "Nan looks at her hands. 'It burned,' she says. 'Nine o'clock. Like a door opening onto the sun.' Then she looks up, and nearly smiles. 'We got everybody. Mam carried the Lightfoot twins up the wall-way one under each arm. We've nothing, but we've everybody.'".
  }
  Topic nan_hearth_lost with nan "Ask Nan Collier about the Hearth" when hearthBurned(hollins) and collierDead(hollins) once {
    Says "Nan looks at her hands. 'It burned,' she says. 'Nine o'clock. Like a door opening onto the sun.' Then: 'Mam went back for the pit boys. She'd got them as far as the fender.' She turns the pencil over in her fingers, and over. 'They've written her name on the brick. Someone has. I can't go and look.'".
  }
  Topic nan_kit with nan "Ask Nan Collier about Kit Lacey" when knows(actor, kit_nan) and hearthBurned(hollins) once {
    Says "Nan takes a scrap of paper out of her pocket and shows you: TWICE, in her own big pencil, and above it, in a careful schooled hand, a whole letter she has read so often it is coming apart at the folds. 'Kit Lacey,' she says. 'Up the Stair. Dame Honor's nephew, the heir of the Small House.' She folds it up again. 'He writes like a book. I write like a collier. He's never seen me, and I've never been up the Stair.' She looks at the burned grate. 'He'll be ashamed. When he sees. A collier, with a burned house.'".
    On discuss { Assert knows(actor, nan_fears). }
  }
  Discovery nan_fears "Nan Collier fears that Kit Lacey, who has only ever read her letters, will be ashamed of her when he sees her: a collier with a burned house.".
  Relation nanBrought(group). Relation kitNanMet(group).
  Topic nan_come with nan "Ask Nan Collier to come up the Stair with you, to the Nursery" when knows(actor, nan_fears) and hearthBurned(hollins) and not nanBrought(nan) once {
    Says "Nan looks at the gap, and the flagstones, and the Stair beyond them going up into the dark. Then she spits on her hand and rubs her face with it, which makes it worse, and stands up. 'If he's ashamed,' she says, 'I'll know. That's something.' She puts the pencil behind her ear.".
    On discuss { Assert nanBrought(nan). Assert acceptsEscort(nan, actor). Assert following(nan, actor). }
  }

  // ── The Keys ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // The Guild of the Keys has played the First Air, the Child's nursery song, a note a minute, by teams jumping on the
  // keys of her piano, every Midwinter for a hundred years; and never finished it, because the last page was lost.
  Relation keysJumpers(group). Relation concertPlayed(group).
  Observe keys_scene at piano_keys when true "The keyboard of the piano is a long white road with black stones on it: eighty-eight keys, each a slab of yellowed ivory as long as a cart and as wide as a door, the black ones raised like tombs. The lid is up. Inside it, over the strings, the Keys have their guildhall: hammocks hung on the strings, which are as thick as cables and hum when the wind goes through the room. A blackboard leans on middle C, chalked with a staff of music and numbers: which team on which key, and when.".
  Observe keys_unfinished at piano_keys as feature when not concertPlayed(party) "On the blackboard, at the end of the music, the last bar is a row of question marks.".
  Person ludovic "Ludovic Flatt" at piano_keys {
    Role "the Cantor of the Keys". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Likeness "bard".
    Greets "A tall old man with white hair like a dandelion clock and a tuning fork on a ribbon round his neck turns from the blackboard. 'A visitor! To the Keys! Nobody visits the Keys.' He seizes your hand. 'Ludovic Flatt, Cantor. Do you sing? Do you jump? Can you count to sixty without losing your place? Most people can't.'".
    Greets again "'Can you count to sixty yet?' says Ludovic Flatt.".
  }
  Topic ludovic_air with ludovic "Ask Ludovic Flatt about the First Air" when true once {
    Says "'The Child taught it to the Laceys,' says Ludovic, 'in the doll's house, at bedtime, the winter she hid them. A nursery song. The Little Ship. My grandfather's grandfather Anselm wrote it down from old Honor Lacey's singing, ninety years after, and founded the Keys to play it on Her piano, because,' and he spreads his hands, 'because what else would you do with a song she sang?' He points to the keys. 'One note a minute. A team to a key: you run, you climb, you jump, together, and the key goes down, and the hammer falls inside, and the note comes up through the strings, enormous.' He stops. 'We've never finished it. The last page was lost when Anselm died. Every Midwinter we play to the end of what we have, and stop, on the fifth, unresolved, and stand there in the silence.' He laughs, and then does not. 'A hundred years of Midwinters ending on a question.'".
    On discuss { Assert knows(actor, page_lost). Assert knows(actor, first_air). }
  }
  Discovery page_lost "The last page of the Keys' score of the First Air, the Child's nursery song, was lost when Anselm Flatt died; the Keys have never played it to the end.".
  Discovery first_air "The First Air is the nursery song the Child sang the Laceys in the doll's house, The Little Ship. The Keys play it on her piano, a note a minute, by teams jumping on the keys.".
  Topic ludovic_jumpers with ludovic "Ask Ludovic Flatt what the Keys need to play it" when knows(actor, first_air) once {
    Says "'Weight,' says Ludovic sadly. 'The bass keys want weight. The colliers jumped the bass for us, sixty years: Bet Collier's people, big and heavy and on the beat. And now,' he gestures at the fireplace, 'now the colliers are on the Skirting with nothing, and nobody's thinking about the bass.' He brightens. 'And the page. If you found the page. Then with weight on the bass, and somebody who can hold a tune to lead the count, we could play it to the end. At night, when She's abed. All of it.' He looks up, at the ceiling, at what is above it. 'She'd hear it, through the floor. Do you think she'd hear it?'".
    On discuss { Assert knows(actor, keys_need). }
  }
  Discovery keys_need "To play the First Air to the end, the Keys need the lost page, weight on the bass keys (the colliers jumped it), and someone to lead the count; and they would play it at night, when the Lady is abed above.".
  Topic ludovic_page with ludovic "Give Ludovic Flatt the lost page" when carries(actor, score_page) once {
    Says "Ludovic takes the sheet in both hands, and unfolds it, and reads it, and you see his lips moving through the eleven notes. Then he sits down on a hammer-felt. 'Postage,' he says faintly. 'He posted it. The old fool posted it to himself.' He reads it again. 'It resolves,' he says. 'It goes down to the tonic. It ends.' And he puts his face in the sheet of music and laughs into it, or something like laughing.".
    On discuss { Spend score_page from actor. Assert pageGiven(ludovic). }
  }
  Relation pageGiven(group).
  Topic bet_jump with bet "Ask Bet Collier whether the colliers would jump the bass for the Keys again" when knows(actor, keys_need) and hearthBurned(hollins) and hearthWarned(hollins) and not keysJumpers(party) once {
    Says "Bet Collier looks at you as if you had asked her to dance at a funeral. Then she looks at her people along the Skirting, sitting in doorways with nothing to do with their hands. 'We jumped that bass for sixty years,' she says slowly. 'My dad jumped it. Bottom C, the big one.' She gets up. 'Aye. Why not. It's that or sit here and look at the wall.' She raises her voice. 'Who's for the Keys?'".
    On discuss { Assert keysJumpers(party). }
  }
  Topic nan_jump with nan "Ask Nan Collier whether the colliers would jump the bass for the Keys again" when knows(actor, keys_need) and hearthBurned(hollins) and collierDead(hollins) and not keysJumpers(party) once {
    Says "Nan looks along the Skirting at what is left of the Hearth. 'Mam jumped bottom C,' she says. 'Every Midwinter.' She is quiet. 'Aye. We'll jump it for her.'".
    On discuss { Assert keysJumpers(party). }
  }
  Relation concertTried(group).
  Action play_air(actor: group, site: place) "Lead the Keys through the First Air, to the end" {
    Description "An hour of running, climbing and jumping on the keys in the dark, a note a minute, with the whole Guild and the colliers on the bass, while the Lady sleeps above.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, piano_keys) and at(ludovic, piano_keys) and pageGiven(ludovic) and keysJumpers(party) and night() and not concertPlayed(party) and not ladyDead(lady) and not concertTried(party).
    Time 6.
    Resolve check(actor, performance, dc_fair).
    On success { Assert concertPlayed(party). Increase primed(lady) by 2. }
    On failure { Assert concertTried(party). }
    Result "It takes an hour. You stand on middle C with Ludovic and count, out loud, sixty to a note, and the teams run down the long white road in the dark and climb and gather and jump, all together, and the key goes down under them with a sound like a door, and somewhere inside the piano a hammer the size of a ram falls, and the note comes up through the strings, so big it is less a sound than a weather. Then silence, and the count, and the next. The colliers jump the bass like men driving piles. The tune goes on, impossibly slowly, a nursery song played by a mountain: The Little Ship. When you come to the last page Ludovic is weeping openly and still counting. The last note is bottom C, and every collier in the Wainscot is on it, and it goes down into the floor of the house and into the walls and up the Stair. And then, in the silence after it, overhead, the floor of the Lady's room creaks, and creaks again.".
    Otherwise "It goes wrong at the turn of the second page: a team on the wrong key, a count lost, two notes at once like a dropped tray, and then everybody stops, and stands in the dark on the keys listening to the strings hum down into silence. 'Again,' says Ludovic. 'Not tonight. But again.' Overhead, nothing stirs.".
  }
  Rule concert_retry when concertTried(party) and hour(clock) == 12 { Retract concertTried(party). }
  // She comes down to the piano with her candle.
  Rule lady_comes_down at piano_keys when concertPlayed(party) and not ladyAtPiano(lady) and at(party, piano_keys)
    says "A long time after, a light comes into the drawing room: a candle the size of a tree, carried slowly, and the great slow tread that shakes the keys. The Lady stands over the piano in a nightgown, holding the candle out, peering, and the Keys scatter into the strings, and you are standing on middle C in the light. She does not look at you. She is not looking at anything. She sets the candle down and puts out one finger, as long as a boat, and plays, very softly, the last eleven notes of the Little Ship, which come up through the keys under your feet; and then she sits on the piano stool and puts her face in her hands. 'Honor,' she says, to nobody. 'Honor, Ned. Are you there?'" { Assert ladyAtPiano(lady). }
  Relation ladyAtPiano(group).

  // ── The tea table ─────────────────────────────────────────────────────────────────────────────────────────────────
  Observe table_scene at tea_table when true "The top of the tea table is a polished field of walnut, with a lace cloth over half of it like a frozen sea. The tea things stand on it like the buildings of a city: the pot a domed hall of blue and white china, the sugar bowl a round tower with tongs in it like a crane, a cup and saucer, a plate with a cake on it as big as a haystack and smelling of caraway.".
  Observe table_lady at tea_table as ambience when at(lady, tea_table) "The Lady's hand comes down out of the air, slowly, with a fingertip the size of a loaf, and feels across the cloth for the cup, and finds it; and lifts it out of sight; and sets it down again, so close to you that the saucer rings like a bell.".
  Observe table_pye at tea_table as ambience when at(lady, tea_table) and at(pye, tea_table) "Mrs Pyecroft is reading aloud from somewhere up by the Lady's shoulder: the shipping news, three months old.".
}

data/adventures/hollins/endings.kyr:
Module hollins "Behind the Wainscot" {
  // ── What the house is, after ──────────────────────────────────────────────────────────────────────────────────────
  // When she dies the book closes on the state of the house: whether she knew them; whether a will was made and lodged
  // and the deed with it; whether the deed went to the Concern; whether the Smoking came, and who was out of it;
  // whether the ratcatcher did what they were hired to. A line is told for each that applies, and then the ending.
  Relation fateTold(entity).
  Entity f_hearth: fact "the Hearth". Entity f_pye: fact "Mrs Pyecroft". Entity f_jarl: fact "the Jarl". Entity f_regiment: fact "the Regiment".
  Entity f_kit: fact "Kit and Nan". Entity f_clock: fact "the clock". Entity f_stone: fact "the stone". Entity f_under: fact "the Under-folk". Entity f_sorrel: fact "Sorrel".
  Query accounting() means ladyDead(lady).
  Rule fate_kit when accounting() and kitNanMet(kit) and not fateTold(f_kit) says "Kit Lacey and Nan Collier are married in the parlour of the Small House in the spring, under the WELCOME, with the colliers on the stair and Dame Honor at the head of the table, wearing, people notice, a new chain: buttons, and in the middle of it a piece of coal." { Assert fateTold(f_kit). }
  Rule fate_sorrel when accounting() and sorrelStays(sorrel) and not fateTold(f_sorrel) says "Sorrel Haddow sat at the chart table every day of the last week with her broom, and wrote down what the Lady said, a yard high; the Readers have bound it, and it is the first book in Hollins written by anyone who lived in its walls." { Assert fateTold(f_sorrel). }
  Rule fate_regiment_rest when accounting() and standDown(regiment) and not fateTold(f_regiment) says "The Tin Regiment sits in its Fort with its keys still, and the nursery children of the Wainscot play round them and climb on them, and sometimes, on a warm day, one of them is heard to tick." { Assert fateTold(f_regiment). }
  Rule fate_regiment_stopped when accounting() and regimentStopped(regiment) and not standDown(regiment) and not fateTold(f_regiment) says "The Tin Regiment stands in its Fort where it stopped, every soldier at his post, the Captain's sword pointing at the door. Nobody winds them. Fennick sits in the ark." { Assert fateTold(f_regiment). }
  Rule fate_regiment_pye when accounting() and pyeStabbed(pye) and not fateTold(f_regiment) says "Mrs Pyecroft was buried in Bootscrape churchyard, which was the first time most of Bootscrape had seen her face close. The tin soldiers stand in their Fort with their bayonets dark, and the Captain has not spoken since." { Assert fateTold(f_regiment). }
  Rule fate_pye_provided when accounting() and pyeTurned(pye) and not pyeStabbed(pye) and not fateTold(f_pye) says "Mrs Pyecroft goes home to Market Lambury, to a cottage with a green door her own size and bees at the bottom of the garden, and writes to Dame Honor every month, in a fair hand, about the bees." { Assert fateTold(f_pye). }
  Rule fate_pye_cowed when accounting() and pyeCowed(pye) and not pyeTurned(pye) and not fateTold(f_pye) says "Mrs Pyecroft goes down the ladder the morning after with her clothes in a bandbox, and takes the carrier to Wendle, and does not look back at the house, and nobody in Bootscrape knows what becomes of her." { Assert fateTold(f_pye). }
  Rule fate_jarl when accounting() and haspStands(hasp) and watDead(wat) and not fateTold(f_jarl) says "In the back of the Pantry, where the trap was, the Jarmen have cut a little room into the side of a honey-crock, and put a whistle made from a pin in it, and nobody goes in there but Hasp." { Assert fateTold(f_jarl). }
  Rule fate_under when accounting() and underfolkEntered(annet) and not fateTold(f_under) says "Forty-one names are entered in the Post's register under a new heading, in Faith Penny's hand: CAME IN BY THE COAL-HOLE. Drewe gives them their thimbles." { Assert fateTold(f_under). }
  Rule fate_stone when accounting() and stoneTurned(party) and not fateTold(f_stone) says "On the moor above Bootscrape the Waiting Stone stands as it always has, except that the lichen on the house side has grown back over the fresh line, and people who walk up there say it does not seem to be waiting any more." { Assert fateTold(f_stone). }
  Rule fate_clock_cold when accounting() and not ladyKnows(lady) and not (smoked(hollins) and not evacuated(hollins)) and not fateTold(f_clock) says "The night she dies, the Winders climb into the works and stop the Long Clock, at the minute it happened, with a finger on the pendulum. It is still the day she died, the Prior says, and nobody argues; the oil-cans are put away." { Assert fateTold(f_clock). }
  Rule fate_clock_known when accounting() and ladyKnows(lady) and not fateTold(f_clock) says "The Long Clock goes on striking. The Winders wind it now, every Sunday, forty turns, with a team on the key, because she said it was today, and so it is." { Assert fateTold(f_clock). }

  Rule fate_nursery when accounting() and smoked(hollins) and not evacuated(hollins) and refugeesHoused(hollins) and not fateTold(f_kit) says "The Nursery was spared. The colliers the Moot had sent up to the Small House came down the ladder in the summer, with the Laceys, and went away over the moor together." { Assert fateTold(f_kit). }
  Rule fate_rat_smoke when accounting() and soldOut(party) and smoked(hollins) and not evacuated(hollins) and not fateTold(f_hearth) says "The Smoking came on the night the ratcatcher's word reached Mrs Pyecroft. The Post's register ends that night, in mid-line." { Assert fateTold(f_hearth). }
  Rule fate_rat_poison when accounting() and soldOut(party) and poisoned(lady) and not fateTold(f_jarl) says "She did not live to the tenth night: there were almonds in her sugar on the sixth, and the Jarl has the Pantry." { Assert fateTold(f_jarl). }

  // ── The endings, from the most particular ─────────────────────────────────────────────────────────────────────────
  Ending ratcatcher "The Ratcatcher" over tea, smoking when ladyDead(lady) and soldOut(party) and not ladyKnows(lady) "She died on the tenth night, in a quiet house. Mrs Pyecroft paid the ratcatcher's account in full, with a bonus, and wrote a character for them in a fair hand: thorough, discreet, and successful. It is quite true. What the Wainscot calls them, those of it who are left, is not written anywhere; but it is said in Bootscrape, at the Mat, to children, as a warning.".
  Ending tea "The Tea at Ten Past Four" when ladyDead(lady) and poisoned(lady) "She died a little before midnight on the sixth day, in her bed, with Mrs Pyecroft holding one of her fingers in both arms. Doctor Hume's great-great-grandson came out from Wendle and said her heart, and nobody in the house said otherwise. Six hundred people in the walls know what was in the sugar; most of them did not want it; none of them will ever say. The Jarl has the Pantry, and the honey, and whatever else is left when her cousin's lawyers come. In the Wainscot they still tell children the story of the Child who hid the Laceys in her own house, and now it has an ending, and the children are not told it.".
  Ending smoking "The Smoking" when ladyDead(lady) and smoked(hollins) and not evacuated(hollins) "She died on the tenth night, in her bed, upstairs, warm, in a house that was quiet at last, as Mrs Pyecroft had promised her it would be. She never knew. In the spring the Bootscrape men went in through the Slot with sacks and lanterns, and came out, and went in again, for a week, and dug in the kitchen garden among the catmint, and did not talk about it afterward, then or ever. The Post's register ends on the night of the Smoking, in mid-line.".
  Ending freehold "The Freehold" when ladyDead(lady) and ladyKnows(lady) and willLodged(lady) and deedLodged(party) and not deedSold(party) "She died on the tenth night, a little before midnight, with six hundred people on her floor. Mr Salcombe proved her will in the county court at Wendle in the spring, against a cousin, the Hollins Stone Concern, and a good deal of laughter, and won, with the deed on the table in front of the judge like a rolled carpet: the house and lands of Hollins, and all in it, to the people who live in its walls, in common, for ever. It is entered in the rolls of the county as the first freehold ever held in Imbar by people living inside a building that belongs to them. In Hollins the shutters are open. The Slot is a door. The Lady's chart hangs in the Hall, framed, a field of paper, with the Wainscot drawn into it in a big black hand, every lane in its place; and in the margin, in hers, under WE LIVE HERE: SO YOU DO. E. W.".
  Ending last_game_sold "The Last Game, and the Quarrymen" when ladyDead(lady) and ladyKnows(lady) and deedSold(party) "She died on the tenth night, knowing. Her last week was the best of her life, she told Dame Honor, who wrote it down. But the deed went to the Concern, and her will, if she made one, could not stand against the conveyance and the deed together. In the spring Mr Overy's men put scaffolding up the chimneys, and the Wainscot went down the rope ladder one family at a time, carrying what fitted, into Bootscrape and over the moor. They took the Small House with them, on a cart, room by room. It is the only house in Imbar that has been carried out of another house.".
  Ending last_game "The Last Game" when ladyDead(lady) and ladyKnows(lady) "She died on the tenth night, knowing; that was the whole of what she had wanted, she told Dame Honor, and more than she had hoped. She made no will that would stand, or none that could be proved without the deed. Her cousin in Sabine's country has written to Mr Salcombe, and Mr Salcombe has written back, and they will write for some years, Salcombe says, which is how the law gives people time. In Hollins the shutters are open, and the Clock strikes, and the Wainscot lives as it lived, in a house it does not own, which it has learned is not the same as a house that does not know it.".
  Ending sold "Sold for Stone" when ladyDead(lady) and deedSold(party) "She died on the tenth night, in a quiet house, not knowing. The deed was in Mr Overy's hands and the conveyance was signed, and in the spring the Concern's men put scaffolding up the chimneys and began to take Hollins down, course by course, for a corn exchange and a gaol in Wendle. The Wainscot went down the ladder before them, one family at a time. Bootscrape took in whom it could. The rest went over the moor.".
  Ending downladder "Down the Ladder" when ladyDead(lady) and smoked(hollins) and evacuated(hollins) "She died on the tenth night, upstairs, in a house that had been smoked from cellar to Hall, and was empty. The Wainscot had gone down the rope ladder to Bootscrape, or up to the Nursery, and it stayed there. Bootscrape is twice the size it was, and has a Post, and a Court that sits in the Mat's back room on Thursdays, and a Nail, and an argument every evening about whether to go back. The house stands on the hill with its windows dark, as it stood for three hundred years, with nobody in it at all.".
  Ending cold "The House Goes Cold" when ladyDead(lady) "She died on the tenth night, in her bed, not knowing; she had thought, at the end, that the noises in the walls were her mind, and had been glad when they were quieter. Mrs Pyecroft closed her eyes and went down the ladder with her bandbox. Nobody found the deed, and the Concern's paper was not worth the trouble of the cousin's lawyers, and so for now nothing happens to Hollins at all. The fires go out. The cold comes back into the walls, slowly, over a week, and the Wainscot puts its coats on again, and goes on living in the house of a woman who never knew it was there, which is what it always did.".

  // ── Experience ────────────────────────────────────────────────────────────────────────────────────────────────────
  Milestone ms_hearth "got the Hearth out before the fire" worth 100 when hearthWarned(hollins) and hearthBurned(hollins).
  Milestone m_rats "ratted the back pantry, honestly" worth 50 when ratted(party).
  Milestone m_wat "kept Wat Tallowby out of the trap" worth 75 when day4() and not watDead(wat).
  Milestone m_bell "belled the cat" worth 150 when belled(bishop) and bellVolunteer(party) or belled(bishop) and not catShutIn(bishop).
  Milestone m_concert "played the First Air to the end" worth 150 when concertPlayed(party).
  Milestone m_chart "wrote back on the Lady's chart" worth 100 when chartWritten(party).
  Milestone m_known "made the Wainscot known to the Lady" worth 200 when ladyKnows(lady).
  Milestone m_honor "brought Honor Lacey before her" worth 100 when honorMet(honor).
  Milestone m_mother "gave the Lady her mother's letter" worth 100 when motherDelivered(lady).
  Milestone m_letter "delivered the letter with the black seal" worth 75 when letterRead(lady).
  Milestone m_stone "carried her answer to the stone" worth 75 when replyLaid(party).
  Milestone m_verity "kept the Clock going" worth 75 when verityRelents(verity).
  Milestone m_under "had the Under-folk counted" worth 75 when underfolkEntered(annet).
  Milestone m_vault "opened the Whitbreads' strongbox" worth 100 when state(strongbox, open).
  Milestone m_poison "kept the poison out of her tea" worth 150 when day7() and not poisoned(lady) and haspPlots(hasp) or haspStands(hasp) and watDead(wat).
  Milestone m_smoke "kept the Smoking from the Wainscot" worth 150 when smokingOver(hollins) and not smoked(hollins) and pyeOrdered(pye) or smoked(hollins) and evacuated(hollins).
  Milestone m_will "saw her will lodged, and the deed with it" worth 200 when willLodged(lady) and deedLodged(party).
  Milestone m_kit "brought Nan Collier up the Stair" worth 75 when kitNanMet(kit).
  Milestone m_peace "ended the Tin Regiment's war" worth 100 when standDown(regiment).
}

data/adventures/hollins/hall.kyr:
Module hollins "Behind the Wainscot" {
  // ── The doorstep and the Slot ─────────────────────────────────────────────────────────────────────────────────────
  // Hob's rope ladder goes up the face of the step from the street; at the top, the letterbox, whose brass flap is
  // propped open with a wedge, and a rope ladder down the inside into the drift of three centuries of letters.
  Place step_top "the top of the doorstep" is room within hollins at 0, 1 outdoors.
  Place slot_inside "the inside of the Slot" is room within ground_floor at 0, 0.
  Place letterdrift "the Letterdrift" is room within ground_floor at 1, 0.
  Place hall_flags "the Hall floor" is room within ground_floor at 2, 1.
  Place clock_foot "the foot of the Long Clock" is room within ground_floor at 3, 1.
  Place clock_case "inside the Long Clock" is room within ground_floor at 3, 0.
  Place clock_hood "the works of the Long Clock" is room within ground_floor at 4, 0.
  Place stair_foot "the foot of the Stair" is room within ground_floor at 2, 2.

  Passage step_ladder "Hob's ladder up the doorstep" is ladder between bs_street and step_top taking 10 minutes.
  Passage the_slot "the Slot" is crawl between step_top and slot_inside taking 2 minutes.
  Passage drift_ladder "the rope ladder down into the drift" is steps between slot_inside and letterdrift.
  Passage drift_path "the path down off the drift" is passage between letterdrift and hall_flags taking 10 minutes.
  Passage clock_path "the way across the flagstones to the clock" is passage between hall_flags and clock_foot taking 10 minutes.
  Passage clock_crack "the crack in the clock's plinth" is crawl between clock_foot and clock_case.
  Passage weight_chain "the weight-chain" is steps between clock_case and clock_hood taking 10 minutes.
  Passage stair_path "the way across the flagstones to the Stair" is passage between hall_flags and stair_foot taking 10 minutes.

  Observe step_scene at step_top when true "The top of the doorstep is a plain of grey stone sixty feet above Bootscrape, worn into a hollow in the middle by the feet of giants. The door rises out of it, black oak, studded, going up into the sky; the keyhole above you is a cave. At the height of your head is the letterbox, a brass mouth a yard long with its flap wedged open by a chunk of wood, and a smell coming out of it of paper, dust and candles.".
  Observe slot_scene at slot_inside when true "Inside the brass mouth of the letterbox, a ledge, and a rope ladder going down into a dimness that smells of old paper. Somebody has painted on the brass, small and neat, POST OFFICE OF THE WAINSCOT. ALL COMERS TO REPORT. And under it, smaller: MIND THE DROP.".
  Observe drift_scene at letterdrift when true "Below the letterbox lies the Letterdrift: three hundred years of letters, fallen through the slot onto the hall floor and never picked up, heaped into a dune as high as a barn and as long as a street. The letters are a giant's letters, each the size of a bedsheet, folded; their seals are cartwheels of red wax. Paths go over and into the drift, and in it people have dug rooms, roofed with envelopes, lit by candle-ends, with addresses for walls: MISS E. WHITBREAD, HOLLINS; THE LADY WHITBREAD, BY HAND; and a great many bills.".
  Observe drift_post at letterdrift as feature when true "In the face of the drift a counter has been built out of a giant's postcard on trestles. Pigeonholes are cut into the paper behind it, labelled in a clear hand: NEWS, OLD; NEWS, OLDER; LOVE; MONEY; DEATHS; ILLEGIBLE.".
  Observe hall_scene at hall_flags when not dark() "The Hall of Hollins. The floor is flagstones of grey stone, each as wide as a threshing-floor, with grass-wide cracks between them where people have planted cress. The far wall is so far off it is blue. Up it climbs the Stair, a flight of cliffs going up into the dimness, and against the east wall stands a tall clock-case like a tower, its face high up, its hands stopped at a little after four. Along the foot of every wall runs the skirting, a moulded board as high as a cottage, with doors cut in it.".
  Observe hall_night at hall_flags when dark() "The Hall at night is a dark plain under a dark sky that is a ceiling. Here and there along the skirting a little light shows, where the Wainscot has its doors. Somewhere out on the flagstones, a long way off, there is a sound like a sack being dragged.".
  Observe hall_lit at hall_flags as feature when hearthBurned(hollins) and not fireOut(hollins) and not ladyDead(lady) and not dark() "Warm air moves across the flagstones from the drawing-room door, where a fire has been lit; and the cress in the cracks has turned toward it, all of it, overnight.".
  Observe hall_still at hall_flags as ambience when at(lady, hall_flags) "The floor is shaking. Everywhere on the flagstones people have stopped exactly where they are, mid-step, mid-word, a child with one foot raised; and above them, filling the Hall, the Lady goes by.".

  // ── The Post of the Wainscot ──────────────────────────────────────────────────────────────────────────────────────
  Person faith "Faith Penny" at letterdrift {
    Role "the Postmistress of the Wainscot". Ancestry halfling. Peaceable. Pronouns she. Manner stoic.
    Likeness "scholar".
    Greets "A halfling woman in a green cap with POST on it in brass letters looks up from a register the size of a cottage door, laid flat on trestles. 'Name, place of origin, purpose of visit,' she says, and dips a pen. 'Everyone who comes in by the Slot is entered. We have entered everyone for two hundred and ninety years.' She waits. 'And you've no letters for anyone, I suppose. Nobody ever has letters.'".
    Greets again "Faith Penny looks up from the register and, without asking, turns to your entry.".
  }
  Relation registered(group).
  Topic faith_enter with faith "Give Faith Penny your name, and where you are from, for the register" when not registered(actor) once {
    Says "Faith Penny writes it down, slowly, in a round clerk's hand, and blots it, and reads it back to you, getting one thing wrong on purpose to see if you are listening. 'Entered,' she says. 'You're somebody in Hollins now. You can draw a thimble at the Sink, and be buried by the Post if it comes to that.' She turns back a page. 'Mrs Pyecroft is entered too. Every morning. She comes down the ladder past this counter and never stops, and I write her down: D. PYECROFT, OF THE LADY'S POCKET, PURPOSE UNSTATED.' She almost smiles. 'She doesn't know she's in the book. Most people don't.'".
    On discuss { Assert registered(actor). }
  }
  Topic faith_post with faith "Ask Faith Penny what the Post does" when true once {
    Says "'We keep the drift,' says Faith Penny. 'Everything that ever came through the Slot. We read it, for the news, because three-hundred-year-old news is the only kind that comes in; it's how we know there was a war in the east and a king called Aldo who died. We enter every soul that comes in.' She sets the pen down. 'And we deliver. When the person a letter is for comes home, we deliver it. That's the oath of the Post. Nobody ever came home.' She looks at the pigeonholes. 'Until Thursday.'".
    On discuss { Assert knows(actor, post_oath). }
  }
  Discovery post_oath "The Post of the Wainscot keeps the Letterdrift, reads it for news, and is sworn to deliver each letter when the person it is for comes home. Nobody ever came home, until the Lady.".
  Topic faith_letter with faith "Ask Faith Penny whether there are letters for the Lady" when knows(actor, post_oath) once {
    Says "Faith Penny's mouth goes thin. 'Four hundred and twelve,' she says, 'addressed to Miss E. Whitbread. Bills, mostly. Condolences on her mother. A school.' She stops. 'And one.' She goes into the back of the drift and comes out with something the size of a door, and lays it on the counter as if it might break: a giant's letter, folded small, the paper gone the colour of tea, its seal a black disc with a C on it. Under the address someone has written, in a hand that shook: TO BE GIVEN HER WHEN SHE COMES HOME. 'It came the week she went,' says Faith. 'Two hundred and ninety-one years under a bell-jar in the back.' She puts both hands flat on it. 'I swore to deliver it. I took the oath on it. And I cannot go out there and walk up to her. I've tried. I get as far as the drawing-room door and my legs stop.'".
    On discuss { Assert knows(actor, letter_kept). }
  }
  Discovery letter_kept "In the Letterdrift, under a bell-jar, the Post has kept a letter to Miss Whitbread with a black C on its seal, which came the week she went away, marked TO BE GIVEN HER WHEN SHE COMES HOME. Faith Penny is sworn to deliver it, and cannot make herself go near the Lady.".
  Topic faith_give_letter with faith "Offer to deliver the Lady's letter for the Post" when knows(actor, letter_kept) and not letterDelivered(party) once {
    Says "Faith Penny takes off her green cap, puts it on the counter, and puts it back on, because the cap is not hers to give. 'Not on the floor,' she says. 'Where she'll find it. Her table in the Library, where she works of a morning; or by her bed.' She pushes the letter across the counter with both hands, and you have to brace to take the weight. 'The Post is obliged to you,' she says, and enters it in the register, and her pen shakes. 'Delivered by hand.'".
    On discuss { Give c_letter to actor. }
  }
  Kind c_letter_kind "the letter with the black seal" is gear worth 0 weighing 3 described "A giant's letter folded to the size of a door, the paper brown with age, sealed with a black wax disc a foot across stamped with a C. The address is in a big slanting hand that leaned on the pen: Miss Ermengarde Whitbread, Hollins. Under it, in another, shakier hand: TO BE GIVEN HER WHEN SHE COMES HOME.".
  Item c_letter "the letter with the black seal" is c_letter_kind at nowhere.
  Relation letterDelivered(group).
  // The lost page of the Keys' score: posted to himself by the Guild's founder ninety years ago, for safe keeping, and
  // never collected, because the postage was not paid.
  Topic faith_page with faith "Ask Faith Penny about the Keys' lost page" when knows(actor, page_lost) and not pageGot(party) once {
    Says "Faith Penny turns the register back a long way, licks her finger, turns some more. 'Here,' she says. 'Ninety-one years ago. One sheet, folded, from Master Anselm Flatt of the Keys, to Master Anselm Flatt of the Keys, care of the Post. Postage due, three coin. Not paid.' She looks up. 'It's in NEWS, OLDER. The Keys have asked for it every year since he died, and every year I tell them the same thing.' She closes the register. 'Three coin. The Post is not a cupboard.'".
    On discuss { Assert knows(actor, page_held). }
  }
  Discovery page_held "The lost last page of the Keys' score is in the Letterdrift: the Guild's founder posted it to himself ninety-one years ago and never paid the postage. Faith Penny will give it up for three coin postage due.".
  Action pay_postage(actor: group, site: place) "Pay Faith Penny three coin postage due on the Keys' page" {
    Speaker faith.
    Requires able(actor) and company(actor) and at(actor, site) and at(faith, site) and knows(actor, page_held) and not pageGot(party) and quantity(actor, gold) >= 3.
    On success { Decrease quantity(actor, gold) by 3. Increase quantity(faith, gold) by 3. Assert pageGot(party). Give score_page to actor. }
    Result "Faith Penny counts the coins twice, enters them, and stamps the register with a stamp cut from a cork. Then she goes into NEWS, OLDER and comes back with a folded sheet of ordinary paper, ordinary-sized, which looks absurd in the drift, like a moth in a barn. 'Postage paid,' she says, with enormous satisfaction. 'Tell Ludovic Flatt the Post has been waiting ninety-one years for him to grow up.'".
  }
  Action plead_postage(actor: group, site: place) "Argue to Faith Penny that a letter to oneself was never posted" {
    Speaker faith.
    Requires able(actor) and company(actor) and at(actor, site) and at(faith, site) and knows(actor, page_held) and not pageGot(party) and not pleadedPage(party).
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert pageGot(party). Give score_page to actor. }
    On failure { Assert pleadedPage(party). }
    Result "Faith Penny opens her mouth, and shuts it, and looks at the register. 'It was addressed,' she says. 'But it was not sent anywhere. It went from him to him. It was never in the post. It was in a cupboard that happened to be the post.' She takes off her cap and rubs her forehead. 'Ninety-one years.' She goes and gets it. 'Don't tell anyone,' she says. 'Especially not Ludovic.'".
    Otherwise "'Postage,' says Faith Penny, 'is due on what is posted. It was posted. It went through my hands. The Post does not do philosophy.' She goes back to her register.".
  }
  Relation pleadedPage(group). Relation pageGot(group).
  Kind page_kind "the Keys' lost page" is gear worth 0 weighing 0 described "One sheet of ordinary paper, folded in four, with a staff of music ruled on it by hand and eleven notes, and under them in an old man's writing: THE LAST OF THE FIRST AIR, AS SHE SANG IT. A. F.".
  Item score_page "the Keys' lost page" is page_kind at nowhere.

  // ── The Long Clock and the Winders ────────────────────────────────────────────────────────────────────────────────
  // The clock was stopped at ten past four by a child's finger, three hundred and twelve years ago. The heretic Absalom
  // Hale came in by the Slot two hundred years since and taught that it held the Day of the Going suspended: so long as
  // it stood, the Child was still on her way home. His Winders oil it and do not wind it. The Lady winds it at dusk on
  // the first evening, and it strikes; whether it goes on striking is the Winders' quarrel.
  Thing long_clock "the Long Clock" at clock_foot is scenery {
    State stopped "High overhead the clock's face is a white moon with black hands, stopped at ten past four.".
    State going "High overhead the clock's face is a white moon, and its hands are moving. From inside the case, slow and enormous, comes the tock of the pendulum, like a door closing in another house, again, and again.".
    State jammed "High overhead the clock's hands have stopped again at a few minutes past some hour, and the case is silent.".
  }
  Observe foot_scene at clock_foot when true "At the foot of the Long Clock the plinth rises like the wall of a fort, carved with acanthus leaves, each leaf a cart you could lose a family in. At the base, where the wood has shrunk from the floor, a crack the height of a door has been widened and hung with a curtain of red velvet, and over it, painted on the wood: THE WINDERS. IT IS STILL THE DAY.".
  Observe case_scene at clock_case when true "Inside the Long Clock the dark goes up and up, a wooden tower, smelling of oil. Two weights hang in it on chains as thick as your leg, each weight a brass barrel the size of a hut; between them the pendulum's bob, a brass sun as tall as two men. Benches face it. Candles burn along a ledge. On the back of the case people have painted, very small and very many, the hands of the clock at ten past four, over and over, like a prayer.".
  Observe case_going at clock_case as feature when state(long_clock, going) "The pendulum swings. The brass sun goes out of the candlelight into the dark, and comes back out of the dark into the candlelight, and the benches are empty but for a few who sit with their faces wet, watching it.".
  Observe hood_scene at clock_hood when true "At the top of the weight-chain, the works: a city of brass wheels with teeth like ploughshares, pinions, a great wheel for the strike with a hammer poised over a bell with a room's worth of silence inside it. Everything here is oiled, and has been oiled, every week, for two hundred years, by people who believed it must never move.".
  Observe hood_jammed at clock_hood as feature when state(long_clock, jammed) "A pin, a giant's dressmaker's pin, has been driven between two teeth of the strike train, and everything has stopped against it.".
  Person tobit "Prior Tobit Hale" at clock_case {
    Role "the Prior of the Winders". Ancestry human. Peaceable. Pronouns he. Manner compassionate.
    Likeness "priest".
    Greets "An old man in a black gown oiled at the cuffs gets up from a bench beneath the hanging weights. 'Peace, and the Day,' he says, the Winders' greeting. 'You have come in the strangest week since the Going. Sit, if you like. Most people come here to sit.'".
    Greets again "'Peace, and the Day,' says Prior Tobit Hale.".
  }
  Topic tobit_day with tobit "Ask Prior Tobit Hale what the Day is" when true once {
    Says "'The Day of the Going,' says the Prior. 'The Child went away at ten past four on a winter afternoon. Absalom Hale, who founded us, taught that she stopped the clock as she went, with her own finger, so that it should be the same day when she came back.' He looks up into the dark of the case. 'So it has been the same day for three hundred and twelve years. We oil the works, and never wind them. While the clock stands, the Child is coming home.'".
    On discuss { Assert knows(actor, the_day). }
  }
  Discovery the_day "The Winders teach that the Child stopped the Long Clock with her finger at ten past four, as she was sent away, so that it would be the same day when she came home; they oil it and never wind it.".
  Topic tobit_struck with tobit "Ask Prior Tobit Hale what it means, that the Clock has struck" when state(long_clock, going) once {
    Says "The old man's face is wet and he does not wipe it. 'She came to the clock,' he says. 'She stood there at dusk, so close I could see the threads in her sleeve, and she opened the trunk and wound it with a key like a ship's wheel, and set the hands by her watch, and it struck six.' He takes your hand. 'It means the Day is over. It means she has come home. We were right. Two hundred years, and we were right.' He holds on. 'Sister Verity says the opposite. Sister Verity says if the Day is over she can never come. Go and talk to her, if you can bear to; I can't.'".
    On discuss { Assert knows(actor, winders_split). }
  }
  Discovery winders_split "The Winders are split by the Clock's striking: Prior Tobit Hale says the Day is over because the Child is home; Sister Verity Cogg says if the Day is over the Child can never come.".
  Topic tobit_serve with tobit "Ask Prior Tobit Hale what the Winders want now" when knows(actor, winders_split) once {
    Says "'To serve her,' says the Prior simply. 'We kept her clock. Two hundred years we kept her clock clean against the day she came. I want to tell her so. I want her to know someone kept faith.' He smiles, and it is a young man's smile on an old face. 'I don't need her to thank us. I'd only like her to know.'".
    On discuss { Assert knows(actor, tobit_wants). }
  }
  Topic tobit_told with tobit "Tell Prior Tobit what the Lady said about her clock" when tobitHonored(tobit) once {
    Says "The Prior listens with his eyes shut. It is today. When you have finished he sits on his bench under the swinging brass sun until the pendulum has gone over twice. 'Two hundred years,' he says, 'we said it was still the day. And she says it is today.' He opens his eyes. 'That is not the same thing, you know. It is better.' He gets up, stiffly, and takes a coil of rope from under the bench, which you realise is for the weights. 'Every Sunday,' he says. 'Forty turns. I shall need a team.'".
  }
  Discovery tobit_wants "Prior Tobit Hale wants only that the Lady should know the Winders kept her clock clean for two hundred years.".

  Person verity "Sister Verity Cogg" at clock_hood {
    Role "a Winder, of the old observance". Ancestry gnome. Peaceable. Pronouns she. Manner grim.
    Likeness "priest".
    Greets "Up among the wheels a small gnome-woman with an oil-can on a strap turns round fast, as if you had caught her at something. 'Nobody comes up here,' she says. 'Nobody but me. Go down.'".
    Greets again "Sister Verity Cogg does not turn round. 'Still here,' she says.".
  }
  Topic verity_day with verity "Ask Sister Verity Cogg why the Clock must not strike" when knows(actor, the_day) once {
    Says "She grips the oil-can. 'Because while it stood, she was coming,' she says. 'Every day. Every single morning of my life I woke and it was still the Day, and she was still on the road, and every knock at the Slot might be her.' Her voice is shaking. 'That old woman upstairs is not the Child. That is a stranger with a cat who sets traps for us. The Child loved us. The Child is still coming, and she cannot come if the Day is over, and the Day is over if it strikes.' She looks at the strike wheel. 'So it will not strike.'".
    On discuss { Assert knows(actor, verity_plans). }
  }
  Discovery verity_plans "Sister Verity Cogg means to stop the Long Clock striking, because she believes that the old woman upstairs is not the Child, and that the Child can never come home if the Day of the Going is over.".
  // She jams the strike train on the third night, unless she has been talked out of it, or is watched.
  Relation verityRelents(group). Relation verityCaught(group).
  Rule verity_jams when state(long_clock, going) and dayN(hollins) >= 3 and hour(clock) >= 23 and not verityRelents(verity) and not verityCaught(verity) and not at(party, clock_hood) {
    Assert state(long_clock, jammed).
  }
  Rule verity_watched at clock_hood when state(long_clock, going) and dayN(hollins) >= 3 and hour(clock) >= 23 and at(party, clock_hood) and not verityRelents(verity) and not verityCaught(verity)
    says "Sister Verity comes up the chain in the dark with a giant's pin over her shoulder like a lance, and stops when she sees you, and stands with it there while the wheels go round. Then she lets it down, very carefully, against the wheels. 'You'd tell,' she says. 'You'd tell the Prior.' She sits down on a spoke of the strike wheel with her face in her hands." { Assert verityCaught(verity). }
  Topic verity_diary with verity "Read Sister Verity Cogg what the Child wrote about the clock" when knows(actor, diary_clock) and not verityRelents(verity) once {
    Says "You read it to her from the diary's copy: I have stopped the hall clock with my finger so that it will still be today when I come home. Sister Verity does not move. Then she puts down the oil-can, and takes the giant's pin out from where she had hidden it behind the bell, and lays it on the floor of the works. 'When I come home,' she says. 'She wrote that. She meant to come home.' She looks up at the wheels, which are turning. 'Then it's today,' she says. 'It's today. She came.' And she laughs, a small helpless sound, and goes on laughing, and cannot stop.".
    On discuss { Assert verityRelents(verity). }
  }
  Action argue_verity(actor: group, site: place) "Ask Sister Verity Cogg what the Child would want with a stopped clock now" {
    Speaker verity.
    Requires able(actor) and company(actor) and at(actor, site) and at(verity, site) and knows(actor, verity_plans) and not verityRelents(verity) and not arguedVerity(party).
    Resolve check(actor, insight, dc_hard).
    On success { Assert verityRelents(verity). }
    On failure { Assert arguedVerity(party). }
    Result "She stares at you. 'The Child stopped it to keep a day from ending,' you say. 'So that it would be the same day. What day is it now?' Sister Verity opens her mouth, and closes it. She looks down through the wheels to the case below, where the pendulum is swinging. 'The day she came home,' she says at last, as if somebody else had said it. She puts the oil-can down. 'I'll oil it,' she says. 'Somebody must. It's going, now. It'll want oiling.'".
    Otherwise "'You don't know what it is to wait,' says Sister Verity. 'Go down.'".
  }
  Relation arguedVerity(group).
  // A jammed clock can be freed by someone who knows works.
  Action free_clock(actor: group, site: place) "Work the pin out of the strike train" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, clock_hood) and state(long_clock, jammed).
    Resolve check(actor, mending, dc_fair).
    Time 3.
    On success { Assert state(long_clock, going). }
    Result "It takes leverage and patience and a good deal of oil. The pin comes out of the teeth with a shriek, and slides, and drops away into the dark of the case, and somewhere below it rings on a brass weight like a gong. The great wheels shiver, and take up their load, and turn.".
    Otherwise "The pin is wedged hard between two teeth like ploughshares, and will not move for anything you can do.".
  }
  // Whoever winds a stopped clock and finds it stopped asks why; and Mrs Pyecroft has an answer.
  Relation clockTrapped(group).
  Rule lady_finds_jammed at clock_foot when state(long_clock, jammed) and at(lady, clock_foot) and hour(clock) >= 18 and not clockTrapped(pye) and not pyeTurned(pye) and not pyeGone(pye)
    says "The Lady stops at the clock with the key in her hand, and stands, and listens. 'Dorothea, it has stopped.' A small dry voice from her shoulder: 'Mice in the works, I expect, Miss Whitbread. I shall see to it.'" { Assert clockTrapped(pye). }
  Relation priorHurt(group).
  Rule clock_trap_springs when clockTrapped(pye) and dayN(hollins) >= 5 and not priorHurt(tobit) and not trapsCleared(clock_case)
    { Assert priorHurt(tobit). }
  Observe case_hurt at clock_case as sign when priorHurt(tobit) "Somebody has put a spring-trap inside the plinth, in the dark at the foot of the weights, and it has gone off; there is blood on the boards, and the benches have been pushed back, and nobody is sitting on them.".
  Relation trapsCleared(place).
  Action clear_clock_trap(actor: group, site: place) "Spring Mrs Pyecroft's trap inside the clock with a candle-end on a stick" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, clock_case) and clockTrapped(pye) and not priorHurt(tobit) and not trapsCleared(clock_case).
    On success { Assert trapsCleared(clock_case). }
    Result "You find it by feel, in the dark under the weights where the Prior sets his candles: iron jaws, open, with a crust of cheese on the plate. You touch the plate with a candle-end on a stick, and the jaws come together with a crack like a shot that brings the Winders up off their benches, and take the candle-end in half.".
  }

  // ── The Stair ─────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe stair_scene at stair_foot when true "The foot of the Stair: the first step is a cliff of polished oak eight feet high, and the next one above it, and the next, going up into the dimness in a flight of twenty-two. Against the first, a ladder; at its foot, a shed made of a giant's slipper-box, a brazier, and a hand-painted sign, RISER LADDERS: UP, A PENNY. DOWN, FREE. MIND THE CAT.".
  Person riser "Ma Riser" at stair_foot {
    Role "who keeps the ladders on the Stair". Ancestry human. Peaceable. Pronouns she. Manner grim.
    Likeness "farmer".
    Greets "A big woman with arms like a bargee's, sitting on a coil of rope by the brazier, puts out her hand without getting up. 'Penny up, free down. Twenty-two ladders, twenty-two families, and every one of them'll want to know your business, so you may as well tell me first and save your breath.'".
    Greets again "Ma Riser puts out her hand. 'Penny.'".
  }
  Thing riser_ladders "the Riser ladders" on stair_way {
    State tolled blocking "The Riser ladders go up the Stair, a ladder to a step, and a Riser at the top of each who will want to see you have paid Ma Riser.".
    State paid "The Risers wave you up, step by step, and their children race you.".
  }
  Passage stair_way "the Riser ladders up the Stair" is ladder between stair_foot and landing taking 30 minutes one way.
  Passage stair_down "the Riser ladders down the Stair" is ladder between landing and stair_foot taking 20 minutes one way.
  Action pay_riser(actor: group, site: place) "Pay Ma Riser a penny for the ladders" {
    Requires able(actor) and company(actor) and at(actor, site) and at(riser, site) and state(riser_ladders, tolled) and quantity(actor, gold) >= 1.
    On success { Decrease quantity(actor, gold) by 1. Increase quantity(riser, gold) by 1. Assert state(riser_ladders, paid). }
    Result "Ma Riser bites the coin, which is a custom, not a doubt, and bellows up the Stair: 'One up, paid!' The cry goes up the cliffs from family to family and comes back down, faint, from the top: 'One up, paid!'".
  }
  Rule ladders_retoll when hour(clock) == 0 and state(riser_ladders, paid) and not freeLadders(party) { Assert state(riser_ladders, tolled). }
  Relation freeLadders(group).
  Topic riser_cat with riser "Ask Ma Riser about the cat" when true once {
    Says "Ma Riser spits in the brazier. 'The Bishop,' she says. 'Hers. Grey, long in the coat, eighteen foot nose to tail, and a mouth on it you could drive a cart into. Sleeps on her bed all day like a lord. Hunts the ground floor all night like a devil. The Hall first, then the carpet in the drawing room, then the kitchen, till first light.' She pokes the fire. 'Took Ezra Tenter's lad off the flagstones the first night, before anybody knew. Didn't eat him. Played with him. That's cats.' She looks at you. 'Nobody crosses the open after nine now. You'd be wise to learn the same.'".
    On discuss { Assert knows(actor, cat_hunts). }
  }
  Discovery cat_hunts "The Lady's cat, the Bishop, eighteen feet long, sleeps on her bed by day and hunts the ground floor by night: the Hall from nine, the drawing-room Carpet from midnight, the kitchen from three, until first light. Nobody crosses the open after nine.".
  Topic riser_comings with riser "Ask Ma Riser who goes up and down" when true once {
    Says "'Everybody, through my hands,' says Ma Riser. 'Readers to the Library, Court folk to the Nursery, the Keys to their piano. Pyecroft goes up in the Lady's pocket and doesn't pay, and won't, and I've told her.' She counts on her fingers. 'And the dumbwaiter in the kitchen goes up to the landing, if you want to save a penny and risk your neck. It's on a rope. The Jarmen work it. They'll want more than a penny.'".
    On discuss { Assert knows(actor, dumbwaiter_known). }
  }
  Discovery dumbwaiter_known "In the kitchen a dumbwaiter, a box on a rope, goes up from the kitchen to the first-floor landing; the Jarmen work it.".
}

data/adventures/hollins/kitchen.kyr:
Module hollins "Behind the Wainscot" {
  // ── The kitchen ───────────────────────────────────────────────────────────────────────────────────────────────────
  // Through the green baize door off the Hall: the kitchen, with the cold range, the stone sink under its dripping tap,
  // the pantry door (the Jarmen's gate), the cellar steps, and the dumbwaiter in its shaft to the floor above.
  Place kitchen_floor "the kitchen floor" is room within ground_floor at 3, 3.
  Place sink "the stone sink" is room within ground_floor at 3, 4.
  Place pantry_gate "the Pantry door" is room within ground_floor at 4, 4.
  Place pantry "the Jarl's hall in the Pantry" is room within ground_floor at 5, 4.
  Place pantry_back "the back of the Pantry" is room within ground_floor at 6, 4.
  Place kitchen_garden "the kitchen garden" is room within grounds at 0, 0.

  Passage baize_door "the baize door to the kitchen" is passage between hall_flags and kitchen_floor taking 10 minutes.
  Passage kitchen_wallway "the wall-way to the kitchen" is passage between bell_walk and kitchen_floor taking 10 minutes.
  Passage sink_rope "the rope up to the Sink" is steps between kitchen_floor and sink taking 5 minutes.
  Passage pantry_way "the way to the Pantry door" is passage between kitchen_floor and pantry_gate taking 5 minutes.
  Passage pantry_in "the Pantry door" is doorway between pantry_gate and pantry.
  Passage pantry_run "the run between the sacks" is passage between pantry and pantry_back taking 5 minutes.
  Passage dumbwaiter "the dumbwaiter" is shaft between kitchen_floor and landing taking 10 minutes.
  Thing dumbwaiter_box "the dumbwaiter" on dumbwaiter {
    State worked blocking "The dumbwaiter's box hangs in its shaft on ropes as thick as your arm. The Jarmen work the ropes from the kitchen end, and nobody rides it but by their leave.".
    State free "The dumbwaiter's box waits at the bottom of its shaft, and the Jarman on the rope nods you in.".
    Change haul "Haul yourself up the dumbwaiter's ropes, hand over hand" from worked to free needing brawn.
  }
  Rule dumbwaiter_friend when haspFriend(hasp) and state(dumbwaiter_box, worked) { Assert state(dumbwaiter_box, free). }
  Passage garden_lane "the lane round the north side of the house" is path between bs_street and kitchen_garden taking 30 minutes.

  Observe kitchen_scene at kitchen_floor when true "The kitchen of Hollins is a stone barn of a room, flagged, with a range along one wall like the front of a foundry, black and cold, its oven doors big enough to drive a cart into. A table runs down the middle that a village could shelter under, and does: there are tents under it. Along the far wall, the stone sink, high up, with a brass tap over it, and from the tap a drop forms, slowly, and falls, and forms. By the door a box of wood hangs in a shaft in the wall, on ropes: the dumbwaiter. Somebody has chalked on the flagstones, in a fair round hand: KEEP OFF THE OPEN AFTER NINE.".
  Observe kitchen_lady at kitchen_floor as ambience when at(lady, kitchen_floor) "The Lady sits at the great table eating bread and butter off a plate, very slowly, and from under the table the tents have emptied and nobody breathes.".
  Observe kitchen_cat at kitchen_floor as sign when at(bishop, kitchen_floor) and prowling() "Something grey comes round the end of the range in the dark, low and slow, and stops, with its tail twitching; and its eyes catch what light there is, two lamps the size of cartwheels, a long way up.".

  // ── The Sink and the Drip ─────────────────────────────────────────────────────────────────────────────────────────
  Relation sinkWarned(group). Relation sinkFlooded(place). Relation refugeesWatered(place).
  Observe sink_scene at sink when not sinkFlooded(hollins) "The Sink is a stone trough as big as a mill-pond, dry but for a pool at the plug-hole end where the drip falls. The drip is the only running water in the house. Round the pool a little town of buckets and gutters and wooden channels catches every drop, and a woman in an oilskin sits on a stool at the end of a plank under the tap, with a slate, and makes a mark each time it falls.".
  Observe sink_flooded at sink when sinkFlooded(hollins) "The Sink is full of water, still and grey and a fathom deep, with buckets floating in it, and planks, and a stool. The town round the drip is gone under. On the draining board, wet to the skin, the Tapwarden sits with her slate, making marks on it out of habit.".
  Person drewe "Tapwarden Drewe" at sink {
    Role "the Tapwarden of the Sink". Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Likeness "official".
    Greets "The woman in the oilskin does not look up from her slate. 'Ninety-one,' she says, as a drop falls. 'Water's by the thimble, a thimble a soul a day, entered against your name. If you've no name in the Post's register you've no thimble.' Another drop. 'Ninety-two.'".
    Greets again "'Ninety-whatever,' says Tapwarden Drewe, not looking up.".
  }
  Topic drewe_drip with drewe "Ask Tapwarden Drewe about the Drip" when true once {
    Says "'One drop a slow breath,' says Drewe. 'A barrel an hour, near enough. Six hundred souls on it.' She makes a mark. 'Tapwardens have counted it since the first drip. My mother's mother's mother. We know what the Wainscot drinks to a thimble, and we keep it fair, and nobody's died of thirst since the Drought of Ninety-eight, when the washer perished in the tap and it stopped for a week.' Another mark. 'Fair is the whole of it. Everybody a thimble. No more for the Court, no less for the grate.'".
  }
  Topic drewe_colliers with drewe "Ask Tapwarden Drewe to give the burned-out colliers water" when hearthBurned(hollins) and not refugeesWatered(hollins) once {
    Says "'They've names in the register?' says Drewe. 'Then they've thimbles.' She looks at her slate. 'They want more. Burns want water. Eighty souls on the Skirting wanting four thimbles each.' She makes a mark, and her hand is not steady. 'If I give them four, I give the Nail three, and the Nail never forgives. That's how the Drought started. That's how it always starts.' She looks at you, for the first time. 'Give me a reason to be unfair that'll hold.'".
    On discuss { Assert knows(actor, drewe_reason). }
  }
  Discovery drewe_reason "Tapwarden Drewe will give the burned colliers more than their thimble only for a reason to be unfair that will hold.".
  Topic drewe_flood with drewe "Tell Tapwarden Drewe the Lady will be running the tap" when knows(actor, drewe_reason) and not refugeesWatered(hollins) and not sinkFlooded(hollins) once {
    Says "Drewe stops with the chalk lifted. 'Running it,' she says. 'Her. The tap.' She looks up at the brass spout over her head, which is the size of a drainpipe, as though she had never considered that it was anything but the sky. 'She'll have the whole Sink full in a minute. A barrel a breath.' And then, slowly, she begins to laugh, and wipes the slate clean with her sleeve. 'Then there's no ration. There's no Drip. There's water.' She stands up. 'Give the colliers what they want. Give them all what they want. And get the Sink off the plug-hole end before she comes, every bucket.'".
    On discuss { Assert refugeesWatered(hollins). Assert sinkWarned(party). }
  }
  Rule tap_runs when day4() and hour(clock) >= 12 and at(lady, kitchen_floor) and not sinkFlooded(hollins) { Assert sinkFlooded(hollins). }
  Event tap_told within house when sinkFlooded(hollins) and sinkWarned(party) "At noon the Lady, at the kitchen table, gets up and goes to the sink and turns the tap; and the water comes down out of the brass like a river out of a cliff, white, roaring, and fills the Sink in the time it takes to say so. The Sink-folk, warned, are on the draining board with every bucket they own, and they stand there soaked in the spray, cheering, which nobody has ever heard the Sink-folk do.".
  Event tap_told_cold within house when sinkFlooded(hollins) and not sinkWarned(party) "At noon the Lady, at the kitchen table, gets up and goes to the sink and turns the tap; and the water comes down out of the brass like a river out of a cliff, white, roaring, and fills the Sink in the time it takes to say so. When she has gone back to her bread the Sink-folk come up out of it onto the draining board, coughing, and count each other, and come out two short.".

  // ── The Pantry and the Jarmen ─────────────────────────────────────────────────────────────────────────────────────
  // The Jarmen came in a hundred and forty years ago, a gang of carters and their families who had robbed a toll-house,
  // and took the Pantry, which is the Wainscot's larder: honey and dried fruit and salt and flour that have kept three
  // centuries in their crocks. They hold the pincushion too, and so the pins. Their Jarl is Hasp Tallowby.
  Observe gate_scene at pantry_gate when true "The pantry door stands an inch ajar, which is a passage a cart could go through, and across the gap the Jarmen have built a gate out of a giant's comb set on its back, its teeth for bars. Behind it, men with pins for spears.".
  Person pinmen "the Jarl's pin-men" at pantry_gate {
    Role "Jarmen, with giant's pins for spears". Ancestry human. Calling warrior. Level 2. Numbers 4. Pronouns they.
    Temperament territorial.
    Greets "The biggest of the pin-men leans on his pin. 'Well?'".
    Lair pantry_gate.
    Guards pantry_in.
    Warns "Four men behind the comb-gate bring their pins down level, eight feet of steel apiece. 'Pantry's the Jarl's,' says the biggest. 'You've business with him, say so. Or you've honey to buy, there's a hatch. Otherwise go back the way you came, and quick.'".
    Comes "The pin-men come through the comb-gate at you, pins first.".
    Pleads "'Enough,' says the biggest of them, on his knees, with his pin a yard away. 'Enough. Go on in. He'll see you. God help you.'".
  }
  Thing comb_gate "the comb-gate" on pantry_in {
    State gate_shut blocking "The comb-gate is shut across the pantry door.".
    State gate_open "The comb-gate stands open.".
  }
  Rule gate_opens when tolerates(pinmen, party) and state(comb_gate, gate_shut) { Assert state(comb_gate, gate_open). }
  Rule gate_opens_routed when (routed(pinmen) or dead(pinmen)) and state(comb_gate, gate_shut) { Assert state(comb_gate, gate_open). }
  Action ask_jarl(actor: group, site: place) "Tell the pin-men you have business with the Jarl" {
    Speaker pinmen.
    Requires able(actor) and company(actor) and at(actor, site) and at(pinmen, site) and not tolerates(pinmen, actor) and not hostile(pinmen, actor) and not toldPinmen(party).
    Time 0.
    On success { Assert toldPinmen(party). Assert tolerates(pinmen, actor). Retract warned(pinmen, actor). }
    Result "The biggest of them looks you over, and jerks his head. 'He'll see you. He sees everyone this week. Mind his boy.'".
  }
  Relation toldPinmen(group).

  Observe pantry_scene at pantry when true "The Pantry is a cave of shelves going up into the dark, and on them the stores of Hollins, three hundred years old: crocks of honey that would swallow a wine-vat, with doors cut in their sides; sacks of flour like grey hills; a ham hanging from a hook, black and hard as wood; jars of salt; a cheese that has turned to stone and been carved into a throne. The Jarmen live on the lowest shelf, among the jars, in rooms cut into the honey-crocks, and the whole place smells of honey, and mice, and men.".
  Observe pantry_poison at pantry as feature when poisonPotFull(pantry) "On a shelf behind the Jarl's throne stands a little pot with a skull scratched on its lid, the kind of skull somebody conscientious scratches, and the paste in it smells of almonds and lard.".
  Person hasp "Hasp Tallowby" at pantry {
    Role "the Jarl of the Jars". Ancestry human. Calling warrior. Level 4. Peaceable. Pronouns he. Manner grim.
    Seen when not at(pye, pantry).
    Likeness "noble".
    Greets "On the cheese throne sits a heavy man with grey stubble and a pin across his knees, eating honey off a knife. 'Ratcatcher,' he says, before you can open your mouth, so that you know he knows. 'Or not. Sit down. The rats are in the back. We've had rats in the back for a hundred years, and we've had ratcatchers for a hundred years, and none of them caught a rat.'".
    Greets again "Hasp Tallowby lifts his knife an inch off the honey, which is his greeting.".
    Sells hollins_honey_kind for 1 coin from 10.
  }
  Person wat "Wat Tallowby" at pantry {
    Role "the Jarl's son". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Seen when not at(pye, pantry).
    Likeness "child".
    Greets "A boy of eleven or so with his father's jaw is whittling a pin into a whistle. 'I go in the back,' he tells you, as if you had asked. 'Every morning before light, to look at the honey-crocks for mice. Da says I'm the best. I'm the quietest.'".
    Greets again "'I'm the quietest,' says Wat Tallowby, quietly.".
  }
  Topic hasp_lady with hasp "Ask Hasp Tallowby what he thinks of the Lady" when true once {
    Says "Hasp licks the knife. 'It's her honey,' he says. 'Her flour, her salt, her shelves. I know that. My grandad's grandad knew it when he broke in. We've eaten her pantry a hundred and forty years and she never missed it.' He points the knife at the ceiling. 'Now she's back, and she's lit the fire, and her woman's putting traps in my back pantry. Rat-traps. Jaws that'd take a child's leg off at the knee.' He sticks the knife in the cheese. 'We'll see.'".
    On discuss { Assert knows(actor, hasp_angry). }
  }
  Discovery hasp_angry "Hasp Tallowby, Jarl of the Jars, knows the Pantry is the Lady's, and hates her for the traps her woman sets in it.".
  Topic hasp_rats with hasp "Ask Hasp Tallowby whether he would pay to have the back pantry ratted" when true once {
    Says "Hasp laughs. 'Pyecroft pays you twopence a tail,' he says. 'I'll pay you three coin and all the honey you can carry for the back pantry clear, and you can sell her the tails besides.' He looks at you sideways. 'There's eight or nine of them back there, big as dogs some of them, and they bite. That's why none of your sort ever came back with a real tail.'".
    On discuss { Assert knows(actor, rats_job). }
  }
  Discovery rats_job "Hasp Tallowby will pay three coin and honey to have the rats in the back of the Pantry killed; there are eight or nine, some as big as dogs.".

  // ── The back of the Pantry: rats, and Mrs Pyecroft's trap ──────────────────────────────────────────────────────────────
  Observe back_scene at pantry_back when true "The back of the Pantry is dark: sacks gnawed open and bled out into dunes of meal, crocks with their lids off, and the droppings of rats everywhere, each the size of a plum stone, which for a rat is what they are. The honey-crocks the Jarmen live by stand along the back wall, and something has been at the nearest one.".
  Species pantry_rat "a pantry rat" like cave_hound temperament ambush described "A brown rat of the back pantry, fat on three hundred years of a giant's stores: as big as a terrier, yellow-toothed, red-eyed, fearless of anything its own size.".
  Person rats "rats" at pantry_back {
    Role "brown, as big as terriers, with eyes red in the dark". Species pantry_rat. Level 1. Numbers 2. Pronouns they.
    Temperament ambush.
    Lair pantry_back.
  }
  Relation ratted(group). Relation ratsPaid(group). Relation tailsCut(group).
  Rule rats_cleared when (dead(rats) or routed(rats)) and not ratted(party) { Assert ratted(party). }
  Action cut_tails(actor: group, site: place) "Cut the tails off the dead rats" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pantry_back) and ratted(party) and not tailsCut(party).
    On success { Assert tailsCut(party). Give real_tails to actor. }
    Result "It is not pleasant work, and you do it properly, a dozen tails on a string, the way Mrs Pyecroft will want them.".
  }
  Item real_tails "a string of rat-tails" is tail_kind at nowhere.
  Topic hasp_paid with hasp "Tell Hasp Tallowby the back pantry is clear of rats" when ratted(party) and not ratsPaid(party) once {
    Says "Hasp gets off his throne and goes and looks, himself, with a lantern, and comes back and stands in front of you, working his jaw. 'A real one,' he says. 'A real ratcatcher.' He counts three coin into your hand, and a pot of honey, and then, gruffly: 'The dumbwaiter's yours whenever you want it. Tell the boys I said.'".
    On discuss { Assert ratsPaid(party). Increase quantity(actor, gold) by 3. Give paid_honey to actor. Assert haspFriend(hasp). }
  }
  Item paid_honey "a pot of Whitbread honey" is hollins_honey_kind at nowhere.
  Relation haspFriend(group).

  // Mrs Pyecroft sets her trap on the run into the back pantry at seven on the second morning. Wat goes in before light.
  Relation watDead(group). Relation pyeSuspects(group).
  Hazard snap_trap "A spring-trap's jaws" means "Deal (2d8) physical damage to ally unless dexterity save against (13).".
  Thing pye_trap "Mrs Pyecroft's trap" on pantry_run {
    State unset "Nothing on the run between the sacks but meal and droppings.".
    State set dangerous "On the run between the sacks lies a spring-trap, its toothed jaws open as wide as a doorway, with a crust of cheese on the plate.".
    State sprung "On the run between the sacks lies a spring-trap with its jaws shut, on nothing.".
    State bloodied "On the run between the sacks lies a spring-trap with its jaws shut. Somebody has covered it with a sack. Under the sack it is dark and wet.".
    Hurts with snap_trap when set then sprung.
    Change spring "Spring the trap with a pin-shaft" from set to sprung.
    Change disarm "Ease the trap's spring and take its teeth out" from set to sprung needing trapwork.
  }
  Observe pantry_pye at pantry as sign when at(pye, pantry) "Every Jarman has vanished into the crocks. Mrs Pyecroft walks along the shelf with a lantern and her skirts held up out of the meal, looking at her trap, looking at the droppings, looking at nothing else.".
  Rule trap_seen_sprung when state(pye_trap, sprung) and changedBy(pye_trap, party) and at(pye, pantry) and at(party, pantry) and not pyeSuspects(pye)
    says "Mrs Pyecroft has seen. She stands with her lantern up and looks at the shut jaws, and then at you. 'That,' she says, 'was my trap.' She writes something in a little book from her pocket, without taking her eyes off you." { Assert pyeSuspects(pye). }
  Discovery trap_seen "Mrs Pyecroft has set a spring-trap on the run between the sacks into the back of the Pantry.".
  Observe trap_teaches at pantry as feature when state(pye_trap, set) and not knows(party, trap_seen) "Wat Tallowby goes in that way every morning before light, to look at the honey." teaches trap_seen.
  Rule trap_laid when dayN(hollins) >= 2 and hour(clock) >= 7 and state(pye_trap, unset) and not pyeTurned(pye) and not pyeGone(pye) { Assert state(pye_trap, set). }
  Rule trap_takes_wat when day2() and hour(clock) == 5 and state(pye_trap, set) and not watDead(wat) { Assert state(pye_trap, bloodied). Assert watDead(wat). Assert at(wat, nowhere). }
  Rule trap_reset when dayN(hollins) >= 3 and hour(clock) == 7 and state(pye_trap, sprung) and not pyeTurned(pye) and not pyeGone(pye) and not trapGivenUp(pye) { Assert state(pye_trap, set). Assert pyeSuspects(pye). }
  Relation trapGivenUp(group).
  Rule trap_given_up when pyeSuspects(pye) and dayN(hollins) >= 5 and not trapGivenUp(pye) { Assert trapGivenUp(pye). }
  Event wat_told within house when watDead(wat) "Before light on the third morning a scream goes through the walls of the house, high and thin, from somewhere at the back of the kitchen, and stops; and then a man's voice, roaring, which does not stop for a long time.".
  Observe pantry_mourning at pantry as sign when watDead(wat) "The Jarmen sit on the lowest shelf in silence, round something laid on a board under a sack. Hasp Tallowby sits on his cheese throne with his pin across his knees, not eating, looking at nothing.".
  Topic hasp_wat with hasp "Speak to Hasp Tallowby about his son" when watDead(wat) once {
    Says "Hasp does not look at you. 'Her trap,' he says. 'On my run. Her woman put it there and her woman goes about in her pocket.' He turns the pin over on his knees. 'She can't see. She doesn't know. I know. Everyone says it.' He looks up then, and his eyes are dry and terrible. 'She sat at her table, warm, eating cake, while my boy was in her trap. I can't hurt the woman; she's too high. I can't hurt the cat.' He stands. 'Get out of my Pantry.'".
    On discuss { Assert knows(actor, hasp_vengeance). }
  }
  Discovery hasp_vengeance "Hasp Tallowby blames the Lady for his son's death in her companion's trap, and means her harm.".
}

data/adventures/hollins/lady.kyr:
Module hollins "Behind the Wainscot" {
  // ── Miss Whitbread ─────────────────────────────────────────────────────────────────────────────────────────────────
  // Ermengarde Whitbread: three hundred and twenty, the greatest cartographer in Imbar, nearly blind, dying of her heart.
  // Until she knows the Wainscot is there she cannot be spoken to as people are; she can be watched, and kept still
  // for, and corrected, and played to, and written to, and, by someone very brave, stepped out in front of. How ready
  // she is to believe what she sees is primed(lady): a corrected chart, a letter delivered, the First Air played.
  Person lady "Miss Whitbread" at counterpane {
    Role "the Lady of Hollins, twelve times your height". Ancestry human. Peaceable. Pronouns she. Manner proud.
    Likeness "elder".
    Known as "the Lady" when not knows(party, lady_home).
    Greets "The Lady bends down out of the air until her face fills everything: a face the size of a house, lined like a chart, with eyes gone milky at the rims, peering. Her breath smells of tea and foxglove. 'There you are,' she says, and her voice is not loud; she is taking care with it, as you would take care not to blow out a candle. 'I can see you if you stand in the light. Stand in the light.' She looks, the way she has looked at every coast she ever drew: taking a bearing. 'Yes,' she says. 'Yes. I was not mistaken.'".
    Greets again "The Lady bends down out of the air, peering, until she finds you. 'There you are.'".
  }
  Measure primed(group). Measure fright(group). Relation ladyKnows(group).
  // The page offers what is done near someone as theirs, and whatever is someone's as talk with them: what is done
  // before she knows anyone is there is asked of her by queries, and comes of it by rules, so that it is the company's
  // own doing and not a conversation with someone who cannot yet be spoken to (friction.md, F3).
  Query ladyUnaware() means not ladyKnows(lady).
  Query primedReady() means primed(lady) >= 2.
  Query primedOnce() means primed(lady) == 1.
  Query primedNever() means primed(lady) == 0.
  Relation steppedOut(group). Relation honorBrought(group).
  Rule stepped_out_known when steppedOut(party) and not ladyKnows(lady) { Assert ladyKnows(lady). }
  Rule honor_brought_known when honorBrought(honor) and not honorMet(honor) { Assert ladyKnows(lady). Assert honorMet(honor). Retract following(honor, party). Assert honorWithLady(honor). }
  Rule lady_mute when talks(lady) and not ladyKnows(lady) { Retract talks(lady). }
  Rule lady_speaks when ladyKnows(lady) and not talks(lady) and not ladyDead(lady) and not poisoned(lady) { Assert talks(lady). }
  Rule lady_silent_dead when talks(lady) and (ladyDead(lady) or poisoned(lady)) { Retract talks(lady). }

  // ── Keeping still ─────────────────────────────────────────────────────────────────────────────────────────────────
  // Where she is, the Wainscot freezes. Whoever stays and moves where she can see them is glimpsed, and every glimpse
  // is, to her, her mind going: she asks Mrs Pyecroft to make it stop.
  Relation stilled(group). Relation nearLady(group). Measure nearSince(group). Measure glimpsedOn(group).
  Rule near_lady when ladyUp() and not ladyKnows(lady) and at(lady, ?p) and at(party, ?p) and not nearLady(party) and not at(?p, counterpane) { Assert nearLady(party). Set nearSince(party) to watch(clock). }
  Rule near_lady_counterpane when at(lady, counterpane) and at(party, counterpane) and not nearLady(party) and not ladyKnows(lady) and hour(clock) >= 7 and hour(clock) < 21 and ladyUp() { Assert nearLady(party). Set nearSince(party) to watch(clock). }
  Rule leave_lady when nearLady(party) and not together(lady, party) { Retract nearLady(party). Retract stilled(party). }
  Observe lady_close near lady when nearLady(party) and not stilled(party) and not ladyKnows(lady) "The floor is shaking with her footfall, her breathing; everyone of the Wainscot within sight has gone still as a stone. You had better do the same, or be gone.".
  Action keep_still(actor: group, site: place) "Keep still, as the Wainscot does, until she has gone by" {
    Description "Stand exactly where you are, and do not move, and do not breathe much.".
    Requires able(actor) and company(actor) and at(actor, site) and nearLady(actor) and not stilled(actor) and ladyUnaware().
    Time 0.
    On success { Assert stilled(actor). }
    Result "You stand stock still, as the children do in the Wainscot's game of Statues, which they learned from their grandparents, who learned it from this.".
  }
  Rule lady_glimpses when nearLady(party) and not stilled(party) and watch(clock) > nearSince(party) and glimpsedOn(lady) != dayN(hollins) and not ladyKnows(lady) and ladyUp()
    says "The Lady stops. Her head comes round, slowly, enormous, and her milky eyes go over the place where you are, and past it, and back. 'Dorothea,' she says, very quietly. 'There is something on the floor. Tell me there is nothing on the floor.' And Mrs Pyecroft's small dry voice, from her shoulder: 'Rats, Miss Whitbread. I have a man in. It will be seen to.' The Lady closes her eyes. 'Make it stop, Dorothea,' she says. 'Whatever you have to do. I cannot bear to see things.'" {
    Set glimpsedOn(lady) to dayN(hollins). Increase fright(lady) by 1.
  }

  // ── Stepping out ──────────────────────────────────────────────────────────────────────────────────────────────────
  // At her chart table, or her tea table, in the light, while she sits: someone can step out and be seen on purpose.
  // What comes of it depends on what has gone before.
  Relation daredOn(group). Measure daredDay(group).
  Query ladySitting(p: place) means at(lady, p) and ladyUp() and (at(lady, chart_table) or at(lady, tea_table)).
  Action step_out_ready(actor: group, site: place) "Step out into the light on the table, where she can see you, and speak to her" {
    Grave "Whatever she does, she will have seen you.".
    Requires able(actor) and company(actor) and at(actor, site) and ladySitting(site) and ladyUnaware() and primedReady().
    Time 1.
    On success { Assert steppedOut(actor). }
    Result "You walk out into the light on the table and stand there and look up. Her hand stops. She bends, slowly, until her face is close enough that you can see the lines of it like the contours on a map, and her breath comes over you warm, and her eyes, milky at the rims, find you, and stop. 'You,' she says. 'Somebody has been trying to tell me something, in my own house, for days. Was it you?' And when you answer, she shuts her eyes, and opens them, and you are still there. 'I am not ill,' she says. 'I am not ill, Dorothea. Go and walk in the garden.'".
  }
  Action step_out_doubt(actor: group, site: place) "Step out into the light on the table, where she can see you, and speak to her" {
    Grave "Whatever she does, she will have seen you.".
    Requires able(actor) and company(actor) and at(actor, site) and ladySitting(site) and ladyUnaware() and primedOnce() and daredDay(actor) != dayN(hollins).
    Time 1.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert steppedOut(actor). }
    On failure { Set daredDay(actor) to dayN(hollins). Increase fright(lady) by 1. }
    Result "You walk out into the light and speak up at her, plainly, about the letter, about the chart, about the Laceys, and she bends down, slowly, until one eye fills the window like a lamp behind wet glass, and stays there. 'Go on,' she says, in a whisper that stirs your hair. 'Go on. I am listening. I am trying very hard to be sure that I am listening.' And at the end she puts out one finger, as long as a boat, and touches the table beside you, very gently, and you feel the table take her weight. 'Real,' she says. 'You are real.'".
    Otherwise "She sees you. She makes a sound you will not forget, a long breath in, like someone at the edge of water, and turns her face away. 'No,' she says. 'Dorothea, no, I will not, take it away,' and Mrs Pyecroft's hand comes down out of nowhere with a napkin like a sail, and you have to run for the edge of the table and the rope.".
  }
  Hazard swept "A giant's hand, sweeping" means "Deal (1d6) physical damage to ally unless dexterity save against (12).".
  Action step_out_cold(actor: group, site: place) "Step out into the light on the table, where she can see you, and speak to her" {
    Grave "Nothing has prepared her for you. Whatever she does, she will have seen you.".
    Requires able(actor) and company(actor) and at(actor, site) and ladySitting(site) and ladyUnaware() and primedNever() and daredDay(actor) != dayN(hollins).
    Time 1.
    Resolve check(actor, persuasion, dc_formidable).
    On success { Assert steppedOut(actor). }
    On failure { Set daredDay(actor) to dayN(hollins). Increase fright(lady) by 2. Assert strikes(swept, actor). }
    Result "You walk out into the light and shout up at her, and by some miracle of nerve and timing you say the one thing: Honor Lacey's name. She goes still. She bends, and bends, until her eye is all there is, and then she says, in a voice like a door opening in another house: 'Honor?' And you have to tell her: no; but Honor's people, still. She listens. Her hand is shaking on the table so that the cups chatter. 'I am going to believe you,' she says at last, with enormous care, the voice of a woman stepping out onto ice. 'I am going to believe you, and if I am mad, I shall at least be mad in company.'".
    Otherwise "She sees you, and screams: an old woman's scream, but as big as a house, and the table jumps, and the cup goes over and a wave of tea comes across the cloth at you, and then her hand, sweeping blindly, the size of a cart, and you are struck and flung and rolling, and the edge is there, and the rope.".
  }
  // Dame Honor Lacey, brought before her.
  Relation honorComes(group). Relation honorMet(group).
  Query ladyAwakeAt(p: place) means at(lady, p) and ladyKnows(lady) and not ladyDead(lady).
  Topic honor_go with honor "Ask Dame Honor Lacey to come with you to the Lady" when knows(actor, diary_laceys) and (primed(lady) >= 1 or knows(actor, mother_letter) or ladyKnows(lady)) and not honorComes(honor) and not honorMet(honor) once {
    Says "You tell her what the diary says. Honor who is nine, who is my best friend. Dame Honor hears it standing, with one hand on the back of her chair. Then she sits down, which you have not seen her do while anyone else stood. 'My best friend,' she says. 'It says that. In her hand.' She looks at the parlour, the eight chairs, the clock. Then she rings for Mr Ambry. 'Mr Ambry,' she says, 'fetch the chain of office, and my good gloves, and the Address. We are going out.' Mr Ambry drops the bell.".
    On discuss { Assert honorComes(honor). Assert acceptsEscort(honor, actor). Assert following(honor, actor). }
  }
  Action bring_honor(actor: group, site: place) "Bring Dame Honor Lacey forward into the light, before the Lady" {
    Requires able(actor) and company(actor) and at(actor, site) and following(honor, actor) and (ladySitting(site) or ladyAwakeAt(site)) and not honorMet(honor).
    Time 2.
    On success { Assert honorBrought(honor). }
    Result "Dame Honor walks out into the light alone, in her handkerchief gown and her chain of buttons, and stops, and looks up. Behind her Mr Ambry clears his throat and begins, in a voice that has waited forty years: 'MOST HIGH AND GRACIOUS DAUGHTER OF HOLLINS,' and gets as far as THE PANTRY before Dame Honor says, without turning round, 'Thank you, Mr Ambry,' and he stops. The Lady has bent down. Her eye, close, would not fit the parlour of the Small House. 'Who are you?' she says, as Dame Honor had known she would; and Dame Honor answers, as she had not known she could: 'Honor Lacey. Not the one you knew. Her great-great-great-great-great-granddaughter. We kept your house for you, Miss Whitbread. We kept it ready.' And the Lady puts her face down on her arms on the table, slowly, like a hill settling, and weeps, and Dame Honor stands in the light beside her enormous grey hair and, after a while, reaches out a gloved hand and lays it on a strand of it.".
  }
  Relation honorWithLady(group).
  Rule honor_home when honorWithLady(honor) and not together(honor, lady) and not at(honor, small_house_parlour) and not following(honor, party) { Assert at(honor, small_house_parlour). }
  Observe honor_by_lady near lady when honorWithLady(honor) and together(honor, lady) and not ladyDead(lady) "Near the Lady's hand, on a doll's chair somebody has carried down from the Small House, Dame Honor Lacey sits in her handkerchief gown, talking, and the Lady bends her enormous head to listen.".

  // ── She speaks to the walls ───────────────────────────────────────────────────────────────────────────────────────
  // The first dusk after she knows, she winds the Clock and does not go back to the fire: she stands in the Hall and
  // speaks to the skirting. The Wainscot comes out onto the floor, by daylight, from then on.
  Relation ladyAddressed(group). Relation wainscotOut(place).
  Rule lady_addresses when ladyKnows(lady) and at(lady, clock_foot) and hour(clock) >= 18 and not ladyAddressed(lady) and not ladyDead(lady) { Assert ladyAddressed(lady). Assert wainscotOut(hollins). }
  Event address_told within house when ladyAddressed(lady) and jossTold(lady) "At six, when she has wound the Clock, she does not go back to the drawing room. She stands in the middle of the Hall with her candle, holding the Bishop's collar in her other hand, and turns slowly round, looking at the skirting, and speaks; not loud. 'I am told you are there. I lit fires. I let my companion lay traps. My cat killed a boy called Joss Tenter, who came out to see me.' A long breath. 'I would like to see you. Come out, if you will.' Nothing moves on the flagstones. Then a door in the skirting opens, low down by the drift, and a thin woman with a black ribbon on her sleeve comes out onto the stone, alone, and walks out into the middle of the Hall, into the candlelight, and stands there with her chin up and her fists shut, and looks at the Lady; and the Lady, very slowly, kneels down on the floor of her own Hall to see her better. Then the doors are opening all along the skirting.".
  Event address_told_plain within house when ladyAddressed(lady) and not jossTold(lady) "At six, when she has wound the Clock, she does not go back to the drawing room. She stands in the middle of the Hall with her candle and turns slowly round, looking at the skirting, and speaks; not loud. 'I am told you are there. I lit fires. I let my companion lay traps. I am sorry.' A long breath. 'I would like to see you. Come out, if you will.' Nothing moves on the flagstones. A cress-stalk bends in the draught. Then a door in the skirting opens, and a child comes out, and is snatched back, and comes out again holding her mother's hand; and then the doors are opening all along the skirting, and the Lady kneels down on the floor of her own Hall to see them better.".
  Observe hall_out at hall_flags as feature when wainscotOut(hollins) and not dark() and not ladyDead(lady) "People are crossing the flagstones in daylight now, unhurried, with baskets; children are racing on the cracks; and nobody stops when the floor shakes, only looks up and lifts a hand.".
  Topic mab_out with mab "Ask Mab Tenter why she was the first to go out" when wainscotOut(hollins) and jossTold(lady) once {
    Says "Mab Tenter ladles for a while before she answers. 'She said his name,' she says. 'Out loud, in the Hall, in front of everybody. Joss Tenter. Nobody's said his name out loud since the funeral; they say the boy, or Mab's lad.' She puts the ladle down. 'So I went out. I wanted her to see who his mother was.' She looks at the black ribbon on her sleeve. 'She got down on her knees on the floor. As big as a hill, and she got down on her knees.' Then, briskly, because the broth is boiling: 'It doesn't stop it. I said I wanted it to stop. It doesn't stop. But it's been said.'".
  }

  // ── What can be said to her, once she knows ───────────────────────────────────────────────────────────────────────
  Relation smallHouseLit(group).
  Topic lady_small_house with lady "Ask the Lady to come up to the Nursery and look in at the Small House" when ladyKnows(lady) and honorMet(honor) and not smallHouseLit(lady) and not ladyDead(lady) and not bedridden(lady) once {
    Says "She comes up the Stair at dusk with her candle, a step at a time, and kneels on the nursery floor, which takes a long time, and the floor groans. The Court has lit every candle in the Small House, the chandelier in the front hall and the lamps in all three storeys, and opened every door; and the Lady puts her face down to the parlour window, as she must have done three hundred and twelve years ago, and looks in. Dame Honor is sitting at the round table with the cloth, in the good gloves, pouring tea into a cup that fits her hand. She looks up at the window, which is entirely filled by an eye, and raises the cup. And the Lady, kneeling on the floor of her nursery in her nightgown, with her candle, says through the glass, in a voice you could not hear across a room: 'Oh, it is all just as it was. You have kept it all just as it was.' 'No,' says Dame Honor, quite clearly. 'We have mended everything. Twice.'".
    On discuss { Assert smallHouseLit(lady). }
  }
  Topic lady_mind with lady "Ask the Lady why she thought it was her mind" when ladyKnows(lady) once {
    Says "'Because I was told so,' says the Lady. 'By my mother, and by Doctor Hume, who measured my head with calipers, and by my aunt, who was kind about it.' She is quiet. 'I was eight. I believed them. What else does a child do?' She looks at the window. 'So I learned to measure everything. Every coast, every bay, every height, to the inch, with chain and staff and theodolite, and wrote the figures on the chart beside every line, so that nobody, ever again, could tell me I had imagined it.' She almost laughs. 'Three hundred years, and I have charted every shore in Imbar, and never this house. I did not dare. I came home to draw it before I died, and the first night I heard you in the walls, and I thought: there. It has come for me at last, the thing Mama said.'".
  }
  Topic lady_who with lady "Tell the Lady who lives in her walls" when ladyKnows(lady) once {
    Says "You tell her. The Slot and the Post. The Skirting and the Nail. The Hearth in her grate, the Keys in her piano, the Readers on her bottom shelf walking her encyclopaedia, the Jarmen in her pantry, the Winders in her clock, the Court in her doll's house. Six hundred. The Lady listens with her chin on her hand and her eye very close, and stops you every so often to ask a measurement: how wide the Skirting, how deep the grate. At the end she sits back. 'In my walls,' she says. 'All of them. All this time.' Then: 'And I have been lighting fires.'".
    On discuss { Assert ladyToldAll(lady). }
  }
  Relation ladyToldAll(group).
  Observe chart_drawing at chart_table as feature when ladyToldAll(lady) and not ladyDead(lady) "Along the Skirting on her chart, beside the big black lines of the Wainscot, there are new figures in her own fine hand: widths, depths, the height of the Nail. She has been measuring what she was told.".
  Topic lady_hearth with lady "Tell the Lady what her fire did to the Hearth" when ladyKnows(lady) and hearthBurned(hollins) and not collierDead(hollins) and not hearthAtoned(lady) once {
    Says "The Lady hears it with her hand over her mouth: a town in her grate, eighty-three people, out of it by a quarter to nine because somebody told them. 'By a quarter of an hour,' she says. 'I measured my whole life by less.' She looks at the grate across the house, as if she could see it through the walls. 'Then the fire goes out. Dorothea will let it go out; I have a shawl. They may have the grate back, and the coal, all of it. And when I am gone they may light it themselves, at whatever size they like.'".
    On discuss { Assert hearthAtoned(lady). Retract ladyCursed(hollins). }
  }
  Topic lady_hearth_dead with lady "Tell the Lady what her fire did to the Hearth" when ladyKnows(lady) and collierDead(hollins) and not hearthAtoned(lady) once {
    Says "The Lady hears it with her hand over her mouth. Then she asks their names. You tell her what is written on the brick, and she says each one after you, slowly, carefully, as if she were lettering it on a chart: and when you come to BET COLLIER, FOREWOMAN, she stops, and asks what she was like, and you tell her, and she says the name again. 'Then the fire goes out,' she says at last. 'Dorothea will let it go out. I have a shawl.' She does not look at the grate. 'They may have it back, and the coal, all of it. It is not a thing I can give. It is only a thing I can stop taking.'".
    On discuss { Assert hearthAtoned(lady). Retract ladyCursed(hollins). }
  }
  Relation hearthAtoned(group).
  Rule hearth_let_out when hearthAtoned(lady) and hearthBurned(hollins) and state(fire, blazing) { Assert state(fire, banked). }
  Rule hearth_stays_out when hearthAtoned(lady) and hearthBurned(hollins) and not fireOut(hollins) { Assert fireOut(hollins). }
  Relation fireOut(place).
  Topic lady_traps with lady "Tell the Lady about Mrs Pyecroft's traps" when ladyKnows(lady) and not watDead(wat) and not trapsLifted(lady) once {
    Says "'Traps,' says the Lady. 'Dorothea's rat-traps. On the pantry run.' You tell her who goes in that way every morning before light, and what a rat-trap does to a hand. She is quiet. Then she raises her voice, and somewhere a window rattles: 'Dorothea. Every trap in this house. Today.'".
    On discuss { Assert trapsLifted(lady). Assert trapGivenUp(pye). }
  }
  Topic lady_traps_wat with lady "Tell the Lady about Mrs Pyecroft's traps, and Wat Tallowby" when ladyKnows(lady) and watDead(wat) and not trapsLifted(lady) once {
    Says "'Traps,' says the Lady. 'Dorothea's rat-traps.' You tell her about Wat Tallowby: eleven, the quietest, the honey-crocks before light. She says nothing. Then she says, 'Eleven,' and then, 'Bring me his father, if he will come. I cannot go to him. Tell him I will sit as still as I can.' And then, in a voice that once sent survey crews up cliffs: 'Dorothea. Every trap in this house. Today.'".
    On discuss { Assert trapsLifted(lady). Assert trapGivenUp(pye). }
  }
  Relation trapsLifted(group).
  Rule traps_up when trapsLifted(lady) and state(pye_trap, set) { Assert state(pye_trap, sprung). }
  Topic lady_sulphur with lady "Tell the Lady what Mrs Pyecroft means to do with the sulphur" when ladyKnows(lady) and knows(actor, smoking_planned) and not ladyForbids(lady) once {
    Says "The Lady goes grey. 'Sulphur,' she says. 'In the walls.' She sits with her hand flat on the table. 'I told her to make it stop,' she says. 'I said, whatever you have to do.' She closes her eyes. 'Then I have been the monster under the bed, all this week, in my own house.' And then, opening them: 'There will be no sulphur. Not while I live, and I shall put it in writing for after.'".
    On discuss { Assert ladyForbids(lady). }
  }
  Relation ladyForbids(group).
  Topic lady_paper with lady "Tell the Lady what the paper she signed in the spring really was" when ladyKnows(lady) and knows(actor, pye_ledger) and not saleRevoked(lady) once {
    Says "'A letter to my bank,' says the Lady slowly. 'She read it to me. I signed where she put my finger.' She is silent. Then, without raising her voice at all: 'Dorothea.' Mrs Pyecroft comes out from behind the inkwell, very small and very straight, and stands in the light, and does not look away. 'Eleven years without wages,' says the Lady. 'Is that in your ledger too?' 'Yes, Miss Whitbread.' 'Then why did you not ask me?' And Mrs Pyecroft's face does something you did not expect: it crumples, like a child's. 'You never asked me anything,' she says. 'Twenty-two years. You never once asked me anything at all.' The Lady looks at her: at the small black dress, the pen, the ink on the second finger. 'No,' she says. 'I did not.' Then: 'The paper is void, and I shall say so to whoever asks. And you shall have your four hundred and forty crowns, Dorothea, and a cottage, and I am sorry.'".
    On discuss { Assert saleRevoked(lady). Assert pyeTurned(pye). }
  }
  Relation saleRevoked(group).
  Topic lady_mother with lady "Give the Lady her mother's letter, from the vault" when ladyKnows(lady) and carries(actor, mama_letter) once {
    Says "She knows the hand before she has the glass up. She sits with the letter unread in her lap while the light moves across the chart. Then she reads it. You watch her read it: the glass going along the lines, and stopping, and going back, and stopping. I saw her. When she reaches the end she folds it, very precisely, in its old folds, and holds it against her chest with both hands, the way you would hold a small animal that might get away. 'She saw,' she says. 'She saw, and she sent me away so that no one would look at me the way they would have looked at her.' Her face is wet. 'And she left the grating open. Every winter.' She is quiet. 'Three hundred years I thought she was the one person in the world who knew I was lying.' And then, at last, she laughs, a real laugh, enormous, so that the windows ring. 'Oh, Mama. You coward. You dear.'".
    On discuss { Spend mama_letter from actor. Assert motherDelivered(lady). }
  }
  Relation motherDelivered(group).
  Relation jossTold(group).
  Topic lady_joss with lady "Tell the Lady about Joss Tenter, and her cat" when ladyKnows(lady) and knows(actor, joss_taken) and not jossTold(lady) once {
    Says "She listens without moving: the first night, the boy of nine who went out onto the flagstones to see her because everybody had said all his life that one day she would come, and what the Bishop did with him until morning. When you have finished she says, 'Joss,' as if she were writing it down. 'Joss Tenter.' And then, very low: 'I heard it. That first night. I heard something crying in the Hall and I put the pillow over my head, because I thought it was me.'".
    On discuss { Assert jossTold(lady). }
  }
  Topic lady_cat with lady "Tell the Lady what her cat does at night" when ladyKnows(lady) and not belled(bishop) once {
    Says "'The Bishop?' says the Lady, appalled. 'Oh, the Bishop. He lost his bell in the carriage; I have it in my reticule.' She feels in a bag by her chair, and brings out a silver bell you could bathe a child in, and rings it, and somewhere upstairs a cat lifts its head. 'He shall wear it night and day. And he shall sleep shut in my room.' She puts the bell away. 'Your Court held a council about belling him, I suppose,' she says, and when you tell her yes, she laughs until she has to hold the table.".
    On discuss { Assert belled(bishop). Assert catShutIn(bishop). }
  }
  Relation catShutIn(group).
  Rule cat_shut_in when catShutIn(bishop) and not catAway(bishop) and prowling() { Assert catAway(bishop). }
  Topic lady_regiment with lady "Tell the Lady that her Tin Regiment is still fighting" when ladyKnows(lady) and knows(actor, regiment_orders) and not standDown(regiment) once {
    Says "'My soldiers?' The Lady's whole face changes; for a moment, under the lines, she is eight. 'Captain Ordinance? Still?' You tell her: three hundred and twelve years; no little person taken by a mouse; the winder in the ark. She is quiet. 'I told them never to stop,' she says. 'Children say never.' She takes a sheet of paper and writes on it, large, and blots it, and holds it out to you, pinched in two fingers like a sail. 'Pin it on the gate. They will know my hand.' It says: THE WAR IS OVER. YOU MAY REST. WITH LOVE AND THANKS, E. W.".
    On discuss { Assert standDown(regiment). Assert tolerates(regiment, party). Assert peaceable(regiment). }
  }
  Topic lady_clock with lady "Tell the Lady that the Winders kept her clock" when ladyKnows(lady) and knows(actor, tobit_wants) and not tobitHonored(tobit) once {
    Says "'Kept it?' You tell her about the Winders: two hundred years of oil and no winding, the Day of the Going, Prior Tobit's benches under the weights. The Lady listens with her eyes shut. 'I stopped it,' she says. 'With my finger, going out. So that it would still be today.' She opens her eyes. 'I had forgotten. Three hundred years, and I had forgotten that, and they remembered it for me.' She is quiet a moment. 'Tell the Prior he may wind it now. Tell him, from me, that it is today.'".
    On discuss { Assert tobitHonored(tobit). }
  }
  Relation tobitHonored(group).
  Topic lady_corwen with lady "Ask the Lady about Corwen" when ladyKnows(lady) and letterRead(lady) once {
    Says "'Corwen Ashgrove,' says the Lady. 'The Ashgroves had the next valley. He was slow. Everybody said so: slow to speak, slow to laugh, slow to grow; he was a head shorter than me at twelve.' She smiles. 'He said he would wait at the stone on the moor. I never had his letter, until this week. Three hundred years I thought he had not written.' She looks out of the window, toward the moor. 'There is a stone up there that the village says is a giant who sat down to wait. I always thought it was a story. I thought most things were stories.' She is quiet. 'I have written to him. If it is him, I should like him to know I came home.'".
  }
  Topic lady_house with lady "Ask the Lady what will become of Hollins when she is gone" when ladyKnows(lady) and (knows(actor, concern_heard) or knows(actor, sale_rumour) or knows(actor, pye_ledger)) and not willWanted(lady) once {
    Says "'There are no Whitbreads,' says the Lady. 'There is a cousin in Sabine's country who would sell it for its stone before I was cold.' She looks round the room, at the shelves, at the dark where the walls are. 'And there are six hundred people who have lived in it longer than I did, and kept it, and kept my clock.' She sits up. 'Then I shall make a will. A proper one, in my hand or one I own, witnessed, lodged. Find me a notary, and somebody to write large. My hand shakes.'".
    On discuss { Assert willWanted(lady). }
  }
  Relation willWanted(group). Relation willMade(group). Relation willLodged(group). Relation deedLodged(group).
  Topic saltash_come with saltash "Ask Mr Salcombe to come into Hollins with you, to witness the Lady's will" when willWanted(lady) and not willMade(lady) and not following(saltash, actor) once {
    Says "Mr Salcombe is putting on his coat before you have finished. 'Her will,' he says. 'Hers. In the house.' He takes his pen-case, a stick of wax, his seal, and, after a moment's thought, his hat. 'My clerk will be the second witness; he's in the back pretending to copy. Toller!' A youth with ink on his nose appears. 'Lead on,' says Mr Salcombe. 'I have lived on her doorstep fifty-one years. Lead on.'".
    On discuss { Assert acceptsEscort(saltash, actor). Assert following(saltash, actor). }
  }
  Topic lady_will with lady "Ask the Lady to make her will now, with Mr Salcombe to witness" when ladyKnows(lady) and willWanted(lady) and not willMade(lady) and following(saltash, actor) and (travelsWith(sorrel, actor) or pyeTurned(pye)) once {
    Says "It is done at the Lady's table, in the window light. Mr Salcombe stands on the inkwell's rim to read the forms aloud; the Lady says each sentence after him, slowly, in her enormous careful voice; and the writing is done large, walked across a sheet of her paper with a broom, in a hand she has looked at and owned as hers: I, ERMENGARDE WHITBREAD OF HOLLINS, BEING OF SOUND MIND, which makes her laugh, LEAVE THE HOUSE AND LANDS OF HOLLINS, AND ALL IN IT, TO THE PEOPLE WHO LIVE IN ITS WALLS, IN COMMON, FOR EVER. She signs it with the mast of a pen, a signature as long as a street. Mr Salcombe and Toller sign under it, very small. Then Mr Salcombe rolls it, which takes all three of you, and seals it. 'Lodged,' he says, 'as soon as I am down the ladder.'".
    On discuss { Assert willMade(lady). Assert willLodged(lady). Retract following(saltash, actor). Assert at(saltash, saltash_office). }
  }
  Topic saltash_deed with saltash "Give Mr Salcombe the deed of Hollins, to lodge it in his strongbox" when carries(actor, deed) and not deedLodged(party) once {
    Says "Mr Salcombe takes the roll in his arms like a man taking a sleeping child, and has to sit down under it. 'Hollins,' he reads, from the seal. He gets up and unlocks his strongbox and puts the deed in it, which fills it, so that he must take out three other men's wills and put them on the desk. He locks it. 'It lies with me,' he says, 'until whoever has the right to it comes for it.' He puts the key on his watch-chain.".
    On discuss { Spend deed from actor. Assert deedLodged(party). }
  }
}

data/adventures/hollins/library.kyr:
Module hollins "Behind the Wainscot" {
  // ── The Library ───────────────────────────────────────────────────────────────────────────────────────────────────
  // Off the Hall to the south. The Readers live on the bottom shelf of the west case, among the folios, and read a
  // giant's books by walking along the lines. The Lady's chart table stands in the south window, where the light is;
  // on the sill outside the glass, in the window-boxes, the Pennocks grow cress, and this week, for the first time in
  // three hundred years, lettuces.
  Place library_floor "the Library floor" is room within ground_floor at 1, 3.
  Place readers_shelf "the Readers' shelf" is room within ground_floor at 0, 3.
  Place chart_table "the chart table" is room within ground_floor at 1, 4.
  Place sill "the Library windowsill" is room within ground_floor at 2, 4.

  Passage library_door "the Library door" is passage between hall_flags and library_floor taking 10 minutes.
  Passage library_wallway "the wall-way to the Library" is passage between skirting and readers_shelf taking 20 minutes.
  Passage shelf_ladder "the Readers' ladder" is steps between library_floor and readers_shelf.
  Passage table_rope "the knotted rope up the chart table" is steps between library_floor and chart_table taking 10 minutes.
  Passage sill_way "the sash-cord up to the sill" is steps between chart_table and sill taking 5 minutes.

  Observe library_scene at library_floor when true "The Library: cases of books going up into the dark on every side like the walls of a gorge, their spines lettered in gold you could stand inside. One book has fallen, long ago, and lies open on the floor like a field ploughed in black furrows; children are playing on it, hopping from word to word. In the south window, in a long slant of daylight, stands a table as tall as a barn, with a rope knotted up one leg.".
  Observe readers_scene at readers_shelf when true "The bottom shelf of the west case is a street of books, folios as tall as houses standing shoulder to shoulder, and the Readers live between them. Lanterns hang from the bookmarks. A ladder leans against an open volume on a lectern made of a giant's book-rest, and on its page, far up, a woman with a lantern walks slowly along a line of print, stops, writes in a ledger, walks on. A painted board says VOLUME M. MAGIC TO MANDRAKE. DAY 14,402.".
  Observe chart_scene at chart_table when true "The top of the chart table: a plain of green baize, and spread across most of it, held down at the corners with books, a sheet of paper that goes on like a field in stubble: a chart, in ink, of a house. You can walk on it. Its walls are lines as wide as your hand, drawn with a ruler, measured to a hair, with figures written along them in a big fine hand; its rooms are labelled HALL, DRAWING ROOM, LIBRARY. In the corner, a compass rose like a cartwheel, and the words HOLLINS, FROM MEMORY AND MEASUREMENT, E. W. An inkwell stands by it the size of a cistern, and a pen as long as a mast.".
  Observe chart_lady at chart_table as ambience when at(lady, chart_table) "The Lady sits over the chart with a glass as big as a millpond held up to one eye, and the light comes through it and moves on the paper like a sun. She draws a line, slowly, with the mast of a pen, and stops, and sits a long time without drawing anything. Her breath goes over the table like a wind.".
  Observe sill_scene at sill when true "Outside the glass, on the stone sill of the Library window, the window-boxes: long troughs of earth the size of fields, and in them, in rows, cress, and radishes, and peas up string. A family of dwarves with their sleeves rolled is working along them. Beyond the sill there is nothing but a drop and the whole of the Hollins country, moor and village and sky.".
  Observe sill_thaw at sill as feature when dayN(hollins) >= 3 "In the end box, where the sun is warmest off the glass, lettuces have come up, pale green and enormous, and the Pennocks keep stopping to look at them.".

  // ── The Readers ───────────────────────────────────────────────────────────────────────────────────────────────────
  Person gideon "Gideon Lamb" at readers_shelf {
    Role "the Master of the Readers". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Likeness "scholar".
    Greets "A small grey man in spectacles mended with thread looks up from a ledger. 'Quietly,' he says. 'Mistress Haddow is on Mandragora, and she has been on it a week.' He takes the spectacles off. 'You'll be wanting the Child's book. Everybody wants the Child's book this week.'".
    Greets again "Gideon Lamb puts a finger on his place in the ledger before he looks up.".
  }
  Topic gideon_reading with gideon "Ask Gideon Lamb how the Readers read" when true once {
    Says "'On foot,' says Gideon. 'A giant's line of print is forty yards. We walk it, with a lantern, and copy it fair, a line at a time, into our own hand, and bind it.' He pats the ledger. 'The Readers have copied fourteen volumes of the Whitbread Encyclopaedia in a hundred and sixty years. We are on M. It has been M for forty years.' He sighs. 'MAGIC, as you'd expect, was long. MAN was very long.'".
  }
  Topic gideon_book with gideon "Ask Gideon Lamb about the Child's book" when true once {
    Says "'Her diary,' says Gideon. 'A child's commonplace book, found in the doll's house attic when my great-grandfather was a boy. Hers. The winter she hid the Laceys.' He takes a thin bound copy from a shelf. 'The original is a block of paper the size of a hayrick, and lives in the Small House, and Dame Honor will not have it moved. This is our fair copy. Read it here, if you like; it doesn't leave the shelf.' He hesitates. 'It is short. The last page is the shortest.'".
    On discuss { Assert knows(actor, copy_offered). }
  }
  Discovery copy_offered "The Readers keep a fair copy of the Child's diary, from the winter she hid the Laceys, and will let it be read on their shelf.".
  Action read_copy(actor: group, site: place) "Read the Readers' fair copy of the Child's diary" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, readers_shelf) and knows(actor, copy_offered) and not readCopy(party).
    Time 3.
    On success { Assert readCopy(party). Assert knows(actor, diary_laceys). Assert knows(actor, diary_clock). }
    Result "It is a child's book, copied fair in a careful grown-up hand that keeps the child's spelling. Most of it is about ponies and an aunt. Then, in the winter: I have found some little people in the coal-hole. They are called the Laceys, a father, a mother, Honor who is nine, and two small ones. They were starving. I have put them in my dolls house which is EXACTLY their size, Mama would say that is a coincidence but I think it was meant. Then weeks of them: what they eat (a crumb is a loaf), the song she taught them, Honor who is her best friend, Ned the father who mended the dolls house clock. Then: Mama has found the bed. Mama says there are no little people and I am a liar or ill, and Doctor Hume says ill. They are sending me to Aunt Sabine. I have told Honor to hide in the walls till I come home. And the last page, in bigger letters, pressed hard: I have stopped the hall clock with my finger so that it will still be today when I come home.".
  }
  Relation readCopy(group).
  Discovery diary_laceys "In her diary the Child wrote that she found the Laceys starving in the coal-hole and hid them in her doll's house, which was exactly their size; that Honor Lacey, who was nine, was her best friend; that she taught them a song; and that when her mother found the doll's bed, Doctor Hume said she was ill, and she was sent to her Aunt Sabine.".
  Discovery diary_clock "The last page of the Child's diary says: I have stopped the hall clock with my finger so that it will still be today when I come home.".

  // ── Sorrel Haddow ───────────────────────────────────────────────────────────────────────────────────────────────────
  // A young Reader who has taught herself to write a giant's hand, at a giant's size, with a broom and a bucket of
  // ink on the Library floor at night. She wants to speak to the Lady more than she has ever wanted anything.
  Person sorrel "Sorrel Haddow" at readers_shelf {
    Role "a Reader of the Library". Ancestry half_elf. Calling bard. Level 2. Peaceable. Pronouns she. Manner cheerful.
    Likeness "scholar".
    Greets "A young woman comes down the ladder off the open volume two rungs at a time with ink up to her elbows and a lantern in her teeth, which she takes out to say: 'You came in by the Slot. This week. You're from outside.' She looks at you as if you were a page. 'Have you seen her? Close? Have you heard her talk?'".
    Greets again "Sorrel Haddow comes down the ladder at once, wiping ink off her hands onto her skirt.".
    Joins "Sorrel Haddow takes a broom out from behind a folio, and a bucket, and a lantern, and stands with all three as if she had been waiting a long time to be told she could go.".
    Remarks at chart_table "Sorrel kneels on the chart and runs her hand along one of its lines, very lightly, the way you would touch the face of somebody asleep. 'Look how straight,' she says. 'She can barely see, and look how straight.'".
    Remarks at small_house_hall "Sorrel stares at the front hall of the Small House, its chandelier and its painted stair. 'She made all this,' she says. 'For them. When she was eight.'".
  }
  Topic sorrel_want with sorrel "Ask Sorrel Haddow what she wants" when true once {
    Says "Sorrel sits down on the bottom rung. 'To talk to her,' she says. 'That's all. That's everything. I've read her books since I was six. I've read her encyclopaedia and her mother's recipes and her father's sermons and her diary, and every one of them was written by somebody who could never hear me answer.' She shows you her hands, black with ink. 'I've taught myself her hand. Big. With a broom, on the floor, at night, so it's a hand she could read without her glass. I've written the alphabet across the Library floor four hundred times.' She looks at you. 'Gideon says the Readers read. They don't write back. I want to write back.'".
    On discuss { Assert knows(actor, sorrel_writes). }
  }
  Discovery sorrel_writes "Sorrel Haddow, a young Reader, has taught herself to write the Lady's hand at the Lady's size, with a broom and a bucket of ink, so that the Lady could read it without her glass. She wants to write back.".
  Topic sorrel_chart with sorrel "Tell Sorrel Haddow about the Lady's chart" when knows(actor, chart_known) and knows(actor, sorrel_writes) once {
    Says "Sorrel goes very still. 'A chart,' she says. 'Of the house. With the walls drawn single.' She stands up. 'She doesn't know there's anything inside them. She doesn't know about the Skirting, or the Nail, or the Hearth, or the Small House. She's drawing her home and leaving us out.' Her face changes. 'Then we draw ourselves in. At night, while she's abed. In her hand, on her chart, so she finds it at nine. That's not shouting at her. That's,' she searches for it, 'that's a correction. She's a mapmaker. She'll have to look at a correction.'".
    On discuss { Assert knows(actor, chart_plan). Assert willing(sorrel, actor). }
  }
  Discovery chart_plan "Sorrel Haddow would draw the Wainscot into the Lady's chart at night, in the Lady's hand, so that she finds it in the morning: a mapmaker must look at a correction.".
  Discovery chart_known "The Lady is drawing a chart of Hollins from memory and measurement, at the table in the Library window, every morning: walls drawn single, with nothing inside them.".
  Observe chart_teaches at chart_table as feature when state(lady_chart, blank) and not knows(party, chart_known) "She is mapping her own house, from memory, and it is unfinished." teaches chart_known.

  Relation sorrelSpoke(group). Relation sorrelStays(group).
  Topic sorrel_lady with lady "Stand aside, and let Sorrel Haddow speak to the Lady" when ladyKnows(lady) and travelsWith(sorrel, actor) and not sorrelSpoke(sorrel) once {
    Says "Sorrel steps out into the light with ink to her elbows and her broom in her hand like a crozier, and opens her mouth, and nothing comes out. Twenty years of reading; nothing. The Lady bends down, peering. 'You are the one who writes my hand,' she says. 'I can tell. You lean on the downstrokes as I did at your age.' And Sorrel, who had meant to ask her about the founding of Hollins and her mother's sermons and the Whitbread charts, says, in a small voice: 'What comes after Mandragora?' The Lady stares at her. Then she laughs, enormously, so that the inkwell rings. 'Mandrake,' she says. 'Then Manners. The article on Manners is very long and entirely wrong. Shall I tell you why?' And she does, and Sorrel sits down on the compass rose to listen, and you understand, watching her face, that she is not coming back to the Readers' shelf, or not soon.".
    On discuss { Assert sorrelSpoke(sorrel). }
  }
  Topic sorrel_stay with sorrel "Ask Sorrel Haddow whether she will stay with the Lady" when sorrelSpoke(sorrel) and travelsWith(sorrel, actor) and not sorrelStays(sorrel) once {
    Says "Sorrel looks up at the Lady, and back at you. 'She can't see to write,' she says. 'And Mrs Pyecroft writes small.' She wipes her hands on her skirt, which only moves the ink about. 'Somebody should write it all down. What she says. The Readers read; somebody should write.' She hugs you, hard, and leaves ink on you. 'Come and see me. I'll be at the table. I'll be the one with the broom.'".
    On discuss { Assert sorrelStays(sorrel). Retract travelsWith(sorrel, actor). Assert at(sorrel, chart_table). }
  }
  // ── The chart, corrected ──────────────────────────────────────────────────────────────────────────────────────────
  // To draw the Wainscot in, the company must know it as a surveyor knows a place (paced, with its turns and lengths),
  // and must write it in a hand she can read: Sorrel's, or its own if it has the learning.
  Thing lady_chart "the Lady's chart of Hollins" at chart_table is scenery {
    State blank "The walls are drawn as single lines, as a giant would see them, and there is nothing inside them: behind the skirting of the Hall, where the Wainscot is, only a thin ruled line, and the word SKIRTING.".
    State corrected "Across the chart, in a big black hand that is not the Lady's but has studied hers, the space behind the Hall skirting has been drawn in: a lane, a market, an inn round a nail, stairs, the Hearth in the grate, the Small House in the nursery, each with its name. In the margin, three words: WE LIVE HERE.".
    State questioned "In the margin of the chart, under WE LIVE HERE, the Lady has written in her own hand, very large, the letters shaking: WHO ARE YOU?".
    State answered "Under her question, in the big black hand: THE LACEYS' PEOPLE, AND ALL WHO CAME AFTER. WE ARE STILL HERE. And under that, in hers, nothing yet.".
  }
  Relation surveyed(group). Relation chartWritten(group).
  Action survey_wainscot(actor: group, site: place) "Pace out the Wainscot as a surveyor would, every lane and turn" {
    Description "Lengths, turns and landmarks, written down: the Skirting, Lath Lane, the Nail, the wall-ways to the grate and the Library.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, skirting) and not surveyed(party).
    Time 6.
    Resolve check(actor, wayfinding, dc_fair).
    On success { Assert surveyed(party). Assert knows(actor, wainscot_paced). }
    Result "It takes an hour, with a knotted string and Faith Penny's register for the names, and the Wainscot follows you about asking what you are doing. By the end you have it on a sheet: every lane and turn, in paces, the way the Lady would have it.".
    Otherwise "You lose count in the turns behind the drawing room, and again on the stair down to the Nail, and come out with a sheet of figures that would put the Nail in the cellar. It will need doing again.".
  }
  Discovery wainscot_paced "You have paced out the Wainscot as a surveyor would, every lane and turn, in figures the Lady could use.".
  Topic sorrel_survey with sorrel "Ask Sorrel Haddow whether the Readers have a plan of the Wainscot" when knows(actor, chart_plan) and not surveyed(party) once {
    Says "'Not one she'd trust,' says Sorrel. 'Ours are drawn the way people draw where they live: big where they matter, small where they don't. The Nail's as big as the Hall on Gideon's.' She frowns. 'She measures. Every line she draws has a figure on it. If we put the Nail in the wrong place she'll know we're guessing, and she'll think it's her eyes again.' She hands you a knotted string. 'Somebody has to pace it.'".
  }
  Relation inkGot(group).
  Topic gideon_ink with gideon "Ask Gideon Lamb for a bucket of the Readers' ink" when knows(actor, chart_plan) and not inkGot(party) once {
    Says "Gideon Lamb looks at you over his mended spectacles. 'For Mistress Haddow's broom,' he says. 'For writing on Her chart.' He takes them off. 'The Readers read. It is what we are. We have never once in a hundred and sixty years written in one of Her books.' He puts the spectacles on again. 'Second bucket on the left, by Mandragora. Don't tell me which night.'".
    On discuss { Assert inkGot(party). }
  }
  Action correct_chart(actor: group, site: place) "Draw the Wainscot into the Lady's chart, in her hand, while she sleeps" {
    Description "A night's work with a broom and a bucket of ink, walking the chart: every lane and room behind her walls, and in the margin, WE LIVE HERE.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, chart_table) and state(lady_chart, blank) and surveyed(party) and inkGot(party) and night() and not ladyDead(lady) and travelsWith(sorrel, actor).
    Time 6.
    On success { Assert state(lady_chart, corrected). Assert chartWritten(party). Assert at(actor, library_floor). }
    Result "Sorrel does the writing. You carry the bucket and call out the figures from the sheet, and she walks the chart with the broom, fast and sure, laying down lines as wide as her hand beside the Lady's lines, and the names in letters a yard high: THE SKIRTING. LATH LANE. THE NAIL. THE HEARTH. THE SMALL HOUSE. Her hand never shakes until the end, in the margin, where she writes WE LIVE HERE, and then has to stop and sit down on the compass rose and put her head between her knees. When the ink is dry you go down the rope in the dark.".
  }
  Action correct_chart_alone(actor: group, site: place) "Draw the Wainscot into the Lady's chart yourself, as near her hand as you can" {
    Description "A night's work with a broom and a bucket of ink, walking the chart; and it must look like a hand she will read without her glass.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, chart_table) and state(lady_chart, blank) and surveyed(party) and inkGot(party) and night() and not ladyDead(lady) and not travelsWith(sorrel, actor) and not chartBotched(party).
    Time 6.
    Resolve check(actor, lore, dc_hard).
    On success { Assert state(lady_chart, corrected). Assert chartWritten(party). Assert at(actor, library_floor). }
    On failure { Assert chartBotched(party). }
    Result "It is the hardest writing you have ever done: with a broom, walking backwards, in letters a yard high, copying the slant of hers from the words HALL and LIBRARY. But by the small hours the Wainscot is on her chart, every lane in its place, and in the margin, WE LIVE HERE. You go down the rope in the dark.".
    Otherwise "The lines go where they should, but the letters will not: they come out lumpy and childish, a yard high, and a mapmaker would take them for a smear. You stop before you spoil the chart, and blot what you can. Somebody who writes her hand should do this.".
  }
  Relation chartBotched(group).
  Rule chart_unbotch when chartBotched(party) and travelsWith(sorrel, party) { Retract chartBotched(party). }
  // At nine she finds it.
  Relation chartSeen(group). Measure seenOn(entity). Measure knewOn(entity).
  Rule lady_finds_chart when state(lady_chart, corrected) and at(lady, chart_table) and not chartSeen(lady) {
    Assert chartSeen(lady). Increase primed(lady) by 1. Set seenOn(lady_chart) to dayN(hollins).
  }
  Event chart_found_told when chartSeen(lady) and seenOn(lady_chart) == dayN(hollins) and at(lady, chart_table) and (at(party, chart_table) or at(party, sill)) "The Lady comes to the table and sits, and reaches for her glass, and stops with it half lifted. She sits very still. Then she bends close over the chart, closer than you have seen her bend over anything, until her breath is a gale across the paper, and moves the glass slowly along the Skirting, the Nail, the Hearth, and stops at the margin. WE LIVE HERE. A long while. Mrs Pyecroft says, from somewhere, 'Miss Whitbread?' and the Lady says, quite calmly, 'Go and see if the post has come, Dorothea,' and when Pyecroft has gone, she dips the pen.".
  Rule lady_asks_chart when chartSeen(lady) and state(lady_chart, corrected) and hour(clock) >= 11 { Assert state(lady_chart, questioned). }
  Action answer_chart(actor: group, site: place) "Answer her question on the chart, in her hand, while she sleeps" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, chart_table) and state(lady_chart, questioned) and inkGot(party) and night() and not ladyDead(lady) and travelsWith(sorrel, actor).
    Time 3.
    On success { Assert state(lady_chart, answered). }
    Result "Sorrel stands a long time over WHO ARE YOU?, with the broom dripping. Then she writes, without stopping, as if she had always known what she would write: THE LACEYS' PEOPLE, AND ALL WHO CAME AFTER. WE ARE STILL HERE.".
  }
  Action answer_chart_alone(actor: group, site: place) "Answer her question on the chart yourself, as near her hand as you can" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, chart_table) and state(lady_chart, questioned) and inkGot(party) and night() and not ladyDead(lady) and not travelsWith(sorrel, actor) and not answerBotched(party).
    Time 3.
    Resolve check(actor, lore, dc_fair).
    On success { Assert state(lady_chart, answered). }
    On failure { Assert answerBotched(party). }
    Result "You stand a long time over WHO ARE YOU?, with the broom dripping. Then you write, as large and as plain as you can: THE LACEYS' PEOPLE, AND ALL WHO CAME AFTER. WE ARE STILL HERE.".
    Otherwise "The words come out crooked, a yard high, and you blot them before they can frighten her. Tomorrow night, steadier.".
  }
  Relation answerBotched(group).
  Rule answer_unbotch when answerBotched(party) and hour(clock) == 12 { Retract answerBotched(party). }
  Rule chart_retry when chartBotched(party) and hour(clock) == 12 and not travelsWith(sorrel, party) { Retract chartBotched(party). }
  Rule lady_reads_answer when state(lady_chart, answered) and at(lady, chart_table) and not chartKnows(lady) { Assert chartKnows(lady). Assert ladyKnows(lady). Set knewOn(lady_chart) to dayN(hollins). }
  Relation chartKnows(group).
  Event chart_answer_told when chartKnows(lady) and knewOn(lady_chart) == dayN(hollins) and at(lady, chart_table) and (at(party, chart_table) or at(party, sill)) "She reads it with the glass, and then without, and then she says, aloud, in a voice that fills the Library: 'The Laceys.' She puts the glass down. 'Honor,' she says. 'Oh, Honor. I told them. I told them and told them.' And then, gathering herself, the voice of a woman who has given orders to harbour-masters: 'Whoever you are. I can't see you. I shall be at this table tomorrow at nine, and I shall sit very still, and I shall not let Dorothea near it. Come and be seen.'".

  // ── The Sill ──────────────────────────────────────────────────────────────────────────────────────────────────────
  Person pennock "Granny Pennock" at sill {
    Role "who keeps the window-boxes". Ancestry dwarf. Peaceable. Pronouns she. Manner cheerful.
    Likeness "farmer".
    Greets "An old dwarf-woman in a straw hat the size of a cartwheel, which on her looks enormous and on the Lady would be a button, sits back on her heels in the cress. 'Hands,' she says. 'Have you got hands? Then you can pick.'".
    Greets again "'Hands,' says Granny Pennock, and points at a basket.".
    Sells rations for 1 coin from 10.
  }
  Topic pennock_thaw with pennock "Ask Granny Pennock about the warm" when true once {
    Says "'The glass is warm,' says Granny Pennock, and lays her palm on it, flat, like a child on a window. 'It was cold all my life, and my gran's. We grew cress, because cress'll grow in anything, and radishes, and that's what the Wainscot's eaten, cress and radishes and her honey.' She points down the trough at the lettuces, pale and wide as umbrellas. 'Lettuce. Real lettuce. My gran had seeds from outside she'd never got to come. I planted them Friday for a joke.' She laughs. 'Whatever else she does, she's warmed the glass.'".
  }
  Relation pickedToday(group).
  Action pick_sill(actor: group, site: place) "Work a morning in the window-boxes for Granny Pennock" {
    Description "Weeding, picking and carrying, in the first sun the sill has had in three hundred years.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, sill) and at(pennock, sill) and hour(clock) >= 7 and hour(clock) < 12 and not pickedToday(party).
    Time 18.
    On success { Assert pickedToday(party). Increase quantity(actor, gold) by 2. Increase quantity(actor, rations) by 1. }
    Result "Three hours on your knees in the cress with the Pennocks, sun on your back through the glass, the whole moor below and the smoke going up from Bootscrape. Nobody talks much. Granny Pennock sings under her breath, something with no tune at all. At noon she pays you two coin and a bundle of radishes and a lettuce leaf like a tablecloth. 'Come back,' she says. 'There's always weeds.'".
  }
  Rule picked_resets when hour(clock) == 0 and pickedToday(party) { Retract pickedToday(party). }
  Topic pennock_lady with pennock "Ask Granny Pennock about watching the Lady at her chart" when true once {
    Says "'Every morning,' says Granny Pennock. 'Right there through the glass, nine till twelve, with her glass up to her eye like a pond, drawing.' She shades her eyes and looks through the pane at the table. 'She draws a line and stops and stares, and draws another. A whole house, from memory. You could see it was her house, from the way she draws it. You don't draw a stranger's house that slow.' She goes back to her weeding. 'There's nothing inside her walls. I noticed that. Just the walls.'".
    On discuss { Assert knows(actor, chart_known). }
  }
}

data/adventures/hollins/lore.kyr:
Module hollins "Behind the Wainscot" {
  Description "Links outward from Bootscrape: the almanack woman, who asked the hour of a clock the size of a church and was sold a candle.".

  // ── The almanack woman ──────────────────────────────────────────────────────────────────────────────────────────
  Discovery lore_cattermole_doorstep "Jessamy Cattermole, who sells almanacks, passed through Bootscrape on her way north-east, asked the carrier what hour it was, and has gone up to Merrowdale, where, she says, there is a notice offering forty crowns for a giant.".
  Topic lore_arkle_cattermole with arkle "Ask Widow Arkle about the woman who sells almanacks" when true once {
    Says "'Cattermole,' says Widow Arkle, as though it were a kind of weather. 'Six calendars, no two of them the same year. She bought one candle, which is more than the pedlars do, and asked me how long it burned. I told her. She wrote it in a book.' The dwarf squares a row of tapers that was square. 'She asked the carrier what hour it was, and he looked at the Long Clock behind the Slot, as we all do, and said, nearly twelve. She said it was a very handsome error. Then she went to Merrowdale, where she says they have a giant too, and nobody has asked him the time.'".
    On discuss { Assert knows(actor, lore_cattermole_doorstep). }
  }
}

data/adventures/hollins/nursery.kyr:
Module hollins "Behind the Wainscot" {
  // ── The first floor ───────────────────────────────────────────────────────────────────────────────────────────────
  // At the top of the Stair the landing; off it the nursery, with the Small House against its west wall and the Fort
  // on the hearthrug; and along the passage the Lady's room. The dumbwaiter comes up in a cupboard on the landing.
  Place landing "the first-floor landing" is room within first_floor at 1, 1.
  Place nursery_floor "the Nursery floor" is room within first_floor at 0, 1.
  Place small_house_hall "the Small House: the front hall" is room within first_floor at 0, 0.
  Place small_house_parlour "the Small House: the parlour" is room within first_floor at 1, 0.
  Place fort "the Fort" is room within first_floor at 0, 2.
  Place toy_box "the toy box" is room within first_floor at 1, 2.

  Passage nursery_door "the nursery door" is passage between landing and nursery_floor taking 10 minutes.
  Passage small_door "the front door of the Small House" is door between nursery_floor and small_house_hall.
  Passage parlour_door "the parlour door" is door between small_house_hall and small_house_parlour.
  Passage fort_path "the way across the hearthrug to the Fort" is passage between nursery_floor and fort taking 5 minutes.
  Passage box_lid "the lip of the toy box" is steps between nursery_floor and toy_box.

  Observe landing_scene at landing when true "The first-floor landing is a gallery of polished boards as wide as a road, with a banister along it like a fence of trees, and the Stair dropping away below into the dimness of the Hall. Doors as tall as cliffs open off it: one with a painted frieze of ducks, which is the nursery; one at the end, where a line of warm light shows under it, which is hers. In a cupboard in the wall, the dumbwaiter's box hangs on its ropes.".
  Observe nursery_scene at nursery_floor when true "The Nursery: a high room papered with faded ships, cold even now, with a rocking horse taller than a dray-horse standing dappled and still by the window, a toy box under it, and on the hearthrug a toy fort of painted wood with a pennant on its tower. Against the west wall, in the light from the window, stands a doll's house. It is a house. It has three storeys and a slate roof and a front door with a brass knocker, and smoke comes out of its chimney, and there are people at its windows.".
  Observe nursery_horse at nursery_floor as feature when true "The rocking horse rocks a little in the draught, all by itself, with a creak like a ship; and every time it does, everyone on the nursery floor looks up.".

  // ── The Small House and the Little Court ──────────────────────────────────────────────────────────────────────────
  // The doll's house is the one thing in Hollins made at our size: its chairs fit, its cups fit a hand, its beds a
  // body. The Laceys moved back into it after the Sweeping, and their descendants are the Court, by right of the
  // only furniture in the world that fits.
  Observe hall_sh_scene at small_house_hall when true "The front hall of the Small House is a front hall: a painted stair, a tiled floor, a chandelier with candles in it, a hat-stand, a looking-glass. Everything fits. After the house outside, it is so strange that you stand in the door a moment, dizzy. The paint on the stair-rail is worn through to the wood where three hundred years of hands have held it. On the wall, framed, a scrap of a giant's paper, a single word in a child's huge round hand: WELCOME.".
  Observe parlour_scene at small_house_parlour when true "The parlour: a little room with a carpet, a fireplace, a round table with a cloth, eight chairs, a clock on the mantel that ticks, and a window onto the nursery, where the light comes in grey off a world of giants. The furniture is three hundred years old and has been mended a thousand times and is the only furniture in the world that fits you. People speak in low voices here, as in a church.".
  Person honor "Dame Honor Lacey" at small_house_parlour {
    Role "the Chatelaine of the Small House". Ancestry human. Peaceable. Pronouns she. Manner proud.
    Likeness "noble".
    Greets "A tall old woman in a gown made from a giant's silk handkerchief, with a chain of shirt-buttons over her shoulders like a mayor's, rises from the head of the round table and inclines her head exactly as far as she means to. 'Honor Lacey,' she says, 'of the Small House. Named, as the eldest daughter of this house has been named for three hundred and twelve years, for the Child's friend.' She sits. 'You are the outsider. Everyone is talking about you. Sit.'".
    Greets again "Dame Honor Lacey inclines her head the same exact distance.".
  }
  Topic honor_court with honor "Ask Dame Honor Lacey what the Court is" when true once {
    Says "'The Laceys were the first,' says Dame Honor. 'The Child found them in the coal-hole and put them here, in her own house, with her own hands. She gave them this.' She touches the table. 'When the Sweeping came they went into the walls, and when it was safe they came back to the house she gave them, and they kept it for her. Everyone who has come in since has come into the Laceys' keeping.' She folds her hands. 'We mint the buttons. We keep the peace, such as it is. We keep the Forms.' Something flickers in her face. 'We keep the house ready for her. We always said she would come back to it.'".
    On discuss { Assert knows(actor, court_told). }
  }
  Discovery court_told "The Little Court of the Small House is the Lacey family, whom the Child put in her doll's house; they mint the buttons, keep the peace and the Forms, and have always said she would come back.".
  Topic honor_forms with honor "Ask Dame Honor Lacey what the Forms are" when knows(actor, court_told) once {
    Says "Dame Honor almost smiles. 'The Forms of Address to the Family,' she says. 'Compiled by my great-grandmother's grandmother, in nine volumes, against the day.' She rings a little bell, and an old man in a tabard made of a giant's cuff comes in at once, as if he had been waiting behind the door for forty years, which he has. 'Mr Ambry, our Herald. Mr Ambry, the Address.' Mr Ambry draws himself up and begins, in a voice like a horn: 'MOST HIGH AND GRACIOUS DAUGHTER OF HOLLINS, THE LACEYS OF THE SMALL HOUSE, WITH ALL THE PEOPLE OF THE WAINSCOT, THE HEARTH, THE PANTRY,' and goes on for some time. When he stops for breath Dame Honor says, gently, 'Thank you, Mr Ambry,' and he goes out. 'He has never said it to anybody,' she says. 'He practises on the rocking horse.'".
  }
  Topic honor_fear with honor "Ask Dame Honor Lacey why she has not gone to the Lady" when knows(actor, court_told) once {
    Says "Dame Honor is silent long enough that you think she will not answer. Then: 'Because I am afraid she will look at me,' she says, very low, 'and not know who I am.' She turns her button chain in her fingers. 'Three hundred years we have told it: the Child, and Honor, and the house she gave us. Every child in the Wainscot knows it. And if I go to her, and she looks down at me, and she says, who are you, little woman,' her voice does not break; it stops, and goes on, 'then we have been telling ourselves a story. Then we are only people who live in a doll's house.' She lifts her chin. 'The Court will decide what is to be done at the Moot. On the third day, at two. You may speak, if someone of the Wainscot brings you.'".
    On discuss { Assert knows(actor, honor_fears). Assert knows(actor, moot_coming). }
  }
  Discovery honor_fears "Dame Honor Lacey is afraid that if she goes to the Lady, the Lady will not know who she is, and the Court's three hundred years will turn out to be a story it told itself.".
  Discovery moot_coming "The Little Court holds a Moot in the Small House parlour at two in the afternoon of the third day, on what is to be done about the Lady; outsiders may speak if someone of the Wainscot brings them.".
  Person kit "Kit Lacey" at small_house_hall {
    Role "Dame Honor's nephew, heir of the Small House". Ancestry human. Peaceable. Pronouns he. Manner compassionate.
    Likeness "noble".
    Greets "A young man in a coat that is too good for him, with ink on his cuff, is sitting on the painted stair reading a letter, and puts it away very fast. 'You're the outsider,' he says. 'Aunt Honor said you'd come. Everybody comes to the Small House eventually. It's the only place in Hollins where the chairs fit.'".
    Greets again "Kit Lacey looks up from the stair, and his hand goes to his pocket.".
  }
  Topic kit_nan with kit "Ask Kit Lacey about Nan Collier" when knows(actor, kit_nan) and not kitNanMet(kit) once {
    Says "Kit goes white, and then red. 'You've seen her? Is she,' and he stops, and starts again. 'They burned the Hearth. I pulled the wire all night.' He takes the letter out of his pocket and looks at it without unfolding it. 'Two years. I know what she thinks about everything. I know she hates turnips and thinks the Winders are mad and wants to see the sea. I don't know what she looks like.' He laughs. 'I've never been down the Stair. Aunt Honor says the heir doesn't go among the Wainscot, the Wainscot comes to the heir.' He folds the letter. 'She'd be ashamed of me. A Lacey who's never done anything but sit on a stair.'".
    On discuss { Assert knows(actor, kit_fears). }
  }
  Discovery kit_fears "Kit Lacey fears Nan Collier will be ashamed of him, a Lacey who has never done anything but sit on a stair.".
  Rule nan_meets_kit at small_house_hall when following(nan, party) and at(party, small_house_hall) and at(kit, small_house_hall) and not kitNanMet(kit)
    says "Kit Lacey stands up off the painted stair so fast the letter falls out of his hand. Nan Collier stands in the front door of the Small House with soot in her plaits and her chin up. Neither of them says anything. Then Nan says, 'You're taller than your writing,' and Kit says, 'You're,' and cannot finish, and Nan says, 'Black. I know. It's the house burning,' and Kit comes down the last two steps and takes her sooty hand in his clean one and does not let go, and says, in a voice nothing like a book: 'Pull twice.' Dame Honor has come to the parlour door. She looks at them, and then, with enormous dignity, goes back into the parlour and shuts the door." {
    Assert kitNanMet(kit). Retract following(nan, party). Assert at(nan, small_house_hall).
  }

  // ── The Fort and the Tin Regiment ─────────────────────────────────────────────────────────────────────────────────
  // Clockwork soldiers half our height, a giant's toys, wound by the Child before she was sent away and told to keep
  // the little people safe from Mother. They have fought the nursery's mice for three hundred years. Fennick, their
  // winder, has deserted; the Regiment is running down.
  Measure wound(group).
  Initially Set wound(regiment) to 30.
  Relation regimentStopped(group). Relation standDown(group). Relation regimentMarched(group). Relation countersign(group).
  Rule regiment_runs_down when hour(clock) == 0 and not windingDone(regiment) and wound(regiment) > 0 and not standDown(regiment) { Decrease wound(regiment) by 6. Assert windingDone(regiment). }
  Rule regiment_night_resets when hour(clock) == 1 and windingDone(regiment) { Retract windingDone(regiment). }
  Relation windingDone(group).
  Rule regiment_stops when wound(regiment) <= 0 and not regimentStopped(regiment) { Assert regimentStopped(regiment). Assert peaceable(regiment). Assert tolerates(regiment, party). }
  Observe fort_scene at fort when true "The Fort is a toy fort on the hearthrug, painted wood, its walls three times your height, its gate a drawbridge on a string. Inside its courtyard a regiment of tin soldiers stands in ranks: each half your height, red-coated, the paint worn to the tin at the elbows, each with a key in its back. A pennant on the tower says, in a child's capitals, THE LITTLE PEOPLES REGIMENT.".
  Observe fort_running at fort as feature when not regimentStopped(regiment) and not standDown(regiment) and wound(regiment) < 20 "The soldiers move slowly, as if through honey: a head turns, and goes on turning for a long while; a hand comes up to a salute and stops halfway. The ticking from their backs is uneven, like a heart.".
  Observe fort_stopped at fort as feature when regimentStopped(regiment) and not standDown(regiment) "The soldiers have stopped where they stood: a sentry with his musket half shouldered, the drummer with his sticks up, the captain with his sword out pointing at the nursery door. Nothing ticks.".
  Observe fort_rest at fort as feature when standDown(regiment) "The soldiers are sitting down, which you did not know they could do: on the courtyard floor, in rows, with their muskets across their knees and their keys still. A sheet of paper is pinned to the gate in an enormous hand: THE WAR IS OVER. YOU MAY REST. WITH LOVE AND THANKS, E. W.".
  Person regiment "the Tin Regiment" at fort {
    Role "clockwork soldiers half your height, red-coated, keys in their backs". Species clockwork_soldier. Level 2. Numbers 6. Pronouns they.
    Temperament obedient.
    Lair fort.
    Comes "The tin soldiers turn all together with a whirr of springs and come at you across the courtyard in step, bayonets down, ticking.".
  }
  Person ordinance "Captain Ordinance" at fort {
    Role "the captain of the Tin Regiment". Species clockwork_soldier. Level 3. Peaceable. Pronouns he. Manner stoic.
    Greets "A tin captain with a painted moustache and a sword the length of your arm turns his head toward you with a whirr. 'HALT,' he says, in a voice like a musical box. 'WHO GOES. GIVE THE WORD, OR BE TAKEN FOR MOTHER'S.'".
    Greets again "'WHO GOES,' says Captain Ordinance, and waits.".
  }
  Rule regiment_tolerates when countersign(party) and not tolerates(regiment, party) and not regimentMarched(regiment) { Assert tolerates(regiment, party). }
  Topic ordinance_orders with ordinance "Ask Captain Ordinance what his orders are" when countersign(actor) once {
    Says "'ORDERS,' says the Captain, 'GIVEN BY THE COLONEL IN PERSON, ON THE DAY.' He recites, in a child's cadence through a musical box: 'You are to keep my little people safe from Mother, and from Mother's traps, and from the cat, and from the mice, until I come home. You are not to stop. You are the best regiment in the world.' He salutes, slowly. 'THREE HUNDRED AND TWELVE YEARS. NO LITTLE PERSON TAKEN BY A MOUSE. MOTHER HAS NOT RETURNED.' His head turns, creaking, to the nursery door. 'IF MOTHER RETURNS WE MARCH.'".
    On discuss { Assert knows(actor, regiment_orders). }
  }
  Discovery regiment_orders "The Tin Regiment's orders, from the Child: keep the little people safe from Mother, Mother's traps, the cat and the mice, until she comes home, and never stop. If Mother returns, they march.".
  Topic ordinance_mother with ordinance "Tell Captain Ordinance that Mother's traps have come back, and whose they are" when knows(actor, regiment_orders) and (watDead(wat) or pyeSuspects(pye) or hiredBy(actor, pye)) and not regimentMarched(regiment) and not regimentStopped(regiment) and not standDown(regiment) once {
    Grave "The Regiment will march on Mrs Pyecroft's hatbox tonight, with bayonets. What they do there will be done.".
    Says "The Captain's whole body whirrs. 'TRAPS,' he says. 'MOTHER'S TRAPS.' His sword comes up, very slowly, to the vertical. 'WHERE.' You tell him: the hatbox on the dressing table, in her room, where the woman who lays them sleeps. 'REGIMENT,' says the Captain, and every tin head in the courtyard turns. 'TONIGHT, WE MARCH.'".
    On discuss { Assert regimentMarched(regiment). }
  }
  Relation pyeStabbed(group).
  Rule regiment_attacks when regimentMarched(regiment) and night() and not regimentStopped(regiment) and not pyeStabbed(pye) and not pyeGone(pye) and at(pye, hatbox) { Assert pyeStabbed(pye). Assert pyeGone(pye). Assert at(pye, nowhere). }
  Event regiment_told within house when pyeStabbed(pye) "In the night, from upstairs, a sound like a musical box played very fast, and a drum, and tin feet on boards, and then a woman's scream, small and high, and the Lady's voice, enormous, 'Dorothea? Dorothea!', and a light, and then the Lady weeping, on and on, in the dark over the house.".
  Observe fort_after at fort as sign when pyeStabbed(pye) "In the courtyard the tin soldiers stand in their ranks with their bayonets dark to the socket. The Captain stands before them, very still. Something has gone out of the way he stands.".

  // ── Fennick ───────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe box_scene at toy_box when true "The toy box is a wooden cave full of broken things: a jack-in-the-box with its spring sprung and its head on its chest, a Noah's ark with half the animals, skittles like felled trees, a ball the size of a hay-cart gone soft, and, on a red ribbon, a silver sleigh bell as big as a bucket.".
  Person fennick "Lance-Corporal Fennick" at toy_box {
    Role "a tin soldier, the Regiment's winder". Species clockwork_soldier. Level 2. Peaceable. Pronouns he. Manner stoic.
    Greets "In the ark, sitting on the deck between a tin giraffe and a tin bear, a tin soldier half your height turns his head toward you and does not get up. 'Don't tell the Captain,' he says. His voice is a musical box too, but a quieter one. 'Or do. It doesn't matter. He's running down.'".
    Greets again "Lance-Corporal Fennick turns his head toward you, ticking.".
    Joins "Fennick gets up out of the ark, stiffly, and brushes off his red coat, and shoulders his musket as if he had forgotten how and was remembering. 'Somebody will have to wind me,' he says. 'Every day. There's a key in my back.'".
    Remarks at fort "Fennick stops at the edge of the courtyard and looks at the Regiment. 'I wound every one of them,' he says. 'Every morning, before light.'".
  }
  Topic fennick_why with fennick "Ask Fennick why he left the Fort" when true once {
    Says "'I'm the winder,' says Fennick. 'Every morning I go down the ranks with the key and wind them for another day. Three hundred and twelve years of mornings.' He looks at his hands. 'Against mice. We kill mice. The mice come back. We kill them. The Colonel said, until I come home. The Colonel never came home.' He ticks. 'And on Thursday something came into the house that shook the floor, and the Captain said, the Colonel? And I thought: if it's her, the war's over. And if it isn't, it never will be.' He looks at you. 'So I stopped winding. If I wind them, it goes on. If I don't, they stop, and the war stops, and so do they.' A long tick. 'I don't know which is right. So I'm sitting in the ark.'".
    On discuss { Assert knows(actor, fennick_stopped). Assert willing(fennick, actor). Assert countersign(actor). }
  }
  Discovery fennick_stopped "Lance-Corporal Fennick, the Tin Regiment's winder, has stopped winding them, so that the war against the mice will end, and so will they; he does not know which is right. The Regiment's word is 'Today'.".
  Topic fennick_word with fennick "Ask Fennick for the Regiment's word" when true once {
    Says "'Today,' says Fennick. 'The Colonel's word. It will still be today when I come home.' He ticks. 'Say it to the Captain and they'll know you for a little person and not one of Mother's.'".
    On discuss { Assert countersign(actor). }
  }
  Topic fennick_after with fennick "Ask Fennick what he will do, now the war is over" when standDown(regiment) once {
    Says "Fennick reads the paper on the gate twice, with his head on one side, ticking. THE WAR IS OVER. YOU MAY REST. 'Rest,' he says. He looks at the Regiment sitting in its rows. 'I never thought of that. I thought there was winding, and not winding.' His winding hand goes round once on nothing. 'I should like to see the sea,' he says. 'The Colonel drew it for us once, on the nursery floor, in chalk. Then I'll sit down with the others.' He holds out his key to you. 'Wind me as far as the sea, if you're going that way. Not further.'".
  }
  Measure spring(group).
  Initially Set spring(fennick) to 24.
  Rule fennick_ticks when travelsWith(fennick, party) and hour(clock) != lastTick(fennick) and spring(fennick) > 0 { Decrease spring(fennick) by 1. Set lastTick(fennick) to hour(clock). }
  Measure lastTick(group).
  Rule fennick_runs_down when spring(fennick) <= 0 and travelsWith(fennick, party) and not fennickStopped(fennick) says "Fennick's ticking slows, and stutters, and stops. He stands where he is with one foot lifted, and does not put it down." { Assert fennickStopped(fennick). Retract travelsWith(fennick, party). Assert at(fennick, toy_box). }
  Relation fennickStopped(group).
  Action wind_fennick(actor: group, site: place) "Wind Fennick's key" {
    Requires able(actor) and company(actor) and at(actor, site) and travelsWith(fennick, actor) and spring(fennick) < 20.
    Time 0.
    On success { Set spring(fennick) to 24. }
    Result "The key in his back turns stiffly, twenty turns, and the ticking steadies. 'Thank you,' says Fennick, as he always does, as if it were a kindness and not a necessity, which perhaps it is.".
  }
  Action wind_regiment(actor: group, site: place) "Go down the ranks with Fennick and wind the Regiment for another day" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, fort) and travelsWith(fennick, actor) and not standDown(regiment) and wound(regiment) < 30 and wound(regiment) > 0.
    Time 3.
    On success { Set wound(regiment) to 30. }
    Result "Fennick goes down the ranks with the key, and you go with him and hold each one steady while he winds, and they come up to the mark one by one, heads lifting, eyes brightening, ticking. The Captain watches without a word. When it is done Fennick stands at the end of the rank and says, quietly, 'Another day, then,' and you cannot tell whether he means it as a mercy or a sentence.".
  }
}

data/adventures/hollins/placed.kyr:
Module hollins "Behind the Wainscot" {
  // The country beyond a march of a generated world: the company that comes in by the moor road is the world's own.
  Entity party: group "Your company".
  // What is said of Hollins in the country behind it: once the Lady is dead, the notice there is old news.
  Entity word: fact "What is said of Hollins in the country behind it.".
  Rule word_old when ladyDead(lady) and not stale(word) { Assert stale(word). }
}

data/adventures/hollins/plots.kyr:
Module hollins "Behind the Wainscot" {
  // ── The Smoking ───────────────────────────────────────────────────────────────────────────────────────────────────
  // On the fourth afternoon Mrs Pyecroft goes down to Bootscrape for Widow Arkle's sulphur candles; if there are none to be
  // had, she sends to Wendle by the carrier, and has them on the seventh. She means to smoke the house on the eighth
  // night, with the Lady asleep upstairs and the doors shut: sooner if she has been told where they nest, or if the
  // Lady has begged her; later if she had to send. It can be stopped by taking her candles, by her own change of
  // mind, or by the Lady's word; and it can be outlived by going upstairs, or down the ladder.
  Relation pyeOrdered(group). Relation smoked(place). Relation smokingOver(place). Relation evacuated(place). Relation evacPlanned(place).
  Measure smokeNight(place).
  Initially Set smokeNight(hollins) to 8.
  Query pyeWilling() means not pyeTurned(pye) and not pyeCowed(pye) and not pyeWaits(pye) and not pyeGone(pye) and not ladyForbids(lady) and not ladyDead(lady).
  Rule pye_buys when day4() and hour(clock) >= 15 and at(pye, bs_street) and pyeWilling() and not pyeOrdered(pye) and not sulphurBought(party) and not arkleRefuses(arkle) {
    Assert pyeOrdered(pye). Assert pyeHasSulphur(pye).
  }
  Rule pye_sends when day4() and hour(clock) >= 15 and at(pye, bs_street) and pyeWilling() and not pyeOrdered(pye) and (sulphurBought(party) or arkleRefuses(arkle)) {
    Assert pyeOrdered(pye). Increase smokeNight(hollins) by 1.
  }
  Rule wendle_carrier when pyeOrdered(pye) and not pyeHasSulphur(pye) and dayN(hollins) >= 7 and hour(clock) >= 15 and pyeWilling() { Assert pyeHasSulphur(pye). }
  Rule pye_hastens when fright(lady) >= 2 and not hastened(pye) and smokeNight(hollins) > 7 { Assert hastened(pye). Decrease smokeNight(hollins) by 1. }
  Relation hastened(group).
  Rule pye_hastens_nest when soldOut(party) and pyeHasSulphur(pye) and smokeNight(hollins) > dayN(hollins) and smokeNight(hollins) > 5 and not hastenedNest(pye) { Assert hastenedNest(pye). Set smokeNight(hollins) to dayN(hollins). }
  Relation hastenedNest(group).
  Query smokeTonight() means dayN(hollins) == smokeNight(hollins) and hour(clock) >= 20.
  Event arkle_tells at arkle_shop when pyeHasSulphur(pye) and pyeOrdered(pye) and at(party, arkle_shop) and not sulphurBought(party) and not arkleRefuses(arkle) "Widow Arkle does not look up from the thimble. 'Your Mrs Pyecroft was in,' she says. 'Bought my three yellow ones. Said it was for the cellars.' She looks up then. 'There's no cellars I know of that want three.'" teaches smoking_planned.
  Topic pye_tells_smoke with pye "Ask Mrs Pyecroft what she will want of you next" when hiredBy(actor, pye) and pyeHasSulphur(pye) and pyeWilling() and not smokingOver(hollins) once {
    Says "'The night of the {smokeNight(hollins)}th,' says Mrs Pyecroft. 'When she has had her drops and is asleep. I have sulphur. I shall light it in the Hall, the drawing room and the kitchen, and shut the doors, and the smoke will go down into every crack in this house where they breed.' She nods, briskly. 'I shall want you to help with the doors. They are heavy.'".
    On discuss { Assert knows(actor, smoking_planned). }
  }
  Rule smoke_lit when smokeTonight() and hour(clock) >= 22 and pyeHasSulphur(pye) and not candlesGone(pye) and pyeWilling() and not smokingOver(hollins) { Assert smoked(hollins). Assert smokingOver(hollins). Set smokedAt(hollins) to watch(clock). }
  Hazard sulphur_smoke "Sulphur smoke, sinking" means "Deal (3d6) physical damage to ally unless constitution save against (14).".
  Rule smoke_chokes when smoked(hollins) and (within(party, ground_floor) or within(party, cellars)) and watch(clock) > smokedAt(hollins) and watch(clock) <= smokedAt(hollins) + 12 and not choked(party)
    says "The smoke finds you too. It comes along the floor yellow and slow, and where it touches it burns, eyes, throat, lungs; you are on your knees before you know it, and the way up is a long way off." { Assert choked(party). Assert strikes(sulphur_smoke, party). }
  Relation choked(group). Measure smokedAt(place).
  Rule smoke_foiled when dayN(hollins) > smokeNight(hollins) and not smokingOver(hollins) and hour(clock) >= 6 { Assert smokingOver(hollins). }
  Rule smoke_evacuates when smokeTonight() and evacPlanned(hollins) and not evacuated(hollins) and pyeHasSulphur(pye) and pyeWilling() and not candlesGone(pye) { Assert evacuated(hollins). }
  Event smoke_told within house when smoked(hollins) and not evacuated(hollins) "At ten o'clock Mrs Pyecroft goes down the Hall in her nightcap with a taper, and lights three fat yellow candles on three saucers, in the Hall, in the drawing room, in the kitchen, and goes out, and shuts the doors, which close like the end of the world. The smoke goes down. It goes down the way water goes down: along the flagstones, under the skirting, into the cracks, the grate, the pantry, the Nail. For a while there is coughing in the walls of the house, everywhere, all at once. Then there is less.".
  Event smoke_told_out within house when smoked(hollins) and evacuated(hollins) "At ten o'clock Mrs Pyecroft goes down the Hall in her nightcap with a taper and lights her yellow candles and shuts the doors, and the smoke goes down into the walls like water; and finds them empty. The Wainscot is out: up the Stair to the Nursery in a long line, or down the rope ladder from the Slot to Bootscrape, where every loft and barn has its doors open and its lamps lit, and Jory Mudge is ladling broth in the street.".
  Action raise_wainscot(actor: group, site: place) "Raise the Wainscot: up the Stair, and out by the Slot, before the smoke" {
    Description "Go along the Skirting door to door with the word, and get six hundred people moving in the dark.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, skirting) and knows(actor, smoking_planned) and dayN(hollins) == smokeNight(hollins) and hour(clock) >= 18 and not evacuated(hollins) and not smokingOver(hollins).
    Time 6.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert evacuated(hollins). }
    Result "You go down the Skirting banging on doors, and at first nobody believes you, and then Mab Tenter does, and then everybody does at once. By ten the Skirting is a river of people going one way, carrying children and bedding and pots, up the Risers' ladders in the dark or up into the Slot and down the rope to the village, and the Post is entering them as they go, out of habit, until Faith Penny throws the pen down and carries a child herself.".
    Otherwise "You go down the Skirting banging on doors and shouting, and they look at you out of their doorways, at the stranger, the ratcatcher some say, and close their doors. A few go. Most do not.".
  }
  Action douse_candles(actor: group, site: place) "Pinch out the sulphur candle on the Hall floor" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hall_flags) and smokeTonight() and hour(clock) >= 22 and pyeHasSulphur(pye) and not smokingOver(hollins).
    Time 1.
    On success { Assert candlesGone(pye). }
    Result "You find it by its light: a yellow candle on a saucer, as big as you, guttering, with a coil of evil smoke going up off it and falling back and spreading along the floor. You hold your breath and push it over and smother the flame in your coat, and do the same in the drawing room, and the kitchen, choking, your eyes streaming.".
  }

  // ── The Hollins Stone Concern ─────────────────────────────────────────────────────────────────────────────────────
  Person overy "Mr Overy" at nowhere {
    Role "the surveyor of the Hollins Stone Concern". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Likeness "merchant".
    Greets "A pleasant man in a good grey coat, with a measuring-chain coiled on the table by his beer, rises and offers his hand. 'Overy, of the Concern. You'll have come out of the house. Remarkable, isn't it? Six thousand tons of dressed granite, I make it, and the slates, and the lead.' He beams. 'A town's worth of stone, standing idle.'".
    Greets again "Mr Overy lifts his beer to you.".
  }
  Rule overy_comes when dayN(hollins) >= 5 and hour(clock) >= 10 and at(overy, nowhere) and not deedLodged(party) and not saleRevoked(lady) { Assert at(overy, mat_tap). }
  Topic overy_stone with overy "Ask Mr Overy what the Concern means to do with Hollins" when true once {
    Says "'Take it down,' says Mr Overy, as you might say a man means to have his hair cut. 'Carefully, mind. Course by course from the chimneys. Wendle wants a corn exchange and a gaol, and there's not a quarry in the county with granite like hers.' He considers his beer. 'It's a quarry that happens to be standing up. Nobody's lived in it for three hundred years.' He looks at you. 'Have they?'".
  }
  Topic overy_paper with overy "Ask Mr Overy what papers the Concern holds" when true once {
    Says "'A conveyance,' says Overy, 'signed by the Lady in the spring, to take effect on her decease, Mrs Pyecroft acting for her. All proper.' He taps his nose. 'Only the deed's not been found. Without the deed her cousin's lawyers'll have us in court for ten years. Mrs Pyecroft's been looking.' He smiles. 'I'd pay for it. Fifteen coin to anybody who brought me the deed of Hollins. No questions.'".
    On discuss { Assert knows(actor, overy_pays). }
  }
  Discovery overy_pays "Mr Overy of the Hollins Stone Concern holds a conveyance the Lady signed in the spring, to take effect on her death, but needs the deed; he will pay fifteen coin for it.".
  Relation deedSold(group).
  Action sell_deed(actor: group, site: place) "Sell Mr Overy the deed of Hollins, for fifteen coin" {
    Grave "With the deed and the conveyance together, the Concern can take the house down when she dies.".
    Speaker overy.
    Requires able(actor) and company(actor) and at(actor, site) and at(overy, site) and carries(actor, deed) and not deedSold(party).
    On success { Spend deed from actor. Assert deedSold(party). Increase quantity(actor, gold) by 15. }
    Result "Mr Overy takes the roll in both arms and sits down under it, beaming, and unties the ribbon enough to read the first line, and ties it again. 'Fifteen,' he says, and counts it out. 'You've done Wendle a good turn. A corn exchange. A gaol.' He pats the deed. 'Nobody lives there, after all.'".
  }
  Rule overy_leaves when (deedLodged(party) or saleRevoked(lady)) and at(overy, mat_tap) { Assert at(overy, nowhere). }
  Event overy_gone at mat_tap when deedLodged(party) and at(party, mat_tap) "Mr Overy's table by the fire is empty, his chain gone. Jory Mudge, wiping it, says: 'Gone back to Wendle on the carrier. Said Salcombe had a deed in his box and a will beside it, and he'd sooner argue with God than with Salcombe.'".

  // ── The Jarl's poison ─────────────────────────────────────────────────────────────────────────────────────────────
  // Mrs Pyecroft lays poisoned bread along the Hall skirting on the third morning. If the Jarl has a death to answer (his
  // son in her trap, or the colliers in her fire), the Jarmen gather it into a pot; and on the sixth afternoon, while
  // she naps before tea, his man climbs the table leg and puts it in her sugar.
  Relation poisonLaid(place). Relation poisonPotFull(place). Relation haspPlots(group). Relation haspStands(group).
  Relation poisonInSugar(group). Relation sugarSpilled(group). Relation potEmptied(group).
  Rule pye_poisons when day3() and hour(clock) >= 7 and pyeWilling() and not poisonLaid(skirting) { Assert poisonLaid(skirting). }
  Rule hasp_resolves when (watDead(wat) or ladyCursed(hollins)) and poisonLaid(skirting) and not haspPlots(hasp) and not haspStands(hasp) and dayN(hollins) >= 3 { Assert haspPlots(hasp). Assert poisonPotFull(pantry). }
  Rule hasp_relents when haspStands(hasp) and poisonPotFull(pantry) { Retract poisonPotFull(pantry). Retract haspPlots(hasp). }
  Discovery poison_plan "The Jarmen have gathered Mrs Pyecroft's poisoned bread into a pot. On the sixth afternoon, while the Lady naps before tea, the Jarl's man will climb the tea table and put it in her sugar.".
  Topic mab_whisper with mab "Ask Mab Tenter what the Wainscot is saying about the Jarmen" when haspPlots(hasp) and not haspStands(hasp) and dayN(hollins) >= 4 once {
    Says "Mab looks round the Nail before she answers, which she has never done before. 'That they've been along the Skirting with a sack, picking up Pyecroft's bread. All of it. Every crust.' She ladles. 'That Hasp sits on his throne with a pot on the shelf behind him and won't eat. That Dunstan Gall's been practising on the table leg in the drawing room at night, up and down, up and down.' She puts the ladle in the pot. 'Sixth day, they're saying. At her tea. In the sugar.' She looks at you. 'And I'm saying nothing. I want it to stop. I told you.'".
    On discuss { Assert knows(actor, poison_plan). }
  }
  Topic nan_whisper with nan "Ask Nan Collier what the colliers are saying" when haspPlots(hasp) and collierDead(hollins) and not haspStands(hasp) once {
    Says "Nan does not look at you. 'The Jarl came to the Skirting,' she says. 'Asked for strong arms to steady a rope up the tea-table leg on the sixth day. For her sugar.' She turns her pencil over. 'Some said yes. For Mam.' A long breath. 'I said no. I don't know why. I hate her. I said no.'".
    On discuss { Assert knows(actor, poison_plan). }
  }
  Action steal_pot(actor: group, site: place) "Take the poison pot from behind the Jarl's throne" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pantry) and poisonPotFull(pantry) and not potEmptied(party) and not stealTried(party).
    Resolve check(actor, stealth, dc_fair).
    On success { Assert potEmptied(party). Retract poisonPotFull(pantry). }
    On failure { Assert stealTried(party). Retract tolerates(pinmen, actor). Assert hostile(pinmen, actor). Assert assails(pinmen, actor). Assert at(pinmen, pantry). }
    Result "You wait until the Jarl goes to the back to look at the crocks, as he does every hour now, as if Wat might be there; and take the pot off the shelf, and are out through the comb-gate with it under your arm before anyone looks round. In the kitchen you empty it down the Sink's drain, and the drip washes it away.".
    Otherwise "Your hand is on the pot when a pin-man turns round. 'Jarl!' he shouts, and the Pantry is full of steel.".
  }
  Relation stealTried(group).
  Action stay_hasp(actor: group, site: place) "Tell Hasp Tallowby that if she dies the quarrymen come, and the Pantry with the rest" {
    Speaker hasp.
    Requires able(actor) and company(actor) and at(actor, site) and at(hasp, site) and haspPlots(hasp) and not haspStands(hasp) and knows(actor, concern_heard) and not stayedHasp(party).
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert haspStands(hasp). }
    On failure { Assert stayedHasp(party). }
    Result "Hasp hears you out about the Concern, and the paper Pyecroft made her sign, and the cartloads of stone going down to Wendle for a corn exchange. He sits very still. 'So she dies,' he says, 'and they pull my Pantry down round my ears, and my boy's dead for nothing, and his da's a murderer for nothing.' He reaches behind him without looking and takes the pot down off the shelf, and holds it on his knee, and looks at it. 'Get it out of my sight,' he says, and gives it to you, and then puts his face in his hands.".
    Otherwise "'Let them come,' says Hasp. 'Let them pull it down. She'll be dead first.' He does not look at you again.".
  }
  Relation stayedHasp(group).
  Topic hasp_summoned with hasp "Tell Hasp Tallowby the Lady asks to see him, and will sit as still as she can" when ladyKnows(lady) and trapsLifted(lady) and watDead(wat) and not haspStands(hasp) once {
    Says "Hasp looks at you a long time. 'She asks,' he says. 'Her.' He gets up off the cheese, slowly, like an old man, and stands with his pin in his hand, and then leans it against the throne and leaves it there. He goes. He is gone an hour. When he comes back his face is not changed, exactly, but something in the way he holds it is. 'She knew his name,' he says. 'She'd asked it. She said it to me. She said, I lit fires and laid traps in my own house because I would not believe what I saw, and your son is dead of it, and I have nothing to give you that is worth anything.' He sits down. 'She cried. She is a hill, and she cried.' He looks at the pot on the shelf. 'Throw that down the drain,' he says, to nobody, and a pin-man does.".
    On discuss { Assert haspStands(hasp). }
  }
  Person brack "Dunstan Gall" at nowhere {
    Role "the Jarl's man". Ancestry human. Calling thief. Level 3. Peaceable. Pronouns he. Manner grim.
    Greets "A lean man with a coil of rope over his shoulder and a pot under his arm stops dead on the cloth and looks at you. 'Out of the way,' he says. 'This is the Jarl's.'".
  }
  Rule brack_climbs when day6() and hour(clock) >= 15 and hour(clock) < 16 and poisonPotFull(pantry) and haspPlots(hasp) and not haspStands(hasp) and at(brack, nowhere) and not poisonInSugar(hasp) and not brackStopped(brack) { Assert at(brack, tea_table). Set brackAt(brack) to watch(clock). }
  Rule brack_doses when at(brack, tea_table) and day6() and hour(clock) >= 15 and not brackStopped(brack) and not poisonInSugar(hasp) and watch(clock) >= brackAt(brack) + 3 { Assert poisonInSugar(hasp). Assert at(brack, nowhere). }
  Measure brackAt(group).
  Relation brackStopped(group).
  Action stop_brack(actor: group, site: place) "Stand between Dunstan Gall and the sugar bowl" {
    Speaker brack.
    Requires able(actor) and company(actor) and at(actor, site) and at(brack, site) and not brackStopped(brack).
    Resolve check(actor, intimidation, dc_fair).
    On success { Assert brackStopped(brack). Assert at(brack, nowhere). Retract poisonPotFull(pantry). }
    On failure { Retract peaceable(brack). Assert assails(brack, actor). }
    Result "You stand in front of the sugar bowl and do not move. Brack looks at you, and at the drop, and at the pot under his arm, and something in him is very tired. 'He'll ask why,' he says. 'Tell him somebody stood in the way.' He goes over the edge on his rope, and halfway down, you hear the pot smash on the Carpet.".
    Otherwise "'Then fight me for it,' says Brack, and puts the pot down, and draws a knife made from a needle.".
  }
  Rule brack_beaten when (dead(brack) or routed(brack)) and not brackStopped(brack) { Assert brackStopped(brack). Retract poisonPotFull(pantry). Assert at(brack, nowhere). }
  Action spill_sugar(actor: group, site: place) "Heave the sugar bowl over the edge of the table" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, tea_table) and poisonInSugar(hasp) and not sugarSpilled(party) and not poisoned(lady).
    Resolve check(actor, brawn, dc_fair).
    Time 1.
    On success { Assert sugarSpilled(party). }
    Result "It is like trying to move a cask. You put your shoulder to the round china tower and push, and rock it, and push, and it goes, slowly, over the lip of the table, and falls for a long time, and bursts on the Carpet like a bomb of snow. When the Lady comes to tea she feels for the bowl and finds nothing and says, 'Dorothea, where is the sugar?' and has her tea without.".
    Otherwise "It will not move. It is a china tower full of sugar and it will not move for you.".
  }
  Topic pye_sugar with pye "Tell Mrs Pyecroft the sugar on the tea table is poisoned" when knows(actor, poison_plan) and (poisonInSugar(hasp) or poisonPotFull(pantry)) and not sugarSpilled(party) and not poisoned(lady) once {
    Says "Mrs Pyecroft stares at you. 'Poisoned,' she says. 'By rats.' And then, slowly, her face changing: 'Not rats.' She does not ask anything else. She goes straight to the sugar bowl, and has the Lady's tea made without it, and the sugar thrown on the fire; and then she sits down on the edge of the saucer, and shakes, and you see that she is very frightened, and that she has been frightened, perhaps, for some days.".
    On discuss { Assert sugarSpilled(party). Retract poisonPotFull(pantry). Assert pyeSuspects(pye). }
  }
  Rule lady_drinks when day6() and hour(clock) >= 16 and poisonInSugar(hasp) and not sugarSpilled(party) and at(lady, tea_table) and not poisoned(lady) { Assert poisoned(lady). }
  Event poison_told within house when poisoned(lady) "At ten past four the Lady takes her tea, with sugar, two spoons. At half past she says the cake tastes of almonds. At five she tries to stand, and cannot, and Mrs Pyecroft's voice goes up and up, calling for somebody, for anybody, in a house where nobody of her size has ever answered.".
  Rule poison_kills when poisoned(lady) and hour(clock) >= 23 and not ladyDead(lady) { Assert ladyDead(lady). }

  // ── The Moot ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // At two on the third day the Court sits in the parlour of the Small House with whoever of the Wainscot will come.
  // Three matters: the Hearth, the Lady, the cat. Whoever someone of the Wainscot vouches for may speak.
  Relation mootDecided(entity). Relation mootApproach(place). Relation bellVolunteer(group).
  Query vouched() means (hearthWarned(hollins) or kitNanMet(kit) or travelsWith(sorrel, party) or ratsPaid(party) or underfolkEntered(annet) or countersign(party)) and not soldOut(party).
  Rule moot_gathers when day3() and hour(clock) >= 13 and not occasionBegun(moot) { Assert at(honor, small_house_parlour). Assert at(kit, small_house_parlour). }
  Rule moot_hasp when day3() and hour(clock) >= 13 and not occasionBegun(moot) and not at(hasp, small_house_parlour) and not haspStands(hasp) { Assert at(hasp, small_house_parlour). }
  Rule moot_hasp_home when (occasionOver(moot) or dayN(hollins) >= 4) and at(hasp, small_house_parlour) { Assert at(hasp, pantry). }
  Rule moot_bet when day3() and hour(clock) >= 13 and not occasionBegun(moot) and hearthWarned(hollins) and not at(bet, small_house_parlour) { Assert at(bet, small_house_parlour). }
  Rule moot_bet_home when occasionOver(moot) and at(bet, small_house_parlour) and not refugeesHoused(hollins) { Assert at(bet, skirting). }
  Rule moot_bet_up when occasionOver(moot) and at(bet, small_house_parlour) and refugeesHoused(hollins) { Assert at(bet, nursery_floor). }
  Observe moot_scene at small_house_parlour when occasionBegun(moot) and not occasionOver(moot) "The parlour of the Small House is packed to the walls: Laceys in their good chairs round the table, and behind them, standing, on the stair, in the hall, in the doorways, the Wainscot: colliers black from the Hearth, Readers with ink on their cuffs, Jarmen with pins, the Post in green caps, a Winder in black. Dame Honor sits at the head with her chain of buttons. Mr Ambry stands behind her with the Forms under his arm, all nine volumes, in case.".
  Occasion moot "the Moot" at small_house_parlour when day3() and hour(clock) >= 14 {
    Matter m_hearth "Dame Honor raps the table with a thimble. 'The first matter: the Hearth. Eighty souls on the Skirting with what they could carry. They cannot go back into the grate while she burns it. Where are they to go?' A Lacey cousin says the Hall is very large. Somebody laughs, not kindly." for 40 minutes until mootDecided(m_hearth).
    Matter m_lady "'The second matter,' says Dame Honor, and the parlour goes quiet, 'is Her. What the Wainscot is to do. Hide, as we have always hidden; or go, while there is a ladder; or,' and she stops, and goes on, 'or make ourselves known.'" for 40 minutes until mootDecided(m_lady).
    Matter m_cat "'The last matter,' says Dame Honor, and sighs, 'is the cat.' There is a murmur of the deepest feeling. 'It has been proposed,' she reads from a paper, 'by the Nail, and seconded by the Risers, that the cat be belled, so that it may be heard coming.' A roar of agreement. 'Carried,' says Dame Honor. 'Who will bell it?' And the parlour, all at once, finds the carpet very interesting." for 40 minutes until mootDecided(m_cat).
    Closes "Dame Honor raps the thimble on the table, and the Moot is over, and the Wainscot goes out of the Small House and down the Stair in silence, past the dappled flank of the rocking horse, which creaks.".
  }
  Rule moot_mute at small_house_parlour when occasionBegun(moot) and not occasionOver(moot) and at(party, small_house_parlour) and not vouched() and not mootMuteSaid(party)
    says "When you open your mouth Mr Ambry is at your elbow at once. 'The outsider has no voice in the Moot,' he says, not unkindly, 'unless someone of the Wainscot speaks for them. That is the Form.' Nobody here speaks for you." { Assert mootMuteSaid(party). }
  Relation mootMuteSaid(group).
  Measure mootOpenedAt(entity).
  Rule moot_opened when matterOpen(?m) and mootOpenedAt(?m) == 0 { Set mootOpenedAt(?m) to watch(clock) + 3. }
  Query mootHeard(m: entity) means matterOpen(m) and mootOpenedAt(m) > 0 and watch(clock) >= mootOpenedAt(m).
  // The Hearth.
  Action speak_hearth(actor: group, site: place) "Speak for taking the colliers into the Small House and up into the Nursery" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, small_house_parlour) and matterOpen(m_hearth) and vouched() and not kitNanMet(kit) and not mootDecided(m_hearth).
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert refugeesHoused(hollins). Assert mootDecided(m_hearth). }
    On failure { Assert mootDecided(m_hearth). }
    Result "You tell them what the Skirting looks like tonight, and how many children, and that the Nursery is the one floor in the house she has not lit a fire on. The Laceys look at each other. Then Dame Honor says, very drily, 'The Small House has four attics and a nursery floor as wide as a moor, and it has been empty of anyone but Laceys for three hundred years. I find I am tired of it.' She raps the thimble. 'The colliers come up.'".
    Otherwise "You speak, and they listen politely, and at the end a Lacey uncle says that the Small House is the Child's gift and not a lodging-house, and enough of the table murmur to carry it. Dame Honor does not look at you. The colliers stay on the Skirting.".
  }
  Rule moot_kit at small_house_parlour when matterOpen(m_hearth) and kitNanMet(kit) and not mootDecided(m_hearth) and at(nan, small_house_hall)
    says "Kit Lacey stands up at the foot of the table before anyone else can, which he has never done in his life. 'The colliers come up,' he says. 'Into the Small House. All of them.' His aunt looks at him. 'Nan Collier is one of them,' he says, 'and I am going to marry her, and so I am not having my wife's people sleep in a gap in the skirting while there's four empty attics over my head.' The parlour is absolutely silent. Then Dame Honor says, 'I see,' and raps the thimble. 'Carried.'" { Assert refugeesHoused(hollins). Assert mootDecided(m_hearth). }
  Rule moot_hearth_lapses at small_house_parlour when mootHeard(m_hearth) and not mootDecided(m_hearth) and not kitNanMet(kit)
    says "Nobody stands. After a while a Lacey uncle says that the Small House is the Child's gift and not a lodging-house, and enough of the table murmur to carry it. The colliers stay on the Skirting." { Assert mootDecided(m_hearth). }
  Rule refugees_up when refugeesHoused(hollins) and at(bet, skirting) { Assert at(bet, nursery_floor). }
  Rule refugees_up_nan when refugeesHoused(hollins) and at(nan, skirting) { Assert at(nan, nursery_floor). }
  // The Lady.
  Rule moot_jarl at small_house_parlour when matterOpen(m_lady) and at(hasp, small_house_parlour) and haspPlots(hasp) and not jarlSpoke(hasp)
    says "Hasp Tallowby stands up at the back with his pin. 'Make ourselves known,' he says. 'To her. My boy made himself known to her trap.' The parlour goes cold. 'She's old and she's blind and she's dying. Let her die quicker. Then the house is ours, as it always was.' Nobody answers him. Dame Honor looks at her hands." { Assert jarlSpoke(hasp). }
  Relation jarlSpoke(group).
  Action answer_jarl(actor: group, site: place) "Answer the Jarl before the Moot" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, small_house_parlour) and matterOpen(m_lady) and jarlSpoke(hasp) and vouched() and not haspStands(hasp) and not answeredJarl(party).
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert haspStands(hasp). Assert answeredJarl(party). }
    On failure { Assert answeredJarl(party). }
    Result "You answer him, in front of all of them: that she did not lay the trap and does not know his son's name; that the house is not theirs and never was, and would be less theirs, not more, with her dead and her cousin's lawyers on the doorstep. And then, because it is true, that you are sorry about Wat. Hasp looks at you across the parlour. Then he sits down, heavily, and puts his pin across his knees, and does not say anything else; and the Jarmen round him look at each other.".
    Otherwise "You answer him, and he hears you out, and says, 'You're not from here,' and sits down; and you can see that it has made no difference at all.".
  }
  Relation answeredJarl(group).
  Action speak_ladder(actor: group, site: place) "Tell the Moot that Bootscrape will take them in, if they must go down the ladder" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, small_house_parlour) and matterOpen(m_lady) and vouched() and knows(actor, bootscrape_shelter) and not evacPlanned(hollins).
    Time 1.
    On success { Assert evacPlanned(hollins). }
    Result "You give them Jory Mudge's words. The lofts and the barns and the Mat's cellar. The parlour stirs: nobody in the Wainscot has ever been offered anything by the outside, except bread for pins. Faith Penny says, 'The Post will keep a list of who goes,' and Ma Riser says, 'The ladders'll take them down free,' and Dame Honor, having rapped the thimble twice for no reason, says: 'Then if it comes to it, we go. The Court will give the word.'".
  }
  Action speak_known(actor: group, site: place) "Urge the Moot to make itself known to her" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, small_house_parlour) and matterOpen(m_lady) and vouched() and (knows(actor, diary_laceys) or primed(lady) >= 1) and not mootApproach(hollins).
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert mootApproach(hollins). Assert mootDecided(m_lady). }
    On failure { Assert mootDecided(m_lady). }
    Result "You tell them what the diary says, or what the chart said back, or both: that she was a child who was told she was lying, and believed it, and has come home not knowing. That the Wainscot is not hiding from a monster but from someone who once put the Laceys in her own house with her own hands. Dame Honor is very still. At the end she says, to the table, not to you: 'Three hundred years we have said she would come back for us. It seems she has, and does not know it.' She raps the thimble. 'The Court will make itself known, when the way is found.'".
    Otherwise "You tell them, and they hear you, and it is too strange and too late. 'We hide,' says Dame Honor at last, 'as we have always hidden. It has kept us alive.' The thimble comes down.".
  }
  Rule moot_lady_lapses at small_house_parlour when mootHeard(m_lady) and not mootDecided(m_lady) 
    says "In the end Dame Honor raps the thimble. 'We hide,' she says, 'as we have always hidden. It has kept us alive.'" { Assert mootDecided(m_lady). }
  // The cat.
  Action volunteer_bell(actor: group, site: place) "Say that you will bell the cat" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, small_house_parlour) and matterOpen(m_cat) and not belled(bishop) and not bellVolunteer(party).
    Time 0.
    On success { Assert bellVolunteer(party). Assert mootDecided(m_cat). }
    Result "Every head in the parlour turns. There is a long silence, of the kind that happens in a room where everyone has been let off something. Then Mab Tenter, at the back, begins to clap, slowly, and then the colliers, and then everyone; and Mr Ambry, deeply moved, writes your name in the margin of the ninth volume of the Forms, under CAT, BELLING OF. 'There is a sleigh bell in the toy box,' says Dame Honor. 'It was hers. It will do.'".
  }
  Rule moot_cat_belled at small_house_parlour when matterOpen(m_cat) and belled(bishop) and not mootDecided(m_cat)
    says "Before anyone can fail to answer, Mab Tenter says from the back: 'It's belled. I heard it this morning, ringing on the Stair like a sleigh. She put it on him herself.' A long silence. 'Minuted,' says Dame Honor faintly, and Mr Ambry, who had been turning to CAT, BELLING OF in the ninth volume of the Forms, closes it with a sound of real grief." { Assert mootDecided(m_cat). }
  Rule moot_cat_lapses at small_house_parlour when mootHeard(m_cat) and not mootDecided(m_cat)
    says "Nobody speaks. Somebody coughs. 'It is minuted,' says Dame Honor at last, without expression, 'that the cat is to be belled.' Mr Ambry writes it down." { Assert mootDecided(m_cat). }
  Relation bellRewarded(group).
  Topic honor_bell_done with honor "Tell Dame Honor Lacey the cat is belled" when belled(bishop) and bellVolunteer(party) and not bellRewarded(party) once {
    Says "Dame Honor looks at you for a long moment as if she were adjusting something in her estimate. 'Mr Ambry,' she says, and he comes in with a little purse of horn buttons, which he counts into your hands one by one: six, the Court's minting, good in every shop in the Wainscot, and at Ottoline Fogg's for coin. 'The Court is obliged,' says Dame Honor. 'The Nail will tell its children about you for a hundred years, which is a responsibility. Try to deserve it.'".
    On discuss { Assert bellRewarded(party). Increase quantity(actor, gold) by 6. }
  }
}

data/adventures/hollins/pye.kyr:
Module hollins "Behind the Wainscot" {
  // ── Mrs Pyecroft ───────────────────────────────────────────────────────────────────────────────────────────────────────
  // Dorothea Pyecroft, sixty-one, a vicar's widow from a market town, the Lady's companion twenty-two years and unpaid
  // eleven of them. She is of our size, and has been looked down on all her life by something larger; she looks down
  // on rats. She has sold the house for stone, on commission, to provide for herself, and wants it to be rats.
  Person pye "Mrs Pyecroft" at hatbox {
    Role "the Lady's companion". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Likeness "official".
    Greets "A small upright woman in black, with a pen behind her ear and a face that has been patient for a long time on purpose, looks at you as she would look at a bill. 'Yes?'".
    Greets again "Mrs Pyecroft looks at you as she would look at a bill she has already paid once.".
    Buys tail_kind for 3 coin.
    Objects "Mrs Pyecroft looks at {?i} in your hands, and then at you, and her face closes like a purse.".
  }
  Topic pye_lady with pye "Ask Mrs Pyecroft about Miss Whitbread" when true once {
    Says "'She is the most accomplished woman in Imbar,' says Mrs Pyecroft, without warmth or irony, as a fact. 'Her charts are in every harbour-master's office from here to the ice. Admirals write to her. Wrote.' She straightens a cuff. 'She cannot see to read now, so I read. She cannot see to write, so I write. She cannot see the stair, so I tell her where it is.' A pause. 'She has come home to draw this house before she dies, and she cannot see it, and she will not be told she cannot.' Another pause, shorter. 'She hears things in the walls.'".
  }
  Topic pye_self with pye "Ask Mrs Pyecroft about herself" when true once {
    Says "Mrs Pyecroft looks at you as if nobody had asked her that in some time, which is the case. 'A vicar's widow,' she says. 'Market Lambury. Twenty-two years ago Miss Whitbread advertised for a companion of the small size, steady, able to write a fair hand and climb a ladder.' Her mouth twitches. 'I could do all three. I have lived in her pocket since. I have seen every coast in Imbar from her shoulder, and slept in a hatbox on a dressing table in nine countries.' She stops. 'It is a great privilege,' she says, in a voice that has said it often, to itself.".
    On discuss { Assert knows(actor, pye_life). }
  }
  Discovery pye_life "Mrs Pyecroft, a vicar's widow from Market Lambury, has been the Lady's companion for twenty-two years, living in her pocket and sleeping in a hatbox, and calls it a great privilege.".

  // What she wants of the ratcatcher: the nest.
  Relation soldOut(group).
  Topic pye_nest with pye "Tell Mrs Pyecroft where the vermin nest: behind the Hall skirting, and in the doll's house" when hiredBy(actor, pye) and knows(actor, wainscot_told) and not soldOut(party) and not pyeTurned(pye) once {
    Grave "She will believe you, and act on it.".
    Says "Mrs Pyecroft writes it down: behind the skirting of the Hall, along its whole length; the grate; the doll's house. Her pen does not hesitate. 'The doll's house,' she says. 'I knew it. The bed slept in.' She blots the page and counts ten coins onto the table. 'That is worth more to me than any number of tails.' Then she looks up, sharply, as if something in your face had told her more than you said. 'Rats,' she says. 'Yes? Rats.' And waits for you to say it.".
    On discuss { Assert soldOut(party). Increase quantity(actor, gold) by 10. Assert poisonLaid(skirting). }
  }
  Observe court_shut at small_house_hall as sign when soldOut(party) and knows(party, court_told) "The front door of the Small House is barred from inside, and someone has hung a sheet over the parlour window, and written on it, in charcoal, for you: RATCATCHER.".

  // Her ledger, read, and put to her.
  Relation pyeConfronted(group). Relation pyeCowed(group).
  Topic pye_ledger_put with pye "Tell Mrs Pyecroft you have read her ledger" when knows(actor, pye_ledger) and not pyeConfronted(pye) and not pyeTurned(pye) and not pyeGone(pye) once {
    Says "Mrs Pyecroft goes white, and then two spots of red come up on her cheekbones, exactly round. 'You have been in my box,' she says. 'Among my things.' She folds her hands, which are shaking, and holds them still. 'Very well. Four hundred and forty crowns. Eleven years. When she dies there will be a cousin who has never met her, and a lawyer, and I shall be put out on the doorstep of a house in a country where I know nobody, at sixty-one, with my clothes in a bandbox.' She lifts her chin. 'The Concern will pay me forty crowns a year for the rest of my life. That is what I have arranged. I would do it again.' And then, much lower: 'She has never asked me one thing about myself. Not one. In twenty-two years.'".
    On discuss { Assert pyeConfronted(pye). Assert knows(actor, pye_reasons). }
  }
  Discovery pye_reasons "Mrs Pyecroft sold the house for stone because she will be put out with nothing when the Lady dies, unpaid eleven years; and because in twenty-two years the Lady has never once asked her anything about herself.".
  Action threaten_pye(actor: group, site: place) "Tell Mrs Pyecroft you will take her ledger to Mr Salcombe unless she gives up the sale and the sulphur" {
    Speaker pye.
    Requires able(actor) and company(actor) and at(actor, site) and at(pye, site) and pyeConfronted(pye) and not pyeTurned(pye) and not pyeCowed(pye) and not threatenedPye(party).
    Resolve check(actor, intimidation, dc_fair).
    On success { Assert pyeCowed(pye). Assert trapGivenUp(pye). }
    On failure { Assert threatenedPye(party). }
    Result "She looks at you a long moment with real hatred, and you see her count it up: the ledger, Salcombe, the county, gaol. 'Very well,' she says. 'No sulphur. I shall write to the Concern.' She turns her back. 'And when she dies I shall have nothing, and that will be your doing, and I hope you sleep.'".
    Otherwise "'Take it to him,' says Mrs Pyecroft. 'She signed it. It is her hand. You will find Mr Salcombe knows the difference between a scandal and a crime.' She does not believe it, quite; but neither, quite, do you.".
  }
  Relation threatenedPye(group).
  Action pay_pye_sovereign(actor: group, site: place) "Give Mrs Pyecroft the Whitbread sovereign, for her wages" {
    Speaker pye.
    Requires able(actor) and company(actor) and at(actor, site) and at(pye, site) and pyeConfronted(pye) and carries(actor, sovereign) and not pyeTurned(pye).
    On success { Spend sovereign from actor. Assert pyeTurned(pye). Assert trapGivenUp(pye). }
    Result "Mrs Pyecroft looks at the gold in your arms, a foot across, and knows it at once: the green purse, the bedside table. Her mouth opens. 'You stole it,' she says. And then, as you put it down in front of her: 'For me.' She sits down on her narrow bed. She puts both hands on the coin, flat, as if to warm them. 'Thirty crowns,' she says. 'It is not four hundred and forty.' A long breath. 'It is the first thing anyone has given me in twenty-two years without my writing it down first.' She looks up. 'No sulphur,' she says. 'I'll write to the Concern tonight. I had not liked it. I want you to know that. I had not liked it at all.'".
  }
  Topic pye_understand with pye "Tell Mrs Pyecroft that you would ask her, if no one else will: what does she want?" when pyeConfronted(pye) and knows(actor, pye_reasons) and not pyeTurned(pye) and not pyeCowed(pye) once {
    Says "Mrs Pyecroft stares at you. Then she laughs, short and hard, and then she is not laughing. 'A cottage,' she says. 'With a door my size. A garden I can see the end of. Somebody to say good morning to who is not up in the air.' She wipes her eyes with the back of her wrist, fiercely, as if they had done it on purpose. 'And for her to know I was there. Twenty-two years. I'd like her to know I was there.' She sits very straight. 'If she knew. If she provided. I should not need the Concern.' She looks at you. 'But she does not know anything, does she. She can't see.'".
    On discuss { Assert knows(actor, pye_wants). }
  }
  Discovery pye_wants "Mrs Pyecroft wants a cottage with a door her size, and for the Lady to know she was there; if the Lady provided for her, she would not need the Concern.".
  Promise pye_promise "to have the Lady provide for Mrs Pyecroft" to pye
    kept when saleRevoked(lady) or pyeProvided(pye) "Mrs Pyecroft has a paper in her desk in the Lady's huge slanting hand, and reads it, they say, every evening."
    broken when ladyDead(lady) and not saleRevoked(lady) and not pyeProvided(pye) "Somewhere a small woman in black packs a bandbox.".
  Relation pyeProvided(group).
  Topic pye_promise_made with pye "Promise Mrs Pyecroft that the Lady will provide for her, if she gives up the sulphur and the sale" when knows(actor, pye_wants) and not pyeTurned(pye) and not promiseMade(pye_promise) once {
    Says "Mrs Pyecroft looks at you for a long time. 'You think you can make her see,' she says. 'Where I have been reading to her for eleven years.' She considers. 'Very well. I will wait. No sulphur, while I wait.' She picks up her pen. 'But the Concern has my letter, and the paper is signed. If she dies not knowing, it goes ahead whether I like it or not.'".
    On discuss { Assert promiseMade(pye_promise). Assert pyeWaits(pye). }
  }
  Relation pyeWaits(group).
  Topic lady_pye with lady "Tell the Lady that Mrs Pyecroft has served her twenty-two years, unpaid for eleven" when ladyKnows(lady) and knows(actor, pye_life) and not pyeProvided(pye) and not saleRevoked(lady) once {
    Says "'Eleven,' says the Lady. 'Unpaid.' She turns her head, slowly, to where Mrs Pyecroft stands on the inkwell's rim. 'Dorothea. Is that so?' 'Yes, Miss Whitbread.' A long silence. 'Where were you born, Dorothea?' Mrs Pyecroft's mouth opens, and stays open. 'Market Lambury,' she says at last, in a voice nobody has heard her use. 'There is a green, and a pond. My father kept bees.' 'Bees,' says the Lady. 'Then you shall have bees.' And she writes it there and then on the corner of her chart, large: TO D. PYECROFT, FOUR HUNDRED AND FORTY CROWNS AND A COTTAGE WITH BEES.".
    On discuss { Assert pyeProvided(pye). Assert pyeTurned(pye). }
  }
}

data/adventures/hollins/wainscot.kyr:
Module hollins "Behind the Wainscot" {
  // ── The Wainscot ──────────────────────────────────────────────────────────────────────────────────────────────────
  // Behind the skirting of the Hall, between the board and the wall, a town: lanes of lath, stairs cut in the plaster,
  // shops in the gaps where the board has warped, and the Nail, an inn built round a giant's nail driven into a stud.
  // It runs the length of the Hall and on round into the walls of the drawing room and the kitchen.
  Place skirting "the Skirting" is room within ground_floor at 2, 0.
  Place button_market "the Button Market" is room within ground_floor at 1, 1.
  Place nail_room "the Nail" is room within ground_floor at 1, 2.
  Place bell_walk "the Bell Walk" is room within ground_floor at 3, 2.

  Passage hall_gap "the gap under the skirting" is crawl between hall_flags and skirting.
  Passage drift_lane "the lane from the drift into the walls" is passage between letterdrift and skirting taking 5 minutes.
  Passage market_lane "Lath Lane" is passage between skirting and button_market taking 5 minutes.
  Passage nail_lane "the stair down to the Nail" is steps between button_market and nail_room.
  Passage bell_lane "the way into the Bell Walk" is passage between skirting and bell_walk taking 10 minutes.

  Observe skirting_scene at skirting when true "Behind the skirting board, in the dark between the board and the wall, a street. The board is the street's one side, a cliff of painted oak with its paint flaking in sheets; the wall is the other, plaster over lath, and into the plaster people have cut doorways and windows and stairs. Candle-ends burn in niches. Washing hangs on thread. There is a smell of soup and tallow and three hundred years of other people's dust, and a great many people, all talking quietly, the way people talk in a house where somebody is ill.".
  Observe skirting_refugees at skirting as sign when hearthBurned(hollins) and not refugeesHoused(hollins) "All down the Skirting, in every doorway and under every stair, colliers from the Hearth: black to the eyes, wrapped in whatever they got out with, children asleep on bundles. A woman is going along them with a pot and a ladle. There is not enough in the pot.".
  Observe skirting_poison at skirting as sign when poisonLaid(skirting) "Somebody has chalked a skull on the board every few yards, and under each skull a heap of bread spread with grey paste has been swept into a sack. The sack has POISON on it, and DON'T, in a child's capitals.".
  Observe skirting_smoked at skirting as sign when smoked(hollins) and not evacuated(hollins) "The Skirting is silent. The candle-ends have gone out in their niches. There is a yellow stain on the plaster at the height of your knee, all the way along, like a tidemark, and a smell of rotten eggs, and nobody, anywhere, talking.".
  Observe skirting_emptied at skirting as sign when smoked(hollins) and evacuated(hollins) "The Skirting is empty, every door open, washing still on the threads. There is a yellow stain on the plaster at the height of your knee, all the way along, like a tidemark; and nobody under it.".

  // ── The Button Market ─────────────────────────────────────────────────────────────────────────────────────────────
  Observe market_scene at button_market when true "Where the skirting board has warped away from the wall the street widens into a market: stalls under awnings of envelope paper, a well that is a giant's thimble sunk in the floor and kept full from the Sink, and everywhere buttons. Buttons as tables, as wheels, as roofs, as shields; buttons in a bin, sorted by size, smallest first; and at the far end a long counter made of a single bone button, where Ottoline Fogg sits under a sign that says BUTTONS BOUGHT, OUTSIDE GOODS SOLD, NO CREDIT, NO CHEESE.".
  Person ottoline "Ottoline Fogg" at button_market {
    Role "the button-factor of the Wainscot". Ancestry gnome. Peaceable. Pronouns she. Manner acerbic.
    Likeness "merchant".
    Greets "A very old gnome-woman in a coat sewn all over with shirt-buttons, like scales, looks you up and down. 'Outside goods,' she says, with relish. 'A body your size come in by the Slot carries the dearest things in the house, and doesn't know it. Every cup that fits a hand, every needle that's not a spear. In here a thimble's a well. A needle is a jewel.'".
    Greets again "'Back to sell me your boots?' says Ottoline Fogg.".
    Sells lantern for 4 coin from 2.
    Sells candle for 1 coin from 10.
    Sells bandages for 1 coin from 6.
    Sells rope for 3 coin from 3.
    Sells hollins_honey_kind for 2 coin from 4.
  }
  Kind hollins_honey_kind "a pot of Whitbread honey" is gear worth 2 weighing 1 described "A clay pot of honey cut from a giant's honey-jar in the Pantry, three hundred years old and as good as the day it was put up: dark, thick, tasting of heather. Honey never spoils; the Wainscot has lived on it.".
  Topic ottoline_buttons with ottoline "Ask Ottoline Fogg why buttons" when true once {
    Says "'Because they can't be made,' says Ottoline Fogg. 'Bread can be made, of her flour. Cloth can be made, of her thread. Rope, of her string. But a button is a button. There's so many in the house and no more, and when they're spent they're spent, so a button's worth what it's worth.' She taps the bone counter. 'The Court mints them. Pins are the Jarmen's. Coin from outside is better than both, because it comes from somewhere there's more of it.' She smiles, all gums. 'Economy. Nobody in there understands it but me and the Jarl.'".
  }
  Topic ottoline_lady with ottoline "Ask Ottoline Fogg what the Lady's coming means for trade" when true once {
    Says "'Ruin,' says Ottoline cheerfully. 'Or a fortune. A warm house means the cress grows on the sill, so bread's down. The fire burned out the colliers, so coal's up. The Jarmen are saying the Pantry's hers again, so honey's up.' She leans over. 'And if she's to be gone in a week, and the house sold for stone, then buttons are worth nothing at all, because there'll be no house to spend them in.' She sits back. 'Which is what I'm buying on. I've a cart in Bootscrape. I'm not a sentimental woman.'".
    On discuss { Assert knows(actor, sale_rumour). }
  }
  Discovery sale_rumour "Ottoline Fogg has heard in Bootscrape that the house is to be sold for stone once the Lady is gone, and has a cart waiting in the village.".

  // ── The Nail ──────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe nail_scene at nail_room when true "The Nail is an inn built round a nail: a giant's iron nail as thick as an oak, driven through the lath into a stud three hundred years ago and rusted to the colour of bread-crust. Rooms are hung off it on brackets, up and round, like nests. Below, a long table, a hearth made of a giant's tinder-box, a smell of mutton broth. Over the hearth, a portrait cut out of a giant's newspaper: a man in a periwig, captioned THE LATE KING ALDO, whom nobody living here has any idea about.".
  Person mab "Mab Tenter" at nail_room {
    Role "who keeps the Nail". Profession innkeeper. Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Likeness "innkeeper".
    Greets "A thin woman with a black ribbon on her sleeve looks up from ladling. 'Bed's a button a night, or a coin, the broth comes with it. Don't go out on the flagstones after nine.' She says it the way people say a thing they say to everyone. Then, differently: 'Don't.'".
    Greets again "Mab Tenter nods, and puts another bowl on the table without being asked.".
    Sells rations for 2 coin from 8.
  }
  Topic mab_ribbon with mab "Ask Mab Tenter about the ribbon on her sleeve" when true once {
    Says "'My boy,' says Mab Tenter. 'Ezra's and mine. Joss. Nine. The first night she came, he went out on the flagstones to see her, because everybody had been saying all his life that one day she'd come.' She goes on ladling. 'The cat had him. Didn't kill him. Played with him all night, on the flagstones, by the drift, where we could hear it.' She puts the ladle down. 'They say she can't see. They say she doesn't know we're here. I don't care. I want it to stop.'".
    On discuss { Assert knows(actor, joss_taken). }
  }
  Discovery joss_taken "Joss Tenter, nine, Mab Tenter's son, went out on the Hall flagstones to see the Lady the night she came, and her cat played with him till he died.".
  Topic mab_house with mab "Ask Mab Tenter how the Wainscot lives" when true once {
    Says "'Off her,' says Mab. 'What else. Flour from the bins, thread from the workbox, honey from the Pantry if the Jarmen let you have it. The Sink for water, a thimble at a time. The Court in the doll's house keeps order, after a fashion, and mints buttons. The Readers read. The Keys play. The Post enters everybody.' She shrugs. 'It's a life. It was cold. Cold and dim and quiet, and we didn't know any better.' She looks at the warm wall. 'Now it's warm, and we're dying of it.'".
  }

  // ── The Bell Walk; Kit and Nan ────────────────────────────────────────────────────────────────────────────────────
  // The servants' bells: a wire runs from every bell-pull in the house through the walls to the bell-board in the
  // kitchen. The wires carry notes. Kit Lacey of the Small House and Nan Collier of the Hearth have courted along them
  // for two years, and have never been in a room together.
  Observe bellwalk_scene at bell_walk when true "Inside the wall, a narrow walk along a run of iron wires, each as thick as a finger, going away into the dark on pulleys: the bell-wires, one from every room in the house to the board in the kitchen. They are labelled, where they pass, in faded giant's paint: DRAWING ROOM. NURSERY. MISS E.'S ROOM. Little scraps of paper are tied to the wires here and there, like leaves.".
  Observe bellwalk_note at bell_walk as feature when hearthBurned(hollins) and not noteRead(party) "On the NURSERY wire, just where it crosses the DRAWING ROOM wire on a pulley, a folded note is tied with blue thread.".
  Relation noteRead(group).
  Action read_note(actor: group, site: place) "Untie the note on the Nursery wire and read it" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bell_walk) and hearthBurned(hollins) and not noteRead(party).
    Time 0.
    On success { Assert noteRead(party). Assert knows(actor, kit_nan). }
    Result "It is written in a careful, schooled hand, on paper cut from a giant's laundry list: N. — The fire was lit at nine. They say the Hearth is burned out. I have pulled the wire every hour since and you do not pull back. If you are alive, pull twice. If you are not, I shall know, and I shall come down, whatever my aunt says. — K. And under it, in pencil, in another hand, very large, as if written in a hurry or in the dark: TWICE. You tie it back.".
  }
  Discovery kit_nan "Kit Lacey of the Small House and Nan Collier of the Hearth write to each other along the servants' bell-wires inside the walls, and have never met.".
  Topic mab_kit with mab "Ask Mab Tenter about Kit Lacey and Nan Collier" when knows(actor, kit_nan) once {
    Says "Mab almost smiles. 'Everybody knows but Dame Honor,' she says. 'Two years, along the wires. The Lacey heir and a collier's girl from the grate. They've never been in a room. Nan's never been up the Stair, and Kit's never been allowed down it.' She wipes the table. 'Bet Collier would skin her. Dame Honor would lock him in the doll's house attic. It's the only nice thing that's happened in this house in my lifetime, and nobody's allowed to know about it.'".
    On discuss { Assert knows(actor, kit_nan_secret). }
  }
  Discovery kit_nan_secret "Everyone in the Wainscot knows about Kit Lacey and Nan Collier except Dame Honor, who would lock him up, and Bet Collier, who would skin her.".
}

data/adventures/hollins/winders.kyr:
Module hollins "Behind the Wainscot" {
  // ── The Winders' account: ten past four, and the twelfth notch ────────────────────────────────────────────────────
  // The count: the days the Long Clock has stood at ten past four (three hundred and twelve years of them). The keepers:
  // the Winders, who oil and never wind. The first page: a child of eleven, sent out of the house at that minute, who
  // meant to scratch her twelfth birthday on the plinth when she came home. The price of reading it aloud: the Winders'
  // whole faith, which the Prior pays gladly and Sister Verity cannot. A domestic book; its danger is a cat, a fire and
  // a cup of sugar, each with its ways round (the bell, the catmint, the drift; the warning, the lamp-oil, the cold hearth;
  // the spilled sugar, the stopped jar), and the Clock is its kept light.

  // ── Depth: things everyone does and no one can explain ────────────────────────────────────────────────────────────
  Observe quiet_minute at button_market when hour(clock) == 16 "At ten past four the whole Button Market drops its awnings together, and every stall-keeper stands with hands behind the back for the count of sixty. When the minute is out the awnings go up, and a man who was haggling over a thimble goes on haggling from exactly the word he stopped at.".
  Observe quiet_notice at skirting as sign when true "A card is tacked to a lath-post at the mouth of Lath Lane, in a careful hand, with a hole in each corner where it has been moved from post to post: STALLS CLOSE AT TEN PAST FOUR FOR ONE MINUTE. NO BARGAINING. NO DISCOUNT FOR THE INCONVENIENCE.".
  Observe oil_smell at clock_foot as feature when true "The air under the Clock smells of whale-oil, old brass, and wet wool: the Winders' gowns, which are never quite dry because the case holds the cold. Somewhere in it, very faint, a smell of candle-wax and boiled sweets, which nobody has been able to account for since the Going.".
  Observe hall_claws at hall_flags as feature when true "The flagstones are scored in long parallel strokes, each set of four as far apart as a man's reach, running from the foot of the Stair toward the drift. They are the cat's, and they are three hundred years deep in places, in places new.".
  Discovery notch_tally "At the foot of the Long Clock's plinth, low, where only a child would reach, someone has scratched eleven notches in the oak and left a space for the twelfth." {
    Found by searching clock_foot "Low on the plinth, behind the velvet curtain of the Winders' door, where only a child would kneel: a row of notches scratched in the oak with a pin, eleven of them, evenly spaced, and a space after the eleventh the exact width of one more. Beside the row, so small it could be a flaw in the grain: E.".
  }
  Topic hasp_time with hasp "Ask Hasp Tallowby why the Jarmen and the Readers do not speak" when true once {
    Says "Hasp scratches under his hat. 'Two hundred years back we borrowed Volume T off the Readers' shelf,' he says. 'For the wrapping. Fine thin paper, good for honey-cakes. And the Readers have never forgiven it. They say the volume had Tides in it, and Tobacco, and Time.' He sniffs. 'We used Time. Went best of the three. Tides wouldn't hold the grease.' He lowers his voice. 'There's a leaf of it in the Prior's case this minute, I'd lay a button. Somebody had to give them something.'".
  }
  Topic gideon_wrap with gideon "Ask Gideon Lamb about the missing leaf of Time" when true once {
    Says "Gideon takes off his spectacles and cleans them on his sleeve for rather longer than they need. 'It was a very good leaf,' he says. 'The entry for Time begins, Time is that which, and the next page is where the Jarmen cut it. We have been reading that sentence for two centuries as if the rest of it were a courtesy.' He puts the spectacles back. 'If anyone were to find the rest, I would consider the quarrel closed.'".
  }
  // Contrast: a comic scene in a gentle house. Ottoline Fogg's weekly auction, the one thing in the Wainscot nobody tries to be sincere about.
  Observe button_auction at button_market when hour(clock) == 17 "Ottoline Fogg is on her bone counter with a pickle-fork for a gavel, auctioning a single mother-of-pearl button the size of a tea-tray to a crowd of eleven. 'The finest button in the Wainscot,' she is saying, 'cut from the cuff of a giant's christening robe. Do I hear four buttons? I hear five from the gentleman who is holding his own ear. Six! Sold, to the lady who has not stopped waving since Tuesday.' The lady has not been bidding. She is waving at her daughter. The button is carried off between four men.".

  // ── Voices by calling ─────────────────────────────────────────────────────────────────────────────────────────────
  Relation hvClockA(group). Relation hvClockB(group). Relation hvClockC(group). Relation hvHallA(group). Relation hvHallB(group).
  Relation hvFortA(group). Relation hvFortB(group). Relation hvKitchenA(group). Relation hvKitchenB(group). Relation hvBedA(group). Relation hvBedB(group). Relation hvNan(group).
  Rule hv_warrior_clock at clock_foot when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and at(party, clock_foot) and not hvClockA(party)
    says "{?m} walks round the plinth once and looks up at the case as a soldier looks at a siege-tower. 'Forty turns of the key and a weight that size,' {?m} says. 'You could set a garrison by it.'" {
    Assert hvClockA(party).
  }
  Rule hv_cleric_clock at clock_foot when memberOf(?m, party) and hasCalling(?m, calling_cleric) and awake(?m) and at(party, clock_foot) and not hvClockB(party)
    says "{?m} reads the painted words on the plinth with a lifted eyebrow, and then the velvet door, and then the little worn place on the boards where kneelers kneel. 'It is a chantry,' {?m} says. 'They have made a chantry of a clock, for a person who is not dead.'" {
    Assert hvClockB(party).
  }
  Rule hv_thief_clock at clock_foot when memberOf(?m, party) and hasCalling(?m, calling_thief) and awake(?m) and at(party, clock_foot) and not hvClockC(party)
    says "{?m} stands where the trunk's keyhole is, and measures it with a finger and thumb. 'The key to this is a ship's wheel,' {?m} says. 'You would have to be a very large person indeed to lose it, and a very small one to want to.'" {
    Assert hvClockC(party).
  }
  Rule hv_warrior_hall at hall_flags when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and at(party, hall_flags) and not hvHallA(party)
    says "{?m} goes down on one knee to the claw-marks and counts the sets with a gauntleted hand. 'Four to a stroke, eighteen foot of reach, always out from the Stair,' {?m} says. 'It comes down the Hall at a trot and turns at the clock.'" {
    Assert hvHallA(party).
  }
  Rule hv_ranger_hall at hall_flags when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, hall_flags) and not hvHallB(party)
    says "'Fish, and old fur, and something like warm bread,' {?m} says, breathing in, turning toward the drift. 'It likes it here. A year it has been coming, and nobody has fed it.'" {
    Assert hvHallB(party).
  }
  Rule hv_warrior_fort at fort when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and at(party, fort) and not hvFortA(party)
    says "{?m} stops at the drawbridge and looks the Regiment over rank by rank, as one soldier looks at another's. 'Keys wound to the same mark,' {?m} says. 'Heads dressed to the left.'" {
    Assert hvFortA(party).
  }
  Rule hv_bard_fort at fort when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, fort) and not hvFortB(party)
    says "{?m} tilts an ear to the Captain's musical-box voice. 'It is a child's voice,' {?m} says. 'Played slow. Every order he gives is a sentence a child once said, in the order she said it, and they have been obeying her ever since.'" {
    Assert hvFortB(party).
  }
  Rule hv_thief_kitchen at kitchen_floor when memberOf(?m, party) and hasCalling(?m, calling_thief) and awake(?m) and at(party, kitchen_floor) and not hvKitchenA(party)
    says "{?m} looks at the pantry door for some time without going near it. 'Pins in the lintel,' {?m} says. 'Hair across the latch. A house this big, and the one door in it that is properly guarded is the one with honey behind it.'" {
    Assert hvKitchenA(party).
  }
  Rule hv_cleric_kitchen at kitchen_floor when memberOf(?m, party) and hasCalling(?m, calling_cleric) and awake(?m) and at(party, kitchen_floor) and not hvKitchenB(party)
    says "{?m} watches the Jarl's men carry a jar of honey across the tiles with their caps off. 'Grace,' {?m} says. 'They are saying a grace, under their breath, and not one of them knows to whom.'" {
    Assert hvKitchenB(party).
  }
  Rule hv_warrior_bed at counterpane when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and at(party, counterpane) and not hvBedA(party)
    says "'You do not talk,' {?m} says, very low, hands folded at the foot of the counterpane. 'You stay on your feet. You let her see someone is standing.'" {
    Assert hvBedA(party).
  }
  Rule hv_bard_bed at counterpane when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, counterpane) and not hvBedB(party)
    says "'Hush.' {?m} lifts a finger: the breath, the clock below, the faint clear note from the piano through the floor. 'The clock, the keys and her breath,' {?m} says, under all three. 'Same beat. Don't move.'" {
    Assert hvBedB(party).
  }
  Rule hv_nan_clock at clock_foot when following(nan, party) and at(party, clock_foot) and not hvNan(party)
    says "Nan Collier stops under the Long Clock with her black hands behind her back. 'We set the Hearth-bell by it before the Going,' she says. 'My gran said you could hear it from the grate if you held your breath. She said it was the sound of a person being sorry.' She looks up at the dark of the case. 'I never believed her. I'd like to now.'" {
    Assert hvNan(party).
  }

  // ── The warrior's word: a soldier gives the order that the Lady alone would otherwise give ──────────────────────────
  // The Regiment stands down for the Lady's word (lady_regiment), which she can give only once she knows them. A warrior
  // who has the Regiment's word and its orders can give a soldier's order the Captain knows the form of, long before. It
  // costs: the Regiment no longer keeps the Wainscot's night patrol, and the children's drum is not heard in the Skirting.
  Relation orderedEasy(group).
  Action order_stand_easy(actor: group, site: place, m: member) "Give the Regiment the order to stand easy, in the form the Colonel would have used" {
    Description "{m} knows how an order is given. It is not the Colonel's. It is the next best thing.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, fort) and at(ordinance, fort) and knows(actor, regiment_orders)
      and memberOf(m, actor) and hasCalling(m, calling_warrior) and awake(m) and not standDown(regiment) and not regimentStopped(regiment)
      and not regimentMarched(regiment) and not pyeStabbed(pye) and not orderedEasy(party).
    Time 3.
    On success { Assert orderedEasy(party). Assert standDown(regiment). Assert tolerates(regiment, party). Assert peaceable(regiment). }
    Result "{m} comes to attention at the edge of the courtyard, feet together, and says it plainly, in the voice of someone who has said it to better men: 'Regiment. The war is over. The Colonel is home. Stand easy.' Every head in the Fort turns. The Captain's sword comes down, very slowly, a degree at a time, until the point rests on the boards. 'THE COLONEL,' he says. A long whirr. 'IS HOME.' Then, to the ranks, in a smaller voice: 'REGIMENT. STAND EASY.' One by one they sit down on the courtyard floor with their muskets across their knees, and the drummer, uncertain, puts his sticks away in his belt as if he were putting away a toy.".
  }
  Observe skirting_no_drum at skirting as feature when orderedEasy(party) "In the Skirting the children, who have gone to sleep for three hundred years to a faint drum through the floor of the nursery, lie awake. Nobody has told them. A mother stands in a doorway with a lamp and listens, and does not know what she is missing.".
  Rule fate_regiment_word when accounting() and orderedEasy(party) and not fateTold(f_regiment) says "The Tin Regiment sits in its Fort with its keys still, by an order given in the one form it had waited for, and the children of the Wainscot, who liked the drum, have made one of their own out of a cotton-reel and play it at the Quiet. The Captain has been heard, on warm days, to whirr a word that sounds like home." { Assert fateTold(f_regiment). }

  // ── The Lady, told of the notches: the first page, and a chart lent ─────────────────────────────────────────────────
  Relation notchesTold(group).
  Kind hollins_lady_map_kind "a copy of the Lady's chart of the northern coast" like map worth 3 weighing 0 described "A sheet of ordinary paper, ruled by hand, a copy of the white-cliff coast in the north where the sea comes in green: a harbour with a mole, a village of a dozen crooked roofs, and a tower on a rock at the end of a long breakwater. Under the tower, in a hand a yard high, reduced: I WAS HAPPY HERE.".
  Item lady_map "the Lady's chart of the northern coast" is hollins_lady_map_kind at nowhere owned by lady.
  Topic lady_notches with lady "Tell the Lady about the eleven notches scratched at the foot of her clock" when ladyKnows(lady) and knows(actor, notch_tally) and not notchesTold(lady) once {
    Says "The Lady is quiet so long you think she has gone to sleep. Then she says, to the ceiling, 'Eleven.' A breath. 'I was eleven. I meant to do the twelfth on the day I came home, with my own pin, standing on the box.' Her hand moves on the counterpane, a boat adrift. 'They sent me to my aunt's in the coach at ten past four, and I stopped the clock with my finger on the way out so it would be the same day when I came back. I thought that was how time worked.' She laughs, a very small one. 'I came back at six on a Thursday, at fifty years' remove, and wound it, and it struck. I thought it was my own fault.' She turns her face toward you. 'Take the chart on the table. It's the coast I was happiest on. Somebody ought to have it who has been to look.'".
    On discuss { Assert notchesTold(lady). Give lady_map to actor. }
  }
  Rule fate_notch when accounting() and notchesTold(lady) and not fateTold(f_notch) says "The twelfth notch was scratched at the foot of the Long Clock on the Sunday after the funeral, in front of the Winders, by Prior Tobit Hale, kneeling, with a pin from the Lady's own workbox, to the surprise of nobody who had been told what the notches were for. He did not say anything. Sister Verity was seen to wipe the pin on her sleeve before she put it back." { Assert fateTold(f_notch). }
  Entity f_notch: fact "the twelfth notch".

  // ── Outward: a world event, read, and a hook for a stranger ──────────────────────────────────────────────────────────
  Observe chart_rose at chart_table when befell(rose_made_whole) "In the corner of the Lady's chart, in an ink newer than the rest, someone has drawn a compass-rose with all its points, and written under it, in the hand that wrote the whole of the house: made good this season, by someone else. The Lady has not told Mrs Pyecroft. She looks at it every morning at nine.".
  Topic jory_visitors with jory "Ask Jory Mudge who comes to Bootscrape from outside" when true once {
    Says "'Carriers,' says Jory. 'And the chandler's man from Wendle. And once a year a pilot off the southern coast, a lamp-keeper's cousin by his talk, who wants a chart off the Lady and has been waiting thirty years for her to be home to ask.' He lays a finger beside his nose. 'If a body wanted to come in under the notice of the house, Bootscrape is where they would have to start. The post goes by the Slot, and the Slot goes by us.'".
  }
}

data/adventures/house-that-grows/annex.k:
Module hhg "The House That Grows" {
  Description "The Annex: the wing of the house that fell into Haddo's barley, and the watchers on their stools around it.".

  Place annex "the room in the barley" is building within barley_field.
  Place barley "the flattened barley" is room within barley_field at 1, 1.
  Place haddo_well "Haddo's well" is room within barley_field at 2, 2.
  Place bedroom "the glass bedroom" is room within annex at 1, 1 indoors.
  Place cup_shelf "the cup shelf" is room within annex at 2, 1 indoors.
  Place coats_low "the hall of coats" is room within annex at 1, 0 indoors.
  Place root_cellar "the root cellar" is room within annex at 1, 2 underground.

  Passage barley_path "the line of flattened barley" is path between east_lip and barley taking 10 minutes.
  Passage well_path "the field edge" is path between barley and haddo_well.
  Passage small_door "the small door" is door between barley and bedroom.
  Passage shelf_door "the door to the cup shelf" is door between bedroom and cup_shelf.
  Passage coats_door "the door into the hall of coats" is door between bedroom and coats_low.
  Passage shelf_coats "the narrow door by the shelf" is door between cup_shelf and coats_low.
  Passage cellar_door "the low door in the floor" is door between bedroom and root_cellar.
  // When the root cellar has grown far enough it breaks into Haddo's well shaft.
  Passage well_breach "the seam in the well shaft" is crawl between root_cellar and haddo_well hidden until well_reached.
  Initially Assert dreamDoor(small_door). Initially Assert dreamDoor(shelf_door). Initially Assert dreamDoor(coats_door).
  Initially Assert dreamDoor(shelf_coats). Initially Assert dreamDoor(cellar_door).
  Initially Assert annexMouth(barley).

  Initially Assert houseRoom(bedroom). Initially Assert houseRoom(cup_shelf). Initially Assert houseRoom(coats_low).
  Initially Assert houseRoom(root_cellar).
  Initially Set bandLo(bedroom) to 1. Initially Set bandHi(bedroom) to 17.
  Initially Set bandLo(cup_shelf) to 18. Initially Set bandHi(cup_shelf) to 34.
  Initially Set bandLo(coats_low) to 35. Initially Set bandHi(coats_low) to 51.
  Initially Set bandLo(root_cellar) to 52. Initially Set bandHi(root_cellar) to 68.
  // The hall of coats is the room the house has in both bodies.
  Initially Assert copyOf(coats_low, coats_high). Initially Assert copyOf(coats_high, coats_low).

  // Every dream-door is shut to anyone looking at it.
  Thing small_leaf "the small door" on small_door {
    State shut blocking "The small door, the only door in the house at a person's height, is shut. It has eleven panes in three rows of four, with one missing at the top right where the handle comes through.".
  }
  Thing shelf_leaf "the door to the cup shelf" on shelf_door { State shut blocking "A tall glass door, shut.". }
  Thing coats_leaf "the door into the hall of coats" on coats_door { State shut blocking "A tall glass door, shut, with coats showing through it.". }
  Thing shelf_coats_leaf "the narrow door by the shelf" on shelf_coats { State shut blocking "A narrow glass door, shut.". }
  Thing cellar_leaf "the low door in the floor" on cellar_door { State shut blocking "A trap of green glass in the floor, shut, warm underfoot.". }
  Observe doors_wont at bedroom as revelation when tried(coats_leaf, pushing) or tried(shelf_leaf, pushing) or tried(small_leaf, pushing)
    "The door does not give. It is not stuck, or locked. It is waiting for you to stop looking at it." teaches doors_known.
  Discovery doors_known "The doors of the house do not open while anyone is looking at them. They open behind your back.".

  // ---- The watchers on the stools ----
  Person watchers "Cobble Ring's watchers" at barley {
    Role "watchers on stools round the glass, two widows and a stare-student". Ancestry human. Numbers 3. Peaceable.
  }
  Person pammu "Old Pammu" at barley {
    Role "an old watch-keeper with a hand-bell in his lap". Ancestry human. Peaceable.
  }
  Initially Assert watcher(watchers). Initially Assert watcher(pammu).
  Initially Assert post(watchers, barley). Initially Assert post(pammu, barley).
  Initially Assert overlooks(watchers, bedroom). Initially Assert overlooks(watchers, cup_shelf).
  Initially Assert overlooks(watchers, coats_low). Initially Assert overlooks(watchers, root_cellar).
  Initially Assert overlooks(pammu, bedroom). Initially Assert overlooks(pammu, cup_shelf).
  Initially Assert overlooks(pammu, coats_low). Initially Assert overlooks(pammu, root_cellar).
  Observe stools at barley as ambience when keepsWatch(watchers) "Round the glass room, on stools set in the flattened barley, Cobble Ring's watchers sit with their eyes on it: two widows with their knitting in their laps and not looking at it, and a stare-student counting panes under her breath.".
  Observe stools_drowse at barley as ambience when drowsing(watchers) "The watchers on the stools have their chins on their chests. One of the widows is snoring softly.".
  Observe stools_turned at barley as ambience when averted(watchers) "The watchers have turned their stools round, and sit with their backs to the glass.".
  // The visiting custom: a mark, and they turn their backs while the small door opens.
  Action pay_visit(actor: group, site: place) "Pay the watchers a mark to turn their backs while the small door opens" {
    Description "It is Cobble Ring's due. They turn back the moment you are through.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, barley) and at(watchers, barley)
      and keepsWatch(watchers) and quantity(actor, gold) >= 1.
    On success { Decrease quantity(actor, gold) by 1. Increase quantity(watchers, gold) by 1.
      Assert averted(watchers). Assert averted(pammu). Set avertedUntil(watchers) to watch(clock). Increase avertedUntil(watchers) by 3.
      Set avertedUntil(pammu) to watch(clock). Increase avertedUntil(pammu) by 3. }
    Result "A widow takes the mark and bites it, out of habit. The watchers turn their stools round and sit with their backs to the glass, and Old Pammu rings his bell once, to tell the town.".
  }
  // From inside, a knock on the glass asks them to turn round for whoever is coming out.
  Action knock_out(actor: group, site: place) "Knock on the glass for the watchers to turn their backs" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bedroom) and at(watchers, barley)
      and keepsWatch(watchers).
    On success { Assert averted(watchers). Assert averted(pammu). Set avertedUntil(watchers) to watch(clock). Increase avertedUntil(watchers) by 3.
      Set avertedUntil(pammu) to watch(clock). Increase avertedUntil(pammu) by 3. }
    Result "Through the glass you see a widow look up from her knitting at the knock. The stools scrape round.".
  }
  Topic pammu_hour with pammu "Ask Old Pammu about the low hour" when true once {
    Says "'The thief,' says Old Pammu. 'An hour before light. There's not a watcher born it doesn't take, if they sit. You stand, you walk, you keep a friend by you.' He rings the bell very softly against his knee. 'We had four. Now Kezu's not here, we've three and me.'".
  }

  // ---- If the council sells ----
  // The Company's guards take the stools. They are paid to watch and they do, after their fashion: they were not
  // born to it, and the low hour takes them as it takes anyone who sits.
  Person guards "the Company's guards" at nowhere {
    Role "two Littoral guards in Company blue, on Cobble Ring's stools". Ancestry human. Calling warrior. Numbers 2. Peaceable.
  }
  Initially Assert serves(guards, dace).
  Rule guards_take_stools when sold(annex) and not at(guards, barley)
    says "The Company's guards come down the barley line with a cart, and Cobble Ring's watchers pick up their stools and go home without a word." {
    Assert at(guards, barley). Assert watcher(guards). Assert post(guards, barley).
    Assert overlooks(guards, bedroom). Assert overlooks(guards, cup_shelf). Assert overlooks(guards, coats_low). Assert overlooks(guards, root_cellar).
    Assert at(watchers, rim). Retract watcher(watchers).
  }
  Observe guards_sit at barley as ambience when at(guards, barley) and keepsWatch(guards) "Two Company guards sit on Cobble Ring's stools round the glass, facing it, bored, with their crossbows across their knees.".
  Observe guards_nod at barley as ambience when at(guards, barley) and drowsing(guards) "The Company's guards are asleep on their stools.".
  Topic guards_in with guards "Ask the guards to let you into the house" when at(guards, barley) and not lends(dace, slate, actor) {
    Says "'Company property,' says one, not getting up. 'Mister Dace says who goes in.'".
  }
  Action guards_turn(actor: group, site: place) "Ask the guards to turn their backs for Dace's mapmaker" {
    Requires able(actor) and company(actor) and at(actor, site) and at(guards, site) and keepsWatch(guards) and lends(dace, slate, actor).
    On success { Assert averted(guards). Set avertedUntil(guards) to watch(clock). Increase avertedUntil(guards) by 3. }
    Result "The guards look at Dace's slate under your arm, shrug, and turn their stools round.".
  }

  // ---- Dace, the Company man, and Haddo ----
  Person dace "Dace" at barley {
    Role "a Company clerk in a Littoral coat, with a knotted cord and a slate". Ancestry human. Peaceable.
    Buys ithren_lamp for 2 coin.
  }
  Initially Set quantity(dace, gold) to 1000.
  Topic dace_sum with dace "Ask Dace what his factor wants with the room" when true once {
    Says "'The barge has a ceiling,' says Dace, 'and the room is in the sum.' He hears himself, and says it in his mother's voice instead. 'Mister Lisle buys things that fall out of the city, and this one's still growing. He tried to lift it yesterday and could not. Now he's offered the town two thousand marks for it, and the council meets on the third day.' He coils his cord. 'He'll pay five hundred for a true map of the inside. A thousand, if it shows a room of the city.'".
    On discuss { Assert knows(actor, map_offer). Assert knows(actor, vote_due). }
  }
  Discovery map_offer "Dace will pay five hundred marks for a true map of the room in the barley, a thousand if it shows a room of the city above. A map of a room you left goes stale if the room grows.".
  Topic dace_cord with dace "Ask Dace how big the room is now" when true {
    Says "Dace walks the long side with his cord and comes back. 'Nineteen and a half,' he says. 'Since you asked.'".
  }
  Item slate "Dace's slate" is map at barley hidden until map_offer owned by dace.
  Topic dace_lend with dace "Ask Dace for the loan of his slate, to map the house" when knows(actor, map_offer) and not lends(dace, slate, actor) {
    Says "Dace hands it over, and the chalk. 'Draw what you can see, as you see it,' he says. 'I'll check it against the cord.'".
    On discuss { Assert lends(dace, slate, actor). }
  }
  // A map of a room is true while the room is as it was when it was drawn.
  Relation mapped(place). Measure mappedAt(place).
  Action draw_room(actor: group, carrier: member, site: place) "Draw {site} on Dace's slate" {
    Description "Chalk what you can see while you are looking at it.".
    Requires able(actor) and company(actor) and at(actor, site) and houseRoom(site) and companyLooks(actor, site)
      and memberOf(carrier, actor) and ownedItem(slate, carrier) and not mapped(site).
    Time 2.
    On success { Assert mapped(site). Set mappedAt(site) to grown(site). Assert averted(actor). Set avertedUntil(actor) to watch(clock). Increase avertedUntil(actor) by 2. }
    Result "You chalk the walls, the doors as they are, the furniture at its size.".
  }
  Query mapStale(x: place) means mapped(x) and grown(x) > mappedAt(x).
  Action sell_map(actor: group, carrier: member, site: place) "Give Dace back his slate, with your map of the house" {
    Requires able(actor) and company(actor) and at(actor, site) and at(dace, site) and memberOf(carrier, actor)
      and ownedItem(slate, carrier) and mapped(bedroom) and mapped(cup_shelf)
      and not (mapped(?x) and grown(?x) > mappedAt(?x)) and not mapped(coats_high) and not mapped(long_hall) and not paidMap(dace).
    Resolve drop(slate, carrier).
    On success { Assert at(slate, nowhere). Assert paidMap(dace). Decrease quantity(dace, gold) by 500. Increase quantity(actor, gold) by 500. }
    Result "Dace walks the glass with the slate and his cord, room by room, and comes back satisfied. He counts five hundred marks in Company paper into your hand. 'He'll want more,' he says. 'He always does.'".
  }
  Action sell_map_high(actor: group, carrier: member, site: place) "Give Dace back his slate, with your map of the house and the city's rooms" {
    Requires able(actor) and company(actor) and at(actor, site) and at(dace, site) and memberOf(carrier, actor)
      and ownedItem(slate, carrier) and mapped(bedroom) and mapped(cup_shelf) and (mapped(coats_high) or mapped(long_hall))
      and not (mapped(?x) and grown(?x) > mappedAt(?x)) and not paidMap(dace).
    Resolve drop(slate, carrier).
    On success { Assert at(slate, nowhere). Assert paidMap(dace). Decrease quantity(dace, gold) by 1000. Increase quantity(actor, gold) by 1000. }
    Result "Dace reads the slate twice, and the second time his lips move. 'The Long Hall,' he says. 'He'll go himself.' He counts a thousand marks in Company paper into your hand and does not look happy about it.".
  }
  Action sell_stale_map(actor: group, carrier: member, site: place) "Give Dace back his slate, with your map of the house" {
    Requires able(actor) and company(actor) and at(actor, site) and at(dace, site) and memberOf(carrier, actor)
      and ownedItem(slate, carrier) and mapped(bedroom) and mapped(?x) and grown(?x) > mappedAt(?x) and not paidMap(dace).
    Resolve drop(slate, carrier).
    On success { Assert at(slate, nowhere). Assert doubted(dace). }
    Result "Dace walks the glass with the slate and his cord, and comes back slower. 'This door isn't here,' he says, 'and this room's half again as long. It's grown since you drew it.' He wipes the slate with his sleeve. 'I can't send him that.'".
  }
  Relation paidMap(group). Relation doubted(group).
  Person haddo "Haddo" at barley {
    Role "the farmer whose barley it is, a month behind everyone else's". Ancestry human. Peaceable.
  }
  Topic haddo_field with haddo "Ask Haddo what he means to do with it" when true once {
    Says "'Sell it,' says Haddo. 'It's in my field and it's spoiled my barley and it's grown a cellar under my turnips. Relic law says it's mine. Council says it's the town's to watch.' He spits. 'Then the town can pay me for the barley.'".
  }

  // ---- The rooms ----
  Observe barley_scene at barley as fixture when true "The barley lies flat in a line, like hair under a comb, to a room of glass the green of pond-ice that sits on a slab of dark stone pressed a hand deep into the soil. Its panes are as long as a man is tall, and between them, where you would put lead, runs something brown and soft. Through the glass you can see a bed the size of a hay wagon.".
  Observe barley_grown at barley as ambience when grown(bedroom) >= 1 "The room in the barley is longer than it was.".
  Observe well_scene at haddo_well as fixture when true "A stone well-head in the corner of the field, a bucket on a chain, and the turf round it trodden bare by forty households waiting their turn.".
  Observe well_warm at haddo_well as revelation when grown(root_cellar) >= 2 "The water in Haddo's well is warm, and brown seams thread the stones of the shaft a little below the rim, soft when you press them." teaches well_reached.
  Discovery well_reached "The house's root cellar has grown into Haddo's well. There is a way into the house there that nobody on the stools is watching.".

  Observe bedroom_scene at bedroom as fixture when true "A giant's bedroom for a child: a bed the size of a hay wagon with its blanket folded at the foot, a chair you would need a ladder for, the green light of the glass, and the warm brown seams between the panes. Through the walls you can see the barley, and the watchers on their stools.".
  Thing bed "the great bed" at bedroom {
    State folded "The blanket at the foot of the bed lies in seven folds.".
    State eight "The blanket at the foot of the bed lies in eight folds. There were seven.".
  }
  Rule bed_grows when grown(bedroom) >= 1 and state(bed, folded) { Assert state(bed, eight). }
  Initially Assert state(bed, folded).
  Thing coat "a child's coat under the blanket" at bedroom {
    Holds.
    State under closed "Something has been folded under the blanket near the pillow, a small shape like a rolled coat.".
    State shaken "A child's coat lies on the bed, shaken out. Its collar is stitched NEME.".
    Change shake "Pull the coat out from under the blanket" from under to shaken.
  }
  Item marble "an orange-glass marble" is dreg in coat.
  Thing seams "the brown seams between the panes" at bedroom {
    State whole "Between the panes the brown stuff is soft and warm, and gives under a thumb.".
    State scorched "One seam is blackened, and the pane beside it has cracked with a sound like a bell.".
    Tries burning.
  }
  Rule seam_burnt when tried(seams, burning) and state(seams, whole) says "The seam shrinks from the flame like a lip, and the pane beside it cracks, ringing. Through the glass you see the watchers on their stools all look up at once." { Assert state(seams, scorched). }
  Rule seam_heals when state(seams, scorched) and not watchedRoom(bedroom) { Assert state(seams, whole). Retract tried(seams, burning). }
  Initially Assert seventhDreg(marble).
  // The bed grows across the door to the cup shelf if the room is left long enough.
  Thing bed_foot "the foot of the great bed" on shelf_door {
    State clear "The foot of the great bed stands clear of the door to the cup shelf.".
    State jammed blocking "The foot of the bed has grown across the door to the cup shelf. The glass behind it is cracked.".
  }
  Rule bed_jams when grown(bedroom) >= 3 and state(bed_foot, clear) { Assert state(bed_foot, jammed). }

  Observe shelf_scene at cup_shelf as fixture when true "A shelf at the height of a barn's eaves runs the length of the room, and on it a row of cups of orange glass, each the size of a bucket.".
  Observe shelf_twin at cup_shelf as revelation when knows(party, kezu_cup_seen) and not carries(party, kezu_cup) "One of the cups on the shelf has a crack in its rim, low on the left, exactly the crack in the little cup by Kezu's bed." teaches cups_match.
  Observe shelf_carried at cup_shelf as revelation when carries(party, kezu_cup) "The little cup in your pack has gone warm, the way the door handle was warm. On the shelf above you its twin, a hundred times its size, has the same crack." teaches cups_match.
  Discovery cups_match "The cracked cup by Kezu's bed has a twin on the cup shelf of the house in the barley, crack and all. What Kezu dreams is this house.".
  Observe shelf_twelve at cup_shelf as feature when grown(cup_shelf) < 1 "There are twelve of them.".
  Observe shelf_thirteen at cup_shelf as feature when grown(cup_shelf) >= 1 "There are thirteen of them. Kezu said twelve.".
  Observe window_scene at cup_shelf as feature when true "At the end of the room a long window runs from floor to roof. Through it you should see the barley. You see a hallway lit from below, as long as a field, with doors on both sides, and through its far glass, cloud." teaches keel_seen.
  Discovery keel_seen "The long window of the house in the barley does not look out on the barley. It looks into a long hallway lit from below, with cloud beyond its glass: somewhere up in the city.".
  Discovery house_one "The house in the barley and the rooms under the city are one house. A door in one can open in the other.".
  Observe high_window at coats_high as revelation when knows(party, keel_seen) "This is the hall the long window showed you, and the long window is behind you now, small, with a bit of barley in it." teaches house_one.

  Observe coats_scene at coats_low as fixture when true "A hall of hooks at the height of a barn roof, every one hung with a child's coat, in sizes from a child of five to a girl of fourteen. Doors go out of it on every side.".
  Observe coats_fifteen at coats_low as ambience when grown(coats_low) >= 1 "At the end of the row, a new coat hangs on a new hook: a girl's coat, for a girl of fifteen.".
  Observe cellar_scene at root_cellar as fixture when true "A low room under the floor, its floor not glass but turf, warm underfoot and threaded with brown seams that are softer than the turf. It goes on into the dark further than the room above it.".
  Observe cellar_longer at root_cellar as ambience when grown(root_cellar) >= 1 and grown(root_cellar) < 2 "The cellar goes further than it did, toward the corner of the field.".
  Observe cellar_well at root_cellar as revelation when grown(root_cellar) >= 2 "At the far end of the cellar the turf gives onto dressed stone, wet and round: the inside of a well shaft. Daylight comes down it." teaches well_reached.

  // ---- The Footman of Folded Glass ----
  // It cannot move while it is watched. It tidies: it puts people away into drawers. It can be broken while watched,
  // and is whole again by any unwatched hour. It is a thing, not a fighter: nobody has ever made it fight.
  Thing footman "a man of folded green glass" at coats_high {
    State standing "A man made of folded green glass stands with his hands clasped in front of him, the folds as fine as linen. He does not move while you look at him.".
    State reaching "The man of folded glass is closer than he was. One hand is held out toward you, palm up, as if he would like to take your coat.".
    State broken "The man of folded glass lies in pieces on the floor, every piece a fold.".
    Change smash "Break the folded man while you are looking at him" from standing to broken needing brawn or crowbar.
    Change smash_near "Break the folded man while you are looking at him" from reaching to broken needing brawn or crowbar.
  }
  Initially Assert state(footman, standing).
  Rule footman_mends when state(footman, broken) and at(footman, ?p) and not watchedRoom(?p)
    { Assert state(footman, standing). }
  // A lapse lets him close; a second puts you away. A hazard cannot put anyone to sleep for longer than a fight lasts,
  // and nothing else stops a company acting, so being put away is a place: the inside of a drawer.
  Place drawer_dark "inside a drawer" is room within annex at 3, 1 indoors.
  Initially Assert unlit(drawer_dark).
  Relation putAway(group). Measure freedAt(group). Relation takenFrom(group, place).
  // Written before footman_closes on purpose: rules see what the rules above them did this turn, so in the other
  // order one lapse would let him close and take at once.
  // Effects cannot be conditional, so what happens to Tobu, if he is with you, is a rule of its own, before the taking.
  Rule tobu_left_by when state(footman, reaching) and at(footman, ?p) and at(party, ?p) and not held(?p) and following(tobu, party) {
    Retract following(tobu, party). Assert staying(tobu). }
  Rule footman_takes when state(footman, reaching) and at(footman, ?p) and at(party, ?p) and not held(?p)
    says "A cool hand that is all folds takes you by the coat, and the room folds with it, small and smaller, into the dark." {
    Assert at(party, drawer_dark). Assert putAway(party). Assert takenFrom(party, ?p).
    Set freedAt(party) to watch(clock). Increase freedAt(party) by 6. Assert state(footman, standing). }
  Rule footman_closes when state(footman, standing) and at(footman, ?p) and at(party, ?p) and not held(?p)
    says "When you look back the folded man is closer, and his hand is out." { Assert state(footman, reaching). }
  Observe drawer_inside at drawer_dark as fixture when true "Dark, and close, and folded: your knees are at your chin and your arms along your sides like a letter's lines. You can hear, as if from the far side of a wall, someone counting coat-hooks.".
  // Someone outside who stares at where you were for an hour unfolds you; nobody, and you stay.
  Rule unfolded when putAway(party) and takenFrom(party, ?p) and staying(tobu) and at(tobu, ?p) and watch(clock) >= freedAt(party)
    says "Light comes in along a seam, and then a great deal of light, and you unfold onto the glass floor stiff in every joint. Tobu is sitting with his eyes on the place you went, and has not looked away for an hour." {
    Retract putAway(party). Retract takenFrom(party, ?p). Assert at(party, ?p). }
  Rule footman_waits when state(footman, reaching) and at(footman, ?p) and not at(party, ?p) { Assert state(footman, standing). }
  // Unwatched, he goes down through the house to tidy what is in the barley. In the low hour, if the stools nod, he
  // comes out of the small door and puts away a watcher.
  Rule footman_descends when at(footman, coats_high) and not watchedRoom(coats_high) and not watchedRoom(coats_low)
    and state(footman, standing) and dark() { Assert at(footman, coats_low). }
  Rule footman_puts_away at barley when at(footman, coats_low) and drowsing(watchers) and drowsing(pammu) and at(pammu, barley)
    and not at(party, barley) and state(footman, standing)
    says "In the barley, in the low hour, something glints at the small door and is gone again. Old Pammu's stool is empty." {
    Assert at(pammu, nowhere). Assert folded(pammu). Retract watcher(pammu). Assert at(footman, coats_high).
  }
  Relation folded(group).
  // The nearest drawer to the barley is the bedroom's: a chest of drawers a child would need a ladder to open.
  Thing drawer "the bottom drawer of the great chest" at bedroom {
    State shut "Against the far wall stands a chest of drawers as tall as a barn door. Its bottom drawer is shut.".
    State full "Against the far wall stands a chest of drawers as tall as a barn door. Its bottom drawer is shut, and from inside it comes, very faintly, the sound of a hand-bell.".
  }
  Rule drawer_fills when folded(pammu) and state(drawer, shut) { Assert state(drawer, full). }
  Initially Assert state(drawer, shut).
  Observe pammu_gone at barley as event when folded(pammu) and at(watchers, barley) "One of the stools is empty, and the widows will not look at it. 'Pammu,' says one. 'In the low hour. We were all three nodding.'" teaches pammu_taken.
  Discovery pammu_taken "In the low hour, while the watchers nodded, the folded man came out of the house and put Old Pammu away.".
  Action unfold(actor: group, site: place) "Sit before the drawer and stare at it for an hour" {
    Description "A folded person comes out only for someone who watches the drawer an hour without looking away. It is the stare.".
    Requires able(actor) and company(actor) and at(actor, site) and at(drawer, site) and state(drawer, full)
      and stareTrained(actor) and companyLooks(actor, site).
    Time 6. Interrupted when not companyLooks(actor, site).
    On success { Assert state(drawer, shut). Retract folded(pammu). Assert at(pammu, site). Assert watcher(pammu). Assert acceptsEscort(pammu, actor). }
    Result "You hold the drawer in your mind as it is, the grain of the glass, the brass of its handle, and do not let your mind make it better or worse. In the hour's last minutes it slides open by itself, and Old Pammu unfolds out of it like a letter, stiff, and blinking, with his bell in his hand.".
  }
}

data/adventures/house-that-grows/attenti:
Module hhg "The House That Grows" {
  Description "The law the Strewnfield lives by: dream-matter sets where nobody attends to it. A watched room is fixed; an unwatched one grows; a dream-door opens only behind your back, onto the less-watched copy of the room beyond it.".

  // ---- Who attends to a room ----
  // Attention comes in three degrees. Someone in a room looking at it (the company, a watcher who keeps watch, a lit
  // Ithren lamp set down) holds it. Cobble Ring's watchers on their stools in the barley overlook every Annex room
  // through the glass, which fixes it, but less firmly than an eye inside it. Nobody: the room grows.
  Relation houseRoom(place). Relation keelSide(place).
  Relation copyOf(place, place).
  Relation dreamDoor(passage).
  Relation watcher(group). Relation overlooks(group, place).
  Relation averted(group). Relation drowsing(group). Relation sitting(group).
  Measure avertedUntil(group).
  Relation lit(entity). Relation seventhLit(entity). Measure burnsOut(entity).
  Relation stareTrained(group).

  Query keepsWatch(g: group) means able(g) and not averted(g) and not drowsing(g).
  Query companyLooks(c: group, p: place) means company(c) and at(c, p) and not averted(c) and not benighted(c)
    and memberOf(?m, c) and awake(?m).
  Query held(p: place) means (company(?c) and at(?c, p) and not averted(?c) and not abed(?c) and not benighted(?c) and memberOf(?m, ?c)
      and awake(?m)) or (watcher(?w) and at(?w, p) and keepsWatch(?w))
    or (lit(?l) and at(?l, p)) or (sitting(?s) and keelSide(p) and keepsWatch(?s)).
  // Watching a room from a post outside it: stools in the barley, a loft's shutter onto a sleeping-room.
  Relation post(group, place).
  Query overlooked(p: place) means overlooks(?w, p) and keepsWatch(?w) and post(?w, ?q) and at(?w, ?q).
  Query watchedRoom(p: place) means held(p) or overlooked(p).
  // The near copy of a room is the one to open on when it is strictly less watched than the far one.
  Query nearLess(a: place, b: place) means not held(a) and (held(b) or (overlooked(b) and not overlooked(a))).
  // Nobody at a door is looking at it: no watcher in the room the company stands in, nobody on the stools if the
  // door is the Annex's own.
  // Someone left to hold a room sits with their back to its glass and watches the room, not its doors.
  Query eyesOn(o: place) means (watcher(?w) and at(?w, o) and keepsWatch(?w) and not staying(?w)) or (sitting(?s) and at(?s, o))
    or (overlooks(?v, ?r) and keepsWatch(?v) and post(?v, o) and at(?v, o) and annexMouth(o)).
  Relation annexMouth(place).

  // ---- Looking away ----
  Rule eyes_back when averted(?g) and watch(clock) >= avertedUntil(?g) { Retract averted(?g). }
  Rule stands_up when sitting(?s) and not at(?s, long_hall) { Retract sitting(?s). }

  // ---- Dream-doors: they open only behind your back ----
  Action back_through(actor: group, way: passage, origin: place, there: place) "Close your eyes and back through {way}" {
    Description "Turn your back on the door, shut your eyes, and step back through when you hear it give. You will not see where it opens until you are there.".
    Requires able(actor) and company(actor) and at(actor, origin) and dreamDoor(way) and connects(way, origin, there) and visibleTo(way, actor)
      and not eyesOn(origin) and not sitting(actor) and not held(there) and not copyOf(there, ?any) and mobile(actor).
    On success { Assert at(actor, there). }
    Result "Behind you the glass sighs. You step back through it with your eyes shut, and open them.".
  }
  // Into a room the house has in both its bodies: the door opens on whichever copy is less watched.
  Action back_through_near(actor: group, way: passage, origin: place, there: place, far: place) "Close your eyes and back through {way}" {
    Description "Turn your back on the door, shut your eyes, and step back through when you hear it give. You will not see where it opens until you are there.".
    Requires able(actor) and company(actor) and at(actor, origin) and dreamDoor(way) and connects(way, origin, there) and visibleTo(way, actor)
      and not eyesOn(origin) and not sitting(actor) and copyOf(there, far) and nearLess(there, far) and mobile(actor).
    On success { Assert at(actor, there). }
    Result "Behind you the glass sighs. You step back through it with your eyes shut, and open them.".
  }
  Action back_through_far(actor: group, way: passage, origin: place, there: place, far: place) "Close your eyes and back through {way}" {
    Description "Turn your back on the door, shut your eyes, and step back through when you hear it give. You will not see where it opens until you are there.".
    Requires able(actor) and company(actor) and at(actor, origin) and dreamDoor(way) and connects(way, origin, there) and visibleTo(way, actor)
      and not eyesOn(origin) and not sitting(actor) and copyOf(there, far) and not held(far) and not nearLess(there, far)
      and mobile(actor).
    On success { Assert at(actor, far). }
    Result "Behind you the glass sighs. You step back through it with your eyes shut, and open them. The light is wrong.".
  }

  // Someone keeping watch beyond a door keeps it shut; knock, and ask them to look away.
  Action knock_watcher(actor: group, way: passage, origin: place, there: place, keeper: group) "Knock on {way} and ask {keeper} to look away" {
    Description "Whoever is watching the room beyond holds it; nobody can come in while they look.".
    Requires able(actor) and company(actor) and at(actor, origin) and dreamDoor(way) and connects(way, origin, there)
      and visibleTo(way, actor) and watcher(keeper) and at(keeper, there) and keepsWatch(keeper) and not company(keeper).
    On success { Assert averted(keeper). Set avertedUntil(keeper) to watch(clock). Increase avertedUntil(keeper) by 3. }
    Result "Through the glass, a voice: 'Who's that?' Then, after a moment, 'All right. I'm not looking.'".
  }

  Action ask_look_away(actor: group, keeper: group, site: place) "Ask {keeper} to look at you, not the door" {
    Requires able(actor) and company(actor) and at(actor, site) and at(keeper, site) and watcher(keeper) and keepsWatch(keeper)
      and not company(keeper) and not following(keeper, actor) and not staying(keeper) and not post(keeper, site).
    On success { Assert averted(keeper). Set avertedUntil(keeper) to watch(clock). Increase avertedUntil(keeper) by 3. }
    Result "{keeper} looks at you instead, and waits.".
  }

  // ---- Growth ----
  // An unwatched room changes on about a 1 in 6 each turn. The world throws one die a watch, so each room is given
  // its own band of the die: no two rooms of one body grow in the same turn.
  Measure grown(place). Measure bandLo(place). Measure bandHi(place).
  Rule house_grows when houseRoom(?p) and not watchedRoom(?p) and dice(clock) >= bandLo(?p) and dice(clock) <= bandHi(?p) {
    Increase grown(?p) by 1.
  }

  // ---- Ithren lamps: a lit one, set down, watches its room for an hour ----
  Rule lamp_set when lit(?l) and at(?l, ?p) and burnsOut(?l) == 0 { Set burnsOut(?l) to watch(clock). Increase burnsOut(?l) by 6. }
  Rule lamp_out when lit(?l) and burnsOut(?l) > 0 and watch(clock) >= burnsOut(?l) { Retract lit(?l). Retract seventhLit(?l). }
  Action fuel_lamp(actor: group, lamp: item, fuel: item, carrier: member) "Put {fuel} into the chimney of {lamp}" {
    Description "Ithren lamps burned a spark of star-matter. Dreg is a dream set hard; whatever dreamed this one, it was not small.".
    Requires able(actor) and company(actor) and memberOf(carrier, actor) and awake(carrier) and ownedItem(lamp, carrier)
      and ownedItem(fuel, carrier) and itemKind(lamp, ithren_lamp) and itemKind(fuel, dreg) and not lit(lamp)
      and seventhDreg(fuel) and not benighted(actor).
    Resolve drop(fuel, carrier).
    On success { Assert lit(lamp). Assert seventhLit(lamp). Set burnsOut(lamp) to 0. Assert at(fuel, nowhere). }
    Result "The dreg goes soft against the glass and runs in like honey. The lamp lights: a small steady flame the colour of pond-ice, that does not flicker when you breathe on it. It feels like being looked at.".
  }
  Relation seventhDreg(item).
  Discovery lamps_watch "A lit Ithren lamp, set down in a room of the house, holds that room as a watcher would, for about an hour.".
  // An observation needs an anchor: a phenomenon that goes where a lamp goes is written once for each lamp.
  Observe lamp_a_watching near lamp_a as revelation when lit(lamp_a) and at(lamp_a, ?p) "The lit lamp stands where it was set and does not waver. The room around it is very still, as a room is when someone is watching it." teaches lamps_watch.
  Observe lamp_b_watching near lamp_b as revelation when lit(lamp_b) and at(lamp_b, ?p) "The lit lamp stands where it was set and does not waver. The room around it is very still, as a room is when someone is watching it." teaches lamps_watch.
  Observe lamp_c_watching near lamp_c as revelation when lit(lamp_c) and at(lamp_c, ?p) "The lit lamp stands where it was set and does not waver. The room around it is very still, as a room is when someone is watching it." teaches lamps_watch.

  // ---- Sleep ----
  // A long rest cannot be seen by rules while it is going on, so sleeping here is two things: lying down, which the
  // house can see, and the night going by. Whoever lies down is not watching. Sleeping where nobody watches: on
  // waking, half the time nothing; a third of the time a small dreg, shaped like something the sleeper loved; in the
  // house, oftener.
  Relation abed(group). Relation sleptUnwatched(group, place).
  Action lie_down(actor: group, site: place) "Lie down and sleep here" {
    Description "Nobody watches a sleeper but whoever sits up with them.".
    Requires able(actor) and company(actor) and at(actor, site) and not abed(actor) and not settled(site) and dark().
    On success { Assert abed(actor). }
    Result "You lie down where you are, and close your eyes, and do not open them again.".
  }
  Action lie_down_kitchen(actor: group, site: place) "Lie down on Kezu's bench and sleep" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, kezu_kitchen) and not abed(actor) and dark().
    On success { Assert abed(actor). }
    Result "You lie down on the bench by the fire, and close your eyes.".
  }
  Query sleepWatched(c: group, p: place) means watcher(?w) and at(?w, p) and keepsWatch(?w) and not company(?w).
  Rule wakes_watched when abed(?c) and not dark() and at(?c, ?p) and sleepWatched(?c, ?p) { Retract abed(?c). }
  Rule wakes_alone when abed(?c) and not dark() and at(?c, ?p) and not sleepWatched(?c, ?p) {
    Retract abed(?c). Assert sleptUnwatched(?c, ?p). }
  Rule waking_dreg when sleptUnwatched(?c, ?p) and houseRoom(?p) and dice(clock) > 33 and at(sleep_dreg, nowhere)
    says "You wake with something warm against your hand: a small hard thing, glassy, the colour of weak tea." {
    Retract at(sleep_dreg, nowhere). Assert at(sleep_dreg, ?p). Assert seventhDreg(sleep_dreg). Retract sleptUnwatched(?c, ?p).
  }
  Rule waking_dreg_ground when sleptUnwatched(?c, ?p) and not houseRoom(?p) and dice(clock) > 66 and at(sleep_dreg, nowhere)
    says "You wake with something warm against your hand: a small hard thing, glassy, the colour of weak tea." {
    Retract at(sleep_dreg, nowhere). Assert at(sleep_dreg, ?p). Retract sleptUnwatched(?c, ?p).
  }
  Rule waking_plain when sleptUnwatched(?c, ?p) { Retract sleptUnwatched(?c, ?p). }
  Item sleep_dreg "a dreg shaped like your father's leather knife, nick and all" is dreg at nowhere.
}

data/adventures/house-that-grows/cobble-:
Module hhg "The House That Grows" {
  Description "Cobble Ring, a crater-ring town of the Strewnfield, the morning after Kezu opened the door in Haddo's barley.".

  // The Strewnfield's own things, declared here rather than added to the shared catalog.
  Kind dreg "Dreg" is treasure worth 2 described "A small hard piece of dream set into matter where nobody was watching: glassy, warm to the hand, and shaped like something the dreamer loved. Reed-growers bury it under their reedbeds, and lens-polishers grind it.".
  Kind ithren_lamp "Ithren lamp" is gear worth 2 described "A lamp of selm-glass from the city, the size of a pear, with a sealed chimney where a spark of star-matter once burned. This one is burnt out. They sell on the ground for curiosities.".
  Kind wax_plugs "Ear-wax plugs" is gear worth 1 described "A twist of wax and wool to stop the ears, as watch-keepers use against snoring in the common hall.".

  // The Strewnfield, as much of it as this story needs: Cobble Ring, Haddo's barley on its east lip, the causeway
  // to Lowmere, and the city overhead, whose underside is the Keel.
  Place strewnfield "the Strewnfield" is region.
  Place ring "Cobble Ring" is settlement within strewnfield at 1, 1.
  Place barley_field "Haddo's barley" is wilderness within strewnfield at 2, 1.
  Place causeway_country "the causeway to Lowmere" is wilderness within strewnfield at 0, 1.
  Place lowmere "Lowmere" is settlement within strewnfield at 0, 2.
  Place keel "the Keel" is site within strewnfield at 1, 0.

  Place kezu_house "Kezu's house" is building within ring.
  Place hall "the sleeping-hall" is building within ring.
  Place reeve_house "the reeve's house" is building within ring.

  Place rim "the rim of Cobble Ring" is room within ring at 1, 0.
  Place pond_side "the pond causeway" is room within ring at 1, 1.
  Place kezu_kitchen "Kezu's kitchen" is room within kezu_house at 0, 1.
  Place kezu_upper "Kezu's loft" is level within kezu_house.
  Place kezu_loft "Kezu's watch-loft" is room within kezu_upper at 0, 0.
  Place kezu_bed "Kezu's sleeping-room" is room within kezu_house at 0, 2.
  Place hall_floor "the common sleeping-hall" is room within hall at 2, 1.
  Place reeve_room "the reeve's room" is room within reeve_house at 1, 2.
  Place east_lip "the east lip" is room within ring at 2, 0.

  Passage rim_steps "the rim steps" is steps between rim and pond_side.
  Passage kezu_door "Kezu's door" is door between pond_side and kezu_kitchen.
  Passage loft_ladder "the loft ladder" is ladder between kezu_kitchen and kezu_loft.
  Passage bed_curtain "the curtain to the sleeping-room" is doorway between kezu_kitchen and kezu_bed.
  Passage hall_door "the hall door" is door between pond_side and hall_floor.
  Passage reeve_door "the reeve's door" is door between pond_side and reeve_room.
  Passage lip_path "the rim path to the east lip" is path between rim and east_lip.
  Initially Assert at(sleep_dreg, nowhere).

  Observe rim_scene at rim as fixture when true "The rim of Cobble Ring is a ring of turf as wide as a lane, with the houses hung inside it facing the pond. Every house has a watch-loft on its rim side, a raised seat behind a shutter. Out over the plain the next crater-rims glitter, and over the middle of the country, a long way up, the city hangs in its grey skirt of cloud.".
  Observe rim_lofts at rim as ambience when dark() "Every watch-loft round the rim is lit. In each one, someone is sitting up.".
  Observe pond_scene at pond_side as fixture when true "A stone causeway runs across the crater pond to the sleeping-hall. Reed thatch, flat roofs, an anchor-stone at the causeway's end where the market is held. Kezu's door, the reeve's door and the hall's open off it.".
  Observe kitchen_scene at kezu_kitchen as fixture when true "Kezu's kitchen: a peat fire, a bench, a ladder to the watch-loft, and a curtain across the door of the sleeping-room. A knitted cover on the loft seat, worn through where she sits.".
  Observe loft_scene at kezu_loft as fixture when true "The watch-loft: a seat and a hand-bell, and a shutter that opens onto the sleeping-room below, so whoever sits here can see the bed.".
  Observe bed_scene at kezu_bed as fixture when true "A narrow sleeping-room: a reed bed with the blanket kicked to the foot, a chest, one window onto the pond, and on the sill a tin cup of tea gone cold with a skin on it.".
  Observe hall_scene at hall_floor as fixture when true "Thirty beds in rows, and four stools between them. The roof beams are numbered in chalk, for apprentices who count them to keep awake.".
  Observe reeve_scene at reeve_room as fixture when true "The reeve's room is also the council's: a long table, nine chairs for the nine arcs, and the town's tax-slates on a rack.".
  Observe lip_scene at east_lip as fixture when true "From the east lip the barley falls away outside the rim. In it, at the end of a line of flattened stalks, a room of green glass stands in the field as if someone had set it down there.".

  // ---- Kezu, her sister, and her sister's boy ----
  Person kezu "Kezu" at kezu_bed {
    Role "watch-keeper of Cobble Ring, sixty-one". Ancestry human. Peaceable.
    State sleeping "Kezu is asleep, on her back, with one hand closed round the little dreg ox she wears on a cord.".
    State waking "Kezu is up, grey in the face, with her hands round a cup of something hot.".
  }
  Initially Assert state(kezu, sleeping).
  // She is sleeping too much: by day she is up only for the afternoon.
  Rule kezu_rises when state(kezu, sleeping) and not dark() and untilDark(clock) <= 36 and untilDark(clock) > 6
    and at(kezu, kezu_bed) { Assert state(kezu, waking). Assert at(kezu, kezu_kitchen). }
  Rule kezu_lies_down when state(kezu, waking) and untilDark(clock) <= 6 { Assert state(kezu, sleeping). Assert at(kezu, kezu_bed). }
  Person hanu "Hanu" at kezu_loft {
    Role "Kezu's sister, Tobu's mother, sitting up with her". Ancestry human. Peaceable.
  }
  Initially Assert watcher(hanu). Initially Assert post(hanu, kezu_loft). Initially Assert overlooks(hanu, kezu_bed).
  Topic hanu_sitting with hanu "Ask Hanu why she is sitting up over her sister" when true once {
    Says "Hanu does not take her eyes off the shutter. 'Because she sleeps too much, and in Cobble Ring what nobody watches changes.' Her hand rests by the bell. 'Since the barley she's down all morning and all night, and up grey for the afternoon. She's sat up for this town since she was Tobu's age. Somebody can sit up for her for a week.'".
  }
  Topic hanu_tobu with hanu "Ask Hanu about Tobu" when true once {
    Says "'Sleeps like an ox,' says Hanu fondly, to the shutter. 'Seventeen, and he'd sleep through the hall bell. That's why she's teaching him. She says a boy who can sleep can learn to stay awake; it's the ones who can't sleep who see things that aren't there.' The corner of her mouth goes up and comes down again. 'He was with her in the barley. He won't tell me what she did. He might tell you.'".
  }
  Person tobu "Tobu" at kezu_kitchen {
    Role "Kezu's sister's boy, seventeen, who sleeps like an ox". Ancestry human. Peaceable.
  }
  Initially Assert watcher(tobu).
  Initially Assert kin(hanu, kezu). Initially Assert kin(tobu, kezu). Initially Assert kin(tobu, hanu).

  // What Kezu did, and what Tobu wants to understand.
  Topic tobu_night with tobu "Ask Tobu what happened in the barley" when not told(tobu, night) {
    Says "Tobu looks at the curtain before he answers. 'We held it all night, she and me and the Company man. Eleven and a third, by his cord. Then the girl asked her to open the door.' He swallows. 'She told me to look at her, and then she shut her eyes. On purpose. And the door opened, and something went out through the barley, and the room's nineteen knots now.' He looks at his hands. 'I want to know why she did it.'".
    On discuss { Assert told(tobu, night). Assert knows(actor, door_opened). }
  }
  Relation told(group, entity). Entity night: fact "the night in the barley".
  Entity door: fact "the new door in Kezu's wall". Entity ox: fact "the dreg ox at Kezu's throat".
  Discovery door_opened "Kezu held the room in Haddo's barley all night, then shut her eyes on purpose so that its small door could open. A girl's voice had asked her to. Something light went out through the barley; the room has grown since.".
  Topic tobu_come with tobu "Ask Tobu to come with you into the house" when knows(actor, door_opened) and not acceptsEscort(tobu, actor) and not following(tobu, actor) {
    Says "'Into it?' Tobu looks at the curtain again, and then at you. 'She'd skin me.' He gets his coat off the peg. 'I'm coming. Somebody has to look at the doors while you don't.'".
    On discuss { Assert acceptsEscort(tobu, actor). }
  }
  Topic tobu_look with tobu "Tell Tobu: 'Look at me, not the door'" when following(tobu, actor) and not averted(tobu) {
    Says "Tobu looks at you. He is trying not to blink.".
    On discuss { Assert averted(tobu). Set avertedUntil(tobu) to watch(clock). Increase avertedUntil(tobu) by 3. }
  }
  Topic tobu_stay with tobu "Ask Tobu to stay here and keep his eyes on this room" when following(tobu, actor) and at(actor, ?p) and houseRoom(?p) {
    Says "Tobu sits down with his back to the glass and looks at the room as Kezu taught him, at the count of things, not the shape of them. 'Go on, then,' he says. 'Don't be long.' He does not look at you as you go.".
    On discuss { Retract following(tobu, actor). Assert dismissed(tobu, actor). Assert staying(tobu). }
  }
  Relation staying(group).
  Topic tobu_fetch with tobu "Tell Tobu he can stop watching and come" when staying(tobu) and together(tobu, actor) {
    Says "Tobu gets up stiffly. 'Eleven of the coat-hooks,' he says. 'I counted them a hundred times. Nothing moved.' He falls in beside you.".
    On discuss { Retract staying(tobu). Retract dismissed(tobu, actor). Assert following(tobu, actor). }
  }
  // Tobu leaves if his aunt is harmed.
  Rule tobu_goes_home when following(tobu, party) and harmed(kezu) says "Tobu hears it in your voice before you have finished. He goes white, and then he goes, without a word, the way home." {
    Retract following(tobu, party). Retract acceptsEscort(tobu, party). Assert at(tobu, kezu_kitchen).
  }
  Relation harmed(group).

  // Kezu, awake: she does not dream, she says.
  Topic kezu_dreams with kezu "Ask Kezu what she dreams" when state(kezu, waking) and not confessed(kezu) {
    Says "'Nothing,' says Kezu. 'I sleep like the dead, and I'm too old to be dreaming.' She drinks. Her other hand is on the ox at her throat. 'It's the two nights awake. It'll pass.'".
  }
  Relation confessed(group).
  Topic kezu_why with kezu "Ask Kezu why she shut her eyes" when state(kezu, waking) and knows(actor, door_opened) and not told(kezu, night) {
    Says "Kezu looks at the fire. 'She asked,' she says. 'She was fourteen and she'd been fourteen a long time, and there's always a room behind her, she said. I had a daughter.' She turns the ox on its cord. 'Nineteen years I never looked away from anything I was paid to watch. That's the Watch. You'll tell me I broke it, and I did.'".
    On discuss { Assert told(kezu, night). }
  }
  Topic kezu_cup with kezu "Tell Kezu her cracked cup has a twin on a shelf in the house" when state(kezu, waking) and knows(actor, cups_match) and not confessed(kezu) {
    Says "Kezu sets her cup down. 'Then I'll tell you, since you've been in.' She does not lower her voice; she has no one to hide it from but herself. 'I dream a hallway with a great many doors, every night since. And someone knocking at the front one, wrong. Not loud. Wrong. And last night I was walking toward it.' She looks at the curtain to her room. 'Hanu sat up with me. If she nods off, I don't know where I go.'".
    On discuss { Assert confessed(kezu). Assert knows(actor, kezu_dreams_house). }
  }
  Discovery kezu_dreams_house "Kezu dreams the house every night since she opened the door: a hallway of many doors, and someone knocking at the front one, wrong. Last night she was walking toward it in her sleep.".
  // Not "owned by kezu": the shared rule would have her see it while asleep, and turn on her own student for ever.
  Item kezu_cup "a cracked orange-glass cup, child-sized" is dreg at kezu_bed.
  Rule kezu_misses_cup when carries(party, kezu_cup) and state(kezu, waking) and together(kezu, party) and not askedBack(kezu)
    says "Kezu sees the cup in your hands, and goes very still. 'Put it back,' she says. 'Please. Where it was. I don't want it, and I don't want it gone.'" {
    Assert askedBack(kezu). }
  Relation askedBack(group).
  Initially Assert seventhDreg(kezu_cup).
  Observe cup_seen at kezu_bed as feature when at(kezu_cup, kezu_bed) "On the floor by the bed stands a small cup of orange glass, the right size for a child, with a crack in the rim." teaches kezu_cup_seen.
  Discovery kezu_cup_seen "By Kezu's bed stands a child-sized cup of orange glass with a crack in its rim, a dreg that came the night she opened the door.".

  // Kezu walks in her sleep, if nobody watches her: every night she dreams the house she is nearer to it. The second
  // night the house grows a door in her room. Hanu sits up with her, until the low hour.
  Measure dreamt(group).
  Rule low_hour when dark() and untilLight(clock) <= 6 and untilLight(clock) > 0 and watcher(?w) and not drowsing(?w)
    and not (together(?w, party) and not abed(party)) and not stareTrained(?w) { Assert drowsing(?w). }
  Rule day_wakes when not dark() and drowsing(?w) { Retract drowsing(?w). }
  Rule kezu_dreams_on when state(kezu, sleeping) and dark() and untilLight(clock) == 2 and not watchedRoom(kezu_bed)
    { Increase dreamt(kezu) by 1. }
  Rule kezu_is_a_door when dreamt(kezu) >= 2 and not doorIn(kezu_bed) { Assert doorIn(kezu_bed). }
  Relation doorIn(place).
  Observe kezu_door_seen at kezu_bed as revelation when doorIn(kezu_bed) "In the wall beside Kezu's bed, where there was whitewash yesterday, there is a door of green glass the height of a child, with a brown seam round it that is warm to the hand." teaches kezu_door_known.
  Discovery kezu_door_known "A door of the house has grown in the wall of Kezu's sleeping-room. Kezu is a door: she dreams the house, and the house has come to her.".
  Rule kezu_walks when doorIn(kezu_bed) and state(kezu, sleeping) and dark() and not watchedRoom(kezu_bed) and at(kezu, kezu_bed)
    { Assert at(kezu, long_hall). Assert sleepwalking(kezu). }
  Relation sleepwalking(group).
  Rule kezu_comes_back when sleepwalking(kezu) and not dark() { Retract sleepwalking(kezu). Assert at(kezu, kezu_bed). }

  // ---- The sleeping-hall ----
  Person wenu "Wenu" at hall_floor {
    Role "hall-warden of Cobble Ring, who keeps the common sleeping-hall". Ancestry human. Peaceable.
    Offers lodging "a watched bed in the common hall" for 2 coin.
    Sells wax_plugs for 1 coin from 3.
    Sells torch for 1 coin from 2.
  }
  // Bolt is an old dog, not a creature with a temperament: as a person he would be a feral cave hound that warns.
  Thing bolt "Bolt, the hall dog" at hall_floor {
    State asleep "An old brindled dog sleeps across the hall door, so that everyone who comes in has to step over him.".
    State fussed "Bolt has rolled over to have his belly scratched, and thumps the floor with his tail.".
    Change scratch "Scratch Bolt behind the ears" from asleep to fussed.
  }
  Rule bolt_settles when state(bolt, fussed) and not at(party, hall_floor) { Assert state(bolt, asleep). }
  Topic wenu_watch with wenu "Ask Wenu about the house in Haddo's barley" when true once {
    Says "'Four on it day and night,' says Wenu, 'and we charge a mark to go and look, which the reeve says is the town's due and I say is a scandal. They turn their backs for you while the little door opens. That's what the mark is for.' She looks at you. 'Kezu's girl. You'll know better than to go in.'".
    On discuss { Assert knows(actor, visit_custom). }
  }
  Discovery visit_custom "Cobble Ring charges a mark to visit the house in the barley. For the mark, the watchers on the stools turn their backs while the small door opens, and turn back once you are in.".

  // ---- The reeve, the council and the Company's offer ----
  Person tessa "Ammu Tessa" at reeve_room {
    Role "crater-reeve of Cobble Ring". Ancestry human. Peaceable.
  }
  Measure sellVotes(group).
  Initially Set sellVotes(tessa) to 5.
  Topic tessa_offer with tessa "Ask the reeve about the Company's offer" when not voted(tessa) {
    Says "'Two thousand marks,' says Ammu Tessa, and taps a slate. 'For a thing we pay four watchers to sit by and that grows if they so much as yawn. Haddo would sell it tonight; it's his field, and his barley's spoiled. The council meets at noon the day after tomorrow. Four arcs for selling, three against, two who'll go with whoever spoke to them last.' She looks up. 'If you've something to say to the council, say it to me first.'".
    On discuss { Assert knows(actor, vote_due). }
  }
  Discovery vote_due "Cobble Ring's council votes at noon on the third day on whether to sell the house in the barley to the Lantern Company for two thousand marks. If it sells, the Company's own guards take the stools.".
  Relation voted(group). Relation persuaded(group, fact).
  Topic tessa_house with tessa "Tell the reeve the house is one house with rooms up in the Keel" when knows(actor, house_one) and not persuaded(tessa, house_one) and not voted(tessa) {
    Says "The reeve puts down her stylus. 'Up there.' She looks at the ceiling, and then, ceilings telling her nothing, at the slates. 'Then what the Company is buying is a door into the city.' She makes a mark on a slate. 'That's a different vote.'".
    On discuss { Assert persuaded(tessa, house_one). Decrease sellVotes(tessa) by 2. }
  }
  Topic tessa_well with tessa "Tell the reeve the house is growing a cellar toward Haddo's well" when knows(actor, well_reached) and not persuaded(tessa, well_reached) and not voted(tessa) {
    Says "'Haddo's well is the east arc's well,' says the reeve. 'Forty households.' She is on her feet. 'Whoever owns it, the town will want it watched by people who were born watching.'".
    On discuss { Assert persuaded(tessa, well_reached). Decrease sellVotes(tessa) by 2. }
  }
  Topic tessa_sell with tessa "Tell the reeve you think the town should sell" when not voted(tessa) and not persuaded(tessa, sale_backed) {
    Says "'Do you.' The reeve counts something on her fingers. 'Your teacher opened its door. I'd have thought you'd want it kept.' She makes a mark anyway.".
    On discuss { Assert persuaded(tessa, sale_backed). Increase sellVotes(tessa) by 1. }
  }
  Entity sale_backed: fact "that the town should sell".
  // Noon on the third day: the council votes. Five or more of nine arcs for the sale carries it.
  Rule council_sells when watch(clock) >= 312 and not voted(tessa) and sellVotes(tessa) >= 5 { Assert voted(tessa). Assert sold(annex). }
  Rule council_keeps when watch(clock) >= 312 and not voted(tessa) and sellVotes(tessa) < 5 { Assert voted(tessa). }
  Relation sold(place).
  Topic tessa_kept with tessa "Ask the reeve what the council decided" when voted(tessa) and not sold(annex) once {
    Says "'Kept.' Ammu Tessa squares the stack of slates. 'And Haddo voted a mark a week for his barley, which he'll spend complaining.' She looks toward the east lip as if she could see the green glass through the wall. 'So it's ours to watch, the way it always was. Four on the stools, day and night, and nobody yawns.'".
  }
  Topic tessa_sold with tessa "Ask the reeve what the council decided" when sold(annex) once {
    Says "'Sold.' The reeve turns the Company draft face down on the slates. 'Two thousand marks. The Company's guards take the stools at dusk.' She taps the draft. 'They don't know how to sit up. I told Dace. He wrote it down.'".
  }
  Observe vote_kept at reeve_room as event when voted(tessa) and not sold(annex) "The council's slates are stacked on the table. The house stays Cobble Ring's to watch, and Haddo has been voted a mark a week for his barley.".
  Observe vote_sold at reeve_room as event when sold(annex) "The council's slates are stacked on the table, and on top of them a Company draft for two thousand marks.".

  // ---- Return visits: the hall's customs, the loft after the door, the town after the vote ----
  Topic wenu_dregs with wenu "Ask Wenu about the small glassy things people wake holding" when true once {
    Says "'Dregs,' says Wenu, and tucks a blanket tighter than it needs. 'Sleep where nobody's sat up with you and you may wake with one in your fist: weak-tea glass, warm, shaped like something you loved when you were small. A ladle. A horse.' She does not say what hers was. 'The reed-growers bury them under the beds, they say it keeps the reeds sweet. The polishers pay by the weight. I say that is selling somebody's childhood by the pound, and I take their money for the bed all the same.'".
    On discuss { Assert knows(actor, dreg_custom). }
  }
  Discovery dreg_custom "In Cobble Ring a dreg is what an unwatched sleeper may wake holding, shaped like something loved: the reed-growers bury them under the reeds, and the lens-polishers buy them by the weight.".
  Topic wenu_north with wenu "Tell Wenu how the towns you come from keep their sleepers" when true once {
    Says "Wenu stops with a blanket half folded. 'Nobody sits up?' She waits for you to say you are joking. 'In a bed, alone, with the door on a bar, and the whole night going by with nobody counting it?' She shakes the blanket out harder than it needs. 'Don't say that in the hall, or thirty of them will walk north to try it and I will have a hall of empty beds and a mouth full of I-told-you.' But she pushes the stool with the wax plugs on it an inch toward you, as a woman does who has been told something dreadful and wants to be of use.".
  }
  Topic hanu_door with hanu "Tell Hanu about the green door in the wall beside her sister's bed" when knows(actor, kezu_door_known) and not told(hanu, door) once {
    Says "Hanu looks at the shutter, and then, for the first time since you came in, not at the shutter. She leans over the rail of the loft until she can see the whitewash by the bed, and the green that is not whitewash. The hand-bell is still in her fist. 'It was not there at supper,' she says. 'I have not looked away. I have not.' She sits back. 'It does not open while I am looking at it. So I will look at it. And Tobu can look at her.'".
    On discuss { Assert told(hanu, door). }
  }
  Observe hanu_door_after at kezu_loft as ambience when told(hanu, door) and doorIn(kezu_bed) "Hanu has moved her stool a hand's breadth along the loft, so that the shutter shows her the bed and the green door both. She does not look at either as one looks at a child; she looks as one looks at a pot about to boil.".
  Topic kezu_ox with kezu "Ask Kezu about the little ox at her throat" when state(kezu, waking) and not told(kezu, ox) once {
    Says "Kezu's hand closes round it. 'It is a dreg,' she says, as if you had called it something else. 'It was in my fist the morning after my girl went. I had slept the first night in nineteen years with nobody sitting up, because there was nobody left to sit.' She holds it out on the cord for you to see: a glassy ox the colour of weak tea, one horn broken short. 'She had one in wood. It lost its horn on the pond stair. This is what I did with the not watching.' She puts it back inside her collar. 'So when I tell you what happens to what nobody watches, I am not repeating a saying.'".
    On discuss { Assert told(kezu, ox). }
  }
  Observe lofts_hour at pond_side as ambience when dark() and untilLight(clock) > 6 "Somewhere round the rim a hand-bell rings the hour, and the next loft takes it up, and the next, house to house all round the crater, until the sound has come back to where it began. Nobody on the causeway hurries. Nobody on it is alone, either.".
  Observe market_morning at pond_side as ambience when not dark() and not voted(tessa) "At the anchor-stone the market is half set out, and every stall has a stool beside it with someone on it who is not selling: a boy, a widow, a man with a goose under his arm. They are the stall-sitters, and they sit with their backs to their own goods, facing the rim, so that nothing in Cobble Ring is ever watched by only one pair of eyes.".
  Observe market_after at pond_side as ambience when voted(tessa) and not dark() "At the anchor-stone the talk is of the vote, and nobody will say how they voted, though everybody knows how everybody else did. A child has chalked a tally on the stone: four, then three, then two more with a question mark.".
  Topic haddo_vote_kept with haddo "Ask Haddo how he voted" when voted(tessa) and not sold(annex) once {
    Says "'Against myself,' says Haddo, and looks astonished to hear it. 'The reeve asked me to say what a field is for, and I said barley, and then I could not say it with a straight face.' He leans on the fence. 'A mark a week. For the barley that will not come up. I have decided to take it as pity and not as wages.'".
  }
  Topic haddo_vote_sold with haddo "Ask Haddo what the sale has left him" when sold(annex) once {
    Says "'A fence,' says Haddo. 'Mended, with the town's money, round a field I cannot cross without a clerk's leave.' He nods toward the stools, where blue coats sit. 'I wanted it gone. It is gone, and I find I know where it is every minute of the day.'".
  }
  Topic wenu_vote with wenu "Ask Wenu what the hall says of the council's vote" when voted(tessa) once {
    Says "'The hall,' says Wenu, 'has said nothing, which is a thing to hear from thirty people.' She squares the blankets. 'Six slept sound last night. They always do after a vote. It is the ones who lie awake who voted the way they wanted.'".
  }
}

data/adventures/house-that-grows/company:
Module hhg "The House That Grows" {
  // A stare-student of Cobble Ring, in Kezu's kitchen (placed.kyr is the world's own company, come in by the rim).
  Company party "You" of 1 to 3 at kezu_kitchen.
  Initially Set quantity(party, gold) to 6.
  Initially Assert stareTrained(party).
}

data/adventures/house-that-grows/keel.ky:
Module hhg "The House That Grows" {
  Description "The Keel's upper decks, 3.5 km over the Strewnfield: the Long Hall the Seventh has dreamed for two and a half thousand years, grown through the Lifted children's old dormitories.".

  Place decks "the dormitory deck" is level within keel.
  Place coats_high "the hall of coats" is room within decks at 0, 1 indoors.
  Place long_hall "the Long Hall" is room within decks at 1, 1 indoors.
  Place bunk_room "the bunk room" is room within decks at 2, 0 indoors seen as "a room beyond the cold door" until bunk_found.
  Place lamp_store "the lamp store" is room within decks at 2, 2 indoors seen as "a room beyond the glinting door" until lamps_found.
  Place choir_room "the choir room" is room within decks at 1, 2 indoors seen as "a room beyond the humming door" until choir_found.
  Place dorm_stair "the dormitory stair" is room within decks at 1, 0 indoors.
  Place keel_edge "the open edge" is room within keel at 3, 1 outdoors.
  Place rigging_foot "the foot of Rigging Row" is room within keel at 1, 3 outdoors.

  Passage high_far_door "the far door of the hall of coats" is door between coats_high and long_hall.
  Passage bunk_door "a door with cold air under it" is door between long_hall and bunk_room.
  Passage lamp_door "a door that glints" is door between long_hall and lamp_store.
  Passage choir_door "a door with a hum behind it" is door between long_hall and choir_room.
  Passage stair_arch "the stone arch to the stair" is arch between long_hall and dorm_stair.
  Passage knot_way "the dormitory stair" is stair between dorm_stair and rigging_foot.
  Passage edge_gap "a gap in the bunk room's outer wall" is crawl between bunk_room and keel_edge.
  // Kezu's door: grown in the wall of her sleeping-room, it opens on the Long Hall.
  Passage kezu_wall "the green door in Kezu's wall" is door between kezu_bed and long_hall hidden until kezu_door_known.
  Initially Assert dreamDoor(high_far_door). Initially Assert dreamDoor(bunk_door). Initially Assert dreamDoor(lamp_door).
  Initially Assert dreamDoor(choir_door). Initially Assert dreamDoor(kezu_wall).

  Initially Assert houseRoom(coats_high). Initially Assert houseRoom(long_hall). Initially Assert houseRoom(bunk_room).
  Initially Assert houseRoom(lamp_store). Initially Assert houseRoom(choir_room).
  Initially Assert keelSide(coats_high). Initially Assert keelSide(long_hall). Initially Assert keelSide(bunk_room).
  Initially Assert keelSide(lamp_store). Initially Assert keelSide(choir_room).
  // The Keel's rooms take the same bands of the die as the Annex's: the two bodies may grow in the same turn.
  Initially Set bandLo(coats_high) to 69. Initially Set bandHi(coats_high) to 85.
  Initially Set bandLo(long_hall) to 86. Initially Set bandHi(long_hall) to 100.
  Initially Set bandLo(bunk_room) to 1. Initially Set bandHi(bunk_room) to 17.
  Initially Set bandLo(lamp_store) to 18. Initially Set bandHi(lamp_store) to 34.
  Initially Set bandLo(choir_room) to 35. Initially Set bandHi(choir_room) to 51.
  Initially Assert unlit(dorm_stair).

  Thing high_far_leaf "the far door of the hall of coats" on high_far_door {
    State shut blocking "A tall glass door, shut. Beyond it, grey light from below.".
    State bled blocking "Where the far door was there is only glass, and a brown seam that has bled a little, warm, and stopped.".
  }
  Thing bunk_leaf "a door with cold air under it" on bunk_door { State shut blocking "A glass door, shut, with a draught coming under it that smells of wind.". }
  Thing lamp_leaf "a door that glints" on lamp_door { State shut blocking "A glass door, shut. Something glints in rows beyond it.". }
  Thing choir_leaf "a door with a hum behind it" on choir_door { State shut blocking "A glass door, shut. Through it, very faintly, a hum.". }
  Thing kezu_leaf "the green door in Kezu's wall" on kezu_wall { State shut blocking "A door of green glass the height of a child, shut, its seam warm.". }
  // Left long enough, the hall of coats seals its far door and opens another into the bunk room.
  Passage coats_bunks "a new door in the hall of coats" is door between coats_high and bunk_room hidden until coats_moved.
  Initially Assert dreamDoor(coats_bunks).
  Thing coats_bunks_leaf "a new door in the hall of coats" on coats_bunks { State shut blocking "A new glass door, shut, its seams still soft.". }
  Rule far_door_bleeds when grown(coats_high) >= 2 and state(high_far_leaf, shut) { Assert state(high_far_leaf, bled). }
  Observe coats_moved_seen at coats_high as revelation when state(high_far_leaf, bled) "The far door is gone. In the side wall, where there was none, there is a new one." teaches coats_moved.
  Discovery coats_moved "The hall of coats in the city has grown shut its far door and grown a new one into the bunk room.".

  Observe coats_high_scene at coats_high as fixture when true "A hall of hooks at the height of a barn roof, every one hung with a child's coat. It is the hall of coats in the barley, hook for hook, but the light comes up grey through the floor instead of in green through the walls, and the air is thin and cold.".

  // ---- The Long Hall ----
  Observe long_hall_scene at long_hall as fixture when true "A hallway as long as a field, its ceiling high enough for a giant child, its light coming up grey through the glass floor from the cloud below. Doors go off on both sides at intervals that do not look the same twice. You weigh less here: your steps come down slowly.".
  Observe hall_far at long_hall as feature when true "Far down the hall, past more doors than you can count, the floor slopes away toward the city's lowest point, and something down there is knocking. Not loud. Wrong.".
  Thing neme_chair "a child's chair in the middle of the hall" at long_hall {
    State empty "In the middle of the Long Hall stands a child's chair, child-sized, the right size, set where someone sitting in it can see forty doors at once. Round it, scratched into the glass floor, are tally marks: hundreds of them, in rows.".
  }
  Observe tallies at long_hall as revelation when tried(neme_chair, looking) "The tallies run in rows of seven, a week to a row, and there are more rows than you can count before your eyes ache. Twelve years of nights, someone sat here and watched these doors." teaches neme_watched.
  Discovery neme_watched "Someone kept the Long Hall from growing for twelve years by sitting in a child's chair in its middle and watching forty doors.".
  Action sit_watch(actor: group, site: place) "Sit in the child's chair and watch the doors" {
    Description "From here one person can see forty doors at once. Watching them, you hold the rooms behind them.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, long_hall) and not sitting(actor) and companyLooks(actor, site).
    On success { Assert sitting(actor). }
    Result "The chair takes your weight. Forty doors: you count them, and hold the count.".
  }
  Action stand_up(actor: group, site: place) "Get up out of the child's chair" {
    Requires able(actor) and sitting(actor) and at(actor, site).
    On success { Retract sitting(actor). }
    Result "You get up. Behind you, somewhere, a door you were not watching changes.".
  }
  Observe sleepwalker at long_hall as event when at(kezu, long_hall) and sleepwalking(kezu) "Kezu is in the Long Hall in her nightdress, barefoot on the glass, walking slowly away from you down the slope with her eyes open. She is going toward the knocking.".

  // ---- The bunk room ----
  Discovery bunk_found "Beyond the cold door off the Long Hall is the bunk room: the Lifted children's old stone dormitory, grown over with glass.".
  Observe bunk_scene at bunk_room as fixture when true "Inside the glass is a stone room older than the glass: a barracks of forty stone shelves for sleeping, three high, like a fossil caught in amber. Children's names are scratched into the stone of every shelf, hundreds of them, in two kinds of letters." teaches bunk_found.
  Observe bunk_edge at bunk_room as feature when true "In the outer wall the old stone has fallen away, and through the gap there is nothing but grey air, and wind.".
  Discovery red_door_known "Among the names on the bunk shelves, scratched in Undal letters by a child of Lowmere: RED DOOR, POND ARC." {
    Found by searching bunk_room "On a low shelf by the gap, among the names, someone small scratched in Undal letters: RED DOOR, POND ARC. LOWMERE.".
  }
  Item bunk_dreg "a dreg like a little wooden ox-cart" is dreg at bunk_room.
  Initially Assert seventhDreg(bunk_dreg).
  Observe bunk_dreg_seen at bunk_room as feature when at(bunk_dreg, bunk_room) "On one of the shelves lies a small glassy thing the colour of weak tea, shaped like a toy ox-cart. It is warm.".
  Person mice "a swarm of glass mice" at bunk_room {
    Role "dreg vermin, glittering, the size of thumbs". Species rat. Numbers 12. Level 1.
    Temperament wary. Refuge bunk_room.
    Flinches "The glass mice pour away into the bunk shelves with a sound like spilled beads.".
    Comes "The glass mice come at your lamp in a glittering wave.".
  }
  // Glass mice eat light: a lit lamp near them burns down faster.
  Rule mice_eat_light when lit(?l) and at(?l, bunk_room) and at(mice, bunk_room) and able(mice) { Decrease burnsOut(?l) by 1. }

  // ---- The open edge ----
  Observe edge_scene at keel_edge as fixture when true "A ledge of the Keel's raw underside, hung with old roots of stone. Below, a long way below, the cloud of the Veil, and through a tear in it the Strewnfield, a country of round ponds shining like coins. Gritcrows hang in the wind at your height and do not land.".
  Hazard keel_fall "A fall from the Keel's edge" means "Deal (2d6) physical damage to ally unless dexterity save against (11).".
  Thing edge_wind "the wind at the edge" on edge_gap is scenery {
    State gusting dangerous "Wind comes through the gap in gusts that would take a careless climber off the ledge.".
    State still "The wind at the gap has dropped.".
    Hurts with keel_fall when gusting then still.
  }
  Rule wind_rises when state(edge_wind, still) and untilLight(clock) == 1 { Assert state(edge_wind, gusting). }

  // ---- The lamp store and the boy hiding in it ----
  Discovery lamps_found "Beyond the glinting door off the Long Hall is a store of burnt-out Ithren lamps.".
  Observe lamp_scene at lamp_store as fixture when true "Shelves to the ceiling, and on them, in rows, thousands of lamps of selm-glass the size of pears, every one burnt out and grey. Among them, newer, bundles in netting: pots, a cradle, a rolled rug, tied with Netters' knots." teaches lamps_found.
  Thing lamp_shelves "the lamp shelves" at lamp_store {
    Holds.
    State rows "Lamps, thousands of them, in rows.".
  }
  Item lamp_a "a burnt-out Ithren lamp" is ithren_lamp in lamp_shelves.
  Item lamp_b "a burnt-out Ithren lamp" is ithren_lamp in lamp_shelves.
  Item lamp_c "a burnt-out Ithren lamp" is ithren_lamp in lamp_shelves.
  Person quill "Ottie" at lamp_store {
    Role "a Lifted boy of eleven, keeping watch over Netters' bundles among the lamps". Ancestry human. Peaceable.
  }
  Initially Assert watcher(quill). Initially Assert home(quill, sennu_kitchen).
  // A boy being taken home is not keeping a watch.
  Rule quill_leaves_post when following(quill, ?c) and watcher(quill) { Retract watcher(quill). }
  Topic quill_bundles with quill "Ask Ottie what he is doing down here" when true once {
    Says "'Minding,' says Ottie. 'Captain Isele's span. The Ballast-Reeve's going to drop our houses over the side, so we're hiding what's ours down here where he won't look.' He hugs his knees. 'Nobody comes down here. The doors move.'".
  }
  Topic quill_home with quill "Ask Ottie where he comes from" when not acceptsEscort(quill, actor) {
    Says "'The floor,' says Ottie, which is what the city calls the ground. 'I don't know the town. There was a pond, and our door was red. My mother sang.' He looks at you. 'You're from the floor. Is it true you have to have someone watch you sleep?'".
  }
  Topic quill_red_door with quill "Tell Ottie about the red door scratched on the bunk shelf" when knows(actor, red_door_known) and not acceptsEscort(quill, actor) {
    Says "Ottie is on his feet before you have finished. 'Lowmere,' he says, trying it. 'Lowmere.' He looks at the bundles he is supposed to be minding, and then at you. 'Will you take me? I can't go back up by the stair. Isele will be cross, but she'd go, if it was hers.'".
    On discuss { Assert acceptsEscort(quill, actor). }
  }
  Topic quill_lamps with quill "Ask Ottie about the lamps" when true once {
    Says "'Two marks apiece on the floor, Isele says, for curiosities.' Ottie picks one off a shelf and turns it. 'My gran said when they were lit they looked at you. They used them for night watches, before the court took the scrapings for drinking.'".
    On discuss { Assert knows(actor, lamp_lore). }
  }
  Discovery lamp_lore "The Ithren used their lamps for night watches, before the court took the star-scrapings that fed them for drinking: lit, they looked at you.".

  // ---- The choir room ----
  Discovery choir_found "Beyond the humming door off the Long Hall are forty glass cradles that sing.".
  Observe choir_scene at choir_room as fixture when true "Forty cradles of glass stand in a row down the room, each rocking very slightly, and all forty hum one lullaby in one voice: an old tune of Thale, low and slow." teaches choir_found.
  Thing choir "forty glass cradles" at choir_room {
    State humming "Forty glass cradles rock and hum one lullaby in one voice.".
    State hushed "The forty cradles have stopped humming. They are rocking very slightly, toward you. They are listening.".
    Change sing "Sing the lullaby back to the cradles" from humming to hushed.
  }
  Rule choir_resumes when state(choir, hushed) and not at(party, choir_room) { Assert state(choir, humming). }
  Measure listened(group).
  Rule choir_lulls when at(party, choir_room) and state(choir, humming) and not holding(party, wax_plugs) { Increase listened(party) by 1. }
  Rule choir_rests when not at(party, choir_room) and listened(party) > 0 { Set listened(party) to 0. }
  // The lullaby cannot be a hazard (a condition applied outside a fight lasts no time, or stops the game), so falling
  // asleep to it is a place: the dream the Choir sings you into, for an hour.
  Place lull_dream "the hallway in the dream" is room within decks at 3, 2 indoors.
  Measure wakesAt(group).
  Rule choir_sleeps when listened(party) >= 3 and dice(clock) <= 60 says "The lullaby has got into your eyelids. You think you will just close them for the length of one verse." {
    Assert at(party, lull_dream). Set wakesAt(party) to watch(clock). Increase wakesAt(party) by 6. Set listened(party) to 0. }
  Rule choir_shrugged when listened(party) >= 3 and at(party, choir_room) { Set listened(party) to 0. }
  Observe dream_scene at lull_dream as fixture when true "You are in a hallway with a great many doors, and you are very small, and someone is knocking at the front one, wrong. A girl's voice somewhere says: there's always a room behind me.".
  Rule lull_wakes when at(party, lull_dream) and watch(clock) >= wakesAt(party) says "You wake on the glass floor of the choir room with your cheek cold and the cradles rocking." { Assert at(party, choir_room). }
  Observe choir_counts at choir_room as revelation when state(choir, humming) and not holding(party, wax_plugs) "Under the lullaby, if you listen, the words are a count: one pane, two panes, three, and on, and it stops, and starts again, and each time it gets a little further." teaches front_door_known.
  Discovery front_door_known "The Choir counts panes under its lullaby, and each count goes a little further: something in the house is being built a pane at a time.".

  // ---- The dormitory stair and the knot-door ----
  Observe stair_scene at dorm_stair as fixture when true "A stone stair, older than the glass, climbing out of the house into the dark. At its head, a door of rope.".
  Thing knot_door "the knot-door" on knot_way {
    State knotted blocking "The head of the stair is closed by a door of net, its edge tied to its frame in a Netter's knot as big as a fist, sealed with tar.".
    State undone "The Netters' knot hangs undone, and the net door swings.".
    Change undo "Undo the Netters' knot" from knotted to undone needing lockwork or climbing.
  }
  Relation knotBroken(place).
  Rule knot_known when state(knot_door, undone) and not knotBroken(rigging_foot) { Assert knotBroken(rigging_foot). }
  Observe rigging_scene at rigging_foot as fixture when true "You come up through a hatch into wind and rigging: a street of houses hung in caul-cable between two terraces of garden, its floor a net. Somewhere along it a bell is ringing, and people are coming, roped, along the net toward the hatch you came through.".
  Observe rigging_angry at rigging_foot as event when knotBroken(rigging_foot) "A Netter in a harness reaches the hatch first and looks at the undone knot, and then at you. 'From the wrong side,' she says. 'That's theft, floor-dirt. The Knot House will hear of it.'".
}

data/adventures/house-that-grows/lore.ky:
Module hhg "The House That Grows" {
  Description "Where Sabe Orrel's name comes from.".
  Discovery lore_orrel_post "Sabe Orrel says Sabe is the post, and Orrel the name of those who hold it; she has heard of another Orrel, on a ship, who holds the same post on a stair that is not hers.".
  Topic lore_sabe_post with sabe "Ask Sabe why people call her by her given name first" when true once {
    Says "'It is not a given name,' says Sabe. 'It is the post. The one who keeps the lamp is Sabe, and the lamp has always been kept by an Orrel. My mother was Sabe, and her mother.' She turns the lamp with her foot. 'They say there is another Orrel somewhere, on a ship in a place with no weather, who keeps a stair lit and is called the same. I would like to meet him.'".
    On discuss { Assert knows(actor, lore_orrel_post). }
  }
}

data/adventures/house-that-grows/lowmere:
Module hhg "The House That Grows" {
  Description "The causeway to Lowmere, and a red door on its pond arc.".

  Place causeway "the crater causeway" is room within causeway_country at 0, 0.
  Place pond_arc "Lowmere's pond arc" is room within lowmere at 1, 1.
  Place sennu_house "the house with the red door" is building within lowmere.
  Place sennu_kitchen "a cord-weaver's kitchen" is room within sennu_house at 1, 2.
  Passage west_road "the west causeway" is causeway between rim and causeway taking 2 hours.
  Passage lowmere_road "the causeway into Lowmere" is causeway between causeway and pond_arc taking 2 hours.
  Passage red_door "the red door" is door between pond_arc and sennu_kitchen.

  Observe causeway_scene at causeway as fixture when true "The causeway runs along crater-rims from town to town, a raised road of packed earth between ponds. Out on the plain, cribs of timber packed with wool-bale run in a fan toward the middle of the country: Lowmere's net, to catch the city.".
  Observe arc_scene at pond_arc as fixture when true "Lowmere is bigger than Cobble Ring: nine arcs of houses facing a wide pond, and every yard full of cord-weaving. On the pond arc one door is painted red.".
  Observe kitchen_scene_l at sennu_kitchen as fixture when true "A cord-weaver's kitchen, cord on every peg, and a loom by the window onto the pond.".

  Person sennu "Sennu Arru" at sennu_kitchen {
    Role "a cord-weaver of Lowmere, who sold her boy up to the city in the famine year". Ancestry human. Peaceable.
  }
  Initially Assert kin(sennu, quill).
  Topic sennu_son with sennu "Ask Sennu Arru about the red door" when not cameHome(quill) {
    Says "'My husband painted it,' says Sennu, 'so the boy would know it from the sky.' She does not stop weaving. 'He was five. The famine year. They took him up as a Netter, for the tax.' The shuttle goes back and forth. 'They told us they'd call him something else.'".
  }
  Event quill_home near sennu when cameHome(quill) "Ottie stands in the red doorway and does not come in. Sennu looks up from the loom, and the shuttle falls out of her hand and runs across the floor on its thread. She says a name that is not Ottie. He says, 'You sang.'" then {
    Assert reunited(quill).
  }
  Relation reunited(group).
  Observe quill_stays at sennu_kitchen as ambience when reunited(quill) and at(quill, sennu_kitchen) "Ottie sits by the loom winding cord for his mother, very badly, and she lets him.".

  // Lowmere's net: the cribs on the plain, and the woman who walks them at first light.
  Person ketu "Ketu Sorrell" at pond_arc {
    Role "keeper of Lowmere's crib-line, who walks the wool-bale cribs at dawn to see what the city dropped". Ancestry human. Peaceable. Pronouns she.
    Buys ithren_lamp for 2 coin.
    Buys dreg for 2 coin.
  }
  Topic ketu_net with ketu "Ask Ketu Sorrell what the cribs have caught" when true once {
    Says "'Wool, mostly, that the wind took off the city's washing-lines,' says Ketu. 'A pot. A pair of boots, once, with a man's feet gone out of them a long time since. And lamps.' She holds up her palm, flat, for the size of a pear. 'Dead as stones. The Company's clerk gives two marks apiece, and so do I, and the difference is that I do not write it on a slate.' She watches the sky the way other people watch a road. 'Nothing living, in my time. My mother's time, a girl. She said she walked home.'".
  }
  Topic ketu_boy with ketu "Ask Ketu Sorrell whether the cribs ever catch children" when not cameHome(quill) once {
    Says "'The cribs are for wool,' says Ketu, too quickly. 'Sennu Arru asks me that every first light, and every first light I tell her.' She is looking at the red door. 'They do not let them fall. They put them down. There is a hatch, Sennu says, and a rope. If you know the knot on the rope you know the child went up and not down.' She turns away to her cribs. 'Ask her about the knot. Not me.'".
  }
  Topic sennu_knot with sennu "Ask Sennu Arru about the knot on the rope" when not cameHome(quill) and knows(actor, knot_custom) once {
    Says "The shuttle stops, for the first time since you came in. 'The Netters' knot,' says Sennu. 'Tied like a fist, sealed with tar. My husband saw it once, on the rope they let down for the tax-man's barrel.' She puts her palm flat on the cord on the loom as if it were a face. 'You have seen where it goes.'".
  }
  Topic sennu_after with sennu "Ask Sennu Arru how the boy is" when reunited(quill) once {
    Says "'Bad at it,' says Sennu, with enormous satisfaction. 'The winding. The knot. He pulls it the Netters' way and I have to take it out.' She will not look at the door, which is open, which is how a house with a red door says it has stopped waiting. 'He asks what the nights are for. He says up there he was told they were for being counted.' The shuttle goes across. 'I told him they were for the other thing.'".
  }
  Observe red_door_open at pond_arc as ambience when reunited(quill) "The red door of the house on the pond arc stands open in the daytime, which neighbours have noticed: nobody has seen it open in the daytime since the famine year.".

  Place offstage "elsewhere" is site within strewnfield at 3, 3.
  Place nowhere "nowhere" is room within offstage at 0, 0.
}

Module hhg "The House That Grows" {
  // The Strewnfield as a country beyond a march: the company that comes in by the rim of Cobble Ring is the world's own.
  Entity party: group "Your company".
  // What is said of the Strewnfield in the country behind it: once the council has voted, or the house has been
  // answered, the rumour of a room that grows is old news there, told by how it ended.
  Entity word: fact "What is said of the Strewnfield in the country behind it.".
  Entity word_free: fact "What is said there of the girl who came down.".
  Entity word_chair: fact "What is said there of the boy in the chair.".
  Entity word_sold: fact "What is said there of the sale.".
  Rule word_old when (voted(tessa) or nemeFree(party) or nemeSits(party)) and not stale(word) { Assert stale(word). }
  Rule word_free_old when nemeFree(party) and not stale(word_free) { Assert stale(word_free). }
  Rule word_chair_old when nemeSits(party) and not stale(word_chair) { Assert stale(word_chair). }
  Rule word_sold_old when sold(annex) and not stale(word_sold) { Assert stale(word_sold). }
}

data/adventures/house-that-grows/slope.k:
Module hhg "The House That Grows" {
  Description "Act III. The downhill end of the Long Hall, where the knocking is: the keeper of the Slope and her lamp, the Reckoning on the wall, a gate with two locks, a front door nobody has used, and the girl who has been knocking at it from the inside.".

  // The count the house is keeping is the Seventh's age in rooms; its first page (why a girl of fourteen was left to dream
  // a house for two and a half thousand years) is missing and is never read out. The price of reading it is that
  // whoever answers the knocking becomes the next to be asked.

  // ---- Places ----
  Place slope "the Slope" is room within decks at 0, 2 indoors.
  Place front_hall "the front hall" is room within decks at 0, 3 indoors.
  Place the_sill "the sill of the front door" is room within keel at 2, 3 outdoors.
  // The Long Hall runs downhill to the Slope on its own floor: the one way in the house that is not a dream-door, which
  // is why the knocking can always be heard from it.
  Passage hall_slope "the downhill end of the Long Hall" is passage between long_hall and slope.
  Passage front_gate "the gate at the foot of the Slope" is door between slope and front_hall.
  Passage front_door "the front door of the house" is door between front_hall and the_sill.

  Observe slope_scene at slope as fixture when true "The Long Hall's floor tilts here until it is a ramp for carts, and then a chute, glass worn to the shine of a spoon. Warm air comes up it from below, and with the air the smell of hot lamp-oil, and the knocking: eleven knocks, close, quick, and then a long wait of the exact length of the eleven, and then eleven again. At the foot a gate of green glass barred with brass stands shut. A lamp burns beside it.".
  Observe hall_slope_back at slope as feature when true "Behind you the Long Hall goes up and away, forty doors on each hand, all shut, none of them looking at you.".
  Observe front_hall_scene at front_hall as fixture when true "A porch the size of a barn, with one door in it: a plain front door of dark house-timber, the only wood in the whole house, with a brass knocker in the shape of a hand and three steps up to a threshold worn hollow by feet that never came. The knocking comes from the near side of it. On the wall are hooks for outdoor coats. The hooks are empty, every one.".
  Observe sill_scene at the_sill as fixture when true "A step of raw stone outside the front door, bolted to the underside of the Keel: nothing in front of it but a very long drop, the cloud of the Veil, and Cobble Ring's pond shining at the bottom of the air like a dropped coin.".

  // ---- Sabe Orrel, and the kept light ----
  Person sabe "Sabe Orrel" at slope {
    Role "keeper of the Slope, a Lifted woman of seventy who minds a lamp". Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Likeness "midwife".
    Greets "A small old woman in a Netters' harness gone grey with age sits on an upturned bucket with a lamp on the floor between her feet and her back against the gate. She does not look round. 'Don't open it,' she says. 'And don't sit on the floor, it slides. There's tea in the can, if the can's still hot.'".
  }
  Thing sabe_lamp "the keeper's lamp" at slope {
    State lit "A lamp of selm-glass the size of a pear burns on the floor beside the bucket: a small steady flame the colour of pond-ice, that does not move when the knocking comes. Under the foot, scratched small, a name: WENN.".
  }
  Initially Assert state(sabe_lamp, lit).
  // She wants the knocking to stop in her lifetime; she is afraid of being the one who stopped it; she says she only minds
  // the lamp; pressed, she will put the lamp out for you.
  Topic sabe_lamp_why with sabe "Ask Sabe whom the lamp is lit for" when true once {
    Says "'Wenn,' says Sabe. 'He had the night-watch on this stair when I was a girl. They said he came off it in the morning and I said I'd see.' She turns the lamp a quarter with her foot, the way you turn a pot to the fire. 'I have not seen. The oil is a mark a month.'".
  }
  Topic sabe_knock with sabe "Ask Sabe about the knocking" when true once {
    Says "'Eleven,' says Sabe, 'and a gap for the twelfth. Always has been, in my time and my mother's. If you count it out loud somebody counts the twelfth with you, so I don't.' She looks at her knuckles. 'It is a girl, and she is on the inside, and she thinks she is knocking to come in. Might be she is knocking to get out; from this side it sounds the same. Don't open that gate on a guess.'".
    On discuss { Assert knows(actor, eleven_strokes). }
  }
  Discovery eleven_strokes "The knocking at the front door of the house is eleven knocks and a gap of the same length where the twelfth should be. Whoever is inside has never been answered with the twelfth.".
  Topic sabe_undal with sabe "Ask Sabe whether she can read the Undal letters on the bunk shelves" when not gaveLetter(sabe) {
    Says "'Undal.' Sabe laughs, short. 'It's what the Ballast-Reeve forbids on the nets, so everyone on the nets can read it.' She takes from her harness a square of folded cord-paper, dark with years. 'The Lifted children wrote to their mothers on the shelves and never had a way to send it. I took this one off the end bunk before the glass grew over. It is to the reeve of Cobble Ring from her brother, who was taken up as a Netter in the famine year, and who writes in Undal because he had no one to teach him the other. I can read you it. You can carry it down.'".
    On discuss { Assert gaveLetter(sabe). Give hhg_undal_letter to actor. Assert knows(actor, brother_letter). }
  }
  Relation gaveLetter(group). Relation gaveToken(group). Relation gaveRope(group).
  Discovery brother_letter "Sabe Orrel holds a letter in Undal letters from the reeve of Cobble Ring's brother, taken up to the Keel as a child in the famine year: he writes that the house in the barley is not a thing to sell but a thing to answer, and that the city has no one who knows how.".
  Kind hhg_undal_letter "a Lifted child's letter in Undal" is gear worth 1 described "A square of cord-paper folded small, written in the narrow Undal letters the Ballast-Reeve forbids on the nets, in a child's careful hand; the creases are brown with years of a harness.".
  Item letter "a Lifted child's letter in Undal" is hhg_undal_letter at nowhere owned by sabe.
  Topic sabe_tea with sabe "Ask Sabe about the Netters, Captain Isele, and the Knot House" when true once {
    Says "'The Knot House ties the net, and unties whoever ties wrong,' says Sabe. 'Isele's span has the hatch at the foot of Rigging Row, and she'll hear a knot cut from the wrong side before the rope has stopped swinging. Cut it from the right side, with a Netter, and it's a favour. From below, it's theft.' She sips from the can. 'A rope would help you out along the edge. A Netter's token would help you with Isele.'".
    On discuss { Assert knows(actor, knot_custom). }
  }
  Discovery knot_custom "The Knot House treats a knot undone from below as theft; from above, with a Netter, as a favour. A Netters' token, or a paid fee, settles it with Isele's span.".
  Topic sabe_token with sabe "Ask Sabe for a Netters' token, to show Isele" when knows(actor, knot_custom) and not gaveToken(sabe) once {
    Says "Sabe unclips a knotted loop of tarred cord from her harness and puts it in your hand. 'Isele knows my knot,' she says. 'Show it, and say Sabe sent the floor-dirt. She'll swear. She won't strike.'".
    On discuss { Assert gaveToken(sabe). Give sabe_token to actor. }
  }
  Kind hhg_netters_token "a Netters' token" is gear worth 1 described "A loop of tarred cord tied in the knot the Knot House calls a keeper's: it means that the holder is a guest of the span, and that Sabe Orrel has stood for them.".
  Item sabe_token "a Netters' token" is hhg_netters_token at nowhere owned by sabe.
  Topic sabe_rope with sabe "Ask Sabe if she has a rope for the wind along the edge" when knows(actor, knot_custom) and not gaveRope(sabe) once {
    Says "She pulls a hank of Netters' rope from under the bucket, ten fathoms, and does not say where she got it. 'For the edge,' she says. 'Tie off on the bunk-room shelf and walk it. The wind's no worse than it was when I was a girl and no kinder.'".
    On discuss { Assert gaveRope(sabe). Give sabe_rope to actor. }
  }
  Item sabe_rope "ten fathoms of Netters' rope" is rope at nowhere owned by sabe.

  // ---- Voices of the company, by calling ----
  Relation heardShelf(group). Relation heardLamps(group). Relation heardHall(group). Relation heardSlope(group).
  Relation heardSlopeB(group). Relation heardHallB(group). Relation heardGate(group). Relation heardGateB(group).
  Rule voice_monk_shelf at cup_shelf when memberOf(?m, party) and hasCalling(?m, calling_monk) and awake(?m) and at(party, cup_shelf) and not heardShelf(party)
    says "{?m} stands with feet apart and lets the room come to {?m} instead of going to it. 'Count them again,' {?m} says, after a while. 'I'll wait. I would like to be wrong.'" {
    Assert heardShelf(party).
  }
  Rule voice_thief_lamps at lamp_store when memberOf(?m, party) and hasCalling(?m, calling_thief) and awake(?m) and at(party, lamp_store) and not heardLamps(party)
    says "{?m} lifts a lamp and weighs it, and sets it exactly back in its own dust-ring. 'These aren't stock,' {?m} says. 'Stock gets dusted. These get left. Somebody counts them every year and puts them back as they were.'" {
    Assert heardLamps(party).
  }
  Rule voice_ranger_hall at long_hall when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, long_hall) and not heardHall(party)
    says "{?m} crouches by a smear of glass dust at the hall's downhill end. 'Bare feet,' {?m} says. 'Small, and sixty years old, and been this way every night this week, down and not back.' {?m} follows the print with a finger. 'Somebody walks in her sleep and she isn't hurrying.'" {
    Assert heardHall(party).
  }
  Rule voice_bard_hall at long_hall when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, long_hall) and not heardHallB(party)
    says "{?m} hums, half a bar, and stops. 'That knocking is in six-eight,' {?m} says. 'Eleven beats and a rest, and the tune wants the rest. I could finish that phrase.' {?m} opens a mouth to supply the twelfth beat, and shuts it again." {
    Assert heardHallB(party).
  }
  Rule voice_cleric_slope at slope when memberOf(?m, party) and hasCalling(?m, calling_cleric) and awake(?m) and at(party, slope) and not heardSlope(party)
    says "{?m} lays a palm on the glass of the wall, as a priest lays it on a sickbed, and keeps it there through two rounds of the knocking. 'Warm,' {?m} says. 'Not from the lamp. It is warm the way a door is warm when someone has just let go of the handle.'" {
    Assert heardSlope(party).
  }
  Rule voice_warrior_slope at slope when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and at(party, slope) and not heardSlopeB(party)
    says "{?m} stamps once on the glass floor, and listens to what it says. 'This is a ramp for carts,' {?m} says. 'Wide, level, and sloped for a brake. Nobody builds that to bring a child in. They build it to take a thing out.'" {
    Assert heardSlopeB(party).
  }
  Rule voice_thief_gate at slope when memberOf(?m, party) and hasCalling(?m, calling_thief) and awake(?m) and at(party, slope) and not heardGate(party)
    says "{?m} goes down on a knee to the gate's lock and looks at it sideways. 'Two locks,' {?m} says. 'The old one is glass and means to be asked. The brass one is newer, and anything newer than the lock beside it was put on by somebody frightened.'" {
    Assert heardGate(party).
  }
  Rule voice_monk_gate at slope when memberOf(?m, party) and hasCalling(?m, calling_monk) and awake(?m) and at(party, slope) and not heardGateB(party)
    says "{?m} stands before the gate with the arms hung loose and does not blink. Behind the glass the knocking slows. 'She is not looking away either,' {?m} says, very quietly. 'My eyes are watering. Don't talk to me for a minute.'" {
    Assert heardGateB(party).
  }

  // ---- The gate: three ways, and each leaves a different girl ----
  Thing gate_leaf "the gate at the foot of the Slope" on front_gate {
    State barred blocking "A gate of green glass barred with a brass bar, shut. The knocking comes through it, eleven and the wait.".
    State open "The gate stands open. Beyond it is the front hall, and the knocking is very near.".
    Change pick "Pick the brass lock of the gate" from barred to open needing lockwork.
  }
  Initially Assert state(gate_leaf, barred).
  Relation gateForced(group). Relation gateAnswered(group). Relation gateStared(group).
  Rule gate_forced_known when state(gate_leaf, open) and not gateAnswered(party) and not gateStared(party) { Assert gateForced(party). }
  // The honest way: knock the eleven, and wait, and the twelfth comes from inside, because someone outside has answered.
  Action knock_count(actor: group, site: place) "Knock the eleven at the gate, and wait the length of the twelfth" {
    Description "Eleven knocks and the wait. The gate is asked, not forced.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, slope) and state(gate_leaf, barred) and knows(actor, eleven_strokes).
    Time 3.
    On success { Assert state(gate_leaf, open). Assert gateAnswered(party). }
    Result "You knock eleven, in her time, and wait in the gap. In the gap, from the other side of the glass, a twelfth knock comes: small, and a little late, and the glass sighs as the brass bar lifts itself clear. 'Oh,' says a voice behind the gate, in the voice of a girl who has been fourteen for two and a half thousand years. 'You waited.'".
  }
  // The monk's way (and the stare-trained's): look at the gate until it blinks. It is the one door that opens in front of its watcher.
  Action stare_gate(actor: group, site: place, m: member) "Stare at the gate with {m} until the brass bar lets go" {
    Description "A Watch-trained eye can outhold a girl who has had longer than the Watch to practise. It takes an hour, and nobody must look away.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, slope) and state(gate_leaf, barred) and stareTrained(actor)
      and memberOf(m, actor) and hasCalling(m, calling_monk) and awake(m) and companyLooks(actor, site).
    Time 6. Interrupted when not companyLooks(actor, site).
    On success { Assert state(gate_leaf, open). Assert gateStared(party). }
    Result "You do not blink. {m} does not blink. Somewhere behind the glass a girl sets her jaw and does not blink either, for a very long time, and then the brass bar drops its latch with a sound like someone sitting down, and a small voice says, aggrieved, 'That isn't fair, you've done it before.'".
  }
  // The Netters' rope across the edge to the sill is the way a visitor from outside comes to the front door: it takes the front way.
  Passage edge_to_sill "the ledge along the Keel to the sill" is crawl between keel_edge and the_sill.
  Thing sill_wind "the wind along the ledge" on edge_to_sill is scenery {
    State blowing dangerous "The wind along the Keel's underside would take a person off a ledge as wide as a hand.".
    State slack "The wind along the ledge has dropped to nothing.".
    Hurts with keel_fall when blowing then slack.
  }
  Initially Assert state(sill_wind, blowing).
  Rule sill_wind_drops when state(sill_wind, blowing) and untilLight(clock) == 3 { Assert state(sill_wind, slack). }
  Rule sill_wind_rises when state(sill_wind, slack) and untilLight(clock) == 1 { Assert state(sill_wind, blowing). }

  // ---- Neme, behind the gate ----
  Person neme "Neme" at front_hall {
    Role "the Seventh, a girl of fourteen, who has dreamed a house for two and a half thousand years". Ancestry human. Peaceable. Pronouns she. Manner jovial.
    Likeness "child".
    Greets "A girl of fourteen in a coat with the collar torn and a name stitched on it stands with her back to the front door and one hand lifted for a knock she is not giving. 'Don't look at me like that,' she says. 'I know it's rude. Everybody always does. I'm only knocking to see who answers.'".
  }
  Initially Assert at(neme, nowhere).
  Rule neme_there when state(gate_leaf, open) and at(neme, nowhere) { Retract at(neme, nowhere). Assert at(neme, front_hall). }
  Relation nemeTrusts(group). Relation nemeFree(group). Relation nemeSits(group). Relation nemeLeft(group).
  Topic neme_who with neme "Ask Neme who she is" when true once {
    Says "'Neme,' she says, 'and the Seventh, they say, but I can't count that high.' She scuffs a toe along the threshold. 'I asked a woman to look away once, in a field. She did. I didn't think she would, and then I couldn't stop looking at what she'd let go of. I only want one person to come in the way a person comes in. By the door.'".
    On discuss { Assert knows(actor, neme_asked). }
  }
  Discovery neme_asked "Neme asked Kezu, across a night of staring, to look away and let the little door open, because no one has ever come into her house by the front door.".
  Topic neme_knock with neme "Ask Neme why she knocks eleven and not twelve" when true once {
    Says "'Because it isn't polite to do all the knocking,' says Neme, as if you were being slow.".
  }
  Topic neme_marble with neme "Ask Neme about the coat with her name on it, and the orange marble" when knows(actor, door_opened) {
    Says "Neme looks at her collar. 'It's got a name on it because I kept losing it,' she says. 'I put the marble in the pocket so I could find the coat. It's a bad system.' She laughs, once. 'If you've got the marble, I'd like it back.'".
  }
  Relation marbleBack(group).
  Action give_marble(actor: group, site: place) "Give Neme the orange-glass marble from her coat" {
    Requires able(actor) and company(actor) and at(actor, site) and at(neme, site) and carries(actor, marble) and not nemeTrusts(party).
    On success { Spend marble from actor. Assert nemeTrusts(party). Assert marbleBack(party). }
    Result "She holds it up to the grey light and squints through it, and for a moment the whole front hall is the colour of weak tea. 'There,' she says. 'Now I know where I am.' She does not say thank you. She puts it in her pocket with a kind of savagery, and stands a little straighter.".
  }
  Rule neme_trusts_by_answer when gateAnswered(party) and at(neme, front_hall) and not nemeTrusts(party) { Assert nemeTrusts(party). }

  // ---- The choice at the front door: three answers, each of which costs something ----
  Relation tobuChair(group).
  // 1. Open the door, with her, and take her out into the Strewnfield. The house, finished, stops growing; Kezu sleeps.
  Action let_neme_out(actor: group, site: place) "Take Neme's hand, open the front door, and walk out by it with her" {
    Description "No one has ever come into the house by its front door. This is the first to go out of it.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, front_hall) and at(neme, front_hall) and state(gate_leaf, open) and nemeTrusts(party) and not nemeFree(party) and not nemeSits(party) and not nemeLeft(party).
    Time 2.
    On success { Assert nemeFree(party). Retract doorIn(kezu_bed). Retract sleepwalking(kezu). Assert at(neme, the_sill). Assert state(sill_wind, slack). Assert at(party, the_sill). }
    Result "The door opens outward, which it has never done. The wind comes in smelling of pond and barley, and Neme steps onto the sill in her torn coat with her chin up, and holds your hand a great deal harder than you expected. Below you, a very long way, a ring of houses faces a pond, and in every one a watcher in a loft turns, one after another, to look up. Behind you the house breathes out, and for the first time in its life stops growing.".
  }
  // 2. Ask Tobu to sit the chair for good, and leave the girl her house: the watcher's price.
  Action tobu_takes_chair(actor: group, site: place) "Ask Tobu to go up and take the child's chair for good, and tell Neme she may go" {
    Description "A watched house does not grow. A watcher in the chair is a watcher for good.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, front_hall) and at(neme, front_hall) and state(gate_leaf, open) and nemeTrusts(party) and following(tobu, actor) and not nemeFree(party) and not nemeSits(party) and not nemeLeft(party).
    Time 3.
    On success { Assert nemeSits(party). Assert tobuChair(party). Assert watcher(tobu). Retract following(tobu, actor). Assert at(tobu, long_hall). Assert sitting(tobu). Retract doorIn(kezu_bed). Retract sleepwalking(kezu). Assert at(neme, the_sill). Assert at(party, the_sill). }
    Result "Tobu hears out the whole of it with his hands in his coat, and says, 'Eleven coat-hooks. I counted them a hundred times.' He goes up the Slope without looking back, and in a little while the knocking stops, and the front door swings out on a morning it has never seen, and Neme goes down the stone steps with her hand in yours. Somewhere up in the Long Hall, in a chair the right size for someone small, a young man from Cobble Ring has begun to count doors.".
  }
  // 3. Shut the gate on her and go: the house stays as it was, and goes on.
  Action leave_the_gate(actor: group, site: place) "Shut the gate again, and leave Neme to her knocking" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, front_hall) and at(neme, front_hall) and not nemeFree(party) and not nemeSits(party) and not nemeLeft(party).
    Time 1.
    On success { Assert nemeLeft(party). Assert state(gate_leaf, barred). Assert at(party, slope). }
    Result "You tell her you will come back. She says, quite kindly, 'They all say that,' and turns round to face her door. The gate closes behind you on its own, and the brass bar drops, and after a little while, from behind it, the knocking begins again: eleven, and the wait.".
  }

  // ---- The letter, and the vote ----
  Entity letter_read: fact "the brother's letter".
  Action give_letter_reeve(actor: group, site: place) "Give the reeve the Lifted brother's letter, with Sabe's reading of it" {
    Description "The reeve has not heard from her brother since the famine year. The letter is not about the sale; it changes how the sale feels.".
    Requires able(actor) and company(actor) and at(actor, site) and at(tessa, site) and holding(actor, hhg_undal_letter)
      and not voted(tessa) and not persuaded(tessa, letter_read) and sellVotes(tessa) >= 2.
    On success { Spend hhg_undal_letter from actor. Assert persuaded(tessa, letter_read). Decrease sellVotes(tessa) by 2. }
    Result "The reeve reads it standing, with her lips moving on the Undal, which she taught herself from a child's primer in the year he went. She reads it twice. Then she goes to the window, and stands there with her back to you for a time. 'He says it's a thing to be answered,' she says at last. 'Not a thing to be sold.' She does not turn round. 'Four arcs for selling. I'll have to speak to the other five.'".
  }

  // ---- The Knot House: a fight is possible and costly; there are two ways round ----
  Person riggers "the Knot House riggers" at nowhere {
    Role "three Netters in harness, with belaying-pins, sent down to find who cut the knot". Ancestry human. Calling warrior. Level 2. Numbers 3. Pronouns they.
    Temperament proud.
    Warns "Three Netters in harness come along the net toward the hatch with belaying-pins in their hands, and the one in front says, quite loudly, 'Floor-dirt. Cut a knot from the wrong side. That's a hand, in the Knot House, or a fee, or the ledge.' Another adds, 'Isele wants a word. She says it would be a short one.'".
    Pleads "The riggers drop their pins on the net and put their hands up, one of them holding on to a stay with his teeth.".
  }
  Initially Set tribute(riggers) to 4.
  Rule riggers_come when knotBroken(rigging_foot) and at(party, rigging_foot) and at(riggers, nowhere) and not riggersSettled(party) { Retract at(riggers, nowhere). Assert at(riggers, rigging_foot). }
  Relation riggersSettled(group).
  Action show_token(actor: group, site: place) "Show the riggers Sabe Orrel's knot, and say that Sabe sent you" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, rigging_foot) and at(riggers, rigging_foot) and holding(actor, hhg_netters_token) and not riggersSettled(party).
    Time 1 minutes.
    On success { Assert riggersSettled(party). Assert tolerates(riggers, actor). Assert at(riggers, nowhere). }
    Result "The one in front takes the tarred loop, turns it in the light, and swears, at length and without repeating herself. 'That's Sabe's,' she says. 'That's Sabe's own keeper's.' She gives it back as if it were hot. 'Isele will have a word anyway. It will be a different one.' They go back along the net with their pins hanging, and one of them looks over his shoulder at you the whole way.".
  }
  Action pay_knot_fee(actor: group, site: place) "Pay the riggers four coin for the knot, to the Knot House's purse" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, rigging_foot) and at(riggers, rigging_foot) and quantity(actor, gold) >= 4 and not riggersSettled(party).
    Time 1 minutes.
    On success { Decrease quantity(actor, gold) by 4. Increase quantity(riggers, gold) by 4. Assert riggersSettled(party). Assert tolerates(riggers, actor). Assert at(riggers, nowhere). }
    Result "The tall rigger counts the coin twice, bites one, and hands it to the youngest, who puts it in a purse with a knot on it. 'Fee paid,' she says. 'That's the knot. The cutting's another matter, but Isele doesn't take cuttings from a fee-payer on a Monday.' They go back along the net, not hurrying.".
  }

  Observe neme_forced at front_hall as feature when gateForced(party) and at(neme, front_hall) and not nemeTrusts(party) "Neme stands very straight with her hand lifted for a knock, and does not look at you. 'You did not wait,' she says. 'Everyone is always so quick.'".
  Milestone m_keeper "found the keeper of the Slope and heard the knocking counted" worth 100 when knows(party, eleven_strokes).
  Milestone m_brother "carried a Lifted brother's letter to the reeve of Cobble Ring" worth 150 when persuaded(tessa, letter_read).
  Milestone m_gate "opened the gate at the foot of the Slope" worth 150 when state(gate_leaf, open).
  Milestone m_marble "gave Neme back her marble" worth 100 when marbleBack(party).
  Milestone m_out "walked Neme out by the front door" worth 400 when nemeFree(party).
  Milestone m_chair "let Tobu take the chair so that Neme might go" worth 300 when nemeSits(party).
  Milestone m_riggers "settled the Knot House's riggers without a blow" worth 100 when riggersSettled(party).

  // ---- The four acts, told as chapters ----
  Chapter ch_ring "I. Cobble Ring" when at(party, ?p) and within(party, ring) and not knows(party, door_opened) "Cobble Ring keeps itself awake. Every house on the rim has a loft with a shutter, and in every loft someone is sitting up with something: a sick cow, a sleeping sister, a hole in the barley. The lamp-oil is the biggest line on the reeve's slates.".
  Chapter ch_barley "II. The House in the Barley" when at(party, ?p) and houseRoom(?p) and not keelSide(?p) "What is watched stays as it is; what is not, grows. The house is a bedroom the size of a barn, and the town sits round it on stools, trying not to yawn.".
  Chapter ch_keel "III. The Keel" when at(party, ?p) and keelSide(?p) "Up here the house hangs from the underside of the city, and the Long Hall is a little longer every time you look down it.".
  Chapter ch_slope "IV. The Slope" when at(party, slope) or at(party, front_hall) "At the foot of the Long Hall the floor tilts, the knocking is loud, and an old woman minds a lamp for someone who is not coming. There is one door left, and every other door in the house leads away from it.".

  // ---- Two further links outward, and a comic scene in a grave house ----
  Topic dace_exchange with dace "Ask Dace where the Company sends what falls out of the city" when true once {
    Says "'The Founders' Exchange sells it on at Corran,' says Dace, 'and the Lesser Instruments there buy anything that still ticks, and a few things that only used to.' He rolls his cord. 'Mister Lisle sells dreg to lens-grinders at Low Water by the pound. He says it takes the edge off a lens.'".
  }
  Relation heardBeams(group).
  Topic wenu_beams with wenu "Ask Wenu about the chalk numbers on the roof beams" when true once {
    Says "'Eleven hundred and nine, and every one counted forty times,' says Wenu. 'Apprentices do it to stay awake. We keep a book on who finishes first. It is called the Beams Book and I have never lost a penny by it.' She lowers her voice. 'There is a beam in the middle, number six hundred and six, that has never been counted by the same person twice. Everyone gets a different number.'".
    On discuss { Assert heardBeams(party). }
  }

  // ---- The endings ----
  Ending the_front_door "The Front Door" when nemeFree(party) "Nobody in Cobble Ring was watching the sky, and so nobody saw a girl in a torn coat come down the last long stair of the Keel into Haddo's barley on the morning after the third night. The house in the field is glass now and nothing more; the doors are only doors, and they open where they are looked at. Kezu sleeps through the night and wakes at dawn like anyone, and the first thing she does is climb to the loft, and sit in the seat that has been Hanu's, and look at the room in the barley, and at the girl on the stool beside it with a dreg marble in her fist, and not look away. In the Keel, a lamp has gone out on the Slope, and an old woman has gone up the stair to see whether Wenn is in his bunk.".
  Ending the_chair "The Chair" when nemeSits(party) "Tobu sits in the child's chair in the middle of the Long Hall and counts forty doors, and the house does not grow. Neme goes down the stair into the Strewnfield with her coat buttoned wrong, and is looked after by Hanu, who has been a week without a patient and is glad of one. Kezu sleeps, and wakes, and goes to the hall every noon with a cup of something hot, and sits on the glass beside her sister's boy for an hour, not speaking, and goes home again. The widows on the rim have knitted Neme a cap, too big, which she wears over her eyes.".
  Ending the_gate_shut "The Knocking Goes On" when nemeLeft(party) "You went back up the Slope, as you had said you would, to see to your own affairs, and the gate shut behind you. The house goes on as it did. Kezu is walked back to her bed by Hanu every morning; the council meets; the barley is not sown. At the foot of the Slope an old woman minds a lamp for a boy called Wenn, and the knocking comes up the glass, and stops, and comes again. Some night it will be answered, by whoever happens to come by.".
}

data/adventures/let-one-remember/act2_ma:
Module corrow "The Road the Star Came Down" {
  Description "Act II, the Grey Country: the Margin, entered by being forgotten and left by being remembered.".

  // ── What the Unsaid is ───────────────────────────────────────────────────────────────────────────────────────────
  // In 412 the Lettings read the star's name in the Root's memories and let it go, by order of both councils, and the
  // star stayed. Ever since, the name has been gathering forgotten things round itself in the Margin. The body woke in
  // 2641 and went after the jewel. The name wants to go after its body.
  Discovery unsaid_is_name "In 412 the Lettings, by order of both councils, read a name in the Root and let it go. What they let go has been in the Margin ever since, gathering forgotten things round itself.".
  Thing warden_chest "a deadiron-bound chest in the old warden's office" at gaol_ring is scenery {
    State shut "In the wreck of the Concord warden's office, under fallen rock, a chest bound in black iron that no fire touched.".
  }
  Discovery warden_ledger "The Concord Warden's account book for 412, kept from thinning in deadiron: 'To the Letting school, for the Long Rite against the star's name, by order of both councils: forty weights of silver, paid. Fog. No market. To searchers for Keld Hollow, sixty men, nine days. Nothing found. They say the road there is longer than it was. The Keeper does not know her daughter. Fog.'" {
    Source warden_book "the Concord Warden's account book of 412" at gaol_ring readable by party.
  }
  Observe name_and_body near party when knows(party, warden_ledger) and knows(party, root_gift) and not knows(party, unsaid_is_name) "The Warden's account and the bear's night in the Root fit together like the two halves of a broken plate. Forty weights of silver, paid, to let go of a name. The ledger does not say whose." teaches unsaid_is_name.
  Topic ferran_told with ferran "Tell Ferran Cosk what is waiting in the grey" when knows(actor, unsaid_is_name) and not turned(ferran) and not unsaidCrossed(margin) {
    Says "Ferran Cosk listens to the end with his hands folded, and then he takes the Open Hand's book of syllables off its shelf, the one they have been filling for a year, and looks at it. 'My great-grandfather's rite,' he says. 'The star's name. We were going to say it at the Seam, out of mercy.' He closes the book. He does not burn it; he gives it to you. 'Whatever you need forgotten,' he says, 'the Open Hand will forget it. That is the only thing we are good for.'".
    On discuss { Assert turned(ferran). }
  }

  // ── The Open Hand's rite ─────────────────────────────────────────────────────────────────────────────────────────
  // On the fortieth day the Open Hand go down to the Seam and say what they have. The name needs seven syllables:
  // two have come through the Seam on Strays over the years; Webb carries one, two with the Short Grey record; the
  // three Strays of Keld carry three, if the Open Hand took them; and a company that said its syllables in the chamber
  // gave one more.
  Measure gathered(place). Relation tallied(place). Relation unsaidCrossed(place).
  Rule tally_base when watch(clock) >= 5600 and not tallied(margin) { Assert tallied(margin). Set gathered(margin) to 2. Assert tallyWebb(margin). }
  Relation tallyWebb(place). Relation tallyStrays(place). Relation tallyStirred(place).
  Rule tally_webb when tallyWebb(margin) and not webbNamed(webb) and able(webb) { Retract tallyWebb(margin). Increase gathered(margin) by syllables(webb). Assert tallyStrays(margin). }
  Rule tally_no_webb when tallyWebb(margin) and (webbNamed(webb) or not able(webb)) { Retract tallyWebb(margin). Assert tallyStrays(margin). }
  Rule tally_strays when tallyStrays(margin) and strayTaken(keld) and not namedStrays(keld) { Retract tallyStrays(margin). Increase gathered(margin) by 3. Assert tallyStirred(margin). }
  Rule tally_no_strays when tallyStrays(margin) and (not strayTaken(keld) or namedStrays(keld)) { Retract tallyStrays(margin). Assert tallyStirred(margin). }
  Rule tally_stirred when tallyStirred(margin) and unsaidStirred(corrow) { Retract tallyStirred(margin). Increase gathered(margin) by 1. }
  Rule tally_unstirred when tallyStirred(margin) and not unsaidStirred(corrow) { Retract tallyStirred(margin). }
  Rule open_hand_rite when watch(clock) >= 5616 and gathered(margin) >= 7 and not turned(ferran) and not unsaidCrossed(margin)
    and not unsaidHoused(margin) and not unsaidSent(margin) and not unsaidSlain(margin)
    says "On the fortieth day the Open Hand go down the Peleth stair in grey, thirty of them, with Ferran Cosk at their head carrying a book. Three days later the Registry enters a line in a tone it has never used: 'Arrival, unlicensed, from below.' What came up the stair that night wore a hundred lost coats and a hundred lost hats and walked like nobody at all, and went north-north-east across the plateau without stopping, toward the road the star went up." {
    Assert unsaidCrossed(margin). Assert at(unsaid, limbo).
  }
  Rule open_hand_short when watch(clock) >= 5616 and gathered(margin) < 7 and not turned(ferran) and not unsaidCrossed(margin) and not riteFailed(margin)
    and not unsaidHoused(margin) and not unsaidSent(margin) and not unsaidSlain(margin)
    says "On the fortieth day the Open Hand go down to the Seam and say what they have, all of it, in the dark, for a night and a day. The lake steams. The grey shore comes so close you could step onto it. Nothing crosses. Ferran Cosk comes up the stair with his book and sits on the rim until the lamps are lit." {
    Assert riteFailed(margin).
  }
  Relation riteFailed(place).

  // ── Going across ─────────────────────────────────────────────────────────────────────────────────────────────────
  // The prioress's sisters forget the company at the Seam; the anchors above say its names without stopping. Each
  // ordinary anchor holds two days. A Keld never tires: a Keld cannot forget.
  Place margin "the Margin" is plane.
  Place grey_country "the grey country" is region within margin.
  Place grey_near "the grey shore" is wilderness within grey_country at 0, 1.
  Place hollow "Keld Hollow" is settlement within grey_country at 1, 0.
  Place grey_far "the grey further in" is wilderness within grey_country at 2, 1.

  Place grey_shore "the grey shore" is room within grey_near at 0, 0 outdoors.
  Place drifts "the drifts" is room within grey_near at 1, 0 outdoors.
  Place hollow_lanes "the lanes of Keld Hollow" is room within hollow at 0, 0 outdoors.
  Place reeve_house "the reeve's house" is room within hollow at 1, 0.
  Place far_field "the far field" is room within hollow at 0, 1 outdoors.
  Place grey_library "the untitled library" is room within grey_far at 0, 0.
  Place mountain_place "the mountain's place" is room within grey_far at 1, 0 outdoors.
  Place short_grey_fog "the fog of 2604" is room within grey_far at 0, 1 outdoors.
  Place unsaid_court "the gathering" is room within grey_far at 2, 0 outdoors.

  Relation riteArranged(group). Measure anchorDays(place). Measure nextAnchor(place). Relation inMargin(place).
  Relation crossing(group). Relation stranded(group).
  Initially Assert inMargin(grey_shore). Initially Assert inMargin(drifts). Initially Assert inMargin(hollow_lanes).
  Initially Assert inMargin(reeve_house). Initially Assert inMargin(far_field). Initially Assert inMargin(grey_library).
  Initially Assert inMargin(mountain_place). Initially Assert inMargin(short_grey_fog). Initially Assert inMargin(unsaid_court).

  Passage seam_lake "the lake at the Seam" is passage between seam and grey_shore taking 1 hour
    opening when riteArranged(rook) and anchorDays(margin) > 0 "The lake is only cold water to the ankle, and the far wall is only a wall.".
  Passage shore_drifts "the drifts along the shore" is path between grey_shore and drifts taking 30 minutes.
  Passage drifts_hollow "a lane nobody remembers" is path between drifts and hollow_lanes taking 1 hour.
  Passage reeve_door "the reeve's door" is door between hollow_lanes and reeve_house.
  Passage far_field_gate "the gate to the far field" is gate between hollow_lanes and far_field.
  Passage hollow_far "the grey road" is path between hollow_lanes and grey_library taking 2 hours.
  Passage library_place "a fence round nothing" is path between grey_library and mountain_place taking 1 hour.
  Passage library_fog "into the fog" is path between grey_library and short_grey_fog taking 1 hour.
  Passage place_court "toward what is gathering" is path between mountain_place and unsaid_court taking 1 hour.

  Topic rook_anchor with rook "Ask Prioress Rook to anchor the company across the lake at the Seam" when knows(actor, seam_found) and not riteArranged(rook) {
    Says "The prioress turns her ring once round her finger. 'Thirty years nobody has asked,' she says. 'My sisters will go down with you to the chamber and forget you there: that is how you cross. Then they will come up, and we will say your names here, all of us, in turns, day and night, until you walk back out of the lake.' She takes your hands one by one and looks at each face in turn, slowly, learning it. 'We are only nurses. We can hold you two days. If you want longer, ask the people who owe you, or who love you. Ask a Keld if you can find one who will; a Keld cannot forget, and will hold you as long as you need.'".
    On discuss { Assert riteArranged(rook). Set anchorDays(margin) to 2. }
  }
  Relation anchoring(group).
  Topic pennick_anchor with pennick "Ask Judge Pennick to stand anchor for the company" when riteArranged(rook) and deedsBack(pennick) and not anchoring(pennick) {
    Says "'The law is a way of remembering on purpose,' says the judge. 'I said that to you once. I'll sit in the hospice and say your names in court hours and out of them.' She writes them down first, so she will have them right.".
    On discuss { Assert anchoring(pennick). Increase anchorDays(margin) by 2. }
  }
  Topic prew_anchor with nameless "Ask Absalom Prew to stand anchor for the company" when riteArranged(rook) and prewBack(nameless) and not anchoring(nameless) {
    Says "'Seven months nobody could say my name,' says Absalom Prew. 'I'll say yours till my voice goes.' His wife, beside him, says she will say them when it does.".
    On discuss { Assert anchoring(nameless). Increase anchorDays(margin) by 2. }
  }
  Topic bram_anchor with bram "Ask Bram Coyle to stand anchor for the company" when riteArranged(rook) and lensHome(bram) and not anchoring(bram) {
    Says "Bram puts the lens in his drawer with the ring and the bill of sale. 'Things come back to this house,' he says. 'So will you.'".
    On discuss { Assert anchoring(bram). Increase anchorDays(margin) by 2. }
  }
  Topic saska_anchor with saska "Ask Mother Saska to stand anchor for the company" when riteArranged(rook) and not anchoring(saska) {
    Says "Mother Saska lays her hands flat on the chair-arms. 'My grandmother was over there,' she says. 'The anchors who brought her back were Marra Coyle and her daughter, and they said her name for nine days.' She settles in her chair. 'I will not forget you. I cannot. Go and come back.'".
    On discuss { Assert anchoring(saska). Increase anchorDays(margin) by 100. }
  }
  Relation lensHome(group).
  Event lens_home near bram when keeps(bram, wenna_lens) "Bram unwraps the lens and holds it to the window, and the window stands in it whole. He puts it back in the drawer with Wenna's mother's ring." then {
    Assert lensHome(bram).
  }
  Initially Assert wants(bram, wenna_lens_kind).

  // The days in the grey, counted by the anchors' voices.
  Rule into_the_grey when at(party, ?p) and inMargin(?p) and not crossing(party) { Assert crossing(party). Set nextAnchor(margin) to watch(clock) + 144. }
  Rule out_of_the_grey when crossing(party) and at(party, ?p) and not inMargin(?p) { Retract crossing(party). }
  Rule anchors_tire when crossing(party) and watch(clock) >= nextAnchor(margin) and anchorDays(margin) > 0 {
    Decrease anchorDays(margin) by 1. Set nextAnchor(margin) to nextAnchor(margin) + 144.
  }
  Rule anchors_fall_silent when crossing(party) and anchorDays(margin) == 0 and not stranded(party)
    says "Somewhere very far off, a voice that has been saying your name for days says it once more, hoarsely, and stops. Nobody takes it up. The grey is very quiet, and you find you cannot remember what the shore looked like, or which way it was." {
    Assert stranded(party).
  }
  Observe anchors_heard at grey_shore when crossing(party) and anchorDays(margin) > 0 "Very faint, from nowhere, voices are saying your names, one after another, over and over, the way a grave-caller reads a row.".
  Observe end_stranded near party when stranded(party) and not knows(party, ending_told) "Nobody is saying your names. You are in the grey with the gloves and the lost buckets and the field-names nobody beats any more, and in the Corrow they are trying to remember who it was the hospice was anchoring that winter, and failing." teaches ending_told.

  // ── The grey country ─────────────────────────────────────────────────────────────────────────────────────────────
  Observe grey_shore_scene at grey_shore when true "A shore of grey grass under a sky the colour of nothing, with no sun and no horizon. Behind you is a lake, and in it, faint as breath on glass, the dome of the Seam. Things stand on the shore with their backs to the water: a sheep, a cart-wheel, a man in a Peleth coat, all quite still, all facing inland.".
  Observe drifts_scene at drifts when true "The drifts. Lost things lie against fences that are forgotten boundaries, banked like snow on the windward side: gloves by the thousand, buttons, keys, a Peleth ledger swollen to twice its size, a child's shoe, a whole hayrick, a dog collar, a well-bucket. Everything anyone in the Corrow ever put down and forgot is here, and most of it is single.".
  Observe hollow_scene at hollow_lanes when true "Keld Hollow: thirty houses in a lane, whole and swept, with smoke going up straight from every chimney into the no-sky. Nobody is in the lanes. The houses remember being lived in; their people went home in 2606.".
  Observe reeve_empty at reeve_house when webbNamed(webb) "The reeve's house. The hearth is cold for the first time in two hundred years: the one this house was keeping warm has gone home to Keld, and it knows. A bed, a chair, a coat-peg with nothing on it. It is waiting for somebody.".
  Observe reeve_kept at reeve_house when not webbNamed(webb) "The reeve's house. A fire on the hearth, low. A young man's coat on the peg by the door, still warm, and on the table a bowl of porridge with the spoon standing upright in it.".
  Observe far_field_scene at far_field when true "The far field: a stone wall round a square of grey grass, and in the middle a hay-fork standing upright in the ground where somebody stuck it and walked away.".
  Observe library_scene at grey_library when true "A library with no titles: shelves going away in every direction, and on them books, scrolls, keepstone plates, tally-chains, all without a name, all Calvessan. Half of a people's history, let go on one night in 1 BB to save the world. Some of the books are open, as if someone had been reading.".
  Observe place_scene at mountain_place when true "Here is a hole. Not in the ground: in the grey itself, a hole-shaped absence a kilometre and more across, ribbed down its sides, three hundred metres deep, with nothing at the bottom and nothing in it at all. It is exactly the shape of the Socket. It is where the mountain belongs. It is waiting.".
  Observe fog_scene at short_grey_fog when true "Fog, standing still. In it, the Wend valley of 2604 as the Short Grey left it: a stretch of road, a hedge, a pear-tree, and a woman's footprints going in and not coming out.".
  Observe gathering_scene at unsaid_court when not unsaidCrossed(margin) and not unsaidSent(margin) and not unsaidSlain(margin) "Things are gathering here, drawn in from the whole grey country the way water is drawn to a drain: coats, hats, a cart, a carved door, names off gravestones written on nothing, a Peleth ledger, a great deal of fog. In the middle of it all something stands up out of it, tall, and wears it.".
  Observe gathering_empty at unsaid_court when unsaidCrossed(margin) or unsaidSent(margin) or unsaidSlain(margin) "Nothing is gathering here now. The things lie where they fell.".

  // The blue bucket, which Sabeth Coyle lost on an elver morning in 2601.
  Kind blue_bucket "a blue bucket, a good one, with an old chalk tally on its side" is treasure worth 0 weighing 2.
  Item bucket "a blue bucket" is blue_bucket at drifts.
  Event bucket_home near bram when keeps(bram, bucket) "Bram turns the bucket round in his hands and reads the chalk on its side, which has not rubbed off in a hundred and thirty years: a row of tally strokes, in his great-great-grandmother's hand. 'Gran said there was a blue bucket,' he says. 'Her gran's. It went in the fog one elver morning.' He sets it on the bench by the lens-grinder's lap, and it looks as if it had always been there." then {
    Assert bucketHome(bram).
  }
  Relation bucketHome(group).
  Initially Assert wants(bram, blue_bucket).

  // The untitled library: the old rite of 300 BB, and what the Unsaid is.
  Discovery way_home_rite "The Forgetting of the Way Home, laid in an untitled Calvessan plate in the grey library: in 300 BB, when an Ondrek war-band held the Wendhead, three hundred of the Calvessa sat in a ring across the raiders' road and forgot, together and on purpose, the road home. The raiders wandered the plateau until they died. It needs three hundred who can forget, sitting across the road the enemy must take, and it takes something from them in payment. The plate does not say what. The rite is laid so that whoever performs it will not remember doing so." {
    Source rite_plate "an untitled plate of laid stone, open on a reading-stand" at grey_library readable by party.
  }
  Discovery library_name "In the untitled library, an open book in Concord hand of 412: the Lettings' own record of the Long Rite. They read the star's name in the Root, it says, and let it go; and on the last page, in another hand: 'The star did not go. We have let go of the wrong thing.'" {
    Source rite_record "an open book in Concord hand" at grey_library readable by party.
  }
  Observe library_inference near party when knows(party, library_name) and not knows(party, unsaid_is_name) "'We have let go of the wrong thing.' Something in the grey has been gathering itself round it ever since." teaches unsaid_is_name.

  // The mountain's place: a stone of the absence is Hightown's place in a pocket.
  Kind place_stone "a stone of the mountain's place, which weighs nothing at all" is treasure worth 0 weighing 0.
  Item absence "a stone of the mountain's place" is place_stone at mountain_place.
  Observe absence_seen at mountain_place when at(absence, mountain_place) "On the lip of the hole a stone lies loose, grey, ribbed like the rest. When you lift it, it weighs nothing at all, and your hand knows the shape of the Socket.".

  // Iniry Calde, forgotten in the Short Grey of 2604.
  Person iniry "Iniry Calde" at short_grey_fog {
    Role "a Calvessan mnemonist of 590 AB, forgotten in the Short Grey". Ancestry human. Calling mage. Level 9. Peaceable.
    State forgotten "A woman in a Calvessan robe sits on a milestone in the fog with her hands in her lap. She is young-looking and very old at once, and furious, and patient.".
    State returned "Iniry Calde is in the Corrow again, and does not like the weather.".
  }
  Topic iniry_who with iniry "Ask the woman on the milestone who she is" when state(iniry, forgotten) once {
    Says "'Iniry Calde,' she says, as to a clerk who has spelt it wrong before. 'Of the charge of the old forgettings. The Quiet Gaol had me from 590 for trying to forget the Chain. A party of heroes let me out in 2601, and three years later I let a fool of a Letting brother talk me into his great-grandfather's rite, and it took us both.' She considers the fog as though it owed her rent. 'A hundred and twenty-seven years, and nobody up there has said my name. You cannot anchor what nobody remembers. Find it written, say it at the shore, and I will come. I know the old rites better than anyone living or forgotten, and I am in a temper.'".
  }
  Topic iniry_rite with iniry "Ask Iniry Calde about the Forgetting of the Way Home" when state(iniry, forgotten) once {
    Says "'Three hundred,' she says at once. 'Who can forget: no Keld, then. Sitting in a ring across the road the enemy must take, before it takes it. You will lose something. You choose what; the rite takes it whether you choose or not, so choose.' She almost smiles. 'It is the only rite that ever won a war in this country. They taught it to children once, without its words, as a skipping game.'".
    On discuss { Assert knows(actor, way_home_rite). }
  }
  Discovery iniry_named "In the Letting record of the Short Grey, among the lost: 'Iniry, of the old charge, Calde; went into the fog on the fortieth day with Brother Cosk, saying she would bring him back. Neither came.'".
  Observe iniry_in_record near party when carries(party, short_grey) and knows(party, short_grey_syllable) and not knows(party, iniry_named) "Further on in the record, among the lost: 'Iniry, of the old charge, Calde; went into the fog on the fortieth day with Brother Cosk, saying she would bring him back. Neither came.'" teaches iniry_named.
  Action call_iniry(actor: group, site: place) "Say Iniry Calde's name aloud on the shore, as the record wrote it, and mean it" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, grey_shore) and knows(actor, iniry_named) and state(iniry, forgotten).
    Time 1.
    On success { Assert state(iniry, returned). Assert at(iniry, hospice_hall). }
    Result "You say it to the grey: Iniry, of the old charge, Calde. For a while nothing. Then she is beside you on the shore with fog on her robe, and she walks past you into the lake without a word, and the lake lets her. When you come up she is in the hospice hall, drinking the prioress's tea and telling her everything she is doing wrong.".
  }

  // ── The Unsaid ───────────────────────────────────────────────────────────────────────────────────────────────────
  Person unsaid "the Unsaid" at unsaid_court {
    Role "a name without its thing, wearing forgotten things". Peaceable.
  }
  Relation unsaidHoused(place). Relation unsaidSent(place). Relation unsaidSlain(place).
  Discovery road_fragments "Three fragments of a road, given up by the Unsaid: the keeper Wenna Coyle's lapses as she fled with the Hush in 2641, moments she let fall into the grey as she went: a night sky with a burnt line up it, north-north-east and up; a wall of cloud with a door in it; a long road of fused air with a star at the end of it, burning.".
  Topic unsaid_wants with unsaid "Ask the Unsaid what it wants" when not unsaidCrossed(margin) and not unsaidSent(margin) and not unsaidSlain(margin) and not unsaidHoused(margin) {
    Says "It does not speak. Things speak for it: a lost hat says 'I', a Peleth ledger says 'was', a gravestone name nobody reads says 'mine'. Slowly, out of a hundred dropped words, you hear it: I WAS SAID ONCE AND THEN NOT. I AM THE SAYING WITHOUT THE THING. I HAVE THREE PIECES OF A ROAD THAT A KEEPER DROPPED. TELL ME THE REST. OR SAY ME, AT THE SEAM, AND I WILL FIND IT MYSELF.".
  }
  Action house_unsaid(actor: group, site: place) "Ask Teshen to give the Unsaid a name and a place: the reeve's empty house in Keld Hollow" {
    Description "A Stray named aloud by someone who means it, and given a place, stops taking. The reeve's house is empty now that Corin is home.".
    Requires able(actor) and company(actor) and at(actor, site) and at(unsaid, site) and travelsWith(teshen, actor)
      and knows(actor, unsaid_is_name) and webbNamed(webb) and not nicheClosed(keld) and not unsaidHoused(margin) and not unsaidSent(margin) and not unsaidSlain(margin) and not unsaidCrossed(margin).
    Time 2.
    On success { Assert unsaidHoused(margin). Assert at(unsaid, reeve_house). Assert knows(actor, road_fragments). }
    Result "Teshen walks into the gathering until the things it wears brush her face, and stands there. 'You're the name of the star,' she says, 'that was said and then not. That's who you are. It's not nothing; it's a name.' The coats and the hats go still. 'And your place is the reeve's house in the Hollow, where Corin lived, because Corin's gone home and the house is waiting for somebody, and the somebody is you.' For a long time nothing moves. Then the Unsaid walks past her, very slowly, out of the gathering and down the grey road, shedding gloves, toward Keld Hollow. When it is gone there are three things lying where it stood: three pieces of a road.".
  }
  Action send_unsaid(actor: group, site: place) "Tell the Unsaid where its body went" {
    Description "North-north-east, and up: the road the star came down. Telling is acting.".
    Requires able(actor) and company(actor) and at(actor, site) and at(unsaid, site)
      and (knows(actor, wenna_band) or knows(actor, horn_bearing) or knows(actor, nail_negative))
      and not unsaidHoused(margin) and not unsaidSent(margin) and not unsaidSlain(margin) and not unsaidCrossed(margin).
    Time 1.
    On success { Assert unsaidSent(margin). Assert at(unsaid, limbo). Assert knows(actor, road_fragments). }
    Result "You tell it: north-north-east and up, the road the star came down, the way the horn points. The things it wears turn, all together, like a field of barley in wind, toward a direction that is not a direction in the grey. Then they fall. Coats, hats, ledgers, fog: all of it drops in a heap where it stood, and in the heap lie three pieces of a road, and the Unsaid is gone, up and out, after its body.".
  }
  Action unmake_unsaid(actor: group, site: place) "Tear the forgotten things off the Unsaid until there is nothing left to wear them" {
    Description "Everything it wears was taken from somebody.".
    Requires able(actor) and company(actor) and at(actor, site) and at(unsaid, site)
      and not unsaidHoused(margin) and not unsaidSent(margin) and not unsaidSlain(margin) and not unsaidCrossed(margin).
    Time 6.
    On success { Assert unsaidSlain(margin). Assert at(unsaid, limbo). Assert knows(actor, road_fragments). }
    Result "You pull. Coats come away, and hats, and names, and the fog it wears like wool tears and drifts off, and under each thing there is another, and you pull for an hour while it says nothing at all. At the end there is a heap of the forgotten, and nothing standing in it, and three pieces of a road at the bottom. Then the heap is not there. Everything it took has gone home at once: across the whole grey country things are lifting and going, and through the grey sky above the mountain's place something enormous and invisible is falling, back, toward where it belongs.".
  }
  // Everything the Unsaid took goes home at once: the mountain's place among them.
  Rule place_returns when unsaidSlain(margin) and not placeReturned(margin) and not crashed(hightown) and not lost(hightown) and not grounded(hightown)
    says "In the Corrow, at the same hour, every Counterweight on Hightown stops what they are doing and looks north, at the lake, and knows it, all at once, as if they had always known." {
    Assert placeReturned(margin). Increase heard(hightown) by 600.
  }
  Relation placeReturned(place).

  // Teshen, at last, can be a stranger.
  Action teshen_stays(actor: group, site: place) "Let Teshen stay in the grey, where nobody can see her" {
    Description "Over here she is the first Keld in a hundred and twenty years that nobody remembers.".
    Requires able(actor) and company(actor) and at(actor, site) and travelsWith(teshen, actor) and at(actor, ?p) and inMargin(?p).
    Time 1.
    On success { Retract travelsWith(teshen, actor). Assert at(teshen, hollow_lanes). Assert strangerAtLast(teshen). }
    Result "Teshen stands in the grey and looks at her own hands as if they were someone else's. 'Nobody's looking at me,' she says. 'Nobody here is going to remember my face.' She laughs, and then she is crying, and then she laughs again. 'Go on. I'll be in the Hollow. If you ever need a stranger, come and not-find me.' She walks off up the lane, and for the first time since you met her, you find you cannot quite remember what she looks like.".
  }
  Relation strangerAtLast(group).
}

data/adventures/let-one-remember/act3_ki:
Module corrow "The Road the Star Came Down" {
  Description "Act III, the Kin Fall: the new star breaks over the Teskarn, and the Unfolded come down the bearing toward the horn and the Well.".

  // ── The star breaks ──────────────────────────────────────────────────────────────────────────────────────────────
  // The slow star in the north-east, brightening since 2593, is the Varakiiri's kin. On the forty-second day it breaks
  // over the Teskarn. What comes out of it unfolds, as the cave bear saw in the Root: bodies of deadiron, as tall as a
  // house, that no spell touches. They walk the bearing of anything that knew the Hush: the horn, then the Well, then
  // the Seam and the band Wenna laid there, which is the only record of where she went.
  Place teskarn "the Teskarn" is wilderness within corrow at 6, 0.
  Place shielings "the high shielings" is room within teskarn at 0, 1 outdoors.
  Place star_crater "where the star came down" is room within teskarn at 1, 0 outdoors.
  Passage shieling_track "the shieling track" is track between socket_north and shielings taking 2 hours.
  Passage crater_climb "the burnt corrie" is path between shielings and star_crater taking 2 hours.
  Observe shielings_scene at shielings when not starFell(corrow) "Summer shielings on the Teskarn's lower slopes, stone huts roofed with turf, empty for the winter. Snow in the corries above. In the north-east, low over the massif, the slow star that came in 2593 is brighter than any star should be, and has been brighter every night this month.".
  Observe shielings_after at shielings when starFell(corrow) "The shielings are empty and their doors stand open. The snow above is black for a kilometre, and the corrie smokes.".
  Observe crater_scene at star_crater when starFell(corrow) "A corrie of the Teskarn blown open to the rock and glazed black. In the middle of it lies what is left of the star: a husk of dark iron the size of a church, split along seams like a seed-case, and empty. Round it the snow has melted into a ring of steaming mud printed with feet three times the length of a man's, going south, all of them, in step.".
  Observe crater_before at star_crater when not starFell(corrow) "A high corrie under the summit of the Teskarn, snow-filled and silent. Directly above it, in the north-east, the slow star stands.".

  Relation starFell(place). Measure kinStage(place). Measure kinNext(place). Relation kinLost(place). Relation bandRead(place).
  Relation hornwakeFled(place). Relation stakeFled(place).
  Species unfolded_kind "an Unfolded" like iron_golem temperament savage described "Something that unfolded out of a falling star: a body of black iron as tall as a house, jointed wrongly, with a head like a closed hand. No spell touches it.".
  Person kin "the Unfolded" at limbo {
    Role "the Varakiiri's kin, come down out of the new star". Species unfolded_kind. Level 10. Numbers 4.
  }
  Rule star_breaks when watch(clock) >= 5904 and not starFell(corrow)
    says "In the small hours of the forty-second night the slow star in the north-east breaks. It does not fall like a star: it opens, like a seed-case, and the pieces come down over the Teskarn in long slow lines of fire, and the snow on the massif goes up in steam. Every dog in the Corrow howls at once. The horn, at Hornwake, swings round in its furrow by a hand's breadth, toward the Teskarn, and back." {
    Assert starFell(corrow). Set kinStage(corrow) to 0. Set kinNext(corrow) to watch(clock) + 144. Assert at(kin, star_crater).
  }
  Objective kin_coming when starFell(corrow) and not kinLost(corrow) and not bandRead(corrow) "The Unfolded are coming down from the Teskarn along the bearing of the horn, toward Hornwake, the Well and the Seam. No spell touches them.".

  // The march: a stage every two days (every day, with the Unsaid crossed and walking at their head).
  Relation kinRoute(place). Measure routeStage(place).
  Initially Assert kinRoute(socket_north). Initially Set routeStage(socket_north) to 1.
  Initially Assert kinRoute(socket_south). Initially Set routeStage(socket_south) to 2.
  Initially Assert kinRoute(horn_foot). Initially Set routeStage(horn_foot) to 3.
  Initially Assert kinRoute(hesk_yard). Initially Set routeStage(hesk_yard) to 4.
  Initially Assert kinRoute(askew_gate). Initially Set routeStage(askew_gate) to 5.
  Initially Assert kinRoute(furrow_end). Initially Set routeStage(furrow_end) to 6.
  Initially Assert kinRoute(rim). Initially Set routeStage(rim) to 7.
  Initially Assert kinRoute(seam). Initially Set routeStage(seam) to 8.
  Rule kin_advance when starFell(corrow) and not kinLost(corrow) and kinStage(corrow) < 8 and watch(clock) >= kinNext(corrow) and not unsaidCrossed(margin) {
    Increase kinStage(corrow) by 1. Set kinNext(corrow) to kinNext(corrow) + 288.
  }
  Rule kin_advance_led when starFell(corrow) and not kinLost(corrow) and kinStage(corrow) < 8 and watch(clock) >= kinNext(corrow) and unsaidCrossed(margin) {
    Increase kinStage(corrow) by 1. Set kinNext(corrow) to kinNext(corrow) + 144.
  }
  Rule kin_move when starFell(corrow) and not kinLost(corrow) and kinRoute(?p) and routeStage(?p) == kinStage(corrow) and not at(kin, ?p) and able(kin) { Assert at(kin, ?p). }
  Observe unsaid_leads near kin when unsaidCrossed(margin) and starFell(corrow) and not kinLost(corrow) "At the head of the column walks something smaller than the rest, wearing a hundred lost coats, and the Unfolded keep pace with it as if it were telling them the way.".
  Rule hornwake_flees when kinStage(corrow) >= 3 and not hornwakeFled(corrow) and not kinLost(corrow)
    says "The Unfolded come into Hornwake at dawn, walking in step, and do not stop. They walk through the wagons and the hoist-towers without turning aside, over a hen coop and across a cook's table, to the horn, and stand round it a long time with their closed-hand heads bowed toward it, and then walk on south along the furrow. Hornwake runs to the Stake ruins with what it can carry." {
    Assert hornwakeFled(corrow). Assert at(wakefolk, chimneys). Assert at(lene, chimneys). Assert at(ruth, chimneys).
  }
  Rule stake_flees when kinStage(corrow) >= 6 and not stakeFled(corrow) and not kinLost(corrow)
    says "The Unfolded reach the Stake ruins and walk through them to the rim, and the salvagers and the people of Hornwake go out the other side and down the Peleth road in the dark, a whole town and a half on the Scarp bends at once." {
    Assert stakeFled(corrow).
  }
  Rule band_read when kinStage(corrow) >= 8 and not bandBroken(corrow) and not bandRead(corrow) and not kinLost(corrow)
    says "Word comes up out of the Well, from the Registry, in a tone it has never used: the Unfolded went down the open shaft without ropes and through the Breach and down the low road, and stood at the Seam a night and a day with their hands on the newest band on the wall. Then they came up again, and went north-north-east across the plateau without stopping, and up. They know where she went." {
    Assert bandRead(corrow). Assert at(kin, limbo).
  }
  Rule kin_baffled when kinStage(corrow) >= 8 and bandBroken(corrow) and not bandRead(corrow) and not kinLost(corrow)
    says "Word comes up out of the Well: the Unfolded went down to the Seam and found the newest band on the wall broken in three, and stood there, and stand there still, with their heads bowed over the empty cup, as if they could not think where to go next." {
    Assert kinLost(corrow). Assert at(kin, seam).
  }
  Observe hornwake_empty at horn_foot when hornwakeFled(corrow) "Hornwake is empty. The wagons stand where they were left, doors open; the hoist-towers have been walked through and lean at angles. Round the horn the frozen ground is printed with enormous feet in a ring.".

  // ── The Forgetting of the Way Home ───────────────────────────────────────────────────────────────────────────────
  // Three hundred who can forget, sitting across the road the enemy must take, before it takes it. No Keld. It takes
  // something in payment, and whoever holds it may choose what.
  Measure riteMinds(place). Relation joinedRite(group). Relation riteHeld(place).
  Relation dragStation(place).
  Initially Assert dragStation(socket_south). Initially Assert dragStation(hesk_yard). Initially Assert dragStation(askew_gate). Initially Assert dragStation(furrow_end).
  Topic rook_rite_minds with rook "Ask the prioress for her sisters, to sit in the Forgetting of the Way Home" when starFell(corrow) and knows(actor, way_home_rite) and not joinedRite(rook) {
    Says "'We are nurses,' says the prioress. 'We help the dying put things down.' She looks out of the window toward the Scarp. 'I suppose the country is dying, a little. Forty of us. Tell us where to sit.'".
    On discuss { Assert joinedRite(rook). Increase riteMinds(corrow) by 40. }
  }
  Topic ferran_rite_minds with ferran "Ask Ferran Cosk for the Open Hand, to sit in the Forgetting of the Way Home" when starFell(corrow) and turned(ferran) and knows(actor, way_home_rite) and not joinedRite(ferran) {
    Says "'Thirty of us,' says Ferran Cosk, 'and we are good at it, God knows. We have been practising on the wrong thing for a year.'".
    On discuss { Assert joinedRite(ferran). Increase riteMinds(corrow) by 30. }
  }
  Topic lene_rite_minds with lene "Ask Lene Tallow to bring Hornwake to sit in the Forgetting of the Way Home" when starFell(corrow) and knows(actor, way_home_rite) and not joinedRite(lene) and (ballasting(lene) or not filing(ruth)) {
    Says "Lene counts the three of you with her eyes, one, two, three. 'You told us the number, when nobody else had,' she says. 'And it was right.' She puts two fingers in her mouth the way Ruth does and whistles up the Wake-moot. 'A hundred and fifty of us. We can forget anything you like. We forget the price of oatcakes every Thursday.'".
    On discuss { Assert joinedRite(lene). Increase riteMinds(corrow) by 150. }
  }
  Topic amberly_rite_minds with amberly "Ask Speaker Vane to bring the Unaskers down to sit in the Forgetting of the Way Home" when starFell(corrow) and knows(actor, way_home_rite) and not joinedRite(amberly) and not crashed(hightown) and not lost(hightown) {
    Says "The Speaker hears you out, and for the first time since you met her she smiles without irony. 'You are asking the people of the Unasked to not-know something, on purpose, together, for the sake of the ground,' she says. 'We have done nothing else for two thousand six hundred years. We are the best in the world at it.' She stands. 'Two hundred of us will come down by the hoists. The doctrine was always correct. It was only waiting for a use.'".
    On discuss { Assert joinedRite(amberly). Increase riteMinds(corrow) by 200. }
  }
  Topic saska_rite with saska "Ask Mother Saska whether the Keld will sit in the Forgetting" when starFell(corrow) and knows(actor, way_home_rite) once {
    Says "'We would,' says Saska. 'We cannot. A Keld cannot forget anything; we would sit in your ring like stones in a river and the rite would go round us.' She folds her hands. 'We will do the other thing. We will remember everyone who sits in it, every name, so that whatever the rite takes from them it cannot take that.'".
  }
  Topic iniry_lead with iniry "Ask Iniry Calde to lead the Forgetting of the Way Home" when starFell(corrow) and state(iniry, returned) and not joinedRite(iniry) {
    Says "'Of course I will lead it,' says Iniry Calde. 'Who else is there? A prioress and a boy with a book.' She is already putting on her coat. 'I will be on the Drag. And when it asks for its price, I will tell you what to give it, and you will not like what I say.'".
    On discuss { Assert joinedRite(iniry). Assert at(iniry, askew_gate). }
  }
  Objective rite_ready when starFell(corrow) and knows(party, way_home_rite) and not riteHeld(corrow) and not kinLost(corrow) and not bandRead(corrow) "The Forgetting of the Way Home needs three hundred who can forget, sitting across the Drag before the Unfolded cross it.".

  // The rite itself: one of four prices. Each needs three hundred minds, the rite known, and the kin not yet past.
  Relation socketLet(place). Relation namesLet(place). Relation companyLet(place). Relation inirySpent(place).
  Action rite_socket(actor: group, site: place) "Hold the Forgetting of the Way Home here, and pay with the way to the Socket" {
    Description "The ring forgets the road home; the rite takes, besides, every mind's knowledge of where the lake is that the mountain came from.".
    Requires able(actor) and company(actor) and at(actor, site) and dragStation(site) and starFell(corrow) and not kinLost(corrow)
      and not riteHeld(corrow) and knows(actor, way_home_rite) and riteMinds(corrow) >= 300 and kinStage(corrow) < routeStage(site).
    Time 12.
    On success { Assert riteHeld(corrow). Assert kinLost(corrow). Assert socketLet(corrow). Set heard(hightown) to 0. }
    Result "Three hundred people sit down in a ring across the Drag in the snow, and Iniry's words, or yours, go round the ring, and round, and round, and nobody afterwards can say what the words were. When the Unfolded come over the rise they walk into the ring and stop. They turn their closed-hand heads one way and the other. Then they walk on, slowly, in different directions, and do not come back. And in the morning nobody in the Corrow can tell you where the lake is that Hightown came out of; there is a lake under the Teskarn, everyone knows that, but whose hole it is, nobody can say.".
  }
  Action rite_names(actor: group, site: place) "Hold the Forgetting of the Way Home here, and pay with the names of the dead" {
    Description "The ring forgets the road home; the rite takes, besides, the names the grave-callers read.".
    Requires able(actor) and company(actor) and at(actor, site) and dragStation(site) and starFell(corrow) and not kinLost(corrow)
      and not riteHeld(corrow) and knows(actor, way_home_rite) and riteMinds(corrow) >= 300 and kinStage(corrow) < routeStage(site).
    Time 12.
    On success { Assert riteHeld(corrow). Assert kinLost(corrow). Assert namesLet(corrow). }
    Result "Three hundred people sit down in a ring across the Drag in the snow, and the words go round, and nobody afterwards can say what they were. The Unfolded walk into the ring and stop, and turn, and walk away in different directions, and do not come back. In Wendmouth that week the grave-callers walk their rounds with their books open, and the pages are blank, and they stand at the stones and cannot read what is cut on them. Only the Keld can say who lies where, and they go from cemetery to cemetery saying it.".
  }
  Action rite_company(actor: group, site: place) "Hold the Forgetting of the Way Home here, and pay with the company: let the Corrow forget you" {
    Description "The ring forgets the road home; the rite takes, besides, every mind's memory of whoever led it. Only the Keld will remember you.".
    Requires able(actor) and company(actor) and at(actor, site) and dragStation(site) and starFell(corrow) and not kinLost(corrow)
      and not riteHeld(corrow) and knows(actor, way_home_rite) and riteMinds(corrow) >= 300 and kinStage(corrow) < routeStage(site).
    Time 12.
    On success { Assert riteHeld(corrow). Assert kinLost(corrow). Assert companyLet(corrow). }
    Result "Three hundred people sit down in a ring across the Drag in the snow, and you lead the words round, and round, and nobody afterwards can say what they were. The Unfolded walk into the ring and stop, and turn, and walk away, and do not come back. When the ring stands up, three hundred people look at you politely, as at strangers, and go home. Only a Keld who was watching from the wall comes over and says your names, one by one, so that somebody has.".
  }
  Action rite_iniry(actor: group, site: place) "Hold the Forgetting of the Way Home here, and let Iniry Calde pay with herself" {
    Description "She says she is a hundred and twenty-seven years forgotten already, and a little more will not hurt.".
    Requires able(actor) and company(actor) and at(actor, site) and dragStation(site) and starFell(corrow) and not kinLost(corrow)
      and not riteHeld(corrow) and knows(actor, way_home_rite) and riteMinds(corrow) >= 300 and kinStage(corrow) < routeStage(site)
      and joinedRite(iniry) and at(iniry, site).
    Time 12.
    On success { Assert riteHeld(corrow). Assert kinLost(corrow). Assert inirySpent(corrow). Assert at(iniry, short_grey_fog). Assert state(iniry, forgotten). }
    Result "Iniry Calde sits in the middle of the ring with her hands in her lap and leads it herself, in the old speech, and the words go round, and nobody can say afterwards what they were. The Unfolded walk into the ring and stop, and turn, and walk away, and do not come back. When the ring stands up there is nobody in the middle of it. Somebody asks who it was that led them. Nobody can say. There is a dent in the snow where someone sat.".
  }
  Rule kin_wander when kinLost(corrow) and riteHeld(corrow) and not at(kin, limbo) and not at(kin, seam) { Assert at(kin, limbo). }
  Observe kin_frozen at socket_south when kinLost(corrow) and riteHeld(corrow) "Out on the plateau, here and there, a figure of black iron as tall as a house stands quite still in the snow, facing nowhere, the way the old story says the raiders of 300 BB stood until they died.".
  Observe kin_frozen_drag at askew_gate when kinLost(corrow) and riteHeld(corrow) "Two of the Unfolded stand in Jory Askew's field facing different ways, quite still, with snow on their shoulders. Jory has hung his gate on the nearer one.".
  Observe stranger_company at inn_room when companyLet(corrow) "Agnes Ruddle looks up as you come in, smiles the smile she keeps for strangers, and asks if you want a room.".
  Observe blank_names at cemetery when namesLet(corrow) "The grave-caller walks the rows with his book open at a blank page, and a Keld girl walks beside him, reading the stones aloud for him, one by one.".

  // ── Drevka's hammer, and Wenna's band ────────────────────────────────────────────────────────────────────────────
  // Only deadiron breaks a laid band cleanly. If the Unfolded reach the Seam and read the band, they know where she went.
  Relation bandBroken(place).
  Kind drevka_hammer "Drevka Orrisk's finishing hammer, of black iron" like crowbar worth 0 weighing 2.
  Item hammer "Drevka's hammer" is drevka_hammer at limbo owned by bede.
  Topic bede_lend with bede "Ask Bede Orrisk for the loan of Drevka's hammer" when (starFell(corrow) or knows(actor, road_fragments) or knows(actor, wenna_band)) and not lends(bede, hammer, actor) {
    Says "Bede takes the hammer off its hook and holds it a long time, the way you hold a sleeping child. 'She closed the last rivet with this,' he says. 'Two thousand six hundred years she held that Chain on a half-set rivet and her own grip.' He holds it out. 'It breaks a laid band in one blow, and it opens a rivet nothing else will open. Whatever you mean to break, be sure.'".
    On discuss { Assert lends(bede, hammer, actor). Assert at(hammer, bede_forge). }
  }
  Action break_band(actor: group, site: place) "Break Wenna's band on the wall with Drevka's hammer" {
    Description "It is the only record of where she went. Whatever reads it can follow her.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, seam) and carries(actor, hammer) and not bandBroken(corrow) and not bandRead(corrow).
    Time 1.
    On success { Assert bandBroken(corrow). }
    Result "Three blows. The first rings like a bell, the whole chamber ringing; the second cracks the band from top to bottom; the third brings it down in pieces into the lake. Wherever Wenna Coyle went, nothing in Imbar can read it now but the horn.".
  }
  Observe band_gone at seam when bandBroken(corrow) "Where the newest band was, the flowstone is broken back to the older bands under it, and three pieces lie in the shallows.".
}

data/adventures/let-one-remember/act4_vo:
Module corrow "The Road the Star Came Down" {
  Description "Act IV, Under Way: Hightown cast off its Chain and steered by memory, up the road the star came down, to the Gate of Being.".

  // ── The vessel ───────────────────────────────────────────────────────────────────────────────────────────────────
  // A weightless mountain is steered by memory. One more Counterweight who holds where it came from sinks it; one the
  // Unaskers let forget raises it. Cast off its Chain at the cradles, with Drevka's hammer on Drevka's own work, and it
  // goes where its people's knowing takes it. The horn stays on the plateau; a needle cut from it points at the Hush.
  Query afloat(p: place) means (not crashed(p) and not grounded(p) and not lost(p)) or relifted(p).
  Relation relifted(place). Relation underWay(place).
  Measure altitude(place). Measure leg(place). Measure legNext(place).
  Action relift(actor: group, site: place) "Ask the Unaskers to let Hightown forget its place again, as the Calvessa first made it forget" {
    Description "It was lifted once by a rite. It can be lifted again. The rite takes its price.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, rim_walk) and knows(actor, way_home_rite)
      and joinedRite(amberly) and (grounded(hightown) or crashed(hightown)) and not relifted(hightown) and not lost(hightown).
    Time 36.
    On success { Assert relifted(hightown). Set heard(hightown) to 0. Set altitude(hightown) to 400. }
    Result "For six hours two hundred Unaskers sit on the broken terraces in the snow and practise the oldest thing they know, and lead the rest. At dusk the mountain creaks along every fault in it, and then it lifts: off the shore, off the plateau, a hand's breadth, a man's height, a house's, with water and rock pouring off its underside, and nobody on it can tell you any more where it used to stand.".
  }

  // The compass: a needle of the horn, cut with the only tool that cuts it.
  Kind horn_needle "a needle of black iron cut from the horn, which will not lie still in the hand" is treasure worth 0 weighing 1.
  Item needle "a needle of the horn" is horn_needle at limbo.
  Action cut_needle(actor: group, site: place) "Cut a needle from the horn's tip with Drevka's hammer" {
    Description "The horn pulls, always, north-north-east and up, toward the Hush. A piece of it will pull the same way.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, horn_foot) and carries(actor, hammer) and at(needle, limbo).
    Time 18.
    On success { Assert at(needle, horn_foot). }
    Result "Three hours of blows, on the horn's thin tip, in the cold. Nothing else in Imbar would mark it. At last a sliver as long as your forearm comes away and falls in the snow, and when you pick it up it turns in your fist like a live fish, and settles, pointing north-north-east and up.".
  }

  // Casting off.
  Relation hartmarkRim(place).
  Action cast_off(actor: group, site: place) "Strike out the pin of the first link's cradle with Drevka's hammer, and let Hightown go" {
    Description "Its Chain falls away to the plateau. It will go wherever the knowing of its people takes it.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, cable_cradles) and carries(actor, hammer) and afloat(hightown)
      and not underWay(hightown) and roster(aron) and joinedRite(amberly).
    Time 6.
    On success { Assert underWay(hightown). Set leg(hightown) to 0. Set legNext(hightown) to watch(clock) + 36. Assert at(actor, cradle_gallery). }
    Result "The pin is Ondrek work, as thick as a man and two thousand six hundred years in its socket, and it comes out at the ninth blow with a sound like the end of something. The first link swings free in its cradle, and the Chain goes: all of it, a hundred and forty links, two and a half kilometres of iron, falling away under you and folding down onto the plateau in a long slow pile that you feel through the mountain for a minute after. Then Hightown is quite still in the air, and nothing holds it at all. You climb up into the gallery. Everybody on the mountain is on the rim, looking down.".
  }
  Rule set_altitude when underWay(hightown) and altitude(hightown) == 0 and not relifted(hightown) { Set altitude(hightown) to 2400. }
  Rule hartmark_cuts when underWay(hightown) and paying(esk) and not hartmarkRim(hightown)
    says "From the rim you see grey-coated riders at the foot of the hoists, too late: Esk of Harrow's men, come to put a Hartmark crew aboard. They watch the mountain go. One of them lifts a hand, as if to wave, and does not." {
    Assert hartmarkRim(hightown).
  }

  // Steering: from the hall of the Charge, which is the helm now.
  Action rise(actor: group, site: place) "Ask the Unaskers to let one of them forget where Hightown came from" {
    Description "One fewer holding its place: four hundred metres up.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, charge_hall) and underWay(hightown) and leg(hightown) < 4.
    Time 6.
    On success { Increase altitude(hightown) by 400. }
    Result "An Unasker sits down on the stone seat in the middle of the Charge and closes her eyes, and the others hum the old not-knowing round her, and after an hour she opens them and asks, puzzled, what everyone is looking at. Under your feet the mountain is a little lighter.".
  }
  Action sink(actor: group, site: place) "Ask Linnet to put one more name on the roster" {
    Description "One more holding its place: four hundred metres down.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, charge_hall) and underWay(hightown) and leg(hightown) < 4
      and altitude(hightown) >= 800.
    Time 6.
    On success { Decrease altitude(hightown) by 400. }
    Result "Linnet Vane writes a name in the roster book in her careful hand, and Aron takes the one it belongs to aside and tells them. Under your feet the mountain is a little heavier.".
  }
  Observe helm_scene at charge_hall when underWay(hightown) "The hall of the Charge is the helm now. The charge-holders sit in their ring with the roster book open on one seat and the Unaskers on another, and every hour someone comes up from the rim to say what can be seen.".

  // The legs. Every six hours the mountain goes on, if it is where it must be.
  Rule over_teskarn when underWay(hightown) and leg(hightown) == 0 and watch(clock) >= legNext(hightown) and altitude(hightown) >= 3200
    says "Hightown goes over the Teskarn. From the rim the summits pass below like the backs of whales, a long way down, and the snow on them is pink with the low sun." {
    Set leg(hightown) to 1. Set legNext(hightown) to watch(clock) + 36.
  }
  Rule into_cloud_sea when underWay(hightown) and leg(hightown) == 1 and watch(clock) >= legNext(hightown) and altitude(hightown) >= 4400
    says "Hightown comes up through the last of the cloud into a sea of it, white, level, going on for ever under a sky that is nearly black at noon. There is no ground any more. There is only north-north-east." {
    Set leg(hightown) to 2. Set legNext(hightown) to watch(clock) + 36.
  }
  Rule onto_road when underWay(hightown) and leg(hightown) == 2 and watch(clock) >= legNext(hightown) and carries(party, needle)
    and altitude(hightown) >= 5200 and altitude(hightown) <= 6800
    says "There it is: the road the star came down. A band of burnt air going up out of the cloud sea toward the north-north-east, dark against the dark sky, glinting here and there with something like ash that does not fall. The needle in your hand pulls along it like a dog on a lead, and Hightown, held at the road's height, goes up it." {
    Set leg(hightown) to 3. Set legNext(hightown) to watch(clock) + 72.
  }
  Rule to_the_gate when underWay(hightown) and leg(hightown) == 3 and watch(clock) >= legNext(hightown) and altitude(hightown) >= 7600
    says "At the top of the road the sky stops. Not the light: the sky. Ahead of Hightown, close enough to touch from the rim, is a wall of nothing in particular that goes up and down and to either side for ever, and in it, where the road meets it, a door." {
    Set leg(hightown) to 4.
  }
  Hazard thin_air "air too thin to breathe" means "Deal (1d6) physical damage to ally unless constitution save against (13).".
  Rule air_too_thin when underWay(hightown) and leg(hightown) < 3 and altitude(hightown) > 7200 and dice(clock) <= 10 { Assert strikes(thin_air, party). }

  // What can be seen from the rim, and what the needle says.
  Observe rim_under_way at rim_walk when underWay(hightown) and leg(hightown) == 0 "Hightown rides free over the plateau with nothing under it. Far below, the Chain lies in a long black scrawl across the snow from the horn. Ahead, north-north-east, the Teskarn: higher than Hightown is.".
  Observe rim_teskarn at rim_walk when underWay(hightown) and leg(hightown) == 1 "The Teskarn falls away behind. Ahead the cloud stands up in a wall, white below and grey above; the mountain will have to go over it.".
  Observe rim_cloud at rim_walk when underWay(hightown) and leg(hightown) == 2 "The cloud sea, white and level, for ever.".
  Observe rim_road at rim_walk when underWay(hightown) and leg(hightown) == 3 "The burnt road goes up ahead into the dark sky, and Hightown goes up it.".
  Observe needle_low near party when carries(party, needle) and underWay(hightown) and leg(hightown) == 2 and altitude(hightown) < 5200 "The needle of the horn strains upward in your hand, hard. Whatever it points at is above you.".
  Observe needle_high near party when carries(party, needle) and underWay(hightown) and leg(hightown) == 2 and altitude(hightown) > 6800 "The needle of the horn dips, pointing down and ahead. You are above whatever it is following.".
  Observe needle_level near party when carries(party, needle) and underWay(hightown) and leg(hightown) == 2 and altitude(hightown) >= 5200 and altitude(hightown) <= 6800 "The needle of the horn lies level in your palm, pointing dead ahead, north-north-east.".
  Observe no_needle near party when not carries(party, needle) and underWay(hightown) and leg(hightown) == 2 "In the cloud sea every way looks the same. Without the horn there is nothing to tell north-north-east from any other way.".
  // What went up the road before you.
  Observe kin_on_road at rim_walk when underWay(hightown) and leg(hightown) == 3 and bandRead(corrow) "Far up the road, small with distance, a column of the Unfolded is climbing, in step, and does not look back.".
  Observe unsaid_on_road at rim_walk when underWay(hightown) and leg(hightown) == 3 and (unsaidSent(margin) or unsaidCrossed(margin)) "On the burnt road, here and there, lie lost things: a glove, a hat, a Peleth ledger. Something went up this way wearing them, and is shedding them as it goes.".

  // ── The Gate of Being ────────────────────────────────────────────────────────────────────────────────────────────
  // The Virina divided the planes so that each power might have its own room. One of them keeps this door.
  Place gate_edge "the Gate of Being" is room within summit at 3, 2 outdoors.
  Passage gangway "the gangway over the rim" is passage between rim_walk and gate_edge
    opening when leg(hightown) == 4 "Over the rim there is only sky.".
  Observe being_gate_scene at gate_edge when true "A ledge of nothing that holds you up, and in front of it a door in the wall at the end of the sky: plain, tall, the colour of the moment before a decision. Beside it stands someone in grey who is not a person, exactly, but who has chosen to look like one so that you can talk to it.".
  Person arbiter "an Arbiter of the Virina" at gate_edge {
    Role "one of those who divided the planes, keeping a door". Peaceable.
  }
  Discovery one_rule "What the Coyle keepers said, and the old prayer sang: one walks the road, always one. Never two: every other who knows where the jewel is draws the star faster. Never none: a jewel no mind knows slips into the plane it binds, and the plane comes undone.".
  Topic saska_one with saska "Ask Mother Saska what the Coyle keepers' rule was" when knows(actor, wenna_band) or knows(actor, road_fragments) once {
    Says "'Never none, never two,' says Saska at once. 'Sabeth Coyle's mother said it to her, and Sabeth said it to Marra, and Marra to Wenna. My grandmother heard Marra say it the day they anchored her back.' She is quiet a moment. 'One walks it, always one. That's in the prayer, the part they still sing.'".
    On discuss { Assert knows(actor, one_rule). }
  }
  Topic arbiter_door with arbiter "Ask the Arbiter to open the door" when not gateOpen(hightown) {
    Says "'What is bound stays bound,' says the Arbiter. 'What is divided stays divided. Beyond this door is a country that was never woven of your world, and in it, a long way off, a woman is carrying a thing that binds one of your planes, and a thing is following her.' It looks at each of you in turn, and you have the impression that it is counting. 'I will open it to one who knows the way. Not to two. If two of you know the way, then there are two.'".
  }
  Relation gateOpen(place). Relation oneKeeps(group).
  Action let_road_go(actor: group, site: place) "Ask the Unaskers to take the road out of all of you but one" {
    Description "Every one of you who read Wenna's band, or took the road's fragments, knows the way. One may keep it.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gate_edge) and not oneKeeps(actor)
      and (knows(actor, wenna_band) or knows(actor, road_fragments)).
    Time 6.
    On success { Assert oneKeeps(actor). }
    Result "The Unaskers come out onto the ledge and sit round you, and hum, and one by one the way goes out of all of you but the one who will lead: north-north-east and up, a burnt road, a door, a star at the end. Afterwards the others look at the door and do not know where it goes. The one who kept it knows, and finds that it is very lonely to be the only one.".
  }
  Topic arbiter_answer with arbiter "Tell the Arbiter the rule: never none, never two" when knows(actor, one_rule) and not gateOpen(hightown)
    and (oneKeeps(actor) or (not knows(actor, wenna_band) and not knows(actor, road_fragments) and carries(actor, needle))) {
    Says "'Never none, never two,' says the Arbiter, as if tasting it. 'A mortal rule, made by mortals, for the same reason we made ours.' It puts its hand on the door. 'One of you knows the way. One. Go through.' The door opens on a country without colour, and a road going on.".
    On discuss { Assert gateOpen(hightown). }
  }
  Topic arbiter_two with arbiter "Tell the Arbiter the rule: never none, never two" when knows(actor, one_rule) and not gateOpen(hightown)
    and not oneKeeps(actor) and (knows(actor, wenna_band) or knows(actor, road_fragments)) {
    Says "'Then you know why I cannot,' says the Arbiter. 'There are three of you who know the way. Make it one.'".
  }
}

data/adventures/let-one-remember/act5_ro:
Module corrow "The Road the Star Came Down" {
  Description "Act V, the Road the Star Came Down: beyond the gates of being, where nothing is woven of the prima materium, and a woman has been thinking of elsewhere for ninety years.".

  Place beyond "beyond the gates of being" is plane.
  Place unwoven "the unwoven country" is region within beyond.
  Place far_road "the road beyond" is wilderness within unwoven at 0, 0.
  Place far_side "the far side of the door" is room within far_road at 0, 0 outdoors.
  Place road_beyond "the burnt road, going on" is room within far_road at 1, 0 outdoors.
  Place nail_wake "the Nail's wake" is room within far_road at 2, 0 outdoors.
  Place wennas_stop "where the road stops" is room within far_road at 3, 0 outdoors.

  Passage the_door "the door in the wall at the end of the sky" is doorway between gate_edge and far_side
    opening when gateOpen(hightown) "The door is shut. The Arbiter stands beside it.".
  Passage road_on "the burnt road" is path between far_side and road_beyond taking 2 hours.
  Passage into_wake "along the furrow it ploughed" is path between road_beyond and nail_wake taking 1 hour.
  Passage past_the_nail "past the Nail" is path between nail_wake and wennas_stop taking 1 hour.

  // Nothing here is woven of the world's binding magic: it is all of a piece with deadiron.
  Observe far_side_scene at far_side when true "The door shuts behind you, and you are in a country with no colour in it: not grey, which is a colour, but none. Ground, sky, the road, all of a piece, all of one black stuff that you have walked on before. Nothing here was ever woven of your world. No spell any of you knows would so much as flicker. Hightown hangs behind you in the door like a picture of somewhere.".
  Observe road_beyond_scene at road_beyond when true "The burnt road goes on, level now, across the unwoven country toward something on the horizon that is very large and does not move.".
  Observe road_kin at road_beyond when bandRead(corrow) "The Unfolded passed this way. Their prints go on ahead of you in step, and once, at the roadside, one of them stands quite still with its closed-hand head bowed, as if listening for something it has lost.".
  Observe road_coats at road_beyond when unsaidSent(margin) or unsaidCrossed(margin) "On the road lie lost things, more and more of them: gloves, hats, a cart-wheel, a Peleth ledger, a gravestone name. Whatever wore them has put them all down.".

  // The Nail: a body without its name, or, if the Unsaid reached it, the Varakiiri whole.
  Relation reunited(place).
  Rule name_finds_body when (unsaidSent(margin) or unsaidCrossed(margin)) and not reunited(beyond) { Assert reunited(beyond). }
  Person nail "the Nail" at nail_wake {
    Role "the Varakiiri that fell on the Corrow, one thought behind the jewel". Peaceable.
  }
  Observe nail_asleep at nail_wake when not reunited(beyond) "The Nail lies across the road like a hill of black iron and glass and something the eye slides off: sixty metres of it, horned, the stump of its greatest horn raw where it broke from the Chain in 2641. It is moving. You can see it move, the way you can see a minute hand move if you watch long enough: toward the horizon, one thought behind whatever is there. It does not see you. It has no name to see you with.".
  Observe nail_awake at nail_wake when reunited(beyond) "The Nail lies across the road like a hill of black iron and glass, horned, and it is awake. Something came up the road wearing lost things and went into it. Its attention moves over you like weather. It is still a thought behind the woman on the horizon. It is no longer content to be.".
  Topic nail_speaks with nail "Listen to the Varakiiri" when reunited(beyond) once {
    Says "It does not speak in words. The ground under you speaks, the stuff of it, and you understand it the way you understand cold. YOU ARE FROM THE PLACE THAT FORGETS. I WAS LEFT BLIND IN A HOLE. I HAVE IT AGAIN. THE JEWEL IS MINE. THERE ARE EIGHT MORE, AND MY KIN ARE COMING FOR THEM. GIVE IT TO ME AND I WILL GO HOME.".
  }

  // Wenna Coyle, aged a hundred and fifty-nine, who has thought of nothing but elsewhere for ninety years.
  Person wenna "the old woman at the end of the road" at wennas_stop {
    Role "an old woman holding something that lights her hands". Ancestry human. Peaceable.
    State keeping "An old woman stands at the very end of the road, where it stops at nothing, with her two hands cupped round something that lights them from inside: something the size of a child's fist, with nine faces. She is very old, older than anyone should be, and she is not looking at you, or at anything. Her lips are moving. She is saying, over and over, the way the Strays say their syllables: elsewhere, elsewhere, elsewhere.".
    State herself "Wenna Coyle stands at the end of the road with the Hush in her hands and her lens in her pocket, and looks at you, and her face goes through hope, and then through caution, and stops there.".
  }
  Observe wenna_ringed at wennas_stop when bandRead(corrow) and state(wenna, keeping) "Round her, at a distance, the Unfolded kneel in a ring with their heads bowed, waiting. They cannot come nearer than she lets them. She has not noticed them.".
  Topic wenna_who with wenna "Ask the old woman who she is" when state(wenna, keeping) once {
    Says "She does not look at you. 'Elsewhere,' she says. 'Elsewhere. Elsewhere.' Then, as if the word had caught on something: 'I was keeping something. I put everything else down so I could carry it. My name was the last thing.' Her hands tighten. 'Elsewhere.'".
  }
  Action give_lens(actor: group, site: place) "Put Wenna's lens in the old woman's hands" {
    Description "She ground it in 2601 and kept it in a drawer, with her mother's ring, where she kept things so they would stay. It came home to the Coyle house in 2719 because she had forgotten it.".
    Requires able(actor) and company(actor) and at(actor, site) and at(wenna, site) and carries(actor, wenna_lens) and state(wenna, keeping).
    Time 1.
    On success { Assert state(wenna, herself). }
    Result "She takes it without looking, the way a hand takes something it has held ten thousand times, and her thumb goes across its face, feeling for the hum of a high spot, and finds none: a true surface makes no sound at all. She lifts it to her eye and looks at you through it. 'Wen,' she says, slowly, as if somebody had called her across a weir. 'Wenna. Coyle.' She lowers it. 'Somebody followed.'".
  }
  Topic wenna_herself with wenna "Ask Wenna Coyle why she came this way" when state(wenna, herself) once {
    Says "'Because it was the way it came,' says Wenna. 'The Witness road. I thought if I carried the jewel back up the road the star came down, the star would follow it home, out of the world, and the Corrow would be quiet.' She looks past you at the thing on the road behind you. 'It followed. It didn't stop. And I couldn't stop, because if I stopped it would have it, and if I thought of anything but elsewhere it would be a thought nearer.' She smiles a little. 'I said if nobody follows it ends with me. I meant it to be a kindness. It wasn't. It was only lonely.'".
  }

  // The last choice: the setting's first law, at the scale of the planes.
  Relation endedOne(place). Relation endedGiven(place). Relation endedNone(place). Relation endedFollowed(place).
  Query ended(p: place) means endedOne(p) or endedGiven(p) or endedNone(p) or endedFollowed(p).
  Action take_charge(actor: group, site: place) "Take the charge from Wenna: the one of you who kept the road keeps the jewel now" {
    Description "Never none, never two. One walks it, always one.".
    Requires able(actor) and company(actor) and at(actor, site) and at(wenna, site) and state(wenna, herself) and not ended(beyond)
      and (oneKeeps(actor) or carries(actor, needle)).
    Time 6.
    On success { Assert endedOne(beyond). }
    Result "She does not lay it in stone; there is no stone here that remembers. She puts it into the hands of the one who kept the road, and closes their fingers on it with hers, and holds them closed while she tells them, slowly, as you would tell a child the way home, everything she knows: where it is, what it is, that it must always be one. When she lets go she is only an old woman, very tired, standing at the end of a road. 'I'll sit down now,' she says, and does, on the edge of nothing, with her lens in her lap, and closes her eyes, and does not open them again. Behind you, on the road, the Nail goes still. Its quarry is known to exactly one mind again. It will fall as slowly as it fell for two thousand years.".
  }
  Action give_heart(actor: group, site: place) "Take the Hush from Wenna and give it to the thing that follows" {
    Description "It says it is its own. It says there are eight more.".
    Requires able(actor) and company(actor) and at(actor, site) and at(wenna, site) and not ended(beyond).
    Time 2.
    On success { Assert endedGiven(beyond). }
    Result "Wenna lets you take it. She does not fight; she is too tired. You walk back along the road with nine faces of light in your hands to the thing lying across it, and hold it out, and the Nail takes it. Not with a hand: the jewel is simply in it, and it is whole. It rises off the road without hurry, a hill of black iron going up into a sky that is not a sky, and turns, and goes away toward wherever such things come from, and the light of it goes a long time. Behind you, through the open door, very far down, every lost thing in the Corrow begins to come home at once.".
  }
  Action let_none(actor: group, site: place) "Let the road go out of the last of you, and out of Wenna, so that no mind knows where the jewel is" {
    Description "Never none: a jewel no mind knows slips into the plane it binds. The plane comes undone.".
    Requires able(actor) and company(actor) and at(actor, site) and at(wenna, site) and not ended(beyond).
    Time 6.
    On success { Assert endedNone(beyond). }
    Result "Wenna understands what you mean to do before you have finished saying it, and does not stop you. The Unaskers' hum, or the Lettings' words, or simply turning away: whatever you use, it works. Nobody knows where the Hush is. Not her, not you. For a moment it lies in her open hands, lit from inside, known to nobody. Then her hands are empty. And behind you, through the door, very far down, the grey country that it bound begins to come apart into the Corrow, and everything forgotten there for two thousand six hundred years comes home at once.".
  }
  Action follow_on(actor: group, site: place) "Go on with Wenna, a thought ahead of the Nail, for ever" {
    Description "Then nobody in the Corrow ever learns where the jewel went, or where you went.".
    Requires able(actor) and company(actor) and at(actor, site) and at(wenna, site) and state(wenna, herself) and not ended(beyond).
    Time 6.
    On success { Assert endedFollowed(beyond). }
    Result "You walk beside her. She is glad of the company. You find you can think of elsewhere too, all of you, after a while, and that it is not so lonely shared among a few, though the rule says it should be one. Behind you the Nail comes on, one thought behind. Ahead there is always more road.".
  }

  // The endings, told once.
  Entity finale_told: fact "How the road ended.".
  Observe finale_home near party when endedOne(beyond) and carries(party, absence) and not knows(party, finale_told) "You carry the jewel back down the road, and through the door, and the Arbiter shuts it behind you. On Hightown's deck you lay the stone of the mountain's place, which weighs nothing, and the mountain knows at once where it belongs. It goes home down the burnt road and over the cloud sea and the Teskarn, sinking a little each hour as its people come to know it, one a day, and in the spring it settles into the Socket like a stone into its own print, and the lake comes up round its sides. The one of you who keeps the jewel lives in Wendmouth, in the Coyle house, and is very careful about what they think of. The Nail lies beyond the gates of being, still falling, very slowly, toward a jewel known to one mind." teaches finale_told.
  Observe finale_one near party when endedOne(beyond) and not carries(party, absence) and not knows(party, finale_told) "You carry the jewel back down the road, and through the door, and the Arbiter shuts it behind you. Hightown comes down the burnt road as its people let it, one a day, and settles at last on the plateau, wherever it was when the roster ran out of names. The one of you who keeps the jewel lives in Wendmouth, in the Coyle house, and is very careful about what they think of. The Nail lies beyond the gates of being, still falling, very slowly, toward a jewel known to one mind." teaches finale_told.
  Observe finale_one_awake near party when endedOne(beyond) and reunited(beyond) "The Nail has its name now, and it knows yours. Every night the one who keeps the jewel dreams of a hill of black iron that is patient, and awake, and one thought behind.".
  Observe finale_given near party when endedGiven(beyond) and not knows(party, finale_told) "The Varakiiri went home with its heart, and the Margin that the jewel bound came apart into the Corrow: Keld Hollow's empty houses standing in a field above Wendhead, the Calvessa's lost history in drifts on the Scarp, a million gloves. The Lettings say it will take a generation to put it all away again. In the north-east, low over the Teskarn, eight new stars have appeared, and none of them is moving with the others." teaches finale_told.
  Observe finale_none near party when endedNone(beyond) and not knows(party, finale_told) "Nobody knows where the Hush is. The Margin it bound has come undone into the Corrow, and everything forgotten there is home at once: the hamlet, the history, the gloves, the name of the mountain, which every Counterweight now knows. The Nail lies on the road beyond the gates with nothing to fall toward, and, very slowly, it has begun to come back the way it came." teaches finale_told.
  Observe finale_followed near party when endedFollowed(beyond) and not knows(party, finale_told) "Nobody in the Corrow knows where you went. In Wendmouth, the grave-callers read your names on their rounds, though there are no stones, because a Keld girl insists. Hightown hangs at the Gate of Being with its door shut, and its people have begun, one a day, to remember the way home." teaches finale_told.
}

Module corrow "Let One Remember" {
  Description "The Corrow in 2731, ninety years after the Unfall: a mountain on a chain drifting toward the hole it came out of, a country whose stones are going blank, and a people who cannot be forgotten.".

  // The country, north to south. Hightown and the Chain are over the plateau; the Well is under the Stake ruins.
  Place corrow "the Corrow" is region.
  Place socket_country "the Socket" is wilderness within corrow at 3, 0.
  Place hightown "Hightown" is settlement within corrow at 4, 0.
  Place chain "the Chain" is site within corrow at 5, 1.
  Place hornwake "Hornwake" is settlement within corrow at 4, 1.
  Place plateau "the Hesk plateau" is wilderness within corrow at 3, 2.
  Place keld "Keld" is settlement within corrow at 1, 2.
  Place stake "the Stake ruins" is settlement within corrow at 3, 3.
  Place well "the Emptied Well" is site within corrow at 4, 3.
  Place scarp "the Scarp road" is wilderness within corrow at 3, 4.
  Place wendhead "Wendhead" is settlement within corrow at 3, 5.
  Place wendmouth "Wendmouth" is settlement within corrow at 3, 6.

  // ── The balance ──────────────────────────────────────────────────────────────────────────────────────────────────
  // Hightown floats because the mountain has forgotten its weight and the air has not. What holds it down is its Chain:
  // 143 links of eleven hundred tonnes, and the horn of three thousand at the end, dragging on the plateau. Whatever of
  // that the mountain cannot lift rests on the ground and grips it. If nothing rests, the mountain goes up with its
  // whole Chain and does not stop.
  //
  //   resting = links × 1,100 + horn 3,000 + 1,000 for every Counterweight who has come to hold where it came from
  //             + what the hoists have carried up as ballast − what the mountain lifts in this air
  //
  // The mountain lifts more as the air grows cold and heavy: 154,000 t in the last of the autumn, 158,500 t in midwinter.
  Measure tailLinks(place). Measure hightownLift(place). Measure restingWeight(place). Measure ballast(place).
  Measure heard(place). Measure nextChill(place).
  Initially Set tailLinks(hightown) to 143.
  Initially Set hightownLift(hightown) to 154000.
  Initially Set nextChill(hightown) to 144.
  Initially Set restingWeight(hightown) to 6300.
  Rule air_chills when watch(clock) >= nextChill(hightown) and hightownLift(hightown) < 158500 {
    Increase hightownLift(hightown) by 250. Set nextChill(hightown) to nextChill(hightown) + 144.
  }
  // Kyr reckons left to right, so the thousand tonnes a head are worked out first, on their own.
  Measure heardWeight(place).
  Rule reckon_heard when heardWeight(hightown) != heard(hightown) * 1000 { Set heardWeight(hightown) to heard(hightown) * 1000. }
  Rule reckon_rest when restingWeight(hightown) != tailLinks(hightown) * 1100 + 3000 + heardWeight(hightown) + ballast(hightown) - hightownLift(hightown) {
    Set restingWeight(hightown) to tailLinks(hightown) * 1100 + 3000 + heardWeight(hightown) + ballast(hightown) - hightownLift(hightown).
  }

  // The drift. Hightown rides north on the gales along the line of the old Drag, toward the Socket: 3.9 km to go. A heavy
  // tail grips; a light one skips. Once twenty more of Hightown hold where it came from, the mountain has sunk some 350 m
  // and the horn bites into the plateau and holds.
  Measure socketDistance(place). Measure sunk(place).
  Initially Set socketDistance(hightown) to 3900.
  Relation bitten(place). Relation overSocket(place).
  Rule sinks_with_heard when sunk(hightown) != heard(hightown) * 16 and heard(hightown) < 150 { Set sunk(hightown) to heard(hightown) * 16. }
  Rule horn_bites when heard(hightown) >= 20 and heard(hightown) < 150 and not bitten(hightown) and not crashed(hightown) and not lost(hightown)
    says "Up on the plateau, the horn stops dragging. It has gone into the frozen ground to the root of its curve, and the Chain above it hangs nearly straight. Hightown is lower in the sky than anyone in Hornwake has ever seen it." {
    Assert bitten(hightown).
  }

  // The great gales of the season: five in four weeks, closer together as the winter deepens.
  Relation galeBlown(entity). Measure galesBlown(place). Measure lastGale(place).
  Entity gale_one: scenery "the first great gale". Entity gale_two: scenery "the second great gale".
  Entity gale_three: scenery "the third great gale". Entity gale_four: scenery "the fourth great gale".
  Entity gale_five: scenery "the fifth great gale".
  Measure galeDue(entity). Relation gale(entity).
  Initially Assert gale(gale_one). Initially Assert gale(gale_two). Initially Assert gale(gale_three).
  Initially Assert gale(gale_four). Initially Assert gale(gale_five).
  Initially Set galeDue(gale_one) to 864. Initially Set galeDue(gale_two) to 1872. Initially Set galeDue(gale_three) to 2736.
  Initially Set galeDue(gale_four) to 3312. Initially Set galeDue(gale_five) to 3744.
  Rule gale_blows when gale(?g) and galeDue(?g) <= watch(clock) and not galeBlown(?g) and not crashed(hightown) and not lost(hightown)
    says "A great gale comes over the Teskarn out of the south-west and lies on the plateau for a day and a night. Nothing moves in it but the mountain and the horn." {
    Assert galeBlown(?g). Increase galesBlown(hightown) by 1. Set lastGale(hightown) to watch(clock). Assert driven(hightown).
  }
  Relation driven(place).
  // How far a gale drives it: Kyr's counts never go below nothing, so the last stretch to the shore is set, not taken.
  Measure driftBy(place).
  Rule drift_heavy when driven(hightown) and not bitten(hightown) and restingWeight(hightown) >= 4000 { Retract driven(hightown). Set driftBy(hightown) to 400. }
  Rule drift_middling when driven(hightown) and not bitten(hightown) and restingWeight(hightown) >= 1000 and restingWeight(hightown) < 4000 { Retract driven(hightown). Set driftBy(hightown) to 800. }
  Rule drift_light when driven(hightown) and not bitten(hightown) and restingWeight(hightown) < 1000 { Retract driven(hightown). Set driftBy(hightown) to 1400. }
  Rule drift_on when driftBy(hightown) > 0 and socketDistance(hightown) >= driftBy(hightown) { Decrease socketDistance(hightown) by driftBy(hightown). Set driftBy(hightown) to 0. }
  Rule drift_ashore when driftBy(hightown) > 0 and socketDistance(hightown) < driftBy(hightown) { Set socketDistance(hightown) to 0. Set driftBy(hightown) to 0. }
  Rule driven_held when driven(hightown) and bitten(hightown) { Retract driven(hightown). }
  Rule over_the_socket when socketDistance(hightown) <= 0 and not overSocket(hightown)
    says "When the gale drops, Hightown is not where it was. It hangs over the south shore of the Socket, and its shadow lies on the water: a long dark bowl on a lake the same shape." {
    Assert overSocket(hightown).
  }

  // Where it ends, for the mountain. Each holds for ever once true.
  Relation crashed(place). Relation lost(place). Relation fellOnShore(place).
  // Nothing rests: up it goes, Chain, horn and all.
  Rule hightown_lost when restingWeight(hightown) <= 0 and not lost(hightown) and not crashed(hightown)
    says "In the night the sound of the horn stops. In the morning it is not in its furrow. It is a hundred metres up, turning slowly at the end of the Chain, with clods of frozen earth falling off it; by noon it is a black speck under a mountain that is smaller every hour; by evening Hightown is a star that moves, going up, and nobody below will ever see its lights again." {
    Assert lost(hightown).
  }
  // Half of Hightown at once: the relation closes, and the mountain falls like the granite it is.
  Rule hightown_falls when heard(hightown) >= 450 and not crashed(hightown) and not lost(hightown)
    says "It does not sink. It drops. For a long breath the whole sky over the plateau is granite, and then the ground jumps under you like a struck table, and the sound comes, and goes on. When the dust lies down there is a mountain where the sky was, tilted, broken at its rim, and the Chain lies slack across the plateau for two kilometres like a dropped necklace." {
    Assert crashed(hightown).
  }
  Rule fell_on_shore when crashed(hightown) and overSocket(hightown) and not fellOnShore(hightown) { Assert fellOnShore(hightown). }

  // Midwinter: the turn of the year, twenty-eight days on. The country takes stock.
  Relation midwinter(place).
  Rule midwinter_comes when watch(clock) >= 4032 and not midwinter(corrow)
    says "It is midwinter. The gale season has another three months to run, but the shortest day is a day the Corrow keeps: the bounds are walked in the dark, the names are read at every grave, and everyone says aloud what they mean to keep." {
    Assert midwinter(corrow).
  }

  // What the company can see it is up against.
  Objective drift_seen when knows(party, arrived) and not crashed(hightown) and not lost(hightown) and not bitten(hightown) and not grounded(hightown) "Hightown is drifting north on every gale toward the lake it was lifted out of. Midwinter is twenty-eight days off.".
  Objective ask_number when knows(party, jobs_known) and filing(ruth) and not knows(party, cut_limit) "The runners are filing another link off the tail. Nobody has asked the Registry how many can go.".
  Objective tell_ruth when knows(party, cut_limit) and filing(ruth) "Ruth Teake believes there are twenty links to spare. There are not.".
  Objective tell_aron when knows(party, method_known) and not roster(aron) and not crashed(hightown) and not grounded(hightown) "The engineers of the Concord Warden's office wrote how to bring the mountain down: let one remember at a time. Aron Fennimore, in Hightown, does not know it.".
  Objective rim_now when gathering(grounders) "The Grounders are gathering on Hightown's rim to tell everyone to look down.".

  // How it stands, told once, wherever the company is.
  Entity ending_told: fact "How it stood at midwinter.".
  Observe end_lost near party when lost(hightown) and not knows(party, ending_told) "Hightown has gone up into the wastes beyond Imbar with nine hundred people on it, and its Chain, and the horn. Hornwake stands round an empty furrow. The runners do not cut anything now." teaches ending_told.
  Observe end_fell_shore near party when fellOnShore(hightown) and not knows(party, ending_told) "Hightown lies on the south shore of the Socket with its north rim in the lake, tilted like a dropped bowl. The terraces broke. A hundred and forty people died on them, and the rest came down the slope of their own mountain onto soil, carrying what they could. It is home, in a way. Nobody in Hightown will say so for a generation." teaches ending_told.
  Observe end_fell_plain near party when crashed(hightown) and not overSocket(hightown) and not knows(party, ending_told) "Hightown lies on the open plateau short of the Socket, broken in half along an old fault, and the furrow and half of Hornwake's wagons are under it. Nobody yet knows how many died. The mountain came down where it happened to be when enough of its people learned where it belonged." teaches ending_told.
  Observe end_lowered near party when midwinter(corrow) and bitten(hightown) and not crashed(hightown) and not lost(hightown) and not knows(party, ending_told) "Hightown hangs low over the plateau with its horn bitten deep, and does not drift. One Counterweight a day comes to know where the mountain came from, as the Warden's engineers of the Concord wrote it should be done, and it sinks a little each time. By spring, if the roster holds, it will come down to the Socket's shore at a walking pace." teaches ending_told.
  Observe end_over near party when midwinter(corrow) and overSocket(hightown) and not bitten(hightown) and not crashed(hightown) and not lost(hightown) and not grounded(hightown) and not knows(party, ending_told) "Hightown turns the year hanging over the Socket with its shadow on the water, a bowl above a bowl. One Counterweight a day is told where the mountain came from, and it is lower each morning. Nobody on the rim looks away from the lake now." teaches ending_told.
  Observe end_anchored near party when midwinter(corrow) and not overSocket(hightown) and not grounded(hightown) and not bitten(hightown) and not crashed(hightown) and not lost(hightown) and restingWeight(hightown) >= 1000 and not knows(party, ending_told) "Hightown rides out the turn of the year at the end of its Chain with enough of the tail on the ground to grip. It is still north of where it was, and the Socket is still ahead of it, and next winter's gales will have their say. But it is still in the Corrow, and still in the air, and still nobody's but its own." teaches ending_told.
  Observe end_slack near party when midwinter(corrow) and not overSocket(hightown) and not grounded(hightown) and not bitten(hightown) and not crashed(hightown) and not lost(hightown) and restingWeight(hightown) < 1000 and not knows(party, ending_told) "Hightown turns the year on a tail so light that the horn skips at every gust. One more cut, one cold night, one hard gale: everyone in Hornwake has done the sum by now, and nobody sleeps well." teaches ending_told.
}

data/adventures/let-one-remember/company:
Module corrow "Let One Remember" {
  Company party "Your company" of 3 at eighth_bend.
  Initially Set quantity(party, gold) to 60. Initially Set quantity(party, rations) to 3.
}

Module corrow "Let One Remember" {
  // The Corrow resolves a great deal on its way to the one road, and until now paid for none of it: a company that named
  // the Strays of Keld, caught a consul's secretary in a wrong face and learned how a mountain is brought down came out
  // of it no richer than one that walked through. These are the things the Corrow itself counts as done.
  Milestone m_strays "named the Strays of Keld, and gave each of them a place" worth 75 when namedStrays(keld).
  Milestone m_hollow "learned who Keld Hollow left in the grey" worth 25 when knows(party, hollow_missing).
  Milestone m_wrong_face "caught the consul's secretary in a face that was not his" worth 50 when knows(party, webb_wrong_face).
  Milestone m_webb "learned what Corin Webb is" worth 100 when knows(party, webb_is_stray).
  Milestone m_unsaid "learned what was let go in 412" worth 50 when knows(party, unsaid_is_name).
  Milestone m_method "learned how the mountain is to come down" worth 75 when knows(party, method_known).
  Milestone m_fragments "gathered the three fragments of the road" worth 75 when knows(party, road_fragments).
  Milestone m_prew "brought Absalom Prew back to his wife" worth 50 when knows(party, prew_reunited).
  Milestone m_road_ended "brought the road to its end" worth 200 when ended(beyond).
}

data/adventures/let-one-remember/hightow:
Module corrow "Let One Remember" {
  Description "Hightown: a granite bowl floating in and out of cloud, nine hundred people, half of them sworn not to know where they came from.".


  Place hightown_rock "the rock of Hightown" is site within hightown.
  Place summit "the summit of Hightown" is level within hightown_rock.
  Place under_summit "the halls under the summit" is level within hightown_rock.
  Place hoist_house "the hoist-house on the rim" is room within summit at 2, 2.
  Place rim_walk "the rim and the nets" is room within summit at 1, 2 outdoors.
  Place terraces "the terraces" is room within summit at 1, 1 outdoors.
  Place cradle_gallery "the cradle gallery" is room within under_summit at 0, 2 underground.
  Place unasked_chapel "the Unasked chapel" is room within summit at 2, 1.
  Place grounders_hall "the Grounders' hall" is room within under_summit at 0, 1 underground.
  Place charge_hall "the hall of the Charge" is room within summit at 1, 0 outdoors.
  Place archive_outer "the archive's outer room" is room within under_summit at 2, 0 underground.
  Place sealed_room "the sealed room" is room within under_summit at 3, 0 underground.

  Passage hoist_door "the hoist-house door" is door between hoist_house and rim_walk.
  Passage rim_steps "the terrace steps" is steps between rim_walk and terraces.
  Passage chapel_porch "the chapel porch" is doorway between terraces and unasked_chapel.
  Passage cistern_stair "the old cistern stair" is stair between terraces and grounders_hall.
  Passage charge_way "the summit path" is path between terraces and charge_hall.
  Passage archive_stair "the archive stair" is stair between charge_hall and archive_outer.
  Passage unasked_door "the door carved with the Unasked" is door between archive_outer and sealed_room.
  Passage cradle_stair "the Ondrek gallery" is stair between cradle_gallery and rim_walk taking 1 hour.
  Passage cradle_mouth "the gallery mouth over the cradles" is crawl between cable_cradles and cradle_gallery taking 20 minutes.

  Observe hoist_house_scene at hoist_house when true "The hoist-house: a winch the size of a mill-wheel, a crew of four in fog-wool, and an open door onto two and a half kilometres of air. Your head aches. Everyone's head aches, the first three days.".
  Observe rim_scene_h at rim_walk when not crashed(hightown) "The rim of Hightown. Fog-nets of rope and wool hang from every edge, hundreds of them, combing the cloud into stone gutters. Walking the rim in cloud is walking by sound. When the cloud parts, the whole Corrow is below you: the plateau, the black line of the furrow, Hornwake like a thumbprint, and the Well a dark eye far to the south.".
  Observe rim_socket at rim_walk when socketDistance(hightown) <= 2000 and not crashed(hightown) "When the cloud parts to the north there is a lake down there now, close, a bowl of clear water with ribs in it. People on the rim look at it, and look away, and some of them look at it again.".
  Observe terraces_scene at terraces when true "Terraces of barley stubble and bean-rows step down into the granite bowl, every wall dry-stone, every field the size of a room. Sheep with long oily fleeces graze between the cisterns. Halls are cut into the rock below.".
  Observe cradle_gallery_scene at cradle_gallery when true "An Ondrek gallery cut through the mountain's base, so old its walls have worn smooth. At one end it opens onto nothing at all, and the Chain.".
  Observe chapel_scene_h at unasked_chapel when true "A low chapel cut into the granite. No image, no altar: a blank wall, polished. The Unasked is carved over the door in Concord letters, and under it in March: WE DO NOT ASK. Benches. A girl of fifteen sits on one alone, frowning at the blank wall as if it owed her money.".
  Observe hall_scene at grounders_hall when true "A dry cistern made into a meeting hall: benches round the walls, lamps, a map of the Corrow painted on the floor with Hightown drawn on it in chalk and rubbed out and drawn again, further north each time. Three hundred people meet here. A few dozen are here now, talking low.".
  Observe charge_scene at charge_hall when true "The hall of the Charge: a ring of stone seats under the summit, and the charge-holders in them in grey, each with the name of what they keep stitched on the breast.".
  Observe archive_outer_scene at archive_outer when true "The archive's outer room: shelves of keepstone and racks of tally-chain in the cold dry air, two cots for the charge-holders who sleep here, and at the back a granite door carved with the Unasked, with a slot for a tally-chain bar where its lock should be.".
  Observe sealed_scene at sealed_room when true "The sealed room. Keepstones, faded but not blank in this cold; tally-chains, racks of them; and on a stone lectern the Concord's record of the Lift, plate after plate. You do not have to read it. You can already see the first plate's heading, cut in the stone above the lectern: a single long word, in Calvessan, which is a name.".

  // Who in Hightown can come to hold where it came from, and how many minds they are.
  Relation counterweight(group). Measure minds(group). Relation holdsOrigin(group).
  Person amberly "Speaker Amberly Vane" at unasked_chapel {
    Role "Speaker of the Charge, keeper of the sealed room's key". Ancestry human. Peaceable.
  }
  Person linnet "Linnet Vane" at unasked_chapel {
    Role "the Speaker's daughter, fifteen". Ancestry human. Peaceable.
  }
  Person aron "Aron Fennimore" at grounders_hall {
    Role "hoist-engineer, leader of the Grounders". Ancestry human. Peaceable.
  }
  Person grounders "the Grounders" at grounders_hall {
    Role "Hightown folk who think it is time to go home". Ancestry human. Numbers 6. Peaceable.
  }
  Person charge "the Charge" at charge_hall {
    Role "Hightown's council of charge-holders". Ancestry human. Numbers 5. Peaceable.
  }
  Topic charge_keep with charge "Ask the charge-holders what they keep" when true once {
    Says "The nearest turns her shoulder so you can read the word stitched on her breast: WELLS. 'Each of us keeps one thing for the whole rock, and keeps it whole,' she says. 'The wells. The nets. The hoist. The seed. The archive.' The others incline their heads as their charges are named. 'What none of us keeps is where we came from. That is the Unasked's.' She says the next words as a congregation says them, without thinking. 'We do not ask.'".
  }
  Person rimfolk "the people on the rim" at rim_walk {
    Role "net-menders and spinners, working the fog-nets". Ancestry human. Numbers 6. Peaceable.
  }
  Topic rimfolk_nets with rimfolk "Ask the net-menders about the fog-nets" when not crashed(hightown) once {
    Says "'Every drop on the rock comes off the cloud,' says a woman with a netting needle, not stopping. 'No springs up here, and the rain's mostly under us. The nets comb the cloud and the gutters take it to the cisterns.' She pulls a knot tight with her teeth. 'A dry month, we drink from the stores. Two, the Charge sits.' Further along the rim a man laughs, not happily. 'And three,' he says, 'we go home, says Aron Fennimore.'".
  }
  Initially Assert counterweight(amberly). Initially Assert counterweight(linnet). Initially Assert counterweight(grounders).
  Initially Assert counterweight(charge). Initially Assert counterweight(rimfolk). Initially Assert counterweight(aron).
  Initially Set minds(amberly) to 1. Initially Set minds(linnet) to 1. Initially Set minds(aron) to 1.
  Initially Set minds(charge) to 9. Initially Set minds(grounders) to 300. Initially Set minds(rimfolk) to 200.
  // Aron already holds it, with his sister and a friend: three thousand tonnes already in the tail's weight.
  Initially Assert holdsOrigin(aron).

  // Telling is acting. The Counterweight who comes to hold where the mountain came from gives it back a thousand tonnes.
  Action tell_origin(actor: group, listener: group, site: place) "Tell {listener} where Hightown came from" {
    Description "That the lake ahead is the hole the mountain left, and the mountain its cast. Whoever of Hightown holds that, gives the mountain back a little of its weight.".
    // The author's F12: the page asks before it is done.
    Grave "Told, it cannot be untold: whoever of Hightown holds it gives the mountain back some of its weight.".
    Requires able(actor) and company(actor) and at(actor, site) and at(listener, site) and counterweight(listener)
      and knows(actor, origin_known) and not holdsOrigin(listener) and not crashed(hightown) and not lost(hightown).
    Time 1.
    On success { Assert holdsOrigin(listener). Increase heard(hightown) by minds(listener). }
    Result "You tell it plainly: the lake at the foot of the Teskarn, the ribs of its bowl, the ribs of the mountain's underside, the Drag that runs between. You watch it go in. Under your feet the granite does nothing you can feel, and everything.".
  }
  Event amberly_holds near amberly when holdsOrigin(amberly) "Speaker Vane has not moved while you spoke. When you stop she says, very evenly, 'You have done a thing to me that I cannot undo, and that nobody on this mountain may ever undo again.' She looks at the blank wall. 'Thank you for doing it to me and not to them.' She does not ask you to leave. She does not need to." then {
    Assert grieved(amberly).
  }
  Relation grieved(group).
  Event linnet_holds near linnet when holdsOrigin(linnet) "Linnet listens with her whole face. At the end she goes to the chapel door and looks north, where the cloud is, and comes back. 'Down there,' she says. 'It's been down there the whole time.' Then, frightened for the first time: 'Am I heavier? Is that me?'" then {
    Assert grieved(linnet).
  }
  Event grounders_hold near grounders when holdsOrigin(grounders) "It goes round the hall the way fire goes round a dry field: from you to the ones who heard, from them to the benches, from the benches out of the door. Aron Fennimore is on his feet shouting for quiet, and there is no quiet. Under the hall the mountain groans like a ship." then {
    Assert grieved(grounders).
  }
  Event rimfolk_hold near rimfolk when holdsOrigin(rimfolk) "The net-menders put down their needles one by one. Someone points north, at the lake, and everyone looks, and this time nobody looks away." then {
    Assert grieved(rimfolk).
  }

  // Speaker Vane and the Unasked.
  Topic amberly_unasked with amberly "Ask Speaker Vane about the Unasked" when true once {
    Says "'It is forbidden to ask, say or learn where the mountain came from,' says the Speaker. 'Our elders taught that the ground was a figure of speech. It is not; I have been down the hoist; I have stood on it.' She smiles slightly. 'But the doctrine was never about the ground. It was about the mountain. We have survived two thousand six hundred years by not knowing one thing. I see no reason to start knowing it now, in a hurry, because a merchant is short of iron.'".
  }
  Topic amberly_anchor with amberly "Ask Speaker Vane what she means to do about the drift" when true once {
    Says "'Anchor her,' says the Speaker. 'There is a link of iron lying finished at the bottom of the Well, made for the Chain and never fitted. Hung on the tail it would add its weight to the ground. Clemence Ninepan will sell it to us at a price we cannot pay, and has no way to lift it.' She folds her hands. 'I am working on the price.'".
  }
  Topic linnet_asks with linnet "Ask Linnet Vane what she is frowning at" when true once {
    Says "'The wall,' says Linnet. 'It's blank so we don't ask. But I've been down to Hornwake twice, and everybody down there asks everything.' She lowers her voice. 'I want to see the sea. Mother says the sea is a figure of speech too.' She looks at you sidelong. 'Is it?'".
  }

  // Aron Fennimore and the Grounders.
  Topic aron_water with aron "Ask Aron Fennimore why the Grounders want to go down" when true once {
    Says "'The water bill,' says Aron. 'The spring the mountain carried up is failing, and has been for a century. We buy water by the hoist with wool, and the wool will not stretch another generation.' He taps the chalk on the floor. 'My grandmother was born up here and died up here and never once stood on soil. I'd like my son to have the choice.' He does not say what he suspects about the lake. You can see him not saying it.".
  }
  Relation roster(group). Measure nextRoster(place).
  Topic aron_method with aron "Tell Aron Fennimore what the Concord Warden's engineers cut in the Drag: let one remember at a time" when knows(actor, method_known) and not roster(aron) and not crashed(hightown) and not lost(hightown) {
    Says "Aron sits down on a bench as if his knees had gone. 'One at a time,' he says. 'Not the hall. Not a sermon from the rim.' He laughs, once, with no breath in it. 'I had the speech written. I was going to tell them all, the day the lake came under us.' He gets up and finds a pencil. 'A roster, then. One a day. Who first? Not me, I'm done, and not my sister. Someone who'll keep it.' He is already writing names. Then he remembers, and digs twenty silver out of the hall's box for you, and will not hear a word against it.".
    On discuss { Assert roster(aron). Set nextRoster(hightown) to watch(clock) + 144. Increase quantity(actor, gold) by 20. }
  }
  Rule roster_turns when roster(aron) and watch(clock) >= nextRoster(hightown) and heard(hightown) < 150 and not crashed(hightown) and not lost(hightown) {
    Increase heard(hightown) by 1. Set nextRoster(hightown) to nextRoster(hightown) + 144.
  }
  // Left alone, Aron finds the station-56 chain himself in the third week, and starts a roster of his own.
  Rule aron_finds_it when watch(clock) >= 3024 and not roster(aron) and not crashed(hightown) and not lost(hightown) and not toldAll(aron)
    says "Word comes along the furrow: Aron Fennimore of Hightown was out on the Drag yesterday with a Keld pilgrim, at the Askew gatepost, and paid the farmer twice over, and went back up the hoist white as wool." {
    Assert roster(aron). Set nextRoster(hightown) to watch(clock) + 144.
  }
  // And when the lake comes under them with too few holding, the Grounders gather on the rim to tell everyone to look
  // down. It takes them two hours. Someone who stands in front of them with the engineers' words can stop it.
  Relation toldAll(group). Relation gathering(group). Relation steadied(group). Measure tellAt(place).
  Rule grounders_gather when overSocket(hightown) and heard(hightown) < 20 and not toldAll(aron) and not gathering(grounders)
    and not steadied(grounders) and not crashed(hightown) and not lost(hightown)
    says "Bells ring in Hightown's hoist-houses, all three, and go on ringing. The Grounders are going up to the rim: the lake is under them and the roster is too slow, and Aron Fennimore has decided that if the mountain is going home it will go home now." {
    Assert gathering(grounders). Set tellAt(hightown) to watch(clock) + 12. Assert at(grounders, rim_walk). Assert at(aron, rim_walk).
  }
  Observe rim_gathering at rim_walk when gathering(grounders) "The rim is full of people. Three hundred Grounders stand along the nets with the lake below them, and more are coming up the terrace steps. Aron Fennimore is on a water-cistern's lid with a paper in his hand, waiting for the bells to stop. Nobody has looked down yet. Everybody is about to.".
  Action steady_grounders(actor: group, site: place) "Stand up beside Aron Fennimore and give the Grounders the engineers' words: let one remember at a time" {
    Description "Three hundred at once will drop the mountain on the shore. One a day will bring it down.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, rim_walk) and gathering(grounders)
      and knows(actor, method_known).
    Time 2.
    On success { Retract gathering(grounders). Assert steadied(grounders). Assert roster(aron). Set nextRoster(hightown) to watch(clock) + 144. Assert at(grounders, grounders_hall). Assert at(aron, grounders_hall). }
    Result "You climb up beside him. You have to shout over the bells. You tell them what the Concord Warden's engineers cut into the Drag two thousand six hundred years ago, in their own words, and Aron Fennimore reads the chain's words out after you from his paper, slowly, and then he tears up his speech. 'One a day,' he says. 'Who's first?' Three hundred people turn their backs on the lake, one by one, and go down the terrace steps without looking.".
  }
  Rule grounders_tell_all when gathering(grounders) and watch(clock) >= tellAt(hightown) and not crashed(hightown) and not lost(hightown)
    says "The bells stop. On Hightown's rim three hundred people look down at the lake, and Aron Fennimore tells them what it is, and they understand; and on the terraces behind them the people who came out to see what the bells were for look down too." {
    Retract gathering(grounders). Assert toldAll(aron). Increase heard(hightown) by 500.
  }

  // Linnet, told, keeps the roster.
  Rule linnet_keeps when roster(aron) and holdsOrigin(linnet) and at(linnet, unasked_chapel) { Assert at(linnet, grounders_hall). }
  Observe linnet_roster at grounders_hall when roster(aron) and at(linnet, grounders_hall) "Linnet Vane sits at Aron's table with the roster book open, writing one name a day in a careful hand, and crossing nobody out.".

  // Hightown comes down whole if enough of it holds, and not half: grounded, at a walking pace.
  Relation grounded(place).
  Rule hightown_grounds when heard(hightown) >= 150 and heard(hightown) < 450 and not grounded(hightown) and not crashed(hightown) and not lost(hightown)
    says "Hightown is coming down. Not falling: settling, the way a feather settles, but a feather a kilometre across, all afternoon, while every soul in Hornwake stands in the furrow with their mouths open. The Chain piles up in loops under it. At dusk it touches, and the ground takes it with a long sigh, and its lights stay lit." {
    Assert grounded(hightown).
  }
  Observe end_grounded_shore near party when grounded(hightown) and overSocket(hightown) and not knows(party, ending_told) "Hightown sits in the Socket's south shore as a stone sits in its own print in mud, tilted a little, its terraces whole. The lake has risen round its north side. Its people walk down off the rim onto the shore of the lake their mountain left, and stand on it." teaches ending_told.
  Observe end_grounded_plain near party when grounded(hightown) and not overSocket(hightown) and not knows(party, ending_told) "Hightown sits on the open plateau short of the Socket, whole, with its Chain piled round it in great loops. It came down where it happened to be. The Grounders say it is near enough; the Unaskers say nothing at all; and Hightown, for the first time in two thousand six hundred years, does not move in the wind." teaches ending_told.

  // Cassen Vane's notebooks of 2602, in the archive's outer room.
  Discovery cassen_notes "Cassen Vane's notebook of 2602, in his own hand: 'They tell me that on the third day of the strangers I stood at the cradles with the Saltreach woman and said the underside was the shape of the lake at the massif's foot, and that the mountain dropped four metres in a minute, and rose three again when she took the minute out of me. I have it only from my own hand. I have measured the spring falling for six years, and I cannot remember a day of it.' Under it, later, in a firmer hand: 'One knowing it was enough to move her. One.'" {
    Source cassen_book "Cassen Vane's notebook of 2602" at archive_outer readable by party.
  }
  Observe cassen_and_drag near party when knows(party, cassen_notes) and knows(party, chart_seen) and not knows(party, origin_known) "Cassen's notebook and the Socket chart sit side by side in your head: the lake at the massif's foot; the underside; four metres for one man knowing. The lake is the mountain's place." teaches origin_known.

  // The charge-holders sleep in the outer room; the sealed door's lock is a tally-chain bar.
  Person keepers "two charge-holders" at archive_outer {
    Role "charge-holders sleeping before the sealed door". Ancestry human. Numbers 2. Peaceable.
  }
  Topic keepers_door with keepers "Speak to the charge-holders by the sealed door" when state(unasked_lock, shut) once {
    Says "One of them opens an eye, sees that you are not on fire, and shuts it again. The other says, without properly waking: 'Archive's shut. Nobody goes through that door. Nobody's asked to.' He turns over toward the wall and pulls the blanket up. 'That's the point of it.'".
  }
  Thing unasked_lock "the tally-chain bar of the sealed door" on unasked_door {
    State shut blocking "The granite door carved with the Unasked is shut. Its lock is a slot for a tally-chain bar.".
    State open "The granite door carved with the Unasked stands open.".
  }
  Action read_unasked_lock(actor: group, site: place) "Ask Teshen to read the sealed door's lock in the dark while the charge-holders sleep" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, archive_outer) and travelsWith(teshen, actor)
      and dark() and state(unasked_lock, shut).
    Time 2.
    On success { Assert state(unasked_lock, open). }
    Result "Teshen kneels at the slot in the dark with her fingers on the bar, and her breath goes short. 'It's the Unasked,' she whispers. 'The whole doctrine, in iron. You open it by saying it.' She sets the shapes one by one. The charge-holders sleep on. The door moves.".
  }
  Discovery mountain_name "The mountain's name, cut over the lectern in the sealed room: a single long Calvessan word, the name of the tor at the Teskarn's foot that was lifted in 51 AB and is still in the Lap.".
  Observe name_seen at sealed_room when not knows(party, mountain_name) "You read the name before you can stop yourself. It is long and liquid and it means nothing to you. To anyone born on this mountain it would mean everything at once." teaches mountain_name.
  Observe method_sealed at sealed_room when not knows(party, method_known) "On the lectern, the last plate of the Concord's record is laid on top, faded but legible to a hand: the engineers' note on how to bring the mountain down if ever they must. 'Let one remember at a time.'" teaches method_known.
  Action speak_name(actor: group, site: place) "Say the mountain's name aloud on the rim, where everyone can hear" {
    Description "A name is the strongest relation there is.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, rim_walk) and knows(actor, mountain_name)
      and not crashed(hightown) and not lost(hightown).
    Time 0.
    On success { Increase heard(hightown) by 600. }
    Result "You say it. It is only a word. Every head on the rim turns toward you at once, and every face has the same look on it, the look of someone who has just remembered where they left something.".
  }
}

data/adventures/let-one-remember/hornwak:
Module corrow "Let One Remember" {
  Description "Hornwake, the town on wheels round the horn; the furrow and the Drag across the plateau; the Socket; and the Chain up to Hightown.".

  Place cookhouse "the cookhouse" is building within hornwake.
  Place watch_hut_b "the Horn Watch" is building within hornwake.
  Place pavilion_b "the Hartmark pavilion" is building within hornwake.

  Place horn_foot "the horn" is room within hornwake at 1, 0.
  Place hoist_feet "the hoist-feet" is room within hornwake at 2, 0.
  Place wagons "the wagon horseshoe" is room within hornwake at 1, 1.
  Place tail "the tail" is room within hornwake at 0, 0.
  Place cook_room "the cookhouse" is room within cookhouse at 0, 1.
  Place watch_hut "the Horn Watch hut" is room within watch_hut_b at 2, 1.
  Place pavilion "the Hartmark pavilion" is room within pavilion_b at 1, 2.

  Place askew_gate "the gate of the Askew farm" is room within plateau at 1, 2.
  Place hesk_yard "the farm below Hesk Dene" is room within plateau at 1, 1.
  Place toppled "the toppled stations" is room within plateau at 2, 1.
  Place furrow "the furrow" is room within plateau at 1, 0.

  Place socket_south "the south shore of the Socket" is room within socket_country at 1, 1.
  Place survey_station "the Lusk survey station" is room within socket_country at 0, 1.
  Place socket_shelf "the bollard shelf" is room within socket_country at 1, 0.
  Place socket_north "the north shore of the Socket" is room within socket_country at 2, 0.

  Passage furrow_road "the furrow road" is track between furrow_end and askew_gate taking 40 minutes.
  Passage drove_to_hesk "the drove road past Hesk Dene" is track between askew_gate and hesk_yard taking 90 minutes.
  Passage hesk_to_furrow "the furrow north of Hesk Dene" is track between hesk_yard and furrow taking 30 minutes.
  Passage toppled_way "the line of the Drag" is path between hesk_yard and toppled taking 30 minutes.
  Passage furrow_to_town "the end of the furrow" is track between furrow and tail taking 30 minutes.
  Passage tail_way "the tail" is path between tail and horn_foot.
  Passage horn_hoists "the way to the towers" is path between horn_foot and hoist_feet.
  Passage horn_wagons "the horseshoe" is path between horn_foot and wagons.
  Passage cook_door "the cookhouse door" is door between wagons and cook_room.
  Passage watch_door "the Horn Watch door" is door between hoist_feet and watch_hut.
  Passage pavilion_flap "the pavilion flap" is doorway between wagons and pavilion.
  Passage socket_track "the track north to the Socket" is track between horn_foot and socket_south taking 1 hour.
  Passage station_path "the shore path" is path between socket_south and survey_station taking 20 minutes.
  Passage shelf_path "the granite shelf" is path between socket_south and socket_shelf taking 20 minutes.
  Passage north_path "the north shore" is path between socket_shelf and socket_north taking 40 minutes.

  // ── Hornwake ─────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe horn_scene at horn_foot when not lost(hightown) and not crashed(hightown) "A black curve of metal the size of a barn lies half buried in the end of the furrow it ploughs, and from it the Chain goes up: one link, the next, the next, smaller and smaller into the sky until you cannot see it go into the cloud. Round the horn the town stands in a horseshoe of wagons, sledges and timber frames. The horn is cold. Nothing grows within ten metres of it, and a magic light held near it gutters and dies.".
  Observe horn_skips at horn_foot when restingWeight(hightown) < 2000 and restingWeight(hightown) > 0 and not bitten(hightown) "When the wind gusts the horn moves: a lurch, a grinding, a skip of a metre along its furrow, and then it settles. People in the horseshoe stop talking each time it does, and start again.".
  Observe horn_bitten at horn_foot when bitten(hightown) "The horn has gone into the ground to the root of its curve and does not move in any wind. Above it the Chain hangs nearly plumb.".
  Observe horn_gone at horn_foot when lost(hightown) "Where the horn lay there is a hole the shape of a horn, and frozen clods round it, and the end of the furrow. Nothing comes down out of the sky.".
  Observe horn_slack at horn_foot when crashed(hightown) "The Chain lies slack across the plateau to the north, link after link in the frozen grass, as far as you can see.".
  Relation towerFell(place).
  Rule tower_falls when galeBlown(gale_one) and not towerFell(hornwake)
    says "In the first great gale the north hoist-tower at Hornwake goes over: it leans, and the crew in the winch-house shout, and then it is down across the wagons in a long crash of timber, and two people who were holding its guy-ropes are under it." {
    Assert towerFell(hornwake).
  }
  Observe tower_down at hoist_feet when towerFell(hornwake) "Two hoist-towers stand where three stood. The third lies in sections by the wagons, and two names are chalked on its foot-beam.".
  Observe hoists_scene at hoist_feet when not towerFell(hornwake) "Three timber hoist-towers stand beside the Chain, each with a winch-house and a counterweight basket, and between them a daily market on trestles: rope, coal, water in casks, dried mutton coming down, fog-wool coming down in great oily bales. A woman with a griddle sells oatcakes.".
  Observe wagons_scene at wagons when true "The horseshoe of Hornwake: wagons with their wheels chocked, canvas, timber frames that come apart in sections, chickens in crates. Every household keeps one ear on the horn.".
  Observe tail_scene at tail when not lost(hightown) and not crashed(hightown) "Behind the horn the tail lies on the ground: seven great links like a felled tree, each eighteen metres long and two thick, black, crusted orange where files have been at them. On the last of them a crew of runners works in a shed of canvas, filing. The sound of it never stops.".
  Observe cook_scene at cook_room when true "A long tent with a stove at each end, the stovepipes still warm from the last shifting day. Every bench is bolted to a pair of runners so that it can be dragged, and the oldest are worn bright underneath. Hornwake eats here.".
  Observe watch_scene at watch_hut when true "An instrument hut: a brass sighting-glass on a stone pier sunk deep into the furrow, a lamp, and books, a whole shelf of them, every one the same: dawn bearings of the horn, one line a day.".
  Observe pavilion_scene at pavilion when true "A good pavilion of grey canvas under a grey banner, a brazier, a camp desk, a strongbox, and maps of the Corrow pinned up with Hightown drawn on them in red, further north each map. The newest is pinned lowest, as though nobody wanted it at eye height.".

  // Ordinary Life (Player Portfolio): a shifting day after every gale.
  Observe shifting_day at wagons when galesBlown(hightown) >= 1 and watch(clock) - lastGale(hightown) < 144 "The move-bell went before dawn: three strokes, then three. Overnight the horn has dragged north; you can see where: a raw trench of turned earth, black at the bottom, ending at the great dark curve of it lying half buried with its chain behind it. Hoist crews are lowering the first tower in sections, calling numbers. Children carry chickens in baskets. A Registry clerk with a measuring chain walks the new stretch of furrow, and three families follow him, arguing about who planted first.".
  Observe shifting_oatcakes at hoist_feet when galesBlown(hightown) >= 1 and watch(clock) - lastGale(hightown) < 144 "By noon the town has stood up again further north, the wagons in the same horseshoe, the cookhouse at the same corner. The woman who sells oatcakes has her griddle going. She charges a bit more than yesterday. 'Always does, on a shifting day,' says the man behind you in the queue. 'She'll be cheaper by Thursday. Unless it blows.'".

  Person bet "Bet Mawby" at hoist_feet {
    Role "oatcake seller". Ancestry human. Peaceable.
    Sells rations for 1 coin from 20.
  }
  Person cook "Hal Brack" at cook_room {
    Role "keeper of the cookhouse". Ancestry human. Profession innkeeper. Peaceable.
  }
  Topic cook_shifting with cook "Ask Hal Brack how the cookhouse keeps up with the horn" when true once {
    Says "'Two stoves,' says Hal Brack, and bangs a ladle on the nearer. 'One at each end. On a shifting day one goes on the first cart, and the other stays lit till the wagons roll, and by noon there's a town again a mile north and I'm frying in it.' The ladle points at the stovepipes. 'Move-bell goes before dawn, three and three. Hornwake's never missed a breakfast for the horn yet, and it won't while this tent stands.'".
  }
  Person wakefolk "the people of Hornwake" at wagons {
    Role "Hornwake households". Ancestry human. Numbers 5. Peaceable.
  }
  Topic wakefolk_tail with wakefolk "Ask the people of Hornwake about cutting the tail" when true once {
    Says "Everyone has an opinion. 'Cut it and let her go north,' says a man mending a harness. 'The Hartmark can have her.' 'The runners say there's twenty links in it before she notices,' says a woman, 'and the runners would know.' 'The runners would say so,' says someone else. A child says the horn is a dragon's tooth and is told to hush.".
  }

  // The hoists. Lene Tallow runs them; the company rides if it is in the hoist book.
  Person lene "Lene Tallow" at hoist_feet {
    Role "hoistmaster of Hornwake". Ancestry human. Peaceable.
  }
  Thing hoist_book "the hoist book" on hoist_ride is scenery {
    State unpaid blocking "The cradles go up for whoever is in Lene Tallow's hoist book for the season.".
    State entered "Your names are in the hoist book for the season.".
  }
  Passage hoist_ride "the hoist" is shaft between hoist_feet and hoist_house taking 6 hours opening when not lost(hightown) and not crashed(hightown) "There is nothing for the cradles to go up to.".
  Action enter_book(actor: group, site: place) "Pay Lene Tallow twelve silver to enter the company in the hoist book for the season" {
    Requires able(actor) and company(actor) and at(actor, site) and at(lene, site) and quantity(actor, gold) >= 12
      and state(hoist_book, unpaid).
    Time 1.
    On success { Decrease quantity(actor, gold) by 12. Assert state(hoist_book, entered). }
    Result "Lene writes your names in a thick book with a stub of lead, without looking up. 'Six hours up, sit in the middle, don't lean on the rail when it swings. Up in the morning, down by dark.'".
  }
  Topic lene_hoists with lene "Ask Lene Tallow about the hoists" when true once {
    Says "'Two tonnes a load, a dozen loads a day a tower, when the wind lets us,' says Lene. 'Water and coal and food up; wool and rope and mutton down.' She squints up the Chain. 'Funny thing. The riggers say every load we send up, she sits a hand lower at the cradles till it's unloaded. Every bale of wool we bring down, she rides higher.' She shrugs. 'Weight's weight, I suppose. Even up there.'".
    On discuss { Assert knows(actor, hoist_weighs). }
  }
  Observe ballast_thought near party when knows(party, hoist_weighs) and knows(party, cut_limit) and not knows(party, ballast_known) "The two things sit side by side in your head and then fit together. A tonne hauled up the hoist and left in Hightown weighs on the Chain exactly as a tonne of tail on the ground does. Stone sent up instead of wool sent down: five hundred and fifty loads would do what a link of iron does, and nobody has to cut anything, or forge anything, or lift anything out of the Well." teaches ballast_known.
  Relation ballasting(group). Measure nextBallast(place).
  Topic lene_ballast with lene "Put it to Lene Tallow: send stone up the hoists and leave it there, as ballast" when knows(actor, ballast_known) and knows(actor, cut_limit) and not ballasting(lene) {
    Says "Lene hears you out, and then she takes the stub of lead from behind her ear and does the sum on the back of the hoist book, twice. 'Eleven hundred tonnes,' she says. 'Thirty-six loads a day if I run all three towers and the weather's kind. A month.' She looks at the tail, where the files are going. 'Stone's cheap. Quarry's a mile off. Hightown won't thank me for it; they'll have to stack it somewhere.' She closes the book. 'I'll start in the morning. Somebody'd better tell the runners to stop, though, or I'm filling a bucket with a hole in it.'".
    On discuss { Assert ballasting(lene). Set nextBallast(hightown) to watch(clock) + 144. }
  }
  Rule ballast_day when ballasting(lene) and watch(clock) >= nextBallast(hightown) and not lost(hightown) and not crashed(hightown) {
    Increase ballast(hightown) by 72. Set nextBallast(hightown) to nextBallast(hightown) + 144.
  }
  Observe ballast_going at hoist_feet when ballasting(lene) and not crashed(hightown) and not lost(hightown) "The cradles are going up loaded with quarry stone, and coming down empty but for the wool. The market thinks Lene Tallow has gone mad, and says so, and buys its oatcakes anyway.".

  // The Horn Watch.
  Person fen "Old Fen Hadley" at watch_hut {
    Role "senior of the Horn Watch". Ancestry human. Peaceable.
  }
  Discovery horn_bearing "Fen Hadley's bearing books: forty years of dawn bearings on the horn. Gale or calm, it leans the same way, north-north-east and eleven degrees up, toward something; and in forty years the bearing has crept half a degree. Whatever it points at is moving." {
    Source bearing_books "Fen Hadley's bearing books" at watch_hut readable by party.
    Known by fen.
  }
  Topic fen_horn with fen "Ask Old Fen Hadley what the horn points at" when true once {
    Says "'Where the star went,' says Fen, as if you had asked what colour the sky is. 'It pulls. Not much. A few tonnes, always the same way, north-north-east and up. You can feel it if you sit on the horn on a still night. The young ones won't.' He pats his books. 'Half a degree in forty years. It's moving, whatever it is. I'll not live to see where.'".
  }

  // The runners, and who pays them.
  Person ruth "Ruth Teake" at tail {
    Role "master of the chain-runners". Ancestry human. Calling thief. Level 3. Peaceable.
  }
  Person runners "the chain-runners" at tail {
    Role "a crew filing the last link of the tail". Ancestry human. Calling thief. Numbers 4. Peaceable.
  }
  Relation filing(group). Measure linkDue(place). Relation paying(group).
  Initially Assert filing(ruth). Initially Assert paying(esk). Initially Set linkDue(hightown) to 2016.
  Rule link_falls when filing(ruth) and watch(clock) >= linkDue(hightown) and not lost(hightown) and not crashed(hightown)
    says "Up on the plateau a sound goes through the ground like a dropped bell: the runners have filed through a link of the tail, and it has fallen away from the Chain." {
    Decrease tailLinks(hightown) by 1. Assert linkCut(hightown). Assert cutWatched(hightown).
  }
  Relation linkCut(place). Relation cutWatched(place).
  Rule next_link_paid when linkCut(hightown) and paying(esk) { Retract linkCut(hightown). Set linkDue(hightown) to watch(clock) + 1440. }
  Rule next_link_unpaid when linkCut(hightown) and not paying(esk) { Retract linkCut(hightown). Set linkDue(hightown) to watch(clock) + 4320. }
  // A runner's apprentice told, the Esk bonus withdrawn: the next link takes the full thirty days.
  Rule bonus_withdrawn when filing(ruth) and not paying(esk) and linkDue(hightown) < watch(clock) + 2880 and withdrawnFrom(esk) {
    Set linkDue(hightown) to linkDue(hightown) + 1440. Retract withdrawnFrom(esk).
  }
  Relation withdrawnFrom(group).
  Observe rose_after_cut at horn_foot when cutWatched(hightown) and not knows(party, tail_light) "Everyone in Hornwake is outside, looking up. Since the link fell, Hightown has risen: twenty metres, the hoist crews say, from the way the cradles hang. When the wind gusts the horn lifts clear of the ground for a heartbeat and comes down with a sound like a door." teaches tail_light.
  Discovery tail_light "When a link of the tail fell, Hightown rose twenty metres and the horn began to lift in the gusts: the tail is very nearly all that holds the mountain down.".
  Topic ruth_runners with ruth "Ask Ruth Teake about cutting the tail" when true once {
    Says "'One link a year,' says Ruth. 'Two this winter, with the Hartmark bonus. Somebody has to feed Hornwake, and it isn't Hightown.' She rubs her hands, which are grey to the wrist. 'My grandfather said there's twenty links in it before she notices. He was a runner forty years.' She looks up the Chain, and away. 'Sixty-one and sixty-two have started talking to me when I climb. I don't like what they say.'".
  }
  Topic ruth_limit with ruth "Tell Ruth Teake what the Registry reckons" when knows(actor, cut_limit) and filing(ruth) {
    Says "Ruth listens with her arms folded. When you say two, she unfolds them. 'Not twenty,' she says. 'Two.' She looks at the shed on the last link, where the files are going. 'That's what Sixty-two said. I thought he was mad.' She puts two fingers in her mouth and whistles, and the filing stops, and the silence on the tail is like a held breath. 'Downtools,' she says. 'Till I say.' Then, to you, quietly: 'Who's going to tell the Hartmark man?'".
    On discuss { Retract filing(ruth). }
  }
  Observe tail_quiet at tail when not filing(ruth) and not lost(hightown) and not crashed(hightown) "The runners' shed on the last link is shut. Their files hang on a nail.".

  // Esk of Harrow, the Hartmark's envoy.
  Person esk "Esk of Harrow" at pavilion {
    Role "envoy of the Hartmark". Ancestry human. Calling warrior. Level 5. Peaceable.
  }
  Topic esk_mountain with esk "Ask Esk of Harrow what the Hartmark wants with Hightown" when true once {
    Says "'A fortress the mage-lords cannot touch,' says Esk, pleasantly, pouring you something. 'My king has enemies with better mages than his. A mountain on a chain of iron that no spell will bite, drifting gently north into his country on the winds God sends, is an answer to a prayer.' He smiles. 'I pay the runners a little to help the winds. Nobody is harmed. It is a free country; I am told so daily.'".
  }
  Topic esk_limit with esk "Tell Esk of Harrow what the Registry reckons" when knows(actor, cut_limit) and paying(esk) {
    Says "Esk sets the cup down very carefully. 'Into the sky,' he says. 'Not north. Up.' For a moment he is only a tired man with two daughters at home. 'Then I stop. Of course I stop. I'll send to Ruth Teake tonight.' He looks at the red-inked maps on his wall a long time. 'And you are the only ones who know this?' It is a courteous question, and he is already thinking about what else the answer is worth.".
    On discuss { Retract paying(esk). Assert withdrawnFrom(esk). }
  }

  // ── The plateau ──────────────────────────────────────────────────────────────────────────────────────────────────
  Observe furrow_scene at furrow when true "The furrow: a trench three metres deep and ten wide running north across the plateau, its floor black and turned. Behind Hornwake it is planted in strips, oats and turnips, every strip with a stake and a name on it.".
  Observe askew_scene at askew_gate when true "The gatepost of the Askew farm is a granite bollard as tall as a man, with a gate hung on iron pins driven into its side. On the side facing the drove road there is a recess, and in the recess, rusted almost black, a chain of small iron links riveted at both ends.".
  Observe hesk_scene at hesk_yard when true "A farm with a stone yard and a gate onto the drove road. Hesk Dene, a grassy hollow, opens behind it, and beyond the hollow the furrow goes by, raw and black.".
  Observe toppled_scene at toppled when true "Here the horn went through the line of the Drag two winters ago and knocked down nine of its bollards like skittles. They lie in and beside the furrow, granite, each with its recess, and in the recesses the tally-chains, rusty, still riveted.".

  // A First Anomaly (Player Portfolio): Tip, at the gate.
  Person granny "old Mother Sallow" at hesk_yard {
    Role "the farmer's mother, ninety, shelling beans". Ancestry human. Peaceable.
  }
  Person ned "Ned Sallow" at hesk_yard {
    Role "farmer below Hesk Dene". Ancestry human. Peaceable.
  }
  Person tip "Tip" at hesk_yard {
    Role "a black-and-white sheepdog, grey in the muzzle". Species dog.
  }
  Event tip_returns at hesk_yard when at(party, hesk_yard) "You stop for water. The farmer's mother is sitting on the step shelling beans, and does not look up. There is a dog at the gate: black and white, grey in the muzzle, sitting the way a sheepdog sits when it has been told to wait. It is looking at the door. 'Is he yours?' you ask. The old woman looks up at last. She looks at the dog, and then at the grey in its muzzle, and the beans go still in her lap. 'That's Tip,' she says. 'That's my grandmother's dog.' She puts the bowl down. 'He died before I was born. She used to tell me about him.' The dog gets up when she says his name, and comes to her, and puts his head in her lap. Her son comes out of the barn, sees it, and swears under his breath. 'Another Return,' he says to you, as though you had asked. 'Third on this road this autumn. Don't mention it in the village. They'll want to put him on the Nail.'" then {
    Assert returnSeen(party).
  }
  Relation returnSeen(group).
  Topic ned_returns with ned "Ask Ned Sallow about the Returns" when returnSeen(actor) once {
    Says "'Things that were lost and not quite gone,' says Ned. 'The old people say the other place is going away from us, and it's dropping what it had on the way out.' He watches his mother with the dog. 'What comes back whole is a Return. What comes back wrong is a Stray, and you don't want one of those near your house. They'll have the house off you.'".
  }

  // A Meaningful Discovery (Player Portfolio): station 56 of the Drag, in Jory Askew's gatepost.
  Person jory "Jory Askew" at askew_gate {
    Role "farmer, leaning on his gate". Ancestry human. Peaceable.
  }
  Relation gatePaid(group).
  Topic jory_gate with jory "Ask Jory Askew about his gatepost" when true once {
    Says "'Concord stone,' says Jory. 'Whole line of them, all the way to the lake. My grandfather hung the gate on it.' He looks at you, and at the chain in the recess. 'Keld come every spring and read them aloud, all sixty-one. They want to read mine, they pay. It's my gatepost.'".
  }
  Action pay_jory(actor: group, site: place) "Pay Jory Askew five silver for leave to read his gatepost" {
    Requires able(actor) and company(actor) and at(actor, site) and at(jory, site) and quantity(actor, gold) >= 5 and not gatePaid(actor).
    Time 0.
    On success { Decrease quantity(actor, gold) by 5. Increase quantity(jory, gold) by 5. Assert gatePaid(actor). }
    Result "Jory pockets it without counting. 'Read away,' he says. 'Whatever it says, it's still my gatepost.'".
  }
  Discovery method_known "The anchor tally of the Drag, station 56, in the hand of the Concord Warden's engineers: how they would bring the mountain down if ever they had to. Not all at once. Let the mountain's own people come to know its place one at a time, and it will come down as slowly as they do. 'Let one remember at a time.'".
  Action read_station(actor: group, site: place) "Ask Teshen to read the chain in the gatepost" {
    Description "Link-script, read by touch. A Keld reads it as you read print.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, askew_gate) and travelsWith(teshen, actor)
      and gatePaid(actor) and not knows(actor, method_known).
    Time 2.
    On success { Assert knows(actor, method_known). }
    Result "Teshen runs her fingers along the chain with her eyes closed, the way you would read a line of print. Her lips move. 'It's a long one,' she says. 'Engineers, not a tow-crew. Different hand.' She reads further. Her fingers stop, then go back, then go over the same six links again. 'What?' 'It says how to bring it down.' She opens her eyes and looks north, where the thread of the Chain goes up into the cloud. 'If they ever had to. It's kept, not let. They saw it done, or they did it.' She puts her fingers back on the chain and reads it aloud in the old speech, then in March: 'Let one remember at a time.'".
  }

  // The toppled stations: the Drag read where the horn knocked it down. The tow from the lake, day by day.
  Discovery origin_known "Hightown came out of the Socket. The lake at the Teskarn's foot is the hole the mountain left when it was lifted, and the mountain's underside is that hole's exact cast.".
  Action read_toppled(actor: group, site: place) "Ask Teshen to read the chains of the toppled stations" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, toppled) and travelsWith(teshen, actor)
      and not knows(actor, origin_known).
    Time 3.
    On success { Assert knows(actor, origin_known). }
    Result "Teshen goes from bollard to bollard along the furrow, kneeling at each, reading. 'Station thirty-three,' she says. 'Three anchors dragging. A storm.' Thirty-four, thirty-five. 'Every one counts from the same place. Days out from the lake. From the shore of the lake under the Teskarn, where the mountain stood.' She sits back on her heels and looks north, at the dark thing in the sky, and then further north, where the lake is. 'They towed it from there,' she says. 'From the Socket. It's the Socket's.' She says it quietly, and you are both glad there is nobody from Hightown in the furrow.".
  }

  // ── The Socket ───────────────────────────────────────────────────────────────────────────────────────────────────
  Observe socket_scene at socket_south when true "The Socket: a lake a kilometre and more across in a bowl of bare ribbed granite at the foot of the Teskarn, so clear you can see the ribs go down and down into blue and then into black. Nothing lives in it. On the shore a woman sits by a theodolite on its tripod, wrapped in a fog-wool blanket, sighting south.".
  Observe socket_shadow at socket_south when socketDistance(hightown) <= 1500 and not crashed(hightown) and not lost(hightown) "Hightown is close now. Its shadow comes and goes on the water as the cloud thins: a long dark bowl on a lake that is the same shape.".
  Observe station_scene at survey_station when true "A stone hut with a slate roof, abandoned by Lusk surveyors in 2603: a desk, a cracked plumb-bob, a cupboard of good brass instruments left behind, as no surveyor ever leaves brass, and on the wall a framed chart.".
  Observe shelf_scene at socket_shelf when true "A shelf of granite at the water's edge, and cut into it in a ring, every twenty paces, a square socket a man could stand in: sixty of them. Something was moored here once, from all sides at once.".
  Observe socket_north_scene at socket_north when true "The north shore, under the Teskarn's first slopes. A camp: two bedrolls, a fire pit, a spyglass on a cairn pointed across the water at the woman on the other side.".

  Person wil "Wil Fennimore" at socket_south {
    Role "a Grounder from Hightown, measuring". Ancestry human. Peaceable.
  }
  Person scouts "the Hartmark scouts" at socket_north {
    Role "two men in grey with a spyglass". Ancestry human. Calling ranger. Level 2. Numbers 2. Peaceable.
  }
  Topic wil_measuring with wil "Ask Wil Fennimore what she is measuring" when true once {
    Says "'Hightown,' says Wil, without taking her eye from the glass. 'How far off, every morning. It was three thousand nine hundred metres when I came down.' She writes a number. 'My brother Aron thinks the mountain's going home. I think it's just going where the wind goes.' She does look up, then, at the lake, and away from it quickly. 'There are men on the north shore measuring me. Hartmark. I wave.'".
  }
  Topic scouts_talk with scouts "Ask the Hartmark scouts what they are watching" when true once {
    Says "'Weather,' says the older one. The younger one laughs. 'The lady with the glass,' he says, 'and the thing she's looking at. Our envoy likes to know how fast it's coming.' He offers you the spyglass. 'Have a look. She waves back, sometimes.'".
  }
  Kind socket_chart "the Lusk survey chart of the Socket, 2571" is treasure worth 10 weighing 1.
  Item chart "the Lusk survey chart of the Socket" is socket_chart at survey_station.
  Discovery chart_seen "The Lusk survey chart of 2571: the Socket drawn contour by contour, every rib of its granite bowl to three hundred and ten metres, so exact you could cast it.".
  Observe chart_read near party when carries(party, chart) and not knows(party, chart_seen) "You unroll the chart. Contour after contour, a bowl with ribs: the lake drawn as if the water were not in it. It is beautiful work. The surveyor has written in the corner, very small, 'the shape is not glacial; by whom cut?'" teaches chart_seen.

  // ── The Chain: the Long Climb ────────────────────────────────────────────────────────────────────────────────────
  Place reach_level "the runners' reach" is level within chain.
  Place wet_level "the wet" is level within chain.
  Place swing_level "the swing" is level within chain.
  Place cradle_level "the cradles" is level within chain.
  Place runners_reach "the runners' reach" is room within reach_level at 0, 3 outdoors.
  Place wet_cradle "a Concord rest-cradle in the cloud" is room within wet_level at 0, 2 outdoors.
  Place the_swing "the swing" is room within swing_level at 0, 1 outdoors.
  Place cable_cradles "the cable-cradles" is room within cradle_level at 0, 0 outdoors.
  Passage tail_climb "the lowest loops of the Chain" is ladder between horn_foot and runners_reach taking 6 hours needing rope or climbing_harness opening when not lost(hightown) and not crashed(hightown) "There is no Chain going up from here any more.".
  Passage wet_climb "the links in the cloud" is ladder between runners_reach and wet_cradle taking 12 hours needing rope or climbing_harness.
  Passage swing_climb "the swinging links" is ladder between wet_cradle and the_swing taking 12 hours needing rope or climbing_harness.
  Passage cradle_climb "the last links" is ladder between the_swing and cable_cradles taking 6 hours needing rope or climbing_harness.

  Observe reach_scene at runners_reach when true "Inside the curve of the thirtieth link the runners have bolted a platform of planks, and on it a shrine: a horseshoe of iron, five candles, five names cut on a board: the links they have cut since 2715. The Chain sways a few metres, slowly. Below, Hornwake is a horseshoe of toys.".
  Observe wet_scene at wet_cradle when true "Inside the cloud. A Concord rest-cradle of iron, older than anything else on the Chain, hung inside the curve of a link. Everything is wet; everything drips. Where the sixty-first link and the sixty-second grind together, just above you, the grinding has words in it.".
  Observe swing_scene at the_swing when true "Above the cloud, in the swing. The Chain moves tens of metres with every gust, slowly, so that the whole world tilts and comes back. The air is thin. The Linkmoot here is silent, or asleep, or listening.".
  Observe cradles_scene at cable_cradles when true "The cable-cradles: great troughs cut into the granite underside of Hightown, and in them the first link of the Chain, held as a bow is held. Inside the curve of that link, riveted, a tally-chain. Above you the mountain's underside goes off in every direction, ribbed, like the inside of a bowl turned over.".
  Hazard chain_ice "ice on the links" means "Deal (1d6) physical damage to ally unless dexterity save against (12).".
  // The ice strikes whoever comes up into the cloud. (A long way kept dangerous by a thing on it turns the company back
  // on the way, so the ice is met on arrival instead.)
  Relation iced(group).
  Rule ice_on_the_links when at(party, wet_cradle) and not iced(party)
    says "The links in the cloud are glazed with ice, and your hands are numb before you are halfway. Somebody slips, and hangs, and is hauled in." {
    Assert iced(party). Assert strikes(chain_ice, party).
  }
  Rule ice_forgotten when iced(party) and not at(party, wet_cradle) { Retract iced(party). }

  // Links 61 and 62 remember the first campaign, and the night of 2641.
  Person hask "Hask of the Sixty-First Link" at wet_cradle {
    Role "a soul bound in the Chain, speaking where the links grind". Peaceable.
  }
  Topic hask_rise with hask "Ask Hask what happened to the Chain on the night of the Unfall" when true once {
    Says "The grinding of iron on iron makes words, slowly. 'The star tore loose and went,' says Hask. 'We felt it go. Like a tooth. The horn broke and the whole of us went up, all of us, the mountain and all, up and up, until enough of us hung in the air to hold it.' A long grind. 'Since then they cut us off the bottom, one by one. Every one they cut, we go up a little, and the ones in it go quiet. One more, in this cold. One. Two, and we all go up and never stop. I told the Teake woman. She thinks I'm mad. Some of us are.'".
    On discuss { Assert knows(actor, cut_limit). }
  }
  Action read_first_tally(actor: group, site: place) "Ask Teshen to read the tally inside the first link" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, cable_cradles) and travelsWith(teshen, actor)
      and not knows(actor, first_tally).
    Time 1.
    On success { Assert knows(actor, first_tally). }
    Result "Teshen hooks her arm through the link and reads with her free hand, two and a half kilometres up, as calmly as at her grandmother's hearth. 'Drevka Venmort holds the last,' she finishes. She looks down, a long way down, at the horn. 'She did, too. Grandmother met her.'".
  }
  Discovery first_tally "The tally riveted in the first link at the cradles, read by touch: 'Hearth Orrisk and the hearths hold the star. Four thousand and one hundred hold. Iron holds iron. Bone holds iron. The water-people talked. Drevka Venmort holds the last.'".
}

data/adventures/let-one-remember/keld.ky:
Module corrow "Let One Remember" {
  Description "Keld: thirty corbelled houses in a cluster of sinkholes, whose people came back from the Margin in 2606 and cannot be forgotten.".

  Place saska_b "Mother Saska's hearth" is building within keld.
  Place bede_b "Bede Orrisk's forge" is building within keld.
  Place keld_green "the sinkhole green" is room within keld at 1, 1.
  Place keld_road "the Keld end of the drove road" is room within keld at 2, 1.
  Place west_field "the west field" is room within keld at 0, 1.
  Place keld_chapel "the Hold chapel at Keld" is room within keld at 1, 0.
  Place saska_hearth "Mother Saska's hearth" is room within saska_b at 1, 2.
  Place bede_forge "Bede Orrisk's forge" is room within bede_b at 2, 2.

  Passage keld_drove "the drove road over the sinkhole country" is road between drove_gate and keld_road taking 6 hours.
  Passage keld_in "the way down into the green" is steps between keld_road and keld_green.
  Passage field_gate "the west field gate" is gate between keld_green and west_field.
  Passage chapel_steps "the chapel steps" is steps between keld_green and keld_chapel.
  Passage saska_door "Mother Saska's door" is door between keld_green and saska_hearth.
  Passage forge_door "the forge door" is door between keld_green and bede_forge.

  Observe keld_road_scene at keld_road when true "The drove road comes over the last rise and there is Keld: no village to be seen at all, only turf roofs in the bottoms of a cluster of sinkholes, with smoke coming up out of the ground.".
  Observe keld_green_scene at keld_green when true "The sinkhole green: a bowl of short turf with houses sunk round its rim, corbelled stone roofed with turf, juniper on every sill. Children in wool cut in a fashion two thousand years old are playing with a ball from Wendmouth. Every face that turns to look at you, you will remember. You can feel it happening.".
  Observe west_field_scene at west_field when true "A walled field on the west side of Keld, sheep-cropped, the wall walked aloud every spring. Its gate is tied with juniper.".
  Observe chapel_k_scene at keld_chapel when true "A Concord chapel of the Hold: a corbelled room with skulls in niches round its wall, each with a name scratched above it and a fresh sprig of juniper. The newest skull is ninety years old. People are looked at here.".
  Observe saska_scene at saska_hearth when true "A corbelled hall with a central hearth and skulls in the north wall. An old woman sits by the fire in a chair with arms, very upright, with a girl of nineteen sitting on the hearthstone at her feet with a book she is not reading.".
  Observe saska_settling at saska_hearth when settling(saska_hearth) "There is a man sitting in the second chair by the fire, quite at home, mending a harness. Nobody remarks on him. When you look at him you cannot quite remember when he came in, or whether he was always there.".
  Observe forge_scene_k at bede_forge when true "A cold forge: no hearth fire, because what Bede Orrisk works does not soften in fire. A water-hammer, idle. Drifts and punches in racks, all of them worn bright. On a hook by the bed, where he can reach it in the night, a smith's hammer of black iron that drinks the lamplight.".

  Person saska "Mother Saska" at saska_hearth {
    Role "eldest of Keld". Ancestry human. Peaceable.
  }
  Person teshen "Teshen" at saska_hearth {
    Role "Saska's granddaughter, nineteen, who wants to go somewhere nobody knows her". Ancestry human. Calling ranger. Peaceable.
    Joins "Teshen is on her feet before you have finished asking. 'Two silver a day,' she says, 'and I read the chains, and I don't lie, and nobody we meet will ever forget me.' She takes her coat off the peg. 'You'll get used to it.'".
  }
  Person bede "Bede Orrisk" at bede_forge {
    Role "the last cold-forger of deadiron, eighty-four". Ancestry human. Peaceable.
  }
  Person keldfolk "the people of Keld" at keld_green {
    Role "Keld households". Ancestry human. Numbers 4. Peaceable.
  }
  Topic keldfolk_remembered with keldfolk "Ask the people of Keld what it is to be remembered" when true once {
    Says "A man with juniper in his hatband laughs. 'Every pedlar who ever sold us a needle knows us by name till he dies. Every creditor too, which is the bad side of it.' A woman beside him looks you in the face. 'We came back from the Margin, and the Margin came back with us. Go on: try and forget me.' You try. You cannot. She looks pleased, and then a little sorry for you.".
  }
  Initially Set hire(teshen) to 2.

  Topic saska_kept with saska "Ask Mother Saska how the Keld speak of the past" when true once {
    Says "'Carefully,' says Mother Saska. 'When I say a thing was kept, I saw it. When I say it was laid, it is in stone and I have read it. When I say it was let, somebody told me, or I have let it go, and you may weigh it as you like.' She looks at you. 'The Calvessa spoke so. We came back from the grey still speaking so. It makes us bad liars and good witnesses, and the valley does not love us for either.'".
    On discuss { Assert knows(actor, evidential_known). }
  }
  Topic saska_strays with saska "Ask Mother Saska about the Strays in the fields" when true once {
    Says "'They come at dawn,' says Saska. 'Three, four. They stand at the edge of the west field and look at the houses. Things that went into the grey all the way and came back with nothing: no name, no place, no people.' Her hands are still on the chair-arms. 'They want belonging, and we are made of it. My grandmother said they mutter. They do. Always the same word, each one his own word.' She will not say what the words are.".
  }
  Topic saska_syllable with saska "Ask Mother Saska what she has sworn never to say" when true once {
    Says "The fire ticks. 'My grandmother heard a thing said, in the grey, before they brought her back,' says Saska. 'One piece of a name. She said it once to me, when I was eight, and made me swear. I have kept it seventy years by never saying it.' She smiles very slightly. 'A man from the consulate in Wendmouth came to ask me about the grey last month. A pleasant man. The dogs did not bark at him. I have been thinking about that.'".
    On discuss { Assert knows(actor, webb_at_keld). }
  }
  Discovery webb_at_keld "Corin Webb of the Lusk consulate has been to Keld asking Mother Saska about the grey; the Keld dogs did not bark at him.".
  Topic saska_hollow with saska "Ask Mother Saska how many came back from Keld Hollow" when true once {
    Says "'A hundred and forty,' says Saska. 'Out of a hundred and forty-one. The one they never found was a young man, Corin, son of the Hollow's reeve, who had gone out to the far field when the fog came and was not in the village with the rest. They called and called for him.' She looks into the fire. 'The anchors could not hold a name nobody had seen for two hundred years, they said. He stayed.'".
    On discuss { Assert knows(actor, hollow_missing). }
  }
  Discovery hollow_missing "Of the hundred and forty-one people of Keld Hollow, the 2606 expedition brought back a hundred and forty. The one left in the grey was Corin, son of the Hollow's reeve, who had gone out to the far field when the fog came.".
  Topic saska_lift with saska "Tell Mother Saska what you know of where Hightown came from" when knows(actor, origin_known) and not knows(actor, method_known) once {
    Says "Saska is quiet while the peat settles in the grate. 'So you know,' she says. 'Then you had better know the rest, or you will do harm with it.' She speaks in the flat voice of a thing learned by heart. 'It was kept, by my grandmother's grandmother, who had it from hers, who lived in 412, when the Lift was three lifetimes back and the Concord Warden's engineers still walked the Drag: if ever the mountain must come down, it comes down as its people come to know their place. Not all at once. Let one remember at a time.' She lets out her breath. 'Kept, not let.'".
    On discuss { Assert knows(actor, method_known). }
  }

  // Teshen: the restless child, who cannot be forgotten, and who met the real secretary.
  Topic teshen_stranger with teshen "Ask Teshen what she wants" when not travelsWith(teshen, actor) once {
    Says "'To be a stranger,' says Teshen. 'Do you know what it's like to never be a stranger? Everyone I have ever met remembers my face for life. If I went to the Hartmark I'd be the girl from Keld by the second day and they'd remember me at ninety.' She shuts the book. 'I'd give an arm to be forgotten for a week. Failing that, I'd go anywhere with anyone who's going somewhere.'".
    On discuss { Assert willing(teshen, actor). }
  }
  Topic teshen_secretary with teshen "Ask Teshen whether she knows the consul's secretary in Wendmouth" when knows(actor, displaced_clerk) or knows(actor, payroll_known) or knows(actor, webb_at_keld) {
    Says "'I witnessed a land deal at the consulate in 2729,' says Teshen. 'The secretary was a tall man with a cough who apologised for the ink. Absalom, they called him.' She frowns. 'Grandmother says the man who came here is called Webb and has been secretary for eleven years. He's short and he doesn't cough. I remember everyone. I can't help it.' She looks at you. 'Somebody's wrong, and it isn't me.'".
    On discuss { Assert knows(actor, webb_wrong_face). }
  }
  Discovery webb_wrong_face "Teshen of Keld, who cannot forget a face, witnessed a deal at the Lusk consulate in 2729 before a secretary called Absalom, tall, with a cough; Corin Webb is short and does not cough.".

  Topic teshen_grey with teshen "Ask Teshen whether she still wants to be forgotten" when travelsWith(teshen, actor) and knows(actor, open_hand_plan) once {
    Says "Teshen walks a while without answering. 'There's one place I'd be a stranger,' she says. 'Across the lake at the bottom of the low road. Over there nobody remembers anybody; that's what it is.' She glances at you. 'My great-great-grandmother came back from it with the rest of the Hollow, and none of us has been forgettable since. If I went in, I'd be the first Keld in a hundred and twenty years that nobody could see.' She shrugs, too carefully. 'If I came out, I'd be the same as ever. If I didn't, I'd be a stranger for good.'".
  }

  // The Strays, at dawn, at the edge of the west field.
  Person strays "the Strays" at limbo {
    Role "people who came back from the grey with nothing". Ancestry human. Numbers 3. Peaceable.
  }
  Rule strays_come when hour(clock) >= 6 and hour(clock) < 9 and at(strays, limbo) and not namedStrays(keld) and not strayTaken(keld) { Assert at(strays, west_field). }
  Rule strays_go when (hour(clock) < 6 or hour(clock) >= 9) and at(strays, west_field) { Assert at(strays, limbo). }
  Relation namedStrays(place). Relation strayTaken(place).
  // In the fourth week the Open Hand come for the Strays at Keld, with ropes and kindness, and take them to the Grey
  // Mile to listen to them.
  Rule strays_taken when watch(clock) >= 3168 and not namedStrays(keld) and not strayTaken(keld) and not turned(ferran)
    says "Word comes up the drove road: grey-coated people from the Open Hand were at Keld at dawn with a cart, and took the three Strays out of the west field, gently, the way you would take a lost child home, and the Keld stood at their doors and let them." {
    Assert strayTaken(keld). Assert at(strays, grey_mile).
  }
  Observe strays_scene at west_field when at(strays, west_field) "At the edge of the west field, just inside the wall, three people stand in the grass and look at the houses of Keld. Their clothes are of no fashion at all. Their faces are of no family. Your eye slides off them the way a hand slides off wet glass. Each is saying something under his breath, over and over.".
  Topic strays_listen with strays "Listen to what the Strays are saying" when at(strays, west_field) once {
    Says "You stand close enough to hear. Each of them is saying one syllable, over and over, as a child says a word to keep from losing it. Three different syllables. None of them is a word. When you step closer the nearest one turns to you, and looks at you as a hungry man looks at a lit window.".
    On discuss { Assert knows(actor, stray_syllables). }
  }
  Discovery stray_syllables "Each of the Strays at Keld mutters one syllable over and over, each his own; together they are pieces of something.".
  Action name_strays(actor: group, site: place) "Ask Teshen to give each Stray a name and a place, aloud, as the Keld do" {
    Description "A Stray named aloud by someone who means it, and given a place, stops taking.".
    Requires able(actor) and company(actor) and at(actor, site) and at(strays, site) and travelsWith(teshen, actor)
      and not namedStrays(keld).
    Time 2.
    On success { Assert namedStrays(keld). Assert at(strays, keld_green). }
    Result "Teshen walks up to the first of them and takes his hands, and he lets her. 'You're Tam,' she says. 'Tam of the west field. You sleep in the byre at Hallows' and you help with the lambing.' The man's face does something, slowly, like water settling. She does it three times, three names, three places. When she is done, three people walk into Keld behind her, and one of them is crying, and none of them is muttering anything at all.".
  }
  Observe strays_named at keld_green when namedStrays(keld) "Three newcomers are being shown how a Keld house is kept: Tam, Ollo and Mag, whom nobody knew this morning and everyone now greets by name.".

  // Bede Orrisk, and Drevka's hammer.
  Topic bede_hammer with bede "Ask Bede Orrisk about the hammer by his bed" when true once {
    Says "'Drevka's,' says Bede. 'She made it in the Binding and closed the last rivet with it in 2601 and gave it to me in 2667 with her last breath, more or less.' He does not look at it. 'It opens a scarf weld clean. It breaks a laid band in one blow. Nothing else in the world does either.' His hands shake on his knees. 'I've had nine come asking to learn. I sent them all home. You don't learn this. You give your life to it, and then you're eighty-four.'".
  }
  Topic bede_link with bede "Ask Bede Orrisk whether the link in the Well could be split" when knows(actor, forge_contract) once {
    Says "Bede's head comes up. 'Who told you there was a scarf?' You tell him: the contract of 1210. 'Ah,' he says, and something in his face wakes. 'A third along the near limb. I'd want to see it. Forty days, with drifts, and a lad to hold them, and the Ninepans off my back.' He looks at his hands. 'I'm eighty-four. That's forty days I'd not get back.' A long pause. 'Ask me again in the spring.'".
  }

  // Corin Webb comes for Saska's syllable in the third week. She refuses; and one of the Strays begins to settle into her household.
  Relation settling(place).
  Rule webb_comes_to_keld when watch(clock) >= 2592 and not webbNamed(webb) and able(webb) and not settling(saska_hearth) and not webbVisited(saska)
    says "Word comes, the way word comes on the drove roads: the consul's secretary was at Keld yesterday, asking Mother Saska again about the grey, and went away without what he came for." {
    Assert webbVisited(saska). Assert settling(saska_hearth).
  }
  Relation webbVisited(group).
  Topic teshen_chair with teshen "Ask Teshen what is troubling her" when settling(saska_hearth) and not namedStrays(keld) once {
    Says "'Grandmother's chair,' says Teshen. 'The second one, by the fire. Everyone at home has started calling it Rab's chair, as if Rab had always sat there.' Her voice is very steady. 'There's no Rab. I'd remember. I remember everyone.' She looks toward the west field. 'One of them's come in.'".
  }
  Rule settler_named when namedStrays(keld) and settling(saska_hearth) { Retract settling(saska_hearth). }

  // After Teshen has gone, and what the settled chair says to a house that cannot forget anyone.
  Topic saska_teshen_gone with saska "Tell Mother Saska that Teshen is travelling with you" when travelsWith(teshen, actor) once {
    Says "'I know,' says Mother Saska. 'The dogs told me; they had gone to the gate before she said a word.' The chair-arms creak. 'I gave her the book. It has nothing in it. She will fill it, and write down every face, and bring it back, and I shall read it by this fire and it will not be a stranger's.' She turns her head toward the empty hearthstone. 'You are to keep her from being forgotten, you know. No. The other thing. You are to let her.'".
  }
  Topic bede_apprentice with bede "Ask Bede Orrisk whether he ever took anyone on" when true once {
    Says "'Nine came,' says Bede Orrisk, 'and I sent nine home. One of them I did not mean to.' He opens one hand on his knee and shuts it. 'A girl. Not a Keld girl; nobody would know her face, which was why she came. I told her it would take a life. She said, whose, and I had no answer, because it was hers.' His eyes go to the hammer on its hook. 'She did not come back. I have not minded the forge as I did.'".
  }
  Observe keld_dogs at keld_green as ambience when settling(saska_hearth) "The Keld dogs lie across the mouth of Saska's door, all of them, with their chins on their paws. They do not growl at anything. They watch the second chair.".
}

data/adventures/let-one-remember/lore.ky:
Module corrow "Let One Remember" {
  Description "Links outward from the Corrow: a man given out for dead who is alive, and the Finder shown a letter from the Lesser Instruments.".

  // ── A world event, read: a name struck from the dead ────────────────────────────────────────────────────────────
  Observe lore_registry_perrin at counting_house when befell(perrin_lives) "A clerk has pinned a slip to the end of a row, in a southern hand that is not the Registry's: PERRIN HALYARD, ENTERED AMONG THE DEAD, IS ALIVE. STRIKE. The head clerk reads it twice. 'We do not strike the dead,' he says. 'We have no mark for it.' The slip stays on the board all week.".

  // ── A visitor from elsewhere: a letter of the Lesser Instruments ────────────────────────────────────────────────
  Discovery lore_finder_collects "The Finder of Wendmouth, shown a letter of the Collegium of Lesser Instruments, says that Corran collects, and the Finder keeps: a lost thing found is held for its owner, a collected thing is held for the collection.".
  Topic lore_finder_letter with finder "Show the Finder the letter of the Lesser Instruments" when holding(actor, collegium_letter) once {
    Says "Pannick holds the letter at arm's length, as if it might be contagious. 'Corran,' he says. 'Collects. They collect brass off me every year and pay in thanks. I hold it for its owner, you understand. It is on the label.' He taps one of his eleven pockets. 'Lesser Instruments. Greater instruments are all broken, so they say. It is a joke. I do not understand it. I have found four of them in the lost-and-found.' He reads on, and frowns, and refolds it with the fastidious care of a man who has found a thing that does not belong to him and has decided what to do about it. 'Keep it by you. If Corran writes to say it wants anything back, I will say it was held.'".
    On discuss { Assert knows(actor, lore_finder_collects). }
  }
}

Module corrow "Let One Remember" {
  // The Corrow as a country beyond a march: the company that comes up the Peleth road is the world's own.
  Entity party: group "Your company".
  // What is said of the Corrow in the country behind it: once the road has ended, the talk of a drifting mountain and a well with no bottom is old news there, told by how it ended.
  Entity word: fact "What is said of the Corrow in the country behind it.".
  Entity word_one: fact "What is said there of the one who keeps the jewel.".
  Entity word_given: fact "What is said there of the heart that went home.".
  Entity word_none: fact "What is said there of the Hush.".
  Entity word_followed: fact "What is said there of the one who followed.".
  Rule word_old when ended(beyond) and not stale(word) { Assert stale(word). }
  Rule word_one_old when endedOne(beyond) and not stale(word_one) { Assert stale(word_one). }
  Rule word_given_old when endedGiven(beyond) and not stale(word_given) { Assert stale(word_given). }
  Rule word_none_old when endedNone(beyond) and not stale(word_none) { Assert stale(word_none). }
  Rule word_followed_old when endedFollowed(beyond) and not stale(word_followed) { Assert stale(word_followed). }
}

data/adventures/let-one-remember/scarp.k:
Module corrow "Let One Remember" {
  Description "The Peleth road up the Scarp, and the Stake ruins on the rim of the Emptied Well.".

  Place cistern_inn "the Rope and Lantern" is building within stake.
  Place hold_chapel "the Hold chapel" is building within stake.
  Place guild_house "the cistern guild" is building within stake.

  Place scarp_foot "the foot of the Scarp" is room within scarp at 0, 1.
  Place eighth_bend "the eighth bend of the Peleth road" is room within scarp at 0, 0.
  Place collar "the Hawse" is room within stake at 1, 1.
  Place chimneys "the street of chimneys" is room within stake at 0, 1.
  Place rim "the rim of the Well" is room within stake at 2, 1.
  Place drove_gate "the drove-road gate" is room within stake at 0, 0.
  Place furrow_end "the north edge of the ruins" is room within stake at 1, 0.
  Place inn_room "the Rope and Lantern" is room within cistern_inn at 1, 2 underground.
  Place chapel_room "the Hold chapel" is room within hold_chapel at 2, 2.
  Place guild_room "the cistern guild's office" is room within guild_house at 0, 2.

  Passage scarp_bends "the bends of the Peleth road" is road between scarp_foot and eighth_bend taking 4 hours.
  Passage last_bend "the ninth bend" is road between eighth_bend and chimneys taking 30 minutes.
  Passage chimney_way "the way between the chimneys" is path between chimneys and collar.
  Passage collar_rim "the lee of the Hawse" is path between collar and rim.
  Passage cistern_steps "the cistern steps" is steps between collar and inn_room.
  Passage chapel_door "the chapel door" is doorway between collar and chapel_room.
  Passage guild_door "the guild's door" is door between chimneys and guild_room.
  Passage drove_lane "the drove lane" is path between chimneys and drove_gate.
  Passage north_lane "the north lane" is path between collar and furrow_end.

  // Arrival (Player Portfolio). The company comes up the Scarp on a carter's wagon.
  Entity arrived: fact "You have come up the Scarp into the Corrow.".
  Observe arrival at eighth_bend when not knows(party, arrived) "The Peleth road climbs the Scarp in nine bends, and at the eighth the wind finds you. It comes off the plateau flat and cold, smelling of sheep and wet limestone. At the top the country opens: grey grass, pale stone breaking through it like knuckles, and a hollow every few hundred paces where the ground has simply sunk. Ahead, a cluster of chimneys stands without the houses that went with them. Smoke rises from a few. Beyond the chimneys the ground stops at the edge of a hole you cannot see across the bottom of. To the north a line runs up out of the plateau into the sky, thin as a thread. You follow it up past one layer of cloud and then another, and at the top, where it ends, something dark sits in the sky the way a stone sits on water, with lights along its rim. The carter beside you does not look up. 'That's Hightown,' she says. 'You get used to it. You'll want the Rope and Lantern. It's in a cistern. Mind the steps.' She sets you down and turns her mules for the descent." teaches arrived.
  Observe bend_scene at eighth_bend when knows(party, arrived) "The eighth bend of the Peleth road, where the wind off the plateau finds you. The parapet is polished along the top where carters sit to put their boots back on. Below, the road goes down the Scarp in long loops to Wendhead; above, the chimneys of the Stake ruins.".
  Observe scarp_foot_scene at scarp_foot when true "The Peleth road leaves the valley at the foot of the Scarp, a grey cliff three hundred metres high pocked with cave-mouths, and starts up it in long bends. Yew grows in the cracks.".

  Observe chimneys_scene at chimneys when not dark() "Brannock's Stake burned ninety years ago when the slowed fire came up the shaft, and what stood up afterwards was chimneys: stone stacks without houses, a whole street of them, and between them salvagers' huts of salvaged timber and canvas. Smoke rises from a few. Everything is pointed toward the hole.".
  Observe chimneys_night at chimneys when dark() "The chimneys stand black against a sky with one low cluster of lights in it, to the north, high up. A dog barks at nothing.".
  Observe collar_scene at collar when true "The Hawse was a ring of bronze-clad stone sixty metres across that guided the Chain into the Well. The fire slagged it into lumps like a burnt loaf. The market stands in its lee: rope, lamps, oatcake, rumour. Wind comes up out of the ground on the far side, warm, at a walking pace.".
  Observe rim_scene at rim when true "The rim of the Emptied Well. Four hundred metres across, and black glass for the first thirty down, then broken rock, then darkness. Warm air rises past your face out of it, and a scrap of paper someone dropped goes up with it and does not come down. Salvagers' ropes go over the edge from iron pins, swaying. To the left a spiral stair is cut into the wall, with a brass bell at its head.".
  Observe drove_gate_scene at drove_gate when true "A field gate at the west end of the ruins, where the drove road goes off over the sinkhole country toward Keld, eighteen kilometres. A shepherd's staff leans by the post for anyone to borrow: the ground out there falls in.".
  Observe furrow_end_scene at furrow_end when true "The north edge of the ruins. From here you can see the furrow: a raw trench three metres deep running north across the plateau, and at the end of it, ten kilometres off, a smudge of smoke and timber where the Chain comes down out of the sky to the ground.".
  Observe inn_scene at inn_room when true "The Rope and Lantern is a Peleth cistern with a floor laid over the water: you can hear it under the boards. It is warm and low and smells of lamp-oil and wet wool. Coils of rope and lamps for hire hang from the vaulting, and the regulars sit with their backs to the curve of the wall.".
  Observe chapel_scene at chapel_room when true "The Hold chapel's walls stood through the fire; its roof is new turf. In the north wall is a niche, empty, scorched black round its edges, the height of a man. Juniper has been put in it anyway.".
  Observe guild_scene at guild_room when true "The cistern guild's office: a counting table, a rack of brass dippers, the smallest worn brightest, and ledgers going back to before the fire in an iron press that kept them. Whoever has the water at the Stake has the Stake.".

  // The Rope and Lantern.
  Person agnes "Agnes Ruddle" at inn_room {
    Role "keeper of the Rope and Lantern". Ancestry human. Profession innkeeper. Peaceable.
    Sells rations for 1 coin from 12.
    Sells lamp for 2 coin from 4.
    Sells lamp_oil for 1 coin from 8.
    Sells rope for 3 coin from 4.
    Sells torch for 1 coin from 10.
  }
  Topic agnes_well with agnes "Ask Agnes Ruddle about going down the Well" when true once {
    Says "'Two ways,' says Agnes, polishing a lamp-glass she has polished already. 'The stair, which is the Registry's, two silver a head, and they write you down going and write you down coming back. Or the ropes, which are nobody's, and nobody writes anything.' She holds the glass to the lamp. 'The machine hears the ropes anyway, mostly. It's a deaf old thing these days, they say, but not that deaf. Take lamps. Magic lights go out down there near the iron, and the glass people will tell you to shutter them anyway.'".
  }
  Topic agnes_hightown with agnes "Ask Agnes Ruddle about Hightown" when true once {
    Says "'It's moving,' says Agnes. 'It always moved; it moves faster now. The runners cut the tail and sell the links, and it gets lighter, and it goes north on the gales.' She jerks her chin at the vault, which is as near as she can get to pointing at the sky. 'Hornwake goes after it with the horn. You can't miss Hornwake. It's the town that won't stay put.'".
  }
  Topic agnes_returns with agnes "Ask Agnes Ruddle about the Returns" when true once {
    Says "'Things come back,' says Agnes. 'Not here so much. In the valley, and out on the drove roads. My mother's thimble came back on the bar one morning, the one she lost in seventy-one. I didn't want it.' She shrugs. 'The ones nobody wants go on the Lost Nail in Wendmouth for a year, then the Fair sells them.'".
  }

  // The hook: everybody wants someone to go down the Well for them, and says so on the board by the steps.
  Discovery jobs_known "The notes on the Rope and Lantern's board, some of them weeks old: THE REGISTRY will enter in its roll as COLLEAGUE whoever brings it heat. J. PENNICK, of the Keepstone Court, will pay for any means to read a blank stone. C. NINEPAN buys deadiron droplets, sixty silver the sack, and says Lamplighter's Camp is still somewhere under the Breach. A. FENNIMORE, of Hightown, will pay for word of any Concord chain on the Drag. The WENDHEAD HOSPICE asks after anyone who has seen a man nobody can name. KELD GUIDES, two silver: ask at Saska's hearth. And one in a fine hand, newer than the rest: STRAYS WANTED, alive, for their own good. Apply at the Grey Mile. F. COSK, for the Open Hand." {
    Source board_notes "the notes on the board by the cistern steps" at inn_room readable by party.
  }
  Observe board_seen at inn_room when not knows(party, jobs_known) "By the cistern steps a board is stuck all over with notes. Every one of them wants somebody to go somewhere they would rather not.".

  // A Return to a Changed Place (Player Portfolio): back up some other way than the stair, after days below.
  Event back_unlogged_blown at inn_room when unclosed(party) and at(party, inn_room) and watch(clock) - wentDown(party) >= 432 and lastGale(hightown) > wentDown(party) "Agnes Ruddle looks at you over the counter for a moment too long. 'The Registry has you down as not come back,' she says. 'Went down the stair and never came up it. I let your room. Your pack's in the store. Most of it.' It has blown while you were below. 'Shifted,' Agnes says. 'The whole of Hornwake, and the mountain with it; you'll see from the door. And there's a woman from the Ninepan House been in asking after you.' She pours you something hot. 'You'll want to go to the Registry and tell it you're alive. It gets upset.'" then {
    Retract unclosed(party).
  }
  Event back_unlogged at inn_room when unclosed(party) and at(party, inn_room) and watch(clock) - wentDown(party) >= 432 and lastGale(hightown) <= wentDown(party) "Agnes Ruddle looks at you over the counter for a moment too long. 'The Registry has you down as not come back,' she says. 'Went down the stair and never came up it. I let your room. Your pack's in the store. Most of it.' She pours you something hot. 'You'll want to go to the Registry and tell it you're alive. It gets upset.'" then {
    Retract unclosed(party).
  }

  // A stone-reader, drunk, who knows a thing nobody believes.
  Person tobin "Tobin Reach" at inn_room {
    Role "a stone-reader from Wendhead, drinking". Ancestry human. Peaceable.
  }
  Discovery seam_reads "A blank keepstone carried down to the bottom of the low road, to the chamber where the jewel lay, reads again for about a month." { Known by tobin. }
  Topic tobin_stones with tobin "Ask Tobin Reach about the blank stones" when true once {
    Says "Tobin puts his cup down with great care. 'They're not dead,' he says. 'Everybody says they're dead. They're sleeping. You take one down, all the way down, down the old road to the cup where the star's heart sat, and you put it on the wet wall and you wait, and it wakes up.' He picks the cup up again. 'For a month. Then it goes off again, up here. I've seen it. I had a stone of my granddad's wedding.' He drinks. 'Nobody listens to a stone-reader. We sell fakes.'".
    On discuss { Assert knows(actor, seam_reads). }
  }

  // The Hawse's tally, under the slag, for anyone who can read link-script.
  Action read_collar(actor: group, site: place) "Ask Teshen to read the tally under the Hawse's slag" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, collar) and travelsWith(teshen, actor)
      and not knows(actor, collar_tally).
    Time 2.
    On success { Assert knows(actor, collar_tally). }
    Result "Teshen goes along the inner face of the Hawse on her knees, feeling under the slag with her fingertips for the iron links set in the stone. 'Here,' she says, and reads it out, slowly, in the old speech and then in March. At 'the water-people talked' she makes a face. 'That's not fair,' she says. 'They forgot half of who they were, doing it.'".
  }
  Discovery collar_tally "The near-copy of the first link's tally on the Hawse's inner face, read by touch under the slag: 'Hearth Orrisk and the hearths hold the star. Four thousand and one hundred hold. Iron holds iron. Bone holds iron. The water-people talked. Drevka Venmort holds the last.'".

  // The cistern guild remembers who drew water on the night of the Unfall.
  Person warden_sall "Warden Sall" at guild_room {
    Role "warden of the cistern guild". Ancestry human. Peaceable.
  }
  Discovery unfall_water "The cistern guild's ledger for the night of the Unfall, 2641: every household at the Stake drew water against the fire, by name. One line is different: 'Coyle, W., of Wendmouth, aged 69, lodging at the Lantern. Drew none. Went down the stair at the ninth bell.'" {
    Source water_ledger "the guild's ledger for 2641" at guild_room readable by party.
    Known by warden_sall.
  }
  Topic sall_water with warden_sall "Ask Warden Sall about the night of the Unfall" when true once {
    Says "'The ledger has it,' says Sall. 'Every bucket. My grandmother's grandmother kept it with the town burning round her, because if you don't write down who had water, somebody says afterwards it was them.' He taps the press. 'Go on and look. It's not secret. It's just old.'".
  }

  // ── Wendhead ─────────────────────────────────────────────────────────────────────────────────────────────────────
  Place hospice "the Wendhead hospice" is building within wendhead.
  Place wend_bridge "Wendhead bridge" is room within wendhead at 1, 0.
  Place wend_pool "the Wendhead pool" is room within wendhead at 2, 0.
  Place hospice_hall "the hospice hall" is room within hospice at 0, 1.
  Place long_ward "the long ward" is room within hospice at 1, 1.
  Place hospice_archive "the hospice archive" is room within hospice at 0, 2.
  Place hospice_under "the hospice cellars" is level within hospice.
  Place hospice_cellar "the hospice cellar" is room within hospice_under at 1, 2 underground.

  Passage wendhead_road "the valley road" is road between wend_bridge and scarp_foot taking 30 minutes.
  Passage pool_path "the pool path" is path between wend_bridge and wend_pool.
  Passage hospice_gate "the hospice gate" is gate between wend_bridge and hospice_hall.
  Passage ward_door "the ward door" is doorway between hospice_hall and long_ward.
  Passage archive_door "the archive door" is door between hospice_hall and hospice_archive.
  Passage cellar_stair "the cellar stair" is stair between hospice_hall and hospice_cellar.

  Observe bridge_scene at wend_bridge when true "Wendhead: a mill, a bridge, a quarry, and on the far bank the hospice behind a wall of grey stone with roses over it. Upstream, a round pool of dark water turns slowly under the Scarp.".
  Observe pool_scene at wend_pool when true "The Wendhead pool is sixty metres across and very deep, and it rises: you can see the water lift and turn at its centre, where the river comes up out of the ground from a cave below the Scarp. Old men say it used to steam in winter. It does not now. On the bank, eelers' tackle is drying on a rail.".
  Observe hospice_hall_scene at hospice_hall when true "A whitewashed hall with benches, a fire, and the smell of camomile and lye. A sister goes by with a basin and smiles at you without stopping.".
  Observe ward_scene at long_ward when true "A long room of beds under high windows. Most of the patients are old and some are dying, and the sisters move among them talking quietly, the way people talk to horses.".
  Observe archive_scene at hospice_archive when true "A small room of shelves and boxes, very dry, with a reading desk. Letting records go back seven hundred years: who came, what they wished to put down, whether they did.".
  Observe cellar_scene at hospice_cellar when true "The hospice cellar runs back into the rock of the Scarp further than a cellar should. At the far end is a door of old oak, bound in iron, with a lock and a Letting sign carved over it: an open hand.".

  Person rook "Prioress Imelda Rook" at hospice_hall {
    Role "prioress of the Wendhead hospice". Ancestry human. Calling cleric. Level 3. Trait vitalist. Peaceable.
  }
  Person sisters "the Letting sisters" at long_ward {
    Role "nurses of the hospice". Ancestry human. Numbers 3. Peaceable.
    Offers healing "a month's nursing, paid as you can" for 3 coin.
  }
  Topic rook_rite with rook "Ask Prioress Rook about the anchoring rite" when true once {
    Says "'We keep it,' says the prioress. 'Nobody has asked for it in thirty years. If someone goes across, into the grey, the anchors stay up here and say their name aloud without stopping, in relays, day and night, until they come back. If every anchor falls silent, they stay.' She smiles a little. 'It is the only rite we have left that is about remembering instead of letting go. I am fonder of it than I ought to be.'".
  }
  Topic rook_record with rook "Ask Prioress Rook about the Short Grey" when true once {
    Says "'Before my time,' says the prioress. 'Brother Cosk's rite, in 2604. Three months of fog, and the Grey Mile below the bridge where nothing grows right still. Our sisters kept a record of it: who was lost, who came back, what was heard in the fog.' She glances toward the archive. 'There's a man from the consulate in Wendmouth who has asked twice to read it. A very pleasant man. I said I would think about it.'".
    On discuss { Assert knows(actor, webb_asked). }
  }
  Discovery webb_asked "Corin Webb, the Lusk consul's secretary, has twice asked the hospice to let him read its record of the Short Grey.".

  // The record of the Short Grey, with a syllable in it; and the manual's warning.
  Kind grey_record "the Letting record of the Short Grey" is treasure worth 0 weighing 1.
  Item short_grey "the Letting record of the Short Grey" is grey_record at hospice_archive owned by rook.
  Discovery short_grey_syllable "In the Letting record of the Short Grey, among things heard in the fog in 2604, one word is written down as heard, a single syllable, and a sister has written beside it: not a word of ours.".
  Discovery anchoring_warning "The hospice's anchoring manual, in a hand of the 2600s: 'Do not say in the chamber what the fog said.'" {
    Source anchoring_manual "the anchoring manual" at hospice_archive readable by party.
    Known by rook.
  }
  Discovery letting_prayer "The Letting prayer, sung at deathbeds, copied with the old marks glossed: '[let] There was a road under the water. [let] We were many who walked it. [kept] I do not walk it. [laid] The stone walks it for me. [let] One walks it, always one.' A sister's note: kept is what the singer saw herself; let is what she was told, or what she has let go." {
    Source prayer_card "a copy of the Letting prayer, with its old marks glossed" at hospice_archive readable by party.
  }
  Observe prayer_grammar near party when knows(party, letting_prayer) and not knows(party, evidential_known) "The sister's note stays with you: kept is what the singer saw; let is what she was told, or let go. The old tongue says how it knows a thing before it says the thing." teaches evidential_known.
  Observe grey_read near party when carries(party, short_grey) and not knows(party, short_grey_syllable) "You turn the pages of the Short Grey record. Names of the lost, names of the found, the weather of each day: fog, fog, fog. On the fortieth day, in a list of things heard in the fog, one word is written as it sounded, a single syllable, and beside it, in another hand: not a word of ours." teaches short_grey_syllable.

  // The nameless man in the long ward, whom nobody knows, his own wife included.
  Person nameless "the nameless man" at long_ward {
    Role "a man nobody can name". Ancestry human. Peaceable.
    State unknown "In the end bed a man of fifty sits with his hands on the blanket, quite well, looking at the door. The sisters call him 'love' and 'dear'. Nobody has ever been able to keep his name in their head for longer than a sentence.".
    State known "Absalom Prew sits on the end bed in his coat, waiting for his wife, with his name on him like a coat as well.".
  }
  Topic nameless_who with nameless "Ask the man in the end bed who he is" when state(nameless, unknown) once {
    Says "'I had a desk,' he says, carefully, as if reading it off the inside of his own forehead. 'In Wendmouth. A good desk. I wrote letters for a man with a seal.' He looks at you hard. 'Seven months ago I went in to work and there was a man at my desk, and he looked up at me as if I were a stranger, and so did the consul, and so did my wife that night.' His hands open on the blanket. 'Everyone says I've been here for ever. I haven't. I'd remember.'".
    On discuss { Assert knows(actor, displaced_clerk). }
  }
  Discovery displaced_clerk "A man in the hospice's long ward, whose name nobody can keep, says he was a secretary at the Lusk consulate in Wendmouth until seven months ago, when another man was at his desk and nobody, his wife included, knew him.".

  // The cellar door: the old way into the Commonplace, which the Lettings keep locked.
  Thing commonplace_door "the oak door with the open hand" on bright_way {
    State locked blocking "The oak door with the open hand over it is locked.".
    State open "The oak door stands open on darkness and the sound of dripping.".
    Change unlock "Unlock the oak door with the prioress's key" from locked to open needing cellar_key.
  }
  Kind letting_key "the prioress's iron key" like cell_key worth 0 weighing 0.
  Item cellar_key "the prioress's iron key" is letting_key at limbo owned by rook.
  Topic rook_door with rook "Ask Prioress Rook where the road under the water begins" when (knows(actor, low_road_known) or knows(actor, letting_prayer)) and state(commonplace_door, locked) {
    Says "The prioress looks at your boots, and then at your faces. 'The Commonplace is going dark,' she says. 'The bright galleries are blank already. Past them it is faint, and past that, at the Root, it is still clear, and from the Root the old road goes down to where the jewel lay.' She takes a key from her belt. 'The Lettings have kept that door for nine hundred years so that nobody goes down it by accident. You are not going by accident.' She gives it to you. 'Bring it back.'".
    On discuss { Assert lends(rook, cellar_key, actor). Assert at(cellar_key, hospice_hall). }
  }

  // ── The Open Hand, at the Grey Mile ──────────────────────────────────────────────────────────────────────────────
  // Brother Cosk's great-grandson keeps a school of forgetting where the Short Grey left the valley wrong. He believes
  // the grey has people in it who want to go home, and that the 412 rite should be finished. He gathers Strays, and
  // what they say.
  Place grey_mile "the Grey Mile" is room within wendhead at 3, 1.
  Passage grey_mile_path "the river path below the bridge" is path between wend_bridge and grey_mile taking 30 minutes.
  Observe grey_mile_scene at grey_mile when true "Below the bridge the valley goes wrong for a mile: the grass grows grey and short, the pears on the old trees ripen with no taste, birds cross it without landing. A long barn stands in the middle of it, freshly limewashed, with an open hand painted over the door.".
  Person ferran "Ferran Cosk" at grey_mile {
    Role "master of the Open Hand". Ancestry human. Calling cleric. Level 4. Peaceable.
  }
  Person open_hand "the Open Hand" at grey_mile {
    Role "brothers and sisters of the Open Hand, in grey". Ancestry human. Numbers 4. Peaceable.
  }
  Topic ferran_hand with ferran "Ask Ferran Cosk what the Open Hand is for" when true once {
    Says "'Letting,' says Ferran Cosk, as if it were the simplest word in March. He has kind eyes and ink on his cuffs. 'My great-grandfather tried to let the star go into the Lap, and failed, and the valley called it a crime. The star went anyway. And in the grey there is something that has been waiting since 412 to go home, and speaks to us through the Strays, a syllable at a time.' He smiles. 'We are writing it down. When we have all of it, we will say it at the Seam, and it can go where it belongs. That is all mercy is: letting a thing go where it belongs.'".
    On discuss { Assert knows(actor, open_hand_plan). }
  }
  Discovery open_hand_plan "The Open Hand are gathering the syllables the Strays repeat, to say the whole word at the Seam and let 'what has waited in the grey since 412' go home.".
  Relation turned(group).

  // Where things wait that are nowhere yet.
  Place limbo "nowhere" is room within scarp at 5, 5.
}

data/adventures/let-one-remember/wendmou:
Module corrow "Let One Remember" {
  Description "Wendmouth: a grey-slate port where the Wend meets the tide, whose land titles are on stones that have gone blank.".

  Place court_b "the Keepstone Court" is building within wendmouth.
  Place consulate_b "the Lusk consulate" is building within wendmouth.
  Place ninepan_b "the Ninepan House" is building within wendmouth.
  Place coyle_b "the Coyle house" is building within wendmouth.

  Place valley_road "the valley road below Wendhead" is room within wendmouth at 1, 0.
  Place well_square "the well square" is room within wendmouth at 1, 1.
  Place quay "the quay" is room within wendmouth at 2, 2.
  Place cemetery "the cemetery on the ridge" is room within wendmouth at 0, 1.
  Place courtroom "the Keepstone Court" is room within court_b at 0, 2.
  Place consulate "the Lusk consulate" is room within consulate_b at 1, 2.
  Place counting_room "the Ninepan counting-room" is room within ninepan_b at 2, 1.
  Place coyle_kitchen "the Coyle house" is room within coyle_b at 0, 0.

  Passage valley_way "the valley road" is road between wend_bridge and valley_road taking 2 hours.
  Passage into_town "the bridge into town" is bridge between valley_road and well_square taking 10 minutes.
  Passage quay_lane "the quay lane" is path between well_square and quay.
  Passage cemetery_lane "the cemetery lane" is path between well_square and cemetery taking 10 minutes.
  Passage court_steps "the court steps" is steps between well_square and courtroom.
  Passage consulate_door "the consulate door" is door between well_square and consulate.
  Passage ninepan_door "the Ninepan House door" is door between quay and counting_room.
  Passage coyle_door "the Coyle house door" is door between valley_road and coyle_kitchen.

  Observe valley_road_scene at valley_road when true "The valley road comes down between orchards, half of them grubbed up for apple and half still pear, to a five-arched Peleth bridge and a grey-slate town on a gravel ridge. On the river below the bridge, weirs of ash stakes stand with half their stakes gone. An old house stands by itself at the bridge-end with an eel-trap over the door.".
  Observe square_scene at well_square when true "A square round a stone well, and on the well-head a great iron nail, and on the nail and on pegs and lines around it, things: a glove, a child's shoe, a brass button, a hat, a doll with one eye, a dog-collar with no dog. The Lost Nail. Everything found in the street is hung here so it stays; and these days, every Return nobody has claimed.".
  Observe quay_scene at quay when true "The Peleth mole runs out into the estuary. Salt pans steam on the flats beyond. A Hartmark grain ship lies at the quay with a crowd of salt-boilers watching it unload, not kindly. Eelers mend tackle on the steps.".
  Observe cemetery_scene at cemetery when true "The cemetery runs along the ridge above the river. A grave-caller in a black coat walks the rows reading names aloud from a book, unhurried. His round ends at a stone near the gate: MARRA COYLE, and two dates of death, 2588 and 2679, and under them a line in Calvessan: calve calve. Kept twice.".
  Observe court_scene at courtroom when not deedsBack(pennick) "The Keepstone Court: a high room of grey stone, benches, a bar, and on the shelves behind the judge's chair hundreds of keepstone plates in rows, each in its slot, each labelled with a farm's name. You do not need to touch them to know: they are blank. A guard stands by the judge's door.".
  Observe consulate_scene at consulate when true "The Lusk consulate: a counting-house with a crest over the door, two desks, files to the ceiling. A brown dog sleeps by the stove and thumps its tail for anyone who comes in.".
  Observe counting_scene_w at counting_room when true "A Peleth counting-house on the quay: a bank, a chandlery and a shipping office in one long room. Clerks, ledgers, a strongroom door, and through the back window a coal yard.".
  Observe coyle_scene at coyle_kitchen when true "The Coyle house: a kitchen with a smoke-loft for eels over it, gone cold, and a lens-grinder's bench by the window that nobody has used in ninety years and nobody has moved.".

  // The Lusk consul's secretary, whom everyone remembers as having held the post for eleven years.
  Person webb "Corin Webb" at consulate {
    Role "secretary to the Lusk consul". Ancestry human. Calling thief. Level 3. Peaceable.
  }
  Observe dog_ignores at consulate when at(webb, consulate) and able(webb) and not webbNamed(webb) and not knows(party, dog_noticed) "The brown dog by the stove looks up when anyone moves: the consul, a clerk, you. When the secretary gets up and crosses the room, it does not look up at all. It does not even seem to know he is there." teaches dog_noticed.
  Discovery dog_noticed "The consulate's dog does not notice Corin Webb at all.".
  Observe webb_mutters at consulate when at(webb, consulate) and able(webb) and not webbNamed(webb) and knows(party, dog_noticed) and knows(party, stray_syllables) and not knows(party, webb_is_stray) "Webb bends over his letters. Under his breath, when he thinks nobody is listening, he is saying one syllable, over and over, the way the Strays at Keld do." teaches webb_is_stray.
  Observe webb_seen_through near party when knows(party, webb_wrong_face) and knows(party, payroll_known) and not knows(party, webb_is_stray) "Teshen's tall secretary with the cough; the payroll with Absalom Prew on it until seven months ago and Corin Webb after it with no letter of appointment; the man in the hospice whose name nobody can keep. Corin Webb did not come to the consulate. He came into someone's place." teaches webb_is_stray.
  Discovery webb_is_stray "Corin Webb is a Settled Stray: something that came back from the grey with nothing, and has taken a real man's place so well that everyone remembers Webb in it, and nobody remembers the man.".
  Relation webbNamed(group). Measure syllables(group).
  Initially Set syllables(webb) to 1.
  Topic webb_talk with webb "Ask Corin Webb about his work" when not webbNamed(webb) once {
    Says "'Letters,' says Webb, with a pleasant, forgettable smile. 'The consul writes to Lusk, Lusk writes to the consul, and I write it all down so it stays.' He tidies a stack that is already tidy. 'I take an interest in old things. The Short Grey. The Keld. The grey country they came back from.' He says the last words slowly, tasting them. 'Eleven years I've been here. You'd think I'd be bored of it.'".
  }
  Action name_webb(actor: group, site: place) "Ask Teshen to give Corin Webb his own name and his own place, aloud" {
    Description "He is Corin, son of the reeve of Keld Hollow, who was in the far field when the fog came, and was never found.".
    Requires able(actor) and company(actor) and at(actor, site) and at(webb, site) and travelsWith(teshen, actor)
      and knows(actor, webb_is_stray) and knows(actor, hollow_missing) and not webbNamed(webb) and able(webb).
    Time 1.
    On success { Assert webbNamed(webb). }
    Result "Teshen goes and stands in front of the secretary's desk until he looks up. 'You're Corin,' she says. 'Son of the reeve of Keld Hollow. You were in the far field when the fog came, and they called and called.' Webb's pleasant face goes still. 'Your place is at Keld,' says Teshen. 'With us. There's a house. Come home.' For a moment nothing happens. Then the brown dog by the stove lifts its head, and looks at him, and growls; and the consul in the next room says, puzzled, 'Absalom?'; and Corin Webb puts his face in his hands.".
  }
  Rule prew_remembered when (webbNamed(webb) or not able(webb)) and state(nameless, unknown) {
    Assert state(nameless, known). Assert prewBack(nameless).
  }
  Relation prewBack(group).
  Rule webb_goes_home when webbNamed(webb) and at(webb, consulate) { Assert at(webb, keld_green). }
  Observe webb_at_keld_after at keld_green when webbNamed(webb) and at(webb, keld_green) "Corin of the Hollow is at Keld, splitting kindling at the door of an empty house that the hearth-moot has given him. He works slowly, like someone learning his own hands. Now and then he stops, as if listening for a word he used to say, and does not find it, and goes on.".
  Observe prew_home at long_ward when prewBack(nameless) and not knows(party, prew_reunited) "A woman in a good grey coat is sitting on the end bed of the long ward, holding the hands of the man who sits there, and both of them are crying, and the sisters have drawn the curtain round them as well as they can. 'Absalom,' she keeps saying, as if she could not say it often enough. 'Absalom Prew.'" teaches prew_reunited.
  Discovery prew_reunited "Absalom Prew is known again, and his wife has come for him.".

  // Webb's syllables. He takes the Short Grey record in the second week, if it is still in the hospice archive.
  Rule webb_takes_record when watch(clock) >= 1440 and at(short_grey, hospice_archive) and not webbNamed(webb) and able(webb) and not guarded(rook)
    says "From Wendhead, word comes down the valley road: there has been a theft at the hospice. A record from the archive. The prioress will not say which, and is very angry with someone." {
    Assert at(short_grey, limbo). Increase syllables(webb) by 1.
  }
  Relation guarded(group).
  Topic rook_webb with rook "Tell Prioress Rook what Corin Webb is" when knows(actor, webb_is_stray) and not guarded(rook) once {
    Says "The prioress hears you out with her hands folded. 'A pleasant man,' she says at last. 'I nearly let him read it.' She gets up. 'The Short Grey record goes into the strongbox under my bed tonight, and the key round my neck.' At the door she turns back. 'Do not say in the chamber what the fog said. Our manual says that. I always thought it was poetry.'".
    On discuss { Assert guarded(rook). }
  }

  // Judge Orla Pennick and the blank stones.
  Person pennick "Judge Orla Pennick" at courtroom {
    Role "judge of the Keepstone Court". Ancestry human. Peaceable.
  }
  Person court_guard "the judge's guard" at courtroom {
    Role "a guard at the judge's door". Ancestry human. Calling warrior. Level 2. Peaceable.
  }
  Topic pennick_ruling with pennick "Ask Judge Pennick about her ruling" when true once {
    Says "'I ruled that a blank stone proves nothing,' says the judge, 'because the alternative was letting whoever shouted loudest own the valley.' She gestures at the shelves. 'Half the land in the Wend is on those, and they have gone blank from the outside in, like frost going off a window. My own house is on one.' She looks at you over her spectacles. 'The law is a way of remembering on purpose. If the stones can't remember, then we must, and we're worse at it. Is there any way to read a dead stone? Nobody has been able to tell me.'".
  }
  Topic pennick_seam with pennick "Tell Judge Pennick that a blank stone reads again at the bottom of the low road" when knows(actor, seam_reads) and not lends(pennick, deeds, actor) and not deedsBack(pennick) {
    Says "The judge takes off her spectacles. 'A stone-reader told you this. Drunk.' She does not wait for you to answer. 'I have heard worse evidence in this room and ruled on it.' She takes a crate from under the bench, a dozen plates packed in straw, and sets it on the bar. 'Twelve deeds from the suits I have before me. Mine among them. If they come back readable, I will hear every case in the valley again, Keld and all, and the stones can say who is lying.' She holds your eye. 'Bring them back.'".
    On discuss { Assert lends(pennick, deeds, actor). Assert at(deeds, courtroom). }
  }
  Item deeds "a crate of the court's blank deeds" is blank_deeds at limbo owned by pennick.
  Relation deedsBack(group).
  Event deeds_returned near pennick when keeps(pennick, deeds) and itemKind(deeds, woken_deeds) "Judge Pennick lays her palm on the first plate and closes her eyes, and you watch her live a man walking a boundary in the hay. She goes through all twelve without a word. Then she sits back. 'The Hallows of Hesk did buy their low field from a Keld in 2650. The Keld were right about the Brookhouse meadow. The Pruetts have lied to my face for a year.' She laughs, once. 'And my house is mine.' She counts thirty silver out of the court's box onto the bar. 'For the carriage. A month, you said, before they go off again? Then I sit every day this month.'" then {
    Assert deedsBack(pennick). Increase quantity(party, gold) by 30.
  }
  Initially Assert wants(pennick, woken_deeds).

  // Bram Coyle, Wenna's grandson, and his drawer of Returns.
  Person bram "Bram Coyle" at coyle_kitchen {
    Role "last of the Coyle weir-holders". Ancestry human. Peaceable.
  }
  Topic bram_wenna with bram "Ask Bram Coyle about Wenna Coyle" when true once {
    Says "'Everybody asks,' says Bram, and answers anyway. 'My grandmother. She was keeper eight years, and on the night of the Unfall she went up to the Stake and down the Well and took the thing out of the ground and went, and the star went after her, and the Stake burned.' He wipes the bench with his sleeve, though it is clean. 'She was sixty-nine. People in the Stake ruins say she did it to steal the star. She did it so it would follow her and not stay. That's what we say in this house, anyway.'".
  }
  Topic bram_drawer with bram "Ask Bram Coyle about the drawer under the bench" when true once {
    Says "Bram pulls it open. Inside: a ring, a bill of sale for a boat, a child's tooth in a twist of paper, a keepstone plate, and a lens wrapped in chamois. 'Returns,' he says. 'They come back to the house. That ring was my great-great-grandmother's. That plate came up in an eel-trap in 2722, out of the river that comes from under the Well, and it reads, when every other stone in Wendmouth is blank.' He unwraps the lens and holds it to the window, and the window stands in it whole. 'Wenna's. The sixth of a set she ground for the Lusk surveyors in 2601, that she never delivered. It went with her in 2641. It came back on the doorstep in 2719.'".
    On discuss { Assert knows(actor, seam_reads). Assert knows(actor, lens_known). }
  }
  Discovery lens_known "Bram Coyle keeps Wenna Coyle's sixth lens, a flawless piece of Choir-glass, in his drawer of Returns.".
  Kind wenna_lens_kind "Wenna Coyle's lens, wrapped in chamois" is treasure worth 20 weighing 0.
  Item wenna_lens "Wenna Coyle's lens" is wenna_lens_kind at limbo owned by bram.
  Topic bram_lend with bram "Ask Bram Coyle for the loan of Wenna's lens" when knows(actor, lens_known) and not lends(bram, wenna_lens, actor) {
    Says "Bram turns the lens in his fingers, once over and once back. 'She kept it in the drawer with her mother's ring,' he says. 'Where she kept things so they'd stay.' He wraps it and holds it out. 'It went away once already. Bring it back.'".
    On discuss { Assert lends(bram, wenna_lens, actor). Assert at(wenna_lens, coyle_kitchen). }
  }
  // Through the lens, from Hornwake, the ribs of Hightown's underside; beside the Socket chart, the same ribs.
  Observe lens_and_chart near party when carries(party, wenna_lens) and carries(party, chart) and at(party, ?p) and inHornwake(?p) and not crashed(hightown) and not lost(hightown) and not knows(party, origin_known) "You hold Wenna's lens to your eye and find Hightown's underside, two and a half kilometres up: not a dark blot through this glass but granite, ribbed, rib after rib curving away like the inside of a bowl turned over. You count them. You unroll the Lusk chart of the Socket on a wagon-tail and count the ribs of the lake's bowl. Same count; same spacing; the same broken rib on the eastern side. The mountain was cut from that bowl." teaches origin_known.
  Relation inHornwake(place).
  Initially Assert inHornwake(horn_foot). Initially Assert inHornwake(hoist_feet). Initially Assert inHornwake(wagons). Initially Assert inHornwake(tail).

  // Clemence Ninepan, who holds the debt.
  Person clemence "Clemence Ninepan" at counting_room {
    Role "head of the Ninepan House". Ancestry human. Peaceable.
    Sells coal_order for 20 coin from 3.
    Sells eel_kit for 15 coin from 2.
    Buys droplet_sack for 60 coin.
  }
  Kind eel_kit "an eeler's diving kit: grease, weights, lines, a sealed lamp" is treasure worth 15 weighing 3.
  Topic clemence_link with clemence "Ask Clemence Ninepan about the link in the Well" when true once {
    Says "'Eleven hundred tonnes of deadiron lying on an anvil four hundred metres down,' says Clemence. 'The Registry says it's the Registry's under a contract of 1210. The Linkmoot says it's theirs. Hightown wants to hang it on the tail. I say salvage.' She smiles. 'None of us can lift it. I have a derrick on the rim and a survey crew below, and they tell me pulleys, and I tell them gods.' She closes a ledger. 'Coal, if you're going down. The Registry's buying, at my price.'".
  }
  Discovery hartmark_coin "The Ninepan ledgers show Hartmark silver changed into Corrow coin, every week since spring, for 'E. of H., wages to Teake's crew'." {
    Source ninepan_ledger "the Ninepan exchange ledger" at counting_room readable by party.
  }

  // Midwinter, for the rest of the country.
  Observe webb_gone_down near party when midwinter(corrow) and syllables(webb) >= 2 and not webbNamed(webb) and able(webb) and not knows(party, webb_epilogue) "At midwinter the Registry's roll has a new line in it: the consul's secretary, licensed for one, gone down the Peleth stair, purpose stated as 'study'. He has not come back up it." teaches webb_epilogue.
  Entity webb_epilogue: fact "Where Corin Webb went at midwinter.".
  Observe court_awake at courtroom when deedsBack(pennick) "The Keepstone Court: a high room of grey stone, benches, a bar, and shelves of keepstone plates behind the judge's chair. Twelve of them, on the bar, are awake.".
  Observe court_sitting at courtroom when deedsBack(pennick) "The court sits every day this month. A Keld witness and a farmer from the valley stand at the bar together with a plate between them, and the judge has her hand on it.".
}

data/adventures/let-one-remember/witness:
Module corrow "Let One Remember" {
  Description "What the company makes of the Corrow by what it is, a niche at Keld that is marked with how it is known, a way past the Old Silver that only a ranger reads, and a Finder who has never found anyone's.".

  // ── The count in this module ──────────────────────────────────────────────────────────────────────────────────────
  // Count: who is held in mind (a mountain's weight by its people, a hollow by its anchors, a man by a lamp). Keeper: the
  // Keld, who cannot forget, and a Registry that enters whatever is brought it. First page: the Lettings' Long Rite of
  // 412, what it was paid to let go. Price of reading: whoever says a name at the Seam is, a little, said back.

  // ── Voices: what each calling makes of the place ─────────────────────────────────────────────────────────────────
  Relation remChapel(group). Relation remField(group). Relation remTail(group). Relation remDesk(group).
  Relation remPlace(group). Relation remLedge(group).

  Rule voice_niche at keld_chapel when memberOf(?m, party) and hasCalling(?m, calling_cleric) and awake(?m) and at(party, keld_chapel) and not remChapel(party)
    says "{?m} goes round the wall as one goes round a roll, lips moving over the scratched names, and touches each sprig in passing. 'A skull for each, and a sprig for each,' {?m} says. 'And this one has a sprig and a lamp and no skull.' A stop. 'Somebody has been burying nobody for a very long time, with great care. I know the form for it. It is not an easy one to keep.'" {
    Assert remChapel(party).
  }
  Rule voice_field at west_field when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, west_field) and not remField(party)
    says "{?m} walks the length of the wall and comes back. 'No track in, no track out,' {?m} says. 'Grass not pressed in the middle in a hundred years. The sheep go round the place the way sheep go round a grave.' {?m} looks at the fork standing upright in the turf. 'Whatever stands here at dawn, it is not walking here.'" {
    Assert remField(party).
  }
  Rule voice_files at tail when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and at(party, tail) and not remTail(party)
    says "{?m} runs a thumb down the bright face of the newest cut. 'All from the east side,' {?m} says. 'Every stroke from the shoulder of a right-handed man who is tired.' A grunt. 'They leave the west face to last, and thin, so the link goes of itself. That is how I would drop a wall, if I had been told not to.'" {
    Assert remTail(party).
  }
  Rule voice_desk at consulate when memberOf(?m, party) and hasCalling(?m, calling_thief) and awake(?m) and at(party, consulate) and not remDesk(party)
    says "{?m} squats and looks at the legs of the secretary's chair, then at the legs of the desk. 'Chair's been sawn down two fingers,' {?m} says. 'Short man. The desk was made for a tall one.' A thumb goes to the blotter. 'Worn at the left, where a tall man's cuff drags. So whoever draws this wage is not the one who sits here.' {?m} straightens. 'Nicely done, whoever did it. I would have liked to meet him.'" {
    Assert remDesk(party).
  }
  Rule voice_place at mountain_place when memberOf(?m, party) and hasCalling(?m, calling_mage) and awake(?m) and at(party, mountain_place) and not remPlace(party)
    says "{?m} holds a palm out over the lip and takes it back. 'I would not call it a hole,' {?m} says. 'A hole is made by taking something out, and one can feel where it went. This has no edge of removal. It was never put in. It is the exact shape of a thing that was lifted, and I have no instrument for that.'" {
    Assert remPlace(party).
  }
  Rule voice_ledge at silver_sump when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, silver_sump) and not remLedge(party) and not fed(old_silver)
    says "{?m} goes down on one knee at the ledge and looks at the bones. 'Dog at the mouth, sheep behind it, the small ones along the wall,' {?m} says. 'It strikes where the water moves and nowhere else. It is blind.' Knuckles rap the rock on the far side. 'That dry shelf is wider than it looks. The stones on it have never been wet.'" {
    Assert remLedge(party).
  }

  // ── A thing only a ranger reads: the dry shelf ───────────────────────────────────────────────────────────────────
  // The Old Silver hunts the water. A company that has rations can feed it; a company with a ranger can go round it on the
  // shelf it does not feel, with no rations spent and nothing thrown. Anyone else may still fight, or pay with food.
  Action round_the_silver(actor: group, site: place, r: member) "Have {r} lead the company along the dry shelf, round the Old Silver" {
    Description "It strikes where the water moves. The shelf on the far side has never been wet, and does not carry the sound of feet.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, silver_sump) and at(old_silver, site) and not fed(old_silver)
      and memberOf(r, actor) and hasCalling(r, calling_ranger).
    Time 2.
    On success { Assert tolerates(old_silver, actor). }
    Result "{r} goes first, one hand flat to the wall, and you put your feet where {r} puts them. The water beside you is black and perfectly still; in it, a long pale shape turns its blind face toward the sound of the river, and toward the river only. You are past it before it has finished deciding. Behind you {r} lets out a breath. 'Eighty years in the dark,' {r} says. 'You would think it would be quicker.'".
  }

  // ── The niche: marked with how it is known ───────────────────────────────────────────────────────────────────────
  // At Keld a skull in a niche has a name scratched over it and a sprig of juniper. One niche has no skull. The mark over
  // it is aun: let, the thing as it is said. The Keld did not see Corin die, and they will not write that they did.
  Discovery corin_niche "In the Hold chapel at Keld one niche has no skull in it. Over it is scratched CORIN, and a word, aun. There is a sprig of juniper in it, and a lamp that has not been let go out." {
    Source niche_mark "the empty niche in the Hold chapel" at keld_chapel readable by party.
  }
  Observe niche_plain at keld_chapel when not knows(party, evidential_known) and not webbNamed(webb) and not nicheClosed(keld) "Among the skulls, one niche is empty. Over it, scratched as deep as any: CORIN, aun. A sprig of juniper lies in it, fresh, and beside the sprig a small lamp is burning, with a thumb-width of oil left in it, as it has every time anyone has looked.".
  Observe niche_read at keld_chapel when knows(party, evidential_known) and not webbNamed(webb) and not nicheClosed(keld) "Among the skulls, one niche is empty. Over it: CORIN, aun. Let: told, not seen. They did not see him go, and they will not write that they did, and they have kept a lamp at his niche for two hundred and twenty-five years in case the mark is wrong.".
  Observe niche_home at keld_chapel when webbNamed(webb) "Over the empty niche, someone has gone up with a chisel in the night and re-cut the last word of the mark. It now reads CORIN, calve: kept, seen with her own eyes. The sprig is still fresh. The lamp has been put out, the way it is when a thing is finished. Nobody at Keld will say who held the ladder.".
  Observe niche_closed at keld_chapel when nicheClosed(keld) "Over the empty niche the mark is the same, aun, and the lamp is out. The sprig has not been changed. Somebody has said an office here, and the chapel has the stillness of a room that has stopped waiting.".

  // The choice. A cleric may say the office for the dead and close it; or trim the lamp and let it be. The Keld cannot forget
  // Corin, and so they cannot mourn him. Closing it lets them. It also ends the vigil the reeve's house is built on.
  Relation nicheClosed(place). Relation nicheKept(place).
  Action close_the_niche(actor: group, site: place, c: member) "Have {c} say the office for the dead over the empty niche, and close it" {
    Description "The Keld do not close a niche while anyone could still be looked for. {c} could close this one, and it would be an act of mercy and of ending.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, keld_chapel) and knows(actor, hollow_missing)
      and memberOf(c, actor) and hasCalling(c, calling_cleric) and not nicheClosed(keld) and not nicheKept(keld) and not webbNamed(webb).
    Time 4.
    On success { Assert nicheClosed(keld). Set hire(teshen) to 0. }
    Result "{c} says it plainly, without the Keld's careful grammar, and when it is done puts out the lamp with a wetted finger. Nobody is in the chapel. By the time you are out on the green the whole of Keld knows, the way Keld knows things: every face that turns to you has been told. Mother Saska, at her door, does not speak. Teshen takes her hands out of her pockets and looks at them. 'Nobody is waiting,' she says. 'Nobody is waiting for anything. I do not know what I am for.' She says she will walk with you for nothing, and she looks, just then, nineteen.".
  }
  Action keep_the_niche(actor: group, site: place, c: member) "Have {c} trim the lamp, lay a fresh sprig, and say nothing" {
    Description "The lamp is not for the dead. It is for the chance that the mark is wrong.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, keld_chapel) and knows(actor, hollow_missing)
      and memberOf(c, actor) and hasCalling(c, calling_cleric) and not nicheClosed(keld) and not nicheKept(keld) and not webbNamed(webb).
    Time 1.
    On success { Assert nicheKept(keld). }
    Result "{c} turns the wick up with a thumbnail, tops the oil from the little can on the sill, and lays the sprig. Mother Saska is in the doorway; nobody heard her come. 'The last who did that wanted something,' she says. 'What do you want?' {c} says, truthfully, that {c} does not know. She considers this for a good while. 'Then it is a clean one,' she says, and goes away across the green without another word.".
  }
  Topic saska_niche with saska "Ask Mother Saska whom the empty niche is kept for" when knows(actor, corin_niche) and not knows(actor, saska_saw) once {
    Says "'Corin,' says Saska. 'The Hollow's reeve's son. I told you that.' She is looking at the fire, not at you. 'I told you my grandmother was over there. That is let. I will say a thing kept, since you ask me to the face.' She sets her hands on the chair-arms. 'I was eight. I stood on the drove road with the other children and I saw the smoke go up straight from every chimney of the Hollow, nine days, when there was no Hollow to go up from. I saw it. Calve.' She does not look at the niche, which is on the north wall behind her. 'A person who cannot forget does not say that to a stranger. I have never said it to Teshen. She will think I have been afraid all her life.' A pause. 'I have.'".
    On discuss { Assert knows(actor, saska_saw). }
  }
  Discovery saska_saw "Mother Saska saw, at eight, the smoke of the Hollow go up for nine days when there was nothing to burn. She calls it calve. She has not told Teshen.".

  // ── The Finder of Wendmouth: a contrast ─────────────────────────────────────────────────────────────────────────
  // Things come home in the Corrow now, and by an old by-law of Wendmouth every thing that comes home must be offered to
  // whoever lost it. Nobody wants any of it. The Finder has spent forty years being refused.
  Person finder "Odo Pannick, Finder of Wendmouth" at well_square {
    Role "the town's Finder, by a by-law of 1840 that nobody has repealed". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Greets "A stout man in a coat with eleven pockets, each with a label, who looks up from a ledger as if you were a thing that had come home. 'Lost anything?' he says, with no hope in it whatever.".
  }
  Topic finder_nail with finder "Ask Odo Pannick what is hung on the great nail" when true once {
    Says "'Property,' says the Finder, with enormous weariness. 'Property returned. It is my duty to offer each piece to the person who lost it, with a receipt in triplicate.' He takes a doll with one eye off a peg. 'This came back in March. I took it to Mrs Dunstan, who lost it. Mrs Dunstan said it was not hers. Hers had two eyes.' He hangs the doll on the peg. 'I have offered her this doll nine times. She says it is gaining weight.'".
  }
  Topic finder_refusals with finder "Ask the Finder whether anybody ever takes anything back" when true once {
    Says "'One man,' says Pannick. 'A glove. He claimed it with enormous dignity, signed in three places, and went out of the square wearing it on the wrong hand. He came back next morning to say it had been the wrong glove.' He looks at the nail, which is hung with coats and doors and a gravestone name. 'It is not that they do not want it. It is that it has come back changed, and so have they. What I deal in, sir, is not property. It is people's opinion of what they used to be.'".
  }
  Topic finder_bell with finder "Ask the Finder about the little bell in his drawer" when knows(actor, origin_known) or knows(actor, method_known) once {
    Says "He is slightly embarrassed, which in him is a visible event. 'A hand-bell,' he says. 'Brass, the size of a sheaf-measure, with a long figure cut into the side of it, like a man lying on a hill. It came home to the bar the winter before last. Nobody here ever lost it.' He opens the drawer a finger's width and shuts it. 'A tinker of the Lesser Instruments, up from Corran, offered me a crown for the brass. I said it was held for the owner. The owner is the reeve of some dale in the south, I am told, who has not written.' He frowns at the drawer.".
  }
  Topic finder_tinker with finder "Ask about the tinker from Corran" when true once {
    Says "'Collects,' says the Finder, with distaste. 'That is the verb. Not buys; they say collects. Brass buttons by the pound, and keys, and anything with a notch in it. He will not say what for. A man who will not say what for is the only kind of customer this town has not yet refused.'".
  }

  // ── Calvessan, and a woman who got it wrong ──────────────────────────────────────────────────────────────────────
  // The low road's marks are only the first place the grammar bites: it is how Keld talk to this day. A cleric hears it.
  Rule voice_grammar at keld_green when memberOf(?m, party) and hasCalling(?m, calling_cleric) and awake(?m) and at(party, keld_green) and knows(party, evidential_known) and not remGrammar(party)
    says "{?m} has been listening to the green for some time. 'They all do it,' {?m} says, surprised. 'Every sentence. The child with the ball said her ball was lost, and then said let, not kept. She did not see it go. Somebody told her.' {?m} watches the children play. 'It must be dreadful to be lied to, in that grammar.'" {
    Assert remGrammar(party).
  }
  Relation remGrammar(group).
}

data/adventures/liberty-of-the-ice/after:
Module pellam "The Liberty of the Ice" {
  // ── The morning after ─────────────────────────────────────────────────────────────────────────────────────────────
  // Before first light on the morning after the ice goes, what became of each of the Fair's people is told as the
  // city's news, whatever became of the hired. In a world that goes on, the city goes on from it.
  Query newsHour() means thawed(lisk) and thirdDay() and hour(clock) == 5 and inPellam().
  Rule news_bel when newsHour() and goslingWedsBel(gosling) once says "Of the alderman and the gin-woman: Hamnet Gosling and Isabel Ashby carried the Frozen Lamb's sign up Swan Stairs together at nine last night, between them, and hung it over the door of a house in the Cheaping, and have not been seen since. The wedding was landed at the Landing, the clerk says, at the very end, by the alderman himself, who shouted it." { }
  Rule news_thessaly when newsHour() and thessalyWedsNoll(thessaly) once says "Of the printer and the factor's daughter: Noll Brisket carried his press up Hay Stairs on a sledge at dusk, with his wife pushing, and has set it up in a cellar in Bankside, where the first thing it printed this morning was the Frost Gazette, signed for the first time with a name: T. BRISKET." { }
  Rule news_gosling_harker when newsHour() and goslingHarker(gosling) once says "Of the wedding: Alderman Gosling and his bride went home to Fleece Row after the Landing, and at midnight, they say, when the ice went, the alderman was seen alone on the bridge in his chain, looking down at it." { }
  Rule news_callow_free when newsHour() and callowAcquitted(callow) once says "Of the heretic: Magister Callow, discharged, slept the night at the Spotted Calf, and this morning was found in the taproom arguing with Nab Pollard that a promise binds only what a man knew, and that this was what he had meant all along." { }
  Rule news_callow_stocks when newsHour() and callowConvicted(callow) and not callowDead(callow) once says "Of the heretic: Magister Callow sat in the stocks till the crier's call, preaching, and walked off the ice on two watermen's arms, and stood on Swan Stairs to watch it go out, laughing until he coughed. 'There,' he said. 'Did I not tell you?'" { }
  Rule news_callow_slipped when newsHour() and callowSlipped(callow) once says "Of the heretic: Magister Callow, who left his hand to answer for him, was seen last on the Black Reach in the second night, preaching to the river. Nobody has seen him since. The watermen say the Lisk Wife took him. The watermen say a great many things." { }
  Rule news_gant_clink when newsHour() and gantSafe(gant) once says "Of the debtor: Sir Lionel Gant has been elected, by the debtors of the Clink, master of the Clink yard, an honour he accepted in a speech of forty minutes." { }
  Rule news_gant_free when newsHour() and gantFree(gant) once says "Of the debtor: Sir Lionel Gant walked up Swan Stairs at nine last night, a free man, owing nobody anything, and was seen at midnight on the bridge in his shirt-sleeves in the frost, cheering the ice." { }
  Rule news_gant_taken when newsHour() and gantTaken(gant) once says "Of the debtor: Sir Lionel Gant is in the Fleece Row compter for thirty coin, saying to anyone who visits him that it was three." { }
  Rule news_bear_dead when newsHour() and bearDead(absolute) once says "Of the bear: Hester Mabb sat all day at the bear-stake with the broken chain in her lap, and went up the North Road this morning alone." { }
  Rule news_bear_live when newsHour() and bearCalmed(absolute) and not bearDead(absolute) once says "Of the bear: Hester Mabb walked Absolute off the ice at dusk, the last of the Fair's beasts, and up the North Road toward the woods, with the chain hanging slack between them." { }
  Rule news_quarle_cream when newsHour() and quarleCream(quarle) once says "Of the Frost Company: Mr. Quarle has taken a shop in the Cheaping, QUARLE'S FROST-CREAMS, and means to keep an ice-house of river ice cut by the watermen, so that there shall be frost-cream in Pellam in August. It is, he says, a perpetual frost of a kind." { }
  Rule news_quarle_ruined when newsHour() and quarleRuined(quarle) once says "Of the Frost Company: Mr. Quarle's tub went out with the ice, and Mr. Quarle with nothing in his pockets but the secret of the third salt, which he has offered to anyone at the Exchange for a coin." { }
  Rule news_saffery when newsHour() and not safferyTaken(saffery) and (hiredFled(lisk) or hiredReleased(lisk)) once says "Of the Lisk Wife: Widow Saffery stood on the bridge all the time the ice was going out, with her lantern, and when it had gone, blew it out, and went in." { }
  Rule news_dickon when newsHour() and urselMet(dickon) and dickonGone(dickon) and not drownedMetWolves(lisk) and not travelsWith(ursel, party) once says "Of the Cobbs: a woman in a caped coat and a big soft-spoken man with a cough were seen going up the North Road together in the thaw before light, arguing." { }
  Rule news_handfast when newsHour() and handfastLanded(party) once says "Of yourself: you are married, landed, from here to the sea. Ursel Cobb has told four people already, and lied about it to three." { }
  Rule news_ursel_gone when newsHour() and urselGone(ursel) once says "Of Ursel Cobb: nothing. Nobody has seen her since the Glove Post. Which is, you suppose, how she would want it told." { }
}

Module pellam "The Liberty of the Ice" {
  // ── Absolute ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // A dancing bear, not tame, cold and cross, kept on the ice by Hester Mabb, who dances him for pennies at the
  // bear-stake. On the second morning he breaks his chain and goes to the ox. The Butchers' Company sends to Harker for
  // his wharf men to put him down by noon. Left alone, he goes down the Reach at dusk, and is out there in the night.
  Person hester "Hester Mabb" at bear_stake {
    Role "a bear-ward, small and weathered, in a coat of patches". Ancestry human. Peaceable. Pronouns she. Manner compassionate.
    Greets "'Mind his reach,' says Hester Mabb. 'He's not cross with you. He's cross with the cold.' The bear behind her sighs like a bellows.".
    Greets again "Hester Mabb nods to you from the bear-stake.".
  }
  Person absolute "Absolute" at bear_stake {
    Role "a brown bear on a chain, in a leather muzzle, as big as a cart" when not bearLoose(absolute).
    Role "a brown bear, loose, with a yard of broken chain dragging" when bearLoose(absolute).
    Species bear. Peaceable. Pronouns he.
  }
  Relation bearLoose(group). Relation bearCalmed(group). Relation bearDead(group). Relation bearLent(group). Relation bearOnReach(group).
  Relation bearAtWedding(group). Relation bearTried(group).
  Observe stake_scene at bear_stake when not bearLoose(absolute) and not bearDead(absolute) and at(absolute, bear_stake) "The bear-stake, at the edge of the Fair: an iron stake hammered into the ice, a ring, a chain, and on the end of it a brown bear the size of a cart, swaying from foot to foot in a leather muzzle, very slowly, like a man who has been waiting a long time for a coach.".
  Observe stake_empty at bear_stake when bearLoose(absolute) "The bear-stake: an iron stake in the ice, a ring, and a yard of broken chain.".
  Topic hester_absolute with hester "Ask Hester Mabb about her bear" when true once {
    Says "'Absolute.' She says it fondly. 'My father called him that because he would do absolutely nothing he was told. He'll dance for a fiddle and nothing else, and he'll come to honey, and to me.' She pulls her coat round her. 'He's eleven. He hates the cold. He hates the noise. He was a cub in a wood once, and he remembers. In the summer, when we're on the roads, he'll go into any river we come to and sit in it to the neck, like a bishop in a bath. He'd go to the water now if it wasn't stone.' She looks at the stake. 'If he gets off that, they'll kill him. Everybody knows that about a bear.'".
    On discuss { Assert knows(actor, bear_ways). }
  }
  Discovery bear_ways "Hester Mabb's bear Absolute will dance for a fiddle, and come to honey, and to her; and if he gets loose on the ice, people will kill him." {
    Known by hester.
  }
  Rule bear_breaks when secondDay() and hour(clock) >= 7 and not bearLoose(absolute) and not bearCalmed(absolute) and not bearDead(absolute)
    {
    Assert bearLoose(absolute). Assert at(absolute, ox_roast). Assert at(hester, ox_roast). Assert happened(ev_bear_breaks). }
  Entity ev_bear_breaks: fact "bear breaks".
  Rule bear_breaks_heard when happened(ev_bear_breaks) and inPellam() and not heardNews(ev_bear_breaks) says "Word comes down Freezeland Street at a run: the bear's off his chain at the bear-stake, and gone to the ox roast, and is eating the Butchers' Company's ox off the spit with his muzzle torn off, and nobody will go near him." { Assert heardNews(ev_bear_breaks). }
  Observe bear_at_ox at ox_roast when bearLoose(absolute) and at(absolute, ox_roast) "Absolute is at the ox. He has pulled the spit down and is lying on the sunken hearth in the steam with the ox between his paws, eating it, and making a sound like a cart going over cobbles. The Butchers' Company's men stand in a ring well back with poles and cleavers, saying what they will do. Hester Mabb stands nearer than any of them, holding out her hand and talking to him, and he is not listening.".
  // Each way of getting him back, one try.
  Action bear_honey(actor: group, site: place) "Hold the crock of honey out to Absolute, and walk backward to the stake" {
    Requires able(actor) and company(actor) and at(actor, site) and at(absolute, site) and bearLoose(absolute) and carries(actor, honey) and not bearCalmed(absolute) and not bearDead(absolute).
    Time 2.
    On success { Assert bearCalmed(absolute). Retract bearLoose(absolute). Assert at(absolute, bear_stake). Assert at(hester, bear_stake). Assert bearTried(actor). }
    Result "You take the cloth off the crock and hold it out at arm's length, and Absolute lifts his great head from the ox and smells it from twenty feet, and gets up. You walk backward. He comes after you, slowly, down Freezeland Street, through a crowd that flattens itself against the booths, with his nose a foot from the honey and Hester at his shoulder, all the way to the bear-stake, where she has the chain on him again before he has finished the first mouthful.".
  }
  Action bear_fiddle(actor: group, site: place) "Play Absolute the tune his ward plays him, and dance him back to the stake" {
    Requires able(actor) and company(actor) and at(actor, site) and at(absolute, site) and bearLoose(absolute) and craft(actor, craft_stage) and knows(actor, bear_ways) and not bearCalmed(absolute) and not bearDead(absolute).
    Time 2.
    On success { Assert bearCalmed(absolute). Retract bearLoose(absolute). Assert at(absolute, bear_stake). Assert at(hester, bear_stake). Assert bearTried(actor). }
    Result "Hester hums it to you, an old reel, and you take it up, voice or fiddle or a comb and paper borrowed off a boy, and at the fourth bar Absolute stops eating and stands up on his hind legs in the steam, enormous, and begins to turn, slowly, on the sunken hearth. You play him up Freezeland Street like that, dancing, the crowd clapping in time and then forgetting to clap, all the way to the bear-stake.".
  }
  Action bear_woodcraft(actor: group, site: place) "Go up to Absolute slowly, low, the way you would to a bear in a wood, and put the chain in Hester's hand" {
    Requires able(actor) and company(actor) and at(actor, site) and at(absolute, site) and bearLoose(absolute) and capable(actor, woodcraft) and not bearCalmed(absolute) and not bearDead(absolute) and not bearTried(actor).
    Time 2.
    Resolve check(actor, woodcraft, dc_fair).
    On success { Assert bearCalmed(absolute). Retract bearLoose(absolute). Assert at(absolute, bear_stake). Assert at(hester, bear_stake). Assert bearTried(actor). }
    On failure { Assert bearTried(actor). }
    Result "You go down on your heels and come at him from the side, not looking at him, slowly, talking low about nothing, the way you would come up on a bear at a carcass in a wood. He watches you with one small eye and goes on eating. When you are close enough to smell him you take up the broken chain and put it in Hester's hand, and she says something to him in a voice nobody else has heard her use, and he gets up and goes with her.".
    Otherwise "He watches you come with one small eye, and when you are still ten feet off he stands up, and you stop, and back off, and he lies down again. Not today.".
  }
  Action bear_hold(actor: group, site: place) "Take hold of Absolute's broken chain and hold him" {
    Requires able(actor) and company(actor) and at(actor, site) and at(absolute, site) and bearLoose(absolute) and not bearCalmed(absolute) and not bearDead(absolute) and not bearTried(actor).
    Time 1.
    Resolve check(actor, brawn, dc_hard).
    On success { Assert bearCalmed(absolute). Retract bearLoose(absolute). Assert at(absolute, bear_stake). Assert at(hester, bear_stake). Assert bearTried(actor). }
    On failure { Assert bearTried(actor). }
    Result "You get the chain round your forearm and set your heels in the ice and he pulls, once, and you hold, and he turns his head and looks at you in astonishment. Then Hester has the other end, and the two of you walk him back to the stake together with your arms aching to the shoulder.".
    Otherwise "You get the chain round your forearm and he pulls, once, and you are sitting on the ice ten feet away with all the breath gone out of you, and the Butchers' men are laughing.".
  }
  // Left alone: at noon Harker's wharf men come with boar-spears; Hester gets him away from the ox with the last of her
  // pennies' worth of tripe, and he goes off down the Reach, out of reach of everyone, and does not come back.
  Rule bear_runs when secondDay() and hour(clock) >= 12 and bearLoose(absolute) and not bearCalmed(absolute) and not bearOnReach(absolute)
    {
    Assert bearOnReach(absolute). Assert at(absolute, reach_head). Assert happened(ev_bear_runs). }
  Entity ev_bear_runs: fact "bear runs".
  Rule bear_runs_heard when happened(ev_bear_runs) and inPellam() and not heardNews(ev_bear_runs) says "At noon three of Harker's wharf men come down Freezeland Street with boar-spears, at the Butchers' Company's asking. Before they reach the ox, Absolute gets up off it, all at once, and goes away from them down the ice past the last booth, onto the Reach, at a long rolling run, with his broken chain jumping behind him, and Hester Mabb running after him calling, until she cannot run any more." { Assert heardNews(ev_bear_runs). }
  // Out on the Reach in the second night, he meets the searchers.
  Rule bear_meets_searchers when bearOnReach(absolute) and not bearCalmed(absolute) and secondDay() and hour(clock) >= 23 and not bearDead(absolute)
    {
    Assert bearDead(absolute). Assert searchersDiverted(lisk). Assert at(absolute, limbo). Assert happened(ev_bear_meets_searchers). }
  Entity ev_bear_meets_searchers: fact "bear meets searchers".
  Rule bear_meets_searchers_heard when happened(ev_bear_meets_searchers) and inPellam() and not heardNews(ev_bear_meets_searchers) says "Late in the night, from down the Reach, a roar, and dogs, and men shouting, and lanterns going every way at once over the ice. In the morning they say Harker's searchers met Hester Mabb's bear on the Black Reach in the dark, and ran, all three, and the dog with them, back to Hay Wharf, and would not go out again; and that the bear went on down the grey ice toward the hole that never freezes, and through it." { Assert heardNews(ev_bear_meets_searchers). }
  // Calmed, he can be lent for an evening's walk on the Reach while the searchers are on it.
  Topic hester_lend with hester "Ask Hester Mabb to bring Absolute for a walk on the Reach tonight, where Harker's searchers are" when bearCalmed(absolute) and knows(actor, dickon_night) and not bearLent(absolute) once {
    Says "She looks at you, and at the bear, and at the Reach. 'Harker's men,' she says. 'The ones with the spears.' She almost smiles. 'He'd like a walk. He hates them more than he hates the cold.' She scratches his ear through the muzzle. 'Ten o'clock, the head of the Reach. Not a hair of him hurt, mind, or I'll set him on you.'".
    On discuss { Assert bearLent(absolute). }
  }
  Rule bear_walks when bearLent(absolute) and searchNight() and secondDay() and not bearDead(absolute) and not searchersDiverted(lisk) and at(searchers, black_reach)
    {
    Assert searchersDiverted(lisk). Assert bearWalked(absolute). Assert happened(ev_bear_walks). }
  Entity ev_bear_walks: fact "bear walks".
  Rule bear_walks_heard when happened(ev_bear_walks) and inPellam() and not heardNews(ev_bear_walks) says "At ten, out on the Reach, Hester Mabb walks her bear past Harker's searchers on a long chain, very slowly, humming, and Absolute stands up on his hind legs in their lanterns and looks at them; and the searchers decide, all three, that the drowned can wait, and go back to Hay Wharf to sit by Fowke's brazier, and stay there." { Assert heardNews(ev_bear_walks). }
  Relation bearWalked(group).
}

data/adventures/liberty-of-the-ice/calli:
Module pellam "The Liberty of the Ice" {
  Description "What each member of the company makes of the Fair by what they are: the cleric at the Saint's scales, the warrior at the Ring, the thief on the rope-walk's boards, the ranger on the tracks at the Reach, the mage under the Glove, the bard on the Liars' Bench; and two things only a particular calling can do: lift the Lisk Wife's lantern, or lift her floor.".

  // The preset party is not a set of declared people, so it has no Remarks of its own. What a rule can ask of a member
  // is their calling, and print their name. Said once for the company by whoever it has of the calling; a company
  // without a ranger has no one to read the tracks, and must read them itself (frosts.kyr, `wolf_tracks`).
  Relation heardCandle(group). Relation heardRing(group). Relation heardGlove(group). Relation heardHatch(group).
  Relation heardTracks(group). Relation heardBench(group).

  // ── The cleric: the pound of wax ──────────────────────────────────────────────────────────────────────────────────
  // Any company can be told by the verger that Harker pays for a pound of wax every spring, "for the weight". Only a
  // cleric knows what office that is. It is not a pardon. It is what is lit for a thing that cannot be put back.
  Discovery candle_office "The pound of wax Master Harker burns each spring before the Saint's scales is the office called the Weight, which is lit for a thing that cannot be put back, and which asks for no pardon.".
  Rule voice_candle at evenhands when memberOf(?m, party) and hasCalling(?m, calling_cleric) and awake(?m) and at(party, evenhands) and knows(party, harker_candle) and not heardCandle(party)
    says "{?m} stands a while before the Saint's scales with a hand flat on the cold beam. 'A pound of wax, a week, every spring after the hiring,' {?m} says. 'I know that office. A fault you confess and are given a weight to carry. This is what you light for a thing you cannot put back. It is called the Weight, because that is what it says: here is a weight I cannot lay down.' The hand comes away. 'He is not asking to be forgiven. He is paying rent.'" teaches candle_office {
    Assert heardCandle(party).
  }
  Relation harkerWeighed(group).
  Topic harker_weight with harker "Tell Master Harker that you know what a pound of wax before the Saint's scales is for" when knows(actor, candle_office) and not harkerWeighed(harker) once {
    Says "He does not turn his ring. It is the first time you have seen his hands do nothing. 'The verger talks,' says Master Harker, 'because nobody has asked him not to.' He looks, for a moment, not at you but at the brass scales on his own wall. 'Rent,' he says. 'Yes. It would be paid in a different coin if I knew to whom it was owed.' The quarter-inch of his bow is back. 'Do not tell me the price of a thing you cannot refund. I have heard it at every hiring for nineteen years, from the other side of the rope.'".
    On discuss { Assert harkerWeighed(harker). }
  }

  // ── The warrior: the Ring ─────────────────────────────────────────────────────────────────────────────────────────
  Rule voice_ring at hiring_ring when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and at(party, hiring_ring) and hiringOn() and not heardRing(party)
    says "{?m} watches Harker go round the rope, and what he passes over. 'The lame girl,' {?m} says, low. 'The clever-looking boy with the spectacles on a string. He wants shoulders, wrists, backs that will not argue.' A long breath. 'I have been picked like that. By a sergeant filling a rank. That is not a man hiring for a farm.'" {
    Assert heardRing(party).
  }

  // ── The mage: the Glove ───────────────────────────────────────────────────────────────────────────────────────────
  Rule voice_glove at freezeland when memberOf(?m, party) and hasCalling(?m, calling_mage) and awake(?m) and at(party, freezeland) and not iceGone() and not heardGlove(party)
    says "{?m} walks once round the foot of the mast with head back, watching the great leather fingers turn. 'Left glove,' {?m} says. 'And the Reeve has shaken with her right all morning. The sign and the hand do not match. I should like to know which of them is older.'" {
    Assert heardGlove(party).
  }

  // ── The bard: the bench ───────────────────────────────────────────────────────────────────────────────────────────
  Rule voice_bench at lamb when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, lamb) and not iceGone() and not heardBench(party)
    says "{?m} sits with an ear turned to the room for a quarter of an hour, counting on one finger under the table. 'Eleven lies since we sat down,' {?m} says. 'Nine of them end on something small and true, a name or a price, set at the back where you would trip on it. Broom is not listening for the lie. Her eyes are shut for the flinch.'" {
    Assert heardBench(party).
  }

  // ── The ranger: the road the wolves keep to ───────────────────────────────────────────────────────────────────────
  // Said, and not explained. The Book of Frosts has the wolves in four frosts of seven and nobody has ever written down
  // why; a ranger can say only what is wrong with the ground.
  Rule voice_tracks at reach_head when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, reach_head) and secondDay() and not dark() and not heardTracks(party)
    says "{?m} goes down on one knee at the edge of the sledge road and lays a bare palm in a print. 'Four,' {?m} says. 'Each one put its foot in the track of the one before. Hounds do that behind a huntsman. Wolves, in my experience, do not.' {?m} lifts the hand and wipes it on the snow. 'And they have kept to the sledge marks, on the ice, in the dark, down a road they could not have seen from the downs. Somebody has been teaching them the way.'" {
    Assert heardTracks(party).
  }

  // ── The thief: the board that is not nailed ───────────────────────────────────────────────────────────────────────
  Discovery hatch_suspected "At the end of the rope-walk house on the bridge one board is worn at the edge by a thumb, and the rope-ends are swept away from it: it is not nailed.".
  Rule voice_hatch at saffery_shop when memberOf(?m, party) and hasCalling(?m, calling_thief) and awake(?m) and at(party, saffery_shop) and not heardHatch(party)
    says "{?m} walks the length of the rope-walk heel and toe, eyes down, and stops at the far end by a board that is no different from the rest. 'Boards,' {?m} says, very low, 'are nailed or they aren't. That one has a thumb-worn edge and the hemp swept off it. She has walked backward the length of this room twelve hundred times and never once across it.' {?m} straightens. 'There is a hatch. I could have it up before her wheel has turned twice.'" teaches hatch_suspected {
    Assert heardHatch(party).
  }
  // The company is offered two doors to the same cellar. The thief's is quick, and it is a door nobody asked about.
  Relation safferyAffronted(group).
  Action thief_lifts_hatch(actor: group, site: place, m: member) "Have {m} lift the loose board at the end of the rope-walk while Widow Saffery's wheel is turning" {
    Description "A quick way to a cellar you were not shown. The widow has not been asked, and will know it.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, saffery_shop) and at(saffery, saffery_shop) and memberOf(m, actor) and hasCalling(m, calling_thief) and awake(m)
      and knows(actor, hatch_suspected) and not knows(actor, starling_known) and not safferyTrusts(saffery) and not safferyAffronted(saffery).
    Time 1.
    On success { Assert knows(actor, starling_known). Assert safferyAffronted(saffery). }
    Result "{m} is on one knee at the far end before the wheel has gone the length of the room and back. The board comes up with a sound like a held breath: a ladder, straw, a smell of river, and a girl's face with straw in her hair looking up. 'You'll not tell,' says Polly Sneath, and this time it is not quite a question. The wheel has stopped. Widow Saffery stands at the other end of her room with the cord hanging from her hands, and looks at you for as long as it takes the cord to stop swinging, and then goes on spinning, backward, away from you, and does not speak. {m} puts the board back. It does not lie as flat as it did.".
  }

  // ── The cleric, again: the Lisk Wife's office ─────────────────────────────────────────────────────────────────────
  // THE calling-unique way through the searchers. Gold buys them, a lie to Kemble sends them, a fight breaks them; but
  // the watermen who walk for Harker are watermen, and every one of them has left the Lisk Wife a penny. A cleric can
  // give her what she has walked the Reach for thirty-one winters to be given: the words for her son, said at the hole.
  // She does not stop looking. She stops looking alone. And the lanterns that come down the Reach stop at the edge of
  // hers. This is the grave scene of a farce.
  Relation officeRead(place).
  Discovery saffery_office "The office for the drowned has been said for Davy Saffery at the hole on the Black Reach, by someone with the right to say it, and the Lisk Wife has asked the company to walk with her.".
  Action read_office(actor: group, site: place, m: member) "Have {m} say the office for the drowned at the black hole, for Davy Saffery, with his mother holding the lantern" {
    Description "Thirty-one winters, and nobody has said the words. They are not long. It will take an hour in the cold, and it cannot be hurried.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, black_reach) and at(saffery, black_reach) and dark() and knows(actor, saffery_davy)
      and memberOf(m, actor) and hasCalling(m, calling_cleric) and awake(m) and not officeRead(lisk) and not safferyAffronted(saffery) and not safferyTaken(saffery) and not iceGone().
    Time 6.
    On success { Assert officeRead(lisk). Assert knows(actor, saffery_office). }
    Result "Widow Saffery does not turn the lantern down. She holds it out over the black water at the length of her arm, and {m} kneels on the ice at the rope with no book, and says the office for the drowned in the plain voice of someone who has said it for strangers before, and means it for this one. Davy. Nine. A bone skate on one foot. In the middle, where the words ask the water to give up what it holds or else to keep it kindly, a second light comes up beside the lantern, small and low, the height of a child's hand; and stays; and at the last word is not there. Widow Saffery has not moved. 'Well,' she says, after a long time, in the voice of the rope-walk. 'He was always slow to go to bed.' She does not stop walking the Reach. She says, 'Tomorrow night, if you are going down it, come with me.'".
  }
  // The lone company's way: a bard has no office, but has a wake-song, and the Lisk Wife has heard worse. It is said for
  // her son by someone with no right to say it, at the hole, and it costs: three coin laid on the ice as the watermen lay
  // pennies, and the widow, who knows what was and was not the office, does not speak to them again. The searchers stop at
  // her light all the same. No second light comes up; the skate is carried in and the hook is left empty.
  Relation officeSung(place).
  Action sing_office(actor: group, site: place, m: member) "Have {m} sing a wake-song for Davy Saffery at the black hole, having no office to say, and lay three coin on the ice" {
    Description "It is not the words. It is what a stranger has, and the Lisk Wife will know the difference.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, black_reach) and at(saffery, black_reach) and dark() and knows(actor, saffery_davy) and quantity(actor, gold) >= 3
      and memberOf(m, actor) and hasCalling(m, calling_bard) and awake(m) and not officeRead(lisk) and not safferyAffronted(saffery) and not safferyTaken(saffery) and not iceGone().
    Time 6.
    On success { Assert officeRead(lisk). Assert officeSung(lisk). Assert safferyAffronted(saffery). Decrease quantity(actor, gold) by 3. }
    Result "{m} sings it low, the one the Garthwaite women sing at a wake, with the verse for a drowned child that the Row sings when a drover's child goes under. It is a good song. Widow Saffery holds the lantern out over the black water and does not turn her head. At the end {m} lays three coin on the ice, as the watermen lay pennies, and she looks at them. 'That is a wake-song,' she says. 'It is not the office.' She takes the lantern in, close to her chest. 'He was never waked. You have been kind.' She says nothing else, and walks the Reach away from you, and does not look back.".
  }
  // Said, she walks the Reach by the lantern and not alone; Harker's men are watermen's sons, and stop at the edge of her light.
  Rule lisk_wife_walks when officeRead(lisk) and searchNight() and not searchersDiverted(lisk) and not iceGone() and able(searchers) {
    Assert searchersDiverted(lisk).
  }
  Observe lisk_wife_light at black_reach when officeRead(lisk) and searchNight() and at(saffery, black_reach) and dark() and not iceGone() "Down the Reach three lanterns come on in a line, walking slowly, and a dog. They come as far as the rim of the old woman's light and stop there as men stop at the edge of a church floor. One of them takes off his cap. A penny is laid on the ice. Without a word the lanterns turn about, and go back the way they came, and the dog goes with them, looking over its shoulder. Widow Saffery has not looked up.".
}

data/adventures/liberty-of-the-ice/callo:
Module pellam "The Liberty of the Ice" {
  // ── Magister Edrin Callow, a teacher of the Flow ──────────────────────────────────────────────────────────────────
  // Sixty, consumptive, vain, generous, a mimic. He preaches on the ice that nothing stays, and that no hand binds the
  // one who did not shake it: the man who shook yesterday is not the man who stands here today. The Court charges him
  // with unswearing, the one crime of the ice, on the first afternoon. The ice has no gaol. An accused is given into
  // the custody of a hand who shakes on producing him at the Landing; and nobody on the ice will shake for a man who
  // says that shaking means nothing. Unhanded, he goes in the stocks at the Glove Post until the Landing.
  Person callow "Magister Edrin Callow" at freezeland {
    Role "a thin old preacher in a black gown gone green, coughing, with a crowd" when not callowCharged(callow).
    Role "a preacher of the Flow, charged with unswearing" when callowCharged(callow).
    Ancestry human. Calling cleric. Level 2. Peaceable. Pronouns he. Manner jovial.
    Greets "The old preacher stops in the middle of a sentence and looks at you with bright, delighted eyes, as at a new argument. 'Ah! A face that has not yet made up its mind. Come here. I have something to unteach you.'".
    Greets again "Callow coughs, and smiles at you, as at a continuing argument.".
  }
  Relation callowCharged(group). Relation callowHand(group). Relation callowStocked(group). Relation callowSlipped(group).
  Relation callowAcquitted(group). Relation callowConvicted(group). Relation callowDead(group). Relation callowPreached(group).
  Relation saidBinds(group). Relation saidChanges(group). Relation saidKnowing(group). Relation callowAsks(group). Relation callowHeard(group).
  Relation knowingDoctrine(place).
  Rule callow_preaches when firstDay() and hour(clock) >= 9 and hour(clock) < 16 and not callowCharged(callow) and not at(callow, freezeland) { Assert at(callow, freezeland). }
  Observe callow_sermon at freezeland when at(callow, freezeland) and not callowCharged(callow) "At the foot of the Glove Post, on an upturned keg, a thin old man in a green-black gown is preaching to a crowd that laughs and shouts back. 'Look under your feet!' he cries. 'This is a river! Yesterday it ran; tomorrow it will run; today you have built a street on it and called it a country and made a law for it. Nothing stays, my friends. Not this ice, not that glove, not the man who shook hands with you on Monday. He is gone! He went out with the river! Why should you pay his debts?' A waterman throws a snowball at him. He catches it, and eats it.".
  Topic callow_teaching with callow "Ask Magister Callow what he teaches" when true once {
    Says "'The Flow.' He coughs into a handkerchief and folds it away. 'Nothing stays. Everyone knows it and no one believes it.' He taps your chest. 'The one who shook hands with the watermen this morning: where is he? You are someone else now, a little, who remembers being him, and the Reeve will make you pay his pennies.' He beams. 'The Court of the Ice does not find that funny. This afternoon I am to be charged with unswearing, for saying as much to some watermen who owe the Company money. It is the only crime on the ice, and I am rather proud of it.' He looks down at the ice under his boots, grey and thick and full of bubbles, like old glass. 'I shall not see it go out, I think. That is all right.'".
    On discuss { Assert callowHeard(actor). }
  }
  // At four on the first day, at the Court, Tredgold's Company charges him.
  Rule callow_charged when firstDay() and hour(clock) >= 16 and not callowCharged(callow) and not iceGone() {
    Assert callowCharged(callow). Assert at(callow, court). }
  Observe callow_in_court at court when callowCharged(callow) and firstDay() and hour(clock) >= 16 and hour(clock) < 17 and not callowHand(party) and not callowStocked(callow) "Magister Callow stands before the trestle, coughing, charged by the Watermen's Company with unswearing. 'There is no gaol on the ice,' says Justice Broom, through her trumpet, to the benches. 'Who'll be his hand? Who'll shake on bringing him here at the Landing?' Nobody moves. A man at the back laughs. Callow looks along the benches, mildly interested, as if it were a question in logic.".
  Entity callow_bargain: bargain "to bring Magister Callow to the Landing".
  Action shake_callow(actor: group, site: place) "Stand up and shake the Reeve's hand, to be Callow's hand until the Landing" {
    Grave "A hand shaken on the ice binds: shake to be Callow's hand, and if he is not at the Landing, the Court will have it of you.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, court) and callowCharged(callow) and at(callow, court) and at(broom, court)
      and not callowHand(actor) and not callowStocked(callow) and not iceGone().
    Time 2 minutes.
    On success { Assert callowHand(actor). Assert shook(actor, callow_bargain). Assert acceptsEscort(callow, actor). Assert following(callow, actor). }
    Result "You stand up. The benches turn round to look at you. Justice Broom puts out her small hard hand over the trestle and you shake it. 'Callow's hand,' she says, 'until the Landing. Bring him here at two on the last day, or answer for him.' Behind you Magister Callow is laughing so hard that he has to sit down. 'You have just shaken,' he says, wiping his eyes, 'to keep a man who says that shaking binds nobody. You see my difficulty. You see yours.' He takes your arm. 'We shall have a great deal to talk about.'".
  }
  Rule callow_stocked when firstDay() and hour(clock) >= 17 and callowCharged(callow) and not callowHand(party) and not callowStocked(callow)
    {
    Assert callowStocked(callow). Assert at(callow, freezeland). Assert happened(ev_callow_stocked). }
  Entity ev_callow_stocked: fact "callow stocked".
  Rule callow_stocked_heard when happened(ev_callow_stocked) and inPellam() and not heardNews(ev_callow_stocked) says "Nobody would be Callow's hand. At five the watermen put him in the stocks at the foot of the Glove Post, in the frost, with a blanket and a brazier, until the Landing; and he preaches from them to whoever passes, between coughs." { Assert heardNews(ev_callow_stocked). }
  Thing stocks "the stocks at the Glove Post" at freezeland is scenery {
    State empty "At the foot of the Glove Post stand the Court's stocks, empty.".
    State holding "At the foot of the Glove Post Magister Callow sits in the stocks with his ankles through the holes, a blanket round him and a brazier at his feet, coughing, and preaching the Flow to whoever stops.".
  }
  Initially Assert state(stocks, empty).
  Rule stocks_fill when callowStocked(callow) and state(stocks, empty) and not callowDead(callow) { Assert state(stocks, holding). }
  // In the stocks two nights in the frost, a consumptive old man may not see the Landing.
  Rule callow_frozen when callowStocked(callow) and secondDay() and hour(clock) >= 4 and hour(clock) < 6 and not callowDead(callow) and not callowFed(callow)
    {
    Assert callowDead(callow). Assert state(stocks, empty). Assert at(callow, limbo). Assert happened(ev_callow_frozen). }
  Entity ev_callow_frozen: fact "callow frozen".
  Rule callow_frozen_heard when happened(ev_callow_frozen) and inPellam() and not heardNews(ev_callow_frozen) says "In the small hours of the last day, in the stocks at the foot of the Glove Post, Magister Edrin Callow stopped coughing. The watermen found him at first light with his blanket round him and his brazier out, and the snow not melting on his face. Someone has written on the board at the foot of the Glove, under KEEP WHAT YOU SHAKE ON, in charcoal: NOTHING STAYS." { Assert heardNews(ev_callow_frozen). }
  Relation callowFed(group).
  Action tend_callow(actor: group, site: place) "Bring Magister Callow in the stocks hot gin, a second blanket, and coal for his brazier" {
    Requires able(actor) and company(actor) and at(actor, site) and at(callow, site) and callowStocked(callow) and not callowFed(callow) and quantity(actor, gold) >= 2.
    Time 1.
    On success { Decrease quantity(actor, gold) by 2. Assert callowFed(callow). }
    Result "He takes the gin in both hands. 'You realise,' he says, 'that the man you are being kind to will not exist by morning, and you will never be thanked by him.' He drinks. 'Thank you.' He coughs for a long time, and then sleeps, sitting up, in the second blanket, with the coal glowing at his feet.".
  }
  // With his hand, he goes where the company goes, and argues.
  Rule callow_follows when following(callow, party) and at(party, ?p) and not at(callow, ?p) and not callowSlipped(callow) and not callowDead(callow) { Assert at(callow, ?p). }
  Topic callow_question with callow "Let Magister Callow ask you his question" when callowHand(actor) and not callowAsks(actor) once {
    Says "He walks beside you with his arm through yours, coughing. 'Here is my question,' he says. 'Yesterday you were a stranger who had never seen Pellam. Today you are a person who has walked on its river and had its law cried at you and shaken on keeping an old heretic. Tomorrow you will be someone else again. Which of you is bound by the hand you gave the Reeve?' He stops in the middle of Freezeland Street. 'Think about it. I want your answer, and I want it to be yours, and not the Reeve's.'".
    On discuss { Assert callowAsks(actor). }
  }
  Topic answer_binds with callow "Tell Callow: the hand binds whoever gave it, changed or not" when callowAsks(actor) and not saidBinds(actor) and not saidChanges(actor) and not saidKnowing(actor) once {
    Says "'The Reeve's answer.' He nods, quite respectfully. 'And Pellam's, and Harker's, and every honest man's. A man is his promises. He changes, they stand still, and he is dragged along behind them like a dog behind a cart.' He walks on. 'Then I shall come to your Landing, since you are bound, and they will put me in the stocks, since I am guilty, and you will have been right.' He pats your arm. 'It is very comfortable, being right. I tried it for a week once.'".
    On discuss { Assert saidBinds(actor). }
  }
  Topic answer_changes with callow "Tell Callow: he is right; nobody is bound by who they were" when callowAsks(actor) and not saidBinds(actor) and not saidChanges(actor) and not saidKnowing(actor) once {
    Says "His face lights up like a boy's. 'Oh, good,' he says. 'Oh, very good. A convert, on the ice.' Then he stops, and looks at you more carefully. 'Then you'll not mind,' he says, 'when I am not at your Landing. The one who shook for me will be gone by then, you see. You will be somebody else, who never promised anything.' He laughs, and coughs. 'I would hate to be a hypocrite in front of a convert.'".
    On discuss { Assert saidChanges(actor). }
  }
  // A middle answer, which only someone who has seen a bargain shaken on a lie can give.
  Topic answer_knowing with callow "Tell Callow: a hand binds the one who shook it, if he knew what he was shaking on; a hand shaken on a lie about the thing itself binds nobody" when callowAsks(actor) and not saidBinds(actor) and not saidChanges(actor) and not saidKnowing(actor)
    and (knows(actor, hired_sold) or knows(actor, tansy_hired) or knows(actor, gant_altered)) once {
    Says "He stops walking. For a while he does not say anything at all, which you have not seen him do. 'That is not the Flow,' he says at last. 'And it is not the Reeve.' He takes his arm back and looks at it. 'It is a third thing. Nothing stays, but what a man knew when he gave his hand, that stays: it is the one thing that was really there.' He looks at you. 'You have been somewhere, to think of that. Somebody shook on a lie in front of you.' He takes your arm again. 'I'll come to your Landing,' says Edrin Callow. 'I'll argue that. It is better than mine.'".
    On discuss { Assert saidKnowing(actor). }
  }
  // On the second night, a man who has been told nothing binds him goes where he likes.
  Rule callow_slips when saidChanges(party) and following(callow, party) and secondDay() and hour(clock) >= 1 and hour(clock) < 5 and not callowSlipped(callow)
    says "In the small hours you wake, or look round, and Magister Callow is not there. On the place where he was sitting there is a scrap of paper in his hand: You are not the one who shook. Neither am I. Gone to preach to the river. E.C." {
    Assert callowSlipped(callow). Retract following(callow, party). Retract acceptsEscort(callow, party). Assert at(callow, black_reach). }
  Observe callow_on_reach at black_reach when callowSlipped(callow) and at(callow, black_reach) and not iceGone() "Out on the Black Reach, by the hole that never freezes, Magister Callow is preaching the Flow to the river, in his gown, with his arms out, and the river is listening.".
  Topic callow_come_back with callow "Ask Callow to come back to the Landing, for your hand's sake" when callowSlipped(callow) and at(callow, black_reach) and not callowReturned(callow) once {
    Says "'For your hand.' He looks at the black water. 'Not for mine. Mine is gone.' He pulls his scarf up over his mouth. 'Very well. The one who left you a note was a hypocrite, and the one standing here is a different man, and he will come.' He takes your arm. 'You see? It cuts both ways. That is the beauty of it.'".
    On discuss { Assert callowReturned(callow). Retract callowSlipped(callow). Assert following(callow, party). Assert acceptsEscort(callow, party). }
  }
  Relation callowReturned(group).
}

data/adventures/liberty-of-the-ice/clock:
Module pellam "The Liberty of the Ice" {
  // ── The three days of the ice ─────────────────────────────────────────────────────────────────────────────────────
  // Pellam's days are counted from the company's coming, at each dawn after the first hour it is here: the day it
  // comes is the first. The Landing is at two on the third day; the ice goes out in the third night.
  Measure dayN(place). Relation dawned(place).
  Initially Set dayN(lisk) to 1.
  Rule dawn_counts when hour(clock) == 6 and not dawned(lisk) and watch(clock) >= 6 { Increase dayN(lisk) by 1. Assert dawned(lisk). }
  Rule dawn_passes when hour(clock) != 6 and dawned(lisk) { Retract dawned(lisk). }
  // In a world that goes on, Pellam's own watch begins at the first morning after it is reached (what is left of the
  // evening it is reached on is nobody's day), so its first day begins then, and nothing of it happens before.
  Query firstDay() means dayN(lisk) == 1 and watch(clock) >= 0.
  Query secondDay() means dayN(lisk) == 2.
  Query thirdDay() means dayN(lisk) == 3.
  Query fourthDay() means dayN(lisk) == 4.
  Query morning() means hour(clock) >= 6 and hour(clock) < 12.
  Query evening() means hour(clock) >= 18 and hour(clock) < 23.
  Query smallHours() means hour(clock) >= 0 and hour(clock) < 5.
  // Winter: the lanterns are lit on the ice at four, and it is dusk on the Flashes from then till six.
  Query dusk() means hour(clock) >= 16 and hour(clock) < 18.
  Query lampLit() means hour(clock) >= 16 or hour(clock) < 7.
  // The nights the searchers walk the Reach: the second and the third, from ten until three. (A day runs from dawn
  // to dawn: the small hours after midnight belong to the day before.)
  Query searchNight() means (secondDay() or thirdDay()) and (hour(clock) >= 22 or hour(clock) < 3).
  // The Landing: the third day, from two until the last case is cried.
  Query landingDay() means thirdDay() and hour(clock) >= 14.
  // The ice goes out at midnight of the third night (earlier, if the watermen cut it).
  Query iceGone() means thawed(lisk).
  Relation thawed(place).

  // ── Where word reaches the company ────────────────────────────────────────────────────────────────────────────────
  // News of the Fair is heard anywhere in Pellam, on the bridge, on the ice or in Bankside; not out on the North Road.
  Query inPellam() means at(party, ?p) and not at(party, north_road) and not at(party, sledge_road) and not at(party, limbo).
  Query onIce() means at(party, ?p) and iceRoom(?p).
  Relation iceRoom(place).
  // What has happened in the city, and whether the company has heard it: news is heard in Pellam, late if it was away.
  Relation happened(fact). Relation heardNews(fact).
  // News already gone round, so it is not told twice.
  Relation spread(fact).
  // A place the company has left and come back to is told shortly.
  Relation visitedNow(place). Relation visitedBefore(place).
  Rule arrives_at when at(party, ?p) and not visitedNow(?p) { Assert visitedNow(?p). }
  Rule leaves_from when visitedNow(?p) and not at(party, ?p) { Retract visitedNow(?p). Assert visitedBefore(?p). }

  // ── The snow ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // Every road out of Pellam is shut by snow, and has been for a month: whatever is said here about the fells, the
  // farms, the hills or the south, nobody can go and see. That is what the Fair runs on.
  Discovery roads_shut "The roads out of Pellam have been shut by snow for a month, north to the fells and south over the downs. Nothing goes in or out but on foot, and nothing that is said about the far side of the snow can be gone and looked at until the thaw." {
    Known by nab, tredgold, ursel, bel, kemble, harker.
  }
}

data/adventures/liberty-of-the-ice/compa:
Module pellam "The Liberty of the Ice" {
  // The campaign played alone: a traveller with a light purse and no plans, coming down the North Road in the snow on
  // the third week of the Frost Fair. (placed.kyr is the world's own company, come in by the same road.)
  Company party "You" of 1 to 3 at north_road.
  Initially Set quantity(party, gold) to 20. Initially Set quantity(party, rations) to 2.
}

data/adventures/liberty-of-the-ice/con.k:
Module pellam "The Liberty of the Ice" {
  // ── The Squire of Hawsfold ────────────────────────────────────────────────────────────────────────────────────────
  // A claim Harker can be brought to believe, held as firmly as what stands behind it: words, and things he can hold.
  // Nothing in the world requires a claim to be true. He tests it against what he is shown, and against whoever he
  // meets; and every success of the lie makes the next harder: a squire believed is asked to supper, and to the
  // wedding, and a squire at a wedding gives a present.
  Entity squire_claim: claim "that the company is the Squire of Hawsfold, with two hundred fell ewes snowed in at Hawsfold".
  Query squireBelieved(h: group) means believes(h, squire_claim) and conviction(h, squire_claim) >= 4 and not squireExposed(party).
  Relation posedSquire(group). Relation squireTold(group). Relation shownTally(group). Relation shownGoodTally(group).
  Relation shownWool(group). Relation shownCoat(group). Relation shownLetter(group). Relation urselVouched(group).
  Relation invited(group).
  Topic pose_squire with harker "Tell Master Harker you are the Squire of Hawsfold, with two hundred fell ewes snowed in on the fells" when knows(actor, harker_buys) and (knows(actor, con_plan) or knows(actor, roads_shut)) and not posedSquire(actor) and not hiredHand(actor) and not squireExposed(actor) and not harkerWary(harker) once {
    Says "Harker's quarter-inch becomes half an inch. 'Hawsfold,' he says. 'Up under Swale Fell. I know the name.' He looks at your boots, and your coat, and your hands. 'Two hundred. Snowed in, you say, with the roads as they are.' He turns his ring. 'Then you'll be wanting to sell them to someone who can wait for the thaw.' He does not say that he believes you. He does not say that he does not.".
    On discuss { Assert posedSquire(actor). Assert believes(harker, squire_claim). Set conviction(harker, squire_claim) to 1. }
  }
  Action spin_hawsfold(actor: group, site: place) "Tell Harker about Hawsfold: the fell, the ewes, your late father, the snow" {
    Requires able(actor) and company(actor) and at(actor, site) and at(harker, site) and posedSquire(actor) and believes(harker, squire_claim)
      and not squireTold(actor) and not squireExposed(actor).
    Time 1.
    Resolve check(actor, deception, dc_fair).
    On success { Assert squireTold(actor). Increase conviction(harker, squire_claim) by 1. }
    On failure { Assert squireTold(actor). }
    Result "You give him Hawsfold: the long fell, the stone folds, your late father's temper and his Swaledale ewes, the snow coming down in October and the shepherd's boy walking down to the dale with the news, and the price of hay. You find you can see it. Harker listens with his head on one side, and at the end says, 'A hard country,' and something has gone out of his shoulders.".
    Otherwise "You tell him about Hawsfold, and somewhere in the middle you put a church where there isn't one, or a river the wrong way, and Harker says 'Indeed,' very politely, and you know he has noticed something, though not what.".
  }
  Action show_tally(actor: group, site: place) "Show Master Harker the printed tally of the flock" {
    Requires able(actor) and company(actor) and at(actor, site) and at(harker, site) and posedSquire(actor) and believes(harker, squire_claim)
      and carries(actor, tally) and not shownTally(actor) and not squireExposed(actor).
    Time 1.
    On success { Assert shownTally(actor). Increase conviction(harker, squire_claim) by 1. }
    Result "He takes the tally to the window and reads it down with his finger: ewes by age and mark, gimmers, tups, the fold, the last count. 'Printed,' he says. 'On the ice, I suppose.' He smiles, a real smile, the first. 'A man who has his flock printed is a man who means to sell it.'".
  }
  Action show_good_tally(actor: group, site: place) "Point out to Harker how the tally is ruled, as a factor's own" {
    Requires able(actor) and company(actor) and at(actor, site) and at(harker, site) and shownTally(actor) and tallyGood(lisk)
      and not shownGoodTally(actor) and not squireExposed(actor).
    Time 1.
    On success { Assert shownGoodTally(actor). Increase conviction(harker, squire_claim) by 1. }
    Result "You show him the columns: the ewes by their teeth, the clip weighed by the stone, the dip and the fold-mark, as a factor rules them. He looks at it again, longer. 'Whoever ruled this,' he says, 'has done business with me before.' Which is true, in a way he will not enjoy.".
  }
  Action show_wool(actor: group, site: place) "Give Master Harker a tuft of the fell wool to feel" {
    Requires able(actor) and company(actor) and at(actor, site) and at(harker, site) and posedSquire(actor) and believes(harker, squire_claim)
      and carries(actor, fell_wool) and not shownWool(actor) and not squireExposed(actor).
    Time 2 minutes.
    On success { Assert shownWool(actor). Increase conviction(harker, squire_claim) by 1. }
    Result "He rolls it between finger and thumb, and pulls a staple out, and holds it up against the window, and smells it. 'Swale grey,' he says. 'Fell-bred. Coarse, but it'll take a dye.' He gives it back to you as if it were a coin. Wool does not lie, Master Harker believes; and wool does not.".
  }
  Action show_coat(actor: group, site: place) "Let Master Harker see Sir Lionel's coat on your back" {
    Requires able(actor) and company(actor) and at(actor, site) and at(harker, site) and posedSquire(actor) and believes(harker, squire_claim)
      and carries(actor, gant_coat) and not shownCoat(actor) and not squireExposed(actor).
    Time 2 minutes.
    On success { Assert shownCoat(actor). Increase conviction(harker, squire_claim) by 1. }
    Result "You take the coat off and hang it on his chair-back while you talk, and he sees the London cut, and the lining, and the place where the buttons were silver once, and behaves from then on as if a gentleman were in the room.".
  }
  Action show_letter(actor: group, site: place) "Give Master Harker Alderman Gosling's letter commending you" {
    Requires able(actor) and company(actor) and at(actor, site) and at(harker, site) and posedSquire(actor) and believes(harker, squire_claim)
      and carries(actor, gosling_letter) and not shownLetter(actor) and not squireExposed(actor).
    Time 2 minutes.
    On success { Assert shownLetter(actor). Increase conviction(harker, squire_claim) by 1. }
    Result "He reads it, and reads it again, and folds it. 'Hamnet Gosling,' he says, 'is a fool about poetry and about nothing else,' which you take to be a compliment to the letter.".
  }
  Action ursel_vouches(actor: group, site: place) "Let Ursel, as your man of business, talk Harker through the terms" {
    Requires able(actor) and company(actor) and at(actor, site) and at(harker, site) and posedSquire(actor) and believes(harker, squire_claim)
      and travelsWith(ursel, actor) and not urselVouched(actor) and not squireExposed(actor).
    Time 1.
    On success { Assert urselVouched(actor). Increase conviction(harker, squire_claim) by 1. }
    Result "Ursel, who has become in the space of a doorway a dry, respectful, slightly bored person in a good cape called Mistress Cobb, talks terms: delivery at the shearing, at the fold, the clip by the stone, the old Squire's executors, a lien on the hay. She is so dull about it that Harker visibly relaxes. Nobody would invent anything so tedious.".
  }
  // Believed, the Squire is asked to supper, and to the wedding.
  Rule squire_invited when squireBelieved(harker) and not invited(party) and together(party, harker) says "'You'll sup with me,' says Master Harker. It is not a question. 'Tonight, at seven, Fleece Row. My daughter is to be married at the Ice Chapel on the last day, at noon, to Alderman Gosling; you'll do us the honour.' He inclines his head an inch. 'A Squire of Hawsfold at the wedding. My late wife would have liked that.'" { Assert invited(party). }

  // ── The props ─────────────────────────────────────────────────────────────────────────────────────────────────────
  Kind hawsfold_tally_kind "a printed tally of the Hawsfold flock" is gear worth 0 weighing 0 described "A tally of two hundred fell ewes at Hawsfold under Swale Fell, by age and mark, printed on the ice by Noll Brisket in a border of very small sheep.".
  Item tally "a printed tally of the Hawsfold flock" is hawsfold_tally_kind at limbo.
  Relation tallyOrdered(group). Relation tallyGood(place).
  Action order_tally(actor: group, site: place) "Have Noll print a tally of two hundred fell ewes at Hawsfold" {
    Requires able(actor) and company(actor) and at(actor, site) and at(noll, site) and (knows(actor, props_known) or knows(actor, con_plan)) and quantity(actor, gold) >= 3 and not tallyOrdered(actor).
    Time 2.
    On success { Decrease quantity(actor, gold) by 3. Assert tallyOrdered(actor). Retract at(tally, limbo). Assert at(tally, printing). }
    Result "Noll does not ask whose ewes. 'A tally's not sworn,' he says cheerfully, setting it. 'A tally's a list. I'll print a list of the angels if you pay for the ink.' He puts a border of little sheep round it, unasked, because he is pleased with them.".
  }
  Action rule_tally(actor: group, site: place) "Rule the tally's columns yourself, in a factor's terms, before Noll prints it" {
    Requires able(actor) and company(actor) and at(actor, site) and at(noll, site) and tallyOrdered(actor) and not tallyGood(lisk) and not ruleTried(actor).
    Time 2.
    Resolve check(actor, lore, dc_fair).
    On success { Assert tallyGood(lisk). Assert ruleTried(actor). }
    On failure { Assert ruleTried(actor). }
    Result "You make Noll pull it again with the columns ruled as a factor rules them: by the teeth, the clip by the stone, the dip and the fold-mark. It looks like something that has been in a counting-house for years.".
    Otherwise "You rule it again, and it looks, if anything, less like a factor's tally than before. Noll says it's lovely.".
  }
  Relation ruleTried(group).
  Kind wool_kind "a tuft of fell wool" is gear worth 0 weighing 0 described "A greasy grey tuft of fell wool, coarse and springy, smelling of sheep and peat-smoke.".
  Item fell_wool "a tuft of fell wool" is wool_kind at limbo.
  // There is also wool in the bondhouse, Harker's own; it would do as well.
  Item bond_wool "a tuft of fell wool" is wool_kind at bond_floor.

  // ── Abel Haws, of Hawsfold ────────────────────────────────────────────────────────────────────────────────────────
  // The real shepherd, come down through the snow to sell the real flock, who cannot lie and believes everything. There
  // is no squire at Hawsfold. There is Abel.
  Person abel "Abel Haws" at limbo {
    Role "a fell shepherd in a sheepskin, with a crook and a black-and-white bitch at heel". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "The shepherd takes off his hat to you, which nobody else in Pellam has done. 'Abel Haws,' he says, 'of Hawsfold, under Swale Fell. I'm looking for a man buys wool.'".
    Greets again "Abel Haws takes off his hat to you again.".
  }
  Person bess "Bess" at limbo {
    Role "a black-and-white sheepdog with one blue eye". Species dog. Peaceable. Pronouns she.
  }
  Relation abelInOnIt(group). Relation abelDiverted(group). Relation abelMetHarker(group). Relation flockReal(group).
  Relation abelSold(group). Relation abelWool(group).
  Initially Assert tattles(abel).
  Rule abel_comes when firstDay() and hour(clock) >= 12 and not abelCame(abel) { Assert abelCame(abel). Assert at(abel, cheaping). Assert at(bess, cheaping). Assert happened(ev_abel_comes). }
  Entity ev_abel_comes: fact "abel comes".
  Rule abel_comes_heard when happened(ev_abel_comes) and inPellam() and not heardNews(ev_abel_comes) says "A shepherd has come in over the North Bar out of the snow, with a crook and a black-and-white dog, asking the first person he meets in the Cheaping, very loudly, where a man might find a buyer for two hundred fell ewes, from Hawsfold, under Swale Fell." { Assert heardNews(ev_abel_comes). }
  Relation abelCame(group).
  Rule abel_day when abelCame(abel) and hour(clock) >= 8 and hour(clock) < 19 and not abelBusy() and not at(abel, cheaping) { Assert at(abel, cheaping). }
  Rule abel_night when abelCame(abel) and (hour(clock) >= 19 or hour(clock) < 8) and not abelOnHulk(abel) and not at(abel, calf_taproom) { Assert at(abel, calf_taproom). }
  Rule abel_hulk_night when abelOnHulk(abel) and (hour(clock) >= 21 or hour(clock) < 7) and not at(abel, patience_hold) { Assert at(abel, patience_hold). }
  Relation abelOnHulk(group).
  Rule bess_follows when at(abel, ?p) and not at(bess, ?p) { Assert at(bess, ?p). }
  // On the second morning everyone in the Cheaping has told him the man to see is Harker, and he goes to the Ring.
  Query abelBusy() means abelToRing() or abelToExchange().
  Query abelToRing() means secondDay() and hour(clock) >= 10 and hour(clock) < 11 and not abelDiverted(abel) and not abelSold(abel).
  Query abelToExchange() means secondDay() and hour(clock) >= 10 and hour(clock) < 12 and abelDiverted(abel) and not abelSold(abel).
  Rule abel_to_ring when abelToRing() and not at(abel, hiring_ring) { Assert at(abel, hiring_ring). }
  Rule abel_to_exchange when abelToExchange() and not at(abel, exchange_floor) { Assert at(abel, exchange_floor). }
  Topic abel_flock with abel "Ask Abel about his ewes" when true once {
    Says "'Two hundred Swale ewes, and the tups, and the gimmers, under Swale Fell at Hawsfold.' He says it as if it were a psalm. 'My father's, and his father's. Snowed in at the fold since Martinmas, and my sister's lad feeding them hay, and the hay going.' He turns his hat round in his hands. 'The fold's on the east side, where the beck comes off the fell and goes down to the Swale. I've come down to sell them on the hoof for the shearing, before the hay's gone and I've to sell them for their skins. Forty coin.' He looks at you hopefully. 'Everyone says the man to see is Harker.'".
    On discuss { Assert knows(actor, abel_flock_known). }
  }
  Discovery abel_flock_known "Abel Haws is the shepherd of Hawsfold under Swale Fell, and has two hundred fell ewes there, snowed in, which he has come down to Pellam to sell for forty coin. There is no squire at Hawsfold. Everyone has told him the man to see is Harker.".
  Topic abel_wool with abel "Ask Abel for a tuft of his wool" when not abelWool(abel) once {
    Says "'Take two.' He pulls a handful off his own sheepskin without thinking about it and pushes it into your hand. 'That's Hawsfold. Feel the spring in it.' He beams. 'You'd know it anywhere.'".
    On discuss { Assert abelWool(abel). }
  }
  // The second day: Harker, who is not a fool about wool, asks the Squire one thing about Hawsfold that a man who owned
  // it would know without thinking. A question put to the player; the right answer is Abel's.
  Relation harkerTested(group). Relation testAnswered(group).
  Event harker_tests near harker when (secondDay() or thirdDay()) and posedSquire(party) and squireBelieved(harker) and together(party, harker)
    and addressed(harker, party) and not harkerTested(party) and not squireExposed(party) "Master Harker turns his ring. 'Tell me,' he says, pleasantly, as one says it of the weather, 'which way does the beck run at Hawsfold? I had a drover once who swore it ran west, into the Lisk, and I have never been able to remember.' He waits. Kemble, at his desk, has stopped writing." then {
    Assert harkerTested(party). }
  Topic answer_beck_east with harker "Tell him: east, off the fell past the fold and down to the Swale" when harkerTested(actor) and not testAnswered(actor) and knows(actor, abel_flock_known) once {
    Says "'East,' says Harker. 'The Swale. Of course.' Kemble begins to write again. 'My drover was a liar,' says Master Harker, and smiles, and it is the smile of a man who has stopped asking questions.".
    On discuss { Assert testAnswered(actor). Increase conviction(harker, squire_claim) by 1. }
  }
  Topic answer_beck_west with harker "Tell him: west, down into the Lisk" when harkerTested(actor) and not testAnswered(actor) once {
    Says "'West,' says Harker. 'Into the Lisk.' He turns his ring round on his finger twice, watching you. 'Then my drover was right after all,' he says, gently, and Kemble does not begin to write again for some time.".
    On discuss { Assert testAnswered(actor). Decrease conviction(harker, squire_claim) by 2. }
  }
  Action answer_beck_bluff(actor: group, site: place) "Tell him a squire does not count becks; he must ask the shepherd" {
    Requires able(actor) and company(actor) and at(actor, site) and at(harker, site) and harkerTested(actor) and not testAnswered(actor).
    Time 2 minutes.
    Resolve check(actor, deception, dc_fair).
    On success { Assert testAnswered(actor). }
    On failure { Assert testAnswered(actor). Decrease conviction(harker, squire_claim) by 1. }
    Result "'A squire,' you tell him, with the air of one who has had to say this to a great many people, 'counts ewes. My shepherd counts becks.' Harker laughs, which you have not heard him do, and lets it go.".
    Otherwise "'A squire counts ewes,' you say, 'not becks,' and Harker says 'Indeed,' and you can see him put the question away in a drawer, to take out later.".
  }
  Rule wool_given when abelWool(abel) and at(fell_wool, limbo) and at(party, ?p) { Retract at(fell_wool, limbo). Assert at(fell_wool, ?p). }
  // Keeping him from Harker: a lie he will believe, because he believes everything.
  Topic abel_divert with abel "Tell Abel that Harker has bought all he wants, and the man to see now is at the Wool Exchange" when knows(actor, abel_flock_known) and posedSquire(actor) and not abelDiverted(abel) and not abelMetHarker(abel) once {
    Says "'Aye?' Abel looks at you with perfect trust. 'Exchange, then. I'll be stood at the door before it's open.' He puts his hat on. 'You're the first in this town that's told me something I didn't want. It'll be true, then.'".
    On discuss { Assert abelDiverted(abel). }
  }
  // Or bringing him into it: not by asking him to lie, which he cannot, but by making him believe.
  Action make_abel_believe(actor: group, site: place) "Tell Abel the old landlord's heir has come up from the south to Hawsfold, and it is you" {
    Requires able(actor) and company(actor) and at(actor, site) and at(abel, site) and knows(actor, abel_flock_known) and posedSquire(actor) and not abelInOnIt(abel) and not abelMetHarker(abel).
    Time 1.
    Resolve check(actor, deception, dc_easy).
    On success { Assert abelInOnIt(abel). Assert believes(abel, squire_claim). Set conviction(abel, squire_claim) to 2. }
    On failure { Assert abelDoubts(abel). }
    Result "You tell him that Hawsfold had a landlord once, before the fell came down to the Haws family, and that the landlord's line went south, and that you are what is left of it, come up to see the old fold. Abel takes off his hat. 'Squire,' he says, as if he had been waiting all his life to say it to someone. 'Squire. I'll tell anyone.' He will.".
    Otherwise "He listens with his head on one side, the way his dog does. 'There's never been a squire at Hawsfold,' he says, quite kindly, 'not in my grandfather's time.' He is not suspicious. He is only sure.".
  }
  Relation abelDoubts(group).
  // What happens when Harker, believing in the Squire, meets the real shepherd of Hawsfold.
  Rule abel_meets_harker when together(abel, harker) and abelCame(abel) and not abelMetHarker(abel) { Assert abelMetHarker(abel). }
  Rule abel_exposes when abelMetHarker(abel) and believes(harker, squire_claim) and not abelInOnIt(abel) and posedSquire(party) and not squireExposed(party) and not abelSold(abel)
    {
    Assert squireExposed(party). Assert harkerWary(harker). Retract believes(harker, squire_claim). Assert happened(ev_abel_exposes). }
  Entity ev_abel_exposes: fact "abel exposes".
  Rule abel_exposes_heard when happened(ev_abel_exposes) and inPellam() and not heardNews(ev_abel_exposes) says "Word goes up and down the ice like a dropped tray: at the Hiring Ring a shepherd from Hawsfold under Swale Fell took his hat off to Master Harker and offered him two hundred fell ewes for forty coin, and Master Harker asked him, in front of everyone, how the Squire of Hawsfold did; and the shepherd said that there was no squire at Hawsfold, there was him." { Assert heardNews(ev_abel_exposes). }
  Rule abel_confirms when abelMetHarker(abel) and believes(harker, squire_claim) and abelInOnIt(abel) and not abelVouched(abel)
    {
    Assert abelVouched(abel). Increase conviction(harker, squire_claim) by 1. Assert happened(ev_abel_confirms). }
  Entity ev_abel_confirms: fact "abel confirms".
  Rule abel_confirms_heard when happened(ev_abel_confirms) and inPellam() and not heardNews(ev_abel_confirms) says "Word goes round the ice: a shepherd from Hawsfold under Swale Fell met Master Harker at the Hiring Ring, and took off his hat, and talked of nothing for a quarter of an hour but the new Squire, come up from the south, God bless him." { Assert heardNews(ev_abel_confirms). }
  Relation abelVouched(group).
  // The lie made true: buy the real flock, for real money, and what was sold to Harker exists.
  Action buy_flock(actor: group, site: place) "Buy Abel's two hundred ewes, for forty coin" {
    Requires able(actor) and company(actor) and at(actor, site) and at(abel, site) and knows(actor, abel_flock_known) and quantity(actor, gold) >= 40 and not abelSold(abel).
    Time 2.
    On success { Decrease quantity(actor, gold) by 40. Increase quantity(abel, gold) by 40. Assert abelSold(abel). Assert flockReal(actor). }
    Result "Abel counts it twice, and then a third time, on the table in the Spotted Calf, and then spits on his palm and holds it out. You shake, and it is not on the ice, and it does not matter, because Abel Haws would keep it in a fire. 'Two hundred Swale ewes at Hawsfold, and the tups, and the gimmers,' he says, 'and my sister's lad to see them through to the shearing.' He blows his nose. 'You'll be good to them.' Somewhere on the fells, two hundred ewes that were a lie this morning are the truth.".
  }
}

data/adventures/liberty-of-the-ice/debat:
Module pellam "The Liberty of the Ice" {
  // ── The Glove Post argues: Callow, Sir Lionel and Ursel ─────────────────────────────────────────────────────────────
  // The owner's review of Mission 18 asked of the philosophers initiative, a sustained exchange, real debate among
  // several, answers to disagreement, teaching, and an argument that is remembered. Callow calls a stranger over; once
  // his question has been answered, the stranger can set Sir Lionel and Ursel at it in front of the crowd, the three of
  // them answer one another, Callow says what the ice has heard (three answers, and the stranger's), and at the Court
  // he remembers which answer the stranger gave.
  Relation callowHailed(group). Relation debateGant(group). Relation debateUrsel(group). Relation debateSummed(group).
  Relation callowRejoined(group). Relation debateWarm(group). Relation callowRemembered(group).
  // He does not wait to be asked.
  Rule callow_hails when firstDay() and at(party, freezeland) and callowOnKeg() and not callowHeard(party) and not callowHailed(party)
    says "On his keg at the foot of the Glove Post the old preacher breaks off in the middle of a sentence and points his handkerchief at you over the heads of the crowd. 'You! Yes. The one with the snow still on their boots. Come here and be argued with: it is free, and it is the only thing on the ice that is.' The crowd turns round to look at you, delighted." {
    Assert callowHailed(party). }
  // Sir Lionel, set at it: a gentleman is his promises.
  Topic gant_is_bound with gant "Ask Sir Lionel, in front of Callow's crowd, whether a man is his promises" when callowPut(actor) and callowOnKeg() and at(gant, freezeland) and not gantFree(gant) and not gantSafe(gant) and not debateGant(actor) once {
    Says "Sir Lionel gets up out of his lean-to, which takes some time, and stands with one hand on the Glove Post. 'A man is nothing else,' he says. 'I gave my hand for three coin at five-and-twenty, to a tailor, for this waistcoat. I am bound to that boy as if he were my own son, and so I am bound for thirty, and it has ruined me, and I would not have it otherwise. Honour is being bound to who you were. Without it,' and he looks down at Callow on his keg, 'you have a philosopher.' The crowd cheers. Callow, coughing, cheers loudest.".
    On discuss { Assert debateGant(actor). }
  }
  Rule callow_answers_gant when debateGant(party) and at(party, freezeland) and callowOnKeg() and not callowRejoined(callow)
    says "'Lionel,' says Callow, quite gently, from his keg, 'you are bound to a boy of five-and-twenty who has been dead these fifteen years, and the only man in Pellam who believes that boy is still alive is Master Harker, who is paid to.' Sir Lionel opens his mouth, and shuts it, and sits down on his lean-to's step, and is quiet for a while, which the crowd does not cheer." {
    Assert callowRejoined(callow). }
  // Ursel, set at it: keep your hand in your pocket.
  Topic ursel_never_shakes with ursel "Ask Ursel Cobb, before the crowd, why she has never shaken on anything" when debateGant(actor) and urselHere() and not debateUrsel(actor) once {
    Says "'Because I tell lies for a living,' says Ursel, loud enough for the back of the crowd, 'and I'm good at it. Anything I say can be a lie, and everybody knows it, and they pay me for that. A hand is the one thing I can't fake. So I keep it in my pocket.' She puts it there to show them. 'He,' a nod at Callow, 'says nothing you give stays. Sir Lionel says everything you give stays for ever. I say: what you never gave, nobody can call in.'".
    On discuss { Assert debateUrsel(actor). }
  }
  Rule the_three_argue when debateUrsel(party) and at(party, freezeland) and callowOnKeg() and at(gant, freezeland) and not debateWarm(callow)
    says "And then they are at it, all three, and you are forgotten. Sir Lionel says that a woman who will not give her hand cannot be trusted with anything. Ursel says that is the first true thing a gentleman has said to her this winter. Callow says that they are both describing the same coward from two sides: the one who is afraid to be someone else tomorrow. A waterman shouts that whoever wins owes him a penny a stair. Sir Lionel tells Callow he is a heretic. Callow tells Sir Lionel he is a debtor. Ursel tells them both they are men, and the crowd, which has been waiting all morning for somebody to say it, roars." {
    Assert debateWarm(callow). }
  // What the ice has heard, as Callow tells it: something to take to the Court, and to keep.
  Topic callow_sums with callow "Ask Callow, when the three of them have done, what the ice has heard" when debateUrsel(actor) and callowOnKeg() and not debateSummed(actor) once {
    Says "Callow wipes his eyes, wet with laughing and with coughing, and holds up three fingers to the crowd. 'Sir Lionel says it binds for ever, and it has ruined him. I say it binds nobody, and that will ruin me at four o'clock. Ursel says give nothing and nothing can be called in, which is the wisest answer and the loneliest.' He lowers his hand and looks at you. 'And yours, which they will remember better than you think. The ice keeps everything said on it until the thaw.'".
    On discuss { Assert debateSummed(actor). Assert knows(actor, three_on_the_ice). }
  }
  Discovery three_on_the_ice "Three answers on the ice to what a hand binds: Sir Lionel Gant's, that it binds the one who gave it for ever, and that is honour; Magister Callow's, that it binds nobody, because nobody stays; Ursel Cobb's, that what you never gave nobody can call in." {
    Known by callow.
  }
  // At the Court he remembers what the stranger said before the Glove Post.
  Rule callow_remembers_binds when callowCharged(callow) and at(callow, court) and at(party, court) and publicBinds(party) and not callowHand(party) and not callowRemembered(callow)
    says "Before the trestle, Magister Callow finds you on the benches and lifts his handkerchief to you. 'There,' he tells the Court, 'is the stranger who told the Glove Post this morning that a hand binds whoever gave it, changed or not. I should like to see what such a hand would do for a man who does not believe in it.' The benches turn round to look at you." {
    Assert callowRemembered(callow). }
  Rule callow_remembers_changes when callowCharged(callow) and at(callow, court) and at(party, court) and publicChanges(party) and not callowHand(party) and not callowRemembered(callow)
    says "Before the trestle, Magister Callow finds you on the benches and smiles. 'My convert,' he tells the Court. 'Converted before noon, on the ice. A convert would never shake to be my hand, of course: whoever shook would be somebody else by the Landing.' He sighs. 'Which is a pity.' The benches turn round to look at you." {
    Assert callowRemembered(callow). }
  Rule callow_remembers_knowing when callowCharged(callow) and at(callow, court) and at(party, court) and publicKnowing(party) and not callowHand(party) and not callowRemembered(callow)
    says "Before the trestle, Magister Callow finds you on the benches and nods to you, gravely, as to a colleague. 'The stranger with the third thing,' he tells the Court. 'Remember it, Justice, when the Landing comes.' Justice Broom writes something down." {
    Assert callowRemembered(callow). }
}

data/adventures/liberty-of-the-ice/deepe:
Module pellam "The Liberty of the Ice" {
  Description "What lies under the Fair and off its critical path: the cut leaf in the Book of Frosts, the left glove, the egg that crosses the bridge each Lady Day, the boys on sheep-bone skates, a fish and a flame in the Saint's scales, the Collegium's brass ell on the Exchange floor; and the Fair's two foreshadowings, which pay off in the morning's news.".

  // ── The count and its first page ──────────────────────────────────────────────────────────────────────────────────
  // The count is the Book of Frosts, kept by Gaffer Tredgold for the Company and by the Company for the river. What it is
  // a count of is not frosts. It was begun to write down what the river did with what was shaken on it. The first leaf
  // has been cut out.
  Discovery book_stub "The Book of Frosts has a stub where its first leaf was, cut out cleanly with a knife: eight leaves went into the gathering and seven frosts are in it. Tredgold's father said the leaf was cut by the first Reeve, Aldith, before she had written a word on it.".
  Topic tredgold_stub with tredgold "Ask Gaffer Tredgold about the stub at the front of the Book of Frosts" when knows(actor, book_of_frosts) once {
    Says "'That.' He opens the Book from the back, as the Company reads it, and lays a thick finger on a finger's breadth of torn edge ahead of the First Frost. 'Eight leaves went into the making of this gathering and there are seven frosts in it. Count it yourself.' He does not take his finger away. 'My father said Reeve Aldith cut it with her own knife before she had put a word on it. Why would you cut a leaf before you wrote on it?' He shuts the Book. 'I have a notion. I keep it to myself. I told my own boy: write what happened, not what you think.' He looks at the saws by the door. 'It is not a wolf leaf, if that is what you are asking. Four of the seven have wolves in them. That one is blank.'".
    On discuss { Assert knows(actor, book_stub). }
  }

  // ── The Glove ─────────────────────────────────────────────────────────────────────────────────────────────────────
  Discovery left_glove "The Glove on the Fair's mast is always a left glove, cut by the Glovers' Company from a pattern in the Company's chest and sewn a size too small for any man; the Reeve shakes with her right.".
  Topic tredgold_glove with tredgold "Ask Gaffer Tredgold why the Glove on the mast is always a left glove" when true once {
    Says "'Is it?' He looks pleased, as a man does who is asked something nobody has asked in thirty years. 'It is. The Glovers' Company has the pattern in a chest at the back of their hall, and it comes out in a frost and goes back after. They sew it a size small, so no man's hand will go in it. A man who can get his hand in the Glove, they say, has got above himself.' He takes up his pen. 'The Reeve shakes with her right; that is the Court's. The left is the Glove's. Ask me why and I will tell you what I told the last man who asked, which was a canon from Veyra with a notebook: it was a left glove before there was a Company.'".
    On discuss { Assert knows(actor, left_glove). }
  }

  // ── An egg on a spoon ───────────────────────────────────────────────────────────────────────────────────
  Discovery bridge_egg "Every Lady Day a Bankside child carries an egg on a spoon from the Bankside end of Pellam Bridge to its midpoint, while an alderman of Pellam stands there and watches; if it is dropped Bankside owes the city a bell. It has not been dropped in living memory.".
  Topic nab_egg with nab "Ask Nab Pollard why a Bankside child carries an egg on a spoon to the middle of the bridge every Lady Day" when true once {
    Says "'Toll.' He is polishing a cup with the rag he polishes everything with. 'After the Frost They Hanged the Reeve, Bankside said she had done right, and Pellam said she had not, and Bankside stood her stool at the middle of the bridge for a year with a candle on it. When the city took it down they came to terms. We could keep our opinion if we paid for it. An egg. On a spoon. From our end to the middle, with an alderman looking on, and if it drops, a bell.' He holds the cup to the light. 'It has not dropped in my time, nor my father's. Last Lady Day it was Hester Pole's lad, nine years old, and he was as white as the egg.'".
    On discuss { Assert knows(actor, bridge_egg). }
  }

  // ── Sheep-bone skates, which a particular morning will account for ────────────────────────────────────────────────
  // Seen by everyone on the first day. It is the foreshadowing that always pays: the morning's news returns to them.
  Observe bone_skates at freezeland when firstDay() and not iceGone() and not dark() "Under the Glove Post the boys of Bankside are skating on the shin-bones of sheep, strapped to their boots with thongs, standing on one leg to push with the other; and the ice sings under them in one long scraped note, like a hundred slow knives on a stone. A very small one has lost a bone already and is going round and round on his own two feet, shrieking, with the other boot off.".
  Observe bone_skates_late at freezeland when thirdDay() and not iceGone() and not dark() "The boys are not skating today. They sit along the edge of the Fair with the sheep-bones in their laps, looking at the ice, which has gone the grey of old pewter, and which has stopped singing.".

  // ── A fish and over it a flame ────────────────────────────────────────────────────────────────────────────────────
  // Found in at most five adventures, explained in none. Here it is in the pivot of the Saint's scales. The verger will
  // not say whose it is.
  Discovery scale_mark "Cut small into the brass of the pivot of Saint Evenhand's great scales, under the polish of the hands: a fish, and over it a flame. The brass of the scales has been cast round it." {
    Found by searching evenhands with insight "You go down on one knee by the pillar with the Saint's beam above you and look where a hand would go. In the pivot, under the polish of a great many Sundays, a fish and over it a flame, very small, cut before the brass was cast.".
  }
  Topic verger_mark with verger "Ask the verger about the little fish and flame in the pivot of the scales" when knows(actor, scale_mark) once {
    Says "'Ah.' He puts a thumb over it, as a man covers a child's ears. 'It is called the Saint's mark. It is not. The Saint's mark is a pair of scales; I looked, in the saints' book, when I was young and had nothing to do.' He takes the thumb away. 'My master said you do not scour it, you do not gild it, you do not ask whose it is.'".
  }
  Topic verger_measures with verger "Ask the verger whose stamp is on the factors' weights" when knows(actor, scales_known) once {
    Says "'Sennet's.' He says it with the weary relish of an old man correcting a young one. 'The Collegium of Measures. They weigh, mind: they do not teach. That is Veyra. Sennet weighs, and stamps what it weighs, and every weight in Fleece Row has the Collegium's mark on its under side.' He nods at the great brass pan. 'The Saint's weights have nobody's. I asked once. Sennet wrote back that they had no standard to stamp them against.'".
  }

  // ── The Exchange floor: a brass ell, and a board nobody has answered ──────────────────────────────────────────────
  Observe ell_scene at exchange_floor when true "Let into the flags of the Exchange floor, a bar of brass the length of a long stride with a row of nail-holes along its edge, and at one end the small round stamp of the Collegium of Measures at Sennet: THE ELL OF PELLAM, SEALED. Factors lay their cloth on it with a flourish and their thumbs on the line. The seal is renewed every seventh year by a Fellow who comes up the North Road with a case and goes home the same week; the last one came before the snow and did not like the sky.".
  Observe exchange_board at exchange_floor when not iceGone() "By the door, chalked in a clerk's round hand and not rubbed out since Michaelmas: FOUNDERS' EXCHANGE: FLEECE BY THE HEAD, SPRING DELIVERY. ASK FOR THE FACTOR'S CARTER. Nobody has asked for the carter in a month. The roads are shut.".

  // ── The Calf, and a stranger's story ──────────────────────────────────────────────────────────────────────────────
  // What a walker brought in ahead of the snow, and what Pellam makes of it. Read only if the Slack has been opened.
  Observe sennet_rumour at calf_taproom when befell(slack_opened) and not iceGone() "A drover who walked in on the last road before the snow is telling three watermen and a dog that at Sennet, on the coast, in the great House of Doors, the floor of the hall has been lifted, and a stair goes down under it a great deal further than the cellar could. He is the only man in the room who is not lying, and nobody believes him.".

  // ── The morning's news: what the Fair's two small things come to ──────────────────────────────────────────────────
  Rule news_skate when newsHour() and not officeRead(lisk) and not officeSung(lisk) once says "Of the bone skates: the watermen collected them from the edge of the Fair at dusk, forty-one pairs in a barrow, and when the ice had gone and the water dropped a little at the foot of Swan Stairs there was one more in the weed, a very small one, brown as a nut and a great deal older than any of the others. Nobody claimed it. It lay on the top step all night, and this morning it is not there." { }
  Rule news_skate_office when newsHour() and officeRead(lisk) and not officeSung(lisk) once says "Of the bone skates: the watermen collected them from the edge of the Fair at dusk, forty-one pairs in a barrow, and when the ice had gone and the water dropped a little at the foot of Swan Stairs there was one more in the weed, a very small one, brown as a nut and a great deal older than any of the others. Widow Saffery was on the top step before it was light, and she took it up as one takes up a sleeping child, and has hung it on the lantern-hook in her window, where the bridge can see it." { }
  Rule news_skate_song when newsHour() and officeSung(lisk) once says "Of the bone skates: the watermen collected them from the edge of the Fair at dusk, forty-one pairs in a barrow, and when the ice had gone and the water dropped a little at the foot of Swan Stairs there was one more in the weed, a very small one, brown as a nut. Widow Saffery was on the top step before it was light. She took it up and carried it indoors, and the lantern-hook in her window is empty." { }
  Rule news_candle when newsHour() and knows(party, candle_office) and hiredLanded(lisk) and not hiredFled(lisk) once says "Of the churchwarden: Master Harker was in the Scale Church at first light, before the verger, and the Saint's candle burned that morning in the thaw, which is not the season; and he sat under the board in gold with his hat on his knee, which is not like him. The verger says the beam did not move." { }
  Rule news_candle_fled when newsHour() and knows(party, candle_office) and (hiredFled(lisk) or hiredReleased(lisk)) once says "Of the churchwarden: Master Harker sent to the chandler on Swan Lane at first light for a second pound of wax, in his own hand, and had the verger set it beside the first. Asked for whom, he said, for the weight. The verger asked him which." { }
}

data/adventures/liberty-of-the-ice/dispu:
Module pellam "The Liberty of the Ice" {
  // ── Callow at the Glove Post: the disputation on the ice ──────────────────────────────────────────────────────────
  // His question was asked only of whoever had stood up at the Court and shaken to be his hand; a stranger who stopped
  // at his keg on the first morning heard what he teaches, and nothing more (the owner's review of Mission 18: the
  // philosophers were thin to meet, and slow to argue). On the first day, before the Court sits, he puts it to anyone
  // who has heard him out, in front of the crowd; each answer has its rejoinder, and its follow-up; the ice joins in;
  // and the third answer, which only someone who has seen a bargain shaken on a lie can give, is waited for.
  Relation callowPut(group). Relation publicBinds(group). Relation publicChanges(group). Relation publicKnowing(group).
  Relation callowPressed(group). Relation gantSpoke(group). Relation urselSpoke(group). Relation callowWaits(group).
  Query callowOnKeg() means at(callow, freezeland) and not callowCharged(callow) and not iceGone().
  Topic callow_puts with callow "Let Magister Callow put his question to you, before the crowd" when callowHeard(actor) and callowOnKeg() and not callowPut(actor) once {
    Says "He gets down off his keg and takes you by both shoulders and turns you to face the crowd, as if you were the text of his sermon. 'Here,' he says, 'is a stranger who came down the North Road this morning, and shook on a penny a stair with a waterman, very likely, or will before the day is out. Tomorrow this stranger will have seen the Fair, and lost a purse, and found it, and be somebody else.' He turns you back to face him. 'So. Which of them does the hand bind? The one who gave it, or the one who is standing here when it is called in?' The crowd goes quiet to hear what you will say, which is the most attention you have had from anybody in Pellam.".
    On discuss { Assert callowPut(actor). }
  }
  Topic callow_public_binds with callow "Tell him, before them all: a hand binds whoever gave it, changed or not" when callowPut(actor) and callowOnKeg() and not publicBinds(actor) and not publicChanges(actor) and not publicKnowing(actor) once {
    Says "'The Reeve's answer,' says Callow, delighted, to the crowd. 'Pellam's answer. Every honest man's. And Master Harker's, who has bought up every bond in this city that a man made when he was younger and poorer and stupider, and calls them in on the man he is now.' He turns back to you. 'You say the man is dragged along behind his promise like a dog behind a cart. Very well. But who wrote the promise down? And was it the same promise when it was called in?' He looks across, very pointedly, at the lean-to in the lee of the Glove Post.".
    On discuss { Assert publicBinds(actor). }
  }
  Topic callow_public_changes with callow "Tell him, before them all: he is right, and nobody is bound by who they were" when callowPut(actor) and callowOnKeg() and not publicBinds(actor) and not publicChanges(actor) and not publicKnowing(actor) once {
    Says "His face lights up like a boy's. 'A convert,' he tells the crowd, 'on the ice, before noon.' Half of them cheer and half of them boo, and a waterman at the back shouts that he'll take his penny a stair off the convert, then, since it's somebody else who'll owe it. 'Ah,' says Callow, and holds up one finger, and coughs. 'There is the difficulty. Every man in Pellam agrees with me about his own promises, and with the Reeve about everybody else's.' He looks at you, sharply, kindly. 'Which are you?'".
    On discuss { Assert publicChanges(actor). }
  }
  // A middle answer, which only someone who has seen a bargain shaken on a lie can give: before the crowd, it is the
  // thing the Court will be argued on at the Landing.
  Topic callow_public_knowing with callow "Tell him, before them all: a hand binds the one who shook it if he knew what he was shaking on; shaken on a lie about the thing itself, it binds nobody" when callowPut(actor) and callowOnKeg() and not publicKnowing(actor)
    and (knows(actor, hired_sold) or knows(actor, tansy_hired) or knows(actor, gant_altered)) once {
    Says "Callow does not say anything at all for a while, which nobody on the ice has seen him do, and the crowd waits with him. 'That is not the Flow,' he says at last. 'And it is not the Reeve.' He holds up one finger, and the crowd, which has been waiting for the cough, is thrown. 'It is a third thing. Nothing stays, but what a man knew when he gave his hand, that stays: it was really there.' He turns to the crowd. 'Remember that this stranger said it, and I did not,' he tells them, 'when it is argued before the Reeve.' Then, to you, quietly: 'Somebody shook on a lie in front of you. Hold onto them. That is your case, and it is better than mine.'".
    On discuss { Assert publicKnowing(actor). Assert knows(actor, third_thing). }
  }
  Discovery third_thing "Magister Callow's third thing, said first by you before the crowd at the Glove Post: a hand binds the one who shook it if he knew what he was shaking on; a hand shaken on a lie about the thing itself binds nobody. It could be argued before the Reeve." {
    Known by callow.
  }
  // Disagreement pressed: each answer has its follow-up, and each follow-up is somewhere to go.
  Topic callow_press_bond with callow "Ask Callow what he meant, looking at the lean-to: who changed the promise?" when publicBinds(actor) and callowOnKeg() and not callowPressed(actor) once {
    Says "'I meant nothing,' says Callow, loudly, for the crowd, and then, low, for you: 'Sir Lionel Gant, under the Glove Post, borrowed three coin from his tailor ten years ago. Master Harker bought the bond, and it says thirty now. The man has changed, and so has the paper, and only one of them was supposed to.' He climbs back on his keg. 'Ask Sir Lionel whether he ever read his own copy. He has not. Nobody reads what they shook on; that is how the world is run.'".
    On discuss { Assert callowPressed(actor). Assert knows(actor, gant_bond). }
  }
  Topic callow_press_reeve with callow "Ask Callow what the Reeve will say to a convert" when publicChanges(actor) and callowOnKeg() and not callowPressed(actor) once {
    Says "'To you? Nothing. You have not preached it.' He looks over at the Court's patched tent beside the Glove Post. 'To me she will say it at four, I think. The watermen have been counting how many of their pennies I have talked off them.' He laughs until it hurts him. 'Come and watch. Nobody on the ice will shake to be my hand, and you will see what a hand is worth when there is none.'".
    On discuss { Assert callowPressed(actor). Assert knows(actor, court_at_four). }
  }
  Discovery court_at_four "Magister Callow expects to be charged at the Court of the Ice at four on the first day, for teaching that a hand binds nobody; and that nobody on the ice will shake to be his hand." {
    Known by callow.
  }
  // He waits for the third answer from whoever has not found it yet: something to go and look for.
  Topic callow_waits with callow "Ask Callow whether there is any answer he has not heard" when callowPut(actor) and (publicBinds(actor) or publicChanges(actor)) and callowOnKeg() and not publicKnowing(actor) and not callowWaits(actor) once {
    Says "'One.' He holds up a finger. 'I have heard the Reeve's, and mine, ten thousand times. I have never heard a third, and I think there is one, and I think it is lying about on this ice somewhere for anyone who has seen a hand shaken on a lie.' He taps your chest. 'Find me someone who shook on a lie, and come and tell me what it bound. Before four, if you would be so kind: after four I expect to be busy.'".
    On discuss { Assert callowWaits(actor). }
  }
  // The ice joins in: Sir Lionel, who borrowed three, for the Reeve's answer; Ursel, who has never shaken, for his.
  Rule gant_joins when publicBinds(party) and at(party, freezeland) and at(gant, freezeland) and not gantFree(gant) and not gantSafe(gant) and not gantSpoke(gant)
    says "From the lean-to under the Glove Post, Sir Lionel Gant raises his glass. 'Bound, sir! Bound for ever, by a hand I gave when I had more hair and fewer creditors. I borrowed three. I am bound for thirty. If the stranger can show me where the other twenty-seven came from, I will shake on anything they like.' The crowd cheers him, as it cheers everything." {
    Assert gantSpoke(gant). }
  Rule ursel_joins when publicChanges(party) and at(party, freezeland) and urselHere() and not urselSpoke(ursel)
    says "Somewhere in the crowd a woman in a man's caped coat laughs out loud. 'Never shook on anything in my life,' she calls, 'and never needed a philosopher to tell me why.' Callow bows to her, very low, and coughs." {
    Assert urselSpoke(ursel). }
}

data/adventures/liberty-of-the-ice/drown:
Module pellam "The Liberty of the Ice" {
  // ── The drowned ───────────────────────────────────────────────────────────────────────────────────────────────────
  // At each hiring one or two of Harker's hired slip out of Kemble's line in the crush on the walk to Hay Stairs, and
  // that night a hat is left on a stake by the hole on the Black Reach that has never frozen. The city says the river
  // takes its own. A drowned man's hand is no hand: his bargain dies with him. They are alive, hidden, and Dickon Cobb,
  // who came back out of Gallowmoor alone last month, is getting them out.
  Discovery drowned_hats "Twice already this Fair, and again this morning, a hat has been found on a stake by the hole on the Black Reach that never freezes, and the river is said to have taken whoever wore it. Each was one of Master Harker's hired." {
    Known by bel, kemble, nab, tredgold, gant, noll, saffery, callow.
  }
  Relation hatDay(place).
  Event first_hat at black_reach when at(party, black_reach) and (secondDay() or thirdDay()) and not dark() "On a stake of the rope round the black hole a hat has been hung, a carter's felt hat with a whipcord round the crown, very neatly, as if on a peg. Under it, in the snow, someone has put a penny." teaches drowned_hats.
  Rule hat_talk when secondDay() and hour(clock) >= 8 and inPellam() and not spread(hat_one) says "All over the Fair this morning: another hat on the stake at the Black Reach. Jem Rudd's, the carter's lad from Garthwaite, hired yesterday at the Ring; he was in Kemble's line at noon and not in the bondhouse at dark. The river has taken him, everyone says, and touches the ice with a knuckle." teaches drowned_hats { Assert spread(hat_one). }
  Entity hat_one: fact "Jem Rudd's hat". Entity hat_two: fact "Polly Sneath's hat".
  Rule hat_talk_two when thirdDay() and hour(clock) >= 8 and inPellam() and not spread(hat_two) and not dickonTaken(dickon) says "Another hat on the stake at the Black Reach this morning: Polly Sneath's, the shepherd's girl from the second hiring. The watermen have stopped laughing about the Lisk Wife." { Assert spread(hat_two). }
  // A company that watches the line come off the ice sees how it is done.
  Observe line_slip at hiring_ring when firstDay() and hour(clock) == 12 and capable(party, insight) and not knows(party, slip_seen) "As Kemble's line goes off across the ice two by two, a lad with a whipcord round his hat stumbles against a gingerbread booth, and a woman in a shawl steps between him and the line, and he is not there. The line goes on. Kemble, counting at the front, does not look back." teaches slip_seen.
  Discovery slip_seen "In the crush of Freezeland Street, as Kemble walked the hired to Hay Stairs, one of them slipped out of the line behind a booth, with a woman in a shawl to cover it.".
  // Whoever reads ground sees that the drowned walked away.
  Discovery tracks_read "By the hole on the Black Reach the snow says what the city does not: whoever hung the hat on the stake walked up to the hole, and then away from it along the bank toward the bridge, putting their feet in the sledge-marks so as not to be seen, and they were two, and one was very light." {
    Found by searching black_reach with woodcraft "You go down on one knee by the stakes. The prints are there under the night's snow if you know to look for them, and they do not stop at the water.".
  }
  Discovery not_drowned "Harker's drowned are not drowned. They slip out of his line, and someone hangs their hats by the hole so they will be thought dead, because a drowned man's hand is no hand and his bargain dies with him; and they are hidden somewhere in Pellam.".
  Rule put_together_drowned when knows(party, drowned_hats) and (knows(party, tracks_read) or knows(party, slip_seen) or knows(party, dickon_alive)) and not knows(party, not_drowned)
    says "You put it together: the hats on the stake, and what you saw. Nobody has drowned. A drowned man's hand is no hand." teaches not_drowned { }

  // ── Widow Saffery, the rope-maker on the bridge ───────────────────────────────────────────────────────────────────
  // Her son went through the ice at the last Frost Fair, thirty-one winters ago, off the Black Reach, and was never
  // found. She walks the Reach every night of the ice with a lantern; the watermen call her the Lisk Wife and leave
  // pennies. She hangs the hats. The newly drowned hide in her cellar in the starling, under her shop, until they can
  // be got down the Reach to the hulk.
  Observe rope_scene at saffery_shop when not visitedBefore(saffery_shop) "A rope-walk house, one room deep and very long, running the width of the bridge, with a window at the far end over the river. Coils of rope, hemp in hanks, a wheel, a smell of tar. An old woman spins a cord at the wheel walking backwards, slowly, the length of the room, and does not stop when you come in.".
  Observe rope_again at saffery_shop when visitedBefore(saffery_shop) "The rope-walk house: hemp, tar, the wheel, the window over the river.".
  Person saffery "Widow Saffery" at saffery_shop {
    Role "a rope-maker on the bridge, very old, very straight" when not knows(party, saffery_lantern).
    Role "a rope-maker whom the watermen call the Lisk Wife" when knows(party, saffery_lantern).
    Ancestry human. Peaceable. Pronouns she. Manner grim.
    Greets "The old woman walks backward the length of the room spinning, and back again, before she looks at you. 'Rope,' she says. 'Or something else.'".
    Greets again "Widow Saffery does not stop her wheel.".
    Sells rope for 1 coin from 4.
  }
  Rule saffery_shop_day when hour(clock) >= 6 and hour(clock) < 20 and not at(saffery, saffery_shop) and not safferyTaken(saffery) { Assert at(saffery, saffery_shop). }
  Rule saffery_reach when (hour(clock) >= 20 or hour(clock) < 1) and not iceGone() and not at(saffery, black_reach) and not safferyTaken(saffery) { Assert at(saffery, black_reach). }
  Rule saffery_back when hour(clock) >= 1 and hour(clock) < 6 and not at(saffery, saffery_shop) and not safferyTaken(saffery) { Assert at(saffery, saffery_shop). }
  Relation safferyTaken(group).
  Observe lantern_on_reach at black_reach when at(saffery, black_reach) and dark() and not knows(party, saffery_lantern) "Out on the Black Reach a lantern is moving, low down, very slowly, the way a person walks who is looking at the ice. It goes to the black hole by the bank and stops there a long time. When you come nearer you see an old woman holding it, very straight, in a shawl." teaches saffery_lantern.
  Observe lantern_again at black_reach when at(saffery, black_reach) and dark() and knows(party, saffery_lantern) "Widow Saffery is out on the Reach with her lantern, by the black hole.".
  Discovery saffery_lantern "Every night of the ice the rope-maker on the bridge, Widow Saffery, walks the Black Reach with a lantern and stands by the hole that never freezes. The watermen call her the Lisk Wife.".
  Topic saffery_son with saffery "Ask Widow Saffery why she walks the Reach at night" when knows(actor, saffery_lantern) and not safferyAffronted(saffery) once {
    Says "She stops the wheel. 'Davy,' she says. 'Nine. The last ice, the last night, off the Reach, with a bone skate on one foot. They never found him. It went out the same night and took the whole bottom of the Fair with it.' She starts the wheel again. 'The watermen call me the Lisk Wife, and leave me pennies. I let them. A widow can use a penny.' She walks backward down the room. 'I'm looking for him. That's all it is. Don't make it into anything.'".
    On discuss { Assert knows(actor, saffery_davy). }
  }
  // What the work does not explain: once, a second light.
  Observe second_light at black_reach when at(saffery, black_reach) and dark() and knows(party, saffery_davy) and not iceGone() "Out past Widow Saffery's lantern, further down the Reach where there is nobody, there is for a moment a second light on the ice, small and low down, the height of a child's hand. When you look again there is only the dark, and the old woman with her back to you, who has not turned round.".
  Discovery saffery_davy "Widow Saffery's son Davy went through the ice off the Black Reach at the last Frost Fair, at nine years old, and was never found. She walks the Reach every night of this ice with a lantern.".
  Topic saffery_hats with saffery "Ask Widow Saffery who hangs the hats on the stake" when knows(actor, saffery_lantern) and knows(actor, not_drowned) and not safferyAffronted(saffery) once {
    Says "The wheel goes round. 'The river,' she says. Then, without turning: 'A drowned child's mother can hang a hat on a stake and be believed. Nobody looks at an old woman by that hole at night; they look away.' She stops. 'If you're Harker's, I'll have you off my bridge. If you're not, you've seen nothing.' She looks at you then, a long look. 'Well?'".
    On discuss { Assert knows(actor, saffery_hangs). Assert safferyAsked(saffery). }
  }
  Relation safferyAsked(group). Relation safferyTrusts(group).
  Discovery saffery_hangs "Widow Saffery hangs the drowned's hats on the stake by the Black Reach, so that they will be believed dead.".
  Topic saffery_not_harker with saffery "Tell her you are not Harker's, and why" when safferyAsked(saffery) and not safferyTrusts(saffery) and not safferyAffronted(saffery) and (knows(actor, hired_sold) or urselConfessed(actor) or hiredHand(actor)) once {
    Says "She hears you out at the wheel. Then she goes to the far end of the room, to a hatch in the floor you had taken for a trap for the rope-ends, and knocks on it twice with her heel, and lifts it, and below in the dark a face looks up, a girl's, with straw in her hair. 'You can come up, Polly,' says Widow Saffery. 'It's not him.'".
    On discuss { Assert safferyTrusts(saffery). Assert knows(actor, starling_known). }
  }
  Discovery starling_known "Under the floor of Widow Saffery's rope-walk house a hatch goes down into a cellar cut in the bridge's third starling, and a rope ladder from there down to the ice under the arches. The newly drowned hide there.".
  Observe starling_scene at starling_cellar when true "A cellar cut into the stone of the starling, under the bridge: low, round, very cold, lit by a slit over the river. A pallet, blankets, a bucket, a crock of water with ice on it. The stone sweats. You can hear the river under the ice, going by, very close.".
  Person polly "Polly Sneath" at limbo {
    Role "a shepherd's girl from Garthwaite, drowned, as far as anyone knows". Ancestry human. Peaceable. Pronouns she. Manner cheerful.
    Seen when knows(viewer, starling_known) or knows(viewer, dickon_alive).
    Greets "'You'll not tell,' says Polly Sneath. It is not a question. Then she grins. 'I'm drowned. I've never felt better.'".
  }
  // Polly slips the line at the second hiring and is in the starling by its noon.
  Rule polly_slips when secondDay() and hour(clock) >= 11 and at(polly, limbo) and not pollyGone(polly) { Assert at(polly, starling_cellar). }
  Relation pollyGone(group).

  // ── The Patience, and Dickon Cobb ─────────────────────────────────────────────────────────────────────────────────
  Person dickon "Dickon Cobb" at patience_hold {
    Role "a big soft-spoken man of twenty with a lead-miner's cough" when not urselMet(dickon).
    Role "Ursel's brother, with a lead-miner's cough" when urselMet(dickon).
    Ancestry human. Calling warrior. Level 2. Peaceable. Pronouns he. Manner compassionate.
    Seen when knows(viewer, hidden_hulk).
    Greets "A big young man comes up out of the dark of the hold between you and the others, with a belaying pin in his fist, and looks at you, and coughs, a deep wet cough from the bottom of his chest. 'Who sent you?'".
    Greets again "Dickon Cobb nods to you from the ballast.".
  }
  Person jem "Jem Rudd" at patience_hold {
    Role "a carter's lad from Garthwaite, drowned". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Seen when knows(viewer, hidden_hulk).
    Greets "'Is it Kemble?' says Jem Rudd from behind Dickon, and then, seeing you, 'it isn't. Thank God.'".
  }
  Relation urselMet(group). Relation dickonTaken(group).
  Discovery hidden_hulk "In the hold of the frozen hulk Patience on the Reach, behind the ballast, Harker's drowned are hiding, alive: and with them Dickon Cobb, Ursel's brother, come back out of Gallowmoor." {
    Found by searching patience_hold "Behind the ballast, where the hull curves in, there is a breath of warmth that is not the brazier's, and blankets, and in the blankets people.".
  }
  Observe hold_scene at patience_hold when true "The hold of the Patience, sloping with her list: coal-dust, ballast stone, a brazier in a bucket of sand, the hull sweating frost. It smells of people.".
  Discovery dickon_alive "Dickon Cobb is alive, in the hold of the Patience. He was sold to Gallowmoor lead last spring, and walked back out of it through the autumn, and hides the hired who slip Harker's line, to get them down the Reach and away south.".
  Topic dickon_story with dickon "Ask Dickon Cobb how he came back" when true once {
    Says "'Walked.' He coughs. 'Three of us came out of Gallowmoor in September. Two got here.' He sits down on the ballast. 'I can't stop the hiring. What I can do is take them out of the line on the ice, one and two at a time, and let the river have them: a hat on the stake, a penny under it, Saffery's cellar till the barges run.' He looks round at the others, lying in their blankets. 'The frost was a gift. I can walk them down the sledge road, nights.' The cough again. 'The searchers walk it too, now.'".
    On discuss { Assert knows(actor, dickon_alive). Assert knows(actor, hired_sold). Assert knows(actor, not_drowned). }
  }
  Topic dickon_ursel with dickon "Tell Dickon Cobb that his sister is on the ice, looking for him" when knows(actor, ursel_brother) and not urselMet(dickon) once {
    Says "He sits down on the ballast as if he had been hit. 'Ursel,' he says. 'Ursel's here?' He laughs, and it turns into the cough. 'She'll have been lying to everybody. She'll have been running some rig on Harker himself, I'll bet you, to get his books.' He wipes his eyes on his wrist. 'Don't bring her here. Don't. If she's seen coming out to the hulk with that face on her, they'll follow her. Tell her I'm well. Tell her the night.'".
    On discuss { Assert knows(actor, dickon_night). Assert dickonToldOfUrsel(dickon). }
  }
  Relation dickonToldOfUrsel(group).
  Discovery dickon_night "Dickon Cobb means to get the hired out of Harker's bondhouse and down the Reach by the sledge road on the second night, in the small hours, before the Landing, when the hired are to be landed: a hired who is not there to stand before the Reeve is not landed, and goes out with the river. He needs the river door of the bondhouse open from inside, a way past the searchers, and, if it can be had, sledges.".
  Topic dickon_plan with dickon "Ask Dickon what he means to do about the bondhouse" when knows(actor, dickon_alive) once {
    Says "'Empty it.' He says it simply. 'Harker lands his hired at two on the last day, hand to hand before the Reeve. A hand that's not there isn't landed, and goes out with the river.' He holds up three fingers. 'The river door's barred inside with an oak baulk iced into its brackets; somebody inside has to have it off. The searchers walk the Reach from ten till three; somebody has to have them somewhere else. And twenty people on foot down the sledge road are slow; Tredgold's watermen have sledges and nothing to do with them, and won't lift a finger for nothing.' He looks at you. 'The second night. The small hours. That's when.'".
    On discuss { Assert knows(actor, dickon_night). Assert dickonPlanned(dickon). }
  }
  Relation dickonPlanned(group).
  Topic dickon_gallowmoor with dickon "Ask Dickon what Gallowmoor is like" when knows(actor, dickon_alive) once {
    Says "He is a while answering. 'Dark,' he says. 'You'd think it'd be the dark you minded. It isn't. It's the counting.' He coughs. 'There's a man called Corder, the overman, stands at the top of the ladder at five with a slate, and you put your hand in his as you go down past him, so he can feel it's a hand, and he chalks it. And at night again, coming up. Hand, chalk. Hand, chalk. He doesn't look at your face; he's never once looked at my face.' He looks at his own palm. 'There's eleven hundred hands at Gallowmoor. Some of them have been there since the Black Lambing, they say, father to son. There's a chapel. There's a song they sing going down, about the hills.' He does not sing it. 'They're very deep hills.'".
    On discuss { Assert knows(actor, gallowmoor_known). }
  }
  Discovery gallowmoor_known "At Gallowmoor lead, three days south over the downs, eleven hundred hands go down the ladder at five and come up at dark, and the overman counts each one by feeling it in his own, and never looks at a face.".
  Topic dickon_sister with dickon "Ask Dickon about his sister" when urselMet(dickon) or knows(actor, ursel_brother) once {
    Says "He smiles, for the first time, and it makes him look about twelve. 'She taught me my letters on a slate with a nail, in the Calf's back kitchen, when Mam was scrubbing. Made me write lies on it, so I'd have something to write: THE BRIDGE IS MADE OF CHEESE. THE MAYOR IS A GOOSE.' He coughs, and keeps smiling. 'I wrote her from Gallowmoor every month. Corder takes the letters at the top of the ladder for the post.' The smile goes. 'I suppose he burns them. I suppose that's what he does.'".
    On discuss { Assert knows(actor, dickon_letters). }
  }
  Discovery dickon_letters "Dickon Cobb wrote to Ursel every month from Gallowmoor, and gave the letters to the overman for the post; none came.".
  // Brought to the hulk, Ursel meets her brother; the company is the only one who can bring her without being followed.
  Rule ursel_finds_dickon when travelsWith(ursel, party) and at(party, patience_hold) and knows(party, hidden_hulk) and not urselMet(dickon) and not dickonTaken(dickon)
    says "Ursel comes down the hatch behind you and stops on the ladder. In the dark of the hold Dickon Cobb stands up off the ballast, coughing. Neither of them says anything. The brazier ticks. Then Ursel Cobb, who has never in her life been at a loss, says 'You great soft lump,' and goes down the rest of the ladder all at once, and holds on to him, and he holds on to her, and nobody in the hold says anything at all." {
    Assert urselMet(dickon). Increase urselTrust(ursel) by 2. Assert wentInForDickon(party). }

  // ── Harker's searchers ────────────────────────────────────────────────────────────────────────────────────────────
  // Three of Harker's wharf men, with a dog and lanterns. By day they keep Hay Wharf; on the second and third nights
  // they walk the Reach from ten until three, looking for people who are officially dead.
  Person searchers "Harker's searchers" at hay_wharf {
    Role "a gang of wharf men with lanterns and cudgels, and a lurcher on a rope". Ancestry human. Calling warrior. Level 2. Numbers 3. Pronouns they.
    Temperament territorial.
    Warns "The lanterns stop. 'Stand where you are,' says a voice behind them, and the lurcher begins to growl, low. 'Who's that out on the Reach? Who've you got with you?'".
    Comes "They come at you over the grey ice with their cudgels up and the lurcher let off its rope.".
    Flinches "The searchers back off over the ice, lanterns swinging, shouting for each other.".
    Pleads "'Enough,' says the one on the ice, with his hands over his head. 'Enough. We're paid by the night, not by the head.'".
  }
  Topic searchers_keep with searchers "Ask the wharf men what they are keeping" when at(searchers, hay_wharf) once {
    Says "'Master Harker's wool,' says the biggest of them, 'and Master Harker's business, and none of yours.' The lurcher agrees with him. Behind them the bondhouse door is barred on the outside, which is an odd way to keep wool in.".
  }
  Initially Assert tolerates(searchers, party). Initially Assert serves(searchers, harker). Initially Assert takesPrisoners(searchers).
  Rule searchers_out when searchNight() and not searchersDiverted(lisk) and able(searchers) and not iceGone() and not at(searchers, black_reach) { Assert at(searchers, black_reach). }
  Rule searchers_wharf when not searchNight() and not searchersDiverted(lisk) and not landingAt(lisk) and able(searchers) and not at(searchers, hay_wharf) { Assert at(searchers, hay_wharf). }
  Relation searchersDiverted(place).
  Observe searchers_reach at black_reach when at(searchers, black_reach) and dark() "Three lanterns out on the Black Reach, walking slowly in a line a few yards apart, and the sound of a dog.".
  Observe searchers_wharf_scene at hay_wharf when at(searchers, hay_wharf) "Three of Harker's wharf men lean on the bondhouse wall with cudgels, stamping their feet, and a lurcher lies on the snow between them.".
  // Seen going out to the hulk at night, the company is followed; going out unseen, it is not.
  Relation slippedPast(group).
  Action slip_reach(actor: group, site: place) "Go out past the searchers' lanterns by the bank, in the dark, where they are not looking" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, black_reach) and at(searchers, black_reach) and dark() and not slippedPast(actor) and tolerates(searchers, actor).
    Time 2 minutes.
    Resolve check(actor, stealth, dc_fair).
    On success { Assert slippedPast(actor). Assert unseen(actor, searchers). }
    On failure { Assert slippedPast(actor). }
    Result "You go wide along the bank where the reeds are frozen in, low, and wait while a lantern swings by, and go on. The dog lifts its head once, and puts it down again.".
    Otherwise "The dog has you before you have gone ten yards, and a lantern swings round, and a voice calls, 'Who's that?' You stand up and say good evening. They watch you go.".
  }
  Rule unseen_lapses when unseen(party, searchers) and not at(party, black_reach) and not at(party, patience_deck) and not at(party, patience_hold) and not at(party, sledge_road) { Retract unseen(party, searchers). Retract slippedPast(party). }
  Rule followed_to_hulk when at(party, patience_deck) and at(searchers, black_reach) and perceivesFrom(searchers) and knows(party, hidden_hulk) and not harkerKnows(hidden_hulk)
    says "Behind you, back on the Reach, one of the lanterns has stopped, and is watching where you went." { Assert harkerKnows(hidden_hulk). }
  Query perceivesFrom(g: group) means alert(g) and not unseen(party, g).
  // What Harker knows of the hiding places, and how he comes to know it.
  Relation harkerKnows(fact). Relation toldOf(group, fact). Relation drownedSold(group).
  Rule tattle_spreads when tattles(?p) and toldOf(?p, ?f) and (together(?p, harker) or together(?p, kemble)) and not harkerKnows(?f) { Assert harkerKnows(?f). }
  Entity sold_bargain: bargain "five coin a head for the drowned, with Kemble".
  Action sell_drowned(actor: group, site: place) "Tell Kemble where the drowned are hiding, for five coin a head" {
    Grave "Kemble writes down what you tell him, and pays, and Harker's searchers go where he sends them.".
    Requires able(actor) and company(actor) and at(actor, site) and at(kemble, site) and knows(actor, kemble_pays)
      and (knows(actor, hidden_hulk) and not harkerKnows(hidden_hulk) or knows(actor, starling_known) and not harkerKnows(starling_known)) and not drownedSold(actor).
    Time 2 minutes.
    On success { Assert drownedSold(actor). Assert harkerKnows(hidden_hulk). Assert harkerKnows(starling_known). Increase quantity(actor, gold) by 15. Assert shook(actor, sold_bargain). }
    Result "Kemble listens with his pen moving, and asks two questions, very exact, and counts fifteen coins onto the desk in a row. 'Master Harker thanks you,' he says. 'The bereaved will be comforted.' He does not look up again.".
  }
  // A careless word to someone who carries everything to Harker: Abel, who asks where a man might sleep for nothing.
  Topic abel_sleep with abel "Tell Abel there's a dry berth for nothing aboard the hulk on the Reach, with kind folk" when knows(actor, hidden_hulk) and not toldOf(abel, hidden_hulk) once {
    Says "'Is there.' Abel beams. 'Kind folk. I'll go out tonight, and take them a bit of my cheese.' He pats his coat. 'You're a good soul. I'll tell them who sent me.' He will tell everyone who sent him, and where he slept, and who was there, to anyone who asks, because nobody has ever told him not to.".
    On discuss { Assert toldOf(abel, hidden_hulk). Assert abelOnHulk(abel). }
  }
  // A lie that sends the searchers the wrong way: told to the man who carries everything to Harker.
  Relation liedToKemble(group).
  Action lie_to_kemble(actor: group, site: place) "Tell Kemble, as a secret, that the drowned are hiding in the Clink, and are going over the downs tonight" {
    Requires able(actor) and company(actor) and at(actor, site) and at(kemble, site) and knows(actor, not_drowned) and not liedToKemble(actor) and not drownedSold(actor)
      and (secondDay() or thirdDay()).
    Time 2 minutes.
    Resolve check(actor, deception, dc_fair).
    On success { Assert liedToKemble(actor). Assert searchersDiverted(lisk). }
    On failure { Assert liedToKemble(actor). Assert harkerWary(harker). }
    Result "Kemble's pen stops. He asks you two very exact questions, and you answer them very exactly, and he writes it down. That night Harker's searchers are not on the Reach. They are in the Clink yard in Bankside, and then on the south road up onto the downs in the snow with their lanterns, looking for footprints that are not there.".
    Otherwise "Kemble writes it down, and then looks at you over his pen the way a clerk looks at a sum that does not come out. 'Thank you,' he says. The searchers walk the Reach that night just the same.".
  }
  Rule diverted_away when searchersDiverted(lisk) and searchNight() and not at(searchers, limbo) { Assert at(searchers, limbo). }
  Rule diverted_ends when searchersDiverted(lisk) and fourthDay() { Retract searchersDiverted(lisk). }

  // ── The raid ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // What Harker knows, his searchers act on, in the small hours of the next night they walk.
  Rule raid_hulk when harkerKnows(hidden_hulk) and searchNight() and smallHours() and not dickonTaken(dickon) and not hiredFled(lisk) and not dickonGone(dickon)
    {
    Assert dickonTaken(dickon). Assert at(dickon, bond_floor). Assert at(jem, bond_floor). Assert happened(ev_raid_hulk). }
  Entity ev_raid_hulk: fact "raid hulk".
  Rule raid_hulk_heard when happened(ev_raid_hulk) and inPellam() and not heardNews(ev_raid_hulk) says "In the small hours there are lanterns and shouting out on the Reach, and a dog going mad, round the hulk Patience. In the morning everybody knows: Harker's searchers took three drowned men out of her hold, alive, and Dickon Cobb with them, and walked them up Hay Stairs to the bondhouse with their hands tied, to be landed at the Landing." { Assert heardNews(ev_raid_hulk). }
  Rule raid_starling when harkerKnows(starling_known) and searchNight() and smallHours() and not safferyTaken(saffery) and not hiredFled(lisk)
    {
    Assert safferyTaken(saffery). Assert at(saffery, bond_floor). Assert pollyGone(polly). Assert at(polly, bond_floor). Assert happened(ev_raid_starling). }
  Entity ev_raid_starling: fact "raid starling".
  Rule raid_starling_heard when happened(ev_raid_starling) and inPellam() and not heardNews(ev_raid_starling) says "In the night there is a noise of boots on the bridge, and a door broken in, and in the morning the rope-walk house stands open with its hemp all over the street: Harker's searchers took a drowned girl out of a hole under the floor, and an old woman with her, who walked between them very straight and said nothing at all." { Assert heardNews(ev_raid_starling). }
  Relation dickonGone(group).
}

data/adventures/liberty-of-the-ice/endin:
Module pellam "The Liberty of the Ice" {
  // ── Endings ───────────────────────────────────────────────────────────────────────────────────────────────────────
  // Reached on the morning after the ice goes out, by what the three days prepared. The first that holds is the one
  // told; what became of each of the others (the alderman, the printer, the heretic, the debtor, the bear, Ursel) is
  // told before it, as the morning's news (aftermath.kyr). None of them is a custom kept for ever after.
  Ending pillory "The Pillory" when fourthDay() and pilloried(party) "You come off the ice at nine at night with snow in your hair and your hands numb from the pillory's holes, and the Lisk goes out behind you at eleven, and in the morning it is a river, and nobody in Pellam remembers your face except as the Squire of Hawsfold, which is a joke now in every taproom on both banks. You leave by the North Road with what you came with, less what the pillory cost you, and on the North Bar someone has chalked a sheep with a crown on. Justice Broom, they tell you, said afterwards that it was the best lie of the Fair, and she was sorry about the pillory, and would do it again.".
  Ending sold "Five Coin a Head" when fourthDay() and drownedSold(party) "Ossett's agent's sledges go out over the downs at first light with Harker's hired roped on them, the first party out of Pellam since the snow, and among them, coughing, Dickon Cobb, landed. You have fifteen coin. Kemble wrote you a receipt. Widow Saffery's rope-walk house on the bridge is shut and nobody knows where she is. On the stake by the Black Reach, where the hole was, somebody has hung a hat, and under it, in the snow, put a penny.".
  Ending unswearing "The Unswearing" when fourthDay() and unsworn(lisk) "By morning the Lisk is running again, and in the Court's book, landed with everything else before the ice went, a new line in the Reeve's own hand: A HAND IS BOUND TO WHAT THE ONE WHO SHOOK IT KNEW. It is only law on the river, and the river is water now; but it was cried at the Glove Post before the whole of Pellam, and by noon the Wool Exchange is in a panic, because if it were law on dry ground half the bargains in the city would be void, and every factor on the floor knows which half. Harker's hired walk out of Pellam by the North Road in the thaw, north to the fells, free. Master Harker does not come to the Exchange. Edrin Callow, discharged, preaches in Bankside that nothing stays, except, he now adds, what a person truly knew; and has more listeners than he did, and coughs less.".
  Ending long_con "The Long Con" when fourthDay() and hiredReleased(lisk) and hiredSquire(lisk) "By noon the North Road is running with meltwater, and twenty young people from the north country are walking up it toward the fells, free, with their tokens still in their hats, because Master Josias Harker, wool-factor and churchwarden, sold their hands to the Squire of Hawsfold for two hundred ewes, and the Squire gave them back before the Reeve. Harker has a landed bargain for a flock at the shearing, good in any court of the country, and in the spring he will go up to Hawsfold under Swale Fell with it to collect. What he finds there depends on Abel Haws. The Fair is already a ballad on Noll Brisket's press, in which the Squire has a golden fleece and Harker is a goose.".
  Ending flight "Not Landed" when fourthDay() and hiredFled(lisk) "Under Pellam Bridge the Lisk goes by in lumps, and on the far side of the downs, in the snow, twenty people from the north country walking north-about to the fells by roads nobody in Pellam can follow until the thaw comes up the valleys; not landed, and not anybody's. Master Harker's bondhouse on Hay Wharf stands open on the river with its straw trodden and its brazier cold. Kemble's book has twenty little drawn hands in it, for shaken, and against every one, in the Court's book, nothing at all. On the Black Reach the hole that never froze is only river now, like the rest.".
  Ending flock_that_was "The Flock That Was" when fourthDay() and flockHonest(lisk) "The river has gone by morning and left one bargain behind it, landed in the Court's book, good from here to the sea: two hundred Swale ewes at Hawsfold under Swale Fell, to Josias Harker, at the shearing. They exist. You bought them off Abel Haws for forty coin and sold them to Harker for sixty, and every hand that was shaken in it will be kept, which is more than can be said for any other bargain of the Fair. Harker will get his ewes, and Abel his forty, and you twenty and a story. It is the most honest swindle anyone in Pellam has ever heard of, and nobody believes it.".
  Ending score_lost "The Score, and Ursel's" when fourthDay() and urselTook(party) and melted(flock_bargain) "The bargain for two hundred ewes that never were went out to sea with the ice, unlanded, and Master Harker is thirty coin the poorer; and so are you, because Ursel Cobb took it out of your coat at the Glove Post five minutes after he paid it, and went, and never shook on anything. Somewhere on the North Road in the thaw there is a woman in a caped coat with sixty coin, laughing like a door. You find, after a while, that you do not entirely mind.".
  Ending score "The Score" when fourthDay() and earnestTaken(party) and melted(flock_bargain) "Somewhere under the water at Pellam Bridge, going out to sea, is a bargain for two hundred fell ewes at Hawsfold that was shaken on the ice and never landed. Master Harker is thirty coin the poorer and the Squire of Hawsfold is nowhere. In the taprooms of Bankside they are telling it already, with improvements. Of Harker's hired, they say nothing: they were landed at the Landing, and went south on Ossett's agent's sledges at first light, which is the kind of thing nobody tells.".
  Ending bound "Hired" when fourthDay() and hiredHand(party) and landed(hire_bargain) "At first light you are on Ossett's agent's sledge on the south road over the downs, roped to Tansy Hobb on one side and a big lad with a whip in his hat on the other, landed, a year's service, good in any court of the country, on a farm in the hills that is a hole in a hill called Gallowmoor. You shook. Harker's palm was soft and very warm.".
  Ending away "Away" when fourthDay() and not inPellam() and not earnestTaken(party) "You are not in Pellam when the ice goes out, and you hear of it in another country, from a drover: the Lisk at Pellam froze from bank to bank and they held a Fair on it, the first in thirty-one winters, with a gin-tent and a printing press and an ox, and a law of its own; and it went out on the third night with a noise like the end of the world. Something about a wool-factor and his hired. The drover does not remember, and talks about the price of fleece.".
  Ending landed "Landed" when fourthDay() "In the morning there is a river under Pellam Bridge, black and running, full of ice. Everything that was landed at the Glove Post is good from here to the sea: Harker's twenty hired among the rest, who went south at first light on Ossett's agent's sledges over the downs, roped, with their tokens still in their hats, to the farm in the hills at Gallowmoor. Pellam goes back to the wool. The watermen put their boats in. Noll Brisket prints a ballad of the Great Frost, at a penny, in which nobody drowns.".
}

Module pellam "The Liberty of the Ice" {
  // ── The Fair: its trades and its crowd ────────────────────────────────────────────────────────────────────────────
  // The street of booths was written from the first (gin and gingerbread, skittles with a frozen sheep's head, a
  // swing-boat, slices of the ox, a man selling the future), but only as what is seen; a stranger came down the stairs
  // into a Fair with nobody in it to buy from or ask (the owner's review of Mission 18). These are its people: on the
  // ice from eight in the morning until nine at night while it holds, and gone home over the bridge after; and its
  // crowd, which goes where the Fair's day goes.

  // Mother Gage's booth, the first at the foot of Swan Stairs: everything the frost wants.
  Person gage "Mother Gage" at swan_foot {
    Role "a chandler in three shawls, at the first booth at the foot of Swan Stairs". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "'Candles, lamp-oil, lanterns, rope, a bar for the ice and a sack for what you win,' says a woman in three shawls, all in one breath, from the first booth at the foot of the stairs. 'Everything the frost wants and nothing it doesn't. You're new. You'll want a light. They all want a light, after.'".
    Greets again "'Back for the light,' says Mother Gage. 'They always come back for the light.'".
    Sells candle for 1 coin from 12. Sells torch for 1 coin from 8. Sells lantern for 6 coin from 2. Sells lamp_oil for 1 coin from 8.
    Sells rope for 1 coin from 4. Sells crowbar for 2 coin from 3. Sells sack for 1 coin from 6. Sells chalk for 1 coin from 6.
    Sells blanket for 1 coin from 4. Sells iron_spikes for 1 coin from 6.
  }
  Rule gage_day when hour(clock) >= 8 and hour(clock) < 21 and not iceGone() and not at(gage, swan_foot) { Assert at(gage, swan_foot). }
  Rule gage_home when (hour(clock) >= 21 or hour(clock) < 8 or iceGone()) and not at(gage, limbo) { Assert at(gage, limbo). }
  Observe gage_booth at swan_foot when at(gage, swan_foot) "At the foot of the stairs the first booth of all is a chandler's, hung with candles in bundles like onions, with lanterns on a pole and a coil of rope for a doorstep.".
  Topic gage_ice with gage "Ask Mother Gage what a stranger ought to know on the ice" when true once {
    Says "'Know?' She does not stop tying wicks. 'Don't shake. That's one. Glove's at the top of the street, and the crier cries the Liberty under it at noon, say what you like, keep what you shake on, and it's the second half they mean. Court's the patched tent, four o'clock. Lamb's at the bottom, Bench at seven. Past the ox it's the Reach, grey on black, and you keep to the sledge-marks or you go in.' She looks at your hands. 'Two. You'll want a light. Penny a candle, and the best in Pellam, there being no other.'".
    On discuss { Assert knows(actor, fair_known). }
  }
  Topic gage_thaw with gage "Ask Mother Gage how long the ice will hold" when true once {
    Says "'Till it goes.' She does not look up from her wicks. 'Last time it went in the night, all at once, with the Fair on it. I lost a booth and a husband. The booth was the better loss.' She ties off a bundle. 'Three days, the watermen say, for what watermen know. When it goes, be on a bank.'".
  }
  Discovery fair_known "The Frost Fair: Freezeland Street runs down the ice from the Glove Post at its top to the Frozen Lamb at its lower end. The Court of the Ice sits at four in the patched tent by the Glove; the Liars' Bench is at the Lamb from seven; the bear is at its stake past the Hiring Ring, and the ox roasts at the bottom of the street. Past the ox is the Reach, grey ice over black water, where people keep to the sledge-marks." {
    Known by gage, crowd, meg.
  }

  // The crowd: thick about the Glove Post by day, round the Court when it sits, at the Liars' Bench of an evening,
  // and gone to bed after.
  Person crowd "the crowd" at limbo {
    Role "apprentices, wool-men, skaters, mothers, a sweep, children with hot codlings: the Fair" when not lampLit().
    Role "the Fair after dark, louder than by day, and redder in the face" when lampLit().
    Ancestry human. Peaceable. Numbers 12. Pronouns they. Manner jovial.
    Greets "Nobody in the crowd is talking to you in particular, and everybody is willing to: an apprentice with a hot codling, a woman with a baby in her shawl, a sweep. 'First time on the ice?' says the apprentice. 'You'll want to see the bear.'".
    Greets again "The crowd shoulders round you, cheerful, cold, smelling of gin and gingerbread.".
  }
  Rule crowd_street when hour(clock) >= 9 and (hour(clock) < 16 or (hour(clock) >= 17 and hour(clock) < 19)) and not iceGone() and not at(crowd, freezeland) { Assert at(crowd, freezeland). }
  Rule crowd_court when hour(clock) >= 16 and hour(clock) < 17 and not iceGone() and not at(crowd, court) { Assert at(crowd, court). }
  Rule crowd_bench when hour(clock) >= 19 and hour(clock) < 23 and not iceGone() and not at(crowd, lamb) { Assert at(crowd, lamb). }
  Rule crowd_bed when (hour(clock) >= 23 or hour(clock) < 9 or iceGone()) and not at(crowd, limbo) { Assert at(crowd, limbo). }
  Topic crowd_see with crowd "Ask the crowd what there is to see on the ice" when true once {
    Says "Everybody tells you at once. The bear, past the Hiring Ring, that dances if you've a penny for Hester. The ox, at the bottom, that's sinking. The swing-boat, here, that you can see the whole Fair from. The Court, at four, in the patched tent, where the Reeve tries handshakes. The Liars' Bench at the Lamb tonight, a silver tongue for the best lie. 'And the knight,' says the apprentice, pointing with his codling at the lean-to under the Glove Post, 'who lives on the ice.'".
    On discuss { Assert knows(actor, fair_known). }
  }
  Topic crowd_knight with crowd "Ask the crowd about the knight who lives on the ice" when at(gant, freezeland) and not gantFree(gant) and not gantSafe(gant) once {
    Says "'Sir Lionel?' The apprentice laughs. 'Owes Master Harker thirty coin, and can't put a foot off the ice or the bailiffs have him: they're stood at the top of both stairs, look.' A woman in a shawl: 'He says it was three.' 'Everybody says it was three.' 'He says it nicer than most.'".
  }
  Topic crowd_hiring with crowd "Ask the crowd about Master Harker's hiring" when not iceGone() once {
    Says "'At the Ring, ten till noon, for a farm in the hills,' says the sweep. 'Good wages. Food. A bed.' A woman in a shawl says, 'My cousin went, at the spring hiring. Not a word since.' 'Your cousin can't write.' 'Nor can any of them, then,' she says, 'for none of them ever has,' and the crowd goes on to talk about the ox.".
  }

  // Long Meg's gingerbread, at the Glove Post.
  Person meg "Long Meg" at limbo {
    Role "a gingerbread-wife a head taller than anyone on the ice, with a tray of gilt gingerbread pigs". Ancestry human. Peaceable. Pronouns she. Manner cheerful.
    Greets "'Gingerbread!' says a woman a head taller than anybody, from behind a tray of pigs with gilt on their backs. 'Penny a pig. Gilt's extra, and you can't eat it, and everybody wants it.'".
    Greets again "Long Meg holds up a pig. 'Gilt this time?'".
    Sells rations for 1 coin from 30.
  }
  Rule meg_day when hour(clock) >= 8 and hour(clock) < 21 and not iceGone() and not at(meg, freezeland) { Assert at(meg, freezeland). }
  Rule meg_home when (hour(clock) >= 21 or hour(clock) < 8 or iceGone()) and not at(meg, limbo) { Assert at(meg, limbo). }
  Topic meg_liberty with meg "Ask Long Meg what the Liberty means" when true once {
    Says "'Say what you will,' says Meg, 'means a lie's no crime on the ice. I can tell you these pigs are gold all through, and you can tell me you're a duke, and neither of us goes to the stocks. Keep what you shake on means the other thing.' She holds up her hand. 'Shake on a thing on this ice and the Reeve holds you to it, whatever was said to get you to. So you don't. Not with me, not with a waterman, and never with a woman in a man's caped coat, if you see one.'".
  }

  // The ox roast: the Butchers' Company's men, and slices at a penny, on bread.
  Person butchers "the Butchers' Company's men" at limbo {
    Role "three butchers in aprons over their greatcoats, round the ox, arguing". Ancestry human. Peaceable. Numbers 3. Pronouns they. Manner proud.
    Greets "'A penny a slice, on bread, with the dripping,' says the biggest butcher, without taking his eyes off the hearth, which is sinking. 'Don't stand on the soft bit.'".
    Sells rations for 1 coin from 40.
  }
  Rule butchers_day when hour(clock) >= 9 and hour(clock) < 20 and not iceGone() and not at(butchers, ox_roast) { Assert at(butchers, ox_roast). }
  Rule butchers_home when (hour(clock) >= 20 or hour(clock) < 9 or iceGone()) and not at(butchers, limbo) { Assert at(butchers, limbo). }
  Topic butchers_ox with butchers "Ask the butchers whether the ox will go through the ice" when not iceGone() once {
    Says "All three answer. The hearth is sinking a hand a day; at a hand a day the ox has four days; the ice will go before the ox does; the ice will never go; the Company has a wager on it with the Watermen, which is why there is a waterman over there watching the hearth with a stick. 'It'll be the river or the ox,' says the biggest butcher, 'and my money's on the ox.'".
  }

  // The skittle alley and the swing-boat, by the Glove Post, a penny a go.
  Relation bowled(group). Relation swung(group). Relation fortuned(group).
  Action bowl_skittles(actor: group, site: place) "Bowl a frozen sheep's head down the skittle alley, a penny a go" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, freezeland) and not dark() and not iceGone()
      and quantity(actor, gold) >= 1 and not bowled(actor).
    Time 5 minutes.
    Resolve check(actor, brawn, dc_fair).
    On success { Decrease quantity(actor, gold) by 1. Increase quantity(actor, rations) by 2. Assert bowled(actor). }
    On failure { Decrease quantity(actor, gold) by 1. Assert bowled(actor). }
    Result "The sheep's head goes down the alley like a cannon-ball, frozen hard as one, and takes out all nine and the boy who was setting them up, who is not hurt and is delighted. The alley-man gives you two gingerbread pigs off Long Meg's tray, and Long Meg puts them on his account.".
    Otherwise "The sheep's head goes down the alley with a wobble, looking at you reproachfully all the way, and takes out two. 'Better than the alderman,' says the alley-man, kindly, and that is all you get.".
  }
  Action ride_swing(actor: group, site: place) "Ride the swing-boat up over the Fair, a penny" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, freezeland) and not dark() and not iceGone()
      and quantity(actor, gold) >= 1 and not swung(actor).
    Time 10 minutes.
    On success { Decrease quantity(actor, gold) by 1. Assert swung(actor). Assert knows(actor, fair_known). Assert knows(actor, fair_from_above). }
    Result "Up, and down, and up, higher each time, until at the top of the swing you can see all of it: Freezeland Street running down the white river from the bridge, the Glove on its mast, the Court's patched tent beside it, the smoke of the ox at the bottom of the street, the Hiring Ring and a dark bulk at the stake past it that is the bear; on the Bankside shore two men in brown stamping at the head of Hay Stairs; and past the last booth, a long way down the grey Reach, a ship locked in the ice at a slant, with her masts gone. Then down, and the Fair closes over you again.".
  }
  Discovery fair_from_above "From the top of the swing-boat: two bailiffs in brown keep the head of Hay Stairs on the Bankside shore, as one keeps Swan Stairs; and far down the Reach past the last booth, a ship is locked in the ice at a slant, with her masts gone.".
  Action buy_fortune(actor: group, site: place) "Pay the man selling the future a penny for yours" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, freezeland) and not iceGone()
      and quantity(actor, gold) >= 1 and not fortuned(actor).
    Time 5 minutes.
    On success { Decrease quantity(actor, gold) by 1. Assert fortuned(actor). }
    Result "The man selling the future has a board that says so, and a cat, and he looks at your palm for a long time with the cat looking too. 'You'll be asked for your hand three times on this ice,' he says. 'Twice by people who want it, and once by somebody who has never given theirs to anybody. Take the third.' He closes your fingers over the palm. 'That's a penny's worth. The rest is dearer.'".
  }

  // The watermen on Swan Stairs, with their plank and their tin cup.
  Person stair_men "two watermen on the stairs" at limbo {
    Role "two watermen with a plank across Swan Stairs and a tin cup" when not stairsPaid(party).
    Role "two watermen on Swan Stairs, who nod to you as a freeman of the stairs" when stairsPaid(party).
    Ancestry human. Peaceable. Numbers 2. Pronouns they. Manner jovial.
    Greets "'A penny a stair,' says the bigger of the two watermen on the top step, without getting up. 'Shake on it.'".
    Greets again "The watermen on the stairs touch their caps.".
  }
  Rule stair_men_day when hour(clock) >= 8 and hour(clock) < 21 and not iceGone() and not at(stair_men, swan_lane) { Assert at(stair_men, swan_lane). }
  Rule stair_men_home when (hour(clock) >= 21 or hour(clock) < 8 or iceGone()) and not at(stair_men, limbo) { Assert at(stair_men, limbo). }
  Topic stair_men_penny with stair_men "Ask the watermen what a penny a stair buys" when not stairsPaid(actor) once {
    Says "'The freedom of both banks till the thaw,' says the bigger one. 'Up and down as you like. Twelve stairs here.' The smaller one says, 'Nine at Hay Stairs, if you're a Bankside sort.' 'Don't tell 'em that.' 'Pay at the bottom,' says the bigger one, 'or pay at the Court. Shake on it, and you're bound to it, by the Liberty. That's how the ice is. River froze and put us out of work, and now every hand on Pellam's worth a penny a stair.'".
  }
}

data/adventures/liberty-of-the-ice/frost:
Module pellam "The Liberty of the Ice" {
  // ── The three days, as weather ────────────────────────────────────────────────────────────────────────────────────
  // Each day of the Fair has its own sky, and the sky is the act: a hard blue frost for the farce's first day, when
  // everything is bright and nothing can be checked; the drowned weather of the second, a fog off the Reach in which
  // the city cannot see its own feet; and on the third the west wind, the thaw-wind, the bridge dripping, the ice
  // going grey, so that everything shaken on it is already counting the hours.
  Entity sky_one: fact "the first day's sky". Entity sky_two: fact "the second day's sky". Entity sky_three: fact "the third day's sky".
  Rule first_sky when firstDay() and inPellam() and not spread(sky_one) says "THE FIRST DAY OF THE FAIR. A hard blue frost, the sky like a glazed dish, not a cloud from the fells to the downs, and the sun on the snow so bright it hurts to look at. Your breath freezes in your scarf. Sound carries: you can hear a hammer on the far side of the river, and a girl laughing on the bridge, and under everything, from the ice, the noise of the Fair, like a hive." {
    Assert spread(sky_one). }
  Rule second_sky when secondDay() and hour(clock) >= 6 and inPellam() and not spread(sky_two) says "THE SECOND DAY OF THE FAIR. Fog, in the night, off the Reach: the watermen call it the drowned weather. It stands on the ice to the height of a house, white and wet and very still, so that from the bridge the Fair is a roof of sound with nothing under it, and in Freezeland Street the booths come at you out of it one at a time like ships. The cathedral bell sounds as if it were being rung in a cupboard. People speak low without knowing why." {
    Assert spread(sky_two). }
  Rule third_sky when thirdDay() and hour(clock) >= 6 and inPellam() and not spread(sky_three) says "THE THIRD DAY OF THE FAIR, AND THE LAST. The wind has gone round to the west in the night, soft and wet, smelling of earth for the first time in a month: the thaw-wind. The icicles along Fleece Row are dripping. Under Pellam Bridge, from every arch, water is running in threads down the stone, and where it falls the ice has gone grey and pocked, like old pewter. Nobody on the Fair says the word. Everybody looks at the sky." {
    Assert spread(sky_three). }
  Observe fog_freezeland at freezeland when secondDay() and hour(clock) >= 6 and hour(clock) < 14 "The fog has the Glove Post to half its height; above that, the great glove hangs in white nothing, dripping.".
  Observe fog_ice within the_ice when spread(sky_two) and secondDay() and hour(clock) >= 6 and hour(clock) < 14 and not at(party, freezeland) "Fog stands in the street to the height of the booth-roofs; the pennants at their peaks are lost in it, and their ropes go up into nothing.".
  Observe thaw_ice within the_ice when spread(sky_three) and not iceGone() and not at(party, freezeland) "Underfoot the ice has a skin of water, and the planks squelch, and the boards of the booths are dark with wet where they stand in it.".
  Observe fog_reach at black_reach when secondDay() and hour(clock) >= 6 and hour(clock) < 16 "In the fog the Black Reach has no other side. The ice creaks, close, and then far, and then close again, as if something were walking on it.".
  Observe fog_bridge at bridge_street when secondDay() and hour(clock) >= 6 and hour(clock) < 14 "Through the gaps between the houses, where the Fair should be, there is only white, and out of it the sound of the Fair.".
  Observe thaw_bridge at bridge_street when thirdDay() and not iceGone() "Water drips from every eave on the bridge. Down through the gaps, the ice under the arches is grey and wet and has lines on it, like a palm.".
  Observe thaw_freezeland at freezeland when thirdDay() and not iceGone() "The planks of Freezeland Street are standing in a skin of water. The great glove on the mast has thawed limp and hangs down, fingers first, dripping on the crier's barrel.".
  Observe thaw_ox at ox_roast when thirdDay() and not iceGone() "The ox's hearth has sunk to the bricks' depth in a pool of its own, and the Butchers have put planks round it, and nobody is standing very near.".

  // ── The bill on the Glove Post ────────────────────────────────────────────────────────────────────────────────────
  // Noll Brisket prints the day each morning and pastes it on the mast under the glove: what is on, and when.
  Observe bill_one at freezeland as reading when firstDay() and not iceGone() "A bill is pasted on the Glove Post, new this morning, the ink smudged with frost: THE GREAT FROST FAIR, FIRST DAY. — HIRING at the RING, TEN till NOON, by Master J. HARKER, for a farm in the hills. — The LIBERTY CRIED at NOON. — The COURT of the ICE sits at FOUR. — The LIARS' BENCH at the FROZEN LAMB from SEVEN. — A BEAR. AN OX. FROST-CREAM. — NO LAW BUT THE GLOVE.".
  Observe bill_two at freezeland when secondDay() and not iceGone() "Today's bill on the Glove Post, pasted over yesterday's: SECOND DAY. — The LAST HIRING, NINE till ELEVEN. — The COURT at FOUR. — The BENCH at SEVEN. — MARRIED, TOMORROW at NOON, at the ICE CHAPEL: ALDERMAN H. GOSLING and MISTRESS THESSALY HARKER. — Beware the Ice below the Bridge.".
  Observe bill_three at freezeland when thirdDay() and not iceGone() "Today's bill on the Glove Post, wet already: THIRD DAY. — The WEDDING at NOON. — The LANDING at TWO, before the REEVE: every hand shaken on the ice to be CRIED, and LANDED, or let go. — OFF THE ICE at NINE, every soul. — God keep the Liberty.".
  // The pillory stands empty by the stocks from the first day, with a board on it waiting to be written on.
  Observe pillory_waits at freezeland as feature when not landingAt(lisk) and not pilloried(party) and not iceGone() "Beside the stocks stands a pillory nobody is in, with snow on the board where the head goes, and a placard hung on it ready, blank, for whatever the Court writes there.".

  // ── The Book of Frosts ────────────────────────────────────────────────────────────────────────────────────────────
  // The Watermen's Company keeps, among its accounts, the river's own history: every frost the Lisk has stood, and what
  // was done on it. Seven in two hundred years. It is why there is a Liberty, and why Harker hires on the ice.
  Topic tredgold_book with tredgold "Ask Gaffer Tredgold what he is writing in the Company's book" when true once {
    Says "'The Frost.' He turns the book round for you. The front of it is accounts, fares and fines; the back, written from the other end and upside down, in a dozen hands, is something else. 'Every frost the river's stood. Seven, with this one, since there's been a Company.' He puts a thick finger on each. 'The First Frost, when Reeve Aldith sat on the ice to judge the watermen, so there was a Court. The Frost of the Glove: Hamo Gledhill shook on forty sacks on the ice and said on land he'd shaken on nothing, and the Reeve had his glove off him and nailed it to a mast. The Black Lambing, when the frost went on into April and the fell flocks died in the folds, and the fell farms came down to Pellam to be sold, and the children after them; that's when the Exchange was built, and the city made its Statute about servants after, that's painted on a board in the Scale Church porch, for all the good it's done. The Frost They Hanged the Reeve. The Short Frost, four days, when nothing was landed and every handfast melted, and they say that's why nobody marries on the ice. The Last Frost, thirty-one winters back. And this.' He takes his finger away. 'Four of the seven, the wolves came down after the river. Write that in, I said to my father. He said, they'll know.'".
    On discuss { Assert knows(actor, book_of_frosts). Assert knows(actor, wolves_down). }
  }
  Discovery book_of_frosts "The Watermen's Book of Frosts records seven frosts in two hundred years: the First (when the Court of the Ice began), the Frost of the Glove (when the Liberty began, with a factor's glove nailed to a mast), the Black Lambing (when the fell flocks died, the fell farms were sold to Pellam, and the hiring of the fell children began), the Frost They Hanged the Reeve, the Short Frost (when every handfast melted), the Last Frost thirty-one winters ago, and this one. In four of them the wolves came down after the river.".
  Topic tredgold_hanged with tredgold "Ask Gaffer Tredgold why they hanged the Reeve" when knows(actor, book_of_frosts) once {
    Says "'For landing a hand.' He closes the book. 'An alderman's son shook on a girl's dowry on the ice and broke it on the land, and Reeve Ottiline Broom landed it at the Landing all the same, before the city, and held him to it. The city hanged her off the bridge the day the ice went, for a riot. The Company cut the ice the night after and sent the Fair out to sea, and the alderman's son with it, nobody knows how.' He looks at the saws by the door. 'The ice is ours till it goes. After that it's water, and water's nobody's.' He goes back to his writing. 'Clemmy Broom is her granddaughter's granddaughter. She knows.'".
    On discuss { Assert knows(actor, reeve_hanged). }
  }
  Discovery reeve_hanged "In an earlier frost Reeve Ottiline Broom landed a bargain against an alderman's son and was hanged by the city off Pellam Bridge for it; the watermen cut the ice and sent the Fair out to sea. Justice Broom is her descendant.".

  // ── The Scale Church, and the Statute of Servants ─────────────────────────────────────────────────────────────────
  Person verger "Amos Tallis" at evenhands {
    Role "the verger of the Scale Church, very old, with a broom and a cold". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "The old verger leans on his broom by the great scales and looks at you without curiosity. 'If it's the Fair you want,' he says, 'it's down the hill. Everybody's down the hill.'".
    Greets again "Amos Tallis nods to you from beside the scales.".
  }
  Topic verger_scales with verger "Ask the verger about the scales" when true once {
    Says "'The Saint's.' He puts his hand flat on the great brass pan, as a man puts his hand on a horse. 'Every fleece Pellam ever sold went over these, once. The factors weigh their own now, in their own houses; they say the Saint's are slow.' He sniffs. 'They are slow. They're honest, and honest is slow.' He nods at the board in gold beside them. 'A false balance is abomination. And they bring their own weights to church on Sundays, and sit under that, and sing.'".
    On discuss { Assert knows(actor, scales_known). }
  }
  Discovery scales_known "The great scales of Saint Evenhand in the Scale Church once weighed every fleece Pellam sold; the factors now weigh their own.".
  Topic verger_statute with verger "Ask the verger about the board in the porch with the writing worn off it" when true once {
    Says "'The Statute of Servants.' He goes with you to look at it, slowly. You can make out a word or two under the soot: HIRED, LIBERTIES, CARRIED. 'The city made it after the Black Lambing, when the fell farms were sold, and the factors were hiring the fell children in the Cheaping and carrying them off to the dye-works over the hills and selling them on. No one hired within the liberties of Pellam shall be carried out of them, but to the place they were hired for. That's the gist.' He looks at it. 'It's never been repealed. It's only been gone round.' He nods down the hill, toward the river. 'The ice isn't the city. It's the Watermen's, bank to bank. The Statute doesn't run on it. Why do you think the hiring's on the ice?'".
    On discuss { Assert knows(actor, statute_servants). }
  }
  Discovery statute_servants "By the Statute of Servants, made after the Black Lambing, no one hired within the liberties of Pellam may be carried out of them except to the place they were hired for. The river is the Watermen's, not the city's, and the Statute does not run on the ice; which is why Harker hires there.".
  Topic verger_harker with verger "Ask the verger about Master Harker, the churchwarden" when knows(actor, statute_servants) once {
    Says "'A good churchwarden.' He sweeps a little round the scales. 'Pays for the candles. Every spring after the hiring he pays for a great candle, a pound of wax, to burn a week before the Saint. I asked him once what it was for.' He stops sweeping. 'He said, for the weight. I didn't ask him what he meant. You don't, with a churchwarden.'".
    On discuss { Assert knows(actor, harker_candle). }
  }
  Discovery harker_candle "Every spring after the hiring Master Harker pays for a pound of wax to burn a week before Saint Evenhand's scales, 'for the weight'.".
  // The Statute does not run on the ice, but Dickon was hired in the Cheaping at the spring hiring, on dry ground,
  // and carried to Gallowmoor: that is a matter for the city, after the thaw, where a lie is a crime.
  Relation statuteLaid(place).
  Topic gosling_statute with gosling "Tell Alderman Gosling that Dickon Cobb was hired in the Cheaping last spring and carried to Gallowmoor, against the Statute of Servants" when knows(actor, statute_servants) and (knows(actor, dickon_alive) or knows(actor, ledger_read)) and not statuteLaid(lisk) once {
    Says "He puts his pen down. 'In the Cheaping. Not on the ice.' He gets up and takes a book down from the shelf behind him, a fat one in calf with a chain on its spine, and turns it to a page he does not need to look for. 'On the ice I am nobody, any more than any of us. On the land I am an alderman of this city and a justice of its peace.' He reads, moving his lips. The fire settles twice. 'Harker,' he says at last, to the book, 'is going to be my father-in-law, or was.' He writes, carefully, a long time, and sands it, and folds it. 'At the Lady Day sessions,' says Alderman Gosling, 'on dry ground. Where a lie is a crime.'".
    On discuss { Assert statuteLaid(lisk). }
  }
  Rule news_statute when newsHour() and statuteLaid(lisk) once says "Of the Statute: on the first morning of the thaw the Town Clerk has nailed a paper to the door of Harker's house in Fleece Row, where everyone going down to the river can read it: that Josias Harker, factor, is to answer at the Lady Day sessions, under the Statute of Servants, for one Dickon Cobb, hired in the Cheaping and carried to Gallowmoor. On land, where a lie is a crime. By ten it has been torn down; by eleven Noll Brisket has printed it." { }

  // ── The wolves, before they come ──────────────────────────────────────────────────────────────────────────────────
  Discovery wolves_down "There are wolves down off the downs after the frozen river, as there are in a great frost: they have taken ewes from the fell folds, and been seen at first light on the sledge road at the foot of the Reach.".
  Topic abel_wolves with abel "Ask Abel what the fells are like, this winter" when secondDay() or thirdDay() once {
    Says "'White.' He turns his hat. 'White to the tops, and the becks froze, and the snow over the walls so you walk on them and don't know.' His bitch presses against his leg. 'And the wolves down. Three of ours out of the fold the week I came away, my sister's lad says, and the hurdles never touched; they came over the snow on the roof of the shed. The watermen say they've followed the river down to the downs.' He puts his hat on. 'They don't come in among folk. Not unless folk go out among them.'".
    On discuss { Assert knows(actor, wolves_down). }
  }
  Topic nab_wolves with nab "Ask Nab Pollard what the watermen saw on the Reach" when secondDay() or thirdDay() once {
    Says "'Wolves.' He says it the way he says the price of beer. 'Four of them, at first light, sat in a row on the sledge road where it comes off the Reach, like magistrates. Old Fowke saw them too, he says, but Fowke sees all sorts.' He wipes a cup. 'They come in a great frost, after the river. Fire keeps them off. So does meat, if you've some to spare, and a good loud voice, if you've the stomach. Or a sledge. Nothing on four legs keeps up with a sledge.'".
    On discuss { Assert knows(actor, wolves_down). }
  }
  Observe wolf_tracks at reach_head when secondDay() and not dark() and capable(party, woodcraft) and not knows(party, wolves_down) "In the snow on the ice at the edge of the Reach, tracks: four sets, big, splayed, in a line, come up from the south on the sledge road in the night and gone back. Not dogs. Dogs wander. These went where they meant to go." teaches wolves_down.
}

Module pellam "The Liberty of the Ice" {
  // ── Sir Lionel Gant, on the ice ───────────────────────────────────────────────────────────────────────────────────
  // A ruined gentleman who has lived on the ice since the freeze, in a lean-to of sailcloth in the lee of the Glove
  // Post, because no bailiff's writ runs on it. His bond (thirty coin, to his tailor, bought up by Harker) waits for
  // him on both banks. He never borrowed thirty; he borrowed three, and somebody has made a nought of the full stop.
  Person gant "Sir Lionel Gant" at freezeland {
    Role "a gentleman in a waistcoat that was magnificent ten years ago, living on the ice" when not gantSafe(gant) and not gantFree(gant).
    Role "a gentleman in his shirt-sleeves, owing nobody anything" when gantFree(gant) or gantSafe(gant).
    Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "A tall thin gentleman in a crimson waistcoat with half its buttons gone sweeps off a hat that has seen better heads. 'Sir Lionel Gant, of nowhere in particular, at your service. You'll forgive the address: I live on the ice. It is the only parish in the country where I owe nobody anything.'".
    Greets again "Sir Lionel sweeps off his hat again.".
  }
  Relation gantSafe(group). Relation gantFree(group). Relation gantTaken(group). Relation gantPaid(group). Relation gantVoided(group).
  Relation gantCoatGiven(group).
  Observe gant_lean at freezeland when at(gant, freezeland) and not iceGone() "In the lee of the Glove Post, a lean-to of sailcloth on two oars, with a brazier, a folding chair, a bottle and a gentleman in it.".
  Discovery gant_bond "Sir Lionel Gant owes thirty coin on a bond to his tailor, which Master Harker has bought up; bailiffs wait for him on both banks to take him the moment he steps off the ice. He swears he borrowed three." {
    Known by gant, kemble.
  }
  Topic gant_why with gant "Ask Sir Lionel why he lives on the ice" when true once {
    Says "'Debt.' He says it with a kind of pride. 'Thirty coin, to my tailor, for this.' He spreads the waistcoat. 'Which I dispute. I borrowed three. A man does not forget three; it is such a small sum, one remembers being ashamed of it.' He pours from the bottle. 'Harker bought the bond from the tailor, as he buys everything, cheap, and there are bailiffs at the head of both stairs with a writ, and the moment I set foot on dry ground I am in the Fleece Row compter till I pay it, which is to say for ever.' He raises the glass to the Glove. 'Long live the ice.'".
    On discuss { Assert knows(actor, gant_bond). }
  }
  Topic gant_thaw with gant "Ask Sir Lionel what he will do at the thaw" when knows(actor, gant_bond) once {
    Says "He looks at the river for a while. 'There is the Clink,' he says, 'in Bankside. A liberty of its own, where a man inside owes nobody anything until he comes out. A man could live in the Clink.' He does not sound as if he thinks a man could. 'If he could get there. The bailiffs know it as well as I do.' He brightens, with an effort. 'Or the ice will hold. Quarle says it will hold for ever. I have shares.'".
    On discuss { Assert knows(actor, clink_known). Assert acceptsEscort(gant, actor). }
  }
  Discovery clink_known "The Clink in Bankside is a liberty of its own: a debtor inside it owes nobody anything until he comes out. Sir Lionel Gant could live there, if he could reach it past the bailiffs on Hay Stairs.".
  // The counterpart: his copy of the bond, which he cannot read for the shame of it, and has never looked at.
  Kind counterpart_kind "Sir Lionel's counterpart" is gear worth 0 weighing 0 described "Sir Lionel Gant's copy of his bond to his tailor, folded very small, in a fair clerk's hand: the sum, written out in words, is three coin.".
  Item counterpart "Sir Lionel's counterpart of his bond" is counterpart_kind at limbo.
  Relation counterpartGiven(group).
  Topic gant_counterpart with gant "Ask Sir Lionel whether he kept his own copy of the bond" when knows(actor, gant_bond) and not counterpartGiven(gant) once {
    Says "'The counterpart.' He pats his waistcoat, and finds it, folded small. 'Never looked at it. One doesn't.' He holds it out to you without unfolding it, the way a man holds out a letter from a woman he has wronged. 'You read it. I'll have another glass.'".
    On discuss { Assert counterpartGiven(gant). }
  }
  Rule counterpart_comes when counterpartGiven(gant) and at(counterpart, limbo) and at(party, ?p) { Retract at(counterpart, limbo). Assert at(counterpart, ?p). }
  Action read_counterpart(actor: group, reader: member, site: place) "Read Sir Lionel's counterpart against what Harker's writ says" {
    Requires able(actor) and at(actor, site) and memberOf(reader, actor) and ownedItem(counterpart, reader) and knows(actor, gant_bond) and not benighted(actor) and not knows(actor, gant_altered) and not counterpartTried(actor).
    Time 1.
    Resolve check(actor, lore, dc_easy).
    On success { Assert knows(actor, gant_altered). Assert counterpartTried(actor). }
    On failure { Assert counterpartTried(actor). }
    Result "Three coin, in words, in the tailor's clerk's hand, and a date, and Sir Lionel's flourish. The writ the bailiffs carry says thirty. Somebody in Fleece Row has turned the bond's figure 3 and its full stop into a 30, in good ink, carefully; but the words cannot be turned, and on the counterpart the words say three.".
    Otherwise "It is all legal hand and whereases, and you cannot make the sum out of it. Somebody with more law than you might.".
  }
  Relation counterpartTried(group).
  Discovery gant_altered "Sir Lionel Gant's bond was for three coin. The copy Harker bought, from which his writ was drawn, has been altered in Fleece Row to thirty; his own counterpart still says three, in words.".
  // A plainer way: pay it.
  Action pay_gant(actor: group, site: place) "Pay Sir Lionel's thirty coin to Kemble, and have the writ withdrawn" {
    Requires able(actor) and company(actor) and at(actor, site) and at(kemble, site) and knows(actor, gant_bond) and quantity(actor, gold) >= 30 and not gantFree(gant) and not gantSafe(gant).
    Time 2 minutes.
    On success { Decrease quantity(actor, gold) by 30. Increase quantity(harker, gold) by 30. Assert gantPaid(gant). Assert gantFree(gant). }
    Result "Kemble counts it, writes a receipt, and sands it. 'Master Harker will be gratified,' he says. 'He had quite given up hope of Sir Lionel.' He does not look surprised that anyone would pay thirty coin for Sir Lionel Gant. Nothing surprises Kemble.".
  }
  // Or get him to the Clink, at night, when the bailiffs have gone home.
  Person bailiffs "the bailiffs" at hay_stairs {
    Role "a pair of bailiffs in brown with a writ, stamping in the snow at the head of Hay Stairs". Ancestry human. Peaceable. Numbers 2. Pronouns they.
  }
  Person swan_bailiff "a bailiff" at swan_lane {
    Role "a man in brown with a copy of the writ, at the head of Swan Stairs". Ancestry human. Peaceable. Pronouns he.
  }
  // Asked, a bailiff says whose writ it is, and holds it up, and does not let go of it.
  Topic bailiff_writ with swan_bailiff "Ask the bailiff whose writ he carries" when not gantFree(gant) and not gantSafe(gant) once {
    Says "'Sir Lionel Gant's,' says the bailiff, and holds it up for you to read without letting go of it. 'At the suit of Josias Harker, wool-factor, thirty coin. He's on the ice, and the ice is a liberty, so I stand here and he stands there.' He stamps his feet. 'He'll come off it. They all come off it, at the thaw.'".
    On discuss { Assert knows(actor, gant_bond). }
  }
  Topic bailiffs_writ with bailiffs "Ask the bailiffs who they are waiting for" when not gantFree(gant) and not gantSafe(gant) once {
    Says "'A gentleman in a red waistcoat,' says one bailiff. 'Thirty coin, at the suit of Master Harker,' says the other. 'If you see him on this side of the river,' says the first, 'you'll tell us.' 'For a consideration,' says the second. They go back to stamping.".
    On discuss { Assert knows(actor, gant_bond). }
  }
  Initially Assert serves(bailiffs, harker). Initially Assert serves(swan_bailiff, harker).
  Initially Assert writServer(bailiffs). Initially Assert writServer(swan_bailiff).
  Relation writServer(group).
  Rule bailiffs_day when hour(clock) >= 7 and hour(clock) < 21 and not gantFree(gant) and not gantSafe(gant) and not at(bailiffs, hay_stairs) { Assert at(bailiffs, hay_stairs). Assert at(swan_bailiff, swan_lane). }
  Rule bailiffs_night when (hour(clock) >= 21 or hour(clock) < 7) and not at(bailiffs, limbo) { Assert at(bailiffs, limbo). Assert at(swan_bailiff, limbo). }
  Rule bailiffs_done when (gantFree(gant) or gantSafe(gant)) and not at(bailiffs, limbo) { Assert at(bailiffs, limbo). Assert at(swan_bailiff, limbo). }
  Rule gant_seized when following(gant, party) and at(gant, ?p) and at(?b, ?p) and writServer(?b) and not iceRoom(?p) and not gantTaken(gant) and not gantFree(gant)
    says "'Sir Lionel Gant!' The bailiffs have him by both arms before his foot is properly off the last stair, with the writ held up in front of his nose. 'At the suit of Josias Harker, thirty coin. You'll come to the compter.' He goes, very upright, saying over his shoulder, 'It was three,' to nobody in particular." {
    Assert gantTaken(gant). Retract following(gant, party). Assert at(gant, limbo). }
  Rule gant_follows when following(gant, party) and at(party, ?p) and not at(gant, ?p) and not gantTaken(gant) { Assert at(gant, ?p). }
  Rule gant_in_clink when following(gant, party) and at(gant, clink_yard) and not gantSafe(gant)
    says "Inside the Clink gate Sir Lionel Gant stops, and takes off his hat, and looks round the yard, at the debtors at their windows and their washing and their dogs, as if it were a palace. 'Gentlemen,' he says, to the yard. 'Sir Lionel Gant. I owe nobody anything.' A cheer goes up from the windows. He turns to you. 'I shan't forget it. Here.' He takes off his coat, the one good coat he has, and puts it into your arms. It is still warm, and smells of tobacco and the inside of a trunk." {
    Assert gantSafe(gant). Retract following(gant, party). Retract acceptsEscort(gant, party). Assert gantCoatGiven(gant). }
  Observe gant_clink at clink_yard when gantSafe(gant) "Sir Lionel Gant is in the Clink yard, holding court among the debtors from a borrowed chair.".
  Rule gant_safe_stays when gantSafe(gant) and not at(gant, clink_yard) { Assert at(gant, clink_yard). }
  // Freed by paying, he gives his coat as freely.
  Rule gant_paid_coat when gantPaid(gant) and not gantCoatGiven(gant) and together(gant, party) says "Sir Lionel takes your hand in both of his. 'Three coin,' he says. 'It was three. But you paid thirty, which is more than anyone has ever thought me worth.' He is out of his coat before you can stop him, and has it round your shoulders, and pulls the lapels straight. 'A man who would pay thirty coin for me,' he says, 'ought at least to look as if he could afford it.'" {
    Assert gantCoatGiven(gant). }
  Kind gant_coat_kind "Sir Lionel's coat" like climbing_harness granting persuasion worth 6 weighing 1
    described "A gentleman's coat of plum-coloured broadcloth, London-cut, ten years out of fashion, the lining gone at one elbow, the silver buttons long since sold and replaced with horn. Anyone who wears it is spoken to as if they had money.".
  Item gant_coat "Sir Lionel's coat" is gant_coat_kind at limbo.
  Rule coat_comes when gantCoatGiven(gant) and at(gant_coat, limbo) and at(party, ?p) { Retract at(gant_coat, limbo). Assert at(gant_coat, ?p). }
  Rule gant_ice_day when hour(clock) >= 7 and not iceGone() and not following(gant, party) and not gantSafe(gant) and not gantTaken(gant) and not gantFree(gant) and not landingAt(lisk) and not at(gant, freezeland) { Assert at(gant, freezeland). }
}

data/adventures/liberty-of-the-ice/gosli:
Module pellam "The Liberty of the Ice" {
  // ── The wedding at the Ice Chapel ─────────────────────────────────────────────────────────────────────────────────
  // At noon on the last day Thessaly Harker is to marry Alderman Hamnet Gosling at the Ice Chapel, on the ice, without
  // banns, because her father wants an alderman on the bench beside the Reeve at the Landing. Gosling, a widower and a
  // bad poet, has loved Bel Ashby since the last ice, when he married her on it, the night it went out. Thessaly writes
  // the Frost Gazette as Mr. Icicle, at Noll Brisket's press, at night; Noll would set the Bible backwards for her.
  Query weddingOn() means thirdDay() and hour(clock) >= 12 and hour(clock) < 13.
  Relation weddingDone(place). Relation goslingHarker(group). Relation goslingWedsBel(group). Relation thessalyWedsNoll(group).
  Relation weddingBroken(place). Relation witnessFree(group).

  // ── Alderman Hamnet Gosling ───────────────────────────────────────────────────────────────────────────────────────
  Person gosling "Alderman Hamnet Gosling" at gosling_study {
    Role "an alderman of Pellam, stout and anxious, with ink on his cuffs" when not goslingWedsBel(gosling).
    Role "an alderman, married, astonished" when goslingWedsBel(gosling).
    Ancestry human. Peaceable. Pronouns he. Manner compassionate.
    Greets "Alderman Gosling looks up from a sheet of paper covered in crossings-out with the face of a man rescued from drowning. 'Company! Thank God. Sit down. Do you know anything that rhymes with Thessaly?'".
    Greets again "'Ah,' says Alderman Gosling. 'Anything yet? With Thessaly?'".
  }
  Rule gosling_study_day when hour(clock) >= 8 and hour(clock) < 14 and not weddingOn() and not at(gosling, gosling_study) { Assert at(gosling, gosling_study). }
  Rule gosling_court when hour(clock) >= 14 and hour(clock) < 18 and not iceGone() and not landingAt(lisk) and not at(gosling, court) { Assert at(gosling, court). }
  Rule gosling_lamb when hour(clock) >= 19 and hour(clock) < 23 and not iceGone() and not at(gosling, lamb) { Assert at(gosling, lamb). }
  Rule gosling_home when (hour(clock) >= 23 or hour(clock) < 8) and not at(gosling, limbo) { Assert at(gosling, limbo). }
  Observe gosling_study_scene at gosling_study when true "Alderman Gosling's study: a fire, a great many books of verse, a portrait of the late Mrs. Gosling looking patient, and a desk buried in sheets of paper, all of them beginning 'O Thessaly'.".
  Observe gosling_at_lamb at lamb when at(gosling, lamb) and at(bel, lamb) and not goslingWedsBel(gosling) "Alderman Gosling sits at the end of the Frozen Lamb's bar over a hot gin he does not drink, and does not look at Bel Ashby, so carefully that everyone else in the tent does.".
  Topic gosling_poem with gosling "Ask the alderman what he is writing" when true once {
    Says "'An epithalamium. A wedding-song. For my own wedding, on the last day of the ice.' He shows you the sheet. 'Josias Harker's daughter. A very clever young woman, much too clever for me, she will tell you so. Her father's idea.' He crosses something out. 'The trouble is, nothing rhymes with Thessaly. I have been at it nine days. Every time I get going it turns into a poem about skating.' He looks at the window. 'I used to skate.'".
    On discuss { Assert knows(actor, gosling_poem). }
  }
  Discovery gosling_poem "Alderman Gosling is writing a wedding-song for his own wedding to Thessaly Harker, a match her father made; nothing rhymes with Thessaly, and every time he gets going it turns into a poem about skating.".
  Relation poemHelped(group). Relation goslingStirred(group). Relation goslingKnows(group). Relation belTold(group).
  Action rhyme_gosling(actor: group, site: place) "Find the alderman a rhyme for Thessaly, and make him read the poem through" {
    Requires able(actor) and company(actor) and at(actor, site) and at(gosling, site) and knows(actor, gosling_poem) and not poemHelped(actor) and not rhymeTried(actor).
    Time 3.
    Resolve check(actor, persuasion, dc_easy).
    On success { Assert poemHelped(actor). Assert goslingStirred(gosling). Assert rhymeTried(actor). }
    On failure { Assert rhymeTried(actor). }
    Result "You give him 'necessary', which is shameless, and he seizes it, and reads you the whole poem through to see if it fits. It is quite bad, and then for twelve lines, near the end, it is not bad at all: a girl at the last Frost Fair skating backwards on the Flashes in a red shawl, laughing, thirty-one winters ago. He stops reading. 'That's not Thessaly,' he says, quietly. 'Is it.' He holds the sheet at arm's length, the way a man holds a letter from his bank. 'That was never Thessaly.'".
    Otherwise "You try, and he tries, and nothing rhymes with Thessaly, and you both give up and he gives you a glass of something.".
  }
  Relation rhymeTried(group).
  // A word for the Squire, from a man Harker trusts about everything but poetry.
  Kind gosling_letter_kind "a letter from Alderman Gosling" is gear worth 0 weighing 0 described "A letter in Alderman Gosling's round hand to Master Josias Harker, commending the bearer as a person of the greatest good sense in poetry and in all things, and asking him to show them every civility.".
  Item gosling_letter "Alderman Gosling's letter to Harker" is gosling_letter_kind at limbo.
  Relation letterGiven(group).
  Topic gosling_word with gosling "Ask the alderman for a word to Master Harker on your behalf" when poemHelped(actor) and posedSquire(actor) and not letterGiven(gosling) once {
    Says "'To Josias? With pleasure.' He writes it on the back of a crossed-out stanza and seals it with his thumb. 'A person who can find a rhyme for Thessaly can be trusted with anything. I've said so.'".
    On discuss { Assert letterGiven(gosling). }
  }
  Rule letter_comes when letterGiven(gosling) and at(gosling_letter, limbo) and at(party, ?p) { Retract at(gosling_letter, limbo). Assert at(gosling_letter, ?p). }

  // ── Parson Doody and the Ice Chapel ───────────────────────────────────────────────────────────────────────────────
  Observe chapel_scene at chapel when not visitedBefore(chapel) "The Ice Chapel: a booth hung with ribbons and paper roses gone stiff with frost, a trestle with a cloth on it for an altar, two candles, a brass bowl for the fee, and a board: MARRIAGES PERFORMED. NO BANNS. NO QUESTIONS. ONE SHILLING. The parson is a little red man in a cassock with a scarf over it, who smells of gin and has a cold.".
  Observe chapel_again at chapel when visitedBefore(chapel) "The Ice Chapel: ribbons, paper roses, the brass bowl for the shilling.".
  Person doody "Parson Doody" at chapel {
    Role "an unbeneficed parson who marries anyone for a shilling". Ancestry human. Calling cleric. Level 1. Peaceable. Pronouns he. Manner jovial.
    Greets "'Marrying?' says Parson Doody, and sneezes. 'A shilling. No banns, no questions, no waiting, and landed at the Landing like any honest bargain.' He wipes his nose. 'Or unlanded, if you'd rather. Very popular, unlanded.'".
    Greets again "Parson Doody sneezes at you, cheerfully.".
  }
  Kind grigg_register_kind "the register of the last Frost Fair" is gear worth 0 weighing 1 described "A little fat book, water-stained, the register of the Ice Chapel of the last Frost Fair, thirty-one winters ago, kept by Parson Doody's predecessor, Parson Grigg: a hundred and forty marriages in eleven days, many of them on the last night.".
  Item old_register "the register of the last Frost Fair" is grigg_register_kind at chapel owned by doody.
  Relation registerLent(group).
  Topic doody_register with doody "Ask Parson Doody whether anyone kept a register at the last Frost Fair" when true once {
    Says "'Old Grigg did.' He sneezes. 'I've his book. Bought it off his widow for the look of the thing.' He fishes it out from under the altar-cloth. 'A hundred and forty in eleven days, and fifty on the last night, when everyone knew the ice was going. None of 'em landed. The ice went out at midnight and took the Court's tent with it.' He chuckles. 'Half the respectable marriages in Pellam would be bigamy if any of the last night had been landed. You can look at it for a shilling. Or for nothing, if you're of the cloth.'".
    On discuss { Assert knows(actor, register_known). }
  }
  Discovery register_known "Parson Doody keeps the register of the Ice Chapel of the last Frost Fair, thirty-one winters ago: fifty marriages on its last night, none of them landed, because the ice went out at midnight.".
  Action borrow_register(actor: group, site: place) "Pay Parson Doody a shilling to borrow the old register" {
    Requires able(actor) and company(actor) and at(actor, site) and at(doody, site) and knows(actor, register_known) and quantity(actor, gold) >= 1 and not registerLent(actor).
    Time 1 minute.
    On success { Decrease quantity(actor, gold) by 1. Increase quantity(doody, gold) by 1. Assert registerLent(actor). Assert lends(doody, old_register, actor). }
    Result "A shilling in the brass bowl. 'Bring it back,' says Doody, sneezing. 'It's a historical document.'".
  }
  Action cloth_register(actor: group, site: place) "Ask Parson Doody, as one of the cloth, to lend you the old register" {
    Requires able(actor) and company(actor) and at(actor, site) and at(doody, site) and knows(actor, register_known) and craft(actor, craft_faith) and not registerLent(actor).
    Time 1 minute.
    On success { Assert registerLent(actor). Assert lends(doody, old_register, actor). }
    Result "'Brother,' says Doody, or 'Sister,' and wipes his nose, and gives it you. 'The cloth must stick together. Nobody else will.'".
  }
  Action read_register(actor: group, reader: member, site: place) "Read the register of the last Frost Fair" {
    Requires able(actor) and at(actor, site) and memberOf(reader, actor) and ownedItem(old_register, reader) and not benighted(actor) and not knows(actor, gosling_wed).
    Time 1.
    On success { Assert knows(actor, gosling_wed). }
    Result "Old Grigg's hand gets worse as the Fair goes on, and on the last night it is very bad indeed. Fifty marriages between dusk and midnight. The forty-first: Hamnet Gosling, nineteen, apprentice to the Wool Exchange, and Isabel Ashby, nineteen, of the Frozen Lamb. Both have signed. He has drawn a little skate beside his name. Under the last entry Grigg has written, very large: ICE GOING. GOD SAVE US. NOT LANDED.".
  }
  Discovery gosling_wed "In the register of the last Frost Fair: Hamnet Gosling and Isabel Ashby of the Frozen Lamb were married at the Ice Chapel on its last night, thirty-one winters ago; the ice went out at midnight, and it was never landed.".
  Topic gosling_shown with gosling "Show the alderman his name in the register of the last Frost Fair" when knows(actor, gosling_wed) and not goslingKnows(gosling) once {
    Says "He looks at the page for a long time, at the little skate. 'She drew that,' he says. 'Bel. I couldn't draw.' He shuts the book. 'Not landed,' he says. 'Not anything. A boy and a girl on the ice for one night, and then the river.' He looks up at you, and he looks nineteen and fifty at once. 'I let it go out with the river. I let her think I'd let it go. And I went home and was respectable for thirty-one years.' He stands up. 'Does she know you've seen this?'".
    On discuss { Assert goslingKnows(gosling). Assert goslingStirred(gosling). }
  }
  Topic bel_told with bel "Tell Bel Ashby that Hamnet Gosling has read the register of the last Frost Fair, and his name in it" when knows(actor, gosling_wed) and goslingKnows(gosling) and not belTold(bel) once {
    Says "Bel puts down the jug she was holding. She does not say anything for a long time. Then: 'And what did he say?' You tell her. She laughs, once, without any breath in it. 'Thirty-one years,' she says, 'and he's marrying Harker's girl on Saturday on my ice.' She wipes her hands on her apron, slowly, finger by finger. 'If he wants to say something to me,' says Bel Ashby, 'he knows where the Lamb is. He's sat at the end of my bar every night of this ice not saying it.'".
    On discuss { Assert belTold(bel). }
  }
  // They say it, at the Lamb, that night: the alderman will marry Bel at noon instead.
  Rule gosling_speaks at lamb when belTold(bel) and goslingKnows(gosling) and at(gosling, lamb) and at(bel, lamb) and not goslingWedsBel(gosling) and not weddingDone(lisk)
    says "At the end of the Frozen Lamb's bar Alderman Gosling stands up, and knocks his hot gin over, and says in a loud voice that shakes, to Bel Ashby and the whole tent: 'Isabel. I was married to you once for four hours on this river, and I have been sorry every day since that I let it go out. I will not be married to anybody else on it.' Nobody in the Lamb breathes. Bel looks at him across the bar, and says, 'Noon, then, Hamnet. Doody's. And mind you're sober.' The Lamb goes up like a bonfire." {
    Assert goslingWedsBel(gosling). Assert witnessFree(gosling). }

  // ── Thessaly Harker, who is Mr. Icicle ────────────────────────────────────────────────────────────────────────────
  Person thessaly "Thessaly Harker" at harker_parlour {
    Role "the factor's daughter, pale and sharp, in grey silk" when not thessalyWedsNoll(thessaly).
    Role "a printer's wife, with ink on her fingers" when thessalyWedsNoll(thessaly).
    Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "Thessaly Harker looks at you as if she were going to write you down later. 'You're new,' she says. 'Everybody new in Pellam comes to see my father. Do sit down. I'll watch.'".
    Greets again "Thessaly Harker nods to you, and watches.".
  }
  Rule thessaly_home when hour(clock) >= 8 and hour(clock) < 16 and not weddingOn() and not thessalyWedsNoll(thessaly) and not thessalyLocked(thessaly) and not at(thessaly, harker_parlour) { Assert at(thessaly, harker_parlour). }
  Rule thessaly_skates when dusk() and not thessalyLocked(thessaly) and not thessalyWedsNoll(thessaly) and not iceGone() and not at(thessaly, flashes) { Assert at(thessaly, flashes). }
  Rule thessaly_supper when hour(clock) >= 18 and hour(clock) < 22 and not thessalyWedsNoll(thessaly) and not at(thessaly, harker_parlour) { Assert at(thessaly, harker_parlour). }
  Rule thessaly_press when hour(clock) >= 22 and not thessalyLocked(thessaly) and not iceGone() and not at(thessaly, printing) { Assert at(thessaly, printing). }
  Rule thessaly_bed when hour(clock) < 8 and not thessalyWedsNoll(thessaly) and not at(thessaly, limbo) { Assert at(thessaly, limbo). }
  Rule thessaly_locked_in when thessalyLocked(thessaly) and not weddingOn() and not at(thessaly, harker_parlour) { Assert at(thessaly, harker_parlour). }
  Rule thessaly_with_noll when thessalyWedsNoll(thessaly) and not at(thessaly, printing) and not landingAt(lisk) { Assert at(thessaly, printing). }
  Relation thessalyLocked(group). Relation thessalyBetrayed(group). Relation thessalyAlly(group). Relation thessalyKnowsNoll(group).
  Observe icicle_seen at printing when at(thessaly, printing) and hour(clock) >= 22 and not knows(party, thessaly_icicle) "The booth flap moves, and a woman in a hooded cloak comes in out of the dark without a word, and slides a folded paper under the ink-slab where it is warm, and a shilling on top of it. Noll does not look round from the press. He goes red to the ears. The hood comes back for a moment as she turns to go, and it is Thessaly Harker." teaches thessaly_icicle.
  Discovery thessaly_icicle "Mr. Icicle, who writes the Frost Gazette and asks whether a hat is the same thing as a head, is Thessaly Harker, Master Harker's daughter.".
  Observe inky_fingers at harker_parlour when at(thessaly, harker_parlour) and capable(party, insight) and not knows(party, thessaly_icicle) and not knows(party, thessaly_inky) "Thessaly Harker has ink on the side of her second finger, printer's ink, black, that has not quite come off with scrubbing; and on the table by her chair, folded small, this morning's Frost Gazette." teaches thessaly_inky.
  Discovery thessaly_inky "Thessaly Harker has printer's ink on her fingers, and this morning's Frost Gazette by her chair.".
  Topic thessaly_wedding with thessaly "Ask Thessaly about her wedding" when true once {
    Says "'My father's selling me to the bench.' She says it pleasantly. 'Not the worst bargain he's made. Hamnet is kind and writes bad verse and will never notice anything I do.' She turns her cup. 'He needs an alderman beside the Reeve at the Landing, to say the city witnesses it. A son-in-law is so much more reliable than a friend.' She looks at you. 'You're thinking I should mind. I'm thinking whether there's anything I'd like better. There isn't, yet.'".
    On discuss { Assert knows(actor, wedding_bargain). }
  }
  Discovery wedding_bargain "Harker is marrying his daughter to Alderman Gosling so that the city's witness at the Landing, beside the Reeve, will be his son-in-law.".
  // At supper, watching the Squire over her glass the whole meal, she has seen what her father has not.
  Relation thessalySees(group).
  Topic thessaly_squire with thessaly "Ask Thessaly Harker, after supper, what she was watching" when supped(actor) and posedSquire(actor) and not thessalySees(thessaly) and not thessalyBetrayed(thessaly) once {
    Says "'You.' She says it pleasantly, low, while her father is at the sideboard. 'You're no more a squire of anywhere than I'm a bishop. You held your fork like a carter and you looked at the silver like a pawnbroker.' She sips. 'I don't care. Rob him if you can; he'll survive it.' She looks at her father's back. 'But if you get into his books, I want to know what's in them. I've wanted to know for nine years.'".
    On discuss { Assert thessalySees(thessaly). }
  }
  Topic thessaly_bargain with thessaly "Tell Thessaly that if you get into her father's books, she'll know what is in them" when thessalySees(thessaly) and not thessalyAlly(thessaly) and not thessalyBetrayed(thessaly) once {
    Says "'On the ice that's only words.' She takes a small brass key off a ribbon at her throat and puts it beside your plate, under the edge of your napkin. 'His desk, in the counting-house. He gave it me when I was twelve to keep his sermons in. He's forgotten.' She smiles at her father as he turns round. 'More goose, Father? The Squire is famished.'".
    On discuss { Assert thessalyAlly(thessaly). }
  }
  Topic thessaly_accused with thessaly "Ask Thessaly Harker whether she is Mr. Icicle" when (knows(actor, thessaly_icicle) or knows(actor, thessaly_inky)) and not thessalyAlly(thessaly) and not thessalyBetrayed(thessaly) once {
    Says "She does not pretend. She looks at the door, to see if it is shut. 'Yes.' Quite calm. 'Since the first week of the ice. Somebody in this city ought to say something, and nobody can say anything that is true, on the ice or off it, without it costing them, except a person who does not exist.' She looks at you steadily. 'If my father knew, I would be locked in until the wedding and married with a hand on my collar. So now you have something to sell him. Most people in Pellam would.'".
    On discuss { Assert knows(actor, thessaly_icicle). Assert icicleAsked(thessaly). }
  }
  Relation icicleAsked(group).
  Topic thessaly_kept with thessaly "Tell Thessaly you'll not sell her" when icicleAsked(thessaly) and not thessalyAlly(thessaly) and not thessalyBetrayed(thessaly) once {
    Says "'On the ice, that's only words.' She smiles, very slightly. 'But I'll believe it till you prove otherwise, which is more than I do for most.' She takes something off a ribbon round her neck: a small brass key. 'My father's desk, in the counting-house. He gave it me when I was twelve to keep his sermons in. He's forgotten.' She puts it in your hand. 'Whatever you are, you're not a squire. Find out what I can't.'".
    On discuss { Assert thessalyAlly(thessaly). }
  }
  Rule key_comes when thessalyAlly(thessaly) and at(desk_key, limbo) and at(party, ?p) { Retract at(desk_key, limbo). Assert at(desk_key, ?p). }
  Topic sell_thessaly with harker "Tell Master Harker who writes the Frost Gazette" when knows(actor, thessaly_icicle) and not thessalyBetrayed(thessaly) and not thessalyAlly(thessaly) once {
    Says "Harker is quiet while the clock on the stair strikes. 'My daughter,' he says. He does not ask how you know. He gets up and goes to the door and speaks to someone outside, and comes back, and sits down. 'Thank you,' he says. 'A father should know these things.' Somewhere in the house a door is locked. He inclines his head to you a full inch, the most you have seen. 'I shall not forget it.'".
    On discuss { Assert thessalyBetrayed(thessaly). Assert thessalyLocked(thessaly). Increase conviction(harker, squire_claim) by 1. }
  }
  Topic thessaly_noll with thessaly "Tell Thessaly that the printer on the ice knows who Mr. Icicle is, and sets every word for her sake" when knows(actor, noll_loves) and thessalyAlly(thessaly) and not thessalyKnowsNoll(thessaly) once {
    Says "She goes very still. 'Noll,' she says. 'Noll Brisket.' She says it again as if she were trying the weight of it. 'He goes red when I come in. I thought it was the brazier.' She looks at her inky finger. 'He has never once in eleven nights asked me who I am.' She is quiet. 'Nobody,' says Thessaly Harker, 'has ever been so tactful with me in my life.'".
    On discuss { Assert thessalyKnowsNoll(thessaly). }
  }
  // What she can do that nobody else can: put the truth on the ice by noon, in a voice that does not exist.
  Relation gazetteGiven(place).
  Action give_gazette(actor: group, site: place) "Give Thessaly her father's book, to print in tomorrow's Frost Gazette" {
    Requires able(actor) and company(actor) and at(actor, site) and at(thessaly, site) and thessalyAlly(thessaly) and (carries(actor, ledger) or carries(actor, bondbook))
      and not gazetteGiven(lisk) and not iceGone().
    Time 2.
    On success { Assert gazetteGiven(lisk). Assert harkerWary(harker). }
    Result "She reads it standing up, by the brazier, to the end, without a word; then she sits down at Noll's slab and writes for an hour without stopping, and gives you the book back. 'Mr. Icicle,' she says, 'has a column tomorrow.' She looks at the copy. 'My father will know whose hand it is the moment he reads it. Nobody else in Pellam writes a Q like that.' She folds it under the ink-slab. 'Let him.'".
  }
  Rule gazette_out when gazetteGiven(lisk) and hour(clock) == 12 and not gazettePrinted(lisk) { Assert gazettePrinted(lisk). Assert happened(ev_gazette). }
  Entity ev_gazette: fact "the Gazette's column".
  Rule gazette_heard when happened(ev_gazette) and inPellam() and not heardNews(ev_gazette) says "By noon the Frost Gazette is on every booth on the ice, and there is only one column in it anybody reads: MR. ICICLE ASKS WHERE THE FARM IN THE HILLS IS. Under it, set very plain, nine years of Pellam hirings by name, with what was paid for them at Gallowmoor, and which of them died there. The watermen read it aloud in the Hall. Somebody has cut the Hiring Ring's rope through at every stake." { Assert heardNews(ev_gazette). }
  Observe gazette_column at printing when gazettePrinted(lisk) and not iceGone() "Pinned by the press, the Frost Gazette with Mr. Icicle's column: WHERE IS THE FARM IN THE HILLS?".
  // At the press that night she asks him; on the last morning, before her father's wedding, they are married at the
  // Ice Chapel for a shilling, by Doody, with no banns, which is what the Ice Chapel is for.
  Rule thessaly_asks at printing when thessalyKnowsNoll(thessaly) and at(thessaly, printing) and at(noll, printing) and not thessalyAsked(thessaly)
    says "At the press, near midnight, Thessaly Harker puts back her hood in front of Noll Brisket for the first time, and says, 'You know who I am.' Noll stops the press. 'Yes,' he says. 'I'm marrying Hamnet Gosling on Saturday,' says Thessaly. 'Unless I'm married already.' Noll does not say anything at all. Then he wipes his hands on his apron, which makes them worse, and holds one out." {
    Assert thessalyAsked(thessaly). }
  Relation thessalyAsked(group).
  Rule thessaly_marries when thessalyAsked(thessaly) and thirdDay() and hour(clock) >= 11 and not thessalyWedsNoll(thessaly) and not weddingDone(lisk)
    {
    Assert thessalyWedsNoll(thessaly). Assert witnessFree(gosling). Assert weddingBroken(lisk). Assert happened(ev_thessaly_marries). }
  Entity ev_thessaly_marries: fact "thessaly marries".
  Rule thessaly_marries_heard when happened(ev_thessaly_marries) and inPellam() and not heardNews(ev_thessaly_marries) says "At eleven on the last morning word goes up Freezeland Street like a shout: Thessaly Harker has been married at the Ice Chapel, for a shilling, by Parson Doody, without banns, to Noll Brisket the printer, with ink on both of them, and two watermen for witnesses; and Master Harker has heard." { Assert heardNews(ev_thessaly_marries). }

  // ── Noon on the last day ──────────────────────────────────────────────────────────────────────────────────────────
  Rule wedding_gathers when weddingOn() and not weddingDone(lisk) and not at(gosling, chapel) { Assert at(gosling, chapel). Assert at(harker, chapel). }
  Rule wedding_thessaly_comes when weddingOn() and not weddingDone(lisk) and not thessalyWedsNoll(thessaly) and not at(thessaly, chapel) { Assert at(thessaly, chapel). }
  Observe wedding_scene at chapel when weddingOn() and not weddingDone(lisk) "The Ice Chapel is packed to the ribbons, and half the Fair is outside the flap. Master Harker in a new black coat; the alderman in a blue one, very red; the bride in grey silk with snowdrops; Parson Doody, sober, which nobody has seen before, sneezing.".
  Rule wedding_bel when weddingOn() and goslingWedsBel(gosling) and not weddingDone(lisk)
    {
    Assert weddingDone(lisk). Assert witnessFree(gosling). Assert weddingBroken(lisk). Assert happened(ev_wedding_bel). }
  Entity ev_wedding_bel: fact "wedding bel".
  Rule wedding_bel_heard when happened(ev_wedding_bel) and inPellam() and not heardNews(ev_wedding_bel) says "At noon, at the Ice Chapel, Alderman Hamnet Gosling marries Isabel Ashby of the Frozen Lamb, for the second time, for a shilling, in front of half the Fair and Master Harker, who leaves before the end with a face like a shut door. Thessaly Harker, in grey silk, is the first to kiss the bride. Afterwards there is hot gin for anyone in Pellam who wants it, which is everyone." { Assert heardNews(ev_wedding_bel). }
  Rule wedding_noll when weddingOn() and thessalyWedsNoll(thessaly) and not goslingWedsBel(gosling) and not weddingDone(lisk)
    {
    Assert weddingDone(lisk). Assert witnessFree(gosling). Assert happened(ev_wedding_noll). }
  Entity ev_wedding_noll: fact "wedding noll".
  Rule wedding_noll_heard when happened(ev_wedding_noll) and inPellam() and not heardNews(ev_wedding_noll) says "At noon there is no wedding at the Ice Chapel, because the bride is married already, since eleven, to a printer. Alderman Gosling stands in the doorway of the Ice Chapel in his blue coat looking, everyone agrees afterwards, as if a great weight had been lifted off him and he did not know where to put his hands." { Assert heardNews(ev_wedding_noll). }
  Rule wedding_bear when weddingOn() and bearAtWedding(absolute) and not goslingWedsBel(gosling) and not thessalyWedsNoll(thessaly) and not weddingDone(lisk)
    {
    Assert weddingDone(lisk). Assert witnessFree(gosling). Assert weddingBroken(lisk). Assert happened(ev_wedding_bear). }
  Entity ev_wedding_bear: fact "wedding bear".
  Rule wedding_bear_heard when happened(ev_wedding_bear) and inPellam() and not heardNews(ev_wedding_bear) says "At noon, as Parson Doody opens his book, Hester Mabb's bear puts his head in through the flap of the Ice Chapel, attracted by the wedding-cake, and the wedding is over in a moment: the alderman under the altar, Master Harker out through the back of the booth with the canvas round his shoulders, Doody up on a bench, and the bride sitting on the cake-table laughing until she cries. It is put off, Harker says afterwards, white, until the spring." { Assert heardNews(ev_wedding_bear). }
  Rule wedding_plain when weddingOn() and hour(clock) == 12 and not goslingWedsBel(gosling) and not thessalyWedsNoll(thessaly) and not bearAtWedding(absolute) and not weddingDone(lisk)
    {
    Assert weddingDone(lisk). Assert goslingHarker(gosling). Assert happened(ev_wedding_plain). }
  Entity ev_wedding_plain: fact "wedding plain".
  Rule wedding_plain_heard when happened(ev_wedding_plain) and inPellam() and not heardNews(ev_wedding_plain) says "At noon, at the Ice Chapel, Parson Doody marries Thessaly Harker to Alderman Hamnet Gosling for a shilling, sober, in front of half the Fair. The bride says her part in a clear dry voice as if she were reading a bill. The alderman says his as if someone had died. Master Harker kisses his daughter, and shakes his son-in-law's hand, and smiles all through the wedding-breakfast at the Frozen Lamb, where Bel Ashby serves it herself and does not look at anyone." { Assert heardNews(ev_wedding_plain). }
  // A squire believed is at the wedding, and is expected to give.
  Relation presentGiven(group). Relation presentMissed(group).
  Action give_share_present(actor: group, site: place) "Give the bride, as the Squire of Hawsfold's wedding present, a share in the Perpetual Frost Company" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, chapel) and weddingOn() and invited(actor) and carries(actor, share) and not presentGiven(actor) and not frostCrashed(lisk).
    Time 1 minute.
    On success { Assert presentGiven(actor). Increase conviction(harker, squire_claim) by 1. }
    Result "Master Harker sees the engraving, and the smiling sun, and his face does something complicated. 'A share,' he says. 'In Quarle's Company. How very forward-looking.' He has two hundred of them himself. He shakes his head at you as at a fellow investor, almost fondly.".
  }
  Action give_cream_present(actor: group, site: place) "Give the wedding Mr. Quarle's frost-cream, as the Squire of Hawsfold's present" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, chapel) and weddingOn() and invited(actor) and quarleCream(quarle) and not presentGiven(actor).
    Time 1 minute.
    On success { Assert presentGiven(actor). Increase conviction(harker, squire_claim) by 1. }
    Result "Mr. Quarle comes in through the flap with a pewter pot packed in salt and ice, and a basket of spoons, and the whole wedding eats frost-cream on the ice in the middle of the ceremony, and Parson Doody has three spoonfuls and forgets the vows. Everyone talks of the Squire of Hawsfold's present for a week.".
  }
  Rule present_missed at chapel when weddingDone(lisk) and invited(party) and at(party, chapel) and not presentGiven(party) and not presentMissed(party) and not squireExposed(party)
    says "Master Harker looks, once, during the breakfast, at the place where the Squire of Hawsfold's wedding present ought to be, and sees nothing there, and looks at you. A squire, his face says, gives a present." {
    Assert presentMissed(party). Decrease conviction(harker, squire_claim) by 1. }
  Rule squire_absent when weddingDone(lisk) and invited(party) and not at(party, chapel) and not squireExposed(party) and not squireMissed(party) {
    Assert squireMissed(party). Assert happened(ev_squire_missed). }
  Relation squireMissed(group).
  Entity ev_squire_missed: fact "the Squire missed the wedding".
  Rule squire_missed_heard when happened(ev_squire_missed) and inPellam() and not heardNews(ev_squire_missed) says "They are saying on the ice that the Squire of Hawsfold's chair at the Harker wedding stood empty right through it, with a card on it, and that Master Harker kept looking at it." { Assert heardNews(ev_squire_missed). }
  // Brought to the wedding, the bear comes in.
  Action bear_to_wedding(actor: group, site: place) "Walk Absolute up Freezeland Street on his chain to the Ice Chapel, with Hester" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bear_stake) and bearCalmed(absolute) and at(hester, bear_stake) and thirdDay() and hour(clock) >= 11 and hour(clock) < 12 and not bearAtWedding(absolute).
    Time 2.
    On success { Assert bearAtWedding(absolute). Assert at(absolute, freezeland_low). Assert at(hester, freezeland_low). Assert at(actor, freezeland_low). }
    Result "Hester says it is the worst idea she has ever heard, and comes. Absolute walks up Freezeland Street between you on his chain, rolling, in his muzzle, sniffing at the gingerbread, while the Fair parts in front of him like water; and outside the Ice Chapel, where the wedding-cake is on a trestle under the ribbons, he stops, and lifts his nose, and stands up.".
  }
}

data/adventures/liberty-of-the-ice/harke:
Module pellam "The Liberty of the Ice" {
  // ── Master Josias Harker ──────────────────────────────────────────────────────────────────────────────────────────
  // Wool-factor and hiring-master, churchwarden of Saint Evenhand's. He never lies outright and never shakes on
  // anything himself: the hired shake on his bargains; he only accepts them. He hires the poor of the north country
  // for "a year's place on a farm in the hills", and sells their indentures, landed and good in any court, to the lead
  // mines at Gallowmoor in the south. This year everything he hires is ice-bargained, and no statute of the city on
  // servants can touch it.
  Person harker "Master Josias Harker" at counting_house {
    Role "a wool-factor in a black coat with a fur collar, and a churchwarden's ring". Ancestry human. Peaceable. Pronouns he. Manner proud.
    Greets "Master Harker inclines his head a quarter of an inch, which is what he has decided you are worth until he knows better. 'Good day to you,' he says. 'I am busy, but I am never too busy to be civil.'".
    Greets again "Master Harker inclines his head the same quarter of an inch.".
  }
  Initially Set quantity(harker, gold) to 160.
  Rule harker_ring when hiringOn() and not at(harker, hiring_ring) and not harkerGone(harker) { Assert at(harker, hiring_ring). }
  Rule harker_counting when hour(clock) >= 12 and hour(clock) < 18 and not hiringOn() and not landingAt(lisk) and not weddingOn() and not harkerGone(harker) and not at(harker, counting_house) { Assert at(harker, counting_house). }
  Rule harker_morning when hour(clock) >= 8 and hour(clock) < 12 and not hiringOn() and not weddingOn() and not harkerGone(harker) and not at(harker, counting_house) { Assert at(harker, counting_house). }
  Rule harker_supper when hour(clock) >= 18 and hour(clock) < 23 and not harkerGone(harker) and not at(harker, harker_parlour) and not showingStock(harker) { Assert at(harker, harker_parlour). }
  Rule harker_bed when (hour(clock) >= 23 or hour(clock) < 8) and not harkerGone(harker) and not at(harker, limbo) and not showingStock(harker) { Assert at(harker, limbo). }
  Relation harkerGone(group). Relation showingStock(group).
  Observe counting_scene at counting_house when not visitedBefore(counting_house) "Harker's counting-house: a long room with a good fire, high desks, a wall of pigeonholes stuffed with wool-notes, a pair of great brass scales with the Saint's mark on them, and a text in black-letter over the hearth: THE LORD WEIGHETH THE SPIRITS. A roll-top desk, locked, by the window. A clerk at a high stool, writing.".
  Observe counting_again at counting_house when visitedBefore(counting_house) "Harker's counting-house: the fire, the pigeonholes, the brass scales, THE LORD WEIGHETH THE SPIRITS, the locked roll-top desk.".
  Observe parlour_scene at harker_parlour when true "Harker's parlour: Turkey carpet, a harpsichord nobody plays, a portrait of the late Mrs. Harker looking as if she had been told to sit still, and a long table laid with more silver than food.".
  Topic harker_hiring with harker "Ask Master Harker about the hiring" when true once {
    Says "'A Christian service.' He says it gently. 'The north country is poor, and the fells are cruel, and young people come down to the hiring with nothing but a tuft of wool in their hats. I give them a year's place on a farm in the hills: good food, a roof, wages at the year's end.' He turns his ring. 'They shake on it of their own free will. I have never in my life put out my hand to a servant. I only accept theirs.' He smiles. 'You may ask anyone.'".
    On discuss { Assert knows(actor, harker_farm). }
  }
  Discovery harker_farm "Master Harker says he hires the north country's poor for a year's place on a farm in the hills. He says he never puts out his hand to a servant, only accepts theirs.".
  Topic harker_wool with harker "Ask Master Harker about the wool trade, with the roads shut" when true once {
    Says "'Speculative.' He likes the word. 'Every factor on the Exchange is buying fleece still on the sheep, at this winter's price, for delivery at the shearing. When the roads open the price will double. I buy what I am offered, from men I can trust, at a fair price, by the head, with a tally.' He looks at you a moment longer than he needs to. 'I am always glad to meet men I can trust.'".
    On discuss { Assert knows(actor, harker_buys). }
  }
  Discovery harker_buys "Master Harker buys fleece still on the sheep, by the head, with a tally, from anyone he trusts, for delivery at the shearing.".

  // His one private thing: his wife's portrait, and what he tells a guest late, when he has drunk a little, about the
  // hiring at which he was himself hired.
  Topic harker_portrait with harker "Ask Master Harker, late, about the portrait over the fireplace" when supped(actor) and hour(clock) >= 20 and at(harker, harker_parlour) once {
    Says "He looks at it until the coal in the grate settles. 'Margaret,' he says. 'She thought me hard.' He pours himself a little more. 'I was hired at the Pellam hiring when I was nine years old. We were Swale Head people, under the scar, and my father had a note out against the wool. He stood me in the Ring with a twist of straw in my cap, and a man put out his palm, and I shook, because my father told me to, and I went to a farm in the hills that was a dye-works in Ossett, and I was there eleven years.' He drinks. 'I learned there that a hand is all a poor man has to sell. So I buy it, at a fair price, and I never lie about the price.' He puts the glass down very precisely. 'Margaret thought me hard,' he says again. 'She was not hired at nine.'".
    On discuss { Assert knows(actor, harker_hired). }
  }
  Discovery harker_hired "Josias Harker was himself hired at the Pellam hiring at nine years old, out of Swale Head, for a farm in the hills that was a dye-works, and served there eleven years. He says a hand is all a poor man has to sell.".
  // ── Silas Kemble, his clerk ───────────────────────────────────────────────────────────────────────────────────────
  Person kemble "Silas Kemble" at counting_house {
    Role "a clerk, thin, with a red nose and a quill behind his ear". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Greets "Silas Kemble does not stop writing. 'Master Harker is engaged. I am engaged. Everyone is engaged.' He blots. 'What do you want?'".
    Greets again "Kemble glances up, and down, and goes on writing.".
  }
  // Kemble tells his master everything he hears, and drinks at the Lamb, where he hears a great deal.
  Initially Assert serves(kemble, harker). Initially Assert tattles(kemble).
  Rule kemble_works when hour(clock) >= 8 and hour(clock) < 18 and not hiringOn() and not landingAt(lisk) and not at(kemble, counting_house) { Assert at(kemble, counting_house). }
  Rule kemble_ring when hiringOn() and not at(kemble, hiring_ring) { Assert at(kemble, hiring_ring). }
  Rule kemble_drinks when hour(clock) >= 19 and hour(clock) < 23 and not iceGone() and not at(kemble, lamb) { Assert at(kemble, lamb). }
  Rule kemble_home when (hour(clock) >= 23 or hour(clock) < 8) and not at(kemble, limbo) { Assert at(kemble, limbo). }
  Relation tattles(group).
  Topic kemble_drowned with kemble "Ask Kemble about the drowned" when knows(actor, drowned_hats) once {
    Says "Kemble puts his pen down for the first time. 'Drowned.' He says it like a sum that will not come out. 'The river has very particular tastes, I find. Only Master Harker's hired. Only the strong ones. Only the ones who stood near the edge at the hiring and looked at the Reach.' He picks up his pen again. 'Master Harker pays five coin a head for word of anyone who has been drowned and is walking about. It is a Christian concern. The bereaved must be comforted.'".
    On discuss { Assert knows(actor, kemble_pays). }
  }
  Discovery kemble_pays "Silas Kemble pays five coin a head, for Master Harker, for word of any of the drowned who are walking about.".

  // ── The roll-top desk, and the hiring ledger ──────────────────────────────────────────────────────────────────────
  Thing harker_desk "the roll-top desk" at counting_house {
    Holds.
    State locked closed "A roll-top desk by the window, its lid down and locked.".
    State open "The roll-top desk stands open: pigeonholes, a pen-tray, a ledger bound in black.".
    Change pick "Pick the lock of the roll-top desk" from locked to open needing lockwork.
    Change key "Open the roll-top desk with Thessaly's key" from locked to open needing desk_key.
  }
  Initially Assert state(harker_desk, locked).
  Kind ledger_kind "Harker's hiring ledger" is gear worth 0 weighing 1 described "A tall ledger bound in black calf, in Kemble's hand: every hiring at Pellam these nine years, name by name, and against every name the same two entries.".
  Item ledger "Harker's hiring ledger" is ledger_kind in harker_desk owned by harker.
  Kind desk_key_kind "a small brass key" is gear worth 0 weighing 0 described "A small brass key on a loop of black ribbon, warm from being worn.".
  Item desk_key "Thessaly's brass key" is desk_key_kind at limbo.
  // Someone in the counting-house sees a company open the desk.
  Rule desk_seen when state(harker_desk, open) and at(party, counting_house) and (perceives(kemble, party) or perceives(harker, party)) and not deskSeen(party) says "Silas Kemble looks up from his stool, and sees the desk open, and you at it, and puts his pen down very slowly. Then he gets up and goes out, without his hat, toward wherever Master Harker is." {
    Assert deskSeen(party). Assert harkerWary(harker). Assert squireExposed(party). }
  Relation deskSeen(group).
  Rule desk_shuts when hour(clock) == 8 and state(harker_desk, open) { Assert state(harker_desk, locked). }
  Action read_ledger(actor: group, reader: member, site: place) "Read Harker's hiring ledger" {
    Requires able(actor) and at(actor, site) and memberOf(reader, actor) and (ownedItem(ledger, reader) or reaches(actor, ledger)) and not benighted(actor) and not knows(actor, ledger_read).
    Time 1.
    On success { Assert knows(actor, ledger_read). Assert knows(actor, hired_sold). }
    Result "Nine years of Pellam hirings in Kemble's neat hand. Name, age, token (crook, pail, whip, mop), and then two columns. The first is headed PLACE, and under it, for every name, in the same hand: farm in the hills. The second is headed DISPOSED, and under it, for every name, in pencil: Gallowmoor, by Ossett's agent, eight coin. At the spring hiring of this year, the eleventh name is Richard Cobb, twenty, of Swale Head, token a crook. Gallowmoor, eight coin. Against three of the names, nine years back, someone has written in pencil, very small: dead.".
  }
  Discovery ledger_read "Harker's hiring ledger: nine years of hirings, every name entered 'farm in the hills' and then, in pencil, 'Gallowmoor, by Ossett's agent, eight coin'. Richard Cobb, called Dickon, of Swale Head, was the eleventh name at this year's spring hiring.".
  Discovery hired_sold "Master Harker does not send his hired to any farm in the hills. He sells their indentures, landed and good in any court, to Ossett's agent for the lead mines at Gallowmoor, at eight coin a head; some of them have died there.".

  // ── The Hiring Ring ───────────────────────────────────────────────────────────────────────────────────────────────
  // On the first day from ten to noon and the second from nine to eleven: young people from the snowbound north
  // country standing in a roped ring on the ice with a token of their trade in their hats, and Harker walking round it.
  Query hiringOn() means (firstDay() and hour(clock) >= 10 and hour(clock) < 12) or (secondDay() and hour(clock) >= 9 and hour(clock) < 11).
  Observe ring_scene at hiring_ring when hiringOn() "The Hiring Ring: a rope on stakes round a trodden circle of ice, and inside it twenty or thirty young people from the north country, standing very still in the cold with a token in their hats for what they can do: a tuft of wool for a shepherd, a whipcord for a carter, a mop-head, a twist of straw. Their breath goes up. Master Harker walks round inside the rope in his fur collar with his clerk behind him, and stops in front of one, and talks a little, kindly, and puts out not his hand but his open palm, and waits; and the one in front of him shakes it, and Kemble writes. A girl with a milk-pail in her hat, who cannot be more than fifteen, has just shaken.".
  Observe ring_empty at hiring_ring when not hiringOn() and not iceGone() "The Hiring Ring is empty: a rope on stakes round a trodden circle of ice, and in the middle a mop-head somebody dropped, frozen to the ice.".
  Person hired "Harker's hired" at limbo {
    Role "a line of young people from the north country, hired at the Ring". Ancestry human. Numbers 6. Peaceable. Pronouns they.
  }
  Person tansy "Tansy Hobb" at limbo {
    Role "a dairymaid from Swale Head, fifteen, with a milk-pail on a string" when not tansyFree(tansy).
    Role "a dairymaid from Swale Head, her own again" when tansyFree(tansy).
    Ancestry human. Peaceable. Pronouns she. Manner compassionate.
    Greets "Tansy Hobb looks at you the way she must look at a strange cow: carefully, and from a little way off. 'Are you hired too?'".
  }
  Relation tansyFree(group).
  Rule hired_at_ring when hiringOn() and not inBond(hired) and not at(hired, hiring_ring) { Assert at(hired, hiring_ring). Assert at(tansy, hiring_ring). }
  // At the end of each hiring Kemble walks the hired over the ice to the bondhouse, to be kept till the Landing.
  Relation inBond(group).
  Rule hired_walked when firstDay() and hour(clock) >= 12 and at(hired, hiring_ring) and not inBond(hired) {
    Assert inBond(hired). Assert at(hired, bond_floor). Assert at(tansy, bond_floor). Assert inBond(tansy). Assert happened(ev_hired_walked). }
  Entity ev_hired_walked: fact "hired walked".
  Rule hired_walked_heard when happened(ev_hired_walked) and inPellam() and not heardNews(ev_hired_walked) says "At noon the hiring ends. Kemble walks Harker's hired off the ice in a line, two by two, across to Hay Stairs and up onto the wharf and in at the door of the long blind warehouse with J. HARKER. WOOL painted on its gable, to be kept there, warm and fed, he tells anyone who asks, until the Landing." { Assert heardNews(ev_hired_walked). }
  Topic tansy_place with tansy "Ask Tansy Hobb where she is going" when true once {
    Says "'A farm in the hills.' She says it like a charm. 'A year's place, and good food, and wages at the year's end, and I can send them home.' She swallows. 'Mam said not to go to Harker. Mam said nobody comes back from Harker's. But Mam said that about the town, too, and I came back from the town.' She looks at her hands. 'I shook. It's done now. You can't unshake.'".
    On discuss { Assert knows(actor, tansy_hired). }
  }
  Discovery tansy_hired "Tansy Hobb, fifteen, a dairymaid from Swale Head, shook hands with Master Harker at the Hiring Ring for a year's place on a farm in the hills.".

  // ── Standing in the Ring: the way in that a plain person has ──────────────────────────────────────────────────────
  // Harker hires the dull gladly, and the strong. Shake his palm and you are his hired, walked into the bondhouse with
  // the rest at noon, and landed at the Landing for a year at Gallowmoor, unless something is done.
  Entity hire_bargain: bargain "a year's service, with Master Harker".
  Relation hiredHand(group). Relation squireExposed(group).
  Action stand_ring(actor: group, site: place) "Put a tuft of straw in your hat and stand in the Hiring Ring" {
    Grave "A hand shaken on the ice binds: shake Harker's palm and you are his hired for a year, to be landed with the rest.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hiring_ring) and hiringOn() and at(harker, hiring_ring)
      and not hiredHand(actor) and not posedSquire(actor) and not harkerWary(harker).
    Time 2.
    On success { Assert hiredHand(actor). Assert shook(actor, hire_bargain). Assert inBond(actor). }
    Result "You stand in the cold with the others with a twist of straw in your hat, and after a while Master Harker comes round to you in his fur collar and looks at you as a man looks at a horse at a price he likes. 'A strong back,' he says kindly. 'And an honest face. A year's place on a farm in the hills: good food, a roof, wages at the year's end.' He holds out his palm, open, and waits. You shake it. His hand is soft and very warm. 'Kemble,' he says, without looking round, and Kemble writes you down.".
  }
  Rule hired_hand_walked when hiredHand(party) and at(party, hiring_ring) and not hiringOn() and not inBondhouse(party) says "The hiring ends. Kemble walks you off the ice in the line with the rest, two by two, across to Hay Stairs, up onto the wharf, and in at the bondhouse door, and you hear the bar go down outside." {
    Assert inBondhouse(party). Assert at(party, bond_floor). Assert at(hired, bond_floor). Assert at(tansy, bond_floor). Assert inBond(hired). Assert inBond(tansy). }
  Relation inBondhouse(group).
  // A hand shaken in the Ring and walked away from is fetched: Harker's wharf men come for it, wherever in Pellam it
  // is, the same afternoon; except the Clink, within whose walls no man owes.
  Relation hiredFetched(group).
  Rule hired_fetched when hiredHand(party) and not inBondhouse(party) and not hiredFetched(party) and not hiringOn() and (firstDay() and hour(clock) >= 14 or secondDay() and hour(clock) >= 12)
    and inPellam() and not at(party, clink_yard) and not hiredOut(lisk) and not hiredFled(lisk) and not landingAt(lisk) and not iceGone()
    says "Two of Harker's wharf men find you, not unkindly, with Kemble behind them holding his book open at your name. 'You shook,' says Kemble. 'Everybody saw. A year's place.' One of them takes your arm. They walk you down to Hay Wharf and in at the bondhouse door among the others, and you hear the bar go down outside." {
    Assert hiredFetched(party). Assert inBondhouse(party). Assert at(party, bond_floor). Assert at(hired, bond_floor). Assert at(tansy, bond_floor). Assert inBond(hired). Assert inBond(tansy). }
  // At night on the bondhouse floor, Tansy Hobb sings to cows that are not there.
  Observe tansy_sings at bond_floor when inBondhouse(party) and dark() and not hiredOut(lisk) and not hiredFled(lisk) "In the dark at the far end of the straw somebody is singing, very low, the song a dairymaid sings to keep a cow standing at the milking: come up, Cushie, come up, my lady, it's only me. It is Tansy Hobb, with her milk-pail in her lap. Nobody tells her to stop.".
  Topic tansy_home with tansy "Ask Tansy Hobb about home" when inBond(tansy) once {
    Says "'Swale Head.' She brightens. 'Under the fell. We've the low farm, by the wash-dub. Three cows, and Gran's goat, which is a devil.' She counts on her fingers. 'Nell, and Moss, and Lady. Lady won't stand for anyone but me. She'll be kicking our Sam into the beck.' She laughs, and then stops. 'Gran said not to shake. She said there was a Swale Head lass once that never shook on anything in her life, and went to the town and did very well.' She looks at her hand. 'I don't know who that was.'".
    On discuss { Assert knows(actor, tansy_home_known). }
  }
  Discovery tansy_home_known "Tansy Hobb's people have the low farm at Swale Head, three cows and a goat; her grandmother told her of a Swale Head girl who never shook on anything and did well in the town.".

  // ── The bondhouse on Hay Wharf ────────────────────────────────────────────────────────────────────────────────────
  Observe wharf_scene at hay_wharf when not visitedBefore(hay_wharf) "Hay Wharf: a timber stage on piles, snowed over, with the river frozen solid round its legs; bales stacked under sailcloth; and the long blind warehouse with J. HARKER. WOOL on its gable and one door, studded, with a new lock.".
  Observe wharf_again at hay_wharf when visitedBefore(hay_wharf) "Hay Wharf: snowed bales, and Harker's bondhouse with its one studded door.".
  Thing bond_lock "the bondhouse lock" on bond_door {
    State locked blocking "The bondhouse door is locked: a new lock, big as a book. Kemble has the key.".
    State open "The bondhouse door stands unlocked.".
    Change pick "Pick the bondhouse lock" from locked to open needing lockwork.
  }
  Initially Assert state(bond_lock, locked).
  Initially Assert keyholder(kemble, bond_lock). Initially Assert keyholder(harker, bond_lock).
  Rule bond_relocks when hour(clock) == 7 and state(bond_lock, open) and not hiredFled(lisk) { Assert state(bond_lock, locked). }
  Thing river_bar "the bar on the river door" on river_door {
    State barred blocking "The river door in the bondhouse's back wall is barred on the inside with a baulk of oak in iron brackets, iced in.".
    State unbarred "The bar is off the river door, and the door stands a hand's breadth open on the ice.".
    Change lift "Break the iced bar out of its brackets and lift it off the river door" from barred to unbarred needing brawn at bond_floor.
  }
  Initially Assert state(river_bar, barred).
  Observe bond_floor_scene at bond_floor when not hiredFled(lisk) "The bondhouse floor: a long dim barn of a place smelling of wool and tallow, fleeces stacked to the beams down one side, and down the other, on straw, Harker's hired, sitting close together for the warmth with blankets round them. A brazier. A trestle by the door with a book on it and a pen. At the far end a low door in the river-wall, barred. A ladder goes up into a loft.".
  Observe bond_floor_empty at bond_floor when hiredFled(lisk) "The bondhouse floor: fleeces stacked to the beams, trodden straw, a cold brazier, and the river door standing open on the ice.".
  Observe bond_loft_scene at bond_loft when not dark() "The loft: fleeces, cobwebs, a little grey daylight through the tiles, and names. The beams are covered in names, cut with knives and nails and pins, year after year: initials and hearts and the names of villages, and crooks and pails scratched beside them.".
  Observe bond_loft_night at bond_loft when dark() "The loft at night: black, and close, and full of the sound of the people below breathing and somebody, somewhere, trying not to cry. When a lantern goes by on the wharf outside, the names on the beams come out for a moment in the slits of light between the tiles, and go.".
  Discovery beam_read "On a beam of the bondhouse loft, cut deep with a nail, among years of names: D. COBB SWALE HEAD. And under it, newer, cut by the same hand, deeper: GALLOWMOOR LEAD. THEY DONT COME BACK. I DID." { Found by searching bond_loft. }
  Kind bondbook_kind "Kemble's bond book" is gear worth 0 weighing 1 described "A thin book in Kemble's hand: this Fair's hirings, name, age and token, each with a little drawn hand beside it for shaken, and on the last page in pencil, not in Kemble's hand but in Harker's: All to Ossett's agent at the thaw. Gallowmoor.".
  Item bondbook "Kemble's bond book" is bondbook_kind at bond_floor owned by harker.
  Action read_bondbook(actor: group, reader: member, site: place) "Read Kemble's bond book" {
    Requires able(actor) and at(actor, site) and memberOf(reader, actor) and (ownedItem(bondbook, reader) or reaches(actor, bondbook)) and not benighted(actor) and not knows(actor, bondbook_read).
    Time 1.
    On success { Assert knows(actor, bondbook_read). Assert knows(actor, hired_sold). }
    Result "This Fair's hirings: Tansy Hobb, fifteen, Swale Head, pail; Amos Pell, nineteen, Garthwaite, whip; and on, name by name, each with a little drawn hand. On the last page, in pencil, in a different hand, broader and more careful: All to Ossett's agent at the thaw. Gallowmoor.".
  }
  Discovery bondbook_read "Kemble's bond book of this Fair's hirings ends, in Harker's own hand: All to Ossett's agent at the thaw. Gallowmoor.".
  Topic tansy_gallowmoor with tansy "Tell Tansy Hobb where the farm in the hills is" when knows(actor, hired_sold) and at(tansy, bond_floor) and not tansyTold(tansy) once {
    Says "She does not cry. She puts her milk-pail down on the straw, carefully, as if it might spill. 'Lead,' she says. 'Mam said.' Round her the others have gone quiet, listening; somebody says 'Gallowmoor' in a whisper, and it goes down the straw like a draught. A big lad with a whip in his hat stands up. 'Then we'll not go,' he says. 'We'll not.' Tansy looks at the barred river door, and then at you. 'We shook,' she says. 'We all shook.'".
    On discuss { Assert tansyTold(tansy). }
  }
  Relation tansyTold(group).
  // With the hired told, and on their feet, the bar comes off together, without anybody's strength in particular.
  Action bar_together(actor: group, site: place) "Get the hired up, all together, to work the iced bar off the river door" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bond_floor) and tansyTold(tansy) and at(hired, bond_floor) and state(river_bar, barred).
    Time 3.
    On success { Assert state(river_bar, unbarred). }
    Result "Twenty pairs of hands on the baulk, and the big lad with the whip counting, and Tansy Hobb pouring hot water out of the brazier-kettle into the iron brackets a cupful at a time: the ice cracks, and the bar shifts, and on the third heave it comes up out of its brackets with a shriek of iron, and the river door swings a hand's breadth open on the dark and the ice.".
  }
  // A company shut in the bondhouse is let out at the Landing with the rest, to be landed; unless it has gone.
  Rule bondhouse_out when inBondhouse(party) and not at(party, bond_floor) and not at(party, bond_loft) { Retract inBondhouse(party). }
}

data/adventures/liberty-of-the-ice/ice.k:
Module pellam "The Liberty of the Ice" {
  // ── The ice: what is seen ─────────────────────────────────────────────────────────────────────────────────────────
  Observe swan_foot_scene at swan_foot when not iceGone() and not lampLit() "The foot of Swan Stairs, on the ice. The river is white and hard from bank to bank, scarred grey with sledge-runners and skates, and up it, from the bridge to as far down as you can see, runs a street of booths made of oars and sailcloth, with smoke going straight up from every one of them into the cold air. The noise comes up the ice at you all at once: hawkers, a fiddle, a hammer, a pig. A boy goes past on bones strapped to his boots, very fast, shrieking.".
  Observe swan_foot_night at swan_foot when not iceGone() and lampLit() "The foot of Swan Stairs. Up the river the booths of Freezeland Street are lit from inside like paper lanterns, and every one of them is making a noise.".
  Observe freezeland_scene at freezeland when not iceGone() and not lampLit() and not visitedBefore(freezeland) "Freezeland Street, at its top end, by the Glove Post: the thick of the Fair. Booths of sailcloth on oars, gin and gingerbread, hot codlings, a skittle alley where men bowl a frozen sheep's head, a swing-boat on a frame, a man selling slices of the ox, a man selling knowledge of the future, a man selling nothing anyone can see with great conviction. Everyone is shouting the price of something. Nobody is saying what anything is worth.".
  Observe freezeland_again at freezeland when not iceGone() and not lampLit() and visitedBefore(freezeland) "Freezeland Street by the Glove Post, loud and smoking: gingerbread, skittles, the swing-boat, the crier's barrel.".
  Observe freezeland_lamps at freezeland when not iceGone() and lampLit() and not dark() "Freezeland Street at lamp-lighting: lanterns on every oar, the ice gone gold in them, and the Fair louder now it cannot be seen so well.".
  Observe freezeland_dark at freezeland when not iceGone() and dark() "Freezeland Street by night: half the booths dark and laced up, the other half louder than ever. Under the lantern at the Glove Post the frost on the great glove glitters.".
  Observe low_scene at freezeland_low when not iceGone() and not visitedBefore(freezeland_low) "The lower end of Freezeland Street, where the booths are older and the jokes worse. A printing booth with a press in it, clanking. A gin-tent with a painted sign of a lamb on skates. A booth hung with ribbons, with a board that says MARRIAGES. Beyond the last of them the street gives out into open ice, and the ox roast's smoke, and further down, the grey of the Reach.".
  Observe low_again at freezeland_low when not iceGone() and visitedBefore(freezeland_low) "The lower end of Freezeland Street: the clanking press, the Frozen Lamb, the ribboned booth of the Ice Chapel.".
  Observe arches_scene at under_arches when not iceGone() "Under the arches of Pellam Bridge the ice is bluer and older, heaved up into ridges where the river came against the starlings and froze standing. It is very quiet here after the Fair: a drip somewhere, the bridge over you like a roof of stone. A rope ladder hangs down the face of the third starling from a hatch high up in its side.".
  Observe hay_foot_scene at hay_foot when not iceGone() "The foot of Hay Stairs, on the Bankside shore of the ice. Above you Hay Wharf stands up out of the river on its piles, and on it a long blind warehouse with a door in its river-wall, low down, that someone has barred, and painted on its gable in white: J. HARKER. WOOL.".
  Observe ox_scene at ox_roast when not iceGone() "The ox roast: a whole ox on an iron spit over a fire of sea-coal laid on a hearth of bricks, so that the ice will not melt under it, which it is doing all the same, slowly; the hearth has sunk a hand's breadth into a pool of its own making and the Butchers' Company's men stand round it arguing. The smell is extraordinary. Slices are a penny, on bread.".
  Observe reach_head_scene at reach_head when not iceGone() and not dark() "Past the last booth the Fair stops as if at a wall, and there is only ice: grey, wide, and very quiet, with the river showing black through it in places like a vein. A line of sledge-marks goes away down the middle of the Reach, and people keep to it. Far down, a hulk sits locked in the ice at an angle, with her masts gone.".
  Observe reach_head_night at reach_head when not iceGone() and dark() "The head of the Reach, at night. Behind you the noise and lights of the Fair; in front of you nothing, grey under the stars, and a cold that comes up off the river and through your boots.".
  Observe black_reach_scene at black_reach when not iceGone() and not dark() "The Black Reach: the deep channel, where the Lisk still runs under the ice, and the ice over it is grey, and creaks when you stand still. Off to one side, near the bank, a ring of stakes with a rope round them marks a hole that has never frozen over, black water breathing a little steam. Someone has put a penny on one of the stakes.".
  Observe black_reach_night at black_reach when not iceGone() and dark() "The Black Reach, at night. You can hear the river under the ice, and once a sound like a door slammed a long way off, which is the ice. The black hole by the bank is a blacker place in the dark.".
  Observe hulk_scene at patience_deck when not iceGone() "The deck of the Patience: a collier-brig frozen in on her way up to the city a month ago and left, her masts struck, her deck white, listing to starboard in the ice. A hatch, closed. Her name is still on her stern in flaking gold.".
  Observe sledge_scene at sledge_road when not iceGone() "The sledge marks go on south down the middle of the river, where the Lisk is wide and frozen hard, toward the downs and the south road beyond the snow. Nobody is on them. From here you can see the whole Fair behind you, very small, smoking.".

  // ── The Frozen Lamb ───────────────────────────────────────────────────────────────────────────────────────────────
  Observe lamb_scene at lamb when not iceGone() and not visitedBefore(lamb) "The Frozen Lamb: a gin-tent the size of a barn, sailcloth on a frame of oars, a brazier in a tub of sand at either end and a bar made of a ship's hatch-cover. Benches. Hot gin with nutmeg on it. At the far end, under a lantern, one bench by itself has LIARS painted on its back. The tent's keeper is a big handsome woman in her fifties with her sleeves rolled up, who looks at everyone who comes in as if she had been expecting someone else.".
  Observe lamb_again at lamb when not iceGone() and visitedBefore(lamb) "The Frozen Lamb: the braziers in their sand, the hatch-cover bar, the Liars' Bench under its lantern.".
  Observe lamb_bench at lamb when not iceGone() and at(broom, lamb) "On the Liars' Bench under the lantern sits Justice Broom with her ear-trumpet and a glass of hot gin, and round her a crowd, waiting. Whoever has a lie stands on the bench opposite and tells it, and the crowd shouts, and Broom listens with her eyes shut.".
  Person bel "Bel Ashby" at lamb {
    Role "the keeper of the Frozen Lamb". Ancestry human. Peaceable. Pronouns she. Manner jovial.
    Greets "'Gin's hot, the bench is warm and the lies are free,' says Bel Ashby. 'What'll you have?' She looks past you at the flap, and then back.".
    Greets again "'Back again,' says Bel, and pours before you ask.".
    Sells rations for 1 coin from 20.
  }
  Kind honey_kind "a crock of honey" is gear worth 2 weighing 1 described "A brown crock of fell honey with a cloth tied over it, gone hard as candle-wax with the cold.".
  Item honey "a crock of honey" is honey_kind at limbo.
  Relation honeyBought(group).
  Action buy_honey(actor: group, site: place) "Buy a crock of honey from Bel" {
    Requires able(actor) and company(actor) and at(actor, site) and at(bel, site) and quantity(actor, gold) >= 2 and not honeyBought(actor) and at(honey, limbo).
    Time 1 minute.
    On success { Decrease quantity(actor, gold) by 2. Assert honeyBought(actor). Retract at(honey, limbo). Assert at(honey, lamb). }
    Result "Bel reaches under the hatch-cover and comes up with a crock. 'For the hot gin,' she says. 'Fell honey. What you want it for is your business.' She puts it on the bar.".
  }
  Topic bel_fair with bel "Ask Bel about the last Frost Fair" when true once {
    Says "'Thirty-one winters.' Bel wipes the bar. 'I was nineteen. My father had this tent, on this ice, near enough this spot, and I poured, and danced, and skated on the Flashes with every boy in Pellam.' She stops wiping. 'And the last night of it the ice went out from under the bottom of the Fair with a noise like the end of the world, and in the morning there was a river, and everyone went home.' She starts wiping again. 'Everyone talks about the last ice as if it were a wedding. It was a wedding. It was mine, and it went out with the river, and he's an alderman.' She looks at you sharply. 'Don't ask me who. Have a gin.'".
    On discuss { Assert knows(actor, bel_wed). }
  }
  Discovery bel_wed "Bel Ashby was married at the last Frost Fair, thirty-one winters ago, to a boy who is now an alderman of Pellam; the ice went out the same night." {
    Known by bel, doody.
  }

  // ── Noll Brisket's printing booth ─────────────────────────────────────────────────────────────────────────────────
  Observe printing_scene at printing when not iceGone() "A booth hardly bigger than the press in it: an old wooden screw-press, a case of type, a brazier under the ink-slab to keep the ink from freezing, and pinned all round the canvas cards that say, in a border of little skates and hearts, PRINTED ON THE ICE AT PELLAM, with a name. A tall boy with ink to the elbows works the press and talks at the same time.".
  Person noll "Noll Brisket" at printing {
    Role "the printer on the ice, ink to the elbows". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "'Your name on the ice, a penny, and a keepsake for life,' says Noll Brisket, without stopping the press. 'Or your sweetheart's. Or your enemy's, with a picture. What'll it be?'".
    Greets again "Noll waves an inky hand without stopping the press.".
  }
  Kind ice_card "a card printed on the ice" is gear worth 0 weighing 0 described "A card in a border of little skates and hearts: PRINTED ON THE ICE AT PELLAM, IN THE GREAT FROST, and a name, a little crooked. The ink smells of lamp-black and gin.".
  Kind both_card "a card printed on the ice, with two names" is gear worth 0 weighing 0 described "A card in a border of little skates and hearts: PRINTED ON THE ICE AT PELLAM, IN THE GREAT FROST, and under it two names together, a little crooked, with an ampersand Noll is proud of.".
  Item name_card "a card printed on the ice" is ice_card at limbo.
  Item pair_card "a card with two names on it" is both_card at limbo.
  Relation cardPrinted(group). Relation pairPrinted(group).
  Action print_name(actor: group, site: place) "Have your name printed on the ice, for a penny" {
    Requires able(actor) and company(actor) and at(actor, site) and at(noll, site) and quantity(actor, gold) >= 1 and not cardPrinted(actor).
    Time 1.
    On success { Decrease quantity(actor, gold) by 1. Assert cardPrinted(actor). Retract at(name_card, limbo). Assert at(name_card, printing). }
    Result "Noll sets your name in the stick, letter by letter, pulls the bar, and peels the card off the forme still wet. 'Printed on the ice,' he says, holding it up to the light. 'When you're old you'll show it to someone and they won't believe you.'".
  }
  Action print_pair(actor: group, site: place) "Have your name and Ursel's printed on one card" {
    Requires able(actor) and company(actor) and at(actor, site) and at(noll, site) and travelsWith(ursel, actor) and quantity(actor, gold) >= 1 and not pairPrinted(actor).
    Time 1.
    On success { Decrease quantity(actor, gold) by 1. Assert pairPrinted(actor). Retract at(pair_card, limbo). Assert at(pair_card, printing). }
    Result "Ursel says 'Don't be soft,' and stands beside you while Noll sets it, and reads it upside down in the stick before he pulls it, and says nothing at all. When the card comes off the forme she takes it from Noll before you can, and looks at it, and gives it to you. 'Keep that,' she says. 'Somebody ought to.'".
  }
  Topic noll_gazette with noll "Ask Noll who writes the Frost Gazette" when true once {
    Says "Noll pulls the bar, very hard. 'Mr. Icicle,' he says. 'Mr. Icicle writes it. Comes in the night, leaves the copy under the ink-slab, and a shilling, and I set it in the morning and it's on the ice by noon.' He peels off a card. 'Never seen him.' He goes red to the ears, which is a long way to go with that much ink on them.".
    On discuss { Assert knows(actor, gazette_night). }
  }
  Discovery gazette_night "The Frost Gazette is written by someone who calls themself Mr. Icicle, who leaves the copy at Noll's press at night. Noll says he has never seen them, and goes red saying it." {
    Known by noll.
  }
  Observe gazette_pinned at printing when not iceGone() and not gazettePrinted(lisk) "Pinned to the canvas by the press, this morning's FROST GAZETTE: a column of fair gossip (an alderman's poem; a debtor's waistcoat; the Butchers' ox) and at the bottom, in smaller type: 'Mr. Icicle asks whether the RIVER is the only party at this Fair that DROWNS PEOPLE, and whether a hat is the same thing as a HEAD.'".
  Relation gazettePrinted(place).
  Topic noll_thessaly with noll "Ask Noll about Thessaly Harker" when knows(actor, thessaly_icicle) once {
    Says "Noll stops the press. It is the first time you have seen it stopped. 'She comes at eleven,' he says, low. 'Most nights. In her cloak. She thinks I don't know her.' He looks at the forme. 'I set every word she writes. I'd set the Bible backwards for her.' He starts the press again. 'She's marrying the alderman on Saturday. Her father's alderman. I'm a printer on the ice. When the ice goes I'm a printer on nothing.' The bar comes down. 'Don't tell her I said.'".
    On discuss { Assert knows(actor, noll_loves). }
  }
  Discovery noll_loves "Noll Brisket, the printer on the ice, is in love with Thessaly Harker, and sets every word she writes as Mr. Icicle, and has never said so to her." {
    Known by noll.
  }

  // ── The Liars' Bench ──────────────────────────────────────────────────────────────────────────────────────────────
  // From seven to eleven, at the Frozen Lamb, while the Reeve sits there. One go a night, for whoever has the nerve.
  Kind silver_tongue_kind "the Silver Tongue" like ashwood_charm granting deception worth 12
    described "A little silver tongue on a ribbon, worn smooth, engraved on one side BROOM and on the other THE ICE, given by the Reeve of the Ice to the best liar of the Fair. Whoever wears it is listened to by people who know better.".
  Item silver_tongue "the Silver Tongue" is silver_tongue_kind at limbo.
  Relation benchTried(group). Relation benchWon(group). Relation benchTruth(group). Relation broomTold(group).
  Rule bench_resets when hour(clock) == 7 and benchTried(party) { Retract benchTried(party). }
  Query benchOpen() means hour(clock) >= 19 and hour(clock) < 23 and at(broom, lamb) and not iceGone().
  Action tell_bench_lie(actor: group, site: place) "Stand on the bench and tell the Reeve the best lie you have" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lamb) and benchOpen() and not benchTried(actor) and not benchWon(actor)
      and not benchWon(ursel).
    Time 2.
    Resolve check(actor, deception, dc_hard).
    On success { Assert benchTried(actor). Assert benchWon(actor). Retract at(silver_tongue, limbo). Assert at(silver_tongue, lamb). }
    On failure { Assert benchTried(actor). }
    Result "You get up on the bench and tell it, and somewhere in the middle of it you find that you have put in something true, a small true thing you had not meant to, and the crowd goes quiet at it and then roars. Broom opens her eyes. 'There,' she says. 'There it is. The stone in the plum.' She takes a little silver tongue on a ribbon out of her coat and holds it out to you. 'Mind how you use it.'".
    Otherwise "You tell it, and the crowd laughs in the right places, and Broom listens with her eyes shut to the end and then says, 'Very nice. No stone,' and the next liar is already climbing up. Come back tomorrow night, if you have another.".
  }
  // A plain person's way to the Silver Tongue, and to the Reeve's ear: tell the Bench the truth about the hired, as if
  // it were a tall tale. Kemble, Harker's clerk, drinks at the Lamb, and hears it too.
  Action tell_bench_truth(actor: group, site: place) "Stand on the bench and tell the Reeve, as if it were a tall tale, what Master Harker does with his hired" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lamb) and benchOpen() and not benchTruth(actor)
      and knows(actor, hired_sold).
    Time 2.
    On success { Assert benchTruth(actor). Assert benchTried(actor). Assert broomTold(broom). Assert harkerWary(harker).
      Assert benchWon(actor). Retract at(silver_tongue, limbo). Assert at(silver_tongue, lamb). }
    Result "You tell it as a tall tale, a wool-factor who hires shepherds for a farm in the hills and sells them by the dozen to a lead mine, and the crowd laughs at first, and then does not, and then a man near the flap gets up and goes out quickly. Broom has opened her eyes in the first minute and does not shut them. When you have finished it is very quiet in the Frozen Lamb. 'That's not a lie,' says Broom at last. 'That's not a lie at all.' She takes a little silver tongue on a ribbon out of her coat, and looks at it, and gives it to you all the same. 'It's the stone with no plum,' she says. 'It's the best I've heard.' The man who went out was Kemble, Master Harker's clerk.".
  }
  Relation harkerWary(group).
}

data/adventures/liberty-of-the-ice/landi:
Module pellam "The Liberty of the Ice" {
  // ── The Landing ───────────────────────────────────────────────────────────────────────────────────────────────────
  // At two on the last day the Court sits at the Glove Post, with the city's witness at the Reeve's elbow, and cries
  // the Fair's bargains, hand to hand, case by case, each for half an hour: Callow; Gant; the Squire's flock;
  // Harker's hired; and whatever else was shaken on. Then the ice is landed, and what was not landed goes out with it.
  Measure landingStart(place).
  Rule landing_opens when thirdDay() and hour(clock) >= 14 and not landingAt(lisk) and not landingDone(lisk) and not iceGone() {
    Assert landingAt(lisk). Set landingStart(lisk) to watch(clock). }
  Kind landingcase.
  Query caseIs(a: landingcase, b: landingcase) means landingAt(lisk) and watch(clock) - landingStart(lisk) >= caseFrom(a) and watch(clock) - landingStart(lisk) < caseFrom(b).
  Measure caseFrom(landingcase).
  Entity case_callow: landingcase "the case of Magister Callow". Entity case_gant: landingcase "the case of Sir Lionel Gant".
  Entity case_flock: landingcase "the case of the Hawsfold flock". Entity case_hired: landingcase "the case of Harker's hired".
  Entity case_hands: landingcase "the last hands". Entity case_end: landingcase "the end of the Landing".
  Initially Set caseFrom(case_callow) to 0. Initially Set caseFrom(case_gant) to 3. Initially Set caseFrom(case_flock) to 6.
  Initially Set caseFrom(case_hired) to 9. Initially Set caseFrom(case_hands) to 12. Initially Set caseFrom(case_end) to 14.
  Query callowCase() means caseIs(case_callow, case_gant).
  Query gantCase() means caseIs(case_gant, case_flock).
  Query flockCase() means caseIs(case_flock, case_hired).
  Query hiredCase() means caseIs(case_hired, case_hands).
  Query handsCase() means caseIs(case_hands, case_end).
  Query landingEnds() means landingAt(lisk) and watch(clock) - landingStart(lisk) >= caseFrom(case_end).
  // Everyone the Landing wants is brought to the Glove Post.
  Rule landing_gathers when landingAt(lisk) and not landingDone(lisk) and not gathered(lisk) {
    Assert gathered(lisk). Assert at(harker, freezeland). Assert at(kemble, freezeland). Assert at(gosling, freezeland). Assert at(tredgold, freezeland). }
  Relation gathered(place).
  // The clerk's list, chalked on a board at the Reeve's elbow, so that whoever has a case knows when it is coming.
  Observe landing_list at freezeland when landingAt(lisk) and not landingDone(lisk) "On a board at the Reeve's elbow the Court's clerk has chalked the Landing's list, and crosses each case off as it is cried: the heretic Callow, and his hand; Sir L. Gant, debtor; the Hawsfold flock, to J. Harker; J. Harker's hired, twenty; and then ALL OTHER HANDS. Then, in bigger letters: OFF THE ICE AT NINE.".
  // Harker's one chance to be someone else: Ursel, who knows now where he came from, asks him the one question.
  Topic ursel_asks_harker with harker "Stand back, and let Ursel ask Master Harker her question" when landingAt(lisk) and not landingDone(lisk) and travelsWith(ursel, party) and (knows(actor, ursel_knows_harker) or toldCobbNote(actor)) and not urselAskedHarker(lisk) once {
    Says "Ursel goes and stands in front of him, close, where the Reeve can see them both. 'Swale Head,' she says. 'Twenty-nine years since. A farm at the beck-head, forty acres of stones, a man called Cobb with a note out against his wool. Was it you came up the dale with it?' Harker looks at her for as long as it takes the clerk to dip his pen. 'I have been up every dale in the north country with a note, mistress,' he says gently. 'I do not remember the farms.' He looks down at his hands, folded at his waist, the right in the left. 'I remember the hands.' And for a moment you think he is going to say something else, and so does she; and then Kemble touches his sleeve, and he turns back to the Reeve, and it is gone. Ursel stands there a moment longer. Then she comes back to you and says, quite cheerfully, 'Well. Now I know I'll never know,' and takes your arm, and does not let go of it until the case is over.".
    On discuss { Assert urselAskedHarker(lisk). Increase urselTrust(ursel) by 1. }
  }
  Relation urselAskedHarker(place).
  Observe ursel_watches_harker at freezeland when hiredCase() and travelsWith(ursel, party) and knows(party, ursel_knows_harker) "Ursel is not watching the hired. She is watching Harker's hands: the way he holds them, clasped, at his waist, the right in the left, as if one were keeping the other from something.".
  Rule landing_hired_come when landingAt(lisk) and not landingDone(lisk) and inBond(hired) and not hiredFled(lisk) and not at(hired, freezeland) { Assert at(hired, freezeland). Assert at(tansy, freezeland). }
  Rule landing_taken_come when landingAt(lisk) and not landingDone(lisk) and dickonTaken(dickon) and not at(dickon, freezeland) { Assert at(dickon, freezeland). Assert at(jem, freezeland). }
  Rule landing_party_hired when landingAt(lisk) and not landingDone(lisk) and inBondhouse(party) and not at(party, freezeland)
    says "At half past one Kemble unlocks the bondhouse and walks Harker's hired, and you with them, over the ice to the Glove Post, two by two, to be landed." {
    Assert at(party, freezeland). Retract inBondhouse(party). }
  Rule landing_gant_come when landingAt(lisk) and not landingDone(lisk) and at(gant, freezeland) and not gantSafe(gant) { Assert gantAtLanding(gant). }
  Relation gantAtLanding(group).
  Observe landing_scene at freezeland when landingAt(lisk) and not landingDone(lisk) "The Landing. The whole Fair has come to the Glove Post and stands packed on the ice in a great ring, quiet for once, breathing. Justice Broom sits at the foot of the mast on the Court's chair, set on a herring barrel, with her trumpet; the waterman-clerk at her side with the Court's book; and at her other elbow, on a stool, as the city's witness, Alderman Gosling, in his chain. Master Harker stands at the front with Kemble and his book. Above them all the great frozen glove.".

  // ── The case of Magister Callow ───────────────────────────────────────────────────────────────────────────────────
  Rule callow_case_dead at freezeland when callowCase() and callowDead(callow) and not callowCaseOpened(lisk)
    says "The clerk calls Magister Edrin Callow, on the charge of unswearing. Justice Broom turns her trumpet toward the empty stocks, as if they might say something. 'Discharged,' she says. 'By the Flow.' Nobody laughs." { Assert callowCaseOpened(lisk). }
  Rule callow_case_hand at freezeland when callowCase() and callowHand(party) and together(callow, party) and not callowCaseOpened(lisk)
    says "The clerk calls Magister Edrin Callow, on the charge of unswearing, and his hand to produce him. Callow steps out of the crowd on your arm, coughing, and bows to the Reeve. 'Produced,' says Broom, and looks at you with something that might be approval. 'Your hand is kept. Now, Magister. What have you to say?'" {
    Assert callowCaseOpened(lisk). Assert handKept(callow_bargain). }
  Rule callow_case_stocks at freezeland when callowCase() and callowStocked(callow) and not callowDead(callow) and not callowCaseOpened(lisk)
    says "The clerk calls Magister Edrin Callow, on the charge of unswearing. The watermen let him out of the stocks and he stands before the Reeve, swaying, blue at the lips, and smiles at her. 'Well, Magister,' says Broom. 'What have you to say?'" {
    Assert callowCaseOpened(lisk). }
  Rule callow_case_gone at freezeland when callowCase() and callowHand(party) and not together(callow, party) and not callowCaseOpened(lisk)
    says "The clerk calls Magister Edrin Callow, on the charge of unswearing, and his hand to produce him. Everyone turns to look at you. There is no Callow. Justice Broom puts down her trumpet. 'A hand,' she says, 'given for a man who says no hand binds, and broken. I'll not pretend I didn't see it coming.'" {
    Assert callowCaseOpened(lisk). Assert handBroken(callow_bargain). Assert brokeHand(party). }
  Relation callowCaseOpened(place). Relation knowingArgued(place).
  Action argue_knowing(actor: group, site: place) "Stand beside Callow and give the Reeve the argument you made together: a hand binds only what the one who shook it knew" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, freezeland) and callowCase() and saidKnowing(actor) and together(callow, actor) and not callowDead(callow) and not knowingArgued(lisk).
    Time 1.
    On success { Assert knowingArgued(lisk). Assert knowingDoctrine(lisk). }
    Result "Callow begins, and then stops, and turns to you, and bows. 'My hand,' he says, 'put it better.' So you say it, to the Reeve and the whole silent Fair: that a word is free on the ice, and a hand is bound; but a hand is only bound to what was really there when it was given, what the one who shook it knew he was shaking on; and a hand got by a lie about the very thing shaken on was never given to that thing at all. Justice Broom listens with her eyes open. When you have finished she says, slowly, 'That is not unswearing. That is the law of the ice, said properly, for the first time in two hundred years.' She bangs her trumpet. 'Discharged.'".
  }
  Action argue_knowing_alone(actor: group, site: place) "Speak for Callow yourself: a hand shaken on a lie about the thing itself was never given to it" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, freezeland) and callowCase() and callowCaseOpened(lisk) and not callowDead(callow) and not saidKnowing(actor)
      and (knows(actor, hired_sold) or knows(actor, gant_altered)) and not knowingArgued(lisk) and not knowingTried(actor).
    Time 1.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert knowingArgued(lisk). Assert knowingDoctrine(lisk). Assert knowingTried(actor). }
    On failure { Assert knowingTried(actor). }
    Result "You speak for him, to the Reeve and the whole Fair: a word is free and a hand is bound, but bound only to what the one who shook it knew; a hand got by a lie about the very thing shaken on was never given to that thing at all. Callow, beside you, has stopped coughing to listen. Justice Broom looks at you a long time. 'That's not his doctrine,' she says. 'That's better than his doctrine.' She bangs her trumpet. 'Discharged.'".
    Otherwise "You try to say it, and it comes out as Callow's doctrine, and the Fair groans, and Broom shakes her head. 'Nothing stays,' she says drily, 'and nor does that argument.'".
  }
  Relation knowingTried(group).
  Rule callow_case_ends when gantCase() and callowCaseOpened(lisk) and not callowDead(callow) and not callowCaseClosed(lisk) and not handBroken(callow_bargain) { Assert callowCaseClosed(lisk). }
  Relation callowCaseClosed(place).
  Rule callow_acquitted when callowCaseClosed(lisk) and knowingArgued(lisk) and not callowAcquitted(callow) { Assert callowAcquitted(callow). Retract callowStocked(callow). Assert state(stocks, empty). }
  Rule callow_convicted at freezeland when callowCaseClosed(lisk) and not knowingArgued(lisk) and not callowConvicted(callow) and not callowAcquitted(callow)
    says "'Guilty of unswearing,' says Justice Broom, 'on his own admission, which is the only thing he has ever been consistent about. The stocks, until the ice goes.' The watermen put him in. He thanks them, and begins at once to preach to the Landing from the stocks, about the ice." {
    Assert callowConvicted(callow). Assert callowStocked(callow). Assert state(stocks, holding). Retract following(callow, party). }
  // A hand broken costs ten coin, or what there is.
  Rule hand_broken_fine when handBroken(callow_bargain) and brokeHand(party) and not callowFined(party) { Assert callowFined(party). Decrease quantity(party, gold) by 10. }
  Relation callowFined(group).

  // ── The case of Sir Lionel Gant ───────────────────────────────────────────────────────────────────────────────────
  Rule gant_case at freezeland when gantCase() and gantAtLanding(gant) and not gantFree(gant) and not gantSafe(gant) and not gantCaseOpened(lisk)
    says "The clerk calls Sir Lionel Gant, of nowhere in particular. Master Harker asks the Court that when the ice goes Sir Lionel be cried off it at Hay Stairs, into the hands of the bailiffs who wait there with his writ, for thirty coin. Sir Lionel stands before the Reeve with his hat in his hand and says, very quietly, 'It was three.'" { Assert gantCaseOpened(lisk). }
  Rule gant_case_clink at freezeland when gantCase() and gantSafe(gant) and not gantCaseOpened(lisk)
    says "The clerk calls Sir Lionel Gant. A boy from Bankside brings up a note to the Reeve, who reads it out: 'Sir Lionel Gant presents his compliments to the Court of the Ice from the Clink, where he owes nobody anything.' The Fair cheers. Harker does not." { Assert gantCaseOpened(lisk). }
  Relation gantCaseOpened(place). Relation harkerForger(group).
  Action show_counterpart(actor: group, site: place) "Show the Reeve Sir Lionel's counterpart: the bond was three coin, and Harker's copy has been made thirty" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, freezeland) and gantCase() and gantCaseOpened(lisk) and gantAtLanding(gant) and carries(actor, counterpart) and knows(actor, gant_altered) and not gantVoided(gant).
    Time 1.
    On success { Assert gantVoided(gant). Assert gantFree(gant). Assert harkerForger(harker). }
    Result "Justice Broom takes the two papers in her small hard hands and holds them side by side against the light, a long time, the counterpart and the copy Harker's writ was drawn from, and the whole Fair waits. 'Three,' she says. 'In words. And here a three and a stop, made into thirty, in good ink, in Fleece Row.' She does not look at Harker. She gives the counterpart back to Sir Lionel. 'Three coin,' she says. 'Pay it to the Court.' Sir Lionel has three coin, just. Behind him half the Fair is looking at Master Harker, who is looking at the glove.".
  }

  // ── The case of the Hawsfold flock ────────────────────────────────────────────────────────────────────────────────
  Relation flockCaseOpened(place). Relation flockLanded(place). Relation flockHonest(place). Relation pilloried(group). Relation restitution(group).
  Rule flock_absent at freezeland when flockCase() and flockShook(party) and not at(party, freezeland) and not flockCaseOpened(lisk)
    says "The clerk calls a hand: Josias Harker, and the Squire of Hawsfold, two hundred fell ewes. Master Harker turns, smiling, to where the Squire should be. There is no Squire. He looks round the ring, and round it again, and Kemble looks, and the crowd begins to laugh, the way a crowd laughs at the Landing every Frost Fair at somebody. 'Not here,' says Justice Broom, with deep satisfaction. 'Not landed. It goes out with the river, Master Harker.' She bangs her trumpet. 'Next.'" {
    Assert flockCaseOpened(lisk). }
  Rule flock_present at freezeland when flockCase() and flockShook(party) and at(party, freezeland) and not flockCaseOpened(lisk)
    says "The clerk calls a hand: Josias Harker, and the Squire of Hawsfold, two hundred fell ewes at Hawsfold under Swale Fell, delivery at the shearing. Master Harker turns to you, smiling, with his palm already open." {
    Assert flockCaseOpened(lisk). }
  // Exposed: no squire and no flock, and a hand shaken. The pillory, unless the price is paid back, twice over.
  Rule flock_exposed at freezeland when flockCase() and flockCaseOpened(lisk) and flockShook(party) and at(party, freezeland) and squireExposed(party) and not flockReal(party) and not pilloried(party) and not restitution(party) and not exposedCried(lisk)
    says "'There is no Squire of Hawsfold,' says Master Harker to the Reeve, very gently, 'and no flock. There is a shepherd called Haws.' The Fair goes quiet. Justice Broom turns her trumpet on you. 'A lie's no crime on the ice,' she says. 'But you shook. Can you deliver two hundred ewes at the shearing?' You cannot. 'Then pay him back what he paid, and as much again for the trouble, before I rise; or the pillory, here, till the ice goes.'" {
    Assert exposedCried(lisk). }
  Relation exposedCried(place).
  Action pay_restitution(actor: group, site: place) "Pay Master Harker back his thirty, and thirty more for the trouble, before the Reeve" {
    Requires able(actor) and company(actor) and at(actor, site) and exposedCried(lisk) and flockCase() and quantity(actor, gold) >= 60 and not restitution(actor) and not pilloried(actor).
    Time 1 minute.
    On success { Decrease quantity(actor, gold) by 60. Increase quantity(harker, gold) by 60. Assert restitution(actor). Assert handBroken(flock_bargain). }
    Result "Sixty coin, counted into Kemble's hands in front of the whole Fair, and the hand is unmade. Harker takes it without a word. You are poorer than you came, and free.".
  }
  Rule pillory_falls at freezeland when hiredCase() and exposedCried(lisk) and not restitution(party) and not pilloried(party)
    says "Justice Broom rises a little on her barrel. 'The pillory,' she says, 'till the ice goes.' The watermen take you by the elbows, quite kindly, and put your head and hands through the holes of the pillory beside Callow's stocks, at the foot of the Glove Post, in front of everyone in Pellam, and the Fair, which has been waiting three days for this, begins to throw snow." {
    Assert pilloried(party). Assert handBroken(flock_bargain). }
  // Believed, or made true: the hand is landed, and Harker pays the rest.
  Rule flock_landed at freezeland when flockCase() and flockCaseOpened(lisk) and flockShook(party) and at(party, freezeland) and not squireExposed(party) and not flockLanded(lisk)
    says "You shake again, before the Reeve, and the clerk cries it: 'Landed!' and writes it in the Court's book; and now, the Fair knows and you know, it is good from here to the sea. Master Harker smiles, and has Kemble count out what remains of the price." {
    Assert flockLanded(lisk). Assert landed(flock_bargain). }
  Rule flock_rest_paid when flockLanded(lisk) and earnestTaken(party) and not restPaid(party) { Assert restPaid(party). Increase quantity(party, gold) by 30. Decrease quantity(harker, gold) by 30. }
  Relation restPaid(group).
  Rule flock_true when flockLanded(lisk) and flockReal(party) and not flockHonest(lisk) { Assert flockHonest(lisk). }
  // The twenty indentures, landed to the Squire with the flock.
  Rule indentures_landed when flockLanded(lisk) and indenturesTraded(party) and not landed(indenture_bargain) { Assert landed(indenture_bargain). Assert hiredSquire(lisk). }
  Relation hiredSquire(place).

  // ── The case of Harker's hired ────────────────────────────────────────────────────────────────────────────────────
  Relation hiredCaseOpened(place). Relation hiredLanded(place). Relation hiredReleased(place). Relation unsworn(place). Relation hiredMissing(place).
  Rule hired_case_gone at freezeland when hiredCase() and hiredFled(lisk) and not hiredCaseOpened(lisk)
    says "The clerk calls Master Harker's hired, twenty hands, a year's service. Harker turns to where they should be standing. Nobody is standing there. Kemble has his book open and his mouth open. 'Gone down the Reach in the night,' somebody shouts from the back, 'on the Company's sledges!' and the watermen in the ring roar. Justice Broom looks at Master Harker, and the whole ring looks with her. 'Not here,' she says. 'Not landed.' Her voice is not unkind. 'It goes out with the river.'" {
    Assert hiredCaseOpened(lisk). Assert hiredMissing(lisk). }
  Rule hired_case_squire at freezeland when hiredCase() and hiredSquire(lisk) and not hiredCaseOpened(lisk)
    says "The clerk calls the hired. 'Landed to the Squire of Hawsfold,' says Kemble, a little sourly, 'with the flock.' The twenty stand in a line in front of the Reeve, in their blankets, with their tokens in their hats, and look at you, because they are yours now, for a year, good in any court." {
    Assert hiredCaseOpened(lisk). }
  Rule hired_case_opens at freezeland when hiredCase() and not hiredFled(lisk) and not hiredSquire(lisk) and not hiredCaseOpened(lisk)
    says "The clerk calls Master Harker's hired, twenty hands, a year's service on a farm in the hills. They stand in a line before the Reeve in their blankets, with their tokens in their hats: crooks, pails, whips, mops. Tansy Hobb is at the end, with her milk-pail on its string. Harker stands beside them with his palm open, kindly, and one by one they come to shake again before the Reeve." {
    Assert hiredCaseOpened(lisk). }
  Action release_hired(actor: group, site: place) "Give the hired their hands back, before the Reeve, and let them go" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, freezeland) and hiredCase() and hiredSquire(lisk) and carries(actor, indentures) and not hiredReleased(lisk).
    Time 1.
    On success { Assert hiredReleased(lisk). Assert tansyFree(tansy). Assert handKept(indenture_bargain). }
    Result "You untie Kemble's black tape and give each of them their indenture back, in front of the Reeve, Tansy Hobb's last, and say the words Broom tells you to say, which are very short: 'Your hand's your own.' Tansy Hobb looks at the paper and then at you, and then she tears it in half, and the big lad with the whip tears his, and then all of them, and the Fair, which has understood rather late what it is watching, begins to cheer, and does not stop. Master Harker, at the front of the ring, has gone the grey of the Reach.".
  }
  Query layable(a: group) means hiredCase() and hiredCaseOpened(lisk) and not hiredSquire(lisk) and not hiredFled(lisk)
    and knowingDoctrine(lisk) and (carries(a, ledger) or carries(a, bondbook)) and not unsworn(lisk).
  Action lay_books(actor: group, site: place) "Lay Harker's books before the Reeve: the farm in the hills is the lead mine at Gallowmoor" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, freezeland) and layable(actor) and witnessFree(gosling).
    Time 1.
    On success { Assert unsworn(lisk). Assert hiredReleased(lisk). Assert tansyFree(tansy). }
    Result "You give the Reeve the book, open, and she reads it with her trumpet in her lap: farm in the hills, and in pencil, Gallowmoor, eight coin, and dead, and dead. She reads for a long time. Then she holds it out to the city's witness. Alderman Gosling reads it, and his face changes, and he says, loud enough for the ring, 'The city witnesses it.' Justice Broom stands up on her barrel. 'By the law of the ice as it was argued here today,' she says, 'a hand is bound to what the one who shook it knew he shook on. These shook on a farm in the hills. There is no farm. There was never any hand.' She turns to the hired. 'Go home,' she says. 'Your hands are your own.' And to the clerk: 'Write it in the book. That's law now, on this river, as long as there's ice to put it on.'".
  }
  // Harker's son-in-law at her elbow will not witness it; the Reeve rules on what she has already been told: by a
  // liar on her own bench, by Mr. Icicle in every booth on the ice, or by a three made thirty in front of her.
  Action lay_books_reeve(actor: group, site: place) "Lay Harker's books before the Reeve, though the city's witness is Harker's son-in-law" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, freezeland) and layable(actor) and not witnessFree(gosling)
      and (gazettePrinted(lisk) or broomTold(broom) or harkerForger(harker)).
    Time 1.
    On success { Assert unsworn(lisk). Assert hiredReleased(lisk). Assert tansyFree(tansy). }
    Result "The Reeve reads the book with her trumpet in her lap, a long time, and holds it out to the city's witness; and Alderman Gosling, Harker's son-in-law of two hours, will not take it. 'The city does not witness,' he says, to the ice, very low. Justice Broom looks at him, and at Master Harker, and at the ring of the whole Fair, which has read it already, or heard it, or seen what Harker does to a three. 'Then the river will,' she says, and stands up on her barrel. 'By the law of the ice as it was argued here today, a hand is bound to what the one who shook it knew he shook on. These shook on a farm in the hills. There is no farm. There was never any hand.' She turns to the hired. 'Go home. Your hands are your own.' And to the clerk: 'Write it in the book. The Reeve witnesses it. That will have to do.'".
  }
  // With the doctrine argued, the books in hand, and Harker's son-in-law at the Reeve's elbow: the city will not witness.
  Observe witness_refuses at freezeland when hiredCase() and knowingDoctrine(lisk) and goslingHarker(gosling) and not gazettePrinted(lisk) and not broomTold(broom) and not harkerForger(harker) and not unsworn(lisk) "At the Reeve's elbow, as the city's witness, sits Alderman Gosling, Harker's son-in-law of two hours, with his chain on and his eyes on the ice. Whatever is laid before the Reeve, you can see, the city will not witness it today.".
  Rule hired_landed at freezeland when handsCase() and hiredCaseOpened(lisk) and not hiredFled(lisk) and not hiredReleased(lisk) and not hiredLanded(lisk) and not hiredSquire(lisk)
    says "The clerk cries it, hand by hand: 'Landed! Landed! Landed!' twenty times, and writes it in the Court's book, and Master Harker thanks the Reeve, and Kemble walks his hired back off the ice to the bondhouse, to wait for Ossett's agent and the thaw." {
    Assert hiredLanded(lisk). Assert landed(hire_bargain). }
  Rule hired_squire_kept when handsCase() and hiredSquire(lisk) and not hiredReleased(lisk) and not hiredLanded(lisk) { Assert hiredLanded(lisk). }
  // By the same ruling, the Squire's own hand was got by a lie about the very thing shaken on.
  Rule unsworn_flock at freezeland when unsworn(lisk) and flockLanded(lisk) and not flockReal(party) and not flockUnsworn(lisk)
    says "'And while I'm about it,' says Justice Broom, turning her trumpet on you, 'a flock that isn't, shaken on, is no hand either, by the same law.' The crowd roars. 'Give Master Harker back his money.' It is fair. It is the law you made." {
    Assert flockUnsworn(lisk). Retract landed(flock_bargain). }
  Relation flockUnsworn(place).
  Rule flock_repaid when flockUnsworn(lisk) and not repaid(party) { Assert repaid(party). Decrease quantity(party, gold) by 60. }
  Relation repaid(group).

  // ── The last hands, and the close ─────────────────────────────────────────────────────────────────────────────────
  Relation handfastLanded(group). Relation handfastLet(group). Relation handfastCried(place).
  Rule handfast_cried at freezeland when handsCase() and handfast(party) and at(party, freezeland) and not handfastCried(lisk)
    says "Last of all the clerk calls a hand of this morning, at the Ice Chapel, by Parson Doody, for a shilling: Ursel Cobb, and you. The Fair, which knows everything, goes 'Ahh.' Justice Broom looks at the two of you over her trumpet. 'Land it,' she says, 'and it's good from here to the sea, as long as you both live. Or let it go out with the river, tonight, and there's an end of it. Your hands.'" {
    Assert handfastCried(lisk). }
  Action land_handfast(actor: group, site: place) "Shake Ursel's hand again before the Reeve, and land it" {
    Requires able(actor) and company(actor) and at(actor, site) and handfastCried(lisk) and handsCase() and not handfastLanded(actor) and not handfastLet(actor) and travelsWith(ursel, actor).
    Time 1 minute.
    On success { Assert handfastLanded(actor). Assert landed(handfast_bargain). }
    Result "Ursel looks at you. Then she puts out her hand, first, in front of all Pellam, and you shake it, and the clerk cries 'Landed!' and the Fair cheers as if somebody had won a race on the Flashes. Ursel Cobb, who has never given her hand on anything in forty years, has given it twice in a day. 'Well,' she says, very loud, to cover something. 'Well. That's me caught.'".
  }
  Action let_handfast(actor: group, site: place) "Tell the Reeve to let it go out with the river" {
    Requires able(actor) and company(actor) and at(actor, site) and handfastCried(lisk) and handsCase() and not handfastLanded(actor) and not handfastLet(actor).
    Time 1 minute.
    On success { Assert handfastLet(actor). }
    Result "'Out with the river,' says Justice Broom, and the clerk does not write it. Ursel nods, quickly. 'Somewhere it doesn't melt, then,' she says, under the noise. 'Or nowhere. We'll see.' She keeps hold of your arm.".
  }
  Rule landing_closes at freezeland when landingEnds() and not landingDone(lisk)
    says "Justice Broom gets down off her barrel. 'The ice is landed,' she says, through her trumpet, to the whole Fair. 'What's landed is landed, and what's not goes out with the river. God save the ice.' The crowd breaks up. Up and down Freezeland Street, already, they are taking the sailcloth off the booths." {
    Assert landingDone(lisk). Retract landingAt(lisk). }
}

data/adventures/liberty-of-the-ice/liber:
Module pellam "The Liberty of the Ice" {
  // ── The law of the ice ────────────────────────────────────────────────────────────────────────────────────────────
  // The river lies in no parish and under no lord, and while it is ice it has its own law, kept by the Watermen's
  // Company and its Reeve: what is said on it is free, and what is shaken on is bound. On the last day of the ice the
  // Court lands its bargains, hand to hand, so that they hold on the banks when there is no ice to stand on; and what
  // is not landed goes out with the river.
  Kind bargain.
  Relation shook(group, bargain). Relation handKept(bargain). Relation handBroken(bargain). Relation landed(bargain).
  Relation melted(bargain).
  Discovery liberty_known "The Liberty of the Ice, cried at noon at the Glove Post: on the ice, a word is free and a hand is bound. Nothing said on the ice is any crime; but a bargain struck by a shake of hands on it, whatever was said to get it, the Court of the Ice will hold you to, to the last penny." {
    Known by broom, tredgold, ursel, bel, gant, kemble, harker, nab, crier.
  }
  Discovery landing_known "On the last day of the ice the Court sits at the Glove Post for the Landing: every bargain of the Fair is cried, hand to hand, both parties standing before the Reeve, and once landed it is good in any court of the country. A bargain not landed goes out with the ice." {
    Known by broom, ursel, kemble, harker, gant, tredgold, callow.
  }
  Discovery ice_nobodys "No warrant, bailiff, banns, tithe or guild rule of the banks runs on the ice. Debtors live on it; lovers marry on it without banns; and anyone may hire anyone on it, for anything, with none of the city's statutes on servants to say otherwise." {
    Known by broom, gant, doody, kemble, harker, tredgold, ursel, bel.
  }

  // The Glove Post: a ship's mast stepped in the ice at the top of Freezeland Street, with a great leather glove nailed
  // to the top of it, the sign of a liberty since there were fairs.
  Observe glove_post at freezeland as feature when not iceGone() "At the top of Freezeland Street a ship's mast has been stepped in the ice and guyed with ropes, and nailed to the head of it, stiff with frost, is a leather glove as big as a sail-bag: the sign of the Liberty. A board at the foot of the mast says in red: SAY WHAT YOU WILL. KEEP WHAT YOU SHAKE ON. C. BROOM, REEVE.".
  Person crier "the Fair's crier" at limbo {
    Role "a waterman with a bell and a voice". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "The crier wipes his bell with his sleeve. 'Noon, and every noon,' he says. 'You'll hear it.'".
  }
  Rule crier_comes when hour(clock) == 12 and not iceGone() and not at(crier, freezeland) { Assert at(crier, freezeland). }
  Rule crier_goes when hour(clock) != 12 and at(crier, freezeland) { Retract at(crier, freezeland). Assert at(crier, limbo). }
  Rule crier_cries at freezeland when hour(clock) == 12 and at(party, freezeland) and at(crier, freezeland) and not iceGone() and not spread(liberty_cried) says "Noon. The crier climbs onto a barrel at the foot of the Glove Post and rings his bell until the whole top of Freezeland Street is looking at him, and cries it: 'O yes, O yes, O yes! The river Lisk being frozen from bank to bank, and lying in no parish and under no lord, the ice is a Liberty, by the custom of the Watermen of Pellam, until it goes! Say what you will on it, and no man shall have the law of you for a word! Keep what you shake on, and the Reeve shall have the law of you for a hand! God save the ice!' Everyone cheers, and goes back to lying to each other." teaches liberty_known { Assert spread(liberty_cried). }
  Entity liberty_cried: fact "The Liberty cried".
  Observe crier_again at freezeland when hour(clock) == 12 and at(crier, freezeland) and spread(liberty_cried) "The crier is on his barrel, crying the Liberty again: say what you will; keep what you shake on.".

  // ── The Court of the Ice ──────────────────────────────────────────────────────────────────────────────────────────
  Observe court_scene at court when not visitedBefore(court) "A tent of patched sailcloth, an iron brazier, and a trestle table across two herring barrels, at which, on a chair with arms, sits a very small old woman in a waterman's coat with an ear-trumpet in her lap. Behind her on the canvas someone has painted, not well, a hand and a glove. A clerk, who is also a waterman, keeps the book. The benches are full of people waiting to be heard and people who have come to hear them.".
  Observe court_again at court when visitedBefore(court) "The Court of the Ice: the brazier, the trestle on its herring barrels, the painted hand and glove on the canvas.".
  Observe court_sitting at court when hour(clock) >= 16 and hour(clock) < 17 and not iceGone() "The Court is sitting. The Reeve listens to each case through her trumpet, with her eyes shut, and opens them only for a good lie, which she seems to taste.".
  Person broom "Justice Clemency Broom" at court {
    Role "the Reeve of the Ice, a waterman's widow of seventy with an ear-trumpet". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "Justice Broom puts her ear-trumpet to her ear and points the other end at you. 'Speak up. If it's a lie, make it a good one. I've heard all the bad ones.'".
    Greets again "Broom lifts her ear-trumpet at you without opening her eyes. 'You again. Go on.'".
  }
  // The Reeve keeps her court from two until five, and spends her evenings on the Liars' Bench at the Frozen Lamb.
  Rule broom_court when hour(clock) >= 14 and hour(clock) < 18 and not iceGone() and not landingAt(lisk) and not at(broom, court) { Assert at(broom, court). }
  Rule broom_landing when landingAt(lisk) and not at(broom, freezeland) { Assert at(broom, freezeland). }
  Rule broom_bench when hour(clock) >= 19 and hour(clock) < 23 and not iceGone() and not at(broom, lamb) { Assert at(broom, lamb). }
  Rule broom_home when (hour(clock) >= 23 or hour(clock) < 9) and not at(broom, limbo) { Assert at(broom, limbo). }
  Rule broom_morning when hour(clock) >= 9 and hour(clock) < 14 and not iceGone() and not at(broom, court) { Assert at(broom, court). }
  Relation landingAt(place).
  Topic broom_law with broom "Ask the Reeve what the law of the ice is" when true once {
    Says "'Two words and a hand.' She holds up a small hard palm. 'Say what you will. Keep what you shake on.' She lowers it. 'A lie is a thing a man makes with his mouth, and I'll not have a man hanged for his trade. A hand is a thing he gives. Give it, and I'll hold him to it if it takes the shirt off him.' She sniffs. 'Thirty-one winters since the last ice. They've forgotten everything on the banks. They think a liberty means nobody minds.' She puts the trumpet back to her ear. 'I mind.'".
    On discuss { Assert knows(actor, liberty_known). Assert knows(actor, ice_nobodys). }
  }
  Topic broom_landing_topic with broom "Ask the Reeve what happens when the ice goes" when knows(actor, liberty_known) once {
    Says "'The Landing.' She says it the way a priest says Easter. 'On the last day, at two, I sit at the Glove Post and every bargain of the Fair is cried, hand to hand, both of 'em standing before me, and I land it. Then it's good from here to the sea, in any court that sits on dry ground.' She smiles, a small hard smile. 'What's not landed goes out with the river. Every Frost Fair there's a crowd of clever men who mean to be across the bridge with their money before two on the last day, so their bargains melt. And every Frost Fair there's a crowd of other clever men waiting at the bridge for them.' She shuts her eyes. 'It's the best day of the year.'".
    On discuss { Assert knows(actor, landing_known). }
  }
  Topic broom_lie with broom "Ask the Reeve what makes a lie good" when knows(actor, liberty_known) once {
    Says "She opens one eye. 'Nobody's ever asked me that.' She thinks. 'A bad lie wants you to believe it. A good lie wants you to want to. And the best,' she says, 'the best has a true thing in the middle of it, like a stone in a plum, that you bite on afterwards, and it hurts your tooth.' She shuts the eye. 'Come to the Bench at the Lamb tonight, if you think you can. I've a silver tongue for whoever makes me bite on something.'".
    On discuss { Assert knows(actor, bench_known). }
  }
  Discovery bench_known "Every night of the Fair the Reeve sits on the Liars' Bench at the Frozen Lamb, from seven, and gives a silver tongue to whoever tells the best lie: one that has a true thing in the middle of it, that hurts the tooth." {
    Known by broom, bel, ursel, nab.
  }

  // ── The stairs: a penny a stair ───────────────────────────────────────────────────────────────────────────────────
  // Tredgold's watermen, out of work since the river froze, keep both stairs onto the ice, and ask a penny a stair.
  Entity stair_bargain: bargain "a penny a stair, with the watermen".
  Measure owedStairs(group). Measure stairCount(passage).
  Initially Set stairCount(swan_stairs) to 12. Initially Set stairCount(hay_steps) to 9.
  Thing swan_plank "the watermen's plank" on swan_stairs is scenery {
    State across blocking "Two watermen sit on the top of Swan Stairs with a plank across it between them, and a tin cup. 'A penny a stair,' says one of them. 'Shake on it.'".
    State lifted "The watermen's plank is lifted aside for you; they nod as you go by.".
  }
  Thing hay_plank "the watermen's plank" on hay_steps is scenery {
    State across blocking "A waterman sits on the top of Hay Stairs with a plank across it and a tin cup. 'A penny a stair, friend. Shake on it.'".
    State lifted "The waterman lifts the plank aside for you.".
  }
  Initially Assert state(swan_plank, across). Initially Assert state(hay_plank, across).
  Relation stairsPaid(group). Relation watermenSour(group). Relation stairsArgued(group).
  Action shake_stairs(actor: group, site: place) "Shake on a penny a stair with the watermen" {
    Grave "A hand shaken on the ice binds: the Court of the Ice will hold you to it, whatever was said.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, swan_lane)
      and not shook(actor, stair_bargain) and not stairsPaid(actor) and not watermenSour(actor) and state(swan_plank, across).
    Time 1 minute.
    On success { Assert shook(actor, stair_bargain). Assert state(swan_plank, lifted). Assert state(hay_plank, lifted).
      Set owedStairs(actor) to 12. }
    Result "You put out your hand, and the waterman spits on his and shakes it, very hard, and lifts the plank. 'Twelve stairs,' he says. 'Twelve pennies. Pay at the bottom or pay at the Court, it's all one to us.' He grins. 'Mind the ninth. It's slippy.'".
  }
  Action shake_hay(actor: group, site: place) "Shake on a penny a stair with the waterman at Hay Stairs" {
    Grave "A hand shaken on the ice binds: the Court of the Ice will hold you to it, whatever was said.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hay_stairs)
      and not shook(actor, stair_bargain) and not stairsPaid(actor) and not watermenSour(actor) and state(hay_plank, across).
    Time 1 minute.
    On success { Assert shook(actor, stair_bargain). Assert state(swan_plank, lifted). Assert state(hay_plank, lifted).
      Set owedStairs(actor) to 9. }
    Result "The waterman spits on his palm and shakes, and lifts the plank. 'Nine stairs, nine pennies, and the freedom of both banks,' he says. 'Pay at the bottom or pay at the Court.'".
  }
  Action pay_stairs(actor: group, site: place) "Pay the watermen a penny a stair" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, swan_lane) or at(actor, hay_stairs) or at(actor, swan_foot) or at(actor, hay_foot) or at(actor, court))
      and not stairsPaid(actor) and owedStairs(actor) > 1 and quantity(actor, gold) >= owedStairs(actor) and not watermenSour(actor).
    Time 1 minute.
    On success { Decrease quantity(actor, gold) by owedStairs(actor). Assert stairsPaid(actor). Set owedStairs(actor) to 0.
      Assert handKept(stair_bargain). Assert state(swan_plank, lifted). Assert state(hay_plank, lifted). }
    Result "A penny a stair into the tin cup, one at a time, counted aloud by both watermen with great enjoyment. 'There,' says one. 'Now you're a freeman of the stairs. Up and down as you like, both banks, till the thaw.' It is, you suspect, the most money anyone has given them in a month.".
  }
  Action push_stairs(actor: group, site: place) "Step over the plank and go down without paying" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, swan_lane) and state(swan_plank, across)
      and not shook(actor, stair_bargain) and not watermenSour(actor).
    Time 1 minute.
    Resolve check(actor, brawn, dc_fair).
    On success { Assert watermenSour(actor). Assert state(swan_plank, lifted). Assert state(hay_plank, lifted). }
    Result "You step over the plank, and when the bigger of the two gets up to stop you, you look at him until he sits down again. Nobody shook on anything. 'Right,' he says to your back. 'Right. We'll know you.'".
    Otherwise "You step over the plank and the bigger waterman stands up and puts you back on the top step with one hand, not roughly. 'A penny a stair,' he says. 'Or the bridge, if you know the way, which you don't.'".
  }
  Rule stairs_owed at court when owedStairs(party) > 0 and hour(clock) >= 16 and firstDay() and at(party, court) and at(broom, court) and not stairsCase(party) says "The Court's waterman-clerk calls: 'Tredgold's men against a stranger, for a penny a stair, a hand shaken.' Everybody turns round to look at you. Justice Broom points her trumpet. 'Did you shake?' You did. 'Then pay,' she says, 'or tell me something I've not heard.'" {
    Assert stairsCase(party). }
  Relation stairsCase(group).
  Action argue_stairs(actor: group, site: place) "Tell the Reeve that Swan Stairs is one stair, of twelve steps, and a penny a stair is a penny" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, court) and at(broom, court) and stairsCase(actor)
      and owedStairs(actor) > 1 and not stairsArgued(actor).
    Time 2 minutes.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert stairsArgued(actor). Set owedStairs(actor) to 1. Assert broomAmused(broom). }
    On failure { Assert stairsArgued(actor). }
    Result "Justice Broom opens both eyes. 'A stair,' she says, 'being the whole flight, and the steps being steps.' She turns the trumpet on the watermen. 'Did you say a penny a step?' They did not. 'One penny,' says Broom, and bangs her trumpet on the trestle, and the benches cheer as if you had won a race. The watermen take it in good part. They will be telling it in the Hall tonight.".
    Otherwise "'A stair is a stair,' says Justice Broom, 'and a step is a stair, and I was born on Swan Stairs, and there's twelve of them.' The benches laugh at you, not unkindly. You owe twelve pennies.".
  }
  Relation broomAmused(group).
  Action pay_stairs_one(actor: group, site: place) "Pay the watermen their one penny" {
    Requires able(actor) and company(actor) and at(actor, site) and owedStairs(actor) == 1 and quantity(actor, gold) >= 1 and not stairsPaid(actor).
    Time 1 minute.
    On success { Decrease quantity(actor, gold) by 1. Assert stairsPaid(actor). Set owedStairs(actor) to 0. Assert handKept(stair_bargain). }
    Result "One penny, into the tin cup, to applause.".
  }
  // A hand not kept by the time the Court rises is a hand broken: the watermen take what is owed out of the purse in
  // front of the Reeve, and what they cannot take they cry.
  Rule stairs_broken at court when firstDay() and hour(clock) >= 17 and owedStairs(party) > 0 and not stairsPaid(party) and stairsCase(party) and not handBroken(stair_bargain) says "The Court rises. 'Unpaid,' says Justice Broom, and the watermen come and stand on either side of you, and the clerk takes what is in your purse up to the debt and drops it in the tin cup, and the rest he writes in the book. 'A hand broken on the first day,' says Broom, to nobody, with great satisfaction. 'It's going to be a good Fair.'" {
    Assert handBroken(stair_bargain). Assert stairsPaid(party). Assert brokeHand(party). Decrease quantity(party, gold) by owedStairs(party). Set owedStairs(party) to 0. }
  Relation brokeHand(group).
  // The watermen keep their word of freedom: a company that paid goes up and down both stairs as it likes.
  Rule planks_stay when stairsPaid(party) and (state(swan_plank, across) or state(hay_plank, across)) { Assert state(swan_plank, lifted). Assert state(hay_plank, lifted). }
}

Module pellam "The Liberty of the Ice" {
  Description "Links outward from Pellam: the almanack woman, who came for the Frost Fair and went on south with a card printed on the ice.".

  // ── The almanack woman ──────────────────────────────────────────────────────────────────────────────────────────
  Discovery lore_cattermole_ice "Jessamy Cattermole, who sells almanacks, had a card printed on the ice at Pellam with a ferryman's name on it, to take to a town on the Wray, and says the thaw will come in the first week of her calendar and not in anyone else's.".
  Topic lore_noll_cattermole with noll "Ask Noll Brisket about the woman with the six calendars" when true once {
    Says "'The almanack woman!' Noll does not stop the press, but he slows it, which for Noll is respect. 'Mrs Cattermole. She wanted a card with a name on it, and it was not hers, and not a sweetheart's. A ferryman, she said, at the Wray, who has hummed one tune on his stage for forty years and does not know where he had it.' He wipes the type with his thumb. 'I did it with a picture of a boat. She paid with a calendar. It has the moon right. It says the ice goes out on the fourth morning.' He looks at the sky, and at the calendar pinned inside his canvas. 'It is the only thing anyone has told me this week that I have not been sold.'".
    On discuss { Assert knows(actor, lore_cattermole_ice). }
  }
}

data/adventures/liberty-of-the-ice/marin:
Module pellam "The Liberty of the Ice" {
  Description "A mariner's wife at the head of Hay Stairs, who has had no word from the Tolleth packet since the river froze, and a letter she would have carried.".

  // ── Jennet Fosdyke, at the head of Hay Stairs ──────────────────────────────────────────────────────────────────────
  // Her want: a letter to her husband, who is mate in the Tolleth packet Dorothea, to go down to the sea by anyone who is
  // going. Her fear: that the river has stopped more than the boats, and that the packet is a thing she wrote to as a
  // habit. The lie: that she is not waiting, only passing the time at the top of the stairs. Said sparingly, because
  // she has said it to everyone on Bankside and nobody has been going that way.
  Person fosdyke "Jennet Fosdyke" at hay_stairs {
    Role "a mariner's wife, in a boat-cloak that is not hers, watching the ice from the head of Hay Stairs". Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Greets "A woman in a man's boat-cloak stands at the rail of Hay Stairs with her back to the Fair, looking the other way, downstream, where the river goes under the last arch and out of the town. 'I am not waiting,' she says, before you have asked. 'I have the air to take. It is a wonderful air.'".
    Greets again "Jennet Fosdyke does not turn from the downstream view. 'Still frozen,' she says. 'I looked.'".
  }
  Item fosdyke_letter "Jennet Fosdyke's letter to Tolleth, sealed with a thimble" is map at limbo owned by fosdyke.
  Relation fosdykeLetter(group). Relation fosdykeEased(group).
  Discovery fosdyke_packet "Jennet Fosdyke's husband is mate in the Tolleth packet, a ketch called the Dorothea, and the river has been frozen on her since the packet last called at Pellam.".

  Topic fosdyke_who with fosdyke "Ask Jennet Fosdyke what she is looking at" when true once {
    Says "'Downstream.' She pulls the cloak across. 'My man's mate in a ketch out of Tolleth, the Dorothea, Captain Bascom, salt south and oil to a rock. She used to run up to Pellam on the spring tide with a hold of herring, and he would come up these stairs two at a time and I would pretend not to have been looking.' The ice creaks. 'The river has shut since Martinmas. The packet will be in Tolleth, or at the rock, or wherever packets are. I know that. I know it the way you know your own front step.' She does not look round. 'He has not been sent for. Nobody sends for a mate.'".
    On discuss { Assert knows(actor, fosdyke_packet). }
  }
  Topic fosdyke_letter_ask with fosdyke "Ask Jennet Fosdyke whether she has a letter to go south" when knows(actor, fosdyke_packet) and not fosdykeLetter(actor) once {
    Says "She is quiet so long you think you have not been heard. Then she reaches into the cloak and brings out a letter folded small, sealed with the end of a thimble, in the way women of Bankside seal things that are not meant to be read aloud. 'Tolleth,' she says. 'The quay. There is a board there that gives her sailings in chalk, they tell me. Captain Bascom will have it for Fosdyke, and if Fosdyke is not aboard he will have it kept.' A breath. 'Do not tell Bascom what is in it. It is nothing. It is a list of what I have been doing. It is very short.' She turns, at last, and looks at you instead of the river. 'If you are going that way. I am not asking.'".
    On discuss { Give fosdyke_letter to actor. Assert fosdykeLetter(actor). }
  }

  // ── Her reaction: the company has been where the packet goes ──────────────────────────────────────────────────────
  // The rubbing of the Prefect's table and the lens of the lamp at Skerrow are brought away from the rock the Dorothea
  // lights. A company that carries either has been where Fosdyke's packet calls; she reads it from them, not from a flag.
  Topic fosdyke_news with fosdyke "Tell Jennet Fosdyke you have been to the rock where the Tolleth packet calls" when (holding(actor, pharos_rubbing) or holding(actor, pharos_lens)) and not fosdykeEased(fosdyke) once {
    Says "Her hands come out of the cloak. 'The rock,' she says. 'Skerrow. The one with the lamp that burns for nobody.' She takes a step toward you and stops, as if the ice might take it back. 'Was she in? A ketch, brown sail, a patch on the topsail the size of a door. Did you see her at the quay, or only the lamp? Did anyone,' and she hears herself and stops, and begins again in the voice for the market. 'Did anyone say how the crew did. I am not asking after one of them.' Whatever you answer, she hears it with her mouth shut and her eyes on yours. Then she nods once, twice, and the boat-cloak slides off one shoulder. 'Thank you,' she says. 'I will go in now. The stairs will keep.'".
    On discuss { Assert fosdykeEased(fosdyke). }
  }
  Observe fosdyke_light at hay_stairs when befell(remainder_steadied) and not fosdykeEased(fosdyke) "Jennet Fosdyke is at the rail with a cup of something hot she has not drunk. 'They say a lens went from a rock to a ship in a bad sea,' she says, to the river. 'A ketch's mate would know that rock. A ketch's mate would have carried it.' She stops. 'Not the lens. The news of it. He is good at news.'".
  Observe fosdyke_eased at hay_stairs when fosdykeEased(fosdyke) "The head of Hay Stairs is empty but for the bailiffs, and a cup on the rail with the ice already skinning it. Someone has written, with a finger in the snow of the rail, a short list. It is very short.".
}

data/adventures/liberty-of-the-ice/night:
Module pellam "The Liberty of the Ice" {
  // ── The second night: the flight down the Reach ───────────────────────────────────────────────────────────────────
  // A hand that is not there to stand before the Reeve at two on the last day is not landed, and goes out with the
  // river. Out of the bondhouse by the river door (the bar off from inside) or the front (the lock picked while old
  // Fowke sleeps), past the searchers, and down the sledge road south: on foot, or on Tredgold's sledges.
  Relation hiredOut(place). Relation hiredFled(place). Relation flightCaught(place).
  Query flightHour() means dark() and (firstDay() or secondDay()).
  Person fowke "old Fowke" at limbo {
    Role "a night-watchman on Hay Wharf, with a brazier and a bottle". Ancestry human. Peaceable. Pronouns he. Manner grim.
    Greets "Old Fowke lifts his lantern into your face. 'Wharf's shut,' he says. 'Everything's shut. Go to bed.'".
  }
  Topic fowke_wharf with fowke "Ask old Fowke what he is watching for" when not asleep(fowke) once {
    Says "'Wool,' says Fowke. 'Master Harker's wool, and rats, and whatever's none of your business.' He drinks. 'There's coughing in there some nights. Rats cough, in a frost. Go to bed.'".
  }
  Initially Assert serves(fowke, harker).
  Rule fowke_on when (hour(clock) >= 21 or hour(clock) < 7) and not at(fowke, hay_wharf) { Assert at(fowke, hay_wharf). }
  Rule fowke_off when hour(clock) >= 7 and hour(clock) < 21 and not at(fowke, limbo) { Assert at(fowke, limbo). Retract asleep(fowke). }
  // From one until four the bottle has the better of him.
  Rule fowke_sleeps when hour(clock) >= 1 and hour(clock) < 4 and at(fowke, hay_wharf) and not asleep(fowke) { Assert asleep(fowke). }
  Rule fowke_wakes when (hour(clock) < 1 or hour(clock) >= 4) and asleep(fowke) and not sodden(fowke) { Retract asleep(fowke). }
  Observe fowke_scene at hay_wharf when at(fowke, hay_wharf) and not asleep(fowke) "Old Fowke sits by the bondhouse door on a keg with a brazier and a bottle, and a lantern at his feet.".
  Observe fowke_asleep at hay_wharf when at(fowke, hay_wharf) and asleep(fowke) "Old Fowke is asleep on his keg by the bondhouse door, his chin on his chest, the bottle in his lap, snoring.".
  // Picking the lock in front of a waking watchman is seen.
  Rule fowke_sees when state(bond_lock, open) and at(party, hay_wharf) and perceives(fowke, party) and not fowkeCried(fowke) says "Old Fowke comes up off his keg with his lantern held high and his mouth open, and bawls for the searchers, and does not stop." {
    Assert fowkeCried(fowke). Assert harkerWary(harker). Assert state(bond_lock, locked). }
  Relation fowkeCried(group).

  // The hired, told, come out with the company: from the floor onto the ice by the river door, or onto the wharf by
  // the front.
  Action lead_out_river(actor: group, site: place) "Bring the hired out through the river door onto the ice" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bond_floor) and tansyTold(tansy) and state(river_bar, unbarred)
      and at(hired, bond_floor) and flightHour() and not hiredOut(lisk).
    Time 2.
    On success { Assert hiredOut(lisk). Assert at(actor, hay_foot). Assert at(hired, hay_foot). Assert at(tansy, hay_foot). Retract inBondhouse(actor). }
    Result "One at a time, through the low door in the river-wall, crouching, onto the ice under the wharf, in the dark: Tansy Hobb first with her pail clutched to her, and the big lad with the whip last. Nobody speaks. Above you on the wharf, old Fowke's brazier glows. The ice under the piles is black and ridged and nobody has walked on it since it froze.".
  }
  Action lead_out_front(actor: group, site: place) "Bring the hired out of the bondhouse by the front door, past old Fowke asleep" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bond_floor) and tansyTold(tansy) and state(bond_lock, open)
      and at(hired, bond_floor) and flightHour() and (asleep(fowke) or not at(fowke, hay_wharf)) and not hiredOut(lisk).
    Time 2.
    On success { Assert hiredOut(lisk). Assert at(actor, hay_foot). Assert at(hired, hay_foot). Assert at(tansy, hay_foot). }
    Result "Past old Fowke on his keg, snoring, one at a time, holding your breath; along the wharf; down Hay Stairs onto the ice, twenty people in the dark trying not to let the treads creak. Fowke stirs once and says something to his bottle, and does not wake.".
  }
  // Out under the wharf, the wharf men on Hay Wharf above hear twenty people on the ice, unless they come out quietly.
  Relation quietOut(place). Relation heardOut(place).
  Action hush_hired(actor: group, site: place) "Keep the hired still and silent under the wharf until the wharf men above have gone by" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hay_foot) and hiredOut(lisk) and not hiredFled(lisk) and not quietOut(lisk) and not heardOut(lisk) and at(searchers, hay_wharf).
    Time 2 minutes.
    Resolve check(actor, stealth, dc_fair).
    On success { Assert quietOut(lisk). }
    On failure { Assert heardOut(lisk). }
    Result "Twenty people crouched in the dark under the piles, breathing into their blankets, while boots go along the planks overhead and a lantern swings and a dog snuffs at the edge of the wharf and goes away. Then nothing. Then the brazier crackling, far up.".
    Otherwise "Somebody's pail clanks on the ice. Overhead the boots stop.".
  }
  Rule wharf_hears when hiredOut(lisk) and not hiredFled(lisk) and not quietOut(lisk) and at(searchers, hay_wharf) and at(party, hay_foot) and tolerates(searchers, party) and (heardOut(lisk) or outWatches(lisk) >= 2)
    says "Up on the wharf a lantern swings over the edge, and a voice shouts, 'Harker's hired! On the ice, under the wharf!' and boots come thundering down Hay Stairs, and a dog." {
    Retract tolerates(searchers, party). Assert at(searchers, hay_foot). Assert assails(searchers, party). }
  Measure outWatches(place).
  Rule out_counts when hiredOut(lisk) and not hiredFled(lisk) and at(party, hay_foot) and not quietOut(lisk) { Increase outWatches(lisk) by 1. }
  // The hired keep with the company on the ice once out, and anyone drowned in hiding comes with them.
  Rule hired_keep when hiredOut(lisk) and not hiredFled(lisk) and not flightCaught(lisk) and at(party, ?p) and iceRoom(?p) and not at(hired, ?p) { Assert at(hired, ?p). Assert at(tansy, ?p). }
  Rule dickon_joins when hiredOut(lisk) and dickonPlanned(dickon) and not dickonTaken(dickon) and not hiredFled(lisk) and at(party, ?p) and iceRoom(?p) and not at(dickon, ?p) { Assert at(dickon, ?p). Assert at(jem, ?p). }
  Observe hired_with at hay_foot when hiredOut(lisk) and not hiredFled(lisk) and at(hired, hay_foot) "Twenty of Harker's hired stand round you on the ice in the dark, in their blankets, shivering, waiting to be told where.".
  // Beaten by the searchers, the company is not killed (they are paid by the night, not by the head): it comes round
  // on the bondhouse straw, the bar back on the river door, and the hired with it.
  Rule caught_by_searchers when captured(searchers, party)
    says "You come round on straw, in the dark, with your head ringing and your hands tied in front of you: the bondhouse floor. Somebody has put the oak bar back on the river door and hammered it into its brackets. Round you in the dark Harker's hired are breathing, and Tansy Hobb is holding a wet rag to your forehead." {
    Retract captured(searchers, party). Assert at(party, bond_floor). Assert inBondhouse(party). Assert state(river_bar, barred).
    Assert tolerates(searchers, party). Retract assails(searchers, party). Assert harkerWary(harker). }
  Rule caught_hired_back when inBondhouse(party) and hiredOut(lisk) and not hiredFled(lisk) {
    Retract hiredOut(lisk). Assert at(hired, bond_floor). Assert at(tansy, bond_floor). Assert at(searchers, hay_wharf). Retract quietOut(lisk). Retract heardOut(lisk). Set outWatches(lisk) to 0. }
  // On the sledges: from the foot of Hay Stairs, straight down the Reach, faster than anyone on foot.
  Action sledges_go(actor: group, site: place) "Put the hired on Tredgold's sledges and go, down the Reach and away south" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hay_foot) and hiredOut(lisk) and sledgesReady(lisk) and at(tredgold, hay_foot)
      and not hiredFled(lisk) and not channelCut(lisk).
    Time 6.
    On success { Assert hiredFled(lisk). Assert at(actor, sledge_road). Assert at(hired, limbo). Assert at(tansy, limbo). Assert tansyFree(tansy). Assert dickonGone(dickon).
      Assert at(dickon, limbo). Assert at(jem, limbo). Assert at(polly, limbo). Assert pollyGone(polly). Assert at(tredgold, watermen_room).
      Assert tolerates(wolves, actor). }
    Result "Four sledges, eight watermen running in the traces, twenty people under blankets, and the whole of the Reach going by grey and fast in the starlight. Behind you, far back, lanterns, and a dog barking, and a voice shouting; and then nothing, because a man on foot cannot catch a sledge on the ice. At the bottom of the Reach where the river widens the watermen stop, blowing, and the hired get down, and Dickon Cobb, or Tansy Hobb, or nobody, points south down the white road toward the downs. They go. You watch them until they are a line of dots, and then not even that. Tredgold spits on the ice. 'There,' he says. 'Not landed.' It is a long walk back.".
  }
  // On foot: down the Reach past the searchers, if they are there.
  Rule caught_on_reach when hiredOut(lisk) and not hiredFled(lisk) and at(party, black_reach) and at(searchers, black_reach) and able(searchers) and not routed(searchers) and tolerates(searchers, party)
    says "The three lanterns swing round together. 'There!' The dog is off its rope. 'Harker's hired, on the Reach, and someone with them!' The searchers come over the grey ice at you with their cudgels." {
    Retract tolerates(searchers, party). Assert assails(searchers, party). }
  Action walk_south(actor: group, site: place) "Send the hired on down the sledge road south, on foot, toward the downs" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, sledge_road) and hiredOut(lisk) and not hiredFled(lisk) and not channelCut(lisk)
      and (not at(wolves, sledge_road) or not able(wolves) or tolerates(wolves, actor)).
    Time 2.
    On success { Assert hiredFled(lisk). Assert at(hired, limbo). Assert at(tansy, limbo). Assert tansyFree(tansy). Assert dickonGone(dickon).
      Assert at(dickon, limbo). Assert at(jem, limbo). Assert at(polly, limbo). Assert pollyGone(polly). }
    Result "They go away from you down the sledge road on foot in a long line, south toward the downs and the snow, holding each other's coats, Tansy Hobb looking back once. Nobody behind you. The Reach is grey and empty and enormous. By the time it is light they will be off the river and into the snow of the downs, where the roads are shut, and where nobody from Pellam can follow them until the thaw, and by then they will not be landed, and not anyone's.".
  }
  // If the channel is cut, the sledge road south ends at black water, and the hired go back.
  Rule channel_turns when hiredOut(lisk) and not hiredFled(lisk) and channelCut(lisk) and at(party, sledge_road) and not flightCaught(lisk)
    says "The sledge road ends at the watermen's channel, forty feet of black water steaming in the starlight, from bank to bank. Nobody goes south on the ice tonight. Behind you the hired stand in their blankets and look at it, and then at you." { Assert channelBlocked(lisk). }
  Relation channelBlocked(place).
  // Out on the ice at dawn, the hired are found, and walked back to the bondhouse.
  Rule flight_fails when hiredOut(lisk) and not hiredFled(lisk) and thirdDay() and hour(clock) >= 6 and not flightCaught(lisk)
    says "Day comes up grey over the Reach and finds Harker's hired on the open ice in their blankets, and the searchers find them soon after, and walk them back up Hay Stairs to the bondhouse, to be landed at two." {
    Assert flightCaught(lisk). Assert at(hired, bond_floor). Assert at(tansy, bond_floor). Assert harkerWary(harker). }
  // Dickon goes south himself on the second night with whoever is hidden, if nobody brings him the bondhouse.
  Rule dickon_leaves when secondDay() and hour(clock) == 3 and not dickonTaken(dickon) and not dickonGone(dickon) and not hiredOut(lisk) and not channelCut(lisk)
    {
    Assert dickonGone(dickon). Assert at(dickon, limbo). Assert at(jem, limbo). Assert at(polly, limbo). Assert pollyGone(polly). }
}

data/adventures/liberty-of-the-ice/place:
Module pellam "The Liberty of the Ice" {
  // The country beyond a march of a generated world: the company that comes in by the North Road is the world's own.
  Entity party: group "Your company".
  // What is said of Pellam in the country behind it: once the ice has gone out the Frost Fair is old news there, told by how the three days came out.
  Entity word: fact "What is said of the Lisk in the country behind it.".
  Entity word_sold: fact "What is said there of the hired hands sold out of the town.".
  Entity word_unsworn: fact "What is said there of the preacher and the Court's book.".
  Entity word_fled: fact "What is said there of the hired who ran.".
  Rule word_old when thawed(lisk) and not stale(word) { Assert stale(word). }
  Rule word_sold_old when drownedSold(party) and not stale(word_sold) { Assert stale(word_sold). }
  Rule word_unsworn_old when unsworn(lisk) and not stale(word_unsworn) { Assert stale(word_unsworn). }
  Rule word_fled_old when hiredFled(lisk) and not stale(word_fled) { Assert stale(word_fled). }
}

data/adventures/liberty-of-the-ice/quarl:
Module pellam "The Liberty of the Ice" {
  // ── The Perpetual Frost Company ───────────────────────────────────────────────────────────────────────────────────
  // Mr. Ambrose Quarle, natural philosopher, sincerely believes the Lisk can be kept frozen for ever by his patent
  // freezing salts, and is selling shares at five coin in a Company to do it. He is not a fraud: salt on ice will
  // freeze a tub of water solid in an hour. A tub is not a river. Half the Wool Exchange has bought, and Harker
  // heavily, on credit, against the price of fleece.
  Person quarle "Mr. Ambrose Quarle" at freezeland_low {
    Role "a natural philosopher in a scorched coat, with a tub". Ancestry human. Calling mage. Level 2. Peaceable. Pronouns he. Manner cheerful.
    Greets "'Sir! Madam! Friend! Observe!' Mr. Quarle seizes your sleeve and points into his tub. 'Water. Common Lisk water, from the hole by the bridge. And in an hour, by my patent salts, ice. Ice! In a tub! On ice!' He beams. 'Imagine it on a river.'".
    Greets again "'Ah! Observe!' says Mr. Quarle, and points into his tub.".
  }
  Rule quarle_day when hour(clock) >= 9 and hour(clock) < 16 and not iceGone() and not quarleRuined(quarle) and not at(quarle, freezeland_low) { Assert at(quarle, freezeland_low). }
  Rule quarle_exchange when hour(clock) >= 16 and hour(clock) < 19 and not quarleRuined(quarle) and not at(quarle, exchange_floor) { Assert at(quarle, exchange_floor). }
  Rule quarle_night when (hour(clock) >= 19 or hour(clock) < 9) and not at(quarle, calf_taproom) { Assert at(quarle, calf_taproom). }
  Relation quarleRuined(group). Relation frostCrashed(place). Relation quarleCream(group). Relation shareBought(group).
  Observe tub_scene at freezeland_low when at(quarle, freezeland_low) and not quarleCream(quarle) "By the printing booth a man in a scorched coat has set up a trestle and a wooden tub, and a board: THE PERPETUAL FROST COMPANY. SHARES FIVE COIN. THE RIVER KEPT FOR EVER. A small crowd watches the tub, in which, very slowly, as they watch, a skin of ice is forming on the water.".
  Observe cream_scene at freezeland_low when at(quarle, freezeland_low) and quarleCream(quarle) "Mr. Quarle's tub has a new board: QUARLE'S FROST-CREAM, A PENNY. A queue of children reaches to the Frozen Lamb.".
  Topic quarle_salts with quarle "Ask Mr. Quarle how his salts work" when true once {
    Says "'Ah.' He lowers his voice, as to a fellow initiate. 'Common salt, and saltpetre, and a third thing, which is my secret, packed about a vessel on the ice. The cold is drawn out of the ice into the salt, and out of the water into the cold, and the water freezes.' He taps the tub. 'If a tub, why not a river? It is only a question of salt, and men, and capital. I need men to cut and pack the ice; nobody will cut ice in a frost. I need capital: hence the Company.' He beams. 'Half the Exchange is in. Master Harker has taken two hundred shares.'".
    On discuss { Assert knows(actor, quarle_needs). Assert knows(actor, harker_shares). }
  }
  Discovery quarle_needs "Mr. Quarle needs men to cut and pack ice for his Perpetual Frost Company, and nobody will cut ice in a frost.".
  Discovery harker_shares "Master Harker has taken two hundred shares in Mr. Quarle's Perpetual Frost Company, on credit, against the price of fleece at the thaw.".
  Kind share_kind "a share in the Perpetual Frost Company" is gear worth 0 weighing 0 described "An engraved certificate, very handsome: THE PERPETUAL FROST COMPANY, ONE SHARE, with a picture of the Lisk frozen under a smiling sun, and Ambrose Quarle's signature, which is larger than the sun.".
  Item share "a share in the Perpetual Frost Company" is share_kind at limbo.
  Action buy_share(actor: group, site: place) "Buy a share in the Perpetual Frost Company, for five coin" {
    Requires able(actor) and company(actor) and at(actor, site) and at(quarle, site) and quantity(actor, gold) >= 5 and not shareBought(actor) and not frostCrashed(lisk).
    Time 2 minutes.
    On success { Decrease quantity(actor, gold) by 5. Increase quantity(quarle, gold) by 5. Assert shareBought(actor). Retract at(share, limbo). Assert at(share, site). }
    Result "Mr. Quarle signs your share with a flourish that goes off the edge of the paper. 'You will tell your grandchildren,' he says, 'that you were in at the beginning of the end of thaws.'".
  }
  // At the Exchange, in front of the factors: why a tub is not a river.
  Observe exchange_scene at exchange_floor when not visitedBefore(exchange_floor) "The Wool Exchange: a hall of pillars and a floor marked out in chalk, and on the floor forty factors in fur collars buying and selling, very loudly, fleece that is still on sheep they have never seen, for delivery at a shearing that has not come, at a price that will be decided by a thaw nobody can name. Slates on the wall chalk the price of Swale grey, Fell white and the Perpetual Frost Company, which is rising.".
  Observe exchange_again at exchange_floor when visitedBefore(exchange_floor) "The Wool Exchange: fur collars, chalk, the slates. The Perpetual Frost Company is still rising.".
  Observe exchange_crashed at exchange_floor when frostCrashed(lisk) "On the slates of the Exchange the Perpetual Frost Company has been rubbed out and chalked in again lower four times, and then rubbed out. Factors stand about in groups not looking at each other.".
  Action expose_frost(actor: group, site: place) "Explain to the Exchange, before Mr. Quarle, why a tub on the ice is not a river" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, exchange_floor) and at(quarle, exchange_floor) and knows(actor, quarle_needs) and not frostCrashed(lisk) and not exposeTried(actor).
    Time 2.
    Resolve check(actor, lore, dc_fair).
    On success { Assert frostCrashed(lisk). Assert exposeTried(actor). Assert harkerShort(harker). }
    On failure { Assert exposeTried(actor). }
    Result "You do it with chalk, on the Exchange floor, in front of forty factors and Mr. Quarle: the ice gives its cold to the salt; the salt is used up; a tub has a bottom and sides and a river has the sea at one end and the hills at the other, and the whole of the summer coming down it. You would need, you work out on the floor, more salt than there is in the country, every day, for ever. There is a silence. Then the first factor goes to the slates with a cloth. By dusk the Perpetual Frost Company is worth nothing, and Master Harker, they say on the Exchange, is two hundred shares and a great deal of credit the poorer, and short of coin.".
    Otherwise "You try, with chalk, and get the sums tangled, and Mr. Quarle very kindly corrects you, and the factors laugh, and the Company goes up a penny.".
  }
  Relation exposeTried(group). Relation harkerShort(group).
  // Mr. Quarle, ruined or not, can be shown what his salts are good for.
  Action quarle_ices(actor: group, site: place) "Tell Mr. Quarle that what his salts would freeze best is cream, with honey in it" {
    Requires able(actor) and company(actor) and at(actor, site) and at(quarle, site) and knows(actor, quarle_needs) and not quarleCream(quarle)
      and (craft(actor, craft_trade) or craft(actor, craft_learning) or frostCrashed(lisk) or carries(actor, honey)).
    Time 1.
    On success { Assert quarleCream(quarle). Retract quarleRuined(quarle). }
    Result "He looks from you to the tub, and back, as a man looks from a creditor to a door. Then he goes to the Frozen Lamb and comes back with a jug of cream from Bel, and a spoon, and some honey, and packs the salts round a pewter pot, and turns it, and turns it, muttering. An hour later he gives you the first spoonful, in the cold, on the ice. It is the best thing you have ever eaten. 'It is not perpetual,' says Mr. Quarle sadly, licking the spoon. 'It does not last at all.' He brightens. 'That is rather the point of it, I think.'".
  }
  Rule quarle_ruined when frostCrashed(lisk) and not quarleCream(quarle) and not quarleRuined(quarle) { Assert quarleRuined(quarle). }
  Observe quarle_sad near quarle when quarleRuined(quarle) "Mr. Quarle sits by his tub with his board turned face down, watching the water freeze, very slowly, as if it were the only thing in the world that had never let him down.".
  // Watermen set to cutting ice for him: work, which keeps the saws off the Reach.
  Observe quarle_men at freezeland_low when quarleHasMen(quarle) and at(quarle, freezeland_low) and not quarleCream(quarle) "Half a dozen young watermen are cutting blocks of ice out of the river by the printing booth with their great saws and packing them in straw for Mr. Quarle, singing, and getting paid for it.".

  // What he says afterwards, and to whoever bought a share: he is sincere, and the page should let him go on being so.
  Topic quarle_share_held with quarle "Show Mr. Quarle your share" when shareBought(actor) and not quarleRuined(quarle) and not quarleCream(quarle) once {
    Says "He takes the certificate in both hands and holds it away from his chest, as one holds a baby that is going to be sick. 'Number four hundred and nine,' says Mr. Quarle, with love. 'The sun on it was my wife's notion. She said a company should look as if it was expecting weather.' He gives it back with a small bow. 'You are a partner. You will be sent the minutes. There are no minutes. I shall write some.'".
  }
  Topic quarle_ruined_talk with quarle "Ask Mr. Quarle how he does" when quarleRuined(quarle) once {
    Says "'Observe,' says Mr. Quarle, without conviction, and points into the tub. The skin of ice has formed, as it always does, in an hour, and it is as perfect as the day he began. 'It is quite true, you know. All of it. A tub freezes.' He looks across the ice at the Exchange, and then back. 'Someone drew me a river on the floor with chalk and I could not find the error. I have been looking for it since. That is the worst of it. I cannot find it.'".
  }
  Topic quarle_cream_talk with quarle "Ask Mr. Quarle how the frost-cream goes" when quarleCream(quarle) once {
    Says "He is packing salt round a pewter pot with his sleeves turned back, and does not stop. 'Four hundred pennies by Tuesday,' says Mr. Quarle, 'and every one of them a child who will remember that Pellam had ice at the right season.' He beams at the pot. 'I used to think of the river, you know. All of that water, all of that cold. Now I think of a boy with his tongue out. It is a smaller thing. It stays done.'".
  }
}

data/adventures/liberty-of-the-ice/suppe:
Module pellam "The Liberty of the Ice" {
  // ── Supper at Fleece Row ──────────────────────────────────────────────────────────────────────────────────────────
  // Believed, the Squire sups with Harker. Harker names his terms: sixty coin for the two hundred, half in hand when
  // they shake on the ice, half at the Landing, when it is landed. A bargain landed binds the Squire to deliver two
  // hundred ewes at the shearing, in any court of the country; a bargain unlanded goes out with the river. Harker
  // means to have it landed. The Squire means to be over the bridge with the half before two on the last day.
  Entity flock_bargain: bargain "two hundred fell ewes at Hawsfold, with Master Harker".
  Relation supped(group). Relation termsHeard(group). Relation indenturesOffered(group). Relation earnestTaken(group).
  Relation indenturesTraded(group). Relation flockShook(group). Relation stockShown(group).
  Event supper_scene at harker_parlour when at(party, harker_parlour) and invited(party) and hour(clock) >= 18 and hour(clock) < 22 and at(harker, harker_parlour) and not squireExposed(party) "Supper at Fleece Row: the long table, too much silver, a goose, Master Harker carving with great care and very small slices, the alderman Gosling at his left hand talking about poetry to nobody, and Thessaly Harker at the foot of the table in grey, saying nothing and watching you over her glass the whole meal with an expression of the greatest interest." then {
    Assert supped(party). }
  Topic harker_terms with harker "Talk terms for the Hawsfold flock with Master Harker" when squireBelieved(harker) and not termsHeard(actor) once {
    Says "'Sixty coin for the two hundred, at the shearing, at the fold, by the head.' He says it as if he were saying grace. 'Thirty in hand when we shake, on the ice, under the Glove, as the custom is. Thirty at the Landing, when it is landed before the Reeve, hand to hand.' He smiles at you down the table. 'I always have my bargains landed. A gentleman like yourself will understand. One cannot be too careful, on the ice.'".
    On discuss { Assert termsHeard(actor). Assert knows(actor, harker_terms_known). }
  }
  Discovery harker_terms_known "Master Harker will pay sixty coin for the Hawsfold flock: thirty in hand when he and the Squire shake on the ice, thirty at the Landing, once it is landed before the Reeve, hand to hand.".
  // The long con: the Squire needs shepherds for the fold, and Harker has a bondhouse full.
  Topic harker_shepherds with harker "Tell Master Harker that Hawsfold wants hands, and the Squire would take some of his hired against the price" when termsHeard(actor) and (knows(actor, tansy_hired) or knows(actor, hired_sold)) and not indenturesOffered(actor) once {
    Says "He puts down the carving knife. 'Indentures,' he says, softly, as if it were the name of a woman. 'Landed, a year's service, good in any court.' He thinks, behind his eyes, very fast: Gallowmoor pays eight a head, and the thaw will come, and the hay is dear, and here is a squire. 'I have twenty in the bondhouse,' he says. 'Strong. I could let the Squire have the whole bondhouse against the flock, and not a coin passed, if the Squire liked. They would be landed to you at the Landing with the flock to me.' He picks up the knife again. 'A Christian arrangement. The fells want hands.'".
    On discuss { Assert indenturesOffered(actor). }
  }
  // Short of coin after the Exchange, he offers it himself.
  Rule harker_short_offers when harkerShort(harker) and termsHeard(party) and together(party, harker) and not indenturesOffered(party) and squireBelieved(harker)
    says "'I must be frank with you,' says Master Harker, which he has never been with anyone. 'Quarle's business has tied up my coin. But I am rich in hands. I have twenty indentures in the bondhouse, landed at the Landing, good in any court; the Squire might take them against the flock, and Hawsfold have shepherds for a year.'" {
    Assert indenturesOffered(party). }
  // He shows a buyer his stock, after supper: he is proud of it.
  Action see_stock(actor: group, site: place) "Ask Master Harker to show you his hired, as a man who may buy" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, harker_parlour) and at(harker, harker_parlour) and squireBelieved(harker) and indenturesOffered(actor)
      and not stockShown(actor) and hour(clock) >= 19 and hour(clock) < 22.
    Time 3.
    On success { Assert stockShown(actor). Assert showingStock(harker). Assert at(actor, bond_floor). Assert at(harker, bond_floor). Assert state(bond_lock, open). }
    Result "He takes you himself, with a lantern, down Fleece Row and over the bridge and along Hay Wharf in the frost, talking all the way about the virtue of work; and Kemble unlocks the bondhouse for him, and he walks you down the straw among his hired with the lantern held up, so you can see their faces, the way a man shows a horse's teeth. 'Strong,' he says. 'Willing. Every one shook of their own free will.' Tansy Hobb is there, with her pail, looking at you.".
  }
  Rule stock_returns when showingStock(harker) and (hour(clock) >= 22 or hour(clock) < 6) and (at(party, bond_floor) or at(party, bond_loft)) and not inBondhouse(party) says "'Late,' says Master Harker, 'late,' and walks you back out onto Hay Wharf, and Kemble locks the door behind you." { Assert at(party, hay_wharf). }
  Rule stock_ends when showingStock(harker) and (hour(clock) >= 22 or hour(clock) < 6) { Retract showingStock(harker). Assert state(bond_lock, locked). Assert at(harker, limbo). }

  // ── The handshake on the flock, under the Glove ───────────────────────────────────────────────────────────────────
  Action shake_flock_coin(actor: group, site: place) "Walk down to the Glove Post with Master Harker and shake on the flock, for thirty coin in hand" {
    Grave "A hand shaken on the ice binds: shake on the flock, and if it is landed you owe Master Harker two hundred ewes at the shearing, in any court in the country.".
    Requires able(actor) and company(actor) and at(actor, site) and at(harker, site) and termsHeard(actor) and squireBelieved(harker) and not flockShook(actor)
      and hour(clock) >= 8 and hour(clock) < 21 and not iceGone() and not landingAt(lisk) and not harkerShort(harker).
    Time 3.
    On success { Assert flockShook(actor). Assert shook(actor, flock_bargain). Assert earnestTaken(actor). Increase quantity(actor, gold) by 30. Decrease quantity(harker, gold) by 30.
      Assert at(actor, freezeland). Assert at(harker, freezeland). }
    Result "Down to the ice together, the factor and the Squire, and through the Fair to the Glove Post, where a little crowd gathers because it knows what it is about to see. Master Harker takes off his glove. You take off yours. He puts out his palm, open, and waits; and for the first time in Pellam's memory, someone tells you afterwards, Josias Harker puts out his hand first. You shake. Kemble counts thirty coin into your palm in front of everyone, and writes it in his book. 'At the Landing, then,' says Harker, 'the other thirty.' He smiles. 'I'll look for you.'".
  }
  Entity indenture_bargain: bargain "twenty indentures, against the flock, with Master Harker".
  Kind indentures_kind "twenty indentures" is gear worth 0 weighing 0 described "Twenty indentures of hiring in Kemble's hand, each with its little drawn hand for shaken, made over by Josias Harker to the Squire of Hawsfold against two hundred fell ewes. Tansy Hobb's is on top.".
  Item indentures "twenty indentures" is indentures_kind at limbo.
  Action shake_flock_hands(actor: group, site: place) "Walk down to the Glove Post with Master Harker and shake on the flock, for the twenty indentures" {
    Grave "A hand shaken on the ice binds: shake on the flock, and if it is landed you owe Master Harker two hundred ewes at the shearing, in any court in the country; and the twenty hired are landed to you.".
    Requires able(actor) and company(actor) and at(actor, site) and at(harker, site) and indenturesOffered(actor) and squireBelieved(harker) and not flockShook(actor)
      and hour(clock) >= 8 and hour(clock) < 21 and not iceGone() and not landingAt(lisk).
    Time 3.
    On success { Assert flockShook(actor). Assert shook(actor, flock_bargain). Assert indenturesTraded(actor). Assert shook(actor, indenture_bargain).
      Retract at(indentures, limbo). Assert at(indentures, freezeland). Assert at(actor, freezeland). Assert at(harker, freezeland). }
    Result "At the Glove Post, before a little crowd, Master Harker puts out his palm and waits, and you shake. Kemble hands you twenty folded indentures tied with a black tape. Tansy Hobb's is on top. 'Landed at two, the last day,' says Harker, 'the hands to you and the flock to me.' He is pleased with himself; he has sold eight-coin hands for a flock worth sixty. 'A Christian arrangement,' he says again.".
  }
  // Ursel, not trusted or lied to, takes the money and goes.
  Rule ursel_takes when earnestTaken(party) and travelsWith(ursel, party) and (liedToUrsel(party) or urselTrust(ursel) < 1) and not urselTook(party)
    says "At the Glove Post, in the crush after the handshake, someone knocks into you and says 'Beg pardon, my love,' and when you put your hand to your purse it is lighter by thirty coin, and Ursel Cobb is not beside you, or anywhere. Pinned inside your coat, where the purse was, is a twist of paper: NEVER SHOOK ON IT. — U.C." {
    Assert urselTook(party). Decrease quantity(party, gold) by 30. Retract travelsWith(ursel, party). Assert urselGone(ursel). Assert at(ursel, limbo). }
  // With the bargain shaken and not landed, Harker means to have the Squire at the Landing: one of his wharf men sits at
  // the North Bar from the handshake on, and at one on the last day his men look for the Squire everywhere in Pellam
  // but the Clink.
  Person bar_man "one of Harker's wharf men" at limbo {
    Role "one of Harker's wharf men, on a keg at the North Bar, watching the road out". Ancestry human. Peaceable. Pronouns he. Manner grim.
    Greets "The wharf man touches his cap to you. 'Squire,' he says, and does not get off his keg.".
  }
  Initially Assert serves(bar_man, harker).
  Rule bar_watched when flockShook(party) and not landed(flock_bargain) and not iceGone() and not landingDone(lisk) and not at(bar_man, north_bar) { Assert at(bar_man, north_bar). }
  Rule bar_unwatched when (iceGone() or landingDone(lisk)) and not at(bar_man, limbo) { Assert at(bar_man, limbo). }
  Observe bar_man_scene at north_bar when at(bar_man, north_bar) "One of Harker's wharf men sits on a keg under the North Bar with his hands in his armpits, watching the road out of Pellam, the way a cat watches a hole.".
  Thing bar_watch "Harker's man at the North Bar" on north_way is scenery {
    State clear "The North Road goes up out of Pellam into the snow.".
    State watched blocking "One of Harker's wharf men sits on a keg in the middle of the North Bar's gateway with his cudgel across his knees. 'Squire,' he says, touching his cap. 'Master Harker's compliments. He'd take it unkindly if the Squire went up the fells before the Landing.'".
  }
  Initially Assert state(bar_watch, clear).
  Rule bar_watch_on when at(bar_man, north_bar) and state(bar_watch, clear) { Assert state(bar_watch, watched). }
  Rule bar_watch_off when not at(bar_man, north_bar) and state(bar_watch, watched) { Assert state(bar_watch, clear). }
  Action slip_bar(actor: group, site: place) "Go out by the North Bar on the far side of a hay-sledge, where Harker's man is not looking" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, north_bar) and at(bar_man, north_bar) and flockShook(actor) and not barSlipped(actor) and not barTried(actor) and not dark().
    Time 3.
    Resolve check(actor, stealth, dc_fair).
    On success { Assert barSlipped(actor). Assert at(actor, north_road). }
    On failure { Assert barTried(actor). }
    Result "A hay-sledge goes out through the North Bar with a farmer walking at its horse's head, and you walk on the far side of it, close, matching its pace, and at the Bar Harker's man is looking at the farmer, and then you are on the North Road in the snow, and nobody calls after you.".
    Otherwise "You walk out beside a hay-sledge, and at the Bar the horse shies, and Harker's man looks round, and sees you, and grins. 'Squire,' he says. Not today.".
  }
  Action lie_bar(actor: group, site: place) "Tell Harker's man the Squire is only going up to the first farm, to send word to Hawsfold about the shearing" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, north_bar) and at(bar_man, north_bar) and flockShook(actor) and not barSlipped(actor) and not barLied(actor).
    Time 2 minutes.
    Resolve check(actor, deception, dc_hard).
    On success { Assert barSlipped(actor). Assert at(actor, north_road). }
    On failure { Assert barLied(actor). }
    Result "'To the first farm,' he says, 'and back by dark.' He thinks about it with his whole face. 'Right you are, Squire. I'll tell Master Harker.' He sits down again on his keg. You walk up the North Road into the snow, and do not look back, and do not come back by dark.".
    Otherwise "'Master Harker said you'd say something like that,' says the wharf man, almost admiringly. 'Not today, Squire.'".
  }
  Relation barSlipped(group). Relation barTried(group). Relation barLied(group). Relation squireFetched(group).
  Rule squire_fetched_landing when squireFetched(party) and landingAt(lisk) and not at(party, freezeland) and not at(party, clink_yard) and inPellam() { Assert at(party, freezeland). }
  Rule squire_sought when thirdDay() and hour(clock) >= 13 and flockShook(party) and not landed(flock_bargain) and inPellam() and not at(party, clink_yard) and not squireFetched(party) and not landingDone(lisk)
    says "Two of Harker's wharf men find you. 'The Squire of Hawsfold,' says one, touching his cap. 'Master Harker's compliments, and he'll see you at the Landing.' They do not go away." {
    Assert squireFetched(party). }
  Relation landingDone(place).
}

Module pellam "The Liberty of the Ice" {
  // ── The thaw ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // All the last day the ice talks. At six the booths come down; at nine the crier cries everyone off; at eleven (at
  // eight, if the watermen cut their channel) the ice goes out from the Reach upward with a noise like the end of the
  // world, and by midnight there is a river. Whatever was not landed goes with it.
  Rule ice_talks when thirdDay() and hour(clock) >= 15 and not spread(ice_talking) and inPellam() says "Under your feet, all over Pellam, the ice has begun to talk: a long creak like a ship's timbers, a crack like a gun a long way off, and then a groan that goes on and on, up the whole length of the river. On the ice everybody stops and listens, and laughs, too loudly, and goes on." { Assert spread(ice_talking). }
  Entity ice_talking: fact "The ice talking".
  Query thawHour() means (thirdDay() and (hour(clock) >= 23 or hour(clock) < 6)) or fourthDay()
    or (channelCut(lisk) and thirdDay() and (hour(clock) >= 20 or hour(clock) < 6)).
  Query offIceHour() means (thirdDay() and (hour(clock) >= 21 or hour(clock) < 6)) or fourthDay()
    or (channelCut(lisk) and thirdDay() and (hour(clock) >= 18 or hour(clock) < 6)).
  Rule booths_struck when thirdDay() and hour(clock) >= 18 and not spread(booths_down) and not iceGone() and inPellam() says "The booths of Freezeland Street are coming down: sailcloth folded, oars carried up Swan Stairs on men's shoulders, the ox's bones dragged off on a sledge. The ice is grey under them, and wet." { Assert spread(booths_down). }
  Entity booths_down: fact "The booths struck".
  Rule crier_off at freezeland when offIceHour() and not iceGone() and not spread(crier_off_fact) says "The crier, for the last time, on his barrel at the Glove Post: 'O yes! O yes! O yes! Off the ice! Off the ice, every soul, the Liberty is ended! God save the ice!' And the watermen take the great glove down off the mast, and fold it like a sail." { Assert spread(crier_off_fact). }
  Entity crier_off_fact: fact "The Liberty cried ended".
  Rule glove_down when offIceHour() and not gloveDown(lisk) { Assert gloveDown(lisk). }
  Relation gloveDown(place).
  // Whoever is on the ice when the crier cries is hurried off it by the watermen, to whichever bank is nearer.
  Rule hurried_off when offIceHour() and onIce() and not iceGone() and not pilloried(party) and not hurried(party) and at(party, ?p) and not farIce(?p)
    says "Two watermen take you by the arms. 'Off,' says one. 'Off, off, off, it's going,' and walks you to the nearest stairs at a run, with the ice cracking behind you like a whip." {
    Assert hurried(party). Assert at(party, swan_lane). }
  Relation hurried(group).
  Relation farIce(place).
  Initially Assert farIce(reach_head). Initially Assert farIce(black_reach). Initially Assert farIce(patience_deck).
  Initially Assert farIce(patience_hold). Initially Assert farIce(sledge_road).
  // The pillory is the last thing taken off the ice: at the crier's call, not before.
  Rule pillory_off when offIceHour() and pilloried(party) and onIce() and not pilloryReleased(party)
    says "At the crier's call the watermen let you out of the pillory, stiff as a board and white with snow, and walk you off the ice at a run with the rest. 'Done your time,' says one, not unkindly. 'Ice is going. Everything's forgiven that isn't landed.'" {
    Assert pilloryReleased(party). Assert at(party, swan_lane). }
  Relation pilloryReleased(group).
  Rule callow_off when offIceHour() and callowStocked(callow) and not callowDead(callow) and not callowFreed(callow) {
    Assert callowFreed(callow). Retract callowStocked(callow). Assert state(stocks, empty). Assert at(callow, calf_taproom). }
  Relation callowFreed(group).
  // The ice goes out.
  Rule ice_goes when thawHour() and not thawed(lisk) says "From down the Reach, all at once, a sound like a city falling down: the ice going out. It comes up the river from the sea toward the bridge in the dark, crack after crack, louder, the whole frozen Lisk breaking into plates and rearing up against the starlings and going under, and the black water coming up through it steaming, and people on both banks with torches shouting at it, or crying, or cheering. By midnight there is a river under Pellam Bridge, running, full of ice, where Freezeland Street was." {
    Assert thawed(lisk). }
  // Every bargain shaken on the ice and not landed goes out with it.
  Rule bargains_melt when thawed(lisk) and shook(?g, ?b) and not landed(?b) and not melted(?b) and not handBroken(?b) and not handKept(?b) { Assert melted(?b). }
  // Whoever is still on the ice when it goes is struck, and comes ashore how they can.
  Hazard ice_breaking "The ice going out from under you" means "Deal (2d6) physical damage to ally unless dexterity save against (13).".
  Rule caught_on_ice when thawed(lisk) and onIce() and not swept(party) says "The ice opens under you with a sound like a door, and you are in the Lisk, in the dark, in the cold that stops the heart, and then on a plate of ice, and then on another, and then on your knees on the stones at the foot of Hay Stairs with a waterman's boat-hook in your collar, alive." {
    Assert swept(party). Assert strikes(ice_breaking, party). Assert at(party, hay_stairs). }
  Relation swept(group).
  // Gant, still on the ice and not free, is cried off it into the bailiffs' hands.
  Rule gant_cried_off when offIceHour() and at(gant, freezeland) and not gantFree(gant) and not gantSafe(gant) and not gantTaken(gant)
    {
    Assert gantTaken(gant). Assert at(gant, limbo). Assert happened(ev_gant_cried_off). }
  Entity ev_gant_cried_off: fact "gant cried off".
  Rule gant_cried_off_heard when happened(ev_gant_cried_off) and inPellam() and not heardNews(ev_gant_cried_off) says "At Hay Stairs, as the watermen hurry the last of the Fair off the ice, the bailiffs are waiting with their writ, and Sir Lionel Gant walks up the stairs into their hands with his hat on, very straight, saying 'It was three' to the bailiff on his left." { Assert heardNews(ev_gant_cried_off). }
  // The ice rooms close: the stairs lead to water.
  Observe swan_lane_thaw at swan_lane when iceGone() "Swan Stairs go down twelve steps into black water running fast, full of broken ice. The watermen are already putting their boats in.".
  Observe hay_thaw at hay_stairs when iceGone() "Hay Stairs go down into the river, black and running, with plates of ice going by. The watermen's boats are out.".
  Observe bridge_thaw at bridge_street when iceGone() "From the bridge, the Lisk: black, high, fast, roaring through the arches, full of ice and sailcloth and the oars of booths, and one gingerbread stall going round and round in an eddy below the third starling.".
}

data/adventures/liberty-of-the-ice/ursel:
Module pellam "The Liberty of the Ice" {
  // ── Ursel Cobb ────────────────────────────────────────────────────────────────────────────────────────────────────
  // A cheerful, efficient liar of forty, who has never shaken on anything in her life. She tells you her con is about
  // money. It is about her brother Dickon, hired by Harker at the spring hiring for "a place on a farm in the hills",
  // who has not written since.
  Person ursel "Ursel Cobb" at freezeland {
    Role "a woman in a man's caped coat, with a laugh like a door" when not urselKnown(party).
    Role "a liar by trade, in a man's caped coat" when urselKnown(party).
    Ancestry human. Calling thief. Level 3. Peaceable. Pronouns she. Manner cheerful.
    Greets "The woman in the caped coat looks you up and down, frankly, the way a horse-coper looks at a horse. 'Well,' she says. 'You're new.'".
    Greets again "'There you are,' says Ursel, as if you had been late.".
    Joins "'Partners,' says Ursel Cobb, and does not put out her hand. 'I don't shake. Nothing personal. I've never shaken on anything in my life, and I'm not starting on the ice.'".
    Leaves "'Mind how you go,' says Ursel, and is somewhere else.".
  }
  Relation urselKnown(group).
  Measure urselTrust(group). Measure urselHolds(group). Measure urselNear(group).
  Relation pursed(group). Relation pursedBack(group). Relation urselPitched(group).
  Relation liedToUrsel(group). Relation keptSecret(group). Relation urselConfessed(group). Relation urselGone(group).
  Relation skated(group). Relation wentInForDickon(group). Relation urselAsked(group). Relation handfast(group).
  Relation urselDeclined(group). Relation urselTook(group).
  Rule ursel_day when hour(clock) >= 8 and hour(clock) < 19 and not travelsWith(ursel, party) and not urselGone(ursel) and not iceGone() and not at(ursel, freezeland) { Assert at(ursel, freezeland). }
  Rule ursel_evening when hour(clock) >= 19 and hour(clock) < 24 and not travelsWith(ursel, party) and not urselGone(ursel) and not iceGone() and not at(ursel, lamb) { Assert at(ursel, lamb). }
  Rule ursel_night when hour(clock) < 8 and not travelsWith(ursel, party) and not urselGone(ursel) and not at(ursel, calf_taproom) { Assert at(ursel, calf_taproom). }

  // The first time the company stands in Freezeland Street, she takes its purse, and holds it up.
  Event purse_lifted at freezeland when at(party, freezeland) and urselHere() and not pursed(party) and quantity(party, gold) > 0 "Somebody knocks into you in the crush by the Glove Post, a woman in a caped coat, who says 'Beg pardon, my love,' and goes on, and when you put your hand to your purse it is not there. You turn round. She has stopped ten feet away and is holding it up by its strings for you to see, and laughing. 'Never shook on it,' she calls. 'Did I? Did you?' A few people nearby laugh too. Nobody calls the watch. There is no watch." then {
    Assert pursed(party). Set urselHolds(ursel) to quantity(party, gold). Set quantity(party, gold) to 0. }
  Query urselHere() means at(ursel, freezeland) and not travelsWith(ursel, party).
  Topic ursel_purse with ursel "Ask her for your purse back" when pursed(actor) and not pursedBack(actor) once {
    Says "'Course you can have it.' She tosses it to you. 'Lesson's free.' She watches you count it. 'All there. I'm not a thief, I'm a teacher. On the ice a word's free and a hand's bound, and I never gave you my hand, and you never asked for it.' She grins. 'Ursel Cobb. And you've a face nobody would ever suspect of anything, which is worth more than what was in there.'".
    On discuss { Assert pursedBack(actor). Increase quantity(actor, gold) by urselHolds(ursel). Set urselHolds(ursel) to 0. Assert urselKnown(actor). Assert knows(actor, liberty_known). }
  }
  Action lift_back(actor: group, site: place) "Lift your purse back off her while she is laughing" {
    Requires able(actor) and company(actor) and at(actor, site) and at(ursel, site) and pursed(actor) and not pursedBack(actor)
      and capable(actor, stealth).
    Time 1 minute.
    Resolve check(actor, stealth, dc_fair).
    On success { Assert pursedBack(actor). Increase quantity(actor, gold) by urselHolds(ursel). Set urselHolds(ursel) to 0.
      Assert urselKnown(actor). Increase urselTrust(ursel) by 1. Assert knows(actor, liberty_known). }
    Result "You walk up to her, smiling, and while she is telling you that she never shook on it you take it back off her, out of her own coat, where she put it, and show it to her. She stops laughing. Then she laughs much louder, and claps you on both shoulders. 'Oh, you'll do,' says Ursel Cobb. 'Oh, you'll do. Ursel Cobb. Come and have a gin. I've a proposition.'".
    Otherwise "You go for it and she turns, easily, and your hand closes on nothing. 'Nearly,' she says, and gives it back to you anyway. 'Lesson's free.'".
  }
  // Someone who reads people saw exactly how it was done, and says so: she likes that better than the purse.
  Topic ursel_seen with ursel "Tell her you watched her do it: the bump, the left hand under the cape, the purse into the sleeve" when pursed(actor) and not pursedBack(actor) and capable(actor, insight) once {
    Says "She stops laughing, and looks at you properly for the first time. 'Left hand under the cape,' she says. 'Nobody sees the left hand.' She gives you the purse back with a little bow. 'Ursel Cobb. And you've eyes, which is rarer on the ice than money. Come and have a gin. I've a proposition.'".
    On discuss { Assert pursedBack(actor). Increase quantity(actor, gold) by urselHolds(ursel). Set urselHolds(ursel) to 0. Assert urselKnown(actor). Increase urselTrust(ursel) by 1. Assert knows(actor, liberty_known). }
  }
  // Someone who reads people sees that a partner who owes them nothing is keeping her options open.
  Observe ursel_options near ursel when travelsWith(ursel, party) and urselTrust(ursel) < 1 and capable(party, insight) and not urselTook(party) "You notice that Ursel never quite stands where you can see both her hands, and that whenever money is mentioned she looks, very briefly, at your coat.".
  // A company that does not go after its purse finds it again before the Court sits, put back where it was taken.
  Rule purse_returned when pursed(party) and not pursedBack(party) and hour(clock) >= 15 and firstDay() says "You put your hand to your coat and your purse is there again, exactly where it was, with a twist of paper in it that says in pencil: NEVER SHOOK ON IT. — U.C. AT THE LAMB." teaches ursel_at_lamb {
    Assert pursedBack(party). Increase quantity(party, gold) by urselHolds(ursel). Set urselHolds(ursel) to 0. }
  Discovery ursel_at_lamb "The woman who took your purse on the ice and put it back calls herself U.C., and can be found at the Frozen Lamb.".

  // ── The proposition ───────────────────────────────────────────────────────────────────────────────────────────────
  Topic ursel_proposition with ursel "Ask Ursel what her proposition is" when urselKnown(actor) once {
    Says "She sits you down on an upturned keg out of the wind and talks low and fast. 'Josias Harker. Wool-factor, Fleece Row, churchwarden, very fond of God. With the roads shut he's buying fleeces that aren't shorn yet off sheep he can't see, cheap, for when the thaw comes and the price goes up. Every factor in Pellam is at it.' She taps your knee. 'So we sell him a flock. Two hundred fell ewes, up at Hawsfold, snowed in. Nobody can go and look till the thaw, and when the thaw comes, we're gone.' She sits back. 'You're the Squire of Hawsfold. I'm your man of business. Sixty coin, forty to you. We take his money on the ice and we're over the bridge before the Landing, and the bargain goes out with the river.' She looks at you. 'Well?'".
    On discuss { Assert knows(actor, con_plan). Assert knows(actor, landing_known). Assert urselPitched(actor). Assert willing(ursel, actor). Set hire(ursel) to 0. }
  }
  Discovery con_plan "Ursel Cobb's plan: the company to be the Squire of Hawsfold, with two hundred fell ewes snowed in on the fells, and to sell them to Master Harker the wool-factor, who is buying fleeces he cannot see; to take his money on the ice, and be over the bridge before the Landing, so the bargain goes out with the river.".
  Topic ursel_why with ursel "Ask Ursel why Harker" when knows(actor, con_plan) and not urselConfessed(actor) once {
    Says "'Because he's rich, and pious, and greedy, and stupid in exactly the one place a man ought to be clever, which is about himself.' She says it quickly and smoothly, to the fire, in the voice of someone who has said it to herself often enough to have worn the corners off. 'And because he'll pay. Ask me something else.' Her spoon goes round and round the cup and never once touches the side.".
    On discuss { Assert knows(actor, ursel_evades). }
  }
  Discovery ursel_evades "Asked why Harker, of all the factors in Pellam, Ursel Cobb answered too quickly, looking at the fire.".
  Topic ursel_travel_props with ursel travelling "Ask Ursel what the Squire of Hawsfold will need" when knows(actor, con_plan) once {
    Says "'Things he can hold.' She counts on her fingers. 'A tally of the flock, in a factor's hand or better, printed: Noll on the ice will print anything that isn't sworn. A bit of the wool, fell grey, from the Shambles or off a shepherd's coat. A coat on your back a squire wouldn't be ashamed of, and you'll not get that honestly. And a word for you from somebody he trusts.' She grins. 'And a face. You've the face. The rest is lies, and lies are free.'".
    On discuss { Assert knows(actor, props_known). }
  }
  Discovery props_known "What will make Harker believe in the Squire of Hawsfold: a printed tally of the flock; a tuft of fell wool; a coat a squire would wear; a word from somebody he trusts. And a face, and lies.".

  // ── What Ursel is looking for ─────────────────────────────────────────────────────────────────────────────────────
  Discovery ursel_brother "Ursel Cobb's brother Dickon was hired by Master Harker at Pellam's spring hiring, for a year's service on a farm in the hills, and has not written since. Her con is a way into Harker's house, and his books, to find where Dickon went." {
    Known by ursel.
  }
  Discovery ursel_watches "At the Hiring Ring Ursel Cobb watches each of Harker's hired as they step up to shake, as if looking for one face in particular, and does not find it.".
  Observe ursel_at_ring at hiring_ring when travelsWith(ursel, party) and hiringOn() and capable(party, insight) and not knows(party, ursel_watches) "Ursel has gone quiet. She stands at the rope of the Ring watching Harker's hired step up one by one to shake, and her eyes go to each face, quickly, and away, and back to the next, the way you look for someone in a crowd at a fair, and do not find them." teaches ursel_watches.
  Topic ursel_who with ursel travelling "Ask Ursel who she is looking for among the hired" when (knows(actor, ursel_watches) or knows(actor, ursel_evades) and urselTrust(ursel) >= 2) and not urselConfessed(actor) once {
    Says "For a moment she looks as if she will laugh it off. Then she does not. 'Dickon,' she says. 'My brother. Twenty. Big soft lump, he'd carry a calf a mile. Harker hired him at the spring hiring here for a farm in the hills, a year's place, good food, and he shook, and went, and he can write, I taught him myself, and nothing. Not a line.' She wipes her nose on her cape. 'So I want into Harker's house, and his books. The money's real. I'll still take his money. But I want the books.' She looks at you the way she looked at the purse in her hand on the first morning: weighing it. 'You can laugh. Everybody lies on the ice. That was mine.'".
    On discuss { Assert urselConfessed(actor). Assert knows(actor, ursel_brother). Increase urselTrust(ursel) by 1. }
  }
  Topic ursel_dickon_ledger with ursel travelling "Tell Ursel what Harker's books say of Dickon Cobb" when knows(actor, ledger_read) and not urselConfessed(actor) once {
    Says "You tell her. She hears you to the end without moving, and then she sits down on the ice, where she is, as if her legs had been taken away. 'Gallowmoor,' she says. 'Gallowmoor lead.' After a while she says, 'You found that, and you came and told me. You could have sold it me.' She gets up. 'Right,' says Ursel Cobb. 'Right. Now I'll tell you the truth, and you can see what it's like.' And she does: a brother, a hiring, a letter that never came.".
    On discuss { Assert urselConfessed(actor). Assert knows(actor, ursel_brother). Increase urselTrust(ursel) by 2. Assert keptSecret(actor). }
  }
  Topic ursel_keep with ursel travelling "Tell Ursel her secret is safe with you" when urselConfessed(actor) and not keptSecret(actor) and not liedToUrsel(actor) once {
    Says "'On the ice,' says Ursel, 'that's just words.' But she looks at you while a skater goes by, and another, and then she nods, once, the way a person nods who has decided to believe something against her own advice.".
    On discuss { Assert keptSecret(actor). Increase urselTrust(ursel) by 1. }
  }
  // A lie told her after she has told the truth: that Dickon is dead, when the company has seen him alive.
  Topic ursel_lie_dickon with ursel travelling "Tell Ursel that Dickon went through the ice, and is gone" when urselConfessed(actor) and knows(actor, dickon_alive) and not liedToUrsel(actor) and not urselMet(dickon) once {
    Says "She takes it like a blow, standing; then she looks at you, a long, flat, professional look, the look she gives a mark, and you see her see it. 'That's a lie,' she says. 'That's a good one, and it's a lie.' She does not ask you why. She does not say anything else to you that evening.".
    On discuss { Assert liedToUrsel(actor). Decrease urselTrust(ursel) by 3. }
  }

  // ── What Ursel tells at night ─────────────────────────────────────────────────────────────────────────────────────
  // Three things, told late, to someone she has begun to trust, each opening the next. The first is why she never
  // shakes; the second where she learned to lie; the third is what she makes of Harker when she learns he was a hired
  // child of the same parish. Swale Head is hers, Tansy Hobb's, and Harker's: three generations of the same hand.
  Query lateHour() means hour(clock) >= 19 or hour(clock) < 5.
  Topic ursel_never with ursel travelling "Ask Ursel, late, why she has never shaken on anything" when lateHour() and urselTrust(ursel) >= 1 once {
    Says "She is quiet so long you think she will not answer. 'Swale Head,' she says. 'Up under the fell, where the becks start. We had a farm, forty acres of stones. The year I was eleven the clip failed, and a Pellam factor came up the dale with a note, against next year's wool, and my father shook on it in our own kitchen, with the factor's glove on the table, and I watched him do it.' She turns her cup round. 'Next year's clip failed too. The note was good in any court of the country. They landed the farm, and the stock, and the bed. My mother walked us down to Pellam with Dickon on her hip.' She drinks. 'I don't know the factor's name. I never asked. If I knew it I'd have to do something.' A pause. 'So I don't shake. A word's free. A hand's what they take your bed with.'".
    On discuss { Assert knows(actor, ursel_father). Increase urselTrust(ursel) by 1. }
  }
  Discovery ursel_father "Ursel Cobb's father shook hands with a Pellam factor on a note against his wool, at Swale Head, when she was eleven; the clip failed, the note was landed, and the farm with it. She has never shaken on anything since, and has never asked the factor's name.".
  Topic ursel_lying with ursel travelling "Ask Ursel where she learned to lie" when knows(actor, ursel_father) once {
    Says "'On the Liars' Bench.' She laughs, properly, for the first time that evening. 'Not this one. The Bench is older than the Frosts; when there's no ice it's a plank at the back of the Calf, and the Reeve's whoever's oldest. I won it at fifteen, with a story about a man who sold the bridge to itself, and old Broom's mother gave me the prize, a penny with a hole in it.' She shows you: it is round her neck on a string, worn thin. 'The truth's very dear, for poor folk. So we tell it on a bench, for fun, with everyone knowing it's lies. That's where you can say anything.' She looks at the fire. 'I've told the truth on that bench more times than anywhere else in my life.'".
    On discuss { Assert knows(actor, ursel_bench). }
  }
  Discovery ursel_bench "Ursel won the Liars' Bench at fifteen, and wears the prize, a penny with a hole in it, on a string; she says she has told more truth on it than anywhere else.".
  Topic ursel_harker_swale with ursel travelling "Tell Ursel that Harker was a hired child once, hired at nine, at Swale Head" when knows(actor, ursel_father) and knows(actor, harker_hired) once {
    Says "She stares at you. 'Swale Head.' Then, slowly: 'There were Harkers at the Head. At the top farm, under the scar, before my time. They went.' She is silent. Somebody at the next table wins at cards and is accused of it. 'So he knows,' she says. 'He knows exactly. He knows what the kitchen looks like, and the glove on the table.' She puts her cup down with great care, the way Harker puts his glass down. 'I'd rather he was a devil. A devil you can do something about.' She does not say anything else, and in the morning she is the same as ever, and laughs at everything, and once, crossing Fleece Row, stops and looks up at his house as if she were trying to see a boy of nine in one of the windows.".
    On discuss { Assert knows(actor, ursel_knows_harker). Increase urselTrust(ursel) by 1. }
  }
  Discovery ursel_knows_harker "Told that Harker was hired at nine out of Swale Head, her own parish, Ursel said she would rather he were a devil.".
  Topic ursel_tansy with ursel travelling "Tell Ursel that one of Harker's hired, Tansy Hobb, is a dairymaid from Swale Head" when knows(actor, tansy_hired) and knows(actor, ursel_father) once {
    Says "'Hobb.' She closes her eyes. 'The Hobbs had the low farm, by the wash-dub, where the beck goes under the road. Mary Hobb gave my mother a cheese the morning we walked down. She'll be this Tansy's grandmother.' She opens them. 'Fifteen, you said.' She stands up. 'Then it's two of us I want out of that barn,' says Ursel, and has her cape fastened to the chin before you have said a word.".
    On discuss { Assert knows(actor, ursel_hobbs). Increase urselTrust(ursel) by 1. }
  }
  Discovery ursel_hobbs "Tansy Hobb's people had the low farm at Swale Head; her grandmother gave Ursel's mother a cheese the morning the Cobbs walked down to Pellam.".

  // ── The note, in the Exchange's book ──────────────────────────────────────────────────────────────────────────────
  // The Exchange keeps a register of every note landed against the wool. Twenty-nine years back there is a Cobb of
  // Swale Head, landed to "J. H."; and there are two J. H.s on Fleece Row, Harker and old Hebden, and were then. The
  // book cannot say which, and nothing else in Pellam will. Whether to tell Ursel is the company's.
  Discovery cobb_note "In the Wool Exchange's register of landed notes, twenty-nine years back: COBB, of Swale Head, a note against two clips, landed, with the farm, to J. H. There were two factors on Fleece Row with those letters then, as now: Josias Harker, and old Jonas Hebden of Hebden & Sons." {
    Found by searching exchange_floor "Under the slates, in a press with its doors warped shut, the Exchange's old registers of landed notes, a volume to a year, in calf gone to powder at the corners.".
  }
  Relation toldCobbNote(group).
  Topic ursel_note with ursel travelling "Tell Ursel what the Exchange's book says of a Cobb of Swale Head" when knows(actor, cobb_note) and knows(actor, ursel_father) and not toldCobbNote(actor) once {
    Says "She listens to the end without moving. 'J. H.,' she says. Then she laughs, not her door-banging laugh, a small one. 'Hebden's eighty and blind and lives over his shop on gruel, and his sons are fools, and he gave my mother a shilling once in the Cheaping because she curtseyed to him.' She is quiet. 'And the other was a boy off the top farm, home from Ossett with money.' She puts her hand on your arm, hard, a moment, the nearest she comes to giving it, and takes it away. 'You could have kept that,' she says. 'I'd never have known there was anything to keep.' She does not say which J. H. she thinks it was. You do not think she has decided.".
    On discuss { Assert toldCobbNote(actor). Increase urselTrust(ursel) by 1. }
  }

  // ── The Flashes, at dusk ──────────────────────────────────────────────────────────────────────────────────────────
  Observe flashes_scene at flashes when not dusk() and not dark() "The Flashes: water-meadows above the city, flooded in the autumn and frozen flat as a table, a mile of grey ice between pollard willows. A few boys with skates of bone. A man selling skates of iron by the hour from a barrow.".
  Observe flashes_dusk at flashes when dusk() "The Flashes at dusk: the whole of Pellam that is young or rich or both, skating, under a sky going green and gold behind the willows, in long scarves, in pairs, in lines holding hands, very fast and very badly. Torches on poles along the bank. Somebody is playing a fiddle with gloves on. Everyone is looking at everyone else.".
  Observe flashes_dark at flashes when dark() "The Flashes at night, empty, the torches out, the ice grey under the stars.".
  Action skate_alone(actor: group, site: place) "Hire skates by the hour and go out on the Flashes" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, flashes) and not dark() and quantity(actor, gold) >= 1 and not travelsWith(ursel, actor) and not skatedAlone(actor).
    Time 6.
    On success { Decrease quantity(actor, gold) by 1. Assert skatedAlone(actor). }
    Result "Iron skates, a size too big, strapped on over your boots. You fall down twice and then, for a little while, you do not, and the willows go by, and for the length of the Flashes there is nothing in the world but the sound of the blades.".
  }
  Relation skatedAlone(group).
  Action skate_ursel(actor: group, site: place) "Hire two pairs of skates, and take Ursel out on the Flashes" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, flashes) and dusk() and travelsWith(ursel, actor) and quantity(actor, gold) >= 2 and not skated(actor).
    Time 6.
    On success { Decrease quantity(actor, gold) by 2. Assert skated(actor). Increase urselTrust(ursel) by 1. }
    Result "Ursel says she cannot skate, which is a lie, and then that she has not skated since she was a girl, which is true. For the first length of the Flashes she holds your arm as if it were a rail. By the third she has let go and is going backwards in front of you with her cape out like wings, laughing her door-banging laugh at the sky, and half the Flashes is watching. When the torches are lit she comes and stops in front of you, breathing hard, and for once has nothing to say.".
  }

  // ── The question at the Ice Chapel ────────────────────────────────────────────────────────────────────────────────
  // On the last morning, before the wedding at noon, Ursel asks one thing, if there is a reason to ask it: shared
  // history, not a score (the skating, the card, the bondhouse, the secret kept), and nothing that ends it.
  Query romanceHolds(a: group) means (skated(a) and pairPrinted(a) and keptSecret(a)) or (skated(a) and wentInForDickon(a))
    or (pairPrinted(a) and wentInForDickon(a)) or (keptSecret(a) and wentInForDickon(a) and skated(a)).
  Event ursel_asks near ursel when thirdDay() and hour(clock) >= 10 and hour(clock) < 12 and travelsWith(ursel, party) and (at(party, freezeland_low) or at(party, chapel)) and romanceHolds(party)
    and not liedToUrsel(party) and not drownedSold(party) and not urselAsked(party) "Ursel stops in the middle of Freezeland Street, by the ribboned booth of the Ice Chapel, where Parson Doody is sweeping the step for the noon wedding. She reads the board that says MARRIAGES as though it were a bill of sale. 'Forty years,' she says, 'I've never given my hand on anything.' She does not look at you. 'They say a hand on the ice is landed at two and good for life. And they say a wedding on the ice that isn't landed goes out with the river, and there's an end of it.' She looks at you then. 'I'd shake on the second kind,' says Ursel Cobb. 'With you. And then see.'" then {
    Assert urselAsked(party). }
  Observe ursel_quiet near ursel when thirdDay() and hour(clock) >= 7 and hour(clock) < 12 and travelsWith(ursel, party) and romanceHolds(party)
    and not liedToUrsel(party) and not urselAsked(party) "Ursel is quieter this morning than you have known her. She keeps looking away down the ice toward the lower end of Freezeland Street, where the ribboned booth of the Ice Chapel is, and then not looking.".
  Entity handfast_bargain: bargain "a handfast with Ursel Cobb, at the Ice Chapel".
  Action shake_ursel(actor: group, site: place) "Take Ursel's hand, in the Ice Chapel, and shake" {
    Grave "A hand shaken on the ice binds. This one will be cried at the Landing with the rest, unless you both let it go out with the river.".
    Requires able(actor) and company(actor) and at(actor, site) and urselAsked(actor) and travelsWith(ursel, actor) and not handfast(actor) and not urselDeclined(actor)
      and (at(actor, chapel) or at(actor, freezeland_low)) and not iceGone().
    Time 1.
    On success { Assert handfast(actor). Assert shook(actor, handfast_bargain). Assert shook(ursel, handfast_bargain). Increase quantity(doody, gold) by 1. }
    Result "Parson Doody, who has been listening from the step with his broom, says 'A shilling,' and you give him one, and he does it in the doorway of the Ice Chapel with his broom under his arm, in about a minute, with a cold in his head. Ursel gives you her hand. It is the first time. Her grip is very hard and her hand is shaking. 'There,' she says, when it is done, and laughs, too loud, and wipes her eyes on her cape. 'There. Now we'll see.'".
  }
  Topic ursel_not_ice with ursel travelling "Tell Ursel you'll not shake on it on the ice" when urselAsked(actor) and not handfast(actor) and not urselDeclined(actor) once {
    Says "'No.' She nods, quickly, as if you had told her the price of something. 'No, you're right. Not on the ice.' She is quiet. Then: 'Somewhere it doesn't melt, then. Or nowhere.' She does not say which she thinks. She puts her arm through yours for the length of Freezeland Street, and then takes it out again.".
    On discuss { Assert urselDeclined(actor). }
  }
}

data/adventures/liberty-of-the-ice/water:
Module pellam "The Liberty of the Ice" {
  // ── Bankside ──────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe bankside_scene at bankside_street when not visitedBefore(bankside_street) "Bankside: the other Pellam, across the river from the respectable one, and it smells of frying. The shut playhouse has snow on its roof and a boy asleep in its doorway; the Watermen's Hall has its oars crossed over the door like a coat of arms; and the long wall of the Clink runs half the length of the street with washing hung over the top. The Clink is a prison for debtors and a liberty of its own, so that a man inside it owes nobody anything until he comes out.".
  Observe bankside_again at bankside_street when visitedBefore(bankside_street) "Bankside: inns and cookshops, the Watermen's Hall, the long wall of the Clink.".
  Observe calf_scene at calf_taproom when true "The Spotted Calf: low beams, a fire you could roast a calf at, drovers and watermen and people who are neither, and a landlord who looks as if he has heard every lie told in Bankside and preferred most of them to the truth.".
  Person nab "Nab Pollard" at calf_taproom {
    Role "the landlord of the Spotted Calf". Profession innkeeper. Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "'Bed's a shilling, supper's a groat, and the lies are on the house,' says Nab Pollard. 'Snowed in, are you? Everyone's snowed in. Pellam's a jar with the lid on.'".
    Greets again "Nab Pollard lifts a hand without looking round from the fire.".
    Sells rations for 1 coin from 20.
  }
  Topic nab_fair with nab "Ask Nab Pollard about the Frost Fair" when true once {
    Says "'First in thirty-one winters. Beer's up a farthing and gin's up a penny, and I've watered neither, so I'm for the frost.' He pours. 'River froze solid in a night, a month back. The watermen lost their living by breakfast, and by dinner there was a gingerbread stall on it, and old Clemmy Broom in a tent with her trumpet, crying the Liberty like her mother did.' He wipes the counter. 'Everybody's got a scheme. Factors buying sheep they can't see, debtors living out on the ice, Harker hiring on it. You'll have yours by tonight. Everyone does.'".
    On discuss { Assert knows(actor, roads_shut). Assert knows(actor, liberty_known). }
  }

  // ── Gaffer Tredgold and the watermen ──────────────────────────────────────────────────────────────────────────────
  // A month out of work. They keep the stairs for a penny a stair, and they have the saws and the men to cut a channel
  // across the bottom of the Reach and end the Fair, and on the second night, unless they have work, they will.
  Observe hall_scene at watermen_room when not visitedBefore(watermen_room) "The Watermen's Hall: a long room with the Company's oars on the walls, a brazier, and thirty men with nothing to do sitting on benches doing it. Ice-saws hang by the door, long two-handled saws with teeth like a pike's. At a table under the window an old waterman with a face like a clenched fist is writing in the Company's book.".
  Observe hall_again at watermen_room when visitedBefore(watermen_room) "The Watermen's Hall: the oars on the walls, the ice-saws by the door, thirty idle men.".
  Person tredgold "Gaffer Tredgold" at watermen_room {
    Role "the master of the Watermen's Company, idle a month". Ancestry human. Calling warrior. Level 3. Peaceable. Pronouns he. Manner grim.
    Greets "Gaffer Tredgold looks at you over the Company's book. 'If you want a boat,' he says, 'there's no river. If you want a fight, there's thirty of us. If you want anything else, be quick.'".
    Greets again "Tredgold looks up from the Company's book, and down.".
  }
  Person watermen "the watermen" at watermen_room {
    Role "a benchful of watermen with nothing to do". Ancestry human. Numbers 4. Peaceable. Pronouns they.
  }
  Rule tredgold_hall when hour(clock) >= 7 and hour(clock) < 22 and not at(tredgold, watermen_room) and not tredgoldOut(tredgold) { Assert at(tredgold, watermen_room). }
  Relation tredgoldOut(group).
  Relation watermenWorked(place). Relation channelCut(place). Relation sledgesReady(place). Relation tredgoldAngry(group).
  Topic tredgold_ice with tredgold "Ask Gaffer Tredgold what the watermen mean to do about the ice" when true once {
    Says "'Wait.' He shuts the book. 'A month we've waited, with the river stopped under us like a clock, and our boats on the stages with the snow on them, and a penny a stair to feed thirty families.' He looks at the saws by the door. 'Old Clemmy keeps the Liberty, and she's ours, and the Fair's ours by right. But a Fair doesn't row anyone anywhere.' He opens the book again. 'There's some of the young ones say cut it. A channel across the foot of the Reach, one night's work, and the ice goes out a day sooner, and the river's back. I've not said no yet.'".
    On discuss { Assert knows(actor, channel_threat). }
  }
  Discovery channel_threat "The idle watermen talk of cutting a channel across the foot of the Reach with their ice-saws, to end the Fair and have their river back. Tredgold has not said no; unless they have work by the second night, they will.".
  Topic tredgold_harker with tredgold "Tell Gaffer Tredgold what Harker does with his hired, on the Watermen's ice" when knows(actor, hired_sold) and not tredgoldAngry(tredgold) once {
    Says "He hears it without moving. Then he gets up, slowly, and goes to the window, and looks across at Hay Wharf, at the long blind wall with J. HARKER. WOOL on it. 'On our ice,' he says. 'Under our Liberty. Under Clemmy's glove.' He turns round. The Hall has gone quiet. 'The Company'll not cut its own ice while there's that to be done on it,' says Gaffer Tredgold. 'What do you want of us?'".
    On discuss { Assert tredgoldAngry(tredgold). Assert watermenWorked(lisk). }
  }
  Action hire_sledges(actor: group, site: place) "Hire the watermen's sledges and men for the second night, ten coin" {
    Requires able(actor) and company(actor) and at(actor, site) and at(tredgold, site) and quantity(actor, gold) >= 10 and not sledgesReady(lisk) and not tredgoldAngry(tredgold)
      and knows(actor, channel_threat).
    Time 2 minutes.
    On success { Decrease quantity(actor, gold) by 10. Assert watermenWorked(lisk). Assert sledgesReady(lisk). }
    Result "Tredgold counts the coin into the Company's box and writes it in the book. 'Ten coin, four sledges and eight men, the second night,' he says. 'Where and when?' You tell him the foot of Hay Stairs, in the small hours. He does not ask what for. 'Done,' he says, and does not offer his hand, because you are not on the ice.".
  }
  Action ask_sledges(actor: group, site: place) "Ask Tredgold for the Company's sledges at the foot of Hay Stairs, in the small hours of the second night, for nothing" {
    Requires able(actor) and company(actor) and at(actor, site) and at(tredgold, site) and tredgoldAngry(tredgold) and not sledgesReady(lisk).
    Time 2 minutes.
    On success { Assert sledgesReady(lisk). }
    Result "'Four sledges and eight men,' says Tredgold. 'And me.' He takes a saw down off the wall and looks along its teeth as if it were a sword. 'Not for cutting. For the dog.'".
  }
  // Ice for Quarle's tub: work of a kind.
  Action set_watermen_quarle(actor: group, site: place) "Tell Tredgold that Mr. Quarle of the Frost Company wants men to cut and haul ice, and will pay" {
    Requires able(actor) and company(actor) and at(actor, site) and at(tredgold, site) and knows(actor, quarle_needs) and not watermenWorked(lisk).
    Time 2 minutes.
    On success { Assert watermenWorked(lisk). Assert quarleHasMen(quarle). }
    Result "'Cutting ice,' says Tredgold, 'to keep it ice.' He thinks about it while the Hall pretends not to listen. 'It's work,' he says. 'It's daft, and it's work, and he pays by the day.' He sends six of the young ones off with saws, grinning, and the Hall is a different place.".
  }
  Relation quarleHasMen(group).
  Rule channel_cut when secondDay() and hour(clock) >= 22 and not watermenWorked(lisk) and not channelCut(lisk) {
    Assert channelCut(lisk). Assert state(channel, open_water). Assert happened(ev_channel_cut). }
  Entity ev_channel_cut: fact "channel cut".
  Rule channel_cut_heard when happened(ev_channel_cut) and inPellam() and not heardNews(ev_channel_cut) says "In the night, from down the Reach, a long sound of saws, a dozen of them, and men singing to keep the time. By morning there is a channel of black water forty feet wide across the foot of the Reach from bank to bank, steaming, and the sledge road south ends at it." { Assert heardNews(ev_channel_cut). }
  Thing channel "the watermen's channel" on sledge_way is scenery {
    State whole "The sledge marks run on south over hard ice.".
    State open_water blocking "Across the foot of the Reach the watermen's channel lies forty feet wide, black water steaming. Nobody goes south on the ice now.".
  }
  Initially Assert state(channel, whole).
  Observe sledges_waiting at hay_foot when sledgesReady(lisk) and secondNightSmall() and not hiredFled(lisk) "At the foot of Hay Stairs, in the dark, four long ice-sledges with rope traces, and eight watermen stamping their feet beside them, and Gaffer Tredgold with an ice-saw over his shoulder.".
  Query secondNightSmall() means secondDay() and (hour(clock) >= 23 or hour(clock) < 6).
  Rule tredgold_waits when sledgesReady(lisk) and secondNightSmall() and not hiredFled(lisk) and not at(tredgold, hay_foot) { Assert at(tredgold, hay_foot). Assert tredgoldOut(tredgold). }
  Rule tredgold_home when tredgoldOut(tredgold) and thirdDay() and hour(clock) >= 6 { Retract tredgoldOut(tredgold). }
}

data/adventures/liberty-of-the-ice/wolve:
Module pellam "The Liberty of the Ice" {
  // ── The wolves on the sledge road ─────────────────────────────────────────────────────────────────────────────────
  // A month of snow has brought the wolves down off the downs after the frozen river, as it brings them in every
  // great frost (the Book of Frosts has them in four of seven). On the second night they sit across the sledge road at
  // the foot of the Reach, which is the way south for anyone who is going: Dickon's drowned, the hired, the company.
  // They can be fought, and are dangerous; or driven off with fire, which they fear; or fed; or gone round, downwind,
  // by someone who knows how; or faced down; or outrun on the watermen's sledges.
  Person wolves "the wolves off the downs" at limbo {
    Role "four of them, grey, lean as rakes with the winter". Species wolf. Numbers 4. Pronouns they.
    Temperament territorial. Refuge limbo. Fears flame.
    Warns "On the sledge road ahead of you, where the ice goes on grey and empty into the dark, four shapes are sitting in a row, the way dogs sit outside a butcher's. They get up, without hurry. One of them puts its head down, and you hear it: a sound like a saw in green wood, very low.".
    Comes "They come at you over the ice low and fast and silent, spreading out as they come, the way the watermen spread out to pull a boat.".
    Flinches "The wolves turn, all four together, and go away down the sledge road at a long easy lope, and stop a long way off, and sit, and watch you, and then are not there.".
  }
  Relation wolvesCame(place). Relation wolvesBeaten(place). Relation wolvesFed(place). Relation wolvesDriven(place).
  Query wolfNight() means secondDay() and (hour(clock) >= 22 or hour(clock) < 5) and not iceGone().
  Rule wolves_come when wolfNight() and able(wolves) and not wolvesCame(lisk) { Assert wolvesCame(lisk). Assert at(wolves, sledge_road). Assert happened(ev_wolves). }
  Rule wolves_go when thirdDay() and hour(clock) >= 5 and at(wolves, sledge_road) { Assert at(wolves, limbo). }
  Entity ev_wolves: fact "wolves".
  Rule wolves_heard when happened(ev_wolves) and inPellam() and not onIce() and not heardNews(ev_wolves) and not at(party, sledge_road)
    says "Far off down the river, past the end of the Fair, past the Reach, a sound you take at first for the wind in the bridge: rising, and falling, and rising, and then two of it, and then four. Wherever people are awake in Pellam they stop talking to listen. Somebody near you says, 'Wolves. On the river,' and somebody else says, 'They'll be after the ox,' and laughs, and nobody laughs with him." {
    Assert heardNews(ev_wolves). }
  Rule wolves_heard_ice when happened(ev_wolves) and onIce() and not heardNews(ev_wolves) and not at(party, sledge_road)
    says "From down the Reach, over the ice, which carries sound the way a table carries a dropped spoon: a howl, long, rising and falling, and then another under it, and another. The lanterns along Freezeland Street seem suddenly very small." {
    Assert heardNews(ev_wolves). }
  Observe wolves_watch at sledge_road when at(wolves, sledge_road) and tolerates(wolves, party) "Away off the sledge road, out on the grey ice, four shapes trot along level with you, a long way off, and stop when you stop.".
  Observe wolves_ate at sledge_road when wolvesFed(lisk) and wolfNight() "Away down the ice, a long way off, a dark heap and four shapes busy at it, and a sound of bone.".

  // Fire. A brand lit at the ox fire, at Fowke's brazier on the wharf, or at the brazier on the bondhouse floor burns
  // two hours; held up and swung, it drives them off for the night.
  Measure brandUntil(group).
  Query brandLit(a: group) means brandUntil(a) > watch(clock).
  Action brand_ox(actor: group, site: place) "Wrap a billet of the ox's firewood in tow, and light it at the ox fire for a brand" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ox_roast) and not iceGone() and not brandLit(actor) and quantity(actor, gold) >= 1.
    Time 2 minutes.
    On success { Decrease quantity(actor, gold) by 1. Set brandUntil(actor) to watch(clock) + 12. }
    Result "The Butcher at the spit sells you a billet of ash and a fist of tarry tow for a penny, and does not ask what for, because a man who sells hot meat in a frost has seen everything. The tow catches with a sound like a sheet shaken out on a line, and burns orange and stinking and very bright.".
  }
  Action brand_wharf(actor: group, site: place) "Light a brand at old Fowke's brazier, with a stave off the bales" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hay_wharf) and dark() and not brandLit(actor)
      and (asleep(fowke) or not at(fowke, hay_wharf) or sodden(fowke)).
    Time 2 minutes.
    On success { Set brandUntil(actor) to watch(clock) + 12. }
    Result "A stave out of the bale-lashings, a twist of greasy fleece round the end of it, and the brazier's coals: it goes up with a smell of a singed sheep and a light that throws your shadow the length of the wharf. Fowke does not stir.".
  }
  Action brand_bondhouse(actor: group, site: place) "Wind a stave in a greasy fleece off the stack, and light it at the bondhouse brazier" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bond_floor) and not brandLit(actor).
    Time 2 minutes.
    On success { Set brandUntil(actor) to watch(clock) + 12. }
    Result "Harker's fleeces are full of their own grease; one of them round the end of a stave out of the straw-rack burns like a church candle, low and yellow and smoking. Tansy Hobb watches you light it and says nothing, and then says, 'For the wolves, is it,' as if everyone knew there were wolves.".
  }
  Observe brand_burning near party when brandLit(party) and dark() "The brand hisses and spits in your fist, and the dark goes back from it a little way on every side.".
  Action brand_wolves(actor: group, site: place) "Hold the brand up high and walk straight at the wolves, swinging it" {
    Requires able(actor) and company(actor) and at(actor, site) and at(wolves, site) and able(wolves) and brandLit(actor) and not tolerates(wolves, actor).
    Time 1 minute.
    On success { Assert wolvesDriven(lisk). Assert at(wolves, limbo). Retract assails(wolves, actor). Retract warned(wolves, actor). }
    Result "You walk at them with the brand over your head, and it roars in the wind of your going, and drips burning on the ice. The nearest backs off a step, with its ears flat, and snaps at the sparks; then they are all going, sideways, unhurried, offended, down the sledge road into the dark, and the dark closes behind them. Your hand is shaking so that the brand shakes. Nobody behind you says anything at all.".
  }

  // Meat. The ox's lights and offal, a bucket of it, thrown out on the ice upwind, and they are busy until morning.
  Kind offal_kind "a bucket of offal" is gear worth 0 weighing 2 described "A wooden bucket of the ox's lights and liver and guts, steaming in the cold, and then not steaming, and then frozen into one red stone.".
  Item offal "a bucket of offal" is offal_kind at limbo.
  Relation offalBought(group).
  Action buy_offal(actor: group, site: place) "Buy a bucket of the ox's offal from the Butchers at the spit" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ox_roast) and not iceGone() and not offalBought(actor) and at(offal, limbo) and quantity(actor, gold) >= 1.
    Time 2 minutes.
    On success { Decrease quantity(actor, gold) by 1. Assert offalBought(actor). Assert at(offal, ox_roast). }
    Result "The Butcher fills a pail from the barrel at the back of the hearth: lights, liver, the long grey ropes of the guts. 'For your dogs?' he says. 'Big dogs.' He takes your penny.".
  }
  Action throw_offal(actor: group, site: place) "Swing the bucket of offal out over the ice upwind of them, as far as it will go" {
    Requires able(actor) and company(actor) and at(actor, site) and at(wolves, site) and able(wolves) and carries(actor, offal) and not tolerates(wolves, actor).
    Time 1 minute.
    On success { Assert wolvesFed(lisk). Assert at(wolves, limbo). Assert at(offal, limbo). Retract assails(wolves, actor). Retract warned(wolves, actor). }
    Result "It goes out over the ice in a red string and lands with a sound like a wet sack, thirty yards off, upwind. For a moment none of them move. Then the biggest gets up and trots over to it, and then all of them, and there is snarling, and the sound of bone; and you go by on the far side of the sledge road with the brand of their noise at your back, walking, because you have been told all your life not to run from a dog.".
  }

  // Downwind. Someone who knows wolves takes the company wide round them along the bank, with the wind in their faces.
  Relation wolvesRounded(group).
  Action round_wolves(actor: group, site: place) "Take everyone wide round the wolves along the bank, downwind of them, slowly" {
    Requires able(actor) and company(actor) and at(actor, site) and at(wolves, site) and able(wolves) and capable(actor, woodcraft) and not tolerates(wolves, actor) and not wolvesRounded(actor).
    Time 3 minutes.
    Resolve check(actor, woodcraft, dc_fair).
    On success { Assert wolvesRounded(actor). Assert tolerates(wolves, actor). Retract warned(wolves, actor). Retract assails(wolves, actor). }
    On failure { Assert wolvesRounded(actor). }
    Result "You wet a finger and hold it up, and go off the sledge road onto the rough ice under the bank, where the reeds stand up through it frozen, with the wind coming at you off the wolves, carrying their smell, rank, like a wet dog in a hot room. You go slowly. They do not turn their heads. Half a mile on you come back onto the sledge road, and behind you, a long way off, four shapes are still sitting where they sat, looking up the river at the lights.".
    Otherwise "Halfway round the wind goes round, the way it does on a river, and one of them lifts its head, and stands up, and turns toward you.".
  }

  // Faced down: one person, walking forward, shouting, big; wolves are cowards about what they do not understand.
  Relation wolvesFaced(group).
  Action face_wolves(actor: group, site: place) "Stand in front of everyone and face the wolves down: shout, wave your arms, walk at them" {
    Requires able(actor) and company(actor) and at(actor, site) and at(wolves, site) and able(wolves) and not tolerates(wolves, actor) and not wolvesFaced(actor).
    Time 1 minute.
    Resolve check(actor, intimidation, dc_hard).
    On success { Assert wolvesFaced(actor). Assert wolvesDriven(lisk). Assert at(wolves, limbo). Retract warned(wolves, actor). Retract assails(wolves, actor). }
    On failure { Assert wolvesFaced(actor). Assert assails(wolves, actor). Retract warned(wolves, actor). }
    Result "You walk at them shouting: words, nothing, the noises a drover makes, your arms out to be wider than you are. They watch you come. Then the leader looks away, which is the whole of it, and they go, unhurried, as if it had been their idea.".
    Otherwise "You walk at them shouting, and the leader does not look away, and you see it see that you are afraid; and they come.".
  }

  // On the sledges, nothing on four legs keeps up for long.
  Rule wolves_outrun when hiredFled(lisk) and sledgesReady(lisk) and at(party, sledge_road) and at(wolves, sledge_road) and not wolvesOutrun(lisk)
    says "At the foot of the Reach, for a mile, there are wolves running beside the sledges in the starlight, four of them, grey, silent, level with the runners, close enough to hear their breath; one of the watermen lays about him with a boat-hook and swears at them as if they were boys on a wall; and then they drop back, and sit down on the ice, and are left behind, and are gone." {
    Assert wolvesOutrun(lisk). Assert at(wolves, limbo). }
  Relation wolvesOutrun(place).
  Rule wolves_dead when wolvesCame(lisk) and not able(wolves) and not wolvesBeaten(lisk) { Assert wolvesBeaten(lisk). }

  // Warned of them, Dickon takes fire with him if he goes south alone with the drowned; not warned, they meet them.
  Relation dickonWarned(group).
  Topic dickon_wolves with dickon "Tell Dickon there are wolves on the sledge road" when knows(actor, wolves_down) and knows(actor, dickon_night) and not dickonGone(dickon) and not dickonTaken(dickon) once {
    Says "He hears it with his head down, coughing. 'Wolves.' He looks round the hold, at Jem Rudd, who is fourteen, and at the girl with the bandaged feet. 'At Gallowmoor there's a man called Corder counts you down the ladder in the morning and counts you up at night, and if the number's short he doesn't go and look.' He gets up. 'We'll go with fire, then. Saffery's got tar.' He looks at you. 'Thank you for telling me. Nobody tells you anything, drowned.'".
    On discuss { Assert dickonWarned(dickon). }
  }
  Rule drowned_meet_wolves when dickonGone(dickon) and not hiredOut(lisk) and not hiredFled(lisk) and at(wolves, sledge_road) and not dickonWarned(dickon) and not spread(drowned_met_wolves) and secondDay() {
    Assert spread(drowned_met_wolves). Assert drownedMetWolves(lisk). }
  Rule drowned_went_fire when dickonGone(dickon) and not hiredOut(lisk) and not hiredFled(lisk) and dickonWarned(dickon) and not spread(drowned_met_wolves) and secondDay() and hour(clock) < 5 {
    Assert spread(drowned_met_wolves). Assert drownedWentFire(lisk). }
  Relation drownedMetWolves(place). Relation drownedWentFire(place).
  Entity drowned_met_wolves: fact "the drowned met the wolves".
  Rule drowned_wolves_heard when drownedMetWolves(lisk) and thirdDay() and hour(clock) >= 7 and inPellam() and not spread(drowned_wolves_told)
    says "A waterman who walked down the Reach at first light to look at the ice comes back up it fast, and stands in the Calf with his cap in his hands. The drowned went south in the night, he says: the tracks of seven or eight people on the sledge road, going south; and over them, the other tracks, four, going the same way, and then not the same way, going round. A cap. A great deal of trodden snow. He did not go on past it. Nobody in Bankside asks him to go back." {
    Assert spread(drowned_wolves_told). }
  Rule drowned_fire_heard when drownedWentFire(lisk) and thirdDay() and hour(clock) >= 7 and inPellam() and not spread(drowned_wolves_told)
    says "A waterman who walked down the Reach at first light says that the drowned went south on the sledge road in the night, seven or eight of them, and wolves after them all the way to the downs; and every half-mile, the ashes of a fire on the ice, and a ring of tracks round it, at a distance, that never came in." {
    Assert spread(drowned_wolves_told). }
  Rule ursel_hears_wolves when drownedMetWolves(lisk) and spread(drowned_wolves_told) and travelsWith(ursel, party) and (urselMet(dickon) or knows(party, ursel_brother)) and not spread(ursel_heard_wolves)
    says "Ursel hears it standing up. Then she goes down Hay Stairs and away down the Reach alone, fast, and does not ask you to come, and you let her. She is gone an hour. When she comes back she has a cap in her hand, a big man's cap, frozen stiff. 'It's not his,' she says. 'It's not his.' She does not say whose it is, and puts it inside her coat." {
    Assert spread(ursel_heard_wolves). }
  Entity ursel_heard_wolves: fact "Ursel heard of the wolves".
  Entity drowned_wolves_told: fact "the drowned and the wolves told".

  // ── The searchers, Kemble and Fowke: paid men ─────────────────────────────────────────────────────────────────────
  // The searchers are paid by the night, not by the head, and will walk the other end of the river for more.
  Relation searchersBribed(group).
  Action bribe_searchers(actor: group, site: place) "Offer the searchers three coin a man to walk the downs road tonight instead of the Reach" {
    Requires able(actor) and company(actor) and at(actor, site) and at(searchers, site) and able(searchers) and (secondDay() or thirdDay()) and not iceGone()
      and quantity(actor, gold) >= 9 and not searchersBribed(actor) and not searchersDiverted(lisk) and tolerates(searchers, actor).
    Time 3 minutes.
    Resolve check(actor, persuasion, dc_easy).
    On success { Decrease quantity(actor, gold) by 9. Assert searchersBribed(actor). Assert searchersDiverted(lisk). }
    On failure { Decrease quantity(actor, gold) by 9. Assert searchersBribed(actor). Assert harkerWary(harker). }
    Result "The eldest of them bites each coin, which is a thing you have only ever seen done in ballads. 'Downs road,' he says. 'Footprints. There's always footprints on the downs road, if you look.' He puts the coins in his cheek. 'We're paid by the night, master. Not by what we find.'".
    Otherwise "They take the money, all of it, and thank you, and that evening Kemble knows what you paid and who you paid it to, and the searchers walk the Reach all the same, nine coin the warmer.".
  }
  // Kemble drinks at the Lamb in the evenings, and talks when he has drunk, and sleeps; and the bondhouse key is on
  // a chain at his waistcoat.
  Relation kembleDrunk(group). Relation kembleTalked(group).
  Kind bond_key_kind "a heavy iron key" is gear worth 0 weighing 0 described "A heavy iron key on a brass ring, with HAY WHARF stamped on the bow.".
  Item bond_key "Kemble's bondhouse key" is bond_key_kind at limbo.
  Action gin_kemble(actor: group, site: place) "Stand Silas Kemble hot gin at the Lamb, one after another, and listen" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lamb) and at(kemble, lamb) and quantity(actor, gold) >= 3 and not kembleDrunk(actor) and not iceGone().
    Time 6.
    On success { Decrease quantity(actor, gold) by 3. Assert kembleDrunk(actor). Assert knows(actor, hired_sold). Assert kembleTalked(actor). }
    Result "Hot gin with Bel's honey in it, and then another, and Kemble's red nose goes redder and his voice goes up, thin and confiding, a clerk's voice, all figures. 'Eight a head,' he says, at the fourth, to his glass. 'Eight a head, landed, and it costs him a farthing a day to keep them in that barn. Gallowmoor. Gallowmoor's the hills, I suppose, in a manner of speaking. Very deep hills.' He laughs at that, a long time, and then puts his head on his arms on the table, and the key on his waistcoat chain swings and taps against the bench.".
  }
  Action lift_kemble_key(actor: group, site: place) "Unhook the bondhouse key from Kemble's waistcoat chain while he sleeps on the table" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lamb) and at(kemble, lamb) and kembleDrunk(actor) and at(bond_key, limbo) and not iceGone().
    Time 1 minute.
    On success { Assert at(bond_key, lamb). }
    Result "The chain is a cheap one and the hook comes undone with a thumbnail. Kemble says 'Seven, eight,' into his sleeve, and does not wake. Bel, behind her plank, watches you do it, and goes on wiping a cup.".
  }
  Action unlock_bond(actor: group, site: place) "Unlock the bondhouse door with Kemble's key" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hay_wharf) and carries(actor, bond_key) and state(bond_lock, locked).
    Time 1 minute.
    On success { Assert state(bond_lock, open). }
    Result "The key goes in stiff with frost and turns with a sound like a dropped pan.".
  }
  // Old Fowke will drink anything, and drinks it faster in company.
  Relation sodden(group).
  Action sodden_fowke(actor: group, site: place) "Sit down by old Fowke's brazier with a bottle of Bel's gin, and keep him company" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hay_wharf) and at(fowke, hay_wharf) and not asleep(fowke) and not sodden(fowke) and quantity(actor, gold) >= 2.
    Time 6.
    On success { Decrease quantity(actor, gold) by 2. Assert sodden(fowke). Assert asleep(fowke). }
    Result "He looks at the bottle for some time, as if it were a bad dog he had met before. Then he moves up on his keg. He tells you about the last Frost, when he was a young man and walked across the river to Bankside on the ice for a bet and came back married; about his wife, who is dead; about Harker, who pays on the nail; about the noises the bondhouse makes in the night, which are only the fleeces settling. By the bottom of the bottle he is asleep with his chin on his chest, and the brazier ticks.".
  }
  Rule fowke_sobers when sodden(fowke) and hour(clock) == 7 { Retract sodden(fowke). }
}

data/adventures/low-water/after.kyr:
Module lowwater "Low Water" {
  Description "What people say once things have happened: after the Seventh is sung again, after the Hearing, after the count, and before the Assessor goes.".

  // Isaura, after the Hearing.
  Topic isaura_after_accord with isaura travelling "Ask Isaura what happens to her now" when verdictAccord(ammerlin) once {
    Says "'The Registrar has offered me Second Grade.' Isaura says it as if reporting a rainfall. 'To keep the new right. Every morning, the Ninth Lock: was the Seventh sung, did the Deep come down, how much went over the lip. A cupful, measured, written, read aloud at need.' She is quiet a moment. 'They've promoted me into exactly the thing I wanted to do, which was measure something nobody else would. I'd assumed promotion would be the opposite.' Then, because she is honest: 'I said yes before she'd finished the sentence. Noted.'".
  }
  Topic isaura_after_rejected with isaura travelling "Ask Isaura how she is, after the Council" when findingRejected(ammerlin) once {
    Says "'We told them a thing they didn't want to have to decide, and they decided not to have heard it.' She does not sound bitter. She sounds as if she is getting a column straight. 'They closed the Channel. The Mere will still fall, a little slower, and by midwinter they'll know.' She closes her book. 'I'll be there when they know. With the tally. I'm not going anywhere. That's what the Office is for, I think. Not being right at the Hearing. Being there afterwards with the figures.'".
  }
  Topic isaura_after_break with isaura travelling "Ask Isaura what the Council's order to break the governor means to her" when verdictBreak(ammerlin) once {
    Says "'It means the forty ells come home.' She is careful. 'It means the Mere fills. It means my tally will close every week for the rest of my life, to the half-ell.' A long pause. 'It means the only thing I have ever met that I could not put in a column goes away, and I'll never know what it was.' She tucks the book away. 'I voted for the columns. I'd like it recorded that I knew what I was voting for.'".
  }
  Topic isaura_after_lapsed with isaura travelling "Ask Isaura what happened at the Hearing" when registrarsFinding(ammerlin) once {
    Says "She looks at you for a while before she answers, and you understand that she has been deciding whether to. 'The Registrar gave the Office's finding. The Guild. I sat at the back with my tally in my coat and didn't stand up.' She takes a breath. 'Nobody asked me to. That's not a reason. It's a fact.' She walks on. 'Noted,' she says, after a while, to herself.".
  }
  Topic isaura_farewell with isaura travelling "Ask Isaura what she will say about you, when you have gone" when hearingDone(ammerlin) once {
    Says "Isaura considers the question with the care she gives everything. 'I'll say the Office engaged an outsider who didn't want anyone's water, and they went where the figures went, which is rarer than you'd think. I'll say they asked me things nobody in the Office has ever asked me. What's over the door. Whether everything can be measured. What I do when I'm not working.' The smallest smile you have seen on her. 'I'll put the cake in. Some things belong in the record.'".
  }
  Topic isaura_dov_after with isaura travelling "Ask Isaura whether she has seen her brother since" when hearingDone(ammerlin) and not drowned(diggers) and not quillDeal(quill) once {
    Says "'He came to the Office.' She seems to find this more extraordinary than anything under the Mere. 'He's never come to the Office. He stood in the hall in his boots with the whole queue looking at him and asked for Clerk-Measurer Vant, Third Grade, by her full title, which he must have practised.' She looks away. 'He wanted to know the Ward's water-right. To the half-ell. So he could tell them in Tench Row.' A breath. 'I told him. He wrote it on his hand.'".
  }
  Topic isaura_dov_lost with isaura travelling "Ask Isaura whether she has seen her brother since" when hearingDone(ammerlin) and quillDeal(quill) once {
    Says "'No.' Very level. 'The Ward plots are sealed to the Guild. I sealed them; it was my turn at the counter.' She does not look at you. 'He came to the Office door and saw who was at the counter and went away again.' She squares the ledger on the counter. 'I'd do it again. It was the bargain that saved the Mere. I'd like that to be enough. Noted that it isn't.'".
  }

  Topic isaura_dissent with isaura travelling "Ask Isaura why she stood up against the Finding" when dissented(isaura) once {
    Says "'Because it was wrong.' She does not look at you. 'You named the Guild with my tally lying on the table saying it wasn't the Guild. I told you I'd sign what's true.' A long breath. 'You may have had reasons. The Council wanted a name; you gave them one they could act on. I understand the reasons.' She walks on. 'I'm not paid to understand reasons. I'm paid to read what the figures say, out loud, at need. That was the need.'".
  }
  // Dov, after.
  Topic dov_after_kept with dov "Ask Dov how the Ward is" when hearingDone(ammerlin) and wardKept(ammerlin) and not drowned(diggers) once {
    Says "'Still here.' Dov grins, and it is the first unguarded thing you have seen him do. 'The Office froze Basset's buying and the Council's to examine the titles, which Measure says means the Office will read every deed in the Ward aloud in the square for a month and argue about commas. Good. Let them.' He looks out at the mud. 'And the water'll come back. Slow. My grandson'll fish off the fourth step.' He thinks. 'I haven't got a grandson. I'd better get on with it.'".
  }
  Topic dov_after_sealed with dov "Ask Dov how the Ward is" when quillDeal(quill) and decided(council) once {
    Says "Dov looks at you for a long moment before he answers. 'The Guild has the dig. And the Hall. And half Tench Row, sealed by the Office, my sister's hand on the seal.' He is not shouting, which is worse. 'The water's coming back, they tell me. Good. We'll be able to see it from the Guild's fence.' He turns away. 'You did right by the Mere, Assessor. You did right by everything but us. That's what the Ward always gets: right by everything but us.'".
  }
  Topic dov_engine with dov "Tell Dov what is under the Ward" when knows(actor, engine_seen) once {
    Says "Dov listens to all of it with his arms folded. 'Under us,' he says at the end. 'All the time. Drinking the Mere through a hole in the floor, counting.' He laughs, short. 'My grandfather used to say the Mere had a bottom made of ears. To listen to the fishermen lie. I thought it was a joke.' He spits, thoughtfully. 'What's it counting?' You tell him what Halm thinks. 'Souls,' says Dov. 'Huh. Well, it's had a few of ours. It can count those.'".
  }
  Topic dov_dam_after with dov "Ask Dov how it went at the breach" when cofferdam(dig) and breached(dig) and not drowned(diggers) once {
    Says "'Dry as a sermon.' He is enormously pleased with himself and is trying to be pleased with his sister instead. 'Hob put the pick through and the dam held and the silt just sat there, and a cold wind came up out of the hole like a cellar's breath.' He clears his throat. 'Hob Kettle and his girl were in that hole. Tell Measure. No, I'll tell her. I'll tell her myself.'".
  }

  // Quill, the sophist, and after.
  Topic quill_believe with quill "Ask Quill whether he believes his own arguments" when met(quill, quill_room) once {
    Says "'Which ones?' Quill is delighted to be asked. 'I was trained by a man in Corran who made us argue both sides of everything, twice, and then tell him which we had believed. The trick, he said, is that you always believe the one you're making while you make it. It's the only way to make it well.' He turns his glass. 'So: yes. Always. While I'm saying it. Afterwards I go back to believing what's useful, which is a different discipline.' A pause, and something more honest. 'It's very restful, Assessor, never having to be only one person. You should try it. No. You shouldn't. You'd be bad at it, and that's why I trust you.'".
  }
  Topic quill_after_renewed with quill "Ask Quill how the Guild stands now" when charterRenewed(ammerlin) once {
    Says "'Solvent.' He says it like a man tasting a wine he had given up on. 'The creditors have been told about the charter, and believed it, which in my trade is the same thing as money. The hands are paid.' He looks at you over the glass. 'You might have named me. It would have been easy, and half the hall wanted it. I've been wondering why you didn't.' He answers himself before you can. 'Because it wasn't true. How tiresome. How very rare.'".
  }
  Topic quill_after_lost with quill "Ask Quill how the Guild stands now" when charterLost(ammerlin) once {
    Says "'Ruined.' Quill is quite calm. 'Candlemas, as I said. The creditors will have the mills, and the mills will stand, because a mill without water is a brick barn.' He pours, and does not drink. 'Four hundred people. I said I'd like you to remember them, Assessor. I hope you did, when you were deciding.' He sets the glass down. 'And the Mere will go on falling. You know it will. Write to me in the spring and tell me which of us was the sliver.'".
  }

  // The Registrar, after.
  Topic fenn_after with fenn "Ask the Registrar what she makes of the Finding" when decided(council) and not registrarsFinding(ammerlin) once {
    Says "Registrar Fenn does not stop writing for a while. 'I asked you for something that would still be standing at the end of the afternoon,' she says. 'It's still standing. That is more than I have managed in eleven years.' She looks up. 'You also showed the Council that the Office's own ledger was wrong for three years, in front of the whole Bowl, with my best clerk reading it out. I shall be answering for that until I retire.' She caps her pen. 'I find I don't mind. That's the part I can't account for.'".
  }
  Topic fenn_vant_after with fenn "Ask the Registrar what will become of Clerk Vant" when decided(council) and not registrarsFinding(ammerlin) once {
    Says "'Second Grade, whether she likes it or not.' The Registrar almost smiles. 'She'll tell me she'd rather measure than check other people's measuring. I'll tell her that's exactly why. She'll say noted.' She caps her ink. 'She stood up in the Moot Hall and said the Office was wrong, with the Office's seal behind her. I've wanted somebody to do that for eleven years. I never thought it would be a Third Grade clerk from the Ward.'".
  }

  // The Sounding, after.
  Topic tamsin_after with tamsin "Ask Merrin how the singing is now" when restoredForGood(bowl) once {
    Says "'Packed.' Merrin is glowing. 'More than before. People come to hear the Seventh. The counting one.' She giggles. 'Jessa says we're the lock-keepers now, all of us, and the boys at the back have started calling the low notes the Cupful.' Then, seriously: 'Cantor Orr says if we sing it wrong the Ward goes dry. She's joking. She's mostly joking. Nobody sings it wrong.'".
  }
  Topic fisk_right with fisk "Ask Precentor Penhale whether he was right" when knows(actor, hymn_cause) and restoredForGood(bowl) once {
    Says "Penhale draws himself up for a speech, and then, unexpectedly, does not make it. 'I said it was the Remainders,' he says. 'I said the dead were going down and away.' He looks down through the grating at the black water. 'It was the Remainders. It was not the dead. It was a gate, and a machine, and a girl's reform, and a boy's book.' He is silent. 'I had the conclusion and none of the reasons. That's not faith, Assessor. That's luck wearing a cassock.' And then, with a flicker of his old self: 'Still. I'll take the luck.'".
  }
  Topic orr_after with orr "Ask Cantor Orr how she is" when orrStanding(orr) and hearingDone(ammerlin) once {
    Says "'Old,' says Cantor Orr. 'Sorry. Busy. In that order, most days.' She plays a chord, in tune for once. 'The young sing the Seventh as if it were the best part, which it isn't, and I let them, because it's the part that's for something.' She closes the lid. 'I'll tell you what I didn't expect. I didn't expect to like the counting. Four low notes, alike. I hated them for fifty years. Now I stand in the loft and the whole nave counts with me, and under the floor something counts back.' She looks at you. 'It's the best building I've ever stood in.'".
  }

  // Abel Tarrant goes down to the Ninth Lock once more.
  Relation abelComes(group).
  Topic abel_seventh with abel "Tell Abel Tarrant the Seventh is sung again, and the Deep comes down" when restoredForGood(bowl) and not abelComes(abel) once {
    Says "Abel does not say anything at all. He gets up, takes the brass horn off its nail, looks at it, and puts it back. 'Tonight,' he says. 'I'll go down tonight. I'd like to see it the once more. If Piet will have an old man on his bench.' He is already looking for his coat.".
    On discuss { Assert abelComes(abel). }
  }
  Rule abel_goes_down when abelComes(abel) and hour(clock) == 18 and at(abel, lusk_room) { Retract at(abel, lusk_room). Assert at(abel, ninth_lock). }
  Rule abel_goes_home when abelComes(abel) and hour(clock) == 22 and at(abel, ninth_lock) { Retract at(abel, ninth_lock). Assert at(abel, lusk_room). Retract abelComes(abel). Assert abelSaw(abel). }
  Relation abelSaw(group).
  Observe abel_and_piet at ninth_lock when at(abel, ninth_lock) and at(piet, ninth_lock) "Abel Tarrant and Piet Harl sit side by side on the keeper's bench, the old man and the young one, both with their hands on their knees, both watching the Deep Gate, neither saying anything.".
  Topic abel_saw with abel "Ask Abel how it was, at the Ninth Lock" when abelSaw(abel) once {
    Says "'Same as ever,' says Abel, and his voice goes. 'Same as it ever was. Up at the Sixth, down at the Seventh. Cupful.' He wipes his eyes on his sleeve without any embarrassment at all. 'Piet wrote it in capitals. I told him off.' He laughs. 'I didn't mean it.'".
  }

  // Sella, after.
  Topic sella_after with sella "Ask Sella Quenby whether the hands were paid" when paidHands(sella) once {
    Says "'Lammas to now, every penny.' Sella does not quite smile. 'You said it first, at the Council. Before anything. I was at the back. I heard it.' She looks at the hammers going. 'I had a bet with myself you'd forget.' A pause. 'I'm glad I lost.'".
  }
  Topic sella_forgotten with sella "Ask Sella Quenby how things are at the mills" when promised(party, sella) and hearingDone(ammerlin) and not laid(ex_hands) once {
    Says "Sella does not look at you. 'You promised,' she says. 'First, before anything. I gave you the report on it.' She turns back to the hammers. 'I had a bet with myself you'd forget. I won.'".
  }

  // The Bowl, later: what a company that stays, or comes back, finds.
  Observe later_ward_filling at ward_landing when decided(council) and mere(bowl) >= 38 and not draining() "There is water at the lowest painted step of the Ward landing again, and somebody has tied a boat to the old ring there, out of hope rather than need.".
  Observe later_ward_empty at tench_row when complete(reckoner) and not completedFed(reckoner) and wardEmpty(ammerlin) and watch(clock) >= completedAt(bowl) + 144 "A Guild cart is loading the Ward's last nets. On a door somebody has chalked, in the Lock-Rhyme's beat: RISE AT THE SIXTH AND THE DEEP GOES UP. Under it, in another hand: AND NEVER CAME DOWN.".
  Observe later_sounding at nave when restoredForGood(bowl) and hearingDone(ammerlin) "Someone has painted the Seventh Remainder round the rim of the bronze grating in the Sounding's old notation, four low marks over and over, all the way round, like a fence.".
}

data/adventures/low-water/auditor.kyr:
Module lowwater "Low Water" {
  Description "What has been reading the counted water: the Reflected that climb out of the Mere at night, the hymnal that came with its cuts already marked, and the Second Reader of the Collegium.".

  // The approach: something on the far side of the last door, coming nearer every night the count goes on. It comes
  // faster as the count nears whole and as the Mere draws back, and slower while the Fourth is sung.
  Measure approach(place). Relation approachedTonight(place). Relation reflectedStilled(place).
  Rule approach_nightly when hour(clock) == 0 and not approachedTonight(bowl) and not broken(reckoner) and not countFalsified(reckoner) and not auditorSettled(bowl) {
    Assert approachedTonight(bowl). Increase approach(bowl) by 1. }
  Rule approach_count when hour(clock) == 0 and approachedTonight(bowl) and ninths(reckoner) >= 7 and not countPressed(bowl) and not broken(reckoner) and not fourthRestored(bowl) {
    Assert countPressed(bowl). Increase approach(bowl) by 1. }
  Rule approach_low when hour(clock) == 0 and approachedTonight(bowl) and mere(bowl) <= 30 and not lowPressed(bowl) and not broken(reckoner) {
    Assert lowPressed(bowl). Increase approach(bowl) by 1. }
  Rule approach_resets when hour(clock) == 12 and approachedTonight(bowl) {
    Retract approachedTonight(bowl). Retract countPressed(bowl). Retract lowPressed(bowl). Retract reflectedStilled(bowl). Retract risenTonight(bowl). }
  Relation countPressed(place). Relation lowPressed(place).
  // Broken, the count feeds nothing, and what stood on the water lies down in it.
  Rule approach_starved when broken(reckoner) and approach(bowl) > 0 { Set approach(bowl) to 0. }
  // How many of them there are: Isaura counts them, of course.
  Measure reflectedSeen(place).
  Rule reflected_counted when approach(bowl) * 3 != reflectedSeen(bowl) { Set reflectedSeen(bowl) to approach(bowl) * 3. }

  // The Reflected: water that has learned to stand up in the shapes of people, left for right.
  Person reflected "the Reflected" at mere_edge {
    Role "figures of water, standing". Numbers 3. Peaceable.
    Seen when dark() and approach(bowl) >= 1 and not broken(reckoner).
  }
  Topic reflected_spoken with reflected "Speak to the figures of water" when not reflectedStilled(bowl) once {
    Says "None of them answers. The nearest turns its clear face toward you, and its lips move with yours a breath behind, the wrong way round: what you said, said backwards, without a sound. Then it turns back to face the Sounding and goes on singing, as if you were a thing it had already counted.".
  }
  Hazard reflected_cold "The cold of the Reflected" means "Deal (1d6) necrotic damage to ally unless wisdom save against (12).".
  Rule reflected_rise when hour(clock) == 22 and approach(bowl) >= 2 and at(reflected, mere_edge) and not reflectedStilled(bowl) and not broken(reckoner) {
    Retract at(reflected, mere_edge). Assert at(reflected, ward_landing). }
  Rule reflected_climb when hour(clock) == 23 and approach(bowl) >= 3 and at(reflected, ward_landing) and not reflectedStilled(bowl) and not broken(reckoner) {
    Retract at(reflected, ward_landing). Assert at(reflected, ninth_lock). }
  Rule reflected_go_down when hour(clock) == 5 and not at(reflected, mere_edge) {
    Retract at(reflected, ward_landing). Retract at(reflected, ninth_lock). Retract at(reflected, measures_square). Assert at(reflected, mere_edge). }
  Rule reflected_square when hour(clock) == 1 and approach(bowl) >= 6 and at(reflected, ninth_lock) and not reflectedStilled(bowl) and not broken(reckoner) {
    Retract at(reflected, ninth_lock). Assert at(reflected, measures_square). }
  // At the Ninth Lock in the small hours they sing the Rising, and the Deep Gate obeys whoever sings it.
  Rule reflected_sing_rising when hour(clock) == 23 and at(reflected, ninth_lock) and state(deep_gate, lowered) and not reflectedStilled(bowl) and not risenTonight(bowl)
    and not complete(reckoner) and not broken(reckoner)
    says "Far down the terraces, in the dark, somebody is singing: the Sixth Remainder, the Rising, one deep note and three bright, over and over, in voices with no breath behind them. Then a sound you have learned to know from anywhere in the Bowl: the bronze of the Deep Gate heaving itself up on edge." {
    Assert state(deep_gate, raised). Increase risings(bowl) by 1. Assert risenTonight(bowl). }
  Relation risenTonight(place).
  Measure risings(place).
  // Where they stand, the cold comes off them: an hour among them is an hour of it.
  Measure lastChill(place).
  Rule reflected_chill when at(reflected, ?p) and at(party, ?p) and dark() and approach(bowl) >= 1 and not reflectedStilled(bowl) and not broken(reckoner) and watch(clock) >= lastChill(bowl) + 6
    says "The cold that comes off the Reflected is not the cold of water. It goes in under the ribs and stays there." {
    Set lastChill(bowl) to watch(clock). Assert strikes(reflected_cold, party). }

  Observe reflected_seen near reflected when dark() and approach(bowl) >= 1 and not broken(reckoner) and not reflectedStilled(bowl) "Figures stand at the edge of the water in the dark: people, or the shapes of people, made of water that has been made to stand up, clear as glass, with the night showing through them. {reflectedSeen(bowl)} of them, or near it; they are hard to count, being clear. They face the Sounding. They are singing, very softly, without breath. Every one of them is the wrong way round, as a face is in a mirror.".
  Observe reflected_annet near reflected when dark() and drowned(diggers) and approach(bowl) >= 1 and not reflectedStilled(bowl) "One of them is a girl of fifteen with a basket on her hip. She is wet through, because she is water. It is Annet Kettle.".
  Observe reflected_isaura near reflected when dark() and travelsWith(isaura, party) and approach(bowl) >= 3 and not reflectedStilled(bowl) "One of them is a woman in a long coat with a rod under her arm: the wrong arm. Beside you, Isaura Vant has stopped walking.".
  Observe reflected_still near reflected when dark() and reflectedStilled(bowl) and approach(bowl) >= 1 "The Reflected lie down in the water as you watch, the way a reflection does when a stone is thrown, and the water closes and is only water.".
  Discovery reflected_known "At night, figures of water climb out of the Mere in the shapes of people, left for right, and sing the hymn without breath; and at the Ninth Lock they sing the Rising, and the Deep Gate rises for them.".
  Rule reflected_learned when at(reflected, ?p) and at(party, ?p) and dark() and approach(bowl) >= 1 and not knows(party, reflected_known) and not broken(reckoner)
    says "You look for a long time before you are sure what you are looking at." teaches reflected_known { }
  // They can be sung down: the Seventh, which they cannot abide, being the verse that keeps the door's mouth small.
  Action sing_down(actor: group, site: place) "Sing the Seventh Remainder at the Reflected, four deep notes, over and over" {
    Description "Deep, deep, deep, deep. The cupful.".
    Requires able(actor) and company(actor) and at(actor, site) and at(reflected, site) and dark() and knows(actor, remainders_tones) and not reflectedStilled(bowl) and approach(bowl) >= 1.
    Time 2.
    On success { Assert reflectedStilled(bowl). }
    Result "You sing it badly, and then less badly: four low notes, alike, over and over, like somebody counting. The Reflected stop singing. They turn their clear faces toward you, all together, and listen, and one by one they go down into the water as if somebody had let go of them.".
  }

  // Piet's book, and the Ward's people, after.
  Topic piet_rising with piet "Ask Piet about the Deep Gate rising in the night" when risings(bowl) >= 1 once {
    Says "Piet shows you the book. Under Down at the Seventh. Cupful, in his careful hand, a second line, shaking: Deep up at the Rising, after eleven. Not by the Sounding. 'They came up the Ward steps,' he says. 'Out of the water. They stood round the lock and sang the Sixth, and it went up. It doesn't care who sings.' He swallows. 'Master Tarrant never said anything about that. Master Tarrant never said anything about any of it.'".
  }
  Topic dov_reflected with dov "Ask Dov about what comes up out of the Mere at night" when approach(bowl) >= 2 once {
    Says "Dov does not laugh, which is how you know. 'The Ward's keeping its doors shut after dark,' he says. 'First it was children saying it. Then old Marra. Then me.' He rubs his face. 'They stand on the landing, facing up the Bowl, and they sing. They look like people we know, only wrong-handed. My father was there last night. He drowned off the Tench nineteen years ago and he was there, with his net over the wrong shoulder.'".
  }
  Topic dov_annet with dov "Ask Dov what he saw on the landing" when drowned(diggers) and approach(bowl) >= 1 once {
    Says "'Annet Kettle.' Dov says it to the ground. 'With her basket. Standing on the landing with the rest of them, clear as a glass of water, singing.' He looks up. 'Hob went down to her. I had to hold him. She didn't look at him. She was looking at the Sounding. They all look at the Sounding.'".
  }
  Topic fisk_reflected with fisk "Ask Precentor Penhale about the Reflected" when knows(actor, reflected_known) once {
    Says "For once Precentor Penhale takes no satisfaction in being right. 'Every soul a drop,' he says. 'I said it at three Councils. I said they went down, and away.' He is grey. 'I never thought they could come back up. I never thought anything down there would want them to.'".
  }
  Topic isaura_reflected with isaura travelling "Ask Isaura how many of them there were" when knows(actor, reflected_known) {
    Says "'{reflectedSeen(bowl)}, as near as I could count; they're hard to count, you can see through them to the ones behind.' She says it flatly, the way she reads gauges. Then: 'More every night.' Then, not flatly at all: 'There was one of me. Did you see? With the rod in the wrong hand.' She looks at her own right hand for a while. 'Noted.'".
  }
  Topic orr_midnight with orr "Ask Cantor Orr to sing the Seventh again at midnight, after the Reflected sing the Rising" when risings(bowl) >= 1 and seventhRestored(bowl) and not midnightSeventh(bowl) once {
    Says "'At midnight.' Cantor Orr looks at you as if you had asked her to sing on the roof. Then she understands what you are telling her, and her face closes like a fist. 'They're singing my hymn back at it. Out of the water.' She stands. 'Then we'll sing it louder. Compline, at midnight, the Seventh and nothing else. The young will come. They'll come for this.'".
    On discuss { Assert midnightSeventh(bowl). }
  }
  Relation midnightSeventh(place). Relation sungMidnight(place).
  Rule compline when hour(clock) == 0 and midnightSeventh(bowl) and not sungMidnight(bowl) and not complete(reckoner) and not broken(reckoner)
    says "At midnight the Sounding's bells ring once, and the Seventh comes down the terraces: four low notes, a thousand voices, slow and furious." {
    Assert sungMidnight(bowl). Assert state(deep_gate, lowered). }
  Rule compline_resets when hour(clock) == 12 and sungMidnight(bowl) { Retract sungMidnight(bowl). }

  // The hymnal Orr cut from: a scholarly edition, a gift, with the cuts already marked in a hand not hers.
  Thing orr_hymnal "the Cantor's working hymnal" at cantor_room {
    State marked "On the clavichord lies the hymnal the Cantor works from, a handsome edition in green boards, its pages scored with her pencil.".
    Tries looking.
  }
  Discovery cuts_marked "In the hymnal Cantor Orr cut the Long Hymn from, the Fourth, Fifth and Seventh Remainders were struck through before she ever touched it, in fine brown ink, in a hand that is not hers; and only those three.".
  Rule hymnal_looked when tried(orr_hymnal, looking) and not knows(party, cuts_marked)
    says "Her pencil is everywhere: breath-marks, tempi, a cross beside a soprano who sings flat. But under the pencil, on three pages only, there is something older: the Fourth, the Fifth and the Seventh Remainders struck through, each with a single fine line of brown ink, and in the margin, very small, in a hand that is not hers: Accretion. Omit." teaches cuts_marked { }
  Discovery pell_named "Cantor Orr's hymnal was a gift of the Collegium of Lesser Instruments, sent with the compliments of its Second Reader, Master Ansel Pell, the spring before the reform.".
  Topic orr_cuts with orr "Ask Cantor Orr who marked the cuts in her hymnal before she did" when knows(actor, cuts_marked) once {
    Says "She takes it from you and looks at the brown lines for a long time. 'The Collegium,' she says. 'The Collegium of Lesser Instruments sent it. A scholarly edition, they said, prepared from the oldest sources, with notes by the Second Reader. Master Pell.' Her voice is very quiet. 'I thought it a great compliment. I thought the notes very learned. Accretion; omit.' She closes the book. 'I cut what a scholar told me was silt, because I wanted to, and he knew I wanted to. Well. That's a sentence I'll have to learn to say.'".
    On discuss { Assert knows(actor, pell_named). }
  }

  // The Second Reader's letters, and what is in their footnotes.
  Discovery pell_letters "Halm was sent to Ammerlin by the Second Reader of the Collegium, Master Ansel Pell, who pays for his stones; Pell's letters are dense with numbered footnotes, as the Collegium's always are.".
  Topic halm_pell with halm "Ask Halm who sent him to Ammerlin" when knows(actor, pell_named) or knows(actor, reflected_known) once {
    Says "'Pell. The Second Reader.' Halm is pleased to talk about him. 'Brilliant man. Never leaves Corran. He knew there was a working instrument under the Bowl before anybody; he said the Ammerliners' hymn had the shape of output, and the Ward would dig itself down to it once the Mere fell. He was right about all of it.' He fishes a fat letter out of his coat. 'He writes every month. Everything in the footnotes, of course. It's a Collegium habit; the footnotes are where we put what matters.' He hands it to you. 'Here. Read it, you'll see what I mean about him.'".
    On discuss { Assert knows(actor, pell_letters). }
  }
  Discovery pell_cipher "The footnote numbers in Pell's letters to Halm are a tally, and read as one they spell: WHEN THE COUNT IS WHOLE LET IT THROUGH. THE LOCK IS CUT. THE READER IS NEAR. MERROW NEXT.".
  Topic isaura_footnotes with isaura travelling "Ask Isaura to look at the footnotes in Pell's letter" when knows(actor, pell_letters) and not knows(actor, pell_cipher) once {
    Says "Isaura reads the letter once, as anyone would, and then a second time, only the little numbers. Then she gets her graphite out. 'They don't go in order,' she says. 'Footnotes go in order. These go three, nineteen, five, two... and the notes they point to don't say anything a footnote would.' She writes on her knee, fast, in figures the size of seeds. 'It's a tally. Every number is a letter's place. Whoever wrote this thinks in columns, the way I do.' She turns the page round so you can read what she has written, and her hand is not quite steady. WHEN THE COUNT IS WHOLE LET IT THROUGH. THE LOCK IS CUT. THE READER IS NEAR. MERROW NEXT.".
    On discuss { Assert knows(actor, pell_cipher). }
  }
  Relation halmTurned(group).
  Topic halm_cipher with halm "Show Halm what the footnotes in Pell's letter say" when knows(actor, pell_cipher) and not halmTurned(halm) once {
    Says "Halm reads Isaura's columns three times. The colour goes out of him. 'The lock is cut,' he says. 'The Fourth. He meant the Fourth.' He sits down on whatever is there. 'He sent the Cantor her edition. He sent me. He sent me to be here when it finished so I could tell him it had.' He looks at you, and for the first time there is nothing delighted in his face at all. 'The Reader is near. Who is the Reader? What has been reading it?' And then, much lower: 'Merrow. The keeper of the Long Man. The clay keeper that walks the wall. He asked me last spring if I knew anybody going north.'".
    On discuss { Assert halmTurned(halm). Assert halmStopped(halm). Assert willTestify(halm). }
  }

  // The column hears a voice it has no mark for.
  Discovery fifth_voice "At the listening column, under the engine's own answer, another voice answers: lower than the deep, a voice the Sounding's notation has no mark for, saying the struck notes back slowly, as if learning them.".
  Rule column_fifth at column_room when at(party, column_room) and spoken(column_room) >= 1 and approach(bowl) >= 1 and not knows(party, fifth_voice) and not broken(reckoner)
    says "Under the column's answer, so low you feel it in your knees before you hear it, another voice says your two notes back to you. Slowly. Carefully. As if it were learning them. It is lower than the deep voice. The hymn has no mark for it." teaches fifth_voice { }
  Topic isaura_fifth with isaura travelling "Ask Isaura what answered at the column" when knows(actor, fifth_voice) once {
    Says "'Something that isn't the machine.' Isaura says it the way she would report a second set of books. 'The machine answers in its own voices. That was another one. Underneath.' She is quiet. 'Halm asked who the count is given to. I think we heard them.'".
  }
}

data/adventures/low-water/bowl.kyr:
Module lowwater "Low Water" {
  Description "Ammerlin, a city of terraces down the inside of an old crater, whose life is carried by the water of the Stair, and whose lake is falling.".

  // The Bowl: the city on its four terraces, the bed of the Mere the water has given up, the works under it, and a
  // place that is not on any map of the Bowl.
  Place bowl "the Bowl of Ammerlin" is region.
  Place ammerlin "Ammerlin" is settlement within bowl at 1, 0.
  Place merebed "the bed of the Mere" is wilderness within bowl at 1, 1.
  Place undercroft "the Undercroft" is site within bowl at 1, 2.
  Initially Assert terrain(bowl, hills).
  // A place the company has been and left is familiar: it is told again in a line, not in full.
  Relation familiar(place).
  Rule familiar_place when been(party, ?p) and not at(party, ?p) and not familiar(?p) { Assert familiar(?p). } Initially Assert landform(merebed, land_lake).

  // What the Bowl's water does, reckoned every eight hours: the Mere, in spans on the Ward gauge; the Reckoner's
  // count, of nine hundred; and the ninths of it its own voice can say.
  Kind engine. Entity reckoner: engine "the Reckoner".
  Measure mere(place). Measure count(engine). Measure ninths(engine). Measure nextReckon(place). Measure nextDay(place).
  Measure reckonings(place).
  Initially Set mere(bowl) to 40. Initially Set count(reckoner) to 640. Initially Set ninths(reckoner) to 6.
  Initially Set nextReckon(bowl) to 48. Initially Set nextDay(bowl) to 132.
  Relation complete(engine). Relation broken(engine). Relation starved(engine).

  // The Deep Gate: a bronze shutter in the floor of the Ninth Lock with no wheel and no chain. The engine moves it by
  // what it hears. It has stood raised since the Short Hymn was first sung.
  Thing deep_gate "the Deep Gate" at ninth_lock {
    State raised "In the floor of the Ninth Lock's lowest chamber a bronze shutter the width of a cart stands up on its edge, and the water of the lock goes down past it into the dark with a sound like a long breath taken and never let out.".
    State half "The bronze shutter of the Deep Gate stands half down. The water goes past it into the dark in a fast smooth tongue.".
    State lowered "The bronze shutter of the Deep Gate lies down in its bed. A thread of water, no thicker than a wrist, runs over its lip and down. That is all.".
    State logged "Oak stop-logs lie jammed across the Deep Gate's mouth, one on another, black with wet. Water goes over the top log in a thin sheet, and the bronze under it shudders now and then, as if it were trying to rise.".
  }

  // The reckoning. Each rule is tried in the order written; the last moves the time of the next reckoning on.
  Rule reckon_raised when watch(clock) >= nextReckon(bowl) and state(deep_gate, raised) and not fed(reckoner) and not complete(reckoner) and not broken(reckoner) {
    Decrease mere(bowl) by 1. Increase count(reckoner) by 12. }
  Rule reckon_half when watch(clock) >= nextReckon(bowl) and state(deep_gate, half) and not fed(reckoner) and not complete(reckoner) and not broken(reckoner) {
    Increase count(reckoner) by 6. Increase halfDrawn(bowl) by 1. }
  Rule reckon_half_drawn when halfDrawn(bowl) >= 2 { Decrease mere(bowl) by 1. Set halfDrawn(bowl) to 0. }
  Rule reckon_fed when watch(clock) >= nextReckon(bowl) and fed(reckoner) and not complete(reckoner) and not broken(reckoner) {
    Increase count(reckoner) by 60. }
  Rule reckon_moves when watch(clock) >= nextReckon(bowl) { Increase nextReckon(bowl) by 48. Increase reckonings(bowl) by 1. }
  Measure halfDrawn(place).
  // Every other morning, what the Channel at the Rim costs the Mere: its mill water comes back to the Stair below the
  // Rim, all but what the fulling drinks and the drying-frames give to the air. Once a day, what it gives back when it is
  // turned home to the Mere.
  Measure nextMills(place). Initially Set nextMills(bowl) to 132.
  Rule day_mills when watch(clock) >= nextMills(bowl) and state(channel_gate, to_mills) { Decrease mere(bowl) by 1. }
  Rule mills_moves when watch(clock) >= nextMills(bowl) { Increase nextMills(bowl) by 288. }
  Rule day_mends when watch(clock) >= nextDay(bowl) and state(channel_gate, to_mere) and not draining() and mere(bowl) < 40 { Increase mere(bowl) by 1. }
  Rule day_moves when watch(clock) >= nextDay(bowl) { Increase nextDay(bowl) by 144. }
  Query draining() means (state(deep_gate, raised) or state(deep_gate, half)) and not fed(reckoner) and not complete(reckoner) and not broken(reckoner).
  Relation fed(engine).
  Rule fed_by_channel when state(channel_gate, to_deep) and not fed(reckoner) { Assert fed(reckoner). }
  Rule unfed when fed(reckoner) and not state(channel_gate, to_deep) { Retract fed(reckoner). }
  Rule ninth_counted when count(reckoner) >= ninths(reckoner) * 100 + 100 and ninths(reckoner) < 9 { Increase ninths(reckoner) by 1. }

  // The hymn, at dusk. The Short Hymn keeps the Sixth Remainder (the Rising) and leaves out the Seventh; the engine,
  // listening down the cistern under the Sounding, raises the Deep Gate at the one and has not heard the other for
  // three years. Restored, the Seventh is sung at eight.
  Relation sungTonight(place). Relation seventhTonight(place). Relation seventhRestored(place). Relation longHymn(place).
  Relation hymnSilenced(place).
  Rule hymn_rises when hour(clock) == 19 and not sungTonight(bowl) and not hymnSilenced(bowl) and not broken(reckoner) and not complete(reckoner)
    and not state(deep_gate, logged) and not state(deep_gate, raised) {
    Assert state(deep_gate, raised). }
  Rule hymn_after_census when hour(clock) == 19 and not sungTonight(bowl) and not hymnSilenced(bowl) and complete(reckoner)
    says "The Hymn, at seven. The bells are the same and the choir is the same, and something under it is not: the water does not answer. Down through the terraces, where for three thousand years the cisterns rang with it, there is only stone." {
    Assert sungTonight(bowl). }
  Rule hymn_after_broken when hour(clock) == 19 and not sungTonight(bowl) and not hymnSilenced(bowl) and broken(reckoner)
    says "Seven, and the bells. It sounds thinner than it did, and it takes you a moment to know why: under them, where the water of the whole Bowl used to take the note and hand it back, nothing hands it back." {
    Assert sungTonight(bowl). }
  Rule hymn_after_hearing when hour(clock) == 19 and not sungTonight(bowl) and not hymnSilenced(bowl) and hearingDone(ammerlin)
    says "The bells go into the Hymn, the first since the Hearing, and the Sounding must be full to the doors: you can hear the singing from the Rim to the Ward, and in the Ward, for once, people are singing too." {
    Assert sungTonight(bowl). }
  Rule hymn_ward_leaving when hour(clock) == 19 and not sungTonight(bowl) and not hymnSilenced(bowl) and wardLeaving(ammerlin) and not seventhRestored(bowl)
    says "The Hymn, at seven. Down in the Ward, where it used to come back off the Mere, nothing comes back; the mud takes it, and the handcarts in Tench Row stop, all together, while it lasts." {
    Assert sungTonight(bowl). }
  Rule hymn_day2 when hour(clock) == 19 and not sungTonight(bowl) and not hymnSilenced(bowl) and day(clock) == 2
    says "Seven o'clock, and the Sounding's bells go into the Hymn again, as they have every evening for three thousand years; and up and down the terraces, at every lock and sluice, keepers put their hands on their wheels." {
    Assert sungTonight(bowl). }
  Rule hymn_day3 when hour(clock) == 19 and not sungTonight(bowl) and not hymnSilenced(bowl) and day(clock) == 3
    says "Somewhere below you a dog howls along with the bells, is hushed, and howls again on the wrong note." {
    Assert sungTonight(bowl). }
  Rule hymn_day5 when hour(clock) == 19 and not sungTonight(bowl) and not hymnSilenced(bowl) and day(clock) == 5
    says "The bells go into the Hymn. A carter on the Stair stops his horse and takes his hat off, and then, looking round to see if anyone saw, puts it on again." {
    Assert sungTonight(bowl). }
  Rule hymn_sung when hour(clock) == 19 and not sungTonight(bowl) and not hymnSilenced(bowl) and true
    says "Over the whole Bowl, terrace below terrace, the Sounding's bells go into the Hymn, and under them, faint and enormous, the choir." {
    Assert sungTonight(bowl). }
  Rule seventh_sung when hour(clock) == 20 and seventhRestored(bowl) and not seventhTonight(bowl) and not hymnSilenced(bowl) and not at(party, ninth_lock)
    says "The bells stop. In the quiet the choir sings four low notes, all alike, and again, and again, slow as somebody counting coins, and the Bowl is so still you can hear the water in the Stair." {
    Assert seventhTonight(bowl). }
  Rule seventh_sung_quietly when hour(clock) == 20 and seventhRestored(bowl) and not seventhTonight(bowl) and not hymnSilenced(bowl) and at(party, ninth_lock) {
    Assert seventhTonight(bowl). }
  Rule seventh_lowers when hour(clock) == 20 and seventhTonight(bowl) and (state(deep_gate, raised) or state(deep_gate, half)) and not broken(reckoner) and not complete(reckoner) {
    Assert state(deep_gate, lowered). }
  Rule hymn_resets when hour(clock) == 3 and sungTonight(bowl) { Retract sungTonight(bowl). Retract seventhTonight(bowl). }

  // The Fifth Remainder: the engine's own voice, a little; every fountain in the Bowl hums for an hour.
  Relation humming(place). Measure humAt(place). Relation fifthRestored(place). Relation fourthRestored(place).
  Rule fifth_sung when hour(clock) == 20 and fifthRestored(bowl) and not humming(ammerlin) and not broken(reckoner) and not complete(reckoner) and not hymnSilenced(bowl)
    says "After the Seventh, the Fifth: one bright note and three in the middle voice, and all over the Bowl the fountains take it up and hum, low and steady, and go on humming long after the choir has stopped." {
    Assert humming(ammerlin). Set humAt(ammerlin) to watch(clock). }
  Rule hum_fades when humming(ammerlin) and watch(clock) >= humAt(ammerlin) + 6 { Retract humming(ammerlin). }
  Rule fourth_holds when hour(clock) == 20 and fourthRestored(bowl) and not doorHeld(reckoner) and not complete(reckoner) and not broken(reckoner) { Assert doorHeld(reckoner). }
  // What the engine does when it is starved: it calls for water in the only voice it has, which is the hymn's.
  Measure lastCall(place).
  Rule starving when state(deep_gate, logged) and not starved(reckoner) and not broken(reckoner) and not complete(reckoner) { Assert starved(reckoner). }
  Rule unstarved when starved(reckoner) and not state(deep_gate, logged) { Retract starved(reckoner). }
  Rule engine_calls when starved(reckoner) and hour(clock) == 2 and watch(clock) >= lastCall(bowl) + 60
    says "In the small hours every fountain in Ammerlin begins to hum, the same rising phrase over and over: one low note, and three bright. Dogs bark the length of the Bowl. Lamps come on in the terraces." {
    Set lastCall(bowl) to watch(clock). Increase calls(bowl) by 1. }
  Measure calls(place).

  // When the count is whole: every bell in the city rings with nobody at the ropes, the last door opens, and the Mere
  // goes down one long last time.
  Rule census_whole when count(reckoner) >= 900 and not complete(reckoner) and not broken(reckoner)
    says "Every bell in Ammerlin rings at once. Nobody is at the ropes. The sound goes round the Bowl and comes back off the Rim, and under it, from the water itself, from the Stair and the cisterns and every pipe and basin in the city, a chord comes up that nobody living has heard: the whole Long Hymn, in one breath, sung by the water. Then nothing." {
    Assert complete(reckoner). Assert state(deep_gate, lowered). Set ninths(reckoner) to 9. Set completedAt(bowl) to watch(clock). }
  Rule door_holds_shut when complete(reckoner) and completedAt(bowl) == watch(clock) and doorHeld(reckoner) and not toldHeld(bowl)
    says "Far below the Ward, where the count runs out at the last door, nothing opens. The Fourth holds it." { Assert toldHeld(bowl). }
  Relation toldHeld(place).
  // Its last breath is drawn from whatever feeds it: the Mere, unless the Grey Way is open.
  Rule last_breath when complete(reckoner) and completedAt(bowl) == watch(clock) and not fed(reckoner) and not drewLast(bowl)
    says "Far down, the Mere draws back from the Ward like a held breath let go, and does not come back." { Decrease mere(bowl) by 6. Assert drewLast(bowl). }
  Relation drewLast(place).
  Measure completedAt(place). Relation completedFed(engine).
  Rule fed_spared when complete(reckoner) and completedAt(bowl) == watch(clock) and fed(reckoner) and not drewLast(bowl)
    says "Far down, the Mere does not move. Under the Rim, in the old grey way, the Guild's water runs on into the dark, and somewhere it stops being needed." { Assert drewLast(bowl). }
  Rule fed_complete when complete(reckoner) and fed(reckoner) and not completedFed(reckoner) and completedAt(bowl) == watch(clock) { Assert completedFed(reckoner). }

  // The Hearing, at noon on the seventh day (watch 888), unless the Registrar has been shown cause to put it off two days.
  Measure hearingAt(place).
  Initially Set hearingAt(bowl) to 888.
  Query hearingDay() means watch(clock) >= hearingAt(bowl) - 72 and watch(clock) < hearingAt(bowl) + 18.
}

data/adventures/low-water/callings.kyr:
Module lowwater "Low Water" {
  Description "What the Assessor's company hears and can do by what it is: the warrior counting bailiffs, the bard in the nave, the cleric at the Ward, and the one thing only a cleric can do for the Reflected.".

  // ── The company's ear ───────────────────────────────────────────────────────────────────────────────────────────
  // Said once, by whoever the company has of the calling. A company without the calling does not hear it.
  Relation heardBailiffs(group). Relation heardNave(group). Relation heardWardWell(group). Relation heardMoot(group).
  Rule voice_bailiffs at quill_outer when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and at(party, quill_outer) and not heardBailiffs(party)
    says "{?m} does not look at the bailiffs, which is how {?m} counts them. 'Six by the door, two on the stair, none who would use it on a customer,' {?m} says. 'They are here for the books. A man who guards ledgers with that many staves has a great deal in them he would sooner not have counted.'" {
    Assert heardBailiffs(party).
  }
  Rule voice_nave at nave when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, nave) and not heardNave(party)
    says "{?m} stands under the vault and hums, very low, until the nave hums back. 'A fifth short,' {?m} says. 'The room was built for seven voices and it is being sung to by six. You can hear where the missing one would sit, the way you can hear a dropped stitch.'" {
    Assert heardNave(party).
  }
  Rule voice_ward_well at ward_well when memberOf(?m, party) and hasCalling(?m, calling_cleric) and awake(?m) and at(party, ward_well) and not heardWardWell(party)
    says "{?m} looks into the Ward well a while and then at the people queueing with their buckets, and counts neither. 'They are not afraid of the water,' {?m} says. 'They are afraid of being the ones who are seen to take it. That is an older fear, and I have buried a great many people who died of it.'" {
    Assert heardWardWell(party).
  }
  Rule voice_moot at moot_hall when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, moot_hall) and not heardMoot(party)
    says "{?m} walks the length of the Moot Hall and back without speaking, and stops at the dais. 'Three chairs face the room,' {?m} says, 'and the room's chairs face them, and nothing in between but floor. Nobody has ever been persuaded in a hall like this. They are arranged to be convicted.'" {
    Assert heardMoot(party).
  }

  // ── The cleric's way ────────────────────────────────────────────────────────────────────────────────────────────
  // The Reflected can be sung down, which stills them for a night, and the Ear's bell can break them, which takes the
  // approach back by one. A cleric knows a third thing, because a cleric knows the difference between quieting the dead
  // and laying them: the office, said by name, takes the approach back by two and needs neither the hymn nor the bell.
  // The price is the reading itself: the office is long, the company stands at the water in the dark for the whole of
  // it, and the Reflected say the cleric's own name back at the end, once, in the cleric's voice.
  Relation officeSaid(group).
  Action say_the_office(actor: group, site: place, c: member) "Say the office of the dead over the Reflected, and name them" {
    Description "They are water that was people. The hymn quiets them; a bell breaks them; only the office tells them they are done.".
    Requires able(actor) and company(actor) and at(actor, site) and at(reflected, site) and dark() and memberOf(c, actor)
      and hasCalling(c, calling_cleric) and awake(c) and approach(bowl) >= 1 and not reflectedStilled(bowl).
    Time 4.
    On success { Assert reflectedStilled(bowl). Assert officeSaid(actor). Decrease approach(bowl) by 2. }
    Result "{c} says it standing at the water's edge, bareheaded, in the low plain voice of someone who has said it over a great many beds. It is not the hymn; it has no verses. It has names, and {c} gives them whatever names there are: a girl with a basket, if she is there, and the rest as the rest, the diggers, the dyers, a woman with a rod under the wrong arm. They stand and hear it. When {c} says the last line they do not come apart and they do not lie down. They go out like lamps in a row. Then, from the black water, in {c}'s own voice, once, very quietly: the name.".
  }

  // ── A companion's choice ────────────────────────────────────────────────────────────────────────────────────────
  // Isaura Vant, travelling with the company, sees her own figure among the Reflected. What she is told decides what
  // she does next. The truth steels her: she will sign the Finding unasked, and she goes back up alone to the Office to
  // do it, so the company goes on without her figures, her rod and her remarks. The kindness keeps her at its side and
  // takes nothing from her, and costs the Finding a signature unless she is asked, on the morning, as she asked to be.
  Relation isauraToldTruth(group). Relation isauraToldKindly(group).
  Topic isaura_water with isaura travelling "Ask Isaura what she sees at the water" when at(party, ward_landing) and dark() and approach(bowl) >= 3 and not reflectedStilled(bowl) once {
    Says "She does not take her eyes off the figure with the rod. 'It has my coat,' she says. 'It has the rod on the wrong arm, and it stands the way I stand when the Registrar is speaking and I have a figure she will not like.' Her voice is perfectly level. 'Tell me what it is. Not what is kind. I have been told what is kind all my working life.'".
  }
  Topic isaura_truth with isaura travelling "Tell her it is what the Office will make of her if the count is allowed to finish" answering isaura_water when at(party, ward_landing) once {
    Grave "She will believe you, and she will not stay.".
    Says "'Yes,' says Isaura. She nods once, as at a figure that has come out as she feared. 'Then I know what the Finding is for.' She takes the brass rod from under her arm and looks at it. 'I will sign it. I do not need to be asked in the morning; I need to be somewhere with a desk, tonight, and not here, being agreed with.' She goes up the Ward steps alone, and does not look back, and at the top she is a woman in a grey coat carrying a rod on the right arm.".
    On discuss { Assert isauraToldTruth(isaura). Assert isauraSigns(isaura). Retract travelsWith(isaura, party). Retract willing(isaura, party). Assert at(isaura, office_hall). }
  }
  Topic isaura_kindness with isaura travelling "Tell her it is only the water, and the dark, and it is nobody" answering isaura_water when at(party, ward_landing) once {
    Says "'Of course.' She says it too quickly, and then, more slowly, as if she were laying down a weight she had meant to keep carrying: 'Of course it is.' She puts the rod back under her arm, the right one. 'Thank you.' She stays at your side the rest of the night, a half-step nearer than before, and says nothing about it in the morning.".
    On discuss { Assert isauraToldKindly(isaura). }
  }

  // ── A comic scene, in a grave adventure ─────────────────────────────────────────────────────────────────────────
  // The Full Measure serves to the Office's own standard, and the standard is the cupful.
  Observe measure_pots at taproom when true "Every pot in the Full Measure has a brass line riveted inside it, a finger below the rim, and a card behind the tap that reads, in a clerk's hand, THE STANDARD POT IS FILLED TO THE LINE AND NOT TO THE BRIM. The regulars drink down to the line, pause with a certain dignity, and hold the pot out to be topped up from the brim, which is legal as long as the pot is not carried out of the room.".
  Topic ruan_line with ruan "Ask Ruan Tell about the brass line in the pots" when true once {
    Says "'Ah,' says Ruan Tell, and comes round the bar in a manner that means a story. 'The Office sent a clerk with a gauge four years ago, to see I was serving a standard pot, and he stayed three days, and measured every pint I poured, and at the end of it he said the Full Measure was serving nine tenths of a pot, and that the Office's own pot was nine tenths of a pot, and that therefore I was in perfect order.' He sets down the rag. 'I asked him what the missing tenth was for. He said it was for the foam. I said there is no foam on that pot. He said that is the foam.' He folds his arms. 'He is a Third Grade now.'".
  }
}

data/adventures/low-water/citadel.kyr:
Module lowwater "Low Water" {
  Description "The Glass Citadel in the outer dark, at the top of the stair that goes up out of Ammerlin in the water: the Assayers at its gate, the hall of receipts, the model of the nine circles, and at its heart the Auditor, whose own heart is set in the Reckoner's ninth wheel.".

  Place citadel_plane "the outer dark" is plane.
  Place outer_dark "the outer dark" is region within citadel_plane.
  Place dark_wild "the outer dark" is wilderness within outer_dark at 0, 0.
  Place dark_landing "the top of the stair" is room within dark_wild at 0, 0 outdoors.
  Place glass_citadel "the Glass Citadel" is settlement within outer_dark at 1, 0.
  Place glass_gate "the glass gate" is room within glass_citadel at 0, 0 outdoors.
  Place hall_receipts "the hall of receipts" is room within glass_citadel at 1, 0.
  Place model_hall "the hall of the nine circles" is room within glass_citadel at 2, 0.
  Place auditor_seat "the seat of the Auditor" is room within glass_citadel at 3, 0.
  // Where the heart sits: behind the grille of the ninth arch, which opens only on a count that is whole and a door
  // that is held.
  Place ninth_socket "the ninth socket" is room within wheels_level at 8, 1 underground.

  Passage up_stair "the stair that goes up" is path between stair_foot and dark_landing taking 60 minutes.
  Passage to_glass_gate "the glass road" is path between dark_landing and glass_gate taking 20 minutes.
  Passage gate_in "the glass gate" is doorway between glass_gate and hall_receipts
    opening when carries(party, ear_bell) or knows(party, ledger_of_water) "The Assayers stand across the gate, and do not move, and do not need to.".
  Passage receipts_on "the arch of receipts" is arch between hall_receipts and model_hall.
  Passage seat_door "the door of the seat" is doorway between model_hall and auditor_seat
    opening when tried(circles, looking) "The door of the seat is a sheet of glass with nothing behind it, until you have understood what you are looking at in this hall.".
  Passage grille "the grille of the ninth arch" is doorway between w_remainder and ninth_socket
    opening when complete(reckoner) and doorHeld(reckoner) "The grille is bronze bars as thick as a wrist, with no lock and no hinge. It will open when the count is whole, and the door it guards is shut, and not before.".

  // The stair: a long climb up into nothing.
  Observe stair_climb at dark_landing when true "The stair ends. Below you, very far down, a disc of pale light that is the still water, and in it, small as a coin's face, the copied Bowl. Above you there is no more stair, and no sky either: only dark, that is not the dark of night, because there has never been anything here for it to be the night of. You can see, though. Everything here gives off a little of the light of the Interval, as a thing still wet gives off cold.".
  Observe landing_citadel at dark_landing when true "Out in the dark, a long way off and not far at all, stands something made of glass: walls, towers, a gate, as clear as the copied city below and much older, its edges worn soft, like a bottle that has lain a thousand years in a river.".
  Observe gate_scene at glass_gate when true "The glass gate is two leaves of glass taller than the Sounding's dome, standing open on a hall full of a dim green light. Across it stand the Assayers: three figures of glass, taller than any person, without faces, each holding before it in both hands a set of scales. In the pans of the scales nothing is weighed; the beams stand level all the same, and tremble. You have seen those scales before, small, in brass, cut into the lintel of the Office of Measures.".
  // The Assayers keep the account level. They are not Peaceable: they tolerate the company until the account is made
  // unequal under their hands (a jar taken from the receipts), and then they come to set it level.
  Species assayer_kind "an Assayer" like crystal_elemental temperament obedient described "A figure of old glass twice the height of a man, without a face, holding a set of scales before it in both hands. When it moves, the beams stay level.".
  Person assayers "the Assayers" at glass_gate {
    Role "figures of glass, holding scales". Species assayer_kind. Level 4. Numbers 3.
    Called "the Assayer of what is counted", "the Assayer of what is owed", "the Assayer of whether they are equal".
    Greets "The Assayers turn, all three, toward you, and the beams of their scales dip, very slightly, and come level.".
    Warns "The three Assayers turn toward you together. Their beams have tipped, all three the same way, toward you, and they are walking to level them.".
  }
  Initially Assert tolerates(assayers, party).
  // They admit what has been counted: a company carrying the Lector's bell, which they know; or one whose mark is in the
  // ledger of water.
  Relation admitted(group).
  Rule admit_bell at glass_gate when at(party, glass_gate) and carries(party, ear_bell) and not admitted(party)
    says "The bell in your pack gives one stroke by itself: high, and under it, as it dies, deep. The Fourth. The three scales tilt, all at once, toward it, as a flower turns, and the Assayers step back out of the gate the way water gives back from a stone." {
    Assert admitted(party). }
  Rule admit_mark at glass_gate when at(party, glass_gate) and knows(party, ledger_of_water) and not admitted(party)
    says "One of the Assayers holds its scales down to you. In one pan, so small you must bend to see it, lies a drop of still water, and in the drop, a whorl: your fingerprint, from the ledger of water. It has been weighed. The beam comes level. You are on the account; the Assayers step back." {
    Assert admitted(party). }
  Topic assayers_ask with assayers "Ask the Assayers what they weigh" when true once {
    Says "None of them has a mouth. The answer comes up out of the pans the way a note comes out of a glass rubbed at the rim, three notes, one from each, and you understand them the way you understood the column's: what is counted; what is owed; whether the two are equal. Then a fourth note, from all three, held a long time, trembling like the beams. Not yet.".
  }

  // The hall of receipts: the counted water of three thousand years, in jars, each one a cupful, each with a face. It is
  // the other side of the Bowl's book: every cupful that left the Mere, entered again where it arrived.
  Observe receipts_scene at hall_receipts when true "Jars. A hall of them, shelved to a height you cannot see, and going on ahead of you further than the hall should go: glass jars the size of a cupped pair of hands, each one full of still water, each one sealed with a disc of glass, and on the disc a mark cut in the machine's notation. A cupful in each. The light in the hall is the light that comes out of them.".
  Thing jars_of_receipt "the jars of counted water" at hall_receipts {
    State shelved "The jars of counted water stand shelved in their thousands, a cupful in each.".
    Tries looking.
  }
  Discovery receipts_read "In the hall of receipts every cupful the Reckoner ever drank is kept in a jar, and in each jar is a face: the counted water keeps an image of whatever was standing at the edge of the Mere when it was drawn. The Ward has been counted with its water for three thousand years, one cupful at a time.".
  Rule receipts_looked when tried(jars_of_receipt, looking) and not knows(party, receipts_read)
    says "You lift one down. It is cold and heavier than water should be. In it, small, as if seen down a well, is a face: a man with a beard and a net over his shoulder, looking down at you with the patient look of a man watching a float. You put it back. You take another: a child. Another: a woman with a basket. A dog. A gull. A boat, drawn small, with a boy in it. Every jar has a face in it, every face is looking down, and every one of them, you realise, is looking down from the edge of the Mere, into the water, at whatever was looking up." teaches receipts_read { }
  Observe receipts_years at hall_receipts when knows(party, receipts_read) "The shelves keep years, and some years are thick. There is a long run of jars all frosted white inside, where the Mere froze to its bed one winter and the machine drank ice. There is a shelf of jars every one of them cracked across, and the faces in those are not looking down but up, with their mouths open: the year of the Long Silence, when the water came up the Stair. And there is a shelf, low down, of faces that are all very young, which you do not look at for long.".
  Observe receipts_isaura at hall_receipts when knows(party, receipts_read) and travelsWith(isaura, party) "Isaura Vant has taken a jar down and is holding it to the light, and reading the mark on its seal, and putting it back, and taking the next. 'They're in order,' she says. 'They're in perfect order. Every cupful that left the Mere, entered again where it arrived.' Her voice is quite steady. 'This is the other side of the book. These are my forty ells.' She stops at a shelf near the floor. 'This is the year of the Thirst Riots. My grandmother would be on this shelf. She was nine. She hid in a dye-vat for two days.' She does not look for her. She puts the jar back exactly where it was.".
  // Annet Kettle, if the Hall's breach drowned the diggers: her jar can be taken from the shelf and broken, and she let go.
  // It is the one thing in the hall the Assayers will not let pass.
  Observe receipts_annet at hall_receipts when knows(party, receipts_read) and drowned(diggers) and not annetFreed(party) "On a shelf at the height of your eyes, newer than the rest, a row of jars still clouded, as if the water in them had not yet quite settled. In the third of them is a girl of fifteen with her mouth open, calling somebody. Annet Kettle. She is still calling.".
  Relation annetFreed(group). Relation assayersRoused(place).
  Action free_annet(actor: group, site: place) "Take down Annet Kettle's jar and break it" {
    Description "She is not owed to anybody.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hall_receipts) and drowned(diggers) and knows(actor, receipts_read) and not annetFreed(actor).
    Time 1.
    On success { Assert annetFreed(actor). Assert assayersRoused(bowl). Set assayTurn(bowl) to watch(clock) + 2. Retract at(assayers, glass_gate). Assert at(assayers, hall_receipts). }
    Result "The jar breaks on the floor like any jar. The water in it does not run: it stands up a moment in the shape of a girl with a basket on her hip, the right way round, and looks at you, and is water, and runs away between the shelves toward the gate and down. Behind you, in the gate, three beams tip all at once with a sound like a struck glass.".
  }
  // They come into the hall with their beams tipped and give the account one watch to come level; then they level it.
  Measure assayTurn(place).
  Rule assayers_close when assayersRoused(bowl) and tolerates(assayers, party) and watch(clock) >= assayTurn(bowl) and at(assayers, hall_receipts) and at(party, hall_receipts)
    says "The Assayers stop waiting. Their beams are tipped, all three the same way, toward you, and they come down the hall between the shelves to level them." {
    Retract tolerates(assayers, party). }
  Observe assayers_waiting at hall_receipts when assayersRoused(bowl) "Three Assayers stand in the hall among the shelves, their beams tipped toward you, waiting, the way the Office waits at the counter for a figure that does not add up. Where the jar stood on its shelf there is a gap, a cupful wide.".
  Thing assay_pan "the empty pan" at hall_receipts {
    Holds.
    State held "Where the broken jar stood there is a gap on the shelf, the shape of a cupful.".
  }
  Rule assay_stone when assayersRoused(bowl) and inside(?w, assay_pan) and itemKind(?w, weight_stone)
    says "You set the weight-stone on the shelf where the jar stood. The nearest Assayer bends over it a long time. Its beam comes level, very slowly, and the other two come level with it, and they go back to the gate without looking at you, the way clerks go back to their desks when a sum has been made to balance." {
    Retract assayersRoused(bowl). Assert tolerates(assayers, party). Retract at(assayers, hall_receipts). Assert at(assayers, glass_gate). }
  Rule assay_cup when assayersRoused(bowl) and inside(?c, assay_pan) and itemKind(?c, still_cup)
    says "You set the cup of still water on the shelf where the jar stood. It is a cupful; it is exactly a cupful. The beams come level at once, all three, and the Assayers go back to the gate, and the cup stands on the shelf among the jars, and in a moment there is a face in it, looking down: yours." {
    Retract assayersRoused(bowl). Assert tolerates(assayers, party). Retract at(assayers, hall_receipts). Assert at(assayers, glass_gate). }
  Action isaura_debit(actor: group, site: place) "Ask Isaura to enter the broken jar as a debit, in front of the Assayers" {
    Description "Honestly. On the right side of the book.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hall_receipts) and assayersRoused(bowl) and travelsWith(isaura, actor).
    Time 1.
    On success { Retract assayersRoused(bowl). Assert tolerates(assayers, party). Retract at(assayers, hall_receipts). Assert at(assayers, glass_gate). }
    Result "Isaura steps in front of the nearest Assayer with her book open, and writes, aloud, the way the Office reads out a judgement: 'One cupful, the Ward, Annet Kettle, aged fifteen. Released by the Independent Assessor, on the Office's account. Owed.' She holds the page up to where its face would be. The beam comes level. The three of them go back to the gate. Isaura closes the book. 'That's a real entry,' she says. 'I'll have to pay it. I don't know in what.'".
  }
  Observe annet_landing at ward_landing when annetFreed(party) "Somebody has left a basket on the lowest step of the landing, with river flowers in it, the kind the Ward children pick for a wedding.".

  // The model hall: the nine circles of the world, as the Varakiiri knew them, and the crack.
  Observe model_scene at model_hall when true "In the middle of a round hall hangs a model of the world: nine rings of glass, one inside another, each turning very slowly on its own tilt, like the rings of a sphere a navigator uses, but there is no globe at the centre. Each ring is pinned to the next by a single point of light, and eight of the points are dark. The ninth burns, faint, on the innermost ring; and round it, in the glass, runs a crack.".
  Thing circles "the nine circles" at model_hall {
    State turning "The nine circles turn on their tilts, pinned by one light.".
    Tries looking.
  }
  Discovery circles_read "The Bowl of Ammerlin is the dent the ninth heart made in the world when the Varakiiri lost it: the jewel fell, and pinned the inner circle where it fell, and the Mere is the water that gathered in the hole. If the heart goes home, the pin comes out, and the Bowl opens on the dark.".
  Rule circles_looked when tried(circles, looking) and not knows(party, circles_read)
    says "You walk round it twice before you see it. The ninth light is not on the ring: it is under it, holding it, the way a nail holds a board; and the crack in the glass runs out from it in a ring, round and shallow, with a little pool of light gathered in the bottom. You know that shape. You have been walking up and down it for days. It is the Bowl of Ammerlin, seen from above: the print a nail leaves when it goes in. The terraces are the crack's edges. The Mere is what pooled. The green glass in the Rim's dust is what splashed." teaches circles_read { }
  Observe model_pins at model_hall when knows(party, circles_read) "The eight dark pins are not empty. Under each, small in the glass of its ring, something has been drawn over the place where it went in, the way a mapmaker draws a town: a sea with a ring of boats on it; a long range of mountains with a white scar down its face; a wood with a road through it that goes round and round; a town of a great many bells; a field, cut short, with one figure standing in it. Three are drawn over with a single line, as a clerk strikes a settled entry. Wherever the hearts went in, someone built something over them, and set it to counting.".
  Observe model_threshold at model_hall when true "Over the hall, where a dome should close it, the glass stops, and there is a round opening on a dark that is darker than the rest, and cut round its edge, in letters you can read because they are the old letters of the Ear: TO THOSE WHO SETTLED THE WORLD, FROM THE NINTH: THE ACCOUNT OF WHAT WAS TAKEN.".
  Topic isaura_circles with isaura travelling "Ask Isaura what the crack in the ninth circle means" when knows(actor, circles_read) once {
    Says "Isaura looks at the crack for a long time with her hands behind her back. 'So we live in the print,' she says. 'Ammerlin. The Ward. The Office. My father's boat. All of it in the hole that a stone made when it fell out of somebody's chest.' She is very quiet. 'And the count is the bill. And it's nearly paid.' She looks up at the opening in the dome, at the letters cut round it. 'Not to it, though. Did you see? It's addressed. It's addressed upward.'".
  }

  // The Auditor. It learned to speak from the Office: the clearest thing the water ever heard was the month after the
  // Thirst Riots, when every right in the Bowl was read out in the square. It speaks like a counter clerk, and believes
  // the motto, because the motto was the first sentence it ever understood.
  Observe seat_scene at auditor_seat when true "A small room, round, with a floor of still water. In the middle of it, where it can be seen from every side, there is a chair of glass, very plain, of the shape the Office's Registrar sits in; and in the chair is nothing at all, except that the water on the floor round it stands in rings, as it does round a stone; and the cold that came off the Reflected comes off the chair; and the room is full of a voice. It is the fifth voice from the column: the one that was not any of the four of you.".
  Observe seat_letters at auditor_seat when true "Beside the chair, on the wet floor, lies a stack of paper that has been wet a long time and has not rotted: letters, a great many, in a small even hand, with the footnotes in red. Collegium of Lesser Instruments. The Second Reader, to: and then a space, on every one, where a name would go.".
  Person auditor "the Auditor" at auditor_seat {
    Role "a voice, and a cold, and the rings in the water round an empty chair". Peaceable.
    Greets "'Received,' says the voice, in exactly the tone of the Office counter, before you have said anything at all. 'You are the Independent Assessor. I have read your commission. It was pinned up by the counter for a week.' The rings in the water widen. 'Sit, if you like. Nothing here is in a hurry but you.'".
  }
  Discovery auditor_heard "The Auditor is the Varakiir whose heart was lost into the Bowl: it has read the count from the far side of the last door for three thousand years, built a likeness of Ammerlin out of the counted water to learn it by, and sent its reflections up the Mere to sing the Rising, because the count is the account of what was taken from it, and when the account is whole its heart is due back. It learned to speak from the Office of Measures.".
  Topic auditor_what with auditor "Ask the Auditor what it is" when true once {
    Says "'One of nine,' says the voice. 'The one whose heart you have been standing over all week.' It does not hurry. 'The water hears whatever is said at its edge, and I have the water, so I have had a long time to learn how you talk. Most of it is weather and quarrels. The clearest thing I ever heard was a woman in your square, the month after the Thirst Riots, reading out every right in the Bowl, one after another, the ell and the hour and the name, in a voice that never went up or down, for thirty days.' A pause. 'I liked her very much. She was so careful. I learned to speak from her. What is measured honestly can be settled peacefully.' The rings settle. 'I believe that. I am here to settle.'".
    On discuss { Assert knows(actor, auditor_heard). }
  }
  Topic auditor_owed with auditor "Ask the Auditor what it is owed" when knows(actor, auditor_heard) once {
    Says "'Everything the wheel counted,' says the voice. 'That is the arrangement. The ones who made the wheel found my heart at the bottom of your Bowl and wrote down everything it holds in place: the makers, the beasts, the dead, the living, the water and what is in it, the unborn, the circles. An inventory of what was taken. It is a very good inventory. I have checked it.' The water is quite still. 'They meant to send it to a court. They died first. The account stayed open. I have been the only party to it who was still alive.'".
  }
  Topic auditor_ward with auditor "Ask the Auditor what it wants of you" when knows(actor, auditor_heard) once {
    Says "'A figure,' says the voice. 'You were engaged to find one. I read the commission.' The rings in the water widen, very slowly, as if it were leaning forward. 'What is the Ward worth? The fishers, the boats, the steps with the paint on, the children skipping the Lock-Rhyme. Your Office has never put a figure on it. Your Guild has, in red. Your Cantor would sing it. I have counted every cupful of it for three thousand years and I do not know.' A long pause. 'I will take any figure you give me. Nobody has ever given me one. You would be surprised how long nobody answers.'".
  }
  Relation wardValued(place).
  Rule approach_floor when approach(bowl) < 0 { Set approach(bowl) to 0. }
  Topic auditor_answer with auditor "Tell the Auditor that the Ward has no figure" when knows(actor, auditor_heard) and not wardValued(bowl) once {
    Says "The voice is silent so long that the rings in the water round the chair go still. 'That is a figure,' it says at last. 'It is the largest one there is. Your Office has a word for it, in the oldest books; I have heard it read. Inestimable.' A pause. 'I will enter it as that. It does not close the account. It makes it very much harder to close.' The cold in the room is less, a little, as if something had stepped back from a counter.".
    On discuss { Assert wardValued(bowl). Decrease approach(bowl) by 2. }
  }
  Topic auditor_bowl with auditor "Ask the Auditor what becomes of Ammerlin when its heart goes home" when knows(actor, auditor_heard) and knows(actor, circles_read) once {
    Says "'The Mere first,' says the voice. 'Through the bottom, into the dark. Then the Ward. Then the terraces, from the bottom up, a step at a time, the way your gauge is read.' It says it the way a clerk reads back a figure, so that you can check it. 'I will keep all of it. You have seen how I keep things. Nothing that is counted is lost.' And then, after a while: 'I am aware that is not a comfort. I did not say it as one. You asked, and it is the figure.'".
  }
  Topic auditor_pell with auditor "Ask the Auditor about Pell, the Second Reader" when knows(actor, auditor_heard) and knows(actor, pell_named) once {
    Says "'He writes a very good footnote,' says the voice. 'Twenty years of them. He leaves the name blank, because he does not know what to call me, and he is too careful to guess.' The water does something that, in a face, might be fondness. 'He thinks that when the door opens I will tell him what the world is fastened with. I will, if he asks. He will not like the answer.' A pause. 'It is me. It is eight more of me. He has not thought about what that means for his instruments.'".
  }
  Topic auditor_aun with auditor "Ask the Auditor about Aun, the Lector of the Ear" when knows(actor, auditor_heard) and knows(actor, lector_words) once {
    Says "The rings in the water stop. For the first time the voice is not quite level. 'She stood at the column for forty nights and sang me shut. I learned her voice. I have been practising it backward ever since, to open what she closed.' A long silence. 'She was not afraid of me. That was what I could not learn. Everyone else at that door was afraid, and you can open anything that is afraid.' Another silence. 'She is on a shelf in the hall you came through. I keep her very carefully.'".
  }
  Topic auditor_upward with auditor "Ask the Auditor why the account is addressed upward, and not to it" when knows(actor, auditor_heard) and knows(actor, circles_read) once {
    Says "'Because the ones who made the wheel were honest,' says the voice. 'They addressed it to a court, not to a creditor. I have read the address every day for three thousand years. It is correct.' The cold in the room deepens until your breath shows. 'Send it up, if you like. Carry my heart to the opening in the dome and let it go, and the court will read the account in its own time, which is longer than mine, and your city will stand on its nail until it does.' A pause. 'Or give it to me. I have been very patient. I am tired. You would not think a thing like me could be tired. It surprised me too.'".
  }

  // The heart.
  Kind kiritarun "the Kiritarun" is treasure worth 0 weighing 1 described "A faceted stone the size of an egg, all the colours a deep water is when the sun goes into it, and moving, slowly, as if it breathes. It is cold enough to hurt, and you cannot put it down for long without wanting to pick it up again.".
  Item ninth_heart "the ninth heart" is kiritarun at ninth_socket.
  Observe socket_scene at ninth_socket when true "Behind the grille, the smallest of the nine wheels has stopped. The count is whole. In the ninth socket of its rim, the stone breathes.".

  // With the door unheld, the Reflected come for it the night the count closes, and carry it up the stair.
  Measure heartDue(place). Relation heartRising(place). Relation heartHome(place). Relation heartRecovered(group).
  Rule heart_taken when complete(reckoner) and not doorHeld(reckoner) and not heartRising(bowl) and not heartRecovered(party) and at(ninth_heart, ninth_socket) and not countFalsified(reckoner) and not auditorSettled(bowl) {
    Retract at(ninth_heart, ninth_socket). Assert keeps(reflected, ninth_heart). Assert heartRising(bowl). Set heartDue(bowl) to watch(clock) + 144. }
  Observe heart_carried near reflected when keeps(reflected, ninth_heart) and dark() "Among the Reflected one goes with its hands cupped in front of it, as you would carry a light in wind; and in its hands, through the water of its fingers, something breathes, all the colours of deep water.".
  Observe heart_on_stair at stair_foot when keeps(reflected, ninth_heart) "Up the stair in the water, very far up, a light is climbing: all the colours of deep water, carried in cupped hands, step after step, slowly, toward the dark.".
  Rule heart_arrives when heartRising(bowl) and keeps(reflected, ninth_heart) and watch(clock) >= heartDue(bowl) and not heartHome(bowl) {
    Retract keeps(reflected, ninth_heart). Assert heartHome(bowl). }
  // It can be taken back from them with the Lector's bell, wherever they stand with it, or on the stair.
  Action ring_for_heart(actor: group, site: place) "Ring the Ear's bell at the Reflected who carry the heart" {
    Description "High, and deep. The Fourth: the last door, least.".
    Requires able(actor) and company(actor) and at(actor, site) and at(reflected, site) and keeps(reflected, ninth_heart) and carries(actor, ear_bell).
    Time 1.
    On success { Retract keeps(reflected, ninth_heart). Assert at(ninth_heart, site). Assert heartRecovered(actor). Retract heartRising(bowl). Assert reflectedStilled(bowl). Increase approach(bowl) by 1. }
    Result "You ring it. The Reflected stop, all of them, mid-step, and the one with the cupped hands turns its clear face toward you with your own attentive look; and then its hands are only water, and the water falls, and the stone drops into it and lies on the ground, breathing, all the colours of deep water. Somewhere a long way below the Mere, in a voice that is no voice of yours, something says, quite quietly, as a clerk says it when a sum comes out wrong: 'Oh.'".
  }
  Action climb_after_heart(actor: group, site: place) "Climb the stair after the light, ringing the Ear's bell" {
    Description "It is a long stair, and they are very patient. You are not.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, stair_foot) and keeps(reflected, ninth_heart) and carries(actor, ear_bell).
    Time 6.
    On success { Retract keeps(reflected, ninth_heart). Assert at(ninth_heart, site). Assert heartRecovered(actor). Retract heartRising(bowl). Assert reflectedStilled(bowl). Increase approach(bowl) by 1. }
    Result "You climb with the bell held over your head, ringing it, high and deep, every tenth step, until your arm is numb and the stair has gone so far up that the copied city is a coin under you. The light comes down to meet you. It does not mean to; it is carried down, step by step, by a figure of water with your own face, which sets it down on the step at your feet as if it were returning something it had borrowed, and goes back down the stair into the water, and is the water.".
  }
  // Or sung out of their hands: the Seventh, the cupful, the verse they cannot abide, sung at the one that carries it.
  Action sing_for_heart(actor: group, site: place) "Sing the Seventh at the one with cupped hands, until it lets go" {
    Description "Deep, deep, deep, deep. The mouth at its least. A cupful, and no more.".
    Requires able(actor) and company(actor) and at(actor, site) and at(reflected, site) and keeps(reflected, ninth_heart) and dark() and knows(actor, remainders_tones).
    Time 4.
    Resolve check(actor, persuasion, dc_hard).
    On success { Retract keeps(reflected, ninth_heart). Assert at(ninth_heart, site). Assert heartRecovered(actor). Retract heartRising(bowl). Assert reflectedStilled(bowl). }
    On failure { Assert strikes(reflected_cold, party). }
    Result "You sing it at the one with the cupped hands, all of you, four low notes, alike, over and over, until your throats are raw; and slowly, the way a reflection breaks up when the wind gets onto the water, its hands lose their shape, and the stone slips through them and lies on the ground, breathing.".
    Otherwise "You sing until your voices go. It stands in front of you with the light in its hands and listens to you attentively, the way it listens to everything, and the cold comes off it into your chests.".
  }
  // By day, after the count closes, what the night did is plain on the landing to anyone who looks.
  Observe heart_prints at ward_landing when keeps(reflected, ninth_heart) and not dark() "On the Ward landing, going down the painted steps toward the Mere, there is a line of wet prints too broad and flat for anybody's feet, and in every print, in the full sun, there is frost.".
  Topic isaura_prints with isaura travelling "Ask Isaura about the frost in the prints on the landing" when keeps(reflected, ninth_heart) once {
    Says "Isaura crouches by the nearest print and measures it with two fingers, because she cannot help it. 'Cold enough to freeze in sunlight,' she says. 'Going down. Not coming back.' She looks at the Mere. 'Something was carried down here last night. I counted them going: one of them was walking the way you walk with a lamp in wind.' She stands. 'Whatever it was, it's still on its way. You don't carry a thing that carefully a short distance.'".
  }
  Topic dov_prints with dov "Ask Dov what came down the landing last night" when keeps(reflected, ninth_heart) once {
    Says "'A light,' says Dov. 'In their hands. All the colours the Mere goes in the morning.' He has not slept. 'They went down into the water with it and the water didn't close over them, it opened, like a door. My grandmother said the Mere had a stair in it that went the wrong way.' He looks at you. 'You've got that bell. Down the steps after dark, where they go. If anybody can, it's you.'".
  }
  Rule heart_found when carries(party, ninth_heart) and not heartRecovered(party) { Assert heartRecovered(party). }
  Observe heart_lying near ninth_heart when not carries(party, ninth_heart) and not keeps(reflected, ninth_heart) and not at(ninth_heart, ninth_socket) "On the ground the stone breathes, all the colours of deep water, and the ground round it is white with frost.".

  // Five ways to end it at the top of the stair.
  Relation heartGiven(group). Relation auditSent(group). Relation longWatch(group).
  Action give_heart(actor: group, site: place) "Give the Auditor its heart" {
    Description "What is counted is given.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, auditor_seat) and carries(actor, ninth_heart).
    Time 1.
    On success { Assert heartGiven(actor). }
    Result "You set it on the arm of the glass chair, and take your hand away, and the cold goes out of your fingers at once, as if it had only ever been borrowed.".
  }
  Action send_upward(actor: group, site: place) "Let the heart go up through the opening in the dome, to those who settled the world" {
    Description "The account was addressed. Deliver it.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, model_hall) and carries(actor, ninth_heart) and knows(actor, circles_read).
    Time 1.
    On success { Assert auditSent(actor). }
    Result "You hold it up under the opening in the dome, and open your hand. It does not fall.".
  }
  Action false_figure(actor: group, site: place) "Ask Isaura to write the false figure, in front of the Auditor" {
    Description "One ninth that is not there. Whole, and short, and wrong.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, auditor_seat) and travelsWith(isaura, actor) and isauraWillWrite(isaura) and not countFalsified(reckoner).
    Time 1.
    On success { Assert countFalsified(reckoner). Set approach(bowl) to 0. }
    Result "Isaura kneels at the edge of the still water on the floor and writes in it, with one finger, slowly, in the machine's notation, a single figure. The water takes it. The rings round the chair stop, and the cold stops, and the voice says, after a long time, in the tone of the Office counter, the tone it learned from her grandmother's Office: 'Received. The account is closed. Nothing further is owed.' And then, as the room begins to empty of it, quieter, the voice not quite level: 'That is not what I counted.' Isaura stands up and wipes her finger on her coat, and does not look at anyone, and says: 'Noted.'".
  }
  Action keep_watch(actor: group, site: place) "Stay at the door of the seat, and sing the Fourth Remainder, and go on singing it" {
    Description "High, and deep. For as long as it takes. Aun did forty nights.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, auditor_seat) and knows(actor, lector_words) and knows(actor, auditor_heard).
    Time 2.
    On success { Assert longWatch(actor). }
    Result "You begin. High, and deep. The voice in the room does not interrupt. After a while it begins, very softly, to sing it with you, backward.".
  }

  // If nobody holds it back, in the end the Mere stands up: not as a monster, but as it was. It comes back in one night
  // to the fourth step of the Ward landing, where Isaura learned to swim, copied from the Auditor's memory of it.
  Relation mereStood(place).
  Rule mere_stands when approach(bowl) >= 14 and dark() and not mereStood(bowl) and not complete(reckoner) and not broken(reckoner) and not countFalsified(reckoner) and not auditorSettled(bowl)
    says "In the middle of the night the whole Mere stands up. There is no wave and no sound. The water is simply higher, all at once, as if it had never gone: up over the mud, over the planks, up the Ward landing to the fourth step, exactly to the fourth step, where it stood when the oldest people in the Ward were children; and every boat-ring is under water, and the Tench is afloat at the end of her rope. The surface is so still that the whole Bowl stands upside down in it. In the reflection, every lamp in the Ward is lit, though most of the Ward is dark, and on the landing in the reflection people are standing who are not standing on the landing. In the morning the water is back where it was, a long way off across the mud. Nobody in the city speaks of it, the way nobody spoke of the Long Silence; but Isaura Vant goes down at first light and measures the tide-mark on the fourth step, and writes the figure in her book, and underlines it." {
    Assert mereStood(bowl). Assert strikes(reflected_cold, party). }
}

data/adventures/low-water/company.kyr:
Module lowwater "Low Water" {
  Company party "Your company" of 3 at rim_road.
  Initially Set quantity(party, gold) to 15. Initially Set quantity(party, rations) to 3.
}

data/adventures/low-water/council.kyr:
Module lowwater "Low Water" {
  Description "The Hearing as a council of war: what the Assessor can lay before the Council about what reads the count, the cause named as a creditor, and the three answers the city can give it. Hold the door; enter the Ward as beyond any figure; or, by Harrow Quill's arithmetic, give the creditor the Ward and keep the Bowl.".

  // Before the Hearing: the Registrar and the Guild hear that the count is an account.
  Topic fenn_claim with fenn "Tell the Registrar the count is an account, owed to someone" when knows(actor, auditor_known) once {
    Says "Registrar Fenn hears it all without a word, her pen still. Then she sets the pen down square to the edge of the blotter. 'Then it's a claim,' she says. 'Against the Bowl. By a party not resident.' She looks at the brown plan of the Stair on her wall as if it might have a column for it. 'The Office hears claims. That is what the Office is for. If you can lay it before the Council, Assessor, I will see that it is heard, and I will see that it is minuted, and I will not see anything else, because I do not want to.'".
  }
  Topic quill_creditor with quill "Tell Quill there is a creditor under the Mere" when knows(actor, auditor_known) once {
    Says "Quill does not laugh. He pours himself a glass, looks at it, and does not drink it. 'A creditor,' he says. 'Well. That's the first thing anybody's told me about this business that I understand.' He turns the glass. 'Every creditor can be dealt with, Assessor. That's what a creditor is: somebody who would rather have something than nothing. Find out what it would take instead of the whole.' He looks out of the good window at the Bowl, the terraces, the Ward at the bottom. 'You won't like where that arithmetic goes. I don't. But I'll do it in front of the Council if you won't, because somebody should.'".
  }

  // What can be laid before the Council of the thing that reads the count.
  Entity ex_reflected: exhibit "the Reflected". Entity ex_cipher: exhibit "the Second Reader's footnotes".
  Entity ex_account: exhibit "the account". Entity ex_question: exhibit "the creditor's question".
  Action lay_reflected(actor: group, site: place) "Lay before the Council what comes up out of the Mere at night" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and knows(actor, reflected_known) and not laid(ex_reflected).
    Time 1.
    On success { Assert laid(ex_reflected). Increase credence(council) by 1. }
    Result "You tell them: figures of water, at night, in the shapes of people, the wrong way round, singing; climbing to the Ninth Lock and singing the Rising, so that the Deep Gate goes up. You expect laughter. There is none. The Councillor for the Ninth Lock, the old woman, has put both hands flat on the table. At the back the Ward is quite silent, the way people are silent about a thing they have all seen and never said.".
  }
  Rule ward_saw when laid(ex_reflected) and mereStood(bowl) and not wardSpoke(ammerlin)
    says "From the back of the hall a fisherwoman calls out, not loud: 'The Mere came up to the fourth step last week. In the night. We all saw it.' And then a great many voices at once, the Ward's, all saying the same thing, and the Councillor for the First Lock has to strike the table twice." {
    Assert wardSpoke(ammerlin). Increase credence(council) by 1. }
  Relation wardSpoke(place).
  Action lay_cipher(actor: group, site: place) "Lay before the Council the Second Reader's footnotes, and what Isaura made of them" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and knows(actor, pell_cipher) and not laid(ex_cipher).
    Time 1.
    On success { Assert laid(ex_cipher). Increase credence(council) by 1. }
    Result "WHEN THE COUNT IS WHOLE LET IT THROUGH. THE LOCK IS CUT. THE READER IS NEAR. You read it out, and then you tell them where it came from: twenty years of footnotes from the Collegium of Lesser Instruments, and a hymnal on the Cantor's desk with the cuts already marked in a hand nobody in Ammerlin owns. On the Cantors' bench Sabeth Orr has gone white to the mouth.".
  }
  Rule halm_confesses when laid(ex_cipher) and present(halm) and at(halm, moot_hall) and halmTurned(halm) and not halmConfessed(halm)
    says "Teodor Halm stands, and this time he does not talk quickly. 'I carried those letters,' he says. 'Twenty years. I thought I was his correspondent; I was his postman. I would like that minuted.' He sits. The Registrar minutes it." {
    Assert halmConfessed(halm). Increase credence(council) by 1. }
  Relation halmConfessed(group).
  Action lay_account(actor: group, site: place) "Lay before the Council what the count is: an account of what was taken, owed to the one whose heart is set in the ninth wheel" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and knows(actor, auditor_known) and laid(ex_engine) and not laid(ex_account).
    Time 1.
    On success { Assert laid(ex_account). Increase credence(council) by 1. }
    Result "You tell them what is behind the grille of the ninth arch: a stone that breathes, in a socket of the smallest wheel, and eight sockets empty. What the count is: everything that stone holds in place, written down, a ninth to a page. Whose it is. That when the account is whole, what is counted is given. The hall hears it the way a hall hears a will read: in silence, and then, from everywhere at once, people working out what they are owed and what they owe.".
  }
  Action lay_question(actor: group, site: place) "Put to the Council the creditor's own question: what is the Ward worth?" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and knows(actor, auditor_heard) and laid(ex_account) and not laid(ex_question).
    Time 1.
    On success { Assert laid(ex_question). Increase credence(council) by 1. }
    Result "You tell them you have been up the stair, and stood in front of it, and that it asked you a question, and that it learned to ask questions here, from the Office, the month after the Thirst Riots. Then you put the question to them in its own words. What is the Ward worth? The fishers, the boats, the steps with the paint on. Nobody answers. It is the longest silence you have heard in Ammerlin that was not under it.".
  }

  // The cause, named as what it is.
  Relation causeAccount(group).
  Action name_account(actor: group, site: place) "Name the cause: a creditor, reading the count through the last door, and a city that stopped singing the verses that kept the door small and shut" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and laid(ex_account) and laid(ex_hymn).
    Time 1.
    On success { Assert named(actor). Assert causeEngine(actor). Assert causeHymn(actor). Assert causeAccount(actor). }
    Result "You name it: a machine that counts, a hymn that told it how much to drink and when to keep its last door shut, a reform that stopped the telling, and on the other side of the door, waiting for the count to be whole, the one it is owed to. Every person in the city doing their job; and one more, not a person, doing its own. The Registrar writes for a long time.".
  }
  // Quill's arithmetic, when the cause is a creditor.
  Relation priced(group).
  Rule quill_prices when causeAccount(party) and not priced(quill)
    says "Harrow Quill rises, and for once there is no smile at all. 'I'll say what nobody else in this hall is going to,' he says. 'A creditor would rather have something than nothing. The whole Bowl is the whole of what it can take. So offer it less.' He holds up the Ward map with the red ink on it. 'The Ward plots, at the Guild's valuation, which is generous: eleven thousand crowns. The rest of the Bowl, Rim to Mere: four hundred thousand. I am a practical man. If it will take the Ward in settlement, give it the Ward, and move the Ward up the terraces, and pay them, and keep the city.' He puts the map down. 'The good of the many is a sum. I didn't say it was a kind one.' The Ward, at the back, does not make a sound." {
    Assert priced(quill). Assert answered(quill). }

  // Three answers the city can give.
  Relation askFourth(group). Relation askInestimable(group). Relation askSettle(group).
  Action ask_fourth(actor: group, site: place) "Ask the Council to order the Fourth Remainder sung every night after the Seventh, and the last door held shut" {
    Description "Aun's answer: keep it shut, for as long as there is anyone to sing.".
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and named(actor) and causeAccount(actor) and not remedied(actor) and hearingOpen(ammerlin).
    Time 1.
    On success { Assert remedied(actor). Assert askFourth(actor). }
    Result "The Seventh, every night, as it was for three thousand years; and after it, the Fourth, high and deep, the last door, least. Not an answer to the creditor: a refusal to let the question be asked. You say so.".
  }
  Action ask_inestimable(actor: group, site: place) "Ask the Council to enter the Ward in the Office's ledger as inestimable, beyond any figure, and send that down as the city's answer" {
    Description "An honest figure. The largest one there is.".
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and named(actor) and causeAccount(actor) and laid(ex_question) and not remedied(actor) and hearingOpen(ammerlin).
    Time 1.
    On success { Assert remedied(actor). Assert askInestimable(actor). }
    Result "You ask them to answer the question it asked: to write in the Office's own ledger, in the Office's own words, that the Ward of Ammerlin is inestimable; and to read it out in the square, as the Office read out every right after the Thirst Riots, so that the water hears it. Registrar Fenn looks up sharply at that, and then, slowly, nods.".
  }
  Action ask_settle(actor: group, site: place) "Ask the Council to offer the creditor the Ward in settlement, as Quill reckons it, and move the Ward up the terraces" {
    Description "The good of the many is a sum.".
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and named(actor) and causeAccount(actor) and priced(quill) and not remedied(actor) and hearingOpen(ammerlin).
    Time 1.
    On success { Assert remedied(actor). Assert askSettle(actor). }
    Result "You ask for it. You hear yourself ask for it. At the back of the hall the Ward stands up, all of it, the way it stood up for the names of the drowned, and stays standing.".
  }
  Rule isaura_refuses_settle when askSettle(party) and travelsWith(isaura, party) and not dissented(isaura)
    says "Isaura Vant does not stand. She closes her book, and puts it in her coat, and sits with her hands in her lap, and says, quite quietly, so that only you and the Council's end of the table can hear: 'No. I won't measure that. Find somebody else.'" {
    Assert dissented(isaura). }

  Relation verdictFourth(place). Relation verdictInestimable(place). Relation verdictSettle(place).
  Rule council_fourth when askFourth(party) and hearingDone(ammerlin) and credence(council) >= 6 and not decided(council)
    says "'The Council accepts the Finding,' says the Councillor for the First Lock. 'The Sounding is to sing the Seventh Remainder every night, and after it the Fourth, and the keeper of the Ninth Lock to record both. The Guild is not found the cause, and its charter is renewed.' She pauses, and adds, not from her paper: 'And the Council would be glad if somebody could tell it, one day, who Aun was.'" {
    Assert decided(council). Assert verdictFourth(ammerlin). Assert charterRenewed(ammerlin). Assert seventhRestored(bowl). Assert restoredForGood(bowl). Assert fourthRestored(bowl). }
  Rule council_inestimable when askInestimable(party) and hearingDone(ammerlin) and credence(council) >= 7 and not decided(council)
    says "The Councillor for the First Lock stands with a paper in her own hand, and does not read from it. 'The Council accepts the Finding. There is entered in the ledger of the Office of Measures, against the claim of the party not resident, the value of the Ward of Ammerlin: inestimable. The Office shall read it out in the square, at noon, for thirty days. The Sounding shall sing the Seventh Remainder every night, as the Assessor has shown it must. The Ward's titles are frozen until further order. The charter is renewed.' Quill, on the front bench, closes his eyes, and opens them, and says to nobody: 'Well. That's a figure too.'" {
    Assert decided(council). Assert verdictInestimable(ammerlin). Assert wardValued(bowl). Decrease approach(bowl) by 3. Assert charterRenewed(ammerlin). Assert seventhRestored(bowl). Assert restoredForGood(bowl). Assert titlesFrozen(ammerlin). }
  Rule council_settles when askSettle(party) and hearingDone(ammerlin) and credence(council) >= 3 and not decided(council)
    says "The Council is out a long time. When the nine come back the Councillor for the First Lock does not stand. 'The Council accepts the Finding, by five to four. The Ward of Ammerlin is to be offered in settlement of the claim of the party not resident, at the Guild's valuation. The Ward's people are to be housed on the upper terraces at the Guild's charge, and compensated at the same valuation, from the Office's funds. The charter is renewed.' The Councillor for the Ninth Lock, the old woman, gets up and walks out of the hall without asking leave." {
    Assert decided(council). Assert verdictSettle(ammerlin). Assert charterRenewed(ammerlin). }

  // What each answer does after the Hearing.
  Observe square_reading at measures_square when verdictInestimable(ammerlin) and hour(clock) == 12 "At noon a clerk of the Office stands on the fountain's rim and reads, in a voice that never goes up or down, from a ledger held open in both hands: 'Against the claim of the party not resident: the Ward of Ammerlin. Inestimable.' Then the next entry, and the next, every right in the Bowl. Nobody stops to listen. The fountain, behind him, is perfectly still.".
  Topic auditor_heard_verdict with auditor "Tell the Auditor what the Council entered in the ledger" when verdictInestimable(ammerlin) once {
    Says "'I heard,' says the voice. 'At noon. A young man on the rim of your fountain, reading.' The rings in the water widen, very slowly, and settle, and widen. 'Thirty days, the order says. The ell and the hour and the name.' A long silence. 'It is the second time. I did not think I would hear it again.' The cold in the room is less, as if a window had been opened somewhere far off. 'Inestimable is not a figure I can close. Your Office knew that when it wrote it.' Another silence. 'Tell them it is received.'".
  }
  // The settlement: the creditor takes the Ward. The Mere stands up to the fourth step and stays, and the Ward is under it.
  Relation wardGiven(place). Relation auditorSettled(place).
  Rule ward_taken when verdictSettle(ammerlin) and hour(clock) == 0 and not wardGiven(ammerlin)
    says "At midnight, from the bottom of the Bowl, a sound like a great many people breathing in. In the morning the Mere stands at the fourth step of the Ward landing, as it stood when the oldest people in the Ward were children, perfectly still; and Tench Row is under it to the eaves; and in the windows of Tench Row, under the water, the lamps are lit." {
    Assert wardGiven(ammerlin). Assert auditorSettled(bowl). Set approach(bowl) to 0. Set mere(bowl) to 64. }
  Observe ward_under at ward_landing when wardGiven(ammerlin) "The Mere stands at the fourth step of the Ward landing, so clear you can see the painted spans going down under it, and the boat-rings, and the mud where the planks were, and Tench Row standing in it to the eaves with every door open and every lamp lit. Things move in the houses, slowly, the wrong way round. The Ward's people have been housed on the second terrace, in Guild lodgings, and come down in the evenings to the top step, and sit, and do not talk much.".
  Observe isaura_resigned at office_hall when verdictSettle(ammerlin) "Isaura Vant's desk in the hall of the Office is cleared. Her ell-rod is gone from its hook. On the blotter, square to the edge, a single sheet, in her hand: Resigned. Not measured.".
  Objective objective_settle when verdictSettle(ammerlin) and not wardGiven(ammerlin) "The Council has offered the creditor the Ward. You will know by morning whether it was accepted.".
}

data/adventures/low-water/dyers.kyr:
Module lowwater "Low Water" {
  Description "The Dyers' Terrace: the Upper Cistern, the Dyers' Basin with an arch on its floor, the Sump, Mag Torrin's vat-yard, and the house of Abel Tarrant, who taught the Lock-Rhyme to two generations of keepers.".


  Place dyers_walk "the Dyers' Walk" is room within ammerlin at 1, 2 outdoors.
  Place cistern_lip "the lip of the Upper Cistern" is room within ammerlin at 0, 2 outdoors.
  Place basin_edge "the edge of the Dyers' Basin" is room within ammerlin at 2, 2 outdoors.
  Place basin_floor "the floor of the Dyers' Basin" is room within ammerlin at 2, 3 outdoors.
  Place vat_yard "Mag Torrin's vat-yard" is room within ammerlin at 3, 2 outdoors.
  Place lusk_house "Abel Tarrant's house" is building within ammerlin.
  Place lusk_room "Abel Tarrant's kitchen" is room within lusk_house at 0, 0.

  Passage second_stair "the Stair, from Measures Terrace to the Dyers' Walk" is steps between measures_square and dyers_walk taking 15 minutes.
  Passage cistern_steps "the steps to the cistern" is steps between dyers_walk and cistern_lip.
  Passage basin_path "the path along the basins" is path between dyers_walk and basin_edge taking 3 minutes.
  Passage yard_gate "the vat-yard gate" is gate between basin_edge and vat_yard.
  Passage lusk_door "Abel Tarrant's door" is door between dyers_walk and lusk_room.
  Passage basin_ladder "the iron ladder down the basin wall" is steps between basin_edge and basin_floor
    opening when level(dyers) <= 1 "An iron ladder goes down the inside of the basin wall and into the water. Below the third rung there is nothing to see but black dye-water.".

  // Three bodies of water, and the two gates between them. Water passes from the higher to the lower, a mark a
  // watch, until they stand level or the lower is full; it is never made and never lost, only moved.
  Kind basin. Entity upper: basin "the Upper Cistern". Entity dyers: basin "the Dyers' Basin". Entity sump: basin "the Sump".
  Measure level(basin). Measure brim(basin).
  Initially Set level(upper) to 4. Initially Set brim(upper) to 5.
  Initially Set level(dyers) to 3. Initially Set brim(dyers) to 3.
  Initially Set level(sump) to 2. Initially Set brim(sump) to 3.

  Thing upper_gate "the upper gate" at cistern_lip {
    State wound_down "The upper gate between the Cistern and the Dyers' Basin is wound down. The Cistern's post stands at {level(upper)}, the basin's at {level(dyers)}.".
    State wound_up "The upper gate is wound up; water goes through it from the Cistern into the Dyers' Basin. The Cistern's post stands at {level(upper)}, the basin's at {level(dyers)}.".
    Change open "Wind the upper gate up" from wound_down to wound_up.
    Change shut "Wind the upper gate down" from wound_up to wound_down.
  }
  Thing sump_gate "the sump gate" at basin_edge {
    State wound_down "The sump gate at the foot of the Dyers' Basin is wound down. The basin's gauge-post stands at {level(dyers)}, the Sump's at {level(sump)}.".
    State wound_up "The sump gate is wound up; the Dyers' Basin pours through it into the Sump. The basin's gauge-post stands at {level(dyers)}, the Sump's at {level(sump)}.".
    Change open "Wind the sump gate up" from wound_down to wound_up.
    Change shut "Wind the sump gate down" from wound_up to wound_down.
  }
  Thing overflow "the Sump's overflow" at basin_edge {
    State chained "On the Sump's far side, a sluice the size of a door is chained shut. A painted board: WARD DRAIN. BY TORRIN'S YARD. KEEP SHUT.".
    State unchained "The Sump's overflow stands open; the Sump runs out of it down the Ward drain, by way of Mag Torrin's yard. The Sump's post stands at {level(sump)}.".
    Change open "Unchain the Sump's overflow and open it" from chained to unchained.
    Change shut "Close the Sump's overflow" from unchained to chained.
  }
  Rule upper_flows when state(upper_gate, wound_up) and level(upper) > level(dyers) and level(dyers) < brim(dyers) {
    Decrease level(upper) by 1. Increase level(dyers) by 1. }
  Rule sump_flows when state(sump_gate, wound_up) and level(dyers) > level(sump) and level(sump) < brim(sump) {
    Decrease level(dyers) by 1. Increase level(sump) by 1. }
  Rule overflow_runs when state(overflow, unchained) and level(sump) > 0 {
    Decrease level(sump) by 1. Assert vatsDrowned(vat_yard). }
  Relation vatsDrowned(place).

  // The gauge-posts tell the truth, every one of them, all the time.
  Observe cistern_gauge at cistern_lip when true "The Upper Cistern is a long stone tank under the terrace wall, brimming from the Stair. Its gauge-post stands at {level(upper)}, of five marks.".
  Observe basin_gauge at basin_edge when true "The Dyers' Basin is a square stone pool three marks deep, its water black-blue from a hundred years of dye. Its gauge-post stands at {level(dyers)}, of three marks. Below it the Sump, a lower tank, stands at {level(sump)}, of three.".
  Observe basin_shape at basin_edge when level(dyers) >= 2 "Down through the dark water something pale stands on the basin floor: the top of an arch, too far down to make out.".
  Observe basin_shallow at basin_edge when level(dyers) == 1 "The basin is down to its last mark. An arch stands up out of the shallows on the floor, carved, grey, too old for the terrace it is in.".
  Observe basin_dry at basin_edge when level(dyers) == 0 "The Dyers' Basin is empty, its walls striped blue to the brim. On its floor stands an arch of grey stone, carved all over.".
  Observe floor_scene at basin_floor when true "The basin floor is slick with blue silt to the ankle. In the middle stands an arch of fine grey stone with nothing behind it but more floor, its face carved with a row of four mouths, each open wider than the last, and beside each a mark like a note of the Sounding's.".
  Observe floor_stones at basin_floor when at(weight_a, basin_floor) or at(weight_b, basin_floor) or at(weight_c, basin_floor) "Round the arch's foot lie blocks of the same grey stone, squared, each with a hole through it for a rope.".
  Observe floor_wet at basin_floor when level(dyers) == 1 "The water is ankle-deep and very cold.".

  Observe walk_scene at dyers_walk when not familiar(dyers_walk) "The Dyers' Walk runs along the third terrace between the Stair and the basins, under lines of dyed wool hung out to dry, so that you walk through a long room of blue and madder and weld-yellow, dripping. The terrace wall below is striped with old dye-runs to the Ward.".
  Observe walk_scene_again at dyers_walk when familiar(dyers_walk) "The Dyers' Walk, under its dripping lines of blue and madder.".
  Observe walk_rhyme at dyers_walk when hour(clock) == 9 and not drawnToday(vat_yard) "The third bell rings from the Sounding, and all along the Walk the dyers look up, as if it had called each of them by name.".
  // The dyers' own draw: at nine, the third bell, Mag Torrin takes a mark of the basin into her vats for the day's blue.
  // At six each morning the Office's man winds the Cistern into the basin until it is full, and the Cistern from the Stair.
  Relation drawnToday(place).
  Rule mag_draws when hour(clock) == 9 and not drawnToday(vat_yard) and level(dyers) >= 1 and not vatsDrowned(vat_yard) {
    Decrease level(dyers) by 1. Assert drawnToday(vat_yard). }
  Rule mag_draws_seen at basin_edge when hour(clock) == 9 and drawnToday(vat_yard) and not toldDraw(vat_yard)
    says "At the third bell a sluice in the yard wall grunts open and a mark of the basin goes off into Mag Torrin's vats in a blue rush." {
    Assert toldDraw(vat_yard). }
  Relation toldDraw(place).
  Rule morning_fill when hour(clock) == 6 and drawnToday(vat_yard) {
    Retract drawnToday(vat_yard). Retract toldDraw(vat_yard). Set level(dyers) to 3. Set level(upper) to 4. Set level(sump) to 2. Assert state(upper_gate, wound_down). }
  Rule morning_fill_dry when hour(clock) == 6 and not drawnToday(vat_yard) and level(dyers) < 3 and not filledToday(vat_yard) {
    Set level(dyers) to 3. Set level(upper) to 4. Set level(sump) to 2. Assert filledToday(vat_yard). Assert state(upper_gate, wound_down). }
  Rule fill_resets when hour(clock) == 7 and filledToday(vat_yard) { Retract filledToday(vat_yard). }
  Relation filledToday(place).
  // Bailing, by hand, a mark at a time.
  Action bail_basin(actor: group, site: place) "Bail the Dyers' Basin with the dyers' buckets" {
    Description "Two hours of buckets for a mark of water, tipped down the dyers' drain.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, basin_edge) and level(dyers) >= 1 and level(dyers) <= 2.
    Time 12.
    On success { Decrease level(dyers) by 1. }
    Result "It is two hours of filling a leather bucket from the ladder, handing it up, and tipping it down the dyers' drain, and at the end your arms are blue to the elbow and the basin is a mark lower.".
  }

  // The arch: four mouths and four notes, and the stones of its foot.
  Kind arch_rubbing "a rubbing of the Dyers' arch" is treasure worth 0 weighing 0 described "Charcoal on a dyer's cloth: four mouths, each wider than the last, a mark like a note beside each, and over them a line of Aenean letters.".
  Relation rubbed(entity).
  Thing arch "the grey arch" at basin_floor {
    State carved "The arch's face is carved with four mouths in a row, each open wider than the last, each with a note-mark beside it, under a line of letters you cannot read.".
    Tries looking.
  }
  Action rub_arch(actor: group, site: place) "Take a rubbing of the arch's face on a dyer's cloth" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, basin_floor) and not rubbed(arch).
    Time 2.
    On success { Assert rubbed(arch). }
    Result "You wet a dyer's cloth, lay it over the carving, and work charcoal over it until the mouths and their marks and the line of letters come up black. It will have to be someone else who reads it.".
  }
  Item rubbing "the rubbing of the arch" is arch_rubbing at basin_floor hidden until arch_rubbed.
  Discovery arch_rubbed "A rubbing of the Dyers' arch lies on the basin floor, taken on a dyer's cloth.".
  Rule rubbing_made when rubbed(arch) and not knows(party, arch_rubbed) says "You fold the cloth with the charcoal inside." teaches arch_rubbed { }
  Discovery arch_mouths "The grey arch on the Dyers' Basin floor shows four mouths, from closed to wide open, each beside a mark like one of the Sounding's notes.".
  Rule arch_looked when tried(arch, looking) and not knows(party, arch_mouths)
    says "Four mouths, carved by someone who had looked hard at mouths: a mouth shut, a mouth a little open, a mouth open to speak, and a mouth wide as if to swallow. Beside each, the same small mark, set higher each time: like the notes in a hymnal, four of them, low to high." teaches arch_mouths { }
  Kind weight_stone "an Aenean weight-stone" is treasure worth 1 weighing 4 described "A squared block of grey stone, cold, heavier than it looks, with a hole through it for a rope.".
  Item weight_a "a weight-stone" is weight_stone at basin_floor.
  Item weight_b "a weight-stone" is weight_stone at basin_floor.
  Item weight_c "a weight-stone" is weight_stone at basin_floor.

  // Mag Torrin and her vats.
  Observe yard_scene at vat_yard when not vatsDrowned(vat_yard) "A yard of tall wooden vats, steaming, each a different blue. Lengths of wet wool hang in the air between the vats like slow banners. Everything, the cobbles, the cat, the woman with the paddle, is some shade of blue.".
  Observe yard_ruined at vat_yard when vatsDrowned(vat_yard) "The vat-yard is a pond. Grey Sump water stands a hand deep across the cobbles and has gone into every vat, and the blues have all gone the same dull colour, like a bruise. Wool lies in it in heaps.".
  Person mag "Mag Torrin" at vat_yard {
    Greets "Mag Torrin keeps stirring. 'If it's about the water,' she says, 'it's always about the water.'".
    Role "dyer and widow of the Dyers' Terrace". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
  }
  Topic mag_basin with mag "Ask Mag Torrin about the Dyers' Basin" when true once {
    Says "'It's my water.' Mag does not stop stirring. 'Mine and four other yards', by right, a mark a day each between us, and I take mine at the third bell for the blue, because blue wants the morning. The Office's man fills it again at six.' She points the paddle at you. 'And there's a stone thing on the bottom nobody's seen in my lifetime and my mother's. Don't go getting ideas. You drain my basin and I've no blue tomorrow.'".
  }
  Topic mag_sump with mag "Ask Mag what happens if the Sump runs over" when true once {
    Says "'Then it comes down the Ward drain, and the Ward drain comes through my yard, because my grandfather was a fool and built where it was cheap.' She nods at the vats. 'Sump water's grey. One hand of it in a vat and the dye's dead, the whole season's dead. Twice in my life. The second time I had to sell my husband's boat.'".
  }
  Relation askedEarly(group).
  Topic mag_early with mag "Ask Mag to take her blue now instead of at the third bell" when not drawnToday(vat_yard) and hour(clock) >= 6 and hour(clock) < 9 and level(dyers) >= 1 and not vatsDrowned(vat_yard) once {
    Says "Mag looks at the sky, and at you, and at the basin. 'Early blue's thin,' she says. 'But I suppose thin's better than none, which is what I'll get if you're going to stand there all morning.' She goes to the yard wall and hauls the sluice. A mark of the basin comes off into the vats in a blue rush.".
    On discuss { Decrease level(dyers) by 1. Assert drawnToday(vat_yard). Assert toldDraw(vat_yard). Assert askedEarly(actor). }
  }
  Event mag_ruined near mag when vatsDrowned(vat_yard) "Mag Torrin stands in the grey water of her yard with the paddle still in her hand. She does not shout. She looks at you, a long time, as if to be sure of your face." then {
    Assert grievance(mag, party). }
  Relation grievance(group, group).
  Topic mag_after with mag "Say something to Mag Torrin about her vats" when vatsDrowned(vat_yard) once {
    Says "'Don't,' she says. 'You wanted the floor of my basin and you got it. I hope there was something on it worth a season.' She wades to the nearest vat and starts bailing it with her hands. Over her shoulder: 'I'll be at the Council. I'll say what you did. I'll say it in a good clear voice.'".
  }

  // Abel Tarrant and the Lock-Rhyme.
  Observe lusk_scene at lusk_room when true "A kitchen with one chair by the stove and a lock-keeper's brass horn on a nail over it. On the shelf, a row of small clay figures of men and women each holding a lock-wheel: forty of them, the keepers he taught, he says, though he made them himself and some of them flatter.".
  Person abel "Abel Tarrant" at lusk_room {
    Greets "Abel Tarrant is delighted to see anybody at all, and says so, and offers you the only chair.".
    Role "who kept the Ninth Lock for forty years". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
  }
  Discovery lock_rhyme "The Lock-Rhyme, which every keeper learns: Upper to Dyer at the bell of six, / Dyer to vat when the third bell ticks; / Rise at the Sixth, and the Deep goes up, / Count at the Seventh, it takes its cup; / Grey from the Rim when the Mere is low, / And the high voice never, or down we go." { Known by abel. }
  Topic abel_rhyme with abel "Ask Abel Tarrant for the Lock-Rhyme" when true once {
    Says "Abel sits up straight, puts his hands on his knees, and says it as a boy says it in school, in a sing-song, with a little bounce on the beat. 'Upper to Dyer at the bell of six, / Dyer to vat when the third bell ticks; / Rise at the Sixth, and the Deep goes up, / Count at the Seventh, it takes its cup; / Grey from the Rim when the Mere is low, / And the high voice never, or down we go.' He beams. 'Forty keepers. Every one of them could say that backwards drunk. The children in the Ward skip to it.'".
    On discuss { Assert knows(actor, lock_rhyme). }
  }
  Topic abel_deep with abel "Ask Abel what 'the Deep goes up' means" when knows(actor, lock_rhyme) once {
    Says "'The Deep Gate. Bottom of my old lock, a great bronze door in the floor.' He shows you with his hands, flat, then tipping up on edge. 'At the Sixth Remainder, of an evening, up it comes by itself; and at the Seventh down it goes, by itself, and lets through a cupful the night long. The keeper's to watch it, that's all, and write it in the book, and if it ever didn't, send to the Sounding.' He chuckles. 'It always did. Forty years. You could set your supper by it.'".
  }
  Topic abel_grey with abel "Ask Abel what 'grey from the Rim' means" when knows(actor, lock_rhyme) once {
    Says "'Ah, now.' He scratches his jaw. 'That one nobody knows. My master didn't know. There's a grey arch up at the head, bricked, and some say that's it, and some say it's just a thing to rhyme with low.' He leans in. 'I'll tell you what I think. I think the old ones had a back way to the Deep, for a dry year. To feed it from the top when the Mere couldn't. And somebody bricked it, because what kind of fool sends good river down a hole?'".
  }
  Topic abel_high with abel "Ask Abel what 'the high voice never' means" when knows(actor, lock_rhyme) once {
    Says "His face changes; he looks, for a moment, like the boy who first learned it, and was frightened by it. 'Never sing the high note into the water. That's all it means. Every keeper's told it his first night, by his master, at the lock, with the lantern out.' He laughs, uneasily. 'Superstition. Children's stuff. Only I never did. Did you ever meet a keeper that did? No. Nor me.'".
  }
  Topic abel_piet with abel "Ask Abel about the keeper of the Ninth Lock now" when true once {
    Says "'Piet Harl. My last. Good lad, too careful by half, which is the right half.' Abel's smile goes. 'He came up to me the first winter of the new Hymn and said, Master Tarrant, the Deep didn't come down. I said, then send to the Sounding, like the rhyme says. He said he had. I said, then send again.' He looks at his hands. 'That was three years ago. I'm an old man, I forget things. I should have gone down there myself.'".
  }
  Topic abel_hymn with abel "Ask Abel what he thinks of the Short Hymn" when true once {
    Says "'It's lovely,' says Abel, surprising you. 'It is. I went the once. All those young ones, the place full like a fish-market. Sabeth Orr's a wonder.' He shrugs. 'But they've cut the Remainders, and the rhyme's built on the Remainders. Rise at the Sixth, count at the Seventh. There's no Seventh now. I said so to a young Cantor and he said the rhyme was only a rhyme.' He looks at the clay keepers on the shelf. 'Well. So it is.'".
  }
  Topic abel_fountains with abel "Ask Abel whether anything else changed when the Hymn was shortened" when true once {
    Says "Abel thinks about it seriously; he is a man who has been asked very few serious questions lately and is enjoying this one. 'The fountains,' he says. 'Now you ask. When I was a boy the fountains hummed of an evening, after the Seventh, at the Fifth. You'd put your hand on the square fountain and feel it go. We called it the Bowl purring.' He frowns. 'It stopped the same winter. I thought I'd gone a bit deaf. Everybody my age thought they'd gone a bit deaf.'".
  }
  Topic abel_arch with abel "Show Abel Tarrant the rubbing of the Dyers' arch" when carries(actor, rubbing) once {
    Says "Abel holds the cloth to the window a long time. 'Four mouths. Shut, a bit, open, wide.' He traces the marks beside them. 'And the notes go up. The bottom note by the shut mouth.' He gives it back to you slowly. 'That's the Deep, isn't it. Low for little. That's the Seventh, all low; a cupful.' He sits down. 'Forty years, and I never once thought the notes meant anything. Take it to Sabeth Orr. She'll know the notes.'".
  }
}

data/adventures/low-water/echoes.kyr:
Module lowwater "Low Water" {
  Description "Echoes: what the Bowl shows, before anyone knows how to read it, of the account kept on the other side of the water. The Office's double entry, the green glass in the Rim's dust, the Ward's mirrors turned to the wall, the reflection that lifts its hand a moment late; and, later, the Cantor and the scholar learning what their own doubles did.".

  // Double entry: the form the whole account takes. Every figure entered twice, once where it left and once where it
  // arrived; Isaura's forty ells are a figure with no other side, until the Interval.
  Topic isaura_double with isaura travelling "Ask Isaura why every figure in the Office ledgers is written twice" when been(party, ledger_room) or knows(actor, channel_measured) once {
    Says "'Double entry.' She is pleased you noticed. 'Every ell that leaves somewhere arrives somewhere. So you write it twice: once on the side it left, once on the side it came to. Then you add up both sides. If they agree, the book is honest. If they don't, somebody is lying, or somebody is wrong, and you go and find out which.' She opens her own book and turns it so you can see: two columns, ruled in red, a figure on the left, the same figure on the right, all the way down the page. 'Fourth Grade copies the book. Third Grade checks the copy against the water. It's very boring.' She turns the page over to check the back of it. 'It's the most beautiful thing anyone ever invented. A book that checks itself.'".
  }
  Topic isaura_other_side with isaura travelling "Ask Isaura where the forty ells went" when knows(actor, water_kept) and knows(actor, discrepancy) once {
    Says "Isaura stands at the edge of the still water and looks out at the copied city for a long time. 'Here,' she says. 'Both sides. The ells left the Mere and never arrived anywhere in the Bowl, so I had a figure with nothing on the other side of the line.' She points with the ell-rod, out across the water, at the clear terraces. 'That's the other side of the line. Somebody else has been keeping the other column. In water.' She closes her book very carefully. 'It balances. I've been wrong for three years. It balances perfectly. It's just that the book is bigger than the Bowl.'".
  }
  Observe office_glass at office_hall when true "On the far wall of the hall, facing the door, hangs an old glass, black with age, as tall as a man. The clerks call it the Check. The words over the inner door are cut in it backward, so that as you stand at the counter you read them in the glass the right way round, over your own shoulder: WHAT IS MEASURED HONESTLY CAN BE SETTLED PEACEFULLY. Your own face is in it too, under the words.".
  Topic isaura_check with isaura travelling "Ask Isaura about the black glass in the Office they call the Check" when been(party, office_hall) once {
    Says "'The Check. It came with the building; nobody knows from where.' She glances at it the way you glance at a clock. 'You're meant to read the motto in it while you make your claim, so you see your own face saying it. People lie less to a counter with a glass behind it. The Registrar had it measured once: it's not quite flat. Your face in it is the right size and very slightly the wrong way round. Nobody can see it unless they're told.' A beat. 'I've been told. I can't stop seeing it.'".
  }

  // The Bowl is a print: green glass in the Rim's dust, splashed when it was made, and a scholar who cannot account for it.
  Observe rim_tears at rim_road when true "In the dust by the carters' trough there are beads of green glass the size of lentils, and a child with a tray is selling them: Mere-tears, a copper a handful, lucky for a journey. When you hold one to the light there is a bubble in it, perfectly round.".
  Topic halm_print with halm "Ask Halm what made the Bowl" when true once {
    Says "'Not fire from below.' He says it at once, as if he has been waiting years for somebody to ask. 'Everybody says an old mountain that fell in on itself. It isn't. The rock of the Rim has been pushed outward and up, like wax round a seal, and it's fused: glass, green glass. You've seen the children selling it on the north road.' He picks a bead out of his waistcoat pocket and turns it. 'Something came down here. From above, hard, and small, and very heavy. The Aeneans called the Bowl the Print. I used to think it was poetry.' He puts the bead away. 'I'd give my fellowship to know what it was, and where it went.'".
  }

  // The Ward's mirrors, turned to the wall at night, so the water cannot learn your face.
  Observe ward_mirrors at tench_row when dark() and not wardEmpty(ammerlin) "In every lit window of Tench Row the little shaving-mirrors and the polished pans have been turned to face the wall.".
  Topic dov_mirrors with dov "Ask Dov why the Ward turns its mirrors to the wall at night" when true once {
    Says "'So the water can't learn your face.' He laughs, short. 'My grandmother's saying. Everybody does it and nobody believes it, the way you don't walk under a net.' He turns a float in his hands. 'Annet Kettle's mother stopped, the year the Mere went down past the boat-rings. Said there was no water near enough now to learn anything off anybody.' He puts the float down. 'Isaura never did it. She said it was unscientific. She used to turn ours face-out again when Mother wasn't looking.'".
  }

  // At dusk, before anyone has seen the Reflected, the Mere gives back your reflection a moment late.
  Observe mere_lag at mere_edge when hour(clock) >= 17 and hour(clock) < 21 and not knows(party, reflected_known) and not wardEmpty(ammerlin) "You lean over the water. The Mere is so still that the whole Bowl stands upside down in it, and you in it, looking up. You raise a hand to shade your eyes against the last of the sun. Your reflection raises its hand a moment after you do. It must be the cold; the water is very still.".

  // As the approach grows: frost on the fountain in summer, and wet prints in the morning on the lock steps.
  Observe fountain_frost at measures_square when dark() and approach(bowl) >= 4 and not complete(reckoner) and not broken(reckoner) "There is frost on the lip of the fountain, in a ring, though the night is warm.".
  Observe lock_prints at ninth_lock when hour(clock) >= 6 and hour(clock) < 10 and approach(bowl) >= 3 and not broken(reckoner) "On the lock steps the night's wet has dried everywhere but in a line of broad flat prints, going down. Piet Harl has thrown sand on them, and written something in his book, and does not look at you.".

  // The Lector's bench in the real Sounding: the face the Auditor copied.
  Observe lector_bench at nave when true "Against the wall of the nave, apart from the choir's benches, stands a bench of the old grey stone that nobody sits on, with a woman's face carved over it, worn almost smooth by three thousand years of hands: eyes shut, mouth open, singing. The choir touch it going in, without looking, the way you touch a doorpost.".
  Topic orr_bench with orr "Ask Cantor Orr whose face is carved over the empty bench" when been(party, nave) once {
    Says "'The Lector's.' Orr does not need to ask which bench. 'The first Cantor before there were Cantors. Nobody sits there. Dunstan says it is the damp in the oak; the oak has not been damp in forty years. The young ones touch it for luck.' She smiles slightly. 'I did, when I was in the choir. I stopped when I became Cantor. It seemed presumptuous.'".
  }
  Topic orr_aun with orr "Tell Cantor Orr who the Lector was, and what she did at the column" when knows(actor, lector_words) or knows(actor, long_silence) once {
    Says "You tell her: Aun, Lector of the Ear; the year the young Cantors left out the Fourth, and the Mere stood up; forty nights at the column, singing it shut; and that she did not come up. Orr does not move. The half-hour strikes somewhere in the Sounding and she lets it. Then she gets up and goes out into the nave, and you follow her, and she stands in front of the empty bench with the carved face over it. 'I cut it,' she says. 'Her verse. The one she went down for. Because the young ones found it dreary.' Her voice is perfectly steady and her hands are not. 'Somebody marked my hymnal so I would. And I did. I thought it was my own idea. That's the part I can't bear: I was so proud of it.' She puts her hand flat on the stone, where the choir's hands have worn it. 'She was right, you know. It is dreary. It's supposed to be. You don't sing a lock for pleasure.'".
  }

  // Halm, turned, learns what his patron was writing to; and offers a lie of his own, a scholar's.
  Relation halmFootnote(group).
  Topic halm_auditor with halm "Tell Halm what the Second Reader has been writing to" when knows(actor, auditor_heard) and halmTurned(halm) once {
    Says "Halm listens with his hands folded, the way he listens to a stone being read. When you have done he says nothing for a while. 'Twenty years,' he says at last. 'I carried his letters to the Rim post myself. I thought I was his correspondent. I was his postman.' He takes off his spectacles. 'He'll write again at midwinter. He always does. He'll want to know whether the count is whole.' He puts them back on. 'I could answer him. In his own footnotes. A wrong date, a wrong ninth, a Lector's verse misread; he would believe me, because he taught me the cipher and he knows I am too vain to make a mistake in it.' He looks at you over the spectacles. 'It would be the only dishonest thing I have ever published. Shall I?'".
  }
  Topic halm_footnote with halm "Ask Halm to answer the Second Reader with a false footnote" when knows(actor, auditor_heard) and halmTurned(halm) and not halmFootnote(halm) once {
    Says "'Then I'll do it properly.' He sits down on an upturned basket at once and begins, in a hand far smaller than his own. After a while he says, without looking up: 'Do you know, it's the most careful thing I've ever written. A lie has to be. The truth you can be sloppy with; it holds up on its own.'".
    On discuss { Assert halmFootnote(halm). Set footnoteAt(halm) to watch(clock). }
  }
  // Two days later the Collegium's courier comes down the north road, and the Second Reader has answered.
  Measure footnoteAt(group).
  Observe halm_answered near halm when halmFootnote(halm) and watch(clock) >= footnoteAt(halm) + 288 "Halm has a letter open on his knee, in a small even hand, with the footnotes in red. He holds it out to you without a word. In the margin of the third page, against his own false date, the Second Reader has written, in ink, not cipher: Thank you. Most helpful. I shall go elsewhere this winter. Halm takes it back and folds it very small. 'He believed me,' he says. 'Of course he did. I've never lied to him before.' He does not look pleased. He looks like a man who has found out what he is capable of.".
}

data/adventures/low-water/halm.kyr:
Module lowwater "Low Water" {
  Description "Teodor Halm, Fellow of the Collegium of Lesser Instruments, who would give the lake for the Reckoner under it.".

  Person halm "Teodor Halm" at dig {
    Greets "Teodor Halm looks up from whatever he is holding with the face of a man interrupted in the middle of falling in love.".
    Role "Fellow of the Collegium of Lesser Instruments". Ancestry human. Calling mage. Level 3. Peaceable. Pronouns he. Manner cheerful.
    Buys weight_stone for 2 coin.
    Buys keeper_mask for 25 coin.
    Buys bell_teeth for 12 coin.
  }
  // The Collegium pays its Fellows badly and its finds well.
  Initially Set quantity(halm, gold) to 120.
  Rule halm_to_inn when hour(clock) == 20 and at(halm, dig) { Retract at(halm, dig). Assert at(halm, taproom). }
  Rule halm_to_dig when hour(clock) == 8 and at(halm, taproom) and not halmBelow(halm) and not digClosed(dig) { Retract at(halm, taproom). Assert at(halm, dig). }
  Rule halm_to_hall when hour(clock) == 8 and at(halm, taproom) and digClosed(dig) and not halmBelow(halm) { Retract at(halm, taproom). Assert at(halm, listening_hall). }
  Relation halmBelow(group).
  // The Collegium's glossary, which Halm keeps in his satchel and will sell.
  Thing satchel "Halm's satchel" at taproom {
    Holds.
    State strapped closed "A scholar's satchel hangs on a peg by the fire, strapped shut, bulging with books.".
  }
  Item glossary "the Collegium's glossary of the old script" is old_glossary in satchel.
  Relation soldGlossary(group).
  Action buy_glossary(actor: group, site: place) "Buy the Collegium's glossary of the old script from Halm, thirty coin" {
    Description "It lets whoever carries it make out the old marks.".
    Requires able(actor) and company(actor) and at(actor, site) and at(halm, site) and knows(actor, glossary_offered)
      and not soldGlossary(halm) and quantity(actor, gold) >= 30.
    Time 2 minutes.
    On success { Decrease quantity(actor, gold) by 30. Increase quantity(halm, gold) by 30. Assert soldGlossary(halm).
      Retract inside(glossary, satchel). Assert at(glossary, site). }
    Result "Halm takes the coins without counting them and puts the book in your hands as if it were a sleeping child. 'Read the marks under the keystone,' he says. 'Slowly. They were not written by anyone in a hurry.'".
  }
  Discovery glossary_offered "Halm will sell the Collegium's glossary of the old script for thirty coin.".

  Topic halm_hello with halm "Ask the scholar who he is" when true once {
    Says "'— and this, you see, isn't Aenean at all, look at the joins, the Aeneans couldn't cut a joint like that if you held a knife to their great-grandchildren, this is older, this is Mathematical, which means the temple was built on something, over something, the whole Ward is a lid — sorry. Sorry. I do this. Hello.' He wipes a hand on his coat and offers it, still muddy. 'Teodor Halm. Collegium of Lesser Instruments. Lesser because the greater instruments are all broken, ha. That's the Collegium joke. There's only the one.'".
  }
  Topic halm_collegium with halm "Ask Halm about the Collegium of Lesser Instruments" when true once {
    Says "'A society. Forty Fellows, a library in a damp house in Corran, and a letter that goes round twice a year. We collect working things.' He lights up. 'Not ruins. Anybody can collect ruins. Working things. A clock in a dead city that still strikes. A door that opens to a word. A keeper of clay in a dale in the north, the reports say, that walks a wall at night and cuts the saplings. Things that were made to go on, and did.' He spreads his hands. 'Almost all of them are Mathematical, or learned from someone who learned from the Mathematical. Almost none of them have been understood.'".
  }
  Topic halm_age with halm "Ask Halm what the Mathematical Age was" when true once {
    Says "'Nobody knows. That's the honest answer, and the Collegium has built a library on it.' He sits on a basket. 'Before the Aeneans, who were before everybody. People who made things to answer questions, by number, and made them so well they still run. We have their marks, which aren't letters. We have their works. We don't have one sentence of what they thought they were doing.' He picks up a weight-stone and turns it. 'Some of us think they were trying to finish something. Some of us think they were trying to stop something. I think they were asking. Everything they made is shaped like a question.'".
  }
  Topic halm_hum with halm "Ask Halm what is behind the wall at the bottom of the throat" when true once {
    Says "'Have you heard it? Put your ear to the Hall's inner wall. Go on.' He waits, bright-eyed. 'Something down there is running. In three thousand years nobody's built a machine that runs a year without a man to oil it. And that has been running since before there were men here at all. A reckoner, the Collegium would call it, if the Collegium had ever found one that worked: a counter.' Then, quietly, for once: 'I'd give the lake for it. I'm sorry. I would. I'd give the lake.'".
  }
  Topic halm_lake with halm "Ask Halm whether he means that about the lake" when true once {
    Says "He considers it seriously, which is the worst thing about him. 'The Mere is a great deal of water, and water comes again; it rains. The Reckoner is the only one in the world.' He sees your face. 'I know. I know how that sounds. There are people at the bottom of the Bowl, and I've eaten their fish, and Dov Vant would take my head off and he'd be right to.' He looks at the stone in his hands. 'I'm not saying it's right. I'm saying it's what I'd do. You should know that about me before you tell me anything useful.'".
  }
  Topic halm_keystone with halm "Ask Halm to read the letters under the keystone in the Listening Hall" when knows(actor, keystone_seen) and not knows(actor, keystone_read) once {
    Says "'You found the keystone. Of course you did; I've been sitting on it for a month.' He takes your arm and walks you through it as if at a lecture. 'The Aenean line says THE FIRST VOICE NAMES; THE VOICE AFTER SAYS HOW MUCH. A grammar, you see: two words to a sentence. And under it, older, in the marks, which I can read about as well as a child reads a gravestone: THE HIGH VOICE IS NOT SUNG BRIGHT. THAT IS THE END OF THE SONG.' He lets go of your arm. 'They wrote a grammar on the wall and a warning underneath it in a language they couldn't read themselves. They copied it because it was holy. That's the Aeneans all over. And your keepers, I'll bet, have it as never sing the high voice at all, which is a warning worn smooth by handling.'".
    On discuss { Assert knows(actor, keystone_read). }
  }
  Topic halm_glossary with halm "Ask Halm whether there is a book for the old marks" when true once {
    Says "'There is, and I have it, and I'll sell it you, because I know it by heart and I'm short.' He produces from his coat a fat book in wooden boards. 'The Collegium's glossary of the old script. Brothers of a dead order wrote the marks beside their own letters. It won't make a scholar of you. It'll make a reader, which is better than most scholars manage.' Thirty coin, he says, and looks embarrassed to.".
    On discuss { Assert knows(actor, glossary_offered). }
  }
  Topic halm_lintel with halm "Ask Halm to read the letters the Reckoner lit over the long stair" when knows(actor, question_heard) once {
    Says "Halm goes white, and then red, and then he sits down on the floor where he is. 'It answered you. In the First Remainder. It sang you its question.' He reads the lintel in a whisper, with his finger moving. 'IT COUNTS WHAT IS BOUND.' He reads it again. 'What is bound.' He tries it three other ways, and puts each down. 'Body. Breath. The binding.' He laughs, helplessly, and stops. 'Somebody left a census running under a pond.'".
    On discuss { Assert knows(actor, census_read). }
  }
  Discovery census_read "Halm reads the lintel the Reckoner lit: IT COUNTS WHAT IS BOUND. The Reckoner is a census of everything that is, was or will be bound, body and soul, by the prima materium.".
  Topic halm_door with halm "Ask Halm to read the words over the last door" when knows(actor, door_words) once {
    Says "Halm has you describe the two lines over the round door mark by mark, and draws them on the back of his hand as you talk, with his tongue between his teeth. 'WHAT IS COUNTED IS GIVEN,' he reads. 'WHAT IS GIVEN IS KEPT.' He touches the round door. 'Given to whom? Kept by whom?' He looks at you as if you might know. 'When it's finished, this opens, and the count goes through. Somebody is meant to receive it.' A long pause. 'I would very much like to know who.'".
    On discuss { Assert knows(actor, door_read). }
  }
  Discovery door_read "Halm reads the words over the last door: WHAT IS COUNTED IS GIVEN. WHAT IS GIVEN IS KEPT.".
  // Teodor Halm and The Long Man: the clay keepers of Merrowdale, if anyone brings him a piece of one.
  Event halm_mask near halm when keeps(halm, ?m) and itemKind(?m, keeper_mask) "Halm holds the grey face up to the light, turns it, strikes it gently with a fingernail, and listens to it ring. 'Hesk weirstone,' he says. 'From Merrowdale. From the keeper of the Long Man, or one of its sisters.' He is quite still. 'Do you know what this is? It's the same fired clay as the Dyers' arch. The same. The Hesk learned their craft from whoever learned it from the people who built this.' He looks at the floor of the Bowl as if he could see through it. 'One family of machines. All asking.'" then {
    Assert halmHasMask(halm). }
  Relation halmHasMask(group).
  Event halm_teeth near halm when keeps(halm, ?t) and itemKind(?t, bell_teeth) "Halm tips the bronze bell-teeth into his hands one by one and rings each. 'Teeth from a counting wheel,' he says. 'Look at the pitch: each one a voice. Somebody up north was building machines that count in voices too, and somebody else has been prising them out and selling them by the pound.' He sounds personally wounded." then {
    Assert halmHasTeeth(halm). }
  Relation halmHasTeeth(group).

  // What Halm does if he is left alone: he reads the keystone himself, goes down, and ends the song.
  Relation halmKnows(group). Relation halmStopped(group). Relation halmPromised(group).
  Rule halm_reads when watch(clock) >= 480 and not halmKnows(halm) { Assert halmKnows(halm). }
  Rule halm_told when knows(party, grammar_known) and not halmKnows(halm) and at(halm, ?p) and at(party, ?p) { Assert halmKnows(halm). }
  Query halmCanGo() means breached(dig) or state(deep_gate, lowered) or state(deep_gate, logged).
  Rule halm_goes when halmKnows(halm) and halmCanGo() and watch(clock) >= 666 and hour(clock) == 23 and not halmBelow(halm) and not halmStopped(halm) and not complete(reckoner) and not broken(reckoner) {
    Assert halmBelow(halm). Retract at(halm, dig). Retract at(halm, taproom). Retract at(halm, listening_hall). Assert at(halm, column_room). }
  Rule halm_ends when halmBelow(halm) and at(halm, column_room) and hour(clock) == 2 and not complete(reckoner) and not broken(reckoner) and not halmStopped(halm) and not at(party, column_room) and not doorHeld(reckoner) {
    Set count(reckoner) to 900. Assert endedBy(reckoner, halm). }
  Rule halm_foiled when halmBelow(halm) and at(halm, column_room) and hour(clock) == 2 and doorHeld(reckoner) and not halmStopped(halm) and not at(party, column_room)
    says "In the morning, word: the scholar from the Collegium came up the Ward steps at dawn, wet to the knees, white, and would not speak to anyone." {
    Assert halmStopped(halm). Assert halmFoiled(halm). Retract at(halm, column_room). Assert at(halm, taproom). Retract halmBelow(halm). }
  Relation halmFoiled(group).
  Observe halm_below at column_room when at(halm, column_room) and not complete(reckoner) "Teodor Halm is sitting cross-legged on the floor by the listening column with a lamp and a notebook and three weight-stones in a sack beside him. He looks up at you with perfect, guilty joy. 'You came,' he says. 'Good. Somebody should see it.'".
  Topic halm_dont with halm "Ask Halm not to sound the high voice" when at(halm, column_room) and not complete(reckoner) and not halmStopped(halm) once {
    Says "'Why not?' He genuinely wants to know. 'It's nearly done. It's been nearly done for three thousand years. If I sound the end it finishes now, with what it has, instead of drinking the rest of the Mere to get there.' He holds the striker. 'Isn't that kinder? Give me a reason. A real one. I'll listen; I'm not a monster. I'm just the only person in this city who wants to know the answer more than he wants anything else.'".
  }
  Topic halm_reason_ward with halm "Tell Halm that ending it now takes the Ward's last water in one breath" when at(halm, column_room) and not complete(reckoner) and not halmStopped(halm) and (knows(actor, door_read) or knows(actor, census_read)) once {
    Says "'One last breath,' he says. 'Yes. Six spans, by the look of the slot.' He looks at the striker a long time. 'And then nothing more, ever. Against six spans a night for a hundred nights.' He holds it out to you, handle first. 'Then you decide. You're the Assessor. That's the whole point of you, isn't it.' He sounds, for the first time, very tired. 'Somebody who isn't me.'".
    On discuss { Assert halmStopped(halm). }
  }
  Topic halm_reason_city with halm "Tell Halm the city has a right to choose this, at the Hearing, and he doesn't" when at(halm, column_room) and not complete(reckoner) and not halmStopped(halm) once {
    Says "Halm opens his mouth to argue and shuts it again. 'The city,' he says. 'Who've sung it orders for three thousand years without knowing. Yes, all right. That's a fair point. That's annoyingly fair.' He puts the striker back on its chain. 'Let them choose. But if they choose to break it, Assessor, I'll stand up at your Hearing and tell them they're vandals, and I'll be right.'".
    On discuss { Assert halmStopped(halm). Assert willTestify(halm). }
  }
  Topic halm_plan with halm "Ask Halm what he means to do about the high voice" when (halmKnows(halm) or knows(actor, grammar_known)) and not halmStopped(halm) and not complete(reckoner) and not broken(reckoner) and not halmBelow(halm) once {
    Says "Halm does not pretend not to understand. 'Sound it,' he says. 'The high voice and the bright. The end of the song. I worked it out from the keystone, the same as you did.' He is almost apologetic. 'It'll finish with what it has instead of drinking the rest of the Mere to get there. One breath, six spans, and then it's done and the lake can come back.' He looks at you. 'And I'll be there to hear the answer. I'm not going to pretend that isn't the reason.'".
  }
  Topic halm_promise with halm "Tell Halm the city has a right to choose this at the Hearing, and he doesn't" when (halmKnows(halm) or knows(actor, grammar_known)) and not halmStopped(halm) and not complete(reckoner) and not broken(reckoner) and not halmBelow(halm) once {
    Says "Halm opens his mouth to argue and shuts it again. 'The city,' he says. 'Who've sung it orders for three thousand years without knowing. Yes, all right. That's a fair point. That's annoyingly fair.' He plants his muddy hands on his knees. 'I'll wait for your Hearing. I give you my word, which the Collegium will tell you is good for most things that aren't instruments. But if they choose to break it, I'll stand up and tell them they're vandals, and I'll be right.'".
    On discuss { Assert halmStopped(halm). Assert willTestify(halm). }
  }
  Rule halm_returns when halmStopped(halm) and at(halm, column_room) and not at(party, column_room) { Retract at(halm, column_room). Assert at(halm, taproom). Retract halmBelow(halm). }
  Rule halm_did_it when endedBy(reckoner, halm) and complete(reckoner) and not toldHalm(party)
    says "In the morning, word: the scholar from the Collegium was seen coming up the Ward steps at dawn, wet to the chest, laughing and weeping at once." {
    Assert toldHalm(party). Retract at(halm, column_room). Assert at(halm, taproom). Retract halmBelow(halm). }
  Relation toldHalm(group).
  Topic halm_after_end with halm "Ask Halm what he heard" when complete(reckoner) and not broken(reckoner) once {
    Says "'Everything,' says Halm. 'Everything and a number.' He has not slept and does not look as if he will. 'The whole hymn came up out of the water at once, and then one long last tone that I think was the count, and then the door opened.' He shakes his head. 'I wrote down the tone. It's a number. I'll be fifty years working out what it means and I'll die before I do, and it'll be the best fifty years anybody in the Collegium ever had.' Then: 'Did it cost much? The water?' He listens to the answer. He does not argue with it.".
  }
  Topic halm_held with halm "Tell Halm the Fourth Remainder keeps the last door shut, and is sung again" when fourthRestored(bowl) or doorHeld(reckoner) once {
    Says "Halm stares at you. 'Keeps it shut.' He sits down, slowly, on whatever is nearest. 'Three thousand years of choirs singing a lock.' He laughs, and stops. 'And you've given it back to them.' For once he has nothing clever to say, and picks the dry mud off his cuff instead. 'Somebody built the count, and somebody else built the lock on its door.' He looks up. 'Which of them was right, Assessor? No. Don't. You don't know either.'".
  }
  Topic halm_after_broken with halm "Say something to Halm about the Reckoner" when broken(reckoner) once {
    Says "Halm does not look at you. 'I heard it stop,' he says. 'In the Hall. I had my ear to the wall and it stopped, like a heart.' He is packing his notebooks into a case, very neatly. 'I'll write to the Collegium tonight. I'll tell them the last working instrument of the Mathematical Age in the north of Imbar was broken by an Assessor of the Office of Measures, to save a pond.' He fastens the case. 'I'll tell them it was a very good pond. I'll be fair. I'm always fair. It's the worst thing about me.'".
  }

  // Halm writes letters as other men breathe. One to the Collegium's friends in the south, for whoever has shown him
  // what the Reckoner says, is as much a gift as he can make.
  Place beyond_map "beyond the map" is wilderness within bowl at 9, 9.
  Place nowhere "nowhere" is room within beyond_map at 0, 0.
  Item halm_letter "Halm's letter of introduction" is collegium_letter at nowhere owned by halm.
  Topic halm_letter_ask with halm "Ask Halm for a letter of introduction to the Collegium's friends" when knows(actor, census_read) and not letterWritten(halm) once {
    Says "'A letter!' says Halm, delighted, and is already looking for ink. 'To everyone. To the Fellows at Corran, to the Collegium of Measures at Sennet, to the Rector, to anyone who can read.' He writes it in four minutes on the back of a tally, folds it with the seal of the Collegium, and gives it to you with both hands. 'It will open fewer doors than I believe,' he says, with real candour. 'But it will open some. They like to be written to by someone who has heard the Reckoner.'".
    On discuss { Give halm_letter to actor. Assert letterWritten(halm). }
  }
  Relation letterWritten(group).
}

data/adventures/low-water/hearing.kyr:
Module lowwater "Low Water" {
  Description "The Hearing before the Council of Ammerlin, at which the Assessor's Finding is read: exhibits, witnesses, a cause named and a remedy asked; and the city after.".

  Person council "the Council of Ammerlin" at moot_hall {
    Role "nine members, one for each lock, in grey". Ancestry human. Numbers 9. Peaceable.
    Seen when hearingOpen(ammerlin) or hearingDone(ammerlin) and watch(clock) < hearingAt(bowl) + 36.
  }
  Relation hearingOpen(place). Relation hearingDone(place). Relation begun(group). Relation present(group).
  Measure credence(group). Measure rebuttal(group).

  // Noon on the day: the Council sits, and those who have said they will speak come.
  Rule hearing_opens when watch(clock) >= hearingAt(bowl) and not hearingOpen(ammerlin) and not hearingDone(ammerlin)
    says "From the Sounding the noon bell, and from the Office the long single note of the Office horn: the Hearing." {
    Assert hearingOpen(ammerlin). Retract at(fenn, registrar_room). Assert at(fenn, moot_hall). Retract at(quill, quill_room). Assert at(quill, moot_hall).
    Set hearingClosesAt(bowl) to watch(clock) + 12. }
  Measure hearingClosesAt(place).
  Rule orr_attends when hearingOpen(ammerlin) and willTestify(orr) and not present(orr) { Retract at(orr, cantor_room). Retract at(orr, choir_loft). Assert at(orr, moot_hall). Assert present(orr). }
  Rule halm_attends when hearingOpen(ammerlin) and willTestify(halm) and not present(halm) and not halmBelow(halm) { Retract at(halm, dig). Retract at(halm, taproom). Retract at(halm, listening_hall). Assert at(halm, moot_hall). Assert present(halm). }
  Rule dov_attends when hearingOpen(ammerlin) and not dovHeld(dov) and not present(dov) { Retract at(dov, dig). Retract at(dov, dov_yard). Assert at(dov, moot_hall). Assert present(dov). }
  Rule piet_attends when hearingOpen(ammerlin) and willTestify(piet) and not present(piet) { Retract at(piet, piet_room). Retract at(piet, ninth_lock). Assert at(piet, moot_hall). Assert present(piet). }
  Rule mag_attends when hearingOpen(ammerlin) and grievance(mag, party) and not present(mag) { Retract at(mag, vat_yard). Assert at(mag, moot_hall). Assert present(mag). }
  Rule sella_attends when hearingOpen(ammerlin) and promised(party, sella) and not present(sella) { Retract at(sella, fulling_mills). Assert at(sella, moot_hall). Assert present(sella). }
  Observe moot_hearing at moot_hall when hearingOpen(ammerlin) "The Moot Hall is full. The nine of the Council sit at the long table under the Office's seal, in grey; Registrar Fenn stands at its end. The benches are packed to the walls: millwrights in green, dyers with blue hands, Cantors in black, and at the back, standing, the Ward. Harrow Quill has a front bench to himself and is smiling at everyone.".
  Topic piet_hearing with piet "Ask Piet Harl to speak at the Hearing" when knows(actor, letters_read) and not willTestify(piet) once {
    Says "Piet goes the colour of the lock wall. 'In the Moot Hall? In front of the Council?' He looks at his book. 'I'd only be able to say what's in the book.' That is the point; you say so. He nods slowly. 'I can do that. I've had a lot of practice.'".
    On discuss { Assert willTestify(piet). }
  }

  // The Finding, given item by item.
  Action begin_finding(actor: group, site: place) "Rise and give your Finding to the Council" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, moot_hall) and hearingOpen(ammerlin) and not begun(actor).
    Time 1.
    On success { Assert begun(actor). }
    Result "You rise. The hall goes quiet in the way of a hall that has been waiting to go quiet. Registrar Fenn says, 'The Independent Assessor, for the Office of Measures, on the matter of the Mere,' and sits.".
  }
  Relation laid(entity).
  Kind exhibit. Entity ex_hands: exhibit "the mill hands' wages". Entity ex_channel: exhibit "the Channel's draw". Entity ex_report: exhibit "the engineers' report".
  Entity ex_tally: exhibit "the tally". Entity ex_register: exhibit "the register". Entity ex_letters: exhibit "the keeper's letters and book".
  Entity ex_hymn: exhibit "the Short Hymn". Entity ex_engine: exhibit "the Reckoner". Entity ex_grammar: exhibit "the Reckoner's speech". Entity ex_census: exhibit "the census".
  Entity ex_diggers: exhibit "the drowned diggers".
  Query giving(a: group) means begun(a) and hearingOpen(ammerlin) and not named(a).
  Relation named(group).
  Action speak_hands(actor: group, site: place) "Say first that the Guild's four hundred hands have not been paid since Lammas" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and promised(actor, sella) and not laid(ex_hands).
    Time 1.
    On success { Assert laid(ex_hands). Increase credence(council) by 1. }
    Result "You say it first, as you promised: four hundred people, Lammas, the charter. It is not what the hall expected. At the back Sella Quenby folds her arms and nods once. On the front bench Harrow Quill stops smiling for the first time.".
  }
  Action lay_channel(actor: group, site: place) "Lay before the Council the Channel's draw: twenty-two ells a day" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and knows(actor, channel_measured) and not laid(ex_channel).
    Time 1.
    On success { Assert laid(ex_channel). Increase credence(council) by 1. }
    Result "Twenty-two ells, gauged at the head, the middle and the bend, twice. The Councillor for the First Lock writes it down. Quill nods along graciously, as if you were reading his own speech.".
  }
  Action lay_report(actor: group, site: place) "Lay before the Council the Corran engineers' report, countersigned by Quill" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and carries(actor, report_copy) and not laid(ex_report).
    Time 1.
    On success { Assert laid(ex_report). Increase credence(council) by 2. }
    Result "You read the last page aloud: THE CHANNEL AS CUT CANNOT ACCOUNT FOR ONE PART IN THREE OF THE FALL. Countersigned, H. Quill, Master. The paper goes along the Council's table hand to hand. Quill does not look at it. He looks, for a long moment, at the back of the hall, where Sella Quenby is standing, and then he looks at the ceiling.".
  }
  Action lay_report_original(actor: group, site: place) "Lay before the Council the Corran engineers' report, countersigned by Quill" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and carries(actor, report) and not carries(actor, report_copy) and not laid(ex_report).
    Time 1.
    On success { Assert laid(ex_report). Increase credence(council) by 2. }
    Result "You read the last page aloud: THE CHANNEL AS CUT CANNOT ACCOUNT FOR ONE PART IN THREE OF THE FALL. Countersigned, H. Quill, Master. The paper goes along the Council's table hand to hand. Quill does not look at it. He looks, for a long moment, at the back of the hall, where Sella Quenby is standing, and then he looks at the ceiling.".
  }
  Action lay_tally(actor: group, site: place) "Lay before the Council Isaura Vant's tally: forty ells a day that arrive nowhere" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and knows(actor, discrepancy) and isauraSigns(isaura) and not laid(ex_tally).
    Time 1.
    On success { Assert laid(ex_tally). Increase credence(council) by 2. }
    Result "Isaura stands up beside you with her thin book and reads it out: Rim Gauge, Channel, every right on every terrace, evaporation. Forty ells unaccounted. The Councillor for the Fourth Lock says, 'The Office's own ledger shows no such figure,' and Isaura says, 'No, sir. That's why I kept a tally.' Registrar Fenn closes her eyes, briefly, and then opens them and nods.".
  }
  Action lay_register(actor: group, site: place) "Lay before the Council the register of the Mere gauge: steady two hundred years, falling since three autumns ago" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and knows(actor, fall_dated) and not laid(ex_register).
    Time 1.
    On success { Assert laid(ex_register). Increase credence(council) by 1. }
    Result "Two hundred years of the Office's own columns, and then three autumns ago, the turn. Somebody on the Cantors' bench says, quite loudly, 'That's the Short Hymn,' and is hushed.".
  }
  Action lay_letters(actor: group, site: place) "Lay before the Council the keeper's book and his letters to the Sounding" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and (knows(actor, letters_read) or knows(actor, lockbook_read)) and not laid(ex_letters).
    Time 1.
    On success { Assert laid(ex_letters). Increase credence(council) by 1. }
    Result "Deep up at the Sixth. Seventh not sung. Deep did not come down. You read three nights of it and then stop, because the hall has understood, and because reading a thousand of them would be cruel.".
  }
  Rule piet_speaks when laid(ex_letters) and present(piet) and at(piet, moot_hall) and not spoke(piet)
    says "Piet Harl stands up at the back without being called. 'I wrote it every night,' he says, too loud, and then quieter: 'I wrote it every night. I sent twice.' He sits down again, red to the ears. Nobody laughs." {
    Assert spoke(piet). Increase credence(council) by 1. }
  Relation spoke(group).
  Action lay_hymn(actor: group, site: place) "Lay before the Council what the Seventh Remainder did, and what its leaving out has done" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and knows(actor, hymn_cause) and not laid(ex_hymn).
    Time 1.
    On success { Assert laid(ex_hymn). Increase credence(council) by 1. }
    Result "You tell them about the Lock-Rhyme the children skip to, and what the Seventh Remainder told the Deep Gate, and the autumn it stopped. On the Cantors' bench Precentor Penhale is on his feet with a face like the end of the world, and Cantor Orr's hand on his sleeve is pulling him down.".
  }
  Rule orr_speaks when laid(ex_hymn) and present(orr) and at(orr, moot_hall) and not spoke(orr)
    says "Cantor Orr stands. She does not ask leave. 'I cut it,' she says, to the Council and the hall. 'I cut three thousand years out of the Hymn because the children were bored, and I was proud of it, and I was right that they were bored, and I was wrong about everything else.' She looks at the back of the hall, at the Ward. 'I am sorry. We sing it again every night now. I'll sing it till I die.' She sits. The hall is so quiet you can hear the fountain in the square." {
    Assert spoke(orr). Increase credence(council) by 2. }
  Action lay_engine(actor: group, site: place) "Lay before the Council what lies under the Mere: a machine that counts by drinking" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and knows(actor, engine_seen) and not laid(ex_engine).
    Time 1.
    On success { Assert laid(ex_engine). Increase credence(council) by 1. Increase rebuttal(council) by 1. }
    Result "You tell them about the Undercroft: the culvert, the Equals, the nine wheels, the column. It is a great deal for a hall to hear. The Councillor for the Ninth Lock, an old woman, says, 'Under the Ward? All this time?' and someone in the Ward says, 'Under us, aye,' and there is laughter, of the wrong kind.".
  }
  Rule halm_speaks when laid(ex_engine) and present(halm) and at(halm, moot_hall) and not spoke(halm)
    says "Teodor Halm stands up uninvited and tells the Council, in four rapid sentences full of words nobody in the hall knows, that the Assessor is quite right, that the Reckoner is the last working instrument of the Mathematical Age in the north of Imbar, and that whoever breaks it will be remembered by the Collegium exactly as long as the Collegium remembers anything. He sits. The Council looks at him as people look at weather." {
    Assert spoke(halm). Increase credence(council) by 1. }
  Action lay_grammar(actor: group, site: place) "Lay before the Council how the Remainders speak to the Reckoner: the first voice names, the second says how much" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and knows(actor, grammar_known) and laid(ex_engine) and not laid(ex_grammar).
    Time 1.
    On success { Assert laid(ex_grammar). Increase credence(council) by 1. Decrease rebuttal(council) by 1. }
    Result "The arch in the Dyers' Basin, the keystone in the Listening Hall, the four voices of the Sounding's hymnal. The Seventh is deep and deep: the mouth, least. A cupful. You watch it go round the hall and come back as a murmur, and then as Merrin Reed on the Cantors' bench saying, quite clearly, 'Oh.'".
  }
  Action lay_census(actor: group, site: place) "Lay before the Council what the Reckoner counts, as Halm reads it: what is bound" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and knows(actor, census_read) and laid(ex_engine) and not laid(ex_census).
    Time 1.
    On success { Assert laid(ex_census). Increase credence(council) by 1. }
    Result "IT COUNTS WHAT IS BOUND. Some of the hall hears souls and some hears nonsense and Precentor Penhale hears vindication and says so, and is hushed again. The Councillor for the Third Lock asks how many it has counted. You tell her. She writes the figure down, and then looks at it as if it might bite.".
  }
  Action lay_diggers(actor: group, site: place) "Lay before the Council the names of the three diggers who drowned" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and drowned(diggers) and not laid(ex_diggers).
    Time 1.
    On success { Assert laid(ex_diggers). }
    Result "Hob Kettle. Annet Kettle. Jory Pale. At the back the Ward stands up, all of it, without a word, and stays standing until you have finished.".
  }
  Rule mag_speaks when begun(party) and present(mag) and at(mag, moot_hall) and not spoke(mag)
    says "Before you have gone far Mag Torrin is on her feet with her blue hands on the bench in front of her. 'This Assessor,' she says in a good clear voice, 'drowned my vats for the sake of a stone arch, and ruined five yards' season, and never said sorry.' She sits. It costs you something with the Council; you can see it cost." {
    Assert spoke(mag). Decrease credence(council) by 1. }
  Rule dov_speaks when laid(ex_tally) and present(dov) and at(dov, moot_hall) and not spoke(dov) and not quillDeal(quill)
    says "From the back, Dov Vant: 'That's my sister,' loud enough for the whole Bowl. 'Those are her figures. You can believe them.' Isaura does not turn round. Her ears go red." {
    Assert spoke(dov). Increase credence(council) by 1. }

  // Quill's answer, when a cause other than his Channel is named without the report to stop him.
  Relation answered(group).
  Rule quill_answers when named(party) and not causeAccount(party) and not laid(ex_report) and not causeGuild(party) and not quillDeal(quill) and not answered(quill)
    says "Harrow Quill rises, gracious, and asks the Council's leave, and has it. 'A machine under the Ward,' he says. 'Bronze men. A hymn that works sluices.' He lets it hang. 'I don't doubt the Assessor saw something down there. I only observe that my Channel is in the Office's register and their machine is in a story.' It is very well done. Half the hall laughs." {
    Assert answered(quill). Decrease credence(council) by 2. }
  Rule quill_concedes when named(party) and not causeAccount(party) and laid(ex_report) and not answered(quill) and not quillDeal(quill)
    says "Quill rises and, for once, does not wait for leave. 'The Assessor has my engineers' report,' he says. 'I should like it known I'd have published it myself in the end.' He considers. 'Probably. In the end.' He sits down to a laugh, which he has earned." {
    Assert answered(quill). }
  Rule quill_supports when named(party) and not causeAccount(party) and quillDeal(quill) and not answered(quill)
    says "Quill rises to support the Assessor's Finding at once, in a short speech of great warmth, and sits down again, and the hall understands that some arrangement has been made, and the Ward understands what it was." {
    Assert answered(quill). Increase credence(council) by 1. }

  // Isaura will not let a lie with a number in it pass in front of her own figures.
  Relation dissented(group).
  Rule isaura_dissents when causeGuild(party) and laid(ex_tally) and not dissented(isaura)
    says "Before the Councillor can speak Isaura Vant is on her feet beside you. 'With respect,' she says, to the Council, to the Registrar, to you, 'the tally I read out says the Channel takes twenty-two ells a day and forty more go somewhere that is not the Channel. The Finding names the Channel. The figures don't.' She sits down. Her hands are shaking and her voice was not." {
    Assert dissented(isaura). }
  // The cause.
  Relation causeGuild(group). Relation causeHymn(group). Relation causeEngine(group).
  Action name_guild(actor: group, site: place) "Name the cause: the Guild's Fulling Channel" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor).
    Time 1.
    On success { Assert named(actor). Assert causeGuild(actor). }
    Result "You name the Channel. The millwrights' benches roar. The Registrar writes it down without looking up.".
  }
  Action name_hymn(actor: group, site: place) "Name the cause: the Short Hymn, which left out the Seventh Remainder" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and laid(ex_hymn).
    Time 1.
    On success { Assert named(actor). Assert causeHymn(actor). }
    Result "You name the Short Hymn. The Cantors' bench goes still, and then everyone on it looks at Cantor Orr, and she looks back at them.".
  }
  Action name_engine(actor: group, site: place) "Name the cause: the Reckoner under the Mere, drinking it through the Deep Gate, and the Hymn that stopped telling it its measure" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and giving(actor) and laid(ex_engine) and laid(ex_hymn).
    Time 1.
    On success { Assert named(actor). Assert causeEngine(actor). Assert causeHymn(actor). }
    Result "You name them both, and the gaps between them: a machine that does what it is told, a hymn that told it, a reform that stopped the telling, and nobody in the city who knew the hymn was an order. Every one of them doing their job. It is not a culprit. The hall does not know what to do with it, and you watch it decide to listen anyway.".
  }

  // The remedy.
  Relation remedied(group). Relation askSeventh(group). Relation askBreak(group). Relation askFeed(group). Relation askAccord(group). Relation askClose(group).
  Action ask_close(actor: group, site: place) "Ask the Council to close the Fulling Channel and send the Ninefold back to the Mere" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and named(actor) and not remedied(actor) and hearingOpen(ammerlin).
    Time 1.
    On success { Assert remedied(actor). Assert askClose(actor). }
    Result "You ask for the Channel closed. The Councillors confer, heads together.".
  }
  Action ask_seventh(actor: group, site: place) "Ask the Council to order the Seventh Remainder sung every night, and the Reckoner kept at its cupful" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and named(actor) and causeHymn(actor) and not remedied(actor) and hearingOpen(ammerlin).
    Time 1.
    On success { Assert remedied(actor). Assert askSeventh(actor). }
    Result "The Seventh every night, as it was for three thousand years: the Reckoner at its cupful, the Mere left to come back, and the count left to go on as slowly as it always did. Nobody now living will hear it finish. You say so.".
  }
  Action ask_break(actor: group, site: place) "Ask the Council to order the Reckoner's governor broken, and the Mere kept for the Bowl" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and named(actor) and causeEngine(actor) and knows(actor, governor_known) and not remedied(actor) and hearingOpen(ammerlin).
    Time 1.
    On success { Assert remedied(actor). Assert askBreak(actor). }
    Result "Break the governor; stop the Reckoner for good; let every ell of the Ninefold come to the Mere from now on. Halm's face, if he is in the hall, is something you will remember.".
  }
  Action ask_feed(actor: group, site: place) "Ask the Council to send the Channel down the Grey Way to the Reckoner until its count is done, and the Mere spared" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and named(actor) and causeEngine(actor) and knows(actor, feeder_known) and not remedied(actor) and hearingOpen(ammerlin).
    Time 1.
    On success { Assert remedied(actor). Assert askFeed(actor). }
    Result "The Grey Way, as the oldest map shows it: the Channel's water past the Mere, straight to the Reckoner, for as long as it needs to finish. The mills idle. The Mere kept. And at the end, whatever the end is.".
  }
  Action ask_accord(actor: group, site: place) "Ask the Council to enter the Reckoner in the Office's ledger as a holder of a water-right, its ration sung each night by the Sounding and measured by the Office" {
    Description "Not a culprit, and not a ruin: a citizen of the Bowl, with a right like any other, kept by the two institutions that between them were keeping it all along without knowing.".
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and named(actor) and causeEngine(actor) and laid(ex_grammar) and laid(ex_tally) and not remedied(actor) and hearingOpen(ammerlin).
    Time 1.
    On success { Assert remedied(actor). Assert askAccord(actor). }
    Result "You ask them to write it into the ledger: the Reckoner, a holder of a right of one cupful a night, by the Seventh Remainder; the Sounding to sing the ration, the Office to measure it, and both to answer to the Council for it. A right like a dyer's or a miller's. Isaura, beside you, has stopped breathing. Registrar Fenn has put down her pen.".
  }

  // The Council decides, on what it has been shown.
  Relation verdictGuild(place). Relation verdictSeventh(place). Relation verdictBreak(place). Relation verdictFeed(place). Relation verdictAccord(place).
  Relation charterRenewed(place). Relation charterLost(place). Relation findingRejected(place). Relation registrarsFinding(place).
  Action rest_finding(actor: group, site: place) "Rest your Finding, and let the Council decide" {
    Requires able(actor) and at(actor, site) and at(actor, moot_hall) and remedied(actor) and hearingOpen(ammerlin).
    Time 3.
    On success { Retract hearingOpen(ammerlin). Assert hearingDone(ammerlin). }
    Result "You sit down. The Council goes out to the Registrar's room. The hall waits, talking low, for half an hour that is very long; and then the nine come back in, and the Councillor for the First Lock stands.".
  }
  Rule council_closes when askClose(party) and hearingDone(ammerlin) and not decided(council)
    says "'The Council accepts the Finding,' says the Councillor for the First Lock. 'The Fulling Channel is to be closed at the head and the Ninefold sent back to the Mere. The Guild's charter is not renewed.' At the back of the hall a mill hand shouts, and then a great many do." {
    Assert decided(council). Assert verdictGuild(ammerlin). Assert charterLost(ammerlin). Assert state(channel_gate, to_mere). }
  Rule council_seventh when askSeventh(party) and hearingDone(ammerlin) and credence(council) >= 4 and not decided(council)
    says "'The Council accepts the Finding,' says the Councillor for the First Lock. 'The Sounding is to sing the Seventh Remainder every night, and the keeper of the Ninth Lock to record the Deep Gate's coming down, and report to the Office if it does not. The Guild is not found the cause, and its charter is renewed.' She sits. It is not applause, quite. It is the sound of a hall letting go of something it had held a long time." {
    Assert decided(council). Assert verdictSeventh(ammerlin). Assert charterRenewed(ammerlin). Assert seventhRestored(bowl). Assert restoredForGood(bowl). }
  Rule council_break when askBreak(party) and hearingDone(ammerlin) and credence(council) >= 5 and not decided(council)
    says "'The Council accepts the Finding,' says the Councillor for the First Lock, 'and orders the Reckoner stopped. The Assessor is to see to it, with the Office's warrant.' From somewhere in the hall a man laughs, high and unhappy: Halm, or someone like him. 'The Guild's charter is renewed.'" {
    Assert decided(council). Assert verdictBreak(ammerlin). Assert charterRenewed(ammerlin). Assert seventhRestored(bowl). }
  Rule council_feed when askFeed(party) and hearingDone(ammerlin) and credence(council) >= 5 and not decided(council)
    says "'The Council accepts the Finding,' says the Councillor for the First Lock. 'The Grey Way is to be opened at the head, and the Guild's Channel sent down it until the Reckoner's count is done, and the Guild compensated from the Office's funds for its idle days. The Guild's charter is renewed.' Quill, on the front bench, bows to nobody in particular." {
    Assert decided(council). Assert verdictFeed(ammerlin). Assert charterRenewed(ammerlin). Assert state(channel_gate, to_deep). Assert state(guild_chain, unlocked). }
  Rule council_accord when askAccord(party) and hearingDone(ammerlin) and credence(council) >= 8 and not decided(council)
    says "The Councillor for the First Lock does not stand at once. When she does, she reads from a paper in her own hand, slowly. 'The Council accepts the Finding. There is entered in the ledger of the Office of Measures a new right: to the Reckoner under the Mere, one cupful a night, by the Seventh Remainder, from this day. The Sounding shall sing it. The Office shall measure it. Both shall answer for it to this Council.' She puts the paper down. 'The Guild's charter is renewed. The Office will examine the Ward's titles.' For a moment nobody in the hall knows what to do, and then Cantor Orr, of all people, begins to laugh, and then everybody is talking at once." {
    Assert decided(council). Assert verdictAccord(ammerlin). Assert charterRenewed(ammerlin). Assert seventhRestored(bowl). Assert restoredForGood(bowl). Assert titlesFrozen(ammerlin). }
  Rule council_rejects when hearingDone(ammerlin) and remedied(party) and not decided(council) and not askClose(party)
    says "'The Council thanks the Assessor,' says the Councillor for the First Lock, in the voice of someone closing a door politely, 'and does not find the Finding proven. It adopts instead the Registrar's provisional finding: the Fulling Channel is the cause of the fall, and is to be closed. The Guild's charter is not renewed.' Registrar Fenn looks at you across the table, and you cannot tell what she is thinking." {
    Assert decided(council). Assert findingRejected(ammerlin). Assert verdictGuild(ammerlin). Assert charterLost(ammerlin). Assert state(channel_gate, to_mere). }
  Relation decided(group).
  // An Assessor who does not come: the Registrar gives her own finding.
  Rule hearing_lapses when hearingOpen(ammerlin) and not begun(party) and watch(clock) >= hearingClosesAt(bowl)
    says "Word comes, wherever you are: the Hearing sat and the Assessor did not come, and Registrar Fenn gave the Office's own finding in their place. The Guild's Fulling Channel, the cause; the Channel to be closed; the charter not renewed. The mills are out on the Rim, and the Ward is drinking to the Office in the Full Measure." {
    Retract hearingOpen(ammerlin). Assert hearingDone(ammerlin). Assert decided(council). Assert registrarsFinding(ammerlin). Assert verdictGuild(ammerlin). Assert charterLost(ammerlin). Assert state(channel_gate, to_mere). }

  // What the Council's verdict leaves the Bowl.
  Rule hands_paid when charterRenewed(ammerlin) and not paidHands(sella) says "On the Rim, by evening, the Guild's mill hands are paid: Lammas to now, in Guild silver, the creditors having been told about the charter." { Assert paidHands(sella). }
  Relation paidHands(group).
  Observe mills_out at fulling_mills when charterLost(ammerlin) "The mills are dead, the Channel dry, and the counting-house shuttered. Sella Quenby is sitting on the bench by the door, alone, as if she were still waiting to be paid.".
  Rule ward_kept when titlesFrozen(ammerlin) and decided(council) and not quillDeal(quill) and not wardKept(ammerlin) { Assert wardKept(ammerlin). }
  Relation wardKept(place).
  Rule plots_sealed when quillDeal(quill) and decided(council) and not plotsSealed(ammerlin) says "The Office seals the Ward plots to the Guild: the dig, the Listening Hall's ground, half Tench Row. In the Ward nobody says anything about it where the Office can hear." { Assert plotsSealed(ammerlin). }
  Relation plotsSealed(place).
  Observe accord_square at measures_square when verdictAccord(ammerlin) "Somebody has chalked on the Office's wall, under the words over the door, in a child's capitals: AND SUNG.".
  Observe accord_office at office_hall when verdictAccord(ammerlin) "On the counter, open, the newest ledger of the Office of Measures, and on its newest page, in Isaura Vant's hand, a right that has never been written before: THE RECKONER UNDER THE MERE. ONE CUPFUL NIGHTLY. BY THE SEVENTH REMAINDER.".
  Objective give_finding when knows(party, commission) and not hearingDone(ammerlin) "Find why the Mere is falling, and give your Finding to the Council at the Hearing in the Moot Hall.".
  Objective break_ordered when verdictBreak(ammerlin) and not broken(reckoner) "The Council has ordered the Reckoner's governor broken, and left it to you.".
}

data/adventures/low-water/interval.kyr:
Module lowwater "Low Water" {
  Description "The Interval: the still water past the last door and under the Mere, and Ammerlin in the water, the city the Auditor has built out of three thousand years of counted water, left for right.".

  Place interval_plane "the Interval" is plane.
  Place interval "the still water" is region within interval_plane.
  Place interval_wild "the still water" is wilderness within interval at 0, 0.
  Place still_water "the still water" is room within interval_wild at 0, 0 outdoors.
  Place far_bowl "the Bowl in the water" is room within interval_wild at 1, 0 outdoors.
  Place mirror_city "Ammerlin in the water" is settlement within interval at 1, 0.
  Place mirror_rim "the Rim in the water" is room within mirror_city at 0, 0 outdoors.
  Place mirror_square "the square in the water" is room within mirror_city at 0, 1 outdoors.
  Place mirror_sounding "the Sounding in the water" is room within mirror_city at 1, 1.
  Place mirror_office "the Office in the water" is room within mirror_city at 2, 1.
  Place mirror_ward "the Ward in the water" is room within mirror_city at 0, 2 outdoors.
  Place stair_foot "the foot of the stair that goes up" is room within mirror_city at 1, 2 outdoors.

  // Two ways in: the round door when the count is whole and the door unheld; and the Mere itself, at night, for a
  // company carrying the Lector's bell, following the Reflected down.
  Passage last_door "the round door" is doorway between last_door_room and still_water
    opening when complete(reckoner) and not doorHeld(reckoner) "The round door is shut, and has no handle, and no seam you can get a blade into.".
  Passage after_reflected "out onto the Mere after the Reflected" is path between mere_edge and still_water one way taking 20 minutes
    opening when dark() and carries(party, ear_bell) and approach(bowl) >= 1 and not broken(reckoner) "The Mere is only water. Nothing on it will hold you up, unless you carry something it knows.".
  Passage up_through "up through the water toward the light" is path between still_water and ward_landing one way taking 20 minutes.
  Passage still_way "the way across the still water" is path between still_water and far_bowl taking 20 minutes.
  Passage into_mirror "the road over the Rim in the water" is path between far_bowl and mirror_rim taking 5 minutes.
  Passage mirror_stair "the Stair in the water" is steps between mirror_rim and mirror_square taking 5 minutes.
  Passage mirror_dome "the Sounding's door, in the water" is doorway between mirror_square and mirror_sounding.
  Passage mirror_counter "the Office's door, in the water" is doorway between mirror_square and mirror_office.
  Passage mirror_down "the Ward steps, in the water" is steps between mirror_square and mirror_ward taking 5 minutes.
  Passage mirror_to_stair "the mud in the water, toward the stair" is path between mirror_ward and stair_foot taking 5 minutes.

  Observe still_scene at still_water when true "Water, still, to the end of seeing, under no sky. It is lit from nowhere, evenly, like the inside of a pearl. It holds you up; you walk on it as on glass, and under your feet, a hand down, it goes on being water for ever. There is no sound at all.".
  Observe still_door at still_water when complete(reckoner) and not doorHeld(reckoner) "Behind you the round door stands in nothing, its edge as thin as paper.".
  Observe still_above at still_water when true "Far overhead, if it is overhead, there is a pale disc like a coin seen from under water: the Mere, from below.".
  Discovery water_kept "The counted water of three thousand years lies in the Interval, still, and it has been used: somebody, or something, has built out of it, far off across the still water, a likeness of the Bowl of Ammerlin.".
  Rule still_far at still_water when at(party, still_water) and not knows(party, water_kept) says "Far off across the water, a long way, something stands up out of it: terraces, a pale ring of them, going down." teaches water_kept { }

  Observe far_scene at far_bowl when true "It is the Bowl. It is Ammerlin, made of water that has been made to stand up: the Rim, the four terraces, the Stair, the Sounding's dome, every roof, as clear as ice and as still. It has been copied the way a child copies a picture it has only ever seen reflected: everything is there, and everything is the wrong way round, left for right. At the bottom the Mere is full to the fourth step of the Ward landing, and every boat in the Ward is afloat on it.".

  Kind still_cup "a cup of the still water" is treasure worth 0 weighing 1 described "A tin cup of water from the Interval. It does not spill when you tip it. It does not warm in your hand. When you hold it to your ear you hear, very faint, the Hymn.".
  Item still_cupful "a cup of the still water" is still_cup at far_bowl.
  Event cup_orr near orr when keeps(orr, ?c) and itemKind(?c, still_cup) "Cantor Orr holds the cup to her ear for a long time. Then she sets it down on the clavichord, very carefully, where she can see it while she plays. 'It's in tune,' she says. 'Of course it is.'" then { Assert orrHasCup(orr). }
  Relation orrHasCup(group).
  Relation stayed(group).
  Action stay_interval(actor: group, site: place) "Stay in the Bowl in the water" {
    Description "Do not go back through the round door.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, far_bowl).
    Time 6.
    On success { Assert stayed(actor). }
    Result "You sit down on the step of the water-Ward, where the boats are afloat, and wait to see who comes.".
  }

  Observe mrim_scene at mirror_rim when true "The Rim in the water. The north road comes over the lip and stops; the Ninefold comes in at the Gauge, clear as glass, and goes down the Stair in falls that do not fall: they stand, each one a frozen white rope. Everything is silent except, very far down, the hymn, and it is coming up the Bowl backwards: the Amen first.".
  Observe msquare_scene at mirror_square when true "The square in the water. The Office is on the wrong side and the Sounding on the other. In the middle the fountain is falling upward: the water leaves the basin in a slow clear column and goes up into the dark and does not come down. People stand round the square, a great many, clear, unmoving, the way people stand at the Hymn. They are all facing the Sounding.".
  Observe msounding_scene at mirror_sounding when true "The Sounding in the water has no grating in its floor and no shaft. At the centre, where the black water should be, stands a figure of water the size of a woman, kneeling, with her face turned up and her mouth open, singing; and her hands are flat on the rim of a basin that is not there.".
  Observe moffice_scene at mirror_office when true "The Office in the water. The counter, the benches, the words over the inner door cut the right way round, and on the far wall, where the Check hangs in the Office you know, a glass in which they read backward: WHAT IS MEASURED HONESTLY CAN BE SETTLED PEACEFULLY, reversed, and under it, the wrong way round, your face. On the counter lies a ledger the size of a door, open, made of water, and on its open page a single column, very long.".
  Observe mward_scene at mirror_ward when true "The Ward in the water. Tench Row stands on its stone feet with every net wet, and the Mere comes up to the fourth step of the landing, and every boat in the Ward is afloat, the Tench among them. On the steps, sitting, standing, lying in the boats as if asleep, are the Reflected: hundreds of them. This is where they wait. Some of them are singing the evening's Hymn; some of them yesterday's; some of them, you think, an evening three thousand years ago.".
  Observe mstair_scene at stair_foot when true "At the edge of the Ward in the water, where the real Mere would be, the still water stands up into a stair: broad, clear, glass, going up, not down, into the dark, step after step, until you lose it. Wet footprints too wide and too flat for any person's go up it, and come down it, and go up.".

  // What the Auditor learned the hymn from: the Lector's forty nights, made into an image.
  Thing aun_image "the kneeling figure" at mirror_sounding {
    State singing "The kneeling figure of water sings without breath.".
    Tries listening.
  }
  Discovery aun_backwards "In the Sounding in the water, the Auditor has made an image of Aun, the Lector who held it back for forty nights, and the image sings her Fourth Remainder backwards: deep then high. It is learning to unsing the lock.".
  Rule aun_listened when tried(aun_image, listening) and not knows(party, aun_backwards)
    says "You put your head close to its mouth. It is singing the Fourth: high, and deep, deep, deep. Then it sings it again, and you hear that it is not: it is deep, deep, deep, and then high. Backwards. Over and over, slowly, the way you would practise a word in a language you meant to speak well. Its face, you see now, is the face carved over the Lector's bench: Aun's." teaches aun_backwards { }
  Topic isaura_aun with isaura travelling "Ask Isaura what the kneeling figure is doing" when knows(actor, aun_backwards) once {
    Says "'Learning.' Isaura has gone very pale. 'It's learning the one voice that ever held it back, so it can say it backwards.' She is quiet. 'It's very patient. It's more patient than the Office. It has been practising one verse for three thousand years.' A breath. 'I'd like to go now. I'd like that noted. I'd like to go and I'm not going to.'".
  }

  // The ledger of water, in the Office in the water: the count as the Auditor reads it.
  Thing water_ledger "the ledger of water" at mirror_office {
    State open "The ledger of water lies open on the counter, one long column down its page.".
    Tries looking.
  }
  Discovery ledger_of_water "The ledger of water in the Office in the water is the count as the far side receives it, written in the machine's notation, a ninth to a page; and the water takes the mark of whoever writes in it.".
  Rule ledger_looked when tried(water_ledger, looking) and not knows(party, ledger_of_water)
    says "The column is the count. You can read it: the machine's notation, the strokes the column sang you, a ninth to a page, the pages turning by themselves as you watch. You put a finger to the page to stop it turning and the water takes your fingerprint, and keeps it, a little whorl in the column, and does not let it go." teaches ledger_of_water { }
  Relation isauraWillWrite(group). Relation countFalsified(engine).
  Topic isaura_ledger with isaura travelling "Ask Isaura what she sees in the ledger of water" when knows(actor, ledger_of_water) once {
    Says "Isaura reads it for a long time, standing, her hands behind her back as if she did not trust them. 'It's the count,' she says. 'As it's received. As whoever is on the far side reads it.' She looks at the fingerprint in the column. 'And it takes a mark.' She does not say the next thing. You watch her not say it. Then she says it, because she is who she is: 'I could write in it. One figure. A ninth that isn't there. It would read the census whole, and short, and wrong.' She takes a breath. 'That would be a lie with a number in it. People believe the number.' She does not look at you. 'So would it.'".
  }
  Topic isaura_will_write with isaura travelling "Ask Isaura to write the false figure in the ledger of water" when knows(actor, ledger_of_water) and knows(actor, auditor_known) and not isauraWillWrite(isaura) and not countFalsified(reckoner) once {
    Says "She looks at you for a long time, and you see her decide, and you see what it costs. 'I'll write it,' she says. 'Not here. In front of it. If it's going to believe a lie of mine it can watch me tell it.' She puts her ledger away in her coat, and buttons the coat over it. 'After this I don't think I'll be able to measure anything. Not honestly. I'll always know I can do the other thing.' She almost smiles. 'Noted.'".
    On discuss { Assert isauraWillWrite(isaura). }
  }

  // The doubles: stay too long among the Reflected and they make a copy of you, and it walks up into the Bowl. Up there
  // it does what a reflection does when it is not shown its original: it tries to take its place.
  Relation doubled(group).
  Measure mirrorWatches(group). Measure lastMirror(group).
  Rule mirror_ticks when (at(party, mirror_ward) or at(party, mirror_square) or at(party, stair_foot) or at(party, mirror_sounding) or at(party, mirror_office)) and watch(clock) > lastMirror(party) {
    Increase mirrorWatches(party) by 1. Set lastMirror(party) to watch(clock). }
  Rule doubles_rise at mirror_ward when at(party, mirror_ward) and not doubled(party) and mirrorWatches(party) >= 1
    says "On the steps of the Ward in the water, one by one, figures stand up that were not there: a woman in a long coat with a rod under the wrong arm; and the rest of you, every one, clear as glass and the wrong way round. They look at you with your own faces, closely, the way a copying clerk looks at the page he is copying from." {
    Assert doubled(party). }
  Relation doublesLoose(group). Relation doublesLaid(group).
  Rule doubles_walk when doubled(party) and mirrorWatches(party) >= 12 and not doublesLoose(party)
    says "Behind you in the Ward in the water, the figures with your faces get up off the steps all together and walk away up the stair toward the coin of light that is the Mere from below." {
    Assert doublesLoose(party). }
  // They fight as the company fights, being copies of it: people, not monsters, with a weapon in the other hand.
  Person doubles "your doubles" at mirror_ward {
    Role "yourselves in water, left for right, your weapons in the other hand". Ancestry human. Calling warrior. Level 1. Numbers 4.
    Called "the double with your face", "the double with the left-handed blade", "the double that is late", "the double in the long coat".
    Seen when doublesLoose(party) and not doublesLaid(party).
    Comes "They come up the steps at you, each to its own, the way a reflection comes up to meet you when you lean over a well.".
  }
  Initially Assert tolerates(doubles, party).
  // Loosed, they stand on the Ward landing after dark, where you stood, and are hostile; by day they are under the water.
  Rule doubles_up when doublesLoose(party) and not doublesLaid(party) and dark() and at(doubles, mirror_ward) {
    Retract at(doubles, mirror_ward). Assert at(doubles, ward_landing). }
  // They give you one watch, the time it takes a reflection to notice that it is being looked at; then they come.
  Measure doublesTurn(group).
  Rule doubles_notice when at(doubles, ward_landing) and at(party, ward_landing) and doublesTurn(party) == 0 and not doublesLaid(party)
    says "On the landing your doubles stop singing and turn to you, all together, with your own faces. They lift their hands as you lift yours, a moment late. Each one is looking at the one it was made from, and coming slowly up the steps toward it." {
    Set doublesTurn(party) to watch(clock) + 1. }
  Rule doubles_turn when doublesTurn(party) > 0 and watch(clock) >= doublesTurn(party) and at(doubles, ward_landing) and at(party, ward_landing) and tolerates(doubles, party) and not doublesLaid(party) {
    Retract tolerates(doubles, party). }
  Rule doubles_let_go when doublesTurn(party) > 0 and not at(party, ward_landing) {
    Set doublesTurn(party) to 0. Assert tolerates(doubles, party). }
  Rule doubles_down when at(doubles, ward_landing) and not dark() {
    Retract at(doubles, ward_landing). Assert at(doubles, mirror_ward). Assert tolerates(doubles, party). }
  Rule doubles_lie when doublesLaid(party) and at(doubles, ward_landing) {
    Retract at(doubles, ward_landing). Assert at(doubles, mirror_ward). Assert tolerates(doubles, party). }
  Observe doubles_on_landing at ward_landing when doublesLoose(party) and not doublesLaid(party) and dark() "Among the Reflected on the landing, now, there is a company you know: the wrong way round, standing where you stood, singing.".
  // Four ways past them besides a fight: the Seventh, the bell, an honest measure, or keeping off the landing at night.
  Action sing_doubles(actor: group, site: place) "Sing the Seventh at your doubles" {
    Description "Four low notes, alike. They are made of the same water as the rest.".
    Requires able(actor) and company(actor) and at(actor, site) and at(doubles, site) and doublesLoose(actor) and not doublesLaid(actor) and knows(actor, remainders_tones).
    Time 1.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert doublesLaid(actor). }
    Result "You sing it at yourselves. Your doubles open their mouths to sing it back, and cannot; it is the one verse the water was never taught backward. They come apart where they stand, the way a reflection comes apart when a stone goes in.".
    Otherwise "You sing it, but your voices shake, and your doubles sing it back at you perfectly, a moment late, and keep coming.".
  }
  Action ring_doubles(actor: group, site: place) "Ring the Ear's bell at your doubles" {
    Description "High, and deep.".
    Requires able(actor) and company(actor) and at(actor, site) and at(doubles, site) and doublesLoose(actor) and not doublesLaid(actor) and carries(actor, ear_bell).
    Time 1.
    On success { Assert doublesLaid(actor). }
    Result "The bell's two notes go out over the landing, and your doubles stop as if somebody had called their names, and the right ones, and stand there, and are water, and run down the steps into the mud.".
  }
  Action measure_doubles(actor: group, site: place) "Ask Isaura to measure your doubles with her ell-rod, and call the figures" {
    Description "Measured honestly, a reflection is only a reflection.".
    Requires able(actor) and company(actor) and at(actor, site) and at(doubles, site) and doublesLoose(actor) and not doublesLaid(actor) and travelsWith(isaura, actor).
    Time 2.
    On success { Assert doublesLaid(actor). }
    Result "Isaura walks straight up to her own double with the ell-rod and lays it against its arm, and calls the figure, loud, the way the Office calls a figure in the square: 'Left arm, one ell and a hand.' The double's rod is in its left hand; she has measured its right arm and called it left. It looks down at itself. She goes along the line of them, one by one, calling every figure true, and every figure is the wrong way round; and one by one, as they hear what they are, they lie down in the water they are made of. She is shaking when she has done. 'They can copy anything,' she says. 'They can't check it.'".
  }
  Topic dov_doubles with dov "Ask Dov why the Ward looks at you the way it does" when doublesLoose(party) once {
    Says "'Because you were on the landing last night,' says Dov. 'All of you. Measure too, with the rod in the wrong hand. Singing with the rest of them.' He looks at you very hard. 'And here you are in my yard with your hands the right way round.' He spits, and does not look away. 'I'll take your word for which is which. The Ward won't. Don't come down the steps after dark.'".
  }
}

data/adventures/low-water/isaura.kyr:
Module lowwater "Low Water" {
  Description "Isaura Vant, Clerk-Measurer, Third Grade, of the Office of Measures: who believes that what is measured honestly can be settled peacefully.".

  Person isaura "Isaura Vant" at rim_head {
    Role "Clerk-Measurer, Third Grade, of the Office of Measures". Ancestry human. Calling thief. Level 3. Peaceable. Pronouns she. Manner stoic.
    Joins "Isaura tucks the brass ell-rod under her arm and falls in beside you, half a step behind, where she can see what you see and also write it down.".
    Leaves "Isaura nods once. 'I'll be at the Office,' she says. 'Ask for Third Grade. They'll know which one you mean.'".
    Carries lantern. Carries lamp_oil.
    Greets "Isaura looks up from her ledger, finishes the line she was writing, and then looks up properly.".
  }
  Rule isaura_waits when watch(clock) >= 36 and at(isaura, rim_head) and not travelsWith(isaura, party) { Retract at(isaura, rim_head). Assert at(isaura, office_hall). }
  Observe isaura_first at rim_head when at(isaura, rim_head) and watch(clock) < 36 "A woman in a grey coat is standing at the head of the Stair with a brass rod under her arm, as if she had been there all morning and would be there all afternoon.".
  Topic isaura_hello with isaura "Ask the woman in grey if she is waiting for you" when not willing(isaura, actor) and not travelsWith(isaura, actor) once {
    Says "'You're the Assessor.' It is not a question. 'Isaura Vant. Office of Measures, Third Grade. I'm to accompany you, record your findings, open what you need opened, and stop you being robbed. The Registrar would like your Finding at the Hearing, which is at noon in six days' time.' She glances down at the Mere. 'It was at the fourth step of the Ward landing when I was a girl. There are twenty-nine painted steps above it now. I'll show you the twenty-ninth. That's the kind of thing I'm for.'".
    On discuss { Assert willing(isaura, actor). Assert knows(actor, commission). }
  }
  Topic isaura_hello_office with isaura "Ask Clerk Vant if she will come with you after all" when not willing(isaura, actor) and not travelsWith(isaura, actor) and at(isaura, office_hall) once {
    Says "'I waited at the Stair,' says Isaura, not reproachfully; it is a fact, and she is recording it. 'You came down another way, or not at all. Either is permitted.' She closes her ledger. 'I'm still assigned to you. I'd like to be useful. I am, generally, in the end.'".
    On discuss { Assert willing(isaura, actor). Assert knows(actor, commission). }
  }

  // On the way: what she says when she is asked, and what comes of what she has seen.
  Topic isaura_grade with isaura travelling "Ask Isaura what Third Grade means" when true once {
    Says "'There are five grades. Fifth carries ledgers. Fourth copies them. Third measures. Second checks the measuring. First is the Registrar's deputy and measures nothing at all; he goes to dinners.' A pause exactly long enough. 'I've been offered Second twice. I'd have to stop measuring things and start checking other people measuring them, and they're nearly all wrong, and I'd have to be polite about it.' She shifts the ell-rod. 'I'm not good at polite. I'm good at accurate. They're not the same skill.'".
  }
  Topic isaura_office_faith with isaura travelling "Ask Isaura whether she believes what is over the Office door" when true once {
    Says "'Yes.' Then, because you wait: 'My grandmother was nine in the Thirst Riots. She hid in a dye-vat on the Dyers' Terrace for two days while men cut each other's throats over the Dyers' Basin, the one with the arch in it. Afterwards the Office measured every right in the Bowl and wrote them down and read them out in the square, every one, for a month. And nobody fought again.' She looks at the terraces. 'It isn't a slogan. It's the reason there are people here. What is measured honestly can be settled peacefully. Honestly is the hard word. Most people think it's measured.'".
  }
  Topic isaura_pleasure with isaura travelling "Ask Isaura what she does when she is not working" when true once {
    Says "She actually considers it. 'I measure the rain on my landlady's roof,' she says. 'With a pan. To compare it with the evaporation from a second pan. She thinks it's witchcraft and leaves me cake so I won't curse her.' A beat. 'It's a very good cake. I've told her it's science and she won't have it. I've stopped trying; the cake is better when she's frightened.' You realise, slightly late, that she has made a joke.".
  }
  Topic isaura_dov with isaura travelling "Ask Isaura about her brother" when knows(actor, isaura_ward) or met(dov, dov_yard) once {
    Says "'Dov.' She walks a few steps. 'He's eleven months older and four times louder. He kept our father's boat when Father drowned. I went up to the Office.' She is quiet. 'He thinks I went up so I wouldn't have to go out on the water. He's half right. I went up so somebody in the family would know what the wind was going to do before it did it.' She looks at you sidelong. 'He calls me Measure. He thinks I hate it. I let him think so. It's the only thing he calls me.'".
  }
  Topic isaura_registrar with isaura travelling "Ask Isaura about Registrar Fenn" when knows(actor, commission) once {
    Says "'Odile Fenn is the best Registrar the Office has had in a century,' says Isaura, 'and she'd tell you so herself, and she'd be right.' A pause. 'She's also been told by half the Council that the Office had better find the Guild guilty, or the charter of the Office comes up for review too. She hasn't told you that. I'm telling you. Note it however you like.'".
  }
  Topic isaura_quill with isaura travelling "Ask Isaura what she makes of Harrow Quill" when met(quill, quill_room) once {
    Says "'He's honest about being dishonest.' She considers that. 'Which is a kind of dishonesty. He tells you exactly what he's doing so you'll admire the telling and forget the doing.' She walks on. 'He's also right that his Channel is twenty-two ells and the fall is sixty. I wish he weren't. It would be so much simpler to dislike him correctly.'".
  }
  Rule met_quill when at(party, quill_room) and at(quill, quill_room) and not met(quill, quill_room) { Assert met(quill, quill_room). }
  Rule met_dov when perceives(dov, party) and not met(dov, dov_yard) { Assert met(dov, dov_yard). }
  Rule met_orr when perceives(orr, party) and not met(orr, cantor_room) { Assert met(orr, cantor_room). }
  Topic isaura_orr with isaura travelling "Ask Isaura what she thinks of Cantor Orr" when met(orr, cantor_room) once {
    Says "'I went to the Short Hymn once. The first winter.' Isaura says it as if confessing to a fine. 'I stood at the back. I don't sing; I can't. But I stood there and the whole dome breathed in, and I breathed in with it, and I couldn't have told you how many people were in that room, and for once I didn't want to.' She is quiet a moment. 'I didn't go again. It frightened me. I like to know how many people are in a room.'".
  }
  Topic isaura_clock with isaura travelling "Ask Isaura how the locks know when to open" when true once {
    Says "'The bells.' She seems surprised you need to ask, and then surprised that she has never been asked. 'Every keeper opens and shuts by the Hymn and the hours. The Third Bell, the Long Amen, the Sixth. It's the Lock-Rhyme; children skip to it.' She frowns. 'Nobody writes it down. It's the one schedule in the Bowl the Office doesn't keep. The Sounding keeps it. By singing.' You can see her not liking that, and filing it.".
  }
  Topic isaura_tally with isaura travelling "Ask Isaura what is troubling her" when knows(actor, channel_measured) and not knows(actor, discrepancy) once {
    Says "'May I show you something that isn't in the official ledger?' She takes out a thin book. 'A ledger is what the Office believes. This is a tally: what I've counted.' Columns, tiny, perfect. 'Inflow at the Rim Gauge, less your twenty-two. Less every right recorded on every terrace. Less evaporation, from my landlady's roof. What's left should arrive in the Mere. It doesn't. Forty ells a day don't arrive anywhere.' She closes the book. 'Forty ells is a river. You can't steal a river in a bucket and nobody's dug a second one. It isn't stolen. It's missing. Water doesn't go missing. That's the first thing they teach you. This is the only figure I have ever written that I can't put somewhere.' And then, very low: 'If I give it to the Registrar she'll tell me to put it on the Guild. I'd be writing a lie with a number in it. People believe the number.'".
    On discuss { Assert knows(actor, discrepancy). }
  }
  Discovery discrepancy "Isaura Vant's own tally of the Bowl's water does not close: forty ells a day of the Ninefold, after the Channel, every right on every terrace and the evaporation, never arrive in the Mere or anywhere else.".
  Discovery missing_found "The forty ells a day Isaura's tally cannot place go down the Deep Gate at the Ninth Lock, and come out nowhere.".
  Rule missing_put when knows(party, discrepancy) and knows(party, deep_drinks) and not knows(party, missing_found)
    says "Forty ells a day that arrive nowhere, and a gate in the floor of the Ninth Lock that water goes down and does not come out of. Isaura says it before you do: 'There. That's where.'" teaches missing_found { }
  Topic isaura_missing with isaura travelling "Ask Isaura what she makes of the Deep Gate" when knows(actor, missing_found) once {
    Says "'It's not stolen. It's not lost. It's used.' She says it slowly, getting it right. 'Water you can account for goes somewhere you can put a rod in. This goes somewhere I can't. That's not a number problem, that's a, I don't know what it is.' She looks at the rod in her hand as if it had failed her. 'I haven't a column for it.'".
  }
  Topic isaura_letters with isaura travelling "Ask Isaura what she thinks of Piet Harl's letters" when knows(actor, letters_read) once {
    Says "She reads them twice, standing, and gives them back. 'He wrote to the Sounding,' she says. 'Not to us. Of course he did; the rhyme tells him to.' A long pause. 'If he'd written to the Office, we'd have answered.' Another. 'We'd have answered with a form. Request for Inspection of a Gate, Sounding Post, in triplicate.' She puts her hands in her coat. 'And somebody would have filed it. I would have filed it, probably. Three years. Noted.'".
  }
  Topic isaura_hymn_cause with isaura travelling "Ask Isaura what she makes of the Short Hymn now" when knows(actor, hymn_cause) once {
    Says "'A schedule nobody wrote down.' She is angrier than you have seen her, in her way, which is to say she is speaking very evenly. 'The most important operating order in the Bowl, kept by a choir, and changed by a choirmistress, for the best of reasons, with nobody told who would need to be told, because nobody knew it was an order.' She breathes. 'Everybody in this city did their job. That's what I can't forgive. Not one person was negligent. It was all the gaps between them.'".
  }
  Topic isaura_engine with isaura travelling "Ask Isaura what she makes of the Reckoner" when knows(actor, engine_seen) once {
    Says "She has not said anything since the counting gallery. Now she says, 'It's a ledger.' You wait. 'It counts by passing water through itself, a measure at a time, and when a wheel is full it locks and the next begins. Columns.' She looks at her own book, in her hands, and then she does not. 'You keep a ledger for somebody to come and settle it. Who?'".
  }
  Topic isaura_census with isaura travelling "Ask Isaura what she thinks the Reckoner is counting" when knows(actor, census_read) once {
    Says "'Halm says souls. The Cantor would say souls, if you asked her, and the Precentor's been saying souls for thirty years.' She walks a while. 'My grandmother used to say every drop in the Mere was somebody who'd lived in the Bowl. I thought it was a nursery thing.' She stops. 'I don't believe it. I want that noted.' Then, with an effort: 'But I'd like to know the number. Isn't that terrible.'".
  }
  Topic isaura_measure_early with isaura travelling "Ask Isaura whether everything can be measured" when not knows(actor, engine_seen) once {
    Says "'Everything that is, can be.' She says it like a catechism, and then, because she is honest, keeps going. 'Not everything is easy. Grief is hard to measure. The Ward's grief is hard. But you can count the people who've left and what they owned and what the water would have been worth to them, and put that in a column, and then at least you're arguing about the same thing.' She looks at you. 'You think that's cold.' You don't say. 'It's the opposite of cold. It's the only way a city of people who hate each other can agree on anything at all.'".
  }
  Topic isaura_measure_late with isaura travelling "Ask Isaura again whether everything can be measured" when knows(actor, engine_seen) once {
    Says "She is quiet so long you think she won't answer. 'Everything can be measured,' she says. 'That isn't the question. The question is who decides what to measure.' She holds up the ell-rod. 'I can tell you the Channel is twenty-two ells. I can't tell you whether the mill hands' wages weigh more than the Ward's fish. I can tell you what's left in the Mere; I can't tell you if a census of souls is worth a pond.' She lowers the rod. 'I used to think measuring settled things. It doesn't. It tells you exactly how big the thing is that you're going to have to decide anyway.'".
  }
  Topic isaura_one with isaura travelling "Ask Isaura whether the Bowl is one city or many" when met(orr, cantor_room) and met(quill, quill_room) once {
    Says "'Many,' she says at once. 'Four terraces, nine locks, a hundred sluices, two thousand rights, and every one of them its own little quarrel with the next.' Then she frowns. 'And one water. That's the trouble. It all comes in at the Rim and it all goes down to the Mere, whoever has it on the way. You can't own a piece of it; you can only own the right to have it for a while as it goes past.' She thinks. 'The Cantor sings it as one. Quill wants it to be a sum.' A small smile. 'I prefer the ledger. You can check a ledger.'".
  }
  Topic isaura_equals with isaura travelling "Ask Isaura what she makes of the Equals" when knows(actor, equals_rule) once {
    Says "'They're clerks.' She is entirely serious. 'Bronze clerks. They have one rule: keep the reckoning even. They don't care who you are or why you're on the floor; they care that the floor's tipped.' She considers. 'I've worked with worse. I've worked under worse.' A pause. 'I've been worse, some days. Noted.'".
  }
  Topic isaura_halm with isaura travelling "Ask Isaura what she thinks of Teodor Halm" when met(halm, dig) once {
    Says "'He'd give the lake for the Reckoner.' She says it without heat. 'He told me so, the first day, so I wouldn't be surprised later. I appreciated that.' She thinks. 'He's the only person in Ammerlin who doesn't want any of the water. That should make him the most neutral person in the Bowl. It makes him the most dangerous.'".
  }
  Rule met_halm when perceives(halm, party) and not met(halm, dig) { Assert met(halm, dig). }
  Topic isaura_ward_leaving with isaura travelling "Ask Isaura about the people leaving the Ward" when wardLeaving(ammerlin) once {
    Says "'Forty-one households this week.' She has counted them, of course. 'Most up to the Dyers' Terrace, to cousins. Some to the mills, for Quill's wages, when there are wages. Some out of the Bowl altogether.' She walks a while. 'They won't come back. That's the thing nobody measures. The water can come back and the people won't. A street is not water. You can't pour it in again.'".
  }
  Topic isaura_drowned with isaura travelling "Say something to Isaura about the diggers who drowned" when drowned(diggers) once {
    Says "'Hob Kettle,' says Isaura. 'Annet Kettle. Jory Pale.' She says it the way her brother said it, and you realise they must have learned that from the same person. 'I had the figure. Three spans under. I had it in my book.' She does not cry; her voice gets more exact. 'I should have taken the book down to him myself. I should have stood in the hole and read it out to him in a loud voice until he believed it.' She closes the book. 'I didn't, because he'd have shouted at me. Three people. Against being shouted at.'".
  }
  Topic isaura_quill_deal with isaura travelling "Ask Isaura what she thinks of your bargain with Quill" when quillDeal(quill) once {
    Says "She does not answer until the ell-rod has been turned over twice in her hands. 'It's a good bargain,' she says at last. 'For the Mere. For the mills, even. The Reckoner gets its water and the Ward keeps its water.' She looks down the terraces, toward the Ward. 'And the Ward doesn't keep its ground. The dig and the temples and everything under them go to the Guild, sealed by the Office. My brother will never speak to me again. I'd like you to know I've worked that out. I'm not asking you to undo it. I'm noting it.'".
  }
  Topic isaura_chain with isaura travelling "Ask Isaura what she thought of breaking the Guild's chain" when state(guild_chain, cut) and not quillDeal(quill) once {
    Says "'It was the Guild's by charter.' Flatly. 'You may have been right to break it. I'll write that you were right, if you were. I'll also write that you broke it.' She looks at you directly. 'That's what I'm for. I'm not here to make what you did look like something else.'".
  }
  Topic isaura_mag with isaura travelling "Ask Isaura about Mag Torrin's vats" when vatsDrowned(vat_yard) once {
    Says "'A season's blue,' says Isaura. 'Five yards' worth, because the others dye from her vats too. I could put a figure on it.' She doesn't. 'She'll be at the Hearing. She's entitled to be.' She walks on, and then, without looking round: 'There was another way down to that floor. Mag would have taken her blue early if you'd asked her.'".
  }
  Topic isaura_reconciled with isaura travelling "Ask Isaura how it was, letting her brother out" when reconciled(isaura) once {
    Says "'He put his hand on my head.' She seems to be checking that she has the fact right. 'He used to do that when I was small and had done something stupid and hadn't drowned. Like a, like a mark on a post. Still there.' She clears her throat. 'He's been arrested four times. I've never once signed him out. I always thought it would look like favour.' A pause. 'It did look like favour. Noted.'".
  }
  Topic isaura_dov_listened with isaura travelling "Tell Isaura that Dov listened to her figures" when warnedDov(dov) once {
    Says "Isaura stops where she is, and stands there. 'He said that?' Yes. 'He said Measure's figures?' Yes. She looks down toward the Ward, where somewhere her brother is shouting at people about sandbags. 'Huh,' says Isaura Vant, Clerk-Measurer, Third Grade, and does not write it down.".
  }
  Topic isaura_broken with isaura travelling "Ask Isaura how she feels about the Reckoner stopping" when broken(reckoner) once {
    Says "'The Mere will stand,' she says. 'The figures will close. The forty ells will come to the Mere, and I'll be able to put them somewhere.' She is very quiet. 'And I'll never know what it was counting.' She tucks the ledger into her coat. 'I'm glad. I'm glad about the Mere. I want that recorded first. The other thing I'll keep in the tally, where it belongs.'".
  }
  Topic isaura_complete with isaura travelling "Ask Isaura how she feels about the count being finished" when complete(reckoner) once {
    Says "'It closed.' She says it with wonder, and some fear. 'Whatever it was counting, the account is closed. Nine wheels locked.' She looks at her own book. 'Somebody's going to come and settle it, I suppose. Or nobody. Or they already have.' Then, practical, because she is: 'The Mere fell six spans in one breath. I measured it, after. Six. The Ward will want that figure.'".
  }
  // Before the Hearing: whether she will put her name to the Finding.
  Relation isauraSigns(group). Relation isauraRefuses(group).
  Topic isaura_sign with isaura travelling "Ask Isaura if she will sign the Finding with you" when knows(actor, discrepancy) and hearingDay() and not isauraSigns(isaura) and not isauraRefuses(isaura) once {
    Says "'It'll be my tally in it.' She knows this already; she is making sure you do. 'The forty ells. That goes against the Office's own ledger. If I sign it, I'm a Third Grade clerk telling the Council that the Office has been wrong for three years.' She takes a breath. 'I'll sign what's true. I'll sign it in front of the Registrar and the Guild and my brother.' She looks at you very steadily. 'What I won't sign is anything that says it's settled when it isn't. If we're going to tell them a thing they have to decide, we tell them so.'".
    On discuss { Assert isauraSigns(isaura). }
  }
  Event isaura_morning when travelsWith(isaura, party) and hearingDay() and hour(clock) >= 7 and knows(party, discrepancy) and not isauraSigns(isaura) and not isauraRefuses(isaura)
    "Isaura is up before you, dressed in her best grey, with her tally in her coat. She does not say anything about the Hearing until you are both on the stair, and then she says, not looking at you: 'If you want my figures in the Finding, you'll have to ask me. I'd like to be asked.'".
  Event isaura_governor at governor_room when travelsWith(isaura, party) and not broken(reckoner) "Isaura watches the bronze arms swing out and in, counting under her breath. 'That's what keeps it honest,' she says at last. 'Without that it would just run. With it, it counts.' She sounds almost envious.".
  Event isaura_door at last_door_room when travelsWith(isaura, party) and not complete(reckoner) "At the bottom of the long stair Isaura stops, and puts her hand flat on the cold round door, the way you would on a horse's neck. 'Whatever's on the other side,' she says, 'it's been waiting longer than the Office has existed.' She takes her hand away. 'I'd still like to see its books.'".
  Event isaura_level at equal_hall when travelsWith(isaura, party) and balanced() and stonesIn(counterpan) > 0 "Isaura stands on the level floor between the two bronze figures and looks from one to the other. 'One weight for each of us,' she says. 'Not by how heavy we are. By how many.' She almost laughs. 'It's a census too. It's counting heads.'".
  Event isaura_counting at count_gallery when travelsWith(isaura, party) and at(party, count_gallery) "Isaura stands in front of the nine wheels and you see her lips moving. She is counting the gates on the nearest wheel. When she gets to the end she starts again.".
  Event isaura_column at column_room when travelsWith(isaura, party) and at(party, column_room) "Isaura looks up the still column of water into the dark for a long time. 'That goes up to the Sounding,' she says. 'Doesn't it. Every night. All of them singing into this.'".
}

data/adventures/low-water/library.kyr:
Module lowwater "Low Water" {
  Description "The Ear's Library: the Aeneans' archive behind the Listening Hall, half drowned, where speaking-stones sing in the voice of the last Lector, and tell what happened the one year the Fourth was not sung.".

  Place library_level "the Ear's Library" is level within hall_site.
  Place reading_room "the Lector's room" is room within library_level at 0, 0 underground.
  Place jar_gallery "the gallery of jars" is room within library_level at 1, 0 underground.
  Place low_archive "the low archive" is room within library_level at 2, 0 underground.
  Initially Assert unlit(reading_room). Initially Assert unlit(jar_gallery). Initially Assert unlit(low_archive).

  Passage ear_door "the low door in the spiral" is doorway between listening_hall and reading_room hidden until ear_door_search.
  Passage jar_stair "the steps down to the jars" is steps between reading_room and jar_gallery.
  Discovery ear_door_search "Behind the outer curve of the spiral, under a fall of silt, a low door." {
    Found by searching listening_hall "Where the spiral's outer wall meets the floor the silt has drifted deep, and where it has slumped the wall is not wall: a lintel, low, carved with an ear. Behind it, steps going down, dry.".
  }

  // Three bodies of water: the Ear's cistern above, the gallery of jars, and the low archive, drowned.
  Entity ear_cistern: basin "the Ear's cistern". Entity ear_gallery: basin "the gallery's pool". Entity ear_archive: basin "the low archive".
  Initially Set level(ear_cistern) to 4. Initially Set brim(ear_cistern) to 5.
  Initially Set level(ear_gallery) to 0. Initially Set brim(ear_gallery) to 3.
  Initially Set level(ear_archive) to 3. Initially Set brim(ear_archive) to 3.
  Thing ear_upper "the cistern valve" at reading_room {
    State wound_down "A valve of green bronze in the wall lets the Ear's cistern into the gallery below. It is shut. The cistern's mark-stone stands at {level(ear_cistern)}, the gallery's at {level(ear_gallery)}.".
    State wound_up "The cistern valve is open; water goes down into the gallery of jars. The cistern's mark-stone stands at {level(ear_cistern)}, the gallery's at {level(ear_gallery)}.".
    Change open "Turn the cistern valve open" from wound_down to wound_up.
    Change shut "Turn the cistern valve shut" from wound_up to wound_down.
  }
  Thing ear_lower "the archive valve" at jar_gallery {
    State wound_down "A second valve, low in the gallery's far wall, a flap of bronze that opens only one way, lets the drowned archive into the gallery's pool and nothing back. It is shut. The pool stands at {level(ear_gallery)}, the archive at {level(ear_archive)}.".
    State wound_up "The archive valve is open; the archive's water comes through into the gallery's pool. The pool stands at {level(ear_gallery)}, the archive at {level(ear_archive)}.".
    Change open "Turn the archive valve open" from wound_down to wound_up.
    Change shut "Turn the archive valve shut" from wound_up to wound_down.
  }
  Thing ear_drain "the pool's drain" at jar_gallery {
    State stopped "In the floor of the gallery's pool a bronze stopper on a chain closes a drain into the Hall's throat.".
    State pulled "The pool's drain stands open; the gallery's water runs away into the dark of the throat.".
    Change pull "Pull the drain's stopper" from stopped to pulled.
    Change stop "Let the stopper back into the drain" from pulled to stopped.
  }
  Rule ear_upper_flows when state(ear_upper, wound_up) and level(ear_cistern) > level(ear_gallery) and level(ear_gallery) < brim(ear_gallery) {
    Decrease level(ear_cistern) by 1. Increase level(ear_gallery) by 1. }
  Rule ear_lower_flows_out when state(ear_lower, wound_up) and level(ear_archive) > level(ear_gallery) and level(ear_gallery) < brim(ear_gallery) {
    Decrease level(ear_archive) by 1. Increase level(ear_gallery) by 1. }
  Rule ear_drains when state(ear_drain, pulled) and level(ear_gallery) > 0 { Decrease level(ear_gallery) by 1. }
  // Rain and seep fill the Ear's cistern again by every dawn, from the Hall's own catchment.
  Rule ear_refills when hour(clock) == 6 and level(ear_cistern) < 4 and not earFilled(bowl) { Set level(ear_cistern) to 4. Assert earFilled(bowl). }
  Rule ear_fill_resets when hour(clock) == 7 and earFilled(bowl) { Retract earFilled(bowl). }
  Relation earFilled(place).
  // The archive's door floats: a stone leaf on a buoy that rises only when the pool beside it is full. And the
  // archive beyond is walkable only once it has been let down to its last mark.
  Passage float_door "the floating door" is doorway between jar_gallery and low_archive
    opening when level(ear_gallery) == 3 and level(ear_archive) <= 1 "In the far wall, beside the archive valve, a door of stone hangs in a slot, its lower edge in the pool, resting on something you cannot see. It does not move when you push it. Through the crack under it, black water.".
  Discovery float_known "The archive's door floats: it rises on a buoy when the gallery's pool beside it is full.".
  Rule float_seen at jar_gallery when at(party, jar_gallery) and not knows(party, float_known)
    says "You lie on the walk and reach down into the pool beside the stone door, and your hand finds a great float of fired clay under its lower edge, sitting on the water: the door is held up by the pool, when there is pool enough." teaches float_known { }

  Observe reading_scene at reading_room when not familiar(reading_room) "A low round room cut in the grey stone, dry as an oven, with a stone bench round its wall and on the bench, in rows, polished stones the size of a loaf, each set on a little cushion of rotten cloth. Above the bench the wall is carved with a single long ear, from floor to ceiling. On the wall by the stair a bronze valve, green, and a mark-stone in a channel.".
  Observe reading_again at reading_room when familiar(reading_room) "The Lector's room: the bench of speaking-stones under the carved ear.".
  Observe gallery_scene at jar_gallery when not familiar(jar_gallery) "A gallery below, longer than the room above, with a stone walk along one side and a pool along the other, and in the pool, on shelves going down into the water, tall jars of fired clay, sealed, hundreds of them. The pool has a drain in its floor and a valve in its far wall, and beside the valve a door of stone hanging in a slot.".
  Observe gallery_again at jar_gallery when familiar(jar_gallery) "The gallery of jars, the pool and its sealed jars, and the stone door hanging in its slot.".
  Observe archive_scene at low_archive when true "The low archive is wet to the knee and smells of three thousand years of nothing. On a dais at the end, a single speaking-stone larger than the rest, black, the size of a child; and on a peg beside it, a bell of green bronze no bigger than a fist.".

  // The speaking-stones: struck, they sing back what was sung into them.
  Thing stones "the speaking-stones" at reading_room {
    State rowed "Rows of polished stones sit on the bench under the carved ear.".
    Tries pushing, looking.
  }
  Discovery lector_heard "Struck, the speaking-stones in the Ear's Library sing in a woman's voice, in Aenean, over and over: the Lector of the Ear, who kept the hymn.".
  Rule stones_struck when tried(stones, pushing) and not knows(party, lector_heard)
    says "You touch the nearest stone, and it sings. A woman's voice, close, as if she were sitting on the bench beside you, singing low in a language that is all vowels and stops: the same phrase, three times, and the stone falls silent. You touch the next. It is her voice again, older. The next: older still. Every stone on the bench is her, a little later each time." teaches lector_heard { }
  Discovery lector_words "The Lector's stones, read with the old script: I am Aun, Lector of the Ear. I keep the hymn for those who come after. Sing all seven. Sing the Fourth above all. The count is owed upward, to those who settled the world; the door was made to open on them. Something below has learned to stand under the door." {
    Found by searching reading_room with lore "Under each stone the bench is cut with Aenean letters, small, and with the glossary they come: I am Aun, Lector of the Ear. I keep the hymn for those who come after. Sing all seven. Sing the Fourth above all. The count is owed upward, to those who settled the world; the door was made to open on them. Something below has learned to stand under the door.".
  }
  Thing chronicle "the black speaking-stone" at low_archive {
    State waiting "The black speaking-stone stands on its dais.".
    Tries pushing.
  }
  Discovery silence_heard "The black stone in the low archive sings the Lector's last record, in Aenean, in a voice gone thin with age.".
  Rule chronicle_struck when tried(chronicle, pushing) and not knows(party, silence_heard)
    says "The black stone sings, and it is Aun again, old now, her voice gone thin and very steady, singing a long record without a single repeat; and at the end of it, four low notes, alike, and then nothing at all." teaches silence_heard { }
  Discovery long_silence "The Long Silence, as Aun recorded it: in the year the young Cantors left out the Fourth, the Mere stood up. It came up the Stair in the shapes of our dead and sang the Rising at every sluice, and the Deep drank, and the count ran, and under the door something pressed. I went down to the column and sang the Fourth into it with my own mouth, forty nights. On the fortieth the door held. I will not climb the stair again. Sing all seven." {
    Found by searching low_archive with lore "Round the dais the record is cut as well as sung, in Aenean, by her own hand you think: In the year the young Cantors left out the Fourth, the Mere stood up. It came up the Stair in the shapes of our dead and sang the Rising at every sluice, and the Deep drank, and the count ran, and under the door something pressed. I went down to the column and sang the Fourth into it with my own mouth, forty nights. On the fortieth the door held. I will not climb the stair again. Sing all seven.".
  }
  Topic halm_stones with halm "Ask Halm to tell you what the Lector's stones sing" when (knows(actor, lector_heard) or knows(actor, silence_heard)) and not knows(actor, long_silence) once {
    Says "Halm makes you sing it to him, the Lector's phrases, as near as you can, and writes, and stops, and writes. 'Aun,' he says. 'Lector of the Ear. She kept the hymn.' He has gone pale under the mud. 'Owed upward, she says, to whoever settled the world. And the door was made to open on them.' He reads the last line again, with his lips, and does not say it aloud. 'Sing the Fourth above all. The Aeneans cut that in stone and I do not think they ever knew what it cost her.'".
    On discuss { Assert knows(actor, lector_words). Assert knows(actor, long_silence). }
  }

  // The Ear's bell: the Lector's own, tuned to the Fourth.
  Kind ear_bell_kind "the Ear's bell" is treasure worth 30 weighing 1 described "A bell of green bronze no bigger than a fist, with a clapper of bone. It gives one note, high, and as it dies a second, deep, under it: the Fourth Remainder in one stroke.".
  Item ear_bell "the Ear's bell" is ear_bell_kind at low_archive.
  Action ring_at_reflected(actor: group, site: place) "Ring the Ear's bell at the Reflected" {
    Description "High, then deep: the Fourth, in one stroke.".
    Requires able(actor) and company(actor) and at(actor, site) and at(reflected, site) and dark() and carries(actor, ear_bell) and approach(bowl) >= 1 and not reflectedStilled(bowl).
    Time 1 minute.
    On success { Assert reflectedStilled(bowl). Decrease approach(bowl) by 1. }
    Result "The bell gives its high note and, under it as it dies, the deep one. The Reflected do not lie down this time. They come apart: as if a hand had been passed through still water, each figure goes to rings, and the rings go out, and the water at the landing is only water, and colder, and further off than it was.".
  }
  Action ring_at_column(actor: group, site: place) "Ring the Ear's bell into the listening column" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, column_room) and carries(actor, ear_bell) and not doorHeld(reckoner) and not complete(reckoner) and not broken(reckoner).
    Time 1 minute.
    On success { Assert doorHeld(reckoner). }
    Result "The bell's two notes go into the still water and up, high and then deep, the Fourth in one stroke. Far down the long stair something settles against the round door, the way a bar settles in its brackets. Under the column, the voice that has no mark goes quiet.".
  }
  // The column, understood afterwards.
  Observe column_lector at column_room when knows(party, long_silence) "Round the rim of the column's basin, where you would put your hands to sing into it, the grey stone is worn into two shallow hollows, the shape of hands, by somebody who knelt here a long time.".
  Topic orr_lector with orr "Tell Cantor Orr about Aun, the Lector of the Ear, and the forty nights" when knows(actor, long_silence) once {
    Says "Cantor Orr listens to all of it without moving. When you have done she gets up, goes to the shelf, and takes down the oldest hymnal, the one with the Remainders in, and opens it at the front, at a page you had taken for a decoration: a woman kneeling with her mouth open over a circle of water. 'We call her the Patron,' she says. 'Nobody knows her name. The choir kisses this page before the Long Hymn on feast days.' She closes the book. 'Aun.' She tries the name. 'I cut the verse she died for. Because a man in Corran wrote omit in the margin.' A long silence. 'Sing all seven. Yes. Every one.'".
    On discuss { Assert fifthRestored(bowl). }
  }
  Topic isaura_lector with isaura travelling "Ask Isaura what she makes of the Lector" when knows(actor, long_silence) once {
    Says "'She kept a record,' says Isaura. 'Three thousand years ago, alone, under a lake. She wrote down what happened, every night, and sang it into a stone so whoever came after could check her figures.' She is quiet for a long time. 'Forty nights. I'd like to have known her. I think she'd have been very hard to work for.'".
  }
}

data/adventures/low-water/locks.kyr:
Module lowwater "Low Water" {
  Description "The Nine Locks: the stair of water down the third terrace, the Ninth Lock and its Deep Gate, the lock-house of Piet Harl, and the culvert beyond the gate.".


  Place lock_stair "the lock stair" is room within ammerlin at 1, 3 outdoors.
  Place ninth_lock "the Ninth Lock" is room within ammerlin at 1, 4 outdoors.
  Place lock_house "the lock-house" is building within ammerlin.
  Place piet_room "the keeper's room" is room within lock_house at 0, 0.
  Place intake_culvert "the intake culvert" is room within undercroft at 0, 0 underground.

  Passage third_stair "the Stair, from the Dyers' Walk down the Nine Locks" is steps between dyers_walk and lock_stair taking 20 minutes.
  Passage ninth_steps "the steps to the Ninth Lock" is steps between lock_stair and ninth_lock.
  Passage keeper_door "the lock-house door" is door between ninth_lock and piet_room.
  Passage keepers_hatch "the keeper's hatch beside the Deep Gate" is steps between ninth_lock and intake_culvert
    opening when state(deep_gate, lowered) or state(deep_gate, logged) or broken(reckoner) or complete(reckoner) "Beside the Deep Gate an iron hatch is set in the lock floor. Under it, the culvert beyond the gate is a black throat of water going down at a run. Nothing goes down it that wants to come back.".
  Initially Assert unlit(intake_culvert).

  Observe stair_scene at lock_stair when not familiar(lock_stair) "The Nine Locks go down the third terrace like a giant's stair: nine stone chambers one below another, each with its gates and its balance-beams and its keeper's bench, and the Ninefold going down them in white falls. Barges of stone and wool wait at the head of each to be let down. A keeper in a blue coat at every lock, and a bell-rope at every keeper.".
  Observe stair_scene_again at lock_stair when familiar(lock_stair) "The lock stair: nine chambers of white water going down the terrace, a keeper at every one.".
  Observe ninth_scene at ninth_lock when not familiar(ninth_lock) "The Ninth Lock is the last and the deepest, at the foot of the terrace, and it does not open onto the Mere. Its lowest chamber has no lower gate. The water comes in from above, goes round in a slow black eddy, and leaves by the floor.".
  Observe ninth_scene_again at ninth_lock when familiar(ninth_lock) "The Ninth Lock, at the foot of the terrace, its water going round and down by the floor.".
  Discovery deep_drinks "The water of the Ninth Lock goes down through the Deep Gate in its floor, and no culvert from it comes out anywhere in the Bowl: not into the Mere, not into the Ward.".
  Rule deep_looked at ninth_lock when at(party, ninth_lock) and (state(deep_gate, raised) or state(deep_gate, half)) and not knows(party, deep_drinks) says "You lean over the chamber's edge. The eddy goes round and round and, at the bronze, down. You walk the lock's whole wall, and the Ward wall below it, for an outfall, a culvert, a weep-hole: there is none. Whatever goes down the Deep does not come back up anywhere you can find." teaches deep_drinks { }
  Discovery gate_hears "The Deep Gate answers the Hymn. At the first bell of the Sixth Remainder its bronze stirs in its bed, by nothing anyone can see.".
  Rule gate_stirs at ninth_lock when at(party, ninth_lock) and hour(clock) == 19 and sungTonight(bowl) and not knows(party, gate_hears) and not state(deep_gate, logged) says "At the first bell of the Hymn from the Sounding, far up the terraces, the bronze of the Deep Gate shivers in its bed, the whole width of it, the way a dog's skin shivers at its name. Nobody has touched it. The keeper on his bench writes something in his book." teaches gate_hears { }
  Discovery gate_falls_seen "At the Seventh Remainder, sung from the Sounding, the Deep Gate lay down in its bed by itself, as Abel Tarrant said it always did.".
  Rule gate_falls at ninth_lock when at(party, ninth_lock) and seventhTonight(bowl) and state(deep_gate, lowered) and hour(clock) == 20 and not knows(party, gate_falls_seen) says "Four low notes come down the terraces from the Sounding, alike, alike, alike, alike. The Deep Gate goes down. It goes down slowly, the whole bronze width of it, until it lies flat in its bed with a thread of water running over its lip. Piet Harl is standing on his bench with his book in both hands, and he is crying." teaches gate_falls_seen { }

  // Piet Harl, keeper of the Ninth Lock.
  Person piet "Piet Harl" at piet_room {
    Greets "Piet Harl stands up as if you were an inspector, and then sees you are not, and sits down again more slowly.".
    Role "the keeper of the Ninth Lock". Ancestry human. Peaceable. Pronouns he. Manner stoic.
  }
  Rule piet_to_bench when hour(clock) == 18 and at(piet, piet_room) { Retract at(piet, piet_room). Assert at(piet, ninth_lock). }
  Rule piet_to_room when hour(clock) == 22 and at(piet, ninth_lock) { Retract at(piet, ninth_lock). Assert at(piet, piet_room). }
  Observe piet_room_scene at piet_room when true "A keeper's room the size of a cupboard: a cot, a stove, a window on the Deep. On the table, the lock-book, open, and a stack of older lock-books in a crate, and a shelf with a clay figure of a young man holding a wheel, which is not very like him.".
  Observe piet_on_bench at ninth_lock when at(piet, ninth_lock) "Piet Harl sits on the keeper's bench with the lock-book on his knees, watching the Deep Gate the way you would watch a sleeping animal.".
  Discovery lockbook_read "Piet Harl's lock-book has one entry a night for three years, in the same hand: Deep up at the Sixth. Seventh not sung. Deep did not come down.".
  Thing lockbook "the lock-book" at piet_room {
    State open "The lock-book lies open on the table.".
    Tries looking.
  }
  Rule lockbook_looked when tried(lockbook, looking) and not knows(party, lockbook_read)
    says "Each night one line in a careful hand. Deep up at the Sixth. Seventh not sung. Deep did not come down. The next night the same. You turn back through the book, and the book in the crate under it, and the one under that. A thousand nights and more. On the first page of the oldest, before the new Hymn: Deep up at the Sixth. Down at the Seventh. Cupful. Then again, Down at the Seventh. Cupful. Then one night: Seventh not sung." teaches lockbook_read { }
  Discovery letters_read "Piet Harl wrote twice to the Sounding, the first winter of the Short Hymn, to ask when the Seventh Remainder would be sung, since the Deep Gate had not come down. The Sounding answered once, that the Remainders were a matter for the Cantors." {
    Source letters "Piet's copies of his letters to the Sounding, and the answer" at piet_room readable by party.
  }
  Topic piet_job with piet "Ask Piet Harl what his work is" when true once {
    Says "'Keeping the Ninth.' He says it as if it were obvious, and then sees it isn't. 'Letting the barges down to here, that's most of it, and the gates. And the Deep. At the Sixth Remainder it goes up, and at the Seventh it comes down, and I watch it, and I write it in the book.' He touches the book. 'Master Tarrant said the keeper's not there to work the Deep. There's nothing to work it with. He's there to see it.'".
  }
  Topic piet_deep with piet "Ask Piet whether the Deep Gate comes down now" when true once {
    Says "'No.' Very quiet. 'Not since the new Hymn. It goes up at the Sixth, they still sing the Sixth, it's the beautiful one. And then there's no Seventh, and it stays up.' He looks at the gate. 'Three years. I write it every night. Deep did not come down. I don't know what else to write. The rhyme says if it doesn't, send to the Sounding. I sent.'".
  }
  Topic piet_letters with piet "Ask Piet what the Sounding said" when true once {
    Says "He takes two folded papers from under the lock-book and a third with a seal, and gives you all three without being asked twice; he has been waiting for somebody to ask. 'I wrote it plain. The Deep did not come down, when will the Seventh be sung. And then again at midwinter.' He taps the sealed one. 'A young Cantor answered. The Remainders are a matter for the Cantors and not the locks.' He tries to smile. 'I thought perhaps it was a test. Of the keeper. To see if I'd keep watching.' He has kept watching.".
  }
  Topic piet_close with piet "Ask Piet whether he could close the Deep Gate himself" when true once {
    Says "'With what?' He shows you: no wheel, no chain, no pin, nothing to turn or pull. 'It's not a gate anybody works. It's a gate that works.' Then, reluctantly: 'There's the stop-logs. Oak beams, for when we dry a chamber to mend it. The crane can drop them in any slot in the Nine. Not the Deep, though. Never the Deep. Master Tarrant said never.' A pause. 'He didn't say why. He said never the high voice, too, and he didn't say why that either.'".
  }
  Relation pietWilling(group). Relation pietAfraid(group).
  Topic piet_logs with piet "Ask Piet to help drop the stop-logs in the Deep's mouth" when (warranted(actor) or knows(actor, hymn_cause)) and not pietWilling(piet) and state(deep_gate, raised) once {
    Says "Piet looks at you, and at the Gate, and back. 'If you're sure,' he says, and you can see what it costs him. 'If it's the Office saying so. Somebody has to say so who isn't me.' He goes to the crane. 'They're heavy. It wants the two of us and the crane, and the Gate won't like it.' He does not explain how he knows what the Gate will like.".
    On discuss { Assert pietWilling(piet). }
  }
  Topic piet_hymn_restored with piet "Ask Piet how it is now the Seventh is sung" when knows(actor, gate_falls_seen) once {
    Says "'It came down.' He says it as if it might not be true if he says it too loud. 'At the Seventh. I wrote it in the book. Down at the Seventh. Cupful.' He laughs, and wipes his face with his sleeve, not hiding it. 'I wrote it in capitals. Master Tarrant would have my ears for that.'".
  }

  // The stop-logs.
  Item lock_bar "a keeper's iron bar" is crowbar at ninth_lock.
  Thing crane "the stop-log crane" at ninth_lock {
    State idle "An oak crane on the lock wall stands over a stack of stop-logs, square black beams as long as a cart.".
  }
  Action drop_logs(actor: group, site: place) "Drop the stop-logs into the Deep Gate's mouth, with Piet and the crane" {
    Description "Jam the Deep Gate with oak, so it cannot draw. What the Gate's makers would think of it is another matter.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ninth_lock) and pietWilling(piet) and at(piet, ninth_lock)
      and (state(deep_gate, raised) or state(deep_gate, half)).
    Time 6.
    On success { Assert state(deep_gate, logged). Set loggedAt(bowl) to watch(clock). }
    Result "It takes an hour. The first log goes down into the eddy and is snatched against the bronze so hard the crane jumps. The second goes on top of it, and the third, and the fourth, and the water piles up behind them and goes over in a sheet, and the long breath of the Deep stops. In the silence you can hear the whole Stair above you. Then the bronze under the logs gives a single heave, and is still.".
  }
  Action drop_logs_alone(actor: group, site: place) "Drop the stop-logs into the Deep Gate's mouth with the crane" {
    Description "Without the keeper. It is heavy work, and he will see it done.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ninth_lock) and capable(actor, brawn) and not pietWilling(piet)
      and (state(deep_gate, raised) or state(deep_gate, half)).
    Time 9.
    On success { Assert state(deep_gate, logged). Set loggedAt(bowl) to watch(clock). Assert loggedAgainst(piet). }
    Result "It takes an hour and a half, and one of the logs swings on the crane and nearly takes your head. But they go down, one on another, until the long breath of the Deep stops. In the silence you can hear the whole Stair above you, and somebody behind you on the lock wall saying no, no, no.".
  }
  Relation loggedAgainst(group).
  Measure loggedAt(place).
  Action lift_logs(actor: group, site: place) "Lift the stop-logs out of the Deep Gate's mouth" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ninth_lock) and state(deep_gate, logged)
      and (pietWilling(piet) or capable(actor, brawn)).
    Time 6.
    On success { Assert state(deep_gate, raised). }
    Result "The logs come up one by one, streaming. Before the last is clear the bronze heaves up under it, and the Deep takes its long breath again.".
  }
  // A day and a night of the Deep starved, and the Equals come up the culvert in the small hours and take the logs out.
  Relation equalsRose(place).
  Rule equals_rise when state(deep_gate, logged) and watch(clock) >= loggedAt(bowl) + 108 and hour(clock) == 3 and not broken(reckoner)
    says "In the small hours there is a sound at the bottom of the Bowl like a cart of bells overturned, once, and then nothing. In the morning the Ward says the Ninth Lock is full of bronze men." {
    Assert state(deep_gate, raised). Assert equalsRose(ammerlin). Set loggedAt(bowl) to 0. }
  Observe equals_marks at ninth_lock when equalsRose(ammerlin) "The stop-logs lie on the lock wall in a neat stack, squared as if by a carpenter, with their ends dented in four places each, deep, by something that held them. The Deep Gate is up. Wet footprints too wide and too flat for any man's go from the hatch to the logs and back.".
  Topic piet_equals with piet "Ask Piet what came up out of the Deep" when equalsRose(ammerlin) once {
    Says "Piet has not slept. 'Two of them,' he says. 'Bronze. Like men if men were made by somebody who'd had men described to him.' He makes a shape with his hands, too broad. 'They came up the hatch. They didn't look at me. They took the logs out one in each hand like kindling and stacked them, very square, and went down again.' He swallows. 'They stacked them square. Why would they do that?'".
  }

  // The culvert beyond the gate: dry while the Deep is shut, and a death while it is open.
  Observe culvert_scene at intake_culvert when not familiar(intake_culvert) "A culvert of the fine grey stone, round as a pipe and tall as two men, going down at a steady slope into the dark. A thread of water runs along its floor. The walls are polished by three thousand years of water to the smoothness of the inside of a shell, and they hum, very faintly, all the time.".
  Observe culvert_scene_again at intake_culvert when familiar(intake_culvert) "The intake culvert, grey and humming, going down into the dark.".
  Hazard culvert_flood "The Deep's water" means "Deal (3d6) physical damage to ally unless strength save against (14).".
  Rule culvert_floods when at(party, intake_culvert) and (state(deep_gate, raised) or state(deep_gate, half)) and not complete(reckoner) and not broken(reckoner)
    says "Behind you, far up the culvert, the bronze of the Deep Gate rises with a sound like a held breath taken. Then the water comes. It comes down the culvert as a wall and takes you off your feet and down, down, along the grey stone, in the dark, and throws you out at the bottom." {
    Assert strikes(culvert_flood, party). Retract at(party, intake_culvert). Assert at(party, vestibule). }
}

data/adventures/low-water/lore.kyr:
Module lowwater "Low Water" {
  Description "Links outward from the Bowl: a black stair in a college read by Halm from afar, a Prefect's writ of keeping laid before him, a notice calling surveyors to a lighthouse, and the almanack woman.".

  // ── A world event, read: Halm hears of the square ───────────────────────────────────────────────────────────────
  Observe lore_taproom_square at taproom when befell(slack_opened) "A fat envelope with a Corran seal has been left against the Full Measure's tap by a carter who did not wait. Ruan Tell has read the outside, which is as far as he reads. 'For Teodor Halm,' he says. 'Third this month. They are all in the same hand, and all say the same thing in the corner: URGENT, THE SQUARE.'".
  Discovery lore_halm_square "Halm has heard from a fellow at the Collegium that a black square in the floor of a college at Sennet has been opened and a stair found under it. He says it is the same stone as the Reckoner, and that nobody has asked the Reckoner what it thinks.".
  Topic lore_halm_black with halm "Ask Halm what the letters from Corran say" when befell(slack_opened) once {
    Says "Halm has them fanned in one hand like cards. 'A square,' he says. 'Black. Let into a floor at Sennet, under a college that has been sitting on it for six hundred years and calling it a paving stone. They have opened it. There is a stair.' He is delighted and appalled in about equal parts. 'Dun Rì has always said the Aeneans built its engines. It is the Collegium's one article of faith. It is not true, and I have been saying so since I was twenty-five, and now a lot of people in good coats are standing on a floor and finding out. Nothing there is Aenean but the lettering.' He puts the letters down. 'I should like to go. I will not. I have a Reckoner.'".
    On discuss { Assert knows(actor, lore_halm_square). }
  }

  // ── A visitor from elsewhere: a writ of keeping ─────────────────────────────────────────────────────────────────
  Discovery lore_writ_kept "A fair copy of the Prefect's writ of keeping, shown to Halm, says KEPT where the Collegium's footnotes say owed. Halm believes the Collegium has been mistranslating one word for four hundred years.".
  Topic lore_halm_writ with halm "Show Halm the fair copy of the Prefect's writ" when holding(actor, prefects_writ) once {
    Says "Halm reads it standing, which he never does, and then sits down on the dig's wet edge. 'Servandam,' he says. 'Servandam, servandam. Not debendam.' He looks up with the wild patience of a man who has found his own mistake in someone else's handwriting. 'Every footnote in four hundred years of the Collegium says OWED. We have been turning custodire into debere because a copyist at Corran had a debtor's nerves. KEPT. Kept, not owed. It changes the hymn.' He hands the copy back at arm's length, as if it might go off. 'Who wrote this out? A woman in a chapel, you said? Tell her the Lesser Instruments collects things, and has just been shown it was holding the wrong thing for four hundred years.'".
    On discuss { Assert knows(actor, lore_writ_kept). }
  }

  // ── An entry point: a call for surveyors ────────────────────────────────────────────────────────────────────────
  Observe lore_measures_notice at measures_square when true "Pinned under the Office's lamp, in a printed hand: THE COLLEGIUM OF MEASURES AT SENNET WOULD HAVE SURVEYORS, CHAIN-BEARERS AND ANY HAND THAT CAN READ A FOOT-RULE AT THE PHAROS ON SKERROW, TO TAKE THE LAMP-ROOM TABLE. PASSAGE FROM TOLLETH ON THE PACKET DOROTHEA, SAILINGS CHALKED ON THE QUAY BOARD. APPLY TO MISTRESS ODILE QUINT. Under it a clerk has written, in pencil: the Registrar says this is not our Office. Someone else has written: it is the Office's foot.".

  // ── The almanack woman ──────────────────────────────────────────────────────────────────────────────────────────
  Discovery lore_cattermole_bowl "Jessamy Cattermole, who sells almanacks, left a wax rubbing for Halm from a church on the coast and has gone up to Merrowdale, where, she says, there is a notice offering forty crowns for a giant.".
  Topic lore_ruan_cattermole with ruan "Ask Ruan Tell who has been through lately with something to sell" when true once {
    Says "'Cattermole,' says Ruan. 'Five almanacks and a rubbing. All five say a different year and she sold the lot, so somebody in Ammerlin is eleven years late or twenty-two years early, and I do not like to ask which.' He wipes the bar. 'The rubbing was off a bench in a church by the sea, wax on rag, with notches on it like a gate-tally. She left it for Halm. Halm has not slept. She went on north to Merrowdale. She said there is a notice there: forty crowns, for a giant. She said, a pedlar can always do business where a giant is wanted.'".
    On discuss { Assert knows(actor, lore_cattermole_bowl). }
  }

  // ── Two papers from elsewhere ───────────────────────────────────────────────────────────────────────────────────
  Discovery lore_rubbing_halm "Halm, shown a rubbing of a keeper's tally from a church by the sea, finds in it the same stroke-and-ring his own notebook gives for the Reckoner's ninth column, and says the coast kept a count the Bowl called a debt.".
  Topic lore_halm_rubbing with halm "Show Halm the wax rubbing of a keeper's tally" when holding(actor, tally_rubbing) once {
    Says "Halm takes it by the corners, because he knows better than to touch a rubbing, and lays it on his knee. 'Three notations,' he says. 'The old, the ruled, and these.' His finger hovers over the stroke and the ring. 'This is the Reckoner's. Not like. Is. I have this very mark in the ninth column of the Nine, which the Office calls the Remainder and writes in red.' He sits back. 'The Bowl owed it. A church by the sea kept it. Two places counting the same sum for the opposite reason.' He looks at you, delighted and a little afraid. 'Where did you get this, and have they got more?'".
    On discuss { Assert knows(actor, lore_rubbing_halm). }
  }
  Discovery lore_surety_fenn "Registrar Fenn, shown the Ninth Valuer's note on a surety, reads it as a rule of her own Office stated with unusual honesty, and keeps a copy of the last clause.".
  Topic lore_fenn_surety with fenn "Show the Registrar the Ninth Valuer's note on a surety" when holding(actor, surety_terms) once {
    Says "Registrar Fenn reads it twice and puts the second reading in her face where you can see it. 'Answers for the keeping named,' she says, 'and where none is named, for all.' She takes a pen and a half-sheet and copies the last clause out in her own hand. 'I have been drafting the Office's liability for nine years and I could not have said it so well.' She blots the half-sheet, folds it, and puts it into her cuff where she keeps what she means to be asked about.".
    On discuss { Assert knows(actor, lore_surety_fenn). }
  }
}

data/adventures/low-water/measures.kyr:
Module lowwater "Low Water" {
  Description "Measures Terrace: the square, the Office of Measures and its Registrar, its ledgers and its oldest map, the Moot Hall, and the Full Measure.".


  Place measures_square "Measures Square" is room within ammerlin at 1, 1 outdoors.
  Place office "the Office of Measures" is building within ammerlin.
  Place office_hall "the hall of the Office" is room within office at 0, 0.
  Place registrar_room "the Registrar's room" is room within office at 1, 0.
  Place ledger_room "the ledger room" is room within office at 0, 1.
  Place moot_hall "the Moot Hall" is room within office at 1, 1.
  Place inn "the Full Measure" is building within ammerlin.
  Place taproom "the Full Measure's taproom" is room within inn at 0, 0.

  Passage first_stair "the Stair, from the Rim to Measures Terrace" is steps between rim_head and measures_square taking 15 minutes.
  Passage office_door "the Office door" is door between measures_square and office_hall.
  Passage registrar_door "the Registrar's door" is door between office_hall and registrar_room.
  Passage ledger_door "the ledger-room door" is door between office_hall and ledger_room.
  Passage moot_doors "the doors of the Moot Hall" is door between office_hall and moot_hall.
  Passage inn_door "the Full Measure's door" is door between measures_square and taproom.

  Observe square_scene at measures_square when not familiar(measures_square) "A square of wet flagstones on the second terrace, with the Office of Measures down one side, all grey ashlar and tall windows, and the Sounding up the other, its bell-tower over everything. In the middle a fountain: a bronze basin on a column, older than either building, brimming without a sound.".
  Observe square_scene_again at measures_square when familiar(measures_square) "Measures Square, the Office down one side and the Sounding up the other, and the old fountain brimming between them.".
  Observe fountain_hums at measures_square when starved(reckoner) "The fountain in the square is humming, low and steady, and the water in its basin stands up in fine rings.".
  Observe fountain_humming at measures_square when humming(ammerlin) "The fountain in the square is humming, low and steady, and children are standing round it with their hands on its rim, feeling it.".
  Observe fountain_still at measures_square when broken(reckoner) "The fountain in the square brims as it always has. Something about it has changed and it takes you a while to know what: the water in the basin no longer trembles, very faintly, as all the water in the Bowl did. It is only water now.".

  // The Office.
  Observe hall_scene at office_hall when not familiar(office_hall) "The hall of the Office of Measures: a long room of benches and a counter of black oak, where the people of Ammerlin come to have their rights read, registered, quarrelled over and sealed. Over the inner door, cut in letters a hand high: WHAT IS MEASURED HONESTLY CAN BE SETTLED PEACEFULLY.".
  Observe hall_scene_again at office_hall when familiar(office_hall) "The hall of the Office, under its words: WHAT IS MEASURED HONESTLY CAN BE SETTLED PEACEFULLY.".
  Observe hall_queue at office_hall when hour(clock) >= 8 and hour(clock) < 17 and not familiar(office_hall) "A queue of people with papers goes along the benches: carters, dyers, two women from the Ward with a child asleep across their knees. Nobody in it is talking to anybody else.".
  Person clerks "the Office clerks" at office_hall {
    Role "at work behind the counter". Ancestry human. Numbers 3. Peaceable.
  }
  Topic clerks_queue with clerks "Ask the clerks what the queue is waiting for" when true once {
    Says "'Rights,' says the nearest clerk, without looking up. 'Read, registered, quarrelled over, sealed. Same as every day.' He stamps a paper and passes it along. 'Only the quarrels don't stop at the counter any more. Everybody's right is a little less water than it was, and everybody wants it written down whose fault that is before the Hearing.' The clerk beside him says, to the ledger, 'Sixty-one in the queue yesterday. In my father's time a busy day was nine.'".
  }
  Topic clerks_water with clerks "Ask the clerks where the water goes" when true once {
    Says "'Ask Clerk Vant,' say two of them at once. The third, the eldest, sighs and draws a grey card from a box under the counter. 'Three hundred and twenty ells a day at the Rim Gauge. A fifth of it to the Guild's Channel, by grant, sealed. The rest down the Stair, lock by lock, every terrace its right by the hour, and what comes to the Mere is what is left.' He puts the card back. 'That is what is written. Whether it is what happens is what you are for.'".
  }
  Person fenn "Registrar Odile Fenn" at registrar_room {
    Greets "Registrar Fenn finishes the line she is writing, and blots it, and only then looks up.".
    Role "the head of the Office of Measures". Ancestry human. Peaceable. Pronouns she. Manner grim.
  }
  Observe registrar_scene at registrar_room when not familiar(registrar_room) "The Registrar's room is small and full of paper, stacked by terrace and tied with coloured tape. On the wall, a plan of the whole Stair in ink faded to brown. Registrar Fenn works standing, at a tall desk, and does not sit down for you.".
  Observe registrar_scene_again at registrar_room when familiar(registrar_room) "The Registrar's room: paper tied in coloured tape, and the brown plan of the Stair.".
  Discovery commission "The Office of Measures has engaged you as Independent Assessor: to find why the Mere is falling, and to give your Finding at the Hearing before the Council, at noon on the seventh day." { Known by fenn, isaura. }
  Topic fenn_commission with fenn "Ask the Registrar what she wants from you" when true once {
    Says "'A Finding,' says Registrar Fenn, writing. 'In writing, sealed, delivered at the Hearing at noon on the seventh day, which the Council has set and which I cannot move. A cause, and a remedy. You are an outsider, which is the point of you: nobody in this city can say why the Mere is falling without being accused of wanting somebody's water.' She looks up for the first time. 'Clerk Vant will go with you and open what you need opened. Find me something I can put in front of the Council that will still be standing at the end of the afternoon.' She counts twenty crowns out of a drawer for your expenses, and has you sign for them.".
    On discuss { Assert knows(actor, commission). Increase quantity(actor, gold) by 20. }
  }
  Topic fenn_culprit with fenn "Ask the Registrar what she believes" when true once {
    Says "'I believe the Guild's Channel takes a fifth of the Ninefold, which it does, and that the Mere is falling, which it is, and that the Council will want those two facts in one sentence.' She lays down the pen. 'I also believe that I have been Registrar for eleven years and never once seen a cause that was only one thing. That belief I can't put in front of the Council, so you will have to.'".
  }
  Topic fenn_office with fenn "Ask the Registrar about the words over the door" when true once {
    Says "'The Thirst Riots,' she says. 'Two hundred years ago. A dry summer and every terrace at every other's sluices with knives. Three hundred dead, most of them in the Ward, because the Ward is at the bottom and water runs downhill and so does a riot.' She taps the brown plan of the Stair. 'The Office was the peace. Every right measured, written, sealed, and read aloud at need. It works. It has worked for two hundred years.' A pause. 'It works as long as everybody believes the measuring. When they stop, the words over the door are a very expensive piece of stone.'".
  }
  Topic fenn_vant with fenn "Ask the Registrar about Clerk Vant" when true once {
    Says "'The best measurer in the Office,' says Fenn at once, 'and the worst politician. She'll tell you the truth to the half-ell and then wonder why you're angry with her.' She is quiet for a moment. 'Her brother is Dov Vant. The Ward. You'll meet him. Everybody does, sooner or later, usually at a volume.'".
  }
  // The Registrar can be shown cause to put off the Hearing, or to freeze the Ward's titles, and can give a warrant.
  Relation titlesFrozen(place). Relation postponed(place). Relation warranted(group).
  Topic fenn_freeze with fenn "Ask the Registrar to freeze the Ward's titles until the Finding" when knows(actor, ward_bought) and not titlesFrozen(ammerlin) once {
    Says "Registrar Fenn listens, and takes a fresh sheet without a word, and writes. 'An order of the Office: no title in the Mere Ward to pass between hands until the Assessor's Finding is read. Grounds: the value of the land depends on the matter under assessment.' She seals it. 'Master Quill will be very charming to me about this at the Council. Let him.' To a clerk, through the door: 'To Basset, at the Ward, by hand, now.'".
    On discuss { Assert titlesFrozen(ammerlin). }
  }
  Topic fenn_postpone with fenn "Ask the Registrar to put the Hearing off two days" when (knows(actor, hymn_cause) or knows(actor, engine_seen)) and not postponed(ammerlin) and watch(clock) < hearingAt(bowl) - 36 once {
    Says "'The Council set the day, not I.' But she does not say no. She listens to the end and then stands at the brown plan of the Stair with one finger on the Ninth Lock. 'If what you say is so, a Finding on the seventh day would be wrong, and a wrong Finding from this Office is worse than none.' She writes. 'I will ask them for two days. I will get them, because I have never asked before.' She seals it. 'Do not make me sorry.'".
    On discuss { Assert postponed(ammerlin). Increase hearingAt(bowl) by 288. }
  }
  Topic fenn_warrant with fenn "Ask the Registrar for a warrant over the Ninth Lock" when knows(actor, letters_read) and not warranted(actor) once {
    Says "'The Ninth Lock is a Sounding post, not ours. The Cantor appoints its keeper.' She thinks. 'But every sluice in the Bowl is under the Office in an emergency, by the charter of the Riots, and I suppose this is one.' She writes it out in her own hand: the bearer may order any keeper in the Bowl to open or close any gate, in the name of the Office, until the Finding. 'Clerk Vant will carry it. She will know when not to use it.'".
    On discuss { Assert warranted(actor). }
  }

  // The ledger room: the Office's long memory of the Mere, and its oldest map.
  Observe ledger_scene at ledger_room when not familiar(ledger_room) "Shelves to the ceiling of bound ledgers, a ladder on a rail, a long table worn hollow by elbows. The oldest books are at the top and smell of mice; the newest are at the bottom and smell of ink.".
  Observe ledger_scene_again at ledger_room when familiar(ledger_room) "The ledger room, two hundred years of the Bowl's water on its shelves.".
  Discovery fall_dated "The Office's register of the Mere gauge shows the Mere steady for two hundred years, within a span or two. It begins to fall in the autumn three years ago, and has not stopped." {
    Source register_book "the register of the Mere gauge" at ledger_room readable by party.
  }
  Discovery feeder_known "The Office's oldest map shows a course from the channel head at the Rim, under the terraces, straight to the Ninth Lock: the Grey Way, marked in a hand older than the Office: TO FEED THE DEEP WHEN THE MERE IS LOW.".
  Thing old_map "the oldest map of the Bowl" at ledger_room {
    State rolled "In a case on the top shelf lies a map so old it has been backed with linen twice.".
    Tries looking.
  }
  Rule map_read when tried(old_map, looking) and not knows(party, feeder_known)
    says "You unroll it on the long table, weighting the corners with ledgers. The Bowl as it was before the Office: the same terraces, the same Stair, and one thing more. From the channel head at the Rim, a grey line goes straight down under the terraces to the Ninth Lock, missing the Mere altogether. Beside it, in a hand older than the Office's: TO FEED THE DEEP WHEN THE MERE IS LOW." teaches feeder_known { }
  // The Full Measure, where carters and Assessors sleep.
  Observe taproom_scene at taproom when not familiar(taproom) "The Full Measure: low beams, a fire, carters' boots, and on every table a pewter measure-jug stamped by the Office, so that nobody can say they were given short.".
  Observe taproom_scene_again at taproom when familiar(taproom) "The Full Measure: carters' boots to the fire, wet rings on every table, and every jug stamped by the Office and every drinker watching his own.".
  Person ruan "Ruan Tell" at taproom {
    Greets "Ruan Tell has a jug in one hand and a cloth in the other, and puts down neither.".
    Role "the keeper of the Full Measure". Ancestry human. Profession innkeeper. Peaceable. Pronouns he. Manner jovial.
    Sells rations for 2 coin from 8.
    Sells lamp_oil for 1 coin from 4.
    Sells torch for 1 coin from 6.
    Sells lantern for 4 coin from 2.
    Sells rope for 2 coin from 2.
  }
  Topic ruan_talk with ruan "Ask Ruan Tell what people are saying" when true once {
    Says "'Saying?' Ruan polishes a measure-jug. 'Carters say it's the drought in the hills, and there's no drought, I've a cousin in the hills. Dyers say it's the Guild. The Guild says it's the drought. The Ward says it's everybody. And the old Cantors say it's the Sounding, for cutting the Hymn, which is the only theory I've heard that's cheap to fix.' He laughs. 'Nobody listens to the old Cantors. They also said it about the new bells.'".
  }
  // What the taproom says changes with what happens: Ruan has it all by evening.
  Topic ruan_tench with ruan "Ask Ruan Tell what the Ward is saying about Dov Vant's boat" when state(tench, stranded) once {
    Says "'That the Tench is on the mud and Dov sat in her all night with a bottle,' says Ruan. 'His father's boat. The Ward's taking it hard. When the last boat goes, they say, the Ward's a street, not a shore.' He sets a jug down. 'Dov says he'll dig her a channel to the water if it takes him to Candlemas. Somebody told him the water would be further off by Candlemas. That's how the fight started.'".
  }
  Topic ruan_clash with ruan "Ask Ruan Tell about the fight at the dig" when clashed(dig) and dovHeld(dov) once {
    Says "Ruan's face goes flat. 'Guild bailiffs and fishers with shovels. Two men cut, and Dov Vant in the Office cells, and the Guild's rope round the dig.' He polishes a jug that does not need it. 'There's talk in the Ward. Not the kind I like to hear in my house. The Ward hasn't forgotten the Riots, and the Riots started with a sluice and a rope just like that one.'".
  }
  Topic ruan_drowned with ruan "Ask Ruan Tell what is being said about the breach" when drowned(diggers) once {
    Says "'Hob Kettle and his girl and Jory Pale.' Ruan does not polish anything. 'Annet used to come in for her father's ale and drink the head off it on the way home and he never once said a word.' He looks at the fire. 'They're saying the Office knew. That there was a clerk who'd measured it. I don't know where they get that.' He looks at you. 'Do you?'".
  }
  Topic ruan_bells with ruan "Ask Ruan Tell what people made of the bells" when complete(reckoner) once {
    Says "'Every bell in the Bowl, and nobody pulling. My cellar rang like a cart of pans. The carters' horses broke their tethers on the Rim.' He sets down a measure-jug very carefully, as if it might start ringing too. 'Precentor Penhale was in here at dawn saying the dead had risen. Then the Ward came in saying the Mere had gone down six spans in a breath, and Penhale went quiet, and had a brandy, which he never does.'".
  }
  Topic ruan_hum with ruan "Ask Ruan Tell about the fountains" when humming(ammerlin) or fifthRestored(bowl) once {
    Says "'Purring.' Ruan laughs, delighted. 'My grandmother's word. The square fountain, and the one in my yard, and the trough on the Rim: humming like a cat at the Fifth, the way they did when she was young. Half my regulars have gone out to put their hands on them.' He lowers his voice. 'Old Abel Tarrant stood by the square fountain with his hand on it and wept. Don't tell him I said.'".
  }
  Topic ruan_hearing with ruan "Ask Ruan Tell what the city is saying about the Hearing" when hearingDone(ammerlin) once {
    Says "'Depends who you ask and how much they've had.' Ruan counts on his fingers. 'The Ward says it was the Office finally being honest. The Rim says it was the Office finally being clever. The Sounding says nothing, very loudly. The carters say it's all one to them as long as the Stair runs.' He grins. 'And everybody says that Clerk Vant read her figures out in front of the Council like a woman reading a will, and nobody dared cough.'".
  }
  Topic ruan_halm with ruan "Ask Ruan Tell about the scholar staying here" when true once {
    Says "'Master Halm. From the Collegium, wherever that is. Pays in advance, eats standing up, comes in covered in Mere mud at all hours and talks to my fire about the Mathematical Age.' He shrugs. 'Good lodger. Bad for the carpets. He's down at the Ward dig with Dov Vant most days, buying stones.'".
  }

  // The Moot Hall, where the Council sits for the Hearing.
  Observe moot_scene at moot_hall when not hearingDay() "The Moot Hall: a high room with tiers of benches on three sides and a table on the fourth under the Office's seal. Empty, it echoes.".
  Observe moot_filling at moot_hall when hearingDay() and not hearingOpen(ammerlin) and not hearingDone(ammerlin) "The Moot Hall is being made ready for the Hearing: clerks setting out ink and sand on the long table, the benches being wiped, a boy on a ladder trimming the lamps. People have begun to come in already and sit, early, the way people do who mean to have a good seat for something.".
  Observe moot_after at moot_hall when hearingDone(ammerlin) and not hearingOpen(ammerlin) "The Moot Hall is empty again, the benches pushed crooked, the ink-pots on the long table dry. Somebody has left a blue dyer's glove on the front bench.".
}

data/adventures/low-water/placed.kyr:
Module lowwater "Low Water" {
  // The Bowl as a country beyond a march: the company that comes over the Rim is the world's own.
  Entity party: group "Your company".
  // The Founders' Exchange, when the world holds a factor of it in the country behind the Rim: its carter's lots go
  // south to the Collegium, which pays double for bronze that rings. A lot of bell-teeth in the carter's keeping,
  // once the carter has gone (the Exchange says so in the world, not here), is in Halm's by the time the company
  // has crossed the Rim, to be shown, rung, and wondered at. It is the same lot, from the same wall; it is not made
  // here. If the company has bought the lot back or the carter never went, the tray is empty.
  Entity ring: group "The Founders' Exchange.".
  Entity carter: group "The carter of the Founders' Exchange.".
  Place south_road "The south road, past the Exchange's yard" is room.
  Rule halm_buys_lot when keeps(carter, ?t) and itemKind(?t, bell_teeth) and at(carter, south_road) {
    Retract keeps(carter, ?t). Assert keeps(halm, ?t). Assert fromExchange(?t).
  }
  Relation fromExchange(item).
  // What the company finds at the dig when the Exchange's lot has come: a thing on a cloth, and Halm's account of it. The
  // lot is only here if the carter brought it; nothing else writes this.
  Relation exchangeLot().
  Rule exchange_lot_noted when keeps(halm, ?t) and fromExchange(?t) and not exchangeLot() { Assert exchangeLot(). }
  Observe halm_tray at dig when exchangeLot() "Apart from the day's finds, on a clean cloth, lie twelve teeth of green bronze, each the shape of a small bell, laid out in a row by someone who has rung every one. Beside them a sack with a tin tag, in a factor's hand: NORTH.".
  Topic halm_tray_ask with halm "Ask Halm where the bell-teeth on the cloth came from" when exchangeLot() once {
    Says "'A cart,' says Halm, without looking round from the tray. 'Last week, from a Founders' Exchange in the north, a factor who buys by the pound and sells to the Collegium by the ring. They always have the stuff that rings.' He picks up a tooth and flicks it; the note goes on and on. 'Twelve. Each a voice, each pitched to the next. They come out of a wheel, and a wheel with twelve teeth missing is a wheel that has stopped doing something.' He puts it down very carefully. 'I paid double. I paid for it. I'd like, if you have any idea where the wheel is, to have it back where it belongs, and to have never been paid for it.'".
  }
  Observe halm_bare_cloth at dig when routed(ring) and not exchangeLot() "On a clean cloth at the edge of the dig, laid out and left, there is nothing. A tin tag lies on it, with NORTH on it in a factor's hand, and no sack.".
  Topic halm_bare_ask with halm "Ask Halm about the empty cloth" when routed(ring) and not exchangeLot() once {
    Says "'The lots have stopped,' says Halm, in the voice of a man at a funeral. 'The Exchange's carter came down every month for three years. Bell-metal, a tooth, a face. It was never much, and it was never the same twice, and it was the only reason the Collegium knew anything was still being found in the north.' He puts the tag down. 'Somebody did something. I don't know what. I don't know whether to thank them.'".
  }
  // What is said of the Bowl in the country behind it: once the Office has given its verdict or the count has closed, the rumour of a falling lake and a hired stranger is old news there, told by what the Office decided.
  Entity word: fact "What is said of the Bowl of Ammerlin in the country behind it.".
  Entity word_accord: fact "What is said there of the Office's verdict.".
  Entity word_false: fact "What is said there of the count.".
  Rule word_old when (verdictAccord(ammerlin) or verdictGuild(ammerlin) or verdictSeventh(ammerlin) or verdictBreak(ammerlin)
    or verdictFeed(ammerlin) or complete(reckoner) or heartGiven(party) or auditSent(party) or longWatch(party)) and not stale(word) { Assert stale(word). }
  Rule word_accord_old when verdictAccord(ammerlin) and not stale(word_accord) { Assert stale(word_accord). }
  Rule word_false_old when countFalsified(reckoner) and not stale(word_false) { Assert stale(word_false). }
}

data/adventures/low-water/rim.kyr:
Module lowwater "Low Water" {
  Description "The Rim of the Bowl: the north road's end, the head of the Stair, the Rim Gauge where the Ninefold comes in, the Fulling Channel, the mills, and Harrow Quill's counting-house.".


  Place rim_road "the north road, at the Rim" is room within ammerlin at 0, 0 outdoors.
  Place rim_head "the head of the Stair" is room within ammerlin at 1, 0 outdoors.
  Place rim_gauge "the Rim Gauge" is room within ammerlin at 2, 0 outdoors.
  Place fulling_mills "the fulling mills" is room within ammerlin at 3, 0 outdoors.
  Place counting_house "the Guild counting-house" is building within ammerlin.
  Place quill_outer "the counting-house floor" is room within counting_house at 0, 0.
  Place quill_room "Harrow Quill's counting-room" is room within counting_house at 1, 0.

  Passage rim_gate "the Rim gate" is gate between rim_road and rim_head.
  Passage gauge_walk "the walk along the Rim" is path between rim_head and rim_gauge taking 10 minutes.
  Passage channel_walk "the Channel towpath" is path between rim_gauge and fulling_mills taking 10 minutes.
  Passage counting_door "the counting-house door" is door between fulling_mills and quill_outer.
  Passage quill_door "the door to the counting-room" is door between quill_outer and quill_room.

  Observe road_first at rim_road when not been(party, rim_head) "The road comes over the lip of the Bowl and stops, because the world does. Below you the city goes down in four great steps, each a ring of roofs and gardens and wet stone, and between the rings the water: falling, turning, held. You can hear it before you understand it, a sound like a great many people breathing out. At the bottom, very far, the Mere lies like a coin somebody dropped. There is a pale ring round it. It takes you a moment to see that the ring is mud.".
  Observe road_scene at rim_road when been(party, rim_head) "The north road ends at a gate in a low wall, and past the gate the ground goes out from under the world. Carters water their horses at a trough fed by a bronze spout older than the wall.".
  Observe road_low at rim_road when been(party, rim_head) and mere(bowl) <= 30 "From the Rim the ring of mud round the Mere is wider than the water now, grey, with things standing up in it.".

  Observe head_scene at rim_head when not familiar(rim_head) "The head of the Stair: a stone landing the size of a market, where the Ninefold, brought along the Rim in a cut channel, drops into the first of the Nine Locks and goes down the Bowl in steps of white water. Stairs for people go down beside it. The spray makes a rainbow over the first lock at this hour and a cold mist at every other.".
  Observe head_scene_again at rim_head when familiar(rim_head) "The head of the Stair, loud with the Ninefold going over into the first lock.".
  Observe head_spray at rim_head when hour(clock) >= 7 and hour(clock) < 11 and not familiar(rim_head) "The rainbow hangs over the first lock, so steady the carters use it to tell the time.".

  // The Rim Gauge: where the Ninefold comes in, and where the Guild took its fifth.
  Observe gauge_scene at rim_gauge when not familiar(rim_gauge) "The Ninefold comes into the Bowl here, out of a cutting in the Rim, over a weir of dressed stone with a brass gauge-plate let into it. Past the weir the water splits at a stone head with three mouths: one down to the head of the Stair, one along the Rim in a new brick channel toward the sound of hammers, and one, the oldest, bricked up with stone so old it has gone green.".
  Observe gauge_scene_again at rim_gauge when familiar(rim_gauge) "The Rim Gauge: the weir, the brass plate, and the channel head with its three mouths.".
  Observe gauge_plate at rim_gauge when true "The brass plate on the weir is cut with the Office's marks, ells-per-day, and stamped with its seal. The water stands on it at three hundred and twenty.".
  Discovery feeder_seen "At the Rim Gauge the channel head has a third mouth, the oldest, bricked up: a course that once went somewhere else than the Stair or the mills.".
  Rule third_mouth at rim_gauge when at(party, rim_gauge) and not knows(party, feeder_seen) says "The third mouth of the channel head is the strangest. The brick that stops it is a later patch on far older work: the arch round it is cut in a stone you have not seen anywhere else in the Bowl, grey, fine, with no tool marks at all." teaches feeder_seen { }

  Thing channel_gate "the channel head" at rim_gauge {
    State to_mills "The channel head is set to the Guild's brick channel: a fifth of the Ninefold goes along the Rim to the mills, and the rest down the Stair.".
    State to_mere "The channel head is set as it was before the Guild: all of the Ninefold goes down the Stair to the Mere, and the brick channel to the mills is a dry ditch.".
    State to_deep "The old third mouth stands open, its patch broken out. A fifth of the Ninefold goes into it and away under the Rim with a hollow roar, toward the Ninth Lock by some way that is not the Stair.".
  }
  Thing guild_chain "the Guild's chain on the channel head" at rim_gauge {
    State padlocked "A chain as thick as a wrist holds the channel head's wheel, padlocked, with a tin plate on it: MILLWRIGHTS' GUILD. BY CHARTER.".
    State cut "The Guild's chain hangs in two pieces from the channel head's wheel.".
    State unlocked "The Guild's chain hangs loose from the channel head's wheel, its padlock open.".
    Change cut "Break the Guild's chain off the channel head" from padlocked to cut needing crowbar.
  }
  Relation measured(entity). Relation channelLicensed(group). Relation feederLicensed(group).
  Discovery channel_measured "The Fulling Channel takes twenty-two ells a day from the Ninefold. Isaura measured it twice, with the same result.".
  Action measure_channel(actor: group, site: place) "Gauge the Fulling Channel's draw, with Isaura's rod" {
    Description "Isaura sounds the brick channel at three places with the brass ell-rod and works the sum.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, rim_gauge) and travelsWith(isaura, actor) and not measured(channel_gate).
    Time 3.
    On success { Assert measured(channel_gate). }
    Result "Isaura goes down on one knee on the wet brick and puts the ell-rod into the Channel at its head, at its middle, and at the bend, and each time reads it, and each time writes. She works the sum on her knee with the graphite. 'Twenty-two,' she says. 'Twenty-two ells and a half, if I'm generous to them, which I'm not.' She does it again, from the beginning. 'Twenty-two.'".
  }
  Rule channel_known when measured(channel_gate) and not knows(party, channel_measured) says "Isaura closes her ledger on the figure: twenty-two ells a day." teaches channel_measured { }

  // Turning the head: by right (the Guild's leave, or the Hearing's order), or by force.
  Action restore_channel(actor: group, site: place) "Turn the channel head back into the Ninefold's course" {
    Description "Send all of the Ninefold down the Stair to the Mere, as it went before the Guild.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, rim_gauge) and not state(channel_gate, to_mere)
      and (state(guild_chain, cut) or state(guild_chain, unlocked)).
    Time 2.
    On success { Assert state(channel_gate, to_mere). Assert turnedBy(channel_gate, actor). }
    Result "The wheel is stiff, and then it is not. The brick channel to the mills chokes and empties, the Stair's white water thickens, and along the Rim the hammers of the mills go one by one out of time, and stop.".
  }
  Action feed_deep(actor: group, site: place) "Break out the old third mouth and send the Channel's water down it" {
    Description "The oldest course, toward the Ninth Lock and the Deep, past the Mere.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, rim_gauge) and knows(actor, feeder_known)
      and not state(channel_gate, to_deep) and (state(guild_chain, cut) or state(guild_chain, unlocked)).
    Time 3.
    On success { Assert state(channel_gate, to_deep). Assert turnedBy(channel_gate, actor). }
    Result "The patch comes out brick by brick, soft with age, and behind it the old grey arch goes on into the Rim, dry as a throat. You turn the wheel. The Channel's water leaves the brick for the grey stone as if it had always been waiting to, and goes in under the Rim with a hollow roar, and somewhere far below you, in the floor of the Bowl, something answers it with a long deep note.".
  }
  Action close_channel_head(actor: group, site: place) "Set the channel head back to the Guild's channel" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, rim_gauge) and not state(channel_gate, to_mills)
      and (state(guild_chain, cut) or state(guild_chain, unlocked)).
    Time 2.
    On success { Assert state(channel_gate, to_mills). }
    Result "The wheel goes round. The brick channel fills again, and along the Rim, after a while, the hammers start.".
  }
  Relation turnedBy(entity, group).

  // The mills, and the people whose work the Channel is.
  Observe mills_scene at fulling_mills when state(channel_gate, to_mills) "Eight new mill-houses of yellow brick stand along the Channel with their wheels turning and their hammers going, and the whole Rim shakes with it. Wet cloth hangs from frames in long red and blue banners. Four hundred people work here, more or less; the more is in the morning.".
  Observe mills_idle at fulling_mills when not state(channel_gate, to_mills) "The mill wheels stand still in an empty channel. The hammers are up. Cloth hangs half-fulled on the frames, and the mill hands stand about in the lanes in groups, not talking much, looking toward the counting-house.".
  Person sella "Sella Quenby" at fulling_mills {
    Greets "Sella Quenby looks round from the hammers and does not stop watching them with the side of her face.".
    Role "forewoman of the fulling mills". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
  }
  Person hands "the mill hands" at fulling_mills {
    Role "fullers and shearers of the Guild mills". Ancestry human. Numbers 6. Peaceable.
  }
  Discovery guild_unpaid "The Guild has not paid its mill hands since Lammas. Sella Quenby says Quill has sworn they will be paid when the charter is renewed." { Known by sella. }
  Discovery engineers_report "Quill's own engineers measured the Fulling Channel the summer it was cut, and wrote that it could not account for the Mere's fall: it takes too little. Quill has the report." { Known by sella. }
  Topic sella_work with sella "Ask Sella Quenby about the mills" when true once {
    Says "'What about them?' Sella does not stop watching the hammers. 'Eight houses, four hundred hands, three shifts when there's orders. Cloth for half the north. Two years ago there were forty people here and a ruined farm.' She points with her chin at the brick channel. 'That's what water's for. Ask anybody who's been hungry.'".
  }
  Topic sella_wages with sella "Ask Sella when the hands were last paid" when true once {
    Says "That makes her look at you. 'Who told you to ask that?' Nobody. She lets out a breath. 'Lammas. Not since Lammas. Master Quill says the charter comes up at the Council and once it's renewed the money's there, the creditors are waiting on it same as us.' She shrugs, hard. 'Four hundred people waiting on a vote. Don't write that down.'".
    On discuss { Assert knows(actor, guild_unpaid). }
  }
  Topic sella_channel with sella "Ask Sella whether the Channel is draining the Mere" when knows(actor, channel_measured) once {
    Says "'No,' she says, straight off, and then: 'Not like they say. Look, I was here the summer it was cut. Two engineers came up from Corran with a chain and a level, Quill paid them a fortune. They measured it every way there is. I carried their stakes.' She lowers her voice. 'They wrote it down. Twenty-two ells, they said, and the Mere's falling sixty, and the one can't be the other. Quill's got their report in his strongbox. He never showed it anybody. Why would he? Everybody blaming the Channel keeps everybody from asking where the rest's going.'".
    On discuss { Assert knows(actor, engineers_report). }
  }
  Relation promised(group, group).
  Topic sella_report with sella "Ask Sella if she could get the engineers' report out of the strongbox" when knows(actor, engineers_report) and not promised(actor, sella) once {
    Says "'And lose my place?' But she is thinking about it. 'I've a key to the strongbox; I do the wages, when there are wages.' She looks at the hands in the lanes. 'Here's my price. At the Council you stand up and you say four hundred people haven't been paid since Lammas, and you say it before anything else. Whatever else you find. Promise me that and I'll have the copy on the bench by the door for you within the hour.'".
  }
  Topic sella_promise with sella "Promise Sella you will speak for the mill hands at the Hearing" when knows(actor, engineers_report) and not promised(actor, sella) {
    Says "Sella looks at you a long while, then nods once. 'Within the hour,' she says, and goes into the counting-house by the side door, jingling.".
    On discuss { Assert promised(actor, sella). Set reportAt(sella) to watch(clock) + 5. }
  }
  Measure reportAt(group).
  Kind engineers_copy "the Corran engineers' report on the Fulling Channel" is treasure worth 0 weighing 0 described "Eleven pages in a good clerk's hand, with a drawing of the channel head and columns of figures. On the last page, underlined twice: THE CHANNEL AS CUT CANNOT ACCOUNT FOR ONE PART IN THREE OF THE FALL OBSERVED IN THE MERE. Signed by two engineers of Corran, and countersigned by H. Quill, Master.".
  Thing strongbox "the Guild strongbox" at quill_room {
    Holds.
    State locked closed "An iron strongbox stands under the window, locked, with the Guild's seal on its lid.".
    State open "The Guild strongbox stands open.".
    Change pick "Pick the strongbox's lock" from locked to open needing lockwork.
  }
  Item report "the engineers' report" is engineers_copy in strongbox owned by quill.
  Item report_copy "Sella's copy of the engineers' report" is engineers_copy in strongbox.
  Rule report_brought at fulling_mills when promised(party, sella) and reportAt(sella) > 0 and watch(clock) >= reportAt(sella) and not broughtOut(report_copy)
    says "Sella Quenby comes out of the counting-house's side door, puts a fat fold of paper on the bench by the door under a stone, and goes back to the hammers without looking at you." {
    Retract inside(report_copy, strongbox). Assert at(report_copy, fulling_mills). Assert broughtOut(report_copy). }
  Relation broughtOut(item).
  Observe report_waiting at fulling_mills when at(report_copy, fulling_mills) "On the bench by the counting-house door, under a stone, lies a fat fold of paper with a Corran seal.".

  // Harrow Quill, Master of the Millwrights' Guild.
  Observe outer_scene at quill_outer when not familiar(quill_outer) "A long room of clerks at high desks, each with a candle and a ledger, under a painted ceiling of the Ninefold coming down from the hills as a woman pouring a jar. The clerks look up at you all at once, and down again all at once, like birds.".
  Observe outer_scene_again at quill_outer when familiar(quill_outer) "The counting-house floor: clerks at their high desks under the painted Ninefold.".
  Observe quill_scene at quill_room when true "A counting-room with good windows over the Rim and the whole Bowl. Maps of the terraces cover one wall, the Ward's plots on them marked in red ink, a good many of them. A tray with a decanter and three glasses, as if visitors were expected and welcome.".
  Person quill "Harrow Quill" at quill_room {
    Greets "Harrow Quill rises, smiling, as if you were the one person in the Bowl he had hoped to see this morning.".
    Role "the Master of the Millwrights' Guild". Ancestry human. Peaceable. Pronouns he. Manner jovial.
  }
  Person bailiffs "the Guild's bailiffs" at quill_outer {
    Role "three big men in green coats". Ancestry human. Calling warrior. Level 2. Numbers 3.
    Temperament territorial.
    Warns "The biggest of the bailiffs steps in front of you and lets his cudgel hang where you can see it. 'Guild ground,' he says. 'Off it.'".
    Comes "The bailiffs come at you all three together, the way men do who have done it before.".
    Flinches "The bailiffs back off, cudgels up, and go for help.".
  }
  Initially Assert tolerates(bailiffs, party).
  Initially Assert serves(bailiffs, quill). Initially Assert keyholder(quill, guild_chain).
  Topic quill_side with quill "Ask Harrow Quill for his side of it" when true once {
    Says "'Sit, Assessor, sit. You'll want to hear my side and I'll want you to have heard it, so let's be efficient.' He pours three glasses and drinks one. 'Twenty-two ells. That's what my Channel takes, or near enough; your clerk will have it to the half-ell, I admire her enormously. Twenty-two ells, bought fairly from farms that were dying, and with it four hundred people have work who had none. The Mere has fallen sixty ells' depth in three years. Do the sum. I am a sliver of your problem. I am the sliver you can see, and so I'm the sliver everyone would like to cut out.'".
  }
  Topic quill_why with quill "Ask Quill why the Mere is falling, then" when true once {
    Says "'Drought,' he says. 'In the hills. The Ninefold's been low three summers running; ask any carter.' He spreads his hands. 'The Bowl has always had good years and bad. My grandfather used to say the Mere breathed: a hundred years in, a hundred out. We are in the out. We will be in the in again. Meanwhile, should four hundred people starve so the fish can have their pond back?' He smiles. 'That's rhetoric. I apologise. I was trained to it, and it's a habit, like a limp.'".
  }
  Topic quill_ward with quill "Ask Quill about the red ink on the Ward map" when true once {
    Says "'Oh, good. You've done more than walk around.' He is delighted. 'Yes. I'm buying it, plot by plot, through Basset. Somebody has to. When the Mere's down, and it's going down, Assessor, it's been going since before either of us drew breath, it's only faster now, that land will be the richest in Ammerlin. There are Aenean temples under it. Do you want them looted by fishermen with shovels, or dug properly, with wages?' He taps the map. 'Those are the only choices anyone's paying for.'".
  }
  Topic quill_good with quill "Ask Quill what he thinks water is for" when true once {
    Says "'For?' He likes the question; he sits back. 'Everything. That's the difficulty. Water is the one thing every use of everything needs, so every use quarrels over it. The Office pretends the quarrel is settled by measuring, but measuring only tells you how much there is to quarrel about.' He turns his glass. 'I say it goes where it does the most good, and the most good can be counted: in cloth, in wages, in bread. The Ward says it goes where it has always gone. That's not an argument, Assessor. That's a habit with a grievance.' A pause. 'Though I grant you a habit with a grievance has won more elections than any argument I ever made.'".
  }
  Topic quill_many with quill "Ask Quill whether the most good of the many is the good of anyone" when knows(actor, guild_unpaid) once {
    Says "He laughs, really laughs. 'You've been talking to Sella.' He puts the glass down. 'Yes, all right. The good of the many is a sum, and a sum is nobody's. Four hundred wages are four hundred suppers, and they're also a figure in a ledger I'm three quarters of a year behind on.' For a moment he looks his age. 'I overbuilt. Eight houses where five would have done. If the charter's renewed the creditors wait, and the hands are paid by spring. If it isn't, the Guild is a ruin by Candlemas and so are four hundred suppers. So when I tell you the Channel is a sliver, I'm telling you the truth, and I'm also telling you what I need to be true. I'd like you to remember both.'".
  }
  Topic quill_report with quill "Tell Quill you know what his engineers wrote" when knows(actor, engineers_report) once {
    Says "Quill is quiet a moment. Then he gets up, goes to the strongbox, and does not open it; he stands with his hand on it. 'Sella,' he says, not to you. 'Well.' He turns. 'Yes. They wrote that the Channel can't be a third of it. I didn't publish it because the city was going to blame somebody, and if not me then somebody worse placed: the Ward, the Sounding, the Office. I am well placed to be blamed. I have lawyers.' He sits again. 'And because I hoped it was drought. It's not, is it. You know what it is.' He looks at you very directly. 'If you know where the rest is going, Assessor, I'll deal. I'm a reasonable man with a great many debts.'".
    On discuss { Assert conceded(quill). }
  }
  Relation conceded(group).
  Topic quill_engine with quill "Tell Quill there is a working machine under the Mere, and what it drinks" when knows(actor, engine_seen) and not quillDeal(quill) once {
    Says "Quill listens to all of it without a word, which you have not seen him do before. 'A machine,' he says at last, 'that drinks a river, and has for three thousand years, and makes nothing anyone can see.' He gets up and looks at the Bowl from his window. 'You know what I hear? I hear that there's a way under the Rim that goes straight to it. That the old ones fed it from up here, past the Mere.' He turns round. 'My Channel could feed it. A few days of my water and it has what it wants, and the Mere keeps the rest. My mills would stand idle. Idle mills I can bear for a week, Assessor, if at the end of the week the city owes me something.'".
    On discuss { Assert offered(quill, actor). }
  }
  Relation offered(group, group). Relation quillDeal(group).
  Topic quill_terms with quill "Ask Quill what the city would owe him" when offered(quill, actor) and not quillDeal(quill) once {
    Says "'The dig,' he says at once. 'The Ward plots I hold, confirmed, and the Aenean land under them, by the Office's seal. And the charter renewed, with your Finding saying in so many words that the Guild was not the cause.' He holds up a hand before you answer. 'I know whose land that is, by habit. I know whose brother digs it. I'm asking anyway. Somebody always gets the land, Assessor. I'm asking that it be somebody who'll pay wages on it.'".
  }
  Topic quill_agree with quill "Agree to Quill's terms: the Ward plots and the charter, for his Channel down the old course" when offered(quill, actor) and not quillDeal(quill) and knows(actor, feeder_known) {
    Says "Quill shakes your hand, warmly, and holds it a moment longer than he needs to. 'Done.' He writes three lines on a slip, sands them, and rings for a clerk. 'The padlock on the head will be off within the hour. You'll want to do the turning yourself, I think; you'll want to be able to say you did.' At the door he says, not quite lightly: 'If it doesn't stop the Mere, I'll still want my plots.'".
    On discuss { Assert quillDeal(quill). Assert state(guild_chain, unlocked). Assert feederLicensed(actor). Assert channelLicensed(actor). }
  }
  Rule chain_cut_seen when state(guild_chain, cut) and not chainReported(quill) says "Somewhere along the Rim a mill whistle goes, and keeps going. Somebody has seen the Guild's chain on the channel head lying in two pieces." {
    Assert chainReported(quill). Retract tolerates(bailiffs, party). }
  Relation chainReported(group).
  // The bailiffs come to the head when the chain is broken, and do not let it lie.
  Rule bailiffs_to_head when chainReported(quill) and not quillDeal(quill) and at(bailiffs, quill_outer) and not met(bailiffs, rim_gauge) {
    Retract at(bailiffs, quill_outer). Assert at(bailiffs, rim_gauge). Assert met(bailiffs, rim_gauge). }
  Relation met(group, place).
  Observe bailiffs_at_head at rim_gauge when at(bailiffs, rim_gauge) "Three big men in green coats stand at the channel head with cudgels, the Guild's bailiffs, waiting for whoever broke the chain to come back.".
}

data/adventures/low-water/sounding.kyr:
Module lowwater "Low Water" {
  Description "The Sounding: the city's church and clock, its choir, Cantor Sabeth Orr who shortened the Hymn, and the bell-well that goes down from its floor into the great cistern.".

  Place sounding "the Sounding" is building within ammerlin.
  Place nave "the Sounding's nave" is room within sounding at 0, 0.
  Place loft_level "the loft" is level within sounding.
  Place choir_loft "the choir loft" is room within loft_level at 0, 0.
  Place cantor_room "the Cantor's room" is room within sounding at 0, 1.
  Place bell_well "the bell-well" is room within sounding at 1, 1.

  Passage sounding_door "the Sounding's great door" is door between measures_square and nave.
  Passage loft_stair "the loft stair" is stair between nave and choir_loft.
  Passage cantor_door "the Cantor's door" is door between nave and cantor_room.
  Passage well_door "the door to the bell-well" is door between nave and bell_well.

  Observe nave_scene at nave when not familiar(nave) "The Sounding: a round nave under a dome, with no altar, no image, nothing at the centre of the floor but a ring of bronze grating as wide as a threshing-floor, through which you can see, a long way down, black water. Benches face inward to it from every side. The dome is ribbed like the inside of a shell.".
  Observe nave_scene_again at nave when familiar(nave) "The Sounding's nave, round under its ribbed dome, the bronze grating and the black water at its heart.".
  Observe nave_full at nave when hour(clock) >= 18 and hour(clock) < 21 "The nave is full to the doors and up the walls: young people mostly, standing on the benches, and old ones sitting on them, and children on shoulders. The air is warm and loud with talk until the bells begin.".
  Observe nave_hymn at nave when hour(clock) == 19 and sungTonight(bowl) "The Hymn. You have heard it from every terrace and it is nothing like this. The choir is in the loft and the whole nave is singing with it, a thousand voices, and the dome takes the sound and gives it down onto the grating and the black water under it, and the water answers: you feel it in the soles of your feet. It is like standing inside a bell.".
  Observe nave_seventh at nave when seventhTonight(bowl) and hour(clock) == 20 "The Seventh Remainder. Four low notes, alike, sung by the whole nave, slow, over and over, and nobody looks bored, which you would not have guessed. Some of the old people are crying. Down through the grating the black water has gone perfectly still.".
  Person orr "Cantor Sabeth Orr" at cantor_room {
    Greets "Cantor Orr does not get up from the clavichord. She plays one more chord, badly, on purpose, and then turns round.".
    Role "the Cantor of the Sounding". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Wants still_cup.
  }
  Rule orr_to_loft when hour(clock) == 18 and at(orr, cantor_room) { Retract at(orr, cantor_room). Assert at(orr, choir_loft). }
  Rule orr_to_room when hour(clock) == 21 and at(orr, choir_loft) { Retract at(orr, choir_loft). Assert at(orr, cantor_room). }
  Person tamsin "Merrin Reed" at choir_loft {
    Greets "Merrin Reed jumps down off the loft bench, all elbows, and then remembers she is in the Sounding and walks the last two steps.".
    Role "a chorister of sixteen, from the Dyers' Terrace". Ancestry human. Peaceable. Pronouns she. Manner cheerful.
  }
  Person fisk "Precentor Aldo Penhale" at nave {
    Greets "Precentor Penhale inclines his head exactly as far as a precentor should for a stranger, and no further.".
    Role "the Precentor, last of the old Cantors". Ancestry human. Peaceable. Pronouns he. Manner proud.
  }
  Observe loft_scene at choir_loft when true "The choir loft rings the dome halfway up, a gallery of benches and music-stands, worn by three thousand years of feet. From here you look straight down through the grating to the water.".
  Observe cantor_scene at cantor_room when not familiar(cantor_room) "The Cantor's room: a bare cell with a clavichord in it, out of tune on purpose so that she can hear the voices against it, she says. Hymnals on every surface, some of them very old, their pages marked with ribbons and pressed flowers.".
  Observe cantor_scene_again at cantor_room when familiar(cantor_room) "The Cantor's room: the clavichord, out of tune on purpose, and the hymnals.".
  Observe well_scene_s at bell_well when true "A narrow round chamber beside the nave, and in its floor a shaft, railed, going straight down into the dark. Far below, black water. The bell-ropes come down through the ceiling and hang over the shaft, and when the bells ring the water down there shakes into rings. You have the sense, looking down it, that it goes much further than the cistern it is said to serve.".
  Discovery shaft_down "The Sounding is built over a shaft that goes down into the great cistern under Measures Terrace, and the water down there rings when the bells do.".
  Rule shaft_seen when at(party, bell_well) and not knows(party, shaft_down) says "You drop a pebble. You count a long time before you hear it." teaches shaft_down { }

  // The Long Hymn as it was: the hymnal with the Remainders.
  Discovery remainders_tones "In the old hymnal, the Remainders are written in the Sounding's four voices, deep, middle, high and bright: the First is bright and then deep thrice; the Fourth is high and then deep thrice; the Fifth is bright and then middle thrice; the Sixth, the Rising, is deep and then bright thrice; the Seventh is deep four times; and the Long Amen is middle four times." {
    Source old_hymnal "the old hymnal of the Long Hymn, with its Remainders" at cantor_room readable by party.
  }
  Discovery short_hymn "Three autumns ago Cantor Orr shortened the Long Hymn from two hours to forty minutes, cutting the Fourth, Fifth and Seventh Remainders and keeping the Sixth.".

  // Before she knows.
  Topic orr_reform with orr "Ask Cantor Orr about the Short Hymn" when true once {
    Says "'You've come about the hymn. Everyone comes about the hymn.' She does not get up from the clavichord. 'The old Cantors think I've cut the heart out of it. I've cut the fat out of it. Do you know what the Long Hymn was? Two hours. Seven Remainders, every one of them the same four bars, a hundred and twelve repetitions of phrases nobody could tell apart. I cut three of the worst and kept the Sixth because it's beautiful. The young came once, before, and never again.' Her chin comes up. 'Now they come. Three times as many. They sing, child. You should hear them.'".
    On discuss { Assert knows(actor, short_hymn). }
  }
  Topic orr_building with orr "Ask Cantor Orr what a hymn is for" when true once {
    Says "'For?' She plays a chord, badly, on purpose. 'A prayer is a letter. You write it alone and send it off and wait. A hymn is a building everybody stands in at once.' She turns round on the stool. 'A thousand people who can't agree about the price of fish breathe in at the same moment and out at the same moment for forty minutes, and for forty minutes they are one thing, and none of them is any less for it. That is the most important thing a city does and nobody counts it. If nobody stands in a building, it's a ruin, however holy the stones.'".
  }
  Topic orr_remainders with orr "Ask Cantor Orr what the Remainders were" when true once {
    Says "'Accretions. Silt.' She is quite sure. 'Some copyist in the Aenean days liked a phrase and wrote it seven times over, and his successors were too frightened to take it out again. The Seventh was the worst. Four low notes all alike, again and again, for a quarter of an hour.' She hums it, flat, contemptuous: deep, deep, deep, deep. 'Like somebody counting coins. I thought it was the ugliest thing in the whole hymn.'".
  }
  Topic orr_voices with orr "Ask Cantor Orr how the hymn is written" when true once {
    Says "'In the four voices, as everything in the Sounding is: deep, middle, high and bright.' She draws them in the air, a mark for each, rising. 'Not notes as a fiddler means them. Voices. The deep is the men at the back with chests like barrels, and the bright is little girls, and every phrase of the old hymn is so many of each.' She shrugs. 'It's older than any music anywhere else I know. There's an old hymnal on the shelf with the Remainders still in. Read it if you want to be bored.'".
  }
  Topic orr_one with orr "Ask Cantor Orr whether a city can really be one thing" when true once {
    Says "'Not by argument.' She is very definite. 'You can't argue people into being one; Quill tries it at the Council and it only makes more of them. And not by counting, either, whatever Odile Fenn's Office thinks. Counting makes many things out of one, that's what it's for.' She hums a single held note, and you notice the cup on her table ring with it. 'But you can sing them into it. For a while. And then they go home and quarrel, and come back the next night and are one again. That's all there is. It's enough.'".
  }
  Topic orr_fisk with orr "Ask Cantor Orr about Precentor Penhale" when true once {
    Says "'Aldo.' A long-suffering sound. 'Aldo thinks the Mere is falling because God is angry about the Remainders. He thinks God has strong views on liturgical length.' She smiles despite herself. 'He's a good singer, and a fool, and he's the only one of the old Cantors who still comes, so I let him stand at the back and look martyred.'".
  }

  // Precentor Penhale, who is right for the wrong reason.
  Topic fisk_mere with fisk "Ask Precentor Penhale why the Mere is falling" when true once {
    Says "'Because she cut the Remainders.' He says it with a terrible satisfaction. 'Three autumns ago she cut them, and three autumns ago the Mere began to fall. Seven Remainders, as it was given to the Aeneans and by them to us, and she took a knife to it like a tailor to a coat.' He folds his hands. 'The Mere is the dead, Assessor. Every soul a drop. When the hymn is broken the dead do not rest, and they go down, and away. I have said so at three Councils. They laugh.'".
  }
  Topic fisk_why with fisk "Ask Penhale how he knows it was the Remainders and not something else" when knows(actor, short_hymn) once {
    Says "'Because I have faith,' he says, and then, seeing your face, rather less grandly: 'And because I can count. The Mere stood still for as long as there has been a Cantor. Then it moved. The only thing that changed in the Bowl that autumn was the hymn.' He looks at you sidelong. 'The Guild's Channel was the next year. Nobody remembers that. Everybody remembers the Channel.'".
  }

  // Merrin, who came because of the reform.
  Topic tamsin_why with tamsin "Ask Merrin why she sings" when true once {
    Says "'Because it's the best thing in the world,' says Merrin, as if you were slow. 'My mum used to say the Hymn was two hours of old men moaning. Then Cantor Orr made it short and my friend Jessa dragged me, and.' She stops, and starts again. 'When we all breathe in together it's like the whole dome breathes in. You can't do that on your own. You can't do it with five people. You need everybody.' She grins. 'Even Precentor Penhale.'".
  }
  Topic tamsin_seventh with tamsin "Ask Merrin what she would think if the Seventh Remainder came back" when knows(actor, hymn_cause) once {
    Says "Merrin pulls a face, and then thinks about it properly, which you like her for. 'The counting one? It's dull. Everybody says so.' She chews her lip. 'But if it was for something. If it actually did something.' She looks down through the grating at the black water. 'I'd sing it. I'd sing it every night. It'd be like, like being the lock-keeper. Only all of us.'".
  }

  // After the hymn is known for what it does.
  Discovery hymn_cause "The Mere began to fall the autumn the Short Hymn was first sung. The Seventh Remainder, which it leaves out, is the verse at which the Deep Gate at the Ninth Lock came down each night; since the Short Hymn, the Deep Gate has never come down.".
  Rule hymn_cause_put when knows(party, short_hymn) and (knows(party, lockbook_read) or knows(party, letters_read)) and (knows(party, fall_dated) or knows(party, lock_rhyme)) and not knows(party, hymn_cause)
    says "It comes together like two halves of a broken plate: the autumn the Short Hymn was first sung, and the autumn the Mere began to fall; the Seventh Remainder that the Short Hymn left out, and the nights since then in the keeper's book, every one of them the same. Deep did not come down." teaches hymn_cause { }
  Relation orrKnows(group).
  Topic orr_told with orr "Tell Cantor Orr what the Seventh Remainder did" when knows(actor, hymn_cause) and not orrKnows(orr) once {
    Says "She stops you before you have finished. 'Say it plainly. I'm seventy-one. I haven't time for you to be kind.' You say it plainly. She sits with her hands in her lap and her eyes on the lid of the clavichord. 'Then it wasn't silt,' she says. 'Then somebody wrote it seven times because it was meant seven times.' She looks at her hands. 'And I thought it was ugly. I thought it was the ugliest thing in the hymn, those four bars. Like somebody counting.' A breath. 'It was somebody counting, wasn't it.'".
    On discuss { Assert orrKnows(orr). }
  }
  Relation trialSung(place).
  Topic orr_trial with orr "Ask Cantor Orr to sing the Seventh Remainder tonight, once, and watch the Deep Gate" when orrKnows(orr) and not seventhRestored(bowl) and not trialSung(bowl) and hour(clock) < 19 once {
    Says "'Once.' She considers it like a doctor considering a dose. 'Yes. The choir will think I've gone mad, and Aldo will think he's won, and the young will be bored for a quarter of an hour.' She gets up, stiffly. 'Go down to the Ninth Lock and watch your gate. If it comes down at the Seventh, I'll know. If it doesn't, I'll know that too, and I'll thank you to tell me which.'".
    On discuss { Assert trialSung(bowl). Assert seventhRestored(bowl). Set trialEnds(bowl) to watch(clock) + 48. }
  }
  Measure trialEnds(place).
  Rule trial_over when trialSung(bowl) and trialEnds(bowl) > 0 and watch(clock) >= trialEnds(bowl) and not restoredForGood(bowl) and hour(clock) > 20 {
    Retract seventhRestored(bowl). Set trialEnds(bowl) to 0. }
  Relation restoredForGood(place).
  Topic orr_restore with orr "Tell Cantor Orr the Deep Gate came down at the Seventh, and ask her to sing it every night" when orrKnows(orr) and knows(actor, gate_falls_seen) and not restoredForGood(bowl) once {
    Says "She hears you out with her eyes shut. 'It came down,' she says. 'Piet Harl's gate. At my four ugly bars.' She opens her eyes. 'Every night, then. The Seventh and nothing else; the Fourth and Fifth can stay cut until somebody shows me they shut something too.' And then, sharp, because she is who she is: 'They'll sing it. You watch. Not because it's beautiful. Because it's for something. That's the thing I forgot. A building everybody stands in, yes, but somebody built it for a reason, and the reason was holding the roof up.'".
    On discuss { Assert seventhRestored(bowl). Assert restoredForGood(bowl). }
  }
  Topic orr_restore_unseen with orr "Ask Cantor Orr to sing the Seventh every night from now on" when orrKnows(orr) and not knows(actor, gate_falls_seen) and not restoredForGood(bowl) and not trialSung(bowl) once {
    Says "'On your word?' She is not unkind. 'Child, I cut it on my word, and look. I'll not put it back on yours. Show me. Let me sing it once and you go and watch that gate with your own eyes, and then come back and tell me, and I'll sing it till I die.'".
  }
  Topic orr_rubbing with orr "Show Cantor Orr the rubbing of the Dyers' arch" when carries(actor, rubbing) once {
    Says "She takes the cloth to the window. 'These are the four voices.' She touches the note-marks one by one, deep to bright. 'Written the old way, the way the oldest hymnal writes them. And these.' The four mouths, shut to wide. 'Shut for the deep. Wide for the bright.' She is quiet. 'Somebody carved a table of what the voices mean. On the floor of a dye-basin.' She gives it back very carefully. 'If that is what they mean, then the Seventh is the deep voice, and the deep voice four times over, and the deep voice is a shut mouth. Somebody was telling something to keep its mouth nearly shut.'".
  }
  // What she comes to believe, after the engine.
  Relation orrStance(group, entity). Kind stance.
  Entity stance_building: stance "the hymn is still a building". Entity stance_answered: stance "the hymn was heard". Entity stance_numbers: stance "the hymn was numbers".
  Topic orr_engine with orr "Tell Cantor Orr what is under the Mere, and what the Remainders are to it" when knows(actor, engine_seen) and orrKnows(orr) and not orrStanding(orr) once {
    Says "She makes you tell it twice. The column, the wheels, the four bars of bronze. When you are done she says, 'Then I have spent my life singing to a machine.' She says it without self-pity, as if testing the weight of it. 'Three thousand years of choirs. The Aeneans, and us. Singing it what to do, and calling it praise, because we didn't know the words.' She looks up at you. 'Well, Assessor? You've been down there. What was it we were doing?'".
    On discuss { Assert orrAsked(orr). }
  }
  Relation orrAsked(group). Relation orrStanding(group).
  Topic orr_answer_building with orr "Tell her the hymn was still a building everybody stood in, whatever else it did" when orrAsked(orr) and not orrStanding(orr) {
    Says "'Both,' she says, slowly. 'It held up the roof, and people stood under it.' She almost laughs. 'Every building's like that, isn't it. Nobody builds a roof for the joy of standing under it. They build it against the rain, and then the joy comes.' She takes your hand, briefly, a dry old hand. 'Thank you. That I can sing.'".
    On discuss { Assert orrStance(orr, stance_building). Assert orrStanding(orr). }
  }
  Topic orr_answer_heard with orr "Tell her the Reckoner heard every note for three thousand years, and did what it was asked" when orrAsked(orr) and not orrStanding(orr) {
    Says "Her eyes fill, which you did not expect. 'Heard,' she says. 'Something heard.' She wipes her face with the back of her wrist, impatient with herself. 'Aldo would say that's God. I'll not say that. But it's more than I had any right to.' She looks down through the floor, as if she could see it. 'We were heard. And when we stopped singing it the right words, it went on doing the last thing it was told. Like Piet.'".
    On discuss { Assert orrStance(orr, stance_answered). Assert orrStanding(orr). }
  }
  Topic orr_answer_numbers with orr "Tell her it was only ever numbers, and the music was what people added" when orrAsked(orr) and not orrStanding(orr) {
    Says "'Numbers.' She takes it like a blow and doesn't fall. 'Yes. I expect that's true.' She closes the clavichord's lid. 'Then I'll sing them the numbers, and I'll let the young think it's music, and perhaps that's what music always was.' She does not look at you again. 'Thank you, Assessor. You're very honest. Goodnight.'".
    On discuss { Assert orrStance(orr, stance_numbers). Assert orrStanding(orr). }
  }
  Topic orr_fifth with orr "Tell Cantor Orr the Fifth Remainder was the Bowl's own voice: bright and middle, its voice a little" when knows(actor, grammar_known) and restoredForGood(bowl) and not fifthRestored(bowl) once {
    Says "'The fountains,' says Cantor Orr at once, before you have finished. 'Abel Tarrant used to say the fountains purred, when he was a boy. I thought he was being sentimental.' She considers it. 'It does nothing? Nothing to the water?' Nothing but sing, as far as you know. Her face does something complicated. 'Then I'll put it back for that. For nothing. Because it sings.' She almost smiles. 'That's the first good reason I've had for anything this week.'".
    On discuss { Assert fifthRestored(bowl). }
  }
  Topic orr_fourth with orr "Tell Cantor Orr what the Fourth Remainder said: high and deep, the last door, least: keep it shut" when knows(actor, grammar_known) and restoredForGood(bowl) and not fourthRestored(bowl) and not complete(reckoner) once {
    Says "She hears it out with her hands flat on the clavichord's lid. 'So when the count is done,' she says slowly, 'the door would open, and the count go through, whatever is on the other side of it. And the Fourth kept it shut. Every night. For three thousand years.' She looks at you. 'Somebody didn't want it given. Or didn't want it given yet.' A long silence. 'I'll not decide that on my own a second time. If you tell me to sing the Fourth, I'll sing it. If you don't, I won't. You're the Assessor.'".
  }
  Topic orr_fourth_sing with orr "Ask Cantor Orr to sing the Fourth every night, and keep the last door shut" when knows(actor, grammar_known) and restoredForGood(bowl) and not fourthRestored(bowl) and not complete(reckoner) {
    Says "'Then it stays shut.' She writes it in the hymnal's margin in pencil, small, beside the Fourth. 'Halm will never speak to either of us again. I can bear that.'".
    On discuss { Assert fourthRestored(bowl). }
  }
  Relation willTestify(group).
  Topic orr_hearing with orr "Ask Cantor Orr to speak at the Hearing" when orrKnows(orr) and not willTestify(orr) once {
    Says "'And say what? That I did it?' A dry look. 'Yes. Of course I'll say it. I'll stand up in front of Odile and Harrow Quill and the whole Council and say I cut three thousand years out of the Hymn because the children were bored.' She stands. 'Somebody should say it who's sorry. Not Aldo. He'd enjoy it.'".
    On discuss { Assert willTestify(orr). }
  }
}

data/adventures/low-water/undercroft.kyr:
Module lowwater "Low Water" {
  Description "The Undercroft: the works under the Mere, made in the Mathematical Age. A dry vestibule, the Hall of the Equals, the counting gallery, the listening column, the governor, and the last door.".

  Place vestibule "the dry vestibule" is room within undercroft at 0, 1 underground.
  Place breach_gallery "the broken gallery" is room within undercroft at 2, 1 underground.
  Place equal_hall "the Hall of the Equals" is room within undercroft at 1, 1 underground.
  Place count_gallery "the counting gallery" is room within undercroft at 1, 2 underground.
  Place column_room "the listening column" is room within undercroft at 0, 2 underground.
  Place governor_room "the governor" is room within undercroft at 2, 2 underground.
  Place depths_level "the depths of the Undercroft" is level within undercroft.
  Place last_door_room "the last door" is room within depths_level at 0, 0 underground.
  Initially Assert unlit(vestibule). Initially Assert unlit(breach_gallery). Initially Assert unlit(equal_hall).
  Initially Assert unlit(count_gallery). Initially Assert unlit(column_room). Initially Assert unlit(governor_room).
  Initially Assert unlit(last_door_room).

  Passage culvert_foot "the foot of the intake culvert" is passage between intake_culvert and vestibule taking 30 minutes.
  Passage vestibule_arch "the arch into the Hall of the Equals" is arch between vestibule and equal_hall.
  Passage gallery_arch "the arch from the broken gallery" is arch between breach_gallery and equal_hall.
  Passage hall_to_count "the far arch of the Hall of the Equals" is arch between equal_hall and count_gallery.
  Passage count_to_column "the way to the column" is passage between count_gallery and column_room.
  Passage count_to_governor "the way to the governor" is passage between count_gallery and governor_room.
  Passage count_to_door "the long stair down" is stair between count_gallery and last_door_room taking 5 minutes.

  Observe vestibule_scene at vestibule when not familiar(vestibule) "The culvert comes out into a square room of the fine grey stone, dry, still, warmer than the culvert. A thread of water crosses the floor in a channel and goes on through an arch.".
  Observe vestibule_scene_again at vestibule when familiar(vestibule) "The dry vestibule, the culvert's thread of water crossing its floor.".
  Observe vest_stones at vestibule when at(vest_weight, vestibule) or at(vest_weight_b, vestibule) "Against the wall, as if somebody had tidied them, squared weight-stones with holes through them.".
  Item vest_weight "a weight-stone" is weight_stone at vestibule.
  Item vest_weight_b "a weight-stone" is weight_stone at vestibule.
  Observe breach_scene at breach_gallery when not familiar(breach_gallery) "A gallery of grey stone, square and dry, and in its wall the ragged hole the diggers made, with mud and broken slab spilled in through it. Everything else is clean: three thousand years clean.".
  Observe breach_scene_again at breach_gallery when familiar(breach_gallery) "The broken gallery, the diggers' hole ragged in its clean grey wall.".
  Discovery engine_seen "Under the Mere there is a working machine of the Mathematical Age that counts by water, and the water it counts does not come out again anywhere.".

  // The Hall of the Equals: the floor is a scale. Whoever walks it tips it, and the Equals keep it even.
  Observe equal_scene at equal_hall when not familiar(equal_hall) "A long hall with a floor of a single slab of grey stone, so finely set that it rocks, very slightly, under your weight; you feel it go down at your end. At the far end, the other side of the balance. Between, two figures of bronze, broad, faceless, too wide at the shoulder, stand facing each other across the floor like the two halves of something.".
  Observe equal_scene_again at equal_hall when familiar(equal_hall) "The Hall of the Equals: the rocking floor, the stone pan on its chains, and the two bronze figures facing each other across it.".
  Person equals "the Equals" at equal_hall {
    Role "two figures of bronze, broad, faceless, made to keep a reckoning even". Species bronze_construct. Level 5. Numbers 2.
    Temperament obedient.
    Warns "The Equals turn, both together, without a sound, and face you where you stand on the tipped floor. One of them lifts its hands, flat, palms down, and presses the air, the way you would press down the end of a plank that has come up.".
    Comes "The Equals come for you together, not fast, not slow, the way water comes, to set the floor level by taking off it whatever tips it.".
  }
  Initially Assert tolerates(equals, party).
  Thing counterpan "the stone pan" at equal_hall {
    Holds.
    State hanging "At the far end of the hall the stone pan hangs from its beam on bronze chains.".
  }
  Measure stonesIn(entity). Measure walkers(group). Relation counted(item). Relation walking(member).
  Rule stone_counted when inside(?w, counterpan) and itemKind(?w, weight_stone) and not counted(?w) { Assert counted(?w). Increase stonesIn(counterpan) by 1. }
  Rule stone_uncounted when counted(?w) and not inside(?w, counterpan) { Retract counted(?w). Decrease stonesIn(counterpan) by 1. }
  Rule walker_counted when memberOf(?m, party) and not walking(?m) { Assert walking(?m). Increase walkers(party) by 1. }
  Rule walker_gone when walking(?m) and not memberOf(?m, party) { Retract walking(?m). Decrease walkers(party) by 1. }
  Query balanced() means stonesIn(counterpan) >= walkers(party).
  Observe pan_level at equal_hall when balanced() "The floor lies level under you, and the stone pan hangs level at the far end, and the Equals stand facing one another across the hall as if you were not there.".
  Observe pan_tipped at equal_hall when not balanced() and stonesIn(counterpan) > 0 "The pan has gone down some way, but not all: the floor is still tipped your way, a finger's breadth.".
  // A watch to see it; then they come. tippedSince is the watch the floor was first seen tipped, and one more.
  Measure tippedSince(group). Relation equalsWarned(group).
  Rule tipped_mark when at(party, equal_hall) and not balanced() and able(equals) and not broken(reckoner) and tippedSince(party) == 0 {
    Set tippedSince(party) to watch(clock) + 1. }
  Rule tipped_eases when tippedSince(party) > 0 and (not at(party, equal_hall) or balanced()) { Set tippedSince(party) to 0. Retract equalsWarned(party). }
  Rule equals_warn at equal_hall when at(party, equal_hall) and tippedSince(party) > 0 and not equalsWarned(party) and able(equals) and tolerates(equals, party)
    says "The Equals turn, both together, without a sound, and face you where you stand on the tipped floor. One lifts its hands, flat, palms down, and presses the air, as you would press down the end of a plank that has come up." {
    Assert equalsWarned(party). }
  Rule equals_come when at(party, equal_hall) and not balanced() and tippedSince(party) > 0 and watch(clock) >= tippedSince(party) + 1 and able(equals) and tolerates(equals, party) {
    Retract tolerates(equals, party). Assert assails(equals, party). }
  Rule equals_settle when balanced() and not tolerates(equals, party) and able(equals) and not guarding(equals) { Assert tolerates(equals, party). }
  Relation guarding(group).
  Discovery equals_rule "The Equals keep the Hall's floor level: whoever tips it, they come for, and a weight set in the far pan to answer each walker sets it level again.".
  Rule equals_understood when at(party, equal_hall) and balanced() and stonesIn(counterpan) > 0 and not knows(party, equals_rule)
    says "As the last stone goes into the pan the floor comes up level under your feet with a long soft grinding, and the Equals lower their hands." teaches equals_rule { }

  // The counting gallery: nine wheels, and how many have turned.
  Observe count_scene at count_gallery when not familiar(count_gallery) "A gallery as long as a street, and down one side of it nine tall arches, and through every arch a wheel of bronze and grey stone, each in a room of its own, each as tall as a house. A channel of moving water runs the length of the gallery and turns in at every arch, and comes out again, by a hundred small gates.".
  Observe count_scene_again at count_gallery when familiar(count_gallery) "The counting gallery, and its nine arches, and the wheel in every one.".
  Observe count_running at count_gallery when not complete(reckoner) and not broken(reckoner) "The gates open and shut with a sound like beads on a wire. The note you heard in the Listening Hall is all round you here, and you can feel it in the floor.".
  Observe count_wheels_0 at count_gallery when not complete(reckoner) and not broken(reckoner) and ninths(reckoner) == 0 "Of the nine wheels, no stand still and locked, their gates shut, as if finished. The next is turning, slowly. The rest wait, dry.".
  Observe count_wheels_1 at count_gallery when not complete(reckoner) and not broken(reckoner) and ninths(reckoner) == 1 "Of the nine wheels, one stands still and locked, their gates shut, as if finished. The next is turning, slowly. The rest wait, dry.".
  Observe count_wheels_2 at count_gallery when not complete(reckoner) and not broken(reckoner) and ninths(reckoner) == 2 "Of the nine wheels, two stand still and locked, their gates shut, as if finished. The next is turning, slowly. The rest wait, dry.".
  Observe count_wheels_3 at count_gallery when not complete(reckoner) and not broken(reckoner) and ninths(reckoner) == 3 "Of the nine wheels, three stand still and locked, their gates shut, as if finished. The next is turning, slowly. The rest wait, dry.".
  Observe count_wheels_4 at count_gallery when not complete(reckoner) and not broken(reckoner) and ninths(reckoner) == 4 "Of the nine wheels, four stand still and locked, their gates shut, as if finished. The next is turning, slowly. The rest wait, dry.".
  Observe count_wheels_5 at count_gallery when not complete(reckoner) and not broken(reckoner) and ninths(reckoner) == 5 "Of the nine wheels, five stand still and locked, their gates shut, as if finished. The next is turning, slowly. The rest wait, dry.".
  Observe count_wheels_6 at count_gallery when not complete(reckoner) and not broken(reckoner) and ninths(reckoner) == 6 "Of the nine wheels, six stand still and locked, their gates shut, as if finished. The next is turning, slowly. The rest wait, dry.".
  Observe count_wheels_7 at count_gallery when not complete(reckoner) and not broken(reckoner) and ninths(reckoner) == 7 "Of the nine wheels, seven stand still and locked, their gates shut, as if finished. The next is turning, slowly. The rest wait, dry.".
  Observe count_wheels_8 at count_gallery when not complete(reckoner) and not broken(reckoner) and ninths(reckoner) == 8 "Of the nine wheels, eight stand still and locked, their gates shut, as if finished. The next is turning, slowly. The rest wait, dry.".
  Observe count_done at count_gallery when complete(reckoner) "All nine wheels stand still and locked. The channel is dry. The gallery is silent for the first time in three thousand years, and the silence is enormous.".
  Observe count_dead at count_gallery when broken(reckoner) "The wheels have stopped where they stood, the turning one half-turned. Water lies in the channel and does not move. Nothing clicks.".
  Rule engine_known when at(party, count_gallery) and not knows(party, engine_seen) says "You stand and watch it for a long time before you let yourself say it. It is a machine, and it is counting: a gate at a time, a measure of water at a time, and the water it has counted runs on down the gallery toward the long stair and does not come back." teaches engine_seen { }

  // The listening column: a pipe of still water going up toward the Sounding, and four bronze bars to sound into it.
  Observe column_scene at column_room when not familiar(column_room) "A round room, and in the middle a column of water, standing up out of a basin in a pipe of polished grey stone as wide as a well, up into the dark as far as your light goes. The water in it is perfectly still. Round the basin's rim hang four bars of bronze on cords, of four lengths, and a bronze striker on a chain.".
  Observe column_scene_again at column_room when familiar(column_room) "The listening column, perfectly still in its pipe of stone, and the four bronze bars round its basin.".
  Discovery column_up "The listening column goes up from the Undercroft toward the great cistern under the Sounding: what is sung in the Sounding comes down it to the Reckoner, and what is sounded here goes up.".
  Observe column_hymn at column_room when hour(clock) == 19 and sungTonight(bowl) "From far up the column, down the still water, comes the Hymn: the Sounding's bells and choir, small and clear and perfect, as if they were singing in the next room.".
  Rule column_up_known when at(party, column_room) and hour(clock) == 19 and sungTonight(bowl) and not knows(party, column_up) says "The water in the column carries it down to you note for note: what is sung in the Sounding comes here." teaches column_up { }
  Measure firstTone(entity).
  Action strike_deep(actor: group, site: place) "Strike the longest bar, the deep voice" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, column_room) and not broken(reckoner).
    Time 1 minute.
    On success { Set struck(column_room) to 1. }
    Result "The longest bar gives a deep note that goes into the water and up the column.".
  }
  Action strike_middle(actor: group, site: place) "Strike the second bar, the middle voice" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, column_room) and not broken(reckoner).
    Time 1 minute.
    On success { Set struck(column_room) to 2. }
    Result "The second bar gives a middle note, plain and round, that goes up the column.".
  }
  Action strike_high(actor: group, site: place) "Strike the third bar, the high voice" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, column_room) and not broken(reckoner).
    Time 1 minute.
    On success { Set struck(column_room) to 3. }
    Result "The third bar gives a high note, thin and clear, that goes up the column.".
  }
  Action strike_bright(actor: group, site: place) "Strike the shortest bar, the bright voice" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, column_room) and not broken(reckoner).
    Time 1 minute.
    On success { Set struck(column_room) to 4. }
    Result "The shortest bar gives a bright note, almost too high to hear, that goes up the column like a spark.".
  }
  Measure struck(entity). Measure secondTone(entity).
  // A struck bar is a first tone, or the second that completes a phrase.
  Rule tone_first when struck(column_room) > 0 and firstTone(column_room) == 0 {
    Set firstTone(column_room) to struck(column_room). Set struck(column_room) to 0. }
  Rule tone_second when struck(column_room) > 0 and firstTone(column_room) > 0 {
    Set secondTone(column_room) to struck(column_room). Set struck(column_room) to 0. }
  Observe tone_hangs at column_room when firstTone(column_room) > 0 and secondTone(column_room) == 0 "The note you struck has not died. It hangs in the column, faint and level, as if the water were waiting for the rest.".
  // What the engine hears, and does.
  Rule says_cupful when firstTone(column_room) == 1 and secondTone(column_room) == 1
    says "Deep, and deep: the Seventh Remainder, as the choir sings it. The water in the column shivers. Far off through the rock you hear, or feel, something heavy settle into a bed of stone." {
    Assert state(deep_gate, lowered). Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_wide when firstTone(column_room) == 1 and secondTone(column_room) == 4 and not complete(reckoner)
    says "Deep, and bright: the Sixth Remainder, the Rising. The column hums. Far off through the rock something heavy heaves itself up on edge, and a long breath begins." {
    Assert state(deep_gate, raised). Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_half when firstTone(column_room) == 1 and (secondTone(column_room) == 2 or secondTone(column_room) == 3) and not complete(reckoner)
    says "The column takes the two notes and the water in the basin rocks once, as if something far off had been moved, and stopped halfway." {
    Assert state(deep_gate, half). Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_count_0 when firstTone(column_room) == 2 and secondTone(column_room) > 0 and ninths(reckoner) == 0
    says "The middle voice: the count. For a moment nothing. Then up out of the column, slow, comes the middle note again, and after it no stroke at all; and then a silence the length of the strokes that are not there." teaches count_heard {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_count_1 when firstTone(column_room) == 2 and secondTone(column_room) > 0 and ninths(reckoner) == 1
    says "The middle voice: the count. For a moment nothing. Then up out of the column, slow, comes the middle note again, and after it a single stroke of the bright voice; and then a silence the length of the strokes that are not there." teaches count_heard {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_count_2 when firstTone(column_room) == 2 and secondTone(column_room) > 0 and ninths(reckoner) == 2
    says "The middle voice: the count. For a moment nothing. Then up out of the column, slow, comes the middle note again, and after it strokes of the bright voice, counting, two in all; and then a silence the length of the strokes that are not there." teaches count_heard {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_count_3 when firstTone(column_room) == 2 and secondTone(column_room) > 0 and ninths(reckoner) == 3
    says "The middle voice: the count. For a moment nothing. Then up out of the column, slow, comes the middle note again, and after it strokes of the bright voice, counting, three in all; and then a silence the length of the strokes that are not there." teaches count_heard {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_count_4 when firstTone(column_room) == 2 and secondTone(column_room) > 0 and ninths(reckoner) == 4
    says "The middle voice: the count. For a moment nothing. Then up out of the column, slow, comes the middle note again, and after it strokes of the bright voice, counting, four in all; and then a silence the length of the strokes that are not there." teaches count_heard {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_count_5 when firstTone(column_room) == 2 and secondTone(column_room) > 0 and ninths(reckoner) == 5
    says "The middle voice: the count. For a moment nothing. Then up out of the column, slow, comes the middle note again, and after it strokes of the bright voice, counting, five in all; and then a silence the length of the strokes that are not there." teaches count_heard {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_count_6 when firstTone(column_room) == 2 and secondTone(column_room) > 0 and ninths(reckoner) == 6
    says "The middle voice: the count. For a moment nothing. Then up out of the column, slow, comes the middle note again, and after it strokes of the bright voice, counting, six in all; and then a silence the length of the strokes that are not there." teaches count_heard {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_count_7 when firstTone(column_room) == 2 and secondTone(column_room) > 0 and ninths(reckoner) == 7
    says "The middle voice: the count. For a moment nothing. Then up out of the column, slow, comes the middle note again, and after it strokes of the bright voice, counting, seven in all; and then a silence the length of the strokes that are not there." teaches count_heard {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_count_8 when firstTone(column_room) == 2 and secondTone(column_room) > 0 and ninths(reckoner) == 8
    says "The middle voice: the count. For a moment nothing. Then up out of the column, slow, comes the middle note again, and after it strokes of the bright voice, counting, eight in all; and then a silence the length of the strokes that are not there." teaches count_heard {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_count_9 when firstTone(column_room) == 2 and secondTone(column_room) > 0 and ninths(reckoner) == 9
    says "The middle voice: the count. For a moment nothing. Then up out of the column, slow, comes the middle note again, and after it strokes of the bright voice, counting, nine in all; and then nothing, for there is nothing left to count." teaches count_heard {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Discovery count_heard "Asked its count in its own voice, the Reckoner answers in ninths: so many strokes of nine as it has counted.".
  Rule says_question when firstTone(column_room) == 4 and secondTone(column_room) == 1
    says "Bright, and deep: the First Remainder. The column answers at once, as if it had been waiting three thousand years for somebody to ask. Up out of the water comes a long phrase in all four voices, over and over, and with it, on the lintel over the long stair, a line of letters you had taken for ornament catches your light and is suddenly plain to see." teaches question_heard {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Discovery question_heard "Asked its question in the First Remainder, the Reckoner sang it back, and the lintel over the long stair to the last door shows it in letters: what Halm reads as IT COUNTS WHAT IS BOUND.".
  Rule says_all when firstTone(column_room) == 4 and secondTone(column_room) == 4
    says "Bright, and bright. The column takes it, and gives it back a hundredfold: the whole Long Hymn, every Remainder, comes up out of the water in one long rising chord, and goes up the column toward the Sounding, and you hear it go on above you through the rock, in every pipe and cistern of the Bowl, all at once." {
    Assert sangBack(ammerlin). Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Relation sangBack(place).
  Rule says_end when firstTone(column_room) == 3 and secondTone(column_room) == 4 and not complete(reckoner) and not broken(reckoner) and not doorHeld(reckoner)
    says "High, and bright: the voice that is not sung. The column takes it and is silent. Then, far off down the gallery, every gate of the count opens at once, and the water goes through the Reckoner like a held breath let out, and the wheels you could not see from here begin to turn all together, faster, faster, nine of them, and stop." {
    Set count(reckoner) to 900. Assert endedBy(reckoner, party). Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Relation endedBy(engine, group).
  Rule says_end_held when firstTone(column_room) == 3 and secondTone(column_room) == 4 and not complete(reckoner) and not broken(reckoner) and doorHeld(reckoner)
    says "High, and bright. The column takes it, and far down the long stair something strains against the round door and does not give. The Fourth holds it. The water in the column shivers, once, and is still." {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_hold when firstTone(column_room) == 3 and secondTone(column_room) == 1 and not complete(reckoner)
    says "High, and deep: the Fourth Remainder. The column takes it and is still. Far down the long stair something settles against the round door, the way a bar settles in its brackets." {
    Assert doorHeld(reckoner). Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Relation doorHeld(engine).
  Rule says_refusal when firstTone(column_room) == 3 and secondTone(column_room) > 1 and secondTone(column_room) < 4
    says "The high voice. The column hears it and gives back a single flat note, low, like a door that will not open partway." {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_hum when firstTone(column_room) == 4 and (secondTone(column_room) == 2 or secondTone(column_room) == 3)
    says "Bright, and middle: the Fifth Remainder. The column gives back a low steady hum, and you hear it go on up through the rock above you, spreading, as if every pipe and basin of the Bowl had begun to hum along." {
    Assert humming(ammerlin). Set humAt(ammerlin) to watch(clock). Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. Increase spoken(column_room) by 1. }
  Rule says_done when complete(reckoner) and secondTone(column_room) > 0
    says "The column takes the notes and gives nothing back. Whatever it was listening for, it has heard." {
    Set firstTone(column_room) to 0. Set secondTone(column_room) to 0. }
  Measure spoken(entity).

  // The governor: what makes the engine count rather than run. Broken, the engine stops for good.
  Observe governor_scene at governor_room when not broken(reckoner) "A room the Reckoner's water goes round, in a channel, through a cage of bronze arms that swing out and in, out and in, unhurried, like the arms of somebody walking. At the centre of the cage is a spindle of grey stone, and on it two balls of bronze turning. Everything in the Undercroft keeps time to it.".
  Observe governor_broken at governor_room when broken(reckoner) "The governor's cage lies twisted in its channel. The spindle is snapped. Water stands round it, still.".
  Discovery governor_known "The governor in the Undercroft keeps the Reckoner counting: break its spindle, and the Reckoner would stop, and never count again.".
  Rule governor_seen when at(party, governor_room) and not broken(reckoner) and not knows(party, governor_known) says "You watch the arms swing out, and in, and see the whole machine wait for them each time." teaches governor_known { }
  Action break_governor(actor: group, site: place) "Break the governor's spindle" {
    Description "Stop the Reckoner, for good. Whatever it was counting, it will never finish.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, governor_room) and not broken(reckoner) and not complete(reckoner)
      and (capable(actor, brawn) or carries(actor, ?bar) and itemKind(?bar, crowbar)).
    Time 1.
    On success { Assert broken(reckoner). Assert brokenBy(reckoner, actor). Assert state(deep_gate, lowered). }
    Result "It takes three blows. The first rings like a bell and does nothing. The second cracks the stone. At the third the spindle goes, and the arms of the cage fly out and wrap themselves round the bars, and the bronze balls drop into the water, and all through the rock the note you have been hearing since the Listening Hall stops, the way a heart stops.".
  }
  Relation brokenBy(engine, group).
  Rule equals_defend when broken(reckoner) and able(equals) and not defended(equals) says "From the Hall of the Equals comes a sound like a cart of bells overturned, and then the sound of something broad and heavy coming down the gallery, not fast, not slow." {
    Assert guarding(equals). Assert defended(equals). Retract tolerates(equals, party). Set equalsArrive(equals) to watch(clock) + 2. }
  Relation defended(group).
  Measure equalsArrive(group).
  Rule equals_arrive when guarding(equals) and equalsArrive(equals) > 0 and watch(clock) >= equalsArrive(equals) and not at(equals, governor_room) {
    Retract at(equals, equal_hall). Assert at(equals, governor_room). }
  Rule equals_fall_on when guarding(equals) and at(equals, governor_room) and at(party, governor_room) and able(equals) and not stilled(equals) { Assert assails(equals, party). }
  Rule equals_stop when broken(reckoner) and guarding(equals) and at(equals, governor_room) and not at(party, governor_room) and not stilled(equals) {
    Assert stilled(equals). Retract guarding(equals). Assert tolerates(equals, party). }
  Relation stilled(group).
  Observe equals_coming at governor_room when guarding(equals) and not at(equals, governor_room) "From the gallery, coming nearer, the sound of something broad and heavy walking, not fast, not slow.".
  Observe equals_still at governor_room when stilled(equals) and at(equals, governor_room) "The Equals stand over the broken governor, one each side, with their hands flat and still, as if they were holding something level that is no longer there.".

  // The last door, and what is written over it.
  Observe door_scene at last_door_room when not complete(reckoner) "At the bottom of the long stair, the counted water goes into a slot in the floor in a smooth black sheet. Beyond it a door of grey stone, round, closed, with no handle; across it a single line of carving. The air here is very cold, and smells of nothing at all.".
  Observe door_open at last_door_room when complete(reckoner) and not doorHeld(reckoner) "The round door stands open. Beyond it is not a room. Beyond it, as far as you can see, is still water under no sky, lit from nowhere, and the cold that comes out of it smells of nothing at all.".
  Observe door_held at last_door_room when complete(reckoner) and doorHeld(reckoner) "The counted water no longer runs into the slot. The round door is shut, and something behind it, or in it, is keeping it so: the Fourth, sung every night, holding what the count has gathered.".
  Observe door_shut_dead at last_door_room when broken(reckoner) "The slot in the floor is dry. The round door is shut, and will stay shut.".
  Discovery door_words "Over the last door in the Undercroft are two lines of carving, one in the oldest marks and one in Aenean.".
  Rule door_carving at last_door_room when at(party, last_door_room) and not knows(party, door_words) says "Across the round door, two lines: one in the oldest marks, the ones under the keystone, and one in Aenean, newer, cut by somebody who was copying something they did not understand." teaches door_words { }
}

data/adventures/low-water/ward.kyr:
Module lowwater "Low Water" {
  Description "The Mere Ward: the landing and its gauge steps, Tench Row, Dov Vant's yard and boat, the Ward well, and the people at the bottom of the Bowl.".


  Place ward_landing "the Ward landing" is room within ammerlin at 1, 5 outdoors.
  Place tench_row "Tench Row" is room within ammerlin at 2, 5 outdoors.
  Place dov_yard "Dov Vant's yard" is room within ammerlin at 3, 5 outdoors.
  Place ward_well "the Ward well" is room within ammerlin at 0, 5 outdoors.

  Passage ward_steps "the Ward steps, below the Nine Locks" is steps between lock_stair and ward_landing taking 15 minutes.
  Passage row_way "the way along Tench Row" is path between ward_landing and tench_row taking 3 minutes.
  Passage yard_way "Dov Vant's gate" is gate between tench_row and dov_yard.
  Passage well_way "the lane to the well" is path between ward_landing and ward_well taking 3 minutes.

  // The gauge steps: the Office's marks, cut in the landing stair, going down into the Mere.
  Observe landing_scene at ward_landing when not familiar(ward_landing) "The Ward landing: a broad stair of stone going down into the Mere, built for boats to tie up at, with the Office's spans cut on every step and painted. Fishing boats lie along it, and not one of them is afloat. The water stands far below the last painted step, across a flat of grey mud with planks laid over it.".
  Observe landing_scene_again at ward_landing when familiar(ward_landing) "The Ward landing, its painted spans going down the stair to the mud.".
  Observe landing_gauge at ward_landing when true "On the lowest step the Office has painted a new mark this month and a newer one this week. The Ward gauge reads {mere(bowl)} spans.".
  Observe landing_low at ward_landing when mere(bowl) <= 30 "The Mere is a long way off now. The planks over the mud have been laid three times and given up.".
  Observe landing_rising at ward_landing when state(channel_gate, to_mere) and not draining() "There is water in the lowest of the old boat-rings again. Children are standing in it, to the shin, shouting.".
  Observe children_skip at ward_landing when hour(clock) >= 15 and hour(clock) < 19 and not wardLeaving(ammerlin) "Children are skipping on the landing in the last of the sun, two turning a net-rope and one jumping, and all of them chanting: Rise at the Sixth, and the Deep goes up! Count at the Seventh, it takes its cup!".
  Rule isaura_landing at ward_landing when at(party, ward_landing) and travelsWith(isaura, party) and not knows(party, isaura_ward) says "Isaura stops on the top step. She looks at the painted spans one by one down to the mud, the way you would read down a column of figures you already know the sum of. 'I learned to swim off the fourth step,' she says. 'It's twenty-nine steps down to the water now. And the mud.' She does not say anything else, and then she does: 'Noted.'" teaches isaura_ward { }
  Discovery isaura_ward "Isaura Vant learned to swim off the Ward landing, when the Mere came up to its fourth step.".

  Observe row_scene at tench_row when not wardEmpty(ammerlin) "Tench Row: fishers' houses of tarred timber on stone feet, built for a shore that has walked away from them. Nets hang dry on every rail. Somebody is gutting the few fish there are on a door laid across two barrels, and a queue is waiting for them.".
  Observe row_leaving at tench_row when wardLeaving(ammerlin) and not wardEmpty(ammerlin) "Handcarts in Tench Row, loaded with beds and pots and nets. People are going up the Ward steps with them, and others are standing in their doors watching them go.".
  Observe row_empty at tench_row when wardEmpty(ammerlin) "Tench Row is empty. Doors stand open on bare rooms. A cat sits on a net-rail watching the Mere, which is a pond now, far off across the mud.".

  // The Ward well, which fails at thirty spans.
  Observe well_scene at ward_well when mere(bowl) > 30 "The Ward well: a round stone head with a windlass, older than the houses. The rope is let out much further than it was, by the marks on it.".
  Observe well_dry at ward_well when mere(bowl) <= 30 "The Ward well has failed. The bucket comes up with a hand of grey silt in it, and people are queuing for the water-cart from the Dyers' Terrace instead, at a copper a jug.".
  Relation wardLeaving(place). Relation wardEmpty(place).
  Rule ward_leaves when mere(bowl) <= 30 and not wardLeaving(ammerlin) says "Word comes down the terraces, and up them: the Ward well has failed. In Tench Row the handcarts are coming out." {
    Assert wardLeaving(ammerlin). }
  Rule ward_empties when mere(bowl) <= 18 and not wardEmpty(ammerlin) { Assert wardEmpty(ammerlin). }

  // Dov Vant, his yard, and the Tench.
  Observe dov_yard_scene at dov_yard when true "A fisher's yard with a smoke-house, a boat-shed, and a heap of things that are not fish: carved grey stone, green bronze, a block with a hole through it, a broken lintel with letters on it, all sorted into piles by some system of Dov's.".
  Person dov "Dov Vant" at dig {
    Greets "Dov Vant straightens up, wipes his hands on his thighs, and grins at you as if you owed him money and he liked you anyway.".
    Role "fisher of the Mere Ward, and its loudest man". Ancestry human. Calling warrior. Level 3. Peaceable. Pronouns he. Manner jovial.
  }
  Person diggers "the Ward diggers" at dig {
    Role "fishers turned diggers, with shovels and baskets". Ancestry human. Numbers 6. Peaceable.
  }
  Item ward_weight "a weight-stone" is weight_stone at dov_yard.
  Rule dov_by_day when hour(clock) == 7 and at(dov, dov_yard) and not dovHeld(dov) and not dovGrieving(dov) { Retract at(dov, dov_yard). Assert at(dov, dig). }
  Rule dov_by_night when hour(clock) == 19 and at(dov, dig) { Retract at(dov, dig). Assert at(dov, dov_yard). }
  Relation dovHeld(group). Relation dovGrieving(group).
  Thing tench "the Tench" at ward_landing {
    State afloat "Dov Vant's boat, the Tench, still floats at the end of the longest plank, in a channel the Ward has dug for her through the mud.".
    State stranded "The Tench lies on her side in the mud at the end of the planks, her channel dried to a crust.".
  }
  Rule tench_strands when mere(bowl) <= 37 and state(tench, afloat) says "Down in the Ward the last boat on the Mere has gone over on her side in the mud: Dov Vant's Tench." {
    Assert state(tench, stranded). }
  Rule tench_floats when mere(bowl) >= 39 and state(tench, stranded) { Assert state(tench, afloat). }

  Topic dov_hello with dov "Ask Dov Vant who he is" when true once {
    Says "'Who am I?' He laughs, enormous. 'I'm the Ward, friend. I'm what's at the bottom when the water's gone.' He looks you over. 'You're the Assessor. The Office's outsider. Measure told me they were getting one.' He sees you not understand. 'My sister. Isaura. I call her Measure. She hates it. She's been measuring things since she could hold a stick, she measured our mother's coffin before the joiner did.'".
  }
  Topic dov_ward with dov "Ask Dov what is happening to the Ward" when true once {
    Says "'It's being drunk.' He points up the terraces with a hand like a spade. 'Up there they've a Channel taking a fifth, and a Sounding taking their hymn out of the old order, and an Office writing it all down neat. And down here the water goes, and the fish go, and the well's going.' He spits. 'It's not drought. My grandfather's grandfather kept a mark on that landing and it never moved more than a hand in a hundred years. Somebody's taking it. Find me the somebody.'".
  }
  Topic dov_dig with dov "Ask Dov about the dig" when true once {
    Says "'The only crop left.' He is proud of it and ashamed and won't choose. 'When the Mere went back off the old temple roofs, we went out on the mud with shovels. Grey stone, carved; old bronze; weights with holes in. The scholar buys it, Halm, pays silver. Forty families eat off it now.' He lowers his voice, which is still loud. 'And there's a way down. The temple's got a throat, a well inside it, going down, and there's a wall at the bottom of the throat, and something behind the wall that hums. We'll be through it in a few days.'".
  }
  Topic dov_quill with dov "Ask Dov about Quill's agent in the Ward" when true once {
    Says "'Basset.' He says it like the name of a disease. 'Going door to door with Guild silver, buying plots off people whose well's failing. Half Tench Row's sold. He'll have the dig soon; old Marra owns the ground it's on and she's eighty and her daughter wants her up the terraces.' He breathes. 'Once Quill has the dig he'll put the bailiffs on it and dig it himself, with wages, he says. Wages. Off our own Mere.'".
    On discuss { Assert knows(actor, ward_bought). }
  }
  Discovery ward_bought "Harrow Quill's agent Basset is buying the Mere Ward plot by plot with Guild silver, and will soon have the ground under the dig.".
  Topic dov_measure with dov "Ask Dov about his sister" when true once {
    Says "His face goes still, which on Dov is like a weather change. 'She went up,' he says. 'To the Office. Clerk-Measurer, Third Grade.' He makes it sound like a disease too, and then he doesn't. 'Our father drowned off the Tench when she was twelve. Squall. She said if we'd known the wind we'd have known not to go. And she went and learned how to know things.' He shrugs. 'I stayed and learned how to go anyway. One of us had to keep the boat.'".
  }
  Topic dov_halm with dov "Ask Dov about the scholar" when true once {
    Says "'Halm's mad,' Dov says fondly. 'Good silver, though. Sits in the hole all day with his ear to the wall like a man listening to his wife through a door.' Then, less fondly: 'He told me what's behind the wall's worth more than the Ward. He didn't mean it as an insult. That's the worst of him. He never does.'".
  }

  // The danger the diggers do not see: the bottom of the throat is below the Mere's water.
  Discovery dig_below "The bottom of the Hall's throat, where the diggers are breaking at the Undercroft wall, is below the level of the Mere standing a stone's throw off. Break through, and the Mere comes in after.".
  Relation gauged(entity).
  Action gauge_dig(actor: group, site: place) "Gauge the bottom of the throat against the Mere, with Isaura's rod and level" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hall_throat) and travelsWith(isaura, actor) and not gauged(diggers).
    Time 3.
    On success { Assert gauged(diggers). }
    Result "Isaura sights along the brass level from the throat's lip to the Mere, and back down into the hole, and does the sum twice. She does not say anything for a moment. 'The bottom of that hole is three spans under the water out there,' she says. 'The silt's holding it out. When they break the wall, the silt goes, and the Mere comes down the throat after it. All of it that can.'".
  }
  Rule dig_known when gauged(diggers) and not knows(party, dig_below) says "Isaura writes it down and underlines it." teaches dig_below { }
  Relation warnedDov(group). Relation cofferdam(entity).
  Topic dov_warn with dov "Tell Dov the bottom of the throat is under the Mere" when knows(actor, dig_below) and not warnedDov(dov) and not breached(dig) once {
    Says "Dov listens with his arms folded, and you can see him wanting not to believe it, and wanting more not to be the man who drowned his diggers. 'Whose figures?' Yours; Isaura's. He looks for a long moment at nothing. 'Measure's figures.' Then, abruptly: 'Right. A dam round the throat, then, before we break. Logs and bags and mud. It'll cost us a day.' He is already shouting for Hob and the baskets. Over his shoulder: 'Tell her. Tell her I listened.'".
    On discuss { Assert warnedDov(dov). Assert cofferdam(dig). }
  }
  Relation breached(entity). Relation drowned(group). Relation digClosed(entity).
  // At six on the fourth morning, if the diggers are still at it, they break through.
  Rule breach_safe when watch(clock) >= 420 and hour(clock) == 6 and cofferdam(dig) and not breached(dig) and not digClosed(dig) and not shutBelow(dig) and mere(bowl) <= 34 and at(diggers, dig)
    says "Word comes up from the Ward at first light: the diggers are through the wall at the bottom of the Hall's throat. The dam held. Nobody was hurt, and Dov Vant is standing on top of it shouting at the sky." {
    Assert breached(dig). }
  Rule breach_drowns when watch(clock) >= 420 and hour(clock) == 6 and not cofferdam(dig) and not breached(dig) and not digClosed(dig) and mere(bowl) > 26 and not shutBelow(dig) and mere(bowl) <= 34 and at(diggers, dig)
    says "At first light there is a noise from the Ward like a door the size of a hill slammed shut, and then screaming. The diggers broke the wall at the bottom of the Hall's throat, and the silt went, and the Mere came down after it. Three were in the hole." {
    Assert breached(dig). Assert drowned(diggers). Assert dovGrieving(dov). Decrease mere(bowl) by 2. Retract at(dov, dig). Assert at(dov, dov_yard). }
  Rule breach_dry when watch(clock) >= 420 and hour(clock) == 6 and not cofferdam(dig) and not breached(dig) and not digClosed(dig) and mere(bowl) <= 26 and not shutBelow(dig) and at(diggers, dig)
    says "Word comes up from the Ward: the diggers are through the wall at the bottom of the Hall's throat. The Mere has fallen so far that there was nothing above the silt to come in." {
    Assert breached(dig). }
  Relation shutBelow(entity).
  Observe dov_grief at dov_yard when dovGrieving(dov) and at(dov, dov_yard) "Dov Vant is sitting on an upturned basket in his yard with his hands hanging between his knees. He does not get up.".
  Topic dov_drowned with dov "Say something to Dov about the diggers" when drowned(diggers) once {
    Says "'Hob Kettle,' says Dov. 'Annet Kettle, his girl, she was fifteen. And Jory Pale.' He says the names to the ground. 'They were in the hole when the wall went. Hob held the ladder for her.' He looks up at you at last, and you wish he hadn't. 'If somebody had told me,' he says. 'If anybody up there had told me anything.' Then he looks past you, to see if his sister is there.".
  }

  // Quill's agent, buying.
  Person basset "Wenn Basset" at tench_row {
    Greets "Wenn Basset tucks his ledger under his arm and gives you a smile with nothing behind it but teeth.".
    Role "agent of the Millwrights' Guild". Ancestry human. Peaceable. Pronouns he. Manner proud.
  }
  Initially Assert serves(basset, quill).
  Relation digBought(entity).
  Topic basset_buying with basset "Ask Basset what he is doing in the Ward" when true once {
    Says "'Buying,' says Basset, who has a ledger under his arm and very clean boots. 'At a fair price, in silver, to people who would like to have silver. Nobody is made to sell. Nobody is ever made to sell.' He smiles. 'Their wells are failing, of course. That isn't me.'".
    On discuss { Assert knows(actor, ward_bought). }
  }
  Rule dig_bought when watch(clock) >= 300 and not titlesFrozen(ammerlin) and not digBought(dig) says "In the Ward, an old woman called Marra Fen signs her plot over to the Guild in Basset's ledger, with her daughter's hand on her shoulder. The plot is the one the dig is on." {
    Assert digBought(dig). }
  Rule basset_stopped when titlesFrozen(ammerlin) and at(basset, tench_row) and not frozenSeen(basset) says "In Tench Row Wenn Basset reads an Office order with his mouth getting smaller, folds it into his ledger, and walks off up the Ward steps without a word to anyone." {
    Assert frozenSeen(basset). Retract at(basset, tench_row). Assert at(basset, quill_outer). }
  Relation frozenSeen(group).
  // At three on the third afternoon, the Guild's bailiffs come to the dig it now owns.
  Relation clashed(entity). Relation stoodBetween(group).
  Rule bailiffs_to_dig when digBought(dig) and able(bailiffs) and watch(clock) >= 330 and not clashed(dig) and not at(bailiffs, dig) and not sentAway(bailiffs) and not breached(dig) {
    Retract at(bailiffs, quill_outer). Retract at(bailiffs, rim_gauge). Assert at(bailiffs, dig). Set clashAt(dig) to watch(clock) + 3. }
  Measure clashAt(entity). Relation sentAway(group).
  Observe bailiffs_at_dig at dig when at(bailiffs, dig) and not clashed(dig) "Three Guild bailiffs in green coats stand on the lip of the dig with cudgels and a paper. Below them in the hole the diggers have stopped, shovels in their hands, and Dov Vant is coming up the ladder.".
  Action stand_between(actor: group, site: place) "Stand between the bailiffs and the diggers, and talk them down" {
    Description "Talk to both sides at once, before anybody swings.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, dig) and at(bailiffs, dig) and not clashed(dig) and not stoodBetween(actor).
    Time 1.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert stoodBetween(actor). Assert clashed(dig). Assert sentAway(bailiffs). Retract at(bailiffs, dig). Assert at(bailiffs, quill_outer). }
    On failure { Assert stoodBetween(actor). }
    Result "You get between them with your hands open and say the things you say, and keep saying them, until the biggest bailiff looks at the paper and at Dov and at you and decides it is not worth his wages. 'The Master'll hear of it,' he says, and they go. Dov lets out a breath that is almost a laugh.".
    Otherwise "You get between them and talk, and for a moment it holds, and then Dov says the wrong word and the biggest bailiff says a worse one, and it is not your argument any more.".
  }
  Action show_warrant(actor: group, site: place) "Show the bailiffs the Office's warrant, and tell them the dig is under assessment" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, dig) and at(bailiffs, dig) and not clashed(dig) and warranted(actor) and travelsWith(isaura, actor).
    Time 1.
    On success { Assert clashed(dig). Assert sentAway(bailiffs). Retract at(bailiffs, dig). Assert at(bailiffs, quill_outer). }
    Result "Isaura takes the warrant out of her coat and reads it aloud, all of it, in the voice of the Office, to the end, including the seal. The bailiffs listen. When she has finished the biggest of them says, 'Right,' and they go back up the Ward steps. Dov looks at his sister as if he had never seen her before.".
  }
  Rule clash_happens when at(bailiffs, dig) and able(bailiffs) and not clashed(dig) and clashAt(dig) > 0 and watch(clock) >= clashAt(dig)
    says "At the dig it comes to cudgels and shovels. It is short and ugly. When it is over, two diggers are bleeding into the mud, the bailiffs have Dov Vant down with his arms tied behind him, and they march him up the Ward steps to the Office cells. The dig is the Guild's." {
    Assert clashed(dig). Assert dovHeld(dov). Assert digClosed(dig). Retract at(dov, dig). Retract at(dov, dov_yard). Assert at(dov, office_cells).
    Retract at(diggers, dig). Assert at(diggers, tench_row). Retract at(bailiffs, dig). Assert at(bailiffs, quill_outer). }
  Place office_below "under the Office" is level within office.
  Place office_cells "the Office cells" is room within office_below at 0, 0.
  Passage cells_stair "the stair down to the cells" is stair between office_hall and office_cells.
  Observe cells_scene at office_cells when true "Three cells under the Office, cut in the rock of the terrace, dry and clean and very cold. The doors have measure-marks on them, as if somebody had once worried about the cells being given short.".
  Topic dov_held with dov "Ask Dov what happened at the dig" when dovHeld(dov) once {
    Says "Dov sits on the cell's bench with a split lip and a look of enormous calm. 'They had a paper,' he says. 'Old Marra's plot, Guild's now. I told them where to put the paper.' He touches his lip. 'Ask my sister if she'll sign my release. Ask her. I want to hear what she says.'".
  }
  Relation released(group).
  Topic dov_release with dov "Tell Dov he is free to go" when dovHeld(dov) and travelsWith(isaura, actor) and not released(dov) {
    Says "Isaura unlocks the cell herself. She does not say anything, and neither does he, until he is past her in the door, and then he stops and puts his big hand on top of her head for a moment, the way you would with a child, and goes up the stair. She stands there. 'Noted,' she says, to nobody.".
    On discuss { Assert released(dov). Retract dovHeld(dov). Retract at(dov, office_cells). Assert at(dov, dov_yard). Assert reconciled(isaura). }
  }
  Relation reconciled(group).
}

data/adventures/low-water/wheels.kyr:
Module lowwater "Low Water" {
  Description "The nine wheels of the count, each in its own room off the counting gallery: what each one counted, the seventh turning now, and behind a grille at the end the ninth, and what it holds.".

  Place wheels_level "the wheel-rooms" is level within undercroft.
  Place w_makers "the room of the first wheel" is room within wheels_level at 0, 0 underground.
  Place w_beasts "the room of the second wheel" is room within wheels_level at 1, 0 underground.
  Place w_aeneans "the room of the third wheel" is room within wheels_level at 2, 0 underground.
  Place w_dead "the room of the fourth wheel" is room within wheels_level at 3, 0 underground.
  Place w_living "the room of the fifth wheel" is room within wheels_level at 4, 0 underground.
  Place w_waters "the room of the sixth wheel" is room within wheels_level at 5, 0 underground.
  Place w_unborn "the room of the seventh wheel" is room within wheels_level at 6, 0 underground.
  Place w_unborn_face "the face of the seventh wheel" is room within wheels_level at 6, 1 underground.
  Place w_planes "the room of the eighth wheel" is room within wheels_level at 7, 0 underground.
  Place w_remainder "the room of the ninth wheel" is room within wheels_level at 8, 0 underground.
  Place foundry "the Equals' foundry" is room within wheels_level at 3, 1 underground.
  Initially Assert unlit(w_makers). Initially Assert unlit(w_beasts). Initially Assert unlit(w_aeneans). Initially Assert unlit(w_dead).
  Initially Assert unlit(w_living). Initially Assert unlit(w_waters). Initially Assert unlit(w_unborn). Initially Assert unlit(w_unborn_face).
  Initially Assert unlit(w_planes). Initially Assert unlit(w_remainder). Initially Assert unlit(foundry).

  Passage arch_makers "the first arch off the gallery" is arch between count_gallery and w_makers.
  Passage arch_beasts "the second arch" is arch between count_gallery and w_beasts.
  Passage arch_aeneans "the third arch" is arch between count_gallery and w_aeneans.
  Passage arch_dead "the fourth arch" is arch between count_gallery and w_dead.
  Passage arch_living "the fifth arch" is arch between count_gallery and w_living.
  Passage arch_waters "the sixth arch" is arch between count_gallery and w_waters.
  Passage arch_unborn "the seventh arch" is arch between count_gallery and w_unborn.
  Passage arch_planes "the eighth arch" is arch between count_gallery and w_planes.
  Passage arch_remainder "the ninth arch" is arch between count_gallery and w_remainder.
  Passage foundry_door "a low door behind the fourth wheel" is doorway between w_dead and foundry.

  // Each room counted one kind of the bound, and says which by a sign cut over its wheel, as the keystone does.
  Observe makers_scene at w_makers when true "A tall narrow room, and in it a wheel of bronze and grey stone as high as the room, locked, its gates shut. Over it, cut deep: a hand, open, with a tally-stick laid across the palm. Every surface of the room is covered with tally-marks in groups of nine, floor to ceiling, so fine and so many that from the door the walls look grey. There is not one picture, not one name. Whoever was counted here was counted only as marks.".
  Observe beasts_scene at w_beasts when true "The second wheel is locked like the first. Over it, a sign of four legs and a head, which could be any beast. The floor of this room is soft, and you see why: it is fur, or was, a drift of grey down a hand deep that crumbles to nothing when you breathe on it. In the wall above the wheel, one window of glass the size of a coin, and behind the glass a single small bone.".
  Observe aeneans_scene at w_aeneans when true "The third wheel. Over it, an ear: the Aeneans. The wheel is locked, and stopped, and stopped early: its last gate is still half open, as if the count had been cut off in the middle of a stroke. On the floor in front of it someone has set out, in a careful row, nine small clay figures of singers with their mouths open, the way Abel Tarrant set out his keepers. The ninth is unfinished.".
  Observe dead_scene at w_dead when true "The fourth wheel, the largest yet, so large the room is built round it like a husk round a seed. Over it, an eye, shut. Its gates are locked, and in every gate, where the water stood when it locked, is a skin of something dry and grey like the inside of an eggshell. The cold here is not the cold of stone. A low door behind the wheel goes on into the dark, and from it, faintly, comes the smell of hot metal.".
  Observe living_scene at w_living when true "The fifth wheel. Over it, an eye, open. This wheel locked last of the six, and not long ago: its gates are still wet, and drip, and the drips run down the wheel's spokes and gather in the channel and go away. The sound of it is the only sound in the room: like a room full of people breathing in their sleep.".
  Observe waters_scene at w_waters when true "The sixth wheel. Over it, a drop of water falling. The channel round this wheel is not dry: it holds black water, perfectly still, and in it, looking down, you see faces, a great many, one behind another down into the dark, as if the water were a window. None of them is reflected from the room. One of them, quite near the surface, is old Marra Fen of the Ward, who sold her plot, and is alive, and asleep in her daughter's house on the Dyers' Terrace.".
  Discovery wheels_counted "Each of the Reckoner's wheels counted one kind of the bound, and its sign is cut over it: the makers, as marks; beasts; the Aeneans, cut off early; the dead; the living; the waters and those in them; the unborn, turning now; the eighth, waiting; and the ninth, behind a grille.".
  Rule wheels_learned when (at(party, w_dead) or at(party, w_living) or at(party, w_waters)) and been(party, w_makers) and not knows(party, wheels_counted)
    says "You understand the gallery all at once, the way you understood the keystone: a wheel for each kind of thing that is bound, body to breath, and each one counted out and locked." teaches wheels_counted { }
  Topic isaura_wheels with isaura travelling "Ask Isaura what she makes of the wheel-rooms" when knows(actor, wheels_counted) once {
    Says "'Columns.' Isaura's voice is not steady and she does not try to make it be. 'It's a ledger with nine columns, and somebody has filled in six of them. The makers. Beasts. The Aeneans, cut short. The dead. The living, just closed.' She stops. 'The living. That's us. We've been counted. Every one of us, in that room with the wet gates, and it locked.' She looks at her own ledger as if it might do the same. 'And the one turning now is the people who haven't been born.'".
  }

  // The seventh wheel is turning: the unborn, counted in bright notes. Its gates flood the room's face in a slow
  // round, open one watch in three; whoever is at the face when the gates come round is put back into the room by
  // the water.
  Measure tide(engine). Measure tideAt(engine).
  Rule seventh_turns when not complete(reckoner) and not broken(reckoner) and watch(clock) >= tideAt(reckoner) {
    Increase tide(reckoner) by 1. Set tideAt(reckoner) to watch(clock) + 1. }
  Rule seventh_round when tide(reckoner) >= 3 { Set tide(reckoner) to 0. }
  Observe unborn_scene at w_unborn when not complete(reckoner) and not broken(reckoner) "The seventh wheel is turning. It fills the room, going round slowly, and water comes in at its top through a hundred little gates and goes out at its foot, and every time a gate shuts it rings, a bright note, small, like a drop falling into a full cup. The notes never stop. Over the wheel, the sign: a curled thing, a seed or a child asleep. Beyond the wheel a ledge goes round to its face, and every few moments the gates come round and the ledge goes under in a smooth sheet of water and comes out again, streaming.".
  Observe unborn_done at w_unborn when complete(reckoner) or broken(reckoner) "The seventh wheel has stopped. The little gates are shut, every one, and there is no sound in the room at all. You had not known how loud the bright notes were until they were gone.".
  Passage unborn_ledge "the ledge round to the wheel's face" is passage between w_unborn and w_unborn_face taking 1 minute
    opening when tide(reckoner) == 0 or complete(reckoner) or broken(reckoner) "The ledge round to the face of the wheel is under a running sheet of water. In a moment the gates will come round again.".
  Hazard gate_sheet "The seventh wheel's water" means "Deal (2d6) physical damage to ally unless dexterity save against (13).".
  Measure atFace(group). Relation faceMarked(group).
  Rule face_arrived when at(party, w_unborn_face) and not faceMarked(party) { Set atFace(party) to watch(clock). Assert faceMarked(party). }
  Rule face_left when faceMarked(party) and not at(party, w_unborn_face) { Retract faceMarked(party). }
  Rule face_flooded when at(party, w_unborn_face) and faceMarked(party) and tide(reckoner) != 0 and watch(clock) > atFace(party) and not complete(reckoner) and not broken(reckoner)
    says "The gates come round. The sheet of water comes over the ledge and the face of the wheel together and takes you with it, back round the ledge in a rush, and puts you down on the floor of the room, gasping, with the bright notes ringing all round you." {
    Assert strikes(gate_sheet, party). Retract at(party, w_unborn_face). Assert at(party, w_unborn). }
  Observe face_scene at w_unborn_face when true "The face of the seventh wheel, close: not a face at all but a dial, a great disc of grey stone ringed with marks, and a pointer of bronze going round it very slowly, and in the middle of the dial a single word in the oldest marks, cut so deep you could put your hand in it.".
  Discovery unborn_read "The dial at the face of the seventh wheel is reading what will be bound, the unborn, and its pointer is three parts round. In the middle of the dial, one word in the oldest marks, which the glossary gives as: OWED.".
  Thing dial "the seventh wheel's dial" at w_unborn_face {
    State turning "The bronze pointer goes round the dial so slowly you can only see it move by looking away and back.".
    Tries looking.
  }
  Rule dial_read when tried(dial, looking) and not knows(party, unborn_read)
    says "You read it as you read the gauges on the Dyers' Terrace: the marks round the rim are a count, and the pointer stands three parts of the way round. The word in the middle is a single mark, cut so deep the dark sits in it. The glossary, or Halm, would say it means OWED." teaches unborn_read { }

  // The eighth wheel waits, dry.
  Observe planes_scene at w_planes when true "The eighth wheel stands dry in a dry channel, every gate open, waiting for water that has not yet come to it. Over it, the sign is not one thing but many: nine circles, overlapping, in a ring, each touching the next, like the links of a chain laid in a round. The floor of the room is cut with the same nine circles, very large, and you are standing in one of them. Halm, if he were here, would not be able to speak.".
  Discovery planes_wheel "The eighth wheel, waiting dry, bears the sign of nine circles linked in a ring: the planes of the settlement. After the bound things of Imbar, the count was to reckon the binding of the world itself.".
  Rule planes_seen when at(party, w_planes) and not knows(party, planes_wheel) says "Nine circles, linked, in a ring. You have heard the priests' account of the settlement: the planes divided among the powers by the Arbiters, and fastened." teaches planes_wheel { }

  // The ninth: behind a grille that nothing on this side can open, the Remainder.
  Observe remainder_scene at w_remainder when not complete(reckoner) and not broken(reckoner) "The ninth arch is closed by a grille of bronze bars as thick as a wrist, set in the stone, with no lock and no hinge. Through it: a small round room, and in it a wheel, small, the smallest of the nine, with nine sockets round its rim like the setting of a ring. Eight of the sockets are empty and dark. In the ninth, something holds a light that is not lamplight: a stone the size of an egg, faceted, that is all the colours a deep water is when the sun goes into it, and moving, slowly, as if it were breathing.".
  Observe remainder_cold at w_remainder when not complete(reckoner) and not broken(reckoner) "The cold here is the cold that came off the Reflected on the landing. You feel it under your ribs. The stone in the socket is looking at you, or something in it is.".
  Discovery remainder_seen "Behind the grille of the ninth arch, set in the smallest wheel of the Reckoner, is a faceted stone that holds its own light and breathes; eight more sockets beside it are empty. The cold that comes off it is the cold of the Reflected.".
  Rule remainder_learned when at(party, w_remainder) and not knows(party, remainder_seen) says "You stand at the grille a long time. Nobody says anything." teaches remainder_seen { }
  Topic halm_remainder with halm "Tell Halm what is set in the ninth wheel" when knows(actor, remainder_seen) once {
    Says "Halm does not interrupt once. When you have done he takes off his spectacles, which you did not know he wore, and cleans them on his coat until the lenses squeak. 'Nine sockets,' he says. 'Eight empty. One full, and breathing, and cold.' He puts them back on. 'There is an old tale about nine jewels.' He starts to tell it, and does not. 'Owed, the dial says. And over the door: what is counted is given.' He is looking at the grille and not at you. 'Assessor, I don't think anybody has ever read it to the end. I think it is waiting to be.'".
    On discuss { Assert knows(actor, auditor_known). }
  }
  Discovery auditor_known "The thing beyond the last door is not a stranger reading the count: it is the Varakiir whose heart is the jewel bound in the Reckoner's ninth wheel. When the count is whole and the door opens, what is counted is given: its heart goes through to it, and the Reflected are its hands until then.".
  Topic isaura_auditor with isaura travelling "Ask Isaura what she makes of the jewel in the ninth wheel" when knows(actor, auditor_known) once {
    Says "'A deposit.' Isaura says it at once, and then hears herself, and does not take it back. 'That's what it is, in a ledger. Something held against an account, to be returned when the account is closed.' She walks the length of the room and back. 'Somebody put a lake on top of it, and a city round the lake, and a choir on the city. For a deposit.' She stops. 'To hand it back. Or to be able to say it was not yet due.'".
  }
  Topic orr_auditor with orr "Tell Cantor Orr what is in the ninth wheel, and what the Reflected are" when knows(actor, auditor_known) once {
    Says "Cantor Orr hears you out with her eyes on the floor. 'Its hands,' she says. 'The things on the landing, singing the Rising in my hymn's voices. Its hands, made of our water.' She looks up, and she is not frightened; she is furious. 'And Pell, in Corran, with his learned notes. Omit.' She stands. 'Then this is a war, and I've a choir. Tell me what to sing.'".
  }

  // The Equals' foundry, behind the fourth wheel.
  Observe foundry_scene at foundry when true "A long low room, warm, where no room under the Mere should be warm, with a channel of water going through it so hot it steams. Along the walls, on stone benches, Equals: not finished. One without arms. One without a head, its neck a smooth stump. One complete but for its hands, which lie beside it on the bench, flat, palms down. At the end of the room, on an anvil of the grey stone, a slate with marks on it in the oldest hand.".
  Discovery foundry_read "The slate in the Equals' foundry, read with the old script: MADE TO KEEP THE FLOOR LEVEL. MADE TO KEEP THE COUNT EVEN. MADE TO KEEP WHAT IS SET IN THE NINTH. IF IT WAKES, TAKE OFF WHATEVER WEIGHS IT TOWARD THE DOOR." {
    Found by searching foundry with lore "The marks on the slate come clear with the glossary: MADE TO KEEP THE FLOOR LEVEL. MADE TO KEEP THE COUNT EVEN. MADE TO KEEP WHAT IS SET IN THE NINTH. IF IT WAKES, TAKE OFF WHATEVER WEIGHS IT TOWARD THE DOOR.".
  }
  Item spare_hands "a pair of bronze hands" is weight_stone at foundry.
  Observe hands_here at foundry when at(spare_hands, foundry) "The unfinished Equal's hands lie on the bench, heavy, flat, palms down.".
  Topic isaura_foundry with isaura travelling "Ask Isaura what the slate in the foundry means" when knows(actor, foundry_read) once {
    Says "'They're not clerks,' says Isaura. 'I was wrong.' She sounds almost relieved to have been wrong about something small. 'They're warders. The floor and the count are just what they do while they wait. What they're for is the thing in the ninth wheel.' She thinks. 'Take off whatever weighs it toward the door. That's us, isn't it, if we're carrying it there. That's anyone.'".
  }
}

data/adventures/muster/beasts.kyr:
Module muster "The Long Muster's Road" {
  // ── The beasts of the road ──────────────────────────────────────────────────────────────────────────────────────
  // The goats know the sound stone; the kites know what will fall; the marmots know the giant's mood; the wolves know
  // the dark; the wyvern knows noon. A company that reads them can go where one that fights them cannot.
  Relation kitesRead(group). Relation wolvesTolerated(group). Relation paidDeserters(group).
  Relation aurelMet(group).

  // ── Ridge-goats ─────────────────────────────────────────────────────────────────────────────────────────────────
  Person goat_steep "a ridge-goat" at track1 {
    Role "grey, on a rock, chewing". Species ridge_goat. Numbers 1. Peaceable.
  }
  Person goat_ledge "a ridge-goat" at ledge1 {
    Role "grey, standing on the line of the Ledge, in the lee". Species ridge_goat. Numbers 1. Peaceable.
  }
  Person goat_shale "a ridge-goat" at pass_n {
    Role "grey, below the crag, watching the shale". Species ridge_goat. Numbers 1. Peaceable.
  }
  Observe goat_sign at track1 as sign when true "Where the path starts to climb the droppings are in a line, and every dropping is on a stone that does not move.".
  Action follow_goat_steep(actor: group, site: place) "Follow the ridge-goat up the steep, setting your feet where it sets its hooves" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, track1) and at(goat_steep, track1).
    Time 3.
    On success { Assert at(actor, track2). }
    Result "It goes up the face as if the face were a stair, looking back twice with an expression of faint contempt, and you go up where it went and nowhere else. Every foot it uses holds. When you come to the top it is already standing on the next rock, chewing.".
  }
  Thing ledge_wind "the wind off the Ledge" on ledge_a {
    State gusting dangerous "Wind comes along the Ledge in sudden shoves, from the open side, with nothing to lean on.".
    State steady "The wind has gone to a steady lean, and you have the measure of it.".
    Hurts with ledge_gust when gusting then steady.
  }
  Hazard ledge_gust "The Ledge's gusts" means "Deal (2d6) physical damage to ally unless dexterity save against (13).".
  Action walk_goat_line(actor: group, site: place) "Walk where the ridge-goat walks, on the inside, and wait when it waits" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ledge1) and at(goat_ledge, ledge1) and state(ledge_wind, gusting).
    Time 1.
    On success { Assert state(ledge_wind, steady). }
    Result "The goat stands in the lee of every buttress and does not step out until the gust has gone by, and you learn to do the same. By the third buttress you can feel the next gust before it comes, as a goat does, and your back is to the rock when it arrives.".
  }
  Action follow_goat_shale(actor: group, site: place) "Follow the ridge-goat up the shale, in its steps" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pass_n) and at(goat_shale, pass_n) and state(goat_slide, loose).
    Time 1.
    On success { Assert state(goat_slide, trodden). }
    Result "It goes up the slope in a long, unhurried zigzag, a hoof here and a hoof there, never across the fall line. You put your boots in its prints. The shale slides under the goat's step and under yours, and settles, and holds.".
  }

  // ── Bone-kites on the Viaduct ──────────────────────────────────────────────────────────────────────────────────
  Person kites "the bone-kites" at via_n {
    Role "five bone-kites on the Viaduct, perched and circling". Species bone_kite. Numbers 5. Peaceable.
  }
  Discovery kites_known "The bone-kites perch only on the parapet's sound blocks, and circle the fallen arch, where nothing will bear them.".
  Observe kite_sign at via_n as sign when true "Rust-backed birds sit along the broken edge of the Viaduct in a row, each on its own block, shifting their feet. Over the fallen arch below three more hang on the draught without a wingbeat, circling a slope of blocks that none of them will land on.".
  Action read_kites(actor: group, site: place) "Watch where the kites settle, and where they will not" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, via_n) and not kitesRead(actor).
    Time 3.
    On success { Assert kitesRead(actor). Assert state(parapet_wind, rigged). }
    Result "You watch them an hour. They settle on the parapet in the same places every time, like men taking their old seats, and not once on any block that has a crack in it. The blocks they use run in a line along the parapet's inner edge. You note the line.".
  }
  Observe kite_known near kites when kitesRead(party) "The kites sit where they always sit. You know now which blocks they trust, and so do you." teaches kites_known.

  // ── Marmots in the Pass: one whistle for a stranger, two for the giant ─────────────────────────────────────────
  Person marmots "the marmots of the Pass" at pass_n {
    Role "a colony of marmots on the scree, up on their haunches". Species pass_marmot. Numbers 6. Peaceable.
  }
  Discovery marmots_known "The marmots whistle once at a stranger and twice at the giant, and the whole colony dives into the ground at the second: when they are gone, he is awake.".
  Observe marmot_once at pass_n as sound when dark() "A single whistle off the scree, thin as a kettle. Then nothing: the colony has gone to ground, and the notch is the giant's.".
  Observe marmot_twice at pass_n as sound when not dark() "A whistle, and a second on its heels, and the whole slope empties. Every marmot has gone into the ground at once, and the scree is bare, and somewhere above the notch a large door is being opened." teaches marmots_known.

  // ── The wolves of the Old Causeway: dangerous, and three ways not to meet them ─────────────────────────────────
  Action hold_wolves_flame(actor: group, site: place) "Stand together with lit torches, and let the pack look at the flame" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, causeway2) and at(wolves, causeway2) and able(wolves) and capable(actor, flame) and not tolerates(wolves, actor).
    Time 0.
    On success { Assert tolerates(wolves, actor). Retract warned(wolves, actor). Assert wolvesTolerated(actor). }
    Result "You close up back to back with the torches held out and high, and the pack sits at the edge of the light and watches. One wolf gets up, circles, and lies down. They do not like the fire. They like it better than you.".
  }
  Action feed_wolves(actor: group, site: place) "Throw the pack three days' rations and walk on while they fight over it" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, causeway2) and at(wolves, causeway2) and able(wolves) and quantity(actor, rations) >= 3 and not tolerates(wolves, actor).
    Time 0.
    On success { Decrease quantity(actor, rations) by 3. Assert tolerates(wolves, actor). Retract warned(wolves, actor). Assert wolvesTolerated(actor). }
    Result "The meat goes out into the heather and the dark moves after it. You are, for as long as it takes, a thing that smells like less than dinner. You do not hurry, and you do not look back.".
  }
  Action shelter_picket(actor: group, site: place) "Climb into the legion's picket-tower and pull the ladder up after you" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, causeway3) and dark() and holding(actor, rope) and not wolvesTolerated(actor).
    Time 0.
    On success { Assert wolvesTolerated(actor). }
    Result "The picket-tower is one room, roofless, ten feet up a wall of squared stone, with a stone ladder-socket the legion's sentries used. A rope over the lip does the same. Below, in the heather, the pack walks round it twice, and sits down, and in the morning is gone.".
  }
  Observe picket_note at causeway3 as sign when true "The guard-post's tower has one wall standing to twice a man's height, and a ring-bolt cut in it. Wolf-marks go round its foot in a smooth path, as if it were a thing they had walked round every night since the legion left.".

  // A party that walks the causeway unanswered is not let walk it: the pack comes in at the end of the heather.
  Relation wolfBitten(group).
  Hazard wolf_rush "The pack closes on the road" means "Deal (2d8) physical damage to ally unless dexterity save against (14).".
  Rule wolves_rush when at(party, causeway3) and not wolvesTolerated(party) and not wolfBitten(party) and able(wolves) and not dead(wolves)
    says "The long note goes up behind you, and the heather moves. They have walked the ridge with you the whole way, and now they come in all at once." { Assert strikes(wolf_rush, party). Assert wolfBitten(party). }
  Rule wolves_rush_back when at(party, causeway1) and not wolvesTolerated(party) and not wolfBitten(party) and hour(clock) >= 18 and able(wolves) and not dead(wolves)
    says "At the head of the causeway the dark fills with sitting shapes." { Assert strikes(wolf_rush, party). Assert wolfBitten(party). }

  // ── The wyvern: noon, wind, and an empty nest ──────────────────────────────────────────────────────────────────
  Relation wyvernOut(group).
  Rule wyvern_leaves when hour(clock) >= 11 and hour(clock) < 14 and not state(sky, wind_sky) and at(wyvern, eyrie) and not dead(wyvern) {
    Retract at(wyvern, eyrie). Assert wyvernOut(wyvern). }
  Rule wyvern_thief when wyvernOut(wyvern) and at(party, eyrie) and holding(party, dragons_tooth) and not dead(wyvern)
    says "A shadow takes the sun off the shelf. It has not gone far, and it knows to the grain what was in its bed." { Assert at(wyvern, eyrie). Retract wyvernOut(wyvern). Assert strikes(wyvern_stoop, party). }
  Rule wyvern_returns when hour(clock) >= 14 and wyvernOut(wyvern) and not dead(wyvern) {
    Assert at(wyvern, eyrie). Retract wyvernOut(wyvern). }
  Observe nest_empty at eyrie when wyvernOut(wyvern) "The nest is a bed of charred bracken on a shelf, empty. Whatever slept in it left an hour ago, and left the heat of it behind.".
  Observe eyrie_bones at eyrie as sign when not dead(wyvern) "A scatter of bones, some of sheep, some of goat, one of a mule. Amongst them a rag of red cloth, bleached nearly white, and a rusted spear-head.".
  Item eyrie_pouch "a courier's pouch, sun-bleached to bone" is courier_pouch at eyrie.
  Item eyrie_ward "a wardstone in a nest of bracken" is wardstone at eyrie.
  Item eyrie_tooth "a shed tooth, long as a finger" is dragons_tooth at eyrie.
  Item eyrie_tag "a courier's tag of lead, pierced, on a rotted cord" is courier_tag at eyrie.
  Kind courier_tag "a courier's lead tag" is document teaching cato_read described "A lead tag stamped with a wheel and a name, hung on the neck of the courier of the year 503, who went north and did not come back.".
  Discovery cato_read "The tag reads: CATO, COURIER, THE SENDING OF THE YEAR 503. The Annals say that he was lost at the Eagle, and that his pouch was not found.".

  // ── Deserters at the head of the Descent ───────────────────────────────────────────────────────────────────────
  // Men of the Last Cohort who would not be Sent: a courier is chosen by lot, goes to the Eagle and comes home with
  // nothing, one spring of nothing is enough for some, and they have gone round it. They hold the end of the road and take a
  // toll of anyone who comes down it, in the name of a Cohort they have walked out on.
  Person deserters "the deserters of the Descent" at pass_s {
    Role "three of the seven deserters of the Last Cohort in patched red, spears across their knees". Ancestry human. Calling warrior. Level 3. Numbers 3. Temperament territorial.
    Warns "Three men in cloaks that were red come out of the rocks on both sides of the road with their spears down. 'Toll,' says the tallest. 'Ten.' He considers it. 'Or a word from the north.'".
    Comes "The deserters come off the rock together, spears level.".
    Lair pass_s.
    State toll blocking "Three deserters of the Last Cohort stand across the head of the Descent, spears down. The road goes through them.".
    State stood_aside "The deserters sit on the rocks with their spears across their knees, and the road is open.".
    Guards descend_in.
  }
  Rule deserters_stand_aside when tolerates(deserters, party) and state(deserters, toll) { Assert state(deserters, stood_aside). Retract warned(deserters, party). }
  Person aurel "Aurel Merula" at pass_s {
    Role "who leads the men who left the Sending". Ancestry human. Calling ranger. Level 4. Pronouns he. Manner grim. Peaceable.
    Greets "A lean man in a red cloak gone brown sits on a boulder with a bow across his back and does not come down. 'Pay,' he says. 'Or don't tell the Prefect. Which are you?'".
  }
  Action pay_deserters(actor: group, site: place) "Pay the deserters their ten coin" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pass_s) and at(deserters, pass_s) and able(deserters) and quantity(actor, gold) >= 10 and not tolerates(deserters, actor).
    Time 0.
    On success { Decrease quantity(actor, gold) by 10. Assert tolerates(deserters, actor). Retract warned(deserters, actor). Assert paidDeserters(actor). }
    Result "The tall one counts the coin into a helmet. 'They paid,' he says over his shoulder. The spears go up.".
  }
  Action show_aurel_letter(actor: group, site: place) "Hold up the pouch addressed to the Centurion Lucilla Merula" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pass_s) and at(deserters, pass_s) and able(deserters) and holding(actor, aurel_letter_kind) and not tolerates(deserters, actor).
    Time 0.
    On success { Assert tolerates(deserters, actor). Retract warned(deserters, actor). Assert aurelMet(actor). }
    Result "Aurel Merula comes down off the boulder faster than he meant to. He reads the superscription, in his own hand, nine years old. 'Where was that?' he says. 'The Eagle. I left it on the stack the spring I went over.' He takes it. 'They never touch another man's. It was a rule.' The spears go up.".
  }
  Topic aurel_why with aurel "Ask Aurel why he left the Cohort" when aurelMet(party) or tolerates(deserters, party) {
    Says "'The lot fell on me,' says Aurel. 'Twenty-six. I took the pouch to the Eagle and wrote my mother a letter and left it on the stack. Then I went over the parapet on a rope.' He rubs his jaw. 'There's a village. Thirty houses and a trough. A woman on a stone, goats. I stood in the willows till dark. Didn't call.' He eyes the road. 'I came back over. Couldn't go home and say. I came here.'".
    On discuss { Assert aurelMet(party). Assert knows(actor, aurel_known). }
  }
  Entity aurel_known: fact "Aurel Merula, who deserted the Sending, crossed the Viaduct by its parapet and saw a village of thirty houses round a trough on the north bank. He has never been able to tell his mother, the Centurion.".
  Topic aurel_mother with aurel "Ask Aurel what he would say to his mother" when aurelMet(party) once {
    Says "'That the boots held,' says Aurel, and does not seem to know why he said it. He turns the pouch over. 'She'll be on the wall at the evening call. She won't ask. Don't tell her unless she asks.'".
  }
  Kind aurel_letter_kind "a courier's pouch addressed to Lucilla Merula" is document teaching aurel_letter_read described "A leather pouch, sealed with a wheel, addressed in a young man's square hand: TO THE CENTURION LUCILLA MERULA, FIRST CENTURY, FROM HER SON M. It has waited at the Eagle for nine springs.".
  Discovery aurel_letter_read "The pouch is a son's letter to his mother, left on the Eagle's stack nine springs ago: he means to cross the fifth arch to see what is there, and if he lives he will be in the Pass.".
  Item aurel_letter_item "a courier's pouch addressed to Lucilla Merula" is aurel_letter_kind at eagle.

  // A pardon the stranger can win and cannot finish: the six go home, and the one who counted them out does not.
  Rule pardon_marches when pardoned(party) and at(deserters, pass_s)
    says "In the morning six men in cloaks that were red go down the Descent with their spears on their shoulders, not looking back, and not quickly." { Retract at(deserters, pass_s). }
  Observe aurel_stays at pass_s when pardoned(party) "Aurel Merula sits on his boulder with the Centurion's pardon folded small in his hand. The others have gone. 'It is for the others,' he says, when you ask. 'I was the one who counted them out. A pardon is for a man who can be forgiven by people he can stand to see.'".
}

data/adventures/muster/cohort.kyr:
Module muster "The Long Muster's Road" {
  // ── The Last Cohort: two thousand people who were left to hold a road ────────────────────────────────────────────
  // Eleven hundred and four years of the last emperor's reign (they count no other). A rearguard of nine hundred
  // was told to hold the valley until the General sent for it; he did not send. They became a town: wheat on the
  // terraces, vines, salt-oxen, a school that teaches the March by heart, a granary kept on a rota, a Sending of one
  // courier north every spring on a lot, and a standard in the forum that every soul in the valley salutes at the
  // fourth hour. Three parties keep the faith in three ways: the Eagles (who hold the standard and the discipline),
  // the Hearth (who hold the fields, and doubt) and the Archive (who have counted, in private, every unanswered
  // spring). The company arrives into that. It may be received as a courier, as a clerk, as a liar or as a thief; it
  // may tell, or not tell; and what it does with the truth is the point of the road.
  Discovery empire_gone "The empire the Cohort serves has been dust for eleven hundred years.".
  Discovery cohort_law "The Muster's law holds the valley: the Prefect rules by the last emperor's regnal year, a courier goes north every spring, and no answer has come.".
  Discovery cohort_factions "The Last Cohort keeps its faith in three parties: the Eagles, who hold the standard; the Hearth, who hold the fields and doubt; and the Archive, who count the springs.".
  Relation received(group). Relation gateRebuffed(group). Relation merulaFull(group). Relation admitted(group). Relation claimedRelief(group). Relation dispatchTaken(group).
  Relation told_prefect(group). Relation told_ostrander(group). Relation told_merula(group). Relation told_elpis(group). Relation traded_only(group).
  Relation valleyTold(group). Measure toldAt(group). Relation scoutGiven(group). Relation pardoned(group). Relation merulaKnowsSon(group).
  Relation goldReturned(group). Relation sealNoted(group). Relation doseTold(group). Relation hobbeShut(group). Relation hearthOwes(group). Relation brandShut(group). Relation brandTold(group). Relation prefectReadSeal(group). Relation forgeryKnown(group).
  Relation orsaConfessed(group). Relation gaiusPontus(group). Relation liviaMapped(group). Relation hobbeFreed(group). Relation gaiusSecret(group).

  // ── The gate: a challenge in a language the company probably cannot speak ───────────────────────────────────────
  Person sentries "the sentries of the gate" at gate {
    Role "four soldiers of the Last Cohort in red cloaks, on the wall". Ancestry human. Calling warrior. Level 3. Numbers 4. Temperament territorial.
    Warns "A voice from the wall rings out in an Aenean so formal it sounds like singing. A spear comes down across the road. 'Quis venit? Give the word, or the pouch.' It means: who comes?".
    Comes "The sentries come down off the wall at the double.".
    Lair gate.
    State challenging blocking "Four soldiers of the Last Cohort stand across the gate with their spears crossed.".
