  Action wk_attend(actor: group, site: place) "Ask Mr Fettiplace to take a chair beside the cage for a quarter of an hour" {
    Speaker wk_fettiplace.
    Requires able(actor) and company(actor) and at(actor, site) and at(wk_fettiplace, site) and not wk_closed(actor).
    Time 5 minutes.
    On success { Set wk_attend_until(wk_fettiplace) to watch(clock) + 9. }
    Result "'A parrot,' says Mr Fettiplace, sitting, and taking a pencil from behind the left ear. 'I have been shown a good many worse witnesses.' He opens the notebook at the ribbon, and looks at the cage with the patient face of a man being offered a hymn.".
  }

  // Arguing, reading, and the settlement
  Action wk_read_widows(actor: group, site: place) "Watch the two Rosalinds receive the mourners, and the mourners receive them" {
    Requires able(actor) and company(actor) and at(actor, site) and at(wk_rosalind, site) and at(wk_lodger, site) and not knows(actor, wk_meant).
    Time 20 minutes.
    Resolve check(actor, insight, dc_fair).
    On success { Assert knows(actor, wk_hands). Assert knows(actor, wk_trunk). Assert knows(actor, wk_tea). }
    Result "You watch for twenty minutes. The Admiral takes condolences like a bill of lading: signed, and stowed. Miss Harbottle takes them with her hands in her lap, palms up, and is touched by none of them. The one has a house. The other has a trunk, a hundred yards behind her eyes.".
    Otherwise "You watch for twenty minutes. Two women in black accept sympathy and sherry. You could not swear to a thing.".
  }
  Rule wk_put_together when knows(party, wk_tea) and knows(party, wk_trunk) and knows(party, wk_hands) and not knows(party, wk_meant) says "The tea nobody drank, the trunk nobody unpacked, and the hands: put together, they say the same thing, and it is not what the sherry says. He meant the lodger." teaches wk_meant { }

  Action wk_argue_lodger(actor: group, site: place) "Put it to Mr Fettiplace that Mr Teague meant the lodger, and why" {
    Speaker wk_fettiplace.
    Requires able(actor) and company(actor) and at(actor, site) and at(wk_fettiplace, site) and knows(actor, wk_meant) and not wk_closed(actor) and not wk_argued(actor).
    Time 15 minutes.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert wk_heardL(actor). Assert wk_argued(actor). }
    On failure { Assert wk_argued(actor). Assert wk_suspicious(wk_fettiplace). }
    Result "'The tea, the trunk and the hands,' says Mr Fettiplace slowly, writing each of them. 'It is a very good deal of nothing, set out beautifully.' He draws a line under it. 'But it all points the same way, and I distrust evidence that does not.'".
    Otherwise "'That is the sort of thing,' says Mr Fettiplace, 'that is said to me by the interested.' He closes the notebook on his finger. 'I shall be wanting to hear it from a witness who is not.'".
  }
  Action wk_split(actor: group, site: place) "Propose to Mr Fettiplace that the four hundred be divided, and pay the Providence's fee for a compromise (12 coin)" {
    Speaker wk_fettiplace.
    Requires able(actor) and company(actor) and at(actor, site) and at(wk_fettiplace, site) and wk_wifeAgrees(actor) and wk_lodgerAgrees(actor) and quantity(actor, gold) >= 12 and not wk_closed(actor).
    Time 20 minutes.
    On success { Decrease quantity(actor, gold) by 12. Assert wk_closed(actor). Assert wk_settled(actor). Assert wk_paid_wife(actor). Assert wk_paid_lodger(actor). Assert wk_friend_wife(actor). Assert wk_friend_lodger(actor). Increase regard(providence) by 1. }
    Result "'Two hundred and two hundred,' says Mr Fettiplace, 'on a signed release from each, and a fee to the Office for the trouble of agreeing, which is twelve.' He takes the twelve, the releases, and the two widows' signatures, in which both Rosalinds have been rather exact about the R. 'It is the first time,' he says, 'that I have seen two women of one name sign beside each other without being asked to.'".
  }
  Topic wk_w_split with wk_rosalind "Put it to Mrs Teague that half of four hundred is better than the Residuary's all of it" when knows(party, wk_two) and not wk_wifeAgrees(party) once {
    Says "'Two hundred,' says Mrs Teague. 'Of what is mine by thirty years.' She considers the ham. 'I should like it understood that I do not like it. Put me down.' She does not look at the lodger, who does not look at her.".
    On discuss { Assert wk_wifeAgrees(actor). }
  }
  Topic wk_l_split with wk_lodger "Put it to Miss Harbottle that half would take her to the next lodging" when knows(party, wk_two) and not wk_lodgerAgrees(party) once {
    Says "'Half,' says Miss Harbottle. 'He did say a Rosalind.' She looks at her hands. 'I was never going to have more than half of anything. Put me down.'".
    On discuss { Assert wk_lodgerAgrees(actor). }
  }
  Action wk_let_it_go(actor: group, site: place) "Tell Mr Fettiplace that the Providence had better keep it (and collect the Office's third, fifteen coin)" {
    Speaker wk_fettiplace.
    Requires able(actor) and company(actor) and at(actor, site) and at(wk_fettiplace, site) and not wk_closed(actor).
    Time 10 minutes.
    On success { Increase quantity(actor, gold) by 15. Assert wk_fee_taken(actor). Assert wk_closed(actor). Assert wk_slighted_providence(actor). }
    Result "'Oh,' says Mr Fettiplace. 'Oh, well.' He is delighted, and ashamed to be delighted. 'The Residuary will have four hundred and the Providence will save the third of it. I shall have to tell the widows you have been very helpful to the Office.' He counts fifteen into your hand. It is the cheerful Office, and cheerful money.".
  }
  Action wk_close_book(actor: group, site: place) "Ask Mr Fettiplace to write his report now, on what he has heard" {
    Speaker wk_fettiplace.
    Requires able(actor) and company(actor) and at(actor, site) and at(wk_fettiplace, site) and not wk_closed(actor).
    Time 5 minutes.
    On success { Assert wk_closed(actor). }
    Result "'Now?' says Mr Fettiplace. 'Very well.' He licks the pencil, and the room, which was talking, stops.".
  }
  Rule wk_deadline when watch(clock) >= 336 and not wk_closed(party) { Assert wk_closed(party). }

  // The verdicts, in order of precedence; each writes once.
  Rule wk_v_exposed when wk_closed(party) and not wk_settled(party) and wk_heardX(party) says "Mr Fettiplace looks at the cage, and at you, and at the cage. 'That,' he says, 'is a very good imitation of the Teague voice, and a very bad one of yours.' The claim is struck. The money goes to the Residuary Office, and the Providence is not at home to you." { Assert wk_settled(party). Assert wk_paid_none(party). Assert wk_slighted_providence(party). Decrease regard(providence) by 2 or to nothing. }
  Rule wk_v_plant_l when wk_closed(party) and not wk_settled(party) and wk_heardPL(party) says "Mr Fettiplace writes it down, nodding, and underlines it. The lodger is paid four hundred, on the strength of a thing that Mr Teague never said." { Assert wk_settled(party). Assert wk_paid_lodger(party). Assert wk_friend_lodger(party). Increase regard(providence) by 1. }
  Rule wk_v_plant_w when wk_closed(party) and not wk_settled(party) and wk_heardPW(party) says "Mr Fettiplace writes it down, nodding, and underlines it. The widow is paid four hundred, on the strength of a thing that Mr Teague never said." { Assert wk_settled(party). Assert wk_paid_wife(party). Assert wk_friend_wife(party). Increase regard(providence) by 1. }
  Rule wk_v_both when wk_closed(party) and not wk_settled(party) and wk_heardL(party) and wk_heardW(party) and not wk_suspicious(wk_fettiplace) says "'He said both,' says Mr Fettiplace sadly. 'In the same breath, almost. The Providence in such a case, by a rule of Mr Gillam's nine years back, pays half of each claimant.' Four hundred is cut in two without a quarrel, and each Rosalind signs for her hundred and seventy." { Assert wk_settled(party). Assert wk_paid_wife(party). Assert wk_paid_lodger(party). Assert wk_friend_wife(party). Assert wk_friend_lodger(party). }
  Rule wk_v_lodger when wk_closed(party) and not wk_settled(party) and wk_heardL(party) says "'The deceased,' says Mr Fettiplace, reading it back, 'in his own voice. The lodger.' He signs. Miss Harbottle is paid four hundred, and does not cry, and then does." { Assert wk_settled(party). Assert wk_paid_lodger(party). Assert wk_friend_lodger(party). Increase regard(providence) by 1. }
  Rule wk_v_wife when wk_closed(party) and not wk_settled(party) and wk_heardW(party) says "'The deceased,' says Mr Fettiplace, reading it back, 'asking for his tea. The wife.' He signs. Mrs Teague is paid four hundred, and puts it away with the air of one who was always going to be." { Assert wk_settled(party). Assert wk_paid_wife(party). Assert wk_friend_wife(party). }
  Rule wk_v_none when wk_closed(party) and not wk_settled(party) says "Mr Fettiplace closes his book. 'Nothing I can take down,' he says. 'I am so sorry. The sum goes to the Residuary Office, which is mourning, I believe, at some length.' The widows do not look at each other, and then do." { Assert wk_settled(party). Assert wk_paid_none(party). }

  // ── What Mr Teague said ──────────────────────────────────────────────────────────────────────────────────
  Action wk_work_out(actor: group, site: place) "Work out what Mr Teague's last words are directions to" {
    Requires able(actor) and company(actor) and at(actor, site) and knows(actor, wk_last) and not knows(actor, d_way_teague).
    Time 15 minutes.
    Resolve check(actor, lore, dc_fair).
    On success { Assert knows(actor, d_way_teague). Assert teagueCombination(actor). }
    Result "Fish, fish, fish-bone. A wheel, and three turns to the left. A Lamprey hatch, on a diving-bell that is for the Lamprey's use only, provided you bring a witness. It was never a lodging-house. A cellar-diver found a way down that the Lamprey's lock was set to keep, and cheated the Office by the length of a bell-rope for nine years. You write it down where Fusby cannot read it.".
    Otherwise "You turn the words over, and they stay a rhyme. A man's last breath, a phrase for a child's game. You will have to ask someone who heard them mean something.".
  }
  Action wk_lodger_says(actor: group, site: place) "Ask Miss Harbottle, quietly, what Mr Teague's last words mean" {
    Speaker wk_lodger.
    Requires able(actor) and company(actor) and at(actor, site) and at(wk_lodger, site) and knows(actor, wk_last) and not knows(actor, d_way_teague) and (wk_friend_lodger(actor) or wk_sat(actor)).
    Time 10 minutes.
    On success { Assert knows(actor, d_way_teague). Assert teagueCombination(actor). }
    Result "'The hatch,' says Miss Harbottle, very low, with the mourners behind you. 'The Lamprey's. The wheel is on the inside of the lid. Fish for the fin, fish for the tail, fish-bone for the spine, and three turns left, and it lets you into the part of the cellars that the Office swears is flooded. He found it nine years ago. I worked the pump while he went in. I never asked what he was bringing out.' She turns her palms over in her lap. 'You may have it. It has done what it was going to do.'".
  }
  Action wk_sit(actor: group, site: place) "Sit the wake through the night with the two Rosalinds" {
    Requires able(actor) and company(actor) and at(actor, site) and at(wk_lodger, site) and at(wk_rosalind, site) and dark() and watch(clock) < 204 and not wk_sat(actor) and not wk_closed(actor).
    Time 36.
    On success { Assert wk_sat(actor). }
    Result "You sit the long hours with the candle and the coffin. The mourners go, one by one. At two the Admiral opens a bottle that has been in the sideboard since the year of the Ordinance, and pours three glasses, and puts one by the coffin. At four the lodger is asleep with her head against the wall, and Mrs Teague has put her own shawl over her, without remark. Nobody asks you to go.".
  }
  Action wk_hearth_lodger(actor: group, site: place) "Ask Miss Harbottle whether the lamp by the coffin might be kept lit on the Night, and the range lit under it" {
    Speaker wk_lodger.
    Requires able(actor) and company(actor) and at(actor, site) and at(wk_lodger, site) and wk_sat(actor) and wk_friend_lodger(actor) and not keeper(hill).
    Time 10 minutes.
    On success { Assert keeper(hill). }
    Result "'A wake keeps a light,' says Miss Harbottle. 'It is only we have not got a corpse for it now.' She looks at the candle. 'The Admiral will say a stove is a wicked extravagance, and then she will light it. We'll keep the range going for the Night. Tell whoever it is.'".
  }
  Action wk_hearth_wife(actor: group, site: place) "Ask Mrs Teague whether the range might be kept alight in the house on the Night" {
    Speaker wk_rosalind.
    Requires able(actor) and company(actor) and at(actor, site) and at(wk_rosalind, site) and wk_sat(actor) and wk_friend_wife(actor) and not keeper(hill).
    Time 10 minutes.
    On success { Assert keeper(hill). }
    Result "'On the Hill?' says Mrs Teague. 'Against the Ordinance, with the neighbours?' She is silent a while. 'My sister Clemency had a hearth in the front kitchen till the day she died, and we all pretended it was the dog's. I shall light it. Say nothing to the Hill.'".
  }
  Action wk_lend_fusby(actor: group, site: place) "Ask Tabitha whether Fusby might be carried to the Hall of the Five to give his evidence" {
    Speaker wk_keeper.
    Requires able(actor) and company(actor) and at(actor, site) and at(wk_keeper, site) and wk_settled(actor) and not witness(wk_fusby) and (wk_friend_wife(actor) or wk_friend_lodger(actor)).
    Time 10 minutes.
    Grave "Fusby repeats everything he has heard, in the order he heard it, in front of whoever is there. The fish, the stair and the coin go in with the rest.".
    On success { Assert witness(wk_fusby). }
    Result "'Him?' says Tabitha. 'In a hall? With the great people?' She looks at the cage. 'He'll say what he heard. I can't stop him, and neither can you. That's the only thing he's good for.' She whistles the three notes through her teeth, softly, and Fusby, under his cloth, mutters, 'Admiral on deck.'".
  }

  // ── Afterward ─────────────────────────────────────────────────────────────────────────────────────────────
  Observe wk_afterglow_w at teague_front when wk_friend_wife(party) "On the sideboard stands a bottle with three glasses beside it, and the ham, wrapped in cloth, has the company's initial pencilled on the corner.".
  Observe wk_afterglow_l at teague_front when wk_friend_lodger(party) and not wk_friend_wife(party) "Miss Harbottle's trunk is gone from the landing and her boots are on the hearth-rug. She is, apparently, staying.".
  Observe wk_fusby_fates at teague_front when wk_settled(party) and not witness(wk_fusby) "Fusby has been given the tall perch by the window. He says nothing today to anybody, which Tabitha says is a sign.".
  Rule wk_fusby_to_hall when day(clock) >= 7 and witness(wk_fusby) and at(wk_fusby, teague_front) { Retract at(wk_fusby, teague_front). Assert at(wk_fusby, hall_five). }
  Rule wk_testifies at hall_five when at(party, hall_five) and at(wk_fusby, hall_five) and witness(wk_fusby) and not wk_testified(party) and not wk_fraud(party) says "Tabitha sets the cage on the bare dais among the five chairs and takes off the cloth. Fusby looks at the Five. He says, in a dead cellar-diver's voice, 'Ros! Hold the line!', and then, with great sweetness, 'It's lit down there. Somebody's feeding it.' And then, 'Fish, fish, fish-bone.' The Lamprey's chair is the first to move. He cannot be bribed, and cannot be asked a question; he can only be heard." { Assert wk_testified(party). Assert wk_slighted_lamprey(party). Decrease regard(lamprey) by 1 or to nothing. }
  Rule wk_testifies_fraud at hall_five when at(party, hall_five) and at(wk_fusby, hall_five) and witness(wk_fusby) and not wk_testified(party) and wk_fraud(party) says "Tabitha sets the cage on the bare dais among the five chairs and takes off the cloth. Fusby looks at the Five. He says, in a dead cellar-diver's voice, 'Ros! Hold the line!', and 'It's lit down there. Somebody's feeding it.' And 'Fish, fish, fish-bone.' And then, in the voice of the company's own liar, 'To the lodger, all of it, no questions,' which is the one thing in his repertoire that Mr Teague never said. The Providence's chair turns slowly to look at you." { Assert wk_testified(party). Assert wk_slighted_lamprey(party). Assert wk_slighted_providence(party). Decrease regard(lamprey) by 1 or to nothing. Decrease regard(providence) by 2 or to nothing. }
}

data/adventures/quittance/slate.kyr:
Module quittance "Quittance" {
  Description "The Bell & Slip and the Wayward Hen: the Slate, the adjuster's licence, a bed, and what the Booths sell.".

  // ── The Bell & Slip ─────────────────────────────────────────────────────────────────────────────────────
  Item licence_card "an adjuster's licence" is adjuster_licence at nowhere.
  Person sprack "Master Sprack" at slip_room {
    Role "Master of the Slate". Ancestry human. Calling bard. Level 3. Peaceable. Manner acerbic. Pronouns he.
    Greets "A very tall, very thin man in a green eyeshade looks down at you over a counter of polished mahogany with a bell on it. 'You are new,' says Master Sprack. 'You are standing in the way of the Slate. Everyone who comes to the Bell & Slip is standing in the way of the Slate; the art is in being somewhere else when it is rewritten.'".
    Greets again "'Ah,' says Master Sprack. 'The Slate has been asking after you.'".
  }
  Person chalk_boy "the chalk boy" at slip_room {
    Role "boy on the ladder". Ancestry human. Peaceable. Manner cheerful. Pronouns he.
    Greets "The boy on the ladder holds up a lump of chalk, with enormous pride. 'I do the *Total Losses*,' he says.".
    Greets again "'Total loss!' the chalk boy cries, to no-one.".
  }
  Topic sprack_slate with sprack "Ask Master Sprack how the Slate works" when true once {
    Says "'Three things,' says Master Sprack, and counts them off on ink-black fingers. 'One. Someone loses. The Office is asked to pay and would rather not, so it hangs the claim here. Two. You take it. Three. You are paid a third of what the Office saves by your report, or a flat fee where it saves nothing. You may be wrong. You may not be dishonest.' He lowers the hand. 'That is reserved.'".
  }
  Topic sprack_licence with sprack "Ask about a licence" when not holding(actor, adjuster_licence) once {
    Says "'Six coin. Three if the Arch has your name in its Roll,' says Master Sprack. 'Take claims. Enter the premises named in them. Certify a mark. Nothing else. Do not ask me for anything else.'".
  }
  Topic sprack_nolicence with sprack "Ask whether a claim can be taken without a licence" when not holding(actor, adjuster_licence) once {
    Says "'Of course,' says Master Sprack. 'Nobody will let you in. Six coin.'".
  }
  Action buy_licence(actor: group, site: place) "Take out an adjuster's licence (6 coin)" {
    Speaker sprack.
    Requires able(actor) and company(actor) and at(actor, site) and at(sprack, site) and not holding(actor, adjuster_licence) and not onTheRoll(actor) and quantity(actor, gold) >= 6.
    Time 10 minutes.
    On success { Decrease quantity(actor, gold) by 6. Give licence_card to actor. }
    Result "Master Sprack writes your names on a card in a hand like a row of railings, blots it with a motion like a priest's, and slides it across. 'Do not lose it,' he says. 'You will be amazed how quickly the Slate stops believing in you.'".
  }
  Action buy_licence_cheap(actor: group, site: place) "Take out an adjuster's licence (3 coin; the Arch has your name)" {
    Speaker sprack.
    Requires able(actor) and company(actor) and at(actor, site) and at(sprack, site) and not holding(actor, adjuster_licence) and onTheRoll(actor) and quantity(actor, gold) >= 3.
    Time 10 minutes.
    On success { Decrease quantity(actor, gold) by 3. Give licence_card to actor. }
    Result "'The Roll of Entrances,' says Master Sprack. 'Says you are who you said you were. Three coin.' He writes the card.".
  }

  // ── The Slate ───────────────────────────────────────────────────────────────────────────────────────────
  // The Slate is rewritten each morning. Its general news is here; each small adventure chalks its own claim in its own
  // file, at slip_room, with the days it is open.
  Observe slate_head at slip_room when true "Over the fireplace the Slate is divided into columns, in chalk: CLAIMS OPEN, CLAIMS TAKEN, TOTAL LOSSES, FIXTURES, PREMIUMS.".
  Observe slate_day0 at slip_room when day(clock) == 1 "TOTAL LOSSES (today): a hat; a ewe; a principle. FIXTURES: Phoenix v. Lamprey, buckets, the fire-house yard, dawn. PREMIUMS: moved up a farthing.".
  Observe slate_day1 at slip_room when day(clock) == 2 "TOTAL LOSSES: a barn, a marriage, a lease. FIXTURES: the Providence bowls the Sovereign at skittles, noon. PREMIUMS: moved up a farthing, then down, then up.".
  Observe slate_day2 at slip_room when day(clock) == 3 "TOTAL LOSSES: a chimney. FIXTURES: an auction of the late Teague's effects, postponed. PREMIUMS: reviewed.".
  Observe slate_day4 at slip_room when day(clock) == 5 "TOTAL LOSSES: a chimney, a hat-shop, a reputation. FIXTURES: the Smokeless Ordinance is read a third time, and a fourth. PREMIUMS: firm.".
  Observe slate_day6 at slip_room when day(clock) == 7 "TOTAL LOSSES: a kitchen, a library, a good name. FIXTURES: the Hall of the Five sits on Reckoning, at two; the public is advised that it is not invited. PREMIUMS: nervous.".
  Observe slate_day7 at slip_room when day(clock) == 8 "RECKONING EVE. Brigades stood to. The Gas Company asks the public to remain indoors. The public, as ever, is advised that it is insured.".
  Observe slate_day8 at slip_room when day(clock) == 9 "RECKONING. The Receipt will be hung at midnight on the Cinderwall. The Offices will meet in the Hall. Premiums are not quoted today, which has never happened.".

  // ── The Wayward Hen ─────────────────────────────────────────────────────────────────────────────────────
  Person pudsey "Mrs Pudsey" at hen_taproom {
    Role "landlady of the Wayward Hen". Ancestry human. Profession innkeeper. Peaceable. Manner jovial. Pronouns she.
    Greets "A broad woman in an apron stamped with a small gilt bird looks up from a ledger and calls, to the room at large, 'New policy-holders!' A pewter pot is on the bar before you have sat down. 'A bed's four coin, a night, with breakfast,' says Mrs Pudsey. 'It is also fully insured. I mention it because I have never been paid out on a bed, and would be most interested to see it done.'".
    Greets again "'Still alive,' Mrs Pudsey says. 'I do like to see that.'".
    Sells rations for 2 coin from 8.
  }
  Topic pudsey_hen with pudsey "Ask Mrs Pudsey about the Hen's three burnt policies" when true once {
    Says "'The first was an accident, my duck,' says Mrs Pudsey. 'The second was Pudsey. The third's on the wall because it's the only one I was sorry about, and he'd left by then, so it was just the beams.' She wipes a tankard that is dry. 'Phoenix, Lamprey, Providence, I've paid them all a tuppence a week in my time, and I'll tell you for nothing, which is what it's worth: same Office, different hats. Mind the step, it's been a quarrel since Michaelmas.'".
  }
  Topic pudsey_gossip with pudsey "Ask what the city is saying" when true once {
    Says "'Same as ever, my duck,' says Mrs Pudsey. 'Premiums too high, that's one. Fires too few, that's two, and new: last year it was too many. The Gas Company's going to be the death of us, that's three, and nobody's said how. And Mr Skell's boys have been in for ham two nights running, which is four, and I've not liked it.'".
  }

  Kind steel_pencil "a steel pencil" is gear worth 1 weighing 0 described "A pencil with a steel point that does not break, which will draw a line exactly as fine as you mean it to. The Booths sell them to clerks who have been told that they will not need another.".

  // ── The Policy Booths ───────────────────────────────────────────────────────────────────────────────────
  Person booth_clerk "the booth clerk" at booths {
    Role "clerk at the Booths". Ancestry human. Peaceable. Manner cheerful. Pronouns she.
    Greets "A girl in a paper cap beams at you from a booth hung with rate cards. 'First night in the city!' she says. 'Insure your luggage, your lodging, your nerves?'".
    Greets again "'Welcome back!' says the booth clerk. 'Have you considered insuring against our being glad to see you?'".
    Sells torch for 1 coin from 8.
    Sells rope for 1 coin from 4.
    Sells bandages for 1 coin from 6.
    Sells chandlers_candle for 1 coin from 12.
    Sells steel_pencil for 1 coin from 6.
    Sells hearn_kindling for 1 coin from 6.
  }
}

data/adventures/quittance/spine.kyr:
Module quittance "Quittance" {
  Description "What the city does while the company is elsewhere: the Appointed Nights, Candlewick Court and Gasket Yard, the Great Tithe at Reckoning, Skelter's rent-book, the acts, and the day's Slate.".

  // ── The Appointed Losses ────────────────────────────────────────────────────────────────────────────────
  // Prewitt's list. A block of the Bare Wards is burned on an Appointed Night, with notice given a week early by a
  // rent-collector. The first, Candlewick Court, burns in the small hours of day 3 (watch 390); the second,
  // Gasket Yard, in the small hours of day 6 (watch 822); the Great Tithe, the Cinder Ward, at Reckoning midnight
  // (watch 1248). Each can be warned, stopped, or witnessed; none waits for the company.
  Relation burned(place). Relation candlewickSaved(group). Relation candlewickWarned(group).
  Relation gasketSaved(group). Relation gasketWarned(group). Relation appointedHalted(group).
  Measure casualties(group).

  Person torchmen "the torchmen" at skelter_room {
    Role "three hired men with oil-cans and a handcart". Ancestry human. Calling thief. Level 2. Numbers 3. Pronouns they.
    Temperament territorial.
    Warns "The handcart stops. 'Move along,' says the biggest, quite gently. 'This court's been declared a hazard. We're here to see it abated.' The others set down the oil-cans and look at you in the way men look at a task that is going to be harder than they were told.".
    Comes "They come at you with the oil-cans swinging, and one of them, you notice, has been crying.".
    Flinches "The torchmen back away down the lane with the handcart rattling.".
    Pleads "'I was told it was empty,' says the biggest, with his hands up. 'They said it was empty.'".
    Refuge skelter_room.
    Lair candlewick.
  }
  Person burners "Skelter's men" at skelter_room {
    Role "four hired men with lamp-oil and a pole-ladder". Ancestry human. Calling warrior. Level 3. Numbers 4. Pronouns they.
    Temperament territorial.
    Warns "Four men stand in the mouth of the yard with their oil, between you and the well. 'The Court is condemned,' says the foreman. 'Official. Move along, or be condemned with it.'".
    Comes "The foreman drops the oil-can and pulls a billet of wood from his belt. 'Right,' he says, with great weariness.".
    Flinches "The men break and go, leaving a pole-ladder and a smell of oil.".
    Pleads "'We've families,' says the foreman. 'Don't. We've families.'".
    Refuge skelter_room.
    Lair gasket_yard.
  }
  Rule torchmen_to_candlewick when watch(clock) >= 384 and not candlewickSaved(party) and not burned(candlewick) and not appointedHalted(city) and not at(torchmen, candlewick) { Assert at(torchmen, candlewick). }
  Rule burners_to_gasket when watch(clock) >= 816 and not gasketSaved(party) and not burned(gasket_yard) and not appointedHalted(city) and not at(burners, gasket_yard) { Assert at(burners, gasket_yard). }
  Rule candlewick_saved_by_force when (routed(torchmen) or dead(torchmen)) and not candlewickSaved(party) and not burned(candlewick) { Assert candlewickSaved(party). }
  Rule gasket_saved_by_force when (routed(burners) or dead(burners)) and not gasketSaved(party) and not burned(gasket_yard) { Assert gasketSaved(party). }
  Rule candlewick_burns when watch(clock) >= 390 and not burned(candlewick) and not candlewickSaved(party) and not appointedHalted(city) {
    Assert burned(candlewick). }
  Rule candlewick_burns_dead when burned(candlewick) and not candlewickWarned(party) and not candlewickCounted(city) { Increase casualties(city) by 19. Assert candlewickCounted(city). }
  Rule candlewick_burns_empty when burned(candlewick) and candlewickWarned(party) and not candlewickCounted(city) { Assert candlewickCounted(city). }
  Relation candlewickCounted(group). Relation gasketCounted(group).
  Rule gasket_burns when watch(clock) >= 822 and not burned(gasket_yard) and not gasketSaved(party) and not appointedHalted(city) {
    Assert burned(gasket_yard). }
  Rule gasket_burns_dead when burned(gasket_yard) and not gasketWarned(party) and not gasketCounted(city) { Increase casualties(city) by 31. Assert gasketCounted(city). }
  Rule gasket_burns_empty when burned(gasket_yard) and gasketWarned(party) and not gasketCounted(city) { Assert gasketCounted(city). }
  Rule torchmen_gone when watch(clock) >= 400 and at(torchmen, candlewick) and (burned(candlewick) or candlewickSaved(party)) and not routed(torchmen) { Assert at(torchmen, skelter_room). }
  Rule burners_gone when watch(clock) >= 832 and at(burners, gasket_yard) and (burned(gasket_yard) or gasketSaved(party)) and not routed(burners) { Assert at(burners, skelter_room). }

  Observe torchmen_at_court at candlewick when at(torchmen, candlewick) and not burned(candlewick) "Three men with oil-cans and a handcart are standing at the mouth of the court in the dark, waiting for a church clock to strike something.".
  Observe candlewick_burnt at candlewick when burned(candlewick) and not candlewickWarned(party) "Seven black shells round a pump. The smell is wet ash and something under it. Women are walking among the timbers, not speaking, turning things over with their feet; a man sits by the pump with a baby that is not his. Nobody has come from any brigade. There is no mark on any of the doors to come for.".
  Observe candlewick_burnt_empty at candlewick when burned(candlewick) and candlewickWarned(party) "Seven black shells round a pump, and the people of the Court standing in the lane in their nightclothes, counting one another, all of them present. A woman is holding a clock. A child is holding a cat. Nobody has come from any brigade. There is no mark on any of the doors to come for.".
  Observe candlewick_saved_scene at candlewick when candlewickSaved(party) "Seven timber houses round a pump, black with smoke and standing. An oil-can lies where it was dropped, and the women have been round it twice to look.".
  Observe gasket_burnt at gasket_yard when burned(gasket_yard) "A square of black timber round a dry well. The notice is still pasted to the well-head, in its clerk's hand, with a corner burned off. What is left of it says: DECLARED A HAZARD. ABATED.".

  // ── The Great Tithe ─────────────────────────────────────────────────────────────────────────────────────
  Relation tithePrepared(group). Relation titheBurned(group).
  Rule tithe_prepared when watch(clock) >= 1230 and not appointedHalted(city) and not fireTerms(party) and not tithePrepared(city) says "Down in the Cinder Ward a handcart goes by in the dark with its wheels bound in rag." { Assert tithePrepared(city). }
  Rule tithe_burns when watch(clock) >= 1248 and tithePrepared(city) and not appointedHalted(city) and not fireTerms(party) and wardsLit(city) < 4 and not titheStopped(city) and not titheBurned(city) {
    Assert titheBurned(city). Assert burned(cinder_ward). }
  Rule tithe_burns_dead when titheBurned(city) and not titheEvacuated(party) and not titheCounted(city) { Increase casualties(city) by 400. Assert titheCounted(city). }
  Relation titheCounted(group).

  // ── Skelter's rent-office ───────────────────────────────────────────────────────────────────────────────
  // Skelter keeps the list. By day he is in his office from nine until noon and from two until six; from noon until two
  // he is out collecting. The door is locked from the inside when he is in; the desk is always locked.
  Item skelter_item "Skelter's rent-book" is skelter_book at nowhere.
  Thing skelter_door "the rent-office door" on market_skelter {
    Tries listening.
    State locked blocking "The rent-office door is shut, and a bolt shoots home on the other side when anyone leans on it.".
    State open "The rent-office door stands open on the hatch and the grating.".
    Change pick "Pick the rent-office lock" from locked to open needing lockwork.
    Change force "Put a shoulder to the rent-office door" from locked to open needing brawn.
  }
  Observe skelter_door_listened near skelter_door when tried(skelter_door, listening) "Behind the door a pen scratches steadily, stops, scratches again. There is the clink of a coin counted twice.".
  Thing skelter_desk "Skelter's desk" at skelter_room {
    Holds.
    State locked closed "A stout desk stands behind the grating, locked, and a heavy book lies on top of it with its spine to the wall.".
    State open "The desk stands open. A shelf of oilcloth-bound books lies inside.".
    Change pick_desk "Pick the desk's lock" from locked to open needing lockwork.
    Change force_desk "Break the desk's lock with a bar" from locked to open needing crowbar.
  }
  Rule skelter_out when hour(clock) == 12 and at(skelter, skelter_room) { Assert at(skelter, night_market). }
  Rule skelter_back when hour(clock) == 14 and at(skelter, night_market) { Assert at(skelter, skelter_room). }
  Relation skelterTold(group). Relation skelterBribed(group). Relation skelterFrightened(group). Relation skelterConned(group).
  Topic skelter_rent with skelter "Ask Mr Skelter what the rent is on the Court" when at(skelter, skelter_room) once {
    Says "'Seven and four,' says Mr Skelter. 'The house. Weekly.' A coin is counted, and counted again. 'Lowest in the city. Dearest to collect. Seven houses at seven and four, that is, that is,' and the pen finishes it for him.".
  }
  Action bribe_skelter(actor: group, site: place) "Offer Mr Skelter thirty coin for the page that lists the next block" {
    Speaker skelter.
    Requires able(actor) and company(actor) and at(actor, site) and at(skelter, site) and quantity(actor, gold) >= 30 and not skelterBribed(actor) and not holding(actor, skelter_book).
    Time 15 minutes.
    On success { Decrease quantity(actor, gold) by 30. Assert skelterBribed(actor). Assert knows(actor, d_gasket_next). Assert knows(actor, d_list_exists). Assert skelterTold(actor). }
    Result "Mr Skelter looks at the coins, and at the grating, and at the door. 'Gasket Yard,' he says, 'the second night. It's in the margin, if you must know. I did not tell you. If you ask me again I'll say I've never seen you.' The coins are gone from the counter before you've seen him move.".
  }
  Action frighten_skelter(actor: group, site: place) "Tell Mr Skelter what a Hearing does to a man who keeps two columns" {
    Speaker skelter.
    Requires able(actor) and company(actor) and at(actor, site) and at(skelter, site) and not skelterFrightened(actor) and not holding(actor, skelter_book).
    Time 15 minutes.
    Resolve check(actor, intimidation, dc_hard).
    On success { Assert skelterFrightened(actor). Give skelter_item to actor. Assert knows(actor, d_skelter_book). }
    On failure { Assert skelterFrightened(actor). }
    Result "Mr Skelter's pen stops. He says nothing for the length of a church clock's quarter. Then he reaches under the counter, and pushes the book through the hatch with the flat of his hand, as if it were something hot. 'It's not mine,' he says. 'It never was.'".
    Otherwise "Mr Skelter smiles, which is worse. 'Out,' he says. 'I have a man in the next room who does sums for the Chief Underwriter. I am sure he would be interested in yours.'".
  }
  Action con_skelter(actor: group, site: place) "Show Mr Skelter the Phoenix's writ and ask for the book, for the audit" {
    Speaker skelter.
    Requires able(actor) and company(actor) and at(actor, site) and at(skelter, site) and holding(actor, phoenix_writ) and not skelterConned(actor) and not holding(actor, skelter_book).
    Time 15 minutes.
    Resolve check(actor, deception, dc_fair).
    On success { Assert skelterConned(actor). Give skelter_item to actor. Assert knows(actor, d_skelter_book). }
    On failure { Assert skelterConned(actor). }
    Result "Mr Skelter reads the writ twice, holds it to the light, and sighs. 'About time,' he says. 'I was beginning to think nobody checked.' The book comes through the hatch. He looks, you think, relieved.".
    Otherwise "'The Chief Underwriter,' says Mr Skelter slowly, 'has a very particular hand. This is a good copy.' He does not move.".
  }
  Action take_book(actor: group, site: place) "Take the oilcloth-bound book from Skelter's desk" {
    Requires able(actor) and company(actor) and at(actor, skelter_room) and state(skelter_desk, open) and not holding(actor, skelter_book) and not at(skelter, skelter_room).
    Time 3 minutes.
    On success { Give skelter_item to actor. }
    Result "You lift the top book from the shelf. Its spine is cracked at a single page.".
  }
  Action read_book(actor: group, site: place) "Read Skelter's rent-book" {
    Requires able(actor) and company(actor) and at(actor, site) and holding(actor, skelter_book) and not knows(actor, d_prewitt_appoints).
    Time 20 minutes.
    On success { Assert knows(actor, d_skelter_book). Assert knows(actor, d_prewitt_appoints). Assert knows(actor, d_gasket_next). Assert knows(actor, d_list_exists). Assert knows(actor, d_appointed_notice). }
    Result "The rents are in black ink and the second column in red. Down the margin, in a hand like a row of pins, run dates a week before each fire, and against each, initials: S.P. Candlewick Court. Gasket Yard. At the foot of the last page, for the night of Reckoning, in the same hand: Cinder Ward, approx. 3,000; abate.".
  }

  // ── The acts ────────────────────────────────────────────────────────────────────────────────────────────
  Chapter act_one "Assessment" when day(clock) == 1 and hour(clock) >= 8 "The city is already awake, and you are standing at its edge with a little money and nothing insured. In nine days it will be Reckoning.".
  Chapter act_two "Adjustment" when day(clock) == 4 and hour(clock) >= 6 "By morning the Slate has a new column, and the new column is mostly zeros. The Offices are very calm about it.".
  Chapter act_three "Settlement" when day(clock) == 7 and hour(clock) >= 6 "The Hall of the Five is being swept. A man on a ladder is taking down last year's bunting. In three days the city is to hang its Receipt, and the Receipt, which you have seen, is the colour of milk.".
  Chapter act_four "Reckoning" when day(clock) == 9 and hour(clock) >= 6 "The bells of the Exchange ring for the last time before the Reckoning. Every window in Policy Row has a candle in it, mark-insured, and not one of them is lit.".

  // ── The Slate's news ───────────────────────────────────────────────────────────────────────────────────
  Observe slate_candle_burnt at slip_room when burned(candlewick) and day(clock) >= 4 "TOTAL LOSSES: Candlewick Court, Bare Wards; uninsured; the Phoenix regrets. Nineteen persons are unaccounted for. The Provident Mutual of the Bare Wards (Penny) has chalked its own column beneath, in a different hand, which the boy on the ladder has been asked not to rub out.".
  Observe slate_candle_empty at slip_room when burned(candlewick) and candlewickWarned(party) and day(clock) >= 4 "TOTAL LOSSES: Candlewick Court, Bare Wards; uninsured; the Phoenix regrets. No persons are reported lost; the Court was, it appears, evacuated beforehand, an irregularity which the Phoenix has noted.".
  Observe slate_candle_saved at slip_room when candlewickSaved(party) and day(clock) >= 4 "FIXTURES: an attempted abatement in the Bare Wards, abandoned. The Phoenix has no comment. The boy on the ladder has written it very small.".
  Observe slate_gasket_burnt at slip_room when burned(gasket_yard) and day(clock) >= 7 "TOTAL LOSSES: Gasket Yard, Bare Wards; uninsured; thirty-one persons unaccounted for. The Phoenix regrets.".
  Observe slate_tithe at slip_room when burned(cinder_ward) "The Slate is blank. Someone has written across it, in a very large hand, QUITTANCE, and nobody will say who.".
}

data/adventures/quittance/spine_hearn.ky:
Module quittance "Quittance" {
  Description "Hearn House: the last Hearthkeeper, his coal, the three lines of the Return, and what an old man can give if he is kept company.".

  Kind hearn_kindling "a bundle of kindling" is gear worth 1 weighing 1 described "Split ash-sticks tied with tarred cord. A bundle of this is, in the inner wards of Quittance, a quiet offence.".
  Measure lucidUntil(group). Relation returnLearned(group). Relation hearnCoalOne(group). Relation hearnCoalTwo(group). Relation hearnKeyGiven(group).
  Discovery d_return_1 "The first line of the Return, as Auberon Hearn gave it: 'What was lent is not lost.'".
  Discovery d_return_2 "The second line of the Return, cut under the soot of the hearth-room lintel: 'What was kept is returned.'".
  Item hearn_key_item "the Exchange cellar key" is cellar_key at nowhere.

  // ── The housekeeper ─────────────────────────────────────────────────────────────────────────────────────
  Person overend "Mrs Overend" at hearn_parlour {
    Role "housekeeper at Hearn House". Ancestry human. Peaceable. Manner acerbic. Pronouns she.
    Greets "A tall woman in grey with a ring of keys and a face like a shut door stands in the parlour with her back to the bricked-up fireplace, as though to keep it in. 'Mr Hearn is not receiving,' says Mrs Overend. 'He is not receiving anything. He has had a quiet week.'".
    Greets again "'Wipe your feet,' says Mrs Overend. 'He may or may not know you.'".
  }
  Topic overend_fuel with overend "Ask why there is no fire in the house" when true once {
    Says "'The Ordinance,' says Mrs Overend. 'No open fire within the inner wards. I have not lit a fire in this house in nineteen years. Mr Hearn has the hearth-room, which is exempt, on grounds of sentiment. I do not carry fuel to it, because I do not hold with sentiment, and if he asks me to I shall say that there is none.' She looks at the floor. 'There is none.'".
  }
  Topic overend_him with overend "Ask how he is" when true once {
    Says "'He is eighty-three,' says Mrs Overend. 'He is the last of them. The Hearns kept the coals for a hundred years and never once said what for, and now he sits by a little red thing in a grate and calls it by a woman's name. Some days he knows me.' She straightens a chair that is straight. 'He is always very polite. That is the dreadful part.'".
  }

  // ── The hearth-room ─────────────────────────────────────────────────────────────────────────────────────
  Thing hearn_lintel "the sooted lintel over the hearth" at hearn_hearth {
    State sooted "The stone lintel over the little hearth is black with a century of smoke. Under the soot, you think, there is something cut.".
    State clean "The lintel has been scrubbed, and a line is cut in it, in a notary's capitals: WHAT WAS KEPT IS RETURNED.".
    Change scrub "Scrub the soot from the lintel" from sooted to clean.
  }
  Observe lintel_read at hearn_hearth when state(hearn_lintel, clean) "Under the lintel, in a neat deep hand: WHAT WAS KEPT IS RETURNED. And beneath it, smaller, as though added by someone who had run out of room: and what is lent is lent." teaches d_return_2.
  Observe auberon_lucid_scene at hearn_hearth when watch(clock) < lucidUntil(auberon) "The old man has turned his chair a little from the fire. His hands are quite steady. He is looking at you with a keen, tired, intelligent attention, like a clerk at the end of a long day who has just been handed the one file that matters.".
  Observe auberon_lost_scene at hearn_hearth when watch(clock) >= lucidUntil(auberon) "The little red coal glows in the grate, no bigger than a hand. The old man has his own hands to it, and watches it as one watches a sleeping child, and now and then speaks to it.".

  Action tend_coal(actor: group, site: place) "Feed the old man's coal a bundle of kindling" {
    Requires able(actor) and company(actor) and at(actor, hearn_hearth) and holding(actor, hearn_kindling).
    Time 10 minutes.
    On success { Spend hearn_kindling from actor. Set lucidUntil(auberon) to watch(clock) + 6. }
    Result "You lay the sticks on the coal as you would lay them on a sleeping animal, one at a time. It takes slowly, with a small crackle, and a clean yellow flame stands up in the grate. The old man draws a long breath, as if from a depth. 'Ah,' says Auberon Hearn. 'There. That is better. Do sit down.' And his face, in the new light, has gathered itself.".
  }
  Rule auberon_first_lucid when watch(clock) < lucidUntil(auberon) and arc(auberon) < 1 { Set arc(auberon) to 1. }
  Topic auberon_who with auberon "Ask whom he takes you for" when watch(clock) >= lucidUntil(auberon) once {
    Says "'The coal-men,' says Auberon Hearn comfortably. 'You will have come for the Return, but it is not yet, it is the autumn. Honora said it was never to be before the bells. You will take tea?' He offers you a cup he does not have. 'I shall just feed my guest.' And he turns back to the hearth, and tends the coal with the end of a spoon.".
  }
  Topic auberon_honora with auberon "Ask about Honora" when watch(clock) < lucidUntil(auberon) once {
    Says "'My great-grandmother,' says Auberon Hearn. 'She was a notary. A very good one. They say she walked into the fire to look for a client.' He smiles. 'That is rather what she did. The client was the fire. She told me once, I was seven, that every contract is a promise to be kind to someone you have not met yet. She said the Offices were the worst thing she ever drafted, and that she had made them so that someone would always be paid to remember.' He looks at the coal. 'I am, I think, what they paid to remember. It is not much.'".
    On discuss { Assert knows(actor, d_fire_is_real). }
  }
  Topic auberon_return with auberon "Ask him to say the Return" when watch(clock) < lucidUntil(auberon) and not knows(actor, d_return_1) once {
    Says "He straightens, with an effort, and puts down the spoon. 'What was lent,' says Auberon Hearn, clearly, in a voice that has done this a hundred times, 'is not lost.' He waits. His lips move. 'And,' he says. 'And.' Something goes out of his face, like a lamp turned down, and he is looking at you with courteous bewilderment. 'I'm so sorry,' he says. 'I had it a moment ago.'".
    On discuss { Assert knows(actor, d_return_1). Assert knows(actor, d_return). Set lucidUntil(auberon) to watch(clock). }
  }
  Rule return_learned when knows(party, d_return_1) and knows(party, d_return_2) and knows(party, d_return_3) and not returnLearned(party) { Assert returnLearned(party). }
  Rule auberon_second_stage when returnLearned(party) and arc(auberon) < 2 { Set arc(auberon) to 2. }
  Topic auberon_say_back with auberon "Say the three lines of the Return back to him, in order" when returnLearned(actor) and watch(clock) < lucidUntil(auberon) once {
    Says "You say it: what was lent is not lost; what was kept is returned; quit, and welcome. The old man is quite still. His eyes have filled, and he does not seem to know it. 'Yes,' he says. 'That is the one.' He reaches out and takes hold of the nearest of you by the sleeve. 'You will say it for me,' says Auberon Hearn. 'I have been so afraid there would be nobody who could.' He lets go. 'The key is in the clock,' he says. 'And the coal is yours to carry. Do not let it go out.'".
    On discuss { Assert hearnKeyGiven(actor). }
  }
  Topic auberon_key with auberon "Ask for the key to the Exchange cellars" when hearnKeyGiven(actor) and not holding(actor, cellar_key) once {
    Says "He opens the case of the little carriage-clock on the mantel, and takes a black key from behind the pendulum as if he had put it there that morning. 'The cellars,' he says. 'Mind the Queue. They are very patient and they will want a pen.'".
    On discuss { Give hearn_key_item to actor. Assert cellarLeave(actor). }
  }
  Action hearn_coal_one(actor: group, site: place) "Ask Auberon Hearn for a coal to carry, for the Night" {
    Speaker auberon.
    Requires able(actor) and company(actor) and at(actor, site) and at(auberon, site) and watch(clock) < lucidUntil(auberon) and day(clock) >= 7 and not hearnCoalOne(actor) and quantity(actor, coal) < 2.
    Time 10 minutes.
    On success { Assert hearnCoalOne(actor). Increase quantity(actor, coal) by 1. Set coalExpires(actor) to watch(clock) + 144. }
    Result "He takes the tongs himself, with a hand that trembles only at the start, and lifts a living coal out of the grate into your tin. It is the colour of the inside of a plum. 'One for every house that will have it,' he says. 'You must choose. I never could.'".
  }
  Action hearn_coal_two(actor: group, site: place) "Ask Auberon Hearn for a second coal" {
    Speaker auberon.
    Requires able(actor) and company(actor) and at(actor, site) and at(auberon, site) and watch(clock) < lucidUntil(auberon) and day(clock) >= 7 and hearnCoalOne(actor) and not hearnCoalTwo(actor) and quantity(actor, coal) < 2 and arc(auberon) >= 2.
    Time 10 minutes.
    On success { Assert hearnCoalTwo(actor). Increase quantity(actor, coal) by 1. Set coalExpires(actor) to watch(clock) + 144. }
    Result "'Another,' says Auberon. 'Yes. If it is for the right sort of house.' His hand is steadier this time. 'I have not given two in my life.'".
  }
  Rule hearn_keeps_hill when arc(auberon) >= 2 and not keeper(hill) { Assert keeper(hill). }
  Rule return_said_below when returnLearned(party) and at(party, hearth_below) and not returnSaid(party) { Assert returnSaid(party). }
}

data/adventures/quittance/spine_people.k:
Module quittance "Quittance" {
  Description "Prewitt, Ottoline and Miss Pettifer, and the people of Candlewick Court and Gasket Yard: the levers on a man who wrote the Tables, the clerk who found the paradox, and the people to be warned.".

  Relation employed(group). Relation kinUsed(group). Relation witnessUsed(group). Relation sumUsed(group). Relation lampUsed(group).
  Relation ottolineSees(group). Relation shawlAsked(group). Relation prewittTurned(group). Relation prewittHardened(group).
  Measure ottolineTrust(group). Measure pettiferTrust(group).

  // ── Ottoline Prewitt ────────────────────────────────────────────────────────────────────────────────────
  Topic ottoline_work with ottoline "Ask Ottoline what the Phoenix wants of an adjuster" when true once {
    Says "'Everything,' says Ottoline Prewitt, 'and nothing it can say aloud.' She pushes a ledger across. 'Mark Street, this morning, is the sort of thing the Phoenix can't help being late for: two brigades and a plate. And my father would like someone from outside to look at our losses. He says that a pair of fresh eyes is cheaper than a pair of tired ones. I think he means that tired ones have seen it.'".
    On discuss { Increase ottolineTrust(ottoline) by 1. }
  }
  Topic ottoline_employ with ottoline "Accept the Phoenix's commission" when not employed(actor) and ottolineTrust(ottoline) >= 1 once {
    Says "'There,' says Ottoline, and opens a drawer, and writes. 'Twenty coin on account, a writ you can show to anyone in a blue coat, and my father's undying indifference.' She blots it. 'I should say that it makes you the Phoenix's. People in the Wards will notice. I haven't thought of a way to stop them.'".
    On discuss { Assert employed(actor). Give writ_item to actor. Increase quantity(actor, gold) by 20. Increase regard(phoenix) by 1. Increase ottolineTrust(ottoline) by 1. }
  }
  Item writ_item "a writ of the Phoenix" is phoenix_writ at nowhere.
  Topic ottoline_father with ottoline "Ask Ottoline about her father" when ottolineTrust(ottoline) >= 1 once {
    Says "'He is the most honest man I know,' says Ottoline. 'I mean that as an accusation. He has never in his life told a lie, which is why nobody has ever caught him in anything.' She laughs, and stops. 'My mother died in a fire. Mark Street. Nobody's allowed to say her name at the Phoenix, which I think is a kind of mourning.'".
    On discuss { Increase ottolineTrust(ottoline) by 1. }
  }
  Topic ottoline_tables with ottoline "Ask Ottoline about the Tables" when true once {
    Says "'The Tables are ninety-four years of the city's fires, column on column,' says Ottoline. 'Cornelia Ashby keeps them—' she stops, as at a fence, '—Pettifer. Cornelia Pettifer. Ashby was her mother's name; the clerks call her Ashby because she's from the Ashby side. Don't ask me. Go and see her. She doesn't like to be asked about her columns; she likes to be asked about her pencils.'".
  }
  Topic ottoline_come with ottoline "Ask Ottoline to come with you, as the Phoenix's adjuster" when employed(actor) and ottolineTrust(ottoline) >= 3 once {
    Says "Ottoline thinks about it for exactly as long as it takes to put her pencil behind her ear. 'My father will say I'm being mistaken for a member of the public,' she says. 'Good.'".
    On discuss { Assert willing(ottoline, actor). Set hire(ottoline) to 0. }
  }
  Topic ottoline_show with ottoline "Show Ottoline Skelter's rent-book" when knows(actor, d_skelter_book) and holding(actor, skelter_book) once {
    Says "Ottoline reads the margin. She reads it again. Her pencil goes back behind her ear and then, absently, into her hair. 'That's his hand,' she says. 'I'd know it on a tombstone.' She closes the book carefully, like a person closing a door on a sleeping child. 'I want to see it,' she says. 'Not a column. The place.'".
    On discuss { Increase ottolineTrust(ottoline) by 1. }
  }
  Rule ottoline_sees_ruin when travelsWith(ottoline, party) and ((at(party, candlewick) and burned(candlewick)) or (at(party, gasket_yard) and burned(gasket_yard)) or (at(party, cinder_ward) and burned(cinder_ward))) and not ottolineSees(party)
    says "Ottoline stops at the mouth of the lane. She does not say anything. After a time she takes off her glove, and then, as though it had been quite another thing she meant to do, puts it back on." { Assert ottolineSees(party). }
  Action ottoline_speaks(actor: group, site: place) "Ask Ottoline to speak to her father" {
    Speaker ottoline.
    Requires able(actor) and company(actor) and at(actor, site) and at(ottoline, site) and ottolineSees(actor) and not kinUsed(actor) and arc(prewitt) < 3 and not prewittHardened(actor).
    Time 1.
    On success { Assert kinUsed(actor). Increase arc(prewitt) by 1. }
    Result "'Not tonight,' says Ottoline, 'and not here.' She goes up the stair to the Chief Underwriter's room with a ledger under her arm, as she has gone every morning for four years. The door closes. You wait on the counting-floor among the hundred clerks, who go on writing. Some while later the door opens, and she comes out, and her face is quite blank and her eyes are quite wet, and she does not say what he said, only: 'He asked whether I'd eaten.' Then she sits down at her desk and begins, very quietly, to work.".
  }

  // ── Sedley Prewitt ──────────────────────────────────────────────────────────────────────────────────────
  Topic prewitt_hello with prewitt "Give your names, and say who sent you" when true once {
    Says "'The Arch sent you,' says Prewitt, 'and Ottoline wrote to me. It comes to the same thing.' He looks at each of you in turn, without hurry, and you have the feeling of being quietly priced. 'I do not need an explanation of why you are here. I should like to know whether you are the sort of person who answers questions that were not asked.'".
    On discuss { Assert knows(actor, d_prewitt_met). }
  }
  Topic prewitt_work with prewitt "Ask what the Phoenix needs" when knows(actor, d_prewitt_met) once {
    Says "'A little attention,' says Prewitt. 'The Phoenix has paid out fewer claims every year for forty years and it finds it cannot enjoy it. The Tables are in order. The city is in order. I should like someone to tell me whether the Tables are lying, or whether the city is. Ottoline will give you a writ.'".
  }
  Topic prewitt_tables with prewitt "Ask whether the Tables could be wrong" when knows(actor, d_prewitt_met) and not knows(actor, d_tables_paradox) once {
    Says "'They are ninety-four years of arithmetic,' says Prewitt. 'Arithmetic is the one thing I have never found to be wrong. It has been, on occasion, unwelcome.'".
  }
  Topic prewitt_tables_paradox with prewitt "Put the paradox to him: the Wards, unmarked, burn least" when knows(actor, d_tables_paradox) once {
    Says "For the first time, Prewitt looks away: at the lamp, at the window, at the shawl on the chair. 'Yes,' he says. 'You have found the one curve in the Tables I have never been able to explain to a Board.' He is quiet. 'I should be very grateful if you would stop looking.'".
  }
  Action ask_shawl(actor: group, site: place) "Ask whose shawl it is, on the other chair" {
    Speaker prewitt.
    Requires able(actor) and company(actor) and at(actor, site) and at(prewitt, site) and not shawlAsked(actor).
    Time 5 minutes.
    Resolve check(actor, insight, dc_fair).
    On success { Assert shawlAsked(actor). }
    On failure { Assert shawlAsked(actor). }
    Result "'My wife's,' says Prewitt. 'Margery.' He does not move his eyes from the window. 'She kept a coal in the kitchen. A mere habit of her mother's; she lit the range from it every morning, and was rather ashamed of it, because the Ordinance had come in. She let it out the winter I became Chief Underwriter. I told her it was only prudent. In March the kitchen burned.' He stops. 'I tell you this because it is in the Phoenix's records, and you will read it. That is the whole of the matter.' He is quite steady. You think he might be, in some fashion, grateful to have been asked.".
    Otherwise "'It is a shawl,' says Prewitt. 'It belongs to someone who is not here.' He turns a page. He does not say anything more about it, and the room goes on being as cold as it was.".
  }
  Action lamp_for_margery(actor: group, site: place) "Light the cold lamp on his desk with a Lent coal, for Margery" {
    Speaker prewitt.
    Requires able(actor) and company(actor) and at(actor, site) and at(prewitt, site) and quantity(actor, coal) >= 1 and shawlAsked(actor) and not lampUsed(actor) and arc(prewitt) < 3 and not prewittHardened(actor).
    Time 5 minutes.
    Grave "A coal given here is a coal not laid in a ward. It will not come back.".
    On success { Decrease quantity(actor, coal) by 1. Assert lampUsed(actor). Increase arc(prewitt) by 1. }
    Result "You open the tin on his desk. The coal ticks; the room smells of ash and bread. Prewitt watches you take the glass chimney off the lamp and set the coal to the wick, and says nothing, and does not stop you, and does not help. The wick takes. A small yellow flame stands up in the cold lamp, gently, like someone getting to their feet, and he lets out a breath he must have been holding for six years. 'Thank you,' he says, in a voice quite unlike the one before. He does not put the lamp out.".
  }
  Action put_the_sum(actor: group, site: place) "Put Miss Pettifer's General Average to him: the Offices shall share a loss, in daylight, and no one in it" {
    Speaker prewitt.
    Requires able(actor) and company(actor) and at(actor, site) and at(prewitt, site) and knows(actor, d_tables_paradox) and arc(pettifer) >= 1 and not sumUsed(actor) and arc(prewitt) < 3 and not prewittHardened(actor).
    Time 20 minutes.
    On success { Assert sumUsed(actor). Increase arc(prewitt) by 1. }
    Result "It is one sheet in Cornelia Pettifer's small hand, with a column of the Offices down the left side. Prewitt reads it standing up. When he comes to the foot of it he sits down, and reads it again, from the top, with his pencil. 'It is,' he says at last, 'a better sum.' He sounds faintly aggrieved. 'The Cinder Ward evacuated, burned in daylight, the loss shared by all five Offices pro rata. Nobody dies. The Fire is paid.' He taps the page. 'This is cheaper. I would have found it in three years if I had not been so certain.'".
  }
  Action threaten_prewitt(actor: group, site: place) "Tell Prewitt you will put his list on the Slate" {
    Speaker prewitt.
    Requires able(actor) and company(actor) and at(actor, site) and at(prewitt, site) and knows(actor, d_prewitt_appoints) and arc(prewitt) < 3 and not prewittHardened(actor).
    Time 5 minutes.
    Grave "A man told he will be exposed does not become kinder.".
    On success { Assert prewittHardened(actor). Decrease regard(phoenix) by 2 or to nothing. }
    Result "'Do,' says Prewitt. The word comes out with no weight at all. 'Chalk it on the Slate. Take it to the Five. They will ask you to produce the man who wrote it, and the man who wrote it will be myself, and I shall say that it was a prudent reserve against a catastrophe. They will believe me. They always believe the Tables.' He rises. He looks old, suddenly, and hard. 'I think you had better go. I shall send someone to see that you do.'".
  }
  Rule prewitt_turns when arc(prewitt) >= 3 and not prewittTurned(party)
    says "Sedley Prewitt takes a pen. The nib scratches. He signs, and blots, and rings for a clerk, and says in an unhurried voice, 'The Appointed Losses are suspended. All of them. By my authority.' The clerk stares. 'Is that all, sir?' 'No,' says Prewitt. 'Fetch my hat.'" {
    Assert prewittTurned(party). Assert appointedHalted(city). Assert witness(prewitt). }
  Rule prewitt_watches_gasket when watch(clock) >= 810 and watch(clock) < 840 and not appointedHalted(city) and not at(prewitt, gasket_yard) and arc(prewitt) < 3 { Assert at(prewitt, gasket_yard). }
  Rule prewitt_home when watch(clock) >= 840 and at(prewitt, gasket_yard) { Assert at(prewitt, prewitt_room). }
  Rule prewitt_watches_cinder when watch(clock) >= 1236 and not appointedHalted(city) and not at(prewitt, cinder_ward) { Assert at(prewitt, cinder_ward). }
  Observe prewitt_in_yard at gasket_yard when at(prewitt, gasket_yard) and not burned(gasket_yard) "A man in a long grey coat stands at the mouth of the lane in the dark, quite still, with his hands behind him. He is not hiding. It is only that nobody here has ever seen him, and the Wards do not know his face.".
  Observe prewitt_in_yard_burning at gasket_yard when at(prewitt, gasket_yard) and burned(gasket_yard) "The man in the grey coat has not moved. The light of the burning Yard is on his face, and he watches it exactly as he would watch a column of figures being added.".
  Action prewitt_witness(actor: group, site: place) "Ask the man in the grey coat to stay, and watch the people on the street" {
    Speaker prewitt.
    Requires able(actor) and company(actor) and at(actor, site) and at(prewitt, site) and burned(gasket_yard) and gasketWarned(actor) and not witnessUsed(actor) and arc(prewitt) < 3 and not prewittHardened(actor).
    Time 20 minutes.
    On success { Assert witnessUsed(actor). Increase arc(prewitt) by 1. Assert knows(actor, d_prewitt_met). }
    Result "'You know me,' says Prewitt. 'Yes.' He does not turn. You do not argue. You go and stand beside him, and after a while you say, only, 'Look at them.' There are three hundred people in the lane in their nightclothes, counted twice, standing in the light of their own houses, with their cats, with their clocks. Nobody is screaming. Someone is passing round a heel of bread. He looks for a very long time. 'I had thought they would be fewer,' says Prewitt, in a low voice. 'On paper, they are always fewer.'".
  }

  // ── Cornelia Pettifer ───────────────────────────────────────────────────────────────────────────────────
  Topic pettifer_pencils with pettifer "Ask Miss Pettifer what she is drawing" when true once {
    Says "'Nothing.' Cornelia Pettifer puts her hand over it. 'It is a— a curve. Two. One is the city. One is the other. It is not a thing one shows.' She looks up, anxious. 'I have only the one pencil, and it is nearly gone, which is why they are so faint.'".
  }
  Action count_with_pettifer(actor: group, site: place) "Sit down and check her figures with her, column by column" {
    Speaker pettifer.
    Requires able(actor) and company(actor) and at(actor, site) and at(pettifer, site) and not knows(actor, d_tables_paradox) and not countedWith(actor).
    Time 40 minutes.
    Resolve check(actor, lore, dc_fair).
    On success { Assert knows(actor, d_tables_paradox). Assert countedWith(actor). Increase pettiferTrust(pettifer) by 1. }
    On failure { Assert countedWith(actor). }
    Result "You pull up a stool. She doesn't look at you; she moves the page a little so that you can see it. At first it is only columns. Then you see what she has seen, because she has made it very plain: the Brickfields, marked and mended and watched, burning a little more each year; the Bare Wards, tinder, unwatched, hung with fires, and the line there as flat as a table. She says nothing. She has the look of someone who has put down a heavy thing in front of a stranger and is waiting to be told it is not heavy.".
    Otherwise "You take her figures one at a time, and every time you reach for a conclusion she is already there, a column ahead, gently waiting. After an hour you have only established that you are not as quick as she is. 'It's quite all right,' she says, with great kindness. 'Nobody is.'".
  }
  Relation countedWith(group).
  Topic pettifer_pencil_gift with pettifer "Give Miss Pettifer a new steel pencil" when holding(actor, steel_pencil) once {
    Says "Cornelia Pettifer holds the pencil without speaking, turning it over, as one holds an animal that has come to the hand. 'It is a very good pencil,' she says at last, in a smaller voice than before. 'Nobody has ever— The Phoenix issues them in blunt. I shall have to be careful not to use it up.' She draws a line, once, to try it, and the line is exactly as thin as she meant. Then, without being asked, she turns the page round.".
    On discuss { Spend steel_pencil from actor. Increase pettiferTrust(pettifer) by 2. Assert knows(actor, d_tables_paradox). }
  }
  Topic pettifer_ashby with pettifer "Ask why the clerks call her Ashby" when true once {
    Says "'My mother was an Ashby,' says Cornelia Pettifer. 'The Pettifers are the sort who wouldn't have been counted at all. It's easier to be an Ashby in a clerks' room. It's a little like being a ghost: you get the quiet, and nobody asks you to speak.'".
  }
  Topic pettifer_promise_topic with pettifer "Promise to stand beside her when the Five sit" when knows(actor, d_tables_paradox) and pettiferTrust(pettifer) >= 1 once {
    Says "She goes the colour of the page. 'In the Hall?' she says. 'In front of— with the Chairmen?' She puts both hands flat on the desk, as though the floor had moved. 'If you stood beside me,' she says. 'Not in front. Beside. I could say the numbers. I can say numbers to anyone.'".
    On discuss { Assert promiseMade(pettifer_stand). Increase arc(pettifer) by 1. Assert willing(pettifer, actor). Set hire(pettifer) to 0. Assert witness(pettifer). }
  }
  Promise pettifer_stand "to stand beside Miss Pettifer when the Five sit" to pettifer
    kept when pettiferSpoke(city) "Cornelia Pettifer, in the Hall, in front of the Five, with the paper trembling in her hand, says the numbers; and does not once look round to see whether you are there, because she knows."
    broken when hearingOver(city) and not pettiferSpoke(city) "Somewhere in the Exchange, in a low room lit by cold-lamps, a woman puts down a very good pencil and does not pick it up again." { Assert pettiferBroken(party). }.
  Relation pettiferSpoke(group). Relation hearingOver(group). Relation pettiferBroken(group).

  // ── Candlewick Court and Gasket Yard ────────────────────────────────────────────────────────────────────
  Person wickersham "Nell Wickersham" at candlewick {
    Role "washerwoman, keeper of the pump". Ancestry human. Peaceable. Manner stoic. Pronouns she.
    Greets "A woman is scrubbing a sheet on the rim of the pump with the concentrated hatred of someone who has to get it clean by dark. 'The Court's paid up,' says Nell Wickersham, 'if you're the collector. If you're not, you can hold the other end.'".
    Greets again "'Hold the other end,' says Nell Wickersham.".
  }
  Topic wickersham_chalk with wickersham "Ask what the number on the pump means" when true once {
    Says "'A man chalked it on Tuesday,' says Nell. 'Not our man. A clerk-sort, with a stamp. I scrubbed it off and it was back in the morning. It's a date, I think. I never was good with dates.'".
  }
  Action warn_candlewick(actor: group, site: place) "Tell Nell the Court will burn on the second night, and to get everyone out of it" {
    Speaker wickersham.
    Requires able(actor) and company(actor) and at(actor, site) and at(wickersham, site) and knows(actor, d_candlewick_next) and not candlewickWarned(actor) and not burned(candlewick) and (measureRegardWards(actor) or entered_gap(actor)).
    Time 15 minutes.
    On success { Assert candlewickWarned(actor). }
    Result "Nell listens with the sheet dripping in her hands. Then she wrings it out in one long twist, hangs it on the pump, and goes to the nearest door. 'Right,' she says, over her shoulder. 'Everybody up. We're having a party in the lane.' By dusk every bed in Candlewick Court is stripped, and every pot, and the cat is in a basket. Nobody will say how they were persuaded; the Court only knows that you did not lie.".
  }
  Query measureRegardWards(g: group) means regard(wardsfolk) >= 1.
  Action warn_candlewick_talk(actor: group, site: place) "Tell Nell the Court will burn, and talk her into believing a stranger" {
    Speaker wickersham.
    Requires able(actor) and company(actor) and at(actor, site) and at(wickersham, site) and knows(actor, d_candlewick_next) and not candlewickWarned(actor) and not burned(candlewick) and not measureRegardWards(actor) and not entered_gap(actor).
    Time 30 minutes.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert candlewickWarned(actor). }
    Result "'I've heard the Phoenix say a lot of things,' says Nell. 'You've got the wrong coat for it. Fine.' She goes round the Court with her arms folded, knocking on doors, and by dusk it is empty.".
    Otherwise "'A stranger comes to the Court and says it'll burn,' says Nell. 'A stranger. I've had that before, and it was a man selling insurance.'".
  }
  Person dolly "Dolly Orrimer" at gasket_yard {
    Role "pump-woman of Gasket Yard". Ancestry human. Peaceable. Manner proud. Pronouns she.
    Greets "A big woman with her hair in a rag is working the handle of the dry well as if it might still give. 'It hasn't had water since the autumn,' says Dolly Orrimer. 'I pump it anyway. It's the principle.'".
    Greets again "'Nothing yet,' says Dolly Orrimer. 'Same as ever.'".
  }
  Action warn_gasket(actor: group, site: place) "Tell Dolly the Yard will burn on the sixth night, and to get everyone out of it" {
    Speaker dolly.
    Requires able(actor) and company(actor) and at(actor, site) and at(dolly, site) and knows(actor, d_gasket_next) and not gasketWarned(actor) and not burned(gasket_yard) and (measureRegardWards(actor) or entered_gap(actor) or knows(actor, d_appointed_notice)).
    Time 15 minutes.
    On success { Assert gasketWarned(actor). }
    Result "Dolly reads the notice on the well-head again, aloud, which nobody has done. 'Declared a hazard,' she says. 'Abated.' She drops the pump handle. 'I'm a hazard, am I.' By nightfall the Yard has put its bedding on the cobbles and set out its chairs in rings, and a boy is chalking, on the notice, in large letters, MOVED.".
  }
  Topic dolly_notice with dolly "Ask Dolly about the notice on the well" when true once {
    Says "'Nobody reads,' says Dolly. 'The clerk who pasted it said it was for the sanitary inspector, and we've no sanitary inspector, so we took it as a compliment.'".
  }

  // ── A kindness, so that a turn is a return (second review C5) ───────────────────────────────────────────
  Relation prewittBed(group).
  Topic prewitt_bed with prewitt "Ask whether the Phoenix keeps a bed for the adjusters it sends for" when knows(actor, d_prewitt_met) and not prewittBed(actor) once {
    Says "Prewitt looks at you, and at the shawl, and at you. 'It does not,' he says. 'It ought. A guest is owed a bed; it is the oldest rule of the trade, older than the marks.' He takes eight coin from a drawer, counts it twice, and pushes it across the desk with one finger, as if it might be hot. 'Mrs Pudsey at the Hen will not ask you for a reference. Do not tell Ottoline I did this. She would think I was ill.'".
    On discuss { Assert prewittBed(actor). Increase quantity(actor, gold) by 8. }
  }
}

data/adventures/quittance/tithe.kyr:
Module quittance "Quittance" {
  Description "The Great Tithe: the Cinder Ward on Reckoning night, six men with oil and a cart, and five ways the night can go that are not the fire. And the Phoenix's wardens, who come for a company that has made an enemy of the Chief Underwriter.".

  Relation titheStopped(group). Relation titheEvacuated(group). Relation tithePaused(group). Relation wardensSent(group). Relation wardensPaid(group).

  // ── The burners ─────────────────────────────────────────────────────────────────────────────────────────
  Person tithe_burners "the Tithe men" at skelter_room {
    Role "six men with oil-cans, a handcart and a foreman who has done this before". Ancestry human. Calling warrior. Level 3. Numbers 6. Pronouns they.
    Temperament territorial.
    Warns "The handcart stops at the mouth of the lane. The foreman looks at you, and at the lit windows behind you, and at his men, and for a moment you can see him arithmetic: six against whatever you are. 'Condemned,' he says, without hope. 'By order. We're to abate it by midnight. You're in the way of an abatement.'".
    Comes "The foreman puts down his can and picks up a billet of ash. 'Right,' he says. 'All of you, then,' and the six come at you across the black ground with their oil swinging.".
    Flinches "The Tithe men give ground, and then give more; the handcart goes over on its side, and the oil spreads on the stones in a long slow fan that nobody dares to strike a light near.".
    Pleads "'It's not the money,' says the foreman, flat on his back with a hand held up. 'It's that they know where I live.'".
    Refuge skelter_room.
    Lair cinder_ward.
  }
  Initially Assert tolerates(tithe_burners, party).
  Rule tithe_men_come when watch(clock) >= 1236 and tithePrepared(city) and not titheStopped(city) and not at(tithe_burners, cinder_ward) { Assert at(tithe_burners, cinder_ward). }
  Rule tithe_men_beaten when (routed(tithe_burners) or dead(tithe_burners)) and not titheStopped(city) { Assert titheStopped(city). }
  Observe tithe_men_seen at cinder_ward when at(tithe_burners, cinder_ward) and not titheStopped(city) and not burned(cinder_ward) "A handcart stands at the foot of the black chimney with six men round it in the dark, waiting for a clock. The oil-cans are the sort that are sold for lamps, and there are a great many of them. All round the Ward the windows are lit, and nobody has gone to bed.".
  Observe tithe_stopped_scene at cinder_ward when titheStopped(city) and not burned(cinder_ward) "The Ward is lit and standing. A handcart lies on its side in a pool of lamp-oil that a boy is carefully, one handful at a time, fencing off with ash.".
  // The Great Tithe stopped, by whichever hand, is one the burn does not happen to.
  Rule tithe_burn_checks when watch(clock) >= 1248 and titheStopped(city) and not tithePaused(city) { Assert tithePaused(city). }

  // ── Five ways round it ──────────────────────────────────────────────────────────────────────────────────
  Action evacuate_ward(actor: group, site: place) "Call the Ward out of its houses, street by street, and stand it on the Cinderwall" {
    Requires able(actor) and company(actor) and at(actor, cinder_ward) and tithePrepared(city) and not titheEvacuated(actor) and not burned(cinder_ward)
      and (regard(wardsfolk) >= 2 or entered_gap(actor) or keeper(wards) or pm_court_warned(actor)).
    Time 60 minutes.
    On success { Assert titheEvacuated(actor). }
    Result "It takes an hour, and nobody asks you why. The Wards know a knock at a door in the night: they come down in their nightclothes with their grandmothers on their arms and the clocks under their coats, street by street, to the Cinderwall, and sit along it in rows with the lamps behind them. A woman counts them twice. Nobody is left in the Ward but the cats, and the cats have been asked and have declined.".
  }
  Action brigades_in_one_line(actor: group, site: place) "Bring both brigades to the lane in one line, with the pumps primed" {
    Requires able(actor) and company(actor) and at(actor, cinder_ward) and tithePrepared(city) and not titheStopped(city) and arc(garrity) >= 1 and (arc(dree) >= 1 or regard(lamprey) >= 2).
    Time 45 minutes.
    On success { Assert titheStopped(city). }
    Result "They come up Salt Lane at the double, blue and black, side by side, on the same side of the whitewash, which each captain will later describe as an accident of the lane. Garrity has the pump; Dree has the hose; neither of them is looking at the other. They draw up across the mouth of the lane with the nozzles up, and the Tithe men look at the plates over the doors, and at the two captains, and at the arithmetic, and set down the cans.".
  }
  Action read_the_second_column(actor: group, site: place) "Read the second column of Skelter's book aloud to the Ward and the Tithe men, name by name" {
    Requires able(actor) and company(actor) and at(actor, cinder_ward) and tithePrepared(city) and not titheStopped(city) and holding(actor, skelter_book) and regard(wardsfolk) >= 1.
    Time 30 minutes.
    On success { Assert titheStopped(city). Increase argued(city) by 1. }
    Result "You begin with Candlewick Court and the date. You say the nineteen names, which Skelter has written down. The Ward comes out of its doors to listen, one house at a time, until the whole of the black ground is full, and at the thirty-first name a man in the crowd says, quite quietly, 'That's my brother,' and the foreman puts down his can. 'I never knew the names,' he says. 'He said they were empty.'".
  }
  Action turn_the_foreman(actor: group, site: place) "Take the foreman aside, and ask him what his own hearth is" {
    Speaker tithe_burners.
    Requires able(actor) and company(actor) and at(actor, site) and at(tithe_burners, site) and tithePrepared(city) and not titheStopped(city).
    Time 15 minutes.
    Resolve check(actor, insight, dc_hard).
    On success { Assert titheStopped(city). }
    On failure { Retract tolerates(tithe_burners, actor). }
    Result "He turns his cap over twice. 'A stove,' he says. 'Iron. With a door. My mother had a coal in a tin and the Ordinance took it off her the winter she died, and I held the shovel.' He does not say anything more; he turns the handcart round, and the others, after a moment, push.".
    Otherwise "'You've a good voice,' says the foreman, not unkindly. 'I've heard it before. It's the voice of someone who doesn't live here.'".
  }

  // ── The Phoenix's wardens ───────────────────────────────────────────────────────────────────────────────
  // A company that has made an enemy of the Chief Underwriter is looked for. Three wardens of the Phoenix, blue-coated,
  // courteous and armed, are sent for it when the threat has been made.
  Person wardens "three wardens of the Phoenix" at nowhere {
    Role "three wardens with staves and a warrant". Ancestry human. Calling warrior. Level 3. Numbers 3. Pronouns they.
    Temperament territorial.
    Warns "Three men in the Phoenix's blue come through the crowd with their staves held crossways, politely, as one carries a rail. 'You'll be the adjusters,' says the sergeant. 'We've a paper that says you're no longer. It's the Chief Underwriter's. You're to come and discuss it.'".
    Comes "The sergeant sighs, and the staves come down. 'Don't make us explain it to the Chief,' he says.".
    Flinches "The wardens withdraw down the Row with dignity, taking their warrant with them, and their sergeant's hat is left behind on the cobbles.".
    Pleads "'You'll not tell Ottoline,' says the sergeant, sitting down on the kerb. 'She taught my daughter to read.'".
    Refuge nowhere.
  }
  Rule wardens_sent when prewittHardened(party) and not wardensSent(party) and hour(clock) >= 8 and hour(clock) < 18 { Assert wardensSent(party). Assert at(wardens, row_street). }
  Action pay_the_wardens(actor: group, site: place) "Pay the wardens' fee for the warrant's inconvenience, and ask them to lose it (12 coin)" {
    Speaker wardens.
    Requires able(actor) and company(actor) and at(actor, site) and at(wardens, site) and quantity(actor, gold) >= 12 and not wardensPaid(actor).
    Time 10 minutes.
    On success { Decrease quantity(actor, gold) by 12. Assert wardensPaid(actor). Assert tolerates(wardens, actor). Assert at(wardens, nowhere). }
    Result "The sergeant counts it with his thumb in the palm of his hand. 'The warrant,' he says, 'is a very delicate paper. It has a way of going missing in a wet coat.' He tips his hat, and they go.".
  }
  Action ottoline_calls_them_off(actor: group, site: place) "Ask Ottoline to tell the sergeant the warrant is hers to withdraw" {
    Speaker wardens.
    Requires able(actor) and company(actor) and at(actor, site) and at(wardens, site) and travelsWith(ottoline, actor) and not wardensPaid(actor).
    Time 5 minutes.
    On success { Assert wardensPaid(actor). Assert tolerates(wardens, actor). Assert at(wardens, nowhere). }
    Result "Ottoline Prewitt steps between you and the staves with her pencil behind her ear and says, in an even voice, 'Sergeant. Whose daughter do you think taught yours her letters?' The staves go up. 'It's not for me to say, miss,' says the sergeant. 'No,' says Ottoline. 'It's for me.' They go back down the Row at a march, not looking round.".
  }
}

data/adventures/quittance/voices.kyr:
Module quittance "Quittance" {
  Description "What each of the company makes of the city, by what they are: the ranger on the ground, the warrior in the yard, the cleric at the Queue and the hearth. One way through the Gasket Yard that only a ranger sees, one that only a cleric can give the Fire, one that only a warrior can put to six men, and the quarrel at the Yard that the company has to settle with itself.".

  // The preset party is not a set of declared people, so it has no Remarks of its own. What a rule can ask of a member is
  // their calling, and print their name. Each voice is said once for the company, by whoever has the calling; a company
  // without one has nobody to notice, and must notice for itself.
  Relation qv_hCourt(group). Relation qv_hDrill(group). Relation qv_hQueue(group). Relation qv_hHearth(group).
  Relation qv_hWard(group). Relation qv_hHall(group).
  Relation qv_quarrelled(group). Relation qv_sidedWarrior(group). Relation qv_sidedCleric(group).
  Relation qv_cistern(group). Relation qv_office(group). Relation qv_lined(group).

  // ── Act One: Assessment ─────────────────────────────────────────────────────────────────────────────────
  Rule qv_voice_court at candlewick when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, candlewick) and not qv_hCourt(party)
    says "{?m} goes along the foot of the houses on one knee, and stops where the gutter-stones are stained dark in a line from the lane to the pump. 'Oil,' {?m} says. 'Not spilled: laid. Somebody has walked this twice with a can, a hand's breadth from the wall, so it would not show from the lane.' {?m} looks up at the sheet on the line. 'Whoever it was has been very careful of the washing.'" {
    Assert qv_hCourt(party).
  }
  Rule qv_voice_drill at drill_yard when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and at(party, drill_yard) and not qv_hDrill(party)
    says "{?m} watches forty buckets go hand to hand along the whitewash and shakes a head slowly. 'They drill for a fire that has been announced,' {?m} says. 'Look at the pumps: new leather, and nobody has wet it. A brigade that expected to be surprised would have its hose in a heap. This one has its hose coiled for a long march and a short stand.' The sergeant on the line, who has been listening, does not look round, and makes the count a little louder." {
    Assert qv_hDrill(party).
  }

  // ── Act Two: Adjustment ─────────────────────────────────────────────────────────────────────────────────
  Rule qv_voice_queue at queue_hall when memberOf(?m, party) and hasCalling(?m, calling_cleric) and awake(?m) and at(party, queue_hall) and not qv_hQueue(party)
    says "{?m} stands at the end of the Queue, which does not notice, and then takes off a hat that is not there. 'This is not a line,' {?m} says, very low. 'There is a form for this and it is not the Exchange's. A line moves. These people are keeping a watch. Somebody sat down in this hall ninety-four years ago and was told to wait, and the whole room has waited with them ever since, so that they would not wait alone.'" {
    Assert qv_hQueue(party).
  }

  // ── Act Three: Settlement ───────────────────────────────────────────────────────────────────────────────
  Rule qv_voice_hearth at hearn_hearth when memberOf(?m, party) and hasCalling(?m, calling_cleric) and awake(?m) and at(party, hearn_hearth) and not qv_hHearth(party)
    says "{?m} holds both hands to Auberon's little coal and takes them away again quickly. 'It is not burning anything,' {?m} says. 'Look at the grate. No ash. It has been lit for ninety-four years and it has made no waste.' {?m} says the next part more quietly, to the old man's back: 'That is not how a fire behaves. That is how a guest behaves who has been told not to leave a mess.'" {
    Assert qv_hHearth(party).
  }
  Rule qv_voice_ward at cinder_ward when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, cinder_ward) and day(clock) >= 7 and not qv_hWard(party)
    says "{?m} licks a finger and holds it up, and the finger goes cold on one side only: the side that faces the black chimney. 'It is drawing,' {?m} says. 'Dead cold chimney, no fire in it, and the air is going in at the foot like a held breath. Every house in the Ward is leaning toward it. If I were to lay a fire here, I would lay it so, with the wind helping.' {?m} is quiet a moment. 'Somebody did.'" {
    Assert qv_hWard(party).
  }

  // ── Act Four: Reckoning ─────────────────────────────────────────────────────────────────────────────────
  Rule qv_voice_hall at hall_five when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and at(party, hall_five) and day(clock) >= 8 and not qv_hHall(party)
    says "{?m} stands with a back to the wall, as a warrior does in a room full of people who have never been hit, and counts the Chairmen's chairs. 'Five seats and six cushions,' {?m} says. 'There is a cushion with nobody on it, and it is warm. It is not one of ours.' The nearest clerk goes the colour of the Receipt." {
    Assert qv_hHall(party).
  }

  // ═══ A way through that only a ranger sees: the Yard's dry well ═════════════════════════════════════════
  // Dolly Orrimer pumps a dry well on principle. The notice calls the Yard a hazard, and the Ordinance defines a hazard by
  // its want of water. A ranger reads the ground and finds that the well is not dry: someone closed the cock, in the
  // autumn, with a key. Opened, it gives water, and the abatement has no premise.
  Observe qv_gasket_damp at gasket_yard when not qv_cistern(party) and not burned(gasket_yard) "Under the dry well, where the cobbles meet the slab, there is a ring of ground a shade darker than the rest. Dolly Orrimer's pump-handle goes up and down above it with a dry gasp.".
  Action qv_ranger_cistern(actor: group, site: place, r: member) "Read the ground round the dry well, and dig for what closed it" {
    Description "A well that does not give is either empty or shut. Its want of water is the whole of the notice on its head.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gasket_yard) and at(dolly, site) and memberOf(r, actor) and hasCalling(r, calling_ranger)
      and knows(actor, d_gasket_next) and not gasketSaved(actor) and not burned(gasket_yard) and not qv_cistern(actor).
    Time 40 minutes.
    On success { Assert qv_cistern(actor). Assert gasketSaved(actor). Retract at(burners, gasket_yard). Increase regard(wardsfolk) by 1. }
    Result "{r} walks the Yard in a slow spiral, looking at nothing but the way water has not been. By the well-head {r} stops, kneels, and clears the slab-edge with a thumb: a socket, and in the socket a brass bonnet the size of a pie, green with a winter's damp and turned fully shut. 'There,' says {r}. 'Somebody wanted it thirsty.' It takes three of Dolly's neighbours and a bar to lift the bonnet, and a quarter of an hour for the dry gasp in the pump to become a cough and then a gush. Dolly Orrimer stands in a spreading puddle with the handle in both hands, and for the first time since autumn is speechless. At dusk, Dolly says afterwards, four men with a pole-ladder came as far as the corner of the lane, as men do who have been told a place is empty, and looked at the notice on the well-head, which says NO WATER, and at the well, which was running over into the gutter, and one of them said, 'Then I've no abatement,' and they went home by the Night Market with their cans full.".
  }

  // ═══ The quarrel at the Yard, and the choice it asks ════════════════════════════════════════════════════
  // A company with a warrior and a cleric has the argument; each is right; it is settled by the company, and the settling
  // costs the other. The warrior's way keeps the Yard standing and loses the Wards' regard. The cleric's way lets the Yard
  // burn empty and wins it. The ranger's way, above, costs neither, and only a ranger has it.
  Rule qv_quarrel_yard at gasket_yard when memberOf(?w, party) and hasCalling(?w, calling_warrior) and awake(?w)
    and memberOf(?c, party) and hasCalling(?c, calling_cleric) and awake(?c)
    and at(party, gasket_yard) and knows(party, d_gasket_next) and not gasketSaved(party) and not gasketWarned(party) and not burned(gasket_yard) and not qv_quarrelled(party)
    says "{?w} says it first, because somebody must. 'There are four of them and a pole-ladder, and they are coming at dusk. Take the oil off them at the Night Market and there is no fire.' {?c} is looking at the women round the well, who have stopped pretending not to listen. 'And the next time a man in a clean coat tells them a thing is a hazard, they will remember that the last people to come into the Yard came with their hands,' says {?c}. 'Tell them. Let them carry their own beds.' Neither looks at you. Both are waiting for you to say which of them is right." {
    Assert qv_quarrelled(party).
  }
  Action qv_side_warrior(actor: group, site: place, w: member, c: member) "Tell {c} that {w} is right: go to the Night Market and take the oil" {
    Description "The Yard stands. The Wards will have seen what an adjuster does when pressed, and what they have seen they will not forget.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gasket_yard) and qv_quarrelled(actor) and not qv_sidedWarrior(actor) and not qv_sidedCleric(actor)
      and not gasketSaved(actor) and not burned(gasket_yard)
      and memberOf(w, actor) and hasCalling(w, calling_warrior) and memberOf(c, actor) and hasCalling(c, calling_cleric).
    Time 3.
    On success { Assert qv_sidedWarrior(actor). Assert gasketSaved(actor). Retract at(burners, gasket_yard). Decrease regard(wardsfolk) by 1 or to nothing. }
    Result "{c} says nothing, and goes on saying nothing all the way to the Night Market. {w} does it without a speech: a hired man at a stall, a barrel with the Gas Company's stencil on it, a cart-pin drawn and pocketed, six cans tipped into the gutter in a long bright fan. Nobody is hurt. A woman at the next stall, who has sold eel-pies in that place for twenty years, watches the whole of it with her pie held out to a customer, and does not charge the customer. 'Yard's safe, then,' she says, as you pass. It is not said as thanks. By evening the story is in Salt Lane, and in Salt Lane it has grown a second man, and a knife.".
  }
  Action qv_side_cleric(actor: group, site: place, w: member, c: member) "Tell {w} that {c} is right: wake the Yard, and let it carry its own beds" {
    Description "The Yard burns, and burns empty; and it will know who told it, and in what voice.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gasket_yard) and qv_quarrelled(actor) and not qv_sidedWarrior(actor) and not qv_sidedCleric(actor)
      and not gasketSaved(actor) and not gasketWarned(actor) and not burned(gasket_yard)
      and memberOf(w, actor) and hasCalling(w, calling_warrior) and memberOf(c, actor) and hasCalling(c, calling_cleric).
    Time 3.
    On success { Assert qv_sidedCleric(actor). Assert gasketWarned(actor). Increase regard(wardsfolk) by 1. }
    Result "{w} says nothing against it, which is not the same as agreeing, and spends the afternoon carrying other people's mattresses up the lane with a face like a shut door. {c} goes from house to house in the voice of someone who has told families things before, and not one house asks for proof. Dolly Orrimer pumps her dry well until the last bed is out, from habit, and then sits on the rim of it with her arms folded to see it done. 'It'll go,' she says. 'It's a hazard.' She says it quite gently. When dusk comes the Yard is out in the lane in rings of chairs, all present; the burners find the oil useful and the Yard empty, and light it anyway, because it was on the list.".
  }

  // ═══ A way that only a cleric can give: the Office for the burned ══════════════════════════════════════
  // The Fire has been asked to hear 1,104 names read, an hour to a hundred, and a hearer with a ledger can do it. A cleric
  // has another thing: the form for a house where a fire has gone out, said over the hearth as it is said at a grave, which
  // does not need the names, because it is not for the names. It is for the room.
  Action qv_cleric_office(actor: group, site: place, c: member) "Let {c} say the Office for a house where the fire has gone out, over the Fire's own hearth" {
    Description "It is the one thing a cleric of the vitalist rite has that is meant for a hearth rather than a body. It takes the better part of an hour, and it is not a bargain.".
    Speaker ds_fire.
    Requires able(actor) and company(actor) and at(actor, site) and at(ds_fire, site) and fireHeard(actor) and not fireWrathful(actor)
      and memberOf(c, actor) and hasCalling(c, calling_cleric) and not qv_office(actor).
    Time 50 minutes.
    On success { Assert qv_office(actor). Increase ds_accord(actor) by 3. Decrease ds_slight(actor) by 1 or to nothing. Assert fireFed(actor). }
    Result "{c} kneels in the ash, which is warm, and begins in the voice used at the bedside of the dying: not the sermon, the other thing, the one that is only for the room. It names no names. It says that the fire in this house is out, and that its people are not here, and that those who are here sit with it. The Fire listens without moving. At the third repetition the coal draws in, the heat goes soft, and a long breath comes off the ash. 'That,' says the Fire, 'is the form. I had forgotten there was a form.' It does not thank {c}. It says, in a voice that for a moment is not a creditor's at all: 'Nobody has said it over me. They said it over everyone else.'".
  }

  // ═══ A way that only a warrior can put to six men: the Tithe line ═══════════════════════════════════════
  // The Tithe men are the strongest of the burners. A warrior does not argue with them. A warrior counts them.
  Action qv_warrior_line(actor: group, site: place, w: member) "Let {w} walk the line of the Tithe men and count them aloud, as a sergeant does" {
    Description "Six cans, six men, a cart, and the knowledge that two of them have already looked at the door. A warrior knows a line that has stopped wanting to be one.".
    Speaker tithe_burners.
    Requires able(actor) and company(actor) and at(actor, site) and at(tithe_burners, site) and tithePrepared(city) and not titheStopped(city) and not qv_lined(actor)
      and memberOf(w, actor) and hasCalling(w, calling_warrior).
    Time 10 minutes.
    Resolve check(actor, intimidation, dc_fair).
    On success { Assert qv_lined(actor). Assert titheStopped(city). }
    On failure { Assert qv_lined(actor). Retract tolerates(tithe_burners, actor). }
    Result "{w} walks the line from the left, slowly, looking each man in the lower face. 'One. Two, who is thinking of his mother. Three, who has a bad knee and knows it.' At the fourth the foreman starts to say something and {w} lifts one finger and he stops. 'Six cans,' {w} says. 'Six men. And somewhere on this side of the Wall there is a seventh who is not holding anything, and has gone for the Phoenix.' There is no seventh. Nobody on the line is certain of that. The cans are put down in an order, rather than all at once, and the handcart goes back up Salt Lane with a wheel that has suddenly begun to squeak.".
    Otherwise "{w} gets as far as the third man. 'Count away,' says the foreman, quite gently, 'we've done it ourselves.' A can is lifted. The line, which was beginning to wonder, stops wondering.".
  }
}

data/adventures/sallowfield/arcs.kyr:
Module sallowfield "Three Nights at Sallowfield" {
  // ── Three who will come with the company, and the others' small knots ────────────────────────────────────────
  Relation pinnSent(group). Relation pinnRisk(group). Relation pinnRoof(group). Relation pinnBrave(group). Relation pinnHome(group).
  Relation craggKin(group). Relation craggKilled(group). Relation craggBow(group). Relation craggGave(group).
  Relation mowbrayPeace(group). Relation mowbrayArms(group). Relation plateGiven(group). Relation plateKept(group). Relation mowbrayRaised(group).
  Relation wadsworthRan(group). Relation ellandFights(group).

  // ── Davy Pinn: twelve, with a sling ───────────────────────────────────────────────────────────────────────────
  Topic pinn_talk with pinn "Ask Davy what he would do if the soldiers came" when true once {
    Says "Davy Pinn takes the sling from round his neck and winds it round his fist, and unwinds it. 'Hit them,' he says. 'What else?' Then, not so loud: 'My da says boys don't. My da is at the mill all day. Do you think I'm too young?'".
  }
  Topic pinn_young with pinn "Yes. Stay with your mother" answering pinn_talk when true {
    Says "Davy goes red to the hair, and says, 'Oh,' and goes back to his pin. After a minute: 'I'll be on the green, then. If anybody needs me.' He does not look round.".
    On discuss { Assert pinnSent(actor). }
  }
  Topic pinn_useful with pinn "Old enough to be useful. Not old enough to be a hero" answering pinn_talk when true {
    Says "'Useful,' says Davy, trying the word. 'I can be useful, then.' He is already thinking about where. 'You tell me where, and I'll be there.'".
    On discuss { Assert willing(pinn, actor). Set hire(pinn) to 0. }
  }
  Topic pinn_all with pinn "Tonight everyone is old enough" answering pinn_talk when true {
    Says "Davy's face does something complicated, and then he is standing as straight as the sling will let him. 'I'm coming,' he says. 'I'll be good. I'll be the best.'".
    On discuss { Assert willing(pinn, actor). Set hire(pinn) to 0. Assert pinnRisk(actor). }
  }
  Topic pinn_roof_ask with pinn "Put Davy on the tower roof, behind the parapet" when travelsWith(pinn, actor) and not pinnRoof(actor) once {
    Says "'The roof,' says Davy. 'Where nobody can get at me.' He is not pleased, and then he is. 'I can see the whole bridge from the roof. I can hit the man with the horn.' He goes up the ladder at a run.".
    On discuss { Assert pinnRoof(actor). }
  }
  Rule pinn_does_it when pinnRoof(party) and travelsWith(pinn, party) and watch(clock) >= assaultAt(wyre) + 6 and not pinnBrave(party) {
    Assert pinnBrave(party). Increase defence(nave) by 3. Increase defence(bridge) by 2. }
  Rule pinn_roof_falls when pinnRoof(party) and overrun(nave) and not pinnHome(party) and dice(pinn) <= 50 { Assert pinnHome(party). Slay pinn. Assert felled(pinn). }
  Rule pinn_runs_out when pinnRisk(party) and not pinnRoof(party) and travelsWith(pinn, party) and watch(clock) >= assaultAt(wyre) + 12 and not pinnHome(party) and dice(pinn) <= 60 {
    Assert pinnHome(party). Slay pinn. Assert felled(pinn). }
  Rule pinn_lucky when pinnRisk(party) and not pinnRoof(party) and travelsWith(pinn, party) and watch(clock) >= assaultAt(wyre) + 12 and not pinnHome(party) and dice(pinn) > 60 {
    Assert pinnHome(party). Assert pinnBrave(party). }

  // ── Ellen Cragg: arrows, and a husband's bow ──────────────────────────────────────────────────────────────────
  Topic cragg_talk with cragg "Ask Mistress Cragg why she is counting arrows in a church" when true once {
    Says "'Because somebody has to know the number,' says Ellen Cragg. 'Nobody tells you that. You think war is hitting people. It is mostly knowing the number.' She lays an arrow on the pile. 'Who have you buried, then? You'd not ask a woman that question if you had not buried someone.'".
  }
  Topic cragg_none with cragg "Nobody. Not yet" answering cragg_talk when true {
    Says "'Then you'll not know the number,' says Ellen Cragg, not unkindly. 'I will tell you it. Whatever you think it is, it is more.' She nods you to the pile. 'I'll come. Somebody should be counting.'".
    On discuss { Assert willing(cragg, actor). Set hire(cragg) to 0. }
  }
  Topic cragg_lost with cragg "A friend. I could not save him" answering cragg_talk when true {
    Says "'Ah,' says Ellen Cragg. She looks at you for the first time as someone who has been addressed as an equal. 'Then you know the other thing about numbers.' She takes up her quiver. 'I will come with you.'".
    On discuss { Assert willing(cragg, actor). Set hire(cragg) to 0. Assert craggKin(actor). }
  }
  Topic cragg_killed with cragg "People I killed" answering cragg_talk when true {
    Says "Ellen Cragg does not move. 'I see,' she says. 'It is honest. I had a husband who could say that and it made him good with a bow.' She thinks. 'I'll come. Don't expect me to like it. It might not come up.'".
    On discuss { Assert willing(cragg, actor). Set hire(cragg) to 0. Assert craggKilled(actor). }
  }
  Discovery cragg_bow_known "Ellen Cragg's husband's bow hangs in Greenhalgh's barn, where he left it.".
  Topic cragg_bow_ask with cragg "Ask Mistress Cragg whether there is a better bow in the village" when travelsWith(cragg, actor) and not craggBow(actor) once {
    Says "'Hal's,' she says at once, and then does not say anything for a while. 'It hangs in Greenhalgh's barn, where I lent it him at harvest-home for the crows. It is a good bow. It has not been drawn since.' She looks at her hands. 'It would be a mercy to hear it.'".
    On discuss { Assert knows(actor, cragg_bow_known). }
  }
  Action fetch_bow(actor: group, site: place) "Take Hal Cragg's bow down from Greenhalgh's barn" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lower_farm) and knows(actor, cragg_bow_known) and not craggBow(actor) and not farmBurned(party).
    Time 3.
    On success { Assert craggBow(actor). }
    Result "It is where she said, on two pegs, oiled, with the string slackened. It is lighter than it looks. It has her husband's initials burned into the stave, and a notch for every year of the crows.".
  }
  Action cragg_arrows(actor: group, site: place, p: place) "Ask Ellen to put the last of her arrows at {p}" {
    Requires able(actor) and company(actor) and at(actor, site) and travelsWith(cragg, actor) and postsite(p) and not craggGave(actor) and watch(clock) >= assaultAt(wyre) + 6 and watch(clock) < assaultAt(wyre) + 12 and w2planned(party).
    Time 0.
    On success { Assert craggGave(actor). Increase defence(p) by 3. }
    Result "Ellen counts them out into the hands of whoever is nearest, aloud, to the last one. 'Forty-one,' she says. 'Remember it.'".
  }
  Rule cragg_bow_sings when craggGave(party) and craggBow(party) and not craggBowDone(party) { Assert craggBowDone(party). Increase defence(ford_stones) by 2. }
  Relation craggBowDone(group).

  // ── Father Mowbray: swears, and has the plate ─────────────────────────────────────────────────────────────────
  Topic mowbray_talk with mowbray "Ask Father Mowbray whether he would kill, if it came to it" when true once {
    Says "'Damn your eyes,' says Mowbray. 'In his own church!' He sits down hard on the pew. Then, flat: 'I have buried a good many who knew. None of them was the better for it.'".
  }
  Topic mowbray_yes with mowbray "Yes, in your place. Come and be a man with a staff" answering mowbray_talk when true {
    Says "He looks at the staff in the corner, which is a good staff. 'Hell and blood,' says Mowbray, almost happily, and hefts it. 'I'll come.'".
    On discuss { Assert willing(mowbray, actor). Set hire(mowbray) to 0. Assert mowbrayArms(actor). }
  }
  Topic mowbray_no with mowbray "No. Come and keep the hurt alive" answering mowbray_talk when true {
    Says "'That,' says Mowbray, 'I can do.' He takes a roll of linen from the plate-chest, where it is evidently the real treasure. 'God send you do not need it, and he will send you need it. I'll come.'".
    On discuss { Assert willing(mowbray, actor). Set hire(mowbray) to 0. Assert mowbrayPeace(actor). }
  }
  Topic mowbray_plate with mowbray "The reeve wants the plate for Wyre. What do you say?" when travelsWith(mowbray, actor) and knows(actor, reeve_would_pay) and not plateGiven(actor) and not plateKept(actor) once {
    Says "'What do I say,' says Mowbray. He sits down on the plate-chest. 'I say it was given to Saint Eadred by a woman who sold her bed for it, in the year of the sweating sickness, and I say I would melt it into spurs for Wyre myself if it would save one child.' He looks up. 'It will not save one child. Men who take the plate take the rest. But I am not the reeve. Tell me, and I'll do it, and be damned for it myself.'".
  }
  Topic mowbray_give with mowbray "Give it, if it is asked" answering mowbray_plate when true {
    Says "He nods, twice. 'God forgive us,' says Mowbray. 'He will be better at it than I.' He unbolts the chest.".
    On discuss { Assert plateGiven(actor). }
  }
  Topic mowbray_keep with mowbray "Keep it. It is not ours to trade" answering mowbray_plate when true {
    Says "'Well,' says Mowbray. 'Well, damn it,' and gets up, and bolts the chest, and is a different man. 'Then it stays where it is, and I'll stay with it.'".
    On discuss { Assert plateKept(actor). }
  }
  Rule arms_help when mowbrayArms(party) and travelsWith(mowbray, party) and watch(clock) >= assaultAt(wyre) - 12 and not armsMod(party) { Assert armsMod(party). Increase drillBonus(party) by 1. }
  Relation armsMod(group).
  Action mowbray_raises(actor: group, site: place, v: group) "Ask Father Mowbray to say the rite over {v}, who fell" {
    Requires company(actor) and at(actor, site) and travelsWith(mowbray, actor) and mowbrayPeace(actor) and not mowbrayRaised(actor) and felled(v) and villager(v) and watch(clock) >= assaultAt(wyre) + 12 and watch(clock) < assaultAt(wyre) + 42.
    Time 2.
    Resolve check(actor, rites, dc_hard).
    On success { Restore v. Retract felled(v). Assert mowbrayRaised(actor). }
    On failure { Assert mowbrayRaised(actor). }
    Result "Mowbray kneels in the blood, swearing steadily, and puts both hands on the body. The words are not elegant. They are, you understand, in the vulgar tongue, and they are an argument. At the end of it {v} coughs.".
    Otherwise "He says the rite to the end. Then he says it again, with the swearing left out, which is worse. {v} does not stir.".
  }

  // ── The small knots ───────────────────────────────────────────────────────────────────────────────────────────
  Topic quarmby_mill with quarmby "Ask Gil Quarmby what the mill is worth to him" when true once {
    Says "'Forty years,' says Quarmby, wiping flour off his forehead with a floury hand and making it worse. 'Father's. Grandfather's. Don't tell me what you want it for, I can see it from here.' He jerks his chin at the race. 'The gate. Drown the meadow. That's Greenhalgh's hay, and Greenhalgh would burn my wheel for it and I'd not blame him. You'd drown your own hay?'".
  }
  Topic quarmby_yes with quarmby "If it saves the mill, yes" answering quarmby_mill when true {
    Says "'Hmph. That's my own thought, and it's sour.' He takes a key off a nail. 'Pin at the head. Bring a bar, I'm not lending mine.'".
    On discuss { Assert quarmbyAgrees(actor). }
  }
  Topic quarmby_no with quarmby "No. We will find another way" answering quarmby_mill when true {
    Says "'Fine,' says Quarmby, to a sack. 'Fine. I'll hold it. Nobody'll shift me once the sun's down, so don't ask.'".
    On discuss { Assert posted(quarmby, mill_yard). }
  }
  Topic greenhalgh_go with greenhalgh "Tell Ned Greenhalgh to take his cows to the fold" when true once {
    Says "'And leave the barn?' says Greenhalgh. 'My father built that barn.' He leans on the gate. 'Tell me one thing that is not a lie. Will they come here first?'".
  }
  Topic greenhalgh_true with greenhalgh "Yes. The farm is the first they reach" answering greenhalgh_go when true {
    Says "Greenhalgh spits, and wipes his mouth. 'Not hard, that.' He whistles the dog off the yard. 'I'll drive them. You can mend the barn yourselves.'".
    On discuss { Assert greenhalghAgreed(actor). }
  }
  Relation greenhalghAgreed(group).
  Action drive_the_cows(actor: group, site: place) "Help Ned Greenhalgh drive the cows up to the fold" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lower_farm) and greenhalghAgreed(actor) and not evacuatedFarm(actor).
    Time 24.
    On success { Assert evacuatedFarm(actor). Assert greenhalghSaved(actor). }
    Result "Forty head, a dog that has views, and a track that was not made for them. It takes the afternoon. At the fold Crowther opens the wall and shuts it, and Greenhalgh does not look back at the barn.".
  }
  Topic greenhalgh_lie with greenhalgh "No. They will go straight for the ford" answering greenhalgh_go when true {
    Says "He looks at you until the cow shifts. 'You are a bad liar,' he says, kindly, and goes back to the cow he was milking.".
  }
  Action rally_wadsworth(actor: group, site: place) "Let Hob Wadsworth tell you how he would hold the bridge" {
    Requires able(actor) and company(actor) and at(actor, site) and at(wadsworth, site) and able(wadsworth) and not posted(wadsworth, bridge) and nerve(wadsworth) >= 1.
    Time 1.
    On success { Assert posted(wadsworth, bridge). }
    Result "It takes forty minutes and includes the Siege of Marden, in which he was not present, and two cousins. At the end of it he has said he will hold the bridge, and means it with the whole of his chest, and is already a little less pink.".
  }
  Rule wadsworth_breaks when posted(wadsworth, bridge) and not steadied(wadsworth) and watch(clock) >= assaultAt(wyre) + 6 and not wadsworthRan(party) and overrun(bridge) {
    Assert wadsworthRan(party). Retract posted(wadsworth, bridge). }
  Topic elland_count with elland "Ask Tib Elland how many sacks there are" when true once {
    Says "'Ninety, ninety, ninety,' says Tib Elland, and breathes. 'Sixty people. Ninety sacks. A person eats a sack and a half in a winter, and it is not enough, and the Margrave takes a third.' He looks small. 'It is a sum I can do. I cannot, I cannot do the other sum.'".
  }
  Topic elland_stand with elland "Say that he can hold a door with a stick, like anyone" when true once {
    Says "He takes a tally-stick in each hand and looks at them as though for the first time. 'It is a stick,' he says. 'I could hold a door with a stick.' He does not sound as if he thinks he could.".
    On discuss { Assert ellandFights(actor). Set nerve(elland) to 1. }
  }
  Topic kersey_iron with kersey "Ask Peg Kersey what the iron is for" when true once {
    Says "'Strap,' says Peg Kersey. 'Coach.' She lifts it out with the tongs. 'Or caltrops. Four hundred. Or both, more iron. No more iron.' She sets it down. 'Yours to say.'".
  }
  Topic kersey_spikes with kersey "Make the spikes" answering kersey_iron when true {
    Says "'Spikes,' says Kersey. 'Coach stays.'".
    On discuss { Assert ironForSpikes(actor). }
  }
  Topic kersey_axle with kersey "Mend the axle" answering kersey_iron when true {
    Says "'Two days,' says Kersey, and files. 'Didn't think you'd stay. Shouldn't.'".
    On discuss { Assert coachMended(actor). }
  }
  Action work_the_forge(actor: group, site: place) "Work Peg Kersey's bellows for nine hours while she makes the spikes" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, forge) and ironForSpikes(actor) and not caltrops(party).
    Time 54.
    On success { Assert caltrops(party). Increase defence(ford_stones) by 3. Increase defence(bridge) by 1. }
    Result "Nine hours of it. The bellows is a lung as big as a boy and it takes all of you in turn. By dusk the floor of the forge is a field of black points, and Peg Kersey is sweeping them into sacks with her hands, and not a drop of blood on her.".
  }
}

data/adventures/sallowfield/battle.kyr:
Module sallowfield "Three Nights at Sallowfield" {
  // ── The night ─────────────────────────────────────────────────────────────────────────────────────────────────
  // Wyre comes at dusk of the third day (or the second, if his riders found the town unwatched). The night is two
  // waves, with the company's choices between them:
  //   +0   the wear: each post loses a quarter of what he sends at it.
  //   +6   the first wave: at each post, what stands there (works, the posted, the drill, the company if it is there)
  //        against what Wyre sent. The reports come in, some late, some wrong.
  //   +6..+12  the company's hour: fall back from a post, hold one to the last, burn the bridge behind the men on it,
  //        light the causeway for the second wave, ring the bell, give out the arrows, move.
  //   +12  the second wave goes where the first one opened a road, against what is left standing.
  //   +14  fire and the push inward; +18 the picked men come for the company, wherever it is; +54 the morning.
  Relation overrun(place). Relation counted(place).
  Relation stands1(place). Relation overrun1(place). Relation stands2(place). Relation overrun2(place).
  Relation w1done(place). Relation w2done(place). Relation here(place). Relation sacrificed(place). Relation abandoned(place).
  Relation casualtyDone(group). Relation cas1(group). Relation p1done(group). Relation p3done(group). Relation p4done(group). Relation dawned(group).
  Relation greenBurns(group). Relation greenSaved(group). Relation helplessLost(group). Relation grainTaken(group). Relation bellSilenced(group).
  Relation pact(group). Relation grainGiven(group). Relation wyreWithdraws(group). Relation picksBeaten(group). Relation picksWithdrawn(group).
  Relation felled(group). Relation morning(group). Relation bellMod(group). Relation w2planned(group). Relation lured(group). Relation bridgeBurned(group). Relation picksArgued(group).
  Measure overrunCount(group). Measure thrust2(place).

  Query battleOn() means watch(clock) >= assaultAt(wyre) and not pact(party) and not wyreWithdraws(party).

  Rule wyre_sees_spoiled when planned(party) and grainSpoiled(party) and wyreKnowsSpoiled(party) and (fothergillTurned(party) or vollLooked(party)) and barricadeUp(party) and (evacuated(party) or bucketLine(party)) and watch(clock) >= assaultAt(wyre) and not wyreWithdraws(party) {
    Assert wyreWithdraws(party). }

  Rule move_to_posts when posted(?v, ?p) and watch(clock) >= assaultAt(wyre) - 12 and able(?v) and not at(?v, ?p) and not travelsWith(?v, party) { Assert at(?v, ?p). }

  // Where the company stands is read at the clash: the post it is at (the nave includes the loft and the roof).
  Rule here_on when postsite(?p) and at(party, ?p) and not here(?p) { Assert here(?p). }
  Rule here_nave_on when (at(party, bell_loft) or at(party, tower_roof)) and not here(nave) { Assert here(nave). }
  Rule here_off when here(?p) and postsite(?p) and distinct(?p, nave) and not at(party, ?p) { Retract here(?p). }
  Rule here_nave_off when here(nave) and not at(party, nave) and not at(party, bell_loft) and not at(party, tower_roof) { Retract here(nave). }

  Rule p1_wear when battleOn() and not p1done(party) {
    Assert p1done(party).
    Decrease defence(ford_stones) by thrust(ford_stones) / 4 or to nothing. Decrease defence(bridge) by thrust(bridge) / 4 or to nothing.
    Decrease defence(mill_yard) by thrust(mill_yard) / 4 or to nothing. Decrease defence(nave) by thrust(nave) / 4 or to nothing. }

  // ── The first wave ──────────────────────────────────────────────────────────────────────────────────────────
  Rule w1_hold_with when battleOn() and p1done(party) and watch(clock) >= assaultAt(wyre) + 6 and postsite(?p) and not w1done(?p) and here(?p) and defence(?p) + 2 * count(posted(?v, ?p) and able(?v)) + drillBonus(party) + 13 >= thrust(?p) + dice(?p) / 20 {
    Assert w1done(?p). Assert stands1(?p). }
  Rule w1_lost_with when battleOn() and p1done(party) and watch(clock) >= assaultAt(wyre) + 6 and postsite(?p) and not w1done(?p) and here(?p) and defence(?p) + 2 * count(posted(?v, ?p) and able(?v)) + drillBonus(party) + 13 < thrust(?p) + dice(?p) / 20 {
    Assert w1done(?p). Assert overrun1(?p). Assert overrun(?p). }
  Rule w1_hold when battleOn() and p1done(party) and watch(clock) >= assaultAt(wyre) + 6 and postsite(?p) and not w1done(?p) and not here(?p) and defence(?p) + 2 * count(posted(?v, ?p) and able(?v)) + drillBonus(party) + 4 >= thrust(?p) + dice(?p) / 20 {
    Assert w1done(?p). Assert stands1(?p). }
  Rule w1_lost when battleOn() and p1done(party) and watch(clock) >= assaultAt(wyre) + 6 and postsite(?p) and not w1done(?p) and not here(?p) and defence(?p) + 2 * count(posted(?v, ?p) and able(?v)) + drillBonus(party) + 4 < thrust(?p) + dice(?p) / 20 {
    Assert w1done(?p). Assert overrun1(?p). Assert overrun(?p). }

  // What the first wave leaves: a held post is worn by a third of what was thrown at it; a fallen one has nothing left.
  Rule w1_worn when stands1(?p) and not worn1(?p) { Decrease defence(?p) by thrust(?p) / 3 or to nothing. Assert worn1(?p). }
  Rule w1_gone when overrun1(?p) and not worn1(?p) { Set defence(?p) to 0. Assert worn1(?p). }
  Relation worn1(place).

  // Where the second wave goes depends on where the first one got through, or was stopped.
  Rule w2_base when w1done(ford_stones) and w1done(bridge) and w1done(mill_yard) and w1done(nave) and not w2planned(party) {
    Set thrust2(ford_stones) to thrust(ford_stones) / 2. Set thrust2(bridge) to thrust(bridge) / 2.
    Set thrust2(mill_yard) to thrust(mill_yard) / 2. Set thrust2(nave) to thrust(nave) / 2. }
  Rule w2_held_ford when stands1(ford_stones) and w1done(nave) and not w2planned(party) { Increase thrust2(mill_yard) by 4. }
  Rule w2_fell_ford when overrun1(ford_stones) and w1done(nave) and not w2planned(party) { Increase thrust2(mill_yard) by 2. Increase thrust2(nave) by 2. }
  Rule w2_held_bridge when stands1(bridge) and w1done(nave) and not w2planned(party) { Increase thrust2(ford_stones) by 3. }
  Rule w2_fell_bridge when overrun1(bridge) and w1done(nave) and not w2planned(party) { Increase thrust2(nave) by 5. }
  Rule w2_fell_mill when overrun1(mill_yard) and w1done(nave) and not w2planned(party) { Increase thrust2(nave) by 3. }
  Rule w2_flooded when sluiceOpen(party) and w1done(nave) and not w2planned(party) { Increase thrust2(mill_yard) by 3. Increase thrust2(nave) by 3. }
  Rule w2_latch when w1done(ford_stones) and w1done(bridge) and w1done(mill_yard) and w1done(nave) and not w2planned(party) { Assert w2planned(party). }

  // ── The company's hour ──────────────────────────────────────────────────────────────────────────────────────
  Action hold_to_the_last(actor: group, p: place) "Hold {p} to the last: the people posted there will not come back" {
    Requires able(actor) and company(actor) and postsite(p) and count(posted(?v, p)) >= 1 and stands1(p) and w2planned(party) and not w2done(p) and not sacrificed(p) and not abandoned(p) and watch(clock) < assaultAt(wyre) + 12.
    Time 0.
    On success { Assert sacrificed(p). Increase defence(p) by 7. }
    Result "You pass the word. Nobody says anything. A woman at {p} takes down her apron and puts it over the dog.".
  }
  Action fall_back_from(actor: group, p: place) "Give up {p} without a second fight, and bring its people in" {
    Requires able(actor) and company(actor) and postsite(p) and count(posted(?v, p)) >= 1 and stands1(p) and w2planned(party) and not w2done(p) and not sacrificed(p) and not abandoned(p) and watch(clock) < assaultAt(wyre) + 12.
    Time 0.
    On success { Assert abandoned(p). }
    Result "The word goes along the line to {p}, and the line comes back with its dead and its wounded and its tools, and without its pride. Behind them the post is a place where the enemy will be.".
  }
  Action burn_the_bridge_behind(actor: group, site: place) "Fire the bridge behind the men on it, with the pitch" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bridge) and holding(actor, lamp_oil) and overrun1(bridge) and not bridgeCut(party) and not bridgeBurned(party) and w2planned(party) and watch(clock) < assaultAt(wyre) + 12.
    Time 0.
    On success { Spend lamp_oil from actor. Assert bridgeBurned(party). Decrease thrust2(nave) by 5 or to nothing. }
    Result "The pitch goes on the planking and the lamp after it. The men on the near arch see it go up, and the men on the far side see it too, and nobody comes over the packhorse bridge for the rest of the night. Some of the men on it are not going to come back from it either.".
  }
  Action light_the_causeway(actor: group, site: place) "Light the lantern on the reed causeway, and walk it into the marsh" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, reed_marsh) and w2planned(party) and not lured(party) and watch(clock) < assaultAt(wyre) + 12.
    Time 0.
    On success { Assert lured(party). Decrease thrust2(ford_stones) by 5 or to nothing. Decrease thrust2(mill_yard) by 4 or to nothing. }
    Result "A lantern on a pole, going away along a track that is not a track. A horseman at the edge of the meadow sees it and shouts. Then a dozen of them are following it, and the first of the horses goes in to the girth.".
  }

  // ── The second wave ─────────────────────────────────────────────────────────────────────────────────────────
  // Only a post that stood the first wave is fought for again; one that fell is simply passed. A post given up is the
  // enemy's. The company's weight counts for eleven if it is there, three if not.
  Rule abandon_effect when abandoned(?p) and not w2done(?p) { Assert w2done(?p). Assert overrun2(?p). Assert overrun(?p). }
  Rule w2_hold_with when battleOn() and w2planned(party) and watch(clock) >= assaultAt(wyre) + 12 and postsite(?p) and stands1(?p) and not w2done(?p) and here(?p) and defence(?p) + 2 * count(posted(?v, ?p) and able(?v)) + drillBonus(party) + 11 >= thrust2(?p) + dice(?p) / 20 {
    Assert w2done(?p). Assert stands2(?p). }
  Rule w2_lost_with when battleOn() and w2planned(party) and watch(clock) >= assaultAt(wyre) + 12 and postsite(?p) and stands1(?p) and not w2done(?p) and here(?p) and defence(?p) + 2 * count(posted(?v, ?p) and able(?v)) + drillBonus(party) + 11 < thrust2(?p) + dice(?p) / 20 {
    Assert w2done(?p). Assert overrun2(?p). Assert overrun(?p). }
  Rule w2_hold when battleOn() and w2planned(party) and watch(clock) >= assaultAt(wyre) + 12 and postsite(?p) and stands1(?p) and not w2done(?p) and not here(?p) and defence(?p) + 2 * count(posted(?v, ?p) and able(?v)) + drillBonus(party) + 3 >= thrust2(?p) + dice(?p) / 20 {
    Assert w2done(?p). Assert stands2(?p). }
  Rule w2_lost when battleOn() and w2planned(party) and watch(clock) >= assaultAt(wyre) + 12 and postsite(?p) and stands1(?p) and not w2done(?p) and not here(?p) and defence(?p) + 2 * count(posted(?v, ?p) and able(?v)) + drillBonus(party) + 3 < thrust2(?p) + dice(?p) / 20 {
    Assert w2done(?p). Assert overrun2(?p). Assert overrun(?p). }
  // A post that fell in the first wave is not fought for again: the second wave passes it.
  Rule w2_passes when overrun1(?p) and w2planned(party) and watch(clock) >= assaultAt(wyre) + 12 and not w2done(?p) { Assert w2done(?p). }

  Rule count_overrun when overrun(?p) and not counted(?p) { Increase overrunCount(party) by 1. Assert counted(?p). }

  // The dead, by name. The first wave takes some of a post that held and many of a post that fell; the second takes
  // more; a post held to the last takes all of its people.
  Rule cas1_lost when overrun1(?p) and posted(?v, ?p) and able(?v) and not cas1(?v) and dice(?v) <= 40 { Slay ?v. Assert felled(?v). Assert cas1(?v). }
  Rule cas1_lost_spared when overrun1(?p) and posted(?v, ?p) and able(?v) and not cas1(?v) and dice(?v) > 40 { Assert cas1(?v). }
  Rule cas1_held when stands1(?p) and posted(?v, ?p) and able(?v) and not cas1(?v) and dice(?v) <= 8 { Slay ?v. Assert felled(?v). Assert cas1(?v). }
  Rule cas1_held_spared when stands1(?p) and posted(?v, ?p) and able(?v) and not cas1(?v) and dice(?v) > 8 { Assert cas1(?v). }
  Rule cas2_sacrificed when sacrificed(?p) and w2done(?p) and posted(?v, ?p) and able(?v) and not casualtyDone(?v) { Slay ?v. Assert felled(?v). Assert casualtyDone(?v). }
  Rule cas2_lost when overrun2(?p) and not abandoned(?p) and posted(?v, ?p) and able(?v) and not casualtyDone(?v) and dice(?v) <= 55 { Slay ?v. Assert felled(?v). Assert casualtyDone(?v). }
  Rule cas2_held when stands2(?p) and posted(?v, ?p) and able(?v) and not casualtyDone(?v) and dice(?v) <= 12 { Slay ?v. Assert felled(?v). Assert casualtyDone(?v). }
  Rule cas2_company_sacrificed when sacrificed(?p) and w2done(?p) and at(party, ?p) and travelsWith(?v, party) and able(?v) and not casualtyDone(?v) { Slay ?v. Assert felled(?v). Assert casualtyDone(?v). }
  Rule cas2_done when w2done(?p) and posted(?v, ?p) and not casualtyDone(?v) { Assert casualtyDone(?v). }
  // The company's own: those who fight beside the fall of a post may not come out of it.
  Rule cas_company_lost when overrun(?p) and at(party, ?p) and travelsWith(?v, party) and able(?v) and not casualtyDone(?v) and dice(?v) <= 35 { Slay ?v. Assert felled(?v). Assert casualtyDone(?v). }
  Rule cas_company_lost_spared when overrun(?p) and at(party, ?p) and travelsWith(?v, party) and able(?v) and not casualtyDone(?v) and dice(?v) > 35 { Assert casualtyDone(?v). }

  // ── Fire, and the push inward ───────────────────────────────────────────────────────────────────────────────
  Rule p3_fire when battleOn() and watch(clock) >= assaultAt(wyre) + 14 and not p3done(party) and (overrun(ford_stones) or overrun(bridge) or overrun(mill_yard)) and not bucketLine(party) {
    Assert p3done(party). Assert greenBurns(party). }
  Rule p3_fire_saved when battleOn() and watch(clock) >= assaultAt(wyre) + 14 and not p3done(party) and (overrun(ford_stones) or overrun(bridge) or overrun(mill_yard)) and bucketLine(party) {
    Assert p3done(party). Assert greenSaved(party). }
  Rule p3_quiet when battleOn() and watch(clock) >= assaultAt(wyre) + 14 and not p3done(party) and not overrun(ford_stones) and not overrun(bridge) and not overrun(mill_yard) { Assert p3done(party). }
  // The helpless in a burning green are lost; the lost are counted in the bad dawn (see the fates).
  Rule p3_helpless when greenBurns(party) and not evacuated(party) and not helplessLost(party) { Assert helplessLost(party). }
  Rule p3_grain when battleOn() and p3done(party) and overrun(mill_yard) and not grainSpoiled(party) and not grainTaken(party) { Assert grainTaken(party). Assert winterShort(party). }
  Rule p3_bell when battleOn() and overrun1(nave) and not bellSilenced(party) { Assert bellSilenced(party). }
  // A company awake for eighteen hours is weary (data/rules/needs.kyr) and the work shows: the wall sags, the levy
  // sees tired strangers, the posts are one point down. Sleep puts it back, at the cost of the hours.
  Rule weary_hits when weary(party) and battleOn() and not wearyMod(party) {
    Assert wearyMod(party). Decrease defence(ford_stones) by 2 or to nothing. Decrease defence(bridge) by 2 or to nothing.
    Decrease defence(mill_yard) by 2 or to nothing. Decrease defence(nave) by 2 or to nothing. Decrease drillBonus(party) by 1 or to nothing. }
  Relation wearyMod(group).
  Rule winter_bites when winterShort(party) and not winterMod(party) { Assert winterMod(party). Decrease nerve(elland) by 1 or to nothing. Decrease nerve(quarmby) by 1 or to nothing. Decrease nerve(ashworth) by 1 or to nothing. Decrease nerve(wadsworth) by 1 or to nothing. }
  Relation winterMod(group).
  Rule bell_silent_costs when bellSilenced(party) and not bellMod(party) { Assert bellMod(party). Decrease drillBonus(party) by 1 or to nothing. }

  // ── The picked men come for the company, wherever it is ──────────────────────────────────────────────────────
  Rule picks_come when battleOn() and p3done(party) and watch(clock) >= assaultAt(wyre) + 18 and not p4done(party) and not fothergillTurned(party) and not picksWithdrawn(party) and at(party, ?r) {
    Assert p4done(party). Assert at(picks, ?r). }
  Rule picks_turned when battleOn() and p3done(party) and watch(clock) >= assaultAt(wyre) + 18 and not p4done(party) and fothergillTurned(party) { Assert p4done(party). Assert picksWithdrawn(party). }
  // If the company does nothing (it waits, or it is away), the picked men take what they came for and go.
  Rule picks_take when p4done(party) and not picksWithdrawn(party) and not dead(picks) and watch(clock) >= assaultAt(wyre) + 24 {
    Assert picksWithdrawn(party). Assert picksTook(party). Assert grainTaken(party). Assert winterShort(party). Assert at(picks, mill_yard). }
  Rule picks_beaten_rule when p4done(party) and dead(picks) and not picksBeaten(party) { Assert picksBeaten(party). }
  Rule wyre_with_the_picks when p4done(party) and overrunCount(party) >= 2 and not picksWithdrawn(party) and at(picks, ?r) and not at(wyre, ?r) { Assert at(wyre, ?r). }
  Rule dawn_comes when watch(clock) >= assaultAt(wyre) + 48 and not dawned(party) { Assert dawned(party). }
  Rule morning_comes when watch(clock) >= assaultAt(wyre) + 54 and not morning(party) { Assert morning(party). }

  Action yield_the_grain(actor: group, site: place) "Tell the picked men they may have the granary, and go" {
    Requires able(actor) and company(actor) and at(actor, site) and at(picks, site) and able(picks) and not grainGiven(party) and not grainSpoiled(party).
    Time 0.
    On success { Assert grainGiven(party). Assert picksWithdrawn(party). Assert winterShort(party). Retract at(picks, site). Retract at(wyre, site). }
    Result "The one with the helm under his arm looks at you. 'The captain will be pleased,' he says, 'and in a year he will want something else.' He puts the helm on. They go, in a line, towards the granary, and the night is quiet behind them.".
  }
  Action parley_the_picks(actor: group, site: place) "Argue with the picked men that there is nothing here worth their dying" {
    Requires able(actor) and company(actor) and at(actor, site) and at(picks, site) and able(picks) and not picksWithdrawn(party) and not parleyTried(party).
    Time 0.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert picksWithdrawn(party). Assert picksArgued(party). Retract at(picks, site). Retract at(wyre, site). }
    On failure { Assert parleyTried(party). }
    Result "You tell them what the village is: a ford, a mill, sixty people, no coin. You tell them what it will cost them, and you tell them exactly, because you have counted. The one with the helm laughs once, shortly, and says to the others, 'He's right about the coin.' They go with their granary unvisited and their purses as empty as they came.".
    Otherwise "They hear you out. The helm is already back on. 'Regrets,' says the first, and he does sound it.".
  }
  Action draw_on_the_picks(actor: group, site: place) "Draw on the picked men" {
    Requires able(actor) and company(actor) and at(actor, site) and at(picks, site) and able(picks) and not picksWithdrawn(party) and not companyBroken(party).
    Time 0.
    Resolve check(actor, brawn, dc_hard).
    On success { Slay picks. Assert picksBeaten(party). }
    On failure { Assert companyBroken(party). }
    Result "The first of them has his helm back on before your blade is out of the scabbard, and it is still not enough. You are quick, and so are the others, and it is a short bad minute in which nobody speaks, and then there are three men standing in the chapel who are not hurt.".
    Otherwise "It is a good fight and it is not a long one. Three men in good steel are hard to kill and the company does it anyway, by a margin it will not forget, with the benches over and the bell-rope cut.".
  }
  Relation companyBroken(group).
  Rule yield_dear when grainGiven(party) and parleyTried(party) and not bellSilenced(party) { Assert bellSilenced(party). }
  Relation parleyTried(group). Relation picksTook(group).

  // ── What the night looks like from wherever you are standing ─────────────────────────────────────────────────
  // Reports are told of what is posted where, and not all of them are true: a horn can be a feint, and the nave
  // is a long way from the ford. First-wave reports live for the hour of the company's choices.
  Observe night_ford_holds near party when stands1(ford_stones) and barricadeUp(party) and watch(clock) < assaultAt(wyre) + 18 "From the ford, a long way off, the noise of the first rush stops, and starts, and stops. The coach has held.".
  Observe night_ford_holds_bare near party when stands1(ford_stones) and not barricadeUp(party) and watch(clock) < assaultAt(wyre) + 18 "From the ford, a long way off, the noise of the first rush stops, and starts, and stops. Nobody comes up the meadow.".
  Observe night_ford_falls near party when overrun1(ford_stones) and watch(clock) < assaultAt(wyre) + 18 "The ford has gone. You know by the sound: the noise of the wall coming apart, and then the noise of men who no longer have to climb.".
  Observe night_bridge_holds near party when stands1(bridge) and posted(wadsworth, bridge) and watch(clock) < assaultAt(wyre) + 18 "Nothing comes over the packhorse bridge. A single voice shouts 'Again!' and it is Hob Wadsworth's.".
  Observe night_bridge_holds_plain near party when stands1(bridge) and not posted(wadsworth, bridge) and watch(clock) < assaultAt(wyre) + 18 "Nothing comes over the packhorse bridge.".
  Observe night_bridge_horn near party when stands1(bridge) and watch(clock) >= assaultAt(wyre) + 6 and watch(clock) < assaultAt(wyre) + 12 "A horn, from the bridge: three blasts, and a voice that is not one of ours shouting that the bridge is lost. It is going round the village faster than it can be answered.".
  Observe night_bridge_falls near party when overrun1(bridge) and watch(clock) < assaultAt(wyre) + 18 "The bridge has gone, and its people with it, and the road into the village is a lit road now.".
  Observe night_mill_holds near party when stands1(mill_yard) and posted(quarmby, mill_yard) and watch(clock) < assaultAt(wyre) + 18 "The mill wheel is still turning. Somebody has put out a lantern in the yard and the dark is full of thrown meal.".
  Observe night_mill_holds_plain near party when stands1(mill_yard) and not posted(quarmby, mill_yard) and watch(clock) < assaultAt(wyre) + 18 "The mill wheel is still turning.".
  Observe night_mill_falls near party when overrun1(mill_yard) and watch(clock) < assaultAt(wyre) + 18 "The mill has stopped. You did not know how loud it was until it stopped.".
  // The nave is the farthest from everything: its report comes late, in the second wave.
  Observe night_nave_holds near party when stands2(nave) and watch(clock) < assaultAt(wyre) + 24 "The chapel door is shut, and has been hit, and is shut.".
  Observe night_nave_falls near party when overrun(nave) and watch(clock) >= assaultAt(wyre) + 12 and watch(clock) < assaultAt(wyre) + 24 "Someone is in the chapel. The bell, which was ringing, has stopped in the middle of a stroke.".
  Observe night_second_ford near party when stands2(ford_stones) and watch(clock) >= assaultAt(wyre) + 12 and watch(clock) < assaultAt(wyre) + 24 "The ford again, and again it holds. They are not coming that way a third time.".
  Observe night_second_mill near party when overrun2(mill_yard) and watch(clock) >= assaultAt(wyre) + 12 and watch(clock) < assaultAt(wyre) + 24 "The second wave has come through the mill yard. The wheel has stopped and the meal is on fire.".
  Observe night_second_lured near party when lured(party) and watch(clock) >= assaultAt(wyre) + 12 and watch(clock) < assaultAt(wyre) + 24 "Somewhere out on the marsh a great many men are shouting at once, and a horse is screaming, and the sound goes on a long time.".
  Observe night_bridge_burned near party when bridgeBurned(party) and watch(clock) >= assaultAt(wyre) + 6 and watch(clock) < assaultAt(wyre) + 24 "Over the roofs, orange, low: the bridge, burning from end to end.".
  Observe night_bell_rung near party when bellRung(party) and watch(clock) >= assaultAt(wyre) + 6 and watch(clock) < assaultAt(wyre) + 18 "Every shutter on the green is open, and nobody is closing them.".
  Observe night_fire near party when greenBurns(party) and watch(clock) < assaultAt(wyre) + 30 "Over the roofs, red. The green is burning; the thatch goes first, in a long sigh, and then the rest.".
  Observe night_fire_out near party when greenSaved(party) and watch(clock) < assaultAt(wyre) + 30 "A torch has gone into the thatch by the inn, and a dozen buckets have been waiting for it. The steam goes up like a flag.".

  // Wyre's intelligence, as it shows from the high places: where the weight of the column is, and so what he has guessed.
  Observe night_wyre_first near party when w2planned(party) and watch(clock) < assaultAt(wyre) + 12 "Behind the first rush a horn is blowing the long note Captain Wyre uses to call men off. It is answered from three places at once.".
  Observe night_wyre_second near party when w2done(ford_stones) and w2done(bridge) and w2done(mill_yard) and w2done(nave) and watch(clock) < assaultAt(wyre) + 24 "Wyre's grey has been seen at the edge of the meadow, not moving. He is not hurrying. He is counting.".

  // Wyre's intelligence, as it shows from the high places: where the weight of the column is, and so what he has guessed.
  Observe wyre_plan_tower_roof_ford at tower_roof when planned(party) and thrust(ford_stones) >= thrust(bridge) and thrust(ford_stones) >= thrust(mill_yard) and thrust(ford_stones) >= thrust(nave) and not dawned(party) and (watch(clock) < assaultAt(wyre) - 54 or watch(clock) >= assaultAt(wyre) - 36) "The column has halted opposite the ford and Captain Wyre's grey is at the head of it. Men are cutting fascines.".
  Observe wyre_plan_lookout_ford at lookout when planned(party) and thrust(ford_stones) >= thrust(bridge) and thrust(ford_stones) >= thrust(mill_yard) and thrust(ford_stones) >= thrust(nave) and not dawned(party) and (watch(clock) < assaultAt(wyre) - 54 or watch(clock) >= assaultAt(wyre) - 36) "The column has halted opposite the ford and Captain Wyre's grey is at the head of it. Men are cutting fascines.".
  Observe wyre_plan_east_road_ford at east_road when planned(party) and thrust(ford_stones) >= thrust(bridge) and thrust(ford_stones) >= thrust(mill_yard) and thrust(ford_stones) >= thrust(nave) and not dawned(party) and (watch(clock) < assaultAt(wyre) - 54 or watch(clock) >= assaultAt(wyre) - 36) "The column has halted opposite the ford and Captain Wyre's grey is at the head of it. Men are cutting fascines.".
  Observe wyre_right_ford near party when dawned(party) and planned(party) and thrust(ford_stones) >= thrust(bridge) and thrust(ford_stones) >= thrust(mill_yard) and thrust(ford_stones) >= thrust(nave) and overrun(ford_stones) "Wyre guessed the ford, and it went.".
  Observe wyre_wrong_ford near party when dawned(party) and planned(party) and thrust(ford_stones) >= thrust(bridge) and thrust(ford_stones) >= thrust(mill_yard) and thrust(ford_stones) >= thrust(nave) and not overrun(ford_stones) "Wyre put his weight on the ford and it stood.".
  Observe wyre_plan_tower_roof_bridge at tower_roof when planned(party) and thrust(bridge) > thrust(ford_stones) and thrust(bridge) >= thrust(mill_yard) and thrust(bridge) >= thrust(nave) and not dawned(party) and (watch(clock) < assaultAt(wyre) - 54 or watch(clock) >= assaultAt(wyre) - 36) "The wagons are drawn up opposite the bridge, and Wyre's standard is planted beside them. Ladders are being roped.".
  Observe wyre_plan_lookout_bridge at lookout when planned(party) and thrust(bridge) > thrust(ford_stones) and thrust(bridge) >= thrust(mill_yard) and thrust(bridge) >= thrust(nave) and not dawned(party) and (watch(clock) < assaultAt(wyre) - 54 or watch(clock) >= assaultAt(wyre) - 36) "The wagons are drawn up opposite the bridge, and Wyre's standard is planted beside them. Ladders are being roped.".
  Observe wyre_plan_east_road_bridge at east_road when planned(party) and thrust(bridge) > thrust(ford_stones) and thrust(bridge) >= thrust(mill_yard) and thrust(bridge) >= thrust(nave) and not dawned(party) and (watch(clock) < assaultAt(wyre) - 54 or watch(clock) >= assaultAt(wyre) - 36) "The wagons are drawn up opposite the bridge, and Wyre's standard is planted beside them. Ladders are being roped.".
  Observe wyre_right_bridge near party when dawned(party) and planned(party) and thrust(bridge) > thrust(ford_stones) and thrust(bridge) >= thrust(mill_yard) and thrust(bridge) >= thrust(nave) and overrun(bridge) "Wyre guessed the bridge, and it went.".
  Observe wyre_wrong_bridge near party when dawned(party) and planned(party) and thrust(bridge) > thrust(ford_stones) and thrust(bridge) >= thrust(mill_yard) and thrust(bridge) >= thrust(nave) and not overrun(bridge) "Wyre put his weight on the bridge and it stood.".
  Observe wyre_plan_tower_roof_mill at tower_roof when planned(party) and thrust(mill_yard) > thrust(ford_stones) and thrust(mill_yard) > thrust(bridge) and thrust(mill_yard) >= thrust(nave) and not dawned(party) and (watch(clock) < assaultAt(wyre) - 54 or watch(clock) >= assaultAt(wyre) - 36) "The led horses are going round by the marsh edge toward the mill, and Wyre has gone with them. The wagons are not unharnessed.".
  Observe wyre_plan_lookout_mill at lookout when planned(party) and thrust(mill_yard) > thrust(ford_stones) and thrust(mill_yard) > thrust(bridge) and thrust(mill_yard) >= thrust(nave) and not dawned(party) and (watch(clock) < assaultAt(wyre) - 54 or watch(clock) >= assaultAt(wyre) - 36) "The led horses are going round by the marsh edge toward the mill, and Wyre has gone with them. The wagons are not unharnessed.".
  Observe wyre_plan_east_road_mill at east_road when planned(party) and thrust(mill_yard) > thrust(ford_stones) and thrust(mill_yard) > thrust(bridge) and thrust(mill_yard) >= thrust(nave) and not dawned(party) and (watch(clock) < assaultAt(wyre) - 54 or watch(clock) >= assaultAt(wyre) - 36) "The led horses are going round by the marsh edge toward the mill, and Wyre has gone with them. The wagons are not unharnessed.".
  Observe wyre_right_mill near party when dawned(party) and planned(party) and thrust(mill_yard) > thrust(ford_stones) and thrust(mill_yard) > thrust(bridge) and thrust(mill_yard) >= thrust(nave) and overrun(mill_yard) "Wyre guessed the mill, and it went.".
  Observe wyre_wrong_mill near party when dawned(party) and planned(party) and thrust(mill_yard) > thrust(ford_stones) and thrust(mill_yard) > thrust(bridge) and thrust(mill_yard) >= thrust(nave) and not overrun(mill_yard) "Wyre put his weight on the mill and it stood.".
  Observe wyre_plan_tower_roof_nave at tower_roof when planned(party) and thrust(nave) > thrust(ford_stones) and thrust(nave) > thrust(bridge) and thrust(nave) > thrust(mill_yard) and not dawned(party) and (watch(clock) < assaultAt(wyre) - 54 or watch(clock) >= assaultAt(wyre) - 36) "Archers are being sent up the Scar path, and Wyre is looking at the chapel tower with a glass.".
  Observe wyre_plan_lookout_nave at lookout when planned(party) and thrust(nave) > thrust(ford_stones) and thrust(nave) > thrust(bridge) and thrust(nave) > thrust(mill_yard) and not dawned(party) and (watch(clock) < assaultAt(wyre) - 54 or watch(clock) >= assaultAt(wyre) - 36) "Archers are being sent up the Scar path, and Wyre is looking at the chapel tower with a glass.".
  Observe wyre_plan_east_road_nave at east_road when planned(party) and thrust(nave) > thrust(ford_stones) and thrust(nave) > thrust(bridge) and thrust(nave) > thrust(mill_yard) and not dawned(party) and (watch(clock) < assaultAt(wyre) - 54 or watch(clock) >= assaultAt(wyre) - 36) "Archers are being sent up the Scar path, and Wyre is looking at the chapel tower with a glass.".
  Observe wyre_right_nave near party when dawned(party) and planned(party) and thrust(nave) > thrust(ford_stones) and thrust(nave) > thrust(bridge) and thrust(nave) > thrust(mill_yard) and overrun(nave) "Wyre guessed the chapel, and it went.".
  Observe wyre_wrong_nave near party when dawned(party) and planned(party) and thrust(nave) > thrust(ford_stones) and thrust(nave) > thrust(bridge) and thrust(nave) > thrust(mill_yard) and not overrun(nave) "Wyre put his weight on the chapel and it stood.".

  Action draw_on_the_raiders(actor: group, site: place) "Draw on the four with the sacks" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lower_farm) and at(raiders, site) and able(raiders) and not companyBroken(party) and not raidersBeaten(party) and not farmBurned(party).
    Time 0.
    Resolve check(actor, brawn, dc_hard).
    On success { Slay raiders. Assert raidersBeaten(party). Assert greenhalghSaved(party). }
    On failure { Assert companyBroken(party). }
    Result "They have sacks in their hands and the sacks go down, and for a minute it is a muddy business at a gate in the dusk. Then there are four men on the ground, and a farmer in the door with a dog, who has not moved.".
    Otherwise "They put the sacks down very carefully. Then they are not four men with sacks any more. Nobody at Sallowfield hears about it for two days.".
  }
  Relation raidersBeaten(group).
}

data/adventures/sallowfield/clock.kyr:
Module sallowfield "Three Nights at Sallowfield" {
  // ── The clock ─────────────────────────────────────────────────────────────────────────────────────────────────
  // Watch 0 is eight in the morning of the first day. The engine's dusk, by which the nights are counted, falls at watch 78 on the first day, 222 on the second and 366 on the third (21:00); the boy and the raiders come up in the evening before it, at 200 to 214.
  // Wyre means to come on the third night (assaultAt 366). If his riders find the town unwatched on the first night he
  // does not wait: he comes on the second (222). Everything he does turns on what he has seen, so what he has seen is
  // kept in plain facts: sawFord, sawBarricade, sawCut, sawTower, sawWatch.
  Measure assaultAt(group). Measure thrust(place). Measure defence(place).
  Initially Set assaultAt(wyre) to 366.
  Relation sawWatch(group). Relation sawBarricade(group). Relation sawCut(group). Relation sawTower(group).
  Relation riders_gone(group). Relation wyreEarly(group). Relation planned(group). Relation lowesCame(group).
  Relation knowsNumbers(group).

  Person wyre "Captain Tobin Wyre" nowhere {
    Role "the captain of the Unpaid, forty-odd of the Margrave's border-company and twenty camp-followers". Ancestry human. Calling warrior. Level 4. Peaceable. Pronouns he. Manner proud.
    Warns "The captain does not move. He lets you finish the thought, and finish the next, and then he says, in an even voice that has been used on horses, 'You are in the way of men who have not eaten.'".
    Comes "Wyre steps back and nods to the men behind him. He has been patient, and is not now.".
    Pleads "Wyre lowers his sword. His voice is dry. 'Stop,' he says. 'Stop it. There's nothing here worth this.'".
  }
  Person fothergill "Lieutenant Fothergill" nowhere {
    Role "Wyre's second, lately of the Margrave's horse". Ancestry human. Calling warrior. Level 3. Peaceable. Pronouns he. Manner proud.
  }
  Person voll "Sergeant Voll" nowhere {
    Role "Wyre's sergeant, a big man with a bad knee". Ancestry human. Calling warrior. Level 2. Peaceable. Pronouns he. Manner stoic.
  }
  Person riders "two of Wyre's riders" nowhere {
    Role "a pair of troopers on lathered horses, in the Margrave's old green". Ancestry human. Calling warrior. Level 2. Numbers 2. Peaceable. Manner stoic. Refuge east_road.
    Uses go.
    Arrives at lookout when watch(clock) >= 12.
    Arrives "Two horsemen come along the Scar road and rein in at the lookout, and sit their horses looking down the vale like a plate laid out. One of them has a slate.".
    Greets "The nearer trooper touches his hat and says the road is free to everyone, and keeps his eyes on the water. The other has a slate on his knee and does not look up.".
  }
  Person lowes "Kit Lowes" nowhere {
    Role "a boy of nineteen in a trooper's coat that is too big for him, with his boots in his hand". Ancestry human. Calling thief. Level 1. Peaceable. Pronouns he. Manner cheerful.
    Pleads "The boy puts his hands over his head and begins to talk before he has been asked anything.".
  }
  Person raiders "four of the Unpaid" nowhere {
    Role "four troopers with sacks, who have not been paid since the spring". Ancestry human. Calling warrior. Level 1. Numbers 4. Peaceable. Manner stoic.
    Arrives at lower_farm when watch(clock) >= 204.
    Arrives "Four men come up from the river in the failing light, with empty sacks.".
    Greets "The oldest of them looks at the cows, and then at you, and then at the sacks in his hand. 'We'll take the cows,' he says, 'and go. Better the cows than the other.' The others do not look up.".
  }
  Person picks "Wyre's picked men" nowhere {
    Role "three of the Unpaid in good steel, who have fought for money in six countries". Ancestry human. Calling warrior. Level 3. Numbers 3. Peaceable. Manner grim.
    Greets "The one in front takes off his helm and holds it under his arm. 'The captain would have the grain,' he says, 'and he'd have the bell. Which of them can you spare?' The other two have not taken their hands off their hilts.".
  }

  // ── Night one: the riders look ─────────────────────────────────────────────────────────────────────────────────
  // They cross as far as the middle stone, look at the town, write it down, and go. What they write depends on whether
  // anyone is about: a man posted at the ford or the bridge, a fire, a lantern. An empty ford means an easy town.
  // The riders ride the valley, Scar to ford, and are seen where they are: the lookout in the morning, the standing
  // stone at noon, the east road in the afternoon, the middle stone at dusk. They stay at the stone till they have looked.
  Pursuit riders_scar for riders "riding the Scar road" priority 5 when watch(clock) >= 12 and watch(clock) < 48 and not riders_gone(party) seeks at(riders, lookout).
  Pursuit riders_stone for riders "riding down to the standing stone" priority 5 when watch(clock) >= 48 and watch(clock) < 66 and not riders_gone(party) seeks at(riders, parley_stone).
  Pursuit riders_road for riders "riding the east road" priority 5 when watch(clock) >= 66 and watch(clock) < 80 and not riders_gone(party) seeks at(riders, east_road).
  Pursuit riders_ford for riders "riding down to the ford" priority 5 when watch(clock) >= 80 and not riders_gone(party) seeks at(riders, ford_stones).
  Observe crowther_four near crowther when riders_gone(party) "'Four,' says Crowther, and holds up four fingers, and puts one down. 'There were three, on the Scar road. There was a fourth this morning, with a slate.'".

  Query watchedFord() means (posted(?v, ford_stones) and at(?v, ford_stones) and able(?v)) or (posted(?v, bridge) and at(?v, bridge) and able(?v)) or at(party, ford_stones) or at(party, bridge) or at(party, ford_meadow).
  Rule riders_look at ford_stones when at(riders, ford_stones) and watch(clock) >= 92 and not riders_gone(party) and watchedFord()
    says "The troopers sit their horses at the middle stone for the length of a long breath. Someone on the bank has been seen. The man with the slate writes a line and wipes his thumb." {
    Assert riders_gone(party). Assert sawWatch(party). Retract at(riders, ford_stones). }
  Rule riders_look_empty at ford_stones when at(riders, ford_stones) and watch(clock) >= 92 and not riders_gone(party) and not watchedFord()
    says "The troopers ride up the ford meadow as far as the hurdle, and sit there, and nothing at all happens. A dog barks, once, a long way off. The man with the slate draws something on his knee, and they turn their horses, unhurried." {
    Assert riders_gone(party). Assert wyreEarly(party). Set assaultAt(wyre) to 222. Retract at(riders, ford_stones). }
  Rule riders_absent when at(riders, ford_stones) and not at(party, ford_stones) and watch(clock) >= 92 and not riders_gone(party) and not watchedFord() { Assert wyreEarly(party). }
  Observe riders_note near stansfield when wyreEarly(party) "The reeve has stopped writing. 'They looked,' he says. 'Nobody was there to be looked at.'".
  Observe riders_mark near stansfield when sawWatch(party) and not wyreEarly(party) "'Good,' says the reeve, and sits.".

  // ── Night two: a scout, a raid ────────────────────────────────────────────────────────────────────────────────
  // Kit Lowes comes through the reeds for a last look at the works. He can be caught in them (the reed track or the
  // farm) or let go. What he sees, Wyre knows.
  Rule lowes_comes when watch(clock) >= 200 and not lowesCame(party) {
    Assert lowesCame(party). Assert at(lowes, reed_marsh). }
  Rule lowes_sees when lowesCame(party) and at(lowes, reed_marsh) and watch(clock) >= 214 and not heldScout(lowes) {
    Retract at(lowes, reed_marsh). Assert lowesGone(party). Assert lowesTruth(party). }
  Relation lowesGone(group). Relation heldScout(group). Relation lowesTruth(group). Relation lowesStamp(group). Relation lowesTold(group). Relation lowesLie(group). Relation lieMod(group).
  // What the boy saw is what stood when he left (or when he was sent): the works are read once, at the stamp, and not after.
  Rule lowes_saw_barricade when lowesTruth(party) and not lowesTold(party) and barricadeUp(party) and not sawBarricade(party) { Assert sawBarricade(party). }
  Rule lowes_saw_cut when lowesTruth(party) and not lowesTold(party) and bridgeCut(party) and not sawCut(party) { Assert sawCut(party). }
  Rule lowes_saw_tower when lowesTruth(party) and not lowesTold(party) and posted(?v, nave) and able(?v) and not sawTower(party) { Assert sawTower(party). }
  Rule lowes_stamp when lowesTruth(party) and not lowesStamp(party) { Assert lowesStamp(party). }
  Rule lowes_told when lowesStamp(party) and not lowesTold(party) { Assert lowesTold(party). }
  // A lie told him to carry: that the ford is the soft place. Wyre believes it, and leans on the ford.
  Rule lowes_lie when planned(party) and lowesLie(party) and not lieMod(party) {
    Assert lieMod(party). Increase thrust(ford_stones) by 4. Decrease thrust(bridge) by 3 or to nothing. Decrease thrust(mill_yard) by 3 or to nothing. }
  Observe lowes_in_reeds at reed_marsh when lowesCame(party) and not lowesGone(party) and not heldScout(lowes) "A boy is picking his way along the reed causeway in the dark with his boots round his neck, counting under his breath. He has not seen you.".
  Observe reeds_lights_crowther near crowther when watch(clock) >= 150 and watch(clock) < 214 and not heldScout(lowes) "'Lights in the reeds,' says Crowther, 'last night. A small man, with a lantern shaded. He goes along the hurdles to where they stop and stands there. I don't know what he's counting.'".
  Observe reeds_lights_greenhalgh near greenhalgh when watch(clock) >= 150 and watch(clock) < 214 and not heldScout(lowes) "'There's a lad comes down the reed track at night,' says Greenhalgh. 'Dog won't have him. Small. Boots in his hand.'".
  Relation lowesAlert(group).
  Rule lowes_alert_effect when planned(party) and lowesAlert(party) and not alertMod(party) { Assert alertMod(party). Increase thrust(ford_stones) by 1. Increase thrust(mill_yard) by 1. }
  Relation alertMod(group).
  Action seize_scout(actor: group, site: place) "Take the boy in the reeds before he sees you" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, reed_marsh) and at(lowes, reed_marsh) and not heldScout(lowes).
    Time 0.
    Resolve check(actor, stealth, dc_fair).
    On success { Assert heldScout(lowes). Retract at(lowes, reed_marsh). Assert at(lowes, taproom). }
    Result "You come out of the reeds behind him with a hand over his mouth. He goes limp, which is the cleverest thing a scout can do, and when you let go he says in a whisper: 'Don't. Please. I'll say anything.'".
    On failure { Retract at(lowes, reed_marsh). Assert lowesGone(party). Assert lowesTruth(party). Assert lowesAlert(party). }
    Otherwise "The reeds rustle under your boot. The boy's head comes up. For a moment you look at each other across ten yards of black water, and then he is gone into the dark, and you hear him going.".
  }
  Rule raid_on_farm at lower_farm when at(raiders, lower_farm) and not farmRaided(party) and watch(clock) >= 210 and not at(party, lower_farm)
    says "Down by the river in the dusk, a cow bellows, and another, and a dog barks and stops. Then there is, for the best part of an hour, the sound of a barn being searched." {
    Assert farmRaided(party). }
  Relation farmRaided(group). Relation greenhalghSaved(group).
  Rule farm_burns when farmRaided(party) and not greenhalghSaved(party) { Assert farmBurned(party). }
  Relation farmBurned(group).
  Rule greenhalgh_hurt when farmBurned(party) and not evacuatedFarm(party) and not greenhalghDead(party) { Slay greenhalgh. Assert felled(greenhalgh). Assert greenhalghDead(party). }
  Relation greenhalghDead(group). Relation evacuatedFarm(group).
  Observe farm_gone at lower_farm when farmBurned(party) "The long house is a roofless black shape and the barn is gone to its walls. The yard is empty of cattle. The dog sits where it sat, with its chin on its paws.".

  // ── The morning of the third day: Wyre decides ────────────────────────────────────────────────────────────────
  // What he does depends only on what he has seen: a barricade at the ford draws him to the bridge; a cut bridge to
  // the ford; both to the marsh and the mill; the flood he does not see, nor the pits, nor the grain spoiled.
  Relation barricadeUp(group). Relation bridgeCut(group). Relation sluiceOpen(group). Relation pitsDug(group). Relation grainSpoiled(group).
  Rule plan_base when watch(clock) >= assaultAt(wyre) - 84 and not planned(party) {
    Assert planned(party).
    Set thrust(ford_stones) to 12. Set thrust(bridge) to 7. Set thrust(mill_yard) to 3. Set thrust(nave) to 3. }
  Rule plan_barricade when planned(party) and sawBarricade(party) and not sawCut(party) and not planMod1(party) {
    Assert planMod1(party). Set thrust(ford_stones) to 6. Set thrust(bridge) to 12. }
  Rule plan_cut when planned(party) and sawCut(party) and not sawBarricade(party) and not planMod1(party) {
    Assert planMod1(party). Set thrust(bridge) to 2. Set thrust(ford_stones) to 13. }
  Rule plan_both when planned(party) and sawCut(party) and sawBarricade(party) and not planMod1(party) {
    Assert planMod1(party). Set thrust(ford_stones) to 6. Set thrust(bridge) to 2. Set thrust(mill_yard) to 12. }
  Relation planMod1(group). Relation planMod2(group).
  Rule plan_tower when planned(party) and sawTower(party) and not planMod2(party) { Assert planMod2(party). Increase thrust(nave) by 5. }
  Rule plan_turned when planned(party) and fothergillTurned(party) and not planMod3(party) {
    Assert planMod3(party). Decrease thrust(ford_stones) by 4 or to nothing. Decrease thrust(bridge) by 4 or to nothing. Decrease thrust(mill_yard) by 4 or to nothing. }
  Relation planMod3(group). Relation fothergillTurned(group).
  // A ruined granary, and unpaid men, and a lieutenant on a rein: the whole line leans harder.
  Rule spoiled_anger when planned(party) and grainSpoiled(party) and not angerMod(party) {
    Assert angerMod(party). Increase thrust(ford_stones) by 3. Increase thrust(bridge) by 3. Increase thrust(mill_yard) by 3. Increase thrust(nave) by 3. }
  Relation angerMod(group).
  Rule plan_grain when planned(party) and grainSpoiled(party) and wyreKnowsSpoiled(party) and not planMod4(party) {
    Assert planMod4(party). Decrease thrust(ford_stones) by 6 or to nothing. Decrease thrust(bridge) by 6 or to nothing. Decrease thrust(mill_yard) by 6 or to nothing. Decrease thrust(nave) by 6 or to nothing. }
  Relation planMod4(group). Relation wyreKnowsSpoiled(group).
}

data/adventures/sallowfield/company.kyr:
Module sallowfield "Three Nights at Sallowfield" {
  Company party "Your company" of 3 at east_road.
  Initially Set quantity(party, gold) to 14. Initially Set quantity(party, rations) to 3.
}

data/adventures/sallowfield/folk.kyr:
Module sallowfield "Three Nights at Sallowfield" {
  // ── The people ───────────────────────────────────────────────────────────────────────────────────────────────
  // Twelve who can be asked to hold a place, each with a nerve (0 will not stand; 1 will if led; 2 will; 3 will and
  // steadies others). Dead is dead: the ending counts them by name.
  Relation villager(group). Measure nerve(group). Relation posted(group, place) exclusive. Relation postsite(place).
  Initially Assert postsite(ford_stones). Initially Assert postsite(bridge). Initially Assert postsite(mill_yard). Initially Assert postsite(nave).

  Person teasdale "Amos Teasdale" at east_road {
    Role "the coachman". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Greets "The axle is across two barrels, and Teasdale is talking to it, not to you. 'Cracked clean through,' he says. 'Three days, the smith says, if she's got the iron. Three days on the Company's time, and I have eleven passengers to feed and not one of you has ever once offered to push.'".
  }
  Person stansfield "Aldred Stansfield" at green {
    Role "the reeve of Sallowfield". Ancestry human. Peaceable. Pronouns he. Manner proud.
    Greets "A stout man in a good coat, with a ledger under his arm, who has plainly been told by someone that this is a time for leadership. 'You are the coach,' he says. 'Good. I have a notice to draw up and I do not know what to put on it. What would you put?'".
  }
  Person ashworth "Nan Ashworth" at taproom {
    Role "landlady of the Ploughshare". Ancestry human. Profession innkeeper. Peaceable. Pronouns she. Manner jovial.
    Greets "'Sit,' says Nan Ashworth, 'sit, sit, it's not a day to be on your feet. I've mutton, I've the end of a cheese, I've a cellar that has never in its life been lent to an army and I'd be obliged if it kept the record.'".
  }
  Person quarmby "Gil Quarmby" at mill_yard {
    Role "the miller". Ancestry human. Peaceable. Pronouns he. Manner grim.
    Greets "The miller has flour in his eyebrows and in the creases of his hands and, you suspect, in his temper. 'If you've come about the soldiers,' he says, 'it's four days since I heard and I've not had a minute. A mill doesn't stop for talk. It stops for fire.'".
  }
  Person kersey "Peg Kersey" at forge {
    Role "the smith". Ancestry dwarf. Peaceable. Pronouns she. Manner stoic.
    Greets "Peg Kersey takes in your boots, and then the door, which she keeps an eye on. 'Axle,' she says. 'Strap's in the coals. Iron's short.' She takes a hammer off the wall and puts it back. 'Don't ask what for. I'll be asked enough.'".
  }
  Person cragg "Ellen Cragg" at nave {
    Role "a widow, in the chapel with a bundle of arrows". Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Joins "Ellen Cragg gathers the arrows into a quiver with the heads all one way, and counts them into it. 'Forty-one,' she says. 'I'm to carry them, then.'".
    Leaves "Ellen Cragg lays the quiver on a pew. 'I'll be at the nave,' she says. 'If you want the number.'".
    Remarks at tower_roof "Ellen Cragg lays an arrow on the parapet, nock out, for the nearest hand. 'Fifty yards to the ford,' she says. 'Sixty to the bridge. Forty to the hedge. I have walked it.'".
    Greets "A woman of fifty on the front pew with an arrow in each hand, counting. 'Thirty-nine,' she says to nobody. 'Forty.' She lays the last on the pile and looks at you for the first time. 'Forty-one, if the boy hasn't been at them.'".
  }
  Person mowbray "Father Mowbray" at nave {
    Role "the priest of Saint Eadred's". Ancestry human. Calling cleric. Level 2. Peaceable. Pronouns he. Manner jovial.
    Joins "Mowbray puts on his hat, takes his staff, takes off his hat again to the altar, and puts it back on. 'Saint Eadred,' he says, 'look the other way.'".
    Leaves "Father Mowbray stops in the porch. 'I'll be at the altar,' he says. 'It is where I am any use.'".
    Remarks at green "Mowbray stops in the middle of the green and looks round at the geese, the well, the forge, the faces in the windows. 'God's teeth,' he says in a different voice. 'They are all here. I did not know that I would be afraid of that.'".
    Greets "A big red priest wrestling the plate-chest's lid with his whole bulk. 'God's teeth,' he says, 'and the Devil's tongue, and the pimply arse of Saint Eadred himself, which I'll say for him he'd have forgiven,' and then he sees you and puts on his dignity like a surplice and does not get it straight.".
  }
  Person pinn "Davy Pinn" at ford_stones {
    Role "the miller's boy, fishing". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Joins "Davy Pinn coils his line round the rod and puts the rod in a hedge. 'I'll fetch it after,' he says, and does not look back at the river.".
    Leaves "Davy Pinn goes off across the grass at a run, towards the mill, without being told to.".
    Remarks at tower_roof "Davy Pinn puts both hands on the parapet and looks down at the village until the light changes. 'It's small,' he says. 'I never knew it was small.'".
    Greets "A boy of twelve with a sling round his neck and a bent pin in the river, who has plainly decided you are the most interesting thing to have happened since the fair. 'I can hit a crow at forty yards,' he says. 'I can hit a man at thirty. Well. Haven't. But I could.'".
  }
  Person crowther "Old Crowther" at fold {
    Role "the shepherd". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "The shepherd turns round when he is ready. 'Sheep,' he says. And after a while: 'There's riders on the Scar road most mornings now. Three. Never four. They look at the village and then go.'".
  }
  Person greenhalgh "Ned Greenhalgh" at lower_farm {
    Role "the farmer at the lower farm". Ancestry human. Peaceable. Pronouns he. Manner grim.
    Greets "A man with a forearm like a ham leans on a gate that has been his father's. 'They'll not take my cows,' he says. 'I've been told they will. I have been told a great many things this week by people who did not stop to see the cows.'".
  }
  Person wadsworth "Hob Wadsworth" at taproom {
    Role "a carter, loudly". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Remarks at bridge "'What it wants,' says Hob Wadsworth, to the whole bridge, 'is a man with a voice. Lucky for you.' His voice has gone up a tone since the sun went down.".
    Greets "A big pink man at the bar with a pot in each hand, telling the room how he would deal with soldiers. He has dealt with soldiers in nine different ways since you came in and each way has been worse than the last. 'You're a fighter,' he says to you, with enormous warmth. 'I can tell. Let me buy you something.'".
  }
  Person elland "Tib Elland" at granary {
    Role "the tithe clerk". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "A thin young man with ink on his chin and a tally-stick in each hand, counting sacks aloud. 'Ninety, ninety, ninety,' he says, and drops a stick. 'Sorry. I. It is not that I am afraid. It is that I have the figures.'".
  }
  Initially Assert villager(stansfield). Initially Assert villager(ashworth). Initially Assert villager(quarmby). Initially Assert villager(kersey).
  Initially Assert villager(cragg). Initially Assert villager(mowbray). Initially Assert villager(pinn). Initially Assert villager(crowther).
  Initially Assert villager(greenhalgh). Initially Assert villager(wadsworth). Initially Assert villager(elland).
  Initially Set nerve(stansfield) to 0. Initially Set nerve(ashworth) to 2. Initially Set nerve(quarmby) to 2. Initially Set nerve(kersey) to 3.
  Initially Set nerve(cragg) to 3. Initially Set nerve(mowbray) to 2. Initially Set nerve(pinn) to 1. Initially Set nerve(crowther) to 2.
  Initially Set nerve(greenhalgh) to 2. Initially Set nerve(wadsworth) to 1. Initially Set nerve(elland) to 0.

  // Asking someone to hold a place. A villager with no nerve will not; a steadied one will.
  Action post_villager(actor: group, site: place, v: group, p: place) "Ask {v} to hold {p}" {
    Requires able(actor) and company(actor) and at(actor, site) and villager(v) and able(v) and at(v, site) and postsite(p) and not posted(v, p) and nerve(v) >= 1 and not travelsWith(v, actor).
    Time 6.
    On success { Assert posted(v, p). Assert at(v, p). }
    Result "{v} nods, once, and the matter is settled. They will be there.".
  }
  Action steady_villager(actor: group, site: place, v: group) "Steady {v} with a word" {
    Requires able(actor) and company(actor) and at(actor, site) and villager(v) and able(v) and at(v, site) and nerve(v) < 2 and not steadied(v) and not travelsWith(v, actor).
    Time 1.
    Resolve check(actor, persuasion, dc_fair).
    On success { Increase nerve(v) by 1. Assert steadied(v). }
    On failure { Assert steadied(v). }
    Result "{v} listens, and breathes out, and something in the shoulders comes down. 'All right,' {v} says. 'All right. Tell me where.'".
    Otherwise "{v} hears you out and nods and does not believe a word. Whatever was in the eyes before is still there.".
  }
  Relation steadied(group).

  // The reeve wants a notice, and the coachman wants his coach.
  Topic stansfield_notice with stansfield "Say what you would put on the notice" when true once {
    Says "Aldred Stansfield writes down every word you say, and after the first sentence he stops writing and simply looks at you. 'It is a great deal,' he says. 'I had thought of THE VILLAGE WILL REMAIN CALM.' He lays down the pen. 'I do not know that it will.'".
  }
  Topic stansfield_pay with stansfield "Ask the reeve what the village could pay" when true {
    Says "'Sixty,' says Stansfield, 'in coin, at the outside, if every house is turned out. And the plate, which is the priest's, and the grain, which is the Margrave's. I have no right to offer either.' He is pale. 'I am not saying I would not.'".
    On discuss { Assert knows(actor, reeve_would_pay). }
  }
  Entity reeve_would_pay: fact "Reeve Stansfield would pay sixty coin, the plate and the grain to be rid of Wyre's company, if he dared.".
  Topic teasdale_leave with teasdale "Ask the coachman when the coach could go on" when true {
    Says "'When the iron comes,' says Teasdale. 'Peg's got a strap in the coals she says will do. Three days. Two, if she doesn't take it for something else.' He looks up at the hills for the first time. 'Why?'".
  }
}

data/adventures/sallowfield/lore.kyr:
Module sallowfield "Three Nights at Sallowfield" {
  // ── The eleven who came on the coach ───────────────────────────────────────────────────────────────────────────
  // Teasdale feeds eleven passengers and nobody ever sees one. They are the village's guests and its first extra mouths,
  // and what becomes of the coach (it is a barricade, if the company chooses) is also what becomes of them.
  Observe coach_folk at east_road when not coachGone(party) and not battleOn() "Eleven people sit on the bank in the order they got down, which is the order of their tickets. A man in a good coat is explaining to a woman with a hatbox that there are forms for this. The woman with the hatbox is looking at the hills. A child is feeding a hen from the ostler's pocket. Nobody has asked them to leave, and nobody has asked them to stay.".
  Observe coach_in_chapel at nave when battleOn() and not greenBurns(party) "The coach's passengers have been put among the pews with the old and the very young. The man in the good coat has found something to do with the hymn-boards and is doing it with enormous care. The woman with the hatbox holds it on her knees like a sleeping child, and does not say what is in it.".
  Observe coach_gone_on at east_road when coachGone(party) "The coach lies on its side across the ford road with its wheels toward the east. Someone has chalked on the boot: TICKETS HONOURED. The passengers are in the chapel, and Teasdale is sitting on the box with his back to what he did.".
  Observe coach_after at green when morning(party) and not greenBurns(party) "Eleven strangers have taken their places in the bucket line without being asked, and are carrying water to a fire that is out. The man in the good coat has a blackened sleeve and is happier than he has been in years.".

  // ── The world, read ────────────────────────────────────────────────────────────────────────────────────────────
  Observe lore_ploughshare_sky at taproom when befell(cloudgate_fell) "Hob Wadsworth has a new story, and tells it to the whole room: a slab of the sky came down on a town in the south, with a house on its back, and he knows a man who knows the man who saw it go. Nan Ashworth says that if the sky is coming down she wants it to wait until the Margrave's soldiers have gone by, and puts another log on.".

  // ── What leaves the village ────────────────────────────────────────────────────────────────────────────────────
  // Told along the east road and the south road, and read by whoever keeps the roads in the countries around.
  Rule sallowfield_held_word when morning(party) and not greenBurns(party) and not pact(party) and not befell(sallowfield_held) { Assert befell(sallowfield_held). }
  Rule sallowfield_burned_word when morning(party) and greenBurns(party) and not befell(sallowfield_burned) { Assert befell(sallowfield_burned). }
}

data/adventures/sallowfield/parley.kyr:
Module sallowfield "Three Nights at Sallowfield" {
  // ── The scout in the cellar, and the captain at the stone ──────────────────────────────────────────────────────
  Relation vollTried(group). Relation lowesKind(group). Relation lowesBristled(group). Relation lowesHard(group). Relation lowesCarries(group). Relation parleyOpen(group). Relation parleyRefused(group).
  Relation bluffed(group). Relation vollLooked(group). Relation fothergillBought(group).
  Entity fothergill_known: fact "Lieutenant Fothergill wants the village burned for what the Margrave owes him personally, and Wyre keeps him on a rein.".

  // Kit Lowes, in the cellar of the Ploughshare, if he was taken.
  Topic lowes_ask with lowes "Ask the boy what he was doing in the reeds" when heldScout(lowes) once {
    Says "'Looking,' says Kit Lowes. He sits on the barrel with his boots between his knees. 'It's what I'm for. They send me because I'm small and I can count.' He swallows. 'What happens to me? I'll tell you anything. I'd just like to know.'".
  }
  Action question_kindly(actor: group, site: place) "Tell the boy he will be fed and sent home when it is over" {
    Speaker lowes.
    Requires able(actor) and company(actor) and at(actor, site) and at(lowes, site) and heldScout(lowes) and not lowesKind(party) and not lowesHard(party) and not lowesBristled(party).
    Time 2.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert lowesKind(party). Assert knows(actor, fothergill_known). }
    On failure { Assert lowesBristled(party). }
    Result "He believes you. It shows. He tells it from the beginning: the Margrave's debt, the unpaid spring, the captain who keeps them together by being honest, and the lieutenant who has never forgiven the vale for a cousin hanged at the last assize. He tells it like something saved up for the first kind person in a month.".
    Otherwise "He does not believe you. His mouth is shut so tight it has gone white, and you have the sense of having done something to him by asking.".
  }
  Action question_hard(actor: group, site: place) "Frighten it out of the boy" {
    Speaker lowes.
    Requires able(actor) and company(actor) and at(actor, site) and at(lowes, site) and heldScout(lowes) and not lowesKind(party) and not lowesHard(party).
    Time 2.
    Resolve check(actor, intimidation, dc_fair).
    On success { Assert lowesHard(party). Assert knows(actor, fothergill_known). }
    On failure { Retract at(lowes, site). Assert lowesGone(party). Assert lowesTruth(party). }
    Result "It does not take long. He tells you all of it fast, looking at your hands. When he is done he says 'Please' once and then nothing, and you have what you wanted and none of it is as good as it should be.".
    Otherwise "You frighten him, and he is no use to anyone. He says the same three words over and over, and then he is through the cellar door and up the lane, and he knows what you are.".
  }
  Action send_lowes_back(actor: group, site: place) "Send the boy back to Wyre with the truth: what you have built, and what you have not" {
    Speaker lowes.
    Requires able(actor) and company(actor) and at(actor, site) and at(lowes, site) and heldScout(lowes) and (lowesKind(party) or lowesHard(party)) and not lowesCarries(party).
    Time 0.
    On success { Assert lowesCarries(party). Assert lowesTruth(party). Retract at(lowes, site). Assert parleyOpen(party). }
    Result "He puts on his boots on the barrel, and the coat, and stands there with your word in his mouth like a coin. 'I'll say it,' he says. 'All of it. The way you said it.' He goes out by the cellar door and up the lane at a walk, which is a courage, and then at a run.".
  }
  Action send_lowes_lying(actor: group, site: place) "Send the boy back to Wyre with a lie: that the ford is where the village is weak" {
    Speaker lowes.
    Requires able(actor) and company(actor) and at(actor, site) and at(lowes, site) and heldScout(lowes) and (lowesKind(party) or lowesHard(party)) and not lowesCarries(party).
    Time 0.
    On success { Assert lowesCarries(party). Assert lowesLie(party). Retract at(lowes, site). Assert parleyOpen(party). }
    Result "'The ford,' says Kit Lowes. 'Soft at the ford. Two old men and a coach.' He says it twice, and the second time it is better than yours. He looks at you as if he would like to be told it is all right. You tell him it is.".
  }
  Rule carries_spoiled when lowesCarries(party) and grainSpoiled(party) and not wyreKnowsSpoiled(party) { Assert wyreKnowsSpoiled(party). }

  // The parley, noon of the last day (or the second, if he is early).
  Rule wyre_arrives when watch(clock) >= assaultAt(wyre) - 54 and not parleyHeld(party) {
    Assert parleyHeld(party). Assert at(wyre, parley_stone). Assert at(voll, parley_stone). Assert at(fothergill, parley_stone). }
  Relation parleyHeld(group).
  Rule wyre_leaves when parleyHeld(party) and watch(clock) >= assaultAt(wyre) - 36 and at(wyre, parley_stone) {
    Retract at(wyre, parley_stone). Retract at(voll, parley_stone). Retract at(fothergill, parley_stone). }
  Observe herald_seen at green when parleyHeld(party) and watch(clock) < assaultAt(wyre) - 36 and watch(clock) >= assaultAt(wyre) - 54 "On the east bank, by the standing stone, a white rag has been tied to a lance. Under it three men sit their horses and wait, and do not look as though they will wait long.".
  Observe wyre_unanswered at parley_stone when watch(clock) >= assaultAt(wyre) - 36 and not wyreMet(party) "The grass round the stone is trodden, and there is a white rag tied to the stone itself.".
  Relation wyreMet(group).

  Topic wyre_talk with wyre "Ask the captain what he wants" when true once {
    Says "'Grain,' says Wyre. He says it flatly, a thing he has stopped being ashamed of. 'Ninety sacks, and the use of the mill till spring. I have forty men and twenty with them who have not been paid since the Margrave decided I was a debt. We do not want your women. We do not want your bell. Sergeant Voll will tell you I have flogged for less.'".
    On discuss { Assert wyreMet(actor). }
  }
  Topic wyre_q with wyre "Wait for what the captain asks" when wyreMet(actor) once {
    Says "He takes off a glove, finger by finger. 'Let me ask the one thing,' he says. 'What is it worth to you, to be left alone? I mean in what you would do. Not what you would say.'".
    On discuss { }
  }
  Topic wyre_pay with wyre "The reeve's sixty, the plate and the grain" answering wyre_q when knows(actor, reeve_would_pay) and plateGiven(actor) and quantity(actor, gold) >= 60 {
    Says "'Hm,' says Wyre. He looks at Voll, who looks at the sky. 'Sixty and the plate and the grain.' He puts the glove on. 'It is too little and I'll take it.' He holds out his hand, and you take it, and it is dry and warm.".
    On discuss { Decrease quantity(actor, gold) by 60. Assert pact(actor). Assert winterShort(actor). }
  }
  Topic wyre_refuse with wyre "Nothing. We will not pay" answering wyre_q when true {
    Says "'No,' says Wyre, without any heat at all. 'I thought not. It is what I would say.' He looks past you at the village, the long way, as at a thing he will have to carry. 'I will come tonight. I would like you to know it gives me no pleasure.'".
    On discuss { Assert parleyRefused(actor). }
  }
  Topic wyre_owed with wyre "Tell me what you are owed. All of it" answering wyre_q when true {
    Says "He is silent for so long that Fothergill shifts in his saddle. Then he tells it, flatly: the spring, the Margrave's letter, the debt that has been recognised for six years and is not recognised this one, the eleven hundred, the forty men who have followed him because he said he would see them paid and has not. 'There,' he says. 'You asked.'".
    On discuss { Assert owedHeard(actor). }
  }
  Relation owedHeard(group).
  Action bluff_wyre(actor: group, site: place) "Tell the captain the Margrave's lancers are a day behind him" {
    Speaker wyre.
    Requires able(actor) and company(actor) and at(actor, site) and at(wyre, site) and not bluffed(party).
    Time 0.
    Resolve check(actor, deception, dc_hard).
    On success { Assert bluffed(party). Decrease thrust(ford_stones) by 4 or to nothing. Decrease thrust(bridge) by 4 or to nothing. Decrease thrust(mill_yard) by 4 or to nothing. Decrease thrust(nave) by 4 or to nothing. }
    On failure { Assert bluffed(party). Increase thrust(ford_stones) by 3. Increase thrust(bridge) by 3. Increase thrust(mill_yard) by 3. }
    Result "He listens to the whole of it with his head on one side, like someone reading a letter in a bad hand. 'A day,' he says. 'Behind me.' He looks at Voll. Voll studies the sky. 'A day,' he says again, to himself, and begins to count.".
    Otherwise "He listens courteously. When you have finished he says, 'Do you know, in thirty years I have been lied to by experts, and that was a good try, and I will remember it,' and there is something at the back of his eyes which was not there before.".
  }
  Topic voll_come with voll "Offer Sergeant Voll safe conduct to see the granary for himself" when grainSpoiled(actor) once {
    Says "Voll looks at the captain, who looks at nothing. 'Safe conduct,' says Voll. 'From you.' He gets down off his horse, which takes a while, and he walks beside you with his hand where you can see it. 'If it is a trap,' he says, 'I would like the lieutenant to know I said so.'".
    On discuss { Assert at(voll, granary). }
  }
  Action let_voll_look(actor: group, site: place) "Let Sergeant Voll walk through the granary, and smell it" {
    Speaker voll.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, granary) and at(voll, granary) and grainSpoiled(party) and not vollLooked(party) and not vollTried(party).
    Time 0.
    Resolve check(actor, deception, dc_fair).
    On success { Assert vollLooked(party). Assert wyreKnowsSpoiled(party). }
    On failure { Assert vollTried(party). Increase thrust(ford_stones) by 2. Increase thrust(bridge) by 2. Increase thrust(mill_yard) by 2. Increase thrust(nave) by 2. }
    Result "Voll goes through the granary door with his bad knee and comes out in the time it takes to boil an egg. He says four words to the captain's man, and it goes up the line. 'Salt,' says Voll. 'And lamp. The lot.'".
    Otherwise "Voll goes through the door and comes out and looks at you. 'Staged,' he says. 'It stinks of a thing done for me to smell.' He goes back up the road, and he does not walk.".
  }
  Action bribe_fothergill(actor: group, site: place) "Offer Lieutenant Fothergill ten coin and a way home" {
    Speaker fothergill.
    Requires able(actor) and company(actor) and at(actor, site) and at(fothergill, site) and knows(actor, fothergill_known) and quantity(actor, gold) >= 10 and not fothergillBought(party).
    Time 0.
    Resolve check(actor, persuasion, dc_hard).
    On success { Decrease quantity(actor, gold) by 10. Assert fothergillBought(party). Assert fothergillTurned(party). }
    On failure { Decrease quantity(actor, gold) by 10. Assert fothergillBought(party). Increase thrust(ford_stones) by 2. Increase thrust(bridge) by 2. Increase thrust(mill_yard) by 2. }
    Result "He takes the coin as he would take a handkerchief from a stranger. 'I would have you know,' says Fothergill, 'that I am not for sale. This is not a sale. This is a man who has reached the limit of what he is owed.' He looks at the vale. 'I will see what I can do about my captain.'".
    Otherwise "'My cousin,' says Fothergill, 'was hanged at Marden assize, and I do not remember that anyone offered ten coin.' He pockets the coin and turns his horse. He has not been moved by it. He has, you think, noted who made the offer, and the coin was not returned.".
  }
}

data/adventures/sallowfield/placed.kyr:
Module sallowfield "Three Nights at Sallowfield" {
  // The country beyond a march of a generated world: the company that comes in by the road is the world's own.
  Entity party: group "Your company".
  // What is said of Sallowfield in the country behind it: once the third morning has come, it is old news.
  Entity word: fact "What is said of Sallowfield in the country behind it.".
  Rule word_old when morning(party) and not stale(word) { Assert stale(word). }
  // And whether the green stands.
  Entity word_burned: fact "That Sallowfield's green was burned.".
  Rule word_burned_old when morning(party) and greenBurns(party) and not stale(word_burned) { Assert stale(word_burned). }
}

data/adventures/sallowfield/works.kyr:
Module sallowfield "Three Nights at Sallowfield" {
  // ── What can be done with two days ───────────────────────────────────────────────────────────────────────────
  // Every work costs hours that something else needed, and most cost the village something it will want later.
  // Time is in tens of minutes: 24 is four hours.
  Relation coachGone(group). Relation winterShort(group). Relation caltrops(group). Relation ironForSpikes(group). Relation coachMended(group).
  Relation drilledOne(group). Relation drilledTwo(group). Measure drillBonus(group).
  Relation evacuated(group). Relation bucketLine(group). Relation bellRung(group). Relation quarmbyAgrees(group).

  Item crowbar_a "a smith's crowbar" is crowbar at forge.
  Item shovel_a "a sod-cutting shovel" is shovel at forge.
  Item shovel_b "a second shovel" is shovel at mill_yard.
  Item pitch_pot "a pot of pitch" is lamp_oil at forge.

  Action build_barricade(actor: group, site: place) "Wall the ford with the coach, the inn's tables and the hurdles" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ford_stones) and not barricadeUp(actor) and posted(?v, ford_stones).
    Time 108.
    On success { Assert barricadeUp(party). Assert coachGone(party). Increase defence(ford_stones) by 4. }
    Result "It takes eighteen hours, six people, and every hurdle in the meadow. When it is done the coach is a wall: the body on its side, the wheels roped across the gap, the inn's tables behind for a firing-step. Teasdale watches the last wheel go up.".
  }
  Thing bridge_span "the packhorse bridge" at bridge {
    State standing "The bridge crosses on its two arches, the cobbles worn into hollows by three centuries of mules.".
    State cut blocking "The keystone of the near arch has been prised out and lies in the river, and the arch has slid after it. There is nothing between the banks but a gap of brown water.".
    Change cut_the_arch "Prise out the keystone of the near arch" from standing to cut needing crowbar.
  }
  Initially Assert state(bridge_span, standing).
  Rule bridge_cut_marks when state(bridge_span, cut) and not bridgeCut(party) { Assert bridgeCut(party). Increase defence(bridge) by 10. }
  Thing flood_gate "the flood-gate on the race" at race {
    State shut "A flood-gate of black oak stands shut across the head of the race, with a windlass and a pin. A painted board nailed over it says: MILLER ONLY.".
    State drawn "The flood-gate is drawn, and the river is going over the sill and out across the meadow in a long sheet, brown, quiet and a hand deep and rising.".
    Change draw_gate "Draw the flood-gate" from shut to drawn needing crowbar when quarmbyAgrees(party) "Gil Quarmby is standing on the sill with his arms folded. He has not said a word, and he does not need to.".
  }
  Initially Assert state(flood_gate, shut).
  Rule flood_marks when state(flood_gate, drawn) and not sluiceOpen(party) { Assert sluiceOpen(party). Assert hayLost(party). Increase defence(ford_stones) by 3. Increase defence(mill_yard) by 3. Decrease defence(bridge) by 4 or to nothing. Decrease nerve(greenhalgh) by 2 or to nothing. }
  // A flood over the meadow drowns the pits, and what it does to the ford it does to the bridge's footings.
  Rule flood_drowns_pits when sluiceOpen(party) and pitsDug(party) and not pitsDrowned(party) { Assert pitsDrowned(party). Decrease defence(ford_stones) by 3 or to nothing. Decrease defence(mill_yard) by 3 or to nothing. }
  Relation pitsDrowned(group).
  Relation hayLost(group).
  Thing meadow_way "the ford meadow" on ford_meadow_way is scenery {
    State dry "The meadow is wet grass and cropped turf.".
    State flooded blocking "The meadow is under a hand of brown water and the hawthorn hedge stands out of it like a row of drowned men.".
  }
  Initially Assert state(meadow_way, dry).
  Rule meadow_floods when sluiceOpen(party) and state(meadow_way, dry) { Assert state(meadow_way, flooded). }
  Action dig_pits(actor: group, site: place) "Dig pits in the ford meadow and lay hurdles over them" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ford_meadow) and holding(actor, shovel) and not pitsDug(party) and not sluiceOpen(party).
    Time 84.
    On success { Assert pitsDug(party). Increase defence(ford_stones) by 3. Increase defence(mill_yard) by 3. Increase defence(bridge) by 1. }
    Result "You dig until your hands blister and then you dig on. The pits are a yard deep, a yard wide, laid out in a staggered line from the hedge to the ford, and the hurdles lie over them as naturally as a hurdle can. The villagers who watch say nothing. A horse would not see them either.".
  }
  Action spoil_grain(actor: group, site: place) "Foul the tithe grain with brine and lamp oil" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, granary) and not grainSpoiled(party) and holding(actor, lamp_oil) and knows(actor, reeve_would_pay).
    Time 6.
    On success { Spend lamp_oil from actor. Assert grainSpoiled(party). Assert winterShort(party). }
    Result "It is a thing you can do in an hour. The oil goes on the sacks in a black stain and the brine from the pickle-tubs after it, and by the end the granary stinks of salt and lamp. Tib Elland watches from the door with his tally-sticks hanging and says, 'That was the winter.'".
  }
  // The grain is the village's winter: what is done to it is done to them.
  Rule spoiled_costs when grainSpoiled(party) and not spoiledMod(party) {
    Assert spoiledMod(party). Assert at(elland, fold).
    Decrease nerve(ashworth) by 1 or to nothing. Decrease nerve(quarmby) by 1 or to nothing. Decrease nerve(wadsworth) by 1 or to nothing. Decrease nerve(greenhalgh) by 1 or to nothing. }
  Relation spoiledMod(group).
  Action drill_levy(actor: group, site: place) "Drill the levy on the green with staves" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, green) and not drilledTwo(party) and watch(clock) < 330.
    Time 60.
    Resolve check(actor, intimidation, dc_fair).
    On success { Increase drillBonus(party) by 1. Assert drilledOne(party). }
    On failure { Assert drilledOne(party). }
    Result "You make them walk in a line and then in two lines, and carry staves, and strike at a post and at each other. By the third hour there are forty of the sixty on the green who know which way to point. Hob Wadsworth is now good at the part where you shout.".
    Otherwise "It is not a success. The line wanders, and a goose gets in it, and Hob Wadsworth makes a speech.".
  }
  Rule drilled_twice when drilledOne(party) and drillBonus(party) >= 2 and not drilledTwo(party) { Assert drilledTwo(party). }
  Action evacuate_the_helpless(actor: group, site: place) "Take the old, the sick and the children up to the high fold" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, green) and not evacuated(party).
    Time 36.
    Resolve check(actor, wayfinding, dc_easy).
    On success { Assert evacuated(party). }
    Result "It is a procession: thirty-odd, a cart, two goats, a cradle, and old Mistress Haworth in a chair carried between two boys who are not speaking to each other. Crowther at the fold stands aside and says only, 'Mind the wall.'".
    Otherwise "The track is steeper than anyone said. You turn back with half of them, and the other half up the hill without you.".
  }
  Action form_bucket_line(actor: group, site: place) "Set a bucket line from the well to the green" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, well) and not bucketLine(party).
    Time 12.
    On success { Assert bucketLine(party). }
    Result "Nan Ashworth takes the end of the line without being asked, and the first bucket is in your hands before you have finished saying where it goes. By dusk there are three lines of women and the well-rope is smoking.".
  }
  Action ring_the_bell(actor: group, site: place) "Ring the chapel bell for the village to stand to" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bell_loft) and not bellRung(party) and watch(clock) >= assaultAt(wyre) + 6 and watch(clock) < assaultAt(wyre) + 12 and w2planned(party).
    Time 0.
    On success { Assert bellRung(party). Increase defence(ford_stones) by 2. Increase defence(bridge) by 2. Increase defence(mill_yard) by 2. Increase defence(nave) by 2. }
    Result "The bell goes out over the vale like a great hand laid on every roof. In every house a door opens. You can hear, under the last note, forty of them finding their feet.".
  }
  Rule numbers_help when knowsNumbers(party) and not numMod(party) { Assert numMod(party). Increase defence(ford_stones) by 2. Increase defence(bridge) by 2. Increase defence(mill_yard) by 2. Increase defence(nave) by 2. }
  Relation numMod(group).
  Action scout_the_road(actor: group, site: place) "Count the column from the Scar" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lookout) and watch(clock) >= 120 and not knowsNumbers(party) and not scouted(party).
    Time 6.
    Resolve check(actor, woodcraft, dc_fair).
    On success { Assert knowsNumbers(party). Assert scouted(party). }
    On failure { Assert badCount(party). Assert scouted(party). }
    Result "You lie on the limestone with the cairn at your head and watch them come down the east road in the late light: forty on horse and foot, a wagon, a string of led horses, a standard with the Margrave's green gone to brown. Twenty more follow, on foot, with women among them. They are not marching. They are walking like people who have not been paid since spring.".
    Otherwise "You lie on the limestone and count, and it comes to sixty on horse and foot, and you tell it so in the village: sixty armed men. It is a good clear count, and it is a bad one. Twenty of them were women with the wagons, and by the time that is known the levy has stopped asking.".
  }

  Relation badCount(group). Relation scouted(group).
  Rule bad_count_hurts when badCount(party) and battleOn() and not badMod(party) { Assert badMod(party). Decrease drillBonus(party) by 1 or to nothing. Decrease defence(ford_stones) by 1 or to nothing. Decrease defence(bridge) by 1 or to nothing. Decrease defence(mill_yard) by 1 or to nothing. Decrease defence(nave) by 1 or to nothing. }
  Relation badMod(group).

  // The ledger: the hours there are, said in bands, until the night he is expected (a quarter of a day each).

  // The reeve's sixty is the village's, house by house; it takes the time it takes, and Stansfield is no use at it.
  Action collect_the_sixty(actor: group, site: place) "Go house to house with the reeve for the sixty" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, green) and knows(actor, reeve_would_pay) and not sixtyCollected(party).
    Time 96.
    Resolve check(actor, persuasion, dc_fair).
    On success { Increase quantity(actor, gold) by 60. Assert sixtyCollected(party). Decrease nerve(stansfield) by 1 or to nothing. }
    On failure { Increase quantity(actor, gold) by 20. Assert sixtyCollected(party). }
    Result "Forty-one doors, and the reeve behind you with his ledger saying the name of each one before you knock. Most open. Nan Ashworth gives the lot of her slate. At the Haworths' they have nothing and give it.".
    Otherwise "It is a bad day for a request. You come back with a purse that is lighter than a sixty, and the reeve writes the name of every door that did not open.".
  }
  Relation sixtyCollected(group).

  Observe ledger_0 near party when not wyreEarly(party) and watch(clock) >= 0 and watch(clock) < 72 and not battleOn() "Two days and a night before the night he is expected. The wall alone is eighteen hours, the pits fourteen, the drill ten each, the caltrops nine; the iron is only enough for the coach or the caltrops. There are not enough hours for the lot.".
  Observe ledger_1 near party when not wyreEarly(party) and watch(clock) >= 72 and watch(clock) < 144 and not battleOn() "A day and most of a night. If the wall is not up by the second dusk it will not be up. Choose what you will not do.".
  Observe ledger_2 near party when not wyreEarly(party) and watch(clock) >= 144 and watch(clock) < 204 and not battleOn() "The second day. The boy in the reeds comes tonight, and the farm is raided the same hour; the company is one body.".
  Observe ledger_3 near party when not wyreEarly(party) and watch(clock) >= 204 and watch(clock) < 246 and not battleOn() "The second evening. What was not begun by now will not be finished before the stone.".
  Observe ledger_4 near party when not wyreEarly(party) and watch(clock) >= 246 and watch(clock) < 306 and not battleOn() "The last morning. Whatever is half done is half done.".
  Observe ledger_5 near party when not wyreEarly(party) and watch(clock) >= 306 and watch(clock) < 342 and not battleOn() "The last afternoon. He is at the stone at noon, if he comes to talk.".
  Observe ledger_6 near party when not wyreEarly(party) and watch(clock) >= 342 and watch(clock) < 366 and not battleOn() "Dusk. Whatever is built is what there is.".
  Observe ledger_early near party when wyreEarly(party) and not battleOn() "He is coming tonight. Whatever is not done is not going to be.".
}

data/adventures/skeel/after.kyr:
Module skeel "Fair Weather" {
  // ── After the Court ───────────────────────────────────────────────────────────────────────────────────────────────
  // Skeel is still here after its story, and shows what became of it. The packet sails on the fourth day, on the
  // evening flood, with whoever is going.
  Rule ewan_brings at net_loft when matterOpen(call) and at(nye, net_loft) and not at(party, net_loft) and not decided(call) says "Ewan Marrock walks the boy up the loft to the table with his hand on his shoulder." { Assert livingShown(reach). Assert decided(call). Assert notWreck(reach). Assert nyeFaced(nye). }
  Rule after_return when courtDone(reach) and not dispersed(reach) {
    Assert dispersed(reach).
    Retract at(jago, net_loft). Assert at(jago, taproom). Retract at(hosken, net_loft). Assert at(hosken, church).
    Retract at(constance, net_loft). Assert at(constance, taproom). Retract at(kerensa, net_loft). Assert at(kerensa, quay).
    Retract at(ewan, net_loft). Assert at(ewan, quay). Retract at(nye, net_loft). Assert at(nye, taproom).
    Retract at(admiral, net_loft). Assert at(admiral, taproom). }
  Relation dispersed(place).
  Rule after_hender_home when courtDone(reach) and not henderGone(hender) and at(hender, net_loft) { Retract at(hender, net_loft). Assert at(hender, reeve_parlour). }
  Rule after_hender_cellar when courtDone(reach) and henderExposed(hender) and not henderGone(hender) and not at(hender, cellars) { Retract at(hender, net_loft). Retract at(hender, reeve_parlour). Assert at(hender, cellars). }
  Rule after_cawse_lantern when courtDone(reach) and lovedayOff(reach) and not at(cawse, lamp_room) { Retract at(cawse, net_loft). Retract at(cawse, wreck_house). Assert at(cawse, lamp_room). }
  Rule after_cawse_back when courtDone(reach) and lovedayKept(reach) and at(cawse, net_loft) { Retract at(cawse, net_loft). Assert at(cawse, wreck_house). }
  Rule after_loveday_home when courtDone(reach) and lovedayKept(reach) and not at(loveday, lamp_room) and not following(loveday, party) { Retract at(loveday, net_loft). Retract at(loveday, taproom). Assert at(loveday, lamp_room). }
  Rule after_loveday_off when courtDone(reach) and lovedayOff(reach) and not at(loveday, taproom) { Retract at(loveday, net_loft). Retract at(loveday, lamp_room). Retract following(loveday, party). Assert at(loveday, taproom). }
  Rule after_ewan_home when courtDone(reach) and at(ewan, quay) and not ewanGoesSouth(ewan) and hour(clock) >= 18 { Retract at(ewan, quay). Assert at(ewan, skerry_landing). }
  Rule after_nye_follow when courtDone(reach) and following(nye, party) { Retract following(nye, party). Assert at(nye, taproom). }

  // The packet: on the fourth day at six in the evening, with the flood.
  Query fourthEvening() means dayN(reach) >= 5 or dayN(reach) == 4 and hour(clock) >= 18.
  Relation packetSailed(place).
  Rule packet_sails when fourthEvening() and courtDone(reach) and not packetSailed(reach) { Assert packetSailed(reach).
    Retract at(constance, taproom). Retract at(constance, acre). Assert at(constance, limbo).
    Retract at(nye, taproom). Assert at(nye, limbo). }
  Rule packet_takes_dog when packetSailed(reach) and dogWithNye(admiral) and not at(admiral, limbo) { Retract at(admiral, taproom). Retract at(admiral, bothy). Assert at(admiral, limbo). }
  Rule packet_takes_hender when packetSailed(reach) and henderExposed(hender) and not henderGone(hender) { Assert henderGone(hender). Retract at(hender, reeve_parlour). Retract at(hender, cellars). Retract at(hender, church). Retract at(hender, wreck_house). Assert at(hender, limbo). }
  Rule packet_takes_ewan when packetSailed(reach) and ewanGoesSouth(ewan) and not at(ewan, limbo) { Retract at(ewan, quay). Retract at(ewan, skerry_landing). Assert at(ewan, limbo). Assert ewanRows(party). }
  Rule packet_takes_kerensa when packetSailed(reach) and not pilotsAgreed(reach) and not travelsWith(kerensa, party) and not kerensaGone(kerensa) { Assert kerensaGone(kerensa). Retract at(kerensa, quay). Retract at(kerensa, reeve_parlour). Assert at(kerensa, limbo). }
  Rule packet_seen_go at quay when packetSailed(reach) and at(party, quay) and not packetGoneTold(party) says "Ferrar's packet goes down the channel on the evening flood, sounding as she goes, the leadsman in the bows calling the marks; and Skeel stands on the quay and watches her, the way it watches anything that comes into the Reach or goes out of it." { Assert packetGoneTold(party). }
  Relation packetGoneTold(group).
  // The dog, if he has nobody else: he will go with the company.
  Rule dog_stays_on when courtDone(reach) and dogFriend(party) and not reunited(nye) and not dogDrowned(admiral) and not willing(admiral, party) and not travelsWith(admiral, party) { Assert willing(admiral, party). }
  Rule dog_leaves_follow when courtDone(reach) and following(admiral, party) and willing(admiral, party) { Retract following(admiral, party). Assert at(admiral, taproom). Retract dogHidden(admiral). }

  // ── How Skeel looks, after ────────────────────────────────────────────────────────────────────────────────────────
  Observe fore_wreck_after at fore_street as sign when courtDone(reach) and wreckDeclared(reach) "On the Reeve's gable, beside the Lady with the Lyre, there is a new saint: a girl of nine in a blue dress with an open book against her chest. CONSTANT AND TRUE.".
  Observe fore_notwreck_after at fore_street as sign when courtDone(reach) and notWreck(reach) and not pilotsAgreed(reach) "On every door along Fore Street somebody has chalked, small, a dog: four legs and a tail and a curl for the coat. Some are rude. Most are not.".
  Observe church_board_after at church as sign when courtDone(reach) and henderExposed(hender) "Chalked on the charter board under NEITHER MAN NOR DOG NOR CAT, in a child's capitals: NOR BOY.".
  Observe church_saint_pilots at church as sign when courtDone(reach) and notWreck(reach) "In the church, under the hanging ships, propped against the altar rail where Constance Ferrar left her, the Constancy's figurehead: the girl in the blue dress with the open book. CONSTANT AND TRUE. 'Keep her,' Constance Ferrar said. 'Put her where people will look at her.'".
  Observe inish_lit at beacon as sign when pilotsAgreed(reach) "The iron basket on the cairn is lit, and burns, and on the strand below there are two gigs where there was one: JACOB, blue, and a second, unpainted, with new planks, that Kerensa Brask says is to be called THE CONSTANCY, and Malachy Sennen says over his dead body.".
  Observe inish_pilots at pilot_house as sign when pilotsAgreed(reach) "On the door of the pilot-house, newly painted in white: STATION. And under it, smaller, in Malachy's own shaking hand: KNOCK.".
  Observe quay_pilots at quay as sign when pilotsAgreed(reach) "On the harbour wall, under the tide-board, a new board, freshly painted: PILOTS OF THE REACH. FIRE A GUN OFF THE BAR. And Jinny Rowse sitting on her bollard under it, eating an apple off her knife, looking very pleased with herself and pretending not to.".
  Observe tap_after_wreck at taproom as ambience when courtDone(reach) and wreckDeclared(reach) "The Admiral is full: there is wreck money in Skeel, and the fishermen at the long table have something stronger than small beer in front of them, and are not looking at it any more cheerfully.".
  Observe tap_after_hungry at taproom as ambience when courtDone(reach) and notWreck(reach) and not pilotsAgreed(reach) "The Admiral is half empty. Mother Jago is giving the fishermen their beer on the slate, and writing nothing on the slate.".
  Observe tap_after_pilots at taproom as ambience when courtDone(reach) and pilotsAgreed(reach) "The Admiral is loud. Somebody has chalked the twelve gigs on the wall by the fire, with their colours, and the fishermen are arguing about which family had which.".
  Observe quay_ewan at quay when ewanInSkeel(ewan) and at(ewan, quay) and courtDone(reach) "Ewan Marrock stands on the quay with his arms folded, the first time in seven years, and Skeel walks round him in a wide curve, the way water goes round a rock, and some of them nod to him, and he nods back.".
  Observe tap_kerensa_spoke at taproom when kerensaSpoke(party) and courtDone(reach) "In the Admiral they are talking about the Reeve's girl, who stood up in the loft; and they stop when you come in.".
  Observe tap_loveday at taproom when at(loveday, taproom) and lovedayOff(reach) "In the back corner by the fire, where it is warm, Loveday Kitto sits with her hands in her lap, facing the window that looks toward the Holm.".
  Observe parlour_after at reeve_parlour when courtDone(reach) and at(hender, reeve_parlour) and (henderConfessed(hender) or henderExposed(hender)) "The Reeve's parlour, very tidy. Hender Brask sits in his chair by the cold grate in his shirtsleeves, with his hands on his knees, waiting. He looks as if he has slept, for the first time in a long while.".
  Observe parlour_gone at reeve_parlour when henderGone(hender) "The Reeve's parlour is empty and the grate is cold. On the table, squared to the edge, the Wreck-House book, closed.".
  Observe lamp_cawse at lamp_room when at(cawse, lamp_room) "Jack Cawse sits in Loveday Kitto's chair in the lamp-room with his boots on the table and his cudgel across his knees, very pleased, looking out at the Reach. The wicks want trimming.".
  Observe bothy_empty at bothy when packetSailed(reach) and ewanGoesSouth(ewan) "The bothy is swept and cold. The shelf where the comb and the ribbon and the shell were is bare. On the door, scratched with a knife: GONE SOUTH. MIND THE SEALS.".
  Observe acre_after at acre as ambience when acreFilled(reach) "The open graves along the wall are filled in, and the turf put back, and there are new stones.".
  Topic jago_after with jago "Ask Mother Jago how Skeel is taking it" when courtDone(reach) once {
    Says "She leans on the bar. 'Like a town that's been told something about itself,' she says. 'Some'll never forgive it, and some'll never forgive themselves, and most'll do both on alternate days for twenty years and then die.' She looks up at the yellow bird in the rafters. 'I'm keeping him. He's no wreck. He's a lodger.'".
  }
  Topic loveday_after_court with loveday "Ask Loveday Kitto how she does" when courtDone(reach) once {
    Says "'I sit and think of the Pulpit,' she says, 'every evening, the notch in the Craigs, and I don't know yet whether I'll stop.' She turns toward the sound of you. 'He was a quiet boy. He'd sit up with me all night and never say a word. I should have known that wasn't goodness. That was a boy counting.'".
  }
  Topic kerensa_pilot_after with kerensa "Ask Kerensa Brask what she will do now" when courtDone(reach) and pilotsAgreed(reach) once {
    Says "She grins with her whole face. 'Pilot. First of the new.' She slaps the gig. 'Malachy says I've hands like Jacob's and a head like a bucket, and he'll make something of me if it kills him, and it might.' Then, not grinning: 'I'll write to my father. Wherever they take him. I'll not go and see him. I'll write.'".
  }
  Topic kerensa_after with kerensa "Ask Kerensa Brask what she will do now" when courtDone(reach) and not pilotsAgreed(reach) and not kerensaGone(kerensa) once {
    Says "'Go,' she says. 'Same as I said. The packet sails on the fourth tide. Or with you, if you're going somewhere with ships in it.' She looks at the gig. 'I'll write to him. I'll not go and see him. I'll write.'".
  }
}

data/adventures/skeel/company.kyr:
Module skeel "Fair Weather" {
  // The campaign played alone: a traveller come down the coast road with a little money and no reason to stop, three
  // days after the Constancy struck. (placed.kyr is the world's own company, come in over the march.)
  Company party "You" of 1 to 3 at coast_road.
  Initially Set quantity(party, gold) to 8. Initially Set quantity(party, rations) to 3.
}

data/adventures/skeel/constance.kyr:
Module skeel "Fair Weather" {
  // ── Constance Ferrar ──────────────────────────────────────────────────────────────────────────────────────────────
  // The shipowner's daughter, twenty-eight, who keeps the books of Ferrar and Daughters in a southern port because her
  // father's hands shake. The Constancy was named for her when she was nine, and carved as her. Her brother Matthew was
  // the mate. She comes in on the owners' packet on the evening of the second day, on the flood, for him and for the
  // ship; and the firm needs the grain as badly as Skeel does.
  Person constance "Constance Ferrar" at limbo {
    Role "who keeps the books of Ferrar and Daughters, shipowners". Ancestry human. Peaceable. Pronouns she. Manner proud.
    Greets "A young woman in grey, very upright, with a ledger under her arm and salt on the hem of her skirt, who looks at you as she must look at a bill of lading: carefully, and expecting it to be wrong. 'Constance Ferrar,' she says. 'The Constancy was ours. My brother was her mate. If you have anything to tell me, I would be grateful for it. Nobody in this town has told me anything except the price of a bed.'".
    Greets again "Constance Ferrar closes her ledger on her finger and waits.".
  }
  Relation constanceCome(group).
  Rule packet_in when secondDay() and hour(clock) >= 17 and not constanceCome(constance) { Assert constanceCome(constance). Retract at(constance, limbo). Assert at(constance, quay). }
  Rule packet_seen at quay when constanceCome(constance) and at(party, quay) and not packetTold(constance) and secondDay() says "A packet-boat is coming up the channel on the flood, a cutter with a red ensign, very careful, sounding as she comes, a man in the bows swinging the lead and calling the marks. She ties up at the quay steps, and a young woman in grey with a ledger under her arm comes up them alone, and stands on the quay looking at the Wreck-House, and the figureheads, and the town looking at her." { Assert packetTold(constance). }
  Relation packetTold(group).
  Rule constance_to_inn when constanceCome(constance) and hour(clock) >= 19 and at(constance, quay) and not courtSitting() { Retract at(constance, quay). Assert at(constance, taproom). }
  Rule constance_to_acre when constanceCome(constance) and thirdDay() and hour(clock) >= 8 and hour(clock) < 14 and at(constance, taproom) { Retract at(constance, taproom). Assert at(constance, acre). }
  Rule constance_from_acre when constanceCome(constance) and thirdDay() and hour(clock) >= 14 and at(constance, acre) { Retract at(constance, acre). Assert at(constance, taproom). }
  Observe acre_constance at acre when at(constance, acre) "Constance Ferrar is walking slowly along the open graves by the wall, reading the old stones as she goes. A SAILOR. A SAILOR. A WOMAN. She has her ledger open, and is writing them down.".

  Topic constance_matthew with constance "Ask Constance Ferrar about her brother" when true once {
    Says "'Matthew.' She opens the ledger and closes it. 'He was the mate. He was thirty. He was the one of us who liked the sea; I like the books.' She looks out at the Reach. 'They tell me the Reach gives back its drowned on the third ebb. I mean to be on the sand when it does. I mean to take him home.' Her voice does not shake at all. 'They tell me also that they bury what it gives them under stones that say A SAILOR. He will not have a stone that says A SAILOR.'".
    On discuss { Assert knows(actor, matthew_named). Assert knows(actor, third_ebb). }
  }
  Topic constance_firm with constance "Ask Constance Ferrar what the Constancy's cargo means to Ferrar and Daughters" when true once {
    Says "She almost smiles. 'Everything.' She taps the ledger. 'Four hundred tons of grain bought on credit at the top of the market, to sell in the north at the bottom of a famine. If it is wreck, the underwriters pay a third, and we sell the house. If it is ours, we live.' She looks at the Wreck-House. 'They are hungry here. I can see that. I have been hungry. It does not make the grain theirs.'".
    On discuss { Assert knows(actor, ferrar_need). }
  }
  Discovery ferrar_need "Ferrar and Daughters bought the Constancy's grain on credit; if she is wreck, the firm is ruined. If she is not, Skeel goes hungry through the winter.".
  Topic give_matthew_letter with constance "Give Constance Ferrar her brother's letter" when carries(actor, matthew_letter) and constanceCome(constance) once {
    Says "She knows the hand before she has it out of the oilskin. She reads it standing, once, fast, the way she reads everything, and then again very slowly, and then she sits down on the nearest thing, which is a lobster-pot, and holds it in her lap. 'I shall bring you something foolish,' she says, aloud. She laughs, which is worse than anything. 'He would have, too. Last year it was a monkey.' She folds the letter along its folds. 'Dunn says there will be the Holm light to steer by,' she reads. She looks up at you. 'There was no Holm light. Was there.'".
    On discuss { Spend letter_matthew from actor. Assert constanceMoved(constance). Assert knows(actor, matthew_known). }
  }
  Relation constanceMoved(group).
  Topic give_ring with constance "Give Constance Ferrar the ring from her brother's chest" when carries(actor, matthew_ring) and constanceCome(constance) once {
    Says "She turns it to the light and reads the inside of the band, M.F. FROM HIS SISTER, and closes her hand on it. 'I bought it with my first quarter's wages,' she says. 'He said it was the ugliest ring he had ever seen, and never took it off.' She puts it on her thumb, where it is too big. 'Thank you.'".
    On discuss { Spend mate_ring_kind from actor. Assert constanceMoved(constance). }
  }
  Topic constance_light with constance "Tell Constance Ferrar what you know of how the Constancy came onto the bank" when knows(actor, hender_did) and constanceCome(constance) once {
    Says "She listens without moving, the ledger shut on her knee. When you have finished she sits with her thumb in the ledger, holding the place. 'So it was not the sea,' she says. 'It was a man. A Reeve. With an oil can and a horn lantern.' She stands up. 'I came here to take my brother home. I will do that. And then I will go to the Admiral's court, in the south, and I will lay an information, and they will hang him, and it will not bring Matthew back, and I will do it anyway.' She looks at you. 'Unless there is some other thing to be done. Is there?'".
    On discuss { Assert constanceKnows(constance). }
  }
  Relation constanceKnows(group).

  // ── The third ebb ─────────────────────────────────────────────────────────────────────────────────────────────────
  // On the night low water of the third day the Reach gives back the Constancy's eleven men at the wrack line below the
  // Slip, as it nearly always does.
  Relation drownedIn(place).
  Rule third_ebb when thirdDay() and lowWater() and hour(clock) >= 23 and not drownedIn(reach) { Assert drownedIn(reach). }
  Rule third_ebb_late when dayN(reach) >= 4 and not drownedIn(reach) { Assert drownedIn(reach). }
  Observe drowned_scene at slip when drownedIn(reach) and not acreFilled(reach) "Along the wrack line at the foot of the Slip, among the weed and the driftwood, the sea has laid out the Constancy's people: eleven men, side by side, almost in a row, as if somebody had arranged them. Lanterns stand on the sand by them, and Skeel stands round them in the dark, men with their hats off, women with their shawls over their heads, quiet. Parson Hosken is going from one to the next.".
  Relation matthewFound(group). Relation matthewHome(group). Relation crewNamed(place).
  Action find_matthew(actor: group, site: place) "Look among the drowned for Matthew Ferrar" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, slip) and drownedIn(reach) and not matthewFound(actor)
      and (knows(actor, matthew_named) or knows(actor, matthew_known)).
    Time 2.
    On success { Assert matthewFound(actor). }
    Result "You go along the line with a lantern. They are not frightening; they are only men, very tired, a long way from home. The seventh is a man of thirty with fair hair and a mate's coat and, on the third finger of his right hand, the white band in the brown where a ring was for years and is not now.".
  }
  Event constance_finds at slip when matthewFound(party) and constanceCome(constance) and not matthewHome(constance) "Constance Ferrar comes down the Slip with her skirts held up out of the wet, and sees where you are standing, and comes along the line of men to you without hurrying and kneels down on the sand by her brother, and puts her hand flat on his chest, the way you put a hand on someone's chest to wake them. Nobody in Skeel says anything at all. After a long time she says, not to anyone: 'Well, Mattie. I've come to fetch you.'" then { Assert matthewHome(constance). }
  Topic give_names with hosken "Give Parson Hosken the names of the Constancy's men" when knows(actor, crew_names) and not crewNamed(reach) once {
    Says "He writes them down in the back of his prayer-book, one by one, as you say them, moving his lips: Abel Dunn, master; Matthew Ferrar, mate; and the rest. When you have finished he reads them through once aloud, very quietly, as if in church. 'Eleven names,' he says. 'Eleven stones. I shall cut them myself if I must.' He takes off his spectacles and wipes them on his cassock, which makes them worse, and puts them on again. 'Thank you. You do not know what you have done for me.'".
    On discuss { Assert crewNamed(reach). }
  }
  Topic nye_names with nye "Ask Nye Gallow for the names of the Constancy's men" when knows(actor, nye_saw) once {
    Says "He says them without stopping, like a lesson: 'Master Abel Dunn. Mister Ferrar, the mate. Tom Kellow, bosun. Davey Treen and his brother Sam. Old Hob. Josiah Wake, the cook. Billy Ash. Dancer, we called him Dancer, his name was Peter Rule. Ned Penrose. Luke Gale.' He stops. 'And me. But I'm not.'".
    On discuss { Assert knows(actor, crew_names). }
  }
  Discovery crew_names "The Constancy's men: Abel Dunn, master; Matthew Ferrar, mate; Tom Kellow, bosun; Davey and Sam Treen; Old Hob; Josiah Wake, cook; Billy Ash; Peter Rule, called Dancer; Ned Penrose; Luke Gale.".
  Rule acre_filled when drownedIn(reach) and dayN(reach) >= 4 and hour(clock) >= 10 and not acreFilled(reach) { Assert acreFilled(reach). }
  Observe acre_named at acre as sign when acreFilled(reach) and crewNamed(reach) "Along the wall, ten new stones, and on each one, cut by an unpractised hand, a name: ABEL DUNN. TOM KELLOW. DAVEY TREEN. SAM TREEN. HOB. JOSIAH WAKE. BILLY ASH. PETER RULE, DANCER. NED PENROSE. LUKE GALE. OF THE CONSTANCY.".
  Observe acre_unnamed at acre as sign when acreFilled(reach) and not crewNamed(reach) "Along the wall, ten new stones, small and square, each one cut the same: A SAILOR.".
  Observe acre_matthew at acre as sign when acreFilled(reach) and not matthewHome(constance) "And an eleventh, a little apart: A SAILOR, MATE.".
  Observe acre_matthew_home at acre as sign when acreFilled(reach) and matthewHome(constance) "There is no eleventh. Constance Ferrar took her brother home on the packet.".
}

data/adventures/skeel/court.kyr:
Module skeel "Fair Weather" {
  // ── Hender, asked ─────────────────────────────────────────────────────────────────────────────────────────────────
  // He will not be moved by a hook, or a cup of oil, or a stranger's say-so. He cannot lie to Loveday Kitto.
  Relation henderConfessed(group). Relation henderExposed(group). Relation bribed(group). Relation toldToConfess(group).
  Event loveday_asks when following(loveday, party) and lovedaySees(loveday) and at(hender, ?p) and at(party, ?p) and not henderConfessed(hender) and not courtSitting() "Loveday Kitto lets go of your arm and walks up to Hender Brask, and he sees her, and stands up; and she stands in front of him in her good shawl, a head shorter than his chest, and takes off the spectacles, as if she would rather not see this, and folds them. 'Hender,' she says. 'Did you put the sea in my oil.' It is not a question the way she says it. He opens his mouth. Nothing comes. You watch his ears go red, slowly, from the lobes up, like a boy's. 'Yes,' he says. Then he sits down, very suddenly, as if somebody had cut a string, and puts his face in his hands, and says it all, to her, not to you: the factor's letter, the arrears, the salt company, the weeks of counting; the watered oil; the hook driven in beside his father's ring; the ship turning for the light; his hand over the lantern. And the boy on the hatch. 'I held up the lamp,' he says into his hands, 'and he looked at me, and I thought: if he lives, she's no wreck. And I walked away.' Loveday Kitto stands and listens to all of it without a word. When he has finished she puts her hand on his head, the way you would on a child's, and leaves it there." teaches hender_did then { Assert henderConfessed(hender). Retract following(loveday, party). }
  Event loveday_asks_blind when following(loveday, party) and not lovedaySees(loveday) and at(hender, ?p) and at(party, ?p) and not henderConfessed(hender) and not courtSitting() "Loveday Kitto lets go of your arm and walks up to Hender Brask, and he sees her, and stands up; and she stands in front of him in her good shawl, a head shorter than his chest, and looks up at him, though she cannot see his face, and he knows she cannot. 'Hender,' she says. 'Did you put the sea in my oil.' It is not a question the way she says it. He opens his mouth. Nothing comes. You watch his ears go red, slowly, from the lobes up, like a boy's. 'Yes,' he says. Then he sits down, very suddenly, as if somebody had cut a string, and puts his face in his hands, and says it all, to her, not to you: the factor's letter, the arrears, the salt company, the weeks of counting; the watered oil; the hook driven in beside his father's ring; the ship turning for the light; his hand over the lantern. And the boy on the hatch. 'I held up the lamp,' he says into his hands, 'and he looked at me, and I thought: if he lives, she's no wreck. And I walked away.' Loveday Kitto stands and listens to all of it without a word. When he has finished she puts her hand on his head, the way you would on a child's, and leaves it there." teaches hender_did then { Assert henderConfessed(hender). Retract following(loveday, party). }
  Topic loveday_after with loveday "Ask Loveday Kitto what happens now" when henderConfessed(hender) and not courtOver(reach) once {
    Says "'Now he'll do what's right,' she says. 'He always does, once he's been made to look at it.' She puts the spectacles back on, if she has them. 'He'll stand up in that loft and say it to Skeel's face. And they'll hang him, likely, the Admiral's men. And I'll keep the Lantern till I can't, and then I'll keep it some more.'".
  }
  // A company that knows can tell him so: he will offer it money to say nothing; or it can send him to her.
  Topic confront_hender with hender "Tell Hender Brask you know who hung the light in the Pulpit" when knows(actor, hender_did) and not henderConfessed(hender) and not bribed(actor) and not toldToConfess(actor) and not courtOver(reach) once {
    Says "He does not deny it. He does not say anything. He looks at the book in front of him until the candle gutters, and then he closes it, and takes out of the drawer a purse, a heavy one, and puts it on the cover. 'Twenty coin,' he says. 'The Admiral's third is mine to give. Nobody has to know. Not the Court. Not Skeel.' His voice drops. 'Not Loveday. Whatever else. Not Loveday.' He looks up. 'What do you want?'".
  }
  Topic take_bribe with hender "Take the purse, and say nothing" answering confront_hender when knows(actor, hender_did) once {
    Grave "Eleven men, and a boy on a hatch, and a purse.".
    Says "He pushes it across the book to you and takes his hand away quickly, as if it were hot. 'Thank you,' he says. It is the worst thing anybody has said to you in a long time.".
    On discuss { Increase quantity(actor, gold) by 20. Assert bribed(actor). }
  }
  Topic send_to_her with hender "Tell him to row out to the Holm and tell Loveday himself, before the Court" answering confront_hender when knows(actor, hender_did) once {
    Says "He flinches as if you had struck him. 'I can't.' He puts the purse back in the drawer, slowly. 'I can't look at her.' But he does not say no again; he sits looking at the closed book, and you leave him there.".
    On discuss { Assert toldToConfess(actor). }
  }
  Topic threaten_court with hender "Tell him you will say it at the Court" answering confront_hender when knows(actor, hender_did) once {
    Says "'Say it, then.' He puts the purse back in the drawer. 'You're a stranger off the coast road. Skeel will look at you, and then at the Wreck-House full of grain, and then at me.' He opens the book again. 'And it will believe whatever keeps it fed. You know that. I know it better than anybody.'".
  }
  // Sent, he goes: on the third morning, in his own boat, to the Holm; and comes back to sit the Court a different man.
  Rule hender_rows when toldToConfess(party) and thirdDay() and hour(clock) >= 8 and not henderConfessed(hender) and not henderGone(hender) { Assert henderConfessed(hender). Assert confessedAlone(hender). }
  Relation confessedAlone(group).
  Rule hender_rows_told when confessedAlone(hender) and within(party, skeel) and not toldRowed(party) says "Word goes along Fore Street at mid-morning: the Reeve was seen at first light rowing himself out to the Holm, alone, in his black coat, and came back an hour later and went into the church and has not come out." { Assert toldRowed(party). }
  Relation toldRowed(group).
  Observe church_hender at church when henderConfessed(hender) and not courtOver(reach) and at(hender, church) "Hender Brask is sitting in the front pew under the hanging ships, not praying, only sitting, with his hat on his knees.".
  Rule hender_sits_church when henderConfessed(hender) and not courtSitting() and not courtOver(reach) and not at(hender, church) { Retract at(hender, wreck_house). Retract at(hender, reeve_parlour). Assert at(hender, church). }

  // ── The Wreck Court ───────────────────────────────────────────────────────────────────────────────────────────────
  // Four o'clock on the third day, on the flood, in the net-loft: the Reeve at a table, the town on the benches, and
  // three matters in order. Nobody votes. The Reeve says the words, in front of whoever is in the room.
  Query courtSitting() means occasionBegun(court) and not occasionOver(court).
  Query courtBegun(p: place) means occasionBegun(court).
  Relation courtDone(place).
  Query courtOver(p: place) means courtDone(reach).
  Relation livingShown(place). Relation wreckDeclared(place). Relation notWreck(place). Relation pilotsAgreed(place).
  Relation lovedayOff(place). Relation lovedayKept(place). Relation attended(group).
  Query cargoToOwners(p: place) means notWreck(reach).
  Rule court_gathers when thirdDay() and hour(clock) >= 15 and not occasionBegun(court) and not courtDone(reach) {
    Retract at(hender, church). Retract at(hender, wreck_house). Retract at(hender, reeve_parlour). Assert at(hender, net_loft).
    Retract at(cawse, wreck_house). Assert at(cawse, net_loft). Retract at(hosken, church). Assert at(hosken, net_loft).
    Retract at(jago, taproom). Assert at(jago, net_loft). }
  Rule court_constance when thirdDay() and hour(clock) >= 15 and constanceCome(constance) and not occasionBegun(court) and not at(constance, net_loft) { Retract at(constance, taproom). Retract at(constance, acre). Retract at(constance, quay). Assert at(constance, net_loft). }
  Rule court_loveday when thirdDay() and hour(clock) >= 15 and not occasionBegun(court) and not following(loveday, party) and not at(loveday, net_loft) { Retract at(loveday, lamp_room). Assert at(loveday, net_loft). }
  Rule court_kerensa when thirdDay() and hour(clock) >= 15 and not occasionBegun(court) and not travelsWith(kerensa, party) and not at(kerensa, net_loft) { Retract at(kerensa, quay). Retract at(kerensa, reeve_parlour). Assert at(kerensa, net_loft). }
  Observe loft_court at net_loft when courtSitting() "The net-loft is packed to the walls: Skeel on the benches in its Sunday black, men standing at the back with their hats in their hands, children on the beams. The air smells of tar and wet wool. At the far end Hender Brask sits at the table with the book open in front of him and the charter board, brought from the church, propped against the wall behind him, shining. Loveday Kitto sits alone on a stool in front of the table, in her good shawl, with her hands in her lap.".
  Observe loft_constance at net_loft as feature when courtSitting() and at(constance, net_loft) "Constance Ferrar stands at the side, by the window, with her ledger, very upright. Nobody stands near her.".
  Observe loft_ewan at net_loft as feature when courtSitting() and at(ewan, net_loft) "By the stair-head, with his arms folded and a sealing-club in his belt, stands Ewan Marrock, and every head in the loft has turned to look at him, and at the boy with the bandaged head beside him.".
  Rule attending when courtSitting() and at(party, net_loft) and not attended(party) { Assert attended(party). }
  Occasion court "the Wreck Court" at net_loft when thirdDay() and hour(clock) >= 16 {
    Matter call "Hender Brask stands. 'The Wreck Court of the Gannet Reach,' he says, 'under the Admiral's charter. The ship Constancy, Ferrar's, struck on Scarth Bank on the night of Saturday last, in fair weather. If any man here knows of a living thing that came ashore of her, neither man nor dog nor cat, let him say so now.' He waits, with the pen in his hand, and the loft is so quiet you can hear the tide coming in under the floor." for 20 minutes until decided(call).
    Matter lantern "'The second matter,' says the Reeve, without looking up. 'The Holm Lantern was dark on the night of the wreck. Its keeper, Loveday Kitto, asks no excuse.' Loveday sits very straight on her stool." for 20 minutes until decided(lantern).
    Matter winter "'The last matter,' says the Reeve, and his voice is not quite steady, 'is the winter.' He looks at the book." for 20 minutes until decided(winter).
    Closes "The Reeve closes the book. The loft empties down the stair in silence, onto a quay where the tide is in and the boats are knocking gently against the wall.".
  }
  Relation decided(matter).

  // The first matter: a living thing in the loft, brought forward.
  Action show_dog(actor: group, site: place) "Bring Admiral forward to the Reeve's table" {
    Requires able(actor) and at(actor, site) and at(actor, net_loft) and matterOpen(call) and at(admiral, net_loft) and not dogDrowned(admiral).
    Time 1 minute.
    On success { Assert livingShown(reach). Assert decided(call). Assert notWreck(reach). }
    Result "You walk up the loft between the benches with the black dog at your heel, and the whole of Skeel watches him go by, and he goes up to the Reeve's table and puts his front paws on it, on the open book, and looks into Hender Brask's face, and wags. Somewhere at the back a man begins to laugh, the helpless kind, and then a woman, and then the children on the beams, and Mother Jago puts her cloth over her face. 'His name's Admiral,' you say, and that does it: the loft roars. Hender Brask does not laugh. He looks at the dog. Then he dips his pen and writes, in the voice he uses for numbers: 'A dog came ashore of her, living. The Constancy is no wreck.' The laughter stops as if it had been cut.".
  }
  Action show_nye(actor: group, site: place) "Bring Nye Gallow forward to the Reeve's table" {
    Requires able(actor) and at(actor, site) and at(actor, net_loft) and matterOpen(call) and at(nye, net_loft).
    Time 1 minute.
    On success { Assert livingShown(reach). Assert decided(call). Assert notWreck(reach). Assert nyeFaced(nye). }
    Result "The boy walks up the loft to the table on his own, with his bandage and his blanket and Ewan Marrock's knife in his belt, and the whole of Skeel draws its breath in at once. He stands in front of the Reeve. 'Nye Gallow,' he says. 'Ship's boy, Constancy. I came ashore.' And then he does the thing he said he wanted to do: he looks at Hender Brask's face. Hender Brask looks back at him. Nobody in the loft can see what passes between them; you can, a little. The Reeve dips his pen. 'A boy came ashore of her, living,' he says, 'and the Constancy is no wreck,' and his hand shakes so that the ink runs.".
  }
  Relation nyeFaced(group).
  // Each matter is given a watch for whoever has something to say; then the Reeve says the words.
  Measure openedAt(matter). Initially Set openedAt(call) to 0. Initially Set openedAt(lantern) to 0. Initially Set openedAt(winter) to 0.
  Rule call_opened when matterOpen(call) and openedAt(call) == 0 { Set openedAt(call) to watch(clock) + 1. }
  Rule lantern_opened when matterOpen(lantern) and openedAt(lantern) == 0 { Set openedAt(lantern) to watch(clock) + 1. }
  Rule winter_opened when matterOpen(winter) and openedAt(winter) == 0 { Set openedAt(winter) to watch(clock) + 1. }
  Query heard(m: matter) means matterOpen(m) and openedAt(m) > 0 and watch(clock) >= openedAt(m).
  Rule call_wreck when heard(call) and not livingShown(reach) and not henderConfessed(hender) and not wreckDeclared(reach) and not decided(call) says "'No living thing came ashore of her,' says the Reeve, 'and the Constancy is wreck: two parts to Skeel, one to the Lord Admiral.' He writes it. The loft lets out its breath, all at once, like a sail emptying." { Assert wreckDeclared(reach). Assert decided(call). }
  // Confessed, he will not say wreck.
  Rule call_confessed at net_loft when matterOpen(call) and henderConfessed(hender) and not decided(call) says "He stops. He puts the pen down. 'No,' he says. 'I will not say it.' The loft stirs. He stands up, holding on to the table. 'She is no wreck. I made her one. I put the sea in Loveday Kitto's oil and I hung a light in the Pulpit beside my father's ring, so that she would steer for it, and she did. I did it for you. You will none of you thank me for it, and you are right.' He turns the book round on the table so that they can read it. 'There was a boy alive on a hatch, after. I saw him. The Constancy is no wreck, and her cargo is her owners', and I am done.' And he sits down, and nobody in the loft moves at all." { Assert decided(call). Assert notWreck(reach). }

  // The second matter: the Lantern. Spoken for, or let go.
  Action speak_loveday(actor: group, site: place) "Tell the Court the Lantern's oil was cut with seawater" {
    Requires able(actor) and at(actor, site) and at(actor, net_loft) and matterOpen(lantern) and knows(actor, oil_watered) and not lovedayKept(reach).
    Time 1 minute.
    On success { Assert lovedayKept(reach). Assert decided(lantern). }
    Result "You tell them. The cloudy oil, the beads that will not mix, the salt on your tongue, the barrel filled on the Saturday. The loft listens in a different silence from before: a town hearing something it has half known. Loveday Kitto does not turn round. Hender Brask writes nothing at all. Then Jinny Rowse, at the back, says quite loudly, 'Then she never slept, did she,' and somebody else says 'No,' and the Reeve, not looking up, says: 'The keeper is not at fault. She keeps the Lantern.' Jack Cawse looks at his boots.".
  }
  Action ask_nye_face(actor: group, site: place) "Ask Nye Gallow whether the man with the lantern is in this room" {
    Requires able(actor) and at(actor, site) and at(actor, net_loft) and matterOpen(lantern) and at(nye, net_loft) and knows(actor, nye_saw) and not henderConfessed(hender) and not henderExposed(hender).
    Time 1 minute.
    On success { Assert henderExposed(hender). Assert lovedayKept(reach). Assert decided(lantern). }
    Result "The boy does not answer you. He has not stopped looking at the Reeve since he came up the stair. He lifts his arm and points, across the table, and his voice when it comes is high and cracked and carries to the back wall. 'Him. He held his lamp up and he saw me on the hatch and he went away.' For a moment nothing at all happens. Then Loveday Kitto, on her stool, turns her head and looks at Hender Brask, and he looks at her, and you see his ears go red, slowly, from the lobes up, like a boy's; and that is answer enough for everyone in Skeel who ever knew him as a boy, which is everyone.".
  }
  // She said: don't ask me. Asked, in front of the loft, she may; or she may go down the stair and not come back.
  Relation kerensaSpoke(group). Relation kerensaWalked(group).
  Action ask_kerensa_loft(actor: group, site: place) "Ask Kerensa Brask, in front of the loft, what she saw on the night of the wreck" {
    Grave "She asked you not to. If she will not, she will not forgive you for asking.".
    Speaker kerensa.
    Requires able(actor) and at(actor, site) and at(actor, net_loft) and matterOpen(lantern) and at(kerensa, net_loft) and knows(actor, kerensa_saw)
      and not henderConfessed(hender) and not henderExposed(hender) and not kerensaWalked(actor).
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert kerensaSpoke(actor). Assert henderExposed(hender). Assert lovedayKept(reach). Assert decided(lantern). }
    On failure { Assert kerensaWalked(actor). Retract willing(kerensa, actor). Set kerensaTrust(kerensa) to 0. }
    Result "She does not stand up at once. She looks at Loveday Kitto on her stool, being turned off for forty-one years in front of the whole of Skeel. Then she stands, and the bench creaks, and the loft turns round. 'He came in at three,' she says, to the far wall, not to her father. 'Wet to here. Red clay on his boots, Craigs clay. He burned his good coat in the copper before it was light.' Her voice goes. She gets it back. 'Loveday never slept. Ask him where he was.' Nobody asks him. Nobody has to. Hender Brask is looking at his daughter as if he has never seen her before, and perhaps he has not.".
    Otherwise "She looks at you across the loft, white, and shakes her head once. Then she gets up and goes down the stair, and you hear her feet on the quay, going toward the slip where the blue gig is.".
  }
  Rule lantern_asks at net_loft when matterOpen(lantern) and not henderConfessed(hender) and not lanternAsked(reach) says "'I shall ask the Court to relieve her of the keeping, with thanks for forty-one years, and give the Lantern to John Cawse.' Big Jack Cawse goes red to the ears." { Assert lanternAsked(reach). }
  Relation lanternAsked(place).
  // A ship brought on by a false light was never the sea's to give: older than the charter, and Hender knows it.
  Rule false_light_voids at net_loft when henderExposed(hender) and wreckDeclared(reach) says "Hender Brask draws his pen through a line in the book, slowly, the whole width of the page. 'A ship brought onto the sands by a false light is no wreck,' he says, to the book. 'That is older than the charter. The Constancy's cargo is her owners'.' He does not look up again." { Retract wreckDeclared(reach). Assert notWreck(reach). }
  Rule lantern_confessed at net_loft when matterOpen(lantern) and henderConfessed(hender) and not decided(lantern) says "'The keeper is not at fault,' the Reeve says, without lifting his head. 'She keeps the Lantern, as long as she likes.' Loveday Kitto folds her hands in her lap, and does not turn round." { Assert lovedayKept(reach). Assert decided(lantern). }
  Rule lantern_off when heard(lantern) and not lovedayKept(reach) and not lovedayOff(reach) and not decided(lantern) says "'The keeper is relieved,' says the Reeve, 'with the thanks of the Reach.' Loveday Kitto gets up off her stool and goes down the stair without looking at anybody, and Jack Cawse does not look at her either." { Assert lovedayOff(reach). Assert decided(lantern). }

  // The third matter: the winter. What a ship that is no wreck leaves Skeel; and what might be done instead.
  Rule winter_wreck at net_loft when matterOpen(winter) and wreckDeclared(reach) and not decided(winter) says "He reads out the shares, house by house, two parts in three, and Skeel sits and listens to it like a congregation to a blessing. The grain will see them to the spring. The Admiral's third will see to the factor. 'The Admiral's third,' he says at the end, 'is in my gift, and I give a stranger's portion from it to the strangers who worked her,' and looks at you." { Assert decided(winter). }
  Rule winter_bare at net_loft when heard(winter) and notWreck(reach) and not pilotsAgreed(reach) and not decided(winter) and not pilotsPossible() says "There is nothing to say about the winter, and nobody says it. Constance Ferrar, by the window, opens her ledger and closes it again. On the benches people are looking at their hands." { Assert decided(winter). }
  Relation portioned(group).
  Rule stranger_portion at net_loft when wreckDeclared(reach) and decided(winter) and at(party, net_loft) and (salvaged(party) or dogDeal(party)) and not portioned(party) says "Jack Cawse comes along the bench to you with a little bag, and puts it in your hand without looking at you: the stranger's portion. Six coin." { Assert portioned(party). Increase quantity(party, gold) by 6. }
  Query pilotsPossible() means rutterWritten(reach) and knows(party, kerensa_sounds) and constanceCome(constance) and at(constance, net_loft) and at(kerensa, net_loft) or rutterWritten(reach) and knows(party, kerensa_sounds) and constanceCome(constance) and at(constance, net_loft) and travelsWith(kerensa, party).
  Action propose_pilots(actor: group, site: place) "Put the Rutter on the table, and ask Kerensa Brask to say what it is for" {
    Requires able(actor) and at(actor, site) and at(actor, net_loft) and matterOpen(winter) and notWreck(reach) and pilotsPossible() and carries(actor, rutter) and not pilotsAgreed(reach).
    Time 1 minute.
    On success { Assert pilotsAgreed(reach). Assert decided(winter). }
    Result "You lay the Rutter on the Reeve's table, open at the last page: PULPIT OVER THE HOLM. Kerensa Brask stands up on her bench before you have said her name, red to the hair, and says it, all of it, too fast and then slower, to the whole town: Jacob's gig, two summers on the bar, Malachy alive on Inish, the channel sounded cast by cast; a station reopened; ships brought up the Reach for a fee instead of onto it for nothing. 'We know this water better than anyone alive,' she says. 'We've spent forty years learning where ships die in it. We could learn where they don't.' Then she turns, shaking, to Constance Ferrar by the window. 'Ferrar's ships come into the Reach, don't they. Every year.' Constance Ferrar looks at the girl, and at the Rutter, and at the town on its benches, and at her ledger; and you watch her do a sum. 'Three years' pilotage on every Ferrar hull into the Reach,' she says slowly. 'Paid in advance. In grain. From the Constancy's hold.' She looks at Hender Brask. 'I am told that is a very great deal of grain.' He looks at the girl on the bench, who is his daughter, and who is not looking at him. 'It is,' he says.".
  }
  Rule winter_pilots_lost at net_loft when heard(winter) and notWreck(reach) and pilotsPossible() and not carries(party, rutter) and not decided(winter) and not pilotsAgreed(reach) says "Kerensa Brask half rises from her bench, and looks round the loft for something, and does not find it, and sits down again." { }
  Relation graceGrain(place).
  Action ask_constance_grain(actor: group, site: place) "Ask Constance Ferrar to leave Skeel something of the grain" {
    Speaker constance.
    Requires able(actor) and at(actor, site) and at(actor, net_loft) and matterOpen(winter) and notWreck(reach) and not pilotsAgreed(reach) and at(constance, net_loft) and not graceGrain(reach) and not asked(constance, actor) and constanceMoved(constance).
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert graceGrain(reach). Assert decided(winter). Assert asked(constance, actor). }
    On failure { Assert asked(constance, actor). Assert decided(winter). }
    Result "She looks at you a long time, and then at the benches, and then down at her ledger, and opens it, and does a sum in the margin with a pencil, slowly, and crosses it out, and does it again. 'One part in eight,' she says. 'Left in the Wreck-House. Not as wreck. As a debt Ferrar's owes the Strangers' Acre, for the graves that were dug ready.' She closes the ledger. 'Father will think I have gone mad. Tell him I had help.'".
    Otherwise "She does not look up from the ledger. 'They dug eleven graves before they knew whether there was anything to put in them,' she says. 'No.'".
  }
  Action ask_constance_grain_cold(actor: group, site: place) "Ask Constance Ferrar to leave Skeel something of the grain" {
    Speaker constance.
    Requires able(actor) and at(actor, site) and at(actor, net_loft) and matterOpen(winter) and notWreck(reach) and not pilotsAgreed(reach) and at(constance, net_loft) and not graceGrain(reach) and not asked(constance, actor) and not constanceMoved(constance).
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert graceGrain(reach). Assert decided(winter). Assert asked(constance, actor). }
    On failure { Assert asked(constance, actor). Assert decided(winter). }
    Result "She looks at you a long time, and then at the benches, and then down at her ledger, and opens it, and does a sum in the margin with a pencil, slowly, and crosses it out, and does it again. 'One part in eight,' she says. 'Left in the Wreck-House. Not as wreck. As a debt Ferrar's owes the Strangers' Acre, for the graves that were dug ready.' She closes the ledger. 'Father will think I have gone mad. Tell him I had help.'".
    Otherwise "She does not look up from the ledger. 'They dug eleven graves before they knew whether there was anything to put in them,' she says. 'No.'".
  }
  Relation asked(group, group).
  Rule court_closes when occasionOver(court) and not courtDone(reach) { Assert courtDone(reach). }
  Relation missedCourt(group).
  Rule court_missed_by when courtDone(reach) and not attended(party) and not within(party, skeel) and not missedCourt(party) and not courtNoted(party) { Assert missedCourt(party). }
  Rule court_noted when courtDone(reach) and not courtNoted(party) { Assert courtNoted(party). }
  Relation courtNoted(group).
  Rule court_missed when thirdDay() and hour(clock) >= 18 and not occasionBegun(court) and not courtDone(reach) { Assert courtDone(reach). Assert wreckDeclared(reach). Assert lovedayOff(reach). }
  Rule after_wreck_default when courtDone(reach) and not wreckDeclared(reach) and not notWreck(reach) { Assert wreckDeclared(reach). }
  Rule after_lantern_default when courtDone(reach) and not lovedayKept(reach) and not lovedayOff(reach) { Assert lovedayOff(reach). }
}

data/adventures/skeel/craigs.kyr:
Module skeel "Fair Weather" {
  // ── The Craigs ────────────────────────────────────────────────────────────────────────────────────────────────────
  // The cliffs of the south arm of the Reach, white with gannets. The egg-climbers of the Penhallow family camp on the
  // top in the season and go down the face on fixed ropes. High on the seaward end is a notch in the skyline, the
  // Pulpit: from the sea it is a mark, and once it was a light.
  Observe cliffroad_scene at cliff_road when true "The cliff road goes round the head of the Reach through gorse and thrift, with the sea below on your right hand, for miles. Ahead the land rises into a long ridge of cliffs, the Craigs, and the noise of them comes to you before anything else: tens of thousands of birds, all talking at once.".
  Observe camp_scene at clifftop when true "A camp on the turf at the top of the Craigs: three tents of old sailcloth, a fire-pit, a cart with the shafts up, and a row of iron stakes driven into the cliff edge with ropes going over and down. The noise of the gannets comes up from below like weather. Baskets of eggs, greenish-white and as big as a fist, stand in rows in the grass, and there is a smell of guano and woodsmoke and the sea.".
  Observe camp_pulpit at clifftop as feature when true "Along the edge to the west, where the cliff steps out highest over the sea, is a notch in the rock like a window: the Pulpit. You can see the ledges below it, and nobody on them.".
  Observe foot_scene_c at craigs_foot when true "The foot of the Craigs: a beach of great rounded boulders under a wall of rock that goes up and up, streaked white. The birds wheel over you and the noise is enormous. A goat path goes up the face in zigzags, and higher up, ropes hang down the cliff from somewhere above.".
  Observe ledges_scene at ledges when true "The gannet ledges: you are standing on a shelf of rock a yard wide, halfway up the Craigs, with the sea two hundred feet below and the birds all round you, close enough to touch. Gannets: big, white, with butter-yellow heads and pale murderous eyes, sitting on their nests a beak's length apart and stabbing at each other and at you. The ledge goes on westward round a buttress, and above, the face goes up to a notch in the sky.".
  Observe pulpit_scene at pulpit when true "The Pulpit: a niche in the very top of the Craigs, open to the sea, with room in it for two people to stand. The wind comes straight through it. Below, the whole Reach; to the north, across nine miles, Skeel on its headland; and directly between, out on the water, the Holm and its tower, so exactly in line with you that they could have been put there with a rule.".
  Observe pulpit_line at pulpit as sign when knows(party, leading_mark) "The Pulpit over the Holm: this is the leading mark. From here you can see the line a ship must hold up the channel, and, just to the east of it, the pale hump of Scarth Bank with the wreck on it.".

  Thing ring_hook "the iron in the Pulpit wall" at pulpit {
    State fixed "Above head height in the back of the niche, cut into the rock, two letters, J.B., worn nearly smooth; beneath them an iron ring rusted to a brown stain. And beside the ring, driven into a crack in the rock, an iron hook, new, bright still where the hammer struck it.".
  }
  Initially Assert state(ring_hook, fixed).
  Hazard edge_wind "The wind on the cliff edge" means "Deal (1d8) physical damage to ally unless dexterity save against (13).".
  Thing edge_gusts "the wind along the edge" on edge_scramble is scenery {
    State gusting dangerous "The way out to the Pulpit along the cliff edge is a sheep-track a foot wide over two hundred feet of air, and the wind comes up the face in gusts that lift your coat.".
    State lulled "The wind along the edge has dropped for a moment.".
    Hurts with edge_wind when gusting then lulled.
  }
  Initially Assert state(edge_gusts, gusting).
  // It is only ever a lull: the wind comes back for the next who goes along the edge.
  Rule gusts_return when state(edge_gusts, lulled) and not enRoute(party, edge_scramble) { Assert state(edge_gusts, gusting). }
  Observe hook_looked near ring_hook when tried(ring_hook, looking) "The new hook has been driven into the crack this month: the rock-dust is still pale in the crack round it. On the rock under it, a fan of tallow drips, white, from a lantern hung there for some hours. On the hook itself, caught in a burr of the iron, a scrap of scorched horn: a pane from a horn lantern, the kind every boat in Skeel carries. Whoever hung it knew to hang it beside J.B.'s ring, where the old pilots' lamp hung." teaches hook_found.
  Discovery hook_found "In the Pulpit, beside the rusted ring where Jacob Brask hung the pilots' lamp, someone drove a new iron hook this month, and hung a horn lantern on it for some hours: there is tallow under it, and a scrap of scorched horn.".

  // ── The Penhallows ────────────────────────────────────────────────────────────────────────────────────────────────
  Person ebrel "Ebrel Penhallow" at clifftop {
    Role "who leads the egg-climbers". Ancestry human. Calling warrior. Level 2. Peaceable. Pronouns she. Manner jovial.
    Greets "A broad, weathered woman with a rope coiled over her shoulder and her sleeves rolled up to show forearms like a man's thighs, eating an egg raw out of the shell. 'You came round by the road or over the sands?' she says. 'Either way you're a long way from anywhere. Sit. Have an egg. Mind the birds, they've no manners.'".
    Greets again "Ebrel Penhallow waves an egg at you.".
  }
  Person piran "Piran Penhallow" at clifftop {
    Role "an egg-climber's son, fifteen". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "A thin boy with his hair in his eyes, sitting at the edge of the cliff with his legs over it, looking west along the face toward the Pulpit. He looks round at you, and back.".
    Greets again "Piran looks round, and nods, and looks back at the Pulpit.".
    Joins "Piran is on his feet before you have finished asking.".
  }
  Topic ebrel_craigs with ebrel "Ask Ebrel Penhallow about the egg-climbing" when true once {
    Says "'Gannets lay one egg.' She holds one up. 'You take the first, and she lays another, and you leave her that. Twenty days in the spring, three hundred eggs a day, pickled, salted, smoked, sold up and down the coast. The Reeve gives the licence, and takes a penny in the shilling.' She cracks the egg on her knee. 'My father's father climbed these, and his. My man climbed them.' A pause. 'He fell off the Pulpit eight years ago, reaching for a nest he didn't need. So now I climb them.'".
    On discuss { Assert knows(actor, piran_father). }
  }
  Discovery piran_father "Ebrel Penhallow's husband, Piran's father, fell from the Pulpit eight years ago. She has forbidden Piran the Pulpit face.".
  Topic ebrel_light with ebrel "Ask Ebrel Penhallow about the light on the Craigs" when knows(actor, craigs_light) once {
    Says "She stops eating. 'Piran saw it. He came in white and said it was his father's ghost, up in the Pulpit with a lamp.' She throws the shell over the edge. 'I told him to hush. I told him there's no ghosts, and he's to say nothing to nobody.' She looks at you straight. 'You want to know why? Because the only folk who go up the Pulpit are climbers, and the climbing's on the Reeve's licence, and I've three children and an old mother. That's why.' She wipes her mouth. 'He's never forgiven me. Talk to him if you like. He talks to strangers. He doesn't talk to me.'".
  }
  Observe piran_turned at clifftop when piranHatesYou(piran) and at(piran, clifftop) "Piran sits at the far end of the camp, as far from you as the cliff allows, with his back to you.".
  Topic piran_ghost with piran "Ask Piran what he saw on the night of the wreck" when true once {
    Says "He does not look round. 'A light. In the Pulpit. I was out on the edge here, I come out here at night, Mam doesn't know. And there was a light in the Pulpit where there's never anything, a lamp, hung up, and a man beside it, all dark. I thought it was my da.' He swallows. 'And then the ship hit, out on the sand, I heard it, like a door slammed a mile off. And the man put his hand over the lamp. And it was dark.' Now he looks at you. 'Ghosts don't put their hands over lamps. Do they.'".
    On discuss { Assert knows(actor, craigs_light). Assert knows(actor, piran_saw). }
  }
  Discovery piran_saw "Piran Penhallow saw a man in the Pulpit on the night of the wreck, beside a hung lamp; when the ship struck, the man covered it with his hand.".
  Topic piran_plan with piran "Ask Piran what he means to do" when knows(actor, piran_saw) and not piranHatesYou(piran) once {
    Says "'Go up.' He says it quite calmly. 'Tomorrow night, when they're all at the Supper and drunk. Up the fixed rope to the ledges, and up the face. I've done the face in my head every night since I was seven. I'll see what's up there.' He looks at you. 'If you tell Mam, I'll go tonight instead.'".
    On discuss { Assert piranPlans(piran). }
  }
  Relation piranPlans(group). Relation piranStopped(group). Relation piranWaits(group). Relation piranUp(group). Relation piranFell(group).
  Topic tell_ebrel with ebrel "Tell Ebrel Penhallow that Piran means to climb the Pulpit" when piranPlans(piran) and not piranStopped(piran) and not piranUp(piran) and not piranFell(piran) once {
    Says "She goes white under the weather. Then she gets up and walks over to the boy at the cliff edge and takes him by the collar and the seat of his breeches and lifts him back from the edge like a sack, and sets him down in the grass, and holds him there, and does not say anything at all, while the gannets go on shouting over them both. He does not fight her. Over her shoulder he looks at you, once, the way you look at someone you will not forgive.".
    On discuss { Assert piranStopped(piran). Assert piranHatesYou(piran). }
  }
  Relation piranHatesYou(group).
  Action talk_piran(actor: group, site: place) "Ask Piran to let you go up and look instead" {
    Speaker piran.
    Requires able(actor) and at(actor, site) and at(piran, site) and piranPlans(piran) and not piranStopped(piran) and not piranWaits(piran) and not piranUp(piran) and not piranFell(piran).
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert piranWaits(piran). }
    Result "He thinks about it for a long time, pulling grass. 'All right,' he says. 'But you come back and tell me. Everything. Exactly what's there.' He holds out his hand, and you shake it, and his is shaking.".
    Otherwise "'You'd only tell Mam.' He turns back to the Pulpit. 'Tomorrow night.'".
  }
  Topic take_piran with piran "Ask Piran to climb the Pulpit with you, now" when piranPlans(piran) and not piranStopped(piran) and not piranUp(piran) and not piranFell(piran) and not following(piran, actor) once {
    Says "His face goes very bright and then very serious. 'Now?' He gets up. 'Mam's at the far stakes. Come on. I'll show you where the rope is good.'".
    On discuss { Assert following(piran, actor). }
  }
  Rule piran_summit at pulpit when following(piran, party) and at(party, pulpit) and not piranUp(piran) says "Piran comes up into the Pulpit beside you on his hands and knees, and stands, holding the rock, and looks. He looks at the sea, and at the Holm, and at Skeel. Then he looks at the back of the niche, and you watch him find the letters there, and the ring, and the new hook. He puts his hand over the hook and holds it, as if it were warm. 'Somebody,' he says, and stops. 'It wasn't him. It was somebody.' He is quiet. Then, quite differently, like a much younger boy: 'He used to say you could see the whole world from up here. You can, nearly.'" { Assert piranUp(piran). }
  Rule piran_home when piranUp(piran) and following(piran, party) and at(party, clifftop) { Retract following(piran, party). Assert at(piran, clifftop). }
  Observe camp_piran_up at clifftop when piranUp(piran) and at(piran, clifftop) "Ebrel Penhallow has her arm round her son's shoulders at the fire. Somebody has told her where he has been, and she has said everything she had to say about it, at length, and now she is not letting go of him.".
  Rule piran_tells when piranWaits(piran) and knows(party, hook_found) and at(party, clifftop) and at(piran, clifftop) and not piranUp(piran) says "You tell Piran what is in the Pulpit, exactly, as you promised: the letters, the ring, the new hook, the tallow, the horn. He listens with his whole body. At the end he lets out a breath. 'Not a ghost, then,' he says, and you cannot tell whether he is glad or sorry." { Assert piranUp(piran). }
  // Left alone with his plan, he goes up on the night of the Supper, in the dark, and the face has him.
  Rule piran_climbs when piranPlans(piran) and not piranStopped(piran) and not piranWaits(piran) and not piranUp(piran) and not piranFell(piran) and secondDay() and hour(clock) >= 21 { Assert piranFell(piran). Retract following(piran, party). Assert at(piran, ledges). }
  Rule piran_climbs_unasked when not piranPlans(piran) and not piranFell(piran) and not piranUp(piran) and not piranStopped(piran) and thirdDay() and hour(clock) >= 21 { Assert piranFell(piran). Assert at(piran, ledges). }
  Observe piran_fallen at ledges when piranFell(piran) and at(piran, ledges) "Piran Penhallow lies on the ledge against the rock with one leg out in front of him at an angle no leg should make. He fell from the face above, in the dark, and the ledge caught him. He is grey and sweating and very quiet. The gannets have drawn back from him.".
  Rule piran_found when piranFell(piran) and at(piran, ledges) and hour(clock) >= 6 and hour(clock) < 21 and not piranCarried(piran) and dayN(reach) >= 3 { Assert piranCarried(piran). Retract at(piran, ledges). Assert at(piran, clifftop). }
  Relation piranCarried(group).
  Action carry_piran(actor: group, site: place) "Get Piran up the fixed rope to the camp" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ledges) and at(piran, ledges) and piranFell(piran) and not piranCarried(piran).
    Time 6.
    Resolve check(actor, brawn, dc_fair).
    On success { Assert piranCarried(piran). Retract at(piran, ledges). Assert at(piran, clifftop). Assert carriedPiran(actor). }
    Result "You get him up the rope on your back, a yard at a time, with his arms round your neck and his breath in your ear, and at the top Ebrel Penhallow is waiting on her knees at the stake, and takes him off you, and does not say a word, and does not need to.".
    Otherwise "You cannot get him up alone; you go up for help, and Ebrel's crew bring him up in a sling, and Ebrel does not look at you.".
  }
  Relation carriedPiran(group).
  Observe camp_piran_hurt at clifftop when piranFell(piran) and at(piran, clifftop) "Piran lies by the fire with his leg splinted between two oars, and Ebrel sits by him, and the crew go round them quietly.".

  // ── Work on the ropes ─────────────────────────────────────────────────────────────────────────────────────────────
  Measure ropeDay(group). Initially Set ropeDay(party) to 0.
  Relation climbedFor(group).
  Action work_ropes(actor: group, site: place) "Work a shift on the ropes with Ebrel's crew, for eggs" {
    Description "Over the edge on a rope, a basket at your hip, three hundred feet of air under you and a gannet at every handhold.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, clifftop) and at(ebrel, clifftop) and daylight()
      and ropeDay(actor) != dayN(reach).
    Time 18.
    Resolve check(actor, climbing, dc_fair).
    On success { Set ropeDay(actor) to dayN(reach). Assert climbedFor(actor). Give gannet_eggs to actor. Increase quantity(actor, gold) by 2. }
    On failure { Set ropeDay(actor) to dayN(reach). Assert climbedFor(actor). Assert strikes(gannet_beak, actor). }
    Result "You go over the edge on a rope with a basket, and for three hours you are a part of the cliff: swing, foot on the ledge, hand under the warm indignant bird, the egg, the basket, swing. The gannets stab at your knuckles. At the end Ebrel gives you a dozen eggs and two coin and says you climb like a Penhallow, which is the highest thing she knows how to say.".
    Otherwise "Halfway down a gannet goes for your eyes and you let go of the rock with both hands, and swing out over two hundred feet of nothing, and come back against the cliff hard, and hang there. Ebrel's crew haul you up like a sack. 'Next time,' Ebrel says, kindly enough, 'keep one hand on the mountain.'".
  }
  Hazard gannet_beak "A gannet's beak, and the cliff" means "Deal (1d6) physical damage to ally unless dexterity save against (11).".
  Kind gannet_eggs_kind "a dozen gannet eggs" is gear worth 2 weighing 2
    described "Twelve big eggs the colour of skimmed milk, chalky, with a smell of fish about them. Roasted in the ashes they taste of the sea, and of hunger, and are very good.".
  Item gannet_eggs "a dozen gannet eggs" is gannet_eggs_kind at limbo.

  // ── The Gannet Supper ─────────────────────────────────────────────────────────────────────────────────────────────
  // On the second night of every big tide in the season the climbers eat what they have gathered, on the cliff top, and
  // sing; and anybody who has come round by the road or over the sands is fed.
  Query supper() means secondDay() and hour(clock) >= 19 and hour(clock) < 23.
  Observe supper_scene at clifftop when supper() "The Gannet Supper: a fire built up high on the cliff top, and the eggs roasted in the ashes by the basketful, and a pot of something with mutton in it, and a cask from somewhere, and twenty climbers and their families sitting round in the firelight with their faces red on one side and dark on the other. Below in the dark, the birds; out across the Reach, the Lantern on the Holm.".
  Relation supped(group). Relation sang(group).
  Action gannet_supper(actor: group, site: place) "Sit down at the Gannet Supper" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, clifftop) and supper() and not supped(actor).
    Time 6.
    On success { Assert supped(actor). Assert fed(actor). }
    Result "They make room for you without asking, and put an egg in your hand too hot to hold, and somebody pours you something. For an hour nobody talks about the wreck, or the Court, or the winter. Ebrel Penhallow tells the story of the climber who went down for an egg and came up with a mermaid's comb, and everybody has heard it, and everybody laughs at the same place. A child falls asleep against your arm.".
  }
  Relation fed(group).
  Action sing_gigs(actor: group, site: place) "Stand up and sing when the song comes round to you" {
    Speaker ebrel.
    Requires able(actor) and at(actor, site) and at(actor, clifftop) and supper() and supped(actor) and not sang(actor).
    Resolve check(actor, performance, dc_fair).
    On success { Assert sang(actor). Assert climbersLike(actor). Assert knows(actor, gigs_song). }
    On failure { Assert sang(actor). Assert knows(actor, gigs_song). }
    Result "You sing what you know, and they listen, and when you stop they bang the ground with their hands, and Ebrel stands up and sings back to you the climbers' own, the old one, 'The Twelve Gigs', about the pilots racing out to a ship in a gale: the blue gig, the red gig, the green gig and the grey. They all come in on the chorus — 'Pulpit over the Holm, my love, and the Holm over the stern' — and you find you are singing it too.".
    Otherwise "You forget the words halfway, and stand there, and they wait kindly, and then Ebrel takes it up for you with the climbers' own, the old one, 'The Twelve Gigs', and everybody comes in on the chorus — 'Pulpit over the Holm, my love, and the Holm over the stern' — and you are let off.".
  }
  Relation climbersLike(group).
  Discovery gigs_song "The climbers' old song, 'The Twelve Gigs', is about the Reach pilots racing out to a ship in a gale. Its chorus is the pilots' leading mark: 'Pulpit over the Holm, my love, and the Holm over the stern.'".
  Topic ebrel_rope with ebrel "Ask Ebrel Penhallow for the loan of a climbing rope" when climbersLike(actor) or climbedFor(actor) once {
    Says "She throws you a coil from the cart without getting up. 'Bring it back or bring me its price,' she says. 'A Penhallow rope's never been off the Craigs before. Don't shame it.'".
    On discuss { Give penhallow_rope to actor. Assert lends(ebrel, penhallow_rope, actor). }
  }
  Item penhallow_rope "a Penhallow climbing rope" is rope at limbo owned by ebrel.
}

data/adventures/skeel/dog.kyr:
Module skeel "Fair Weather" {
  // ── Admiral ───────────────────────────────────────────────────────────────────────────────────────────────────────
  // The Constancy's dog: a big black curly water-dog, who came ashore swimming the morning after the wreck and has
  // lived on the Strand since, eating wrack and dead fish, wary of everybody. At low water he quarters the sands round
  // the wreck; when the tide comes in he swims out to Seal Skerry, where his boy is. Under the charter he is a living
  // thing come ashore, and he makes the Constancy no wreck.
  Species ship_dog "a ship's dog" like dog temperament wary
    described "A big black curly-coated water-dog, web-footed, bred to go over the side after a dropped line or a man; thin now, with a frayed rope collar.".
  Person admiral "Admiral" at flats {
    Role "a big black curly-coated water-dog, thin, with a frayed rope collar". Species ship_dog. Peaceable. Pronouns he.
    Joins "Admiral falls in at your heel as if he had always walked there.".
    Known as "a black dog" when not knows(party, dog_named).
  }
  Discovery dog_known "A black water-dog has been living on the Strand since the morning after the wreck: the Constancy's dog, come ashore alive. Under the charter a living thing come ashore makes her no wreck. The Reeve has put a shilling on its head, for a sheep-worrier.".
  Discovery dog_named "The black dog on the Strand is called Admiral: it says so on a brass tag on his rope collar, under CONSTANCY.".
  Discovery dog_swims "When the tide comes in, the black dog leaves the Strand and swims west, strongly, toward Seal Skerry.".
  Observe dog_seen near admiral when not following(admiral, party) and not dogPenned(admiral) and onSands(party) "A big black curly dog is trotting along the wrack line a hundred yards off, nose down, ribs showing. When you stop, he stops, and watches you, one forefoot lifted. He has a rope collar. When you take a step toward him he takes two away." teaches dog_known.
  Topic dog_jago with jago "Ask Mother Jago about the black dog on the Strand" when not knows(actor, dog_known) once {
    Says "'Off the Constancy. Swam ashore the morning after, half dead, and won't come to anybody.' She lowers her voice. 'There's a shilling on him at the Wreck-House. For a sheep-worrier, the Reeve says, and there's not a sheep on the Strand.' She looks at you over the cloth. 'A living thing come ashore, you see. Neither man nor dog nor cat.'".
    On discuss { Assert knows(actor, dog_known). }
  }
  // Where he is.
  Relation dogPenned(group). Relation dogHidden(group). Relation dogDrowned(group). Relation dogDealt(group). Relation dogWithNye(group).
  Query dogFree() means not following(admiral, party) and not dogPenned(admiral) and not dogHidden(admiral) and not dogDrowned(admiral) and not dogWithNye(admiral) and not travelsWith(admiral, party).
  Rule dog_to_sands when dogFree() and lowWater() and not at(admiral, flats) { Retract at(admiral, haulout). Assert at(admiral, flats). }
  Rule dog_to_skerry when dogFree() and not lowWater() and not at(admiral, haulout) { Retract at(admiral, flats). Assert at(admiral, haulout). }
  Rule dog_swims_seen when dogFree() and turning() and onSands(party) and not knows(party, dog_swims) says "Out on the sand the black dog lifts his head and looks at the sea coming, and then trots, not toward Skeel or the Holm, but straight out toward the Gut, and into the water, and you watch his black head go away west across the channel, steady, toward Seal Skerry, until you lose it." teaches dog_swims { }
  Observe dog_at_haulout at haulout when at(admiral, haulout) and dogFree() "Among the seals, absurdly, a black dog lies on a rock with his chin on his paws, looking at the bothy.".

  // Winning him: food, thrown, and patience; three times and he will come to a hand.
  Measure dogTrust(group). Initially Set dogTrust(admiral) to 0.
  Measure fedDog(group). Initially Set fedDog(party) to 0.
  Action feed_dog(actor: group, site: place) "Throw the black dog something to eat" {
    Description "From a distance, and then sit down, and look away.".
    Requires able(actor) and company(actor) and at(actor, site) and at(admiral, site) and dogFree() and quantity(actor, rations) >= 1
      and fedDog(actor) != watch(clock).
    Time 2.
    On success { Decrease quantity(actor, rations) by 1. Increase dogTrust(admiral) by 1. Set fedDog(actor) to watch(clock). }
    Result "You throw it as far as you can toward him and sit down on the sand and look at the Holm. After a long time you hear him come, and stop, and come, and eat, fast, the way a starved dog eats, and go away again, but not so far.".
  }
  Action feed_dog_eggs(actor: group, site: place) "Throw the black dog a gannet egg" {
    Requires able(actor) and company(actor) and at(actor, site) and at(admiral, site) and dogFree() and holding(actor, gannet_eggs_kind)
      and fedDog(actor) != watch(clock).
    Time 2.
    On success { Increase dogTrust(admiral) by 2. Set fedDog(actor) to watch(clock). }
    Result "The egg lands and does not break. The dog comes for it, and rolls it with his nose, and breaks it, and eats it shell and all, and then looks at you as if you might be a person after all.".
  }
  Relation readDog(group).
  Action read_dog(actor: group, site: place) "Sit downwind of the black dog, low and still, and let him come to you" {
    Description "The way you would with any frightened animal: no looking, no reaching, all the time in the world.".
    Requires able(actor) and company(actor) and at(actor, site) and at(admiral, site) and dogFree() and not readDog(actor).
    Time 3.
    Resolve check(actor, woodcraft, dc_fair).
    On success { Assert readDog(actor). Increase dogTrust(admiral) by 2. }
    On failure { Assert readDog(actor). }
    Result "You sit down on the sand with the wind in your face and your hands in your lap and look at nothing. It takes half an hour. Then there is a cold nose against the back of your neck, and gone, and back again.".
    Otherwise "You sit, and he watches you sit, and after a while he lies down a long way off, and so do you, and that is all.".
  }
  Observe dog_closer near admiral when dogFree() and dogTrust(admiral) >= 2 and onSands(party) "The black dog lies down twenty feet from you with his chin on his forepaws, watching you, and his tail moves, once, on the sand.".
  Action call_dog(actor: group, site: place) "Hold out your hand to the black dog" {
    Requires able(actor) and company(actor) and at(actor, site) and at(admiral, site) and dogFree() and dogTrust(admiral) >= 3.
    Time 1.
    On success { Assert following(admiral, actor). Assert knows(actor, dog_named). Assert dogFriend(actor). }
    Result "He comes, low, his whole back end going, and puts his head under your hand, and leans on your leg with all his weight, and shakes. On his rope collar there is a brass tag, green with the sea: CONSTANCY, and under it, ADMIRAL. You say his name. He looks up at you as if you had brought him something he had lost.".
  }
  Relation dogFriend(group).
  // Or run him down. He is quick, and frightened, and he will not thank you for it.
  Action catch_dog(actor: group, site: place) "Run the black dog down" {
    Requires able(actor) and company(actor) and at(actor, site) and at(admiral, site) and dogFree() and onSands(actor).
    Resolve check(actor, tumbling, dc_hard).
    On success { Assert following(admiral, actor). Assert knows(actor, dog_named). }
    Result "You run him across the sand in a long loop and he doubles back and you throw yourself on him, and for a moment it is all teeth and sand and wet black fur, and then you have him by the rope collar and he goes limp, trembling, and lets you. CONSTANCY, says the brass tag on the collar. ADMIRAL. He will come with you on the rope. He will not look at you.".
    Otherwise "He is away across the sand before you are halfway to him, and stops two hundred yards off, and watches you, and you have to start again. He has learned something about you.".
  }
  Rule catch_cost when following(admiral, party) and not dogFriend(party) and dogTrust(admiral) > 0 { Set dogTrust(admiral) to 0. }
  Observe dog_with_you near admiral when following(admiral, party) and dogFriend(party) "Admiral walks at your heel with his nose at your hand.".
  Observe dog_with_you_led near admiral when following(admiral, party) and not dogFriend(party) "Admiral comes on the end of the rope, as far from you as the rope allows.".
  Action pet_admiral(actor: group, site: place) "Make much of Admiral" {
    Requires able(actor) and company(actor) and at(actor, site) and at(admiral, site) and (following(admiral, actor) or travelsWith(admiral, actor) or dogHidden(admiral) or dogWithNye(admiral)).
    Time 0.
    Result "You scratch him behind the ears and he groans and leans on you and his eyes close.".
  }

  // ── The hunt ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // On the second morning, at low water, Jack Cawse's brothers go out on the Strand with a net and a club to earn the
  // Reeve's shilling. If the dog is loose, they get him; the Reeve will not have him drowned, when it comes to it, and
  // has him penned in the Wreck-House until after the Court.
  Person lads "the Cawse lads" at limbo {
    Role "three young men with a herring net and their fists". Ancestry human. Calling commoner. Level 1. Numbers 3. Pronouns they.
    Temperament territorial.
    Warns "The three Cawse lads spread out across the sand with their net between them. 'Stand off, stranger,' calls the biggest. 'That's the Reeve's shilling, that dog. You'll not come between a man and his shilling in a bad year.'".
    Comes "The Cawse lads drop the net and come at you with their fists and their boots.".
    Pleads "The Cawse lads back off across the sand with their hands up, bleeding, and go off toward the Slip, shouting what the Reeve will say.".
  }
  Rule lads_out when secondDay() and lowWater() and hour(clock) >= 10 and hour(clock) < 14 and not huntOver(reach) and not at(lads, flats) and dogFree() { Retract at(lads, limbo). Assert at(lads, flats). }
  Relation huntOver(place).
  Observe lads_scene at flats when at(lads, flats) and not huntOver(reach) "Out on the sand three young men are stalking the black dog with a herring net held between them, the way you drive a sheep into a corner, and the dog is running, low, doubling, tiring.".
  Rule lads_catch when at(lads, flats) and dogFree() and hour(clock) >= 12 and not huntOver(reach) says "Out on the Strand there is a shout, and a yelp, and then the sound of a dog that has been caught in a net and is fighting it, which goes on a long time." { Assert huntOver(reach). Assert dogPenned(admiral). Retract at(admiral, flats). Assert at(admiral, wreck_house). Retract at(lads, flats). Assert at(lads, limbo). }
  Rule lads_give_up when at(lads, flats) and not dogFree() and not huntOver(reach) says "The Cawse lads stand about on the sand with their net, and look at the dog at your heel, and at you, and one of them spits, and they go home." { Assert huntOver(reach). Retract at(lads, flats). Assert at(lads, limbo). }
  Rule lads_beaten when at(lads, flats) and not able(lads) and not huntOver(reach) { Assert huntOver(reach). Assert beatLads(party). }
  Relation beatLads(group). Relation ladsMourned(place).
  // Three of the town's sons left on the sand: Skeel does not forgive a stranger that, whatever the dog was worth.
  Rule lads_mourned when beatLads(party) and not ladsMourned(reach) and within(party, skeel) says "Skeel knows. You can see it in the doorways as you pass: the Cawse boys were carried up the Slip on hurdles, and the town has decided what you are. Mother Jago will not serve you. Jinny Rowse looks at the sea when you speak to her." { Assert ladsMourned(reach). Assert refusesService(jago, party). Assert refusesJinny(party). }
  Relation refusesJinny(group).
  Action pay_lads(actor: group, site: place) "Pay the Cawse lads two coin to go home" {
    Speaker lads.
    Requires able(actor) and company(actor) and at(actor, site) and at(lads, site) and not huntOver(reach) and quantity(actor, gold) >= 2.
    Time 1 minute.
    On success { Decrease quantity(actor, gold) by 2. Assert tolerates(lads, actor). Assert huntOver(reach). Retract at(lads, flats). Assert at(lads, limbo). }
    Result "The biggest one looks at the coins, and at his brothers. 'That's twice the Reeve's shilling,' he says, wondering. 'What's a dog to you?' But he takes it, and they roll up the net and go.".
  }
  Observe dog_penned at wreck_house when dogPenned(admiral) and at(admiral, wreck_house) "In a pen of hurdles at the back, among the casks, the black dog lies with his nose through the bars, not moving, watching the door.".
  Thing pen "the hurdle pen" at wreck_house {
    State pen_shut blocking "A pen of hurdles lashed together with cord and a padlocked chain.".
    State pen_open "The pen of hurdles stands open.".
    Change pick_pen "Pick the padlock on the pen" from pen_shut to pen_open needing lockwork.
    Change cut_pen "Cut the cords of the pen" from pen_shut to pen_open needing brawn.
  }
  Initially Assert state(pen, pen_shut).
  Rule dog_freed when dogPenned(admiral) and state(pen, pen_open) and at(party, wreck_house) says "The dog is out of the pen and at your knees before the gate has finished swinging. On his rope collar, a brass tag: CONSTANCY, and under it, ADMIRAL." teaches dog_named { Retract dogPenned(admiral). Assert following(admiral, party). Assert tookDog(party). Assert dogFriend(party). }
  Relation tookDog(group).
  Topic ask_hender_dog with hender "Ask Hender Brask what he will do with the dog in the pen" when dogPenned(admiral) once {
    Says "He does not look up for a long time. 'Keep him,' he says. 'Until after the Court. Then he can go where he likes.' His pen has stopped. 'They wanted me to drown him. I went out to the pen last night with a sack, and he looked at me.' He puts the pen down. 'You can think what you like of me. I could not drown a dog.'".
  }

  // ── The offer taken ───────────────────────────────────────────────────────────────────────────────────────────────
  Action drown_dog(actor: group, site: place) "Drown Admiral in the Gut, for the Reeve's shilling" {
    Grave "He trusts you. He will go into the water with you, and not come out.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gut_lip) and following(admiral, actor) and dogDeal(actor).
    Time 3.
    On success { Retract following(admiral, actor). Assert dogDrowned(admiral). Assert dogDealt(admiral). Retract at(admiral, gut_lip). Assert at(admiral, limbo). Assert drownedDog(actor). }
    Result "It does not take long. That is the worst of it. Afterward you sit on the soft sand at the lip of the Gut with your arms wet to the shoulder, and a shilling owed you at the Wreck-House, and the sea comes over the Strand behind you, and you do not feel it for a while.".
  }
  Relation drownedDog(group). Relation dogLied(group).
  Action lie_dog(actor: group, site: place) "Tell Hender Brask the dog is drowned" {
    Speaker hender.
    Requires able(actor) and at(actor, site) and at(hender, site) and dogDeal(actor) and not dogDrowned(admiral) and not dogLied(actor)
      and (dogHidden(admiral) or dogWithNye(admiral) or following(admiral, actor)) and not at(admiral, site).
    Resolve check(actor, deception, dc_fair).
    On success { Assert dogLied(actor). Assert dogDealt(admiral). Increase quantity(actor, gold) by 1. }
    Result "He looks at your sleeves, which are dry, and then at your face, and you hold it. After a long moment he takes the shilling out of the drawer and lays it on the table, and writes something in the book. 'Thank you,' he says, and you see that he is relieved, and that he is ashamed of being relieved, and that he will not ask.".
    Otherwise "He looks at your sleeves, which are dry. 'No,' he says quietly. 'No, it isn't.' He puts the shilling back in the drawer. 'Keep it out of my sight, then. That is all I ask.'".
  }
  Event dog_shilling at wreck_house when drownedDog(party) and at(party, wreck_house) and at(hender, wreck_house) "Hender Brask looks at your sleeves, which are still stiff with salt, and takes a shilling out of the drawer and lays it on the table, and does not touch your hand when you take it. He writes something in the book. Then he sits looking at what he has written." then { Increase quantity(party, gold) by 1. }
}

data/adventures/skeel/endings.kyr:
Module skeel "Fair Weather" {
  // ── Chapters ──────────────────────────────────────────────────────────────────────────────────────────────────────
  Chapter ch_fair "Fair Weather" when within(party, reach) and firstDay() "There has not been a cloud over the Gannet Reach for a week.".
  Chapter ch_living "Living Things" when secondDay() and hour(clock) >= 6 "The second morning comes up still and bright over the Reach. On the Strand the tide-bell is ringing at the foot of the Slip, and the carts are going out again.".
  Chapter ch_court "The Wreck Court" when thirdDay() and hour(clock) >= 15 "At three the tide turns on the Strand, and in Skeel the shutters go up on the shops, and people put on their black and go down the Drang to the fish cellars, and climb the stair to the net-loft in silence.".
  Chapter ch_ebb "The Third Ebb" when courtDone(reach) and drownedIn(reach) "On the third ebb, in the dark, the Reach gives back what it took.".

  // ── What else is told when the Court rises ────────────────────────────────────────────────────────────────────
  Relation fateTold(entity).
  Entity fate_grace: fact "the grain left". Entity fate_info: fact "the information laid". Entity fate_kerensa: fact "Kerensa".
  Rule fate_grain when courtDone(reach) and graceGrain(reach) and not fateTold(fate_grace) says "One part in eight of the grain stays in the Wreck-House, entered in Constance Ferrar's ledger as a debt of Ferrar and Daughters to the Strangers' Acre. Skeel does not know what to call it. Parson Hosken calls it grace, and is told to stop." { Assert fateTold(fate_grace). }
  Rule fate_info when courtDone(reach) and constanceKnows(constance) and notWreck(reach) and not henderConfessed(hender) and not henderExposed(hender) and not fateTold(fate_info) says "Constance Ferrar does not say anything about the Reeve in the loft. She has her ledger. A month later, in the south, an information is laid before the Admiral's court in her careful hand, and two officers come up the coast road to Skeel in the rain." { Assert fateTold(fate_info). }
  Rule fate_kerensa when courtDone(reach) and kerensaWalked(party) and not fateTold(fate_kerensa) says "Kerensa Brask is not on the packet when it sails. The blue gig is gone from the slip, and nobody saw her take it out." { Assert fateTold(fate_kerensa). Assert kerensaGone(kerensa). Retract at(kerensa, quay). Retract at(kerensa, net_loft). Assert at(kerensa, limbo). }

  // ── Endings ───────────────────────────────────────────────────────────────────────────────────────────────────────
  // Told when Ferrar's packet sails on the fourth evening, the Court a day behind and the third ebb come and gone, so
  // that what the Court decided can be lived in for a night and a day before it is told. The first that holds is the
  // one told. The Reach goes on after it, and the company can stay, or come back.
  Ending pilots "The Pilots" when packetSailed(reach) and pilotsAgreed(reach) "The Constancy's grain goes down to the quay in the carts it came up in, and is weighed into Ferrar's packet, and then, at Constance Ferrar's word, two-thirds of it is weighed out again onto the quay and carried back up the Drang to the Wreck-House: three years' pilotage, paid in advance, on every Ferrar hull into the Reach. The contract is drawn in the net-loft that evening in Constance Ferrar's hand and witnessed by Parson Hosken, who weeps. It names the pilots of the Reach: Kerensa Brask, Jinny Rowse, and, as master of the station on Inish Gall, Malachy Sennen, who has not been asked and will be furious. Skeel does not know how to feel about any of it. It has never been paid to keep a ship whole. In the Admiral that night they argue about it until two, and somebody starts singing 'The Twelve Gigs', and the whole taproom comes in on the chorus, badly, as if they had all known it all their lives and forgotten that they did.".
  Ending godson "The Godson" when packetSailed(reach) and henderConfessed(hender) "Hender Brask gives the Wreck-House keys to Parson Hosken on the quay, and the book, and his black coat, and goes home and sits in his parlour to wait for the Admiral's officers, who will come for him on the next packet. The grain goes down to the quay for Ferrar's. Skeel watches it go, house by house, in the doorways, and says nothing; there is nothing to say to a winter. At dusk Loveday Kitto lights the Lantern on the Holm, as she has fourteen thousand times, and then, because she cannot help it, rows herself across to the quay in Jinny Rowse's punt and walks up the Drang, slowly, in her good shawl, and knocks at the Reeve's door; and he lets her in.".
  Ending exposed "The Light in the Pulpit" when packetSailed(reach) and henderExposed(hender) "They do not hang him in Skeel. They do not know how. Jack Cawse and two of his brothers walk Hender Brask down the Drang between them to the quay, gently, as if he were drunk, and lock him in the fish cellars among the idle presses until the packet sails, and Constance Ferrar writes out the information against him in her ledger on her knee by the light of the cellar lamp, and has him sign it, and he does. The grain goes down to the quay for Ferrar's. In the night somebody chalks on the charter board by the church door, under NEITHER MAN NOR DOG NOR CAT, the words NOR BOY, and in the morning Parson Hosken, after thinking about it for a long time, leaves it there.".
  Ending living "A Living Thing" when packetSailed(reach) and notWreck(reach) "The grain goes down to the quay in the carts it came up in. Skeel stands in its doorways and watches it go, sack by sack, into Ferrar's packet, and does not help, and does not hinder, and nobody throws anything, quite. Constance Ferrar pays the carters double and nobody refuses it. Hender Brask stands at the Wreck-House door with the book under his arm and checks every sack against it, and signs for it, in the voice he uses for numbers; and in the evening goes up to the church with his rag and his dish of oil and works it into the gilt letters of the charter one by one, NEITHER MAN NOR DOG NOR CAT, as he has done every week of his life. It is a hungry winter on the Reach that year. They say in the Admiral that it was a dog that did it, and laugh, and stop laughing.".
  Ending share "A Stranger's Share" when packetSailed(reach) and wreckDeclared(reach) and (drownedDog(party) or bribed(party)) "Skeel eats that winter. The grain is shared out house by house, two parts in three, and the factor is paid at Martinmas out of the Admiral's third, and the salt company does not come. The Constancy's saint goes up on the Reeve's gable beside the Lady with the Lyre, the girl with the open book, CONSTANT AND TRUE. Loveday Kitto sits in a room at the back of the Admiral, by Mother Jago's charity, and does not go out. Jack Cawse keeps the Lantern. On the first black night of the winter it goes out, and he does not notice. In the spring a man in Skeel who drinks too much tells a stranger in the Admiral about the stranger who was here when the Constancy came in, who walked the Strand like a native, and did the Reeve a service, and was paid for it; and the stranger he is telling it to asks what service, and the man looks at his beer and does not say.".
  Ending away "Wreck, While You Were Away" when packetSailed(reach) and wreckDeclared(reach) and missedCourt(party) "You are not in the net-loft when the Reeve says the word, and you hear it afterward, the way you hear news of a place you have left: from a carter on the coast road, cheerfully, as good news. Wreck, the Constancy, two parts to Skeel. They'll eat this winter on the Reach. The old woman who let the Lantern go out has been turned off, poor soul, and the Reeve's man has it now. The carter flicks his whip. Funny thing, he says: there was a dog.".
  Ending wreck "Wreck" when packetSailed(reach) and wreckDeclared(reach) "Skeel eats that winter. The grain is shared out house by house, two parts in three, and the factor is paid at Martinmas out of the Admiral's third, and the salt company does not come. The Constancy's saint goes up on the Reeve's gable beside the Lady with the Lyre: a girl with an open book, CONSTANT AND TRUE. On the Sunday after, the church of Lir Who Gives sings the Wreck Psalm, IF SHIPS MUST FOUNDER, LORD, SEND THEM TO SKEEL, and Hender Brask stands in the front pew and sings it with the rest, every word, and in the evening oils the charter board. Loveday Kitto is gone off the Holm. Jack Cawse keeps the Lantern now, and is proud of it, and the light goes out across the Reach every night in its long gold road, and nobody on a ship coming in from the south could tell the difference.".
}

data/adventures/skeel/holm.kyr:
Module skeel "Fair Weather" {
  // ── Hobb's Holm ───────────────────────────────────────────────────────────────────────────────────────────────────
  // A tidal island a mile out: on foot at low water, by the Patience at high. The Lantern is a squat round tower with a
  // coal-and-oil light in a glazed lamp-room; Loveday Kitto has kept it for forty-one years, and her mother before her.
  Observe holm_scene at holm_shore when true "A hump of turf and grey rock a quarter-mile long, with sheep on it, and the Lantern on its crown: a squat round tower of whitewashed stone, with a glazed lamp-room on top like a lantern on a stick. At the tower's foot, a low cell of older stone half sunk in the turf, its doorway facing the sea. A well with a stone lid. Washing on a line: one woman's.".
  Observe holm_well at holm_shore as feature when true "On the well-lid, scratched deep and old: HOBB. And under it, newer, in chalk, the islanders' joke: SALT SINCE THE WRECK YEAR. The Holm's well went brackish forty years ago, the year the pilots went, and Skeel says the island is ashamed.".
  Observe holm_low at holm_shore as weather when lowWater() "The sands run away from the Holm on every side, shining, and the withies march across them to Skeel.".
  Observe holm_high at holm_shore as weather when not lowWater() "The sea has come round the Holm and stands level with the turf. The sheep have gone up to the tower wall in a huddle, and one of them is eating the washing.".
  Observe foot_scene at tower_foot when true "The tower's one room: a bed, a chair, a table with a Bible of Lir and a teapot on it, a fire of driftwood. Everything is very clean and set exactly where it is, the way things are in a house where someone has learned to find them without looking. A stair goes up round the wall.".
  Observe lamp_scene at lamp_room when true "The lamp-room: glass on every side, salt-dimmed, and in the middle on its iron stand the light, a great brass oil-lamp with eight wicks in a ring and a polished reflector behind them like a sunflower. The whole Reach is round you. To the south, across the water, the black line of the Craigs, and the high notch in them they call the Pulpit.".
  Observe lamp_lit at lamp_room as feature when lanternLit() "The eight wicks burn steady and yellow, and the reflector throws them out across the Reach in a long golden road.".
  Query lanternLit() means hour(clock) >= 19 or hour(clock) < 6.
  Observe holm_lit at holm_shore as sign when lanternLit() "Above you the Lantern burns, and you stand in its light.".
  Observe slip_lantern at slip as sign when lanternLit() "Out on the Reach the Lantern on the Holm is lit, a steady yellow star.".

  Person loveday "Loveday Kitto" at lamp_room {
    Role "who keeps the Holm Lantern". Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Greets "A small old woman in a grey shawl is polishing the great reflector with a rag, slowly, by touch, her face very close to the brass. She turns her head toward you, not quite at you. 'If you're from the Reeve,' she says, 'you can tell him I've polished it. If you're not, you've walked a long way to see an old woman who let a ship go on the bank, and here she is.'".
    Greets again "Loveday Kitto turns her head toward the sound of you. 'Back again,' she says.".
    Joins "Loveday Kitto takes your arm, and holds it, and you go at her pace.".
    Remarks at acre "Loveday Kitto stands a long time at the open graves along the wall, and says the names of the Constancy's men to herself, those she has been told.".
  }
  Discovery loveday_eyes "Loveday Kitto is going blind. She can tell light from dark, and little more; she keeps the Lantern by touch and by habit, and could not see that it had gone out.".
  Discovery oil_watered "The oil in the Lantern's barrel has been cut with seawater: it is cloudy, and when it burns it spits and gutters and goes out. Whoever filled that barrel meant the Lantern to fail.".

  Topic loveday_night with loveday "Ask Loveday Kitto about the night of the wreck" when true once {
    Says "She folds the rag very small. 'I lit at sunset. I've lit at sunset fourteen thousand nights. I trimmed her and I went down and made my tea, and I sat, and I must have slept.' Her hands keep folding. 'When I came up she was out. All eight wicks out, and cold. I don't know how long. I didn't hear the ship. You'd think you'd hear a ship.' She looks toward the glass, not seeing it. 'I've never slept at the Lantern. Never once. I don't know how I came to.'".
    On discuss { Assert knows(actor, wreck_known). Assert askedLoveday(actor). }
  }
  Relation askedLoveday(group).
  Topic loveday_hender with loveday "Ask Loveday Kitto about Hender Brask" when askedLoveday(actor) once {
    Says "Her face softens. 'Hender. I had him from twelve, when Jacob went. He was a quiet boy. He'd sit up here with me all night and never say a word, only watch the light go out across the water.' She smiles. 'He brings my oil every Saturday in his own boat. Forty years. Never once missed.' The smile goes. 'He'll turn me off at the Court. He has to. He came and told me himself, and cried, which I've not seen him do since he was twelve. I told him he must do his duty. He always does.'".
    On discuss { Assert knows(actor, pilot_son). Assert knows(actor, oil_by_hender). }
  }
  Discovery oil_by_hender "Hender Brask brings the Lantern's oil out to the Holm in his own boat every Saturday, and has for forty years. He brought it on the evening of the wreck.".
  Topic loveday_pilots with loveday "Ask Loveday Kitto about the pilots" when askedLoveday(actor) once {
    Says "'Oh, the pilots.' She sits down on the iron step of the lamp-stand. 'Twelve gigs on the Reach when I was a girl, painted all colours, racing out to the ships. Jacob Brask's was blue. He used to say to me, Loveday, keep the Lantern lit and I'll keep the Pulpit, and between us we'll bring them home.' She laughs, a little. 'The leading mark. The Pulpit over the Holm. A ship coming in from the south keeps the notch in the Craigs right over this light, one on top of the other, and comes straight up the channel to Skeel in the dark without touching. Jacob used to light a lamp up on the Pulpit on the black nights, so they'd have both.' She is quiet. 'Nobody's done that in forty years.'".
    On discuss { Assert knows(actor, leading_mark). }
  }
  Discovery leading_mark "The old pilots' leading mark: a ship coming in from the south keeps the Pulpit, the high notch in the Craigs, directly over the Holm Lantern, and comes up the channel to Skeel safely. On black nights Jacob Brask used to hang a lamp on the Pulpit, so a ship would have both lights. A light on the Pulpit with the Holm dark would show a stranger the wrong line: straight onto Scarth Bank.".

  // ── The lamp, kept with her ───────────────────────────────────────────────────────────────────────────────────────
  Relation helpedLight(group).
  Action help_light(actor: group, site: place) "Help Loveday Kitto light the Lantern" {
    Description "Sunset, on the Holm: eight wicks, trimmed and lit, and the reflector turned to the Reach.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lamp_room) and at(loveday, lamp_room)
      and hour(clock) >= 18 and hour(clock) < 21 and not helpedLight(actor).
    Time 3.
    On success { Assert helpedLight(actor). Assert knows(actor, loveday_eyes). }
    Result "She hands you the taper and talks you through it: trim each wick square with the scissors, so; turn it up a hair; light from the sea side round. You do the first two. Then she takes the scissors back to show you the third, and you watch her find the wick with her fingertips, and the scissors with her other hand, and bring them together very slowly, an inch from her face, and miss. She tries again, and finds it. She does not look at you. 'There,' she says. 'Nothing to it.' And you understand that she has not seen the flame of her own Lantern for a long time; that she keeps it by the warmth on her face.".
  }
  Topic loveday_eyes_ask with loveday "Ask Loveday Kitto how long she has not been able to see" when knows(actor, loveday_eyes) and not lovedaySees(loveday) once {
    Says "She sits very still. 'Two winters,' she says at last. 'I can see the sun. I can see the lamp, a little, like a candle through a blanket. I can see the Craigs at sunset, a black line.' Her hands are folded. 'If I'd told anyone, they'd have given the Lantern to Jack Cawse, and he'd have let it go out the first night it rained. I thought: I'll keep it till I can't.' Then, very low: 'And then I couldn't. And eleven men.'".
  }
  Relation keptNight(group).
  Action keep_night(actor: group, site: place) "Sit the night watch in the lamp-room with Loveday Kitto" {
    Description "Trimming the wicks every two hours, and talking, or not.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lamp_room) and at(loveday, lamp_room)
      and (hour(clock) >= 21 or hour(clock) < 2) and not keptNight(actor).
    Time 36.
    On success { Assert keptNight(actor). Assert knows(actor, leading_mark). Assert knows(actor, pilot_son). }
    Result "You keep the Lantern through the night with her. Every two hours you trim the wicks and she tells you how; between, the sea, and the dark, and the light going out across the water in its long road. She tells you about her mother, who kept the Lantern before her, and about the pilots' gigs racing out, and about a boy called Hender who sat up here every night the winter his father drowned and never said a word. She tells you the old leading mark, the Pulpit over the Holm, and you look south across the dark to where the Craigs must be, and see nothing there at all. Toward dawn she falls asleep in her chair with the scissors in her lap, and you trim the wicks yourself, and when she wakes she knows by the warmth that they were done, and says nothing, and pats your hand.".
  }

  // ── The spectacles ────────────────────────────────────────────────────────────────────────────────────────────────
  Relation lovedaySees(group).
  Topic give_specs with loveday "Give Loveday Kitto a pair of spectacles from the Constancy" when holding(actor, specs_kind) and not lovedaySees(loveday) once {
    Says "She turns the tin case over in her hands, and opens it, and feels the spectacles inside, and puts them on, very carefully, hooking them over each ear. Then she is quite still. She looks at her hands. She looks at you, properly, for the first time. She looks out through the salt-dim glass at the whole Reach in the light, and the Craigs, and the Pulpit, and a long time passes. 'Oh,' she says. 'Oh, there it all is.'".
    On discuss { Spend specs_kind from actor. Assert lovedaySees(loveday). }
  }
  Rule loveday_reads at lamp_room when lovedaySees(loveday) and at(loveday, lamp_room) and at(party, lamp_room) and not knows(party, oil_watered) and not lovedayKnowsOil(loveday) says "Then, because she has been a lamp-keeper fifty years and the first thing a lamp-keeper does with her eyes is look at her lamp, she goes to the stand and draws off a cup of oil from the reservoir and holds it up to the window. It is cloudy. At the bottom of the cup there are beads, clear as glass, that will not mix. She tips the cup, and they roll. 'That's water,' she says. 'That's sea in my oil.' She puts the cup down very gently on the iron. 'Somebody put the sea in my oil.'" teaches oil_watered { Assert lovedayKnowsOil(loveday). }
  Relation lovedayKnowsOil(group).

  // ── The cell, and the oil barrel ──────────────────────────────────────────────────────────────────────────────────
  Observe cell_scene at cell when true "The oldest building on the Reach: a beehive of unmortared stone, so low you stoop, with a stone bench along one wall worn hollow by somebody's sitting a very long time ago. Carved over the bench, a fish and a flame. It is the Lantern's store now: a pile of coal, wicks in a box, cans, and a big iron-hooped oil barrel on a trestle with a tap.".
  Thing barrel "the oil barrel" at cell {
    Tries burning.
    State standing "An oil barrel on a trestle, half full, with a brass tap and a tin cup hung on it. Chalked on the head: SAT. — H.B.".
  }
  Initially Assert state(barrel, standing).
  Observe barrel_looked near barrel when tried(barrel, looking) "You draw a cup from the tap and hold it to the doorway. Lamp oil should be clear and yellow as honey. This is cloudy, and at the bottom of the cup, beads, clear as glass, that roll and will not mix. You touch one and taste your finger. Salt." teaches oil_watered.
  Observe barrel_burnt near barrel when tried(barrel, burning) "You wet a wick from the cup and put a flame to it. It catches, and spits, and sputters blue, and burns for the count of twenty, and goes out with a hiss, and will not light again." teaches oil_watered.
  Topic tell_oil with loveday "Tell Loveday Kitto her oil was cut with seawater" when knows(actor, oil_watered) and not lovedayKnowsOil(loveday) once {
    Says "She does not answer at once. Then she gets up, and feels her way down the stair, and you follow, and in the cell she draws a cup and puts her finger in it and touches it to her tongue. She stands there with the cup in her hand. 'Saturday,' she says. 'The barrel's filled Saturday. I lit at sunset Saturday, and she burned an hour, and went out.' She puts the cup back on its hook. 'And I sat downstairs with my tea and thought I'd slept.'".
    On discuss { Assert lovedayKnowsOil(loveday). }
  }
  Topic loveday_who with loveday "Ask Loveday Kitto who filled the barrel" when lovedayKnowsOil(loveday) once {
    Says "'You know who fills it.' She is looking at the chalk on the barrel-head, SAT. — H.B., which she can read now, or has always known by heart. 'Every Saturday for forty years.' Her voice does not change. 'I'll not have you say it. Not you, and not the Court, and not anybody. If it was him, he'll tell me. He never could lie to me. He used to try, when he was twelve, and his ears went red.'".
    On discuss { Assert lovedayResolved(loveday). }
  }
  Relation lovedayResolved(group).
  Topic loveday_come with loveday "Ask Loveday Kitto to come with you to Skeel, to ask him" when lovedayResolved(loveday) and not following(loveday, actor) and not henderConfessed(hender) once {
    Says "She takes off her apron and folds it and puts on her other shawl, the good one. 'I've not been in Skeel since Lir's Day,' she says. 'They'll stare.' She takes your arm. 'Let them.'".
    On discuss { Assert following(loveday, actor). }
  }
}

data/adventures/skeel/inish.kyr:
Module skeel "Fair Weather" {
  // ── Inish Gall ────────────────────────────────────────────────────────────────────────────────────────────────────
  // Beyond the Gut: a low brown island with three stone houses on it, two of them roofless, and a cairn. It was the
  // pilot station. Old Malachy Sennen, the last of the Reach pilots, lives in the third house with a goat.
  Observe inish_scene at inish_strand when true "A strand of shingle under a low brown island. Three stone houses stand above it in a row, facing the sea: two have no roofs, and grass growing in their doorways; the third has a roof of tarred canvas and a goat on it. Drawn up on the shingle, rotting gently, are the bones of boats: long, narrow gigs, six of them, their paint gone to a ghost of blue and red and green.".
  Observe inish_gigs at inish_strand as feature when true "Five gigs, and a gap at the end of the row where a sixth lay: the shingle there is pressed into the shape of a long hull, and two drag-marks run down from it to the sea, grassed over, a summer or two old.".
  Observe beacon_scene at beacon when true "A cairn of stones on the top of Inish, as high as a man, with an iron basket on it full of old tarred wood, ready. From here you see the whole Reach and the open sea, and the bar where the sea breaks at the mouth of the channel, and the channel itself, a darker line in the water, running in toward Skeel past the Holm.".
  Observe pilot_scene at pilot_house when true "One room, crammed: a bed, a stove, nets, a telescope on a tripod at the window, a goat-harness, two hundred books, and on every wall, in chalk and charcoal and paint, the Reach. Channels, banks, depths in fathoms, bearings, marks: drawn and corrected and drawn again over forty years, so that the walls are dark with it, like a cave painted by a man who has never seen anything else.".
  Observe pilot_rutter at pilot_house as feature when not rutterWritten(reach) "On the table under the window, a book in a canvas cover, burned along one edge, its pages stiff and brown. On the cover, in old gilt: THE PILOTS' RUTTER OF THE GANNET REACH.".

  Person malachy "Old Malachy Sennen" at pilot_house {
    Role "the last pilot of the Reach". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Greets "A very old man, very small, very upright, in a blue coat with brass buttons gone green, is looking at you through a telescope from across the room. 'You came over the Sill,' he says, 'or Jinny Rowse brought you. If it was the Sill, you're a fool, and if it was Jinny, you're a fool with three coin less. Sit down. Nobody's come to Inish in a year but the goat.'".
    Greets again "Old Malachy Sennen lowers the telescope. 'You again. Sit.'".
  }
  Topic malachy_pilots with malachy "Ask Malachy Sennen about the pilots" when true once {
    Says "'Twelve gigs.' He holds up both hands and two fingers. 'Twelve crews of six, racing out over the bar to every sail that showed, first aboard got the job. Brought her in up the channel, Pulpit over the Holm, and took her fee, and the Reach lived on it. Eighty years of that.' He lowers the hands. 'Then the old Admiral bought the wreck-right from the crown. He never forbade us. He was cleverer than that. He just let the station's lease run out, and kept the Lantern, and let it be known a ship that came in without a pilot came in at her own risk. And they did. And they struck. And the wreck paid better than the pilotage.' He laughs, a dry small sound. 'In one generation Skeel went from bringing ships in to taking them to pieces. Never noticed it happening. Nobody does.'".
    On discuss { Assert knows(actor, pilots_known). }
  }
  Discovery pilots_known "Forty years ago the Reach lived by piloting: twelve gigs out of Inish Gall brought ships in up the channel for a fee. When the old Lord Admiral bought the wreck-right he let the pilot station's lease lapse, and Skeel turned from piloting ships in to stripping the ones that struck.".
  Topic malachy_tide with malachy "Ask Malachy Sennen to teach you to read the tide" when true once {
    Says "He is delighted. He takes a stick of chalk and goes to the wall. 'Four hours dry at each low water. Low water an hour later every day, and back round with the springs. The Gut runs through the Sill like a mill-race, except the hour either side of dead low, when it stops to think, and that's when a man can wade it, if he's a fool. Your harbour dries when your sands do; so you walk out on the ebb and sail home on the flood, and never the other way about.' He draws as he talks, fast, a tide like a heartbeat. 'And the fifth hour, when the sea comes over the Strand, you are somewhere high, or you are dead. That's all of it. Fifty years to learn it properly. Now go away and do it.'".
    On discuss { Assert knows(actor, tide_known). Assert knows(actor, slack_known). Assert knows(actor, withy_way_known). }
  }
  Discovery slack_known "The Gut runs through the Sill too hard to wade except for the hour either side of dead low water, when it slackens.".
  Topic malachy_jacob with malachy "Ask Malachy Sennen about Jacob Brask" when knows(actor, pilots_known) once {
    Says "He is quiet for a while. 'My partner. The best of us. Blue gig.' He points out of the window at the rotting boats, at the gap at the end of the row. 'She lay there. JACOB, she was called. Somebody took her, two summers back. I never asked who. He could take a ship up the channel on a black night with no Lantern, by the feel of the water and the smell of the Holm sheep. When the station went, he had nothing to do with it all.' He taps his head. 'He drank. He burned the Rutter in the stove one night, roaring, and I pulled it out, half of it. Next week he took his gig out over the bar alone and the sea brought it back without him.' He looks at you. 'His boy's the Reeve now. Hender. Brought up by Loveday Kitto on the Holm. Fine boy. Never set foot on Inish since. I don't blame him.'".
    On discuss { Assert knows(actor, pilot_son). }
  }
  Topic malachy_light with malachy "Tell Malachy Sennen about the light in the Pulpit" when knows(actor, hook_found) or knows(actor, craigs_light) and knows(actor, leading_mark) once {
    Says "He puts the telescope down very carefully, as if it might break. 'In the Pulpit,' he says. 'With the Lantern dark.' He looks at the wall, at the channel drawn there and drawn again, and puts one finger on it, at Scarth Bank. 'A stranger from the south sees one light, high, where the chart says the Holm is, and steers for it. And the line from there to that light goes straight over Scarth.' His finger stays on the bank. 'You'd have to know the mark. You'd have to know where the old lamp hung. You'd have to know it in your bones, the way you know it if your father took you up there on his back when you were five to show you.' He takes his finger away, and sits down, suddenly, an old man. 'There's four people alive who know where the Pulpit lamp hung. I'm one. Loveday's one. Jinny Rowse might be. And Jacob's boy.'".
    On discuss { Assert knows(actor, only_four). }
  }
  Discovery only_four "Only four people alive know where the old pilots' lamp hung in the Pulpit: Old Malachy Sennen, Loveday Kitto, perhaps Jinny Rowse, and Jacob Brask's son Hender.".

  // ── The Rutter ────────────────────────────────────────────────────────────────────────────────────────────────────
  // Malachy's half-burned book of the Reach: its channels, depths, marks and bottoms. What is burned can be sounded
  // again: five passages of it, each to be taken with a lead-line, at the right water, in the right place.
  Topic malachy_rutter with malachy "Ask Malachy Sennen about the burned book" when knows(actor, pilots_known) once {
    Says "'The Rutter.' He lays a hand on it. 'Every depth, every mark, every bottom, every danger on the Reach, sounded and written down by eighty years of pilots. Half of it's ash.' He opens it: the burned edge crumbles. 'The bar's gone. The channel by Scarth Bank's gone. The Sill. The Holm channel. The leading mark itself, the page with the bearing on it, gone.' He shuts it. 'I could write it again, if I had the soundings. I'm too old to take them. You'd want a lead-line, and the tide-hours, and the sense not to drown.' He looks at you sideways. 'Not that anybody needs a Rutter. There's no pilots.'".
    On discuss { Assert rutterAsked(actor). }
  }
  Relation rutterAsked(group).
  Measure soundings(place). Initially Set soundings(reach) to 0.
  Relation sounded(entity).
  Entity snd_scarth: fact "the channel by Scarth Bank". Entity snd_sill: fact "the Sill". Entity snd_holm: fact "the Holm channel".
  Entity snd_mark: fact "the leading mark". Entity snd_bar: fact "the bar".
  Action sound_scarth(actor: group, site: place) "Sound the channel beside Scarth Bank with the lead-line" {
    Description "From the wreck's stern with the sea in, or wading the gully along the bank at low water.".
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, stern) and not lowWater() or at(actor, scarth) and lowWater()) and holding(actor, lead_line) and not sounded(snd_scarth).
    Time 3.
    On success { Assert sounded(snd_scarth). Increase soundings(reach) by 1. }
    Result "You heave the lead into the channel beside the bank and let the line run: two fathoms, three, four and a half by the calico, and the tallow comes up with clean grey sand in it and a fleck of shell. Then you sound along the bank, a cast every few yards, and see where it shoals to nothing under you, and write it all down: here a ship can go; here she cannot.".
  }
  Action sound_sill(actor: group, site: place) "Sound the Sill at slack water with the lead-line" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, sill) and slack() and holding(actor, lead_line) and not sounded(snd_sill).
    Time 2.
    On success { Assert sounded(snd_sill). Increase soundings(reach) by 1. }
    Result "Standing thigh-deep on the Sill in the stopped water, you cast up the Gut and down it. Upstream, nine fathoms and black mud; downstream it shelves away fast over stones. The tallow comes up with a tiny crab in it.".
  }
  Action sound_holm(actor: group, site: place) "Sound the Holm channel from the Holm strand with the lead-line" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, holm_shore) and not lowWater() and holding(actor, lead_line) and not sounded(snd_holm).
    Time 3.
    On success { Assert sounded(snd_holm). Increase soundings(reach) by 1. }
    Result "You walk the Holm's edge and cast into the channel that runs past it toward Skeel: five fathoms, six, steady, a good clean channel with a shell bottom, deep enough for anything. This is the way in. This is what a pilot would bring a ship up.".
  }
  Action sound_mark(actor: group, site: place) "Take the bearing of the leading mark from the Pulpit" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pulpit) and knows(actor, leading_mark) and not sounded(snd_mark).
    Time 2.
    On success { Assert sounded(snd_mark). Increase soundings(reach) by 1. }
    Result "You lay a straight edge along the line from the Pulpit's lip to the Lantern on the Holm, and past it to the church tower in Skeel, and note how the three stand, and what lies either side: the channel to the west, Scarth Bank close to the east. It is not a wide line. You see for yourself how little it would take to bring a ship onto the bank: a light a few yards from where it should be.".
  }
  Kind notebook_kind "a pilot's notebook, very new" is gear worth 0 weighing 0
    described "A small notebook bound in sailcloth, full of soundings in a neat hand: the bar, cast by cast, at every state of the tide, for two summers. On the first page: JACOB'S LINE. K.B.".
  Item kerensa_notes "Kerensa Brask's notebook" is notebook_kind at limbo.
  Topic give_notes with malachy "Give Malachy Sennen Kerensa Brask's soundings of the bar" when carries(actor, kerensa_notes) and not sounded(snd_bar) once {
    Says "He reads the notebook through, every page, his lips moving. Then he reads it again. 'Two summers,' he says. 'Every state of the tide. The bar, cast by cast.' He closes it. 'Jacob's granddaughter.' He wipes his eyes with the back of his hand and is angry about it. 'Jacob's granddaughter, in her grandfather's gig, all alone, sounding the bar for a station that doesn't exist.'".
    On discuss { Assert sounded(snd_bar). Increase soundings(reach) by 1. }
  }
  Relation rutterWritten(place).
  Action write_rutter(actor: group, site: place) "Sit with Malachy Sennen and write the Rutter up again" {
    Description "Two hours at his table, with the burned book open and your soundings beside it.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pilot_house) and at(malachy, pilot_house) and soundings(reach) >= 4 and not rutterWritten(reach).
    Time 12.
    On success { Assert rutterWritten(reach). Give rutter to actor. Assert knows(actor, rutter_known). }
    Result "You write it up with him through the afternoon. He dictates and you write, because his hand shakes; he argues with every figure and accepts every one; he draws the channel on the last clean page from memory and your soundings and gets it, he says, exactly right, and then draws it again because exactly right is not good enough. Toward the end the goat comes in and lies down by the stove. At the end he blots the page, and sits back, and looks at it. 'There,' he says. 'There's the Reach. All of her. Any fool could bring a ship in with that.' He closes the book and pushes it across the table to you. 'Somebody should.'".
  }
  Kind rutter_kind "the Pilots' Rutter of the Gannet Reach" is treasure worth 0 weighing 2
    described "A canvas-covered book, burned along one edge, its old pages brown and its new ones white: every depth, bottom, mark and danger of the Reach, sounded again this week. The leading mark on the last page, drawn twice: PULPIT OVER THE HOLM.".
  Item rutter "the Pilots' Rutter" is rutter_kind at limbo.
  Discovery rutter_known "The Pilots' Rutter of the Gannet Reach has been written up again from new soundings: with it, anyone who can handle a boat could bring a ship safely up the channel to Skeel.".
  // Back across, in the gig nobody has rowed in forty years: Malachy will put the company over to the quay when there is water.
  Action malachy_rows(actor: group, site: place) "Ask Old Malachy Sennen to put you across to Skeel" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, inish_strand) and boatsRun() and (rutterAsked(actor) or knows(actor, pilots_known)).
    Time 6.
    On success { Retract at(actor, inish_strand). Assert at(actor, quay). }
    Result "He has a little cockleshell of a boat under the stern of the blue gig, and he rows it as if it were a gig, upright, slow, every stroke the same, all the way across the Reach to the quay, and will not let you take an oar. At the harbour wall he holds on to a ring and looks up at the town for a long time. 'No,' he says, to nobody, and lets go, and rows home.".
  }
}

data/adventures/skeel/keeper.kyr:
Module skeel "Fair Weather" {
  Description "What the hermit's cell on the Holm was for: the keeper's bench and its tally, three notations deep, and the mark of the fish and the flame.".

  // ── The keeper's bench ─────────────────────────────────────────────────────────────────────────────────────────
  // Nobody on the Reach knows what the cell was built for, and everybody has a use for it. Parson Hosken thinks a
  // hermit; Skeel thinks a store. The bench is a ledger. Cut along its underside, in three hands that are not one
  // hand, is the keeping of the Light: a long cut for a ship, and under it a short cut for each soul the sea gave
  // back living, with a flame in the stroke, and for each dog or cat a small paw. Neither man nor dog nor cat is not
  // a charter's whim: it is what the keepers counted. The oldest rows are in a notation nobody reads; the middle rows
  // are in the numerals the Aeneans used, I, V, X, cut with a ruler; the last are the Holm's own marks, a stroke and
  // a ring, and they stop forty years ago, the year the pilots went and the well turned salt.
  Observe lamp_stand_mark at lamp_room as feature when true "Cast into the iron foot of the lamp-stand, rubbed bright where a hand has gone over it for fifty years, is a small device: a fish, and above it a flame.".
  Observe bench_underside at cell when tried(bench, looking) "Under the lip of the hollowed bench the stone is cut in close rows, hand-wide, from one end to the other and back: long strokes, and short ones under them, and in some of the short strokes a little flame, and in a few a paw. The rows are in three hands. The last row ends a hand's breadth short of the wall." teaches tally_seen.
  Thing bench "the worn stone bench in the cell" at cell {
    Tries looking.
    State standing "A stone bench along one wall of the cell, worn into a hollow by somebody's sitting a very long time ago.".
  }
  Initially Assert state(bench, standing).
  Discovery tally_seen "Cut along the underside of the cell's bench is a tally in three hands: a long stroke for a ship, short strokes under it, some of them with a flame cut in, a few with a paw. It stops forty years ago.".
  Discovery tally_read "The bench is the keeper's tally. The oldest rows are in a notation nobody can read; then, in the numerals of the Aeneans, a long stroke for every ship and under it a short one for each person the sea gave back living, with a flame; a paw for every dog or cat; a ring for the dead. The last rows are the Holm's own, and stop in the year the pilots went. Neither man nor dog nor cat is what the keepers counted. A ship that gave back a flame was never wreck." {
    Found by searching cell with lore "You lie on your back on the cell floor with a candle, and the rows come up out of the stone one by one. Three hands: the last is Loveday's mother's, a stroke and a ring, careful, with the habit of someone who learned it by touch; the middle is cut with a rule, in Aenean numerals, so many ships and so many flames under them, century on century of the same patient regular count; the oldest you cannot read at all, but you can read its shape, because it is the same shape. A long stroke. Short ones under it. A flame in some. In all that count there are four hundred and nine ships with a flame in them, and not one of them is marked wreck. Neither man nor dog nor cat: those are not a charter's words. They are the keeper's columns.".
  }
  Topic loveday_bench with loveday "Ask Loveday Kitto what the bench in the cell is for" when knows(actor, tally_seen) once {
    Says "'The bench.' She is quiet. 'My mother said you sit on it the third ebb. When the sea has given somebody back, living, you take them in, and you sit with them on the bench till the third ebb, and you do not say what they are, or whose, or what they were carrying, to anybody. Not to the Reeve. Not to the town.' She turns the rag in her hands. 'Till they've had three ebbs. She said: nobody is to say a word of a man for three ebbs, because a man who's been given back has the right to be nobody for a bit.' She half-laughs. 'I took it for a sailor's superstition. Forty years I've kept a light and sat on that bench one night in a hard winter, to rest my back.'".
  }
  Topic hosken_tally with hosken "Ask Parson Hosken to read the tally on the underside of the cell's bench" when knows(actor, tally_seen) and not knows(actor, tally_read) once {
    Says "He lies on his back on the cell floor in his cassock, with the candle, and says nothing at all for a quarter of an hour, and when he sits up he has stone-dust in his hair and is very pale. 'Not a hermit,' he says. 'I have preached it for twenty years in the vestry: a hermit. A hermit does not count ships.' He shows you the middle rows. 'These are Aenean, they are the numerals one sees on the church foundation, and look, a flame in every fourth stroke, a paw. A dog, a cat. Neither man nor dog nor cat.' He sits on the bench, where nobody has sat. 'It is not the Admiral's phrase. It is older than the Admiral. It is what a keeper wrote down. And the Admiral's grandfather's clerk bought it for a wreck-right and kept the words and did not understand them.'".
    On discuss { Assert knows(actor, tally_read). }
  }
  Discovery keepers_third "The keeper of the Light took in whoever the sea gave back living, sat with them the third ebb, and told no one what they were; the keeper's count of those given back living is why a ship with a living thing ashore of her was never wreck.".

  // ── The Court hears it ──────────────────────────────────────────────────────────────────────────────────────────
  // The Court is asked to relieve a keeper of an office it did not give her. Read, the tally says what a keeper is.
  Relation tallyRead(place).
  Action read_tally(actor: group, site: place) "Read the keeper's tally to the Court" {
    Description "The Court may relieve a keeper it appointed. The tally says who appointed this one.".
    Requires able(actor) and at(actor, site) and at(actor, net_loft) and matterOpen(lantern) and knows(actor, tally_read)
      and not lovedayKept(reach) and not tallyRead(reach) and not henderConfessed(hender).
    Time 2.
    On success { Assert tallyRead(reach). Assert lovedayKept(reach). Assert decided(lantern). Assert knows(actor, keepers_third). }
    Result "You put it plainly, and not well: a bench in a cell, a tally in three hands, four hundred and nine ships with a flame in them, and none of them wreck. Parson Hosken stands up beside you with his hat in his hands and says the middle rows are numerals he has seen cut in the church foundation, and sits down. Nobody in the loft moves. Then Loveday Kitto, on her stool, says clearly, to nobody, 'Third ebb,' and a very old man on the back bench says it with her, 'third ebb,' and then two women, who have not said it since they were girls. Hender Brask puts down his pen. 'The Court,' he says, 'does not relieve what it did not appoint.' He writes it in the book. 'The keeper keeps. The Court notes the tally.'".
  }
  Observe loft_tally_after at net_loft when tallyRead(reach) and decided(lantern) "Jack Cawse has taken his hat off, and does not seem to know it.".
  Rule tally_church_after when courtDone(reach) and tallyRead(reach) and at(party, church) and not tallyNoted(party) says "Parson Hosken has had the chalk-board down from the church wall and turned to its back, where he has begun in a fair hand, in two columns, the names of the Constancy's men, with a space beside each for the day the sea gives them back. At the head he has written, and rubbed out, and written again: THE KEEPER SITS." { Assert tallyNoted(party). }
  Relation tallyNoted(group).

  // Parson Hosken takes a rubbing of the bench, because he has been a clerk and cannot help it. A bilingual of a kind: the
  // Aenean numerals gloss the strokes. He gives it to whoever sat with him in the cell.
  Item bench_rubbing "a wax rubbing of the keeper's bench" is tally_rubbing at nowhere owned by hosken.
  Topic hosken_rubbing with hosken "Ask Parson Hosken to take a rubbing of the tally, for the Court's keeping" when knows(actor, tally_read) and not rubbed(hosken) once {
    Says "'The Court's keeping is a drawer in Hender's parlour,' says Hosken. 'Mine is a vestry cupboard.' He takes a lump of wax and a square of linen out of his cassock, where he had it all along, and goes back to the cell on his knees. It takes him an hour. When he gives it to you it is a piece of the underside of the bench, in cloth, three notations deep and the length of a forearm. 'Take it where it can be read by someone who isn't me,' he says. 'I am afraid I should read it for the rest of my life.'".
    On discuss { Give bench_rubbing to actor. Assert rubbed(hosken). }
  }
  Relation rubbed(group).
}

data/adventures/skeel/kerensa.kyr:
Module skeel "Fair Weather" {
  // ── Kerensa Brask ─────────────────────────────────────────────────────────────────────────────────────────────────
  // The Reeve's daughter, nineteen. Two summers ago she took her grandfather's gig off the shingle at Inish, where it
  // had lain rotting for thirty-eight years, and rebuilt it plank by plank on the slip; and on summer nights she has
  // been rowing it out alone to sound the bar, with Bartle Tonkin's lead-line, for no reason she can tell anybody. She
  // means to leave Skeel on the Ferrar packet. She knows what her father did, or knows enough.
  Person kerensa "Kerensa Brask" at quay {
    Role "the Reeve's daughter, with tar to the elbows". Ancestry human. Calling ranger. Level 2. Peaceable. Pronouns she. Manner acerbic.
    Greets "A tall girl in an old guernsey with her hair tied up in a rag is caulking the seams of a long narrow rowing-gig on the slip, with a mallet and a bucket of pitch. The gig is painted blue, quite new, over very old wood. Without looking up: 'If you're looking for my father he's in the Wreck-House counting. If you're looking for the wreck it's that way. If you're looking for me, nobody is.'".
    Greets again "Kerensa Brask looks up from the gig and points the mallet at you.".
    Joins "Kerensa Brask wipes the tar off her hands onto her guernsey, which is past saving. 'Right,' she says. 'Where to.'".
    Leaves "Kerensa Brask nods, and goes back to her gig.".
  }
  Observe gig_scene at quay as feature when at(kerensa, quay) "On the bow of the blue gig, newly cut and gilded, a name: JACOB.".
  Rule kerensa_home when hour(clock) >= 21 and at(kerensa, quay) and not travelsWith(kerensa, party) and not courtSitting() { Retract at(kerensa, quay). Assert at(kerensa, reeve_parlour). }
  Rule kerensa_out when hour(clock) >= 7 and hour(clock) < 21 and at(kerensa, reeve_parlour) and not travelsWith(kerensa, party) and not kerensaGone(kerensa) { Retract at(kerensa, reeve_parlour). Assert at(kerensa, quay). }
  Measure kerensaTrust(group). Initially Set kerensaTrust(kerensa) to 0.
  Relation kerensaGone(group).

  Topic kerensa_gig with kerensa "Ask Kerensa Brask about the gig" when true once {
    Says "She stops caulking. 'My grandfather's. Jacob Brask's. She lay on the shingle on Inish for thirty-eight years with the grass growing through her, and two summers ago I rowed over in Jinny's punt and dug her out and towed her home.' She slaps the gunwale. 'New garboards, new stem, eleven new planks, and every rib but three. She's more mine than his now. Don't tell my father; he thinks I bought her off a man in Callowport.' She goes back to the seam. 'He's never once come down the quay to look.'".
    On discuss { Increase kerensaTrust(kerensa) by 1. Assert knows(actor, pilot_son). }
  }
  Relation helpedGig(group).
  Action help_gig(actor: group, site: place) "Help Kerensa Brask turn the gig and pay her seams" {
    Description "Hot pitch, a mallet, and a long hull to roll over on the slip without cracking her.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, quay) and at(kerensa, quay) and daylight() and not helpedGig(actor).
    Time 12.
    Resolve check(actor, mending, dc_fair).
    On success { Assert helpedGig(actor). Increase kerensaTrust(kerensa) by 1. }
    On failure { Assert helpedGig(actor). }
    Result "You roll her over between you on the slip, slowly, on old fenders, and pay the seams of her bottom with hot pitch, and Kerensa talks to the boat the whole time, the way you talk to a horse: steady now, there, there's my girl. When it is done she sits back on her heels with pitch to the eyebrows and looks at you differently. 'You've done that before,' she says. 'Or you've hands that learn.'".
    Otherwise "You do your best, and it is not much, and she does it again after you without a word. But she lets you stay.".
  }
  Topic kerensa_leaving with kerensa "Ask Kerensa Brask what she means to do" when kerensaTrust(kerensa) >= 1 once {
    Says "'Go.' She drives a strand of oakum into a seam. 'There's a packet coming tomorrow from the south for the Constancy, the owners' packet. It goes back on the fourth tide. I'm going on it if I have to stow away in the bread.' Mallet. 'There's nothing here. There's wreck and there's waiting for wreck. There's my father in the Wreck-House counting the dead's grain, and the whole town hoping the sea'll be kind to it and cruel to somebody else.' She looks out at the Reach. 'I want to go where there's ships coming in, not ships coming apart.'".
    On discuss { Increase kerensaTrust(kerensa) by 1. }
  }
  Topic kerensa_bar with kerensa "Ask Kerensa Brask what she has been sounding the bar for" when kerensaTrust(kerensa) >= 2 and (knows(actor, pilots_known) or turnedWheel(actor)) once {
    Says "She goes very still with the mallet in the air. Then she laughs, angrily. 'Bartle. Bartle Tonkin and his one lead-line a year.' She puts the mallet down and wipes her hands and takes out of her guernsey a little notebook bound in sailcloth, and holds it, not giving it. 'Two summers. Every state of the tide, every cast, the whole bar from the Craigs to Inish. I don't know why. Because he did it. Because it's there to be known and nobody knows it any more.' She turns the notebook over. 'Because if anybody ever wanted pilots on the Reach again, somebody would have to know the bar.' She almost holds it out. 'It's no use to anybody. There's no station.'".
    On discuss { Assert knows(actor, kerensa_sounds). Increase kerensaTrust(kerensa) by 1. }
  }
  Discovery kerensa_sounds "Kerensa Brask has been rowing her grandfather's rebuilt gig out at night for two summers, sounding the whole of the Reach's bar, cast by cast, and keeps it in a notebook.".
  Topic kerensa_notes_ask with kerensa "Ask Kerensa Brask to let Old Malachy see her notebook, for the Rutter" when knows(actor, kerensa_sounds) and rutterAsked(actor) once {
    Says "'Malachy Sennen.' She says it as you might say the name of a saint. 'He's alive? He's still on Inish? I thought — father said — ' She stops. She looks at the notebook, and at the gig, and at you. Then she puts the notebook in your hand and closes your fingers over it. 'Tell him it's Jacob's line,' she says. 'Tell him who sounded it. And bring it back.'".
    On discuss { Give kerensa_notes to actor. Increase kerensaTrust(kerensa) by 1. }
  }
  Topic return_notes with kerensa "Give Kerensa Brask back her notebook" when carries(actor, kerensa_notes) and sounded(snd_bar) once {
    Says "She takes it and turns the pages as if to see whether anything is missing. 'He read it?' You tell her what Malachy said. She does not say anything for a while. Then she puts the notebook inside her guernsey, against her chest, and picks up the mallet, and hits the gig rather harder than the seam needs.".
    On discuss { Spend notebook_kind from actor. Increase kerensaTrust(kerensa) by 1. }
  }
  // What she saw. She will tell it only when she has decided to go, and only to someone she trusts.
  Discovery kerensa_saw "On the night of the wreck Kerensa Brask heard her father come in at three in the morning. He was wet to the thigh and there was red clay on his boots, Craigs clay, that does not come from anywhere in Skeel; he burned his coat in the wash-house copper before dawn, and he has not slept since.".
  Topic kerensa_father with kerensa "Ask Kerensa Brask about the night of the wreck" when kerensaTrust(kerensa) >= 3 once {
    Says "She does not answer. She is looking at the gig's name, and the mallet hangs from her hand. 'He came in at three,' she says at last. 'I wasn't asleep. I heard the door. He was wet to here.' She touches her thigh. 'There was red clay on his boots. There's no red clay in Skeel. There's only red clay on the Craigs path.' She swallows. 'He lit the copper in the wash-house at four in the morning, and burned his good black coat in it, and stood watching it burn. In the morning he had his other coat on and he went out with the carts and he's not slept since. Not one night. I hear him walking.' Now she looks at you. 'I'm going on the packet. I'm telling you because I'm going. I'll not stand in the loft and say it to his face. I'll not. Don't ask me.'".
    On discuss { Assert knows(actor, kerensa_saw). }
  }
  Rule kerensa_willing when kerensaTrust(kerensa) >= 3 and not willing(kerensa, party) and not travelsWith(kerensa, party) and not kerensaGone(kerensa) { Assert willing(kerensa, party). }
  Rule kerensa_rows when travelsWith(kerensa, party) and not rowsFor(kerensa, party) { Assert rowsFor(kerensa, party). }
  Rule kerensa_rows_not when rowsFor(kerensa, party) and not travelsWith(kerensa, party) { Retract rowsFor(kerensa, party). }

  // ── The inference ─────────────────────────────────────────────────────────────────────────────────────────────────
  Discovery hender_did "Hender Brask put the sea in the Lantern's oil on the Saturday he brought it, and hung a horn lantern in his father's place in the Pulpit, so that the Constancy would take it for the Holm and steer onto Scarth Bank; and when she struck he covered it.".
  Rule put_together when knows(party, nye_saw) and (knows(party, kerensa_saw) or knows(party, only_four) or knows(party, oil_watered) and knows(party, oil_by_hender) or knows(party, withies_moved) and knows(party, hook_found)) and not knows(party, hender_did)
    says "A tall man in a black coat, with marks under his eyes like bruises, who walked away from a boy in the sea. You have met him. He oils the charter board himself, every week." teaches hender_did { }
}

data/adventures/skeel/lore.kyr:
Module skeel "Fair Weather" {
  Description "Links outward from the Reach: a light seen at sea after a ship was left in the Slack, a stranger's rubbing of the Prefect's table, and the almanack woman who walks from here to the Bowl.".

  // ── A world event, read: the Holm Lantern's night log ───────────────────────────────────────────────────────────
  // If, in the world, the ship Remainder was left in the Slack (the Grand Tour's), a lamp-keeper who has kept the log
  // of an empty sea for years is the first to put it down. Said once, for the room.
  Observe lore_log_light at lamp_room when befell(remainder_kept) "Under the night log of the Lantern, in Loveday Kitto's round hand, a line that is not about weather: LIGHT AT THE EDGE OF THE SEA, 2 A.M., NO SHIP. IT WAS STILL. It is entered again the next night, and the next, always at the same hour, with the same three words after it, and the third night a small mark in the margin, like a tally, that is not Loveday's.".
  Observe lore_taproom_south at taproom when befell(slack_opened) "In the corner by the settle two drovers are explaining to a pilot who has not asked that a great house in a town on the south coast has a black square let into its floor. The pilot is looking at his beer. 'A hole in a floor,' he says. 'We have the sea for that.' Mother Jago, polishing a pot, says that if the sea ever lets a house keep a stair she would like to be told.".

  // ── A visitor from elsewhere: the Prefect's table ───────────────────────────────────────────────────────────────
  Discovery lore_table_same "Loveday has seen the rubbing of the Prefect's table and says the foot-rule on it is the same as the one on the lamp-room wall.".
  Topic lore_loveday_table with loveday "Show Loveday Kitto the rubbing of the Prefect's table" when holding(actor, pharos_rubbing) once {
    Says "Loveday lays it on the lamp-room floor and weights the corners with the tin of wicks, the matches, and two boots. She reads it with her whole arm, the way she reads the sea. 'Columns of numbers,' she says, 'and beside them a column that was scrubbed and never came clean. I know a scrubbed column. Look.' She turns the lamp-stand a quarter so that the light slants, and on the iron foot, beside the fish and the flame, under fifty years of polish, there is a mark you could take for a maker's. She sets her thumb over it, and then she measures the rubbing's foot-rule against the one painted on the wall, twice, and it is the same length. She rolls the rubbing carefully and does not hand it back at once.".
    On discuss { Assert knows(actor, lore_table_same). }
  }

  // ── The almanack woman ──────────────────────────────────────────────────────────────────────────────────────────
  // Jessamy Cattermole walks a loop that no map draws: the Reach, the Bowl of Ammerlin, Merrowdale, the Lim valley,
  // the Wray, and back to the sea. She sells almanacks, each printed in a different town, each for a different year.
  Discovery lore_cattermole_skeel "Jessamy Cattermole, who sells almanacks, was at the Admiral at Michaelmas and has gone up the coast road to the Bowl of Ammerlin, where a man named Halm pays by the inch for anything with a mark on it that is not writing. Parson Hosken gave her a stub of wax.".
  Topic lore_jago_cattermole with jago "Ask Mother Jago who else has come down the coast road this autumn" when true once {
    Says "'Cattermole,' says Jago at once, as if the name were a plate she had been waiting to put down. 'The almanack woman. Six towns' worth in a leather satchel, and no two of them agree what year it is. She says it does not matter, they all keep Michaelmas on the same night.' She wipes her hands. 'Sold the Reeve a calendar he did not want and Parson Hosken a stub of rubbing-wax he did. Went off up the north road to a place called Ammerlin, to a man called Halm who pays by the inch for marks that are not writing. If you see her, she owes me for four pints and a stable.'".
    On discuss { Assert knows(actor, lore_cattermole_skeel). }
  }

  // ── An entry point: a letter for the Tolleth packet ─────────────────────────────────────────────────────────────
  // Mother Jago's man cooks aboard a packet out of Tolleth, the Dorothea, and writes once a year. She has a letter and
  // nobody to carry it south. The Dorothea sails on the noon ebb from the quay at Tolleth; Captain Bascom will know him.
  Item lore_jago_letter "Mother Jago's letter, folded in a sketch of the Admiral" is map at limbo owned by jago.
  Relation lore_jagoLetter(group).
  Topic lore_jago_packet with jago "Ask Mother Jago whether she has word for anyone on the Tolleth packet" when true once {
    Says "'Now who told you?' says Jago, and puts down the pot. 'My man is cook on the Dorothea, Tolleth packet, Captain Bascom, salt south and lamp-oil to the rock at Skerrow and back. He writes at Michaelmas and I write at Lady Day and it has not once crossed.' She digs under the counter and brings up a letter folded inside a drawing of the Admiral, the roof, the sign, a cat. 'If you are going that way. The board on the quay at Tolleth gives her sailings in chalk. Tell Bascom it is for her cook, and tell him the cat is well. Do not tell him the roof.'".
    On discuss { Give lore_jago_letter to actor. Assert lore_jagoLetter(actor). }
  }

  // ── Three papers and a face from elsewhere, each shown to someone who would know what to do with it ───────────────
  Discovery lore_mask_notch "Parson Hosken, shown a grey mask with a single notch for a brow, says the notch is a count of one, and that he has preached over the Holm's cell for twenty years without once asking what it kept.".
  Topic lore_hosken_mask with hosken "Show Parson Hosken the grey mask with the notch" when holding(actor, keeper_mask) once {
    Says "Hosken holds it by the rim, as he holds the chalice, and turns it to the window. 'No eyes,' he says. 'No mouth. A face made to be looked at and not to look.' His thumb finds the notch. 'One,' he says. 'Not a sin, not a saint's day. One. As on the bench in the cell, where the strokes come in rows and the rows end.' 'Somebody was meant to keep this count and stand where it could see the sea.' He sets the mask on the pew very gently, face up, and does not take his hand away from it for some time.".
    On discuss { Assert knows(actor, lore_mask_notch). }
  }
  Discovery lore_letter_lead "Bartle Tonkin, shown a letter from the Collegium of Lesser Instruments, says the Collegium wants things that work and that the only working thing on the ropewalk is his one lead-line, which he casts once a year and writes down.".
  Topic lore_bartle_letter with bartle "Show Bartle Tonkin the letter of the Collegium of Lesser Instruments" when holding(actor, collegium_letter) once {
    Says "Bartle reads it with his lips, and then reads the seal. 'Friend of working things,' he says. 'There is a college that thinks well of a hank of tarred cord. I never knew.' He wipes his hands on his apron for longer than they need. 'I have a lead-line. One. I take it out over the bar every Michaelmas, a cast to the foot, and put the numbers in a book that nobody has asked for in thirty years.' He looks at the letter, and at the book on its nail, and takes the book down and wipes its cover with his sleeve before he puts it back.".
    On discuss { Assert knows(actor, lore_letter_lead). }
  }
  Discovery lore_surety_jago "Mother Jago, shown the Ninth Valuer's note on a surety, says she stood surety once for a boat's caulking and that nobody wrote down which keeping she was standing for.".
  Topic lore_jago_surety with jago "Show Mother Jago the Ninth Valuer's note on a surety" when holding(actor, surety_terms) once {
    Says "Jago reads the strip at arm's length and then holds it to the lamp. 'Answers for the keeping named,' she says, 'and where none is named, for all.' She puts a thumb on the last words. 'I put my name to the Patience's new planking, the spring Skeel was short. Nobody wrote what I was standing for. I thought I was standing for a plank.' She hands it back, and goes to see to a pot that does not need seeing to, and for a while the taproom hears her thinking about the whole ship.".
    On discuss { Assert knows(actor, lore_surety_jago). }
  }

  // ── The Scarth light, down the coast ────────────────────────────────────────────────────────────────────────────
  // Lamp-keepers read each other's lights. Loveday Kitto has never seen the Scarth rock, but she knows its character
  // from eleven miles of sea, and puts down what she sees of it in the same hand as the weather.
  Observe lore_log_scarth_kept at lamp_room when befell(scarth_kept) and not befell(scarth_lost) "Under the night log, in Loveday Kitto's round hand, a line that is not about weather: THE SCARTH LIGHT WAS LIT AT DUSK AND STOOD ALL NIGHT AND WAS LIT AT DAWN. She has underlined ALL NIGHT. 'You'd think that the rule,' she says, 'not the news. But I have been keeping a light thirty years and I have seen it go out on a rock with a keeper in it. I put it down when one doesn't.'".
  Observe lore_log_scarth_lost at lamp_room when befell(scarth_lost) "Under the night log, in Loveday Kitto's round hand, a line that is not about weather: THE SCARTH LIGHT WAS LIT, AND THE KEEPER'S WINDOW WAS NOT. She has not underlined it. She has turned the log a quarter on the table, as one turns a slate, so that the next page is the one that faces her. 'It is a long way to be sorry from,' she says, 'but I find I am.'".
}

data/adventures/skeel/placed.kyr:
Module skeel "Fair Weather" {
  // The Reach as a country beyond a march: the company that comes in by the coast road is the world's own.
  Entity party: group "Your company".
  // What is said of the Reach in the country behind it: once the Wreck Court has risen, it is old news there.
  Entity word: fact "What is said of the Gannet Reach in the country behind it.".
  Rule word_old when courtDone(reach) and not stale(word) { Assert stale(word). }
}

data/adventures/skeel/skeel.kyr:
Module skeel "Fair Weather" {
  // ── What everybody in Skeel knows ─────────────────────────────────────────────────────────────────────────────────
  Discovery wreck_known "Three nights ago, in fair weather and a light westerly, the merchantman Constancy, out of the south with grain and wine, steered into the Reach in the dark and struck Scarth Bank, and broke her back. The Lantern on Hobb's Holm was dark that night. Nobody came ashore from her alive, they say, and by morning half Skeel was out on the sands with carts." {
    Known by jago, hender, kerensa, cawse, bartle, jinny, cuddy, huer, hosken, loveday, ebrel, piran, ewan, malachy.
  }
  Discovery court_known "At four o'clock on the third day, on the flood, so that the island men can come, the Wreck-Reeve, Hender Brask, sits as the Wreck Court in the net-loft over the fish cellars and calls the Constancy wreck or not. Wreck, under the Reach's charter, is two parts in three to Skeel and one to the Lord Admiral." {
    Known by jago, hender, kerensa, cawse, bartle, jinny, cuddy, hosken.
  }
  Discovery charter_known "Skeel's charter, painted by the church door: what the sea brings into the Reach is wreck, two parts to the town and one to the Lord Admiral, PROVIDED THAT NO LIVING THING CAME ASHORE OF HER, NEITHER MAN NOR DOG NOR CAT. If anything did, the ship and all of her are her owners' still." {
    Source charter_board "the charter board by the church door" at church readable by party.
    Known by hender, hosken, kerensa, malachy, jago.
  }
  Discovery hunger_known "The herring failed off the Reach last autumn and the autumn before. The Lord Admiral's factor has written that the Reach's rents are two years behind, and that if they are not paid at Martinmas he will let the wreck-right to a Lowland salt company. Without the Constancy's grain, Skeel's children go hungry this winter." {
    Known by jago, hender, kerensa, bartle, jinny, hosken.
  }
  Discovery craigs_light "On the night of the wreck, before she struck, there was a light on the Craigs, high up, where no light belongs; and when she struck it went out." {
    Known by huer, jinny, piran, ebrel.
  }

  // ── The town ──────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe road_scene at coast_road when true "The coast road comes over the shoulder of the down and there below you, all at once, is the Gannet Reach: nine miles of shining water, or of shining sand, depending on the hour, with islands in it, and on the near headland a town of grey roofs going down to a harbour in steps. A track leads off right along the cliff to a little hut on the very end of the headland. The road goes on down into the town, and another, longer, goes away round the head of the Reach toward a line of cliffs on the far side, white with birds.".
  Observe road_wreck at coast_road as sign when not courtOver(reach) "Out on the sands a ship lies on her side, stern up, like a dead animal. Even from here you can see people round her.".
  Observe fore_scene at fore_street when true "Skeel is built of ships. The house-beams are ships' beams, tarred black, with the treenail holes still in them; the doors are hatch-covers; a garden fence is a row of oars stuck in the ground. And on every gable, leaning out over the street, there is a figurehead: a woman with a lyre, a lion, a bishop, a mermaid with her nose gone, a man in a cocked hat, a horse, a child holding a dove. The town calls them the Wooden Saints and knows the name of every one. Fore Street runs along the top of the town, with the church at one end and an inn at the other, and a steep stepped lane, the Drang, falls away between the houses toward the harbour.".
  Observe fore_saints at fore_street as feature when true "Over the inn door is the biggest of the saints: an admiral in a gilt coat with a telescope under his arm and most of his nose shot away. Under him, the sign: THE ADMIRAL.".
  Observe fore_busy at fore_street as ambience when daylight() and not courtOver(reach) "Carts come up the Drang loaded with casks and wet bales, and men walk beside them with their hands on the load, the way you walk beside a coffin.".
  Observe fore_after at fore_street as ambience when courtOver(reach) and daylight() "Fore Street is quiet. People speak to each other on doorsteps in low voices, about the winter.".
  Observe church_scene at church when true "A low church, whitewashed, smelling of tar and candles. The roof is a ship's hull turned over, keel to the sky, and from the ribs hang little ship-models, dozens of them, votive, each one made by somebody's hand for somebody who did not come home. Behind the altar a carving of Lir Who Gives: a bearded man rising waist-deep from the sea with both hands held out, full.".
  Observe church_psalm at church as feature when true "By the door, two boards, both lettered in gilt. The first is the Wreck Psalm, which Skeel sings on the Sunday after a wreck: IF SHIPS MUST FOUNDER, LORD, SEND THEM TO SKEEL. The second, older and better kept, is the charter. Someone oils that one; the wood shines.".
  Observe acre_scene at acre when true "The Strangers' Acre is the strip of turf between the church and the cliff edge, where Skeel buries what the sea brings it. The stones are small and most of them have no names: A SAILOR. A SAILOR. A WOMAN. A SAILOR, 1291. Over the wall the Reach goes out to the horizon.".
  Observe acre_fresh at acre as sign when not acreFilled(reach) "Eleven graves have been dug ready along the wall and stand open and empty, with planks over them against the rain: for the Constancy's dead, when the Reach gives them back.".
  Relation acreFilled(place).
  Observe quay_scene at quay when true "A curved stone quay with a harbour inside it no bigger than a field. Herring boats lie in it with their sails furled, and the ferry lugger, and a long, narrow, very old rowing-gig pulled up on the slip with a girl working on her. On the quay: barrows, nets spread to dry, the Wreck-House with its iron-bound doors, and the fish cellars with a loft over them.".
  Observe quay_dry at quay as weather when lowWater() "The harbour has emptied. The boats lie on the mud, each on its side or propped on its legs, and you can walk round them. It smells of weed and fish and the inside of things.".
  Observe quay_full at quay as weather when not lowWater() "The harbour is full and the boats ride in it, knocking gently against the wall.".
  Observe cellar_scene at cellars when true "Long low vaults with the herring-presses in them, great beams with stones hung on the ends, standing idle. The salt is stacked waiting for fish that did not come. It is very cold.".
  Observe loft_scene at net_loft when not courtBegun(reach) "A long loft under the roof, where the nets are mended in winter. It has been swept, and benches set out in rows, and at the far end, a table with a cloth on it and one chair behind it: for the Wreck Court.".
  Observe slip_scene at slip when true "A cobbled slipway goes down off the end of the harbour wall onto the Strand. At its foot a post is driven into the sand with a bell on it, and beside the post the first of the withies: a laurel branch stuck upright, then another, and another, away across the sand.".

  Observe parlour_scene at reeve_parlour when true "A narrow, very tidy parlour: two chairs by a grate, a clock, a shelf of ledgers in date order, and on the wall a framed chart of the Reach, old and foxed, with a pilot's soundings on it in faded ink. Under the chart, a blue-painted oar, very old, hung on two pegs like a sword.".
  Relation chartRead(group).
  Action read_chart(actor: group, site: place) "Study the old chart of the Reach on the Reeve's wall" {
    Description "Faded soundings in a pilot's hand, and marks nobody in Skeel uses any more.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, reeve_parlour) and not chartRead(actor) and not benighted(actor).
    Time 2.
    Resolve check(actor, lore, dc_fair).
    On success { Assert chartRead(actor). Assert knows(actor, leading_mark). Assert knows(actor, chart_jacob). }
    On failure { Assert chartRead(actor). }
    Result "It is a pilot's working chart, sixty years old, the soundings in brown ink in a small neat hand, and in the margin, signed J.B., a note on the leading mark: the Pulpit kept over the Holm light brings a ship up the channel clear of Scarth Bank, and a lamp is hung in the Pulpit on black nights at the iron ring. Somebody has gone over that note very recently with a finger; the dust on the glass is wiped clean along it, and nowhere else.".
    Otherwise "Soundings, bearings, marks in a cramped hand and an old notation you cannot follow. You can see that it means something, and not what.".
  }
  Discovery chart_jacob "On the Reeve's parlour wall hangs Jacob Brask's own chart of the Reach, with the leading mark noted in the margin and the place of the Pulpit lamp; the dust on the glass has been wiped away along that note, recently, by a finger.".
  Observe head_scene at head when true "The very end of Skeel Head: turf, thrift, a sheer drop on three sides to the sea, and the whole Reach spread below like a map. A stone hut the size of a cupboard stands on the point with a window on every side.".
  // ── Mother Jago and the Admiral ───────────────────────────────────────────────────────────────────────────────────
  Observe tap_scene at taproom when true "A low room built into the hold of a ship, they say, and it feels it: the beams curve, the floor tilts a little toward the fire, and the lamps swing when the door opens. Fishermen with nothing to fish sit at the long table over small beer. On the wall, a painted board with the names of ships that have come to Skeel, and the years. The last name, freshly painted: CONSTANCY.".
  Person jago "Mother Jago" at taproom {
    Role "who keeps the Admiral". Ancestry human. Profession innkeeper. Peaceable. Pronouns she. Manner cheerful.
    Sells rations for 1 coin from 20.
    Sells pilchard_pie for 1 coin from 10.
    Buys wine_cask_kind for 7 coin.
    Greets "'Come in, come in, mind the floor, it goes downhill.' A big woman in a man's waistcoat, with a cloth over one shoulder. 'You'll be off the coast road. You've come at a bad time or a good one, depending who you ask, and I'm not saying which.'".
    Greets again "Mother Jago lifts the cloth off her shoulder at you by way of hello.".
  }
  Initially Set quantity(jago, gold) to 40.
  Kind wine_cask_kind "a cask of southern wine" is treasure worth 6 weighing 8
    described "A small cask, wet, sound by the knock. It is not water. It is red, and very good, and worth a good deal more in the Admiral's taproom than it cost you on the quay.".
  Observe tap_bird at taproom as feature when true "Up in the rafters, in among the hams, a small yellow bird hops about and sings, as if it had always lived here. Mother Jago says it came in at the door the morning after the wreck and she has not the heart to put it out.".
  Topic jago_bird with jago "Ask Mother Jago whether a bird is a living thing, under the charter" when knows(actor, charter_known) once {
    Says "Mother Jago looks up at the rafters, where the yellow bird is singing, and then at you, and then she puts a finger to her lips. 'Neither man nor dog nor cat,' she says. 'It says nothing about canaries. I asked Hosken. He said it was a very interesting question and he'd pray on it.' She lowers her voice. 'Don't you dare.'".
  }
  Kind pilchard_pie "a star-gazy pie" is gear worth 1 weighing 1
    described "A pie with the heads of six pilchards sticking up through the crust round the edge, looking at the sky. Mother Jago says it is so they can see where they are going.".
  Topic jago_wreck with jago "Ask Mother Jago about the wreck" when true once {
    Says "'The Constancy.' She points the cloth at the board on the wall. 'Painted her up yesterday. Fair weather, light airs, a big ship from the south, and she walks straight onto Scarth Bank like a cow onto a cart. Lantern was out, that's what they say. Loveday Kitto fell asleep.' She wipes a table that does not need it. 'Forty-one years that woman's kept the Lantern and never once. Well. Once is all it takes, at sea.'".
    On discuss { Assert knows(actor, wreck_known). }
  }
  Topic jago_court with jago "Ask Mother Jago what happens now" when knows(actor, wreck_known) once {
    Says "'Now? Now the Reeve sits in the net-loft day after tomorrow at four, on the flood, and says wreck, and we eat this winter.' She looks round at the fishermen at the long table, who are looking at their beer. 'Two years the herring's not come. You see them? Thirty boats and nothing to put in them. The Admiral's factor wants his rents, and there's talk of a salt company. So: wreck, and grain, and nobody asks too close how a ship comes to walk onto a bank in fair weather.' She stops wiping. 'I didn't say that. It's the beer talking, and I've not had any.'".
    On discuss { Assert knows(actor, court_known). Assert knows(actor, hunger_known). }
  }
  Topic jago_name with jago "Ask Mother Jago why everyone laughs when the Admiral is mentioned" when knows(actor, dog_known) once {
    Says "She laughs herself, helplessly, into the cloth. 'Because the dog's called Admiral. The ship's dog. Off the Constancy, came ashore swimming, and the Reeve wants it dead before the Court, because a living dog makes her no wreck, and there's our winter gone over a dog. And the Lord Admiral gets his third, and this house is the Admiral, and him on the gable is the Admiral, and the dog is the Admiral.' She wipes her eyes. 'Every time anybody says it this week somebody chokes. Old Hosken preached on Sunday about the Admiral's due and the whole church was in fits and he never knew why.'".
  }
  Topic jago_saints with jago "Ask Mother Jago about the figureheads" when true once {
    Says "'The saints?' She is pleased; it is a thing she likes to be asked. 'One for every ship that ever came to Skeel. They go up on the house of whoever got to her first. Him over my door's the oldest, the Admiral, off a man-of-war a hundred years back, and the Jagos have had him since. The Reeve has the Lady with the Lyre. The Kittos have none; they keep the Lantern, it's not right for them.' A pause. 'The Constancy's saint's up on Scarth Bank still, on her bow, under the water half the day. A girl, they say, holding a book. Nobody's got to her yet. She's in the Reeve's gift, the saint is, and he's not given her.'".
  }
  Topic jago_dog_hide with jago "Ask Mother Jago to hide the dog under her stairs" when following(admiral, actor) and not dogHidden(admiral) once {
    Says "Mother Jago looks at the dog, and the dog looks at Mother Jago, and something passes between them. 'Under the stairs,' she says. 'There's a sack there, and a bone with some ham left. If the Reeve asks, I've never seen a dog in my life, and I'll swear it in church.' She points the cloth at the dog. 'You. Not a sound.'".
    On discuss { Retract following(admiral, actor). Assert dogHidden(admiral). Assert at(admiral, taproom). }
  }

  Topic jago_dog_back with jago "Ask Mother Jago for the dog from under the stairs" when dogHidden(admiral) and at(admiral, taproom) once {
    Says "She goes to the stairs and says something to the dark under them, and Admiral comes out with ham on his whiskers and his tail going, and she brushes him down with the cloth as if he were going to church. 'There,' she says. 'Somebody in this town had better be respectable.'".
    On discuss { Retract dogHidden(admiral). Assert following(admiral, actor). }
  }
  // ── Bartle Tonkin's ropewalk ──────────────────────────────────────────────────────────────────────────────────────
  Observe rope_scene at ropewalk when true "A long straight alley of beaten earth behind the houses, two hundred yards of it, roofed with old sails on posts. At one end a great wheel with a handle; down its length, strands of hemp stretched between hooks, being twisted into rope as a man walks backward away from the wheel feeding fibre from a bundle at his waist. It smells of tar and hay.".
  Person bartle "Bartle Tonkin" at ropewalk {
    Role "rope-maker of Skeel". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Sells rope for 1 coin from 6.
    Sells lead_line for 2 coin from 3.
    Greets "A man walking backward down the ropewalk, with hemp round his middle, stops walking backward and looks at you. 'Rope or work?' he says.".
    Greets again "Bartle Tonkin nods without stopping walking backward.".
  }
  Kind lead_line "a lead-line" like rope worth 2 weighing 2
    described "Twenty fathoms of tarred line marked with leather and bunting and calico at every fathom, and on the end a lead the shape of a bell, hollowed underneath and filled with tallow, so that it brings up a little of whatever it touches: sand, shell, mud, stone. A pilot reads the bottom of the sea with it, as a blind man reads a face.".
  Topic bartle_lead with bartle "Ask Bartle Tonkin what a lead-line is for" when true once {
    Says "'Sounding.' He holds one up: a bell of lead on a marked line. 'Heave it, let it run, read the depth off the marks as it goes slack. Tallow in the bottom. Brings you up sand, or shell, or mud.' He looks at it. 'Used to sell forty a year to the pilots. Now I sell one a year, to the Reeve's girl, and she doesn't think I know what she wants it for.'".
  }
  Relation turnedWheel(group). Measure wheelDays(group).
  Action turn_wheel(actor: group, site: place) "Turn Bartle Tonkin's rope-wheel for the afternoon, for two coin" {
    Description "Hard work and no thinking. He pays at the end.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ropewalk) and at(bartle, ropewalk)
      and daylight() and wheelDays(actor) != dayN(reach).
    Time 18.
    On success { Increase quantity(actor, gold) by 2. Set wheelDays(actor) to dayN(reach). Assert turnedWheel(actor). }
    Result "You turn the wheel for three hours while Bartle walks backward away from you with the hemp, and back, and away, and the strands twist and tighten and become rope. He does not speak once. At the end he counts two coins into your hand and says, 'You'll do,' which from Bartle Tonkin is a speech.".
  }
  Topic bartle_talk with bartle "Ask Bartle Tonkin about the Reeve" when turnedWheel(actor) once {
    Says "He coils rope while he talks. 'Hender Brask.' Coil. 'I was at school with him. His father was Jacob Brask, the pilot, the best on the Reach. When the pilots were finished, Jacob drank, and then he went out in his gig one night and didn't come back, and Hender was twelve and Loveday Kitto took him in.' Coil. 'He's a good Reeve. Reads everybody's letters for them, them that can't. Knows what everybody owes. Never cheated anyone of a farthing in his life.' He hangs the coil on its peg. 'Hasn't slept since the wreck. You can see it on him. I don't know what that means and I'm not going to think about it.'".
    On discuss { Assert knows(actor, pilot_son). }
  }
  Discovery pilot_son "Hender Brask is the son of Jacob Brask, the best pilot the Reach ever had. When the pilots were finished, forty years ago, Jacob drank, and was lost in his gig, and Loveday Kitto took the boy in.".

  // ── Jinny Rowse and the Patience ──────────────────────────────────────────────────────────────────────────────────
  Person jinny "Jinny Rowse" at quay {
    Role "who sails the Patience". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "A small woman in a man's sea-boots, sitting on a bollard eating an apple with a knife. 'If you want the Patience,' she says, 'it's three coin for the day, anywhere she'll go, as many times as you like, while there's water. Holm, Skerry, Inish. Not the Craigs, there's no landing.'".
    Greets again "Jinny Rowse cuts you a slice of apple and holds it out on the knife.".
  }
  Measure fareDay(group). Initially Set fareDay(party) to 0.
  Query passage(g: group) means fareDay(g) == dayN(reach) or rowsFor(kerensa, g).
  Relation rowsFor(group, group).
  Action pay_jinny(actor: group, site: place) "Pay Jinny Rowse three coin for the day's sailing" {
    Description "Holm, Skerry or Inish Gall, as often as you like today, while there is water in the harbour.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, quay) and at(jinny, quay)
      and quantity(actor, gold) >= 3 and not passage(actor) and not refusesJinny(actor).
    Time 0.
    On success { Decrease quantity(actor, gold) by 3. Increase quantity(jinny, gold) by 3. Set fareDay(actor) to dayN(reach). }
    Result "Jinny Rowse puts the coins in her boot. 'When there's water,' she says, and looks at the harbour, and at the tide-board.".
  }
  Topic jinny_night with jinny "Ask Jinny Rowse about the night of the wreck" when true once {
    Says "She cuts a slice of apple and eats it off the knife. 'I was out. Lines, off the Skerry. Nothing biting.' Another slice. 'I saw the Constancy's lights come in from the south, a big ship, going careful. Then there was a light on the Craigs, high up, where there's never a light. And she turned for it.' She stops chewing. 'You know why she'd turn for it? Because a light up there is where the Holm's light would be if you were further south than you are. A stranger reads it as the Holm. And then she struck, and the light on the Craigs went out, like that.' She closes her hand. 'And the Lantern was dark the whole time. I sat in my boat and watched it, and I've not told the Reeve, and I'll tell you why: he never asked.'".
    On discuss { Assert knows(actor, craigs_light). }
  }
  Topic jinny_pilot with jinny "Ask Jinny Rowse how she knows the channels" when knows(actor, craigs_light) once {
    Says "'Same as anybody. Forty years in them.' She wipes the knife on her knee. 'There's no pilots on the Reach, not since the Admiral let the station go. A ship that wants bringing in hangs about off the bar and fires a gun, and if I'm about I go out to her, and if I'm not, she takes her chance. Most years she takes her chance and comes to Skeel the other way.' She looks at the gable over the Wreck-House: a lady with a lyre. 'I'm not a pilot. Pilots are paid.'".
  }

  // ── Cuddy Pascoe, the Sands-Guide ─────────────────────────────────────────────────────────────────────────────────
  Person cuddy "Cuddy Pascoe" at slip {
    Role "the Sands-Guide". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "A long thin man with a bundle of laurel branches under one arm and a staff with a bell on it, wet to the thighs. 'Going out? Don't,' he says, beaming. 'Not on your own. Not your first time. A coin and I'll walk you, and you'll come back with the same number of legs.'".
    Greets again "Cuddy Pascoe rings his little bell at you.".
  }
  Rule cuddy_at_slip when lowWater() and daylight() and not at(cuddy, slip) { Retract at(cuddy, taproom). Assert at(cuddy, slip). }
  Rule cuddy_at_inn when not (lowWater() and daylight()) and not at(cuddy, taproom) { Retract at(cuddy, slip). Assert at(cuddy, taproom). }
  Action hire_cuddy(actor: group, site: place) "Pay Cuddy Pascoe a coin to walk you over the sands" {
    Description "He knows every soft place on the Strand by its first name.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, slip) and at(cuddy, slip)
      and lowWater() and quantity(actor, gold) >= 1 and not guided(actor).
    Time 0.
    On success { Decrease quantity(actor, gold) by 1. Increase quantity(cuddy, gold) by 1. Assert guided(actor). Increase walkedWith(cuddy) by 1. }
    Result "Cuddy takes the coin and rings his bell at the sand, as if to warn it. 'Right side going out,' he says. 'Left side coming in. Walk where I walk. If I stop, stop. If I run, run.'".
  }
  Measure walkedWith(group). Initially Set walkedWith(cuddy) to 0.
  Topic cuddy_teach with cuddy "Ask Cuddy Pascoe how he knows where the soft sand is" when walkedWith(cuddy) >= 1 once {
    Says "'Look at it.' He points with his staff. 'Wet sand shines. Hard sand shines. Soft sand's dull, like a sick dog's eye. And never walk between two withies more than twenty paces apart, because if they're further than that, one's washed out and the sand's moved.' He hands you a withy. 'Right side going out, left side coming in. That's the whole of it. That and four hours. I lost a boy last spring who knew the whole of it and forgot the four hours.'".
    On discuss { Assert knows(actor, withy_way_known). }
  }
  Topic cuddy_night with cuddy "Ask Cuddy Pascoe who was on the sands the night of the wreck" when knows(actor, wreck_known) once {
    Says "His smile goes. 'Everybody, by morning.' He turns a withy in his hands. 'Before? Nobody. Nobody walks the Strand at night but me, and I was abed.' He looks out at the sand. 'Only the withies were wrong, after. Three of them out by Scarth Bank, pulled and stuck back a yard off, the way a man does who's walking with a lantern and leans on them. I put them right. I never said.' He rings the bell, very softly. 'You don't, in Skeel.'".
    On discuss { Assert knows(actor, withies_moved). }
  }
  Topic cuddy_wet with cuddy "Tell Cuddy Pascoe the sea caught you on the Strand" when caughtByFlood(actor) once {
    Says "He stops smiling and looks at you properly, up and down, the way you look at someone to count their legs. 'Four hours,' he says. 'And the fifth is the sea's.' Then he rings his little bell at you, softly, twice, which you understand is what he does instead of saying he is glad you are alive.".
  }
  Discovery withies_moved "On the morning after the wreck, Cuddy Pascoe found three withies out by Scarth Bank pulled and stuck back a yard off true, the way a man leans on them who is walking the Strand at night with a lantern.".

  // ── The huer ──────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe huer_scene at huer_hut when true "A stone hut the size of a cupboard on the very end of Skeel Head, with a window on every side and a speaking-trumpet on a hook. From here you can see the whole Reach, and the open sea beyond it to the west. Painted over the door, very faded: HEVVA.".
  Person huer "Old Pender" at huer_hut {
    Role "the huer of Skeel". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Greets "An old man with a telescope, who does not take his eye from it. 'Hevva,' he says, softly, to nobody. 'That's what you cry, when you see the herring. The water goes red with them, and you cry Hevva! down the trumpet, and the whole town runs.' He lowers the telescope. 'I've not cried it in two years.'".
    Greets again "Old Pender lifts a hand without turning from the window.".
  }
  Topic huer_wreck with huer "Ask Old Pender what he cries now" when true once {
    Says "'Wreck.' He puts the telescope down. 'They pay me the same for wrecks. Four shillings a year to watch the sea, and a share. I cried the Constancy at first light, and the town came running, and I got my share.' He rubs his eye. 'There was a light on the Craigs before she struck. I saw that too. I didn't cry it. A huer cries what he's paid to.'".
    On discuss { Assert knows(actor, craigs_light). }
  }
  Topic huer_herring with huer "Ask Old Pender where the herring have gone" when true once {
    Says "'Ah.' He brightens. 'Now there's a question. The Lowlanders say we fished them out. Hosken says it's a judgement. My father said the herring go where they're sung for, and they stopped singing for them when the pilots went, because it was the pilots' wives who sang them in.' He looks at you sidelong. 'I don't hold with that. But they came every year he was alive.'".
  }

  // ── The parson ────────────────────────────────────────────────────────────────────────────────────────────────────
  Person hosken "Parson Hosken" at church {
    Role "priest of Lir Who Gives". Ancestry human. Peaceable. Pronouns he. Manner compassionate.
    Greets "A round, kind, short-sighted man in a cassock gone green at the seams. 'Welcome to Lir's house. He gives, you know. That is the whole of the theology here, and I have found it to be sufficient.'".
    Greets again "Parson Hosken peers at you, and finds you, and beams.".
  }
  Topic hosken_psalm with hosken "Ask Parson Hosken about the Wreck Psalm" when true once {
    Says "'Ah, the Psalm.' He looks at the board as at a difficult relative. 'It is very old. It is a prayer for the town to be fed, and if you pray to be fed by the sea you must take what the sea brings.' He polishes his spectacles on his cassock, which makes them worse. 'I preached once that we should add a verse, for the drowned. They were very kind about it. Nobody came for three weeks.'".
  }
  Topic hosken_charter with hosken "Ask Parson Hosken about the charter" when knows(actor, charter_known) once {
    Says "'Neither man nor dog nor cat.' He says it with pleasure, like a line of verse. 'It is an old law, older than the Admiral. The idea, I think, was that if anything lived, someone might come for her. A ship with a living thing on her is still somebody's.' He looks at the board. 'Hender oils it himself, every week. He says it is the only law on the Reach that has never been broken. I have always thought that a strange thing to be proud of.'".
  }
  Topic hosken_burial with hosken "Ask Parson Hosken about the open graves in the Acre" when true once {
    Says "'The Reach gives back its drowned on the third ebb, nearly always. On the Strand, at the wrack line below the Slip.' He folds his hands. 'We bury them in the Acre with a stone each, A SAILOR, because we do not know their names. Once a man came from the south to look for his son, two years too late, and walked up and down the Acre reading A SAILOR, A SAILOR, A SAILOR, and then went home.' He is quiet a moment. 'I should like, this once, to know their names.'".
    On discuss { Assert knows(actor, third_ebb). }
  }
  Discovery third_ebb "The Reach gives back its drowned on the third ebb after a wreck, at the wrack line on the Strand below the Slip, and Skeel buries them in the Strangers' Acre under stones that say A SAILOR.".
}

data/adventures/skeel/skerry.kyr:
Module skeel "Fair Weather" {
  // ── Seal Skerry ───────────────────────────────────────────────────────────────────────────────────────────────────
  // A low black rock beyond the Holm, by boat only, where the grey seals haul out. Ewan Marrock lives on it alone, by
  // sealing: oil, skins, and the wrack. Seven years ago his wife Morva went, and Skeel says she went back into the sea,
  // being a seal-woman, as everybody knew; and Ewan has let them say it. On the morning after the wreck he found a boy
  // on a hatch in the weed at the haul-out, and has hidden him, because he knows what Skeel is.
  Observe landing_scene at skerry_landing when true "A shelf of black rock with weed on it, slippery, and a ring in the rock to tie up to. Behind it the Skerry humps up, all rock and sea-pinks, with a turf bothy crouched in the lee of it, smoke going sideways from a hole in its roof. Seal-skins are pegged out to dry on the rock, and a coracle lies upside down like a black beetle.".
  Observe haul_scene at haulout when true "The haul-out: a long sloping slab of rock running down into the sea at the Skerry's western end, and lying on it, packed close, like people on a beach on a feast day, the grey seals: forty, fifty, great mottled cows and their white pups and a bull or two as long as a boat, rolling, scratching, groaning, watching you with enormous wet black eyes.".
  Observe haul_evening at haulout as ambience when evening() "As the light goes, the seals begin to sing: a long, rising, falling, human sound, one voice and then another, out across the water, like women calling to each other from boats.".
  Observe bothy_scene at bothy when true "Inside the bothy: smoke, a peat fire, a box bed, a barrel of seal oil, skins, a lamp, and a great deal of order. On a shelf by itself, a woman's comb, and a shell, and a blue ribbon, laid out the way things are laid out in a church.".

  Person ewan "Ewan Marrock" at skerry_landing {
    Role "the sealer of Seal Skerry". Ancestry human. Calling warrior. Level 3. Peaceable. Pronouns he. Manner grim.
    Greets "A big man with a black beard going grey and a sealing-club through his belt is waiting on the rock with his arms folded before your boat has touched. 'There's nothing here for Skeel,' he says. 'No wreck. No dog. No anything. Go home.'".
    Greets again "Ewan Marrock watches you come ashore with his arms folded.".
  }
  Person nye "Nye Gallow" at bothy {
    Role "the Constancy's boy, fourteen, with a bandaged head". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Seen when knows(viewer, nye_known).
    Greets "A boy is sitting up in the box bed in the corner with a blanket round him and a bandage round his head, very white, holding Ewan's sealing-knife in both hands pointed at you. 'I'm not going,' he says. 'I'm not going to Skeel. They'll do me like they want to do the dog.'".
    Greets again "Nye Gallow looks at you, and at the door behind you, to see who else is coming.".
    Joins "Nye Gallow comes, with the blanket round him and the knife in his belt, keeping close.".
  }
  Discovery nye_known "A boy came ashore alive from the Constancy: Nye Gallow, fourteen, her cabin boy, who was washed onto Seal Skerry on a hatch the morning after the wreck. Ewan Marrock has hidden him in his bothy. Under the charter he makes her no wreck.".
  Measure ewanTrust(group). Initially Set ewanTrust(ewan) to 0.
  Relation ewanRows(group).
  Query ewanTrusts() means ewanTrust(ewan) >= 2.

  Topic ewan_skeel with ewan "Ask Ewan Marrock what he has against Skeel" when true once {
    Says "'Against it?' He looks across the water at the town on its headland. 'Nothing. It's a fine town. It buries what the sea sends it under stones that say A SAILOR, and it sings a hymn asking for more.' He spits into the sea. 'And when my wife went, it said she was a seal and had gone back to her own, and laughed at me in the Admiral for seven years. I've nothing against Skeel. I just don't go there.'".
    On discuss { Increase ewanTrust(ewan) by 1. Assert knows(actor, morva_tale). }
  }
  Discovery morva_tale "Seven years ago Ewan Marrock's wife Morva left the Skerry and did not come back. Skeel says she was a seal-woman who went back to the sea; it has laughed at Ewan over it for seven years. He keeps her comb and ribbon on a shelf in his bothy.".
  Topic ewan_seals with ewan "Ask Ewan Marrock about the seals" when true once {
    Says "His arms come unfolded. 'Greys. They come in at the back end to pup. Fifty on the slab this year, more than last.' He looks at them as you might look at a field of your own. 'I take some. Oil and skins. Not the pups, not the cows. Old bulls, past it.' A pause. 'They sing, at night. Did they tell you that in Skeel? Skeel says it's the seal-women singing for their men.' He looks at the haul-out. 'I don't know what it is. I sit out and listen to it.'".
    On discuss { Increase ewanTrust(ewan) by 1. }
  }
  Action ewan_plea(actor: group, site: place) "Tell Ewan Marrock you are not from the Reeve, and you know the boy is here" {
    Speaker ewan.
    Requires able(actor) and at(actor, site) and at(ewan, site) and knows(actor, dog_swims) and not ewanTrusts() and not knows(actor, nye_known).
    Resolve check(actor, persuasion, dc_fair).
    On success { Set ewanTrust(ewan) to 2. }
    Result "He looks at you for a long time, and then at the sea, where the dog swims every tide. 'You followed the dog,' he says. 'Aye. I thought somebody would.' He unfolds his arms. 'Come in, then. Mind him; he has my knife.'".
    Otherwise "'There's no boy here,' he says, flatly. 'There's me and the seals. Go home.'".
  }
  // The dog knows where his boy is.
  Rule dog_finds_nye at skerry_landing when following(admiral, party) and at(party, skerry_landing) and not dogWithNye(admiral) says "Admiral is off the boat before it touches, into the water and up the weed, and across the rock past Ewan Marrock as if he were not there, straight to the bothy door, barking, high and frantic, the way a dog barks only for one person; and from inside a boy's voice cries out a name, and the barking stops." teaches nye_known { Set ewanTrust(ewan) to 2. }
  Rule ewan_shows when ewanTrusts() and not knows(party, nye_known) and at(party, skerry_landing) and at(ewan, skerry_landing) says "Ewan Marrock jerks his head toward the bothy. 'There's a boy in there,' he says. 'Off your wreck. I found him on a hatch in the weed at the haul-out the morning after, more dead than not. I've kept him.' He looks at you hard. 'If you take him to Skeel, you take him over my body. That's all.'" teaches nye_known { }
  Rule dog_reunited when following(admiral, party) and knows(party, nye_known) and at(party, bothy) and not dogWithNye(admiral) says "The boy drops the knife and has his arms round the dog's neck, and his face in the wet black curls, and the dog is making a sound you have not heard a dog make." { Retract following(admiral, party). Assert dogWithNye(admiral). Assert at(admiral, bothy). Assert reunited(nye). }
  Relation reunited(group).
  Observe nye_dog at bothy when dogWithNye(admiral) and at(admiral, bothy) and knows(party, nye_known) "Admiral lies across the foot of the box bed with the boy's feet under him, and will not be moved.".
  // Searching the bothy by force: Ewan will fight for the boy.
  Action force_bothy(actor: group, site: place) "Push past Ewan Marrock into the bothy" {
    Grave "He has told you he will fight, and he will.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, skerry_landing) and at(ewan, skerry_landing) and not ewanTrusts() and not knows(actor, nye_known).
    Time 1 minute.
    On success { Retract peaceable(ewan). Assert assails(ewan, actor). Assert ewanFought(actor). }
    Result "Ewan Marrock takes the club out of his belt.".
  }
  Relation ewanFought(group).
  Rule ewan_beaten when ewanFought(party) and not able(ewan) and not knows(party, nye_known) says "Ewan Marrock is down on the weed, and from the bothy door a boy with a bandaged head is screaming at you to leave him alone." teaches nye_known { }

  // ── Nye ───────────────────────────────────────────────────────────────────────────────────────────────────────────
  Discovery nye_saw "Nye Gallow's account. The Constancy came in from the south at night, steering for a light the master took for the Holm, high up to the south of them. When she struck, the light went out 'as if a hand covered it'. Nye went over the side and held on to a hatch. At low water, in the dark, among the wreckage on the sand, a man came walking with a horn lantern, a tall man in a black coat with marks under his eyes like bruises; he held the lantern up, and saw Nye on the hatch, and looked at him, and turned round and walked away. Then the tide came and took the hatch.".
  Topic nye_story with nye "Ask Nye Gallow what happened to the Constancy" when knows(actor, nye_known) once {
    Says "He tells it with the knife still in his hands, not fast. 'Master Dunn had the Holm light on the chart. And there it was, high up, south, and he said good, that's her, and brought her round for it.' He swallows. 'Mister Ferrar said it was too high. He said it twice. And then she hit, and the whole ship stood up on end, and I went over.' His voice goes very flat. 'And the light went out. Like somebody put their hand over it.' He looks at the fire. 'After, it was low water, and I was on a hatch, on the sand, in the dark, and all the others were — and a man came walking. With a lantern. A horn one. Tall, black coat. Marks under his eyes. He held it up and he saw me. He looked right at me.' The boy's hands are white on the knife. 'And he turned round and walked away.'".
    On discuss { Assert knows(actor, nye_saw). }
  }
  Topic nye_wants with nye "Ask Nye Gallow what he wants" when knows(actor, nye_saw) once {
    Says "'Home.' At once. 'My mam's in Callowport. And Admiral. He's mine; Mister Ferrar gave him me when he was a pup, for the ship.' He looks at the door. 'And I want — ' He stops. 'I want to see that man's face again. I want to look at him. That's all. I want to see if he looks back.'".
    On discuss { Assert nyeWantsFace(nye). }
  }
  Relation nyeWantsFace(group).
  Topic nye_matthew with nye "Ask Nye Gallow about Mister Ferrar" when knows(actor, nye_saw) once {
    Says "'The mate. He was all right.' The boy's mouth works. 'He had a sister he was always on about. Con. The ship's named for her, the figurehead's her when she was little, he said, holding her book. He was taking her a parrot. It was in a cage in his cabin.' He looks away. 'He said the light was too high. He said it twice.'".
    On discuss { Assert knows(actor, matthew_named). }
  }
  Discovery matthew_named "The Constancy's mate was Matthew Ferrar, the owner's son; the ship was named for his sister Constance, and her figurehead is Constance as a child, holding a book. On the night of the wreck he told the master twice that the light was too high.".
  // To the Court. Ewan will bring him, if asked by someone he trusts; or he will come with the company.
  Relation nyeComing(group).
  Topic ask_ewan_court with ewan "Ask Ewan Marrock to bring the boy to the Wreck Court at four o'clock" when knows(actor, nye_saw) and ewanTrusts() and not nyeComing(nye) once {
    Says "He thinks about it a long time, looking at the town. 'In my boat,' he says at last. 'On the flood, at the quay steps. I'll walk him up the Drang myself, and stand by him in the loft, with my club, and we'll see who in Skeel wants to put a hand on him.' He nearly smiles. 'Seven years I've not set foot in that town. It'll be worth it to see their faces.'".
    On discuss { Assert nyeComing(nye). }
  }
  Topic ask_nye_come with nye "Ask Nye Gallow to come with you" when knows(actor, nye_saw) and not following(nye, actor) and not nyeComing(nye) once {
    Says "He looks at Ewan, and Ewan shrugs. The boy gets out of the box bed, slowly, with the blanket round him, and puts the knife in his belt. 'All right,' he says. 'But I keep the knife.'".
    On discuss { Assert following(nye, actor). }
  }
  Rule nye_to_court when nyeComing(nye) and thirdDay() and hour(clock) >= 15 and not courtOver(reach) and not at(nye, net_loft) and not following(nye, party) { Retract at(nye, bothy). Retract at(ewan, skerry_landing). Assert at(nye, net_loft). Assert at(ewan, net_loft). Assert ewanInSkeel(ewan). }
  Relation ewanInSkeel(group).
  Rule dog_to_court when dogWithNye(admiral) and at(nye, net_loft) and not at(admiral, net_loft) { Retract at(admiral, bothy). Assert at(admiral, net_loft). }
  Rule dog_follows_nye when dogWithNye(admiral) and following(nye, party) and not following(admiral, party) { Assert following(admiral, party). }
  // In Skeel before the Court, a boy off the wreck is noticed.
  Rule nye_noticed at fore_street when following(nye, party) and within(party, skeel) and not courtBegun(reach) and not nyeSeen(nye) says "On Fore Street a woman at a door sees the boy with the bandaged head, and looks, and looks again, and goes in fast. By the time you are at the end of the street there are faces at every window, and a man running down the Drang toward the quay." { Assert nyeSeen(nye). }
  Relation nyeSeen(group).

  // ── Morva's letter ────────────────────────────────────────────────────────────────────────────────────────────────
  // Nothing to do with the wreck, except that the Constancy carried the mail. Ewan cannot read.
  Relation letterGiven(group). Relation letterTruth(group). Relation letterLie(group). Relation letterKept(group).
  Topic give_letter with ewan "Give Ewan Marrock the letter from the Constancy's mailbag" when carries(actor, morva_letter) and not letterGiven(ewan) once {
    Says "He takes it and turns it over in his big hands and runs a thumb along the lines of writing as if they were a rope he was testing, and then fits it to the thumbprint in the tallow. 'That's her hand,' he says. 'She wrote big, she never learned it right.' He holds it out to you again. 'I can't read it. I never could. Morva could, a bit; she said she'd teach me.' His voice is quite steady. 'You read it. Tell me what it says.'".
    On discuss { Assert letterGiven(ewan). Spend letter_morva from actor. }
  }
  Topic read_true with ewan "Read Ewan the letter as it is written" answering give_letter when letterGiven(ewan) once {
    Says "You read it to him. It is not long. Morva is in Callowport, in the south, in service at an inn. She went because she could not bear the Skerry any longer, the wind and the quiet and the seals, and she was ashamed to say so, and so she said nothing, and went. She has a daughter. The daughter is six. 'She has your hands,' the letter says, 'and she is afraid of nothing, and I have told her about the seals.' She asks him to forgive her if he can, and if he cannot, to write and say so, and she will not trouble him again. There is no more. Ewan sits on the rock with his hands hanging between his knees. 'Six,' he says. After a long time: 'Afraid of nothing.' The seals have begun to sing, out on the slab. He does not seem to hear them.".
    On discuss { Assert letterTruth(ewan). }
  }
  Topic read_lie with ewan "Tell Ewan the letter says she is happy in the sea, and he is not to wait" answering give_letter when letterGiven(ewan) once {
    Grave "He will believe you. He will never ask anyone else to read it.".
    Says "You tell him that. He listens, and nods slowly, and nods. 'Aye,' he says. 'Aye, I thought so.' He takes the letter back from you, very carefully, and goes into the bothy and puts it on the shelf beside the comb and the ribbon, and comes out, and sits down on the rock to listen to the seals; and for the first time since you came to the Skerry he looks almost at peace.".
    On discuss { Assert letterLie(ewan). }
  }
  Topic read_none with ewan "Tell Ewan you will not read another's letter to him; let him find someone he trusts" answering give_letter when letterGiven(ewan) once {
    Says "He looks at you, and then at the letter, and nods. 'Fair,' he says. He puts it inside his shirt, against his skin. 'Hosken can read. I'll ask Hosken.' He looks across the water at the church on the headland. 'Seven years,' he says. 'I'll have to go into Skeel.'".
    On discuss { Assert letterKept(ewan). }
  }
  Relation ewanGoesSouth(group).
  Topic ewan_south with ewan "Ask Ewan Marrock what he will do" when letterTruth(ewan) once {
    Says "'Go south.' He says it as if it surprised him. 'There's a packet, the girl's coming on, Ferrar's, for her brother. Goes back on the fourth tide. I'll ask them for a passage, and work it.' He looks round at the Skerry, the bothy, the seals. 'Six. She'll not know me.' Then: 'Will you take the boat, after? Somebody should. The seals know it.'".
    On discuss { Assert ewanGoesSouth(ewan). }
  }
  Action listen_seals(actor: group, site: place) "Sit on the rock and listen to the seals sing" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, haulout) and evening() and not heardSeals(actor).
    Time 6.
    On success { Assert heardSeals(actor). }
    Result "You sit on the cold rock with your arms round your knees while the light goes out of the sky, and the seals sing. It is not like anything. It rises and falls and breaks off and is taken up further along the slab, one voice and then many, and dies away, and begins again; and out on the dark water, very far off, something answers it. You understand why Skeel says what it says about the seal-women. You understand why Ewan Marrock sits out here every night and has never once told anyone whether he believes it.".
  }
  Relation heardSeals(group).
}

data/adventures/skeel/tide.kyr:
Module skeel "Fair Weather" {
  // ── The days ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // Counted from the company's coming, at each dawn after the first hour it is here: the day it comes is the first.
  // The Constancy struck three nights before. The Wreck Court sits at four on the third day, on the flood.
  Measure dayN(place). Relation dawned(place).
  Initially Set dayN(reach) to 1.
  Rule dawn_counts when hour(clock) == 6 and not dawned(reach) and watch(clock) >= 6 { Increase dayN(reach) by 1. Assert dawned(reach). Increase lag(reach) by 1. }
  Rule dawn_passes when hour(clock) != 6 and dawned(reach) { Retract dawned(reach). }
  Query firstDay() means dayN(reach) == 1.
  Query secondDay() means dayN(reach) == 2.
  Query thirdDay() means dayN(reach) == 3.
  Query evening() means hour(clock) >= 18 and hour(clock) < 23.
  Query daylight() means hour(clock) >= 6 and hour(clock) < 20.

  // ── The tide ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // Low water comes an hour later each day: on the first day the Strand stands dry from nine until one, and from nine at
  // night until one in the morning; on the second from ten, and so on, for four days, when the springs come round again
  // and it is back to nine. tide(reach) is the hour, put back by the day's lateness, and twenty-four on, so that it is
  // never below nothing: the morning low water is 33 to 37, the night's is 45 and over, or under 25.
  Measure lag(place). Measure tide(place).
  Initially Set lag(reach) to 0. Initially Set tide(reach) to 32.
  Rule springs_return when lag(reach) >= 4 { Set lag(reach) to 0. }
  Rule tide_reckoned when tide(reach) != hour(clock) + 24 - lag(reach) { Set tide(reach) to hour(clock) + 24 - lag(reach). }
  Query lowWater() means tide(reach) >= 33 and tide(reach) < 37 or tide(reach) >= 45 or tide(reach) < 25.
  // Slack: the middle of low water, an hour each side of the bottom of the ebb, when the Gut stops running through the Sill.
  Query slack() means tide(reach) >= 34 and tide(reach) < 36 or tide(reach) >= 46 or tide(reach) >= 22 and tide(reach) < 24.
  // The last hour before the flood.
  Query turning() means tide(reach) == 36 or tide(reach) == 24.
  // The harbour dries at low water: the boats sit on the mud on their legs. Jinny Rowse sails by day, round high water.
  Query boatsRun() means not lowWater() and hour(clock) >= 6 and hour(clock) < 21.
  Query onSands(g: group) means at(g, flats) or at(g, scarth) or at(g, gut_lip) or at(g, sill).
  // A company already crossing when the sea comes keeps its way: it is between two places, and the sea is between it and both.
  Query sandsOpen() means lowWater() or onSands(party) or enRoute(party, ?w).

  // The tide-board on the quay: the hours of low water, chalked fresh each morning by the harbourmaster's boy.
  Discovery tide_known "The Strand stands dry for four hours at each low water, morning and night, and low water comes an hour later every day; the harbour dries at the same time, and boats can only sail round high water." {
    Source board_reading "the tide-board" at quay readable by party.
  }
  Observe board_today at quay as sign when lag(reach) == 0 "On the harbour wall a black tide-board, chalked fresh this morning: LOW WATER 11 AND 11. SANDS FROM 9. Under the chalk, painted and peeling: KEEP THE WITHIES. THE STRAND GIVES FOUR HOURS. THE SEA TAKES THE FIFTH.".
  Observe board_today1 at quay as sign when lag(reach) == 1 "On the harbour wall the tide-board, chalked fresh this morning: LOW WATER 12 AND 12. SANDS FROM 10.".
  Observe board_today2 at quay as sign when lag(reach) == 2 "On the harbour wall the tide-board, chalked fresh this morning: LOW WATER 1 AND 1. SANDS FROM 11.".
  Observe board_today3 at quay as sign when lag(reach) == 3 "On the harbour wall the tide-board, chalked fresh this morning: LOW WATER 2 AND 2. SANDS FROM 12.".

  // ── What the water looks like, from where the company is ──────────────────────────────────────────────────────────
  Observe reach_low at slip as weather when lowWater() and daylight() "The sea has gone out of the Reach. The Strand lies ribbed and shining for miles, cut by the dark line of the Gut, with the Holm and its Lantern standing up out of it, and the wreck on Scarth Bank, and far off the Craigs. Gulls walk on it like people.".
  Observe reach_high at slip as weather when not lowWater() and daylight() "The sea is in. Where the Strand was there is grey water to the Craigs, with the Holm standing in it, and the wreck's stern, and a line of withy-tops showing like a hedge drowned to the eyes.".
  Observe reach_dark at slip as weather when not daylight() "The Reach is out there in the dark. You hear it breathe in over the Strand and breathe out, and you know where the Holm is only by where the sound changes.".
  Observe sands_low at flats when lowWater() "Ribbed sand to every side, hard as a road where the withies are and softer off them, shining wet. Each ripple holds a thread of water. A line of laurel branches stuck upright leads away across it, one every twenty paces, toward the Holm, toward Scarth Bank, toward the Gut, toward the Craigs.".
  Observe sands_flood at flats when not lowWater() "The sea is coming over the Strand. It does not come as waves; it comes as a sheet, an inch deep and then a foot, faster than you can walk, from every side at once, with a hiss like frying.".
  Observe sands_dark at flats as ambience when not daylight() and lowWater() "In the dark the withies are the only thing: you go from one to the next with your hand out, and between them there is nothing at all.".
  Observe sands_turning at flats as sign when turning() "The ripples have begun to fill. Far out, toward the Gut, there is a line on the sand that was not there before, white, and it is moving.".
  Observe lip_scene at gut_lip when lowWater() "The Strand ends at a bank of soft grey sand, and below it the Gut runs, a channel sixty yards wide that the tide never empties, green-black and moving. Across it, low and brown, is Inish Gall, with a stone house and a cairn. Downstream the water breaks white over a bar of stones: the Sill, the one place a man can wade it.".
  Observe sill_scene at sill when true "Water to the thigh, cold enough to stop your breath, pulling at you toward the sea. Under your feet the stones of the Sill shift and settle. Upstream the Gut is deep and green; downstream it falls away into the dark.".
  Observe sill_running at sill as sign when not slack() "The current has your shins and wants the rest of you. The stones turn under your boot like loaves.".
  Observe sill_slack at sill as sign when slack() "The water has stopped in the Gut. A strand of weed that was streaming toward the sea hangs straight down, and for a few minutes you could cross in your sleep.".

  // ── The flood ─────────────────────────────────────────────────────────────────────────────────────────────────────
  // A company out on the sands when the sea comes is struck by the water every watch until it gets to high ground: the
  // Holm, the Craigs, Inish, the wreck's stern, or back up the Slip.
  Hazard flood_water "The flood over the Strand" means "Deal (1d6) physical damage to ally unless constitution save against (12).".
  Hazard gut_water "The Gut running through the Sill" means "Deal (2d6) physical damage to ally unless strength save against (14).".
  Rule flood_warns when onSands(party) and turning() and not warnedTurn(party) says "Out across the sand, from the direction of the sea, there is a sound like a long breath let out. The tide has turned." { Assert warnedTurn(party). }
  Rule flood_reset when not onSands(party) and warnedTurn(party) { Retract warnedTurn(party). }
  Relation warnedTurn(group).
  Rule flood_strikes when onSands(party) and not lowWater() and not at(party, sill) says "The sea is round your knees and pulling, and then round your waist. Somewhere behind you a withy goes under." { Assert strikes(flood_water, party). Assert caughtByFlood(party). }
  Rule gut_strikes when at(party, sill) and not slack() says "The Gut takes your legs. For a long moment there is nothing under you, and then there are stones, and you are further downstream than you were." { Assert strikes(gut_water, party). }
  Relation caughtByFlood(group).

  // ── The withies, and the sinking sand off them ────────────────────────────────────────────────────────────────────
  // Cuddy Pascoe sets the withies after every big tide. Off them, at the edges of the Strand, the sand will take a leg
  // to the thigh, and then hold it while the tide comes. Whoever has walked the way with him, or learned it from Malachy
  // Sennen, keeps to them; a stranger walking alone may not.
  Discovery withy_way_known "The way over the Strand is the line of laurel withies Cuddy Pascoe sets out; keep them on the right going out and the left coming in, never walk between two that are more than twenty paces apart, and where the sand shines dull instead of wet, go round.".
  Hazard sinking_sand "The sinking sand" means "Deal (1d6) physical damage to ally unless dexterity save against (12).".
  Relation sankHere(group). Relation guided(group).
  Rule quick_takes at flats when at(party, flats) and not knows(party, withy_way_known) and not guided(party) and not sankHere(party) and dice(clock) <= 60 says "Ten paces off the withies the sand goes soft as butter and takes you to the knee, and then to the thigh, and holds. It takes a long, frightening time, and all your strength, to get out of it, and you leave a boot-full of sand behind." { Assert strikes(sinking_sand, party). Assert sankHere(party). }
  Rule quick_spared at flats when at(party, flats) and not sankHere(party) { Assert sankHere(party). }
  Rule quick_reset when not onSands(party) and sankHere(party) { Retract sankHere(party). }
  Rule guide_lapses when guided(party) and (at(party, quay) or at(party, fore_street) or within(party, holm) or within(party, craigs) or within(party, inish) or within(party, coast)) { Retract guided(party). }
}

data/adventures/skeel/tracks.kyr:
Module skeel "Fair Weather" {
  Description "What a ranger can read in the Pulpit that nobody else would look at: the print of a boot in the red clay, and whose boot it was. A second way to the same truth as the boy's, by the ground and not the sea.".

  // ── The ranger's way ────────────────────────────────────────────────────────────────────────────────────────────
  // The boy on Seal Skerry saw what the Reeve did on the Strand. The ground in the Pulpit saw what he did before it:
  // the hook, the lantern, and the man who stood there a long time, and then ran. Anyone can see the hook (it is on the
  // Pulpit's list of things to look at). Only someone who reads ground sees the man.
  Discovery boot_prints "In the lee of the Pulpit's back wall, in a skin of red clay that the wind cannot reach, the print of a left boot, iron-heeled, with the third nail of the heel missing: a tall man, standing a long time, and then going down the edge faster than he came up.".
  Action read_pulpit_ground(actor: group, site: place, r: member) "Read the clay in the lee of the Pulpit's back wall" {
    Description "Everything else up here has been scoured by the wind. There is one place it does not reach.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pulpit) and memberOf(r, actor)
      and hasCalling(r, calling_ranger) and awake(r) and knows(actor, hook_found) and not knows(actor, boot_prints).
    Time 3.
    On success { Assert knows(actor, boot_prints). }
    Result "{r} goes down on hands and knees in the niche, with the wind shouting overhead, and puts a cheek almost to the rock. In the angle of the back wall the clay is red and damp and has kept something. 'There,' {r} says. 'One man, tall, left foot a shade turned in. He stood here from before the moon was up till the ship struck. Look how deep the toes are: he was leaning on the hook.' A finger hovers over the heel. 'Iron on the heel, and the third nail gone, so the print has a bite out of it.' Then, lower: 'And the next prints are twice as far apart.'".
  }
  Observe boots_by_the_stove at reeve_parlour when knows(party, boot_prints) "A pair of big black boots stands by the parlour stove, drying, the left one worn down on its outer edge. The iron on the left heel is short of a nail; the third one is gone, and has left a bite. Red clay is dried in the welt, the red that is only on the Craigs path." teaches boots_match.
  Discovery boots_match "The Reeve's left boot has its third heel-nail missing, and Craigs clay in the welt: the same boot that stood in the Pulpit.".
  Rule put_together_boots when knows(party, hook_found) and knows(party, boot_prints) and knows(party, boots_match) and not knows(party, hender_did)
    says "A hook driven new into a crack, and a boot-print with a bite out of the heel, and the same bite in a boot that dries by a stove in Fore Street. You did not need a boy on a hatch to tell you whose. You need only to know that he stood there a long time first." teaches hender_did { }

  // ── The ranger's ear ────────────────────────────────────────────────────────────────────────────────────────────
  // Said once for the company, by whoever it has of the calling. A company without a ranger walks the same ground deaf.
  Relation heardSand(group). Relation heardGannets(group). Relation heardHolmShore(group). Relation heardHaulout(group).
  Rule ranger_sand at flats when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, flats) and not heardSand(party)
    says "{?m} walks twenty paces along the wrack line and stops, and looks back at the prints. 'Everything on this sand is a day old at most,' {?m} says. 'The tide sees to that. Whatever was done out here was done since the last ebb, or it was not done on the sand.'" {
    Assert heardSand(party).
  }
  Rule ranger_gannets at clifftop when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, clifftop) and not heardGannets(party)
    says "{?m} watches the gannets fold and drop for a long minute without a word. 'They fish the line where the two tides meet,' {?m} says. 'That is the only chart the birds need. Anyone who could read it could tell you where the bar is deepest. I wonder who in Skeel does.'" {
    Assert heardGannets(party).
  }
  Rule ranger_holm at holm_shore when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, holm_shore) and not heardHolmShore(party)
    says "{?m} crouches by the Holm's landing and turns a handful of the shingle over. 'Dry,' {?m} says. 'Dry at the top and wet at the bottom, as it should be. And no weed above the line, where it would be if anyone had been carrying wet things up from a boat.' A beat. 'Nobody has carried anything up from a boat here for a long time. Whoever tends the lamp does not come this way.'" {
    Assert heardHolmShore(party).
  }
  Rule ranger_haulout at haulout when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, haulout) and not heardHaulout(party)
    says "{?m} lies flat on the rock a good way off and watches the seals without moving a hand. 'Cows to the middle, bulls to the edge, pups where it is dry,' {?m} says. 'Somebody has counted these for years and never driven them. If I were selling oil I would never have thought to leave the pups.'" {
    Assert heardHaulout(party).
  }
}

data/adventures/skeel/wreck.kyr:
Module skeel "Fair Weather" {
  // ── The Constancy on Scarth Bank ──────────────────────────────────────────────────────────────────────────────────
  Observe scarth_scene at scarth when true "The Constancy lies on her side on Scarth Bank with her back broken, her bow half buried and her stern cocked up in the air higher than a house, so that you walk under her counter as under a cliff. Her planking has sprung along the turn of the bilge and you can see into her: the ribs, the hold, the black inside of a ship. Weed has started on her already. The sand round her is trodden to porridge by boots and cartwheels.".
  Observe scarth_saint at scarth as feature when not saintTaken(reach) "Down at the buried end, with the sand to her waist, is her figurehead: a girl of nine or ten, carved and painted, in a blue dress, holding an open book against her chest. The paint on her face is quite fresh. Somebody has tied a rope round her, ready, and not pulled.".
  Relation saintTaken(place).
  Observe scarth_work at scarth as ambience when lowWater() and salvaging() "Twenty people of Skeel are at work on her: men in the hold passing up casks, women with barrows, boys on the yards cutting down what is left of her rigging. They work fast and do not talk much, and every so often somebody looks at the sea.".
  Observe scarth_quiet at scarth as ambience when lowWater() and not salvaging() "There is nobody at her now. She has been stripped to the ribs.".
  Query salvaging() means not courtOver(reach) and daylight().
  Observe stern_scene at stern when true "You are up on the Constancy's stern, on the tilted deck, holding on. The great cabin is below you through a hatch, its stern windows broken out: a table bolted to the floor, a bunk, a bird-cage with its door open and no bird. Everything that could be carried has been carried. From up here the whole Reach is laid out round you, and you can see why a ship coming in from the south at night would want a light to steer by.".
  Observe stern_cage at stern as feature when true "On the cage a brass plate: DICKON.".
  Observe stern_sea at stern as weather when not lowWater() "The sea is all round the wreck, grey and moving. The ladder goes down into it. You are on an island the size of a cart, and it creaks.".

  // A night on the stern: the tide in, the dark, the ship talking. Told an hour at a time.
  Measure sternSince(group). Initially Set sternSince(party) to 0.
  Relation sternNight(group).
  Rule stern_begins when at(party, stern) and not lowWater() and not daylight() and not sternNight(party) and sternHours(party) < 6 { Assert sternNight(party). Set sternSince(party) to watch(clock). Set sternHours(party) to 1. }
  Rule stern_ends when sternNight(party) and not at(party, stern) { Retract sternNight(party). }
  Measure sternHours(group). Initially Set sternHours(party) to 0.
  Rule stern_later when sternNight(party) and sternHours(party) == 2 and watch(clock) >= sternSince(party) + 6 { Set sternHours(party) to 3. }
  Rule stern_latest when sternNight(party) and sternHours(party) == 4 and watch(clock) >= sternSince(party) + 12 { Set sternHours(party) to 5. }
  Rule stern_one at stern when at(party, stern) and sternHours(party) == 1 and not lowWater() says "The wreck moves under you, once, very slowly, like a sleeper turning over. Down in the hold, something heavy rolls from one side to the other, and stops." { Increase sternHours(party) by 1. }
  Rule stern_two at stern when at(party, stern) and sternHours(party) == 3 and not lowWater() says "Something is knocking on the hull, below the waterline. Not regular, the way a loose cask would knock. Three knocks, then nothing, then two." { Increase sternHours(party) by 1. }
  Rule stern_three at stern when at(party, stern) and sternHours(party) == 5 and not lowWater() says "You understand what is knocking, and wish you did not. The Constancy's people are under her. The tide has brought them back to her, the way the tide brings everything back, and they are caught in the rigging that hangs down her side into the water, and the sea moves them against the planks. Eleven men. You sit with your back against the cabin hatch and listen to them asking to come in." teaches crew_under { Increase sternHours(party) by 1. }
  Discovery crew_under "The Constancy's drowned are caught under her in the trailing rigging; the tide moves them against her hull.".

  // Salvage: a stranger can work on the wreck at low water for a day's share, as anybody in Skeel does.
  Measure workedDay(group). Initially Set workedDay(party) to 0.
  Relation salvaged(group).
  Action work_wreck(actor: group, site: place) "Work on the wreck for a stranger's share" {
    Description "Passing casks up out of the hold, and bales, and whatever else is still in her. Four coin, paid at the Wreck-House.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, scarth) and lowWater() and salvaging()
      and not turning() and workedDay(actor) != dayN(reach).
    Time 6.
    Resolve check(actor, brawn, dc_easy).
    On success { Increase quantity(actor, gold) by 4. Set workedDay(actor) to dayN(reach). Assert salvaged(actor). }
    On failure { Increase quantity(actor, gold) by 2. Set workedDay(actor) to dayN(reach). Assert salvaged(actor). }
    Result "You work an hour and more in the hold of the Constancy, up to your knees in water and wet grain, passing casks up a chain of hands. The men beside you are careful and quick and kind to you, and do not talk about anything. When the tide-bell rings at the Slip they stop all at once, as if a string had been cut, and walk. Big Jack Cawse pays you on the sand out of a bag: four coin, the stranger's share.".
    Otherwise "You are slower than the Skeel men, and drop a cask, and it bursts and runs red into the bilge, wine, and a man laughs at you, not unkindly. Big Jack Cawse pays you two coin on the sand, the slow stranger's share.".
  }
  Rule cawse_out when salvaging() and lowWater() and not turning() and at(cawse, wreck_house) and not courtSitting() { Retract at(cawse, wreck_house). Assert at(cawse, scarth). }
  Rule cawse_in when (not lowWater() or turning() or not salvaging()) and at(cawse, scarth) { Retract at(cawse, scarth). Assert at(cawse, wreck_house). }
  Topic salvage_talk with cawse "Ask Jack Cawse why the men don't talk on the wreck" when salvaged(actor) once {
    Says "'Bad luck.' He weighs the coin-bag. 'You don't talk on a dead ship. They can hear you.' He looks at you to see if you'll laugh, and you don't, so he goes on. 'My grandad said you sing the Psalm under your breath, and you never take anything off a wreck with your left hand, and you don't look at the saint.' He jerks his head toward the figurehead in the sand. 'That one's been looking at me two days.'".
  }

  // The saint: the Reeve's to give. Whoever has her raised sets her on their gable.
  Kind saint_kind "the Constancy's figurehead" is treasure worth 0 weighing 40
    described "A carved girl of nine or ten in a blue dress, holding an open book against her chest. On the open pages, very small, someone has carved the words CONSTANT AND TRUE. She is wet and heavy and smells of the sea.".

  // ── The Wreck-House ───────────────────────────────────────────────────────────────────────────────────────────────
  Observe wh_scene at wreck_house when true "A stone barn with iron-bound doors, built for salvage. It is full to the rafters: grain in sacks stacked to the beams, casks of wine in rows on their sides, wet bales of cloth, a ship's bell, coils of cable, a binnacle, chairs, a harmonium, a crate of something stencilled WITH CARE in a southern hand. Everything is chalked with a number. On a table by the door is a great book, and a lamp, and the Reeve.".
  Observe wh_grain at wreck_house as feature when not courtOver(reach) "The smell of the grain is sweet and heavy and fills the place. There is enough in here, you think, to feed a town through a winter. That is what it is for.".
  Observe wh_empty at wreck_house when courtOver(reach) and cargoToOwners(reach) "The Wreck-House is half empty. The grain has gone down to the quay in carts, to the packet, consigned to Ferrar and Daughters.".
  Person cawse "Big Jack Cawse" at wreck_house {
    Role "the Reeve's man". Ancestry human. Calling warrior. Level 2. Peaceable. Pronouns he. Manner jovial.
    Greets "A very large young man with a cudgel stuck in his belt, who stands up when you come in, and then sits down again when he sees you are not anybody. 'Reeve's busy,' he says.".
    Greets again "Big Jack Cawse touches his cudgel, the way another man would touch his hat.".
  }
  Observe cawse_sore at wreck_house when beatLads(party) and at(cawse, wreck_house) "Big Jack Cawse has a split lip, which is his brothers' and which he is wearing for them, and he watches you the whole time you are in the Wreck-House.".
  Topic cawse_lantern with cawse "Ask Jack Cawse what he wants" when true once {
    Says "He thinks about it seriously. 'The Lantern,' he says. 'Reeve says he'll ask the Court for it, for me, when Loveday's turned off. Three coin a week and the house on the Holm and nobody bothers you.' He grins. 'And you can see everything that comes into the Reach, first.'".
    On discuss { Assert knows(actor, cawse_lantern_known). }
  }
  Discovery cawse_lantern_known "The Reeve means to ask the Wreck Court to turn Loveday Kitto off the Lantern for letting it go dark, and give it to Jack Cawse.".

  // ── Hender Brask ──────────────────────────────────────────────────────────────────────────────────────────────────
  Person hender "Hender Brask" at wreck_house {
    Role "the Wreck-Reeve of the Gannet Reach". Ancestry human. Calling warrior. Level 3. Peaceable. Pronouns he. Manner stoic.
    Greets "A tall man of fifty in a good black coat, with the book open in front of him and a pen in his hand. He has a very still, careful face, and has not slept; the skin under his eyes is the colour of a bruise. 'Hender Brask, the Admiral's Reeve,' he says, and writes a number before he looks up. 'If you have come to buy, the sale is the day after tomorrow. If you have come to sell, I do not buy. If you have come off the coast road to look at the wreck, everyone does, and you are welcome.'".
    Greets again "Hender Brask looks up from the book, and finishes the number he was writing first.".
  }
  // Where he is: the Wreck-House by day; the church at the end of the day, oiling the charter; his parlour at night.
  Rule hender_church when hour(clock) >= 18 and hour(clock) < 20 and not courtSitting() and henderFree() and not at(hender, church) { Retract at(hender, wreck_house). Retract at(hender, reeve_parlour). Assert at(hender, church). }
  Rule hender_home when (hour(clock) >= 20 or hour(clock) < 8) and henderFree() and not at(hender, reeve_parlour) { Retract at(hender, church). Retract at(hender, wreck_house). Assert at(hender, reeve_parlour). }
  Rule hender_work when hour(clock) >= 8 and hour(clock) < 18 and not courtSitting() and henderFree() and not at(hender, wreck_house) { Retract at(hender, church). Retract at(hender, reeve_parlour). Assert at(hender, wreck_house). }
  Query henderFree() means not henderGone(hender) and not henderAtSale().
  Relation henderGone(group).
  Observe hender_oils at church when at(hender, church) and not henderConfessed(hender) "Hender Brask is at the charter board with a rag and a dish of linseed oil, working it into the gilt letters one at a time, slowly, as a man does a thing he has done every week of his life.".

  Topic hender_wreck with hender "Ask Hender Brask about the wreck" when true once {
    Says "'The Constancy, Ferrar's of the south, master Abel Dunn, four hundred tons, grain and wine and sundries.' He says it like an entry. 'She stood into the Reach in the night on a false reckoning and struck Scarth Bank. The Lantern was not lit.' His pen does not move. 'Loveday Kitto is seventy-three. She fell asleep. It is nobody's fault, and it is the end of her keeping, and I am sorry for it; she was good to me when I was a boy.'".
    On discuss { Assert knows(actor, wreck_known). Assert knows(actor, cawse_lantern_known). }
  }
  Topic hender_charter with hender "Ask Hender Brask about the charter" when knows(actor, charter_known) once {
    Says "For the first time he looks fully at you. 'It is the best law I know,' he says. 'Short. Plain. Nobody can argue it. If a thing lives, she's theirs; if nothing lives, she's ours. It doesn't care who is hungry, or who is owed, or who is sorry. It just counts.' He puts the pen down. 'I oil the board myself. My father taught me to read on it.'".
  }
  Topic hender_dog with hender "Ask Hender Brask about the dog on the sands" when knows(actor, dog_known) once {
    Says "'A black dog has been seen on the Strand worrying the Holm sheep.' He picks the pen up again. 'There's a shilling on it at the Wreck-House for whoever brings it in. That is all.' He writes a number. He does not look up. 'It is not the Constancy's dog. The Constancy had no dog.'".
  }
  Topic hender_father with hender "Ask Hender Brask about his father" when knows(actor, pilot_son) once {
    Says "Something goes out of his face, and comes back. 'Jacob Brask was a pilot. The best on the Reach. When the Admiral let the station go he had nothing to do with what he knew, and he drank, and one night he took the gig out and I suppose he went where he was going.' He closes the book. 'I learned something from him, which is that the Reach does not want pilots. It wants wrecks. It has wanted wrecks for forty years. I have only ever given it what it wants, honestly, by the book.'".
  }
  Topic hender_hunger with hender "Ask Hender Brask what becomes of Skeel if the Constancy is not wreck" when knows(actor, hunger_known) once {
    Says "'Then her owners have their grain back, and are glad of it, I am sure.' He spreads his hands flat on the book. 'And we have two failed seasons and the Admiral's factor at Martinmas, and a Lowland salt company on the Strand by spring, and the children of this town eating limpets off the Holm by February. I have counted it. I have counted it many times.' He looks at the stacked sacks, and his voice is very quiet. 'I have counted every grain in this building.'".
  }
  Relation watchedHands(group).
  Action watch_hender(actor: group, site: place) "Watch Hender Brask's hands while he talks of the Lantern" {
    Requires able(actor) and company(actor) and at(actor, site) and at(hender, site) and not watchedHands(actor) and knows(actor, wreck_known).
    Time 1 minute.
    Resolve check(actor, insight, dc_fair).
    On success { Assert watchedHands(actor). Assert knows(actor, hender_shaken). }
    On failure { Assert watchedHands(actor). }
    Result "His voice is steady; it is a good voice for numbers. His hands are not. Each time he says the word Lantern his right hand closes, very slightly, on the pen, as if on the handle of something that is burning him; and each time he says Loveday he puts the pen down altogether. Grief, you think. Or not only grief.".
    Otherwise "He talks well and evenly, and if there is anything under it, you do not see it.".
  }
  Discovery hender_shaken "Hender Brask's hands close on his pen whenever he names the Lantern, and he cannot hold it at all when he names Loveday Kitto.".
  // Hender's offer: to a stranger he has seen out on the sands, on the second day.
  Relation henderOffered(group). Relation dogDeal(group).
  Topic hender_offer with hender "Ask Hender Brask whether there is work for a stranger" when secondDay() and knows(actor, dog_known) and not dogDealt(admiral) and not dogPenned(admiral) once {
    Says "He looks at you for a long moment, as if adding you up. 'You have been out on the Strand,' he says. 'You walk it well enough. The dog that has been worrying the Holm sheep is out there, and the town's boys cannot get near it.' He takes a shilling from the drawer and lays it on the book, and beside it, slowly, four more coins. 'A shilling for the dog, at the Wreck-House, before the Court sits. And a stranger's portion of the Admiral's third, which is mine to give, at the Court. Twelve coin, perhaps more.' He does not look away. 'It is a sheep-worrier. You understand me.'".
    On discuss { Assert henderOffered(actor). }
  }
  Topic take_offer with hender "Tell Hender Brask you will see to the dog" answering hender_offer when henderOffered(actor) once {
    Grave "Admiral is the only living thing in Skeel's way, and the town would thank you for it in its stomach and never in its church.".
    Says "He nods, once, and puts the coins back in the drawer, all but the shilling. 'Before the Court sits,' he says. 'The Gut is deep, off the Sill.' He goes back to his writing, and you see that his hand is not steady, and that he sees you see it.".
    On discuss { Assert dogDeal(actor). }
  }
  Topic refuse_offer with hender "Tell Hender Brask you do not do that kind of work" answering hender_offer when henderOffered(actor) once {
    Says "'No,' he says. 'No, I did not think you did.' He puts the shilling back in the drawer. 'Forgive me. I have not slept.'".
  }

  // The mailbag: the drowned's letters, which nobody in Skeel will pay a farthing for.
  Kind mailbag_kind "the Constancy's mailbag" is gear worth 0 weighing 4
    described "A canvas bag with a brass lock, sodden and salt-white, stencilled FERRAR'S PACKET: MAILS. Inside, letters going north and south, some swollen to pulp and some still legible.".
  Item mailbag "the Constancy's mailbag" is mailbag_kind at wreck_house owned by hender.
  Topic ask_mailbag with hender "Ask Hender Brask for the Constancy's mailbag, for the families of the drowned" when true once {
    Says "He looks at the bag on its hook. 'The mails are not wreck,' he says, almost to himself. 'The charter does not reach to letters. They are nobody's.' He gets up and takes it down and holds it a moment. 'I read them, you know. Everybody's letters, all my life, for those who can't. I have not opened this one.' He holds it out. 'Take it. Do what is right with them. I find I cannot.'".
    On discuss { Assert lends(hender, mailbag, actor). Give mailbag to actor. Assert mailbagGiven(hender). }
  }
  Relation mailbagGiven(group).
  Relation bagRead(group).
  Action read_mailbag(actor: group, site: place) "Go through the Constancy's mailbag" {
    Description "Letters of the living, carried by the dead.".
    Requires able(actor) and company(actor) and at(actor, site) and carries(actor, mailbag) and not bagRead(actor) and not benighted(actor).
    Time 3.
    On success { Assert bagRead(actor). Give morva_letter to actor. }
    Result "You go through the mailbag, letter by letter. Most are pulp. Some are not: a bill for forty yards of sailcloth; a mother in the north writing to her son that the cow has calved; a love letter so explicit that you put it back. And one, in a large uncertain hand, folded small and sealed with a thumbprint in tallow, addressed to EWAN MARROCK, THE SEAL SKERRY, THE GANNET REACH, BY KINDNESS OF ANY SAILOR. It has been paid for twice, in two different ports.".
  }
  Kind letter_morva "a letter for Ewan Marrock" is gear worth 0 weighing 0
    described "A letter folded small and sealed with a thumbprint in tallow, addressed to EWAN MARROCK, THE SEAL SKERRY. The postmark is from a southern port. It has been paid for twice.".
  Item morva_letter "the letter for Ewan Marrock" is letter_morva at limbo.

  // ── The sale ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // On the second morning the Reeve sells, on the quay, what will not keep or will not go to market: lots unopened, as
  // they lie. The town bids against itself with wreck money it has not yet been paid.
  Query henderAtSale() means occasionBegun(sale) and not occasionOver(sale).
  Occasion sale "the Wreck Sale" at quay when secondDay() and hour(clock) >= 9 and not henderConfessed(hender) {
    Matter lot_cask "Hender Brask, on a barrel with the book under his arm, calls the first lot: 'A cask, unmarked, wet. Sound, by the knock of it. Two coin? Two coin for the cask.' Somebody at the back says, 'It's water,' and the quay laughs." for 20 minutes until lotSold(lot_cask).
    Matter lot_crate "'Lot two. A crate, small, very heavy for its size, stencilled WITH CARE, in the southern hand.' He rocks it with his foot, and it clinks, finely, like a great many small things. 'Glass. Three coin?' Mother Jago, at the front, puts her hand up." for 20 minutes until lotSold(lot_crate).
    Matter lot_chest "'Lot three.' He hesitates over this one. 'A sea-chest. Officer's. The lid is cut with two letters, M and F. Locked; the key's at the bottom of the Reach. Contents unknown.' Jack Cawse says, 'A shilling,' and nobody else says anything." for 20 minutes until lotSold(lot_chest).
    Closes "Hender Brask closes the book, and gets down off the barrel, and the quay goes back to its work.".
  }
  Relation lotSold(matter).
  Observe sale_on at quay when henderAtSale() "The quay is crowded. Hender Brask stands on a barrel with the book under his arm and sells the drowned's things to the drowned's finders, one lot at a time, in the voice he uses for numbers.".
  Action bid_cask(actor: group, site: place) "Bid two coin for the cask" {
    Requires able(actor) and at(actor, site) and at(actor, quay) and matterOpen(lot_cask) and quantity(actor, gold) >= 2.
    Time 1 minute.
    On success { Decrease quantity(actor, gold) by 2. Assert lotSold(lot_cask). Give wine_cask to actor. }
    Result "'Two coin, to the stranger.' The quay laughs again. Somebody tells you to mind it's not water.".
  }
  Action bid_crate(actor: group, site: place) "Bid four coin for the crate, over Mother Jago" {
    Requires able(actor) and at(actor, site) and at(actor, quay) and matterOpen(lot_crate) and quantity(actor, gold) >= 4.
    Time 1 minute.
    On success { Decrease quantity(actor, gold) by 4. Assert lotSold(lot_crate). Give spectacles to actor. Assert crateBought(actor). }
    Result "Mother Jago turns round and looks at you, and laughs, and puts her hand down. 'Four coin, to the stranger.' You prise the lid off on the quay. It is full of spectacles: two hundred pairs, each in a little tin case lined with green baize, steel-rimmed, graded by strength and labelled in the southern hand: FOR THE OLD.".
  }
  Relation crateBought(group).
  Action bid_chest(actor: group, site: place) "Bid two coin for the sea-chest, over Jack Cawse" {
    Requires able(actor) and at(actor, site) and at(actor, quay) and matterOpen(lot_chest) and quantity(actor, gold) >= 2.
    Time 1 minute.
    On success { Decrease quantity(actor, gold) by 2. Assert lotSold(lot_chest). Give sea_chest to actor. Assert chestBought(actor). }
    Result "Jack Cawse turns round. 'Two coin,' you say again, and he shrugs, and the Reeve says 'Two coin, to the stranger,' without looking at you, and writes it down.".
  }
  Relation chestBought(group).
  // Unbid, the lots go where they would have gone.
  Rule cask_goes when matterDone(lot_cask) and not lotSold(lot_cask) { Assert lotSold(lot_cask). }
  Rule crate_goes when matterDone(lot_crate) and not lotSold(lot_crate) { Assert lotSold(lot_crate). Assert jagoHasCrate(jago). }
  Rule chest_goes when matterDone(lot_chest) and not lotSold(lot_chest) { Assert lotSold(lot_chest). Assert cawseHasChest(cawse). }
  Relation jagoHasCrate(group). Relation cawseHasChest(group).
  // No sale, when the Reeve has stopped selling: Jack Cawse sells off what will not keep himself, out of the door.
  Rule no_sale when secondDay() and hour(clock) >= 11 and not occasionBegun(sale) and not lotSold(lot_chest) { Assert lotSold(lot_cask). Assert lotSold(lot_crate). Assert lotSold(lot_chest). Assert jagoHasCrate(jago). Assert cawseHasChest(cawse). }
  // If the sale was missed, what was sold can still be had of whoever bought it.
  Topic jago_specs with jago "Ask Mother Jago for a pair of the spectacles out of the crate" when jagoHasCrate(jago) once {
    Says "'Two hundred pairs of spectacles,' she says, 'and not a soul in Skeel who can read.' She digs in her apron and brings out a tin case. 'Take a pair. Take two. I bought them for the tins.'".
    On discuss { Give spectacles to actor. }
  }
  Action buy_chest_cawse(actor: group, site: place) "Buy the officer's sea-chest off Jack Cawse for four coin" {
    Requires able(actor) and company(actor) and at(actor, site) and at(cawse, site) and cawseHasChest(cawse) and quantity(actor, gold) >= 4.
    Time 0.
    On success { Decrease quantity(actor, gold) by 4. Increase quantity(cawse, gold) by 4. Retract cawseHasChest(cawse). Give sea_chest to actor. Assert chestBought(actor). }
    Result "Jack Cawse is delighted. 'Couldn't get it open,' he says. 'Tried with a cleaver.'".
  }
  Item wine_cask "a cask of southern wine" is wine_cask_kind at limbo.
  Kind specs_kind "a pair of spectacles in a tin case" is gear worth 1 weighing 0
    described "Steel-rimmed spectacles with round lenses, ground in the south, in a tin case lined with green baize. A label inside the lid in a careful hand: FOR THE OLD. NO. 6, STRONG.".
  Item spectacles "a pair of spectacles" is specs_kind at limbo.
  Kind chest_kind "an officer's sea-chest, initials M.F." is gear worth 0 weighing 12
    described "A sea-chest of oak bound with brass, swollen with water, the lid carved M.F. and under that, in smaller letters, someone has scratched with a knife CONSTANT.".
  Item sea_chest "the sea-chest marked M.F." is chest_kind at limbo.
  Relation chestOpened(group).
  Action open_chest(actor: group, site: place) "Force the sea-chest marked M.F." {
    Requires able(actor) and company(actor) and at(actor, site) and carries(actor, sea_chest) and not chestOpened(actor).
    Time 2.
    Resolve check(actor, brawn, dc_fair).
    On success { Assert chestOpened(actor). Give matthew_ring to actor. Give matthew_letter to actor. Assert knows(actor, matthew_known). }
    Result "The lid comes up with a crack of swollen oak. Inside, wet through: shirts, a razor, a quadrant in a box, a child's book of sea-stories with a girl's name written in it, CONSTANCE, and under them a ring on a string, gold, with a ship cut into it, and a letter in an oilskin wrapper, dry, addressed to Miss Constance Ferrar.".
    Otherwise "The swollen lid will not move. It needs a stronger arm, or more patience.".
  }
  Discovery matthew_known "The officer's chest marked M.F. was Matthew Ferrar's, the Constancy's mate: in it, his sister Constance's childhood book, a gold ring with a ship cut into it, and a letter to her.".
  Kind mate_ring_kind "a gold ring with a ship cut into it" is treasure worth 5 weighing 0
    described "A man's gold ring, worn thin, with a three-masted ship cut into the bezel. Inside the band: M.F. FROM HIS SISTER.".
  Item matthew_ring "Matthew Ferrar's ring" is mate_ring_kind at limbo.
  Kind letter_matthew "a letter to Miss Constance Ferrar" is gear worth 0 weighing 0
    described "A letter in an oilskin wrapper, dry inside. It is not sealed. It begins: 'Con — we raise the Reach tomorrow night, if this wind holds, and Dunn says there will be the Holm light to steer by and good water all the way in.' It goes on about the price of grain, and their father's knees, and ends: 'I shall be home for your birthday, and I shall bring you something foolish.'".
  Item matthew_letter "Matthew Ferrar's letter to his sister" is letter_matthew at limbo.
}

data/adventures/skerrow/caller.kyr:
Module skerrow "The Light on Scarth Holm" {
  // ── The Caller ────────────────────────────────────────────────────────────────────────────────────────────────
  // It is a Thing, not a Person: nothing can be fought, wounded or killed, and the night is not the same without it.
  // Whenever it is dark and the tide is in it is on the holm: it knocks in the evening and calls from midnight, whatever
  // the lamp is doing, and the people who answer are lost. What the lamp changes is where it can climb. While the lamp
  // is bright it lies in the cistern and reaches only the sea-side rooms (the landing, the boat shed, the bell hut, the
  // cistern). When the lamp sinks it reaches the store and the keeper's room; when it is out it reaches every room.
  // It goes to wherever the company is, if that room is within reach, and after half an hour takes one of them. A
  // bell sends it back to sea for an hour while the lamp lives; holy water and a flame send it back whatever the lamp
  // does. Nobody on the holm will tell the company any of this.
  Thing caller "the thing in the cistern" at open_water is scenery {
    State below "In the black water by the ladder something grey lies the whole length of the tank, with its hands closed.".
    State stair "On the iron stair, a wet print on every tread, going up, and the smell of the cistern.".
    State here "A grey length of something is in the room with you. Its hands are open.".
  }
  Initially Assert state(caller, below).
  Measure cArr(entity). Measure lastTake(entity). Measure lastKnock(entity).
  Query exposed() means at(party, cistern) or at(party, boat_shed) or at(party, landing) or at(party, bell_hut)
    or (not state(lamp, bright) and (at(party, store) or at(party, keeper_room)))
    or ((state(lamp, out) or (state(lamp, low) and watch(clock) >= lowSince(lamp) + 6)) and (at(party, kitchen) or at(party, lamp_room) or at(party, gallery))).
  Rule caller_sea when not hunting() and not at(caller, open_water) and at(caller, ?p) {
    Retract at(caller, ?p). Assert at(caller, open_water). Assert state(caller, below).
  }
  Rule caller_hunts when hunting() and exposed() and at(party, ?q) and not at(caller, ?q) and at(caller, ?p) {
    Retract at(caller, ?p). Assert at(caller, ?q). Assert state(caller, here). Set cArr(tide) to watch(clock).
  }
  Rule caller_cistern when hunting() and not exposed() and not state(lamp, low) and not at(caller, cistern) and at(caller, ?p) {
    Retract at(caller, ?p). Assert at(caller, cistern). Assert state(caller, below). Set cArr(tide) to watch(clock).
  }
  Rule caller_stair when hunting() and not exposed() and state(lamp, low) and not at(caller, keeper_room) and at(caller, ?p) {
    Retract at(caller, ?p). Assert at(caller, keeper_room). Assert state(caller, stair). Set cArr(tide) to watch(clock).
  }

  // Evenings, a knocking. From midnight, voices, five of them. They come whatever the lamp is doing, and they are why
  // Gaff, Dib, Corrie and Hettie are lost or kept.
  Rule knocks when hunting() and not calling() and within(party, holm) and watch(clock) >= lastKnock(tide) + 6 {
    Set lastKnock(tide) to watch(clock).
  }
  Observe knock within holm as sound when hunting() and not calling() and lastKnock(tide) > 0 and watch(clock) < lastKnock(tide) + 7 "Under the floor of the tower something knocks, twice. Then it stops.".
  Rule the_call when calling() and within(party, holm) and watch(clock) >= lastCall(tide) + 6 {
    Increase callN(tide) by 1. Set lastCall(tide) to watch(clock).
  }
  Observe call_one within holm as sound when calling() and callN(tide) == 1 and watch(clock) < lastCall(tide) + 7 "Out on the water a man shouts, a long way off, one word, as you would shout across a river. It might be a gull.".
  Observe call_two within holm as sound when calling() and callN(tide) == 2 and watch(clock) < lastCall(tide) + 7 "A woman's voice, nearer, from under the window. 'Is anyone there?' She says it like someone who already knows.".
  Observe call_three within holm as sound when calling() and callN(tide) == 3 and watch(clock) < lastCall(tide) + 7 "From the sea-side of the rock a man's voice, easy, calls a boy's name, and laughs, and calls it again, nearer than the laugh.".
  Observe call_four within holm as sound when calling() and callN(tide) == 4 and watch(clock) < lastCall(tide) + 7 "The voice is at the foot of the tower. It is no one you have to guess at. It says a name as it was said at home.".
  Observe call_five within holm as sound when calling() and callN(tide) >= 5 and watch(clock) < lastCall(tide) + 7 "The voices have stopped being separate. A whole street of them is in the cistern, all saying the one name, softly, over and over, and waiting.".

  // What it does in the room it has come to. A taking is half an hour after it arrives, and one in an hour at most.
  Hazard taken_by_the_sea "Answering the sea" means "Kill ally.".
  Rule caller_takes_cistern when hunting() and exposed() and at(party, cistern) and at(caller, cistern) and watch(clock) >= cArr(tide) + 3 and watch(clock) >= lastTake(tide) + 6
    says "The water does not move. The hands open, along the whole grey back, together. A voice you know says your name from close by, and somebody has gone down the ladder to it before you have turned." {
    Assert strikes(taken_by_the_sea, party). Set lastTake(tide) to watch(clock).
  }
  Rule caller_takes_keeper_room when hunting() and exposed() and at(party, keeper_room) and at(caller, keeper_room) and watch(clock) >= cArr(tide) + 3 and watch(clock) >= lastTake(tide) + 6
    says "The glove on the sill is wet through. Something has come up the stair and stands in the doorway with its hands open, and says one name. One of you answers it before they have decided to." {
    Assert strikes(taken_by_the_sea, party). Set lastTake(tide) to watch(clock).
  }
  Rule caller_takes_store when hunting() and exposed() and at(party, store) and at(caller, store) and watch(clock) >= cArr(tide) + 3 and watch(clock) >= lastTake(tide) + 6
    says "The shelves are running with water. Something stands among the flasks with its hands open, and says a name, and a flask rolls off the shelf and breaks. One of you has gone to it." {
    Assert strikes(taken_by_the_sea, party). Set lastTake(tide) to watch(clock).
  }
  Rule caller_takes_kitchen when hunting() and exposed() and at(party, kitchen) and at(caller, kitchen) and watch(clock) >= cArr(tide) + 3 and watch(clock) >= lastTake(tide) + 6
    says "The range ticks as it cools. The cistern door is open, and nobody opened it, and the thing in the doorway has its hands open. It says a name, and a chair goes back." {
    Assert strikes(taken_by_the_sea, party). Set lastTake(tide) to watch(clock).
  }
  Rule caller_takes_lamp_room when hunting() and exposed() and at(party, lamp_room) and at(caller, lamp_room) and watch(clock) >= cArr(tide) + 3 and watch(clock) >= lastTake(tide) + 6
    says "The black glass shows the room back to itself, and in it a grey shape stands at your shoulder with its hands open. It says a name, close to your ear. Somebody answers it before they have decided to." {
    Assert strikes(taken_by_the_sea, party). Set lastTake(tide) to watch(clock).
  }
  Rule caller_takes_gallery when hunting() and exposed() and at(party, gallery) and at(caller, gallery) and watch(clock) >= cArr(tide) + 3 and watch(clock) >= lastTake(tide) + 6
    says "Over the rail, climbing the outside of the glass, come the grey hands, one after another. It says a name into the wind, and one of you leans out to answer." {
    Assert strikes(taken_by_the_sea, party). Set lastTake(tide) to watch(clock).
  }
  Rule caller_takes_boat_shed when hunting() and exposed() and at(party, boat_shed) and at(caller, boat_shed) and watch(clock) >= cArr(tide) + 3 and watch(clock) >= lastTake(tide) + 6
    says "The sea has come in under the door to your ankles, and the thing stands in it with its hands open. It says a name from close by, and somebody wades to it." {
    Assert strikes(taken_by_the_sea, party). Set lastTake(tide) to watch(clock).
  }
  Rule caller_takes_landing when hunting() and exposed() and at(party, landing) and at(caller, landing) and watch(clock) >= cArr(tide) + 3 and watch(clock) >= lastTake(tide) + 6
    says "The thing is on the steps, to its waist in the water, with its hands open. It says a name, and somebody goes down to it." {
    Assert strikes(taken_by_the_sea, party). Set lastTake(tide) to watch(clock).
  }
  Rule caller_takes_bell_hut when hunting() and exposed() and at(party, bell_hut) and at(caller, bell_hut) and watch(clock) >= cArr(tide) + 3 and watch(clock) >= lastTake(tide) + 6
    says "The bell hangs still. The grey length has come up the rock to the beam with its hands open, and says a name, and somebody steps out from under the roof." {
    Assert strikes(taken_by_the_sea, party). Set lastTake(tide) to watch(clock).
  }

  // Answering is a thing that can be done, outdoors, by anyone who hears a voice and goes to it.
  Relation answeredFalse(group). Relation torchTried(group).
  Action answer_voice(actor: group, site: place) "Answer the voice by your own name" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, landing) or at(actor, gallery)) and calling() and watch(clock) < lastCall(tide) + 3.
    Time 0.
    On success { Assert strikes(taken_by_the_sea, actor). }
    Result "You say it. It is a relief to say it. The voice is glad. When the cold has gone one of you is on the stones with their eyes open, and the voice has stopped.".
  }
  Action answer_false(actor: group, site: place) "Answer the voice with someone else's name, and make it sound afraid" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, landing) or at(actor, gallery)) and calling() and watch(clock) < lastCall(tide) + 3 and not answeredFalse(actor).
    Time 0.
    Resolve check(actor, deception, dc_hard).
    On success { Assert answeredFalse(actor). Set repelUntil(tide) to watch(clock) + 8. }
    On failure { Assert answeredFalse(actor). Assert strikes(taken_by_the_sea, actor). }
    Result "You say a name that is not yours, in a voice that is not yours, and put into it everything you have been afraid of. A long silence. The water turns over once, like a sleeper changing sides, and goes out.".
    Otherwise "You say the false name. The voice stops. Then it says your own.".
  }

  // What it does not like: holy water, and a flame held out at the full length of an arm. Both send it back to sea
  // whatever the lamp is doing, for a while.
  Item holy_a "a flask of holy water" is holy_water at store.
  Item holy_b "a second flask of holy water" is holy_water in hettie_basket hidden until basket_looked.
  Thing hettie_basket "Hettie's basket" at kitchen {
    State covered closed "A basket with a cloth over it stands by the range. It smells of a loaf and, faintly, of a chapel.".
    State open "The basket stands open: a loaf, a jar, a candle-end, and a small flask stoppered with wax.".
    Change open_basket "Look in Hettie's basket" from covered to open.
    Holds.
  }
  Discovery basket_looked "Hettie's basket holds a loaf, a jar, a candle-end and a flask of holy water.".
  Observe basket_taught at kitchen when state(hettie_basket, open) "The flask is stoppered with wax and smells of a chapel. It is not the sort of thing one brings to a lighthouse for tea." teaches basket_looked.
  Action splash_caller(actor: group, site: place) "Throw holy water where the hands are opening" {
    Requires able(actor) and company(actor) and at(actor, site) and at(caller, site) and holding(actor, holy_water).
    Time 0.
    On success { Spend holy_water from actor. Set repelUntil(tide) to watch(clock) + 12. }
    Result "The flask breaks on the grey back, and where the water runs there is a sound like fat on a griddle. The hands close. Every one of them. The thing goes down without turning, lamp or no lamp, and the water in the cistern goes still for two hours.".
  }
  Action drive_it_off(actor: group, site: place) "Take a torch to it" {
    Requires able(actor) and company(actor) and at(actor, site) and at(caller, site) and capable(actor, light) and not torchTried(party).
    Time 0.
    Resolve check(actor, intimidation, dc_hard).
    On success { Set repelUntil(tide) to watch(clock) + 6. }
    On failure { Assert torchTried(party). }
    Result "You hold the flame out at the full length of the arm. The hands fold, one at a time. It goes back down, step by step, facing you.".
    Otherwise "You hold the flame out. It does not mind. It says your name again, in the voice of the person you would least like to refuse.".
  }
  Rule torch_rests when torchTried(party) and hour(clock) >= 12 and hour(clock) < 13 { Retract torchTried(party). }
}

data/adventures/skerrow/company.kyr:
Module skerrow "The Light on Scarth Holm" {
  Company party "Your company" of 3 at shore_road.
  Initially Set quantity(party, gold) to 14. Initially Set quantity(party, rations) to 3.
}

data/adventures/skerrow/folk.kyr:
Module skerrow "The Light on Scarth Holm" {
  // ── Seven people and a dog on a rock ───────────────────────────────────────────────────────────────────────────
  // Each has a want, a secret and a way of talking. Seddon: short, no adjectives. Hettie: food and the dead, in the
  // same breath. Gaff: loud, friendly, never finishes a sentence he is laughing at. Piers: qualifies everything.
  // Dib: asks, does not wait. Lowrie: speaks as if a question had been put to him from far off. Corrie: prices.
  // The dog: is right.
  Measure love(entity).

  Person orrin "Edmund Seddon" at kitchen {
    Role "keeper of the Scarth light". Ancestry human. Calling warrior. Level 3. Peaceable. Pronouns he. Manner stoic.
    Greets "A man of sixty in a navy jersey darned at both elbows looks at the tide-table, and at you, and back at the table. 'Late,' he says. 'You're in. Boots by the range.' That is the whole of the welcome, and it is warm.".
  }
  Topic orrin_asks with orrin "Answer Seddon's question about the night" when true once {
    Says "'Can you stay awake?' says Seddon. 'All of you. Till it's light.' He does not say what for. 'I'll not have the lamp touched by anyone who'd sooner sleep.' The window has fog on it.".
  }
  Topic orrin_yes with orrin "We can. Say what we're to do" answering orrin_asks when true {
    Says "'Good,' says Seddon. 'If anyone calls, say nothing.' He turns the cup in his hands. 'Oil's in the store. Take what you want of it.'".
  }
  Topic orrin_no with orrin "No. We'd sooner sleep" answering orrin_asks when true {
    Says "'Sleep, then,' says Seddon. 'Shutters down.' He turns his back. 'I'll take the lamp. Touch it and you answer to me.'".
    On discuss { Assert lampForbidden(party). }
  }
  Topic orrin_what with orrin "Ask what happens at night" answering orrin_asks when true {
    Says "'Tide comes in,' says Seddon. 'Dark comes down.' He thinks about it. 'People hear things. It's a rock. Say nothing if anyone calls. The oil's in the store, if you're up.'".
  }
  Relation readTried(group). Relation orrinTamAsked(group). Relation orrinSpoke(group). Relation orrinDeclared(group). Relation orrinTried(group). Relation hettieUpTried(group). Relation holdTried(group).
  Relation hettieSecret(group). Relation hettieKept(group). Relation hettieTaken(group). Relation hettieWalking(group). Relation hettieHeld(group).
  Relation orrinTaken(group). Relation dibTaken(group). Relation gaffTaken(group). Relation piersLost(group). Relation lowrieGone(group). Relation corrieLost(group).

  Person hettie "Hettie Marram" at kitchen {
    Role "a widow in black, with a basket". Ancestry human. Peaceable. Pronouns she. Manner compassionate.
    Greets "The loaf is being cut into slices thicker than it can spare, by a round woman in a black straw bonnet who does not stop for you. 'Sit,' she says. 'Tea. I always bring tea. Tam said it was the only part of the journey that was properly planned.'".
  }
  Topic hettie_ask with hettie "Hear what Hettie asks you over the tea" when true once {
    Says "Hettie pours. 'May I ask you a thing?' she says. 'It's tonight, you see. Eleven years. I come every year and bring the loaf. Do you think the drowned can be spoken to?'".
  }
  Topic hettie_no with hettie "No. They are gone" answering hettie_ask when true {
    Says "'That's what I tell myself,' says Hettie, and gets up for the sugar nobody asked for. 'Being told is a comfort. It doesn't last.'".
    On discuss { Assert hettieAsked(party). Set hettieAt(tide) to 5. }
  }
  Topic hettie_some with hettie "Some of them, perhaps" answering hettie_ask when true {
    Says "'Perhaps,' says Hettie. Her face lifts. 'That's what I say.' She takes your hand across the table, and holds it harder than kindness.".
    On discuss { Assert hettieAsked(party). Set hettieAt(tide) to 3. }
  }
  Topic hettie_would with hettie "Ask what Tam would want of her tonight" answering hettie_ask when true {
    Says "Hettie is silent. 'He'd want me home,' she says at last. 'By the fire. With the cat.' Her mouth goes sideways. 'He was a dull man, Tam. I loved him extremely.'".
    On discuss { Assert hettieAsked(party). Increase love(tide) by 1. }
  }
  Relation hettieAsked(group).
  Topic hettie_secret_t with hettie "Ask Hettie why she comes to this rock" when hettieAsked(party) once {
    Says "'Because it's here,' says Hettie. 'Tam went into the sea off that causeway tonight, eleven years since, at ten past nine. Mr Seddon was keeping the light. They were friends.' She smooths the cloth. 'I come to be near the last place he was. And I come to hear him. I think he calls me. I've never answered. I wonder if this year I shall.'".
    On discuss { Assert hettieSecret(party). }
  }

  Person gaff "Gaff Mullen" at kitchen {
    Role "a drover with a cart of cheeses in the lee of the causeway post, and a dog". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "A man built like a barn door fills the best chair, his boots in the fender and a mug that holds a quart on his knee. 'FRIENDS!' he says. 'Come in, come in, there's tea and there's something to put in the tea. Gaff Mullen. Forty-two cheeses and a dog. Not a word to the revenue, they're all under the sacking.'".
  }
  Topic gaff_asks with gaff "Take Gaff's question" when true once {
    Says "'Here's a thing,' says Gaff, loudly. 'Last time I came this way a fellow at the slipway told me the rock likes a loud man. Likes him, he said. Ha! What d'you make of that? You've the look of folk who've been about.'".
  }
  Topic gaff_hush with gaff "Tell him to keep his voice down tonight, and mean it" answering gaff_asks when true {
    Says "Gaff's laugh stops. He puts the mug down. 'Eh,' he says, and the great face goes small. 'Is that so.' He turns the mug a quarter-turn on his knee. The dog has not moved from the door in an hour. 'I'll keep my mouth shut, then. First time for everything.'".
    On discuss { Assert gaffHushed(party). }
  }
  Topic gaff_laugh with gaff "Laugh with him; it's a rock" answering gaff_asks when true {
    Says "'THERE!' says Gaff, delighted, and slaps the table so that the tea jumps. 'A man after my own heart!' He begins a song. It is very loud, and the whole kitchen is under it, and nobody could hear a voice at the window through it. He is afraid of nothing at present, and the dog has gone under the table.".
    On discuss { Assert gaffLoud(party). }
  }
  Relation gaffHushed(group). Relation gaffLoud(group).
  Person sprat "Sprat" at kitchen {
    Role "Gaff's dog, a lurcher with a split ear". Species dog. Peaceable.
  }
  Observe sprat_door near sprat when hunting() and at(caller, cistern) "Sprat is at the cistern door with her nose to the crack, and her whole body is pointed at it like a needle. She makes no sound.".
  Observe sprat_here near sprat when hunting() and at(caller, kitchen) "Sprat has crawled under the table and will not come out. She is looking at the cistern door, which is open.".
  Observe sprat_stair near sprat when hunting() and at(caller, keeper_room) "Sprat has left the cistern door and gone to the foot of the iron stair. Her hackles are up, and she is looking at the ceiling.".

  Person piers "Piers Tolland" at kitchen {
    Role "a clerk of the Tide Board, with a satchel on his knees". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "The satchel is held on the stool in both arms, and the thin young man in the brown coat that fits him in the sleeves and nowhere else is held on behind it. 'Tolland,' he says. 'Piers. Tide Board. Which is to say, I think, that I am the Tide Board, as far as this rock is concerned, though of course there are others. I do apologise for the satchel. It is not that I do not trust you.'".
  }
  Topic piers_asks with piers "Hear what Piers has to say in confidence" when true once {
    Says "Piers looks round the kitchen twice. 'In confidence,' he says. 'I am to give notice, you see. I have it here. The Board has resolved to discontinue the Scarth light on the first of next month, as the traffic no longer warrants it, and I am to hand it to the keeper personally and I have been here two hours and I have not.' He swallows. 'What would you do?'".
  }
  Topic piers_tell with piers "Tell the keeper tonight, and be there when he reads it" answering piers_asks when true {
    Says "'Tonight,' says Piers, in a small voice. 'On the night. Yes. I see that you are right and I see that I shall die of it.' He stands up with the satchel held to his chest.".
    On discuss { Assert piersTold(party). }
  }
  Topic piers_wait with piers "Keep it till morning; it is the worse for being said in the dark" answering piers_asks when true {
    Says "'Till morning,' says Piers, with deep relief. 'Yes. Thank you.' He lets out a breath he has been holding since the causeway. 'Then I shall sit up with him. I can carry an oil-can. It is the least I can do for a man I am going to ruin.'".
    On discuss { Assert piersWaits(party). Increase refills(lamp) by 1. }
  }
  Relation piersTold(group). Relation piersWaits(group). Relation piersEscort(group).

  Person corrie "Corrie Fenwether" at kitchen {
    Role "a rope-seller, with a coil on her shoulder and a ledger in her sleeve". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "'Four pence the fathom,' says a square woman at the end of the bench, in a man's waxed coat, counting the strands of a tarred coil with her thumb. 'Three if you take the lot. Fenwether, cordage, and I am not to be haggled with on a rock.' She does not look up. 'I was at the slipway at twelve and I am on the wrong side of the tide for it. That is a day's trade gone.'".
  }
  Topic corrie_asks with corrie "Ask Corrie Fenwether what she is doing on a rock in the fog" when true once {
    Says "'Selling,' says Corrie. 'Nothing sells like a rope on a day the tide's in.' She winds a turn of line round her thumb. 'I was here last year. I heard my sister in that cistern. She is alive, and keeps a stall at the fair. I was out of this place quickly.'".
    On discuss { Assert corrieSister(party). }
  }
  Item corrie_line "a coil of Corrie's tarred line" is rope at kitchen.
  Relation corrieSold(group). Relation corrieSister(group).
  Topic corrie_buy with corrie "Buy a coil of Corrie's line" when corrieSister(party) once {
    Says "'Two crowns,' says Corrie, and does not haggle. She weighs a coil in her hand and puts it in yours. 'And the other thing is the price. If you hear her tonight, you come and tell me it was her.' She shuts her ledger. 'Then I shall stay in my seat and let her come to me.'".
    On discuss { Assert corrieSold(party). Decrease quantity(actor, gold) by 2. Give corrie_line to actor. }
  }

  Person dib "Dib Wyke" at kitchen {
    Role "the keeper's boy, taken in off a wreck last winter". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "'Have you been in the sea? Have you seen the sea at night? Does your dog bite?' A boy of twelve with a face scrubbed raw and a sleeve out of one elbow is on you before you are through the door. 'You haven't a dog. Why haven't you? Can I see that?'".
  }
  Topic dib_asks with dib "Let Dib show you what he found" when true once {
    Says "Dib drags you to the store and hauls up the hatch by its iron ring. Black water, a ladder going down, the smell of an old cellar. 'Cistern,' he says. 'Mr Seddon says never. But you can hear the sea in it. And sometimes you hear my dad.' He says it as he says everything. 'Would you? If it was your dad?'".
  }
  Topic dib_no with dib "No. It isn't him" answering dib_asks when true {
    Says "'Mr Seddon says that,' says Dib. He lets the hatch fall. 'It sounds just like him, though.'".
    On discuss { Assert dibDoubts(party). }
  }
  Topic dib_stay with dib "I'd want to. Stay by me tonight, and we'll listen together" answering dib_asks when true {
    Says "Dib looks at you as if nobody had offered him anything this year. 'All right,' he says. 'Together.'".
    On discuss { Assert dibWatched(party). Assert following(dib, party). }
  }
  Relation dibWatched(group). Relation dibDoubts(group).

  Person lowrie "Mr Lowrie" at keeper_room {
    Role "a man the sea gave back a month ago". Ancestry human. Peaceable. Pronouns he. Manner grim.
    Greets "A man sits upright on the bunk in a keeper's coat that does not fit, with his hands on his knees and his eyes on the window. He does not turn his head. 'It is that you came in by the door,' he says. 'The door is a good way. The sea is not a way.' The skin of his hands is the colour of candle-wax and does not look wet, though it is.".
  }
  Topic lowrie_rule with lowrie "Ask Mr Lowrie what he knows of the night" when true once {
    Says "'The sea keeps what it is given,' says Lowrie. 'I was given. I was kept. I have been let go on a loan.' He says it to a window. 'I said more once and was heard.'".
    On discuss { Assert lowrieHeard(party). }
  }
  Topic lowrie_who with lowrie "Ask Mr Lowrie who he was before the sea" when lowrieHeard(party) once {
    Says "'Lowrie,' he says. 'It was answered.' The window clouds, from the inside. 'There is a thing I am asked. Which of you has a name worth keeping.'".
  }
  Topic lowrie_all with lowrie "All of us. Every one" answering lowrie_who when true {
    Says "'Then I shall ring for you,' says Lowrie, and for the first time turns his head. 'I have nothing else to be used for.'".
    On discuss { Assert lowrieOffers(party). }
  }
  Topic lowrie_me with lowrie "I do. I can't speak for the others" answering lowrie_who when true {
    Says "'That is honest,' says Lowrie. 'It is the only sort of name that stays.' He turns back to the window. 'Keep it.'".
    On discuss { Assert lowrieSpared(party). }
  }
  Relation lowrieHeard(group). Relation lowrieOffers(group). Relation lowrieRang(group). Relation lowrieSpared(group).

  // The rest of the drama: bringing two people to say a thing. Each of these is tried once.
  Topic orrin_tam with orrin "Ask Seddon what Tam was to him" when hettieSecret(party) and not orrinTamAsked(party) once {
    Says "'Friend,' says Seddon. 'He owed me a pound.' He turns the cup. 'He was the one man on this coast who laughed at the bell.' He does not look at Hettie, who is looking at him.".
    On discuss { Assert orrinTamAsked(party). Increase love(tide) by 1. }
  }
  Action bring_hettie_up(actor: group, site: place) "Take Hettie up the iron stair to the lamp room" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, kitchen) and at(hettie, kitchen) and hettieSecret(party) and not hettieTaken(party) and not hettieHeld(party) and not hettieUpTried(party).
    Time 2.
    Resolve check(actor, persuasion, dc_fair).
    On success { Retract at(hettie, kitchen). Assert at(hettie, lamp_room). Increase love(tide) by 1. }
    On failure { Assert hettieUpTried(party). }
    Result "'Oh, I couldn't,' says Hettie, and has her bonnet on. She goes up the iron stair on your arm, saying she is too heavy for such stairs, and on the last turn she sees the lamp, and stops.".
    Otherwise "'No,' says Hettie, gently. 'I think I'll sit with the tea.'".
  }
  Action ask_orrin_speak(actor: group, site: place) "Ask Seddon whether there is a thing he has never said to Mrs Marram" {
    Speaker orrin.
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, lamp_room) or at(actor, kitchen)) and at(orrin, site) and at(hettie, site) and hettieSecret(party) and orrinSpoke(party) and not orrinDeclared(party) and not orrinTried(party) and love(tide) < 3.
    Time 1.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert orrinDeclared(party). Increase love(tide) by 2. }
    On failure { Assert orrinTried(party). }
    Result "Seddon looks at the lamp. He looks at it. 'Hettie,' he says. He has not said it, you realise, in eleven years. 'I held the light that night. I heard him. I did not answer, and I did not ring, and he went in.' He stops. 'I should have rung.' Hettie has taken a step. 'You rang,' she says. 'Edmund. You rang. I heard it from the road.'".
    Otherwise "Seddon says, 'No,' and trims a wick that did not need it.".
  }
  // A company that has earned the keeper's trust (a love of three) is not made to roll: he has been waiting to be asked.
  Action ask_orrin_speak_known(actor: group, site: place) "Ask Seddon whether there is a thing he has never said to Mrs Marram" {
    Speaker orrin.
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, lamp_room) or at(actor, kitchen)) and at(orrin, site) and at(hettie, site) and hettieSecret(party) and orrinSpoke(party) and not orrinDeclared(party) and love(tide) >= 3.
    Time 1.
    On success { Assert orrinDeclared(party). Increase love(tide) by 2. }
    Result "Seddon looks at the lamp. 'Hettie,' he says. He has not said it, you realise, in eleven years. 'I held the light that night. I heard him. I did not answer, and I did not ring, and he went in.' He stops. 'I should have rung.' Hettie has taken a step. 'You rang,' she says. 'Edmund. You rang. I heard it from the road.'".
  }
  Action read_orrin(actor: group, site: place) "Watch Seddon's hands while Mrs Marram talks of Tam" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, kitchen) and at(orrin, kitchen) and at(hettie, kitchen) and hettieSecret(party) and not orrinSpoke(party) and not readTried(party).
    Time 1.
    Resolve check(actor, insight, dc_fair).
    On success { Assert orrinSpoke(party). Increase love(tide) by 1. }
    On failure { Assert readTried(party). }
    Result "He is not looking at her. He is looking at the clock, which stopped at four. His hand on the table has the cloth in a fist.".
    Otherwise "Seddon's face is shut.".
  }

  // What the evening shows of it, for anyone who looks. Nothing here is a number the player is told.
  Observe love_one near orrin when love(tide) == 1 and not hettieTaken(party) "Seddon has put out a second cup without being asked, on Hettie's side of the table.".
  Observe love_two near orrin when love(tide) == 2 and not hettieTaken(party) "Somebody has wound the clock that stopped at four. It is wrong by hours, and nobody mentions it.".
  Observe love_three near orrin when love(tide) == 3 and not hettieTaken(party) "When Hettie talks, Seddon no longer looks at the tide-table. He looks at the cup.".
  Observe love_four near orrin when love(tide) >= 4 and not hettieTaken(party) "Whenever Hettie crosses the room Seddon half rises, and sits down again. The cup in his hand is cold.".
}

data/adventures/skerrow/lore.kyr:
Module skerrow "The Light on Scarth Holm" {
  // ── The morning after, and the world's word ───────────────────────────────────────────────────────────────────────
  // The kitchen was the same room at nine at night and at nine in the morning. A person who lived through the dark
  // is not the person who sat down to tea: what is left on the rock says so, and says it differently to each.
  Query dayTwo() means reachedAt(tide) > 0 and watch(clock) >= reachedAt(tide) + 90 and watch(clock) < reachedAt(tide) + 180 and not crossed(party).

  Observe d2_seddon at lamp_room when dayTwo() and not orrinTaken(party) and at(orrin, lamp_room) "Seddon has not sat down since the bell. He has a tide-table open in his hand, upside down, and has read it that way twice, and the tea he has made is in the pot he uses for the lamp-glass.".
  Observe d2_hettie near hettie when dayTwo() and not hettieTaken(party) and at(hettie, kitchen) "Hettie has cut the loaf again and it is the same loaf. She has put out cups for seven. She counts the cups, and takes the extra ones back to the shelf, one at a time, without remark.".
  Observe d2_gaff near gaff when dayTwo() and not gaffTaken(party) and at(gaff, kitchen) "Gaff Mullen is sitting very straight in the chair he sprawled in. The mug is empty, and he is holding it as one holds something that might be needed. He says good morning in an ordinary voice, and the dog looks at him.".
  Observe d2_corrie near corrie when dayTwo() and not corrieLost(party) and at(corrie, kitchen) "Corrie Fenwether has laid out her stock on the bench in length order, shortest to longest, and is pricing it a penny lower than last night. She does not look at the cistern door. She has put her ledger in her boot.".
  Observe d2_dib near dib when dayTwo() and not dibTaken(party) and at(dib, kitchen) "Dib has asked nothing since you came down. He is sitting on the store door with his back against the hatch, as if it were a small animal, and he is not going to let it get up.".
  Observe d2_piers near piers when dayTwo() and not piersLost(party) and at(piers, kitchen) "Piers Tolland has the Board's notice out of the satchel and flat on his knee, and has been smoothing it so long that the crease has gone soft as cloth. He has not yet decided which of two sentences to begin with.".

  // Gaff's road. The cheeses are bound inland: the people who keep the roads and the inns know the cart.
  Topic gaff_road with gaff "Ask Gaff what he is doing on a causeway with forty-two cheeses" when true once {
    Says "'Selling 'em where nobody else will,' says Gaff, loudly, and lowers it. 'Coast road's a long road and a cheese ages on it. I take them up from the dairies in the hills to the market in the first town off the main road, where the innkeeper has a contract, and I come back the long way round with whatever the fishing villages will pay in salt.' He taps the side of his nose. 'This rock I do for love. The keeper's tea is the best on four counties, and nobody else will buy a cheese off me with a straight face.'".
  }

  // ── What leaves the rock ─────────────────────────────────────────────────────────────────────────────────────────
  // Told by the lamp-keepers and the pilots of other coasts (Skeel's Loveday Kitto reads both in her night log).
  Rule scarth_kept_word when crossed(party) and not hettieTaken(party) and not orrinTaken(party) and not befell(scarth_kept) { Assert befell(scarth_kept). }
  Rule scarth_lost_word when crossed(party) and (hettieTaken(party) or orrinTaken(party)) and not befell(scarth_lost) { Assert befell(scarth_lost). }

  // And what the rock hears. The Board's clerk is the only man on it with a list of the coast's other business.
  Observe lore_piers_list at kitchen when befell(remainder_kept) and not piersLost(party) and at(piers, kitchen) "Piers has a second paper under the Board's notice, a printed list of vessels reported overdue, and one entry on it is ruled through in red with a note in the margin in a clerk's hand: LEFT, NOT LOST. 'Which is not a column the Board has,' he says. 'Someone has added one. I should like very much to know who is allowed to do that.'".
}

data/adventures/skerrow/morning.kyr:
Module skerrow "The Light on Scarth Holm" {
  // ── The day that isn't: who knows the posts, who comes, who stays ───────────────────────────────────────────────
  Relation orrinComes(group).
  Topic dib_line with dib "Ask Dib to take you out along the posts" when dibWatched(party) and not dibTaken(party) and not lined(party) and state(tide, low) once {
    Says "'The posts?' says Dib. 'Course. Eleven to a hundred and four, and the bad ones are the odd ones, because the mud's soft there. You count them out loud, you don't look. I did it with Mr Seddon the first week.' He wipes his nose on his wrist. 'Dad would've hated it. He was always for the boat.'".
    On discuss { Assert lined(party). }
  }
  Topic orrin_comes_t with orrin "Ask Seddon to come over the sands with Mrs Marram" when orrinDeclared(party) and hettieKept(party) and not orrinComes(party) and not orrinTaken(party) once {
    Says "Seddon has kept the lamp twenty-six years. He looks at Hettie, who has her hand on his sleeve. 'I held it the night Tam went,' he says. 'I've held it every night since.' He puts his hand over hers. 'It'll keep a day.' He fetches his coat, and his tide-tables, and then, after a moment, he puts the tide-tables back.".
    On discuss { Assert orrinComes(party). Retract orrinPost(orrin). Assert following(orrin, party). Assert following(hettie, party). }
  }
  Observe fog_morning at kitchen when state(fog, thick) and reachedAt(tide) > 0 and watch(clock) >= reachedAt(tide) + 90 "It is morning by the clock, and the window shows a wall. The bell is still going, somewhere, patient.".
}

data/adventures/skerrow/night.kyr:
Module skerrow "The Light on Scarth Holm" {
  // ── The night's decisions: who answers, who is held, who goes after whom ────────────────────────────────────────
  // What happens to the people is told by sound, which carries over the whole holm, and by what is left in the room
  // afterwards (see the Observes at the foot), so it is told truly wherever the company happens to be.
  Relation hettieDecided(group). Relation orrinChasing(group). Relation orrinHeld(group). Relation stopTried(group).
  Measure walkAt(entity). Measure hettieAt(entity). Initially Set hettieAt(tide) to 4.
  Relation hushTried(group). Relation keepTried(group).

  // Seddon's days and nights.
  Rule orrin_to_lamp when orrinPost(orrin) and (hour(clock) >= 19 or hour(clock) < 7) and not at(orrin, lamp_room) and not orrinChasing(party) and not orrinTaken(party) and at(orrin, ?p) {
    Retract at(orrin, ?p). Assert at(orrin, lamp_room).
  }
  Rule orrin_to_kitchen when orrinPost(orrin) and hour(clock) >= 7 and hour(clock) < 19 and at(orrin, lamp_room) and not orrinChasing(party) and not orrinTaken(party) and at(orrin, ?p) {
    Retract at(orrin, ?p). Assert at(orrin, kitchen).
  }
  Rule orrin_returns when not orrinPost(orrin) and orrinFreed(party) and not orrinComes(party) and watch(clock) >= walkAt(tide) + 12 and not orrinTaken(party) { Assert orrinPost(orrin). }
  Relation orrinFreed(group).

  // Gaff: the second call is the one he answers (the first, if he was encouraged to be loud), unless he has been hushed.
  Rule gaff_answers when (callN(tide) >= 2 or (callN(tide) >= 1 and gaffLoud(party))) and not gaffHushed(party) and not gaffTaken(party) and watch(clock) >= lastCall(tide) + 3 and at(gaff, kitchen)
    and at(gaff, ?p) says "A great voice, not far off: 'WHO'S THAT? HERE! I'M HERE, FRIEND! COME UP!' A silence the length of a man's breath. Then a door, and laughing, going away across the rock." {
    Assert gaffTaken(party). Retract at(gaff, ?p).
  }
  Action hush_gaff(actor: group, site: place) "Put a hand over Gaff's mouth and keep it there" {
    Speaker gaff.
    Requires able(actor) and company(actor) and at(actor, site) and at(gaff, site) and not gaffHushed(party) and not gaffTaken(party) and callN(tide) >= 1 and not hushTried(party).
    Time 1.
    Resolve check(actor, intimidation, dc_fair).
    On success { Assert gaffHushed(party). }
    On failure { Assert hushTried(party). }
    Result "Gaff's eyes go wide over your hand, and then softer. He nods. He does not make another sound the whole of the night.".
    Otherwise "He shoves you off cheerfully, and takes a breath to say something enormous.".
  }

  // Dib: the third call is his father. He answers it unless someone has him by the sleeve.
  Rule dib_answers when (callN(tide) >= 4 or (callN(tide) >= 3 and not dibDoubts(party) and not gaffLoud(party))) and not dibWatched(party) and not dibTaken(party) and at(dib, kitchen) and watch(clock) >= lastCall(tide) + 3
    and at(dib, ?p) says "In the store the hatch-ring clangs against the stone, and a boy's feet go down a ladder, quickly, and then no more of them." {
    Assert dibTaken(party). Retract at(dib, ?p).
  }
  Action keep_dib(actor: group, site: place) "Take Dib by the sleeve and keep him by you" {
    Requires able(actor) and company(actor) and at(actor, site) and at(dib, site) and not dibWatched(party) and not dibTaken(party) and not keepTried(party).
    Time 1.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert dibWatched(party). Assert following(dib, party). }
    On failure { Assert keepTried(party). }
    Result "'Aw,' says Dib. He lets himself be held. After a moment he leans on you, by accident, and falls to watching the lens go round.".
    Otherwise "'I'm all right,' says Dib, and ducks under your arm. 'I'm not a baby.'".
  }

  // Seddon, who would not have the lamp touched, puts the oil-can in the company's hand at the first call.
  Rule seddon_relents when lampForbidden(party) and callN(tide) >= 1 and orrinPost(orrin)
    says "At the first call a voice you know from the lamp room, flat and tired: 'Oil's in the store. Don't let it go out. I'll not say I was wrong.'" {
    Retract lampForbidden(party).
  }

  // Corrie: she answers the second call, unless she has been promised something for it.
  Rule corrie_answers when (callN(tide) >= 3 or (callN(tide) >= 2 and not gaffLoud(party))) and not corrieSold(party) and not corrieLost(party) and watch(clock) >= lastCall(tide) + 3 and at(corrie, kitchen)
    and at(corrie, ?p) says "A woman's voice, in a tone you have not heard from her: 'Sister?' A bench scrapes. A door." {
    Assert corrieLost(party). Retract at(corrie, ?p).
  }

  // Lowrie: he rings, if he is asked, and does not come back. Unasked, he answers the fourth call himself.
  Topic lowrie_ring with lowrie "Ask Mr Lowrie whether he would ring the bell for you" when lowrieOffers(party) and dark() and not lowrieRang(party) once {
    Says "'You ask,' says Lowrie. He stands. He is taller than the coat. 'Two hours is what I have in my arms. It is a good use.' He goes out into the fog with no light, and you hear his feet on the rock, and, after some time, the bell.".
    On discuss { Assert lowrieRang(party). Retract at(lowrie, keeper_room). Assert at(lowrie, bell_hut). Set bellUntil(tide) to watch(clock) + 12. }
  }
  Rule lowrie_done when lowrieRang(party) and watch(clock) >= bellUntil(tide) and not lowrieGone(party)
    and at(lowrie, ?p) says "The bell stops, in the middle of a stroke." {
    Assert lowrieGone(party). Retract at(lowrie, ?p).
  }
  Rule lowrie_walks when callN(tide) >= 4 and not lowrieRang(party) and not lowrieSpared(party) and not lowrieGone(party) and hunting()
    and at(lowrie, ?p) says "A door opens, and a slow step goes down the stair and out, and a dry voice says, politely, to nobody: 'I am called.'" {
    Assert lowrieGone(party). Retract at(lowrie, ?p).
  }

  // Hettie: if the night never reaches a fourth call, nothing takes her. Otherwise the fourth call is Tam.
  Rule hettie_spared when hour(clock) >= 6 and hour(clock) < 12 and reachedAt(tide) > 0 and watch(clock) >= reachedAt(tide) + 90 and not hettieDecided(party) and not hettieTaken(party) {
    Assert hettieDecided(party). Assert hettieKept(party).
  }
  Rule hettie_kept_held when callN(tide) >= hettieAt(tide) and not hettieDecided(party) and not hettieTaken(party) and hettieHeld(party)
    says "At the call, aloud, in Hettie's voice, steady: 'Tam, I'm not coming.' Then nothing, for the length of a held breath. Then the sound of a woman being sat down." {
    Assert hettieDecided(party). Assert hettieKept(party).
  }
  Rule hettie_kept_loved when callN(tide) >= hettieAt(tide) and not hettieDecided(party) and not hettieHeld(party) and orrinDeclared(party) and at(hettie, lamp_room)
    says "At the call, a whisper: 'He'll have to do without. I've somebody here.'" {
    Assert hettieDecided(party). Assert hettieKept(party).
  }
  Rule hettie_walks when callN(tide) >= hettieAt(tide) and not hettieDecided(party) and not hettieHeld(party) and (not orrinDeclared(party) or not at(hettie, lamp_room)) and not hettieTaken(party) and not hettieKept(party)
    and at(hettie, ?p) says "At the call, Hettie's voice: 'That's Tam. Excuse me.' A shawl taken off its peg, a door, and an unhurried step going down to the landing." {
    Assert hettieDecided(party). Assert hettieWalking(party). Set walkAt(tide) to watch(clock). Retract at(hettie, ?p). Assert at(hettie, landing).
  }
  Rule hettie_goes when hettieWalking(party) and watch(clock) >= walkAt(tide) + 4 and not hettieKept(party) and not hettieTaken(party) and not orrinChasing(party)
    and at(hettie, ?p) says "From the landing, no splash. The dog begins to howl." {
    Assert hettieTaken(party). Retract hettieWalking(party). Retract at(hettie, ?p).
  }
  // Calling Hettie back needs standing with her: the company must have sat with her and heard her out (love of two). One try.
  Action stop_hettie(actor: group, site: place) "Take Hettie by both hands on the landing and say her name" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, landing) and at(hettie, landing) and hettieWalking(party) and not hettieKept(party) and love(tide) >= 2 and not stopTried(party).
    Time 0.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert hettieKept(party). Retract hettieWalking(party). Retract at(hettie, landing). Assert at(hettie, kitchen). }
    On failure { Assert stopTried(party). }
    Result "'Hettie,' you say. 'Hettie. It is not him. He would not say it like that.' She stands with her hands in yours, and her face goes through several things, and she says, 'No. He wouldn't. He'd say it as if it were the end of a joke.' Her mouth works. Then she laughs, and has to sit on the step. You take her home.".
    Otherwise "She looks past you. 'I shan't be long,' she says, kindly, and takes her hands away.".
  }
  Action hold_hettie(actor: group, site: place) "Sit with Hettie, with her hand in yours, and not let go" {
    Requires able(actor) and company(actor) and at(actor, site) and at(hettie, site) and hettieSecret(party) and not hettieHeld(party) and not hettieTaken(party) and not hettieKept(party) and callN(tide) >= 1 and not holdTried(party) and (at(actor, kitchen) or at(actor, lamp_room)).
    Time 1.
    Resolve check(actor, insight, dc_fair).
    On success { Assert hettieHeld(party). Increase love(tide) by 1. }
    On failure { Assert holdTried(party). }
    Result "You do not argue. You only take her hand across the table, and hold it, and tell her the true thing, which is that you are afraid of the cistern and would like not to be alone. She lets you. She does not take it back.".
    Otherwise "Hettie pats your hand, and takes hers away, and goes on looking at the window.".
  }

  // Seddon follows, if he has spoken. If he is held to his lamp, he does not. Before he goes the room can see whether he
  // is sure of her, and the company has the length of two watches to keep him at the lamp.
  Observe orrin_wavers near orrin when hettieWalking(party) and orrinDeclared(party) and not orrinChasing(party) and not orrinHeld(party) and love(tide) < 4 "Seddon is at the head of the stair. His hands will not settle on the rail. She has not looked back at him once tonight, and he knows it.".
  Observe orrin_certain near orrin when hettieWalking(party) and orrinDeclared(party) and not orrinChasing(party) and not orrinHeld(party) and love(tide) >= 4 "Seddon is at the head of the stair with his jersey already inside out. He is not looking at the lamp.".
  Action hold_orrin(actor: group, site: place) "Put a hand on Seddon's arm: keep the lamp; you will bring her back" {
    Speaker orrin.
    Requires able(actor) and company(actor) and at(actor, site) and at(orrin, site) and hettieWalking(party) and orrinDeclared(party) and not orrinChasing(party) and not orrinHeld(party).
    Time 0.
    On success { Assert orrinHeld(party). }
    Result "'Keep the lamp,' you say. 'We'll bring her.' His hand is on the rail. It stays there. He does not take his eyes from the dark landing.".
  }
  Rule orrin_follows when hettieWalking(party) and orrinDeclared(party) and orrinPost(orrin) and not orrinHeld(party) and watch(clock) >= walkAt(tide) + 2 and not orrinChasing(party) and not hettieKept(party) and not hettieTaken(party)
    and at(orrin, ?p) says "An oil-can set down hard. Boots on the iron stair, three at a time, going down in the dark." {
    Assert orrinChasing(party). Retract orrinPost(orrin). Retract at(orrin, ?p). Assert at(orrin, landing). Set walkAt(tide) to watch(clock).
  }
  Rule chase_wins when orrinChasing(party) and watch(clock) >= walkAt(tide) + 2 and love(tide) >= 4 and not hettieKept(party) and not hettieTaken(party)
    and at(hettie, ?p) says "From the landing, a man's voice, ordinary: 'Hettie, come up. It's cold.' And after a while a woman's: 'Yes. All right.'" {
    Assert hettieKept(party). Retract hettieWalking(party). Assert orrinFreed(party). Retract at(hettie, ?p). Assert at(hettie, kitchen). Retract at(orrin, ?p). Assert at(orrin, kitchen). Retract orrinChasing(party).
  }
  Rule chase_loses when orrinChasing(party) and watch(clock) >= walkAt(tide) + 2 and love(tide) < 4 and not hettieKept(party) and not hettieTaken(party)
    and at(hettie, ?p) says "From the landing, a splash, and then another. For a time the lamp goes round above the empty water, and the bell does not ring." {
    Assert hettieTaken(party). Assert orrinTaken(party). Retract hettieWalking(party). Retract orrinChasing(party). Retract at(hettie, ?p). Retract at(orrin, ?p).
  }

  // What is left in the rooms, for whoever walks into them.
  Observe gaff_left at kitchen when gaffTaken(party) "Gaff's chair is empty. His mug stands on the arm of it, still full, and the dog has her nose to the door.".
  Observe dib_left at kitchen when dibTaken(party) "The boy's place on the settle is empty. The store door is open, and the hatch is open, and there is a wet print on the first rung, and another on the second.".
  Observe corrie_left at kitchen when corrieLost(party) "Corrie Fenwether's coil lies on the bench where she put it down, with the ledger beside it.".
  Observe piers_left at kitchen when piersLost(party) "Piers Tolland's stool is in the middle of the floor, and the satchel is not on it.".
  Observe lowrie_left at keeper_room when lowrieGone(party) "The bunk is empty.".
  Observe hettie_left at landing when hettieTaken(party) "A black straw bonnet lies on the winch, set down neatly.".
  Observe orrin_left at landing when orrinTaken(party) "A navy jersey, darned at both elbows and worn inside out, lies on the steps.".

  // The lamp left to itself: without Seddon at his post the party must keep it, and fill it.
  Observe lamp_unkept at lamp_room when not orrinPost(orrin) and not orrinTaken(party) "Nobody is keeping the lamp. The oil-can stands where it was put down.".
  Observe lamp_unkept_two at lamp_room when orrinTaken(party) "The lamp is lit, and no one is keeping it. The oil-can stands where it was put down, and there is nobody to fill it.".

  // Piers: noon of the second day. If he is promised company he waits and goes with them; if not, he goes alone.
  Topic piers_escort_t with piers "Tell Piers you will walk him over at noon, and he is to wait" when reachedAt(tide) > 0 and not piersEscort(party) once {
    Says "Piers's whole body unwinds. 'At noon,' he says. 'Together. With the rope.' He takes his hat off his knee and puts it on. 'Thank you. I shall be perfectly ready. I have been ready since Tuesday.'".
    On discuss { Assert piersEscort(party). }
  }
  Rule piers_waits when piersEscort(party) and not piersLost(party) and hour(clock) >= 8 and reachedAt(tide) > 0 and watch(clock) >= reachedAt(tide) + 90 and not following(piers, party) {
    Assert following(piers, party).
  }
  Rule piers_leaves when state(tide, low) and hour(clock) >= 11 and reachedAt(tide) > 0 and watch(clock) >= reachedAt(tide) + 90 and not piersEscort(party) and not piersLost(party) and not at(party, shore_road) and at(piers, kitchen)
    and at(piers, ?p) says "The door below opens, and a thin man's quick step goes out across the rock, towards the posts, and does not come back." {
    Assert piersLost(party). Retract at(piers, ?p).
  }
  Action tell_piers_notice(actor: group, site: place) "Put the Board's notice into Seddon's hand, and stay while he reads it" {
    Speaker orrin.
    Requires able(actor) and company(actor) and at(actor, site) and at(orrin, site) and (piersTold(party) or (piersWaits(party) and hour(clock) >= 6 and hour(clock) < 19 and reachedAt(tide) > 0 and watch(clock) >= reachedAt(tide) + 90)) and not noticeGiven(party) and not piersLost(party).
    Time 1.
    On success { Assert noticeGiven(party). }
    Result "Seddon reads it twice, standing, and folds it along its folds. 'First of next month,' he says. 'Well. It has been coming.' He puts it in his pocket and goes on with what he was doing, which was nothing." when hettieTaken(party).
    Result "Seddon reads it twice, standing, and folds it along its folds. 'First of next month,' he says. 'Well. It has been coming.' He puts it in his pocket and goes on with what he was doing, which was nothing. Hettie, who has not been told what it says, puts her hand on his sleeve.".
  }
  Relation noticeGiven(group).
}

data/adventures/skerrow/placed.kyr:
Module skerrow "The Light on Scarth Holm" {
  Entity party: group "Your company".
  // What is said of the Scarth light in the country behind it: once the company has walked the causeway out, it is old news.
  Entity word: fact "What is said of the Scarth light in the country behind it.".
  Rule word_old when crossed(party) and not stale(word) { Assert stale(word). }
  // And whether the keeper or the widow came out: the light goes dark on the coast road's lips, or it does not.
  Entity word_dark: fact "That the Scarth light lost its keeper or its widow to the sea.".
  Rule word_dark_old when crossed(party) and (hettieTaken(party) or orrinTaken(party)) and not stale(word_dark) { Assert stale(word_dark). }
}

data/adventures/skerrow/sea.kyr:
Module skerrow "The Light on Scarth Holm" {
  // ── The sea, the fog, the lamp, the bell, and what lives under the tower ───────────────────────────────────────
  // The rules a player is meant to infer and never be told: the Caller comes up with the high tide in the dark; a bright
  // lamp holds it to a knocking and a sunk lamp lets it call and climb; the bell sends it back to sea for an hour; it
  // takes whoever answers, and whoever it finds in a dark room. The causeway dries from eleven to two, every day, and
  // is fogged all hours but one to two.
  Place open_water "the open water" is room within sands at 3, 3 outdoors.

  Thing tide "the tide" at sands_mid is scenery {
    State low "The sea is out. Mud, posts, a wet shine to the horizon.".
    State high "The sea is over the causeway, brown and quick, and the posts stand in it like a drowned fence.".
  }
  Initially Assert state(tide, high).
  Measure reachedAt(entity). Measure bellUntil(entity). Measure lastRang(entity). Measure lastCall(entity). Measure callN(entity).
  Measure oil(entity). Measure oilTick(entity). Measure flasks(entity). Measure refills(entity). Measure repelUntil(entity). Measure ringN(entity). Measure lowSince(entity).
  Relation lampForbidden(group).
  Rule tide_falls when state(tide, high) and hour(clock) >= 11 and hour(clock) < 14 { Assert state(tide, low). }
  Rule tide_rises when state(tide, low) and (hour(clock) >= 14 or hour(clock) < 11) { Assert state(tide, high). }
  Rule marks_arrival when at(party, landing) and reachedAt(tide) == 0 { Set reachedAt(tide) to watch(clock). }

  // The fog is thick at every hour but one to two; a party on the sands in it is lost unless it has a line.
  Thing fog "the fog" at landing is scenery {
    State thick "The fog has come in off the sea and stands against the tower like a wall. The bell is the only direction there is.".
    State thin "The fog is thin enough to see the posts, the first dozen, and nothing beyond.".
  }
  Initially Assert state(fog, thick).
  Rule fog_thickens when state(fog, thin) and (hour(clock) >= 14 or hour(clock) < 13) { Assert state(fog, thick). }
  Rule fog_thins when state(fog, thick) and hour(clock) >= 13 and hour(clock) < 14 { Assert state(fog, thin). }
  Relation lined(group). Relation bearingTried(group). Relation lostTold(group).
  Hazard mud_lost "The sands in fog" means "Deal (3d6) physical damage to ally unless constitution save against (14).".
  Rule sands_fog at sands_mid when at(party, sands_mid) and state(fog, thick) and not lined(party) and not lostTold(party)
    says "The posts stop. You walk the way the posts were, and the mud takes you to the knee, and the tower is behind you now, or beside you. The bell, when it comes, comes from everywhere." {
    Assert strikes(mud_lost, party). Assert lostTold(party).
  }
  Rule line_washes when lined(party) and state(tide, high) { Retract lined(party). Retract bearingTried(party). }
  Rule lost_clears when lostTold(party) and not at(party, sands_mid) { Retract lostTold(party). }
  Hazard cold_wade "The sea coming in over the causeway" means "Deal (2d6) cold damage to ally unless strength save against (13).".
  Rule sea_comes at sands_mid when at(party, sands_mid) and state(tide, high)
    says "The sea comes over the mud from both sides at once, and then it is at your knees and pulling. You wade for the light, because it is the only direction." {
    Assert strikes(cold_wade, party). Assert at(party, landing).
  }
  Action peg_line(actor: group, site: place) "Peg a guide-line along the posts" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, shore_road) or at(actor, landing)) and holding(actor, rope) and state(tide, low) and not lined(actor).
    Time 3.
    On success { Assert lined(actor). }
    Result "You tie the rope to the first post, and the second, and the third, hand over hand, a long grey line of it paying out into the fog. It will take you out. It will bring you back.".
  }
  Action take_bearing(actor: group, site: place) "Listen for the bell and take a bearing on it" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, shore_road) or at(actor, landing)) and state(tide, low) and not lined(actor) and not bearingTried(party).
    Time 1.
    Resolve check(actor, wayfinding, dc_hard).
    On success { Assert lined(actor). }
    On failure { Assert bearingTried(party). }
    Result "The bell tolls once, a long way off and to the left of where it ought to be. Twice more. You pace it out against the posts. After that you know where the line of the posts is, which is the same as having a rope.".
    Otherwise "The bell comes from the right, and then the left, and then both. You cannot say where it is.".
  }

  // The lamp: oil is time. Orrin fills it while he keeps his post; when he does not, someone must.
  Thing lamp "the lamp" at lamp_room is scenery {
    State bright "The lamp burns white.".
    State low "The lamp has sunk to a blue bead.".
    State out "The lamp is out.".
  }
  Initially Assert state(lamp, bright). Initially Set oil(lamp) to 10. Initially Set flasks(store) to 7. Initially Set refills(lamp) to 1.
  Relation orrinPost(group). Initially Assert orrinPost(orrin).
  Rule oil_burns when reachedAt(tide) > 0 and watch(clock) >= oilTick(lamp) + 6 and oil(lamp) > 0 { Decrease oil(lamp) by 1 or to nothing. Set oilTick(lamp) to watch(clock). }
  Rule lamp_goes_low when oil(lamp) < 4 and oil(lamp) > 0 and not state(lamp, low) { Assert state(lamp, low). Set lowSince(lamp) to watch(clock). }
  Rule lamp_goes_out when oil(lamp) <= 0 and not state(lamp, out) { Assert state(lamp, out). }
  Rule lamp_brightens when oil(lamp) >= 4 and not state(lamp, bright) { Assert state(lamp, bright). }
  Rule orrin_fills when orrinPost(orrin) and oil(lamp) < 6 and refills(lamp) > 0 {
    Increase oil(lamp) by 4. Decrease refills(lamp) by 1.
  }
  Action fill_lamp(actor: group, site: place) "Fill the lamp from a flask out of the store" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lamp_room) and (not lampForbidden(party) or not orrinPost(orrin)) and flasks(store) > 0 and oil(lamp) < 10.
    Time 1.
    On success { Decrease flasks(store) by 1. Increase oil(lamp) by 4. }
    Result "You carry the flask up the iron stair and fill the reservoir through the brass funnel, and the flame stands up again. The oil smells of fish.".
  }
  Action bring_flasks(actor: group, site: place) "Take two flasks of oil up to the lamp room and leave them by the funnel" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, store) and (not lampForbidden(party) or not orrinPost(orrin)) and flasks(store) > 1.
    Time 1.
    On success { Decrease flasks(store) by 2. Increase oil(lamp) by 8. }
    Result "Two flasks, one under each arm, up the dark stair. You pour them in together, and stand with your hands wet, listening to the lens turn.".
  }

  // The bell: an hour under the bell, the Caller is put back to sea. Seddon rings it from the lamp room, by a cord, in the
  // first four watches of every ten of the dark.
  Thing fog_bell "the fog-bell" at bell_hut is scenery {
    State hanging "The bronze bell hangs from its beam, still.".
  }
  Initially Assert state(fog_bell, hanging).
  Query bellRecent() means watch(clock) < bellUntil(tide).
  // A sunk lamp is the clock: while it is out the bell does not hold the Caller below.
  Query repelled() means watch(clock) < repelUntil(tide).
  Query hunting() means dark() and state(tide, high) and not repelled() and (not bellRecent() or state(lamp, out)).
  // The voices come from midnight to six, whatever the lamp is doing.
  Query calling() means hunting() and hour(clock) < 6.
  Observe seddon_store at lamp_room when at(orrin, lamp_room) and orrinPost(orrin) and oil(lamp) < 3 "Seddon turns the empty oil-can in his hands. 'I don't go in the store after dark,' he says. 'The hatch.' He does not say whose errand that makes it.".
  Observe cord_pulled at lamp_room when at(orrin, lamp_room) and bellRecent() and lastRang(tide) > 0 "Seddon has the bell-cord in his fist, and pulls to a count he does not say. Far out on the east point the bell answers.".
  // The company may ring once between noons: the weights that drive the lens drive the bell, and the oil goes with it.
  Rule bell_rested when hour(clock) >= 12 and hour(clock) < 13 and ringN(tide) > 0 { Set ringN(tide) to 0. }
  Rule orrin_rings when orrinPost(orrin) and dark() and state(tide, high) and watch(clock) >= lastRang(tide) + 10 and not bellRecent()
    says "From the east point the bell begins: slow, evenly, a stroke to every breath." {
    Set bellUntil(tide) to watch(clock) + 4. Set lastRang(tide) to watch(clock).
  }
  Action ring_bell(actor: group, site: place) "Take the bell-cord and ring the fog-bell for an hour" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lamp_room) and not bellRecent() and ringN(tide) < 1 and oil(lamp) > 2.
    Time 2.
    On success { Set bellUntil(tide) to watch(clock) + 6. Increase ringN(tide) by 1. Decrease oil(lamp) by 2. }
    Result "The cord is warm where a hand has worn it, and it pulls back. The lens slows a little, as the weights are shared, and the bell goes out over the fog, a long bronze note and a long silence, and the sea, which has been listening, goes a little further off.".
  }

}

data/adventures/tallow/company.kyr:
Module tallow "Tallow Deep" {
  Company party "Your company" of 3 at road.
  Initially Set quantity(party, gold) to 14. Initially Set quantity(party, rations) to 3.
}

data/adventures/tallow/creatures.kyr:
Module tallow "Tallow Deep" {
  // ---------------------------------------------------------------------------------------------------------------
  // Who lives where, and what each does to the others. Read from the top of the hill down:
  // bats roost and the spiders eat them; the rats eat the Tallymen's leavings and the spiders eat the rats; the
  // slump eats what the bats drop; the ghouls eat the Company's dead and raid the rats; the stalkers eat the ghouls
  // and any Tallyman who goes below alone; the custodians eat nothing, and keep the measure.
  Relation scattered(group). Relation baited(group). Measure scatteredAt(group). Measure baitedAt(group).
  Measure muffledUntil(group). Relation muffled(group).

  // The upland.
  Person owlbear "the owlbear" at scrub {
    Role "a she-owlbear, heavy with a late litter". Species owlbear. Level 2. Numbers 1. Temperament territorial.
    Warns "The heather ahead heaves, and something broad as a cart turns its head: a beak where a muzzle should be, a mat of brown feathers on a bear's shoulders. It rises on its hind legs and the sheep's bones slide off its back. It does not roar. It breathes in, once, long.".
    Comes "The owlbear drops on all fours and comes through the heather like a landslide.".
    Flinches "The owlbear backs into the scrub with her head low, and a sound comes out of her like a kettle.".
    Lair scrub.
  }
  Action bait_owlbear(actor: group, site: place) "Leave a ration of meat in the heather and back away" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, scrub) and at(owlbear, scrub) and able(owlbear)
      and not tolerates(owlbear, actor) and quantity(actor, rations) >= 2.
    Time 0.
    On success { Decrease quantity(actor, rations) by 2. Assert tolerates(owlbear, actor). }
    Result "The owlbear watches you set it down, a haunch's worth, and sniffs the air twice before she lowers her head to it.  You walk round her to the rim with your hands out from your sides.".
  }

  Observe owlbear_fed at scrub when tolerates(owlbear, party) and able(owlbear) "The she-owlbear has her head down in what you left. Her flank goes in and out, and she does not lift her head as you pass.".

  // The Rising and the bat chimney.
  Person rising_bats "the bats of the Rising" at rising_gallery {
    Role "a great roost of bats". Species bat. Numbers 12. Peaceable.
  }
  Person chimney_bats "the bats of the chimney" at bat_chimney {
    Role "a smaller roost, fouling the floor". Species bat. Numbers 6. Peaceable.
  }
  Person chimney_centipedes "the centipedes in the guano" at bat_chimney {
    Role "pale centipedes the length of an arm, that live in the guano". Species centipede. Level 1. Numbers 2. Temperament territorial.
    Warns "The guano on the floor stirs, and a long pale body rears out of it, jointed and feeling the air.".
    Lair bat_chimney.
  }

  // The Tallymen's rats, and the Settling Cistern's.
  Person rats "the rats of the old stores" at stores {
    Role "rats as big as cats, that live on the Tallymen's leavings". Species great_rat. Level 2. Numbers 5. Temperament territorial.
    Warns "The dark along the shelves shifts and resolves into rats, a great many, sitting up on their haunches along the gnawed wood.".
    Lair stores.
  }
  Person settling_rats "the rats of the Settling Cistern" at settling {
    Role "grey rats as fat as terriers, that have the mud-bank for a warren". Species great_rat. Level 2. Numbers 5. Temperament territorial.
    Warns "The mud-bank is moving: grey backs, wet whiskers, a hundred small black eyes turning in the lantern-light.".
    Lair settling.
  }
  Action lay_ratsbane_stores(actor: group, site: place) "Lay ratsbane along the shelves" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, stores) and holding(actor, ratsbane) and not baited(rats) and not dead(rats).
    Time 0.
    On success { Spend ratsbane from actor. Assert baited(rats). Set baitedAt(rats) to watch(clock). }
    Result "You lay the poison down in rag twists on the sill and in the gnawed corners, and back away. The rats watch you do it. They do not yet know what you have done.".
  }
  Action lay_ratsbane_settling(actor: group, site: place) "Lay ratsbane along the mud-bank" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, settling) and holding(actor, ratsbane) and not baited(settling_rats) and not dead(settling_rats).
    Time 0.
    On success { Spend ratsbane from actor. Assert baited(settling_rats). Set baitedAt(settling_rats) to watch(clock). }
    Result "You lay the poison in the silt where the runs go down to the water. The rats do not stir.".
  }
  Rule rats_die_stores when baited(rats) and watch(clock) >= baitedAt(rats) + 36 { Slay rats. Retract baited(rats). }
  Rule rats_die_settling when baited(settling_rats) and watch(clock) >= baitedAt(settling_rats) + 36 { Slay settling_rats. Retract baited(settling_rats). }
  Observe rats_dead_stores at stores when dead(rats) "The rats lie where they stopped, in the corners and under the shelves, stiff. The stores no longer stink of the living.".
  Observe rats_dead_settling at settling when dead(settling_rats) "The mud-bank is silent. A great many small grey bodies lie on it, and the silt is the stiller for them.".

  // The Spider Gallery: bats and rats are what the spiders eat; with the rats gone they come down to the water.
  Person spiders "the spiders of the gallery" at spider_gallery {
    Role "cave spiders with a hound's body, strung in tiers among the webs". Species cave_spider. Level 3. Numbers 2. Temperament territorial.
    Warns "The tiers of web tremble. High in the vault, where the lantern does not reach, two grey shapes with too many legs turn to look down at you, together.".
    Comes "The nearer spider lets go of the vault and falls on its line.".
    Lair spider_gallery. Refuge spider_vault.
  }
  Action burn_webs(actor: group, site: place) "Put a flame to the webs" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, spider_gallery) and at(spiders, spider_gallery) and able(spiders)
      and capable(actor, flame).
    Time 0.
    On success { Retract at(spiders, spider_gallery). Assert at(spiders, spider_vault). 
      Set scatteredAt(spiders) to watch(clock). }
    Result "The web goes up in a long soundless sheet, and the gallery is lit orange from end to end. Shapes with too many legs go up the vault in a rush, into the dark above the climb, and the bats that were wrapped in the silk fall out of it, dead and singed.".
  }
  Rule spiders_return when at(spiders, spider_vault) and watch(clock) >= scatteredAt(spiders) + 144 and not at(party, spider_gallery) {
    Retract at(spiders, spider_vault). Assert at(spiders, spider_gallery).
  }
  Place spider_vault "the web-roofed vault" is room within l2 at 2, 1 underground.
  Initially Assert unlit(spider_vault).
  Passage gallery_vault "the climb into the vault" is ladder between spider_gallery and spider_vault needing climbing or rope.
  Observe vault_scene at spider_vault when true "A domed hollow in the Aenean masonry, roofed in web, where the spiders have their wrapped larder. Bats are hung in it, and a small grey cat, and something that was a man in a bend-watch's baldric, lashed to a beam in silk to the neck. Treve went up the service walk after the boy's cat, three weeks since, and the ledge was two paces wide.".
  Rule spiders_range when dead(rats) and dead(settling_rats) and at(spiders, spider_gallery) and not scattered(spiders) and untilLight(clock) == 1 and dice(clock) <= 40 {
    Retract at(spiders, spider_gallery). Assert at(spiders, settling). Assert scattered(spiders).
  }
  Observe spiders_down at settling when scattered(spiders) "The silt-bank is webbed over, in sheets, in tiers. The rats are gone and something else has taken their place.".

  // The Cistern Hall: the slump under the black water.
  Person slump "the slump in the Cistern Hall" at cistern_hall {
    Role "clay that water has worked loose and set moving". Species slump. Level 3. Numbers 1. Temperament territorial.
    Warns "The black water at the foot of a column swells, smooth as a belly, and slides toward you, and the column is clean to the waterline as no stone in the hall is clean.".
    Comes "The black water rises in a wave that is not a wave, and the wave has a front.".
    Lair cistern_hall. Refuge the_cap.
  }
  Kind guano_sack "a sack of bat guano" is treasure worth 2 weighing 1 described "A sack of the bat chimney's guano, dry, pale and ammoniac. A farmer would pay for it; so, perhaps, would something that eats it.".
  Item guano_a "a sack of guano" is guano_sack at bat_chimney.
  Item guano_b "a sack of guano" is guano_sack at bat_chimney.
  Item guano_c "a sack of guano" is guano_sack at bat_chimney.
  Action feed_slump(actor: group, site: place) "Heap guano on the shore for the slump" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, cistern_hall) and at(slump, cistern_hall) and able(slump)
      and holding(actor, guano_sack) and not tolerates(slump, actor).
    Time 0.
    On success { Spend guano_sack from actor. Assert tolerates(slump, actor). }
    Result "You tip the sack out on the white shore. The water reaches up the stone and takes it, all of it, and the shore is clean. The hall has gone quiet. Whatever is in the water has turned away.".
  }
  Observe slump_fed at cistern_hall when tolerates(slump, party) and able(slump) "The black water lies flat along the causeway, and the columns on either side of it are clean to the waterline.".
  Observe slump_sign at north_walk as sign when not dead(slump) "The black water along the north shore is scoured clean of scum and droppings. A slow ripple moves against the current, and a rat's skull sits on the lip of the stone, picked white.".

  // The Ossuary: the dead of the Breakthrough, and what feeds on them.
  Person ghouls "the ghouls of the Ossuary" at ossuary {
    Role "dead things in the Company's rotted leather, crouched among the stacked dead". Species ghoul. Level 3. Numbers 4. Temperament territorial.
    Warns "Three of the stacked dead sit up, in the dim, with the unhurried awkwardness of things that have been eating. Their hands are long.".
    Comes "The nearest ghoul comes down off the stack on all fours.".
    Lair ossuary.
  }
  Action lay_dead(actor: group, site: place) "Say the Company's burial words over the stacked dead" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ossuary) and at(ghouls, ossuary) and able(ghouls) and not ritedFailed(actor)
      and not knows(actor, vault_laid).
    Time 0.
    Resolve check(actor, rites, dc_hard).
    On success { Slay ghouls. Assert laid(party). }
    On failure { Assert ritedFailed(actor). }
    Result "You say the words over them, all of them, to the last. The long hands go still on the stacked boots. The dead are only dead.".
    Otherwise "The words go out into the vault and come back changed. The nearest ghoul tips its head and smiles, and the smile is wrong in a way you recognise as grief.".
  }
  // Told by the one who held the lamp how the Foreman laid them, the words are said in his order, and the rite is easier.
  Action lay_dead_told(actor: group, site: place) "Say the burial words in the order Barrick says Carr laid the dead" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ossuary) and at(ghouls, ossuary) and able(ghouls) and not ritedFailed(actor)
      and knows(actor, vault_laid).
    Time 0.
    Resolve check(actor, rites, dc_fair).
    On success { Slay ghouls. Assert laid(party). }
    On failure { Assert ritedFailed(actor). }
    Result "You begin with the one he laid first, nearest the wall, and go along the stack as he went, one at a time, with the lamp held low. The long hands go still on the stacked boots. The dead are only dead.".
    Otherwise "You have the order, and not the voice. The words go out into the vault and come back changed. The nearest ghoul tips its head and smiles, and the smile is wrong in a way you recognise as grief.".
  }
  Relation laid(group). Relation ritedFailed(group).
  Observe carr_sits at gate_house when true "Against the wheel of the Calx Gate a man in a Foreman's coat sits with his chin on his chest and an oilcan in his hand, unopened. He has been here sixty years. The pawl above him is red with rust. He never reached it.".  
  Observe ghouls_signs at breach as sign when not dead(ghouls) "From the Ossuary side, the smell of old sweet rot, and a sound like a stack of wood being gently rearranged.".

  // The Quiet Gallery: the stalkers hunt by breath, and the Bore has its custodians.
  Person stalkers "the hollow-stalkers" at quiet_gallery {
    Role "three pale many-jointed things, each with a ring of wet pits for a mouth; the smallest is scarred, and carries a hobnailed boot in its jaws". Species hollow_stalker. Level 8. Numbers 3. Temperament ambush.
    Warns "In the dead quiet of the gallery, something turns toward you. A ring of wet pits opens in a long pale head, far ahead, and in another, and in a third behind it, and every pit of them is pointed at your mouth. The smallest is carrying something.".
    Comes "They come along the ceiling, soundless, each the length of a man's body laid on legs.".
    Lair quiet_gallery.
  }
  Observe stalkers_remains at gear_hall as sign when not dead(stalkers) "At the mouth of the Quiet Gallery a miner's tin lamp lies on its side, rusted to the floor, with a coil of rope beside it that has gone to black string, cut clean through a hand above where it was tied. Nothing else is left.".
  Action muffle(actor: group, site: place) "Bind blankets over boots and wrap wet cloth across mouths" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, breach) or at(actor, gear_hall) or at(actor, dial_room)) and holding(actor, blanket) and not muffled(actor).
    Time 6.
    On success { Spend blanket from actor. Assert muffled(actor). Set muffledUntil(actor) to watch(clock) + 18.
      Assert tolerates(stalkers, actor). }
    Result "You cut the blanket, bind your feet in it and tie wet strips across your faces, and breathe through the cloth. It is stifling. Your own heartbeat is deafening. You have, you think, two hours before the cloth is dry.".
  }
  Observe cloth_drying at quiet_gallery as sign when muffled(party) and watch(clock) >= muffledUntil(party) - 3 "The wet cloth across your mouth has gone stiff at the edges. Another half hour, and it will not hold your breath in.".
  Observe cloth_drying_dial at dial_room as sign when muffled(party) and watch(clock) >= muffledUntil(party) - 3 "The wet cloth across your mouth has gone stiff at the edges. Another half hour, and it will not hold your breath in.".
  Rule unmuffle when muffled(party) and watch(clock) >= muffledUntil(party) {
    Retract muffled(party). Retract tolerates(stalkers, party).
  }

  Person custodians "the custodians" at gear_hall {
    Role "two man-high figures of grey metal, winding something". Species clockwork_soldier. Level 3. Numbers 2. Temperament territorial.
    Warns "The two figures stop winding. Both turn their heads together, with a tick, and look at you with no faces. A third tick, and the wire in the middle of the hall swings a little wider, and the figures take one step each, in step, toward the middle.".
    Comes "The custodians cross the floor in perfect step.".
    Lair gear_hall.
  }
  Thing escapement "the Gear-Hall's escapement" at gear_hall {
    State running "A bank of tiny wheels turns against another bank, and a dial of grey glass shows the beat: one, and one, and one.".
    State set "The escapement has been set to the beat the Aeneans cut into the Tally-Wall: one swing in six breaths. The custodians have gone back to their winding.".
  }
  Initially Assert state(escapement, running).
  Action set_by_wall(actor: group, site: place) "Set the escapement to the beat cut in the Tally-Wall" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gear_hall) and knows(actor, period_known) and state(escapement, running).
    Time 0.
    On success { Assert state(escapement, set). Assert tolerates(custodians, actor). }
    Result "Under the Company's chalk the engineers' figure was one swing in six breaths. You set the wheels to it, one at a time, with the tip of a knife. The wire swings once, steadily. The figures stop. The nearer one inclines its head to you, exactly as far as a clerk does, and goes back to winding.".
  }
  Action set_by_chart(actor: group, site: place) "Set the escapement to the beat in the chart's border" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gear_hall) and holding(actor, celestial_chart) and state(escapement, running).
    Time 0.
    On success { Assert state(escapement, set). Assert tolerates(custodians, actor). }
    Result "The chart's border is a beat, marked in tiny strokes of the same grey ink. You read it off and set the wheels to match. The wire swings once, steadily. The figures stop, incline their heads, and go back to winding.".
  }
  Rule beat_pleases when state(escapement, set) and not tolerates(custodians, party) and at(party, gear_hall) { Assert tolerates(custodians, party). }
}

data/adventures/tallow/keeping.kyr:
Module tallow "Tallow Deep" {
  // ── Keeping ─────────────────────────────────────────────────────────────────────────────────────────────────────
  // What the hill is about: things kept after the reason for keeping them has gone. The makers' weight is kept
  // swinging by figures that wind it; the Aeneans kept a cap over what they could not read; the Company kept its dead
  // in a vault and its secret in a desk; the Tallymen keep a road they did not make; the village keeps its back
  // turned. Each of them is answerable to something it will not look at.
  Relation namesRead(group). Relation ticked(group).

  Chapter ch_swallet "The Village That Does Not Look" when true "Swallet keeps its back to the ridge. Everyone in it can tell you the way in, and nobody will tell you why they stopped going.".
  Chapter ch_dayl "The Company's Works" when been(party, adit) "The Brasiers left in a season, and left their tools hanging. Other people have been living in their leavings since.".
  Chapter ch_cistern "What the Legion Capped" when been(party, cistern_hall) "A hall built to settle a river, and, in the middle of it, a lid.".
  Chapter ch_bore "The Weight" when been(party, breach) "Under the lid there is a stair, and at the bottom of the stair something has been counting for longer than there have been people to count for.".

  // A tick under the pipe, from the first day: the figure in the Bore is six breaths.
  Observe pipe_tick at green as sound when true "Under the gurgle of the pipe, so faint you take it for your own pulse, something ticks: once, and again, six breaths apart.".
  Observe shaft_tick at winding as sound when true "Under the water far below the cage there is a tick, and a tick, evenly, not a drip. It has the patience of a thing that does not mind who is listening.".
  Topic dunstan_tick with dunstan "Ask Barrick about the ticking under the pipe" when true {
    Says "'You hear it, then,' says Barrick. 'Not many do. We heard it in the shaft the winter before we broke the wall, and the Foreman had us stop work to listen, and it kept time, and not ours: six breaths between, and I counted a thousand of them before the wall went.' He drinks. 'Carr said the Legion's engineers heard it too. He'd read their wall. He said they were the first people who had the sense to be afraid of it, and the only ones who had the sense to leave it running.'".
    On discuss { Assert knows(actor, period_known). }
  }

  // The Foreman's ledger: fourteen names and the wages owed them.
  Topic joss_father with joss "Show Cador the fourteen names in the Foreman's ledger" when holding(actor, carr_ledger) and knows(actor, ledger_read) and not namesRead(party) once {
    Says "Cador reads down the column with a clerk's finger, past the Foreman's name at the head and a struck-through sixth, and stops at the ninth. TARBET, J., SENIOR: 3 DAYS. He does not move. 'I was told he went to Porthwen for work,' he says at last. 'Thirty years, I've been running brandy under the place he was lying in.' He gives the ledger back with both hands. 'The Company never paid him,' he says, and laughs, and it is a bad laugh. 'Three days. I should like them paid.'".
    On discuss { Assert ticked(party). }
  }
  Topic dunstan_names with dunstan "Read Barrick the names from the Foreman's ledger" when holding(actor, carr_ledger) and knows(actor, ledger_read) and not namesRead(party) once {
    Says "You read the fifteen. Barrick sits with his tankard untouched. At the sixth name, which is his own, struck through in a different ink because Carr knew he had gone up the shaft alive and would not have him owed, he lifts his head. 'I did,' he says. 'I did go up. I have been dead sixty years, and nobody has said.' He takes the ledger and reads the rest aloud himself, to the room, and Lowen Pook, at her pots, says each after him. Afterwards he pins the page to the beam beside the tokens.".
    On discuss { Assert namesRead(party). }
  }
  Observe names_pinned at taproom when namesRead(party) "Beside the Company's tokens, pinned to the beam, a page from a ledger: fourteen names, and by each of them, in Lowen's hand, a day's wage in pence, paid.".
  Action read_names(actor: group, site: place) "Read the fourteen names aloud over the stacked dead" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ossuary) and at(ghouls, ossuary) and able(ghouls) and holding(actor, carr_ledger) and knows(actor, ledger_read).
    Time 0.
    On success { Slay ghouls. Assert laid(party). }
    Result "You read them: the first to the Foreman, who is not here, and the last to the boy in the first boots. At the ninth, the long hands lie down. At the fourteenth, no one in the vault is eating.".
  }

  Milestone m_names "had the fourteen counted" worth 200 when namesRead(party) or ticked(party) or laid(party).
  // The Dial's shelf: whatever has been taken off it and not set back (carried, sold, dropped) is owed. Each missing piece
  // is a further chance in ten of the Wend rising at first light (works.kyr), and the tick under Swallet's pipe goes late.
  Relation setBack(entity). Measure shelfRestored(group).
  Query orreryOut() means not at(dial_orrery, dial_room) and not setBack(dial_orrery).
  Query chartOut() means not at(dial_chart, dial_room) and not setBack(dial_chart).
  Query crystalOut() means not at(dial_lens, dial_room) and not setBack(dial_lens).
  Query compassOut() means not at(dial_compass, dial_room) and not setBack(dial_compass).
  Query shelfShort() means orreryOut() or chartOut() or crystalOut() or compassOut().
  Observe pipe_tick_slow at green instead of pipe_tick as sound when shelfShort() "Under the gurgle of the pipe the tick has changed. It comes late, and then twice, and then late. Lowen has stopped wiping her pots.".
  Observe pipe_cloudy at green when shelfShort() "The trough has gone from cloudy to brown, and the horses will not drink at it.".
  Action restore_orrery(actor: group, site: place) "Set the orrery back on the shelf of grey metal" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, dial_room) and holding(actor, ancient_orrery).
    Time 0.
    On success { Spend ancient_orrery from actor. Assert setBack(dial_orrery). Increase shelfRestored(party) by 1. }
    Result "You set the orrery on its own clean place in the dust. The wire swings once over the glass, and goes on.".
  }
  Action restore_chart(actor: group, site: place) "Lay the chart of the stars back on the shelf of grey metal" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, dial_room) and holding(actor, celestial_chart).
    Time 0.
    On success { Spend celestial_chart from actor. Assert setBack(dial_chart). Increase shelfRestored(party) by 1. }
    Result "The chart goes down on the shelf, grey on grey, and the stars in the floor lean a hair toward it.".
  }
  Action restore_crystal(actor: group, site: place) "Stand the lensing crystal back on the shelf of grey metal" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, dial_room) and holding(actor, lensing_crystal).
    Time 0.
    On success { Spend lensing_crystal from actor. Assert setBack(dial_lens). Increase shelfRestored(party) by 1. }
    Result "The crystal finds its ring in the dust as if it had been waiting, and the light on the glass floor draws together under it.".
  }
  Action restore_compass(actor: group, site: place) "Set the compass back on the shelf of grey metal" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, dial_room) and holding(actor, antique_compass).
    Time 0.
    On success { Spend antique_compass from actor. Assert setBack(dial_compass). Increase shelfRestored(party) by 1. }
    Result "You put the compass down, and its needle, which has pointed at the wire since you took it, lets go.".
  }
  Topic hester_report_kind with hester "Tell Lowen the old road is open" when state(calx_gate, raised) and ticked(party) and not sold_out(party) once {
    Says "Lowen Pook listens, and is a long time with the pot. 'He asked me,' she says at last, 'not to tell you. Cador. He said you would see it for yourself, or you would not.' She wipes the pot. 'I will not be the one. It's his father's grave he's been carrying brandy over, and he has paid the parish a tithe every year for it, which I did not understand till now.' She looks at the beam. 'Tell him yourself.'".
  }
  // Hunger bites: a company that has missed a meal is hurt at every half-day until it eats.
  Hazard hunger_bite "Hunger" means "Deal (1d4) physical damage to ally unless constitution save against (12).".
  Measure gnawAt(group).
  Rule gnaw_starts when hungry(party) and gnawAt(party) == 0 { Set gnawAt(party) to watch(clock) + 72. }
  Rule gnaws when hungry(party) and gnawAt(party) > 0 and watch(clock) >= gnawAt(party)
    says "Hunger gnaws at you. Somebody has stopped talking, and somebody else has started counting the ration bags." {
    Assert strikes(hunger_bite, party). Set gnawAt(party) to watch(clock) + 72.
  }
  Rule gnaw_ends when not hungry(party) and gnawAt(party) != 0 { Set gnawAt(party) to 0. }
  Action play_cards(actor: group, site: place) "Sit in on the Tallymen's game of cards for the loan of the lantern" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, tally_room) and at(joss, tally_room) and not cardsPlayed(actor).
    Time 1.
    Resolve check(actor, deception, dc_fair).
    On success { Assert cardsPlayed(actor). Assert tolerates(bend_watch, actor). Increase quantity(actor, gold) by 4. }
    On failure { Assert cardsPlayed(actor). Decrease quantity(actor, gold) by 3 or to nothing. }
    Result "The dog watches the cards, and Cador watches the dog, which is where you notice that the dog has been dealt a hand. You win four coin and the lantern's loan by turning up a knave that the dog, on reflection, had been sitting on, and Cador says, without rancour, that he will have the dog re-schooled.".
    Otherwise "You lose three coin to a dog. Cador pretends not to have seen it, which is the cruellest thing he could do.".
  }
  Relation cardsPlayed(group).
}

data/adventures/tallow/lore.kyr:
Module tallow "Tallow Deep" {
  // ── Swallet afterwards, and the hill's word abroad ───────────────────────────────────────────────────────────────
  // The village was static: the same pot wiped on every visit. What the company does under the hill now shows in the
  // Chandler's Arms and on the green, and what the hill gives up is told elsewhere (befell: calx_opened, tallow_names).

  // What Treve found. The cat's collar goes to Nib; the man in the vault goes to Cador, who sent him up the walk.
  Relation vaultTold(group).
  Topic joss_vault with joss "Tell Cador what is hanging in the web-roofed vault" when been(party, spider_vault) and not vaultTold(party) once {
    Says "Cador takes his hat off, which is a thing he does for the dead and for the excise. 'In the silk,' he says. 'With his baldric on.' He turns the hat round by the brim. 'I sent three of them to the bend that night so I should not have to go up and look. Enys wanted to. I said we had a boy to think of.' He puts the hat on the table between you. 'Whatever you were going to charge me for the news, I'll pay it twice, and you'll not be stopped at my bend again.' He does not smile. 'Tell Nib yourself. He will take it better from someone who is not me.'".
    On discuss { Assert vaultTold(party). Assert tolerates(bend_watch, party). Increase quantity(actor, gold) by 12. }
  }
  Observe bend_quiet at adit when vaultTold(party) and not sold_out(party) "At the bend of the adit a lantern is hung where Treve's tin lamp used to hang, and nobody sits under it. The men who have the watch stand a little apart from the place.".

  // Swallet after the company has been about the hill: each thing it did leaves something on the green or in the taproom.
  Observe brandy_gone at taproom when sold_out(party) "On the shelf where the Tallymen's tithe-bottles stood, Lowen has propped a card in a careful hand: NOT TO BE ASKED FOR. She waters nothing. She simply serves less.".
  Observe lads_drinking at taproom when paid_by_joss(party) and not sold_out(party) "Two of Cador's lads are drinking in the Chandler's in the daytime, which they have never done, and Lowen serves them with her face turned to the pots. Nobody on the settle moves up for them.".
  Observe road_traffic at lane when state(calx_gate, raised) and not sold_out(party) "There is a cart-track in the lime-wash dust that was not on the lane yesterday, going out toward the west road with its tail to the hill. A doorstep coil of wet rope has been taken in.".
  Observe tokens_laid at taproom when laid(party) and not namesRead(party) "Barrick has taken the Company's tokens down from the beam, one at a time, and set them along the sill in a row, the way one sets plates for a table that is going to be sat at. He is not drinking.".
  Observe orpe_coat at counter when state(calx_gate, raised) "Mistress Orpe has put her good coat on over her apron and has not explained it. The drawer marked NOT BLACK is standing open, and she is writing something small on the back of a specimen label.".

  // A thing the village knew: the tick that Swallet does not speak of, going late as the hill is robbed (keeping.kyr).
  Topic hester_tick with hester "Ask Lowen when she last stopped hearing the pipe" when knows(actor, period_known) once {
    Says "Lowen takes a while to find a cloth that is not the one in her hand. 'The winter they hit the wall it went quiet for a night,' she says. 'Nine hours. My mother sat up in the kitchen with her knitting stopped. In the morning the river came out of the Rising brown, and she said: that is what it does when it has been woken.' She folds the cloth. 'I have the pot on the hob every night in case of it. I do not tell people that. It is a very little thing to keep.'".
  }

  // ── The wider world, as the hill hears it ───────────────────────────────────────────────────────────────────────
  Observe lore_orpe_sky at counter when befell(cloudgate_fell) "Mistress Orpe has taken the magnet off its string and is holding it up to the window, which she does not do in daylight. 'A drover says a slab came down out of a sky with nothing in it, into a bay, with a house on its back,' she says. 'If it is grey, and rings, I shall hear of it by Michaelmas. Nothing else has ever fallen that true.' She hangs the magnet back, and it swings, and settles, and points a little to the south of where it did.".
  Observe lore_cador_slack at tally_room when befell(slack_opened) "Cador has a new line in the ledger under the old tolls, and a name against it that is not a person's: A DOOR UNDER A COLLEGE, SOUTH. 'A man brings me brandy from the coast,' he says, 'and tells me a floor has been opened in a house in the south, and there is a stair under it going a long way down.' He taps the line. 'I have been selling this hill short, Enys says. Everyone has a stair now.'".

  // What the hill lets out. Read by Quittance's Arch (links.kyr there).
  Rule calx_word when state(calx_gate, raised) and not befell(calx_opened) { Assert befell(calx_opened). }
  Rule names_word when (namesRead(party) or ticked(party) or laid(party)) and not befell(tallow_names) { Assert befell(tallow_names). }
}

data/adventures/tallow/people.kyr:
Module tallow "Tallow Deep" {
  // ---------------------------------------------------------------------------------------------------------------
  // Swallet: the village that keeps its back to the hill.
  Person hester "Lowen Pook" at taproom {
    Role "landlady of the Chandler's Arms". Ancestry human. Profession innkeeper. Peaceable. Pronouns she. Manner acerbic.
    Greets "Lowen Pook wipes a pot that is already dry, as she has every evening since her brother Abner did not come home from the shift. 'You'll be going up the hill,' she says. 'They all do, sooner or later. There's the Rising, which is wet, and the portal, which is watched, and the Swallow, which is a rope. And there's the old road, which is nowhere.'".
  }
  Topic ask_rising with hester "Ask Lowen about the Rising" when true {
    Says "'It's the river coming out,' says Lowen. 'It runs low in a dry week, and you can wade it up to the first gallery with your boots round your neck. When it's rained on the downs it's a mill-race by the next dawn, and it stays one for a day. Don't be under that hill when it rains.'".
  }
  Topic ask_portal with hester "Ask Lowen about the Day-Level portal" when true {
    Says "'The Tallymen,' says Lowen. 'Smugglers. They've the Company's old workings for a cellar, and run salt and brandy under the hill. They don't hurt the village; they pay a tithe in brandy. They'll let you through for six coin. Don't call it a toll, they're particular.'".
  }
  Topic ask_swallow with hester "Ask Lowen about the Swallow" when true {
    Says "'Where the river goes in. You can climb down it with a rope and a stout heart. I wouldn't. There's a she-bear up in the scrub that has taken two of my neighbour's calves, and a she-bear is not a thing you want to meet with a rope on your back.' She says it again, with the stress on 'bear'. It is not a bear.".
  }
  Topic ask_trouble with hester "Ask Lowen about the water-trouble" when true {
    Says "'The Company holed into something, in the winter of 'fifty-two,' says Lowen, 'and the river came into the works, and fourteen men didn't come out. The Company packed up in a season. Nobody speaks of it. If you want to hear it you'll want Barrick Ibbot, and he won't tell it sober.'".
    On discuss { Assert knows(actor, breakthrough_known). }
  }
  Topic ask_road with hester "Ask Lowen about the old road" when true {
    Says "'Under the ridge, there's a road,' says Lowen. 'My gran said so. A road the soldiers made, to save climbing. The west end's under a hill of stones, and the east end is wherever the Company holed into it. They say the dead men are in it.'".
    On discuss { Assert knows(actor, calx_known). }
  }

  Person dunstan "Barrick Ibbot" at taproom {
    Role "an old miner". Ancestry human. Peaceable. Pronouns he. Manner grim.
    Greets "An old man by the fire holds his tankard in both hands, as if it might be taken. 'Going down,' he says, not asking.".
  }
  Topic dunstan_tale with dunstan "Ask Barrick what happened in 'fifty-two" when true {
    Says "'We were following the lead down the Blind Shaft,' says Barrick, 'and Foreman Carr had us set a fire against the north wall, to crack it and see where the vein turned, and the wall wasn't a wall. It was a cap. Under it, a hall, and in the hall, water, and in the middle of the water, a thing hanging. Carr said he'd sooner not look at it again. The river came in at the crack like a door opening. I went up the shaft. Fourteen didn't.' He drinks. 'Carr kept a book. He wrote a letter to the Company before the lamp went. He left it where a man would look, if he were the Company. The Company never came to look.'".
    On discuss { Assert knows(actor, breakthrough_known). Assert knows(actor, foreman_known). Assert knows(actor, cap_known). }
  }
  Topic dunstan_stope with dunstan "Ask Barrick about a way round the Tallymen" when knows(actor, breakthrough_known) {
    Says "'There's a stope from the bat chimney to the old stores,' says Barrick, 'that the Company cut for a drain. No one's looked at it since. You'll lose some skin. You'd come out behind the Tallymen's backs.'".
    On discuss { Assert knows(actor, stope_known). }
  }
  Topic dunstan_wheel with dunstan "Ask Barrick about the Calx Gate" when knows(actor, calx_known) {
    Says "'The old road,' he says. 'We broke into it by accident, down past the Breach, and it ran off west dead straight in the dark. There's a bronze gate across it, a few hundred paces on, with a wheel to raise it. Carr said the pawl was rusted solid. He wanted to oil it. He said the road went out west under the ridge's end and he could be out in an hour. That's what he said.'".
    On discuss { Assert knows(actor, gate_known). }
  }

  Person orpe "Mistress Orpe" at counter {
    Role "assayer to the Brasiers' Company, retired". Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Buys ironglass_dagger for 40 coin.
    Buys dowsing_rod for 20 coin.
    Buys bell_teeth for 30 coin.
    Buys ancient_orrery for 250 coin.
    Buys celestial_chart for 150 coin.
    Buys rose_quartz for 12 coin.
    Buys jeweled_box for 30 coin.
    Buys zoological_manual for 20 coin.
    Buys lensing_crystal for 30 coin.
    Buys antique_compass for 90 coin.
    Greets "Mistress Orpe is scoring a grey lump with a nail, and goes on scoring. 'If it is black, I'll buy it. If it is not black, I will tell you what it is, for a penny. If you have a brass instrument, I will buy that, and ask no questions, because they are the only things from down there that are worth anything.'".
  }
  Topic orpe_black with orpe "Ask Mistress Orpe what the black ore is" when true {
    Says "'Ironglass,' says Mistress Orpe. 'The Company was after lead, and the lead was sitting on a seam of this. It takes an edge like nothing else in the country and it will not smelt, so every ounce was broken out by hand, and the seam runs down toward the cap. The last fortnight they did nothing else. Carr kept the best of it back in a box in his office, and I would pay well for the box.'".
  }
  Topic orpe_cap with orpe "Ask Mistress Orpe about the Cap" when knows(actor, breakthrough_known) {
    Says "'A lid,' says Mistress Orpe. 'On something. The Aeneans made lids, they were fond of them. But Carr said it was not lead under that lid, and it was not water. The Company's secretary wrote to say the hall was to be sealed and nobody paid to look at it. I burned the letter. I have been sorry since.'".
  }
  Topic orpe_sample with orpe "Ask Mistress Orpe about the specimens on her counter" when true {
    Says "'Calcite, from the Swallow rim, which glows a little in the dark; Aenean brick from the Settling Cistern; and the grey one is nothing I can name. It is a kind of metal and a kind of glass, and I have a piece as long as a thumb that came up the shaft in a dead man's pocket. It rings like a bell. If you find more of it I will pay thirty a tooth, and tell you what I think it is for.'".
  }

  Person osk "Usk" at shop {
    Role "storekeeper". Ancestry dwarf. Peaceable. Pronouns he. Manner stoic.
    Sells rope for 1 coin from 8.
    Sells lamp_oil for 2 coin from 8.
    Sells torch for 1 coin from 12.
    Sells lantern for 4 coin from 3.
    Sells piton for 1 coin from 10.
    Sells crowbar for 3 coin from 3.
    Sells shovel for 3 coin from 3.
    Sells chalk for 1 coin from 10.
    Sells rations for 2 coin from 12.
    Sells bandages for 1 coin from 6.
    Sells signal_whistle for 2 coin from 3.
    Sells blanket for 2 coin from 6.
    Buys bell_teeth for 12 coin.
    Sells ratsbane for 3 coin from 4.
    Sells climbing_harness for 6 coin from 2.
    Buys guano_sack for 3 coin.
    Joins "Usk takes his hammer from its nail and puts it in his belt, and hangs a card on the door that says BACK AFTER. 'I have never been under that hill,' he says. 'My grandfather would not go.'".
    Leaves "Usk shoulders his bag. 'I'll see to the shop,' he says. 'You have your own road.'".
    Remarks at gear_hall "Usk stops on the last stair. He looks at the wheels, the teeth, the dark floor, and takes off his cap, which he has not done for a king. 'There,' he says, low. 'No joints. It was never put together.'".
    Remarks at cistern_hall "Usk lays a palm on a column. 'Aenean,' he says. 'Cut to a thumb.' He takes the hand away and rubs the thumb on the finger. 'Clean. Clean to the waterline. Water doesn't do that.'".
    Greets "Usk looks you over once, boots to hat, and begins taking things off the shelf. 'You want rope,' he says. 'Everyone wants rope. Buy oil with it.'".
  }
  Topic osk_gear with osk "Ask Usk what to take" when true {
    Says "'A light each. Oil for a day more than you think. Rope. A bar, for doors. Chalk, because the dark won't keep your steps. A whistle.' He considers the shelf. 'And a shovel. If you've heard of the old road, there's a hill of stones at the west end of it, and you'll want to come back up it. Shovel, not a sword.'".
  }

  // The Tallymen.
  Person nib "Nib" at adit_mouth {
    Role "a boy on watch". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "The boy on the barrel is nine or ten and has the face of someone who has been told to say nothing. 'I'm not looking,' he says. 'Anyone can go in if they pay six at the bend. I'm not supposed to say.'".
  }
  Topic wick_ask with nib "Ask Nib about the Tallymen" when true {
    Says "'There's Cador, who's the boss, and Enys and Treve and Sib at the bend, and the dog. They don't hurt anyone who pays. They hurt people who don't, because it wouldn't be fair. They're nice, mostly. They go down the Blind Shaft sometimes, with rope, for the black stone. Treve went up the Aenean stair after my cat, on a Tuesday three weeks gone, and didn't come down, and nobody's gone up since.'".
  }
  Topic wick_hobb with nib "Ask Nib what happened to Treve" when true {
    Says "'He went up the Aenean stair after Biscuit,' says Nib, 'on a Tuesday, three weeks gone, with the tin lamp, and the lamp didn't come back. Cador said not to ask. There's spiders up there, he says. Treve's afraid of spiders.' He corrects himself. 'Was.'".
  }

  Person bend_watch "the Tallymen on watch" at adit {
    Role "three of the Tallymen, at the bend". Ancestry human. Calling thief. Level 2. Numbers 3. Temperament territorial.
    Warns "Three men with a lantern step out of the dark at the bend of the adit, unhurried. 'Six coin,' says the tall one, 'for the lot of you, and the lantern's lent. Or back out the way you came. Those are the two choices, and I'd sooner you took the first.'".
    Comes "The three step in together, without a word.".
    Pleads "The tall one puts his hands up. 'Six is cheap,' he says, 'and you've made it dear.'".
    Lair adit. Refuge drift.
  }

  Person joss "Cador Tarbet" at tally_room {
    Role "master of the Tallymen". Ancestry human. Calling thief. Level 3. Peaceable. Pronouns he. Manner jovial.
    Sells rope for 2 coin from 6.
    Sells lamp_oil for 3 coin from 6.
    Sells ratsbane for 4 coin from 6.
    Sells rations for 3 coin from 6.
    Sells waterskin for 2 coin from 4.
    Buys steel_coin for 3 coin.
    Buys bell_teeth for 10 coin.
    Greets "A broad man in a good coat gets up from the ledger without hurry. 'Cador Tarbet,' he says. 'I keep the accounts of the Day-Level. You'll have paid? Of course you have. Sit down. I buy, if you have anything worth the walk, and I sell, at a profit, because the alternative is Swallet's prices. What brings you down?'".
  }
  Topic joss_hill with joss "Ask Cador about the hill" when true {
    Says "'It's a pie with a lot of crusts,' says Cador. 'The Company's works we use. Below the Blind Shaft there is a hall full of water that I have no use for, because it is full of water. Past the hall there's a stair that goes down further than I care to count, and what's at the bottom does not trouble anyone, because no one has been to the bottom and come up again. I have lost one man to the Aeneans' ledge, and I do not propose to lose another.'".
  }
  Topic joss_road with joss "Ask Cador about the old road" when knows(actor, calx_known) {
    Says "Cador does not smile. 'I'd give a great deal for that road,' he says. 'Two miles from the Swallet green to a place the excise never goes. Everyone who has looked for it has found the east end, which is a charnel house, and the gate, which is rusted shut. If you open it, I would very much like to hear.' He pauses. 'And I would very much like you not to tell the village.'".
    On discuss { Assert knows(actor, gate_known). }
  }
  Topic joss_spiders with joss "Ask Cador about the spiders" when true {
    Says "'The boy's cat went up the service walk three weeks ago, and Treve after her, and the spiders had them both. They have bodies like hounds, and they sit above you. They do not like smoke. If you can spare a torch and carry it up, you can burn a way through. Or you can go round by the Settling Cistern, but it is rats.'".
  }
  Topic joss_hobb with joss "Ask Cador about Treve" when true {
    Says "'Treve was soft,' says Cador. 'The boy's cat went up the service walk on a Tuesday, three weeks gone, and Treve took a lamp and went after her, along a ledge two paces wide above the Settling Cistern. I went as far as the stair and saw the silk. Think about that, if you were thinking of the walk.'".
  }
  Topic joss_buy with joss "Ask Cador what he pays for" when true {
    Says "'Steel coin, which is Aenean, and the old toll-silver in the chest there, which isn't for sale. Bell-teeth, which the barge-men want. The little brass instruments the assayer likes, I don't touch; she gets them. Black stone I buy by weight, but I'll want to see it first, and I'll want to know where you had it.'".
  }

  Person dog "the Tallymen's dog" at tally_room {
    Role "a grey lurcher with a notched ear". Species dog. Peaceable.
  }

  Thing strongbox "the brass-bound chest" at tally_room {
    State chained closed "A brass-bound chest is chained to the wall by the stove. A padlock as big as a fist holds the chain.".
    State open "The chest stands open. The chain hangs loose, and the padlock lies beside it.".
    Change pick_chest "Pick the chest's padlock" from chained to open needing lockwork.
    Change force_chest "Force the chain with a bar" from chained to open needing crowbar.
    Holds.
  }
  Item toll_sack "a season of the Toll" is toll_silver in strongbox owned by joss.
  Item joss_coin "a dull steel coin" is steel_coin in strongbox owned by joss.
  Topic osk_stone with osk "Ask Usk what he makes of the stone on the hill" when true {
    Says "'Company work is dwarf-cut. You can see it,' says Usk. 'Under that, Aenean. Cut to a thumb, and they thought it a boast.' He lifts a shoulder. 'Under that, something I was told as a boy not to name. My grandfather's master walked into a hall like it and never cut again. No joints. You can't find where it was made. Only where it was stopped.'".
  }
  Topic hester_amos with hester "Ask Lowen about her brother" when true once {
    Says "'Abner,' says Lowen, and sets the pot down. 'The fourth shift down, the winter of 'fifty-two. They said the water took the whole of it. Nobody has ever said whose names.' She picks the pot up again. 'I was nine. I have kept the inn so the door would be open when someone came to say.'".
  }
}

data/adventures/tallow/placed.kyr:
Module tallow "Tallow Deep" {
  // The country beyond a march of a generated world: the company that comes in by the road is the world's own.
  Entity party: group "Your company".
  // What is said of Tallow Edge in the country behind it: once the Calx Gate is raised, or the fourteen are counted, it is old news.
  Entity word: fact "What is said of Tallow Edge in the country behind it.".
  Rule word_old when (state(calx_gate, raised) or namesRead(party) or ticked(party) or laid(party)) and not stale(word) { Assert stale(word). }
  // And which: the old road open under the ridge, which the village hears of at once.
  Entity word_road: fact "That the old road under Tallow Edge is open.".
  Rule word_road_old when state(calx_gate, raised) and not stale(word_road) { Assert stale(word_road). }
}

data/adventures/tallow/quests.kyr:
Module tallow "Tallow Deep" {
  // ── Companions, asides and questions ───────────────────────────────────────────────────────────────────────────
  // Two who will come down with the company (Sib Wray, an informer in a smuggler's hammock; Usk, a mason with a
  // grandfather's silence), three errands that do not touch the Bore (a cat, a drowned man's letter, a cook's book),
  // and the questions people put to whoever is asking questions of them.
  Relation sibNoLocks(group). Relation sibOpens(group). Relation sibAsks(group). Relation sibInformer(group).
  Relation sibExposed(group). Relation sibKept(group). Relation sibBurned(group). Relation sibSold(group).
  Relation oskPromised(group). Relation oskCut(group). Relation oskHolds(group).
  Relation motiveCoin(group). Relation motiveDead(group). Relation motiveCurious(group).
  Relation nibTold(group). Relation nibLied(group). Relation cookKnown(group). Relation oreNamed(group). Relation sibGone(group).

  // Lowen asks the one question: why go up.
  Topic hester_why with hester "Say why you are going up the hill" when true once {
    Says "Lowen Pook looks at you across the bar for a time. 'Everyone says they are going up for something,' she says. 'Coin, mostly. I should like to know what you are going up for. It is the only thing I am any good at, telling which of them will come down.'".
  }
  Topic why_coin with hester "For what it will fetch" answering hester_why when true {
    Says "'Honest,' says Lowen, and nods, 'and the commonest. Then you want Cador Tarbet, who buys at the bottom, and Mistress Orpe, who buys the things he can't. Don't look at me like that. Coin is a reason.'".
    On discuss { Assert motiveCoin(actor). }
  }
  Topic why_dead with hester "For the men who did not come out" answering hester_why when true {
    Says "Lowen's hands stop on the pot. 'Then you want Barrick, by the fire,' she says. 'He will not tell you sober. I will pour him a second, and you may owe me for it.' She does not say her brother's name. She pours.".
    On discuss { Assert motiveDead(actor). Assert knows(actor, foreman_known). }
  }
  Topic why_look with hester "To see what is there" answering hester_why when true {
    Says "'Ah,' says Lowen, less kindly. 'One of those.' She turns the pot. 'Mistress Orpe is one too. Go and be looked at by her; she has been waiting forty years for somebody to ask the right question about a piece of grey metal.'".
    On discuss { Assert motiveCurious(actor). }
  }

  // Orpe tests the asker.
  Action name_ore(actor: group, site: place) "Take the black lump from Mistress Orpe's counter and say what it is" {
    Speaker orpe.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, counter) and at(orpe, counter) and not oreNamed(actor).
    Time 1.
    Resolve check(actor, lore, dc_fair).
    On success { Assert oreNamed(actor). Increase quantity(actor, gold) by 6. }
    On failure { Assert oreNamed(actor). }
    Result "'Ironglass,' you say, and Mistress Orpe puts down her nail for the first time. 'By what?' By the fracture, you tell her, and the way it takes the light. 'Six coin,' she says, 'for the first person in forty years who didn't say lead.'".
    Otherwise "'Lead,' you say. 'Lead,' agrees Mistress Orpe, wearily, and takes it back, and puts it in the drawer marked NOT BLACK.".
  }

  // Sib Wray: a Tallywoman with a letter she did not ask to receive.
  Person sib "Sib Wray" at tally_room {
    Role "one of the Tallymen, off the bend". Ancestry human. Calling thief. Level 2. Peaceable. Pronouns she. Manner acerbic. Seen when not sibGone(party).
    Greets "A woman about thirty, on the hammock nearest the stove, with a rope-burned neck and the quick plain eyes of someone who counts the exits when she sits down. She does not get up. 'I'm Sib,' she says. 'Not the toll. I only take that when Enys is sick.'".
    Joins "Sib swings her feet down, ties her bundle shut in two knots, and keeps her back to Cador Tarbet, who is looking at the chest. 'I'll show you the bits that aren't on any of Nib's maps,' she says. 'For my price, and because I am tired of this room.'".
    Leaves "Sib lifts her bundle and her chin. 'I'll find my own road,' she says. 'I always have.'".
    Remarks at settling "Sib stops at the edge of the silt-bank and does not go further. 'I know that coat,' she says, to nobody. Then she looks at the ceiling, hard, as if it had said something.".
    Remarks at gate_house "Sib puts a hand flat on the Calx wheel and keeps it there. 'It goes out two miles west,' she says. 'And comes up behind the Porthwen customs-barn. I know exactly where, because I have drawn it twice.' She takes the hand off. 'Forget I said that.'".
  }
  Topic sib_talk with sib "Ask Sib what a woman does on the bend of a smugglers' adit" when true once {
    Says "'Counts,' says Sib. 'Barrels, coin, who looks tired.' She turns a coin over her knuckles. 'Let me ask you, since you ask. You find a lock on a thing that isn't yours. A box, a door, a man's mouth. What do you do?'".
  }
  Topic sib_leave with sib "Leave it. It's locked for a reason" answering sib_talk when true {
    Says "'A saint,' says Sib, without scorn. 'You'll starve. But I'd rather go down with someone who knows what's theirs.' She sets her price at eight coin and looks glad of it.".
    On discuss { Assert sibNoLocks(actor). Assert willing(sib, actor). Set hire(sib) to 8. }
  }
  Topic sib_open with sib "Open it. A lock is an opinion" answering sib_talk when true {
    Says "'There she is,' says Sib, and grins like a cut. 'Four coin, and I'll want to see the thing you open.'".
    On discuss { Assert sibOpens(actor). Assert willing(sib, actor). Set hire(sib) to 4. }
  }
  Topic sib_ask_whose with sib "Ask whose it is, and why they locked it" answering sib_talk when true {
    Says "Sib is silent a moment. 'That's the answer of someone who has been lied to by a lock,' she says. 'Six. And you'll tell me, if I ask, why you wanted to know.'".
    On discuss { Assert sibAsks(actor). Assert willing(sib, actor). Set hire(sib) to 6. }
  }

  // The drowned man in the Settling Cistern, and his letter.
  Observe drowned_man at settling when not sibExposed(party) "A pair of good boots stands out of the silt-bank at the weir's foot, toes up, with a Customs button on the left.".
  Kind excise_letter "a letter on the Board's paper" is document teaching sib_informer_known described "A single sheet, water-wrinkled but legible, in a Customs clerk's round hand.".
  Discovery sib_informer_known "The Board of Excise at Porthwen writes to 'Sibyl Wray, at the Day-Level': the sum is approved; the landing at Porthwen shall be watched on the night of the next quarter-day; the bearer of this letter is to be given a writ of passage south. Sib Wray has been selling the Tallymen to the Customs for two years.".
  Item excise_item "a letter on the Board's paper" is excise_letter at settling hidden until drowned_man_found.
  Discovery drowned_man_found "The drowned man in the silt-bank carries a letter.".
  Observe drowned_taught at settling when true "Under the silt the man's coat holds a letter in an oilcloth." teaches drowned_man_found.
  Topic sib_letter with sib "Show Sib the letter from the drowned man" when holding(actor, excise_letter) and knows(actor, sib_informer_known) and not sibExposed(party) and not sibKept(party) and not sibBurned(party) once {
    Says "Sib reads it as if it were in a tongue she had once had. 'He was meant to meet me at the weir,' she says. 'He was twenty-two. He said he'd bring a writ.' She gives it back with a steady hand. 'Well. You know now. What will you do with it?'".
  }
  Topic sib_burn with sib "Burn it where she can see" answering sib_letter when holding(actor, excise_letter) {
    Says "You hold a corner of it to a flame. Sib watches the Board's seal run. 'That was a good seal,' she says, and sits on the nearest barrel with her back to the room.".
    On discuss { Spend excise_letter from actor. Assert sibBurned(party). Assert sibKept(party). Assert sibInformer(party). }
  }
  Topic sib_joss with sib "Give it to Cador Tarbet" answering sib_letter when holding(actor, excise_letter) and at(joss, tally_room) and at(sib, tally_room) {
    Says "'Of course,' says Sib, evenly. She takes up her bundle. At the arch she turns, once: 'He was kind to me,' she says. 'I don't say that to move you.' She is gone before Cador has finished the first line.".
    On discuss { Assert sibExposed(party). Assert sibSold(party). Assert sibInformer(party). Retract travelsWith(sib, actor). Retract at(sib, tally_room). Assert sibGone(party). }
  }
  Topic sib_board with sib "Take it to the Board yourself, for the reward" answering sib_letter when holding(actor, excise_letter) {
    Says "'Give it here,' says Sib. 'I'll carry it to Porthwen on the quarter-day myself, and take the writ south, and Cador will have a clean road for one more year and a wrong one after.' She counts eight coin into your hand. 'For the lock you didn't open.' She has her bundle on her shoulder before you have closed your hand on it.".
    On discuss { Spend excise_letter from actor. Assert sibInformer(party). Assert sibKept(party). Increase quantity(actor, gold) by 8. Retract travelsWith(sib, actor). Assert sibGone(party). }
  }
  // Gone is gone, from wherever she was: the Tally-Room, the weir, the Gear-Hall.
  Rule sib_goes when sibGone(party) and at(sib, ?p) { Retract at(sib, ?p). }
  Rule sib_flees when sold_out(party) and at(sib, tally_room) and not travelsWith(sib, party) { Assert sibGone(party). }
  Observe sib_joss_fallout at tally_room when sibSold(party) "Cador Tarbet sits with a page on his knee, not reading it. There is a hammock cut down by the stove and no one is talking.".
  Observe sib_burned_fallout near sib when sibBurned(party) "Sib has stopped counting the exits. She sits with her back to the wall and her face to the room, which is a thing she has not done before.".

  // Usk, who will come if he is promised something.
  Topic osk_offer with osk "Ask Usk to come and look at the Cap" when knows(actor, cap_known) and not oskPromised(actor) once {
    Says "Usk sets down the trowel he is not using. 'The Cap,' he says. 'Aenean?' You say it is, and something under it is not. He looks at the shelf above the counter for some time. 'If it is the sort of thing that should not be touched,' he says, 'will you leave it?'".
  }
  Topic osk_leave with osk "Yes. If it asks to be left alone" answering osk_offer when true {
    Says "'Then I'll come,' says Usk. 'For nothing. I should like to see a joint nobody has pointed.'".
    On discuss { Assert oskPromised(actor). Assert willing(osk, actor). Set hire(osk) to 0. }
  }
  Topic osk_known with osk "No. It should be known, whatever it is" answering osk_offer when true {
    Says "'That is what my grandfather's master said,' says Usk, dryly. 'He cut one sample.' He picks up his hammer. 'Four coin, and I decide what is cut.'".
    On discuss { Assert oskCut(actor). Assert willing(osk, actor). Set hire(osk) to 4. }
  }
  Topic osk_unsure with osk "I don't know yet. I'd like to see it first" answering osk_offer when true {
    Says "'That I'll take,' says Usk. 'It is the only answer I'd trust.' He shoulders his bag. 'Come on then.'".
    On discuss { Assert oskHolds(actor). Assert willing(osk, actor). Set hire(osk) to 0. }
  }

  // Usk in the Gear-Hall: the makers' stone, and whether to take any.
  Action osk_cut(actor: group, site: place) "Let Usk cut one sample from the grey wall" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gear_hall) and travelsWith(osk, actor) and not oskCutDone(actor) and not oskPromised(actor).
    Time 0.
    On success { Assert oskCutDone(actor). Give bell_teeth_sample to actor. }
    Result "Usk sets a chisel to the wall, once, and strikes it once. A crescent of grey comes away that rings like a struck cup. The wire above you misses a beat and takes it up again late. Usk looks at the chisel, then at his hand, and puts the chisel away.".
  }
  Action osk_forbear(actor: group, site: place) "Ask Usk to leave the wall alone" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gear_hall) and travelsWith(osk, actor) and not oskCutDone(actor) and not oskLeft(actor).
    Time 0.
    On success { Assert oskLeft(actor). }
    Result "Usk puts the chisel back in his belt without a word. Then, 'Thank you,' he says. 'I did not want to be asked. I did not want not to be.'".
  }
  Relation oskCutDone(group). Relation oskLeft(group). Relation oskGone(group).
  Kind bell_teeth_sample "a crescent of the makers' grey" is treasure worth 40 weighing 1 described "A crescent the length of a thumb, grey, ringing. It is too light and has no grain.".
  Observe osk_names near osk when namesRead(party) and travelsWith(osk, party) "Usk has taken a chisel to a flat stone by the green and is cutting fourteen names into it, one a line, in the plain square letters his grandfather's master used. He keeps cutting. 'The Company never had the sense,' he says.".

  // Nib's cat.
  Topic nib_cat with nib "Ask Nib why he watches the portal so hard" when true once {
    Says "Nib looks at his boots. 'Biscuit went in,' he says. 'Three weeks, on a Tuesday. She does, she likes the bats. Treve went up the stair after her.' He looks up. 'If you see her, you tell her I said come home. Don't tell Cador I asked.'".
  }
  Topic nib_collar with nib "Give Nib the cat's collar" when holding(actor, bell) and not nibTold(actor) once {
    Says "He takes it. The bell is stopped with a bit of web. He picks the web out with a fingernail, careful, and it gives a small dull note. 'Was it quick?' he says, not looking at you.".
  }
  Topic nib_truth with nib "No. It was not quick" answering nib_collar when true {
    Says "He nods, for a long while. 'I knew,' he says. 'Thank you for not saying.' He gives you his father's whistle without being asked, and goes in to the barrel and sits on it with the collar in his fist.".
    On discuss { Spend bell from actor. Assert nibTold(actor). Give signal_whistle to actor. }
  }
  Topic nib_lie with nib "Yes. She did not know" answering nib_collar when true {
    Says "'Good,' says Nib, in a small voice. 'That's good.' He puts the collar on the barrel beside him and turns it so the bell faces the wall.".
    On discuss { Spend bell from actor. Assert nibTold(actor). Assert nibLied(actor). }
  }

  // Elspeth Noakes, who cooked for them.
  Thing cook_stone "the flat stone under the foxglove" at garden is scenery {
    State lying "Under the foxglove a flat stone lies, cut with a spoon and a pot: ELSPETH NOAKES. SHE FED THEM. Something has been laid in the hollow of the pot: a clean white pebble, and another, and another.".
  }
  Initially Assert grows(cook_stone).
  Kind cook_book "Elspeth Noakes's receipt book" is document teaching cook_known_fact described "A fat book of receipts, greasy, tied with a bootlace, kept by the Company's cook. In the margins she has written who ate what.".
  Discovery cook_known_fact "The Company's cook wrote in the margin of every dinner who had taken seconds and who had not. Against the Foreman: Mr Carr does not eat when he is afraid. Against the night of the breaking-in: fifteen plates laid. Fourteen cold.".
  Item cook_book_item "Elspeth Noakes's receipt book" is cook_book at bothy hidden until cook_stone_seen.
  Place bothy "the Brasiers' bothy" is room within foot at 0, 1 outdoors.
  Passage bothy_door "the bothy door" is door between garden and bothy.
  Observe bothy_scene at bothy when true "The cook's bothy has kept a roof. A hearth with a pot-crane, a bench with a place worn at one end, a dresser of plates stacked for a table that was never laid again. The air smells of old fat and bay.".
  Discovery cook_stone_seen "Under the foxglove, a cook's stone; behind it, her bothy.".
  Observe cook_taught at garden when state(cook_stone, lying) "Under the foxglove a flat stone is cut with a spoon and a pot." teaches cook_stone_seen.
  Topic hester_cook with hester "Ask Lowen about Elspeth Noakes" when knows(actor, cook_stone_seen) once {
    Says "'My mother's sister,' says Lowen, and for a moment she is not an innkeeper. 'She laid the fifteen plates, and went home when the wall went, and never came back to wash them. She was the only person in Swallet who didn't take it as a judgement.' She breathes out. 'Is her book still there? She wrote in it who ate what. She used to say you can tell everything about a man by whether he takes seconds.'".
  }

  // The answers given are heard again.
  Topic dunstan_open with dunstan "Tell Barrick you came for the men who did not come out" when motiveDead(party) and not knows(party, vault_laid) once {
    Says "He puts his tankard down for the first time. 'Then I'll tell you what I told no one,' he says. 'Carr stacked them. All thirteen, one at a time, to the Breach, because it was the only dry place. I held the lamp. When the last was down he said, I'll oil the pawl, and I said, I'll fetch more oil, and went up the shaft instead, with my eyes on the rungs.' He folds his hands. 'It was me that left the Foreman. I would like that read somewhere.'".
    On discuss { Assert knows(actor, vault_laid). Give lamp to actor. }
  }
  Entity vault_laid: fact "Carr stacked the thirteen in the vault by the Breach himself, one at a time, while Barrick held the lamp; then Barrick went up the shaft and left him there.".
  Topic joss_coin with joss "Tell Cador you came for what it fetches" when motiveCoin(party) once {
    Says "Cador smiles, the first honest smile of the evening. 'Then we understand each other,' he says, and tosses you a flask of oil from under the table. 'On account. You'll bring me things. I won't ask where from, and I won't pay you for the ones that have a Customs button on them.'".
    On discuss { Give lamp_oil to actor. }
  }
  Topic orpe_curious with orpe "Tell Mistress Orpe you came to see what is there" when motiveCurious(party) once {
    Says "'Then you will want this,' says Mistress Orpe, and goes to the drawer marked NOT BLACK, and unlocks it with her back to you. She takes out a map on hide, much folded. 'The Company's survey of the Conduit. The Aeneans' numbers are on it, 800 down to nothing. They count down to the Swallow, not up. Nobody could ever say what to.'".
    On discuss { Give faded_map to actor. }
  }
  Topic nib_stope_free with nib "Ask Nib again about the hole in the chimney" when nibTold(party) and not nibLied(party) and not knows(party, stope_known) once {
    Says "'You didn't lie to me,' says Nib. 'So.' He lowers his voice to the barrel. 'The bat chimney. It goes down on the left, all knees. You come out behind Enys's back. Never said.'".
    On discuss { Assert knows(actor, stope_known). }
  }
  Observe nib_lied_note near nib when nibLied(party) "Nib has tied the cat's bell to his belt, where it hangs unrung. He looks past you when you come near, as if you might say the thing you did not.".
  Observe sib_lock_a near sib when sibNoLocks(party) and travelsWith(sib, party) "Sib walks a little behind you and touches nothing she is not given.".
  Observe sib_lock_b near sib when sibOpens(party) and travelsWith(sib, party) "Sib goes ahead and tries every latch on the way, lightly, with two fingers, and shuts them again.".
  Observe sib_lock_c near sib when sibAsks(party) and travelsWith(sib, party) "Sib walks beside you and now and then looks at you sideways, as if you had a question she meant to hear.".
  Observe osk_left near osk when oskLeft(party) "Usk has cut a card for the shop door in square letters: NOTHING TAKEN THAT CANNOT BE GIVEN BACK.".
  Observe osk_cut_note near osk when oskCutDone(party) "Usk keeps the crescent of grey in his coat and does not take it out. He has stopped asking about the hill.".
  Observe shelf_back at dial_room when shelfRestored(party) > 0 "On the shelf of grey metal, in the dust, are the clean places where things used to stand and one place where something has stood again.".
  Observe osk_hold_note near osk when oskHolds(party) and travelsWith(osk, party) "Usk walks with his hands behind him, looking at everything and touching nothing, a man waiting to be told what he saw.".
  Observe osk_cutter near osk when oskCut(party) and travelsWith(osk, party) "Usk's chisel hangs loose on his belt, where it can be reached.".
  Milestone m_sib "learned what Sib Wray was, and chose" worth 200 when sibInformer(party).
  Milestone m_cook "read what the cook wrote in the margin" worth 120 when knows(party, cook_known_fact).

  Topic hester_book with hester "Show Lowen the cook's receipt book" when holding(actor, cook_book) and not cookKnown(party) once {
    Says "Lowen turns the pages with her thumb and stops at a margin. She reads it twice. Against her brother Abner: takes seconds, always, says it is for his sister. 'He did,' she says, and puts the book to her chest like a child. 'He did, he did.' When she can speak she gives you six coin from the till and will not hear a word about it. 'I'll pin the page,' she says. 'Beside the names.'".
    On discuss { Spend cook_book from actor. Assert cookKnown(party). Increase quantity(actor, gold) by 6. }
  }
  Topic hester_supper with hester "Ask Lowen whether a cook's page buys a supper for the road" when cookKnown(party) once {
    Says "'It buys the cook's supper,' says Lowen, and goes through to the back, and comes out with two rations wrapped in a cloth. 'Her receipts were for the road, mostly. She said a company marches on its seconds.' She puts them in your hands. 'Do not tell me they are too many.'".
    On discuss { Increase quantity(actor, rations) by 2. }
  }
  Observe cook_pinned at taproom when cookKnown(party) "Under the ledger's page on the beam is a second page, in a cook's hand: who took seconds, and who did not.".
  // Usk goes home when the matter is settled, or he has done what he came to do.
  Rule osk_home at green when travelsWith(osk, party) and at(party, green) and (namesRead(party) or oskCutDone(party) or oskLeft(party)) and not oskGone(party)
    says "Usk stops at his own door. 'That is enough hill,' he says. 'I will cut what I must cut here.' He goes in and the card on the door turns round." {
    Assert oskGone(party). Retract travelsWith(osk, party). Assert at(osk, shop). }
}

data/adventures/tallow/wake.kyr:
Module tallow "Tallow Deep" {
  // ---------------------------------------------------------------------------------------------------------------
  // What the village wants, what the Tallymen want, and what the hill remembers.
  Relation sold_out(group). Relation paid_by_joss(group).
  Topic joss_report with joss "Tell Cador the old road is open" when state(calx_gate, raised) and not sold_out(party) and not paid_by_joss(party) once {
    Says "Cador sits very still for a moment. Then he laughs, once. 'Two miles,' he says. 'Two miles of paved road under the excise's feet.' He counts sixty coin out of the ledger-box. 'You never saw me do it. And my lads will be on the bend for your coming and going, free, so long as you are mine.'".
    On discuss { Increase quantity(actor, gold) by 60. Assert paid_by_joss(party). Assert tolerates(bend_watch, party). }
  }
  Topic hester_report with hester "Tell Lowen the old road is open" when state(calx_gate, raised) and not ticked(party) and not paid_by_joss(party) and not sold_out(party) once {
    Says "Lowen Pook sets the pot down. 'The Tallymen's cellar,' she says, 'and that road. Well.' She is quiet. 'The parish will be wanting a word with Cador Tarbet. I'll see he has a night to pack.' She gives you twenty coin out of the till. 'That's the parish's thanks. It isn't much. It's all there is.'".
    On discuss { Increase quantity(actor, gold) by 20. Assert sold_out(party). Retract at(bend_watch, adit). Retract at(joss, tally_room). Retract at(dog, tally_room). }
  }
  Observe market_gone at tally_room when sold_out(party) "The Tally-Room is empty: hammocks cut down, the stove cold, the ledger gone, and a chalk line across the table where somebody counted for the last time.".
  Observe watch_gone at adit when sold_out(party) "The bend of the adit is empty. The lantern has gone from its hook.".


  Objective ask_swallet when not knows(party, breakthrough_known) "Swallet keeps its back to the hill. The assayer, the landlady and an old miner by the fire all know something of why.".
  Objective find_foreman when knows(party, foreman_known) and not knows(party, letter_read) "Foreman Carr led the Breakthrough and left a letter in his office in the hall under the Blind Shaft. Someone should read it.".
  Objective open_road when knows(party, calx_known) and not state(calx_gate, raised) "There is said to be an old road under the ridge, with a rusted gate and a wheel.".
  Objective reach_bore when knows(party, bore_known) and not been(party, dial_room) "The Cap in the Cistern Hall covers a shaft, and the Tally-Wall says a weight still swings in it.".

  Milestone m_foreman "found Foreman Carr's papers" worth 120 when knows(party, letter_read).
  Milestone m_cistern "stood on the shore of the Cistern Hall" worth 100 when been(party, cistern_hall).
  Milestone m_calx "opened the Calx Gate" worth 250 when state(calx_gate, raised).
  Milestone m_through "walked the Calx Way to the daylight" worth 200 when been(party, calx_inner) and been(party, calx_portal) and state(portal_inside, cleared).
  Milestone m_gear "stood in the Gear-Hall, and was not stopped" worth 250 when been(party, gear_hall) and tolerates(custodians, party).
  Milestone m_dial "stood in the Dial" worth 400 when been(party, dial_room).
  Milestone m_dead "laid the Company's dead" worth 150 when laid(party).
  Milestone m_slump "fed what lives in the Cistern Hall" worth 100 when tolerates(slump, party).
  Milestone m_bore "learned what hangs in the Bore" worth 150 when knows(party, bore_known).
}

data/adventures/tallow/works.kyr:
Module tallow "Tallow Deep" {
  // ---------------------------------------------------------------------------------------------------------------
  // What can be known.
  Discovery breakthrough_known "In the winter of 'fifty-two the Brasiers' Company broke into the Aenean cap from the Blind Shaft's north wall; the river came in and fourteen men died in the Breach.".
  Discovery foreman_known "Foreman Carr, who led the Breakthrough, left a letter and a ledger in his office on the north walk, in the hall under the Blind Shaft.".
  Discovery calx_known "A paved Aenean road runs under the ridge, from the Breach to a portal buried two miles west of Swallet.".
  Discovery stope_known "A miners' stope joins the bat chimney to the old stores, behind the Tallymen's watch at the bend.".
  Discovery gate_known "The Calx Gate is a bronze portcullis raised by a wheel; its pawl is rusted solid and wants oil, and then the wheel will turn.".
  Discovery cap_known "The Cap is an Aenean lid, set over the head of a shaft older than the Cistern, and a stair goes down under it.".
  Discovery period_known "The Aeneans measured the Bore's weight at one swing in six breaths, and they cut the figure into the Tally-Wall: VI.".
  Discovery bore_known "The Bore is a plumb-line well: a weight hangs in it, and has been swinging since before the Aeneans came. They capped it, and wrote on the Cap THE WEIGHT STILL SWINGS.".

  // ---------------------------------------------------------------------------------------------------------------
  // The Wend, and the days it rises.
  Thing wend "the Wend" at rising_gallery is scenery {
    State low "The Wend runs knee-deep and clear through the gallery, loud on its stones.".
    State spate "The Wend is in spate: a brown, roaring mass of water that fills the gallery from wall to wall.".
  }
  Initially Assert state(wend, low).
  Measure spateUntil(entity).
  Relation surged(group).
  Rule rain_on_downs when untilLight(clock) == 1 and state(wend, low) and dice(clock) <= 20 {
    Assert state(wend, spate). Set spateUntil(wend) to watch(clock) + 144.
  }
  // Every grey thing taken off the Dial's shelf and not set back is another chance in ten at each first light.
  Rule rain_orrery when untilLight(clock) == 1 and state(wend, low) and orreryOut() and dice(clock) > 20 and dice(clock) <= 30 { Assert state(wend, spate). Set spateUntil(wend) to watch(clock) + 144. }
  Rule rain_chart when untilLight(clock) == 1 and state(wend, low) and chartOut() and dice(clock) > 30 and dice(clock) <= 40 { Assert state(wend, spate). Set spateUntil(wend) to watch(clock) + 144. }
  Rule rain_crystal when untilLight(clock) == 1 and state(wend, low) and crystalOut() and dice(clock) > 40 and dice(clock) <= 50 { Assert state(wend, spate). Set spateUntil(wend) to watch(clock) + 144. }
  Rule rain_compass when untilLight(clock) == 1 and state(wend, low) and compassOut() and dice(clock) > 50 and dice(clock) <= 60 { Assert state(wend, spate). Set spateUntil(wend) to watch(clock) + 144. }
  Rule spate_goes when state(wend, spate) and watch(clock) >= spateUntil(wend) { Assert state(wend, low). Retract surged(party). }
  Thing ford_spate "the Wend at the bank" on wend_ford is scenery {
    State easy "The Wend is a shallow gravel run, bright and quick.".
    State flooding blocking "The Wend is brown and loud over the gravel bank, a mill-race coming out of the hill. Nobody wades it.".
  }
  Initially Assert state(ford_spate, easy).
  Rule ford_floods when state(wend, spate) and state(ford_spate, easy) { Assert state(ford_spate, flooding). }
  Rule ford_clears when state(wend, low) and state(ford_spate, flooding) { Assert state(ford_spate, easy). }
  Thing gallery_spate "the Wend in the gallery" on gallery_settling is scenery {
    State easy "The Wend runs in its channel, knee-deep.".
    State flooding blocking "The channel is a brown torrent from wall to wall, and the roof drips with its spray.".
  }
  Initially Assert state(gallery_spate, easy).
  Rule gallery_floods when state(wend, spate) and state(gallery_spate, easy) { Assert state(gallery_spate, flooding). }
  Rule gallery_clears when state(wend, low) and state(gallery_spate, flooding) { Assert state(gallery_spate, easy). }
  Hazard surge_wave "The Wend in spate" means "Deal (2d6) physical damage to ally unless strength save against (13).".
  Rule surge_catches at rising_gallery when state(wend, spate) and at(party, rising_gallery) and not surged(party) and watch(clock) >= spateUntil(wend) - 132
    says "A noise like a cart on a bridge comes up the gallery, and the roof drips, and then the water is not knee-deep any more." {
    Assert strikes(surge_wave, party). Assert surged(party).
  }
  Observe spate_news at green when state(wend, spate) "The pipe over the trough runs brown and thick. It rained on the downs in the night, and the Rising will be loud.".
  Observe spate_news_bank at bank when state(wend, spate) "The Wend comes out of the Rising in a brown standing wave. The bats are not flying.".
  Observe rising_sound at rising_gallery as sound when state(wend, spate) "Somewhere upstream there is a long, even roar that was not there a minute ago.".

  // ---------------------------------------------------------------------------------------------------------------
  // The toll at the bend: a day's loan of the lantern, and the price of a hill is that you pay it again. The Tallymen bar
  // the way in from the mouth of the adit, and nobody who is already inside is kept from leaving by them.
  Measure tollPaidAt(entity). Relation lapsed(group).
  Thing bend_bar "the Tallymen at the bend" on adit_drift from adit {
    State up blocking "The three Tallymen stand across the adit at the bend, one with the lantern, and nobody goes past them without paying.".
    State down "The bend of the adit is open.".
  }
  Initially Assert state(bend_bar, up).
  Rule bend_lifts when state(bend_bar, up) and (tolerates(bend_watch, party) or not able(bend_watch) or not at(bend_watch, adit)) { Assert state(bend_bar, down). }
  Rule bend_bars when state(bend_bar, down) and able(bend_watch) and at(bend_watch, adit) and not tolerates(bend_watch, party) { Assert state(bend_bar, up). }
  Rule toll_lapses when tolerates(bend_watch, party) and tollPaidAt(bend_watch) > 0 and watch(clock) >= tollPaidAt(bend_watch) + 144 and not paid_by_joss(party) and not at(party, adit) {
    Retract tolerates(bend_watch, party). Set tollPaidAt(bend_watch) to 0. Assert lapsed(party).
  }
  Action pay_toll(actor: group, site: place) "Pay the Tallymen six coin for the lantern's loan" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, adit) and at(bend_watch, adit) and able(bend_watch)
      and not tolerates(bend_watch, actor) and not lapsed(actor) and quantity(actor, gold) >= 6.
    Time 1.
    On success { Decrease quantity(actor, gold) by 6. Assert tolerates(bend_watch, actor). Set tollPaidAt(bend_watch) to watch(clock). }
    Result "The tall one counts the coins into a cap, nods, and steps back into the dark with the other two. 'The lantern's yours till you come out,' he says, 'and we'll not ask what for.'".
  }
  Action pay_toll_again(actor: group, site: place) "Pay the Tallymen six coin again; the lantern's loan was yesterday's" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, adit) and at(bend_watch, adit) and able(bend_watch)
      and not tolerates(bend_watch, actor) and lapsed(actor) and quantity(actor, gold) >= 6.
    Time 1.
    On success { Decrease quantity(actor, gold) by 6. Assert tolerates(bend_watch, actor). Set tollPaidAt(bend_watch) to watch(clock). Retract lapsed(actor). }
    Result "The tall one holds out the cap before you have your purse open. 'A day, the lantern,' he says. 'You were told.' He counts it, and the three of them step back into the dark.".
  }
  Relation lied(group).
  Action lie_to_watch(actor: group, site: place) "Tell the Tallymen you are the assayer's surveyors" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, adit) and at(bend_watch, adit) and able(bend_watch)
      and not tolerates(bend_watch, actor) and not lied(actor).
    Time 1.
    Resolve check(actor, deception, dc_hard).
    On success { Assert tolerates(bend_watch, actor). Set tollPaidAt(bend_watch) to watch(clock). Retract lapsed(actor). }
    On failure { Assert lied(actor). }
    Result "The tall one looks at the cleanest of you, and at Mistress Orpe's name on the lie, and lets the lantern swing. 'Mind the timbers,' he says.".
    Otherwise "The tall one hears all of it out. 'Orpe's never sent anyone,' he says, almost kindly. 'Six, or the way you came.'".
  }
  Action tell_boy(actor: group, site: place) "Give Nib twopence for what he did not say" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, adit_mouth) and at(nib, adit_mouth) and quantity(actor, gold) >= 2.
    Time 1.
    On success { Decrease quantity(actor, gold) by 2. Assert knows(actor, stope_known). }
    Result "Nib takes the coins and looks at the sky. 'The bat chimney,' he says, to the sky. 'It goes up from the Rising. There's a hole in the side, going down, and it's all knees. Never said.'".
  }

  // ---------------------------------------------------------------------------------------------------------------
  // The Company's works.
  Thing office_door "the counting-house's back door" at counting {
    State bricked blocking "A door in the back wall has been bricked shut, and the brick is newer than the room.".
    State broken "The bricks of the back door lie in a heap, and a low passage goes back into the dark.".
    Change break_bricks "Break through the bricked-up door" from bricked to broken needing crowbar.
  }
  Passage counting_back "the counting-house's back passage" is passage between counting and winding hidden until counting_back_known.
  Discovery counting_back_known "Behind the bricked-up door in the counting-house, a passage runs back to the winding-house.".
  Observe back_opens at counting when state(office_door, broken) "Behind the broken bricks a low passage runs back toward the winding-house." teaches counting_back_known.

  // The cage still hangs on its chain. It will take a company down once, if the chain holds, and it is no way back.
  Passage cage_way "the Blind Shaft's cage" is shaft between winding and sump taking 10 minutes.
  Thing cage "the Blind Shaft's cage" on cage_way {
    State hung dangerous "A plank cage hangs at the top of the Blind Shaft from a single chain. The chain is bright with rust and has two links worn thin. It will carry a company down, perhaps, and only once.".
    State fallen blocking "The cage is gone, and the shaft has the sound of something very large going on falling.".
    Hurts with cage_drop when hung then fallen.
  }
  Hazard cage_drop "The cage's chain" means "Deal (2d6) physical damage to ally unless dexterity save against (13).".
  Observe shaft_voice at winding as sound when true "A long way down, water is talking to itself.".
  Observe sweet_smell at shaft_head as sign when true "The smell that comes up with the draught is sweet and wrong. Something dead has lain down there a long time.".

  // The sluice: the Aeneans' valve on the Wend. It does not stay shut: the river backs up the Swallow's throat and the
  // wheel creeps back a tooth at a time, so that four hours after it was wound (or after the Cap's ring was last turned) the
  // gate gives, the Hall fills, and the causeway to the Cap is under the water again.
  Thing sluice "the Swallow's sluice-gate" at sluice_house {
    State open "The great bronze wheel on the wall is set to OPEN, and below the floor the river goes by in its channel with the sound of a mill-race.".
    State wound "The wheel is wound round to SHUT, and under the floor the channel is empty and ticking as it drains. The wheel does not hold: it creeps back a tooth at a time against the river, and from above comes a groaning, the Wend backing up the Swallow's throat. You judge you have four hours.".
    Change close_sluice "Wind the sluice-wheel shut" from open to wound.
    Change open_sluice "Wind the sluice-wheel open" from wound to open.
  }
  Initially Assert state(sluice, open).
  Measure shutAt(entity). Measure ringTurns(entity).
  Rule shut_marks when state(sluice, wound) and shutAt(sluice) == 0 { Set shutAt(sluice) to watch(clock). }
  Rule shut_clears when state(sluice, open) and shutAt(sluice) != 0 { Set shutAt(sluice) to 0. Set ringTurns(sluice) to 0. }
  Hazard burst_water "The river returning" means "Deal (2d6) physical damage to ally unless strength save against (13).".
  Rule gate_gives when state(sluice, wound) and shutAt(sluice) != 0 and watch(clock) >= shutAt(sluice) + 24 {
    Assert state(sluice, open).
  }
  Rule gate_gives_news at cistern_hall when state(sluice, open) and at(party, cistern_hall) and shutWas(party)
    says "A boom comes down the stair from the Conduit, and then a wall of the Wend." {
    Assert strikes(burst_water, party). Retract shutWas(party).
  }
  Relation shutWas(group).
  Rule shutwas_clears when state(sluice, open) and shutWas(party) and not at(party, cistern_hall) { Retract shutWas(party). }
  Rule remember_shut when state(sluice, wound) and not shutWas(party) { Assert shutWas(party). }
  // The causeway to the Cap is under the black water until the river is cut; once the company has stood on the Cap it can
  // be swum when the river runs, and the river takes its toll of whoever goes first.
  Thing causeway "the causeway" on hall_cap {
    State dry "The causeway is a white road out of the black mud.".
    State flooded dangerous "The causeway lies a hand under black water, and the river runs over it.".
    Hurts with causeway_swept when flooded then flooded.
  }
  Hazard causeway_swept "The river on the causeway" means "Deal (2d6) physical damage to ally unless strength save against (12).".
  Initially Assert state(causeway, flooded).
  Rule causeway_dries when state(sluice, wound) and state(causeway, flooded) { Assert state(causeway, dry). }
  Rule causeway_floods when state(sluice, open) and state(causeway, dry) { Assert state(causeway, flooded). }
  Query hallDry() means state(sluice, wound).
  Observe causeway_dry at cistern_hall when hallDry() "With the river cut, the hall has dropped a man's height. A causeway of white stone runs out of the black mud toward the Cap, and the columns stand on their bases. The mud is drying only on its top.".
  Observe water_high at cistern_hall when not hallDry() "The water is a fathom deep and perfectly still. A causeway runs out toward the Cap, a hand beneath the surface.".
  Observe sluice_news at north_walk when state(sluice, wound) "From the Hall the sound of the river has changed: it is running down a grating, thinner, and the water-line on the wall is exposed in a band of green slime.".
  // The river comes back where it is cut, and every place below it is told before it comes: the Hall (where it hits), the
  // Cap, the Breach and Gear-Hall, the Quiet Gallery and the Dial. Two hours, three, and the gate gives at four.
  Observe hall_damp at cistern_hall as sound when state(sluice, wound) and watch(clock) >= shutAt(sluice) + 12 "From the stair that goes up to the Conduit, a groaning, a long way off, that was not there an hour ago. The mud along the causeway has stopped drying.".
  Observe hall_damp2 at cistern_hall as sound when state(sluice, wound) and watch(clock) >= shutAt(sluice) + 18 "Water is running down the Conduit stair in a thin sheet, and the black pools between the columns have begun to creep toward each other.".
  Observe cap_damp at the_cap as sound when state(sluice, wound) and watch(clock) >= shutAt(sluice) + 12 "Somewhere above the Hall, far off, a groaning has started that was not there an hour ago.".
  Observe cap_damp2 at the_cap when state(sluice, wound) and watch(clock) >= shutAt(sluice) + 18 "The bronze ring is wet. The air coming up the stair has stopped moving, and water is beginning to stand on the causeway, a finger deep.".
  Observe bore_damp at breach as sound when state(sluice, wound) and watch(clock) >= shutAt(sluice) + 16 "Far above, a dull knock, then a long fall of water, going down the Bore wall.".
  Observe bore_damp2 at gear_hall as sound when state(sluice, wound) and watch(clock) >= shutAt(sluice) + 16 "The ticking is lost under a rising roar from the Bore wall: the river is coming back.".
  Observe gallery_damp at quiet_gallery as sign when state(sluice, wound) and watch(clock) >= shutAt(sluice) + 16 "The floor takes no sound, but it shivers underfoot, as a bridge does under a cart a long way off.".
  Observe dial_damp at dial_room when state(sluice, wound) and watch(clock) >= shutAt(sluice) + 16 "The stars in the glass floor shiver, every one, and settle. Somewhere above, the river is on its way back down.".
  Action wind_cap_ring(actor: group, site: place) "Turn the Cap's bronze ring to hold the river back another four hours" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, the_cap) and state(sluice, wound) and ringTurns(sluice) < 3 and quantity(actor, rations) >= 1.
    Time 6.
    On success { Set shutAt(sluice) to watch(clock). Increase ringTurns(sluice) by 1. Decrease quantity(actor, rations) by 1. }
    Result "The ring is a hand-wheel, once you take the weight on it; the Legion put it where a keeper of the weight could reach it without leaving the stair. It takes all of you an hour, and a day's food in sweat. Far above, the gate answers, grudging. You have bought four hours, and the ring is a little stiffer for it.".
  }
  Observe ring_stiff at the_cap when state(sluice, wound) and ringTurns(sluice) >= 3 "The ring will not move again. The Legion's grease is gone from it, and whatever you do the river will come back.".
  // The Cap and the Bore.
  Observe cap_sign at the_cap as sign when true "The bronze ring is polished on one side by something that has dragged on it, a very long time ago.".
  Observe the_stair_cold at the_cap as sound when true "A tick, tick, tick comes up the stair from a long way below. It does not hurry.".

  // The Calx Gate.
  Thing calx_gate "the Calx Gate" on gate_way {
    State rusted blocking "The Calx Gate hangs in its slot, green bronze; the wheel's pawl is a lump of rust and the wheel will not turn.".
    State freed blocking "The wheel's pawl is black with oil, and moves in its notch when pushed.".
    State raised "The bronze portcullis has gone up into its slot, grumbling, and the road runs away west under its vault.".
    Change oil_pawl "Free the gate-wheel's pawl with lamp oil" from rusted to freed needing lamp_oil consuming lamp_oil.
    Change raise_gate "Turn the wheel and raise the Calx Gate" from freed to raised.
  }
  Observe gate_lantern at gate_house when state(calx_gate, raised) "The way west lies open, and a faint draught from it smells of grass." teaches calx_known.
  Thing buried_portal "the scree against the portal" on buried_way {
    State buried "Scree and earth are heaped against the portal's arch to twice a man's height.".
    State dug "The scree has been shovelled aside from the arch, and the old gate stands dark behind it.".
    Change dig_scree "Dig the portal out" from buried to dug needing shovel.
  }
  Thing portal_inside "the fall of earth inside the portal" on portal_inner {
    State caved blocking "A slope of earth and stone fills the arch from inside. At the top there is a gap you could get a hand through.".
    State cleared "The earth has been dug back from the arch, and daylight comes in.".
    Change dig_inner "Dig the earth out of the portal" from caved to cleared needing shovel.
  }
  Rule portal_connects when state(buried_portal, dug) and state(portal_inside, caved) { Assert state(portal_inside, cleared). }
  Rule portal_connects_back when state(portal_inside, cleared) and state(buried_portal, buried) { Assert state(buried_portal, dug). }
  Hazard sway_stone "The scree shifting" means "Deal (2d6) physical damage to ally unless dexterity save against (12).".

  // The foreman's papers.
  Kind foreman_letter "Foreman Carr's letter" is document teaching letter_read described "A letter in a clerk's hand and a foreman's, the last lines written in pencil. It was never sent.".
  Discovery letter_read "Carr's letter: 'The Company will not like what it has to hear. We have broken into a lid. Under the lid is a hall, and under the hall a shaft older than the road. In the shaft hangs a weight, and the weight moves. There are grey men in the shaft who wind it. We broke the road in the process and the river came in; there is a gate on the road, and the road goes west two miles and comes out in daylight. I have laid the men in the vault by the Breach myself, in their boots, and counted them twice. I am going to oil the pawl. If I do not come back, burn this.'" .
  Kind carr_ledger "the Company's ledger of the last fortnight" is document teaching ledger_read described "A ledger of tonnage and wages in a bold hand; the last pages are names and a sum against each.".
  Discovery ledger_read "Fifteen names, the foreman's own at the head, each with a day's wage unpaid; one, the sixth, struck through in another ink. Thirteen lie in the vault; the Foreman is not among them.".
  Item letter_item "Foreman Carr's letter" is foreman_letter in desk hidden until foreman_found.
  Item ledger_item "the Company's ledger" is carr_ledger in desk hidden until foreman_found.
  Thing desk "the Foreman's desk" at foremans_office {
    State latched "The Foreman's desk is closed, and a stone sits on its lid.".
    State open "The desk is open. A letter and a ledger lie in it, and a box.".
    Change open_desk "Lift the stone and open the desk" from latched to open.
    Holds.
  }
  Discovery foreman_found "The Foreman's desk holds the Company's last papers.".
  Observe desk_open at foremans_office when state(desk, open) "The desk's lid is open." teaches foreman_found.
  Item carr_box "Foreman Carr's box" is jeweled_box in desk hidden until foreman_found.
  Item carr_dagger "a dagger of black glass" is ironglass_dagger in desk hidden until foreman_found.
  Item carr_rod "the assayer's dowsing rod" is dowsing_rod at counting.
  Item carr_zoology "a zoological manual, water-stained" is zoological_manual at foremans_office.

  // The Tally-Wall.
  Observe wall_read at tally_wall when true "Under the Company's chalk the Aenean script is clear: the legion's engineers signing off a work. THE CAP IS SET. THE WEIGHT STILL SWINGS. LET NO ONE STOP IT. VI." teaches bore_known.
  Observe wall_period at tally_wall when knows(party, bore_known) "The last figure is not a date. It is a measure, cut with the engineers' own gauge: one swing in six breaths." teaches period_known.
  Observe wall_cap at the_cap when true "On the Cap, cut deep and recut, one line of Aenean: THE WEIGHT STILL SWINGS." teaches cap_known.
}

data/adventures/the-dorothea/antlers.kyr:
Module dorothea "The Dorothea" {
  Description "The Antlers: a drowned forest of sea-stacks a night north of Tolleth, white with guano and loud with birds; a harvest of eggs, down and fat that the House buys at its own price; a rope-ladder older than the lease; a cresset on the biggest stack that the lease forbids anyone to light.".

  Place antlers "the Antlers" is region.
  Place antler_camp "the harvest camp" is settlement within antlers at 0, 0.
  Place stacks "the Great Stack" is wilderness within antlers at 1, 0.
  Place antler_ledge "the Antlers' ledge" is room within antler_camp at 0, 1.
  Place hut_room "the harvest hut" is room within antler_camp at 1, 0.
  Place stack_foot "the foot of the Great Stack" is room within stacks at 0, 0.
  Place stack_top "the top of the Great Stack" is room within stacks at 1, 0.

  Passage ledge_way "the ledge path" is path between antler_ledge and hut_room taking 10 minutes.
  Passage stack_way "the path round the stack-foot" is path between hut_room and stack_foot taking 20 minutes.
  Passage stack_ladder "the rope ladder" is ladder between stack_foot and stack_top
    opening when ladderSound(party) "The ladder hangs down the stack face in a long frayed S, the lashings of the lower rungs eaten through by salt and the upper ones nested in. A rung as it swings goes black with birds. Nobody sensible puts a foot on it as it is.".
  Query onAntlers(g: group) means at(g, antler_ledge) or at(g, hut_room) or at(g, stack_foot) or at(g, stack_top).

  Observe ledge_scene at antler_ledge when not at(hull, antler_ledge) "The Antlers' ledge: a wet shelf of rock, a plank-stump, ropes going up and down the faces of the stacks like rigging on a stone ship. The noise is a wall. Down drifts through it like snow in a draught.".
  Observe hut_scene at hut_room when true "The harvest hut: a long low room roofed in turf and whalebone, hammocks in tiers, egg-trays to the rafters with straw between, a barrel of fat, and on a shelf two day-books, a green one and a grey one, with a key-and-ring branded in the covers. The air tastes of ammonia and fish and warm feathers.".
  Observe foot_scene_antlers at stack_foot when true "The foot of the Great Stack: guano like frozen milk to the ankle, the cliff going up out of sight into a roar, and from a ring-bolt a ladder of rope and driftwood rungs, more repaired than made, going up into the cloud of wings. Beside it, a hoist-basket on a long rope, and a boy-sized hole in the rock where the harvesters sleep when the weather turns.".
  Observe top_scene at stack_top when not lampLit(lamp_antlers) "The top of the Great Stack: a green roof of turf and thrift, and on it a crowd of gannets, standing shoulder to shoulder, who regard you with great calm. At the middle an iron cresset on a post, rusted and cold. A board is nailed to the post: THE HOUSE OF MARCHBANK. LEASE OF THIS STACK. CLAUSE 7: NO FIRE UPON THIS STACK WITHOUT THE HOUSE'S LEAVE. A key-and-ring in one corner. The sea goes away on all sides without end, and not a light on it.".
  Observe top_lit at stack_top when lampLit(lamp_antlers) "The cresset burns on the top of the Great Stack and the gannets have not moved. Hob Sedge's boys are sitting round it eating the House's sandwiches, and the sea in the dark below is full of the shapes of stones, each one showing now.".

  Person deane "Osric Deane" at hut_room {
    Role "agent of the House at the Antlers". Ancestry human. Level 2. Peaceable. Pronouns he. Manner jovial.
    Likeness "merchant".
    Greets "A big soft man in a green waistcoat is lying in a hammock in the harvest hut with a green-bound ledger on his chest, rising and falling with his breath. He does not get up. 'Excuse my not rising,' he says. 'Deane. The House's agent, here, and not well, in the way of a man who has been well too long.' He lifts one finger from the green book. 'You'll want to see the Prentice. Everyone does. I just have the title.'".
    Greets again "Osric Deane has not risen, but he has moved the green ledger from his chest to his knee, which in Osric Deane is a great exertion. 'Back so soon,' he says. 'It is always a good sign when they come back. It means they have been disappointed by something other than me.'".
  }
  Person wick "Wick Bligh" at hut_room {
    Role "prentice of the House, keeper of the Antlers' day-book". Ancestry human. Level 1. Peaceable. Pronouns she. Manner jovial.
    Likeness "scholar".
    Greets "A girl of twelve in a sack apron, grey cuffs to the elbow, sits cross-legged on the egg-tray with a grey-bound book on her knee and a pencil behind each ear. 'Prentice,' she says, 'bound seven years, four to go. Wick. I do the day-book. Mr Deane does the other book, which has a green cover, and a different number in it.'".
    Greets again "Wick Bligh has a new pencil behind each ear and is writing so fast the tip squeaks. 'I put you in,' she says, without looking up. 'The grey book, not the green one. You are down as Visitor. Mr Deane would have put Nuisance.'".
  }
  Person hob "Hob Sedge" at stack_foot {
    Role "headman of the Antlers' harvest". Ancestry human. Level 3. Peaceable. Pronouns he. Manner stoic.
    Likeness "sailor".
    Greets "A man with a face like a shut door and a rope round his waist coiled six times looks up from splicing. He has a missing finger on each hand. 'Sedge,' he says, to the splice. 'Stack-man. We go up for the eggs in the dark, and down for the down in the day, and never up the same way twice. You'll want the hoist. Everyone does, the first time. Most of them only the once.'".
    Greets again "Hob Sedge does not look up from the splice. 'Up the hoist or down it,' he says. 'Not up the ladder. The ladder is for the ones that mean to be in the book.'".
  }
  Initially Set quantity(deane, gold) to 12.

  Relation ladderSound(group). Relation cressetFree(group). Relation birdsCounted(group). Relation hobWilling(group).
  Hazard rung_fall "The rung that gives" means "Deal (2d6) physical damage to ally unless dexterity save against (13).".

  // ── The ladder: three ways up, one of them a danger ─────────────────────────────────────────────────────────────
  Topic hob_hoist with hob "Ask Hob Sedge to take you up in the egg-basket" when true once {
    Says "'It holds two,' says Hob, 'and a boy to work the winch. You go up sitting on the eggs and you don't look down and you don't talk.' He considers you. 'Four of you will take three trips. I'll bill the House.'".
    On discuss { Assert ladderSound(actor). }
  }
  Action mend_the_ladder(actor: group, site: place) "Re-lash the rope ladder's lower rungs with new rope" {
    Description "It wants a coil of good rope, and a hand that knows a lashing.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, stack_foot) and not ladderSound(actor) and holding(actor, rope).
    Time 6.
    On success { Spend rope from actor. Assert ladderSound(actor). }
    Result "You pull the worn lashings out and put new ones in, each rung in turn, the way the seamen do, with the birds screaming round your head. Hob Sedge watches, and says nothing, and then gets up and tries the first rung with his whole weight. 'Aye,' he says, which is a speech.".
  }
  Action climb_old_ladder(actor: group, site: place) "Climb the old rope ladder as it is" {
    Description "Eighty feet. The lashings are salt-rotten. Hob Sedge says he has not been up it in three seasons.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, stack_foot) and not ladderSound(actor).
    Time 4.
    Resolve check(actor, climbing, dc_fair).
    On success { Retract at(actor, stack_foot). Assert at(actor, stack_top). }
    On failure { Assert strikes(rung_fall, party). }
    Result "You go up by feel and nerve, with the birds exploding off the rock round you and the ladder swinging out under your weight and back, until a hand comes over the lip and hauls, and you are lying face down in thrift, with a gannet looking at you from a yard away as at a poor relation.".
    Otherwise "A rung gives under your foot, a knuckle of wood, and then another, and you are on your hands on the rope, and then the ground arrives. Hob Sedge has not moved. 'Told you,' he says, quite kindly.".
  }

  // ── The cresset, and clause seven ───────────────────────────────────────────────────────────────────────────────
  Topic deane_clause with deane "Ask Osric Deane why no fire may be lit on the stack" when true once {
    Says "'Clause seven,' says Deane, to the ceiling. 'A fire on the stack puts the birds off the ledges, and a stack without birds is worth nothing, and the lease is on the harvest. That is what I am told. I have never seen a fire on the stack.' He turns a page. 'Hob's boys used to light it for the boats, in my predecessor's time. A ship came in by it once in a gale, I'm told. There has not been a fire since I came. And the Tern went on the race, in the dark, at Whitsun, and I went up the ladder myself next day and stood by a cold basket and wrote it in the other book.'".
  }
  Topic deane_books with deane "Ask Osric Deane about the two books" when leafAntlers(actor) once {
    Says "He is quiet for so long you think he has gone back to sleep. 'The green book goes to the Factor,' he says. 'It says the birds are put off by fire, and the cresset is kept cold for the harvest. The grey one is Wick's. It says what happened.' He opens his eyes. 'I should like it if it was never said that I knew. I should like it more if it was never said that I could have lit it.'".
  }
  Action pay_antler_rent(actor: group, site: place) "Pay the Antlers' rent arrears, fifteen coin, and buy out clause seven" {
    Description "The House sells the leave it will not grant. It takes coin for it, in Deane's hand, on the quarter.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hut_room) and at(deane, site) and houseHolds(lamp_antlers) and not cressetFree(actor) and quantity(actor, gold) >= 15.
    Time 2.
    On success { Decrease quantity(actor, gold) by 15. Increase quantity(deane, gold) by 15. Assert cressetFree(actor). }
    Result "Deane writes it in the green book, and then, after a moment, in the grey one, which Wick holds out to him without a word. He tears a slip from the back of the lease and writes on it: LEAVE GIVEN, CLAUSE 7, THE CRESSET, FOR SO LONG AS THE ARREARS ARE PAID. 'It is the House's leave,' he says. 'I have signed it as the House.' He gives it to Wick to put in the day-book.".
  }
  Action count_the_birds(actor: group, site: place) "Walk the stack top and count what the birds do round a flame" {
    Description "The lease says fire puts them off. A hawk of a ranger can say whether a bird minds.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, stack_top) and houseHolds(lamp_antlers) and not birdsCounted(actor) and capable(actor, woodcraft).
    Time 6.
    Resolve check(actor, woodcraft, dc_fair).
    On success { Assert birdsCounted(actor). }
    Result "You go along the nests with a stick of charcoal and the back of a shirt, and you count: the old nests, the new ones, the places where the nests are thickest. The thick places are the south edge, where the House's board faces. It is the windward face; the fire would stand on the lee. You count the gannets that have stood there for the last two seasons without moving, at a quarter-mile from the lee of the nearest sea-fire in the Reach: none have moved. It is a count a man can show.".
    Otherwise "The birds are many, and you are not a bird. You come down with a number you do not trust.".
  }
  Topic deane_release with deane "Show Osric Deane the count of the nests" when birdsCounted(actor) once {
    Says "He reads it, and then reads it again, and puts his thumb on the number as if it might fall off the page. 'The birds don't mind,' he says. 'No. They never did.' He signs the leave, his own name, not the House's, in a hand that has not been used that way for years. 'I will be dismissed,' he says, with a cheerfulness that surprises both of you. 'Posts are not hard to come by, only to keep.'".
    On discuss { Assert cressetFree(actor). }
  }
  Action pull_the_board(actor: group, site: place) "Pull the House's board off the cresset-post and throw it into the sea" {
    Description "Nobody has ever been put in gaol for a board. The House will remember it.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, stack_top) and houseHolds(lamp_antlers) and not cressetFree(actor).
    Time 1.
    On success { Assert cressetFree(actor). Assert marked(actor). }
    Result "It comes away with a screech of nails. The gannets do not look round. You carry it to the edge and throw it, and it spins out over the sea, key-and-ring and all, and does not splash for a very long time. You have just made an enemy of a counting-house.".
  }
  Action light_the_cresset(actor: group, site: place) "Light the Antlers' cresset" {
    Description "Hob's boys have kept the fat in the barrel and the wick in the tin for twenty years. They have not been asked.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, stack_top) and houseHolds(lamp_antlers) and cressetFree(actor).
    Time 3.
    On success { Retract houseHolds(lamp_antlers). Assert lampLit(lamp_antlers). Increase freed(actor) by 1. Assert hobWilling(actor). }
    Result "It takes the three of you and a coat held for a windbreak. When it goes, it goes with a roar, and the gannets lift as one white sheet off the whole top of the stack and settle again, one by one, and look at the flame. Hob Sedge's boys have come up the hoist and stand along the edge, saying nothing. Hob himself puts his hand on the cold iron post and then takes it away. 'My father lit it,' he says. 'Twenty years.' The Tern's lights, you think, would have been just there.".
  }

  // ── What the Prentice knows ─────────────────────────────────────────────────────────────────────────────────────
  Topic wick_book with wick "Ask Wick Bligh to read you the day-book" when true once {
    Says "She has been waiting, you think, to be asked for years. 'Down, ninety stone. Eggs, eleven great hundred. The Tern, at Whitsun, on the race, no light on the stack, forty-two hands.' She turns the page. 'Lamps and Lights: the cresset, clause seven. Rent arrears fifteen crowns. Mr Deane to send the Factor Book One.' She looks up. 'Book Two is this one. He doesn't say that. I do.'".
    On discuss { Assert leafAntlers(actor). Increase leaves(actor) by 1. Assert knows(actor, leaf_antlers_d). }
  }
  Topic wick_ranks with wick "Ask Wick Bligh who is above whom in the House" when true once {
    Says "'Prentice, that's me,' says Wick, ticking on her fingers. 'Clerk, that's Mr Pym at Port Ness, he writes the day-book fair so the Factor can read it. Agent, that's Mr Deane, and Mr Quillon at Skerrow. Factor is Miss Stannard in Orsett, and sometimes at the Ness. Principal is Mr Marchbank, who has a seal. Each one owes the one above, and is owed by the one below. I'm owed by nobody.' She considers. 'Hob's boys owe me eggs.'".
    On discuss { Assert knowsRanks(actor). }
  }

  // ── The race, if there is no pilot ──────────────────────────────────────────────────────────────────────────────
  Action hail_harvest_boats(actor: group, site: place) "Fire the gun and hail the harvesters' boats to tow her up the race" {
    Description "Hob Sedge's boys row a lugger of eggs up that lane twice a day. They will not row for nothing, but they will row.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and at(hull, antler_race) and troubled(hull) and not towCalled(hull).
    Time 1.
    On success { Assert towCalled(hull). }
    Result "Rune fires the little gun, and the sound goes up the lane and comes back a dozen times off the stacks, and a flock of something lifts. After a long while a black dot appears in the white, and then four, and then there are boats, small and low, with a man in each who rows as if the lane were his own garden.".
  }
  Rule tow_comes when towCalled(hull) and troubled(hull) and watch(clock) >= raceAt(hull) + 14
    says "The harvesters' boats get a line aboard and take her up the race as a boy takes a cow home: cheerfully, and without asking her opinion. Bascom lets out a breath. 'Pay them in eggs,' she says, 'since I can't in cash.'" {
    Retract troubled(hull). Decrease cargo(hull) by 2.
  }
  Action run_the_race(actor: group, site: place) "Take the wheel and run the race yourselves" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, helm) and at(hull, antler_race) and troubled(hull) and not towCalled(hull).
    Time 2.
    Resolve check(actor, wayfinding, dc_hard).
    On success { Retract troubled(hull). }
    On failure { Retract troubled(hull). Increase water(hull) by 10. Assert holed(hull). }
    Result "The stacks go by at a pace of your own choosing, which turns out to be too fast. Somewhere in the white you find the lane, and the lane finds you. Bascom, at your elbow, says nothing, and goes on saying it.".
    Otherwise "The Dorothea takes a stone on her larboard bilge, and a barrel's worth of her goes. Bascom takes the wheel with a word you will not repeat. She gets her through. There is water in the hold, and the pump will be wanted.".
  }
}

data/adventures/the-dorothea/ashkeld.kyr:
Module dorothea "The Dorothea" {
  Description "Ashkeld: three days out on the south-west road, a black cone that has smoked for as long as there has been a Tolleth, hot springs, ash on every roof, and a people who sell yellow stone and have not seen the House's agent in two seasons. The one light on the Reach nobody leases.".

  Place ashkeld "Ashkeld" is region.
  Place ashkeld_village "the boiling-houses" is settlement within ashkeld at 0, 0.
  Place ashkeld_cone "the cone" is wilderness within ashkeld at 1, 0.
  Place ashkeld_beach "Ashkeld's black beach" is room within ashkeld_village at 0, 1.
  Place ashkeld_springs "the hot springs" is room within ashkeld_village at 1, 1.
  Place ashkeld_works "the sulphur-house" is room within ashkeld_village at 2, 0.
  Place ashkeld_rim "the crater rim" is room within ashkeld_cone at 0, 0.

  Passage beach_way "the beach road" is path between ashkeld_beach and ashkeld_springs taking 10 minutes.
  Passage works_way "the ash track" is path between ashkeld_springs and ashkeld_works taking 10 minutes.
  Passage rim_way "the path up the cone" is path between ashkeld_works and ashkeld_rim taking 1 hour.

  Observe ash_beach_scene at ashkeld_beach when not at(hull, ashkeld_beach) "Ashkeld's black beach: sand like gunpowder, a line of tide-wrack of pale pumice that bobs, and a plume of steam going straight up from the hill. The sea at the edge is warm. The air tastes of a struck match.".
  Observe ash_springs_scene at ashkeld_springs when true "The hot springs: a hillside of terraces, each a pool the colour of milk or turquoise or rust, with steam standing over it in rags. Women sit in them to the shoulders with their washing. Ash lies on every ledge like a grey flour, and when it rains it smells of eggs.".
  Observe ash_works_scene at ashkeld_works when true "The sulphur-house: a long shed of lava blocks roofed in tarred sailcloth, floored with yellow dust, and heaped to the rafters with crates of yellow stone. Every crate has a key-and-ring stencilled on it. None has been moved in a year; the stencil is faded to a ghost.".
  Observe ash_rim_scene at ashkeld_rim when true "The crater rim: a crust of cooled black over a bowl you cannot see the floor of. Vents hiss from cracks, yellow-lipped, and the air comes in slow warm breaths that make your eyes run. Beyond the lip, far down, a dull red eye opens and shuts.".
  Observe cone_night at ashkeld_beach when dark() and not at(hull, ashkeld_beach) "In the dark, the underside of the cone's cloud is red. It glows and fades like a coal blown on. Of all the lights on the Reach it is the only one that has never needed a keeper, or been leased.".

  Person merrow "Merrow Gantry" at ashkeld_works {
    Role "headwoman of the Ashkeld gatherers". Ancestry human. Level 3. Peaceable. Pronouns she. Manner acerbic.
    Likeness "farmer".
    Greets "A broad woman in a leather apron stands on a stool, nailing a lid onto a crate with a hammer, and not looking up. 'I gather, I don't sell,' she says. 'Gantry. Merrow. The House sells. The House hasn't sent an Agent in two seasons and I'd as soon it didn't send one now. You came on the Dorothea? Then you have come a long way to pay for the stone I have been sitting on.'".
    Greets again "Merrow Gantry has another lid on the stool and another crate under it, and has not taken her eyes off the nail. 'You have not gone,' she says. 'I notice that about the House's friends. They are slow to leave, and quick to be owed.'".
  }
  Person ansel "Ansel Hallow" at ashkeld_springs {
    Role "bath-keeper, who reads the cone". Ancestry human. Level 2. Peaceable. Pronouns he. Manner stoic.
    Likeness "abbess".
    Greets "A very thin man sits on the lip of a milk-white pool with his eyes shut, his feet in it, and a stick of charcoal in his hand with which he is, you see, keeping a tally on his knee of something that is not time. 'You are standing in my light,' he says, without opening his eyes, and there is no light to stand in. 'Hallow. I keep the baths, and a count of the mountain's breaths. You'll want to know when it breathes in.'".
    Greets again "Ansel Hallow does not open his eyes. 'You are standing in my light again,' he says, and the milk-white water moves round his ankles though nothing has moved it. 'Seventeen. Do not ask. I will tell you when it is eighteen.'".
  }
  Relation anselTip(group). Relation belled(group). Relation crateGiven(group).
  Hazard vent_gas "The breath of the vents" means "Deal (2d6) physical damage to ally unless constitution save against (13).".

  Topic merrow_house with merrow "Ask Merrow Gantry what the House owes Ashkeld" when true once {
    Says "'Two seasons of stone,' says Merrow, nailing. 'Crated, stencilled, waiting for the Dorothea, who has not called. A clerk in Tolleth writes to me every quarter-day: the shipment will be fetched. It will be fetched.' She puts the hammer down. 'I will give it to whoever carries it to him. At a price. I do not eat on a clerk's promises.'".
  }
  Topic merrow_cone with merrow "Ask Merrow Gantry about the cone" when true once {
    Says "'It has smoked since the roads,' she says. 'Longer. My grandmother said the Aeneans came and drew a line round it and said it was theirs, and went away, and it went on smoking. It lights the sea to the north at night for forty miles. The House wants to buy everything on the Reach that is a light. It sent a man to ask about the cone once. He went up it. He came down sooner.'".
  }
  Topic ansel_breath with ansel "Ask Ansel Hallow when the cone breathes in" when true once {
    Says "'At noon,' says Ansel, 'the vents take in for the space of a pot coming to the boil. Then the rim is as safe as a kitchen. At any other hour you want a wet cloth, and a strong constitution, and no hurry.' He opens one eye. 'Merrow's mule-bell is up there. It went over the lip in the spring with a mule on the end of it. She wants the bell. Fetch the bell at noon, and she will give you what she has.'".
    On discuss { Assert anselTip(actor). }
  }
  Topic ansel_count with ansel "Ask Ansel Hallow what he is counting on his knee" when true once {
    Says "'Breaths,' says Ansel. 'In, then out, then in. My father cut notches on the lintel, and his father before him; there are eleven hundred on the door of the bath-house, and I have the twelve hundredth on my knee.' He turns the charcoal over. 'It takes in later every year. The interval was a pot to the boil in my father's time. It is a pot and a little more. I do not say what it is a count of. I say that the women stopped bringing their washing to the top pool in the spring, and that nobody told them to.' He opens the other eye. 'Somebody ought to tell the House. The House does not ask.'".
  }
  Action fetch_the_bell(actor: group, site: place) "Go to the rim at noon and fetch Merrow Gantry's mule-bell from the lip" {
    Description "Ansel's breath. The vents take in for the space of a pot coming to the boil.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ashkeld_rim) and anselTip(actor) and not belled(actor).
    Time 2.
    On success { Assert belled(actor). }
    Result "You stand on the lip counting, and at the count Ansel gave you the hiss falls, and the air goes cool and clean and tastes of nothing, and you go down the three yards of crust with a rope round your middle and take the bell off its rotten strap. The vent behind you takes its breath in; the next one, out, is full of yellow. You are on the lip before it reaches you.".
  }
  Action fetch_the_bell_blind(actor: group, site: place) "Go down to the lip for the bell with a wet cloth and no counting" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ashkeld_rim) and not anselTip(actor) and not belled(actor).
    Time 2.
    Resolve check(actor, woodcraft, dc_hard).
    On success { Assert belled(actor). }
    On failure { Assert strikes(vent_gas, party). }
    Result "You tie the cloth and go, and the vents all behave. The bell is where it fell. The sweat has a yellow taste on your lip.".
    Otherwise "The vent behind you breathes out, and the world goes yellow, and you are on your hands and knees on a hot crust, being sick.".
  }
  Topic merrow_bell with merrow "Give Merrow Gantry her mule-bell" when belled(actor) and not crateGiven(actor) once {
    Says "She takes the bell and turns it over and rings it once, and a woman in the sulphur-house looks up and puts her hand to her mouth. 'That was the old mule's,' says Merrow. 'Take the Tolleth crate. The one on the left with the faded ring.' She stops. 'Tell the clerk what it cost.'".
    On discuss { Give dorothea_sulphur_crate to actor. Assert crateGiven(actor). }
  }
  Action pay_for_crate(actor: group, site: place) "Pay Merrow Gantry twelve coin for the Tolleth crate" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ashkeld_works) and at(merrow, site) and not crateGiven(actor) and quantity(actor, gold) >= 12.
    Time 1.
    On success { Decrease quantity(actor, gold) by 12. Increase quantity(merrow, gold) by 12. Give dorothea_sulphur_crate to actor. Assert crateGiven(actor). }
    Result "She counts it, grunts, and shoves the crate across the dust with her boot. 'Twelve,' she says. 'And the clerk will give you twenty-five, and say it was nothing.'".
  }
  Action argue_for_crate(actor: group, site: place) "Argue Merrow Gantry out of the crate on the clerk's good name" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ashkeld_works) and at(merrow, site) and not crateGiven(actor).
    Time 2.
    Resolve check(actor, persuasion, dc_hard).
    On success { Give dorothea_sulphur_crate to actor. Assert crateGiven(actor). }
    Result "You say it is the House's crate and the House's clerk and the House's debt, and that she will have the money when the crate is on his desk; that she has two seasons of stone to see sold. She looks at you for a long time with her hammer on her shoulder. 'You've a face for a lie,' she says. 'But you have not told me one.' The crate is yours.".
    Otherwise "'I sell stone,' says Merrow, 'not sentences.'".
  }
  Kind dorothea_sulphur_crate "a crate of Ashkeld sulphur" is gear worth 10 weighing 3 described "A tarred crate of yellow stone with a faded key-and-ring on the lid, and underneath it, burned in with a hot iron, a clerk's number and the word TOLLETH.".
}

data/adventures/the-dorothea/combs.kyr:
Module dorothea "The Dorothea" {
  Description "The Combs: a mile of rock between the open sea and Skerrow, one gap in it, and four ways to meet it.".

  // At first light the Dorothea is at the Combs. The gap is a quarter-mile wide and runs like a mill-race on the ebb;
  // on the slack, at the turn of the tide, it is merely hard. Bascom wants the gap now, because she is a day behind her
  // debt. The mate has the helm when she does not. The company chooses what it is party to.
  Measure combsAt(entity).
  Relation combsMet(entity). Relation waitedFlood(entity). Relation ranGap(entity). Relation lightened(entity). Relation wheelTaken(group).
  Rule combs_trouble when at(hull, teeth) and not combsMet(hull)
    says "'Slack's in five hours,' says Rune, at the wheel. 'The gap's running now at six knots. We can lie off and wait, which is safe and loses us the morning and the Orsett man's patience, or we can run it, which is not.' Nobody says anything. Bascom looks at the rocks as if they owed her money." {
    Assert combsMet(hull). Assert troubled(hull). Set combsAt(hull) to watch(clock).
  }
  Observe combs_choice at deck when combsMet(hull) and troubled(hull) and at(hull, teeth) "The Dorothea lies off the Combs with her sails shivering. Every face on deck is turned to the gap, and every one of them is doing a different sum.".
  Action lie_off(actor: group, site: place) "Ask Bascom to lie off and wait for the slack" {
    Description "Five hours. The Orsett man's patience is a thing a ship can run out of faster than a tide.".
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, helm) or at(actor, deck)) and combsMet(hull) and troubled(hull) and not waitedFlood(hull) and not ranGap(hull) and not lightened(hull).
    Time 1.
    On success { Assert waitedFlood(hull). Assert decidedCombs(hull). }
    Result "'Aye,' says Bascom, after a long moment, as if the word cost her a coin. 'We'll lie off.' She takes the pipe out of her mouth, looks at it, and puts it back. 'Mind what I owe the man,' she says. 'It goes up every hour.'".
  }
  Relation decidedCombs(entity).
  Rule slack_comes when waitedFlood(hull) and troubled(hull) and watch(clock) >= combsAt(hull) + 30
    says "The roar in the gap dies by degrees, like a crowd leaving, until it is a lane of dark water between white lines. 'Now,' says Bascom, and the Dorothea goes through it under bare poles with her keel a foot above the rock, and nobody breathes." {
    Retract troubled(hull). Retract waitedFlood(hull).
  }
  Action take_the_wheel(actor: group, site: place) "Take the wheel and run the gap on the ebb" {
    Description "A ship goes through the gap at six knots or does not go at all. Whoever steers has nothing to do but be right.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, helm) and combsMet(hull) and troubled(hull) and not waitedFlood(hull) and not ranGap(hull) and not decidedCombs(hull).
    Time 2.
    Resolve check(actor, wayfinding, dc_hard).
    On success { Assert ranGap(hull). Assert decidedCombs(hull). Retract troubled(hull). Assert wheelTaken(actor). }
    On failure { Assert ranGap(hull). Assert decidedCombs(hull). Retract troubled(hull). Increase water(hull) by 14. Assert holed(hull). }
    Result "Bascom gives up the wheel with a face gone to wood, and you have the Dorothea under your hands, alive, trembling, wanting to go. The gap opens in front of you like a door in a wall, and the sea runs through it, and the keel scrapes nothing, and then you are through, in green water, in sun, and behind you the Combs go on roaring at nobody. Bascom looks at the pipe in her hand as at something she once agreed to. 'Aye,' she says. It is all she says.".
    Otherwise "The wheel bucks in your hands, and the Dorothea takes a rock on the larboard quarter, and the noise goes up through the soles of your feet. Bascom takes the wheel away from you without a word. She gets the ship through, a hand's breadth at a time, but there is water coming in forward, and the pumps are going before the Combs are out of sight.".
  }
  Action rune_at_the_wheel(actor: group, site: place) "Ask Rune to take her through, as he can" {
    Description "Rune has run the gap eleven times. He has not run it with a company to answer to since he took the Orsett man's money.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, helm) and combsMet(hull) and troubled(hull) and indebted(rune, actor) and not decidedCombs(hull) and not disgraced(rune).
    Time 2.
    On success { Assert ranGap(hull). Assert decidedCombs(hull). Retract troubled(hull). }
    Result "Rune takes the wheel as a man takes a hand that has been offered to him once in his life. He does not look at the Captain. 'Slack's not for an hour,' he says, 'but I've never needed it.' He takes the Dorothea through the gap with her sails drawing and the whole Atlantic of the afternoon pushing at her stern, and at the far end of it Bascom puts down the pipe and says: 'Mr Rune.' Rune says: 'Captain.' Nobody speaks again until the Combs are a white line astern.".
  }
  Action jettison_cargo(actor: group, site: place) "Cut away cargo to lighten her through the gap" {
    Description "A ship rides higher in the water with fewer casks in her. Every cask is a day of the Captain's debt.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and combsMet(hull) and troubled(hull) and not decidedCombs(hull) and cargo(hull) >= 12.
    Time 3.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert lightened(hull). Assert decidedCombs(hull). Retract troubled(hull). Decrease cargo(hull) by 12. }
    Result "Bascom's face works. She has not said she will lose her ship, and she says it now with her hands, by taking the knife off her belt and cutting the first lashing herself. Twelve casks go over the side one after another, and each one makes the same small sound. The Dorothea rises, and rises, and slides through the gap as if the sea had opened her a door.".
    Otherwise "'My cargo,' says Bascom, very low, 'is the only thing on this ship that's mine,' and that is the end of that.".
  }
}

data/adventures/the-dorothea/crew.kyr:
Module dorothea "The Dorothea" {
  Description "The Dorothea's people: a master in debt, a mate who sells what is not his, a cook who sees everything, a boy, a passenger with a measuring-rod; and a night visitor with a cutter.".

  Person rune "Tobias Rune" at deck {
    Role "mate of the Dorothea". Ancestry human. Calling thief. Level 3. Peaceable. Pronouns he. Manner jovial.
    Likeness "sailor".
    Greets "A long man in a patched jersey who looks as if he has been folded up and put away wet. 'Mate,' he says, touching his cap. 'Tobias Rune. Don't mind the Captain, she speaks to the sea and the sea has never answered back. She likes that in a friend.'".
    Greets again "Tobias Rune touches his cap and then, because he has been caught doing it, touches it again as a joke. 'Mind the Captain's mood,' he says. 'It follows the glass, and the glass has been unreliable all week.'".
  }
  Person mab "Mab Hallam" at forecastle {
    Role "cook". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "Mab Hallam stirs a pot the size of a font with a spoon the size of a boat-hook, and has not looked up since you came down the ladder. 'I've fed forty crews on this ship,' she says. 'I've fed three that were hanged and two that were bishops and I couldn't tell you which was which by the manners.'".
    Greets again "Mab Hallam hands you a ladle to hold and does not say what it is for. 'Stand there,' she says. 'If you are going to be in my galley, you can be useful, and if you are going to be useless, you can be warm.'".
  }
  Person nipper "Nipper" at deck {
    Role "ship's boy". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "A boy of about eleven, barefoot on the cold deck, looks you up and down with the frank hostility of someone who has been told a landsman is coming and what will be expected of him.".
    Greets again "The boy has found a spar to lean on and a reason to be on this side of the deck. 'They said landsmen go green by the second day,' he says, unimpressed. 'You're a poor green.'".
  }
  Person quint "Odile Quint" at deck {
    Role "a surveyor of the Collegium of Measures, bound for the Pharos". Ancestry human. Calling mage. Level 2. Peaceable. Pronouns she. Manner stoic.
    Likeness "scholar".
    Joins "Odile Quint closes her pocket-book on a finger, takes her ell-rod under her arm, and falls in at your elbow, a little too close, as someone who measures people measures them.".
    Leaves "Odile Quint nods once. 'I shall be at the Collegium of Measures at Sennet,' she says. 'Ask for the junior Fellow who is always right.'".
    Carries old_glossary.
    Greets "A narrow woman in a grey coat is seated on a cask with a brass ell-rod across her knees, looking not at the sea but at a pocket-book of figures. She does not look up. 'Odile Quint,' she says. 'Collegium of Measures, Sennet. If you're sick, be sick to leeward. If you're not, I'd like a word about your idea of a straight line.'".
    Greets again "Odile Quint has put a second pocket-book beside the first, and the two do not agree with each other. 'A word,' she says. 'Not the straight line. The curved one. Do you know how you measure a thing that bends back on itself?'".
  }
  Initially Assert acceptsEscort(quint, party).

  Topic rune_cargo with rune "Ask Rune how the Dorothea does for money" when true once {
    Says "'Sixty crowns of the Orsett factor's money in her keel, and every penny's got a face on it that looks at the Captain,' says Rune. He laughs without sound. 'You'd think a woman could sell enough salt.' He looks, for just a moment, at the after hatch.".
  }
  Topic mab_rune with mab "Ask Mab what she thinks of the mate" when true once {
    Says "'Rune's the best hand I ever sailed with,' says Mab, 'and I wouldn't leave a spoon where he could see it. He loves her, you know. The Captain. Not that way. The way a dog loves a person that's never once been nice to it.' She tastes the pot. 'He sold two casks of the Pharos oil in Orsett in the spring. She's not counted them yet. When she does I'd sooner be on deck.'".
    On discuss { Assert knows(actor, rune_sells). }
  }
  Discovery rune_sells "The mate, Tobias Rune, has been selling the Pharos's lamp-oil out of the Dorothea's hold, two casks at a time, to make up the Captain's debt before she finds out how deep it is.".
  Topic nipper_gun with nipper "Ask Nipper about the gun" when true once {
    Says "He looks at you for the first time as if you might be worth the bother. 'It's a swivel. Brass. It's under the tarpaulin on the starboard rail and nobody's to touch it but Mr Rune.' He lowers his voice. 'It's fired for the Combs, and for funerals, and once for a bishop. It's not for fighting. The Captain says a gun's not for killing anyone, it's for telling the whole sea you are here.' He scratches his ankle with the other foot. 'I'd like to hear it once when it isn't somebody dead.'".
  }
  Topic quint_rod with quint "Ask Odile Quint what the Collegium wants with the Pharos" when true once {
    Says "'It is a unit,' she says. 'A very good one. Seven feet and some inches of a measure that is not a foot and not a yard, and has its own sixths, and has been the length of the Pharos stair and the width of its door and the height of its lamp for as long as anybody has measured. The Aeneans wrote it on a bronze table in the tower, and thought it was theirs.' She taps the ell-rod. 'I would like to lay mine against it. I would like to know whether we have been using the right one.'".
  }
  Topic quint_pharos with quint "Ask Odile Quint who the Pharos's builders were" when true once {
    Says "She smiles a very small smile. 'You'll hear that Aeneans built it. The Aeneans cut a line over the door and said it was theirs. Have you looked at the joints? I have looked at the joints through a lens. They are better than the Aeneans' best. Whoever made the tower had a measure that was not in use when the Aeneans came, and the Aeneans, to their credit, wrote it down.'".
  }

  // ── The night visitor ───────────────────────────────────────────────────────────────────────────────────────────
  // Jago Pendry's cutter, the Kestrel, does a night's business on this passage as other masters take the air. What the
  // company sees, what it does about it, and who is told, decide what the mate is to the Captain at the Combs.
  Person jago "Jago Pendry" at nowhere {
    Role "master of the cutter Kestrel". Ancestry human. Calling thief. Level 4. Pronouns he. Manner jovial.
    Likeness "sailor".
    Greets "Jago Pendry sits on the Dorothea's rail as if the ship were his and he were merely letting her sail. 'Good evening,' he says. 'Don't get up. I'm only passing the time with Mr Rune.'".
    Greets again "Jago Pendry has moved from the rail to the hatch-cover, which is a different kind of sitting entirely. 'Mr Rune says you are all right,' he says. 'I have always found Mr Rune a poor judge of anyone but himself.'".
  }
  Relation hailed(entity). Relation sold(entity). Relation told(group). Relation bribed(group). Relation shamed(group). Relation looked(group).
  Rule kestrel_hails when at(hull, open_sea) and progress(hull) >= 66 and not hailed(hull) and not troubled(hull)
    says "A light has been following the Dorothea since dusk, low, to leeward. Now it closes. A cutter slides under the lee quarter without a word spoken, a long dark vessel with a mast like a thought, and a man in a good coat steps over the rail and onto your deck as if it were a drawing room. Rune is at the after hatch before anyone has seen him go." {
    Assert hailed(hull). Assert at(jago, deck). Set hailAt(hull) to watch(clock).
  }
  Measure hailAt(entity).
  // Left alone, Pendry takes what Rune sells and goes: the casks are the Captain's loss by morning.
  Rule jago_leaves when at(jago, deck) and watch(clock) >= hailAt(hull) + 24 and not sold(hull)
    says "Jago Pendry finishes his business with the mate, nods to the company as to old acquaintances, and goes back over the rail with two casks on a line. The cutter slides off to leeward, and Rune goes below to count something." {
    Retract at(jago, deck). Assert sold(hull). Decrease cargo(hull) by 4 or to nothing. Assert quiet(hull).
  }
  Relation quiet(entity).
  Observe jago_deck at deck when at(jago, deck) and not sold(hull) "Jago Pendry and Tobias Rune stand together at the after hatch, talking low. Two casks are on the hatch-cover between them, and neither is looking at the casks.".
  Action watch_the_hatch(actor: group, site: place) "Watch what passes at the after hatch" {
    Description "Not hiding. Only being where somebody can be seen to be.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and at(jago, deck) and not looked(actor).
    Time 2.
    Resolve check(actor, insight, dc_easy).
    On success { Assert looked(actor). Assert knows(actor, rune_sells). }
    Result "You watch the two men for as long as it takes to make a cask change hands. Jago hands Rune a purse. Rune hands Jago the cask. Neither of them thinks it is anything but a tender thing between friends. Nipper, on the rail with his back to them, is crying without noise.".
    Otherwise "You watch, and see nothing but two men talking, and one of them is looking back at you.".
  }
  Topic jago_cut with jago "Ask Jago Pendry what he buys" when looked(actor) or knows(actor, rune_sells) once {
    Says "'Whatever a good man sells,' says Jago. 'The Pharos oil is the best on the coast. Clean, no smoke. I pay Rune what Orsett pays and he gets to feel like a rogue and not a thief.' He studies you. 'I'll make you a proposal. You saw nothing, and I saw nothing, and here is eight coin to make the nothing mutual.'".
    On discuss { Assert offered(jago). }
  }
  Relation offered(entity).
  Topic take_cut with jago "Take Jago Pendry's eight coin" when offered(jago) and not bribed(actor) and not shamed(actor) and not told(actor) once {
    Says "He puts the coin in your hand, and for a moment you are in the same trade. 'Sensible,' he says, and goes back over the rail as lightly as he came, with two casks on a line behind him, and the cutter slides back into the dark. In the morning the hold is a little lighter and the Captain, counting, stops one tier short.".
    On discuss { Assert bribed(actor). Increase quantity(actor, gold) by 8. Assert sold(hull). Retract at(jago, deck). Decrease cargo(hull) by 4 or to nothing. }
  }
  Topic tell_bascom with bascom "Tell Captain Bascom what you saw at the after hatch" when (looked(actor) or knows(actor, rune_sells)) and not told(actor) and not shamed(actor) and not bribed(actor) once {
    Says "She hears you out without a word. Then she walks aft along the deck with the unhurried step of a woman who has decided to do the thing she has been putting off. 'Mr Pendry,' she says. 'Mr Rune.' Her voice does not change. Jago is over the rail before she reaches the hatch, with a flourish and no casks. Rune stands where he is. 'Eleven casks,' she says. 'In the spring I made it fourteen. I told myself I'd counted wrong.' She looks at him a long time. 'You will stand your watch. You will not touch the wheel. When we raise Skerrow you will go ashore with your bag.' Rune opens his mouth. 'Don't,' says Bascom, gently, and puts her pipe back between her teeth.".
    On discuss { Assert told(actor). Retract at(jago, deck). Assert disgraced(rune). }
  }
  Relation disgraced(group).
  Topic shame_rune with rune "Take Rune aside and say what you saw" when (looked(actor) or knows(actor, rune_sells)) and not told(actor) and not shamed(actor) and not bribed(actor) once {
    Says "'It isn't what it looks like,' says Rune, and his mouth goes on trying, and then he stops. He looks at Nipper's back. 'It's exactly what it looks like.' He sits down on the hatch-cover. 'She's been good to me,' he says. 'She's been better to me than anyone and I've been robbing her for a year to keep her in the Orsett man's good books, and every cask I sold made it worse.' He puts both hands over his face. 'Tell me what to do.'".
    On discuss { Assert shamed(actor). Assert indebted(rune, actor). }
  }
  Relation indebted(group, group).
  Action unload_casks(actor: group, site: place) "Make Rune and Jago Pendry put the casks back" {
    Description "Pendry is a smuggler and a gentleman. He has no wish to fight on another man's deck.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and at(jago, deck) and shamed(actor) and not sold(hull).
    Time 3.
    Resolve check(actor, intimidation, dc_fair).
    On success { Assert sold(hull). Retract at(jago, deck). }
    On failure { Retract at(kestrel_hands, nowhere). Assert at(kestrel_hands, deck). }
    Result "Rune lifts the first cask back onto his shoulder and carries it to the hatch, and Jago Pendry watches him do it, and watches the company's faces, and does a sum. 'Another time,' he says, with real regret, and steps over the rail. The cutter's light goes out as it left, one thing at a time.".
    Otherwise "Pendry only smiles, and holds out his hand for the purse he has already paid, and Rune cannot give it back because he has already spent it.".
  }

  // If the company pushes and cannot push hard enough, Pendry does not argue. He whistles, and his hands come over the rail
  // with belaying-pins. They can be fought; they can be paid; the Captain can be fetched; or the mate, if he is the
  // company's, can say a word, and they are Rune's old friends.
  Person kestrel_hands "the Kestrel's hands" at nowhere {
    Role "three hard men off the cutter with belaying-pins". Ancestry human. Calling thief. Level 2. Numbers 3. Temperament territorial.
    Warns "Three men are over the rail and on the deck of the Dorothea before anyone saw the cutter's boat. The nearest hefts a belaying-pin, not as a threat but as a sort of punctuation.".
    Comes "The nearest says, 'Don't make it into a thing,' and the belaying-pin comes round in a flat, practised arc.".
  }
  Relation handsPaid(group). Relation handsSent(group). Relation handsBeaten(group).
  // Beaten on the deck, the hands go over the rail with their wounded, and Pendry with them; the casks stay.
  Rule hands_beaten when at(kestrel_hands, deck) and not able(kestrel_hands) and not handsBeaten(party)
    says "The last of them sits down on the hatch-cover with a hand to his head and says, with great fairness, that he has had enough. Jago Pendry steps over the rail without his coat, which Rune picks up, and the cutter's boat takes them off into the dark. The casks are where they were." {
    Assert handsBeaten(party). Assert sold(hull). Retract at(jago, deck). Retract at(kestrel_hands, deck). Assert at(kestrel_hands, nowhere).
  }
  Action pay_the_hands(actor: group, site: place) "Pay the Kestrel's hands eight coin to go back over the rail" {
    Description "It is cheaper than a head. It is also eight coin that will be spent on drink by the next watch.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and at(kestrel_hands, site) and quantity(actor, gold) >= 8 and not handsPaid(actor).
    Time 1.
    On success { Decrease quantity(actor, gold) by 8. Assert handsPaid(actor). Retract at(kestrel_hands, deck). Assert at(kestrel_hands, nowhere). Retract at(jago, deck). Assert sold(hull). Decrease cargo(hull) by 4 or to nothing. }
    Result "The tallest looks at the coin, and at the company, and does a sum his face is not used to doing. 'Eight,' he says. 'For the trouble.' He pockets it with the dignity of a man being paid a fee. They go back over the rail one at a time, and the cutter takes her boat in, and four casks are not in the hold in the morning.".
  }
  Action rune_speaks(actor: group, site: place) "Have Rune speak to the Kestrel's hands, who drank with him in Orsett" {
    Description "He has sold them four casks and a good deal of rum. They like him.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and at(kestrel_hands, site) and indebted(rune, actor) and not handsSent(actor).
    Time 1.
    On success { Assert handsSent(actor). Retract at(kestrel_hands, deck). Assert at(kestrel_hands, nowhere). Retract at(jago, deck). Assert sold(hull). }
    Result "'Davy,' says Rune. 'Pike. Hobb.' He is not loud. 'She has a keel and a debt and one cask less than I have wronged her for. Go home.' There is a short and terrible silence in which three hard men look at a mate they have known for ten years, and at the company he has chosen, and then at each other. 'Aye,' says the one called Davy, with something not quite like shame, and they go.".
  }

  // ── The Dorothea's leaf: the House form on the cabin shelf ──────────────────────────────────────────────────────
  Action read_cabin_ledgers(actor: group, site: place) "Read the ledgers on Bascom's cabin shelf" {
    Description "She is at the wheel. It is her private shelf, and it is also the House's paper.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, cabin) and not at(bascom, cabin) and not leafDorothea(actor).
    Time 2.
    Resolve check(actor, stealth, dc_fair).
    On success { Assert leafDorothea(actor). Increase leaves(actor) by 1. Assert knows(actor, leaf_dorothea_d). }
    Result "A House form, folded in four and soft with handling: the keel, sixty crowns, PLEDGED. Sailing orders, in a clerk's round hand, to call at the House's ports only. To carry no oil to any unleased light. And an instruction in the margin that makes you read it twice: on default of a light, to stand by for salvage. One part in three to the master. Bascom has underlined the last line, once, in pencil, and then rubbed the underlining out.".
    Otherwise "A voice comes down the ladder: 'That is a private shelf.' You have the ledger shut and your hands behind you before she has reached the top of it.".
  }
  Topic bascom_note with bascom "Ask Bascom to show you the House's paper on her keel" when told(actor) or shamed(actor) or wheelTaken(actor) once {
    Says "She takes the pipe out. She goes below, and comes up with a House form folded in four, and puts it in your hand without looking at it. 'I was told it was a keel,' she says. 'Sixty crowns, and a call at the House's ports. I did not read the margin until the night the Mary Ann went. I have read it every night since.' She looks at the grey road. 'I made fourteen casks of oil for the Pharos, once. I carried eight. I have been told which ones to leave at the quay.'".
    On discuss { Assert leafDorothea(actor). Increase leaves(actor) by 1. Assert knows(actor, leaf_dorothea_d). }
  }
}

data/adventures/the-dorothea/entries.kyr:
Module dorothea "The Dorothea" {
  Description "Ways into the Reach other than a fare at the quay: a clerk who needs a crate fetched, a wife with a letter, a black lugger on the coast, a bottle on the harbourmaster's desk, a runaway prentice in the chandlery. Each is a short scene in Tolleth that hands the company to a leg of the archipelago, with a consequence there.".

  Kind dorothea_letter "a wife's letter" is document described "A letter folded small and sealed with a thumb of wax, addressed in a careful hand: JOSS KETTERIDGE, STACK-MAN, THE ANTLERS, TO BE GIVEN HIM AND NOT THE BOOK.".
  Kind dorothea_reply "a stack-man's answer" is document described "A scrap of egg-tray pasteboard written on both sides in pencil, folded, and sealed with a gull's feather. TO DILYS. FROM J.".
  Kind dorothea_bottle "a bottle with a message" is document teaching bottle_read described "A green bottle, stoppered with tarred rag, with a strip of oilskin inside it written on in burnt stick.".
  Discovery bottle_read "The oilskin says: TO THE HARBOUR. THE HOLM'S IRON IS LOOSE AND THE ONES COMING HOME ARE NOT. COME AT LOW WATER. M. OAKE.".
  Relation raidNews(group). Relation raidLanded(group). Relation raidTurned(group). Relation raided(group). Relation bonded(group).
  Relation crateDelivered(group). Relation hired(group). Relation letterTaken(group). Relation pipHome(group). Relation pipReturned(group). Relation bottleTaken(group). Relation replyGiven(group). Relation hobDefies(group).
  Measure raidAt(entity). Measure owesHouse(group).

  // ── (a) A counting-house in Tolleth, waiting on a shipment ──────────────────────────────────────────────────────
  Person latch "Corwin Latch" at taproom {
    Role "clerk of the House of Marchbank, at the Tolleth desk". Ancestry human. Level 1. Peaceable. Pronouns he. Manner jovial.
    Likeness "scholar".
    Greets "A young man with a blue cuff and an inkstand clipped to his belt has taken the best table by the window and spread on it six sheets of the House's paper, none with anything written on it. 'Corwin Latch, Clerk, the Tolleth desk,' he says. 'Do sit. I am waiting for a crate. I have been waiting for a crate since Candlemas. I am told the House is a great deal of money. I find it is mostly waiting.'".
    Greets again "Corwin Latch has a seventh sheet of the House's paper in front of him, and one word on it. 'Crate,' it says. 'I am told that is progress. It is the first word I have been allowed since Candlemas.'".
  }
  Initially Set quantity(latch, gold) to 80.
  Topic latch_crate with latch "Ask Corwin Latch about the crate" when true once {
    Says "'Sulphur,' says Latch. 'Two seasons of it, crated at Ashkeld, three days south-west, and no ship will call, because it is not on the way to anywhere the House sells. A crate with a faded ring on the lid and my number burned in. Bring it to me and the House pays twenty-five crowns on the desk, and I give you twelve against the fare, to have you there at all.' He considers his sheets. 'It is a poor errand. The Factor has not mentioned it in a year. I am the only person in Orsett who remembers that Ashkeld exists.'".
    On discuss { Assert knows(actor, latch_asked). }
  }
  Action latch_advance(actor: group, site: place) "Take the clerk's twelve coin against the fare to Ashkeld" {
    Requires able(actor) and company(actor) and at(actor, site) and at(latch, site) and knows(actor, latch_asked) and not hired(actor).
    Time 1.
    On success { Increase quantity(actor, gold) by 12. Decrease quantity(latch, gold) by 12. Assert hired(actor). }
    Result "He counts it out of a House purse and enters it in a column. 'Advanced against the Ashkeld shipment,' he writes, and his face lights as of a man whose ledger has at last grown a line.".
  }
  Discovery latch_asked "Corwin Latch, clerk of the House at Tolleth, will pay twenty-five crowns for a crate of Ashkeld sulphur with a faded ring on the lid and his number burned into it, and twelve against the fare.".
  Action deliver_crate(actor: group, site: place) "Put the Ashkeld crate on Corwin Latch's table" {
    Requires able(actor) and company(actor) and at(actor, site) and at(latch, site) and holding(actor, dorothea_sulphur_crate) and not crateDelivered(actor).
    Time 1.
    On success { Spend dorothea_sulphur_crate from actor. Increase quantity(actor, gold) by 25. Decrease quantity(latch, gold) by 25. Assert crateDelivered(actor). }
    Result "Latch reads his own number off the lid with something close to reverence. 'Two seasons,' he says. 'Mrs Gantry's will be on the Dorothea's next call.' He pays out twenty-five crowns from a purse that was, you notice, never meant for it. 'I shall tell Orsett,' he says, 'that the House keeps its word. It is an unusual thing to be able to say.'".
  }
  Observe ashkeld_paid at ashkeld_works when crateDelivered(party) "Someone has chalked on the sulphur-house door a new line under the old stencil: SETTLED, TOLLETH DESK. Merrow Gantry has pinned beside it a clerk's receipt in a blue hand, and has put a nail through the corner, twice.".

  // ── (b) A mariner's wife ────────────────────────────────────────────────────────────────────────────────────────
  Person dilys "Dilys Ketteridge" at quay {
    Role "a mariner's wife, whose husband is on the Antlers". Ancestry human. Level 1. Peaceable. Pronouns she. Manner proud.
    Likeness "farmer".
    Greets "A woman in a good shawl gone thin at the edges stands at the end of the quay with her back very straight, reading the notice board though she has plainly read it. She has the look of someone who has been polite to a number of people about a boat. 'You're not sailing for the Antlers,' she says. 'No. You look as though you might. I am Dilys Ketteridge.'".
    Greets again "Dilys Ketteridge has stopped reading the notice board and is reading the water instead, which is worse. 'Any word?' she says, and does not wait for it. 'No. I would have heard. Joss would have made sure of it.'".
  }
  Topic dilys_letter with dilys "Ask Dilys Ketteridge what she is waiting for" when true once {
    Says "'My husband went up the Antlers for the eggs in March,' she says. 'Joss. He's a stack-man; he does a rope that frightens most men. He wrote by the Dorothea at Whitsun. At Lammas, nothing. Since then, nothing.' She takes a folded paper out of the shawl and holds it in both hands. 'I've written him eleven. The House's clerk says the boat is full. Bascom says she will call at the Antlers when she is asked, and nobody has asked, and I am not a woman who asks.' She looks at you. 'I am asking.'".
    On discuss { Give dorothea_letter to actor. Assert letterTaken(actor). }
  }
  Topic dilys_reply with dilys "Give Dilys Ketteridge her husband's answer" when holding(actor, dorothea_reply) once {
    Says "She reads it standing, and her face does not change at all, and then she folds it back along its creases, and sits down on a bollard, which she has not done in front of anyone in eleven weeks. 'He says the ladder broke at Lammas, and the House's man has not a rope to spare. He says there has been a light wanted, and he's been asked to hold his tongue.' She laughs once. 'He's never held it in his life.' She presses eight coin into your hand, her housekeeping, folded in a handkerchief, and will not have it back.".
    On discuss { Spend dorothea_reply from actor. Increase quantity(actor, gold) by 8. Assert replyGiven(actor). }
  }
  Person joss "Joss Ketteridge" at stack_foot {
    Role "stack-man at the Antlers". Ancestry human. Level 2. Peaceable. Pronouns he. Manner jovial.
    Likeness "sailor".
    Greets "A lean man with a rope tied round each ankle and a third round his waist is lying on his back in the guano with his boots up on a rock, looking at the sky. 'Ketteridge,' he says. 'Joss. Don't mind me. I'm not hurt. I'm only not going up that.' He tilts his head at the ladder.".
    Greets again "Joss Ketteridge has turned over, so that the guano is on the other side of him. 'I am not going up that,' he says. 'If you are, you may tell my wife I am a hero. If you are not, you may tell her I am resting.'".
  }
  Topic joss_letter with joss "Give Joss Ketteridge his wife's letter" when holding(actor, dorothea_letter) once {
    Says "He reads it with his lips, slowly, through a face that gets younger by degrees. 'Eleven,' he says. 'She says she has sent me eleven. I've had none.' He sits up. 'They go to the Agent's hammock. I know where.' He writes an answer on a scrap of egg-tray with a pencil end and a great deal of tongue. Then he gets up, and walks to the ladder, and looks at it, and says, 'I'll put the rig back on it. I was told not to. I was told a good many things. Let them write it down.'".
    On discuss { Spend dorothea_letter from actor. Give dorothea_reply to actor. Assert ladderSound(actor). Assert hobDefies(actor). }
  }

  // ── (c) A black lugger on the coast, and the House's price for protection ───────────────────────────────────────
  Person raiders "the Gannet's Widow's boarders" at nowhere {
    Role "two men and a woman off the lugger Gannet's Widow, with cutlasses and a sack". Ancestry human. Calling thief. Level 2. Numbers 3. Temperament territorial.
    Warns "Three people are standing on the pier in a loose half-circle with their backs to the sea. The nearest has a cutlass hanging from her wrist and a face like a clean plate. 'Don't make it a thing,' she says. 'It's only salt.'".
    Comes "The woman with the cutlass lifts it, almost lazily, from her wrist.".
  }
  Topic latch_raid with latch "Ask Corwin Latch about the black lugger the pilots are talking about" when true once {
    Says "'The Gannet's Widow,' says Latch, dropping his voice, which in a taproom is a gesture. 'Black Meg's. She takes salt and sells it back to the people she took it from. She was at the Combs a week ago and is expected at Port Ness before the new moon, because it is the fattest harbour on the Reach and defended by a reeve.' He taps his inkstand. 'The House would protect its own. It has a guard-boat in Orsett. For thirty crowns, in a bond, against your company's good name and a lien on whatever you carry. The House is always glad to be of use.'".
    On discuss { Assert raidNews(actor). Set raidAt(house) to watch(clock) + 150. }
  }
  Action sign_the_bond(actor: group, site: place) "Sign the House's protection bond: thirty crowns, owed" {
    Description "The guard-boat will be at Port Ness when the lugger comes. The bond is a lien on your company, to be redeemed at the Tolleth desk.".
    Requires able(actor) and company(actor) and at(actor, site) and at(latch, site) and raidNews(actor) and not bonded(actor) and not raidTurned(actor).
    Time 2.
    On success { Assert bonded(actor). Assert raidTurned(actor). Set owesHouse(actor) to 30. }
    Result "Latch writes it out fair and turns it for the company's mark. 'You will find the House exactly as grateful as it is exact,' he says. He blots it. 'The guard-boat leaves at the next tide.' It is, you think, a very good price for a very small boat.".
  }
  Action redeem_the_bond(actor: group, site: place) "Redeem the House's bond at the Tolleth desk, thirty coin" {
    Requires able(actor) and company(actor) and at(actor, site) and at(latch, site) and bonded(actor) and owesHouse(actor) >= 1 and quantity(actor, gold) >= 30.
    Time 1.
    On success { Decrease quantity(actor, gold) by 30. Increase quantity(latch, gold) by 30. Set owesHouse(actor) to 0. }
    Result "Latch strikes it through in red. 'Paid,' he writes, and then, because he is a decent young man in an indecent trade, 'with thanks.'".
  }
  Rule raid_lands at ness_quay when raidNews(party) and watch(clock) >= raidAt(house) and not raidLanded(party) and not raidTurned(party) and not raided(party)
    says "A black lugger with a bone in her teeth comes round the end of the pier without a flag, and men and women go over her side into the shallows with the unhurried air of those who have done a thing often. The women on the pier put down their shovels." {
    Assert raidLanded(party). Retract at(raiders, nowhere). Assert at(raiders, ness_quay).
  }
  Rule raid_ends when raidLanded(party) and not raidTurned(party) and not raided(party) and watch(clock) >= raidAt(house) + 30 {
    Assert raided(party). Retract at(raiders, ness_quay). Assert at(raiders, nowhere).
  }
  Observe raided_pier at ness_quay when raided(party) "Three lighters lie burnt to the waterline against the pier, and the salt barn door hangs off one hinge. The women are sweeping salt out of the burnt hulls into sacks. Nobody looks up. A reeve is standing with his arms at his sides.".
  Observe bonded_pier at ness_quay when bonded(party) and raidTurned(party) and not raided(party) "A neat black guard-boat with a key-and-ring on her bow lies at the end of Port Ness pier, two men in the House's grey at her oars, doing nothing at all. Nobody on the pier speaks to them.".
  Topic warn_auld with auld "Warn Dunstan Auld that Black Meg's lugger is coming" when raidNews(actor) and not raidTurned(actor) and not raidLanded(actor) once {
    Says "'Aye,' says Auld. He takes the rake off his shoulder. 'We've done it before.' He puts two fingers in his mouth and whistles, and the rakers stop in a long line down the dams. By evening there are two hundred of them at the pier in their rag gloves with their rakes, and every lighter has a line of white-handed women sitting along its gunwale. 'She'll not land on that,' he says. 'She'll count it, and sail on.'".
    On discuss { Assert raidTurned(actor). }
  }
  Action parley_raiders(actor: group, site: place) "Parley with the woman with the cutlass" {
    Requires able(actor) and company(actor) and at(actor, site) and at(raiders, site) and not raidTurned(actor).
    Time 2.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert raidTurned(actor). Retract at(raiders, site). Assert at(raiders, nowhere). }
    Result "You say that the pier is the House's, and that the House has a guard-boat in Orsett, and that you have the reeve behind you, and that salt is cheap compared to what a hanging costs. She looks at you for a while with her head on one side. 'Four sacks,' she says. 'From the top of the heap, where it's dry.' They take four sacks. The lugger goes out on the ebb with her sails the colour of a rotten tooth.".
    Otherwise "'I didn't get to be Meg's mate,' she says, 'by being talked to.'".
  }
  Rule raid_beaten when at(raiders, ness_quay) and not able(raiders) and not raidTurned(party) { Assert raidTurned(party). }

  // ── (d) A bottle on the harbourmaster's desk ────────────────────────────────────────────────────────────────────
  Topic dacey_bottle with harbourman "Ask Dacey Hoe about the bottle on her desk" when true once {
    Says "'Cast up on the strand at the spring tide,' says Dacey Hoe. 'Salvage is the finder's, and the finder's a boy who has gone to sea. I have no authority to open another man's bottle, so I have not.' She has plainly not read it eleven times. 'The oilskin says the Holm. The Holm is a mile out past Port Ness and nobody lives on it but a widow who is paid not to be there. If you are going that way, you may say it was handed to you.'".
    On discuss { Give dorothea_bottle to actor. Assert bottleTaken(actor). }
  }
  Topic marit_bottle with marit "Give Marit Oake the bottle" when holding(actor, dorothea_bottle) once {
    Says "She turns it over in the lamp of the door. 'The night the Rosa Lind went,' she says. 'I put it in the water myself. I never thought it would go anywhere but down.' She holds it a while longer. 'Since Lammas. I thought it was in the bar with the rest. And now somebody has brought it back.' She sets it on the sill. 'The stand,' she says. 'You'll be wanting to see the stand. The iron is loose. It always was.'".
    On discuss { Spend dorothea_bottle from actor. Assert maritWilling(actor). }
  }

  // ── (e) A runaway ───────────────────────────────────────────────────────────────────────────────────────────────
  Person pip "Pip Vosper" at shop {
    Role "a runaway prentice of the House, eleven, from the Antlers". Ancestry human. Level 1. Peaceable. Pronouns he. Manner stoic.
    Joins "Pip Vosper takes a coil of rope off the pile, sets it on his shoulder like a man and falls in at your elbow, a pace behind, looking at the sea.".
    Leaves "Pip nods once, to nobody. 'I'll be all right here,' he says, in a voice that does not say so.".
    Greets "Behind the coils of rope at the back of Garrick's, between a keg of tar and the wall, a boy of about eleven in a grey cuff is sitting with his knees up and an unlit candle in his hand, quite still. 'Not a word,' he says. 'Please. I'm bound to the House seven years and I've done three and I want my mother, and they'll send me to the Ness, which is the other way.'".
    Greets again "Pip Vosper has moved the candle from one hand to the other. 'Not a word,' he says. 'You've not told? I did not think you had. I have begun to think you will not, and I do not know what to do with that.'".
  }
  Initially Assert acceptsEscort(pip, party).
  Topic pip_mother with pip "Ask Pip Vosper where his mother is" when true once {
    Says "'The Antlers,' says Pip. 'She's Hob Sedge's sister. I was bound to the House to pay her debt in flour. She's not paid it, the House says, because it keeps the flour on the book at its own price.' He turns the candle over. 'There's a man at the taproom with a blue cuff who's put up five crowns to anyone who brings me back. I'd go myself, if I knew the way. I don't, and I've no fare.'".
  }
  Topic latch_pip with latch "Tell Corwin Latch where the runaway is, for the House's five coin" when knows(actor, pip_seen) and not pipReturned(actor) and not pipHome(actor) once {
    Says "Latch is up in a moment, the chair going over behind him. 'Where?' he says. And then, hearing himself, sits down again. 'The House,' he says, 'does not like to lose a prentice. It likes still less to be seen to lose one.' He counts five crowns out. 'Garrick's, you say. Thank you.' He does not look pleased. He looks like a man given a thing to do that he would rather not have been able to do.".
    On discuss { Increase quantity(actor, gold) by 5. Assert pipReturned(actor). Retract at(pip, shop). Assert at(pip, nowhere). }
  }
  Discovery pip_seen "In Garrick's chandlery, behind the coils of rope, a boy of eleven in a House prentice's grey cuffs is hiding from the Tolleth desk.".
  Observe pip_found at shop when true "At the back, between a keg of tar and the wall, there is a place where the rope has been moved to make a nest." teaches pip_seen.
  Topic hob_pip with hob "Bring Pip Vosper to Hob Sedge" when following(pip, party) and not pipHome(party) once {
    Says "Hob Sedge looks at the boy, and the boy at Hob, and nobody speaks. Then Hob picks him up, boots and all, and holds him against his chest like a bundle of sticks, and the guano comes off the boy's boots onto his coat and he does not notice. 'The House says seven years,' he says at last, over Pip's head. 'The House can say it to me.' He puts him down, and takes the rope off his waist, and looks at the stack. 'Clause seven is the House's, and it's the Antlers' too, and when the Antlers' headman gives leave, that's a thing that's been done. You'll light it. I'll stand under it.'".
    On discuss { Assert pipHome(actor). Assert hobDefies(actor). Assert cressetFree(actor). }
  }
}

data/adventures/the-dorothea/holm.kyr:
Module dorothea "The Dorothea" {
  Description "Wrack Holm: a hump of black rock a mile out across the Ness flats, reached by a drowned causeway for five hours in twelve, with the stump of an older lamp upon it and a widow who has been paid for twenty years to leave it dark.".

  Place holm "Wrack Holm" is wilderness within portness at 3, 0.
  Place holm_beach "the Holm's beach" is room within holm at 0, 0.
  Place holm_stump "the lamp-stump" is room within holm at 1, 0.

  // The tide is a number the clock keeps: twelve hours round, seventy-two watches, and the causeway is dry for the five
  // hours (thirty watches) in the middle of the ebb. Anyone on the Holm when it closes waits for the next.
  Entity tide: scenery "the tide over the Wrack Road.".
  Measure phase(entity).
  Rule tide_runs when true { Set phase(tide) to watch(clock) - watch(clock) / 72 * 72. }
  Passage wrack_road "the Wrack Road" is causeway between ness_strand and holm_beach
    opening when phase(tide) >= 30 and phase(tide) < 60 "The Wrack Road is under green water, the black stones showing a little in the troughs, and a line of weed on the top of the swell. It will be out again in a few hours; the gauge on the wall says when.".
  Passage stump_door "the stump's low door" is door between holm_beach and holm_stump.

  Observe holm_beach_scene at holm_beach when true "The Holm: black rock, a beach of broken shell, a drift-line of rope and planking a man could build a house from. It is built from. A boat's ribs stand up out of the sand like a hand. Everything is wet, and everything is arranged.".
  Observe holm_stump_scene at holm_stump when not lampLit(lamp_holm) "The stump: the bottom three men's heights of a round tower of black stone, fitted without mortar, the top of it broken off level. A stove and a hammock in the base, a iron lamp-stand in the middle of the floor as tall as a child with nothing on it, and on the stand's foot, when you kneel, a fish with a flame over it, cut in the iron, and filled with rust.".
  Observe holm_stump_lit at holm_stump when lampLit(lamp_holm) "The stump has a light in it again. It stands on the iron, in the broken top of the tower, a hard small flame that does not seem to mind the wind. Marit Oake sits under it with her knitting and does not look up. It is not that she has stopped looking.".

  Person marit "Marit Oake" at holm_stump {
    Role "widow, paid by the House to keep the Holm". Ancestry human. Level 2. Peaceable. Pronouns she. Manner proud.
    Likeness "farmer".
    Greets "A woman of sixty with a gull on her shoulder and a net half knitted on her knee does not get up. 'Mind the step,' she says. 'It has had worse than you.' She looks at you for a while the way a person looks at the sea to see which of its moods it is in. 'You came across the Wrack Road. Most don't. They think they have time.'".
    Greets again "Marit Oake lifts the gull off her shoulder and puts it on the net, where it sits, offended. 'You are back,' she says. 'Most are not. The sea gets a few, and the Holm gets the rest, and I do not always know which of us is the kinder.'".
  }
  Relation maritWilling(group). Relation raftLantern(group).
  Topic marit_rent with marit "Ask Marit Oake what the House pays her for" when true once {
    Says "'Four crowns the quarter,' she says, 'for the Holm. It was for my husband, before; he was a wrecker, God rest him, and the House bought him off the trade with a rent, and when he went the rent came to me.' She does not say it with shame. 'The rent's for no light. That is on the paper. The Holm is to show no light, the stump is to be left cold, and I'm to keep the beach clear of any who'd come to put one on it. I've kept it clear for twenty years.' She strokes the gull. 'You'll have seen the weed on the bar, from the Ness. I don't look at it any more.'".
  }
  Topic marit_stand with marit "Ask Marit Oake about the lamp-stand" when true once {
    Says "'Older than the tower, they say. Older than the stump, I'd say, if you've a mind to say. There was a lantern on that iron once. It went out on the tide one winter on a raft of casks, with a board nailed to it, and a good many people have claimed to see it since.' She shrugs. 'People claim a lot, near the Wrack Road.' She taps the iron. 'It would take a clean oil to light it. Not tallow; there's a reason this one went out. The Dorothea carries a white oil up from Skerrow, or used to.'".
  }
  Topic quint_holm with quint "Ask Odile Quint to read the device on the lamp-stand" when at(actor, holm_stump) once {
    Says "Quint kneels with her ell-rod across her knees and wipes the rust with a thumb. 'The same mark,' she says. 'As the Pharos keystone. As the Gull's paper. A fish, and a flame over it.' She is quiet for a moment. 'There is a line cut round the foot, in the old imperial, and the salt has had most of it. I can give you two words and I would not swear to the second.' She stands up and puts her knees back where they belong. 'I would not have it taken for scrap.'".
  }
  // The Holm's problem: a light, a widow, and a rent. Marit must be willing, and the stump must be fuelled.
  Action argue_marit(actor: group, site: place) "Tell Marit Oake what the stump was for, and ask her to let it be lit" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, holm_stump) and houseHolds(lamp_holm) and not maritWilling(actor).
    Time 3.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert maritWilling(actor). }
    Result "You say it badly and plainly. She listens with the gull's beak at her ear. 'My man built wrecks,' she says. 'He didn't build lights. And he'd be the first to say so.' She looks at the stand. 'The rent is four crowns. The Rosa Lind was forty-one hands.' She puts down the knitting. 'Light it, then. I'll not stop you.' She looks at the empty iron. 'It wants oil that burns clean. Fish and tallow would only make it a thing to be put out. There is a white oil goes up and down this coast in the Dorothea. Ask where it is kept.'".
    Otherwise "'The rent is four crowns,' says Marit Oake, 'and I am sixty.' She goes on knitting. She is not unkind.".
  }
  Action pay_marit_rent(actor: group, site: place) "Pay Marit Oake six coin against the House's rent, so that she need not be paid for the dark" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, holm_stump) and houseHolds(lamp_holm) and not maritWilling(actor) and quantity(actor, gold) >= 6.
    Time 1.
    On success { Decrease quantity(actor, gold) by 6. Increase quantity(marit, gold) by 6. Assert maritWilling(actor). }
    Result "She counts the six coin into a tin that once held tea. 'That is a year and a bit of the House's money,' she says, 'at the other price.' She shuts the tin. 'Light it.'".
  }
  Action show_marit_lantern(actor: group, site: place) "Show Marit Oake the lantern from the raft" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, holm_stump) and houseHolds(lamp_holm) and not maritWilling(actor) and holding(actor, lantern) and raftLantern(actor).
    Time 1.
    On success { Assert maritWilling(actor). }
    Result "She takes it in both hands. She turns it, and finds the ring on its top, worn bright by a hand she cannot have known. 'That is the Holm's,' she says. 'It is the Holm's.' The gull moves to the other shoulder. 'Don't ask me how it came to be on a raft. Put it back.'".
  }
  Action oil_the_holm(actor: group, site: place) "Fill the stump's lamp-stand from a keg of the Pharos's oil, and light it" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, holm_stump) and houseHolds(lamp_holm) and maritWilling(actor) and holding(actor, dorothea_oil_keg).
    Time 4.
    On success { Spend dorothea_oil_keg from actor. Retract houseHolds(lamp_holm). Assert lampLit(lamp_holm). Increase freed(actor) by 1. }
    Result "You set the iron lamp on the stand and fill it, and Marit Oake strikes the light herself. It takes the third try. She stands with her hands cold on the stand and says nothing for as long as she likes.".
  }
  Action set_the_lantern(actor: group, site: place) "Set the raft's lantern on the stand where it came from" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, holm_stump) and houseHolds(lamp_holm) and maritWilling(actor) and holding(actor, lantern) and raftLantern(actor).
    Time 2.
    On success { Spend lantern from actor. Retract houseHolds(lamp_holm). Assert lampLit(lamp_holm). Increase freed(actor) by 1. }
    Result "The lantern sits on the iron as if it had never been off. The flame stands up straight in the draught from the door. Marit says nothing at all, and presently the gull begins, quietly, to preen.".
  }
}

data/adventures/the-dorothea/house.kyr:
Module dorothea "The Dorothea" {
  Description "The House of Marchbank, of Orsett: salt, carriage and assurance on the Reach, and a ground-rent on every light. Its ranks, its ledgers read in pieces, its leverage on each island, and the ways a company may answer it.".

  // ── What the House is ───────────────────────────────────────────────────────────────────────────────────────────
  // A counting-house in Orsett whose mark is a key and a ring. Five ranks, each with a colour of binding, learnt by
  // travelling: Prentice (grey, keeps an island's day-book), Clerk (blue, copies it to the ledger), Agent (green, keeps
  // a post), Factor (red, keeps a coast), Principal (black, keeps the seal). It holds the landing at Skerrow, the pans
  // at Port Ness, the harvest at the Antlers, the carrying (the Dorothea's keel is its note), and a LUM. column: the
  // lease of every kept light on the Reach, left dark, and under each dark light a W.R. column: wreck-rights, which
  // fall to the House in default of a light. The Pharos is the last big one lit, and is pending.
  Entity house: group "The House of Marchbank, of Orsett.".
  Entity lamp_ness: fact "The Ness Light.". Entity lamp_antlers: fact "The Antler cresset.". Entity lamp_holm: fact "The Holm stump.". Entity lamp_pharos: fact "The Pharos.".
  Relation houseHolds(entity). Relation lampLit(entity).
  Initially Assert houseHolds(lamp_ness). Initially Assert houseHolds(lamp_antlers). Initially Assert houseHolds(lamp_holm).
  Measure freed(group). Measure leaves(group).
  Relation marked(group). Relation houseExposed(group). Relation reckoned(group). Relation silenced(group).
  Relation leafNess(group). Relation leafAntlers(group). Relation leafSkerrow(group). Relation leafDorothea(group). Relation leafTolleth(group).
  Measure holdUntil(entity). Initially Set holdUntil(hull) to 0.

  Kind dorothea_oil_keg "a keg of the Pharos's oil" is gear worth 8 weighing 2 described "A small keg of clean lamp oil, bunged with a plug of wax, the stave-heads burned with nothing at all: no key, no ring. It smells of nothing, which is how you know.".
  Kind dorothea_copy "a copy of the House's leaves" is document teaching house_plan described "Five sheets in your own hand, copied from five ledgers, with the same three marks recurring in the margin: LUM., W.R., and a small key-and-ring.".

  // ── Ledgers, read in pieces ─────────────────────────────────────────────────────────────────────────────────────
  Discovery leaf_ness_d "In the Port Ness day-book, in the blue clerk's hand: SALT, 4,100 SACKS, CONSIGNED TO THE ACCOUNT. And in a separate column headed LUM.: NESS LIGHT, KEEPER'S BOND, SKAIL, DEBIT 18 CR., BOOK CLOSED AT LAMMAS, OIL NIL. THE HOLM, RENT TO OAKE 4 CR. THE QUARTER, FOR NO LIGHT. And under W.R.: ROSA LIND, HOLM BAR, SALVAGE TAKEN 212 CR." {
  }
  Discovery leaf_antlers_d "In the Antlers' day-book, a child's careful hand: DOWN, 90 STONE. EGGS, 11 GREAT HUNDRED. LUM.: THE CRESSET, LEASE OF THE STACK, CLAUSE 7, NO FIRE UPON THIS STACK WITHOUT THE HOUSE'S LEAVE. RENT ARREARS 15 CR. AGENT TO SEND TO FACTOR: BOOK ONE. (BOOK TWO IS THIS ONE.) W.R.: TERN, THE RACE, TAKEN 160 CR." {
  }
  Discovery leaf_skerrow_d "In Silas Quillon's green ledger: SKERROW, THE LANDING, A THIRD. LUM.: THE PHAROS. PENDING. BRONZE, TABLE AND REFLECTOR, TO BE CLEARED BY MARTINMAS ON THE PRINCIPAL'S ORDER, 'THE LAMP ROOM TO BE LEFT EMPTY'. LIGHTS IN HAND: NESS, ANTLERS, HOLM. OUTSTANDING: ONE. W.R.: MARY ANN, THE COMBS, LAMMAS." {
  }
  Discovery leaf_dorothea_d "On the shelf in Bascom's cabin, a House form: DOROTHEA, KETCH, KEEL ADVANCED 60 CR., PLEDGED. SAILING ORDERS: CALL AT THE HOUSE'S PORTS ONLY. CARRY NO OIL TO ANY UNLEASED LIGHT. AT THE COMBS OR THE RACE, ON DEFAULT OF A LIGHT, STAND BY FOR SALVAGE. W.R.: AS FOLLOWS, IN SUCH CASE, 1 PART IN 3 TO THE MASTER." {
  }
  Discovery leaf_tolleth_d "In Dacey Hoe's ledger of sailings, a second column nobody reads: PREM., the House's premiums on every hull that clears; and beside it W.R., the hulls that did not. Eleven names this year. Against each: SALVAGE IN DEFAULT OF A LIGHT, THE HOUSE'S. Against nine of them, in the margin, in pencil: NO LIGHT." {
  }
  Discovery house_plan "The House of Marchbank leases the kept lights of the Reach and does not light them; it holds, under each dark light, the wreck-rights; the Pharos is the last big one lit, and the House has been sent to take it.".

  // Reading a leaf is done where the leaf is: at the counting-room (Pym), the day-book (Wick Bligh), the Gull (Quillon),
  // the cabin shelf (Bascom), the harbourmaster's ledger (Dacey Hoe). Each is a different small hazard. Three, of any
  // five, are enough to see the pattern.
  Action reckon_leaves(actor: group, site: place) "Lay the House's leaves side by side and sum them" {
    Description "Three or more, from different hands, with the same columns in the margin.".
    Requires able(actor) and company(actor) and at(actor, site) and leaves(actor) >= 3 and not reckoned(actor).
    Time 4.
    On success { Assert reckoned(actor). Give dorothea_copy to actor. Assert knows(actor, house_plan). }
    Result "You lay them on the hatch-cover and weigh the corners with a belaying-pin, a boot and a mug. The columns do not agree: one says SALT, one EGGS, one SULPHUR, one the price of a keel. The margins agree. LUM., LUM., LUM., and beside each a W.R. with a sum, and when you run a thumb down the W.R. column every figure is dated the week its light went dark. Nobody wrecked a ship. Somebody held the lease on the lamp that would have saved her, and left the wick as it was. Under the last leaf, in pencil, a pin on a chart at Port Ness, loose on the sill, has been marked WAITING. You copy the lot out fair on the back of a sailing bill, because the pencil is going to be wanted.".
  }

  // ── Ranks, as a Prentice tells them ─────────────────────────────────────────────────────────────────────────────
  // (Pym tells them at Port Ness; Wick Bligh at the Antlers; Quillon, who is an Agent, tells them less kindly.)

  // ── Answering the House ─────────────────────────────────────────────────────────────────────────────────────────
  // Expose it: the reckoning before the harbourmaster at Tolleth, who will chalk it on the board and send it to the
  // Pilots' Bench. The House answers by holding the Dorothea on a bailiff's order for two days (holdUntil).
  Topic hoe_expose with harbourman "Lay the House's reckoning before Dacey Hoe" when reckoned(actor) and not houseExposed(actor) and not silenced(actor) once {
    Says "Dacey Hoe reads the copy through, once, with her mouth getting thinner. Then she turns the ledger of sailings to its second column and puts a finger on it, as if she were pinning something. 'I collected these,' she says. 'Eleven years. I never read the right hand.' She takes the chalk from behind her ear. By noon the board outside has a new line under LOST THIS YEAR: NO LIGHT, NO PREMIUM. THE HOUSE OF MARCHBANK'S LEASES, OPEN TO READING AT THIS OFFICE. A copy goes to the Pilots' Bench by the Wednesday boat. 'They'll come for the Dorothea,' she says. 'It is what they have. Bascom will be held on the quay.'".
    On discuss { Assert houseExposed(actor). Set holdUntil(hull) to watch(clock) + 288. Assert cressetFree(actor). }
  }
  Observe board_exposed at quay when houseExposed(party) "The board under LOST THIS YEAR has a new line in Dacey Hoe's square hand: NO LIGHT, NO PREMIUM. THE HOUSE OF MARCHBANK'S LEASES, OPEN TO READING AT THE HARBOURMASTER'S. A knot of pilots stands reading it with their hats on. Somebody has rubbed the key-and-ring off the foot of every sailing.".
  Observe board_freed at quay when freed(party) >= 2 and not houseExposed(party) "Under LOST THIS YEAR the fourth line has been rubbed out again, and nobody has begun it. Someone has chalked a small flame beside the Antlers.".

  // The Pharos is the fourth light. It is kept if the lamp was not sold; that is counted here, whichever way it came.
  Relation pharosCounted(group).
  Rule pharos_kept_counts when keptLamp(party) and not pharosCounted(party) and not lampOut(party) { Assert pharosCounted(party). Increase freed(party) by 1. }

  // ── The Principal, at the quay, when it is known ────────────────────────────────────────────────────────────────
  Person principal "Josselin Marchbank" at nowhere {
    Role "Principal of the House of Marchbank". Ancestry human. Level 4. Peaceable. Pronouns he. Manner stoic.
    Likeness "merchant".
    Greets "A tall old man in a black coat stands at the foot of the notice board, reading it as one reads a bill one has already paid. He has no ledger in his hand: only a seal on a chain, a key and a ring. 'Josselin Marchbank,' he says. 'You have been reading my books, in pieces. It is the usual way people read them.'".
    Greets again "Josselin Marchbank has read the notice board again, and gives the impression of being very slightly disappointed in it. 'You have read more,' he says. 'You will have found that my books are a story. I have never denied it. I only dispute the ending.'".
  }
  Relation principalMet(group).
  Rule principal_comes when reckoned(party) and at(party, quay) and not principalMet(party)
    says "A man in a black coat has come down the Orsett road with a clerk and a stick, and stands at the foot of the notice board with his hands behind him." {
    Assert principalMet(party). Retract at(principal, nowhere). Assert at(principal, quay).
  }
  Topic marchbank_lights with principal "Ask Josselin Marchbank why the House leases lights it does not light" when true once {
    Says "'A lit coast needs no pilot,' he says. 'No assurance. No salvage. A free light is a hole in a market, and I have been filling it for thirty-one years.' He turns the seal on its chain, once round, as another man turns a ring. 'I have never wrecked a ship. Put that in your copy, if you must have a line of mine.'".
  }
  Topic marchbank_offer with principal "Hear what Josselin Marchbank offers for the copy" when true once {
    Says "'Forty crowns,' he says. 'Or the Dorothea's note struck off. Or a clerkship at Orsett for whichever of you writes the fairest hand.' He does not raise his voice for any of the three. 'Choose before the tide turns.'".
  }
  Action take_silver(actor: group, site: place) "Take the Principal's forty crowns for the copy" {
    Requires able(actor) and company(actor) and at(actor, site) and at(principal, site) and holding(actor, dorothea_copy) and not silenced(actor).
    Time 1.
    On success { Increase quantity(actor, gold) by 40. Spend dorothea_copy from actor. Assert silenced(actor). Retract at(principal, quay). Assert at(principal, nowhere). }
    Result "Marchbank counts it out himself, forty crowns, as a man pays a debt he does not think he owes. He folds the copy into his coat. 'Forty,' he says. 'Counted twice.' He does not say thank you; the House does not.".
  }
  Action press_principal(actor: group, site: place) "Tell him the copy is also with Dacey Hoe, and the Pilots' Bench" {
    Requires able(actor) and company(actor) and at(actor, site) and at(principal, site) and houseExposed(actor) and not silenced(actor) and not principalLeft(actor).
    Time 1.
    On success { Assert principalLeft(actor). Retract at(principal, quay). Assert at(principal, nowhere). Set holdUntil(hull) to watch(clock). }
    Result "Marchbank looks at the board, and at the pilots with their hats on, and at the clerk, who has turned the colour of paper. 'Ah,' he says. 'So.' He puts the seal back inside his coat, and for a moment he looks his age. 'The Dorothea is free to sail,' he says. 'You will find the House is not at all as large as it was this morning.' He goes up the Orsett road with his stick, and the clerk after him, carrying nothing.".
  }
  Relation principalLeft(group).

  // ── Aims the page can lead with ───────────────────────────────────────────────────────────────────────────────────
  Objective dark_light_plan when knows(party, house_plan) and not keptLamp(party) and not marlSold(party) and not lampOut(party)
    "The House of Marchbank leases the kept lights of the Reach and does not light them. The Pharos is the last big one lit, and is pending.".
  Objective rune_oil when knows(party, rune_sells) and not keptLamp(party) and not marlSold(party) and not lampOut(party)
    "The mate of the Dorothea has been selling the Pharos's lamp-oil out of the hold, two casks at a time, to make up the Captain's debt.".
}

data/adventures/the-dorothea/lamp.kyr:
Module dorothea "The Dorothea" {
  Description "The Lamp Below: what the Pharos is the chimney of. A stair under the oil store, a keepers' gate, a hall of turning brass, a gallery where two centuries of argument are chalked on the wall, and a well at the bottom with an engine in it that has been counting since before the roads. Three acts, a Governor, five ways past it. Level five to seven in its dangers, and a way round each.".

  // The Pharos is the chimney of a lamp-engine of the Mathematical Age; the Aeneans found it, learned to start it, fenced it
  // and wrote law about it. Its plaque is their claim to have built it, and is to be read as their claim.
  // ── The way down: shut by a seal while the ring stood ──────────────────────────────────────────────────────────────
  Place oil_store "the oil store under the tower" is room within pharos_site at 0, 1.
  Place lamp_below "the Lamp Below" is site within skerrow at 3, 0.
  Place lb_head "the foot of the trap stair" is room within lamp_below at 0, 0.
  Place lb_stair "the black stair" is room within lamp_below at 0, 1.
  Place lb_gate "the keepers' gate" is room within lamp_below at 0, 2.
  Place lb_ledge "the ledge over the wheel-floor" is room within lamp_below at 1, 2.
  Place lb_far "the far side of the wheel-floor" is room within lamp_below at 2, 2.
  Place lb_crawl "the tally-crawl" is room within lamp_below at 1, 3.
  Place lb_gallery "the keepers' gallery" is room within lamp_below at 2, 3.
  Place lb_well "the lens-well" is room within lamp_below at 3, 3.
  Passage oil_door "the oil store door" is door between pharos_foot and oil_store.
  Passage trap_stair "the trap in the oil store floor" is stair between oil_store and lb_head
    opening when ringFallen(party) "A trap, two planks wide, in the oil store's floor, under a hasp and a House padlock with a key and a ring cut in it. Marren Kestle will not so much as look at it. 'A seal is only brass that everyone has agreed to be afraid of,' she said when you asked. 'And that one is the ring's. A Kestle doesn't cross the ring.'".
  Passage lb_down "the black stair" is passage between lb_head and lb_stair.
  Passage lb_gateway "the last turns of the stair" is passage between lb_stair and lb_gate.
  Passage lb_wheel_way "across the wheel-floor" is bridge between lb_ledge and lb_far
    opening when crossed(party) "Between the ledge and the far side, brass wheels the width of cartwheels turn in the dark, edge to edge, each tooth as long as a forearm. There is no floor that does not move.".
  Passage lb_to_ledge "through the gate" is gate between lb_gate and lb_ledge
    opening when gateWays() "The keepers' gate is shut: two leaves of black bronze, closed on a lock of their own.".
  Passage lb_crawl_in "the tally-crawl" is crawl between lb_gate and lb_crawl
    opening when count(memberOf(?m, party)) == 1 "A crawl-hole, a hand high at the knee and no wider than a pair of shoulders, goes in at the foot of the gate-wall. A company would not fit it, nor all of one.".
  Passage lb_crawl_out "the tally-crawl, out" is crawl between lb_crawl and lb_gallery.
  Passage lb_far_gallery "the gallery arch" is arch between lb_far and lb_gallery.
  Passage lb_gallery_well "down to the lens-well" is passage between lb_gallery and lb_well.

  Observe lb_oil_scene at oil_store when not ringFallen(party) "Kegs on their sides in cradles, a lead pipe as thick as a wrist going down through the floor, and in the floor a trap, bolted, with a House padlock on the hasp. The oil in the kegs smells of nothing at all.".
  Observe lb_oil_open at oil_store when ringFallen(party) "Kegs in their cradles, a lead pipe as thick as a wrist going down through the floor, and in the floor a trap with its hasp cut. The padlock lies on the boards, key and ring uppermost, with a dent in it from the trimming-knife. A smell of cold air comes up, and under it a smell of warm brass.".
  Rule seal_cut at oil_store when ringFallen(party) and at(party, oil_store) and not sealCut(party)
    says "Marren Kestle has come down behind you with her grandfather's grandfather's trimming-knife. She puts the point under the hasp and leans, and the House's padlock drops into the dust like a dead bird. 'There's a stair under this tower,' she says, to the hole and not to you. 'I was told about it when I was nine. Every autumn for thirty years I've carried oil to the top of it, and I have never once gone down to see what I was feeding.'" {
    Assert sealCut(party).
  }
  Relation sealCut(group). Relation crossed(group). Relation gateRead(group). Relation brakeThrown(group). Relation governorRests(group). Relation pilotLit(group). Relation oswinOut(group).
  Relation stopSaid(group). Relation lbDone(group).

  // ── Act I: the stair and the gate ─────────────────────────────────────────────────────────────────────────────────
  Observe lb_head_scene at lb_head when true "A stair-head cut out of the living rock, no wider than the trap, warm: warmer than a cellar has any right to be. Whale oil and brass and, under it, a very slow tick, one to a breath, like a clock that is not hurrying. A lead pipe comes down through the ceiling and goes on down with the stair.".
  Observe lb_stair_scene at lb_stair when true "The stair goes down in a left-hand spiral cut from black stone, each step worn into a shallow dish on the inner edge and not on the outer: the whole of it has been walked down by people who did not much mind where they put their feet, and up by people who did. On the wall, scratched at the height of a hand, names. They go all the way down. The last one is a girl's.".
  Observe stair_coins at lb_stair when true "In a niche on the third turn, a drift of small copper has built up the way snow drifts: coins of nine reigns, a button, a milk-tooth, a ribbon. Everyone who has gone down has left one. The drift has a hollow in its crown where the last coin went in, and the hollow is still bright.".
  Action leave_a_coin(actor: group, site: place) "Leave a coin in the drift on the third turn" {
    Description "Everyone who has gone down has left one. Nobody can say why.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lb_stair) and quantity(actor, gold) >= 1 and not coinLeft(actor).
    Time 1.
    On success { Decrease quantity(actor, gold) by 1. Assert coinLeft(actor). }
    Result "The coin goes into the hollow in the crown of the drift with a small clear ring, and the drift takes it. It is not nothing. It is the kind of thing that is worth exactly one coin.".
  }
  Observe lb_coin_on_the_way_up at lb_head when coinLeft(party) and lbDone(party) "Behind you, down the stair, a coin you left is in the drift where the last one was, and the hollow in the crown of it is bright again.".
  Observe lb_light_above at lb_head when lbDone(party) "The stair-head is warm at your back. Above, in the square of the trap, is the first light you have seen in hours that did not come off brass.".
  Observe lb_gate_tick at lb_gate when true "Here the tick is loud enough to count by, and slower than your pulse. After a minute you notice that you have begun to breathe to it.".
  Observe lb_gate_scene at lb_gate when true "The keepers' gate: two leaves, closed, the bronze gone black as an old pan. A fish and over it a flame are inlaid in the leaves in a green metal that has not tarnished, and under them a plate of numerals in two columns, one of them scrubbed to a shadow. A draught comes out from under the gate, smelling of warm oil.".
  Rule voice_stair at lb_stair when at(party, lb_stair) and memberOf(?m, party) and brings(?m, woodcraft) and awake(?m) and not vStair(party)
    says "{?m} goes down three turns and stops with a hand on the wall. 'The steps are worn on the inside edge,' {?m} says. 'That is somebody going down quickly with a load on the outer arm. Oil, in a can. Every year.' {?m} looks up the stair. 'And up on the outside, slowly. Somebody whose knees were going. The same pair of knees, I think. Thirty years of them.'" {
    Assert vStair(party).
  }
  Relation vStair(group). Relation vGate(group). Relation vTeeth(group). Relation vOffice(group). Relation vHip(group). Relation vTally(group).
  Rule voice_gate at lb_gate when at(party, lb_gate) and memberOf(?m, party) and brings(?m, lockwork) and awake(?m) and not vGate(party)
    says "{?m} runs a thumb down the left leaf and stops at the seam. 'Two locks,' {?m} says. 'The one on the face is for show: it takes a number, and people will stand here an hour with a number. The real one is under the plate. A tumbler, here, and a click you could miss. Quiet, if you take your time.'" {
    Assert vGate(party).
  }
  Thing keepers_gate "the keepers' gate" at lb_gate {
    State locked "The keepers' gate is shut, its numerals unread.".
    State open "The keepers' gate stands open on a dark that ticks.".
    State broken "The keepers' gate hangs from one leaf, its lock sheared, and the tick beyond it has quickened.".
    Change read_open "Set the gate's numerals from the rubbing of the Prefect's Table" from locked to open needing pharos_rubbing.
    Change pick_open "Take the gate's tumbler, quietly" from locked to open needing lockwork.
    Change force_open "Break the gate's lock with a bar" from locked to broken needing brawn.
    Tries listening.
  }
  Query gateWays() means state(keepers_gate, open) or state(keepers_gate, broken).
  Rule gate_force_costs when state(keepers_gate, broken) and not stirred(party) and at(party, lb_gate) says "The bronze shrieks, and somewhere below a great many small things stop turning and begin again, faster." {
    Assert stirred(party).
  }
  Relation stirred(group).
  Action count_the_gate(actor: group, site: place) "Ask Marren Kestle's counting of the numerals out loud" {
    Description "Aenean numerals in a row, and Marren's habit of counting under her breath on the stair behind you.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lb_gate) and sealCut(party) and not gateRead(actor) and state(keepers_gate, locked).
    Time 2.
    Resolve check(actor, insight, dc_fair).
    On success { Assert gateRead(actor). Assert state(keepers_gate, open). }
    Result "Marren has come down as far as the last turn and stopped, with her knife in her belt. You say the numerals back to her in the order they stand, and she counts them under her breath, as she has counted the lamp's wicks all her life, and at the ninth she says 'No,' quite kindly, and gives you the right one. The gate leans inward on its own weight.".
    Otherwise "Marren listens to the numerals, and her lips move, and she says that she can count to forty in the Aenean way but not backwards.".
  }

  // ── Act II: the engine hall and the gallery ────────────────────────────────────────────────────────────────────────
  Thing engine "the engine under the Pharos" at lb_ledge {
    State running "Under the ledge a floor of brass wheels the width of cartwheels turns in the dark, edge to edge, each tooth as long as a forearm, ticking.".
    State stilled "Under the ledge the brass wheels stand with their teeth locked, and the tick has stopped for the first time in two thousand years.".
    Change throw_brake "Throw the keepers' brake" from running to stilled needing brawn.
    Change pick_brake "Ease the keepers' brake's pawl" from running to stilled needing lockwork.
  }
  Thing keepers_brake "the keepers' brake" at lb_ledge { State free "A black iron lever as long as an arm, set in a slot in the ledge wall, with a pawl the size of a thumb. It has not moved in a very long time.". }
  Observe lb_ledge_scene at lb_ledge when true "A ledge of black stone over a hall the size of a barn. Below, in the dark, brass: wheels, hundreds of them, each as wide as a cartwheel, meshed edge to edge and turning, on a floor that is also wheels. Every one carries numerals. The tick is the sound of them. The whole hall hangs on a taut flat steadiness, as a heart does in a body asleep.".
  Observe lb_far_scene at lb_far when true "The far side of the wheel-floor: a landing, a rail, an arch into lamplight. The brass goes on turning behind you with the sound of someone counting to himself.".
  Rule voice_teeth at lb_ledge when at(party, lb_ledge) and memberOf(?m, party) and brings(?m, lore) and awake(?m) and not vTeeth(party)
    says "{?m} watches the wheels for a full minute with the stillness of someone doing a sum. 'They are not random,' {?m} says. 'Every tooth has a number and the numbers are in step. If you cross on the evens as they come up, and wait out the odds, there is a path of about thirty paces. I could do it. I'd rather not have to say how.'" {
    Assert vTeeth(party).
  }
  Action cipher_the_wheels(actor: group, site: place) "Read the wheel-floor's numbers, and give the company the path across" {
    Description "Only someone who has been taught to see a number in a toothed wheel can do it unaided.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lb_ledge) and not crossed(party) and state(engine, running) and memberOf(?m, party) and brings(?m, lore).
    Time 4.
    On success { Assert crossed(party). }
    Result "{?m} walks you over in the order the teeth allow, a pace at a time, with a hand flat on each of your backs, saying the numbers aloud. It takes eleven minutes, and nobody is touched by a wheel. On the far side {?m} sits down on the landing and says that was the most tiresome thing that has ever been done with a pencil.".
  }
  Action walk_the_lines(actor: group, site: place) "Cross on the lines the rubbing of the Prefect's Table shows" {
    Description "The second column of the Prefect's Table is not a list of keepers. It is a tread.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lb_ledge) and not crossed(party) and state(engine, running) and holding(actor, pharos_rubbing).
    Time 4.
    On success { Assert crossed(party). }
    Result "You hold the rubbing up to the lamp-glow, and the ghost column that nobody on Skerrow could read is a tread: strokes where a foot may go, in the order the teeth come round. You walk it with the paper held out in front of you like a map in a gale. At the end the wheels are behind you, and you find that you have been counting.".
  }
  Action run_the_wheels(actor: group, site: place) "Run the wheel-floor, and trust the dark" {
    Description "Thirty paces across brass that moves. A hard climb at the best, and a bad end at the worst.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lb_ledge) and not crossed(party) and state(engine, running).
    Time 2.
    Resolve check(actor, climbing, dc_hard).
    On success { Assert crossed(party). }
    On failure { Assert strikes(lb_teeth, party). Assert crossed(party). }
    Result "You go over the brass in a series of bad ideas that happen to work. At the far rail you discover that you are all still the right number.".
    Otherwise "You are across. You are not across all in one piece: a wheel has taken you and passed you on, the way a mill-race passes a stick.".
  }
  Hazard lb_teeth "The turning teeth" means "Deal (3d6) bludgeoning damage to ally unless dexterity save against (15).".
  Rule ledge_stilled_crossed when state(engine, stilled) and not crossed(party) { Assert crossed(party). }
  Rule brake_thrown_cost when state(engine, stilled) and not brakeThrown(party)
    says "Above you, through a hundred feet of rock, the Pharos goes out. You do not see it. There is simply a place in the dark above the stair where the glow was, and a silence in the oil pipe." {
    Assert brakeThrown(party).
  }
  // The island's night pays for the brake: a day with the Pharos dark and the pilot unfed, and something on the Reach pays.
  Measure darkAt(entity). Relation reachPaid(group).
  Rule dark_begins when brakeThrown(party) and not pilotLit(party) and darkAt(party) == 0 and not reachPaid(party) {
    Set darkAt(party) to watch(clock). Increase darkAt(party) by 144.
  }
  Rule reach_pays when darkAt(party) > 0 and watch(clock) >= darkAt(party) and not pilotLit(party) and not reachPaid(party)
    says "Through the rock, from very far above, comes the thump of a gun, and a second, and no third. Wherever you are on the island, some time after, you will be told what it was, and you will not need telling." {
    Assert reachPaid(party). Set darkAt(party) to 0.
  }
  Rule pilot_saves_the_reach when pilotLit(party) and darkAt(party) > 0 { Set darkAt(party) to 0. }
  Observe reach_paid_scene at pharos_foot when reachPaid(party) "A boat's spars lie across the strand below the Pharos, a day old, and the gulls are very quiet about them. Nobody on the island will say whose.".
  Observe lamp_dims at pharos_lamp when brakeThrown(party) and not pilotLit(party) "The lamp room is dark. The wicks are trimmed, the oil is in, and the great bronze reflector has nothing to throw. Marren Kestle sits on the floor with her back to it, saying nothing, and the Dorothea's captain is the only one on the Reach who has noticed.".
  Observe lb_crawl_scene at lb_crawl when true "A crawl as narrow as a chimney, polished on the floor to a trough by the knees and elbows of keepers one at a time, the one who tends and the one who counts. Every yard or so, scratched at the height of a cheek, a name and a year, in the hand of whoever was crawling.".
  Observe lb_gallery_air at lb_gallery when true "The tick has thinned to a murmur behind the rock. The air has the dry sweetness of a room where a fire has been banked for longer than the room has had a roof.".
  Observe lb_gallery_scene at lb_gallery when true "A long low gallery in the rock with a table down the middle, a lamp on it, benches on both sides, and on the walls, chalked and re-chalked in four hands over two hundred years, two columns of argument. The left column is headed OWED, and the right KEPT, and where the chalk of one reaches the other there is a smear where a hand has wiped it. At the end a man in a surveyor's coat sits with his back against the wall, pretending to take a reading.".
  Observe lb_well_heat at lb_well when true "It is hot at the bottom, a dry heat like the back of a baker's oven, and it smells of scorched brass and of nothing else. Green light moves on the curve of the rock overhead as light moves on the ceiling above a pond.".
  Observe lb_well_scene at lb_well when true "The bottom of the Lamp Below: a round well in the rock, a hundred feet across and as deep as the stair, with a cage of bronze in the middle of it, hung from nothing. In the cage a lens of green glass the size of a house turns on its axis at the pace of a slow walk, and under the lens a small pilot flame burns in a bronze cup, fed by a lead pipe that comes down the wall out of the dark.".
  Observe well_pilot at lb_well when pilotLit(party) "The pilot burns steady in its cup, fed, and the lens above it turns at the pace of a slow breath. Far above, through a hundred feet of rock, there is a green that was not there.".

  Person oswin "Oswin Tarn" at lb_gallery {
    Role "a surveyor of the Collegium of Measures, nine days below". Ancestry human. Calling mage. Level 2. Peaceable. Pronouns he. Manner proud.
    Likeness "scholar".
    Greets "The man in the surveyor's coat gets to his feet with a great effort at ease, and a pencil falls out of his hair. 'Tarn. Oswin. Measures. I am taking readings. I am entirely well, and the readings are very good, and there is nothing at all to be done about the thing in the well.' He sits down again, rather quickly.".
    Greets again "Oswin Tarn has found his pencil and written something on the back of his own hand. 'Taking readings,' he says. 'The readings are better. I wish I could tell you why, and I am afraid I can.'".
  }
  Topic oswin_why with oswin "Ask Oswin Tarn how he came down" when true once {
    Says "'By the sea-door,' says Tarn. 'Which is under the cliff, and was a dry cave at low water, and is not now. The House sent me. A survey of the Pharos for the lease, they said. To weigh the bronze.' He lifts a notebook: 'It is not bronze. It is the chimney of a thing. I have been nine days with the readings and I am a happy man and I have not eaten since the tide went.'".
  }
  Topic oswin_governor with oswin "Ask Oswin Tarn about the Governor" when true once {
    Says "'The Governor counts,' says Tarn. 'It was built to count whoever is below. One keeper below at a time, tending; one at the gate, counting. It reads the company on the stair. If there are more than two, it concludes the lamp is being taken.' He looks at his notebook. 'It has a word. The keepers had a word, to stand it down. I have it in my book, and I am not going to read it to anyone who plans to leave me here.'".
    On discuss { Assert oswinWord(oswin). }
  }
  Relation oswinWord(group).
  Topic oswin_leave with oswin "Promise Oswin Tarn the way out, and ask for the word" when oswinWord(oswin) and not stopSaid(actor) once {
    Says "'You are very kind,' says Tarn, faintly, and then, in a rush: 'It is nine characters, read as one, three times, the third time lower. Say it from the lip of the well. It will lie down. It has been waiting for someone to say it for longer than there has been a Tolleth.' He closes the book. 'It is the only thing I own. I should like it back, in a printed form, with my name.'".
    On discuss { Assert knows(actor, lb_stopword). Assert stopSaid(actor). }
  }
  Discovery lb_stopword "Tarn's notebook has the Governor's word: nine characters, read as one, three times, the third time lower; said from the lip of the well, it lies down.".
  Topic oswin_heart with oswin "Ask Oswin Tarn what he is afraid of" when true once {
    Says "'That I shall be told I was wrong,' says Tarn, at once, and without any pride at all. 'Everyone is afraid of the thing in the well. I am afraid that the Collegium will say my reading of the second column is a copyist's slip. If I take the book out and I am wrong, I have wasted two Collegia. If I leave it here and I am right, I have wasted the only true thing I ever found.' He laughs, once. 'Choose one of us to carry, if you have to.'".
  }
  // Tarn will not leave without his book, and the company cannot carry both a man who has not eaten in nine days and
  // nine days of paper up a hundred feet of dish-worn stair: it carries him, and the book stays on the bench (he says it
  // was only ever a reading), or it carries the book and Marren fetches him in the morning, if he is still there.
  Relation bookTaken(group). Relation coinLeft(group).
  Kind lb_notebook "the surveyor's notebook" is treasure worth 50 weighing 1 described "Nine days of readings in a surveyor's hand, in pencil, going lighter toward the end. The second column of the Prefect's Table is copied out in it as a tread, with a note in the margin: NOT A LIST.".
  Action carry_oswin(actor: group, site: place) "Take Oswin Tarn back up the stair with you, and leave his book on the bench" {
    Description "A man who has not eaten in nine days, up a hundred feet of dish-worn stair. The book stays.".
    Requires able(actor) and company(actor) and at(actor, site) and at(oswin, site) and not oswinOut(actor) and not bookTaken(actor).
    Time 6.
    On success { Assert oswinOut(actor). Retract at(oswin, lb_gallery). Assert at(oswin, lb_head). }
    Result "Tarn looks at the notebook for as long as it takes to be afraid of it, and puts it on the bench with the pencil across it, squared, like a man leaving a hat. 'It was a reading,' he says. 'Only ever a reading.' He takes your arm like a man on a ship's deck. He climbs the stair on it, one dish-worn step at a time, saying the numbers he can see in the wall, and at the trap he stops and looks up at the sky he has not seen in nine days. 'Oh,' he says. 'It's still there.'".
  }
  Action take_oswins_book(actor: group, site: place) "Take Oswin Tarn's notebook for the Collegium, and leave him to be fetched" {
    Description "The only true thing he ever found, out of the hands that found it.".
    Requires able(actor) and company(actor) and at(actor, site) and at(oswin, site) and not oswinOut(actor) and not bookTaken(actor).
    Time 1.
    On success { Give lb_notebook to actor. Assert bookTaken(actor). }
    Result "'Take it,' says Tarn, quickly, before he can think, and puts it in your hands. 'If I am wrong, say it was a copyist.' He sits down again, rather carefully, with his back to the wall and his readings gone. 'Send someone,' he says, to the lamp on the table. 'In the morning will do. I shall be very quiet.'".
  }
  Observe oswin_left at oil_store when bookTaken(party) and not oswinOut(party) "Marren Kestle has rope, a lantern and a ration-bag ready by the trap, and her back to you. 'There is a man down there,' she says, without turning. 'Nine days. You carried his paper up and left him with the lamp.' She does not say it as a charge. She says it as a sum.".
  Observe oswin_out at oil_store when oswinOut(party) "Oswin Tarn sits on an oil keg in the light from the door, eating oatcake with both hands, and telling Marren Kestle, in a voice getting steadier with every mouthful, exactly how wrong he was.".

  Rule voice_office at lb_gallery when at(party, lb_gallery) and memberOf(?m, party) and brings(?m, rites) and awake(?m) and not vOffice(party)
    says "{?m} reads the chalk columns end to end, lips moving, and stops where the two hands meet in a smear. 'Somebody at the Collegium wrote OWED against every year's oil,' {?m} says. 'Somebody on the island wrote KEPT over it. Two hundred years of rubbing out each other's totals.' {?m} puts a thumb in the smear and takes it away grey. 'We have an office for the dead that argues the same point, and we settle it the island's way. I know what to say to this. I'm not sure it will like being said to.'" {
    Assert vOffice(party).
  }
  Action read_the_office(actor: group, site: place) "Read the office for the dead over the tally, aloud, from the lip of the well" {
    Description "The Governor keeps the count of the living and the lost. A cleric has a form of words for closing a count.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lb_well) and at(governor, lb_well) and not tolerates(governor, actor) and memberOf(?m, party) and brings(?m, rites) and not governorRests(actor).
    Time 4.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert tolerates(governor, actor). Assert governorRests(actor). }
    Result "{?m} says the office at the well's edge in the plain voice of someone who has said it for strangers, naming no one. At the word 'kept' the lens stops. For the length of a breath nothing in the Lamp Below moves, not a wheel, not the tick. Then the Governor folds its hands over the knife, and the round green lens of its face dulls like a pebble taken out of water.".
    Otherwise "{?m} begins, and the Governor turns its head at the first line and does not find it agreeable. The patience of the thing has shortened.".
  }

  // ── Act III: the lens-well and the Governor ───────────────────────────────────────────────────────────────────────
  Species lb_governor "the Governor of the Lamp Below" like golem temperament territorial described "A body of black bronze nine feet tall, jointed at the knee and hip with plates that overlap like a lobster's, and for a face a round green lens; it holds a trimming-knife the length of a spear.".
  Person governor "the Governor" at lb_well {
    Role "the engine's keeper, set to count whoever is below". Species lb_governor. Level 6. Temperament territorial. Pronouns it.
    Warns "In the cage of bronze the lens stops, and a figure beside the pilot turns its round green face on you with the whole of a slow body. It counts you. You can see it do it: a finger lifting once for each of you. A voice like a hinge says a number. The number is not the number of the company. 'One keeper,' it says. 'One counter. All others are removal.'".
    Comes "The Governor takes its trimming-knife from the cage with an unhurried hand, and the number it says is yours.".
    Flinches "The Governor's head tilts. For a moment it seems to count someone who is not there.".
    Pleads "The Governor stops with one arm raised, and the lens in its face goes from green to a very pale amber. 'Count,' it says. 'Count. Count.'".
  }
  Rule governor_counts_one at lb_well when at(party, lb_well) and count(memberOf(?m, party)) == 1 and at(governor, lb_well) and not tolerates(governor, party) and not governorRests(party) and not stirred(party)
    says "The Governor counts the company, one finger at a time. Then it counts again. 'One,' it says, in the hinge of its voice. 'One keeper. Tend.' It steps aside from the pilot as if from a table it has been told to lay for a guest, and the lens goes on turning." {
    Assert tolerates(governor, party). Assert governorRests(party).
  }
  Rule voice_hip at lb_well when at(party, lb_well) and memberOf(?m, party) and brings(?m, brawn) and awake(?m) and at(governor, lb_well) and not vHip(party)
    says "{?m} looks at the Governor's hip for as long as it takes to be afraid of it, and then at the plate above the left knee. 'Overlap's worn on that side,' {?m} says, low. 'Two hundred years of the same stroke with the same knife. You'd get a blade into that gap, but you'd be in reach to do it.' A breath. 'I'd rather talk to it.'" {
    Assert vHip(party).
  }
  Action say_the_word(actor: group, site: place) "Say the keepers' word from the lip of the well, three times, the third lower" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lb_well) and at(governor, lb_well) and knows(actor, lb_stopword) and not tolerates(governor, actor) and not governorRests(actor).
    Time 1.
    On success { Assert tolerates(governor, actor). Assert governorRests(actor). }
    Result "Nine characters, as one, three times, the third time lower. At the first the Governor's finger stops. At the second it lowers the knife. At the third it kneels, and sets its hand flat on the coping, and the green lens in its face goes slowly dark. 'Counted,' it says.".
  }
  Action feed_the_pilot(actor: group, site: place) "Pour a keg of the Pharos's oil into the pilot's cup" {
    Description "The oil comes down the pipe from the island's store, by hand, every autumn. Nobody has taken it the rest of the way.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lb_well) and holding(actor, dorothea_oil_keg) and not pilotLit(party).
    Time 2.
    On success { Spend dorothea_oil_keg from actor. Assert pilotLit(party). Assert tolerates(governor, actor). Assert governorRests(actor). }
    Result "The cup was a thumb's depth from dry. You pour, slowly, and the flame, which had been the size of a fingernail, stands up. The lens above you picks up its turn; the tick in the hall behind you steadies; the Governor, which came to its feet at the first sign of the keg, stops with the trimming-knife half raised and looks at the flame with the whole of its round green face. 'Fed,' it says. It is the first word it has said that sounds like anything but a count.".
  }
  Action take_gauge(actor: group, site: place) "Take the engine-keeper's gauge from the cage" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lb_well) and governorRests(actor) and not lbDone(actor).
    Time 2.
    On success { Give lb_gauge to actor. Assert lbDone(actor). }
    Result "The gauge hangs on a hook by the pilot: a dial gone black with age, with a needle the length of a finger, and across its face the Aenean numerals in the first column, and in the second the strokes of the tread. It is lighter than it looks. The Governor watches you take it, and does not count.".
  }
  Kind lb_gauge "the engine-keeper's gauge" is treasure worth 60 weighing 1 described "A dial of black bronze with a needle the length of a finger, taken from the cage of the Lamp Below. On its back, in a green metal that has not tarnished, a fish and over it a flame.".

  // What the Lamp Below leaves in the world. The Pharos above is the chimney of this; nothing here is a world event, and
  // only this module reads it.
  Rule lamp_known_by_fall when governorRests(party) and not engineKnown(party) { Assert engineKnown(party). }
  Relation engineKnown(group).
  Observe plaque_scene at lb_well when governorRests(party) "Cut into the well's coping, a plaque in the Aeneans' numerals and the Aeneans' Latin says that this was made by the Prefect's order, for the keeping of the lights. It is the Aeneans' claim, and a good plain one. The engine is older than the wall it is set in by about two thousand years, and the wall is Aenean.".
}

data/adventures/the-dorothea/mangrow.kyr:
Module dorothea "The Dorothea" {
  Description "Mangrow: five days south, where the Reach runs out into green. A river mouth under cane and fig, a pier that is mostly a rumour, a House outstation the forest has been eating for eleven months, a naturalist in a tree, and a fever that comes in with the bites. The bark that cures it is locked in the House's own strong-room.".

  // Terrain kinds do not exist (friction A1): Mangrow is a `settlement` and a `wilderness`, and the jungle is prose and two
  // mechanisms, a heat measure (`swelter`) that climbs while the company is in the green and a hazard when it climbs too far.
  Place mangrow "Mangrow" is region.
  Place mangrow_shore "the Mangrow landing" is settlement within mangrow at 0, 0.
  Place mangrow_wood "the forest" is wilderness within mangrow at 1, 0.
  Place mangrow_pier "the rotting pier" is room within mangrow_shore at 0, 1.
  Place mangrow_yard "the outstation yard" is room within mangrow_shore at 1, 1.
  Place mangrow_store "the strong-room" is room within mangrow_shore at 2, 1.
  Place mangrow_creek "the creek mouth" is room within mangrow_wood at 0, 0.
  Place mangrow_hide "Vail's hide" is room within mangrow_wood at 1, 0.

  Relation ferried(group). Relation storeOpen(group). Relation burntOpen(group). Relation barkTaken(group). Relation barkCut(group).
  Relation netted(group). Relation barked(group). Relation fevered(group). Relation vailTrusts(group). Relation oskTended(group).
  Relation strandedMangrow(group). Relation felt2(group). Relation felt6(group).
  Measure swelter(group). Measure stingAt(group). Measure barkEnds(group).

  Passage mangrow_track "the overgrown track" is path between mangrow_pier and mangrow_yard taking 1 hour.
  Passage mangrow_cut "the cut through the cane" is path between mangrow_yard and mangrow_creek taking 30 minutes.
  Passage mangrow_planks "the plank-walk to the hide" is path between mangrow_creek and mangrow_hide taking 30 minutes.
  Passage mangrow_ferry "Sula Weir's flat boat" is path between mangrow_pier and mangrow_creek taking 40 minutes
    opening when ferried(party) "The flat boat lies in the reeds with its pole across it. Sula Weir does not pole for nothing.".
  Passage mangrow_strong_door "the strong-room door" is door between mangrow_yard and mangrow_store
    opening when storeOpen(party) "The strong-room door is shut. A fig has put one root through the frame and another through the lock, and the iron has stopped being the stronger of the two.".

  Query inGreen(g: group) means at(g, mangrow_yard) or at(g, mangrow_store) or at(g, mangrow_creek) or at(g, mangrow_hide).
  Query onMangrow(g: group) means at(g, mangrow_pier) or at(g, mangrow_yard) or at(g, mangrow_store) or at(g, mangrow_creek) or at(g, mangrow_hide).

  Observe deck_mangrow_roads at deck when at(hull, mangrow_roads) "Mangrow roads: a green wall with a brown mouth in it. The water has gone the colour of tea, and warm air comes off the shore like the breath of a large animal. Something is calling in the trees, over and over, the same three notes.".
  Observe deck_mangrow at deck when at(hull, mangrow_pier) "The Dorothea lies against a pier that Bascom has not trusted with a line: she has laid out two anchors and a plank. Vines come down the bank to the waterline. Mab, who has been here twice, stands on the hatch with a hand over her mouth and a cloth tied round her hair.".
  Observe mangrow_pier_scene at mangrow_pier when true "The Mangrow pier: forty yards of black piles with about a third of the planking left on them, the rest gone to the river a board at a time. Green comes right down to the water. Vines hang from the bollards, thick as a wrist, and the air is wet enough to wear. A hum comes off the cane that you take for wind until something lands on your neck.".
  Observe mangrow_yard_scene at mangrow_yard when true "The House's outstation: a long shed on stilts, its veranda sagging, its stencilled key-and-ring blistered to a ghost. A fig has taken the east end whole, and its roots go through the boards like fingers through a loaf. There is a chair on the veranda with a fern growing in it. On the table inside, under a skin of green mould, a letter in a clerk's round hand has been rained on and dried most of a year.".
  Observe mangrow_store_scene at mangrow_store when true "The strong-room: stone, the only dry place at Mangrow, and it smells of cloves and wet dog. Rolls of grey bark are stacked to the ceiling in tiers, every tier stencilled HELD, and a fig-root has found the ceiling and hangs from it, patient as a plumb-line.".
  Observe mangrow_store_book at mangrow_store when true "On the top bale lies the outstation's day-book, open, in Perrin Osk's cramped hand. Month after month the same line: BARK GATHERED, SO MANY BALES. BARK HELD. NOT TO BE SHIPPED, PRICE TO BE KEPT. Under the last entry, in another ink, a figure that is the Tolleth physic's price for a bale this autumn, and beside it, in pencil, a second figure: the lower town's burials.".
  Observe mangrow_creek_scene at mangrow_creek when true "The creek mouth: brown water the width of a street going slowly out under a roof of figs, a bar of mud where the tide leaves things, a log on the far bank that is not a log. Bats go over at noon. The insects here are not midges. They have opinions.".
  Observe mangrow_hide_scene at mangrow_hide when true "Vail's hide: a plank platform in a mangrove, twelve feet above the mud and roofed in palm. A hammock, a trestle of pinned moths under glass, a hundred paper packets in a fine hand, a kettle, and behind a hung cloth a second hammock in which someone is breathing carefully.".

  Person weir "Sula Weir" at mangrow_pier {
    Role "ferrywoman of the Mangrow creek". Ancestry human. Level 2. Peaceable. Pronouns she. Manner acerbic.
    Likeness "sailor".
    Greets "A woman as thin and dark as a pole leans on the pier's last good bollard, a cheroot unlit in one hand and a slapping-cloth in the other. She slaps her neck and looks at the palm before she speaks. 'I pole the creek. Sula Weir, in case you want it for the complaint. You will have come about the Agent, or the bark, or because Bascom said it was an adventure.' She wipes the palm on her skirt. 'Three coin and I take you up it. Walk and you pay the cane instead.'".
    Greets again "Sula Weir slaps her neck, looks at her palm, and shows it to you in evidence. 'Dead,' she says. 'That's four hundred this morning, and I have not yet had breakfast. If you are staying in Mangrow, grow a thicker skin, or a thinner reason.'".
  }
  Person ennis_vail "Ennis Vail" at mangrow_hide {
    Role "naturalist, struck off the rolls of the Collegium of Measures, and counting". Ancestry human. Level 2. Peaceable. Pronouns he. Manner stoic.
    Likeness "scholar".
    Greets "A man so brown and so thin that he seems made of the same stuff as the hide stands up from the trestle with a pin in his teeth and does not take it out until he has put the moth down. 'Vail,' he says. 'You are not the Collegium. The Collegium would have sent a boat with a flag. You are not the House either, because the House has sent nothing for eleven months, and I have a very good ear for the absence of the House.'".
    Greets again "Ennis Vail has pinned another moth, and does not look to see whether you have admired it. 'You are not the Collegium yet,' he says. 'I have started to like that about you. It is the only reason I am talking.'".
  }
  Person osk "Perrin Osk" at mangrow_hide {
    Role "the House's Agent at Mangrow, who went up the creek eleven months ago and has been ill since". Ancestry human. Level 1. Peaceable. Pronouns he. Manner jovial.
    Likeness "merchant".
    Greets "Behind the cloth a man in a once-good waistcoat lies with his boots on and a sheet to the chin, yellow as a candle, and turns his head with great care. 'You will forgive the waistcoat,' he says. 'Osk, Perrin, the House of Marchbank's Agent at Mangrow, at your service, and you may see how I am serving.' He tries a laugh and thinks better of it.".
    Greets again "Perrin Osk has propped himself on one elbow, which has cost him the sheet. 'You have not gone,' he says, and the yellow face works. 'People go. The ones that come twice are always on a mission. What is yours? Is it mercy, or is it the bark?'".
  }

  // ── Getting there and what the green does ───────────────────────────────────────────────────────────────────────
  Topic sula_creek with weir "Ask Sula Weir about the creek" when true once {
    Says "'It is the road,' says Sula. 'The track from here to the outstation was cut by the House's people with the House's money, so you can guess how much of it is left. The creek goes up under the figs to a man in a tree.' She looks at you with some pity. 'The air is the trouble. You will not feel it for the first hour. Then the bites go to your head. Net, or smoke, or the bark. I have all three in my bad dreams.'".
  }
  Topic sula_osk with weir "Ask Sula Weir what became of the Agent" when true once {
    Says "'Went up the creek in March with the strong-room key round his neck and the petty cash in a boot,' says Sula, to the cheroot. 'I do not say I poled him. I say a man cannot get up that creek on his own legs.' She finds a match. 'He was not stealing. He was carrying. You'll see.'".
  }
  Action pay_sula(actor: group, site: place) "Pay Sula Weir three coin to pole you up the creek" {
    Description "The flat boat takes you to the creek mouth in forty minutes. The track takes an hour to the outstation, and the cane has its toll.".
    Requires able(actor) and company(actor) and at(actor, site) and at(weir, site) and at(actor, mangrow_pier) and not ferried(actor) and quantity(actor, gold) >= 3.
    Time 1.
    On success { Decrease quantity(actor, gold) by 3. Increase quantity(weir, gold) by 3. Assert ferried(actor). }
    Result "She puts the coin in the cheroot-hand and the cheroot in her mouth, which is as near as she comes to a receipt. 'Sit in the middle,' she says. 'Hands in the boat. Whatever is on the log, it is a log.'".
  }

  // The heat: one sting a hour in the green, half as often under netting, none under the bark. Four of them and the river
  // fever takes the company; eight and Sula comes and carries it out.
  Initially Set swelter(party) to 0. Initially Set stingAt(party) to 0. Initially Set barkEnds(party) to 0.
  Rule sting_clock when not inGreen(party) { Set stingAt(party) to watch(clock) + 6. }
  Rule swelter_rises when inGreen(party) and not barked(party) and not netted(party) and watch(clock) >= stingAt(party) {
    Increase swelter(party) by 1. Set stingAt(party) to watch(clock) + 6.
  }
  Rule swelter_rises_netted when inGreen(party) and not barked(party) and netted(party) and watch(clock) >= stingAt(party) {
    Increase swelter(party) by 1. Set stingAt(party) to watch(clock) + 12.
  }
  Rule bark_fades when barked(party) and watch(clock) >= barkEnds(party)
    says "The bitter has gone out of your mouth, and the cane has noticed." {
    Retract barked(party).
  }
  Rule felt_warm when swelter(party) >= 2 and not felt2(party)
    says "Your shirt has stopped being a shirt and become a damp opinion. The bites are in clusters on the neck and wrists, and every one is a small hot coin. You are slow to answer when spoken to." {
    Assert felt2(party).
  }
  Rule felt_cool when felt2(party) and swelter(party) < 2 { Retract felt2(party). }
  Hazard river_fever "The river fever" means "Deal (2d6) physical damage to ally unless constitution save against (13).".
  Rule fever_takes when swelter(party) >= 4 and not fevered(party)
    says "It comes in all at once, as a tide comes in over flat sand: a cold in the spine in a place where the air is warm, and a ringing, and the green going too bright at the edges. Someone laughs at nothing and it is yourself." {
    Assert fevered(party). Assert strikes(river_fever, party).
  }
  Rule fever_breaks when fevered(party) and swelter(party) <= 1 { Retract fevered(party). }
  Rule felt_dire when swelter(party) >= 6 and not felt6(party) says "The river is a long way off and the ground is nearer than it was. Somebody is saying your name from a boat." { Assert felt6(party). }
  Rule felt_dire_over when felt6(party) and swelter(party) < 6 { Retract felt6(party). }
  Rule swelter_collapses when at(party, ?w) and inGreen(party) and swelter(party) >= 8
    says "You do not remember sitting down. You remember a flat boat, a pole, and a woman's voice saying, to the mud, that she had told them." {
    Retract at(party, ?w). Assert at(party, mangrow_pier). Set swelter(party) to 3. Retract felt6(party).
  }

  // ── The protections ─────────────────────────────────────────────────────────────────────────────────────────────
  Kind dorothea_netting "a length of tarred netting" is gear worth 2 weighing 1 described "Fine hemp netting, tarred against the damp and cut to hang from a hat-brim or a hammock. Wat Garrick swears it has never failed anyone who was alive to complain.".
  Action hang_netting(actor: group, site: place) "Put on the netting and tar your wrists" {
    Description "It halves the stings. It does not stop them.".
    Requires able(actor) and company(actor) and at(actor, site) and onMangrow(actor) and not netted(actor) and holding(actor, dorothea_netting).
    Time 1.
    On success { Spend dorothea_netting from actor. Assert netted(actor). }
    Result "You hang it from your hats and tar the cuffs, and look like a company of bee-keepers going to a funeral. The hum drops half a note.".
  }
  Action rest_on_pier(actor: group, site: place) "Sit out in the breeze at the end of the pier until your head clears" {
    Description "The sea air does what the green takes away. It takes the better part of an hour.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, mangrow_pier) and swelter(actor) >= 1.
    Time 6.
    On success { Decrease swelter(actor) by 2 or to nothing. }
    Result "You sit with your feet over the water and the wind coming off the roads, and the ringing eases a note at a time, until it is the Dorothea's rigging and no more.".
  }
  Kind dorothea_bark "a bale of Mangrow bark" is gear worth 8 weighing 2 described "A roll of grey-white bark, tied with raffia, stencilled HELD and, under it in a hand with less certainty, a key-and-ring. It smells of cloves and wet dog. A pinch steeped in a pannikin is bitter enough to stand a spoon in.".
  Action drink_bark(actor: group, site: place) "Steep a pinch of the bark and drink it round" {
    Description "It is a day's protection from the bites and the fever behind them. It is also, by report, the worst thing you have ever put in your mouth.".
    Requires able(actor) and company(actor) and at(actor, site) and holding(actor, dorothea_bark) and not barked(actor).
    Time 1.
    On success { Spend dorothea_bark from actor. Assert barked(actor). Set swelter(actor) to 0. Set barkEnds(actor) to watch(clock) + 90. }
    Result "The pannikin goes round. The one who has drunk worse in the army says they have not. By the second round the cane has gone quiet, and the ringing is a sound you remember from somewhere else.".
  }
  Action brew_for_the_boy(actor: group, site: place) "Steep the Mangrow bark for the boy" {
    Description "A fever on a ship is a fever on a ship. This one the bark was made for.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and fever(hull) and holding(actor, dorothea_bark).
    Time 2.
    On success { Spend dorothea_bark from actor. Retract fever(hull). Retract troubled(hull). }
    Result "Mab holds the pannikin and Nipper holds his nose. It takes three tries and a promise about the biscuit. By the second watch the sweat has gone cold and honest, and he is asking whether there is any more of the cheese.".
  }

  // ── Vail and his count ──────────────────────────────────────────────────────────────────────────────────────────
  Topic vail_count with ennis_vail "Ask Ennis Vail what he is counting" when true once {
    Says "'Moths,' says Vail, and the word comes out like a thing he has been saving. 'Twelve hundred and four kinds on this river, in six years, of which the Collegium would grant me eight hundred, and has struck the whole table out of the Tables on the ground that a man cannot see so many in a place so small.' He lays a pin down very straight. 'I have the pins. They can come and look at the pins.' He glances at the hammock behind the cloth. 'I count the Agent too. Sixty-one days since he last sat up. He is a man who sits up when he is ashamed.'".
    On discuss { Assert vailTrusts(actor). }
  }
  Topic vail_bark with ennis_vail "Ask Ennis Vail what cures the river fever" when true once {
    Says "'The bark of the white fig-leaf. It weeps red where it is cut. A pinch in a pannikin, and the river lets go.' He waves at the hide. 'I take a cup a day. Perrin takes what I can keep in him. The House bought every bale on this coast two seasons running and shut them in a stone room. I would call it hoarding, but the House would call it a position.'".
  }
  Topic quint_vail with quint "Ask Odile Quint whether she knows Ennis Vail" when at(actor, mangrow_hide) once {
    Says "Quint has been standing very straight since you climbed the ladder. 'Ennis Vail,' she says, and then, to him, in a different voice: 'You wrote the note on the unequal wings. You said a measure that cannot be repeated is a rumour. I put it on the wall of my room at Sennet.' Vail takes the pin out of his teeth. 'It was wrong,' he says. 'It was a rumour.' 'It was the best thing in the Tables,' says Quint. He sits down on the trestle rather quickly. When he has found his voice again he is making a pannikin of the bark for the whole company without being asked.".
    On discuss { Assert vailTrusts(actor). Assert barked(actor). Set swelter(actor) to 0. Set barkEnds(actor) to watch(clock) + 90. }
  }
  Topic vail_tea with ennis_vail "Ask Ennis Vail for a pannikin of the bark for the company" when vailTrusts(actor) and not barked(actor) once {
    Says "'You have asked about the moths,' says Vail. 'Nobody does. It is the price.' He puts the kettle on. 'Drink it all. It will do your tongue a permanent injury and the river will leave you alone for most of a day.'".
    On discuss { Assert barked(actor). Set swelter(actor) to 0. Set barkEnds(actor) to watch(clock) + 90. }
  }
  Action pay_vail(actor: group, site: place) "Pay Ennis Vail four coin for a pannikin of the bark and an hour of his ear" {
    Description "He is a man of principle. His principle is that he has not been paid for six years.".
    Requires able(actor) and company(actor) and at(actor, site) and at(ennis_vail, site) and not vailTrusts(actor) and quantity(actor, gold) >= 4.
    Time 2.
    On success { Decrease quantity(actor, gold) by 4. Increase quantity(ennis_vail, gold) by 4. Assert vailTrusts(actor). Assert barked(actor). Set swelter(actor) to 0. Set barkEnds(actor) to watch(clock) + 90. }
    Result "He looks at the coin as at a moth he has not seen before. 'It is not enough,' he says, 'and it is the most anyone has given me since I wrote to the Collegium.' He puts it in a packet and labels it. The pannikin, when it comes, is bitter beyond the language.".
  }

  // ── Perrin Osk, and the key ─────────────────────────────────────────────────────────────────────────────────────
  Topic osk_why with osk "Ask Perrin Osk why he walked out of the outstation" when true once {
    Says "'Because the letter on the table said HOLD,' says Osk. 'It is the fourth letter that said it. The first said hold until the price is right, and the price was right in the spring. The second said hold until the price is better. By the third the lower town at Tolleth was burying its children by the dozen, and the physic there was paying the House's price for a cup of what I had in a stone room, and I had the key.' He closes his eyes. 'I did not steal the cash. I paid the gatherers with it, so that the bark would be cut and not rot on the trees. That is a thing the House calls embezzlement, and I call arithmetic.'".
  }
  Kind dorothea_strong_key "the strong-room key at Mangrow" is gear worth 1 weighing 0 described "A black iron key as long as a hand, on a loop of fishing-line, with a key-and-ring stamped on the bow and, scratched under it with a nail, a tally of days.".
  Action tend_osk(actor: group, site: place) "Carry Vail's pannikin behind the cloth and sit with Perrin Osk while he drinks it" {
    Description "He will not take it from a stranger, and then he will, and then he will talk.".
    Requires able(actor) and company(actor) and at(actor, site) and at(osk, site) and at(actor, mangrow_hide) and vailTrusts(actor) and not oskTended(actor).
    Time 3.
    On success { Assert oskTended(actor). }
    Result "He drinks it in four swallows and a curse. You sit while the colour goes slowly up his face like water up a wick. When he can hold a cup he looks at it, and at you, and takes a long breath. 'I will tell you what I should have told the House,' he says.".
  }
  Topic osk_key with osk "Ask Perrin Osk for the strong-room key" when oskTended(actor) and not barkTaken(actor) once {
    Says "He lifts the loop of fishing-line over his head, and his hand shakes with the weight of it. 'The big bales are the Tolleth physic's,' he says. 'There are twenty-two. Take what two can carry, and tell the physic what it cost.' He lets his hand fall on the sheet. 'Tell nobody in Orsett where I am. I am not hiding. I am waiting until I am well enough to be arrested.'".
    On discuss { Give dorothea_strong_key to actor. }
  }
  Action use_the_key(actor: group, site: place) "Cut the roots from the lock and turn Osk's key" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, mangrow_yard) and holding(actor, dorothea_strong_key) and not storeOpen(actor).
    Time 2.
    On success { Spend dorothea_strong_key from actor. Assert storeOpen(actor). }
    Result "The fig has fought for the lock, but the key was cut for it, and it turns. The door swings in on cloves and dry stone.".
  }
  Action pick_the_strongroom(actor: group, site: place) "Work the strong-room lock free of the fig's roots" {
    Description "A thief's job, and a patient one. The roots have been at the wards for most of a year.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, mangrow_yard) and capable(actor, lockwork) and not storeOpen(actor).
    Time 4.
    Resolve check(actor, lockwork, dc_hard).
    On success { Assert storeOpen(actor). }
    On failure { Increase swelter(actor) by 2. }
    Result "You find the wards by feel, between the roots, and lift them one by one in the humming dark. The last one gives a click. The door comes open on cloves.".
    Otherwise "A tendril has taken the pick; you break it out with the lock, and your hand with it. The sweat runs into the cuts, and the insects arrive in a body.".
  }
  Action burn_the_fig(actor: group, site: place) "Burn the fig off the strong-room door with a torch" {
    Description "It is quick, and it is dry stone behind. The bark behind it is not stone.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, mangrow_yard) and holding(actor, torch) and not storeOpen(actor).
    Time 2.
    On success { Spend torch from actor. Assert storeOpen(actor). Assert burntOpen(actor). }
    Result "The fig goes up with a noise like a bolt of wet cloth being torn, and a smell of burnt sugar, and the veranda behind it takes a share. When the roots have shrivelled the door falls open. The inside stops short of burning, but the nearest tier is black and the air is full of cloves, roasted.".
  }
  Relation barkTaken2(group).
  Action take_bark(actor: group, site: place) "Carry a bale out of the strong-room" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, mangrow_store) and storeOpen(actor) and not burntOpen(actor) and not barkTaken(actor).
    Time 3.
    On success { Give dorothea_bark to actor. Assert barkTaken(actor). }
    Result "You take the nearest, which weighs as much as a drowned man, and carry it out into the heat with your teeth set. Behind you twenty more tiers go on waiting, in order, as the House left them.".
  }
  Action take_second_bark(actor: group, site: place) "Carry a second bale out" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, mangrow_store) and storeOpen(actor) and not burntOpen(actor) and barkTaken(actor) and not barkTaken2(actor).
    Time 3.
    On success { Give dorothea_bark to actor. Assert barkTaken2(actor). }
    Result "A second, because a company of three can carry two and a half. The stencil on it says HELD; you hold it.".
  }
  Action take_scorched_bark(actor: group, site: place) "Carry out the one bale the fire spared" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, mangrow_store) and burntOpen(actor) and not barkTaken(actor).
    Time 3.
    On success { Give dorothea_bark to actor. Assert barkTaken(actor). Assert barkTaken2(actor). }
    Result "The outer tiers are cinders. You find one bale in the back that the smoke has only browned, and carry it out under your arm, coughing, past the smouldering veranda.".
  }
  Action cut_bark(actor: group, site: place) "Find the white fig-leaf tree and cut your own bark" {
    Description "Vail has said what it looks like. A tree that weeps red does not hide.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, mangrow_creek) and capable(actor, woodcraft) and not barkCut(actor).
    Time 6.
    Resolve check(actor, woodcraft, dc_fair).
    On success { Give dorothea_bark to actor. Assert barkCut(actor). }
    On failure { Increase swelter(actor) by 1. }
    Result "A leaf with a white underside, a trunk that bleeds when your knife goes in: a quarter of a mile up the bank, where the ground begins to rise. You strip a bale's worth, in the whining dusk, and bring it back with a face that has stopped feeling like yours.".
    Otherwise "Every tree is a fig-leaf and every fig-leaf is the wrong one. You come back with a bleeding hand and a poor opinion of botany.".
  }
  Rule osk_gone when oskTended(party) and not oskWalks(party) and watch(clock) >= reachedAt(hull) + 140 says "A man is sitting up on the veranda of the outstation in a clean waistcoat, with the letter in his hand, reading it as one reads a debt. He does not look up when you pass. He is, you think, waiting to be arrested." {
    Assert oskWalks(party).
  }
  Relation oskWalks(group).

  // ── Home with it ────────────────────────────────────────────────────────────────────────────────────────────────
  Topic drinkers_mangrow with drinkers "Ask the regulars about Mangrow" when true once {
    Says "'Bark island,' says the man with one eye, and spits to the side of the fire. 'Five days south, and a fever for the unwary. The House has bought the whole crop of it, and sells it out of Orsett at a price that would buy a ship. There's children in the lower town lying on the floor with it this autumn, and the physic charges for a cup what you'd pay a priest.'".
  }
  Topic mab_mangrow with mab "Ask Mab about Mangrow" when true once {
    Says "'Twice,' says Mab. 'I will tell you what I told the boy. Netting from Garrick, and tar, and a tin of the bad tobacco, and do not drink from the creek and do not sit in the shade, because the shade is where it keeps the biters.' She tastes the pot. 'And do not let the Captain tie the Dorothea to that pier. She will, if you let her. She has a feeling about piers.'".
  }
  Action sell_bark(actor: group, site: place) "Sell Wat Garrick a bale of Mangrow bark for the physic's price" {
    Description "He knows the physic. The physic has been asking him for it since Michaelmas.".
    Requires able(actor) and company(actor) and at(actor, site) and at(pellow, site) and holding(actor, dorothea_bark) and quantity(pellow, gold) >= 10.
    Time 1.
    On success { Spend dorothea_bark from actor. Increase quantity(actor, gold) by 10. Decrease quantity(pellow, gold) by 10. }
    Result "Wat Garrick weighs the bale in his hand, and sniffs it, and goes the colour of a man who has been told a price in a dream. He counts out ten coin without bargaining, which has never happened in his shop, and puts the bale on a hook behind the door where a runner will fetch it. 'There's six households I could name,' he says, 'and I won't.'".
  }
  Initially Set quantity(pellow, gold) to 40.

  // ── Left behind ─────────────────────────────────────────────────────────────────────────────────────────────────
  Rule left_behind_mangrow when homeward(hull) and bound(hull) == 5 and not aboardNow(party) and onMangrow(party) and not strandedMangrow(party) { Assert strandedMangrow(party). }
  Observe mangrow_stranded at mangrow_pier when strandedMangrow(party) "The Dorothea is a brown sail going north, and Sula Weir is sitting on the last good bollard watching it go. 'Bascom does not wait for anyone,' she says. 'It is her most reliable quality. The bark-cutter Hesper takes passengers for nine, on the tide, when her master is sober.'".
  Action sail_on_the_hesper(actor: group, site: place) "Pay nine coin to go home on the bark-cutter Hesper" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, mangrow_pier) and strandedMangrow(actor) and quantity(actor, gold) >= 9.
    Time 1.
    On success { Decrease quantity(actor, gold) by 9. Retract at(actor, mangrow_pier). Assert at(actor, quay). Retract strandedMangrow(actor). Set swelter(actor) to 0. }
    Result "The Hesper is a cutter with a hold full of nothing and a master with a hand like a ham, and she takes five days to do what the Dorothea did in five, with a good deal less conversation. At Tolleth she puts you on the quay without a word, and is gone before you have your feet.".
  }

  // ── A voice: the ranger at the creek ────────────────────────────────────────────────────────────────────────────
  Relation vCreek(group).
  Rule voice_creek at mangrow_creek when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, mangrow_creek) and not vCreek(party)
    says "{?m} stands in the green glare with a hand on a trunk and looks up it. 'There,' {?m} says, to nobody. 'White underleaf. That one weeps. If the man in the tree is right, that is the bark, and I do not need the House's stone room for a bale of it. I need an hour and a good knife and not to mind the biters.'" {
    Assert vCreek(party).
  }
}

data/adventures/the-dorothea/ness.kyr:
Module dorothea "The Dorothea" {
  Description "Port Ness: a salt island, flat as a table, eleven miles of pans and boiling-houses, forty lighters, and the counting-room of a house whose paper is on all the Reach. A long afternoon from Tolleth; a light on the point that has not been what it was since Lammas.".

  Place portness "Port Ness" is region.
  Place ness_town "Port Ness" is settlement within portness at 0, 0.
  Place ness_flats "the Ness flats" is wilderness within portness at 1, 0.
  Place ness_light_site "the Ness Light" is site within portness at 2, 0.
  Place counting_house "the House's counting-house" is building within ness_town.
  Place ness_quay "Port Ness pier" is room within ness_town at 0, 1.
  Place ness_row "Salt Row" is room within ness_town at 1, 1.
  Place counting_room "the counting-room" is room within counting_house at 2, 0.
  Place salt_pans "the salt pans" is room within ness_flats at 0, 0.
  Place ness_strand "the Ness strand" is room within ness_flats at 1, 0.
  Place ness_light_foot "the foot of the Ness Light" is room within ness_light_site at 0, 0.
  Place ness_lantern "the Ness Light's lantern" is room within ness_light_site at 1, 0.

  Passage ness_pier_way "the pier road" is path between ness_quay and ness_row taking 5 minutes.
  Passage counting_door "the counting-house door" is door between ness_row and counting_room
    opening when not marked(party) "The counting-house door is shut and bolted, and the brass plate has been turned to the wall. Somebody inside has been told about you.".
  Passage pans_way "the causeway through the pans" is path between ness_row and salt_pans taking 15 minutes.
  Passage strand_way "the sea-wall path" is path between salt_pans and ness_strand taking 10 minutes.
  Passage light_way "the cliff path to the Ness Light" is path between ness_row and ness_light_foot taking 30 minutes.
  Passage light_stair "the Ness Light stair" is passage between ness_light_foot and ness_lantern.

  // Everywhere on this island, for a rule that asks where the company is.
  Query onNess(g: group) means at(g, ness_quay) or at(g, ness_row) or at(g, counting_room) or at(g, salt_pans) or at(g, ness_strand) or at(g, ness_light_foot) or at(g, ness_lantern) or at(g, holm_beach) or at(g, holm_stump).

  Observe ness_quay_scene at ness_quay when true "Port Ness pier. Salt lighters lie three deep, black flat barges with their sides white to the waterline, and a gang of women in rag gloves are shovelling a white mountain down a chute into a barn. The smell is boiled brine, coal smoke, and under it the sweet rot of wrack. Every sack has a key-and-ring stencilled on it, and the stencil is newer than the sacks.".
  Observe ness_row_scene at ness_row when true "Salt Row: a street of low houses whitened to the eaves by the blown salt, every window glazed with a crust. A chandlery with a green door. At the end, the only house on the Row with a slate roof, and a brass plate beside its door that has been polished so often the letters have gone soft: THE HOUSE OF MARCHBANK, ORSETT. In the house-fronts there is the sound of raking, from the pans behind: steady as breathing.".
  Observe counting_scene at counting_room when true "A long panelled room with two high desks, a stove, and an iron-bound strongbox on a stone shelf. On the wall a chart of the coast under glass, with brass pins stuck in it like a surgeon's tray: a key-and-ring pin beside the Ness, one beside the Antlers, one by a speck of land marked THE HOLM. A fourth pin lies loose on the sill under the chart, beside SKERROW, and has not been pushed in yet.".
  Observe pans_scene at salt_pans when true "The pans: a hundred acres of shallow squares, clay-lined, each a different grey where the brine stands in it, the rakers moving along the dams with their long wooden rakes and their heads down. Steam from the boiling-houses lies over it like a lid. Behind every raker, set on a post, a tin disc stamped with a key-and-ring.".
  Observe strand_scene at ness_strand when true "The Ness strand: pale sand, wrack, and then a causeway of black stones going out across the flat towards a low hump of rock a mile away, with a stump of a tower on it. A tide-gauge on the sea-wall, painted in fathoms and in a hand-width of something older, shows where the water stands.".
  // The Wrack Road is dry for five hours in twelve (holm.kyr, phase of the tide). The strand says which hour it is.
  Observe strand_flood at ness_strand when phase(tide) >= 60 "The tide has just taken the Wrack Road. The black stones go down into green water a hundred yards out, and the gauge stands at the top of its marks. It will be a long wait. There is the pans, and the Row, and the light on the point.".
  Observe strand_high at ness_strand when phase(tide) < 20 "The sea is over the Wrack Road, a mile of it, heaving gently. The gauge stands high. The causeway will be bare again in the better part of half a day; the old gauge-marks, if you can read them, say how many hours.".
  Observe strand_ebbing at ness_strand when phase(tide) >= 20 and phase(tide) < 30 "The water is going off the Wrack Road: the first black stones are showing in the troughs, and the weed lies down on them like hair. An hour or two, and a man could walk it.".
  Observe strand_dry at ness_strand when phase(tide) >= 30 and phase(tide) < 55 "The Wrack Road lies bare from the sea-wall to the Holm, wet and shining, with pools in the hollows and a gull walking it. The gauge is down to its lowest mark. It will not stay so: those who cross had best be back, or be ready to stay.".
  Observe strand_turning at ness_strand when phase(tide) >= 55 and phase(tide) < 60 "The Wrack Road is still bare, but the water is lipping at the seaward stones, and it is coming faster than it looks. Anyone on the Holm who means to be back by dark should be on the road now.".
  Observe ness_foot_scene at ness_light_foot when true "The Ness Light: a round stone tower the height of three houses on the end of the point, with a stove-chimney at its foot, a hen run, and a stair you can see through the cracks. The wind has a habit of leaning on it. Over the door someone has chalked a tally of nights: a row of strokes, and the last few of them not struck through.".
  Observe ness_lantern_scene at ness_lantern when not lampLit(lamp_ness) "The lantern of the Ness Light: glass cloudy with salt, an iron lamp the size of a bucket, a smell of fish-oil and cold wick. The reservoir is nearly dry. Somebody has been burning rush-lights in a saucer in the middle of the great lamp, and the saucer is black.".
  Observe ness_lantern_lit at ness_lantern when lampLit(lamp_ness) "The lantern of the Ness Light: the glass wiped clear, the reservoir full, the great lamp burning with a hard white flame that throws the room's shadow out over the flats. Kit Skail has set a hen on the sill, and the hen does not mind.".

  // ── The factor, and the clerk ───────────────────────────────────────────────────────────────────────────────────
  Person thane "Ysolde Stannard" at ness_row {
    Role "factor of the House of Marchbank (the Orsett factor), come to Port Ness for the pans". Ancestry human. Level 3. Peaceable. Pronouns she. Manner acerbic.
    Likeness "merchant".
    Greets "A woman of fifty in a plain dark dress stands on the step of the counting-house with a red-bound book under one arm, counting lighters as they pull out. She counts them all, and her lips do not move. 'Ysolde Stannard,' she says. 'Factor, of the House of Marchbank. Orsett is my seat; I come to Port Ness for the pans, as a bishop to a bad parish. Is it salt you want, or a signature?' The red of the book is the red of a good cherry, and she holds it the way some women hold a child.".
    Greets again "Ysolde Stannard is on the step of the counting-house with the red book under the other arm. She has counted the lighters again, and the number has not changed. 'I remember you,' she says. 'You are one of the ones I have not entered.'".
  }
  Person pym "Ewart Pym" at counting_room {
    Role "clerk to the Factor at Port Ness". Ancestry human. Level 1. Peaceable. Pronouns he. Manner stoic.
    Likeness "scholar".
    Greets "A thin young man with ink to the elbow and a blue cuff on his right sleeve sits at the high desk with a blue-bound day-book open before him. He gets down off the stool a good deal too fast. 'Ewart Pym, Clerk,' he says. 'I only copy. If it is anything about the salt, it is the Factor, on the step. If it is anything about anything else, it is also the Factor.'".
    Greets again "Ewart Pym drops off the stool again, a degree faster than before. 'I only copy,' he says, 'it is all I am for. I copied your name in the blue book yesterday. I have not copied it into the other.'".
  }
  Person auld "Dunstan Auld" at salt_pans {
    Role "reeve of the Port Ness rakers". Ancestry human. Level 2. Peaceable. Pronouns he. Manner stoic.
    Likeness "farmer".
    Greets "A heavy man with salt-cracked hands and the squint of one who has looked at white ground all his life leans on a rake at the end of the nearest dam. 'Auld,' he says. 'Reeve. That means I go and tell the Factor when they are tired, and then I go and tell them she's said no.' He taps a tin disc on its post. 'You'll not be paid in coin on this island, mind. Not unless you're passing through.'".
    Greets again "Dunstan Auld taps the tin disc on its post as if to be sure it has not been taken. 'Reeve,' he says again, though he has already said it. 'Tired, all of them. She says no. You have caught me between the two.'".
  }
  Person skail "Kit Skail" at ness_lantern {
    Role "keeper of the Ness Light". Ancestry human. Level 2. Peaceable. Pronouns she. Manner proud.
    Likeness "abbess".
    Greets "A very old woman in three cardigans and a man's cap is sitting on the lamp-room floor with a saucer of rush-lights, which she is trimming with a pair of nail-scissors. 'Go careful on the stair,' she says. 'I've swept it. No one comes. It is a thing I do for the look of the thing.' She puts one rush-light in the saucer and watches it as other people watch a sleeping child. 'It isn't much,' she says. 'It's what there is.'".
    Greets again "Kit Skail looks up from the saucer, and the rush-light in her fingers does not waver. 'The stair is swept,' she says. 'You will have noticed. It is a thing I do. Nobody has noticed in thirty years, so I do it twice as thoroughly.'".
  }
  Initially Set quantity(thane, gold) to 90. Initially Set quantity(pym, gold) to 2.

  // ── The ranks of the House, as learnt on a stool in a counting-room ─────────────────────────────────────────────
  Relation knowsRanks(group).
  Topic pym_ranks with pym "Ask Ewart Pym how the House is arranged" when true once {
    Says "'Five ranks,' says Pym, glad to be asked something he is allowed to answer. 'Prentice, in grey boards: she keeps the day-book on an island, and mostly nobody reads it. Clerk, in blue, which is me: we copy the day-book into the ledger. Agent, in green: he keeps a post, and gives the orders on it. Factor, in red: she keeps a coast, and answers for the sums. And the Principal, in Orsett, whose book is black, and nobody I know has seen it, only the seal.' He touches the blue cuff. 'Each owes the one above and is owed by the one below. It is how you know where you are, in a House.'".
    On discuss { Assert knowsRanks(actor). }
  }
  Topic pym_house with pym "Ask Ewart Pym what the House does on the Reach" when true once {
    Says "'Salt, here,' says Pym. 'Down, eggs, and fat, at the Antlers; the landing at Skerrow; the carrying, that's the Dorothea. And the lights.' He stops. 'The paper on the lights is a sort of ground-rent. I don't write that book. The Factor writes that book.'".
  }
  Topic thane_salt with thane "Ask Ysolde Stannard about the salt" when true once {
    Says "'It is the one honest thing on the coast,' says Stannard. 'Sea, sun, and a woman with a rake. I pay the rakers in the House's scrip because coin goes to the Row's alehouse and scrip goes to the House's chandlery and the House's chandlery gets them through a winter. You may call that a system. I do.' She turns a page without looking at it. 'The fleet is in tonight. You'll hear it.'".
  }
  Topic thane_lights with thane "Ask Ysolde Stannard about the Ness Light" when true once {
    Says "'Kit Skail keeps it, on the House's oil, on the House's book,' says Stannard. 'The book has been closed since Lammas. Eighteen crowns, in her debit. Eighteen is what it was, so eighteen is what I wrote. I am not paid to be sorry in a margin.' She looks at the point, where the tower stands with its small, sour flame. 'Nobody steers by the Ness Light. They steer by the pans. They've steered by the pans since before the House had a name.'".
  }
  Topic auld_scrip with auld "Ask Dunstan Auld about the tin discs" when true once {
    Says "'Scrip,' says Auld. 'A rake a day is a disc. Ten discs and the House's chandlery gives you a sack of meal. You can't take a disc to the Row's ale-house, and you can't take it to Tolleth. You can take it to the chandlery.' He looks at the disc on the post. 'We'd not have starved. But we'd not have owned a boat, either. There's forty lighters at Port Ness and not a one of them is a raker's.'".
  }
  Topic auld_fleet with auld "Ask Dunstan Auld about the fleet and the Mary Ann" when true once {
    Says "'Fleet's the same forty boats it's been all my life,' says Auld. 'We lose one every year or two. This year the Mary Ann, on the Combs, at Lammas; and the Rosa Lind on the Holm bar, on a clear night. A clear night.' He rakes a stroke, and another. 'There was no light on the Holm. There never is. But there was a light at the Ness, and Kit Skail's, and she was trimming it. We saw it. It was out by midnight.'".
  }

  // ── The Ness Light: Kit Skail's bond ────────────────────────────────────────────────────────────────────────────
  Topic skail_light with skail "Ask Kit Skail about the light" when true once {
    Says "'The House gave me the oil on the quarter's book for forty years,' she says. 'Since Lammas the book is shut. Eighteen crowns, and Mr Pym says there's a bond on it, in the strongbox, with my mark.' She puts the nail-scissors down. 'I don't know what a bond is. I put my mark on a paper when my husband died.' She looks at the saucer. 'Rush-lights don't throw. It's like trying to light a coal-hole with a match.' She turns the saucer. 'Fish-oil smokes the glass. The Skerrow people burn something white that doesn't. Mab, the Dorothea's cook, says there is a store of it under their tower, for whoever asks right. I have never been to Skerrow. I have never been anywhere I couldn't walk back from.'".
  }
  Topic skail_wrecks with skail "Ask Kit Skail what she saw the night the Rosa Lind went" when true once {
    Says "'A clear night,' says Kit Skail, 'and the Ness gone out because my oil gave. You can see the Holm bar from the lantern on a clear night, if there's a light to see by. I saw her lights go down on it like a row of stars being let fall.' She does not weep. 'Forty-one hands. Five were Ness men. I know all their mothers.' She picks up the scissors again. 'There's a man of the House who comes on the quarter-day with a barrow, for salvage. He doesn't look at me.'".
  }

  // ── Setting the Ness Light free of the House's book ─────────────────────────────────────────────────────────────
  // Five ways: pay the bond, fill the lamp with the Pharos's oil, lay the reckoning before the Factor, take the
  // bond out of the strongbox, or have the House's own book exposed on the Tolleth quay (house.kyr). Each puts
  // the Ness Light out of the House's keeping and lights it.
  Action pay_skail_bond(actor: group, site: place) "Pay Kit Skail's eighteen coin at Pym's desk, and have the bond cancelled" {
    Description "The House does not forgive a debt. It does take it paid.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, counting_room) and at(pym, site) and houseHolds(lamp_ness) and quantity(actor, gold) >= 18.
    Time 2.
    On success { Decrease quantity(actor, gold) by 18. Increase quantity(pym, gold) by 18. Retract houseHolds(lamp_ness). Assert lampLit(lamp_ness). Increase freed(actor) by 1. Assert nessPaid(actor). }
    Result "Pym counts the coin with his lips moving, finds it right, and writes PAID in the margin of a page in the blue book. He opens the strongbox, takes out a stiff paper with a thumb-mark on it, and tears it across, once, and again, in a way he has not done before. 'I am not to do that without the Factor,' he says. 'I find I am doing it.'".
  }
  Relation nessPaid(group). Relation nessOiled(group). Relation nessBond(group).
  Action oil_ness_light(actor: group, site: place) "Fill the Ness Light's lamp from a keg of the Pharos's oil" {
    Description "Marren Kestle trims a lamp that burns clean. A keg of what she burns would last the Ness Light a winter.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ness_lantern) and houseHolds(lamp_ness) and holding(actor, dorothea_oil_keg).
    Time 3.
    On success { Spend dorothea_oil_keg from actor. Retract houseHolds(lamp_ness). Assert lampLit(lamp_ness). Increase freed(actor) by 1. Assert nessOiled(actor). }
    Result "Kit Skail takes the stopper out, and smells it, and shuts her eyes. 'That is not fish,' she says. You help her tip it into the reservoir, and she trims the wick with the nail-scissors, and strikes a light. The flame stands up white, and does not lean. 'There,' she says. 'Let the House send a man to say it is not on the book.'".
  }
  Action lift_ness_bond(actor: group, site: place) "Take Kit Skail's bond out of the Factor's strongbox" {
    Description "The Factor is on the step, and the clerk is at his desk. A strongbox is a strongbox. A bond is a piece of paper.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, counting_room) and houseHolds(lamp_ness) and capable(actor, lockwork).
    Time 4.
    Resolve check(actor, lockwork, dc_hard).
    On success { Retract houseHolds(lamp_ness). Assert lampLit(lamp_ness). Increase freed(actor) by 1. Assert nessBond(actor). Assert missingBond(actor). }
    On failure { Assert marked(actor). Retract at(actor, counting_room). Assert at(actor, ness_row). }
    Result "The lock has a second lever, set back under the first, such as a clerk would use who does not trust his Factor. You find it by the sound. The bond is on top, in a fold of the Factor's own paper: a thumb-mark, and a line of print. You put it in your sleeve and shut the lid without a click. Pym, who has been very carefully reading his day-book upside down, turns a page.".
    Otherwise "The lock bites, and the lid thuds, and Pym says, in a high small voice, 'Factor!' Ysolde Stannard's step is on the stair before the echo. 'The door,' she says, in a voice you will remember, 'will be bolted behind this company.' You are on the Row, with the door shut at your back, before you have decided to be.".
  }
  Relation missingBond(group).
  Topic kit_thanks with skail "Ask Kit Skail how the light is" when lampLit(lamp_ness) once {
    Says "'It throws,' says Kit Skail. She says it twice, to be sure. 'I went out at dusk and stood on the point and looked back, and it was a thing I had never done, not once in forty years, because I had always been in it. It goes right across the flats. It goes to the Holm.' She sits down on the step, and rises again at once. 'There is a man on the Holm who ought to know. I'll send the hen.'".
  }

  // ── The way home, if left ───────────────────────────────────────────────────────────────────────────────────────
  Observe ness_stranded at ness_quay when strandedNess(party) "The Dorothea is a smudge going north. At the end of the pier a salt lighter lies with its lines doubled, and a man in the stern calls out that she goes to Tolleth on the next tide, and that four coin is four coin.".
  Action take_the_lighter(actor: group, site: place) "Take a place on the salt lighter back to Tolleth, four coin" {
    Description "A black flat barge loaded to the gunwale with white. You will be the third-worst-smelling thing on her.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ness_quay) and not at(hull, ness_quay) and quantity(actor, gold) >= 4.
    Time 24.
    On success { Decrease quantity(actor, gold) by 4. Retract at(actor, ness_quay). Assert at(actor, quay). Retract strandedNess(actor). }
    Result "The lighter goes out on the ebb and comes in on the flood, white to the gunwale and salt to the eyebrows. The Tolleth quay is exactly where you left it.".
  }

  // ── The Port Ness leaf: the Clerk's day-book ────────────────────────────────────────────────────────────────────
  Action pay_pym_to_turn(actor: group, site: place) "Pay Ewart Pym three coin to find a reason to be at the stove" {
    Description "A clerk's honesty is a thing of the price he is offered and the Factor he fears.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, counting_room) and at(pym, site) and not leafNess(actor) and quantity(actor, gold) >= 3.
    Time 2.
    On success { Decrease quantity(actor, gold) by 3. Increase quantity(pym, gold) by 3. Assert leafNess(actor). Increase leaves(actor) by 1. Assert knows(actor, leaf_ness_d). }
    Result "He takes the coin as if it were hot, turns the blue book on its slope so that the light from the window falls on it, and walks to the stove and has a great deal to see to in it. You read: salt, and sacks, and a column headed LUM., and a column headed W.R. When you look up he is still poking the stove, and the back of his neck is red to the collar.".
  }
  Action ask_pym_plainly(actor: group, site: place) "Tell Ewart Pym what a clerk's book is for, and ask to read it" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, counting_room) and at(pym, site) and not leafNess(actor).
    Time 3.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert leafNess(actor). Increase leaves(actor) by 1. Assert knows(actor, leaf_ness_d). }
    Result "You say that a book is the only thing in the House that has to tell the truth, because everything else is made of it. Pym looks at his cuff. 'I copy it,' he says. 'I copy it fair. I have never been asked to read it to anyone.' He turns the book round. His hand, when he lets go of it, shakes only a little. You read.".
    Otherwise "'The Factor,' says Pym, wretchedly, 'is on the step.'".
  }
  Topic stannard_reckoning with thane "Lay the House's reckoning before Ysolde Stannard" when reckoned(actor) and houseHolds(lamp_ness) once {
    Says "She reads your copy standing, and her mouth does not move. At the end of it she closes the red-bound book very softly, and gives it to Pym. 'You are right,' she says. 'I have been in the House thirty years and never done the sum.' She looks at the point, where the little flame stands. 'I cannot undo the House. I am a Factor. I can undo a bond.' She goes into the counting-room herself, and the bond is torn across before the company has crossed the Row. 'The Principal will hear of it,' she says, from the step. 'Not from me. I should like to see his face when he reads the Port Ness book. Go and light your lights.'".
    On discuss { Retract houseHolds(lamp_ness). Assert lampLit(lamp_ness). Increase freed(actor) by 1. }
  }
}

data/adventures/the-dorothea/night.kyr:
Module dorothea "The Dorothea" {
  Description "The second night on Skerrow: the men who come for the bronze, the paper on the Gull's wall that nobody has read, the lens, and the boy who is out in the weather when the lamp is dark.".

  // ── The paper nobody has read ───────────────────────────────────────────────────────────────────────────────────
  // The Gull's framed paper is the island's oldest document and its least consulted. It is in two hands and a dead
  // language, and the module never translates it: the company is told what Quint will say of it and no more. The device
  // in its corner is a mark of keeping and is never glossed here.
  Discovery receipt_seen "On the wall of the Gull's kitchen hangs a framed paper nobody on Skerrow has read in living memory: two hands, one of them very formal, and in the corner a small device, a fish with a flame over it." {
    }
  Discovery receipt_read "Odile Quint has read the Gull's framed paper aloud, and will say of it only that it is not a lease, that the upper hand is a clerk's and the lower is not, and that she would not hang it where the kitchen steam reaches.".
  Topic gull_paper with gull "Ask Hester Gull about the framed paper on the wall" when true once {
    Says "'The lease,' says Hester Gull. 'Or the charter. Or the will of somebody. Marren says it's a lease and Jory says it's a joke and my mother said it was the first thing the island ever owned, and that's why it's framed.' She wipes the glass with her apron, which has not been done in years. 'Foreign, I'm told. My mother thought it was Aenean and my father thought it was a joke, and the glass has outlived the pair of them.'".
    On discuss { Assert knows(actor, receipt_seen). }
  }
  Topic quint_receipt with quint "Ask Odile Quint to read the paper on the Gull's wall" when knows(actor, receipt_seen) once {
    Says "She stands in front of it with her hands behind her back for a time that Hester Gull plainly finds improper, and then she reads it aloud, a line at a time, in a language the kitchen has not heard since the frame was bought. Hester Gull sits down. When Quint has finished she is quiet. 'It is not a lease,' she says. 'It is not a charter either. I will not give you a translation, because I would be improving it, and the one thing I am sure of is that it was not written to be improved.' She looks a moment longer at the small device in the corner. 'Hang it where the steam does not reach.'".
    On discuss { Assert knows(actor, receipt_read). }
  }
  Observe device_seen at pharos_foot when true "Cut small into the keystone of the arch, worn almost smooth by two thousand winters of salt: a fish, and over it a flame. You have seen it before, you think, or something very like it, on the iron foot of a lamp-stand in a place you cannot at once name." teaches device_known.
  Discovery device_known "A fish, and over it a flame: the device cut on the keystone of the Pharos on Skerrow, and on the lamp-stand of the Holm Lantern on the Gannet Reach, and on the ring of the great lens.".

  // ── The lens ────────────────────────────────────────────────────────────────────────────────────────────────────
  // The reflector is bronze and is Quillon's to buy. The lens is something else: green, heavy, set in a ring that is
  // marked, with stones round its rim and an empty socket among them. Marren will
  // not give it to a stranger who asks, because a stranger is not who was foretold. She will give it to a Watch's
  // tally, which she has never seen and will know.
  Topic kestle_lens with kestle "Ask Marren Kestle about the green lens" when true once {
    Says "'It is not ours,' says Marren Kestle. She says it at once, as if she had practised, in her bed, for years. 'My grandmother's grandmother kept the lamp for it. We were told that it was a lamp to be kept, not a lamp to be given, and that someone would ask for it, and that we would know them.' She looks at the green glass with something that is not fondness. 'I thought it would be a soldier. I thought it would be someone with a seal. I have been wrong about a number of things in my life, but I have never been so wrong as I am about that.'".
    On discuss { Assert knows(actor, lens_asked_for). }
  }
  Discovery lens_asked_for "Marren Kestle keeps the lens of the Pharos as a lamp to be kept and not given, until someone she will know comes to ask for it.".
  Item lens "the green lens of the Pharos" is pharos_lens at nowhere owned by kestle.
  Relation lensGiven(group).
  Topic kestle_give_lens with kestle "Show Marren Kestle the Watch's tally-stick" when holding(actor, watch_tally) and not lensGiven(kestle) once {
    Says "She takes it in both hands. She counts the notches with her thumb, aloud, to eleven, and stops, and her thumb stays on the blank. 'I knew it would be wood,' she says. She does not weep. She goes up the stair to the lamp room, and you hear her up there for a quarter of an hour, doing a thing with a spanner that she has not done in thirty years, and when she comes down she is carrying the lens against her chest like a sleeping child. 'Tell them it was kept,' she says. 'Tell them it was kept the whole time.' She puts it into your arms. It is warmer than glass has any right to be. 'The lamp will burn without it,' she says. 'Not as far.'".
    On discuss { Give lens to actor. Assert lensGiven(kestle). }
  }
  Observe lamp_dimmer at pharos_lamp when lensGiven(kestle) "The lamp burns in the lamp room as it always did. It does not throw as far. The window seems to have more dark in it than a window should.".

  // ── The men who come for the plate ──────────────────────────────────────────────────────────────────────────────
  // Signed, the paper is not yet done. It is done when two of Quillon's men have been up the hill with a bar, and a
  // barrow, and have been let. They can be stopped. They are not wicked; they are paid by the barrow.
  Person quillon_men "Quillon's hired men" at nowhere {
    Role "two hired men with a barrow and a bar". Ancestry human. Calling warrior. Level 2. Numbers 2. Temperament territorial.
    Warns "Two men are standing in the doorway of the Pharos with a barrow between them and a bar over one shoulder. The taller one looks at you as a man looks at a fence that is not his and may be in the way.".
    Comes "The taller man lowers the bar to the horizontal and says, quite politely, 'We've been paid for the plate. Don't make it into a thing.'".
  }
  Relation voided(group). Relation plateTaken(group). Relation menCame(group). Relation islandCalled(group).
  Rule men_come when marlSold(party) and not menCame(party) and watch(clock) >= reachedAt(hull) + 138
    says "At dusk two of Quillon's men go up Pharos Hill with a barrow and a bar. Marren Kestle is standing at the tower door with the trimming-knife in her hand, and has not used it, and does not look as if she will." {
    Assert menCame(party). Retract at(quillon_men, nowhere). Assert at(quillon_men, pharos_foot).
  }
  Action bluff_the_men(actor: group, site: place) "Tell Quillon's men the plate is an Aenean antiquity under the Collegium of Measures' claim" {
    Description "A man paid by the barrow does not read the paper he is carrying a plate for. He reads the face of whoever tells him it is not his to take.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pharos_foot) and at(quillon_men, site) and not voided(actor) and not plateTaken(actor).
    Time 2.
    Resolve check(actor, deception, dc_fair).
    On success { Assert voided(actor). Retract at(quillon_men, pharos_foot). Assert at(quillon_men, green). }
    Result "You say it as one says a thing that is not a lie, and then one more thing, and the taller man's face does the sum. 'Collegium,' he says, to the other. 'Antiquity.' 'We were hired for scrap,' says the other. They look at the plate and the barrow and at you and at Marren Kestle's knife, which is now quite slightly higher. They put the bar down. 'We'll go and ask Mr Quillon,' says the taller man. 'He'll be wanting to know what a Collegium is.'".
    Otherwise "The taller man listens politely to the end. 'Is that so,' he says. 'And I'm the Prefect.'".
  }
  Action call_the_island(actor: group, site: place) "Go down to the green, and call the island up the hill" {
    Description "Forty-one people. Most of them would never lift a hand to a neighbour's hired man, and all of them have a view.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pharos_foot) and at(quillon_men, site) and not voided(actor) and not plateTaken(actor) and not islandCalled(actor).
    Time 6.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert islandCalled(actor). Assert voided(actor). Retract at(quillon_men, pharos_foot). Assert at(quillon_men, green). }
    Result "You go down to the green and say it to Hester Gull, who says it to the Gull, who says it to the lane, and they come up the hill by ones and twos with their lanterns and their boy-children, not to do anything, only to stand there in a half circle on the grass, forty-one people with their arms folded. The taller man looks at the half circle for a long time. 'It's a great deal to ask for sixty down,' he says, at last, and picks up his bar.".
    Otherwise "You say it to the Gull, and the Gull listens, and says that Jory has signed, and that a signature is a signature, and goes back to its tea.".
  }
  Rule plate_taken when menCame(party) and not voided(party) and not plateTaken(party) and watch(clock) >= reachedAt(hull) + 150
    says "By nightfall the plate is off the wall, and the reflector off its mount, and the barrow is going down the hill on its one wheel, ringing, ringing, ringing off every stone. The lamp room window is dark." {
    Assert plateTaken(party). Assert tableSold(party). Assert lampOut(party).
  }
  Rule sale_voided when voided(party) and marlSold(party) and not keptLamp(party)
    says "At the Gull Silas Quillon is told what happened on the hill. He closes the ledger, and after a while opens it again, and draws a line through a number. 'I do not enjoy being wrong in public,' he says. 'I enjoy it somewhat less when it was a lighthouse.'" {
    Assert keptLamp(party). Retract marlSold(party). Retract at(marl, gull_room).
  }

  // ── The night the lamp is for ──────────────────────────────────────────────────────────────────────────────────
  // Marren said it is for whoever is out there tonight. On the second night someone is: Jory's eldest, fourteen, has
  // gone out in the boat for the pots at the turn of the weather. If the lamp is lit he is brought home by it, and
  // that is the whole of the lamp. If it is dark, a company that is awake can do something about it, in four ways.
  Place off_skerrow "the black water off Skerrow" is room within lane at 4, 0.
  Person wen "Wen Kestle" at kestle_house {
    Role "Jory Kestle's eldest, fourteen". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "A long boy, all wrists, with his father's shoulders not yet arrived. 'You came on the Dorothea,' he says. 'Is it true she's got a gun? Da says no, but Da says no about most things.'".
    Greets again "Wen Kestle has been practising a very grown-up expression and drops it when he sees you. 'Is it true she's got a gun?' he says. 'You said you'd tell me. You didn't. Da said you wouldn't. Da is usually right and I am sick of it.'".
  }
  Place kestle_house "Jory Kestle's house" is room within hamlet at 2, 1.
  // Wen is a boy with a boat and a grievance, and he says so a day before it matters.
  Topic wen_pots with wen "Ask Wen Kestle about the pots he has set" when true once {
    Says "'Eleven pots on the black rocks, off the point,' says Wen, 'and Da says leave them till the weather settles, because Da says leave everything.' He scowls at the stove. 'The glass has been going down since the Dorothea came in. If it turns I'll have to get them in tonight, or the sea will, and then it's a winter of cold porridge. I can see the rocks from the hill. The light's on them, if it's lit. It's the one thing it's good for, Da says, and then he says he didn't say it.'".
  }
  Passage kestle_door "Jory Kestle's door" is door between green and kestle_house.
  Observe kestle_scene at kestle_house when true "Jory Kestle's house: one room, four beds in two tiers, a table with a net spread over it, a stove, a framed picture of a woman in a cap with the glass cracked across and mended with a strip of tape. The children's boots stand in a row from big to small.".
  Relation stormOn(group). Relation wenOut(group). Relation wenSafe(group). Relation wenLost(group). Relation beaconLit(group). Relation shipLit(group).
  Rule storm_rises when arrived(hull) and not stormOn(party) and not wenSafe(party) and watch(clock) >= reachedAt(hull) + 152
    says "The wind goes round in the evening, as it does on Skerrow when it has finished with the sea and means to start on the land, and the rain comes in flat. Down at the jetty the Dorothea's lines groan. Somewhere on the green a woman is shouting a boy's name into the weather. The island's pot-boat is gone from the shingle." {
    Assert stormOn(party). Assert wenOut(party). Retract at(wen, kestle_house). Assert at(wen, off_skerrow).
  }
  Observe storm_green at green when stormOn(party) and wenOut(party) "It is a black night and a roaring one. Jory Kestle is at the end of the jetty with a lantern that keeps going out, calling, and the island is standing behind him in its oilskins, not speaking.".
  // What each place offers on that night, said where the company stands, so that it is not a puzzle to find.
  Observe storm_hill at hill_path when stormOn(party) and wenOut(party) and lampOut(party) "The wind comes over the shoulder of the hill like a hand. Below you the whole black water lies open, and a fire up here, in the lee of the wall, would be seen from every rock off the point. The island's driftwood is stacked under the wall. The oil is under the tower.".
  Observe storm_jetty at jetty when stormOn(party) and wenOut(party) and lampOut(party) "The island's second boat is drawn up on the shingle with a lantern lashed in her bows. Jory Kestle stands at the end of the jetty with another and does not look round. Out in this a man might find a boy. He might as easily be a second thing for the island to look for.".
  Observe storm_helm at helm when stormOn(party) and wenOut(party) and lampOut(party) and arrived(hull) "From the wheel the Dorothea's yards are bare black spars and her lanterns are in their locker. The little gun is under its tarpaulin on the rail. Bascom is looking at the jetty, and at Jory Kestle's one small light on it, with her pipe gone cold.".
  Observe lamp_lit_night at green when stormOn(party) and wenOut(party) and not lampOut(party) "High on the hill, the Pharos is burning. It does not seem to notice the weather. It goes out over the water in a long hard road, and the road goes a long way out.".
  Rule wen_comes_by_the_light when stormOn(party) and wenOut(party) and not lampOut(party) and not wenSafe(party) and watch(clock) >= reachedAt(hull) + 166
    says "A small black shape comes up out of the dark on the long road of the lamp: a boat, with a boy at the oars who is crying and laughing and has lost his cap. Jory Kestle wades out to his waist and takes the bow-line out of his son's hand. Marren Kestle has come down the hill in her oilskins, and she stands at the edge of the lantern-light and looks at the boy and does not say a word. After a time she says, to nobody, 'That is what it is for.'" {
    Assert wenSafe(party). Retract wenOut(party). Retract at(wen, off_skerrow). Assert at(wen, jetty).
  }
  Action light_beacon(actor: group, site: place) "Build a beacon of the island's driftwood and oil on the hill" {
    Description "A fire the weather cannot put out is a thing that takes wood, and oil, and a person who has built one before.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hill_path) and stormOn(party) and wenOut(party) and lampOut(party) and not beaconLit(actor) and not shipLit(actor).
    Time 6.
    Resolve check(actor, woodcraft, dc_fair).
    On success { Assert beaconLit(actor). Assert wenSafe(actor). Retract wenOut(actor). Retract at(wen, off_skerrow). Assert at(wen, jetty). }
    Result "You pile the island's driftwood in the lee of the wall, the dry under the wet, and soak it with the lamp-oil from the tower store, and the third attempt takes. It goes up with a roar that is a kind of joy. A quarter-mile out on the black water a small light that had been going the wrong way turns, and comes in. Marren Kestle has watched you do it from the tower door with the trimming-knife hanging from her hand. 'It's not the lamp,' she says. 'But it's the right idea.'".
    Otherwise "The wood is wet, the wind is round the wrong side, and what you get is a column of smoke and a smell. You will have to try again with something that burns.".
  }
  Action light_the_ship(actor: group, site: place) "Ask Captain Bascom to hang every lantern the Dorothea has from her yards, and fire her gun" {
    Description "The Captain's oil is the Captain's. A ship lit like a church can be seen a long way. It will cost her.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, helm) and at(bascom, helm) and stormOn(party) and wenOut(party) and lampOut(party) and not beaconLit(actor) and not shipLit(actor).
    Time 2.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert shipLit(actor). Assert wenSafe(actor). Retract wenOut(actor). Retract at(wen, off_skerrow). Assert at(wen, jetty). Decrease cargo(hull) by 3 or to nothing. }
    Result "'It's lamp-oil,' says Captain Bascom, 'and the Orsett man counts it,' and then she looks at Jory Kestle at the end of the jetty with the lantern and says a word you will not repeat. She goes up the shrouds like a girl. In ten minutes the Dorothea is lit from deck to truck like a church at Easter, and Rune fires the gun, and the sound goes out over the black water, and in the wake of it a small voice a long way off, a boy shouting, cracked with cold, is answered. Bascom comes down, wet through. 'Three casks,' she says. 'I'll have it off somebody.'".
    Otherwise "'My oil,' says Bascom, 'is the only thing between me and the Orsett man's attorney.' She looks at the water. She does not look at you.".
  }
  Hazard gale "The gale off Skerrow" means "Deal (2d6) physical damage to ally unless dexterity save against (14).".
  Action row_out(actor: group, site: place) "Take the island's boat out into the weather with a lantern, and look for the boy" {
    Description "In a gale, in the dark, off a rock. It is the thing most likely to drown a second person.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, jetty) and stormOn(party) and wenOut(party) and lampOut(party) and not beaconLit(actor) and not shipLit(actor).
    Time 12.
    Resolve check(actor, wayfinding, dc_hard).
    On success { Assert wenSafe(actor). Retract wenOut(actor). Retract at(wen, off_skerrow). Assert at(wen, jetty). }
    On failure { Assert strikes(gale, party). }
    Result "You take the boat out past the jetty with a lantern between your knees and the sea coming over the bow, and for what feels like a day you row at nothing, and then a boy is shouting, off to starboard, and a dark thing is a boat, and you have him by the collar. Jory's lantern at the jetty is a low yellow star. You do not know how you get back. You do.".
    Otherwise "The sea takes the oar, and the boat, and a good part of your afternoon. You come back to the jetty on your hands and knees, with someone else's lantern and no boy.".
  }
  Rule wen_lost when stormOn(party) and wenOut(party) and not wenSafe(party) and not wenLost(party) and watch(clock) >= reachedAt(hull) + 200
    says "At the end of the jetty Jory Kestle lowers the lantern. It is not a decision. His arm is tired. The island has gone indoors with its lanterns, and presently Marren Kestle goes up the hill in her oilskins to the dark tower, and the dark tower swallows her." {
    Assert wenLost(party). Retract wenOut(party). Retract at(wen, off_skerrow). Assert at(wen, nowhere).
  }
  Observe grief_green at green when wenLost(party) "The island is very quiet. Jory Kestle sits on the sea-wall with his hands between his knees. The net is still spread over his table, half mended, as the boy left it.".
  Observe saved_green at green when wenSafe(party) and stormOn(party) "In the grey of the morning Jory Kestle is asleep on the jetty bench with a boy's head in his lap and an old man's coat over them both. The rain has stopped. The bench is too short for either of them, and neither moves.".
}

data/adventures/the-dorothea/placed.kyr:
Module dorothea "The Dorothea" {
  // Tolleth as a country: the company that comes down the coast road is the world's own.
  Entity party: group "Your company".
  Entity word: fact "What is said of Tolleth and the Skerrow passage in the country behind it.".
  Rule word_old when arrived(hull) and not stale(word) { Assert stale(word). }
  // The Founders' Exchange of the country this passage is in, when the world holds one: Quillon's buyer.
  Entity ring: group "The Founders' Exchange.".
  Entity ring_coast: group "The ring's man on the coast.".
  Entity ring_head: group "The ring's Principal.".
  Place abroad "Abroad" is room.
  Entity ledger_read: fact "A leaf of the ring's day-book has been read.".
  Entity lieutenant_named: fact "The ring's man on the coast has been named.".
  Entity principal_traced: fact "The ring's Principal has been traced.".
  Entity seal_seen: fact "The ring's seal has been seen.".
  Entity waybill_read: fact "A cellar waybill has been read.".
}

data/adventures/the-dorothea/port.kyr:
Module dorothea "The Dorothea" {
  Description "Tolleth, a salt-and-herring port at the end of a long road; the ketch Dorothea at her quay; and her calls: Skerrow, a night and a morning out, where a lamp has burned since before the roads; Port Ness, the salt; the Antlers, a night away among the stacks. All of it is the paper of a counting-house in Orsett.".

  // The port, the ship and the island are three places with no way between them on foot. The ship is a thing that is
  // at a place: the quay, then the Sound, open water, the Combs, the roads of Skerrow. The company, aboard, goes about
  // her deck and does not leave her; where she is, is a fact of the world, and the clock moves her.
  Place tolleth "Tolleth" is region.
  Place harbour "Tolleth harbour" is settlement within tolleth at 0, 0.
  Place road_wild "the coast road" is wilderness within tolleth at 0, 1.
  Place road_end "the end of the coast road" is room within road_wild at 0, 0.
  Place anchor_inn "the Anchor and Hope" is building within harbour.
  Place chandlery "Garrick's chandlery" is building within harbour.
  Place office "the harbourmaster's office" is building within harbour.
  Place quay "Tolleth quay" is room within harbour at 1, 1.
  Place taproom "the Anchor and Hope" is room within anchor_inn at 0, 1.
  Place shop "Garrick's chandlery" is room within chandlery at 2, 1.
  Place harbourmaster "the harbourmaster's office" is room within office at 1, 0.
  Place nowhere "nowhere" is room within road_wild at 9, 9.

  Passage coast_road "the coast road" is road between road_end and quay taking 30 minutes.
  Passage inn_door "the Anchor's door" is door between quay and taproom.
  Passage shop_door "Garrick's door" is door between quay and shop.
  Passage office_door "the harbourmaster's door" is door between quay and harbourmaster.

  Observe road_scene at road_end when true "The coast road comes down off the moor to a harbour the colour of slate, with a smell of tar and herring on the wind. Masts stand in it close as reeds, and beyond the harbour mouth a grey line that might be cloud or might be an island.".
  Observe quay_scene at quay when true "Tolleth quay: a curved stone wall, bollards worn to the shape of ropes, barrels in rows, gulls. A notice board outside the harbourmaster's door gives the tides and the sailings in chalk: ORSETT, WED. PORT NESS (SALT), SAT. THE ANTLERS, WHEN THE PILOT IS SOBER. SKERROW, THE NOON EBB (DOROTHEA). ASHKELD (STONE), THREE DAYS, WHEN THE HOUSE REMEMBERS. MANGROW (BARK), FIVE DAYS SOUTH, FEVER ALLOWING. Under it, in another hand and a different chalk, a column of names with a cross against each, and the heading LOST THIS YEAR: MARY ANN, THE COMBS, LAMMAS. ROSA LIND, THE HOLM BAR. TERN, THE ANTLERS RACE. A fourth line has been begun, and rubbed out, and begun again. Each sailing is chalked with a small key-and-ring at the end of its line, the way a brewer brands a cask.".
  Observe taproom_scene at taproom when true "A low taproom full of men with salt in their hair, and a fire that smokes when the wind is in the west. A slate by the door has names on it, and sums.".
  Observe shop_scene at shop when true "Garrick's: rope in coils like sleeping snakes, tar in kegs, oilskins on pegs, a rack of lead-lines. The smell is enough to give a landsman a headache and a seaman a sentimental turn.".
  Observe office_scene at harbourmaster when true "A narrow room with a tide-table on the wall as long as a man, a barometer that has not been believed since it was hung, and a ledger of sailings in a neat hand, ruled in two columns, the right-hand one headed in small capitals W.R. and not read.".

  Person bascom "Captain Ingrith Bascom" at quay {
    Role "master of the ketch Dorothea". Ancestry human. Calling ranger. Level 4. Peaceable. Pronouns she. Manner stoic.
    Likeness "sailor".
    Greets "A broad woman in a man's coat, a clay pipe unlit between her teeth, stands with her arms folded at the foot of the Dorothea's gangway, counting casks as they go up. She counts them again as you speak to her. 'Passage to Skerrow,' she says. 'A night and a morning if the wind holds, two days if it doesn't, and I don't discuss the other thing.'".
    Greets again "Captain Bascom has stopped counting casks, which is a sign that all the casks are counted. 'Passage,' she says, round the pipe, 'and no discount for knowing me.' 'The tide waits for no one, and I am the tide's friend.'".
  }
  Person pellow "Wat Garrick" at shop {
    Role "chandler". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Sells rope for 1 coin from 4. Sells rations for 2 coin from 6. Sells torch for 1 coin from 6.
    Sells dorothea_netting for 2 coin from 4.
    Greets "Wat Garrick looks up from a coil he is whipping, and at your boots, and says that nobody goes to Skerrow in those, and then sells you something.".
    Greets again "Wat Garrick holds up a pair of boots, not yours, and shakes them to be sure they have no sea in them. 'Better,' he says, with approval. 'Now you look like someone who has been told what to buy.'".
  }
  Person harbourman "Dacey Hoe" at harbourmaster {
    Role "harbourmaster". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "Dacey Hoe does not look up from the ledger. 'Sailings are chalked on the board,' she says. 'The Dorothea goes on the noon ebb, Bascom's never missed a tide in her life and has no intention of starting on yours.'".
    Greets again "Dacey Hoe has rubbed out the Dorothea's time and chalked it in again an hour earlier, without comment. 'There,' she says. 'Now it is right. It was always right. I have only changed it to what it ought to be.'".
  }
  Person drinkers "the Anchor's regulars" at taproom {
    Role "seamen and pilots' men". Ancestry human. Numbers 4. Peaceable.
  }
  Topic drinkers_skerrow with drinkers "Ask the regulars about Skerrow" when true once {
    Says "'A night out, and nothing on it but sheep and a lamp,' says a man with one eye. 'The lamp's the Aeneans'. It's been lit since before there was a Tolleth, and the Kestles have trimmed it, father to son, and never once been thanked.' 'The Combs are what you want to mind,' says another. 'Not the sea, the Combs. They've a name for a ship that doesn't make the passage on the morning flood.' He doesn't say what the name is.".
  }
  Topic drinkers_bascom with drinkers "Ask the regulars about Captain Bascom" when true once {
    Says "'Honest,' says the one-eyed man, in the tone of a man giving a bad report. 'Owes the salt-factor in Orsett sixty crowns for the Dorothea's new keel, and the factor's wife's brother has the island lease. She'll make the passage if it kills her.' He drinks. 'It might.'".
  }

  // ── Booking a passage ───────────────────────────────────────────────────────────────────────────────────────────
  // Six coin, or the company's backs at the casks, or neither and a quiet hour in the dark. Whichever it is, the
  // Dorothea goes on the noon ebb and does not wait.
  Relation booked(group). Relation workedPassage(group). Relation stowedAway(group). Relation paidFare(group). Relation asked(group).
  Topic bascom_passage with bascom "Ask Captain Bascom for passage to Skerrow" when not booked(actor) once {
    Says "'Six coin a head, in coin,' says Bascom, 'or a back at the casks till the tide, which I'll count as three. Cargo's salt for the island's pickling and lamp oil for the Pharos, and I'm forty casks short of a full hold and a day behind my debt.' She takes the pipe out. 'Noon. I go on the noon ebb. If you are not on my deck at noon you are on my quay, and I'll be sorry for you in a general way.'".
    On discuss { Assert asked(actor). }
  }
  Topic bascom_why with bascom "Ask Captain Bascom why she sails to Skerrow" when asked(actor) once {
    Says "'To sell salt, and to buy fish, and because the lease on the island's landing is the Orsett factor's and the Orsett factor will have my keel for his brother-in-law by Michaelmas if I miss a call.' She looks past you at the grey line beyond the harbour mouth. 'And because someone has to. The Pharos is lit. Do you know how many lights are lit on this coast that no one pays for? One. A lamp that was lit before Tolleth had a name.'".
  }
  Action pay_fare(actor: group, site: place) "Pay Captain Bascom six coin for a passage to Skerrow" {
    Requires able(actor) and company(actor) and at(actor, site) and at(bascom, site) and at(actor, quay) and asked(actor) and not booked(actor) and bound(hull) == 1 and quantity(actor, gold) >= 6.
    Time 1.
    On success { Decrease quantity(actor, gold) by 6. Increase quantity(bascom, gold) by 6. Assert booked(actor). Assert paidFare(actor). }
    Result "Bascom counts the coin twice into her palm and puts it away in a pocket that has seen it before. 'Gangway's down,' she says. 'Mind the third rung.'".
  }
  Action carry_casks(actor: group, site: place) "Work your passage: carry casks up the gangway until the tide" {
    Description "Forty casks short of a full hold, and the whole company's backs. It works whichever call she is to make.".
    Requires able(actor) and company(actor) and at(actor, site) and at(bascom, site) and at(actor, quay) and asked(actor) and not booked(actor) and capable(actor, brawn) and watch(clock) < sailAfter(hull) - 2.
    Time 8.
    On success { Assert booked(actor). Assert workedPassage(actor). }
    Result "You carry casks for an hour and a half, and the quay learns your name. Bascom says nothing, which from her is warmth. Her mate, a long man called Rune who has been watching from the rail, says you've a good back, for a landsman, and goes below.".
  }
  Action slip_aboard(actor: group, site: place) "Slip aboard unseen among the casks" {
    Description "The tide is near. The gangway is not watched all the time.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, quay) and not booked(actor) and capable(actor, stealth).
    Time 2.
    Resolve check(actor, stealth, dc_fair).
    On success { Assert booked(actor). Assert stowedAway(actor). }
    Result "You go up with the casks, and you are a cask. Below, in the dark of the hold, nobody asks you anything.".
    Otherwise "You go up behind a cask and a gull screams at you. Bascom does not look round. 'Six coin,' she says, 'or the quay.'".
  }

  // ── Where to: the calls ─────────────────────────────────────────────────────────────────────────────────────────
  // Bascom makes one call a voyage and comes home. Skerrow is the one on the board in capitals; she will put in at
  // Port Ness or the Antlers instead for another fare. The call is fixed before the fare is paid; the fare, the road
  // and the way home follow it (voyage.kyr, return.kyr). A company left abroad finds her coming back to where it is.
  Relation askedCalls(group).
  Topic bascom_calls with bascom "Ask Captain Bascom where else she calls" when asked(actor) once {
    Says "'Skerrow, six coin; you know it. Port Ness, four: the salt. A long afternoon out, a night in the barn if you like, and back with the lighters' leavings. The Antlers, eight, on account of the race, and on account of the pilot, who is a man that has to be found sober.' She shifts the pipe. 'There is Ashkeld, twelve, three days south-west, if you like your supper warm. And Mangrow, sixteen, five days south, up a river: bark, and a fever for those who go in without netting. Most of them are the House's paper, as it happens, the House of Marchbank, Orsett. You'll find a man of the House on most of them. You'll know them by the colour of their books.'".
    On discuss { Assert askedCalls(actor). }
  }
  Action course_skerrow(actor: group, site: place) "Ask Captain Bascom to make her call Skerrow after all" {
    Requires able(actor) and company(actor) and at(actor, site) and at(bascom, site) and at(actor, quay) and asked(actor) and not booked(actor) and not sailed(hull) and bound(hull) > 1.
    Time 0.
    On success { Set bound(hull) to 1. Set seaEnd(hull) to 100. Set stayFor(hull) to 217. Set homeOpenAt(hull) to 32. Set homeSoundAt(hull) to 120. Set homeQuayAt(hull) to 160. }
    Result "'Skerrow, then,' says Bascom. 'Six coin. Mind the third rung.'".
  }
  Action course_ness(actor: group, site: place) "Ask Captain Bascom to put in at Port Ness (four coin)" {
    Requires able(actor) and company(actor) and at(actor, site) and at(bascom, site) and at(actor, quay) and asked(actor) and not booked(actor) and not sailed(hull) and (bound(hull) < 2 or bound(hull) > 2).
    Time 0.
    On success { Set bound(hull) to 2. Set seaEnd(hull) to 56. Set stayFor(hull) to 96. Set homeOpenAt(hull) to 6. Set homeSoundAt(hull) to 34. Set homeQuayAt(hull) to 70. }
    Result "'Port Ness,' says Bascom, as if tasting it. 'Four coin. Salt and sulphur and a clerk who counts my casks twice. I'll be in by dusk.'".
  }
  Action course_antlers(actor: group, site: place) "Ask Captain Bascom to put in at the Antlers (eight coin)" {
    Requires able(actor) and company(actor) and at(actor, site) and at(bascom, site) and at(actor, quay) and asked(actor) and not booked(actor) and not sailed(hull) and (bound(hull) < 3 or bound(hull) > 3).
    Time 0.
    On success { Set bound(hull) to 3. Set seaEnd(hull) to 88. Set stayFor(hull) to 130. Set homeOpenAt(hull) to 8. Set homeSoundAt(hull) to 64. Set homeQuayAt(hull) to 100. }
    Result "'The Antlers.' Bascom turns the pipe over and looks at it. 'Eight coin. There's a pilot, if he's sober. If he isn't I'll be asking you for a favour at the race.'".
  }
  Action course_ashkeld(actor: group, site: place) "Ask Captain Bascom to put in at Ashkeld, the burning island (twelve coin)" {
    Requires able(actor) and company(actor) and at(actor, site) and at(bascom, site) and at(actor, quay) and asked(actor) and not booked(actor) and not sailed(hull) and askedCalls(actor) and (bound(hull) < 4 or bound(hull) > 4).
    Time 0.
    On success { Set bound(hull) to 4. Set seaEnd(hull) to 370. Set stayFor(hull) to 150. Set homeOpenAt(hull) to 8. Set homeSoundAt(hull) to 352. Set homeQuayAt(hull) to 388. }
    Result "'Ashkeld.' Bascom says it the way people say the name of a relative who has been in prison. 'Three days out and three back, and the House has not called there in two seasons. Twelve coin. I will not tell you it is a pretty place.'".
  }
  Action course_mangrow(actor: group, site: place) "Ask Captain Bascom to put in at Mangrow, up the river (sixteen coin)" {
    Requires able(actor) and company(actor) and at(actor, site) and at(bascom, site) and at(actor, quay) and asked(actor) and not booked(actor) and not sailed(hull) and askedCalls(actor) and bound(hull) < 5.
    Time 0.
    On success { Set bound(hull) to 5. Set seaEnd(hull) to 660. Set stayFor(hull) to 200. Set homeOpenAt(hull) to 8. Set homeSoundAt(hull) to 656. Set homeQuayAt(hull) to 692. }
    Result "'Mangrow.' Bascom takes the pipe out and looks into the bowl as into a well. 'Five days south and five back, and a pier I will not trust with a line. Sixteen coin. Buy netting from Garrick. I am not saying it for your sake, I am saying it because Mab will not stop.'".
  }
  Action pay_fare_mangrow(actor: group, site: place) "Pay Captain Bascom sixteen coin for a passage to Mangrow" {
    Requires able(actor) and company(actor) and at(actor, site) and at(bascom, site) and at(actor, quay) and asked(actor) and not booked(actor) and bound(hull) == 5 and quantity(actor, gold) >= 16.
    Time 1.
    On success { Decrease quantity(actor, gold) by 16. Increase quantity(bascom, gold) by 16. Assert booked(actor). Assert paidFare(actor). }
    Result "Sixteen coin, counted three times. 'South,' says Bascom, 'until the sea goes the colour of tea. Mind your hats.'".
  }
  Action pay_fare_ashkeld(actor: group, site: place) "Pay Captain Bascom twelve coin for a passage to Ashkeld" {
    Requires able(actor) and company(actor) and at(actor, site) and at(bascom, site) and at(actor, quay) and asked(actor) and not booked(actor) and bound(hull) == 4 and quantity(actor, gold) >= 12.
    Time 1.
    On success { Decrease quantity(actor, gold) by 12. Increase quantity(bascom, gold) by 12. Assert booked(actor). Assert paidFare(actor). }
    Result "Twelve coin, counted twice. 'South-west by west,' says Bascom, 'until the sea goes the wrong colour.'".
  }
  Action pay_fare_ness(actor: group, site: place) "Pay Captain Bascom four coin for a passage to Port Ness" {
    Requires able(actor) and company(actor) and at(actor, site) and at(bascom, site) and at(actor, quay) and asked(actor) and not booked(actor) and bound(hull) == 2 and quantity(actor, gold) >= 4.
    Time 1.
    On success { Decrease quantity(actor, gold) by 4. Increase quantity(bascom, gold) by 4. Assert booked(actor). Assert paidFare(actor). }
    Result "Four coin into the broad palm. 'Salt,' says Bascom. 'Mind your boots, the barn eats leather.'".
  }
  Action pay_fare_antlers(actor: group, site: place) "Pay Captain Bascom eight coin for a passage to the Antlers" {
    Requires able(actor) and company(actor) and at(actor, site) and at(bascom, site) and at(actor, quay) and asked(actor) and not booked(actor) and bound(hull) == 3 and quantity(actor, gold) >= 8.
    Time 1.
    On success { Decrease quantity(actor, gold) by 8. Increase quantity(bascom, gold) by 8. Assert booked(actor). Assert paidFare(actor). }
    Result "Eight coin. Bascom counts it, and then looks along the quay for something she has not found. 'The pilot,' she says. 'Find him before noon.'".
  }

  // The Antlers' pilot: asleep at the foot of the board, with his hat over his face. The race is not run drunk.
  Person rudd "Fenwick Pelham" at quay {
    Role "pilot of the Antlers race". Ancestry human. Calling ranger. Level 3. Peaceable. Pronouns he. Manner jovial.
    Likeness "sailor".
    Greets "A broad red man in a pilot's blue coat lies along a coil of rope at the foot of the notice board with his hat over his face and one boot off. 'Not drunk,' he says, without moving the hat. 'Resting my judgement. There is a difference, and it is eleven pints.'".
    Greets again "Fenwick Pelham has swapped the boot he has off for the one he has on. 'Judgement,' he says, from under the hat, 'is not yet recovered. Come back at the turn. There will be a pilot then, I give you my word, and it might even be me.'".
  }
  Relation ruddSober(group).
  Topic rudd_race with rudd "Ask Fenwick Pelham about the Antlers race" when true once {
    Says "'A street with a hundred corners and every one of them has a stone on it,' says Pelham. He lifts the hat an inch. 'Nobody has run it blind and lived to be sorry, so they say. I've run it sober eleven hundred times and drunk twice. Don't ask me to choose which was better.' He puts the hat back. 'The House pays my retainer. By the quarter. When it pays.'".
  }
  Action walk_rudd(actor: group, site: place) "Walk Fenwick Pelham up and down the quay until he can see straight" {
    Description "He will complain the whole way. It takes the better part of an hour.".
    Requires able(actor) and company(actor) and at(actor, site) and at(rudd, site) and at(actor, quay) and not ruddSober(actor) and not sailed(hull).
    Time 6.
    On success { Assert ruddSober(actor). }
    Result "You get him up between you and walk him the length of the quay and back, and again, with the gulls watching. By the third turn he has stopped swearing; by the fifth he is reading the sky. 'Southerly by dark,' he says, in a voice from a different man. 'Where am I wanted?'".
  }
  Action pay_rudd_slate(actor: group, site: place) "Pay Fenwick Pelham's slate at the Anchor, four coin, so that he goes to bed early" {
    Description "The slate by the taproom door has sums on it. Four of them are his.".
    Requires able(actor) and company(actor) and at(actor, site) and at(rudd, site) and at(actor, quay) and not ruddSober(actor) and not sailed(hull) and quantity(actor, gold) >= 4.
    Time 2.
    On success { Decrease quantity(actor, gold) by 4. Assert ruddSober(actor). }
    Result "The barman wipes four sums off the slate with a thumb. Pelham watches it done with the face of a man at his own funeral, and says nothing, and goes in to sleep, and comes out at noon looking like a bishop.".
  }
  Rule rudd_ships when sailed(hull) and bound(hull) == 3 and ruddSober(party) and not pilotAboard(hull) {
    Assert pilotAboard(hull). Retract at(rudd, quay). Assert at(rudd, helm).
  }

  Topic hoe_ledger with harbourman "Ask Dacey Hoe what the second column in her ledger is" when true once {
    Says "'Premiums,' says Dacey Hoe, 'on the left. I collect them for the House on every hull that clears, a shilling a ton, since my predecessor.' She turns the book. 'And the right is the hulls that did not. W.R. Eleven this year. I took the House's word that W.R. was a thing in law. I wrote the names. I did not read the margins.' She has read them now. In pencil, against nine of the names: NO LIGHT.".
    On discuss { Assert leafTolleth(actor). Increase leaves(actor) by 1. Assert knows(actor, leaf_tolleth_d). }
  }
}

data/adventures/the-dorothea/return.kyr:
Module dorothea "The Dorothea" {
  Description "The way home: the Dorothea lades dried cod, takes on a tide, and goes back by the same stations in reverse. Left behind, a company waits for the next ship, or finds another way.".

  // She stays two days at the jetty: a day to discharge and lade, a night to sleep, a morning ebb to go. A company that is
  // not aboard when she goes is on Skerrow; the next sail is the Mary Ann's, twelve days after, and a crown dearer.
  Measure back(entity). Measure leftAt(entity).
  Relation homeward(entity). Relation stranded(group).
  // The stay at each island is stayFor(hull): Skerrow a day and a half, Port Ness a long afternoon and a night, the Antlers
  // a day. What she does on turning is the same: her bow comes round, the count of the way home begins at nothing.
  Rule hull_returns when arrived(hull) and not homeward(hull) and not safeHome(hull) and at(hull, jetty) and watch(clock) >= reachedAt(hull) + stayFor(hull)
    says "At the top of the morning ebb Bascom comes down the jetty with the pipe unlit, and the lines come off the rings, and the Dorothea goes out of Skerrow roads with her bow turned east." {
    Assert homeward(hull). Retract at(hull, jetty). Assert at(hull, roads). Set back(hull) to 0. Set leftAt(hull) to watch(clock). Retract arrived(hull). Retract troubled(hull). Assert state(hull, underway).
    Retract at(bascom, jetty). Assert at(bascom, helm). Set seaDrawn(hull) to 0. Retract squallDone(hull). Retract raftDone(hull). Retract feverDone(hull). Retract calmDone(hull). Retract fleetDone(hull).
  }
  Rule hull_returns_ness when arrived(hull) and not homeward(hull) and not safeHome(hull) and at(hull, ness_quay) and watch(clock) >= reachedAt(hull) + stayFor(hull)
    says "Bascom comes down Port Ness pier with a bill of lading under her arm and the pipe lit, and the lighters either side lean out of the way. The lines come off the posts. The Dorothea goes out between the salt barges with her bow to the north." {
    Assert homeward(hull). Retract at(hull, ness_quay). Assert at(hull, ness_roads). Set back(hull) to 0. Set leftAt(hull) to watch(clock). Retract arrived(hull). Retract troubled(hull). Assert state(hull, underway).
    Retract at(bascom, ness_quay). Assert at(bascom, helm). Set seaDrawn(hull) to 0. Retract squallDone(hull). Retract raftDone(hull). Retract feverDone(hull). Retract calmDone(hull). Retract fleetDone(hull).
  }
  Rule hull_returns_antlers when arrived(hull) and not homeward(hull) and not safeHome(hull) and at(hull, antler_ledge) and watch(clock) >= reachedAt(hull) + stayFor(hull)
    says "The plank is hauled in with a bird still on it. Bascom shouts down the wind, and the anchors come up, one and then the other, black with weed, and the Dorothea falls away from the rock on the ebb with the whole roaring face of the stack going by her rail." {
    Assert homeward(hull). Retract at(hull, antler_ledge). Assert at(hull, antler_race). Set back(hull) to 0. Set leftAt(hull) to watch(clock). Retract arrived(hull). Retract troubled(hull). Assert state(hull, underway).
    Retract at(bascom, antler_ledge). Assert at(bascom, helm). Set seaDrawn(hull) to 0. Retract squallDone(hull). Retract raftDone(hull). Retract feverDone(hull). Retract calmDone(hull). Retract fleetDone(hull).
  }
  Rule hull_returns_ashkeld when arrived(hull) and not homeward(hull) and not safeHome(hull) and at(hull, ashkeld_beach) and watch(clock) >= reachedAt(hull) + stayFor(hull)
    says "The boat is hauled up and the anchors come in black and warm. The Dorothea stands off Ashkeld, and the cone makes a farewell of sparks, and she turns her bow to the north-east and the long road." {
    Assert homeward(hull). Retract at(hull, ashkeld_beach). Assert at(hull, ashkeld_roads). Set back(hull) to 0. Set leftAt(hull) to watch(clock). Retract arrived(hull). Retract troubled(hull). Assert state(hull, underway).
    Retract at(bascom, ashkeld_beach). Assert at(bascom, helm). Set seaDrawn(hull) to 0. Retract squallDone(hull). Retract raftDone(hull). Retract feverDone(hull). Retract calmDone(hull). Retract fleetDone(hull).
  }
  Rule hull_returns_mangrow when arrived(hull) and not homeward(hull) and not safeHome(hull) and at(hull, mangrow_pier) and watch(clock) >= reachedAt(hull) + stayFor(hull)
    says "The plank comes in dripping. Bascom shouts down the wind, though there is none, and the anchors come up black and heavy with leaf-mould, and the Dorothea backs out of the tea-coloured water with the green closing behind her like a door." {
    Assert homeward(hull). Retract at(hull, mangrow_pier). Assert at(hull, mangrow_roads). Set back(hull) to 0. Set leftAt(hull) to watch(clock). Retract arrived(hull). Retract troubled(hull). Assert state(hull, underway).
    Retract at(bascom, mangrow_pier). Assert at(bascom, helm). Set seaDrawn(hull) to 0. Retract squallDone(hull). Retract raftDone(hull). Retract feverDone(hull). Retract calmDone(hull). Retract fleetDone(hull).
  }
  Rule home_open_mangrow when homeward(hull) and bound(hull) == 5 and at(hull, mangrow_roads) and back(hull) >= 8 says "The green wall sinks until it is a line, and then a smudge, and the air loses its weight. You find you have been breathing shallow for a week." {
    Retract at(hull, mangrow_roads). Assert at(hull, open_sea).
  }
  Rule home_open_ashkeld when homeward(hull) and bound(hull) == 4 and at(hull, ashkeld_roads) and back(hull) >= 8 says "The cone goes down the sea by degrees until it is a smudge, and then a darker place in the sky, and then a thing you remember." {
    Retract at(hull, ashkeld_roads). Assert at(hull, open_sea).
  }
  Rule home_tick when homeward(hull) and not troubled(hull) and not safeHome(hull) { Increase back(hull) by 1. }
  Rule home_open_ness when homeward(hull) and bound(hull) == 2 and at(hull, ness_roads) and back(hull) >= 6 says "The salt shore sinks into its own steam. Ahead, nothing but the grey road home." {
    Retract at(hull, ness_roads). Assert at(hull, open_sea).
  }
  Rule home_open_antlers when homeward(hull) and bound(hull) == 3 and at(hull, antler_race) and back(hull) >= 8 says "The last stack goes by, and the birds fall back to a murmur, and then to a rumour. The swell takes her under the quarter and she begins to lift." {
    Retract at(hull, antler_race). Assert at(hull, open_sea).
  }
  Rule home_combs when homeward(hull) and bound(hull) == 1 and at(hull, roads) and back(hull) >= 14 says "Ahead, the Combs: lower on the flood, the sea going over them in long white lines. Bascom takes the wheel herself. 'Not a word,' she says." {
    Retract at(hull, roads). Assert at(hull, teeth).
  }
  Rule home_open when homeward(hull) and bound(hull) == 1 and at(hull, teeth) and back(hull) >= 32 says "The Combs are astern. The sea opens its long shoulders, and there is a smell in the wind of a place with chimneys." {
    Retract at(hull, teeth). Assert at(hull, open_sea).
  }
  Rule home_sound when homeward(hull) and at(hull, open_sea) and back(hull) >= homeSoundAt(hull) says "The first headland of the Sound stands up out of the haze, and a tern goes by with something silver in its beak, and Nipper, who has not been out of sight of land for two days, says it is the best thing he has ever seen." {
    Retract at(hull, open_sea). Assert at(hull, sound).
  }
  Rule home_quay when homeward(hull) and at(hull, sound) and back(hull) >= homeQuayAt(hull) and not safeHome(hull) says "Tolleth takes the Dorothea in with the sea going out of her like a great held breath. A woman on the quay shouts a name, and Mab Hallam answers it with a word that is not a name." {
    Retract at(hull, sound). Assert at(hull, quay). Assert safeHome(hull). Assert state(hull, alongside). Retract homeward(hull). Assert arrived(hull). Set homeAt(hull) to watch(clock).
  }
  Relation safeHome(entity).
  Rule left_behind_isle when homeward(hull) and not aboardNow(party) and at(party, green) and not stranded(party) { Assert stranded(party). }
  Observe stranded_scene at jetty when stranded(party) and not arrived(hull) "The jetty is bare. Out on the roads a brown sail is getting small. Someone has chalked on the Gull's wall: MARY ANN, THE 24TH.".
  Observe tied_up_back at quay when safeHome(hull) "The Dorothea lies against Tolleth quay with her gangway down and her crew carrying casks of dried cod up the quay as though they had never left. Bascom is counting.".

  // ── Turning round ───────────────────────────────────────────────────────────────────────────────────────────────
  // A day after she is home, with the company not aboard, she is made ready for her next call: the hold re-laden, the
  // pump dry, the count at nothing, and the sailing fixed for the next noon. The call is what she last made unless the
  // company has arranged another with Bascom; a company that was left abroad finds her coming back to where it is.
  Rule hull_turns_round when safeHome(hull) and at(hull, quay) and not aboardNow(party) and watch(clock) >= homeAt(hull) + 30 {
    Retract sailed(hull). Retract safeHome(hull). Retract arrived(hull). Retract homeward(hull). Retract booked(party). Retract troubled(hull).
    Retract combsMet(hull). Retract waitedFlood(hull). Retract ranGap(hull). Retract lightened(hull). Retract decidedCombs(hull). Retract raceMet(hull). Retract towCalled(hull). Retract pilotAboard(hull).
    Retract holed(hull). Retract callPumped(hull). Retract at(rudd, helm). Assert at(rudd, quay). Retract ruddSober(party). Retract fog(hull). Retract heaved(hull).
    Retract squall(hull). Retract raft(hull). Retract fever(hull). Retract calm(hull).
    Retract ferried(party). Retract netted(party). Retract barked(party). Retract fevered(party). Retract felt2(party). Retract felt6(party). Set swelter(party) to 0.
    Retract squallDone(hull). Retract raftDone(hull). Retract feverDone(hull). Retract calmDone(hull). Retract fleetDone(hull).
    Set progress(hull) to 0. Set back(hull) to 0. Set water(hull) to 0. Set cargo(hull) to 40. Set seaDrawn(hull) to 0.
    Assert state(hull, alongside). Retract at(bascom, helm). Assert at(bascom, quay).
    Set sailAfter(hull) to (watch(clock) / 144 + 1) * 144 + 24. Increase voyages(hull) by 1.
  }
  // Left on the other islands: Port Ness has a lighter that goes with the tide; the Antlers has the Dorothea's next call.
  Relation strandedNess(group). Relation strandedAntlers(group).
  Rule left_behind_ness when homeward(hull) and bound(hull) == 2 and not aboardNow(party) and onNess(party) and not strandedNess(party) { Assert strandedNess(party). }
  Rule left_behind_antlers when homeward(hull) and bound(hull) == 3 and not aboardNow(party) and onAntlers(party) and not strandedAntlers(party) { Assert strandedAntlers(party). }
}

data/adventures/the-dorothea/ring.kyr:
Module dorothea "The Dorothea" {
  // ── The ring's coast: a store in Tolleth, a loft at Port Ness ──────────────────────────────────────────────────────
  // The Ring is the House of Marchbank's criminal arm, and a world's Founders' Exchange is its front in the country
  // behind this passage (data/goings-on/factors). Deem casts its ring_coast and its Principal there. This module is
  // where they sit when they are on the coast: R. in a bonded store behind Garrick's, the Principal in a loft over
  // the boiling-house at Port Ness, each for days at a time, on a circuit. Nothing here names the Exchange: what is
  // read is the ring, the ring_coast and the Principal (herald-bound), a place called abroad, and four facts the
  // ring's people let slip, all of them canonical relations on entities the herald bound (at, routed, dead, knows).
  Measure sawAbroad(entity). Measure ringUntil(entity). Measure lastSaw(entity).
  Relation ringHome(group). Relation ringFallen(group). Relation loftKnown(group). Relation storeKnown(group). Relation deskLooked(group).

  Place store_house "the bonded store" is building within harbour.
  Place bonded_store "the bonded store behind Garrick's" is room within store_house at 3, 1.
  Place boiling_house "the boiling-house" is building within ness_town.
  Place ring_loft "the boiling-house loft" is room within boiling_house at 3, 1.
  Discovery store_seen "A lading hatch under the quay's edge opens, at low water, on a store behind Garrick's chandlery that has no door on the street." { Found by searching quay. }
  Discovery loft_seen "Over the boiling-house at Port Ness there is a loft with a lamp in it, and a ladder that is drawn up when the House's boat is out." { Found by searching ness_quay. }
  Passage store_door "the plank door behind the chandler's racks" is door between shop and bonded_store hidden until lieutenant_named.
  Passage store_hatch "the lading hatch under the quay" is ladder between quay and bonded_store hidden until store_seen.
  Passage loft_ladder "the ladder to the boiling-house loft" is ladder between ness_row and ring_loft hidden until principal_traced.
  Passage loft_stair "the back stair of the boiling-house" is stair between ness_quay and ring_loft hidden until loft_seen.

  Observe store_scene at bonded_store when at(ring_coast, bonded_store) "A long low room under the chandlery with no windows: crates stencilled NORTH, a bell on its side with its clapper in felt, a stove, a back-table with a lamp and a day-book, and everywhere the smell of tar and cold iron. A key and a ring are scored in the table's edge.".
  Observe store_swept at bonded_store when not at(ring_coast, bonded_store) "The bonded store is swept. Four crates' worth of dust on the flags, a stove still warm, and on the back-table a clean oblong where a day-book lay. Somebody has taken the lot and the man, and not in that order.".
  Observe loft_scene at ring_loft when true "A loft under the slates over the pans' boiling-house, warm from the coppers below, with a trestle table, a black trunk, a map of the Reach with pins in it, and a lamp in the gable window that is lit when the House's boat is out. Brine has dried white on everything.".
  Observe bill_scene at harbourmaster when routed(ring_coast) "A new bill is pinned inside the harbourmaster's door in a clerk's round hand: the House of Marchbank begs the Reach to know that its bonded agent at Tolleth, called R., has absconded with a sum, and that the House will see him taken.".

  // The ring_coast's desk: the letter in the Principal's hand, which is the second way to the loft.
  Kind ring_letter "a letter under the key and ring" is document teaching principal_traced described "A letter on thick paper under a cut seal, key and ring: three lines, in a hand that has never raised its voice. The Principal will be at the Ness loft after the store, and R. is to keep the day-book square.".
  Item ring_letter_item "a letter under the key and ring" is ring_letter at nowhere.
  Action search_desk(actor: group, site: place) "Go through the back-table's day-book and drawer" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bonded_store) and not deskLooked(actor) and (tolerates(ring_coast, actor) or routed(ring_coast) or dead(ring_coast) or not at(ring_coast, bonded_store)) and not storeSwept(party).
    Time 6.
    On success { Give ring_letter_item to actor. Assert deskLooked(actor). Assert knows(actor, seal_seen). }
    Result "The drawer sticks and then does not. A thick letter under a cut seal, key and ring, lies on the day-book: three lines. The Principal will be at the Ness loft after the store. R. is to keep the day-book square.".
  }
  Relation storeSwept(group).
  Rule store_swept_clean when routed(ring_coast) and not storeSwept(party) { Assert storeSwept(party). }

  // ── The Principal's circuit ─────────────────────────────────────────────────────────────────────────────────────────
  // He goes round: the town, then abroad (a day by the House's boat), then the bonded store in Tolleth for two days,
  // then the loft at Port Ness for three, then home. If R. has been put out (routed) he does not stop at the store, and
  // the loft sees him longer. Rules write only what a rule may: where he is. The town's own rules bring him home.
  Rule ring_waits when at(ring_head, abroad) and sawAbroad(ring_head) == 0 and not ringHome(ring_head) and not routed(ring_head) and not dead(ring_head) {
    Set sawAbroad(ring_head) to watch(clock). Increase sawAbroad(ring_head) by 145.
  }
  Rule ring_to_store when at(ring_head, abroad) and sawAbroad(ring_head) > 0 and watch(clock) >= sawAbroad(ring_head) and not ringHome(ring_head) and not routed(ring_coast) and not routed(ring_head) and not dead(ring_head)
    says "A boat with no light puts in under the quay at slack water, and a figure in a black coat goes up the lading steps and in at a door that was not there." {
    Retract at(ring_head, abroad). Assert at(ring_head, bonded_store). Set sawAbroad(ring_head) to 0. Set ringUntil(ring_head) to watch(clock). Increase ringUntil(ring_head) by 288.
  }
  Rule ring_skips_store when at(ring_head, abroad) and sawAbroad(ring_head) > 0 and watch(clock) >= sawAbroad(ring_head) and not ringHome(ring_head) and routed(ring_coast) and not routed(ring_head) and not dead(ring_head) {
    Retract at(ring_head, abroad). Assert at(ring_head, ring_loft). Set sawAbroad(ring_head) to 0. Set ringUntil(ring_head) to watch(clock). Increase ringUntil(ring_head) by 576.
  }
  Rule ring_to_loft when at(ring_head, bonded_store) and watch(clock) >= ringUntil(ring_head) and not routed(ring_head) and not dead(ring_head) {
    Retract at(ring_head, bonded_store). Assert at(ring_head, ring_loft). Set ringUntil(ring_head) to watch(clock). Increase ringUntil(ring_head) by 432.
  }
  Rule ring_home when at(ring_head, ring_loft) and watch(clock) >= ringUntil(ring_head) and not routed(ring_head) and not dead(ring_head) {
    Retract at(ring_head, ring_loft). Assert at(ring_head, abroad). Assert ringHome(ring_head). Set ringUntil(ring_head) to 0.
  }
  Rule homeward_over when ringHome(ring_head) and not at(ring_head, abroad) { Retract ringHome(ring_head). }
  // R. is a ring_coast of the coast: he is put at his store when the world has cast him and has nowhere else to put him.
  Rule lieutenant_posted when at(ring_coast, abroad) and not routed(ring_coast) and not dead(ring_coast) { Retract at(ring_coast, abroad). Assert at(ring_coast, bonded_store). }

  // Seen at the bonded store or the loft only if they are there. The Principal at the loft is the end of the circuit's
  // reach: a company that comes by the Dorothea finds him by the lamp in the gable.
  Observe lamp_gable at ness_row when at(ring_head, ring_loft) and not routed(ring_head) "Over the boiling-house a gable window is lit in broad day. The Row's washing hangs in a line under it, and every woman pegging it out has her back to the window.".
  Observe lamp_gable_dark at ness_row when not at(ring_head, ring_loft) "Over the boiling-house the gable window is dark.".

  // ── What the ring's fall opens ──────────────────────────────────────────────────────────────────────────────────────
  // When its Principal is routed or dead, the House's seal on the Pharos's lower door, which only the ring's authority
  // kept shut, is struck. See lamp.kyr.
  Rule ring_has_fallen when (routed(ring_head) or dead(ring_head)) and not ringFallen(party) { Assert ringFallen(party). }
}

data/adventures/the-dorothea/skerrow.kyr:
Module dorothea "The Dorothea" {
  Description "Skerrow: forty-one souls, a winter coming, a lease held by a factor who wants a different thing from the Pharos than the island does, and a keeper who will not say what she will take for it.".

  Person gull "Hester Gull" at gull_room {
    Role "keeper of the Gull". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Sells rations for 2 coin from 6.
    Sells rag_paper for 1 coin from 4.
    Greets "Hester Gull has kept the Gull for thirty years and the debts of the island for thirty-one, and she keeps both with the same flat hand. 'You came on the Dorothea,' she says. 'Then you'll want to know who owes what. Everybody owes everything. It's how an island holds together.'".
    Greets again "Hester Gull has added a line to the slate behind her. You do not see what it says, and she does not offer. 'Everybody owes everything,' she says. 'You are on the slate now. It is no insult; it is where I keep the people I mean to remember.'".
  }
  Person kestle_jory "Jory Kestle" at green {
    Role "fisherman, the keeper's brother". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "A big man mending a net on the green, with three children under it and a fourth on his shoulders. He does not stop mending. 'You'll have been told about the Pharos,' he says. 'You'll have been told my sister keeps it. You'll not have been told what a family eats on in a winter when the cod don't come.'".
    Greets again "Jory Kestle has a different child on his shoulders. 'The cod have not come,' he says, mending. 'You have the look of a person who might know why. I have the look of a person who does not want to be told.'".
  }
  Person marl "Silas Quillon" at gull_room {
    Role "agent of the Orsett factor". Ancestry human. Calling bard. Level 3. Pronouns he. Manner jovial.
    Likeness "merchant".
    Greets "A neat man in a neat coat, with a ledger open before him on the Gull's long table and a cup of the Gull's tea untouched at his elbow. He rises for you, which nobody else has. 'Silas Quillon, of Orsett. Agent. I'm here for the lease, and a matter of old metal. I'm told I'm not liked. I find it never matters.'".
    Greets again "Silas Quillon rises again, and is again the only one in the room who has. 'Back,' he says. 'And I am no more liked, I find, though I take comfort that it never matters. The lease is not signed, the old metal is not sold, and I am enjoying the island more than I expected. How are you getting on with it?'".
  }
  Person islanders "the people of Skerrow" at green {
    Role "islanders". Ancestry human. Numbers 5. Peaceable.
  }
  Initially Set quantity(marl, gold) to 60. Initially Set quantity(gull, gold) to 24.

  // ── What the island needs, and what the factor offers ──────────────────────────────────────────────────────────
  Relation marlOffered(group). Relation marlSold(group). Relation jorySways(group). Relation keptLamp(group). Relation tableSold(group). Relation lampOut(group).
  Topic gull_island with gull "Ask Hester Gull how Skerrow lives" when true once {
    Says "'On fish, sheep and the Dorothea,' says Hester Gull. 'The Dorothea brings salt, lamp-oil and news, and takes our dried cod. The lease on the landing is the Orsett factor's, so a third of every landing goes to Orsett. And the Pharos...' She snorts. 'The Pharos earns us nothing. A ship that sees it doesn't pay, a ship that doesn't, can't. It's a lamp. We keep it because it is a lamp, and you keep a lamp.'".
  }
  Topic marl_offer with marl "Ask Silas Quillon what he wants with old metal" when true once {
    Says "'The bronze in the Pharos,' says Silas Quillon, pleasantly. 'A plate in the wall that no one can read, and a lens-frame, and a reflector that's worth, I'm told, a hundred and forty crowns to a foundry. The island gets sixty down, and the lease waived for ten years. Winter, you see, comes.' He turns a page. 'They give me their answer at the Gull on the second evening. I do not hurry a man who is going to say yes. Jory Kestle holds the pen, whatever his sister holds.' 'I'm not your enemy. Think of me as a man who can count.'".
    On discuss { Assert marlOffered(actor). }
  }
  // The same buyer as the one on the coast road in the country behind (Merrowdale's Heron sells him bell-bronze by the
  // pound): said as a trade, not as a plot, and only to someone who has already heard the offer.
  Topic marl_others with marl "Ask Silas Quillon who else sells him old metal" when marlOffered(actor) once {
    Says "'Everyone with a bell they have stopped hearing,' says Silas Quillon, and smiles at the page. 'Sluice-gates. Weir-teeth. A barge-master up a beck in the hills who brings me a dozen green teeth a year, and tells her hands they are ballast. It is a most agreeable country: it keeps the old things where I can find them, and no one asks what they were holding up.' He caps the ink. 'The Pharos is the first lamp I have been offered. I confess I find it more difficult. A lamp is not a thing one weighs.'".
  }
  Topic jory_winter with kestle_jory "Ask Jory Kestle about the winter" when true once {
    Says "'It's the sixth bad cod season in nine,' says Jory. 'Hester's got every house in the book. Marren thinks I want to sell the Pharos. I want to sell it as a man wants to cut his hand off: I'd rather have a hand, and I'd rather eat.' He looks up the hill at the tower. 'My children have never once been warm in a room with that light in it. They don't know what it's for. I don't, either.'".
  }
  Topic kestle_lamp with kestle "Ask Marren Kestle what the Pharos is for" when true once {
    Says "She sits back on her heels. 'The first night my father let me trim it I asked him that. He said: it is for whoever is out there tonight. And I said: who is out there? And he said, you won't know till they're not.' She puts the rag down. 'I have been asked what I'll take for it nine times in twenty years. I have never once been asked what it's for, except by a child.'".
  }
  Topic kestle_table with kestle "Ask Marren Kestle about the bronze table in the lamp room" when true once {
    Says "'The Prefect's Table,' she says. 'That's what my family calls it. I've never known what it says. It's been scrubbed so many times by so many Kestles that half of it's polish. One column is Aenean numbers, and I can count in those. The other...' She shakes her head. 'My mother said the other column is the part the Prefect didn't write. She said somebody else wrote it first.'".
    On discuss { Assert knows(actor, table_seen). }
  }
  Discovery table_seen "In the lamp room of the Pharos is a bronze table: a column of Aenean numerals, and beside it a second column, in marks that have been scrubbed and polished by generations of keepers, which nobody on Skerrow can read.".

  // ── The rubbing, and the table ─────────────────────────────────────────────────────────────────────────────────
  Kind rag_paper "a sheet of rag paper" is gear worth 1 weighing 0 described "A sheet of rag paper from the Gull's ledgers, with a stick of charcoal rolled in it.".
  Action rub_the_table(actor: group, site: place) "Take a rubbing of the Prefect's Table" {
    Description "Charcoal, a sheet of paper, and an hour with the lamp turned low. A rubbing keeps what a table says even when the table is sold.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pharos_lamp) and holding(actor, rag_paper) and not rubbed(actor) and not tableSold(party).
    Time 6.
    On success { Assert rubbed(actor). Assert knows(actor, rubbing_made). Spend rag_paper from actor. }
    Result "Marren Kestle holds the sheet flat while you pass the charcoal over it, and the table comes up out of the bronze by degrees, a column at a time: the Aenean numerals in a clean row, and beside them, ghostly, scrubbed to a shadow, a second column of strokes in a different hand. Marren looks at it for a long time over your shoulder. 'I did not know it had that many,' she says. 'Thirty years I've been polishing it. Do you know, I never once looked.'".
  }
  Relation rubbed(group).
  Discovery rubbing_made "You have a rubbing of the Prefect's Table, taken on Skerrow.".
  Item rubbing "a rubbing of the Prefect's table" is pharos_rubbing at nowhere owned by kestle.
  Rule rubbing_given when rubbed(party) and not given(rubbing) { Give rubbing to party. Assert given(rubbing). }
  Relation given(item).

  // ── The factor's offer: who decides ────────────────────────────────────────────────────────────────────────────
  // The island decides on the second evening, at the Gull. Marren Kestle will not sell; Jory Kestle will; the island
  // listens to whoever it trusts. The company can pay for a winter, argue, or watch.
  Action pay_winter(actor: group, site: place) "Offer to stand Jory Kestle's winter debts at the Gull" {
    Description "Twenty coin, against the Gull's ledger. It will not buy the island a winter. It will buy a family one.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, green) and at(kestle_jory, site) and marlOffered(actor) and not jorySways(party) and quantity(actor, gold) >= 20.
    Time 2.
    On success { Decrease quantity(actor, gold) by 20. Increase quantity(gull, gold) by 20. Assert jorySways(party). }
    Result "Jory puts the net down. He looks at the coin as if it were an unusual fish, and at you, and at his children, and at last at the hill. 'I'll not take it as a gift,' he says. 'I'll take it as a loan against the cod, and I'll have it written at the Gull, in front of her, so it's a thing that's been done.' He holds out a hand the size of a spade. 'And my sister's to be told by me. Not by you.'".
  }
  Action argue_winter(actor: group, site: place) "Argue the island out of selling the Pharos" {
    Description "Not an argument that will feed anyone. An argument that might give a hungry place a reason to want to be what it is.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, green) and marlOffered(actor) and not jorySways(party).
    Time 2.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert jorySways(party). }
    Result "You tell them, on the green, in the evening, with the sheep eating the grass round your boots: that a lamp is a promise, and a promise lets a place be forgiven for being nowhere. You are not eloquent. You say it plainly. Jory Kestle listens with the baby on his shoulder, and when you have finished he says: 'That's all very well. It's still February.' But he says it more quietly.".
    Otherwise "They hear you out, kindly. The sheep are more interested.".
  }
  Rule marl_buys when watch(clock) >= reachedAt(hull) + 132 and arrived(hull) and not marlSold(party) and not jorySways(party) and marlOffered(party) and not routed(ring)
    says "In the evening, at the Gull, Jory Kestle puts his name to Silas Quillon's paper. Nobody looks at him. He signs it the way a man puts down a child he has carried too far, and goes out into the dusk without his cap." {
    Assert marlSold(party).
  }
  Rule marl_leaves when jorySways(party) and not keptLamp(party) and arrived(hull) says "Silas Quillon closes his ledger, rises, and shakes the company's hands one by one. 'I count,' he says. 'I counted wrong. I'll be back when the lease is up, and the island will have a different winter.' He takes the Dorothea's last place home." {
    Assert keptLamp(party). Retract at(marl, gull_room).
  }
  Observe lamp_out_scene at green when lampOut(party) "The Pharos hill is dark. Where the lamp-room window was, a rectangle of darker dark; and at the foot of the hill a barrow with a plate in it, green-black, polished. Marren Kestle is sitting on the wall with her knees up and her back to the sea.".
  // Quillon sells what he buys. If the Exchange that would take the plate has fallen in the country behind the passage,
  // Quillon has a lot of old bronze and nobody to sell it to, and the island's winter is the only winter.
  Rule marl_no_buyer when routed(ring) and arrived(hull) and not keptLamp(party) and marlOffered(party)
    says "A letter has come on the Dorothea's mail-bag for Silas Quillon, from Orsett, and he reads it standing in the Gull's kitchen with his tea going cold. 'The Exchange has closed its yard,' he says, to the room. 'It seems I am a man with a lease and no foundry.' He closes the ledger and thanks Hester Gull for the tea." {
    Assert keptLamp(party). Retract at(marl, gull_room).
  }

  // ── The House at Skerrow: the Agent, and his ledger ─────────────────────────────────────────────────────────────
  Action read_quillon_ledger(actor: group, site: place) "Read Silas Quillon's open ledger upside down while he pours his tea" {
    Description "It is open on the Gull's long table. He reads it as a priest reads a psalter: with his eyes closed.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gull_room) and at(marl, site) and not leafSkerrow(actor).
    Time 2.
    Resolve check(actor, insight, dc_fair).
    On success { Assert leafSkerrow(actor). Increase leaves(actor) by 1. Assert knows(actor, leaf_skerrow_d). }
    Result "A green ledger, a neat hand, and in the right-hand margin a column headed LUM. with four lines in it. Three are struck through in a different ink. The fourth is the Pharos, and beside it, in capitals, PENDING. You have time to read the last thing before he sets the cup down: THE LAMP ROOM TO BE LEFT EMPTY.".
    Otherwise "Quillon puts a hand flat on the page, pleasantly, as one covers a wound. 'It is not interesting,' he says.".
  }
  Topic marl_book with marl "Put what you have read to Silas Quillon" when leaves(actor) >= 2 and not leafSkerrow(actor) once {
    Says "He does not close the ledger. He turns it round to face you, and pushes it across, which is the rudest thing he has ever done. 'I was told it was scrap,' he says. 'Bronze, and old glass, and a lease on a landing. I counted. I did not ask what the glass was for.' He taps the right-hand margin. 'I see I am the last of four.' He takes his tea. 'Read what you like.'".
    On discuss { Assert leafSkerrow(actor). Increase leaves(actor) by 1. Assert knows(actor, leaf_skerrow_d). }
  }
  Topic marl_ranks with marl "Ask Silas Quillon whom he answers to" when true once {
    Says "'The Factor, who is in Orsett at this season, or at the Ness,' says Quillon. 'And over her the Principal, whom I have seen twice, at a distance, in a good light.' He closes the green cover for emphasis. 'I am an Agent. It is a post. The rank above is a sort of weather.'".
    On discuss { Assert knowsRanks(actor). }
  }
  Topic kestle_oil with kestle "Tell Marren Kestle what the House's ledgers say of the other lights" when leaves(actor) >= 2 and not lampOut(actor) once {
    Says "She listens with the rag in her hand, and when you have finished she sits for some time. 'Three,' she says. 'Three lights dark, and the Pharos the fourth. I thought we were the only one.' She gets up. 'There is a store under the tower. Oil, in kegs. A keeper's oil is for whoever is out there. Take three. Don't tell me where they go; tell me when they are lit.'".
    On discuss { Give 3 dorothea_oil_keg to actor. }
  }
}

data/adventures/the-dorothea/voices.kyr:
Module dorothea "The Dorothea" {
  Description "What the company's members make of the sea, by what they are.".

  Relation vSky(group). Relation vHatch(group). Relation vPump(group). Relation vCombs(group). Relation vLamp(group). Relation vGull(group).
  Rule voice_sky at deck when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(hull, open_sea) and not vSky(party)
    says "{?m} stands at the rail with the wind in the face and does not speak for a while. 'Glass is falling,' {?m} says at last, 'and the swell has changed its mind about where it is coming from. It will be thick by the morning, and the Captain knows. She has the look.'" {
    Assert vSky(party).
  }
  Rule voice_hatch at deck when memberOf(?m, party) and hasCalling(?m, calling_thief) and awake(?m) and at(jago, deck) and not vHatch(party)
    says "{?m} does not look at the two men at the hatch. {?m} looks at the cutter's mast, and the way the cutter has taken the lee, and the men on her deck who are not showing lights. 'He does this twice a month,' {?m} says, low. 'Look at the mate's hands. They are not frightened. They are practised.'" {
    Assert vHatch(party).
  }
  Rule voice_pump at hold when memberOf(?m, party) and hasCalling(?m, calling_cleric) and awake(?m) and water(hull) >= 6 and at(party, hold) and not vPump(party)
    says "{?m} stands ankle-deep in the black water and says a short plain prayer for the planks. It is the sort of prayer a sailor would say, with no great hope and no great shame: that the keel hold, that the pump hold, that the hands hold. 'Pump,' {?m} says then, in an entirely different voice. 'Prayer is for after.'" {
    Assert vPump(party).
  }
  Rule voice_combs at deck when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and troubled(hull) and at(hull, teeth) and not vCombs(party)
    says "{?m} looks at the gap for a long time, as a soldier looks at a ford. 'A thing that kills you at six knots,' {?m} says, 'and merely hurts you at slack. I would wait the five hours. But I would not be the one to tell her.'" {
    Assert vCombs(party).
  }
  Rule voice_lamp at pharos_lamp when memberOf(?m, party) and hasCalling(?m, calling_mage) and awake(?m) and not vLamp(party)
    says "{?m} puts a palm near the great bronze reflector and takes it away again. 'Nothing in it,' {?m} says. 'No working. It is a shape. It throws the light out in a way that shows you where it is, and the way it does that is so exactly right that I cannot find where the sorcery is hiding.'" {
    Assert vLamp(party).
  }
  Rule voice_gull at gull_room when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and not vGull(party)
    says "{?m} listens to the Gull's kitchen for a while: the range, the ledger, the sheep through the wall. 'This is how a place like this sings,' {?m} says. 'The sum of what it owes. If you wrote it down it would scan.'" {
    Assert vGull(party).
  }

  // ── The archipelago ─────────────────────────────────────────────────────────────────────────────────────────────
  Relation vLock(group). Relation vBirds(group). Relation vTide(group). Relation vLadder(group). Relation vRim(group).
  Rule voice_lock at counting_room when memberOf(?m, party) and hasCalling(?m, calling_thief) and awake(?m) and at(party, counting_room) and houseHolds(lamp_ness) and not vLock(party)
    says "{?m} does not look at the clerk. {?m} looks at the strongbox, and at the keyhole, and at the way the brass about it is worn on the left only. 'Two levers,' {?m} says, low. 'The second one is set back under the first. Somebody who didn't trust his Factor put it there. It would take a quiet hour.'" {
    Assert vLock(party).
  }
  Rule voice_birds at stack_top when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, stack_top) and houseHolds(lamp_antlers) and not vBirds(party)
    says "{?m} walks to the edge of the turf with the wind in the face and watches the gannets for a time. 'They're on the lee side,' {?m} says. 'Thickest. The board is on the windward, where they're thin. Whoever wrote that clause never stood here. A fire on the lee side would not put these off, it would warm them.'" {
    Assert vBirds(party).
  }
  Rule voice_tide at ness_strand when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, ness_strand) and not vTide(party)
    says "{?m} crouches by the tide-gauge and puts a hand on the weed-line. 'Low water at about this hour,' {?m} says, 'and five hours of road, no more. After that the road drowns. Weed lies on it a handsbreadth deep by the next high. Whoever goes out should come back with the ebb still running.'" {
    Assert vTide(party).
  }
  Rule voice_ladder at stack_foot when memberOf(?m, party) and hasCalling(?m, calling_warrior) and awake(?m) and at(party, stack_foot) and not ladderSound(party) and not vLadder(party)
    says "{?m} takes the ladder in both fists and leans back on it, and a rung comes away in the hand. 'No,' {?m} says. 'I have seen men go up worse. I have seen them come down faster.' {?m} looks at the hoist-basket and the boy at the winch. 'I will go in the basket, and I will not say that I like it.'" {
    Assert vLadder(party).
  }
  Rule voice_rim at ashkeld_rim when memberOf(?m, party) and hasCalling(?m, calling_ranger) and awake(?m) and at(party, ashkeld_rim) and not vRim(party)
    says "{?m} stands on the lip with a wet cloth over the face and listens, as one listens to a sleeping animal. 'It breathes,' {?m} says. 'Slow. In, hold, out. There is a gap in it. If I had a clock I could use it. If I had the bath-keeper I could ask.'" {
    Assert vRim(party).
  }
}

data/adventures/the-dorothea/voyage.kyr:
Module dorothea "The Dorothea" {
  Description "The passage: a clock, a position, and the things that happen on the way. The Dorothea's progress is counted in watches from her casting off; where she is, is a fact of the world; trouble stops the count and the count goes on when the trouble is settled.".

  Measure progress(entity). Measure water(entity). Measure fogAt(entity). Measure cargo(entity).
  Relation fog(entity). Relation fogDone(entity). Relation heaved(entity). Relation holed(entity).
  Initially Set progress(hull) to 0. Initially Set water(hull) to 0. Initially Set cargo(hull) to 40.

  // The call she is making (bound(hull): 1 Skerrow, 2 Port Ness, 3 the Antlers) sets these when the fare is settled
  // (port.kyr): where the open-sea table stops outbound, how long she lies at the island, and the stations home.
  Measure seaEnd(entity). Measure stayFor(entity). Measure homeOpenAt(entity). Measure homeSoundAt(entity).
  Measure homeQuayAt(entity). Measure homeAt(entity). Measure voyages(entity).
  Initially Set seaEnd(hull) to 100. Initially Set stayFor(hull) to 217. Initially Set homeOpenAt(hull) to 32.
  Initially Set homeSoundAt(hull) to 120. Initially Set homeQuayAt(hull) to 160. Initially Set voyages(hull) to 0.
  // The window of the sea table (weather.kyr): on every open-sea leg, out or home, after the first hours and before
  // the next landfall is near.
  Query seaWindow(h: entity) means not homeward(h) and progress(h) >= 40 and progress(h) <= seaEnd(h) or homeward(h) and back(h) >= homeOpenAt(h) + 4 and back(h) <= homeSoundAt(h) - 4.

  // Time at sea: one tick for each watch she is under way and not in trouble.
  Rule sail_tick when sailed(hull) and not troubled(hull) and not arrived(hull) and not homeward(hull) and not safeHome(hull) { Increase progress(hull) by 1. }

  // The stations of her passage.
  Rule enters_open when at(hull, sound) and progress(hull) >= 36 and not homeward(hull) says "That was the last of the Sound's headlands, a minute since; and the Dorothea lifts to her first real swell. Bascom puts the pipe back in her mouth, which Rune says means she is satisfied." {
    Retract at(hull, sound). Assert at(hull, open_sea).
  }
  Rule enters_combs when at(hull, open_sea) and bound(hull) == 1 and progress(hull) >= 108 and not homeward(hull) says "Dawn comes up grey and cold, and in it, dead ahead and from rim to rim of the sea, a line of white. The Combs." {
    Retract at(hull, open_sea). Assert at(hull, teeth).
  }
  Rule enters_roads when at(hull, teeth) and progress(hull) >= 126 and not troubled(hull) and not homeward(hull) says "The Combs fall astern. The water goes from slate to green, and ahead a white tower stands on a green hill." {
    Retract at(hull, teeth). Assert at(hull, roads).
  }
  Rule reaches_jetty when at(hull, roads) and progress(hull) >= 140 and not arrived(hull) and not homeward(hull) and sailed(hull) says "A boy on the jetty catches the Dorothea's bow-line, and makes it fast to the third ring, and the whole ship settles against the stone with a sound like a long breath." {
    Retract at(hull, roads). Assert at(hull, jetty). Assert arrived(hull). Assert state(hull, moored_isle). Set reachedAt(hull) to watch(clock).
  }

  // ── Port Ness: a day's sail, nearer, with the salt ──────────────────────────────────────────────────────────────
  Rule enters_ness when at(hull, open_sea) and bound(hull) == 2 and progress(hull) >= 60 and not homeward(hull) says "The swell shortens, and the water goes from slate to a muddy green. A smell comes down the wind that is not the sea: wet earth, boiled brine, a thousand hearths. Low on the larboard bow there is a long grey shore with white mounds on it like a laundry." {
    Retract at(hull, open_sea). Assert at(hull, ness_roads).
  }
  Rule reaches_ness when at(hull, ness_roads) and progress(hull) >= 68 and not arrived(hull) and not homeward(hull) and sailed(hull) says "Port Ness takes the Dorothea in among its salt lighters, flat black barges with their sides white to the waterline. A man on the pier looks at her bow, and at her ensign, and writes something on a slate." {
    Retract at(hull, ness_roads). Assert at(hull, ness_quay). Assert arrived(hull). Assert state(hull, moored_ness). Set reachedAt(hull) to watch(clock).
  }

  // ── The Antlers: a night's sail, and a race between the stacks ──────────────────────────────────────────────────
  Relation pilotAboard(entity). Relation raceMet(entity). Relation towCalled(entity). Measure raceAt(entity).
  Rule enters_race when at(hull, open_sea) and bound(hull) == 3 and progress(hull) >= 92 and not homeward(hull) says "At first light the sea is full of towers. They stand up out of it by dozens, black and white, streaked like a barn roof, with a roar of birds about them that you hear before you see: the Antlers. Between the nearest stacks a lane of water runs like a street, and the swell goes up it in lumps." {
    Retract at(hull, open_sea). Assert at(hull, antler_race).
  }
  Rule race_with_pilot when at(hull, antler_race) and pilotAboard(hull) and not raceMet(hull) and not homeward(hull)
    says "Fenwick Pelham, who was asleep on a coil of rope an hour ago, stands up at the wheel as sober as a bell. He does not look at the stacks. He looks at the water between them, and takes the Dorothea up the race with his hands as light as a man playing a flute." {
    Assert raceMet(hull).
  }
  Rule race_trouble when at(hull, antler_race) and not pilotAboard(hull) and not raceMet(hull) and not homeward(hull)
    says "'The race,' says Bascom, and takes the pipe out. 'There's a pilot for this. There is meant to be.' The lane between the stacks is a quarter-mile of cross-sea, and every stone in it has a white beard. Rune looks at the Captain, and the Captain looks at the company." {
    Assert raceMet(hull). Assert troubled(hull). Set raceAt(hull) to watch(clock).
  }
  Rule reaches_antlers when at(hull, antler_race) and raceMet(hull) and not troubled(hull) and progress(hull) >= 104 and not arrived(hull) and not homeward(hull) and sailed(hull) says "She comes in under the biggest stack with the birds going up off it in a sheet, and a plank is run out to a ledge of wet rock no wider than a cart. Two anchors go down. A boy in a sack apron is already waving." {
    Retract at(hull, antler_race). Assert at(hull, antler_ledge). Assert arrived(hull). Assert state(hull, moored_antlers). Set reachedAt(hull) to watch(clock).
  }
  // ── Ashkeld: three days south-west, and the loneliest light on the Reach ────────────────────────────────────────
  Rule enters_ashkeld when at(hull, open_sea) and bound(hull) == 4 and progress(hull) >= 380 and not homeward(hull) says "On the third morning there is a cloud that does not move, standing on the sea ahead of the bow like a tree. As the Dorothea closes it, it has a foot: a black cone, a brown wash of ash on the water, and a smell like struck matches. Rune says, with real respect, that he would not live there for a thousand crowns. Mab says she would not either, and has already put a pot of the water aside to taste it." {
    Retract at(hull, open_sea). Assert at(hull, ashkeld_roads).
  }
  Rule reaches_ashkeld when at(hull, ashkeld_roads) and progress(hull) >= 396 and not arrived(hull) and not homeward(hull) and sailed(hull) says "The boat goes down on its falls and the company goes ashore in the surf, with the ketch rolling off the black beach on her anchors. Warm water runs up the sand, and steam stands up in rags from the rocks above. A woman in a leather apron has already come down with a barrow." {
    Retract at(hull, ashkeld_roads). Assert at(hull, ashkeld_beach). Assert arrived(hull). Assert state(hull, moored_ashkeld). Set reachedAt(hull) to watch(clock).
  }
  Observe deck_ashkeld_roads at deck when at(hull, ashkeld_roads) "Ashkeld roads: black sand, grey sea, ash drifting down on the deck like a thin snow, and the cone above it all with a flat red smear on the underside of its cloud that is not sunset.".
  Observe deck_ashkeld at deck when at(hull, ashkeld_beach) "Ashkeld: black beach, white steam, a smell of eggs. Women in leather aprons and men with their trousers rolled stand in the surf with barrows of yellow stone.".
  Observe deck_ness_roads at deck when at(hull, ness_roads) "Port Ness roads: a long shore with pans on it, square after square of grey water, and over them a haze of steam from the boiling-houses. Gulls stand on every post.".
  Observe deck_ness_quay at deck when at(hull, ness_quay) "Port Ness pier. Salt lighters lie three deep, their loads heaped white, and a gang of women in rag gloves are shovelling it down a chute into the dark of a barn. Nobody looks up.".
  Observe deck_race at deck when at(hull, antler_race) and not troubled(hull) "The race. Stacks go by close enough to touch, the guano white as a frost down their faces, the birds a roar of wings. Every few cables there is a rope hanging down one, and the end of it is in the sea.".
  Observe deck_race_trouble at deck when at(hull, antler_race) and troubled(hull) "The Dorothea lies hove-to at the mouth of the race with her sails shaking. The cross-sea runs up the lane and breaks on the stacks, and the stacks do not mind.".
  Observe deck_antlers at deck when at(hull, antler_ledge) "The Antlers' ledge: a wet shelf of rock, a plank, a hoist-rope going up a stack into cloud, and down the sheer wall of the biggest stack, a rope-ladder of such an age that the sea-birds have nested in it.".

  // ── Mangrow: five days south, and the green ────────────────────────────────────────────────────────────────────
  Rule enters_mangrow when at(hull, open_sea) and bound(hull) == 5 and progress(hull) >= 680 and not homeward(hull) says "On the fifth morning the sea changes colour from slate to tea, and a smell comes across it that is not the sea: wet leaf, rot, something sweet beyond the rot. Then a green wall rises from the water and goes on rising, and in it a single brown mouth. Rune says it is the only place he knows where the land has the weather." {
    Retract at(hull, open_sea). Assert at(hull, mangrow_roads).
  }
  Rule reaches_mangrow when at(hull, mangrow_roads) and progress(hull) >= 700 and not arrived(hull) and not homeward(hull) and sailed(hull) says "Bascom will not trust a line to the pier. Two anchors go down in the tea-coloured water and a plank is run out to the black piles, and at the end of it, with a cheroot, a thin dark woman is waiting to be paid." {
    Retract at(hull, mangrow_roads). Assert at(hull, mangrow_pier). Assert arrived(hull). Assert state(hull, moored_mangrow). Set reachedAt(hull) to watch(clock). Set stingAt(party) to watch(clock) + 6.
  }
  // The long legs read as days: Ashkeld's third and Mangrow's fifth.
  Observe deck_day_two at deck when at(hull, open_sea) and bound(hull) >= 4 and progress(hull) >= 150 and progress(hull) < 290 and not homeward(hull) and not troubled(hull) "The second day out. The wind has gone round to the south and there is warmth in it that was not there yesterday. The gulls have turned back. Nipper has stopped asking how far.".
  Observe deck_day_three at deck when at(hull, open_sea) and bound(hull) >= 4 and progress(hull) >= 290 and progress(hull) < 430 and not homeward(hull) and not troubled(hull) "The third day, and the sea is the same sea. The ship's sounds have settled into a drone. Mab has stopped serving the fresh bread, and the biscuit has become a subject.".
  Observe deck_day_four at deck when at(hull, open_sea) and bound(hull) == 5 and progress(hull) >= 430 and progress(hull) < 570 and not homeward(hull) and not troubled(hull) "The fourth day. Flying fish go across the bow in sheets. The water has begun to smell of something that is not salt. Bascom, at the wheel, has not said a word since breakfast, and when she does it is to ask for the lead.".
  Observe deck_day_five at deck when at(hull, open_sea) and bound(hull) == 5 and progress(hull) >= 570 and not homeward(hull) and not troubled(hull) "The fifth day, towards dusk. A drift of leaves goes by, and then a whole bough, and a bird of a colour you have no word for sits on the rail and looks at the company with deep disapproval.".

  // ── Fog in the Sound ────────────────────────────────────────────────────────────────────────────────────────────
  Rule fog_rolls when at(hull, sound) and progress(hull) >= 22 and not fogDone(hull)
    says "It comes down the Sound from the sea like a wall being let fall: first the headlands go, then the bow, then the hand on the rail. Bascom says 'Rune,' very quietly, and Rune is already at the lead." {
    Assert fog(hull). Assert troubled(hull). Assert fogDone(hull). Set fogAt(hull) to watch(clock).
  }
  Observe fog_deck at deck when fog(hull) "Fog, thick as wool. The jib has gone. Somewhere ahead and to larboard a bell is tolling, slow, and nobody aboard can say whether it is a buoy or a ship.".
  Action take_soundings(actor: group, site: place) "Take the lead-line forward and call the depth" {
    Description "A man in the bows with a weight on a cord can feel a shoaling before the bow does. It is not a thing that is done well by someone who has never done it.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and fog(hull) and not heaved(hull).
    Time 3.
    Resolve check(actor, wayfinding, dc_fair).
    On success { Retract fog(hull). Retract troubled(hull). }
    On failure { Increase water(hull) by 6. Assert holed(hull). }
    Result "You swing the lead and call it, and call it, and the number tells you the shape of the sea floor better than eyes: a hollow, a hump, the long sweep of the channel. When the bell is a ship's bell you call that, too, and the Dorothea wears away to starboard with ten fathoms to spare. Bascom looks at you for the first time as at a person. 'Where did you learn that,' she says. It is not quite a question.".
    Otherwise "The lead comes up and the number you call is the wrong number by a fathom, and the Dorothea's keel finds the Whelk Bank with a long groan that you feel in your teeth. Bascom takes the wheel from Rune and brings her off, swearing in a very low voice. In the hold a seam has opened and is letting in a little sea.".
  }
  Rule bascom_heaves when fog(hull) and not heaved(hull) and watch(clock) >= fogAt(hull) + 8
    says "Captain Bascom brings the Dorothea up into the wind and lets her sails go slack. 'We'll wait,' she says. 'We'll lose the morning, and we'll keep the keel.'" {
    Assert heaved(hull).
  }
  Rule fog_burns_off when fog(hull) and heaved(hull) and watch(clock) >= fogAt(hull) + 22
    says "Sometime in the small hours the fog tears, all at once, and there are stars, and a headland four cables off that nobody aboard had known was there. Bascom looks at it for some time. 'Right,' she says." {
    Retract fog(hull). Retract troubled(hull). Retract heaved(hull).
  }

  // ── The leak and the pump ───────────────────────────────────────────────────────────────────────────────────────
  Rule leak_gains when holed(hull) and sailed(hull) and not arrived(hull) and not safeHome(hull) and water(hull) < 60 { Increase water(hull) by 1. }
  Observe leak_hold at hold when water(hull) > 0 "Sea water slops about the hold, ankle-deep, black, and cold enough to hurt. It is the sort of cold that gets into a plank and stays.".
  Action pump(actor: group, site: place) "Work the pump" {
    Description "A hand-pump on the hold's ladder: two men to the brake. It is a labour done in turns, and nobody who has done it for an hour will say they enjoy it.".
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, hold) or at(actor, deck)) and water(hull) >= 6.
    Time 3.
    On success { Decrease water(hull) by 6. }
    Result "You work the brake until your arms stop being yours. The water goes down the side in a clear rush, and for a while it is a quarter inch lower.".
  }
  Rule bascom_calls_pump when water(hull) >= 18 and not callPumped(hull) and sailed(hull) and not arrived(hull) says "'All hands to the pump!' calls Bascom, in a voice that has never once needed to be raised. 'She's making water faster than I like.'" { Assert callPumped(hull). }
  Relation callPumped(entity).
  Rule founder_check when water(hull) >= 40 and sailed(hull) and not arrived(hull) and not foundered(hull) says "The Dorothea settles. It is a gentle thing, like a woman sitting down, and the sea comes over the rail without malice and without hurry." {
    Assert foundered(hull).
  }
  Relation foundered(entity).
}

data/adventures/the-dorothea/weather.kyr:
Module dorothea "The Dorothea" {
  Description "A table of the sea, drawn by the ship's own die: while she is in open water and not in trouble, each watch may bring one of five things (a squall, a drifting lantern, a fever, a calm, a fishing fleet). Two at most on a passage; which, and when, differ with the seed. Each is a Kyr rule keyed on dice(hull), so the table is data in the module and needs nothing from the engine.".

  Measure seaDrawn(entity). Measure seaAt(entity).
  // seaQuiet: a flat-calm passage (the table is off); the fixed-timeline tests of the first pass use it.
  Relation seaQuiet(entity). Relation squall(entity). Relation raft(entity). Relation fever(entity). Relation calm(entity).
  Relation squallDone(entity). Relation raftDone(entity). Relation feverDone(entity). Relation calmDone(entity). Relation fleetDone(entity).
  Initially Set seaDrawn(hull) to 0.

  // The window: open water, outward, not in other trouble, and not so near the Kestrel's hail that the two crowd.
  // The table, by the ship's die for the watch (1-100):  1-5 squall  6-10 raft  11-15 fever  16-20 calm  21-25 fleet.

  Rule sea_squall when at(hull, open_sea) and sailed(hull) and not troubled(hull) and seaWindow(hull) and seaDrawn(hull) < 2 and not seaQuiet(hull) and not squallDone(hull) and dice(hull) <= 5
    says "The horizon to windward has gone the colour of a bruise, and the swell, which was long and idle, shortens. Bascom looks at it, and at the sky over it, and then at Rune. 'Reef,' she says. 'Now.'" {
    Assert squall(hull). Assert squallDone(hull). Assert troubled(hull). Increase seaDrawn(hull) by 1.
  }
  Observe squall_deck at deck when squall(hull) "Rain comes across the deck in a sheet. The Dorothea lies over until the lee rail drinks, and every rope aboard has stopped humming and begun to scream.".
  Action reef_down(actor: group, site: place) "Go aloft with Rune and take in the topsail" {
    Description "A wet sail is a wet sail, and a wet sail in a squall is a hundred pounds of someone else's temper.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and squall(hull).
    Time 2.
    Resolve check(actor, wayfinding, dc_fair).
    On success { Retract squall(hull). Retract troubled(hull). }
    On failure { Retract squall(hull). Retract troubled(hull). Increase water(hull) by 8. Assert holed(hull). }
    Result "You go up the shrouds on your hands and your hope, and the sail comes in in armfuls, and Rune's hand is at your belt the whole time as if you were a thing he had paid for. By the time you are down the worst of it has gone over, and Bascom, at the wheel, has the look of someone who has won an argument with the weather by refusing to have it.".
    Otherwise "The sail takes you for its own and, for a moment, you are not sure it is wrong. Rune gets it in, and you, and the Dorothea takes a sea over the beam that finds the seam by the mast-step. It is a small seam. It will not stay one.".
  }
  Action run_before_it(actor: group, site: place) "Bear away and run before the squall" {
    Description "Nobody was ever hurt by running. It costs the watches that it costs.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and squall(hull).
    Time 6.
    On success { Retract squall(hull). Retract troubled(hull). Increase water(hull) by 3. Assert holed(hull). }
    Result "Bascom puts the wind on her quarter and lets the Dorothea go, and for an hour the sea goes under her like a road. When the sky lightens you are a long way to leeward of where you meant to be, and a little wetter, and the hold has a quarter-inch more in it than it had.".
  }

  Rule sea_raft when at(hull, open_sea) and sailed(hull) and not troubled(hull) and seaWindow(hull) and seaDrawn(hull) < 2 and not seaQuiet(hull) and not raftDone(hull) and dice(hull) > 5 and dice(hull) <= 10
    says "A speck on the water, to larboard, in the last of the light, and the speck is a light. Not a ship's: lower, steadier, riding on something flat. Mab, who sees it first, makes the sign against nothing in particular." {
    Assert raft(hull). Assert raftDone(hull). Assert troubled(hull). Increase seaDrawn(hull) by 1. Set seaAt(hull) to watch(clock).
  }
  Observe raft_deck at deck when raft(hull) "A raft of lashed casks, black with weed, with a stable lantern wired to a post at its middle. The lantern is lit, and has been filled this week, which is the odd part. On the post, in a hand a century out of fashion, is nailed a board with one word on it: HOLM.".
  Action take_the_lantern(actor: group, site: place) "Fish the lantern off the raft with a boat-hook" {
    Description "It is warm and nearly full. Whoever lit it did not mean it for the ship.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and raft(hull).
    Time 2.
    On success { Give lantern to actor. Assert raftLantern(actor). Retract raft(hull). Retract troubled(hull). }
    Result "Rune gets the hook through the ring, and you bring it over the rail. Mab trims the wick, sniffs the oil, and says it is lamp-oil like any other, which she seems to find the worst of it. She sets it on a cask in the galley, where she can see it.".
  }
  Action leave_the_raft(actor: group, site: place) "Sail on, and leave it burning" {
    Description "There are lights in the world that are for someone else.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and raft(hull).
    Time 1.
    On success { Retract raft(hull). Retract troubled(hull). }
    Result "The raft draws astern, and the lantern is a spark, and then it is Bascom's pipe, as she lights it from the binnacle and looks the other way.".
  }

  Rule sea_fever when at(hull, open_sea) and sailed(hull) and not troubled(hull) and seaWindow(hull) and seaDrawn(hull) < 2 and not seaQuiet(hull) and not feverDone(hull) and dice(hull) > 10 and dice(hull) <= 15
    says "Nipper does not come up for the morning watch. Mab goes down for him, and comes back up faster than she went, and says to nobody: 'He's burning.'" {
    Assert fever(hull). Assert feverDone(hull). Assert troubled(hull). Increase seaDrawn(hull) by 1.
  }
  Observe fever_deck at deck when fever(hull) "Below, in the fo'c'sle, a boy sweats in a hammock, with a face the colour of tallow, and mutters in the voice of someone describing a house to a person who is not there.".
  Action tend_the_boy(actor: group, site: place) "Sit with the boy through the worst of it" {
    Description "It is an old fever and an old cure: water, a wet cloth, and someone to be awake.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and fever(hull).
    Time 4.
    Resolve check(actor, insight, dc_easy).
    On success { Retract fever(hull). Retract troubled(hull). }
    On failure { Retract fever(hull). Retract troubled(hull). Decrease cargo(hull) by 2 or to nothing. }
    Result "You keep the cloth cold and the boy talking, and sometime before light his fever breaks like a plate. 'Mother,' he says, quite clearly, 'the Combs.' Then he sleeps.".
    Otherwise "You do what you can, and what you can is not quite it. He lives; but Mab spends two casks of the Pharos oil on a poultice, and does not say sorry, and does not look at the Captain.".
  }
  Action say_the_office_for_the_sick(actor: group, site: place) "Say the office for the sick over the boy" {
    Description "A short office, in the dialect of any harbour church. The words are less than the voice.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and fever(hull) and capable(actor, rites).
    Time 2.
    On success { Retract fever(hull). Retract troubled(hull). }
    Result "The office is short and has a gap in it for the sick person's name. You do not know the boy's second name and say 'Nipper', and Mab, at the door, nods as at a thing correctly entered. The fever lets go of him as a hand lets go of a rail.".
  }

  Rule sea_calm when at(hull, open_sea) and sailed(hull) and not troubled(hull) and seaWindow(hull) and seaDrawn(hull) < 2 and not seaQuiet(hull) and not calmDone(hull) and dice(hull) > 15 and dice(hull) <= 20
    says "The wind goes out of the afternoon like a held breath. The sails hang. The sea becomes a plate, a green one, with the Dorothea set down on it for someone to look at." {
    Assert calm(hull). Assert calmDone(hull). Assert troubled(hull). Increase seaDrawn(hull) by 1. Set seaAt(hull) to watch(clock).
  }
  Observe calm_deck at deck when calm(hull) "Nothing moves. A gull sits on the water a cable off and does not trouble to be anywhere else. The only sound is the ship's own timbers settling, one at a time, like old people sitting down.".
  Action sweeps_out(actor: group, site: place) "Man the sweeps and row her on" {
    Description "The Dorothea carries two long oars for harbours. Nobody built her to be rowed twelve miles.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and calm(hull) and capable(actor, brawn).
    Time 6.
    On success { Retract calm(hull). Retract troubled(hull). }
    Result "You and Rune and the cook take a sweep apiece. It is slow, wet, and unlovely. By the time a breath of wind comes, you have moved the Dorothea half a mile and your hands will not close.".
  }
  Rule calm_ends when calm(hull) and watch(clock) >= seaAt(hull) + 12 says "A cat's paw crosses the plate, and another, and the topsail fills, and someone aft clears his throat as if he had done it. Bascom lets out a breath. 'There,' she says, as if she had arranged it." {
    Retract calm(hull). Retract troubled(hull).
  }

  // A fleet is not a trouble: it is the sea being inhabited. It does not stop the count.
  Rule sea_fleet when at(hull, open_sea) and sailed(hull) and not troubled(hull) and seaWindow(hull) and seaDrawn(hull) < 2 and not seaQuiet(hull) and not fleetDone(hull) and dice(hull) > 20 and dice(hull) <= 25
    says "Sails, a dozen of them, tan and patched, working the swell in a loose line: a Port Ness salt-fleet at its drift-nets, with gulls over it like a second sky. A boat comes alongside with a basket of herring and a hail across the water, and Bascom answers it with a word and an arm. 'Ah,' says the man, and looks at her sails, and at the sea. 'Mind the lights, then. There are fewer of them every year. We lost the Mary Ann on the Combs at Lammas, and there was a night the Pharos was the only one of the lot of them showing.'" {
    Assert fleetDone(hull). Increase seaDrawn(hull) by 1.
  }
}

data/adventures/the-grand-tour/aftermath:
Module sennet "The Grand Tour" {
  // ── The morning's news ────────────────────────────────────────────────────────────────────────────────────────────
  // At eight on the morning the book closes, what became of each of the city's people is told, as Sennet tells it,
  // wherever the company is in the city. In a world that goes on, the city goes on from it.
  Query newsHour() means closingDay() and hour(clock) == 8.
  Rule news_perrin_crushed when newsHour() and perrinDead(party) and whelmCrushed(sennet_bay) and knows(party, perrin_alive) once says "Of Perrin Halyard: Cloudgate says he was dead already, and let down on the third day, and that is the end of it. He was under the bay. The bay is under a hill." { }
  Rule news_perrin_dead when newsHour() and perrinDead(party) and not whelmCrushed(sennet_bay) and knows(party, perrin_alive) once says "Of Perrin Halyard: the merfolk brought him up the Fish Stairs at dawn and laid him on the third step, above the plate, which nobody stopped them doing. His mother came down the chain for him herself. This time there is a body in the coffin." { }
  Rule news_perrin_up when newsHour() and perrinUp(party) and not perrinDead(party) once says "Of Perrin Halyard: he has taken a room over the Sounding Line, with his leg up on a stool, and is teaching Peg Arklow's potman Aenean, and is visited twice a day by his mother and his brother, separately, and every evening at the turn of the tide by a merfolk girl at the foot of the Fish Stairs, where he sits on the third step to talk to her with his bad leg in the sea." { }
  Rule news_perrin_under when newsHour() and not perrinUp(party) and not perrinDead(party) and not cloudgateFell(sennet_bay) and knows(party, perrin_alive) once says "Of Perrin Halyard: he is dead, officially, and was let down on the third day, and is in an air-bell under the bay with his leg mending, reading drowned books by an Aenean lamp, and is, the merfolk say, the happiest dead man in the Whelm." { }
  Rule news_brothers when newsHour() and aubreyFreed(aubrey) once says "Of Aubrey Halyard: he has stopped drinking his father's brandy, and started drinking his own, which is worse brandy and less of it. He goes down the chain every evening. Cloudgate has noticed that he looks at the view." { }
  Rule news_aubrey_guilt when newsHour() and not aubreyFreed(aubrey) and not perrinDead(party) and aubreyTalked(aubrey) and not cloudgateFell(sennet_bay) once says "Of Aubrey Halyard: he is still on the sofa in his rooms, with a bottle, believing what he believes. Nobody has told him otherwise." { }
  Rule news_imogen when newsHour() and imogenSorry(imogen) once says "Of the Dowager Lady Halyard: she has been seen on the Quay, in black, buying an eel pie from Old Bethan, which she did not eat, and asking the way to the Fish Stairs." { }
  Rule news_rector_taken when newsHour() and rectorTaken(quance) once says "Of the Rector: she is in the Watch-house on Fish Street, and the Courant has stopped printing Thresholds in the middle of Chapter Thirty-One." { }
  Rule news_rector_fled when newsHour() and rectorFled(quance) once says "Of the Rector: she was seen at first light walking up the coast road toward the downs alone, in an ordinary grey coat, with no chain, and nobody has seen her since. The House has found her study tidy and her desk empty except for a black case with four hollows in it, and a note, in violet ink: I DID NOT REVISE THIS." { }
  Rule news_rector_first when newsHour() and rectorThrough(quance) and not firstThrough(party) once says "Of the Rector: she went through the Door of Doors with the four petals of the Rose set in it, alone, and has not come back. Mr. Threlkeld has written in his ledger: MAGISTRA I. QUANCE. OUT." { }
  Rule news_halyards_fallen when newsHour() and cloudgateFell(sennet_bay) once says "Of the Halyards: the Dowager was carried off the hill on a door by four of her own footmen, upright, saying nothing; Aubrey Halyard was found in the wine cellar of Halyard House, up to his knees in the sea, holding a bottle, laughing." { }
  Rule news_rector_through when newsHour() and rectorThrough(quance) and firstThrough(party) once says "Of the Rector: she went through the Door of Doors after you, into everywhere, and did not come out again. Mr. Threlkeld has written in his ledger: MAGISTRA I. QUANCE. OUT. And has left the column for In empty." { }
  Rule news_tolley when newsHour() and tolleyFriend(tolley) once says "Of Mr. Tolley: the Courant on Fish Street has bought the first three chapters of A Romance of the Sea, by Edwin Tolley, for four coin, and asked for more." { }
  Rule news_fabian_home when newsHour() and fabianHome(party) once says "Of Fabian Murrey: he has taken the portrait of his grandmother down from over the counter at Murrey's, and put it up again, a little lower, and begun the seventh edition again from the first page, in pencil." { }
  Rule news_fabian_beloved when newsHour() and beloved(fabian) once says "Of Fabian Murrey, also: the seventh edition, when it comes out, will have a dedication. He will not tell anyone what it says, which in Lamp Street is taken to mean everyone knows." { }
  Rule news_fabian_away when newsHour() and fabianWilling(fabian) and not fabianHome(party) and not fabianLost(party) once says "Of Fabian Murrey: the shop on Lamp Street is shut, with a card in the window in pencil: GONE THROUGH. BACK SOON. F.M." { }
  Rule news_fabian_lost when newsHour() and fabianLost(party) once says "Of Fabian Murrey: the shop on Lamp Street is shut. Nobody has taken the books out of the window." { }
  Rule news_fabian_stayed when newsHour() and not fabianWilling(fabian) and met(fabian) once says "Of Fabian Murrey: he is behind the counter at Murrey's, correcting the commas in his grandmother's book." { }
  Rule news_bethan when newsHour() and bethanAtPeace(bethan) once says "Of Old Bethan: she is asleep behind her barrow on the Quay, in the sun, with her mouth open, and the harbour is stepping round her." { }
  Rule news_hapenny when newsHour() and hapennyShopped(hapenny) and not cloudgateFell(sennet_bay) once says "Of Ha'penny: she sits on the third step every morning with her cockles and a glass fish, which she shows to the harbour children, who have never seen a merfolk child so pleased with a thing she cannot eat." { }
  Rule news_admittance when newsHour() and admittanceLaughed(admittance) and stepTold(admittance) and not cloudgateFell(sennet_bay) once says "Of No Admittance and Mr. Pumphrey: they have met, at the third step, with the whole Quay watching, she in her crown in the water and he in his brass buttons on the step above with the Bylaws under his arm. Nobody heard what was said. When it was over he took a screwdriver out of his pocket and took the brass plate off the step, and gave it to her, and she took it down into the Whelm, where it is hung, they say, over the back door of the Guildhall, under the other sign." { }
  Rule news_prue when newsHour() and prueFriend(prue) and not madeSet(sennet_bay) once says "Of Prue Quickly: her furnace is roaring and she has had a new card printed for the tray of red glass: GENUINE PETALS OF THE ROSE. NOT REAL. ONE COIN. They sell twice as fast." { }
  Rule news_prue_cold when newsHour() and furnaceCold(glasshouse) and met(prue) once says "Of Prue Quickly: her furnace is cold, and she has gone to blow bottles for her cousin in a glass-house in another town, where nobody has heard of the Rose." { }
  Rule news_jem when newsHour() and jemFree(jem) once says "Of Jem Tuttle: he is Peg Arklow's potman at the Sounding Line, or Prue Quickly's stoker, and has not looked up once since he came down, and says it is the most beautiful thing in the world, the ground." { }
  Rule news_kittiwake when newsHour() and strikeSettled(sennet_bay) once says "Of the winch-gang: it has had its third, and Mother Kittiwake has chalked a new line under UP 5 COIN. DOWN FREE. NO DOGS on the slate on the basket rail: MERMAIDS BY ARRANGEMENT." { }
  Rule news_florian_changed when newsHour() and florianChanged(florian) once says "Of the Honourable Florian Mottram: he has given his cabinet of souvenirs to the Museum of the Tour, with a note asking Dr. Cole to send home anything that wants to go. Miss Sone has given notice to the Mottrams, and been taken on by Florian, as he puts it, as a friend." { }
  Rule news_florian when newsHour() and not florianChanged(florian) and met(florian) once says "Of the Honourable Florian Mottram: he has bought a print of the Door of Doors, opened, for his cabinet." { }
  Rule news_ember when newsHour() and emberHome(fire_land) once says "Of the ember: Cabinet Fourteen in the Museum of the Tour is empty, and Dr. Cole has left the label in it, and written under it in pencil: GONE HOME." { }
  Rule news_chert when newsHour() and travelsWith(chert, party) once says "Of Chert: he is on your boot, looking at a gull." { }
  Rule news_thursday when newsHour() and doorOpen(sennet_bay) once says "Of Thursday, the House's cat: Mr. Threlkeld saw him go through the cat-flap of the tower door yesterday, as he always does, and come out an hour later with sand in his fur from a beach nobody in Sennet has ever seen. The first through the Door of Doors in two hundred years, Mr. Threlkeld says, may not have been a person." { }
  Rule news_true_home when newsHour() and airHome(sennet_bay) once says "Of the North Wind: he has his petal back, and the wind off the sea at Sennet this morning is from the north, and warm." { }
  Rule news_true_rose when newsHour() and roseMade(sennet_bay) and not airHome(sennet_bay) once says "Of the Air petal: it is in the Rose, in the boss of the Door of Doors, with the other three, and the North Wind has not been told." { }
  Rule news_rector_barred when newsHour() and rectorFree() and rectorBarred(quance) once says "Of the Rector: she sat all night on the floor of the Nexus looking at the Door of Doors, and in the morning went down the tower stair and gave out that the Grand Tour was won, and that she would not go through herself, having seen it; which the Courant prints, and believes." { }
  Rule news_rector_balked when newsHour() and rectorBalked(quance) and rectorFree() once says "Of the Rector: she went down the keel ladder of Halyard House on the seventh night with her black case under her arm, Jem Tuttle says, and came up again an hour later with her hands bleeding and the case shut, and walked down the Promenade to the basket without a word to anyone. The Courant has received no chapter this week." { }
  Rule news_rector_free when newsHour() and rectorFree() and doorOpen(sennet_bay) and not rectorThrough(quance) and not rectorBarred(quance) once says "Of the Rector: she came up the tower stair from the Lanterns at midnight and found the Door of Doors open and the Grand Tour won, and sat down on the floor of the Nexus, and laughed for a long time. This morning she has given out that the Tour is won, magnificently, and is dictating the chapter about it; and has asked Mr. Tolley, very pleasantly, for the winner's name and lodging." { }
  Rule news_rector_unopened when newsHour() and rectorFree() and not doorOpen(sennet_bay) and not cloudgateFell(sennet_bay) and not rectorBalked(quance) once says "Of the Rector: she is in her study, dictating, and has asked Mr. Tolley to find out where you are lodging." { }

  // ── In a world that goes on ───────────────────────────────────────────────────────────────────────────────────────
  Observe after_market at glass_market when closingDay() and hour(clock) >= 9 and doorOpen(sennet_bay) "In the Glass Market a hawker is selling prints of the Door of Doors, opened, at a penny, with a figure going through it whose face is left blank, so that the buyer can draw their own.".
  Observe after_quay at quay when closingDay() and hour(clock) >= 9 and cloudgateFell(sennet_bay) "Halyard Hill stands in the bay a hundred yards off the end of the Fish Stairs, wet to its first floors, an island, with a ferry going out to it.".
  Observe after_crier at glass_market when closingDay() and hour(clock) >= 9 and not doorOpen(sennet_bay) "The crier's board says THE GRAND TOUR CONTINUES, in red, and under it, in chalk, someone has written: WHO WITH?".
  Rule news_aubrey_taken when newsHour() and aubreyTaken(aubrey) and not aubreyFreed(aubrey) once says "Of Aubrey Halyard: he is in the Watch-house on Fish Street, and has signed everything that was put in front of him, in a good clear hand. The Assize sits at Michaelmas. His mother has not been down." { }
  Rule news_sexton_kept when newsHour() and not bellSilent() and not sextonKilled(party) and knows(party, sexton_known) once says "Of the bell under the bay: it rings at the turn of the tide, morning and evening, as it always has, and the children of the Whelm ring it, and now some of them know why." { }
  Rule news_sexton_down when newsHour() and at(sexton, drowned_street) once says "Of the Whelm: Chandlers' Row is shut, and has been since the bell stopped. The merfolk go round by the Guildhall roof. Nobody in Sennet has noticed, except that there are fewer cockles on the third step." { }
  Rule news_sexton_dead when newsHour() and sextonKilled(party) once says "Of the Sexton: it lies along Chandlers' Row where it died, and the crabs are at it, and the children of the Whelm go and look at it every morning and are told not to. The children still ring the bell at the turn, for the noise. It keeps nothing now." { }
}

data/adventures/the-grand-tour/air.kyr:
Module sennet "The Grand Tour" {
  // ── The Plane of Air: the Gallery of Winds ────────────────────────────────────────────────────────────────────────
  // Every word said in the Air is carried everywhere at once, so nothing is secret there, and nothing is believed.
  // The sylphs' court gives audience by reputation: the North Wind receives only whoever is most talked of. Whatever
  // is said in the Gallery is blown down into Cloudgate and Sennet within the hour. The court's petal was given away
  // two hundred years ago by the North Wind, Prince Tramontane, to a mortal girl he loved.
  Query inAir() means within(party, air_land).
  Thing air_bar "the bar of the Air Door" on air_door {
    State sealed blocking "A bar of silver lies across the arch of the Air Door, with the Halyards' seal on it in green wax: whoever has the Halyards' leave lifts it, and sets it back.".
    State broken "The bar of the Air Door lies on the grass, and the Halyards' seal is broken.".
    Change break_seal "Break the Halyards' seal, and lift the bar off the Air Door" from sealed to broken.
  }
  Initially Assert keyholder(imogen, air_bar).
  Rule air_leave when (halyardLeave(party) or travelsWith(aubrey, party) or following(aubrey, party)) and not keyholder(party, air_bar) { Assert keyholder(party, air_bar). }
  Rule seal_broken when state(air_bar, broken) and not sealBroken(party) says "Somewhere behind you on the Promenade a footman shouts." { Assert sealBroken(party). Increase talk(party) by 1. }
  Relation sealBroken(group).
  Observe threshold_air at air_threshold when true "Through the arch, and there is nothing under your feet, and you do not fall. You stand on air, as on a floor of glass that is not there, and below you, a very long way below, cloud, and below the cloud, more sky. Wind goes past you in every direction at once, warm and cold, carrying voices. All the voices are talking about something.".
  Observe gallery_scene at gallery when true "The Gallery of Winds is a long hall made of nothing, a hall you know is there by the way the wind goes round its pillars. The sylphs of the Air are in it, a great many of them, slight and quick and nearly transparent, talking, all of them, all the time, in voices that go past you and come back from behind. Every word said anywhere in the hall is said everywhere in it a moment later.".
  Observe gallery_talk at gallery as ambience when inAir() "In the voices going past, you hear, over and over, the same few things: who the Rector of the House of Doors is dining with, what the Mottram boy said about his tailor, and your own name, which nobody here has been told.".
  Observe eyrie_scene at eyrie when true "The eyrie of the North Wind is the top of the sky: blue going to black, stars in the day, cold enough to hurt. There is nothing here but the wind, and the wind is a person: a tall pale shape with hair of snow streaming from it, who has been looking out over the edge of the world at nothing for a very long time.".

  Person sylphs "the sylphs of the Gallery" at gallery {
    Role "the sylphs of the Air, a great many, all talking". Ancestry sylph. Numbers 5. Calling mage. Level 3. Peaceable. Pronouns they.
    Greets "A sylph comes past you, turns round in the air, comes back, and looks at you very close, as a bird does. 'Oh, it's you!' they say. 'We've heard all about you. Have you heard what they're saying about you?' They do not wait for an answer. 'Neither have we. Tell us something.'".
    Greets again "'It's you!' say the sylphs. 'Tell us something.'".
  }
  Initially Assert overhears(sylphs).
  // What the sylphs hear is down in Cloudgate within the hour, and in Sennet by the next.
  Relation gossip(entity). Measure gossipAt(entity). Relation blown(entity).
  Rule gossip_noted when heardOf(sylphs, ?f) and not gossip(?f) { Assert gossip(?f). Set gossipAt(?f) to watch(clock). }
  Rule gossip_blows when gossip(?f) and not blown(?f) and watch(clock) >= gossipAt(?f) + 6 {
    Assert blown(?f). Assert heardOf(quance, ?f). Assert heardOf(imogen, ?f). Assert heardOf(aubrey, ?f). Assert heardOf(florian, ?f). }
  Rule gossip_heard within cloudgate when gossip(?f) and blown(?f) and not gossipHeard(?f) and within(party, cloudgate)
    says "A wind comes down out of the clear sky over Cloudgate, cold, smelling of snow, and every window on the Promenade bangs at once; and in the wind, very small and very fast, voices, telling it to everyone in the street." { Assert gossipHeard(?f). }
  Relation gossipHeard(entity).
  Topic sylphs_petal with sylphs "Ask the sylphs about the Air petal of the Rose" when true once {
    Says "'Oh, that!' They are delighted. It is the oldest thing in the Air to talk about and they talk about it. 'Tramontane gave it away! The North Wind! To a girl! A mortal girl from the Sennet side, Ysabeau, with red hair, two hundred years ago, they talked all one summer up in his eyrie and he gave her the petal for a keepsake, the court's own petal, imagine, and she took it home and set it in the bottom of her hill and lifted her whole family into the sky with it.' They go round you, faster. 'And the sea came in. And she never came back. And he's been blowing cold ever since, haven't you noticed, the north wind, it's cold, it's because of her.' They come close. 'It's still there! In the hill! Holding them up! Everyone knows! Nobody ever says!'".
    On discuss { Assert knows(actor, keel_petal). Assert knows(actor, tramontane_story). }
  }
  Discovery tramontane_story "Prince Tramontane, the North Wind, gave the Air court's petal to Ysabeau Halyard, a red-haired girl from Sennet he loved, two hundred years ago, after a summer in his eyrie. She set it in the keel of her hill and lifted it into the sky, and never came back. The sylphs say he has blown cold ever since.".
  Topic sylphs_audience with sylphs "Ask the sylphs how you might be received by the North Wind" when true once {
    Says "'You have to be talked about!' They seem to think this obvious. 'He only sees whoever's most talked of. Everybody's talking about the Rector this week, and the Mottram boy, and before that it was a goat.' They consider you. 'You're hardly talked about at all. Do something! Do something in Cloudgate, everybody listens to Cloudgate. Or tell us something, and we'll talk about you telling us.' They laugh, a sound like a flute with a crack in it. 'Something true, preferably. We can't tell the difference, but it's more fun.'".
    On discuss { Assert knows(actor, talked_of). }
  }
  Discovery talked_of "The North Wind receives only whoever is most talked of in the Air. Something done in Cloudgate is talked of there; so is anything told to the sylphs, who carry it down into Cloudgate and Sennet within the hour.".
  Topic sylphs_self with sylphs "Tell the sylphs one true thing about yourself" when not toldSelf(actor) once {
    Says "You tell them. You do not know why you choose the thing you choose; it is the first true thing that comes. They listen, all of them, perfectly still for once, and then they take it away with them in every direction at once, and a moment later it comes back to you from behind, said in a hundred voices, and it sounds, said by them, like something worth having said.".
    On discuss { Assert toldSelf(actor). Increase talk(actor) by 1. }
  }
  Relation toldSelf(group).
  Topic sylphs_alive with sylphs "Tell the sylphs that Perrin Halyard is alive" when knows(actor, perrin_alive) and not heardOf(sylphs, perrin_alive) once {
    Grave "Whatever is said in the Gallery is down in Cloudgate within the hour, and in Sennet, and in the House of Doors.".
    Says "There is a silence in the Gallery of Winds, which has not happened in living memory. Then the sylphs scream, all of them, with joy, and are gone in every direction at once, down, down, toward the cloud and the hill and the city, telling it.".
    On discuss { Assert heardOf(sylphs, perrin_alive). Assert toldAlive(actor). Increase talk(actor) by 2. }
  }
  Topic sylphs_pushed with sylphs "Tell the sylphs that it was the Rector of the House of Doors who pushed Perrin Halyard" when knows(actor, quance_pushed) and not heardOf(sylphs, quance_pushed) once {
    Grave "Whatever is said in the Gallery is down in Cloudgate within the hour, and in Sennet, and in the House of Doors.".
    Says "The sylphs do not believe it; they never believe anything. But they have never in their lives had anything so good to not believe. They go out of the Gallery like a flock of starlings off a field.".
    On discuss { Assert heardOf(sylphs, quance_pushed). Assert heardOf(sylphs, perrin_alive). Assert toldAlive(actor). Increase talk(actor) by 3. }
  }
  Topic sylphs_keel with sylphs "Tell the sylphs, out loud, that the Air petal is in the keel of Cloudgate" when knows(actor, keel_petal) and not heardOf(sylphs, keel_petal) once {
    Says "'We know!' they cry, all of them, enchanted. 'But nobody's ever said it! Out loud! In the Gallery!' And they are off, saying it, out loud, in every direction, all the way down.".
    On discuss { Assert heardOf(sylphs, keel_petal). Increase talk(actor) by 2. }
  }

  // ── Prince Tramontane, the North Wind ─────────────────────────────────────────────────────────────────────────────
  Passage eyrie_rise "the updraught" is path between gallery and eyrie taking 5 minutes
    opening when talk(party) >= 3 or following(imogen, party) "The north wind will not let you up: it puts you back down in the Gallery like a leaf. The sylphs say he receives only whoever is most talked of.".
  Person tramontane "Tramontane" at eyrie {
    Role "the North Wind, a prince of the Air, with hair of snow". Ancestry sylph. Calling mage. Trait conjurer. Level 10. Peaceable. Pronouns he. Manner grim.
    Wants air_petal_kind. Wants ysabeau_letter_kind.
    Greets "The tall pale shape turns from the edge of the world, slowly, and looks at you, and you are cold to the bone. 'They talk of you,' says the North Wind. His voice is the sound of a wind round a house at night. 'Down there, and up here. So you are let up.' He looks at you longer. 'You have come from Sennet. You smell of the sea.' And then, after a long time: 'Is it still there? The hill?'".
    Greets again "The North Wind turns his head to you, and the cold comes with it.".
  }
  Relation tramontaneHeard(group).
  Topic tramontane_ysabeau with tramontane "Tell the North Wind the hill is still there, and ask him about Ysabeau" when true once {
    Says "He is silent so long the stars move. 'She came up through the arch at seventeen, on a dare, with her skirts tied up, and stood on nothing, and was not afraid. Nobody had come up for a hundred years.' The wind goes round you, softer. 'We talked a summer. I was four hundred; I was young. At the end of it she said, give me something to remember you by, and I gave her the petal. The court's petal. I had no right.' His face does not change. 'She went home and set it in the bottom of her family's hill and lifted them into the sky above the smell of fish. And the sea came in under them, and her people's people drowned in their beds. And she never came back up the arch. Not once.' He looks at the edge of the world. 'She used it as a lever. I gave her my heart and she used it as a lever.' A pause. 'I have blown cold since. You will have noticed.'".
    On discuss { Assert tramontaneHeard(tramontane). Assert knows(actor, tramontane_story). Assert knows(actor, keel_petal). }
  }
  Topic tramontane_want with tramontane "Ask the North Wind whether he wants the petal back" when tramontaneHeard(tramontane) and not giftRenewed(sennet_bay) once {
    Says "'Want.' He tries the word as if it were in another language. 'The court wants it back. The court has wanted it back for two hundred years; it is the court's.' He looks at you. 'I want her to have meant it.' The cold deepens. 'Bring it back, and I will take it, and her hill will go down into the sea where it came out, and that is justice, I suppose. Or bring me something that says she meant it, and I will let it be what it was, a keepsake, and let it hold up her house as long as it likes.' He turns back to the edge of the world. 'I do not know which I would rather. Bring me one or the other.'".
    On discuss { Assert knows(actor, tramontane_terms). }
  }
  Discovery tramontane_terms "The North Wind will take the Air petal back, and let Cloudgate go down into the sea; or, brought something to show that Ysabeau loved him, he will let the petal be a keepsake still, and hold up her house as long as it likes.".
  // Ysabeau's letter, or a Halyard come to say they are sorry: the gift renewed.
  Event letter_read near tramontane when keeps(tramontane, ysabeau_letter) and not giftRenewed(sennet_bay) "The North Wind reads it. It is two lines; he reads it twice, the second time with a finger under the line. Then his face, which has not changed since you came up, changes, and the cold goes out of the eyrie all at once like a held breath let go, and somewhere far below, over Sennet, in June, it begins to snow: big soft flakes out of a clear sky, falling on the Quay and the glass-houses and the bay and on Cloudgate, settling on the orange trees. 'Remember me,' says Tramontane. 'She said that.' He folds the letter very small. 'Then let her house keep what I gave her. Tell them it is a keepsake. Tell them it is not theirs.' He looks at you. 'And tell them the North Wind is sorry about the sea.'" then {
    Assert giftRenewed(sennet_bay). }
  Event halyard_sorry near tramontane when at(party, eyrie) and (following(imogen, party) and imogenSorry(imogen)) and not giftRenewed(sennet_bay) "Lady Imogen Halyard stands on nothing at the top of the sky in her black lace, with her chin up, and says to the North Wind what nobody of her name has said in two hundred years: that her family took what it was given in love and used it as a lever, and let the sea in on its neighbours, and never once came back to say so; and that she is sorry. Her voice does not shake until the last word. The North Wind considers her, as he considers weather. 'You have her chin,' he says. And somewhere far below, over Sennet, in June, it begins to snow." then {
    Assert giftRenewed(sennet_bay). Retract following(imogen, party). Assert at(imogen, drawing_room). }
  Event petal_home near tramontane when keeps(tramontane, air_petal) and not airHome(sennet_bay) "The North Wind takes the petal, and it stops pulling upward in his hand, and lies still, as if it had come to the end of a long way. 'Home,' he says. He closes his hand on it. 'You know what it held up.' He does not ask; he is not a person who asks. 'Then it is done, and it was not mine to do.' He looks down, through the cloud, toward the place where the hill was." then {
    Assert airHome(sennet_bay). }
  Relation airHome(place).
  // A breath of him, for Prue's furnace; given if asked, or caught in a jar.
  Kind feather_kind "a feather of the North Wind" is gear worth 0 weighing -1 granting climbing described "A long white feather, cold to the touch, that lifts a little toward the sky when you open your hand. Whoever carries it does not fall: they come down, wherever they come down, like a leaf.".
  Item north_feather "a feather of the North Wind" is feather_kind at offstage.
  Item north_jar "a jar of the North Wind" is north_wind_kind at offstage.
  Topic tramontane_jar with tramontane "Ask the North Wind for a breath of himself in a jar, for a glass-blower in Lamp Street" when tramontaneHeard(tramontane) and holding(actor, wind_jar_kind) and at(north_jar, offstage) once {
    Says "'For a glass-blower.' Something that might once have been a smile goes over the North Wind's face. 'To make another petal. To set in her hill in place of mine, so that mine can come home and her house stay up.' He considers the idea as if he had never met one before. 'That is the first new thing anybody has said to me since the jar.' He breathes into the jar. Frost grows inside the glass in ferns. He stops it himself, with one cold finger.".
    On discuss { Spend wind_jar_kind from actor. Give north_jar to actor. }
  }
  Action catch_wind(actor: group, site: place) "Unstop the empty wind-jar and hold it up into the North Wind" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, eyrie) and holding(actor, wind_jar_kind) and at(north_jar, offstage).
    Time 1 minute.
    On success { Spend wind_jar_kind from actor. Give north_jar to actor. }
    Result "The North Wind gets into the jar the way it gets into everything, and you stop it, and the glass goes white with frost in your hands and pulls a little upward. The tall pale shape at the edge of the world does not turn round.".
  }
  Topic tramontane_feather with tramontane "Ask the North Wind what he will give whoever brings his gift home" when (airHome(sennet_bay) or giftRenewed(sennet_bay)) and at(north_feather, offstage) once {
    Says "He takes a feather out of the air, or out of himself; it is hard to tell. 'Carry this,' he says. 'Whoever carries it does not fall.' He gives it you. 'It seemed to me a thing somebody in your city should have.'".
    On discuss { Give north_feather to actor. }
  }
}

data/adventures/the-grand-tour/ascent.ky:
Module sennet "The Grand Tour" {
  // ── The Ascent ────────────────────────────────────────────────────────────────────────────────────────────────────
  // One way up to Cloudgate for a person who cannot climb two hours of chain: the basket, wound up the anchor chain
  // by four capstans in the winch-house, sixty men and women on the bars in shifts, under Mother Kittiwake. Five coin
  // a head by day. At dawn the laundry of Cloudgate goes up (Cloudgate has no water to wash in) and whoever carries a
  // hamper rides with it. Down is free: nobody, Mother Kittiwake says, has ever been charged for coming down to earth.
  Observe yard_scene at ascent_yard when true "The anchor chain comes down out of the cloud into the middle of the yard, each link the size of a door, and goes into the ground through an iron collar on a granite block the size of a house, and the whole yard hums with it, very low, the way a church does after the organ has stopped. Beside it the winch-house, all doors and chimneys, smoking.".
  Observe yard_chain at ascent_yard when not descending(sennet_bay) and not cloudgateFell(sennet_bay) "Looking straight up the chain you lose it in the cloud a long way up, and above the cloud, very small, very sunlit, the underside of Cloudgate.".
  Observe winch_scene at winch_floor when true "The winch-house: four capstans as big as merry-go-rounds, each with fifteen bars and fifteen people on them, walking round and round in a thunder of boots and chain, singing. In the middle of the floor the basket waits on its hook, a wicker thing the size of a cart with a bench in it and a rail round it, and a slate hanging off the rail: UP 5 COIN. DOWN FREE. NO DOGS.".
  Observe winch_strike at winch_floor when strike(sennet_bay) "The capstans stand still. The bars are leant against the wall, and the gang sits on the floor round them playing cards, very loudly, so that it can be heard up the chain.".

  Person kittiwake "Mother Kittiwake" at winch_floor {
    Role "the master of the winch-gang, with a voice like a foghorn". Ancestry human. Peaceable. Pronouns she. Manner jovial.
    Greets "A woman built like a capstan herself, in a leather apron with a bosun's whistle on a chain, looks you up and down. 'UP OR DOWN?' she says, at a volume meant for the far side of the bay, and then, at a normal one, seeing you flinch: 'Sorry, love. Twenty years in here. Up's five. Down's free. Nobody's ever been charged for coming down to earth.'".
    Greets again "'UP OR DOWN?' says Mother Kittiwake, cheerfully.".
  }
  Relation gangFriend(group). Relation strike(place). Relation strikeSettled(place). Relation laundryHand(group).
  Rule kittiwake_day when hour(clock) >= 5 and hour(clock) < 22 and not at(kittiwake, winch_floor) { Assert at(kittiwake, winch_floor). }
  Rule kittiwake_night when (hour(clock) >= 22 or hour(clock) < 5) and not at(kittiwake, offstage) { Assert at(kittiwake, offstage). }
  Query basketRuns() means (hour(clock) >= 5 and hour(clock) < 22 or lanternNight() or (day(clock) == 5 and hour(clock) < 1)) and not strike(sennet_bay) and not descending(sennet_bay) and not cloudgateFell(sennet_bay).
  Action ride_up(actor: group, site: place) "Pay five coin and go up in the basket" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, winch_floor) and basketRuns() and not gangFriend(actor) and quantity(actor, gold) >= 5.
    Time 3.
    On success { Decrease quantity(actor, gold) by 5. Increase quantity(kittiwake, gold) by 5. Assert at(actor, landing_stage). }
    Result "You sit on the bench. Mother Kittiwake blows her whistle and the capstans start to walk, and the floor drops away, and the roof, and the winch-house is a box of noise under you, and the city a map, and the bay a plate, and then the cloud comes down over all of it, white, cold, wet, for a long time, nothing but the chain going up beside you link by link like a ladder in a dream. And then you come up out of it, and Cloudgate is over your head with its gardens hanging over the edge, and the basket comes up through a hole in the Landing Stage like a bucket out of milk.".
  }
  Action ride_up_free(actor: group, site: place) "Go up in the basket, a friend of the gang" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, winch_floor) and basketRuns() and gangFriend(actor).
    Time 3.
    On success { Assert at(actor, landing_stage). }
    Result "'Mind your heads,' says Mother Kittiwake, and blows the whistle, and the gang sings you up through the cloud.".
  }
  Query laundryHour() means hour(clock) >= 5 and hour(clock) < 8.
  Action ride_laundry(actor: group, site: place) "Carry a hamper of Cloudgate's laundry up in the dawn basket" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, winch_floor) and laundryHour() and basketRuns().
    Time 3.
    On success { Assert at(actor, landing_stage). Assert laundryHand(actor). }
    Result "Nobody asks who you are. A girl hands you a wicker hamper with HALYARD stencilled on the lid, smelling of starch, and you go up with nine laundresses and forty hampers through the cloud in the grey of the early morning, and at the top, in sudden gold light, a footman in a green coat is waiting on the Landing Stage with a list, and ticks off your hamper without looking at your face.".
  }
  Action ride_down(actor: group, site: place) "Go down in the basket" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, landing_stage) and basketRuns().
    Time 3.
    On success { Assert at(actor, winch_floor). }
    Result "Down through the cloud, and out of the bottom of the cloud into Sennet's weather, whatever it is, with the bay coming up at you and the capstans' thunder coming up through the floor of the basket, until you are set down on the winch-house floor and somebody unhooks you.".
  }
  // In the Halyards' laundry, by the back way: the servants' hall takes in its hampers, and nobody looks at whoever
  // carries one.
  Action laundry_in(actor: group, site: place) "Carry the Halyards' hamper round to the servants' hall" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, landing_stage) and laundryHand(actor) and laundryHour().
    Time 1.
    On success { Assert at(actor, servants_hall). Retract laundryHand(actor). }
    Result "Round the back of the Promenade, down an area, through a green door, into a stone-flagged hall with a long table and a fire, where a cook takes the hamper off you and gives you a cup of tea for your trouble without asking your name.".
  }
  Rule laundry_done when laundryHand(party) and not laundryHour() { Retract laundryHand(party). }

  // ── The capstan ───────────────────────────────────────────────────────────────────────────────────────────────────
  Action work_capstan(actor: group, site: place) "Put your shoulder to a capstan bar for a shift" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, winch_floor) and at(kittiwake, site) and openHours() and not gangFriend(actor) and not strike(sennet_bay).
    Time 18.
    On success { Assert gangFriend(actor). }
    Result "Mother Kittiwake looks at you as if you had offered to marry her, and then puts you on number three capstan between a boy of fourteen and a woman of seventy who walks you off your feet. You walk round. You walk round. The chain goes up and comes down; baskets of Tourists go up, baskets of laundry come down; the gang sings, the same song, which is about a girl in Cloudgate who dropped her garter and what became of the man it hit. At the end of the shift your legs have stopped belonging to you, and Mother Kittiwake slaps you on the back hard enough to loosen a tooth. 'You'll go up free,' she says. 'Whenever you like. You've earned it the hard way, which is the only way up that's honest.'".
  }
  Topic kittiwake_halyards with kittiwake "Ask Mother Kittiwake how the gang gets on with Cloudgate" when true once {
    Says "'Cloudgate pays by the basket. The Halyards pay, being the first family, and the rest pay the Halyards.' She spits, accurately, into a bucket. 'Since the boy fell, the Dowager's docked us. A third. Mourning economies, says her steward. They've stopped the laundry going up twice a week and the coal going up and our pay going down, and the wine still goes up every morning, I notice.' She folds her arms. 'Ascension Day's the fourth day. They'll want every basket running for their lanterns. If we've not had our third by noon on Ascension Day, the gang sits down.'".
    On discuss { Assert knows(actor, strike_coming). }
  }
  Discovery strike_coming "Since Perrin Halyard fell, the Dowager of Cloudgate has docked the winch-gang's pay by a third. Unless it is paid back by noon on Ascension Day, the fourth day, Mother Kittiwake's gang will sit down and the basket stop.".
  Rule strike_begins when day(clock) == 4 and hour(clock) >= 12 and not strikeSettled(sennet_bay) and not strike(sennet_bay) and not strikeOver(sennet_bay)
    says "At noon a long horn blows from the winch-house at the foot of the Ascent, and goes on blowing, and then stops; and the chain, which has hummed all your time in Sennet, is silent. The winch-gang has sat down." {
    Assert strike(sennet_bay). }
  Relation strikeOver(place).
  // Cloudgate holds out for six hours, and then it runs out of clean shirts for the Lanterns.
  Rule strike_ends when strike(sennet_bay) and day(clock) == 4 and hour(clock) >= 18
    says "At six in the evening the Halyards' steward comes down the chain on a bosun's chair, which nobody has seen a steward do before, with a purse. Cloudgate has run out of clean shirts for the Lanterns. The horn blows again, short, and the chain starts to hum." {
    Retract strike(sennet_bay). Assert strikeOver(sennet_bay). }
  Topic kittiwake_paid with kittiwake "Pay Mother Kittiwake the gang's third out of your own purse, twenty coin" when knows(actor, strike_coming) and not strikeSettled(sennet_bay) and not strikeOver(sennet_bay) and quantity(actor, gold) >= 20 once {
    Says "She looks at the coins in her hand for a long moment. 'From you,' she says. 'Well.' She weighs them. 'Then it's the Halyards owe you, not us. That's better. That's a lot better.' She blows the whistle. 'BACK ON THE BARS. WE'VE BEEN PAID BY A STRANGER.' The gang cheers, and looks at you, and the look is the look of sixty people who will remember your face.".
    On discuss { Decrease quantity(actor, gold) by 20. Increase quantity(kittiwake, gold) by 20. Assert strikeSettled(sennet_bay). Assert gangFriend(actor). Retract strike(sennet_bay). }
  }
  // Or the Dowager is brought to pay it, by someone she will hear (cloudgate.kyr); either way the gang knows who.
  Rule strike_settled_up when strikeSettled(sennet_bay) and strike(sennet_bay) { Retract strike(sennet_bay). }

  // ── The night Perrin fell ─────────────────────────────────────────────────────────────────────────────────────────
  // The winch-gang knows who went up and who came down, and when, because it carried them. It does not tell
  // Cloudgate's business to anyone who has not walked a shift, or put money in the gang's hand.
  Topic kittiwake_night with kittiwake "Ask Mother Kittiwake who came down the night Perrin Halyard fell" when gangFriend(actor) and heardFall() once {
    Says "She stops the capstan with a blast of the whistle and comes close, and for once her voice is not much more than an ordinary voice. 'The Rector,' she says. 'Magistra Quance, in her gown, with her chain on. She went up on the seven o'clock with all the House for the Halyards' do, and the House came down at nine, all of them, except her. She came down on the eleven o'clock. Alone. That was after the bells, and the shouting up there, and the fog.' She looks at her own hands. 'She gave me a crown. A crown, for the basket, that's free going down. And her hand was shaking so, she dropped it, and I picked it up for her.' She straightens. 'I put it down to the height. Everybody shakes, coming down off that rock after a death.' A pause. 'I'd not say it to anybody that hadn't walked my bars.'".
    On discuss { Assert knows(actor, late_basket). }
  }
  Discovery late_basket "On the night Perrin Halyard fell, the Rector, Magistra Quance, did not come down from Cloudgate on the nine o'clock basket with the rest of the House, but alone on the eleven o'clock, after the fall, and tipped Mother Kittiwake a crown for a basket that is free going down, with a hand that shook so that she dropped it.".
}

Module sennet "The Grand Tour" {
  Description "What a company's bard hears in Sennet that nobody else would, and the one thing only a bard can do for the North Wind: sing him the Quay's song of the girl who stood on nothing.".

  // ── The bard's ear ──────────────────────────────────────────────────────────────────────────────────────────────
  // Said once for the company, by whoever it has of the calling. A company without a bard has nobody to hear any of it.
  Relation heardQuayCries(group). Relation heardRoll(group). Relation heardDrownedStreet(group). Relation heardBalustrade(group).
  Rule bard_quay at quay when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, quay) and not heardQuayCries(party)
    says "{?m} stands at the end of the Quay with eyes shut for the length of three street-cries. 'Eel pie, a penny,' {?m} says at last, to nobody. 'Always the same four notes, down to the last one, and then she drops the last one. Twenty years of it. Somebody taught her the whole tune, and she has kept the part that sells.'" {
    Assert heardQuayCries(party).
  }
  Rule bard_roll at hall_of_doors when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, hall_of_doors) and not heardRoll(party)
    says "{?m} reads the gilt of the Roll aloud, under the breath, and stops at the entry for 1088. 'DECLARED NOTHING,' {?m} says. 'A clerk wrote that. A clerk who had been told nothing, and did not like it, and found the only verdict he had. Nobody declares nothing. You declare nothing when what you have to say will not go into a column.'" {
    Assert heardRoll(party).
  }
  Rule bard_drowned at drowned_street when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, drowned_street) and not heardDrownedStreet(party)
    says "{?m} tilts a head toward the water and listens to the shop-signs knock on their chains. 'Four of them in tune,' {?m} says, pleased in spite of the cold. 'Somebody hung the signs by pitch, a long time before there were merfolk to name themselves out of them. I would not have thought a draper cared.'" {
    Assert heardDrownedStreet(party).
  }
  Rule bard_balustrade at balustrade when memberOf(?m, party) and hasCalling(?m, calling_bard) and awake(?m) and at(party, balustrade) and aloft() and not heardBalustrade(party)
    says "{?m} leans on the rail where the young man went over it, and does not look down. 'No echo,' {?m} says. 'You can shout off any rail in the world and the sea shouts back. Here the cloud eats it.' A pause. 'He would have heard nothing at all on the way down. Not even himself.'" {
    Assert heardBalustrade(party).
  }

  // ── The Quay's song ─────────────────────────────────────────────────────────────────────────────────────────────
  // A tune that old women on the Quay hum over the eels and cut off before the end; they will give the end to someone who
  // can carry it. Only a bard asks the right question, because only a bard knows that a tune cut off is a tune with a
  // last verse in it.
  Discovery ysabeau_ballad "The Quay has a song of the girl from the hill who stood on nothing; the last verse says that every night of her life she left the north casement unlatched, and her daughters after her.".
  Topic bethan_ballad with bethan "Ask Old Bethan for the last verse of the song she hums over the eels" when memberOf(?m, actor) and hasCalling(?m, calling_bard) and hour(clock) >= 8 and hour(clock) < 18 once {
    Says "Old Bethan stops with the knife in an eel. 'Who told you there was a last verse?' She looks at you, and at your hands, and decides. 'Nobody sings it. The girl from the hill, that went up the arch on a dare.' Her voice is cracked and perfectly true. 'She stood on nothing and she was not afraid, and she came home with the wind in her skirts. She never went back up the arch, but her window faces north, and every night of her life she left it latched to nothing, and her daughters after her, and the Halyard women to this day.' She goes back to the eel. 'That is all of it. It never rhymed. I put the rhyme on myself.'".
    On discuss { Assert knows(actor, ysabeau_ballad). }
  }
  Discovery casement_known "In the drawing room of Halyard House the northmost casement is found unlatched every morning, though the footmen shut it every night, and the household has long ago given up asking why.".
  Observe casement_unlatched at drawing_room when aloft() and not knows(party, casement_known) "At the northmost end of the long row of windows one casement stands a hand's breadth open on the cloud, and the draught from it moves the fringe of the nearest chair. A footman, passing with a duster, shuts it with his thumb without breaking step. 'Every night,' he says, not to you. 'And every morning.'" teaches casement_known.
  Action sing_to_the_wind(actor: group, site: place, b: member) "Sing the North Wind the last verse, as the Quay has it" {
    Description "Not a letter, and not an apology. A custom that has been kept up in the dark by people who could not have said what for.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, eyrie) and memberOf(b, actor) and hasCalling(b, calling_bard) and awake(b)
      and tramontaneHeard(tramontane) and knows(actor, ysabeau_ballad) and knows(actor, casement_known)
      and not giftRenewed(sennet_bay) and not airHome(sennet_bay).
    Time 6.
    On success { Assert giftRenewed(sennet_bay). }
    Result "{b} sings it the way Bethan has it, without the rhyme, flat, to the edge of the world. The North Wind does not turn round. At the last verse, the one about the casement, the cold in the eyrie goes still, as if it were listening with its whole body. 'Latched to nothing,' says Tramontane. 'Every night.' It is a long time before he speaks again. 'The footmen shut it, and she opened it. And the daughters.' Far below, over Sennet, in June, it begins to snow. 'Then she meant it,' he says. 'Tell them it is a keepsake. Tell them it is not theirs.'".
  }
}

data/adventures/the-grand-tour/clock.kyr:
Module sennet "The Grand Tour" {
  // ── The week ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // Sennet's days are counted from the company's coming: the morning it comes down the coast road is the first. The
  // coffin goes off the Balustrade at noon on the third day; the Night of Lanterns is the fourth night; the book
  // closes on the eighth morning, or the morning after the Door of Doors is opened, whichever is first. In a world
  // that goes on, the first day begins the first morning after Sennet is reached, and nothing of it happens before.
  Query begun() means watch(clock) >= 0.
  Query morning() means hour(clock) >= 6 and hour(clock) < 12.
  Query afternoon() means hour(clock) >= 12 and hour(clock) < 18.
  Query evening() means hour(clock) >= 18 and hour(clock) < 23.
  Query dawn() means hour(clock) >= 5 and hour(clock) < 7.
  Query smallHours() means hour(clock) < 5.
  // The working day: shops open, the House receives, the basket runs.
  Query openHours() means hour(clock) >= 8 and hour(clock) < 19.
  // The Night of Lanterns: the fourth night, from dusk until midnight.
  Query lanternNight() means day(clock) == 4 and hour(clock) >= 19.
  // Cloudgate in the sky, where it has always been (state.kyr says what brings it down).
  Query aloft() means not cloudgateFell(sennet_bay).

  Chapter day_one "The Coast Road" when begun() and day(clock) == 1 "The bells of the House of Doors ring eight across the bay, and the gulls go up off the Quay all at once, and over all of it, over the cloud, a hill of houses catches the sun.".
  Chapter day_two "The Courts" when day(clock) == 2 and hour(clock) >= 6 "Sennet wakes to the winch-gang's horn at the foot of the Ascent and the smell of the glass-houses lighting their furnaces from the Fire Door.".
  Chapter day_three "The Letting-Down" when day(clock) == 3 and hour(clock) >= 6 "It is the day Cloudgate lets Perrin Halyard's coffin down off the Balustrade. All morning the Quay looks up.".
  Chapter day_four "Ascension Day" when day(clock) == 4 and hour(clock) >= 6 "Ascension Day. Cloudgate has hung out its bunting; you can see it from the Quay, very small, in the sun above the cloud. On the Quay the harbour is buying candles.".
  Chapter day_five "The Morning After" when day(clock) == 5 and hour(clock) >= 6 "The morning after the Lanterns. Paper lanterns that went up from Cloudgate last night are coming down all over Sennet, burnt out, on roofs and in gutters and on the water.".
  Chapter day_six "The Divers" when day(clock) == 6 and hour(clock) >= 6 "A grey morning, with the wind off the sea. The fishing boats stay in.".
  Chapter day_seven "The Keel" when day(clock) == 7 and hour(clock) >= 6 "The seventh day of the Tour since you came. In the Glass Market a man is selling a print of the Door of Doors, opened, with a Rector going through it in a halo.".

  // ── Breath under the water ────────────────────────────────────────────────────────────────────────────────────
  // What a company needs to go down the Fish Stairs: a kiss of the merfolk's, for three hours, or a brine-glass helm
  // while it is held (whelm.kyr).
  Entity breath: capability "Breath under water".
  // How long a kiss of the merfolk's lasts, on Sennet's own clock: the shared grantedUntil is left at 0 (held), and the
  // module ends the grant itself, because a module placed in a world reads its own watch and the shared rule the
  // world's (friction.md).
  Measure breathUntil(group).
  Rule breath_ends when granted(party, breath) and breathUntil(party) >= 1 and watch(clock) >= breathUntil(party) {
    Set breathUntil(party) to 0. }
  Rule breath_lost when granted(party, breath) and breathUntil(party) == 0 and not holding(party, brine_helm_kind) { Retract granted(party, breath). }

  // ── Where word reaches the company ────────────────────────────────────────────────────────────────────────────────
  // News of the city is heard anywhere in Sennet, in Cloudgate or on the coast road; not under the water, nor in the
  // planes.
  Query inSennet() means within(party, sennet_town) or within(party, cloudgate) or at(party, coast_road).
  Query inWhelm() means within(party, whelm).
  Query inPlanes() means within(party, fire_land) or within(party, earth_land) or within(party, air_land).
  // Whoever follows the company is carried with it by the basket, the cage and the stairs, as by the ways.
  Rule followers_keep_up when following(?x, party) and at(party, ?p) and not at(?x, ?p) { Assert at(?x, ?p). }
  // Whom the company has met, to be told of afterwards.
  Relation met(group).
  Rule meets when addressed(?p, party) and not met(?p) { Assert met(?p). }
  // A place the company has left and come back to is told shortly.
  Relation visitedNow(place). Relation visitedBefore(place).
  Rule arrives_at when at(party, ?p) and not visitedNow(?p) { Assert visitedNow(?p). }
  Rule leaves_from when visitedNow(?p) and not at(party, ?p) { Retract visitedNow(?p). Assert visitedBefore(?p). }
}

data/adventures/the-grand-tour/cloudgate:
Module sennet "The Grand Tour" {
  // ── Cloudgate ─────────────────────────────────────────────────────────────────────────────────────────────────────
  // The top of old Sennet, lifted two hundred years ago, above the cloud-line, where it is always a fine afternoon.
  // Its first family keeps the Air Door and a secret: what Ysabeau Halyard brought home through it, and set in the keel.
  Observe stage_scene at landing_stage when not visitedBefore(landing_stage) and aloft() and not dark() "Sun. That is the first thing: after the grey of the cloud, sun, warm and gold and steady, the light of a fine afternoon in a good summer, and a sky over everything so blue it looks lacquered. The Landing Stage is white stone with gilt railings. Below the railings, in every direction, the top of the cloud lies like a country of snow, and out of it, here and there, a gull comes up and looks surprised.".
  Observe stage_again at landing_stage when visitedBefore(landing_stage) and aloft() and not dark() "The Landing Stage, white and gilt, in the sun, with the cloud lying below the railings like snow.".
  Observe stage_night at landing_stage as weather when dark() and aloft() "Even at night it is not quite dark in Cloudgate. Above the cloud the stars are enormous, and the cloud below gives back a light of its own, like snow under a moon.".
  Observe promenade_scene at promenade when aloft() and not dark() "The Promenade runs round the rim of Cloudgate between the great houses and the edge: gravel raked into patterns, orange trees in tubs, benches with nobody on them, and people walking slowly in pale clothes under parasols, looking at the view, which is cloud. The houses of Cloudgate are the houses of old Sennet, very old, with their ground floors gone into the rock, so that the front doors are on the first floor and the steps go up to them out of the gravel. All the windows face outward.".
  Observe promenade_nurse at promenade when aloft() and not dark() and hour(clock) < 12 and not lanternNight() "A nursemaid from the Sennet side, in Halyard green, wheels a Cloudgate baby along the rim of the Promenade. She keeps to the inside of the path, against the house-fronts, and does not look at the view; and when the baby throws its rattle at the Balustrade she lets it lie.".
  Observe promenade_night at promenade when aloft() and dark() "The Promenade at night: the gravel grey under enormous stars, the orange trees black in their tubs, the great houses shuttered, and all round the rim the cloud lying pale below the Balustrade like a field of snow under a moon. Somebody in one of the houses is playing a piano, badly, with the window open.".
  Observe balustrade_scene at balustrade when aloft() "At the end of the Promenade the gravel stops at a stone balustrade, waist-high, with a broad flat rail you could sit on, and beyond it nothing at all: the cloud, a long way down, and the curve of the world. A wreath of white flowers has been tied to the rail, and is going brown. Nobody is standing near it.".
  Observe court_scene at wind_court when aloft() "The Wind Court is a round garden in the middle of Cloudgate, walled, with no plants in it but grass, and the grass all lying flat in one direction. In the wall on the far side is an arch of white stone, very old, with nothing in it but sky; and out of the sky in it comes a wind, steady, cold, smelling of snow, that never stops.".
  Observe chapel_ascension at ascension_chapel when true "The Ascension Chapel: small, gilt, full of the smell of lilies going over. Over the altar, in a painted window, a lady in green is lifting a hill on the palm of her hand, smiling, with a little city on it and a little sea underneath pouring into the hole.".
  Observe drawing_scene at drawing_room when aloft() "The drawing room of Halyard House runs the width of the house with windows all down the outer side, so that the cloud fills them like a white wall. Every chair is gilt. Down the inner wall, Halyards in oils look down their noses at the windows, beginning with a lady in green with a hill on her hand.".
  Observe aubrey_scene at aubrey_rooms when true "Aubrey Halyard's rooms: a sitting room that was handsome once, with the curtains drawn against the view and the furniture pushed back to the walls, and on every flat surface a bottle or a glass or a playing card, and a smell of brandy and cold ash.".
  Observe servants_scene at servants_hall when true "The servants' hall: stone-flagged, low, warm, with a long table and a range and a dresser of blue plates, and no windows at all. Nobody who works in Cloudgate, they say down below, ever gets to see the view.".
  Observe cellar_scene at wine_cellar when true "The wine cellar of Halyard House is cut into the rock of the hill: racks and racks of bottles in the lamplight, all their necks pointing the same way, and at the far end, where the racks stop, the bare rock, cold and sweating.".
  // Once it has come down it is a hill in the bay, wet to its first floors, in Sennet's weather.
  Observe stage_fallen at landing_stage when cloudgateFell(sennet_bay) "The Landing Stage is a step off a boat now: white stone, green to the knee with weed, with the sea slapping at the gilt railings and a fisherman's punt tied up where the basket used to come. Over it the sky is Sennet's, grey, with gulls in it.".
  Observe promenade_fallen at promenade when cloudgateFell(sennet_bay) "The Promenade is a beach. The gravel has gone down the rim into the sea in long grey fans, and the orange trees lie on their sides in their tubs at the tideline, and the people of Cloudgate are walking up and down it in their pale clothes, wet to the ankle, looking at the Quay a hundred yards off as if they had never seen it, which, from this side, they have not.".
  Observe balustrade_fallen at balustrade when cloudgateFell(sennet_bay) "The Balustrade stands where it stood, waist-high, with its broad flat rail; and beyond it, ten feet down, the grey water of the bay, and the Fish Stairs, and the harbour standing on the Quay looking back. The wreath has gone.".
  Observe court_fallen at wind_court when cloudgateFell(sennet_bay) "The Wind Court's grass stands up every which way, as grass does. Through the arch in the far wall there is still sky, and cold coming out of it; but nothing is lying flat any more.".
  Observe drawing_fallen at drawing_room when cloudgateFell(sennet_bay) "The windows of the drawing room are full of Sennet now: the Quay, the glass-houses, the washing on the lines of Lamp Street. Two of the portraits have come down off the inner wall, and nobody has put them up.".
  Observe keel_scene at keel when true "You come out of the bottom of the hill onto the underside of Cloudgate: rock, brown and wet and hanging, roots coming out of it like hair, and a ledge cut along it for a man to walk on, with an iron rail; and under the rail, a long way down through the cloud, nothing; and then, through a hole in the cloud, very small, the bay, and the Quay, and a boat on the water like a seed.".

  // ── The Dowager Lady Imogen Halyard ───────────────────────────────────────────────────────────────────────────────
  Person imogen "Lady Imogen Halyard" at ascension_chapel {
    Role "the Dowager of Cloudgate, in black, very upright" when not perrinUp(party).
    Role "the Dowager of Cloudgate, who has had her son back" when perrinUp(party).
    Ancestry human. Peaceable. Pronouns she. Manner proud.
    Greets "A tall woman in black lace looks at you down a very long nose, as if you were a long way below her, which, to be fair, all of Sennet is. 'You are a Tourist,' she says. 'I can always tell. You look at the view.' She does not offer her hand. 'I am Imogen Halyard. My son is dead. You will forgive me if I do not make conversation.'".
    Greets again "Lady Halyard inclines her head to you, exactly one inch.".
    Joins "Lady Halyard takes your arm, as if it were the most ordinary thing in the world, and does not let go of it.".
    Leaves "Lady Halyard lets go of your arm, and straightens her shawl, and is the Dowager of Cloudgate again.".
  }
  Relation imogenToldAlive(group). Relation imogenBelieves(group). Relation imogenMetMercy(group). Relation imogenShamed(group).
  Relation imogenSorry(group). Relation halyardLeave(group). Relation bribed(group). Relation bribeOffered(group). Relation secretToldImogen(group).
  Query mourning() means day(clock) <= 2.
  Rule imogen_vigil when mourning() and hour(clock) >= 8 and hour(clock) < 12 and not following(imogen, party) and not at(imogen, ascension_chapel) { Assert at(imogen, ascension_chapel). }
  Rule imogen_receives when hour(clock) >= 12 and hour(clock) < 23 and not funeralHour() and not lanternNight() and not following(imogen, party) and not at(imogen, drawing_room) { Assert at(imogen, drawing_room). }
  Rule imogen_morning when not mourning() and hour(clock) >= 8 and hour(clock) < 12 and not funeralHour() and not following(imogen, party) and not at(imogen, drawing_room) { Assert at(imogen, drawing_room). }
  Rule imogen_lanterns when lanternNight() and not following(imogen, party) and not at(imogen, promenade) { Assert at(imogen, promenade). }
  Rule imogen_night when (hour(clock) >= 23 or hour(clock) < 8) and not following(imogen, party) and not at(imogen, offstage) { Assert at(imogen, offstage). }
  Topic imogen_perrin with imogen "Ask Lady Halyard about her son" when true once {
    Says "'Perrin.' She says it as if it were a word in a language she has stopped speaking. 'He wanted to be a Doorward. A Halyard, keeping other people's doors, for a salary, on the headland. I said it was beneath him. He said everything was beneath us, Mother, that was rather the point.' Her mouth moves, very slightly. 'He was the clever one. Aubrey is the eldest.' She looks at the window, at the white wall of cloud. 'The sea does not give back what goes off this rock. We are letting down an empty box on the third day, because one must let down something.'".
    On discuss { Assert knows(actor, imogen_grief). }
  }
  Discovery imogen_grief "Lady Halyard thought Perrin's wish to be a Doorward beneath the family; he told her everything was beneath them, that was rather the point. She is letting down an empty coffin because one must let down something.".
  Topic imogen_lifting with imogen "Ask Lady Halyard about the Lifting" when true once {
    Says "'My husband's grandmother, six times back, lifted this hill on the palm of her hand. I married it.' She does not look at the portrait; she does not need to. 'Ysabeau Halyard. She went through the Air Door a girl and came back a woman, with the means to raise her family above the damp and the smells and the sea, and she used them. That is what one does with means.' She folds her hands. 'Down there they call it something else. They would.'".
    On discuss { Assert knows(actor, imogen_lifting). }
  }
  Discovery imogen_lifting "Lady Halyard says Ysabeau Halyard went through the Air Door a girl and came back with the means to lift her family above the sea, and used them, as one does with means.".
  Topic imogen_ysabeau with imogen "Ask Lady Halyard about the lady in green with the hill on her hand" when knows(actor, imogen_lifting) once {
    Says "'They say she loved a wind.' Lady Halyard says it with great distaste, as if repeating something said by a servant. 'A prince of the Air. Family nonsense. She kept a box of letters to him that she never sent, it's in the escritoire there with the deeds, nobody has opened it in a hundred years.' She looks at the portrait at last. 'She married her cousin the year after the Lifting, so as not to change her name, and had nine children, and died at ninety in that chair. If she loved a wind, she got over it.'".
    On discuss { Assert knows(actor, ysabeau_letters). }
  }
  Discovery ysabeau_letters "Ysabeau Halyard, who lifted Cloudgate, is said to have loved a prince of the Air. A box of her letters to him that she never sent is in the escritoire in the drawing room of Halyard House, with the deeds.".
  Kind ysabeau_letter_kind "Ysabeau Halyard's last letter" is gear worth 0 weighing 0 described "A letter folded small and gone the colour of tea, addressed on the outside, in a girl's hand, To the North Wind, and never sent. Inside, two lines: I did a terrible thing with what you gave me, and I have been sorry every day of my life, and I have never once stopped loving you. Do not forgive me. Remember me. Y.".
  Item ysabeau_letter "Ysabeau's letter" is ysabeau_letter_kind in escritoire owned by imogen.
  Thing escritoire "the escritoire" at drawing_room {
    Holds.
    State locked closed "An escritoire of black lacquer stands under the portrait of the lady in green, locked.".
    State open "The escritoire under the portrait stands open, full of deeds and a box of letters tied with green ribbon.".
  }
  Initially Assert keyholder(imogen, escritoire).
  // Picked only with nobody by: the footman keeps the drawing room by day, the Dowager receives in it till eleven.
  Action pick_escritoire(actor: group, site: place) "Pick the lock of the escritoire, while the drawing room is empty" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, drawing_room) and state(escritoire, locked)
      and capable(actor, lockwork) and not at(jem, drawing_room) and not at(imogen, drawing_room).
    Time 2.
    Resolve check(actor, lockwork, dc_fair).
    On success { Retract state(escritoire, locked). Assert state(escritoire, open). Assert escritoirePicked(actor). }
    Result "The drawing room is dark but for the cloud in the windows, which gives back a light of its own. The lock is old and good and French, and takes you a quarter of an hour, with the Halyards in oils watching you down their noses the whole time; and then the lid comes down into your hands without a sound.".
    Otherwise "The lock is old and good and French, and it beats you. Somewhere in the house a clock strikes the quarter, and then the half, and you leave it.".
  }
  Relation escritoirePicked(group).
  // Moved, the Dowager gives the letter herself (door.kyr has the North Wind's answer).
  Topic imogen_letter with imogen "Ask Lady Halyard for Ysabeau's last letter, to take to the North Wind" when knows(actor, ysabeau_letters) and imogenSorry(imogen) and not carries(actor, ysabeau_letter) once {
    Says "She unlocks the escritoire herself, and takes out the box, and unties the green ribbon, and finds the last letter without looking, as if she had always known which it was. She reads it standing. Then she gives it to you. 'Take it to him,' she says. 'Tell him a Halyard sent it. Tell him we are sorry.' She holds on to it a moment longer than she needs to. 'Tell him she meant it.'".
    On discuss { Assert lends(imogen, ysabeau_letter, actor). Give ysabeau_letter to actor. }
  }
  // Leave to use the Air Door, after the mourning, to an entered Tourist; or Aubrey takes the company through.
  Topic imogen_leave with imogen "Ask Lady Halyard for leave to go through the Air Door" when enrolled(actor) and not halyardLeave(actor) once {
    Says "'The Wind Court is closed while my son lies in the chapel.' She does not raise her voice. 'After he is let down, on the third day, a Tourist of the Grand Tour may have the Halyards' leave, since the Rector has asked it of us, and one does not refuse the House.' She looks at you without any warmth at all. 'Afterwards. Not before.'".
    On discuss { Assert knows(actor, leave_after). }
  }
  Discovery leave_after "Lady Halyard will give a Tourist of the Grand Tour leave to use the Air Door, but not while Perrin lies in the chapel: only after he is let down on the third day.".
  Topic imogen_leave_given with imogen "Ask Lady Halyard again for leave to go through the Air Door, now that her son is let down" when knows(actor, leave_after) and enrolled(actor) and not mourning() and not halyardLeave(actor) once {
    Says "She takes a card from the escritoire, and writes on it, and gives it you without a word. It says, in a small hard hand: THE HALYARDS' LEAVE. I.H.".
    On discuss { Assert halyardLeave(actor). }
  }

  // ── Aubrey Halyard ────────────────────────────────────────────────────────────────────────────────────────────────
  // The heir. Quarrelled with his brother ten minutes before the fall, and cannot remember the end of the night, and
  // has come to believe he did it.
  Person aubrey "Aubrey Halyard" at aubrey_rooms {
    Role "the Halyards' heir, unshaven, in last night's shirt" when not perrinUp(party) and not aubreyFreed(aubrey).
    Role "the Halyards' heir, who has had his brother back" when aubreyFreed(aubrey).
    Ancestry human. Calling warrior. Trait brave. Level 3. Peaceable. Pronouns he. Manner grim.
    Wants brother_letter_kind.
    Greets "A man of thirty in a shirt he has slept in is lying on a sofa with his boots on the silk and a bottle on his chest, and does not get up. 'Another Tourist,' he says, to the ceiling. 'Mother sends them in to be cheered up by. Go away and look at the view.'".
    Greets again "Aubrey Halyard lifts the bottle to you without lifting his head.".
    Joins "Aubrey Halyard puts the bottle down, and looks at it, and leaves it. 'All right,' he says. 'Where.'".
    Leaves "Aubrey Halyard goes back the way you came, walking carefully, like a man on a deck.".
  }
  Entity aubrey_guilt: claim "Aubrey Halyard pushed his brother off the Balustrade".
  Initially Assert believes(aubrey, aubrey_guilt). Initially Set conviction(aubrey, aubrey_guilt) to 2.
  Relation aubreyTalked(group). Relation aubreyFreed(group). Relation aubreyFriend(group). Relation drankWith(group).
  Rule aubrey_rooms_day when hour(clock) >= 8 and hour(clock) < 19 and not funeralHour() and not aubreyTaken(aubrey) and not following(aubrey, party) and not at(aubrey, aubrey_rooms) { Assert at(aubrey, aubrey_rooms). }
  Rule aubrey_promenade when hour(clock) >= 19 and hour(clock) < 24 and not aubreyTaken(aubrey) and not following(aubrey, party) and not at(aubrey, promenade) { Assert at(aubrey, promenade). }
  Rule aubrey_night when hour(clock) < 8 and not aubreyTaken(aubrey) and not following(aubrey, party) and not at(aubrey, offstage) { Assert at(aubrey, offstage). }
  Action drink_aubrey(actor: group, site: place) "Sit down and drink with Aubrey Halyard" {
    Requires able(actor) and company(actor) and at(actor, site) and at(aubrey, site) and not drankWith(actor).
    Time 6.
    On success { Assert drankWith(actor). }
    Result "You sit on the floor, since he is on the sofa, and he passes you the bottle without looking, and for an hour you drink his family's brandy, which is very good, and he talks about nothing: horses, a girl in Sennet who married a ship's chandler, the view, which he hates. Toward the end of the bottle he stops talking, and looks at the ceiling, and you understand that if you ask him now, he will tell you.".
  }
  Topic aubrey_night_asked with aubrey "Ask Aubrey Halyard what happened on the night his brother fell" when drankWith(actor) and not aubreyTalked(aubrey) once {
    Says "He doesn't answer. He turns the bottle until its label faces him, as if it might help. 'We quarrelled. On the Promenade. Perrin had found something out, family business, and he was going to give it away. Give it away, to strangers, to the wind.' He laughs. 'I said if he wanted to go down so badly he could jump. I said that.' He puts the bottle down on the floor, carefully. 'He went off to the Balustrade. I went after him. I was going to say I was sorry. And then I don't remember. The fog came up. I remember the rail under my hands, wet. And then bells, and people shouting, and I was sitting on the gravel.' He looks at his hands. 'I think I put my hands on him. I think I did. I'd had a great deal to drink and I was angry, and he was my brother, and I think I put my hands on him.'".
    On discuss { Assert aubreyTalked(aubrey). Assert knows(actor, aubrey_quarrel). }
  }
  Discovery aubrey_quarrel "On the night Perrin fell, he and Aubrey quarrelled on the Promenade: Perrin had found out family business and meant to give it away, and Aubrey told him to jump. Aubrey followed him to the Balustrade to say sorry, and remembers nothing after the fog came up but the wet rail under his hands; he believes he pushed his brother.".
  Topic aubrey_keel with aubrey "Ask Aubrey Halyard what family business his brother found out" when aubreyTalked(aubrey) and aubreyFriend(aubrey) and not knows(actor, keel_ladder_known) once {
    Says "'You'd better see it.' He gets up, steadier than you expected. 'When we were boys we used to climb down the keel ladder, Perrin and I, at the back of the wine cellar, and spit at the clouds. Nobody goes down there. Mother doesn't know it's there.' He finds a key on his watch-chain and gives it you. 'The cellar stair. Go down, and go to the end of the racks, and feel along the rock on the left. There's a ladder. Go down it, and along the ledge, and look at what's set in the rock.' He sits down again. 'That's what he found. That's what he was going to give away.'".
    On discuss { Assert knows(actor, keel_ladder_known). Assert keyholder(party, cellar_lock). }
  }
  // Freed of it by his brother: a letter in Perrin's hand, or Perrin himself (whelm.kyr, fall.kyr).
  Relation letterToAubrey(group).
  Kind brother_letter_kind "Perrin's letter to his brother" is gear worth 0 weighing 0 described "A letter written in pencil on a page out of a drowned book, the paper still damp, in a quick clever hand: Aubrey, you great fool. It wasn't you. You were sitting on the gravel being sick when I went over, I could hear you. I'm alive, I've broken my leg, I'm happier than I've ever been, and I'm not coming up. Stop drinking Father's brandy. P.".
  Item brother_letter "Perrin's letter to Aubrey" is brother_letter_kind at offstage.
  Event aubrey_reads near aubrey when keeps(aubrey, brother_letter) and not aubreyFreed(aubrey) "Aubrey Halyard reads the letter standing up. He reads it again. Then he sits down on the floor, all at once, as if his strings had been cut, and puts his face in his hands, and his shoulders shake, and it is some time before you understand that he is laughing. 'Father's brandy,' he says, through his fingers. 'Father's brandy. The little swine.' He looks up at you with his face wet. 'He's alive. He's alive and he's not coming up.' And then, a good deal later: 'Where is he? Can you take me? Can I see him?'" then {
    Assert aubreyFreed(aubrey). Set conviction(aubrey, aubrey_guilt) to 0. Assert aubreyFriend(aubrey). }
  Topic aubrey_alive_told with aubrey "Tell Aubrey Halyard that his brother is alive" when knows(actor, perrin_alive) and not aubreyFreed(aubrey) and not carries(actor, brother_letter) once {
    Says "He looks at you with something close to hatred. 'Don't.' He gets up off the sofa. 'Don't, do you hear. Every Tourist in Cloudgate has a story about the bay. He's dead. I killed him.' He opens the door for you. 'Bring me something in his hand,' he says, 'or don't come back.'".
  }
  Rule aubrey_befriended when aubreyTalked(aubrey) and drankWith(party) and talked_twice(party) and not aubreyFriend(aubrey) { Assert aubreyFriend(aubrey). }
  Relation talked_twice(group).
  Topic aubrey_not_you with aubrey "Tell Aubrey Halyard that a man who meant to say sorry is not a man who pushes his brother" when aubreyTalked(aubrey) and not aubreyFreed(aubrey) and not talked_twice(actor) once {
    Says "He looks at you, and then at his hands, which have been the problem for twelve days. 'You don't know that.' But he picks up the bottle, and looks at it, and puts it down without drinking. 'Nobody's said that. Mother says nothing. The whole of Cloudgate looks at me the way you look at a hole in the road.' He rubs his face. 'Sit down, then. If you're staying.'".
    On discuss { Assert talked_twice(actor). }
  }
  // Aubrey brought down to the Fish Stairs at night to see his brother (whelm.kyr), or Perrin brought up.
  Topic aubrey_comes with aubrey "Ask Aubrey Halyard to come down with you to the Fish Stairs, to his brother" when aubreyFreed(aubrey) and not perrinDead(party) and not travelsWith(aubrey, party) and not brothersMet(party) once {
    Says "He is putting on his coat before you have finished. 'Let me shave,' he says, and then: 'No. He'd only laugh.'".
    On discuss { Assert following(aubrey, party). }
  }
  Relation brothersMet(group).

  // ── Jem Tuttle, footman ───────────────────────────────────────────────────────────────────────────────────────────
  // Brought up from Sennet at fourteen, never let down again (the Dowager does not let her servants go down: they do
  // not come back), and terrified of the edge every day of his life. On the night of the fall he was sent to the
  // Balustrade with a shawl.
  Person jem "Jem Tuttle" at drawing_room {
    Role "a footman of Halyard House in a green coat, who keeps away from the windows" when not jemFree(jem).
    Role "a potman, lately a footman, who has come down to earth" when jemFree(jem).
    Ancestry human. Peaceable. Pronouns he. Manner compassionate.
    State at_door blocking "Jem Tuttle keeps the door of Halyard House, and nobody comes in by it without his say.".
    Guards halyard_door.
    Greets "A young footman in a green coat bows to you, from as far from the windows as the room allows. 'Halyard House. Her Ladyship receives in the afternoon. Have you a card?'".
    Greets again "The footman bows, from the far side of the room from the windows.".
  }
  Relation jemFree(group). Relation jemWants(group). Relation jemPlace(group).
  Rule jem_door when hour(clock) >= 8 and hour(clock) < 18 and not jemFree(jem) and not at(jem, drawing_room) { Assert at(jem, drawing_room). }
  Rule jem_hall when (hour(clock) >= 18 or hour(clock) < 8) and hour(clock) >= 5 and not jemFree(jem) and not at(jem, servants_hall) { Assert at(jem, servants_hall). }
  Rule jem_sleeps when hour(clock) < 5 and not jemFree(jem) and not at(jem, offstage) { Assert at(jem, offstage). }
  Rule jem_potman when jemFree(jem) and hour(clock) >= 10 and hour(clock) < 23 and not at(jem, taproom) { Assert at(jem, taproom). }
  Rule jem_bed_below when jemFree(jem) and (hour(clock) >= 23 or hour(clock) < 10) and not at(jem, offstage) { Assert at(jem, offstage). }
  // Let in: as gentlefolk, as an entered Tourist with the Rector's card, or with the heir.
  Rule jem_admits when (craft(party, craft_court) or holding(party, tour_licence_kind) or travelsWith(aubrey, party) or following(aubrey, party)) and not tolerates(jem, party) { Assert tolerates(jem, party). }
  Topic jem_edge with jem "Ask the footman why he keeps away from the windows" when true once {
    Says "He goes red. 'Heights, sir. Madam.' He swallows. 'I come up at fourteen from Fish Street. Her Ladyship took me on for my legs. I've not been down since. She doesn't let us down, the servants: they don't come back, she says.' He looks at the window, and away. 'Eleven years I've been up here, and every morning I wake up and think about the edge. There's nothing on the other side of those windows, and everyone up here walks about as if there was.' He straightens his coat. 'I'd go down tomorrow if I'd a place to go to. I'd go down on my hands and knees.'".
    On discuss { Assert jemWants(jem). Assert knows(actor, jem_wish). }
  }
  Discovery jem_wish "Jem Tuttle, the Halyards' footman, came up from Fish Street at fourteen, is terrified of heights, and has not been let down in eleven years; he would go down tomorrow if he had a place below to go to.".
  Topic peg_potman with peg "Ask Peg Arklow whether the Sounding Line could use a potman, a Fish Street lad, honest" when knows(actor, jem_wish) and not jemPlace(jem) once {
    Says "'A potman.' Peg considers you, and the window, and the hill in it. 'One of theirs? A footman?' She snorts. 'Can he carry six pints without spilling and be civil to fishermen?' You say that he has carried trays through Halyard House for eleven years without falling off the edge of the world. She laughs. 'Send him down. If he's Fish Street, I knew his mother.'".
    On discuss { Assert jemPlace(jem). }
  }
  Topic prue_hand with prue "Ask Prue Quickly whether she could use a hand at the furnace, a Fish Street lad" when knows(actor, jem_wish) and not jemPlace(jem) and not furnaceCold(glasshouse) once {
    Says "'Can he stand heat?' You say he has stood Cloudgate for eleven years. 'That's cold,' says Prue. 'Cold's worse.' She shrugs. 'Send him down. I'll have his eyebrows off in a week.'".
    On discuss { Assert jemPlace(jem). }
  }
  Topic jem_told_place with jem "Tell the footman there is a place for him below" when jemPlace(jem) and not jemFree(jem) once {
    Says "He stares at you. Then, very slowly, he takes off his green coat, and folds it, and lays it on a gilt chair, and puts his white gloves on top of it. 'I'll go down on the four o'clock,' he says, 'with my eyes shut.' He looks round the drawing room, at all of it, and at the white windows. Then he looks at you, and lowers his voice. 'There's a thing I never told. Who would I have told?' He wets his lips. 'The night Master Perrin went over. I was sent to the Balustrade at ten with a shawl for her Ladyship, in the fog. And there was someone at the rail, just where he— Not her Ladyship. A woman, in a long gown, with sleeves like a bishop's, hanging down, and something on a chain that rang. And then there wasn't anyone. And I ran.' He picks up his gloves again, and puts them down. 'I thought I'd seen a ghost. I'm a Fish Street lad. We see the drowned.'".
    On discuss { Assert jemFree(jem). Assert knows(actor, bishop_sleeves). }
  }
  Discovery bishop_sleeves "Jem Tuttle, the Halyards' footman, was at the Balustrade at ten on the night Perrin fell, and in the fog saw a woman at the rail, not the Dowager, in a long gown with sleeves like a bishop's, hanging down, and something on a chain that rang; and then nobody.".
  // A frightened man can be frightened into it, and ruined by it.
  Action scare_jem(actor: group, site: place) "Take the footman by his collar and make him tell you what he saw on the night of the fall" {
    Speaker jem.
    Requires able(actor) and company(actor) and at(actor, site) and at(jem, site) and heardFall() and not jemFree(jem) and not knows(actor, bishop_sleeves) and not scared(jem).
    Time 1 minute.
    Resolve check(actor, intimidation, dc_fair).
    On success { Assert scared(jem). Assert knows(actor, bishop_sleeves). }
    On failure { Assert scared(jem). }
    Result "He tells you in a whisper with his eyes on the window: a woman at the rail in the fog, at ten, in a long gown with sleeves like a bishop's, and something on a chain that rang, and then nobody. Then he goes to Her Ladyship's steward, white, and gives notice, and is not let down: he is sent to the kitchens, where nobody will see him again.".
    Otherwise "He goes white and says nothing at all, and the steward comes in to see what the noise is.".
  }
  Relation scared(group).

  // ── The cellar ────────────────────────────────────────────────────────────────────────────────────────────────────
  Thing cellar_lock "the cellar door" on cellar_stair {
    State locked blocking "The cellar door at the top of the stair is locked.".
    State open "The cellar door stands open.".
    Change pick "Pick the lock of the cellar door" from locked to open needing lockwork.
  }
  Initially Assert keyholder(imogen, cellar_lock).
  Discovery keel_ladder_searched "Behind the last rack of the wine cellar, in the rock, iron rungs go down into the dark.".
  Rule ladder_found_searching when knows(party, keel_ladder_searched) and not knows(party, keel_ladder_known) says "Behind the last rack of the wine cellar, in the rock, iron rungs go down." teaches keel_ladder_known { }
  Observe cellar_rungs at wine_cellar when knows(party, keel_ladder_known) "At the end of the racks, on the left, iron rungs are let into the bare rock, going down into the dark, wet, cold, with a wind coming up them.".

  // ── The letting-down ──────────────────────────────────────────────────────────────────────────────────────────────
  // At noon on the third day the empty coffin goes off the Balustrade on ropes into the cloud, and is let go.
  Query funeralHour() means day(clock) == 3 and hour(clock) >= 11 and hour(clock) < 13.
  Thing coffin "Perrin Halyard's coffin" at ascension_chapel {
    State lying "A coffin of white wood with silver handles lies on trestles before the altar, under a pall embroidered with a hill on a hand. There is a great deal of white lilies.".
    State gone "The trestles before the altar are bare.".
  }
  Rule mourners_gather when funeralHour() and not at(imogen, balustrade) { Assert at(imogen, balustrade). }
  Rule aubrey_mourns when funeralHour() and not aubreyTaken(aubrey) and not at(aubrey, balustrade) { Assert at(aubrey, balustrade). }
  Rule rector_mourns when funeralHour() and rectorFree() and not at(quance, balustrade) { Assert at(quance, balustrade). Assert rectorAbout(quance). }
  Rule mourners_part when day(clock) == 3 and hour(clock) >= 13 and rectorAbout(quance) { Retract rectorAbout(quance). }
  Occasion letting_down "the letting-down of Perrin Halyard" at balustrade when day(clock) == 3 and hour(clock) >= 12 and not rectorTaken(quance) {
    Matter eulogy "Six Halyard footmen carry the white coffin out of the Ascension Chapel to the Balustrade and set it on the rail, and the Rector of the House of Doors steps forward in her gown of four colours, and speaks without notes, in a voice that carries without being raised: of a boy who could read Aenean like a menu and was kind, which they never are at that age; of a Doorward who believed that every door is a promise to someone on the other side of it; of the bay, which does not give back what it is given. Half the Promenade is crying. The Dowager stands like a post. Aubrey Halyard, at the back, holds on to an orange tree." for 30 minutes.
    Matter lowering "The footmen take the ropes. The coffin goes over the rail and down the face of the rock into the cloud, slowly, the ropes creaking, until the cloud has it." for 20 minutes.
    Matter let_go "At a sign from the Dowager the footmen let go the ropes, all at once, and they snake over the rail after it, and are gone." for 10 minutes.
    Closes "Cloudgate stands at the Balustrade a while longer, looking at the cloud, and then goes in to lunch.".
  }
  // With the Rector in the Watch-house, the House sends its chaplain, who did not know the boy, and says so.
  Occasion letting_down_plain "the letting-down of Perrin Halyard" at balustrade when day(clock) == 3 and hour(clock) >= 12 and rectorTaken(quance) {
    Matter eulogy_amis "Six Halyard footmen carry the white coffin out of the Ascension Chapel to the Balustrade and set it on the rail. The House of Doors has sent its chaplain, Brother Amis, since its Rector is in the Watch-house on Fish Street, and the whole of Cloudgate knows why. He says that he did not know the young man, and that Veyra asks us to remember the absent traveller, and to promise him a path home; and then, looking at the white box, that he will not say anything else, since it seems to him that this one may find his own." for 30 minutes.
    Matter lowering_plain "The footmen take the ropes. The coffin goes over the rail and down the face of the rock into the cloud, slowly, the ropes creaking, until the cloud has it." for 20 minutes.
    Matter let_go_plain "At a sign from the Dowager the footmen let go the ropes, all at once, and they snake over the rail after it, and are gone." for 10 minutes.
    Closes "Cloudgate stands at the Balustrade a while longer, looking at the cloud, and then goes in to lunch.".
  }
  Observe eulogy_hands at balustrade when matterOpen(eulogy) and capable(party, insight) "The Rector's voice does not shake once. But all the time she speaks she holds the rail of the Balustrade with her left hand, and the knuckles of it are white as the rail.".
  Rule coffin_gone when (matterDone(let_go) or matterDone(let_go_plain)) and state(coffin, lying) { Assert state(coffin, gone). }

  // Aubrey at his brother's letting-down: what he believes, out loud, or the rope in his own hands.
  Observe funeral_aubrey at balustrade when matterOpen(lowering) and not aubreyFreed(aubrey) and not aubreyTaken(aubrey) "As the footmen take the ropes Aubrey Halyard says, quite loudly, to nobody, 'I did it, you know. Ask anyone.' Nobody looks at him. His mother does not turn her head. The Rector, beside her, puts a hand on his arm, very kindly, and he lets it stay there.".
  Observe funeral_aubrey_freed at balustrade when matterOpen(lowering) and aubreyFreed(aubrey) "Aubrey Halyard has taken one of the ropes from a footman and is letting the empty box down himself, hand under hand, with his face perfectly straight, and every so often a sound comes out of him that Cloudgate takes for grief.".
}

data/adventures/the-grand-tour/collegium:
Module sennet "The Grand Tour" {
  // ── The House of Doors ────────────────────────────────────────────────────────────────────────────────────────────
  // The Collegium of Veyra, on the headland: the Hall of Doors with the Fire and the Earth doors in it (the Air door is
  // in Cloudgate, the Water door in the Whelm); the Museum of the Tour, two centuries of things brought home; Veyra's
  // chapel; the Rector's study; and up the tower stair, the Nexus, where the Door of Doors has stood shut since the
  // Rose was broken. The Rector, Magistra Isadora Quance, has proclaimed the Grand Tour, and receives every Tourist
  // herself.
  Observe gate_scene at college_gate when true "The House of Doors stands on the headland over the bay, a long grey building with a short grey tower, much less grand than you expected, with lichen on it and students sitting on the wall eating pies. Over the gate, in old letters, a line cut deep: EVERY DOOR IS A PROMISE TO SOMEONE ON THE OTHER SIDE OF IT.".
  Observe quad_scene at quad when true "The Quad: grass worn to earth along the paths, four doors in four walls, and students crossing it in gowns of four colours, red, brown, blue and white, arguing. A board by the Hall's doors says THE GRAND TOUR: TOURISTS TO THE RECTOR'S DOOR, and somebody has added in chalk, AND GOD HELP YOU.".
  Observe hall_scene at hall_of_doors when true "The Hall of Doors: long, dim, cold, with a floor of black and white stone worn into dips, and at the far end two doors side by side in the wall. One is iron, red-hot along its edges, and the air in front of it shakes. The other is a slab of granite on hinges as thick as your leg, with moss growing on it, and a draught coming under it that smells of cellars. Between them a little man sits at a desk with a ledger.".
  Observe museum_scene at museum when true "The Museum of the Tour: a long gallery of glass cabinets, two hundred years of things brought home. A stuffed salamander, still smoking very slightly. A sylph's feather under a bell jar, standing on its tip. A merfolk crown of shells labelled PRESENTED. A bowl of stones from the Plane of Earth, each labelled with the name of the Tourist who picked it up, in a larger hand than the name of the stone.".
  Observe cabinet14 at museum when not emberFreed(museum) "In Cabinet Fourteen, on black velvet, under glass, a coal the size of a hen's egg is burning. It has burnt since the year it was brought home; the label says so: AN EMBER OF THE HOUR COURT. BROUGHT HOME BY THE HON. THOS. MOTTRAM, 1210. When you lean close it brightens, and when you speak it gives off a little flurry of sparks against the glass, as if it were trying to say something back.".
  Observe chapel_scene at chapel when true "Veyra's chapel: small, whitewashed, with a single lamp, and a table instead of an altar, laid for one, with a cup and a plate and a candle, the way you lay a place for somebody who has not come home yet. On the wall, in the same old letters as over the gate: SHARE FOOD. REMEMBER THE ABSENT. PROMISE A PATH HOME.".
  Observe study_scene at rector_study when true "The Rector's study: books to the ceiling and on the floor and on the chairs, a desk the size of a boat, and on the desk among the books a case of black wood lined with velvet with four empty hollows in it, each the shape of a petal. Through the window, the bay, and Cloudgate.".
  Observe tower_scene at tower_stair when true "The tower stair goes up in a tight stone spiral to a door at the top: oak, iron-bound, with a lock the size of a book. Somebody, long ago, has cut a cat-flap in the bottom of it.".
  Observe nexus_scene at nexus when true "The Nexus is a round room at the top of the tower with no windows and no furniture. In the middle of it a door stands by itself in a frame, with nothing behind it: you can walk round it. On this side it is a plain door of pale wood with a round boss in the middle, carved into a rose of four petals, and four hollows in the rose where petals should be. On the far side, when you walk round, it is the same door. A cat's dish stands by it, empty.".

  // ── Magistra Isadora Quance, Rector ───────────────────────────────────────────────────────────────────────────────
  // Brilliant, generous, vain and very funny, and a murderer. Perrin Halyard, her best student, found what is in the
  // keel of Cloudgate (the Air petal, stolen; door.kyr) and told her, and told her he would tell the Plane of Air so
  // that it could have it back; that would have put the fourth petal where no Rector could reach it. She followed him
  // to the Balustrade in the fog. She has proclaimed the Tour so that others will bring her the three petals that
  // the courts still keep, and means to take the fourth herself.
  Person quance "Magistra Isadora Quance" at rector_study {
    Role "the Rector of the House of Doors, in a gown of four colours and a chain of keys" when not rectorExposed(quance).
    Role "the Rector of the House of Doors, found out" when rectorExposed(quance).
    Ancestry human. Calling mage. Trait enchanter. Level 9. Peaceable. Pronouns she. Manner jovial.
    Wants fire_petal_kind. Wants earth_petal_kind. Wants water_petal_kind. Wants air_petal_kind. Wants perrin_notebook_kind.
    Greets "A tall woman of sixty in a gown sewn in four colours gets up from behind a desk the size of a boat, scattering books, and comes round it with both hands out. On her chain of office a ring of old keys clinks. 'A Tourist! A real one, from over the hill. Do sit. Throw those on the floor, they've been there for years.' She looks at you with enormous interest, as if you were the only interesting thing to have happened to her all week. 'Isadora Quance. I run this place, or it runs me. You've come about the Grand Tour. Everybody has. Most of them are idiots. Are you?'".
    Greets again "'You!' says the Rector, delighted, and clinks, and then stops with her hand on the ring of old keys as if she had remembered something she would rather have dropped. 'Tolley has been taking down my memoirs all morning, and I have just discovered that I do not remember the Tour at all. Only the proclamation. Sit and tell me what it was like.'".
  }
  // Ascension Eve, six to seven: an hour on Old Bethan's crate (courant.kyr).
  Query isaEve() means day(clock) == 3 and hour(clock) == 18 and not cloudgateFell(sennet_bay).
  Query rectorFree() means not rectorExposed(quance) and not rectorTaken(quance) and not rectorThrough(quance) and not rectorFled(quance) and not dead(quance).
  Relation rectorAbout(group). Relation rectorAway(group).
  Rule quance_study when hour(clock) >= 9 and hour(clock) < 17 and rectorFree() and not rectorAbout(quance) and not rectorAway(quance) and not at(quance, rector_study) { Assert at(quance, rector_study). }
  Rule quance_eve when isaEve() and rectorFree() and not rectorAbout(quance) and not rectorAway(quance) and not at(quance, quay) { Assert at(quance, quay). }
  Rule quance_hall when hour(clock) >= 17 and hour(clock) < 19 and not isaEve() and rectorFree() and not rectorAbout(quance) and not rectorAway(quance) and not at(quance, hall_of_doors) { Assert at(quance, hall_of_doors). }
  Rule quance_writes when hour(clock) >= 19 and hour(clock) < 23 and not lanternNight() and rectorFree() and not rectorAbout(quance) and not rectorAway(quance) and not at(quance, rector_study) { Assert at(quance, rector_study). }
  Rule quance_bed when (hour(clock) >= 23 or hour(clock) < 9) and rectorFree() and not rectorAbout(quance) and not rectorAway(quance) and not at(quance, offstage) { Assert at(quance, offstage). }
  Rule quance_lanterns when lanternNight() and rectorFree() and not rectorAbout(quance) and not rectorAway(quance) and not at(quance, promenade) { Assert at(quance, promenade). }

  Topic quance_rose with quance "Ask the Rector about the Rose of the Winds" when true once {
    Says "'The key of the Door of Doors.' She picks up a book, looks at it, and drops it. 'Broken in four and given to the four courts of the planes, the Fire, the Earth, the Water and the Air, so that nobody could ever open the Door alone. Very sensible. Very dull.' She lights a cigarillo off a candle. 'The Door opens on anywhere, you know. Anywhere at all. You think of a place and there it is, on the other side. Nobody has been through it since the last Rector but two.' She blows smoke at the ceiling. 'The courts still have their petals. They have to be asked for them, each in its own fashion, which is the Tour. Bring me all four and you'll be first through. That's the prize.' She smiles. 'And I'll be second. That's mine.'".
    On discuss { Assert knows(actor, rose_known). }
  }
  Discovery rose_known "The Rose of the Winds is the key of the Door of Doors, broken into four petals, each given to one of the four courts of the elemental planes to keep, so that nobody could open the Door alone. Whoever brings the Rector all four will be first through the Door of Doors, which opens on anywhere.".
  Topic quance_perrin with quance "Ask the Rector about Perrin Halyard" when heardFall() once {
    Says "For a moment the Rector does not say anything. She puts down the cigarillo. 'My best,' she says. 'The best student I have had in thirty years. He could read Aenean like a menu, and he was kind, which they never are at that age.' She looks out of the window at Cloudgate. 'He'd been drinking. He and his brother. They always fought. He went to the Balustrade to cool off, and the fog came up.' She picks the cigarillo up again; her hand is perfectly steady. 'I gave the eulogy at the lying-in-state. I'll give it again on the third day, when they let him down. I would give the whole Tour to have him back.' She smiles at you, a little crookedly. 'Don't tell anyone I said that. It's very bad for discipline.'".
    On discuss { Assert knows(actor, rector_on_perrin). }
  }
  Discovery rector_on_perrin "The Rector says Perrin Halyard was the best student she had in thirty years, that he and his brother had been drinking and fighting, and that he went to the Balustrade to cool off and the fog came up. She says she would give the whole Tour to have him back.".
  // Entering the Tour: ten coin; or a favour for her; or as second bear-leader to a Mottram (rivals.kyr).
  Kind tour_licence_kind "a Tourist's licence of the Grand Tour" is gear worth 0 weighing 0 described "A card the size of your hand, printed in four colours, with the Rector's signature across it in violet ink the size of a fist: THE BEARER IS ENTERED FOR THE GRAND TOUR AND IS TO BE GIVEN EVERY CIVILITY THROUGH THE DOORS OF THE HOUSE. On the back, smaller: THE HOUSE ACCEPTS NO RESPONSIBILITY.".
  Item licence "a Tourist's licence" is tour_licence_kind at offstage.
  Topic quance_enter with quance "Ask the Rector to enter you for the Grand Tour" when not enrolled(actor) once {
    Says "'Of course.' She is already writing on a card in violet ink. 'The fee's ten coin, I'm afraid. The Bursar insists. It keeps out the riff-raff and lets in the rich, which is the opposite of what one wants, but there.' She looks up at you over the pen. 'Unless.' She taps her teeth with it. 'There is a thing you could do for me, instead. If you go down into the Whelm, for the Water petal. Perrin's things went into the bay with him. His notebook. It was the House's, and it was the last thing he wrote, and I'd like it back.' Her voice is quite steady. 'Find me that, and you're entered for nothing. I'll lend you a helm.'".
    On discuss { Assert knows(actor, tour_fee). }
  }
  Discovery tour_fee "The Grand Tour's fee is ten coin. The Rector will waive it for a Tourist who will look in the Whelm for Perrin Halyard's notebook, which went into the bay with him, and lend them a brine-glass helm for it.".
  Action pay_fee(actor: group, site: place) "Pay the Rector the Tour's fee, ten coin" {
    Speaker quance.
    Requires able(actor) and company(actor) and at(actor, site) and at(quance, site) and knows(actor, tour_fee) and not enrolled(actor) and quantity(actor, gold) >= 10.
    Time 1 minute.
    On success { Decrease quantity(actor, gold) by 10. Increase quantity(quance, gold) by 10. Assert enrolled(actor). Give licence to actor. }
    Result "She signs the card with a flourish that goes off the edge of it, and blows on it, and gives it you. 'There. You're a Tourist. Go and be astonished at things. Bring me petals.'".
  }
  Item house_helm "the House's brine-glass helm" is brine_helm_kind at offstage.
  Relation commissioned(group).
  Topic quance_commission with quance "Say you will look in the Whelm for Perrin Halyard's notebook" when knows(actor, tour_fee) and not enrolled(actor) once {
    Says "'Bless you.' She says it simply, and for a moment she looks her age. Then she is writing on the card again, and ringing a bell, and a timid young man comes in with a glass helm in his arms like a baby. 'Tolley, the House's helm for our Tourist. Mind the bladder, it squeaks.' To you: 'His notebook is red, with the House's key on it. If you find it, bring it straight to me. Nobody else.' She signs the card. 'Not his mother, poor woman. It would only distress her.'".
    On discuss { Assert enrolled(actor). Assert commissioned(actor). Give licence to actor. Give house_helm to actor. Assert lends(quance, house_helm, actor). }
  }
  // The Rector likes to be asked, and likes to give, and remembers what she gave.
  Relation rectorFavour(group).
  Topic quance_prue with quance "Ask the Rector to have the House withdraw its complaint against Prue Quickly" when knows(actor, prue_complaint) and prueTrouble(prue) and not prueSaved(prue) once {
    Says "'The glass-blower!' She laughs till she has to sit down. 'The Mottram boy laid it on that very desk, and I turned it over and it said A PRESENT FROM SENNET, and I nearly died. The Bursar has no sense of humour; it was taken out at birth.' She scribbles a note and rings for Tolley. 'Withdrawn. With the House's compliments, and tell her I want a paperweight.' She looks at you over her spectacles, amused. 'You owe me one, now. I shall remember.'".
    On discuss { Assert prueSaved(prue). Assert rectorFavour(actor). }
  }
  // Petals laid before her, by the company or anyone, are hers (rivals.kyr has Florian bring his).
  Event fire_to_rector near quance when keeps(quance, fire_petal) and not rectorHas(fire_petal) "The Rector holds the petal up to the window, and the light in it moves, and she says nothing at all for a long moment. Then she lays it in its hollow in the black case on her desk, very gently, as if it might wake. 'One,' says Isadora Quance." then { Assert rectorHas(fire_petal). Increase rectorPetals(sennet_bay) by 1. }
  Event earth_to_rector near quance when keeps(quance, earth_petal) and not rectorHas(earth_petal) "The Rector takes the stone petal in both hands, and nearly drops it for the weight, and laughs. She sets it in its hollow in the black case. 'You'd think it would be the heavy one that's hard to get,' she says. 'It's always the light ones.'" then { Assert rectorHas(earth_petal). Increase rectorPetals(sennet_bay) by 1. }
  Event water_to_rector near quance when keeps(quance, water_petal) and not rectorHas(water_petal) "The Rector holds the green petal to her ear, the way you do a shell, and listens, with her eyes shut. Then she lays it in its hollow, wet, on the velvet." then { Assert rectorHas(water_petal). Increase rectorPetals(sennet_bay) by 1. }
  Event air_to_rector near quance when keeps(quance, air_petal) and not rectorHas(air_petal) "The Rector takes the clear petal, and it pulls upward out of her fingers, and she closes her hand on it so hard her knuckles go white. She does not ask where you found it. 'Well,' she says, very softly. 'Well, well.'" then { Assert rectorHas(air_petal). Increase rectorPetals(sennet_bay) by 1. }
  // Perrin's notebook (whelm.kyr) given her: its last pages are dated after he fell.
  Event notebook_to_rector near quance when keeps(quance, perrin_notebook) and not heardOf(quance, perrin_alive) "The Rector takes the red notebook and opens it at the end, and you see her see the dates. Her face does not move at all. 'Thank you,' she says. 'This is a great kindness.' She puts it in a drawer and locks the drawer. 'Where exactly did you find it?' And then, lightly, before you can answer: 'No. Don't tell me. It would only distress me.'" then { Assert heardOf(quance, perrin_alive). }

  // ── Mr. Edwin Tolley, amanuensis ──────────────────────────────────────────────────────────────────────────────────
  // Takes down the Rector's memoirs, Thresholds, which the Sennet Courant prints in parts; writes better than she does,
  // and she takes his sentences. Until he is his own man, whatever he hears goes to her.
  Person tolley "Mr. Edwin Tolley" at rector_study {
    Role "the Rector's amanuensis, a young man with a shorthand pad and no chin". Ancestry human. Peaceable. Pronouns he. Manner compassionate.
    Greets "A young man in a gown too big for him looks up from a shorthand pad and goes pink. 'Tolley,' he says. 'Amanuensis. I take down. The Rector's memoirs, mostly. Thresholds. The Courant prints them on Saturdays.' He looks at his pad. 'Very good they are. Everybody says so.'".
    Greets again "Mr. Tolley looks up from his pad and goes pink, and tries to hide it by writing something, and the something is your name. 'Thresholds,' he says. 'I am doing thresholds. The Rector says everyone you meet is one. I have forty pages and I am only up to the harbour.'".
  }
  Initially Assert passesTo(tolley, quance).
  Relation tolleyFriend(group). Relation tolleyCredited(group). Relation tolleyNovel(group).
  Rule tolley_works when hour(clock) >= 9 and hour(clock) < 17 and not tolleyFriend(tolley) and not at(tolley, rector_study) { Assert at(tolley, rector_study). }
  Rule tolley_works_free when hour(clock) >= 9 and hour(clock) < 17 and tolleyFriend(tolley) and not at(tolley, rector_study) and rectorFree() { Assert at(tolley, rector_study). }
  Rule tolley_evening when hour(clock) >= 19 and hour(clock) < 23 and not at(tolley, taproom) { Assert at(tolley, taproom). }
  Rule tolley_bed when (hour(clock) >= 23 or hour(clock) < 9 or (hour(clock) >= 17 and hour(clock) < 19)) and not at(tolley, offstage) { Assert at(tolley, offstage). }
  Observe tolley_writing at taproom when at(tolley, taproom) "In the corner of the Sounding Line, with a pint he has not touched, Mr. Tolley is writing in a notebook that is not his shorthand pad, fast, with his tongue between his teeth, and covering the page with his arm whenever anyone goes by.".
  Topic tolley_book with tolley "Ask Mr. Tolley what he is writing, here in the corner" when at(tolley, taproom) once {
    Says "He covers the page with both arms, and then, slowly, uncovers it. 'A novel.' He says it as if it were a disease. 'A romance. Of the sea. About a lighthouse keeper's daughter who.' He stops. 'It doesn't matter.' He turns his pint round. 'The Rector says I've no ear. She takes the bits she likes for Thresholds. That line over the gate of the House, everyone thinks is hers: Every door is a promise to someone on the other side of it. She had it off me in March. It was the first line of my chapter four.' He drinks, finally. 'She says the House's sentences are the House's.'".
    On discuss { Assert knows(actor, tolley_line). }
  }
  Discovery tolley_line "The line cut over the gate of the House of Doors, EVERY DOOR IS A PROMISE TO SOMEONE ON THE OTHER SIDE OF IT, which everyone thinks the Rector's, is Edwin Tolley's, from his novel; she took it for her memoirs, saying the House's sentences are the House's.".
  Topic quance_tolley with quance "Ask the Rector to put Mr. Tolley's name to the line over the gate" when knows(actor, tolley_line) and not tolleyCredited(tolley) once {
    Says "She stares at you. Then she throws back her head and laughs. 'Did he tell you that? The little toad.' She is not angry; she is delighted. 'Of course it's his. It's far too good for me. I steal from everybody.' She rings. 'Tolley! The next part of Thresholds will say, in a footnote, that the line over the gate is by Mr. Edwin Tolley, my amanuensis, who has more talent than is good for him. There. Now go away and stop telling Tourists things.' He goes out the colour of a beetroot. She winks at you. 'You owe me another.'".
    On discuss { Assert tolleyCredited(tolley). Assert rectorFavour(actor). }
  }
  Topic tolley_own with tolley "Tell Mr. Tolley to put his own name to his own novel, and take it to the Courant himself" when knows(actor, tolley_line) and not tolleyNovel(tolley) and at(tolley, taproom) once {
    Says "He looks at you as if you had suggested he take it to the moon. 'Under my name.' He looks at the notebook. 'Edwin Tolley. A Romance of the Sea.' He says it again, quietly, trying it. 'She'd sack me.' He thinks about that for longer than you expect, and then he laughs, out loud, for the first time since you've known him. 'She would. She'd sack me. And then I'd have to.' He closes the notebook. 'The Courant's on Fish Street. They open at nine.'".
    On discuss { Assert tolleyNovel(tolley). }
  }
  Rule tolley_his_own when (tolleyCredited(tolley) or tolleyNovel(tolley)) and not tolleyFriend(tolley) { Assert tolleyFriend(tolley). Retract passesTo(tolley, quance). }
  Topic tolley_chapter with tolley "Ask Mr. Tolley what the Rector has dictated about the night Perrin Halyard fell" when tolleyFriend(tolley) and heardFall() once {
    Says "He looks round, though there is nobody to see. 'She's done it four times.' He gets out his pad and turns back through it. 'Chapter Thirty-One, The Halyards' Reception. The first time, the morning after: I came down on the eleven o'clock basket, shaken by the height, and could not sleep. The second time she struck out shaken by the height. The third time it was the ten o'clock. The fourth time, and that's the one going to the Courant, it was the nine o'clock, with the rest of the House, and she was in her bed by ten.' He shuts the pad. 'I don't know what it means. I know she doesn't change things. She never changes anything. She says it's vulgar to revise.'".
    On discuss { Assert knows(actor, chapter_rewritten). }
  }
  Discovery chapter_rewritten "The Rector has dictated the chapter of her memoirs about the night Perrin Halyard fell four times: first saying she came down on the eleven o'clock basket shaken by the height, last that she came down at nine with the rest of the House and was in bed by ten. Mr. Tolley says she never revises anything.".

  // ── Dr. Evander Cole and the ember in Cabinet Fourteen ────────────────────────────────────────────────────────────
  // A child of the Hour Court, carried off as a curiosity eighty years ago by a Mottram, and burning since behind
  // glass. Dr. Cole knows it is alive. The Rector will not have it given back: the collection is not a lending library.
  Person cole "Dr. Evander Cole" at museum {
    Role "Curator of the Museum of the Tour, in a dusty frock-coat". Ancestry gnome. Peaceable. Pronouns he. Manner compassionate.
    Greets "A small gentleman in a frock-coat with dust in all its creases comes out from behind a cabinet with a feather duster. 'Cole. Curator. Two centuries of the Tour, and not one Tourist in fifty looks at any of it.' He dusts a bell jar. 'They look at the labels, to see whose name is on it.'".
    Greets again "'Ah,' says Dr. Cole, and dusts something, and the something is a medal he has never dusted before. 'Two centuries of the Tour, and you are the first Tourist to come back and ask a second question. I took the liberty of putting it in the catalogue.'".
  }
  Relation emberFreed(place). Relation coleAgrees(group). Relation emberAsked(group).
  Rule cole_works when openHours() and not at(cole, museum) { Assert at(cole, museum). }
  Rule cole_home when not openHours() and not at(cole, offstage) { Assert at(cole, offstage). }
  Topic cole_ember with cole "Ask Dr. Cole about the ember in Cabinet Fourteen" when not emberFreed(museum) once {
    Says "He stops dusting. 'It's alive.' He says it very quietly. 'They don't believe me, upstairs. A child of the Hour Court, a little one, a spark. Thomas Mottram scooped it up in a fire-tongs in the year 1210 and brought it home in a brass warming-pan and gave it to the Museum, and it's been in that case for eighty years.' He goes to the cabinet; the coal brightens. 'It talks to me. In sparks. I've learned a little. It says the same thing, mostly.' He puts his hand flat on the glass. 'It says, is it the next hour yet.'".
    On discuss { Assert knows(actor, ember_alive). }
  }
  Discovery ember_alive "The ember in Cabinet Fourteen of the Museum of the Tour is a living child of the Hour Court, carried off in a warming-pan by Thomas Mottram in 1210. Dr. Cole has learned a little of its sparks: it asks whether it is the next hour yet.".
  Topic cole_home_ember with cole "Ask Dr. Cole to let you take the ember home through the Fire Door" when knows(actor, ember_alive) and not emberFreed(museum) and not emberAsked(cole) once {
    Says "'I've asked.' He sits down on a bench as if his legs had gone. 'Every Rector for twenty years. This one laughed, and then she said, Evander, the collection is not a lending library.' He looks at the ember. 'It's not mine to give. It's the Museum's. It's the Mottrams', in law, I suppose, being their gift; a Mottram could take it back, I've always thought, if one ever asked, which none of them will.' He looks at you. 'Or the Rector could, by a word. She won't. I can't.' He looks at the lock on the cabinet, and then away from it, very deliberately. 'I go home at seven,' he says. 'I've always gone home at seven.'".
    On discuss { Assert emberAsked(cole). Assert knows(actor, ember_ways). }
  }
  Discovery ember_ways "Dr. Cole cannot give up the ember; it is the Museum's, or the Mottrams' in law, and a Mottram could take it back. The Rector will not. He has said, looking away from the lock on Cabinet Fourteen, that he always goes home at seven.".
  Kind ember_kind "the ember of the Hour Court" is gear worth 0 weighing 1 described "A coal the size of a hen's egg, carried in a brass warming-pan with the lid on, burning, that brightens when you speak and gives off sparks when you open the lid, as if it were asking you something.".
  Item ember "the ember" is ember_kind in cabinet owned by cole.
  Thing cabinet "Cabinet Fourteen" at museum {
    Holds.
    State locked closed "Cabinet Fourteen is locked, a little brass lock with the Museum's key on it.".
    State open "Cabinet Fourteen stands open.".
    State broken "The glass of Cabinet Fourteen is broken.".
    Change pick "Pick the lock of Cabinet Fourteen" from locked to open needing lockwork.
    Change smash "Break the glass of Cabinet Fourteen" from locked to broken needing crowbar.
  }
  Relation emberStolen(group).
  Rule ember_taken when carries(party, ember) and not emberFreed(museum) { Assert emberFreed(museum). Assert emberStolen(party). Assert lends(cole, ember, party). }
  Observe cabinet_empty at museum when emberFreed(museum) "Cabinet Fourteen is empty, the black velvet with a scorched hollow in it the size of a hen's egg. The label is still there.".
  Rule glass_heard when state(cabinet, broken) and openHours() and not brokenHeard(museum) says "Somebody in the Museum shouts at the sound of breaking glass, and runs for the Doorwarden." { Assert brokenHeard(museum). Assert hostile(cole, party). }
  Relation brokenHeard(place).
  // Given by a word of the Rector's, if she owes the company two.
  Topic quance_ember with quance "Ask the Rector to let the ember in Cabinet Fourteen go home" when knows(actor, ember_alive) and not emberFreed(museum) once {
    Says "'The ember.' She sighs. 'Evander's been at you. He's been at me for years.' She taps the pen on her teeth. 'The collection is not a lending library. If I give back one thing, every court on every plane will be at the door for its stones and its feathers and its crowns, and the Museum will be an empty room with labels in it.' She looks at you. 'No. I'm sorry. Ask me for something else.'".
    On discuss { Assert knows(actor, rector_refuses_ember). }
  }
  Discovery rector_refuses_ember "The Rector will not let the ember go home: if the Museum gives back one thing, every court of every plane will want its things back.".

  // ── Mr. Threlkeld, the Doorwarden ─────────────────────────────────────────────────────────────────────────────────────
  Person tench "Mr. Threlkeld" at hall_of_doors {
    Role "the Doorwarden, at a desk between the doors with a ledger". Ancestry halfling. Peaceable. Pronouns he. Manner stoic.
    State on_duty blocking "Mr. Threlkeld keeps the Fire Door and the Earth Door with his ledger open, and nobody goes through either without his say.".
    Guards fire_door. Guards earth_door.
    Greets "The little man at the desk looks up over half-spectacles. 'Threlkeld. Doorwarden. Name, licence, and are you sure.' He dips his pen. 'Everybody's sure. Then they come back through the Fire one with their eyebrows off.'".
    Greets again "'Name, licence, and are you sure,' says Mr. Threlkeld, without looking up, and the pen goes down with a little more force than the words. 'I have a list of those who said yes to the last question. It is longer than the list of those who came back. Do take your time.'".
  }
  Rule tench_licensed when holding(party, tour_licence_kind) and not tolerates(tench, party) { Assert tolerates(tench, party). }
  Rule tench_lets_out when within(party, fire_land) and not tolerates(tench, party) { Assert tolerates(tench, party). }
  Rule tench_lets_out_earth when within(party, earth_land) and not tolerates(tench, party) { Assert tolerates(tench, party). }
  Action tip_tench(actor: group, site: place) "Give the Doorwarden the customary shilling, and three more" {
    Speaker tench.
    Requires able(actor) and company(actor) and at(actor, site) and at(tench, site) and not tolerates(tench, actor) and quantity(actor, gold) >= 4.
    Time 1 minute.
    On success { Decrease quantity(actor, gold) by 4. Increase quantity(tench, gold) by 4. Assert tolerates(tench, actor). }
    Result "He writes something in the ledger that is not your name. 'Student,' he says. 'Visiting. Mind the heat.'".
  }
  Item tench_cloak "the House's fire-cloak" is fire_cloak_kind at offstage.
  Topic tench_cloak_lend with tench "Ask the Doorwarden for a fire-cloak out of the House's press" when holding(actor, tour_licence_kind) and at(tench_cloak, offstage) once {
    Says "He gets down off his stool, and unlocks a press, and gives you a grey cloak that stands up by itself. 'The House's. Bring it back. If you come back without it, I'll know what happened.' He climbs back on the stool. 'Cooked.'".
    On discuss { Give tench_cloak to actor. Assert lends(tench, tench_cloak, actor). }
  }

  // ── Thursday ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // The House's cat, who goes through doors.
  Person thursday "Thursday" at quad {
    Role "the House's cat, a large grey tom with singed whiskers". Species cat. Peaceable. Pronouns he.
  }
  Rule thursday_hall when hour(clock) >= 8 and hour(clock) < 12 and not following(thursday, party) and not at(thursday, hall_of_doors) { Assert at(thursday, hall_of_doors). }
  Rule thursday_stair when hour(clock) >= 12 and hour(clock) < 16 and not following(thursday, party) and not at(thursday, tower_stair) { Assert at(thursday, tower_stair). }
  Rule thursday_quad when (hour(clock) >= 16 or hour(clock) < 8) and not following(thursday, party) and not at(thursday, quad) { Assert at(thursday, quad). }
  Observe thursday_fire at hall_of_doors when at(thursday, hall_of_doors) and hour(clock) == 10 "The Fire Door opens a crack on its own, and a large grey cat walks out of it with a mouse made of cinders in his mouth, still glowing, and lays it at the Doorwarden's feet, and walks off. Mr. Threlkeld writes something in the ledger.".
  Observe thursday_flap at tower_stair when at(thursday, tower_stair) "The grey cat is sitting at the top of the tower stair washing his face. While you watch he gets up, stretches, and goes through the cat-flap in the tower door as if it were any door in the world, and the flap swings, and is still.".

  // ── Veyra's chapel ────────────────────────────────────────────────────────────────────────────────────────────────
  Person amis "Brother Amis" at chapel {
    Role "chaplain of Veyra to the House of Doors". Ancestry dwarf. Profession priest. Peaceable. Pronouns he. Manner compassionate.
    Greets "A dwarf in a grey robe is laying the place on the table again, the cup, the plate, the candle, though nothing on it has been touched. 'Veyra's,' he says. 'Keeper of the Returning Path. She asks three things of us. Share food. Remember the absent. Promise a path home.' He straightens the cup. 'The House has got very good at the second, lately, and forgotten the other two.'".
    Greets again "Brother Amis straightens the cup on the table.".
  }
  Topic amis_house with amis "Ask Brother Amis what he means, that the House has forgotten" when true once {
    Says "'The Tour was a pilgrimage, once. You went through a door, and you were a guest of whoever was on the other side, and you ate what they ate, and you came back and told your own people about them.' He looks at the table. 'Now they go through to bring things back. Look in the Museum. Every one of those things had a path home, and nobody promised it one.' He lights the candle. 'Veyra keeps the returning path. It is not a road for bringing things home. It is a road for coming home with nothing in your hands, and being glad.'".
    On discuss { Assert knows(actor, veyra_way). }
  }
  Discovery veyra_way "Brother Amis says the Tour was once a pilgrimage, where a traveller was a guest on the far side of a door and came home to tell of it; now Tourists go through to bring things back, and nothing in the Museum was ever promised a path home.".

  // ── The tower door ────────────────────────────────────────────────────────────────────────────────────────────────
  Thing tower_lock "the lock of the tower door" on nexus_way {
    State locked blocking "The tower door is locked. The lock is the size of a book.".
    State open "The tower door stands open.".
    Change pick "Pick the lock of the tower door" from locked to open needing lockwork.
  }
  Initially Assert keyholder(quance, tower_lock).
}

data/adventures/the-grand-tour/company.k:
Module sennet "The Grand Tour" {
  // The campaign played alone: a traveller with a little money, coming down the coast road to Sennet on the
  // thirteenth day after the Rector proclaimed the Grand Tour. (placed.kyr is the world's own company, come in by the
  // same road.)
  Company party "You" of 1 to 3 at coast_road.
  Initially Set quantity(party, gold) to 18. Initially Set quantity(party, rations) to 2.
}

data/adventures/the-grand-tour/courant.k:
Module sennet "The Grand Tour" {
  // ── The Sennet Courant, and the crier's board ─────────────────────────────────────────────────────────────────────
  // The race is told as the city tells it: the crier's board in the Glass Market each morning, and the Courant on
  // the bar of the Sounding Line, which prints the Rector's memoirs, Thresholds, a chapter a day through the Tour
  // (Tolley takes them down; collegium.kyr). The chapters are the Rector's history in her own voice, and the third of
  // them, printed on the morning of the funeral, is the fourth draft of the night Perrin fell: a lie a reader can
  // set beside what the winch-gang remembers.

  // The board, as the Tour goes (each line is chalked up under the proclamation, and stays).
  Observe board_fire_rival at glass_market as sign when rivalCrowned(fire_land) "Chalked under the proclamation: MR. F. MOTTRAM OF CLOUDGATE CROWNED IN THE HOUR COURT. THE FIRE PETAL TAKEN. Somebody has drawn a crown, and under it a small fire on a man's head.".
  Observe board_fire_you at glass_market as sign when everCrowned(party) "Chalked under the proclamation: A TOURIST CROWNED IN THE FIRE, NAME NOT KNOWN. A crowd is arguing about who.".
  Observe board_earth_rival at glass_market as sign when rivalHas(earth_petal) "Chalked under the proclamation: THE EARTH PETAL TO MR. MOTTRAM (DUG).".
  Observe board_divers at glass_market as sign when divers(quance) and not raided(quance) "A new bill on the board, printed: THE HOUSE OF DOORS REQUIRES DIVERS. TWO SHILLINGS A DAY AND THE HOUSE'S HELM. APPLY THE BURSAR. Under it, in chalk, in a different hand: WHAT FOR.".
  Observe board_raid at glass_market as sign when whelmRaided(admittance) "Chalked on the board: THE WATER PETAL RECOVERED FOR THE HOUSE. Under it, in another hand: FROM WHO.".
  Observe board_repulsed at glass_market as sign when raidRepulsed(quance) "Chalked on the board: THE HOUSE'S DIVERS RETURN. And under it, smaller, with a great deal of satisfaction: WET.".
  Observe board_strike at glass_market as sign when strike(sennet_bay) and not strikeOver(sennet_bay) "Chalked on the board, in capitals a foot high: THE GANG HAS SAT DOWN.".
  Observe board_desk_fire at glass_market as sign when rectorHas(fire_petal) "A card in the House's violet ink, pinned at the foot of the board: RECEIVED AT THE RECTOR'S DOOR, THE FIRE.".
  Observe board_desk_earth at glass_market as sign when rectorHas(earth_petal) "Another violet card: RECEIVED, THE EARTH.".
  Observe board_desk_water at glass_market as sign when rectorHas(water_petal) "Another violet card: RECEIVED, THE WATER. Somebody has pinned a dead fish beside it.".
  Observe board_funeral at glass_market as sign when day(clock) == 3 and hour(clock) < 12 "Across the top of the board, in black: PERRIN HALYARD LET DOWN TODAY AT NOON. HATS OFF ON THE QUAY.".

  // Thresholds, a chapter a morning, on the bar of the Sounding Line.
  Observe courant_29 at taproom as sign when day(clock) == 1 and hour(clock) >= 8 "On the bar, the Sennet Courant, with this week's part of the Rector's memoirs. THRESHOLDS, by Magistra I. Quance. Chapter the Twenty-Ninth: Under the Plate. 'I was born in a room on Fish Street that the spring tides came into, and my mother sold eels on the Quay from the barrow beside the steps. On Ascension night I sat on the third step from the bottom, on the brass plate that says how high the sea may come, and watched the lanterns go up from a hill I would never be let up; and it seemed to me that the plate had been put there for me as much as for the sea.'" teaches thresholds_plate.
  Discovery thresholds_plate "The Rector was born on Fish Street, the daughter of an eel-wife on the Quay, and as a girl sat on the brass plate on the third step to watch Cloudgate's lanterns go up; so she writes in Thresholds.".
  Observe courant_30 at taproom as sign when day(clock) == 2 and hour(clock) >= 8 "The Courant on the bar. THRESHOLDS, Chapter the Thirtieth: Second. 'I went through my first door at fourteen, as a scullion, with a bucket of the Hall's ashes, because the Doorward's boy was sick. I have been second through every door since. The second Doorward of my year, after a Mottram. The second woman to be Rector, after a Halyard. I shall be second through the Door of Doors, after whoever wins the Tour, which is only right: it will be the first door anyone ever asked me to go through.'" teaches thresholds_second.
  Discovery thresholds_second "In Thresholds the Rector writes that she has been second through every door of her life, after a Mottram, after a Halyard, and that she will be second through the Door of Doors.".
  Observe courant_31 at taproom as sign when day(clock) == 3 and hour(clock) >= 8 and rectorFree() "The Courant on the bar, with a black border for the funeral. THRESHOLDS, Chapter the Thirty-First: The Halyards' Reception. 'I left the Halyards' at nine, with the rest of the House, and came down on the nine o'clock basket, and was in my bed by ten, and knew nothing of what happened on the Balustrade until Tolley woke me in the morning. I have not slept properly since. Perrin was the best of us.'" teaches thresholds_nine.
  Discovery thresholds_nine "Thresholds, as printed on the morning of the funeral, says the Rector came down from Cloudgate on the nine o'clock basket with the rest of the House and was in bed by ten on the night Perrin fell.".
  Observe courant_32 at taproom as sign when day(clock) == 4 and hour(clock) >= 8 and rectorFree() "The Courant on the bar. THRESHOLDS, Chapter the Thirty-Second: Lanterns. 'The first time the Halyards asked me up for the Lanterns I was fifty-one and Rector of the House. I let my lantern go off the rim with the rest of Cloudgate, and watched it go up, and found that I did not want to be up there at all. I wanted to be someone who could have refused.'" teaches thresholds_refused.
  Discovery thresholds_refused "In Thresholds the Rector writes that when Cloudgate at last asked her up, she found she wanted only to have been able to refuse.".
  Observe courant_33 at taproom as sign when day(clock) >= 5 and hour(clock) >= 8 and rectorFree() and not doorOpen(sennet_bay) "The Courant on the bar. THRESHOLDS, Chapter the Thirty-Third: The Door. 'Every door is a promise to someone on the other side of it. I have kept every promise I ever made to a door.'".
  Observe courant_stopped at taproom as sign when hour(clock) >= 8 and rectorTaken(quance) "The Courant on the bar has a blank column where THRESHOLDS should be, and a line at the foot: The editor regrets.".

  // The printed lie, set beside what the winch-gang remembers, is a witness of its own.
  Rule printed_lie when knows(party, late_basket) and knows(party, thresholds_nine) and not knows(party, quance_pushed)
    says "You put the two side by side: the Rector says in print that she came down on the nine o'clock basket with the House, and Mother Kittiwake says she came down alone on the eleven o'clock, after the fall, and dropped the coin. One of them is lying in the Courant." teaches quance_pushed { }

  // The eel-wife on the next barrow: Old Bethan knew her mother.
  Topic bethan_isa with bethan "Ask Old Bethan whether she knew the Rector when she was a girl on Fish Street" when knows(actor, thresholds_plate) or knows(actor, thresholds_second) once {
    Says "'Isa Quance.' She says it the way you say a name off a gravestone. 'Her mother had the barrow next to mine forty years. Good eels. Clever girl, Isa. Too clever for the Quay, and knew it, and so did the Quay.' She kills an eel. 'She used to stand in the Ascent yard with her arms round the chain and her eyes shut, to feel it hum. Never went up it. Never asked. Then one day she went up the Headland Steps with a bucket, and that was Isa gone.' She wipes the knife. 'She comes down, Ascension Eve, every year. In that gown. Sits on my crate an hour and says nothing, and goes up to the Lanterns.' A pause. 'Brings me nothing. I'd not take it.'".
    On discuss { Assert knows(actor, isa_quance). }
  }
  Discovery isa_quance "Old Bethan knew the Rector as Isa Quance, the clever daughter of the eel-wife on the next barrow, who used to hold the anchor chain with her eyes shut to feel it hum and never went up it; she still comes and sits on Bethan's crate an hour every Ascension Eve, and says nothing.".
  Observe isa_visit at quay when isaEve() and at(quance, quay) and at(bethan, quay) "Behind Old Bethan's barrow, on an upturned crate, a tall woman in a gown of four colours is sitting with her hands in her lap, looking at the Fish Stairs. Neither of them is saying anything. After a while the woman gets up, and touches the old one's shoulder, and goes off toward the Ascent.".
}

data/adventures/the-grand-tour/door.kyr:
Module sennet "The Grand Tour" {
  // ── The Door of Doors ─────────────────────────────────────────────────────────────────────────────────────────────
  // A door standing by itself in the Nexus, with a rose of four hollows in its boss. Set all four petals and turn the
  // Rose, and it opens on anywhere; or start the tide-engine under the Whelm, and it is pushed open from below
  // (undertow.kyr). Whoever is first through it is the Doorward: from the Nexus, the Door opens for them on any town
  // they have stood in; and from any door in the world, knocked on three times, they can step back into the Nexus.
  Relation socketed(entity). Measure socketCount(place). Relation doorward(group). Relation rectorMeansFirst(group).
  Action set_fire(actor: group, site: place) "Set the Fire petal in the rose of the Door of Doors" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, nexus) and carries(actor, fire_petal) and not socketed(fire_petal).
    Time 1 minute.
    On success { Spend fire_petal_kind from actor. Assert socketed(fire_petal). Increase socketCount(nexus) by 1. }
    Result "It goes into its hollow in the boss with a click, and the light in it moves, and the door, which has been only a door, is warm under your hand.".
  }
  Action set_earth(actor: group, site: place) "Set the Earth petal in the rose of the Door of Doors" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, nexus) and carries(actor, earth_petal) and not socketed(earth_petal).
    Time 1 minute.
    On success { Spend earth_petal_kind from actor. Assert socketed(earth_petal). Increase socketCount(nexus) by 1. }
    Result "It goes in heavily, with a sound like a stone settling in a wall, and the door's frame stands a little more firmly on the floor, as if it had grown roots.".
  }
  Action set_water(actor: group, site: place) "Set the Water petal in the rose of the Door of Doors" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, nexus) and carries(actor, water_petal) and not socketed(water_petal).
    Time 1 minute.
    On success { Spend water_petal_kind from actor. Assert socketed(water_petal). Increase socketCount(nexus) by 1. }
    Result "It goes in wet, and the sound of the sea in it fills the round room for a moment, and the boards of the door darken, as if a wave had gone over them.".
  }
  Action set_air(actor: group, site: place) "Set the Air petal in the rose of the Door of Doors" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, nexus) and carries(actor, air_petal) and not socketed(air_petal).
    Time 1 minute.
    On success { Spend air_petal_kind from actor. Assert socketed(air_petal). Increase socketCount(nexus) by 1. }
    Result "It goes into its hollow pulling upward, and stops pulling, and a cold wind comes out from under the door, smelling of snow.".
  }
  Action turn_rose(actor: group, site: place) "Turn the Rose" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, nexus) and socketCount(nexus) >= 4 and not doorOpen(sennet_bay).
    Grave "The Door of Doors has not been opened in two hundred years. Opened, it is open.".
    Time 1 minute.
    On success { Assert doorOpen(sennet_bay). Assert roseMade(sennet_bay). Set openedAt(sennet_bay) to watch(clock). }
    Result "You put your hand on the boss and turn it, and it turns, the four petals going round together like the hands of a clock, and the Door of Doors opens. On the other side of it there is no room. There is everywhere. You see the coast road, and the Glass Market, and the Hour Court burning, and the inside of the Slow Assembly, and the eyrie of the North Wind, and a street in a town a long way off where it is raining, and a kitchen you have never seen with a woman in it singing, and a beach, and the moon, close, and all of them are there at once and each of them is the only one, and the wind of all of them comes through the doorway into the Nexus and lifts your hair.".
  }
  Observe door_open at nexus when doorOpen(sennet_bay) "The Door of Doors stands open in the middle of the round room, and through it, everywhere: the coast road, the Hour Court, a beach, the moon, a kitchen with a woman singing, all of them at once and each the only one. A wind comes through it that smells of every weather.".
  Observe door_shut at nexus when not doorOpen(sennet_bay) and socketCount(nexus) >= 1 "Petals set in the rose of the Door of Doors: {socketCount(nexus) in words} of the four.".
  Measure firstAt(group).
  Action step_through(actor: group, site: place) "Step through the Door of Doors, first" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, nexus) and doorOpen(sennet_bay) and not firstThrough(actor) and not rectorThrough(quance).
    Time 1 minute.
    On success { Assert firstThrough(actor). Assert doorward(actor). Set firstAt(actor) to watch(clock). }
    Result "You step through, and for a moment you are everywhere, and it is not like anything; it is like being a door. Then you think of the Nexus, because it is the last place you were, and you are standing in it again with the wind of everywhere at your back, and you are the first person in two hundred years to have done that, and you know, without anybody telling you, that the Door knows you now. That it will open for you on anywhere you have stood. And that any door in the world, knocked on three times by you, will open on this room.".
  }
  // The Doorward's door: from the Nexus to any town square or street the company has stood in; and
  // back, from anywhere indoors, by knocking.
  Action open_on(actor: group, site: place, dest: place) "Open the Door of Doors on {dest}" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, nexus) and doorward(actor) and been(actor, dest)
      and settled(dest) and not indoors(dest).
    Time 1.
    On success { Assert at(actor, dest). }
    Result "You think of {dest}, and it is there on the other side of the Door, exactly as you last saw it, and you step through.".
  }
  Action knock_home(actor: group, site: place) "Knock three times on the nearest door, and step through it into the Nexus" {
    Requires able(actor) and company(actor) and at(actor, site) and doorward(actor) and indoors(site) and not at(actor, nexus) and not inPlanes().
    Time 1.
    On success { Assert at(actor, nexus). }
    Result "You knock three times on the door, any door, and open it, and there is the round room at the top of the tower in Sennet, and the Door of Doors standing in it, and a wind of everywhere. You step through, and the door you came by shuts itself behind you.".
  }

  // Chert, who is the size of a cat, goes where the House's cat goes, and draws the bolt from inside.
  Action chert_flap(actor: group, site: place) "Ask Chert to roll through the cat-flap and draw the bolt of the tower door from inside" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, tower_stair) and travelsWith(chert, actor) and state(tower_lock, locked).
    Time 1 minute.
    On success { Assert state(tower_lock, open). }
    Result "Chert looks at the cat-flap, and at you, and says that he has been waiting six hundred and forty years for somebody to ask him to do something disreputable. He rolls through it, flap and all. There is a long pause, and the sound of a small stone person climbing a large wooden door, and then the bolt goes back with a clank, and the tower door swings open on the round room, and Chert, hanging off the bolt by both arms, says, 'There's a cat's dish.'".
  }

  // ── The petal in the keel ─────────────────────────────────────────────────────────────────────────────────────────
  Thing keel_rose "the petal in the keel" at keel {
    State set "In a socket cut into the rock of the keel, at the end of the ledge, a petal of clear glass is set, point downward, and wind pours out of it, steady and cold, smelling of snow. Leaning on the rail beside it you can feel the whole hill above you lean on it, the way a house leans on a beam.".
    State taken "The socket at the end of the ledge is empty. The rock round it is wet with thaw.".
    State replaced "In the socket at the end of the ledge, a petal of Lamp Street glass with a fern of frost in it, pouring wind. The hill leans on it as it leaned on the other.".
  }
  Observe keel_feel at keel when state(keel_rose, set) and not knows(party, keel_petal) "There is something set in the rock at the end of the ledge. You can feel the wind of it from here." teaches keel_seen.
  Discovery keel_seen "Something is set in the rock at the end of the ledge under Cloudgate, and a cold wind pours out of it downward.".
  Action take_keel(actor: group, site: place) "Take the Air petal out of the keel of Cloudgate" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, keel) and state(keel_rose, set) and not giftRenewed(sennet_bay).
    Grave "Cloudgate stands on that petal. Taken out, the hill will come down where it came from, on the Whelm.".
    Time 1 minute.
    On success { Assert state(keel_rose, taken). Give air_petal to actor. Assert petalTaken(air_petal). Assert descending(sennet_bay). Set descent(sennet_bay) to 0. Assert tookKeel(actor). }
    Result "It comes out of the rock into your hand, pulling upward, cold, and the wind stops. In the silence you hear the hill above you settle, all at once, the way a sleeper turns over; and then the ledge under your feet is not quite where it was.".
  }
  // Given again, by leave, it is a keepsake and not a key: it does not come out of the rock for anyone.
  Observe keel_kept at keel when giftRenewed(sennet_bay) and state(keel_rose, set) "The petal in the rock at the end of the ledge pours its cold wind down as it always has; but there is frost on the rock round it now, in the shape of a fern, and when you put your hand to it, it does not move at all, as a ring does not that has been worn too long to come off.".
  Relation tookKeel(group). Relation rectorTookKeel(group).
  Action swap_keel(actor: group, site: place) "Take the Air petal out of the keel, and set Prue Quickly's petal in its place" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, keel) and state(keel_rose, set) and carries(actor, made_petal) and not giftRenewed(sennet_bay).
    Time 1 minute.
    On success { Assert state(keel_rose, replaced). Spend made_petal_kind from actor. Give air_petal to actor. Assert petalTaken(air_petal). Assert madeSet(sennet_bay). }
    Result "You have to do it in one movement, the old out and the new in, with your hands numb and your heart going. For the length of a breath the wind stops and the hill leans on nothing, and the ledge tilts under you, and somewhere above you a great many plates fall off a great many dressers. Then the Lamp Street petal takes the weight, and the wind comes out of it, steady, cold, smelling of snow; and Cloudgate holds. In your other hand the true petal pulls upward, toward home.".
  }

  // ── The coming down ───────────────────────────────────────────────────────────────────────────────────────────────
  // Without its petal Cloudgate comes down where it came from, over the next hour, into the bay, on the Whelm. The
  // merfolk can go home through the Water Door, if somebody tells them in time.
  Rule descent_goes when descending(sennet_bay) and not cloudgateFell(sennet_bay) and descent(sennet_bay) < 6 { Increase descent(sennet_bay) by 1. }
  Rule descent_one when descending(sennet_bay) and descent(sennet_bay) == 1 and not toldDescent(sennet_bay)
    says "All over Sennet the windows rattle, and the dogs begin. Over the bay, in the sun above the cloud, Cloudgate has begun, very slowly, to tilt." { Assert toldDescent(sennet_bay). }
  Relation toldDescent(place).
  Observe falling_promenade at promenade when descending(sennet_bay) and not cloudgateFell(sennet_bay) "The Promenade is tilting. The gravel is running toward the Balustrade in little streams, and the orange trees in their tubs are sliding after it, and the people of Cloudgate are standing very still in their pale clothes, holding on to things, looking down, at the cloud coming up.".
  Observe falling_quay at quay when descending(sennet_bay) and not cloudgateFell(sennet_bay) "Over the bay Cloudgate is coming down through the cloud, slowly, tilted, the size of a hill, with its gardens hanging off it and its windows flashing, and the whole Quay is standing looking up at it with its mouth open, and the chain from the Ascent is going slack in great loops into the water.".
  Action warn_whelm(actor: group, site: place) "Tell No Admittance that Cloudgate is coming down on the Whelm, and the merfolk must go home through the Water Door" {
    Requires able(actor) and company(actor) and at(actor, site) and at(admittance, site) and (descending(sennet_bay) or knows(actor, keel_petal)) and not whelmEmptied(sennet_bay) and not cloudgateFell(sennet_bay).
    Time 1 minute.
    On success { Assert whelmEmptied(sennet_bay). }
    Result "No Admittance hears you without moving. Then she takes the crown of shells off her head, and holds it in her lap, and looks round her Guildhall at the white lamps and the drowned tables and the arms of the Glovers' Company, for a long time. 'Home,' she says. 'Through the Water Door. Where my grandmother came from.' She stands up out of the mayor's chair, which nobody has seen her do. 'Well. We kept it a long time.' And she raises her voice, and the Whelm comes out of its doors.".
  }
  Rule cloudgate_lands when descending(sennet_bay) and descent(sennet_bay) >= 6 and not cloudgateFell(sennet_bay) {
    Assert cloudgateFell(sennet_bay). Retract descending(sennet_bay). Set openedAt(sennet_bay) to watch(clock). }
  Rule cloudgate_lands_told when cloudgateFell(sennet_bay) and not landedTold(sennet_bay) and (within(party, sennet_town) or at(party, coast_road) or inWhelm())
    says "Cloudgate comes down into the bay. It comes down slowly, slower than you would believe, into the hole it came out of two hundred years ago; and the sea goes up round it in a wall, white, higher than the Quay, and comes in over the Quay and up the Haul and into the Glass Market to the knees, and goes out again, taking a great deal with it. When it has gone, Halyard Hill is standing in the bay where it always stood, wet to the first floor, with its gardens dripping, a little island, a hundred yards off the end of the Fish Stairs." {
    Assert landedTold(sennet_bay). }
  // Aboard, it is another thing: the ride down.
  Rule cloudgate_lands_aboard when cloudgateFell(sennet_bay) and not landedTold(sennet_bay) and within(party, cloudgate)
    says "Cloudgate comes down. From on it, it is not slow at all. The cloud comes up past the railings like a white wall and then you are in it, grey, wet, blind, with every bell in the hill ringing on its own and the dressers of Halyard House going over one after another like a long applause; and then you are out under it, in Sennet's light, and the bay is coming up, and the Quay, and every face on the Quay; and the hill sits down into the sea with a sound you feel in your back teeth, and the sea goes up all round it in a white wall, and comes down on you." {
    Assert landedTold(sennet_bay). }
  Relation landedTold(place).
  Rule cloudgate_crushes when cloudgateFell(sennet_bay) and not whelmEmptied(sennet_bay) and not whelmCrushed(sennet_bay) {
    Assert whelmCrushed(sennet_bay). }
  Relation whelmCrushed(place).
  Rule perrin_crushed when whelmCrushed(sennet_bay) and at(perrin, air_bell) and not perrinDead(party) { Assert perrinDead(party). Retract at(perrin, air_bell). Assert at(perrin, offstage). }
  Rule merfolk_gone when cloudgateFell(sennet_bay) and whelmEmptied(sennet_bay) and at(admittance, guildhall) { Retract at(admittance, guildhall). Assert at(admittance, offstage). Retract at(mercy, air_bell). Assert at(hapenny, offstage). }
  // The company on Cloudgate rides it down; under the bay, it is thrown up the stairs.
  Hazard landing "Cloudgate coming down" means "Deal (2d8) physical damage to ally unless dexterity save against (13).".
  Rule keel_drowned when cloudgateFell(sennet_bay) and at(party, keel) { Assert at(party, landing_stage). }
  Rule rides_down when cloudgateFell(sennet_bay) and within(party, cloudgate) and not rode(party) and not holding(party, feather_kind) { Assert rode(party). Assert strikes(landing, party). }
  Rule thrown_up when cloudgateFell(sennet_bay) and inWhelm() and not rode(party) { Assert rode(party). Assert strikes(landing, party). Assert at(party, fish_stairs). }
  Relation rode(group).
  // Once it is down, there is no more Ascent: the Landing Stage is a step off a boat, and the keel is under the sea.
  Rule chain_slack when cloudgateFell(sennet_bay) and not slackened(sennet_bay) { Assert slackened(sennet_bay). }
  Relation slackened(place).
  Passage hill_ferry "the ferry to Halyard Hill" is ferry between quay and landing_stage taking 10 minutes
    opening when cloudgateFell(sennet_bay) "No ferry runs between the Quay and Halyard Hill while the hill is in the sky.".
}

data/adventures/the-grand-tour/earth.kyr:
Module sennet "The Grand Tour" {
  // ── The Plane of Earth: the Slow Assembly ─────────────────────────────────────────────────────────────────────────
  // The earth-folk deliberate at the pace of stone. The Earth petal lies set in the floor of their chamber, under a
  // motion tabled in the year of the Lifting: "that the Assembly consider whether to consider the return of the petal
  // to the House of Doors". The second reading is nearly done: it has reached "...the petal to the House", at a word
  // a day of Sennet's, and two words are left. Whoever sits through them is the petitioner, and the petition will be
  // granted. Or there is Chert, the youngest delegate, who is six hundred and forty and cannot bear it.
  Initially Assert unlit(earth_threshold). Initially Assert unlit(assembly). Initially Assert unlit(minutes).
  Query inEarth() means within(party, earth_land).
  Observe threshold_earth at earth_threshold when true "Through the granite door, and the cold shuts behind you like a lid. Rock: rock above and below and on every side, and a tunnel going on into it, square, as if cut by someone with all the time in the world. There is no sound at all. The air tastes of a cellar and of something older than cellars.".
  Observe assembly_scene at assembly when true "The chamber of the Slow Assembly is a cave as big as the inside of a hill, and the Assembly sits round it in tiers: shapes of stone, some as big as houses, some as small as a dog, perfectly still, every one of them facing the middle. In the middle, set into the floor, a petal of dark stone, and over it, on a pillar of basalt, the Speaker, who is speaking. A word comes out of the Speaker, very slowly, like a boulder coming down a slope in a dream. It takes a long time to arrive.".
  Observe minutes_scene at minutes when true "The Gallery of the Minutes is a long passage whose walls are banded, layer on layer, in every colour stone comes in: the minutes of the Slow Assembly, each layer a sitting, laid down as it happened. Here and there a layer has cracked and fallen in a heap at the foot of the wall, and lies there.".

  Measure words(place). Relation motionCarried(place). Relation sat(group). Relation dugOut(group).
  Initially Set words(assembly) to 0.
  Person speaker "the Speaker of the Slow Assembly" at assembly {
    Role "a pillar of basalt that speaks, a word at a time". Species earth_elemental. Level 9. Peaceable. Pronouns it.
  }
  Person delegates "the Slow Assembly" at assembly {
    Role "a hundred shapes of stone in tiers, listening". Species earth_elemental. Numbers 9. Level 5. Peaceable. Pronouns they.
  }
  Observe speaker_word0 at assembly when words(assembly) == 0 "The Speaker is in the middle of a word. You listen through two breaths of the whole Assembly before you understand that the word, when it is finished, will be OF.".
  Observe speaker_word1 at assembly when words(assembly) == 1 and not motionCarried(assembly) "The Speaker is in the middle of a word. It will be DOORS.".
  Topic speaker_asked with speaker "Ask the Speaker of the Slow Assembly what it is saying" when true once {
    Says "The Speaker does not stop. Nothing stops in the Assembly. But after a while, a long while, a small pebble on the bottom tier rolls down to your feet and says, in a voice like gravel in a bucket, very fast: 'It's reading the motion. The second reading. That the Assembly consider whether to consider the return of the petal to the House of Doors. It's got to the petal to the House.' The pebble sighs. 'It started the second reading in your year Ten-Ninety. It'll say of tomorrow, by your sun. Doors the day after. Then it puts the question, and they'll say yes, they always say yes, they're only careful.' It looks up at you. 'If you sat through it, you'd be the petitioner. They'd give it you. Two days.' It looks round at the tiers. 'Two days! I can't bear it. I'm Chert.'".
    On discuss { Assert knows(actor, motion_known). }
  }
  Discovery motion_known "The Slow Assembly is reading the motion that it consider whether to consider the return of the petal to the House of Doors, a word a day; it has reached 'the petal to the House'. Two words are left. Whoever sits through them is the petitioner, and the Assembly will give them the Earth petal.".
  Action sit_assembly(actor: group, site: place) "Sit through a day of the Slow Assembly" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, assembly) and not motionCarried(assembly) and not petalTaken(earth_petal) and knows(actor, motion_known).
    Time 144.
    Interrupted when threatened(actor).
    On success { Increase words(assembly) by 1. Assert sat(actor). }
    Result "You sit. There is nothing else to do. You sit on a ledge of the bottom tier, in the dark or in your own small light, and the Speaker speaks, and the word comes down the slope of the day toward you, and the Assembly listens, perfectly still, and so after a while do you. You sleep, once or twice. You eat what you have. At the end of the day of Sennet's sun, which you cannot see, the word arrives, enormous and quiet, and is said; and the Assembly, all of it, settles a hair's breadth lower on its tiers, satisfied.".
  }
  Rule motion_put at assembly when words(assembly) >= 2 and sat(party) and not motionCarried(assembly) and not petalTaken(earth_petal)
    says "DOORS, says the Speaker, at last; and then, without a pause, which in the Assembly is like a shout, it puts the question. The Assembly answers. It answers all at once, a hundred voices of stone saying the same word, AYE, so low that you feel it in the floor rather than hear it, and the petal in the middle of the chamber floor rises out of the rock by itself, slowly, the way a stone comes up through a field in spring, and rolls to the feet of the petitioner." {
    Assert motionCarried(assembly). Give earth_petal to party. Assert petalTaken(earth_petal). }
  // Moved, in the old form, that the question be now put: it is a word less, and a day.
  Action move_question(actor: group, site: place) "Move, in the old form, that the question be now put" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, assembly) and knows(actor, motion_known) and not motionCarried(assembly) and not petalTaken(earth_petal) and not moved(actor)
      and (capable(actor, lore) or craft(actor, craft_learning)).
    Time 1 minute.
    Resolve check(actor, lore, dc_fair).
    On success { Assert moved(actor). Increase words(assembly) by 1. Assert sat(actor). }
    On failure { Assert moved(actor). }
    Result "You stand up on the bottom tier and say, in the form the Handbook gives for addressing a court of the planes, and the House's Aenean for the part about the question, that you move the question be now put. Nothing happens for an hour. Then the Speaker's word, which was coming slowly down its slope, comes a great deal faster, and the Assembly settles, and Chert, beside you, whispers that you have saved it a day and that he loves you.".
    Otherwise "You stand up and move it, and the Assembly does not hear, because you have not said it in any form it knows, and after an hour you sit down again.".
  }
  Relation moved(group).

  // ── Chert ─────────────────────────────────────────────────────────────────────────────────────────────────────────
  Species pebble "a pebble of the Slow Assembly" like earth_elemental tame described "A small earth-person, the size of a cat, of grey stone with white veins in it, round as a river stone, with two short stone arms and a face that is mostly cracks.".
  Person chert "Chert" at assembly {
    Role "the youngest delegate of the Slow Assembly, a pebble the size of a cat". Species pebble. Level 2. Peaceable. Pronouns he.
    Greets "A pebble the size of a cat rolls down off the bottom tier and stops against your boot. 'You're quick,' it says, with deep approval, in a voice like gravel in a bucket. 'Everything up there's quick, isn't it. I've heard. Birds. Weather. Weeks.' It looks up the tunnel toward the door. 'I'm six hundred and forty,' it says, 'and I have never seen a week.'".
    Greets again "'Still quick,' says Chert approvingly, and rolls a little way toward you, which for him is running.".
    Joins "Chert rolls up onto your boot and clings there with both stone arms. 'Don't tell them,' he says, nodding at the Assembly. 'They'll find out in about a hundred years. By then I'll have seen a bird.'".
    Leaves "'I'll roll home from here,' says Chert. 'It's downhill. Everything is, for me.'".
  }
  Relation chertAsked(group). Relation chertTook(group). Relation chertSaw(group).
  Topic chert_want with chert "Ask Chert what he would do, if he could do anything" when true once {
    Says "'See the sky.' He says it at once. 'I've heard about it. It's blue, they say, and very big, and nothing holds it up. And birds. And a week.' He rocks on his round bottom. 'I'd go through the door. I'd roll all the way to wherever the sky is and look at it until I was bored, which would be about fifty years.' He looks round at the Assembly, which has not moved. 'They'd say wait. They'd say there's a motion before the Assembly.' He makes a noise like a small landslide. 'There's always a motion before the Assembly.'".
    On discuss { Assert chertAsked(chert). Assert willing(chert, actor). Set hire(chert) to 0. }
  }
  Topic chert_petal with chert travelling "Ask Chert whether he might fetch the petal out of the chamber floor, motion or no motion" when travelsWith(chert, party) and at(party, assembly) and not petalTaken(earth_petal) once {
    Says "'It's only a motion.' He rolls off your boot and across the chamber floor, quite slowly, while the Assembly listens to the Speaker and notices nothing, and puts both his stone arms round the petal in the floor and pulls, with a face of enormous effort, and it comes out of the rock with a sound like a cork. He rolls back with it held over his head. 'There,' says Chert. 'They'll find out in about a hundred years. They'll say, Chert. In that voice.' He grins with all his cracks. 'I'll be a hundred and forty by then. I'll be old enough to argue.'".
    On discuss { Assert chertTook(chert). Give earth_petal to actor. Assert petalTaken(earth_petal). }
  }
  Rule chert_sees_sky when travelsWith(chert, party) and (within(party, cloudgate) or within(party, sennet_town) or at(party, coast_road)) and at(party, ?p) and not indoors(?p) and not dark() and not chertSaw(chert)
    says "Chert, on your boot, sees the sky, and goes completely still, and stays still for so long that you think he has turned back into a stone. Then he says, very small, 'Oh.' And then, 'It doesn't hold up.' And then, 'Nothing holds it up.' And he does not say anything else for an hour." {
    Assert chertSaw(chert). }
  // Dug out with a pick, which the Assembly will consider.
  Action dig_petal(actor: group, site: place) "Dig the Earth petal out of the chamber floor while the Assembly listens to the Speaker" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, assembly) and not petalTaken(earth_petal) and (capable(actor, digging) or craft(actor, craft_earth)).
    Time 6.
    On success { Assert dugOut(actor). Give earth_petal to actor. Assert petalTaken(earth_petal). }
    Result "You dig. The rock round the petal is hard, and old, and does not want to go, and you swear at it in a whisper because it seems wrong to swear aloud; and after an hour the petal comes out of the floor in your hands, heavy as a sleeping cat, and the Assembly does not move. Not a hair. You go up the tunnel with it with the back of your neck crawling. Behind you, very slowly, something has begun to turn its head.".
  }
  Rule assembly_turns when dugOut(party) and not inEarth() and not assemblyTurned(party) { Assert assemblyTurned(party). }
  Relation assemblyTurned(group).

  // ── The Minutes ───────────────────────────────────────────────────────────────────────────────────────────────────
  Kind geode_kind "a geode from the Minutes" is treasure worth 4 weighing 2 described "A round grey stone the size of an apple, from a fallen layer of the Minutes of the Slow Assembly, that rattles a little when you shake it. Chert says it is an amendment, abandoned, and hollow inside, and that it took longer to grow than your whole kind has had names.".
  Item geode "a geode" is geode_kind at minutes.
  Topic chert_geode with chert "Ask Chert about the round stones in the fallen layers of the Minutes" when true once {
    Says "'Amendments.' He sounds bored. 'Abandoned ones. They fall out of the minutes when nobody seconds them, and lie about.' He looks at you sideways. 'They're hollow. Crack one, and it's all crystals inside. Took a million years to grow, give or take. Everyone up there makes such a fuss about them.' He rolls a little. 'You can have one. Nobody'll miss it. Nobody's missed anything in here since the Lifting.'".
    On discuss { Assert knows(actor, geode_known). }
  }
  Discovery geode_known "The round stones in the fallen layers of the Minutes of the Slow Assembly are abandoned amendments, hollow, lined with crystal that took about a million years to grow. Chert says the company may have one.".
}

data/adventures/the-grand-tour/endings.k:
Module sennet "The Grand Tour" {
  // ── When the book closes ──────────────────────────────────────────────────────────────────────────────────────────
  // At nine on the morning after the Door of Doors is opened or Cloudgate comes down, or on the eighth morning,
  // whichever is first. What became of each of the city's people is told an hour before, as the morning's news
  // (aftermath.kyr); the settlement is the city's answer to what was taken, and what was given back.
  Measure decisiveDay(place).
  Rule decided when (doorOpen(sennet_bay) or cloudgateFell(sennet_bay)) and decisiveDay(sennet_bay) == 0 { Set decisiveDay(sennet_bay) to day(clock). }
  Query closingDay() means (decisiveDay(sennet_bay) >= 1 and day(clock) > decisiveDay(sennet_bay)) or day(clock) >= 8.
  Query closing() means closingDay() and hour(clock) >= 9.

  Ending end_accomplice "First Through" when closing() and accomplice(party) "You went through the Door of Doors first, as she promised, with the Rector of the House of Doors laughing at your elbow, and the wind of everywhere in your face; and you came back, as the Door lets you. She did not. Behind you, while you went, a hill came down out of the sky into the bay. In the morning Sennet does not know who took the petal out of the keel, nor yet how many of the sea-folk were under the hill when it came down, and the Door of Doors knows you, and will open for you on anywhere you have stood, for as long as you live. Every place you think of is there on the other side of it. You find that there are a great many places you would rather not see again.".
  Ending end_second_whelming "The Second Whelming" when closing() and cloudgateFell(sennet_bay) and not whelmEmptied(sennet_bay) "In the morning Halyard Hill is standing in the bay where it stood two hundred years ago, wet to its first floors, its gardens hanging off it in ropes of weed, a hundred yards off the end of the Fish Stairs; and under it is the Whelm. Chandlers' Row, and Lir's church with its bell, and the Guildhall with the arms of the Glovers' Company, and the merfolk who lived in them, who had never in their lives been told that anything was coming. Some got through the Water Door. Not many. All morning things come up on the tide at the Fish Stairs: a teapot, a drowned armchair, a basket of cockles. The harbour stands on the Quay and watches the water and says nothing, not even the thing it says when the sea is up. Cloudgate's people come across on the fishermen's boats, in their pale clothes, wet, and stand on the Quay among them, and for once nobody in Sennet can tell which is which.".
  Ending end_coming_down "The Coming Down" when closing() and cloudgateFell(sennet_bay) "In the morning Halyard Hill is an island in the bay, a hundred yards off the end of the Fish Stairs, wet to the first floor, with its orange trees standing in the sea; and the Whelm under it is empty. No Admittance took her people home through the Water Door in the hour before it came down, the whole Whelm in a long line through the green, children and old men and the lamps they could carry, the first time in three generations, and the Door closed behind them. Ha'penny came up to the third step before she went, to say goodbye to the Quay, and left her basket on it. Now the Fish Stairs go down into rock. A ferry runs to Cloudgate from the end of the Quay for a penny; the Halyards walk on the Quay like anybody, and buy eel pies, and are cheated, like anybody. It is not always afternoon there any more. It is whatever it is in Sennet.".
  Ending end_rectors_door "The Rector's Door" when closing() and rectorThrough(quance) and not firstThrough(party) "The Rector of the House of Doors went first through the Door of Doors, in her gown of four colours, with the wind of everywhere lifting the hair off her forehead, and did not come back on this side. The House has a new Rector by the morning, a nervous man from the Earth faculty who will not go up the tower stair. Nobody knows where she went. The Courant prints the last part of Thresholds on Saturday, as dictated, and it ends at the door. Some say she is somewhere very far off, being first at things. Some say the Door of Doors does not open on anywhere for a person who has done what she did; only on everywhere, which is not the same, and which you cannot come back from. The Grand Tour is declared closed. Its prize has been taken.".
  Ending end_made_petal "A Present from Sennet" when closing() and madeSet(sennet_bay) "In the morning Cloudgate is in the sky, where it has always been, at the top of its chain, in the sun above the cloud; and it is held up there by a petal of Lamp Street glass with a fern of frost in it, made in a night by a woman with no eyebrows, and stamped on the back, very small, A PRESENT FROM SENNET. Prue Quickly sends the Halyards her account, which is very long, and includes the heat, the night, the frost on the street and the breakage, and the Halyards pay it, because there is nobody else in the world who can make another. The winch-gang has had its third. Cloudgate is now, in a manner of speaking, in trade. Down on the Quay they think this the best joke in two hundred years, and they are right.".
  Ending end_gift_renewed "The Keepsake" when closing() and giftRenewed(sennet_bay) and imogenSorry(imogen) "It snowed on Sennet in June: big soft flakes out of a clear sky, on the Quay and the glass-houses and the bay, on Cloudgate's orange trees, on the brass plate on the third step of the Fish Stairs. By morning it has gone, and Cloudgate is still in the sky, held up by a keepsake that is not its own, by leave. The Halyards know it now, and so does the harbour, because the sylphs told everyone. Lady Halyard came down the chain in the night and stood on the Quay among the harbour's candles with one of her own, which she did not know how to light, and Old Bethan lit it for her without a word. Nobody in Sennet is sure yet what it means that she came. Nobody in Cloudgate is sure either.".
  Ending end_letter "The Letter" when closing() and giftRenewed(sennet_bay) "It snowed on Sennet in June: big soft flakes out of a clear sky, on the Quay and the glass-houses and the bay, on Cloudgate's orange trees, on the brass plate on the third step of the Fish Stairs. By morning it has gone, and Cloudgate is still in the sky, held up by a keepsake that is not its own, by leave of a wind who was given a letter two hundred years late, by a hand that had no business with it. Nobody at Halyard House knows who opened the escritoire. Lady Halyard has had the lock changed, and sat on in the drawing room until the fire was out, with an empty box and a green ribbon in her lap, and has not sent for the Watch. The sylphs know, and are telling everyone. Nobody believes them; it is too good.".
  Ending end_undertow "The Undertow" when closing() and openedBelow(sennet_bay) "The Door of Doors was opened from below, by the whole of the Whelm with its hands on a wheel the Aeneans found, and wrote their plaque beside, and by you; and the Rose was never made. The four petals of it are where they are: in their courts, in your packs, in the keel of a hill in the sky. The Grand Tour is declared, by a House that does not know what else to declare, won. The lamps of the Whelm came back on at the turn of the next tide, row by row along the Undercroft, as if somebody were walking along them with a taper; and the merfolk came out of their houses into the green and looked at one another, and No Admittance said, in bubbles, that it had been a long time since anybody in the Whelm had done anything, and that she had liked it.".
  Ending end_found_out "Found Out" when closing() and rectorTaken(quance) "The Rector of the House of Doors is in the Watch-house on Fish Street, in a cell with a window on the bay, dictating to nobody. Sergeant Bassett brings her tea. She is perfectly charming to him. The Door of Doors stands in its round room at the top of the tower, shut, with the cat-flap of the tower door swinging, and the House has no Rector, and the Grand Tour is suspended, pending. Nobody has opened anything. Nobody has fallen out of the sky. The courts keep their petals, or you do, or a hill does. In Sennet they say it is the strangest Tour there has ever been, because nobody won it, and everybody seems to have come home.".
  Ending end_kept_above "Kept Above" when closing() and bribed(party) "Cloudgate is in the sky, at the top of its chain, in the sun, and it is always afternoon there, and it is held up by a thing it was given for love and used as a lever, and you know it, and have a hundred coin of the Halyards' money in your pack for knowing it. You are received at Halyard House whenever you go up. You find that you do not go up.".
  Ending end_unopened "The Tour Unfinished" when closing() "The eighth morning. The Door of Doors is shut at the top of the tower, and the Rose is in pieces where it was, and Cloudgate is in the sky, and the Whelm is under the bay, and the gulls stand on the bollards of the Quay as if they had been appointed to them. The Grand Tour goes on, the crier says, until somebody wins it. Somebody may. Sennet does not wait to see. It has eels to sell.".
}

data/adventures/the-grand-tour/fall.kyr:
Module sennet "The Grand Tour" {
  // ── Who was at the Balustrade ─────────────────────────────────────────────────────────────────────────────────────
  // Three people saw a piece of it, and each told it only once something had been done for them: Mother Kittiwake
  // (the eleven o'clock basket), Jem Tuttle (the sleeves, the chain), Mr. Tolley (the chapter dictated four times).
  // Perrin heard the keys. Any two of the three, put together, say who it was; so does Perrin, told any one.
  Rule two_witnesses_basket_sleeves when knows(party, late_basket) and knows(party, bishop_sleeves) and not knows(party, quance_pushed)
    says "You put it together: a woman at the rail at ten in a gown with sleeves like a bishop's, and a chain that rang; and the Rector, alone, on the eleven o'clock basket, with a hand that shook so she dropped the crown." teaches quance_pushed { }
  Rule two_witnesses_basket_chapter when knows(party, late_basket) and knows(party, chapter_rewritten) and not knows(party, quance_pushed)
    says "You put it together: the Rector came down alone on the eleven o'clock basket after the fall, shaking; and she has dictated that night four times, until she came down at nine and was in bed by ten." teaches quance_pushed { }
  Rule two_witnesses_sleeves_chapter when knows(party, bishop_sleeves) and knows(party, chapter_rewritten) and not knows(party, quance_pushed)
    says "You put it together: a woman at the rail at ten in a gown with sleeves like a bishop's, with a chain that rang; and the Rector, who never revises, has rewritten the night four times." teaches quance_pushed { }
  // Who can be brought to say what they saw, out loud, before others.
  Query witnessKittiwake() means knows(party, late_basket) and gangFriend(party).
  Query witnessJem() means knows(party, bishop_sleeves) and jemFree(jem).
  Query witnessTolley() means knows(party, chapter_rewritten) and tolleyFriend(tolley).
  Query twoWitnesses() means (witnessKittiwake() and witnessJem()) or (witnessKittiwake() and witnessTolley()) or (witnessJem() and witnessTolley()).
  Query perrinHere() means following(perrin, party) or (perrinUp(party) and at(perrin, ?p) and at(party, ?p)).

  // ── Before Cloudgate, at the Lanterns ─────────────────────────────────────────────────────────────────────────────
  Action accuse_lanterns(actor: group, site: place) "Say out loud, before all Cloudgate, that the Rector pushed Perrin Halyard off the Balustrade" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, promenade) and at(quance, site) and lanternNight() and knows(actor, quance_pushed) and rectorFree() and not accused(actor).
    Grave "Said before all Cloudgate, it is said, and the Rector will know you know.".
    Time 1 minute.
    On success { Assert accused(actor). Assert heardOf(quance, quance_pushed). Increase talk(actor) by 2. }
    Result "You say it. Your voice goes out across the Promenade in the silence of the band's stopping, and every face turns. The Rector of the House of Doors lowers her glass.".
  }
  Relation accused(group).
  Rule accusation_holds at promenade when accused(party) and rectorFree() and (perrinHere() or twoWitnesses()) and lanternNight()
    says "Nobody laughs. Somebody says the name of Jem Tuttle, the footman who went down, and somebody says that Mother Kittiwake has been telling the winch-house about the eleven o'clock basket since the fourth day; and the Rector looks round the faces of Cloudgate one by one, and sees in them that it is believed. 'Well,' she says, and sets her glass down on the rim of the Balustrade, very carefully. The Dowager says, 'Take her,' without raising her voice, and four Halyard footmen do." {
    Assert rectorExposed(quance). Assert rectorTaken(quance). Assert at(quance, offstage). Assert rectorLostPetals(quance). }
  Rule accusation_fails at promenade when accused(party) and rectorFree() and not perrinHere() and not twoWitnesses() and lanternNight() and not laughed(party)
    says "There is a silence; and then the Rector laughs, delightedly, and Cloudgate laughs with her, because she is laughing. 'My dear,' she says, 'what a story. You must write it down.' She raises her glass to you. Over its rim, for a moment, her eyes are not laughing at all." {
    Assert laughed(party). }
  Relation laughed(group). Relation rectorLostPetals(group).
  // Taken, she gives up what she held: the petals go back to the courts they came from, or to whoever won them.
  Rule petals_released when rectorLostPetals(quance) and (rectorHas(fire_petal) or rectorHas(earth_petal) or rectorHas(water_petal)) {
    Retract rectorHas(fire_petal). Retract rectorHas(earth_petal). Retract rectorHas(water_petal). Assert petalsHeld(sennet_bay). }
  Relation petalsHeld(place).
  Topic imogen_petals with imogen "Ask Lady Halyard for the petals the Rector was carrying" when petalsHeld(sennet_bay) once {
    Says "'The House's? Or the courts'?' She has the black case in her lap; the footmen brought it. She opens it, and looks at what is in it for a long moment, and closes it, and gives it you. 'I find I do not want anything in my house,' says Lady Halyard, 'that anybody has carried up a hill.'".
    On discuss { Retract petalsHeld(sennet_bay). Give fire_petal to actor. Give earth_petal to actor. Give water_petal to actor. }
  }

  // ── Before the Watch ──────────────────────────────────────────────────────────────────────────────────────────────
  Topic bassett_told with bassett "Lay before Sergeant Bassett what the winch-gang, the footman and the amanuensis know about the night Perrin Halyard fell" when knows(actor, quance_pushed) and twoWitnesses() and rectorFree() once {
    Says "The sergeant hears it all without a word, writing in his notebook on the crown of his hat. When you have finished he reads it back to you, slowly, with his finger under the line, and asks you twice whether that is what was said, and twice you tell him it is. Then he puts the notebook away. 'I've known the winch-gang thirty years,' he says, 'and the Halyards' people, and most of the House. They're not all honest. But they're frightened, and frightened people are mostly telling the truth.' He puts his hat on. 'I'm going up the headland,' says Sergeant Bassett, 'to have a word.'".
    On discuss { Assert rectorExposed(quance). Assert bassettGoes(bassett). Set bassettAt(bassett) to watch(clock). }
  }
  Relation bassettGoes(group). Measure bassettAt(group).
  Rule bassett_takes when bassettGoes(bassett) and not rectorTaken(quance) and not rectorThrough(quance) and not rectorFled(quance) and (within(quance, sennet_town) or at(quance, offstage)) and watch(clock) >= bassettAt(bassett) + 6
    says "Sergeant Bassett of the Watch walks up the Headland Steps with his hat in his hand, and into the House of Doors, and is in the Rector's study for a quarter of an hour; and, in the hour after, the whole of Lamp Street sees him come down again with the Rector of the House of Doors walking beside him in her gown of four colours, her chain of keys in his other hand, talking to him pleasantly about the weather in Cloudgate." {
    Assert rectorTaken(quance). Assert at(quance, offstage). Assert rectorLostPetals(quance). }

  // ── Perrin, face to face ──────────────────────────────────────────────────────────────────────────────────────────
  Event perrin_meets_rector near quance when perrinHere() and rectorFree() and at(quance, ?p) and at(party, ?p) and not dark() "The Rector turns, and sees Perrin Halyard, wet, on a crutch made of an oar, and for the first time since you have known her Isadora Quance has nothing to say. She looks at him. He looks at her. 'You lent me your own books,' he says. 'You taught me Aenean.' 'You were the best I ever had,' she says, and her voice is quite steady. 'And you were going to give it to the wind.' She looks down at her hands, and at the keys on her chain, and takes the chain off over her head, and holds it out to him; and when he does not take it she lets it fall on the floor between them. 'Say it where it can't be unsaid,' says the Rector. 'I taught you that.' And she sits down on the nearest thing, which is the floor, in her gown of four colours, and waits for whoever will come." then {
    Assert rectorExposed(quance). Assert rectorTaken(quance). Assert rectorLostPetals(quance). Assert perrinConfronted(perrin). }
  Relation perrinConfronted(group).
  Rule rector_led_off when rectorTaken(quance) and not at(quance, offstage) { Assert at(quance, offstage). }

  // ── Kept above: the Dowager's price ───────────────────────────────────────────────────────────────────────────────
  Topic imogen_secret with imogen "Tell Lady Halyard you know what holds Cloudgate up" when knows(actor, keel_petal) and not secretToldImogen(actor) and not cloudgateFell(sennet_bay) and not imogenSorry(imogen) once {
    Says "She does not look at the portrait. She looks at your boots, which have been on the Quay. Then she goes to the escritoire, and unlocks it, and takes out a purse, heavy, and sets it on the table between you. 'A hundred coin,' she says. 'And the friendship of this house, which in Cloudgate is worth more than the coin.' She does not sit down. 'My son wanted to give it to the wind. My son is at the bottom of the bay.' Her face does not move. 'What do you want?'".
    On discuss { Assert secretToldImogen(actor). Assert bribeOffered(actor). }
  }
  Topic take_bribe with imogen "Take the purse, and say you will keep Cloudgate's secret" answering imogen_secret when bribeOffered(actor) and not bribed(actor) once {
    Grave "A hand that takes the Halyards' money keeps the Halyards' secret.".
    Says "She does not watch you pick it up. 'Thank you,' she says, to the window. 'You will be received in this house, whenever you come up.' And then, still to the window: 'He would have despised you.'".
    On discuss { Assert bribed(actor). Increase quantity(actor, gold) by 100. Assert promiseMade(keep_secret). }
  }
  Topic refuse_bribe with imogen "Leave the purse on the table" answering imogen_secret when bribeOffered(actor) and not bribed(actor) and not refusedBribe(actor) once {
    Says "She looks at the purse, and at you, and for a moment something moves in her face that might be respect, and might be fear. 'Then we understand each other,' says Lady Halyard. 'Good afternoon.'".
    On discuss { Assert refusedBribe(actor). }
  }
  Relation refusedBribe(group).
  Promise keep_secret "to keep the secret of what holds Cloudgate up" to imogen
    kept when cloudgateFell(sennet_bay) or doorOpen(sennet_bay) or day(clock) >= 8 "Lady Halyard's purse is lighter, and her house is still in the sky."
    broken when heardOf(sylphs, keel_petal) or tookKeel(party) "Somewhere in Cloudgate a door is closed to you for good." { }.

  // ── The wrong answer ──────────────────────────────────────────────────────────────────────────────────────────────
  // Aubrey's own story, carried to the Watch, is believed: he believes it himself. The Rector is pleased. Only the
  // dead man can undo it, by coming up.
  Relation aubreyTaken(group).
  Topic bassett_aubrey with bassett "Tell Sergeant Bassett that it was Aubrey Halyard who pushed his brother off the Balustrade" when knows(actor, aubrey_quarrel) and not aubreyTaken(aubrey) and not aubreyFreed(aubrey) and not knows(actor, quance_pushed) and not bassettGoes(bassett) once {
    Grave "Aubrey Halyard believes it himself. If you say it to the Watch, he will not deny it.".
    Says "The sergeant writes it down, every word, on the crown of his hat, and reads it back to you, and you hear how it sounds: two brothers, a quarrel, the fog, the rail. 'Heir to Cloudgate,' he says. 'That'll be a long day.' He puts his hat on. 'I'll go up and ask him. Mostly they tell you.'".
    On discuss { Assert aubreyTaken(aubrey). Assert aubreyTakenSays(bassett). Set bassettAt(bassett) to watch(clock). }
  }
  Relation aubreyTakenSays(group).
  Rule aubrey_led_down when aubreyTakenSays(bassett) and watch(clock) >= bassettAt(bassett) + 6 and not at(aubrey, offstage) and not aubreyFreed(aubrey)
    says "Within the hour Sergeant Bassett comes down the chain in the basket with Aubrey Halyard beside him, unshaven, in last night's shirt, not in irons, looking at the cloud going past as if he had never seen it. The whole Quay watches them walk to the Watch-house on Fish Street. Aubrey does not deny anything. He thanks the sergeant for the walk." {
    Assert at(aubrey, offstage). }
  Observe rector_pleased at rector_study when aubreyTaken(aubrey) and not aubreyFreed(aubrey) and at(quance, rector_study) "The Rector looks up from Tolley's pad as you come in. 'Poor Aubrey,' she says. 'I always thought it might be. One hopes the court is kind.' Her keys chime. She looks, for the first time since you have known her, entirely at rest.".
  Topic perrin_brother_taken with perrin "Tell Perrin Halyard that his brother is in the Watch-house, for pushing him" when aubreyTaken(aubrey) and not aubreyFreed(aubrey) and not perrinWantsUp(perrin) once {
    Says "He does not say anything. He puts the drowned book down on the weed, very carefully, open, so as not to lose his place, and then he looks at the oar splinted to his leg as if it were somebody else's. 'He'll say yes,' he says at last. 'He'll say yes to all of it, because he thinks it's true. The idiot. The great kind idiot.' He reaches for the oar. 'Get me up those stairs.'".
    On discuss { Assert perrinWantsUp(perrin). }
  }
  Rule aubrey_released when aubreyTaken(aubrey) and not aubreyFreed(aubrey) and (perrinUp(party) or rectorExposed(quance))
    says "Word comes along the Quay as fast as a gull: the Watch has let Aubrey Halyard go. He walked out of the Watch-house on Fish Street and stood on the step in the sun, and did not seem to know which way to go, and then went down to the Fish Stairs and sat on the third one, on the plate, and stayed there." {
    Assert aubreyFreed(aubrey). Retract aubreyTaken(aubrey). Assert at(aubrey, aubrey_rooms). }
}

data/adventures/the-grand-tour/fire.kyr:
Module sennet "The Grand Tour" {
  // ── The Plane of Fire: the Hour Court ─────────────────────────────────────────────────────────────────────────────
  // Nothing in the Fire lasts more than an hour, so the court of the ifrit values only what is new. A thing seen
  // twice is ash. Every hour the court crowns whatever is newest in it, and the Monarch holds the Fire petal for the
  // hour, in a brazier of white fire, and may do with it as a Monarch does. What the Fire has never in its existence
  // seen is anything old.
  Hazard heat "The heat of the Fire" means "Deal (1d6) fire damage to ally unless constitution save against (11).".
  Query inFire() means within(party, fire_land).
  Relation scorched(group).
  // Every half hour, not every ten minutes: the Fire is meant to drive a Tourist out, not cook one mid-sentence.
  // Once on the way in, unshielded; half an hour later the court carries out whoever is still there, and sets them
  // down at Mr. Threlkeld's feet: the Fire is meant to drive a Tourist out, not cook one mid-sentence.
  Measure scorchedAt(group). Relation scorching(group).
  Rule fire_scorches when inFire() and not capable(party, heatproof) and not heatSuspended(fire_land) and not scorching(party) {
    Assert strikes(heat, party). Assert scorching(party). Set scorchedAt(party) to watch(clock). }
  Rule fire_carries_out when inFire() and scorching(party) and not capable(party, heatproof) and not heatSuspended(fire_land) and watch(clock) >= scorchedAt(party) + 3
    says "The heat takes your legs out from under you. The last thing you see clearly is the Hour Court, crowding round, interested; and then you are being carried, by a great many hands that are too hot to bear, through a door, and set down on cold stone. 'Cooked,' says Mr. Threlkeld, above you, and writes it in the ledger." {
    Retract scorching(party). Assert at(party, hall_of_doors). }
  Rule fire_cools when scorching(party) and not inFire() { Retract scorching(party). }
  Rule fire_scorch_told when inFire() and not capable(party, heatproof) and not scorched(party) says "The heat comes at you like a hand on the face. Your hair crackles. Without a fire-cloak, the Fire will cook you a little at a time." { Assert scorched(party). }
  Rule fire_scorch_reset when scorched(party) and not inFire() { Retract scorched(party). }
  Observe threshold_fire at fire_threshold when true "Through the door, and the Hall is gone, and there is no ground, only a floor of red light like the floor of a forge, and over it a sky of slow orange cloud, and everything moving, flickering, changing its shape while you look at it: hills that are flames, flames that are towers. Behind you the Fire Door stands in nothing, a door-shaped piece of cool grey Sennet, with a halfling's ledger visible through it.".
  Observe hour_court_scene at hour_court when true "The Hour Court is a great hall without walls, held up by pillars of fire that are never the same pillars twice. The court of the ifrit moves through it, tall and burning, in clothes of smoke, talking all at once and never about the same thing for more than a moment. In the middle, on a dais of embers, a brazier of white fire, and in the white fire, lying on it as if on a cushion, a petal of red glass. Beside the brazier, a throne, and on the throne, this hour's Monarch.".
  Observe hour_monarch_a at hour_court when not crowned(party) and not emberCrowned(fire_land) and hour(clock) < 6 "This hour's Monarch is a little salamander in a paper crown, who seems as surprised as anyone.".
  Observe hour_monarch_b at hour_court when not crowned(party) and not emberCrowned(fire_land) and hour(clock) >= 6 and hour(clock) < 12 "This hour's Monarch is a song: a tune of three notes that somebody made up a little while ago, sitting on the throne as a wavering in the air. The court bows to it.".
  Observe hour_monarch_c at hour_court when not crowned(party) and not emberCrowned(fire_land) and hour(clock) >= 12 and hour(clock) < 18 and not rivalCrowned(fire_land) "This hour's Monarch is a colour nobody had seen before this morning, a kind of blue-red, sitting on the throne as a light.".
  Observe hour_monarch_d at hour_court when not crowned(party) and not emberCrowned(fire_land) and hour(clock) >= 18 "This hour's Monarch is an ifrit child of a few minutes old, asleep on the throne, glowing. The court tiptoes.".
  Observe hour_monarch_you at hour_court when crowned(party) "This hour's Monarch is you. The court of the ifrit stands about the throne, burning, and watches you with the most enormous interest, as they have watched nothing else in their lives, for the length of an hour.".
  Observe hour_monarch_ember at hour_court when emberCrowned(fire_land) "This hour's Monarch, and the last hour's, and the hour's before, is a small coal on the throne, the size of a hen's egg, that remembers. The court has never had a Monarch that remembered anything, and stands about it, burning, in an uneasy and delighted silence.".
  Observe ash_scene at ash_market when true "The Ash Market: stalls of flame selling flame. Everything on them is brand-new and burning, and will be ash within the hour, and the ifrit buying and selling it do not seem to mind; they mind only if it is not new. At the back of the market, where the stalls were an hour ago, lie drifts of grey ash, and a breeze is taking them.".
  Observe lists_scene at lists when true "The Lists of the Salamanders: a ring of fire, and in the ring two salamanders as long as horses fighting, rolling over and over, biting, while the court of the ifrit watches and cheers each new hold and turns away bored at any it has seen before.".

  Relation heatSuspended(place). Relation crowned(group). Relation emberCrowned(place). Relation rivalCrowned(place).
  Relation shown(entity). Measure reign(place). Measure lastHour(place). Relation sangToCourt(group).
  Initially Set reign(fire_land) to 3. Initially Set lastHour(fire_land) to 8.
  Relation everCrowned(group).
  Rule hour_turns_told at hour_court when inFire() and hour(clock) != lastHour(fire_land) and crowned(party)
    says "A bell of fire rings somewhere, and the hour turns, and the court turns away from you all at once, as if you had never been, to crown whatever is newest now. Your reign is over." { }

  // Each hour the court crowns its own newest, at three; and whatever the company was is over.
  Rule hour_turns when hour(clock) != lastHour(fire_land) {
    Set lastHour(fire_land) to hour(clock). Set reign(fire_land) to 3. Retract crowned(party). Retract heatSuspended(fire_land). }
  // ── The hawker ────────────────────────────────────────────────────────────────────────────────────────────────────
  Person hawker "a hawker of the Ash Market" at ash_market {
    Role "an ifrit selling flames off a tray of flame". Species ifrit. Peaceable. Pronouns they.
    Greets "An ifrit with a tray of fire hung round their neck turns to you and looks you over, flickering. 'New!' they say. 'You're new. I've never seen you.' They look again, and their face falls in on itself in smoke. 'Oh. I have now.'".
    Greets again "'Have I seen you?' says the hawker, and squints. 'I have. Pity.'".
  }
  Topic hawker_rule with hawker "Ask the hawker how a Monarch is made in the Hour Court" when true once {
    Says "'Newness!' They spread their hands, and flames come off the fingers. 'Every hour the court crowns the newest thing in it. A song somebody's just made up. A colour. A baby. A fight, if it's a new fight; never the same hold twice.' They lean close, hot as an oven. 'Show the court something it has never seen, and if it's newer than the Monarch, you're the Monarch till the bell. And the Monarch has the brazier, and the petal on it.' They shrug, in sparks. 'Only nothing's new to us for long. A thing seen twice is ash. And we've seen everything that burns.' They look at you with sudden cunning. 'What have you got that doesn't?'".
    On discuss { Assert knows(actor, hour_rule). }
  }
  Discovery hour_rule "In the Hour Court a new Monarch is crowned every hour, of whatever is newest there. Shown something it has never seen, newer than the Monarch, the court crowns whoever showed it until the bell, and the Monarch holds the Fire petal. A thing seen twice is ash to them; they have seen everything that burns.".
  Topic hawker_old with hawker "Ask the hawker what is the newest thing anyone ever showed the court" when knows(actor, hour_rule) once {
    Says "'Oh.' The hawker goes quite still, which for an ifrit is a kind of trance. 'There was a woman, once, before I was lit. I was told. In a grey cloak, with a book. She showed them a snowball.' They shiver, in sparks. 'Cold. A thing that was cold. And then she was rude to them, which nobody had ever been.' They lean in. 'The oldest thing in the Fire is about an hour old. Anything older than that,' they whisper, as if it were indecent, 'nobody here has ever seen. We wouldn't know what to do with ourselves.'".
    On discuss { Assert knows(actor, old_is_new). }
  }
  Discovery old_is_new "Nothing in the Fire is older than an hour, so nothing old has ever been seen there: the hawker says the court would not know what to do with itself before anything old.".

  // ── Things to show the court ──────────────────────────────────────────────────────────────────────────────────────
  // Each is shown once; a thing newer than this hour's Monarch crowns the company. The newest of all are the oldest:
  // Dame Philippa's own Handbook, forty years old, nine times through the Doors, and a geode from the Minutes of the
  // Slow Assembly (earth.kyr), older than anything.
  Query crownable() means inFire() and at(party, hour_court) and not crowned(party) and not emberCrowned(fire_land).
  Rule crowned_felt when crowned(party) and not everCrowned(party) { Assert everCrowned(party). Increase talk(party) by 2. }
  Relation fabianLetGo(group).
  Topic fabian_book_ask with fabian travelling "Ask Fabian whether you may show the Hour Court his grandmother's own Handbook" when inFire() and at(party, hour_court) and carries(party, philippa_copy) and knows(actor, old_is_new) and not fabianLetGo(fabian) and not shown(philippa_copy) once {
    Says "He knows what you are going to ask before you ask it; you can see him know. He looks at the brazier, and at the court, and at the red book gone brown in your hands. 'It'll burn,' he says. 'In an hour. Everything here does.' He takes it from you and opens it at the flyleaf, where an old woman has written PHILIPPA MURREY HER BOOK in green ink, and under it, in a child's hand, much later, F. MURREY. He reads it three times, with his lips. 'She'd hate it,' he says. 'Being shown off to the Hour Court like a snowball.' And then he laughs, and it is a real laugh, the first you have heard from him. 'Go on. Show them. I've got it by heart anyway, God help me. I'll write my own.'".
    On discuss { Assert fabianLetGo(fabian). Increase fondness(fabian) by 2. }
  }
  Action show_handbook(actor: group, site: place) "Show the Hour Court Dame Philippa's own Handbook, forty years old" {
    Requires able(actor) and company(actor) and at(actor, site) and crownable() and carries(actor, philippa_copy) and not shown(philippa_copy)
      and (fabianLetGo(fabian) or not travelsWith(fabian, party)).
    Time 1 minute.
    On success { Assert shown(philippa_copy). Spend philippa_kind from actor. Assert crowned(actor). Set reign(fire_land) to 9. Assert bookBurned(party). }
    Result "You hold it up. The court of the ifrit looks at it, and does not understand, and then understands, all at once, the whole court, the way a flock of birds turns. A thing that is forty years old. That has been through the Fire Door nine times, and come back nine times, and not burned. That has someone's writing in it, in green, and someone else's, in pencil, and a flower from another world pressed flat. They come close, burning, and do not touch it. A very old ifrit (perhaps fifty minutes old) begins to weep fire. Then the whole court kneels, and they take the paper crown off the head of the last Monarch and put it on yours, and set the red book on the white fire beside the petal, where it begins, very slowly, at one corner, to burn.".
  }
  Relation bookBurned(group).
  Observe book_burning at hour_court when bookBurned(party) and crowned(party) "On the white fire beside the petal Dame Philippa's Handbook is burning, very slowly, from one corner, page by page, the green ink going up last. The court will not take its eyes off it.".
  Action show_geode(actor: group, site: place) "Show the Hour Court the geode from the Minutes" {
    Requires able(actor) and company(actor) and at(actor, site) and crownable() and holding(actor, geode_kind) and not shown(geode_kind) and reign(fire_land) < 8.
    Time 1 minute.
    On success { Assert shown(geode_kind). Assert crowned(actor). Set reign(fire_land) to 8. }
    Result "You crack it open in your two hands, as Chert showed you, and hold out the halves: a hollow lined with purple crystal, grown slowly, a speck at a time, in the dark, over a length of time the court of the ifrit has no word for. They stare into it. One of them asks how long. You say a million years, which is a guess. The court makes a noise like a forge-bellows breathing in, and sits down, all of it, on the floor of light, and crowns you.".
  }
  Action show_wind(actor: group, site: place) "Show the Hour Court the jar of the North Wind" {
    Requires able(actor) and company(actor) and at(actor, site) and crownable() and holding(actor, north_wind_kind) and not shown(north_wind_kind) and reign(fire_land) < 6.
    Time 1 minute.
    On success { Assert shown(north_wind_kind). Assert crowned(actor). Set reign(fire_land) to 6. }
    Result "You hold up the jar, and the frost on the inside of the glass ferns up in the heat, and does not melt. The court crowds in. Cold, they say to one another, cold, and something that is not anything moving in it, and it does not burn. They put the paper crown on you, gingerly, as if you might freeze it.".
  }
  Action show_mirror(actor: group, site: place) "Show the Hour Court a hand-mirror" {
    Requires able(actor) and company(actor) and at(actor, site) and crownable() and holding(actor, mirror_kind) and not shown(mirror_kind) and reign(fire_land) < 5.
    Time 1 minute.
    On success { Assert shown(mirror_kind). Assert crowned(actor). Set reign(fire_land) to 5. }
    Result "You hold it up to the court, and the nearest ifrit looks into it and sees itself, still. Not flickering. Not changing. Held in the glass the way nothing in the Fire is ever held. It screams, delightedly, and the court comes running to look at itself standing still, and crowns you for it while they jostle.".
  }
  Action show_glass_petal(actor: group, site: place) "Show the Hour Court a glass petal stamped A PRESENT FROM SENNET" {
    Requires able(actor) and company(actor) and at(actor, site) and crownable() and holding(actor, glass_petal_kind) and not shown(glass_petal_kind) and reign(fire_land) < 4.
    Time 1 minute.
    On success { Assert shown(glass_petal_kind). Assert crowned(actor). Set reign(fire_land) to 4. }
    Result "They look at the glass petal, and at the real one on the brazier, and back, and an ifrit turns it over and reads A PRESENT FROM SENNET, and explains to the others what a present is, and what Sennet is, and that this is a thing pretending to be another thing, and will not burn while it does it. The court has never seen a lie that did not burn. They crown you, laughing in great gusts of smoke.".
  }
  Action show_shop_book(actor: group, site: place) "Show the Hour Court a copy of Murrey's Handbook from the shop" {
    Requires able(actor) and company(actor) and at(actor, site) and crownable() and holding(actor, handbook_kind) and not shown(handbook_kind).
    Time 1 minute.
    On success { Assert shown(handbook_kind). }
    Result "They look at it politely. It is new paper, printed last spring. They have seen paper. One of them takes it, and it is ash in their hand before they have opened it, and they blow the ash away, and look past you for something else.".
  }
  Action sing_court(actor: group, site: place) "Sing the Hour Court something nobody has ever sung" {
    Requires able(actor) and company(actor) and at(actor, site) and crownable() and not sangToCourt(actor) and reign(fire_land) < 5.
    Time 1 minute.
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert sangToCourt(actor). Assert crowned(actor). Set reign(fire_land) to 5. }
    On failure { Assert sangToCourt(actor). }
    Result "You make it up as you go: a song about the coast road, and a gull on a bollard, and the bay, in a tune you have never heard either. The court listens. Nobody has sung it before; nobody will sing it again, because nobody will remember it in an hour, and you will not either. While it lasts it is the newest thing in the world. They crown you on the last note.".
    Otherwise "You sing, and halfway through the second verse you hear yourself singing a song you know, a song from home, and so does the court: it has heard that one, an hour ago or a thousand years ago, it does not matter. They turn away.".
  }
  // A player by trade makes something up that the court has never seen, without a roll: a turn, a bit, a trick.
  Action perform_court(actor: group, site: place) "Give the Hour Court a turn of your own devising, as a player does" {
    Requires able(actor) and company(actor) and at(actor, site) and crownable() and craft(actor, craft_stage) and not performed(actor) and reign(fire_land) < 6.
    Time 1 minute.
    On success { Assert performed(actor). Assert crowned(actor). Set reign(fire_land) to 6. }
    Result "You give them a bit you have never done, because you are making it up out of the heat and the faces and the brazier: a Tourist meeting the Fire for the first time, losing an eyebrow, then the other, then their dignity. The court has never seen itself from the outside. It screams. It sits down. It begs for more, and then remembers it has seen that now, and crowns you instead.".
  }
  Relation performed(group).
  // The ember of Cabinet Fourteen, brought home: nobody in the Fire remembers it, and it is new to them; and it is the
  // only thing in the Fire that remembers anything.
  Action ember_home(actor: group, site: place) "Open the warming-pan and set the ember down before the Hour Court" {
    Requires able(actor) and company(actor) and at(actor, site) and inFire() and at(actor, hour_court) and carries(actor, ember) and not emberCrowned(fire_land).
    Time 1 minute.
    On success { Spend ember_kind from actor. Assert emberCrowned(fire_land). Retract crowned(actor). Assert emberHome(fire_land). }
    Result "You open the lid. The ember sits in the pan for a moment, quite still, as if it did not believe it; and then it rolls out onto the floor of light, and flares up as high as your shoulder, white, and the court of the ifrit turns to look at it all at once. They have never seen it. They do not remember it; nobody in the Fire has remembered anything for eighty years. It is the newest thing in the Hour Court. They carry it to the throne. And on the throne it does a thing no Monarch of the Fire has done: it looks across the court at you, and you understand that it knows you, and knows Dr. Cole, and knows the inside of Cabinet Fourteen, and eighty years of a museum, and the next hour, and the one after that. It remembers.".
  }
  Relation emberHome(place).
  Kind hour_ember_kind "an hour-ember" is gear worth 0 weighing 0 granting light described "A coal no bigger than a hazelnut in a cage of copper wire, warm, that gives a steady small light and does not go out, and brightens when it is spoken to.".
  Item hour_ember "an hour-ember" is hour_ember_kind at offstage.
  Relation emberThanked(group).
  Rule ember_thanks at hour_court when emberCrowned(fire_land) and at(party, hour_court) and not emberThanked(party)
    says "The coal on the throne gives off a flurry of sparks, and an ifrit beside it, listening, steps down off the dais and holds out to you, with great care, a petal of red glass from the white fire, and a coal no bigger than a hazelnut in a cage of copper wire. 'The Monarch says,' says the ifrit, frowning, because it has never had to say what a Monarch says twice, 'that it is the next hour now. It says, thank you for the hour. It says, take this, for the light, and this, because it is the only thing it has. It says,' the ifrit stops, baffled, 'remember it.'" {
    Assert emberThanked(party). Give hour_ember to party. }
  Rule ember_gives_petal when emberThanked(party) and not petalTaken(fire_petal) and not rivalHas(fire_petal) and not rectorHas(fire_petal) {
    Give fire_petal to party. Assert petalTaken(fire_petal). }

  // ── What a Monarch may do ─────────────────────────────────────────────────────────────────────────────────────────
  Action decree_petal(actor: group, site: place) "Decree that the Fire petal goes home with the Monarch" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hour_court) and crowned(actor) and not petalTaken(fire_petal) and not rivalHas(fire_petal).
    Time 1 minute.
    On success { Give fire_petal to actor. Assert petalTaken(fire_petal). }
    Result "You stand up off the throne and say so, and the court of the ifrit is enchanted: nobody has ever decreed anything about the petal; it has always just lain there. An ifrit lifts it off the white fire in its bare hands and gives it to you, warm as a cup of tea. 'Decreed,' says the court, all at once, and forgets, and is watching you to see what you will do next.".
  }
  Action decree_cool(actor: group, site: place) "Decree that nothing in the Hour Court shall burn anybody until the bell" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hour_court) and crowned(actor) and not heatSuspended(fire_land).
    Time 1 minute.
    On success { Assert heatSuspended(fire_land). }
    Result "The court looks at you as if you had asked the sea to be dry. Then, because it is a new thing to be asked, it does it: the whole Hour Court goes down to the heat of a warm bath, and stays there, sulkily, every flame in it holding itself in like a breath.".
  }
  Action decree_holiday(actor: group, site: place) "Decree a holiday in the Hour Court, for the rest of the hour" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hour_court) and crowned(actor) and not holidayDecreed(actor).
    Time 1 minute.
    On success { Assert holidayDecreed(actor). Increase talk(actor) by 1. }
    Result "The court has never had a holiday, since it has never had anything but holidays. It is delighted to have a name for it. It dances. You will hear of this dance, later, in places you would not expect.".
  }
  Relation holidayDecreed(group).
  // A Tourist with nothing to show can reach into the white fire, which is not new.
  Action snatch_petal(actor: group, site: place) "Reach into the brazier for the Fire petal while the court is looking the other way" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hour_court) and not crowned(actor) and not petalTaken(fire_petal) and not rivalHas(fire_petal) and not snatched(actor).
    Time 1 minute.
    Resolve check(actor, stealth, dc_hard).
    On success { Assert snatched(actor). Give fire_petal to actor. Assert petalTaken(fire_petal). Assert strikes(heat, actor). }
    On failure { Assert snatched(actor). Assert strikes(heat, actor). Assert strikes(heat, actor). }
    Result "Your hand goes into the white fire and out of it with the petal, and the pain comes after, enormous, and you are walking away across the floor of light holding a petal in a hand that has no feeling in it, and nobody has turned round.".
    Otherwise "The white fire is not the fire of the hall. It goes into your arm to the shoulder. The court turns, and looks at you, and you see it decide that a Tourist with their arm on fire is not new, and turn away again.".
  }
  Relation snatched(group).

  // ── The Lists ─────────────────────────────────────────────────────────────────────────────────────────────────────
  Person salamander "the champion of the Lists" at lists {
    Role "a salamander as long as a horse, in the ring of fire". Species fire_elemental. Level 3. Peaceable. Pronouns it.
    Pleads "The salamander rolls over on its back in the ring and goes dull red, and the court cheers you, a new thing, a Tourist who won.".
  }
  Relation challenged(group).
  Action challenge(actor: group, site: place) "Step into the ring of fire against the champion of the Lists" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lists) and at(salamander, site) and able(salamander) and not challenged(actor).
    Time 1 minute.
    On success { Assert challenged(actor). Retract peaceable(salamander). Assert assails(salamander, actor). }
    Result "The court of the ifrit sees you step over the ring and goes quiet, and then goes mad. A Tourist! In the Lists! The champion turns its long head to you and opens its mouth, and inside it is white.".
  }
  Rule lists_won when challenged(party) and not able(salamander) and not listsWon(party) and not crowned(party) and not emberCrowned(fire_land)
    says "The court carries you out of the Lists and across the floor of light to the Hour Court on its shoulders, burning, and puts the paper crown on your head, because nobody has seen that before." {
    Assert listsWon(party). Assert crowned(party). Set reign(fire_land) to 6. Assert at(party, hour_court). Increase talk(party) by 1. }
  Relation listsWon(group).
}

data/adventures/the-grand-tour/harbour.k:
Module sennet "The Grand Tour" {
  // ── The Quay and the Fish Stairs ──────────────────────────────────────────────────────────────────────────────────
  // The harbour is the city's oldest people: the families who came up out of the lower town on the night it drowned,
  // and stayed by the water, and sell what comes out of it. Nothing here touches the Rose. The harbour has its own
  // troubles: a widow who cannot sleep for a bell; a merfolk child who wants to go shopping; a bylaw.
  // The first sight: the three storeys from the top of the coast road, before anyone in them has said a word.
  Observe coast_scene at coast_road when not visitedBefore(coast_road) "The coast road comes over the last of the downs, and there below you, all at once, is the sea, and a city going down to it in glass. Above the city, over the bay, the cloud lies on the water like a fleece; and standing up out of the cloud, in sunlight, is a hill. It has houses on it, and gardens hanging over its edges, and a chain coming down out of the bottom of it to the city like a plumb-line, as if somebody had lifted the hill up out of the bay by it and forgotten to put it back. Under the bay, where the hill came out, there is nothing to see at all. A milestone at the roadside says SENNET 1, and under it someone has scratched: AND THEN UP, OR DOWN.".
  Observe coast_again at coast_road when visitedBefore(coast_road) "The top of the coast road, with Sennet going down to the sea below you, and Cloudgate standing in the sky over the bay at the top of its chain.".
  Observe landward_scene at landward_gate when not visitedBefore(landward_gate) "The Landward Gate is a gate in no wall: the wall came down a century ago and the gate was kept because the city liked it. Beyond it Sennet goes down to the water in roofs of green copper and glass, glass everywhere, glass-house chimneys smoking, and the bay beyond, very blue. Under everything, so low you feel it in your feet before you hear it, the city hums: that is the chain.".
  Observe landward_again at landward_gate when visitedBefore(landward_gate) "The Landward Gate, and the city going down to the water, and Cloudgate over the bay.".
  Observe market_scene at glass_market when true "The Glass Market: a square of stalls under awnings, and everything on them glass. Glass floats for nets, glass eyes for dolls, glass bottles with the light of the Fire Door still moving in them, sold as night-lights. A crier walks the square with a board on a pole.".
  Observe market_crier at glass_market when openHours() and not doorOpen(sennet_bay) "The crier's board says, in red: THE GRAND TOUR IS PROCLAIMED. Underneath, smaller, in black: PERRIN HALYARD, DOORWARD, FELL 12 DAYS SINCE. LET DOWN ON THE 3RD DAY AT NOON. Someone has chalked beneath both of them: MIND YOUR HEADS." teaches perrin_board.
  Discovery perrin_board "The crier's board in the Glass Market says that Perrin Halyard, a Doorward, fell from Cloudgate twelve days before you came, and will be let down on the third day at noon.".
  Query heardFall() means knows(party, perrin_fell) or knows(party, perrin_board).
  Observe quay_scene at quay when true "The Quay: granite, wet, smelling of weed and tar and frying. Boats tied two deep. Eel barrows, lobster pots, a gull standing on a bollard with the air of having been appointed to it. Looking up from here, Cloudgate is directly overhead, and its underside is rock, brown and hanging, like the bottom of a turnip pulled out of the ground.".
  Observe fish_stairs_scene at fish_stairs when true "The Fish Stairs go down off the end of the Quay into the bay: green granite, worn hollow in the middle, going down and down under the water until the light gives up on them. A brass plate is let into the third step from the bottom of the dry ones: BY ORDER: NO PERSON OF THE SEA ABOVE THIS STEP. MCCXI.".
  Observe taproom_scene at taproom when true "The Sounding Line is low, and dark, and full of fishermen. A sounding-lead the size of a child's head hangs over the bar on its line, and every so often somebody pats it for luck without looking. The window looks straight out across the bay at nothing but water and, above the water, the underside of Cloudgate.".

  // ── The bell under the water ──────────────────────────────────────────────────────────────────────────────────────
  // Lir's church went down with the lower town, and its bell is still in the tower, under the bay. At each turn of the
  // tide, morning and evening, it rings. The harbour says it is the drowned. It is the merfolk children, who think it
  // is the best noise in the world.
  Query tideTurn() means hour(clock) == 6 or hour(clock) == 18.
  Relation bellStopped(place). Relation bellMuffled(place). Relation bellForNed(place). Relation bellRungForNed(place).
  Observe bell_heard at quay as sound when tideTurn() and not bellStopped(sennet_bay) and not bellMuffled(sennet_bay) "Out in the bay, under the water, a bell is ringing: slow, deep, a long way down, as if someone had rung it in a dream. On the Quay nobody looks up, and everybody stops.".
  Observe bell_heard_stairs at fish_stairs as sound when tideTurn() and not bellStopped(sennet_bay) and not bellMuffled(sennet_bay) "Under your feet, under the stairs, under the water, a bell rings: slow, and deep, and very far down.".
  Observe bell_heard_line at taproom as sound when tideTurn() and not bellStopped(sennet_bay) and not bellMuffled(sennet_bay) "Through the window, out of the bay, a bell rings under the water. The fishermen at the bar stop talking until it has done.".

  // ── Old Bethan ────────────────────────────────────────────────────────────────────────────────────────────────────
  Kind eel_basket_kind "a basket of live eels" is gear worth 2 weighing 2 described "A wicker creel of live eels under a wet sack, heavy and moving, from Old Bethan's barrow. Eels are what the harbour lives on, and what lives on the harbour.".
  Person bethan "Old Bethan" at quay {
    Role "an eel-wife, at a barrow of live eels" when not bethanAtPeace(bethan).
    Role "an eel-wife, who has slept" when bethanAtPeace(bethan).
    Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Sells rations for 1 coin from 6.
    Sells eel_basket_kind for 2 coin from 4.
    Greets "A small old woman in three shawls looks up from a barrow of live eels, and looks at your boots, and says: 'Eel pie. A penny. You'll not get better in Sennet and you'll get worse up there.' She jerks her head at the sky without looking at it.".
    Greets again "'Eel pie,' says Old Bethan, which is how she says good morning, and then, because she has had time to think: 'There's a boy been asking after you up the steps. Ate two. Didn't pay for either. I said you'd settle.'".
  }
  Relation bethanAtPeace(group). Relation bethanFriend(group).
  Rule bethan_quay when hour(clock) >= 8 and hour(clock) < 18 and not at(bethan, quay) { Assert at(bethan, quay). }
  Rule bethan_eve when isaEve() and not at(bethan, quay) { Assert at(bethan, quay). }
  Rule bethan_line when hour(clock) >= 18 and hour(clock) < 22 and not isaEve() and not bellForNed(sennet_bay) and not at(bethan, taproom) { Assert at(bethan, taproom). }
