  "roles": {
    "mouth": { "lit": true, "names": ["the doorway"], "scenes": ["A square doorway is cut in the hillside, its jambs and lintel single blocks of limestone fitted so close a knife would not go between them."] },
    "gate_hall": { "names": ["the gate-hall"], "scenes": ["A hall of dressed limestone, its floor channelled: a channel for each spring, each with a bronze slot where a gate stood. The mouth of a great pipe of lead opens in one wall, dark, breathing cold air."] },
    "race_head": { "names": ["the master sluice"], "scenes": ["The springs come together here in a basin of stone, and leave it by two ways: a channel that runs off to the doorway and the hillside, and a race that goes down into the dark. A bronze gate as tall as a house stands where the two divide."] },
    "store": { "names": ["the wardens' store"], "scenes": ["Shelves of stone, and on them the Wardens' tools in rows: rods and gauges of bronze, a coil of lead pipe, wax for the gates, all of it set down as if someone meant to be back in the morning."] },
    "still_room": { "names": ["the reading-room"], "scenes": ["A round room with a shallow basin in its floor, full of water so still it is hard to see where the stone stops. Benches go round the wall, facing it, as if people sat here to watch the water."] },
    "vent": { "names": ["the overflow"], "scenes": ["A culvert where the water once ran off when the cisterns were full: a low tunnel of fitted stone, floored with silt, that goes up and out toward a grey light."] },
    "stair_head": { "names": ["the head of the stair"], "scenes": ["The hall narrows to a stair going down between two slots cut deep in the walls, where a gate runs, and beside the stair stands a wheel of bronze as tall as a man."] },
    "stair_foot": { "names": ["the foot of the stair"], "scenes": ["The stair comes down onto a stone walkway along the side of a cistern: black water a hand below the walkway's edge, and pillars standing up out of it into the dark, in rows."] },
    "colonnade": { "names": ["the colonnade"], "scenes": ["A forest of pillars stands in the water, carved at the top like the heads of reeds, and walkways run between them a hand above the surface. Your light goes off across the water and does not reach the other side."] },
    "pipe_gallery": { "names": ["the pipe gallery"], "scenes": ["A gallery where the pipes of lead run along both walls in bundles as thick as a man, each stamped with the Wardens' mark and a number, going away into the hill to places with names nobody knows now."] },
    "wardens_hall": { "names": ["the wardens' hall"], "scenes": ["A dry hall over the cisterns, with a hearth and stone benches, where the Wardens on watch slept and ate. A chart of the springs is cut in the wall, every spring a circle, every gate a line across a channel."] },
    "pump": { "names": ["the great wheel"], "scenes": ["A wheel as tall as two houses stands in a pit, with a race in the rock above to bring water down onto its paddles, and pump-rods of bronze running from its axle down into the deep cistern below."] },
    "cell": { "names": ["a warden's cell"], "scenes": ["A cell with a stone bed and a stone shelf, and on the shelf a little dish worn smooth with use, for still water to be read in alone."] },
    "deep_gate": { "names": ["the end of the gallery"], "scenes": ["The gallery ends at a gate: two posts of limestone and a lintel cut with the Wardens' mark, round a black opening, and the sound of a great deal of water standing very still beyond it."] },
    "landing": { "names": ["the landing"], "scenes": ["A landing of stone at the top of a flight of steps that goes down into the deep cistern, and a pillar beside it with marks cut every hand's breadth, where the Wardens read how full it was."] },
    "drowned_hall": { "names": ["the drowned hall"], "scenes": ["A hall of the deep cistern where the water stood longest: its pillars are furred with lime, and the floor is a crust of white, and the walkways have fallen in places."] },
    "vault": { "names": ["the wardens' vault"], "scenes": ["A vault off the drowned hall, its door of bronze sealed with wax that has kept the water out: inside, shelves, and on them what the Wardens kept dry."] },
    "archive": { "names": ["the archive"], "scenes": ["A room of stone shelves above the waterline, where the Wardens kept their reckoning of the springs, year by year, cut in tablets of slate. At the back the floor drops away in steps cut down the cistern's wall."] },
    "shore": { "names": ["the shore"], "scenes": ["At the bottom of the steps there is a shore, a strip of white stone along water that does not move at all: not a ripple, not a drip, though water runs everywhere above."] },
    "heart": { "names": ["the still water"], "scenes": ["A pool as wide as a hall lies under the hill, perfectly still, and your light does not go into it but lies on top of it. In the middle of the pool, on a pillar a hand under the surface, there is something that glints."] },
    "source": { "names": ["the source"], "scenes": ["Behind the pool the rock opens on a crack where the water comes up from somewhere much deeper, silently, without a sound or a ripple. The air in the crack is warm."] }
