  "type": "=defined('type') ? #type : lookup(gems, #rank)",
  "quality": "=lookup(gemQuality, any)",
  "cut": "=lookup(gemCut, any)",
  "size": "=lookup(gemSize, any)"
 }
}

data/generation/town/companions.json:
{
 "about": "The companions of the first town and what each asks of the company, for bond.kyrt (src/world/region-bonds.ts): the questions are the companion's own, said unprompted when their condition holds; each has three answers, each answer a trait shown (candour, mercy, thrift) and regard gained; a paragon quest at a place, open at regard three, ends in a keepsake that grants a capability.",
 "companions": [
  {
   "id": "{t}_manor_keeper",
   "name": "Wystan Hale",
   "capability": "woodcraft",
   "rankup": "Wystan Hale walks a little way ahead for a while, and when he drops back he does not say why, only: 'I have decided you are people I should be ashamed to lie to. I did not expect that.'",
   "howtext": "'Like being let off a chain,' says Wystan Hale, 'and finding I had forgotten the use of my legs.' He thinks. 'You ask me what I think, which my sergeant never did. I find I am thinking it.'",
   "questions": [
    {
     "when": "knows(party, {t}_roadwood_grant)",
     "ask": "Wystan Hale falls into step beside you. 'A thing, if I may. You have read the paper. The family kept it shut for forty years and I stood at their chain for seven. If you had found it and nobody had asked you, would you have said so? Or let the chain stand, and the quarrel with it, because it was not yours?'",
     "answers": [
      {
       "label": "'I should have said so at once, and let them be angry.'",
       "says": "'Hm,' says Wystan Hale. 'That is how my corporal would have said it. It cost him his place.' He nods slowly. 'I would rather be told the truth by a man who knows what it costs.'",
       "trait": "candour",
       "regard": 2
      },
      {
       "label": "'I should have told the reeve and let him decide what to do with it.'",
       "says": "Wystan Hale considers this. 'Kind,' he says. 'And it puts the weight on the one who has least to carry it with. But kind.'",
       "trait": "mercy",
       "regard": 1
      },
      {
       "label": "'I should have kept it until it was worth something.'",
       "says": "Wystan Hale does not say anything for a while. 'That is honest,' he says at last, in the voice of a man putting a hand on a hot kettle to see. 'I wish it were not.'",
       "trait": "thrift",
       "regard": 0
      }
     ]
    },
    {
     "when": "at(party, {t}_green) and {t}_roadwood_shared(party)",
     "ask": "Wystan Hale stops at the well-curb. 'I have not spoken to Aldous Fenn in six years about anything but oak. He will be at the sheds. What would you say to him, if you were me? I find I want an answer more than I want to go.'",
     "answers": [
      {
       "label": "'Tell him the plain truth: you stood at the chain because you were told to, and you were wrong to.'",
       "says": "'Wrong to,' says Wystan Hale, trying it. 'Yes.' He straightens. 'I am going to say that. And then I am going to buy him a drink.'",
       "trait": "candour",
       "regard": 2
      },
      {
       "label": "'Say nothing. Stand beside him until he speaks.'",
       "says": "Wystan Hale lets out a long breath. 'My corporal did that,' he says. 'It always worked. It was like being forgiven by weather.'",
       "trait": "mercy",
       "regard": 2
      },
      {
       "label": "'Offer him the wardens' oak, now the chain is down. He will talk about that.'",
       "says": "'He will,' says Wystan Hale, and smiles for the first time in the telling. 'It is not the same as saying sorry. But it is a good second.'",
       "trait": "thrift",
       "regard": 1
      }
     ]
    },
    {
     "when": "at(party, {t}_stones_tree)",
     "ask": "Wystan Hale touches a rag on the old tree. 'My corporal's mother tied one here the day he left for the castellan's company. She told him if he came back he was to take it down himself. He did not come back. Aldous's father was my corporal, I think I said. I do not know what to do about the rag.'",
     "answers": [
      {
       "label": "'Tie another beside it. Leave the first. Let it be a company.'",
       "says": "'A company,' says Wystan Hale. 'Yes. That is more than he ever had.'",
       "trait": "mercy",
       "regard": 2
      },
      {
       "label": "'Take it down. A promise is a promise, and she made it.'",
       "says": "Wystan Hale goes still, then nods once, as at an order. 'She would have wanted that,' he says. 'I am not sure I do.'",
       "trait": "candour",
       "regard": 1
      },
      {
       "label": "'Leave it. It is not ours to settle.'",
       "says": "'No,' says Wystan Hale. He sounds almost relieved. 'No. It is not.'",
       "trait": "thrift",
       "regard": 1
      }
     ]
    }
   ],
   "appraise": {
    "candour": "'You say what you think and you pay for it,' says Wystan Hale. 'I knew men like that. They were not easy to serve under, and I would have followed any of them into a ditch.'",
    "mercy": "'You think first of what it does to the one who has least,' says Wystan Hale. 'It will get you killed one day. I should like to be there to see it does not.'",
    "thrift": "'You count,' says Wystan Hale. 'Always the cost, always the use. I used to think that was cold. I stood at a chain for seven years because someone counted a different sum from mine. I begin to see its use.'"
   },
   "paragon": {
    "place": "{t}_stones_tree",
    "label": "Tie a rag on the old tree beside the corporal's, with Wystan Hale",
    "says": "Wystan Hale takes a strip of grey cloth from his coat, which he has evidently carried for a long time, and ties it beside an older one gone white with weather. He stands a while with his hand on the knot. 'There,' he says. 'Corporal Fenn. I have stood at the wrong chain. I would like you to have known that I knew.' He turns to you. 'I have a whistle of his that he gave me when I was nineteen. It was for calling the line in a wood. It will call the line for you. I have never given it to anyone.'",
    "giftname": "the corporal's whistle",
    "giftdesc": "A boxwood whistle on a thong, worn pale where a thumb goes, that calls a scattered line together in a wood. It knows the trees as a corporal knew them, which is by their sound.",
    "effect": "",
    "after": "On the old tree two strips of cloth hang side by side, a grey one still dark with its dye and a white one gone to thread."
   }
  },
  {
   "id": "{t}_iv",
   "name": "Isaure Venn",
   "capability": "lore",
   "rankup": "Isaure Venn stops, in the middle of a sentence about an inscription, and says without looking up: 'I have started to read your face the way I read stone. Please do not take it as an insult. It is the highest thing I know how to do.'",
   "howtext": "'Like being a footnote,' says Isaure Venn, 'in a book that is finally being *written*. I have copied things for years that nobody has done anything with. You *do* things. It is rather alarming and I do not wish it to stop.'",
   "questions": [
    {
     "when": "at(party, {t}_stones_hall)",
     "ask": "Isaure Venn looks up at the dais and not at you. 'May I ask something of the sort one should not? If the stone told us the hall was a place of judgement, and the stone were wrong, and the folk had spent four hundred years leaving offerings to the *wrong thing*, would you tell them?'",
     "answers": [
      {
       "label": "'Yes. They have a right to know what they are doing.'",
       "says": "'Yes,' says Isaure Venn, and lets out a breath. 'Yes. I thought you would, and I was afraid you would, and I am glad.'",
       "trait": "candour",
       "regard": 2
      },
      {
       "label": "'Not unless it hurt them. A custom can be wrong and kind.'",
       "says": "'Kind,' says Isaure Venn, turning the word over. 'A good scholar would say a wrong thing kept alive is an error preserved. But I have eaten the bread of a custom, so I will not say it.'",
       "trait": "mercy",
       "regard": 1
      },
      {
       "label": "'Depends who is paying for the truth.'",
       "says": "Isaure Venn laughs, not unkindly. 'You are the first person who has said that aloud. Everyone else thought it.'",
       "trait": "thrift",
       "regard": 0
      }
     ]
    },
    {
     "when": "{t}_roadwood_shared(party)",
     "ask": "Isaure Venn catches up with you at the end of a lane. 'I must ask. You settled the quarrel by reading a paper. If the paper had said the Hall was right, and the wardens would have lost their living, would you have shown it to the reeve?'",
     "answers": [
      {
       "label": "'Yes. The paper does not know who is poor.'",
       "says": "'The paper does not know,' says Isaure Venn. 'I am going to write that down. May I? I shall not say it is yours.'",
       "trait": "candour",
       "regard": 2
      },
      {
       "label": "'I should have found some way to soften it first.'",
       "says": "'Soften,' says Isaure Venn, with care. 'It is a verb scholars use for ink. I had not thought of using it for people.'",
       "trait": "mercy",
       "regard": 2
      },
      {
       "label": "'No. I should have kept it, and taken a fee for not showing it.'",
       "says": "Isaure Venn's pen stops. 'I see,' she says. 'I think that is very likely what most people with papers do. I have been very naive about that, and I thank you for the lesson.'",
       "trait": "thrift",
       "regard": 0
      }
     ]
    },
    {
     "when": "knows(party, {t}_boy_tune)",
     "ask": "Isaure Venn waits until you are quite alone with her. 'Can I tell you why I came? Not the paper. My teacher had four notes in his notebook, with no word beside. He died last winter. If it turns out they are the chime, and what the chime means is something that would unmake what he spent his life on, would you want me to tell you?'",
     "answers": [
      {
       "label": "'Tell me. All of it. I would rather be unmade by the truth.'",
       "says": "'Unmade by the truth,' says Isaure Venn. 'I am going to remember you said that when I am frightened.'",
       "trait": "candour",
       "regard": 2
      },
      {
       "label": "'Tell me what you can bear, and we will decide the rest together.'",
       "says": "Her face does something complicated. 'Together,' she says. 'Yes.'",
       "trait": "mercy",
       "regard": 2
      },
      {
       "label": "'Tell me what it is worth first.'",
       "says": "'Honest,' says Isaure Venn, after a moment, and laughs. 'And fair. Truth is worth what the person who needs it will pay.' She does not seem to mind.'",
       "trait": "thrift",
       "regard": 1
      }
     ]
    }
   ],
   "appraise": {
    "candour": "'You want the thing as it is,' says Isaure Venn. 'It makes you a hard travelling companion for someone who likes a theory. I hope you never change.'",
    "mercy": "'You keep wondering who it will hurt,' says Isaure Venn. 'I had thought that was a failing in a person who wants the truth. I am revising the opinion.'",
    "thrift": "'You ask what everything is *for*,' says Isaure Venn. 'It irritates me and it is perfectly right: the Empire asked the same, and look what it left us.'"
   },
   "paragon": {
    "place": "{t}_stones_hall",
    "label": "Read the scored-out word on the dais with Isaure Venn",
    "says": "Isaure Venn climbs the dais at last, and kneels with her cheek almost to the stone, and reads aloud in the flat voice of a clerk reading a deed. 'There,' she says. 'The first makers' letters, and over them, scored through hard, an Aenean word: IUDICIUM. Judgement. A surveyor's hand, a later one. The Empire did not find a judgement-hall. It *named* it one. And the figures are not holding scales.' She sits back on her heels. 'They are holding rods. Something to be measured against. I do not know what. But the people who came after wrote over what they could not read, and everyone since has read the wrong thing.' She is crying a little and does not seem to mind. 'I want you to have my primer. It will not teach you to read the old script, but it will teach you to doubt it properly, which is better.'",
    "giftname": "Isaure's primer",
    "giftdesc": "A thumbed paper primer of the old script's commonest words, in a young scholar's hand, with the margins full of doubts. It teaches the habit of reading the stone before the label on it.",
    "effect": "Assert knows(actor, {t}_rubbed_word).",
    "after": "Chalked under the dais, in a small, quick hand: THE LABEL IS NOT THE STONE. I.V."
   }
  },
  {
   "id": "{t}_anselm",
   "name": "Brother Anselm Tarr",
   "capability": "insight",
   "rankup": "Brother Anselm Tarr has been quiet for a mile. 'I said my office this morning,' he says at last, 'and found I had said it *at* you. As a witness. I do not know if I am permitted that. I find that I do not mind.'",
   "howtext": "'Like a doubt with legs,' says Brother Anselm Tarr, with the nearest thing to a smile you have seen on him. 'My master says a priest should not travel except to a pulpit. You are all my pulpit. I shall be very bad at it.'",
   "questions": [
    {
     "when": "state({t}_stones_niche, restored)",
     "ask": "Brother Anselm Tarr looks at the cup in its dust, and not at you. 'May I ask a thing? You put it back. If the cup had been worth a hundred coin to a collector, and the dead had not been watching, and there were a family to feed in the town: would you have put it back?'",
     "answers": [
      {
       "label": "'Yes. The dead are watching even when they are not.'",
       "says": "'Even when they are not,' says Brother Anselm Tarr. 'There is a text on that. It is not very good. You have said it better.'",
       "trait": "candour",
       "regard": 2
      },
      {
       "label": "'I should have wanted to, and I do not know that I should have.'",
       "says": "He looks at you for a long time. 'Thank you,' he says. 'That is the first honest thing anyone has said to me about faith.'",
       "trait": "mercy",
       "regard": 2
      },
      {
       "label": "'No. The living come first.'",
       "says": "'Yes,' says Brother Anselm Tarr, very quietly. 'I thought you might say so. I will not tell you that you are wrong, because I am not sure.'",
       "trait": "thrift",
       "regard": 0
      }
     ]
    },
    {
     "when": "{t}_death_told(party) or {t}_fenn_truth(party)",
     "ask": "Brother Anselm Tarr stops you by the shrine door. 'You told someone a thing, lately, about a death or a father. I do not ask what. I ask this: when you decide what to tell the grieving, how do you decide?'",
     "answers": [
      {
       "label": "'By what they would want to know, if they could see it all.'",
       "says": "'If they could see it all,' says Brother Anselm Tarr. 'That is God's view, and not a bad rule for a man to borrow for an afternoon.'",
       "trait": "candour",
       "regard": 2
      },
      {
       "label": "'By what they can carry.'",
       "says": "'Yes,' says Brother Anselm Tarr, and for a moment he is very young. 'That is what the priest does for forty years. I am surprised to hear it from someone who is not one.'",
       "trait": "mercy",
       "regard": 2
      },
      {
       "label": "'By what it will cost me.'",
       "says": "He is silent. 'It is a fair answer,' he says. 'It is how most of us decide, and it is a good deal more honest than the ones with a lantern on the cover.'",
       "trait": "thrift",
       "regard": 0
      }
     ]
    },
    {
     "when": "at(party, {t}_stones_under)",
     "ask": "Brother Anselm Tarr speaks very low, in the niches' dark. 'If I find, after all this, that what the coins are is nothing: manners, habit, a long forgetting. Will you think less of me for having asked so loudly?'",
     "answers": [
      {
       "label": "'No. A question you do not ask is a vow you have not taken.'",
       "says": "'Not taken,' says Brother Anselm Tarr, as if tasting it. 'I shall use that. I shall not say whose it is.'",
       "trait": "candour",
       "regard": 2
      },
      {
       "label": "'I should think more of you. It is brave.'",
       "says": "He laughs, once, painfully. 'Brave. I have never been called brave. I have been called difficult.'",
       "trait": "mercy",
       "regard": 2
      },
      {
       "label": "'I should think it a waste of a good lamp.'",
       "says": "'It might be,' says Brother Anselm Tarr. 'Thank you for the practicality. It is a form of respect.'",
       "trait": "thrift",
       "regard": 1
      }
     ]
    }
   ],
   "appraise": {
    "candour": "'You speak plainly even where plain speech is a risk,' says Brother Anselm Tarr. 'It is not a virtue the house teaches. I should like to know where you learned it.'",
    "mercy": "'You are gentle,' says Brother Anselm Tarr, 'at some cost, I think. I have seen that in saints. I have also seen it in people who were afraid. I cannot tell which you are. I do not think it matters.'",
    "thrift": "'You count the cost,' says Brother Anselm Tarr. 'The house calls that worldliness. The house has not walked three days to find out whether a coin is idolatry. I am not sure the house is right.'"
   },
   "paragon": {
    "place": "{t}_stones_under",
    "label": "Keep a vigil in the undercroft with Brother Anselm Tarr",
    "says": "Brother Anselm Tarr kneels at the foot of the niches and does not pray, quite; he sits with his hands open in his lap and lets the dark do what it will. You sit beside him a long time. Somewhere in the stone the chime stirs and does not ring. 'There,' he says at length, very softly. 'That is the thing I could not find in the books. It does not ask. The dead do not ask for anything. They are only *kept*.' He wipes his face, unashamed. 'The faith says the dead are in the god's keeping. I think it is simpler than that, and I think the god would not mind. Whoever keeps them, keeps them. I have decided to be a person who keeps things.' He takes a small grey lamp from his cloak. 'It was my first. It burns whether or not anyone is looking. Have it.'",
    "giftname": "the acolyte's grey lamp",
    "giftdesc": "A small grey tin lamp, trimmed with care, that burns steadily with a light that lets you see what a person means as well as what they say. Brother Anselm Tarr carried it for ten years and never once let it go out.",
    "effect": "",
    "after": "A grey lamp burns, trimmed and steady, on the ledge of the lowest niche: the only light in the undercroft that has not been brought in by someone."
   }
  }
 ]
}

data/goings-on/circus/act4.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── Act IV: the crate, the hatchlings, the Sundial, and what comes home ───────────────────────────────────────
  // After the Revels. A crate comes for the Keeper of the Menagerie Royal, which the Colonel signed himself, whatever the Revels made of him, because he wrote a
  // letter in the first week of whatever the Revels made of him, to the one address in the Keepers' Book he had not tried. The eggs in
  // it hatch within a day. What the company does with a clutch of frightened, clever animals decides how the town
  // takes it; what they are decides where the Colonel goes next; and where he goes next is a place his Keepership
  // should have been about from the beginning.
  Relation crateCome(concern). Relation crateOpened(concern). Relation eggsKept(concern). Relation eggsHatched(concern).
  Relation hatchlingsLoose(concern). Relation hatchlingsPenned(concern). Relation fenwickShown(concern).
  Relation voyageReady(concern). Relation voyaged(concern). Relation backFromSarn(concern).
  Relation wapshottAboard(concern). Relation billieAboard(concern). Relation mumchanceAboard(concern).
  Relation trumpetPending(concern). Relation trumpetDone(concern). Relation colonelStopped(concern). Relation herdScattered(concern).
  Relation takeLeave(concern). Relation takeEgg(concern). Relation takeSpecimens(concern). Relation billieResigned(concern).
  Relation fenwickDispleased(concern). Relation colonelAwed(concern). Relation ruleRead(concern).
  Measure crateDay(concern). Measure hatchLosses(concern). Measure trumpetAt(concern).

  Person crewe "Tobiah Crewe" at tober_a {
    Role "mate of the brig Sundial, lately her master". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "A thin, weathered man in a salt-stiff coat stands in the yard with his hat in both hands, reading the names on the wagons. 'Crewe,' he says. 'Tobiah. Mate of the Sundial, brig, out of Port Dree. Master, now.' He turns the hat. 'I've a crate for a Colonel Wapshott, who wrote to Port Dree and signed himself Keeper of the Menagerie Royal. I was told to give it into his hand and no other. I've been looking for his hand a month.'".
  }
  Initially Assert offstage(crewe).
  Topic crewe_who with crewe "Ask Mate Crewe who sent the crate" when true {
    Says "'Captain Vance, that was master,' says Crewe. 'He took a letter at Port Dree six months ago, from a Colonel Wapshott, Keeper of something. He'd been to the Preserve once as a boy. He went back for it. He took fever on the way home, off the Cape, and left me the crate, and this.' He gives you a salt-stained paper. 'I'm to say: the last clutch. I don't know what that means.'".
    On discuss { Assert knows(actor, crate_known). }
  }
  Topic crewe_ship with crewe "Ask Mate Crewe where the Sundial lies" when knows(actor, crate_known) {
    Says "'At the quay in the fair town, with half her crew in the taverns,' says Crewe. 'She's sound. She'll go south to Sarn for anyone who'll pay her master's wages and her bond. It's eleven days, wind or no wind.' He looks at the crate. 'It's an island nobody's been to since I was a lad. Vance said it was full.'".
    On discuss { Assert knows(actor, ship_known). }
  }
  Entity crate_known: fact "A crate has come for Colonel Wapshott, who signed himself Keeper of the Menagerie Royal from the late Captain Vance of the brig Sundial, with a paper that says: the last clutch.".
  Entity ship_known: fact "The brig Sundial lies at the quay in the fair town, her master Tobiah Crewe, and will go south to the Isle of Sarn for anyone who pays her bond.".
  Entity eggs_known: fact "The crate holds a clutch of grey eggs, the size of loaves, packed in sawdust and warm.".
  Entity sarn_known: fact "The crate came from the Isle of Sarn, which the Keepers' Book names in the margin of the Southern Preserve, and where the Progress once kept its beasts.".

  Thing sea_crate "the sea-captain's crate" at tober_a is scenery {
    State sealed "A sea-captain's crate stands in the wagon-yard, as long as a coffin, with SARN burnt into the lid and a crowned wheel burnt under it. It is warm to the hand.".
    State opened "The lid of the crate has been prised off. A bed of sawdust, still warm, and in it a ring of grey eggs, loaf-big.".
    State hatched "The crate lies in splinters in the yard, and the sawdust has been scraped into nests by small feet.".
  }
  Initially Assert offstage(sea_crate). Initially Assert state(sea_crate, sealed).
  Rule crate_comes when revelsDone(wapshotts) and pitched(wapshotts) and day(clock) >= revelsDay(wapshotts) + 2 and hour(clock) >= 10 and not crateCome(wapshotts)
    and current(wapshotts, ?g) and groundRoom(?g, rk_yard, ?r) {
    Assert crateCome(wapshotts). Retract offstage(sea_crate). Retract offstage(crewe). Assert at(sea_crate, ?r). Assert at(crewe, ?r).
    Assert travels(sea_crate). Assert post(sea_crate, rk_yard). Set crateDay(wapshotts) to day(clock). }
  Rule fenwick_returns when crateCome(wapshotts) and offstage(fenwick) and not backFromSarn(wapshotts) and day(clock) >= crateDay(wapshotts) { Retract offstage(fenwick). Assert travels(fenwick). Assert post(fenwick, rk_tober). Assert fenwickCome(fenwick). }
  Rule crewe_stays when crateCome(wapshotts) and not voyaged(wapshotts) and current(wapshotts, ?g) and groundRoom(?g, rk_yard, ?r) and not at(crewe, ?r) and not away(crewe) { Assert at(crewe, ?r). }
  Observe crate_scene near sea_crate when state(sea_crate, sealed) "A sea-captain's crate is in the yard, burnt with SARN and a crowned wheel, and the wagon-hands are keeping a yard away from it.".

  Action open_crate(actor: group, site: place) "Prise up the lid of the crate" {
    Requires able(actor) and company(actor) and at(actor, site) and at(sea_crate, site) and state(sea_crate, sealed) and not crateOpened(wapshotts).
    Time 3.
    On success { Assert crateOpened(wapshotts). Assert state(sea_crate, opened). }
    Result "The lid comes up with a shriek of nails and a breath of warm air that smells of eggs and the sea. In the sawdust, in a ring, eleven loaf-big grey eggs lie in a ring like a clutch of stones. One of them rocks, a little, as you watch.".
  }
  Observe eggs_taught near sea_crate when state(sea_crate, opened) "Eleven eggs lie in the sawdust, warm. One rocks." teaches eggs_known.

  // The Colonel on seeing it: the first mistake is made with love.
  Topic wap_crate with wapshott "Show the Colonel what the crate holds" when knows(actor, eggs_known) and not colonelAwed(wapshotts) once {
    Says "The Colonel goes down on one knee in the yard. He puts a hand on an egg, flat, as a physician does on a chest. 'Warm,' he says. 'Warm! Do you know what this is?' It is not a question. 'It is the Keepership. It is what it was FOR.' He gets up. His moustache is trembling, and Ada, from the ticket wagon, has put down her pen. 'We shall hatch them,' he says. 'We shall hatch them in the ring.'".
    On discuss { Assert colonelAwed(wapshotts). Assert wapshottKeen(wapshotts). }
  }
  Relation wapshottKeen(concern).
  Topic billie_eggs with billie "Ask Billie what to do with the eggs" when knows(actor, eggs_known) {
    Says "'Keep them warm and keep them quiet and keep him out of it,' says Billie. 'A clutch hatches in a dark nest, not in a ring. Honoria's oven, the cool end, with a damp cloth. Or I'll do it under a lamp in the straw, if you'll shift the wagon.' She looks at the eggs with an expression you have not seen on her. 'They'll be wild, whatever we do. Don't let him name them.'".
  }
  Action warm_oven(actor: group, site: place) "Ask Honoria to put the eggs in the cool end of her oven" {
    Speaker honoria.
    Requires able(actor) and company(actor) and at(actor, site) and at(honoria, site) and crateOpened(wapshotts) and not eggsKept(wapshotts) and not eggsHatched(wapshotts).
    Time 1.
    On success { Assert eggsKept(wapshotts). Increase regard(honoria) by 1. }
    Result "Honoria looks at the eggs, and at you, and takes off her apron and wraps the first in it. 'They'll want turning,' she says. 'Like a loaf.' She carries them to the oven one by one, as if they were the Archbishop.".
  }
  Action warm_lamp(actor: group, site: place) "Ask Billie to make them a nest under a lamp" {
    Speaker billie.
    Requires able(actor) and company(actor) and at(actor, site) and at(billie, site) and crateOpened(wapshotts) and not eggsKept(wapshotts) and not eggsHatched(wapshotts) and regard(billie) >= 1.
    Time 1.
    On success { Assert eggsKept(wapshotts). Increase regard(billie) by 1. }
    Result "Billie says nothing at all. She makes a nest of the clean straw in the corner of the beast tent, lined with her own coat, and moves a lamp until it is exactly right, and stands over it with her arms folded. Nobody else is to come in.".
  }

  // They hatch in the night of the day they come (or the day after).
  Person hatchlings "the hatchlings" at tober_a {
    Role "eleven young hook-claws, an hour out of the egg". Species hook_claw. Variant young. Numbers 5. Level 1. Temperament wary.
    Warns "A small barred head comes up from behind a wagon wheel, and looks, and does not run. Not yet.".
    Flinches "The nearest hatchling bolts under the wagons with its tail straight out.".
  }
  Initially Assert offstage(hatchlings).
  Rule hatch_kept when crateCome(wapshotts) and eggsKept(wapshotts) and not eggsHatched(wapshotts) and hour(clock) >= 22 and day(clock) >= crateDay(wapshotts)
    and current(wapshotts, ?g) and groundRoom(?g, rk_beasts, ?b) {
    Assert eggsHatched(wapshotts). Assert hatchlingsPenned(wapshotts). Retract offstage(hatchlings). Assert at(hatchlings, ?b). Assert state(sea_crate, hatched). Assert peaceable(hatchlings). Assert travels(hatchlings). Assert post(hatchlings, rk_beasts). }
  Observe hatched_kept near hatchlings when hatchlingsPenned(wapshotts) "Eleven hook-claws kitten-small are asleep in a heap in a nest of straw, with Billie's coat under them. One is awake. It looks at you with the whole of its face and says nothing, as a creature does that has not yet found out about being looked at.".
  Rule hatch_loose when crateCome(wapshotts) and not eggsKept(wapshotts) and not eggsHatched(wapshotts) and hour(clock) >= 22 and day(clock) >= crateDay(wapshotts)
    and current(wapshotts, ?g) and greenOf(?g, ?n) {
    Assert eggsHatched(wapshotts). Assert hatchlingsLoose(wapshotts). Retract offstage(hatchlings). Assert at(hatchlings, ?n). Assert state(sea_crate, hatched). }
  Observe hatched_loose near hatchlings when hatchlingsLoose(wapshotts) "On the green, in the grey, the hatchlings are everywhere: on the horse-trough, in the gutters, on the stocks, one inside the pump. They are kitten-small and have a hooked claw on each foot. The geese are making a noise you would not have thought geese could.".

  // In town: three ways to get them back, none of them a fight.
  Action coax_meat(actor: group, site: place) "Lay a trail of meat from the green to the beast tent" {
    Requires able(actor) and company(actor) and at(actor, site) and at(hatchlings, site) and hatchlingsLoose(wapshotts) and quantity(actor, rations) >= 1.
    Time 1.
    On success { Decrease quantity(actor, rations) by 1. Retract hatchlingsLoose(wapshotts). Assert hatchlingsPenned(wapshotts). Assert peaceable(hatchlings). Assert travels(hatchlings). Assert post(hatchlings, rk_beasts). }
    Result "They come in ones and twos, with their heads low and their tails out, tearing at the bait and looking over their shoulders, and after the last of it there is a pen and an open gate, and Billie shutting it.".
  }
  Action coax_stillness(actor: group, site: place) "Sit down in the middle of the green and be a tree" {
    Requires able(actor) and company(actor) and at(actor, site) and at(hatchlings, site) and hatchlingsLoose(wapshotts).
    Time 3.
    Resolve check(actor, stealth, dc_fair).
    On success { Retract hatchlingsLoose(wapshotts). Assert hatchlingsPenned(wapshotts). Assert peaceable(hatchlings). Assert travels(hatchlings). Assert post(hatchlings, rk_beasts). }
    Result "You sit. You are still for a long time. A small barred animal climbs on to your knee, looks into your face, and lies down on your boot. Then the rest come, as if you had been a trough. At the end of it Billie takes them one at a time from you into a sack, with an expression of faint professional jealousy.".
    Otherwise "You sit down on the horse-trough and they all watch you do it. When you reach for the nearest, it takes a piece out of your thumb and runs up the pump.".
  }
  Action coax_billie(actor: group, site: place) "Ask Billie to bring them in" {
    Speaker billie.
    Requires able(actor) and company(actor) and at(actor, site) and at(hatchlings, site) and hatchlingsLoose(wapshotts) and regard(billie) >= 2.
    Time 2.
    On success { Retract hatchlingsLoose(wapshotts). Assert hatchlingsPenned(wapshotts). Assert peaceable(hatchlings). Assert travels(hatchlings). Assert post(hatchlings, rk_beasts). Increase regard(billie) by 1. }
    Result "Billie comes down the green with a sack and a bucket of offal, walking quite slowly, talking to nobody. Within ten minutes she has all eleven, and the geese have been restored to a state of grievance.".
  }
  Rule hatchlings_damage when hatchlingsLoose(wapshotts) and hour(clock) >= 7 and hour(clock) < 8 and hatchLosses(wapshotts) < 6 and current(wapshotts, ?g) {
    Decrease standing(?g) by 1 or to nothing. Increase hatchLosses(wapshotts) by 1. }

  // Sir Gervase, the Book, and the charter.
  Topic fenwick_crate with fenwick "Show Sir Gervase the crate's paper" when knows(actor, crate_known) and not fenwickShown(wapshotts) once {
    Says "Sir Gervase takes the paper in both hands and reads it as he has not read anything since the claw. 'Sarn,' he says. 'SARN. It's in the margin, it's in red, in the Southern column, Jabez showed me and I took it for a mistake.' He sits down on the step of the cookhouse wagon. 'The Progress had a preserve. On an island. It has been a hundred and fifty miles south of the Cape all this time. I have sent a letter to the Royal Society every month for a year saying we had nothing to find.' He looks up. 'Eleven eggs! Madam, sir, I will charter a ship.'".
    On discuss { Assert fenwickShown(wapshotts). Assert knows(actor, sarn_known). }
  }
  Topic fenwick_charter with fenwick "Ask Sir Gervase to charter the Sundial" when knows(actor, sarn_known) and knows(actor, ship_known) and not voyageReady(wapshotts) once {
    Says "'The Sundial,' says Sir Gervase. 'Yes. Done. Her master's wages, her bond, and a hold for specimens: a pair of each, for the Society, alive if possible, preserved if not, and a full account.' He beams. 'It is the largest undertaking of my life, and I am delighted to be paying for it. She sails on the morning ebb whenever you are ready. I shall go myself. I should not like to miss a thing.' And, as an afterthought, as if it were nothing: 'The Colonel will want to come. It is, after all, his Keepership.'".
    On discuss { Assert voyageReady(wapshotts). }
  }
  Topic wap_sail with wapshott "Tell the Colonel that Sir Gervase has chartered the Sundial" when voyageReady(wapshotts) and not wapshottAboard(wapshotts) once {
    Says "The Colonel takes off his hat, which is the only time you have ever seen it off in daylight. 'Sarn,' he says. 'A hundred and fifty miles south, and four hundred years since they laid it out.' His hands are trembling. 'I wrote to the one address I had not tried. That is the whole of my gift: I write to the one address I have not tried.' He puts the hat back. 'I shall bring my trumpet,' he says. 'And Ada's best opinion of me. And Billie, if she will come.'".
    On discuss { Assert wapshottAboard(wapshotts). }
  }
  Topic billie_sail with billie "Ask Billie whether she will go to Sarn" when voyageReady(wapshotts) and not billieAboard(wapshotts) once {
    Says "'To the Preserve,' says Billie. 'The place the Book says the beasts were kept.' She is quiet. 'I'll come. On my terms. I'll go where I can see what's done to them, and I'll say when it's enough.' She puts on her coat. 'And nobody is to name anything.'".
    On discuss { Assert billieAboard(wapshotts). Increase regard(billie) by 1. }
  }
  Topic mum_sail with mumchance "Ask Mumchance to come to Sarn" when voyageReady(wapshotts) and regard(mumchance) >= 2 and not mumchanceAboard(wapshotts) once {
    Says "Mumchance looks at you a good while with his clown's face. Then he nods, once, and goes to get his coat. He is the only man in the circus who has ever managed to stand perfectly still in front of the Colonel when the Colonel is excited, and it has occurred to you that this may be what an island is for.".
    On discuss { Assert mumchanceAboard(wapshotts). }
  }


  // The Colonel on the island: three moments, and what he decides.
  Observe wap_landing near wapshott when voyaged(wapshotts) and at(party, landing) and not colonelMoved(wapshotts) "Colonel Wapshott stands at the end of the quay with his hat in his hand, looking up the jungle. He has not spoken since the gangway. On the post by his hand the crowned wheel is cut deep, with a crown over it, and a date, and a name he has been told all his life was a legend.".
  Relation colonelMoved(concern).
  Topic wap_what with wapshott "Ask the Colonel what he sees" when voyaged(wapshotts) and at(party, landing) and not colonelMoved(wapshotts) once {
    Says "'Mud,' says the Colonel. 'A great deal of mud.' He puts his hat back on. He takes it off again. He has been trying, for some minutes, to say something to the jungle, and it has not been listening.".
    On discuss { Assert colonelMoved(wapshotts). }
  }
  Topic wap_rule with wapshott "Show the Colonel the Rule of the Preserve over the hearth" when voyaged(wapshotts) and at(party, preserve_hall) and not ruleRead(wapshotts) once {
    Says "The Colonel reads it aloud, as he reads everything, as if to a house. THE KEEPER IS ANSWERABLE TO THE BEAST. He stops. 'That is a hard thing to be told in a stranger's hall,' he says quietly. 'I thought it was the other way about.' He looks round for Billie, and finds her, and looks away.".
    On discuss { Assert ruleRead(wapshotts). }
  }
  Rule trumpet_found at lake_shore when at(party, lake_shore) and hour(clock) >= 5 and hour(clock) < 9 and voyaged(wapshotts) and herdSeen(party) and not trumpetPending(wapshotts) and not trumpetDone(wapshotts)
    says "The Colonel has stopped being awed. You see it happen: his chest comes up, his hand goes into his coat, and out of it, with a fumbling flourish, comes the trumpet. It is nine inches of brass with a ribbon on it. He is looking at ten lantern-necks and a lake with an expression of terrible joy." {
    Assert trumpetPending(wapshotts). Set trumpetAt(wapshotts) to watch(clock). }
  Rule trumpet_pocketed when trumpetPending(wapshotts) and not at(party, lake_shore) says "Behind you on the shore the Colonel has put the trumpet away, unblown. It is not a thing he can do in front of nobody." { Retract trumpetPending(wapshotts). }
  Action stop_colonel(actor: group, site: place) "Take the Colonel by the elbow before he blows" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lake_shore) and trumpetPending(wapshotts).
    Time 1.
    Resolve check(actor, persuasion, dc_fair).
    On success { Retract trumpetPending(wapshotts). Assert trumpetDone(wapshotts). Assert colonelStopped(wapshotts). }
    Result "'Colonel,' you say, and put your hand on his sleeve. He looks at you, and at the herd, and at his trumpet. After a time he lowers it. 'You are right,' he says, in a small voice. 'There are some audiences one does not play to.'".
    Otherwise "He shakes you off, kindly, and puts the trumpet to his lips.".
  }
  Action still_colonel(actor: group, site: place) "Let Mumchance lay a hand on the Colonel's arm" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, lake_shore) and trumpetPending(wapshotts) and mumchanceAboard(wapshotts).
    Time 0.
    On success { Retract trumpetPending(wapshotts). Assert trumpetDone(wapshotts). Assert colonelStopped(wapshotts). }
    Result "Mumchance walks across the mud without a sound and stands beside him, and puts one white-gloved hand lightly on his sleeve. The Colonel does not look round. His breath goes out of him. He lowers the trumpet slowly, as a man lowers a flag, and after a moment he takes off his hat. The herd goes on drinking.".
  }
  Rule trumpet_blown at lake_shore when at(party, lake_shore) and trumpetPending(wapshotts) and not colonelStopped(wapshotts) and watch(clock) >= trumpetAt(wapshotts) + 2 and not trumpetDone(wapshotts)
    says "The Colonel blows. It is a beautiful note, bright, brazen, perfectly pitched, and it goes out over the lake like a thrown plate. The nearest lantern-neck turns its small head, slowly. The herd takes one step, all together, to the left, and the shore is a shore of mud and spray and vast grey legs." {
    Assert trumpetDone(wapshotts). Assert herdScattered(wapshotts). Assert strikes(herd_stride, party). Retract trumpetPending(wapshotts). }

  Observe herd_scattered_seen at lake_shore when herdScattered(wapshotts) "The mud is churned to soup. A calf is standing apart from the others, with its head up, looking back at the Colonel. Nobody has mentioned the trumpet.".
  Chapter ch_crate "The Crate" when crateCome(wapshotts) and not voyaged(wapshotts) "A sea-captain's crate has come for Colonel Wapshott, who signed himself Keeper of the Menagerie Royal. It is warm, and it is burnt with a crowned wheel, and the Colonel has seen the lid.".
  Chapter ch_sarn "The Isle of Sarn" when voyaged(wapshotts) and within(party, sarn) "A hundred and fifty miles south of the Cape, on a quay with a crowned wheel on every post, in a jungle where nothing has been shown for four hundred years.".
  Chapter ch_after_sarn "After Sarn" when backFromSarn(wapshotts) "The Sundial has put them down at the fair town's quay. Whatever the Colonel took home, or left, the wagons are where they were.".

  Objective colonel_told when voyageReady(wapshotts) and not wapshottAboard(wapshotts) "Sir Gervase has chartered the Sundial. The Colonel will want to be told.".
  Objective crate_ask when crateCome(wapshotts) and not knows(party, crate_known) "A crate has come for Colonel Wapshott, who signed himself Keeper of the Menagerie Royal. Mate Crewe in the yard will say who sent it.".
  Objective hatch_ask when crateOpened(wapshotts) and not eggsHatched(wapshotts) "The eggs will not wait. Billie, Honoria's oven, a lamp: they hatch tonight.".
  Objective loose_ask when hatchlingsLoose(wapshotts) "Eleven young hook-claws are loose in the town, and the geese are screaming.".
  Objective sarn_ask when knows(party, sarn_known) and not voyaged(wapshotts) "The crate came from the Isle of Sarn, where the Progress once kept its beasts. Sir Gervase will charter the Sundial.".

  Milestone m_crate "learned who sent the crate" worth 80 when knows(party, crate_known).
  Milestone m_hatched "saw the clutch through its first night, penned or caught" worth 150 when hatchlingsPenned(wapshotts).
  Milestone m_charter "had the Sundial chartered for Sarn" worth 150 when voyageReady(wapshotts).
  Milestone m_sarn "stood on the Progress's quay" worth 200 when voyaged(wapshotts).
  Milestone m_herd "watched the lantern-necks come down to the lake at dawn" worth 400 when herdSeen(party).
  Milestone m_journal "read Warden Orme's journal" worth 200 when knows(party, journal_read).
  Milestone m_hooks "was suffered by the hook-claws" worth 250 when hookTolerates(party).
  Milestone m_tar "got the sunk three-horn out of the pitch" worth 250 when tarFreed(party).
  Milestone m_egg_back "put the egg back in its bed" worth 150 when eggReturned(party).
  Milestone m_stopped "stopped the Colonel blowing his trumpet" worth 200 when colonelStopped(wapshotts).
  Milestone m_home "brought the Colonel home from Sarn" worth 200 when backFromSarn(wapshotts).
}

data/goings-on/circus/acts.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── The shape of it: four chapters ──────────────────────────────────────────────────────────────────────────
  // The wagons (wonder); the note (the backstage truth, and the rival's shadow); the Goose Fair (the worst hour, and
  // the last show given anyway); and the road again. Each opens on something seen.
  Chapter ch_wagons "The Wagons" when at(party, ?g) and here(?g) and groundOf(?g, ?g) "The field gate stands open and the grass inside it is already trodden into paths. A smell of horse and oranges and wet canvas, a dog asleep on a coil of rope, and a man somewhere out of sight shouting HEAVE in a voice like a gong. You have walked into a circus.".
  Chapter ch_note "The Note" when knows(party, note_known) "Behind every circus there is a second circus, which the public never sees: the ledger, the larder, the wages, the wagon with a wheel that is going. You have seen it now.".
  Chapter ch_fair "The Goose Fair" when fairOn(wapshotts) and within(party, town_a) "The roads into {town_a} are white with geese, and have been for a day; the whole country is coming in behind them to buy and sell and be fleeced. Somewhere in the din, a small round man in a black gown is ringing a bell.".
  Chapter ch_road "On the Road Again" when noteSettled(wapshotts) and onRoad(wapshotts) "At six the canvas comes down in its long sigh, and the wagons go out of {town_a} in the old order, Bucephalus first. Whatever was won or lost, the circus does what it has always done. It goes on round.".

  // ── Before the note: what is seen before it is said ─────────────────────────────────────────────────────────
  Observe grey_hat_house near ringpost when showOn(wapshotts) and nights(wapshotts) >= 1 and not noteServed(wapshotts) and act(wapshotts) >= 2 "At the very back of the house, standing, though there are seats, is a man in a grey topper who does not laugh at anything. He is writing in a small book: not during the acts, you notice, but between them, when the canvasmen come on to clear the ring. He seems to be counting the benches.".
  Observe colonel_counting near wagonring when at(wagonring, ?r) and noteServed(wapshotts) and not noteSettled(wapshotts) and (hour(clock) >= 23 or hour(clock) < 5) "There is one candle still lit in the crimson wagon. Through the little window you can see the Colonel in his shirt, alone, counting the strongbox onto the table, then counting it again, then writing a sum on the back of a playbill and crossing it out.".
  Thing relics "the Colonel's relics" at tober_a {
    State hung "Inside the crimson wagon, over the Colonel's bunk, hang his relics: a framed bill, a length of iron chain, and a picture in a gilt frame with its face to the wall.".
    State turned "Inside the crimson wagon, over the Colonel's bunk, hang his relics: a framed bill, a length of iron chain, and the picture in its gilt frame, turned to face the room: a young woman with a lion cub in her lap and an account-book under her elbow, painted by somebody who loved her.".
    Change turn_picture "Turn the picture round" from hung to turned.
    Tries looking.
  }
  Initially Assert state(relics, hung). Initially Assert travels(relics). Initially Assert post(relics, rk_wagons).
  Observe relics_looked near relics when tried(relics, looking) and not knows(party, relics_known) "The bill, framed in black: WAPSHOTT'S CIRCUS. IN HOB'S FIELD, BEHIND THE WAGGONER, DUNMERE. ONE HORSE. ONE LADDER. ONE GENTLEMAN. ADMISSION AN EGG. The chain is an elephant's ankle-chain, the iron worn bright on the inside, with DIDO stamped on the lock; she died at Marlow in the flood year, Ada says later, and is buried under the market cross, and the town still argues about whether it was a privilege." teaches relics_known.
  Entity relics_known: fact "The Colonel keeps the bill of his first show (Hob's Field, Dunmere; admission an egg), the ankle-chain of Dido, an elephant who died at Marlow in the flood year, and a portrait turned to the wall.".
  Observe sallow_portrait near relics when state(relics, turned) and not knows(party, portrait_known) "Under the portrait, on the frame, a small brass plate: C., AT DUNMERE." teaches portrait_known.
  Entity portrait_known: fact "The portrait the Colonel keeps turned to the wall is of a young woman with a lion cub and an account-book, marked C., AT DUNMERE.".
  Rule picture_back when state(relics, turned) and at(relics, ?r) and not at(party, ?r) { Assert state(relics, hung). }

  // The Fair coming: geese on every road toward the fair town, from the eighth day once the note is out.
  Observe geese_ab at road_ab when noteServed(wapshotts) and day(clock) >= 8 and not fairDone(wapshotts) and not dark() "The road is white with geese: a flock of two hundred or more being driven toward {town_a} for the Goose Fair by two girls with long sticks and a boy with a dog, the whole mass of them moving like a slow spill of milk and hissing at everything that is not a goose.".
  Observe geese_bc at road_bc when noteServed(wapshotts) and day(clock) >= 8 and not fairDone(wapshotts) and not dark() "Geese on the road, a whole flock of them, driven by a woman in a red shawl toward the Fair at {town_a}. Their feet have been dipped in tar and sand for the walk, she tells you, so they will not go lame; they look as if they were wearing boots, and as if they knew it.".
  Observe geese_ca at road_ca when noteServed(wapshotts) and day(clock) >= 8 and not fairDone(wapshotts) and not dark() "Geese on the road, going the way the wagons go, toward {town_a} and the Goose Fair: a hundred white backs in a bobbing tide between the hedges, and a drover asleep on a donkey behind them.".
  Relation fairDone(concern).
  Rule fair_done when noteSettled(wapshotts) and not fairDone(wapshotts) { Assert fairDone(wapshotts). }

  // ── The worst hour: the tober-raiders, on the Fair's first night ─────────────────────────────────────────────
  // At eleven, three men from Dunmere come onto the ground with knives for the guy-ropes, hired by Slee by the rope.
  // They can be fought; or the old cry raised, which brings the whole backyard; or paid; or told whose ropes they
  // are; or led a dance through the ropes in the dark. Left alone for an hour, they bring the big top down.
  Person raiders "three men from Dunmere" at tober_a {
    Role "tober-raiders with knives and cudgels". Ancestry human. Calling warrior. Level 2. Numbers 3. Pronouns they.
    Temperament territorial.
    Warns "Three men are coming across the dark field from the hedge, low, with their hats pulled down: one has a lantern with the shutter nearly closed, and in the slice of light you see a knife, and a rope parting under it with a sound like a bow-string. The biggest of them sees you and stops. 'Go back to bed,' he says, quite kindly. 'This is none of yours. We're paid by the rope.'".
    Comes "The three of them come at you through the guy-ropes with their cudgels up.".
    Flinches "The men from Dunmere go back over the hedge the way they came, faster than they came.".
    Pleads "The last of the men from Dunmere sits down in the wet grass with his hands up. 'A shilling a rope,' he says. 'The gent in grey. That's all I know. That's all any of us know.'".
  }
  Initially Assert offstage(raiders).
  Relation raidOn(concern). Relation raidStopped(concern). Relation canvasCut(concern). Measure raidAt(concern).
  Rule raid_comes when fairFirst() and hour(clock) >= 23 and not raidOn(wapshotts) and not raidStopped(wapshotts) and not canvasCut(wapshotts) and not sleeExposed(slee) {
    Assert raidOn(wapshotts). Set raidAt(wapshotts) to watch(clock). Retract offstage(raiders). Assert at(raiders, tober_a). }
  Rule raid_heard near beastpost when raidOn(wapshotts) and at(party, beasts_a) and not raidHeard(wapshotts)
    says "Out on the front, in the dark, voices, low; and then a sound you know, the creak of a guy-rope taking a knife, and the snap as it goes." { Assert raidHeard(wapshotts). }
  Relation raidHeard(concern).
  Rule raid_done near pole when raidOn(wapshotts) and watch(clock) >= raidAt(wapshotts) + 6 and not raidStopped(wapshotts) and able(raiders)
    says "In the small hours, with a long groan of canvas, the big top of Wapshott's sags, and leans, and comes down on one side across the ring, with the guy-ropes cut on the side toward the hedge. Lusk is out in his nightshirt with a lantern before it has finished falling. By first light the whole circus is sewing." {
    Assert canvasCut(wapshotts). Retract raidOn(wapshotts). Assert offstage(raiders). Set canvas(wapshotts) to 0. }
  Rule raid_beaten when raidOn(wapshotts) and not able(raiders) { Assert raidStopped(wapshotts). Retract raidOn(wapshotts). Increase evidence(party) by 1. }
  Rule raid_gone when raidStopped(wapshotts) and not offstage(raiders) and able(raiders) { Assert offstage(raiders). }
  Action hey_rube(actor: group, site: place) "Raise the old cry of the circus at the top of your voice: Hey Rube!" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(raiders, site) and raidOn(wapshotts) and (hand(actor) or regard(lusk) >= 2 or regard(honoria) >= 2).
    On success { Assert raidStopped(wapshotts). Retract raidOn(wapshotts). Increase regard(lusk) by 1. Increase evidence(actor) by 1. }
    Result "You shout it: HEY RUBE! And the circus, which was asleep, is not. Wagon doors bang open all round the ring. Lusk comes round the big top in his shirt with a king-stake in each hand; eight canvasmen behind him with mallets; the Quinceys, cartwheeling; Billie with a pitchfork; and last, filling the gap between two wagons, Honoria Bulstrode in a flowered nightgown with a frying-pan. The men from Dunmere look at Honoria for a long moment. Then they are over the hedge, and one of them leaves his hat, and in the hat is a paper with the number of ropes on it and a shilling a rope, in a neat grey hand.".
  }
  Action hey_rube_flattie(actor: group, site: place) "Shout Hey Rube! as you have heard the circus does, and hope it answers a stranger" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(raiders, site) and raidOn(wapshotts) and not hand(actor) and regard(lusk) < 2 and regard(honoria) < 2 and not shoutedRube(actor).
    Resolve check(actor, performance, dc_hard).
    On success { Assert raidStopped(wapshotts). Retract raidOn(wapshotts). Increase evidence(actor) by 1. }
    On failure { Assert shoutedRube(actor). }
    Result "You shout it, HEY RUBE, in a voice you did not know you had, and for a moment nothing; and then a wagon door bangs, and Lusk's voice says 'Who's that?', and then all the doors, and the circus comes out to see who is calling its call, and finds three men from Dunmere with knives. The men do not wait to be introduced.".
    Otherwise "You shout it, and somewhere a dog barks, and the biggest of the three men laughs. 'That's not yours to shout, flattie,' he says.".
  }
  Relation shoutedRube(group).
  Action raiders_paid(actor: group, site: place) "Offer the men from Dunmere twelve coin to go home, which is more than they are paid" {
    Speaker raiders. Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(raiders, site) and raidOn(wapshotts) and quantity(actor, gold) >= 12.
    On success { Decrease quantity(actor, gold) by 12. Increase quantity(raiders, gold) by 12. Assert raidStopped(wapshotts). Retract raidOn(wapshotts). }
    Result "The biggest one weighs the coins in his hand, and looks at his friends, and at the ropes, and does a sum. 'The gent in grey said a shilling a rope,' he says. 'He didn't say anything about a better offer.' They go back over the hedge, and one of them, from the far side, wishes you a good night.".
  }
  Action raiders_told(actor: group, site: place) "Tell the men from Dunmere whose ropes these are, and who sleeps in the cookhouse wagon thirty feet away" {
    Speaker raiders. Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(raiders, site) and raidOn(wapshotts) and not toldRaiders(actor).
    Resolve check(actor, intimidation, dc_fair).
    On success { Assert raidStopped(wapshotts). Retract raidOn(wapshotts). Increase evidence(actor) by 1. }
    On failure { Assert toldRaiders(actor). }
    Result "You tell them, low, about the Ox of Abernant: what she lifts every night, and what she lifted off her brother at fourteen, and that she is a light sleeper. The smallest of them has seen her lift the horse. He starts to go, without a word, and the others look at him, and then they go too. 'The gent in grey never said,' one of them mutters, going. 'The gent in grey never says anything.'".
    Otherwise "You tell them about the Ox of Abernant, and the biggest of them says he has heard of her and that she is in the bills in letters twice the size she is in life.".
  }
  Relation toldRaiders(group).
  Action raiders_led(actor: group, site: place) "Lead them a dance through the guy-ropes in the dark, the way a clown goes through a crowd" {
    Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(raiders, site) and raidOn(wapshotts) and not ledRaiders(actor).
    Resolve check(actor, tumbling, dc_fair).
    On success { Assert raidStopped(wapshotts). Retract raidOn(wapshotts). }
    On failure { Assert ledRaiders(actor). }
    Result "You grab the nearest one's lantern and run, and they come after you, into the guy-ropes: forty of them, in the dark, at the height of a man's shin, and you know where every one is because you have been tripping over them for days. You go through them like a hare through a hedge. Behind you there is a sound like a bag of tools being dropped down a well, three times. By the time they have got up, every wagon door is open.".
    Otherwise "You run into the guy-ropes with a stolen lantern and the first rope you meet is the one you forgot, and you go down, and the lantern goes out, and the three of them stand over you in the dark, breathing.".
  }
  Action raiders_feinted(actor: group, site: place) "Feint: look past them at the cookhouse wagon, and call out to Honoria as if she were already on the steps" {
    Speaker raiders. Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(raiders, site) and raidOn(wapshotts) and feintLearned(actor) and not ledRaiders(actor).
    Resolve check(actor, deception, dc_easy).
    On success { Assert raidStopped(wapshotts). Retract raidOn(wapshotts). }
    On failure { Assert ledRaiders(actor). }
    Result "You look past them, over the biggest one's shoulder, at the dark bulk of the cookhouse wagon, and say, quite quietly, 'No, it's all right, Honoria. Put it down. There's only three.' All three of them turn round. When they turn back you are gone, and so, in another moment, are they.".
    Otherwise "You look past them and call to Honoria, and the biggest one does not turn. 'Oldest trick there is,' he says. 'My granny did that one.'".
  }
  Relation ledRaiders(group).
  Observe canvas_patched near ringpost when canvasCut(wapshotts) and fairOn(wapshotts) "The big top has been sewn back together in a day: a long scar of new stitching runs down one side, and two of the guy-ropes are knotted where they were cut, and through a seam near the king-pole you can see a strip of sky.".
  Rule contest_patched when fairThird() and showOn(wapshotts) and act(wapshotts) == 1 and canvasCut(wapshotts) and not patchedCounted(wapshotts) {
    Assert patchedCounted(wapshotts). Decrease quality(wapshotts) by 2. }
  Relation patchedCounted(concern).

  // ── The jury, aloud, at the pump at nine ──────────────────────────────────────────────────────────────────
  Rule jury_clerk at green_a when fairThird() and hour(clock) >= 21 and juryIn(wapshotts) and not juryClerkSaid(wapshotts)
    says "Before the verdict, by the charter, each of the jury gives a reason. Master Pettigrew first, consulting his ledger: 'The Hippodrome's pitch-toll was paid on the day it came, in full, with a goose. Wapshott's,' he looks over the ledger, 'is noted.'" {
    Assert juryClerkSaid(wapshotts). }
  Rule jury_clerk_paid at green_a when juryClerkSaid(wapshotts) and feePaid(wapshotts) and not juryClerkPaid(wapshotts)
    says "'Noted,' he adds, 'as paid. For the first time in nineteen years. I have told my wife.'" { Assert juryClerkPaid(wapshotts). }
  Relation juryClerkSaid(concern). Relation juryClerkPaid(concern).
  Rule jury_keeper_lie at green_a when juryClerkSaid(wapshotts) and basiliskBilled(wapshotts) and not juryKeeperSaid(wapshotts)
    says "Then {keeper_a}: 'A full house both nights, and nobody hurt. But I'll not give a prize to a basilisk with a bantam's legs. I've had the Colonel's mermaid.'" { Assert juryKeeperSaid(wapshotts). }
  Rule jury_keeper_cut at green_a when juryClerkSaid(wapshotts) and canvasCut(wapshotts) and not juryKeeperSaid(wapshotts)
    says "Then {keeper_a}: 'They played in a tent that was on the ground at dawn. Sewn up in a day. You could see the stars through it in the third act, and nobody went home.'" { Assert juryKeeperSaid(wapshotts). Increase fairScore(wapshotts) by 1. }
  Rule jury_keeper_plain at green_a when juryClerkSaid(wapshotts) and not juryKeeperSaid(wapshotts)
    says "Then {keeper_a}: 'A full house both nights, and nobody hurt, and no lies on the bills that I could catch. That's all I ask of anybody.'" { Assert juryKeeperSaid(wapshotts). }
  Relation juryKeeperSaid(concern).
  Rule jury_priest_mother at green_a when juryKeeperSaid(wapshotts) and reunited(pruett) and not juryPriestSaid(wapshotts)
    says "Last {priest_a}, quietly, so that the Fair leans in to hear: 'I said I did not mind a thing being impossible, only false. A woman walked on a rope tonight, forty feet up, and stopped in the middle, and lifted her parasol to her mother on the back bench. That was impossible. It was not false.'" { Assert juryPriestSaid(wapshotts). Increase fairScore(wapshotts) by 2. }
  Rule jury_priest_cock at green_a when juryKeeperSaid(wapshotts) and basiliskHonest(wapshotts) and not juryPriestSaid(wapshotts)
    says "Last {priest_a}: 'There is a board in Wapshott's menagerie that says a cockerel believes himself a basilisk, and asks you not to contradict him. It is the most honest thing I have read this year.'" { Assert juryPriestSaid(wapshotts). Increase fairScore(wapshotts) by 1. }
  Rule jury_priest_laugh at green_a when juryKeeperSaid(wapshotts) and not juryPriestSaid(wapshotts)
    says "Last {priest_a}: 'I laughed,' {priest_a} says, and seems surprised to hear it. 'In both. More in one.'" { Assert juryPriestSaid(wapshotts). }
  Relation juryPriestSaid(concern).

  // ── People noticing the rhyme ────────────────────────────────────────────────────────────────────────────
  Topic mum_back_bench with mumchance "Tell Mumchance about Mrs Pruett on the back bench" when knows(actor, susan_pruett) once {
    Says "Mumchance puts down his brush. 'My father sat at the back,' he says. 'Every year, at the Midsummer Fair at Dunmere, for twenty-two years. Never once came round. I never once went out to him. I'd see the shape of him against the lamps at the flap and I'd do the ladder for him, the whole act, for one man at the back who'd sent me to the sword.' He picks the brush up again. 'Then one year the shape wasn't there.' He goes on painting. 'Somebody should walk that girl down the lane.'".
  }
  Topic mum_colonel_fall with mumchance "Ask Mumchance about the way the Colonel falls over the ring boards every night" when true once {
    Says "Mumchance smiles, which takes some time to arrive. 'Nineteen years,' he says, 'and he has never once meant it. He backs out bowing, and the boards are where they always are, and down he goes, and the house thinks it is the best joke of the night, and he gets up red to the ears and furious.' He blots his lip. 'The day he means it, he'll be a clown. I've been waiting for that day since he was a young man in Hob's Field with one horse and a borrowed ladder.'".
  }
  Topic priest_c_bone with priest_c "Ask {priest_c} about the great bone kept in the shrine" when true once {
    Says "{priest_c} takes you to it: under the side-altar, on a trestle, wrapped in a moth-eaten altar cloth, a bone the colour of strong tea and as long as a tall man, with a knuckle at one end the size of a cottage loaf. 'From the marl-pit, last spring,' {priest_c} says. 'The diggers stopped work for a week. The children call it the giant's leg. Old Tull says it is from the ox that drew the ark.' {priest_c} lays the cloth back over it, gently. 'I say prayers over it, in case. Nobody has told me for whom.'".
    On discuss { Assert knows(actor, bone_seen). }
  }
  Entity bone_seen: fact "Under the side-altar of the shrine at {town_c} lies a bone as long as a tall man, dug from the marl-pit last spring: nobody knows of what.".
  Topic pip_cant with pip "Ask Pip what all the circus words mean" when true once {
    Says "'Oh!' Pip sits down on a bucket, delighted to be asked. 'The tober's the ground. The flatties are you lot, the town, no offence. A joey is a clown, after Joey Pell, who was the first one, at Dunmere, a hundred years ago, and could make a whole house cry by eating a string of sausages. A kinker's a performer, a grafter's a canvasman, the half is half an hour before the show, and the bunce is what's left in the box after, which is never anything.' She thinks. 'And if you ever hear somebody shout Hey Rube, you drop what you're holding and run toward it, whatever it is. That's the oldest one. That's for when the flatties come for the tober with sticks. It hasn't happened since I've been here.' She looks pleased and a little disappointed. 'Mumchance says it happened at Wakeham.'".
    On discuss { Assert knows(actor, hey_rube_known). }
  }
  Entity hey_rube_known: fact "Hey Rube! is the oldest cry of the circus: whoever hears it drops what they are holding and runs toward it, for when the tober is attacked.".

  // ── At the Flyting: forty years of silence, and one word ──────────────────────────────────────────────────
  Rule mum_speaks at green_a when boutWon(party, bombazine) and answerLearned(party) and not mumSpoke(mumchance)
    says "Bombazine, red under his paint, rounds on the old man in the white face. 'And HIM!' he bellows to the Fair. 'Forty years and never a WORD! Is there a word in him? Is there ONE?' The green goes quiet. Mumchance takes one step forward, and looks at Bombazine, and then at you, a long look, the one he gave you over forty dropped plates; and says, quite clearly, in his soft dry voice, so that the whole of {town_a} hears it: 'Again.' The Fair goes up like a hayrick. Somewhere at the back a small bald cobbler is shouting 'HE SPOKE! NINE YEARS! HE SPOKE!' and weeping into his apron." {
    Assert mumSpoke(mumchance). Increase fairScore(wapshotts) by 1. }
  Relation mumSpoke(group).
  // Jos at the Fair: for Wapshott's if he was beaten fair, and against it if he was not.
  Rule jos_to_fair when fairSecond() and hour(clock) >= 14 and hour(clock) < 17 and not at(jos, green_a) { Assert at(jos, green_a). }
  Rule jos_back when fairSecond() and hour(clock) >= 17 and at(jos, green_a) { Assert at(jos, green_b). }
  Rule jos_for_us at green_a when inBout(bombazine) and boutWon(party, jos) and not josSided(jos)
    says "From the crowd, a voice like a rusty hinge: 'Go on, swan! I taught you better than that! Tell him about his wig!' Jos Haverhill, in his Sunday coat, has walked all the way from {town_b} to heckle for you." {
    Assert josSided(jos). Decrease composure(bombazine) by 1 or to nothing. }
  Rule jos_against at green_a when at(party, green_a) and inBout(bombazine) and boutLost(party, jos) and not boutWon(party, jos) and not josSided(jos)
    says "From the crowd, a voice like a rusty hinge: 'That's the one I had for breakfast in {town_b}, Captain! Go easy, it bruises!' Jos Haverhill has walked all the way from {town_b}, it seems, to enjoy himself." {
    Assert josSided(jos). Decrease poise(party) by 1 or to nothing. }
  Relation josSided(group).

  // ── Ada and the roof she is offered ───────────────────────────────────────────────────────────────────────
  Topic ada_offer with ada "Ask Ada what Madame Sallow wanted with her" when fairOn(wapshotts) and day(clock) >= fairDay(wapshotts) + 1 and not noteSettled(wapshotts) once {
    Says "Ada does not look up from the ledger. 'A quarter-share,' she says. 'In the Hippodrome. Now. Today. Her own book-keeper's going to Dunmere to marry a wine-merchant and she wants somebody who can add and isn't frightened of a man in a crimson coat.' She turns a page that does not need turning. 'It's what I wanted. A quarter of a circus by thirty. I'm twenty-four.' Her pencil has stopped. 'She looked at me the way you'd look at a good horse in a bad stable. Nobody's ever looked at me like that. The Colonel looks at me like a man looking at a fence.'".
    On discuss { Assert knows(actor, ada_offered). }
  }
  Entity ada_offered: fact "Madame Sallow has offered Ada Thripp a quarter-share in the Imperial Hippodrome, now, which is what Ada wanted of Wapshott's by thirty.".
  Topic ada_stay with ada "Tell Ada that Wapshott's needs her more than the Hippodrome does" answering ada_offer when not adaAnswered(ada) {
    Says "'I know,' says Ada. 'That's the trouble with it.' She closes the ledger. 'I'll tell her after the Fair. Whatever the Fair says.'".
    On discuss { Assert adaAnswered(ada). }
  }
  Topic ada_go with ada "Tell Ada she should take it" answering ada_offer when not adaAnswered(ada) {
    Says "Ada looks at you properly for the first time. 'Yes,' she says. 'I should.' She goes on looking. 'And who'd keep him? Fipps? The horse?' She opens the ledger again. 'I'll tell her after the Fair. Whatever the Fair says.'".
    On discuss { Assert adaAnswered(ada). }
  }
  Relation adaAnswered(group).
  Topic wap_ada with wapshott "Tell the Colonel that Madame Sallow has offered Ada a quarter-share" when knows(actor, ada_offered) and not noteSettled(wapshotts) once {
    Says "The Colonel stops with his hand on the wagon door. For once he does not say anything large. 'Of course she has,' he says. 'Cordelia always knew what a thing was worth before I did.' He looks across the wagon-ring at the hatch of the ticket wagon, where a green bonnet is bent over a book. 'Four years,' he says. 'And I have never once asked her what she wanted.' He goes in, and shuts the door, and does not come out for an hour.".
    On discuss { Assert colonelKnowsAda(wapshott). }
  }
  Relation colonelKnowsAda(group).
  Rule ada_share near wapshott when noteDischarged(wapshotts) and colonelKnowsAda(wapshott) and not adaShared(ada)
    says "When Madame Sallow has gone, the Colonel turns round in the lamplight and holds out his pen to Ada: his own pen, the steel one with the brass cap. 'A quarter-share,' he says. 'Drawn up properly, by you, since I should get it wrong. And the pen.' Ada takes the pen. She turns it over once, as if checking it for a maker's mark. Then she puts it behind her ear with the two pencils, and says, 'Thank you, Florian,' which nobody in the circus has ever heard her call him." {
    Assert adaShared(ada). }
  Relation adaShared(group).
}

data/goings-on/circus/art.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── The Gentle Art: what Mumchance teaches, which is the art of the sword done with a bucket ────────────────
  // Four foundations, in order: the Fall (to go down on purpose and come up laughing), the Look (to time a thing so
  // the house, or a man with a club, looks where you want), the Feint (to show the eye one thing and the hand
  // another), and the Answer (to give back what is thrown at you, in words). Each once learned is a technique
  // Mumchance will drill into a member for what they have learned in the world; the Wire, which the Sylph teaches, is
  // balance, and stays in the body. What comes after the four (the Riposte, the Mirror) he only speaks of.
  Relation fallLearned(group). Relation lookLearned(group). Relation feintLearned(group). Relation answerLearned(group).
  Relation wireLearned(group). Relation wireWalked(group). Measure triedFallDay(group). Measure triedLookDay(group). Measure triedFeintDay(group).
  Measure triedWireDay(group). Relation watchedEntree(group). Relation tumbledWithQuinceys(group). Relation bandLearned(group).
  Query freeHour() means not showOn(wapshotts) and not onRoad(wapshotts).

  Topic mum_teach with mumchance "Ask Mumchance whether he would teach you" when knows(actor, gentle_art_heard) and not fallLearned(actor) once {
    Says "Mumchance looks at you for a long time in the mirror. 'People ask me to teach them to be funny,' he says. 'I can't. Nobody can. I can teach you to fall down. That's all. Everything else grows out of the fall, if you let it, the way a tree grows out of a hole in the ground.' He turns round on his bucket. 'My father taught the sword in four lessons, and so do I. The Fall. The Look. The Feint. The Answer. You'll get hurt. You'll get up. The getting up is the art.' He nods at the ring. 'Sawdust's soft. Come when there's no show on.'".
    On discuss { Assert knows(actor, art_offered). }
  }
  Entity art_offered: fact "Mumchance will teach the Gentle Art, in four lessons as his father taught the sword: the Fall, the Look, the Feint, the Answer.".
  Action learn_fall(actor: group, site: place) "Learn the Fall from Mumchance" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(mumchance, site) and knows(actor, art_offered) and freeHour()
      and not fallLearned(actor) and triedFallDay(actor) < day(clock).
    Resolve check(actor, tumbling, dc_fair).
    On success { Assert fallLearned(actor). Assert teaches(mumchance, pratfall). Assert canTurn(actor, turn_clown). Give slap_shoes to actor. Assert knows(actor, shoes_given). }
    On failure { Set triedFallDay(actor) to day(clock). }
    Result "An hour of falling. Forwards, backwards, sideways off a barrel, off a chair, off Pip. 'Don't fall,' says Mumchance, over and over. 'Go down. A fall happens to you. Going down is something you do.' Near the end of the hour you trip over the ring boards by accident and your body does it by itself: tucks, rolls, takes the ground along the long muscles of the back, and you come up sitting, unhurt, looking at the boards as if they had been rude. Mumchance nods. Then he goes to his trunk and gives you a pair of long, flat, floppy shoes, soft as gloves. 'My first slap-shoes,' he says. 'They'll know where the ground is before you do.' Then: 'The next is the Look. You can't be told it. Stand in the wing at the ring curtain one night when I go on, and watch me from the side, not the front. Then come and ask.'".
    Otherwise "An hour of falling, and every fall is a fall: you go down like a dropped sack and come up wincing. 'Tomorrow,' says Mumchance mildly. 'The body has to forget that it's afraid. That takes a night's sleep.'".
  }
  Kind circus_slapshoe_kind "a clown's slap-shoes" like boots_of_swiftness granting tumbling worth 2 weighing 1
    described "Long, flat, floppy shoes of soft leather, worn thin at the toes, that slap the ground with a sound like applause. They were Mumchance's first.".
  Item slap_shoes "Mumchance's old slap-shoes" is circus_slapshoe_kind at tober_a hidden until shoes_given.
  Discovery shoes_given "Mumchance has given you his first slap-shoes.".

  Topic mum_next_lesson with mumchance "Ask Mumchance about the second lesson" when fallLearned(actor) and not watchedEntree(actor) and not lookLearned(actor) {
    Says "'The Look,' says Mumchance. 'Stand in the wing, by the ring curtain, when I go on with the ladder: after the Ox, before the wire. Watch from the side. Then come and ask me.'".
  }
  Action watch_entree(actor: group, site: place) "Stand in the wing at the ring curtain and watch Mumchance's entrée from the side" {
    Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and ringHere(site) and showOn(wapshotts) and act(wapshotts) == 5 and fallLearned(actor)
      and not watchedEntree(actor).
    On success { Assert watchedEntree(actor). }
    Result "You watch him from the side, where the house cannot see you and you can see both him and them. And you see what you never could from the benches: that the laugh does not come when he falls. It comes a moment after, when he looks. He waits until the house has finished being frightened for him; and then he looks at the ladder; and the look is the joke. He times it to their breathing. He is conducting them.".
  }
  Action learn_look(actor: group, site: place) "Ask Mumchance to teach you the Look" {
    Speaker mumchance. Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(mumchance, site) and fallLearned(actor) and watchedEntree(actor) and freeHour()
      and not lookLearned(actor) and triedLookDay(actor) < day(clock).
    Resolve check(actor, performance, dc_fair).
    On success { Assert lookLearned(actor). Assert teaches(mumchance, taunt). }
    On failure { Set triedLookDay(actor) to day(clock). }
    Result "He sits you on a bucket facing Pip, and makes Pip drop a plate, and makes you look at the plate. Forty times. Too soon, and nobody has seen the plate. Too late, and everybody has stopped caring. On the forty-first Pip laughs out loud before she can stop herself, and Mumchance says, 'There.' Then, more quietly: 'That look, held a little longer, at a man who means you harm, makes him look at you and nobody else. Bulls do it. Bullies do it. It's useful, in a tight place, to be the one everyone's looking at, if you know what you'll do with it.'".
    Otherwise "Forty times you look at the plate. Every time, Pip just watches you look at it. 'You're looking because you know you should,' says Mumchance. 'Look because you can't help it. Tomorrow.'".
  }
  Action learn_feint(actor: group, site: place) "Fence with Mumchance in the backyard, a stick each, for the Feint" {
    Speaker mumchance. Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(mumchance, site) and lookLearned(actor) and freeHour()
      and not feintLearned(actor) and triedFeintDay(actor) < day(clock).
    Resolve check(actor, deception, dc_fair).
    On success { Assert feintLearned(actor). Assert teaches(mumchance, feint). Assert teaches(mumchance, dodge). }
    On failure { Set triedFeintDay(actor) to day(clock). }
    Result "Mumchance takes two broom handles from the canvas wagon, gives you one, and for the first time since you have known him stands up straight. He is suddenly a fencing-master's son, light on his bad knees, and you cannot touch him. 'You look at my eyes,' he says. 'Stop. My eyes are lying.' He shows you: the shoulder that says left while the hip goes right, the step back that is a step in, the dropped stick that is not dropped. In the end you get one past him, by looking hard at his left boot and hitting his right elbow, and he laughs aloud, which nobody in the circus has heard him do. 'That,' he says, 'is a feint. And this,' he sways out of your next stroke without moving his feet, 'is how a clown doesn't get hit.'".
    Otherwise "Mumchance does not let you touch him once in an hour. 'You decide what to do and then you pretend,' he says. 'Pretend first. Decide later.' He hangs the sticks up. 'Again tomorrow.'".
  }
  Topic mum_answer with mumchance "Ask Mumchance about the fourth lesson, the Answer" when feintLearned(actor) and not answerLearned(actor) once {
    Says "'The Answer I can't teach,' says Mumchance. 'You learn it from whoever is throwing things at you. When someone in the house shouts at you, and they will, the whole house turns to see what you'll do. Answer them right and the house is yours. Answer them wrong and it's theirs.' He thinks. 'There's a cobbler in {town_b} called Jos Haverhill who heckles every show we give there, and he's the best I ever heard. Go and lose to him. Then go and lose to him again. One night you'll answer.'".
    On discuss { Assert knows(actor, jos_named). }
  }
  Entity jos_named: fact "Jos Haverhill, a cobbler of {town_b}, heckles every show Wapshott's gives there, and Mumchance says he is the best he ever heard.".
  Topic mum_after_art with mumchance "Ask Mumchance what comes after the four" when answerLearned(actor) once {
    Says "Mumchance is quiet for a long time. 'After the four,' he says, 'is the Riposte: to let a blow come, and be where it isn't, and have it land on the one who threw it. My father could do it with a sword. I can do it with a custard.' He looks at the wire, high up. 'And after that, they say, is the Mirror. I saw it once. A clown at the Fair at Dunmere, forty years ago, called Old Pantaloon, with a conjuror in the ring throwing fire at him; and he held up his two hands, empty, like a man looking in a glass, and the fire went back the way it came.' He shakes his head. 'I don't know how. Nobody does now. Maybe nobody ever did and I dreamed it.' He looks at you. 'You've the four. You're a clown, of the first degree. That's a lot more than most. The rest is the road.'".
    On discuss { Assert knows(actor, mirror_heard). }
  }
  Entity mirror_heard: fact "After the Gentle Art's four foundations come the Riposte and, Mumchance says, the Mirror: he once saw an old clown at Dunmere hold up empty hands and send a conjuror's fire back the way it came.".

  // The Wire: balance, from the Sylph, for one who can already fall.
  Action learn_wire(actor: group, site: place) "Ask Zéphyrine to teach you on the low practice wire" {
    Speaker zephyrine. Time 12.
    Requires able(actor) and company(actor) and at(actor, site) and at(zephyrine, site) and fallLearned(actor) and regard(zephyrine) >= 1 and freeHour()
      and not wireLearned(actor) and triedWireDay(actor) < day(clock).
    Resolve check(actor, tumbling, dc_hard).
    On success { Assert wireLearned(actor). }
    On failure { Set triedWireDay(actor) to day(clock). }
    Result "There is a practice wire strung at knee height between two wagons, and for two hours the Sylph walks beside you on the grass while you fall off it. 'You look at your feet,' she says. 'Your feet know where they are. Look at the end.' 'You hold your breath. Breathe. The wire does not like to be held.' At the end of the second hour you walk its whole length, looking at the end of it, breathing, and step off, and your body feels as if it has been taken apart and put back together the right way round. 'Good,' she says, and for a moment, in the dusk, her accent is from nowhere further than the next county. 'Walk it once more, for me, and it is yours.'".
    Otherwise "For two hours the Sylph walks beside you while you fall off the wire. 'Not today,' she says, without unkindness. 'The wire is like a cat. It comes to you when you have stopped wanting it.'".
  }
  Action walk_wire(actor: group, walker: member, site: place) "Have {walker} walk the practice wire once more, for Zéphyrine" {
    Time 2.
    Requires memberOf(walker, actor) and awake(walker) and at(actor, site) and at(zephyrine, site) and wireLearned(actor) and not wireWalked(actor).
    Resolve endow(walker, dexterity, by_one).
    On success { Assert wireWalked(actor). Increase regard(zephyrine) by 1. }
    Result "{walker} walks it once more, end to end, without looking down, and it stays: something in the ankles and the back of the neck that will not now go away. Zéphyrine nods once, as a sylph nods to another sylph.".
  }

  // Tumbling with the Brothers Quincey, and the band with Fipps: what a turn of each kind rests on.
  Action tumble_quinceys(actor: group, site: place) "Practise tumbling with the Brothers Quincey" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(hal, site) and at(dunstan, site) and freeHour() and not tumbledWithQuinceys(actor).
    Resolve check(actor, tumbling, dc_fair).
    On success { Assert tumbledWithQuinceys(actor). Assert canTurn(actor, turn_tumble). Increase regard(hal) by 1. Increase regard(dunstan) by 1. }
    Result "An hour in the ring between the Quinceys, each of whom gives you instructions meant for the other. 'Tuck tighter,' says Hal, 'not like some people.' 'Land on the ball of the foot,' says Dunstan, 'which some people never learned.' By the end you can do a cartwheel, a back-roll and a thing that is nearly a handspring, and both of them, separately, tell you that you have a gift.".
    Otherwise "An hour in the ring between the Quinceys, who both tell you that your cartwheel is a crime, and then argue about whose fault it is, through Pip.".
  }
  Action learn_band(actor: group, site: place) "Learn a part with Fipps and the band" {
    Speaker fipps. Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(fipps, site) and freeHour() and not bandLearned(actor).
    Resolve check(actor, performance, dc_easy).
    On success { Assert bandLearned(actor). Assert canTurn(actor, turn_band). Increase regard(fipps) by 1. }
    Result "Fipps sits you on an upturned tub between Tom Gale and his cornet and Abel Rudd and his drum, and teaches you the Grand Entry, the Galop and the Sylph's Waltz, by singing them at you with his eyes shut. 'Music,' he says, 'is just counting, with feeling. The counting is the easy part. The feeling,' he taps the serpent, 'is what she won't do.' By the end Abel Rudd, who cannot hear, nods at you, which Fipps says is the highest honour in the band.".
    Otherwise "An hour with the band. You are always one bar behind, and Abel Rudd, who cannot hear you, knows it anyway, and looks at you sorrowfully over the drum. 'Tomorrow,' says Fipps. 'Counting, with feeling.'".
  }

  // ── The Answer: a bout of words with whoever heckles the ring ─────────────────────────────────────────────
  // A heckler throws three things at the one standing up to them; each answer may shake them (their composure) or
  // leave the one answering shaken (their poise). A heckler shaken to nothing is beaten, and the house with them;
  // one who shakes the answerer to nothing has won, and the house with him.
  Relation heckler(group). Relation inBout(group). Measure composure(group). Measure poise(group). Measure jab(group).
  Relation boutWon(group, group). Relation boutLost(group, group). Relation answered(group). Measure boutDay(group).
  Person jos "Jos Haverhill" at green_b {
    Role "a cobbler of the town, and its wit". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Greets "A little bald man in a leather apron is sitting on a bench with a boot on a last between his knees and a mouth full of nails, which he takes out one at a time to talk through. 'Haverhill,' he says. 'Jos. Cobbler. Mend anything but a broken heart, and I'll have a go at that if it's leather.' He looks you over. 'You'll be with the circus. You've the look. Like a goose that's been told it's a swan.'".
    Greets again "'Here's the swan,' says Jos Haverhill, taking a nail out of his mouth.".
  }
  Initially Assert heckler(jos).
  Rule jos_to_show when here(tober_b) and showOn(wapshotts) and not at(jos, ring_b) { Assert at(jos, ring_b). }
  Rule jos_home when not showOn(wapshotts) and not at(jos, green_b) { Assert at(jos, green_b). }
  Topic jos_heckle with jos "Ask Jos why he heckles the circus" when true once {
    Says "'Somebody has to,' says Jos. 'Thirty folk in spangles shouting at you that it's wonderful: a man's got to shout back, or what's he? Furniture.' He hammers a nail. 'The old clown never answers. He just looks at me. I've been trying to make that man say a word for nine years. Biggest laugh I ever got was the night he nearly did.'".
  }
  Rule jos_heckles near jos when showOn(wapshotts) and here(tober_b) and act(wapshotts) == 3 and at(party, ring_b) and boutDay(jos) < day(clock)
    and not inBout(jos) and not boutWon(party, jos)
    says "From the back of the benches a voice like a rusty hinge: 'Oi! You! Yes, you, sat there like a ha'penny bun!' Heads turn. Jos Haverhill is on his feet, pointing at you. 'You're with this lot, aren't you? I can tell by the face. Go on, then. Do something. The whole of {town_b}'s waiting.'" {
    Assert inBout(jos). Set composure(jos) to 5. Set poise(party) to 3. Set jab(jos) to 1. Set boutDay(jos) to day(clock). Retract answered(party). }
  Rule jos_jab2 near jos when inBout(jos) and jab(jos) == 2 and not answered(party) and not jabTold(jos)
    says "'Is that it?' says Jos, to the house. 'I've had livelier conversations with a boot. I've had funnier conversations with a boot, and I nailed that one shut.'" { Assert jabTold(jos). }
  Rule jos_jab3 near jos when inBout(jos) and jab(jos) == 3 and not answered(party) and not jabTold(jos)
    says "Jos turns to the house with his arms out. 'Ladies and gentlemen of {town_b}! The circus has sent us its finest wit! Look at it! It's thinking! You can hear it from here, like a cart on a cobbled street!'" { Assert jabTold(jos). }
  Relation jabTold(group).
  Query boutOpen(o: group, a: group) means inBout(o) and heckler(o) and at(a, ?r) and at(o, ?r) and not answered(a).
  Action answer_back(actor: group, foe: group, site: place) "Answer {foe} back, sharp, so the whole house hears it" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and boutOpen(foe, actor) and at(foe, site).
    Resolve check(actor, performance, dc_fair).
    On success { Decrease composure(foe) by 2 or to nothing. Assert answered(actor). }
    On failure { Decrease poise(actor) by 1 or to nothing. Assert answered(actor). }
    Result "You give it back to him, sharp and quick, and the house laughs at him, not you: a short bark of a laugh, the sound of a crowd changing sides.".
    Otherwise "You give it back to him and it comes out wrong, a little slow, a little proud, and he catches it in the air and throws it back, and the house laughs at you.".
  }
  Action agree_louder(actor: group, foe: group, site: place) "Agree with {foe}, louder than he said it" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and boutOpen(foe, actor) and at(foe, site).
    Resolve check(actor, persuasion, dc_easy).
    On success { Decrease composure(foe) by 1 or to nothing. Assert answered(actor). }
    On failure { Decrease poise(actor) by 1 or to nothing. Assert answered(actor). }
    Result "You agree with him. Enthusiastically. You go further than he did, you add things he had not thought of, you call on the house to witness how right he is, until he is standing there with his mouth open and nothing left to say against you that you have not said first.".
    Otherwise "You agree with him, and he says 'There you are, then,' and sits down satisfied, and somehow that is worse.".
  }
  Action fall_for_him(actor: group, foe: group, site: place) "Fall off the bench, as if his words had knocked you down" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and boutOpen(foe, actor) and at(foe, site) and fallLearned(actor).
    Resolve check(actor, tumbling, dc_fair).
    On success { Decrease composure(foe) by 2 or to nothing. Assert answered(actor). }
    On failure { Decrease poise(actor) by 1 or to nothing. Assert answered(actor). }
    Result "You clutch your heart as if shot, go down off the bench and roll the length of the gangway, and come to rest at his feet, and look up at him reproachfully, like Mumchance at his ladder. The house shrieks. He has nothing to say to a body at his feet.".
    Otherwise "You go down off the bench as if shot, and it is only a fall, and you bang your elbow, and he says 'Mind the furniture,' and they laugh at the elbow.".
  }
  Action feint_him(actor: group, foe: group, site: place) "Look past {foe}, as if at someone come in behind him" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and boutOpen(foe, actor) and at(foe, site) and feintLearned(actor).
    Resolve check(actor, deception, dc_easy).
    On success { Decrease composure(foe) by 2 or to nothing. Assert answered(actor). }
    On failure { Decrease poise(actor) by 1 or to nothing. Assert answered(actor). }
    Result "You stop. You look past his shoulder, at the flap, with a face of dawning horror, and nod very slightly as if to someone there, and he turns round to look; and the whole house laughs, because there is nobody there, and he has turned round in front of all of them.".
    Otherwise "You look past his shoulder at nothing, and he does not turn. 'Oldest trick in the book,' he says. 'My granny did that one.'".
  }
  Action give_look(actor: group, foe: group, site: place) "Say nothing, and give {foe} the Look" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and boutOpen(foe, actor) and at(foe, site) and lookLearned(actor).
    Resolve check(actor, performance, dc_easy).
    On success { Decrease composure(foe) by 3 or to nothing. Assert answered(actor). }
    On failure { Decrease poise(actor) by 1 or to nothing. Assert answered(actor). }
    Result "You say nothing. You look at him. You wait until the house has finished turning to see what you will do; and then a little longer; and then you look at him the way Mumchance looks at the ladder. He opens his mouth. He shuts it. The house, which has been holding its breath, lets it out in a roar, and he sits down.".
    Otherwise "You say nothing and look at him, and hold it a beat too long, and he says, 'It's stopped. Somebody wind it up,' and the house roars.".
  }
  Rule bout_next when inBout(?o) and answered(party) and composure(?o) >= 1 and poise(party) >= 1 and jab(?o) < 3 {
    Increase jab(?o) by 1. Retract answered(party). Retract jabTold(?o). }
  Rule bout_won when inBout(?o) and composure(?o) < 1 and current(wapshotts, ?g)
    says "{?o} sits down. Then, after a moment, from the seat, he begins to clap, slowly, and the whole house claps with him, and it is for you." {
    Retract inBout(?o). Assert boutWon(party, ?o). Increase standing(?g) by 1. Increase renown(party) by 1. Assert wonABout(party). }
  Rule bout_lost when inBout(?o) and poise(party) < 1
    says "The house is laughing at you, kindly, the way it laughs at a dog that has fallen in a pond, and {?o} bows to all sides. You have lost the house tonight. Behind the curtain Mumchance has seen it all, and nods to you, as if to say: now you know where the floor is." {
    Retract inBout(?o). Assert boutLost(party, ?o). }
  Rule bout_drawn when inBout(?o) and answered(party) and jab(?o) >= 3 and composure(?o) >= 1 and poise(party) >= 1
    says "The house has stopped knowing whose side it is on, and so has {?o}. He sits down muttering, and the show goes on round you both." {
    Retract inBout(?o). }
  Rule bout_ends_with_show when inBout(?o) and not showOn(wapshotts) and not boutAtFair(?o) { Retract inBout(?o). }
  Relation boutAtFair(group). Relation wonABout(group).
  Rule answer_learned when wonABout(party) and not answerLearned(party) and fallLearned(party)
    says "On the way out through the backyard Mumchance falls into step beside you, and walks a while, and says only: 'That was the Answer.' Then he goes to bed." {
    Assert answerLearned(party). Assert teaches(mumchance, vicious_mockery). }
  Topic jos_beaten with jos "Ask Jos whether he has forgiven you" when boutWon(actor, jos) once {
    Says "Jos takes a nail out of his mouth and points it at you. 'Nine years,' he says, 'I've been beaten by nobody in {town_b} but my wife. You're the second.' He puts the nail back, and talks round it. 'Come back next round. I'll have something new. I'll have been up nights.' He grins, which you have never seen. 'Here: give us your boots. I'll do the heels for nothing. A wit wants good heels.'".
    On discuss { Increase regard(jos) by 2. }
  }
  Topic jos_won with jos "Ask Jos how you could have answered him" when boutLost(actor, jos) and not boutWon(actor, jos) once {
    Says "'Don't argue,' says Jos. 'Never argue. Everybody in the house is cleverer than you when you're arguing. Make 'em look at something.' He hammers. 'Your old clown knows. He just looks. Drives me mad.'".
  }

  // ── Pastimes of the ground ──────────────────────────────────────────────────────────────────────────────────
  // Wapshott's Grand Gurning Match: at three on the second day of a stand, on the front, a crown to the ugliest.
  Relation gurnOn(concern). Measure gurnDay(concern). Relation gurned(group). Relation gurnEntered(group).
  Rule gurn_starts when pitched(wapshotts) and day(clock) == arrivedDay(wapshotts) + 1 and hour(clock) >= 15 and hour(clock) < 16 and gurnDay(wapshotts) < day(clock) {
    Assert gurnOn(wapshotts). Set gurnDay(wapshotts) to day(clock). Retract gurnEntered(party). }
  Rule gurn_ends when gurnOn(wapshotts) and hour(clock) >= 16 { Retract gurnOn(wapshotts). }
  Rule gurn_seen near pole when gurnOn(wapshotts) and not gurnTold(wapshotts)
    says "On the front of the big top a horse-collar hangs from a pole, and the Colonel is standing on a barrel beside it bellowing: 'WAPSHOTT'S GRAND GURNING MATCH! A CROWN TO THE UGLIEST FACE IN THE COUNTRY! PUT YOUR HEAD THROUGH THE COLLAR AND DO YOUR WORST!' A line of townspeople waits to put their heads through the horse-collar and pull faces. Honoria Bulstrode is in the line. She enters every time. She has never won. She is too kind in the face." { Assert gurnTold(wapshotts). }
  Relation gurnTold(concern).
  Rule gurn_told_reset when gurnTold(wapshotts) and not gurnOn(wapshotts) { Retract gurnTold(wapshotts). }
  Action gurn(actor: group, site: place) "Put your head through the horse-collar and pull the worst face you can" {
    Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and gurnOn(wapshotts) and at(pole, site) and not gurnEntered(actor) and not lookLearned(actor).
    Resolve check(actor, performance, dc_hard).
    On success { Assert gurnEntered(actor). Increase quantity(actor, gold) by 3. Assert gurned(actor). Increase renown(actor) by 1. }
    On failure { Assert gurnEntered(actor). }
    Result "You put your head through the collar and do something with your face that you did not know your face could do. A child screams. A man drops his pie. The Colonel, who has seen everything, takes a step back off his barrel. 'THE WINNER,' he roars, from the grass, 'AND I NEVER WANT TO SEE IT AGAIN,' and gives you the crown, which is three coin in a twist of paper.".
    Otherwise "You put your head through the collar and pull your face, and it is a good face, and the next man in the line is a thatcher from up the road who has no teeth and has been practising since Lady Day, and he wins.".
  }
  Action gurn_look(actor: group, site: place) "Put your head through the horse-collar and give the town the Look" {
    Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and gurnOn(wapshotts) and at(pole, site) and not gurnEntered(actor) and lookLearned(actor).
    Resolve check(actor, performance, dc_fair).
    On success { Assert gurnEntered(actor). Increase quantity(actor, gold) by 3. Assert gurned(actor). Increase renown(actor) by 1. }
    On failure { Assert gurnEntered(actor). }
    Result "You put your head through the collar and pull no face at all. You just look at them, the whole waiting line, with Mumchance's look, the one that says the world has done this to you personally; and you hold it, and hold it, until the face you are not pulling is worse than any face could be. The thatcher with no teeth concedes. The Colonel gives you the crown with his eyes shut.".
    Otherwise "You give them the Look through the collar, and they wait for the face, and there is no face, and they think you have not started yet, and the thatcher with no teeth goes past you and wins.".
  }
  // Arm-wrestling the Ox, once a day, at the cookhouse table.
  Measure wrestledDay(group). Relation beatHonoria(group).
  Action wrestle_honoria(actor: group, site: place) "Arm-wrestle Honoria Bulstrode across the cookhouse table" {
    Speaker honoria. Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and at(honoria, site) and freeHour() and wrestledDay(actor) < day(clock).
    Resolve check(actor, brawn, dc_formidable).
    On success { Set wrestledDay(actor) to day(clock). Assert beatHonoria(actor). Increase regard(honoria) by 1. }
    On failure { Set wrestledDay(actor) to day(clock). }
    Result "Honoria sets her elbow on the table, takes your hand, and smiles at you encouragingly. You heave. She lets you get her arm halfway down, out of politeness; then something happens to her face, a small surprised respect, and you put her hand flat on the boards. The backyard goes dead silent. Then Honoria laughs till she cries, and kisses you on the forehead, and tells everyone, and goes on telling them for a week.".
    Otherwise "Honoria sets her elbow on the table, takes your hand, and smiles at you encouragingly while you heave. Then, very gently, as if putting a baby down, she lays the back of your hand on the table. 'There,' she says. 'Have a bun.'".
  }
  Topic honoria_beaten with honoria "Ask Honoria whether she has forgiven you for the arm-wrestling" when beatHonoria(actor) once {
    Says "'Forgiven you?' says Honoria. 'My love, I've told every soul in the circus and two in the town. Nobody's put my hand down since the slate-cart.' She pats your arm, carefully, the way you would pat a cannon. 'Mind, I'd a bad shoulder that day. We'll have it again at the Fair, in front of people.'".
  }
  Topic pip_gurn with pip "Ask Pip what she made of your face at the gurning" when gurned(actor) once {
    Says "'It was horrible,' says Pip, with deep respect. 'A baby cried. Two babies. A dog went under a cart and wouldn't come out.' She tries to do it herself, and can't, and falls over trying. 'Will you teach me? Mumchance says a face is a door; you have to know which way it opens.'".
  }
  // Pip at the juggling: three things, any three.
  Relation juggled(group).
  Action juggle_pip(actor: group, site: place) "Let Pip teach you to juggle three oranges" {
    Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and at(pip, site) and freeHour() and not juggled(actor).
    On success { Assert juggled(actor). Increase regard(pip) by 1. }
    Result "Pip teaches you with three oranges, then three potatoes, then two potatoes and a hedgehog, which is a mistake. By the end you can keep three things in the air for the count of nine, and Pip says you're a natural, and then says she says that to everyone, and then says it's true this time, sort of.".
  }
}

data/goings-on/circus/art2.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── The Gentle Art, second degree ───────────────────────────────────────────────────────────────────────────
  // After the four foundations: the Riposte (Mumchance: to be where the blow is not, and let it land on its thrower),
  // the Echo (Mother Pell: to give back a voice, which is attention with the volume up), and the Reversal, which only
  // the two of them together can teach, because it was their act: the mirror-door of Pell and Fell, the first
  // disciplined imitation, a body that gives back another body's movement. Mumchance calls it the door to the
  // Mirror, and not the Mirror.
  Relation riposteLearned(group). Relation echoLearned(group). Relation reversalLearned(group). Relation courtTaught(group).
  Measure triedRiposteDay(group). Measure triedEchoDay(group). Measure triedReversalDay(group). Relation madePellLaugh(group).
  Relation partnered(group). Relation partnerRehearsed(group). Relation pipReady(group). Relation knowsWhyNow(group).

  Topic mum_why_now with mumchance "Ask Mumchance about the Riposte" when answerLearned(actor) and letterCome(wapshotts) once {
    Says "Mumchance does not answer at once. He is looking at the King's Rest on its hill, or at where it would be from here. 'I said I'd teach the four,' he says. 'I've taught the four. The fifth I never taught anybody. My father taught it me with a sword, and I never found anyone I wanted to give it to with a custard.' He turns on his bucket. 'The knees are seventy. I'd like to show it you while I can still be where the blow isn't.' A pause. 'And there's the Revels. The ladder for two, before the Household of the Progress. I've thought about that ladder for forty years. I never had a second.'".
    On discuss { Assert knowsWhyNow(actor). }
  }
  Topic mum_partner with mumchance "Tell Mumchance you will be his second on the ladder at the Revels" when knowsWhyNow(actor) and not partnered(actor) once {
    Says "Mumchance holds out his hand. It is the second time. 'The ladder for two,' he says. 'One climbs, one helps; the one who helps is the joke. You'll be the one who helps.' He almost smiles. 'It was Polly's part. She did it with her mouth. You'll have to do it with your feet.'".
    On discuss { Assert partnered(actor). Increase regard(mumchance) by 2. }
  }
  Action rehearse_partner(actor: group, site: place) "Rehearse the ladder for two with Mumchance, in the empty ring" {
    Time 12.
    Requires able(actor) and company(actor) and at(actor, site) and at(mumchance, site) and partnered(actor) and freeHour() and not partnerRehearsed(actor).
    Resolve check(actor, tumbling, dc_fair).
    On success { Assert partnerRehearsed(actor). }
    Result "Two hours in the empty ring with the ladder. He climbs; you help; he falls. You learn where to stand so that your help is always a foot to the left of where it is needed, and how long to look at him when he lands, and that the whole thing is a conversation in which you never once say a word. At the end he lies in the sawdust and you stand over him with the ladder, and he says, without moving, 'Again,' and you know that it is good.".
    Otherwise "Two hours with the ladder, and every time he falls you catch him, out of kindness, which ruins it. 'Don't help,' he says. 'Help wrongly. Tomorrow.'".
  }
  Action learn_riposte(actor: group, site: place) "Learn the Riposte from Mumchance: stand in the ring while he throws custards" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(mumchance, site) and knowsWhyNow(actor) and answerLearned(actor) and freeHour()
      and not riposteLearned(actor) and triedRiposteDay(actor) < day(clock).
    Resolve check(actor, tumbling, dc_hard).
    On success { Assert riposteLearned(actor). Assert teaches(mumchance, riposte). Increase regard(mumchance) by 1. }
    On failure { Set triedRiposteDay(actor) to day(clock). }
    Result "Honoria makes him a bucket of custard. He stands at one side of the ring and throws, with a fencing-master's wrist, and for the first hour every custard finds you. 'You're getting out of the way,' he says. 'Don't get out of the way. Be where it isn't, and leave something where it is.' In the second hour you learn to leave your hat. In the third a custard leaves his hand, and you are not where it goes, and your hat is, and it goes past your hat and on, all the way, into Pip's face where she is sitting on the ring boards. Mumchance sits down in the sawdust and laughs till he cannot get up. 'That,' he says, wiping his eyes, 'is the Riposte. The blow goes on to someone who deserved it more.'".
    Otherwise "Three hours of custard. You go to bed yellow. 'Tomorrow,' says Mumchance. 'Honoria will make more. She thinks it's good for you.'".
  }
  Action amuse_pell(actor: group, site: place) "Give Mother Pell Mumchance's look, the one at the ladder" {
    Speaker motherpell. Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and at(motherpell, site) and lookLearned(actor) and not madePellLaugh(actor).
    Resolve check(actor, performance, dc_fair).
    On success { Assert madePellLaugh(actor). Increase regard(motherpell) by 2. }
    Result "You give her the Look: Mumchance's, at the ladder, the one that says the world has done this to you personally. Mother Pell stares. Then she laughs so hard the bath-chair rolls a yard backward, and she has to be fetched. 'Gus Fell,' she says, wiping her eyes with a shawl. 'Gus Fell to the life. He's given you his face. The old fool's given somebody his face.'".
    Otherwise "You give her the Look. 'Very nice,' she says. 'Whose is it meant to be?'".
  }
  Action learn_echo(actor: group, site: place) "Ask Mother Pell to teach you the voices" {
    Speaker motherpell. Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(motherpell, site) and (madePellLaugh(actor) or regard(motherpell) >= 2) and not echoLearned(actor)
      and triedEchoDay(actor) < day(clock).
    Resolve check(actor, performance, dc_fair).
    On success { Assert echoLearned(actor). Assert teaches(motherpell, echo). Assert canTurn(actor, turn_voices). }
    On failure { Set triedEchoDay(actor) to day(clock). }
    Result "An hour beside the bath-chair while the town goes by, with Mother Pell giving you voices like sweets: the innkeeper, a goose, Augustus, Augustus as a goose. 'Don't copy,' she says. 'Copying is mockery, and mockery is cheap. Listen. Listen till you could love them for an hour. Then give it them back.' Toward the end a carter passes, cursing his horse, and you give him back his own curse, in his own voice, and he stops and turns round, quite certain his brother is behind him. Mother Pell claps her mittens. 'The Echo,' she says. 'First step to the Mirror, Gus would say. He only says that because he never could do it.'".
    Otherwise "An hour of voices, and every one of them comes out as you doing a voice. 'You're listening to yourself,' says Mother Pell. 'Listen to them. Tomorrow.'".
  }
  Action learn_reversal(actor: group, site: place) "Ask Pell and Fell to teach you the mirror-door together" {
    Time 12.
    Requires able(actor) and company(actor) and at(actor, site) and at(mumchance, site) and at(motherpell, site) and pellAndFellMet(mumchance) and riposteLearned(actor) and echoLearned(actor)
      and not reversalLearned(actor) and triedReversalDay(actor) < day(clock).
    Resolve check(actor, tumbling, dc_hard).
    On success { Assert reversalLearned(actor). Assert teaches(mumchance, reversal). Increase regard(mumchance) by 1. Increase regard(motherpell) by 1. }
    On failure { Set triedReversalDay(actor) to day(clock). }
    Result "On the green stage of the Revels Hall, with Mother Pell calling it from her chair and Mumchance on his bad knees, they show you the mirror-door: two people either side of an empty frame, each the other's reflection, until one of them moves first and the other does not follow, and the whole house screams. 'It isn't copying,' says Mother Pell. 'It's giving back.' 'It's where the weight goes,' says Mumchance. You learn it for two hours, his movement in your body, her timing in your ear, until, at the end, he lunges at the frame and you give his lunge back to him, exactly, and he goes over his own feet and down. He lies there. 'That's the Reversal,' he says from the boards. 'A man's own weight, given back. The door to the Mirror.' He looks up at the green ceiling of the hall. 'Not the Mirror. The door.'".
    Otherwise "Two hours at the mirror-door, and you are always a hair late, so that you are not a mirror but a person copying. 'Again tomorrow,' they say, together, and look at each other, startled.".
  }
  // In a bout of words: the Echo gives a heckler his own voice; the Riposte lets his jab land on someone else.
  Action echo_him(actor: group, foe: group, site: place) "Give {foe} back his own voice, word for word" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and boutOpen(foe, actor) and at(foe, site) and echoLearned(actor).
    Resolve check(actor, performance, dc_easy).
    On success { Decrease composure(foe) by 3 or to nothing. Assert answered(actor). }
    On failure { Decrease poise(actor) by 1 or to nothing. Assert answered(actor). }
    Result "You give it back to him: his own words, in his own voice, his own pause, the little sniff he does not know he does; and the house hears the sniff, and is lost, and he hears it too, and does not know where to put his face.".
    Otherwise "You give him his own voice, and it comes out as somebody's uncle.".
  }
  Action riposte_him(actor: group, foe: group, site: place) "Let {foe}'s jab land on someone who deserves it more" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and boutOpen(foe, actor) and at(foe, site) and riposteLearned(actor).
    Resolve check(actor, deception, dc_fair).
    On success { Decrease composure(foe) by 3 or to nothing. Assert answered(actor). }
    On failure { Decrease poise(actor) by 1 or to nothing. Assert answered(actor). }
    Result "You agree that someone in this room is everything he says; and then, without a word, you turn and look at him, so that the whole house turns with you, and everything he said is now about him.".
    Otherwise "You try to pass it on, and there is nobody to pass it to, and it stays on you.".
  }

  // A turn of voices, for one who has the Echo.
  Entity turn_voices: turnkind "a turn of voices and imitations".
  Topic book_voices with wapshott "Ask the Colonel to put you on tonight in a turn of voices" when auditioned(actor) and canTurn(actor, turn_voices) and not booked(actor, turn_voices) and not onTurn(actor) {
    Says "'Voices!' says the Colonel. 'Do mine.' You do his. He listens with his head on one side, and then, slowly, goes red. 'I do not sound like that,' he says, in exactly the voice you used. 'After the Ox. Leave me out of it.'".
    On discuss { Assert booked(actor, turn_voices). }
  }
  Rule voices_triumph near ringpost when triumph(party) and booked(party, turn_voices)
    says "You give the house itself back to itself: the innkeeper, the priest, the man who sells eels, the Colonel at the top of his voice; and then, at the end, very quietly, Mumchance, who never speaks, saying 'Again.' The tent comes apart. In the wings Mumchance has his hand over his eyes." {
    Assert turnPaid(party). Increase regard(mumchance) by 1. }
  Rule voices_fair near ringpost when fairTurn(party) and booked(party, turn_voices)
    says "You do the town's voices, and the house knows every one, and laughs at its neighbours, which is the safest kind of laugh there is." { Assert turnPaid(party). }
  Rule voices_flop near ringpost when flop(party) and booked(party, turn_voices)
    says "You do the town's voices, and they are all the same voice, and it is yours, and a man in the front row asks who you are meant to be." { Assert turnPaid(party). }
  Action turn_bold_voices(actor: group, site: place) "Go for the big finish: the Colonel's own voice, to his face" {
    Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and onTurn(actor) and not turnChosen(actor) and booked(actor, turn_voices).
    Resolve check(actor, performance, dc_hard).
    On success { Assert turnChosen(actor). Increase turnScore(actor) by 4. }
    On failure { Assert turnChosen(actor). Decrease turnScore(actor) by 1 or to nothing. }
    Result "You turn to the Colonel, in the middle of his own ring, and become him: the chest, the moustache, the LADIES AND GENTLEMEN, the tears at the right moment. He stands it for ten seconds. Then he starts to laugh, helplessly, the first time anyone in the circus has seen him laugh at himself, and the house sees it, and that is the end of everybody.".
    Otherwise "You turn to the Colonel and become him, and he does not laugh. He looks at you like a man shown a portrait he paid for and did not like.".
  }

  // ── The forms of a court, from Hench ────────────────────────────────────────────────────────────────────────
  Action learn_court(actor: group, site: place) "Ask Hench to teach you the forms of a court" {
    Speaker hench. Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(hench, site) and knows(actor, letter_known) and not courtTaught(actor).
    Resolve check(actor, insight, dc_fair).
    On success { Assert courtTaught(actor). Increase regard(hench) by 1. }
    Result "Hench sets two chairs in the wardrobe wagon, one for the Dowager and one for the Steward, and puts a hatbox on each, and for an hour you bow to hatboxes. 'One does not turn one's back on the dais. One does not laugh until Her Serene Highness has laughed, and then one laughs a little less. One does not speak to a dowager who is also an archduchess until she has decided which she is today; she will tell you by the hand she offers.' He corrects your knee with his tape-measure. 'And one never, ever, explains a joke at court. If a joke has to be explained at court, one has simply died, and must lie still.' At the end you can bow to a hatbox as if it owned a country, and Hench, for the first time, says 'Good.'".
    Otherwise "An hour of bowing to hatboxes, and every bow is a bow to a hatbox. 'You are sincere,' says Hench with distaste. 'At court that is mistaken for impertinence.'".
  }

  // ── Pip's first entrée ───────────────────────────────────────────────────────────────────────────────────────
  Topic pip_entree with pip "Ask Pip whether she has an entrée of her own for the Revels" when letterCome(wapshotts) and fallLearned(actor) and not pipReady(pip) and not travelsWith(pip, actor) once {
    Says "Pip goes pink. 'Mumchance said I could go on at the Revels. Alone. Three minutes.' She twists her nose in her pocket. 'I've got the start, I fall off a barrel. I've got the end, I bow to the wrong person. I haven't got the middle. Everybody says the middle's where the joke is.' She looks at you. 'You've done the four. Would you,' she says, very fast, 'help.'".
    On discuss { Assert pipAsked(pip). }
  }
  Relation pipAsked(group).
  Action help_pip(actor: group, site: place) "Work out Pip's entrée with her, the middle of it" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(pip, site) and pipAsked(pip) and freeHour() and not pipReady(pip).
    Resolve check(actor, performance, dc_fair).
    On success { Assert pipReady(pip). Increase regard(pip) by 2. }
    Result "You work it out together in the backyard among the washing, with Pip falling off the barrel forty times: and the middle, it turns out, is the get-up. She falls off the barrel, and gets up, and the barrel is still there, and she looks at it, and decides to forgive it, and goes to shake its hand, and it rolls away. She does it once more and you laugh out loud before you can stop, and she stops dead and stares at you. 'That's it,' she says. 'That's it, isn't it? Oh, Mumchance is going to be so cross I didn't ask him.'".
    Otherwise "You try the middle a dozen ways, and every one is a joke you can see coming. 'Tomorrow,' says Pip, who has started to sound exactly like Mumchance.".
  }
}

data/goings-on/circus/endings.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── Act IV, the physical half: water, meat, fever, the tide, the night, the reef ──────────────────────────────────
  // The party are staff and passengers of a patron's expedition. What presses is a hold of water and meat that does
  // not last the tide, a reef passage that closes on a date and can leave the Sundial aground for a month, the delta's
  // fever, the tyrant at dusk, and one night on the quay. Nobody judges anybody. The Colonel decides what he takes
  // from what he has done and seen, and it costs someone.
  Relation huntOn(concern). Relation huntDone(concern). Relation huntClean(concern). Relation refuged(group). Relation firesLit(group).
  Relation huntDiverted(group). Relation crewLost(concern). Relation crewHurt(concern). Relation colonelDragged(concern).
  Relation colonelHurt(concern). Relation colonelStays(concern). Relation fever(group). Relation feverHit(group). Relation hullHoled(concern).
  Relation tideMarked(concern). Relation reefRun(concern). Relation springKnown(group). Relation specimensCaught(concern).
  Relation fenwickWants(concern). Relation hunted(group). Relation huntAbsent(concern). Relation dragTried(concern). Relation colonelWentIn(concern). Relation billieGlad(concern).
  Measure packDay(concern). Measure reefDay(concern). Measure landDay(concern). Measure huntAt(concern). Measure waterCasks(concern). Measure drankDay(concern). Measure feverDay(concern). Measure thirstDay(concern). Measure huntedDay(group).

  // ── The camp ─────────────────────────────────────────────────────────────────────────────────────────────────────
  Person mudge "Mr Mudge" at deck {
    Role "bosun of the Sundial". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "'MUDGE!' shouts a barrel of a man, from a yard away. 'Bosun! Who's for biscuit?' Crewe has told him about his voice. He has taken it as praise.".
  }
  Initially Assert offstage(mudge).
  Rule mudge_aboard when voyaged(wapshotts) and offstage(mudge) { Retract offstage(mudge). Assert at(mudge, deck). }
  Person nunn "Aggie Nunn" at deck {
    Role "cook of the Sundial". Ancestry human. Peaceable. Pronouns she. Manner cheerful.
    Greets "'Stew,' says Aggie Nunn. 'You'll not be wanting to ask what. I'll tell you on the way home, if there's a way home.' She stirs it with her arm.".
  }
  Initially Assert offstage(nunn).
  Rule nunn_aboard when voyaged(wapshotts) and offstage(nunn) { Retract offstage(nunn). Assert at(nunn, deck). }
  Topic nunn_stew with nunn "Ask Aggie what is in the stew" when true {
    Says "'Biscuit,' says Aggie. 'And Mr Mudge's opinion. He puts it in.'".
  }
  Entity pack_night_known: fact "Harrow's net-men say the pack comes to the quay on the fifth night.".
  Topic mudge_pack with mudge "Ask Mr Mudge why the net-men sit with their backs to the cages" when berthS(wapshotts) {
    Says "'FIFTH NIGHT!' says Mr Mudge. 'Harrow's lads say the little ones come for the egg-smell on the fifth night. They sit by the fire. I sit by the fire. We are none of us going to the cages without a reason.'".
    On discuss { Assert knows(actor, pack_night_known). }
  }
  Topic mudge_tide with mudge "Ask Mr Mudge about the reef" when berthS(wapshotts) {
    Says "'NINE DAYS!' says Mr Mudge. 'Reef's a gate and the gate shuts on the ninth. Then she's aground till the spring tide, and that's a month, and we eat the cook.' He laughs until the deck shakes. 'She doesn't mind. She's tough.'".
  }
  Rule tide_marks when berthS(wapshotts) and not tideMarked(wapshotts) {
    Assert tideMarked(wapshotts). Set reefDay(wapshotts) to day(clock) + 9. Set landDay(wapshotts) to day(clock). Set waterCasks(wapshotts) to 4.
    Increase quantity(party, rations) by 4.
    Assert away(mudge). Assert at(mudge, landing). Assert away(nunn). Assert at(nunn, landing). }
  Observe tide_board at landing when tideMarked(wapshotts) "A tide table is cut into the quay's last post under the wheel: nine notches, and over the ninth a bar. Mr Mudge has chalked beside it: SHUT.".
  Observe camp_scene at landing when tideMarked(wapshotts) "The camp is a ring of four casks, two tarpaulins and Aggie Nunn's fire on the quay. Billie's crates are stacked by the first cage, and the Colonel's trumpet hangs from a post.".
  Rule drink_day when (berthS(wapshotts) or within(party, sarn)) and tideMarked(wapshotts) and hour(clock) == 7 and drankDay(wapshotts) < day(clock) {
    Set drankDay(wapshotts) to day(clock). Decrease waterCasks(wapshotts) by 1 or to nothing. }
  Hazard thirst_day "A dry day" means "Deal (1d6) physical damage to ally unless constitution save against (13). Apply weakened to ally for 24 hours unless constitution save against (13).".
  Rule thirst_bites when (berthS(wapshotts) or within(party, sarn)) and tideMarked(wapshotts) and waterCasks(wapshotts) == 0 and hour(clock) == 10 and thirstDay(wapshotts) < day(clock)
    says "The last cask is dry. Mr Mudge turns it over, shakes it, and sets it down like a friend who has let him down." {
    Set thirstDay(wapshotts) to day(clock). Assert strikes(thirst_day, party). }
  Rule water_low when (berthS(wapshotts) or within(party, sarn)) and tideMarked(wapshotts) and waterCasks(wapshotts) == 1 and hour(clock) == 8 and drankDay(wapshotts) == day(clock) and tallyDay(wapshotts) < day(clock)
    says "Mr Mudge taps the last cask with his knuckle and, for once, says it quietly. 'One,' he says. 'One cask, and a spring in the forest if somebody can follow the runners.'" { Set tallyDay(wapshotts) to day(clock). }
  Measure tallyDay(concern).
  Rule rations_low when (berthS(wapshotts) or within(party, sarn)) and tideMarked(wapshotts) and quantity(party, rations) < 2 and hour(clock) == 8 and rationTallyDay(wapshotts) < day(clock)
    says "Aggie Nunn lifts the lid of the biscuit barrel, looks in, and puts the lid back. 'Meat,' she says, to the air. 'Somebody's going to want to find me meat.'" { Set rationTallyDay(wapshotts) to day(clock). }
  Measure rationTallyDay(concern).
  Observe casks_low at landing when tideMarked(wapshotts) and waterCasks(wapshotts) < 3 "Two casks, or one. Mr Mudge has stopped joking about it.".
  Action fill_casks(actor: group, site: place) "Fill the casks at the spring" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, kingsfoil_hollow) and tideMarked(wapshotts) and knows(actor, spring_known) and waterCasks(wapshotts) < 4.
    Time 2 hours.
    On success { Increase waterCasks(wapshotts) by 3. }
    Result "The spring comes up cold out of the rock. It is two hours back to the quay with the casks on your shoulders.".
  }
  Entity spring_known: fact "A spring rises in the sheltered hollow; the fern-runners go there at noon to drink.".
  Action follow_runners(actor: group, site: place) "Follow the fern-runners when they go off together at noon" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, forest_edge) and hour(clock) >= 11 and hour(clock) < 14 and not springKnown(party).
    Time 3 hours.
    Resolve check(actor, woodcraft, dc_fair).
    On success { Assert springKnown(party). Assert knows(actor, spring_known). Assert knows(actor, hollow_way_known). }
    Result "They run in a line, stopping, starting, looking back. They go under the cycads and over a log, and out through a notch of bank to a pool in a hollow, and drink one at a time with their heads up. You drink after them.".
    Otherwise "They look back at you once, together, and go in six directions.".
  }
  Observe spring_taught at kingsfoil_hollow when true "A spring comes out of the rock at the bank's foot, clear and cold, into a pool no larger than a bath." teaches spring_known.
  Action hunt_meat(actor: group, site: place) "Spend the morning hunting for the camp's pot" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, forest_edge) or at(actor, plain_south) or at(actor, delta_edge)) and hour(clock) >= 5 and hour(clock) < 10 and huntedDay(party) < day(clock).
    Time 4 hours.
    Resolve check(actor, woodcraft, dc_fair).
    On success { Set huntedDay(party) to day(clock). Increase quantity(party, rations) by 3. }
    On failure { Set huntedDay(party) to day(clock). Assert strikes(hunt_scrape, party). }
    Result "A stilt-runner too slow, or too trusting. It is not a fair trade and nobody says so; it is three days' meat, hung in the shade.".
    Otherwise "You come back empty and scratched, with a rattle of small things in the brush laughing at you.".
  }
  Hazard hunt_scrape "A morning in the brush" means "Deal (1d6) physical damage to ally unless dexterity save against (12).".

  // ── The fever ────────────────────────────────────────────────────────────────────────────────────────────────────
  Hazard marsh_fever "The delta fever" means "Deal (1d4) poison damage to ally unless constitution save against (13). Apply weakened to ally for 24 hours unless constitution save against (13).".
  Rule fever_comes when tideMarked(wapshotts) and hour(clock) == 5 and dice(clock) <= 4 and not fever(party)
    and (at(party, landing) or at(party, delta_edge) or at(party, egg_beds) or at(party, harrow_camp) or at(party, wreck_camp) or at(party, channels)) {
    Assert fever(party). Set feverDay(wapshotts) to day(clock). }
  Rule fever_warns when fever(party) and feverBites(wapshotts) == 0 and hour(clock) == 18 and day(clock) == feverDay(wapshotts) + 1 and (berthS(wapshotts) or within(party, sarn))
    says "Mr Mudge has stopped shouting. He is sitting by the fire with his collar turned up, shivering in the heat. 'Nothing,' he says. 'Delta damp.' By the look of the sweat on him it is the fever, and it will come for the rest of you in a day or so. Kingsfoil, or feverwort, or a hard few days." { }
  Measure feverBites(concern).
  Rule fever_bites when fever(party) and day(clock) >= feverDay(wapshotts) + 2 and hour(clock) == 8 and feverBiteDay(wapshotts) + 2 <= day(clock) and feverBites(wapshotts) < 3 { Set feverBiteDay(wapshotts) to day(clock). Increase feverBites(wapshotts) by 1. Assert feverHit(party). Assert strikes(marsh_fever, party). }
  Rule fever_bites_told when feverHit(party) and fever(party) and hour(clock) == 8 and feverBiteDay(wapshotts) == day(clock) says "The shaking comes on in the early light, all at once, like a cart going over. The delta fever has its dues." { }
  Observe fever_shakes at landing when feverHit(party) and fever(party) "The shaking starts in the hands. By noon nobody is making jokes, and Aggie Nunn has put her stew down.".
  Hazard hunger_day "An empty day" means "Deal (1d6) physical damage to ally unless constitution save against (12). Apply weakened to ally for 24 hours unless constitution save against (13).".
  Rule hunger_bites when (berthS(wapshotts) or within(party, sarn)) and tideMarked(wapshotts) and quantity(party, rations) < 1 and hour(clock) == 9 and hungerDay(wapshotts) < day(clock) { Set hungerDay(wapshotts) to day(clock). Assert strikes(hunger_day, party). }
  Measure hungerDay(concern). Measure feverBiteDay(concern).
  Action dose_kingsfoil(actor: group, site: place) "Steep a sprig of kingsfoil and make the sick drink it" {
    Requires able(actor) and company(actor) and at(actor, site) and fever(party) and holding(actor, kingsfoil).
    Time 0.
    On success { Spend kingsfoil from actor. Retract fever(party). Retract feverHit(party). }
    Result "The smell is clean and sharp in the wet heat. By morning the shaking has stopped.".
  }
  Action dose_feverwort(actor: group, site: place) "Steep feverwort and make the sick drink it" {
    Requires able(actor) and company(actor) and at(actor, site) and fever(party) and holding(actor, feverwort).
    Time 0.
    On success { Spend feverwort from actor. Retract fever(party). Retract feverHit(party). }
    Result "It is bitter. It does what it does.".
  }

  // ── The night: the pack comes to the quay, three times ──────────────────────────────────────────────────────────
  Person night_pack "the pack at the camp" at hook_den {
    Role "five hook-claws". Species hook_claw. Level 3. Numbers 5. Peaceable.
  }
  Initially Assert offstage(night_pack).
  Rule hunt_starts when (berthS(wapshotts) or within(party, sarn)) and tideMarked(wapshotts) and day(clock) >= landDay(wapshotts) + 5 and hour(clock) >= 22 and not huntOn(wapshotts) and packDay(wapshotts) < day(clock) {
    Assert huntOn(wapshotts). Set huntAt(wapshotts) to watch(clock). Set packDay(wapshotts) to day(clock). Retract refuged(party). Retract firesLit(party). Retract huntDiverted(party). Retract dragTried(wapshotts). Retract huntClean(wapshotts). Retract offstage(night_pack). }
  Observe pack_sign at landing when tideMarked(wapshotts) and day(clock) >= landDay(wapshotts) + 3 and day(clock) < landDay(wapshotts) + 5 and hour(clock) >= 5 and hour(clock) < 11 "In the sand round the camp, outside the firelight, there are prints in a ring: three-toed, a hand wide, a long stride and a short, and one deep scrape where something has sat on its haunches and watched the casks all night. Mr Mudge walks round them twice and says nothing for a quarter of an hour.".
  Observe pack_dusk at landing when tideMarked(wapshotts) and day(clock) >= landDay(wapshotts) + 5 and hour(clock) >= 18 and hour(clock) < 22 and not huntOn(wapshotts) "At the edge of the forest, as the light goes, the clicking begins. It is not loud. It is simply, all round the quay, where the dark is.".
  Rule pack_to_quay when huntOn(wapshotts) and not at(night_pack, landing) { Assert at(night_pack, landing). }
  Observe hunt_first near night_pack when huntOn(wapshotts) and watch(clock) < huntAt(wapshotts) + 12 "The click stops all round the quay. Eyes: a row of them at the edge of the firelight, low, not blinking. Mr Mudge, who has been talking, is not.".
  Observe hunt_second near night_pack when huntOn(wapshotts) and watch(clock) >= huntAt(wapshotts) + 12 and watch(clock) < huntAt(wapshotts) + 24 "They have come closer. One of them is walking the tarpaulin's edge, lifting a foot clear of the ground and setting it down. Another is at the cask-stack, working a rope with its teeth.".
  Observe hunt_third near night_pack when huntOn(wapshotts) and watch(clock) >= huntAt(wapshotts) + 24 "The first cage door rings. Something has put a claw through the bars and is testing the bar.".
  Observe hunt_colonel near wapshott when huntOn(wapshotts) and not colonelDragged(wapshotts) "The Colonel has taken his trumpet down from the post. He is going out to meet it.".
  Rule colonel_goes_in when huntOn(wapshotts) and colonelHumbled() and not colonelCovered(wapshotts) and not colonelDragged(wapshotts) { Assert colonelDragged(wapshotts). Assert colonelWentIn(wapshotts). }
  Observe colonel_went_in near wapshott when colonelWentIn(wapshotts) and huntOn(wapshotts) "The Colonel has hung the trumpet back on its post, unblown, and gone into the nearest cage of his own accord. He is sitting on the floor of it with his knees up, like a man in a pew.".
  Action shut_cages(actor: group, site: place) "Shut as many as will fit into the Wardens' cages and drop the bar" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, landing) or at(actor, cage_row)) and huntOn(wapshotts) and not refuged(party).
    Time 0.
    Resolve check(actor, brawn, dc_fair).
    On success { Assert refuged(party). }
    On failure { Assert refuged(party). Assert crewHurt(wapshotts). }
    Result "The doors are bronze and a hand thick, and the bar drops. Four cages. Six people go in. Mr Mudge and Aggie Nunn stay by the fire to keep it, because somebody must, and Mr Mudge says so loudly enough to be heard by the cages.".
    Otherwise "The bar jams on the third door. Somebody's arm is through it when it drops.".
  }
  Action hold_door_billie(actor: group, site: place) "Let Billie hold the door with her shoulder while the rest go in" {
    Speaker billie.
    Requires able(actor) and company(actor) and at(actor, site) and at(billie, site) and billieField(wapshotts) and (at(actor, landing) or at(actor, cage_row)) and huntOn(wapshotts) and not refuged(party).
    Time 0.
    On success { Assert refuged(party). }
    Result "'I've held worse,' says Billie, and does. She talks to the dark through the bars in the voice she uses to the horses, and it goes on until the grey.".
  }
  Action light_fires(actor: group, site: place) "Build the fire up on the quay and feed it oil" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, landing) or at(actor, cage_row)) and huntOn(wapshotts) and holding(actor, lamp_oil) and not firesLit(party).
    Time 0.
    On success { Spend lamp_oil from actor. Assert firesLit(party). }
    Result "The fire goes up in a column. Beyond the ring of it, the eyes step back a pace, and hold there.".
  }
  Action throw_the_meat(actor: group, site: place) "Throw four rations of meat into the dark and sit still" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, landing) or at(actor, cage_row)) and huntOn(wapshotts) and quantity(actor, rations) >= 4 and not huntDiverted(party).
    Time 0.
    On success { Decrease quantity(actor, rations) by 4. Assert huntDiverted(party). }
    Result "You hear it land. You hear something come for it, and stop, and eat. You do not hear it leave.".
  }
  Action drag_colonel_in(actor: group, site: place) "Take the Colonel by the collar and pull him into a cage" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, landing) or at(actor, cage_row)) and huntOn(wapshotts) and not colonelDragged(wapshotts) and not dragTried(wapshotts).
    Time 1.
    Resolve check(actor, brawn, dc_fair).
    On success { Assert colonelDragged(wapshotts). }
    On failure { Assert dragTried(wapshotts). }
    Result "He comes in backwards, still blowing, with his hat over his eyes and the trumpet jammed in a bar. The note goes out into the dark. Nothing answers it.".
    Otherwise "He shakes you off and strides for the quay's end. 'I should like,' he says, 'to see it.'".
  }
  // The outcomes, at the quay. A pack fed or at peace comes to nothing; the cages alone cost the bosun; the fire alone costs blood.
  Rule hunt_clean when huntOn(wapshotts) and watch(clock) >= huntAt(wapshotts) + 36 and (huntDiverted(party) or (hookTolerates(party) and tolerates(tyrant, party))) {
    Retract huntOn(wapshotts). Assert huntDone(wapshotts). Assert huntClean(wapshotts). Assert offstage(night_pack). }
  Rule hunt_caged_and_lit when huntOn(wapshotts) and watch(clock) >= huntAt(wapshotts) + 36 and refuged(party) and firesLit(party) and not huntDiverted(party) and not (hookTolerates(party) and tolerates(tyrant, party)) {
    Retract huntOn(wapshotts). Assert huntDone(wapshotts). Assert huntClean(wapshotts). Assert offstage(night_pack). }
  Rule hunt_caged when huntOn(wapshotts) and watch(clock) >= huntAt(wapshotts) + 36 and refuged(party) and not firesLit(party) and not huntDiverted(party) and not (hookTolerates(party) and tolerates(tyrant, party))
    says "It does not come into the cages. It takes the fire, the tarpaulin and Mr Mudge's arm, in that order, and goes. In the grey he is sitting against a cask, white to the lips, telling the dawn that it was a fine bite." {
    Retract huntOn(wapshotts). Assert huntDone(wapshotts). Assert crewHurt(wapshotts). Assert offstage(night_pack). }
  Rule hunt_lit when huntOn(wapshotts) and watch(clock) >= huntAt(wapshotts) + 36 and firesLit(party) and not refuged(party) and not huntDiverted(party) and not (hookTolerates(party) and tolerates(tyrant, party)) and (at(party, landing) or at(party, cage_row))
    says "It does not come through the fire. It takes what it can reach round the edge of the light: the tarpaulin, a cask, a man's arm." {
    Retract huntOn(wapshotts). Assert huntDone(wapshotts). Assert crewHurt(wapshotts). Assert offstage(night_pack). }
  Rule hunt_bare when huntOn(wapshotts) and not crewLost(wapshotts) and watch(clock) >= huntAt(wapshotts) + 36 and not firesLit(party) and not refuged(party) and not huntDiverted(party) and not (hookTolerates(party) and tolerates(tyrant, party)) and (at(party, landing) or at(party, cage_row))
    says "The fire is out before anyone has seen what put it out. There is a short, wet noise from the tarpaulin where Mr Mudge sleeps. In the morning there are the boots." {
    Retract huntOn(wapshotts). Assert huntDone(wapshotts). Assert crewLost(wapshotts). Slay mudge. Assert strikes(pack_night, party). Assert offstage(night_pack). }
  Rule hunt_bare_later when huntOn(wapshotts) and crewLost(wapshotts) and watch(clock) >= huntAt(wapshotts) + 36 and not firesLit(party) and not refuged(party) and not huntDiverted(party) and not (hookTolerates(party) and tolerates(tyrant, party)) and (at(party, landing) or at(party, cage_row))
    says "The fire is out before anyone has seen what put it out. When the light comes Aggie Nunn is sitting against the cask-stack with the ladle in her fist and her other arm in her apron, swearing in a low level voice, like a woman reading." {
    Retract huntOn(wapshotts). Assert huntDone(wapshotts). Assert crewHurt(wapshotts). Assert strikes(pack_night, party). Assert offstage(night_pack). }
  Rule hunt_away when huntOn(wapshotts) and watch(clock) >= huntAt(wapshotts) + 36 and not (at(party, landing) or at(party, cage_row)) and not huntDiverted(party) and not (hookTolerates(party) and tolerates(tyrant, party)) {
    Retract huntOn(wapshotts). Assert huntDone(wapshotts). Assert huntAbsent(wapshotts). Assert crewHurt(wapshotts). Assert offstage(night_pack). }
  Observe hunt_away_told at landing when crewHurt(wapshotts) and not crewLost(wapshotts) and not refuged(party) and not firesLit(party) and hour(clock) < 12 "Mr Mudge has his arm in a sling of Aggie's apron. 'IT STOOD AT THE FIRE,' he says. 'IT STOOD THERE, AND THE COOK HIT IT WITH THE STEW.' Aggie Nunn is not saying.".
  Rule colonel_hurt when huntDone(wapshotts) and not colonelDragged(wapshotts) and not huntClean(wapshotts) and not crewLost(wapshotts) and not colonelHurt(wapshotts) { Assert colonelHurt(wapshotts). }
  Observe hunt_morning at landing when huntClean(wapshotts) and hour(clock) < 9 "Morning. The quay is untouched. A track a yard wide goes to the water's edge and comes back, and one cask has rolled a hundred feet. Aggie Nunn says nothing, and makes the stew.".
  Observe hunt_loss at landing when crewLost(wapshotts) and hour(clock) < 12 "Mr Mudge's boots stand side by side by the tarpaulin. Nobody touches them. Aggie Nunn has made no stew.".
  Milestone m_night "came through the night on the quay" worth 400 when huntDone(wapshotts) and not huntAbsent(wapshotts).

  // ── The reef: nine days open; a failed run keeps her aground; a month to the next spring tide ────────────────────
  Hazard reef_scrape "The reef" means "Deal (1d8) physical damage to ally unless dexterity save against (14).".
  Action run_reef(actor: group, site: place) "Take the Sundial out through the reef passage" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and voyaged(wapshotts) and berthS(wapshotts) and colonelDecided() and (huntDone(wapshotts) or day(clock) >= landDay(wapshotts) + 3) and not crewePardoned(wapshotts) and not creweBlamed(wapshotts) and day(clock) <= reefDay(wapshotts) and not reefRun(wapshotts).
    Time 0.
    Resolve check(actor, wayfinding, dc_hard).
    On success { Retract berthS(wapshotts). Assert atSea(wapshotts). Retract outward(wapshotts). Assert homeward(wapshotts). Set sailDay(wapshotts) to day(clock). Assert reefRun(wapshotts). Increase quantity(party, rations) by 12. }
    On failure { Assert hullHoled(wapshotts). Assert strikes(reef_scrape, party). Set reefDay(wapshotts) to day(clock) - 1. Decrease waterCasks(wapshotts) by 2 or to nothing. Decrease quantity(party, rations) by 2 or to nothing. }
    Result "The Sundial goes out through a gap forty feet wide with the surf standing up white on either hand. The keel does not touch. You find you have not breathed since the quay.".
    Otherwise "She takes the reef under the forefoot with a noise like a cart on cobbles, and sits there. The ebb goes out from under her. The gate shut behind the keel. Crewe takes off his hat and puts it on again.".
  }
  Action run_reef_with_crewe(actor: group, site: place) "Ask Crewe to take the Sundial out through the reef, and keep your hands off" {
    Speaker crewe.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and voyaged(wapshotts) and berthS(wapshotts) and colonelDecided() and (huntDone(wapshotts) or day(clock) >= landDay(wapshotts) + 3) and crewePardoned(wapshotts) and day(clock) <= reefDay(wapshotts) and not reefRun(wapshotts).
    Time 0.
    Resolve check(actor, wayfinding, dc_fair).
    On success { Retract berthS(wapshotts). Assert atSea(wapshotts). Retract outward(wapshotts). Assert homeward(wapshotts). Set sailDay(wapshotts) to day(clock). Assert reefRun(wapshotts). Increase quantity(party, rations) by 12. }
    On failure { Assert hullHoled(wapshotts). Assert strikes(reef_scrape, party). Set reefDay(wapshotts) to day(clock) - 1. Decrease waterCasks(wapshotts) by 2 or to nothing. Decrease quantity(party, rations) by 2 or to nothing. }
    Result "Crewe takes her out like a man leading a horse through a fire. He talks all the way, to the Captain, who is not there.".
    Otherwise "He misses by a hand's breadth. The reef takes some paint and a good deal of his confidence, and holds her.".
  }
  Action run_reef_unsure(actor: group, site: place) "Take the Sundial out through the reef with Crewe wringing his hat beside you" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and voyaged(wapshotts) and berthS(wapshotts) and colonelDecided() and (huntDone(wapshotts) or day(clock) >= landDay(wapshotts) + 3) and creweBlamed(wapshotts) and day(clock) <= reefDay(wapshotts) and not reefRun(wapshotts).
    Time 0.
    Resolve check(actor, wayfinding, dc_formidable).
    On success { Retract berthS(wapshotts). Assert atSea(wapshotts). Retract outward(wapshotts). Assert homeward(wapshotts). Set sailDay(wapshotts) to day(clock). Assert reefRun(wapshotts). Increase quantity(party, rations) by 12. }
    On failure { Assert hullHoled(wapshotts). Assert strikes(reef_scrape, party). Set reefDay(wapshotts) to day(clock) - 1. Decrease waterCasks(wapshotts) by 2 or to nothing. Decrease quantity(party, rations) by 2 or to nothing. }
    Result "He tells you the marks and then cannot find them. You find them. It is not his fault, and he will say so for the rest of the voyage.".
    Otherwise "Crewe says 'Port', and then 'Starboard', and then nothing. She goes on the reef broadside.".
  }
  Action run_reef_late(actor: group, site: place) "Take the Sundial out through the shut reef on the ebb, and pray" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and voyaged(wapshotts) and berthS(wapshotts) and colonelDecided() and (huntDone(wapshotts) or day(clock) >= landDay(wapshotts) + 3) and day(clock) > reefDay(wapshotts) and day(clock) < reefDay(wapshotts) + 30 and not reefRun(wapshotts).
    Time 0.
    Resolve check(actor, wayfinding, dc_formidable).
    On success { Retract berthS(wapshotts). Assert atSea(wapshotts). Retract outward(wapshotts). Assert homeward(wapshotts). Set sailDay(wapshotts) to day(clock). Assert reefRun(wapshotts). Increase quantity(party, rations) by 6. }
    On failure { Assert hullHoled(wapshotts). Assert strikes(reef_scrape, party). Decrease waterCasks(wapshotts) by 2 or to nothing. }
    Result "The passage is a single green slot in a white wall. She goes through on the top of a wave with a hand's breadth either side. Nobody speaks until the island is a smudge.".
    Otherwise "The wave puts her down on the reef, lifts her off, and puts her down again. Mr Mudge is praying in four languages.".
  }
  Action run_reef_spring(actor: group, site: place) "Take the Sundial out through the reef on the spring tide" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, deck) and voyaged(wapshotts) and berthS(wapshotts) and colonelDecided() and (huntDone(wapshotts) or day(clock) >= landDay(wapshotts) + 3) and day(clock) >= reefDay(wapshotts) + 30 and not reefRun(wapshotts).
    Time 0.
    Resolve check(actor, wayfinding, dc_fair).
    On success { Retract berthS(wapshotts). Assert atSea(wapshotts). Retract outward(wapshotts). Assert homeward(wapshotts). Set sailDay(wapshotts) to day(clock). Assert reefRun(wapshotts). Increase quantity(party, rations) by 2. }
    On failure { Assert hullHoled(wapshotts). Assert strikes(reef_scrape, party). }
    Result "The gate is open again, and everyone in the Sundial is thin, and nobody says a word about the cook.".
    Otherwise "She scrapes, and comes off on the flood.".
  }
  Observe reef_shut at deck when berthS(wapshotts) and tideMarked(wapshotts) and day(clock) > reefDay(wapshotts) and day(clock) < reefDay(wapshotts) + 30 "The reef passage is a wall of surf from end to end. Crewe looks at it, and at the water-casks, and says what a mate says when the next spring tide is a month off: nothing.".
  Milestone m_reef "took the Sundial out through the reef" worth 400 when reefRun(wapshotts).

  // ── The Colonel decides ─────────────────────────────────────────────────────────────────────────────────────────
  Query colonelDecided() means takeLeave(wapshotts) or takeEgg(wapshotts) or takeSpecimens(wapshotts) or colonelStays(wapshotts).
  Query colonelWouldStay() means namedLetGo(wapshotts) and (ruleRead(wapshotts) or colonelGrieved(wapshotts) or colonelStopped(wapshotts)).
  Query colonelProud() means colonelCovered(wapshotts) or not colonelHumbled().
  Query colonelHumbled() means ruleRead(wapshotts) or colonelGrieved(wapshotts) or namedLetGo(wapshotts) or colonelNamedFear(wapshotts) or colonelStopped(wapshotts).
  Action catch_specimens(actor: group, site: place) "Help Sir Gervase net a pair of the small and plentiful" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, forest_edge) or at(actor, delta_edge)) and fenwickWants(wapshotts) and not specimensCaught(wapshotts).
    Time 4 hours.
    Resolve check(actor, woodcraft, dc_fair).
    On success { Assert specimensCaught(wapshotts). }
    Result "Two fern-runners, in a net, outraged. Sir Gervase takes them into his coat like a man given a baby. They look at him with the whole of their faces. He weeps a little.".
    Otherwise "The runners go through the net as through a thought.".
  }
  Topic wap_decides_leave with wapshott "Ask the Colonel what he means to do now" when voyaged(wapshotts) and berthS(wapshotts) and at(party, landing) and (huntDone(wapshotts) or day(clock) >= landDay(wapshotts) + 3) and not colonelDecided() and not colonelWouldStay() and colonelHumbled() and not colonelCovered(wapshotts) once {
    Says "The Colonel turns his hat over, and over. He looks along the quay. 'Nothing,' he says. 'A fern-runner would take the lock off the wagon and give it to a goose.' He puts the hat on. 'Nothing,' he says again, as if trying the weight of it. 'I shall tell Ada it was a large field.'".
    On discuss { Assert takeLeave(wapshotts). }
  }
  Topic wap_decides_egg with wapshott "Ask the Colonel what he means to do now" when voyaged(wapshotts) and berthS(wapshotts) and at(party, landing) and (huntDone(wapshotts) or day(clock) >= landDay(wapshotts) + 3) and not colonelDecided() and not colonelWouldStay() and colonelProud() and holding(actor, dragons_egg) once {
    Says "The Colonel takes the egg out of your hands before you have offered it. 'One,' he says. 'For the oven, with a damp cloth, and Honoria to turn it.' He does not look round.".
    On discuss { Assert takeEgg(wapshotts). }
  }
  Topic wap_decides_specimens with wapshott "Ask the Colonel what he means to do now" when voyaged(wapshotts) and berthS(wapshotts) and at(party, landing) and (huntDone(wapshotts) or day(clock) >= landDay(wapshotts) + 3) and not colonelDecided() and not colonelWouldStay() and colonelProud() and not holding(actor, dragons_egg) and fenwickWants(wapshotts) and specimensCaught(wapshotts) once {
    Says "'The Society's pair,' says the Colonel. 'Sir Gervase has been patient.' He signs the paper on the cask-head in the capitals Sir Gervase asked for.".
    On discuss { Assert takeSpecimens(wapshotts). }
  }
  Topic wap_decides_nothing with wapshott "Ask the Colonel what he means to do now" when voyaged(wapshotts) and berthS(wapshotts) and at(party, landing) and (huntDone(wapshotts) or day(clock) >= landDay(wapshotts) + 3) and not colonelDecided() and not colonelWouldStay() and colonelProud() and not holding(actor, dragons_egg) and not (fenwickWants(wapshotts) and specimensCaught(wapshotts)) once {
    Says "'What is there?' says the Colonel. 'Mud. Mud and a great deal of nothing a man could carry.' He looks at the jungle, which says nothing back. 'Home,' he says, and means it, and does not like it.".
    On discuss { Assert takeLeave(wapshotts). }
  }
  Topic wap_stay_yes with wapshott "Ask the Colonel what he means to do now" when voyaged(wapshotts) and berthS(wapshotts) and at(party, landing) and (huntDone(wapshotts) or day(clock) >= landDay(wapshotts) + 3) and not colonelDecided() and colonelWouldStay() once {
    Says "'Home,' says the Colonel, 'is a field in Ashby Lowe with a bill on the gate.' He turns his hat over twice. 'I put it to myself that a man might stay a season. To keep the doors.' 'I have named one thing in my life,' he says, 'and let it go. I find I should like to see what comes of it.' He gives you the trumpet. 'Tell Ada I have gone to look at the lake.'".
    On discuss { Assert colonelStays(wapshotts). Retract following(wapshott, party). Assert at(wapshott, landing). }
  }
  Rule billie_resigns when billieAboard(wapshotts) and not billieResigned(wapshotts) and (takeEgg(wapshotts) or takeSpecimens(wapshotts) or colonelStays(wapshotts)) { Assert billieResigned(wapshotts). }
  Rule billie_pleased when billieAboard(wapshotts) and takeLeave(wapshotts) and not billieGlad(wapshotts) { Assert billieGlad(wapshotts). Increase regard(billie) by 2. }
  Observe billie_leave_note near billie when takeLeave(wapshotts) and berthS(wapshotts) and billieAboard(wapshotts) "Billie, ten yards off, has stopped coiling the rope.".
  Observe billie_egg_note near billie when takeEgg(wapshotts) and berthS(wapshotts) and billieAboard(wapshotts) "Billie says 'Aye,' to nobody, and goes on coiling the rope as if it were a neck.".
  Observe billie_specimen_note near billie when takeSpecimens(wapshotts) and berthS(wapshotts) and billieAboard(wapshotts) "Billie watches the pen. When the Colonel has signed she goes up the Sundial's gangway without being told, and down into the hold, and shuts the hatch.".
  Observe billie_stay_note near billie when colonelStays(wapshotts) and berthS(wapshotts) and billieAboard(wapshotts) "Billie looks at the Colonel for a long time, and says nothing, and begins to unpack the crates she had packed.".
  Rule colonel_remains when colonelStays(wapshotts) and backFromSarn(wapshotts) and at(wapshott, landing) { Retract at(wapshott, landing). Assert offstage(wapshott). }
  Rule billie_leaves when billieResigned(wapshotts) and backFromSarn(wapshotts) and not billieField(wapshotts) and travels(billie) { Retract travels(billie). Retract post(billie, rk_beasts). Assert offstage(billie). }

  // ── Endings, one at a time ──────────────────────────────────────────────────────────────────────────────────────
  Query endedLost() means crewLost(wapshotts).
  Query endedHurt() means colonelHurt(wapshotts) and not crewLost(wapshotts) and not colonelStays(wapshotts).
  Query endedFiasco() means colonelNamed(wapshotts) and not namedLetGo(wapshotts) and hatchlingsPenned(wapshotts) and not hatchlingsHome(party) and not colonelStays(wapshotts) and not crewLost(wapshotts) and not colonelHurt(wapshotts).
  Observe colonel_stays_note near ada when colonelStays(wapshotts) and backFromSarn(wapshotts) and not endedLost() "Ada Thripp reads the Colonel's note again. GONE TO LOOK AT THE LAKE. DO NOT LET HONORIA SELL THE BAND. She has put it in the strongbox, and has not, in all the days since, called a stand off.".
  Observe end_loss near ada when backFromSarn(wapshotts) and endedLost() and not colonelStays(wapshotts) "Mr Mudge's boots have come home in the Sundial's locker. Crewe stands them at the foot of the king-pole. The wagons are quiet. Honoria makes the tea, and nobody drinks it until she says.".
  Observe end_loss_stay near ada when backFromSarn(wapshotts) and endedLost() and colonelStays(wapshotts) "Mr Mudge's boots stand at the foot of the king-pole and the Colonel's chair in the ticket wagon is empty. Crewe has put his hat on the chair, and then taken it off again. Nobody has sat down.".
  Observe end_crew_hurt near mudge when backFromSarn(wapshotts) and crewHurt(wapshotts) and not crewLost(wapshotts) "Mr Mudge's arm is in a sling, and he is telling the dock about it.".
  Observe end_hurt near wapshott when backFromSarn(wapshotts) and endedHurt() "The Colonel comes home with his arm in a sling made of Sir Gervase's best handkerchief. He says it was a capital night. Honoria hands him tea in the wrong cup, and he drinks it.".
  Observe end_fiasco near wapshott when backFromSarn(wapshotts) and endedFiasco() "A small barred head comes out of the Colonel's coat at the gate, looks at Ada's ticket book, and eats it. 'The Duchess,' says the Colonel, 'has come home.'".
  Observe sarn_home_leave near wapshott when backFromSarn(wapshotts) and takeLeave(wapshotts) and not endedLost() and not endedHurt() and not endedFiasco() and not colonelStays(wapshotts) "The Colonel has had a board painted and nailed over the beast-tent flap, in his largest hand: NOTHING IS TO BE TAKEN THAT CANNOT BE FED. Underneath, in Ada's: Mr Wapshott's own, and he means it.".
  Observe sarn_home_egg near wapshott when backFromSarn(wapshotts) and takeEgg(wapshotts) and not endedLost() and not endedFiasco() "A grey egg lies in a basket by Honoria's oven under a damp cloth, and she turns it with a wooden spoon every hour.".
  Observe home_billie_gone near wapshott when backFromSarn(wapshotts) and billieResigned(wapshotts) "Billie's coat is gone from its peg in the beast tent.".
  Observe sarn_home_specimens near wapshott when backFromSarn(wapshotts) and takeSpecimens(wapshotts) and not endedLost() and not endedFiasco() "Sir Gervase has a pair of fern-runners in a cage in the yard and a clerk from the Society with a ledger. The beast tent is quiet.".
  Observe home_dab near wapshott when backFromSarn(wapshotts) and dabColonel(wapshotts) "Master Dab, Assistant Zoologist, is polishing a cage with his sleeve and a face of enormous importance.".
  Observe home_dab_told near crewe when backFromSarn(wapshotts) and dabTold(wapshotts) "Dab is at the galley door of the Sundial at the fair town's quay, carrying a bucket. Crewe is pretending not to see the bucket.".
  Observe home_fenwick near fenwick when backFromSarn(wapshotts) and fenwickYielded(wapshotts) "Sir Gervase has pinned his drawings of the lake to the cookhouse wagon. He has drawn his own hand in the margin again.".
  Chapter ch_reef "The Reef" when berthS(wapshotts) and tideMarked(wapshotts) and day(clock) >= reefDay(wapshotts) - 2 "Three days to the gate. The casks are low.".

  Observe harrow_camp_beaten at harrow_camp when harrowBeaten(party) "The camp is half struck. A net-man is explaining to the dog how he came to be here.".
  Observe harrow_camp_friend at harrow_camp when harrowFriend(party) and not harrowBeaten(party) "Harrow has set a camp-stool for you by the fire, with the grave air of a man who has not been robbed.".
  Observe mum_read_seen near mumchance when mumRead(party) and atSea(wapshotts) "Mumchance nods to you across the deck. It is a very small nod.".
  Observe billie_read_seen near billie when billieRead(party) and berthS(wapshotts) "Billie has her hands in her coat. She counts nothing today.".
  Observe wapshott_keen near wapshott when wapshottKeen(wapshotts) and not colonelHumbled() and berthS(wapshotts) "The Colonel has named four things on the quay since breakfast, and one of them is the jetty.".
  Observe awed_colonel near wapshott when colonelAwed(wapshotts) and berthS(wapshotts) and not colonelMoved(wapshotts) "The Colonel has still not said a word about the jungle. He has put his best coat on for it.".
  Observe herd_blessed_seen at plain_mid when herdBlessed(party) and not dead(three_horns) "The three-horns' cow lifts her head as you pass and goes on tearing at the ferns. A black-skinned calf with pitch on its flank trots by her knee.".
  Observe fenwick_wept_seen near fenwick when fenwickWept(party) and berthS(wapshotts) "Sir Gervase has put his net away. He is reading the lake again, upside down.".
  Observe scope_all_sulk near fenwick when scopeAll(wapshotts) and takeLeave(wapshotts) and backFromSarn(wapshotts) "Sir Gervase has not spoken to the Colonel since the quay. He has drawn him, very small, at the bottom of a page of lizards.".
  Observe crew_left_home near honoria when crewLeft(wapshotts) and backFromSarn(wapshotts) "Four net-men are drying their oilskins on the cookhouse wagon. Their old master has sent them a keg and no letter.".
}

data/goings-on/circus/isle_life.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── Who lives on Sarn, and how they behave ─────────────────────────────────────────────────────────────────────
  Relation eggTaken(group). Relation eggReturned(group). Relation herdSeen(group). Relation herdBlessed(group).
  Relation tarFreed(group). Relation hookTolerates(group). Relation harrowFriend(group). Relation harrowBeaten(group).
  Relation hatchlingsHome(group). Relation nightPackCame(group). Relation specimenTaken(group). Relation journalRead(group).

  Person fern_runners "the fern-runners" at forest_edge {
    Role "a company of cat-sized feathered runners". Species fern_runner. Numbers 6. Peaceable.
  }
  Person stilt_runners "the stilt-runners" at plain_south {
    Role "grey-feathered runners as tall as a man, feeding in the ferns". Species stilt_runner. Numbers 5. Peaceable.
  }
  Person hook_claws "the hook-claws" at hook_den {
    Role "a pack of five, barred green and rust". Species hook_claw. Level 3. Numbers 5. Temperament territorial.
    Warns "The click stops. All round the hollow, in the ferns, there are heads: long, barred, bright-eyed, turned. They do not hurry. One, nearer than the others, lifts a single hooked foot clear of the ground and lowers it.".
    Comes "The nearest hook-claw goes down on its hocks and comes, and the ferns close behind it with five others in them.".
    Lair hook_den. Refuge kingsfoil_hollow.
  }
  Person three_horns "the three-horns" at plain_mid {
    Role "a herd of four, grazing, with a calf in the middle of them". Species three_horn. Level 4. Numbers 4. Temperament territorial.
    Warns "The nearest of the beasts lifts a head barrel-headed, with three horns on it, and turns. The calf goes under the biggest cow's belly. The cow lowers her frill and paws the clay once, and the herd closes.".
    Comes "The cow comes across the clay like a wagon off a hill.".
    Lair plain_mid.
    State grazing blocking "The three-horns graze across the herd-trail to the lake, the calf in the middle of them, and any road through them is theirs.".
    Guards plain_lake.
  }
  Person lantern_necks "the lantern-necks" at lake_shore {
    Role "ten of the island's greatest animals, wading, with their calves between them". Species lantern_neck. Level 8. Numbers 3. Peaceable.
  }
  Person tyrant "the tyrant" at tyrant_hollow {
    Role "the island's hunter, asleep or not". Species tyrant. Level 6. Numbers 1. Temperament territorial.
    Warns "The ground ahead rises. A head the length of a man comes up out of the ferns with its mouth a little open, unhurried, and the teeth in it are the length of your hand.".
    Comes "It comes across the ground in three strides and the ground shakes at every one.".
    Lair tyrant_hollow.
  }
  Person delta_croc "the delta-lurker" at channels {
    Role "an old crocodile, long as a boat, with a notched back". Species crocodile. Variant great. Variant elder. Level 3. Numbers 1. Temperament ambush.
    Warns "A log in the black water turns, and has an eye in it.".
    Comes "The water explodes at the bank.".
    Lair channels.
  }
  Person sail_wings "the sail-wings" at ledges {
    Role "a colony of great-winged lizards, six hundred strong". Species sail_wing. Level 2. Numbers 6. Temperament territorial.
    Warns "The colony rises half off the ledge in one movement, bills open, crests up, a roar of wings. Not a single bird has left its nest.".
    Comes "The wings come down over you in a tearing white storm.".
    Lair ledges.
    State nesting blocking "The colony sits across the ledge path to the top, bills open, and does not give way.".
    Guards ledges_top.
  }

  // ── Captain Harrow and the Hippodrome's nets ─────────────────────────────────────────────────────────────────
  Person harrow "Captain Dace Harrow" at harrow_camp {
    Role "an animal-dealer, lately of the Imperial Hippodrome". Ancestry human. Calling thief. Level 4. Peaceable. Pronouns he. Manner jovial.
    Greets "A lean, brown man in a good oilskin gets up from a camp-stool, bows, and does not take his hands out of his sleeves. 'Harrow,' he says. 'Dace Harrow. You'll be Wapshott's. I knew you were coming; you can smell a circus half a league off a beach. Welcome to Sarn. Do not touch the nets.'".
  }
  Person harrow_men "Captain Harrow's men" at harrow_camp {
    Role "four net-men in oilskins, off the Hippodrome". Ancestry human. Calling warrior. Level 2. Numbers 4. Peaceable.
  }
  Topic harrow_why with harrow "Ask Captain Harrow what he is doing on Sarn" when true {
    Says "'Collecting,' says Harrow. 'For a lady with an old lion who has told me she wants something young.' He gestures at the crates. 'Two stilt-runner chicks, a hook-claw calf, and a nest of those little feathered things that open latches. I take what the island can spare. It can spare a great deal. It has seven hundred stilt-runners and I mean to leave it six hundred and ninety-eight.' He smiles. 'I have never lost an animal in transit, Wapshott. Ask the Hippodrome.'".
    On discuss { Assert knows(actor, harrow_known). }
  }
  Entity harrow_known: fact "Captain Dace Harrow has a camp in the delta, taking young stilt-runners and a hook-claw calf for the Hippodrome.".
  Topic harrow_young with harrow "Ask Captain Harrow about the hook-claw calf" when knows(actor, harrow_known) {
    Says "'Took it from a den in the forest,' says Harrow. 'The mother was out. I am told she has been looking for it since. I would not go into the forest, if I were you.' He is not joking. 'Forty coin, if you want it, and the cage.'".
  }
  Action buy_calf(actor: group, site: place) "Buy the hook-claw calf from Captain Harrow, forty coin" {
    Speaker harrow.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, harrow_camp) and at(harrow, harrow_camp) and quantity(actor, gold) >= 40 and not calfBought(party) and not calfFreed(party).
    Time 0.
    On success { Decrease quantity(actor, gold) by 40. Assert calfBought(party). Assert harrowFriend(party). }
    Result "Harrow counts the coin twice, and nods at the least of the crates. 'You'll want the cage back,' he says. 'You will not get it.' Inside it a young hook-claw the size of a cat looks at you sidelong, with the whole of its face, and clicks once.".
  }
  Relation calfBought(group). Relation calfFreed(group).
  Thing calf_cage "the hook-claw's cage" at harrow_camp {
    State locked closed "In the least of the crates a young hook-claw sits upright with its tail wrapped round its feet, looking out between the slats.".
    State sprung "The crate stands open, empty.".
    Change spring_cage "Spring the calf's crate" from locked to sprung needing crowbar or lockwork.
    Holds.
  }
  Rule calf_freed_rule at harrow_camp when at(party, harrow_camp) and state(calf_cage, sprung) and not calfFreed(party)
    says "Harrow's men look up from their mugs at the sound, and do not move. The calf comes out of the crate in a single sideways flow, and is gone into the mangroves with its tail out straight." {
    Assert calfFreed(party). Assert tolerates(hook_claws, party). Assert hookTolerates(party). Assert harrowBeaten(party). Retract tolerates(harrow_men, party).
  }
  Action parley_harrow(actor: group, site: place) "Argue with Captain Harrow that the island is not his to thin" {
    Speaker harrow.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, harrow_camp) and at(harrow, harrow_camp) and not harrowFriend(party) and not harrowBeaten(party).
    Time 0.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert harrowFriend(party). }
    Result "Harrow listens with his head on one side. 'You are a showman,' he says. 'Everything on this island is a house. You and I want the same thing and have quarrelled about the price.' He lets the nets fall. 'Take the stilt-runners. I will take my chances with the hook-claw.'".
    Otherwise "Harrow listens, smiling, and when you have finished he says, kindly, 'No.'".
  }

  // ── The egg-beds: what to take, and what taking costs ────────────────────────────────────────────────────────
  Item egg_a "a grey loaf-big egg, warm as bread" is dragons_egg at egg_beds.
  Item egg_b "a second egg, a little darker" is dragons_egg at egg_beds.
  Item egg_c "a third, cracked and cold" is dragons_egg at egg_beds.
  Rule egg_taken_rule at egg_beds when at(party, egg_beds) and holding(party, dragons_egg) and not eggTaken(party) and not eggReturned(party)
    says "The beds are warm under your hand, and the egg is warm in it. Out in the mangroves, a long way off, there is a single hard click." {
    Assert eggTaken(party).
  }
  Hazard pack_night "The pack at the camp" means "Deal (3d6) physical damage to ally unless dexterity save against (14).".
  Rule pack_comes when eggTaken(party) and not eggReturned(party) and not hookTolerates(party) and dark() and not nightPackCame(party) and (at(party, landing) or at(party, delta_edge) or at(party, cage_row) or at(party, forest_edge) or at(party, cycad_aisle)) {
    Assert nightPackCame(party). Assert strikes(pack_night, party).
  }
  Observe pack_night_told at landing when nightPackCame(party) "Something went through the camp in the night, in a silence of clicking, and took what it was looking for out of the dark, and left a long red line down someone's arm.".
  Action return_egg(actor: group, site: place) "Set the egg back in the warm sand where it was found" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, egg_beds) and holding(actor, dragons_egg) and eggTaken(party) and not eggReturned(party).
    Time 0.
    On success { Spend dragons_egg from actor. Assert eggReturned(party). Retract eggTaken(party). }
    Result "You put it back in its ring, point down, in the warm. It is a small thing to have done. The mangrove, which has been holding its breath since you took it, lets it out.".
  }

  // ── The hook-claws and the hatchlings ────────────────────────────────────────────────────────────────────────
  Action return_hatchlings(actor: group, site: place) "Set the young hook-claws down at the edge of the hollow and step back" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hook_den) and at(hook_claws, hook_den) and able(hook_claws)
      and youngAshore(party) and (not colonelNamed(wapshotts) or namedLetGo(wapshotts)) and not hookTolerates(party).
    Time 0.
    On success { Assert hookTolerates(party). Assert tolerates(hook_claws, party). Assert hatchlingsHome(party). Assert at(hatchlings, hook_den). Retract youngAshore(party). }
    Result "You open the sack and set them down in the bare earth, and step back, and nobody moves. One of the young goes forward in short, stopped runs, and the biggest of the pack lowers her head to it, and makes a sound you could not have told from a purr. The pack closes round them. When it opens, you are no longer in it, and no one has looked at you since.".
  }
  Observe hook_pack_soft at hook_den when hookTolerates(party) "The pack lies in the sun in its hollow with the young in the middle, and takes no notice of you at all.".
  Action throw_meat(actor: group, site: place) "Throw the pack a ration of meat and back off" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hook_den) and at(hook_claws, hook_den) and quantity(actor, rations) >= 2 and not tolerates(hook_claws, actor).
    Time 0.
    On success { Decrease quantity(actor, rations) by 2. Assert tolerates(hook_claws, actor). }
    Result "The meat lands among them and the pack falls on it in the old silence. You are not forgiven. You are, for as long as it takes to eat, a thing that is not worth the trouble.".
  }

  // ── The herd at dawn: the sight to be had for not doing anything ────────────────────────────────────────────
  Observe dawn_herd at lake_shore when hour(clock) >= 5 and hour(clock) < 8 and not dead(lantern_necks) "The mist on the lake begins to move. Out of it, one at a time, necks first, come the lantern-necks: grey, vast, wading, with their small heads high among the cycad crowns. The calves come between their legs. They do not look at you. A foot comes down in the mud beside you the size of a wagon-wheel, and the whole shore tilts.".
  Rule herd_wakes at lake_shore when at(party, lake_shore) and hour(clock) >= 5 and hour(clock) < 8 and not herdSeen(party)
    says "You stand at the lake's edge at dawn and the lantern-necks come down out of the mist to drink, ten of them, and the calves between them, and they take no notice of you whatever. It is the largest thing you have ever seen alive, and it is not interested in you." {
    Assert herdSeen(party).
  }
  Entity herd_known: fact "At dawn the lantern-necks come down out of the crater mist to wade and drink in the lake, with their calves between them, and are interested in nothing.".
  Rule herd_stride_rule at lake_shore when at(party, lake_shore) and hour(clock) >= 6 and hour(clock) < 7 and herdSeen(party) and dice(clock) <= 2 and not tyrantFled(party) and not knows(party, piper_known)
    says "A wagon-wheel of a foot comes down in the shallows, too near." {
    Assert strikes(herd_stride, party).
  }
  Relation tyrantFled(group).
  Observe dawn_ridge at plain_ridge when hour(clock) >= 5 and hour(clock) < 8 "Far below, on the grey edge of the lake, the herd has come down out of the mist: ten great backs wading, and nothing else moving anywhere on the plain." teaches herd_known.
  Rule ridge_sees at plain_ridge when at(party, plain_ridge) and hour(clock) >= 5 and hour(clock) < 8 and not herdSeen(party) says "From the ridge, at a safe distance, the lantern-necks come down to drink. You have the whole of it at once, as a picture, and nobody trampled." {
    Assert herdSeen(party).
  }

  // ── The tyrant's hunting, and the herd's shadow ──────────────────────────────────────────────────────────────
  Action stand_in_herd(actor: group, site: place) "Stand in the lee of the sleeping three-horns until the hunting is over" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, plain_mid) and tolerates(three_horns, actor) and hour(clock) >= 15.
    Time 0.
    On success { Assert tolerates(tyrant, actor). Assert tyrantFled(party). }
    Result "The cows have drawn into a ring with the calf in the middle and you in with the calf, and not one of them objects. Something large goes past the ring in the dusk without turning its head, and the herd does not move a muscle. Afterwards the biggest cow looks at you, just once, like a landlady.".
  }

  // ── The tar-pit: something dying that could be saved, or not ─────────────────────────────────────────────────
  Person tar_calf "the sunk three-horn" at tar_pits {
    Role "a young three-horn sunk to the shoulders in pitch". Species three_horn. Variant young. Numbers 1. Peaceable.
  }
  Action free_tar_calf(actor: group, site: place) "Rope the three-horn and haul it out of the pitch" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, tar_pits) and holding(actor, rope) and not tarFreed(party).
    Time 6.
    Resolve check(actor, brawn, dc_hard).
    On success { Assert tarFreed(party). Assert tolerates(three_horns, actor). Assert herdBlessed(party). Retract at(tar_calf, tar_pits). }
    On failure { Assert strikes(bog_pitch, party). }
    Result "It takes all of you, and a rope round its horns, and an hour. At the end of it, a great black-skinned calf comes out of the pitch with a sound like a boot out of a bog, and lies quite still on the sulphur crust, and then lurches to its feet and goes off over the ridge calling for something that answers.".
    Otherwise "The rope slips. The pitch takes your boots to the ankle, and the animal looks at you with one dark and patient eye.".
  }
  Action end_tar_calf(actor: group, site: place) "Put the sunk animal out of its misery" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, tar_pits) and not tarFreed(party) and not tarEnded(party).
    Time 1.
    On success { Assert tarEnded(party). Retract at(tar_calf, tar_pits). }
    Result "It takes only a moment, and you are not proud of it, and it was the kind thing.".
  }
  Relation tarEnded(group).
  Observe tar_gas at tar_pits as feature when true "The flat stinks of struck matches. The crust gives a little, and gives again.".
  Rule gas_hurts at tar_pits when at(party, tar_pits) and dice(clock) <= 12 and not gassed(party)
    says "The wind drops, and the smell of bad eggs closes round your head like a hand." { Assert strikes(sulphur_gas, party). Assert gassed(party). }
  Relation gassed(group).
  Rule gas_clears when gassed(party) and not at(party, tar_pits) { Retract gassed(party). }
  Rule hot_crust at bone_beds when at(party, bone_beds) and dice(clock) <= 6 and not crusted(party) and not knows(party, crust_safe)
    says "The crust under your boot gives, and the heat under it comes through the leather." { Assert strikes(hot_ground, party). Assert crusted(party). }
  Relation crusted(group).
  Rule crust_clears when crusted(party) and not at(party, bone_beds) { Retract crusted(party). }

  // ── The journal and the cages ─────────────────────────────────────────────────────────────────────────────────
  Kind warden_journal "Warden Orme's journal" is document teaching journal_read described "A leather-bound book swollen with damp, in a fair copperplate hand: the day-book of the last Warden of the Southern Preserve, Osric Orme, who kept it for thirty-one years and left it on the table in the hall.".
  Discovery journal_read "Warden Orme's journal: the Progress founded the Preserve four hundred years ago and went round its last time three hundred years since to keep beasts of the southern sea; the Great Beast sent north in the last Progress, to the King as a gift, was a lantern-neck, a calf of three summers, and went with a hook-claw cub from the forest to keep him company; the ship's master was told to feed him cabbages; the Preserve was left to itself when the Progress was disbanded; and the last entry is a note to whoever came after: PUT NOTHING IN A CAGE THAT CAN BE LET OUT OF ONE.".
  Item journal_item "Warden Orme's journal" is warden_journal at preserve_hall.
  Kind keepers_map "the Warden's map of the island" is document teaching map_read described "A map on tanned hide in the Warden's hand, with the island's six countries named and the beasts in each drawn in the margins, and a warning, in red, at the plain's north-west corner: THE TYRANT HUNTS AT EVENING.".
  Discovery map_read "The Warden's map names the island's six countries and the beasts in each, and warns of the tyrant at evening.".
  Item map_item "the Warden's map of the island" is keepers_map at preserve_hall.
  Observe rule_board at preserve_hall when true "Painted over the hearth: THE RULE OF THE PRESERVE. I. NOTHING IS TO BE KILLED FOR SPORT. II. NOTHING IS TO BE TAKEN THAT CANNOT BE FED. III. THE KEEPER IS ANSWERABLE TO THE BEAST.".

  // ── What grows, and what lies about ───────────────────────────────────────────────────────────────────────────
  Thing shore_dulse "the dulse" at landing is scenery { State growing "Dulse grows on the rocks beneath the quay, red and leathery.". }
  Initially Assert grows(shore_dulse).
  Discovery shore_dulse_hid "The dulse on the quay rocks is gathered, not found.".
  Item shore_dulse_1 "a handful of dulse" is dulse_gathered in shore_dulse hidden until shore_dulse_hid.
  Initially Assert crop(shore_dulse_1, shore_dulse).
  Thing delta_bamboo "the bamboo" at delta_edge is scenery { State growing "Bamboo stands in the mud in a jointed green thicket, twenty feet tall.". }
  Initially Assert grows(delta_bamboo).
  Discovery delta_bamboo_hid "The bamboo is gathered, not found.".
  Item delta_bamboo_1 "a length of bamboo" is bamboo_gathered in delta_bamboo hidden until delta_bamboo_hid.
  Initially Assert crop(delta_bamboo_1, delta_bamboo).
  Thing edge_cinnamon "the cinnamon" at forest_edge is scenery { State growing "A small tree with aromatic bark grows in a clearing by the first cycads. Its bark has been stripped in places by something with a small beak.". }
  Initially Assert grows(edge_cinnamon).
  Discovery edge_cinnamon_hid "The cinnamon tree is gathered, not found.".
  Item edge_cinnamon_1 "a curl of cinnamon bark" is cinnamon_gathered in edge_cinnamon hidden until edge_cinnamon_hid.
  Initially Assert crop(edge_cinnamon_1, edge_cinnamon).
  Thing aisle_dragonwort "the dragonwort" at cycad_aisle is scenery { State growing "Dragonwort grows along the edge of the trampled aisle, red-flowered, in the light the great animals let in.". }
  Initially Assert grows(aisle_dragonwort).
  Discovery aisle_dragonwort_hid "The dragonwort along the aisle is gathered, not found.".
  Item aisle_dragonwort_1 "a spray of dragonwort" is dragonwort_gathered in aisle_dragonwort hidden until aisle_dragonwort_hid.
  Initially Assert crop(aisle_dragonwort_1, aisle_dragonwort).
  Thing hollow_kingsfoil "the kingsfoil" at kingsfoil_hollow is scenery { State growing "Kingsfoil grows in a bank by the spring, low and three-leaved, the sharp scent of it carrying across the hollow. Nothing has trodden on it.". }
  Initially Assert grows(hollow_kingsfoil).
  Discovery hollow_kingsfoil_hid "The kingsfoil in the hollow is gathered, not found.".
  Item hollow_kingsfoil_1 "a sprig of kingsfoil" is kingsfoil in hollow_kingsfoil hidden until hollow_kingsfoil_hid.
  Initially Assert crop(hollow_kingsfoil_1, hollow_kingsfoil).
  Item hollow_kingsfoil_2 "a second sprig of kingsfoil" is kingsfoil in hollow_kingsfoil hidden until hollow_kingsfoil_hid.
  Initially Assert crop(hollow_kingsfoil_2, hollow_kingsfoil).
  Item hollow_kingsfoil_3 "a third sprig of kingsfoil" is kingsfoil in hollow_kingsfoil hidden until hollow_kingsfoil_hid.
  Initially Assert crop(hollow_kingsfoil_3, hollow_kingsfoil).
  Thing plain_stagger "the staggerweed" at plain_south is scenery { State growing "Staggerweed grows low in the ferns at the forest's edge, small and inconspicuous. The stilt-runners walk round it.". }
  Initially Assert grows(plain_stagger).
  Discovery plain_stagger_hid "The staggerweed on the plain is gathered, not found.".
  Item plain_stagger_1 "a handful of staggerweed" is staggerweed_gathered in plain_stagger hidden until plain_stagger_hid.
  Initially Assert crop(plain_stagger_1, plain_stagger).

  Kind sarn_pitch "a lump of island pitch" is treasure worth 6 weighing 2 described "A lump of black pitch cut from the tar-pits, still faintly warm, smelling of struck matches and the sea. It burns well, and an apothecary in a port will pay for it.".
  Item pitch_a "a lump of island pitch" is sarn_pitch at tar_pits.
  Item pitch_b "a second lump of island pitch" is sarn_pitch at tar_pits.
  Item tooth_a "a shed tooth the length of a hand" is dragons_tooth at bone_beds.
  Item tooth_b "a second shed tooth, chipped" is dragons_tooth at bone_beds.
  Item tooth_c "a large tooth, black at the root" is dragons_tooth at tyrant_hollow.
  Item shell_a "an unusual seashell, the size of a fist" is unusual_seashell at landing.
  Item star_a "a fallen star, pitted and black, cold" is fallen_star at tar_pits.
  Item channel_oil "a drowned net-man's oil-flask, stopped and full, caught in the roots" is lamp_oil at channels.
  Item bracelet_a "a bronze bracelet on a warden's wrist-bone" is bronze_bracelet at bone_beds.
}

data/goings-on/circus/isle_wild.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── Act IV.iv: the island's hours, its smaller people, and many ways ──────────────────────────────────────────────
  // The island keeps a day. The dawn-pipers sing the herd down; the lantern-necks wade, graze the plain, and sleep in
  // a ring at dusk; the tyrant walks the plain's edge at evening; the sail-wings launch at first light. A company that
  // comes back finds it at another hour. Six of its kinds are the island's small people, and each is a telegraph.
  Relation piperHeard(group). Relation fenwickWept(group). Relation writShown(group).
  Relation netsRotted(group). Relation tyrantBaited(group). Relation colonyLaunched(group).

  Entity piper_known: fact "The dawn-pipers sing an hour before the lantern-necks come down to the lake; the flock's crests are tuned to it.".
  Entity hollow_way_known: fact "At dusk the glide-lizards cross the cycad forest by the one game-trail that goes round the hook-claws' hollow, to the sheltered hollow where nothing else goes.".
  Entity crust_safe: fact "The bone-scuttlers cross the steam basin's crust by one line, and the crust bears the line.".
  Entity channels_warn: fact "When the mud-skimmers come out of the delta's water and stand in rows on the bank, something large is in the channels.".
  Entity colony_known: fact "The sail-wings launch off the ledges together at first light, and leave the ledges empty for an hour.".

  Person dawn_pipers "the dawn-pipers" at plain_south {
    Role "forty small crested runners in blue-grey down, standing in a flock". Species dawn_piper. Numbers 6. Peaceable.
  }
  Person plate_backs "the plate-backs" at plain_south {
    Role "four plate-backs, grazing the plain's margin with their young between them". Species plate_back. Level 3. Numbers 3. Peaceable.
  }
  Person mud_skimmers "the mud-skimmers" at delta_edge {
    Role "dozens of flat-headed shell-diggers on the mud-banks". Species mud_skimmer. Numbers 8. Peaceable.
  }
  Person glide_lizards "the glide-lizards" at cycad_aisle {
    Role "orange-and-green gliders, hanging head-down in the cycad crowns". Species glide_lizard. Numbers 6. Peaceable.
  }
  Person bone_scuttlers "the bone-scuttlers" at bone_beds {
    Role "files of black-and-yellow carrion-eaters on the crust". Species bone_scuttler. Numbers 8. Peaceable.
  }
  Person shore_brooder "the shore-brooder" at cliff_foot {
    Role "a great bald-necked brooder on a nest of tide-wrack". Species shore_brooder. Level 4. Numbers 1. Temperament defensive.
    Warns "The mound of wrack on the strand rises. Under a ruff of black plumes a bald red neck comes up, and a beak like a pair of shears opens, and the whole nest hisses. It does not get up. It does not need to.".
    Comes "The brooder comes off the nest in a rush, wings half out, beak open.".
    Lair cliff_foot.
    State brooding blocking "The brooder sits on the strand under the cliff, across the way to the ledges, and will not give way to anything on two legs.".
    Guards landing_cliffs.
  }

  // What each of them tells you, without anyone fighting anyone.
  Observe pipers_song at plain_south as sound when hour(clock) >= 4 and hour(clock) < 5 "In the grey, on the plain, forty small throats begin: not a song, a single breathed chord on forty hollow crests, rising and falling. Every other animal on the plain stops. It is, you realise slowly, a clock, and it says the herd is an hour from the lake." teaches piper_known.
  Observe glide_dusk at cycad_aisle when hour(clock) >= 17 and hour(clock) < 20 "At dusk the glide-lizards drop from the crowns in ones and twos, spread their ribs, and go across the forest in long flat curves, all in one direction, to a notch in the trees on the north-east. They have done it every evening for longer than there have been roads." teaches hollow_way_known.
  Observe scuttler_line at bone_beds when true "The files of bone-scuttlers cross the yellow crust in one line, over and over, and never put a foot a hand's breadth to either side. The crust to either side of the line is the colour of a sore." teaches crust_safe.
  Observe skimmers_flee at delta_edge when not dead(delta_croc) and hour(clock) >= 12 "The mud-skimmers are all out of the water, in rows along the bank, heads up and perfectly still. Not one is in the channels. The black water beyond them is smooth." teaches channels_warn.
  Observe skimmers_mounds at egg_beds when true "Mounds of dug shell mark the safe sand between the nests: the skimmers have worked it for years, and the nests lie only where they have not.".
  Observe piper_morning near dawn_pipers when hour(clock) >= 5 and hour(clock) < 8 "The pipers have drawn into a tight blue-grey knot with their crests all turned the same way, to the lake.".
  Observe brooder_sign at landing as sign when true "A line of enormous three-toed prints goes along the strand toward the cliffs and ends in a circle of trodden wrack the size of a threshing-floor.".

  // The sail-wings launch at first light and leave the ledges for an hour.
  Rule colony_launch when hour(clock) >= 5 and hour(clock) < 8 and not offstage(sail_wings) { Assert offstage(sail_wings). }
  Rule colony_return when (hour(clock) >= 8 or hour(clock) < 5) and offstage(sail_wings) { Retract offstage(sail_wings). Assert at(sail_wings, ledges). }
  Observe colony_gone at ledges when offstage(sail_wings) "The ledge is empty. The whole colony is up over the sea, a high wheeling cloud with the sun on its wings, and the nests are left in the open like a street of cradles." teaches colony_known.
  Observe colony_up at cliff_top when hour(clock) >= 5 and hour(clock) < 8 "The colony drops off the edge below in one long unrolling, and the headland shakes with it. From the top you can see the whole island, laid out like a map, and the Isle's one road, the herd-trail, going away to the lake.".

  // The tyrant's evening patrol, and the herd's day.
  Rule tyr_dusk when hour(clock) >= 17 and hour(clock) < 20 and not dead(tyrant) and at(tyrant, ?r) and distinct(?r, plain_mid) { Retract at(tyrant, ?r). Assert at(tyrant, plain_mid). }
  Rule tyr_late when hour(clock) >= 20 and hour(clock) < 22 and not dead(tyrant) and at(tyrant, ?r) and distinct(?r, plain_south) { Retract at(tyrant, ?r). Assert at(tyrant, plain_south). }
  Rule tyr_home when (hour(clock) >= 22 or hour(clock) < 17) and not dead(tyrant) and at(tyrant, ?r) and distinct(?r, tyrant_hollow) { Retract at(tyrant, ?r). Assert at(tyrant, tyrant_hollow). }
  Rule tyr_forgets when hour(clock) == 4 and tolerates(tyrant, party) and not dead(tyrant) { Retract tolerates(tyrant, party). Retract tyrantBaited(party). }
  Rule herd_dawn when hour(clock) >= 5 and hour(clock) < 9 and at(lantern_necks, ?r) and distinct(?r, lake_shore) { Retract at(lantern_necks, ?r). Assert at(lantern_necks, lake_shore). }
  Rule herd_day when hour(clock) >= 9 and hour(clock) < 17 and at(lantern_necks, ?r) and distinct(?r, plain_mid) { Retract at(lantern_necks, ?r). Assert at(lantern_necks, plain_mid). }
  Rule herd_night when (hour(clock) >= 17 or hour(clock) < 5) and at(lantern_necks, ?r) and distinct(?r, plain_south) { Retract at(lantern_necks, ?r). Assert at(lantern_necks, plain_south). }
  Observe tyrant_tracks at plain_south as sign when not dead(tyrant) and hour(clock) < 17 "A three-toed track a yard across, pressed into the clay at the plain's edge and already filling with water. Beside it a ribcage, picked.".

  // Ways past the tyrant: leave the plain at evening; the ridge; the three-horn ring; the plate-back ring; the
  // lantern-necks' legs; meat; a fight (genuinely dangerous: level six, five dice a bite).
  Action shelter_plates(actor: group, site: place) "Settle among the sleeping plate-backs and keep your voices down" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, plain_south) and hour(clock) >= 17 and at(plate_backs, plain_south).
    Time 0.
    On success { Assert tolerates(tyrant, actor). }
    Result "The plate-backs have gone down in a ring at dusk, plates out, tails to the middle, the young inside. You sit among their armour with six tons of bone on either side. Something comes along the plain's edge in the dusk, stops, considers the ring, and goes on. It does not like to bite what it has to open.".
  }
  Action shelter_lanterns(actor: group, site: place) "Walk in among the legs of the sleeping lantern-necks" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, plain_south) and hour(clock) >= 17 and at(lantern_necks, plain_south).
    Time 0.
    Resolve check(actor, stealth, dc_fair).
    On success { Assert tolerates(tyrant, actor). }
    Result "You walk in among them as one walks into a wood: grey trunks, a roof of necks, the smell of hay and warm stone. Nothing stirs. Out in the dusk the tyrant comes along the plain's edge, looks at the herd, and turns away. In the morning your coat is damp with the breath of something tall as a house.".
    Otherwise "A foot as wide as a cartwheel is lifted and set down six inches from your head, and you are glad of the dusk.".
  }
  Action bait_tyrant(actor: group, site: place) "Set three rations of meat on the clay and go quietly to the ridge" {
    Requires able(actor) and company(actor) and at(actor, site) and (at(actor, plain_mid) or at(actor, plain_south)) and quantity(actor, rations) >= 3 and not tyrantBaited(party).
    Time 0.
    On success { Decrease quantity(actor, rations) by 3. Assert tyrantBaited(party). Assert tolerates(tyrant, actor). }
    Result "You lay it out where the herd-trail crosses the ridge-path, and back away with your hands low. Behind you, in the dusk, the ground begins to shake in a rhythm. When you look back there is a shape on the clay tall as a house, quite still, eating with its eyes shut.".
  }

  // Ways past the hook-claws.
  Action fire_hooks(actor: group, site: place) "Hold a torch up in the mouth of the hollow" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hook_den) and at(hook_claws, hook_den) and able(hook_claws) and capable(actor, flame) and not tolerates(hook_claws, actor).
    Time 0.
    On success { Retract at(hook_claws, hook_den). Assert at(hook_claws, kingsfoil_hollow). Assert tolerates(hook_claws, actor). }
    Result "They do not like it. One by one the barred heads lower, and the pack goes out of the hollow by the dry stream-bed like water running out of a basin, clicking, its tails out straight. The bare earth where it lay is yours, and you know, quite clearly, that you have made an enemy of the hollow.".
  }
  Action sit_with_hooks(actor: group, site: place) "Ask Mumchance to sit down alone in the middle of the hollow" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hook_den) and mumchanceAboard(wapshotts) and (mumYes(wapshotts) or mumMatters(wapshotts)) and at(hook_claws, hook_den) and not tolerates(hook_claws, actor).
    Time 0.
    On success { Assert tolerates(hook_claws, actor). }
    Result "Mumchance walks into the hollow with his hands open and sits down in the middle of the bare earth. The pack looks at him for a long time. One, then another, lowers its head to the earth. At the end of an hour the youngest has gone to sleep against his boot, and the rest have forgotten there was anyone to guard against.".
  }
  Topic wap_let_go with wapshott "Ask the Colonel to put the Duchess down at the edge of the hollow" when at(party, hook_den) and colonelNamed(wapshotts) and not namedLetGo(wapshotts) and youngAshore(party) once {
    Says "The littlest is on the Colonel's boot, as she has been since the sack was opened. The Colonel looks at the pack. 'She has not once asked me to be anything,' he says. He kneels. He takes her off his boot with both hands and holds her up, and then sets her down on the bare earth. She sits there looking at him. 'Go on,' he says. 'Go on, Duchess.'".
    On discuss { Assert namedLetGo(wapshotts). Increase regard(billie) by 2. }
  }
  Observe hatchling_clings at hook_den when colonelNamed(wapshotts) and not namedLetGo(wapshotts) and youngAshore(party) and not hookTolerates(party) "One hatchling has attached itself to the Colonel's boot, and every time the Colonel moves, it moves with the boot. The pack watches this with a patience that is almost courteous.".

  // Ways past the three-horn herd.
  Action lay_bamboo(actor: group, site: place) "Lay a bundle of bamboo shoots before the cow and back away" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, plain_mid) and at(three_horns, plain_mid) and holding(actor, bamboo_gathered) and not tolerates(three_horns, actor).
    Time 0.
    On success { Spend bamboo_gathered from actor. Assert tolerates(three_horns, actor). }
    Result "The cow looks at the shoots, and at you, and at the calf. She takes a step, and a mouthful, and another. The herd's frill goes down, one plate at a time, like a house closing its shutters. You are, for the length of a meal, a traveller who brings bamboo.".
  }
  Action walk_the_herd(actor: group, site: place) "Cross the herd-trail at the herd's own pace, never looking at the calf" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, plain_mid) and at(three_horns, plain_mid) and not tolerates(three_horns, actor).
    Time 0.
    Resolve check(actor, stealth, dc_hard).
    On success { Assert tolerates(three_horns, actor). }
    Result "You walk as they graze: three steps, a stop, three steps, a stop. You do not look at the calf. The cow's head follows you across the clay like a weathervane, and lets you go.".
    Otherwise "The cow has a exact idea of how far away you are, and it is not as far as you thought.".
  }
  Action sit_with_herd(actor: group, site: place) "Ask Mumchance to sit by the calf" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, plain_mid) and at(three_horns, plain_mid) and mumchanceAboard(wapshotts) and (mumNo(wapshotts) or mumMatters(wapshotts)) and not tolerates(three_horns, actor).
    Time 0.
    On success { Assert tolerates(three_horns, actor). }
    Result "He sits down on the clay by the calf's flank with his white-gloved hands in his lap. The cow looks at him, and her breath goes in and out, three times, and she lowers her head and goes on tearing at the ferns. Mumchance does not move for an hour.".
  }

  // Ways past Captain Harrow: parley, purchase, the cage, the nets, the Society's writ, or a fight with four men.
  Action rot_nets(actor: group, site: place) "Cut through the net-lines and the drying-poles while the men are at their mugs" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, harrow_camp) and not netsRotted(party) and not harrowBeaten(party).
    Time 0.
    Resolve check(actor, trapwork, dc_hard).
    On success { Assert netsRotted(party). Assert harrowBeaten(party). Retract at(harrow_men, harrow_camp). }
    Result "By the time the net-men notice, every line in the camp has been neatly severed a hand's breadth from its peg and the poles lie in the creek. Harrow looks at the wreck for a long minute. 'Well,' he says, 'I did say not to touch the nets.' He sends the men down to the boat. It is not, quite, defeat.".
    Otherwise "A net-man, looking up from his mug, says mildly, 'That is not a fishing knife.'".
  }
  Topic fenwick_writ with fenwick "Ask Sir Gervase to show Captain Harrow the Society's charter" when at(party, harrow_camp) and clausesRead(wapshotts) and not writShown(party) once {
    Says "Sir Gervase unrolls the Society's charter on Harrow's camp-table, kindly, with a flourish, and explains in some detail that the collection of living animals in this region is under the Society's licence and that Captain Harrow's, regrettably, is not. Harrow listens, entirely pleasant. 'And you,' he says, 'are taking a pair of each.' Sir Gervase says it is not at all the same. There is a pause in which the whole island seems to look at the pair of them. 'Well,' says Harrow at last, 'a licence is a licence.' He folds his tents. He has, you notice, taken the calf's cage with him; and he has left it empty on the creek-bank.".
    On discuss { Assert writShown(party). Assert harrowBeaten(party). Assert calfFreed(party). Retract at(harrow_men, harrow_camp). Retract at(harrow, harrow_camp). }
  }
  Observe harrow_gone at harrow_camp when writShown(party) "The camp is struck: a ring of black grass, a stockade of cut mangrove, a hippodrome flag nailed to a post by one corner, and a row of empty crates.".

  // Sir Gervase, who is not wrong, at the lake.
  Observe fenwick_weeps near fenwick when at(party, lake_shore) and herdSeen(party) and hour(clock) >= 5 and hour(clock) < 9 "Sir Gervase Fenwick has sat down in the mud with his drawing-block on his knee and is drawing and weeping at once. He has drawn his own hand in the margin four times, and has not noticed. 'Ten,' he says. 'Ten, and the calves.' He draws a line under it.".
  Topic fenwick_lake with fenwick "Sit down in the mud beside Sir Gervase" when at(party, lake_shore) and herdSeen(party) and not fenwickWept(party) once {
    Says "'Ten,' says Sir Gervase, and cannot go on. He offers you a biscuit. You eat it together.".
    On discuss { Assert fenwickWept(party). }
  }

  // History beyond the story.
  Observe cage_graves at cage_row when true "Beyond the last cage, under a casuarina, six flat stones lie in a row, cut with a wheel and a name each: Warden Osric, Warden Gunnar, Warden Ysolt, Warden Hob, and two that the moss has taken. A seventh place has no stone, only a bronze key-plate set in the earth, and nothing in the slot.".
  Observe cage_nine at cage_row when true "The ninth cage's door has a plate that has been wiped, recently, by hand: NO. 9. THE GREAT BEAST. SENT NORTH IN THE LAST PROGRESS, ON THE HASTY MARY. THE CAGE IS KEPT. The cage is swept. Nobody has swept it since the Wardens, and it is swept.".
  Observe founding_roll at preserve_hall when true "Burnt into the black beam over the hearth, a roll of names: the Founder-King, Aldred of the Wheel, who first went round his kingdom in a cart and ordered a Preserve laid out for the beasts he met on the way; the Wardens, seven; and, last, the Keepers of the Menagerie Royal, nine, the final name left blank." teaches founded_known.
  Entity founded_known: fact "The Preserve was laid out by Aldred of the Wheel, the first king to go round his kingdom, to keep the beasts of the southern sea; seven Wardens kept it, and nine Keepers after them.".
  Milestone m_pipers "heard the dawn-pipers tell the hour of the herd" worth 100 when knows(party, piper_known).
  Milestone m_hollow "followed the glide-lizards to the sheltered hollow" worth 100 when knows(party, hollow_way_known).
  Milestone m_crust "learned the scuttlers' line over the crust" worth 100 when knows(party, crust_safe).
  Milestone m_colony "saw the colony launch" worth 150 when knows(party, colony_known).
  Milestone m_founded "read the founding roll of the Preserve" worth 150 when knows(party, founded_known).

  Action slip_channels(actor: group, site: place) "Wade the channels in the wake of the skimmers when they go back in" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, harrow_camp) and knows(actor, channels_warn) and hour(clock) >= 15 and at(delta_croc, channels) and not tolerates(delta_croc, actor).
    Time 0.
    On success { Assert tolerates(delta_croc, actor). }
    Result "The skimmers go back into the water in a body, one after another, at the hour the old crocodile goes up the bank to sleep. You go in behind them. Nothing in the black water looks at you.".
  }
  Observe colony_coming at cliff_foot when knows(party, colony_known) and hour(clock) >= 4 and hour(clock) < 5 "The first sail-wings have begun to shift on the ledges above. In an hour the ledge will be empty.".
  Observe herd_hour at plain_ridge when knows(party, herd_known) and hour(clock) >= 4 and hour(clock) < 5 "You know where to be at first light. You are in it.".
  Observe map_warns at plain_mid when knows(party, map_read) and hour(clock) >= 15 and hour(clock) < 17 "The Warden's map says THE TYRANT HUNTS AT EVENING. It is not yet evening.".
}

data/goings-on/circus/ledger.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── What the circus eats, owes and mends ───────────────────────────────────────────────────────────────────
  // Each morning the larder goes down by a day; Honoria buys at her price when it runs low and the box will bear
  // it. At every strike the wages are due, ten coin; unpaid twice, the canvasmen sit down and there is no show till
  // they are paid. Every strike wears the canvas; it can be mended with Lusk.
  Measure ateDay(concern). Measure mendedDay(group). Measure honoriaBought(concern). Relation lentColonel(group).
  Rule larder_eaten when (pitched(wapshotts) or onRoad(wapshotts)) and hour(clock) >= 6 and ateDay(wapshotts) < day(clock) {
    Set ateDay(wapshotts) to day(clock). Decrease larder(wapshotts) by 1 or to nothing. }
  Rule larder_bought when pitched(wapshotts) and hour(clock) >= 9 and larder(wapshotts) < 2 and strongbox(wapshotts) >= 9 and honoriaBought(wapshotts) < day(clock) {
    Set honoriaBought(wapshotts) to day(clock). Decrease strongbox(wapshotts) by 6. Increase larder(wapshotts) by 2. }
  Rule wages_paid when onRoad(wapshotts) and hour(clock) < 14 and not wagesReckoned(wapshotts) and strongbox(wapshotts) >= 10 {
    Assert wagesReckoned(wapshotts). Decrease strongbox(wapshotts) by 10. Set arrears(wapshotts) to 0. Retract strikeOn(wapshotts). }
  Rule wages_owed when onRoad(wapshotts) and hour(clock) < 14 and not wagesReckoned(wapshotts) and strongbox(wapshotts) < 10 {
    Assert wagesReckoned(wapshotts). Increase arrears(wapshotts) by 1. }
  Rule hand_paid when onRoad(wapshotts) and wagesReckoned(wapshotts) and hand(party) and not handPaid(party) and strongbox(wapshotts) >= 2 {
    Assert handPaid(party). Decrease strongbox(wapshotts) by 2. Increase quantity(party, gold) by 2. }
  Rule wages_reset when pitched(wapshotts) and wagesReckoned(wapshotts) { Retract wagesReckoned(wapshotts). Retract handPaid(party). }
  Relation wagesReckoned(concern). Relation handPaid(group).
  Initially Assert wagesReckoned(wapshotts).
  Rule canvasmen_sit when arrears(wapshotts) >= 2 and not strikeOn(wapshotts) and pitched(wapshotts) {
    Assert strikeOn(wapshotts). }
  Observe strike_seen near pole when strikeOn(wapshotts) and at(pole, ?r) "Lusk's canvasmen are sitting in a row on the grass in front of the big top with their arms folded and their caps over their eyes. A board leans against the ticket wagon, chalked in a large careful hand: NO PAY NO PLAY. Lusk is sitting at the end of the row, with them.".
  Topic lusk_strike with lusk "Ask Lusk what it would take for the lads to play" when strikeOn(wapshotts) {
    Says "'Two stands owed,' says Lusk. 'Twenty coin.' He looks at you, not unkindly. 'I'll not cross them. They're right. If somebody paid the arrears, we'd have the big top up and lit by seven, and not a word said.'".
  }
  Action pay_arrears(actor: group, site: place) "Pay Lusk's lads their arrears out of your own purse" {
    Speaker lusk. Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(lusk, site) and strikeOn(wapshotts) and quantity(actor, gold) >= arrears(wapshotts) * 10.
    On success { Decrease quantity(actor, gold) by arrears(wapshotts) * 10. Set arrears(wapshotts) to 0. Retract strikeOn(wapshotts). Increase regard(lusk) by 2. }
    Result "Lusk counts it, carefully, twice, and divides it among eight caps on the grass. The lads stand up. One of them shakes your hand. Lusk says, 'Thank you.' It is the most anybody has heard from him since the spring.".
  }
  Action talk_lads_round(actor: group, site: place) "Talk Lusk's lads into playing tonight, on your word they will be paid at the Fair" {
    Speaker lusk. Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(lusk, site) and strikeOn(wapshotts) and not talkedLads(actor).
    Resolve check(actor, persuasion, dc_hard).
    On success { Retract strikeOn(wapshotts). Set arrears(wapshotts) to 1. Assert talkedLads(actor). Assert promiseMade(lads_promise). }
    On failure { Assert talkedLads(actor). }
    Result "You talk to them, the eight of them in a row on the grass with their caps over their eyes, about the Fair, and the box, and the Colonel, and the house that is already queuing at the gate; and one by one the caps come up. 'On your word,' says Lusk at last. 'Not his. Yours.' They stand up.".
    Otherwise "You talk to them, and they listen, politely, with their caps over their eyes, and at the end one of them says 'Very nice,' and they go on sitting.".
  }
  Relation talkedLads(group).
  Promise lads_promise "to see Lusk's canvasmen paid what they are owed" to lusk
    kept when arrears(wapshotts) < 1 and not strikeOn(wapshotts) and noteSettled(wapshotts) "Lusk nods to you across the backyard: the lads are paid."
    broken when arrears(wapshotts) >= 2 "Lusk's lads are sitting on the grass again, and Lusk does not look at you." { Decrease regard(lusk) by 2 or to nothing. }.
  Action pay_wages(actor: group, site: place) "Put ten coin of your own into the strongbox for the wages" {
    Speaker ada. Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(ada, site) and pitched(wapshotts) and quantity(actor, gold) >= 10.
    On success { Decrease quantity(actor, gold) by 10. Increase strongbox(wapshotts) by 10. Increase regard(ada) by 1. Assert lentColonel(actor). }
    Result "Ada looks at the coins, and at you, and writes in the ledger, in a column of its own, your name and the sum. 'That's a loan,' she says, 'whatever you say, and it'll be paid, whatever he says.'".
  }

  // A wheel off on the road: the wagons come in late, unless someone puts a shoulder to it.
  Relation wheelOff(concern). Relation wheelThrown(concern).
  Rule wheel_thrown when onRoad(wapshotts) and hour(clock) >= 8 and not wheelThrown(wapshotts) { Assert wheelThrown(wapshotts). }
  Rule wheel_comes_off when wheelThrown(wapshotts) and onRoad(wapshotts) and not wheelOff(wapshotts) and not wheelSettled(wapshotts) and dice(clock) <= 20 + (2 - canvas(wapshotts)) * 15 {
    Assert wheelOff(wapshotts). Assert wheelSettled(wapshotts). }
  Rule wheel_holds when wheelThrown(wapshotts) and not wheelSettled(wapshotts) { Assert wheelSettled(wapshotts). }
  Rule wheel_reset when pitched(wapshotts) and wheelThrown(wapshotts) { Retract wheelThrown(wapshotts). Retract wheelSettled(wapshotts). Retract wheelOff(wapshotts). }
  Relation wheelSettled(concern).
  Observe wheel_off near lusk when wheelOff(wapshotts) and onRoad(wapshotts) "Halfway along, the canvas wagon is down on one corner in the ditch with its near hind wheel off and lying in the road, and the whole circus is standing round it giving advice. Lusk is under the axle. Bucephalus has gone on alone for a quarter of a mile, and is waiting, with his back to everybody, like a man pretending not to know his family.".
  Action wheel_on(actor: group, site: place) "Put your shoulder under the canvas wagon while Lusk gets the wheel back on" {
    Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(lusk, site) and wheelOff(wapshotts) and onRoad(wapshotts).
    Resolve check(actor, brawn, dc_fair).
    On success { Retract wheelOff(wapshotts). Increase regard(lusk) by 1. }
    Result "You get your shoulder under the tail of the wagon with three canvasmen and Honoria, who takes most of it, and heave, and the corner comes up out of the ditch an inch, two, and Lusk slides the wheel on and drives the pin home with the heel of his hand. A cheer. Bucephalus, a quarter of a mile off, turns round and comes back as if it had been his idea.".
    Otherwise "You heave with the rest, and the wagon comes up an inch and goes down again on Lusk's thumb, and the language under the axle is something the circus will quote for years.".
  }
  Rule late_in near quirk when wheelOff(wapshotts) and onRoad(wapshotts) and hour(clock) >= 14 and hour(clock) < 18 and not lateTold(wapshotts)
    says "Word comes along the road that Wapshott's will be late in: a wheel off the canvas wagon. There will be no parade today." { Assert lateTold(wapshotts). }
  Relation lateTold(concern).
  Rule late_reset when pitched(wapshotts) and lateTold(wapshotts) { Retract lateTold(wapshotts). Assert paraded(wapshotts). }
  // Signing on, and riding with the wagons.
  Topic ada_sign with ada "Sign Ada's book as a hand of the circus" when not hand(actor) once {
    Says "Ada opens the book at a page with a great many names on it, some crossed out, one with a skull drawn beside it. 'Two coin a stand when there is any,' she says, 'board, a place under a wagon, and the right to be shouted at by everyone.' She hands you the pen. 'Sign there. Hands travel with the wagons. Tell Lusk if you're riding.' When you have signed, she blots it, and for a moment almost smiles. 'Welcome to Wapshott's. Don't lend him money.'".
    On discuss { Assert hand(actor). Assert admitted(actor). }
  }
  Topic lusk_ride with lusk "Tell Lusk you will ride with the wagons when they go on" when hand(actor) and not riding(actor) {
    Says "Lusk nods. 'Six,' he says. 'Sharp.' Then, after a while: 'Cookhouse wagon. Tail-board. Mind Honoria's feet.'".
    On discuss { Assert riding(actor). }
  }
  Topic lusk_stay with lusk "Tell Lusk you will make your own way, this time, and not ride with the wagons" when riding(actor) {
    Says "Lusk nods. 'Road's there,' he says, which seems to cover it.".
    On discuss { Retract riding(actor). }
  }
  Rule riding_needs_hand when riding(party) and not hand(party) { Retract riding(party). }

  // Buying the larder, cheaper than the Colonel does.
  Relation sellsTo(place, group).
  Initially Assert sellsTo(tober_a, merchant_a). Initially Assert sellsTo(tober_b, merchant_b). Initially Assert sellsTo(tober_c, merchant_c).
  Measure haggledDay(group).
  Action haggle_larder(actor: group, seller: group, site: place) "Talk {seller} down on flour, oats and bacon for the circus's larder, four coin" {
    Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(seller, site) and current(wapshotts, ?g) and sellsTo(?g, seller) and pitched(wapshotts)
      and quantity(actor, gold) >= 4 and haggledDay(actor) < day(clock) and larder(wapshotts) < 8
      and knows(actor, larder_known).
    Resolve check(actor, persuasion, dc_fair).
    On success { Decrease quantity(actor, gold) by 4. Increase quantity(seller, gold) by 4. Increase larder(wapshotts) by 3. Set haggledDay(actor) to day(clock). Increase regard(honoria) by 1. }
    On failure { Decrease quantity(actor, gold) by 4. Increase quantity(seller, gold) by 4. Increase larder(wapshotts) by 1. Set haggledDay(actor) to day(clock). }
    Result "You talk {seller} down from the price the Colonel always pays to the price anyone else would, and then a little further, for the circus's sake and the sake of the Ox's pie. Three days' flour, oats and bacon go up to the field in a handcart, and Honoria, when she sees it, kisses you on the top of the head.".
    Otherwise "{seller} has met the Colonel, and knows a circus when one stands in the shop. You get a day's worth for four coin, and a look.".
  }
  Action give_rations(actor: group, site: place) "Give Honoria two of your own rations for the larder" {
    Speaker honoria. Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(honoria, site) and quantity(actor, rations) >= 2.
    On success { Decrease quantity(actor, rations) by 2. Increase larder(wapshotts) by 1. Increase regard(honoria) by 1. }
    Result "Honoria takes them as if they were a bunch of violets. 'That's thirty dinners' worth of soup,' she says, which cannot be true, and somehow is.".
  }
  // The canvas, mended a seam at a time.
  Action mend_canvas(actor: group, site: place) "Climb up on the big top with Lusk and mend a rotten seam" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(lusk, site) and pitched(wapshotts) and freeHour() and canvas(wapshotts) < 3 and mendedDay(actor) < day(clock).
    Resolve check(actor, mending, dc_fair).
    On success { Increase canvas(wapshotts) by 1. Set mendedDay(actor) to day(clock). Increase regard(lusk) by 1. }
    On failure { Set mendedDay(actor) to day(clock). }
    Result "An hour up on the canvas of the big top, spread-eagled on the warm slope of it with the field below, sewing a seam with a palm and a needle as long as your hand while Lusk sews toward you from the other end. When your stitches meet his in the middle he looks at them, and then at you, and nods.".
    Otherwise "An hour up on the canvas, and your stitches will not lie flat. Lusk comes along the seam behind you and takes them all out, without a word, and does them again.".
  }
  Action lend_colonel(actor: group, site: place) "Lend the Colonel ten coin, against the Fair" {
    Speaker wapshott. Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(wapshott, site) and quantity(actor, gold) >= 10 and not lentColonel(actor) and metCircus(actor).
    On success { Decrease quantity(actor, gold) by 10. Increase strongbox(wapshotts) by 10. Assert lentColonel(actor). Increase regard(wapshott) by 1. Decrease regard(ada) by 0. }
    Result "The Colonel takes the coins as a bishop takes a relic, and kisses one, and gives them to Ada, who was standing behind him and did not want him to see her face. 'You will be repaid,' he says, 'TENFOLD.' Ada writes down: ten.".
  }
  Rule colonel_repays near ada when lentColonel(party) and at(party, ?r) and at(ada, ?r) and noteDischarged(wapshotts) and strongbox(wapshotts) >= 10 and not repaid(party)
    says "Ada finds you before you have finished breakfast and counts ten coin into your hand, and then, after a moment, one more. 'From the Colonel,' she says. 'He said tenfold. I said one. We compromised.'" {
    Assert repaid(party). Decrease strongbox(wapshotts) by 11. Increase quantity(party, gold) by 11. }
  Relation repaid(group).

  // ── The Brothers Quincey ───────────────────────────────────────────────────────────────────────────────────
  Topic hench_quinceys with hench "Ask Hench about the Brothers Quincey's father" when knows(actor, father_quincey) once {
    Says "'Barnaby Quincey,' says Hench, at once. 'Tumbler. Dead nine years. A good man and a very poor dresser.' He puts down his needle. 'When the Waggoner at Dunmere sold up, the Colonel bought the players' lumber in the loft for a song, and there was a Quincey trunk in it. It is in my wagon. Under the Margravine's second-best petticoat. The boys have never asked for it. I do not think they know it was saved.'".
    On discuss { Assert knows(actor, quincey_trunk). }
  }
  Entity quincey_trunk: fact "Hench has the late Barnaby Quincey's trunk in the wardrobe wagon, bought with the lumber of the Waggoner's loft at Dunmere.".
  Action search_trunk(actor: group, site: place) "Go through Barnaby Quincey's old trunk with Hench" {
    Speaker hench. Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(hench, site) and knows(actor, quincey_trunk) and not knows(actor, wheel_bill).
    On success { Assert knows(actor, wheel_bill). Give wheel_playbill to actor. Assert knows(actor, playbill_given). }
    Result "Under the Margravine's second-best petticoat, a battered trunk with B.Q. on the lid: a pair of tights darned past darning, a wooden leg with a shoe on it, a bundle of letters to a Mrs Quincey, and a playbill, foxed and soft as cloth, from a fair at Marlow twenty-four years ago. MR BARNABY QUINCEY, it says, WILL PERFORM, FOR THE FIRST TIME BEFORE ANY PUBLIC, THE QUINCEY WHEEL, OF HIS OWN INVENTION, WITH MR TOBIAS GROAT. Beneath it, a woodcut: two men back to back, going over each other like the spokes of a wheel. Hench reads it over your shoulder. 'Twenty-four years,' he says. 'The boys are twenty-two.'".
  }
  Entity wheel_bill: fact "A playbill of twenty-four years ago shows the Quincey Wheel performed by Barnaby Quincey, of his own invention, before either of his sons was born.".
  Kind quincey_bill_kind "Barnaby Quincey's old playbill" is gear worth 0 weighing 0
    described "A foxed playbill from a fair at Marlow, twenty-four years old: MR BARNABY QUINCEY WILL PERFORM THE QUINCEY WHEEL, OF HIS OWN INVENTION. A woodcut of two men back to back, going over each other like the spokes of a wheel.".
  Item wheel_playbill "Barnaby Quincey's old playbill" is quincey_bill_kind at tober_a hidden until playbill_given.
  Discovery playbill_given "You have Barnaby Quincey's old playbill, from his trunk.".
  Action show_brothers(actor: group, site: place) "Get both Quinceys together and show them their father's playbill" {
    Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(hal, site) and at(dunstan, site) and holding(actor, quincey_bill_kind) and not feudMended(hal) and not dunstanGone(dunstan).
    On success { Assert feudMended(hal). Increase regard(hal) by 2. Increase regard(dunstan) by 2. Increase regard(pip) by 1. }
    Result "You put the playbill down on an upturned bucket between them, and stand back. Hal reads it. Dunstan reads it upside down, then goes round and reads it the right way up. Nobody says anything. Somewhere behind the canvas the band is tuning, badly. 'He dreamed it,' says Hal at last, hoarsely. 'He worked it out,' says Dunstan. 'On a slate.' They look at the woodcut, the two men going over each other like a wheel. 'He never said,' says Hal. 'He wanted us to think it was ours,' says Dunstan. And then, without anybody deciding, they are hitting each other, but it is mostly on the shoulders, and it turns into something else, and Pip, watching from the ring boards, bursts into tears and says she is not crying, she has sawdust in both eyes.".
  }
  Topic honoria_heads with honoria "Ask Honoria to bang the Quinceys' heads together, as their father would have" when knows(actor, father_quincey) and regard(honoria) >= 1 and not feudMended(hal) and not dunstanGone(dunstan) once {
    Says "Honoria wipes her hands on her apron. 'Barnaby used to say that,' she says, 'and never did it, not once; he was too soft.' She goes into the ring, where the brothers are tumbling at opposite ends, takes one by each collar, lifts them off the ground, and brings their heads together, not hard, with a noise like two coconuts meeting at a fair. She sets them down. 'Your father,' she says, 'would be ashamed of the pair of you. Now kiss and be friends or I'll do it again.' They do not kiss. But that night, in the ring, they look at each other.".
    On discuss { Assert feudMended(hal). Increase regard(pip) by 1. }
  }

  // ── The Sylph's mother ─────────────────────────────────────────────────────────────────────────────────────
  Place tripe_lane_c "the lane behind the green" is room within town_c at 0, 2.
  Passage tripe_way_c "the alley off the green" is path between green_c and tripe_lane_c taking 3 minutes.
  Observe tripe_scene at tripe_lane_c when true "A narrow lane of whitewashed back-yards, wet cobbles, and a smell of boiling. In one yard a small woman with forearms like a navvy's is scraping tripe on a board under a lean-to, very fast, with a curved knife.".
  Person pruett "Mrs Pruett" at tripe_lane_c {
    Role "a tripe-dresser of the town". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "The small woman does not stop scraping. 'Tripe's a penny the pound,' she says, 'and honeycomb's twopence, and if you're from the shrine I've paid.' She looks up at you with very still grey eyes, which you have seen before, forty feet up.".
  }
  Rule pruett_to_show when here(tober_c) and showOn(wapshotts) and not at(pruett, ring_c) and not reunited(pruett) { Assert at(pruett, ring_c). }
  Rule pruett_home when not showOn(wapshotts) and not at(pruett, tripe_lane_c) and not reunited(pruett) { Assert at(pruett, tripe_lane_c). }
  Observe pruett_back near pruett when showOn(wapshotts) and at(pruett, ring_c) and knows(party, susan_pruett) "On the very back bench, in her apron, alone, sits Mrs Pruett from the tripe-lane, with her hands folded, watching the wire.".
  Topic pruett_circus with pruett "Ask Mrs Pruett whether she goes to the circus" when true once {
    Says "'Every night they're here,' says Mrs Pruett, scraping. 'Back bench. It's a penny well spent.' A pause. 'I like the wire-walker. She has my mother's ankles. My mother could stand on a gate.' The knife stops. 'That's all.' It starts again.".
  }
  Topic pruett_susan with pruett "Tell Mrs Pruett you know who the Sylph of the Wire is" when knows(actor, susan_pruett) and not reunited(pruett) once {
    Says "Mrs Pruett puts down the knife. She wipes her hands on her apron, very thoroughly, one finger at a time. 'She went off at fifteen,' she says, 'with my good knife and a rope I'd had for the washing. Left a note. YOU WILL HEAR OF ME.' She almost laughs. 'And I did. On the bills. MADEMOISELLE.' She picks the knife up again and does not use it. 'She's never once come down the lane. Eight years. I'll not go up there to her. I'll not stand in a field like a tinker's dog and be told she has a headache.' Her voice does not change at all. 'You tell her, if she wants her mother, her mother's where she left her.'".
    On discuss { Assert knows(actor, pruett_waits). }
  }
  Entity pruett_waits: fact "Mrs Pruett of the tripe-lane will not go up to the circus to her daughter, but says her daughter's mother is where she left her.".
  Action persuade_pruett(actor: group, site: place) "Persuade Mrs Pruett to come round to the back of the big top after the show, just once" {
    Speaker pruett. Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(pruett, site) and knows(actor, pruett_waits) and not reunited(pruett) and not triedPruett(actor) and here(tober_c).
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert reunited(pruett). Assert walksForHer(zephyrine). Increase regard(zephyrine) by 2. Increase larder(wapshotts) by 2. }
    On failure { Assert triedPruett(actor). }
    Result "You do not tell her anything about her daughter she does not know. You tell her about the wire: that the Sylph sits down on it halfway, every night, and nobody in the house knows why, and you think you do. Mrs Pruett scrapes the same piece of tripe for a long while. Then she unties her apron. That night, when the house has gone, a small woman in her Sunday shawl comes round the back of the big top past the horse lines, with a parcel of tripe under her arm, and knocks on the steps of a blue wagon with stars on it; and the door opens, and nobody in the backyard looks, very carefully, for an hour.".
    Otherwise "'No,' says Mrs Pruett. 'She knows where the lane is.'".
  }
  Relation triedPruett(group).
  Topic zeph_mother with zephyrine "Tell Zéphyrine that her mother sits at the back every night, and is where she left her" when knows(actor, pruett_waits) and not reunited(pruett) once {
    Says "The Sylph goes very white, and then very red, and her accent goes altogether. 'She comes?' says Susan Pruett of {town_c}. 'Every night? The old devil. The old devil. She never said a word.' She sits down on the wagon steps. 'I wrote her a letter every round for eight years and I tore them all up. I was going to come down the lane in a carriage. With a footman. And throw her a purse.' She laughs, and it comes out wrong. 'I haven't got a carriage. I haven't got a footman.' She puts her face in her hands. 'Will you walk down with me? I'll not get there on my own. I've walked over a river on a rope and I can't walk down that lane.'".
    On discuss { Assert zephAsks(zephyrine). }
  }
  Relation zephAsks(group). Relation reunited(group).
  Action walk_down_lane(actor: group, site: place) "Walk down the tripe-lane with Zéphyrine to her mother's yard" {
    Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(zephyrine, site) and zephAsks(zephyrine) and here(tober_c) and not reunited(pruett) and not showOn(wapshotts).
    On success { Assert reunited(pruett). Assert walksForHer(zephyrine). Assert at(actor, tripe_lane_c). Assert at(pruett, tripe_lane_c). Increase regard(zephyrine) by 3. Increase larder(wapshotts) by 2. }
    Result "She walks down through {town_c} beside you in her silver wrap with her chin up, past people who know her and do not know her, into the lane; and at the yard gate she stops. Mrs Pruett is scraping tripe. She does not look up. 'You've not been eating,' she says. 'I can see your collar-bones from here.' 'Mother,' says the Sylph of the Wire. 'You'll want your knife back, I expect,' says Mrs Pruett, and puts hers down, and then the two of them are holding each other in a yard full of tripe, and neither of them says anything at all, and you go and look at a wall for a while. When you come back Mrs Pruett is wrapping a great parcel of tripe and honeycomb for the circus. 'Thirty of them,' she says, 'and the horse. Tripe's good for a horse.' It is not, but nobody says so.".
  }
  Topic zeph_after with zephyrine "Ask Zéphyrine how she does" when reunited(pruett) once {
    Says "'I'm going to stay Zéphyrine,' says Susan Pruett. 'On the bills. Nobody pays a penny to see Susan.' She is mending a slipper and humming. 'She's coming to the Fair at {town_a}. She's never been further than the next parish. She says if I'm going to walk across a river on a rope she wants to be underneath with her apron out.' She bites the thread. 'Mind you, I still haven't got a steeple.'".
  }

  // ── Mumchance's knees ───────────────────────────────────────────────────────────────────────────────────────
  Relation camphor(group).
  Action buy_camphor(actor: group, seller: group, site: place) "Buy a twist of camphor from {seller} for Mumchance's liniment, two coin" {
    Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(seller, site) and current(wapshotts, ?g) and sellsTo(?g, seller) and knows(actor, knees_known)
      and quantity(actor, gold) >= 2 and not camphor(actor).
    On success { Decrease quantity(actor, gold) by 2. Increase quantity(seller, gold) by 2. Assert camphor(actor). }
    Result "{seller} sells you a twist of camphor in blue paper. It smells like a winter cupboard.".
  }
  Action camphor_to_honoria(actor: group, site: place) "Give Honoria the camphor for Mumchance's liniment" {
    Speaker honoria. Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(honoria, site) and camphor(actor).
    On success { Retract camphor(actor). Assert liniment(mumchance). Set linimentDay(mumchance) to day(clock) + 4. Increase regard(honoria) by 1. Increase regard(mumchance) by 1. }
    Result "Honoria takes the camphor and sniffs it and nods, and mixes it in a saucepan with goose-grease, turpentine and something from a brown bottle, and the backyard fills with a smell like a horse's funeral. She takes it to Mumchance in a jar. He rubs it on his knees, sitting on his bucket, without a word; and after a while he stands up, and bends, and straightens, and does a small, perfect, entirely unnecessary pratfall onto the grass, and lies there looking at the sky. 'Ah,' he says.".
  }
  Rule liniment_wears when liniment(mumchance) and day(clock) > linimentDay(mumchance) { Retract liniment(mumchance). }

  // ── Lusk's Nell ────────────────────────────────────────────────────────────────────────────────────────────
  Place aske_cottage_b "Mrs Aske's cottage" is room within town_b at 0, 2 indoors.
  Passage aske_door_b "Mrs Aske's door" is door between green_b and aske_cottage_b.
  Observe aske_scene at aske_cottage_b when true "A tidy cottage with a dresser of willow-pattern plates and a clock that ticks very loudly, as if keeping an eye on everyone.".
  Person aske "Mrs Aske" at aske_cottage_b {
    Role "a grandmother of the town". Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Greets "A tall old woman with her hair in a tight grey knot looks up from a sampler. 'If you're from the circus,' she says, 'the answer is no.'".
  }
  Person nell "Nell" at aske_cottage_b {
    Role "a girl of eight, Lusk's daughter". Ancestry human. Peaceable. Pronouns she.
    Greets "A girl of eight with her father's enormous serious face, in miniature, is sitting under the table drawing a tent on a slate. 'Is my dad coming?' she says. 'Has he got the big top up? Is it the red one? It's always the red one.'".
  }
  Relation nellAtShow(group).
  Action persuade_aske(actor: group, site: place) "Ask Mrs Aske to bring Nell to the circus tonight, to see her father's tent lit" {
    Speaker aske. Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(aske, site) and knows(actor, nell_known) and here(tober_b) and not nellAtShow(nell) and not triedAske(actor).
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert nellAtShow(nell). }
    On failure { Assert triedAske(actor). }
    Result "You tell her about the canvas wagon, and the eight good lads, and the man who sews the big top seam by seam every morning and carries a child's drawing of it folded in his shirt. Mrs Aske goes on with her sampler, and the clock goes on with its ticking, and you count eleven ticks. 'Once,' she says at last. 'The back bench. And home by nine.' Under the table there is a sound like a kettle coming to the boil.".
    Otherwise "'No,' says Mrs Aske. 'I know what a circus is. A circus is a thing that leaves.'".
  }
  Relation triedAske(group).
  Rule nell_to_show when nellAtShow(nell) and showOn(wapshotts) and here(tober_b) and not nellSeen(nell) { Assert at(nell, ring_b). Assert at(aske, ring_b). Assert nellSeen(nell). }
  Relation nellSeen(group).
  Rule nell_seen near nell when nellSeen(nell) and showOn(wapshotts) and at(nell, ring_b) and not nellTold(nell)
    says "On the back bench, very upright, sits Mrs Aske in her best bonnet, and beside her, standing on the bench, Nell, with her mouth open, looking up at the canvas her father put there. Down at the ring curtain, where the canvasmen stand to watch, a very large man has taken off his cap and is holding it in both hands." {
    Assert nellTold(nell). Increase regard(lusk) by 3. }
  Relation nellTold(group).
  Rule nell_home when nellSeen(nell) and not showOn(wapshotts) and at(nell, ring_b) { Assert at(nell, aske_cottage_b). Assert at(aske, aske_cottage_b). }
  Topic lusk_nell_thanks with lusk "Ask Lusk whether Nell liked the show" when nellTold(nell) once {
    Says "Lusk does not answer for a while. Then he says, all at once, as if it had been waiting a long time behind his teeth: 'She said the red one was the best one, and she was right, and her gran held my hand at the gate, which she's not done since the funeral, and I'll sew your boots for you, or your coat, or anything you've got, for the rest of my life.' He stops. He looks quite frightened. 'That's a lot of words,' he says.".
  }
}

data/goings-on/circus/lives.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── The company's own lives, in the Revels round ────────────────────────────────────────────────────────────
  // These go on whether or not the company has a hand in them. The company can be asked to; it changes how they go.

  // Honoria and Mumchance: Wakeham, at last, in the chapel of the Rest on the day before the Revels.
  Relation weddingSet(group). Relation weddingDone(group). Relation witness(group). Relation ringMade(group).
  Rule wedding_set when letterCome(wapshotts) and day(clock) >= letterDay(wapshotts) + 3 and not weddingSet(honoria) { Assert weddingSet(honoria). }
  Topic hon_singing with honoria "Ask Honoria why she is singing over the pot" when weddingSet(honoria) and not weddingDone(honoria) once {
    Says "Honoria goes red from the apron up. 'He asked me,' she says. 'Last night. At the cookhouse door.' She stirs the pot, which does not need stirring. 'He said one word. Wakeham. Just that. With a question at the end of it.' She wipes her eyes on her sleeve. 'Thirty years that bridge has been washed out. We're to be married in the little chapel up at the Rest, the day before the Revels, by {priest_b}, if {priest_b} will climb the hill.' She looks at you. 'Will you stand for us? Somebody has to hold the ring, and Gus says his hands shake, and mine would bend it.'".
    On discuss { Assert witness(actor). Increase regard(honoria) by 2. }
  }
  Topic hob_ring with ninepence "Ask Ninepence whether he could make a wedding ring for the Ox" when witness(actor) and (hobJoined(ninepence) or hobStaysToRevels(ninepence)) and not ringMade(honoria) once {
    Says "'For the Ox,' says Ninepence, and something in his brown face goes soft. 'Her mother left cream for the slate-hob at Abernant forty years and never once saw him. He told me.' He holds out a long hand. 'Give me a night and a brass curtain-ring off the wardrobe wagon.' In the morning there is a ring on the cookhouse step: brass, worked all round with tiny slates, and a bridge.".
    On discuss { Assert ringMade(honoria). }
  }
  Rule wedding_rest at rest_chapel when weddingSet(honoria) and here(tober_r) and day(clock) == revelsDay(wapshotts) - 1 and hour(clock) >= 12 and not weddingDone(honoria) and at(party, rest_chapel)
    says "The chapel of the Rest is full to the door and the door is full of Bucephalus. {priest_b} has climbed the hill, and is out of breath, and is moved. Honoria wears a hat with a whole garden on it; Mumchance wears no face at all, for the first time in public, and is a plain old man with kind eyes, and looks younger. When {priest_b} asks for the ring, you hold it out; and Mumchance, who hardly ever says anything at all, says two words, clearly, in the little chapel under the crowned wheel: 'I do.' Then Honoria lifts him off his feet, which was not in the service, and nobody minds." {
    Assert weddingDone(honoria). Increase regard(honoria) by 2. Increase regard(mumchance) by 2. }
  Rule wedding_away when weddingSet(honoria) and here(tober_r) and day(clock) == revelsDay(wapshotts) - 1 and hour(clock) >= 13 and not weddingDone(honoria) {
    Assert weddingDone(honoria). }
  Observe wedding_after near honoria when weddingDone(honoria) and pitched(wapshotts) and hour(clock) >= 18 and hour(clock) < 19 "Honoria Bulstrode, who is Honoria Fell now, if anyone dares call her it, is making Mumchance up for the show herself, with the white and the lard, very carefully, at the cookhouse table; and he is letting her.".

  // Ada, The Brigand's Bride, and a reader at court.
  Relation partRead(concern). Relation dowagerReads(group). Relation adaReveals(group). Relation colonelKnowsBride(group).
  Rule part_read near wapshott when letterCome(wapshotts) and day(clock) >= letterDay(wapshotts) + 5 and hour(clock) >= 21 and pitched(wapshotts) and not partRead(wapshotts)
    says "In the backyard after the show, Quirk comes in from the road with the new part of THE BRIGAND'S BRIDE from the printer at {town_a}, and the Colonel, who has never read a novel, seizes it and reads it aloud to the cookhouse fire with all the voices. He is magnificent. He is magnificent for eleven pages, until there enters, in a crimson coat, COUNT FLORIZEL WAPSOTTI, A MOUNTEBANK OF RUINOUS HABITS AND IRRESISTIBLE MOUSTACHE, and he stops. He reads the paragraph again, silently. Across the fire Ada Thripp has gone the colour of the page." {
    Assert partRead(wapshotts). }
  Topic tobias_dowager with tobias "Ask Tobias what the Dowager Archduchess is like" when knows(actor, letter_known) once {
    Says "'Terrifying,' says Tobias at once, with love. 'She is a Dowager, an Archduchess and a Margravine, by three treaties, and nobody knows which she is on any day until she gives you a hand to kiss. She is eighty. She has outlived two husbands and a war.' He lowers his voice. 'And she reads, every month, a penny romance called THE BRIGAND'S BRIDE, which her ladies buy for her in disguise, and she would give a province to know who A Lady of the Road is. She has said so. In front of a bishop.'".
    On discuss { Assert knows(actor, dowager_reads). }
  }
  Entity dowager_reads: fact "The Dowager Archduchess who comes to the Revels reads THE BRIGAND'S BRIDE every month in secret, and would give a province to know who A Lady of the Road is.".
  Topic ada_dowager with ada "Tell Ada that the Dowager Archduchess reads The Brigand's Bride, and longs to meet its author" when knows(actor, ada_writes) and knows(actor, dowager_reads) and not adaReveals(ada) once {
    Says "Ada puts down her pencil. 'The Dowager,' she says. 'Reads. The Bride.' She looks at the ledger as if it might help. 'If I say who I am, the Colonel will know he's Count Wapsotti. Everybody will. I'll be the book-keeper who writes penny dreadfuls.' Then, slowly: 'I'll be a writer who keeps books.' She closes the ledger. 'I'll think. Don't watch me thinking.'".
    On discuss { Assert adaReveals(ada). }
  }
  Topic wap_bride with wapshott "Tell the Colonel who wrote The Brigand's Bride" when partRead(wapshotts) and knows(actor, ada_writes) and not colonelKnowsBride(wapshott) once {
    Says "The Colonel says nothing for so long that you think he has not heard. Then: 'Ada.' He looks across at the ticket wagon. 'Ada wrote Wapsotti.' His chest begins, slowly, to swell. 'A COUNT,' he says. 'She made me a COUNT. Irresistible MOUSTACHE.' He strides off to the ticket wagon, and you hear him through the hatch, very loud and very hurt and very proud all at once: 'Eleven hundred copies? ELEVEN HUNDRED? And in part twenty-three I am to be hanged?'".
    On discuss { Assert colonelKnowsBride(wapshott). }
  }

  // The Sylph's Ascension: a wire from the gatehouse tower across the Long Court, at the Revels.
  Relation ascensionRigged(concern). Relation triedRig(group).
  Topic zeph_tower with zephyrine "Tell Zéphyrine about the gatehouse tower at the King's Rest" when letterCome(wapshotts) and knows(actor, ascension_known) once {
    Says "The Sylph goes very still. 'How high?' You tell her. 'And the court below. Half a furlong of court, and the Household of the Progress looking up.' She stands, and her accent is gone entirely; she is Susan Pruett of {town_c}, and she wants something so much she is shaking. 'The Ascension. From a tower. My mother underneath.' She takes your hands. 'Lusk will have to anchor it. And somebody will have to go up that tower with the end of the rope. I can't carry the rope; I have to carry myself.'".
    On discuss { Assert knows(actor, ascension_plan). }
  }
  Entity ascension_plan: fact "Zéphyrine means to make her Ascension at the Revels on a wire from the gatehouse tower of the King's Rest across the Long Court, if Lusk anchors it and somebody takes the rope up the tower.".
  Action rig_ascension(actor: group, site: place) "Take the end of the Sylph's wire up the gatehouse tower while Lusk anchors it at the mounting-block" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gate_tower) and knows(actor, ascension_plan) and here(tober_r) and not ascensionRigged(wapshotts) and not triedRig(actor).
    Resolve check(actor, climbing, dc_fair).
    On success { Assert ascensionRigged(wapshotts). Increase regard(zephyrine) by 2. Increase regard(lusk) by 1. }
    On failure { Assert triedRig(actor). }
    Result "With a coil of the Sylph's wire over your shoulder you make it fast round the gatehouse merlon in the knot Lusk taught you, three turns and a hitch, while Old Tom watches with interest and tries to steal the end. Far below, across the court, Lusk hauls on the turnbuckle at the mounting-block until the wire sings, and the whole Long Court is suddenly crossed by a line too fine to see except where the sun runs along it.".
    Otherwise "You get the wire round the merlon and the knot will not sit, and the whole coil slithers off the parapet and down the face of the gatehouse with a long singing rattle; Lusk, below, looks up at you for some time.".
  }

  // Clemency Vane, offered the chance to be funny.
  Relation clemencyFolly(group).
  Topic offer_clemency with clem_vane "Offer Clemency Vane the part of Folly in Wapshott's masque at the Revels" when knows(actor, clemency_comic) and knows(actor, letter_known) and not clemencyFolly(clem_vane) once {
    Grave "A leading lady who plays in a rival's masque does not go back to her own company's the same.".
    Says "Clemency Vane looks at you over her cold tea for a long time. 'Folly,' she says. 'In a circus masque. Before the Household of the Progress. With my husband in the other masque, being Justice.' She puts the cup down very carefully. 'He will never forgive me.' A pause. 'He has never once laughed at me. Not once in twenty years.' She stands up. 'Yes. Tell your Colonel yes. Tell him I want a fan, and a ladder, and I want to sit down in the middle of something.'".
    On discuss { Assert clemencyFolly(clem_vane). }
  }

  // Fipps's Grand Circus Overture, for a band of twenty: Pell's musicians, and the low G.
  Relation orchestraLent(group).
  Topic augustus_band with augustus "Ask Augustus Pell to lend his musicians for Fipps's Overture at the Revels" when knows(actor, letter_known) and knows(actor, augustus_pierrot) and not orchestraLent(augustus) once {
    Says "'Lend my band,' says Augustus Pell, magnificently, 'to a circus, for an overture, to be played before the Household, in the masque that opposes mine?' He draws breath for an aria of refusal. You say, quietly, that you know about the Pierrot. Augustus stops. For a moment he is eight years old in a ruff on the stage of the Theatre Royal, with the house laughing. 'Grandmother,' he says. Then, slowly, he lets the breath go. 'Fourteen musicians,' he says, in a small ordinary voice. 'They are better than your three. Tell your Signor that if his serpent cannot play the low G, mine can.'".
    On discuss { Assert orchestraLent(augustus). Increase regard(fipps) by 2. }
  }

  // Lusk's Nell, and the seventh hook in the Keeper's Lodge.
  Relation jabezHeir(group).
  Rule nell_up_hill when nellTold(nell) and here(tober_r) and hour(clock) >= 8 and hour(clock) < 17 and not at(nell, keeper_lodge) and not nellSweeping(nell) { Assert at(nell, keeper_lodge). Assert nellSweeping(nell). }
  Rule nell_down_hill when nellSweeping(nell) and hour(clock) >= 17 { Retract nellSweeping(nell). Assert at(nell, aske_cottage_b). }
  Relation nellSweeping(group).
  Observe nell_and_jabez near nell when nellSweeping(nell) and at(nell, keeper_lodge) "Lusk's Nell is sitting on Jabez Orme's table with her legs swinging, being shown the Keepers' Book a page at a time, and she is not bored by any of it, and Jabez is so happy he has to keep stopping.".
  Topic jabez_nell with jabez "Ask Jabez whether Nell might take down the seventh broom, one day" when nellSweeping(nell) and knows(actor, seventh_hook) and not jabezHeir(jabez) once {
    Says "Jabez looks at the child on his table, who is reading the Book's margins aloud in a whisper and getting the long words wrong in the right way. 'She's not an Orme,' he says. Then: 'There's never been anything in the Book about that.' His voice is not steady. 'Her father goes round with the wagons. She'd see him every time they came up the hill.' He looks at the seventh hook on the wall. 'I'll ask her gran,' he says. 'Her gran's always right. It's a terrible thing in a woman.'".
    On discuss { Assert jabezHeir(jabez). Increase regard(lusk) by 2. }
  }

  // The hob of the kitchen comes home.
  Relation hobKnowsRest(group). Relation hobAtRest(group).
  Topic hob_kitchen with ninepence "Ask Ninepence whether he knows the King's Rest" when (hobJoined(ninepence) or hobAtInn(ninepence)) and knows(actor, inventory_known) once {
    Says "Ninepence does not answer. He is looking up the hill. 'A Hobbe of the Kitchenne,' he says at last. 'In Service. Not to be Thanked.' He says it as if reading it, though he cannot have seen the Book. 'I swept that kitchen for the old kings. Turned the spits, scoured the coppers, in the dark, for two hundred years. And then they went away one spring and nobody came back, and there was nobody to cook for.' He rubs his long hands. 'A hob without a kitchen is a sad thing. I walked down the hill to the fulling-mill because they were working in the night there, and that's near enough to a kitchen if you're lonely.' He looks at you. 'Is there anybody to cook for, up there? Now?'".
    On discuss { Assert hobKnowsRest(ninepence). }
  }
  Topic jabez_hob with jabez "Tell Jabez that the Hob of the Kitchen is Ninepence, and that he remembers the Rest" when hobKnowsRest(ninepence) once {
    Says "Jabez sits down very suddenly on his own step. 'The Hobbe,' he says. 'Gone, nobody to cook for. My first father wrote that.' He looks at the ruined kitchen range through the broken wall of the lodge. 'I cook,' he says. 'Porridge. Every morning for seventy years. Very badly.' He stands up. 'Tell him there's porridge. Tell him it's very bad. He'll like that; a hob likes something to put right.'".
    On discuss { Assert hobInvited(ninepence). }
  }
  Relation hobInvited(group).

  // Hench at court: the Dowager knows him.
  Relation henchOffered(group). Relation henchStays(group). Relation henchGoes(group).

  // ── Cordelia: inside the company, or across the court ──────────────────────────────────────────────────────
  Relation lionLent(group). Relation lionHere(group).
  Species old_lion "an old lion" like lion tame described "A lion with a grey muzzle, a torn ear and a mane gone thin and pale, nearly blind, who moves like a great tired dog and lies down wherever he stops.".
  Person neb "Nebuchadnezzar" at tober_a {
    Role "an old blind lion". Species old_lion. Peaceable. Pronouns he.
    Greets "The old lion lifts his head toward your voice, and breathes in your smell for a long time, and lays his head down again, satisfied, as if you would do.".
  }
  Initially Assert offstage(neb).
  // United, he is the company's; Billie keeps him.
  Rule lion_ours when merged(wapshotts) and offstage(neb) and pitched(wapshotts) {
    Retract offstage(neb). Assert exhibit(neb). Assert travels(neb). Assert post(neb, rk_beasts). Assert lionHere(neb). Increase draw(wapshotts) by 3. Increase exhibits(wapshotts) by 1. }
  Observe neb_shown near neb when exhibit(neb) "In a deep straw pen at the back of the menagerie, the old lion Nebuchadnezzar lies with his chin on his paws. A board says only: NEBUCHADNEZZAR. HE WAS AT DUNMERE. Somebody, at some point, has added underneath in chalk: SO WAS I.".
  Observe colonel_lion near neb when exhibit(neb) and merged(wapshotts) and (hour(clock) >= 22 or hour(clock) < 5) "In the dark of the menagerie, by the old lion's pen, somebody is sitting on an upturned bucket in a crimson coat, talking to the lion in a low voice about Dunmere. After a while somebody else comes in with a lantern and a cane, and stands, and then, after a longer while, sits on the straw beside the bucket.".
  // The two companies as one: the white horses in the ring, the wages paid, every expense argued.
  Rule horses_told near ringpost when showOn(wapshotts) and act(wapshotts) == 2 and merged(wapshotts) and not horsesToldTonight(wapshotts)
    says "After Bucephalus, the Hippodrome's twelve white horses come in at a canter in a wheel, nose to tail, with no riders, turning together like a thing with one mind; and Bucephalus, at the curtain, watches them with the bleak tolerance of an old general watching recruits." {
    Assert horsesToldTonight(wapshotts). Increase quality(wapshotts) by 2. Increase house(wapshotts) by 2. }
  Rule horses_reset when horsesToldTonight(wapshotts) and not showOn(wapshotts) { Retract horsesToldTonight(wapshotts). }
  Relation horsesToldTonight(concern).
  Rule cordelia_pays when merged(wapshotts) and onRoad(wapshotts) and wagesReckoned(wapshotts) and arrears(wapshotts) >= 1 and not cordeliaPaid(wapshotts) {
    Assert cordeliaPaid(wapshotts). Set arrears(wapshotts) to 0. }
  Rule cordelia_paid_reset when cordeliaPaid(wapshotts) and pitched(wapshotts) { Retract cordeliaPaid(wapshotts). }
  Relation cordeliaPaid(concern).
  Topic sallow_inside with sallow "Ask Madame Sallow how she finds being half of the Colonel's circus" when merged(wapshotts) once {
    Says "Madame Sallow is going through the Colonel's receipts with a red pencil, and there are a great many red marks. 'Exhausting,' she says. 'He ordered a gilded coach for the Revels, and I cancelled it, and he did not speak to me for a day, and then he brought me a cup of tea and asked whether the horses would like to see the King's Rest.' She draws a line through something. 'The wages are paid on the day now. Your Lusk shook my hand. Nobody in the Hippodrome ever shook my hand; they were paid on the day too, and thought nothing of it.' She looks up. 'I had forgotten that a circus could be a family. Mine was a business. His is a family that cannot add.' She makes another red mark. 'I am going to teach it.'".
  }
  Topic wap_partner with wapshott "Ask the Colonel how he likes having a partner again" when merged(wapshotts) once {
    Says "The Colonel lowers his voice to a rumble, which for him is a whisper. 'Terrible,' he says. 'Wonderful. She has taken away my pen. She reads my letters before I send them. She has made me pay Hench for the gold braid, with interest.' He looks across at the ticket wagon, where a dove-grey back is bent over the ledger beside a green bonnet, the two of them conferring like generals. 'Ada has a friend,' he says, quite softly. 'I never thought of that. Ada never had a friend in this circus who could add.'".
  }
  // Rivals: she brings her white horses, and the lion, to the Revels in her own name.
  Topic sallow_rival with sallow "Ask Madame Sallow why she is claiming the Revels too" when not merged(wapshotts) and knows(actor, rivals_known) and here(tober_r) once {
    Says "'Because I said I would beat him fairly,' says Madame Sallow, 'and I keep my word. And because the Household should have someone who can add.' She looks across the Long Court at the striped big top. 'And because if I do not, he will be given a royal ruin and a menagerie and a warrant, and he will spend the Treasury's wagon in a fortnight, and somebody will have to watch.' A pause. 'I would rather it were me watching than reading about it.'".
  }
  Topic sallow_lend_lion with sallow "Ask Madame Sallow to let Nebuchadnezzar walk in Wapshott's procession of the Inventory" when not merged(wapshotts) and knows(actor, inventory_known) and here(tober_r) and not lionLent(neb) once {
    Says "Madame Sallow considers it. 'He is in the Inventory,' she says. 'Nebuchadnezzar the third. I bought him from the last of the Dunmere menageries, and they had him from the Rest.' She looks at her own blue-and-gold wagons. 'If he walks for you he does not walk for me.' Then: 'He is very old, and very slow. He would walk in anyone's procession who walked slowly enough.' She looks at you. 'And Florian has never once asked after him.'".
    On discuss { Assert lionAsked(neb). }
  }
  Relation lionAsked(group).
  Topic sallow_lion_yes with sallow "Say that the Colonel sits up at night talking about Dunmere to anyone who will listen, and asked after the lion" answering sallow_lend_lion when lionAsked(neb) and not lionLent(neb) and knows(actor, lion_well) {
    Says "Madame Sallow is quiet for a while. 'Did he,' she says. Then: 'Very well. Nebuchadnezzar walks for Wapshott's. Last, and slowly, and Billie walks beside him, not Florian.' She makes a note. 'I shall lose the Revels by it. I find I do not much mind.'".
    On discuss { Assert lionLent(neb). }
  }
  Topic sallow_lion_no with sallow "Say that the lion should walk for whoever owns him" answering sallow_lend_lion when lionAsked(neb) and not lionLent(neb) {
    Says "'Yes,' says Madame Sallow. 'That is what I think too.' She seems, for a moment, disappointed in you both.".
  }
}

data/goings-on/circus/marl.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── The Marl Wake, and the pit ──────────────────────────────────────────────────────────────────────────────
  // The third town's diggers keep their Wake on the second day of the circus's stand there in the Revels round: a
  // Marl Queen, a greasy pole, the pit opened for the year. The pit is flooded; a great pike lives in it; under the
  // water, where the King's diggers stopped three hundred years ago, there is more of whatever the Leg came from.
  Relation wakeOn(concern). Relation wakeDone(concern).
  Rule wake_starts when letterCome(wapshotts) and current(wapshotts, tober_c) and pitched(wapshotts) and day(clock) == arrivedDay(wapshotts) + 1 and hour(clock) >= 13
    and not wakeDone(wapshotts) and not wakeOn(wapshotts) {
    Assert wakeOn(wapshotts). }
  Rule wake_ends when wakeOn(wapshotts) and hour(clock) >= 19 { Retract wakeOn(wapshotts). Assert wakeDone(wapshotts). }
  Observe wake_green at green_c when wakeOn(wapshotts) "It is the Marl Wake. {green_c} is full of diggers in clean smocks with marl still in the creases of their hands, and their wives, and a fiddler, and a pole thirty feet high greased from top to bottom with a leg of mutton tied at the summit. Down the street comes the Marl Queen in a crown of white clay and cowslips, on a cart drawn by four diggers, throwing sugared almonds at the priest's door. Wapshott's band has been asked to play her in, and is playing something it does not know with tremendous confidence.".
  Person tull "Sim Tull" at green_c {
    Role "the foreman of the marl-diggers". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "A broad man in a smock with forearms the colour of the pit and a pot of ale in each hand gives you one of the pots before you have asked. 'Sim Tull,' he says. 'Foreman of the marl, when there's marl to dig.' He drinks. 'Come to the Marl Wake, when the circus is next here: there's a greasy pole with a leg of mutton on top. Nobody's had the mutton in four years. My granfer had it in his day; he never stops telling us.'".
  }
  Person granfer "Granfer Tull" at green_c {
    Role "the oldest digger of the town". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Greets "A tiny, bald, furious old man in a smock older than you are, sitting on a bench with his stick between his knees, looks you up and down. 'In my day,' he says, 'we had the mutton every year. Every year. Now they slide down that pole like butter off a knife.' He spits. 'And some thief of a dealer had my best bantam off me at Michaelmas for a shilling and a lie.'".
  }
  Topic granfer_roderick with granfer "Tell Granfer Tull his bantam is in Wapshott's menagerie, as a cockerel of uncommon malice" when exhibit(roderick) and basiliskHonest(wapshotts) once {
    Says "Granfer Tull gets up. He walks up the field to the menagerie on his stick, very fast for a man of his age, and you follow; and in front of the pen where Sir Roderick stands under his board, he stops, and reads it, his lips moving. WHO BELIEVES HIMSELF A BASILISK. DO NOT CONTRADICT HIM. Sir Roderick sees him and flies at the wire. 'That's him,' says Granfer Tull. 'That's him. Took the eye out of a fox at three weeks old.' He wipes his nose on his sleeve. 'Uncommon malice. Well. They've got him right.' He goes away down the field quite happy, and tells the whole Wake.".
    On discuss { Increase standing(tober_c) by 1. }
  }
  Topic granfer_basilisk with granfer "Tell Granfer Tull his bantam is in Wapshott's menagerie, billed as a basilisk" when exhibit(roderick) and basiliskBilled(wapshotts) once {
    Says "Granfer Tull goes purple. He walks up the field to the menagerie as fast as his stick will go, and tears down the black curtain over the pen, and holds up Sir Roderick by the legs for the whole Wake to see. 'BASILISK!' he roars. 'That's my bantam! He's a Tull bird! Dyed!' The diggers, who have all paid a penny to view the basilisk in the glass provided, are not pleased. The Colonel, coming up at a run, is pleased even less.".
    On discuss { Decrease standing(tober_c) by 2 or to nothing. Retract basiliskBilled(wapshotts). Assert basiliskHonest(wapshotts). }
  }
  Relation poleTried(group). Relation muttonWon(group).
  Action greasy_pole(actor: group, site: place) "Climb the greasy pole for the leg of mutton" {
    Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and wakeOn(wapshotts) and at(actor, green_c) and not poleTried(actor).
    Resolve check(actor, tumbling, dc_hard).
    On success { Assert poleTried(actor). Assert muttonWon(actor). Increase standing(tober_c) by 2. Increase larder(wapshotts) by 1. Increase renown(actor) by 1. }
    On failure { Assert poleTried(actor). }
    Result "Nobody climbs a greasy pole. You learn this at once. What you can do, if you have learned to fall, is fall upward: a little way, and slide, and catch, and fall a little further up, like a clown going up a ladder that leans against nothing. The diggers stop laughing about halfway, and start shouting. At the top you untie the mutton with your teeth. Granfer Tull, on his bench, stands up and takes off his hat.".
    Otherwise "You go up the pole like a man up a waterfall, and come down it the same way, all of it, into the arms of the Marl Queen, who is very kind about it.".
  }

  Topic granfer_mutton with granfer "Tell Granfer Tull you had the mutton off the pole" when muttonWon(actor) once {
    Says "Granfer Tull looks at you for a long time from under his eyebrows. 'Fell up it,' he says. 'I saw. Fell up it like a cat up a curtain.' He spits, with approval. 'Nobody's done that since me. And I did it sober, which you did, which is a disgrace to the Wake.' He gives you his hand, which is like a root. 'Come and have your dinner with the Tulls. There's more mutton.'".
    On discuss { Increase larder(wapshotts) by 1. Increase standing(tober_c) by 1. }
  }

  // ── The pit ─────────────────────────────────────────────────────────────────────────────────────────────────
  Entity marl_heard: fact "The marl-pit outside {town_c}, where the great bone came from, has been flooded since spring; the diggers will not go down because of what lives in the water.".
  Initially Assert leadsTo(marl_heard, marl_lip).
  Topic tull_pit with tull "Ask Sim Tull about the marl-pit, where the bone came from" when true once {
    Says "Sim Tull's face changes. 'Flooded,' he says. 'The spring we dug the Leg out, the bottom of the pit went through into a spring, and filled overnight. Forty feet of water.' He lowers his voice. 'And there's a pike in it. Came up the culvert from the river as a jack and grew on whatever it could find. Took the Pargeter's dog in May, the whole dog. Nobody's been down since.' He drinks. 'There's an old sluice at the foot, on the river side. My granfer says the King's diggers put it in. Rusted solid. If you could get it open, the pit would drain into the river in a night, and the pike with it, or not.' He grins. 'Or you could just ask the pike nicely.'".
    On discuss { Assert knows(actor, marl_heard). Assert knows(actor, sluice_known). }
  }
  Entity sluice_known: fact "An old sluice at the foot of the marl-pit, on the river side, would drain it in a night if it could be opened; it is rusted solid.".
  Place marl_lip "the lip of the marl-pit" is room within town_c at 4, 4.
  Place pit_water "the flooded bottom of the marl-pit" is room within town_c at 4, 5.
  Passage marl_lane "the diggers' lane to the marl-pit" is path between green_c and marl_lip taking 25 minutes hidden until marl_heard.
  Passage pit_ladder "the diggers' ladder" is path between marl_lip and pit_water taking 5 minutes.
  Observe lip_scene at marl_lip when not pitDrained(wapshotts) "A great raw bowl cut in the hillside, terraced in grey-white steps by a hundred years of digging, and at the bottom, forty feet down, black water, perfectly still. A ladder goes down into it and does not come out. On the far side, at the foot, a stone sluice-gate with an iron wheel, red with rust.".
  Observe lip_drained at marl_lip when pitDrained(wapshotts) "The marl-pit is empty: a great grey bowl, its floor a field of wet white clay pocked with puddles, the old sluice open at its foot and still running a little. Down on the floor, near the middle, something stands up out of the clay like the rib of a boat.".
  Observe water_scene at pit_water when not pitDrained(wapshotts) "Black water to the waist, cold enough to stop the breath, on a floor of slick clay that tilts toward the middle. The far side is very far. Something moves under the surface out there, a long shadow, and the water bulges and settles.".
  Observe floor_scene at pit_water when pitDrained(wapshotts) "The floor of the pit: wet white clay to the ankle, and the smell of a river bed. Near the middle, where the King's diggers must have stopped, a squared stone stands upright in the clay with letters cut in it, and beside it something stands up out of the marl that is not stone: dark, curved, ribbed, taller than a man.".
  Relation pitDrained(concern). Relation sluiceOpened(concern). Measure sluiceAt(concern). Relation triedSluice(group).
  Species marl_pike "a great pike" like great_pike temperament territorial described "A pike as long as a boat, olive and gold, its jaw undershot, its eye like a coin set in it upside down. It is very old, and very hungry, and it has the patience of a thing that has been waiting in the dark for the next dog.".
  Person pike "the pike in the marl-pit" at pit_water {
    Role "a great pike, as long as a boat". Species marl_pike. Pronouns it.
    Warns "Out in the black water the long shadow turns, and comes toward you, unhurried, a wake running ahead of it like an arrowhead, and stops a few yards off; and you see, just under the surface, an eye, gold, watching you, and a mouth that could take a dog. It waits. It has always been good at waiting.".
    Comes "The pike comes out of the black water at you with its mouth open.".
  }
  Rule pike_stranded when pitDrained(wapshotts) and not dead(pike) and not pikeStranded(pike) { Assert pikeStranded(pike). Assert peaceable(pike). Assert tolerates(pike, party). }
  Relation pikeStranded(group). Relation pikeSaved(group).
  Observe pike_mud near pike when pikeStranded(pike) and not pikeSaved(pike) "In the last of the water, in a hollow of the clay, the great pike lies on its side, gasping, its gold eye rolling up at the sky. It is enormous. It is also, very obviously, dying.".
  Action open_sluice(actor: group, site: place) "Put your weight to the rusted wheel of the old sluice" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, marl_lip) and knows(actor, sluice_known) and not sluiceOpened(wapshotts) and not triedSluice(actor).
    Resolve check(actor, brawn, dc_hard).
    On success { Assert sluiceOpened(wapshotts). Set sluiceAt(wapshotts) to watch(clock). }
    On failure { Assert triedSluice(actor). }
    Result "You get round the outside of the pit to the sluice and set your back to the iron wheel and heave; and heave; and then, with a shriek like a gate the size of a church, it turns a quarter. Water spouts out of the foot of the gate into the river, brown and roaring. Slowly, over the night, the black water in the pit will go down.".
    Otherwise "The wheel will not move. You might as well heave at the hill.".
  }
  Topic honoria_sluice with honoria "Ask Honoria to come and turn the sluice-wheel at the marl-pit" when knows(actor, sluice_known) and not sluiceOpened(wapshotts) and here(tober_c) once {
    Says "Honoria comes, in her apron, with her sleeves rolled up, and looks at the wheel, and spits on her hands, and turns it. It shrieks, and gives, and turns, and the river roars at the foot of the gate. She dusts her palms. 'There,' she says. 'Is that all? I left a pie.'".
    On discuss { Assert sluiceOpened(wapshotts). Set sluiceAt(wapshotts) to watch(clock). }
  }
  Rule pit_drains when sluiceOpened(wapshotts) and watch(clock) >= sluiceAt(wapshotts) + 30 and not pitDrained(wapshotts) { Assert pitDrained(wapshotts). }
  Action save_pike(actor: group, site: place) "Get the great pike into a canvas sling with Billie and carry it down to the river" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(pike, site) and pikeStranded(pike) and not pikeSaved(pike) and not dead(pike) and regard(billie) >= 2.
    On success { Assert pikeSaved(pike). Assert offstage(pike). Increase regard(billie) by 2. }
    Result "Billie comes down the ladder with a length of canvas side-wall and two of Lusk's lads, and between the four of you, up to the knees in clay, you get the pike into it, all of it, thrashing, and carry it up the terraces like a coffin with a temper and down to the river below the sluice; and let it go. It lies in the shallows a long moment, gold eye looking at you. Then it is a long shadow going away downstream, unhurried. Billie wipes her face with her sleeve, which spreads the clay about. 'Well,' she says. 'Somebody had to.'".
  }
  Action wade_by_night(actor: group, site: place) "Wade out across the black water in the dark, while the pike is far side" {
    Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pit_water) and dark() and not pitDrained(wapshotts) and not knows(actor, worm_stone) and not dead(pike).
    Resolve check(actor, stealth, dc_hard).
    On success { Assert knows(actor, worm_stone). }
    Result "You go out into the black water up to the chest, feeling with your feet on the tilted clay, without a sound, while far off on the other side something turns, and turns, and does not come. In the middle your foot strikes stone, squared, upright; your hands find letters cut in it; you read them like a blind man. Then something else, beside the stone, under the water: a great curve, ribbed, colder than stone. You get out of the pit without remembering how.".
  }
  Entity worm_stone: fact "On the floor of the marl-pit stands a squared stone cut with the words HERE THE KINGS DIGGERS STOPT. NOT DEAD ENOUGH., and beside it, standing out of the marl, a great dark ribbed curve taller than a man.".
  Observe stone_read at pit_water when pitDrained(wapshotts) and not knows(party, worm_stone) "On the upright stone, cut deep and carefully, as if by someone who meant it to be read in three hundred years: HERE THE KINGS DIGGERS STOPT. NOT DEAD ENOUGH. And beside it, standing out of the clay at an angle, the thing like a boat's rib: a single claw, black and glossy, curved like a sickle and as tall as you, still sharp along its inner edge." teaches worm_stone.
  Kind marl_claw_kind "the great claw from the marl-pit" is gear worth 30 weighing 6
    described "A claw as long as a scythe-blade, black and glossy as if lacquered, curved like a sickle, ribbed along its back, and still, after however long it has been in the marl, sharp along its inner edge. It is heavier than it looks, and colder.".
  Item great_claw "the great claw from the marl-pit" is marl_claw_kind at pit_water hidden until worm_stone.
  Relation clawShown(group). Relation clawToShrine(group). Relation clawReburied(group). Relation clawToColonel(group).
  Topic fenwick_claw with fenwick "Show Sir Gervase the great claw from the marl-pit" when holding(actor, marl_claw_kind) and not clawShown(fenwick) once {
    Says "Sir Gervase does not say anything at all. He takes off his hat. He takes the claw in both hands as a priest takes the cup, and turns it in the light, and runs his thumb, very carefully, along the inner edge, and draws blood, and does not notice. 'It is not a bird,' he says at last, quietly. 'It is not a bear. It is not a lizard, though it is very like a lizard, if a lizard were a cathedral.' He gives it back to you. His hands are shaking. 'The rest of it is under that field,' he says. 'Isn't it. That is what the stone means.' He laughs, quite wildly, a boy's laugh. 'Not dead enough!'".
    On discuss { Assert clawShown(fenwick). Assert shownFenwick(party). Increase regard(fenwick) by 2. }
  }
  Topic wap_claw with wapshott "Show the Colonel the great claw from the marl-pit" when holding(actor, marl_claw_kind) and not clawToColonel(wapshott) once {
    Says "The Colonel holds the claw up to the sky, at arm's length, with both hands, and his moustache begins to tremble. 'What,' he says, 'is this OFF?' You tell him about the stone. NOT DEAD ENOUGH. A light comes into the Colonel's eye that Ada, from the ticket wagon, sees from forty feet off. 'Bigger than an elephant,' he whispers. 'Under a field. And the Household of the Progress has a warrant for beasts.' He hands the claw back to you as if it were a crown. 'Keep it safe,' he says. 'Show it at the Revels. And say nothing to Sir Gervase. Say nothing to anybody. Say nothing to me; I shall only get ideas.' He has already got them.".
    On discuss { Assert clawToColonel(wapshott). Assert clawGiven(party). }
  }
  Topic priest_c_claw with priest_c "Take the great claw to {priest_c}, to lie with the Leg under the altar" when holding(actor, marl_claw_kind) and not clawToShrine(priest_c) once {
    Says "{priest_c} lays the claw on the altar cloth beside the Leg, and stands back. Together they make a shape the mind does not want to finish. {priest_c} says nothing for some time. Then: 'I shall say the prayers over two now,' {priest_c} says. 'Still for whom, I don't know. It seems a better place for them than a cabinet.' {priest_c} lays the cloth over both.".
    On discuss { Assert clawToShrine(priest_c). Assert clawGiven(party). Spend marl_claw_kind from actor. }
  }
  Action rebury_claw(actor: group, site: place) "Put the claw back in the marl beside the stone, where the King's diggers left it" {
    Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pit_water) and holding(actor, marl_claw_kind) and not clawReburied(actor).
    On success { Assert clawReburied(actor). Assert clawGiven(party). Spend marl_claw_kind from actor. Increase regard(jabez) by 1. }
    Result "You put it back where you found it, point down, in the cold clay beside the stone, and press the marl round it with your hands. It is a strange feeling, burying a thing that was never alive in your time, as if you were tucking it in. Up on the lip of the pit, when you climb out, the wind has got up, and for a moment you could swear the ground under your boots was warm.".
  }
  Topic priest_c_leg with priest_c "Ask {priest_c} to lend the great bone to the Revels at the King's Rest" when knows(actor, bone_seen) and knows(actor, inventory_known) and not legLent(priest_c) once {
    Says "{priest_c} hesitates. 'It has been in the shrine a year,' {priest_c} says. 'The children bring it flowers.' Then: 'The Book says it came from the Rest before it went into the marl?' You explain: from the marl to the Rest, three hundred years ago, and back into the marl. {priest_c} considers this. 'Then it is going home for a night. It may go. On a cart, with a cloth over it, and back the next day. And the children may walk beside it.'".
    On discuss { Assert legLent(priest_c). }
  }
  Relation legLent(group).
}

data/goings-on/circus/menagerie.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── Wapshott's Cabinet of Living Wonders ────────────────────────────────────────────────────────────────────
  // Begun when the Colonel resolves on it; kept by Billie Ostrander, in an old canvas pitched on the front. What it
  // holds goes round with the wagons; how well it is kept (its welfare) decides whether it draws or smells, and
  // whether what is in it stays in it. A beast that can talk is asked, not taken.
  Relation menagerieOpen(concern). Measure draw(concern). Measure welfare(concern). Relation exhibit(group).
  Measure exhibits(concern). Measure keptDay(group).
  Initially Set welfare(wapshotts) to 3.
  Topic wap_menagerie with wapshott "Ask the Colonel about his menagerie" when knows(actor, wapshott_dreams) and not menagerieOpen(wapshotts) once {
    Says "The Colonel seizes your arm. 'WAPSHOTT'S CABINET OF LIVING WONDERS,' he says, so loudly that Bucephalus lays his ears back. 'A penny extra at the flap. Beasts of legend! Prodigies of nature! Things that Cordelia Sallow, with her camel, has never DREAMED of!' He lowers his voice. 'I have already acquired the first. A basilisk. In a crate. Very reasonable; a man in {town_b} let me have it for my watch.' He produces a paper from his coat. 'And here is my list. I want them all. I cannot go myself; a proprietor is needed at the helm. But a person of resource, with an honest face, who knew the country.' He presses the list into your hands. 'Billie will keep them. She does not know it yet.'".
    On discuss { Assert menagerieOpen(wapshotts). Assert knows(actor, wonders_list). Give wonders_paper to actor. Assert knows(actor, list_given). Assert post(billie, rk_beasts). }
  }
  Kind wonders_list_kind "the Colonel's List of Wonders Wanted" is gear worth 0 weighing 0
    described "A playbill with a list written on the back of it in the Colonel's huge looping hand: WONDERS WANTED. 1. The Basilisk (in hand; in crate; do not open). 2. The Glimmer-Fox, said to walk the water-meadows below the third town by night, burning cold. 3. A Hob, a genuine one, said to haunt the old fulling-mill at the second town, which is to be sold. 4. Some great Beast that is eating the bees in the orchards of the fair town, description various, all large. 5. A Tortoise of Antiquity, at the carrier's yard in the third town, to be had cheap, as nobody can move it. 6. A SERPENT, for Fipps, who will not stop asking. Under it, smaller: Billie says no cages for anything that can talk. Noted.".
  Item wonders_paper "the Colonel's List of Wonders Wanted" is wonders_list_kind at tober_a hidden until list_given.
  Discovery list_given "The Colonel has given you his List of Wonders Wanted.".
  Action read_list(actor: group, site: place) "Read the Colonel's List of Wonders Wanted" {
    Time 1 minute.
    Requires able(actor) and at(actor, site) and holding(actor, wonders_list_kind).
    Result "On the back of a playbill, in the Colonel's huge looping hand: WONDERS WANTED. 1. The Basilisk (in hand; in crate; do not open). 2. The Glimmer-Fox, said to walk the water-meadows below {town_c} by night, burning cold. 3. A Hob, a genuine one, said to haunt the old fulling-mill at {town_b}, which is to be sold. 4. Some great Beast that is eating the bees in the orchards of {town_a}, description various, all large. 5. A Tortoise of Antiquity, at the carrier's yard in {town_c}, to be had cheap, as nobody can move it. 6. A SERPENT, for Fipps, who will not stop asking. Underneath, smaller, in another hand: Billie says no cages for anything that can talk. Noted.".
  }
  Entity wonders_list: fact "Colonel Wapshott wants for his menagerie: the basilisk in its crate, a glimmer-fox from the water-meadows of {town_c}, the hob of the mill at {town_b}, whatever is eating the bees in {town_a}'s orchards, a giant tortoise at the carrier's yard in {town_c}, and a serpent for Fipps.".
  Objective wonders when knows(party, wonders_list) and menagerieOpen(wapshotts) and exhibits(wapshotts) < 3 "Find the Colonel his Wonders, if you choose: a basilisk in a crate, a glimmer-fox, a hob, a beast in the orchards, a tortoise, a serpent.".
  Topic billie_keeper with billie "Ask Billie whether she will keep the Colonel's menagerie" when menagerieOpen(wapshotts) once {
    Says "'He told you before he told me,' says Billie. 'That's the Colonel.' She is quiet. 'I'll keep it. On my terms. Clean straw daily. Fed before the people are. Room to turn round. Anything that pines goes back where it came from, and anything that can talk is asked, not caught, or I walk.' She looks at you. 'You'll be the one fetching them. So they're your terms too.'".
    On discuss { Increase regard(billie) by 1. Assert knows(actor, billie_terms). }
  }
  Entity billie_terms: fact "Billie Ostrander keeps the menagerie on her terms: clean straw daily, fed before the people, room to turn round, anything that pines goes home, and anything that can talk is asked, not caught.".
  Observe beasts_scene near beastpost when at(beastpost, ?r) and menagerieOpen(wapshotts) "The menagerie is an old canvas tent, patched, smelling of straw and something wild. A painted board inside the flap says WAPSHOTT'S CABINET OF LIVING WONDERS, and under it, in Billie's square hand, DO NOT POKE.".
  Thing beastpost "the menagerie" at tober_a is scenery {
    State kept "Billie Ostrander's straw is clean and fresh.".
    State neglected "The straw is foul, the water-pails empty, and the tent stinks.".
    State packed "The menagerie travels in its own wagons behind the cookhouse, the cages lashed under canvas, Billie walking alongside talking to them.".
  }
  Initially Assert travels(beastpost). Initially Assert post(beastpost, rk_beasts).
  Rule beasts_kept when pitched(wapshotts) and welfare(wapshotts) >= 2 and state(beastpost, neglected) { Assert state(beastpost, kept). }
  Rule beasts_neglected when pitched(wapshotts) and welfare(wapshotts) < 2 and state(beastpost, kept) { Assert state(beastpost, neglected). }
  // Each morning: feed eaten, welfare kept by Billie if there is feed, falling if there is none.
  Rule beasts_fed when menagerieOpen(wapshotts) and exhibits(wapshotts) >= 1 and hour(clock) == 7 and keptDay(billie) < day(clock) and feed(wapshotts) >= 1 {
    Set keptDay(billie) to day(clock). Decrease feed(wapshotts) by 1. Increase welfare(wapshotts) by 1. }
  Rule beasts_hungry when menagerieOpen(wapshotts) and exhibits(wapshotts) >= 1 and hour(clock) == 7 and keptDay(billie) < day(clock) and feed(wapshotts) < 1 {
    Set keptDay(billie) to day(clock). Decrease welfare(wapshotts) by 1 or to nothing. }
  Rule welfare_cap when welfare(wapshotts) > 4 { Set welfare(wapshotts) to 4. }
  Rule feed_bought when menagerieOpen(wapshotts) and exhibits(wapshotts) >= 1 and feed(wapshotts) < 1 and strongbox(wapshotts) >= 8 and hour(clock) == 8 and not feedBoughtToday(wapshotts) {
    Decrease strongbox(wapshotts) by 2. Increase feed(wapshotts) by 1. Assert feedBoughtToday(wapshotts). }
  Rule feed_reset when feedBoughtToday(wapshotts) and hour(clock) == 9 { Retract feedBoughtToday(wapshotts). }
  Relation feedBoughtToday(concern).
  Action muck_out(actor: group, site: place) "Help Billie muck out and feed the menagerie" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(beastpost, site) and exhibits(wapshotts) >= 1 and keptDay(actor) < day(clock).
    On success { Set keptDay(actor) to day(clock). Increase welfare(wapshotts) by 1. Increase regard(billie) by 1. }
    Result "An hour with a fork and a barrow and Billie, who says nothing while you work and then, at the end, hands you a mug of tea with five sugars in it, because that is how she was given it at your age, on a drove road in the rain.".
  }
  Action buy_feed(actor: group, site: place) "Buy two days' feed for the menagerie from Billie's dealer, three coin" {
    Speaker billie. Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(billie, site) and menagerieOpen(wapshotts) and quantity(actor, gold) >= 3 and feed(wapshotts) < 6.
    On success { Decrease quantity(actor, gold) by 3. Increase feed(wapshotts) by 2. Increase regard(billie) by 1. }
    Result "Billie writes a note to the corn-chandler and the knacker, and counts your coins into her coat. 'That's them right till Thursday,' she says.".
  }
  Topic billie_how with billie "Ask Billie how the menagerie does" when menagerieOpen(wapshotts) {
    Says "'Feed for {feed(wapshotts)} days,' says Billie. 'Kept {welfare(wapshotts)} out of four, by my reckoning: four is as good as a beast in a tent can be, and nought is a disgrace, and somebody will get out.' She looks at the cages. 'Every penny they bring at the flap, they've earned. I'd like them to see some of it.'".
  }
  // The menagerie's pull at the flap: by what it holds, kept or not.
  Rule draw_fed when menagerieOpen(wapshotts) and welfare(wapshotts) < 2 and draw(wapshotts) >= 2 and not drawHalved(wapshotts) {
    Assert drawHalved(wapshotts). Decrease draw(wapshotts) by 1. }
  Rule draw_restored when drawHalved(wapshotts) and welfare(wapshotts) >= 2 { Retract drawHalved(wapshotts). Increase draw(wapshotts) by 1. }
  Relation drawHalved(concern).
  Query beastIn(b: group) means exhibit(b) and pitched(wapshotts).

  // ── 1. The basilisk, in its crate ───────────────────────────────────────────────────────────────────────────
  Thing crate "a crate stencilled BASILISK" at tober_a {
    State sealed "A tall slatted crate stands in the straw, nailed shut and stencilled in red: BASILISK. LIVE. DO NOT LOOK INTO ITS EYES. THIS WAY UP. There is a knot-hole in one side, at about the height of an eye.".
    State empty "The lid is off the basilisk's crate.".
    Change prise "Prise the lid off the basilisk's crate" from sealed to empty.
    Tries looking, listening.
  }
  Initially Assert travels(crate). Initially Assert post(crate, rk_beasts).
  Entity sale_read: fact "The basilisk's bill of sale reads: ONE BASILISK, JUVENILE, OF THE COCKATRICE STRAIN, WITH CERTIFICATE. FED ON CORN. CROWS AT DAWN. Signed with an X, and a thumb-print in green dye.".
  Action read_sale(actor: group, site: place) "Read the dealer's bill of sale tacked to the basilisk's crate" {
    Time 1 minute.
    Requires able(actor) and at(actor, site) and at(crate, site) and not knows(actor, sale_read).
    On success { Assert knows(actor, sale_read). }
    Result "A greasy half-sheet, tacked to the slats: ONE BASILISK, JUVENILE, OF THE COCKATRICE STRAIN, WITH CERTIFICATE. FED ON CORN. CROWS AT DAWN. It is signed with an X, and a thumb-print in green dye. There is no certificate.".
  }
  Observe crate_heard near crate when tried(crate, listening) and state(crate, sealed) "Something in the crate shifts its weight, and scratches, and makes a low, indignant, gargling noise. If you are honest with yourself, it sounds like a hen with opinions." teaches crate_clucks.
  Entity crate_clucks: fact "Whatever is in the basilisk's crate scratches, and gargles, like a hen with opinions.".
  Observe crate_eye near crate when tried(crate, looking) and state(crate, sealed) and not knows(party, roderick_known) "You put your eye to the knot-hole, and remember the stencil, and take it away again sharply. Something inside moved toward the hole. Something with an eye. You did not look into it. Probably.".
  Topic hench_mirror with hench "Ask Hench whether he has a looking-glass you could borrow" when menagerieOpen(wapshotts) and state(crate, sealed) once {
    Says "'For the basilisk,' says Hench. 'Naturally. One does not look a basilisk in the eye; one looks at it in a glass, as Perseus did, or was it the other one.' He gives you a small round shaving mirror in a tortoiseshell back. 'Her Grace's late husband's. He used it to see if he was still there.'".
    On discuss { Assert lentMirror(actor). }
  }
  Relation lentMirror(group).
  Action mirror_crate(actor: group, site: place) "Hold Hench's glass to the knot-hole and look at the basilisk in it" {
    Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(crate, site) and state(crate, sealed) and lentMirror(actor) and not knows(actor, roderick_known).
    On success { Assert knows(actor, roderick_known). }
    Result "You angle the glass at the knot-hole, and look in it, and there, small and furious and upside down, is the basilisk: a bantam cockerel, about the size of a loaf, with a comb dyed bright green and a stare of absolute malice. It sees itself in the glass, and its comb goes up, and it hurls itself at the knot-hole with a scream of 'COCK-A-' that is cut off by the slats.".
  }
  Entity roderick_known: fact "The Colonel's basilisk is a bantam cockerel with a comb dyed green.".
  Rule crate_reasoned when knows(party, crate_clucks) and knows(party, sale_read) and not knows(party, roderick_known)
    says "Corn. Crows at dawn. A green thumb-print. A noise like a hen with opinions. You do not need to look into its eyes; you know what is in the crate." teaches roderick_known { }
  Species bantam "a bantam cockerel" like hen tame described "A small, upright cockerel with a comb dyed green and spurs like nails. He is afraid of nothing, including you.".
  Person roderick "Sir Roderick" at tober_a {
    Role "a bantam cockerel with a green comb, billed as a basilisk". Species bantam. Peaceable. Pronouns he.
    Greets "Sir Roderick looks at you with one eye, then the other, and then flies at your knees.".
  }
  Initially Assert away(roderick). Initially Assert offstage(roderick).
  Hazard spurred "A cockerel's spurs" means "Deal (1) physical damage to ally.".
  Rule crate_opened_blind near crate when state(crate, empty) and not knows(party, roderick_known) and not roderickOut(roderick)
    says "The lid comes off and something small and green and screaming comes out of the crate at your face, all spurs, and you fall over backwards into the straw with your arms over your eyes, quite sure you have been turned to stone; and when you dare to look, it is a bantam cockerel with a green comb, standing on your chest, crowing." teaches roderick_known {
    Assert strikes(spurred, party). Assert roderickOut(roderick). }
  Rule crate_opened near crate when state(crate, empty) and knows(party, roderick_known) and not roderickOut(roderick)
    says "You take the lid off, and the basilisk steps out of the crate into the straw: a bantam cockerel with a green comb, who looks round the menagerie as if he had bought it, and crows." {
    Assert roderickOut(roderick). }
  Relation roderickOut(group).
  Rule roderick_in when roderickOut(roderick) and away(roderick) { Retract away(roderick). Retract offstage(roderick). Assert travels(roderick). Assert post(roderick, rk_beasts). }
  Topic wap_basilisk with wapshott "Tell the Colonel his basilisk is a bantam cockerel with a dyed comb" when knows(actor, roderick_known) and not basiliskDecided(wapshotts) once {
    Says "The Colonel looks at you for a long time. Then he goes to the menagerie and looks at Sir Roderick, who looks back. 'He cost me my watch,' he says quietly. 'It was my father's watch.' A pause. Then, slowly, magnificently, the Colonel's chest begins to swell. 'But who,' he says, 'is to SAY, my friend, that a basilisk does not look, to the uninstructed eye, very like a cockerel? Who has SEEN one? I put it to you.' He spreads his hands. 'THE BASILISK. LIVING. A penny. It is not a lie. It is a theory.'".
    On discuss { Assert knows(actor, basilisk_theory). }
  }
  Entity basilisk_theory: fact "The Colonel means to show his bantam cockerel as THE BASILISK, LIVING, unless he is talked out of it.".
  Topic basilisk_honest with wapshott "Talk the Colonel into billing him honestly, as a cockerel of uncommon malice" answering wap_basilisk when not basiliskDecided(wapshotts) {
    Says "You argue it: that every child in {town_a} has seen a cockerel; that a cockerel who thinks he is a basilisk is funnier than a basilisk; that a cheat found out is a circus finished. The Colonel listens, pulling his moustache. 'A COCKEREL OF UNCOMMON MALICE,' he says at last, trying it. 'SIR RODERICK, WHO BELIEVES HIMSELF A BASILISK. Hm.' Sir Roderick flies at him. 'Hm!' says the Colonel, delighted. 'He does, doesn't he.' Billie, behind him, looks at you and nods.".
    On discuss { Assert basiliskDecided(wapshotts). Assert basiliskHonest(wapshotts). Assert exhibit(roderick). Increase draw(wapshotts) by 2. Increase exhibits(wapshotts) by 1. Increase regard(billie) by 1. }
  }
  Topic basilisk_billed with wapshott "Let the Colonel bill him as the Basilisk" answering wap_basilisk when not basiliskDecided(wapshotts) {
    Says "'Splendid,' says the Colonel. 'Splendid. Quirk will want new bills.' He goes off already composing them. Billie, at the menagerie flap, says nothing at all, very loudly.".
    On discuss { Assert basiliskDecided(wapshotts). Assert basiliskBilled(wapshotts). Assert exhibit(roderick). Increase draw(wapshotts) by 3. Increase exhibits(wapshotts) by 1. Decrease regard(billie) by 1 or to nothing. }
  }
  Relation basiliskDecided(concern). Relation basiliskHonest(concern). Relation basiliskBilled(concern).
  Observe roderick_shown near roderick when exhibit(roderick) and basiliskHonest(wapshotts) "Over Sir Roderick's pen a board says: SIR RODERICK. A COCKEREL OF UNCOMMON MALICE, WHO BELIEVES HIMSELF A BASILISK. DO NOT CONTRADICT HIM.".
  Observe roderick_billed near roderick when exhibit(roderick) and basiliskBilled(wapshotts) "Over Sir Roderick's pen a black curtain hangs on a rail, and a board says: THE BASILISK. LIVING. VIEW ONLY IN THE GLASS PROVIDED. A mirror is chained to the pole.".

  // ── 2. The glimmer-fox of the water-meadows ─────────────────────────────────────────────────────────────────
  Place meadow_c "the water-meadows below the town" is room within town_c at 4, 3.
  Passage meadow_path_c "the path down to the water-meadows" is path between tober_c and meadow_c taking 20 minutes.
  Observe meadow_scene at meadow_c when true "Wet meadows in a loop of slow water, the grass long and silver, alders along the bank, and a line of pollard willows like men with their hair standing up.".
  Observe meadow_night at meadow_c when dark() "In the dark the meadow is all sound: water, a moorhen, the long grass hissing.".
  Discovery fox_trail "A line of frost-ferns crosses the meadow grass, in the middle of summer, from the alders to the willows: the glimmer-fox's road." {
    Found by searching meadow_c with woodcraft "Low in the long grass, where nobody would see it who was not looking for it, there is frost: a line of frost-ferns on the blades, like the breath on a window, running from the alders to the willows. In the middle of summer. It melts as you look at it.".
  }
  Topic keeper_c_fox with keeper_c "Ask {keeper_c} about lights in the water-meadows" when knows(actor, wonders_list) once {
    Says "'The glimmer,' says {keeper_c}. 'You'll see it from the bridge on a dark night, going along low by the willows, a cold sort of light, blue-white, like a candle in a church. The old folk call it the frost-fox. Children go looking for it and come back with chilblains in August.' {keeper_c} shrugs. 'It's never hurt anybody. It eats moths. Leave it be, I'd say. But nobody asks me.' A glance at the door. 'If you must: where it goes the grass whitens, even in August. A line of frost from the alders to the willows. Lie by that, after dark, and keep still.'".
    On discuss { Assert knows(actor, fox_trail). }
  }
  Species glimmer_fox "a glimmer-fox" like fox tame described "A small, slender fox, its coat pale as ash, whose brush glows with a cold blue-white light, like moonlight on frost. Where it steps the grass whitens.".
  Person glimmer "the glimmer-fox" at meadow_c {
    Role "a fox whose brush burns cold". Species glimmer_fox. Peaceable. Pronouns she.
  }
  Initially Assert offstage(glimmer).
  Relation foxSeen(group). Relation foxCaught(group). Relation foxPainted(concern). Relation foxFreed(group).
  Action wait_fox(actor: group, site: place) "Lie in the reeds by the frost-line, and wait for the glimmer-fox" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, meadow_c) and dark() and knows(actor, fox_trail) and not foxSeen(actor) and not exhibit(glimmer).
    Resolve check(actor, stealth, dc_fair).
    On success { Assert foxSeen(actor). Retract offstage(glimmer). Assert at(glimmer, meadow_c). }
    Result "You lie in the wet reeds for an hour, not moving, until your legs are part of the meadow. Then, along the frost-line, a light: low, blue-white, cold. She comes out of the alders with her brush held high and burning, a small pale fox, and stops, and looks straight at you, and goes on; and where she steps the grass goes white. She is hunting moths. They come to her light and she takes them out of the air, delicately, like someone eating grapes.".
    Otherwise "You lie in the reeds an hour, and shift, and a moorhen goes up with a clatter, and far off by the willows a cold light winks once and goes out.".
  }
  Topic honoria_giblets with honoria "Ask Honoria for something a fox would come to" when foxSeen(actor) once {
    Says "'A fox?' says Honoria. 'Chicken giblets. They'd come for those from three parishes.' She wraps you a parcel in a page of the Colonel's sermons. 'Mind, that's for catching. If you're only going to look at it, give it to the poor thing anyway.'".
    On discuss { Assert giblets(actor). }
  }
  Relation giblets(group).
  Action catch_fox(actor: group, site: place) "Lay Honoria's giblets on the frost-line, and throw a sack over the glimmer-fox when she comes" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, meadow_c) and dark() and foxSeen(actor) and giblets(actor) and not exhibit(glimmer) and not foxFreed(actor).
    Resolve check(actor, woodcraft, dc_fair).
    On success { Assert foxCaught(actor). Assert exhibit(glimmer). Assert travels(glimmer). Assert post(glimmer, rk_beasts). Increase draw(wapshotts) by 3. Increase exhibits(wapshotts) by 1. Retract giblets(actor). Set foxDays(glimmer) to 0. }
    On failure { Retract giblets(actor). }
    Result "She comes for the giblets, light first, along the frost-line, and puts her nose down; and you have the sack over her. Inside the sack she does not fight. She goes still, and the sack glows from inside, faintly, like a lantern with a cloth over it, and the canvas is cold to hold. You carry her up through the dark to the circus with the light coming through the weave in a pattern of tiny stars.".
    Otherwise "She comes for the giblets, and you move a breath too soon, and the sack comes down on frost and grass and a fox that is not there any more. The light goes away along the willows. The giblets go with it.".
  }
  Topic ada_fox with ada "Tell Ada what you saw in the water-meadows" when foxSeen(actor) and not exhibit(glimmer) and not foxPainted(wapshotts) once {
    Says "Ada listens with her pencil stopped. 'Blue-white,' she says. 'And the grass whitening. And taking moths out of the air like grapes.' She is writing fast. 'Don't catch it. I'll put it in the Brigand's Bride, part twenty-two, and Quirk can paint a bill, and the Colonel can stand on a barrel and tell them where to go to see it for nothing, and they'll come to the circus to hear about it first.' She looks up. 'People pay more for a wonder they haven't seen yet.'".
    On discuss { Assert foxPainted(wapshotts). Increase draw(wapshotts) by 1. Increase regard(billie) by 2. Increase regard(ada) by 1. }
  }
  Measure foxDays(group).
  Rule fox_pines when exhibit(glimmer) and hour(clock) == 7 and not darkTent(wapshotts) and not foxPinedToday(glimmer) {
    Increase foxDays(glimmer) by 1. Assert foxPinedToday(glimmer). Decrease welfare(wapshotts) by 1 or to nothing. }
  Rule fox_pine_reset when foxPinedToday(glimmer) and hour(clock) == 8 { Retract foxPinedToday(glimmer). }
  Relation foxPinedToday(group). Relation darkTent(concern).
  Observe fox_pining near glimmer when exhibit(glimmer) and not darkTent(wapshotts) "The glimmer-fox lies in the back of her pen with her nose in her brush. In the daylight of the tent her light is almost nothing, a grey glow, like a coal going out. Billie has put a moth-trap by her, and the moths are not coming.".
  Observe fox_days near glimmer when exhibit(glimmer) and foxDays(glimmer) >= 3 "On the board over the glimmer-fox's pen, under her name, Billie has chalked a number, and rubbed it out, and chalked a bigger one: {foxDays(glimmer)} DAYS.".
