  }
  Topic jury_keeper with keeper_a "Ask {keeper_a} what the jury will be looking for" when knows(actor, contest_rules) once {
    Says "'Me?' says {keeper_a}. 'A full house and nobody hurt. And no lies on the bills: I've had the Colonel's basilisks before, and his mermaids. Last year it was a mermaid. It was a monkey sewn to a fish.' {keeper_a} wipes the bar. 'And I'll tell you what tips it, with Pettigrew. The town. Whoever this town's fondest of on the night, that's who he'll give it to, and say it was the charter.'".
    On discuss { Assert knows(actor, jury_wants). }
  }
  Entity jury_wants: fact "{keeper_a} says the jury wants a full house, nobody hurt and no lies on the bills, and that the Clerk will give it to whichever show the town is fondest of.".
  Topic jury_priest with priest_a "Ask {priest_a} what the jury will be looking for" when knows(actor, contest_rules) once {
    Says "{priest_a} considers. 'Something true,' {priest_a} says. 'I don't mind it being impossible. A woman walking on a rope is impossible. I mind it being false.' A small smile. 'And I should like to laugh. I am asked to so seldom in my work.'".
  }

  // The Flyting: at three on the Fair's second day, on the green. Mumchance will not speak; someone must.
  Rule flyting_called at green_a when fairSecond() and hour(clock) >= 15 and not flytingDone(wapshotts) and not inBout(bombazine) and at(party, green_a)
    says "Master Pettigrew rings his bell on the mounting-block. 'THE FLYTING!' he cries. 'By old custom of the Fair, the fool of each show shall stand upon the green and abuse the other, and the Fair decide!' Captain Bombazine bounds out of the crowd in his red wig and epaulettes to a roar, and bows to all sides, and then turns to Wapshott's, where Mumchance stands in his white face with his hands folded, not saying a word, as he never does. 'WELL?' bellows Bombazine. 'Is the old man going to SPEAK? Or will somebody speak for him?' Mumchance looks at you." {
    Assert inBout(bombazine). Assert boutAtFair(bombazine). Assert heckler(bombazine). Set composure(bombazine) to 6. Set poise(party) to 3. Set jab(bombazine) to 1. Retract answered(party).
    Assert at(bombazine, green_a). Assert at(mumchance, green_a). Assert flytingCalled(wapshotts). }
  Relation flytingDone(concern). Relation flytingCalled(concern).
  Rule bomb_jab1 near bombazine when inBout(bombazine) and jab(bombazine) == 1 and not answered(party) and not jabTold(bombazine)
    says "'LOOK at it!' shouts Bombazine, pointing at you. 'Wapshott's champion! They had to send out for one! The old one's forgotten how to talk and the Colonel's forgotten how to pay!'" { Assert jabTold(bombazine). }
  Rule bomb_jab2 near bombazine when inBout(bombazine) and jab(bombazine) == 2 and not answered(party) and not jabTold(bombazine)
    says "Bombazine falls over backwards with a crash, gets up, and shouts: 'That's a FALL! Did you see? They do it for nothing at Wapshott's, because nobody's paid them to stand up!'" { Assert jabTold(bombazine). }
  Rule bomb_jab3 near bombazine when inBout(bombazine) and jab(bombazine) == 3 and not answered(party) and not jabTold(bombazine)
    says "Bombazine plants himself in front of you, nose to nose, so that his breath smells of peppermint. 'Go on,' he says, very loud. 'Say something FUNNY. I dare you. The whole Fair's waiting. Even the GEESE are waiting.'" { Assert jabTold(bombazine). }
  Rule flyting_won when boutWon(party, bombazine) and not flytingDone(wapshotts) says "Master Pettigrew rings his bell. 'The Fair has spoken!' he cries, though it is still speaking, and loudly, and mostly about you. 'The Flyting to Wapshott's!' Mumchance, who has not moved, unfolds his hands." {
    Assert flytingDone(wapshotts). Increase fairScore(wapshotts) by 2. Increase standing(tober_a) by 1. Increase regard(mumchance) by 2. }
  Rule flyting_lost when boutLost(party, bombazine) and not flytingDone(wapshotts) says "Master Pettigrew rings his bell. 'The Flyting to the Hippodrome!' Bombazine is carried off on the shoulders of the Hippodrome's canvasmen. Mumchance pats your arm, once, as he passes, and says very softly: 'I lost my first Flyting at Dunmere to a man with a trumpet. Never mind.'" {
    Assert flytingDone(wapshotts). Decrease fairScore(wapshotts) by 1. }
  Rule flyting_drawn when flytingCalled(wapshotts) and not inBout(bombazine) and not flytingDone(wapshotts) says "Master Pettigrew rings his bell, and consults nobody, and declares the Flyting a draw by ancient precedent, and goes to lunch." {
    Assert flytingDone(wapshotts). }
  Rule flyting_unanswered at green_a when fairSecond() and hour(clock) >= 16 and not flytingCalled(wapshotts) and not flytingDone(wapshotts)
    says "On the green, the Flyting is called, and Captain Bombazine abuses Wapshott's for a quarter of an hour, and Mumchance stands and looks at him without a word, as he always does, and nobody else from Wapshott's comes forward; and in the end Master Pettigrew gives it to the Hippodrome, regretfully, on the ground that silence, however eloquent, is not strictly speaking abuse." {
    Assert flytingDone(wapshotts). Decrease fairScore(wapshotts) by 1. }
  Rule bomb_home when flytingDone(wapshotts) and at(bombazine, green_a) and hour(clock) >= 17 { Assert at(bombazine, sallow_ground). }

  // The last night: both shows; the jury sees both; the verdict at nine; the reckoning at ten.
  Rule fair_scores when fairThird() and showOn(wapshotts) and act(wapshotts) == 1 and not fairCounted(wapshotts) and current(wapshotts, ?g) {
    Assert fairCounted(wapshotts). Assert juryIn(wapshotts). }
  Relation fairCounted(concern). Relation juryIn(concern).
  Rule jury_seen near ringpost when juryIn(wapshotts) and showOn(wapshotts) and not juryTold(wapshotts)
    says "On the front bench tonight, very upright, sit the jury of the Goose Fair: Master Pettigrew in his gown with his silver goose, and beside him {keeper_a} and {priest_a}, looking as if they would rather be anywhere and are secretly enjoying themselves. Behind them the benches are full to the canvas. At the very back, in dove-grey, with her account-book on her knee, sits Madame Sallow." { Assert juryTold(wapshotts). }
  Relation juryTold(concern).
  Rule jury_menagerie when juryIn(wapshotts) and exhibits(wapshotts) >= 3 and not juryMenagerie(wapshotts) { Assert juryMenagerie(wapshotts). Increase fairScore(wapshotts) by 1. }
  Rule jury_basilisk when juryIn(wapshotts) and basiliskBilled(wapshotts) and not juryBasilisk(wapshotts) { Assert juryBasilisk(wapshotts). Decrease fairScore(wapshotts) by 2. }
  Rule jury_honest when juryIn(wapshotts) and basiliskHonest(wapshotts) and not juryBasilisk(wapshotts) { Assert juryBasilisk(wapshotts). Increase fairScore(wapshotts) by 1. }
  Rule jury_town when juryIn(wapshotts) and standing(tober_a) >= 5 and not juryTown(wapshotts) { Assert juryTown(wapshotts). Increase fairScore(wapshotts) by 2. }
  Rule jury_mother when juryIn(wapshotts) and reunited(pruett) and not juryMother(wapshotts) { Assert juryMother(wapshotts). Assert at(pruett, ring_a). }
  Relation juryMenagerie(concern). Relation juryBasilisk(concern). Relation juryTown(concern). Relation juryMother(concern).
  Rule basilisk_found_out near ringpost when juryIn(wapshotts) and basiliskBilled(wapshotts) and showOn(wapshotts) and act(wapshotts) == 3 and not exposedTold(wapshotts)
    says "In the interval a farmer's boy who went into the menagerie to see THE BASILISK, LIVING comes back out and stands up on the bench and shouts, 'IT'S OUR SIR RODERICK! IT'S GRANFER TULL'S BANTAM, HE SOLD IT AT MICHAELMAS, IT'S GOT DYE ON!' The house laughs. The jury does not. Master Pettigrew writes something in his ledger." { Assert exposedTold(wapshotts). }
  Relation exposedTold(concern).
  Rule verdict at green_a when fairThird() and hour(clock) >= 21 and juryIn(wapshotts) and not contestWon(wapshotts) and not contestLost(wapshotts) and quality(wapshotts) + fairScore(wapshotts) >= 12
    says "At the pump on the green, under a ring of lanterns, Master Pettigrew climbs onto his mounting-block and rings his bell until the whole Fair is quiet, even the geese. 'By the charter of the Goose Fair,' he says, 'the jury has seen both shows. Madame Sallow's Hippodrome is magnificent. It is everything a show should be. And this town,' he says, and seems surprised at himself, 'is fond of the other one.' He holds up a purse. 'The Great Pitch of the Fair, and forty coin, to WAPSHOTT'S.' The roar goes up and up. The Colonel, in his crimson coat, does not roar. He takes off his hat, and holds it over his heart, and weeps openly, and at the back of the crowd Madame Sallow closes her account-book and claps, twice, precisely." {
    Assert contestWon(wapshotts). Increase strongbox(wapshotts) by 40. Increase standing(tober_a) by 1. }
  Rule verdict_lost at green_a when fairThird() and hour(clock) >= 21 and juryIn(wapshotts) and not contestWon(wapshotts) and not contestLost(wapshotts) and quality(wapshotts) + fairScore(wapshotts) < 12
    says "At the pump on the green, under the lanterns, Master Pettigrew rings his bell for silence. 'By the charter of the Goose Fair,' he says, 'the jury has seen both shows. The Great Pitch, and forty coin, to Sallow's Imperial Hippodrome.' There is a cheer, and some of it is real. The Colonel, in his crimson coat, nods, and bows to the blue-and-gold canvasmen, beautifully, and does not let anyone see his face." {
    Assert contestLost(wapshotts). }
  Rule no_show_no_contest at green_a when fairThird() and hour(clock) >= 21 and not juryIn(wapshotts) and not contestWon(wapshotts) and not contestLost(wapshotts)
    says "At the pump Master Pettigrew gives the Great Pitch and the purse to the Hippodrome, which was the only show in {town_a} tonight." { Assert contestLost(wapshotts). }

  // The reckoning, at ten, in the Colonel's wagon.
  Rule reckoning_paid near wapshott when (contestWon(wapshotts) or contestLost(wapshotts)) and hour(clock) >= 22 and not noteSettled(wapshotts) and strongbox(wapshotts) >= note(wapshotts)
    says "At ten Madame Sallow comes to the Colonel's wagon, alone, with her cane and her account-book, and the whole circus finds a reason to be in the wagon-ring. The Colonel opens the strongbox. He counts out sixty coin onto her open book, one at a time, slowly, saying the numbers aloud, and Ada behind him mouths them with him; and when he has finished he takes her hand and kisses it, and bows, and steps back, and falls magnificently over the boot-scraper. For once in his life he meant to. In the shadow of the next wagon Mumchance, who has seen it, says nothing, and nods, once, as if a long-standing account had been settled too. Madame Sallow looks down at the Colonel on the grass. 'Florian,' she says. 'You have paid a debt. I am not sure you know what to do now.' 'Nor am I,' says the Colonel from the grass. 'Isn't it wonderful?'" {
    Assert noteSettled(wapshotts). Assert noteDischarged(wapshotts). Decrease strongbox(wapshotts) by note(wapshotts). Set note(wapshotts) to 0. }
  Rule reckoning_torn near wapshott when (contestWon(wapshotts) or contestLost(wapshotts)) and hour(clock) >= 22 and not noteSettled(wapshotts) and strongbox(wapshotts) < note(wapshotts) and sleeExposed(slee)
    says "At ten Madame Sallow comes to the Colonel's wagon, alone, with her account-book. The Colonel opens the strongbox and shows her what is in it, which is not enough, and begins to make a speech. She stops him with one gloved hand. Then she takes the note out of her book, and looks at it, and tears it in half, and in half again, and lets the pieces fall into the strongbox. 'My man worked against you,' she says. 'With my money, in my name. I will not take a thing I have half-stolen.' She turns to go, and turns back. 'Next year, Florian, I shall beat you fairly. Please be there. It is very dull being magnificent alone.'" {
    Assert noteSettled(wapshotts). Assert noteTorn(wapshotts). Set note(wapshotts) to 0. }
  Rule reckoning_merged near wapshott when (contestWon(wapshotts) or contestLost(wapshotts)) and hour(clock) >= 22 and not noteSettled(wapshotts) and strongbox(wapshotts) < note(wapshotts) and not sleeExposed(slee)
    says "At ten Madame Sallow comes to the Colonel's wagon with her account-book, and the Colonel shows her the strongbox, which is not enough. She does not gloat. She sits down on his steps and opens the book. 'The wagons, the canvas, the beasts, and the people, by the note, are mine,' she says. 'I do not want them. I want them run.' She writes. 'SALLOW AND WAPSHOTT'S UNITED CIRCUS. Your name second; it is alphabetical. You will have the ring and the bills and the parade and every idea you have ever had, and I will have the strongbox and the key to it.' She holds out the pen. The Colonel looks at the pen as a man looks down a well. Then he signs, and the whole wagon-ring breathes out. 'Cordelia,' he says. 'Florian,' she says. 'You have ink on your moustache.'" {
    Assert noteSettled(wapshotts). Assert merged(wapshotts). Set note(wapshotts) to 0. Retract offstage(sallow). Assert travels(sallow). Assert post(sallow, rk_wagons). }

  // ── After the Fair ─────────────────────────────────────────────────────────────────────────────────────────
  Rule hippodrome_leaves when noteSettled(wapshotts) and not sallowGone(wapshotts) and hour(clock) >= 6 and day(clock) > fairDay(wapshotts) + 2 {
    Assert sallowGone(wapshotts). Assert sleeGone(slee). Assert offstage(slee). Assert offstage(bombazine). }
  Rule sallow_away when sallowGone(wapshotts) and not merged(wapshotts) and not offstage(sallow) and not sallowAtRevels(sallow) { Assert offstage(sallow). }

  Observe united_board near pole when merged(wapshotts) and pitched(wapshotts) and at(pole, ?r) "On the painted front of the big top a new board has been nailed over the old: SALLOW & WAPSHOTT'S UNITED CIRCUS. Under it, in chalk, in a large looping hand: (WAPSHOTT'S).".
  Observe pitch_charter near pole when contestWon(wapshotts) and at(pole, ?r) "Nailed to the ticket wagon, framed in gilt, is a parchment with a red seal: THE CHARTER OF THE GREAT PITCH OF THE GOOSE FAIR OF {town_a}, TO WAPSHOTT'S CIRCUS, IN PERPETUITY OR UNTIL FURTHER NOTICE.".
  Topic wap_next with wapshott "Ask the Colonel what comes next for Wapshott's" when noteSettled(wapshotts) once {
    Says "The Colonel stands at the field gate in the morning with his hands behind his back, looking at the road. 'Next,' he says. 'Next season, my friend, the menagerie GROWS. An elephant. No. Something bigger than an elephant.' He turns. 'Quirk! What is bigger than an elephant?' 'A whale, Colonel,' says Quirk, from up a ladder. 'Bigger.' Pip, going by with a bucket, says: 'They dug a bone out of the marl-pit at {town_c} last spring, Colonel, a thigh-bone as long as a man, and they've put it in the shrine and nobody knows what it's off.' The Colonel goes very still. A light comes into his eye that Ada, in the hatch of the ticket wagon, sees from forty feet off, and puts her pen down, and puts her head in her hands. The Colonel, without turning round, says to you, quite quietly: 'Thank you. I mean it. Ada tells me I never sound as if I do.'".
    On discuss { Assert knows(actor, bone_heard). }
  }
  Entity bone_heard: fact "A thigh-bone as long as a man was dug out of the marl-pit at {town_c}, and the Colonel has heard of it.".
  Topic wap_letter with wapshott "Ask the Colonel about the letter with the crowned seal" when noteSettled(wapshotts) and (crestShown(wapshotts) or contestWon(wapshotts)) once {
    Says "The Colonel takes it out of his inside pocket, where it has been since dawn, over his heart. Thick paper, a seal of red wax: a wheel, with a crown over it. 'A gentleman was in the house on the last night,' he says. 'In a plain coat, at the back. He wrote this at the inn and left it for me.' He reads it to you, though he clearly knows it by heart. 'The Steward of the Household of the Progress presents his compliments to Colonel Wapshott, and begs to inquire whether the Colonel would consider bringing his company, and,' the Colonel's voice wobbles, 'his tortoise, to perform before the Household at a date to be agreed.' He folds it. 'Before the Household,' he says. 'The Household of the Progress.' He looks at you. 'Hench says I must learn to bow. Properly. To a dowager who is also an archduke.' He swallows. 'I have never been so frightened in my life.'".
  }
  Topic ada_torn with ada "Ask Ada what she made of Madame Sallow tearing up the note" when noteTorn(wapshotts) once {
    Says "Ada has the torn pieces of the note in an envelope in the back of the ledger, between the Brigand's Bride and the wages. 'I'm keeping them,' she says. 'For when he forgets.' She is quiet. 'She looked at the books, you know. Before she tore it. She asked to see them and I showed her, and she went down every page with her finger, and at the end she said, Miss Thripp, you are wasted on him. And I said, I know. And she said, So was I.' Ada shuts the ledger. 'Then she tore it up.'".
  }
  Query crestShown(n: concern) means knows(party, crest_known) and exhibit(methuselah).
  Topic mum_end with mumchance "Ask Mumchance how he feels, now the Fair is done" when noteSettled(wapshotts) once {
    Says "Mumchance is sitting on his bucket in the sun, with no face on, which you have hardly seen: an old man's face, lined and plain and very kind. 'Tired,' he says. 'Good tired.' He watches Honoria hanging out the washing on the guy-ropes. 'She asked me last night,' he says, 'whether I remembered Wakeham. I said I'd never forgotten it.' He picks a straw off his knee. 'Then neither of us said anything for an hour, which is about right for us.' He looks at you. 'We go round again tomorrow. Come and find us. You always know where we are; we're the ones in the field.'".
  }
  Milestone m_turn "went on in the ring at Wapshott's" worth 50 when turns(party) >= 1.
  Milestone m_triumph "brought the house down at Wapshott's" worth 100 when renown(party) >= 4.
  Milestone m_fall "learned the Fall from Mumchance" worth 50 when fallLearned(party).
  Milestone m_art "learned the four foundations of the Gentle Art" worth 200 when fallLearned(party) and lookLearned(party) and feintLearned(party) and answerLearned(party).
  Milestone m_jos "out-heckled Jos Haverhill" worth 75 when boutWon(party, jos).
  Milestone m_quinceys "mended the Brothers Quincey" worth 100 when feudMended(hal).
  Milestone m_sylph "walked the Sylph of the Wire home to her mother" worth 150 when reunited(pruett).
  Milestone m_nell "brought Nell to see her father's tent lit" worth 75 when nellTold(nell).
  Milestone m_basilisk "found out the basilisk" worth 50 when knows(party, roderick_known).
  Milestone m_fox "saw the glimmer-fox hunting moths" worth 75 when foxSeen(party).
  Milestone m_fox_free "let the glimmer-fox go home" worth 75 when foxFreed(party).
  Milestone m_hob "found Ninepence the hob a hearth" worth 150 when hobJoined(ninepence) or hobAtInn(ninepence).
  Milestone m_bramble "brought in the owlbear of the orchards alive" worth 200 when exhibit(bramble) or brambleLost(wapshotts).
  Milestone m_tortoise "brought the Tortoise of Antiquity up to the circus" worth 75 when tortoiseHome(wapshotts).
  Milestone m_serpent "found Fipps his serpent" worth 75 when serpentGiven(party).
  Milestone m_slee "showed Madame Sallow what her man had done" worth 150 when sleeExposed(slee).
  Milestone m_flyting "won the Flyting at the Goose Fair" worth 150 when boutWon(party, bombazine).
  Milestone m_pitch "saw Wapshott's win the Great Pitch of the Goose Fair" worth 250 when contestWon(wapshotts) and knows(party, note_known).
  Milestone m_note "saw the Colonel's note settled" worth 200 when (noteDischarged(wapshotts) or noteTorn(wapshotts)) and knows(party, note_known).
}

data/goings-on/circus/pells.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── Pell's Comedians, of the Theatre Royal at Dunmere ───────────────────────────────────────────────────────
  // Once the letter is out they travel the circuit too, always one town ahead of the wagons, playing tragedy on a
  // cart-stage on the green and skimming the house the circus will want. For the Revels stand they are at the King's
  // Rest, as claimants. They are not villains: a company of real actors, poor and proud, who think the circus a
  // disease of the public taste and are a little afraid it may be the cure.
  Relation pellsOut(concern). Relation pellsPlayed(place). Relation pellPlayer(group).
  Person augustus "Augustus Pell" at tober_a {
    Role "the manager and tragedian of Pell's Comedians". Ancestry human. Peaceable. Pronouns he. Manner proud.
    Greets "A tall man in a cloak with a fur collar the moths have been at, a profile like a coin and a voice like a cello played in a cathedral, turns to you as if you had entered stage left. 'Augustus Pell,' he says, 'of the Theatre Royal, Dunmere. You will have heard of my Margrave.' You have not. He forgives you with a small gesture. 'You are with the circus. One can always tell. There is a little sawdust about the soul.'".
    Greets again "Augustus Pell inclines his profile toward you, the better side.".
  }
  Person clem_vane "Clemency Vane" at tober_a {
    Role "the leading lady of Pell's Comedians". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "A handsome tired woman of forty in a dressing-gown over the second act of something, with a cold cup of tea and a part pinned to her knee, looks up at you. 'Clemency Vane,' she says. 'I have died eleven hundred times. Poisoned, stabbed, of grief, in a convent, under a portcullis. Once of a draught, but that was a real one.' She sips the cold tea. 'You're from the circus. Is it true your Sylph sits down in the middle of the wire? I should give my teeth to be allowed to sit down in the middle of anything.'".
    Greets again "Clemency Vane raises her cold cup to you.".
  }
  Person kit "Kit Darrow" at tober_a {
    Role "Pell's apprentice". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "A gangling boy of eighteen in a tragic black doublet too short in the sleeves is practising a dying fall against a cart-wheel, and doing it badly, and enjoying it far too much. 'Kit Darrow,' he says from the ground. 'Apprentice. I play Prudence, the Second Murderer and a tree.' He sits up. 'Mr Pell says I die like a man falling off a cart. I say that's how people die. Mostly. Off carts.'".
    Greets again "'Hullo!' says Kit Darrow, from somewhere on the ground.".
  }
  Person motherpell "Mother Pell" at tober_a {
    Role "the grandmother of Pell's Comedians, a clown of the old theatre". Ancestry human. Peaceable. Pronouns she. Manner jovial.
    Greets "In a bath-chair by the cart-stage, wrapped in shawls up to a nose like a parrot's, sits a tiny old woman with eyes like two currants in a bun. 'Mother Pell,' she says, in a big warm voice, and then, without moving her face at all, in a perfect copy of Augustus: 'You will have HEARD of my MARGRAVE.' Then in her own again: 'He's my grandson. I taught him everything and he forgot the funny part.' She looks you up and down. 'You've been near Gus Fell. I can smell the greasepaint. White, with a bit of lard in it. He always used too much lard.'".
    Greets again "'You again,' says Mother Pell, in your own voice, exactly, and then laughs in hers.".
  }
  Initially Assert offstage(augustus). Initially Assert offstage(clem_vane). Initially Assert offstage(kit). Initially Assert offstage(motherpell).
  Initially Assert pellPlayer(augustus). Initially Assert pellPlayer(clem_vane). Initially Assert pellPlayer(kit). Initially Assert pellPlayer(motherpell).
  Rule pells_come when letterCome(wapshotts) and day(clock) >= letterDay(wapshotts) + 1 and not pellsOut(wapshotts) { Assert pellsOut(wapshotts). }
  Rule pells_ahead when pellsOut(wapshotts) and not revelsDone(wapshotts) and pellPlayer(?p) and current(wapshotts, ?g) and nextGround(?g, ?n) and greenOf(?n, ?green)
    and not here(tober_r) and not at(?p, ?green) and not kitAway(?p) {
    Retract offstage(?p). Assert at(?p, ?green). }
  Rule pells_at_rest when pellsOut(wapshotts) and here(tober_r) and pellPlayer(?p) and not at(?p, revels_hall) and not revelsDone(wapshotts) and not kitAway(?p) {
    Retract offstage(?p). Assert at(?p, revels_hall). }
  Rule pells_on when revelsDone(wapshotts) and pellPlayer(?p) and not offstage(?p) and not kitAway(?p) and hour(clock) >= 6 and day(clock) > revelsDay(wapshotts) { Assert offstage(?p). }
  Relation kitAway(group).
  Observe pells_playing near augustus when pellsOut(wapshotts) and not here(tober_r) and hour(clock) >= 19 and hour(clock) < 21 "On a cart-stage in the middle of the town, by the light of four smoking flares, Pell's Comedians are playing THE TRAGEDY OF THE UNHAPPY MARGRAVE to forty people standing and a dog. Augustus Pell dies at length. Clemency Vane dies more briefly and better. A boy in a black doublet, who is a tree in the first act, catches a falling flare without breaking the line, and the dog barks at him.".
  Observe pells_by_day near augustus when pellsOut(wapshotts) and not here(tober_r) and (hour(clock) < 19 or hour(clock) >= 21) "Against a wall stands the cart of Pell's Comedians: a wagon that unfolds into a stage, painted THEATRE ROYAL DUNMERE in letters of faded gold, with a canvas sky rolled on the roof and a bath-chair chained to the tail.".
  // A town that saw the tragedy last week has spent its coin.
  Rule pells_skim when pellsOut(wapshotts) and hour(clock) == 20 and at(augustus, ?green) and greenOf(?n, ?green) and not pellsPlayed(?n) { Assert pellsPlayed(?n). }
  Rule pells_house when showOn(wapshotts) and act(wapshotts) == 1 and not told(part_entry) and current(wapshotts, ?g) and pellsPlayed(?g) {
    Retract pellsPlayed(?g). Decrease house(wapshotts) by 2 or to nothing. }
  Topic ada_pells with ada "Ask Ada why the houses are thinner this round" when pellsOut(wapshotts) once {
    Says "'Pell's,' says Ada, and taps the ledger. 'They go a town ahead of us and play tragedy on a cart for half our price, and the flatties have had their evening out by the time we come. Two coin a night off the house, near enough.' She sniffs. 'The worst of it is, they're good. I went to see the Margrave in {town_c} on my afternoon off. I cried at the poison. Don't tell the Colonel.'".
  }

  Topic augustus_circus with augustus "Ask Augustus Pell what he has against the circus" when true once {
    Says "'Against it?' Augustus Pell looks wounded, nobly. 'Nothing. I simply observe that for three thousand years the stage has been a place where human beings speak to each other of their souls, and for nineteen your Colonel has made it a place where a large woman lifts a horse.' He arranges his cloak. 'The Revels were plays. Masques. Allegories of the Virtues, in verse. The beasts came after, as a sort of interval. We shall give them a masque. You will give them a horse being lifted.' A pause, less noble. 'It is a very good horse.'".
  }
  Topic augustus_secret with motherpell "Ask Mother Pell why Augustus hates clowns" when true once {
    Says "Mother Pell's currant eyes go bright. 'Because he was one,' she says. 'At eight. I put him in the harlequinade at the Theatre Royal as a little Pierrot, and he fell over, which was the joke, and the house laughed, which was the point, and he cried, which was not.' She sighs. 'He took up tragedy so nobody would ever laugh at him again. Forty years. And they laugh all the same, at the dying; they think nobody notices.' She pats your hand. 'Don't you tell him I told you. I'll do his voice at you in your sleep.'".
    On discuss { Assert knows(actor, augustus_pierrot). }
  }
  Entity augustus_pierrot: fact "Augustus Pell played a Pierrot at eight in his grandmother's harlequinade, fell over, was laughed at, and has played tragedy ever since so that nobody should laugh at him again.".
  Topic clemency_dying with clem_vane "Ask Clemency Vane whether she likes dying for a living" when true once {
    Says "'Like it?' Clemency considers her cold tea. 'I was a comedienne, you know. At twenty. Sauce and a fan and the second-best legs in Dunmere. Then Augustus married me, and in our company the leading lady dies.' She sets the cup down. 'He's a good man and a great actor and he has never once let me be funny in front of him. I don't think he knows he hasn't.' She looks across at the circus's posters on the inn wall, the Sylph sitting on her wire. 'I should like, once before I die properly, to sit down in the middle of something.'".
    On discuss { Assert knows(actor, clemency_comic). }
  }
  Entity clemency_comic: fact "Clemency Vane, Pell's leading lady and his wife, was a comedienne before she married him; in Pell's company the leading lady dies, and she has never been let be funny since.".

  // ── Mother Pell and Mumchance: an old double act ───────────────────────────────────────────────────────────
  Topic motherpell_gus with motherpell "Ask Mother Pell how she knows Mumchance" when true once {
    Says "'Know him? I was half of him.' She settles in her shawls. 'Pell and Fell, at the Midsummer Fair at Dunmere, forty years ago. He did the falls, I did the voices. He never said a word, so I said all of them: his, mine, the Lord Mayor's, the horse's. The whole fair, in two mouths, and one of them shut.' She is quiet. 'Then my father wanted me back indoors, at the Theatre Royal, with a roof and a salary. And Gus wouldn't come indoors. He said a circus is a thing that leaves, and he'd sooner fall in a field than stand on a stage that stays put.' She sniffs. 'Forty years. He's never once written. Well. He can't, can he. He'd have to say something.'".
    On discuss { Assert knows(actor, pell_and_fell). }
  }
  Entity pell_and_fell: fact "Forty years ago at the Midsummer Fair at Dunmere, Mumchance and Mother Pell were a double act, Pell and Fell: he did the falls and she did all the voices; they parted when she went indoors to the Theatre Royal and he would not.".
  Topic mum_pell with mumchance "Tell Mumchance that Mother Pell is with Pell's Comedians, and remembers Pell and Fell" when knows(actor, pell_and_fell) once {
    Says "Mumchance's brush stops halfway across his mouth. He sits quite still on his bucket for long enough that a hen walks past him and looks back. 'Polly Pell,' he says at last. 'She did my voice better than I did.' He finishes the line of his mouth, very carefully. 'Is she well? Does she still do the Lord Mayor?' You say she does it at the dog. Something happens to the white face that, in anyone else, would be laughing. 'Tell her,' he says, and stops. 'No. Don't tell her anything. I'll,' and stops again. 'Forty years,' he says. 'I never once knew what to say to her. She always said it for me.'".
    On discuss { Assert knows(actor, mum_pell_known). }
  }
  Entity mum_pell_known: fact "Mumchance still does not know what to say to Polly Pell after forty years; she always said it for him.".
  Relation pellAndFellMet(group).
  Rule old_partners at revels_hall when here(tober_r) and at(motherpell, revels_hall) and knows(party, mum_pell_known) and at(party, revels_hall) and not pellAndFellMet(mumchance)
    says "Mumchance comes into the Revels Hall in his shirt-sleeves, without his face on, and stops inside the door. In her bath-chair by the green stage Mother Pell sees him and goes perfectly still. Then, without a word, she does his voice, his real soft dry voice, saying: 'Hullo, Polly.' And Mumchance, who cannot think what to say, has had it said for him again, and sits down on the stage steps beside her chair, and takes her hand, and they stay like that, saying nothing at all, the two halves of Pell and Fell, while Augustus stands in the gallery with his mouth open." {
    Assert pellAndFellMet(mumchance). Increase regard(motherpell) by 2. Increase regard(mumchance) by 2. }

  // ── Kit and Pip ────────────────────────────────────────────────────────────────────────────────────────────
  // Kit walks back along the road after Pell's show to see the circus's; Pip notices. It goes on whether or not the
  // company has a hand in it; the company may be asked.
  Measure kitNights(group). Relation kitAsked(group). Relation kitJoins(group). Relation pipToTheatre(group).
  Rule kit_watches near ringpost when pellsOut(wapshotts) and showOn(wapshotts) and act(wapshotts) == 7 and not kitSeenTonight(kit) and not travelsWith(pip, party) and not revelsDone(wapshotts)
    says "At the very back of the house, still in half a tree costume with the leaves taken off, stands a boy who has walked two hours along the road from Pell's cart to see the end of the show. When Pip cartwheels past in the parade he does not look at anything else." {
    Assert kitSeenTonight(kit). Increase kitNights(kit) by 1. }
  Relation kitSeenTonight(group).
  Rule kit_reset when kitSeenTonight(kit) and not showOn(wapshotts) and hour(clock) == 6 { Retract kitSeenTonight(kit). }
  Topic pip_kit with pip "Ask Pip about the boy in the tree costume at the back of the house" when kitNights(kit) >= 2 and not kitAsked(pip) once {
    Says "Pip goes red from the collar up. 'Kit,' she says. 'Kit Darrow. He's Pell's. He plays a tree. He walks all the way back after his own show to see ours, and then all the way to his again, in the dark, and he's always got a bit of a leaf on him somewhere.' She scuffs the sawdust. 'He wants to be a clown. He's terrible. He falls like a cupboard. He asked me to show him the get-up.' She looks at you sideways. 'Mr Pell would never let him go. And I couldn't go to Pell's; I'd have to stand still and say verse.' She falls over a bucket, which you think she meant. 'What would you do?'".
    On discuss { Assert kitAsked(pip). }
  }
  Topic pip_kit_come with pip "Tell Pip that Kit should come to Wapshott's, and learn the get-up from Mumchance" answering pip_kit when not kitJoins(kit) and not pipToTheatre(pip) {
    Says "'Mr Pell will go purple,' says Pip, delighted at the thought. 'He'd lose his Prudence.' She thinks. 'Mumchance would take him. He'd take anybody who can fall without crying.' She runs off to find a pencil and paper, and spends the dead hour after dinner writing what is clearly a very long letter.".
    On discuss { Assert kitPlanned(kit). }
  }
  Topic pip_kit_go with pip "Tell Pip she could try the theatre for a season, and come back with all the words she can't help saying" answering pip_kit when not kitJoins(kit) and not pipToTheatre(pip) {
    Says "Pip stares at you. 'Me? Indoors?' Then her face does something complicated. 'Mother Pell does voices. All of them. Mumchance says she was the other half of him.' She hugs her knees. 'A loud clown. In a theatre where you can hear the loud.' She does not decide; you can see her not deciding. 'I'd have to ask Mumchance. I'd have to ask him with my face, he won't hear it any other way.'".
    On discuss { Assert pipThinks(pip). }
  }
  Relation kitPlanned(group). Relation pipThinks(group).
  Rule kit_comes_over near kit when kitPlanned(kit) and here(tober_r) and day(clock) == revelsDay(wapshotts) - 1 and not kitJoins(kit)
    says "On the day before the Revels, in the dead hour after dinner, Kit Darrow walks out of the Revels Hall with his bundle on his back and his tree costume over his arm, across the Long Court in front of all of Pell's Comedians, and asks Mumchance, at the cookhouse fire, whether he might learn to fall. Mumchance looks at him. Then he pushes him over. Kit gets up, and looks at the ground as if it had insulted his mother. Mumchance nods. In the gallery of the Revels Hall, Augustus Pell has gone the colour of a plum." {
    Assert kitJoins(kit). Assert kitAway(kit). Assert travels(kit). Assert post(kit, rk_ring). Retract offstage(kit). }
  Rule pip_goes near pip when pipThinks(pip) and revelsDone(wapshotts) and not pipToTheatre(pip) and not kitJoins(kit) and not travelsWith(pip, party) and day(clock) > revelsDay(wapshotts)
    says "The morning after the Revels, Pip Gallant goes round the backyard with her bundle and a red nose in her pocket and kisses everybody, including Bucephalus, who allows it, and climbs up on the tail of Pell's cart beside Kit and Mother Pell's bath-chair. 'One season,' she shouts to the circus. 'Loud!' Mumchance, at the cookhouse fire, lifts one hand. Then he goes into his wagon and stays there until noon." {
    Assert pipToTheatre(pip). Assert away(pip). Assert offstage(pip). }
  Topic augustus_kit with augustus "Ask Augustus Pell how he does without his Prudence" when kitJoins(kit) once {
    Says "Augustus Pell regards you down his nose for a long time. 'A tree,' he says, 'can be replaced. Prudence is a tree in a better costume.' A pause. 'He was never going to be a tragedian. He laughed in the poison scene. Every night. Quietly, but I heard.' He turns away, and turns back. 'You will tell Fell to teach him properly. Not the lard. The lard is a disgrace.'".
  }
}

data/goings-on/circus/progress.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── Phase II: The Crowned Wheel ─────────────────────────────────────────────────────────────────────────────
  // On the first day of the first stand after the Goose Fair (the second town), the Clerk of the Household of the
  // Progress comes to the circus with a letter: the Steward has leave for one Little Progress, a night of Revels at
  // the King's Rest eleven days on, where the office of Master of the Revels and Keeper of the Menagerie Royal may be
  // given. The circus's next round goes up the hill for its last stand; the Revels are on that stand's third night.
  Relation letterCome(concern). Measure letterDay(concern). Measure revelsDay(concern). Relation restRound(concern).
  Relation revelsOn(concern). Relation revelsDone(concern).
  Query revelsNight() means letterCome(wapshotts) and day(clock) == revelsDay(wapshotts).
  Query phaseTwo() means letterCome(wapshotts) and not revelsDone(wapshotts).

  Chapter ch_letter "The Letter" when knows(party, letter_known) "Fame, when it comes to a travelling circus, comes on foot, in a good coat gone shiny at the elbows, carrying a letter with a red seal. Nobody in the backyard has ever seen a seal like it. Everybody has an opinion about it by dinner.".
  Chapter ch_rest "The King's Rest" when letterCome(wapshotts) and at(party, rest_gate) "Up the hill road, through the rooks, to a gatehouse twice as high as it needs to be, with a wheel and a crown over the arch. Behind it, half a furlong of swept stone, and an old man leaning on a broom, waiting, as his family has waited, for the kings to come back.".

  Person tobias "Tobias Quarrendon" at tober_a {
    Role "the Clerk of the Household of the Progress". Ancestry human. Peaceable. Pronouns he. Manner cheerful. Wants progress_seal_kind.
    Greets "A tall young man in a good black coat gone shiny at the elbows, with ink on his cuffs, a satchel of papers, a face all nose and earnestness, and a seal-ring on a ribbon round his neck (no; on second look the ribbon is empty, and he keeps touching it), stands up very quickly and drops several papers. 'Quarrendon,' he says. 'Tobias. Clerk of the Household of the Progress. The Household is myself and my great-aunt. She is the Steward; I am,' he gathers the papers, 'everything else.'".
    Greets again "Tobias Quarrendon stands up, drops something, and is very glad to see you.".
  }
  Initially Assert offstage(tobias).
  Rule letter_comes when noteSettled(wapshotts) and pitched(wapshotts) and current(wapshotts, tober_b) and day(clock) == arrivedDay(wapshotts) and hour(clock) >= 15
    and not letterCome(wapshotts) and groundRoom(tober_b, rk_wagons, ?w) {
    Assert letterCome(wapshotts). Set letterDay(wapshotts) to day(clock). Set revelsDay(wapshotts) to day(clock) + 11.
    Retract offstage(tobias). Assert at(tobias, ?w). Assert travels(tobias). Assert post(tobias, rk_wagons). Assert sealLost(tobias). }
  Rule letter_told near tobias when letterCome(wapshotts) and at(tobias, ?w) and at(wapshott, ?w) and not letterTold(wapshotts)
    says "A tall young man in a shiny black coat is on the Colonel's steps with a letter held out in both hands, as if it might go off. The Colonel takes it. The seal is red, a crowned wheel. He reads it, and sits down on his own boot-scraper, and reads it again, and then reads it aloud to the wagon-ring in a voice that goes up and up: 'The Steward of the Household of the Progress, having the Crown's leave for a Little Progress, will hold Revels at the King's Rest on the twelfth night from this, and will hear the claims of any company to the office of MASTER OF THE REVELS AND KEEPER OF THE MENAGERIE ROYAL, vacant these three hundred years.' The Colonel lowers the letter. Nobody in the backyard says anything. Then Bucephalus, in the horse lines, sneezes." {
    Assert letterTold(wapshotts). }
  Relation letterTold(concern).
  Entity letter_known: fact "The Steward of the Household of the Progress will hold Revels at the King's Rest, above {town_b}, on the twelfth night after the letter came, and give the vacant office of Master of the Revels and Keeper of the Menagerie Royal to the company that best deserves it.".
  Topic tobias_letter with tobias "Ask Tobias what the Household is, and what the Revels are" when letterCome(wapshotts) once {
    Says "Tobias sits on the steps and explains, with his hands. 'The Household of the Progress went round the country with the old kings: two hundred wagons, a chapel on wheels, the Treasury in an iron cart, and the Menagerie Royal behind, so the country could see what the king had. The King's Rest, on the hill above this town, was its winter seat. Then there was a war, or a wedding, nobody agrees, and the Progress never came back, and the Household went on existing. On paper. In a house near the sea.' He smiles. 'My great-aunt has been Steward for fifty years and has never once had anything to steward. Then the Crown said she might hold one Little Progress, a night of Revels at the Rest, and give the old office, if anyone deserves it.' He looks at the big top. 'I was at your Goose Fair. At the back. I wrote to her that night. I said: they have been going round the Progress road for nineteen years and do not know it.'".
    On discuss { Assert knows(actor, letter_known). Assert knows(actor, rest_heard). }
  }
  Topic tobias_road with tobias "Ask Tobias what he meant, that the circus goes round the Progress road" when knows(actor, letter_known) once {
    Says "'The milestones!' Tobias is delighted that anybody asked. 'Every road your wagons take has the old stones on it, a crowned wheel on each, mostly worn to a smudge. The Progress came this way, {town_a}, {town_b}, {town_c}, and round, exactly as you do, exactly as slowly. Your Colonel thought he chose his circuit.' He laughs. 'Nobody chooses a road. A road chooses the people who need it.'".
  }
  Observe revels_bill_a at green_a when letterCome(wapshotts) and not revelsDone(wapshotts) "Over Wapshott's bill someone has pasted a new one, gold on black, with a crowned wheel at the top: THE REVELS OF THE PROGRESS AT THE KING'S REST, ABOVE {town_b}. FOR THE FIRST TIME IN THREE HUNDRED YEARS. WAPSHOTT'S CIRCUS WILL ATTEND. ON THE LAST NIGHT OF ITS ROUND.".
  Observe revels_bill_b at green_b when letterCome(wapshotts) and not revelsDone(wapshotts) "Over Wapshott's bill someone has pasted a new one, gold on black, with a crowned wheel at the top: THE REVELS OF THE PROGRESS AT THE KING'S REST, ON THE HILL ABOVE THIS TOWN. FOR THE FIRST TIME IN THREE HUNDRED YEARS. WAPSHOTT'S CIRCUS WILL ATTEND. ON THE LAST NIGHT OF ITS ROUND.".
  Observe revels_bill_c at green_c when letterCome(wapshotts) and not revelsDone(wapshotts) "Over Wapshott's bill someone has pasted a new one, gold on black, with a crowned wheel at the top: THE REVELS OF THE PROGRESS AT THE KING'S REST, ABOVE {town_b}. FOR THE FIRST TIME IN THREE HUNDRED YEARS. WAPSHOTT'S CIRCUS WILL ATTEND. ON THE LAST NIGHT OF ITS ROUND.".
  Observe milestone_ab at road_ab when true "By the road stands an old milestone, worn to a stub, with a wheel cut in it and something over the wheel that might once have been a crown.".
  Observe milestone_bc at road_bc when true "A milestone leans in the grass at the roadside, half sunk: on its face a worn wheel, and over it, if you look closely, the points of a crown.".
  Observe milestone_ca at road_ca when true "At a bend in the road a squat old milestone with a crowned wheel cut in its face, so worn that the crown is only a row of bumps, like knuckles.".
  Topic tobias_who with tobias "Ask Tobias who else means to claim the office" when knows(actor, letter_known) once {
    Says "'The letter went to every company that plays the Progress road,' says Tobias. 'So far: you; Pell's Comedians, of the Theatre Royal at Dunmere, who say that the Revels were plays before ever they were beasts, which is true, and that a circus is a disease of the public taste, which my great-aunt thinks is a point of view.' He hesitates. 'And Madame Sallow has written.' He looks at the Colonel's wagon. 'She wrote a very short letter. It said: Yes.'".
    On discuss { Assert knows(actor, rivals_known). }
  }
  Entity rivals_known: fact "Pell's Comedians, of the Theatre Royal at Dunmere, claim the office of the Revels too; and Madame Sallow has written, Yes.".
  Topic tobias_wants with tobias "Ask Tobias what the Steward will want to see at the Revels" when knows(actor, letter_known) once {
    Says "Tobias counts on long fingers. 'A Rest fit to hold Revels in: the Hall roofed, the dens fit for beasts, the Warm-House standing. Whatever of the Inventory a company can show: Jabez Orme has the Book. A masque: my great-aunt is very old-fashioned; she will want Virtues. And,' he swallows, 'the seal. The office cannot be given without the Household's seal on the warrant, and I had the seal on a ribbon round my neck when I went up to the Rest to measure the Hall, and I came down without it.' He touches the empty ribbon. 'If I tell her, she will strike me off the Household. There are only two of us. It would be a very small ceremony, and I should mind it very much.'".
    On discuss { Assert knows(actor, revels_wants). Assert knows(actor, seal_lost_known). }
  }
  Entity revels_wants: fact "For the Revels the Steward will want the King's Rest fit (the Hall roofed, the dens fit for beasts, the Warm-House standing), what of the Inventory a company can show, a masque with Virtues in it, and the Household's seal, which Tobias lost on the hill.".
  Entity seal_lost_known: fact "Tobias Quarrendon lost the Household's seal-ring up at the King's Rest.".
  Objective revels when knows(party, letter_known) and not revelsDone(wapshotts) "Help Wapshott's win the office of the Revels at the King's Rest, on the twelfth night after the letter: the Rest made fit, the Inventory shown, a masque, and the Household's seal found.".
  Objective seal when knows(party, seal_lost_known) and sealLost(tobias) and not revelsDone(wapshotts) "Find the Household's seal-ring, which Tobias lost up at the King's Rest.".

  // The last stand of the Revels round is up the hill, in the Long Court, instead of on the second town's field.
  Rule rest_round when letterCome(wapshotts) and pitched(wapshotts) and current(wapshotts, tober_a) and day(clock) + 5 >= revelsDay(wapshotts) and not restRound(wapshotts) {
    Retract nextGround(tober_a, tober_b). Assert nextGround(tober_a, tober_r). Assert restRound(wapshotts). }
  Rule rest_round_ends when restRound(wapshotts) and revelsDone(wapshotts) and nextGround(tober_a, tober_r) and current(wapshotts, tober_c) {
    Retract nextGround(tober_a, tober_r). Assert nextGround(tober_a, tober_b). }
  Rule wap_up_hill near wapshott when here(tober_r) and day(clock) == arrivedDay(wapshotts) and not upHillTold(wapshotts)
    says "The wagons come up the hill road one after another with the horses blowing, under the gatehouse arch and into the Long Court, and stop. The Colonel climbs down off the box and stands on the swept setts where two hundred royal wagons stood, and takes off his hat, and for once does not say anything at all. Jabez Orme, at the far end with his broom, takes off his." { Assert upHillTold(wapshotts). }
  Relation upHillTold(concern).

  // ── Sir Gervase Fenwick, and his money ───────────────────────────────────────────────────────────────────
  Person fenwick "Sir Gervase Fenwick" at tober_a {
    Role "a baronet and naturalist, of Coldharbour". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "A pink, plump, delighted man of fifty in a coat with forty pockets, every one of them bulging, is looking at a beetle on the back of his hand through a glass. 'Fenwick,' he says, without looking up. 'Gervase. Baronet, naturalist, member of four learned societies and expelled from a fifth. Look at this.' He shows you the beetle. 'Do you know what this is? Neither do I. Isn't it marvellous?' Then he looks at you, and you have the impression of being, briefly, also a beetle.".
    Greets again "'Ah!' says Sir Gervase, lowering his glass. 'My favourite specimen.' He means it kindly.".
  }
  Initially Assert offstage(fenwick).
  Relation fenwickCome(group). Relation fenwickSigned(concern). Relation clauseBeasts(concern). Relation clauseLeg(concern). Relation clauseHob(concern).
  Relation fenwickRefused(concern). Relation fundsFound(concern).
  Rule fenwick_comes when letterCome(wapshotts) and day(clock) >= letterDay(wapshotts) + 1 and hour(clock) >= 10 and pitched(wapshotts) and not fenwickCome(fenwick) {
    Assert fenwickCome(fenwick). Retract offstage(fenwick). Assert travels(fenwick). Assert post(fenwick, rk_tober). Assert clauseBeasts(wapshotts). Assert clauseLeg(wapshotts). Assert clauseHob(wapshotts). }
  Topic fenwick_offer with fenwick "Ask Sir Gervase what brings him to the circus" when fenwickCome(fenwick) once {
    Says "'The Menagerie Royal!' says Sir Gervase, as other men might say a woman's name. 'Three hundred years I have wanted to see the Inventory, and so did my father, and his. I heard of your tortoise. I came at once. I came in my carriage, which is to say very slowly, behind a horse who disapproves of me.' He leans in. 'Your Colonel needs money to make the Rest fit for Revels. I have money. I have nothing but money and beetles. A hundred coin, for the Rest, on a small contract.' He produces it from a pocket, folded small. 'Three clauses. Nothing at all. A first right to buy, should any beast of the Inventory ever be sold. The Leg of the Great Worm, and anything found with it, to my cabinet at Coldharbour. And an afternoon, only an afternoon, with your hob and a pair of calipers.' He beams. 'Science, you see. Science is very small print.'".
    On discuss { Assert knows(actor, fenwick_contract). }
  }
  Entity fenwick_contract: fact "Sir Gervase Fenwick offers a hundred coin for the restoration of the King's Rest, on three clauses: first right to buy any beast of the Inventory that is ever sold; the Leg of the Great Worm and anything found with it to his cabinet; and an afternoon with the hob and a pair of calipers.".
  Topic billie_fenwick with billie "Ask Billie what she makes of Sir Gervase's contract" when knows(actor, fenwick_contract) once {
    Says "Billie reads it standing up, with her lips pressed together. 'First right to buy,' she says. 'Means every beast we've got is for sale, and he's first in the queue.' She hands it back. 'And calipers for the hob. You put a pair of calipers near Ninepence and he'll sour every pail from here to the sea, and he'll be right.' She folds her arms. 'He's a nice man. He likes animals the way some men like clocks. If the Colonel signs that as it stands, he can keep his own menagerie.'".
    On discuss { Assert knows(actor, billie_will_quit). }
  }
  Entity billie_will_quit: fact "Billie Ostrander will give up the menagerie if the Colonel signs Sir Gervase's contract with its first clause, that any beast of the Inventory is his to buy first.".
  // Each clause may be struck by talk; or traded.
  Action strike_beasts(actor: group, site: place) "Talk Sir Gervase out of the first clause: no beast of the Inventory is for sale" {
    Speaker fenwick. Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(fenwick, site) and knows(actor, fenwick_contract) and clauseBeasts(wapshotts) and not fenwickSigned(wapshotts) and not triedBeasts(actor).
    Resolve check(actor, persuasion, dc_hard).
    On success { Retract clauseBeasts(wapshotts). }
    On failure { Assert triedBeasts(actor). }
    Result "You put it to him as one who loves a beast to another: that a beast with a price on it is a beast already half in a jar, and that he has never in his life wanted a thing that could be bought, only a thing that could be seen. Sir Gervase listens with his head on one side, like a thrush. Then he takes out a pencil and crosses the clause through, twice. 'You are quite right,' he says. 'I should only have been tempted.'".
    Otherwise "'But a first right is nothing,' says Sir Gervase kindly, 'unless you mean to sell. You don't mean to sell. So it costs you nothing.' The logic is perfect, and you can find nothing to say to it.".
  }
  Relation triedBeasts(group).
  Action strike_hob(actor: group, site: place) "Tell Sir Gervase what Ninepence would do to anyone who came at him with calipers" {
    Speaker fenwick. Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and at(fenwick, site) and knows(actor, fenwick_contract) and clauseHob(wapshotts) and not fenwickSigned(wapshotts).
    On success { Retract clauseHob(wapshotts). }
    Result "You tell him about the milk. All the milk, for ever, from here to the sea, and his own dairy at Coldharbour first. Sir Gervase goes a little pale under the pink. 'A sourcing hob,' he says, 'is very well attested in the literature.' He crosses the clause out. 'An afternoon's conversation,' he writes above it. 'If the hob consents.' He shows you. 'Will that do?'".
  }
  Action trade_leg(actor: group, site: place) "Promise Sir Gervase the first look at whatever is found in the marl-pit, in place of owning it" {
    Speaker fenwick. Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and at(fenwick, site) and knows(actor, fenwick_contract) and clauseLeg(wapshotts) and not fenwickSigned(wapshotts).
    On success { Retract clauseLeg(wapshotts). Assert promiseMade(first_look). }
    Result "'The first look,' says Sir Gervase. He thinks about it with his eyes shut. 'Before anyone. Before the Colonel.' He opens them. 'Done. A first look is worth more than a jar.' He crosses out the clause and writes over it, in a tiny hand: FIRST LOOK. Then he underlines it three times.".
  }
  Promise first_look "to give Sir Gervase the first look at whatever is found in the marl-pit" to fenwick
    kept when shownFenwick(party) "Sir Gervase writes in his notebook: kept."
    broken when clawGiven(party) and not shownFenwick(party) "Sir Gervase hears that the marl-pit gave something up, and that he was not sent for." { Decrease regard(fenwick) by 2 or to nothing. }.
  Relation shownFenwick(group). Relation clawGiven(group).
  // The Colonel signs, whatever is struck, three days after Sir Gervase comes, unless the money is found elsewhere.
  Rule colonel_signs when fenwickCome(fenwick) and day(clock) >= letterDay(wapshotts) + 4 and not fenwickSigned(wapshotts) and not fenwickRefused(wapshotts) and not fundsFound(wapshotts) {
    Assert fenwickSigned(wapshotts). Increase strongbox(wapshotts) by 100. }
  Rule colonel_signs_told near wapshott when fenwickSigned(wapshotts) and not signedTold(wapshotts)
    says "The Colonel signs Sir Gervase's contract on the cookhouse table with a flourish that takes the pen through the paper, and Sir Gervase counts a hundred coin into the strongbox in little gold piles, humming. Ada watches from the hatch with her hand flat on the ledger, as if it might get up and leave." { Assert signedTold(wapshotts). }
  Relation signedTold(concern).
  Rule billie_quits near billie when fenwickSigned(wapshotts) and clauseBeasts(wapshotts) and not billieQuit(billie)
    says "Billie Ostrander takes off her keeper's apron in the menagerie and hangs it on the tent-pole. 'Horses,' she says to the Colonel. 'I'll keep your horses. The rest you can keep for Sir Gervase.' She goes out to the horse lines and does not come back into the menagerie tent." {
    Assert billieQuit(billie). Assert post(billie, rk_yard). }
  Relation billieQuit(group).
  Rule hob_offended near wapshott when fenwickSigned(wapshotts) and clauseHob(wapshotts) and hobJoined(ninepence) and not hobOffended(ninepence)
    says "In the night every pail of milk in the circus turns, and the butter will not come, and the Colonel's hat is found full of whey. Ninepence has heard about the calipers." {
    Assert hobOffended(ninepence). }
  Relation hobOffended(group).
  Topic hob_calipers with ninepence "Tell Ninepence the calipers will never come near him" when hobOffended(ninepence) once {
    Says "'They'll not,' says Ninepence, 'because I'll not be here.' He is packing: his brush, a cup, a fulling-cloth coat. Then he stops, and looks at you, and sits on his bundle. 'You'd have struck it out if you could. I know. I watched you try.' He considers the milk. 'I'll stay to the Revels. For the Ox, and the clown's ladder. After that we'll see who measures what.'".
    On discuss { Retract hobOffended(ninepence). Assert hobStaysToRevels(ninepence). }
  }
  Relation hobStaysToRevels(group).
  // Other money: Cordelia's, if the companies are one; the fair town's, by subscription; Ada's own.
  Rule cordelia_refuses near sallow when merged(wapshotts) and fenwickCome(fenwick) and not fenwickSigned(wapshotts) and not fundsFound(wapshotts)
    says "Cordelia Sallow reads Sir Gervase's contract through once, standing, with her cane under her arm, and hands it back to him. 'No,' she says. 'We will pay for our own roof, Sir Gervase, out of our own box, and you may come and look at anything you like, for a ticket.' The Colonel opens his mouth. 'Florian,' she says. He shuts it." {
    Assert fundsFound(wapshotts). Assert fenwickRefused(wapshotts). Increase strongbox(wapshotts) by 40. }
  Topic keeper_a_subscribe with keeper_a "Ask {keeper_a} whether the fair town would subscribe to the circus's Revels" when knows(actor, letter_known) and knows(actor, fenwick_contract) and not fundsFound(wapshotts) and not fenwickSigned(wapshotts) once {
    Says "'For Wapshott's?' says {keeper_a}, and thinks about it, and looks at the wall where the old bill hangs. 'I'll put a box on the bar. The Clerk of the Fair will put in, for the honour of the town; he'll want a receipt. Leave it a day.'".
    On discuss { Assert subscribed(keeper_a). Set subscribedDay(keeper_a) to day(clock). }
  }
  Relation subscribed(group). Measure subscribedDay(group).
  Rule subscription_in near ada when subscribed(keeper_a) and day(clock) > subscribedDay(keeper_a) and not fundsFound(wapshotts) and not fenwickSigned(wapshotts) and standing(tober_a) >= 4
    says "Word comes up from {town_a}: the box on the bar at the inn holds thirty-two coin, a lock of hair, two buttons and a receipt from the Clerk of the Fair for five coin in his own hand. The fair town has subscribed to the Revels." {
    Assert fundsFound(wapshotts). Increase strongbox(wapshotts) by 32. Assert fenwickRefused(wapshotts). }
  Rule subscription_thin near ada when subscribed(keeper_a) and day(clock) > subscribedDay(keeper_a) and not fundsFound(wapshotts) and not fenwickSigned(wapshotts) and standing(tober_a) < 4 and not thinTold(keeper_a)
    says "Word comes up from {town_a}: the box on the bar at the inn holds eleven coin and a button. The fair town is fond of the circus, but not that fond." {
    Assert thinTold(keeper_a). Increase strongbox(wapshotts) by 11. }
  Relation thinTold(group).
  Topic tell_wap_refuse with wapshott "Tell the Colonel the money is found without Sir Gervase, and he need not sign" when fundsFound(wapshotts) and not fenwickSigned(wapshotts) and not merged(wapshotts) once {
    Says "The Colonel looks at the contract in his hand, and at you, and at the strongbox. 'Without the small print,' he says. 'I have never in my life been offered money without small print.' He gives the contract back to Sir Gervase with a bow. Sir Gervase takes it without the least offence. 'Then I shall come as a guest,' he says, 'and look at everything for nothing, which is better.'".
  }

  // ── Success is expensive: the Colonel's state coach ─────────────────────────────────────────────────────────
  Thing state_coach "a gilded state coach" at tober_a {
    State gilt "A state coach stands on the front of the big top, gilded from the wheels up, with WAPSHOTT'S on the door in letters of gold, a coachman's seat upholstered in crimson plush, and no horse in the circus able to pull it. Bucephalus has looked at it once and declined.".
  }
  Initially Assert offstage(state_coach). Relation coachOrdered(concern). Relation coachStopped(concern). Relation coachCome(concern).
  Rule coach_ordered when letterCome(wapshotts) and day(clock) >= letterDay(wapshotts) + 2 and not coachOrdered(wapshotts) { Assert coachOrdered(wapshotts). }
  Topic ada_coach with ada "Ask Ada why she is white to the bonnet" when coachOrdered(wapshotts) and not coachCome(wapshotts) and not coachStopped(wapshotts) once {
    Says "Ada holds out a bill without a word. A STATE COACH, GILDED, FOR THE ROYAL REVELS, WITH ARMORIAL DOORS. TWENTY-FIVE COIN ON DELIVERY. From a coachmaker in {town_a}, delivery in three days. 'He's ordered a coach,' she says. 'To arrive at a royal ruin. In. A coach. We have eleven wagons and a horse who won't pull a cart he doesn't like the look of.' She folds the bill very small. 'If anybody can talk him out of it, it isn't me. He thinks I don't understand grandeur.'".
    On discuss { Assert knows(actor, coach_known). }
  }
  Entity coach_known: fact "The Colonel has ordered a gilded state coach for the Revels, twenty-five coin on delivery in three days.".
  Action stop_coach(actor: group, site: place) "Talk the Colonel out of the gilded state coach" {
    Speaker wapshott. Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(wapshott, site) and knows(actor, coach_known) and not coachCome(wapshotts) and not coachStopped(wapshotts) and not triedCoach(actor).
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert coachStopped(wapshotts). Increase regard(ada) by 1. }
    On failure { Assert triedCoach(actor). }
    Result "You do not tell him it is extravagant; he knows. You tell him that the Progress came on foot and in wagons, and that the Steward has been waiting fifty years to see wagons, not a coach; that Jabez Orme has kept the court swept for wheels like theirs. The Colonel looks at his own wagons for a long time. Then he writes to the coachmaker, in capitals, CANCEL, and underneath, smaller, REGRETFULLY.".
    Otherwise "'But a coach,' says the Colonel, with tears in his eyes, 'is a STATEMENT.' You cannot think what of.".
  }
  Relation triedCoach(group).
  Rule coach_vetoed_cordelia near ada when coachOrdered(wapshotts) and not coachStopped(wapshotts) and not coachCome(wapshotts) and merged(wapshotts)
    says "Cordelia Sallow reads the coachmaker's bill at breakfast, writes CANCELLED across it in red, and sends it back by the carrier before the Colonel has finished his egg. When he finds out he goes into his wagon and does not come out until dinner, and then eats two helpings, and brings her a cup of tea." {
    Assert coachStopped(wapshotts). }
  Rule coach_vetoed near ada when coachOrdered(wapshotts) and not coachStopped(wapshotts) and not coachCome(wapshotts) and adaShared(ada)
    says "Ada, who holds a quarter-share now and the Colonel's own pen, has cancelled the Colonel's gilded coach by letter, without asking him, in a hand that does not shake. When he finds out he goes into his wagon and does not come out until dinner, and then eats two helpings." {
    Assert coachStopped(wapshotts). }
  Rule coach_comes when coachOrdered(wapshotts) and not coachStopped(wapshotts) and not coachCome(wapshotts) and day(clock) >= letterDay(wapshotts) + 5 and pitched(wapshotts) {
    Assert coachCome(wapshotts). Retract offstage(state_coach). Assert travels(state_coach). Assert post(state_coach, rk_tober). Decrease strongbox(wapshotts) by 25 or to nothing. }
}

data/goings-on/circus/rest.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── The King's Rest: the Household of the Progress's winter seat, on the hill above the second town ──────────
  // A ruin since the last Progress, three hundred years ago; swept every day since by a family of keepers nobody has
  // paid. It is there from the first day, for whoever asks about the walls on the hill; in Phase II it is where the
  // Revels are held, and the circus's last stand of that round is pitched in its Long Court.
  Entity rest_heard: fact "On the hill above {town_b} stand the walls of the King's Rest, where the old kings' Progress wintered, three hundred years ago; an old man called Jabez Orme still keeps it.".
  Initially Assert leadsTo(rest_heard, rest_gate).
  Topic keeper_b_rest with keeper_b "Ask {keeper_b} about the walls on the hill" when true once {
    Says "'The King's Rest,' says {keeper_b}. 'Where the old kings stopped, when they went round. Three hundred years since anybody stopped there but rooks.' {keeper_b} wipes a cup. 'Old Jabez Orme keeps it. Keeps it from what, nobody knows. He sweeps it. His father swept it, and his father's father, back to the last king. Comes down for bread on Saturdays and won't take it for nothing, pays in rooks' eggs.' A pause. 'Go up if you like. He'll be glad. He's always glad, which is the sad part.'".
    On discuss { Assert knows(actor, rest_heard). }
  }
  Place rest_gate "the gatehouse of the King's Rest" is room within town_b at 7, 0.
  Place gate_tower "the top of the gatehouse tower" is room within town_b at 7, 1.
  Place beast_yard "the Beast Yard" is room within town_b at 8, 0.
  Place warm_house "the Warm-House" is room within town_b at 9, 0 indoors.
  Place revels_hall "the Revels Hall" is room within town_b at 8, 2.
  Place keeper_lodge "the Keeper's Lodge" is room within town_b at 7, 2 indoors.
  Place rest_chapel "the chapel of the Rest" is room within town_b at 9, 2 indoors.
  Place tober_r "the Long Court of the King's Rest" is room within town_b at 8, 1.
  Place ring_r "the big top" is room within town_b at 9, 1 indoors.
  Place yard_r "the backyard of the circus" is room within town_b at 10, 1.
  Place wagons_r "the ring of living-wagons" is room within town_b at 10, 0.
  Place beasts_r "the menagerie tent" is room within town_b at 10, 2 indoors.
  Passage hill_road "the hill road to the King's Rest" is road between green_b and rest_gate taking 40 minutes hidden until rest_heard.
  Passage tower_stair "the broken gatehouse stair" is path between rest_gate and gate_tower taking 5 minutes needing climbing or rope.
  Passage gate_arch "the arch of the gatehouse" is arch between rest_gate and tober_r.
  Passage yard_arch "the archway to the Beast Yard" is arch between tober_r and beast_yard.
  Passage warm_door "the Warm-House door" is doorway between beast_yard and warm_house.
  Passage hall_door "the great door of the Revels Hall" is doorway between tober_r and revels_hall.
  Passage lodge_door "the lodge door" is door between rest_gate and keeper_lodge.
  Passage chapel_door "the chapel door" is door between tober_r and rest_chapel.
  Passage flap_r "the flap of the big top" is doorway between tober_r and ring_r opening when here(tober_r) and (not showOn(wapshotts) or admitted(party)).
  Passage back_r "the way round behind the big top" is path between tober_r and yard_r taking 2 minutes opening when here(tober_r).
  Passage wagon_steps_r "the gap between the wagons" is path between yard_r and wagons_r taking 1 minute opening when here(tober_r).
  Passage ring_curtain_r "the ring curtain" is doorway between ring_r and yard_r opening when here(tober_r).
  Passage beast_flap_r "the menagerie flap" is doorway between tober_r and beasts_r hidden until list_given opening when here(tober_r) and menagerieOpen(wapshotts).
  Initially Assert groundRoom(tober_r, rk_tober, tober_r). Initially Assert groundRoom(tober_r, rk_ring, ring_r).
  Initially Assert groundRoom(tober_r, rk_yard, yard_r). Initially Assert groundRoom(tober_r, rk_wagons, wagons_r).
  Initially Assert groundRoom(tober_r, rk_beasts, beasts_r).
  Initially Assert groundOf(tober_r, tober_r). Initially Assert groundOf(ring_r, tober_r). Initially Assert groundOf(yard_r, tober_r).
  Initially Assert groundOf(wagons_r, tober_r). Initially Assert groundOf(beasts_r, tober_r).
  Initially Assert greenOf(tober_r, green_b). Initially Assert roadOut(tober_r, road_bc). Initially Assert nextGround(tober_r, tober_c).
  Initially Assert billOf(tober_r, bill_b). Initially Assert sellsTo(tober_r, merchant_b). Initially Set standing(tober_r) to 3.

  Observe gate_scene at rest_gate when true "A gatehouse of grey stone, twice the height it needs to be, with a carved wheel over the arch, a crown over the wheel, and a rook's nest in the crown. The gates themselves went for firewood long ago. The arch is swept. Someone has swept it this morning.".
  Observe tower_scene at gate_tower when true "The top of the gatehouse tower, open to the sky, with a broken parapet and a view of the whole country: the road going down to {town_b}, the road going on, the long roof of the Revels Hall, the glitter of the Warm-House. In a corner of the parapet is a heap of sticks, wool, and things that shine.".
  Observe court_scene at tober_r when true "The Long Court: a yard of setts half a furlong long, between ranges of low stone sheds with their roofs gone, where two hundred wagons once stood in rows. Every sett is swept. Weeds grow only along the walls, where a broom cannot quite reach. At the far end a stone mounting-block with steps, worn to a dip in the middle by three hundred years of nobody.".
  Observe court_circus near pole when at(pole, tober_r) and here(tober_r) "In the middle of the Long Court, where nothing has stood for three hundred years, stands the big top of Wapshott's, its pennant snapping above the old sheds; the living-wagons are drawn up in a ring at the end where the royal wagons stood, and Bucephalus is drinking from a stone trough with a crown cut on it.".
  Observe yard_scene_r at beast_yard when true "The Beast Yard: a square of stone dens with iron-barred fronts, each with a name cut in the lintel, half of them unreadable. BISHOP. NEBUCHADNEZZAR. THE GLIMMER. THE TWO BEARS. SALAMANDERS (WARM-HOUSE). And one long den at the end, empty and enormous, with no name at all, and the bars bent outward.".
  Observe warm_scene at warm_house when true "A long glass-house over a warm spring, its iron ribs whole and most of its glass gone, so that it is warm underfoot and cold above. Steam lies on the water in the stone basin. Ferns grow here that grow nowhere else in the country, and on the hot stones round the basin, small red shapes lie very still, like coals that have learned to bask.".
  Observe hall_scene at revels_hall when true "The Revels Hall: a great room with a stage at one end and a gallery at the other, its roof timbers standing against the sky like the ribs of a boat. A painted cloud hangs over the stage on rusted chains, a cloud of wood and canvas big enough to carry four people, with a faded gilt sun behind it. Rain has been falling on the stage for three centuries; the boards are green.".
  Observe lodge_scene at keeper_lodge when true "One room, very clean: a bed, a table, a fire, a broom by the door, a row of six brooms worn to the stick on hooks along the wall, one for each Orme. On the table a great book in a box, and a coat of bottle-coloured velvet of a cut three hundred years old, brushed and folded.".
  Observe chapel_scene at rest_chapel when true "A little chapel with a crowned wheel in the east window, half its glass gone and the gaps filled with sacking. The benches are sound. Somebody has put a jar of primroses on the altar.".

  // ── Jabez Orme, Keeper of the King's Rest ───────────────────────────────────────────────────────────────────
  Person jabez "Jabez Orme" at keeper_lodge {
    Role "the hereditary Keeper of the King's Rest". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "A very old man, small and bent, with a broom in his hand and a face like a walnut that has been pleased about something for ninety years, puts the broom carefully against the wall and bows to you: a real bow, from the waist, the kind you have only read about. 'Jabez Orme,' he says, 'Keeper of the King's Rest, at your service. Is it the Progress? No. No, I can see it isn't.' He does not seem disappointed; he seems to have practised not being disappointed. 'Come in, come in. You're the first in a twelvemonth. Will you see the dens? Everybody likes the dens.'".
    Greets again "'You came back,' says Jabez Orme, delighted, as if this were the most remarkable thing that had happened in three hundred years, which it may be.".
  }
  Rule jabez_rounds when hour(clock) >= 7 and hour(clock) < 12 and not at(jabez, tober_r) and not jabezBusy(jabez) { Assert at(jabez, tober_r). }
  Rule jabez_home when (hour(clock) >= 12 or hour(clock) < 7) and not at(jabez, keeper_lodge) and not jabezBusy(jabez) { Assert at(jabez, keeper_lodge). }
  Relation jabezBusy(group).
  Observe jabez_sweeping near jabez when at(jabez, tober_r) and not here(tober_r) "Jabez Orme is sweeping the Long Court, sett by sett, working down from the gatehouse in a long patient line, as his father did and his father's father.".
  Topic jabez_why with jabez "Ask Jabez why he keeps the Rest" when true once {
    Says "'Because the Progress will come back,' says Jabez, simply. 'The last king said so, at the gate, in the year of the comet. My first father was standing where you're standing. The King said, Keep it, Orme, and we shall come again next spring. And he gave him a shilling.' He shows you, on a ribbon round his neck, a silver coin worn as thin as a fingernail. 'They didn't come next spring. Something happened in the city; a war, or a wedding. But the King said. So we've kept it.' He smiles. 'Somebody has to be ready. It would be a terrible thing if they came and found it dirty.'".
    On discuss { Increase regard(jabez) by 1. Assert knows(actor, jabez_shilling). }
  }
  Entity jabez_shilling: fact "The last king told Jabez Orme's ancestor at the gate of the King's Rest to keep it, for the Progress would come again next spring; six generations of Ormes have kept it since, unpaid, on the strength of a shilling.".
  Topic jabez_brooms with jabez "Ask Jabez about the six brooms on the wall" when true once {
    Says "'Fathers,' says Jabez. 'Mine and his and his. You sweep with a broom till it's worn to the stick, and then you hang it up and take a new one, and when you hang up your last one your son takes it down.' He looks at the hooks. 'There's a seventh hook. I put it up myself, when I was young.' He is quiet. 'I never married. There was a girl in {town_b} but she wanted to see the sea.' He picks up his broom. 'It'll want somebody. After.'".
    On discuss { Assert knows(actor, seventh_hook). }
  }
  Entity seventh_hook: fact "There is a seventh hook on the wall of the Keeper's Lodge for the next Orme's broom, and there is no next Orme.".

  // The Keepers' Book: the Menagerie Royal's last inventory, with three hundred years of notes in its margins.
  Thing keepers_book "the Keepers' Book" at keeper_lodge {
    State boxed "On the table, in a box of black oak, lies the Keepers' Book.".
    Tries looking.
  }
  Initially Assert state(keepers_book, boxed).
  Action read_book(actor: group, site: place) "Ask Jabez to show you the Keepers' Book" {
    Speaker jabez. Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(jabez, site) and at(keepers_book, site) and regard(jabez) >= 1 and not knows(actor, inventory_known).
    On success { Assert knows(actor, inventory_known). Increase regard(jabez) by 1. }
    Result "Jabez lifts the book out of its box with both hands, as you would lift a sleeping child, and opens it on the table. The first pages are in a clerk's hand, brown and spiky: THE INVENTORIE OF THE MENAGERIE ROYALL AS IT LAY AT THE KING'S REST AT THE LAST PROGRESSE. Then a list. THE BISHOP, a tortoise of the isle of Ascensioun, given to the King by the Admiral, and his Diett. A LION of Barbary, NEBUCHADNEZZAR, the third of that Name, and his Wiff. THE GLIMMER, a Fox of the Fennes that burneth colde. A HOBBE of the Kitchenne, in Service, not to be Thanked. Two BEARES of the Owle Kind, very savage. SALAMANDERS of the Warme-House, a dozen, not to be let grow colde. And at the last, in a different ink: THE LEGGE OF THE GREAT WORME, from the Marle at the third Towne, the rest of Him being still under the Field. In the margins, in six hands, three hundred years of notes, and Jabez knows every one by heart.".
  }
  Entity inventory_known: fact "The Keepers' Book lists the Menagerie Royal at the last Progress: the Bishop, a tortoise; a lion of Barbary, Nebuchadnezzar the third; the Glimmer, a fox of the fens that burns cold; a Hob of the Kitchen, in service; two bears of the owl kind; a dozen salamanders of the Warm-House; and the Leg of the Great Worm, from the marl at the third town, the rest of him still under the field.".
  Topic jabez_margins with jabez "Ask Jabez what the notes in the margins say" when knows(actor, inventory_known) once {
    Says "Jabez runs a finger down the margins. 'Here, my first father: THE BISHOP STRAYED AT THE THIRD TOWNE FORD ON THE LAST DAY. NOT FOUND. That was the morning they left. He was always slow.' His finger moves. 'Here, his son: THE GLIMMERS GONE BACK TO THE FENNE. Here: THE HOBBE GONE, NOBODY TO COOK FOR. Here, the bears: GONE OVER THE WALL IN THE GREAT FROST, and somebody's added, my grandfather, I think, THEIR GRANDCHILDREN IN THE ORCHARDS AT THE FAIR TOWNE, EATING BEES.' He laughs, a dry little laugh like a bird. 'And here, at the Leg, my great-grandfather, the only time any Orme ever wrote in red: DO NOT DIGGE. HE IS NOT DEAD ENOUGH.' Jabez closes the book. 'We never knew what he meant. Grandfather said it was a joke. He never laughed at it, though.'".
    On discuss { Assert knows(actor, margins_known). Assert knows(actor, marl_heard). }
  }
  Entity margins_known: fact "The Keepers' Book's margins say the Bishop strayed at the third town's ford on the last day of the last Progress; the Glimmer went back to the fen; the Hob left with nobody to cook for; the owl-bears went over the wall and their grandchildren eat bees in the fair town's orchards; and, in red, at the Leg of the Great Worm: DO NOT DIG. HE IS NOT DEAD ENOUGH.".
  // What the company already knows answers lines in the Book: Phase I's beasts, recognised.
  Topic jabez_bishop with jabez "Tell Jabez that Wapshott's has a great tortoise with a crowned wheel on his shell" when knows(actor, margins_known) and exhibit(methuselah) once {
    Says "Jabez sits down. He does not seem able to stand. 'The Bishop,' he says. 'The Bishop's alive.' He takes your hand in both his, and his hands are shaking. 'Three hundred years. Strayed at the ford. My first father went back for him and looked a week.' He stands up, and goes to the door, and looks down the hill toward {town_b}, as if the tortoise might be coming up it now, slowly. 'Would they bring him? Your people? Just to see the yard? He'd know it. They say a tortoise knows a place.'".
    On discuss { Assert knows(actor, bishop_identified). Increase regard(jabez) by 2. }
  }
  Entity bishop_identified: fact "Wapshott's giant tortoise is the Bishop of the Menagerie Royal, a tortoise of Ascension given to the King by the Admiral, who strayed at the third town's ford on the last day of the last Progress, three hundred years ago.".
  Topic jabez_bears with jabez "Tell Jabez about Bramble, the owlbear from the fair town's orchards" when knows(actor, margins_known) and (exhibit(bramble) or brambleLost(wapshotts)) once {
    Says "'Grandchildren of the two that went over the wall!' Jabez is delighted. 'Grandchildren of grandchildren. Eating bees, Grandfather said. He was right.' He finds the line and taps it. 'Two Beares of the Owle Kind, very savage. Is she very savage?' You tell him about the honey and the net and the face. He laughs till he has to hold the table. 'That's the Orme in her,' he says. 'We always fed them honey on feast days. It's in the Book.'".
  }

  // ── Old Tom, the raven of the Rest ─────────────────────────────────────────────────────────────────────────
  Species rest_raven "a great raven" like raven tame described "A raven the size of a cat, black with a sheen of purple, with a grey beard of feathers at his throat and a white feather in one wing. He has a voice like a creaking door and a vocabulary three hundred years old.".
  Person tom "Old Tom" at gate_tower {
    Role "the raven of the King's Rest". Species rest_raven. Peaceable. Pronouns he.
    Greets "The raven looks at you with one eye and says, distinctly, in an old man's voice: 'MAKE WAY. MAKE WAY FOR THE KING.' Then, in a different voice, younger: 'Tom! Supper!' Then he laughs, exactly like Jabez Orme.".
  }
  Rule tom_down when hour(clock) >= 7 and hour(clock) < 9 and not at(tom, tober_r) { Assert at(tom, tober_r). }
  Rule tom_up when (hour(clock) >= 9 or hour(clock) < 7) and not at(tom, gate_tower) { Assert at(tom, gate_tower). }
  Topic jabez_tom with jabez "Ask Jabez about the raven" when true once {
    Says "'Old Tom,' says Jabez. 'He was my grandfather's. Eighty-one years old, which is old for a raven but he doesn't know it. He talks. Ravens of the Rest always talked; there's been a raven at the gate since the Progress, father to son, like us.' He lowers his voice. 'He steals. Anything that shines. He's a hoard on the gatehouse top you could buy a farm with, if it weren't mostly buttons. You can't climb to it without a rope, and he'll not come down for anybody but me, at supper, when I call him the old way.' Jabez cups his hands and calls, in a high thin voice: 'Tom! Supper!' On the gatehouse a raven laughs, exactly like him.".
    On discuss { Assert knows(actor, tom_call). }
  }
  Entity tom_call: fact "Old Tom the raven comes down only to Jabez's old call, 'Tom! Supper!', at supper; his hoard of shining things is on the gatehouse top, which wants a rope to climb to.".
  Observe hoard_scene near tom when at(tom, gate_tower) and at(party, gate_tower) "Old Tom sits on the edge of his hoard, which is enormous: buttons, buckles, a spoon, a bishop's ring, a child's whistle, three thimbles, a brass doorknob, a piece of a mirror, and, on top, catching the light, a heavy gold seal-ring with a crowned wheel cut in it.".
  Kind progress_seal_kind "the Steward's seal-ring" is gear worth 20 weighing 0
    described "A heavy gold ring with a flat bezel cut in reverse: a crowned wheel, and round it, HOUSEHOLD OF THE PROGRESSE. It is very old, and much too large for anybody now living.".
  Item seal_ring "the Steward's seal-ring" is progress_seal_kind at gate_tower hidden until seal_seen.
  Discovery seal_seen "On top of Old Tom's hoard on the gatehouse tower lies a gold seal-ring with a crowned wheel." { Known by jabez. }
  Rule seal_noticed when at(party, gate_tower) and sealLost(tobias) and not knows(party, seal_seen) says "On top of the raven's hoard, catching the light, lies a heavy gold seal-ring with a crowned wheel cut in it." teaches seal_seen { }
  Relation sealLost(group). Relation sealBack(group).
  Action take_seal(actor: group, site: place) "Take the seal-ring off the raven's hoard while he is watching" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(seal_ring, site) and at(tom, site) and knows(actor, seal_seen).
    Resolve check(actor, stealth, dc_hard).
    On success { Give seal_ring to actor. }
    On failure { Assert strikes(raven_beak, party). }
    Result "You wait until he turns his head to look at a rook, and have it, and he turns back and sees the gap in his hoard and screams at you in four voices, one of them a bishop's.".
    Otherwise "Your hand is an inch from the ring when Old Tom drives his beak into the back of it like a cobbler's awl, and says, in Jabez's voice, 'Now then.'".
  }
  Hazard raven_beak "A raven's beak" means "Deal (1d3) physical damage to ally.".
  Action trade_spangles(actor: group, site: place) "Spread Hench's spare spangles on the parapet for Old Tom, and take the ring while he chooses" {
    Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and at(seal_ring, site) and at(tom, site) and spangles(actor).
    On success { Give seal_ring to actor. Retract spangles(actor). Increase regard(tom) by 1. }
    Result "You lay the spangles out on the parapet in a little galaxy, silver and gold and one green one, and Old Tom forgets the world. He goes along them one at a time, turning each over with his beak, saying 'Ah,' in Hench's voice, which he cannot possibly have heard; and you lift the ring off his hoard and he does not even look round.".
  }
  Relation spangles(group).
  Topic hench_spangles with hench "Ask Hench for a handful of spare spangles" when knows(actor, seal_seen) and not spangles(actor) once {
    Says "Hench looks at you over his pins. 'For a raven,' he says. 'Naturally. Everything I sew in this circus is for an animal.' He tips a saucerful into a twist of paper: silver, gold, and one green, which he looks at a moment. 'The green is from the Margravine's ball gown. Give it to him last. He should have one good thing.'".
    On discuss { Assert spangles(actor). }
  }
  Action call_tom(actor: group, site: place) "Cup your hands and call Old Tom down in Jabez's voice: 'Tom! Supper!'" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, rest_gate) and knows(actor, tom_call) and knows(actor, seal_seen) and at(seal_ring, gate_tower) and echoLearned(actor).
    Resolve check(actor, performance, dc_easy).
    On success { Give seal_ring to actor. }
    Result "You cup your hands and call, high and thin, the way Jabez calls, and it is Jabez's voice that comes out, near enough to fool a raven of eighty-one. Old Tom comes down off the gatehouse in a long black slant and lands on your shoulder, and puts into your ear, as a present, the thing he likes best in the world, which is a heavy gold ring. Then he waits for supper. You owe him supper.".
    Otherwise "You call, and it is your voice, not Jabez's, and on the gatehouse top Old Tom says, in your voice, exactly, 'Tom! Supper!' and laughs at you.".
  }
  Action climb_tower(actor: group, site: place) "Climb the broken gatehouse stair to the raven's hoard" {
    Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, rest_gate) and not at(actor, gate_tower) and not capable(actor, climbing).
    Resolve check(actor, climbing, dc_hard).
    On success { Assert at(actor, gate_tower). }
    Result "You go up what is left of the gatehouse stair by its broken edges, with the wind in your ears and three hundred years of rook-droppings under your hands, and come out at the top among the sky.".
    Otherwise "Halfway up the broken stair a step goes from under your foot and you come down in a slither of stone and rook-nest, bruised, with Old Tom laughing above you.".
  }
  Action climb_down_tower(actor: group, site: place) "Climb back down the broken gatehouse stair" {
    Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gate_tower) and not capable(actor, climbing).
    On success { Assert at(actor, rest_gate). }
    Result "You come down the broken stair the slow way, facing the wall, a hand and a foot at a time, with Old Tom leaning over the parapet above you making remarks in three voices.".
  }
  Event seal_home near tobias when keeps(tobias, seal_ring) "Tobias Quarrendon takes the ring as if it were his great-aunt's heart, and kisses it, and puts it on his thumb, where it fits. 'She would have struck me off the Household,' he says. 'There are only two of us. It would have been a very small ceremony.'" then {
    Assert sealBack(tobias). Retract sealLost(tobias). Increase regard(tobias) by 2. }

  // ── The salamanders of the Warm-House ─────────────────────────────────────────────────────────────────────
  Species rest_salamander "a salamander" like lizard tame described "A lizard the length of a hand, coal-red and shining as if wet, with a crest like a cock's comb and eyes like drops of honey. It is hot to stand near. When frightened it glows brighter, and whatever dry thing it is lying on begins to smoke.".
  Person salamanders "the salamanders" at warm_house {
    Role "a dozen fire-lizards on the warm stones". Species rest_salamander. Numbers 12. Peaceable. Pronouns they.
    Greets "A dozen salamanders lift their heads together from the hot stones and look at you with honey-coloured eyes, and one of them, the largest, glows a little brighter, and the fern beside it begins to steam.".
  }
  Topic jabez_salamanders with jabez "Ask Jabez about the red lizards in the Warm-House" when true once {
    Says "'The salamanders! Twelve of them in the Book, and there's twelve now, give or take. They came with the Admiral, with the Bishop, from somewhere very hot.' He beams. 'They live on the warm stones by the spring, and eat beetles, and they'll set fire to anything dry if they're frighted or cold. My father lost three hats.' He sobers. 'The glass is going. Every winter more of it. When it's all gone the spring won't keep them warm enough, and they'll go into the straw of the sheds to get warm, and,' he spreads his hands, 'the Rest will burn down. It'll be the most exciting thing that's ever happened here, and the last.'".
    On discuss { Assert knows(actor, salamander_ways). }
  }
  Entity salamander_ways: fact "The salamanders of the Warm-House set anything dry alight if they are frightened or cold; the glass of the Warm-House is going, and when it is gone they will go into the straw of the sheds for warmth and burn the Rest down.".
  Relation warmGlazed(concern). Relation salamanderTaken(concern). Relation brazierCage(group). Measure glazeCost(concern).
  Topic billie_salamanders with billie "Ask Billie what she makes of the salamanders" when knows(actor, salamander_ways) once {
    Says "Billie has been to look. 'They belong in that glass-house,' she says. 'It's the only place in the country hot enough for them, and it's falling down. Mend the glass and they'll be there in a hundred years.' She is quiet. 'Take one on the road and you'll want a brazier going under it day and night, in an iron cage, and somebody awake to feed it coal. Let it go cold in a straw tent and you'll have no tent.' She looks at you. 'I'd mend the glass. But I'm not the one wanting a show.'".
  }
  Action glaze_warm(actor: group, site: place) "Pay a glazier from {town_b} to mend the Warm-House, eight coin" {
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, warm_house) and knows(actor, salamander_ways) and quantity(actor, gold) >= 8 and not warmGlazed(wapshotts).
    On success { Decrease quantity(actor, gold) by 8. Assert warmGlazed(wapshotts). Increase regard(billie) by 1. Increase regard(jabez) by 2. }
    Result "The glazier comes up from {town_b} with a boy and a handcart of glass, and stands looking at the iron ribs for a long while with his mouth open, and then works till dark. By evening the Warm-House holds its heat again; the steam lies thick on the basin, and on the stones the salamanders have gone from dull red to a bright and comfortable orange, like a grate that has just been made up.".
  }
  Topic lusk_brazier with lusk "Ask Lusk to make an iron cage with a brazier under it, for a salamander" when knows(actor, salamander_ways) and not brazierCage(actor) once {
    Says "Lusk looks at you for a while. 'Fire,' he says. 'In a tent.' Then: 'Old grate from the cookhouse. Bars from the cage-wagon offcuts. Tray of sand.' He goes off to do it. When he comes back with it he says: 'Somebody feeds it coal. Every night. Or.' He does not finish.".
    On discuss { Assert brazierCage(actor). }
  }
  Action take_salamander(actor: group, site: place) "Coax the biggest salamander onto a hot stone and carry it in Lusk's iron brazier-cage" {
    Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, warm_house) and brazierCage(actor) and not salamanderTaken(wapshotts) and menagerieOpen(wapshotts).
    Resolve check(actor, woodcraft, dc_fair).
    On success { Assert salamanderTaken(wapshotts). Increase draw(wapshotts) by 2. Increase exhibits(wapshotts) by 1. }
    Result "You lift a flat stone off the basin's edge with tongs, hot enough to hiss in the steam, and set it in the brazier-cage, and wait; and the biggest salamander considers it, and you, and walks onto it as if it were a throne, and settles, and glows a contented orange through the bars.".
    Otherwise "The salamander does not want to go. It glows white, and the fern under it bursts into flame, and you drop the tongs.".
  }
  Observe salamander_shown near beastpost when salamanderTaken(wapshotts) and at(beastpost, ?r) "In an iron cage on a tray of sand, over a brazier of coals, a salamander the length of a hand lies on a flat stone and glows like a coal in a grate. A board says: THE SALAMANDER OF THE KING'S REST. HOTTER THAN IT LOOKS. DO NOT BLOW ON IT.".
  // A salamander gone cold on a night with no coal sets the straw alight.
  Rule salamander_cold when salamanderTaken(wapshotts) and feed(wapshotts) < 1 and hour(clock) == 2 and pitched(wapshotts) and not strawFire(wapshotts) {
    Assert strawFire(wapshotts). Decrease welfare(wapshotts) by 2 or to nothing. Decrease strongbox(wapshotts) by 4 or to nothing. }
  Relation strawFire(concern).
  Rule straw_fire_told near beastpost when strawFire(wapshotts) and not strawFireTold(wapshotts) says "In the small hours the menagerie is full of smoke: the salamander's brazier has gone out, and the salamander, cold, has climbed down into the straw to get warm, and the straw has done what straw does. Billie has it out with two buckets before it reaches the canvas; but the tent is scorched black on one side, and every beast in it is shaking." { Assert strawFireTold(wapshotts). }
  Relation strawFireTold(concern).
  Rule straw_fire_reset when strawFire(wapshotts) and hour(clock) == 12 { Retract strawFire(wapshotts). Retract strawFireTold(wapshotts). }

  // ── The Bishop goes home ─────────────────────────────────────────────────────────────────────────────────
  // Whose tortoise is he? Once the Household knows him, it may claim him; the company may give him back (and so,
  // if the Warrant comes, keep him after all), sell him to Fenwick, or ask the Colonel to keep him.
  Relation bishopHome(group). Relation bishopSold(group). Relation bishopKept(group).
  Topic tobias_bishop with tobias "Tell Tobias that the tortoise in the menagerie is the Bishop of the Inventory" when knows(actor, bishop_identified) and exhibit(methuselah) and not bishopHome(methuselah) and not bishopSold(methuselah) once {
    Says "Tobias goes to the menagerie and kneels in the straw, in his good coat, and reads the shell with his finger as Hench did, and his lips move. 'He is the Crown's,' he says at last, unhappily. 'I mean, legally. He is the property of the Household, strayed, never sold, never given. My great-aunt will have to claim him. She will hate it; she hates claiming things.' He looks up at you. 'Unless the Colonel gives him back. Then it is a gift, not a claim, and gifts are recorded in the Book in red.'".
    On discuss { Assert knows(actor, bishop_claim). }
  }
  Entity bishop_claim: fact "Tobias says the Bishop is the Household's by law: strayed, never sold. The Steward must claim him, unless the Colonel gives him back as a gift.".
  Topic wap_bishop with wapshott "Put it to the Colonel that the Bishop should be given back to the Household" when knows(actor, bishop_claim) and not bishopHome(methuselah) and not bishopSold(methuselah) once {
    Says "The Colonel's face goes through several provinces. 'Give him BACK,' he says. 'My Tortoise of Antiquity. My second-best attraction.' He walks to the menagerie flap and looks at the tortoise eating a cabbage, and something happens to him that you have seen happen to him once before, at the lion. 'He has been walking home for three hundred years,' he says, quite quietly. 'At a cabbage an hour.' Then, in his own voice, enormous: 'Of COURSE we shall give him back. In PERSON. With the BAND. Fipps! We need a processional!'".
    On discuss { Assert bishopHome(methuselah). Increase regard(wapshott) by 1. Increase regard(jabez) by 3. Increase regard(tobias) by 2. }
  }
  Topic fenwick_bishop with fenwick "Sell the tortoise to Sir Gervase for forty coin" when knows(actor, bishop_identified) and exhibit(methuselah) and not bishopHome(methuselah) and not bishopSold(methuselah) once {
    Grave "A tortoise sold is gone with his buyer; the Household will remember it.".
    Says "Sir Gervase counts out forty coin with the delight of a boy buying a kite. 'The Bishop!' he says. 'The actual Bishop! He shall have a heated pen at Coldharbour and a man to measure him daily.' He shakes your hand. In the menagerie, Billie turns her back. Tobias Quarrendon writes something in a small book, and does not look at you either.".
    On discuss { Assert bishopSold(methuselah). Increase strongbox(wapshotts) by 40. Retract exhibit(methuselah). Assert offstage(methuselah). Decrease exhibits(wapshotts) by 1 or to nothing. Decrease draw(wapshotts) by 2 or to nothing. Decrease regard(billie) by 3 or to nothing. Decrease regard(tobias) by 2 or to nothing. }
  }
  Rule bishop_walks_home near methuselah when bishopHome(methuselah) and here(tober_r) and at(methuselah, ?b) and groundOf(?b, tober_r) and not bishopAtRest(methuselah)
    says "The procession goes out of the menagerie and across the Long Court at the pace of a tortoise, which is to say for most of an hour: Fipps and the band playing a processional he wrote last night on the back of a playbill, Bucephalus with a plume, the Colonel bareheaded, and the Bishop walking toward a cabbage that Jabez Orme is holding out at the Beast Yard arch, in his ancestors' green velvet coat, crying without trying to stop. At the den with BISHOP cut over it, the tortoise stops, and lifts his old head, and looks at the stone for a long time, and goes in." {
    Assert bishopAtRest(methuselah). Retract travels(methuselah). Assert at(methuselah, beast_yard). }
  Relation bishopAtRest(group).
  Observe bishop_in_yard near methuselah when bishopAtRest(methuselah) "In the den with BISHOP cut over it, on fresh straw, the old tortoise is eating a cabbage at the pace of the hour hand, at home.".
}

data/goings-on/circus/revels.kyr:
Module circus "Wapshott's Peregrine Circus" {
  // ── The Revels at the King's Rest ──────────────────────────────────────────────────────────────────────────
  // On the twelfth night after the letter, in the Revels Hall. The court comes at five; the masques begin at seven,
  // a part every twenty minutes: the court seated; Pell's masque; Sallow's offering (if she is a rival); Wapshott's
  // Triumph of Wonder, made of whatever the company has made possible; a mishap, which waits for someone to do
  // something; the Dowager's laugh, or not; and the Steward's verdict at the end.
  Measure masque(concern). Measure masqueAt(concern). Measure revelsScore(concern). Measure pellScore(concern). Measure sallowScore(concern).
  Relation mishapOn(concern). Relation mishapDone(concern). Relation masqueTold(entity).
  Relation hallRoofed(concern). Relation densFit(concern). Relation cloudMended(concern).
  Relation warrantOurs(concern). Relation warrantFenwick(concern). Relation warrantPell(concern). Relation warrantSallow(concern).
  Query rivalSallow() means not merged(wapshotts).
  Chapter ch_revels "The Revels" when courtCome(wapshotts) and within(party, town_b) "Lamps in every empty window of the King's Rest for the first time in three hundred years. Carriages on the hill road, and a sedan chair with four men sweating under it, and the whole of {town_b} walking up behind in its Sunday clothes to stand in the Long Court and look. At the gatehouse, in a green velvet coat three centuries out of fashion, Jabez Orme bows to everyone, including a dog.".
  Chapter ch_after "After the Revels" when revelsDone(wapshotts) and onRoad(wapshotts) "The wagons go down the hill road at six in the old order, Bucephalus first; and whatever was given or not given in the Revels Hall last night, the circus does what it has always done. It goes on round. Only, it is a little different now, and everyone in it knows how.".

  Person steward "Dame Honorine Quarrendon" at tober_a {
    Role "the Steward of the Household of the Progress". Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Greets "A very small, very old woman in black silk with a white lace cap and a staff of office as tall as herself, topped with a little gilt wheel, looks at you with eyes like a hawk's. 'Quarrendon,' she says. 'Steward. Fifty-one years. This is the first time I have had anything to steward, and I find I am enjoying it a great deal more than is proper.' She taps the staff on the setts. 'You will be the person who found my great-nephew's ring. Or the person who did not. I have not yet decided which.'".
  }
  Person dowager "Her Serene Highness the Dowager Archduchess Ottilie" at tober_a {
    Role "who is also a Margravine and a Princess of the Progress". Ancestry human. Peaceable. Pronouns she. Manner proud.
    Greets "A large old lady upholstered in purple, with a face like a pleased bulldog and a great many pearls, extends a hand to you: the left, which Hench says means today she is a Margravine. 'Well,' she says. 'A person from the circus. Do they really have a lion? I was promised a lion. I was promised a lion at my first wedding and it was a dog in a mane.'".
  }
  Initially Assert offstage(steward). Initially Assert offstage(dowager).
  Rule court_comes when letterCome(wapshotts) and day(clock) == revelsDay(wapshotts) and hour(clock) >= 17 and not courtCome(wapshotts) {
    Assert courtCome(wapshotts). Retract offstage(steward). Retract offstage(dowager). Assert at(steward, revels_hall). Assert at(dowager, revels_hall).
    Retract offstage(fenwick). Assert at(fenwick, revels_hall). Assert away(fenwick). Assert at(jabez, revels_hall). Assert jabezBusy(jabez). }
  Relation courtCome(concern).
  Rule sallow_comes when courtCome(wapshotts) and rivalSallow() and offstage(sallow) and not sallowAtRevels(sallow) {
    Assert sallowAtRevels(sallow). Retract offstage(sallow). Assert at(sallow, revels_hall). }
  Relation sallowAtRevels(group).
  Rule lion_with_sallow when courtCome(wapshotts) and rivalSallow() and offstage(neb) and not lionLent(neb) { Retract offstage(neb). Assert at(neb, revels_hall). }
  Rule lion_with_us when courtCome(wapshotts) and rivalSallow() and offstage(neb) and lionLent(neb) { Retract offstage(neb). Assert at(neb, revels_hall). Assert lionHere(neb). }
  Rule pruett_to_revels when courtCome(wapshotts) and reunited(pruett) and not at(pruett, revels_hall) and not revelsDone(wapshotts) { Assert at(pruett, revels_hall). }
  Rule nell_to_revels when courtCome(wapshotts) and nellTold(nell) and not at(nell, revels_hall) and not revelsDone(wapshotts) { Assert at(nell, revels_hall). }
  // The circus's own show does not play on the Revels night; the company goes into the Hall.
  Rule revels_begin when courtCome(wapshotts) and hour(clock) >= 19 and not revelsOn(wapshotts) and not revelsDone(wapshotts) {
    Assert revelsOn(wapshotts). Set masque(wapshotts) to 1. Set masqueAt(wapshotts) to watch(clock). Set revelsScore(wapshotts) to 0.
    Set pellScore(wapshotts) to 9. Set sallowScore(wapshotts) to 8. }
  Rule troupe_to_hall when revelsOn(wapshotts) and performer(?p) and not at(?p, revels_hall) and not away(?p) and not travelsWith(?p, party) { Assert at(?p, revels_hall). }
  Relation revelsGoer(group).
  Initially Assert revelsGoer(ada). Initially Assert revelsGoer(hench). Initially Assert revelsGoer(billie). Initially Assert revelsGoer(lusk).
  Initially Assert revelsGoer(nance). Initially Assert revelsGoer(quirk). Initially Assert revelsGoer(tobias).
  Rule company_to_hall when revelsOn(wapshotts) and revelsGoer(?p) and not offstage(?p) and not at(?p, revels_hall) and not away(?p) and not travelsWith(?p, party) { Assert at(?p, revels_hall). }
  Rule masque_next when revelsOn(wapshotts) and watch(clock) >= masqueAt(wapshotts) + 2 and masque(wapshotts) < 7 and not (mishapOn(wapshotts) and not mishapDone(wapshotts)) {
    Increase masque(wapshotts) by 1. Set masqueAt(wapshotts) to watch(clock). }

  // ── The restoration: what the Rest needs to be fit for Revels ─────────────────────────────────────────────
  Topic lusk_hall with lusk "Ask Lusk to roof the Revels Hall with canvas" when knows(actor, revels_wants) and not hallRoofed(wapshotts) once {
    Says "Lusk goes up the hill on the dead afternoon with four of his lads and stands in the Revels Hall looking up at the ribs of the roof for a long time. 'Old side-wall,' he says. 'The black. And the spare from the cookhouse fly.' He looks at you. 'Canvas won't come back off. Not whole. The big top'll be thinner for it.' Then, because you are still there: 'Worth it.' By dark the Revels Hall has a roof of patched black canvas laced to its old timbers, and the rain, for the first time in three hundred years, has nowhere to fall.".
    On discuss { Assert hallRoofed(wapshotts). Decrease canvas(wapshotts) by 1 or to nothing. Increase regard(lusk) by 1. }
  }
  Rule fenwick_roofs near jabez when fenwickSigned(wapshotts) and not hallRoofed(wapshotts) and day(clock) >= letterDay(wapshotts) + 6
    says "Word comes down the hill: Sir Gervase's slaters from {town_b} have roofed the Revels Hall with real slate, in four days, at his expense, and are now complaining about the raven." {
    Assert hallRoofed(wapshotts). }
  Rule fenwick_glazes when fenwickSigned(wapshotts) and not warmGlazed(wapshotts) and day(clock) >= letterDay(wapshotts) + 7 { Assert warmGlazed(wapshotts). }
