data/voice/address.json:
{
  "about": "Someone is spoken to: how they take it, by whether they have spoken with the company before (moment first or again), who the company is to them (bond), their manner, and the hour. Said once, when the company turns its attention to them; what can be put to them follows. Someone with a temper of their own (wary, territorial, defensive, as a place's dwellers are) takes it in that temper, whoever they are to the company. Someone fretting, grieving or angry (as what they are doing says: Odile pacing the terrace) takes it as they are, whatever their manner.",
  "kinds": [
    "address"
  ],
  "lines": [
    {
      "id": "address.first.many",
      "when": {
        "moment": "first",
        "number": "many"
      },
      "text": "{Actor} [break|breaks] off talking among themselves to hear what you want."
    },
    {
      "id": "address.again.many",
      "when": {
        "moment": "again",
        "number": "many"
      },
      "text": "{Actor} [make|makes] room for you without being asked."
    },
    {
      "id": "address.first.1",
      "when": {
        "moment": "first"
      },
      "text": "{Actor} looks up, and takes a moment to place you, and fails. ‘Yes?’"
    },
    {
      "id": "address.first.2",
      "when": {
        "moment": "first"
      },
      "text": "{Actor} straightens, and wipes {their} hands, and waits to hear what you want."
    },
    {
      "id": "address.first.3",
      "when": {
        "moment": "first"
      },
      "text": "‘You’re not from here,’ [say|says] {actor}. It is not a question, and not quite unfriendly."
    },
    {
      "id": "address.first.4",
      "when": {
        "moment": "first"
      },
      "text": "{Actor} gives you the look people keep for strangers who have stopped walking. ‘Can I help you?’"
    },
    {
      "id": "address.again.1",
      "when": {
        "moment": "again"
      },
      "text": "‘You again,’ [say|says] {actor}, and it seems to be all right."
    },
    {
      "id": "address.again.2",
      "when": {
        "moment": "again"
      },
      "text": "{Actor} nods to you as to someone {they} [have|has] spoken to before."
    },
    {
      "id": "address.again.3",
      "when": {
        "moment": "again"
      },
      "text": "{Actor} sees you coming and leaves off what {they} [were|was] doing."
    },
    {
      "id": "address.first.night",
      "when": {
        "moment": "first",
        "time": "night"
      },
      "text": "{Actor} peers at you in the bad light. ‘It’s late to be making acquaintances.’"
    },
    {
      "id": "address.first.morning",
      "when": {
        "moment": "first",
        "time": "morning"
      },
      "text": "‘Morning,’ [say|says] {actor}, the way people say it before they have decided about you."
    },
    {
      "id": "address.again.night",
      "when": {
        "moment": "again",
        "time": "night"
      },
      "text": "‘Still about?’ [say|says] {actor}. ‘You’ll want your bed, like the rest of us.’"
    },
    {
      "id": "address.first.cheerful",
      "when": {
        "moment": "first",
        "manner": "cheerful"
      },
      "text": "‘Well now,’ [say|says] {actor}, brightening at the sight of a new face. ‘What brings you?’"
    },
    {
      "id": "address.first.cheerful.2",
      "when": {
        "moment": "first",
        "manner": "cheerful"
      },
      "text": "{Actor} grins before you have said anything at all. ‘You look like a person with a question.’"
    },
    {
      "id": "address.first.cheerful.4",
      "when": {
        "moment": "first",
        "manner": "cheerful"
      },
      "text": "{Actor} looks up and smiles as if you were the best thing to happen all morning. ‘Hello! What can I do?’"
    },
    {
      "id": "address.first.cheerful.5",
      "when": {
        "moment": "first",
        "manner": "cheerful"
      },
      "text": "‘A stranger!’ [say|says] {actor}, pleased. ‘Sit, if you like. Ask, if you like.’"
    },
    {
      "id": "address.again.cheerful",
      "when": {
        "moment": "again",
        "manner": "cheerful"
      },
      "text": "‘There you are!’ [say|says] {actor}, as if {they} had been expecting you."
    },
    {
      "id": "address.again.cheerful.3",
      "when": {
        "moment": "again",
        "manner": "cheerful"
      },
      "text": "‘Back again!’ [say|says] {actor}. ‘I hoped you would be.’"
    },
    {
      "id": "address.first.grim",
      "when": {
        "moment": "first",
        "manner": "grim"
      },
      "text": "{Actor} looks at you for longer than is comfortable. ‘Well?’"
    },
    {
      "id": "address.first.grim.2",
      "when": {
        "moment": "first",
        "manner": "grim"
      },
      "text": "{Actor} does not look up. ‘Say it, then.’"
    },
    {
      "id": "address.first.grim.4",
      "when": {
        "moment": "first",
        "manner": "grim"
      },
      "text": "{Actor} waits for you to speak, and does nothing to help."
    },
    {
      "id": "address.first.grim.5",
      "when": {
        "moment": "first",
        "manner": "grim"
      },
      "text": "‘If it’s trouble,’ [say|says] {actor}, ‘I have enough of my own.’"
    },
    {
      "id": "address.first.grim.6",
      "when": {
        "moment": "first",
        "manner": "grim"
      },
      "text": "{Actor} looks you over, and does not seem to like what {they} [see|sees] any better than anything else."
    },
    {
      "id": "address.again.grim",
      "when": {
        "moment": "again",
        "manner": "grim"
      },
      "text": "‘You,’ [say|says] {actor}, neither pleased nor otherwise."
    },
    {
      "id": "address.again.grim.3",
      "when": {
        "moment": "again",
        "manner": "grim"
      },
      "text": "{Actor} nods once, and goes back to what {they} [were|was] doing until you speak."
    },
    {
      "id": "address.first.stoic",
      "when": {
        "moment": "first",
        "manner": "stoic"
      },
      "text": "{Actor} looks up, and puts {their} hands still, and waits for you to say what you want."
    },
    {
      "id": "address.first.stoic.3",
      "when": {
        "moment": "first",
        "manner": "stoic"
      },
      "text": "{Actor} hears you come, and finishes what {they} [were|was] doing before {they} [look|looks] round."
    },
    {
      "id": "address.first.stoic.4",
      "when": {
        "moment": "first",
        "manner": "stoic"
      },
      "text": "{Actor} nods to you, and says nothing until you do."
    },
    {
      "id": "address.first.stoic.5",
      "when": {
        "moment": "first",
        "manner": "stoic"
      },
      "text": "‘Yes?’ [say|says] {actor}, without hurry."
    },
    {
      "id": "address.again.stoic",
      "when": {
        "moment": "again",
        "manner": "stoic"
      },
      "text": "{Actor} inclines {their} head, which seems to be a whole greeting."
    },
    {
      "id": "address.again.stoic.3",
      "when": {
        "moment": "again",
        "manner": "stoic"
      },
      "text": "‘Again,’ [say|says] {actor}, as a thing noted, not a complaint."
    },
    {
      "id": "address.first.jovial",
      "when": {
        "moment": "first",
        "manner": "jovial"
      },
      "text": "‘Now then!’ [say|says] {actor}, loud enough for anyone near to hear. ‘A new face. What can I do for you?’"
    },
    {
      "id": "address.first.jovial.3",
      "when": {
        "moment": "first",
        "manner": "jovial"
      },
      "text": "‘Come in, come in, whoever you are,’ [say|says] {actor}. ‘Everybody else has.’"
    },
    {
      "id": "address.first.jovial.4",
      "when": {
        "moment": "first",
        "manner": "jovial"
      },
      "text": "{Actor} slaps the nearest flat surface by way of welcome. ‘Well? Out with it!’"
    },
    {
      "id": "address.again.jovial",
      "when": {
        "moment": "again",
        "manner": "jovial"
      },
      "text": "‘Back for more of my wisdom,’ [say|says] {actor}. ‘Can’t say I blame you.’"
    },
    {
      "id": "address.again.jovial.3",
      "when": {
        "moment": "again",
        "manner": "jovial"
      },
      "text": "‘The very one!’ [say|says] {actor}. ‘I was just telling someone about you. Not all of it true.’"
    },
    {
      "id": "address.first.compassionate",
      "when": {
        "moment": "first",
        "manner": "compassionate"
      },
      "text": "{Actor} takes in the state of you: the road dust, the tiredness. ‘You’ve come a way. What do you need?’"
    },
    {
      "id": "address.first.compassionate.3",
      "when": {
        "moment": "first",
        "manner": "compassionate"
      },
      "text": "‘Sit down a moment,’ [say|says] {actor}. ‘Whatever it is, it will keep that long.’"
    },
    {
      "id": "address.first.compassionate.4",
      "when": {
        "moment": "first",
        "manner": "compassionate"
      },
      "text": "{Actor} looks at your face, and then at your boots, and [speak|speaks] gently. ‘What is it you need?’"
    },
    {
      "id": "address.again.compassionate",
      "when": {
        "moment": "again",
        "manner": "compassionate"
      },
      "text": "‘How are you getting on?’ [ask|asks] {actor}, and seems to want to know."
    },
    {
      "id": "address.again.compassionate.3",
      "when": {
        "moment": "again",
        "manner": "compassionate"
      },
      "text": "‘You came back,’ [say|says] {actor}, glad of it. ‘Is it any better?’"
    },
    {
      "id": "address.first.proud",
      "when": {
        "moment": "first",
        "manner": "proud"
      },
      "text": "{Actor} lets you speak first, as is plainly {their} due."
    },
    {
      "id": "address.first.proud.2",
      "when": {
        "moment": "first",
        "manner": "proud"
      },
      "text": "‘I don’t know you,’ [say|says] {actor}, and waits to be told why {they} should."
    },
    {
      "id": "address.first.proud.4",
      "when": {
        "moment": "first",
        "manner": "proud"
      },
      "text": "{Actor} finishes what {they} [were|was] saying to someone else first."
    },
    {
      "id": "address.first.proud.5",
      "when": {
        "moment": "first",
        "manner": "proud"
      },
      "text": "{Actor} looks at you as if deciding whether you are worth a whole sentence."
    },
    {
      "id": "address.again.proud",
      "when": {
        "moment": "again",
        "manner": "proud"
      },
      "text": "{Actor} acknowledges you with the smallest movement of the chin."
    },
    {
      "id": "address.again.proud.3",
      "when": {
        "moment": "again",
        "manner": "proud"
      },
      "text": "‘You again,’ [say|says] {actor}, as if granting it."
    },
    {
      "id": "address.first.acerbic",
      "when": {
        "moment": "first",
        "manner": "acerbic"
      },
      "text": "‘Lost?’ [say|says] {actor}. ‘People usually are, when they come over to me.’"
    },
    {
      "id": "address.first.acerbic.2",
      "when": {
        "moment": "first",
        "manner": "acerbic"
      },
      "text": "{Actor} looks you up and down. ‘Whatever it is, the answer’s probably no. Go on.’"
    },
    {
      "id": "address.first.acerbic.4",
      "when": {
        "moment": "first",
        "manner": "acerbic"
      },
      "text": "‘Let me guess,’ [say|says] {actor}. ‘You want something.’"
    },
    {
      "id": "address.first.acerbic.5",
      "when": {
        "moment": "first",
        "manner": "acerbic"
      },
      "text": "{Actor} sighs before you have said a word. ‘Go on, then.’"
    },
    {
      "id": "address.again.acerbic",
      "when": {
        "moment": "again",
        "manner": "acerbic"
      },
      "text": "‘Oh, it’s you,’ [say|says] {actor}. ‘I wondered when you’d be back to bother me.’"
    },
    {
      "id": "address.again.acerbic.3",
      "when": {
        "moment": "again",
        "manner": "acerbic"
      },
      "text": "‘Still here,’ [say|says] {actor}. ‘I suppose that’s something.’"
    },
    {
      "id": "address.kin.first",
      "when": {
        "bond": "kin",
        "moment": "first"
      },
      "text": "{Actor} looks at you as if counting the years you have been away, and then just holds on to you a moment."
    },
    {
      "id": "address.kin.first.2",
      "when": {
        "bond": "kin",
        "moment": "first"
      },
      "text": "‘There you are,’ [say|says] {actor}, as if you had stepped out an hour ago; only the voice gives it away."
    },
    {
      "id": "address.kin.first.3",
      "when": {
        "bond": "kin",
        "moment": "first"
      },
      "text": "{Actor} [get|gets] up so fast the stool goes over, and then [stand|stands] there, not sure what to do with {their} hands."
    },
    {
      "id": "address.kin.first.4",
      "when": {
        "bond": "kin",
        "moment": "first"
      },
      "text": "‘You came,’ [say|says] {actor}. ‘I said you would. Nobody believed me.’"
    },
    {
      "id": "address.kin.again",
      "when": {
        "bond": "kin",
        "moment": "again"
      },
      "text": "‘What is it?’ [say|says] {actor}, as family say it: not unkindly, and not getting up."
    },
    {
      "id": "address.kin.again.2",
      "when": {
        "bond": "kin",
        "moment": "again"
      },
      "text": "{Actor} makes room for you without being asked."
    },
    {
      "id": "address.expected.first",
      "when": {
        "bond": "expected",
        "moment": "first"
      },
      "text": "{Actor} takes in the road on your boots, and that you have come straight to {them}, and waits to hear what you have brought."
    },
    {
      "id": "address.expected.first.2",
      "when": {
        "bond": "expected",
        "moment": "first"
      },
      "text": "‘You’ve come a long way to find somebody,’ [say|says] {actor}. ‘Is it me?’"
    },
    {
      "id": "address.creditor.first",
      "when": {
        "bond": "creditor",
        "moment": "first"
      },
      "text": "{Actor} looks at your hands before your face, to see whether there is anything in them."
    },
    {
      "id": "address.creditor.again",
      "when": {
        "bond": "creditor",
        "moment": "again"
      },
      "text": "‘Well?’ [say|says] {actor}, and looks at your purse rather than at you."
    },
    {
      "id": "address.friend.first",
      "when": {
        "bond": "friend",
        "moment": "first"
      },
      "text": "{Actor} knows you before you are close, and comes to meet you. ‘I wondered if you’d come this way.’"
    },
    {
      "id": "address.friend.again",
      "when": {
        "bond": "friend",
        "moment": "again"
      },
      "text": "‘Sit down a minute,’ [say|says] {actor}. ‘You make me tired, standing.’"
    },
    {
      "id": "address.neighbour.first",
      "when": {
        "bond": "neighbour",
        "moment": "first"
      },
      "text": "{Actor} looks twice, and then a third time. ‘Well. Look who it is.’"
    },
    {
      "id": "address.neighbour.first.2",
      "when": {
        "bond": "neighbour",
        "moment": "first"
      },
      "text": "‘You’re back, then,’ [say|says] {actor}, as if you had been gone a week and not three years."
    },
    {
      "id": "address.neighbour.again",
      "when": {
        "bond": "neighbour",
        "moment": "again"
      },
      "text": "{Actor} nods to you the way the place nods to its own."
    },
    {
      "id": "address.fellow.again",
      "when": {
        "bond": "fellow",
        "moment": "again"
      },
      "text": "{Actor} falls into step beside you. ‘What is it?’"
    },
    {
      "id": "address.fellow.again.2",
      "when": {
        "bond": "fellow",
        "moment": "again"
      },
      "text": "‘Thinking something?’ [say|says] {actor}. ‘You’ve got that look.’"
    },
    {
      "id": "address.wary.first.1",
      "when": {
        "moment": "first",
        "temper": "wary",
        "kind": "person"
      },
      "text": "{Actor} [draw|draws] back from you and [watch|watches], weapons low but ready. Nobody speaks first."
    },
    {
      "id": "address.wary.first.2",
      "when": {
        "moment": "first",
        "temper": "wary",
        "kind": "person"
      },
      "text": "{Actor} [go|goes] still when you come. There is a mutter, and an answer, and then {they} [wait|waits] to see what you will do."
    },
    {
      "id": "address.wary.again.1",
      "when": {
        "moment": "again",
        "temper": "wary",
        "kind": "person"
      },
      "text": "{Actor} [know|knows] you now, and [keep|keeps] the same distance as before."
