    {
      "id": "address.troubled.first.1",
      "when": {
        "moment": "first",
        "mood": "troubled",
        "kind": "person"
      },
      "text": "{Actor} [look|looks] round at you as if from a long way off. ‘Yes? Forgive me. What is it?’"
    },
    {
      "id": "address.troubled.first.2",
      "when": {
        "moment": "first",
        "mood": "troubled",
        "kind": "person"
      },
      "text": "‘Not now—’ [begin|begins] {actor}, and then [see|sees] you properly. ‘No. I’m sorry. What do you want?’"
    },
    {
      "id": "address.troubled.again.1",
